INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 1, 1, 'Pradžioje Dievas sutvėrė dangų ir žemę.'),
  (@b1, 1, 2, 'Ir žemė buvo beformė ir tuščia; ir tamsa buvo virš gelmių paviršiaus. Ir Dievo Dvasia judėjo virš vandenų paviršiaus.'),
  (@b1, 1, 3, 'Ir Dievas tarė: „Tebūna šviesa“; ir buvo šviesa.'),
  (@b1, 1, 4, 'Ir Dievas matė šviesą, kad ji buvo gera; ir Dievas atskyrė šviesą nuo tamsos.'),
  (@b1, 1, 5, 'Ir Dievas pavadino šviesą diena, o tamsą jis pavadino naktimi. Ir vakaras ir rytas buvo pirmoji diena.'),
  (@b1, 1, 6, 'Ir Dievas tarė: „Tebūna tvirtuma viduryje vandenų, ir ji teatskiria vandenis nuo vandenų“.'),
  (@b1, 1, 7, 'Ir Dievas padarė tvirtumą ir atskyrė vandenis, kurie buvo po tvirtuma, nuo vandenų, kurie buvo virš tvirtumos; ir taip buvo.'),
  (@b1, 1, 8, 'Ir Dievas pavadino tvirtumą dangumi. Ir vakaras ir rytas buvo antroji diena.'),
  (@b1, 1, 9, 'Ir Dievas tarė: „Tesusirenka vandenys, kurie yra po dangumi, į vieną vietą ir tepasirodo sausuma“; ir taip buvo.'),
  (@b1, 1, 10, 'Ir Dievas pavadino sausumą žeme; o vandenų samplūdį jis pavadino jūromis; ir Dievas matė, kad tai buvo gerai.'),
  (@b1, 1, 11, 'Ir Dievas tarė: „Tegul žemė duoda žolę, žoles, duodančias sėklą, ir vaismedžius, duodančius vaisių pagal savo rūšį, kurių sėkla yra juose pačiuose, ant žemės“; ir taip buvo.'),
  (@b1, 1, 12, 'Ir žemė davė žolę ir žoles, duodančias sėklą pagal savo rūšį, ir medžius, duodančius vaisių pagal savo rūšį, kurių sėkla buvo juose pačiuose; ir Dievas matė, kad tai buvo gerai.'),
  (@b1, 1, 13, 'Ir vakaras ir rytas buvo trečioji diena.'),
  (@b1, 1, 14, 'Ir Dievas tarė: „Tebūna šviesos dangaus tvirtumoje dienai nuo nakties atskirti; ir tebūna jos už ženklus ir už laikotarpius, ir už dienas ir metus;'),
  (@b1, 1, 15, 'ir jos tebūna už šviesas dangaus tvirtumoje, kad apšviestų žemę“; ir taip buvo.'),
  (@b1, 1, 16, 'Ir Dievas padarė dvi dideles šviesas: didesniąją šviesą dienai valdyti ir mažesniąją šviesą nakčiai valdyti; taip pat jis padarė žvaigždes.'),
  (@b1, 1, 17, 'Ir Dievas sudėliojo jas dangaus tvirtumoje, kad apšviestų žemę'),
  (@b1, 1, 18, 'ir valdytų dieną bei naktį, ir atskirtų šviesą nuo tamsos; ir Dievas matė, kad tai buvo gerai.'),
  (@b1, 1, 19, 'Ir vakaras ir rytas buvo ketvirtoji diena.'),
  (@b1, 1, 20, 'Ir Dievas tarė: „Tegul vandenys gausiai duoda judančių sutvėrimų, turinčių gyvybę, ir skrajūnų, kad skraidytų virš žemės, atviroje dangaus tvirtumoje“.'),
  (@b1, 1, 21, 'Ir Dievas sutvėrė didelius banginius ir kiekvieną judantį gyvą sutvėrimą, kurių gausiai vandenys davė pagal jų rūšį, ir kiekvieną sparnuotą skrajūną pagal jų rūšį; ir Dievas matė, kad tai buvo gerai.'),
  (@b1, 1, 22, 'Ir Dievas juos palaimino, tardamas: „Būkite vaisingi ir dauginkitės, ir pripildykite vandenis jūrose, ir skrajūnai tesidaugina žemėje“.'),
  (@b1, 1, 23, 'Ir vakaras ir rytas buvo penktoji diena.'),
  (@b1, 1, 24, 'Ir Dievas tarė: „Tegul žemė duoda gyvų sutvėrimų pagal jų rūšis, galvijų, roplių ir žemės žvėrių pagal jų rūšis“; ir taip buvo.'),
  (@b1, 1, 25, 'Ir Dievas padarė žemės žvėris pagal jų rūšis ir galvijus pagal jų rūšis, ir kiekvieną ropojantį ant žemės pagal jų rūšį; ir Dievas matė, kad tai buvo gerai.'),
  (@b1, 1, 26, 'Ir Dievas tarė: „Padarykime žmogų pagal mūsų atvaizdą, pagal mūsų panašumą; ir teviešpatauja jie jūros žuvims, oro skrajūnams, galvijams ir visai žemei, ir kiekvienam ropliui, kuris ropoja ant žemės“.'),
  (@b1, 1, 27, 'Taigi Dievas sutvėrė žmogų pagal savo atvaizdą, pagal Dievo atvaizdą jis sutvėrė jį; vyriškos lyties ir moteriškos lyties jis juos sutvėrė.'),
  (@b1, 1, 28, 'Ir Dievas juos palaimino, ir Dievas jiems tarė: „Būkite vaisingi ir dauginkitės, pripildykite žemę ir užvaldykite ją; ir viešpataukite jūros žuvims, oro skrajūnams ir kiekvienam gyvam padarui, kuris juda ant žemės“.'),
  (@b1, 1, 29, 'Ir Dievas tarė: „Štai aš jums daviau visas žoles, duodančias sėklą, kurios yra ant visos žemės paviršiaus, ir visus medžius, kuriuose yra medžio vaisius, duodantis sėklą; jums tai bus maistas.'),
  (@b1, 1, 30, 'Ir visiems žemės žvėrims, visiems oro skrajūnams ir visiems padarams, kurie kruta ant žemės, kuriuose yra gyvybė, daviau visas žalias žoles maistui“; ir taip buvo.'),
  (@b1, 1, 31, 'Ir Dievas matė viską, ką buvo padaręs, ir štai, tai buvo labai gerai. Ir vakaras ir rytas buvo šeštoji diena.'),
  (@b1, 2, 1, 'Taip buvo užbaigti dangūs ir žemė, ir visa jų kariuomenė.'),
  (@b1, 2, 2, 'Ir Dievas septintąją dieną užbaigė savo darbą, kurį jis padarė; ir ilsėjosi septintąją dieną nuo viso savo darbo, kurį jis padarė.'),
  (@b1, 2, 3, 'Ir Dievas palaimino septintąją dieną ir ją pašventė; nes joje jis ilsėjosi nuo viso savo darbo, kurį Dievas sutvėrė ir padarė.'),
  (@b1, 2, 4, 'Ši yra dangų ir žemės kilmė, kai jie buvo sutverti tą dieną, kurią VIEŠPATS Dievas padarė žemę ir dangus,'),
  (@b1, 2, 5, 'ir visus lauko augalus, kol jų dar nebuvo žemėje, ir visas lauko žoles, kol jos dar neaugo; nes VIEŠPATS Dievas nedavė lyti žemėje, ir nebuvo žmogaus žemei įdirbti.'),
  (@b1, 2, 6, 'Bet migla kilo nuo žemės ir drėkino visą dirvos paviršių.'),
  (@b1, 2, 7, 'Ir VIEŠPATS Dievas suformavo žmogų iš dirvos dulkių ir įkvėpė į jo šnerves gyvybės kvapą; ir žmogus tapo gyva siela.'),
  (@b1, 2, 8, 'Ir VIEŠPATS Dievas pasodino sodą Edene rytuose; ir ten jis pastatė žmogų, kurį buvo suformavęs.'),
  (@b1, 2, 9, 'Ir VIEŠPATS Dievas padarė, kad iš dirvos išaugo visokie medžiai, malonūs pažiūrėti ir geri maistui; taip pat gyvybės medis sodo viduryje ir medis pažinimo gero bei pikto.'),
  (@b1, 2, 10, 'Ir upė tekėjo iš Edeno drėkinti sodą; o nuo ten ji persiskyrė ir tapo keturiomis pagrindinėmis.'),
  (@b1, 2, 11, 'Pirmosios vardas Pišonas; tai yra ta, kuri teka aplink visą Havilos šalį, kur yra aukso;'),
  (@b1, 2, 12, 'o tos šalies auksas yra geras; ten yra bdelijo ir onikso akmens.'),
  (@b1, 2, 13, 'Ir antrosios upės vardas Gihonas; ji yra ta, kuri teka aplink visą Etiopijos šalį.'),
  (@b1, 2, 14, 'Ir trečiosios upės vardas Hidekelis; tai yra ta, kuri teka į Asirijos rytus. Ir ketvirtoji upė yra Eufratas.'),
  (@b1, 2, 15, 'Ir VIEŠPATS Dievas paėmė žmogų ir pastatė jį Edeno sode, kad jį įdirbtų ir saugotų.'),
  (@b1, 2, 16, 'Ir VIEŠPATS Dievas įsakė žmogui, tardamas: „Nuo kiekvieno sodo medžio gali valgyti laisvai;'),
  (@b1, 2, 17, 'bet nuo medžio pažinimo gero ir pikto, nevalgyk nuo jo; nes tą dieną, kai nuo jo valgysi, tikrai mirsi“.'),
  (@b1, 2, 18, 'Ir VIEŠPATS Dievas tarė: „Negerai žmogui būti vienam; padarysiu jam padėjėją – jam tinkamą“.'),
  (@b1, 2, 19, 'Ir VIEŠPATS Dievas iš dirvos suformavo visus lauko žvėris ir visus oro skrajūnus; ir atvedė juos Adomui, kad matytų, kuo jis juos pavadins; ir kuo Adomas pavadino kiekvieną gyvą sutvėrimą, tas ir buvo jo vardas.'),
  (@b1, 2, 20, 'Ir Adomas davė vardus visiems galvijams ir oro skrajūnams, ir visiems lauko žvėrims; tačiau Adomui neatsirado padėjėjo – jam tinkamo.'),
  (@b1, 2, 21, 'Ir VIEŠPATS Dievas padarė, kad gilus miegas nupuolė ant Adomo, ir jis užmigo; ir jis išėmė vieną jo šonkaulių, ir to vietą uždarė kūnu.'),
  (@b1, 2, 22, 'Ir šonkaulį, kurį VIEŠPATS Dievas buvo išėmęs iš žmogaus, padarė jis moterimi ir atvedė ją pas žmogų.'),
  (@b1, 2, 23, 'Ir Adomas tarė: „Dabar tai yra kaulas mano kaulų ir kūnas mano kūno; ji bus vadinama moterimi, nes iš vyro ji buvo paimta“.'),
  (@b1, 2, 24, 'Todėl žmogus savo tėvą bei savo motiną paliks ir prie savo žmonos prilips; ir jie bus vienas kūnas.'),
  (@b1, 2, 25, 'Jie abu – žmogus ir jo žmona – buvo nuogi ir nesigėdijo.'),
  (@b1, 3, 1, 'Na, o gyvatė buvo gudresnė už visus lauko žvėris, kuriuos VIEŠPATS Dievas buvo padaręs. Ir ji tarė moteriai: „Taip, ar Dievas pasakė: ‘Nevalgykite nuo visų sodo medžių’?“'),
  (@b1, 3, 2, 'Ir moteris tarė gyvatei: „Mes galime valgyti sodo medžių vaisių;'),
  (@b1, 3, 3, 'bet apie vaisių medžio, kuris yra sodo viduryje, Dievas tarė: ‘Nevalgykite nuo jo nei nelieskite jo, kad nemirtumėte’“.'),
  (@b1, 3, 4, 'Ir gyvatė tarė moteriai: „Jūs tikrai nemirsite;'),
  (@b1, 3, 5, 'nes Dievas žino, kad tą dieną, kai valgysite nuo jo, atsivers jūsų akys, ir jūs būsite kaip dievai, pažindami gera ir pikta“.'),
  (@b1, 3, 6, 'Ir kai moteris pamatė, kad medis buvo geras maistui ir kad jis malonus akims, ir kad medis geistinas, idant padarytų išmintingu, ji ėmė jo vaisiaus ir valgė, ir taip pat davė savo vyrui, esančiam su ja; ir jis valgė.'),
  (@b1, 3, 7, 'Ir atsivėrė jų abiejų akys, ir jie pažino esą nuogi; ir jie susiuvo figmedžio lapus ir pasidarė prijuostes.'),
  (@b1, 3, 8, 'Ir jie išgirdo VIEŠPATIES Dievo, vaikštančio sode, dienos vėsumoje, balsą; ir Adomas ir jo žmona pasislėpė nuo VIEŠPATIES Dievo akivaizdos tarp sodo medžių.'),
  (@b1, 3, 9, 'Ir VIEŠPATS Dievas pašaukė Adomą ir jam tarė: „Kur tu?“'),
  (@b1, 3, 10, 'Ir jis tarė: „Išgirdau tavo balsą sode ir išsigandau, kadangi aš nuogas; ir pasislėpiau“.'),
  (@b1, 3, 11, 'Ir jis tarė: „Kas tau pasakė, kad tu nuogas? Ar valgei nuo medžio, nuo kurio tau įsakiau nevalgyti?“'),
  (@b1, 3, 12, 'Ir žmogus tarė: „Moteris, kurią davei, kad būtų su manimi, ji davė man nuo to medžio, ir aš valgiau“.'),
  (@b1, 3, 13, 'Ir VIEŠPATS Dievas tarė moteriai: „Kas tai, ką tu padarei?“ Ir moteris tarė: „Gyvatė mane apgavo, ir aš valgiau“.'),
  (@b1, 3, 14, 'Ir VIEŠPATS Dievas tarė gyvatei: „Kadangi tai padarei, tu prakeikta labiau už visus galvijus ir už visus lauko žvėris; savo pilvu vaikščiosi ir ėsi dulkes per visas savo gyvenimo dienas;'),
  (@b1, 3, 15, 'ir aš padėsiu priešiškumą tarp tavęs bei moters ir tarp tavo sėklos bei jos sėklos; ta sutrins tavo galvą, o tu sutrinsi jos kulnį“.'),
  (@b1, 3, 16, 'Moteriai jis tarė: „Aš didžiai padauginsiu tavo sielvartą ir tavo nėštumus; sielvarte tu gimdysi vaikus; ir tavo noras bus savo vyrui, o jis tave valdys“.'),
  (@b1, 3, 17, 'Ir Adomui jis tarė: „Kadangi paklausei savo žmonos balso ir valgei nuo medžio, apie kurį tau įsakiau, sakydamas: ‘Nevalgyk nuo jo’; prakeikta dirva dėl tavęs; sielvarte maitinsies iš jos per visas savo gyvenimo dienas;'),
  (@b1, 3, 18, 'taip pat erškėčius ir usnis ji tau duos; ir tu valgysi lauko žoles;'),
  (@b1, 3, 19, 'savo veido prakaite valgysi duoną, kol sugrįši į dirvą; nes iš jos buvai paimtas; nes tu dulkė, ir į dulkę sugrįši“.'),
  (@b1, 3, 20, 'Ir Adomas pavadino savo žmoną vardu Ieva; nes ji buvo visų gyvųjų motina.'),
  (@b1, 3, 21, 'Taip pat VIEŠPATS Dievas Adomui ir jo žmonai padarė apsiaustus iš odų ir juos aprengė.'),
  (@b1, 3, 22, 'Ir VIEŠPATS Dievas tarė: „Štai žmogus tapo kaip vienas iš mūsų, kad pažintų gera ir pikta; ir dabar, kad jis neištiestų savo rankos ir neskintų nuo gyvybės medžio, ir nevalgytų, ir negyventų per amžius“;'),
  (@b1, 3, 23, 'dėl to VIEŠPATS Dievas išsiuntė jį iš Edeno sodo dirbti dirvą, iš kurios jis buvo paimtas.'),
  (@b1, 3, 24, 'Taigi jis išvarė žmogų; ir jis Edeno sodo rytuose pastatė kerubus ir liepsnojantį kalaviją, kuris sukiojosi į visas puses, kad saugotų gyvybės medžio kelią.'),
  (@b1, 4, 1, 'Ir Adomas pažino savo žmoną Ievą; ir ji pastojo ir pagimdė Kainą, ir tarė: „Gavau vyrą nuo VIEŠPATIES“.'),
  (@b1, 4, 2, 'Ir ji vėl pagimdė jo brolį Abelį. Ir Abelis buvo avių laikytojas, bet Kainas buvo žemdirbys.'),
  (@b1, 4, 3, 'Ir laikui einant įvyko, kad Kainas atnešė iš dirvos vaisiaus atnašą VIEŠPAČIUI.'),
  (@b1, 4, 4, 'Ir Abelis, jis taip pat atnešė iš savo kaimenės pirmagimių ir iš jų taukų. Ir VIEŠPATS atsižvelgė į Abelį ir į jo atnašą;'),
  (@b1, 4, 5, 'tačiau į Kainą ir į jo atnašą jis neatsižvelgė. Ir Kainas labai užsirūstino, ir jo veidas paniuro.'),
  (@b1, 4, 6, 'Ir VIEŠPATS tarė Kainui: „Kodėl tu užsirūstinęs ir kodėl tavo veidas paniuręs?'),
  (@b1, 4, 7, 'Jei darai gerai, argi nebūsi priimtinas? O jei darai negerai, nuodėmė tyko prie durų. Ir tau bus jos noras, bet tu ją valdyk“.'),
  (@b1, 4, 8, 'Ir Kainas kalbėjo su savo broliu Abeliu; ir įvyko, kai jie buvo ant lauko, Kainas pakilo prieš savo brolį Abelį ir jį užmušė.'),
  (@b1, 4, 9, 'Ir VIEŠPATS tarė Kainui: „Kur tavo brolis Abelis?“ Ir jis tarė: „Nežinau; ar aš savo brolio sargas?“'),
  (@b1, 4, 10, 'Ir jis tarė: „Ką padarei? Tavo brolio kraujo balsas šaukiasi manęs iš dirvos.'),
  (@b1, 4, 11, 'Ir dabar tu prakeiktas nuo žemės, kuri atvėrė savo burną priimti tavo brolio kraują iš tavo rankos;'),
  (@b1, 4, 12, 'kai dirbsi dirvą, ji nuo šiol tau nebeduos savo stiprybės; tu būsi bėglys ir bastūnas žemėje“.'),
  (@b1, 4, 13, 'Ir Kainas tarė VIEŠPAČIUI: „Mano bausmė didesnė nei galiu pakelti.'),
  (@b1, 4, 14, 'Štai tu šią dieną mane išvarei nuo žemės paviršiaus; ir aš būsiu paslėptas nuo tavo veido; ir būsiu bėglys ir bastūnas žemėje; ir įvyks, kad kiekvienas, kas mane sutiks, mane užmuš“.'),
  (@b1, 4, 15, 'Ir VIEŠPATS jam tarė: „Todėl kas užmuša Kainą, tam septyneriopai bus atkeršyta“. Ir VIEŠPATS uždėjo Kainui ženklą, kad kas jį užtikęs jo nenužudytų.'),
  (@b1, 4, 16, 'Ir Kainas nuėjo nuo VIEŠPATIES akivaizdos ir apsigyveno Nodo šalyje, Edeno rytuose.'),
  (@b1, 4, 17, 'Ir Kainas pažino savo žmoną; ir ji pastojo ir pagimdė Henochą; ir jis pastatė miestą, ir pavadino miestą savo sūnaus vardu – Henochas.'),
  (@b1, 4, 18, 'O Henochui gimė Iradas; o Iradas pagimdė Mehujaelį; o Mehujaelis pagimdė Metušaelį; o Metušaelis pagimdė Lamechą.'),
  (@b1, 4, 19, 'O Lamechas ėmė sau dvi žmonas; vienos vardas buvo Ada, o kitos vardas Cila.'),
  (@b1, 4, 20, 'O Ada pagimdė Jabalą; jis buvo tėvas tokių, kurie gyvena palapinėse, ir tokių, kurie turi galvijų.'),
  (@b1, 4, 21, 'O jo brolio vardas buvo Jubalas; jis buvo tėvas visų tokių, kurie valdo arfą ir vargonus.'),
  (@b1, 4, 22, 'O Cila, ji taip pat pagimdė Tubal-Kainą, visų žalvario ir geležies kalvių mokytoją; ir Tubal-Kaino sesuo buvo Naama.'),
  (@b1, 4, 23, 'Ir Lamechas tarė savo žmonoms: „Ada ir Cila, išgirskite mano balsą; jūs, Lamecho žmonos, klausykitės mano kalbos; nes aš užmušiau vyrą už mano žaizdą, jaunuolį už mano sužalojimą.'),
  (@b1, 4, 24, 'Jei už Kainą bus atkeršyta septyneriopai, tai tikrai už Lamechą – septyniasdešimt septynis kartus“.'),
  (@b1, 4, 25, 'Ir Adomas vėl pažino savo žmoną; ir ji pagimdė sūnų ir pavadino jį vardu Setas; „Nes Dievas, – ji tarė, – man paskyrė kitą sėklą vietoje Abelio, kurį Kainas užmušė“.'),
  (@b1, 4, 26, 'Ir Setui, jam irgi gimė sūnus; ir jis pavadino jį vardu Enas; tuomet žmonės pradėjo šauktis VIEŠPATIES vardo.'),
  (@b1, 5, 1, 'Šita yra Adomo genealogijos knyga. Tą dieną, kai Dievas sutvėrė žmogų, jis padarė jį panašų į Dievą;'),
  (@b1, 5, 2, 'vyriškos lyties ir moteriškos lyties sutvėrė jis juos; ir palaimino juos ir pavadino juos vardu Adomas tą dieną, kai jie buvo sutverti.'),
  (@b1, 5, 3, 'Ir Adomas pragyveno šimtą ir trisdešimt metų ir pagimdė sūnų pagal savo panašumą, pagal savo atvaizdą; ir pavadino jį vardu Setas;'),
  (@b1, 5, 4, 'ir Adomo dienų, po to, kai jis pagimdė Setą, buvo aštuoni šimtai metų; ir jis pagimdė sūnų bei dukterų;'),
  (@b1, 5, 5, 'ir visų Adomo dienų, kurias jis gyveno, buvo devyni šimtai trisdešimt metų; ir jis mirė.'),
  (@b1, 5, 6, 'Ir Setas pragyveno šimtą penkeris metus ir pagimdė Eną;'),
  (@b1, 5, 7, 'ir Setas, po to, kai pagimdė Eną, gyveno aštuonis šimtus septynerius metus ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 8, 'ir visų Seto dienų buvo devyni šimtai dvylika metų; ir jis mirė.'),
  (@b1, 5, 9, 'Ir Enas pragyveno devyniasdešimt metų ir pagimdė Kainaną;'),
  (@b1, 5, 10, 'ir Enas, po to, kai pagimdė Kainaną, gyveno aštuonis šimtus penkiolika metų ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 11, 'ir visų Eno dienų buvo devyni šimtai penkeri metai; ir jis mirė.'),
  (@b1, 5, 12, 'Ir Kainanas pragyveno septyniasdešimt metų ir pagimdė Malaleelį;'),
  (@b1, 5, 13, 'ir Kainanas, po to, kai pagimdė Malaleelį, gyveno aštuonis šimtus keturiasdešimt metų ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 14, 'ir visų Kainano dienų buvo devyni šimtai dešimt metų; ir jis mirė.'),
  (@b1, 5, 15, 'Ir Malaleelis pragyveno šešiasdešimt penkis metus ir pagimdė Jaredą;'),
  (@b1, 5, 16, 'ir Malaleelis, po to, kai pagimdė Jaredą, gyveno aštuonis šimtus trisdešimt metų ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 17, 'ir visų Malaleelio dienų buvo aštuoni šimtai devyniasdešimt penkeri metai; ir jis mirė.'),
  (@b1, 5, 18, 'Ir Jaredas pragyveno šimtą šešiasdešimt dvejus metus ir pagimdė Henochą;'),
  (@b1, 5, 19, 'ir Jaredas, po to, kai pagimdė Henochą, gyveno aštuonis šimtus metų ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 20, 'ir visų Jaredo dienų buvo devyni šimtai šešiasdešimt dveji metai; ir jis mirė.'),
  (@b1, 5, 21, 'Ir Henochas pragyveno šešiasdešimt penkeris metus ir pagimdė Matūzalį;'),
  (@b1, 5, 22, 'ir Henochas, po to, kai pagimdė Matūzalį, vaikščiojo su Dievu tris šimtus metų ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 23, 'ir visų Henocho dienų buvo trys šimtai šešiasdešimt penkeri metai;'),
  (@b1, 5, 24, 'ir Henochas vaikščiojo su Dievu; ir jo nebebuvo; nes Dievas jį paėmė.'),
  (@b1, 5, 25, 'Ir Matūzalis pragyveno šimtą aštuoniasdešimt septynerius metus ir pagimdė Lamechą;'),
  (@b1, 5, 26, 'ir Matūzalis, po to, kai pagimdė Lamechą, gyveno septynis šimtus aštuoniasdešimt dvejus metus ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 27, 'ir visų Matūzalio dienų buvo devyni šimtai šešiasdešimt devyneri metai; ir jis mirė.'),
  (@b1, 5, 28, 'Ir Lamechas pragyveno šimtą aštuoniasdešimt dvejus metus ir pagimdė sūnų;'),
  (@b1, 5, 29, 'ir jis pavadino jį vardu Nojus, sakydamas: „Šitas mus paguos dėl mūsų darbo ir dėl mūsų rankų triūso, dėl dirvos, kurią VIEŠPATS prakeikė“.'),
  (@b1, 5, 30, 'Ir Lamechas, po to, kai pagimdė Nojų, gyveno penkis šimtus devyniasdešimt penkerius metus ir pagimdė sūnų bei dukterų;'),
  (@b1, 5, 31, 'ir visų Lamecho dienų buvo septyni šimtai septyniasdešimt septyneri metai; ir jis mirė.'),
  (@b1, 5, 32, 'Ir Nojus buvo penkių šimtų metų; ir Nojus pagimdė Šemą, Chamą ir Jafetą.'),
  (@b1, 6, 1, 'Ir įvyko, kai žmonių pradėjo daugėti ant žemės paviršiaus ir jiems gimė dukterų,'),
  (@b1, 6, 2, 'Dievo sūnūs matė žmonių dukteris, kad jos gražios; ir jie ėmė jas į žmonas iš visų, kurias jie išsirinko.'),
  (@b1, 6, 3, 'Ir VIEŠPATS tarė: „Mano Dvasia nesivaidys su žmogumi amžinai, nes jis yra ir kūnas; jo dienų dar bus šimtas dvidešimt metų“.'),
  (@b1, 6, 4, 'Anomis dienomis žemėje buvo milžinų; taip pat po to, kai Dievo sūnūs įėjo pas žmonių dukteris ir jos pagimdė jiems vaikų, tie tapo galiūnais, kurie nuo seno buvo garsūs vyrai.'),
  (@b1, 6, 5, 'Ir DIEVAS matė, kad žmogaus nedorybė žemėje buvo didelė, ir kad kiekvienas jo širdies minčių sumanymas nuolat buvo tik piktas.'),
  (@b1, 6, 6, 'Ir gailėjosi VIEŠPATS, kad jis žemėje padarė žmogų, ir tai sukėlė sielvartą jo širdyje.'),
  (@b1, 6, 7, 'Ir VIEŠPATS tarė: „Išnaikinsiu žmogų, kurį sutvėriau, nuo žemės paviršiaus; tiek žmogų, tiek gyvulį, tiek roplį, tiek oro skrajūną; nes gailiuosi, kad juos padariau“.'),
  (@b1, 6, 8, 'Tačiau Nojus rado malonę VIEŠPATIES akyse.'),
  (@b1, 6, 9, 'Ši yra Nojaus giminė: Nojus buvo teisus žmogus, tobulas savo kartose, ir Nojus vaikščiojo su Dievu.'),
  (@b1, 6, 10, 'Ir Nojus pagimdė tris sūnus: Šemą, Chamą ir Jafetą.'),
  (@b1, 6, 11, 'Taip pat ir žemė Dievo akivaizdoje buvo sugedusi, ir žemė buvo pripildyta smurto.'),
  (@b1, 6, 12, 'Ir Dievas pažiūrėjo į žemę, ir štai ji buvo sugedusi; nes kiekvienas kūnas žemėje sugadino savo kelius.'),
  (@b1, 6, 13, 'Ir Dievas tarė Nojui: „Kiekvieno kūno galas atėjo mano akivaizdon; nes per juos žemė yra pripildyta smurto; ir štai aš sunaikinsiu juos su žeme.'),
  (@b1, 6, 14, 'Pasidaryk arką iš gofero medžio; arkoje padaryk kambarius ir ištepk ją derva iš vidaus ir iš lauko.'),
  (@b1, 6, 15, 'Ir štai pavyzdys, pagal kurį turi ją padaryti: arkos ilgis turi būti trys šimtai uolekčių, jos plotis – penkiasdešimt uolekčių, o jos aukštis – trisdešimt uolekčių.'),
  (@b1, 6, 16, 'Padaryk arkai langą ir užbaik jį per uolektį nuo viršaus; ir arkos duris įstatyk jos šone; padaryk ją su apatiniu, antru ir trečiu aukštu.'),
  (@b1, 6, 17, 'Ir štai aš užleisiu vandenų tvaną ant žemės, išnaikinti po dangumi kiekvieną kūną, kuriame yra gyvybės kvapas; ir visa, kas yra žemėje, mirs.'),
  (@b1, 6, 18, 'Bet su tavimi aš įtvirtinsiu savo sandorą; tu ateisi į arką, tu ir tavo sūnūs, ir tavo žmona, ir tavo sūnų žmonos su tavimi.'),
  (@b1, 6, 19, 'Ir iš kiekvieno gyvo padaro iš visokio kūno, įvesk į arką po du iš kiekvienos rūšies, kad išlaikytum juos gyvus su savimi; jie turi būti patinas ir patelė.'),
  (@b1, 6, 20, 'Iš skrajūnų pagal jų rūšis ir iš galvijų pagal jų rūšis, iš visų žemės roplių pagal jų rūšis, ateis pas tave po du iš kiekvienos rūšies, kad išliktų gyvi.'),
  (@b1, 6, 21, 'Ir pasiimk visokio valgomo maisto ir surink tai pas save; ir tai bus maistas tau ir jiems“.'),
  (@b1, 6, 22, 'Nojus taip padarė; pagal visa, ką Dievas jam įsakė, taip jis padarė.'),
  (@b1, 7, 1, 'Ir VIEŠPATS tarė Nojui: „Ateik į arką tu ir visi tavo namai; nes mačiau tave teisų mano akivaizdoje šioje kartoje.'),
  (@b1, 7, 2, 'Pasiimk iš kiekvieno švaraus gyvulio po septynetą, patiną ir jo patelę; ir iš gyvulių kurie yra nešvarūs, po du, patiną ir jo patelę.'),
  (@b1, 7, 3, 'Taip pat iš oro skrajūnų po septynetą, patiną ir patelę; kad išlaikytų sėklą gyvą ant visos žemės paviršiaus.'),
  (@b1, 7, 4, 'Nes dar septynios dienos, ir padarysiu, kad lis ant žemės keturiasdešimt dienų ir keturiasdešimt naktų; ir išnaikinsiu nuo žemės paviršiaus visa, kas gyva, ką esu padaręs“.'),
  (@b1, 7, 5, 'Ir Nojus padarė pagal visa, ką VIEŠPATS jam įsakė.'),
  (@b1, 7, 6, 'Ir Nojus buvo šešių šimtų metų, kai vandenų tvanas buvo žemėje.'),
  (@b1, 7, 7, 'Ir Nojus ir jo sūnūs, ir jo žmona, ir jo sūnų žmonos su juo įėjo į arką dėl tvano vandenų.'),
  (@b1, 7, 8, 'Iš švarių gyvulių ir iš gyvulių, kurie nešvarūs, ir iš skrajūnų, ir iš kiekvieno padaro, ropojančio žeme,'),
  (@b1, 7, 9, 'poromis įėjo pas Nojų į arką, patinas ir patelė, kaip Dievas buvo įsakęs Nojui.'),
  (@b1, 7, 10, 'Ir įvyko po septynių dienų, kad tvano vandenys buvo žemėje.'),
  (@b1, 7, 11, 'Šeši šimtaisiais Nojaus gyvenimo metais, antrąjį mėnesį, septynioliktąją to mėnesio dieną, tą dieną pratrūko visi didžiųjų gelmių šaltiniai, ir dangaus langai atsidarė.'),
  (@b1, 7, 12, 'Ir lietus buvo žemėje keturiasdešimt dienų ir keturiasdešimt naktų.'),
  (@b1, 7, 13, 'Tą pačią dieną įėjo Nojus ir Nojaus sūnūs: Šemas, Chamas ir Jafetas, ir Nojaus žmona, ir trys jo sūnų žmonos su jais į arką;'),
  (@b1, 7, 14, 'jie ir kiekvienas žvėris pagal savo rūšį, ir visi galvijai pagal jų rūšis, ir kiekvienas roplys, ropojantis žeme, pagal savo rūšį, ir kiekvienas skrajūnas pagal savo rūšį, visi kiekvienos rūšies paukščiai.'),
  (@b1, 7, 15, 'Ir jie įėjo pas Nojų į arką, poromis iš visų kūnų, kuriuose yra gyvybės kvapas.'),
  (@b1, 7, 16, 'Ir tie, kurie įėjo, įėjo patinas ir patelė iš visų kūnų, kaip Dievas jam buvo įsakęs; ir VIEŠPATS pãskui jį užrakino.'),
  (@b1, 7, 17, 'Ir tvanas buvo žemėje keturiasdešimt dienų; ir vandenys daugėjo ir pakėlė arką, ir ji buvo pakelta virš žemės.'),
  (@b1, 7, 18, 'Ir vandenys įsigalėjo ir labai padaugėjo žemėje; ir arka plaukė vandenų paviršiumi.'),
  (@b1, 7, 19, 'Ir vandenys nepaprastai įsigalėjo žemėje; ir visos aukštos kalvos, esančios po visu dangumi, buvo apdengtos.'),
  (@b1, 7, 20, 'Vanduo įsigalėjo penkiolika uolekčių aukščiau; ir kalnai buvo apdengti.'),
  (@b1, 7, 21, 'Ir žuvo visi kūnai, kurie judėjo ant žemės – tiek skrajūnų, tiek galvijų, tiek žvėrių, tiek visų roplių, ropojančių ant žemės, ir visi žmonės;'),
  (@b1, 7, 22, 'visi, kurių šnervėse buvo gyvybės kvapas, iš visų, esančių sausumoje, išmirė.'),
  (@b1, 7, 23, 'Ir visa, kas buvo gyva ant dirvos paviršiaus, buvo sunaikinta – tiek žmogus, tiek galvijas, tiek roplys, tiek dangaus skrajūnas; ir jie buvo išnaikinti nuo žemės; o tik Nojus išliko gyvas ir tie, kurie buvo su juo arkoje.'),
  (@b1, 7, 24, 'Ir vanduo apsėmė žemę šimtą penkiasdešimt dienų.'),
  (@b1, 8, 1, 'Ir Dievas atsiminė Nojų ir kiekvieną gyvą padarą bei visus galvijus, esančius su juo arkoje; ir Dievas padarė, kad vėjas perėjo per žemę, ir vandenys nurimo;'),
  (@b1, 8, 2, 'taip pat ir gelmių šaltiniai bei dangaus langai buvo uždaryti ir buvo sulaikytas lietus iš dangaus;'),
  (@b1, 8, 3, 'ir vandenys nuolat traukėsi atgal nuo žemės; ir pasibaigus šimtui penkiasdešimčiai dienų, vandenys slūgo.'),
  (@b1, 8, 4, 'Ir septintą mėnesį, septynioliktąją to mėnesio dieną, arka ilsėjosi ant Ararato kalnų.'),
  (@b1, 8, 5, 'Ir vandenys nuolat mažėjo iki dešimtojo mėnesio; dešimtąjį mėnesį, to mėnesio pirmąją dieną, buvo matomos kalnų viršūnės.'),
  (@b1, 8, 6, 'Ir įvyko pasibaigus keturiasdešimčiai dienų, kad Nojus atidarė langą arkos, kurią jis buvo padaręs;'),
  (@b1, 8, 7, 'ir jis išsiuntė varną, kuris lakiojo ten ir atgal, kol vandenys nudžiūvo nuo žemės.'),
  (@b1, 8, 8, 'Taip pat jis išsiuntė nuo savęs karvelį, pažiūrėti, ar vandenys nusekę nuo dirvos paviršiaus;'),
  (@b1, 8, 9, 'bet karvelis nerado savo kojų pėdoms poilsio, ir sugrįžo pas jį į arką, nes vandenys buvo ant visos žemės paviršiaus; tada jis ištiesė savo ranką ir jį paėmė, ir įsitraukė pas save į arką.'),
  (@b1, 8, 10, 'Ir jis palaukė dar kitas septynias dienas; ir vėl išsiuntė iš arkos karvelį;'),
  (@b1, 8, 11, 'ir karvelis parlėkė pas jį vakare; ir štai jo burnoje buvo nuskintas alyvmedžio lapas; taip Nojus sužinojo, kad vandenys žemėje buvo nuslūgę.'),
  (@b1, 8, 12, 'Ir jis palaukė dar kitas septynias dienas; ir išsiuntė karvelį; kuris daugiau nebesugrįžo pas jį.'),
  (@b1, 8, 13, 'Ir įvyko šeši šimtai pirmaisiais metais, pirmąjį mėnesį, pirmąją to mėnesio dieną, kad vandenys buvo nudžiūvę žemėje; ir Nojus nuėmė arkos dangtį ir pasižiūrėjo, ir štai dirvos paviršius buvo sausas.'),
  (@b1, 8, 14, 'Ir antrąjį mėnesį, dvidešimt septintąją to mėnesio dieną, žemė buvo išdžiūvusi.'),
  (@b1, 8, 15, 'Ir Dievas kalbėjo Nojui, sakydamas:'),
  (@b1, 8, 16, '„Išeik iš arkos tu ir tavo žmona, ir tavo sūnūs, ir tavo sūnų žmonos su tavimi.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 8, 17, 'Išvesk su savimi visus gyvus padarus, esančius su tavimi, iš visų kūnų, tiek iš skrajūnų, tiek iš galvijų, tiek iš visų roplių, ropojančių žeme; kad jie gausiai veistųsi žemėje ir būtų vaisingi, ir daugintųsi žemėje“.'),
  (@b1, 8, 18, 'Ir Nojus išėjo ir jo sūnūs, ir jo žmona, ir jo sūnų žmonos su juo;'),
  (@b1, 8, 19, 'visi gyvuliai, visi ropliai ir visi skrajūnai, ir visa, kas ropoja ant žemės, pagal jų rūšis išėjo iš arkos.'),
  (@b1, 8, 20, 'Ir Nojus pastatė VIEŠPAČIUI aukurą; ir paėmė iš visų švariųjų gyvulių ir iš visų švariųjų skrajūnų ir atnašavo ant aukuro deginamąsias atnašas.'),
  (@b1, 8, 21, 'Ir VIEŠPATS užuodė gardų kvapą; ir VIEŠPATS tarė savo širdyje: „Nebeprakeiksiu dirvos dėl žmogaus; nes žmogaus širdies sumanymai pikti nuo pat jo jaunystės; nei nebetriuškinsiu viso, kas gyva, kaip esu padaręs.'),
  (@b1, 8, 22, 'Kol žemė pasilieka, nesiliaus sėja ir pjūtis, šaltis ir karštis, vasara ir žiema, diena ir naktis“.'),
  (@b1, 9, 1, 'Ir Dievas palaimino Nojų bei jo sūnus ir jiems tarė: „Būkite vaisingi ir dauginkitės, ir pripildykite žemę.'),
  (@b1, 9, 2, 'Ir jūsų baimė ir jūsų išgąstis bus ant visų žemės gyvulių ir ant visų oro skrajūnų, ant visų, kas juda žemėje, ir ant visų jūros žuvų; į jūsų ranką jie yra atiduoti.'),
  (@b1, 9, 3, 'Visa, kas kruta, kas gyva, bus jums maistui; lygiai kaip žalias žoles, aš atidaviau jums viską.'),
  (@b1, 9, 4, 'Bet mėsos su jos gyvybe, kuri yra jos kraujas, nevalgykite.'),
  (@b1, 9, 5, 'Ir tikrai jūsų gyvybių kraujo aš pareikalausiu; iš kiekvieno gyvulio rankos jo pareikalausiu, ir iš žmogaus rankos; iš kiekvieno žmogaus brolio rankos pareikalausiu žmogaus gyvybės.'),
  (@b1, 9, 6, 'Kas pralieja žmogaus kraują, to kraujas turi būti žmogaus pralietas; nes pagal Dievo atvaizdą jis padarė žmogų.'),
  (@b1, 9, 7, 'Ir būkite vaisingi ir dauginkitės; gausiai gimdykite žemėje ir dauginkitės joje“.'),
  (@b1, 9, 8, 'Ir Dievas kalbėjo Nojui ir jo sūnums su juo, sakydamas:'),
  (@b1, 9, 9, '„Ir aš štai įtvirtinu savo sandorą su jumis ir su jūsų sėkla po jūsų;'),
  (@b1, 9, 10, 'ir su visais gyvais sutvėrimais, su jumis esančiais, iš skrajūnų, iš galvijų ir iš visų žemės gyvulių, esančių su jumis; iš visų, kurie išėjo iš arkos, iki kiekvieno žemės gyvulio.'),
  (@b1, 9, 11, 'Ir aš įtvirtinsiu savo sandorą su jumis; nei vienas kūnas nebebus atkirstas tvano vandenų; nei nebebus tvano žemei sunaikinti“.'),
  (@b1, 9, 12, 'Ir Dievas tarė: „Šitas yra ženklas sandoros, kurią aš sudarau tarp savęs ir jūsų bei visų gyvų sutvėrimų, esančių su jumis, nesibaigiančioms kartoms:'),
  (@b1, 9, 13, 'savo lanką įdedu į debesį, ir jis bus ženklas sandoros tarp manęs ir žemės.'),
  (@b1, 9, 14, 'Ir įvyks, kad, kai užleisiu debesį virš žemės, lankas matysis debesyje;'),
  (@b1, 9, 15, 'ir aš atsiminsiu savo sandorą, esančią tarp manęs ir jūsų bei visų visokio kūno gyvų sutvėrimų; ir vandenys daugiau nevirs tvanu visiems kūnams sunaikinti.'),
  (@b1, 9, 16, 'Ir lankas bus debesyje; ir aš į jį pažiūrėsiu, kad atsiminčiau amžinąją sandorą tarp Dievo ir visų visokio kūno gyvų sutvėrimų, esančių žemėje“.'),
  (@b1, 9, 17, 'Ir Dievas tarė Nojui: „Tai yra ženklas sandoros, kurią aš įtvirtinau tarp savęs ir kiekvieno žemėje esančio kūno“.'),
  (@b1, 9, 18, 'Ir Nojaus sūnūs, kurie išėjo iš arkos, buvo Šemas, Chamas ir Jafetas; o Chamas yra Kanaano tėvas.'),
  (@b1, 9, 19, 'Tie yra trys Nojaus sūnūs; ir iš jų pasklido po visą žemę.'),
  (@b1, 9, 20, 'Ir Nojus pradėjo būti žemdirbys ir pasodino vynuogyną;'),
  (@b1, 9, 21, 'ir jis gėrė vyno, ir buvo girtas; ir buvo nusidengęs savo palapinėje.'),
  (@b1, 9, 22, 'Ir Chamas, Kanaano tėvas, pamatė savo tėvo nuogumą ir pasakė savo dviems broliams lauke.'),
  (@b1, 9, 23, 'O Šemas ir Jafetas paėmė drabužį ir, užsidėję jį ant abiejų savo pečių, nuėjo atbuli ir uždengė savo tėvo nuogumą; ir jų veidai buvo nusukti atgal, ir jie nepamatė savo tėvo nuogumo.'),
  (@b1, 9, 24, 'Ir Nojus prabudo nuo savo vyno ir sužinojo, ką jam buvo padaręs jo jaunesnis sūnus.'),
  (@b1, 9, 25, 'Ir jis tarė: „Prakeiktas tebūna Kanaanas; tarnų tarnas jis bus savo broliams“.'),
  (@b1, 9, 26, 'Ir jis tarė: „Palaimintas tebūna VIEŠPATS, Šemo Dievas; o Kanaanas bus jo tarnas.'),
  (@b1, 9, 27, 'Dievas praplės Jafetą, ir jis gyvens Šemo palapinėse; o Kanaanas bus jo tarnas“.'),
  (@b1, 9, 28, 'Ir po tvano Nojus gyveno tris šimtus penkiasdešimt metų.'),
  (@b1, 9, 29, 'Ir visų Nojaus dienų buvo devyni šimtai penkiasdešimt metų; ir jis mirė.'),
  (@b1, 10, 1, 'Na, o ši yra Nojaus sūnų, Šemo, Chamo ir Jafeto genealogija; ir jiems po tvano gimė sūnų.'),
  (@b1, 10, 2, 'Jafeto sūnūs: Gomeras, Magogas, Madajas, Javanas, Tubalas, Mešechas ir Tiras.'),
  (@b1, 10, 3, 'O Gomero sūnūs: Aškenazas, Rifatas ir Togarma.'),
  (@b1, 10, 4, 'O Javano sūnūs: Eliša ir Taršišas, Kitimas ir Dodanimas.'),
  (@b1, 10, 5, 'Iš šitų pagonių salos pasidalijo į savąsias šalis; kiekviena pagal savo kalbą, pagal savo šeimas, savo tautose.'),
  (@b1, 10, 6, 'O Chamo sūnūs: Kušas, Mizraimas, Putas ir Kanaanas.'),
  (@b1, 10, 7, 'O Kušo sūnūs: Seba, Havila, Sabta, Rama ir Sabtecha; o Ramos sūnūs: Šeba ir Dedanas.'),
  (@b1, 10, 8, 'Ir Kušas pagimdė Nimrodą; jis pradėjo būti galiūnas žemėje.'),
  (@b1, 10, 9, 'Jis buvo smarkus medžiotojas VIEŠPATIES akivaizdoje; todėl sakoma: „Kaip Nimrodas, galingas medžiotojas VIEŠPATIES akivaizdoje“.'),
  (@b1, 10, 10, 'Ir jo karalystės pradžia buvo Babelis, Erechas, Akadas ir Kalnė Šinaro šalyje.'),
  (@b1, 10, 11, 'Iš tos šalies išvyko Ašūras ir pastatė Ninevę ir Rehoboto miestą bei Kelachą,'),
  (@b1, 10, 12, 'ir Reseną tarp Ninevės ir Kelacho; šis yra didis miestas.'),
  (@b1, 10, 13, 'Ir Mizraimas pagimdė ludimus, anamus, lehabus, naftuchus,'),
  (@b1, 10, 14, 'patrusimus, kasluchus (iš kurių kilo filistai) ir kaftoriečius.'),
  (@b1, 10, 15, 'Ir Kanaanas pagimdė savo pirmagimį Sidoną, Hetą,'),
  (@b1, 10, 16, 'jebusietį, amoritą, girgašą,'),
  (@b1, 10, 17, 'hivą, arką, siną,'),
  (@b1, 10, 18, 'arvadietį, semarą ir hamatietį; o po to kanaaniečių šeimos pasklido.'),
  (@b1, 10, 19, 'Ir kanaaniečių ribos buvo nuo Sidono, einant į Gerarą iki Gazos; einant iki Sodomos, Gomoros, Admos ir Ceboimo iki Lašos.'),
  (@b1, 10, 20, 'Šitie yra Chamo sūnūs pagal jų šeimas, pagal jų kalbas, jų šalyse, jų tautose.'),
  (@b1, 10, 21, 'Taip pat gimė vaikų ir Šemui, visų Ebero vaikų tėvui, vyresniajam Jafeto broliui.'),
  (@b1, 10, 22, 'Šemo vaikai: Elamas, Ašūras, Arfaksadas, Ludas ir Aramas.'),
  (@b1, 10, 23, 'O Aramo vaikai: Ucas, Hulas, Geteras ir Mašas.'),
  (@b1, 10, 24, 'Ir Arfaksadas pagimdė Salą; o Sala pagimdė Eberą.'),
  (@b1, 10, 25, 'O Eberui gimė du sūnūs: vieno vardas Pelegas; nes jo dienomis žemė buvo padalyta; o jo brolio vardas Joktanas.'),
  (@b1, 10, 26, 'Ir Joktanas pagimdė Almodadą, Šelefą, Hacarmavetą, Jerachą,'),
  (@b1, 10, 27, 'Hadoramą, Uzalą, Diklą,'),
  (@b1, 10, 28, 'Obalą, Abimaelį, Šebą,'),
  (@b1, 10, 29, 'Ofyrą, Havilą ir Jobabą; šie visi yra Joktano sūnūs.'),
  (@b1, 10, 30, 'Ir jų gyvenama vieta buvo nuo Mešos einant iki rytų kalno Sefaro.'),
  (@b1, 10, 31, 'Šitie yra Šemo sūnūs pagal jų šeimas, pagal jų kalbas, jų šalyse, pagal jų tautas.'),
  (@b1, 10, 32, 'Šitos yra Nojaus sūnų šeimos pagal jų genealogiją, jų tautose; ir iš šitų tautos pasidalijo žemėje po tvano.'),
  (@b1, 11, 1, 'Ir visa žemė buvo vienos kalbos ir vienos šnekos.'),
  (@b1, 11, 2, 'Ir įvyko, kad jiems bekeliaujant iš rytų jie rado lygumą Šinaro šalyje; ir ten apsigyveno.'),
  (@b1, 11, 3, 'Ir jie sakė vienas kitam: „Nagi, pasidarykime plytų ir jas gerai išdekime“. Ir plytą jie turėjo už akmenį, o dumblą jie turėjo už statybinį skiedinį.'),
  (@b1, 11, 4, 'Ir jie tarė: „Nagi, pasistatykime miestą ir bokštą, kurio viršūnė siektų iki dangaus; ir pasidarykime sau vardą, kad nebūtume išsklaidyti po visos žemės paviršių“.'),
  (@b1, 11, 5, 'Ir VIEŠPATS nužengė pamatyti miesto ir bokšto, kurį žmonių vaikai statė.'),
  (@b1, 11, 6, 'Ir VIEŠPATS tarė: „Štai yra viena tauta, ir jie visi turi vieną kalbą; ir tai jie pradėjo daryti; ir jiems jau nebus ribų niekam, ką jie besumanytų daryti.'),
  (@b1, 11, 7, 'Nagi, nuženkime ir ten sumaišykime jų kalbą, kad jie nebesuprastų vienas kito šnekos“.'),
  (@b1, 11, 8, 'Taip VIEŠPATS juos iš ten išsklaidė po visos žemės paviršių; ir jie liovėsi statę miestą.'),
  (@b1, 11, 9, 'Todėl jo vardas pramintas Babeliu; nes ten VIEŠPATS sumaišė visos žemės kalbą; ir iš ten VIEŠPATS juos išsklaidė po visos žemės paviršių.'),
  (@b1, 11, 10, 'Šita yra Šemo genealogija: Šemas buvo šimto metų ir pagimdė Arfaksadą dvejiems metams praėjus po tvano;'),
  (@b1, 11, 11, 'ir Šemas, po to, kai pagimdė Arfaksadą, gyveno penkis šimtus metų ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 12, 'Ir Arfaksadas pragyveno trisdešimt penkerius metus ir pagimdė Salą;'),
  (@b1, 11, 13, 'ir Arfaksadas, po to, kai pagimdė Salą, gyveno keturis šimtus trejus metus ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 14, 'Ir Sala pragyveno trisdešimt metų ir pagimdė Eberą;'),
  (@b1, 11, 15, 'ir Sala, po to, kai pagimdė Eberą, gyveno keturis šimtus trejus metus ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 16, 'Ir Eberas pragyveno trisdešimt ketverius metus ir pagimdė Pelegą;'),
  (@b1, 11, 17, 'ir Eberas, po to, kai pagimdė Pelegą, gyveno keturis šimtus trisdešimt metų ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 18, 'Ir Pelegas pragyveno trisdešimt metų ir pagimdė Rejų;'),
  (@b1, 11, 19, 'ir Pelegas, po to, kai pagimdė Rejų, gyveno du šimtus devynerius metus ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 20, 'Ir Rejus pragyveno trisdešimt dvejus metus ir pagimdė Serugą;'),
  (@b1, 11, 21, 'ir Rejus, po to, kai pagimdė Serugą, gyveno du šimtus septynerius metus ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 22, 'Ir Serugas pragyveno trisdešimt metų ir pagimdė Nahorą;'),
  (@b1, 11, 23, 'ir Serugas, po to, kai pagimdė Nahorą, gyveno du šimtus metų ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 24, 'Ir Nahoras pragyveno dvidešimt devynerius metus ir pagimdė Terachą;'),
  (@b1, 11, 25, 'ir Nahoras, po to, kai pagimdė Terachą, gyveno šimtą devyniolika metų ir pagimdė sūnų bei dukterų.'),
  (@b1, 11, 26, 'Ir Terachas pragyveno septyniasdešimt metų ir pagimdė Abramą, Nahorą ir Haraną.'),
  (@b1, 11, 27, 'Na, o šita yra Teracho giminė: Terachas pagimdė Abramą, Nahorą ir Haraną; o Haranas pagimdė Lotą.'),
  (@b1, 11, 28, 'Ir Haranas mirė savo tėvo Teracho akivaizdoje savo gimtojoje šalyje, kaldėjų Ūre.'),
  (@b1, 11, 29, 'O Abramas ir Nahoras ėmė sau žmonas; Abramo žmonos vardas buvo Saraja; o Nahoro žmonos vardas Milka, duktė Harano – Milkos tėvo ir Iskos tėvo.'),
  (@b1, 11, 30, 'Bet Saraja buvo nevaisinga; ji neturėjo vaikų.'),
  (@b1, 11, 31, 'Ir Terachas paėmė savo sūnų Abramą ir Harano sūnų Lotą, savo sūnaus sūnų, ir savo marčią Sarają, savo sūnaus Abramo žmoną; ir jie išėjo su jais iš kaldėjų Ūro, kad eitų į Kanaano šalį; ir jie atėjo iki Harano ir ten apsigyveno.'),
  (@b1, 11, 32, 'Ir Teracho dienų buvo du šimtai penkeri metai; ir Terachas mirė Harane.'),
  (@b1, 12, 1, 'Na, o VIEŠPATS tarė Abramui: „Eik iš savo krašto ir iš savo giminių, ir iš savo tėvo namų į šalį, kurią tau parodysiu;'),
  (@b1, 12, 2, 'ir padarysiu tave didele tauta ir laiminsiu tave, ir padarysiu didį tavo vardą; ir tu būsi palaiminimas;'),
  (@b1, 12, 3, 'ir aš laiminsiu tuos, kurie tave laimina, ir prakeiksiu tą, kuris tave prakeikia; ir tavyje bus palaimintos vìsos žemės šeimos“.'),
  (@b1, 12, 4, 'Taigi Abramas išvyko, kaip VIEŠPATS jam buvo pasakęs; ir su juo ėjo Lotas; ir Abramas buvo septyniasdešimt penkerių metų, kai išvyko iš Harano.'),
  (@b1, 12, 5, 'Ir Abramas ėmė savo žmoną Sarają, savo brolio sūnų Lotą ir visą jų turtą, kurį jie buvo sukaupę, ir sielas, kurias jie buvo įsigiję Harane; ir jie išvyko, kad eitų į Kanaano šalį; ir atvyko į Kanaano šalį.'),
  (@b1, 12, 6, 'Ir Abramas perėjo per tą šalį iki Sichemo vietovės, iki Morės lygumos. O anuomet kanaaniečiai buvo toje šalyje.'),
  (@b1, 12, 7, 'Ir VIEŠPATS pasirodė Abramui ir tarė: „Tavo sėklai aš duosiu šitą šalį“. Ir jis ten pastatė aukurą VIEŠPAČIUI, kuris jam pasirodė.'),
  (@b1, 12, 8, 'Ir iš ten jis pasitraukė link kalno Bet-Elio rytuose ir pastatė savo palapinę, Bet-Eliui esant vakaruose, o Ajui – rytuose; ir ten jis pastatė aukurą VIEŠPAČIUI ir šaukėsi VIEŠPATIES vardo.'),
  (@b1, 12, 9, 'Ir Abramas keliavo vis eidamas pietų link.'),
  (@b1, 12, 10, 'Ir buvo badas toje šalyje; ir Abramas nuvyko žemyn į Egiptą, ten laikinai apsigyventi; nes badas buvo sunkus toje šalyje.'),
  (@b1, 12, 11, 'Ir įvyko, kai jis priartėjo, kad įeitų į Egiptą, jis tarė savo žmonai Sarajai: „Štai aš žinau, kad esi moteris graži pažiūrėti;'),
  (@b1, 12, 12, 'todėl įvyks, kad tave išvydę egiptiečiai, sakys: ‘Šita yra jo žmona’; ir jie užmuš mane, bet tave paliks gyvą.'),
  (@b1, 12, 13, 'Sakyk, meldžiu tave, tu esi mano sesuo; idant man gerai klotųsi dėl tavęs; ir mano siela gyvens tavo dėka“.'),
  (@b1, 12, 14, 'Ir įvyko, kad Abramui įėjus į Egiptą, egiptiečiai pamatė moterį, kad ji buvo labai graži.'),
  (@b1, 12, 15, 'Taip pat ją pamatė faraono kunigaikščiai ir ją gyrė faraonui; ir moteris buvo paimta į faraono namus.'),
  (@b1, 12, 16, 'Ir jis gerai elgėsi su Abramu dėl jos; ir jis turėjo avių, jaučių, asilų, tarnų, tarnaičių, asilių ir kupranugarių.'),
  (@b1, 12, 17, 'Ir VIEŠPATS vargino faraoną ir jo namus didelėmis rykštėmis dėl Sarajos, Abramo žmonos.'),
  (@b1, 12, 18, 'Ir faraonas pasišaukė Abramą ir tarė: „Kas tai, ką tu man padarei? Kodėl nepasakei man, kad ji tavo žmona?'),
  (@b1, 12, 19, 'Kodėl sakei: ‘Ji mano sesuo‘? Taip aš ją būčiau ėmęs sau už žmoną; taigi dabar, štai tavo žmona, imk ją ir eik sau“.'),
  (@b1, 12, 20, 'Ir faraonas įsakė savo žmonėms dėl jo; ir jie palydėjo jį ir jo žmoną, ir visa, ką jis turėjo.'),
  (@b1, 13, 1, 'Ir Abramas, jis ir jo žmona, ir visa, ką jis turėjo, bei Lotas su juo, ėjo iš Egipto aukštyn į pietus.'),
  (@b1, 13, 2, 'O Abramas buvo labai turtingas galvijais, sidabru ir auksu.'),
  (@b1, 13, 3, 'Ir jis ėjo savo kelionėse nuo pietų ligi Bet-Elio, iki tos vietos, kur pradžioje tarp Bet-Elio ir Ajo buvo jo palapinė;'),
  (@b1, 13, 4, 'iki vietos to aukuro, kurį jis pirma buvo ten padaręs; ir ten Abramas šaukėsi VIEŠPATIES vardo.'),
  (@b1, 13, 5, 'Ir Lotas, kuris vyko su Abramu, irgi turėjo kaimenių ir bandų, ir palapinių.'),
  (@b1, 13, 6, 'Ir ta šalis nebegalėjo pakelti jų, kad jie gyventų drauge; nes jų turtas buvo toks didžiulis, kad jie negalėjo gyventi drauge.'),
  (@b1, 13, 7, 'Ir buvo vaidai tarp Abramo galvijų kerdžių ir Loto galvijų kerdžių; o tuomet kanaaniečiai ir perizai gyveno toje šalyje.'),
  (@b1, 13, 8, 'Ir Abramas tarė Lotui: „Tenebūna, meldžiu tave, vaidų tarp manęs ir tavęs, tarp mano kerdžių ir tavo kerdžių; nes mes broliai.'),
  (@b1, 13, 9, 'Argi ne visa šalis tavo priešaky? Atsiskirk, meldžiu tave, nuo manęs; jei pasuksi į kairę, tuomet aš eisiu į dešinę; o jei išvyksi į dešinę, tuomet aš eisiu į kairę“.'),
  (@b1, 13, 10, 'Ir Lotas pakėlė savo akis ir matė visą Jordano lygumą, kad ji, prieš VIEŠPAČIUI sunaikinant Sodomą ir Gomorą, buvo visur gerai drėkinama kaip VIEŠPATIES sodas, kaip Egipto šalis einant link Coaro.'),
  (@b1, 13, 11, 'Tada Lotas pasirinko visą Jordano lygumą; ir Lotas keliavo į rytus; ir juodu atsiskyrė vienas nuo kito.'),
  (@b1, 13, 12, 'Abramas gyveno Kanaano šalyje, o Lotas gyveno lygumos miestuose, ir pasistatė palapinę Sodomos link.'),
  (@b1, 13, 13, 'Bet Sodomos žmonės buvo nedori ir be galo nusidėję prieš VIEŠPATĮ.'),
  (@b1, 13, 14, 'Ir VIEŠPATS tarė Abramui, kai Lotas buvo nuo jo atsiskyręs: „Pakelk dabar savo akis ir pažvelk iš vietos, kurioje esi, į šiaurę ir į pietus, į rytus ir į vakarus;'),
  (@b1, 13, 15, 'nes visą šalį, kurią matai, aš duosiu tau ir tavo sėklai amžiams.'),
  (@b1, 13, 16, 'Ir padarysiu tavo sėklą kaip žemės dulkes; taip, kad jei kas galėtų suskaičiuoti žemės dulkes, tai ir tavo sėkla būtų suskaičiuota.'),
  (@b1, 13, 17, 'Kelkis, pereik šalį per jos ilgį ir per jos plotį; nes tau ją duosiu“.'),
  (@b1, 13, 18, 'Tada Abramas patraukė savo palapinę ir atėjo bei gyveno Mamrės lygumoje, kuri yra Hebrone, ir ten pastatė aukurą VIEŠPAČIUI.'),
  (@b1, 14, 1, 'Ir įvyko Šinaro karaliaus Amrafelio, Elasaro karaliaus Arjocho, Elamo karaliaus Kedorlaomerio ir tautų karaliaus Tidalo dienomis;'),
  (@b1, 14, 2, 'kad šitie kariavo su Sodomos karaliumi Bera ir su Gomoros karaliumi Birša, Admos karaliumi Šinabu ir Ceboimo karaliumi Šemeberiu, ir karaliumi Belos, kuri yra Coaras.'),
  (@b1, 14, 3, 'Tie visi susivienijo Sidimo slėnyje, kuris yra Druskos jūra.'),
  (@b1, 14, 4, 'Dvylika metų jie tarnavo Kedorlaomeriui, o tryliktaisiais metais sukilo.'),
  (@b1, 14, 5, 'Ir keturioliktaisiais metais atėjo Kedorlaomeris ir su juo esantys karaliai ir sumušė refajus Ašterot Karnaime, zuzus Chame, emus Šave Kirjataime'),
  (@b1, 14, 6, 'ir horus jų kalne Seyre iki El-Parano, esančio prie dykumos.'),
  (@b1, 14, 7, 'Ir jie sugrįžo ir atėjo į En-Mišpatą, kuris yra Kadešas, ir sutriuškino visą amalekiečių kraštą, taip pat amoritus, kurie gyveno Hacecon-Tamare.'),
  (@b1, 14, 8, 'Ir išėjo Sodomos karalius, Gomoros karalius, Admos karalius, Ceboimo karalius ir karalius Belos (kuri yra Coaras); ir jie stojo kovai su jais Sidimo slėnyje;'),
  (@b1, 14, 9, 'su Elamo karaliumi Kedorlaomeriu, su tautų karaliumi Tidalu, su Šinaro karaliumi Amrafeliu ir Elasaro karaliumi Arjochu – keturi karaliai su penkiais.'),
  (@b1, 14, 10, 'O Sidimo slėnis buvo pilnas klampių duobių; ir Sodomos ir Gomoros karaliai bėgo ir ten griuvo; o likusieji pabėgo į kalną.'),
  (@b1, 14, 11, 'Ir jie paėmė visą Sodomos bei Gomoros turtą ir visą jų maistą, ir nuėjo sau.'),
  (@b1, 14, 12, 'Ir jie paėmė Abramo brolio sūnų Lotą, kuris gyveno Sodomoje, bei jo turtą ir išėjo.'),
  (@b1, 14, 13, 'Ir atėjo vienas, kuris buvo pabėgęs, ir papasakojo hebrajui Abramui; nes jis gyveno lygumoje Mamrės, amorito – Eškolo ir Anero brolio; o šitie buvo Abramo sąjungininkai.'),
  (@b1, 14, 14, 'Ir išgirdęs, kad jo brolis buvo paimtas į nelaisvę, Abramas apginklavo tris šimtus aštuoniolika savo išlavintųjų tarnų, gimusių jo paties namuose, ir vijosi juos iki Dano.'),
  (@b1, 14, 15, 'Ir nakčia jis ir jo tarnai pasidalino prieš juos ir juos sumušė, ir vijosi juos iki Hobos, esančios Damasko kairėje.'),
  (@b1, 14, 16, 'Ir jis pargabeno atgal visą turtą, pargabeno ir savo brolį Lotą bei jo turtą, taip pat moteris ir tautą.'),
  (@b1, 14, 17, 'O po jo sugrįžimo iš Kedorlaomerio ir su juo buvusių karalių skerdynių Sodomos karalius išėjo jo pasitikti Šavės slėnyje, kuris yra karaliaus slėnis.'),
  (@b1, 14, 18, 'Ir Melkizedekas, Salemo karalius, išnešė duonos ir vyno; ir jis buvo aukščiausiojo Dievo kunigas.'),
  (@b1, 14, 19, 'Ir jis palaimino jį ir tarė: „Tebūna palaimintas Abramas aukščiausiojo Dievo, dangaus ir žemės savininko;'),
  (@b1, 14, 20, 'ir tebūna palaimintas aukščiausiasis Dievas, kuris atidavė tavo priešus į tavo ranką“. Ir jis davė jam nuo visko dešimtąją dalį.'),
  (@b1, 14, 21, 'Ir Sodomos karalius tarė Abramui: „Duok man žmones, o turtą imk sau“.'),
  (@b1, 14, 22, 'Ir Abramas tarė Sodomos karaliui: „Aš pakeliu savo ranką į VIEŠPATĮ, aukščiausiąjį Dievą, dangaus ir žemės savininką,'),
  (@b1, 14, 23, 'kad neimsiu nei siūlo, nei apavo dirželio ir kad neimsiu nieko, kas yra tavo, kad nesakytum: ‘Aš padariau Abramą turtingą’;'),
  (@b1, 14, 24, 'išskyrus tai, ką suvalgė jaunuoliai, ir dalį su manimi ėjusių vyrų: Anero, Eškolo ir Mamrės; jie tepasiima savo dalį“.'),
  (@b1, 15, 1, 'Po šių dalykų VIEŠPATIES žodis atėjo Abramui regėjime, sakydamas: „Nebijok, Abramai; aš esu tavo skydas ir tavo be galo didelis atlygis“.'),
  (@b1, 15, 2, 'Ir Abramas tarė: „Viešpatie DIEVE, ką man duosi, kadangi aš einu bevaikis ir mano namų prievaizdas yra šis Eliezeras iš Damasko?“'),
  (@b1, 15, 3, 'Ir Abramas tarė: „Štai tu man nedavei sėklos; o štai gimęs mano namuose yra mano paveldėtojas“.'),
  (@b1, 15, 4, 'Ir štai jam atėjo VIEŠPATIES žodis, sakydamas: „Šis nebus tavo paveldėtojas; bet tas, kuris išeis iš tavo paties vidurių, bus tavo paveldėtojas“.'),
  (@b1, 15, 5, 'Ir išvedęs jį laukan tarė: „Nagi pažvelk į dangų ir skaičiuok žvaigždes, jei gali jas suskaičiuoti“; ir jis jam tarė: „Tokia bus tavo sėkla“.'),
  (@b1, 15, 6, 'Ir jis patikėjo VIEŠPAČIU; ir jis jam tai užskaitė teisumu.'),
  (@b1, 15, 7, 'Ir jis jam tarė: „Aš – VIEŠPATS, kuris tave išvedžiau iš kaldėjų Ūro, kad tau duočiau paveldėti šitą šalį“.'),
  (@b1, 15, 8, 'Ir jis tarė: „Viešpatie DIEVE, iš ko aš žinosiu, kad ją paveldėsiu?“'),
  (@b1, 15, 9, 'Ir jis jam tarė: „Paimk man trejų metų karvę, trejų metų ožką, trejų metų aviną, purplelį ir jauną karvelį“.'),
  (@b1, 15, 10, 'Ir pasiėmęs visus tuos jis padalijo juos pusiau ir sudėjo kiekvieną gabalą vieną priešais kitą; bet paukščių jis nepadalijo.'),
  (@b1, 15, 11, 'Ir kai skrajūnai nusileido ant lavonų, Abramas juos nuvaikė.'),
  (@b1, 15, 12, 'Ir saulei leidžiantis gilus miegas nupuolė ant Abramo; ir štai didžios tamsos išgąstis nupuolė ant jo.'),
  (@b1, 15, 13, 'Ir jis tarė Abramui: „Tikrai žinok, kad tavo sėkla bus ateivis ne savo krašte ir jiems tarnaus; o jie juos vargins keturis šimtus metų;'),
  (@b1, 15, 14, 'bet ir tą tautą, kuriai jie tarnaus, aš teisiu; o po to jie išvyks su dideliu turtu.'),
  (@b1, 15, 15, 'O tu nueisi pas savo tėvus ramybėje; tu būsi palaidotas žiloje senatvėje.'),
  (@b1, 15, 16, 'Bet ketvirtoje kartoje jie čia sugrįš; nes amoritų neteisybė dar nepilna“.'),
  (@b1, 15, 17, 'Ir įvyko, kad, kai nusileido saulė ir buvo tamsu, štai rūkstanti krosnis ir degantis žibintas praėjo tarp tų gabalų.'),
  (@b1, 15, 18, 'Tą pačią dieną VIEŠPATS sudarė su Abramu sandorą, sakydamas: „Tavo sėklai aš daviau šitą šalį nuo Egipto upės iki didžiosios upės, Eufrato upės:'),
  (@b1, 15, 19, 'kenitus, kenazus, kadmonitus,'),
  (@b1, 15, 20, 'hetitus, perizus, refajus,'),
  (@b1, 15, 21, 'amoritus, kanaaniečius, girgašus ir jebusiečius“.'),
  (@b1, 16, 1, 'Na, o Saraja, Abramo žmona, nepagimdė jam vaikų; ir ji turėjo egiptietę tarnaitę, kurios vardas Hagara.'),
  (@b1, 16, 2, 'Ir Saraja tarė Abramui: „Štai VIEŠPATS sulaikė mane nuo gimdymo; aš meldžiu tave, įeik pas mano tarnaitę; galbūt per ją gausiu vaikų“. Ir Abramas paklausė Sarajos balso.'),
  (@b1, 16, 3, 'Ir Abramui išgyvenus dešimtį metų Kanaano šalyje, Abramo žmona Saraja ėmė egiptietę Hagarą, savo tarnaitę, ir ją davė savo vyrui Abramui būti jo žmona.'),
  (@b1, 16, 4, 'Ir jis įėjo pas Hagarą, ir ji pastojo; o kai ji pamatė, kad pastojo, jos šeimininkė buvo paniekinta jos akyse.'),
  (@b1, 16, 5, 'Ir Saraja tarė Abramui: „Mano skriauda tebūna ant tavęs; aš daviau savo tarnaitę tavo prieglobstin; o kai ji pamatė, kad pastojo, aš buvau paniekinta jos akyse; VIEŠPATS teteisia tarp manęs ir tavęs“.'),
  (@b1, 16, 6, 'Bet Abramas tarė Sarajai: „Štai tavo tarnaitė yra tavo rankoje; daryk jai, kaip tau patinka“. Ir kai Saraja su ja šiurkščiai elgėsi, ta pabėgo nuo jos veido.'),
  (@b1, 16, 7, 'Ir VIEŠPATIES angelas ją rado prie vandens šaltinio dykumoje, prie šaltinio kelyje į Šūrą.'),
  (@b1, 16, 8, 'Ir jis tarė: „Hagara, Sarajos tarnaite, iš kur atėjai ir kur eisi?“ Ir ji tarė: „Aš bėgu nuo savo šeimininkės Sarajos veido“.'),
  (@b1, 16, 9, 'Ir VIEŠPATIES angelas jai tarė: „Sugrįžk pas savo šeimininkę ir nusižemink po jos rankomis“.'),
  (@b1, 16, 10, 'Ir VIEŠPATIES angelas jai tarė: „Aš nepaprastai padauginsiu tavo sėklą, kad dėl daugybės nebus galima jos suskaičiuoti“.'),
  (@b1, 16, 11, 'Ir VIEŠPATIES angelas jai tarė: „Štai tu nėščia ir pagimdysi sūnų, ir praminsi jį vardu Išmaelis; nes VIEŠPATS išgirdo tavo sielvartą.'),
  (@b1, 16, 12, 'Ir jis bus laukinis žmogus; jo ranka bus prieš visus, o visų ranka prieš jį; ir jis gyvens visų savo brolių akivaizdoje“.'),
  (@b1, 16, 13, 'Ir VIEŠPATĮ, kuris jai kalbėjo, ji praminė vardu: „Tu, Dieve, mane matai“; nes ji sakė: „Ar aš čia žiūrėjau paskui tą, kuris mane mato?“'),
  (@b1, 16, 14, 'Todėl tą šulinį pavadino Beer-Lachai-Roi; štai jis yra tarp Kadešo ir Beredo.'),
  (@b1, 16, 15, 'Ir Hagara pagimdė Abramui sūnų; ir Abramas savo sūnų, kurį pagimdė Hagara, praminė vardu Išmaelis.'),
  (@b1, 16, 16, 'Ir Abramas buvo aštuoniasdešimt šešerių metų, kai Hagara pagimdė Abramui Išmaelį.'),
  (@b1, 17, 1, 'Ir kai Abramas buvo devyniasdešimt devynerių metų, VIEŠPATS pasirodė Abramui ir jam tarė: „Aš esu Visagalis Dievas; vaikščiok mano akivaizdoje ir būk tobulas.'),
  (@b1, 17, 2, 'Ir aš sudarysiu savo sandorą tarp savęs ir tavęs ir nepaprastai tave padauginsiu“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 17, 3, 'Ir Abramas parpuolė veidu žemyn; ir Dievas kalbėjo su juo, tardamas:'),
  (@b1, 17, 4, '„Kas dėl manęs, štai mano sandora yra su tavimi; ir tu būsi daugelio tautų tėvu.'),
  (@b1, 17, 5, 'Nei nesivadinsi vardu Abramas, bet tavo vardas bus Abraomas; nes aš tave padariau daugelio tautų tėvu.'),
  (@b1, 17, 6, 'Ir aš tave padarysiu nepaprastai vaisingą ir iš tavęs padarysiu tautas, ir karaliai išeis iš tavęs.'),
  (@b1, 17, 7, 'Ir aš įtvirtinsiu savo sandorą tarp savęs ir tavęs bei tavo sėklos po tavęs per jų kartas kaip amžiną sandorą, kad būčiau Dievas tau ir tavo sėklai po tavęs.'),
  (@b1, 17, 8, 'Ir aš duosiu tau ir tavo sėklai po tavęs šalį, kurioje esi ateivis, visą Kanaano šalį, amžinai nuosavybei; ir aš būsiu jų Dievas“.'),
  (@b1, 17, 9, 'Ir Dievas tarė Abraomui: „Todėl laikykis mano sandoros, tu ir tavo sėkla po tavęs per jų kartas.'),
  (@b1, 17, 10, 'Ta yra mano sandora, kurios turite laikytis, tarp manęs ir jūsų bei tavo sėklos po tavęs; kiekvienas vyriškos lyties vaikas tarp jūsų bus apipjaustytas.'),
  (@b1, 17, 11, 'Jūs apipjaustykite savo apyvarpės kūną; ir tai bus sandoros ženklas tarp manęs ir jūsų.'),
  (@b1, 17, 12, 'Ir kas yra aštuonių dienų amžiaus, bus apipjaustytas tarp jūsų – kiekvienas vyriškos lyties vaikas jūsų kartose: kas gimęs namuose ar iš kurio svetimšalio už pinigus nupirktas, kuris nėra iš tavo sėklos.'),
  (@b1, 17, 13, 'Būtinai turi būti apipjaustytas gimusysis tavo namuose ir už tavo pinigus nupirktasis; ir mano sandora jūsų kūne bus amžina sandora.'),
  (@b1, 17, 14, 'O neapipjaustytas vyriškos lyties vaikas, kurio apyvarpės kūnas nėra apipjaustytas, ta siela bus iškirsta iš savo tautos; jis sulaužė mano sandorą“.'),
  (@b1, 17, 15, 'Ir Dievas tarė Abraomui: „O dėl tavo žmonos Sarajos, nevadink jos vardu Saraja, bet jos vardas bus Sara.'),
  (@b1, 17, 16, 'Ir aš ją laiminsiu ir taip pat tau duosiu iš jos sūnų; taip, aš ją palaiminsiu ir ji bus tautų motina; tautų karaliai bus iš jos“.'),
  (@b1, 17, 17, 'Tada Abraomas parpuolė veidu žemėn ir juokėsi bei savo širdyje tarė: „Ar tam, kuris yra šimto metų, gims vaikas, ir ar Sara, kuri yra devyniasdešimties metų, gimdys?“'),
  (@b1, 17, 18, 'Ir Abraomas tarė Dievui: „Ach, kad tik Išmaelis gyventų tavo akivaizdoje!“'),
  (@b1, 17, 19, 'Ir Dievas tarė: „Tavo žmona Sara iš tikrųjų pagimdys tau sūnų; ir tu jį praminsi vardu Izaokas; ir aš įtvirtinsiu savo sandorą su juo kaip amžiną sandorą, ir su jo sėkla po jo.'),
  (@b1, 17, 20, 'O dėl Išmaelio, aš tave išklausiau; štai aš jį palaiminau ir padarysiu jį vaisingą ir nepaprastai jį padauginsiu; jis pagimdys dvylika kunigaikščių, ir aš jį padarysiu didele tauta.'),
  (@b1, 17, 21, 'Tačiau savo sandorą aš įtvirtinsiu su Izaoku, kurį tau Sara pagimdys šiuo nustatytu laiku kitais metais“.'),
  (@b1, 17, 22, 'Ir jis baigė kalbėti su juo, ir Dievas pakilo nuo Abraomo.'),
  (@b1, 17, 23, 'Ir Abraomas paėmė savo sūnų Išmaelį bei visus jo namuose gimusius ir visus už jo pinigus nupirktus, kiekvieną vyriškos lyties tarp Abraomo namų žmonių; ir apipjaustė jų apyvarpės kūną tą pačią dieną, kaip Dievas buvo jam sakęs.'),
  (@b1, 17, 24, 'Ir Abraomas buvo devyniasdešimt devynerių metų, kai jis buvo apipjaustytas jo apyvarpės kūne.'),
  (@b1, 17, 25, 'O jo sūnus Išmaelis buvo trylikos metų, kai jo apyvarpės kūnas buvo apipjaustytas.'),
  (@b1, 17, 26, 'Tą pačią dieną buvo apipjaustyti Abraomas ir jo sūnus Išmaelis.'),
  (@b1, 17, 27, 'Ir visi jo namų vyrai, gimusieji namuose ir už pinigus iš svetimšalio nupirktieji, buvo apipjaustyti su juo.'),
  (@b1, 18, 1, 'Ir VIEŠPATS jam pasirodė Mamrės lygumose; o jis sėdėjo palapinės duryse dienos kaitroje;'),
  (@b1, 18, 2, 'ir jis pakėlė savo akis ir pažiūrėjo, ir štai trys vyrai stovėjo prie jo; ir juos pamatęs jis bėgo nuo palapinės durų jų pasitikti ir nusilenkė iki žemės'),
  (@b1, 18, 3, 'bei tarė: „Mano Viešpatie, jei dabar radau palankumą tavo akyse, meldžiu tave, nepraeik pro šalį nuo savo tarno;'),
  (@b1, 18, 4, 'meldžiu jus, tebūna atnešta truputis vandens, ir nusiplaukite kojas, ir pailsėkite po medžiu;'),
  (@b1, 18, 5, 'o aš atnešiu duonos kąsnį, ir paguoskite savo širdis; po to eikite toliau; nes dėl to jūs atėjote pas savo tarną“. Ir jie tarė: „Daryk taip, kaip kalbėjai“.'),
  (@b1, 18, 6, 'Ir Abraomas nuskubėjo į palapinę pas Sarą ir tarė: „Skubiai paruošk tris saikus smulkių miltų, suminkyk juos ir iškepk ant židinio paplotėlių“.'),
  (@b1, 18, 7, 'O Abraomas nubėgo prie bandos ir paėmęs minkštą gerą veršį padavė jaunuoliui; o tas skubėjo jį paruošti.'),
  (@b1, 18, 8, 'Ir jis paėmė sviesto bei pieno ir veršį, kurį buvo paruošęs, ir padėjo prieš juos; ir jis stovėjo prie jų po medžiu, o jie valgė.'),
  (@b1, 18, 9, 'Ir jie tarė jam: „Kur tavo žmona Sara?“ Ir jis tarė: „Štai, palapinėje“.'),
  (@b1, 18, 10, 'O jis tarė: „Aš tikrai sugrįšiu pas tave pagal tą gyvenimo laiką; ir štai tavo žmona Sara turės sūnų“. O Sara tai girdėjo palapinės duryse, esančiose jo užnugaryje.'),
  (@b1, 18, 11, 'Na, o Abraomas ir Sara buvo seni, gerai palaužti amžiaus; ir Sarai paliovė būti pagal moterų būdą.'),
  (@b1, 18, 12, 'Todėl Sara juokėsi savyje, sakydama: „Pasenusi ir mano viešpačiui esant senam, ar aš turėsiu malonumą?“'),
  (@b1, 18, 13, 'Ir VIEŠPATS tarė Abraomui: „Kodėl Sara juokėsi, sakydama: ‚Ar aš, būdama sena, tikrai vaiką pagimdysiu?‘'),
  (@b1, 18, 14, 'Ar yra kas VIEŠPAČIUI per sunku? Skirtu laiku pagal tą gyvenimo laiką aš sugrįšiu pas tave, ir Sara turės sūnų“.'),
  (@b1, 18, 15, 'Tada Sara gynėsi, sakydama: „Aš nesijuokiau“; nes ji bijojo. Ir jis tarė: „Ne; tu juokeisi“.'),
  (@b1, 18, 16, 'Ir tie vyrai pakilo iš ten ir žiūrėjo link Sodomos; o Abraomas ėjo su jais, kad juos palydėtų į kelią.'),
  (@b1, 18, 17, 'Ir VIEŠPATS tarė: „Ar aš slėpsiu nuo Abraomo tai, ką aš darau;'),
  (@b1, 18, 18, 'kadangi Abraomas tikrai taps didele ir galinga tauta, ir visos žemės tautos bus palaimintos jame?'),
  (@b1, 18, 19, 'Nes aš žinau jį, kad jis įsakys savo vaikams ir savo namiškiams po savęs, ir jie laikysis VIEŠPATIES kelio, kad darytų teisingumą ir teismą; kad VIEŠPATS atneštų Abraomui tai, ką yra apie jį kalbėjęs“.'),
  (@b1, 18, 20, 'Ir VIEŠPATS tarė: „Kadangi Sodomos ir Gomoros šauksmas yra didelis ir kadangi jų nuodėmė yra labai sunki;'),
  (@b1, 18, 21, 'aš dabar nusileisiu ir pamatysiu, ar jie darė visiškai pagal tą savo šauksmą, kuris mane yra pasiekęs; o jei ne, aš sužinosiu“.'),
  (@b1, 18, 22, 'Ir tie vyrai nusuko nuo ten savo veidus ir ėjo link Sodomos; bet Abraomas dar tebestovėjo VIEŠPATIES akivaizdoje.'),
  (@b1, 18, 23, 'Ir Abraomas priartėjo ir tarė: „Ar tu sunaikinsi taip pat ir teisųjį su nedorėliu?'),
  (@b1, 18, 24, 'Galbūt penkiasdešimt teisiųjų yra mieste; ar taip pat sunaikinsi ir nepagailėsi tos vietovės dėl penkiasdešimties teisiųjų, esančių joje?'),
  (@b1, 18, 25, 'Tebūna toli nuo tavęs taip daryti – kad nužudytum teisųjį su nedorėliu; ir kad teisusis būtų kaip nedorėlis, tebūna tai toli nuo tavęs; argi visos žemės Teisėjas neturėtų daryti, kas teisu?“'),
  (@b1, 18, 26, 'Ir VIEŠPATS tarė: „Jei Sodomoje, miesto viduje, rasiu penkiasdešimt teisiųjų, tai dėl jų pasigailėsiu visos vietovės“.'),
  (@b1, 18, 27, 'Ir Abraomas atsakė ir tarė: „Na štai, apsiėmiau kalbėti Viešpačiui aš, kuris tesu dulkės ir pelenai;'),
  (@b1, 18, 28, 'galbūt ligi penkiasdešimties teisiųjų trūks penkių; ar dėl pritrūkusių penkių sunaikinsi visą miestą?“ Ir jis tarė: „Jei ten rasiu keturiasdešimt penkis, aš jo nesunaikinsiu“.'),
  (@b1, 18, 29, 'Ir jis dar jam kalbėjo ir tarė: „Galbūt ten bus rasta keturiasdešimt“. Ir jis tarė: „Dėl keturiasdešimties aš to nepadarysiu“.'),
  (@b1, 18, 30, 'Ir jis tarė jam: „O, tenepyksta Viešpats, ir aš kalbėsiu; galbūt ten bus rasta trisdešimt“. Ir jis tarė: „Aš to nedarysiu, jei ten rasiu trisdešimt“.'),
  (@b1, 18, 31, 'Ir jis tarė: „Na štai, apsiėmiau kalbėti Viešpačiui: galbūt ten bus rasta dvidešimt“. Ir jis tarė: „Aš nesunaikinsiu jo dėl dvidešimties“.'),
  (@b1, 18, 32, 'Ir jis tarė: „O, tenepyksta Viešpats, ir aš dar vieną kartą kalbėsiu: galbūt ten bus rasta dešimt“. Ir jis tarė: „Aš nesunaikinsiu jo dėl dešimties“.'),
  (@b1, 18, 33, 'Ir VIEŠPATS, baigęs kalbėti su Abraomu, nuėjo sau; o Abraomas sugrįžo į savo vietą.'),
  (@b1, 19, 1, 'Ir du angelai atėjo vakare į Sodomą; o Lotas sėdėjo Sodomos vartuose; ir juos pamatęs Lotas atsikėlė jų pasitikti; ir jis nusilenkė veidu į žemę;'),
  (@b1, 19, 2, 'ir jis tarė: „Štai dabar, mano viešpačiai, užsukite, meldžiu jus, į savo tarno namus ir pasilikite visą naktį, ir nusiplaukite kojas, o anksti atsikėlę eikite savo keliu“. Ir jie tarė: „Ne; mes pasiliksime visą naktį gatvėje“.'),
  (@b1, 19, 3, 'O jis primygtinai juos prašė; ir jie užsuko pas jį ir įėjo į jo namus; ir jis paruošė jiems vaišes ir iškepė neraugintos duonos, ir jie valgė.'),
  (@b1, 19, 4, 'Bet, jiems dar neatsigulus, miesto vyrai, Sodomos vyrai, apsupo namus – tiek seni, tiek jauni, visa tauta iš visų pusių;'),
  (@b1, 19, 5, 'ir jie pašaukė Lotą ir jam tarė: „Kur tie vyrai, kurie šiąnakt atėjo pas tave? Išvesk juos pas mus, kad juos pažintume“.'),
  (@b1, 19, 6, 'Ir Lotas išėjo pas juos prie durų ir užrakino paskui save duris,'),
  (@b1, 19, 7, 'ir tarė: „Broliai, meldžiu jus, nedarykite taip piktai.'),
  (@b1, 19, 8, 'Štai aš turiu dvi dukteris, kurios nėra pažinusios vyro; leiskite man, meldžiu jus, jas išvesti pas jus, ir joms darykite, kaip yra gerai jūsų akyse; tik šitiems vyrams nieko nedarykite; nes dėl to jie atėjo po mano stogo priedanga“.'),
  (@b1, 19, 9, 'Ir jie tarė: „Atsitrauk“. Ir vėl jie sakė: „Šitas atėjo laikinai apsigyventi, o nori būti teisėjas; dabar pasielgsime su tavimi blogiau negu su jais“. Ir jie labai veržėsi prie to vyro, prie Loto, ir priartėjo, kad išlaužtų duris.'),
  (@b1, 19, 10, 'Tačiau tie vyrai ištiesė savo ranką ir įtempė Lotą pas save į namą, ir užrakino duris.'),
  (@b1, 19, 11, 'O vyrus, esančius prie namų durų, jie ištiko aklumu, tiek mažus, tiek didelius; taip, kad šie nuvargo beieškodami durų.'),
  (@b1, 19, 12, 'Ir tie vyrai tarė Lotui: „Ar dar ką čia turi? Žentą, savo sūnus, savo dukteris ir ką tik turi mieste, išvesk iš šitos vietos;'),
  (@b1, 19, 13, 'nes mes sunaikinsime šitą vietą, kadangi jų šauksmas pasidarė didelis prieš VIEŠPATIES veidą; ir VIEŠPATS mus siuntė jį sunaikinti“.'),
  (@b1, 19, 14, 'Ir Lotas išėjo ir kalbėjo savo žentams, kurie vedė jo dukteris, ir sakė: „Kelkitės, išeikite iš šitos vietos; nes VIEŠPATS sunaikins šitą miestą“. Bet jis atrodė savo žentams kaip išsijuokiantis.'),
  (@b1, 19, 15, 'Ir išaušus rytui angelai skubino Lotą, sakydami: „Kelkis, imk savo žmoną ir savo dvi dukteris, kurios čia yra; kad nebūtum sunaikintas šio miesto neteisybėje“.'),
  (@b1, 19, 16, 'O jam tebedelsiant tie vyrai nutvėrė jo ranką, jo žmonos ranką ir jo abiejų dukterų rankas – VIEŠPATS buvo jam gailestingas – ir jie išvedė jį ir pastatė jį už miesto.'),
  (@b1, 19, 17, 'Ir įvyko, kai jie juos išvedė laukan, jis tarė: „Gelbėkis dėl savo gyvybės; nežiūrėk paskui save nei nestovėk visoje toje lygumoje; bėk į kalną, kad nebūtum sunaikintas“.'),
  (@b1, 19, 18, 'Ir Lotas jiems tarė: „O ne, mano Viešpatie;'),
  (@b1, 19, 19, 'štai tavo tarnas rado malonę tavo akyse, ir tu išaukštinai savo gailestingumą, kurį man parodei išgelbėdamas mano gyvybę; bet aš negaliu pabėgti į kalną, kad manęs kas pikta neištiktų ir aš nemirčiau;'),
  (@b1, 19, 20, 'štai šitas miestas arti į jį pabėgti ir jis mažas; o, leisk man ten pabėgti (argi jis ne mažas?), ir mano siela gyvens“.'),
  (@b1, 19, 21, 'Ir jis jam tarė: „Štai aš atsižvelgiau į tave ir dėl šito dalyko, kad aš nesunaikinčiau šito miesto, apie kurį kalbėjai.'),
  (@b1, 19, 22, 'Skubėk, ten bėk; nes aš nieko negaliu daryti, kol tu ten nebūsi nuėjęs“. Todėl to miesto vardas buvo vadinamas Coaras.'),
  (@b1, 19, 23, 'Saulė buvo patekėjusi virš žemės, kai Lotas įėjo į Coarą.'),
  (@b1, 19, 24, 'Tada VIEŠPATS lijo ant Sodomos ir Gomoros siera ir ugnimi nuo VIEŠPATIES iš dangaus;'),
  (@b1, 19, 25, 'ir jis išvertė šituos miestus, visą tą lygumą, visus miestų gyventojus ir tai, kas augo ant dirvos.'),
  (@b1, 19, 26, 'Bet jo žmona, esanti už jo, pažvelgė atgal ir pavirto druskos stulpu.'),
  (@b1, 19, 27, 'Ir Abraomas atsikėlė ankstų rytą eiti į tą vietą, kur jis stovėjo VIEŠPATIES akivaizdoje;'),
  (@b1, 19, 28, 'ir jis pažvelgė į Sodomą bei Gomorą ir į visą tos lygumos šalį ir pamatė, ir štai, krašto dūmai kilo aukštyn kaip krosnies dūmai.'),
  (@b1, 19, 29, 'Ir įvyko, kai Dievas naikino tos lygumos miestus, Dievas atsiminė Abraomą ir siuntė Lotą iš griovimo vidurio, kai jis griovė miestus, kuriuose gyveno Lotas.'),
  (@b1, 19, 30, 'O Lotas ėjo aukštyn iš Coaro ir gyveno kalne, ir jo abi dukterys su juo; nes jis bijojo gyventi Coare; ir jis gyveno oloje, jis ir abi jo dukterys.'),
  (@b1, 19, 31, 'Ir pirmagimė tarė jaunesniajai: „Mūsų tėvas senas, ir nėra žemėje vyro, kad įeitų pas mus pagal visos žemės būdą;'),
  (@b1, 19, 32, 'eikš, pagirdykime vynu savo tėvą, ir mes su juo sugulsime, kad iš savo tėvo išsaugotume sėklą“.'),
  (@b1, 19, 33, 'Ir jos tą naktį pagirdė vynu savo tėvą; ir pirmagimė įėjo ir gulėjo su savo tėvu; o jis nepajuto nei kai ji atsigulė, nei kai ji atsikėlė.'),
  (@b1, 19, 34, 'Ir rytojaus dieną įvyko, kad pirmagimė tarė jaunesniajai: „Štai aš vakar naktį gulėjau su savo tėvu; pagirdykime jį vynu ir šiąnakt; ir įeik tu ir sugulk su juo, kad iš savo tėvo išsaugotume sėklą“.'),
  (@b1, 19, 35, 'Ir jos ir tą naktį pagirdė vynu savo tėvą; ir pakilo jaunesnioji ir sugulė su juo; o jis nepajuto nei kai ji atsigulė, nei kai ji atsikėlė.'),
  (@b1, 19, 36, 'Taip abi Loto dukterys buvo nėščios nuo savo tėvo.'),
  (@b1, 19, 37, 'Ir pirmagimė pagimdė sūnų ir praminė jį vardu Moabas; jis yra moabiečių tėvas iki šios dienos.'),
  (@b1, 19, 38, 'Ir jaunesnioji, ji taip pat pagimdė sūnų ir praminė jį vardu Ben-Amis; jis yra Amono vaikų tėvas iki šios dienos.'),
  (@b1, 20, 1, 'Ir iš ten Abraomas keliavo pietų šalies link ir gyveno tarp Kadešo ir Šūro, ir laikinai apsigyveno Gerare.'),
  (@b1, 20, 2, 'Ir Abraomas sakė apie savo žmoną Sarą: „Ji mano sesuo“; ir Geraro karalius Abimelechas pasiuntė ir paėmė Sarą.'),
  (@b1, 20, 3, 'Bet Dievas atėjo pas Abimelechą sapne naktį ir jam tarė: „Štai tu numirėlis dėl moters, kurią paėmei; nes ji vyro žmona“.'),
  (@b1, 20, 4, 'Bet Abimelechas nebuvo prie jos prisiartinęs; ir jis tarė: „Viešpatie, ar tu ir teisią tautą užmuši?'),
  (@b1, 20, 5, 'Argi jis man nesakė: ‘Ji mano sesuo‘? Ir ji, ir ji pati sakė: ‘Jis mano brolis’; savo širdies dorumu ir savo rankų nekaltumu aš tai padariau“.'),
  (@b1, 20, 6, 'Ir Dievas jam tarė sapne: „Taip, aš žinau, kad tai padarei savo širdies dorumu; nes taip pat aš tave sulaikiau, kad prieš mane nenusidėtum; todėl tau neleidau jos paliesti.'),
  (@b1, 20, 7, 'Taigi dabar sugrąžink vyrui jo žmoną; nes jis yra pranašas, ir jis melsis už tave, ir tu gyvensi; o jei jos nesugrąžinsi, žinok, kad tikrai mirsi, tu ir visa, kas tavo“.'),
  (@b1, 20, 8, 'Taigi Abimelechas atsikėlė anksti ryte ir pašaukė visus savo tarnus, ir pasakė visa tai į jų ausis; ir tie vyrai labai bijojo.'),
  (@b1, 20, 9, 'Paskui Abimelechas pašaukė Abraomą ir jam tarė: „Ką mums padarei? Ir kuo aš tau nusikaltau, kad užtraukei ant manęs ir ant mano karalystės didelę nuodėmę? Padarei man tai, kas neturėtų būti daroma“.'),
  (@b1, 20, 10, 'Ir Abimelechas tarė Abraomui: „Ką regėjai, kad padarei tokį dalyką?“'),
  (@b1, 20, 11, 'Ir Abraomas tarė: „Kadangi aš maniau: ‘Tikrai Dievo baimės nėra šioje vietovėje; ir dėl mano žmonos jie užmuš mane’.'),
  (@b1, 20, 12, 'Be to, iš tiesų ji yra mano sesuo; ji yra mano tėvo duktė, bet ne mano motinos duktė; ir ji tapo mano žmona.'),
  (@b1, 20, 13, 'Ir įvyko, kai Dievas man liepė klajoti nuo mano tėvo namų, tada aš jai tariau: ‘Tai tavo gerumas, kurį man parodysi; kiekvienoje vietoje, kur mes ateisime, sakyk apie mane: Jis mano brolis’“.'),
  (@b1, 20, 14, 'Ir Abimelechas ėmė avių, jaučių, tarnų bei tarnaičių ir juos davė Abraomui, ir jam grąžino jo žmoną Sarą.'),
  (@b1, 20, 15, 'Ir Abimelechas tarė: „Štai mano kraštas yra tavo akivaizdoje; gyvenk, kur tau patinka“.'),
  (@b1, 20, 16, 'O Sarai jis tarė: „Štai aš daviau tavo broliui tūkstantį sidabrinių; štai jis tau yra akių dangalas visiems, kurie yra su tavimi ir su visais kitais“; taip ji buvo pabarta.'),
  (@b1, 20, 17, 'Taigi Abraomas meldėsi Dievui; ir Dievas išgydė Abimelechą, jo žmoną ir jo tarnaites; ir jos gimdė vaikus.'),
  (@b1, 20, 18, 'Nes VIEŠPATS buvo tvirtai uždaręs visas Abimelecho namų įsčias dėl Abraomo žmonos Saros.'),
  (@b1, 21, 1, 'Ir VIEŠPATS aplankė Sarą, kaip jis buvo sakęs, ir VIEŠPATS padarė Sarai, kaip jis buvo kalbėjęs.'),
  (@b1, 21, 2, 'Nes Sara pastojo ir pagimdė sūnų Abraomui jo senatvėje, paskirtu metu, apie kurį Dievas buvo jam kalbėjęs.'),
  (@b1, 21, 3, 'Ir Abraomas praminė savo sūnų, kuris jam buvo gimęs, kurį jam pagimdė Sara, vardu Izaokas.'),
  (@b1, 21, 4, 'Ir Abraomas apipjaustė savo sūnų Izaoką, esantį aštuonių dienų amžiaus, kaip Dievas jam buvo įsakęs.'),
  (@b1, 21, 5, 'Ir Abraomas buvo šimto metų, kai jam gimė jo sūnus Izaokas.'),
  (@b1, 21, 6, 'Ir Sara tarė: „Dievas man padarė juoko, kad visi, kurie girdės, juoksis su manimi“.'),
  (@b1, 21, 7, 'Ir ji tarė: „Kas būtų pasakęs Abraomui, kad Sara žindys vaikus? Nes aš jam pagimdžiau sūnų jo senatvėje“.'),
  (@b1, 21, 8, 'Ir vaikas augo ir buvo nujunkytas; ir tą dieną, kai Izaokas buvo nujunkytas, Abraomas iškėlė didelį pokylį.'),
  (@b1, 21, 9, 'Ir Sara pamatė egiptietės Hagaros sūnų, kurį ji buvo pagimdžiusi Abraomui, besityčiojantį.'),
  (@b1, 21, 10, 'Dėl to ji tarė Abraomui: „Išvaryk šitą vergę ir jos sūnų; nes šitos vergės sūnus nebus paveldėtojas su mano sūnumi, su Izaoku“.'),
  (@b1, 21, 11, 'Ir tas dalykas buvo labai sunkus Abraomo akyse dėl jo sūnaus.'),
  (@b1, 21, 12, 'Ir Dievas tarė Abraomui: „Tenebūna tai sunku tavo akyse dėl berniuko ir dėl tavo vergės; visame, ką Sara tau sakė, paklausyk jos balso; nes Izaoke bus pašaukta tavo sėkla.'),
  (@b1, 21, 13, 'Ir taip pat iš vergės sūnaus aš padarysiu tautą, nes jis yra tavo sėkla“.'),
  (@b1, 21, 14, 'Ir Abraomas atsikėlė anksti ryte ir paėmė duonos bei indą vandens ir davė Hagarai, užkėlęs tai jai ant peties, ir vaiką, ir ją išleido; ir ji išėjo ir klaidžiojo Beer-Šebos dykumoje.'),
  (@b1, 21, 15, 'Ir vanduo inde buvo išsekęs, ir ji numetė vaiką po vienu iš krūmokšnių.'),
  (@b1, 21, 16, 'Ir ji nuėjo bei atsisėdo priešais jį per gerą, lyg lanko šūvio, atstumą; nes ji tarė: „Tenematysiu vaiko mirties“. Ir ji sėdėjo priešais jį ir pakeltu balsu verkė.'),
  (@b1, 21, 17, 'Ir Dievas išgirdo berniuko balsą; ir Dievo angelas pašaukė iš dangaus Hagarai ir jai tarė: „Kas tau yra, Hagara? Nebijok; nes Dievas išgirdo berniuko balsą ten, kur jis yra.'),
  (@b1, 21, 18, 'Kelkis, pakelk berniuką ir laikyk jį savo rankoje; nes aš jį padarysiu didele tauta“.'),
  (@b1, 21, 19, 'Ir Dievas jai atvėrė akis, ir ji išvydo vandens šulinį; ir ji nuėjo ir pripylė indą vandens ir davė berniukui gerti.'),
  (@b1, 21, 20, 'Ir Dievas buvo su berniuku; ir jis augo ir gyveno dykumoje, ir tapo lankininku.'),
  (@b1, 21, 21, 'Ir jis gyveno Parano dykumoje; ir jo motina ėmė jam žmoną iš Egipto šalies.'),
  (@b1, 21, 22, 'Ir įvyko anuo metu, kad Abimelechas ir jo kariuomenės vyriausiasis vadas Picholas tarė Abraomui, sakydamas: „Dievas yra su tavimi visame, ką tu darai;'),
  (@b1, 21, 23, 'todėl dabar prisiek man čia Dievu, kad nesielgsi melagingai su manimi nei su mano sūnumi, nei su mano sūnaus sūnumi; bet pagal gerumą, kurį tau padariau, taip padarysi man ir kraštui, kuriame esi laikinai apsigyvenęs“.'),
  (@b1, 21, 24, 'Ir Abraomas tarė: „Aš prisieksiu“.'),
  (@b1, 21, 25, 'Ir Abraomas priekaištavo Abimelechui dėl vandens šulinio, kurį Abimelecho tarnai buvo smurtu atėmę.'),
  (@b1, 21, 26, 'Ir Abimelechas tarė: „Aš nežinau, kas tai padarė; nei tu man pranešei, nei aš apie tai girdėjau, bet tik šiandien“.'),
  (@b1, 21, 27, 'Ir Abraomas paėmė avių bei jaučių ir davė juos Abimelechui; ir jie abu sudarė sandorą.'),
  (@b1, 21, 28, 'Ir Abraomas atskirai pasistatė septynias kaimenės avis.'),
  (@b1, 21, 29, 'Ir Abimelechas tarė Abraomui: „Ką reiškia šios septynios avys, kurias atskirai pasistatei?“'),
  (@b1, 21, 30, 'Ir jis tarė: „Nes šias septynias avis imsi iš mano rankos, kad jos būtų man liudijimas, jog aš iškasiau šitą šulinį“.'),
  (@b1, 21, 31, 'Dėl to tą vietą jis pavadino Beer-Šeba; nes ten jie abu prisiekė.'),
  (@b1, 21, 33, 'Ir Abraomas pasodino Beer-Šeboje giraitę ir ten šaukėsi VIEŠPATIES, amžinojo Dievo, vardo.'),
  (@b1, 21, 34, 'Ir Abraomas daug dienų gyveno filistinų šalyje.'),
  (@b1, 21, 32, 'Taip jie sudarė sandorą Beer-Šeboje; paskui Abimelechas ir jo kariuomenės vyriausiasis vadas Picholas pakilo ir jie sugrįžo į filistinų šalį.'),
  (@b1, 22, 1, 'Ir įvyko po šitų dalykų, kad Dievas gundė Abraomą ir jam tarė: „Abraomai“; ir jis tarė: „Štai aš čia“.'),
  (@b1, 22, 2, 'Ir jis tarė: „Imk dabar savo sūnų, savo vienintelį sūnų Izaoką, kurį tu myli, ir eik į Morijos šalį; ir ten jį atnašauk kaip deginamąją atnašą ant vieno iš kalnų, apie kurį aš tau pasakysiu“.'),
  (@b1, 22, 3, 'Ir Abraomas atsikėlė anksti ryte ir pabalnojo savo asilą bei paėmė su savimi du iš savo jaunuolių ir savo sūnų Izaoką ir prisiskaldė malkų deginamajai atnašai, ir pakilo bei ėjo į vietą, apie kurią jam Dievas buvo sakęs.'),
  (@b1, 22, 4, 'Tada, trečiąją dieną Abraomas pakėlė akis ir iš tolo pamatė tą vietą.'),
  (@b1, 22, 5, 'Ir Abraomas tarė savo jaunuoliams: „Pasilikite čia su asilu; o aš ir berniukas eisime ten bei pagarbinsime ir sugrįšime pas jus“.'),
  (@b1, 22, 6, 'Ir Abraomas paėmė deginamosios atnašos malkas ir uždėjo jas ant savo sūnaus Izaoko; o jis pasiėmė į ranką ugnies ir peilį; ir jie abu ėjo kartu.'),
  (@b1, 22, 7, 'Ir Izaokas kalbėjo savo tėvui Abraomui ir tarė: „Mano tėve“; o jis tarė: „Aš čia, mano sūnau“. Ir jis tarė: „Štai ugnis ir malkos; bet kur yra avinėlis deginamajai atnašai?“'),
  (@b1, 22, 8, 'Ir Abraomas tarė: „Dievas sau parūpins avinėlį deginamajai atnašai, mano sūnau“; taip jie abu ėjo kartu.'),
  (@b1, 22, 9, 'Ir jie atėjo į vietą, apie kurią Dievas jam buvo kalbėjęs; ir Abraomas ten pastatė aukurą ir išklojo malkas, ir surišo savo sūnų Izaoką, ir paguldė jį ant aukuro ant malkų.'),
  (@b1, 22, 10, 'Ir Abraomas ištiesė savo ranką ir paėmė peilį, kad papjautų savo sūnų.'),
  (@b1, 22, 11, 'Bet VIEŠPATIES angelas jam pašaukė iš dangaus ir tarė: „Abraomai, Abraomai!“ Ir jis tarė: „Aš čia“.'),
  (@b1, 22, 12, 'Ir jis tarė: „Nedėk savo rankos ant berniuko ir nieko jam nedaryk; nes dabar žinau, kad bijai Dievo, kadangi nesulaikei nuo manęs savo sūnaus, savo vienintelio sūnaus“.'),
  (@b1, 22, 13, 'Ir Abraomas pakėlė savo akis ir pažiūrėjo, ir štai jam už nugaros avinas įstrigęs tankumyne savo ragais; ir Abraomas nuėjo ir paėmė tą aviną, ir jį paaukojo deginamajai atnašai vietoj savo sūnaus.'),
  (@b1, 22, 14, 'Ir Abraomas praminė tą vietą vardu Jehova-Jireh; kaip yra sakoma iki šios dienos: „VIEŠPATIES kalne tai bus matoma“.'),
  (@b1, 22, 15, 'Ir VIEŠPATIES angelas antrą kartą šaukė Abraomui iš dangaus'),
  (@b1, 22, 16, 'ir tarė: „Aš prisiekiau savimi, sako VIEŠPATS, kadangi tai padarei ir nesulaikei savo sūnaus, savo vienintelio sūnaus;'),
  (@b1, 22, 17, 'aš tave laiminte laiminsiu ir dauginte padauginsiu tavo sėklą kaip dangaus žvaigždes ir kaip smėlį, esantį ant jūros kranto; ir tavo sėkla pasisavins savo priešų vartus;'),
  (@b1, 22, 18, 'ir tavo sėkloje bus palaimintos visos žemės tautos; kadangi paklusai mano balsui“.'),
  (@b1, 22, 19, 'Taigi Abraomas sugrįžo pas savo jaunuolius, ir jie pakilo bei ėjo drauge į Beer-Šebą; ir Abraomas gyveno Beer-Šeboje.'),
  (@b1, 22, 20, 'Ir įvyko po šitų dalykų, kad Abraomui buvo pranešta, sakant: „Štai Milka, ji irgi pagimdė vaikų tavo broliui Nahorui:'),
  (@b1, 22, 21, 'jo pirmagimį Ucą, jo brolį Būzą, Aramo tėvą Kemuelį,'),
  (@b1, 22, 22, 'Kesedą, Hazoją, Pildašą, Idlafą ir Betuelį“.'),
  (@b1, 22, 23, 'O Betuelis pagimdė Rebeką; šituos aštuonis Milka pagimdė Abraomo broliui Nahorui.'),
  (@b1, 22, 24, 'O jo sugulovė, kurios vardas Reuma, ji irgi pagimdė: Tebą, Gahamą, Tahašą ir Maaką.'),
  (@b1, 23, 1, 'Ir Sara buvo šimto dvidešimt septynerių metų; šie buvo Saros gyvenimo metai.'),
  (@b1, 23, 2, 'Ir Sara mirė Kirjat-Arboje; tai yra Hebronas Kanaano krašte; ir Abraomas atėjo Saros apraudoti ir jos apverkti.'),
  (@b1, 23, 3, 'Ir Abraomas atsikėlė nuo savo mirusiosios ir kalbėjo Heto sūnums, sakydamas:'),
  (@b1, 23, 4, '„Aš pas jus esu ateivis ir laikinai apsigyvenęs; duokite man nuosavybę laidojimo vietai pas jus, kad aš palaidočiau savo mirusiąją nuo savo akių“.'),
  (@b1, 23, 5, 'Ir Heto vaikai atsakė Abraomui, jam sakydami:'),
  (@b1, 23, 6, '„Pasiklausyk mūsų, mano viešpatie; tu esi galingas kunigaikštis tarp mūsų; mūsų rinktiniuose kapuose palaidok savo mirusiąją; nei vienas iš mūsų nesulaikys nuo tavęs savo kapo, kad savo mirusiąją palaidotum“.'),
  (@b1, 23, 7, 'Ir Abraomas atsistojo ir nusilenkė tos šalies tautai, Heto vaikams.'),
  (@b1, 23, 8, 'Ir jis kalbėjo su jais, sakydamas: „Jei tai jūsų valia, kad aš palaidočiau savo mirusiąją nuo savo akių; paklausykite manęs ir maldaukite už mane Efroną, Coharo sūnų,'),
  (@b1, 23, 9, 'kad jis man duotų Machpelos olą, kurią jis turi, kuri yra jo lauko gale; už tiek pinigų, kiek ji verta jis tegul man ją duoda nuosavybėn laidojimo vietai tarp jūsų“.'),
  (@b1, 23, 10, 'O Efronas gyveno tarp Heto vaikų; ir hetitas Efronas, girdint Heto vaikams, visiems įeinantiems pro jo miesto vartus, atsakė Abraomui, sakydamas:'),
  (@b1, 23, 11, '„Ne, mano viešpatie, pasiklausyk manęs: lauką tau duodu ir jame esančią olą tau duodu; mano tautos sūnų akivaizdoje tau tai duodu; palaidok savo mirusiąją“.'),
  (@b1, 23, 12, 'Ir Abraomas nusilenkė tos šalies tautos akivaizdoje.'),
  (@b1, 23, 13, 'Ir tos šalies tautai girdint jis kalbėjo Efronui, sakydamas: „Jei tu tai duosi, meldžiu tave, pasiklausyk manęs; aš tau duosiu pinigus už lauką; imk juos iš manęs, ir aš ten palaidosiu savo mirusiąją“.'),
  (@b1, 23, 14, 'Ir Efronas atsakė Abraomui, jam sakydamas:'),
  (@b1, 23, 15, '„Mano viešpatie, pasiklausyk manęs; žemė verta keturių šimtų šekelių sidabro; kas tai yra tarp manęs ir tavęs?“ Taigi palaidok savo mirusiąją.'),
  (@b1, 23, 16, 'Ir Abraomas paklausė Efrono; ir Abraomas atsvėrė Efronui sidabrą, kurį jis, Heto sūnums girdint, buvo minėjęs, keturis šimtus šekelių sidabro, pirklių apyvartos pinigus.'),
  (@b1, 23, 17, 'Ir Efrono laukas, esantis Machpeloje, kuri buvo prieš Mamrę, – laukas ir jame esanti ola bei visi lauke esantys medžiai, kurie buvo aplinkui visame plote, – buvo patvirtinti'),
  (@b1, 23, 18, 'Abraomui nuosavybėn, Heto vaikų akivaizdoje, prieš visus, kurie įėjo pro jo miesto vartus.'),
  (@b1, 23, 19, 'Ir po to Abraomas palaidojo savo žmoną Sarą Machpelos lauko oloje prieš Mamrę; kuri yra Hebronas Kanaano šalyje.'),
  (@b1, 23, 20, 'Ir laukas ir jame esanti ola Heto sūnų buvo patvirtinti Abraomui nuosavybėn laidojimo vietai.'),
  (@b1, 24, 1, 'Ir Abraomas buvo senas, gerai palaužtas amžiumi; ir VIEŠPATS palaimino Abraomą visuose dalykuose.'),
  (@b1, 24, 2, 'Ir Abraomas tarė savo namų vyriausiajam tarnui, kuris valdė visa, ką jis turėjo: „Meldžiu tave, dėk savo ranką po mano šlaunimi;'),
  (@b1, 24, 3, 'ir aš prisaikdinsiu tave VIEŠPAČIU, dangaus Dievu ir žemės Dievu, kad neimsi žmonos mano sūnui iš kanaaniečių dukterų, tarp kurių aš gyvenu;'),
  (@b1, 24, 4, 'bet vyksi į mano kraštą ir pas mano gimines ir paimsi žmoną mano sūnui Izaokui“.'),
  (@b1, 24, 5, 'Ir tarnas jam tarė: „Galbūt moteris nenorės sekti paskui mane į šitą šalį; ar aš turėsiu sugrąžinti tavo sūnų į kraštą, iš kurio tu atėjai?“'),
  (@b1, 24, 6, 'Ir Abraomas jam tarė: „Saugokis, kad nesugrąžintum ten mano sūnaus.'),
  (@b1, 24, 7, 'VIEŠPATS, dangaus Dievas, kuris mane paėmė iš mano tėvo namų ir iš mano giminių šalies, kuris man kalbėjo ir kuris man prisiekė, tardamas: ‘Tavo sėklai aš duosiu šitą šalį’; jis siųs savo angelą pirma tavęs, ir iš ten paimsi žmoną mano sūnui.'),
  (@b1, 24, 8, 'O jei moteris nenorės sekti paskui tave, tuomet tu būsi laisvas nuo šitos mano priesaikos; tik mano sūnaus ten nesugrąžink“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 24, 9, 'Ir tarnas padėjo savo ranką po savo šeimininko Abraomo šlaunimi ir jam prisiekė dėl šio dalyko.'),
  (@b1, 24, 10, 'Ir tarnas paėmė dešimt kupranugarių iš savo šeimininko kupranugarių ir išėjo; nes visas jo šeimininko turtas buvo jo rankoje; ir jis pakilo ir nuvyko į Mesopotamiją, į Nahoro miestą.'),
  (@b1, 24, 11, 'Ir jis suklupdė savo kupranugarius už miesto prie vandens šulinio vakaro metu, tuo metu, kai moterys išeina semti vandens.'),
  (@b1, 24, 12, 'Ir jis tarė: „O, VIEŠPATIE, mano šeimininko Abraomo Dieve, meldžiu tave, siųsk man šiandien sėkmę ir parodyk gerumą mano šeimininkui Abraomui.'),
  (@b1, 24, 13, 'Štai aš stoviu čia prie vandens šulinio; o miesto vyrų dukterys išeina semti vandens.'),
  (@b1, 24, 14, 'Ir teįvyksta, kad panelė, kuriai aš sakysiu: ‘Meldžiu tave, nuleisk savo ąsotį, kad atsigerčiau’; ir ji atsakytų: ‘Gerk, aš ir tavo kupranugariams duosiu atsigerti’; ji tebūna ta, kurią esi paskyręs savo tarnui Izaokui; ir iš to žinosiu, kad parodei gerumą mano šeimininkui“.'),
  (@b1, 24, 15, 'Ir įvyko, kad jam dar nebaigus kalbėti, štai išėjo Rebeka, kuri buvo gimusi Abraomo brolio Nahoro žmonos Milkos sūnui Betueliui, su savo ąsočiu ant peties.'),
  (@b1, 24, 16, 'O ta panelė buvo labai gražios išvaizdos, mergelė, ir joks vyras nebuvo jos pažinęs; ir ji nusileido prie šulinio ir pripildė savo ąsotį, ir užlipo aukštyn.'),
  (@b1, 24, 17, 'Ir tarnas nubėgo jos pasitikti ir tarė: „Meldžiu tave, leisk man atsigerti truputį vandens iš tavo ąsočio“.'),
  (@b1, 24, 18, 'O ji tarė: „Gerk, mano viešpatie“; ir ji pasiskubino ir nuleido ąsotį sau ant rankos, ir davė jam gerti.'),
  (@b1, 24, 19, 'Ir baigusi jam duoti atsigerti, ji tarė: „Aš ir tavo kupranugariams pasemsiu vandens, kol jie atsigers“.'),
  (@b1, 24, 20, 'Ir ji pasiskubino ir išpylė savo ąsotį į lovį ir vėl nubėgo prie šulinio semti, ir pasėmė visiems jo kupranugariams.'),
  (@b1, 24, 21, 'O tas žmogus stebėjosi ja ir tylėjo, kad pažinotų, ar VIEŠPATS buvo padaręs jo kelionę sėkmingą, ar ne.'),
  (@b1, 24, 22, 'Ir įvyko, kad kupranugariams atsigėrus, tas žmogus paėmė auksinį auskarą, pusės šekelio svorio, ir dvi apyrankes jos rankoms, dešimties šekelių svorio aukso;'),
  (@b1, 24, 23, 'ir tarė: „Kieno tu duktė? Pasakyk man, meldžiu tave; ar yra tavo tėvo namuose mums vietos pernakvoti?“'),
  (@b1, 24, 24, 'Ir ji jam tarė: „Aš esu duktė Betuelio, Milkos sūnaus, kurį ji pagimdė Nahorui“.'),
  (@b1, 24, 25, 'Ji dar tarė jam: „Mes turime tiek šiaudų, tiek pašaro užtektinai, tiek vietos pernakvoti“.'),
  (@b1, 24, 26, 'Ir tas žmogus nulenkė žemyn galvą ir pagarbino VIEŠPATĮ.'),
  (@b1, 24, 27, 'Ir jis tarė: „Palaimintas tebūna VIEŠPATS, mano šeimininko Abraomo Dievas, kuris nepaliko mano šeimininko be savo gailestingumo ir tiesos; man esant kelyje, VIEŠPATS atvedė mane į mano šeimininko brolių namus“.'),
  (@b1, 24, 28, 'Ir panelė nubėgo bei papasakojo tuos dalykus savo motinos namiškiams.'),
  (@b1, 24, 29, 'Ir Rebeka turėjo brolį, jo vardas buvo Labanas; ir Labanas išbėgo laukan pas tą žmogų prie šulinio.'),
  (@b1, 24, 30, 'Ir įvyko, kad pamatęs auskarą ir apyrankes ant savo sesers rankų ir išgirdęs savo sesers Rebekos žodžius, sakant: „Taip man kalbėjo tas žmogus“; jis atėjo pas tą žmogų; ir štai, šis stovėjo šalia kupranugarių prie šulinio.'),
  (@b1, 24, 31, 'Ir jis tarė: „Įeik, VIEŠPATIES palaimintasis; kodėl stovi lauke? Nes aš paruošiau namus ir vietą kupranugariams“.'),
  (@b1, 24, 32, 'Ir tas žmogus įėjo į namus; o jis nubalnojo jo kupranugarius ir padavė šiaudų bei pašaro kupranugariams ir vandens jo kojoms ir su juo buvusių vyrų kojoms nuplauti.'),
  (@b1, 24, 33, 'Ir prieš jį buvo padėta maisto valgyti; bet jis tarė: „Nevalgysiu iki būsiu išsakęs savo pavedimą“. Ir jis sakė: „Kalbėk“.'),
  (@b1, 24, 34, 'Ir jis tarė: „Aš esu Abraomo tarnas.'),
  (@b1, 24, 35, 'Ir VIEŠPATS didžiai palaimino mano šeimininką; ir jis tapo didis: jis jam yra davęs kaimenių, bandų, sidabro, aukso, tarnų, tarnaičių, kupranugarių ir asilų.'),
  (@b1, 24, 36, 'Ir mano šeimininko žmona Sara, būdama sena, pagimdė sūnų mano šeimininkui; ir jis jam davė viską, ką turi.'),
  (@b1, 24, 37, 'Ir mano šeimininkas mane prisaikdino, tardamas: ‘Neimk mano sūnui žmonos iš dukterų kanaaniečių, kurių šalyje aš gyvenu;'),
  (@b1, 24, 38, 'bet eik į mano tėvo namus, pas mano gimines, ir imk mano sūnui žmoną’.'),
  (@b1, 24, 39, 'Ir aš sakiau savo šeimininkui: ‘Galbūt moteris neseks paskui mane’.'),
  (@b1, 24, 40, 'O jis man tarė: ‘VIEŠPATS, kurio akivaizdoje aš vaikštau, pasiųs su tavimi savo angelą ir padarys tavo kelią sėkmingą; ir tu paimsi mano sūnui žmoną iš mano giminių, iš mano tėvo namų;'),
  (@b1, 24, 41, 'tada būsi laisvas nuo šios mano priesaikos, kai atvyksi pas mano giminę; ir jeigu jie tau jos neduos, tu būsi laisvas nuo mano priesaikos.'),
  (@b1, 24, 42, 'Ir šią dieną aš atėjau prie šulinio ir tariau: ‘O, VIEŠPATIE, mano šeimininko Abraomo Dieve, jei darai sėkmingą mano kelią, kuriuo aš einu;'),
  (@b1, 24, 43, 'štai aš stoviu prie vandens šulinio; ir įvyks, kai mergelė išeis semti vandens ir aš jai tarsiu: „Duok man, meldžiu tave, truputį vandens atsigerti iš savo ąsočio“;'),
  (@b1, 24, 44, 'ir ji man sakys: „Ir tu pats gerk, ir tavo kupranugariams pasemsiu“; ji tebūna ta moteris, kurią VIEŠPATS yra paskyręs mano šeimininko sūnui’.'),
  (@b1, 24, 45, 'Ir man dar nebaigus kalbėti savo širdyje, štai išėjo Rebeka su savo ąsočiu ant peties; ir ji nusileido prie šulinio ir sėmė vandenį; ir aš jai tariau: ‘Duok man, meldžiu tave, atsigerti’.'),
  (@b1, 24, 46, 'Ir ji pasiskubino ir nukėlė nuo savo pečių savo ąsotį ir tarė: ‘Gerk, aš ir tavo kupranugariams duosiu atsigerti’; taigi aš gėriau, o ji ir kupranugarius pagirdė.'),
  (@b1, 24, 47, 'Ir aš jos paklausiau ir tariau: ‘Kieno tu duktė?‘ Ir ji tarė: ‘Duktė Betuelio, Nahoro sūnaus, kurį jam pagimdė Milka’; ir aš uždėjau auskarą ant jos veido ir apyrankes ant jos rankų.'),
  (@b1, 24, 48, 'Ir aš nulenkiau savo galvą ir pagarbinau VIEŠPATĮ, ir palaiminau VIEŠPATĮ, savo šeimininko Abraomo Dievą, kuris mane atvedė teisingu keliu, paimti savo šeimininko brolio dukterį jo sūnui.'),
  (@b1, 24, 49, 'O dabar, jei pasielgsite su mano šeimininku gerai ir ištikimai, man pasakykite; ir jei ne, man pasakykite; kad aš sukčiau į dešinę arba į kairę“.'),
  (@b1, 24, 50, 'Tada Labanas ir Betuelis atsakydami tarė: „Iš VIEŠPATIES išėjo tas dalykas; mes negalime tau kalbėti bloga ar gera.'),
  (@b1, 24, 51, 'Štai Rebeka yra tavo akivaizdoje; imk ją ir eik, ir ji tebūna tavo šeimininko sūnaus žmona, kaip VIEŠPATS yra kalbėjęs“.'),
  (@b1, 24, 52, 'Ir įvyko, kai tik Abraomo tarnas išgirdo jų žodžius, jis pagarbino VIEŠPATĮ nusilenkdamas iki žemės.'),
  (@b1, 24, 53, 'Ir tas tarnas išnešė sidabrinių ir auksinių brangenybių bei drabužių ir davė juos Rebekai; taip pat jis davė vertingų daiktų jos broliui ir jos motinai.'),
  (@b1, 24, 54, 'Ir jie valgė ir gėrė, jis ir su juo esantys vyrai, ir pasiliko visą naktį; ir jie atsikėlė ryte, ir jis tarė: „Išleiskite mane pas mano šeimininką“.'),
  (@b1, 24, 55, 'O jos brolis ir jos motina tarė: „Tepasilieka panelė pas mus keletą dienų, mažiausiai dešimtį; po to ji vyks“.'),
  (@b1, 24, 56, 'Ir jis jiems tarė: „Neužlaikykite manęs, kadangi VIEŠPATS padarė mano kelią sėkmingą; išleiskite mane, kad vykčiau pas savo šeimininką“.'),
  (@b1, 24, 57, 'Ir jie tarė: „Mes pašauksime panelę ir jos burnos paklausime“.'),
  (@b1, 24, 58, 'Ir jie pašaukė Rebeką ir jai tarė: „Ar tu eisi su šiuo žmogumi?“ Ir ji tarė: „Eisiu“.'),
  (@b1, 24, 59, 'Ir jie išsiuntė savo seserį Rebeką bei jos auklę ir Abraomo tarną bei jo vyrus.'),
  (@b1, 24, 60, 'Ir jie palaimino Rebeką ir jai tarė: „Mūsų seserie tu, būki tūkstančių milijonų motina, ir tavo sėkla tepasisavina vartus tų, kurie jos nekenčia“.'),
  (@b1, 24, 61, 'Ir pakilo Rebeka bei jos panelės ir jojo ant kupranugarių ir sekė paskui tą žmogų; ir tas tarnas ėmė Rebeką ir nuėjo sau.'),
  (@b1, 24, 62, 'O Izaokas atėjo nuo Lachaj-Roijo šulinio kelio; nes jis gyveno pietų šalyje.'),
  (@b1, 24, 63, 'Ir Izaokas pavakaryje išėjo ant lauko apmąstyti; ir jis pakėlė savo akis ir išvydo, ir štai ateina kupranugariai.'),
  (@b1, 24, 64, 'Ir Rebeka pakėlė savo akis ir pamačiusi Izaoką nulipo nuo kupranugario.'),
  (@b1, 24, 65, 'Nes ji buvo sakiusi tam tarnui: „Kas yra tas žmogus, kuris eina per lauką mūsų pasitikti?“ O tarnas buvo taręs: „Tai mano šeimininkas“; todėl ji paėmė šydą ir užsidengė.'),
  (@b1, 24, 66, 'Ir tarnas papasakojo Izaokui visus dalykus, kuriuos jis buvo atlikęs.'),
  (@b1, 24, 67, 'Ir Izaokas ją įvedė į savo motinos Saros palapinę ir ėmė Rebeką, ir ji tapo jo žmona; ir jis ją mylėjo; ir Izaokas buvo paguostas po savo motinos mirties.'),
  (@b1, 25, 1, 'Po to Abraomas vėl ėmė žmoną, o jos vardas buvo Ketūra.'),
  (@b1, 25, 2, 'Ir ji jam pagimdė Zimraną, Jokšaną, Medaną, Midjaną, Išbaką ir Šuachą.'),
  (@b1, 25, 3, 'Ir Jokšanas pagimdė Šebą ir Dedaną. Ir Dedano sūnūs buvo ašūriečiai, letušai ir leumai.'),
  (@b1, 25, 4, 'Ir Midjano sūnūs buvo Efa, Eferas, Hanochas, Abida ir Eldaa. Visi šitie buvo Ketūros vaikai.'),
  (@b1, 25, 5, 'Ir Abraomas atidavė visa, ką turėjo, Izaokui.'),
  (@b1, 25, 6, 'Bet sūnums sugulovių, kurias Abraomas turėjo, Abraomas davė dovanų ir dar būdamas gyvas juos išsiuntė nuo savo sūnaus Izaoko į rytus, į rytų šalį.'),
  (@b1, 25, 7, 'Ir šios yra Abraomo nugyvento gyvenimo metų dienos: šimtas septyniasdešimt penki metai.'),
  (@b1, 25, 8, 'Tada Abraomas atidavė dvasią ir mirė žiloje senatvėje, senis, pasisotinęs metais, ir buvo surinktas prie savo tautos.'),
  (@b1, 25, 9, 'Ir jį palaidojo jo sūnūs Izaokas ir Išmaelis Machpelos oloje, Coharo sūnaus Efrono, hetito, lauke, esančiame prieš Mamrę;'),
  (@b1, 25, 10, 'tame lauke, kurį Abraomas nusipirko iš Heto sūnų; ten buvo palaidotas Abraomas ir jo žmona Sara.'),
  (@b1, 25, 11, 'Ir įvyko, po Abraomo mirties, kad Dievas palaimino jo sūnų Izaoką; ir Izaokas gyveno prie Lachai-Roijo šulinio.'),
  (@b1, 25, 12, 'Na, o šita yra genealogija Išmaelio, Abraomo sūnaus, kurį egiptietė Hagara, Saros tarnaitė, pagimdė Abraomui;'),
  (@b1, 25, 13, 'ir tie yra vardai Išmaelio sūnų, pagal jų vardus, pagal jų genealogiją: Išmaelio pirmagimis Nebajotas; Kedaras, Adbeelis, Mibsamas,'),
  (@b1, 25, 14, 'Mišma, Dūma, Masa,'),
  (@b1, 25, 15, 'Hadaras ir Tema, Jetūras, Nafišas ir Kedma;'),
  (@b1, 25, 16, 'tie yra Išmaelio sūnūs, ir tie yra jų vardai pagal jų miestelius ir pagal jų pilis; dvylika kunigaikščių pagal jų tautas.'),
  (@b1, 25, 17, 'Ir šitie yra Išmaelio gyvenimo metai: šimtas trisdešimt septyneri metai; ir jis atidavė dvasią bei mirė; ir buvo surinktas prie savo tautos.'),
  (@b1, 25, 18, 'Ir jie gyveno nuo Havilos iki Šūro, esančio prieš Egiptą, einant link Asirijos; ir jis mirė visų savo brolių akivaizdoje.'),
  (@b1, 25, 19, 'Ir šita yra Abraomo sūnaus Izaoko genealogija: Abraomas pagimdė Izaoką;'),
  (@b1, 25, 20, 'o Izaokas buvo keturiasdešimties metų, kai jis ėmė į žmonas Rebeką, siro Betuelio iš Padan-Aramo dukterį, siro Labano seserį.'),
  (@b1, 25, 21, 'Ir Izaokas maldavo VIEŠPATĮ už savo žmoną, nes ji buvo nevaisinga; ir VIEŠPATS davėsi jo išmeldžiamas, ir jo žmona Rebeka pastojo.'),
  (@b1, 25, 22, 'Ir vaikai jos viduje grūmėsi; ir ji tarė: „Jei taip yra, kodėl esu taip?“ Ir ji nuėjo VIEŠPATIES pasiklausti.'),
  (@b1, 25, 23, 'Ir VIEŠPATS jai tarė: „Dvi tautos yra tavo įsčiose, ir dvi skirtingos tautos persiskirs iš tavo vidurių; ir viena tauta bus galingesnė už kitą tautą; ir vyresnysis tarnaus jaunesniajam“.'),
  (@b1, 25, 24, 'Ir kai išsipildė jos dienos, kad gimdytų, štai buvo jos įsčiose dvyniai.'),
  (@b1, 25, 25, 'Ir pirmasis išėjo raudonas, visas kaip plaukuotas drabužis; ir jie praminė jį vardu Ezavas.'),
  (@b1, 25, 26, 'O paskui išėjo jo brolis, ir jo ranka nutvėrė Ezavo kulnį; ir jis buvo pramintas vardu Jokūbas; ir Izaokas buvo šešiasdešimties metų, kai ji juos pagimdė.'),
  (@b1, 25, 27, 'Ir berniukai augo; ir Ezavas buvo sumanus medžiotojas, lauko vyras; o Jokūbas buvo paprastas žmogus, gyvenąs palapinėse.'),
  (@b1, 25, 28, 'Ir Izaokas mylėjo Ezavą, nes jis valgė iš jo žvėrienos; bet Rebeka mylėjo Jokūbą.'),
  (@b1, 25, 29, 'Ir Jokūbas virė viralą; o Ezavas parėjo nuo lauko ir jis buvo nusilpęs;'),
  (@b1, 25, 30, 'ir Ezavas tarė Jokūbui: „Pavalgydink mane, meldžiu tave, šiuo raudonu viralu; nes aš nusilpęs“; todėl jį pavadino vardu Edomas.'),
  (@b1, 25, 31, 'Ir Jokūbas tarė: „Parduok man šią dieną savo pirmagimystės teisę“.'),
  (@b1, 25, 32, 'Ir Ezavas tarė: „Štai aš prie mirties ribos; ir kokią gi naudą man duos ši pirmagimystės teisė?“'),
  (@b1, 25, 33, 'Ir Jokūbas tarė: „Prisiek man šią dieną“; ir jis jam prisiekė; ir jis pardavė Jokūbui savo pirmagimystės teisę.'),
  (@b1, 25, 34, 'Tada Jokūbas davė Ezavui duonos ir lęšių viralo; ir šis valgė bei gėrė ir atsikėlė bei nuėjo sau; taip Ezavas paniekino savo pirmagimystės teisę.'),
  (@b1, 26, 1, 'Ir šalyje buvo badas, neskaitant ano, pirmo bado, kuris buvo Abraomo dienomis. Ir Izaokas nuvyko pas filistinų karalių Abimelechą į Gerarą.'),
  (@b1, 26, 2, 'Ir VIEŠPATS jam pasirodė ir tarė: „Nesileisk į Egiptą; gyvenk šalyje, apie kurią aš tau pasakysiu;'),
  (@b1, 26, 3, 'laikinai apsigyvenk šioje šalyje, o aš būsiu su tavimi ir laiminsiu tave; nes tau ir tavo sėklai aš duosiu visas šias šalis, ir aš įvykdysiu priesaiką, kurią prisiekiau tavo tėvui Abraomui;'),
  (@b1, 26, 4, 'aš padauginsiu tavo sėklą kaip dangaus žvaigždes ir duosiu tavo sėklai visas šias šalis; ir tavo sėkloje bus palaimintos visos žemės tautos;'),
  (@b1, 26, 5, 'kadangi Abraomas pakluso mano balsui ir laikėsi mano įpareigojimo, mano įsakymų, mano įstatų ir mano įstatymų“.'),
  (@b1, 26, 6, 'Ir Izaokas apsigyveno Gerare;'),
  (@b1, 26, 7, 'ir tos vietos vyrai klausinėjo jį apie jo žmoną; ir jis sakė: „Ji mano sesuo“; nes jis bijojo sakyti: „Ji mano žmona; kad, – jis tarė, – tos vietos vyrai manęs nenužudytų dėl Rebekos, nes ji buvo graži pažiūrėti“.'),
  (@b1, 26, 8, 'Ir įvyko, jam ten būnant ilgą laiką, kad filistinų karalius Abimelechas pažiūrėjo pro langą ir pamatė, ir štai Izaokas žaidė su savo žmona Rebeka.'),
  (@b1, 26, 9, 'Ir Abimelechas pašaukė Izaoką ir tarė: „Štai tikrai ji tavo žmona; o kaip tu sakei: ‘Ji mano sesuo‘?“ Ir Izaokas jam tarė: „Kadangi aš sakiau: ‘Kad aš dėl jos nemirčiau’“.'),
  (@b1, 26, 10, 'Ir Abimelechas tarė: „Kas tai yra, ką tu mums padarei? Vienas iš tautos lengvai būtų galėjęs sugulti su tavo žmona, ir tu būtum užtraukęs ant mūsų kaltę“.'),
  (@b1, 26, 11, 'Ir Abimelechas įpareigojo visą savo tautą, sakydamas: „Kas palies šitą vyrą ar jo žmoną, tikrai bus nužudytas“.'),
  (@b1, 26, 12, 'Tada Izaokas sėjo toje šalyje ir gavo tais metais šimteriopai; ir VIEŠPATS jį laimino.'),
  (@b1, 26, 13, 'Ir šis žmogus tapo didis ir, kuo toliau, tuo labiau augo, kol pasidarė labai didis;'),
  (@b1, 26, 14, 'nes jis turėjo kaimenių nuosavybę bei bandų nuosavybę ir didelę gausybę tarnų; ir filistinai jam pavydėjo.'),
  (@b1, 26, 15, 'Nes visus šulinius, kuriuos jo tėvo tarnai buvo iškasę jo tėvo Abraomo dienomis, filistinai užkimšo ir pripylė juos žemių.'),
  (@b1, 26, 16, 'Ir Abimelechas tarė Izaokui: „Eik nuo mūsų; nes tu daug galingesnis už mus“.'),
  (@b1, 26, 17, 'Ir Izaokas išvyko iš ten ir pasistatė savo palapinę Geraro slėnyje ir ten gyveno.'),
  (@b1, 26, 18, 'Ir Izaokas vėl iškasė vandens šulinius, kuriuos jie buvo iškasę jo tėvo Abraomo dienomis; nes filistinai buvo juos užkimšę po Abraomo mirties; ir jis juos pavadino vardais, pagal tuos vardus, kuriais juos buvo pavadinęs jo tėvas.'),
  (@b1, 26, 19, 'Ir Izaoko tarnai kasė slėnyje ir ten rado versminio vandens šulinį.'),
  (@b1, 26, 20, 'Ir Geraro kerdžiai barėsi su Izaoko kerdžiais, sakydami: „Tas vanduo mūsų“; ir jis praminė tą šulinį vardu Esekas; nes jie barėsi su juo.'),
  (@b1, 26, 21, 'Ir jie iškasė kitą šulinį ir dėl jo taip pat susibarė; ir jis jį praminė vardu Sitna.'),
  (@b1, 26, 22, 'Ir jis pasitraukė iš ten ir iškasė kitą šulinį; o dėl šito jie nesibarė; ir jis jį praminė vardu Rehobotas; ir jis tarė: „Nes dabar VIEŠPATS mums padarė vietos ir mes būsime vaisingi toje šalyje“.'),
  (@b1, 26, 23, 'Ir iš ten jis ėjo aukštyn į Beer-Šebą.'),
  (@b1, 26, 24, 'Ir tą pačią naktį jam pasirodė VIEŠPATS ir tarė: „Aš esu tavo tėvo Abraomo Dievas; nebijok, nes aš esu su tavimi ir tave palaiminsiu, ir padauginsiu tavo sėklą dėl mano tarno Abraomo“.'),
  (@b1, 26, 25, 'Ir jis ten pastatė aukurą ir šaukėsi VIEŠPATIES vardo, ir ten pasistatė savo palapinę; ir Izaoko tarnai ten kasė šulinį.'),
  (@b1, 26, 26, 'Tuomet pas jį nuvyko Abimelechas iš Geraro ir Ahuzatas, vienas iš jo draugų, ir jo kariuomenės vyriausiasis vadas Picholas.'),
  (@b1, 26, 27, 'Ir Izaokas jiems tarė: „Ko atėjote pas mane? Jūs juk nekenčiate manęs ir mane išsiuntėte nuo savęs“.'),
  (@b1, 26, 28, 'Ir jie tarė: „Mes aiškiai matėme, kad VIEŠPATS yra su tavimi; ir mes tarėme: ‘Tebūna dabar tarp mūsų priesaika, tarp mūsų ir tavęs, ir sudarykime sandorą su tavimi;'),
  (@b1, 26, 29, 'kad tu mums nedarysi žalos, kaip mes tavęs nelietėme ir kaip mes tau nieko nedarėme, o tik gera, ir ramybėje tave išleidome’; tu dabar esi VIEŠPATIES palaimintasis“.'),
  (@b1, 26, 30, 'Ir jis iškėlė jiems puotą, ir jie valgė bei gėrė.'),
  (@b1, 26, 31, 'Ir jie atsikėlė anksti ryte ir prisiekė vienas kitam; ir Izaokas juos išleido, ir jie nuėjo nuo jo ramybėje.'),
  (@b1, 26, 32, 'Ir įvyko tą pačią dieną, kad Izaoko tarnai atėjo ir jam pasakė apie šulinį, kurį jie buvo iškasę, ir jam tarė: „Mes radome vandens“.'),
  (@b1, 26, 33, 'Ir jis jį pavadino Šeba; todėl to miesto vardas ligi šios dienos yra Beer-Šeba.'),
  (@b1, 26, 34, 'Ir Ezavas buvo keturiasdešimties metų, kai jis ėmė į žmonas hetito Beerio dukterį Juditą ir hetito Elono dukterį Basematą;'),
  (@b1, 26, 35, 'kurios Izaokui ir Rebekai buvo dvasios sielvartas.'),
  (@b1, 27, 1, 'Ir įvyko, kad, kai Izaokas buvo senas ir jo akys buvo aptemusios, jog jis nebegalėjo matyti, jis pasišaukė savo vyresnįjį sūnų Ezavą ir jam tarė: „Mano sūnau“; o jis jam tarė: „Štai, aš čia“.'),
  (@b1, 27, 2, 'Ir jis tarė: „Štai, jau esu senas, nežinau savo mirties dienos;'),
  (@b1, 27, 3, 'taigi dabar, meldžiu tave, imk savo ginklus, savo strėlinę bei lanką ir išėjęs ant lauko sumedžiok man žvėrienos;'),
  (@b1, 27, 4, 'ir paruošk man skanų valgį, kokį aš mėgstu, ir atnešk man jį, kad aš valgyčiau; kad mano siela tave palaimintų prieš man mirštant“.'),
  (@b1, 27, 5, 'O Rebeka girdėjo, kai Izaokas kalbėjo savo sūnui Ezavui. Ir Ezavas nuėjo ant lauko žvėrienos medžioti ir jos parnešti.'),
  (@b1, 27, 6, 'Ir Rebeka kalbėjo savo sūnui Jokūbui, sakydama: „Štai aš išgirdau tavo tėvą kalbant tavo broliui Ezavui, sakant:'),
  (@b1, 27, 7, '‘Parnešk man žvėrienos ir paruošk man skanų valgį, kad aš valgyčiau ir prieš savo mirtį tave palaiminčiau VIEŠPATIES akivaizdoje’.'),
  (@b1, 27, 8, 'Taigi dabar, mano sūnau, paklusk mano balsui tame, ką tau liepsiu.'),
  (@b1, 27, 9, 'Eik dabar į kaimenę ir iš ten man atnešk du gerus ožiukus; o aš paruošiu iš jų tavo tėvui skanų valgį, kokį jis mėgsta;'),
  (@b1, 27, 10, 'ir tu jį nunešk savo tėvui, kad jis valgytų ir kad prieš savo mirtį tave palaimintų“.'),
  (@b1, 27, 11, 'O Jokūbas tarė savo motinai Rebekai: „Štai mano brolis Ezavas yra plaukuotas žmogus, o aš glotnus;'),
  (@b1, 27, 12, 'rasi mano tėvas mane pačiupinės, ir aš jam pasirodysiu kaip apgavikas; ir aš užsitrauksiu ant savęs prakeikimą, o ne palaiminimą“.'),
  (@b1, 27, 13, 'Ir jo motina jam tarė: „Ant manęs tebūna tavo prakeikimas, mano sūnau; tik paklusk mano balsui ir eik, atnešk man juos“.'),
  (@b1, 27, 14, 'Ir jis ėjo ir atgabeno bei atnešė juos savo motinai; o jo motina paruošė skanų valgį, kokį mėgo jo tėvas.'),
  (@b1, 27, 15, 'Ir Rebeka paėmė savo vyresniojo sūnaus Ezavo gražius drabužius, kurie buvo pas ją namuose, ir apvilko jais savo jaunesnįjį sūnų Jokūbą;'),
  (@b1, 27, 16, 'ir ožiukų kailiais apvilko jo rankas ir jo kaklo glotnumą;'),
  (@b1, 27, 17, 'ir padavė skanųjį valgį ir duonos, kuriuos buvo paruošusi, į savo sūnaus Jokūbo ranką.'),
  (@b1, 27, 18, 'Ir jis atėjo pas savo tėvą ir tarė: „Mano tėve“; ir jis tarė: „Aš čia“; „kas tu esi, mano sūnau?“'),
  (@b1, 27, 19, 'Ir Jokūbas tarė savo tėvui: „Aš Ezavas, tavo pirmagimis; aš padariau pagal tai, kaip man liepei; kelkis, meldžiu tave, atsisėsk ir valgyk mano žvėrienos, kad tavo siela mane palaimintų“.'),
  (@b1, 27, 20, 'Ir Izaokas tarė savo sūnui: „Kaipgi yra, mano sūnau, kad taip greitai tai radai?“ Ir jis tarė: „Nes VIEŠPATS, tavo Dievas, man tai atnešė“.'),
  (@b1, 27, 21, 'Ir Izaokas tarė Jokūbui: „Prisiartink, meldžiu tave, kad aš apčiupinėčiau tave, mano sūnau, ar tu esi tas pats mano sūnus Ezavas, ar ne“.'),
  (@b1, 27, 22, 'Ir Jokūbas prisiartino prie savo tėvo Izaoko; o tas jį apčiupinėjo ir tarė: „Balsas – Jokūbo balsas, bet rankos – Ezavo rankos“.'),
  (@b1, 27, 23, 'Ir jis neatpažino jo, nes jo rankos buvo plaukuotos, kaip jo brolio Ezavo rankos; taigi jis palaimino jį.'),
  (@b1, 27, 24, 'Ir jis tarė: „Ar tu esi tas pats mano sūnus Ezavas?“ Ir jis tarė: „Aš esu“.'),
  (@b1, 27, 25, 'Ir jis tarė: „Atnešk tai prie manęs ir aš valgysiu savo sūnaus žvėrienos, kad tave palaimintų mano siela“. Ir jis atnešė tai prie jo, ir jis valgė; ir jis atnešė jam vyno, ir jis gėrė.'),
  (@b1, 27, 26, 'Ir jo tėvas Izaokas jam tarė: „Prieik dabar ir pabučiuok mane, mano sūnau“.'),
  (@b1, 27, 27, 'Ir jis priartėjo ir pabučiavo jį; ir jis pauostė jo drabužių kvapą ir palaimino jį bei tarė: „Štai mano sūnaus kvapas kaip kvapas lauko, kurį palaimino VIEŠPATS;'),
  (@b1, 27, 28, 'todėl Dievas tegul tau duoda iš dangaus rasos ir žemės riebumo, ir apsčiai javų bei vyno;'),
  (@b1, 27, 29, 'tegul tarnauja tau tautos ir tenusilenkia tau tautybės; būk viešpats savo broliams, ir tenusilenkia tau tavo motinos sūnūs; kas tave keikia, tebūna prakeiktas, o kas tave laimina, tebūna palaimintas“.'),
  (@b1, 27, 30, 'Ir įvyko, kad, kai tik Izaokas buvo baigęs laiminti Jokūbą ir Jokūbas vos buvo išėjęs nuo savo tėvo Izaoko akivaizdos, jo brolis Ezavas atėjo iš savo medžioklės.'),
  (@b1, 27, 31, 'Ir jis irgi pagamino skanų valgį ir atnešė tai savo tėvui, ir tarė savo tėvui: „Tegul mano tėvas atsikelia ir valgo savo sūnaus žvėrienos, kad mane palaimintų tavo siela“.'),
  (@b1, 27, 32, 'Ir jo tėvas Izaokas jam tarė: „Kas tu esi?“ Ir jis tarė: „Aš esu tavo sūnus, tavo pirmagimis Ezavas“.'),
  (@b1, 27, 33, 'Ir Izaokas labai smarkiai drebėjo ir tarė: „Kas? Kur yra tas, kuris sumedžiojo žvėrienos ir man jos atnešė, ir aš, prieš tau ateinant, visko valgiau ir jį palaiminau? Taip, ir jis bus palaimintas“.'),
  (@b1, 27, 34, 'Ir kai Ezavas išgirdo savo tėvo žodžius, jis šaukė stipriu ir nepaprastai karčiu šauksmu ir tarė savo tėvui: „Palaimink mane, taip pat ir mane, o mano tėve!“'),
  (@b1, 27, 35, 'O jis tarė: „Tavo brolis atėjo su klasta ir atėmė tavo palaiminimą“.'),
  (@b1, 27, 36, 'Ir jis tarė: „Argi ne teisingai jis pramintas Jokūbu? Nes tuos du kartus jis užėmė mano vietą; jis atėmė mano pirmagimystę; ir štai dabar jis atėmė mano palaiminimą“. Ir jis tarė: „Ar tu man neužlaikei jokio palaiminimo?“'),
  (@b1, 27, 37, 'Ir Izaokas atsakydamas tarė Ezavui: „Štai aš jį padariau tavo viešpačiu ir visus jo brolius jam daviau į tarnus; ir javais bei vynu jį pastiprinau; ir ką gi aš dabar darysiu tau, mano sūnau?“'),
  (@b1, 27, 38, 'Ir Ezavas tarė savo tėvui: „Ar tik vieną turi palaiminimą, mano tėve? Palaimink mane, taip pat ir mane, o mano tėve“. Ir Ezavas pakėlęs savo balsą verkė.'),
  (@b1, 27, 39, 'Ir jo tėvas Izaokas atsakydamas jam tarė: „Štai tavo gyvenimas bus riebumas iš žemės ir iš dangaus rasõs iš aukštai;'),
  (@b1, 27, 40, 'ir savo kalaviju gyvensi ir savo broliui tarnausi; ir įvyks, kai tu viešpatausi, tada nutrauksi jo jungą nuo savo kaklo“.'),
  (@b1, 27, 41, 'Ir Ezavas nekentė Jokūbo dėl palaiminimo, kuriuo jo tėvas jį palaimino; ir Ezavas tarė savo širdyje: „Čia pat yra gedėjimo dėl mano tėvo dienos; tada aš užmušiu savo brolį Jokūbą“.'),
  (@b1, 27, 42, 'Ir Rebekai buvo pranešti šie jos vyresniojo sūnaus Ezavo žodžiai; ir ji pasiuntė ir pasišaukė savo jaunesnįjį sūnų Jokūbą ir jam tarė: „Štai tavo brolis Ezavas dėl tavęs guodžiasi, ketindamas tave nužudyti.'),
  (@b1, 27, 43, 'Taigi dabar, mano sūnau, paklusk mano balsui; ir kelkis, bėk pas mano brolį Labaną į Haraną;'),
  (@b1, 27, 44, 'ir keletą dienų pasilik pas jį, kol nusisuks tavo brolio įtūžis;'),
  (@b1, 27, 45, 'kol tavo brolio pyktis nusigręš nuo tavęs, ir jis pamirš, ką esi jam padaręs; tada aš nusiųsiu ir tave iš ten pargabensiu; kodėl aš turėčiau ir jūsų abiejų netekti vieną dieną?“'),
  (@b1, 27, 46, 'Ir Rebeka tarė Izaokui: „Aš nuvargau nuo savo gyvenimo dėl Heto dukterų; jei Jokūbas ims žmoną iš Heto dukterų, tokią, kaip šitos, esančios iš tos šalies dukterų, ką gero man beduos mano gyvenimas?“'),
  (@b1, 28, 1, 'Ir Izaokas pašaukė Jokūbą, jį palaimino ir įpareigojo jį jam sakydamas: „Neimk žmonos iš Kanaano dukterų.'),
  (@b1, 28, 2, 'Kelkis, vyk į Padan-Aramą, į tavo motinos tėvo Betuelio namus; ir iš ten imk sau žmoną iš tavo motinos brolio Labano dukterų.'),
  (@b1, 28, 3, 'Ir Visagalis Dievas tepalaimina tave, tepadaro tave vaisingą ir tepadaugina tave, kad tu būtum tautų daugybė;'),
  (@b1, 28, 4, 'ir teduoda tau Abraomo palaiminimą, tau ir tavo sėklai su tavimi; kad paveldėtum šalį, kurioje esi ateivis, kurią Dievas davė Abraomui“.'),
  (@b1, 28, 5, 'Ir Izaokas išleido Jokūbą; ir jis vyko į Padan-Aramą pas Labaną, siro Betuelio sūnų, Jokūbo ir Ezavo motinos Rebekos brolį.'),
  (@b1, 28, 6, 'Kai Ezavas pamatė, kad Izaokas palaimino Jokūbą ir jį išleido į Padan-Aramą žmonos iš ten imti; ir kad jį laimindamas jį įpareigojo, sakydamas: „Neimk žmonos iš Kanaano dukterų“;'),
  (@b1, 28, 7, 'ir kad Jokūbas paklausė savo tėvo bei motinos ir buvo išvykęs į Padan-Aramą;'),
  (@b1, 28, 8, 'ir Ezavas matydamas, kad Kanaano dukterys nepatiko jo tėvui Izaokui,'),
  (@b1, 28, 9, 'tada Ezavas nuėjo pas Išmaelį ir prie savo turimųjų žmonų ėmė Mahalatą, Abraomo sūnaus Išmaelio dukterį, Nebajoto seserį, kad būtų jo žmona.'),
  (@b1, 28, 10, 'O Jokūbas išvyko iš Beer-Šebos ir vyko Harano link.'),
  (@b1, 28, 11, 'Ir jis užtiko vieną vietą ir ten pasiliko visą naktį, nes saulė buvo nusileidusi; ir jis paėmė iš tos vietos akmenų ir pasidėjo juos savo priegalviui, ir atsigulė toje vietoje miegoti.'),
  (@b1, 28, 12, 'Ir jis sapnavo, ir štai kopėčios pastatytos ant žemės, o jų viršus siekė dangų; ir štai Dievo angelai jomis kilo ir leidosi.'),
  (@b1, 28, 13, 'Ir štai VIEŠPATS stovėjo virš jų ir tarė: „Aš esu VIEŠPATS, tavo tėvo Abraomo Dievas ir Izaoko Dievas; žemę, ant kurios guli, duosiu tau ir tavo sėklai;'),
  (@b1, 28, 14, 'ir tavo sėkla bus kaip žemės dulkės, ir tu išsiplėsi į vakarus, į rytus, į šiaurę ir į pietus; ir tavyje bei tavo sėkloje bus palaimintos visos žemės šeimos.'),
  (@b1, 28, 15, 'Ir štai aš esu su tavimi ir tave saugosiu visur, kur eisi, ir tave sugrąžinsiu į šitą šalį; nes aš nepaliksiu tavęs, kol padarysiu tai, apie ką esu tau kalbėjęs“.'),
  (@b1, 28, 16, 'Ir Jokūbas pabudo iš savo miego ir tarė: „Tikrai VIEŠPATS yra šioje vietoje; o aš to nežinojau“.'),
  (@b1, 28, 17, 'Ir jis bijojo ir tarė: „Kokia bauginanti ši vieta! Tai ne kas kita, kaip tik Dievo namai, ir tai yra dangaus vartai“.'),
  (@b1, 28, 18, 'Ir Jokūbas atsikėlė ankstų rytą ir paėmė akmenį, kurį buvo pasidėjęs savo priegalviui, ir pastatė jį kaip stulpą, ir užpylė aliejaus ant jo viršaus.'),
  (@b1, 28, 19, 'Ir jis praminė tą vietą vardu Bet-Elis; tačiau pirma tas miestas vadinosi vardu Lūzas.'),
  (@b1, 28, 20, 'Ir Jokūbas davė įžadą, tardamas: „Jei Dievas bus su manimi ir mane saugos šiame kelyje, kuriuo einu, ir duos man duonos valgyti ir drabužių vilkėti,'),
  (@b1, 28, 21, 'kad aš ramybėje sugrįžčiau į savo tėvo namus; tada VIEŠPATS bus mano Dievas;'),
  (@b1, 28, 22, 'ir šitas akmuo, kurį pastačiau kaip stulpą, bus Dievo namai; ir iš viso, ką tu man duosi, aš tikrai tau duosiu dešimtinę“.'),
  (@b1, 29, 1, 'Tada Jokūbas leidosi savo kelionėn ir atvyko į rytų tautos šalį.'),
  (@b1, 29, 2, 'Ir jis pažiūrėjo, ir štai šulinys lauke, ir štai ten buvo trys kaimenės avių, sugulusių prie jo; nes iš to šulinio jie girdė kaimenes; ir didelis akmuo buvo ant šulinio angos.'),
  (@b1, 29, 3, 'Ir ten buvo susirinkusios visos kaimenės; ir jie nuritino akmenį nuo šulinio angos ir pagirdė avis, ir vėl uždėjo akmenį ant šulinio angos į jo vietą.'),
  (@b1, 29, 4, 'Ir Jokūbas jiems tarė: „Mano broliai, iš kur jūs esate?“ Ir jie tarė: „Mes iš Harano“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 29, 5, 'Ir jis jiems tarė: „Ar pažįstate Labaną, Nahoro sūnų?“ Ir jie tarė: „Pažįstame jį“.'),
  (@b1, 29, 6, 'Ir jis jiems tarė: „Ar jis sveikas?“ Ir jie tarė: „Sveikas“; ir štai jo duktė Rachelė ateina su avimis.'),
  (@b1, 29, 7, 'Ir jis tarė: „Štai dar daug dienos, ir dar ne metas, kad būtų suvaryti galvijai; pagirdykite avis ir eikite, ganykite jas“.'),
  (@b1, 29, 8, 'O jie tarė: „Mes negalime, iki susirinks visos kaimenės, ir jie nuritins akmenį nuo šulinio angos; tada mes pagirdysime avis“.'),
  (@b1, 29, 9, 'Ir jam dar bekalbant su jais, Rachelė atėjo su savo tėvo avimis; nes ji saugojo jas.'),
  (@b1, 29, 10, 'Ir įvyko, kai Jokūbas pamatė Rachelę, savo motinos brolio Labano dukterį, ir savo motinos brolio Labano avis, tada Jokūbas priėjo, nurito akmenį nuo šulinio angos ir pagirdė savo motinos brolio Labano kaimenę.'),
  (@b1, 29, 11, 'Ir Jokūbas pabučiavo Rachelę ir pakėlęs savo balsą verkė.'),
  (@b1, 29, 12, 'Ir Jokūbas pasakė Rachelei, kad jis esąs jos tėvo brolis, kad jis esąs Rebekos sūnus; ir ji nubėgo ir pasakė savo tėvui.'),
  (@b1, 29, 13, 'Ir įvyko, kai Labanas išgirdo žinią apie savo sesers sūnų Jokūbą, jis bėgo jo pasitikti ir jį apkabino, ir pabučiavo, ir nuvedė jį į savo namus. Ir jis papasakojo Labanui visus tuos dalykus.'),
  (@b1, 29, 14, 'Ir Labanas jam tarė: „Tikrai tu esi mano kaulas ir mano kūnas“. Ir jis pasiliko pas jį mėnesiui.'),
  (@b1, 29, 15, 'Ir Labanas tarė Jokūbui: „Kadangi tu esi mano brolis, argi turėtum man už dyką tarnauti? Pasakyk man, kokia turėtų būti tavo alga?“'),
  (@b1, 29, 16, 'Ir Labanas turėjo dvi dukteris: vyresnioji buvo vardu Lėja, o jaunesnioji vardu Rachelė.'),
  (@b1, 29, 17, 'Lėja buvo silpnų akių; o Rachelė buvo graži ir dailios išvaizdos.'),
  (@b1, 29, 18, 'Ir Jokūbas pamilo Rachelę; ir tarė: „Aš tau tarnausiu septynerius metus už tavo jaunesniąją dukterį Rachelę“.'),
  (@b1, 29, 19, 'Ir Labanas tarė: „Geriau kad duočiau ją tau, negu kad duočiau ją kitam vyrui; pasilik pas mane“.'),
  (@b1, 29, 20, 'Ir Jokūbas tarnavo už Rachelę septynerius metus; ir jie jam pasirodė kaip kelios dienos, dėl meilės, kuria jis ją mylėjo.'),
  (@b1, 29, 21, 'Ir Jokūbas tarė Labanui: „Duok man mano žmoną, nes išsipildė mano dienos, kad įeičiau pas ją“.'),
  (@b1, 29, 22, 'Ir Labanas surinko visus tos vietovės žmones ir iškėlė puotą.'),
  (@b1, 29, 23, 'Ir įvyko vakare, kad jis ėmė savo dukterį Lėją ir ją atvedė pas jį; ir jis įėjo pas ją.'),
  (@b1, 29, 24, 'Ir Labanas davė savo dukteriai Lėjai savo tarnaitę Zilpą į tarnaites.'),
  (@b1, 29, 25, 'Ir įvyko ryte, štai, tai buvo Lėja; ir jis tarė Labanui: „Kas tai yra, ką man padarei? Ar ne už Rachelę tarnavau pas tave? Tad kodėl mane apgavai?“'),
  (@b1, 29, 26, 'O Labanas tarė: „Mūsų šalyje taip nedaroma, kad atiduotų jaunesniąją pirmiau pirmagimės.'),
  (@b1, 29, 27, 'Išpildyk jos savaitę, ir mes tau duosime ir šitą, už tarnystę, kuria tarnausi pas mane dar kitus septynerius metus“.'),
  (@b1, 29, 28, 'Ir Jokūbas taip padarė ir išpildė jos savaitę; ir jis jam davė taip pat savo dukterį Rachelę į žmonas.'),
  (@b1, 29, 29, 'Ir Labanas davė savo dukteriai Rachelei savo tarnaitę Bilhą būti jos tarnaite.'),
  (@b1, 29, 30, 'Ir jis įėjo ir pas Rachelę, ir taip pat mylėjo Rachelę labiau už Lėją, ir tarnavo pas jį dar kitus septynerius metus.'),
  (@b1, 29, 31, 'Ir VIEŠPATS, matydamas, kad Lėja buvo nekenčiama, atidarė jos įsčias; bet Rachelė buvo nevaisinga.'),
  (@b1, 29, 32, 'Ir Lėja pastojo ir pagimdė sūnų ir praminė jį vardu Rubenas; nes ji sakė: „Tikrai VIEŠPATS pažvelgė į mano sielvartą; todėl dabar mane mylės mano vyras“.'),
  (@b1, 29, 33, 'Ir ji vėl pastojo ir pagimdė sūnų; ir tarė: „Kadangi VIEŠPATS girdėjo, kad aš buvau nekenčiama, todėl jis man davė ir šitą sūnų“; ir ji praminė jį vardu Simeonas.'),
  (@b1, 29, 34, 'Ir ji vėl pastojo ir pagimdė sūnų; ir tarė: „Dabar, šįkart, mano vyras jungsis prie manęs, nes jam pagimdžiau tris sūnus“; todėl jis buvo pramintas vardu Levis.'),
  (@b1, 29, 35, 'Ir ji vėl pastojo ir pagimdė sūnų; ir ji tarė: „Dabar aš girsiu VIEŠPATĮ“; todėl ji praminė jį vardu Juda; ir liovėsi gimdžiusi.'),
  (@b1, 30, 1, 'O kai Rachelė matė, kad nepagimdė Jokūbui vaikų, Rachelė pavydėjo savo seseriai; ir tarė Jokūbui: „Duok man vaikų, kitaip aš mirsiu“.'),
  (@b1, 30, 2, 'Ir Jokūbas užsidegė pykčiu ant Rachelės; ir jis tarė: „Ar aš esu vietoje Dievo, kuris užlaikė nuo tavęs įsčių vaisių?“'),
  (@b1, 30, 3, 'Ir ji tarė: „Štai mano tarnaitė Bilha, įeik pas ją; ir ji pagimdys ant mano kelių, kad iš jos aš taipogi turėčiau vaikų“.'),
  (@b1, 30, 4, 'Ir ji davė jam į žmonas savo tarnaitę Bilhą; ir Jokūbas įėjo pas ją.'),
  (@b1, 30, 5, 'Ir Bilha pastojo ir pagimdė Jokūbui sūnų.'),
  (@b1, 30, 6, 'Ir Rachelė tarė: „Dievas mane teisė ir taipogi išgirdo mano balsą, ir man davė sūnų“; todėl ji pavadino jį vardu Danas.'),
  (@b1, 30, 7, 'Ir Rachelės tarnaitė Bilha vėl pastojo ir pagimdė Jokūbui antrą sūnų.'),
  (@b1, 30, 8, 'Ir Rachelė tarė: „Didelėse grumtynėse aš grūmiausi su savo seserimi ir nugalėjau“; ir ji praminė jį vardu Naftalis.'),
  (@b1, 30, 9, 'Kai Lėja pamatė, kad liovėsi gimdžiusi, ji ėmė savo tarnaitę Zilpą ir ją davė Jokūbui į žmonas.'),
  (@b1, 30, 10, 'Ir Lėjos tarnaitė Zilpa pagimdė Jokūbui sūnų.'),
  (@b1, 30, 11, 'Ir Lėja tarė: „Pulkas ateina“; ir ji praminė jį vardu Gadas.'),
  (@b1, 30, 12, 'Ir Lėjos tarnaitė Zilpa pagimdė Jokūbui antrą sūnų.'),
  (@b1, 30, 13, 'Ir Lėja tarė: „Aš esu laiminga, nes dukterys vadins mane palaiminta“; ir ji praminė jį vardu Ašeras.'),
  (@b1, 30, 14, 'Ir kviečių pjūties metu Rubenas nuėjęs rado ant lauko mandragorų ir jas parnešė savo motinai Lėjai. Tada Rachelė tarė Lėjai: „Duok man, meldžiu tave, savo sūnaus mandragorų“.'),
  (@b1, 30, 15, 'O ji jai tarė: „Ar maža, kad esi atėmusi mano vyrą? Ar nori atimti ir mano sūnaus mandragoras?“ Ir Rachelė tarė: „Todėl jis šiąnakt gulės su tavimi už tavo sūnaus mandragoras“.'),
  (@b1, 30, 16, 'Ir Jokūbui pareinant vakare iš lauko, Lėja išėjo jo pasitikti ir tarė: „Tu turi įeiti pas mane; nes aš tikrai pasamdžiau tave už savo sūnaus mandragoras“. Ir tą naktį jis gulėjo su ja.'),
  (@b1, 30, 17, 'Ir Dievas išklausė Lėją ir ji pastojo, ir pagimdė Jokūbui penktąjį sūnų.'),
  (@b1, 30, 18, 'Ir Lėja tarė: „Dievas man davė mano atlyginimą, kadangi daviau savo tarnaitę savo vyrui“; ir ji praminė jį vardu Isacharas.'),
  (@b1, 30, 19, 'Ir Lėja vėl pastojo ir pagimdė Jokūbui šeštąjį sūnų.'),
  (@b1, 30, 20, 'Ir Lėja tarė: „Dievas apdalino mane puikiu kraičiu; dabar mano vyras gyvens su manimi, nes aš jam pagimdžiau šešis sūnus; ir ji praminė jį vardu Zebulonas.'),
  (@b1, 30, 21, 'Ir po to ji pagimdė dukterį ir ją praminė vardu Dina.'),
  (@b1, 30, 22, 'Ir Dievas atsiminė Rachelę, ir Dievas ją išklausė bei atvėrė jos įsčias.'),
  (@b1, 30, 23, 'Ir ji pastojo ir pagimdė sūnų; ir tarė: „Dievas nuėmė mano gėdą“;'),
  (@b1, 30, 24, 'ir ji praminė jį vardu Juozapas; ir tarė: „VIEŠPATS man pridės dar kitą sūnų“.'),
  (@b1, 30, 25, 'Ir įvyko, kai Rachelė pagimdė Juozapą, Jokūbas tarė Labanui: „Išleisk mane, kad vykčiau į savo paties vietą ir į savo šalį.'),
  (@b1, 30, 26, 'Duok man mano žmonas ir mano vaikus, už kuriuos tau tarnavau, ir leisk man eiti; nes tu žinai mano tarnystę, kurią esu tau atlikęs“.'),
  (@b1, 30, 27, 'Ir Labanas jam tarė: „Meldžiu tave, jei radau palankumą tavo akyse, pasilik; nes aš iš patirties sužinojau, kad VIEŠPATS mane palaimino dėl tavęs“.'),
  (@b1, 30, 28, 'Ir jis tarė: „Nurodyk man savo algą, ir aš ją duosiu“.'),
  (@b1, 30, 29, 'Ir jis jam tarė: „Tu žinai, kaip tau tarnavau ir kaip tavo galvijai buvo su manimi.'),
  (@b1, 30, 30, 'Nes jų buvo mažai, kurių prieš man atvykstant turėjai, o dabar yra priaugę iki daugybės; ir VIEŠPATS tave laimino nuo tada, kai atėjau; o dabar, kada aš galėsiu rūpintis ir savo namais?“'),
  (@b1, 30, 31, 'Ir jis tarė: „Ką tau duoti?“ O Jokūbas tarė: „Tu man nieko neduok; jei man padarysi tą dalyką, aš vėl ganysiu ir saugosiu tavo kaimenę;'),
  (@b1, 30, 32, 'šiandien pereisiu per visą tavo kaimenę, išimdamas iš ten visus margus bei dėmėtus galvijus ir visus rudus galvijus tarp avių, o dėmėtus bei margus tarp ožkų; ir iš tokių bus mano užmokestis.'),
  (@b1, 30, 33, 'Taip mano teisumas ateinančiu laiku atsakys už mane, kai ateis tavo akivaizdon dėl mano užmokesčio: visa, kas nebus marga bei dėmėta tarp ožkų ir ruda tarp avių, tai bus laikoma mano pavogta“.'),
  (@b1, 30, 34, 'Ir Labanas tarė: „Štai norėčiau, kad tai būtų pagal tavo žodį“.'),
  (@b1, 30, 35, 'Ir tą dieną jis išėmė dryžuotus bei dėmėtus ožius ir visas margas bei dėmėtas ožkas ir kiekvieną, kuriame buvo kas balto, ir visas rudas tarp avių, ir juos padavė į savo sūnų ranką.'),
  (@b1, 30, 36, 'Ir jis paskyrė trijų dienų kelią tarp savęs ir Jokūbo; o Jokūbas ganė likusias Labano kaimenes.'),
  (@b1, 30, 37, 'Ir Jokūbas pasiėmė šviežių tuopos, lazdyno ir kaštono lazdų; ir išlupinėjo jose baltus dryžius, padarydamas, kad pasirodytų lazdose esantis baltumas.'),
  (@b1, 30, 38, 'Ir jis sustatė lazdas, kurias buvo išlupinėjęs, kaimenių akivaizdoje į latakus, į girdomuosius lovius, kai kaimenės atėjo gerti, kad jos pastotų atėjusios atsigerti.'),
  (@b1, 30, 39, 'Ir kaimenės pastojo prieš lazdas ir atsivedė dryžuotus, margus bei dėmėtus galvijus.'),
  (@b1, 30, 40, 'Ir Jokūbas atskyrė avinėlius ir nukreipė kaimenių veidus į dryžuotus ir visus ruduosius Labano kaimenėje; ir jis atsidėjo savo paties kaimenes atskirai ir nestatė jų prie Labano galvijų.'),
  (@b1, 30, 41, 'Ir įvyko, kai tik stipresnieji galvijai pastojo, Jokūbas įdėjo lazdas į latakus prieš galvijų akis, kad jie pastotų tarp lazdų.'),
  (@b1, 30, 42, 'Bet kai galvijai buvo silpni, jis jų neįdėdavo; taip silpnesnieji buvo Labano, o stipresnieji Jokūbo.'),
  (@b1, 30, 43, 'Ir tas vyras nepaprastai augo ir turėjo daug galvijų, tarnaičių, tarnų, kupranugarių ir asilų.'),
  (@b1, 31, 1, 'Ir jis girdėjo Labano sūnų žodžius, sakant: „Jokūbas pasiėmė viską, kas buvo mūsų tėvo; ir iš to, kas buvo mūsų tėvo, jis įsigijo visą šitą šlovę“.'),
  (@b1, 31, 2, 'Ir Jokūbas pamatė Labano veidą, ir štai šis nebuvo nukreiptas į jį kaip anksčiau.'),
  (@b1, 31, 3, 'Ir VIEŠPATS tarė Jokūbui: „Grįžk į savo tėvų šalį ir pas savo gimines; ir aš būsiu su tavimi“.'),
  (@b1, 31, 4, 'Ir Jokūbas pasiuntė ir pasišaukė Rachelę bei Lėją ant lauko į savo kaimenę'),
  (@b1, 31, 5, 'ir joms tarė: „Aš matau jūsų tėvo veidą, kad jis nebėra nukreiptas į mane kaip anksčiau; bet mano tėvo Dievas buvo su manimi.'),
  (@b1, 31, 6, 'Ir jūs žinote, kad visa savo jėga tarnavau jūsų tėvui.'),
  (@b1, 31, 7, 'O jūsų tėvas mane apgavo ir dešimt kartų keitė mano atlyginimą; tačiau Dievas jam neleido daryti man pikto.'),
  (@b1, 31, 8, 'Jei jis sakė taip: „Margieji bus tavo užmokestis“; tuomet visi galvijai gimdė margus; o jei jis sakė taip: „Dryžuotieji bus tavo užmokestis“; tuomet visi galvijai gimdė dryžuotus.'),
  (@b1, 31, 9, 'Taip Dievas atėmė iš jūsų tėvo galvijus ir davė man.'),
  (@b1, 31, 10, 'Ir įvyko, kad galvijų pastojimo metu aš pakėliau savo akis ir sapne regėjau, ir štai avinai, kurie šokinėjo ant galvijų, buvo dryžuoti, margi ir dėmėti.'),
  (@b1, 31, 11, 'Ir Dievo angelas sapne man kalbėjo, sakydamas: ‘Jokūbai’; ir aš tariau: ‘Aš čia’.'),
  (@b1, 31, 12, 'Ir jis tarė: ‘Na, pakelk savo akis ir žiūrėk, visi avinai, kurie šokinėja ant galvijų, yra dryžuoti, margi ir dėmėti; nes aš mačiau viską, ką Labanas tau daro.'),
  (@b1, 31, 13, 'Aš esu Dievas Bet-Elio, kur tu patepei stulpą ir kur man davei įžadą; dabar kelkis, išeik iš šios šalies ir sugrįžk į savo giminių šalį“.'),
  (@b1, 31, 14, 'O Rachelė ir Lėja atsakydamos jam tarė: „Ar mums yra dar kokia dalis ar paveldas mūsų tėvo namuose?'),
  (@b1, 31, 15, 'Argi nebuvome jo laikomos svetimomis? Nes jis mus pardavė ir visiškai surijo ir mūsų pinigus.'),
  (@b1, 31, 16, 'Nes visi turtai, kuriuos Dievas atėmė iš mūsų tėvo, tai yra mūsų ir mūsų vaikų; taigi dabar daryk visa, ką Dievas yra tau pasakęs“.'),
  (@b1, 31, 17, 'Tada Jokūbas pakilęs užsodino ant kupranugarių savo sūnus ir savo žmonas;'),
  (@b1, 31, 18, 'ir jis nusivarė visus savo galvijus ir visą savo turtą, kurį buvo įsigijęs, savo įgytus galvijus, kuriuos buvo įsigijęs Padan-Arame, kad vyktų pas savo tėvą Izaoką į Kanaano šalį.'),
  (@b1, 31, 19, 'Ir Labanas nuėjo savo avių kirpti; o Rachelė buvo pavogusi atvaizdus, kurie buvo jos tėvo.'),
  (@b1, 31, 20, 'Ir Jokūbas vogčia išslinko sirui Labanui nejaučiant, jam nepasakydamas, kad jis pabėgo.'),
  (@b1, 31, 21, 'Taigi jis pabėgo su viskuo, ką turėjo; ir pakilęs persikėlė per upę ir nukreipė savo veidą Gileado kalno link.'),
  (@b1, 31, 22, 'O trečiąją dieną Labanui buvo pranešta, kad Jokūbas pabėgęs.'),
  (@b1, 31, 23, 'Ir paėmęs su savimi savo brolius, jis vijosi jį septynių dienų kelią; ir jie pasivijo jį Gileado kalne.'),
  (@b1, 31, 24, 'Ir Dievas atėjo pas sirą Labaną naktį sapne ir jam tarė: „Saugokis, kad nekalbėtum Jokūbui nei gera, nei bloga“.'),
  (@b1, 31, 25, 'Tada Labanas pasivijo Jokūbą. Na, o Jokūbas buvo pasistatęs savo palapinę kalne; ir Labanas su savo broliais stovyklavo Gileado kalne.'),
  (@b1, 31, 26, 'Ir Labanas tarė Jokūbui: „Ką tu padarei, kad vogčia išslinkai man nežinant ir išsivedei mano dukteris kaip kalaviju paimtas belaisves?'),
  (@b1, 31, 27, 'Kodėl slapčia pabėgai ir vogčia išslinkai nuo manęs? Ir man nepasakei, kad tave išlydėčiau su džiaugsmu ir giesmėmis, su būgnu ir arfa?'),
  (@b1, 31, 28, 'Ir man neleidai pabučiuoti mano sūnų ir mano dukterų? Kvailai pasielgei taip darydamas.'),
  (@b1, 31, 29, 'Aš turiu galią savo rankoje jums daryti pikta; bet jūsų tėvo Dievas vakar naktį man kalbėjo, sakydamas: ‘Saugokis, kad nekalbėtum Jokūbui nei gera, nei bloga’.'),
  (@b1, 31, 30, 'O dabar, nors tu norėjai būtinai išeiti, kadangi labai išsiilgai savo tėvo namų, tačiau kodėl pavogei mano dievus?“'),
  (@b1, 31, 31, 'Ir Jokūbas atsakydamas tarė Labanui: „Kadangi aš bijojau; nes aš tariau: ‘Galbūt tu norėsi prievarta atimti iš manęs savo dukteris’.'),
  (@b1, 31, 32, 'Tas, pas kurį rasi savo dievus, tenelieka gyvas; mūsų brolių akivaizdoje atskirk, kas pas mane tavo, ir pasiimk“. Nes Jokūbas nežinojo, kad Rachelė buvo juos pavogusi.'),
  (@b1, 31, 33, 'Ir Labanas įėjo į Jokūbo palapinę, į Lėjos palapinę ir į dviejų tarnaičių palapines; bet jis jų nerado. Paskui, išėjęs iš Lėjos palapnės, jis įėjo į Rachelės palapinę.'),
  (@b1, 31, 34, 'Na, o Rachelė buvo paėmusi atvaizdus ir juos padėjusi kupranugario pakinktuose ir atsisėdusi ant jų. Ir Labanas išieškojo visą palapinę, bet jų nerado.'),
  (@b1, 31, 35, 'Ir ji tarė savo tėvui: „Tenesupyksta mano viešpats, kad negaliu atsikelti prieš tave; nes man atsitiko pagal moterų būdą“. Ir jis išieškojo, tačiau atvaizdų nerado.'),
  (@b1, 31, 36, 'Ir Jokūbas užsirūstino ir barėsi su Labanu; ir Jokūbas atsakydamas tarė Labanui: „Koks mano nusikaltimas? Kokia mano nuodėmė, kad taip užsidegęs mane vijaisi?'),
  (@b1, 31, 37, 'Nors išieškojai visus mano daiktus, ką radai iš visų savo namų daiktų? Padėk tai čia, mano brolių ir savo brolių akivaizdoje, kad jie teistų tarp mudviejų.'),
  (@b1, 31, 38, 'Šiuos dvidešimt metų aš buvau pas tave; tavo avys ir tavo ožkos neišsimetė, ir tavo kaimenės avinų aš nevalgiau.'),
  (@b1, 31, 39, 'Žvėrių sudraskyto tau neatnešiau; aš prisiėmiau to nuostolį; iš mano rankos to reikalavai, ar tai pavogto dieną, ar pavogto naktį.'),
  (@b1, 31, 40, 'Taip aš buvau; dieną mane rijo kaitra, o naktį šaltis; ir miegas pasitraukė nuo mano akių.'),
  (@b1, 31, 41, 'Taip aš buvau dvidešimt metų tavo namuose; aš tau tarnavau keturiolika metų už tavo abi dukteris ir šešerius metus už tavo galvijus; o tu dešimt kartų keitei mano atlyginimą.'),
  (@b1, 31, 42, 'Jei mano tėvo Dievas, Abraomo Dievas, ir Izaoko baimė nebūtų buvę su manimi, tikrai dabar būtum mane išleidęs tuščią. Mano sielvartą ir mano rankų triūsą Dievas pamatė ir vakar naktį tave subarė“.'),
  (@b1, 31, 43, 'Ir Labanas atsakydamas tarė Jokūbui: „Šios dukterys yra mano dukterys, šie vaikai yra mano vaikai, šie galvijai yra mano galvijai, ir visa, ką matai, yra mano; ir ką šią dieną galiu padaryti šioms savo dukterims ar jų vaikams, kuriuos jos pagimdė?'),
  (@b1, 31, 44, 'Taigi dabar eikš, sudarykime sandorą, aš ir tu; ir ji tebūna liudijimui tarp manęs ir tavęs“.'),
  (@b1, 31, 45, 'Ir Jokūbas paėmė akmenį ir jį pastatė kaip stulpą.'),
  (@b1, 31, 46, 'Ir Jokūbas tarė savo broliams: „Surinkite akmenų“; ir jie ėmė akmenis ir padarė krūvą; ir jie valgė ten ant krūvos.'),
  (@b1, 31, 47, 'Ir Labanas ją pavadino Jegar-Sahaduta; bet Jokūbas ją praminė Galeedu.'),
  (@b1, 31, 48, 'Ir Labanas tarė: „Ši krūva šią dieną yra liudytoja tarp manęs ir tavęs“. Todėl ją praminė vardu Galeedas;'),
  (@b1, 31, 49, 'ir Micpa; nes jis tarė: „VIEŠPATS tegul stebi tarp manęs ir tavęs, kai nebebūsime vienas kito akivaizdoje.'),
  (@b1, 31, 50, 'Jei tu skaudinsi mano dukteris ar imsi kitų žmonų šalia mano dukterų, nei vieno žmogaus nėra su mumis; štai Dievas yra liudytojas tarp manęs ir tavęs“.'),
  (@b1, 31, 51, 'Ir Labanas tarė Jokūbui: „Štai ši krūva ir štai šis stulpas, ką sumečiau tarp savęs ir tavęs;'),
  (@b1, 31, 52, 'ši krūva bus liudytoja ir šis stulpas bus liudytojas, kad aš nepereisiu pas tave per šią krūvą, ir kad tu nepereisi pas mane per šią krūvą ir šį stulpą dėl pikto.'),
  (@b1, 31, 53, 'Abraomo Dievas ir Nahoro Dievas, jų tėvų Dievas, teteisia tarp mūsų“. Ir Jokūbas prisiekė savo tėvo Izaoko baime.'),
  (@b1, 31, 54, 'Tada Jokūbas atnašavo ant kalno auką ir pakvietė savo brolius valgyti duonos; ir jie valgė duonos ir pasiliko visą naktį kalne.'),
  (@b1, 31, 55, 'Ir Labanas atsikėlė anksti ryte, pabučiavo savo sūnus bei savo dukteris ir juos palaimino; ir Labanas išėjo ir sugrįžo į savo vietą.'),
  (@b1, 32, 1, 'Ir Jokūbas nukeliavo sau, ir jį pasitiko Dievo angelai.'),
  (@b1, 32, 2, 'Ir Jokūbas, juos išvydęs, tarė: „Tai Dievo kariuomenė“; ir jis praminė tą vietą vardu Machanaimas.'),
  (@b1, 32, 3, 'Ir Jokūbas siuntė pirma savęs pasiuntinius pas savo brolį Ezavą į Seyro šalį, Edomo kraštą.'),
  (@b1, 32, 4, 'Ir jis jiems įsakė, sakydamas: „Šitaip sakykite mano viešpačiui Ezavui: ‘Taip sako tavo tarnas Jokūbas: Buvau laikinai apsigyvenęs pas Labaną ir pasilikau ten iki dabar;'),
  (@b1, 32, 5, 'ir aš turiu jaučių, asilų ir kaimenių, tarnų ir tarnaičių; ir pasiunčiau pranešti savo viešpačiui, kad rasčiau malonę tavo akyse’“.'),
  (@b1, 32, 6, 'Ir pasiuntiniai sugrįžo pas Jokūbą, sakydami: „Mes nuėjome pas tavo brolį Ezavą, o jis taip pat ateina tavęs pasitikti, ir su juo keturi šimtai vyrų“.'),
  (@b1, 32, 7, 'Tada Jokūbas labai nusigando ir sielojosi; ir jis padalijo su juo esančią liaudį, kaimenes, bandas ir kupranugarius į du būrius;'),
  (@b1, 32, 8, 'ir tarė: „Jei Ezavas ateis prie vieno būrio ir jį sumuš, tuomet kitas išlikęs būrys išsigelbės“.'),
  (@b1, 32, 9, 'Ir Jokūbas tarė: „O, mano tėvo Abraomo Dieve ir mano tėvo Izaoko Dieve, VIEŠPATIE, kuris man sakei: ‘Grįžk į savo šalį pas savo gimines, ir aš tau gera darysiu’;'),
  (@b1, 32, 10, 'aš nevertas nei mažiausio iš visų gailestingumų ir visos tiesos, kurią esi parodęs savo tarnui; nes su savo lazda aš perėjau šį Jordaną; o dabar aš tapau dviem būriais.'),
  (@b1, 32, 11, 'Išgelbėk mane, meldžiu tave, iš mano brolio rankos, iš Ezavo rankos; nes aš jo bijau, kad jis neateitų ir nesumuštų manęs bei motinos su vaikais.'),
  (@b1, 32, 12, 'Ir tu sakei: ‘Aš tikrai darysiu tau gera ir padarysiu tavo sėklą kaip jūros smėlį, kurio dėl daugybės negalima suskaičiuoti’“.'),
  (@b1, 32, 13, 'Ir jis ten nakvojo tą pačią naktį; ir paėmė iš to, kas pateko į jo ranką, dovaną savo broliui Ezavui:'),
  (@b1, 32, 14, 'du šimtus ožkų ir dvidešimt ožių, du šimtus avių ir dvidešimt avinų,'),
  (@b1, 32, 15, 'trisdešimt melžiamų kupranugarių su jų kumeliukais, keturiasdešimt karvių ir dešimt bulių, dvidešimt asilių ir dešimt asiliukų.'),
  (@b1, 32, 16, 'Ir jis juos davė savo tarnams į rankas, kiekvieną bandą atskirai; ir tarė savo tarnams: „Eikite pirma manęs ir palikite tarpą tarp bandos ir bandos“.'),
  (@b1, 32, 17, 'Ir jis įsakė pirmajam, sakydamas: „Kai tave pasitiks mano brolis Ezavas ir tavęs paklaus, sakydamas: ‘Kieno tu esi? Ir kur eini? Ir kieno yra šitie tavo priešakyje?’'),
  (@b1, 32, 18, 'Tuomet sakyk: ‘Jie yra tavo tarno Jokūbo; tai dovana siunčiama mano viešpačiui Ezavui; o štai ir jis mums iš paskos’“.'),
  (@b1, 32, 19, 'Ir taip jis įsakė antrajam ir trečiajam, ir visiems, kurie ėjo paskui bandas, tardamas: „Šitaip kalbėkite Ezavui, kai jį sutiksite.'),
  (@b1, 32, 20, 'Ir dar sakykite: ‘Štai tavo tarnas Jokūbas yra mums iš paskos’“. Nes jis tarė: „Aš jį permaldausiu dovana, kuri eina pirma manęs, o paskui išvysiu jo veidą; galbūt jis iš manęs priims“.'),
  (@b1, 32, 21, 'Taip dovana ėjo pirma jo; o pats tą naktį nakvojo būryje.'),
  (@b1, 32, 22, 'Ir atsikėlęs tą naktį jis paėmė abi savo žmonas, abi savo tarnaites bei vienuolika savo sūnų ir perbrido Jaboko brastą.'),
  (@b1, 32, 23, 'Ir jis, juos paėmęs, persiuntė per upelį ir persiuntė viską, ką turėjo.'),
  (@b1, 32, 24, 'O Jokūbas pasiliko vienas; ir ten vyras grūmėsi su juo iki prabrėško aušra.'),
  (@b1, 32, 25, 'Ir matydamas, kad jo nenugali, jis palietė jo šlaunies įdubą; ir Jokūbo šlaunies įduba išsinarino jam besigrūmiant su juo.'),
  (@b1, 32, 26, 'Ir jis tarė: „Paleisk mane, nes brėkšta aušra“. O jis tarė: „Aš tavęs nepaleisiu, jei manęs nepalaiminsi“.'),
  (@b1, 32, 27, 'Ir jis jam tarė: „Kuo tu vardu?“ Ir jis tarė: „Jokūbas“.'),
  (@b1, 32, 28, 'Ir jis tarė: „Tu jau nebebūsi vadinamas Jokūbo vardu, bet Izraeliu; nes kaip kunigaikštis tu turi jėgos su Dievu ir su žmonėmis, ir nugalėjai“.'),
  (@b1, 32, 29, 'Ir Jokūbas jo klausdamas tarė: „Pasakyk man, meldžiu tave, savo vardą“. Ir jis tarė: „Dėl ko tai yra, kad klausi mano vardo?“ Ir jis jį ten palaimino.'),
  (@b1, 32, 30, 'Ir Jokūbas pavadino tą vietą vardu Penielis: „Nes aš regėjau Dievą veidas į veidą, ir mano gyvybė yra išsaugota“.'),
  (@b1, 32, 31, 'Ir jam einant per Penuelį, jam patekėjo saulė, ir jis šlubavo savo šlaunimi.'),
  (@b1, 32, 32, 'Todėl iki šios dienos Izraelio vaikai nevalgo sutraukimo sausgyslės, esančios ant šlaunies įdubos; nes jis palietė Jokūbo šlaunies įdubą prie sutraukimo sausgyslės.'),
  (@b1, 33, 1, 'Ir pakėlęs savo akis Jokūbas pažiūrėjo, ir štai atėjo Ezavas ir su juo keturi šimtai vyrų. Ir jis padalijo vaikus Lėjai, Rachelei ir abiems tarnaitėms.'),
  (@b1, 33, 2, 'Ir jis pastatė tarnaites ir jų vaikus pačiame priekyje, Lėją ir jos vaikus už jų, o Rachelę ir Juozapą pačius paskutinius.'),
  (@b1, 33, 3, 'Ir jis nuėjo pirma jų ir septynis kartus nusilenkė ligi žemės, kol priartėjo prie savo brolio.'),
  (@b1, 33, 4, 'Ir Ezavas bėgo jo pasitikti, jį apkabino ir, puolęs jam ant kaklo, jį bučiavo; ir jie verkė.'),
  (@b1, 33, 5, 'Ir pakėlęs savo akis jis pamatė moteris ir vaikus; ir tarė: „Kas yra šitie su tavimi?“ Ir jis tarė: „Vaikai, kuriuos Dievas maloningai davė tavo tarnui“.'),
  (@b1, 33, 6, 'Tada priartėjo tarnaitės, jos ir jų vaikai, ir jie nusilenkė.'),
  (@b1, 33, 7, 'Taip pat priartėjo Lėja su savo vaikais, ir jie nusilenkė; o paskui priartėjo Juozapas ir Rachelė, ir jie nusilenkė.'),
  (@b1, 33, 8, 'Ir jis tarė: „Ko sieki visa šia banda, kurią sutikau?“ Ir jis tarė: „Šitie yra, kad mano viešpaties akivaizdoje rasčiau malonę“.'),
  (@b1, 33, 9, 'Ir Ezavas tarė: „Aš turiu užtektinai, mano broli; pasilaikyk, ką turi, sau“.'),
  (@b1, 33, 10, 'Ir Jokūbas tarė: „Ne, meldžiu tave, jei dabar radau malonę tavo akyse, tai priimk iš mano rankos mano dovaną; nes todėl aš išvydau tavo veidą, tarsi išvydau Dievo veidą, ir tu buvai patenkintas manimi.'),
  (@b1, 33, 11, 'Imk, meldžiu tave, mano palaiminimą, kuris yra tau atgabentas; kadangi Dievas maloningai su manimi elgėsi ir kadangi aš užtektinai turiu“. Ir jis primygtinai siūlė, ir jis paėmė.'),
  (@b1, 33, 12, 'Ir jis tarė: „Leiskimės kelionėn ir eikime, o aš eisiu pirma tavęs“.'),
  (@b1, 33, 13, 'Ir jis jam tarė: „Mano viešpats žino, kad vaikai yra silpnučiai, ir su manimi yra kaimenės ir bandos su jaunikliais; ir jei juos per greitai varys per vieną dieną, visa kaimenė išgaiš.'),
  (@b1, 33, 14, 'Mano viešpats, meldžiu tave, tegul eina pirma savo tarno; o aš palengva vesiu kiek prieš mane einantys galvijai ir vaikai pajėgia ištverti, kol ateisiu pas mano viešpatį į Seyrą“.'),
  (@b1, 33, 15, 'Ir Ezavas tarė: „Leisk man palikti pas tave bent kiek iš žmonių, kurie su manimi“. O jis tarė: „Kam tai? Terasiu malonę mano viešpaties akivaizdoje“.'),
  (@b1, 33, 16, 'Taip Ezavas tą dieną grįžo savo keliu į Seyrą.'),
  (@b1, 33, 17, 'O Jokūbas keliavo į Sukotą ir pasistatė namus, o savo galvijams padarė pastoges; todėl praminė tą vietą vardu Sukotas.'),
  (@b1, 33, 18, 'Ir atėjęs iš Padan-Aramo Jokūbas atėjo į Šalemą, Šechemo miestą, esantį Kanaano šalyje; ir pasistatė savo palapinę prieš miestą.'),
  (@b1, 33, 19, 'Ir jis nusipirko lauko sklypą, kur buvo išskleidęs savo palapinę, iš Šechemo tėvo Hamoro vaikų rankos, už šimtą monetų.'),
  (@b1, 33, 20, 'Ir jis ten pastatė aukurą ir jį pavadino El-Elohe-Izrael.'),
  (@b1, 34, 1, 'Ir Lėjos duktė Dina, kurią ji buvo pagimdžiusi Jokūbui, išėjo pažiūrėti tos šalies dukterų.'),
  (@b1, 34, 2, 'Ir šalies kunigaikščio hivo Hamoro sūnus Šechemas ją pamatęs paėmė ją ir sugulė su ja, ir ją suteršė.'),
  (@b1, 34, 3, 'Ir jo siela prilipo prie Jokūbo dukters Dinos, ir jis pamilo tą panelę, ir maloniai tai panelei kalbėjo.'),
  (@b1, 34, 4, 'Ir Šechemas kalbėjo savo tėvui Hamorui, tardamas: „Gauk man šitą panelę į žmonas“.'),
  (@b1, 34, 5, 'Ir Jokūbas išgirdo, kad jis suteršė jo dukterį Diną; na, o jo sūnūs buvo prie jo galvijų ant lauko; ir Jokūbas tylėjo, kol jie parėjo.'),
  (@b1, 34, 6, 'Ir Šechemo tėvas Hamoras išėjo pas Jokūbą su juo kalbėtis.'),
  (@b1, 34, 7, 'Ir Jokūbo sūnūs, tai išgirdę, parėjo nuo lauko; ir tie vyrai sielojosi ir jie labai užsirūstino, nes suguldamas su Jokūbo dukterimi jis padarė kvailystę Izraelyje; kas neturėtų būti daroma.'),
  (@b1, 34, 8, 'Ir Hamoras kalbėjosi su jais, sakydamas: „Mano sūnaus Šechemo siela ilgisi jūsų dukters; meldžiu jus, duokite jam ją į žmonas.'),
  (@b1, 34, 9, 'Ir sudarykite su mumis santuokas, duokite mums savo dukteris ir imkite sau mūsų dukteris.'),
  (@b1, 34, 10, 'Ir gyvenkite su mumis; ir šalis bus jūsų priešakyje; gyvenkite ir verskitės joje, ir įsigykite joje nuosavybę“.'),
  (@b1, 34, 11, 'Ir Šechemas tarė jos tėvui ir jos broliams: „Leiskite man rasti malonę jūsų akyse, ir ką man pasakysite, aš duosiu.'),
  (@b1, 34, 12, 'Prašykite manęs kaip niekada daug kraičio ir dovanų, ir aš duosiu, kaip jūs man pasakysite; tik man duokite tą panelę į žmonas“.'),
  (@b1, 34, 13, 'Ir Jokūbo sūnūs atsakė Šechemui ir jo tėvui Hamorui klastingai kalbėdami, nes jis buvo suteršęs jų seserį Diną;'),
  (@b1, 34, 14, 'ir jie tarė jiems: „Mes negalime to padaryti, duoti savo seserį tam, kuris yra neapipjaustytas; nes tai būtų mums gėda;'),
  (@b1, 34, 15, 'tik tuo sutiksime su jumis: jei jūs būsite tokie, kaip mes, kad kiekvienas jūsų vyriškos lyties būtų apipjaustytas;'),
  (@b1, 34, 16, 'tada duosime jums savo dukteris ir imsime sau jūsų dukteris, ir gyvensime su jumis, ir tapsime viena tauta.'),
  (@b1, 34, 17, 'Bet jei jūs mūsų neklausysite, kad būtumėte apipjaustyti; tuomet pasiimsime savo dukterį ir išvyksime“.'),
  (@b1, 34, 18, 'Ir jų žodžiai patiko Hamorui ir Hamoro sūnui Šechemui.'),
  (@b1, 34, 19, 'Ir tas jaunuolis nedelsė to padaryti, nes jis žavėjosi Jokūbo dukterimi; ir jis buvo gerbiamas labiau už visus savo tėvo namus.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 34, 20, 'Ir Hamoras ir jo sūnus Šechemas atėjo prie savo miesto vartų ir kalbėjo savo miesto vyrams, sakydami:'),
  (@b1, 34, 21, '„Šitie žmonės yra taikūs su mumis; todėl tegyvena jie šalyje ir joje verčiasi; nes šalis štai jiems užtektinai didelė; imkime jų dukteris sau į žmonas ir duokime jiems mūsų dukteris.'),
  (@b1, 34, 22, 'Tik tuo tie žmonės sutiks su mumis gyventi pas mus, kad būtume viena tauta, jei kiekvienas tarp mūsų vyriškos lyties bus apipjaustytas, kaip jie yra apipjaustyti.'),
  (@b1, 34, 23, 'Argi jų galvijai, jų turtas ir visi jų gyvuliai nebus mūsų? Tik sutikime su jais, ir jie gyvens pas mus“.'),
  (@b1, 34, 24, 'Ir Hamoro ir jo sūnaus Šechemo paklausė visi, kurie išėjo iš jo miesto vartų; ir visi vyriškos lyties buvo apipjaustyti, visi, kurie išėjo iš jo miesto vartų.'),
  (@b1, 34, 25, 'Ir įvyko trečiąją dieną, kai jiems skaudėjo, jog du iš Jokūbo sūnų, Simeonas ir Levis, Dinos broliai, pasiėmė kiekvienas savo kalaviją ir drąsiai užpuolė miestą, ir išžudė visus vyriškos lyties.'),
  (@b1, 34, 26, 'Ir jie nužudė kalavijo ašmenimis Hamorą ir jo sūnų Šechemą ir paėmė Diną iš Šechemo namų, ir išėjo.'),
  (@b1, 34, 27, 'Jokūbo sūnūs užėjo ant užmuštųjų ir apiplėšė miestą, nes jie suteršė jų seserį.'),
  (@b1, 34, 28, 'Jie paėmė jų avis, jų jaučius, jų asilus, tai, kas buvo mieste, ir tai, kas buvo ant lauko,'),
  (@b1, 34, 29, 'visą jų turtą, visus jų mažylius, jų žmonas jie išsivedė į nelaisvę ir pasigrobė viską, kas buvo namuose.'),
  (@b1, 34, 30, 'Ir Jokūbas tarė Simeonui ir Leviui: „Jūs man sukėlėte nerimą, padarę, kad smirdėčiau tos šalies gyventojų, kanaaniečių ir perizų tarpe; ir man esant mažam skaičiumi, jie susitelks prieš mane ir mane užmuš; ir aš būsiu sunaikintas, aš ir mano namai“.'),
  (@b1, 34, 31, 'Ir jie tarė: „Ar jis turėjo pasielgti su mūsų seserimi kaip su paleistuve?“'),
  (@b1, 35, 1, 'Ir Dievas tarė Jokūbui: „Kelkis, eik aukštyn į Bet-Elį ir ten gyvenk; ir ten padaryk aukurą Dievui, kuris tau pasirodė, kai bėgai nuo savo brolio Ezavo veido“.'),
  (@b1, 35, 2, 'Tada Jokūbas tarė savo namiškiams ir visiems, kurie buvo su juo: „Pašalinkite svetimus dievus, esančius tarp jūsų, ir būkite švarūs ir pakeiskite savo drabužius;'),
  (@b1, 35, 3, 'ir pakilę eikime aukštyn į Bet-Elį; ir ten aš padarysiu aukurą Dievui, kuris atsakė man mano suspaudimo dieną ir buvo su manimi kelyje, kuriuo ėjau“.'),
  (@b1, 35, 4, 'Ir jie davė Jokūbui visus svetimus dievus, esančius jų rankose, bei visus savo auskarus, esančius jų ausyse; ir Jokūbas juos paslėpė po ąžuolu, esančiu prie Šechemo.'),
  (@b1, 35, 5, 'Ir jie keliavo; ir Dievo baimė buvo ant visų, aplink juos esančių miestų, ir jie nesivijo Jokūbo sūnų.'),
  (@b1, 35, 6, 'Taip Jokūbas atvyko į Lūzą, esantį Kanaano šalyje, tai yra Bet-Elį, jis ir visa su juo esanti tauta.'),
  (@b1, 35, 7, 'Ir ten jis pastatė aukurą ir tą vietą pavadino El-Bet-Eliu; nes ten jam pasirodė Dievas, kai jis bėgo nuo savo brolio veido.'),
  (@b1, 35, 8, 'Bet numirė Debora, Rebekos žindyvė, ir ji buvo palaidota Bet-Elio apačioje, po ąžuolu; ir jis buvo pramintas vardu Alon-Bakutas.'),
  (@b1, 35, 9, 'Ir Dievas vėl pasirodė Jokūbui, atvykus jam iš Padan-Aramo, ir jį palaimino.'),
  (@b1, 35, 10, 'Ir Dievas jam tarė: „Tavo vardas yra Jokūbas; tu nebesivadinsi vardu Jokūbas, bet Izraelis bus tavo vardas“; ir jis pavadino jį vardu Izraelis.'),
  (@b1, 35, 11, 'Ir Dievas jam tarė: „Aš esu Visagalis Dievas; būk vaisingas ir dauginkis; tauta ir tautų būrys bus iš tavęs, ir karaliai išeis iš tavo strėnų;'),
  (@b1, 35, 12, 'ir šalį, kurią daviau Abraomui ir Izaokui, tau ją duosiu, ir tavo sėklai po tavęs duosiu tą šalį“.'),
  (@b1, 35, 13, 'Ir Dievas pakilo nuo jo toje vietoje, kur kalbėjosi su juo.'),
  (@b1, 35, 14, 'Ir Jokūbas pastatė stulpą toje vietoje, kur jis kalbėjosi su juo, akmeninį stulpą; ir jis užpylė ant jo geriamąją atnašą ir užpylė ant jo aliejaus.'),
  (@b1, 35, 15, 'Ir vietą, kur Dievas kalbėjosi su juo, Jokūbas praminė vardu Bet-Elis.'),
  (@b1, 35, 16, 'Ir jie keliavo iš Bet-Elio; ir ateiti iki Efrato buvo tik truputis kelio; ir Rachelė kentėjo gimdymo skausmus, ir jos gimdymas buvo sunkus.'),
  (@b1, 35, 17, 'Ir įvyko, kad jai sunkiai gimdant pribuvėja jai tarė: „Nebijok; tu turėsi ir šį sūnų“.'),
  (@b1, 35, 18, 'Ir įvyko, jos sielai išeinant (nes ji mirė), ji praminė jį vardu Ben-Oni; bet jo tėvas jį pavadino Benjaminu.'),
  (@b1, 35, 19, 'Ir Rachelė mirė ir buvo palaidota kelyje į Efratą, kuris yra Betliejus.'),
  (@b1, 35, 20, 'Ir Jokūbas pastatė ant jos kapo stulpą; tai Rachelės kapo stulpas iki šios dienos.'),
  (@b1, 35, 21, 'Ir Izraelis keliavo ir ištiesė savo palapinę anapus Edaro bokšto.'),
  (@b1, 35, 22, 'Ir įvyko, kad Izraeliui gyvenant toje šalyje, Rubenas nuėjo ir sugulė su savo tėvo sugulove Bilha; ir Izraelis tai išgirdo. Na, o Jokūbo sūnų buvo dvylika;'),
  (@b1, 35, 23, 'Lėjos sūnūs: Jokūbo pirmagimis Rubenas, Simeonas, Levis, Juda, Isacharas ir Zebulonas;'),
  (@b1, 35, 24, 'Rachelės sūnūs: Juozapas ir Benjaminas;'),
  (@b1, 35, 25, 'o Rachelės tarnaitės Bilhos sūnūs: Danas ir Naftalis;'),
  (@b1, 35, 26, 'o Lėjos tarnaitės Zilpos sūnūs: Gadas ir Ašeras; šie yra Jokūbo sūnūs, kurie jam gimė Padan-Arame.'),
  (@b1, 35, 27, 'Ir Jokūbas atėjo pas savo tėvą Izaoką į Mamrę, į Arbo miestą, kuris yra Hebronas, kur Abraomas ir Izaokas laikinai gyveno.'),
  (@b1, 35, 28, 'Ir Izaoko dienų buvo šimtas aštuoniasdešimt metų.'),
  (@b1, 35, 29, 'Ir Izaokas, atidavęs dvasią, numirė ir buvo surinktas prie savo tautos, būdamas senas ir pasisotinęs dienomis; ir jį palaidojo jo sūnūs Ezavas ir Jokūbas.'),
  (@b1, 36, 1, 'Na, o šita yra Ezavo, kuris yra Edomas, genealogija.'),
  (@b1, 36, 2, 'Ezavas ėmė savo žmonas iš Kanaano dukterų: hetito Elono dukterį Adą bei Aholibamą, dukterį Anos, dukterį hivo Sibeono;'),
  (@b1, 36, 3, 'ir Basematą, Išmaelio dukterį, Nebajoto seserį.'),
  (@b1, 36, 4, 'Ir Ada pagimdė Ezavui Elifazą; ir Basemata pagimdė Reuelį;'),
  (@b1, 36, 5, 'o Aholibama pagimdė Jeušą, Jaalamą ir Korachą; šitie yra Ezavo sūnūs, kurie jam gimė Kanaano šalyje.'),
  (@b1, 36, 6, 'Ir Ezavas paėmė savo žmonas, savo sūnus ir savo dukteris bei visus savo namų asmenis, ir savo galvijus, ir visus savo gyvulius, ir visą savo turtą, kurį jis buvo įsigijęs Kanaano šalyje; ir vyko nuo savo brolio Jokūbo veido į kraštą.'),
  (@b1, 36, 7, 'Nes jų turtas buvo per didelis, kad jie galėtų gyventi drauge; ir šalis, kurioje jie buvo ateiviai, negalėjo jų pakelti dėl jų galvijų.'),
  (@b1, 36, 8, 'Taip Ezavas gyveno Seyro kalne; Ezavas tai Edomas.'),
  (@b1, 36, 9, 'Ir šita yra genealogija Ezavo, edomitų tėvo Seyro kalne;'),
  (@b1, 36, 10, 'šitie yra Ezavo sūnų vardai: Ezavo žmonos Ados sūnus Elifazas, Ezavo žmonos Basematos sūnus Reuelis.'),
  (@b1, 36, 11, 'Ir Elifazo sūnūs buvo Temanas, Omaras, Sefojas, Gatamas ir Kenazas.'),
  (@b1, 36, 12, 'O Timna buvo Ezavo sūnaus Elifazo sugulovė; ir ji pagimdė Elifazui Amaleką; šitie buvo Ezavo žmonos Ados sūnūs.'),
  (@b1, 36, 13, 'O šitie yra Reuelio sūnūs: Nahatas ir Zerachas, Šama ir Miza; šitie buvo Ezavo žmonos Basematos sūnūs.'),
  (@b1, 36, 14, 'Ir šitie buvo sūnūs Aholibamos, Anos dukters, Sibeono dukters, Ezavo žmonos; ir ji pagimdė Ezavui Jeušą, Jaalamą ir Korachą.'),
  (@b1, 36, 15, 'Šitie yra Ezavo sūnų kunigaikščiai; Ezavo pirmagimio sūnaus Elifazo sūnūs: kunigaikštis Temanas, kunigaikštis Omaras, kunigaikštis Sefojas, kunigaikštis Kenazas,'),
  (@b1, 36, 16, 'kunigaikštis Korachas, kunigaikštis Gatamas ir kunigaikštis Amalekas; šitie yra kunigaikščiai, kilę iš Elifazo, Edomo krašte; šitie buvo Ados sūnūs.'),
  (@b1, 36, 17, 'Ir šitie yra Ezavo sūnaus Reuelio sūnūs: kunigaikštis Nahatas, kunigaikštis Zerachas, kunigaikštis Šama, kunigaikštis Miza; šitie yra kunigaikščiai, kilę iš Reuelio, Edomo krašte; šitie yra Ezavo žmonos Basematos sūnūs.'),
  (@b1, 36, 18, 'Ir šitie yra Ezavo žmonos Aholibamos sūnūs: kunigaikštis Jeušas, kunigaikštis Jaalamas, kunigaikštis Korachas; šitie yra kunigaikščiai, kilę iš Aholibamos, Anos dukters, Ezavo žmonos.'),
  (@b1, 36, 19, 'Šitie yra sūnūs Ezavo, kuris yra Edomas, ir šitie yra jų kunigaikščiai.'),
  (@b1, 36, 20, 'Šitie yra horo Seyro sūnūs, kurie apgyveno kraštą: Lotanas, Šobalas, Sibeonas, Ana,'),
  (@b1, 36, 21, 'Dišonas, Eseras ir Dišanas; šitie yra kunigaikščiai horų, Seyro vaikai Edomo krašte.'),
  (@b1, 36, 22, 'Ir Lotano vaikai buvo Horis ir Hemamas; o Lotano sesuo buvo Timna.'),
  (@b1, 36, 23, 'Ir šitie yra Šobalo vaikai: Alvanas, Manahatas, Ebalas, Šefojas ir Onamas.'),
  (@b1, 36, 24, 'Ir šitie yra Sibeono vaikai: Aja ir Ana; tai tas Ana, kuris rado mulus dykumoje, ganydamas savo tėvo Sibeono asilus.'),
  (@b1, 36, 25, 'Ir šitie yra Anos vaikai: Dišonas ir Anos duktė Aholibama.'),
  (@b1, 36, 26, 'Ir šitie yra Dišono vaikai: Hemdanas, Ešbanas, Itranas ir Keranas.'),
  (@b1, 36, 27, 'Šitie yra Esero vaikai: Bilhanas, Zaavanas ir Akanas.'),
  (@b1, 36, 28, 'Šitie yra Dišano vaikai: Ucas ir Aranas.'),
  (@b1, 36, 29, 'Šitie yra kunigaikščiai, kilę iš horų: kunigaikštis Lotanas, kunigaikštis Šobalas, kunigaikštis Sibeonas, kunigaikštis Ana,'),
  (@b1, 36, 30, 'kunigaikštis Dišonas, kunigaikštis Eseras, kunigaikštis Dišanas; šitie yra kunigaikščiai, kilę iš horų, tarp savų kunigaikščių Seyro krašte.'),
  (@b1, 36, 31, 'Ir šitie yra karaliai, kurie karaliavo Edomo krašte, kai dar joks karalius nekaraliavo Izraelio vaikams.'),
  (@b1, 36, 32, 'Ir Edome karaliavo Beoro sūnus Bela; ir jo miestas vadinosi Dinhaba.'),
  (@b1, 36, 33, 'Ir Belai mirus, jo vietoje karaliavo Zeracho sūnus Jobabas iš Bocros.'),
  (@b1, 36, 34, 'Ir Jobabui mirus, jo vietoje karaliavo Hušamas iš Temano šalies.'),
  (@b1, 36, 35, 'Ir Hušamui mirus, jo vietoje karaliavo Hadadas sūnus Bedado, kuris sumušė Midjaną Moabo laukuose; ir jo miestas vadinosi Avitas.'),
  (@b1, 36, 36, 'Ir Hadadui mirus, jo vietoje karaliavo Samla iš Masrekos.'),
  (@b1, 36, 37, 'Ir Samlai mirus, jo vietoje karaliavo Saulius iš Rehoboto prie upės.'),
  (@b1, 36, 38, 'Ir Sauliui mirus, jo vietoje karaliavo Achboro sūnus Baal-Hananas.'),
  (@b1, 36, 39, 'Ir Achboro sūnui Baal-Hananui mirus, jo vietoje karaliavo Hadaras; ir jo miestas vadinosi Pavas; ir jo žmona vadinosi Mehetabelė, Matredo duktė, Mezahabo duktė.'),
  (@b1, 36, 40, 'Ir šitie yra vardai kunigaikščių, kilusių iš Ezavo, pagal jų šeimas, pagal jų vietas, pagal jų vardus: kunigaikštis Timna, kunigaikštis Alva, kunigaikštis Jetetas,'),
  (@b1, 36, 41, 'kunigaikštis Aholibama, kunigaikštis Ela, kunigaikštis Pinonas,'),
  (@b1, 36, 42, 'kunigaikštis Kenazas, kunigaikštis Temanas, kunigaikštis Mibsaras,'),
  (@b1, 36, 43, 'kunigaikštis Magdielis, kunigaikštis Iramas; šitie yra Edomo kunigaikščiai pagal jų buveines jų nuosavybės šalyje; jis yra Ezavas, edomitų tėvas.'),
  (@b1, 37, 1, 'Ir Jokūbas gyveno šalyje, kurioje jo tėvas buvo ateivis, Kanaano šalyje.'),
  (@b1, 37, 2, 'Šita yra Jokūbo giminė. Juozapas, būdamas septyniolikos metų, ganė su savo broliais kaimenę; ir tas berniukas buvo su savo tėvo žmonų Bilhos ir Zilpos sūnumis; ir Juozapas parnešdavo savo tėvui apie juos piktus atsiliepimus.'),
  (@b1, 37, 3, 'Na, o Izraelis mylėjo Juozapą labiau už visus savo vaikus, nes jis buvo jo senatvės sūnus; ir jis padarė jam margaspalvį apdarą.'),
  (@b1, 37, 4, 'Ir jo broliai pamatę, kad jų tėvas jį mylėjo labiau už visus jo brolius, jie nekentė jo ir negalėjo su juo taikingai kalbėti.'),
  (@b1, 37, 5, 'Ir Juozapas sapnavo sapną ir papasakojo jį savo broliams; ir jie dar labiau jo nekentė.'),
  (@b1, 37, 6, 'Ir jis jiems tarė: „Meldžiu jus, pasiklausykite šio sapno, kurį sapnavau;'),
  (@b1, 37, 7, 'štai mes rišome pėdus ant lauko, ir štai mano pėdas atsikėlė ir stovėjo tiesiai; ir štai jūsų pėdai sustojo aplinkui ratu ir nusilenkė mano pėdui“.'),
  (@b1, 37, 8, 'Ir jo broliai jam tarė: „Ar tu tikrai mums karaliausi? Ar tu tikrai mums viešpatausi?“ Ir jie dar labiau jo nekentė dėl jo sapnų ir dėl jo žodžių.'),
  (@b1, 37, 9, 'Ir jis sapnavo dar kitą sapną ir jį papasakojo savo broliams, ir sakė: „Štai aš sapnavau dar kitą sapną; ir štai saulė, mėnulis ir vienuolika žvaigždžių man nusilenkė“.'),
  (@b1, 37, 10, 'Ir jis tai papasakojo savo tėvui ir savo broliams; ir jo tėvas jį barė ir jam tarė: „Kas tai per sapnas, kurį sapnavai? Argi aš, tavo motina ir tavo broliai tikrai ateisime nusilenkti tau iki žemės?“'),
  (@b1, 37, 11, 'Ir jo broliai jam pavydėjo; bet jo tėvas įsidėmėjo šitą pasakymą.'),
  (@b1, 37, 12, 'Ir jo broliai nuėjo ganyti savo tėvo kaimenę Šecheme.'),
  (@b1, 37, 13, 'Ir Izraelis tarė Juozapui: „Ar tavo broliai negano kaimenės Šecheme? Ateik, ir aš tave nusiųsiu pas juos“. Ir jis jam tarė: „Aš čia“.'),
  (@b1, 37, 14, 'Ir jis jam tarė: „Eik, meldžiu tave, pažiūrėk, ar gerai sekasi tavo broliams ir kaimenėms; ir parnešk man žinią“. Taigi jis išsiuntė jį iš Hebrono slėnio, ir jis atėjo į Šechemą.'),
  (@b1, 37, 15, 'Ir vienas žmogus užtiko jį, štai beklaidžiojantį ant lauko; ir tas žmogus jį paklausė, sakydamas: „Ko ieškai?“'),
  (@b1, 37, 16, 'Ir jis tarė: „Savo brolių ieškau; meldžiu tave, pasakyk man, kur jie gano savo kaimenes“.'),
  (@b1, 37, 17, 'Ir tas vyras tarė: „Jie iš čia išėję; nes girdėjau juos sakant: ‘Vykime į Dotaną’. Ir Juozapas ėjo paskui savo brolius ir juos rado Dotane.'),
  (@b1, 37, 18, 'Ir pamatę jį iš tolo, jam dar nepriartėjus prie jų, jie susimokė prieš jį, kad jį nužudytų.'),
  (@b1, 37, 19, 'Ir jie sakė vienas kitam: „Štai ateina tas sapnuotojas.'),
  (@b1, 37, 20, 'Taigi dabar eikime, užmuškime jį, įmeskime jį į kokią duobę ir sakykime: ‘Kažkoks piktas žvėris jį suėdė’; ir mes pamatysime, kas bus iš jo sapnų“.'),
  (@b1, 37, 21, 'Ir Rubenas, tai išgirdęs, išgelbėjo jį iš jų rankų; ir tarė: „Nežudykime jo“.'),
  (@b1, 37, 22, 'Ir Rubenas jiems tarė: „Neišliekite kraujo, bet įmeskite jį į šitą dykumoje esančią duobę ir nepridėkite prie jo rankos“; kad jis jį išgelbėtų iš jų rankų, kad grąžintų jį jo tėvui.'),
  (@b1, 37, 23, 'Ir įvyko, kai Juozapas atėjo pas savo brolius, jie nuvilko nuo Juozapo jo apdarą, jo margaspalvį apdarą, kuris buvo ant jo;'),
  (@b1, 37, 24, 'ir paėmę jį, jie įmetė jį į duobę; o duobė buvo tuščia, joje nebuvo vandens.'),
  (@b1, 37, 25, 'Ir jie susėdo duonos valgyti; ir pakėlę savo akis pažiūrėjo, ir štai išmaelitų būrys atėjo iš Gileado su savo kupranugariais, nešančiais prieskonius, balzamą ir mirą, einančiais, kad nugabentų tai žemyn į Egiptą.'),
  (@b1, 37, 26, 'Ir Juda tarė savo broliams: „Kokia nauda, jei užmušime savo brolį ir paslėpsime jo kraują?'),
  (@b1, 37, 27, 'Eime, parduokime jį išmaelitams, o mūsų ranka tenebūna ant jo; nes jis yra mūsų brolis, mūsų kūnas“. Ir jo broliai sutiko.'),
  (@b1, 37, 28, 'Tada ėjo pro šalį midjaniečiai pirkliai; ir jie traukdami iškėlė Juozapą iš duobės ir pardavė Juozapą išmaelitams už dvidešimt sidabrinių; o jie nugabeno Juozapą į Egiptą.'),
  (@b1, 37, 29, 'Ir Rubenas sugrįžo prie duobės; ir štai Juozapo nebuvo duobėje; ir jis perplėšė savo drabužius.'),
  (@b1, 37, 30, 'Ir jis sugrįžo pas savo brolius ir tarė: „Vaiko nėra; o aš, kur aš eisiu?“'),
  (@b1, 37, 31, 'Ir jie paėmė Juozapo apdarą ir, papjovę ožiuką, apdarą pamirkė kraujyje;'),
  (@b1, 37, 32, 'ir jie nusiuntė margaspalvį apdarą ir nunešė jį savo tėvui; ir tarė: „Šitą mes radome; dabar atpažink, ar tai tavo sūnaus apdaras, ar ne?“'),
  (@b1, 37, 33, 'Ir jis atpažino jį ir tarė: „Tai mano sūnaus apdaras; piktas žvėris jį suėdė; be abejonės Juozapas sudraskytas į gabalus“.'),
  (@b1, 37, 34, 'Ir Jokūbas perplėšė savo drabužius, užsidėjo ašutinę ant strėnų ir daugelį dienų gedėjo savo sūnaus.'),
  (@b1, 37, 35, 'Ir visi jo sūnūs ir visos jo dukterys pakilo jo guosti; tačiau jis nesutiko būti paguostas; ir jis tarė: „Nes aš gedėdamas nusileisiu į kapą pas savo sūnų“. Taip jį apraudojo jo tėvas.'),
  (@b1, 37, 36, 'O midjaniečiai jį pardavė Egipte Potifarui, faraono pareigūnui, sargybos vadui.'),
  (@b1, 38, 1, 'Ir įvyko anuo laiku, kad Juda ėjo žemyn nuo savo brolių ir pasuko pas vieną adulamietį, kurio vardas Hyra.'),
  (@b1, 38, 2, 'Ir Juda ten pamatė dukterį vieno kanaaniečio, kurio vardas Šūva; ir jis ją ėmė ir įėjo pas ją.'),
  (@b1, 38, 3, 'Ir ji pastojo ir pagimdė sūnų; ir jis praminė jį vardu Eras.'),
  (@b1, 38, 4, 'Ir ji vėl pastojo ir pagimdė sūnų; ir ji praminė jį vardu Onanas.'),
  (@b1, 38, 5, 'Ir ji vėl dar pastojo ir pagimdė sūnų; ir praminė jį vardu Šela; ir jis buvo Kezibe, kai ji pagimdė jį.'),
  (@b1, 38, 6, 'Ir Juda paėmė savo pirmagimiui Erui žmoną, kurios vardas Tamara.'),
  (@b1, 38, 7, 'Bet Eras, Judos pirmagimis, buvo nedoras VIEŠPATIES akyse; ir VIEŠPATS jį užmušė.'),
  (@b1, 38, 8, 'Ir Juda tarė Onanui: „Įeik pas savo brolio žmoną ir vesk ją, ir prikelk savo broliui sėklą“.'),
  (@b1, 38, 9, 'Ir Onanas žinojo, kad ta sėkla nebus jo; ir įvyko, kai jis įėjo pas savo brolio žmoną, jis išleido ją ant žemės, kad neduotų savo broliui sėklos.'),
  (@b1, 38, 10, 'Ir VIEŠPAČIUI nepatiko tai, ką jis darė; todėl jis ir jį užmušė.'),
  (@b1, 38, 11, 'Tuomet Juda tarė savo marčiai Tamarai: „Pasilik našle savo tėvo namuose, kol užaugs mano sūnus Šela“; nes jis tarė: „Kad ir jis nemirtų kaip jo broliai“. Ir Tamara nuėjusi gyveno savo tėvo namuose.'),
  (@b1, 38, 12, 'Ir laikui bėgant mirė Šūvos duktė, Judos žmona; ir Juda pasiguodęs ėjo aukštyn į Timną pas savo avių kirpėjus, jis ir jo draugas adulamietis Hyra.'),
  (@b1, 38, 13, 'Ir tai buvo pranešta Tamarai, sakant: „Štai tavo uošvis eina aukštyn į Timną savo avių kirpti“.'),
  (@b1, 38, 14, 'Ir ji nusivilko savo našlės drabužius, apsidengė šydu, apsivyniojo ir atsisėdo atviroje vietoje, kuri yra pakeliui į Timną; nes ji matė, kad Šela buvo užaugęs, tačiau ji nebuvo duota jam į žmonas.'),
  (@b1, 38, 15, 'Juda, ją pamatęs, manė ją esant paleistuve; nes ji buvo apsidengusi veidą.'),
  (@b1, 38, 16, 'Ir jis pasuko pas ją palei kelią ir tarė: „Na, meldžiu tave, leisk man įeiti pas tave“ (nes jis nežinojo, kad ji buvo jo marti). O ji tarė: „Ką man duosi, idant įeitum pas mane?“'),
  (@b1, 38, 17, 'Ir jis tarė: „Aš tau atsiųsiu ožiuką iš kaimenės“. O ji tarė: „Ar man duosi užstatą, kol jį atsiųsi?“'),
  (@b1, 38, 18, 'Ir jis tarė: „Kokį užstatą tau duoti?“ Ir ji tarė: „Tavo antspaudo žiedą, tavo apyrankę ir tavo lazdą, esančią tavo rankoje“. Ir jis tai jai davė ir įėjo pas ją, ir ji nuo jo pastojo.'),
  (@b1, 38, 19, 'Ir ji atsikėlusi nuėjo ir, pasidėjusi šalia šydą nuo savęs, apsivilko savo našlystės drabužiais.'),
  (@b1, 38, 20, 'Ir Juda nusiuntė ožiuką per savo draugo adulamiečio ranką, kad atsiimtų iš moters rankos savo užstatą; bet jis jos nerado.'),
  (@b1, 38, 21, 'Tada jis klausinėjo tos vietos žmonių, sakydamas: „Kur yra ta paleistuvė, kuri buvo atvirai pakelėje?“ Ir jie tarė: „Čia šioje vietoje nebuvo jokios paleistuvės“.'),
  (@b1, 38, 22, 'Ir jis sugrįžo pas Judą ir tarė: „Negaliu jos rasti; ir taip pat tos vietos žmonės sakė, kad čia, šioje vietoje, nebuvo jokios paleistuvės.'),
  (@b1, 38, 23, 'Ir Juda tarė: „Tegul ji tai pasiima sau, kad nebūtume sugėdinti; štai aš nusiunčiau šitą ožiuką, bet tu jos neradai“.'),
  (@b1, 38, 24, 'Ir įvyko, kad maždaug po trijų mėnesių Judai buvo pranešta, sakant: „Tavo marti Tamara paleistuvavo; ir dargi, štai per paleistuvavimą ji yra nėščia“. Ir Juda tarė: „Išveskite ją, tebūna ji sudeginta“.'),
  (@b1, 38, 25, 'Kai ji buvo išvesta, ji nusiuntė savo uošviui, sakydama: „Nuo to vyro, kurio yra šitie, aš esu nėščia“; ir ji tarė: „Atpažink, meldžiu tave, kieno yra šitie: antspaudo žiedas, apyrankė ir lazda“.'),
  (@b1, 38, 26, 'Ir Juda atpažino juos ir tarė: „Ji yra teisesnė už mane; kadangi aš jos nedaviau savo sūnui Šelai“. Ir jis jos daugiau nepažino.'),
  (@b1, 38, 27, 'Ir įvyko, jos gimdymo skausmų metu štai dvyniai buvo jos įsčiose.'),
  (@b1, 38, 28, 'Ir įvyko, kai ji buvo gimdymo skausmuose, vienas iškišo savo ranką; ir pribuvėja paėmusi užrišo ant jo rankos skaisčiai raudoną siūlą, tardama: „Šitas pirmas išėjo“.'),
  (@b1, 38, 29, 'Ir įvyko, kai jis įtraukė atgal savo ranką, štai išėjo jo brolis; ir ji tarė: „Kaip tu prasiveržei? Šis plyšys bus ant tavęs“; todėl jį praminė vardu Peresas.'),
  (@b1, 38, 30, 'O paskui išėjo jo brolis, kuris ant savo rankos turėjo skaisčiai raudoną siūlą; ir jis buvo pramintas vardu Zerachas.'),
  (@b1, 39, 1, 'Ir Juozapas buvo nuvestas žemyn į Egiptą; ir egiptietis Potifaras, faraono pareigūnas, sargybos vadas, jį nupirko iš išmaelitų rankų, kurie jį buvo ten nugabenę.'),
  (@b1, 39, 2, 'Ir VIEŠPATS buvo su Juozapu, ir jis buvo klestintis vyras; ir jis buvo savo šeimininko egiptiečio namuose.'),
  (@b1, 39, 3, 'Ir jo šeimininkas matė, kad VIEŠPATS buvo su juo, ir kad VIEŠPATS padarė, jog klestėtų jo rankose viskas, ką jis bedarė.'),
  (@b1, 39, 4, 'Ir Juozapas rado malonę jo akyse ir jam tarnavo; ir jis paskyrė jį savo namų prievaizdu ir visa, ką turėjo, jis padavė į jo rankas.'),
  (@b1, 39, 5, 'Ir įvyko, kad nuo to laiko, kai jis jį paskyrė prižiūrėtoju savo namuose ir visko, ką jis turėjo, VIEŠPATS dėl Juozapo laimino egiptiečio namus; ir VIEŠPATIES palaiminimas buvo ant visko, ką jis turėjo namuose ir ant lauko.'),
  (@b1, 39, 6, 'Ir visa, ką turėjo, jis paliko Juozapo rankose; ir jis apie nieką, ką turėjo, nežinojo, o tik apie duoną, kurią valgė. O Juozapas buvo dailus ir gražios išvaizdos.'),
  (@b1, 39, 7, 'Ir įvyko po šių dalykų, kad jo šeimininko žmona ant Juozapo padėjo akį; ir ji tarė: „Gulkis su manimi“.'),
  (@b1, 39, 8, 'Bet jis atsisakė ir tarė savo šeimininko žmonai: „Štai mano šeimininkas nežino, kas su manimi namuose, ir jis man patikėjo visa, ką jis turi, į mano rankas;'),
  (@b1, 39, 9, 'šiuose namuose nėra nei vieno didesnio už mane; ir jis neužlaikė nieko nuo manęs, išskyrus tave, nes tu jo žmona; tad kaip aš galiu padaryti tokią didelę piktybę ir nusidėti Dievui?“'),
  (@b1, 39, 10, 'Ir įvyko, kai ji dieną po dienos kalbėjo Juozapui, jis jos neklausė, kad prie jos atsigultų ar kad su ja pabūtų.'),
  (@b1, 39, 11, 'Ir įvyko maždaug tuo laiku, kad Juozapas įėjo į namus atlikti savo darbo; ir nei vieno iš tų namų žmonių ten viduje nebuvo.'),
  (@b1, 39, 12, 'Ir ji nutvėrė jį už jo drabužio, sakydama: „Gulkis su manimi“; bet jis, palikęs savo drabužį jos rankoje, pabėgo ir išėjo laukan.'),
  (@b1, 39, 13, 'Ir įvyko, kai ji pamatė, kad jis paliko savo drabužį jos rankoje ir buvo išbėgęs,'),
  (@b1, 39, 14, 'ji pašaukė savo namų žmones ir jiems kalbėjo, sakydama: „Štai jis atvedė mums hebrają, kad mus išjuoktų; jis įėjo pas mane gulėti su manimi, bet aš šaukiau garsiu balsu;'),
  (@b1, 39, 15, 'ir įvyko, kai jis išgirdo, kad aš šaukiau pakeltu balsu, jis paliko savo drabužį pas mane ir pabėgęs išėjo laukan“.'),
  (@b1, 39, 16, 'Ir ji pasidėjo jo drabužį šalia savęs, kol jo viešpats parėjo į namus.'),
  (@b1, 39, 17, 'Ir ji jam kalbėjo pagal šiuos žodžius, sakydama: „Tas hebrajas tarnas, kurį mums atvedei, pas mane įėjo, kad mane išjuoktų;'),
  (@b1, 39, 18, 'ir įvyko, kai aš šaukiau pakeltu balsu, jis paliko savo drabužį pas mane ir pabėgo laukan“.'),
  (@b1, 39, 19, 'Ir įvyko, kai jo šeimininkas išgirdo savo žmonos žodžius, kuriuos ji jam kalbėjo, sakydama: „Šitaip tavo tarnas man padarė“, užsidegė jo rūstybė.'),
  (@b1, 39, 20, 'Ir Juozapo šeimininkas jį paėmęs pasodino jį į kalėjimą, į vietą, kur kalėjo karaliaus kaliniai; ir jis buvo ten kalėjime.'),
  (@b1, 39, 21, 'Bet VIEŠPATS buvo su Juozapu ir parodė jam gailestingumą bei davė jam palankumą kalėjimo prižiūrėtojo akyse.'),
  (@b1, 39, 22, 'Ir kalėjimo prižiūrėtojas pavedė Juozapui į rankas visus kalinius, esančius kalėjime; ir ką jie ten darė, jis buvo to darytojas.'),
  (@b1, 39, 23, 'Kalėjimo prižiūrėtojas nesirūpino niekuo, kas buvo pavaldu jo rankai; nes VIEŠPATS buvo su juo, ir ką jis darė, VIEŠPATS padarė, kad tai klestėtų.'),
  (@b1, 40, 1, 'Ir įvyko po šitų dalykų, kad Egipto karaliaus taurininkas ir jo kepėjas nusikalto savo viešpačiui, Egipto karaliui.'),
  (@b1, 40, 2, 'Ir faraonas buvo užsirūstinęs ant abiejų savo pareigūnų, ant taurininkų vyriausiojo ir kepėjų vyriausiojo.'),
  (@b1, 40, 3, 'Ir jis uždarė juos saugoti sargybos vado namuose, į kalėjimą, į vietą, kur kalėjo Juozapas.'),
  (@b1, 40, 4, 'Ir sargybos vadas įpareigojo dėl jų Juozapą, ir jis jiems patarnavo; ir jie liko saugojami kurį laiką.'),
  (@b1, 40, 5, 'Ir jie abu sapnavo sapną, kiekvienas savąjį sapną tą pačią naktį, kiekvienas pagal savo sapno aiškinimą, Egipto karaliaus taurininkas ir kepėjas, kurie kalėjo kalėjime.'),
  (@b1, 40, 6, 'Ir ryte Juozapas įėjo pas juos ir į juos pažvelgė, ir štai jie buvo liūdni.'),
  (@b1, 40, 7, 'Ir jis paklausė faraono pareigūnų, esančių su juo jo viešpaties namų daboklėje, sakydamas: „Kodėl šiandien jūs taip liūdnai atrodote?“'),
  (@b1, 40, 8, 'Ir jie jam tarė: „Mes sapnavome sapną, bet nėra jo aiškintojo“. Ir Juozapas jiems tarė: „Argi aiškinimai nepriklauso Dievui? Papasakokite juos man, meldžiu jus“.'),
  (@b1, 40, 9, 'Ir vyriausiasis taurininkas papasakojo savo sapną Juozapui ir jam tarė: „Mano sapne štai prieš mane buvo vynmedis;'),
  (@b1, 40, 10, 'ir tame vynmedyje buvo trys šakos; ir jis buvo tarsi išleidęs pumpurus ir išskleidęs savo žiedus; ir jo kekės davė prisirpusių vynuogių;'),
  (@b1, 40, 11, 'ir faraono taurė buvo mano rankoje; ir aš paėmiau tas vynuoges, jas išspaudžiau į faraono taurę ir tą taurę padaviau faraonui į ranką“.'),
  (@b1, 40, 12, 'Ir Juozapas jam tarė: „Šis yra jo aiškinimas: tos trys šakos tai trys dienos;'),
  (@b1, 40, 13, 'trijų dienų laikotarpyje faraonas pakels tavo galvą ir tave sugrąžins į tavo vietą; ir tu paduosi faraonui taurę į jo ranką pagal ankstesnįjį būdą, kai buvai jo taurininkas.'),
  (@b1, 40, 14, 'Tik prisimink mane, kai tau gerai seksis, ir parodyk, meldžiu tave, man gerumą, ir paminėk mane faraonui, ir išvesk mane iš šitų namų;'),
  (@b1, 40, 15, 'nes tikrai aš buvau pavogtas iš hebrajų šalies; o taip pat ir čia nieko nesu padaręs, kad jie pasodintų mane į požeminį kalėjimą“.'),
  (@b1, 40, 16, 'Vyriausiasis kepėjas, pamatęs, kad aiškinimas buvo geras, tarė Juozapui: „Aš irgi buvau savo sapne, ir štai aš turėjau tris baltas pintines ant savo galvos;'),
  (@b1, 40, 17, 'ir viršutinėje pintinėje buvo visokių kepinių faraonui; ir paukščiai juos lesė iš pintinės ant mano galvos“.'),
  (@b1, 40, 18, 'Ir Juozapas atsakydamas tarė: „Šis yra jo aiškinimas: tos trys pintinės – tai trys dienos;'),
  (@b1, 40, 19, 'trijų dienų laikotarpyje faraonas pakels tavo galvą nuo tavęs ir pakars tave ant medžio; ir paukščiai les nuo tavęs tavo kūną“.'),
  (@b1, 40, 20, 'Ir įvyko trečiąją dieną, kai buvo faraono gimtadienis, jis iškėlė puotą visiems savo tarnams; ir jis pakėlė vyriausiojo taurininko ir vyriausiojo kepėjo galvą tarp savo tarnų.'),
  (@b1, 40, 21, 'Ir jis sugrąžino vyriausiąjį taurininką į jo taurininkystę; ir jis padavė taurę į faraono ranką;'),
  (@b1, 40, 22, 'bet vyriausiąjį kepėją jis pakorė; kaip jiems buvo išaiškinęs Juozapas.'),
  (@b1, 40, 23, 'Tačiau vyriausiasis taurininkas neprisiminė Juozapo, bet jį pamiršo.'),
  (@b1, 41, 1, 'Ir įvyko dvejų pilnų metų pabaigoje, kad faraonas sapnavo; ir štai jis stovėjo prie upės.'),
  (@b1, 41, 2, 'Ir štai iš upės išlipo septynios dailios išvaizdos karvės ir riebaus kūno; ir jos ganėsi pievoje.'),
  (@b1, 41, 3, 'Ir štai po jų išlipo iš upės kitos septynios karvės, bjaurios išvaizdos ir lieso kūno; ir atsistojo šalia anų karvių ant upės kranto.'),
  (@b1, 41, 4, 'Ir bjaurios išvaizdos bei lieso kūno karvės suėdė septynias gražios išvaizdos ir riebias karves. Taigi faraonas prabudo.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 41, 5, 'Ir jis miegojo ir sapnavo antrą kartą: ir štai septynios javų varpos išaugo ant vieno stiebo, vešlios ir geros.'),
  (@b1, 41, 6, 'Ir štai po jų išdygo septynios plonos ir rytų vėjo išdžiovintos varpos.'),
  (@b1, 41, 7, 'Ir septynios plonosios varpos prarijo septynias vešliąsias ir pilnąsias varpas. Ir faraonas prabudo, ir štai tai buvo sapnas.'),
  (@b1, 41, 8, 'Ir įvyko ryte, kad jo dvasia nerimavo; ir jis siuntė ir pakvietė visus Egipto burtininkus ir visus jo išminčius; ir faraonas jiems papasakojo savo sapną; bet nebuvo nei vieno, kuris galėtų juos išaiškinti faraonui.'),
  (@b1, 41, 9, 'Tada vyriausiasis taurininkas kalbėjo faraonui, sakydamas: „Aš šią dieną prisimenu savo kaltes;'),
  (@b1, 41, 10, 'faraonas buvo užsirūstinęs ant savo tarnų ir įkalino mane sargybos vado namuose, tiek mane, tiek vyriausiąjį kepėją;'),
  (@b1, 41, 11, 'ir vieną naktį aš ir jis sapnavome sapną; mes sapnavome kiekvienas pagal savo sapno aiškinimą.'),
  (@b1, 41, 12, 'Ir ten buvo su mumis jaunas vyras, hebrajas, sargybos vado tarnas; ir mes jam papasakojome, o jis mums išaiškino mūsų sapnus; išaiškino kiekvienam pagal kiekvieno sapną.'),
  (@b1, 41, 13, 'Ir įvyko, kaip jis mums išaiškino, taip ir buvo: mane jis sugrąžino į mano tarnybą, o jį jis pakorė“.'),
  (@b1, 41, 14, 'Tada faraonas pasiuntė ir pašaukė Juozapą, ir jie skubiai jį išvedė iš požeminio kalėjimo; ir jis nusiskutęs ir pasikeitęs drabužius įėjo pas faraoną.'),
  (@b1, 41, 15, 'Ir faraonas tarė Juozapui: „Aš sapnavau sapną, o nėra nei vieno, kuris galėtų jį išaiškinti; bet aš girdėjau sakant apie tave, kad tu gali suprasti sapną, kad jį išaiškintum“.'),
  (@b1, 41, 16, 'Ir Juozapas atsakė faraonui, sakydamas: „Tai nėra manyje; Dievas duos faraonui taikingą atsakymą“.'),
  (@b1, 41, 17, 'Ir faraonas tarė Juozapui: „Savo sapne štai aš stovėjau ant upės kranto;'),
  (@b1, 41, 18, 'ir štai iš upės išlipo septynios karvės, riebaus kūno ir dailios išvaizdos, ir jos ganėsi pievoje;'),
  (@b1, 41, 19, 'ir štai po jų išlipo kitos septynios karvės, menkos, labai bjaurios išvaizdos ir sulysusios, tokios prastos, kokių nesu matęs visoje Egipto šalyje;'),
  (@b1, 41, 20, 'ir liesosios bei bjaurios išvaizdos karvės suėdė pirmąsias septynias riebiąsias karves;'),
  (@b1, 41, 21, 'ir kai jos jas suėdė, nebuvo galima pažinti, kad jos buvo jas suėdusios; bet jos vis dar buvo bjaurios išvaizdos, kaip pradžioje. Taigi aš pabudau.'),
  (@b1, 41, 22, 'Ir aš savo sapne regėjau, ir štai septynios varpos išaugo ant vieno stiebo, pilnos ir gražios;'),
  (@b1, 41, 23, 'ir štai po jų išdygo septynios sudžiūvusios, plonos, rytų vėjo išdžiovintos varpos;'),
  (@b1, 41, 24, 'ir plonosios varpos prarijo septynias gražiąsias varpas; ir aš tai papasakojau burtininkams; bet nebuvo nei vieno, kuris galėtų man jį išaiškinti“.'),
  (@b1, 41, 25, 'Ir Juozapas tarė faraonui: „Faraono sapnas yra vienas; Dievas parodė faraonui, ką jis ketina daryti.'),
  (@b1, 41, 26, 'Septynios gražiosios karvės – tai septyneri metai; ir septynios gražiosios varpos – tai septyneri metai; sapnas yra vienas.'),
  (@b1, 41, 27, 'Ir septynios liesosios ir bjaurios išvaizdos karvės, išlipusios po jų, tai septyneri metai; ir septynios tuščiosios, rytų vėjo išdžiovintos varpos, bus septyneri bado metai.'),
  (@b1, 41, 28, 'Šis yra dalykas, kurį aš pasakiau faraonui: ‘Dievas parodo faraonui, ką jis ketina daryti’.'),
  (@b1, 41, 29, 'Štai ateina septyneri didelio pertekliaus metai visoje Egipto šalyje;'),
  (@b1, 41, 30, 'bet po jų kils septyneri bado metai; ir bus pamirštas visas perteklius Egipto šalyje; ir badas sunaikins šalį;'),
  (@b1, 41, 31, 'ir perteklius nebebus žinomas šalyje dėl to bado, kuris seks paskui; nes jis bus labai sunkus.'),
  (@b1, 41, 32, 'O kad sapnas dusyk pakartotas faraonui; tai todėl, kad tas dalykas yra Dievo įtvirtintas, ir Dievas netrukus jį įvykdys.'),
  (@b1, 41, 33, 'Taigi dabar faraonas teieško protingo ir išmintingo žmogaus ir tepastato jį Egipto šalies valdytoju.'),
  (@b1, 41, 34, 'Tedaro tai faraonas ir tepaskiria šaliai pareigūnų ir tepaima penktąją Egipto šalies dalį per septynerius pertekliaus metus.'),
  (@b1, 41, 35, 'Ir tesurenka jie visą šitų ateinančių gerųjų metų maistą ir tekaupia javus faraono rankai vadovaujant, ir tesaugo jie maistą miestuose.'),
  (@b1, 41, 36, 'Ir tas maistas bus atsarga šaliai septyneriems bado metams, kurie bus Egipto šalyje; kad šalis per badą nepražūtų“.'),
  (@b1, 41, 37, 'Ir tas dalykas buvo geras faraono akyse ir visų jo tarnų akyse.'),
  (@b1, 41, 38, 'Ir faraonas tarė savo tarnams: „Ar berasime tokį žmogų, kaip šis, kuriame yra Dievo Dvasia?“'),
  (@b1, 41, 39, 'Ir faraonas tarė Juozapui: „Kadangi Dievas tau visa tai apreiškė, tai nėra nei vieno tokio protingo ir išmintingo, kaip tu;'),
  (@b1, 41, 40, 'tu būsi mano namų valdovas ir pagal tavo žodį bus valdoma visa mano tauta; tik sostu aš būsiu didesnis už tave“.'),
  (@b1, 41, 41, 'Ir faraonas tarė Juozapui: „Štai aš tave pastačiau visos Egipto šalies valdovu“.'),
  (@b1, 41, 42, 'Ir faraonas numovė nuo savo rankos savo žiedą ir jį užmovė ant Juozapo rankos ir apvilko jį plonos drobės drabužiais, ir užkabino jam ant kaklo auksinę grandinę;'),
  (@b1, 41, 43, 'ir jis davė jam važiuoti antrajame vežime, kurį jis turėjo; ir jie šaukė pirma jo: „Klaupkitės“; ir jis jį padarė visos Egipto šalies valdovu.'),
  (@b1, 41, 44, 'Ir faraonas pasakė Juozapui: „Aš esu faraonas, ir be tavęs niekas nepakels savo rankos ar kojos visoje Egipto šalyje“.'),
  (@b1, 41, 45, 'Ir faraonas praminė Juozapą vardu Safnat-Paneachas; ir jis jam davė į žmonas Asenatą, Ono kunigo Poti-Feros dukterį. Ir Juozapas išvyko po visą Egipto šalį.'),
  (@b1, 41, 46, 'Ir Juozapas buvo trisdešimties metų, kai jis stovėjo prieš Egipto karalių faraoną. Ir Juozapas, išėjęs nuo faraono akivaizdos, ėjo po visą Egipto šalį.'),
  (@b1, 41, 47, 'Ir per septynerius pertekliaus metus žemė davė saujomis.'),
  (@b1, 41, 48, 'Ir jis surinko visą maistą septynerių metų, kurie buvo Egipto šalyje, ir sukaupė maistą miestuose; maistą laukų, esančių aplink kiekvieną miestą, sukaupė tame mieste.'),
  (@b1, 41, 49, 'Ir Juozapas surinko grūdų labai daug, kaip jūros smėlio, kol liovėsi skaičiavęs; nes jų buvo be skaičiaus.'),
  (@b1, 41, 50, 'Ir prieš užeinant bado metams, Juozapui gimė du sūnūs, kuriuos jam pagimdė Asenata, Ono kunigo Poti-Feros duktė.'),
  (@b1, 41, 51, 'Ir Juozapas praminė pirmagimį vardu Manasas; jis sakė: „Nes Dievas padarė, kad pamirščiau visą mano vargą ir visus mano tėvo namus“.'),
  (@b1, 41, 52, 'O antrąjį jis praminė vardu Efraimas: „Nes Dievas padarė, kad būčiau vaisingas mano sielvarto šalyje“.'),
  (@b1, 41, 53, 'Ir pasibaigė septyneri metai pertekliaus, kuris buvo Egipto šalyje.'),
  (@b1, 41, 54, 'Ir priartėjo septyneri bado metai, kaip Juozapas buvo sakęs; ir badas buvo visose šalyse; tačiau visoje Egipto šalyje buvo duonos.'),
  (@b1, 41, 55, 'Ir visai Egipto šaliai ėmus badauti, tauta šaukėsi faraono dėl duonos; ir faraonas tarė visiems egiptiečiams: „Eikite pas Juozapą; darykite, ką jis jums sakys“.'),
  (@b1, 41, 56, 'Ir badas buvo ant viso žemės paviršiaus; ir Juozapas atidarė visus sandėlius ir pardavinėjo egiptiečiams; ir badas Egipto šalyje ėjo sunkyn.'),
  (@b1, 41, 57, 'Ir visos šalys atėjo į Egiptą pas Juozapą javų pirkti; nes badas visose šalyse buvo toks sunkus.'),
  (@b1, 42, 1, 'Na, o kai Jokūbas pamatė, kad Egipte buvo javų, Jokūbas tarė savo sūnums: „Ko žiūrite vienas į kitą?“'),
  (@b1, 42, 2, 'Ir jis tarė: „Štai aš girdėjau, kad yra javų Egipte; nueikite ten žemyn ir mums nupirkite iš ten; kad gyventume ir nemirtume“.'),
  (@b1, 42, 3, 'Ir dešimt Juozapo brolių leidosi pirkti javų iš Egipto.'),
  (@b1, 42, 4, 'Tačiau Juozapo brolio Benjamino Jokūbas nepasiuntė su jo broliais; nes jis tarė: „Kad kartais jam neatsitiktų nelaimė“.'),
  (@b1, 42, 5, 'Ir tarp atvykusiųjų ir Izraelio sūnūs atėjo javų pirkti; nes badas buvo Kanaano šalyje.'),
  (@b1, 42, 6, 'O Juozapas buvo šalies valdytojas, ir jis buvo tas, kuris pardavinėjo visai šalies tautai; ir atėję Juozapo broliai nusilenkė prieš jį veidais į žemę.'),
  (@b1, 42, 7, 'Ir Juozapas, pamatęs savo brolius, pažino juos, bet jiems rodėsi tarsi svetimas ir šiurkščiai su jais kalbėjo; ir jis tarė jiems: „Iš kur atvykote?“ Ir jie tarė: „Iš Kanaano šalies maisto pirkti“.'),
  (@b1, 42, 8, 'O Juozapas pažino savo brolius, tačiau jie nepažino jo.'),
  (@b1, 42, 9, 'Ir Juozapas atsiminė sapnus, kuriuos apie juos sapnavo, ir jiems tarė: „Jūs esate žvalgai; jūs atvykote apžiūrėti šios šalies nuogumo“.'),
  (@b1, 42, 10, 'O jie jam tarė: „Ne, mano viešpatie, tavo tarnai atėjo maisto nusipirkti.'),
  (@b1, 42, 11, 'Mes visi esame vieno vyro sūnūs; mes esame dori žmonės, tavo tarnai nėra žvalgai“.'),
  (@b1, 42, 12, 'O jis jiems tarė: „Ne, šalies nuogumo jūs atėjote apžiūrėti“.'),
  (@b1, 42, 13, 'Ir jie tarė: „Tavo tarnų yra dvylika brolių, vieno vyro sūnūs Kanaano šalyje; ir štai jauniausiasis šią dieną yra pas mūsų tėvą, o vieno nebėra“.'),
  (@b1, 42, 14, 'Ir Juozapas jiems tarė: „Yra taip, kaip jums pasakiau, sakydamas: ‘Jūs esate žvalgai’;'),
  (@b1, 42, 15, 'tuo būsite išmėginti: kaip gyvas faraonas, jūs neišeisite iš čia, jei čia neatvyks jūsų jauniausiasis brolis.'),
  (@b1, 42, 16, 'Pasiųskite vieną iš jūsų, ir jis teatveda jūsų brolį, o jūs būsite laikomi kalėjime, kad būtų išmėginti jūsų žodžiai, ar jumyse yra tiesos; o kitaip, kaip gyvas faraonas, tikrai jūs esate žvalgai“.'),
  (@b1, 42, 17, 'Ir trims dienoms jis įdavė juos kartu sargybai.'),
  (@b1, 42, 18, 'Ir trečiąją dieną Juozapas jiems tarė: „Tai darykite ir gyvensite; nes aš bijau Dievo;'),
  (@b1, 42, 19, 'jei jūs esate dori, tegul vienas iš jūsų brolių lieka sulaikytas jūsų kalėjimo namuose; jūs eikite, neškite javų dėl jūsų namų bado;'),
  (@b1, 42, 20, 'bet atveskite pas mane savo jauniausiąjį brolį; taip jūsų žodžiai pasitvirtins, ir jūs nemirsite“. Ir taip jie padarė.'),
  (@b1, 42, 21, 'Ir jie tarė vienas kitam: „Iš tikrųjų mes esame kalti dėl savo brolio, nes matėme jo sielos skausmą, kai jis mus maldavo, bet mes nenorėjome išklausyti; todėl ši bėda užėjo ant mūsų“.'),
  (@b1, 42, 22, 'Ir Rubenas jiems atsakė, tardamas: „Argi jums nesakiau, sakydamas: ‘Nenusidėkite prieš tą vaiką’; bet jūs nenorėjote išklausyti. Todėl štai jo kraujas išieškomas“.'),
  (@b1, 42, 23, 'Ir jie nežinojo, kad Juozapas juos suprato; nes jis jiems kalbėjo per vertėją.'),
  (@b1, 42, 24, 'Ir jis nusigręžė nuo jų ir verkė; ir vėl sugrįžo pas juos bei su jais kalbėjo, ir paėmė iš jų Simeoną, ir surišo jį jų akyse.'),
  (@b1, 42, 25, 'Tada Juozapas įsakė pripildyti jų maišus javų, sugrąžinti jų pinigus kiekvienam į jo maišą ir jiems duoti atsargų į kelią; ir taip jis jiems padarė.'),
  (@b1, 42, 26, 'Ir jie pakrovė savo asilus javais ir iš ten išvyko.'),
  (@b1, 42, 27, 'Ir kai vienas iš jų užeigoje atrišo savo maišą, kad duotų pašaro savo asilui, jis pamatė savo pinigus; nes štai jie buvo jo maišo angoje.'),
  (@b1, 42, 28, 'Ir jis tarė savo broliams: „Mano pinigai sugrąžinti; ir štai jie mano maiše“; ir jiems nutirpo jų širdys, ir bijodami vienas kitam sakė: „Kas tai yra, ką Dievas mums padarė?“'),
  (@b1, 42, 29, 'Ir jie parėjo pas savo tėvą Jokūbą į Kanaano šalį ir papasakojo jam viską, kas jiems buvo atsitikę, tardami:'),
  (@b1, 42, 30, '„Tas vyras, šalies viešpats, šiurkščiai kalbėjo su mumis ir mus palaikė tos šalies žvalgais.'),
  (@b1, 42, 31, 'Ir mes jam sakėme: ‘Mes esame dori; mes nesame žvalgai;'),
  (@b1, 42, 32, 'mes esame dvylika brolių, mūsų tėvo sūnūs; vieno nebėra, o jauniausiasis šią dieną yra pas mūsų tėvą Kanaano šalyje’.'),
  (@b1, 42, 33, 'O tas vyras, tos šalies viešpats, mums tarė: ‘Iš to pažinsiu, kad jūs esate dori: vieną iš jūsų brolių palikite čia pas mane ir, paėmę maisto dėl jūsų namų bado, eikite;'),
  (@b1, 42, 34, 'ir atveskite pas mane savo jauniausiąjį brolį; tada aš žinosiu, kad jūs nesate žvalgai, o kad esate dori žmonės; tai aš jums atiduosiu jūsų brolį, ir jūs galėsite prekiauti šalyje’“.'),
  (@b1, 42, 35, 'Ir įvyko jiems betuštinant savo maišus, štai kiekvieno pinigų ryšulėlis buvo jo paties maiše; ir jie ir jų tėvas, pamatę pinigų ryšulėlius, išsigando.'),
  (@b1, 42, 36, 'Ir jų tėvas Jokūbas jiems tarė: „Jūs atėmėte mano vaikus; Juozapo nebėra, Simeono nebėra, ir Benjaminą norite atimti; visa tai yra atsisukę prieš mane“.'),
  (@b1, 42, 37, 'Ir Rubenas kalbėjo savo tėvui, sakydamas: „Užmušk mano abu sūnus, jei aš jo neparvesiu pas tave; duok jį į mano rankas, ir aš jį tau sugrąžinsiu“.'),
  (@b1, 42, 38, 'O jis tarė: „Mano sūnus nevyks žemyn su jumis; nes jo brolis yra miręs, o jis palikęs vienas; jei jam atsitiks nelaimė kelyje, kuriuo jūs eisite, tada jūs nuvarysite mano žilus plaukus su širdgėla į kapą“.'),
  (@b1, 43, 1, 'Ir badas šalyje buvo sunkus.'),
  (@b1, 43, 2, 'Ir įvyko, kai jie suvalgė javus, kuriuos buvo parsigabenę iš Egipto, jų tėvas jiems tarė: „Grįžkite, nupirkite mums truputį maisto“.'),
  (@b1, 43, 3, 'O Juda kalbėjo jam, sakydamas: „Tas vyras mums rimtai pareiškė, sakydamas: ‘Nepamatysite mano veido, jei jūsų brolio nebus su jumis’.'),
  (@b1, 43, 4, 'Jei pasiųsi su mumis mūsų brolį, mes vyksime žemyn ir nupirksime tau maisto;'),
  (@b1, 43, 5, 'bet jei jo nesiųsi, mes nevyksime žemyn; nes tas vyras mums pasakė: ‘Nepamatysite mano veido, jei jūsų brolio nebus su jumis’“.'),
  (@b1, 43, 6, 'Ir Izraelis tarė: „Kodėl taip blogai pasielgėte su manimi, tam vyrui pasakydami turį dar kitą brolį?“'),
  (@b1, 43, 7, 'Ir jie tarė: „Tas vyras griežtai klausinėjo apie mūsų padėtį ir apie mūsų giminę, sakydamas: ‘Ar jūsų tėvas dar gyvas? Ar turite kitą brolį?’ Ir mes jam pasakėme pagal tų žodžių turinį; argi mes tikrai galėjome žinoti, kad jis sakys: ‘Atveskite žemyn savo brolį’?“'),
  (@b1, 43, 8, 'Ir Juda tarė savo tėvui Izraeliui: „Siųsk berniuką su manimi, ir mes pakilę vyksime; kad mes gyventume, o nemirtume, nei mes, nei tu, nei mūsų mažyliai.'),
  (@b1, 43, 9, 'Aš būsiu užstatas už jį; iš mano rankos jo reikalauk; jei jo neparvesiu pas tave ir nepastatysiu prieš tave, tuomet leisk man nešioti kaltę visam laikui;'),
  (@b1, 43, 10, 'nes jei nebūtume delsę, tikrai dabar būtume grįžę šį antrąjį kartą“.'),
  (@b1, 43, 11, 'Ir jų tėvas Izraelis jiems tarė: „Jei taip dabar turi būti, darykite štai ką: pasiimkite į savo indus iš geriausių krašto vaisių ir nugabenkite žemyn tam vyrui dovaną: truputį balzamo ir truputį medaus, prieskonių ir miros, riešutų ir migdolų;'),
  (@b1, 43, 12, 'ir paimkite į savo rankas dvigubai pinigų; o pinigus, kurie buvo sugrąžinti į jūsų maišų angas, neškite juos atgal savo rankose; galbūt tai buvo apsirikimas;'),
  (@b1, 43, 13, 'pasiimkite taip pat savo brolį ir pakilę grįžkite pas tą vyrą;'),
  (@b1, 43, 14, 'o Visagalis Dievas teduoda jums gailestingumo to vyro akivaizdoje, kad jis išleistų kitą jūsų brolį ir Benjaminą. Jei aš būsiu netekęs savo vaikų, aš būsiu netekęs“.'),
  (@b1, 43, 15, 'Ir tie vyrai paėmė tą dovaną, paėmė į savo rankas dvigubai pinigų ir Benjaminą; ir pakilę nuvyko žemyn į Egiptą ir atsistojo Juozapo akivaizdoje.'),
  (@b1, 43, 16, 'Ir Juozapas, pamatęs su jais Benjaminą, tarė savo namų valdovui: „Atvesk tuos vyrus į namus, papjauk ir paruošk; nes tie vyrai pietaus su manimi vidurdienį“.'),
  (@b1, 43, 17, 'Ir tas žmogus padarė, kaip Juozapas įsakė; ir tas žmogus įvedė tuos vyrus į Juozapo namus.'),
  (@b1, 43, 18, 'Bet tie vyrai bijojo, kadangi buvo atvesti į Juozapo namus; ir jie sakė: „Mes esame atvesti dėl tų pinigų, pirmąjį kartą sugrąžintų į mūsų maišus; kad jis ieškotų progos prieš mus, pultų ant mūsų ir paimtų į vergus mus bei mūsų asilus“.'),
  (@b1, 43, 19, 'Ir jie priartėjo prie Juozapo namų prievaizdo ir kalbėjo su juo prie namų durų,'),
  (@b1, 43, 20, 'ir sakė: „O, pone, mes pirmąjį kartą tikrai leidomės maisto pirkti;'),
  (@b1, 43, 21, 'ir įvyko, kai mes atėjome į užeigą, mes atrišome savo maišus, ir štai kiekvieno vyro pinigai buvo jo maišo angoje – mūsų pinigai pilno svorio; ir juos savo rankose atsinešėme atgal.'),
  (@b1, 43, 22, 'Ir atsinešėme savo rankose kitų pinigų maistui pirkti; mes nežinome, kas įdėjo mūsų pinigus į mūsų maišus“.'),
  (@b1, 43, 23, 'O jis tarė: „Būkite ramūs, nebijokite; jūsų Dievas ir jūsų tėvo Dievas davė jums lobį į jūsų maišus; aš gavau jūsų pinigus“. Ir jis išvedė Simeoną pas juos.'),
  (@b1, 43, 24, 'Ir tas žmogus atvedė tuos vyrus į Juozapo namus ir padavė jiems vandens, ir jie nusiplovė savo kojas; ir jis davė pašaro jų asilams.'),
  (@b1, 43, 25, 'Ir jie paruošė tą dovaną iki Juozapui ateinant vidurdienį; nes girdėjo, kad jie turės ten valgyti duonos.'),
  (@b1, 43, 26, 'Ir Juozapui parėjus namo jie atnešė jam į namus tą dovaną, kuri buvo jų rankose, ir nusilenkė jam ligi žemės.'),
  (@b1, 43, 27, 'Ir jis teiravosi jų apie jų gerovę ir tarė: „Ar sveikas jūsų tėvas, senis, apie kurį kalbėjote? Ar jis dar gyvas?“'),
  (@b1, 43, 28, 'Ir jie atsakė: „Tavo tarnas, mūsų tėvas yra geros sveikatos, jis dar gyvas“. Ir palenkę savo galvas jie išreiškė pagarbą.'),
  (@b1, 43, 29, 'Ir jis pakėlęs savo akis pamatė savo brolį Benjaminą, savo motinos sūnų, ir tarė: „Ar šitas yra jūsų jauniausias brolis, apie kurį man kalbėjote?“ Ir jis tarė: „Dievas tebūna tau maloningas, mano sūnau“.'),
  (@b1, 43, 30, 'Ir Juozapas pasiskubino; nes jo viduriai ilgėjosi jo brolio; ir jis ieškojo, kur verkti; ir jis įėjo į savo kambarį ir ten verkė.'),
  (@b1, 43, 31, 'Ir nusiprausęs veidą, jis išėjo ir tvardydamasis tarė: „Padėkite duonos“.'),
  (@b1, 43, 32, 'Ir jie padėjo jam atskirai, jiems atskirai ir su juo valgantiems egiptiečiams atskirai; nes egiptiečiai negali valgyti duonos su hebrajais; nes egiptiečiams tai yra pasibjaurėjimas.'),
  (@b1, 43, 33, 'Ir jie sėdėjo priešais jį, pirmagimis pagal jo pirmagimystės teisę ir jauniausiasis pagal jo jaunatvę; ir tie vyrai stebėjosi vienas prieš kitą.'),
  (@b1, 43, 34, 'Ir jis paėmė ir pasiuntė jiems valgių iš to, kas buvo ties juo; bet Benjamino valgių buvo penkis kartus daugiau už kiekvieno iš jų. Ir jie gėrė ir linksminosi su juo.'),
  (@b1, 44, 1, 'Ir jis įsakė savo namų prievaizdui, tardamas: „Pripilk tų vyrų maišus maisto tiek, kiek jie gali gabentis, ir įdėk kiekvieno pinigus į jų maišų angas.'),
  (@b1, 44, 2, 'O mano taurę, sidabrinę taurę, įdėk į jauniausiojo maišo angą su jo javų pinigais“. Ir jis padarė pagal Juozapo pasakytą žodį.'),
  (@b1, 44, 3, 'Rytui tik išaušus tie vyrai buvo išleisti, jie su savo asilais.'),
  (@b1, 44, 4, 'Ir jiems išėjus iš miesto, bet dar nesant toli, Juozapas tarė savo prievaizdui: „Kelkis, sek paskui tuos vyrus; ir juos pasivijęs jiems sakyk: ‘Kodėl jūs atmokėjote piktu už gera?'),
  (@b1, 44, 5, 'Ar ji nėra ta, iš kurios geria mano viešpats ir kuria jis tikrai buria ateitį? Jūs pikta padarėte taip darydami’“.'),
  (@b1, 44, 6, 'Ir juos pasivijęs jis jiems kalbėjo šituos pačius žodžius.'),
  (@b1, 44, 7, 'O jie jam tarė: „Kodėl mano viešpats sako šiuos žodžius? Gink Dieve, kad tavo tarnai darytų pagal tą dalyką;'),
  (@b1, 44, 8, 'štai pinigai, kuriuos mes radome savo maišų angose, tau atnešėme atgal iš Kanaano šalies; tad kaip mes vogtume iš tavo viešpaties namų sidabrą ar auksą?'),
  (@b1, 44, 9, 'Pas kurį iš tavo tarnų ji bus rasta, tas temiršta, ir taip pat mes tebūsime mano viešpaties vergais“.'),
  (@b1, 44, 10, 'Ir jis tarė: „Dabar tebūna pagal jūsų žodžius; pas kurį ji bus rasta, tas bus mano tarnas; o jūs būsite nekalti“.'),
  (@b1, 44, 11, 'Tada jie kiekvienas skubiai nukėlė savo maišą žemėn ir kiekvienas atrišo savo maišą.'),
  (@b1, 44, 12, 'Ir jis ieškojo pradėjęs nuo vyriausiojo ir baigė jauniausiuoju; ir taurė buvo rasta Benjamino maiše.'),
  (@b1, 44, 13, 'Tada jie persiplėšė savo drabužius ir kiekvienas pakrovęs savo asilą sugrįžo į miestą.'),
  (@b1, 44, 14, 'Ir Juda ir jo broliai atėjo į Juozapo namus; nes jis dar ten tebebuvo; ir jie puolė prieš jį ant žemės.'),
  (@b1, 44, 15, 'Ir Juozapas jiems tarė: „Kas tai per darbas, kurį padarėte? Argi nežinojote, kad toks vyras, kaip aš, tikrai moku burti ateitį?“'),
  (@b1, 44, 16, 'Ir Juda tarė: „Ką mes besakysime mano valdovui? Ką bekalbėsime? Ar kaip bepasiteisinsime? Dievas atrado tavo tarnų neteisybę; štai mes esame mano viešpaties tarnai, tiek mes, tiek ir tas, pas kurį yra rasta taurė“.'),
  (@b1, 44, 17, 'O jis tarė: „Gink Dieve, kad taip padaryčiau; tik vyras, kurio rankoje yra rasta taurė, tas bus mano tarnas; o kas dėl jūsų, jūs ramiai eikite aukštyn pas savo tėvą“.'),
  (@b1, 44, 18, 'Tada Juda priartėjo prie jo ir tarė: „O, mano viešpatie, leisk, meldžiu tave, tavo tarnui tarti žodį mano viešpačiui į ausis, ir teneužsidega tavo pyktis prieš tavo tarną; nes tu esi kaip faraonas.'),
  (@b1, 44, 19, 'Mano viešpats paklausė savo tarnų, sakydamas: ‘Ar jūs turite tėvą ar brolį?‘'),
  (@b1, 44, 20, 'Ir mes sakėme mano viešpačiui: ‘Mes turime tėvą, senį, ir jo senatvės vaiką, mažiausiąjį; o jo brolis yra miręs, ir jis vienas beišlikęs iš savo motinos, ir jo tėvas myli jį’.'),
  (@b1, 44, 21, 'Ir tu sakei tavo tarnams: ‘Atsiveskite jį žemyn pas mane, idant nukreipčiau į jį savas akis’.'),
  (@b1, 44, 22, 'Ir mes sakėme mano viešpačiui: ‘Berniukas negali palikti savo tėvo; nes jei jis paliktų savo tėvą, jo tėvas numirtų’.'),
  (@b1, 44, 23, 'Ir tu sakei savo tarnams: ‘Jei jūsų jauniausiasis brolis neatvyks žemyn su jumis, jūs nebeišvysite mano veido’.'),
  (@b1, 44, 24, 'Ir įvyko, kai nuvykome aukštyn pas tavo tarną, mano tėvą, mes jam pasakėme mano viešpaties žodžius.'),
  (@b1, 44, 25, 'Ir mūsų tėvas tarė: ‘Grįžkite, nupirkite mums truputį maisto’.'),
  (@b1, 44, 26, 'Ir mes tarėme: ‘Negalime leistis; jei mūsų jauniausias brolis bus su mumis, tuomet leisimės; nes negalime išvysti to vyro veido, jei mūsų jauniausiojo brolio nebus su mumis’.'),
  (@b1, 44, 27, 'Ir tavo tarnas, mano tėvas, mums tarė: ‘Jūs žinote, kad mano žmona pagimdė man du sūnus;'),
  (@b1, 44, 28, 'ir vienas išėjo nuo manęs, ir aš tariau: „Tikrai jis sudraskytas į gabalus“; ir nuo tada aš jo nebemačiau;'),
  (@b1, 44, 29, 'jei ir šitą paimsite nuo manęs ir nelaimė jam atsitiks, tai nuvarysite mano žilus plaukus su širdgėla į kapą’.'),
  (@b1, 44, 30, 'Taigi dabar, kai pareisiu pas tavo tarną, mano tėvą, o su mumis nebus berniuko; kadangi jo gyvybė yra prisirišusi prie berniuko gyvybės;'),
  (@b1, 44, 31, 'tai įvyks, kai tik jis pamatys, kad berniuko nėra su mumis, jis numirs; ir tavo tarnai nuvarys tavo tarno, mūsų tėvo, žilus plaukus su sielvartu į kapą.'),
  (@b1, 44, 32, 'Nes tavo tarnas tapo užstatu už berniuką mano tėvui, tardamas: ‘Jei jo neparvesiu pas tave, tada aš nešiosiu kaltę savo tėvui visam laikui’.'),
  (@b1, 44, 33, 'Todėl dabar, meldžiu tave, leisk savo tarnui pasilikti berniuko vietoje mano viešpaties vergu; o berniukas tegul eina aukštyn su savo broliais.'),
  (@b1, 44, 34, 'Nes kaipgi aš eisiu aukštyn pas savo tėvą, o berniuko nebus su manimi? Aš pamatyčiau nelaimę, kuri ištiktų mano tėvą“.'),
  (@b1, 45, 1, 'Tada Juozapas nebegalėjo susivaldyti akivaizdoje visų prie jo stovinčiųjų; ir jis sušuko: „Liepkite visiems nuo manęs išeiti“. Ir niekas nestovėjo prie jo, kol Juozapas davė save atpažinti savo broliams.'),
  (@b1, 45, 2, 'Ir jis garsiai verkė; ir girdėjo egiptiečiai ir faraono namai.'),
  (@b1, 45, 3, 'Ir Juozapas tarė savo broliams: „Aš esu Juozapas; ar mano tėvas dar gyvas?“ Ir jo broliai negalėjo jam atsakyti; nes jie sunerimo jo akivaizdoje.'),
  (@b1, 45, 4, 'Ir Juozapas tarė savo broliams: „Meldžiu jus, priartėkite prie manęs“. Ir jie priartėjo. Ir jis tarė: „Aš esu Juozapas, jūsų brolis, kurį pardavėte į Egiptą.'),
  (@b1, 45, 5, 'Todėl dabar nesisielokite ir nei nepykite ant savęs, kad mane čion pardavėte; nes gyvybei išlaikyti Dievas mane pasiuntė pirma jūsų.'),
  (@b1, 45, 6, 'Nes šiuos dvejus metus badas yra šalyje; ir yra dar penkeri metai, kuriais nebus nei arimo, nei pjūties.'),
  (@b1, 45, 7, 'Bet Dievas mane pasiuntė pirma jūsų, kad išsaugotų jums palikuonių žemėje ir išgelbėtų jūsų gyvybes didžiu išgelbėjimu.'),
  (@b1, 45, 8, 'Taigi tai ne jūs mane čia atsiuntėte, bet Dievas; ir jis mane padarė faraonui tėvu, visų jo namų viešpačiu ir valdovu visoje Egipto šalyje.'),
  (@b1, 45, 9, 'Skubėkite, vykite aukštyn pas mano tėvą ir jam sakykite: ‘Taip sako tavo sūnus Juozapas: „Dievas mane padarė viso Egipto viešpačiu; leiskis pas mane, nedelsk;'),
  (@b1, 45, 10, 'ir tu gyvensi Gošeno šalyje ir būsi arti manęs, tu, tavo vaikai ir tavo vaikų vaikai, tavo kaimenės, tavo bandos ir visa, ką turi;'),
  (@b1, 45, 11, 'ir ten aš tave maitinsiu; nes dar yra penki bado metai; kad tu, tavo namiškiai ir visa, ką turi, nenuskurstumėte“’.'),
  (@b1, 45, 12, 'Ir štai, jūsų akys ir mano brolio Benjamino akys mato, kad tai yra mano burna, kuri jums kalba.'),
  (@b1, 45, 13, 'Ir papasakokite mano tėvui apie visą mano šlovę Egipte ir apie viską, ką jūs matėte; ir pasiskubinkite, ir atgabenkite čia žemyn mano tėvą“.'),
  (@b1, 45, 14, 'Ir jis puolė savo broliui Benjaminui ant kaklo ir verkė; ir Benjaminas verkė ant jo kaklo.'),
  (@b1, 45, 15, 'Jis dar pabučiavo visus savo brolius ir ant jų verkė; o po to jo broliai kalbėjosi su juo.'),
  (@b1, 45, 16, 'Ir ta žinia pasigirdo faraono namuose, sakant: „Juozapo broliai atvykę“; ir tai labai patiko faraonui ir jo tarnams.'),
  (@b1, 45, 17, 'Ir faraonas tarė Juozapui: „Sakyk savo broliams: ‘Tai darykite: pakraukite savo gyvulius ir eikite, parvykite į Kanaano šalį;'),
  (@b1, 45, 18, 'ir paimkite savo tėvą bei savo namiškius ir atvykite pas mane; ir aš jums duosiu, kas Egipto šalies geriausia, ir jūs valgysite tos šalies riebumų’.'),
  (@b1, 45, 19, 'Na, o tau įsakyta: ‘Taip darykite: imkite sau iš Egipto šalies vežimų savo mažyliams bei savo žmonoms ir atgabenkite savo tėvą, ir atvykite.'),
  (@b1, 45, 20, 'Taip pat nepaisykite savo daiktų; nes tai, kas visos Egipto šalies geriausia, yra jūsų’“.'),
  (@b1, 45, 21, 'Ir Izraelio vaikai taip padarė; ir Juozapas jiems davė vežimų pagal faraono įsakymą, ir jiems į kelią davė atsargų.'),
  (@b1, 45, 22, 'Jiems visiems jis davė kiekvienam po pakaitą drabužių; bet Benjaminui jis davė tris šimtus sidabrinių ir penkias drabužių pakaitas.'),
  (@b1, 45, 23, 'O savo tėvui jis nusiuntė šitaip: dešimt asilų, pakrautų Egipto gėrybėmis, ir dešimt asilių, apkrautų javais ir duona bei maistu savo tėvui į kelią.'),
  (@b1, 45, 24, 'Taigi jis išsiuntė savo brolius, ir jie išvyko; ir jis jiems tarė: „Žiūrėkite, nesivaidykite kelyje“.'),
  (@b1, 45, 25, 'Ir jie traukė iš Egipto aukštyn ir atvyko į Kanaano šalį pas savo tėvą Jokūbą'),
  (@b1, 45, 26, 'ir jam pranešė, sakydami: „Juozapas dar gyvas ir jis yra visos Egipto šalies valdytojas“. Ir Jokūbo širdis sutirpo, nes jis nepatikėjo jais.'),
  (@b1, 45, 27, 'Ir jie pasakė jam visus Juozapo jiems kalbėtus žodžius; ir kai jis pamatė vežimus, kuriuos Juozapas buvo pasiuntęs jam vežti, jų tėvo Jokūbo dvasia atgijo;'),
  (@b1, 45, 28, 'ir Izraelis tarė: „Gana; mano sūnus Juozapas dar gyvas; aš vyksiu ir pamatysiu jį prieš numirdamas“.'),
  (@b1, 46, 1, 'Ir Izraelis leidosi į kelionę su viskuo, ką turėjo, ir atvykęs į Beer-Šebą atnašavo aukas savo tėvo Izaoko Dievui.'),
  (@b1, 46, 2, 'Ir Dievas kalbėjo Izraeliui nakties regėjimuose ir tarė: „Jokūbai, Jokūbai“. Ir jis tarė: „Aš čia“.'),
  (@b1, 46, 3, 'Ir jis tarė: „Aš esu Dievas, tavo tėvo Dievas; nebijok leistis į Egiptą; nes ten iš tavęs aš padarysiu didelę tautą;'),
  (@b1, 46, 4, 'aš leisiuosi su tavimi į Egiptą; ir taip pat aš tikrai tave pargabensiu aukštyn; o Juozapas uždės savo ranką ant tavo akių“.'),
  (@b1, 46, 5, 'Ir Jokūbas pakilo iš Beer-Šebos; ir Izraelio sūnūs vežė savo tėvą Jokūbą, savo mažylius ir savo žmonas vežimuose, kuriuos faraonas buvo atsiuntęs jo vežti.'),
  (@b1, 46, 6, 'Ir jie ėmė savo galvijus ir savo turtą, kurį buvo įsigiję Kanaano šalyje, ir atvyko į Egiptą, Jokūbas ir su juo visa jo sėkla:'),
  (@b1, 46, 7, 'jo sūnūs ir jo sūnų sūnūs su juo, jo dukterys ir jo sūnų dukterys, visą savo sėklą jis atgabeno su savimi į Egiptą.'),
  (@b1, 46, 8, 'O šitie yra vardai atvykusių į Egiptą Izraelio vaikų, Jokūbo ir jo sūnų: Jokūbo pirmagimis Rubenas.'),
  (@b1, 46, 9, 'O Rubeno sūnūs: Hanochas, Palus, Hesronas ir Karmis.'),
  (@b1, 46, 10, 'O Simeono sūnūs: Jemuelis, Jaminas, Ohadas, Jachinas, Coharas ir kanaanietės sūnus Šaulius.'),
  (@b1, 46, 11, 'O Levio sūnūs: Geršonas, Kehatas ir Meraris.'),
  (@b1, 46, 12, 'O Judos sūnūs: Eras, Onanas, Šela, Peresas ir Zerachas; bet Eras ir Onanas mirė Kanaano šalyje. Ir Pereso sūnūs buvo Hesronas ir Hamulas.'),
  (@b1, 46, 13, 'O Isacharo sūnūs: Tola, Pūva, Jobas ir Šimronas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b1, 46, 14, 'O Zebulono sūnūs: Seredas, Elonas ir Jahleelis.'),
  (@b1, 46, 15, 'Šitie yra Lėjos sūnūs, kuriuos ji pagimdė Jokūbui Padan-Arame, su jo dukterimi Dina: visų jo sūnų bei dukterų sielų buvo trisdešimt trys.'),
  (@b1, 46, 16, 'O Gado sūnūs: Sifjonas, Hagis, Šūnis, Esbonas, Eris, Arodis ir Arelis.'),
  (@b1, 46, 17, 'O Ašero sūnūs: Imna, Išva, Išvis, Berija ir jų sesuo Seracha; o Berijos sūnūs: Heberas ir Malkielis.'),
  (@b1, 46, 18, 'Šitie yra sūnūs Zilpos, kurią Labanas davė savo dukteriai Lėjai, ir šituos ji pagimdė Jokūbui – šešiolika sielų.'),
  (@b1, 46, 19, 'Jokūbo žmonos Rachelės sūnūs: Juozapas ir Benjaminas.'),
  (@b1, 46, 20, 'O Juozapui Egipto šalyje gimė Manasas ir Efraimas, kuriuos jam pagimdė Ono kunigo Poti-Feros duktė Asenata.'),
  (@b1, 46, 21, 'O Benjamino sūnūs buvo Bela, Becheras, Ašbelas, Gera, Naamanas, Ehis, Rošas, Mupimas, Hupimas ir Ardas.'),
  (@b1, 46, 22, 'Šitie yra Rachelės sūnūs, kurie gimė Jokūbui – visų sielų buvo keturiolika.'),
  (@b1, 46, 23, 'O Dano sūnūs: Hušimas.'),
  (@b1, 46, 24, 'O Naftalio sūnūs: Jachseelis, Gunis, Jeseras ir Šilemas.'),
  (@b1, 46, 25, 'Šitie yra sūnūs Bilhos, kurią Labanas davė savo dukteriai Rachelei, ir šituos ji pagimdė Jokūbui – visų sielų buvo septynios.'),
  (@b1, 46, 26, 'Visų sielų, atvykusių į Egiptą su Jokūbu, išėjusių iš jo strėnų, neskaitant Jokūbo sūnų žmonų, visų sielų buvo šešiasdešimt šešios;'),
  (@b1, 46, 27, 'ir Juozapo sūnų, kurie jam gimė Egipte, buvo dvi sielos; visų Jokūbo namų sielų, atvykusių į Egiptą, buvo septyniasdešimt.'),
  (@b1, 46, 28, 'Ir jis išsiuntė Judą pirma savęs pas Juozapą, kad nukreiptų jo veidą į Gošeną; ir jie atvyko į Gošeno šalį.'),
  (@b1, 46, 29, 'Ir Juozapas pasikinkė savo vežimą ir nuvyko aukštyn į Gošeną savo tėvo Izraelio pasitikti, ir jam prisistatė; ir jis puolė jam ant kaklo ir ilgai verkė ant jo kaklo.'),
  (@b1, 46, 30, 'Ir Izraelis tarė Juozapui: „Dabar, jau pamatęs tavo veidą, temirštu, kadangi tu dar esi gyvas“.'),
  (@b1, 46, 31, 'Ir Juozapas tarė savo broliams ir savo tėvo namiškiams: „Aš vyksiu aukštyn ir pranešiu faraonui bei jam sakysiu: ‘Mano broliai ir mano tėvo namiškiai, kurie buvo Kanaano šalyje, yra atvykę pas mane;'),
  (@b1, 46, 32, 'ir tie vyrai yra piemenys, nes jie vertėsi galvijų ganymu; ir jie atsigabeno savo kaimenes, savo bandas ir visa, ką turi’.'),
  (@b1, 46, 33, 'Ir įvyks, kai faraonas jus pasišauks ir sakys: ‘Koks jūsų užsiėmimas?’'),
  (@b1, 46, 34, 'Jūs tai sakykite: ‘Tavo tarnai vertėsi galvijais nuo pat mūsų jaunystės iki dabar, tiek mes, tiek ir mūsų tėvai’; kad galėtumėte gyventi Gošeno šalyje; nes kiekvienas piemuo yra pasibjaurėjimas egiptiečiams“.'),
  (@b1, 47, 1, 'Paskui Juozapas atvykęs pranešė faraonui ir tarė: „Mano tėvas ir mano broliai su savo kaimenėmis, savo bandomis ir su viskuo, ką jie turi, yra atvykę iš Kanaano šalies; ir štai, jie yra Gošeno šalyje“.'),
  (@b1, 47, 2, 'Ir jis pasiėmė keletą savo brolių, penkis vyrus, ir pristatė juos faraonui.'),
  (@b1, 47, 3, 'Ir faraonas tarė jo broliams: „Koks jūsų užsiėmimas?“ Ir jie tarė faraonui: „Tavo tarnai – piemenys, tiek mes, tiek ir mūsų tėvai“.'),
  (@b1, 47, 4, 'Jie dar sakė faraonui: „Atvykome laikinai apsigyventi toje šalyje; nes nėra ganyklos tavo tarnų kaimenėms; nes badas sunkus Kanaano šalyje; todėl dabar, meldžiame tave, leisk savo tarnams gyventi Gošeno šalyje“.'),
  (@b1, 47, 5, 'Ir faraonas kalbėjo Juozapui, sakydamas: „Tavo tėvas ir tavo broliai yra atvykę pas tave;'),
  (@b1, 47, 6, 'Egipto šalis yra tavo priešaky; geriausioje šalies dalyje apgyvendink savo tėvą ir savo brolius; jie tegyvena Gošeno šalyje; ir jei žinai tarp jų kokių veiklių vyrų, tai paskirk juos mano galvijų prižiūrėtojais“.'),
  (@b1, 47, 7, 'Ir Juozapas įvedė savo tėvą Jokūbą ir jį pastatė prieš faraoną; ir Jokūbas palaimino faraoną.'),
  (@b1, 47, 8, 'Ir faraonas tarė Jokūbui: „Kiek tau metų?“'),
  (@b1, 47, 9, 'Ir Jokūbas tarė faraonui: „Mano kelionės metų dienų yra šimtas trisdešimt metų; nedaug ir piktos buvo mano gyvenimo metų dienos ir nepasiekė mano tėvų gyvenimo metų dienų jų kelionės dienomis“.'),
  (@b1, 47, 10, 'Ir Jokūbas palaimino faraoną ir išėjo nuo faraono akivaizdos.'),
  (@b1, 47, 11, 'Ir Juozapas apgyvendino savo tėvą ir savo brolius ir davė jiems nuosavybės Egipto šalyje, šalies geriausioje dalyje, Ramzio šalyje, kaip faraonas buvo įsakęs.'),
  (@b1, 47, 12, 'Ir Juozapas maitino duona savo tėvą, savo brolius ir visus savo tėvo namiškius, pagal jų šeimas.'),
  (@b1, 47, 13, 'Ir nebuvo duonos visoje šalyje; nes badas buvo labai sunkus, taip, kad Egipto šalis ir visa Kanaano šalis alpo nuo bado.'),
  (@b1, 47, 14, 'Ir Juozapas surinko visus pinigus, randamus Egipto šalyje ir Kanaano šalyje, už javus, kurių jie pirko; ir Juozapas atgabeno tuos pinigus į faraono namus.'),
  (@b1, 47, 15, 'O kai pinigai pasibaigė Egipto šalyje ir Kanaano šalyje, visi egiptiečiai atėjo pas Juozapą ir tarė: „Duok mums duonos; kodėl turėtume mirti tavo akivaizdoje? Nes pinigai pasibaigė“.'),
  (@b1, 47, 16, 'Ir Juozapas tarė: „Duokite savo galvijus; ir aš duosiu jums už jūsų galvijus, jei pinigai pasibaigė“.'),
  (@b1, 47, 17, 'Ir jie atvedė savo galvijus pas Juozapą; ir Juozapas davė jiems duonos mainais už arklius, už kaimenes, už bandų galvijus ir už asilus; ir jis juos maitino duona už visus jų galvijus už tuos metus.'),
  (@b1, 47, 18, 'Tiems metams pasibaigus, jie atėjo pas jį antraisiais metais ir jam tarė: „Mes neslėpsime to nuo savo viešpaties, kad mūsų pinigai išleisti; taip pat mano viešpats turi mūsų galvijų bandas; nieko kito nebepaliko mano viešpaties akivaizdoje, kaip tik mūsų kūnai ir mūsų žemės;'),
  (@b1, 47, 19, 'kodėl turėtume mirti tavo akyse, tiek mes, tiek mūsų žemė? Pirk mus ir mūsų žemę už duoną, ir mes ir mūsų žemė būsime faraonui tarnais; ir duok mums sėklos, kad mes gyventume, o ne mirtume, kad žemė nebūtų apleista“.'),
  (@b1, 47, 20, 'Ir Juozapas nupirko faraonui visą Egipto žemę; nes egiptiečiai, kadangi badas juos nugalėjo, pardavė kiekvienas savo lauką; taip žemė tapo faraono.'),
  (@b1, 47, 21, 'O dėl tautos, jis perkėlė juos į miestus nuo vieno Egipto ribos galo iki kito jos galo.'),
  (@b1, 47, 22, 'Tik kunigų žemės jis nepirko; nes kunigai turėjo iš faraono jiems nustatytą dalį ir maitinosi faraono jiems duota jų dalimi; todėl jie nepardavė savo žemių.'),
  (@b1, 47, 23, 'Tada Juozapas tarė tautai: „Štai šią dieną aš nupirkau faraonui jus ir jūsų žemę; štai yra jums sėkla, ir jūs sėkite žemę.'),
  (@b1, 47, 24, 'Ir įvyks prieaugyje, kad jūs duosite penktąją dalį faraonui, o keturios dalys bus jūsų pačių, lauko sėklai ir maistui jūsų bei jūsų namiškių, ir jūsų mažylių maistui“.'),
  (@b1, 47, 25, 'Ir jie tarė: „Tu išgelbėjai mūsų gyvybes; leisk mums rasti malonę mano viešpaties akyse, ir mes būsime faraono tarnai“.'),
  (@b1, 47, 26, 'Ir Juozapas tai padarė Egipto žemės įstatymu iki šios dienos, kad faraonas turėtų penktąją dalį; tik išskyrus kunigų žemę, netapusią faraono.'),
  (@b1, 47, 27, 'Ir Izraelis gyveno Egipto šalyje, Gošeno krašte; ir jie turėjo nuosavybę joje ir augo, ir gausiai dauginosi.'),
  (@b1, 47, 28, 'Ir Jokūbas gyveno Egipto šalyje septyniolika metų; taigi visas Jokūbo amžius buvo šimtas keturiasdešimt septyneri metai.'),
  (@b1, 47, 29, 'Ir priartėjo laikas Izraeliui mirti; ir jis pašaukė savo sūnų Juozapą ir jam tarė: „Jei tad radau malonę tavo akyse, tai dėk, meldžiu tave, savo ranką po mano šlaunimi ir pasielk su manimi gerai ir teisingai; meldžiu tave, nepalaidok manęs Egipte;'),
  (@b1, 47, 30, 'bet aš noriu gulėti su savo tėvais; ir išnešk mane iš Egipto, ir mane palaidok jų laidojimo vietoje“. Ir jis tarė: „Aš padarysiu, kaip sakei“.'),
  (@b1, 47, 31, 'Ir jis tarė: „Prisiek man“. Ir jis jam prisiekė. Ir Izraelis nusilenkė ant lovos galvūgalio.'),
  (@b1, 48, 1, 'Ir įvyko po šitų dalykų, kad Juozapui pasakė: „Štai tavo tėvas serga“; ir jis paėmė su savimi abu savo sūnus, Manasą ir Efraimą.'),
  (@b1, 48, 2, 'Ir Jokūbui pranešė ir tarė: „Štai tavo sūnus Juozapas ateina pas tave“; ir Izraelis sukaupė savo jėgas ir atsisėdo lovoje.'),
  (@b1, 48, 3, 'Ir Jokūbas tarė Juozapui: „Visagalis Dievas man pasirodė Lūze, Kanaano šalyje ir mane palaimino,'),
  (@b1, 48, 4, 'ir man tarė: ‘Štai aš padarysiu tave vaisingą, tave padauginsiu ir iš tavęs padarysių tautų daugybę; ir šitą šalį duosiu tavo sėklai po tavęs amžinon nuosavybėn.'),
  (@b1, 48, 5, 'O dabar abu tavo sūnūs, Efraimas ir Manasas, tau gimę Egipto šalyje prieš man atvykstant pas tave į Egiptą, yra mano; jie bus mano kaip Rubenas ir Simeonas.'),
  (@b1, 48, 6, 'O tavo vaikai, kuriuos tu pagimdysi po jų, bus tavo, ir bus praminti vardais jų brolių jų pavelduose.'),
  (@b1, 48, 7, 'O dėl manęs, kai aš atvykau iš Padano, Rachelė mirė šalia manęs Kanaano šalyje, kelyje, kai iki Efrato ateiti dar buvo likęs truputis kelio; ir aš ją palaidojau ten, kelyje Efrato; tas yra Betliejus“.'),
  (@b1, 48, 8, 'Ir Izraelis, pamatęs Juozapo sūnus, tarė: „Kas yra šitie?“'),
  (@b1, 48, 9, 'Ir Juozapas tarė savo tėvui: „Jie yra mano sūnūs, kuriuos Dievas man čia davė“. Ir jis tarė: „Meldžiu tave, atvesk juos prie manęs, ir aš juos palaiminsiu“.'),
  (@b1, 48, 10, 'Na, o Izraelio akys buvo aptemusios dėl amžiaus, kad jis nebegalėjo matyti. Ir jis privedė juos prie jo; ir jis juos pabučiavo bei juos apkabino.'),
  (@b1, 48, 11, 'Ir Izraelis tarė Juozapui: „Aš nesitikėjau išvysti tavo veido; o štai Dievas man parodė ir tavo sėklą“.'),
  (@b1, 48, 12, 'Ir Juozapas išvedė juos nuo savo tarpkojo ir nusilenkė veidu į žemę.'),
  (@b1, 48, 13, 'Ir Juozapas paėmė juos abu: į savo dešinę Efraimą, Izraelio kairės link, o į savo kairiąją Manasą, Izraelio dešinės link, ir juos privedė prie jo.'),
  (@b1, 48, 14, 'Ir Izraelis ištiesęs savo dešinę ranką, uždėjo ją ant galvos Efraimo, kuris buvo jaunesnysis, o savo kairiąją ranką ant Manaso galvos, sąmoningai vesdamas savo rankas; nes Manasas buvo pirmagimis.'),
  (@b1, 48, 15, 'Ir jis palaimino Juozapą ir tarė: „Dievas, kurio akivaizdoje vaikščiojo mano tėvai Abraomas ir Izaokas, Dievas, kuris mane ganė per visą mano gyvenimą iki pat šios dienos,'),
  (@b1, 48, 16, 'Angelas, kuris atpirko mane iš viso pikto, tepalaimina šituos berniukus; ir tegul jie būna minimi mano vardu ir vardu mano tėvų Abraomo ir Izaoko; ir tegul jie išauga į daugybę viduryje žemės“.'),
  (@b1, 48, 17, 'Ir kai Juozapas pamatė, kad jo tėvas uždėjo savo dešinę ranką ant Efraimo galvos, jam tai nepatiko; ir jis pakėlė savo tėvo ranką, kad ją perkeltų nuo Efraimo galvos ant Manaso galvos.'),
  (@b1, 48, 18, 'Ir Juozapas tarė savo tėvui: „Ne taip, mano tėve; nes šitas yra pirmagimis; dėk savo dešinę ranką ant jo galvos“.'),
  (@b1, 48, 19, 'Bet jo tėvas nesutiko, tardamas: „Žinau tai, mano sūnau, žinau; jis irgi taps tauta, jis irgi bus didis; tačiau tikrai jo jaunesnysis brolis bus didesnis už jį, ir jo sėkla taps tautų daugybe“.'),
  (@b1, 48, 20, 'Ir jis tą dieną juos palaimino, tardamas: „Tavyje Izraelis laimins, sakydamas: ‘Dievas tepadaro tave kaip Efraimą ir kaip Manasą’“; ir jis pastatė Efraimą pirmiau Manaso.'),
  (@b1, 48, 21, 'Ir Izraelis tarė Juozapui: „Štai aš mirštu; bet Dievas bus su jumis ir jus parves atgal į jūsų tėvų šalį.'),
  (@b1, 48, 22, 'Be to, aš tau daviau viena dalimi daugiau nei tavo broliams, kurią atėmiau iš amoritų rankos savo kalaviju ir savo lanku“.'),
  (@b1, 49, 1, 'Ir Jokūbas pašaukė savo sūnus ir tarė: „Susirinkite, kad paskelbčiau jums tai, kas jums atsitiks paskutinėmis dienomis.'),
  (@b1, 49, 2, 'Susirinkite ir klausykitės, Jokūbo sūnūs; ir paklausykite Izraelio, savo tėvo.'),
  (@b1, 49, 3, 'Rubenai, tu esi mano pirmagimis, mano galybė ir mano stiprybės pradžia, pralenkiąs orumu ir pralenkiąs galia;'),
  (@b1, 49, 4, 'nepastovus kaip vanduo, tu nepralenksi; nes tu įlipai į savo tėvo lovą; tuomet tu sutepei ją; jis įlipo į mano guolį.'),
  (@b1, 49, 5, 'Simeonas ir Levis yra broliai; žiaurumo įrankiai yra jų buveinėse.'),
  (@b1, 49, 6, 'O mano siela, neik į jų paslaptis; su jų susirinkimu, mano garbe, tu nesusivienyk; nes savo pyktyje jie užmušė vyrą ir savivaliaudami iškasė sieną.'),
  (@b1, 49, 7, 'Prakeiktas tebūna jų pyktis, nes jis buvo smarkus; ir jų rūstybė, nes ji buvo žiauri; aš juos padalinsiu Jokūbe, juos išsklaidysiu Izraelyje.'),
  (@b1, 49, 8, 'Juda, tu esi tas, kurį girs tavo broliai; tavo ranka bus ant tavo priešų sprando; nusilenks prieš tave tavo tėvo vaikai.'),
  (@b1, 49, 9, 'Juda yra liūto jauniklis; nuo grobio, mano sūnau, tu esi iškilęs; jis pasilenkė, jis prigulė kaip liūtas, kaip senas liūtas; kas jį prikels?'),
  (@b1, 49, 10, 'Neatsitrauks skeptras nuo Judos, nei įstatymleidys iš jo tarpkojo, kol ateis Šilojus; ir pas jį bus tautų susirinkimas.'),
  (@b1, 49, 11, 'Pririšęs prie vynmedžio savo kumeliuką ir prie rinktinio vynmedžio savo asilo jauniklį; jis išsiplovė vyne savo drabužius, vynuogių kraujyje savo apdarus;'),
  (@b1, 49, 12, 'jo akys bus raudonos nuo vyno, ir jo dantys balti nuo pieno.'),
  (@b1, 49, 13, 'Zebulonas gyvens jūros uoste; ir jis bus laivų uostas; ir jo riba bus iki Sidono.'),
  (@b1, 49, 14, 'Isacharas yra stiprus asilas, atsigulantis tarp dviejų naštų;'),
  (@b1, 49, 15, 'ir jis matė, kad poilsis buvo geras, ir kad šalis buvo miela; ir palenkė savo petį, kad neštų, ir tapo tarnu duoklei.'),
  (@b1, 49, 16, 'Danas teis savo tautą kaip viena iš Izraelio genčių.'),
  (@b1, 49, 17, 'Danas bus gyvatė prie kelio, angis ant tako, geliantis žirgui į kulnis, kad jo raitelis nukristų atbulas.'),
  (@b1, 49, 18, 'Tavo išgelbėjimo laukiau, o VIEŠPATIE.'),
  (@b1, 49, 19, 'Gadas, pulkas jį nugalės; bet jis galiausiai nugalės.'),
  (@b1, 49, 20, 'Iš Ašero riebi bus jo duona, ir jis duos karališkus skanėstus.'),
  (@b1, 49, 21, 'Naftalis yra paleista elnė; jis teikia gražius žodžius.'),
  (@b1, 49, 22, 'Juozapas yra vaisinga šaka, vaisinga šaka prie versmės; kurios atšakos stiebiasi virš sienos;'),
  (@b1, 49, 23, 'šauliai sukėlė jam didelį sielvartą, šaudė į jį, ir jo nekentė;'),
  (@b1, 49, 24, 'tačiau jo lankas pasiliko stiprus, ir jo rankų pečiai buvo sustiprinti per Jokūbo galingojo Dievo rankas (iš ten yra ganytojas, Izraelio akmuo);'),
  (@b1, 49, 25, 'per tavo tėvo Dievą, kuris tau padės; per Visagalį, kuris tave palaimins dangaus palaiminimais iš aukštybių, palaiminimais gelmių, gulinčių apačioje, palaiminimais krūtų ir įsčių;'),
  (@b1, 49, 26, 'tavo tėvo palaiminimai pranašesni už mano pirmtakų palaiminimus iki amžinųjų kalvų tolimiausių ribų; jie bus ant Juozapo galvos ir ant galvos vainiko to, kuris buvo atskirtas nuo savo brolių.'),
  (@b1, 49, 27, 'Benjaminas draskys kaip vilkas; ryte jis ės, ką sugavo, o naktį padalins grobį“.'),
  (@b1, 49, 28, 'Visi šitie yra dvylika Izraelio genčių; ir tai yra, ką jų tėvas kalbėjo jiems ir juos laimino; kiekvieną pagal jų palaiminimus palaimino jis juos.'),
  (@b1, 49, 29, 'Ir jis juos įpareigojo ir jiems tarė: „Aš esu surenkamas prie savo tautos; palaidokite mane pas mano tėvus oloje, esančioje hetito Efrono lauke,'),
  (@b1, 49, 30, 'oloje, kuri yra lauke Machpelos, esančios prieš Mamrę, Kanaano šalyje, kurią Abraomas nusipirko su hetito Efrono lauku, laidojimo vietos nuosavybėn.'),
  (@b1, 49, 31, 'Ten jie palaidojo Abraomą ir jo žmoną Sarą; ten jie palaidojo Izaoką ir jo žmoną Rebeką; ir ten aš palaidojau Lėją.'),
  (@b1, 49, 32, 'Nupirktas laukas su jame esančia ola buvo iš Heto vaikų“.'),
  (@b1, 49, 33, 'Ir Jokūbas, baigęs duoti įsakymus savo sūnums, įkėlė savo kojas į lovą, atidavė dvasią ir buvo surinktas prie savo tautos.'),
  (@b1, 50, 1, 'Ir Juozapas puolė ant savo tėvo veido, verkė ant jo ir jį bučiavo.'),
  (@b1, 50, 2, 'Ir Juozapas įsakė savo tarnams gydytojams išbalzamuoti jo tėvą; ir gydytojai išbalzamavo Izraelį.'),
  (@b1, 50, 3, 'Ir dėl jo buvo išpildyta keturiasdešimt dienų; nes taip yra išpildomos dienos tų, kurie yra balzamuojami; ir egiptiečiai jį apraudojo septyniasdešimt dienų.'),
  (@b1, 50, 4, 'Ir praėjus jo apraudojimo dienoms, Juozapas kalbėjo faraono namams, sakydamas: „Jei tad radau malonę jūsų akyse, meldžiu jus, kalbėkite faraonui į ausis, sakydami:'),
  (@b1, 50, 5, '‘Mano tėvas mane prisaikdino, sakydamas: „Štai aš mirštu; mano kape, kurį sau išsikasiau Kanaano šalyje, ten mane palaidok“. Todėl dabar, meldžiu tave, leisk man vykti aukštyn ir palaidoti savo tėvą, ir aš sugrįšiu’“.'),
  (@b1, 50, 6, 'Ir faraonas tarė: „Vyk aukštyn ir palaidok savo tėvą, kaip jis tave prisaikdino“.'),
  (@b1, 50, 7, 'Ir Juozapas traukė aukštyn savo tėvo laidoti; ir su juo vyko aukštyn visi faraono tarnai, jo namų vyresnieji ir visi Egipto šalies vyresnieji,'),
  (@b1, 50, 8, 'ir visi Juozapo namai, jo broliai ir jo tėvo namai; tik savo mažylius, savo kaimenes ir savo bandas jie paliko Gošeno šalyje.'),
  (@b1, 50, 9, 'Ir su juo traukė aukštyn tiek vežimai, tiek raiteliai; ir tai buvo labai didelis būrys.'),
  (@b1, 50, 10, 'Ir atvykę į Atado klojimą, esantį anapus Jordano, jie ten raudojo didžia ir labai skaudžia rauda; ir jis atliko savo tėvui gedėjimą septynias dienas.'),
  (@b1, 50, 11, 'O šalies gyventojai, kanaaniečiai, matydami tą gedulą Atado klojime, sakė: „Tai yra sunkus gedulas egiptiečiams“; todėl jį praminė vardu Abel-Misraimas, kuris yra anapus Jordano.'),
  (@b1, 50, 12, 'Ir jo sūnūs jam padarė taip, kaip jis buvo jiems įsakęs;'),
  (@b1, 50, 13, 'nes jo sūnūs nugabeno jį į Kanaano šalį ir palaidojo jį prieš Mamrę Machpelos lauko oloje, kurią Abraomas su lauku nupirko iš hetito Efrono, laidojimo vietos nuosavybėn.'),
  (@b1, 50, 14, 'Ir palaidojęs savo tėvą Juozapas sugrįžo į Egiptą, jis, jo broliai ir visi, kurie vyko su juo aukštyn jo tėvo laidoti.'),
  (@b1, 50, 15, 'Ir Juozapo broliai, matydami, kad jų tėvas yra miręs, tarė: „Galbūt Juozapas mūsų nekęs ir tikrai mums atmokės už visa pikta, ką mes jam padarėme“.'),
  (@b1, 50, 16, 'Ir jie siuntė Juozapui pasiuntinį, sakydami: „Tavo tėvas prieš mirdamas įsakė, sakydamas:'),
  (@b1, 50, 17, '‘Taip sakykite Juozapui: „Atleisk, meldžiu tave, savo brolių nusikaltimą ir jų nuodėmę; nes jie padarė tau pikta“; o dabar, meldžiame tave, atleisk tavo tėvo Dievo tarnų nusikaltimą“. Ir Juozapas verkė, kai jie jam kalbėjo.'),
  (@b1, 50, 18, 'Ir jo broliai taip pat nuėjo ir parpuolė prieš jo veidą; ir jie tarė: „Štai mes esame tavo tarnai“.'),
  (@b1, 50, 19, 'Bet Juozapas jiems tarė: „Nebijokite; nes argi aš esu Dievo vietoje?'),
  (@b1, 50, 20, 'Tačiau dėl jūsų, jūs sumanėte prieš mane pikta; bet Dievas norėjo tai dėl gero, idant įvykdytų, kaip yra šią dieną, kad daug žmonių išlaikytų gyvų.'),
  (@b1, 50, 21, 'Taigi dabar nebijokite; aš maitinsiu jus ir jūsų mažylius“. Ir jis guodė juos ir maloniai jiems kalbėjo.'),
  (@b1, 50, 22, 'Ir Juozapas gyveno Egipte, jis ir jo tėvo namai; ir Juozapas gyveno šimtą dešimt metų.'),
  (@b1, 50, 23, 'Ir Juozapas matė Efraimo trečios kartos vaikus; taip pat Manaso sūnaus Machyro vaikai buvo auginami Juozapui ant kelių.'),
  (@b1, 50, 24, 'Ir Juozapas tarė savo broliams: „Aš mirštu; o Dievas tikrai jus aplankys ir išves iš šitos šalies į šalį, kurią jis prisiekė Abraomui, Izaokui ir Jokūbui“.'),
  (@b1, 50, 25, 'Ir Juozapas prisaikdino Izraelio vaikus, tardamas: „Dievas tikrai jus aplankys, ir jūs nunešite iš čia aukštyn mano kaulus“.'),
  (@b1, 50, 26, 'Taigi Juozapas mirė, būdamas šimto dešimties metų; ir jie jį išbalzamavo, ir jis buvo paguldytas į karstą Egipte.'),
  (@b2, 1, 1, 'Na, o šitie yra vardai Izraelio vaikų, kurie atvyko į Egiptą; kiekvienas su savo namiškiais atėjo su Jokūbu:'),
  (@b2, 1, 2, 'Rubenas, Simeonas, Levis ir Juda,'),
  (@b2, 1, 3, 'Isacharas, Zebulonas ir Benjaminas,'),
  (@b2, 1, 4, 'Danas ir Naftalis, Gadas ir Ašeras.'),
  (@b2, 1, 5, 'Ir visų iš Jokūbo strėnų išėjusių sielų buvo septyniasdešimt sielų; nes Juozapas jau buvo Egipte.'),
  (@b2, 1, 6, 'Ir mirė Juozapas, visi jo broliai ir visa ana karta.'),
  (@b2, 1, 7, 'O Izraelio vaikai buvo vaisingi, gausiai daugėjo, dauginosi ir tapo nepaprastai galingi; ir šalis buvo pripildyta jų.'),
  (@b2, 1, 8, 'Na, o Egiptui iškilo naujas karalius, kuris nežinojo Juozapo.'),
  (@b2, 1, 9, 'Ir jis tarė savo tautai: „Štai Izraelio vaikų tauta yra gausesnė ir galingesnė už mus;'),
  (@b2, 1, 10, 'nagi, pasielkime su jais išmintingai; kad jie nesidaugintų, ir neįvyktų, kad ištikus kokiam karui jie taipogi neprisijungtų prie mūsų priešų ir nekariautų prieš mus, ir taip neišeitų iš šalies“.'),
  (@b2, 1, 11, 'Todėl jie pastatė jiems darbų paskyrėjų, kad juos spaustų savo naštomis. Ir jie pastatė faraonui sandėlių miestus, Pitomą ir Ramzį.'),
  (@b2, 1, 12, 'Bet kuo labiau jie spaudė juos, tuo labiau jie dauginosi ir augo. Ir jie sielojosi dėl Izraelio vaikų.'),
  (@b2, 1, 13, 'Ir egiptiečiai griežtumu vertė Izraelio vaikus tarnauti;'),
  (@b2, 1, 14, 'ir jie apkartino jų gyvenimus sunkia vergyste prie statybinio skiedinio, prie plytų ir prie visokių tarnavimų ant lauko; visoks jų tarnavimas, kuriuo jie vertė juos tarnauti, buvo su griežtumu.'),
  (@b2, 1, 15, 'Ir Egipto karalius kalbėjo hebrajų pribuvėjoms, kurių viena buvo vardu Šifra, o kita vardu Pūva;'),
  (@b2, 1, 16, 'ir jis tarė: „Atlikdamos pribuvėjos pareigas hebrajų moterims, apžiūrėkite jas ant krėslų; jei būtų sūnus, tuomet jį nužudykite; bet jei būtų duktė, tuomet ji tegyvena“.'),
  (@b2, 1, 17, 'Tačiau pribuvėjos bijojo Dievo ir nedarė, kaip joms įsakė Egipto karalius, bet išsaugojo berniukus gyvus.'),
  (@b2, 1, 18, 'Ir Egipto karalius pašaukė pribuvėjas ir joms tarė: „Kodėl jūs tai padarėte ir išsaugojote berniukus gyvus?“'),
  (@b2, 1, 19, 'O pribuvėjos tarė faraonui: „Todėl, kad hebrajų moterys ne tokios, kaip egiptiečių moterys; nes jos yra gyvybingos ir būna pagimdžiusios, prieš ateinant pas jas pribuvėjoms“.'),
  (@b2, 1, 20, 'Todėl Dievas gerai elgėsi su pribuvėjomis; o tauta didėjo ir pasidarė labai galinga.'),
  (@b2, 1, 21, 'Ir įvyko, kadangi pribuvėjos bijojo Dievo, jis padarė joms namus.'),
  (@b2, 1, 22, 'Ir faraonas įpareigojo visą savo tautą, sakydamas: „Kiekvieną gimusį sūnų įmeskite į upę, o kiekvieną dukterį išsaugokite gyvą“.'),
  (@b2, 2, 1, 'Ir toks vyras iš Levio namų ėjo ir ėmė į žmonas Levio dukterį.'),
  (@b2, 2, 2, 'Ir ta moteris pastojo ir pagimdė sūnų; ir kai ji pamatė jį, kad jis buvo gražus vaikas, slėpė jį tris mėnesius.'),
  (@b2, 2, 3, 'Ir nebegalėdama ilgiau jo slėpti, ji paėmė jam dėžę iš meldų, apglaistė ją dumblu ir derva ir įdėjo į ją vaiką; ir ji paguldė ją vilkdalgiuose prie upės kranto.'),
  (@b2, 2, 4, 'O jo sesuo stovėjo iš toli, kad žinotų, kas jam darysis.'),
  (@b2, 2, 5, 'Ir faraono duktė nusileido prie upės nusiprausti; o jos panelės vaikščiojo upės pakrante; ir, išvydusi dėžę tarp vilkdalgių, ji pasiuntė savo tarnaitę, kad ją atneštų.'),
  (@b2, 2, 6, 'Ir atidariusi ją ji pamatė vaiką; ir štai kūdikis verkė. Ir ji pasigailėjo jo ir tarė: „Tai vienas iš hebrajų vaikų“.'),
  (@b2, 2, 7, 'Tada jo sesuo tarė faraono dukteriai: „Ar man eiti ir tau pašaukti žindyvę iš hebrajų moterų, kad ji tau žindytų tą vaiką?“'),
  (@b2, 2, 8, 'Ir faraono duktė jai tarė: „Eik“. Ir ta panelė nuėjo ir pašaukė to vaiko motiną.'),
  (@b2, 2, 9, 'Ir faraono duktė jai tarė: „Pasiimk šitą vaiką ir žindyk jį man, o aš tau duosiu tavo uždarbį“. Ir ta moteris paėmė tą vaiką ir jį žindė.'),
  (@b2, 2, 10, 'Ir tas vaikas augo, ir ji atvedė jį faraono dukteriai, ir jis tapo jos sūnus. Ir ji praminė jį vardu Mozė; ir ji tarė: „Kadangi ištraukiau jį iš vandens“.'),
  (@b2, 2, 11, 'Ir įvyko anomis dienomis, kai Mozė užaugo, jis išėjo pas savo brolius ir žiūrėjo į jų naštas; ir jis pamatė egiptietį, bemušantį vieną iš jo brolių – hebrają.'),
  (@b2, 2, 12, 'Ir šen bei ten apsidairęs ir matydamas, kad nėra nei vieno žmogaus, jis užmušė egiptietį ir paslėpė jį smėlyje.'),
  (@b2, 2, 13, 'Ir kai jis išėjo antrą dieną, štai du hebrajų vyrai besivaidijantys; ir jis tarė darančiam neteisybę: „Kodėl muši savo bendrą?“'),
  (@b2, 2, 14, 'O jis tarė: „Kas tave paskyrė mums kunigaikščiu ir teisėju? Ar ketini mane nužudyti, kaip nužudei egiptietį?“ Ir Mozė išsigando ir tarė: „Tikrai šis dalykas yra žinomas“.'),
  (@b2, 2, 15, 'Na, o faraonas tai išgirdęs siekė nužudyti Mozę. Bet Mozė pabėgo nuo faraono veido ir apsigyveno Midjano šalyje; ir jis sėdėjo prie šulinio.'),
  (@b2, 2, 16, 'Na, o Midjano kunigas turėjo septynias dukteris; ir jos atėjusios sėmė vandenį ir pripildė lovius, kad pagirdytų savo tėvo kaimenę.'),
  (@b2, 2, 17, 'Ir atėjo piemenys ir jas nuvarė; bet Mozė atsistojo, joms padėjo ir pagirdė jų kaimenę.'),
  (@b2, 2, 18, 'Ir joms parėjus pas savo tėvą Reuelį, jis tarė: „Kaip jūs šiandien taip anksti parėjote?“'),
  (@b2, 2, 19, 'Ir jos tarė: „Egiptietis mus išgelbėjo iš piemenų rankų ir taip pat mums užtektinai prisėmė vandens ir pagirdė kaimenę“.'),
  (@b2, 2, 20, 'Ir jis tarė savo dukterims: „O kur jis yra? Kodėl gi jūs palikote tą vyrą? Pašaukite jį, kad jis valgytų duonos“.'),
  (@b2, 2, 21, 'Ir Mozė sutiko gyventi pas tą žmogų; ir jis davė Mozei savo dukterį Siporą.'),
  (@b2, 2, 22, 'Ir ji pagimdė jam sūnų, o jis praminė jį vardu Geršomas; nes jis sakė: „Aš buvau ateivis svetimoje šalyje“.'),
  (@b2, 2, 23, 'Ir įvyko laikui bėgant, kad mirė Egipto karalius; o Izraelio vaikai dejavo dėl vergystės ir šaukė, ir jų šauksmas dėl vergystės pakilo aukštyn pas Dievą.'),
  (@b2, 2, 24, 'Ir Dievas išgirdo jų dejavimą, ir Dievas atsiminė savo sandorą su Abraomu, su Izaoku ir su Jokūbu.'),
  (@b2, 2, 25, 'Ir Dievas pažvelgė į Izraelio vaikus, ir Dievas atsižvelgė į juos.'),
  (@b2, 3, 1, 'Na, o Mozė saugojo savo uošvio, Midjano kunigo Jetro, kaimenę; ir jis nuvedė kaimenę į dykumos galą ir atėjo prie Dievo kalno, prie Horebo.'),
  (@b2, 3, 2, 'Ir VIEŠPATIES angelas jam pasirodė ugnies liepsnoje, iš krūmo vidurio; ir jis pažiūrėjo, ir štai krūmas degė ugnimi, bet tas krūmas nesudegė.'),
  (@b2, 3, 3, 'Ir Mozė tarė: „Dabar aš pasuksiu į šalį ir pasižiūrėsiu į šį didingą reginį, kodėl nesudega tas krūmas“.'),
  (@b2, 3, 4, 'Ir VIEŠPATS pamatęs, kad jis pasuko į šalį pasižiūrėti, Dievas jį pašaukė iš krūmo vidurio ir tarė: „Moze, Moze!“ Ir jis tarė: „Aš čia“.'),
  (@b2, 3, 5, 'Ir jis tarė: „Nesiartink čia; nusiauk nuo savo kojų apavą, nes vieta, ant kurios stovi, yra šventa žemė“.'),
  (@b2, 3, 6, 'Jis dar daugiau sakė: „Aš esu tavo tėvo Dievas, Abraomo Dievas, Izaoko Dievas ir Jokūbo Dievas“. Ir Mozė paslėpė savo veidą; nes jis bijojo pažiūrėti į Dievą.'),
  (@b2, 3, 7, 'Ir VIEŠPATS tarė: „Aš tikrai mačiau suspaudimą savo tautos, esančios Egipte, ir išgirdau jų šauksmą dėl jų darbų paskyrėjų; nes aš žinau jų sielvartą;'),
  (@b2, 3, 8, 'ir aš nužengiau juos išgelbėti iš egiptiečių rankos ir išvesti juos iš tos šalies aukštyn į gerą šalį ir didelę, į šalį, plūstančią pienu ir medumi; į kanaaniečių, hetitų, amoritų, perizų, hivų ir jebusiečių vietą.'),
  (@b2, 3, 9, 'Taigi dabar, štai Izraelio vaikų šauksmas atėjo pas mane; ir taip pat aš mačiau engimą, kuriuo egiptiečiai juos engia.'),
  (@b2, 3, 10, 'Taigi dabar ateik, ir aš tave siųsiu pas faraoną, kad išvestum iš Egipto mano tautą, Izraelio vaikus“.'),
  (@b2, 3, 11, 'Ir Mozė tarė Dievui: „Kas aš, kad eičiau pas faraoną ir kad išvesčiau iš Egipto Izraelio vaikus?“'),
  (@b2, 3, 12, 'Ir jis tarė: „Tikrai aš būsiu su tavimi; ir šis bus tau ženklas, kad aš tave siunčiau: kai išvesi iš Egipto tautą, jūs tarnausite Dievui ant šito kalno“.'),
  (@b2, 3, 13, 'Ir Mozė tarė Dievui: „Štai kai aš ateisiu pas Izraelio vaikus ir jiems sakysiu: ‘Jūsų tėvų Dievas mane siuntė pas jus’; o jie man sakys: ‘Koks yra jo vardas?’ Ką aš jiems sakysiu?“'),
  (@b2, 3, 14, 'Ir Dievas tarė Mozei: „AŠ ESU, KURIS ESU“; ir jis tarė: „Šitaip sakyk Izraelio vaikams: ‘AŠ ESU‘ mane siuntė pas jus“.'),
  (@b2, 3, 15, 'Ir Dievas dar tarė Mozei: „Šitaip sakyk Izraelio vaikams: ‘VIEŠPATS, jūsų tėvų Dievas, Abraomo Dievas, Izaoko Dievas ir Jokūbo Dievas, mane siuntė pas jus; šitas yra mano vardas per amžius ir šitas yra mano atminimas visoms kartoms’.'),
  (@b2, 3, 16, 'Eik, surink Izraelio vyresniuosius ir jiems sakyk: ‘VIEŠPATS, jūsų tėvų Dievas, Abraomo, Izaoko ir Jokūbo Dievas, man pasirodė, tardamas: Aš tikrai jus aplankiau ir pamačiau tai, kas jums padaryta Egipte;'),
  (@b2, 3, 17, 'ir aš tariau: ‘Aš jus išvesiu iš Egipto suspaudimo aukštyn į kanaaniečių, hetitų, amoritų, perizų, hivų ir jebusiečių šalį, į šalį, plūstančią pienu ir medumi’.'),
  (@b2, 3, 18, 'Ir jie paklausys tavo balso; ir tu ateisi, tu ir Izraelio vyresnieji, pas Egipto karalių ir jam sakysite: ‘VIEŠPATS, hebrajų Dievas, susitiko su mumis; o dabar, meldžiame tave, leisk mums eiti trijų dienų kelionę į dykumą, kad mes aukotume VIEŠPAČIUI, savo Dievui’.'),
  (@b2, 3, 19, 'O aš esu įsitikinęs, kad Egipto karalius jūsų neišleis ir per galingą ranką.'),
  (@b2, 3, 20, 'Ir aš ištiesiu savo ranką ir ištiksiu Egiptą visais savo stebuklais, kuriuos darysiu jo tarpe; o po to jis išleis jus.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b2, 3, 21, 'Ir šitai tautai aš duosiu palankumą egiptiečių akyse; ir įvyks, kai eisite, tai jūs nevyksite tuščiomis;'),
  (@b2, 3, 22, 'bet kiekviena moteris pasiskolins iš savo kaimynės ir iš laikinai gyvenančios jos namuose sidabrinių brangenybių, auksinių brangenybių ir drabužių; ir jūs juos uždėsite ant savo sūnų ir savo dukterų; ir jūs apiplėšite egiptiečius“.'),
  (@b2, 4, 1, 'Ir Mozė atsakydamas tarė: „Bet štai jie netikės manimi nei klausys mano balso; nes jie sakys: ‘Tau nepasirodė VIEŠPATS’“.'),
  (@b2, 4, 2, 'Ir VIEŠPATS jam tarė: „Kas tai tavo rankoje?“ Ir jis tarė: „Lazda“.'),
  (@b2, 4, 3, 'Ir jis tarė: „Mesk ją ant žemės“. Ir jis numetė ją ant žemės, o ji pavirto gyvate; ir Mozė bėgo nuo jos.'),
  (@b2, 4, 4, 'Ir VIEŠPATS tarė Mozei: „Ištiesk savo ranką ir paimk ją už uodegos“. Ir jis ištiesė savo ranką ir nutvėrė ją, ir ji virto lazda jo rankoje;'),
  (@b2, 4, 5, '„Kad jie tikėtų, kad tau pasirodė VIEŠPATS, jų tėvų Dievas, Abraomo Dievas, Izaoko Dievas ir Jokūbo Dievas“.'),
  (@b2, 4, 6, 'Ir VIEŠPATS dar jam tarė: „Įkišk dabar savo ranką sau į užantį“. Ir jis įkišo savo ranką sau į užantį; ir kai jis ištraukė ją, štai jo ranka buvo raupsuota kaip sniegas.'),
  (@b2, 4, 7, 'Ir jis tarė: „Vėl įkišk savo ranką sau į užantį“. Ir jis vėl įkišo savo ranką sau į užantį; ir ją ištraukė iš savo užančio, ir štai ji vėl buvo tapusi kaip jo likęs kūnas.'),
  (@b2, 4, 8, '„Ir įvyks, jeigu jie netikės tavimi nei nepaklausys pirmojo ženklo balso, tai jie patikės paskesniojo ženklo balsu.'),
  (@b2, 4, 9, 'Ir įvyks, jeigu jie netikės ir šitais dviem ženklais nei nepaklausys tavo balso, tai paimk upės vandens ir išliek jį ant sausos žemės; ir vanduo, kurį paimsi iš upės, pavirs ant sausos žemės krauju“.'),
  (@b2, 4, 10, 'Ir Mozė tarė VIEŠPAČIUI: ‘O, mano Viešpatie, aš nesu iškalbingas nei iki tol, nei nuo tada, kai tu kalbėjai savo tarnui; bet esu lėtos kalbos ir lėto liežuvio“.'),
  (@b2, 4, 11, 'Ir VIEŠPATS jam tarė: „Kas padarė žmogaus burną, arba kas padaro nebylį ar kurčią, ar regintį, ar aklą? Argi ne aš, VIEŠPATS?'),
  (@b2, 4, 12, 'Taigi dabar eik, o aš būsiu su tavo burna ir tave pamokysiu, ką tau sakyti“.'),
  (@b2, 4, 13, 'Bet jis tarė: „O, mano Viešpatie, meldžiu tave, siųsk per ranką to, kurį siųsi“.'),
  (@b2, 4, 14, 'Ir užsidegė VIEŠPATIES pyktis prieš Mozę, ir jis tarė: „Ar ne levitas Aaronas tavo brolis? Aš žinau, kad jis moka gerai kalbėti. Ir, be to, štai jis išeina tavęs pasitikti; ir tave išvydęs jis džiaugsis savo širdyje.'),
  (@b2, 4, 15, 'Ir tu kalbėk jam ir dėk žodžius į jo burną; o aš būsiu su tavo burna ir su jo burna ir jus pamokysiu, ką jums daryti.'),
  (@b2, 4, 16, 'Ir jis bus tavo kalbėtojas tautai; ir jis, jis tau bus vietoj burnos, o tu jam būsi vietoj Dievo.'),
  (@b2, 4, 17, 'Ir pasiimk į savo ranką šitą lazdą, kuria darysi ženklus“.'),
  (@b2, 4, 18, 'Ir Mozė ėjo ir sugrįžo pas savo uošvį Jetrą, ir jam tarė: „Meldžiu tave, leisk man eiti ir sugrįžti pas savo brolius, esančius Egipte, ir pažiūrėti, ar jie dar gyvi. Ir Jetras tarė Mozei: „Eik ramybėje“.'),
  (@b2, 4, 19, 'Ir VIEŠPATS tarė Mozei Midjane: „Eik, sugrįžk į Egiptą; nes mirę visi tie vyrai, kurie ieškojo tavo gyvybės“.'),
  (@b2, 4, 20, 'Ir Mozė pasiėmė savo žmoną ir savo sūnus, užsodino juos ant asilo ir sugrįžo į Egipto šalį; ir Mozė pasiėmė į ranką Dievo lazdą.'),
  (@b2, 4, 21, 'Ir VIEŠPATS tarė Mozei: „Kai eisi, kad sugrįžtum į Egiptą, žiūrėk, kad padarytum faraono akivaizdoje visus tuos stebuklus, kuriuos aš įdėjau į tavo ranką; bet aš užkietinsiu jo širdį, kad jis neišleistų tautos.'),
  (@b2, 4, 22, 'Ir sakyk faraonui: ‘Taip sako VIEŠPATS: Izraelis yra mano sūnus, mano pirmagimis;'),
  (@b2, 4, 23, 'ir aš tau sakau: „Išleisk mano sūnų, kad jis man tarnautų; o jei atsisakysi jį paleisti, štai aš užmušiu tavo sūnų, tavo pirmagimį”’“.'),
  (@b2, 4, 24, 'Ir įvyko pakeliui į užeigą, kad VIEŠPATS jį sutiko ir siekė jį nužudyti.'),
  (@b2, 4, 25, 'Tada Sipora, paėmusi aštrų akmenį, nupjovė savo sūnaus apyvarpę ir numetė ją prie jo kojų, ir tarė: „Tu tikrai esi man kruvinas vyras“.'),
  (@b2, 4, 26, 'Tad jis paleido jį; tada ji pasakė: „Kruvinas vyras tu esi dėl apipjaustymo“.'),
  (@b2, 4, 27, 'Ir VIEŠPATS tarė Aaronui: „Eik į dykumą Mozės pasitikti“. Ir jis ėjo, sutiko jį Dievo kalne ir pabučiavo.'),
  (@b2, 4, 28, 'Ir Mozė pasakė Aaronui visus žodžius VIEŠPATIES, kuris jį siuntė, ir visus ženklus, kuriuos jis jam įsakė.'),
  (@b2, 4, 29, 'Ir Mozė su Aaronu nuėję surinko visus Izraelio vaikų vyresniuosius;'),
  (@b2, 4, 30, 'ir Aaronas kalbėjo visus žodžius, kuriuos VIEŠPATS buvo kalbėjęs Mozei, ir darė ženklus tautos akyse.'),
  (@b2, 4, 31, 'Ir tauta tikėjo; ir kai jie išgirdo, kad VIEŠPATS aplankė Izraelio vaikus ir kad jis pažvelgė į jų suspaudimą, jie nulenkė savo galvas ir pagarbino.'),
  (@b2, 5, 1, 'O po to Mozė ir Aaronas įėję tarė faraonui: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Išleisk mano tautą, kad jie švęstų man šventę dykumoje’“.'),
  (@b2, 5, 2, 'Ir faraonas tarė: „Kas yra VIEŠPATS, kad turėčiau klausyti jo balso ir išleisti Izraelį? Aš nepažįstu VIEŠPATIES nei neišleisiu Izraelio“.'),
  (@b2, 5, 3, 'Ir jie tarė: „Hebrajų Dievas susitiko su mumis; leisk mums, meldžiame tave, eiti trijų dienų kelionę į dykumą ir aukoti VIEŠPAČIUI, mūsų Dievui; kad jis ant mūsų nepultų maru ar kalaviju“.'),
  (@b2, 5, 4, 'Bet Egipto karalius jiems tarė: „Kodėl jūs, Moze ir Aaronai, atitraukiate tautą nuo jų darbų? Eikite prie savo naštų“.'),
  (@b2, 5, 5, 'Ir faraonas tarė: „Štai šalies tauta jau gausi, o jūs skatinate ją ilsėtis nuo jos naštų“.'),
  (@b2, 5, 6, 'Ir tą pačią dieną faraonas įsakė tautos darbų paskyrėjams ir jos pareigūnams, sakydamas:'),
  (@b2, 5, 7, '„Nebeduokite, kaip anksčiau, tautai šiaudų plytoms gaminti; jie patys tegul eina ir prisirenka šiaudų.'),
  (@b2, 5, 8, 'Ir uždėkite jiems tą skaičių plytų, kiek jie lig šiol padarydavo; nieko nemažinkite; nes jie dykinėja; todėl jie šaukia, sakydami: ‘Eikime, aukokime savo Dievui’.'),
  (@b2, 5, 9, 'Tebūna tiems žmonėms uždėta daugiau darbo, kad triūstų jame; ir tenepaiso jie tuščių žodžių“.'),
  (@b2, 5, 10, 'Ir tautos darbų paskyrėjai ir jų pareigūnai išėję kalbėjo tautai, sakydami: „Taip sako faraonas: ‘Aš neduosiu jums šiaudų.'),
  (@b2, 5, 11, 'Eikite, atsineškite šiaudų iš ten, kur rasite; tačiau jūsų darbas nei kiek nebus sumažintas’“.'),
  (@b2, 5, 12, 'Taigi tauta išsisklaidė po visą Egipto šalį rinkti ražienų vietoj šiaudų.'),
  (@b2, 5, 13, 'O darbų paskyrėjai skubino juos, sakydami: „Atlikite savo darbus, savo dienos užduotis, kaip tada, kai buvo šiaudų“.'),
  (@b2, 5, 14, 'Ir Izraelio vaikų pareigūnai, kuriuos jiems buvo paskyrę faraono darbų paskyrėjai, buvo mušami ir iš jų buvo reikalaujama: „Kodėl neatlikote savo užduoties plytų gaminime nei vakar, nei šiandien, kaip anksčiau?“'),
  (@b2, 5, 15, 'Tada Izraelio vaikų pareigūnai atėję šaukė faraonui, tardami: „Kodėl taip elgiesi su savo tarnais?'),
  (@b2, 5, 16, 'Neduoda tavo tarnams šiaudų, o jie mums sako: ‘Gaminkite plytas’; ir štai tavo tarnai mušami; bet kaltė yra tavo paties tautoje“.'),
  (@b2, 5, 17, 'Bet jis tarė: „Jūs dyki, jūs dyki; todėl sakote: ‘Eikime, aukokime VIEŠPAČIUI’.'),
  (@b2, 5, 18, 'Taigi dabar eikite, dirbkite; nes šiaudų jums neduos, tačiau turėsite pristatyti tą plytų kiekį“.'),
  (@b2, 5, 19, 'Ir Izraelio vaikų pareigūnai pamatė esą bėdoje po to, kai buvo pasakyta: „Nemažinkite kasdienio jums užduoto jūsų plytų kiekio“.'),
  (@b2, 5, 20, 'Ir išėję iš faraono jie susitiko Mozę ir Aaroną, bestovinčius kelyje;'),
  (@b2, 5, 21, 'ir jie tarė jiems: „VIEŠPATS tepažvelgia į jus ir tegul teisia; nes jūs padarėte, kad mūsų kvapu bjaurėtųsi faraono ir jo tarnų akyse, įduodami kalaviją į jų ranką, kad mus užmuštų“.'),
  (@b2, 5, 22, 'Ir Mozė grįžo pas VIEŠPATĮ ir tarė: „Viešpatie, kodėl tu taip piktai pasielgei su šita tauta? Kodėl gi tu mane siuntei?'),
  (@b2, 5, 23, 'Nes nuo tada, kai atėjau pas faraoną kalbėti tavo vardu, jis darė pikta šitai tautai; ir tu visai neišvadavai savo tautos“.'),
  (@b2, 6, 1, 'Tada VIEŠPATS tarė Mozei: „Dabar tu pamatysi, ką aš padarysiu faraonui; nes stipria ranka jis juos išleis, ir stipria ranka jis juos išvarys iš savo šalies“.'),
  (@b2, 6, 2, 'Ir Dievas kalbėjo Mozei ir jam tarė: „Aš esu VIEŠPATS;'),
  (@b2, 6, 3, 'ir aš pasirodžiau Abraomui, Izaokui ir Jokūbui Visagalio Dievo vardu, bet savo vardu ‘JEHOVA’ aš jiems nebuvau žinomas.'),
  (@b2, 6, 4, 'Ir taip pat aš įtvirtinau su jais savo sandorą, kad duočiau jiems Kanaano šalį, jų kelionės šalį, kurioje jie buvo ateiviai.'),
  (@b2, 6, 5, 'Taip pat aš girdėjau dejavimą Izraelio vaikų, kuriuos egiptiečiai laiko vergovėje; ir aš atsiminiau savo sandorą.'),
  (@b2, 6, 6, 'Todėl sakyk Izraelio vaikams: ‘Aš esu VIEŠPATS ir išvesiu jus iš po egiptiečių naštų, ir išvaduosiu jus iš jų vergovės, ir atpirksiu jus ištiesta ranka ir dideliais teismais;'),
  (@b2, 6, 7, 'ir imsiu jus sau už tautą ir būsiu jums Dievas; o jūs žinosite, kad aš esu VIEŠPATS, jūsų Dievas, kuris jus išvedė iš po egiptiečių naštų.'),
  (@b2, 6, 8, 'Ir aš jus nuvesiu į šalį, apie kurią prisiekiau Abraomui, Izaokui ir Jokūbui duoti; ir ją duosiu jums paveldui; aš esu VIEŠPATS’“.'),
  (@b2, 6, 9, 'Ir Mozė taip kalbėjo Izraelio vakams; bet jie neklausė Mozės dėl dvasios skausmo ir dėl žiaurios vergystės.'),
  (@b2, 6, 10, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 6, 11, '„Įeik, kalbėk Egipto karaliui faraonui, kad jis išleistų Izraelio vaikus iš savo šalies“.'),
  (@b2, 6, 12, 'Bet Mozė kalbėjo VIEŠPATIES akivaizdoje, sakydamas: „Štai Izraelio vaikai manęs neklausė; tad kaip klausys faraonas manęs, esančio neapipjaustytomis lūpomis?“'),
  (@b2, 6, 13, 'Ir VIEŠPATS kalbėjo Mozei bei Aaronui ir davė jiems įpareigojimą Izraelio vaikams ir Egipto karaliui faraonui, kad išvestų Izraelio vaikus iš Egipto šalies.'),
  (@b2, 6, 14, 'Šitos yra jų tėvų namų galvos: Izraelio pirmagimio Rubeno sūnūs: Hanochas, Palus, Hesronas ir Karmis; šitos yra Rubeno šeimos.'),
  (@b2, 6, 15, 'O Simeono sūnūs: Jemuelis, Jaminas, Ohadas, Jakinas, Soharas ir kanaanietės moters sūnus Šaulius; šios yra Simeono šeimos.'),
  (@b2, 6, 16, 'O šitie yra Levio sūnų vardai pagal jų genealogiją: Geršonas, Kehatas ir Meraris; ir Levio gyvenimo metų buvo šimtas trisdešimt septyneri metai.'),
  (@b2, 6, 17, 'Geršono sūnūs: Libnis ir Šimis pagal jų šeimas.'),
  (@b2, 6, 18, 'O Kehato sūnūs: Amramas, Iccharas, Hebronas ir Uzielis; o Kehato gyvenimo metų buvo šimtas trisdešimt treji metai.'),
  (@b2, 6, 19, 'O Merario sūnūs: Machlis ir Mušis; šitos yra Levio šeimos pagal jų genealogiją.'),
  (@b2, 6, 20, 'O Amramas ėmė sau į žmonas savo tėvo seserį Jochebedą; ir ji jam pagimdė Aaroną ir Mozę; o Amramo gyvenimo metų buvo šimtas trisdešimt septyneri metai.'),
  (@b2, 6, 21, 'O Iccharo sūnūs: Korachas, Nefegas ir Zichris.'),
  (@b2, 6, 22, 'O Uzielio sūnūs: Mišaelis, Elcafanas ir Sitris.'),
  (@b2, 6, 23, 'O Aaronas ėmė sau į žmonas Elišebą, Aminadabo dukterį, Naasono seserį; ir ji jam pagimdė Nadabą, Abihuvą, Eleazarą ir Itamarą.'),
  (@b2, 6, 24, 'O Koracho sūnūs: Asiras, Elkana ir Abiasafas; šitos yra korachų šeimos.'),
  (@b2, 6, 25, 'Ir Aarono sūnus Eleazaras ėmė sau į žmonas vieną iš Putielio dukterų; ir ji jam pagimdė Finehasą; šitos yra levitų tėvų galvos pagal jų šeimas.'),
  (@b2, 6, 26, 'Šitie yra tas Aaronas ir Mozė, kuriems VIEŠPATS sakė: „Išveskite Izraelio vaikus iš Egipto šalies pagal jų kariuomenes“.'),
  (@b2, 6, 27, 'Šitie yra tie, kurie kalbėjo Egipto karaliui faraonui, kad išvestų Izraelio vaikus iš Egipto; šitie yra tas Mozė ir Aaronas.'),
  (@b2, 6, 28, 'Ir įvyko tą dieną, kai VIEŠPATS kalbėjo Mozei Egipto šalyje,'),
  (@b2, 6, 29, 'kad VIEŠPATS kalbėjo Mozei, sakydamas: „Aš esu VIEŠPATS; kalbėk Egipto karaliui faraonui viską, ką aš tau kalbu“.'),
  (@b2, 6, 30, 'Bet Mozė tarė VIEŠPATIES akivaizdoje: „Štai aš esu neapipjaustytomis lūpomis, ir kaipgi manęs klausys faraonas?“'),
  (@b2, 7, 1, 'Ir VIEŠPATS tarė Mozei: „Štai aš tave padariau dievu faraonui; o tavo brolis Aaronas bus tavo pranašas.'),
  (@b2, 7, 2, 'Kalbėk viską, ką aš tau įsakau; o tavo brolis Aaronas kalbės faraonui, kad jis išleistų Izraelio vaikus iš savo šalies.'),
  (@b2, 7, 3, 'O aš užkietinsiu faraono širdį ir padauginsiu savo ženklus ir stebuklus Egipto šalyje.'),
  (@b2, 7, 4, 'Bet faraonas jūsų neklausys, kad aš uždėčiau savo ranką ant Egipto ir dideliais teismais išvesčiau iš Egipto šalies savo kariuomenes ir savo tautą, Izraelio vaikus.'),
  (@b2, 7, 5, 'Ir egiptiečiai žinos, kad aš esu VIEŠPATS, kai ištiesiu savo ranką ant Egipto ir išvesiu iš jų tarpo Izraelio vaikus“.'),
  (@b2, 7, 6, 'Ir Mozė ir Aaronas padarė, kaip VIEŠPATS jiems įsakė, taip jie padarė.'),
  (@b2, 7, 7, 'O Mozė buvo aštuoniasdešimties metų, o Aaronas aštuoniasdešimt trijų metų, kai jie kalbėjo faraonui.'),
  (@b2, 7, 8, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b2, 7, 9, '„Kai faraonas kalbės jums, sakydamas: ‘Padarykite sau stebuklą’; tada sakyk Aaronui: ‘Imk savo lazdą ir numesk ją priešais faraoną’, ir ji pavirs gyvate“.'),
  (@b2, 7, 10, 'Ir Mozė ir Aaronas įėjo pas faraoną ir jie padarė taip, kaip VIEŠPATS buvo įsakęs; ir Aaronui numetus savo lazdą priešais faraoną ir jo tarnus, ji pavirto gyvate.'),
  (@b2, 7, 11, 'Tada faraonas irgi pasišaukė išminčių ir burtininkų; na, o Egipto burtininkai, jie irgi savo kerais taip pat padarė.'),
  (@b2, 7, 12, 'Nes jie numetė kiekvienas savo lazdą, ir jos pavirto gyvatėmis; bet Aarono lazda prarijo jų lazdas.'),
  (@b2, 7, 13, 'Ir jis užkietino faraono širdį, kad jis jų neklausė; kaip VIEŠPATS buvo kalbėjęs.'),
  (@b2, 7, 14, 'Ir VIEŠPATS tarė Mozei: „Faraono širdis užkietėjusi, jis atsisako išleisti tautą.'),
  (@b2, 7, 15, 'Eik ryte pas faraoną; štai jis išeina prie vandens; o tu atsistok prieš jį, ateinantį prie upės kranto; ir tą lazdą, kuri buvo pavirtusi gyvate, pasiimk į ranką.'),
  (@b2, 7, 16, 'Ir jam sakyk: ‘VIEŠPATS, hebrajų Dievas, mane siuntė pas tave, sakydamas: „Išleisk mano tautą, kad jie man tarnautų dykumoje“; ir štai lig šiol tu nenorėjai klausyti.'),
  (@b2, 7, 17, 'Taip sako VIEŠPATS: „Iš to tu pažinsi, kad aš esu VIEŠPATS: štai aš suduosiu mano rankoje esančia lazda į vandenis, kurie yra upėje, ir jie pavirs krauju.'),
  (@b2, 7, 18, 'Ir upėje esančios žuvys išdvės, ir upė smirdės; ir egiptiečiai bjaurėsis gerti upės vandenį’“.'),
  (@b2, 7, 19, 'Ir VIEŠPATS kalbėjo Mozei: „Sakyk Aaronui: ‘Imk savo lazdą ir ištiesk savo ranką virš Egipto vandenų, virš jų upelių, virš jų upių ir virš jų tvenkinių, ir virš visų jų vandens telkinių, kad jie pavirstų krauju; ir kad būtų kraujas visoje Egipto šalyje, tiek mediniuose, tiek akmeniniuose induose’“.'),
  (@b2, 7, 20, 'Ir Mozė ir Aaronas padarė taip, kaip VIEŠPATS įsakė; ir jis pakėlė lazdą ir sudavė į vandenis, esančius upėje, faraono ir jo tarnų akivaizdoje; ir visi upėje esantys vandenys pavirto krauju.'),
  (@b2, 7, 21, 'Ir upėje esančios žuvys išdvėsė; ir upė smirdėjo, ir egiptiečiai nebegalėjo gerti vandens iš upės; ir kraujas buvo visoje Egipto šalyje.'),
  (@b2, 7, 22, 'Ir Egipto burtininkai taip padarė savo kerais; ir faraono širdis buvo užkietėjusi, ir jis jų neklausė; kaip VIEŠPATS buvo kalbėjęs.'),
  (@b2, 7, 23, 'Ir faraonas nusigręžė ir nuėjo į savo namus, ir jis nepakreipė į tai savo širdies.'),
  (@b2, 7, 24, 'O visi egiptiečiai aplink upę kasė gėrimui vandens; nes jie negalėjo gerti iš upės vandens.'),
  (@b2, 7, 25, 'Ir išsipildė septynios dienos po to, kai VIEŠPATS buvo ištikęs upę.'),
  (@b2, 8, 1, 'Ir VIEŠPATS kalbėjo Mozei: „Eik pas faraoną ir jam sakyk: ‘Taip sako VIEŠPATS: Išleisk mano tautą, kad jie man tarnautų.'),
  (@b2, 8, 2, 'O jei atsisakysi juos išleisti, štai aš ištiksiu visas tavo ribas varlėmis;'),
  (@b2, 8, 3, 'ir upė gausiai duos varlių, kurios eis į viršų ir ateis į tavo namus, į tavo miegamąjį, ant tavo lovos, į tavo tarnų namus ir ant tavo tautos, į tavo krosnis ir į tavo duonkubilius;'),
  (@b2, 8, 4, 'ir varlės lips aukštyn tiek ant tavęs, tiek ant tavo tautos, tiek ant tavo visų tarnų’“.'),
  (@b2, 8, 5, 'Ir VIEŠPATS kalbėjo Mozei: „Sakyk Aaronui: ‘Ištiesk savo ranką su savo lazda virš upelių, virš upių, virš tvenkinių ir padaryk, kad varlės liptų ant Egipto žemės’“.'),
  (@b2, 8, 6, 'Ir Aaronas ištiesė savo ranką virš Egipto vandenų; ir varlės lipo aukštyn ir apdengė Egipto šalį.'),
  (@b2, 8, 7, 'Ir burtininkai taip padarė savo kerais ir atvedė aukštyn varles ant Egipto šalies.'),
  (@b2, 8, 8, 'Tada faraonas, pašaukęs Mozę ir Aaroną, tarė: „Maldaukite VIEŠPATĮ, kad jis pašalintų varles nuo manęs ir nuo mano tautos; ir aš išleisiu tautą, kad jie aukotų VIEŠPAČIUI“.'),
  (@b2, 8, 9, 'Ir Mozė tarė faraonui: „Turėk šlovę per mane; kada turiu maldauti už tave, už tavo tarnus ir už tavo tautą, kad varles išnaikintų nuo tavęs ir iš tavo namų, kad jos tik upėje pasiliktų?“'),
  (@b2, 8, 10, 'Ir jis tarė: „Rytoj“. Ir jis tarė: „Tebūna pagal tavo žodį; kad žinotum, jog nėra nei vieno lygaus VIEŠPAČIUI, mūsų Dievui.'),
  (@b2, 8, 11, 'Ir varlės pasišalins nuo tavęs, iš tavo namų, nuo tavo tarnų ir nuo tavo tautos; jos pasiliks tik upėje“.'),
  (@b2, 8, 12, 'Ir Mozė ir Aaronas išėjo nuo faraono; ir Mozė šaukėsi VIEŠPATIES dėl varlių, kurias jis buvo atvedęs prieš faraoną.'),
  (@b2, 8, 13, 'Ir VIEŠPATS padarė pagal Mozės žodį; ir varlės išdvėsė iš namų, iš kaimų ir iš laukų.'),
  (@b2, 8, 14, 'Ir jie surinko jas į krūvas; ir šalis smirdėjo.'),
  (@b2, 8, 15, 'Bet faraonas, matydamas, kad buvo atokvėpis, užkietino savo širdį ir jų neklausė; kaip VIEŠPATS buvo sakęs.'),
  (@b2, 8, 16, 'Ir VIEŠPATS tarė Mozei: „Sakyk Aaronui: ‘Ištiesk savo lazdą ir suduok į žemės dulkes, kad jos pavirstų utėlėmis visoje Egipto šalyje’“.'),
  (@b2, 8, 17, 'Ir jie taip padarė; nes Aaronas ištiesė savo ranką su savo lazda ir sudavė į žemės dulkes, ir jos pavirto utėlėmis ant žmonių ir ant gyvulių; visos žemės dulkės pavirto utėlėmis visoje Egipto šalyje.'),
  (@b2, 8, 18, 'Ir burtininkai taip darė savo kerais, kad išgautų utėlių, bet jie negalėjo; taigi utėlės buvo ant žmonių ir ant gyvulių.'),
  (@b2, 8, 19, 'Tada burtininkai tarė faraonui: „Tai Dievo pirštas“; o faraono širdis užkietėjo, ir jis jų neklausė; kaip VIEŠPATS buvo sakęs.'),
  (@b2, 8, 20, 'Ir VIEŠPATS tarė Mozei: „Atsikelk anksti ryte ir stokis faraono akivaizdon; štai jis išeina prie vandens; ir jam sakyk: ‘Taip sako VIEŠPATS: Išleisk mano tautą, kad jie man tarnautų.'),
  (@b2, 8, 21, 'Kitaip, jei tu neišleisi mano tautos, štai aš atsiųsiu musių spiečius ant tavęs, ant tavo tarnų, ant tavo tautos ir į tavo namus; ir egiptiečių namai bus pilni musių spiečių ir taip pat žemė, ant kurios jie yra.'),
  (@b2, 8, 22, 'Ir tą dieną aš atskirsiu Gošeno šalį, kurioje gyvena mano tauta, kad ten nebūtų musių spiečių; tuo tikslu, kad žinotum, jog aš esu VIEŠPATS žemės viduryje.'),
  (@b2, 8, 23, 'Ir aš padarysiu skirtumą tarp mano tautos ir tavo tautos; rytoj bus šitas ženklas’“.'),
  (@b2, 8, 24, 'Ir VIEŠPATS taip padarė; ir didžiulis musių spiečius atskrido į faraono namus, į jo tarnų namus ir į visą Egipto šalį; žemė buvo pagadinta dėl to musių spiečiaus.'),
  (@b2, 8, 25, 'Ir faraonas, pašaukęs Mozę ir Aaroną, tarė: „Eikite, aukokite savo Dievui šioje šalyje“.'),
  (@b2, 8, 26, 'O Mozė tarė: „Nedera taip daryti; nes mes aukosime egiptiečių pasibjaurėjimą VIEŠPAČIUI, savo Dievui; štai jei mes aukosime egiptiečių pasibjaurėjimą jų akyse, argi jie mūsų neužmėtys akmenimis?'),
  (@b2, 8, 27, 'Mes eisime trijų dienų kelionę į dykumą ir aukosime VIEŠPAČIUI, savo Dievui, kaip jis mums įsakys“.'),
  (@b2, 8, 28, 'Ir faraonas tarė: „Aš jus išleisiu, kad jūs aukotumėte VIEŠPAČIUI, jūsų Dievui, dykumoje; tik nenueikite labai toli; maldaukite už mane“.'),
  (@b2, 8, 29, 'Ir Mozė tarė: „Štai iš tavęs išėjęs aš maldausiu VIEŠPATĮ, kad rytoj musių spiečiai pasišalintų nuo faraono, nuo jo tarnų ir jo tautos; bet daugiau tenesielgia faraonas apgaulingai, neišleisdamas tautos VIEŠPAČIUI aukoti“.'),
  (@b2, 8, 30, 'Ir Mozė išėjo iš faraono ir maldavo VIEŠPATĮ.'),
  (@b2, 8, 31, 'Ir VIEŠPATS padarė pagal Mozės žodį: jis pašalino musių spiečius nuo faraono, nuo jo tarnų ir nuo jo tautos; nei vienos nebeliko.'),
  (@b2, 8, 32, 'Bet ir šįkart faraonas užkietino savo širdį ir neišleido tautos.'),
  (@b2, 9, 1, 'Tada VIEŠPATS tarė Mozei: „Įeik pas faraoną ir jam tark: ‘Taip sako VIEŠPATS, hebrajų Dievas: Išleisk mano tautą, kad jie man tarnautų.'),
  (@b2, 9, 2, 'Nes jei atsisakysi juos paleisti ir vis dar juos sulaikysi,'),
  (@b2, 9, 3, 'štai VIEŠPATIES ranka yra ant lauke esančių tavo galvijų, ant arklių, ant asilų, ant kupranugarių, ant jaučių ir ant avių: bus labai sunkus maras.'),
  (@b2, 9, 4, 'Ir VIEŠPATS darys skirtumą tarp Izraelio galvijų ir Egipto galvijų; ir niekas nepadvės iš viso to, kas yra Izraelio vaikų’“.'),
  (@b2, 9, 5, 'Ir VIEŠPATS paskyrė nustatytą laiką, tardamas: „Rytoj VIEŠPATS padarys šitą dalyką šalyje“.'),
  (@b2, 9, 6, 'Ir rytojaus dieną VIEŠPATS padarė šitą dalyką, ir išdvėsė visi Egipto galvijai; bet iš Izraelio vaikų galvijų nei vienas nenugaišo.'),
  (@b2, 9, 7, 'Ir faraonas pasiuntė, ir štai iš izraelitų galvijų nei vienas nebuvo nugaišęs. Bet faraono širdis užkietėjo, ir jis neišleido tautos.'),
  (@b2, 9, 8, 'Ir VIEŠPATS tarė Mozei ir Aaronui: „Pasiimkite pilnas saujas krosnies pelenų, ir tegul Mozė juos paberia į dangų faraono akivaizdoje.'),
  (@b2, 9, 9, 'Ir jie taps smulkiomis dulkėmis visoje Egipto šalyje, ir ant žmonių ir ant gyvulių bus votys, iškylančios pūslėmis visoje Egipto šalyje“.'),
  (@b2, 9, 10, 'Ir jie ėmė krosnies pelenų ir atsistojo faraono akivaizdoje; ir Mozė juos pabėrė į dangų; ir jie tapo votimis, iškylančiomis pūslėmis ant žmonių ir ant gyvulių.'),
  (@b2, 9, 11, 'Ir burtininkai negalėjo stotis Mozės akivaizdon dėl vočių; nes votys buvo ant burtininkų ir ant visų egiptiečių.'),
  (@b2, 9, 12, 'Bet VIEŠPATS užkietino faraono širdį, ir jis neklausė jų; kaip VIEŠPATS buvo kalbėjęs Mozei.'),
  (@b2, 9, 13, 'Ir VIEŠPATS tarė Mozei: „Atsikelk anksti ryte, stokis faraono akivaizdon ir jam sakyk: ‘Taip sako VIEŠPATS, hebrajų Dievas: Išleisk mano tautą, kad ji man tarnautų.'),
  (@b2, 9, 14, 'Nes šįkart aš siųsiu visas savo rykštes ant tavo širdies, ant tavo tarnų ir ant tavo tautos; kad žinotum, jog nėra nei vieno man lygaus visoje žemėje.'),
  (@b2, 9, 15, 'Nes dabar aš ištiesiu savo ranką, kad ištikčiau maru tave ir tavo tautą; ir tu būsi iškirstas nuo žemės.'),
  (@b2, 9, 16, 'Bet iš tikrųjų dėl tos priežasties tave iškėliau, kad tavyje parodyčiau savo galybę; ir kad mano vardas būtų skelbiamas po visą žemę.'),
  (@b2, 9, 17, 'Ar tu vis dar aukštini save prieš mano tautą, kad jos neišleistum?'),
  (@b2, 9, 18, 'Štai rytoj apie šitą laiką aš padarysiu, kad lytų labai sunki kruša, kokios nėra buvę Egipte nuo jo įsikūrimo iki dabar.'),
  (@b2, 9, 19, 'Taigi dabar siųsk, surink savo galvijus ir visa, ką turi ant lauko; nes ant visų žmonių ir gyvulių, kurie bus rasti ant lauko ir nebus parvesti namo, kris kruša, ir jie mirs’“.'),
  (@b2, 9, 20, 'Kas tarp faraono tarnų bijojo VIEŠPATIES žodžio, vertė bėgti į namus savo tarnus ir savo galvijus;'),
  (@b2, 9, 21, 'o kas nekreipė dėmesio į VIEŠPATIES žodį, paliko savo tarnus ir savo galvijus lauke.'),
  (@b2, 9, 22, 'Ir VIEŠPATS tarė Mozei: „Ištiesk savo ranką į dangų, kad būtų kruša visoje Egipto šalyje: ant žmonių, ant gyvulių ir ant visų lauko žolių visoje Egipto šalyje“.'),
  (@b2, 9, 23, 'Ir Mozė ištiesė savo lazdą į dangų; ir VIEŠPATS siuntė griaustinį ir krušą, ir ugnis sklido po žemę; ir VIEŠPATS pylė krušą ant Egipto šalies.'),
  (@b2, 9, 24, 'Taigi kruša ir ugnis, susimaišiusi su kruša, buvo labai sunki, kokios nėra buvę visoje Egipto šalyje nuo tada, kai ji tapo tauta.'),
  (@b2, 9, 25, 'Ir visoje Egipto šalyje kruša išmušė visa, kas buvo ant lauko: tiek žmones, tiek gyvulius; ir kruša išmušė visas lauko žoles ir sulaužė visus lauko medžius.'),
  (@b2, 9, 26, 'Tik Gošeno šalyje, kur buvo Izraelio vaikai, nebuvo krušos.'),
  (@b2, 9, 27, 'Ir faraonas pasiuntęs pašaukė Mozę bei Aaroną ir jiems tarė: „Šį kartą nusidėjau; VIEŠPATS yra teisus, o aš ir mano tauta esame blogi.'),
  (@b2, 9, 28, 'Maldaukite VIEŠPATĮ (nes jau gana), kad nebebūtų galingų griaustinių ir krušos; ir aš jus išleisiu, ir jūs ilgiau nebepasiliksite“.'),
  (@b2, 9, 29, 'Ir Mozė jam tarė: „Kai tik būsiu išėjęs iš miesto, aš išskėsiu savo rankas į VIEŠPATĮ; griaustiniai nustos ir krušos nebebus; idant žinotum, kad žemė yra VIEŠPATIES.'),
  (@b2, 9, 30, 'Bet, kas dėl tavęs ir tavo tarnų, aš žinau, kad jūs vis dar nebijosite VIEŠPATIES Dievo“.'),
  (@b2, 9, 31, 'Linai ir miežiai buvo išmušti; nes miežiai buvo varpose, o linai buvo sukrovę sėklas.'),
  (@b2, 9, 32, 'Bet kviečiai ir rugiai nebuvo išmušti; nes jie nebuvo subrendę.'),
  (@b2, 9, 33, 'Ir Mozė išėjo nuo faraono iš miesto ir išskėtė savo rankas į VIEŠPATĮ; ir liovėsi griaustiniai ir kruša, ir lietus nebepylė į žemę.'),
  (@b2, 9, 34, 'O faraonas, matydamas, kad lietus, kruša ir griaustiniai liovėsi, vėl nusidėjo ir užkietino savo širdį, jis ir jo tarnai.'),
  (@b2, 9, 35, 'Ir faraono širdis užkietėjo, ir jis neišleido Izraelio vaikų; kaip VIEŠPATS buvo kalbėjęs per Mozę.'),
  (@b2, 10, 1, 'Ir VIEŠPATS tarė Mozei: „Įeik pas faraoną; nes aš užkietinau jo širdį ir jo tarnų širdis, kad parodyčiau šituos savo ženklus jo akivaizdoje;'),
  (@b2, 10, 2, 'ir kad pasakotum savo sūnums ir savo sūnų sūnums į ausis, kokių dalykų padariau Egipte, ir mano ženklus, kuriuos padariau tarp jų; kad jūs žinotumėte, jog aš esu VIEŠPATS“.'),
  (@b2, 10, 3, 'Ir Mozė ir Aaronas įėjo pas faraoną ir jam tarė: „Taip sako VIEŠPATS, hebrajų Dievas: ‘Kaip ilgai atsisakysi nusižeminti prieš mane? Išleisk mano tautą, kad ji man tarnautų.'),
  (@b2, 10, 4, 'Kitaip, jei tu atsisakysi išleisti mano tautą, štai rytoj atvesiu į tavo sritį skėrių;'),
  (@b2, 10, 5, 'ir jie taip apdengs žemės paviršių, kad nebus galima matyti žemės; ir jie ės išgelbėtą likutį, kuris jums išliko nuo krušos, ir ės nuo lauko kiekvieną jums augantį medį;'),
  (@b2, 10, 6, 'ir jie pripildys tavo namus, visų tavo tarnų namus ir visų egiptiečių namus; ko nėra matę nei tavo tėvai, nei tavo tėvų tėvai nuo tos dienos, kai jie buvo žemėje, iki šios dienos’“. Ir jis apsigręžė ir išėjo iš faraono.'),
  (@b2, 10, 7, 'Ir faraono tarnai jam tarė: „Kaip ilgai šitas žmogus bus mums žabangos? Išleisk tuos žmones, kad jie tarnautų VIEŠPAČIUI, savo Dievui; ar dar nežinai, kad Egiptas yra sunaikintas?“'),
  (@b2, 10, 8, 'Ir Mozė ir Aaronas buvo vėl atvesti pas faraoną; ir jis jiems tarė: „Eikite, tarnaukite VIEŠPAČIUI, savo Dievui; bet kas yra tie, kurie eis?“'),
  (@b2, 10, 9, 'Ir Mozė tarė: „Eisime su savo jaunais ir savo senais, su savo sūnumis ir savo dukterimis, su savo kaimenėmis ir savo bandomis eisime; nes mes turime švęsti šventę VIEŠPAČIUI“.'),
  (@b2, 10, 10, 'Bet jis jiems tarė: „VIEŠPATS tebūna su jumis taip, kaip aš išleisiu jus ir jūsų mažylius; žiūrėkitės; nes jūsų priešakyje yra pikta.'),
  (@b2, 10, 11, 'Ne taip; eikite dabar jūs, vyrai, ir tarnaukite VIEŠPAČIUI; nes to jūs norėjote“. Ir juos išvarė iš faraono akivaizdos.'),
  (@b2, 10, 12, 'Ir VIEŠPATS tarė Mozei: „Ištiesk savo ranką virš Egipto šalies dėl skėrių, kad jie ateitų ant Egipto šalies ir ėstų visas šalies žoles, visa, ką paliko kruša“.'),
  (@b2, 10, 13, 'Ir Mozė ištiesė savo lazdą virš Egipto šalies, ir VIEŠPATS nešė rytų vėją ant šalies visą tą dieną ir visą tą naktį; o kai buvo rytas, rytų vėjas atnešė skėrius.'),
  (@b2, 10, 14, 'Ir skėriai užkilo virš visos Egipto šalies ir nusileido visoje Egipto srityje; jie buvo labai sunkūs; prieš juos nėra buvę tokių skėrių kaip tie, nei po jų tokių nebus.'),
  (@b2, 10, 15, 'Nes jie taip apdengė visos žemės paviršių, kad šalis buvo aptemdyta; ir jie ėdė visas šalies žoles ir visus medžių vaisius, kuriuos buvo palikusi kruša; ir neliko nieko, kas žalia ant medžių ar ant lauko žolių, visoje Egipto šalyje.'),
  (@b2, 10, 16, 'Tada faraonas skubiai pašaukė Mozę ir Aaroną; ir tarė: „Nusidėjau prieš VIEŠPATĮ, jūsų Dievą, ir prieš jus.'),
  (@b2, 10, 17, 'Taigi dabar, meldžiu tave, atleisk mano nuodėmę tik šį vieną kartą ir maldaukite VIEŠPATĮ, savo Dievą, kad jis tik pašalintų nuo manęs šitą mirtį“.'),
  (@b2, 10, 18, 'Ir jis išėjo iš faraono ir maldavo VIEŠPATĮ.'),
  (@b2, 10, 19, 'Ir VIEŠPATS atsuko labai smarkų vakarų vėją, kuris pašalino skėrius ir įmetė juos į Raudonąją jūrą; nei vieno skėrio neliko visose Egipto ribose.'),
  (@b2, 10, 20, 'Bet VIEŠPATS užkietino faraono širdį taip, kad jis neišleido Izraelio vaikų.'),
  (@b2, 10, 21, 'Ir VIEŠPATS tarė Mozei: „Ištiesk savo ranką į dangų, kad tamsa būtų virš Egipto šalies, tamsa, kurią būtų galima pajusti“.'),
  (@b2, 10, 22, 'Ir Mozė ištiesė savo ranką į dangų; ir tiršta tamsa buvo tris dienas visoje Egipto šalyje;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b2, 10, 23, 'per tris dienas jie nematė vienas kito, nei niekas nesikėlė iš savo vietos; bet visi Izraelio vaikai turėjo šviesą savo buveinėse.'),
  (@b2, 10, 24, 'Ir faraonas pašaukęs Mozę tarė: „Eikite, tarnaukite VIEŠPAČIUI; tik jūsų kaimenės ir jūsų bandos tepasilieka; jūsų mažyliai irgi teeina su jumis“.'),
  (@b2, 10, 25, 'Bet Mozė tarė: „Tu turi mums duoti taip pat ir aukas bei deginamąsias atnašas, kad mes aukotume VIEŠPAČIUI, mūsų Dievui.'),
  (@b2, 10, 26, 'Mūsų galvijai irgi eis su mumis; nepasiliks nei viena kanopa; nes iš to mes turime imti, kad tarnautume VIEŠPAČIUI, savo Dievui; o mes nežinome, kuo mes turime tarnauti VIEŠPAČIUI, kol ten neatėjome“.'),
  (@b2, 10, 27, 'Bet VIEŠPATS užkietino faraono širdį, ir jis nenorėjo jų išleisti.'),
  (@b2, 10, 28, 'Ir faraonas jam tarė: „Eik nuo manęs, saugokis, nebeišvysk daugiau mano veido; nes tą dieną, kai išvysi mano veidą, mirsi“.'),
  (@b2, 10, 29, 'Ir Mozė tarė: „Tu gerai pasakei, aš daugiau nebeišvysiu tavo veido“.'),
  (@b2, 11, 1, 'Ir VIEŠPATS tarė Mozei: „Dar vieną rykštę užleisiu ant faraono ir ant Egipto; po to jis išleis jus iš čia; kai jis jus išleis, jis tikrai jus išvarys iš čia visiškai.'),
  (@b2, 11, 2, 'Kalbėk dabar tautai į ausis, ir tegul kiekvienas iš savo kaimyno ir kiekviena iš savo kaimynės pasiskolina sidabrinių ir auksinių brangenybių“.'),
  (@b2, 11, 3, 'Ir VIEŠPATS davė tautai palankumą egiptiečių akyse. Be to, tas vyras Mozė buvo labai didis Egipto šalyje, faraono tarnų akyse ir tautos akyse.'),
  (@b2, 11, 4, 'Ir Mozė tarė: „Taip sako VIEŠPATS: ‘Apie vidurnaktį aš išeisiu į Egipto vidurį;'),
  (@b2, 11, 5, 'ir išmirs visi pirmagimiai Egipto šalyje, nuo faraono pirmagimio, kuris sėdi jo soste, iki pirmagimio tarnaitės, esančios prie girnų; ir visi gyvulių pirmagimiai.'),
  (@b2, 11, 6, 'Ir visoje Egipto šalyje bus didis šauksmas, kokio nėra buvę ir kokio daugiau nebebus.'),
  (@b2, 11, 7, 'Bet nei prieš vieną iš Izraelio vaikų nei šuo nepajudins savo liežuvio, nei prieš žmogų, nei gyvulį; kad jūs žinotumėte, jog VIEŠPATS daro skirtumą tarp egiptiečių ir Izraelio.'),
  (@b2, 11, 8, 'Ir visi šitie tavo tarnai nusileis pas mane ir man nusilenks, sakydami: „Išeik tu ir visa tauta, kuri seka paskui tave“; o po to išeisiu’“. Ir jis išėjo iš faraono didžiai supykęs.'),
  (@b2, 11, 9, 'Ir VIEŠPATS tarė Mozei: „Faraonas jūsų neklausys; kad mano stebuklų padaugėtų Egipto šalyje“.'),
  (@b2, 11, 10, 'O Mozė ir Aaronas padarė visus šituos stebuklus faraono akivaizdoje; bet VIEŠPATS užkietino faraono širdį taip, kad jis neišleido Izraelio vaikų iš savo šalies.'),
  (@b2, 12, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui Egipto šalyje, sakydamas:'),
  (@b2, 12, 2, '„Šitas mėnuo jums bus mėnesių pradžia; jis jums bus pirmasis metų mėnuo.'),
  (@b2, 12, 3, 'Kalbėkite visam Izraelio susirinkimui, sakydami: ‘Šito mėnesio dešimtąją dieną tegul jie ima kiekvienas po avinėlį, pagal jų tėvų namus, po avinėlį namams;'),
  (@b2, 12, 4, 'o jei namai per maži avinėliui, tegul jis su savo kaimynu, gretimu jo namams, paima jį atsižvelgiant į sielų skaičių; kiekvienas pagal savo suvalgymą apsiskaičiuokite dėl avinėlio.'),
  (@b2, 12, 5, 'Jūsų avinėlis turi būti be trūkumų, pirmametis patinas; paimkite jį iš avių ar ožkų;'),
  (@b2, 12, 6, 'ir jį laikykite iki šito mėnesio keturioliktos dienos; ir visa Izraelio susirinkimo sueiga jį papjaus vakare.'),
  (@b2, 12, 7, 'Ir jie turi paimti kraujo ir juo patepti abi šonines staktas bei viršutinę durų staktą tų namų, kuriuose jie valgys jį.'),
  (@b2, 12, 8, 'Ir tą naktį jie turi valgyti mėsą, keptą ugnimi, su nerauginta duona; su karčiomis žolėmis jie turi jį valgyti.'),
  (@b2, 12, 9, 'Nevalgykite jo žalio ar kokiu būdu virto vandenyje, bet iškepkite ugnimi: jo galvą su jo kojomis ir su jo viduriais.'),
  (@b2, 12, 10, 'Ir nieko iš jo nepalikite iki ryto; o kas iš jo paliks iki ryto, sudeginkite ugnimi.'),
  (@b2, 12, 11, 'Ir taip jį valgykite: susijuosę strėnas, su apavu ant kojų ir su savo lazda rankoje; ir jį valgykite paskubomis; tai yra VIEŠPATIES Apėjimas.'),
  (@b2, 12, 12, 'Nes šitą naktį aš pereisiu per Egipto šalį ir užmušiu visus pirmagimius Egipto šalyje, tiek žmones, tiek gyvulius; ir visiems Egipto dievams įvykdysiu teismą; aš esu VIEŠPATS.'),
  (@b2, 12, 13, 'O kraujas bus jums ženklas ant namų, kuriuose jūs esate; ir pamatęs kraują jus apeisiu, ir rykštės jums nebus, kad jus sunaikintų, man ištinkant Egipto šalį.'),
  (@b2, 12, 14, 'Ir šita diena bus jums atminimui; ir ją švęsite kaip šventę VIEŠPAČIUI per savo kartas; ją švęskite kaip šventę amžinu įsaku.'),
  (@b2, 12, 15, 'Septynias dienas valgykite neraugintą duoną; jau pirmąją dieną pašalinkite raugą iš savo namų; nes kiekvienas, kuris valgys raugintos duonos nuo pirmosios iki septintosios dienos, ta siela bus iškirsta iš Izraelio.'),
  (@b2, 12, 16, 'Ir pirmąją dieną bus šventas sušaukimas, ir septintąją dieną bus jums šventas sušaukimas; jokio darbo nebus galima dirbti jomis, išskyrus tai, ką kiekvienas turi valgyti, tik tai gali būti daroma jūsų.'),
  (@b2, 12, 17, 'Ir laikykitės neraugintos duonos šventės; nes šitą pačią dieną aš išvedžiau jūsų kariuomenes iš Egipto šalies; todėl laikykitės šitos dienos per savo kartas amžinu įsaku.'),
  (@b2, 12, 18, 'Pirmąjį mėnesį, keturioliktąją to mėnesio dieną, vakare, valgykite neraugintą duoną, iki dvidešimt pirmosios to mėnesio dienos, vakare.'),
  (@b2, 12, 19, 'Septynias dienas neturi atsirasti raugo jūsų namuose; nes kiekvienas, kuris valgys tai, kas rauginta, ta siela bus iškirsta iš Izraelio susirinkimo, ar jis būtų ateivis, ar gimęs šioje šalyje.'),
  (@b2, 12, 20, 'Nieko rauginto nevalgysite; visose savo buveinėse valgysite neraugintą duoną’“.'),
  (@b2, 12, 21, 'Tada Mozė sušaukė visus Izraelio vyresniuosius ir jiems tarė: „Ištraukite ir imkite sau avinėlį pagal jūsų šeimas ir papjaukite Apėjimą.'),
  (@b2, 12, 22, 'Ir paimkite pundelį yzopo ir, pamirkę jį į dubenyje esantį kraują, patepkite sąramą ir abi šonines staktas dubenyje esančiu krauju; ir nei vienas jūsų teneišeina iki ryto iš savo namų durų.'),
  (@b2, 12, 23, 'Nes VIEŠPATS pereis, kad užmuštų egiptiečius; ir pamatęs kraują ant sąramos ir abiejų šoninių staktų, VIEŠPATS apeis duris ir neleis naikintojui įeiti į jūsų namus jūsų užmušti.'),
  (@b2, 12, 24, 'O jūs laikykitės šito dalyko kaip įsako tau ir tavo vaikams amžinai.'),
  (@b2, 12, 25, 'Ir įvyks, kai būsite atvykę į šalį, kurią VIEŠPATS jums duos, kaip jis yra pažadėjęs, tai laikykitės šito tarnavimo.'),
  (@b2, 12, 26, 'Ir įvyks, kai jūsų vaikai jums sakys: ‘Ką turite omenyje šituo tarnavimu?’,'),
  (@b2, 12, 27, 'tai jūs sakykite: ‘Tai yra Apėjimo auka VIEŠPATIES, kuris apėjo Izraelio vaikų namus Egipte, kai jis sumušė egiptiečius, o mūsų namus išgelbėjo’“. Ir tauta nulenkė galvas ir pagarbino.'),
  (@b2, 12, 28, 'Ir Izraelio vaikai nuėjo ir padarė, kaip VIEŠPATS buvo įsakęs Mozei ir Aaronui, taip jie padarė.'),
  (@b2, 12, 29, 'Ir įvyko, kad vidurnaktį VIEŠPATS užmušė visus pirmagimius Egipto šalyje – nuo faraono pirmagimio, sėdinčio jo soste, iki pirmagimio belaisvio, esančio požeminiame kalėjime; ir visus galvijų pirmagimius.'),
  (@b2, 12, 30, 'Ir faraonas tą naktį atsikėlė, jis, visi jo tarnai ir visi egiptiečiai; ir buvo didis šauksmas Egipte; nes nebuvo namų, kuriuose nebūtų buvę numirusio.'),
  (@b2, 12, 31, 'Ir jis nakčia pašaukė Mozę bei Aaroną ir tarė: „Kelkitės, išeikite iš mano tautos tarpo, tiek jūs, tiek Izraelio vaikai; ir eikite, tarnaukite VIEŠPAČIUI, kaip esate sakę.'),
  (@b2, 12, 32, 'Taip pat imkite savo kaimenes ir savo bandas, kaip esate sakę, ir eikite; taip pat mane palaiminkite“.'),
  (@b2, 12, 33, 'Ir egiptiečiai ragino tautą, kad skubiai juos išsiųstų iš šalies; nes jie tarė: „Mes visi būsime numirėliai“.'),
  (@b2, 12, 34, 'Ir tauta ėmė savo dar neįrūgusią tešlą, savo duonkubilius, įvyniotus į jų drabužius, ant savo pečių.'),
  (@b2, 12, 35, 'Ir Izraelio vaikai padarė pagal Mozės žodį: ir jie pasiskolino iš egiptiečių sidabro brangenybių, aukso brangenybių ir drabužių;'),
  (@b2, 12, 36, 'ir VIEŠPATS davė tautai palankumą egiptiečių akyse, jog jie paskolino jiems tokių dalykų, kokių jie prašė. Ir jie apiplėšė egiptiečius.'),
  (@b2, 12, 37, 'Ir Izraelio vaikai keliavo iš Ramzio į Sukotą: apie šešis šimtus tūkstančių pėsčių vyrų, neskaitant vaikų.'),
  (@b2, 12, 38, 'Ir mišri daugybė taip pat ėjo su jais aukštyn; ir kaimenės bei bandos, labai daug galvijų.'),
  (@b2, 12, 39, 'Ir jie kepė neraugintus pyragus iš tešlos, kurią jie išsinešė iš Egipto, nes ji nebuvo rauginta; kadangi jie buvo išvaryti iš Egipto ir nebegalėjo delsti, nei nepasigamino jie maisto.'),
  (@b2, 12, 40, 'Na, o Izraelio vaikų, gyvenusių Egipte, laikinai apsigyventa buvo keturis šimtus trisdešimt metų.'),
  (@b2, 12, 41, 'Ir įvyko, pasibaigus keturiems šimtams trisdešimčiai metų, tą pačią dieną įvyko, kad visos VIEŠPATIES kariuomenės išėjo iš Egipto šalies.'),
  (@b2, 12, 42, 'Tai naktis, kurios labai turėtų būti laikomasi VIEŠPAČIUI dėl jų išvedimo iš Egipto šalies; tai ta VIEŠPATIES naktis, kurios turi laikytis visi Izraelio vaikai jų kartose.'),
  (@b2, 12, 43, 'Ir VIEŠPATS tarė Mozei ir Aaronui: „Šitas yra Apėjimo įsakas: Jokiam ateiviui negalima jo valgyti;'),
  (@b2, 12, 44, 'bet kiekvieno tarnas, nupirktas už pinigus, kai būsi jį apipjaustęs, tuomet jis galės jo valgyti.'),
  (@b2, 12, 45, 'Svetimšaliui ir samdiniui negalima jo valgyti.'),
  (@b2, 12, 46, 'Vienuose namuose jis turi būti valgomas; nieko iš tos mėsos neišnešk iš namų laukan; nei nesulaužykite jo kaulo.'),
  (@b2, 12, 47, 'Visas Izraelio susirinkimas turi jo laikytis.'),
  (@b2, 12, 48, 'O kai ateivis laikinai apsigyvens pas tave ir norės švęsti Apėjimą VIEŠPAČIUI, tai tebūna apipjaustyti visi jo vyriškiai, o tada jis tepriartėja ir jį tešvenčia; ir jis bus kaip gimusysis šioje šalyje; nes joks neapipjaustytas asmuo jo nevalgys.'),
  (@b2, 12, 49, 'Vienas įstatymas bus pas jus gimusiam ir ateiviui, laikinai apsigyvenusiam tarp jūsų“.'),
  (@b2, 12, 50, 'Taip padarė visi Izraelio vaikai; kaip VIEŠPATS įsakė Mozei ir Aaronui, taip jie padarė.'),
  (@b2, 12, 51, 'Ir įvyko tą pačią dieną, kad VIEŠPATS išvedė Izraelio vaikus jų kariuomenėmis iš Egipto šalies.'),
  (@b2, 13, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 13, 2, '„Pašvęsk man visus pirmagimius, kurie Izraelio vaikų tarpe atveria įsčias, tiek iš žmonių, tiek iš gyvulių; tai yra mano“.'),
  (@b2, 13, 3, 'Ir Mozė tarė tautai: „Atsiminkite šitą dieną, kurią išėjote iš Egipto, iš vergystės namų; nes rankos jėga VIEŠPATS jus išvedė iš šios vietos; rauginta duona nebus valgoma.'),
  (@b2, 13, 4, 'Šią dieną jūs išėjote, Abibo mėnesį.'),
  (@b2, 13, 5, 'Ir kai VIEŠPATS tave nuves į kanaaniečių, hetitų, amoritų, hivų ir jebusiečių šalį, kurią jis prisiekė tavo tėvams tau duoti, šalį, plūstančią pienu ir medumi, tada tu laikykis šito tarnavimo šį mėnesį.'),
  (@b2, 13, 6, 'Septynias dienas valgyk neraugintą duoną, o septintąją dieną bus šventė VIEŠPAČIUI.'),
  (@b2, 13, 7, 'Nerauginta duona turi būti valgoma septynias dienas; ir raugintos duonos neturi matytis pas tave, ir nei raugo neturi matytis pas tave visose tavo ribose.'),
  (@b2, 13, 8, 'Ir skelbk savo sūnui tą dieną, sakydamas: ‘Tai daroma dėl to, ką VIEŠPATS man padarė, kai išėjau iš Egipto’.'),
  (@b2, 13, 9, 'Ir tai tau bus ženklu ant tavo rankos ir prisiminimu tarp tavo akių, kad VIEŠPATIES įstatymas būtų tavo burnoje; nes stipria ranka VIEŠPATS tave išvedė iš Egipto.'),
  (@b2, 13, 10, 'Todėl laikykis šio įsako jo laiku, iš metų į metus.'),
  (@b2, 13, 11, 'Ir kai VIEŠPATS tave nuves į kanaaniečių šalį, kaip jis prisiekė tau ir tavo tėvams, ir tau ją duos,'),
  (@b2, 13, 12, 'tada tu atskirk VIEŠPAČIUI visus atveriančius gimdą ir kiekvieną pirmagimį, išeinantį iš gyvulio, kurį tu turi; vyriškos lyties esantys bus VIEŠPATIES.'),
  (@b2, 13, 13, 'Ir kiekvieną asilo pirmagimį išpirk avinėliu; o jei jo neišpirksi, tuomet nulaužk jam sprandą; ir visus žmonių pirmagimius tarp tavo vaikų atpirk.'),
  (@b2, 13, 14, 'Ir įvyks, kai ateityje tavo sūnus tave paklaus, sakydamas: ‘Kas tai?’, tai tu jam sakyk: ‘Rankos jėga VIEŠPATS mus išvedė iš Egipto, iš vergystės namų;'),
  (@b2, 13, 15, 'ir įvyko, kai faraonas sunkiai norėjo mus išleisti, tada VIEŠPATS nužudė visus pirmagimius Egipto šalyje, tiek žmonių pirmagimius, tiek gyvulių pirmagimius; todėl aš aukoju VIEŠPAČIUI visus, esančius vyriškos lyties, atveriančius gimdą; bet visus mano vaikų pirmagimius aš atperku.'),
  (@b2, 13, 16, 'Ir tai bus kaip ženklas ant tavo rankos ir kaip galvaraištis tarp tavo akių; nes rankos jėga VIEŠPATS mus išvedė iš Egipto’“.'),
  (@b2, 13, 17, 'Ir įvyko, faraonui išleidus tautą, Dievas jos nevedė filistinų šalies keliu, nors tai buvo arti; nes Dievas tarė: „Kad pamačiusi karą, tauta neimtų gailėtis ir nesugrįžtų į Egiptą“;'),
  (@b2, 13, 18, 'bet Dievas vedė tautą aplinkui, Raudonosios jūros dykumos keliu; ir Izraelio vaikai apsiginklavę ėjo aukštyn iš Egipto šalies.'),
  (@b2, 13, 19, 'Ir Mozė ėmė su savimi Juozapo kaulus; nes jis buvo griežtai prisaikdinęs Izraelio vaikus, tardamas: „Dievas tikrai aplankys jus; o jūs išneškite iš čia aukštyn mano kaulus su savimi“.'),
  (@b2, 13, 20, 'Ir jie leidosi kelionėn iš Sukoto ir stovyklavo Etame, dykumos pakraštyje.'),
  (@b2, 13, 21, 'O VIEŠPATS ėjo pirma jų dieną debesies stulpe, kad juos vestų keliu; o naktį ugnies stulpe, kad šviestų jiems; kad eitų dieną ir naktį;'),
  (@b2, 13, 22, 'jis nepatraukė nuo tautos priešakio nei debesies stulpo dieną, nei ugnies stulpo naktį.'),
  (@b2, 14, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 14, 2, '„Kalbėk Izraelio vaikams, kad jie pasuktų ir stovyklautų prieš Pi-Hahirotą, tarp Migdolo ir jūros, priešais Baal-Sefoną; stovyklaukite prieš jį, pajūryje.'),
  (@b2, 14, 3, 'Nes faraonas sakys apie Izraelio vaikus: ‘Jie susipainioję šalyje, dykuma juos užrakino’.'),
  (@b2, 14, 4, 'O aš užkietinsiu faraono širdį, kad jis juos persekios; ir aš būsiu gerbiamas ant faraono bei visos jo kariuomenės; kad egiptiečiai žinotų, jog aš esu VIEŠPATS“. Ir jie taip padarė.'),
  (@b2, 14, 5, 'O Egipto karaliui buvo pranešta, kad tauta pabėgo; ir faraono ir jo tarnų širdis atsigręžė prieš tautą, ir jie tarė: „Kodėl mes tai padarėme, išleisdami Izraelį nuo tarnavimo mums?“'),
  (@b2, 14, 6, 'Ir jis pasikinkė savo vežimą ir ėmėsi su savimi savo tautą;'),
  (@b2, 14, 7, 'ir jis paėmė šešis šimtus rinktinių vežimų ir visus Egipto vežimus, ir jų visų vadus.'),
  (@b2, 14, 8, 'Ir VIEŠPATS užkietino Egipto karaliaus faraono širdį, ir jis persekiojo Izraelio vaikus; o Izraelio vaikai išėjo aukšta ranka.'),
  (@b2, 14, 9, 'Bet egiptiečiai juos persekiojo, visi faraono žirgai, vežimai, jo raiteliai ir jo kariuomenė, ir pasivijo juos bestovyklaujančius palei jūrą, ties Pi-Hahirotu, prieš Baal-Sefoną.'),
  (@b2, 14, 10, 'Ir faraonui priartėjus, Izraelio vaikai pakėlė savo akis, ir štai egiptiečiai žygiavo jiems iš paskos; ir jie labai išsigando; ir Izraelio vaikai šaukėsi VIEŠPATIES.'),
  (@b2, 14, 11, 'Ir jie tarė Mozei: „Ar todėl, kad nebuvo kapų Egipte, mus išsivedei, kad numirtume dykumoje? Kodėl taip su mumis pasielgei, išvesdamas mus iš Egipto?'),
  (@b2, 14, 12, 'Ar ne tas yra žodis, kurį tau kalbėjome Egipte, sakydami: ‘Palik mus, kad mes tarnautume egiptiečiams?’ Nes mums būtų buvę geriau tarnauti egiptiečiams, negu turėtume mirti dykumoje“.'),
  (@b2, 14, 13, 'Ir Mozė tarė tautai: „Nebijokite, stovėkite nejudėdami ir stebėkite VIEŠPATIES išgelbėjimą, kurį jis šiandien jums parodys; nes egiptiečių, kuriuos šiandien matėte, niekada daugiau nematysite per amžius.'),
  (@b2, 14, 14, 'VIEŠPATS kariaus už jus, o jūs tylėsite“.'),
  (@b2, 14, 15, 'Ir VIEŠPATS tarė Mozei: „Ko šaukiesi manęs? Kalbėk Izraelio vaikams, kad jie eitų pirmyn;'),
  (@b2, 14, 16, 'bet tu pakelk savo lazdą, ištiesk savo ranką virš jūros ir perskirk ją; ir Izraelio vaikai eis sausa žeme per jūros vidurį.'),
  (@b2, 14, 17, 'O aš, štai aš užkietinsiu egiptiečių širdis, ir jie eis paskui juos; ir aš įgysiu sau garbę ant faraono, ant visos jo kariuomenės, ant jo vežimų ir ant jo raitelių.'),
  (@b2, 14, 18, 'Ir egiptiečiai žinos, kad aš esu VIEŠPATS, kai būsiu įsigijęs garbę ant faraono, ant jo vežimų ir ant jo raitelių“.'),
  (@b2, 14, 19, 'Ir Dievo angelas, kuris ėjo Izraelio stovyklos priešakyje, atsitraukė ir ėjo jų užnugaryje; ir debesies stulpas nuėjo nuo jų veido ir atsistojo jiems iš užnugario;'),
  (@b2, 14, 20, 'ir jis atėjo tarp egiptiečių stovyklos ir Izraelio stovyklos; ir jis buvo jiems debesis ir tamsa, bet jis naktį švietė šitiems; taip, kad nepriartėjo vieni prie kitų per visą tą naktį.'),
  (@b2, 14, 21, 'Ir Mozė ištiesė savo ranką virš jūros; ir VIEŠPATS visą tą naktį smarkiu rytų vėju vertė jūrą trauktis atgal ir pavertė jūrą sausa žeme, ir vandenys pasidalijo.'),
  (@b2, 14, 22, 'Ir Izraelio vaikai įėjo į jūros vidurį sausuma; o vandenys jiems buvo siena jų dešinėje ir jų kairėje.'),
  (@b2, 14, 23, 'Ir egiptiečiai vijosi ir įėjo paskui juos į jūros vidurį – visi faraono žirgai, jo vežimai ir jo raiteliai.'),
  (@b2, 14, 24, 'Ir įvyko, kad rytiniame budėjime VIEŠPATS iš ugnies ir debesies stulpo pažvelgė į egiptiečių kariuomenę ir sutrikdė egiptiečių kariuomenę,'),
  (@b2, 14, 25, 'ir numovė jų vežimų ratus, kad jie sunkiai juos pavežė; taip, kad egiptiečiai sakė: „Bėkime nuo Izraelio veido; nes VIEŠPATS kariauja už juos prieš egiptiečius“.'),
  (@b2, 14, 26, 'O VIEŠPATS tarė Mozei: „Ištiesk savo ranką virš jūros, kad vandenys sugrįžtų ant egiptiečių, ant jų vežimų ir ant jų raitelių“.'),
  (@b2, 14, 27, 'Ir Mozė ištiesė savo ranką virš jūros ir, rytui pasirodžius, jūra grįžo į savo stiprybę; o egiptiečiai bėgo jai priešais; ir VIEŠPATS pargriovė egiptiečius jūros viduryje.'),
  (@b2, 14, 28, 'Ir vandenys sugrįžo ir uždengė vežimus, raitelius ir visą faraono kariuomenę, atėjusią paskui juos į jūrą; nei vieno iš jų nebeliko.'),
  (@b2, 14, 29, 'Bet Izraelio vaikai ėjo sausuma jūros viduriu; o vandenys jiems buvo siena jų dešinėje ir jų kairėje.'),
  (@b2, 14, 30, 'Taip VIEŠPATS tą dieną išgelbėjo Izraelį iš egiptiečių rankos; ir Izraelis matė egiptiečius mirusius ant jūros kranto.'),
  (@b2, 14, 31, 'Ir Izraelis pamatė tą didį darbą, kurį VIEŠPATS padarė ant egiptiečių; ir tauta bijojo VIEŠPATIES ir tikėjo VIEŠPAČIU bei jo tarnu Moze.'),
  (@b2, 15, 1, 'Tada Mozė ir Izraelio vaikai giedojo VIEŠPAČIUI šitą giesmę ir kalbėjo, sakydami: „Giedosiu VIEŠPAČIUI, nes jis šlovingai nugalėjo; žirgą ir jo raitelį jis įmetė į jūrą.'),
  (@b2, 15, 2, 'VIEŠPATS yra mano stiprybė ir giesmė, ir jis tapo mano išgelbėjimu; jis yra mano Dievas, aš paruošiu jam buveinę; mano tėvo Dievas, aš jį aukštinsiu.'),
  (@b2, 15, 3, 'VIEŠPATS yra karo vyras; VIEŠPATS yra jo vardas.'),
  (@b2, 15, 4, 'Faraono vežimus ir jo kariuomenę jis įmetė į jūrą; jo išrinktieji vadai taip pat nuskendo Raudonojoje jūroje.'),
  (@b2, 15, 5, 'Gelmės uždengė juos; jie nugrimzdo į dugną kaip akmuo.'),
  (@b2, 15, 6, 'Tavo dešinė ranka, o VIEŠPATIE, tapo šlovinga jėgoje; tavo dešinė ranka, o VIEŠPATIE, sutrupino priešą.'),
  (@b2, 15, 7, 'Savo prakilnybės didybe tu pargriovei tuos, kurie sukilo prieš tave; tu siuntei savo rūstybę, kuri suėdė juos kaip ražienas.'),
  (@b2, 15, 8, 'Ir tavo šnervių pūtimu susirinko vandenys, potvyniai stovėjo stačiai kaip krūva, ir gelmės sustingo jūros širdyje.'),
  (@b2, 15, 9, 'Priešas tarė: ‘Vysiuosi, pasivysiu, padalinsiu grobį; mano geismas jais pasitenkins; aš išsitrauksiu kalaviją, juos sunaikins mano ranka’.'),
  (@b2, 15, 10, 'Tu papūtei savo vėju, jūra juos apdengė; jie nuskendo kaip švinas galinguose vandenyse.'),
  (@b2, 15, 11, 'Kas yra tau, o VIEŠPATIE, lygus tarp dievų? Kas šlovingas šventumu, kaip tu, baisus gyriuose, darantis stebuklus?'),
  (@b2, 15, 12, 'Tu ištiesei savo dešinę ranką, juos prarijo žemė.'),
  (@b2, 15, 13, 'Tu savo gailestingumu vedei tautą, kurią atpirkai; tu ją vedei savo stiprybe į savo šventąją buveinę.'),
  (@b2, 15, 14, 'Išgirdusios tautos bijos; sielvartas suims Palestinos gyventojus.'),
  (@b2, 15, 16, 'Ant jų nupuls išgąstis ir didelė baimė; tavo rankos didybe jie bus tylūs kaip akmuo; kol pereis tavo tauta, o VIEŠPATIE, kol pereis tauta, kurią nusipirkai.'),
  (@b2, 15, 17, 'Tu juos įvesi ir pasodinsi juos savo paveldo kalne, vietoje, kurią tu, o VIEŠPATIE, pasidarei sau gyventi, Šventovėje, o Viešpatie, kurią sutvirtino tavo rankos.'),
  (@b2, 15, 18, 'VIEŠPATS karaliaus per amžių amžius“.'),
  (@b2, 15, 19, 'Nes faraono žirgas įėjo su jo vežimais ir jo raiteliais į jūrą, ir VIEŠPATS sugrąžino ant jų jūros vandenis; bet Izraelio vaikai ėjo sausa žeme jūros vidury.'),
  (@b2, 15, 20, 'Ir pranašė Mirjama, Aarono sesuo, pasiėmė į ranką tambūriną; ir visos moterys išėjo paskui ją su tambūrinais ir šokiais.'),
  (@b2, 15, 21, 'Ir Mirjama jiems atsakė: „Giedokite VIEŠPAČIUI, nes jis šlovingai nugalėjo; žirgą ir jo raitelį jis įmetė į jūrą“.'),
  (@b2, 15, 22, 'Taigi Mozė išvedė Izraelį iš Raudonosios jūros, ir jie išėjo į Šūro dykumą; ir tris dienas jie ėjo dykuma ir nerado vandens.'),
  (@b2, 15, 23, 'Ir atvykę į Marą, jie negalėjo gerti Maros vandenų, nes jie buvo kartūs; todėl ji buvo praminta vardu Mara.'),
  (@b2, 15, 24, 'Ir tauta murmėjo prieš Mozę, sakydama: „Ką gersime?“'),
  (@b2, 15, 25, 'Ir jis šaukėsi VIEŠPATIES; ir VIEŠPATS jam parodė medį, kurį jam įmetus į vandenis, vandenys pasidarė saldūs; ten jis nustatė jiems įstatą bei įsaką ir ten juos mėgino,'),
  (@b2, 15, 26, 'ir tarė: „Jei stropiai klausysi VIEŠPATIES, savo Dievo, balso ir darysi, kas teisu jo akyse, ir kreipsi ausį į jo įsakymus, ir laikysies visų jo įstatų, tai ant tavęs neužleisiu nei vienos iš tų ligų, kurias užleidau ant egiptiečių; nes aš esu VIEŠPATS, kuris tave gydo“.'),
  (@b2, 15, 27, 'Ir jie atvyko į Elimą, kur buvo dvylika vandens šaltinių ir septyniasdešimt palmių; ir ten jie stovyklavo prie vandenų.'),
  (@b2, 15, 15, 'Tada Edomo kunigaikščiai stebėsis; Moabo galiūnai – juos drebulys apims; sutirps visi Kanaano gyventojai.'),
  (@b2, 16, 1, 'Ir jie leidosi kelionėn iš Elimo, ir visas Izraelio vaikų susirinkimas atvyko į Sino dykumą, esančią tarp Elimo ir Sinajaus, antrojo mėnesio penkioliktąją dieną po jų išėjimo iš Egipto šalies.'),
  (@b2, 16, 2, 'Ir visas Izraelio vaikų susirinkimas murmėjo prieš Mozę ir Aaroną dykumoje;'),
  (@b2, 16, 3, 'ir Izraelio vaikai jiems sakė: „O kad būtume mirę nuo VIEŠPATIES rankos Egipto šalyje, kai sėdėjome prie mėsos puodų, kai valgėme duonos iki soties; nes jūs mus išvedėte į šitą dykumą, kad numarintumėte badu visą šį susirinkimą“.'),
  (@b2, 16, 4, 'Tada VIEŠPATS tarė Mozei: „Štai aš jums lysiu duona iš dangaus; o tauta išeis ir kasdien rinks tam tikrą saiką, kad juos išmėginčiau, ar jie vaikščios mano įstatymu, ar ne.'),
  (@b2, 16, 5, 'Ir įvyks, kad šeštąją dieną jie paruoš tai, ką parsinešė; ir tai bus dvigubai to, ką jie kasdien surenka“.'),
  (@b2, 16, 6, 'Ir Mozė ir Aaronas tarė visiems Izraelio vaikams: „Vakare jūs žinosite, kad VIEŠPATS jus išvedė iš Egipto šalies;'),
  (@b2, 16, 7, 'o ryte jūs išvysite VIEŠPATIES šlovę; nes jis girdi jūsų murmėjimus prieš VIEŠPATĮ; o kas esame mes, kad murmate prieš mus?“'),
  (@b2, 16, 8, 'Ir Mozė tarė: „Tai bus, kai VIEŠPATS jums duos vakare mėsos valgyti, o ryte duonos iki soties; nes VIEŠPATS girdi jūsų murmėjimus, kuriais jūs murmate prieš jį; o kas mes esame? Jūsų murmėjimai ne prieš mus, bet prieš VIEŠPATĮ“.'),
  (@b2, 16, 9, 'Ir Mozė kalbėjo Aaronui: „Sakyk visam Izraelio vaikų susirinkimui: ‘Priartėkite VIEŠPATIES akivaizdon; nes jis išgirdo jūsų murmėjimus’“.'),
  (@b2, 16, 10, 'Ir įvyko, kad, Aaronui tebekalbant visam Izraelio vaikų susirinkimui, jie pažvelgė į dykumą, ir štai debesyje pasirodė VIEŠPATIES šlovė.'),
  (@b2, 16, 11, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 16, 12, '„Aš girdėjau Izraelio vaikų murmėjimus; kalbėk jiems, sakydamas: ‘Vakare jūs valgysite mėsos, o ryte pasisotinsite duona; ir žinosite, kad aš esu VIEŠPATS, jūsų Dievas’“.'),
  (@b2, 16, 13, 'Ir įvyko, kad vakare užėjo putpelės ir apdengė stovyklą; o ryte rasa apgulė aplink kariuomenę.'),
  (@b2, 16, 14, 'O kai gulinti rasa pakilo, štai ant dykumos paviršiaus gulėjo maži ir apvalūs, maži kaip balsvas šerkšnas ant žemės.'),
  (@b2, 16, 15, 'Ir tai pamatę Izraelio vaikai tarė vienas kitam: „Tai mana“; nes jie nežinojo, kas tai. Ir Mozė jiems tarė: „Tai – duona, kurią VIEŠPATS jums davė valgyti.'),
  (@b2, 16, 16, 'Štai ką VIEŠPATS įsakė: ‘Prisirinkite jos kiek kiekvienas galite suvalgyti, po omerą kiekvienam žmogui, pagal savo asmenų skaičių; kiekvienas paimkite esantiems savo palapinėje’“.'),
  (@b2, 16, 17, 'Ir Izraelio vaikai taip padarė, ir prisirinko kai kurie daugiau, kai kurie mažiau.'),
  (@b2, 16, 18, 'Bet kai jie seikėjo tai omeru, kas daug prisirinko, neturėjo per daug, o kas mažai prisirinko, neturėjo stokos; jie kiekvienas prisirinko, kiek galėjo suvalgyti.'),
  (@b2, 16, 19, 'Ir Mozė tarė: „Nei vienas tenepalieka nieko iš to ligi ryto“.'),
  (@b2, 16, 20, 'Tačiau jie neklausė Mozės; bet kai kurie iš jų paliko to ligi ryto, ir tai sukirmijo ir pasmirdo; ir Mozė užsirūstino ant jų.'),
  (@b2, 16, 21, 'Ir jie tai rinkosi kiekvieną rytą, kiekvienas, kiek galėjo suvalgyti; o saulei įkaitus, tai sutirpo.'),
  (@b2, 16, 22, 'Ir įvyko, kad šeštąją dieną jie prisirinko dvigubai daugiau duonos: po du omerus kiekvienam; ir visi susirinkimo valdovai atėjo ir pranešė Mozei.'),
  (@b2, 16, 23, 'Ir jis jiems tarė: „Štai ką VIEŠPATS sakė: ‘Rytoj yra šventojo sabato poilsis VIEŠPAČIUI; kepkite, ką norite kepti šiandien, ir virkite, ką norite virti; o tai, kas atlieka, atsidėkite, kad palaikytumėte iki ryto’“.'),
  (@b2, 16, 24, 'Ir jie atsidėjo tai iki ryto, kaip Mozė įsakė; ir tai nepasmirdo nei nebuvo tame jokio kirmino.'),
  (@b2, 16, 25, 'Ir Mozė tarė: „Valgykite tai šiandien; nes šiandien yra sabatas VIEŠPAČIUI; šiandien to nerasite lauke.'),
  (@b2, 16, 26, 'Šešias dienas tai rinkite; bet septintąją dieną, kuri yra sabatas, joje nieko nebus“.'),
  (@b2, 16, 27, 'Ir įvyko, kad septintąją dieną kai kurie iš tautos išėjo rinkti, ir jie nieko nerado.'),
  (@b2, 16, 28, 'Ir VIEŠPATS tarė Mozei: „Kaip ilgai atsisakinėsite laikytis mano įsakymų ir mano įstatymų?'),
  (@b2, 16, 29, 'Štai kadangi VIEŠPATS jums davė sabatą, todėl šeštąją dieną jis duoda jums dviejų dienų duonos; kiekvienas pasilikite savo vietoje, nei vienas teneišeina iš savo vietos septintąją dieną“.'),
  (@b2, 16, 30, 'Taip tauta ilsėjosi septintąją dieną.'),
  (@b2, 16, 31, 'Ir Izraelio namai tai praminė vardu Mana; o ji buvo kaip kalendros sėkla, balta; o jos skonis buvo kaip papločių, pagamintų su medumi.'),
  (@b2, 16, 32, 'Ir Mozė tarė: „Štai ką VIEŠPATS įsako: ‘Pripilkite omerą jos, kad būtų išlaikyta jūsų kartoms; kad jos matytų duoną, kuria jus maitinau dykumoje, kai išvedžiau jus iš Egipto šalies“.'),
  (@b2, 16, 33, 'Ir Mozė tarė Aaronui: „Paimk puodą, įpilk į jį pilną omerą manos ir jį atidėk VIEŠPATIES akivaizdoje, kad būtų išlaikytas jūsų kartoms“.'),
  (@b2, 16, 34, 'Kaip VIEŠPATS įsakė Mozei, taip Aaronas jį atidėjo prieš Liudijimą, kad būtų saugojamas.'),
  (@b2, 16, 35, 'Ir Izraelio vaikai valgė maną keturiasdešimt metų, kol atėjo į apgyvendintą šalį; jie valgė maną, kol atėjo prie Kanaano šalies ribų.'),
  (@b2, 16, 36, 'Na, o omeras yra dešimtoji efos dalis.'),
  (@b2, 17, 1, 'Ir visas Izraelio vaikų susirinkimas keliavo iš Sino dykumos pagal savo keliavimus VIEŠPATIES įsakymu ir stovyklavo Refidime; o ten nebuvo tautai vandens atsigerti.'),
  (@b2, 17, 2, 'Todėl tauta barėsi su Moze ir tarė: „Duok mums vandens, kad gertume“. O Mozė jiems tarė: „Ko baratės su manimi? Kodėl gundote VIEŠPATĮ?“'),
  (@b2, 17, 3, 'O tauta ten troško vandens; ir tauta murmėjo prieš Mozę ir tarė: „Kodėl atvedei mus aukštyn iš Egipto, kad numarintum troškuliu mus, mūsų vaikus ir mūsų galvijus?“'),
  (@b2, 17, 4, 'Ir Mozė šaukėsi VIEŠPATIES, sakydamas: „Ką man daryti šitai tautai? Jie beveik pasiruošę užmėtyti mane akmenimis“.'),
  (@b2, 17, 5, 'Ir VIEŠPATS tarė Mozei: „Eik tautos priešakin ir imk su savimi iš Izraelio vyresniųjų; ir imk į ranką savo lazdą, kuria sudavei į upę, ir eik.'),
  (@b2, 17, 6, 'Štai aš ten stovėsiu priešais tave ant uolos, Horebe; ir tu suduosi į uolą, ir iš jos ištekės vanduo, kad tauta galėtų gerti“. Ir Mozė taip padarė Izraelio vyresniųjų akyse.'),
  (@b2, 17, 7, 'Ir jis praminė tą vietą vardu Masa ir Meriba, kadangi Izraelio vaikai barėsi ir kadangi jie gundė VIEŠPATĮ, sakydami: „Ar VIEŠPATS yra tarp mūsų, ar ne?“'),
  (@b2, 17, 8, 'Tada atėjo Amalekas ir kariavo su Izraeliu Refidime.'),
  (@b2, 17, 9, 'Ir Mozė tarė Jozuei: „Išrink mums vyrų ir išėjęs kariauk su Amaleku; rytoj aš stovėsiu ant kalvos viršūnės su Dievo lazda savo rankoje“.'),
  (@b2, 17, 10, 'Taigi Jozuė padarė taip, kaip Mozė buvo jam sakęs, ir kariavo su Amaleku; o Mozė, Aaronas ir Hūras užlipo į kalvos viršūnę.'),
  (@b2, 17, 11, 'Ir įvyko, kad kai Mozė laikė pakėlęs savo ranką, Izraelis imdavo viršų; o kai jis nuleisdavo savo ranką, Amalekas imdavo viršų.'),
  (@b2, 17, 12, 'Bet Mozės rankos apsunko; ir jie paėmė akmenį ir jį padėjo po juo, ir jis atsisėdo ant jo; o Aaronas ir Hūras parėmė jo rankas, vienas iš vienos pusės, kitas iš kitos pusės; ir jo rankos buvo tvirtos iki saulės nusileidimo.'),
  (@b2, 17, 13, 'Ir Jozuė nugalėjo Amaleką ir jo tautą kalavijo ašmenimis.'),
  (@b2, 17, 14, 'Ir VIEŠPATS tarė Mozei: „Įrašyk tai į knygą atminimui ir pakartok tai Jozuei į ausis; nes aš visiškai išdildysiu Amaleko atminimą iš po dangaus“.'),
  (@b2, 17, 15, 'Ir Mozė pastatė aukurą ir jį pavadino vardu „Jehova-Nisi“;'),
  (@b2, 17, 16, 'nes jis tarė: „Kadangi VIEŠPATS prisiekė, kad VIEŠPATS kariaus su Amaleku iš kartos į kartą“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b2, 18, 1, 'Kai Jetras, Midjano kunigas, Mozės uošvis, išgirdo visa, ką Dievas buvo padaręs Mozei ir savo tautai Izraeliui, kad VIEŠPATS buvo išvedęs Izraelį iš Egipto;'),
  (@b2, 18, 2, 'tada Jetras, Mozės uošvis, ėmė Siporą, Mozės žmoną, po to, kai jis buvo ją pasiuntęs atgal,'),
  (@b2, 18, 3, 'ir jos abu sūnus; kurių vieno vardas buvo Geršomas; nes jis sakė: „Buvau ateivis svetimoje šalyje“;'),
  (@b2, 18, 4, 'o kito vardas buvo Eliezeras; jis sakė: „Nes mano tėvo Dievas buvo mano pagalba ir mane išgelbėjo nuo faraono kalavijo“;'),
  (@b2, 18, 5, 'ir Jetras, Mozės uošvis, atėjo su jo sūnumis ir jo žmona pas Mozę į dykumą, kur jis stovyklavo prie Dievo kalno;'),
  (@b2, 18, 6, 'ir jis tarė Mozei: „Aš, tavo uošvis Jetras, esu atėjęs pas tave, ir tavo žmona ir jos abu sūnūs su ja“.'),
  (@b2, 18, 7, 'Mozė išėjo pasitikti savo uošvio, nusilenkė ir pabučiavo jį; ir jie vienas kito klausinėjo apie gerovę; ir jie įėjo į palapinę.'),
  (@b2, 18, 8, 'Ir Mozė papasakojo savo uošviui visa, ką VIEŠPATS buvo padaręs faraonui ir egiptiečiams dėl Izraelio, visą vargą, ištikusį juos kelyje, ir kaip VIEŠPATS juos išgelbėjo.'),
  (@b2, 18, 9, 'Ir Jetras džiaugėsi dėl viso gerumo, kurį VIEŠPATS buvo padaręs Izraeliui, kurį jis išgelbėjo iš egiptiečių rankos.'),
  (@b2, 18, 10, 'Ir Jetras tarė: „Tebūna palaimintas VIEŠPATS, kuris jus išgelbėjo iš egiptiečių rankos ir faraono rankos, kuris išgelbėjo tautą iš po egiptiečių rankos.'),
  (@b2, 18, 11, 'Dabar žinau, kad VIEŠPATS yra didesnis už visus dievus; nes tame dalyke, kame jie elgėsi išdidžiai, jis buvo aukščiau jų“.'),
  (@b2, 18, 12, 'Ir Jetras, Mozės uošvis, paėmė deginamąją atnašą ir aukų Dievui; ir atėjo Aaronas ir visi Izraelio vyresnieji valgyti duonos su Mozės uošviu Dievo akivaizdoje.'),
  (@b2, 18, 13, 'Ir įvyko rytojaus dieną, kad Mozė sėdosi teisti tautos; o tauta stovėjo prie Mozės nuo ryto iki vakaro.'),
  (@b2, 18, 14, 'Ir Mozės uošvis, pamatęs visa, ką jis darė tautai, tarė: „Kas tai, ką tu darai tautai? Kodėl tu sėdi pats vienas, o visa tauta stovi prie tavęs nuo ryto iki vakaro?“'),
  (@b2, 18, 15, 'Ir Mozė tarė savo uošviui: „Dėl to, kad tauta ateina pas mane Dievo pasiklausti;'),
  (@b2, 18, 16, 'kai jie turi kokį reikalą, jie ateina pas mane; o aš teisiu tarp vieno ir kito, ir duodu jiems žinoti Dievo įstatus ir jo įstatymus“.'),
  (@b2, 18, 17, 'Ir Mozės uošvis jam tarė: „Tai, ką tu darai, nėra gerai.'),
  (@b2, 18, 18, 'Tu visiškai nusikamuosi, tiek tu, tiek ši tauta, kuri yra su tavimi; nes tau tai per sunku; tu nepajėgus pats vienas to atlikti.'),
  (@b2, 18, 19, 'Dabar paklausyk mano balso, aš tau patarsiu, o Dievas bus su tavimi: tu būk tautai į Dievą, kad pristatytumei reikalus Dievui;'),
  (@b2, 18, 20, 'ir mokyk juos įsakų bei įstatymų, ir parodyk jiems kelią, kuriuo jie turi eiti, ir darbą, kurį jie turi daryti.'),
  (@b2, 18, 21, 'Be to, parūpink iš visos tautos pajėgių vyrų, Dievo bijančių, tiesos vyrų, godumo nekenčiančių; ir pastatyk tokius aukščiau jų būti tūkstančių valdovais, šimtų valdovais, penkiasdešimčių valdovais ir dešimčių valdovais;'),
  (@b2, 18, 22, 'ir tegul jie teisia tautą visais laikotarpiais; ir bus, kad kiekvieną didelį reikalą jie tau pristatys, bet kiekvieną mažą reikalą jie teis; taip bus lengviau tau pačiam, ir jie neš naštą su tavimi.'),
  (@b2, 18, 23, 'Jei darysi šitą dalyką ir tau Dievas taip įsakys, tuomet tu pajėgsi ištverti, ir taip pat visa ši tauta eis į savo vietą ramybėje“.'),
  (@b2, 18, 24, 'Taigi Mozė paklausė savo uošvio balso ir padarė visa, ką jis buvo sakęs.'),
  (@b2, 18, 25, 'Ir Mozė išrinko pajėgių vyrų iš viso Izraelio ir juos padarė tautos galvomis: tūkstančių valdovais, šimtų valdovais, penkiasdešimčių valdovais ir dešimčių valdovais.'),
  (@b2, 18, 26, 'Ir jie teisė tautą visais laikotarpiais; sunkius reikalus jie pristatydavo Mozei, bet kiekvieną mažą reikalą jie patys teisdavo.'),
  (@b2, 18, 27, 'Ir Mozė išleido savo uošvį; o jis nuėjo sau į savo paties šalį.'),
  (@b2, 19, 1, 'Trečiąjį mėnesį, kai Izraelio vaikai buvo išėję iš Egipto šalies, tą pačią dieną jie atvyko į Sinajaus dykumą.'),
  (@b2, 19, 2, 'Nes jie buvo išėję iš Refidimo, ir buvo atvykę į Sinajaus dykumą, ir stovyklavo dykumoje; ir Izraelis stovyklavo ten priešais kalną.'),
  (@b2, 19, 3, 'Ir Mozė ėjo aukštyn pas Dievą, ir VIEŠPATS jam šaukė nuo kalno, sakydamas: „Taip sakyk Jokūbo namams ir pranešk Izraelio vaikams:'),
  (@b2, 19, 4, '‘Jūs matėte, ką aš padariau egiptiečiams ir kaip nešiau jus ant erelio sparnų, ir atgabenau jus pas save.'),
  (@b2, 19, 5, 'Taigi dabar, jei tikrai paklusite mano balsui ir laikysitės mano sandoros, tuomet man būsite ypatinga brangenybė viršum visų tautų; nes visa žemė yra mano.'),
  (@b2, 19, 6, 'Ir man būsite kunigų karalystė ir šventa tauta’. Šitie yra žodžiai, kuriuos kalbėk Izraelio vaikams“.'),
  (@b2, 19, 7, 'Ir atėjęs Mozė pasišaukė tautos vyresniuosius ir prieš jų veidus išdėstė visus šituos žodžius, kuriuos VIEŠPATS jam įsakė.'),
  (@b2, 19, 8, 'Ir visa tauta, kartu atsakydama, tarė: „Visa, ką VIEŠPATS kalbėjo, mes darysime“. Ir Mozė perdavė tautos žodžius VIEŠPAČIUI.'),
  (@b2, 19, 9, 'Ir VIEŠPATS tarė Mozei: „Štai aš ateinu pas tave tirštame debesyje, kad tauta girdėtų, kai aš kalbėsiu su tavimi, ir amžinai tavimi tikėtų“. Ir Mozė pranešė tautos žodžius VIEŠPAČIUI.'),
  (@b2, 19, 10, 'Ir VIEŠPATS tarė Mozei: „Eik pas tautą ir pašvęsk juos šiandien ir rytoj, ir teišsiplauna jie savo drabužius,'),
  (@b2, 19, 11, 'ir tebūna pasiruošę trečiajai dienai; nes trečią dieną VIEŠPATS nusileis ant Sinajaus kalno visos tautos akyse.'),
  (@b2, 19, 12, 'Ir tu nustatysi aplinkui ribas tautai, tardamas: ‘Saugokitės, nelipkite į kalną ir nepalieskite jo krašto; kiekvienas, kuris palies kalną, tikrai bus užmuštas;'),
  (@b2, 19, 13, 'jokia ranka jo tenepaliečia, bet jis tikrai bus užmėtytas akmenimis ar peršautas; ar tai būtų gyvulys, ar žmogus, jis negyvens’; kai ilgai skambės trimitas, jie lips į kalną“.'),
  (@b2, 19, 14, 'Ir Mozė nulipo nuo kalno pas tautą ir pašventė tautą; ir jie išsiplovė savo drabužius.'),
  (@b2, 19, 15, 'Ir jis tarė tautai: „Būkite pasiruošę trečiajai dienai; neikite pas savo žmonas“.'),
  (@b2, 19, 16, 'Ir įvyko trečiąją dieną ryte, kad buvo griaustiniai ir žaibai, tirštas debesis ant kalno ir nepaprastai stiprus trimito garsas; taip, kad drebėjo visa tauta, esanti stovykloje.'),
  (@b2, 19, 17, 'Ir Mozė išvedė tautą iš stovyklos susitikti su Dievu; ir jie sustojo kalno papėdėje.'),
  (@b2, 19, 18, 'O Sinajaus kalnas visas rūko, nes VIEŠPATS ant jo nusileido ugnyje; ir jo dūmai kilo kaip krosnies dūmai, ir visas kalnas smarkiai drebėjo.'),
  (@b2, 19, 19, 'O kai trimito garsas ilgai skambėjo ir darėsi vis garsesnis ir garsesnis, Mozė kalbėjo, o Dievas jam atsakė balsu.'),
  (@b2, 19, 20, 'Ir VIEŠPATS nusileido ant Sinajaus kalno, ant kalno viršūnės; ir VIEŠPATS pasišaukė Mozę į kalno viršūnę; ir Mozė užlipo.'),
  (@b2, 19, 21, 'Ir VIEŠPATS tarė Mozei: „Eik žemyn, įpareigok tautą, kad jie nesiveržtų link VIEŠPATIES spoksoti ir daugelis iš jų nežūtų.'),
  (@b2, 19, 22, 'Ir kunigai taip pat, kurie artinasi prie VIEŠPATIES, tepasišvenčia, kad VIEŠPATS neišsiveržtų prieš juos“.'),
  (@b2, 19, 23, 'Ir Mozė tarė VIEŠPAČIUI: „Tauta negali lipti į Sinajaus kalną; nes tu mus įpareigojai, tardamas: ‘Nustatyk aplink kalną ribas ir pašvęsk jį’“.'),
  (@b2, 19, 24, 'Ir VIEŠPATS jam tarė: „Eik, nulipk ir užlipk tu ir Aaronas su tavimi; bet kunigai ir tauta tenesiveržia lipti pas VIEŠPATĮ, kad jis neišsiveržtų prieš juos“.'),
  (@b2, 19, 25, 'Taigi Mozė nulipo pas tautą ir jiems kalbėjo.'),
  (@b2, 20, 1, 'Ir Dievas kalbėjo visus tuos žodžius, sakydamas:'),
  (@b2, 20, 2, '„Aš esu VIEŠPATS, tavo Dievas, kuris tave išvedžiau iš Egipto šalies, iš vergystės namų.'),
  (@b2, 20, 3, 'Neturėk kitų dievų mano akivaizdoje.'),
  (@b2, 20, 4, 'Nedaryk sau jokio raižyto atvaizdo nei jokio panašumo į tai, kas yra aukštai danguje ar kas žemai žemėje, ar kas vandenyje po žeme;'),
  (@b2, 20, 5, 'nesilenk jiems nei tarnauk jiems; nes aš VIEŠPATS, tavo Dievas, esu pavydus Dievas, lankantis tėvų neteisybes ant vaikų iki trečios ir ketvirtos kartos tų, kurie manęs nekenčia;'),
  (@b2, 20, 6, 'ir rodantis gailestingumą tūkstančiams tų, kurie mane myli ir laikosi mano įsakymų.'),
  (@b2, 20, 7, 'Tuščiai nevartok VIEŠPATIES, savo Dievo, vardo; nes VIEŠPATS nelaikys nekaltu to, kuris tuščiai vartoja jo vardą.'),
  (@b2, 20, 8, 'Atsimink sabato dieną, kad ją laikytum šventa.'),
  (@b2, 20, 9, 'Šešias dienas dirbk ir atlik visą savo darbą;'),
  (@b2, 20, 10, 'bet septintoji diena yra VIEŠPATIES, tavo Dievo sabatas; joje nedirbk jokio darbo nei tu, nei tavo sūnus, nei tavo dukra, nei tavo tarnas, nei tavo tarnaitė, nei tavo galvijai, nei tavo ateivis, esantis tavo vartuose;'),
  (@b2, 20, 11, 'nes per šešias dienas VIEŠPATS padarė dangų ir žemę, jūrą ir visa, kas yra juose, o septintąją dieną ilsėjosi; todėl VIEŠPATS palaimino sabato dieną ir ją pašventė.'),
  (@b2, 20, 12, 'Gerbk savo tėvą ir savo motiną; kad tavo dienos būtų ilgos šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda.'),
  (@b2, 20, 13, 'Nežudyk.'),
  (@b2, 20, 14, 'Nesvetimauk.'),
  (@b2, 20, 15, 'Nevok.'),
  (@b2, 20, 16, 'Neliudyk melagingai prieš savo artimą.'),
  (@b2, 20, 17, 'Negeisk savo artimo namų, negeisk savo artimo žmonos nei jo tarno, nei jo tarnaitės, nei jo jaučio, nei jo asilo, nei nieko, kas yra tavo artimo“.'),
  (@b2, 20, 18, 'Ir visa tauta matė griaustinius, žaibus, trimito garsą ir rūkstantį kalną; ir kai tauta tai pamatė, jie atsitraukė ir stovėjo iš tolo.'),
  (@b2, 20, 19, 'Ir jie tarė Mozei: „Tu kalbėk su mumis, o mes klausysime; bet tenekalba su mumis Dievas, kad nemirtume“.'),
  (@b2, 20, 20, 'O Mozė tarė tautai: „Nebijokite; nes Dievas atėjo jus išmėginti, ir kad jo baimė būtų jūsų akyse, kad nenusidėtumėte“.'),
  (@b2, 20, 21, 'Ir tauta stovėjo iš tolo, o Mozė artinosi prie tirštos tamsos, kur buvo Dievas.'),
  (@b2, 20, 22, 'Ir VIEŠPATS tarė Mozei: „Taip sakyk Izraelio vaikams: ‘Jūs matėte, kad aš kalbėjau su jumis iš dangaus.'),
  (@b2, 20, 23, 'Nedarykite šalia manęs dievų iš sidabro nei nesidarykite dievų iš aukso.'),
  (@b2, 20, 24, 'Padaryk man aukurą iš žemės ir ant jo aukok savo deginamąsias atnašas ir savo taikos atnašas, savo avis ir savo jaučius; visose vietose, kur įamžinsiu savo vardą, aš ateisiu pas tave ir tave palaiminsiu.'),
  (@b2, 20, 25, 'O jei darysi man aukurą iš akmens, nestatyk jo iš tašytų akmenų; nes jei ant jo pakelsi savo įrankį, būsi jį sutepęs.'),
  (@b2, 20, 26, 'Taip pat laiptais nelipk prie mano aukuro, kad prie jo nebūtų atidengtas tavo nuogumas’“.'),
  (@b2, 21, 1, 'Na, o šitie yra teismai, kuriuos tu išstatysi jų priešakyje.'),
  (@b2, 21, 2, 'Jei nusipirksi hebrają tarną, jis tarnaus šešerius metus; o septintaisiais išeis į laisvę už dyką.'),
  (@b2, 21, 3, 'Jei jis atėjo vienas, vienas jis turi išeiti; jei jis buvo vedęs, tada jo žmona išeis su juo.'),
  (@b2, 21, 4, 'Jei jo šeimininkas jam davė žmoną ir ji jam pagimdė sūnų ar dukterų; žmona ir jos vaikai bus jos šeimininko, o jis išeis vienas.'),
  (@b2, 21, 5, 'Bet jei tarnas aiškiai sakys: ‘Aš myliu savo šeimininką, savo žmoną ir savo vaikus; aš neisiu į laisvę’;'),
  (@b2, 21, 6, 'tuomet jo šeimininkas atves jį pas teisėjus; taip pat jis atves jį prie durų ar durų staktos; ir jo šeimininkas yla perdurs jo ausį; ir jis jam tarnaus amžinai.'),
  (@b2, 21, 7, 'O jei kas parduoda savo dukterį būti tarnaite, ji neišeis, kaip išeina tarnai.'),
  (@b2, 21, 8, 'Jei ji nepatinka savo šeimininkui, kuris su ja susižadėjo, tai jis leis jai būti išpirktai; jis neturi valdžios ją parduoti svetimai tautai, kadangi jis apgaulingai su ja pasielgė.'),
  (@b2, 21, 9, 'O jei jis sužadėjo ją su savo sūnumi, jis turi elgtis su ja pagal dukterų teises.'),
  (@b2, 21, 10, 'Jei jis ims sau kitą žmoną; jis tenesumažina jai maisto, rūbų ir santuokinių pareigų.'),
  (@b2, 21, 11, 'O jei jis neatlieka jai šitų trijų, tada ji išeis į laisvę ne už pinigus.'),
  (@b2, 21, 12, 'Kas muša žmogų taip, kad jis miršta, tas tikrai bus užmuštas.'),
  (@b2, 21, 13, 'O jei žmogus netykoja, bet Dievas atiduoda jį į jo rankas; tuomet aš paskirsiu tau vietą, kur jis turės pabėgti.'),
  (@b2, 21, 14, 'Bet jei kas tyčiomis puola ant savo artimo, kad klastingai jį nužudytų; tai paimk jį nuo mano aukuro, kad jis mirtų.'),
  (@b2, 21, 15, 'O kas muša savo tėvą ar savo motiną, tikrai bus užmuštas.'),
  (@b2, 21, 16, 'O kas pavagia žmogų ir jį parduoda, arba jei jis būtų rastas jo rankose, tas tikrai bus užmuštas.'),
  (@b2, 21, 17, 'O kas keikia savo tėvą ar savo motiną, tikrai bus užmuštas.'),
  (@b2, 21, 18, 'Ir jei vyrams susivaidijus, vienas sumuša kitą akmeniu ar kumščiu, o tas nenumiršta, bet neatsikelia iš lovos;'),
  (@b2, 21, 19, 'jei tas atsikelia ir vaikšto su lazda, tuomet jo sumušėjas bus laisvas; jis tik turi sumokėti už to prarastą laiką ir padaryti, kad tas visiškai išgytų.'),
  (@b2, 21, 20, 'O jei kas sumuša savo tarną ar tarnaitę lazda, ir tas numiršta po jo ranka; jis tikrai bus nubaustas.'),
  (@b2, 21, 21, 'Tačiau jei tas pasilieka dieną ar dvi, jis nebus baudžiamas; nes tas yra jo pinigai.'),
  (@b2, 21, 22, 'Jei vyrai susivaidija ir sužeidžia nėščią moterį taip, kad išsimeta jos vaisius, tačiau jokia žala neatsiranda; jis tikrai bus baudžiamas pagal tai, ką jam uždės tos moters vyras; ir jis sumokės kaip teisėjai nuspręs.'),
  (@b2, 21, 23, 'Bet jei atsiranda žala, tuomet atiduosi gyvybę už gyvybę,'),
  (@b2, 21, 24, 'akį už akį, dantį už dantį, ranką už ranką, koją už koją,'),
  (@b2, 21, 25, 'nudeginimą už nudeginimą, žaizdą už žaizdą, kirtį už kirtį.'),
  (@b2, 21, 26, 'O jei kas sumuša savo tarno akį ar tarnaitės akį, kad ta sunyksta, jis už jo akį paleis jį į laisvę.'),
  (@b2, 21, 27, 'O jei jis išmuša savo tarno dantį ar tarnaitės dantį, jis už jo dantį paleis jį į laisvę.'),
  (@b2, 21, 28, 'Jei jautis subado vyrą ar moterį, kad jie miršta; tada tas jautis tikrai bus užmėtytas akmenimis, o jo mėsa nebus valgoma; bet to jaučio savininkas bus laisvas.'),
  (@b2, 21, 29, 'Bet jei jautis praeityje buvo pratęs badytis savo ragais, ir jo savininkui buvo tai paliudyta, o jis nelaikė jo uždaręs, bet jis yra užmušęs vyrą ar moterį, tas jautis bus užmėtytas akmenimis ir taip pat jo savininkas bus užmuštas.'),
  (@b2, 21, 30, 'Jei jam uždėta pinigų suma, tuomet jis turės duoti savo gyvybės išpirkai, kiek tik jam bus uždėta.'),
  (@b2, 21, 31, 'Ar jis yra subadęs sūnų ar subadęs dukrą, jam bus padaryta pagal šį teismą.'),
  (@b2, 21, 32, 'Jei jautis subadys tarną ar tarnaitę, jis duos jų šeimininkui trisdešimt sidabro šekelių, o jautis bus užmėtytas akmenimis.'),
  (@b2, 21, 33, 'O jei kas atidarys duobę, arba jei kas iškas duobę, o jos neuždengs, ir į ją įkris jautis ar asilas;'),
  (@b2, 21, 34, 'tos duobės savininkas už tai atlygins ir duos pinigų jų savininkui; o nudvėsęs gyvulys bus jo.'),
  (@b2, 21, 35, 'O jei kieno jautis sužalos kito jautį, kad tas padvės; tuomet jie parduos gyvąjį jautį ir pasidalins to pinigus; taip pat ir nugaišusį jautį jie pasidalins.'),
  (@b2, 21, 36, 'Arba jei yra žinoma, kad jautis praeityje buvo įpratęs badytis, o jo savininkas nelaikė jo uždaręs; jis tikrai sumokės jaučiu už jautį; o padvėsusysis bus jo paties.'),
  (@b2, 22, 1, 'Jei kas pavogs jautį ar avį ir tą papjaus ar parduos; tas sugrąžins penkis jaučius už jautį ir keturias avis už avį.'),
  (@b2, 22, 2, 'Jei vagis būtų užtiktas besilaužiąs ir būtų sumuštas taip, kad jis miršta, už jį nebus išlietas kraujas.'),
  (@b2, 22, 3, 'Jei ant jo bus patekėjusi saulė, už jį bus išlietas kraujas; nes jis turi pilnai atlyginti; jei jis nieko neturi, tuomet jis bus parduotas už savo vagystę.'),
  (@b2, 22, 4, 'Jei kas pavogta būtų tikrai rasta jo rankose gyva, ar tai būtų jautis, ar asilas, ar avis; jis grąžins dvigubai.'),
  (@b2, 22, 5, 'Jei kas nuganys lauką ar vynuogyną, įleis savo gyvulius ir ganys kito lauke, jis atlygins iš to, kas geriausia jo paties lauke, ir iš to, kas geriausia jo paties vynuogyne.'),
  (@b2, 22, 6, 'Jei išsiveržusi ugnis užgriebia erškėčius taip, kad sudegina javų kupetas ar stovinčius javus, ar lauką, tas, kuris sukėlė gaisrą, tikrai turės atlyginti.'),
  (@b2, 22, 7, 'Jei kas įduos savo artimui saugoti pinigus ar daiktus, o tai būtų pavogta iš to žmogaus namų; jei vagis bus surastas, tesumoka jis dvigubai.'),
  (@b2, 22, 8, 'Jei vagis nebus surastas, tuomet tų namų šeimininkas bus nuvestas pas teisėjus išsiaiškinti, ar jis nėra pridėjęs savo rankos prie savo artimo turto.'),
  (@b2, 22, 9, 'Už visokius nusižengimus, ar tai būtų dėl jaučio, dėl asilo, dėl avies, dėl rūbo ar dėl bet kokio dingusio daikto, apie kurį kitas tvirtina, kad tai jo, abiejų pusių byla turi ateiti teisėjų akivaizdon; ir tas, kurį teisėjai pasmerks, dvigubai sumokės savo artimui.'),
  (@b2, 22, 10, 'Jei kas įduos savo artimui saugoti asilą ar jautį, ar avį, ar bet kokį gyvulį; o tas, niekam to nematant, padvės ar susižalos, ar bus nuvarytas,'),
  (@b2, 22, 11, 'tuomet VIEŠPATIES priesaika tebūna tarp jų abiejų, kad jis nėra pridėjęs savo rankos prie savo artimo turto; ir to savininkas tai priims, ir jis neturės už jį atlyginti.'),
  (@b2, 22, 12, 'O jei tai būtų iš jo pavogta, tas turės atlyginti to savininkui.'),
  (@b2, 22, 13, 'Jei tas būtų sudraskytas į gabalus, tuomet jis tą teatgabena paliudijimui, ir jis neturės atlyginti už tai, kas buvo sudraskyta.'),
  (@b2, 22, 14, 'Jei kas pasiskolins ką iš savo artimo, ir tai būtų sužalota ar padvėstų, to savininkui nesant su juo, jis tikrai atlygins už tai.'),
  (@b2, 22, 15, 'Bet jei to savininkas yra su tuo, jis neturės už tai atlyginti; jei tas buvo išnuomotas, tai išėjo už jo nuomą.'),
  (@b2, 22, 16, 'O jei kas suvilioja panelę, kuri nesužadėta, ir sugula su ja, tas ją tikrai parems kraičiu, kad būtų jo žmona.'),
  (@b2, 22, 17, 'Jei jos tėvas visiškai nesutinka jam jos duoti, jis sumokės pinigus pagal mergelių kraitį.'),
  (@b2, 22, 18, 'Neleisk raganai išlikti gyvai.'),
  (@b2, 22, 19, 'Kas sugula su gyvuliu, tikrai bus užmuštas.'),
  (@b2, 22, 20, 'Kas aukoja kuriam tai dievui, o ne vienam VIEŠPAČIUI, tas bus visiškai sunaikintas.'),
  (@b2, 22, 21, 'Tu nei spausi ateivį, nei jį engsi; nes jūs buvote ateiviai Egipto šalyje.'),
  (@b2, 22, 22, 'Jūs nespausite našlės ar našlaičio.'),
  (@b2, 22, 23, 'Jei juos kaip nors spausi, ir jie kaip nors šauksis manęs, aš tikrai išklausysiu jų šauksmo;'),
  (@b2, 22, 24, 'ir užsidegs mano rūstybė, ir jus išžudysiu kalaviju; ir jūsų žmonos bus našlės, o jūsų vaikai našlaičiai.'),
  (@b2, 22, 25, 'Jei skolinsi pinigų kuriam nors mano tautos beturčiui, esančiam šalia tavęs, nebūk jam kaip palūkininkas nei neapkrauk jo palūkanomis.'),
  (@b2, 22, 26, 'Jei kokiu tai būdu paimsi užstatu savo artimo drabužį, atiduok jam jį iki saulės laidos;'),
  (@b2, 22, 27, 'nes tai yra jo vienintelis dangalas, tai yra jo drabužis jo odai; kame gi jis miegos? Ir įvyks, kai jis šauksis manęs, aš išklausysiu; nes aš esu maloningas.'),
  (@b2, 22, 28, 'Nekeik dievų nei neprakeik savo tautos valdovo.'),
  (@b2, 22, 29, 'Nedelsk atnašauti savo pirmųjų prinokusių vaisių bei savo pirmosios sunkos; pirmagimį iš savo sūnų man atiduok.'),
  (@b2, 22, 30, 'Taip pat daryk su savo jaučiais ir savo avimis: septynias dienas jis bus pas savo motiną; aštuntąją dieną duosi jį man.'),
  (@b2, 22, 31, 'Ir būkite man šventi žmonės; nei nevalgykite jokios mėsos, žvėrių sudraskytos ant lauko; numeskite ją šunims.'),
  (@b2, 23, 1, 'Neskleisk melagingo gando; nepridėk savo rankos su nedorėliu, kad būtum neteisus liudytojas.'),
  (@b2, 23, 2, 'Nesek paskui minią daryti pikta; nei nekalbėk byloje, kad nukryptum paskui daugumą teismo iškreipti,'),
  (@b2, 23, 3, 'ir nepataikauk beturčiui jo byloje.'),
  (@b2, 23, 4, 'Jei sutiksi klaidžiojantį savo priešo jautį ar asilą, tikrai jam parvesk jį.'),
  (@b2, 23, 5, 'Jei pamatysi tavęs nekenčiančiojo asilą, gulintį po savo našta, ir norėsi susilaikyti nuo pagalbos jam, tu tikrai pagelbėk su juo.'),
  (@b2, 23, 6, 'Neiškreipk savo beturčio teismo jo byloje.'),
  (@b2, 23, 7, 'Laikykis toli nuo melagingo dalyko; nežudyk nekalto bei teisaus; nes aš neišteisinsiu nedorėlio.'),
  (@b2, 23, 8, 'Neimk dovanos; nes dovana apakina išmintinguosius ir iškreipia teisiųjų žodžius.'),
  (@b2, 23, 9, 'Taip pat neenk ateivio; nes jūs žinote ateivio širdį, kadangi jūs buvote ateiviai Egipto šalyje.'),
  (@b2, 23, 10, 'Šešerius metus tu sėsi savo žemę ir rinksi jos vaisius;'),
  (@b2, 23, 11, 'bet septintaisiais metais leisi jai pailsėti ir gulėti nejudinamai; kad tavo tautos beturčiai valgytų; o ką jie palieka, suės lauko žvėrys. Tokiu pat būdu pasielgsi su savo vynuogynu ir savo alyvmedžių sodu.'),
  (@b2, 23, 12, 'Šešias dienas dirbk savo darbą, o septintąją dieną ilsėkis; kad pailsėtų tavo jautis ir tavo asilas ir kad atsigaivintų tavo tarnaitės sūnus ir ateivis.'),
  (@b2, 23, 13, 'Ir būkite apdairūs visuose dalykuose, ką jums pasakiau; ir neminėkite kitų dievų vardo, ir tenesigirdi tai iš jūsų burnos.'),
  (@b2, 23, 14, 'Tris kartus metuose švęsk man šventes.'),
  (@b2, 23, 15, 'Švęsk Neraugintos duonos šventę (septynias dienas valgyk neraugintą duoną, kaip tau įsakiau, Abibo mėnesio nustatytu laiku; nes juo išėjai iš Egipto; ir niekas tenepasirodo mano akivaizdoje tuščiomis);'),
  (@b2, 23, 16, 'ir Derliaus šventę, tavo darbų pirmavaisių, kuriuos buvai pasėjęs ant lauko; ir Surinkimo šventę, esančią metų pabaigoje, kai būsi surinkęs nuo lauko savo darbus.'),
  (@b2, 23, 17, 'Tris kartus metuose visi vyriškos lyties tavieji turės pasirodyti Viešpaties DIEVO akivaizdoje.'),
  (@b2, 23, 18, 'Neatnašauk mano aukos kraujo su rauginta duona; ir mano aukos taukai neturi išlikti iki ryto.'),
  (@b2, 23, 19, 'Pirmuosius iš savo šalies pirmavaisių atnešk į VIEŠPATIES, savo Dievo, namus. Nevirk ožiuko jo motinos piene.'),
  (@b2, 23, 20, 'Štai aš siunčiu Angelą pirma tavęs, kad tave saugotų kelyje ir nuvestų tave į vietą, kurią esu paruošęs.'),
  (@b2, 23, 21, 'Saugokis jo ir paklusk jo balsui, nekurstyk jo; nes jis neatleis jūsų nusižengimų; nes jame yra mano vardas.'),
  (@b2, 23, 22, 'Bet jei tikrai paklusi jo balsui ir darysi viską, ką aš kalbu; tada aš būsiu priešas tavo priešams ir priešininkas tavo priešininkams.'),
  (@b2, 23, 23, 'Nes mano Angelas eis pirma tavęs ir tave nuves pas amoritus, hetitus, perizus, kanaaniečius, hivus ir jebusiečius; ir aš juos iškirsiu.'),
  (@b2, 23, 24, 'Nesilenk jų dievams nei jiems tarnauk, nei daryk pagal jų darbus; bet visiškai juos išgriauk ir visiškai sudaužyk jų atvaizdus.'),
  (@b2, 23, 25, 'Ir tarnaukite VIEŠPAČIUI, savo Dievui, ir jis palaimins tavo duoną bei tavo vandenį; ir aš pašalinsiu ligą iš tavo tarpo.'),
  (@b2, 23, 26, 'Nebus persileidžiančios nei nebus nevaisingos tavo šalyje; aš išpildysiu tavo dienų skaičių.'),
  (@b2, 23, 27, 'Aš pasiųsiu savo baimę pirma tavęs ir sunaikinsiu kiekvieną tautą, pas kurią tu ateisi, ir padarysiu, kad visi tavo priešai atsuks tau savo nugaras.'),
  (@b2, 23, 28, 'Ir aš pasiųsiu pirma tavęs širšes, kurios išvarys nuo tavęs hivus, kanaaniečius ir hetitus.'),
  (@b2, 23, 29, 'Aš jų nenuvarysiu nuo tavęs per vienerius metus; kad šalis netaptų tuščia, ir nepadaugėtų lauko žvėrių prieš tave.'),
  (@b2, 23, 30, 'Bet pamažu aš juos nuvarysiu nuo tavęs, kol tu būsi padaugėjęs, ir paveldėsi tą šalį.'),
  (@b2, 23, 31, 'Ir aš nustatysiu tavo ribas nuo Raudonosios jūros iki filistinų jūros ir nuo dykumos iki upės; nes aš atiduosiu į jūsų ranką tos šalies gyventojus; ir tu juos nuvarysi nuo savęs.'),
  (@b2, 23, 32, 'Nesudaryk sandoros su jais nei su jų dievais.'),
  (@b2, 23, 33, 'Jie negyvens tavo šalyje, idant nepadarytų, kad tu prieš mane nusidėtum; nes jei tarnausi jų dievams, tai tikrai bus tau žabangomis“.'),
  (@b2, 24, 1, 'Ir jis tarė Mozei: „Užlipk pas VIEŠPATĮ tu ir Aaronas, Nadabas ir Abihuvas bei septyniasdešimt iš Izraelio vyresniųjų; ir pagarbinkite iš tolo.'),
  (@b2, 24, 2, 'O Mozė tik vienas teprieina prie VIEŠPATIES; bet anie tenepriartėja; nei tauta tenelipa su juo“.'),
  (@b2, 24, 3, 'Ir Mozė atėjęs pranešė tautai visus VIEŠPATIES žodžius ir visus teismus; ir visa tauta atsakė vienu balsu ir tarė: „Visus žodžius, kuriuos VIEŠPATS kalbėjo, mes vykdysime“.'),
  (@b2, 24, 4, 'Ir Mozė užrašė visus VIEŠPATIES žodžius ir ankstų rytą atsikėlęs pastatė aukurą kalvos papėdėje ir dvylika stulpų pagal dvylika Izraelio genčių.'),
  (@b2, 24, 5, 'Ir jis pasiuntė Izraelio vaikų jaunuolius, kurie atnašavo deginamąsias atnašas ir aukojo taikos atnašas iš jaučių VIEŠPAČIUI.'),
  (@b2, 24, 6, 'Ir Mozė paėmė pusę kraujo ir supylė į dubenis; o pusę kraujo šlakstė ant aukuro.'),
  (@b2, 24, 7, 'Ir jis ėmė sandoros knygą ir, tautai klausantis, perskaitė; o jie tarė: „Visa, ką VIEŠPATS kalbėjo, mes darysime ir būsime paklusnūs“.'),
  (@b2, 24, 8, 'Ir Mozė ėmė kraują, apšlakstė juo tautą ir tarė: „Štai kraujas sandoros, kurią VIEŠPATS sudarė su jumis dėl visų šių žodžių“.'),
  (@b2, 24, 9, 'Tada Mozė ir Aaronas, Nadabas ir Abihuvas bei septyniasdešimt iš Izraelio vyresniųjų užlipo;'),
  (@b2, 24, 10, 'ir jie išvydo Izraelio Dievą; ir po jo kojomis buvo tarsi grindinys iš safyro akmens ir tarsi dangaus kūnas savo skaidrumu.'),
  (@b2, 24, 11, 'Ir ant Izraelio vaikų kilmingųjų jis nepridėjo savo rankos; jie taip pat regėjo Dievą ir valgė, ir gėrė.'),
  (@b2, 24, 12, 'Ir VIEŠPATS tarė Mozei: „Užlipk pas mane į kalną ir ten būk; ir aš tau duosiu akmens plokštes, įstatymą ir įsakymus, kuriuos aš užrašiau; kad juos mokytum“.'),
  (@b2, 24, 13, 'Ir pakilo Mozė ir jo tarnautojas Jozuė; ir Mozė įlipo į Dievo kalną.'),
  (@b2, 24, 14, 'Ir jis pasakė vyresniesiems: „Čia palaukite mūsų, kol sugrįšime pas jus; o štai Aaronas ir Hūras yra su jumis; jei kas turi kokį reikalą spręsti, tegul ateina pas juos“.'),
  (@b2, 24, 15, 'Ir Mozė įlipo į kalną, ir debesis apdengė kalną.'),
  (@b2, 24, 16, 'Ir VIEŠPATIES šlovė gyveno ant Sinajaus kalno, ir debesis jį dengė šešias dienas; o septintąją dieną jis pašaukė Mozę iš debesies vidurio.'),
  (@b2, 24, 17, 'Ir VIEŠPATIES šlovės reginys Izraelio vaikų akyse buvo kaip ryjanti ugnis kalno viršūnėje.'),
  (@b2, 24, 18, 'Ir Mozė įėjo į debesies vidurį ir įlipo į kalną; ir Mozė buvo kalne keturiasdešimt dienų ir keturiasdešimt naktų.'),
  (@b2, 25, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 25, 2, '„Kalbėk Izraelio vaikams, kad jie atneštų man atnašą; iš kiekvieno, kuris duoda noriai iš širdies, imkite mano atnašą.'),
  (@b2, 25, 3, 'O ta yra atnaša, kurią imsite iš jų: auksas, sidabras, žalvaris,'),
  (@b2, 25, 4, 'mėlyna, purpurinė, skaisčiai raudona, plona drobė, ožkų šeriai,');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b2, 25, 5, 'raudonai dažytos avinų odos, barsukų odos, šitimo medžiai,'),
  (@b2, 25, 6, 'aliejus apšvietimui, kvapai tepamajam aliejui ir kvapiems smilkalams,'),
  (@b2, 25, 7, 'onikso akmenys ir akmenys įstatymui į efodą ir į krūtinės skydelį.'),
  (@b2, 25, 8, 'Ir jie tepadaro man šventovę; kad gyvenčiau tarp jų.'),
  (@b2, 25, 9, 'Pagal visa tai, ką tau parodysiu, pagal padangtės pavyzdį ir visų jos įrankių pavyzdį, taip ją padarysite.'),
  (@b2, 25, 10, 'Ir jie padarys skrynią iš šitimo medžio; jos ilgis bus dvi su puse uolekties, jos plotis pusantros uolekties, o aukštis pusantros uolekties.'),
  (@b2, 25, 11, 'Ir padenk ją grynu auksu, iš vidaus ir iš išorės ją padenk, ir ant jos aplinkui padaryk aukso vainiką.'),
  (@b2, 25, 12, 'Ir jai nuliek keturis aukso žiedus ir pritaisyk juos keturiuose jos kampuose; du žiedai bus vienoje jos pusėje, o du žiedai kitoje jos pusėje.'),
  (@b2, 25, 13, 'Ir padaryk kartis iš šitimo medžio ir jas padenk auksu.'),
  (@b2, 25, 14, 'Ir įkišk kartis į žiedus prie skrynios šonų, kad jomis nešiotų skrynią.'),
  (@b2, 25, 15, 'Kartys bus skrynios žieduose; jos nebus ištrauktos iš jos.'),
  (@b2, 25, 16, 'Ir įdėk į skrynią liudijimą, kurį tau duosiu.'),
  (@b2, 25, 17, 'Ir padaryk gailestingumo krasę iš gryno aukso; jos ilgis bus dvi su puse uolekties, o jos plotis pusantros uolekties.'),
  (@b2, 25, 18, 'Ir padaryk du kerubus iš aukso, kaltiniu darbu juos padaryk abiejuose gailestingumo krasės galuose.'),
  (@b2, 25, 19, 'Ir padaryk vieną kerubą viename gale, o kitą kerubą kitame gale; iš gailestingumo krasės padarykite kerubus abiejuose jos galuose.'),
  (@b2, 25, 20, 'O kerubai išskės savo sparnus aukštyn, apdengdami savo sparnais gailestingumo krasę, o jų veidai žiūrės vienas į kitą; kerubų veidai bus nukreipti gailestingumo krasės link.'),
  (@b2, 25, 21, 'Ir uždėk gailestingumo krasę ant skrynios iš viršaus; o į skrynią įdėk liudijimą, kurį tau duosiu.'),
  (@b2, 25, 22, 'Ir ten aš su tavimi susitiksiu ir kalbėsiuosi su tavimi nuo gailestingumo krasės viršaus, iš tarpo dviejų kerubų, esančių ant Liudijimo skrynios, apie viską, ką aš tau duosiu įsakymu Izraelio vaikams.'),
  (@b2, 25, 23, 'Taip pat padaryk stalą iš šitimo medžio; jo ilgis bus dvi uolektys, jo plotis – uolektis, o jo aukštis – pusantros uolekties.'),
  (@b2, 25, 24, 'Ir jį padenk grynu auksu ir jam aplinkui padaryk auksinį vainiką.'),
  (@b2, 25, 25, 'Ir padaryk jam aplinkui plaštakos pločio briauną ir padaryk auksinį vainiką jo briaunai aplinkui.'),
  (@b2, 25, 26, 'Ir padaryk jam keturis aukso žiedus ir tuos žiedus pritaisyk prie keturių kampų, esančių ant jo keturių kojų.'),
  (@b2, 25, 27, 'Prie pat briaunos žiedai bus vietos kartims, stalui nešioti.'),
  (@b2, 25, 28, 'O kartis padaryk iš šitimo medžio ir jas padenk auksu, kad jomis nešiotų stalą.'),
  (@b2, 25, 29, 'Ir padaryk jo lėkštes, jo šaukštus, jo dangčius ir jo dubenis, kad jais uždengtų; iš gryno aukso juos padaryk.'),
  (@b2, 25, 30, 'Ir nuolat mano akivaizdoje dėk ant stalo parodomąją duoną.'),
  (@b2, 25, 31, 'Ir padaryk žvakidę iš gryno aukso; žvakidė bus padaryta kaltiniu darbu: jos kotas ir jos šakos, jos taurelės, jos buoželės ir jos gėlės bus iš to paties.'),
  (@b2, 25, 32, 'O iš jos šonų išeis šešios šakos: trys žvakidės šakos iš vieno šono ir trys žvakidės šakos iš kito šono;'),
  (@b2, 25, 33, 'trys taurelės, panašios į migdolus su buožele ir gėle, vienoje šakoje; ir trys taurelės, panašios į migdolus su buožele ir gėle, kitoje šakoje; taip šešiose šakose, išeinančiose iš žvakidės.'),
  (@b2, 25, 34, 'O ant žvakidės bus keturios taurelės, panašios į migdolus su jų buoželėmis ir gėlėmis.'),
  (@b2, 25, 35, 'Ir po dviem šakom bus buoželė iš to paties, ir po dviem šakom buoželė iš to paties, ir po dviem šakom buoželė iš to paties, pagal šešias šakas, išeinančias iš žvakidės.'),
  (@b2, 25, 36, 'Jų buoželės ir jų šakos bus iš to paties: ji visa bus vienas kaltinis darbas iš gryno aukso.'),
  (@b2, 25, 37, 'Ir padaryk septynis jos žibintus; ir jie uždegs jos žibintus, kad jie šviestų jos priešakį.'),
  (@b2, 25, 38, 'Ir jos gnybtuvai ir jos indeliai nuognaiboms bus gryno aukso.'),
  (@b2, 25, 39, 'Iš vieno gryno aukso talento jis tai padarys su visais šitais indais.'),
  (@b2, 25, 40, 'Ir žiūrėk, kad juos padarytum pagal jų pavyzdį, kuris tau buvo parodytas kalne.'),
  (@b2, 26, 1, 'Dar padaryk padangtę iš dešimties uždangalų plono sukto lino, mėlyno, purpurinio ir skaisčiai raudono; juos padaryk su sumanaus darbo kerubais.'),
  (@b2, 26, 2, 'Vieno uždangalo ilgis bus dvidešimt aštuonios uolektys, o plotis vieno uždangalo – keturios uolektys; ir visi uždangalai turės vieną matą.'),
  (@b2, 26, 3, 'Penki uždangalai bus sujungti vienas su kitu; ir kiti penki uždangalai bus sujungti vienas su kitu.'),
  (@b2, 26, 4, 'Ir padaryk kilpas iš mėlyno ant vieno uždangalo krašto, ant paties galo, sujungime; ir panašiai padaryk prie tolimiausio krašto kito uždangalo, antrojo sujungime.'),
  (@b2, 26, 5, 'Penkiasdešimt kilpų padaryk viename uždangale ir penkiasdešimt kilpų padaryk krašte uždangalo, esančio antrojo sujungime; kad kilpos laikytųsi viena kitos.'),
  (@b2, 26, 6, 'Ir padaryk penkiasdešimt aukso kabių ir kabėmis sujunk uždangalus kartu; ir bus viena padangtė.'),
  (@b2, 26, 7, 'Ir padaryk uždangalus iš ožkos šerių, kad būtų apdengimas ant padangtės; padaryk vienuolika uždangalų.'),
  (@b2, 26, 8, 'Vieno uždangalo ilgis bus trisdešimt uolekčių, o vieno uždangalo plotis – keturios uolektys; ir vienuolika uždangalų bus vieno mato.'),
  (@b2, 26, 9, 'Ir sujunk penkis uždangalus atskirai ir šešis uždangalus atskirai, o šeštąjį uždangalą sulenk dvilinką ant padangtės priekio.'),
  (@b2, 26, 10, 'Ir padaryk penkiasdešimt kilpų prie krašto vieno uždangalo, prie paties krašto, sujungime, ir penkiasdešimt kilpų prie krašto to uždangalo, kuris sujungia antrąjį.'),
  (@b2, 26, 11, 'Ir padaryk penkiasdešimt žalvarinių kabių, įdėk kabes į kilpas ir sujunk palapinę, kad ji būtų viena.'),
  (@b2, 26, 12, 'O palapinės uždangalų atliekamą likutį, pusę atliekamo uždangalo, pakabink ant padangtės nugarinės pusės.'),
  (@b2, 26, 13, 'Ir uolektis vienoje pusėje ir uolektis kitoje pusėje iš to, kas atlieka nuo palapinės uždangalų ilgio, kabės vienoje ir kitoje pusėje ant padangtės šonų, kad ją apdengtų.'),
  (@b2, 26, 14, 'Ir padaryk palapinei apdengimą iš raudonai dažytų avinų odų, o apdengimą viršuje iš barsukų odų.'),
  (@b2, 26, 15, 'Ir padaryk padangtei stovinčias lentas iš šitimo medžio.'),
  (@b2, 26, 16, 'Vienos lentos ilgis bus dešimt uolekčių, o lentos plotis bus pusantros uolekties.'),
  (@b2, 26, 17, 'Vienoje lentoje bus du dygiai, lygiagrečiai įtaisyti vienas prieš kitą; taip padaryk visoms padangtės lentoms.'),
  (@b2, 26, 18, 'Ir padaryk padangtei lentas: dvidešimt lentų pietiniame šone pietų link.'),
  (@b2, 26, 19, 'Ir padaryk keturiasdešimt sidabrinių movų po dvidešimtimi lentų; dvi movas po viena lenta, jos abiem dygiam, ir dvi movas po kita lenta, jos abiem dygiam.'),
  (@b2, 26, 20, 'O antrajam padangtės šonui, šiauriniame šone bus dvidešimt lentų'),
  (@b2, 26, 21, 'ir jų keturiasdešimt sidabrinių movų; dvi movos po viena lenta ir dvi movos po kita lenta.'),
  (@b2, 26, 22, 'O padangtės šonams vakarų link padaryk šešias lentas.'),
  (@b2, 26, 23, 'Ir padaryk dvi lentas padangtės kertėms abiejuose šonuose.'),
  (@b2, 26, 24, 'Ir jos bus sujungtos apačioje, ir jos bus sujungtos viršuje, pačiame gale, vienu žiedu; taip bus joms abiems; jos bus dviems kertėms.'),
  (@b2, 26, 25, 'Ir jos bus aštuonios lentos, ir jų movos iš sidabro – šešiolika movų; dvi movos po viena lenta ir dvi movos po kita lenta.'),
  (@b2, 26, 26, 'Ir padaryk skersinius iš šitimo medžio: penkis vieno padangtės šono lentoms,'),
  (@b2, 26, 27, 'penkis skersinius kito padangtės šono lentoms ir penkis skersinius padangtės šono lentoms – dviems šonams vakaruose.'),
  (@b2, 26, 28, 'O vidurinis skersinis lentų viduryje sieks nuo vieno galo iki kito.'),
  (@b2, 26, 29, 'O lentas padenk auksu ir padaryk jų žiedus iš aukso kaip vietas skersiniams; ir padenk skersinius auksu.'),
  (@b2, 26, 30, 'Ir pastatyk padangtę pagal tą jos pavyzdį, kuris tau buvo parodytas kalne.'),
  (@b2, 26, 31, 'Ir padaryk uždangą iš mėlyno, purpurinio, skaisčiai raudono ir plono sumanaus darbo susukto lino; ji bus padaryta su kerubais;'),
  (@b2, 26, 32, 'ir pakabink ją ant keturių šitimo medžio stulpų, padengtų auksu; jų kabliai bus iš aukso, ant keturių sidabro movų.'),
  (@b2, 26, 33, 'Ir uždangą pakabink po kabėmis, kad ten vidun už uždangos įneštum Liudijimo skrynią; ir uždanga atskirs jums tarp šventosios vietos ir švenčiausiosios.'),
  (@b2, 26, 34, 'Ir uždėk gailestingumo krasę ant Liudijimo skrynios švenčiausioje vietoje.'),
  (@b2, 26, 35, 'Ir pastatyk stalą uždangos išorėje bei žvakidę priešais stalą, padangtės šone pietų link; o stalą padėk šiauriniame šone.'),
  (@b2, 26, 36, 'Ir padaryk užuolaidą palapinės durims iš mėlyno, purpurinio, skaisčiai raudono ir plono susukto lino, siuvinėto darbo.'),
  (@b2, 26, 37, 'O užuolaidai padaryk penkis šitimo medžio stulpus ir juos padenk auksu, ir jų kabliai bus iš aukso; ir nuliek jiems penkias žalvarines movas.'),
  (@b2, 27, 1, 'Ir padaryk aukurą iš šitimo medžio, penkių uolekčių ilgio ir penkių uolekčių pločio; tas aukuras bus kvadratinis; o jo aukštis bus trys uolektys.'),
  (@b2, 27, 2, 'Ir padaryk jo ragus ant keturių jo kampų; jo ragai bus iš to paties; ir padenk jį žalvariu.'),
  (@b2, 27, 3, 'Ir padaryk jo puodus jo pelenams supilti, jo semtuvus, jo dubenis, jo šakutes mėsai ir jo indus žarijoms; visus jo įrankius padaryk iš žalvario.'),
  (@b2, 27, 4, 'Ir jam padaryk tinklines groteles iš žalvario; ir padaryk ant tinklo keturis žalvarinius žiedus keturiuose jo kampuose.'),
  (@b2, 27, 5, 'Ir jį padėk po aukuro ribomis apačioje, kad tinklas būtų iki aukuro vidurio.'),
  (@b2, 27, 6, 'Ir padaryk aukurui kartis, kartis iš šitimo medžio, ir jas padenk žalvariu.'),
  (@b2, 27, 7, 'O kartys bus įkištos į žiedus, ir kartys bus abiejuose aukuro šonuose, jam nešti.'),
  (@b2, 27, 8, 'Padaryk jį tuščiavidurį iš lentų; kaip tau buvo parodyta kalne, taip jie jį padarys.'),
  (@b2, 27, 9, 'Ir padaryk padangtės kiemą; pietinei pusei pietų link bus kiemui užuolaidos iš plono susukto lino, šimto uolekčių ilgio vienam šonui;'),
  (@b2, 27, 10, 'ir dvidešimt jo stulpų ir jų dvidešimt movų bus iš žalvario; stulpų kabliai ir jų apvadai bus iš sidabro.'),
  (@b2, 27, 11, 'Taip pat šiaurinei pusei palei ilgį bus užuolaidos šimto uolekčių ilgio ir jo dvidešimt stulpų, ir jų dvidešimt movų iš žalvario; stulpų kabliai ir jų apvadai iš sidabro.'),
  (@b2, 27, 12, 'O kiemo pločiui vakarinėje pusėje bus penkiasdešimties uolekčių užuolaidos; jų dešimt stulpų ir tų dešimt movų.'),
  (@b2, 27, 13, 'O kiemo plotis rytinėje pusėje rytų link bus penkiasdešimt uolekčių.'),
  (@b2, 27, 14, 'Vienos pusės vartų užuolaidos bus penkiolikos uolekčių; trys jų stulpai ir tų trys movos.'),
  (@b2, 27, 15, 'O antroje pusėje bus penkiolika uolekčių užuolaidų; trys jų stulpai ir tų trys movos.'),
  (@b2, 27, 16, 'Ir kiemo vartams bus dvidešimties uolekčių užuolaida iš mėlyno, purpurinio, skaisčiai raudono ir plono susukto lino, siuvinėto darbo; o jų stulpų bus keturi, ir keturios tų movos.'),
  (@b2, 27, 17, 'Visi stulpai aplinkui kiemą bus apsupti sidabro apvadais; jų kabliai bus iš sidabro, o jų movos iš žalvario.'),
  (@b2, 27, 18, 'Kiemo ilgis bus šimtas uolekčių, plotis visur – penkiasdešimt, ir aukštis – penkios uolektys iš plono susukto lino, o jų movos iš žalvario.'),
  (@b2, 27, 19, 'Visi padangtės įrankiai visame jos tarnavime, visi jos kuolai ir visi kiemo kuolai bus iš žalvario.'),
  (@b2, 27, 20, 'Ir įsakyk Izraelio vaikams, kad jie tau atneštų gryno išgrūstų alyvų aliejaus apšvietimui, padaryti, kad žibintas nuolat degtų.'),
  (@b2, 27, 21, 'Susirinkimo padangtėje, išorėje uždangos, esančios prieš liudijimą, Aaronas ir jo sūnūs jį tvarkys nuo vakaro iki ryto VIEŠPATIES akivaizdoje; tai bus jų kartoms amžinas įstatas dėl Izraelio vaikų.'),
  (@b2, 28, 1, 'Ir pasiimk iš Izraelio vaikų tarpo savo brolį Aaroną ir jo sūnus su juo, kad jis man tarnautų kunigo tarnyboje: Aaroną, Nadabą ir Abihuvą, Eleazarą ir Itamarą, Aarono sūnus.'),
  (@b2, 28, 2, 'Ir padaryk savo broliui Aaronui šventus drabužius šlovei ir grožiui.'),
  (@b2, 28, 3, 'Ir kalbėk visiems, esantiems išmintingos širdies, kuriuos esu pripildęs išminties dvasia, kad jie padarytų Aarono drabužius jo įšventinimui, kad jis man tarnautų kunigo tarnyboje.'),
  (@b2, 28, 4, 'O šitie yra drabužiai, kuriuos jie padarys: krūtinės skydelis, efodas, apsiaustas, išsiuvinėtas apdaras, mitra ir juosta; ir jie padarys šventus drabužius tavo broliui Aaronui ir jo sūnums, kad jis man tarnautų kunigo tarnyboje.'),
  (@b2, 28, 5, 'Ir jie paims aukso, mėlyno, purpurinio, skaisčiai raudono ir plono lino.'),
  (@b2, 28, 6, 'Ir jie padarys efodą iš aukso, mėlyno, purpurinio, skaisčiai raudono ir susukto plono lino, sumaniu darbu.'),
  (@b2, 28, 7, 'Jis turės dvi jo perpetes, sujungtas savo abiejuose kraštuose; ir taip jis bus sujungtas.'),
  (@b2, 28, 8, 'O daili efodo juosta, esanti ant jo, bus iš to paties, pagal jo padarymą: iš aukso, mėlyno, purpurinio, skaisčiai raudono ir plono susukto lino.'),
  (@b2, 28, 9, 'Ir paimk du onikso akmenis ir išraižyk ant jų Izraelio vaikų vardus:'),
  (@b2, 28, 10, 'šešis jų vardus ant vieno akmens ir kitus šešis likusiųjų vardus ant kito akmens, pagal jų gimimą.'),
  (@b2, 28, 11, 'Akmens raižytojo darbu, kaip antspaudo graviūras, išraižyk abu akmenis Izraelio vaikų vardais; padaryk, kad jie būtų įstatyti į aukso lizdus.'),
  (@b2, 28, 12, 'Ir abu akmenis uždėk ant efodo pečių kaip atminimo akmenis Izraelio vaikams; o Aaronas nešios jų vardus VIEŠPATIES akivaizdoje ant abiejų savo pečių atminimui.'),
  (@b2, 28, 13, 'Ir padaryk aukso lizdus;'),
  (@b2, 28, 14, 'ir dvi grandinėles iš gryno aukso, galuose; jas padaryk pinto darbo ir pritvirtink pintas grandinėles prie lizdų.'),
  (@b2, 28, 15, 'Ir sumaniu darbu padaryk teismo krūtinės skydelį; padaryk jį pagal efodo padarymą: iš aukso, mėlyno, purpurinio, skaisčiai raudono ir iš plono susukto lino jį padaryk.'),
  (@b2, 28, 16, 'Jis bus kvadratinis, dvilinkas; jo ilgis bus sprindis, ir jo plotis bus sprindis.'),
  (@b2, 28, 17, 'Ir įstatyk į jį akmenų įtvarus – keturias akmenų eiles; pirmoji eilė bus sardis, topazas ir raudonasis granatas; šita bus pirmoji eilė.'),
  (@b2, 28, 18, 'O antroji eilė bus smaragdas, safyras ir deimantas.'),
  (@b2, 28, 19, 'O trečioji eilė: liguras, agatas ir ametistas.'),
  (@b2, 28, 20, 'Ir ketvirtoji eilė: berilas, oniksas ir jaspis; jie turės būti įstatyti į auksą, į jų įtvarus.'),
  (@b2, 28, 21, 'Ir tie akmenys bus su Izraelio vaikų vardais, dvylika, pagal jų vardus, kaip antspaudo graviūros; jie bus kiekvienas su savo vardu pagal dvylika genčių.'),
  (@b2, 28, 22, 'Ir padaryk ant krūtinės skydelio galų pynimo darbo grandinėles iš gryno aukso.'),
  (@b2, 28, 23, 'Ir padaryk ant krūtinės skydelio du aukso žiedus, ir abu žiedus pritaisyk prie dviejų krūtinės skydelio galų.'),
  (@b2, 28, 24, 'Ir įverk abi pintas aukso grandinėles į abu žiedus, esančius prie krūtinės skydelio galų.'),
  (@b2, 28, 25, 'O abiejų pintų grandinėlių kitus du galus pritvirtink prie dviejų lizdų ir pritaisyk juos prie efodo perpečių priešais jį.'),
  (@b2, 28, 26, 'Ir padaryk du aukso žiedus ir juos pritvirtink prie dviejų krūtinės skydelio galų, tame jo krašte, kuris yra efodo pusėje, į vidų.'),
  (@b2, 28, 27, 'Ir padaryk du kitus aukso žiedus ir juos pritvirtink prie abiejų efodo šonų apačioje, iš priekinės pusės, priešais kitą jo sujungimą, virš dailiosios efodo juostos.'),
  (@b2, 28, 28, 'Ir jie pririš krūtinės skydelį jo žiedais prie efodo žiedų su raiščiu iš mėlyno, kad jis būtų virš dailiosios efodo juostos, ir kad krūtinės skydelis neatsilaisvintų nuo efodo.'),
  (@b2, 28, 29, 'Ir Aaronas nešios Izraelio vaikų vardus teismo krūtinės skydelyje ant savo širdies, kai jis eis į šventąją vietą, dėl atminimo VIEŠPATIES akivaizdoje nuolatos.'),
  (@b2, 28, 30, 'Ir į teismo krūtinės skydelį įdėk Urimą ir Tumimą; ir jie bus ant Aarono širdies, kai jis eina VIEŠPATIES akivaizdon; ir Aaronas nuolat nešios ant savo širdies Izraelio vaikų teismą VIEŠPATIES akivaizdoje.'),
  (@b2, 28, 31, 'O efodo apsiaustą padaryk visą iš mėlyno.'),
  (@b2, 28, 32, 'Ir jo viršuje, jo viduryje bus anga; jis turės austinio darbo apvadą aplinkui jo angą, tarsi šarvo angą, kad jis nesuplyštų.'),
  (@b2, 28, 33, 'O apačioje prie jo apsiuvo padaryk granatus iš mėlyno, purpurinio ir skaisčiai raudono, aplinkui jo apsiuvą; o tarp jų aplinkui – aukso varpelius:'),
  (@b2, 28, 34, 'auksinis varpelis ir granatas, auksinis varpelis ir granatas, prie apsiausto apsiuvo aplinkui.'),
  (@b2, 28, 35, 'Ir jis bus ant Aarono, tarnystei; ir jam įeinant į šventąją vietą VIEŠPATIES akivaizdon ir jam išeinant, jo skambėjimas turės girdėtis, kad jis nemirtų.'),
  (@b2, 28, 36, 'Ir padaryk plokštelę iš gryno aukso ir į ją įrėžk kaip antspaudo graviūras: ‘ŠVENTENYBĖ VIEŠPAČIUI’.'),
  (@b2, 28, 37, 'Ir ją pritvirtink prie mėlyno raiščio, kad ji būtų ant mitros; ji bus ant mitros priekio.'),
  (@b2, 28, 38, 'Ir ji bus ant Aarono kaktos, kad Aaronas nešiotų neteisybes šventųjų dalykų, kuriuos pašvęs Izraelio vaikai visose jų šventose dovanose; ir ji visada bus ant jo kaktos, kad jie būtų priimtini VIEŠPATIES akivaizdoje.'),
  (@b2, 28, 39, 'Ir išsiuvinėk apdarą iš plono lino ir padaryk mitrą iš plono lino, ir padaryk siuvinėto darbo juostą.'),
  (@b2, 28, 40, 'Ir Aarono sūnums padaryk apdarus, ir padaryk jiems juostas, ir kepures jiems padaryk šlovei ir grožiui.'),
  (@b2, 28, 41, 'Ir aprenk jais savo brolį Aaroną ir jo sūnus su juo; ir juos patepk, įšventink ir pašvęsk, kad jie man tarnautų kunigo tarnyboje.'),
  (@b2, 28, 42, 'Ir padaryk jiems linines kelnes jų nuogumui uždengti; jos sieks nuo strėnų iki šlaunų;'),
  (@b2, 28, 43, 'ir jos bus ant Aarono bei jo sūnų, jiems įeinant į susirinkimo padangtę arba jiems artėjant prie aukuro tarnauti šventojoje vietoje; kad jie nenešiotų neteisybės ir nemirtų; tai bus amžinas įstatas jam ir jo sėklai po jo.'),
  (@b2, 29, 1, 'Ir štai, ką jiems padaryk, kad juos pašvęstum man tarnauti kunigo tarnystėje: paimk vieną jauną jautuką ir du avinus be trūkumų,'),
  (@b2, 29, 2, 'neraugintos duonos, neraugintų pyragų, sumaišytų su aliejumi, ir neraugintų papločių, pateptų aliejumi; iš kvietinių miltų juos pagamink.'),
  (@b2, 29, 3, 'Ir įdėk juos į vieną pintinę ir pintinėje juos atgabenk su jautuku ir dviem avinais.'),
  (@b2, 29, 4, 'O Aaroną ir jo sūnus atvesk prie susirinkimo padangtės durų ir juos nuplauk vandeniu.'),
  (@b2, 29, 5, 'Ir paimk drabužius, apvilk Aaroną apdaru, efodo apsiaustu, efodu, krūtinės skydeliu ir apjuosk jį efodo dailiąja juosta;'),
  (@b2, 29, 6, 'ir uždėk mitrą ant jo galvos ir uždėk šventąjį vainiką ant mitros.'),
  (@b2, 29, 7, 'Tada paimk patepimo aliejaus ir užpilk jį ant jo galvos, ir jį patepk.'),
  (@b2, 29, 8, 'Ir atvesk jo sūnus ir juos apvilk apdarais.'),
  (@b2, 29, 9, 'Ir juos apjuosk juostomis, Aaroną ir jo sūnus, ir uždėk jiems kepures; ir kunigo tarnystė bus jų kaip amžinas įstatas; ir įšventink Aaroną ir jo sūnus.'),
  (@b2, 29, 10, 'Ir padaryk, kad būtų atvestas jautukas prieš susirinkimo padangtę; o Aaronas ir jo sūnūs uždės savo rankas ant jautuko galvos.'),
  (@b2, 29, 11, 'Ir papjauk jautuką VIEŠPATIES akivaizdoje prie susirinkimo padangtės durų.'),
  (@b2, 29, 12, 'Ir paimk jautuko kraujo ir užtepk jį savo pirštu ant aukuro ragų, o visą kraują išliek prie aukuro apačios.'),
  (@b2, 29, 13, 'Ir paimk visus taukus, kurie dengia vidurius, virš kepenų esančią taukinę, abu inkstus ir ant jų esančius taukus, ir juos sudegink ant aukuro.'),
  (@b2, 29, 14, 'Bet jautuko mėsą, jo odą ir jo mėšlus sudegink ugnimi už stovyklos; tai nuodėmės atnaša.'),
  (@b2, 29, 15, 'Taip pat imk vieną aviną; o Aaronas ir jo sūnūs uždės savo rankas ant avino galvos.'),
  (@b2, 29, 16, 'Ir papjauk aviną, imk jo kraują ir jį šlakstyk aplinkui ant aukuro.'),
  (@b2, 29, 17, 'O aviną supjaustyk į gabalus, nuplauk jo vidurius ir jo kojas, ir juos sudėk prie jo gabalų bei jo galvos.'),
  (@b2, 29, 18, 'Ir sudegink visą aviną ant aukuro; tai deginamoji atnaša VIEŠPAČIUI; tai gardus kvapas, ugnies atnaša VIEŠPAČIUI.'),
  (@b2, 29, 19, 'Ir paimk kitą aviną; o Aaronas ir jo sūnūs uždės savo rankas ant avino galvos.'),
  (@b2, 29, 20, 'Tada papjauk aviną, paimk jo kraujo, uždėk jo ant Aarono dešinės ausies galo, ant jo sūnų dešinės ausies galo, ant jų dešinės rankos nykščio ir ant jų dešinės kojos nykščio ir šlakstyk kraują aplinkui ant aukuro.'),
  (@b2, 29, 21, 'Ir paimk ant aukuro esančio kraujo bei patepimo aliejaus ir apšlakstyk juo Aaroną, jo drabužius, jo sūnus ir drabužius jo sūnų, esančių su juo; ir bus pašvęstas jis, jo drabužiai, jo sūnūs ir jo sūnų drabužiai su juo.'),
  (@b2, 29, 22, 'Taip pat imk iš avino taukus, pasturgalį, taukus, kurie dengia vidurius, virš kepenų esančią taukinę, abu inkstus, ant jų esančius taukus ir dešinįjį petį; nes tai yra įšventinimo avinas;'),
  (@b2, 29, 23, 'ir vieną duonos kepalą, vieną aliejumi išteptos duonos pyragą ir vieną paplotį iš neraugintos duonos pintinės, esančios VIEŠPATIES akivaizdoje;'),
  (@b2, 29, 24, 'ir viską padėk į Aarono rankas bei jo sūnų rankas; ir mosuok juos kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje.'),
  (@b2, 29, 25, 'Ir imk juos iš jų rankų ir juos sudegink ant aukuro kaip deginamąją atnašą, kaip gardų kvapą VIEŠPATIES akivaizdoje; tai yra ugnies atnaša VIEŠPAČIUI.'),
  (@b2, 29, 26, 'Ir imk Aarono įšventinimo avino krūtinę ir ją mosuok kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje; ir tai bus tavo dalis.'),
  (@b2, 29, 27, 'Ir pašvęsk mosuojamosios atnašos krūtinę ir keliamosios atnašos petį, kuri yra mosuota ir kuri yra kilnota iš įšventinimo avino, iš to, kas yra Aaronui, ir iš to, kas yra jo sūnums;'),
  (@b2, 29, 28, 'ir tai bus Aarono ir jo sūnų pagal amžiną įstatą nuo Izraelio vaikų; nes tai yra keliamoji atnaša; ir tai bus keliamoji atnaša nuo Izraelio vaikų iš jų taikos atnašavimų aukos, jų keliamoji atnaša VIEŠPAČIUI.'),
  (@b2, 29, 29, 'Ir šventi Aarono drabužiai bus jo sūnų po jo, kad juose būtų patepti ir juose būtų įšventinti.'),
  (@b2, 29, 30, 'Ir tas sūnus, kuris yra kunigas jo vietoje, jais apsivilks septynias dienas, įeidamas į susirinkimo padangtę, kad tarnautų šventojoje vietoje.'),
  (@b2, 29, 31, 'Ir imk tą įšventinimo aviną ir išvirk jo mėsą šventojoje vietoje.'),
  (@b2, 29, 32, 'O Aaronas ir jo sūnūs valgys to avino mėsą ir duoną, esančią pintinėje, prie susirinkimo padangtės durų.'),
  (@b2, 29, 33, 'Ir jie valgys tuos dalykus, kuriais buvo atliktas sutaikinimas, kad juos įšventintų ir pašvęstų; bet pašalietis jų nevalgys, nes jie yra šventi.'),
  (@b2, 29, 34, 'O jei kas iš įšventinimų mėsos ar duonos lieka iki ryto, tuomet sudegink likutį ugnimi; tai nebus valgoma, nes tai yra šventa.'),
  (@b2, 29, 35, 'Ir taip daryk Aaronui ir jo sūnums pagal visus dalykus, kuriuos tau įsakiau: septynias dienas atlikinėk jų įšventinimą.'),
  (@b2, 29, 36, 'Ir kiekvieną dieną atnašauk jautuką, kaip nuodėmės atnašą sutaikinimui; ir apvalyk aukurą, kai būsi atlikęs sutaikinimą už jį, ir jį patepk, kad jį pašvęstum.'),
  (@b2, 29, 37, 'Septynias dienas atlikinėk sutaikinimą už aukurą ir jį pašvęsk; ir jis bus švenčiausias aukuras; kas palies aukurą, tas bus šventas.'),
  (@b2, 29, 38, 'Na, o štai ką atnašauk ant aukuro: be perstojo, kiekvieną dieną, du pirmų metų avinėlius.'),
  (@b2, 29, 39, 'Vieną avinėlį atnašauk ryte; o kitą avinėlį atnašauk vakare;'),
  (@b2, 29, 40, 'ir su vienu avinėliu dešimtą dalį miltų, sumaišytų su ketvirtadaliu hino grūsto aliejaus; ir ketvirtadalį hino vyno kaip geriamąją atnašą.'),
  (@b2, 29, 41, 'O kitą avinėlį atnašauk vakare ir jam daryk pagal rytinę maisto atnašą bei jo geriamąją atnašą, kaip gardų kvapą, ugnies atnašą VIEŠPAČIUI.'),
  (@b2, 29, 42, 'Tai bus per jūsų kartas nuolatinė deginamoji atnaša VIEŠPATIES akivaizdoje, prie susirinkimo padangtės durų; kur aš susitiksiu su jumis, kad ten tau kalbėčiau.'),
  (@b2, 29, 43, 'Ir ten aš susitiksiu su Izraelio vaikais, ir padangtė bus pašvęsta mano šlove.'),
  (@b2, 29, 44, 'Ir aš pašvęsiu susirinkimo padangtę ir aukurą; taip pat aš pašvęsiu Aaroną ir jo sūnus, kad jie man tarnautų kunigo tarnystėje.'),
  (@b2, 29, 45, 'Ir aš gyvensiu tarp Izraelio vaikų ir būsiu jų Dievas.'),
  (@b2, 29, 46, 'Ir jie žinos, kad aš esu VIEŠPATS, jų Dievas, kuris juos išvedžiau iš Egipto šalies, idant gyvenčiau tarp jų; aš esu VIEŠPATS, jų Dievas.'),
  (@b2, 30, 1, 'Ir padaryk aukurą smilkymui ant jo; iš šitimo medžio jį padaryk.'),
  (@b2, 30, 2, 'Jo ilgis bus uolektis, ir plotis uolektis; jis bus kvadratinis; o jo aukštis bus dvi uolektys; jo ragai bus iš to paties.'),
  (@b2, 30, 3, 'Ir padenk jį grynu auksu, jo viršų, jo šonus aplinkui ir jo ragus; ir jam aplinkui padaryk aukso vainiką.'),
  (@b2, 30, 4, 'Ir du auksinius žiedus jam padaryk po jo vainiku, prie abiejų jo kampų, padaryk tai ant abiejų jo šonų; ir jie bus kaip vietos kartims, kad jomis jį neštų.'),
  (@b2, 30, 5, 'O kartis padaryk iš šitimo medžio ir padenk jas auksu.'),
  (@b2, 30, 6, 'Ir jį pastatyk prieš uždangą, esančią prie Liudijimo skrynios, prieš gailestingumo krasę, esančią virš Liudijimo, kur aš susitiksiu su tavimi.'),
  (@b2, 30, 7, 'O Aaronas kiekvieną rytą degins ant jo kvapius smilkalus; kai jis ruoš žibintus, jis ant jo degins smilkalus.'),
  (@b2, 30, 8, 'O kai Aaronas vakare uždegs žibintus, jis ant jo degins smilkalus, nuolatinius smilkalus VIEŠPATIES akivaizdoje per jūsų kartas.'),
  (@b2, 30, 9, 'Neaukokite ant jo svetimų smilkalų nei deginamosios aukos, nei maisto atnašos; nei geriamosios atnašos ant jo neišliekite.'),
  (@b2, 30, 10, 'O kartą metuose Aaronas atliks ant jo ragų sutaikinimą nuodėmės atnašos sutaikinimų krauju; jis atliks ant jo sutaikinimą kartą metuose, per jūsų kartas; tai yra švenčiausia VIEŠPAČIUI“.'),
  (@b2, 30, 11, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 30, 12, '„Kai sumuosi Izraelio vaikus pagal jų skaičių, tada jie kiekvienas duos išpirką už savo sielą VIEŠPAČIUI, kai juos skaičiuosi; kad tarp jų nebūtų kokia rykštė, kai juos skaičiuosi.'),
  (@b2, 30, 13, 'Štai ką duos jie, kiekvienas, kuris pereis tarp suskaičiuotųjų: pusę šekelio pagal šventovės šekelį (šekelis yra dvidešimt gerų); pusė šekelio bus VIEŠPATIES atnaša.'),
  (@b2, 30, 14, 'Kiekvienas, kuris pereina tarp suskaičiuotųjų, nuo dvidešimties metų ir daugiau, duos atnašą VIEŠPAČIUI.'),
  (@b2, 30, 15, 'Jiems duodant atnašą VIEŠPAČIUI, kad atliktų sutaikinimą už jūsų sielas, turtingasis neturės duoti daugiau, o beturtis neturės duoti mažiau kaip pusę šekelio.'),
  (@b2, 30, 16, 'Ir paimk iš Izraelio vaikų sutaikinimo pinigus ir paskirk juos susirinkimo padangtės tarnystei; kad tai būtų atminimas Izraelio vaikams VIEŠPATIES akivaizdoje, atlikti sutaikinimui už jūsų sielas“.'),
  (@b2, 30, 17, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b2, 30, 18, '„Taip pat padaryk praustuvę iš žalvario, ir taip pat jos koją iš žalvario, nusiplovimui; ir ją pastatyk tarp susirinkimo padangtės ir aukuro, ir įpilk į ją vandens.'),
  (@b2, 30, 19, 'Nes Aaronas ir jo sūnūs ten nusiplaus savo rankas ir savo kojas;'),
  (@b2, 30, 20, 'įeidami į susirinkimo padangtę, jie nusiplaus vandeniu, kad nemirtų; arba artėdami prie aukuro tarnauti, kad degintų ugnies atnašą VIEŠPAČIUI;'),
  (@b2, 30, 21, 'taigi jie nusiplaus rankas ir kojas, kad nemirtų; ir tai jiems bus amžinas įstatas, jam ir jo sėklai per jų kartas“.'),
  (@b2, 30, 22, 'Dar VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 30, 23, '„Taip pat imk sau geriausių kvapų: penkis šimtus šekelių grynos miros, kvapaus cinamono pusę tiek, tai yra du šimtus penkiasdešimt šekelių ir du šimtus penkiasdešimt šekelių kvapaus ajero,'),
  (@b2, 30, 24, 'penkis šimtus šekelių kasijos, pagal šventovės šekelį, ir hiną alyvų aliejaus;'),
  (@b2, 30, 25, 'ir iš tų padaryk švento tepalo aliejų, tepalą, sumaišytą vaistininko meistriškumu; tai bus šventas patepimo aliejus.'),
  (@b2, 30, 26, 'Ir juo patepk susirinkimo padangtę, Liudijimo skrynią,'),
  (@b2, 30, 27, 'stalą ir visus jo indus, žvakidę ir jos indus, smilkalų aukurą,'),
  (@b2, 30, 28, 'deginamosios atnašos aukurą su visais jo indais ir praustuvę su jos koja.'),
  (@b2, 30, 29, 'Ir juos pašvęsk, kad jie būtų švenčiausi; kas tik juos palies, tas bus šventas.'),
  (@b2, 30, 30, 'Ir patepk Aaroną bei jo sūnus ir juos įšventink, kad jie man tarnautų kunigo tarnyboje.'),
  (@b2, 30, 31, 'Ir kalbėk Izraelio vaikams, sakydamas: ‘Šitas man bus šventas patepimo aliejus per jūsų kartas.'),
  (@b2, 30, 32, 'Ant žmogaus kūno jis nebus išliejamas, taip pat jūs nedarykite kokio kito panašaus į jį jo sudėtimi: jis yra šventas ir jis bus jums šventas.'),
  (@b2, 30, 33, 'Kas sumaišytų kokį kaip šis, ar kas uždėtų jo nors kiek ant pašaliečio, bus iškirstas iš savo tautos’“.'),
  (@b2, 30, 34, 'Ir VIEŠPATS tarė Mozei: „Imk sau gardžių kvapų: stakto, onikso ir galbano; šitų gardžių kvapų su grynais smilkalais; kiekvieno jų turi būti po lygiai svorio;'),
  (@b2, 30, 35, 'ir padaryk iš jų kvepalus, mišinį vaistininko meistriškumo, sumaišytą, gryną ir šventą;'),
  (@b2, 30, 36, 'ir sutrink dalį jo labai smulkiai, ir padėk jo priešais Liudijimą susirinkimo padangtėje, kur aš susitiksiu su tavimi; tai jums bus švenčiausia.'),
  (@b2, 30, 37, 'O dėl kvepalų, kuriuos padarysi, sau nesidarykite pagal jų sudėtį; jie tau bus šventi VIEŠPAČIUI.'),
  (@b2, 30, 38, 'Kas padarys tokius, kaip šitie, kad juos uostytų, tas bus iškirstas iš savo tautos“.'),
  (@b2, 31, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 31, 2, '„Štai aš pašaukiau vardu Hūro sūnaus Ūrio sūnų Becalelį iš Judos genties;'),
  (@b2, 31, 3, 'ir jį pripildžiau Dievo Dvasia, išmintimi, supratimu, pažinimu ir visokiu meistriškumu,'),
  (@b2, 31, 4, 'kad sugalvotų sumanių darbų, kad dirbtų iš aukso, sidabro ir žalvario,'),
  (@b2, 31, 5, 'ir akmenų pjaustyme, kad juos įstatytų, ir medienos pjaustyme, kad dirbtų visokį darbą.'),
  (@b2, 31, 6, 'O aš, štai aš daviau su juo Ahisamacho sūnų Oholiabą iš Dano genties; ir į visų išmintingos širdies esančiųjų širdis aš įdėjau išmintį, kad jie padarytų viską, ką esu tau įsakęs:'),
  (@b2, 31, 7, 'susirinkimo padangtę, Liudijimo skrynią bei ant jos esančią gailestingumo krasę, visus padangtės reikmenis,'),
  (@b2, 31, 8, 'stalą su jo reikmenimis, gryną žvakidę su visais jos reikmenimis, smilkymo aukurą,'),
  (@b2, 31, 9, 'deginamosios atnašos aukurą su visais jo reikmenimis, praustuvę su jos koja,'),
  (@b2, 31, 10, 'tarnavimo rūbus, šventus drabužius kunigui Aaronui ir jo sūnų drabužius – kad tarnautų kunigo tarnyboje,'),
  (@b2, 31, 11, 'patepimo aliejų ir kvapius smilkalus šventajai vietai; jie padarys pagal visa tai, ką esu tau įsakęs“.'),
  (@b2, 31, 12, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 31, 13, '„Taip pat kalbėk Izraelio vaikams, sakydamas: ‘Tikrai laikykitės mano sabatų; nes jie yra ženklas tarp manęs ir jūsų per jūsų kartas; kad žinotumėte, jog esu VIEŠPATS, kuris jus pašvenčiu.'),
  (@b2, 31, 14, 'Todėl laikykitės sabato; nes jis jums yra šventas; kiekvienas, kuris jį suterš, tikrai bus užmuštas; nes kiekvienas, kuris per jį dirbs kokį darbą, ta siela bus iškirsta iš savo tautos tarpo.'),
  (@b2, 31, 15, 'Šešias dienas gali būti atliekamas darbas; bet septintąją yra poilsio sabatas, šventas VIEŠPAČIUI; kas sabato dieną darys kokį darbą, tas tikrai bus užmuštas.'),
  (@b2, 31, 16, 'Todėl Izraelio vaikai turės laikytis sabato, kad švęstų sabatą per savo kartas kaip amžiną sandorą.'),
  (@b2, 31, 17, 'Jis yra ženklas tarp manęs ir Izraelio vaikų per amžius; nes per šešias dienas VIEŠPATS padarė dangų ir žemę, o septintąją dieną jis ilsėjosi ir atsigaivino’“.'),
  (@b2, 31, 18, 'Ir jis Mozei, baigęs su juo kalbėtis ant Sinajaus kalno, davė dvi liudijimo plokštes, akmens plokštes, užrašytas Dievo pirštu.'),
  (@b2, 32, 1, 'O tauta, matydama, kad Mozė delsia nulipti nuo kalno, tauta susirinko prie Aarono ir jam tarė: „Kelkis, padaryk mums dievų, kurie eitų pirma mūsų; nes kas dėl šito Mozės, to vyro, kuris mus išvedė iš Egipto šalies, nežinome, kas jam atsitiko“.'),
  (@b2, 32, 2, 'Ir Aaronas jiems tarė: „Nutraukite auksinius auskarus, esančius jūsų žmonų, jūsų sūnų ir jūsų dukterų ausyse, ir atneškite juos man“.'),
  (@b2, 32, 3, 'Ir visa tauta nusitraukė auksinius auskarus, esančius jų ausyse, ir atnešė juos Aaronui.'),
  (@b2, 32, 4, 'Ir gavęs juos iš jų rankų, ir padaręs iš to nulietą veršį, jis apdirbo tai raižikliu; ir jie tarė: „Šitie yra tavo dievai, o Izraeli, kurie tave išvedė aukštyn iš Egipto šalies“.'),
  (@b2, 32, 5, 'Ir Aaronas, tai pamatęs, pastatė aukurą to priešakyje; ir Aaronas paskelbė ir tarė: „Rytoj yra šventė VIEŠPAČIUI“.'),
  (@b2, 32, 6, 'Ir atsikėlę anksti rytojaus dieną, jie atnašavo deginamąsias atnašas ir atnešė taikos atnašas; ir tauta sėdosi valgyti ir gerti, ir kėlėsi žaisti.'),
  (@b2, 32, 7, 'Ir VIEŠPATS tarė Mozei: „Eik, lipk žemyn; nes tavo tauta, kurią išvedei iš Egipto šalies, sugedo;'),
  (@b2, 32, 8, 'jie greitai nukrypo nuo kelio, kurį jiems įsakiau: jie pasidarė sau nulietą veršį, garbino jį, jam aukojo ir tarė: ‘Šitie yra tavo dievai, o Izraeli, kurie tave išvedė aukštyn iš Egipto šalies’“.'),
  (@b2, 32, 9, 'Ir VIEŠPATS tarė Mozei: „Aš mačiau šitą tautą, ir štai ji kietasprandė tauta;'),
  (@b2, 32, 10, 'taigi dabar palik mane ramybėje, kad mano rūstybė užsidegtų prieš juos ir kad juos sunaikinčiau; o iš tavęs aš padarysiu didžiulę tautą“.'),
  (@b2, 32, 11, 'Ir Mozė maldavo VIEŠPATĮ, savo Dievą, tardamas: „Kodėl, VIEŠPATIE, ušsidega tavo rūstybė prieš tavo tautą, kurią tu išvedei iš Egipto šalies su didele jėga ir galinga ranka?'),
  (@b2, 32, 12, 'Kodėl turėtų kalbėti egiptiečiai, sakydami: ‘Blogybei jis juos išvedė, kad juos išžudytų kalnuose ir išnaikintų juos nuo žemės paviršiaus’? Gręžkis nuo savo įnirtingos rūstybės ir apsigalvok dėl to pikto savo tautai.'),
  (@b2, 32, 13, 'Atsimink savo tarnus Abraomą, Izaoką ir Izraelį, kuriems prisiekei pačiu savimi ir jiems sakei: ‘Aš padauginsiu jūsų sėklą kaip dangaus žvaigždes, ir visą šitą šalį, apie kurią kalbėjau, duosiu jūsų sėklai, ir jie ją paveldės amžinai’“.'),
  (@b2, 32, 14, 'Ir VIEŠPATS apsigalvojo dėl to pikto, kurį jis galvojo padaryti savo tautai.'),
  (@b2, 32, 15, 'Ir atsigrežęs Mozė lipo žemyn nuo kalno, ir jo rankoje buvo dvi liudijimo plokštės; plokštės buvo prirašytos abiejose jų pusėse; vienoje ir kitoje pusėje jos buvo prirašytos.'),
  (@b2, 32, 16, 'O plokštės buvo Dievo darbas, ir raštas buvo Dievo raštas, įrėžtas į plokštes.'),
  (@b2, 32, 17, 'O Jozuė, išgirdęs tautos triukšmą, kai jie šūkavo, tarė Mozei: „Karo triukšmas stovykloje“.'),
  (@b2, 32, 18, 'O jis tarė: „Tai ne nugalėjusiųjų šauksmo balsas ir ne nugalėtųjų šauksmo balsas; bet giedančiųjų garsą aš girdžiu“.'),
  (@b2, 32, 19, 'Ir įvyko, kai tik jis priartėjo prie stovyklos, jis išvydo veršį ir šokius; ir užsidegė Mozės pyktis, ir jis išmetė iš savo rankų plokštes, ir jas sudaužė kalno papėdėje.'),
  (@b2, 32, 20, 'Ir jis ėmė veršį, kurį jie buvo padarę, sudegino jį ugnyje ir sutrynė į miltus, ir išbarstė ant vandens, ir sugirdė tai Izraelio vaikams.'),
  (@b2, 32, 21, 'Ir Mozė tarė Aaronui: „Ką tau padarė šita tauta, kad tu užtraukei ant jos tokią didelę nuodėmę?“'),
  (@b2, 32, 22, 'Ir Aaronas tarė: „Teneužsidega mano viešpaties pyktis; tu žinai tą tautą, kad jie linkę į piktadarystę.'),
  (@b2, 32, 23, 'Nes jie man sakė: ‘Padaryk mums dievų, kurie eitų pirma mūsų; nes kas dėl šito Mozės, to vyro, kuris mus išvedė aukštyn iš Egipto šalies, nežinome, kas jam atsitiko’.'),
  (@b2, 32, 24, 'Ir aš jiems tariau: ‘Kas turi aukso, tenusitraukia jį’. Taigi jie man jį davė; tada aš įmečiau jį į ugnį, ir išėjo šitas veršis“.'),
  (@b2, 32, 25, 'Ir kai Mozė pamatė, kad tauta buvo nuoga (nes Aaronas buvo ją apnuoginęs jų gėdai tarp jų priešų);'),
  (@b2, 32, 26, 'tada Mozė atsistojo stovyklos vartuose ir tarė: „Kas yra VIEŠPATIES pusėje, teateina pas mane“. Ir susirinko pas jį visi Levio sūnūs.'),
  (@b2, 32, 27, 'Ir jis jiems tarė: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Kiekvienas prisidėkite savo kalaviją prie šono, eikite šen ir ten per stovyklą, nuo vartų iki vartų, ir žudykite kiekvienas savo brolį, kiekvienas savo draugą ir kiekvienas savo artimą’“.'),
  (@b2, 32, 28, 'Ir Levio vaikai padarė pagal Mozės žodį; ir tą dieną krito iš tautos apie tris tūkstančius vyrų.'),
  (@b2, 32, 29, 'Nes Mozė buvo sakęs: „Pasišvęskite šiandien VIEŠPAČIUI, kiekvienas ant savo sūnaus ir ant savo brolio; kad jis jums šiandien suteiktų palaiminimą“.'),
  (@b2, 32, 30, 'Ir įvyko rytojaus dieną, kad Mozė tarė tautai: „Jūs nusidėjote didele nuodėme; o dabar aš eisiu aukštyn pas VIEŠPATĮ; galbūt atliksiu sutaikinimą už jūsų nuodėmę“.'),
  (@b2, 32, 31, 'Ir sugrįžęs pas VIEŠPATĮ Mozė tarė: „Ak, šita tauta nusidėjo didele nuodėme ir pasidarė aukso dievų.'),
  (@b2, 32, 32, 'Tačiau dabar, jei norėsi, atleisk jų nuodėmę; o jei ne, meldžiu tave, išbrauk mane iš savo knygos, kurią esi parašęs“.'),
  (@b2, 32, 33, 'Ir VIEŠPATS tarė Mozei: „Kas prieš mane nusidėjęs, tą aš išbrauksiu iš savo knygos.'),
  (@b2, 32, 34, 'Todėl dabar eik, vesk tautą į vietą, apie kurią esu tau kalbėjęs; štai mano Angelas eis pirma tavęs; tačiau tą dieną, kai aš aplankysiu, aš aplankysiu jų nuodėmę ant jų“.'),
  (@b2, 32, 35, 'Ir VIEŠPATS ištiko tautą rykšte, nes jie padarė tą veršį, kurį padarė Aaronas.'),
  (@b2, 33, 1, 'Ir VIEŠPATS tarė Mozei: „Išeik, eik iš čia aukštyn, tu ir tauta, kurią išvedei aukštyn iš Egipto šalies, į šalį, kurią prisiekiau Abraomui, Izaokui ir Jokūbui, sakydamas: ‘Aš ją duosiu tavo sėklai’;'),
  (@b2, 33, 2, 'ir aš siųsiu pirma tavęs angelą; ir išvarysiu kanaanietį, amoritą, hetitą, perizą, hivą ir jebusietį;'),
  (@b2, 33, 3, 'į šalį, plūstančią pienu ir medumi; nes aš neisiu aukštyn tavo tarpe; nes tu esi kietasprandė tauta; kad aš nesunaikinčiau tavęs kelyje“.'),
  (@b2, 33, 4, 'O išgirdusi tą piktą žinią, tauta gedėjo; ir nei vienas neužsidėjo savo papuošalų.'),
  (@b2, 33, 5, 'Nes VIEŠPATS buvo sakęs Mozei: „Sakyk Izraelio vaikams: ‘Jūs esate kietasprandė tauta; aš akimirksniu ateisiu aukštyn į tavo tarpą ir tave sunaikinsiu; todėl dabar nusiimk savo papuošalus, kad žinočiau, ką daryti su tavimi’“.'),
  (@b2, 33, 6, 'Ir Izraelio vaikai nusiėmė savo papuošalus prie Horebo kalno.'),
  (@b2, 33, 7, 'O Mozė ėmė padangtę ir ją pastatė už stovyklos, toli nuo stovyklos, ir ją praminė Susirinkimo padangte. Ir įvyko, kad kiekvienas, kuris ieškojo VIEŠPATIES, išeidavo prie Susirinkimo padangtės, kuri buvo už stovyklos.'),
  (@b2, 33, 8, 'Ir įvyko, kai Mozė išeidavo prie padangtės, tada visa tauta pakildavo, kiekvienas atsistodavo savo palapinės duryse ir žiūrėdavo paskui Mozę, kol jis įeidavo į padangtę.'),
  (@b2, 33, 9, 'Ir įvyko, kai Mozė įeidavo į padangtę, nusileisdavo debesuotas stulpas ir stovėdavo padangtės duryse, ir VIEŠPATS kalbėdavosi su Moze.'),
  (@b2, 33, 10, 'Ir visa tauta matė debesuotą stulpą stovint padangtės duryse; ir visa tauta pakilo ir pagarbino, kiekvienas savo palapinės duryse.'),
  (@b2, 33, 11, 'Ir VIEŠPATS kalbėdavo Mozei veidas į veidą, kaip žmogus kalba savo draugui. Ir jis sugrįždavo į stovyklą; bet jo tarnas Jozuė, Nūno sūnus, jaunuolis, nepasitraukdavo iš padangtės.'),
  (@b2, 33, 12, 'Ir Mozė tarė VIEŠPAČIUI: „Štai tu man sakai: ‘Vesk aukštyn šitą tautą’; bet nedavei man žinoti, ką pasiųsi su manimi. Tačiau tu man sakei: ‘Aš pažįstu tave vardu, ir taip pat, tu radai malonę mano akyse’.'),
  (@b2, 33, 13, 'Taigi dabar, jei radau malonę tavo akyse, meldžiu tave, paskelbk man dabar savo kelią, kad tave pažinčiau, kad rasčiau malonę tavo akyse; ir atsižvelk, kad šita tauta yra tavo liaudis“.'),
  (@b2, 33, 14, 'Ir jis tarė: „Mano artumas eis su tavimi, ir aš tau duosiu poilsį“.'),
  (@b2, 33, 15, 'Ir jis jam tarė: „Jei tavo artumas neis su manimi, tai nevesk mūsų iš čia aukštyn.'),
  (@b2, 33, 16, 'Iš ko gi bus galima pažinti, kad aš ir tavo tauta radome malonę tavo akyse? Argi ne iš to, kad eini su mumis? Taip mes būsime atskirti, aš ir tavo tauta, nuo visų tautų, esančių ant žemės paviršiaus“.'),
  (@b2, 33, 17, 'Ir VIEŠPATS tarė Mozei: „Taip pat ir šitą dalyką, kurį kalbėjai, aš padarysiu; nes tu radai malonę mano akyse, ir aš tave pažįstu vardu“.'),
  (@b2, 33, 18, 'Ir jis tarė: „Meldžiu tave, parodyk man savo šlovę“.'),
  (@b2, 33, 19, 'Ir jis tarė: „Aš leisiu praeiti tavo akivaizdoje visam savo gerumui ir paskelbsiu VIEŠPATIES vardą tavo priešakyje; ir būsiu maloningas, kam būsiu maloningas, ir parodysiu gailestingumą, kuriam parodysiu gailestingumą“.'),
  (@b2, 33, 20, 'Ir jis tarė: „Tu negali išvysti mano veido; nes nėra žmogaus, kuris mane regėtų ir gyventų“.'),
  (@b2, 33, 21, 'Ir VIEŠPATS tarė: „Štai šalia manęs yra vieta, ir tu atsistok ant uolos;'),
  (@b2, 33, 22, 'ir įvyks, kad praeinant mano šlovei, aš tave pastatysiu uolos plyšyje ir tave apdengsiu savo ranka, kol praeisiu;'),
  (@b2, 33, 23, 'ir atitrauksiu savo ranką, o tu matysi mano nugarą; bet mano veidas nebus matomas“.'),
  (@b2, 34, 1, 'Ir VIEŠPATS tarė Mozei: „Išsikirsk dvi akmens plokštes, tokias, kaip pirmosios; ir aš įrašysiu į šias plokštes žodžius, kurie buvo pirmosiose plokštėse, kurias tu sudaužei.'),
  (@b2, 34, 2, 'Ir būk pasiruošęs ryte, užkilk ryte ant Sinajaus kalno ir ten man atsistok kalno viršūnėje.'),
  (@b2, 34, 3, 'Ir niekas tenelipa su tavimi ir nei vieno tenesimato visame kalne; taip pat nei kaimenės, nei bandos tenesigano prieš tą kalną“.'),
  (@b2, 34, 4, 'Ir jis iškirto dvi akmens plokštes, tokias, kaip pirmosios; ir anksti ryte atsikėlęs Mozė užkilo ant Sinajaus kalno, kaip VIEŠPATS jam buvo įsakęs, pasiėmęs į ranką dvi akmens plokštes.'),
  (@b2, 34, 5, 'Ir VIEŠPATS nusileido debesyje, ten atsistojo prie jo ir paskelbė VIEŠPATIES vardą.'),
  (@b2, 34, 6, 'Ir VIEŠPATS praėjo jo priešakyje ir paskelbė: „VIEŠPATS, VIEŠPATS Dievas, gailestingas ir maloningas, ilgai pakantus, gausus gerumu ir tiesa,'),
  (@b2, 34, 7, 'išlaikantis gailestingumą tūkstančiams, atleidžiantis neteisybę, nusižengimą ir nuodėmę, bet jokiu būdu nepateisinantis kalto; aplankantis tėvų kaltę ant vaikų ir ant vaikų vaikų iki trečios ir ketvirtos kartos“.'),
  (@b2, 34, 8, 'Ir Mozė pasiskubino ir nusilenkė galva iki žemės, ir pagarbino.'),
  (@b2, 34, 9, 'Ir jis tarė: „Jei dabar radau malonę tavo akyse, o Viešpatie, meldžiu tave, tegul mano Viešpats eina tarpe mūsų; nes tai kietasprandė tauta; ir atleisk mūsų neteisybę bei mūsų nuodėmę ir paimk mus savo nuosavybėn“.'),
  (@b2, 34, 10, 'Ir jis tarė: „Štai aš darau sandorą; visos tavo tautos akivaizdoje aš darysiu stebuklus, kokių nebuvo daryta visoje žemėje nei jokioje tautoje; ir visa tauta, tarp kurios tu esi, matys VIEŠPATIES darbą; nes siaubinga tai, ką darysiu su tavimi.'),
  (@b2, 34, 12, 'Saugokis, kad nedarytum sandoros su gyventojais šalies, į kurią eini, kad tai nebūtų žabangomis tavo tarpe;'),
  (@b2, 34, 13, 'bet jūs sugriaukite jų aukurus, sudaužykite jų atvaizdus ir iškirskite jų giraites;'),
  (@b2, 34, 14, 'nes tu negarbinsi kito dievo; nes VIEŠPATS, kurio vardas yra Pavydulingasis, yra pavydulingas Dievas;'),
  (@b2, 34, 15, 'kad nedarytum sandoros su šalies gyventojais, ir jiems einant ištvirkauti paskui savo dievus ir aukojant savo dievams, kažkam tave pakvietus, nevalgytum jo aukos;'),
  (@b2, 34, 16, 'ir neimtum iš jų dukterų savo sūnums, ir jų dukterims ištvirkaujant paskui savo dievus, nepadarytų, kad tavo sūnūs ištvirkautų paskui jų dievus.'),
  (@b2, 34, 17, 'Nesidaryk sau nulietų dievų.'),
  (@b2, 34, 18, 'Švęsk Neraugintos duonos šventę. Septynias dienas valgyk neraugintą duoną, kaip esu tau įsakęs, Abibo mėnesio laiku; nes Abibo mėnesį tu išėjai iš Egipto.'),
  (@b2, 34, 19, 'Visi atveriantys gimdą yra mano; ir kiekvienas pirmagimis, kuris yra patinas tarp tavo galvijų, ar tai jautis, ar avis.'),
  (@b2, 34, 20, 'Bet asilo pirmagimį atpirk avinėliu; o jeigu jo neatpirksi, tada nulaužk jam sprandą. Atpirk visus savo sūnų pirmagimius. Ir niekas tenepasirodo mano akivaizdoje tuščiomis.'),
  (@b2, 34, 21, 'Dirbk šešias dienas, bet septintąją dieną ilsėkis; arimo ir pjūties metu ilsėkis.'),
  (@b2, 34, 22, 'Ir švęsk Savaičių šventę, kviečių pjūties pirmavaisių, ir Surinkimo šventę metų pabaigoje.'),
  (@b2, 34, 23, 'Triskart metuose visi tavo vyriškos lyties vaikai pasirodys Viešpaties DIEVO, Izraelio Dievo, akivaizdoje.'),
  (@b2, 34, 24, 'Nes aš išvarysiu tautas tavo akivaizdoje ir praplatinsiu tavo ribas; taip pat niekas neužsigeis tavo šalies, tau triskart metuose einant aukštyn pasirodyti VIEŠPATIES, tavo Dievo, akivaizdoje.'),
  (@b2, 34, 25, 'Neatnašauk mano aukos kraujo su raugu; nei Apėjimo šventės auka tenepasilieka iki ryto.'),
  (@b2, 34, 26, 'Pirmus iš savo žemės pirmavaisių atnešk į VIEŠPATIES, savo Dievo, namus. Nevirk ožiuko jo motinos piene“.'),
  (@b2, 34, 27, 'Ir VIEŠPATS tarė Mozei: „Užrašyk šituos žodžius; nes pagal šitų žodžių turinį aš sudariau sandorą su tavimi ir Izraeliu“.'),
  (@b2, 34, 28, 'Ir jis ten buvo su VIEŠPAČIU keturiasdešimt dienų ir keturiasdešimt naktų; jis nei duonos nevalgė, nei vandens negėrė. Ir jis užrašė į plokštes sandoros žodžius, dešimt įsakymų.'),
  (@b2, 34, 29, 'Ir įvyko, kai Mozė atėjo žemyn nuo Sinajaus kalno su dviem Liudijimo plokštėmis Mozės rankoje, jam nulipus žemyn nuo kalno, Mozė nežinojo, kad jo veido oda spindėjo jam kalbantis su juo.'),
  (@b2, 34, 30, 'O kai Aaronas ir visi Izraelio vaikai pamatė Mozę, štai jo veido oda spindėjo; ir jie bijojo prie jo priartėti.'),
  (@b2, 34, 31, 'Ir Mozė juos pašaukė; ir Aaronas bei visi susirinkimo valdovai sugrįžo pas jį; ir Mozė kalbėjo su jais.'),
  (@b2, 34, 32, 'O po to priartėjo visi Izraelio vaikai; ir jis jiems davė įsakymu visa, ką VIEŠPATS buvo kalbėjęs su juo Sinajaus kalne.'),
  (@b2, 34, 33, 'Ir kol Mozė nebaigė kalbėti su jais, jis užsidėjo ant veido gaubtuvą.'),
  (@b2, 34, 34, 'Bet kai Mozė įeidavo VIEŠPATIES akivaizdon kalbėtis su juo, jis nusiimdavo gaubtuvą iki kol išeidavo. Ir išėjęs jis kalbėdavo Izraelio vaikams tai, kas jam buvo įsakyta.'),
  (@b2, 34, 35, 'Ir Izraelio vaikai matė Mozės veidą, kad spindėjo Mozės veido oda; ir Mozė vėl užsidėdavo ant veido gaubtuvą, iki įeidavo kalbėtis su juo.'),
  (@b2, 34, 11, 'Laikykis to, ką tau šią dieną įsakau; štai aš išvarysiu tavo akivaizdoje amoritą, kanaanietį, hetitą, perizą, hivą ir jebusietį.'),
  (@b2, 35, 1, 'Ir Mozė surinko visą Izraelio vaikų susirinkimą ir jiems tarė: „Šitie yra žodžiai, kuriuos VIEŠPATS įsakė, kad juos vykdytumėte.'),
  (@b2, 35, 2, 'Šešias dienas bus atliekamas darbas, bet septintąją dieną jums bus šventa diena, poilsio sabatas VIEŠPAČIUI; kas joje darys darbą, bus užmuštas.'),
  (@b2, 35, 3, 'Nekurkite ugnies sabato dieną nei vienoje jūsų buveinėje“.'),
  (@b2, 35, 4, 'Ir Mozė kalbėjo visam Izraelio vaikų susirinkimui, sakydamas: „Štai ką VIEŠPATS įsakė, sakydamas:'),
  (@b2, 35, 5, '‘Paimkite iš savo tarpo atnašą VIEŠPAČIUI; kiekvienas, esantis laisvanoriškos širdies, ją teatneša – VIEŠPATIES atnašą: aukso, sidabro, žalvario,'),
  (@b2, 35, 6, 'mėlyno, purpurinio, skaisčiai raudono, plono lino, ožkos šerių,'),
  (@b2, 35, 7, 'raudonai dažytų avinų odų ir barsukų odų, šitimo medžio,'),
  (@b2, 35, 8, 'aliejaus apšvietimui, kvapų patepimo aliejui bei kvapiems smilkalams,'),
  (@b2, 35, 9, 'onikso akmenų ir akmenų – kad būtų įstatyti – efodui ir krūtinės skydeliui.'),
  (@b2, 35, 10, 'Ir visi tarp jūsų esantys išmintingos širdies teateina ir padaro viską, ką VIEŠPATS yra įsakęs:'),
  (@b2, 35, 11, 'padangtę, jos palapinę, jos apdangalą, jos kabes, jos lentas, jos skersinius, jos stulpus ir jos movas,'),
  (@b2, 35, 12, 'skrynią ir jos kartis bei gailestingumo krasę ir apdengimo uždangą,'),
  (@b2, 35, 13, 'stalą, jo kartis, visus jo indus bei parodomąją duoną,'),
  (@b2, 35, 14, 'taip pat žvakidę šviesai, jos reikmenis, jos žibintus su aliejumi šviesai,'),
  (@b2, 35, 15, 'smilkalų aukurą bei jo kartis, patepimo aliejų, kvapius smilkalus ir užuolaidą durims ties padangtės įėjimu,'),
  (@b2, 35, 16, 'deginamosios atnašos aukurą su jo žalvarinėmis grotelėmis, jo kartimis ir visais jo indais, praustuvę su jos koja,'),
  (@b2, 35, 17, 'kiemo užuolaidas, jo stulpus bei jų movas ir užuolaidą kiemo durims,'),
  (@b2, 35, 18, 'padangtės kuolus, kiemo kuolus bei jų virves,'),
  (@b2, 35, 19, 'tarnavimo drabužius, tarnauti šventojoje vietoje, šventus drabužius kunigui Aaronui ir jo sūnų drabužius, kad tarnautų kunigo tarnyboje’“.'),
  (@b2, 35, 20, 'Ir visas Izraelio vaikų susirinkimas pasišalino iš Mozės akivaizdos.'),
  (@b2, 35, 21, 'Ir atėję, kiekvienas savo širdies pažadintas, ir kiekvienas, savo dvasios paskatintas laisvanoriškumui, jie atnešė VIEŠPATIES atnašą susirinkimo padangtės darbui, visai jo tarnystei ir šventiems drabužiams.'),
  (@b2, 35, 22, 'Ir jie atėję, tiek vyrai, tiek moterys, visi esantys laisvanoriškos širdies, atnešė apyrankes, auskarus, žiedus ir plokšteles, visas brangenybes iš aukso; ir kiekvienas, kuris atnašavo, atnašavo VIEŠPAČIUI aukso atnašą.'),
  (@b2, 35, 23, 'Ir kiekvienas, pas kurį buvo rasta mėlyno, purpurinio, skaisčiai raudono, plono lino, ožkos šerių, raudonų avinų odų ir barsukų odų, tuos atnešė.'),
  (@b2, 35, 24, 'Visi, kurie atnašavo sidabro ir žalvario atnašą, atnešė VIEŠPATIES atnašą; ir kiekvienas, pas kurį buvo rasta šitimo medžio bet kokiam tarnavimo darbui, jį atnešė.'),
  (@b2, 35, 25, 'Ir visos išmintingos širdies moterys verpė savo rankomis ir atnešė tai, ką nuverpė iš mėlyno, iš purpurinio, iš skaisčiai raudono ir plono lino.'),
  (@b2, 35, 26, 'Ir visos moterys, savo širdžių pažadintos išminčiai, verpė ožkų šerius.'),
  (@b2, 35, 27, 'O valdovai atnešė onikso akmenų ir akmenų – kad būtų įstatyti – efodui ir krūtinės skydeliui;'),
  (@b2, 35, 28, 'kvepalų ir aliejaus apšvietimui, patepimo aliejui ir kvapiems smilkalams.'),
  (@b2, 35, 29, 'Izraelio vaikai, kiekvienas vyras ir moteris, kurių širdys padarė juos laisvanoriškais, kad atneštų visokiam darbui, kurį VIEŠPATS buvo įsakęs atlikti per Mozės ranką, atnešė laisvanorišką atnašą VIEŠPAČIUI.'),
  (@b2, 35, 30, 'Ir Mozė tarė Izraelio vaikams: „Štai VIEŠPATS pašaukė vardu Becalelį, Hūro sūnaus Ūrio sūnų iš Judos genties;'),
  (@b2, 35, 31, 'ir jis pripildė jį Dievo Dvasia, išmintimi, supratimu, pažinimu ir visokiu meistriškumu;'),
  (@b2, 35, 32, 'kad sugalvotų dailių darbų, kad dirbtų iš aukso, sidabro ir žalvario,'),
  (@b2, 35, 33, 'ir akmenų pjaustyme, kad juos įstatytų, ir medžio pjaustyme, kad atliktų bet kokį sumanų darbą.'),
  (@b2, 35, 34, 'Ir jis jam įdėjo į širdį, kad jis mokytų, tiek jis, tiek Ahisamacho sūnus Oholiabas iš Dano genties.'),
  (@b2, 35, 35, 'Juos jis pripildė širdies išmintimi, kad atliktų visokį darbą raižytojo, sumanaus darbininko bei siuvinėtojo mėlynu, purpuriniu, skaisčiai raudonu bei plonu linu, ir audėjo, iš atliekančių visokį darbą ir iš sugalvojančių sumanų darbą“.'),
  (@b2, 36, 1, 'Tada dirbo Becalelis, Oholiabas ir visi išmintingos širdies žmonės, į kuriuos VIEŠPATS įdėjo išmintį ir supratimą, kad žinotų, kaip atlikti visokį darbą šventovės tarnavimui, pagal visa, ką VIEŠPATS buvo įsakęs.'),
  (@b2, 36, 2, 'Ir Mozė pasišaukė Becalelį, Oholiabą ir visus išmintingos širdies žmones, į kurių širdis VIEŠPATS buvo įdėjęs išmintį – visus, kurie buvo savo širdies pažadinti ateiti prie darbo, kad jį atliktų;'),
  (@b2, 36, 3, 'ir jie ėmė iš Mozės visą atnašą, kurią Izraelio vaikai buvo atnešę šventovės tarnystės darbui, kad ją padarytų. Ir jie kas rytą vis jam tebenešė laisvos valios atnašas.'),
  (@b2, 36, 4, 'Ir visi išmintingi vyrai, kurie dirbo visą šventovės darbą, atėjo kiekvienas vyras nuo savo darbo, kurį darė;'),
  (@b2, 36, 5, 'ir jie kalbėjo Mozei, sakydami: „Tauta atneša daug daugiau, negu reikia tarnavimui darbo, kurį VIEŠPATS įsakė atlikti“.'),
  (@b2, 36, 6, 'Ir Mozei įsakius, jie liepė tai paskelbti po visą stovyklą, sakant: „Nei vyras, nei moteris daugiau tenedaro darbo šventovės atnašai“. Taip tauta buvo sulaikyta, kad nebeneštų.'),
  (@b2, 36, 7, 'Nes medžiagos, kurios jie turėjo, užteko visam darbui, kad jį darytų, ir per daug.'),
  (@b2, 36, 8, 'Ir visi išmintingos širdies vyrai tarp dirbančiųjų padangtės darbą, padarė dešimt uždangalų iš plono sukto lino, mėlyno, purpurinio ir skaisčiai raudono; juos padarė su sumanaus darbo kerubais.'),
  (@b2, 36, 9, 'Vieno uždangalo ilgis buvo dvidešimt aštuonios uolektys, o vieno uždangalo plotis – keturios uolektys; visi uždangalai buvo vienodo dydžio.'),
  (@b2, 36, 10, 'Ir jis sujungė penkis uždangalus vieną su kitu; ir kitus penkis uždangalus jis sujungė vieną su kitu.'),
  (@b2, 36, 11, 'Ir jis padarė kilpas iš mėlyno ant vieno uždangalo krašto, ant paties krašto, sujungime; taip pat jis padarė kito uždangalo tolimiausiame šone, antrojo sujungime.'),
  (@b2, 36, 12, 'Jis padarė penkiasdešimt kilpų viename uždangale ir penkiasdešimt kilpų jis padarė krašte uždangalo, esančio antrojo sujungime; tos kilpos laikė vieną uždangalą su kitu.'),
  (@b2, 36, 13, 'Ir jis padarė penkiasdešimt aukso kabių ir sujungė uždangalus vieną su kitu kabėmis; taip ji tapo viena padangte.'),
  (@b2, 36, 14, 'Ir jis padarė uždangalų iš ožkų šerių palapinei virš padangtės; jis padarė jų vienuolika uždangalų.'),
  (@b2, 36, 15, 'Vieno uždangalo ilgis buvo trisdešimt uolekčių, o vieno uždangalo plotis buvo keturios uolektys; tie vienuolika uždangalų buvo vienodo dydžio.'),
  (@b2, 36, 16, 'Ir jis atskirai sujungė penkis uždangalus ir atskirai šešis uždangalus.'),
  (@b2, 36, 17, 'Ir jis padarė penkiasdešimt kilpų ant tolimiausio uždangalo krašto, sujungime, ir penkiasdešimt kilpų jis padarė ant krašto uždangalo, kuris sujungia antrąjį.'),
  (@b2, 36, 18, 'Ir jis padarė penkiasdešimt žalvario kabių palapinei sujungti, kad ji būtų viena.'),
  (@b2, 36, 19, 'Ir jis padarė palapinei apdangalą iš raudonai dažytų avinų odų, ir barsukų odų apdangalą virš jo.'),
  (@b2, 36, 20, 'Ir jis padarė padangtei stovinčias lentas iš šitimo medžio.'),
  (@b2, 36, 21, 'Lentos ilgis buvo dešimt uolekčių, o lentos plotis – pusantros uolekties.'),
  (@b2, 36, 22, 'Viena lenta turėjo du dygius, vienodai nutolusius vienas nuo kito; šitaip jis padarė visoms padangtės lentoms.'),
  (@b2, 36, 23, 'Ir jis padarė lentas padangtei: dvidešimt lentų pietiniam šonui pietų link;'),
  (@b2, 36, 24, 'ir jis padarė keturiasdešimt sidabro movų po dviem dešimtimis lentų: dvi movos po viena lenta jos dviems dygiams ir dvi movos po kita lenta jos dviems dygiams.'),
  (@b2, 36, 25, 'Ir kitam padangtės šonui, esančiam šiaurinio krašto link, jis padarė dvidešimt lentų,'),
  (@b2, 36, 26, 'ir jų keturiasdešimt sidabro movų: dvi movas po viena lenta ir dvi movas po kita lenta.'),
  (@b2, 36, 27, 'O padangtės šonams vakarų link jis padarė šešias lentas.'),
  (@b2, 36, 28, 'Ir jis padarė dvi lentas padangtės kampams dviejuose šonuose.'),
  (@b2, 36, 29, 'O jos buvo sujungtos apačioje ir sujungtos pačiame jų viršuje, prie vieno žiedo; šitaip jis padarė joms abiems abiejuose kampuose.'),
  (@b2, 36, 30, 'Ir buvo aštuonios lentos; o jų movų buvo šešiolika sidabro movų, dvi movos po kiekviena lenta.'),
  (@b2, 36, 31, 'Ir jis padarė skersinius iš šitimo medžio: penkis vieno padangtės šono lentoms,'),
  (@b2, 36, 32, 'penkis skersinius kito padangtės šono lentoms ir penkis skersinius padangtės lentoms, šonams vakarų link.'),
  (@b2, 36, 33, 'Ir jis padarė vidurinį skersinį perkišimui per lentas nuo vieno galo iki kito.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b2, 36, 34, 'Ir lentas jis padengė auksu ir jų žiedus padarė iš aukso, kad būtų vieta skersiniams, ir padengė skersinius auksu.'),
  (@b2, 36, 35, 'Ir jis padarė uždangą iš mėlyno, purpurinio, skaisčiai raudono bei plono sukto lino; jis padarė ją sumaniu darbu su kerubais.'),
  (@b2, 36, 36, 'Ir jis jai padarė keturis šitimo medžio stulpus ir juos padengė auksu; jų kabliai buvo iš aukso; ir jis jiems nuliejo keturias sidabro movas.'),
  (@b2, 36, 37, 'Ir jis padarė padangtės durims užuolaidą iš mėlyno, purpurinio, skaisčiai raudono bei plono sukto lino, siuvinėto darbo;'),
  (@b2, 36, 38, 'ir jos penkis stulpus su jų kabliais; ir jis padengė auksu jų kapitelius ir jų apvadus; bet jų penkios movos buvo iš žalvario.'),
  (@b2, 37, 1, 'Ir Becalelis padarė iš šitimo medžio skrynią; jos ilgis – dvi su puse uolekties, jos plotis – pusantros uolekties, ir pusantros uolekties jos aukštis;'),
  (@b2, 37, 2, 'ir jis padengė ją grynu auksu iš vidaus ir iš išorės, ir jai aplinkui padarė auksinį vainiką.'),
  (@b2, 37, 3, 'Ir jis nuliejo jai keturis aukso žiedus, kad būtų pritvirtinti prie jos keturių kampų: du žiedus prie jos vieno šono ir du žiedus prie jos kito šono.'),
  (@b2, 37, 4, 'Ir jis padarė kartis iš šitimo medžio ir jas padengė auksu.'),
  (@b2, 37, 5, 'Ir jis įkišo kartis į žiedus prie skrynios šonų, skryniai nešioti.'),
  (@b2, 37, 6, 'Ir jis padarė gailestingumo krasę iš gryno aukso; jos ilgis buvo dvi su puse uolekties, o jos plotis pusantros uolekties.'),
  (@b2, 37, 7, 'Ir jis padarė du kerubus iš aukso, jis padarė juos nukaltus iš vieno gabalo, abiejuose gailestingumo krasės galuose:'),
  (@b2, 37, 8, 'vieną kerubą prie vieno galo šioje pusėje, o kitą kerubą prie kito galo anoje pusėje; iš gailestingumo krasės jis padarė kerubus prie abiejų jos galų.'),
  (@b2, 37, 9, 'O kerubai išskėtė savo sparnus aukštyn, apdengė savo sparnais gailestingumo krasę, savo veidais vienas į kitą; kerubų veidai buvo gailestingumo krasės link.'),
  (@b2, 37, 10, 'Ir jis padarė stalą iš šitimo medžio: jo ilgis buvo dvi uolektys, jo plotis – uolektis, ir jo aukštis – pusantros uolekties;'),
  (@b2, 37, 11, 'ir jis padengė jį grynu auksu ir ant jo aplinkui padarė aukso vainiką.'),
  (@b2, 37, 12, 'Taip pat jis padarė ant jo aplinkui plaštakos pločio briauną; ir jo briaunai aplinkui padarė aukso vainiką.'),
  (@b2, 37, 13, 'Ir jis nuliejo jam keturis aukso žiedus ir pritvirtino žiedus prie keturių kampų, kurie buvo prie keturių jo kojų.'),
  (@b2, 37, 14, 'Prie briaunos buvo žiedai, vietos kartims, stalui nešioti.'),
  (@b2, 37, 15, 'Ir jis padarė kartis iš šitimo medžio ir jas padengė auksu, stalui nešioti.'),
  (@b2, 37, 16, 'Ir jis padarė iš gryno aukso indus, esančius ant stalo: jo lėkštes, jo šaukštus, jo dubenis ir jo dangčius jų uždengimui.'),
  (@b2, 37, 17, 'Ir jis padarė žvakidę iš gryno aukso; jis padarė žvakidę kaltinio darbo: jos stiebas, jos šaka, jos taurelės, jos buoželės ir jos gėlės buvo iš to paties;'),
  (@b2, 37, 18, 'o šešios šakos ėjo iš jos šonų: trys žvakidės šakos iš vieno jos šono ir trys žvakidės šakos iš kito jos šono;'),
  (@b2, 37, 19, 'trys taurelės, panašios į migdolus, buoželė ir gėlė – vienoje šakoje; ir trys taurelės, panašios į migdolus, buoželė ir gėlė – kitoje šakoje; taip šešiose šakose, išeinančiose iš žvakidės.'),
  (@b2, 37, 20, 'O ant žvakidės buvo keturios taurelės, panašios į migdolus, jos buoželės ir jos gėlės;'),
  (@b2, 37, 21, 'buoželė po dviem šakom iš to paties, buoželė po dviem šakom iš to paties ir buoželė po dviem šakom iš to paties, pagal šešias, iš jos išeinančias šakas.'),
  (@b2, 37, 22, 'Jų buoželės ir jų šakos buvo iš to paties; ji visa buvo vienas kaltinis darbas iš gryno aukso.'),
  (@b2, 37, 23, 'Ir jis padarė jos septynis žibintus, jos gnybtuvus ir jos dubenėlius nuognaiboms iš gryno aukso.'),
  (@b2, 37, 24, 'Iš talento gryno aukso jis padarė ją ir visus jos indus.'),
  (@b2, 37, 25, 'Ir jis padarė smilkalų aukurą iš šitimo medžio; jo ilgis buvo uolektis ir jo plotis uolektis; jis buvo kvadratinis; ir jo aukštis buvo dvi uolektys; jo ragai buvo iš to paties.'),
  (@b2, 37, 26, 'Ir jis padengė jį grynu auksu: jo viršų, jo šonus aplinkui ir jo ragus; taip pat jis padarė jam aplinkui aukso vainiką.'),
  (@b2, 37, 27, 'Ir jis padarė jam du aukso žiedus po jo vainiku, prie abiejų jo kampų, ant abiejų jo šonų, kad būtų vietomis kartims, kad jomis jį nešiotų.'),
  (@b2, 37, 28, 'Ir jis padarė kartis iš šitimo medžio ir jas padengė auksu.'),
  (@b2, 37, 29, 'Ir vaistininko darbu jis padarė šventą patepimo aliejų ir grynus gardžių kvapų smilkalus.'),
  (@b2, 38, 1, 'Ir jis padarė deginamosios atnašos aukurą iš šitimo medžio: jo ilgis buvo penkios uolektys, o jo plotis – penkios uolektys; jis buvo kvadratinis; ir jo aukštis – trys uolekys.'),
  (@b2, 38, 2, 'Ir jis padarė jo ragus prie keturių jo kampų; jo ragai buvo iš to paties; ir jis padengė jį žalvariu.'),
  (@b2, 38, 3, 'Ir jis padarė visus aukuro indus: puodus, semtuvus, dubenis, šakutes mėsai ir indus žarijoms; visus jo indus jis padarė iš žalvario.'),
  (@b2, 38, 4, 'Ir jis padarė aukurui žalvarines tinklines groteles po jo ribomis apačioje iki jo vidurio.'),
  (@b2, 38, 5, 'Ir keturiems žalvario grotelių galams nuliejo keturis žiedus – vietas kartims.'),
  (@b2, 38, 6, 'Ir jis padarė kartis iš šitimo medžio ir jas padengė žalvariu.'),
  (@b2, 38, 7, 'Ir jis įkišo kartis į žiedus ant aukuro šonų, kad jomis jį nešiotų; jis padarė aukurą tuščiavidurį iš lentų.'),
  (@b2, 38, 8, 'Ir jis padarė žalvario praustuvę ir jos koją iš žalvario, iš veidrodžių tų susirenkančių moterų, kurios susirinkdavo prie susirinkimo padangtės durų.'),
  (@b2, 38, 9, 'Ir jis padarė kiemą: pietiniame šone, pietų link, kiemo užuolaidos buvo iš plono sukto lino – šimtas uolekčių;'),
  (@b2, 38, 10, 'jų stulpų buvo dvidešimt ir jų žalvarinių movų dvidešimt; stulpų kabliai ir jų apvadai buvo iš sidabro.'),
  (@b2, 38, 11, 'Ir šiauriniam šonui užuolaidos buvo šimto uolekčių, jų stulpų buvo dvidešimt ir jų žalvario movų dvidešimt; stulpų kabliai ir jų apvadai iš sidabro.'),
  (@b2, 38, 12, 'O vakariniam šonui užuolaidos buvo penkiasdešimties uolekčių, jų stulpų dešimt ir jų movų dešimt; stulpų kabliai ir jų apvadai iš sidabro.'),
  (@b2, 38, 13, 'Ir rytiniam šonui rytų link – penkiasdešimties uolekčių.'),
  (@b2, 38, 14, 'Vienos vartų pusės užuolaidos buvo penkiolikos uolekčių; jų stulpai trys ir jų movos trys.'),
  (@b2, 38, 15, 'Ir kitai kiemo vartų pusei, šiapus ir anapus, buvo penkiolikos uolekčių užuolaidos; jų stulpai trys ir jų movos trys.'),
  (@b2, 38, 16, 'Visos kiemo užuolaidos aplink buvo iš plono sukto lino.'),
  (@b2, 38, 17, 'O movos stulpams buvo iš žalvario; stulpų kabliai ir jų apvadai iš sidabro; ir jų kapitelių apdangalas iš sidabro; ir visi kiemo stulpai buvo apjuosti sidabro apvadais.'),
  (@b2, 38, 18, 'O užuolaida kiemo vartams buvo siuvinėto darbo iš mėlyno, purpurinio, skaisčiai raudono ir plono susukto lino; dvidešimt uolekčių buvo ilgis, ir aukštis platume buvo penkios uolektys, atitinkanti kiemo užuolaidas.'),
  (@b2, 38, 19, 'O jų stulpai buvo keturi ir jų movos iš žalvario keturios; jų kabliai iš sidabro ir jų kapitelių apdangalas ir jų apvadai iš sidabro.'),
  (@b2, 38, 20, 'Ir visi padangtės ir kiemo aplinkui kuolai buvo iš žalvario.'),
  (@b2, 38, 21, 'Šis yra susumavimas padangtės, Liudijimo padangtės, kaip buvo paskaičiuota pagal Mozės įsakymą levitų tarnavimui, ranka Itamaro, sūnaus kunigui Aaronui.'),
  (@b2, 38, 22, 'Ir Hūro sūnaus Ūrio sūnus Becalelis iš Judos genties padarė viską, ką VIEŠPATS įsakė Mozei.'),
  (@b2, 38, 23, 'O su juo buvo Ahisamacho sūnus Oholiabas iš Dano genties, raižytojas, sumanus darbininkas ir siuvinėtojas iš mėlyno, purpurinio, skaisčiai raudono ir plono lino.'),
  (@b2, 38, 24, 'Viso aukso, panaudoto darbui visame šventosios vietos darbe, būtent atnašavimo aukso, buvo dvidešimt devyni talentai ir septyni šimtai trisdešimt šekelių, pagal šventovės šekelį.'),
  (@b2, 38, 25, 'O iš susirinkimo suskaičiuotųjų sidabro buvo šimtas talentų ir tūkstantis septyni šimtai septyniasdešimt penki šekeliai, pagal šventovės šekelį:'),
  (@b2, 38, 26, 'beka, tai yra pusė šekelio, iš kiekvieno, pagal šventovės šekelį, iš visų ėjusiųjų, kad būtų suskaičiuoti, nuo dvidešimties metų ir daugiau, iš šešių šimtų trijų tūkstančių penkių šimtų penkiasdešimties žmonių.'),
  (@b2, 38, 27, 'Ir iš šimto sidabro talentų buvo nulietos šventovės movos ir uždangos movos; šimtas movų iš šimto talentų, talentas movai.'),
  (@b2, 38, 28, 'O iš tūkstančio septynių šimtų septyniasdešimt penkių šekelių jis padarė kablius stulpams, padengė jų kapitelius ir juos apjuosė apvadais.'),
  (@b2, 38, 29, 'O atnašavimo žalvario buvo septyniasdešimt talentų ir du tūkstančiai keturi šimtai šekelių.'),
  (@b2, 38, 30, 'Iš to jis padarė movas susirinkimo padangtės durims, žalvarinį aukurą, jam žalvarines groteles, visus aukuro indus,'),
  (@b2, 38, 31, 'aplinkui einančio kiemo movas ir kiemo vartų movas, visus padangtės kuolus ir visus kiemo kuolus aplinkui.'),
  (@b2, 39, 1, 'Ir iš mėlyno, purpurinio ir skaisčiai raudono jie padarė tarnavimo drabužius, kad atliktų tarnavimą šventojoje vietoje, ir padarė šventus drabužius Aaronui; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 2, 'Ir jis padarė efodą iš aukso, mėlyno, purpurinio, skaisčiai raudono ir iš plono susukto lino.'),
  (@b2, 39, 3, 'Ir jie išplojo auksą į plonus lakštus ir supjaustė juos į gijas, kad sumaniu darbu įaustų jas į mėlyną, purpurinį, skaisčiai raudoną ir į ploną liną.'),
  (@b2, 39, 4, 'Jie jam padarė perpetes, kad jį sujungtų; abiem kraštais jis buvo sujungtas.'),
  (@b2, 39, 5, 'Ir jo efodo dailioji juosta, esanti ant to, buvo iš to paties, vienodo darbo; iš aukso, mėlyno, purpurinio, skaisčiai raudono ir plono susukto lino; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 6, 'Ir jie apdirbo onikso akmenis, įtaisytus į aukso lizdus, su Izraelio vaikų vardais išraižytus, kaip yra išraižomi antspaudai.'),
  (@b2, 39, 7, 'Ir jis pritvirtino juos prie efodo pečių, kad jie būtų akmenimis atminimui Izraelio vaikams; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 8, 'Ir jis padarė krūtinės skydelį, sumanaus darbo, kaip efodo darbo; iš aukso, mėlyno, purpurinio, skaisčiai raudono ir plono susukto lino.'),
  (@b2, 39, 9, 'Jis buvo kvadratinis; jie padarė krūtinės skydelį dvilinką; jo ilgis – sprindis, ir jo plotis – sprindis, jis buvo dvilinkas.'),
  (@b2, 39, 10, 'Ir jie įstatė į jį keturias akmenų eiles: pirmoji eilė buvo sardis, topazas ir raudonasis granatas – tai pirmoji eilė.'),
  (@b2, 39, 11, 'O antroji eilė: smaragdas, safyras ir deimantas.'),
  (@b2, 39, 12, 'O trečioji eilė: liguras, agatas ir ametistas.'),
  (@b2, 39, 13, 'O ketvirtoji eilė: berilas, oniksas ir jaspis; jie buvo įtverti į aukso lizdus jų įtvaruose.'),
  (@b2, 39, 14, 'O tų akmenų buvo pagal Izraelio vaikų vardus – dvylika – pagal jų vardus, kaip antspaudo išraižymai, kiekvienas su savo vardu pagal dvylika genčių.'),
  (@b2, 39, 15, 'Ir ant krūtinės skydelio, galuose, jie padarė gryno aukso, pinto darbo grandinėles.'),
  (@b2, 39, 16, 'Ir jie padarė du aukso lizdus bei du aukso žiedus; ir pritvirtino abu žiedus prie abiejų krūtinės skydelio galų.'),
  (@b2, 39, 17, 'Ir jie įkišo abi pintas aukso grandinėles į abu žiedus prie krūtinės skydelio galų.'),
  (@b2, 39, 18, 'O abiejų pintų grandinėlių abu galus jie pritvirtino prie abiejų lizdų ir jas pritvirtino prie efodo perpečių priešais jį.'),
  (@b2, 39, 19, 'Ir jie padarė du aukso žiedus ir juos pritvirtino prie abiejų krūtinės skydelio galų, prie to jo krašto, kuris buvo ant efodo pusės, nukreiptos vidun.'),
  (@b2, 39, 20, 'Ir jie padarė kitus du auksinius žiedus ir juos pritvirtino prie abiejų efodo šonų apačioje, iš priekinės pusės, priešais kitą jo sujungimą, virš efodo dailiosios juostos.'),
  (@b2, 39, 21, 'Ir jie pririšo krūtinės skydelį jo žiedais prie efodo žiedų su raiščiu iš mėlyno, kad jis būtų virš dailiosios efodo juostos, ir kad krūtinės skydelis neatsilaisvintų nuo efodo; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 22, 'Ir jis padarė efodo apsiaustą austinio darbo, visą iš mėlyno.'),
  (@b2, 39, 23, 'O apsiausto viduryje buvo anga, kaip šarvo anga su apvadu aplinkui angą, kad nesuplyštų.'),
  (@b2, 39, 24, 'O prie apsiausto apsiuvų jie padarė granatus iš mėlyno, purpurinio, skaisčiai raudono ir susukto lino.'),
  (@b2, 39, 25, 'Ir jie padarė gryno aukso varpelius, ir pritvirtino varpelius tarp granatų prie apsiausto apsiuvo, tarp granatų aplinkui:'),
  (@b2, 39, 26, 'varpelis ir granatas, varpelis ir granatas aplinkui apsiuvą apsiausto, kad tarnautų jame; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 27, 'Ir jie padarė plono lino apsiaustus, austinio darbo, Aaronui ir jo sūnums,'),
  (@b2, 39, 28, 'plono lino mitrą, gražias plono lino kepures, linines plono susukto lino kelnes,'),
  (@b2, 39, 29, 'siuvinėto darbo juostą iš plono sukto lino, mėlyno, purpurinio ir skaisčiai raudono; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 30, 'Ir jie padarė šventojo vainiko plokštelę iš gryno aukso ir ant jos užrašė raštą, panašų į antspaudo išraižymą: „ŠVENTENYBĖ VIEŠPAČIUI“.'),
  (@b2, 39, 31, 'Ir jie pririšo prie jos raištį iš mėlyno, kad ją pritvirtintų viršuje prie mitros; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 39, 32, 'Taip buvo baigtas visas susirinkimo palapinės padangtės darbas; ir Izraelio vaikai padarė pagal visa tai, ką VIEŠPATS įsakė Mozei, jie taip padarė.'),
  (@b2, 39, 33, 'Ir jie atnešė padangtę Mozei: palapinę ir visus jos reikmenis: jos kabes, jos lentas, jos skersinius, jos stulpus ir jos movas,'),
  (@b2, 39, 34, 'raudonai dažytų avinų odų apdangalą, barsukų odų apdangalą ir apdengiančią uždangą,'),
  (@b2, 39, 35, 'Liudijimo skrynią, jos kartis ir gailestingumo krasę,'),
  (@b2, 39, 36, 'stalą, visus jo indus ir parodomąją duoną,'),
  (@b2, 39, 37, 'gryną žvakidę su jos žibintais, tai yra, su žibintais, kad būtų sustatyti pagal tvarką, visus jos įrankius ir aliejų šviesai,'),
  (@b2, 39, 38, 'auksinį aukurą, patepimo aliejų, kvapius smilkalus ir užuolaidą padangtės durims,'),
  (@b2, 39, 39, 'žalvarinį aukurą, jo žalvarines groteles, jo kartis ir visus jo indus, praustuvę ir jos koją,'),
  (@b2, 39, 40, 'kiemo užuolaidas, jo stulpus, jo movas, užuolaidą kiemo vartams, jo virves, jo kuolus ir visus padangtės tarnavimo reikmenis susirinkimo palapinei,'),
  (@b2, 39, 41, 'tarnavimo drabužius, kad tarnautų šventojoje vietoje, šventus drabužius kunigui Aaronui ir jo sūnų drabužius, kad tarnautų kunigo tarnyboje.'),
  (@b2, 39, 42, 'Pagal visa, ką VIEŠPATS įsakė Mozei, taip Izraelio vaikai atliko visą darbą.'),
  (@b2, 39, 43, 'Ir Mozė apžiūrėjo visą darbą, ir štai jie buvo jį atlikę, kaip VIEŠPATS buvo įsakęs, taip jie buvo tai atlikę; ir Mozė palaimino juos.'),
  (@b2, 40, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b2, 40, 2, '„Pirmojo mėnesio pirmąją dieną pastatyk susirinkimo palapinės padangtę.'),
  (@b2, 40, 3, 'Ir padėk joje Liudijimo skrynią ir apdenk skrynią uždanga.'),
  (@b2, 40, 4, 'Ir įnešk stalą ir sudėk pagal tvarką dalykus, kurie turi būti ant jo sudėti pagal tvarką; ir įnešk žvakidę ir uždek jos žibintus.'),
  (@b2, 40, 5, 'Ir pastatyk aukso aukurą smilkalams prieš Liudijimo skrynią ir pakabink padangtei durų užuolaidą.'),
  (@b2, 40, 6, 'Ir pastatyk deginamosios atnašos aukurą prieš susirinkimo palapinės padangtės duris.'),
  (@b2, 40, 7, 'Ir tarp susirinkimo palapinės ir aukuro pastatyk praustuvę ir įpilk į ją vandens.'),
  (@b2, 40, 8, 'Ir išstatyk kiemą aplinkui ir pakabink ant kiemo vartų užuolaidą.'),
  (@b2, 40, 9, 'Ir paėmęs patepimo aliejaus, patepk padangtę ir visa, kas yra joje, ir pašvęsk ją bei visus jos įrankius; ir tai bus šventa.'),
  (@b2, 40, 10, 'Ir patepk deginamosios atnašos aukurą bei visus jo indus, ir pašvęsk aukurą; ir jis bus švenčiausias aukuras.'),
  (@b2, 40, 11, 'Ir patepk praustuvę bei jos koją ir tai pašvęsk.'),
  (@b2, 40, 12, 'Ir atvesk Aaroną ir jo sūnus prie susirinkimo padangtės durų ir apiplauk juos vandeniu.'),
  (@b2, 40, 13, 'Ir apvilk Aaroną šventais drabužiais, patepk jį ir jį pašvęsk; kad jis man tarnautų kunigo tarnyboje.'),
  (@b2, 40, 14, 'Ir atvesk jo sūnus ir juos apvilk apsiaustais;'),
  (@b2, 40, 15, 'ir juos patepk, kaip patepei jų tėvą, kad jie man tarnautų kunigo tarnyboje; nes jų patepimas tikrai bus amžina kunigystė per jų kartas“.'),
  (@b2, 40, 16, 'Taip padarė Mozė: pagal visa, ką VIEŠPATS jam įsakė, jis taip padarė.'),
  (@b2, 40, 17, 'Ir įvyko, kad pirmąjį mėnesį, antraisiais metais, to mėnesio pirmąją dieną, buvo pastatyta padangtė.'),
  (@b2, 40, 18, 'Ir Mozė pastatė padangtę, pritvirtino jos movas, sustatė jos lentas, įkišo jos skersinius ir sustatė jos stulpus.'),
  (@b2, 40, 19, 'Ir jis ištiesė ant padangtės palapinę ir uždėjo viršuje ant jos palapinės apdangalą; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 20, 'Ir paėmęs jis įdėjo liudijimą į skrynią, pritaisė prie skrynios kartis ir viršuje ant skrynios uždėjo gailestingumo krasę;'),
  (@b2, 40, 21, 'ir jis įnešė skrynią į padangtę, pakabino apdengimo uždangą ir apdengė Liudijimo skrynią; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 22, 'Ir jis padėjo stalą susirinkimo palapinėje, padangtės šone į šiaurę, uždangos išorėje.'),
  (@b2, 40, 23, 'O ant jo jis sudėjo duoną pagal tvarką VIEŠPATIES akivaizdoje; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 24, 'Ir jis padėjo žvakidę susirinkimo palapinėje priešais stalą, padangtės šone pietų link.'),
  (@b2, 40, 25, 'Ir jis uždegė žibintus VIEŠPATIES akivaizdoje; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 26, 'Ir jis padėjo auksinį aukurą susirinkimo palapinėje prieš uždangą;'),
  (@b2, 40, 27, 'ir jis degino ant jo kvapius smilkalus; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 28, 'Ir jis pakabino užuolaidą ant padangtės durų.'),
  (@b2, 40, 29, 'Ir jis padėjo deginamosios atnašos aukurą prie susirinkimo palapinės padangtės durų ir ant jo atnašavo deginamąją atnašą ir maisto atnašą; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 30, 'Ir jis pastatė praustuvę tarp susirinkimo palapinės ir aukuro ir į ją įpylė vandens nusiplovimui.'),
  (@b2, 40, 31, 'Ir Mozė, Aaronas ir jo sūnūs joje plovė savo rankas ir savo kojas;'),
  (@b2, 40, 32, 'įėję į susirinkimo palapinę ir priartėję prie aukuro, jie nusiplaudavo; kaip VIEŠPATS įsakė Mozei.'),
  (@b2, 40, 33, 'Ir jis pastatė kiemą aplink padangtę bei aukurą ir užkabino kiemo vartų užuolaidą. Taip Mozė užbaigė darbą.'),
  (@b2, 40, 34, 'Tada debesis apdengė susirinkimo palapinę, ir VIEŠPATIES šlovė pripildė padangtę.'),
  (@b2, 40, 35, 'Ir Mozė negalėjo įeiti į susirinkimo palapinę, nes ant jos pasiliko debesis, ir VIEŠPATIES šlovė pripildė padangtę.'),
  (@b2, 40, 36, 'Ir kai debesis būdavo pakeltas nuo padangtės viršaus, Izraelio vaikai eidavo toliau į visas savo keliones;'),
  (@b2, 40, 37, 'bet jei debesis nepakildavo, tuomet jie nekeliaudavo iki tos dienos, kuomet jis pakildavo.'),
  (@b2, 40, 38, 'Nes VIEŠPATIES debesis dieną būdavo ant padangtės, o naktį ant jos būdavo ugnis visų Izraelio namų akyse per visas jų keliones.'),
  (@b3, 1, 1, 'Ir VIEŠPATS pašaukė Mozę ir jam kalbėjo iš susirinkimo padangtės, sakydamas:'),
  (@b3, 1, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Jei kas iš jūsų neš atnašą VIEŠPAČIUI, tai atneškite savo atnašą iš galvijų, būtent iš bandos ir iš kaimenės.'),
  (@b3, 1, 3, 'Jei jo atnaša bus deginamoji auka iš bandos, jis teatnašauja patiną be trūkumų; jis teatnašauja jį savo paties laisva valia prie susirinkimo padangtės durų VIEŠPATIES akivaizdoje.'),
  (@b3, 1, 4, 'Ir jis uždės savo ranką ant deginamosios atnašos galvos; ir ta bus priimta dėl jo, sutaikinimui už jį atlikti.'),
  (@b3, 1, 5, 'Ir jis papjaus jautuką VIEŠPATIES akivaizdoje; o Aarono sūnūs, kunigai, atneš kraują ir šlakstys kraują aplinkui ant aukuro, esančio prie susirinkimo padangtės durų.'),
  (@b3, 1, 6, 'Ir jis nulups odą deginamajai atnašai ir ją sukapos į jos gabalus.'),
  (@b3, 1, 7, 'O kunigo Aarono sūnūs sukurs ugnį ant aukuro ir išklos malkas ant ugnies;'),
  (@b3, 1, 8, 'ir Aarono sūnūs, kunigai, išguldys dalis, galvą ir taukus ant malkų, esančių ant ugnies, kuri yra ant aukuro;'),
  (@b3, 1, 9, 'bet jos vidurius ir jos kojas jis nuplaus vandenyje; ir kunigas viską sudegins ant aukuro, kad būtų deginamoji auka, gardaus kvapo ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 1, 10, 'O jeigu jo atnaša būtų iš kaimenių, būtent iš avių ar ožkų, deginamajai aukai, jis teatneš patiną be trūkumų.'),
  (@b3, 1, 11, 'Ir jis papjaus jį aukuro pusėje šiaurės link, VIEŠPATIES akivaizdoje; o Aarono sūnūs, kunigai, šlakstys jo kraują aplinkui ant aukuro.'),
  (@b3, 1, 12, 'Ir jis sukapos jį į jo gabalus su jo galva ir jo taukais; o kunigas juos išguldys ant malkų, esančių ant ugnies, kuri yra ant aukuro;'),
  (@b3, 1, 13, 'bet vidurius ir kojas jis nuplaus vandeniu; ir kunigas visa tai atneš ir sudegins ant aukuro; tai yra deginamoji auka, gardaus kvapo ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 1, 14, 'O jei deginamoji auka jo atnašai VIEŠPAČIUI būtų iš skrajūnų, tuomet jis atneš savo atnašą iš purplelių ar jaunų karvelių.'),
  (@b3, 1, 15, 'O kunigas atneš jį prie aukuro, nusuks jam galvą ir sudegins jį ant aukuro; o jo kraujas bus išsunktas prie aukuro šono;'),
  (@b3, 1, 16, 'ir jis ištrauks jo gūžį su jo plunksnomis ir numes tai šalia aukuro rytinėje dalyje prie pelenų vietos;'),
  (@b3, 1, 17, 'ir jis perskels jį su jo sparnais, bet jo nepadalins pusiau; o kunigas sudegins jį ant aukuro, ant malkų, esančių ant ugnies; tai yra deginamoji auka, ugnies atnaša, kaip gardus kvapas VIEŠPAČIUI.'),
  (@b3, 2, 1, 'Ir jei kas norės atnašauti maisto atnašą VIEŠPAČIUI, jo atnaša bus smulkių miltų; ir jis užpils ant jos aliejaus ir uždės ant jos smilkalų;'),
  (@b3, 2, 2, 'ir jis ją nuneš Aarono sūnums, kunigams; ir jis iš jos paims pilną saują iš jos miltų ir iš jos aliejaus su visais jos smilkalais; ir kunigas sudegins ant aukuro jos atminimą, kad būtų ugnies atnaša, kaip gardus kvapas VIEŠPAČIUI;'),
  (@b3, 2, 3, 'o maisto atnašos likutis bus Aarono ir jo sūnų; tai yra švenčiausias dalykas iš VIEŠPATIES ugnies atnašų.'),
  (@b3, 2, 4, 'O jei neši auką maisto atnašos, keptos krosnyje, tai bus nerauginti pyragai smulkių miltų, sumaišytų su aliejumi, arba nerauginti papločiai, patepti aliejumi.'),
  (@b3, 2, 5, 'O jei tavo auka bus skardoje kepta maisto atnaša, ji bus neraugintų smulkių miltų, sumaišytų su aliejumi.'),
  (@b3, 2, 6, 'Padalink ją į gabaliukus ir ant jos užpilk aliejaus; tai yra maisto atnaša.'),
  (@b3, 2, 7, 'O jei tavo auka bus keptuvėje kepta maisto atnaša, ji bus pagaminta iš smulkių miltų su aliejumi.'),
  (@b3, 2, 8, 'Ir atnešk maisto atnašą, kuri yra pagaminta iš tų dalykų, VIEŠPAČIUI; o kai ji bus įteikta kunigui, jis ją nuneš prie aukuro.'),
  (@b3, 2, 9, 'Ir kunigas paims iš maisto atnašos jos atminimą ir sudegins tai ant aukuro; tai yra gardaus kvapo ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 2, 10, 'O tai, kas palieka iš maisto atnašos, bus Aarono ir jo sūnų; tai yra švenčiausia šventenybė iš VIEŠPATIES ugnies atnašų.'),
  (@b3, 2, 11, 'Jokia maisto atnaša, kurią atnešite VIEŠPAČIUI, nebus gaminama su raugu; nes jūs nedeginsite jokio raugo nei jokio medaus jokioje VIEŠPATIES ugnies atnašoje.'),
  (@b3, 2, 12, 'O dėl pirmavaisių aukos, atnašaukite juos VIEŠPAČIUI; bet jie nebus deginami ant aukuro gardžiam kvapui.'),
  (@b3, 2, 13, 'Ir kiekvieną savo maisto atnašos auką paskanink druska; taip pat neleisk, kad tavo maisto atnašai stigtų tavo Dievo sandoros druskos; su visomis savo atnašomis atnašauk druską.'),
  (@b3, 2, 14, 'O jei atnašausi VIEŠPAČIUI maisto atnašą iš savo pirmavaisių, atnašauk maisto atnašai iš savo pirmavaisių žalias, ugnimi išdžiovintas javų varpas, tai yra, grūdus, iškultus iš pilnų varpų.'),
  (@b3, 2, 15, 'Ir užpilk ant jos aliejaus ir uždėk ant jos smilkalų; tai yra maisto atnaša.'),
  (@b3, 2, 16, 'O kunigas sudegins jos atminimą, jos iškultų grūdų dalį ir jos aliejaus dalį su visais jos smilkalais; tai yra ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 3, 1, 'O jei jo auka būtų auka taikos atnašos, jei jis ją atnašaus iš bandos; ar tai būtų patinas ar patelė, jis ją atnašaus neturinčią trūkumų VIEŠPATIES akivaizdoje.'),
  (@b3, 3, 2, 'Ir jis uždės savo ranką ant savo atnašos galvos ir ją papjaus prie susirinkimo padangtės durų; o Aarono sūnūs, kunigai, šlakstys kraują aplinkui ant aukuro.'),
  (@b3, 3, 3, 'Ir jis atnašaus ugnies atnašą VIEŠPAČIUI iš taikos atnašos aukos; taukus, kurie apdengia vidurius, ir visus taukus, esančius ant vidurių,'),
  (@b3, 3, 4, 'abu inkstus ir ant jų esančius taukus, kurie yra prie strėnų, ir virš kepenų esančią taukinę su inkstais – jis tai išims.'),
  (@b3, 3, 5, 'O Aarono sūnūs tai sudegins ant aukuro, ant deginamosios aukos, esančios ant malkų, kurios yra ant ugnies; tai yra ugnies atnaša, kaip gardus kvapas VIEŠPAČIUI.'),
  (@b3, 3, 6, 'O jei jo atnaša – taikos atnašos aukai VIEŠPAČIUI – bus iš kaimenės; jis atnašaus patiną ar patelę, neturinčią trūkumų.'),
  (@b3, 3, 7, 'Jei jis atnašaus avinėlį kaip savo atnašą, tada jis jį atnašaus VIEŠPATIES akivaizdoje.'),
  (@b3, 3, 8, 'Ir jis uždės savo ranką ant savo atnašos galvos ir ją papjaus prieš susirinkimo padangtę; o Aarono sūnūs šlakstys jos kraują aplinkui ant aukuro.'),
  (@b3, 3, 9, 'Ir jis atnašaus iš taikos atnašos aukos ugnies atnašą VIEŠPAČIUI; jos taukus, visą pasturgalį, prie pat nugarkaulio jis tai išims; ir taukus, kurie apdengia vidurius, bei visus taukus, esančius ant vidurių,'),
  (@b3, 3, 10, 'abu inkstus, ant jų esančius taukus, kurie yra prie strėnų, ir virš kepenų esančią taukinę su inkstais – jis tai išims.'),
  (@b3, 3, 11, 'O kunigas tai sudegins ant aukuro; tai yra ugnies atnašos maistas VIEŠPAČIUI.'),
  (@b3, 3, 12, 'O jei jo atnaša bus ožka, tada jis ją atnašaus VIEŠPATIES akivaizdoje.'),
  (@b3, 3, 13, 'Ir jis uždės savo ranką ant jos galvos ir ją papjaus prieš susirinkimo padangtę; o Aarono sūnūs šlakstys jos kraują aplinkui ant aukuro.'),
  (@b3, 3, 14, 'Ir jis atnašaus iš jos savo atnašą, ugnies atnašą VIEŠPAČIUI; taukus, kurie apdengia vidurius, ir visus taukus, esančius ant vidurių,'),
  (@b3, 3, 15, 'abu inkstus, ant jų esančius taukus, kurie yra prie strėnų, ir virš kepenų esančią taukinę su inkstais – jis tai išims.'),
  (@b3, 3, 16, 'O kunigas juos sudegins ant aukuro; tai yra maistas ugnies atnašos gardžiam kvapui; visi taukai yra VIEŠPATIES.'),
  (@b3, 3, 17, 'Tai bus amžinas įstatas jūsų kartoms visose jūsų buveinėse, kad jūs nevalgysite nei taukų, nei kraujo’“.'),
  (@b3, 4, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 4, 2, '„Kalbėk Izraelio vaikams, sakydamas: ‘Jei siela dėl nežinojimo nusidės prieš bet kurį iš VIEŠPATIES įsakymų dėl dalykų, kurių nereikėtų daryti, ir padarys prieš kurį nors vieną iš jų;'),
  (@b3, 4, 3, 'jei kunigas, kuris yra pateptas, nusidės pagal tautos nuodėmę; tada jis už savo nuodėmę, kuria nusidėjo, teatveda jauniklį jautuką be trūkumų VIEŠPAČIUI kaip nuodėmės atnašą.'),
  (@b3, 4, 4, 'Ir jis atves jautuką prie susirinkimo padangtės durų VIEŠPATIES akivaizdon; ir uždės savo ranką ant jautuko galvos ir papjaus jautuką VIEŠPATIES akivaizdoje.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b3, 4, 5, 'Ir kunigas, kuris yra pateptas, paims jautuko kraujo ir jį įneš į susirinkimo padangtę;'),
  (@b3, 4, 6, 'ir kunigas pamirkys savo pirštą kraujyje ir šlakstys kraujo septynis kartus VIEŠPATIES akivaizdoje priešais šventovės uždangą.'),
  (@b3, 4, 7, 'Ir kunigas uždės VIEŠPATIES akivaizdoje dalį kraujo ant ragų kvapniųjų smilkalų aukuro, esančio susirinkimo padangtėje; o visą jautuko kraują išlies apačioje deginamosios atnašos aukuro, esančio prie susirinkimo padangtės durų.'),
  (@b3, 4, 8, 'Ir jis išims iš jo visus jautuko taukus nuodėmės atnašai; taukus, kurie apdengia vidurius, ir visus taukus, esančius ant vidurių,'),
  (@b3, 4, 9, 'abu inkstus, ant jų esančius taukus, kurie yra prie strėnų, ir virš kepenų esančią taukinę su inkstais – jis tai išims,'),
  (@b3, 4, 10, 'kaip tai buvo išimama iš taikos atnašos aukos jautuko; o kunigas juos sudegins ant deginamosios atnašos aukuro.'),
  (@b3, 4, 11, 'O jautuko odą, visą jo mėsą su jo galva ir jo kojomis, jo vidurius ir jo mėšlus –'),
  (@b3, 4, 12, 'visą jautuką jis išgabens už stovyklos į švarią vietą, kur yra išpilami pelenai, ir jį sudegins ugnimi ant malkų; jis bus sudegintas, kur yra išpilami pelenai.'),
  (@b3, 4, 13, 'O jei visas Izraelio susirinkimas nusidės dėl nežinojimo, ir tas dalykas liks paslėptas nuo susirinkimo akių, ir jei jie bus padarę kažką prieš bet kurį iš VIEŠPATIES įsakymų dėl dalykų, kurių neturėtų daryti, ir bus kalti;'),
  (@b3, 4, 14, 'kai nuodėmė, kuria jie nusidėjo prieš jį, yra žinoma, tuomet susirinkimas atnašaus už nuodėmę jauniklį jautuką ir jį atves prieš susirinkimo padangtę.'),
  (@b3, 4, 15, 'O susirinkimo vyresnieji uždės savo rankas ant jautuko galvos VIEŠPATIES akivaizdoje; ir jautukas bus papjautas VIEŠPATIES akivaizdoje.'),
  (@b3, 4, 16, 'O kunigas, kuris yra pateptas, atneš jautuko kraujo į susirinkimo padangtę;'),
  (@b3, 4, 17, 'ir kunigas pamirkys savo pirštą dalyje kraujo ir šlakstys jį septynis kartus VIEŠPATIES akivaizdoje, prieš uždangą.'),
  (@b3, 4, 18, 'Ir jis uždės dalį kraujo ant ragų aukuro, esančio VIEŠPATIES akivaizdoje, susirinkimo padangtėje, o visą kraują išlies apačioje deginamosios atnašos aukuro, esančio prie susirinkimo padangtės durų.'),
  (@b3, 4, 19, 'O visus jo taukus jis iš jo išims ir sudegins ant aukuro.'),
  (@b3, 4, 20, 'Ir jis padarys su jautuku, kaip jis padarė su jautuku nuodėmės atnašai; taip jis padarys su šituo; o kunigas atliks sutaikinimą už juos, ir jiems bus atleista.'),
  (@b3, 4, 21, 'Ir jis išgabens jautuką už stovyklos ir jį sudegins, kaip jis sudegino pirmąjį jautuką; tai yra nuodėmės atnaša už susirinkimą.'),
  (@b3, 4, 22, 'Kai valdovas nusidės, dėl nežinojimo padarydamas kažką prieš bet kurį iš VIEŠPATIES, jo Dievo, įsakymų dėl dalykų, kurių neturėtų daryti, ir bus kaltas;'),
  (@b3, 4, 23, 'arba jeigu jo nuodėmė, kuria jis nusidėjo, taps jam žinoma, jis atgabens savo atnašą, ožiuką, patiną be trūkumų;'),
  (@b3, 4, 24, 'ir jis uždės savo ranką ant ožio galvos ir jį papjaus toje vietoje, kur jie pjauna deginamąją atnašą VIEŠPATIES akivaizdoje; tai yra nuodėmės atnaša.'),
  (@b3, 4, 25, 'O kunigas paims savo pirštu nuodėmės atnašos kraujo ir jo uždės ant deginamosios atnašos aukuro ragų, o jo kraują išlies deginamosios atnašos aukuro apačioje.'),
  (@b3, 4, 26, 'O visus jo taukus jis sudegins ant aukuro, kaip taikos atnašų aukos taukus; ir kunigas atliks sutaikinimą už jį dėl jo nuodėmės, ir ji jam bus atleista.'),
  (@b3, 4, 27, 'O jei kuris iš paprastų žmonių nusidės dėl nežinojimo, darydamas kažką prieš bet kurį iš VIEŠPATIES įsakymų dėl dalykų, kurių neturėtų daryti, ir bus kaltas;'),
  (@b3, 4, 28, 'arba jeigu jo nuodėmė, kuria jis nusidėjo, taps jam žinoma; tuomet jis atgabens savo atnašą, ožiuką, patelę be trūkumų, už savo nuodėmę, kuria jis nusidėjo.'),
  (@b3, 4, 29, 'Ir jis uždės savo ranką ant nuodėmės atnašos galvos ir papjaus nuodėmės atnašą deginamosios atnašos vietoje.'),
  (@b3, 4, 30, 'O kunigas paims savo pirštu jos kraujo ir jo uždės ant deginamosios atnašos aukuro ragų, o visą jos kraują išlies aukuro apačioje.'),
  (@b3, 4, 31, 'Ir jis išims visus jos taukus, kaip yra pašalinami taukai iš taikos atnašų aukos; ir kunigas tai sudegins ant aukuro dėl gardaus kvapo VIEŠPAČIUI; ir kunigas atliks sutaikinimą už jį, ir jam bus atleista.'),
  (@b3, 4, 32, 'O jei jis atneš avinėlį nuodėmės atnašai, jis atneš patelę be trūkumų.'),
  (@b3, 4, 33, 'Ir jis uždės savo ranką ant nuodėmės atnašos galvos ir ją papjaus nuodėmės atnašai toje vietoje, kur jie pjauna deginamąją atnašą.'),
  (@b3, 4, 34, 'O kunigas paims savo pirštu nuodėmės atnašos kraujo ir jo uždės ant deginamosios atnašos aukuro ragų, o visą jos kraują išlies aukuro apačioje;'),
  (@b3, 4, 35, 'ir jis išims visus jos taukus, kaip yra išimami avinėlio taukai iš taikos atnašų aukos; o kunigas sudegins juos ant aukuro, pagal ugnies atnašas VIEŠPAČIUI; ir kunigas atliks sutaikinimą už jo padarytą nuodėmę, ir jam bus atleista.'),
  (@b3, 5, 1, 'O jei siela nusidėtų išgirdusi keikimo balsą, ir yra liudytoja, ar tai būtų mačiusi, ar žinojusi apie tai; jei ji to nepasakys, tada ji nešios savo neteisybę.'),
  (@b3, 5, 2, 'Arba jei siela palies bet kokį nešvarų dalyką, ar tai būtų nešvaraus žvėries lavonas, ar nešvaraus galvijo lavonas, ar nešvarių ropojančių padarų lavonas, ir jei tai būtų nuo jos paslėpta; ji taip pat bus nešvari ir kalta.'),
  (@b3, 5, 3, 'Arba jeigu ji palies žmogaus nešvarumą, koks tai bebūtų nešvarumas, kuriuo žmogus susiteps, ir tai nuo jos būtų paslėpta; kai ji apie tai sužinos, tada ji bus kalta.'),
  (@b3, 5, 4, 'Arba jei siela prisiekia, tardama savo lūpomis daryti pikta ar gera, kas tai bebūtų, ką žmogus ištars su priesaika, ir tai nuo jos būtų paslėpta; kai ji apie tai sužinos, tuomet ji bus kalta vienu iš jų.'),
  (@b3, 5, 5, 'Ir bus, kad kai ji bus kalta vienu iš tų dalykų, ji turės išpažinti, kad ji tuo dalyku nusidėjo;'),
  (@b3, 5, 6, 'ir ji atgabens savo nusižengimo atnašą VIEŠPAČIUI už savo nuodėmę, kuria ji nusidėjo, patelę iš kaimenės, avelę ar ožkytę, nuodėmės atnašai; o kunigas atliks sutaikinimą už ją dėl jos nuodėmės.'),
  (@b3, 5, 7, 'O jei ji nepajėgs atgabenti avinėlio, tuomet už savo nusižengimą, kurį ji padarė, atneš du purplelius arba du jaunus karvelius VIEŠPAČIUI; vieną nuodėmės atnašai, o kitą deginamajai atnašai.'),
  (@b3, 5, 8, 'Ir ji juos atneš pas kunigą, kuris pirma atnašaus tą, kuris yra nuodėmės atnašai, ir nusuks jam galvą nuo jo kaklo, bet nedalins jo pusiau;'),
  (@b3, 5, 9, 'ir jis šlakstys nuodėmės atnašos kraujo ant aukuro šono; o likęs kraujas bus išsunktas prie aukuro apačios; tai yra nuodėmės atnaša.'),
  (@b3, 5, 10, 'O antrąjį atnašaus deginamajai atnašai pagal paprotį; o kunigas atliks sutaikinimą už ją dėl jos nuodėmės, kuria ji nusidėjo, ir jai bus atleista.'),
  (@b3, 5, 11, 'Bet jei ji nepajėgs atnešti dviejų purplelių arba dviejų jaunų karvelių, tuomet ta, kuri nusidėjo, atneš kaip savo atnašą dešimtą dalį efos smulkių miltų kaip nuodėmės atnašą; ji neužpils ant jos aliejaus nei uždės ant jos jokių smilkalų; nes tai yra nuodėmės atnaša.'),
  (@b3, 5, 12, 'Tada ji nuneš tai kunigui, o kunigas paims iš to pilną saują, to atminimą, ir sudegins tai ant aukuro pagal ugnies atnašas VIEŠPAČIUI; tai yra nuodėmės atnaša.'),
  (@b3, 5, 13, 'Ir kunigas atliks sutaikinimą už ją dėl jos nuodėmės, kuria ji nusidėjo vienu iš šitų, ir jai bus atleista; o likutis bus kunigo, kaip maisto atnaša’“.'),
  (@b3, 5, 14, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 5, 15, '„Jei siela nusižengs ir nusidės dėl nežinojimo šventuose VIEŠPATIES dalykuose; tada ji atneš už savo nusižengimą VIEŠPAČIUI aviną be trūkumų iš kaimenių, tavo įvertinimu sidabro šekeliais, pagal šventyklos šekelį, nusižengimo atnašai;'),
  (@b3, 5, 16, 'ir ji atlygins už žalą, kurią ji padarė šventame dalyke, ir prie to pridės penktąją dalį ir tai duos kunigui; o kunigas atliks sutaikinimą už ją nusižengimo atnašos avinu, ir jai bus atleista.'),
  (@b3, 5, 17, 'O jei siela nusidės ir padarys bet kurį iš tų dalykų, kurie yra uždrausti daryti VIEŠPATIES įsakymų; nors ji to ir nežinotų, tačiau ji bus kalta, ir nešios savo neteisybę.'),
  (@b3, 5, 18, 'Ir ji atneš kunigui iš kaimenės aviną be trūkumų, tavo įvertinimu, nusižengimo atnašai; o kunigas atliks sutaikinimą už ją dėl jos nežinojimo, kuo ji klydo ir to nežinojo, ir jai bus atleista.'),
  (@b3, 5, 19, 'Tai yra nusižengimo atnaša; ji tikrai yra nusižengusi prieš VIEŠPATĮ“.'),
  (@b3, 6, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 6, 2, '„Jei siela nusidės ir nusižengs prieš VIEŠPATĮ, ir meluos savo artimui dėl to, kas buvo jai duota saugoti, ar dėl bendravimo, ar dėl prievarta atimto dalyko, ar apgaudinėjo savo artimą;'),
  (@b3, 6, 3, 'ar rado ką pamesta, o apie tai melavo ir melagingai prisiekė; bet kuriuo iš visų tų, ką žmogus daro tuo nusidėdamas;'),
  (@b3, 6, 4, 'tuomet, kadangi ji nusidėjo ir yra kalta, ji sugrąžins tai, ką ji prievarta atėmė, ar tai, ką apgaule įsigijo, ar tai, kas buvo jai duota saugoti, ar pamestą daiktą, kurį ji rado,'),
  (@b3, 6, 5, 'ar visa tai, apie ką ji melagingai prisiekė; ji sugrąžins tai pilnai ir prie to dar pridės penktąją dalį, ir tai duos tam, kuriam tai priklauso, savo nusižengimo atnašos dieną.'),
  (@b3, 6, 6, 'Ir ji atneš savo nusižengimo atnašą VIEŠPAČIUI – iš kaimenės, neturintį trūkumų aviną, tavo įvertinimu, kaip nusižengimo atnašą – kunigui;'),
  (@b3, 6, 7, 'o kunigas atliks sutaikinimą už ją VIEŠPATIES akivaizdoje; ir jai bus atleista už viską, ką ji yra padariusi tame nusižengdama“.'),
  (@b3, 6, 8, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 6, 9, '„Įsakyk Aaronui ir jo sūnums, sakydamas: ‘Šitas yra deginamosios atnašos įstatymas: Tai yra deginamoji atnaša dėl to, kad dega ant aukuro visą naktį iki ryto, ir aukuro ugnis degs jame.'),
  (@b3, 6, 10, 'Ir kunigas apsivilks savo lininiu drabužiu ir užsimaus savo linines kelnes ant savo kūno ir išims pelenus deginamosios atnašos, kurią ant aukuro suėdė ugnis, ir jis padės juos šalia aukuro.'),
  (@b3, 6, 11, 'Ir jis nusivilks savo drabužius, apsivilks kitais drabužiais ir išneš pelenus už stovyklos į švarią vietą.'),
  (@b3, 6, 12, 'O ant aukuro ugnis jame degs; ji nebus užgesinta; ir kunigas kiekvieną rytą degins ant jo malkas ir sudėlios ant jo deginamąją atnašą; ir jis degins ant jo taikos atnašų riebalus.'),
  (@b3, 6, 13, 'Ugnis visada degs ant aukuro; ji niekada neužges.'),
  (@b3, 6, 14, 'O šitas yra maisto atnašos įstatymas: Aarono sūnūs ją atnašaus VIEŠPATIES akivaizdoje, prieš aukurą.'),
  (@b3, 6, 15, 'Ir jis paims iš jos saują, iš maisto atnašos miltų bei iš jos aliejaus ir visus smilkalus, esančius ant maisto atnašos, ir sudegins tai ant aukuro gardžiam kvapui, jos atminimą VIEŠPAČIUI.'),
  (@b3, 6, 16, 'O jos likutį suvalgys Aaronas ir jo sūnūs; tai bus valgoma su nerauginta duona šventojoje vietoje; susirinkimo padangtės kieme jie ją valgys.'),
  (@b3, 6, 17, 'Tai nebus kepama su raugu. Aš tai daviau jiems kaip jų dalį iš mano ugnies atnašų; tai yra švenčiausia, kaip nuodėmės atnaša ir kaip nusižengimo atnaša.'),
  (@b3, 6, 18, 'Kiekvienas vyriškos lyties tarp Aarono vaikų tai valgys. Tai bus amžinas įstatas jūsų kartose dėl VIEŠPATIES ugnies atnašų; kas tik jas palies, tas bus šventas’“.'),
  (@b3, 6, 19, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 6, 20, '„Ta yra Aarono ir jo sūnų atnaša, kurią jie atnašaus VIEŠPAČIUI tą dieną, kai jis bus pateptas: dešimtąją dalį efos smulkių miltų nuolatinei maisto atnašai, pusę jos ryte ir pusę jos naktį.'),
  (@b3, 6, 21, 'Skardoje ji bus paruošta su aliejumi; ir kai ji bus iškepta, tu ją įnešk; ir iškeptus maisto atnašos gabaliukus atnašauk kaip gardų kvapą VIEŠPAČIUI.'),
  (@b3, 6, 22, 'Kunigas, kuris iš jo sūnų bus pateptas jo vietoje, ją atnašaus; tai amžinas įstatas VIEŠPAČIUI; ji bus visa sudeginta.'),
  (@b3, 6, 23, 'Nes kiekviena maisto atnaša kunigui bus visiškai sudeginta; ji nebus valgoma’“.'),
  (@b3, 6, 24, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 6, 25, '„Kalbėk Aaronui ir jo sūnums, sakydamas: ‘Tas yra nuodėmės atnašos įstatymas: Toje vietoje, kur pjaunama deginamoji atnaša, bus pjaunama nuodėmės atnaša VIEŠPATIES akivaizdoje; ji yra švenčiausia.'),
  (@b3, 6, 26, 'Kunigas, kuris ją atnašauja už nuodėmę, ją valgys; ji bus valgoma šventojoje vietoje, susirinkimo padangtės kieme.'),
  (@b3, 6, 27, 'Visa, kas palies jos mėsą, bus šventa; ir kai apsitaškys jos kraujo ant kokio drabužio, išplauk tai, ant ko buvo aptaškyta, šventojoje vietoje.'),
  (@b3, 6, 28, 'Bet molinis indas, kuriame ji buvo virta, bus sudaužytas; o jei ji būtų virta žalvariniame puode, jis bus iššveistas ir išskalautas vandenyje.'),
  (@b3, 6, 29, 'Kiekvienas vyriškos lyties tarp kunigų jos valgys; ji yra švenčiausia.'),
  (@b3, 6, 30, 'Bet jokia nuodėmės atnaša, kurios kiek nors kraujo yra įnešta į susirinkimo padangtę, kad juo sutaikintų šventojoje vietoje, nebus valgoma; ji bus sudeginta ugnyje.'),
  (@b3, 7, 1, 'Taip pat šitas yra įstatymas nusižengimo atnašos; ji yra švenčiausia.'),
  (@b3, 7, 2, 'Toje vietoje, kur jie papjauna deginamąją auką, jie papjaus nusižengimo atnašą; ir jos kraują šlakstys aplinkui ant aukuro.'),
  (@b3, 7, 3, 'Ir jis atnašaus iš jos visus jos taukus; pasturgalį ir taukus, kurie apdengia vidurius,'),
  (@b3, 7, 4, 'abu inkstus, ant jų esančius taukus, kurie yra prie strėnų, ir virš kepenų esančią taukinę su inkstais – jis tai išims;'),
  (@b3, 7, 5, 'ir kunigas juos sudegins ant aukuro kaip ugnies atnašą VIEŠPAČIUI; tai yra nusižengimo atnaša.'),
  (@b3, 7, 6, 'Kiekvienas vyriškos lyties tarp kunigų jos valgys; ji bus valgoma šventojoje vietoje; ji yra švenčiausia.'),
  (@b3, 7, 7, 'Kaip yra nuodėmės atnaša, taip yra ir nusižengimo atnaša; joms yra vienas įstatymas; kunigas, kuris jomis atlieka sutaikinimą, jas gaus.'),
  (@b3, 7, 8, 'O kunigas, kuris atnašauja kieno nors deginamąją atnašą, tas kunigas galės sau turėti odą deginamosios atnašos, kurią jis atnašavo.'),
  (@b3, 7, 9, 'O visa maisto atnaša, kepama krosnyje, ir visa, kas paruošta keptuvėje ir skardoje, bus kunigo, kuris tai atnašauja.'),
  (@b3, 7, 10, 'O kiekvieną maisto atnašą, sumaišytą su aliejumi ir sausą, gaus Aarono sūnūs, vienas tiek pat, kiek kitas.'),
  (@b3, 7, 11, 'O šis yra įstatymas taikos atnašų aukos, kurią kas atnašaus VIEŠPAČIUI.'),
  (@b3, 7, 12, 'Jei kas ją atnašaus padėkai, tuomet su padėkos auka jis atnašaus neraugintus pyragus, sumaišytus su aliejumi, neraugintus papločius, pateptus aliejumi, ir keptus smulkių miltų pyragus, sumaišytus su aliejumi.'),
  (@b3, 7, 13, 'Neskaitant pyragų, kaip savo atnašą jis atnašaus raugintą duoną su savo taikos atnašų padėkos auka.'),
  (@b3, 7, 14, 'O iš to jis atnašaus vieną iš visos aukos kaip iškeliamąją atnašą VIEŠPAČIUI, ir tai gaus kunigas, kuris šlaksto taikos atnašų kraują.'),
  (@b3, 7, 15, 'O jo taikos atnašų aukos mėsa padėkai bus valgoma tą pačią dieną, kai ji yra atnašaujama; nieko iš jos jis nepaliks iki ryto.'),
  (@b3, 7, 16, 'Bet jei jo atnašos auka būtų įžadas ar savanoriška atnaša, ji bus valgoma tą pačią dieną, kai jis atnašauja savo auką; o rytojaus dieną ir jos likutis bus suvalgytas;'),
  (@b3, 7, 17, 'bet aukos mėsos likutis trečiąją dieną bus sudegintas ugnimi.'),
  (@b3, 7, 18, 'O jei trečiąją dieną kaip nors bus valgoma jo taikos atnašų aukos mėsos, ji nebus priimtina, ir ji nebus įskaityta tam, kuris ją atnašauja; ji bus pasibjaurėjimas, o siela, kuri jos valgo, nešios savo neteisybę.'),
  (@b3, 7, 19, 'O mėsa, kuri prisiliečia prie ko nors nešvaraus, nebus valgoma; ji bus sudeginta ugnimi; o dėl mėsos, kiekvienas švarus galės jos valgyti.'),
  (@b3, 7, 20, 'Bet siela, kuri valgys taikos atnašų aukos mėsos, skirtos VIEŠPAČIUI, turinti ant savęs savo nešvarumą, ta siela bus iškirsta iš savo tautos.'),
  (@b3, 7, 21, 'Be to, siela, kuri palies ką nors nešvaraus, kaip žmogaus nešvarumą ar kokį nešvarų gyvulį, ar kokią pasibjaurėtiną nešvarybę, ir valgys VIEŠPAČIUI priklausančios taikos atnašų aukos mėsos, ta siela bus iškirsta iš savo tautos’“.'),
  (@b3, 7, 22, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 7, 23, '„Kalbėk Izraelio vaikams, sakydamas: ‘Nevalgykite jokių jaučio ar avies, ar ožkos taukų.'),
  (@b3, 7, 24, 'O nustipusio gyvulio taukai ir žvėrių sudraskytojo taukai gali būti panaudojami bet kuriam kitam reikalui; bet jokiu būdu jų nevalgykite.'),
  (@b3, 7, 25, 'Nes kiekvienas, kuris valgys taukus gyvulio, iš kurio kas nors atnašauja ugnies atnašą VIEŠPAČIUI, ta siela, kuri tai valgys, bus iškirsta iš savo tautos.'),
  (@b3, 7, 26, 'Be to, jokiose jūsų buveinėse nevalgykite jokio kraujo, ar tai būtų skrajūnų, ar gyvulių.'),
  (@b3, 7, 27, 'Kokia bebūtų siela, kuri valgys kokio nors kraujo, ta siela bus iškirsta iš savo tautos’“.'),
  (@b3, 7, 28, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 7, 29, '„Kalbėk Izraelio vaikams, sakydamas: ‘Tas, kuris atnašauja savo taikos atnašų auką VIEŠPAČIUI, atneš savo auką VIEŠPAČIUI iš savo taikos atnašų aukos.'),
  (@b3, 7, 30, 'Jo paties rankos atneš VIEŠPATIES ugnies atnašas, taukus su krūtine, tai jis turės atnešti, kad krūtinė būtų mosuojama kaip mosuojamoji atnaša VIEŠPATIES akivaizdoje.'),
  (@b3, 7, 31, 'Ir kunigas sudegins taukus ant aukuro; bet krūtinė bus Aarono ir jo sūnų.'),
  (@b3, 7, 32, 'O dešinįjį petį duosite kunigui kaip iškeliamąją atnašą iš savo taikos atnašų aukų.'),
  (@b3, 7, 33, 'Tas, kuris iš Aarono sūnų atnašauja taikos atnašų kraują ir taukus, tas gaus dešinįjį petį savo daliai.'),
  (@b3, 7, 34, 'Nes mosuojamąją krūtinę ir iškeliamąjį petį aš paėmiau iš Izraelio vaikų, iš jų taikos atnašų aukų, ir juos daviau kunigui Aaronui ir jo sūnums iš Izraelio vaikų tarpo amžinu įstatu’“.'),
  (@b3, 7, 35, 'Ta yra Aarono patepimo ir jo sūnų patepimo dalis iš VIEŠPATIES ugnies atnašų tą dieną, kai jis pristatė juos tarnauti VIEŠPAČIUI kunigo tarnyboje;'),
  (@b3, 7, 36, 'kurią VIEŠPATS įsakė jiems duoti iš Izraelio vaikų tą dieną, kai jis juos patepė, amžinu įstatu per jų kartas.'),
  (@b3, 7, 37, 'Šis yra įstatymas deginamosios atnašos, maisto atnašos, nuodėmės atnašos, nusižengimo atnašos, įšventinimų ir taikos atnašų aukos;'),
  (@b3, 7, 38, 'kurias VIEŠPATS įsakė Mozei Sinajaus kalne tą dieną, kai jis įsakė Izraelio vaikams atnašauti jų aukas VIEŠPAČIUI Sinajaus dykumoje.'),
  (@b3, 8, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 8, 2, '„Paimk Aaroną ir jo sūnus su juo, drabužius, patepimo aliejų, jautuką nuodėmės atnašai, du avinus ir pintinę neraugintos duonos;'),
  (@b3, 8, 3, 'ir surink visą susirinkimą prie susirinkimo padangtės durų“.'),
  (@b3, 8, 4, 'Ir Mozė padarė, kaip VIEŠPATS jam įsakė; ir susirinkimas susirinko prie susirinkimo padangtės durų.'),
  (@b3, 8, 5, 'Ir Mozė tarė susirinkimui: „Štai ką VIEŠPATS įsakė, kad būtų padaryta“.'),
  (@b3, 8, 6, 'Ir Mozė atvedė Aaroną bei jo sūnus ir juos nuplovė vandeniu.'),
  (@b3, 8, 7, 'Ir jis apvilko jį apdaru, apjuosė jį juosta, užvilko jam apsiaustą, uždėjo ant jo efodą, apjuosė jį efodo dailiąja juosta ir tąja pririšo jį prie jo.'),
  (@b3, 8, 8, 'Ir jis uždėjo ant jo krūtinės skydelį; taip pat įdėjo į krūtinės skydelį Urimą ir Tumimą.'),
  (@b3, 8, 9, 'Ir jis uždėjo jam ant galvos mitrą; taip pat ant mitros, ant jo galvos priekio, jis uždėjo auksinę plokštelę, šventąjį vainiką; kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 8, 10, 'Ir Mozė ėmė patepimo aliejų, patepė padangtę bei viską, kas buvo joje, ir juos pašventė.'),
  (@b3, 8, 11, 'Ir septynis kartus šlakstė jį ant aukuro ir patepė aukurą bei visus jo įrankius, tiek praustuvę, tiek jos koją, kad juos pašvęstų.'),
  (@b3, 8, 12, 'Ir jis užpylė patepimo aliejaus ant Aarono galvos ir jį patepė, kad jį pašvęstų.'),
  (@b3, 8, 13, 'Ir Mozė atvedė Aarono sūnus, juos apvilko apdarais, apjuosė juos juostomis ir uždėjo ant jų kepures; kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 8, 14, 'Ir jis atvedė jautuką nuodėmės atnašai; o Aaronas ir jo sūnūs uždėjo savo rankas ant nuodėmės atnašos jautuko galvos.'),
  (@b3, 8, 15, 'Ir jis papjovė jį; ir Mozė paėmė kraują, jo uždėjo savo pirštu aplinkui ant aukuro ragų ir apvalė aukurą, o kraują išliejo aukuro apačioje, ir jį pašventė, kad ant jo atliktų sutaikinimą.'),
  (@b3, 8, 16, 'Ir jis ėmė visus ant vidurių esančius taukus, taukinę virš kepenų, abu inkstus ir jų taukus, ir Mozė tai sudegino ant aukuro.'),
  (@b3, 8, 17, 'Bet jautuką, jo odą, jo mėsą ir jo mėšlą jis sudegino ugnimi už stovyklos; kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 8, 18, 'Ir jis atvedė aviną deginamajai atnašai; o Aaronas ir jo sūnūs uždėjo savo rankas ant avino galvos.'),
  (@b3, 8, 19, 'Ir jis papjovė jį; ir Mozė šlakstė kraują ant aukuro aplinkui.'),
  (@b3, 8, 20, 'Ir jis sukapojo aviną į gabalus; ir Mozė sudegino galvą, gabalus ir taukus.'),
  (@b3, 8, 21, 'Ir jis nuplovė vandenyje vidurius ir kojas; ir Mozė sudegino visą aviną ant aukuro; tai buvo deginamoji auka gardžiam kvapui ir ugnies atnaša VIEŠPAČIUI; kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 8, 22, 'Ir jis atvedė kitą aviną, įšventinimo aviną; o Aaronas ir jo sūnūs uždėjo savo rankas ant avino galvos.'),
  (@b3, 8, 23, 'Ir jis papjovė jį; ir Mozė paėmė jo kraujo ir uždėjo jo ant Aarono dešinės ausies galiuko, ant jo dešinės rankos nykščio ir ant jo dešinės kojos nykščio.'),
  (@b3, 8, 24, 'Ir jis atvedė Aarono sūnus, ir Mozė uždėjo kraujo ant jų dešiniųjų ausų galiukų, ant jų dešiniųjų rankų nykščių ir ant jų dešiniųjų kojų nykščių; ir Mozė šlakstė kraują ant aukuro aplinkui.'),
  (@b3, 8, 25, 'Ir jis ėmė taukus, pasturgalį, visus ant vidurių esančius taukus, taukinę virš kepenų, abu inkstus bei jų taukus ir dešinįjį petį;'),
  (@b3, 8, 26, 'ir iš neraugintos duonos pintinės, esančios VIEŠPATIES akivaizdoje, jis ėmė vieną neraugintą pyragą, aliejuotos duonos pyragą bei vieną paplotį ir juos uždėjo ant taukų ir ant dešinio peties;'),
  (@b3, 8, 27, 'ir jis viską uždėjo ant Aarono rankų bei jo sūnų rankų ir juos mosavo kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje.'),
  (@b3, 8, 28, 'Ir Mozė juos ėmė iš jų rankų ir sudegino juos ant aukuro virš deginamosios atnašos; jie buvo įšventinimai gardžiam kvapui; tai yra ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 8, 29, 'Ir Mozė ėmė krūtinę ir ją mosavo kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje; nes iš įšventinimo avino tai buvo Mozės dalis; kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 8, 30, 'Ir Mozė ėmė patepimo aliejaus ir ant aukuro esančio kraujo ir šlakstė tai ant Aarono ir jo drabužių, ant jo sūnų ir ant drabužių jo sūnų, esančių su juo; ir pašventė Aaroną ir jo drabužius, jo sūnus ir drabužius jo sūnų, esančių su juo.'),
  (@b3, 8, 31, 'Ir Mozė tarė Aaronui ir jo sūnums: „Virkite mėsą prie susirinkimo padangtės durų; ir ten valgykite ją su duona, esančia įšventinimų pintinėje, kaip aš įsakiau, sakydamas: ‘Aaronas ir jo sūnūs tai valgys’.'),
  (@b3, 8, 32, 'O tai, kas lieka nuo mėsos ir nuo duonos, sudeginkite ugnimi.'),
  (@b3, 8, 33, 'O jūs neišeikite nuo susirinkimo padangtės durų per septynias dienas, kol neužsibaigs jūsų įšventinimo dienos; nes jis šventins jus septynias dienas.'),
  (@b3, 8, 34, 'Kaip jis yra šią dieną padaręs, taip VIEŠPATS yra įsakęs daryti sutaikinimui už jus atlikti.'),
  (@b3, 8, 35, 'Todėl pasilikite prie susirinkimo padangtės durų septynias dienas, dieną ir naktį, ir laikykitės VIEŠPATIES įpareigojimo, kad nemirtumėte; nes taip man įsakyta“.'),
  (@b3, 8, 36, 'Taip Aaronas ir jo sūnūs padarė viską, ką VIEŠPATS įsakė per Mozės ranką.'),
  (@b3, 9, 1, 'Ir įvyko aštuntąją dieną, kad Mozė pašaukė Aaroną, jo sūnus bei Izraelio vyresniuosius;'),
  (@b3, 9, 2, 'ir jis tarė Aaronui: „Pasiimk jauną veršį nuodėmės atnašai ir aviną deginamajai atnašai, be trūkumų, ir atnašauk juos VIEŠPATIES akivaizdoje.'),
  (@b3, 9, 3, 'Ir kalbėk Izraelio vaikams, sakydamas: ‘Imkite ožiuką nuodėmės atnašai; ir veršį bei avinėlį, abejus pirmųjų metų, be trūkumų, deginamajai atnašai;'),
  (@b3, 9, 4, 'taip pat jautuką ir aviną taikos atnašoms, kad aukotumėte VIEŠPATIES akivaizdoje; ir maisto atnašą, sumaišytą su aliejumi; nes šiandien jums pasirodys VIEŠPATS’“.'),
  (@b3, 9, 5, 'Ir jie atgabeno tai, ką Mozė įsakė, priešais susirinkimo padangtę; ir visas susirinkimas prisiartino ir atsistojo VIEŠPATIES akivaizdoje.'),
  (@b3, 9, 6, 'Ir Mozė tarė: „Štai ką VIEŠPATS įsakė, kad jūs darytumėte; ir jums pasirodys VIEŠPATIES šlovė“.'),
  (@b3, 9, 7, 'Ir Mozė tarė Aaronui: „Eik prie aukuro ir atnašauk savo nuodėmės atnašą bei savo deginamąją atnašą, ir atlik sutaikinimą už save ir už tautą; ir atnašauk tautos atnašą ir atlik sutaikinimą už juos; kaip VIEŠPATS įsakė“.'),
  (@b3, 9, 8, 'Taigi Aaronas nuėjo prie aukuro ir papjovė nuodėmės atnašos veršį, kuris buvo už jį.'),
  (@b3, 9, 9, 'Ir Aarono sūnūs atnešė jam kraują; ir jis pamirkė savo pirštą kraujyje ir uždėjo jo ant aukuro ragų, o kraują išliejo aukuro apačioje;'),
  (@b3, 9, 10, 'bet nuodėmės atnašos taukus, inkstus ir taukinę virš kepenų jis sudegino ant aukuro; kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 9, 11, 'O mėsą ir odą jis sudegino ugnimi už stovyklos.'),
  (@b3, 9, 12, 'Ir jis papjovė deginamąją atnašą; o Aarono sūnūs pateikė jam kraują, kurį jis šlakstė aplinkui ant aukuro.'),
  (@b3, 9, 13, 'Ir jie pateikė jam deginamąją atnašą su jos gabalais ir galva; ir jis sudegino juos ant aukuro.'),
  (@b3, 9, 14, 'Ir jis nuplovė vidurius bei kojas ir juos sudegino ant deginamosios atnašos, ant aukuro.'),
  (@b3, 9, 15, 'Ir jis atgabeno tautos atnašą, paėmė ožį, kuris buvo nuodėmės atnaša už tautą, jį papjovė ir atnašavo jį už nuodėmę, kaip pirmąjį.'),
  (@b3, 9, 16, 'Ir jis atgabeno deginamąją atnašą ir ją atnašavo pagal paprotį.'),
  (@b3, 9, 17, 'Ir jis atnešė maisto atnašą, paėmė iš jos saują ir tai sudegino ant aukuro, neskaitant rytinės deginamosios aukos.'),
  (@b3, 9, 18, 'Taip pat jis papjovė jautuką ir aviną, kaip taikos atnašų auką, kuri buvo už tautą; o Aarono sūnūs jam pateikė kraują, kurį jis šlakstė aplinkui ant aukuro,'),
  (@b3, 9, 19, 'ir jautuko bei avino taukus, pasturgalį ir tai, kas uždengia vidurius, ir inkstus, ir taukinę virš kepenų;'),
  (@b3, 9, 20, 'ir jie uždėjo taukus ant krūtinių, ir jis sudegino taukus ant aukuro;'),
  (@b3, 9, 21, 'o krūtines ir dešinįjį petį Aaronas mosavo kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje; kaip Mozė įsakė.'),
  (@b3, 9, 22, 'Ir Aaronas pakėlė savo ranką į tautą, juos palaimino ir nulipo žemyn nuo nuodėmės atnašos, deginamosios atnašos ir taikos atnašų atnašavimo.'),
  (@b3, 9, 23, 'Ir Mozė bei Aaronas įėjo į susirinkimo padangtę ir išėję palaimino tautą; ir VIEŠPATIES šlovė pasirodė visai tautai.'),
  (@b3, 9, 24, 'Ir atėjo ugnis nuo VIEŠPATIES akivaizdos ir prarijo ant aukuro deginamąją atnašą ir taukus; tai pamačiusi, visa tauta šaukė ir parpuolė veidais žemyn.'),
  (@b3, 10, 1, 'O Nadabas ir Abihuvas, Aarono sūnūs, kiekvienas paėmė savo smilkytuvą, įdėjo į juos ugnies, uždėjo ant jos smilkalų ir atnašavo VIEŠPATIES akivaizdoje svetimą ugnį, ko jis nebuvo jiems įsakęs.'),
  (@b3, 10, 2, 'Ir išėjo nuo VIEŠPATIES ugnis ir juos prarijo, ir jie mirė VIEŠPATIES akivaizdoje.'),
  (@b3, 10, 3, 'Tada Mozė tarė Aaronui: „Tai yra tai, ką VIEŠPATS kalbėjo, sakydamas: ‘Aš būsiu pašvęstas tuose, kurie artinasi prie manęs, ir visos tautos akivaizdoje aš būsiu pašlovintas’“. O Aaronas tylėjo.'),
  (@b3, 10, 4, 'Ir Mozė pašaukė Mišaelį ir Elcafaną, Aarono dėdės Uzielio sūnus, ir jiems tarė: „Prieikite, išneškite savo brolius nuo šventyklos priekio už stovyklos“.'),
  (@b3, 10, 5, 'Taigi jie priėjo ir išnešė juos jų apdaruose už stovyklos; kaip Mozė buvo sakęs.'),
  (@b3, 10, 6, 'Ir Mozė tarė Aaronui ir jo sūnums Eleazarui ir Itamarui: „Neatsidenkite savo galvų nei nepersiplėškite savo drabužių; kad nemirtumėte ir kad rūstybė neateitų ant visos tautos; bet jūsų broliai, visi Izraelio namai, teapraudoja tą sudeginimą, kurį VIEŠPATS užkūrė.'),
  (@b3, 10, 7, 'Ir nenueikite nuo susirinkimo padangtės durų, kad nemirtumėte; nes VIEŠPATIES patepimo aliejus yra ant jūsų“. Ir jie padarė pagal Mozės žodį.'),
  (@b3, 10, 8, 'Ir VIEŠPATS kalbėjo Aaronui, sakydamas:'),
  (@b3, 10, 9, '„Negerk vyno ir stipraus gėrimo nei tu, nei tavo sūnūs su tavimi, kai įeinate į susirinkimo padangtę, kad nemirtumėte; tai bus amžinas įstatas per jūsų kartas;'),
  (@b3, 10, 10, 'ir kad skirtumėte tarp švento ir nešvento ir tarp nešvaraus ir švaraus;'),
  (@b3, 10, 11, 'ir kad mokytumėte Izraelio vaikus visų įstatų, kuriuos VIEŠPATS yra jiems kalbėjęs per Mozės ranką“.'),
  (@b3, 10, 12, 'Ir Mozė kalbėjo Aaronui ir Eleazarui bei Itamarui, jo išlikusiems sūnums: „Imkite maisto atnašą, atlikusią nuo VIEŠPATIES ugnies atnašų, ir ją valgykite neraugintą šalia aukuro; nes ji yra švenčiausia;'),
  (@b3, 10, 13, 'ir valgykite ją šventojoje vietoje, nes tai yra tavo dalis ir tavo sūnų dalis iš VIEŠPATIES ugnies aukų; nes taip man įsakyta.'),
  (@b3, 10, 14, 'O mosuojamąją krūtinę ir iškeliamąjį petį valgykite švarioje vietoje; tu ir tavo sūnūs bei tavo dukterys su tavimi; nes tie yra tavo dalis ir tavo sūnų dalis, kurie yra duoti iš Izraelio vaikų taikos atnašų aukų.'),
  (@b3, 10, 15, 'Iškeliamąjį petį ir mosuojamąją krūtinę jie atneš su taukų ugnies atnašomis, kad tai mosuotų kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje; ir tai bus tavo ir tavo sūnų su tavimi amžinu įstatu; kaip VIEŠPATS yra įsakęs“.'),
  (@b3, 10, 16, 'Ir Mozė stropiai ieškojo nuodėmės atnašos ožio, ir štai jis buvo sudegintas; ir jis supyko ant Eleazaro ir Itamaro, likusiųjų gyvų Aarono sūnų, sakydamas:'),
  (@b3, 10, 17, '„Kodėl nevalgėte nuodėmės atnašos šventojoje vietoje, kadangi ji yra švenčiausia, ir Dievas jums davė ją, kad nešiotumėte susirinkimo neteisybę, kad atliktumėte sutaikinimą už juos VIEŠPATIES akivaizdoje?'),
  (@b3, 10, 18, 'Štai jos kraujas nebuvo įneštas į šventosios vietos vidų; jūs iš tikrųjų turėjote ją valgyti šventojoje vietoje, kaip aš įsakiau’“.'),
  (@b3, 10, 19, 'O Aaronas tarė Mozei: „Štai šią dieną jie atnašavo savo nuodėmės atnašą ir savo deginamąją atnašą VIEŠPATIES akivaizdoje; ir man yra atsitikę tokie dalykai; ir jei šiandien būčiau valgęs nuodėmės atnašą, argi tai būtų buvę priimtina VIEŠPATIES akyse?“'),
  (@b3, 10, 20, 'Ir Mozė tai išgirdęs sutiko.'),
  (@b3, 11, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, jiems sakydamas:'),
  (@b3, 11, 2, '„Kalbėkite Izraelio vaikams, sakydami: ‘Tie yra gyvuliai, kuriuos valgysite iš visų gyvulių, esančių žemėje.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b3, 11, 3, 'Katras gyvulių tarpe skelia nagą ir yra skeltanagis bei gromuliuoja, tą valgysite.'),
  (@b3, 11, 4, 'Tačiau iš tų, kurie gromuliuoja, ar iš tų, kurie dalija nagą, jūs nevalgysite šitų: kupranugario, nes jis gromuliuoja, bet nedalija nago; jis jums yra nešvarus.'),
  (@b3, 11, 5, 'Ir triušio, nes jis gromuliuoja, bet nedalija nago; jis jums yra nešvarus.'),
  (@b3, 11, 6, 'Ir kiškio, nes jis gromuliuoja, bet nedalija nago; jis jums yra nešvarus.'),
  (@b3, 11, 7, 'Ir kiaulės, nors ji ir dalija nagą ir yra skeltanagė, tačiau ji negromuliuoja; ji jums yra nešvari.'),
  (@b3, 11, 8, 'Nevalgysite iš jų mėsos ir neliesite jų lavonų; jie jums yra nešvarūs.'),
  (@b3, 11, 9, 'Iš visų, esančių vandenyse, valgysite šituos: kurie turi pelekus ir žvynus vandenyse, jūrose ir upėse, tuos valgysite.'),
  (@b3, 11, 10, 'O visi, kurie neturi pelekų ir žvynų jūrose ir upėse iš visų judančių vandenyse ir iš visų gyvų padarų, esančių vandenyse, tie bus jums bjaurastis;'),
  (@b3, 11, 11, 'jie bus jums bjaurastis; nevalgysite iš jų mėsos, bet bjaurėsitės jų lavonais.'),
  (@b3, 11, 12, 'Kas vandenyse neturi pelekų ir žvynų, tas bus jums bjaurastis.'),
  (@b3, 11, 13, 'O šitie yra tie, kuriais bjaurėsitės tarp skrajūnų; jie nebus valgomi, jie yra bjaurastis: erelis, grifas, jūros erelis,'),
  (@b3, 11, 14, 'maitvanagis, pesliai pagal jų rūšis;'),
  (@b3, 11, 15, 'visi varnai pagal jų rūšis;'),
  (@b3, 11, 16, 'pelėda, naktinis vanagas, gegutė ir vanagai pagal jų rūšis,'),
  (@b3, 11, 17, 'mažoji pelėda, kormoranas, didžioji pelėda,'),
  (@b3, 11, 18, 'gulbė, pelikanas, erelis žuvininkas,'),
  (@b3, 11, 19, 'gandras, garniai pagal jų rūšis, pempė ir šikšnosparnis.'),
  (@b3, 11, 20, 'Visi ropojantys skrajūnai, vaikštantys visomis keturiomis, bus jums bjaurastis.'),
  (@b3, 11, 21, 'Tačiau galite valgyti šituos iš visų skraidančių, ropojančių padarų, vaikštančių visomis keturiomis, viršum savo pėdų turinčių kojas, kad jomis šokinėtų ant žemės;'),
  (@b3, 11, 22, 'šituos iš jų galite valgyti: skėrius pagal jų rūšis, įkypveidžius skėrius pagal jų rūšis, vabalus pagal jų rūšis ir žiogus pagal jų rūšis.'),
  (@b3, 11, 23, 'Bet visi kiti skraidantys, ropojantys padarai, turintys keturias kojas, jums bus bjaurastis.'),
  (@b3, 11, 24, 'Ir dėl šitų būsite nešvarūs; kas palies jų lavoną, bus nešvarus iki vakaro.'),
  (@b3, 11, 25, 'Ir kas neš ką nors iš jų lavonų, išsiplaus savo drabužius ir bus nešvarus iki vakaro.'),
  (@b3, 11, 26, 'Visų gyvulių, kurie dalija nagą, o nėra skeltanagiai nei negromuliuoja, lavonai yra jums nešvarūs; kas juos palies, bus nešvarus.'),
  (@b3, 11, 27, 'O kurie vaikšto letenomis tarp visokių gyvulių, vaikščiojančių visomis keturiomis, šitie jums yra nešvarūs; kas palies jų lavoną, bus nešvarus iki vakaro.'),
  (@b3, 11, 28, 'Ir kas neš jų lavoną, išsiplaus savo drabužius ir bus nešvarus iki vakaro; jie jums yra nešvarūs.'),
  (@b3, 11, 29, 'Taip pat šitie jums bus nešvarūs tarp ropojančių būtybių, kurios ropoja ant žemės: žebenkštis, pelė, vėžliai pagal jų rūšis,'),
  (@b3, 11, 30, 'šeškas, chameleonas, driežas, sraigė ir kurmis.'),
  (@b3, 11, 31, 'Tie yra jums nešvarūs tarp visų ropojančių; kas juos palies, kai jie padvėsę, bus nešvarus iki vakaro.'),
  (@b3, 11, 32, 'O ant ko kuris nors iš tų padvėsusių užkristų, tai bus nešvaru; ar tai būtų koks medžio indas, ar drabužis, ar oda, ar maišas, koks tai bebūtų įrankis, kuriuo atliekamas bet koks darbas, turės būti įdėtas į vandenį, ir tai bus nešvaru iki vakaro; taip jis bus apvalytas.'),
  (@b3, 11, 33, 'Ir kiekvienas molinis indas, į kurį kas nors iš tų įkris, visa, kas bus jame, tai bus nešvaru; ir jūs jį sudaužykite.'),
  (@b3, 11, 34, 'Kiekvienas valgomas maistas, ant kurio pateks toks vanduo, bus nešvarus; ir kiekvienas geriamas gėrimas kiekviename tokiame inde, bus nešvarus.'),
  (@b3, 11, 35, 'Ir visa, ant ko užkris kokia dalis iš jų lavonų, bus nešvaru; ar tai būtų krosnis, ar viryklė puodams, jos turės būti sudaužytos; nes jos yra nešvarios, ir jums bus nešvarios.'),
  (@b3, 11, 36, 'Tačiau versmė ar duobė, kuriose yra gausu vandens, bus švarios; bet kas palies jų lavoną, bus nešvaru.'),
  (@b3, 11, 37, 'Ir jei kuri jų lavono dalis nukris ant kokios nors sėjamos sėklos, kurią reikia sėti, ji bus švari.'),
  (@b3, 11, 38, 'Bet jei koks vanduo bus užpiltas ant sėklos ir jei kuri jų lavono dalis užkris ant jos, ji bus jums nešvari.'),
  (@b3, 11, 39, 'Ir jei padvės koks gyvulys, kurio jums galima valgyti; kas palies jo lavoną, bus nešvarus iki vakaro.'),
  (@b3, 11, 40, 'O kas valgys jo lavono, išsiplaus savo drabužius ir bus nešvarus iki vakaro; ir tas, kuris neš jo lavoną, išsiplaus drabužius ir bus nešvarus iki vakaro.'),
  (@b3, 11, 41, 'O kiekvienas ropojantis padaras, ropojantis ant žemės, bus bjaurastis; jis nebus valgomas.'),
  (@b3, 11, 42, 'Nevalgykite tų, kurie vaikšto pilvu, kurie vaikšto visomis keturiomis ar kurie turi daugiau kojų tarp visų ropojančių būtybių, kurie ropoja ant žemės; nes jie yra bjaurastis.'),
  (@b3, 11, 43, 'Neapsibjaurinkite jokiu ropojančiu padaru, kuris ropoja, nei nesusitepkite jais, kad jais nesusiterštumėte.'),
  (@b3, 11, 44, 'Nes aš esu VIEŠPATS, jūsų Dievas; todėl pašvęskite save, ir būsite šventi; nes aš esu šventas; nei nesusiterškite jokiais ropojančiais padarais, kurie ropoja ant žemės.'),
  (@b3, 11, 45, 'Nes aš esu VIEŠPATS, kuris jus išvedu aukštyn iš Egipto šalies, kad būčiau jūsų Dievas; todėl būkite šventi, nes aš esu šventas’“.'),
  (@b3, 11, 46, 'Šitas yra įstatymas apie gyvulius, apie skrajūnus, apie kiekvieną gyvą sutvėrimą, judantį vandenyse, ir apie kiekvieną sutvėrimą, ropojantį ant žemės;'),
  (@b3, 11, 47, 'kad darytų skirtumą tarp nešvaraus ir švaraus ir tarp gyvūno, kurį galima valgyti, ir gyvūno, kurio negalima valgyti.'),
  (@b3, 12, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 12, 2, '„Kalbėk Izraelio vaikams, sakydamas: ‘Jei moteris užmezga sėklą ir pagimdo vyriškos lyties vaiką, tuomet ji bus nešvari septynias dienas; pagal atskyrimo dienas dėl jos negalios ji bus nešvari.'),
  (@b3, 12, 3, 'O aštuntąją dieną bus apipjaustytas jo apyvarpės kūnas.'),
  (@b3, 12, 4, 'Ir tada trisdešimt tris dienas ji pasiliks savo apsivalymo kraujyje; ji nelies jokio švento dalyko nei įeis į šventovę, kol išsipildys jos apsivalymo dienos.'),
  (@b3, 12, 5, 'Bet jei ji pagimdys mergaitę, tuomet ji bus nešvari dvi savaites, kaip jos atsiskyrime; ir ji pasiliks savo apsivalymo kraujyje šešiasdešimt šešias dienas.'),
  (@b3, 12, 6, 'Ir jos apsivalymo dienoms išsipildžius, dėl sūnaus ar dėl dukters, ji atgabens pirmų metų avinėlį deginamajai atnašai ir jauną karvelį ar purplelį nuodėmės atnašai prie susirinkimo padangtės durų pas kunigą;'),
  (@b3, 12, 7, 'kuris jį atnašaus VIEŠPATIES akivaizdoje ir atliks sutaikinimą už ją; ir ji bus apvalyta nuo savo kraujoplūdžio. Šitas yra įstatymas tai, kuri pagimdo vyriškos lyties ar moteriškos lyties vaiką.'),
  (@b3, 12, 8, 'O jei ji negalės atgabenti avinėlio, tuomet ji atgabens du purplelius ar du jaunus karvelius; vieną – deginamajai atnašai, o kitą – nuodėmės atnašai; o kunigas atliks sutaikinimą už ją, ir ji bus švari’“.'),
  (@b3, 13, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b3, 13, 2, '„Kai žmogus savo kūno odoje turės iškilimą, šašligę ar šviesią dėmę, ir tai jo kūno odoje būtų kaip raupsų žaizda, tuomet jis bus atvestas pas kunigą Aaroną ar pas vieną iš jo sūnų, kunigų;'),
  (@b3, 13, 3, 'o kunigas apžiūrės žaizdą kūno odoje; ir kai žaizdoje plaukai bus pabalę, ir žaizda žiūrint bus įdubesnė už jo kūno odą, tai yra raupsų rykštė; ir kunigas, jį apžiūrėjęs, paskelbs jį nešvariu.'),
  (@b3, 13, 4, 'Jei šviesi dėmė jo kūno odoje bus balta ir žiūrint nebus įdubesnė už odą, ir jos plaukai nebus pabalę; tuomet kunigas uždarys turintį žaizdą septynioms dienoms;'),
  (@b3, 13, 5, 'ir kunigas septintąją dieną jį apžiūrės; ir štai, jei jam žiūrint, žaizda sustojusi, žaizda neplinta odoje, tuomet kunigas uždarys jį dar kitoms septynioms dienoms;'),
  (@b3, 13, 6, 'ir kunigas septintąją dieną vėl jį apžiūrės; ir štai jei žaizda būtų patamsėjusi, ir žaizda neplinta odoje, kunigas paskelbs jį švariu; tai tėra šašligė; ir jis išsiplaus drabužius ir bus švarus.'),
  (@b3, 13, 7, 'Bet jei jam, kunigo apžiūrėtam dėl jo apsivalymo, šašligė labai paplinta odoje, jis vėl bus kunigo apžiūrėtas;'),
  (@b3, 13, 8, 'ir jei kunigui tai apžiūrėjus, štai šašligė paplitusi odoje, tuomet kunigas paskelbs jį nešvariu; tai yra raupsai.'),
  (@b3, 13, 9, 'Kai raupsų žaizda yra žmoguje, tuomet jis bus atvestas pas kunigą;'),
  (@b3, 13, 10, 'ir kunigas jį apžiūrės; ir štai jei iškilimas būtų baltas odoje ir tai pabalino plaukus, ir iškilime būtų gyva žalia mėsa;'),
  (@b3, 13, 11, 'tai yra įsisenėję raupsai jo kūno odoje, ir kunigas paskelbs jį nešvariu ir jo neuždarys; nes jis yra nešvarus.'),
  (@b3, 13, 12, 'O jei raupsai išsiplės odoje ir raupsai apdengs visą žaizduotojo odą nuo jo galvos iki jo kojų, kur tik kunigas apžiūri;'),
  (@b3, 13, 13, 'tuomet kunigas atidžiai apžiūrės; ir štai jei raupsai yra apdengę visą jo kūną, jis paskelbs žaizduotąjį švariu; tas visas yra pabalęs; jis yra švarus.'),
  (@b3, 13, 14, 'Bet kai jame pasirodys žalia mėsa, jis bus nešvarus.'),
  (@b3, 13, 15, 'Ir kunigas apžiūrės žalią mėsą ir paskelbs jį esant nešvariu; nes žalia mėsa yra nešvari; tai raupsai.'),
  (@b3, 13, 16, 'Arba jei žalia mėsa atsikeičia ir pasikeičia į baltą, jis ateis pas kunigą;'),
  (@b3, 13, 17, 'ir kunigas jį apžiūrės; ir štai jei žaizda pavirtusi į baltą, tuomet kunigas paskelbs žaizduotąjį švariu; jis yra švarus.'),
  (@b3, 13, 18, 'Taip pat kūnas, kuriame, jo odoje, buvo skaudulys ir yra užgijęs,'),
  (@b3, 13, 19, 'ir skaudulio vietoje būtų baltas iškilimas ar šviesi dėmė, balta ir paraudusi, ir tai būtų parodyta kunigui;'),
  (@b3, 13, 20, 'ir jei kunigui tai apžiūrėjus, štai žiūrint ta bus įdubesnė už odą, ir jos plaukai bus pabalę, kunigas paskelbs jį nešvariu; tai rykštė raupsų, prasiveržusių iš skaudulio.'),
  (@b3, 13, 21, 'Bet jei kunigas ją apžiūrės, ir štai joje nėra baltų plaukų ir jei ji nėra įdubesnė už odą, bet yra patamsėjusi; tuomet kunigas uždarys jį septynioms dienoms;'),
  (@b3, 13, 22, 'o jei ji labai išplis odoje, tada kunigas paskelbs jį nešvariu; tai rykštė.'),
  (@b3, 13, 23, 'Bet jei šviesi dėmė pasiliks savo vietoje ir nesiplės, tai – deginantis skaudulys; ir kunigas paskelbs jį švariu.'),
  (@b3, 13, 24, 'Arba jei būtų kokia mėsa, kurios odoje yra karštas nudegimas, ir gyva nudegusi mėsa turi šviesią baltą dėmę, paraudusią ar baltą;'),
  (@b3, 13, 25, 'tuomet kunigas tai apžiūrės; ir štai jei plaukai šviesioje dėmėje pabalę, ir ta žiūrint yra įdubesnė už odą; tai raupsai, išsiveržę iš nudegimo; todėl kunigas paskelbs jį nešvariu; tai raupsų rykštė.'),
  (@b3, 13, 26, 'Bet jei kunigas ją apžiūrės, ir štai šviesioje dėmėje nėra baltų plaukų ir ta nėra įdubesnė už kitą odą, bet yra patamsėjusi; tuomet kunigas jį uždarys septynioms dienoms;'),
  (@b3, 13, 27, 'ir jei, kunigui septintąją dieną jį apžiūrėjus, tai bus labai išplitę odoje, tuomet kunigas paskelbs jį nešvariu; tai yra raupsų rykštė.'),
  (@b3, 13, 28, 'O jei šviesi dėmė liks savo vietoje neišplitusi odoje, bet ji bus patamsėjusi; tai yra nudegimo iškilimas, o kunigas paskelbs jį švariu; nes tai nudegimo uždegimas.'),
  (@b3, 13, 29, 'Jei vyras ar moteris turi žaizdą ant galvos ar smakro;'),
  (@b3, 13, 30, 'tada kunigas apžiūrės žaizdą; ir štai jei ji žiūrint bus įdubesnė už odą; ir joje bus geltoni ploni plaukai; tuomet kunigas paskelbs jį nešvariu; tai yra sausas šašuotumas, raupsai ant galvos ar smakro.'),
  (@b3, 13, 31, 'O jei kunigas apžiūrės šašuotumo žaizdą, ir štai ji žiūrint nebus įdubesnė už odą ir joje nebus juodų plaukų; tuomet kunigas uždarys turintį šašuotumo žaizdą septynioms dienoms;'),
  (@b3, 13, 32, 'o septintąją dieną kunigas apžiūrės žaizdą; ir štai jei šašuotumas neplinta ir joje nėra geltonų plaukų, ir šašuotumas žiūrint nėra įdubesnis už odą;'),
  (@b3, 13, 33, 'jis bus nuskustas, bet šašuotumo jis neapskus; ir kunigas uždarys turintį šašuotumą dar septynioms dienoms;'),
  (@b3, 13, 34, 'ir septintąją dieną kunigas apžiūrės šašuotumą; ir štai jei šašuotumas neišplitęs odoje nei žiūrint nėra įdubesnis už odą; tuomet kunigas paskelbs jį švariu; o jis išsiplaus drabužius ir bus švarus.'),
  (@b3, 13, 35, 'Bet jei po jo apiplovimo šašuotumas labai išplis odoje;'),
  (@b3, 13, 36, 'tada kunigas jį apžiūrės; ir štai jei šašuotumas išplitęs odoje, kunigas nebeieškos geltonų plaukų; jis yra nešvarus.'),
  (@b3, 13, 37, 'Bet jei jam žiūrint šašuotumas yra sustojęs, ir juodi plaukai yra išdygę jame; šašuotumas yra išgijęs, jis yra švarus; ir kunigas paskelbs jį švariu.'),
  (@b3, 13, 38, 'Taip pat jei vyras ar moteris turi savo kūno odoje šviesių dėmių, baltų šviesių dėmių;'),
  (@b3, 13, 39, 'tuomet kunigas apžiūrės; ir štai jei jų kūno odoje šviesios dėmės būtų apytamsio baltumo; tai yra šlakuota dėmė, auganti odoje; jis yra švarus.'),
  (@b3, 13, 40, 'O vyras, kuriam nuslinkę plaukai nuo galvos, jis yra nuplikęs; tačiau jis yra švarus.'),
  (@b3, 13, 41, 'O tas, kurio plaukai nuslinkę nuo jo galvos priešakinės dalies, jis yra plikakaktis; tačiau jis yra švarus.'),
  (@b3, 13, 42, 'O jei ant nuplikusios galvos ar nuplikusios kaktos būtų rausvai balta žaizda, tai yra raupsai, iššokę jo nuplikusioje galvoje ar nuplikusioje jo kaktoje.'),
  (@b3, 13, 43, 'Tuomet kunigas tai apžiūrės; ir štai jei žaizdos iškilimas jo nuplikusioje galvoje ar nuplikusioje jo kaktoje būtų rausvai baltas, kaip pasirodo raupsai kūno odoje,'),
  (@b3, 13, 44, 'jis yra raupsuotas žmogus, jis yra nešvarus; kunigas paskelbs jį visiškai nešvariu; jo rykštė yra ant jo galvos.'),
  (@b3, 13, 45, 'Ir raupsuotasis, kuriame yra rykštė, jo drabužiai bus perplėšti, jo galva apnuoginta, jis užsidės apdangalą ant viršutinės lūpos ir šauks: „Nešvarus, nešvarus“.'),
  (@b3, 13, 46, 'Visas dienas, kuriomis rykštė bus jame, jis bus suterštas; jis yra nešvarus; jis gyvens vienas; už stovyklos bus jo buveinė.'),
  (@b3, 13, 47, 'Taip pat drabužis, kuriame yra raupsų rykštė, ar tai būtų vilnonis, ar lininis drabužis;'),
  (@b3, 13, 48, 'ar tai būtų metmenyse, ar atauduose; iš lininio ar iš vilnonio; ar tai odoje, ar kokiame nors odos dirbinyje;'),
  (@b3, 13, 49, 'ir jei žaizda yra žalsva ar rausva drabužyje ar odoje, ar metmenyse, ar atauduose, ar kokiame daikte iš odos; tai yra raupsų rykštė, ir bus parodyta kunigui;'),
  (@b3, 13, 50, 'o kunigas, apžiūrėjęs žaizdą, uždarys tai, kas turi žaizdą, septynioms dienoms;'),
  (@b3, 13, 51, 'ir jei jam, septintąją dieną apžiūrėjus žaizdą, žaizda bus išplitusi drabužyje ar metmenyse, ar atauduose, ar odoje, ar kokiame dirbinyje, padarytame iš odos; ta rykštė yra įsigraužiantys raupsai; tai yra nešvaru.'),
  (@b3, 13, 52, 'Todėl jis sudegins tą drabužį ar tai metmenis, ar ataudus, vilnoniame ar lininiame, ar bet kokį daiktą iš odos, kuriame yra žaizda; nes tai yra įsigraužiantys raupsai; tai bus sudeginta ugnyje.'),
  (@b3, 13, 53, 'O jei kunigas apžiūrės, ir štai žaizda neišplitusi drabužyje ar tai metmenyse, ar atauduose, ar bet kokiame daikte iš odos;'),
  (@b3, 13, 54, 'tada kunigas įsakys, kad jie išplautų tai, kame yra žaizda, ir jis tai uždarys dar septynioms dienoms;'),
  (@b3, 13, 55, 'ir kai tai yra išplauta, kunigas apžiūrės žaizdą; ir štai jei žaizda nepakeitusi savo spalvos ir žaizda neišplitusi, tai yra nešvaru; sudegink tai ugnyje; ji yra įsigraužusi vidun, ar tai ji būtų plika viduje, ar išorėje.'),
  (@b3, 13, 56, 'O jei kunigas apžiūrės, ir štai žaizda, ją išplovus, būtų patamsėjusi; tuomet jis ją išplėš iš drabužio ar iš odos, ar iš metmenų, ar iš ataudų;'),
  (@b3, 13, 57, 'o jei tai vis dar pasirodys drabužyje ar tai metmenyse, ar atauduose, ar bet kokiame daikte iš odos; tai yra plintanti žaizda; sudegink ugnimi tai, kame yra žaizda.'),
  (@b3, 13, 58, 'O drabužis ar tai metmenys, ar ataudai, ar bet koks daiktas iš odos, kuriuos išplausi, jei žaizda pasitrauks nuo tų, tuomet tai bus išplauta antrą kartą, ir bus švaru“.'),
  (@b3, 13, 59, 'Šitas yra įstatymas apie raupsų rykštę vilnoniame ar lininiame drabužyje, ar metmenyse, ar atauduose, ar bet kokiame daikte iš odos, kad paskelbtų tai švariu, ar paskelbtų tai nešvariu.'),
  (@b3, 14, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 14, 2, '„Šitas bus įstatymas raupsuotojo jo apvalymo dieną; jis bus atvestas pas kunigą;'),
  (@b3, 14, 3, 'o kunigas išeis už stovyklos; ir kunigas apžiūrės, ir štai jei raupsų žaizda raupsuotajame yra išgijusi;'),
  (@b3, 14, 4, 'tada kunigas įsakys, kad paimtų tam, kuris turės būti apvalytas, du gyvus, švarius paukščius, kedro medžio, skaisčiai raudono ir yzopą;'),
  (@b3, 14, 5, 'ir kunigas įsakys, kad būtų papjautas vienas iš paukščių moliniame inde virš tekančio vandens;'),
  (@b3, 14, 6, 'o dėl gyvojo paukščio, jis paims jį, kedro medžio, skaisčiai raudono bei yzopą ir pamerks juos ir gyvąjį paukštį į kraują paukščio, papjauto virš tekančio vandens;'),
  (@b3, 14, 7, 'ir septynis kartus jis apšlakstys tą, kuris turi būti apvalytas nuo raupsų, ir paskelbs jį švariu, o gyvąjį paukštį paleis į atvirą lauką.'),
  (@b3, 14, 8, 'O tas, kuris turi būti apvalytas, išplaus savo drabužius, nusiskus visus plaukus ir nusiplaus vandenyje, kad būtų švarus; o po to jis ateis į stovyklą ir septynias dienas pasiliks už savo palapinės.'),
  (@b3, 14, 9, 'Bet septintąją dieną jis nusiskus visus plaukus nuo galvos ir savo barzdą bei antakius, jis nusiskus visus plaukus; ir jis išplaus savo drabužius, taip pat nusiplaus kūną vandenyje, ir bus švarus.'),
  (@b3, 14, 10, 'O aštuntąją dieną jis paims du avinėlius be trūkumų, vieną pirmųjų metų avį be trūkumų, tris dešimtadalius smulkių miltų, sumaišytų su aliejumi, kaip maisto atnašą, ir vieną logą aliejaus.'),
  (@b3, 14, 11, 'O apvalantis jį kunigas pristatys tą žmogų, kuris turi būti apvalytas, ir tuos dalykus VIEŠPATIES akivaizdoje prie susirinkimo padangtės durų;'),
  (@b3, 14, 12, 'ir kunigas paims vieną avinėlį ir jį atnašaus kaip nusižengimo atnašą, ir logą aliejaus, ir juos mosuos kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje;'),
  (@b3, 14, 13, 'ir jis papjaus avinėlį toje vietoje, kur papjauna nuodėmės atnašą ir deginamąją atnašą, šventojoje vietoje; nes kaip nuodėmės atnaša, taip ir nusižengimo atnaša yra kunigo; ji yra švenčiausia;'),
  (@b3, 14, 14, 'ir kunigas paims šiek tiek nusižengimo atnašos kraujo, ir kunigas jo uždės ant dešinės ausies galiuko tam, kuris turi būti apvalytas, ant jo dešinės rankos nykščio ir ant jo dešinės kojos nykščio;'),
  (@b3, 14, 15, 'ir kunigas paims dalį iš logo aliejaus ir jo įpils į savo kairės rankos delną;'),
  (@b3, 14, 16, 'ir kunigas pamirkys savo dešinįjį pirštą į aliejų, esantį jo kairėje rankoje, ir septynis kartus savo pirštu pašlakstys aliejaus VIEŠPATIES akivaizdoje;'),
  (@b3, 14, 17, 'o jo rankoje esančio likusio aliejaus kunigas uždės ant dešinės ausies galiuko tam, kuris turi būti apvalytas, ant jo dešinės rankos nykščio ir ant jo dešinės kojos nykščio, ant nusižengimo atnašos kraujo;'),
  (@b3, 14, 18, 'o likutį kunigo rankoje esančio aliejaus jis užpils ant galvos tam, kuris turi būti apvalytas; ir kunigas atliks už jį sutaikinimą VIEŠPATIES akivaizdoje.'),
  (@b3, 14, 19, 'Ir kunigas atnašaus nuodėmės atnašą ir atliks sutaikinimą už tą, kuris turi būti apvalytas nuo jo nešvarumo; o po to jis papjaus deginamąją atnašą;'),
  (@b3, 14, 20, 'ir kunigas atnašaus ant aukuro deginamąją atnašą ir maisto atnašą; ir kunigas atliks sutaikinimą už jį, ir jis bus švarus.'),
  (@b3, 14, 21, 'O jei jis būtų beturtis ir negalėtų tiek daug įsigyti; tuomet jis paims vieną avinėlį kaip nusižengimo atnašą, kad būtų mosuojama, sutaikinimui atlikti už jį, ir vieną dešimtadalį smulkių miltų, sumaišytų su aliejumi, kaip maisto atnašą, ir logą aliejaus;'),
  (@b3, 14, 22, 'du purplelius arba du jaunus karvelius, kokius jis gali įsigyti; ir vienas bus nuodėmės atnaša, o kitas – deginamoji atnaša.'),
  (@b3, 14, 23, 'Ir aštuntąją dieną jis juos atgabens savo apvalymui pas kunigą prie susirinkimo padangtės durų, VIEŠPATIES akivaizdon.'),
  (@b3, 14, 24, 'Ir kunigas paims nusižengimo atnašos avinėlį bei logą aliejaus, ir kunigas juos mosuos kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje;'),
  (@b3, 14, 25, 'ir jis papjaus nusižengimo atnašos avinėlį, ir kunigas paims dalį nusižengimo atnašos kraujo ir uždės jo ant dešinės ausies galiuko tam, kuris turi būti apvalytas, ant jo dešinės rankos nykščio ir ant jo dešinės kojos nykščio;'),
  (@b3, 14, 26, 'ir kunigas įpils aliejaus į savo kairės rankos delną;'),
  (@b3, 14, 27, 'ir kunigas savo dešiniuoju pirštu pašlakstys truputį aliejaus, esančio jo kairėje rankoje, septynis kartus VIEŠPATIES akivaizdoje;'),
  (@b3, 14, 28, 'ir kunigas uždės jo rankoje esančio aliejaus ant dešinės ausies galiuko tam, kuris turi būti apvalytas, ant jo dešinės rankos nykščio ir ant jo dešinės kojos nykščio, ant nusižengimo atnašos kraujo vietos;'),
  (@b3, 14, 29, 'o kunigo delne likusio aliejaus jis uždės ant galvos tam, kuris turi būti apvalytas, kad atliktų už jį sutaikinimą VIEŠPATIES akivaizdoje.'),
  (@b3, 14, 30, 'Ir jis atnašaus vieną iš purplelių ar jaunų karvelių, kokius jis gali įsigyti;'),
  (@b3, 14, 31, 'tai yra, kokius jis yra pajėgus įsigyti, vieną kaip nuodėmės atnašą, o kitą kaip deginamąją atnašą, su maisto atnaša; ir kunigas atliks sutaikinimą už tą, kuris turi būti apvalytas, VIEŠPATIES akivaizdoje.'),
  (@b3, 14, 32, 'Šitas yra įstatymas to, kuriame yra raupsų rykštė, kurio ranka nepajėgi įsigyti to, kas priklauso jo apvalymui“.'),
  (@b3, 14, 33, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b3, 14, 34, '„Kai būsite įėję į Kanaano šalį, kurią jums duosiu nuosavybėn, ir aš uždėsiu raupsų rykštę ant jūsų nuosavybės šalies namų;'),
  (@b3, 14, 35, 'ir namų savininkas ateis ir praneš kunigui, sakydamas: ‘Man atrodo, namuose yra tarsi rykštė’;'),
  (@b3, 14, 36, 'tada kunigas įsakys, kad prieš kunigui įeinant žaizdos apžiūrėti, jie ištuštintų namus, kad nepasidarytų nešvaru visa tai, kas yra namuose; o po to kunigas įeis namų apžiūrėti;'),
  (@b3, 14, 37, 'ir jis apžiūrės žaizdą, ir štai jei žaizda yra namų sienose su žalsvomis ar rausvomis įdubomis, kurios žiūrint yra gilesnės už sieną;'),
  (@b3, 14, 38, 'tada kunigas išeis iš namų prie namų durų ir uždarys namus septynioms dienoms;'),
  (@b3, 14, 39, 'o septintąją dieną kunigas sugrįš ir apžiūrės; ir štai jei žaizda išplitusi namų sienose;'),
  (@b3, 14, 40, 'tuomet kunigas įsakys, kad išimtų akmenis, kuriuose yra žaizda, ir juos išmestų už miesto į nešvarią vietą;'),
  (@b3, 14, 41, 'ir jis lieps namus nugrandyti viduje aplinkui, ir jie išpils dulkes, kurias nugrandė, už miesto į nešvarią vietą;'),
  (@b3, 14, 42, 'ir jie paims kitus akmenis ir juos įdės į anų akmenų vietą; ir paims kitą tinką ir ištinkuos tuos namus.'),
  (@b3, 14, 43, 'O jei, akmenis išėmus, namus nugrandžius ir juos ištinkavus, žaizda sugrįžta ir išplinta namuose;'),
  (@b3, 14, 44, 'tada kunigas ateis ir apžiūrės, ir štai jei žaizda išplitusi namuose, tai yra įsigraužiantys raupsai namuose; jie yra nešvarūs.'),
  (@b3, 14, 45, 'Ir nugriaus tuos namus, jų akmenis, jų rąstus ir visą namų tinką; ir juos išgabens už miesto į nešvarią vietą.'),
  (@b3, 14, 46, 'Be to, kas įeis į namus per visą tą laiką, kai jie uždaryti, bus nešvarus iki vakaro.'),
  (@b3, 14, 47, 'Ir kas atsigula tuose namuose, išplaus savo drabužius; ir kas valgo tuose namuose, išplaus savo drabužius.'),
  (@b3, 14, 48, 'O jei kunigas įeis ir juos apžiūrės, ir štai po namų ištinkavimo žaizda neišplitusi namuose; tuomet kunigas paskelbs namus švariais, nes žaizda yra išgijusi.'),
  (@b3, 14, 49, 'Ir namams apvalyti jis paims du paukščius, kedro medžio, skaisčiai raudono ir yzopą;'),
  (@b3, 14, 50, 'ir jis papjaus vieną iš paukščių moliniame inde virš tekančio vandens;'),
  (@b3, 14, 51, 'ir paims kedro medžio, yzopo, skaisčiai raudono bei gyvąjį paukštį ir juos pamirkys papjauto paukščio kraujyje bei tekančiame vandenyje ir septynis kartus pašlakstys namus;'),
  (@b3, 14, 52, 'ir apvalys tuos namus paukščio krauju, tekančiu vandeniu, gyvuoju paukščiu, kedro medžiu, yzopu ir skaisčiai raudonu;'),
  (@b3, 14, 53, 'bet jis paleis gyvąjį paukštį iš miesto į atvirus laukus ir atliks sutaikinimą už namus; ir jie bus švarūs“.'),
  (@b3, 14, 54, 'Šitas yra įstatymas visokiai raupsų rykštei ir šašuotumui,'),
  (@b3, 14, 55, 'ir drabužio bei namų raupsams,'),
  (@b3, 14, 56, 'iškilimui, šašams ir šviesiai dėmei;'),
  (@b3, 14, 57, 'pamokymui, kada tai yra nešvaru ir kada tai yra švaru; šitas yra raupsų įstatymas.'),
  (@b3, 15, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b3, 15, 2, '„Kalbėkite Izraelio vaikams ir jiems sakykite: ‘Kai koks nors žmogus turi plūdimą iš savo kūno, dėl savo plūdimo jis yra nešvarus.'),
  (@b3, 15, 3, 'Ir šitas bus jo nešvarumas jo plūdime: ar tai jo kūnas išlieja plūdimą, ar jo kūnas bus sustabdęs savo plūdimą, tai yra jo nešvarumas.'),
  (@b3, 15, 4, 'Kiekvienas patalas, kuriame gulės turintis plūdimą, yra nešvarus; ir viskas, ant ko jis atsisės, bus nešvaru.'),
  (@b3, 15, 5, 'Ir kas palies jo patalą, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 6, 'Ir kas atsisės ant to, ant ko sėdėjo turintis plūdimą, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 7, 'Ir kas palies kūną to, kuris turi plūdymą, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 8, 'Ir jei turintis plūdimą spjauna ant švaraus; tuomet tas išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 9, 'Ir balnas, ant kurio turintis plūdimą jotų, bus nešvarus.'),
  (@b3, 15, 10, 'Ir kiekvienas, kuris paliestų bet ką, kas buvo po juo, bus nešvarus iki vakaro; o kas neštų bet ką iš tų daiktų, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 11, 'Ir kurį turintis plūdimą paliestų, nenuskalavęs savo rankų vandenyje, tas išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 12, 'Ir indas iš molio, kurį paliestų turintis plūdimą, bus sudaužytas; o kiekvienas indas iš medžio bus išskalautas vandenyje.'),
  (@b3, 15, 13, 'O kai turintis plūdimą yra apvalytas nuo savo ištekėjimo; tada jis sau atskaičiuos septynias dienas savo apvalymui, išplaus savo drabužius, nusiplaus kūną tekančiame vandenyje ir bus švarus.'),
  (@b3, 15, 14, 'O aštuntąją dieną jis pasiims du purplelius ar du jaunus karvelius, ateis VIEŠPATIES akivaizdon prie susirinkimo padangtės durų ir juos duos kunigui;'),
  (@b3, 15, 15, 'o kunigas juos atnašaus: vieną kaip nuodėmės atnašą, o kitą kaip deginamąją atnašą; ir kunigas atliks sutaikinimą už jį VIEŠPATIES akivaizdoje dėl jo plūdimo.'),
  (@b3, 15, 16, 'Ir jei kuriam vyrui iš jo išsilieja susijungimo sėkla, tada jis nuplaus vandenyje visą savo kūną ir bus nešvarus iki vakaro.'),
  (@b3, 15, 17, 'Ir kiekvienas drabužis bei kiekviena oda, ant kurių yra susijungimo sėkla, bus nuplauti vandeniu ir bus nešvarūs iki vakaro.'),
  (@b3, 15, 18, 'Taip pat moteris, su kuria suguls vyras su susijungimo sėkla, jie abu nusiplaus vandenyje ir bus nešvarūs iki vakaro.'),
  (@b3, 15, 19, 'O jei moteris turi plūdimą, ir jos plūdimas jos kūne būtų kraujas, ji bus atskirta septynioms dienoms; o kas ją palies, bus nešvarus iki vakaro.'),
  (@b3, 15, 20, 'Ir visa, ant ko ji atsiguls, būdama savo atskyrime, bus nešvaru; taip pat visa, ant ko ji atsisės, bus nešvaru.'),
  (@b3, 15, 21, 'Ir kas palies jos patalą, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 22, 'Ir kas palies bet ką, ant ko ji sėdėjo, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 23, 'Ir jei tai bus ant jos patalo ar ant to, ant ko ji sėdėjo, kai jis tai palies, jis bus nešvarus iki vakaro.'),
  (@b3, 15, 24, 'Ir jei kuris vyras tikrai suguls su ja, ir jos mėnesinių išskyros bus ant jo, jis bus nešvarus septynias dienas; ir kiekvienas patalas, ant kurio jis atsiguls, bus nešvarus.'),
  (@b3, 15, 25, 'O jei moteris turi kraujoplūdį daugelį dienų ne savo atsiskyrimo metu, arba jei tai plūsta ilgiau jos atsiskyrimo laiko; visos jos nešvarumo plūdimo dienos bus kaip jos atskyrimo dienos; ji bus nešvari.'),
  (@b3, 15, 26, 'Kiekvienas patalas, ant kurio ji atsiguls per visas savo plūdimo dienas, bus jai kaip jos atsiskyrimo patalas; ir ant ko ji atsisės, tai bus nešvaru, kaip jos atsiskyrimo nešvarumas.'),
  (@b3, 15, 27, 'Ir kas tuos dalykus palies, bus nešvarus ir išplaus savo drabužius bei nusiplaus vandenyje, ir bus nešvarus iki vakaro.'),
  (@b3, 15, 28, 'Bet jei ji bus apvalyta nuo savo plūdimo, tada ji sau atskaičiuos septynias dienas, ir po to ji bus švari.'),
  (@b3, 15, 29, 'O aštuntąją dieną ji pasiims du purplelius ar du jaunus karvelius ir juos nuneš kunigui prie susirinkimo padangtės durų.'),
  (@b3, 15, 30, 'Ir kunigas atnašaus vieną kaip nuodėmės atnašą, o kitą kaip deginamąją atnašą; ir kunigas atliks sutaikinimą už ją VIEŠPATIES akivaizdoje dėl jos nešvarumo plūdimo.'),
  (@b3, 15, 31, 'Taip jūs atskirsite Izraelio vaikus nuo jų nešvarumo; kad jie nemirtų savo nešvarume, sutepdami mano padangtę, esančią tarp jų’“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b3, 15, 32, 'Šitas yra įstatymas turinčiojo plūdimą ir to, kurio sėkla išteka iš jo ir tuo suteršia;'),
  (@b3, 15, 33, 'ir sergančiosios savo mėnesinių išskyrimu, turinčiojo plūdimą, vyro ir moters, ir to, kuris sugula su nešvaria.'),
  (@b3, 16, 1, 'Ir VIEŠPATS kalbėjo Mozei po dviejų Aarono sūnų mirties, kai jie atnašavo VIEŠPATIES akivaizdoje ir mirė;'),
  (@b3, 16, 2, 'ir VIEŠPATS tarė Mozei: „Kalbėk savo broliui Aaronui, kad jis bet kokiu metu neateitų į šventąją vietą už uždangos prieš gailestingumo krasę, esančią ant skrynios; kad jis nemirtų; nes aš pasirodysiu debesyje ant gailestingumo krasės.'),
  (@b3, 16, 3, 'Taip Aaronas įeis į šventąją vietą: su jaunikliu jautuku nuodėmės atnašai ir su avinu deginamajai atnašai.'),
  (@b3, 16, 4, 'Jis užsivilks šventą lininį apdarą ir turės linines kelnes ant savo kūno, bus apsijuosęs linine juosta ir užsidėjęs lininę mitrą; šitie yra šventi drabužiai; todėl jis nusiplaus kūną vandenyje, ir taip juos apsivilks.'),
  (@b3, 16, 5, 'O iš Izraelio vaikų susirinkimo jis ims du ožiukus nuodėmės atnašai ir vieną aviną deginamajai atnašai.'),
  (@b3, 16, 6, 'Ir Aaronas atnašaus savo nuodėmės atnašos jautuką, kuris yra už jį, ir atliks sutaikinimą už save ir už savo namus.'),
  (@b3, 16, 7, 'Ir jis paims du ožius ir juos pristatys VIEŠPATIES akivaizdon prie susirinkimo padangtės durų.'),
  (@b3, 16, 8, 'Ir Aaronas mes burtus dėl abiejų ožių: vieną burtą VIEŠPAČIUI, o kitą burtą paleidimo ožiui.'),
  (@b3, 16, 9, 'Ir Aaronas atves ožį, ant kurio krito VIEŠPATIES burtas, ir jį atnašaus kaip nuodėmės atnašą.'),
  (@b3, 16, 10, 'Bet ožys, ant kurio krito burtas, kad būtų paleidimo ožiu, bus pristatytas gyvas VIEŠPATIES akivaizdon, kad juo atliktų sutaikinimą ir kad jį paleistų kaip paleidimo ožį į dykumą.'),
  (@b3, 16, 11, 'Ir Aaronas atves nuodėmės atnašos jautuką, kuris yra už jį, ir atliks sutaikinimą už save ir savo namus ir papjaus nuodėmės atnašos jautuką, kuris yra už jį;'),
  (@b3, 16, 12, 'ir nuo aukuro VIEŠPATIES akivaizdoje jis paims smilkytuvą, pilną degančių žarijų, ir savo saujas, pilnas smulkiai sutrintų kvapių smilkalų, ir juos įneš už uždangos;'),
  (@b3, 16, 13, 'ir jis uždės smilkalus ant ugnies VIEŠPATIES akivaizdoje, kad smilkalų debesis apdengtų gailestingumo krasę, esančią ant Liudijimo, kad jis nemirtų;'),
  (@b3, 16, 14, 'ir jis ims jautuko kraujo ir savo pirštu šlakstys jo ant gailestingumo krasės rytų link; ir septynis kartus savo pirštu jis pašlakstys kraujo prieš gailestingumo krasę.'),
  (@b3, 16, 15, 'Paskui jis papjaus nuodėmės atnašos ožį, kuris yra už tautą, ir įneš jo kraują už uždangos, ir padarys su tuo krauju, kaip jis padarė su jautuko krauju, ir jį šlakstys ant gailestingumo krasės ir prieš gailestingumo krasę;'),
  (@b3, 16, 16, 'ir jis atliks sutaikinimą už šventąją vietą dėl Izraelio vaikų nešvarumo ir dėl jų nusižengimų visomis jų nuodėmėmis; ir taip jis padarys susirinkimo padangtei, pasiliekančiai tarp jų, viduryje jų nešvarumo.'),
  (@b3, 16, 17, 'Ir jam įeinant atlikti sutaikinimą šventojoje vietoje, jokio žmogaus nebus susirinkimo padangtėje, kol jis išeis, atlikęs sutaikinimą už save, už savo namiškius ir už visą Izraelio susirinkimą.'),
  (@b3, 16, 18, 'Ir jis išeis prie VIEŠPATIES akivaizdoje esančio aukuro ir už jį atliks sutaikinimą; ir paims jautuko kraujo bei ožio kraujo ir uždės jo ant aukuro ragų aplinkui.'),
  (@b3, 16, 19, 'Ir jis septynis kartus savo pirštu šlakstys ant jo kraujo, apvalys jį ir jį pašvęs nuo Izraelio vaikų nešvarumo.'),
  (@b3, 16, 20, 'Ir užbaigęs sutaikinti šventąją vietą, susirinkimo padangtę ir aukurą, jis atves gyvąjį ožį;'),
  (@b3, 16, 21, 'ir Aaronas uždės abi savo rankas ant gyvojo ožio galvos ir išpažins ant jo visas Izraelio vaikų neteisybes bei visus jų nusižengimus visose jų nuodėmėse, jas uždėdamas ant ožio galvos, ir tinkamo vyro ranka jį paleis į dykumą;'),
  (@b3, 16, 22, 'ir ožys nuneš ant savęs visas jų neteisybes į negyvenamą žemę; ir paleis ožį dykumoje.'),
  (@b3, 16, 23, 'Ir Aaronas įeis į susirinkimo padangtę ir nusivilks lininius drabužius, kuriuos jis apsivilko, įeidamas į šventąją vietą, ir juos ten paliks;'),
  (@b3, 16, 24, 'ir jis nusiplaus vandeniu kūną šventojoje vietoje, apsivilks savo drabužius ir išėjęs atnašaus savo deginamąją atnašą bei tautos deginamąją atnašą, ir atliks sutaikinimą už save ir už tautą.'),
  (@b3, 16, 25, 'O nuodėmės atnašos taukus jis sudegins ant aukuro.'),
  (@b3, 16, 26, 'O tas, kuris paleido ožį kaip paleidimo ožį, išsiplaus savo drabužius, nusiplaus vandenyje savo kūną, o po to įeis į stovyklą.'),
  (@b3, 16, 27, 'O nuodėmės atnašos jautuką ir nuodėmės atnašos ožį, kurių kraujas buvo įneštas sutaikinimui atlikti šventojoje vietoje, išneš už stovyklos; ir sudegins ugnyje jų odas, jų mėsą ir jų mėšlą.'),
  (@b3, 16, 28, 'O tas, kuris juos sudegins, išsiplaus savo drabužius, nusiplaus vandenyje kūną, ir po to jis įeis į stovyklą.'),
  (@b3, 16, 29, 'Ir tas bus jums amžinas įstatas: septintąjį mėnesį, dešimtąją to mėnesio dieną, jūs varginsite savo sielas ir visiškai nedirbsite darbo, ar tai būtų tėvynainis, ar ateivis, laikinai apsigyvenęs tarp jūsų;'),
  (@b3, 16, 30, 'nes tą dieną kunigas atliks sutaikinimą už jus jūsų apvalymui, kad būtumėte švarūs nuo visų savo nuodėmių VIEŠPATIES akivaizdoje.'),
  (@b3, 16, 31, 'Tai bus jums poilsio sabatas, ir jūs varginsite savo sielas pagal amžinąjį įstatą.'),
  (@b3, 16, 32, 'O kunigas, kurį pateps ir įšventins tarnauti kunigo tarnyboje jo tėvo vietoje, atliks sutaikinimą ir apsivilks lininiais apdarais, būtent šventais drabužiais;'),
  (@b3, 16, 33, 'ir atliks sutaikinimą už šventąją šventovę, ir jis atliks sutaikinimą už susirinkimo padangtę ir už aukurą, ir jis atliks sutaikinimą už kunigus ir už visą susirinkimo tautą.'),
  (@b3, 16, 34, 'Ir tai jums bus amžinas įstatas, kartą metuose atlikti sutaikinimą už Izraelio vaikus dėl visų jų nuodėmių“. Ir jis padarė, kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 17, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 17, 2, '„Kalbėk Aaronui, jo sūnums bei visiems Izraelio vaikams ir jiems sakyk: ‘Štai ką VIEŠPATS įsakė, sakydamas:'),
  (@b3, 17, 3, 'Kas bebūtų iš Izraelio namų, kuris papjautų jautį ar avinėlį, ar ožką stovykloje, ar kuris tai papjautų už stovyklos'),
  (@b3, 17, 4, 'ir jo neatgabentų prie susirinkimo padangtės durų, atnašauti atnašą VIEŠPAČIUI prieš VIEŠPATIES padangtę; kraujas bus priskirtas tam žmogui; jis yra praliejęs kraują; ir tas žmogus bus iškirstas iš savo tautos tarpo;'),
  (@b3, 17, 5, 'tuo tikslu, kad Izraelio vaikai atgabentų savo aukas, kurias jie atnašauja atvirame lauke, kad jie atgabentų jas VIEŠPAČIUI prie susirinkimo padangtės durų pas kunigą ir atnašautų jas kaip taikos atnašas VIEŠPAČIUI.'),
  (@b3, 17, 6, 'O kunigas šlakstys kraują ant VIEŠPATIES aukuro prie susirinkimo padangtės durų ir sudegins taukus kaip gardų kvapą VIEŠPAČIUI.'),
  (@b3, 17, 7, 'Ir jie daugiau nebeatnašaus savo aukų velniams, paskui kuriuos jie nuėjo paleistuvauti. Šitas jiems bus amžinas įstatas per jų kartas’“.'),
  (@b3, 17, 8, '„Ir jiems sakyk: ‘Kas bebūtų iš Izraelio namų ar iš ateivių, laikinai apsigyvenusių tarp jūsų, kuris atnašaus deginamąją atnašą ar auką'),
  (@b3, 17, 9, 'ir jos neatgabens prie susirinkimo padangtės durų, ją atnašauti VIEŠPAČIUI; tas žmogus bus iškirstas iš savo tautos tarpo.'),
  (@b3, 17, 10, 'Ir kas bebūtų iš Izraelio namų ar iš ateivių, laikinai apsigyvenusių tarp jūsų, kuris valgytų bet kokio kraujo; aš nukreipsiu savo veidą prieš tą sielą, kuri valgo kraują, ir ją iškirsiu iš jos tautos tarpo.'),
  (@b3, 17, 11, 'Nes kūno gyvybė yra kraujyje; ir aš jums daviau jį ant aukuro, atlikti sutaikinimui už jūsų sielas; nes tai kraujas, kuris atlieka sutaikinimą už sielą.'),
  (@b3, 17, 12, 'Todėl pasakiau Izraelio vaikams: „Jokia siela iš jūsų nevalgys kraujo, nei joks ateivis, laikinai apsigyvenęs tarp jūsų, nevalgys kraujo“.'),
  (@b3, 17, 13, 'Ir kas bebūtų iš Izraelio vaikų ar iš ateivių, laikinai apsigyvenusių tarp jūsų, kuris medžios ir pagaus kokį žvėrį ar skrajūną, kurį galima valgyti; jis išlies jo kraują ir jį uždengs dulkėmis.'),
  (@b3, 17, 14, 'Nes jis yra gyvybė kiekvieno kūno; jo kraujas yra jo gyvybei; todėl aš pasakiau Izraelio vaikams: „Jūs nevalgysite jokio kūno kraujo; nes kiekvieno kūno gyvybė yra jo kraujas; kas jį valgys, tas bus iškirstas“.'),
  (@b3, 17, 15, 'Ir kiekviena siela, ar tai būtų tėvynainis, ar ateivis, kuris valgys, kas padvėsę ar žvėrių sudraskyta, išplaus savo drabužius ir nusiplaus vandenyje, ir bus nešvarus iki vakaro; po to jis bus švarus.'),
  (@b3, 17, 16, 'Bet jei jis jų neišplaus nei nenusiplaus kūno; tada jis nešios savo neteisybę’“.'),
  (@b3, 18, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 18, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 18, 3, 'Nesielkite pagal darbus Egipto šalies, kurioje gyvenote; ir nesielkite pagal darbus Kanaano šalies, į kurią aš jus įvesiu; nei nevaikščiokite pagal jų įsakus.'),
  (@b3, 18, 4, 'Vykdykite mano teismus ir laikykitės mano įsakų, kad jais vaikščiotumėte: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 18, 5, 'Todėl laikykitės mano įstatų ir mano teismų, kuriuos vykdydamas žmogus jais gyvens: aš esu VIEŠPATS.'),
  (@b3, 18, 6, 'Nei vienas iš jūsų nesiartinkite prie kokio nors savo artimo giminaičio, atidengti jo nuogumo: aš esu VIEŠPATS.'),
  (@b3, 18, 7, 'Neatidenk savo tėvo nuogumo ar savo motinos nuogumo; ji yra tavo motina; neatidenk jos nuogumo.'),
  (@b3, 18, 8, 'Neatidenk savo tėvo žmonos nuogumo: tai yra tavo tėvo nuogumas.'),
  (@b3, 18, 9, 'Nuogumo savo sesers, tavo tėvo dukters ar tavo motinos dukters, gimusios namuose ar gimusios svetur – jų nuogumo neatidenk.'),
  (@b3, 18, 10, 'Nuogumo savo sūnaus dukters ar savo dukters dukros – jų nuogumo neatidenk; nes jų nuogumas yra tavo nuogumas.'),
  (@b3, 18, 11, 'Nuogumo savo tėvo žmonos dukters, pagimdytos tavo tėvo, ji yra tavo sesuo – jos nuogumo neatidenk.'),
  (@b3, 18, 12, 'Neatidenk savo tėvo sesers nuogumo – ji yra tavo tėvo artima giminaitė.'),
  (@b3, 18, 13, 'Neatidenk savo motinos sesers nuogumo, nes ji yra tavo motinos artima giminaitė.'),
  (@b3, 18, 14, 'Neatidenk savo tėvo brolio nuogumo, nesiartink prie jo žmonos – ji yra tavo teta.'),
  (@b3, 18, 15, 'Neatidenk savo marčios nuogumo – ji yra tavo sūnaus žmona; neatidenk jos nuogumo.'),
  (@b3, 18, 16, 'Neatidenk savo brolio žmonos nuogumo – tai yra tavo brolio nuogumas.'),
  (@b3, 18, 17, 'Neatidenk moters ir jos dukters nuogumo nei neimk jos sūnaus dukters ar jos dukters dukros, kad atidengtum jos nuogumą; nes jos yra jos artimos giminaitės; tai yra nedorybė.'),
  (@b3, 18, 18, 'Neimk žmonos su jos seserimi, kad ją vargintum, kad atidengtum jos nuogumą prie kitos, jai gyvai esant.'),
  (@b3, 18, 19, 'Taip pat nepriartėk prie moters, kad atidengtum jos nuogumą, kol ji yra atskirta dėl jos nešvarumo.'),
  (@b3, 18, 20, 'Be to, nesugulk su savo artimo žmona kūniškai, kad su ja susiterštum.'),
  (@b3, 18, 21, 'Nei vieno iš savo sėklos neleisk perleisti per ugnį Molechui nei nesuteršk savo Dievo vardo – aš esu VIEŠPATS.'),
  (@b3, 18, 22, 'Nesugulk su vyriškiu kaip su moteriške: tai yra bjaurastis.'),
  (@b3, 18, 23, 'Nei nesugulk su jokiu gyvuliu, kad juo susiterštum; taip pat jokia moteris teneatsistoja priešais gyvulį, kad tam atsigultų – tai yra bjaurastis.'),
  (@b3, 18, 24, 'Nesusiterškite nei vienu iš šitų dalykų; nes visais šitais yra susiteršusios tautos, kurias aš išvarau iš jūsų akivaizdos;'),
  (@b3, 18, 25, 'ir ta šalis yra suteršta; todėl aš aplankau jos neteisybę ant jos, ir pati šalis išvemia savo gyventojus.'),
  (@b3, 18, 26, 'Todėl laikykitės mano įstatų ir mano teismų, ir nei vienas jūsų tėvynainis ir nei joks ateivis, laikinai apsigyvenęs tarp jūsų, nedarykite nei vienos iš šitų bjaurasčių'),
  (@b3, 18, 27, '(nes visas tas bjaurastis darė šios šalies žmonės, kurie buvo pirma jūsų, ir šalis yra suteršta);'),
  (@b3, 18, 28, 'kad šalis, jums ją suteršus, taip pat ir jūsų neišspjautų, kaip ji išspjovė tautas, buvusias pirma jūsų.'),
  (@b3, 18, 29, 'Nes kiekvienas, kuris darys kokią nors iš šitų bjaurysčių, tos sielos, kurios tai darys, bus iškirstos iš savo tautos tarpo.'),
  (@b3, 18, 30, 'Todėl laikykitės mano įsako, kad nedarytumėte nei vieno iš šitų bjaurių papročių, kurie buvo daromi pirma jūsų, kad jūs nesusiterštumėte jais: aš esu VIEŠPATS, jūsų Dievas’“.'),
  (@b3, 19, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 19, 2, '„Kalbėk visam Izraelio vaikų susirinkimui ir jiems sakyk: ‘Būkite šventi; nes aš VIEŠPATS, jūsų Dievas, esu šventas.'),
  (@b3, 19, 3, 'Kiekvienas bijokite savo motinos bei savo tėvo ir laikykitės mano sabatų: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 19, 4, 'Nesikreipkite į stabus nei nepasidirbkite sau lietų dievų: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 19, 5, 'Ir jei atnašausite taikos atnašų auką VIEŠPAČIUI, atnašaukite tai savo paties noru.'),
  (@b3, 19, 6, 'Ji bus valgoma tą pačią dieną, kai ją atnašausite, ir rytojaus dieną; o jei kas atliks iki trečios dienos, tai bus sudeginta ugnyje.'),
  (@b3, 19, 7, 'O jei trečią dieną kaip nors jos valgys, tai yra pasibjaurėjimas; tai nebus priimtina.'),
  (@b3, 19, 8, 'Todėl, kas jos valgys, tas nešios savo neteisybę, nes jis yra suteršęs tai, kas yra VIEŠPATIES šventa; ir ta siela bus iškirsta iš savo tautos tarpo.'),
  (@b3, 19, 9, 'Ir jums nuimant savo žemės derlių, visiškai nenuimk savo lauko pakraščių nei nesurink savo derliaus parankų.'),
  (@b3, 19, 10, 'Ir nenurankiok savo vynuogyno nei nesurink visų savo vynuogyno vynuogių; palik jas beturčiui ir ateiviui: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 19, 11, 'Nevokite, nesielkite apgaulingai ir nemeluokite vienas kitam.'),
  (@b3, 19, 12, 'Ir neprisiekite melagingai mano vardu nei nesuterškite savo Dievo vardo: aš esu VIEŠPATS.'),
  (@b3, 19, 13, 'Neapgaudinėk savo artimo nei jo neapiplėšk; samdinio alga nepasiliks pas tave per visą naktį.'),
  (@b3, 19, 14, 'Neprakeik kurčiojo nei nepadėk kliuvinio prieš akląjį, bet bijok savo Dievo: aš esu VIEŠPATS.'),
  (@b3, 19, 15, 'Nedarykite neteisumo teisme; neatsižvelk į beturčio asmenį nei nesuteik pagarbos galingojo asmeniui; bet teisumu teisk savo artimą.'),
  (@b3, 19, 16, 'Nevaikštinėk kaip liežuvautojas tarp savo tautos; nei nesistok prieš savo artimo kraują: aš esu VIEŠPATS.'),
  (@b3, 19, 17, 'Tau nevalia nekęsti savo brolio savo širdyje; visaip bark savo artimą, ir neapkęsk jame nuodėmės.'),
  (@b3, 19, 18, 'Nekeršyk nei nesinešiok jokios pagiežos prieš savo tautos vaikus, bet mylėk savo artimą kaip save patį: aš esu VIEŠPATS.'),
  (@b3, 19, 19, 'Laikykitės mano įstatų. Neleisk savo galvijams sueiti su skirtinga veisle; neapsėk savo lauko maišyta sėkla; nei drabužis, sumaišytas iš lininių ir vilnonių, neužeis ant tavęs.'),
  (@b3, 19, 20, 'Ir kas suguls kūniškai su moterimi, kuri yra vergė, susižadėjusi su vyru ir visiškai neišpirkta, nei jai duota laisvė; ji bus nuplakta; jie nebus užmušti, nes ji nebuvo laisva.'),
  (@b3, 19, 21, 'Ir jis atgabens savo nusižengimo atnašą VIEŠPAČIUI prie susirinkimo padangtės durų – aviną nusižengimo atnašai.'),
  (@b3, 19, 22, 'O kunigas atliks už jį sutaikinimą nusižengimo atnašos avinu VIEŠPATIES akivaizdoje už jo nuodėmę, kurią jis padarė; ir nuodėmė, kurią jis padarė, bus jam atleista.'),
  (@b3, 19, 23, 'Ir kai įeisite į šalį ir pasodinsite visokių medžių maistui, tada laikysite jų vaisių kaip neapipjaustytą; tris metus jis bus jums kaip neapipjaustytas; jo nebus valgoma.'),
  (@b3, 19, 24, 'Bet ketvirtaisiais metais visi jų vaisiai bus šventi, jais girti VIEŠPATĮ.'),
  (@b3, 19, 25, 'O penktaisiais metais valgysite jų vaisių, kad jie duotų jums savo prieaugį: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 19, 26, 'Nieko nevalgykite su krauju; nei neužsiiminėkite kerais, nei nesilaikykite laikų.'),
  (@b3, 19, 27, 'Neapvalinkite savo galvos kraštų nei nedarkykite savo barzdos kraštų.'),
  (@b3, 19, 28, 'Nedarykite jokių įpjovimų savo kūne dėl mirusio nei nesispausdinkite jokių ženklų ant savęs: aš esu VIEŠPATS.'),
  (@b3, 19, 29, 'Neparduok savo dukters, versdamas ją paleistuvauti; kad šalis nenupultų į paleistuvystę ir šalis nepasidarytų pilna nedorybės.'),
  (@b3, 19, 30, 'Laikykitės mano sabatų ir gerbkite mano šventovę: aš esu VIEŠPATS.'),
  (@b3, 19, 31, 'Nesikreipkite į turinčius namų dvasias nei nesivaikykite burtininkų, kad jais nesusiterštumėte: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 19, 32, 'Atsistok prieš žilą galvą, gerbk senio veidą ir bijok savo Dievo: aš esu VIEŠPATS.'),
  (@b3, 19, 33, 'Ir jei ateivis laikinai apsigyvens pas tave, jūsų šalyje, jo nespauskite.'),
  (@b3, 19, 34, 'Bet ateivis, gyvenantis pas jus, jums bus kaip tarp jūsų gimęs, mylėk jį kaip save patį; nes jūs buvote ateiviai Egipto šalyje: aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 19, 35, 'Nedarykite teisme neteisumo ilgio matu, svoriu ar saiku.'),
  (@b3, 19, 36, 'Turėkite teisingas svarstykles, teisingus svarsčius, teisingą efą ir teisingą hiną: aš esu VIEŠPATS, jūsų Dievas, kuris jus išvedžiau iš Egipto šalies.'),
  (@b3, 19, 37, 'Todėl laikykitės visų mano įstatų bei visų mano teismų ir juos vykdykite: aš esu VIEŠPATS’“.'),
  (@b3, 20, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 20, 2, '„Vėl sakyk Izraelio vaikams: ‘Kas iš Izraelio vaikų ar ateivių, laikinai apsigyvenusių Izraelyje, duos kurį nors iš savo sėklos Molechui; tas tikrai bus užmuštas; šalies tauta jį užmėtys akmenimis.'),
  (@b3, 20, 3, 'Ir aš nukreipsiu savo veidą prieš tą žmogų ir jį iškirsiu iš jo tautos tarpo; nes davė iš savo sėklos Molechui, kad suterštų mano šventovę ir išniekintų mano šventąjį vardą.'),
  (@b3, 20, 4, 'O jei šalies tauta kokiu būdu paslėps savo akis nuo to žmogaus, kai šis duos iš savo sėklos Molechui, ir jo neužmuš;'),
  (@b3, 20, 5, 'tada aš nukreipsiu savo veidą prieš tą žmogų bei prieš jo šeimą ir iškirsiu iš jų tautos tarpo jį ir visus, kurie paleistuvaudami juo seka, kad paleistuvautų su Molechu.'),
  (@b3, 20, 6, 'O siela, kuri kreipsis į turinčius namų dvasias ir į burtininkus, kad paleistuvaudama jais sektų, aš nukreipsiu savo veidą prieš tą sielą ir ją iškirsiu iš jos tautos tarpo.'),
  (@b3, 20, 7, 'Todėl pasišvęskite ir būkite šventi; nes aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 20, 8, 'Ir laikykitės mano įstatų ir juos vykdykite: aš esu VIEŠPATS, kuris jus pašvenčiu.'),
  (@b3, 20, 9, 'Nes kiekvienas, kuris prakeiks savo tėvą ar motiną, tikrai bus užmuštas; jis prakeikė savo tėvą ar motiną; jo kraujas bus ant jo’.'),
  (@b3, 20, 10, 'O kuris svetimaus su kito vyro žmona, būtent tas, kuris svetimaus su savo artimo žmona, svetimautojas ir svetimautoja tikrai bus užmušti.'),
  (@b3, 20, 11, 'O vyras, kuris suguls su savo tėvo žmona, bus atidengęs savo tėvo nuogumą; jie abu tikrai bus užmušti; jų kraujas bus ant jų.'),
  (@b3, 20, 12, 'O jei vyras suguls su savo marčia, jie abu tikrai bus užmušti – jie atliko sumaišymą; jų kraujas bus ant jų.'),
  (@b3, 20, 13, 'Taip pat jei vyras suguls su vyru kaip sugula su moterimi, jie abu bus padarę bjaurastį; jie tikrai bus užmušti; jų kraujas bus ant jų.'),
  (@b3, 20, 14, 'O jei vyras ima žmoną ir jos motiną, tai yra nedorybė; jie bus sudeginti ugnimi – jis ir jos; kad nebūtų nedorybės tarp jūsų.'),
  (@b3, 20, 15, 'O jei vyras suguls su gyvuliu, jis tikrai bus užmuštas; ir gyvulį užmušite.'),
  (@b3, 20, 16, 'Ir jei moteris priartės prie kokio gyvulio ir jam atsiguls, užmušk tą moterį ir tą gyvulį; jie tikrai bus užmušti; jų kraujas bus ant jų.'),
  (@b3, 20, 17, 'Ir jei vyras ims savo seserį, savo tėvo dukterį ar savo motinos dukterį ir pamatys jos nuogumą, o ta pamatys jo nuogumą; tai yra nedorybė; ir jie bus iškirsti jų tautos akyse; jis atidengė savo sesers nuogumą; jis nešios savo neteisybę.'),
  (@b3, 20, 18, 'Ir jei vyras suguls su moterimi, turinčia savo ligą, ir atidengs jos nuogumą; jis bus atidengęs jos šaltinį ir ji bus atidengusi savo kraujo šaltinį; ir jie abu bus iškirsti iš savo tautos tarpo.'),
  (@b3, 20, 19, 'Neatidenk savo motinos sesers nei savo tėvo sesers nuogumo; nes toks atidengia savo artimą giminaitį; jie nešios savo neteisybę.'),
  (@b3, 20, 20, 'Ir jei vyras suguls su savo dėdės žmona, jis bus atidengęs savo dėdės nuogumą; jie nešios savo nuodėmę; jie mirs bevaikiai.'),
  (@b3, 20, 21, 'O jei vyras ims savo brolio žmoną, tai yra nešvarumas; jis bus atidengęs savo brolio nuogumą; jie bus bevaikiai.'),
  (@b3, 20, 22, 'Todėl laikykitės visų mano įstatų bei visų mano teismų ir juos vykdykite; kad jūsų neišspjautų šalis, į kurią jus įvesiu, kad joje gyventumėte.'),
  (@b3, 20, 23, 'Ir nevaikščiokite pagal papročius tautos, kurią aš išvarysiu jūsų akivaizdoje; nes jie visa tai darė, ir todėl aš jais pasibjaurėjau.'),
  (@b3, 20, 24, 'Bet aš jums tariau: Jūs paveldėsite jų šalį, ir aš ją jums duosiu, kad ją pasisavintumėte, šalį, plūstančią pienu ir medumi: aš esu VIEŠPATS, jūsų Dievas, kuris jus atskyriau nuo kitų tautų.'),
  (@b3, 20, 25, 'Todėl jūs atskirkite švarų gyvulį nuo nešvaraus ir nešvarų skrajūną nuo švaraus; ir neapsibjaurinkite savo sielų gyvuliu ar skrajūnu, ar bet kokiu gyvu padaru, ropojančiu ant žemės, kuriuos aš atskyriau nuo jūsų kaip nešvarius.'),
  (@b3, 20, 26, 'Būsite man šventi; nes aš, VIEŠPATS, esu šventas ir jus atskyriau nuo kitų tautų, kad būtumėte mano.'),
  (@b3, 20, 27, 'Taip pat vyras ar moteris, turintys namų dvasią ar esantys burtininkai, tikrai bus užmušti; juos užmėtys akmenimis – jų kraujas bus ant jų“.'),
  (@b3, 21, 1, 'Ir VIEŠPATS tarė Mozei: „Kalbėk kunigams, Aarono sūnums, ir sakyk jiems: ‘Nei vienas tenesusiterš dėl mirusiojo tarp savo tautos;'),
  (@b3, 21, 2, 'bet dėl savo giminaičių, kurie yra jam artimi, tai yra, dėl savo motinos, dėl savo tėvo, dėl savo sūnaus, dėl savo dukters, dėl savo brolio,'),
  (@b3, 21, 3, 'dėl savo sesers, mergelės, jam artimos, kuri neturėjusi vyro; dėl jos jis gali susiteršti.'),
  (@b3, 21, 4, 'Bet tenesusiteršia jis, būdamas vadas tarp savo tautos, kad savęs nesuterštų.'),
  (@b3, 21, 5, 'Jie tenesidaro plikės ant savo galvos, taip pat tenenuskuta savo barzdos kraštų ir tenesidaro savo kūne įpjovų.'),
  (@b3, 21, 6, 'Jie bus šventi savo Dievui ir neniekins savo Dievo vardo; nes jie atnašauja VIEŠPATIES ugnies atnašas ir savo Dievo duoną; todėl jie bus šventi.'),
  (@b3, 21, 7, 'Jie neims žmonos, kuri yra paleistuvė ar suteršta; taip pat jie neims moters, nuo savo vyro atmestos; nes jis yra šventas savo Dievui.'),
  (@b3, 21, 8, 'Todėl jį pašvęsk; nes jis atnašauja tavo Dievo duoną; jis tau bus šventas; nes šventas esu aš, VIEŠPATS, kuris jus pašvenčiu.'),
  (@b3, 21, 9, 'O jei kurio kunigo duktė susiterš paleistuvavimu, ji suterš savo tėvą; ji bus sudeginta ugnimi.'),
  (@b3, 21, 10, 'O kas yra aukščiausiasis kunigas tarp savo brolių, ant kurio galvos buvo išpiltas patepimo aliejus ir kuris yra įšventintas, kad apsivilktų tais drabužiais, neatidengs savo galvos nei nepersiplėš savo drabužių;'),
  (@b3, 21, 11, 'taip pat jis neįeis pas jokį mirusį kūną nei nesusiterš dėl savo tėvo ar dėl savo motinos;'),
  (@b3, 21, 12, 'taip pat neišeis jis iš šventovės nei nesuterš savo Dievo šventovės; nes ant jo yra jo Dievo patepimo aliejaus vainikas: aš esu VIEŠPATS.'),
  (@b3, 21, 13, 'Ir jis teima žmoną jos nekaltybėje.'),
  (@b3, 21, 14, 'Našlės ar išsiskyrusios moters, ar suterštos, ar paleistuvės – šitų jis neims; bet jis ims į žmonas mergelę iš savo paties tautos.'),
  (@b3, 21, 15, 'Jis tenesuterš savo sėklos tarp savo tautos; nes aš, VIEŠPATS, jį pašvenčiu’“.'),
  (@b3, 21, 16, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 21, 17, '„Kalbėk Aaronui, sakydamas: ‘Nei vienas iš tavo sėklos jų kartose, turintis kokį trūkumą, nesiartins savo Dievo duonos atnašauti.'),
  (@b3, 21, 18, 'Nesiartins joks turintis trūkumą, ar jis būtų neregys, ar raišas, ar turintis plokščią nosį, ar ką tai nereikalingo,'),
  (@b3, 21, 19, 'ar sulaužtakojis, ar sulaužtarankis,'),
  (@b3, 21, 20, 'ar kuprius, ar neūžauga, ar turintis trūkumų akyje, ar sergantis skorbutu, ar nušašęs, ar turintis sutrėkštas sėklides;'),
  (@b3, 21, 21, 'nei vienas iš kunigo Aarono sėklos, turintis trūkumų, nesiartins VIEŠPATIES ugnies atnašų atnašauti; jis turi trūkumą; jis nesiartins savo Dievo duonos atnašauti.'),
  (@b3, 21, 22, 'Jis valgys savo Dievo duonos iš švenčiausių ir iš šventų.'),
  (@b3, 21, 23, 'Tik jis neįeis prie uždangos nei nepriartės prie aukuro, nes jis turi trūkumą; kad jis nesuterštų mano šventovių; nes aš, VIEŠPATS, jas pašvenčiu’“.'),
  (@b3, 21, 24, 'Ir Mozė tai pasakė Aaronui bei jo sūnums ir visiems Izraelio vaikams.'),
  (@b3, 22, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 22, 2, '„Kalbėk Aaronui ir jo sūnums, kad jie atsiskirtų nuo Izraelio vaikų šventų dalykų ir nesuterštų mano šventojo vardo tais dalykais, kuriuos jie man pašvenčia; aš esu VIEŠPATS.'),
  (@b3, 22, 3, 'Sakyk jiems: ‘Kas bebūtų iš visos jūsų sėklos tarp jūsų kartų, kuris, turintis ant savęs savo nešvarumą, eitų prie šventų dalykų, kuriuos Izraelio vaikai pašvenčia VIEŠPAČIUI, ta siela bus iškirsta iš mano akivaizdos: aš esu VIEŠPATS.'),
  (@b3, 22, 4, 'Kas iš Aarono sėklos yra raupsuotas ar turintis plūdimą, tas nevalgys šventų dalykų, kol nebus švarus. Ir kas palies tai, kas yra nešvaru nuo mirusio, ar vyrą, iš kurio išsilieja jo sėkla;'),
  (@b3, 22, 5, 'ar kas palies kokį roplį, kuriuo jis taps nešvariu, ar žmogų, iš kurio jis perims nešvarumą, kokį nešvarumą jis beturėtų;'),
  (@b3, 22, 6, 'ta siela, kuri bus ką nors tokio palietusi, bus nešvari iki vakaro ir nevalgys šventų dalykų, nebent ji nuplaus savo kūną vandeniu.'),
  (@b3, 22, 7, 'O saulei nusileidus, jis bus švarus ir po to valgys šventų dalykų; nes tai yra jo maistas.'),
  (@b3, 22, 8, 'Jis nevalgys maitos ar žvėrių sudraskyto, kad tuo nesusiterštų: aš esu VIEŠPATS.'),
  (@b3, 22, 9, 'Todėl jie laikysis mano įsako, kad dėl jo jiems netektų nešioti nuodėmės ir dėl to mirti, jeigu jie jį suterštų: aš VIEŠPATS juos pašvenčiu.'),
  (@b3, 22, 10, 'Joks pašalietis nevalgys to, kas šventa; laikinai apsigyvenęs pas kunigą ar samdinys nevalgys to, kas šventa.'),
  (@b3, 22, 11, 'Bet jei kunigas nusipirks kokią sielą už pinigus, ji iš to valgys ir gimusysis jo namuose; jie valgys iš jo maisto.'),
  (@b3, 22, 12, 'Taip pat jei kunigo duktė ištekės už pašaliečio, ji nevalgys iš šventų dalykų atnašos.'),
  (@b3, 22, 13, 'Bet jei kunigo duktė būtų našlė ar išsiskyrusi ir neturinti vaikų, ir yra sugrįžusi į savo tėvo namus kaip savo jaunystėje, tai ji valgys savo tėvo maisto; bet joks pašalietis to nevalgys.'),
  (@b3, 22, 14, 'O jei kas nežiniomis valgys to, kas šventa, tuomet jis prie to pridės to penktąją dalį ir duos tai kunigui su tuo šventuoju dalyku.'),
  (@b3, 22, 15, 'Ir jie tenesuteršia Izraelio vaikų šventųjų dalykų, kuriuos jie atnašauja VIEŠPAČIUI;'),
  (@b3, 22, 16, 'arba teleidžia jiems nešioti nusižengimo neteisybę, kai jie valgys jų šventus dalykus; nes aš, VIEŠPATS, juos pašvenčiu’“.'),
  (@b3, 22, 17, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 22, 18, '„Kalbėk Aaronui bei jo sūnums ir visiems Izraelio vaikams ir jiems sakyk: ‘Kai kas nors iš Izraelio namų ar iš ateivių Izraelyje norės atnašauti savo auką už visus savo įžadus ir už visas savo laisvanoriškas atnašas, kurias jie norės atnašauti VIEŠPAČIUI kaip deginamąją atnašą;'),
  (@b3, 22, 19, 'atnašaukite savo paties noru patiną be trūkumų iš galvijų, iš avių ar iš ožkų.'),
  (@b3, 22, 20, 'Bet jokio, turinčio trūkumų, neaukokite; nes tai nebus priimtina dėl jūsų.'),
  (@b3, 22, 21, 'Ir kas atnašaus VIEŠPAČIUI taikos atnašų auką, kad atliktų savo įžadą, ar laisvos valios atnašą, galvijais ar avimis, ji bus tobula, kad būtų priimtina; joje nebus jokio trūkumo.'),
  (@b3, 22, 22, 'Aklo ar sulaužyto, ar luošo, ar turinčio lipomą, ar sergančio skorbutu, ar šašuoto – šitų neaukokite VIEŠPAČIUI nei neatlikite iš jų ant aukuro ugnies atnašos VIEŠPAČIUI.'),
  (@b3, 22, 23, 'Arba jautuką ar avinėlį, turintį savo kūno dalyse kažką atliekamo ar trūkstamo, tu gali atnašauti kaip savanorišką atnašą; bet jis nebus priimtinas dėl įžado.'),
  (@b3, 22, 24, 'Sumušto ar sutraiškyto, ar sulaužyto, ar supjaustyto, neaukokite VIEŠPAČIUI; nei neatlikinėkite jais jokių atnašų savo šalyje.'),
  (@b3, 22, 25, 'Nei iš svetimšalio rankos neaukokite savo Dievo duonos iš jokių šitų; nes jų sugedimas yra juose, trūkumai yra juose; jie nebus priimtini dėl jūsų’“.'),
  (@b3, 22, 26, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 22, 27, '„Kai gims jautukas ar avis, ar ožiukas, tuomet jis septynias dienas bus po motina; o nuo aštuntos dienos ir toliau jis bus priimtinas kaip ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 22, 28, 'Ir ar tai būtų karvė, ar avis, nepjaukite jos tą pačią dieną su jos jaunikliu.'),
  (@b3, 22, 29, 'O kai atnašausite padėkos auką VIEŠPAČIUI, atnašaukite ją savo paties laisva valia.'),
  (@b3, 22, 30, 'Ji bus suvalgyta tą pačią dieną; nieko iš jos nepalikite iki rytojaus: aš esu VIEŠPATS.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b3, 22, 31, 'Todėl laikykitės mano įsakymų ir juos vykdykite: aš esu VIEŠPATS.'),
  (@b3, 22, 32, 'Nesuterškite mano šventojo vardo; bet aš būsiu pašvenčiamas tarp Izraelio vaikų: aš esu VIEŠPATS, kuris jus pašvenčiu,'),
  (@b3, 22, 33, 'kuris jus išvedžiau iš Egipto šalies, kad būčiau jūsų Dievas: aš esu VIEŠPATS“.'),
  (@b3, 23, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 23, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Dėl VIEŠPATIES švenčių, kurias paskelbsite šventais sušaukimais – šitos yra mano šventės.'),
  (@b3, 23, 3, 'Šešias dienas bus dirbamas darbas; bet septintoji diena yra poilsio sabatas, šventas sušaukimas; jokio darbo jame nedirbsite: tai yra VIEŠPATIES sabatas visose jūsų buveinėse.'),
  (@b3, 23, 4, 'Šitos yra VIEŠPATIES šventės, šventi sušaukimai, kuriuos paskelbsite jų metu.'),
  (@b3, 23, 5, 'Pirmojo mėnesio, keturioliktąją dieną, vakare, yra VIEŠPATIES Apėjimas.'),
  (@b3, 23, 6, 'O penkioliktąją to paties mėnesio dieną yra Neraugintos duonos šventė VIEŠPAČIUI; septynias dienas valgysite neraugintą duoną.'),
  (@b3, 23, 7, 'Pirmąją dieną turėsite šventą sušaukimą; joje nedirbkite jokio tarnavimo darbo.'),
  (@b3, 23, 8, 'Bet septynias dienas atnašaukite ugnies atnašą VIEŠPAČIUI; septintąją dieną yra šventas sušaukimas; joje nedirbkite jokio tarnavimo darbo’“.'),
  (@b3, 23, 9, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 23, 10, '„Kalbėk Izraelio vaikams, ir jiems sakyk: ‘Kai įeisite į šalį, kurią aš jums duodu, ir pjausite jos derlių, tada atnešite savo derliaus pirmavaisių pėdą kunigui;'),
  (@b3, 23, 11, 'o jis mosuos pėdą VIEŠPATIES akivaizdoje, kad būtų priimtinas dėl jūsų; rytojaus dieną po sabato kunigas jį mosuos.'),
  (@b3, 23, 12, 'Ir tą dieną, kai mosuosite pėdą, atnašausite pirmųjų metų avinėlį be trūkumų, kaip deginamąją atnašą VIEŠPAČIUI.'),
  (@b3, 23, 13, 'Ir jos maisto atnaša bus du dešimtadaliai smulkių miltų, sumaišytų su aliejumi, ugnies atnaša VIEŠPAČIUI, kaip gardus kvapas; ir jos geriamoji atnaša bus iš vyno – ketvirtadalis hino.'),
  (@b3, 23, 14, 'Ir jūs nevalgykite nei duonos, nei paskrudintų grūdų, nei žalių varpų iki pačios tos dienos, kai būsite atgabenę atnašą savo Dievui; tai bus amžinas įstatas per jūsų kartas visose jūsų buveinėse.'),
  (@b3, 23, 15, 'Ir atskaičiuokite sau nuo rytojaus dienos po sabato, nuo tos dienos, kai atnešėte mosuojamosios atnašos pėdą; bus užbaigti septyni sabatai;'),
  (@b3, 23, 16, 'rytojaus dienai po septintojo sabato suskaičiuokite penkiasdešimt dienų; ir atnašaukite naują maisto atnašą VIEŠPAČIUI.'),
  (@b3, 23, 17, 'Iš savo buveinių atneškite du mosuojamus kepalus iš dviejų dešimtadalių; jie bus iš smulkių miltų; jie bus iškepti su raugu; jie yra pirmavaisiai VIEŠPAČIUI.'),
  (@b3, 23, 18, 'Ir su duona atnašaukite septynis pirmųjų metų avinėlius be trūkumų, vieną jauniklį jautuką ir du avinus; jie bus kaip deginamoji atnaša VIEŠPAČIUI su jų maisto atnaša ir jų geriamąja atnaša, tai yra gardaus kvapo ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 23, 19, 'Paskui aukokite vieną ožiuką nuodėmės atnašai ir du pirmųjų metų avinėlius taikos atnašų aukai.'),
  (@b3, 23, 20, 'O kunigas juos mosuos su pirmavaisių duona mosuojamajai atnašai VIEŠPATIES akivaizdoje su dviem avinėliais; jie bus šventi VIEŠPAČIUI, skirti kunigui.'),
  (@b3, 23, 21, 'Ir tą pačią dieną paskelbsite, kad jums būtų šventas sušaukimas; joje nedirbsite jokio tarnavimo darbo; tai bus amžinas įstatas visose jūsų buveinėse per jūsų kartas.'),
  (@b3, 23, 22, 'Ir kai imsite savo šalies derlių, imdamas nesuvalyk savo lauko pakraščių nei nenurink savo derliaus parankų; palik tai beturčiui ir ateiviui: aš esu VIEŠPATS, jūsų Dievas’“.'),
  (@b3, 23, 23, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 23, 24, '„Kalbėk Izraelio vaikams, sakydamas: ‘Septintąjį mėnesį, to mėnesio pirmąją dieną, turėsite sabatą, trimitavimo priminimą, šventą sušaukimą.'),
  (@b3, 23, 25, 'Joje nedirbkite jokio tarnavimo darbo; bet atnašaukite ugnies atnašą VIEŠPAČIUI’“.'),
  (@b3, 23, 26, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 23, 27, '„Taip pat dešimtąją šito septintojo mėnesio dieną bus Sutaikinimo diena; jums tai bus šventas sušaukimas; o jūs varginsite savo sielas ir atnašausite ugnies atnašą VIEŠPAČIUI.'),
  (@b3, 23, 28, 'Tąją dieną nedirbkite jokio darbo; nes tai yra Sutaikinimo diena, sutaikinimui už jus atlikti VIEŠPATIES, jūsų Dievo, akivaizdoje.'),
  (@b3, 23, 29, 'Nes ta siela, kuri tąją dieną nesivargins, bus iškirsta iš savo tautos tarpo.'),
  (@b3, 23, 30, 'O ta siela, kuri tąją dieną dirbs bet kokį darbą, tą sielą aš išnaikinsiu iš jos tautos tarpo.'),
  (@b3, 23, 31, 'Nedarykite jokio darbo; tai bus amžinas įstatas per jūsų kartas visose jūsų buveinėse.'),
  (@b3, 23, 32, 'Tai jums bus poilsio sabatas, ir jūs varginsite savo sielas; devintąją to mėnesio dieną vakare, nuo vakaro iki vakaro, švęskite savo sabatą“.'),
  (@b3, 23, 33, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 23, 34, '„Kalbėk Izraelio vaikams, sakydamas: ‘Šito septintojo mėnesio penkioliktąją dieną septynias dienas bus Padangčių šventė VIEŠPAČIUI.'),
  (@b3, 23, 35, 'Pirmąją dieną bus šventas sušaukimas; joje nedirbkite jokio tarnavimo darbo.'),
  (@b3, 23, 36, 'Septynias dienas atnašaukite VIEŠPAČIUI ugnies atnašą; aštuntąją dieną jums bus šventas sušaukimas; ir atnašausite ugnies atnašą VIEŠPAČIUI; tai yra iškilmingas susirinkimas; ir joje nedirbkite jokio tarnavimo darbo.'),
  (@b3, 23, 37, 'Šitos yra VIEŠPATIES šventės, kurias paskelbsite šventais sušaukimais, kad atnašautumėte ugnies atnašą VIEŠPAČIUI, deginamąją atnašą ir maisto atnašą, auką ir geriamąsias atnašas, viską pagal savo dieną;'),
  (@b3, 23, 38, 'neskaitant VIEŠPATIES sabatų, neskaitant jūsų dovanų, neskaitant visų jūsų įžadų ir neskaitant visų jūsų savanoriškų atnašų, kurias duosite VIEŠPAČIUI.'),
  (@b3, 23, 39, 'Taip pat septintojo mėnesio penkioliktąją dieną, kai būsite surinkę šalies vaisių, švęskite VIEŠPAČIUI šventę septynias dienas; pirmąją dieną bus sabatas ir aštuntąją dieną bus sabatas.'),
  (@b3, 23, 40, 'Ir pirmąją dieną pasiimkite šakų iš gražių medžių, palmių šakų, tankių medžių šakų bei upelio gluosnių; ir linksminkitės VIEŠPATIES, savo Dievo, akivaizdoje septynias dienas.'),
  (@b3, 23, 41, 'Ir ją švęskite kaip šventę VIEŠPAČIUI septynias dienas metuose. Tai bus amžinas įstatas jūsų kartose; ją švęskite septintąjį mėnesį.'),
  (@b3, 23, 42, 'Pastogėse gyvenkite septynias dienas; visi gimę izraelitais gyvens pastogėse;'),
  (@b3, 23, 43, 'kad jūsų kartos žinotų, jog aš Izraelio vaikams liepiau gyventi pastogėse, kai juos išvedžiau iš Egipto šalies; aš esu VIEŠPATS, jūsų Dievas’“.'),
  (@b3, 23, 44, 'Ir Mozė paskelbė Izraelio vaikams VIEŠPATIES šventes.'),
  (@b3, 24, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 24, 2, '„Įsakyk Izraelio vaikams, kad jie tau atneštų gryno sugrūstų alyvų aliejaus šviesai, kad nuolat degtų žibintai.'),
  (@b3, 24, 3, 'Už Liudijimo uždangos, susirinkimo padangtėje, Aaronas juos tvarkys be perstojo, nuo vakaro iki ryto VIEŠPATIES akivaizdoje; tai bus amžinas įstatas jūsų kartose.'),
  (@b3, 24, 4, 'Jis be perstojo tvarkys žibintus ant grynos žvakidės VIEŠPATIES akivaizdoje.'),
  (@b3, 24, 5, 'Ir imk smulkių miltų ir iš jų iškepk dvylika pyragų; du dešimtadaliai bus viename pyrage.'),
  (@b3, 24, 6, 'Ir sudėk juos dviem eilėm, po šešis eilėje, ant gryno stalo VIEŠPATIES akivaizdoje.'),
  (@b3, 24, 7, 'Ir uždėk ant kiekvienos eilės grynų smilkalų, kad jie būtų ant duonos, atminimui – ugnies atnaša VIEŠPAČIUI.'),
  (@b3, 24, 8, 'Kiekvieną sabatą jis nepaliaujamai tuos tvarkys VIEŠPATIES akivaizdoje, paimtus iš Izraelio vaikų amžina sandora.'),
  (@b3, 24, 9, 'Ir tie bus Aarono ir jo sūnų; ir jie tai valgys šventojoje vietoje; nes tai jam yra švenčiausia iš VIEŠPATIES ugnies atnašų pagal amžiną įstatą“.'),
  (@b3, 24, 10, 'O izraelitės moters sūnus, kurio tėvas buvo egiptietis, išėjo Izraelio vaikų tarpe; ir tas izraelitės moters sūnus susivaidijo stovykloje su Izraelio vyru;'),
  (@b3, 24, 11, 'ir izraelitės moters sūnus piktžodžiavo VIEŠPATIES vardui ir jį keikė. Ir jie atvedė jį pas Mozę (o jo motinos vardas buvo Šelomita, Dibrio duktė, iš Dano genties);'),
  (@b3, 24, 12, 'ir jie pasodino jį saugoti, kad jiems būtų paskelbtas VIEŠPATIES ketinimas.'),
  (@b3, 24, 13, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 24, 14, '„Išvesk keikusįjį už stovyklos; ir visi jį girdėjusieji teuždeda savo rankas ant jo galvos, o visas susirinkimas teužmėto jį akmenimis.'),
  (@b3, 24, 15, 'O Izraelio vaikams kalbėk, sakydamas: ‘Kas keikia savo Dievą, nešios savo nuodėmę.'),
  (@b3, 24, 16, 'Ir kas piktžodžiauja VIEŠPATIES vardui, tas tikrai bus užmuštas, visas susirinkimas tikrai jį užmėtys akmenimis; kaip ateivis, taip ir tėvynainis, kai jis piktžodžiauja VIEŠPATIES vardui, bus užmuštas.'),
  (@b3, 24, 17, 'O kas nužudys kokį žmogų, tas tikrai bus užmuštas.'),
  (@b3, 24, 18, 'O kas užmuš gyvulį, atlygins už jį; gyvuliu už gyvulį.'),
  (@b3, 24, 19, 'O jei kas padarys sužalojimą savo artimui; kaip jis padarė, taip bus ir jam padaryta:'),
  (@b3, 24, 20, 'sulaužymas už sulaužymą, akis už akį, dantis už dantį; kaip jis sužalojo žmogų, taip ir jam bus padaryta.'),
  (@b3, 24, 21, 'Ir kas užmuš gyvulį, tas jį sugrąžins; o kas nužudys žmogų, bus užmuštas.'),
  (@b3, 24, 22, 'Turėsite tokį pat įstatymą tiek ateiviui, tiek ir tėvynainiui; nes aš esu VIEŠPATS, jūsų Dievas’“.'),
  (@b3, 24, 23, 'Ir Mozė kalbėjo Izraelio vaikams, kad jie išvestų keikusįjį už stovyklos ir jį užmėtytų akmenimis. Ir Izraelio vaikai padarė, kaip VIEŠPATS įsakė Mozei.'),
  (@b3, 25, 1, 'Ir VIEŠPATS kalbėjo Mozei Sinajaus kalne, sakydamas:'),
  (@b3, 25, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Kai įeisite į šalį, kurią jums duodu, tuomet ta šalis švęs sabatą VIEŠPAČIUI.'),
  (@b3, 25, 3, 'Šešerius metus sėk savo lauką ir šešerius metus genėk savo vynuogyną ir rink jo vaisių;'),
  (@b3, 25, 4, 'bet septintaisiais metais šaliai bus sabato poilsis, sabatas VIEŠPAČIUI; nei savo lauko nesėsi, nei savo vynuogyno negenėsi.'),
  (@b3, 25, 5, 'Tai, kas savaime užauga iš tavo derliaus, nenupjauk, nei vynuogių nenurink nuo savo nenugenėto vynmedžio; nes tai yra poilsio metai šaliai.'),
  (@b3, 25, 6, 'O šalies sabatas bus jums maistas; tau, tavo tarnui ir tavo tarnaitei, tavo samdiniui ir tavo ateiviui laikinai apsigyvenusiam pas tave,'),
  (@b3, 25, 7, 'tavo galvijams ir žvėrims, esantiems tavo šalyje, visas jos prieaugis bus maistas.'),
  (@b3, 25, 8, 'Ir atskaičiuok sau septynis metų sabatus, septyniskart septynerius metus; ir septynių metinių sabatų laikas tau bus keturiasdešimt devyneri metai.'),
  (@b3, 25, 9, 'Tuomet septintojo mėnesio dešimtąją dieną padaryk, kad skambėtų jubiliejaus trimitas, Sutaikinimo dieną padarykite, kad skambėtų trimitas po visą jūsų šalį.'),
  (@b3, 25, 10, 'Ir pašvęskite penkiasdešimtuosius metus ir paskelbkite visoje šalyje laisvę visiems jos gyventojams; jums tai bus jubiliejus; ir kiekvienas sugrįžkite į savo nuosavybę, ir kiekvienas sugrįžkite į savo šeimą.'),
  (@b3, 25, 11, 'Tie penkiasdešimtieji metai bus jums jubiliejus; nei sėkite, nei pjaukite to, kas auga juose savaime, nei nerinkite vynuogių juose nuo savo nenugenėtų vynmedžių.'),
  (@b3, 25, 12, 'Nes tai yra jubiliejus; jis jums bus šventas; valgykite jo prieaugį nuo lauko.'),
  (@b3, 25, 13, 'Šito jubiliejaus metais kiekvienas sugrįžkite į savo nuosavybę.'),
  (@b3, 25, 14, 'O jei ką parduosi savo artimui ar ką nusipirksi iš savo artimo rankos, neenkite vienas kito;'),
  (@b3, 25, 15, 'pagal metų skaičių po jubiliejaus pirksi iš savo artimo, ir pagal vaisių metų skaičių jis tau parduos;'),
  (@b3, 25, 16, 'pagal metų daugumą tu padidinsi to kainą, ir pagal metų negausumą tu sumažinsi to kainą; nes pagal vaisių metų skaičių jis tau parduos.'),
  (@b3, 25, 17, 'Todėl neenkite vienas kito; bet bijok savo Dievo: nes aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 25, 18, 'Todėl vykdykite mano įstatus, laikykitės mano teismų ir juos vykdykite; ir saugiai gyvensite šalyje.'),
  (@b3, 25, 19, 'Ir šalis duos savo vaisių, ir jūs sočiai valgysite ir saugiai joje gyvensite.'),
  (@b3, 25, 20, 'O jei sakysite: „Ką valgysime septintaisiais metais? Štai nesėsime nei nerinksime savo prieaugio“;'),
  (@b3, 25, 21, 'tada aš įsakysiu savo palaiminimui ant jūsų šeštaisiais metais ir jis atneš vaisių trejiems metams.'),
  (@b3, 25, 22, 'Ir jūs sėsite aštuntaisiais metais ir dar tebevalgysite senų vaisių iki devintųjų metų; kol ateis jų derlius, jūs valgysite iš senų atsargų.'),
  (@b3, 25, 23, 'Žemė nebus parduodama per amžius; nes šalis yra mano; nes jūs esate ateiviai ir laikinai apsigyvenę pas mane.'),
  (@b3, 25, 24, 'Ir visoje jūsų nuosavybės žemėje suteikite už žemę atpirkimą.'),
  (@b3, 25, 25, 'Jei tavo brolis nuskurdęs ir pardavęs dalį savo nuosavybės, ir jei kuris iš jo giminaičių ateitų tai atpirkti, tuomet jis teatperka tai, ką buvo pardavęs jo brolis.'),
  (@b3, 25, 26, 'O jei kas neturėtų nei vieno, kad tai atpirktų, ir pats būtų pajėgus tai atpirkti;'),
  (@b3, 25, 27, 'tuomet jis tepaskaičiuoja to pardavimo metus ir teatmoka už perteklių tam žmogui, kuriam jis buvo tai pardavęs; kad jis sugrįžtų į savo nuosavybę.'),
  (@b3, 25, 28, 'Bet jei jis būtų nepajėgus jam už tai atmokėti, tuomet tai, kas yra parduota, pasiliks rankoje to, kuris tai nupirko, iki jubiliejaus metų; o per jubiliejų tai išeis, ir jis sugrįš į savo nuosavybę.'),
  (@b3, 25, 29, 'O jei kas parduos gyvenamą namą mieste, apsuptame siena, tuomet jis galės jį atpirkti per ištisus metus po to, kai jis parduotas; per pilnus metus jis galės tai atpirkti.'),
  (@b3, 25, 30, 'O jei jis nebus atpirktas per pilnų metų laikotarpį, tuomet tas namas, esantis mieste, apsuptame siena, bus amžiams įtvirtintas tam, kuris jį nusipirko, per jo kartas; jis neišeis per jubiliejų.'),
  (@b3, 25, 31, 'Bet namai kaimų, neturinčių aplinkinės sienos, bus laikomi kaip šalies laukai; juos galima atpirkti, ir per jubiliejų jie išeis.'),
  (@b3, 25, 32, 'Tačiau levitų miestus, jų nuosavybės miestų namus, levitai galės atpirkti bet kada.'),
  (@b3, 25, 33, 'O jei kas nusipirks iš levitų, tuomet parduotas namas ir jo nuosavybės miestas išeis jubiliejaus metais; nes levitų miestų namai yra jų nuosavybė tarp Izraelio vaikų.'),
  (@b3, 25, 34, 'Bet jų miestų priemiesčių lauko negalima parduoti; nes tai yra jų amžina nuosavybė.'),
  (@b3, 25, 35, 'Ir jei tavo brolis būtų nuskurdęs ir žlugęs pas tave; tuomet jam padėk; taip, nors jis būtų ateivis ar laikinai apsigyvenęs; kad jis gyventų pas tave.'),
  (@b3, 25, 36, 'Neimk iš jo palūkanų ar prieaugio; bet bijok savo Dievo; kad tavo brolis gyventų pas tave.'),
  (@b3, 25, 37, 'Neduok jam savo pinigų už palūkanas nei neskolink jam savo maisto už prieaugį.'),
  (@b3, 25, 38, 'Aš esu VIEŠPATS, jūsų Dievas, kuris jus išvedžiau iš Egipto šalies, kad jums duočiau Kanaano šalį ir kad būčiau jūsų Dievas.'),
  (@b3, 25, 39, 'O jei tavo brolis, gyvenantis šalia tavęs, būtų nuskurdęs ir tau parsidavęs; neversk jo tarnauti kaip vergo;'),
  (@b3, 25, 40, 'bet kaip samdinys, kaip laikinai apsigyvenęs, jis bus pas tave ir tarnaus tau iki jubiliejaus metų;'),
  (@b3, 25, 41, 'o po to jis išeis iš tavęs, jis ir jo vaikai su juo, ir sugrįš pas savo šeimą, ir jis sugrįš į savo tėvų nuosavybę.'),
  (@b3, 25, 42, 'Nes jie yra mano tarnai, kuriuos aš išvedžiau iš Egipto šalies; jie nebus parduodami kaip vergai.'),
  (@b3, 25, 43, 'Rūsčiai jam neviešpatauk; bet bijok savo Dievo.'),
  (@b3, 25, 44, 'Tavo vergai ir tavo vergės, kuriuos turėsi, bus iš aplink jus esančių pagonių; iš jų pirkite vergus ir verges.'),
  (@b3, 25, 45, 'Be to, iš ateivių vaikų, laikinai apsigyvenusių tarp jūsų, iš jų pirkite ir iš jų šeimų, pas jus esančių, kuriuos jie pagimdė jūsų šalyje; ir jie bus jūsų nuosavybė.'),
  (@b3, 25, 46, 'Ir juos paimkite kaip paveldą savo vaikams po jūsų, kad juos paveldėtų nuosavybėn; jie bus jūsų vergais per amžius; bet savo broliams Izraelio vaikams vienas kitam rūsčiai neviešpataukite.'),
  (@b3, 25, 47, 'O jei laikinai apsigyvenęs ar ateivis praturtės šalia tavęs, o šalia jo gyvenantis tavo brolis nuskurs ir parsiduos ateiviui ar laikinai apsigyvenusiam šalia tavęs, ar ateivio šeimos giminei;'),
  (@b3, 25, 48, 'po savo parsidavimo jis gali būti atpirktas; vienas iš jo brolių gali jį atpirkti;'),
  (@b3, 25, 49, 'ar jo dėdė, ar jo dėdės sūnus gali jį atpirkti, arba tas, kuris yra jo artimas giminaitis iš jo šeimos, gali jį atpirkti; arba jeigu jis yra pajėgus, jis pats galės išsipirkti.'),
  (@b3, 25, 50, 'Ir jis apskaičiuos su tuo, kuris jį buvo nupirkęs, nuo metų, kuriais jis buvo jam parsidavęs, iki jubiliejaus metų; ir jo pardavimo kaina bus pagal metų skaičių, bus su juo pagal samdinio laiką.'),
  (@b3, 25, 51, 'Jei dar bus likę daug metų, pagal juos jis duos savo atpirkimo kainą iš pinigų, už kuriuos jis buvo nupirktas.'),
  (@b3, 25, 52, 'O jei likę tik keletas metų iki jubiliejaus metų, tuomet jis apskaičiuos su juo, ir pagal savo metus jam duos savo atpirkimo kainą.'),
  (@b3, 25, 53, 'Ir kaip kasmet pasamdytas tarnas jis bus pas jį; o anas, tau matant, rūsčiai jam neviešpataus.'),
  (@b3, 25, 54, 'O jei jis nebus atpirktas šitais metais, tuomet jis išeis jubiliejaus metais, jis ir jo vaikai su juo.'),
  (@b3, 25, 55, 'Nes man Izraelio vaikai yra tarnai; jie yra mano tarnai, kuriuos aš išvedžiau iš Egipto šalies: aš esu VIEŠPATS, jūsų Dievas’.'),
  (@b3, 26, 1, '‘Nesidirbkite sau stabų nei raižyto atvaizdo nei nepasistatykite stovinčio atvaizdo, nei nepasistatykite jokio atvaizdo iš akmens savo šalyje, kad jam lankstytumėtės: nes aš esu VIEŠPATS, jūsų Dievas.'),
  (@b3, 26, 2, 'Laikykitės mano sabatų ir gerbkite mano šventovę: aš esu VIEŠPATS.'),
  (@b3, 26, 3, 'Jei vaikščiosite pagal mano įstatus, laikysitės mano įsakymų ir juos vykdysite;'),
  (@b3, 26, 4, 'tuomet aš duosiu jums lietų tinkamu laikotarpiu, ir žemė duos savo prieaugį, ir lauko medžiai duos savo vaisių.'),
  (@b3, 26, 5, 'Ir jūsų kūlimas nusitęs iki vynuogių rinkimo, o vynuogių rinkimas nusitęs iki sėjos; ir jūs valgysite savo duonos iki soties ir saugiai gyvensite savo šalyje.'),
  (@b3, 26, 6, 'Ir aš duosiu ramybę šalyje, o jūs atsigulsite, ir niekas jūsų neišgąsdins; ir aš išvarysiu piktus žvėris iš šalies, ir nei kalavijas neis per jūsų šalį.'),
  (@b3, 26, 7, 'Ir jūs vysitės savo priešus, ir jie kris jūsų akivaizdoje nuo kalavijo.'),
  (@b3, 26, 8, 'Ir penki iš jūsų vysis šimtą, o šimtas iš jūsų privers bėgti dešimtį tūkstančių; ir jūsų priešai kris jūsų akivaizdoje nuo kalavijo.'),
  (@b3, 26, 9, 'Nes aš atsižvelgsiu į jus, jus padarysiu vaisingus, jus padauginsiu ir įtvirtinsiu savo sandorą su jumis.'),
  (@b3, 26, 10, 'Ir jūs valgysite senas atsargas ir išnešite seną dėl naujo.'),
  (@b3, 26, 11, 'Ir aš pastatysiu savo padangtę tarp jūsų; ir mano siela jumis nesibjaurės.'),
  (@b3, 26, 12, 'Ir aš vaikščiosiu tarp jūsų ir būsiu jūsų Dievas, o jūs būsite mano tauta.'),
  (@b3, 26, 13, 'Aš esu VIEŠPATS, jūsų Dievas, kuris jus išvedžiau iš Egipto šalies, kad nebūtumėte jų vergais; ir aš sulaužiau jūsų jungo raiščius ir padariau, kad jūs vaikščiotumėte atsitiesę.'),
  (@b3, 26, 14, 'Bet jei jūs manęs neklausysite ir nevykdysite visų šitų įsakymų;'),
  (@b3, 26, 15, 'ir jei išniekinsite mano įstatus arba jei jūsų siela bjaurėsis mano teismais, jog nevykdysite visų mano įsakymų, bet sulaužysite mano sandorą;'),
  (@b3, 26, 16, 'tai ir aš jums štai ką padarysiu: aš paskirsiu, kad ant jūsų būtų išgąstis, džiova ir drugys, kurie užgesins akis ir sukels širdies sielvartą; ir jūs veltui sėsite savo sėklą, nes ją suvalgys jūsų priešai.'),
  (@b3, 26, 17, 'Ir aš nukreipsiu savo veidą prieš jus, ir jūs būsite žudomi savo priešų akivaizdoje; jums viešpataus tie, kurie nekenčia jūsų; ir bėgsite, niekam nesivejant jūsų.'),
  (@b3, 26, 18, 'O jei dėl viso to dar manęs neklausysite, tada jus bausiu septynis kartus daugiau už jūsų nuodėmes.'),
  (@b3, 26, 19, 'Ir sulaužysiu jūsų galios išdidumą; ir padarysiu jūsų dangų kaip geležį, o jūsų žemę kaip varį;'),
  (@b3, 26, 20, 'ir jūsų stiprybė bus eikvojama veltui; nes jūsų žemė neduos savo prieaugio, nei šalies medžiai neduos savo vaisių.'),
  (@b3, 26, 21, 'O jei vaikščiosite man priešiški ir nenorėsite manęs klausyti; tai aš užleisiu ant jūsų rykščių septynis kartus daugiau pagal jūsų nuodėmes.'),
  (@b3, 26, 22, 'Taip pat siųsiu laukinius žvėris tarp jūsų, kurie iš jūsų atims jūsų vaikus, išnaikins jūsų galvijus ir sumažins jūsų skaičių; ir jūsų vieškeliai ištuštės.'),
  (@b3, 26, 23, 'O jei nuo manęs šitais dalykais nepersiauklėsite, bet vaikščiosite man priešiški,'),
  (@b3, 26, 24, 'tuomet ir aš vaikščiosiu jums priešiškas ir bausiu jus dar septyneriopai už jūsų nuodėmes.'),
  (@b3, 26, 25, 'Ir atvesiu ant jūsų kalaviją, kuris atkeršys už mano sandoros ginčą; ir kai būsite susirinkę savo miestuose, aš pasiųsiu marą į jūsų tarpą; ir jūs būsite atiduoti į priešo ranką.'),
  (@b3, 26, 26, 'Ir kai būsiu sulaužęs jūsų duonos lazdą, dešimt moterų keps jūsų duoną vienoje krosnyje ir jums sugrąžins jūsų duoną pagal svorį; o jūs valgysite, bet nepasisotinsite.'),
  (@b3, 26, 27, 'O jei jūs dėl viso to manęs neklausysite, bet vaikščiosite man priešiški,'),
  (@b3, 26, 28, 'tuomet ir aš įtūžęs vaikščiosiu jums priešiškas; ir aš, būtent aš bausiu jus septyneriopai už jūsų nuodėmes.'),
  (@b3, 26, 29, 'Ir valgysite savo sūnų kūną, ir savo dukterų kūną jūs valgysite.'),
  (@b3, 26, 30, 'Ir aš sunaikinsiu jūsų aukštumas, iškirsiu jūsų atvaizdus, numesiu jūsų lavonus ant jūsų stabų lavonų, ir mano siela bjaurėsis jumis.'),
  (@b3, 26, 31, 'Ir jūsų miestus padarysiu tuščius, nusiaubsiu jūsų šventoves ir neuostysiu jūsų gardžių aromatų kvapo.'),
  (@b3, 26, 32, 'Ir nusiaubsiu šalį; ir joje gyvenantys jūsų priešai bus tuo apstulbinti.'),
  (@b3, 26, 33, 'Ir išsklaidysiu jus tarp pagonių ir jums iš paskos išsitrauksiu kalaviją; ir jūsų šalis bus tuščia, o jūsų miestai nuniokoti.'),
  (@b3, 26, 34, 'Tada šalis mėgausis savo sabatais tol, kol ji bus tuščia, o jūs būsite savo priešų šalyje; būtent tada šalis ilsėsis ir mėgausis savo sabatais.'),
  (@b3, 26, 35, 'Ji ilsėsis tol, kol ji bus tuščia; nes ji nesiilsėjo per jūsų sabatus, kai jūs joje gyvenote.'),
  (@b3, 26, 36, 'O tiems, kurie iš jūsų yra išlikę gyvi, aš siųsiu į jų širdis silpnumą jų priešų šalyse; ir virpančių lapų šlamėjimas juos persekios; ir jie bėgs, kaip bėga nuo kalavijo; ir jie pargrius, niekam nesivejant.'),
  (@b3, 26, 37, 'Ir jie grius vienas ant kito tarsi prieš kalaviją, niekam nesivejant; ir neturėsite galios atsilaikyti prieš savo priešus.'),
  (@b3, 26, 38, 'Ir žūsite tarp pagonių, ir jus prarys jūsų priešų šalis.'),
  (@b3, 26, 39, 'O jūsų išlikusieji sunyks savo neteisybėje, jūsų priešų šalyse; ir taip pat savo tėvų neteisybėse jie su jais sunyks.'),
  (@b3, 26, 40, 'Jeigu jie išpažins savo neteisybę ir savo tėvų neteisybę su jų nusižengimu, kuriuo jie nusižengė prieš mane, ir taip pat, kad jie vaikščiojo priešiški man;'),
  (@b3, 26, 41, 'ir kad aš taip pat vaikščiojau priešiškas jiems ir juos atvedžiau į jų priešų šalį; jei tada jų neapipjaustytos širdys nusižemins ir jie priims savo neteisybės bausmę;'),
  (@b3, 26, 42, 'tada aš atsiminsiu savo sandorą su Jokūbu ir taip pat savo sandorą su Izaoku, ir taip pat savo sandorą su Abraomu aš atsiminsiu; ir aš atsiminsiu šalį.'),
  (@b3, 26, 43, 'Taip pat ir šalis bus jų palikta ir mėgausis savo sabatais, būdama be jų tuščia; ir jie priims savo neteisybės bausmę; kadangi jie išniekino mano teismus ir kadangi jų siela bjaurėjosi mano įstatais.'),
  (@b3, 26, 44, 'Tačiau ir dėl viso to, kai jie bus savo priešų šalyje, aš jų neatmesiu ir jais nesibjaurėsiu, kad juos visiškai sunaikinčiau ir sulaužyčiau savo sandorą su jais; nes aš esu VIEŠPATS, jų Dievas.'),
  (@b3, 26, 45, 'Bet jų labui aš atsiminsiu sandorą jų protėvių, kuriuos, pagonims matant, išvedžiau iš Egipto šalies, kad būčiau jų Dievas: aš esu VIEŠPATS’“.'),
  (@b3, 26, 46, 'Šitie yra įstatai, teismai ir įstatymai, kuriuos VIEŠPATS per Mozės ranką Sinajaus kalne sudarė tarp savęs ir Izraelio vaikų.'),
  (@b3, 27, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b3, 27, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Jei kas padarys atskirą įžadą, asmenys bus VIEŠPAČIUI pagal tavo įvertinimą.'),
  (@b3, 27, 3, 'Ir tavo įvertinimas nuo dvidešimties metų iki šešiasdešimties metų vyriškio, tavo įvertinimas bus penkiasdešimt sidabro šekelių, pagal šventovės šekelį.'),
  (@b3, 27, 4, 'O jei tai bus moteriškė, tuomet tavo įvertinimas bus trisdešimt šekelių.'),
  (@b3, 27, 5, 'O jei tai bus nuo penkerių metų iki dvidešimties metų, tuomet tavo įvertinimas vyriškos lyties bus dvidešimt šekelių, o už moterišką lytį – dešimt šekelių.'),
  (@b3, 27, 6, 'O jei tai bus nuo mėnesio iki penkerių metų, tuomet tavo įvertinimas vyriškio bus penki sidabro šekeliai, o tavo įvertinimas už moteriškę – trys sidabro šekeliai.'),
  (@b3, 27, 7, 'O jei tai bus nuo šešiasdešimties metų ir daugiau; jei tai bus vyriškos lyties, tuomet tavo įvertinimas bus penkiolika šekelių, o už moterišką lytį – dešimt šekelių.'),
  (@b3, 27, 8, 'Bet jei jis bus skurdesnis nei tavo įvertinimas, tada jis prisistatys kunigo akivaizdon, o kunigas jį įvertins; pagal pajėgumą to, kuris padarė įžadą, kunigas jį įvertins.'),
  (@b3, 27, 9, 'O jei tai bus gyvulys, iš kurio atgabena atnašą VIEŠPAČIUI, visa, ką iš tokių kas nors duos VIEŠPAČIUI, bus šventa.'),
  (@b3, 27, 10, 'Jis jo nepakeis nei jį išmainys: gero į blogą ar blogo į gerą; o jei jis kaip nors išmainys gyvulį į gyvulį, tuomet tas ir jį pakeitusysis bus šventi.'),
  (@b3, 27, 11, 'O jei tai bus koks nešvarus gyvulys, iš kurio jie neatnašauja aukos VIEŠPAČIUI, tada jis pristatys tą gyvulį kunigo akivaizdon;'),
  (@b3, 27, 12, 'o kunigas jį įvertins, ar jis yra geras ar blogas; kaip tu vertini jį, kunige, taip ir bus.'),
  (@b3, 27, 13, 'Bet jei jis norės jį visiškai atpirkti, tada jis pridės jo penktadalį prie tavo įvertinimo.'),
  (@b3, 27, 14, 'Ir jei kas pašvęs savo namus, kad būtų šventi VIEŠPAČIUI, tada kunigas juos įvertins, ar jie yra geri ar blogi; kaip juos kunigas įvertins, taip ir pasiliks.'),
  (@b3, 27, 15, 'O jei tas, kuris juos pašventė, nori atpirkti savo namus, tada jis pridės prie jų penktadalį tavo įvertinimo pinigų, ir jie bus jo.'),
  (@b3, 27, 16, 'Ir jei kas pašvęs VIEŠPAČIUI dalį iš savo nuosavybės lauko, tuomet tavo įvertinimas bus pagal jo sėklą; homeras miežių sėklos bus įvertintas penkiasdešimčia sidabro šekelių.'),
  (@b3, 27, 17, 'Jei jis pašvęs savo lauką nuo jubiliejaus metų, tai pasiliks pagal tavo įvertinimą.'),
  (@b3, 27, 18, 'Bet jei kas pašvęs savo lauką po jubiliejaus, tuomet kunigas jam apskaičiuos pinigus pagal metus, kurie dar lieka iki jubiliejaus metų, ir bus sumažinta kaina iš tavo įvertinimo.'),
  (@b3, 27, 19, 'O jei tas, kuris pašventė lauką, norės jį visiškai atpirkti, tada jis prie jo pridės penktadalį tavo įvertinimo pinigų, ir jis jam bus užtikrintas.'),
  (@b3, 27, 20, 'O jei jis nenorės lauko atpirkti arba bus pardavęs lauką kam kitam, tai jis daugiau nebebus atperkamas.'),
  (@b3, 27, 21, 'Bet laukas, išėjęs per jubiliejų, bus šventas VIEŠPAČIUI kaip pašvęstas laukas; to nuosavybė bus kunigo.'),
  (@b3, 27, 22, 'O jei kas pašvęs VIEŠPAČIUI lauką, kurį jis yra nusipirkęs, kuris nėra iš jo nuosavybės laukų;'),
  (@b3, 27, 23, 'tuomet kunigas jam apskaičiuos tavo įvertinimo kainą iki jubiliejaus metų; ir tą dieną jis duos tavo įvertinimą kaip šventą dalyką VIEŠPAČIUI.'),
  (@b3, 27, 24, 'Jubiliejaus metais laukas sugrįš tam, iš kurio jis buvo nupirktas, tam, kuriam priklausė lauko nuosavybė.'),
  (@b3, 27, 25, 'Ir visi tavo įvertinimai bus pagal šventovės šekelį; dvidešimt gerų bus vienas šekelis.'),
  (@b3, 27, 26, 'Tik gyvulių pirmagimio, kuris turės būti VIEŠPATIES pirmagimis, niekas jo nepašvęs; ar tai būtų jautis, ar avis; tai yra VIEŠPATIES.'),
  (@b3, 27, 27, 'O jei tai būtų iš nešvaraus gyvulio, tada jis tą atpirks pagal tavo įvertinimą ir prie jo pridės penktą jo dalį; arba jei tas nebus atpirktas, tuomet bus parduotas pagal tavo įvertinimą.'),
  (@b3, 27, 28, 'Tačiau joks pašvęstas dalykas, kurį kas nors pašvęs VIEŠPAČIUI iš viso to, ką jis turi – iš žmonių, iš gyvulių ir iš savo nuosavybės lauko, – nebus parduodamas ar atperkamas: kiekvienas pašvęstas dalykas yra švenčiausias VIEŠPAČIUI.'),
  (@b3, 27, 29, 'Joks pašvęstasis, kuris bus pašvęstas iš žmonių, nebus atperkamas; bet tikrai bus užmuštas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b3, 27, 30, 'Ir kiekviena žemės dešimtinė, ar tai iš žemės sėklų, ar iš medžių vaisių, yra VIEŠPATIES; tai yra šventa VIEŠPAČIUI.'),
  (@b3, 27, 31, 'O jei kas nori visiškai atpirkti ką nors iš savo dešimtinių, tas pridės prie jų penktąją jų dalį.'),
  (@b3, 27, 32, 'O dėl dešimtinės iš bandos ar iš kaimenės, iš kiekvieno, kuris praeina po lazda, dešimtadalis bus šventas VIEŠPAČIUI.'),
  (@b3, 27, 33, 'Nebus tyrinėjama, ar jis geras, ar blogas, nei nebus mainoma; o jei jį visiškai išmainytų, tuomet jis ir jį pakeitusysis bus šventi; jie nebus atperkami’“.'),
  (@b3, 27, 34, 'Šitie yra įsakymai, kuriuos VIEŠPATS įsakė Mozei dėl Izraelio vaikų Sinajaus kalne.'),
  (@b4, 1, 1, 'Ir VIEŠPATS kalbėjo Mozei Sinajaus dykumoje, susirinkimo padangtėje, antrojo mėnesio pirmąją dieną, antraisiais metais po jų išvykimo iš Egipto šalies, sakydamas:'),
  (@b4, 1, 2, '„Susumuokite visą Izraelio vaikų susirinkimą pagal jų šeimas, pagal jų tėvų namus, pagal jų vardų skaičių, visus vyriškos lyties, galva po galvos;'),
  (@b4, 1, 3, 'nuo dvidešimties metų ir vyresnius, visus Izraelyje pajėgius eiti į karą; tu ir Aaronas juos suskaičiuosite pagal jų kariuomenes.'),
  (@b4, 1, 4, 'Ir su jumis bus po vyrą iš kiekvienos genties; kiekvienas savo tėvų namų galva.'),
  (@b4, 1, 5, 'O šitie yra vardai vyrų, kurie stovės pas jus: iš Rubeno genties: Šedeūro sūnus Elicūras.'),
  (@b4, 1, 6, 'Iš Simeono: Cūrišadajo sūnus Šelumielis.'),
  (@b4, 1, 7, 'Iš Judos: Aminadabo sūnus Nachšonas.'),
  (@b4, 1, 8, 'Iš Isacharo: Cuaro sūnus Netanelis.'),
  (@b4, 1, 9, 'Iš Zebulono: Helono sūnus Eliabas.'),
  (@b4, 1, 10, 'Iš Juozapo vaikų: iš Efraimo: Amihudo sūnus Elišama; iš Manaso: Pedahcūro sūnus Gamalielis.'),
  (@b4, 1, 11, 'Iš Benjamino: Gideonio sūnus Abidanas.'),
  (@b4, 1, 12, 'Iš Dano: Amišadajo sūnus Ahiezeras.'),
  (@b4, 1, 13, 'Iš Ašero: Ochrano sūnus Pagielis.'),
  (@b4, 1, 14, 'Iš Gado: Deuelio sūnus Eljasafas.'),
  (@b4, 1, 15, 'Iš Naftalio: Enano sūnus Ahyra“.'),
  (@b4, 1, 16, 'Šitie buvo susirinkimo žymieji, jų tėvų genčių kunigaikščiai, tūkstančių galvos Izraelyje.'),
  (@b4, 1, 17, 'O Mozė ir Aaronas ėmė tuos vyrus, kurie buvo išvardyti jų vardais;'),
  (@b4, 1, 18, 'ir jie surinko visą susirinkimą antrojo mėnesio pirmąją dieną, ir jie paskelbė jų kilmę pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnius, galva po galvos.'),
  (@b4, 1, 19, 'Kaip VIEŠPATS įsakė Mozei, taip jis juos suskaičiavo Sinajaus dykumoje.'),
  (@b4, 1, 20, 'Ir vyriausio Izraelio sūnaus Rubeno vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, galva po galvos, visų vyriškos lyties nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 21, 'tų, kurie buvo suskaičiuoti iš jų, iš Rubeno genties, buvo keturiasdešimt šeši tūkstančiai penki šimtai.'),
  (@b4, 1, 22, 'Iš Simeono vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, kurie buvo iš jų suskaičiuoti pagal vardų skaičių, galva po galvos, visų vyriškos lyties nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 23, 'tų, kurie buvo suskaičiuoti iš jų, iš Simeono genties, buvo penkiasdešimt devyni tūkstančiai trys šimtai.'),
  (@b4, 1, 24, 'Iš Gado vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 25, 'tų, kurie buvo suskaičiuoti iš jų, iš Gado genties, buvo keturiasdešimt penki tūkstančiai šeši šimtai penkiasdešimt.'),
  (@b4, 1, 26, 'Iš Judos vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 27, 'tų, kurie buvo suskaičiuoti iš jų, iš Judos genties, buvo septyniasdešimt keturi tūkstančiai šeši šimtai.'),
  (@b4, 1, 28, 'Iš Isacharo vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 29, 'tų, kurie buvo suskaičiuoti iš jų, iš Isacharo genties, buvo penkiasdešimt keturi tūkstančiai keturi šimtai.'),
  (@b4, 1, 30, 'Iš Zebulono vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 31, 'tų, kurie buvo suskaičiuoti iš jų, iš Zebulono genties, buvo penkiasdešimt septyni tūkstančiai keturi šimtai.'),
  (@b4, 1, 32, 'Iš Juozapo vaikų, būtent iš Efraimo vaikų, pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 33, 'tų, kurie buvo suskaičiuoti iš jų, iš Efraimo genties, buvo keturiasdešimt tūkstančių penki šimtai.'),
  (@b4, 1, 34, 'Iš Manaso vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 35, 'tų, kurie buvo suskaičiuoti iš jų, iš Manaso genties, buvo trisdešimt du tūkstančiai du šimtai.'),
  (@b4, 1, 36, 'Iš Benjamino vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 37, 'tų, kurie buvo suskaičiuoti iš jų, iš Benjamino genties, buvo trisdešimt penki tūkstančiai keturi šimtai.'),
  (@b4, 1, 38, 'Iš Dano vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 39, 'tų, kurie buvo suskaičiuoti iš jų, iš Dano genties, buvo šešiasdešimt du tūkstančiai septyni šimtai.'),
  (@b4, 1, 40, 'Iš Ašero vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 41, 'tų, kurie buvo suskaičiuoti iš jų, iš Ašero genties, buvo keturiasdešimt vienas tūkstantis penki šimtai.'),
  (@b4, 1, 42, 'Iš Naftalio vaikų pagal jų genealogiją, pagal jų šeimas, pagal jų tėvų namus, pagal vardų skaičių, nuo dvidešimties metų ir vyresnių, visų pajėgių eiti į karą;'),
  (@b4, 1, 43, 'tų, kurie buvo suskaičiuoti iš jų, iš Naftalio genties, buvo penkiasdešimt trys tūkstančiai keturi šimtai.'),
  (@b4, 1, 44, 'Šitie yra suskaičiuotieji, kuriuos suskaičiavo Mozė, Aaronas ir Izraelio kunigaikščiai – dvylika vyrų – kiekvienas buvo savo tėvų namams.'),
  (@b4, 1, 45, 'Taigi visų suskaičiuotų iš Izraelio vaikų pagal jų tėvų namus, nuo dvidešimties metų ir vyresnių, visų į karą eiti pajėgių Izraelyje;'),
  (@b4, 1, 46, 'visų suskaičiuotų buvo šeši šimtai trys tūkstančiai penki šimtai penkiasdešimt.'),
  (@b4, 1, 47, 'Bet levitai pagal jų tėvų gentį nebuvo suskaičiuoti tarp jų.'),
  (@b4, 1, 48, 'Nes VIEŠPATS buvo kalbėjęs Mozei, sakydamas:'),
  (@b4, 1, 49, '„Tik Levio genties neskaičiuok nei jų nesumuok tarp Izraelio vaikų;'),
  (@b4, 1, 50, 'bet paskirk levitus prie Liudijimo padangtės, prie visų jos įrankių ir visko, kas jai priklauso; jie nešios padangtę ir visus jos įrankius; ir jie jai tarnaus ir aplink padangtę stovyklaus.'),
  (@b4, 1, 51, 'Ir padangtei išvykstant, levitai ją išardys; o padangtę pastatant, levitai ją pastatys; o pašalinis, kuris prisiartins, bus užmuštas.'),
  (@b4, 1, 52, 'Ir Izraelio vaikai pasistatys savo palapines, kiekvienas prie savo paties stovyklos bei kiekvienas prie savo paties vėliavos savo kariuomenėse.'),
  (@b4, 1, 53, 'Bet levitai stovyklaus aplink Liudijimo padangtę, kad nebūtų rūstavimo ant Izraelio vaikų susirinkimo; ir levitai prižiūrės Liudijimo padangtę“.'),
  (@b4, 1, 54, 'Ir Izraelio vaikai padarė pagal visa, ką VIEŠPATS įsakė Mozei, taip jie padarė.'),
  (@b4, 2, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b4, 2, 2, '„Kiekvienas iš Izraelio vaikų stovyklaus prie savo paties vėliavos su jų tėvų namų ženklu; jie stovyklaus aplinkui susirinkimo padangtę atokiai.'),
  (@b4, 2, 3, 'Ir rytinėje pusėje, saulėtekio link, tie iš Judos stovyklos vėliavos stovyklaus savo kariuomenėse; o Judos vaikų vadas bus Aminadabo sūnus Nachšonas.'),
  (@b4, 2, 4, 'O jo kariuomenė ir tie, kurie buvo iš jų suskaičiuoti, buvo septyniasdešimt keturi tūkstančiai šeši šimtai.'),
  (@b4, 2, 5, 'O tie, kurie stovyklaus šalia jo, bus Isacharo gentis; o Isacharo vaikų vadas bus Cuaro sūnus Netanelis.'),
  (@b4, 2, 6, 'O jo kariuomenė ir iš jos suskaičiuotųjų buvo penkiasdešimt keturi tūkstančiai keturi šimtai.'),
  (@b4, 2, 7, 'Paskui Zebulono gentis; o Zebulono vaikų vadas bus Eliabas, Helono sūnus.'),
  (@b4, 2, 8, 'O jo kariuomenė ir iš jos suskaičiuotųjų buvo penkiasdešimt septyni tūkstančiai keturi šimtai.'),
  (@b4, 2, 9, 'Visų Judos stovykloje suskaičiuotųjų jų kariuomenėse buvo šimtas aštuoniasdešimt šeši tūkstančiai keturi šimtai; šitie pirmi išvyks.'),
  (@b4, 2, 10, 'Pietinėje pusėje bus vėliava Rubeno stovyklos pagal jų kariuomenes; o Rubeno vaikų vadas bus Elicūras, Šedeūro sūnus.'),
  (@b4, 2, 11, 'O jo kariuomenė ir iš jos suskaičiuotųjų buvo keturiasdešimt šeši tūkstančiai penki šimtai.'),
  (@b4, 2, 12, 'O tie, kurie stovyklaus šalia jo, bus Simeono gentis; o Simeono vaikų vadas bus Cūrišadajo sūnus Šelumielis.'),
  (@b4, 2, 13, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo penkiasdešimt devyni tūkstančiai trys šimtai.'),
  (@b4, 2, 14, 'Po to Gado gentis; o Gado sūnų vadas bus Reuelio sūnus Eljasafas.'),
  (@b4, 2, 15, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo keturiasdešimt penki tūkstančiai šeši šimtai penkiasdešimt.'),
  (@b4, 2, 16, 'Visų Rubeno stovykloje suskaičiuotųjų jų kariuomenėse buvo šimtas penkiasdešimt vienas tūkstantis keturi šimtai penkiasdešimt. Ir jie išvyks antri.'),
  (@b4, 2, 17, 'Paskui išvyks susirinkimo padangtė su levitų stovykla, esančia stovyklos viduryje; kaip jie stovyklauja, taip jie ir išvyks, kiekvienas savo vietoje prie savo vėliavų.'),
  (@b4, 2, 18, 'Vakarinėje pusėje bus vėliava Efraimo stovyklos pagal jų kariuomenes; o Efraimo sūnų vadas bus Amihudo sūnus Elišama.'),
  (@b4, 2, 19, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo keturiasdešimt tūkstančių penki šimtai.'),
  (@b4, 2, 20, 'O šalia jo bus Manaso gentis; o Manaso vaikų vadas bus Pedahcūro sūnus Gamalielis.'),
  (@b4, 2, 21, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo trisdešimt du tūkstančiai du šimtai.'),
  (@b4, 2, 22, 'Paskui Benjamino gentis; o Benjamino sūnų vadas bus Gideonio sūnus Abidanas.'),
  (@b4, 2, 23, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo trisdešimt penki tūkstančiai keturi šimtai.'),
  (@b4, 2, 24, 'Visų iš Efraimo stovyklos suskaičiuotųjų jų kariuomenėse buvo šimtas aštuoni tūkstančiai šimtas. Ir jie išvyks treti.'),
  (@b4, 2, 25, 'Vėliava Dano stovyklos pagal jų kariuomenes bus šiaurinėje pusėje; o Dano vaikų vadas bus Amišadajo sūnus Ahiezeras.'),
  (@b4, 2, 26, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo šešiasdešimt du tūkstančiai septyni šimtai.'),
  (@b4, 2, 27, 'O tie, kurie stovyklaus šalia jo, bus Ašero gentis; o Ašero vaikų vadas bus Ochrano sūnus Pagielis.'),
  (@b4, 2, 28, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo keturiasdešimt vienas tūkstantis penki šimtai.'),
  (@b4, 2, 29, 'Paskui Naftalio gentis; o Naftalio vaikų vadas bus Enano sūnus Ahyra.'),
  (@b4, 2, 30, 'O jo kariuomenė ir iš jų suskaičiuotųjų buvo penkiasdešimt trys tūkstančiai keturi šimtai.'),
  (@b4, 2, 31, 'Visų Dano stovykloje suskaičiuotųjų buvo šimtas penkiasdešimt septyni tūkstančiai šeši šimtai. Jie vyks paskutiniai su savo vėliavomis“.'),
  (@b4, 2, 32, 'Šitie yra Izraelio vaikų suskaičiuotieji pagal jų tėvų namus; visų suskaičiuotųjų iš stovyklų jų kariuomenėse buvo šeši šimtai trys tūkstančiai penki šimtai penkiasdešimt.'),
  (@b4, 2, 33, 'Bet levitai nebuvo suskaičiuoti tarp Izraelio vaikų; kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 2, 34, 'Ir Izraelio vaikai padarė pagal visa, ką VIEŠPATS įsakė Mozei: taip jie stovyklavo prie savo vėliavų ir taip jie išvyko, kiekvienas pagal savo šeimas, pagal savo tėvų namus.'),
  (@b4, 3, 1, 'Taip pat šita yra Aarono ir Mozės genealogija tą dieną, kai VIEŠPATS kalbėjosi su Moze Sinajaus kalne.'),
  (@b4, 3, 2, 'Ir šitie yra Aarono sūnų vardai: pirmagimis Nadabas ir Abihuvas, Eleazaras ir Itamaras.'),
  (@b4, 3, 3, 'Šitie yra vardai Aarono sūnų, kunigų, kurie buvo patepti, kuriuos jis įšventino tarnauti kunigo tarnyboje.'),
  (@b4, 3, 4, 'O Nadabas ir Abihuvas mirė VIEŠPATIES akivaizdoje, atnašaudami svetimą ugnį VIEŠPATIES akivaizdoje Sinajaus dykumoje, ir jie neturėjo vaikų; o Eleazaras ir Itamaras tarnavo kunigo tarnyboje, matant jų tėvui Aaronui.'),
  (@b4, 3, 5, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 3, 6, '„Privesk artyn Levio gentį ir juos pristatyk kunigo Aarono akivaizdon, kad jie jam tarnautų.'),
  (@b4, 3, 7, 'Ir jie laikysis jo įpareigojimo ir įpareigojimo viso susirinkimo priešais susirinkimo padangtę, kad atliktų padangtės tarnavimą.'),
  (@b4, 3, 8, 'Ir jie saugos visus susirinkimo padangtės įrankius ir laikysis Izraelio vaikų įpareigojimo, kad atliktų padangtės tarnavimą.'),
  (@b4, 3, 9, 'Ir levitus duok Aaronui ir jo sūnums; jie yra visiškai jam atiduoti iš Izraelio vaikų.'),
  (@b4, 3, 10, 'O Aaroną ir jo sūnus paskirk, ir jie patarnaus savo kunigystės pareigose; o svetimas, kuris priartės, bus užmuštas“.'),
  (@b4, 3, 11, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 3, 12, '„Ir aš, štai aš paėmiau levitus iš Izraelio vaikų tarpo vietoj visų pirmagimių, kurie praveria gimdą tarp Izraelio vaikų; todėl levitai bus mano;'),
  (@b4, 3, 13, 'kadangi visi pirmagimiai yra mano; nes tą dieną, kai užmušiau visus pirmagimius Egipto šalyje, aš sau pašvenčiau visus pirmagimius Izraelyje, tiek žmones, tiek gyvulius; jie bus mano: aš esu VIEŠPATS“.'),
  (@b4, 3, 14, 'Ir VIEŠPATS kalbėjo Mozei Sinajaus dykumoje, sakydamas:'),
  (@b4, 3, 15, '„Suskaičiuok Levio vaikus pagal jų tėvų namus, pagal jų šeimas; suskaičiuok visus vyriškos lyties, nuo mėnesio ir vyresnius“.'),
  (@b4, 3, 16, 'Ir Mozė juos suskaičiavo pagal VIEŠPATIES žodį, kaip jam buvo įsakyta.'),
  (@b4, 3, 17, 'Ir šitie buvo Levio sūnūs pagal jų vardus: Geršonas, Kehatas ir Meraris.'),
  (@b4, 3, 18, 'O šitie yra Geršono sūnų vardai pagal jų šeimas: Libnis ir Šimis.'),
  (@b4, 3, 19, 'O Kehato sūnūs pagal jų šeimas: Amramas ir Isharas, Hebronas ir Uzielis.'),
  (@b4, 3, 20, 'O Merario sūnūs pagal jų šeimas: Machlis ir Mušis. Šitos yra levitų šeimos pagal jų tėvų namus.'),
  (@b4, 3, 21, 'Iš Geršono buvo libnių šeima ir šimių šeima; šitos yra geršonų šeimos.'),
  (@b4, 3, 22, 'Tų, kurie iš jų buvo suskaičiuoti pagal skaičių visų vyriškių, nuo mėnesio ir vyresnių, iš jų suskaičiuotų buvo septyni tūkstančiai penki šimtai.'),
  (@b4, 3, 23, 'Geršonų šeimos stovyklaus padangtės užnugaryje, vakarų link.'),
  (@b4, 3, 24, 'Ir geršonų tėvo namų vadas bus Laelio sūnus Eljasafas.'),
  (@b4, 3, 25, 'O Geršono sūnų pareiga susirinkimo padangtėje bus padangtė ir palapinė, jos apdangalas ir susirinkimo padangtės durų užuolaida,'),
  (@b4, 3, 26, 'kiemo užuolaidos, aplink padangtę ir aukurą esančio kiemo durų uždanga ir jos virvės, visam jo tarnavimui.'),
  (@b4, 3, 27, 'O iš Kehato buvo amramų šeima, ischarų šeima, hebronų šeima ir uzielitų šeima; šitos yra kehatų šeimos.'),
  (@b4, 3, 28, 'Visų vyriškių skaičiumi, nuo mėnesio ir vyresnių, buvo aštuoni tūkstančiai šeši šimtai besilaikančių šventovės pareigos.'),
  (@b4, 3, 29, 'Kehato sūnų šeimos stovyklaus padangtės pusėje į pietus.'),
  (@b4, 3, 30, 'O kehatų šeimų tėvo namų vadas bus Uzielio sūnus Elicafanas.'),
  (@b4, 3, 31, 'Ir jų pareiga bus skrynia, stalas, žvakidė, aukurai, šventovės įrankiai, kuriais jie tarnauja, užuolaida ir visas šito tarnavimas.'),
  (@b4, 3, 32, 'O levitų vadų vadas bus kunigo Aarono sūnus Eleazaras, prižiūrintis tuos, kurie laikosi šventovės pareigos.'),
  (@b4, 3, 33, 'Iš Merario buvo machlių šeima ir mušių šeima; šitos yra Merario šeimos.'),
  (@b4, 3, 34, 'O tų, kurie iš jų buvo suskaičiuoti, pagal skaičių visų nuo mėnesio ir vyresnių vyriškių, buvo šeši tūkstančiai du šimtai.'),
  (@b4, 3, 35, 'O Merario šeimų tėvo namų vadas buvo Abihailo sūnus Curielis; šitie stovyklaus padangtės pusėje į šiaurę.'),
  (@b4, 3, 36, 'O Merario sūnų globoje ir priežiūroje bus padangtės lentos, jos skersiniai, jos stulpai, jos movos, visi jos įrankiai ir visa, kas tam tarnauja,'),
  (@b4, 3, 37, 'aplinkinio kiemo stulpai, jų movos, jų kuolai ir jų virvės.'),
  (@b4, 3, 38, 'Bet tie, kurie stovyklaus priešais padangtę į rytus, būtent priešais susirinkimo padangtę rytų link, bus Mozė, Aaronas ir jo sūnūs, besilaikantys šventovės pareigos kaip Izraelio vaikų pareigos; o svetimas, kuris priartės, bus užmuštas.'),
  (@b4, 3, 39, 'Visų tų, kurie iš levitų buvo suskaičiuoti, kuriuos VIEŠPATIES įsakymu suskaičiavo Mozė ir Aaronas jų šeimose, visų nuo mėnesio ir vyresnių vyriškių, buvo dvidešimt du tūkstančiai.'),
  (@b4, 3, 40, 'Ir VIEŠPATS tarė Mozei: „Suskaičiuok visus vyriškos lyties pirmagimius iš Izraelio vaikų, nuo mėnesio ir vyresnius, ir paimk jų vardų skaičių.'),
  (@b4, 3, 41, 'Ir imk man levitus (aš esu VIEŠPATS) vietoj visų pirmagimių tarp Izraelio vaikų; ir levitų galvijus vietoj visų pirmagimių tarp Izraelio vaikų galvijų“.'),
  (@b4, 3, 42, 'Ir Mozė suskaičiavo, kaip VIEŠPATS jam įsakė, visus pirmagimius tarp Izraelio vaikų.'),
  (@b4, 3, 43, 'Ir visų vyriškos lyties pirmagimių pagal vardų skaičių, nuo vieno mėnesio ir vyresnių, iš jų suskaičiuotų buvo dvidešimt du tūkstančiai du šimtai septyniasdešimt trys.'),
  (@b4, 3, 44, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 3, 45, '„Paimk levitus vietoj visų pirmagimių tarp Izraelio vaikų ir levitų galvijus vietoj jų galvijų; ir levitai bus mano: aš esu VIEŠPATS.'),
  (@b4, 3, 46, 'O dėl tų, kurie turės būti atpirkti iš dviejų šimtų septyniasdešimt trijų iš Izraelio vaikų pirmagimių, kurių yra daugiau nei levitų;'),
  (@b4, 3, 47, 'imk po penkis šekelius už galvą, pagal šventovės šekelį juos imk (šekelis yra dvidešimt gerų);'),
  (@b4, 3, 48, 'ir duok tuos pinigus, kuriais turės būti atpirktas jų viršijantis skaičius, Aaronui ir jo sūnums“.'),
  (@b4, 3, 49, 'Ir Mozė ėmė atpirkimo pinigus iš tų, kurių buvo daugiau nei tų, kurie buvo levitų atpirkti;'),
  (@b4, 3, 50, 'jis iš Izraelio vaikų pirmagimių paėmė pinigus: tūkstantį tris šimtus šešiasdešimt penkis šekelius, pagal šventovės šekelį;'),
  (@b4, 3, 51, 'ir Mozė davė pinigus iš tų, kurie buvo atpirkti, Aaronui bei jo sūnums, pagal VIEŠPATIES žodį, kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 4, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b4, 4, 2, '„Susumuok Kehato sūnus iš Levio sūnų tarpo pagal jų šeimas, pagal jų tėvų namus,'),
  (@b4, 4, 3, 'nuo trisdešimties metų ir vyresnius – iki penkiasdešimties metų, visus įeinančius į kariuomenę, kad atliktų darbą susirinkimo padangtėje.'),
  (@b4, 4, 4, 'Šitas bus Kehato sūnų tarnavimas susirinkimo padangtėje prie švenčiausių dalykų;'),
  (@b4, 4, 5, 'ir stovyklai išvykstant, ateis Aaronas ir jo sūnūs ir nuims apdengiančią uždangą ir ja apdengs Liudijimo skrynią;'),
  (@b4, 4, 6, 'o ant jos uždės barsukų odų apdangalą, ant jo viršaus užties audeklą, visą iš mėlyno, ir įkiš jos kartis.'),
  (@b4, 4, 7, 'O ant parodomosios duonos stalo jie užties audeklą iš mėlyno ir ant jo sudės lėkštes, šaukštus, dubenis ir dangčius, kad jais uždengtų; ir nuolatinė duona bus ant jo;'),
  (@b4, 4, 8, 'o ant jų jie užties audeklą iš skaisčiai raudono, apdengs jį barsukų odų apdangalu ir įkiš jo kartis.'),
  (@b4, 4, 9, 'Ir jie paims audeklą iš mėlyno ir apdengs apšvietimo žvakidę, jos žibintus, jos gnybtuvus, jos dubenis nuognaiboms ir visus jos aliejaus indus, kuriais jie jai tarnauja;'),
  (@b4, 4, 10, 'o ją ir visus jos įrankius jie įdės į barsukų odų apdangalą ir tai uždės ant skersinio.'),
  (@b4, 4, 11, 'O ant auksinio aukuro jie užties audeklą iš mėlyno, jį apdengs barsukų odų apdangalu ir padės prie jo karčių;'),
  (@b4, 4, 12, 'ir jie paims visus tarnavimo įrankius, kuriais jie tarnauja šventovėje, juos įdės į audeklą iš mėlyno, juos apdengs barsukų odų apdangalu ir juos uždės ant skersinio;'),
  (@b4, 4, 13, 'ir jie išims pelenus iš aukuro ir užties ant jo purpurinį audeklą;'),
  (@b4, 4, 14, 'ir jie uždės ant jo visus jo įrankius, kuriais jie prie jo tarnauja: smilkytuvus, šakutes mėsai, semtuvus ir dubenis – visus aukuro įrankius; ir ant jo jie išties barsukų odų apdangalą ir padės prie jo karčių.'),
  (@b4, 4, 15, 'O kai Aaronas ir jo sūnūs stovyklai išvykstant bus baigę dengti šventovę ir visus šventovės įrankius; po to ateis Kehato sūnūs, kad juos neštų; bet jie nelies nieko, kas šventa, kad nemirtų. Šitie dalykai yra Kehato sūnų našta susirinkimo padangtėje.'),
  (@b4, 4, 16, 'O kunigo Aarono sūnaus Eleazaro pareigai priklauso aliejus šviesai, kvapūs smilkalai, kasdienė maisto atnaša, patepimo aliejus, priežiūra visos padangtės ir viso to, kas yra joje, šventovėje ir jos įrankiuose“.'),
  (@b4, 4, 17, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b4, 4, 18, '„Neiškirskite kehatų šeimų genties iš levitų tarpo;'),
  (@b4, 4, 19, 'bet taip jiems darykite, kad jie gyventų, o ne mirtų, jiems artėjant prie švenčiausių daiktų; Aaronas ir jo sūnūs įeis ir paskirs juos kiekvieną jo tarnavimui ir jo naštai;'),
  (@b4, 4, 20, 'bet jie neįeis pasižiūrėti, kai uždengiami šventi dalykai, kad nemirtų“.'),
  (@b4, 4, 21, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 4, 22, '„Susumuok taip pat iš Geršono sūnų jų tėvų namuose pagal jų šeimas;'),
  (@b4, 4, 23, 'nuo trisdešimties metų ir vyresnius – iki penkiasdešimties metų, juos suskaičiuok; visus, įeinančius tarnystės atlikti, dirbti darbo susirinkimo padangtėje.'),
  (@b4, 4, 24, 'Šita yra geršonų šeimų tarnystė, tarnauti ir naštoms:'),
  (@b4, 4, 25, 'ir jie nešios padangtės uždangalus, susirinkimo padangtę, jos apdangalą, viršuje ant jo esantį barsukų odų apdangalą, susirinkimo padangtės durų užuolaidą,'),
  (@b4, 4, 26, 'kiemo užuolaidas, aplink padangtę ir aukurą esančio kiemo vartų durų užuolaidą, jų virves ir visus jų tarnavimo įrankius, ir visa, kas jiems yra padaryta; taip jie tarnaus.'),
  (@b4, 4, 27, 'Aarono ir jo sūnų paskyrimu bus visa geršonų sūnų tarnystė visose jų naštose ir visoje jų tarnystėje; ir jiems paskirsite priežiūrai visas jų naštas.'),
  (@b4, 4, 28, 'Šita yra Geršono sūnų šeimų tarnystė susirinkimo padangtėje; ir jų pareigos bus vadovaujant rankai Itamaro, kunigo Aarono sūnaus.'),
  (@b4, 4, 29, 'O dėl Merario sūnų, tu juos suskaičiuok pagal jų šeimas, pagal jų tėvų namus;'),
  (@b4, 4, 30, 'suskaičiuok juos nuo trisdešimties metų ir vyresnius – iki penkiasdešimties metų, visus, įeinančius į tarnystę atlikti susirinkimo padangtės darbo.'),
  (@b4, 4, 31, 'O šita yra jiems įpareigota našta pagal visą jų tarnystę susirinkimo padangtėje: padangtės lentos, jos skersiniai, jos stulpai, jos movos,'),
  (@b4, 4, 32, 'aplinkinio kiemo stulpai, jų movos, jų kuolai ir jų virvės su visais jų įrankiais ir su visu jų tarnavimu; ir pagal vardus priskirkite jų įpareigotos naštos įrankius.'),
  (@b4, 4, 33, 'Šita yra Merario sūnų šeimų tarnystė pagal visą jų tarnystę susirinkimo padangtėje, vadovaujant rankai Itamaro, kunigo Aarono sūnaus“.'),
  (@b4, 4, 34, 'Ir Mozė, Aaronas ir susirinkimo vyresnieji suskaičiavo kehatų sūnus pagal jų šeimas ir pagal jų tėvų namus,'),
  (@b4, 4, 35, 'nuo trisdešimties metų ir vyresnius – iki penkiasdešimties metų, visus, įeinančius į tarnystę, darbui susirinkimo padangtėje;'),
  (@b4, 4, 36, 'o iš tų, kurie buvo jų suskaičiuoti pagal jų šeimas, buvo du tūkstančiai septyni šimtai penkiasdešimt.'),
  (@b4, 4, 37, 'Šitie buvo suskaičiuotieji iš kehatų šeimų, visi, galintys atlikti tarnystę susirinkimo padangtėje, kuriuos Mozė ir Aaronas suskaičiavo pagal VIEŠPATIES įsakymą per Mozės ranką.'),
  (@b4, 4, 38, 'O suskaičiuotųjų iš Geršono sūnų jų šeimose ir pagal jų tėvų namus,'),
  (@b4, 4, 39, 'nuo trisdešimties metų ir vyresnių – iki penkiasdešimties metų, visų, įeinančių į tarnystę, darbui susirinkimo padangtėje,'),
  (@b4, 4, 40, 'iš tų, kurie buvo jų suskaičiuoti jų šeimose, pagal jų tėvų namus, buvo du tūkstančiai šeši šimtai trisdešimt.'),
  (@b4, 4, 41, 'Šitie yra suskaičiuotieji iš Geršono sūnų šeimų, iš visų, galinčių atlikti tarnystę susirinkimo padangtėje, kuriuos Mozė ir Aaronas suskaičiavo pagal VIEŠPATIES įsakymą.'),
  (@b4, 4, 42, 'O suskaičiuotųjų iš Merario sūnų šeimų jų šeimose pagal jų tėvų namus,'),
  (@b4, 4, 43, 'nuo trisdešimties metų ir vyresnių – iki penkiasdešimties metų, visų, įeinančių į tarnystę, darbui susirinkimo padangtėje,'),
  (@b4, 4, 44, 'iš tų, kurie buvo jų suskaičiuoti pagal jų šeimas, buvo trys tūkstančiai du šimtai.'),
  (@b4, 4, 45, 'Šitie buvo suskaičiuotieji iš Merario sūnų šeimų, kuriuos suskaičiavo Mozė ir Aaronas pagal VIEŠPATIES žodį per Mozės ranką.'),
  (@b4, 4, 46, 'Visų, suskaičiuotų iš levitų, kuriuos Mozė, Aaronas ir Izraelio vyresnieji suskaičiavo pagal jų šeimas ir pagal jų tėvų namus,'),
  (@b4, 4, 47, 'nuo trisdešimties metų ir vyresnių – iki penkiasdešimties metų, visų, kurie atėjo atlikti tarnybos tarnavimo ir naštų tarnavimo susirinkimo padangtėje,'),
  (@b4, 4, 49, 'Pagal VIEŠPATIES įsakymą jie buvo suskaičiuoti per Mozės ranką, kiekvienas pagal savo tarnystę ir pagal savo naštą; šitaip jie buvo jo suskaičiuoti, kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 4, 48, 'iš tų, kurie buvo jų suskaičiuoti, buvo aštuoni tūkstančiai penki šimtai aštuoniasdešimt.'),
  (@b4, 5, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 5, 2, '„Įsakyk Izraelio vaikams, kad jie išvarytų iš stovyklos kiekvieną raupsuotąjį, kiekvieną, turintį išsiliejimą, ir kiekvieną, susiteršusį mirusiuoju;'),
  (@b4, 5, 3, 'tiek vyriškos lyties, tiek moteriškos lyties asmenis išvarykite, išsiųskite juos už stovyklos; kad jie nesuterštų savo stovyklų, tarp kurių aš gyvenu“.'),
  (@b4, 5, 4, 'Ir Izraelio vaikai taip padarė ir išvarė juos už stovyklos; kaip VIEŠPATS kalbėjo Mozei, taip Izraelio vaikai padarė.'),
  (@b4, 5, 5, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 5, 6, '„Kalbėk Izraelio vaikams: ‘Kai vyras ar moteris padarys kokią nors žmonių daromą nuodėmę, nusižengdami prieš VIEŠPATĮ, ir tas asmuo yra kaltas;'),
  (@b4, 5, 7, 'tada jie išpažins savo nuodėmę, kurią jie padarė; ir atlygins savo nusižengimą su visa jo verte ir prie jos pridės penktą jos dalį, ir tai duos tam, prieš kurį nusižengė.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b4, 5, 8, 'Bet jei tas žmogus neturi giminaičio, kuriam atlygintų nusižengimą, tai nusižengimas tebūna atlyginamas VIEŠPAČIUI, kunigui; neskaitant sutaikinimo avino, kuriuo bus atliekamas sutaikinimas už jį.'),
  (@b4, 5, 9, 'Ir kiekviena visų Izraelio vaikų šventų dalykų atnaša, kurią jie atneša kunigui, bus jo.'),
  (@b4, 5, 10, 'Ir kiekvieno pašvęsti dalykai bus jo; kas ką duos kunigui, tai bus jo’“.'),
  (@b4, 5, 11, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 5, 12, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Jei kurio vyro žmona nuklysta ir jam nusižengia,'),
  (@b4, 5, 13, 'ir vyras sugula su ja kūniškai, o tai bus paslėpta nuo jos vyro akių ir bus laikoma paslaptyje, ir ji bus suteršta, o nėra liudytojo prieš ją, ir ji nėra pagauta taip elgiantis;'),
  (@b4, 5, 14, 'ir jį apimtų pavydo dvasia, ir jis pavyduliautų savo žmonai, ir ji būtų suteršta; arba jeigu jį apimtų pavydo dvasia, ir jis pavyduliautų savo žmonai, o ji nebūtų suteršta;'),
  (@b4, 5, 15, 'tada vyras atves savo žmoną pas kunigą ir jis atneš jos atnašą už ją – dešimtadalį efos miežinių miltų; jis neužpils ant jų aliejaus nei neuždės ant jų smilkalų; nes tai yra pavyduliavimo atnaša, priminimo atnaša, primenanti neteisybę.'),
  (@b4, 5, 16, 'Ir kunigas ją prives ir pastatys VIEŠPATIES akivaizdoje;'),
  (@b4, 5, 17, 'ir kunigas paims švento vandens moliniame inde; ir kunigas paims iš padangtės asloje esančių dulkių ir jas įdės į vandenį;'),
  (@b4, 5, 18, 'ir kunigas pastatys moterį VIEŠPATIES akivaizdoje, atidengs moters galvą ir padės ant jos rankų priminimo atnašą, kuri yra pavyduliavimo atnaša; o kunigas savo rankoje turės kartaus vandens, sukeliančio prakeikimą;'),
  (@b4, 5, 19, 'ir kunigas įpareigos ją prisiekti ir tai moteriai sakys: „Jei joks vyras negulėjo su tavimi ir jei nebuvai nuklydusi į nešvarumą su kitu vietoje savo vyro, tai būk laisva nuo šito kartaus vandens, sukeliančio prakeikimą;'),
  (@b4, 5, 20, 'bet jei buvai nuklydusi pas kitą vietoje savo vyro ir jei esi suteršta, ir kuris nors vyras be tavo vyro gulėjo su tavimi“;'),
  (@b4, 5, 21, 'tuomet kunigas įpareigos tą moterį prisiekti prakeikimo priesaika, ir kunigas sakys tai moteriai: „VIEŠPATS tave tepadaro prakeikimu ir priesaika tarp tavo tautos, kai VIEŠPATS daro, kad tavo šlaunis supūtų ir tavo pilvas sutintų;'),
  (@b4, 5, 22, 'ir šitas prakeikimą sukeliantis vanduo įeis į tavo vidurius, kad padarytų, jog sutintų tavo pilvas ir supūtų tavo šlaunis“; o moteris sakys: „Amen, amen“.'),
  (@b4, 5, 23, 'Ir kunigas užrašys šiuos prakeikimus į knygą ir nuplaus juos karčiuoju vandeniu;'),
  (@b4, 5, 24, 'ir jis lieps moteriai gerti prakeikimą sukeliantį kartų vandenį; ir prakeikimą sukeliantis vanduo įeis į ją ir taps kartus.'),
  (@b4, 5, 25, 'Tada kunigas paims iš moters rankos pavyduliavimo atnašą, mosuos tą atnašą VIEŠPATIES akivaizdoje ir ją atnašaus ant aukuro;'),
  (@b4, 5, 26, 'ir kunigas paims saują iš atnašos, jos atminimą, ir sudegins tai ant aukuro, o paskui duos moteriai gerti tą vandenį.'),
  (@b4, 5, 27, 'Jam pagirdžius ją vandeniu, tuomet įvyks – jei ji yra suteršta ir nusižengusi savo vyrui, į ją įeis prakeikimą sukeliantis vanduo ir taps kartus, ir sutins jos pilvas, ir supus jos šlaunis; ir ta moteris bus prakeikimu tarp savo tautos.'),
  (@b4, 5, 28, 'O jei ta moteris nėra suteršta, bet yra švari; tuomet ji bus laisva, ir joje užsimegs sėkla.'),
  (@b4, 5, 29, 'Šitas yra pavyduliavimo įstatymas, kai žmona nuklysta pas kitą vietoje savo vyro ir yra suteršta;'),
  (@b4, 5, 30, 'arba kai jį apima pavyduliavimo dvasia ir jis pavyduliauja dėl savo žmonos, ir pastatys moterį VIEŠPATIES akivaizdoje, o kunigas įvykdys jai visą šitą įstatymą.'),
  (@b4, 5, 31, 'Tada vyras bus nekaltas neteisybe, o ši moteris nešios savo neteisybę’“.'),
  (@b4, 6, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 6, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Kai vyras ar moteris atsiskiria, kad duotų naziro įžadą, kad atsiskirtų VIEŠPAČIUI;'),
  (@b4, 6, 3, 'jis atsiskirs nuo vyno ir stipraus gėrimo ir negers vyno acto ar stipraus gėrimo acto nei negers jokios vynuogių sunkos, nei nevalgys šviežių ar džiovintų vynuogių.'),
  (@b4, 6, 4, 'Visas savo atsiskyrimo dienas jis nevalgys nieko, kas pagaminta iš vynmedžio, nuo sėklelių iki odelės.'),
  (@b4, 6, 5, 'Visas savo atsiskyrimo įžado dienas skustuvas neužeis ant jo galvos; kol išsipildys dienos, kuriose jis atsiskyrė VIEŠPAČIUI, jis bus šventas ir leis augti savo galvos plaukų kasoms.'),
  (@b4, 6, 6, 'Visomis dienomis, kai jis atsiskiria VIEŠPAČIUI, jis neis prie jokio mirusio kūno.'),
  (@b4, 6, 7, 'Jis nesusiterš dėl savo tėvo ar dėl savo motinos, dėl savo brolio ar dėl savo sesers jiems mirus; nes jo Dievo įšventinimas yra ant jo galvos.'),
  (@b4, 6, 8, 'Visas savo atsiskyrimo dienas jis yra šventas VIEŠPAČIUI.'),
  (@b4, 6, 9, 'O jei kas labai staigiai numirtų šalia jo ir jis suterštų savo įšventinimo galvą; tuomet jis nusiskus galvą savo apsivalymo dieną, septintąją dieną ją nusiskus.'),
  (@b4, 6, 10, 'O aštuntąją dieną atneš du purplelius ar du jaunus karvelius kunigui prie susirinkimo padangtės durų;'),
  (@b4, 6, 11, 'ir kunigas atnašaus vieną kaip nuodėmės atnašą, o kitą kaip deginamąją atnašą, ir atliks sutaikinimą už jį, kadangi jis nusidėjo per mirusį, ir tą pačią dieną pašvęs savo galvą.'),
  (@b4, 6, 12, 'Ir jis įšventins VIEŠPAČIUI savo atsiskyrimo dienas ir atgabens pirmųjų metų avinėlį nusižengimo atnašai; bet ankstesnės dienos bus prarastos, nes jo atsiskyrimas buvo suterštas.'),
  (@b4, 6, 13, 'Ir šitas yra naziro įstatymas, kai išsipildys jo atsiskyrimo dienos; jis bus atvestas prie susirinkimo padangtės durų;'),
  (@b4, 6, 14, 'ir jis atnašaus savo atnašą VIEŠPAČIUI: vieną pirmųjų metų avinėlį be trūkumų deginamajai atnašai, vieną pirmųjų metų avį be trūkumų nuodėmės atnašai, vieną aviną be trūkumų taikos atnašoms'),
  (@b4, 6, 15, 'ir pintinę neraugintos duonos pyragų iš smulkių miltų, sumaišytų su aliejumi, ir neraugintos duonos papločių, pateptų aliejumi, jų maisto atnašą ir jų geriamąsias atnašas.'),
  (@b4, 6, 16, 'O kunigas tuos atneš VIEŠPATIES akivaizdon ir atnašaus jo nuodėmės atnašą bei jo deginamąją atnašą;'),
  (@b4, 6, 17, 'ir jis atnašaus aviną kaip taikos atnašų auką VIEŠPAČIUI su pintine neraugintos duonos; kunigas taip pat atnašaus jo maisto atnašą ir jo geriamąją atnašą.'),
  (@b4, 6, 18, 'Ir naziras nusiskus prie susirinkimo padangtės durų savo atsiskyrimo galvą, ims savo atsiskyrimo galvos plaukus ir juos įdės į ugnį, esančią po taikos atnašų auka.'),
  (@b4, 6, 19, 'Ir kunigas paims išvirtą avino petį, vieną neraugintą pyragą iš pintinės ir vieną neraugintą paplotį ir juos uždės ant naziro rankų po to, kai bus nuskusti jo atsiskyrimo plaukai;'),
  (@b4, 6, 20, 'ir kunigas juos mosuos kaip mosuojamąją atnašą VIEŠPATIES akivaizdoje; tai yra šventa kunigui su mosuojamąja krūtine ir iškeliamuoju pečiu; o paskui naziras gali gerti vyno.'),
  (@b4, 6, 21, 'Šitas yra įstatymas naziro, kuris davė įžadą, ir jo atnašos VIEŠPAČIUI dėl savo atsiskyrimo, neskaitant to, ką įgis jo ranka; pagal įžadą, kurį jis davė, taip jis turės daryti pagal savo atsiskyrimo įstatymą’“.'),
  (@b4, 6, 22, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 6, 23, '„Kalbėk Aaronui ir jo sūnums, sakydamas: ‘Taip jūs laiminsite Izraelio vaikus, jiems tardami:'),
  (@b4, 6, 24, '„VIEŠPATS telaimina tave ir tesaugo tave;'),
  (@b4, 6, 25, 'VIEŠPATS teapšviečia tave savo veidu ir tebūna tau maloningas;'),
  (@b4, 6, 26, 'VIEŠPATS tepakelia savo veidą į tave ir teduoda tau ramybę“.'),
  (@b4, 6, 27, 'Ir jie uždės mano vardą ant Izraelio vaikų; o aš juos laiminsiu’“.'),
  (@b4, 7, 1, 'Ir įvyko tą dieną, kai Mozė pilnai pastatė padangtę, patepė ją, pašventė ją ir visus jos įrankius, tiek aukurą, tiek visus jo įrankius, ir patepė juos, ir pašventė juos;'),
  (@b4, 7, 2, 'kad atnašavo Izraelio kunigaikščiai, jų tėvų namų galvos, kurie buvo genčių kunigaikščiai, ir vadovavo suskaičiuotiems;'),
  (@b4, 7, 3, 'ir jie atgabeno savo atnašą VIEŠPATIES akivaizdon: šešis dengtus vežimus ir dvylika jaučių; po vežimą nuo dviejų kunigaikščių ir po jautį nuo kiekvieno; ir jie atgabeno juos priešais padangtę.'),
  (@b4, 7, 4, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 7, 5, '„Imk tai iš jų, kad jie būtų susirinkimo padangtės tarnystei atlikti; ir duok juos levitams, kiekvienam pagal jo tarnystę“.'),
  (@b4, 7, 6, 'Ir Mozė ėmė vežimus bei jaučius ir juos davė levitams.'),
  (@b4, 7, 7, 'Du vežimus ir keturis jaučius jis davė Geršono sūnums pagal jų tarnystę;'),
  (@b4, 7, 8, 'keturis vežimus ir aštuonis jaučius jis davė Merario sūnums pagal jų tarnystę, vadovaujant kunigo Aarono sūnaus Itamaro rankai.'),
  (@b4, 7, 9, 'Bet Kehato sūnums jis nieko nedavė; nes jiems priklausanti šventovės tarnystė buvo ta, kad jie turėjo nešioti ant pečių.'),
  (@b4, 7, 10, 'Ir kunigaikščiai atnašavo aukuro įšventinimui tą dieną, kai jis buvo pateptas, kunigaikščiai atnašavo savo atnašą prieš aukurą.'),
  (@b4, 7, 11, 'Ir VIEŠPATS tarė Mozei: „Jie atnašaus savo atnašą, kiekvienas kunigaikštis savo dieną, aukuro įšventinimui“.'),
  (@b4, 7, 12, 'Ir tas, kuris pirmąją dieną atnašavo savo atnašą, buvo Aminadabo sūnus Nachšonas iš Judos genties;'),
  (@b4, 7, 13, 'o jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu buvo pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 14, 'vienas dešimties aukso šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 15, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 16, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 17, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Aminadabo sūnaus Nachšono atnaša.'),
  (@b4, 7, 18, 'Antrąją dieną atnašavo Cuaro sūnus Netanelis, Isacharo kunigaikštis;'),
  (@b4, 7, 19, 'jis atnašavo savo atnašai vieną sidabro dubenį šimto trisdešimties šekelių svorio, vieną septyniasdešimties šekelių sidabro taurę, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 20, 'vieną dešimties šekelių aukso šaukštą, pilną smilkalų;'),
  (@b4, 7, 21, 'vieną jauniklį jautuką, vieną aviną, vieną pirmų metų avinėlį, deginamajai atnašai;'),
  (@b4, 7, 22, 'vieną ožkiuką nuodėmės atnašai;'),
  (@b4, 7, 23, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Cuaro sūnaus Netanelio atnaša.'),
  (@b4, 7, 24, 'Trečiąją dieną atnašavo Helono sūnus Eliabas, Zebulono vaikų kunigaikštis;'),
  (@b4, 7, 25, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 26, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 27, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 28, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 29, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Helono sūnaus Eliabo atnaša.'),
  (@b4, 7, 30, 'Ketvirtąją dieną atnašavo Šedeūro sūnus Elicūras, Rubeno vaikų kunigaikštis;'),
  (@b4, 7, 31, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 32, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 33, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 34, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 35, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Šedeūro sūnaus Elicūro atnaša.'),
  (@b4, 7, 36, 'Penktąją dieną atnašavo Cūrišadajo sūnus Šelumielis, Simeono vaikų kunigaikštis;'),
  (@b4, 7, 37, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 38, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 39, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 40, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 41, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Cūrišadajo sūnaus Šelumielio atnaša.'),
  (@b4, 7, 42, 'Šeštąją dieną atnašavo Deuelio sūnus Eljasafas, Gado vaikų kunigaikštis;'),
  (@b4, 7, 43, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 44, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 45, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 46, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 47, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Deuelio sūnaus Eljasafo atnaša.'),
  (@b4, 7, 48, 'Septintąją dieną atnašavo Amihudo sūnus Elišama, Efraimo vaikų kunigaikštis;'),
  (@b4, 7, 49, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 50, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 51, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 52, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 53, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Amihudo sūnaus Elišamos atnaša.'),
  (@b4, 7, 54, 'Aštuntąją dieną atnašavo Pedahcūro sūnus Gamalielis, Manaso vaikų kunigaikštis;'),
  (@b4, 7, 55, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 56, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 57, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 58, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 59, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Pedahcūro sūnaus Gamalielio atnaša.'),
  (@b4, 7, 60, 'Devintąją dieną atnašavo Gideonio sūnus Abidanas, Benjamino vaikų kunigaikštis;'),
  (@b4, 7, 61, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 62, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 63, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 64, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 65, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Gideonio sūnaus Abidano atnaša.'),
  (@b4, 7, 66, 'Dešimtąją dieną atnašavo Amišadajo sūnus Ahiezeras, Dano vaikų kunigaikštis;'),
  (@b4, 7, 67, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 68, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 69, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 70, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 71, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Amišadajo sūnaus Ahiezero atnaša.'),
  (@b4, 7, 72, 'Vienuoliktąją dieną atnašavo Ochrano sūnus Pagielis, Ašero vaikų kunigaikštis;'),
  (@b4, 7, 73, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 74, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 75, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 76, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 77, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Ochrano sūnaus Pagielio atnaša.'),
  (@b4, 7, 78, 'Dvyliktąją dieną atnašavo Enano sūnus Ahyra, Naftalio vaikų kunigaikštis;'),
  (@b4, 7, 79, 'jo atnaša buvo vienas sidabro dubuo šimto trisdešimties šekelių svorio, viena septyniasdešimties šekelių sidabro taurė, pagal šventovės šekelį; tie abu pilni smulkių miltų, sumaišytų su aliejumi, maisto atnašai;'),
  (@b4, 7, 80, 'vienas auksinis dešimties šekelių šaukštas, pilnas smilkalų;'),
  (@b4, 7, 81, 'vienas jauniklis jautukas, vienas avinas, vienas pirmų metų avinėlis, deginamajai atnašai;'),
  (@b4, 7, 82, 'vienas ožkiukas nuodėmės atnašai;'),
  (@b4, 7, 83, 'o taikos atnašų aukai du jaučiai, penki avinai, penki ožiai, penki pirmų metų avinėliai; šita buvo Enano sūnaus Ahyros atnaša.'),
  (@b4, 7, 84, 'Šitas buvo aukuro įšventinimas nuo Izraelio kunigaikščių tą dieną, kai jis buvo pateptas: dvylika sidabro dubenų, dvylika sidabro taurių, dvylika aukso šaukštų;'),
  (@b4, 7, 85, 'kiekvienas sidabro dubuo svėrė šimtą trisdešimt šekelių, kiekviena taurė – septyniasdešimt; visi sidabro indai svėrė du tūkstančius keturis šimtus šekelių pagal šventovės šekelį;'),
  (@b4, 7, 86, 'auksinių šaukštų, pilnų smilkalų, buvo dvylika, kiekvienam sveriant dešimt šekelių pagal šventovės šekelį; visas šaukštų auksas buvo šimtas dvidešimt šekelių.'),
  (@b4, 7, 87, 'visų jaučių deginamajai atnašai buvo dvylika jautukų, avinų – dvylika, pirmų metų avinėlių – dvylika, su jų maisto atnaša; ir dvylika ožkiukų nuodėmės atnašai.'),
  (@b4, 7, 88, 'O visų jaučių taikos atnašų aukai buvo dvidešimt keturi jautukai, avinų – šešiasdešimt, ožių – šešiasdešimt, pirmų metų avinėlių – šešiasdešimt. Šitas buvo įšventinimas aukuro po to, kai jis buvo pateptas.'),
  (@b4, 7, 89, 'O kai Mozė įėjo į susirinkimo padangtę kalbėtis su juo, išgirdo balsą, kalbančiojo jam nuo gailestingumo krasės, esančios ant Liudijimo skrynios, iš dviejų kerubų tarpo; ir jis kalbėjo jam.'),
  (@b4, 8, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 8, 2, '„Kalbėk Aaronui ir jam sakyk: ‘Kai uždegsi žibintus, septyni žibintai švies žvakidės priešakyje’“.'),
  (@b4, 8, 3, 'Ir Aaronas taip padarė: jis uždegė jos žibintus žvakidės priešakyje, kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 8, 4, 'Ir šis žvakidės dirbinys buvo iš nukalto aukso, iki jos koto, iki jos gėlių, buvo nukaltas dirbinys; pagal pavyzdį, kurį VIEŠPATS buvo parodęs Mozei, taip jis padarė žvakidę.'),
  (@b4, 8, 5, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 8, 6, '„Imk levitus iš Izraelio vaikų tarpo ir juos apvalyk.'),
  (@b4, 8, 7, 'Ir taip jiems padaryk, kad juos apvalytum: apšlakstyk juos apvalymo vandeniu, ir jie tenusiskuta visą savo kūną ir teišplauna savo drabužius, ir taip apsivalys.'),
  (@b4, 8, 8, 'Tada jie teima jauniklį jautuką su jo maisto atnaša, tai yra, smulkiais miltais, sumaišytais su aliejumi, ir paimk kitą jauniklį jautuką nuodėmės atnašai.'),
  (@b4, 8, 9, 'Ir atvesk levitus priešais susirinkimo padangtę; ir surink visą Izraelio vaikų susirinkimą;'),
  (@b4, 8, 10, 'ir atvesk levitus VIEŠPATIES akivaizdon; o Izraelio vaikai uždės savo rankas ant levitų;'),
  (@b4, 8, 11, 'ir Aaronas atnašaus levitus kaip Izraelio vaikų atnašą VIEŠPATIES akivaizdoje, kad jie vykdytų VIEŠPATIES tarnystę.'),
  (@b4, 8, 12, 'O levitai uždės savo rankas ant jautukų galvų; ir vieną atnašauk kaip nuodėmės atnašą, o kitą – kaip deginamąją atnašą VIEŠPAČIUI, kad atliktum sutaikinimą už levitus.'),
  (@b4, 8, 13, 'Ir pastatyk levitus Aarono akivaizdon ir jo sūnų akivaizdon ir atnašauk juos kaip atnašą VIEŠPAČIUI.'),
  (@b4, 8, 14, 'Taip išskirsi levitus iš Izraelio vaikų tarpo; ir levitai bus mano.'),
  (@b4, 8, 15, 'O po to levitai įeis, kad atliktų susirinkimo padangtės tarnystę; ir juos apvalyk ir atnašauk juos kaip atnašą.'),
  (@b4, 8, 16, 'Nes jie yra visiškai man duoti iš Izraelio vaikų tarpo; vietoj tokių, kurie atveria kiekvienas įsčias, tai yra, vietoje visų Izraelio vaikų pirmagimių, aš juos pasiėmiau sau.'),
  (@b4, 8, 17, 'Nes visi Izraelio vaikų pirmagimiai yra mano, tiek žmonės tiek gyvuliai; tą dieną, kai aš užmušiau visus pirmagimius Egipto šalyje, aš juos sau pašvenčiau.'),
  (@b4, 8, 18, 'Ir ėmiau levitus už visus Izraelio vaikų pirmagimius.'),
  (@b4, 8, 19, 'Ir daviau levitus kaip dovaną Aaronui ir jo sūnums iš Izraelio vaikų tarpo, kad vykdytų Izraelio vaikų tarnystę susirinkimo padangtėje ir atliktų sutaikinimą už Izraelio vaikus; kad jokios rykštės nebūtų Izraelio vaikų tarpe, Izraelio vaikams besiartinant prie šventovės“.'),
  (@b4, 8, 20, 'Ir Mozė ir Aaronas bei visas Izraelio vaikų susirinkimas padarė levitams pagal visa, ką VIEŠPATS įsakė Mozei apie levitus, taip jiems padarė Izraelio vaikai.'),
  (@b4, 8, 21, 'Ir levitai buvo apvalyti ir jie išplovė savo drabužius; ir Aaronas atnašavo juos kaip atnašą VIEŠPATIES akivaizdoje; ir Aaronas atliko už juos sutaikinimą, kad juos apvalytų.'),
  (@b4, 8, 22, 'O po to levitai įėjo, kad atliktų savo tarnystę susirinkimo padangtėje Aarono akivaizdoje ir jo sūnų akivaizdoje; kaip VIEŠPATS buvo įsakęs Mozei apie levitus, taip jie padarė jiems.'),
  (@b4, 8, 23, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 8, 24, '„Tai yra tai, kas priklauso levitams: nuo dvidešimt penkerių metų ir vyresni jie įeis, kad patarnautų susirinkimo padangtės tarnystėje;'),
  (@b4, 8, 25, 'o nuo penkiasdešimties metų jie nustos patarnauti jos tarnystėje ir daugiau nebetarnaus;'),
  (@b4, 8, 26, 'tačiau tarnaus su savo broliais susirinkimo padangtėje, kad vykdytų pareigas, bet neturės atlikti tarnystės. Šitaip padaryk levitams dėl jų pareigų“.'),
  (@b4, 9, 1, 'Ir VIEŠPATS kalbėjo Mozei Sinajaus dykumoje antrųjų metų pirmąjį mėnesį po to, kai jie buvo išėję iš Egipto šalies, sakydamas:'),
  (@b4, 9, 2, '„Izraelio vaikai taip pat tešvenčia Apėjimą jo nustatytu laiku.'),
  (@b4, 9, 3, 'Šio mėnesio keturioliktąją dieną, vakare, jį švęsite jo nustatytu laiku; švęskite jį pagal visus jo ritualus ir pagal visas jo apeigas“.'),
  (@b4, 9, 4, 'Ir Mozė kalbėjo Izraelio vaikams, kad jie švęstų Apėjimą.'),
  (@b4, 9, 5, 'Ir jie šventė Apėjimą pirmojo mėnesio keturioliktąją dieną, vakare, Sinajaus dykumoje; Izraelio vaikai padarė pagal visa tai, ką VIEŠPATS įsakė Mozei.'),
  (@b4, 9, 6, 'Ir buvo tokių, kurie buvo susiteršę mirusiu žmogaus kūnu, kad tą dieną jie negalėjo švęsti Apėjimo; ir tą dieną jie atėjo Mozės akivaizdon ir Aarono akivaizdon;'),
  (@b4, 9, 7, 'ir tie žmonės jam tarė: „Mes esame susiteršę mirusiu žmogaus kūnu; kodėl esame sulaikyti, kad negalėtume atnašauti VIEŠPATIES atnašos jos nustatytu laiku Izraelio vaikų tarpe?“'),
  (@b4, 9, 8, 'Ir Mozė jiems tarė: „Pastovėkite nejudėdami, o aš išgirsiu, ką VIEŠPATS įsakys dėl jūsų“.'),
  (@b4, 9, 9, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 9, 10, '„Kalbėk Izraelio vaikams, sakydamas: ‘Jei kas iš jūsų ar iš jūsų palikuonių bus nešvarus dėl mirusio kūno ar bus tolimoje kelionėje, visgi jis švęs Apėjimą VIEŠPAČIUI.'),
  (@b4, 9, 11, 'Antrojo mėnesio keturioliktąją dieną, vakare, jie švęs jį, valgydami jį su nerauginta duona ir karčiomis žolėmis.'),
  (@b4, 9, 12, 'Nepaliks iš jo nieko iki ryto nei nesulaužys nei vieno jo kaulo; jie laikysis jo pagal visus Apėjimo įsakus.'),
  (@b4, 9, 13, 'Bet žmogus, kuris yra švarus ir nėra kelionėje, o susilaiko švęsti Apėjimą, ta siela bus iškirsta iš savo tautos tarpo; nes ji neatnešė VIEŠPATIES atnašos jos nustatytu laiku; tas žmogus nešios savo nuodėmę.'),
  (@b4, 9, 14, 'O jei ateivis laikinai apsigyvens tarp jūsų ir norės švęsti Apėjimą VIEŠPAČIUI; jis darys pagal Apėjimo įsaką ir pagal jo būdą; jums bus vienas įsakas tiek ateiviui, tiek šalyje gimusiam“.'),
  (@b4, 9, 15, 'Ir tą dieną, kai buvo pastatyta padangtė, debesis apdengė padangtę, tai yra Liudijimo palapinę; o vakare ant padangtės buvo tarsi ugnies reginys iki ryto.'),
  (@b4, 9, 16, 'Taip buvo visada: debesis ją dengė dieną, o ugnies reginys naktį.'),
  (@b4, 9, 17, 'O kai debesis pakildavo nuo padangtės, tai po to Izraelio vaikai keliaudavo; o toje vietoje, kur debesis apsistodavo, ten Izraelio vaikai statydavo savo palapines.'),
  (@b4, 9, 18, 'Pagal VIEŠPATIES įsakymą Izraelio vaikai keliaudavo ir pagal VIEŠPATIES įsakymą jie stovyklaudavo; tol, kol debesis likdavo ant padangtės, jie ilsėdavosi savo palapinėse.'),
  (@b4, 9, 19, 'Ir kai debesis ilgai užtrukdavo ant padangtės, tada Izraelio vaikai laikydavosi VIEŠPATIES įpareigojimo ir nekeliaudavo.'),
  (@b4, 9, 20, 'Ir taip buvo, kai debesis būdavo keletą dienų ant padangtės; pagal VIEŠPATIES įsakymą jie pasilikdavo savo palapinėse ir pagal VIEŠPATIES įsakymą jie keliaudavo.'),
  (@b4, 9, 21, 'Ir taip buvo, kai debesis pasilikdavo nuo vakaro iki ryto, o debesiui ryte pakilus, jie keliaudavo; ar tai buvo dieną ar naktį, kai debesis pakildavo, jie keliaudavo.'),
  (@b4, 9, 22, 'Ar tai būdavo dvi dienas, ar mėnesį, ar metus, kai debesis apsistodavo ant padangtės, ant jos pasilikdamas, Izraelio vaikai pasilikdavo savo palapinėse ir nekeliaudavo; bet jam pakilus, jie keliaudavo.'),
  (@b4, 9, 23, 'Pagal VIEŠPATIES įsakymą jie ilsėdavosi palapinėse ir pagal VIEŠPATIES įsakymą jie keliaudavo; jie laikėsi VIEŠPATIES įpareigojimo pagal VIEŠPATIES įsakymą per Mozės ranką.'),
  (@b4, 10, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 10, 2, '„Pasidaryk du sidabro trimitus; padaryk juos iš vieno gabalo; kad juos naudotum susirinkimui sušaukti ir stovykloms vykti į kelionę.'),
  (@b4, 10, 3, 'Ir jais papūtus, visas susirinkimas susirinks pas tave prie susirinkimo padangtės durų.'),
  (@b4, 10, 4, 'O jei tik vienu trimitu papūs, tada susirinks pas tave kunigaikščiai, Izraelio tūkstančių galvos.'),
  (@b4, 10, 5, 'Kai trimituosite pavojų, tada stovyklos, išsidriekusios rytiniame krašte, eis į priekį.'),
  (@b4, 10, 6, 'Kai antrą kartą trimituosite pavojų, tada stovyklos, išsidriekusios pietinėje pusėje, leisis kelionėn; jie trimituos pavojų dėl jų kelionių.'),
  (@b4, 10, 7, 'Bet surenkant susirinkimą trimituosite, tačiau neskelbsite pavojaus signalo.'),
  (@b4, 10, 8, 'O Aarono sūnūs, kunigai, trimituos tais trimitais; ir tie jums bus amžinu įsaku jūsų kartose.'),
  (@b4, 10, 9, 'O jei savo šalyje eisite į karą prieš jus engiantį priešą, tada trimituokite trimitais pavojų; ir jūs būsite atminti VIEŠPATIES, jūsų Dievo, akivaizdoje ir būsite išgelbėti iš savo priešų.'),
  (@b4, 10, 10, 'Taip pat jūsų džiaugsmo dieną, jūsų iškilmingomis dienomis ir jūsų mėnesių pradžiomis, trimituokite trimitais dėl savo deginamųjų atnašų ir dėl savo taikos atnašų aukų; kad jie jums būtų prisiminimui jūsų Dievo akivaizdoje: aš esu VIEŠPATS, jūsų Dievas“.'),
  (@b4, 10, 11, 'Ir įvyko, kad antraisias metais, antrojo mėnesio dvidešimtąją dieną, debesis pakilo nuo Liudijimo padangtės.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b4, 10, 12, 'Ir Izraelio vaikai leidosi į keliones iš Sinajaus dykumos; ir debesis ilsėjosi Parano dykumoje.'),
  (@b4, 10, 13, 'Ir pirmąkart jie leidosi kelionėn pagal VIEŠPATIES įsakymą per Mozės ranką.'),
  (@b4, 10, 14, 'Pirmiausia ėjo vėliava Judos vaikų stovyklos pagal jų kariuomenes; o jo kariuomenei vadovavo Aminadabo sūnus Nachšonas.'),
  (@b4, 10, 15, 'O Isacharo vaikų genties kariuomenei vadovavo Cuaro sūnus Netanelis.'),
  (@b4, 10, 16, 'O Zebulono vaikų genties kariuomenei vadovavo Helono sūnus Eliabas.'),
  (@b4, 10, 17, 'Ir buvo išardyta padangtė; ir išvyko Geršono sūnūs ir Merario sūnūs, nešdami padangtę.'),
  (@b4, 10, 18, 'Ir Rubeno stovyklos vėliava išvyko pagal jų kariuomenes; o jo kariuomenei vadovavo Šedeūro sūnus Elicūras.'),
  (@b4, 10, 19, 'O Simeono vaikų genties kariuomenei vadovavo Cūrišadajo sūnus Šelumielis.'),
  (@b4, 10, 20, 'O Gado vaikų genties kariuomenei vadovavo Deuelio sūnus Eljasafas.'),
  (@b4, 10, 21, 'Ir išvyko kehatai, nešdami šventovę; o prieš jiems ateinant, kiti padangtę pastatė.'),
  (@b4, 10, 22, 'Ir Efraimo vaikų stovyklos vėliava išvyko pagal jų kariuomenes; o jo kariuomenei vadovavo Amihudo sūnus Elišama.'),
  (@b4, 10, 23, 'O Manaso vaikų genties kariuomenei vadovavo Pedahcūro sūnus Gamalielis.'),
  (@b4, 10, 24, 'Ir Benjamino vaikų genties kariuomenei vadovavo Gideonio sūnus Abidanas.'),
  (@b4, 10, 25, 'Ir išvyko Dano vaikų stovyklos vėliava, kuri buvo visų stovyklų užnugaris jų kariuomenėse; o jo kariuomenei vadovavo Amišadajo sūnus Ahiezeras.'),
  (@b4, 10, 26, 'O Ašero vaikų genties kariuomenei vadovavo Ochrano sūnus Pagielis.'),
  (@b4, 10, 27, 'O Naftalio vaikų genties kariuomenei vadovavo Enano sūnus Ahyra.'),
  (@b4, 10, 28, 'Taip buvo Izraelio vaikų kelionės pagal jų kariuomenes, kai jie išvykdavo.'),
  (@b4, 10, 29, 'Ir Mozė tarė midjaniečio Reuelio sūnui Hobabui, Mozės uošviui: „Mes keliaujame į tą vietą, apie kurią VIEŠPATS pasakė: ‘Ją duosiu jums’; eik su mumis ir mes darysime tau gera; nes VIEŠPATS kalbėjo gera dėl Izraelio“.'),
  (@b4, 10, 30, 'O jis jam tarė: „Neisiu; tačiau aš išeisiu į savo šalį ir pas savo gimines“.'),
  (@b4, 10, 31, 'O jis tarė: „Nepalik mūsų, meldžiu tave; kadangi tu žinai, kaip mes turime stovyklauti dykumoje, tu galėtum mums būti vietoj akių.'),
  (@b4, 10, 32, 'Ir bus, jei eisi su mumis, kokį gerumą VIEŠPATS mums padarys, tą patį mes tau padarysime“.'),
  (@b4, 10, 33, 'Ir jie išvyko nuo VIEŠPATIES kalno trijų dienų kelionėn; o keliaujant tris dienas VIEŠPATIES Sandoros skrynia ėjo pirma jų, kad jiems surastų poilsio vietą.'),
  (@b4, 10, 34, 'Ir jiems išeinant iš stovyklos, VIEŠPATIES debesis buvo ant jų dienos metu.'),
  (@b4, 10, 35, 'Ir įvyko, kad skryniai išvykstant, Mozė sakė: „Kelkis, VIEŠPATIE, teišsisklaido tavo priešai; ir tebėga nuo tavo akivaizdos tavęs nekenčiantys“.'),
  (@b4, 10, 36, 'Ir jai ilsintis, jis sakė: „Sugrįšk, o VIEŠPATIE, pas Izraelio tūkstančių daugybę“.'),
  (@b4, 11, 1, 'Ir tautai skundžiantis, tai nepatiko VIEŠPAČIUI; ir VIEŠPATS tai išgirdo; ir užsidegė jo pyktis; ir VIEŠPATIES ugnis užsidegė tarp jų ir prarijo esančius tolimiausiame stovyklos krašte.'),
  (@b4, 11, 2, 'Ir tauta šaukė Mozei; o kai Mozė pasimeldė VIEŠPAČIUI, ugnis užgeso.'),
  (@b4, 11, 3, 'Ir tą vietą praminė vardu Tabera; nes tarp jų degė VIEŠPATIES ugnis.'),
  (@b4, 11, 4, 'O mišri minia, esanti tarp jų, buvo apimta geidulio; ir taip pat Izraelio vaikai vėl verkė, sakydami: „Kas mums duos mėsos valgyti?'),
  (@b4, 11, 5, 'Mes atsimename žuvis, kurių laisvai valgėme Egipte; agurkus, melionus, porus, svogūnus ir česnakus;'),
  (@b4, 11, 6, 'bet dabar išdžiūvo mūsų siela; be šitos manos prieš mūsų akis visiškai nieko nebėra“.'),
  (@b4, 11, 7, 'O mana buvo kaip kalendros sėkla, o jos spalva – kaip bdelijaus spalva.'),
  (@b4, 11, 8, 'Ir tauta vaikščiojo aplinkui, ją rinko, malė girnomis ar grūdo grūstuvėje, kepė skardose ir iš jos darė pyragus; o jos skonis buvo kaip šviežio aliejaus skonis.'),
  (@b4, 11, 9, 'Ir kai rasa naktį krito ant stovyklos, mana krito ant jos.'),
  (@b4, 11, 10, 'Tada Mozė išgirdo tautą verkiančią jų šeimose, kiekvieną prie savo palapinės durų; ir labai užsidegė VIEŠPATIES pyktis; taip pat ir Mozė buvo nepatenkintas.'),
  (@b4, 11, 11, 'Ir Mozė tarė VIEŠPAČIUI: „Kodėl kamuoji savo tarną ir kodėl neradau palankumo tavo akyse, kad uždėjai ant manęs visos šitos tautos naštą?'),
  (@b4, 11, 12, 'Argi aš pradėjau visą šitą tautą? Ar aš juos pagimdžiau, kad man sakytum: ‘Nešk juos savo prieglobstyje, kaip slaugantis tėvas neša žindomą vaiką’, į šalį, kurią prisiekei jų tėvams?'),
  (@b4, 11, 13, 'Iš kur man turėti mėsos, kad duočiau visai šitai tautai? Nes jie verkia man, sakydami: ‘Duok mums mėsos, kad valgytume’.'),
  (@b4, 11, 14, 'Aš vienas nepajėgiu nešti visos šitos tautos, nes tai man per sunku.'),
  (@b4, 11, 15, 'O jei tu taip elgiesi su manimi, meldžiu tave, nužudyk mane iš karto, jei esu radęs palankumą tavo akyse; ir neleisk man matyti savo apgailėtinumo“.'),
  (@b4, 11, 16, 'Ir VIEŠPATS tarė Mozei: „Surink man septyniasdešimt vyrų iš Izraelio vyresniųjų, kuriuos žinai, kad jie yra tautos vyresnieji ir jos pareigūnai; ir juos nuvesk prie susirinkimo padangtės, kad jie ten atsistotų su tavimi.'),
  (@b4, 11, 17, 'Ir aš nužengsiu ir ten kalbėsiu su tavimi; ir paimsiu iš Dvasios, kuri yra ant tavęs, ir uždėsiu jos ant jų; ir jie nešios tautos naštą su tavimi, kad tu vienas pats jos neneštum.'),
  (@b4, 11, 18, 'O tautai sakyk: ‘Pašvęskite save rytojui, ir valgysite mėsos; nes verkėte į VIEŠPATIES ausis, sakydami: „Kas mums duos mėsos valgyti? Nes mums gerai buvo Egipte“; todėl VIEŠPATS jums duos mėsos, ir jūs valgysite.'),
  (@b4, 11, 19, 'Jūs valgysite ne vieną dieną, ne dvi dienas, ne penkias dienas, ne dešimt dienų, ne dvidešimt dienų;'),
  (@b4, 11, 20, 'bet net visą mėnesį, kol ji išlįs jums per šnerves ir bus jums šlykšti; nes jūs išniekinote VIEŠPATĮ, kuris yra tarp jūsų, ir verkėte jo akivaizdoje, sakydami: „Kodėl mes išvykome iš Egipto?’“'),
  (@b4, 11, 21, 'O Mozė tarė: „Tauta, kurios tarpe aš esu, yra šeši šimtai tūkstančių pėstininkų; o tu pasakei: ‘Aš jiems duosiu mėsos, kad jie valgytų visą mėnesį’.'),
  (@b4, 11, 22, 'Ar jiems bus papjautos kaimenės ir bandos, kad jiems užtektų? Arba, ar jiems bus surinktos visos jūros žuvys, kad jiems užtektų?“'),
  (@b4, 11, 23, 'Ir VIEŠPATS tarė Mozei: „Argi VIEŠPATIES ranka sutrumpėjo? Dabar pamatysi, ar mano žodis tau išsipildys, ar ne“.'),
  (@b4, 11, 24, 'Ir išėjęs Mozė pasakė tautai VIEŠPATIES žodžius, ir surinko septyniasdešimt vyrų iš tautos vyresniųjų ir juos sustatė aplink padangtę.'),
  (@b4, 11, 25, 'Ir VIEŠPATS nužengė debesyje ir jam kalbėjo, ir paėmė ant jo buvusios Dvasios ir jos davė septyniasdešimčiai vyresniųjų; ir įvyko, kai Dvasia ilsėjosi ant jų, jie pranašavo ir nepaliovė.'),
  (@b4, 11, 26, 'Bet du iš vyrų buvo pasilikę stovykloje, vieno vardas buvo Eldadas, o kito vardas Medadas; ir Dvasia ilsėjosi ant jų; o jie buvo iš užrašytųjų, bet neišėjo prie padangtės; ir jie pranašavo stovykloje.'),
  (@b4, 11, 27, 'Ir jaunuolis nubėgo ir pasakė Mozei, sakydamas: „Eldadas ir Medadas pranašauja stovykloje“.'),
  (@b4, 11, 28, 'Ir Nūno sūnus Jozuė, Mozės tarnas, vienas iš jo jaunuolių, atsiliepdamas tarė: „Mano viešpatie Moze, uždrausk jiems“.'),
  (@b4, 11, 29, 'O Mozė jam tarė: „Ar pavydi dėl manęs? O kad visa VIEŠPATIES tauta būtų pranašai, kad VIEŠPATS uždėtų savo Dvasią ant jų!“'),
  (@b4, 11, 30, 'Ir Mozė įėjo į stovyklą, jis ir Izraelio vyresnieji.'),
  (@b4, 11, 31, 'Ir vėjas išėjo nuo VIEŠPATIES ir atgabeno nuo jūros putpelių ir jas numetė prie stovyklos, apie dienos kelionę į šitą pusę ir apie dienos kelionę į kitą pusę, aplink stovyklą, apie dviejų uolekčių aukščio ant žemės paviršiaus.'),
  (@b4, 11, 32, 'Ir tauta stojosi visą tą dieną, visą tą naktį ir visą kitą dieną, ir jie rinko putpeles; kas surinko mažiausiai, tas surinko dešimt homerų; ir jie jas visas paskleidė sau visur aplink stovyklą.'),
  (@b4, 11, 33, 'O mėsai dar tebesant tarp jų dantų, prieš ją sukramtant, VIEŠPATIES rūstybė užsidegė prieš tautą, ir VIEŠPATS ištiko tautą labai sunkia rykšte.'),
  (@b4, 11, 34, 'Ir tą vietą praminė vardu Kibrot-Hataava; nes ten jie palaidojo tautą, kuri geidė.'),
  (@b4, 11, 35, 'Iš Kibrot-Hataavos tauta keliavo į Hacerotą; ir pasiliko Hacerote.'),
  (@b4, 12, 1, 'Ir Mirjama ir Aaronas kalbėjo prieš Mozę dėl etiopės moters, kurią jis buvo vedęs; nes jis buvo vedęs etiopę moterį.'),
  (@b4, 12, 2, 'Ir jie sakė: „Ar iš tikrųjų tik per Mozę VIEŠPATS kalbėjo? Argi jis nekalbėjo ir per mus?“ O VIEŠPATS tai girdėjo.'),
  (@b4, 12, 3, '(Na, o tas vyras Mozė buvo labai romus, labiau už visus žmones, esančius ant žemės paviršiaus.)'),
  (@b4, 12, 4, 'Ir VIEŠPATS staiga tarė Mozei, Aaronui ir Mirjamai: „Jūs trys išeikite prie susirinkimo padangtės“. Ir jie trys išėjo.'),
  (@b4, 12, 5, 'Ir VIEŠPATS nužengė debesies stulpe, atsistojo padangtės duryse ir pašaukė Aaroną ir Mirjamą; ir juodu išėjo.'),
  (@b4, 12, 6, 'Ir jis tarė: „Klausykite dabar mano žodžių; jei bus pranašas tarp jūsų, aš, VIEŠPATS, regėjime jam apsireikšiu, sapne jam kalbėsiu.'),
  (@b4, 12, 7, 'Ne toks mano tarnas Mozė, kuris yra ištikimas visuose mano namuose.'),
  (@b4, 12, 8, 'Burna į burną kalbėsiu su juo, aiškiai, o ne paslaptingais žodžiais; jis matys VIEŠPATIES pavidalą; tai kodėl jūs nebijote kalbėti prieš mano tarną Mozę?“'),
  (@b4, 12, 9, 'Ir VIEŠPATIES pyktis užsidegė prieš juos; ir jis nuėjo.'),
  (@b4, 12, 10, 'Ir debesis pasišalino nuo padangtės; ir štai Mirjama tapo raupsuota, balta kaip sniegas; ir Aaronas pažvelgė į Mirjamą, ir štai ji buvo raupsuota.'),
  (@b4, 12, 11, 'Ir Aaronas tarė Mozei: „O, mano viešpatie, meldžiu tave, neuždėk ant mūsų nuodėmės, kuria mes kvailai padarėme ir kuria nusidėjome.'),
  (@b4, 12, 12, 'Tenebūna ji kaip mirusysis, kurio kūnas, jam išeinant iš savo motinos įsčių, pusiau sunykęs“.'),
  (@b4, 12, 13, 'Ir Mozė šaukė VIEŠPAČIUI, sakydamas: „O, Dieve, pagydyk ją dabar, meldžiu tave“.'),
  (@b4, 12, 14, 'O VIEŠPATS tarė Mozei: „Jei jos tėvas būtų tik spjovęs jai į veidą, argi ji nesigėdytų septynias dienas? Ji tebūna uždaryta septynioms dienoms už stovyklos, o po to ji vėl tebus priimta“.'),
  (@b4, 12, 15, 'Ir Mirjama buvo uždaryta už stovyklos septynias dienas; o tauta nekeliavo, kol Mirjama nebuvo vėl parvesta.'),
  (@b4, 12, 16, 'O po to tauta pasitraukė iš Haceroto ir stovyklavo Parano dykumoje.'),
  (@b4, 13, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 13, 2, '„Pasiųsk vyrus, kad jie ištirtų Kanaano šalį, kurią aš duodu Izraelio vaikams; siųsk iš kiekvienos jų tėvų genties po vyrą, kad kiekvienas būtų valdovas jų tarpe“.'),
  (@b4, 13, 3, 'Ir Mozė pagal VIEŠPATIES įsakymą išsiuntė juos iš Parano dykumos; visi tie vyrai buvo Izraelio vaikų galvos.'),
  (@b4, 13, 4, 'O šitie buvo jų vardai: iš Rubeno genties – Zakūro sūnus Šamūva;'),
  (@b4, 13, 5, 'iš Simeono genties – Horio sūnus Šafatas;'),
  (@b4, 13, 6, 'iš Judos genties – Jefunės sūnus Kalebas;'),
  (@b4, 13, 7, 'iš Isacharo genties – Juozapo sūnus Igalas;'),
  (@b4, 13, 8, 'iš Efraimo genties – Nūno sūnus Ošėja;'),
  (@b4, 13, 9, 'iš Benjamino genties – Rafuvo sūnus Paltis;'),
  (@b4, 13, 10, 'iš Zebulono genties – Sodžio sūnus Gadielis;'),
  (@b4, 13, 11, 'iš Juozapo genties, būtent iš Manaso genties, – Susio sūnus Gadis;'),
  (@b4, 13, 12, 'iš Dano genties – Gemalio sūnus Amielis;'),
  (@b4, 13, 13, 'iš Ašero genties – Mykolo sūnus Setūras;'),
  (@b4, 13, 14, 'iš Naftalio genties – Vofsio sūnus Nachbis;'),
  (@b4, 13, 15, 'iš Gado genties – Machio sūnus Geuelis.'),
  (@b4, 13, 16, 'Šitie yra vardai vyrų, kuriuos Mozė išsiuntė šalies išžvalgyti. O Nūno sūnų Ošėją Mozė praminė Jozue.'),
  (@b4, 13, 17, 'Ir Mozė išsiuntė juos Kanaano šalies ištirti, ir jiems tarė: „Eikite aukštyn tuo keliu į pietus ir užlipkite į kalną;'),
  (@b4, 13, 18, 'ir apžiūrėkite šalį, kokia ji yra; ir tautą, kuri joje gyvena: ar jie stiprūs, ar silpni, mažai jų ar daug;'),
  (@b4, 13, 19, 'ir kokia yra šalis, kurioje jie gyvena: ar gera, ar bloga; ir kokie miestai, kuriuose jie gyvena: ar palapinėse, ar tvirtovėse;'),
  (@b4, 13, 20, 'ir kokia yra žemė: ar ji riebi, ar liesa, ar joje yra medžių, ar ne. Ir būkite drąsūs ir parneškite iš tos žemės vaisių“. Na, o metas buvo pirmųjų prinokusių vynuogių metas.'),
  (@b4, 13, 21, 'Taigi jie nuėjo aukštyn ir ištyrė šalį nuo Cino dykumos iki Rehobo, kur ateinama į Hamatą.'),
  (@b4, 13, 22, 'Ir jie kilo pietų puse ir atėjo į Hebroną; kur buvo Ahimanas, Šešajas ir Talmajas, Anako vaikai (na, o Hebronas buvo pastatytas septyneriais metais anksčiau už Coaną Egipte).'),
  (@b4, 13, 23, 'Ir jie atėjo prie Eškolo upelio ir iš ten nupjovė šaką su viena keke vynuogių, ir jie ją nešė dviese ant lazdos; ir jie nešė granatų ir figų.'),
  (@b4, 13, 24, 'Ta vieta buvo pavadinta Eškolo upeliu dėl vynuogių kekės, kurią Izraelio vaikai iš ten nupjovė.'),
  (@b4, 13, 25, 'Ir jie sugrįžo iš šalies tyrinėjimo po keturiasdešimties dienų.'),
  (@b4, 13, 26, 'Ir jie nuėjo ir atvyko pas Mozę, Aaroną ir visą Izraelio vaikų susirinkimą, į Parano dykumą, į Kadešą; ir parnešė žinią jiems ir visam susirinkimui, ir jiems parodė šalies vaisių.'),
  (@b4, 13, 27, 'Ir jie jam pasakojo, tardami: „Mes atvykome į šalį, į kurią mus siuntei, ir ji tikrai plūsta pienu ir medumi; ir šis yra jos vaisius.'),
  (@b4, 13, 28, 'Tačiau stipri yra tauta, gyvenanti toje šalyje, ir miestai apsupti sienomis ir labai dideli; o be to, ten matėme Anako vaikus.'),
  (@b4, 13, 29, 'Amalekiečiai gyvena pietų šalyje; o hetitai, jebusiečiai ir amoritai gyvena kalnuose; o kanaaniečiai gyvena prie jūros ir palei Jordano krantą“.'),
  (@b4, 13, 30, 'Ir Kalebas nuramino tautą Mozės priešakyje ir tarė: „Tikrai kilkime ir ją pasisavinkime; nes mes esame visiškai pajėgūs ją nugalėti“.'),
  (@b4, 13, 31, 'Bet vyrai, ėję su juo aukštyn, sakė: „Mes nepajėgūs eiti aukštyn prieš tą tautą, nes jie yra stipresni už mus“.'),
  (@b4, 13, 32, 'Ir jie atnešė Izraelio vaikams blogą atsiliepimą apie tą šalį, kurią jie buvo ištyrę, sakydami: „Žemė, kurią perėjome, kad ją ištirtume, yra žemė, kuri suryja savo gyventojus; o visa tauta, kurią joje matėme, yra didelio ūgio žmonės.'),
  (@b4, 13, 33, 'Ir ten matėme milžinus, Anako sūnus, kilusius iš milžinų; o mes savo pačių akyse buvome kaip žiogai, ir tokie buvome jų akyse“.'),
  (@b4, 14, 1, 'Ir visas susirinkimas pakėlė savo balsą ir šaukė; ir tauta verkė tą naktį.'),
  (@b4, 14, 2, 'Ir visi Izraelio vaikai murmėjo prieš Mozę ir Aaroną; ir visas susirinkimas jiems tarė: „O kad būtume mirę Egipto šalyje arba būtume mirę šitoje dykumoje!'),
  (@b4, 14, 3, 'Ir kodėl VIEŠPATS atvedė mus į šitą šalį, kad kristume nuo kalavijo, kad mūsų žmonos ir mūsų vaikai būtų grobiu? Ar nebūtų mums geriau sugrįžti į Egiptą?“'),
  (@b4, 14, 4, 'Ir jie tarė vienas kitam: „Pasiskirkime vadą ir grįžkime į Egiptą“.'),
  (@b4, 14, 5, 'Tada Mozė ir Aaronas parpuolė veidais žemyn visos Izraelio vaikų susirinkimo sueigos akivaizdoje.'),
  (@b4, 14, 6, 'O Nūno sūnus Jozuė ir Jefunės sūnus Kalebas, kurie buvo iš tų, kurie ištyrė šalį, perplėšė savo drabužius;'),
  (@b4, 14, 7, 'ir jie kalbėjo visai Izraelio vaikų miniai, sakydami: „Ta žemė, kurią perėjome, kad ją ištirtume, yra nepaprastai gera žemė.'),
  (@b4, 14, 8, 'Jei VIEŠPATS mumis gėrėsis, tada jis mus įves į šitą šalį ir ją mums duos; šalį, plūstančią pienu ir medumi.'),
  (@b4, 14, 9, 'Tik nemaištaukite prieš VIEŠPATĮ nei nebijokite tos šalies tautos; nes jie yra mums duona; nuo jų pasitraukė jų apsauga, o VIEŠPATS yra su mumis; nebijokite jų“.'),
  (@b4, 14, 10, 'Bet visas susirinkimas liepė juos užmėtyti akmenimis. Ir VIEŠPATIES šlovė pasirodė susirinkimo padangtėje visų Izraelio vaikų akivaizdoje.'),
  (@b4, 14, 11, 'Ir VIEŠPATS tarė Mozei: „Kaip ilgai šita tauta mane kurstys? Ir kaip ilgai tai bus, kol jie tikės manimi dėl visų ženklų, kuriuos esu parodęs jų tarpe?'),
  (@b4, 14, 12, 'Aš jiems smogsiu maru ir iš jų atimsiu paveldėjimo teisę, o iš tavęs padarysiu didesnę tautą ir galingesnę už ją“.'),
  (@b4, 14, 13, 'Ir Mozė tarė VIEŠPAČIUI: „Tada egiptiečiai tai išgirs (nes tu savo galybe išvedei šitą tautą iš jų tarpo);'),
  (@b4, 14, 14, 'ir jie tai pasakys šitos šalies gyventojams; nes jie girdėjo, kad tu, VIEŠPATIE, esi šitos tautos tarpe, kad tu, VIEŠPATIE, esi regėtas akis į akį, ir tavo debesis stovi viršum jų, ir tu eini pirma jų debesies stulpe dienos metu, o ugnies stulpe naktį.'),
  (@b4, 14, 15, 'Na, o jei nužudysi visą šitą tautą kaip vieną žmogų, tuomet tautos, kurios girdėjo garsą apie tave, kalbės sakydamos:'),
  (@b4, 14, 16, '‘Kadangi VIEŠPATS nepajėgė įvesti šitos tautos į šalį, kurią jiems prisiekė, todėl jis juos išžudė dykumoje’.'),
  (@b4, 14, 17, 'O dabar, meldžiu tavęs, tebūna didelė mano VIEŠPATIES galia pagal tai, kaip esi kalbėjęs, sakydamas:'),
  (@b4, 14, 18, '‘VIEŠPATS yra ilgai pakenčiantis ir didžio gailestingumo, atleidžiantis neteisybę ir nusižengimą ir jokiu būdu nepateisinantis kaltojo, aplankantis tėvų neteisybę ant vaikų iki trečios ir ketvirtos kartos’.'),
  (@b4, 14, 19, 'Atleisk, meldžiu tave, šitos tautos neteisybę pagal tavo gailestingumo didybę ir kaip esi atleidęs šitai tautai nuo Egipto iki šiol“.'),
  (@b4, 14, 20, 'Ir VIEŠPATS tarė: „Aš atleidau pagal tavo žodį;'),
  (@b4, 14, 21, 'tačiau taip tikrai, kaip aš gyvas, visa žemė bus pripildyta VIEŠPATIES šlovės.'),
  (@b4, 14, 22, 'Kadangi visi tie, kurie matė mano šlovę ir mano stebuklus, kuriuos dariau Egipte ir dykumoje, mane gundė jau šiuos dešimt kartų ir neklausė mano balso;'),
  (@b4, 14, 23, 'jie tikrai neišvys šalies, kurią prisiekiau jų tėvams, ir nei vienas iš tų, kurie mane kurstė, jos nematys;'),
  (@b4, 14, 24, 'bet savo tarną Kalebą, kadangi jis turėjo kitą dvasią savyje ir sekė manimi iki galo, jį aš įvesiu į šalį, į kurią jis ėjo; ir jo sėkla ją pasisavins'),
  (@b4, 14, 25, '(na, o amalekiečiai ir kanaaniečiai gyveno slėnyje). Rytoj gręžkitės ir eikite į dykumą Raudonosios jūros keliu“.'),
  (@b4, 14, 26, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b4, 14, 27, '„Kaip ilgai turėsiu kęsti šitą piktą susirinkimą, kuris murma prieš mane? Aš girdėjau Izraelio vaikų murmėjimus, kuriais jie murma prieš mane.'),
  (@b4, 14, 28, 'Sakyk jiems: ‘Taip tikrai, kaip aš gyvas, sako VIEŠPATS, aš jums padarysiu taip, kaip jūs kalbėjote man į ausis;'),
  (@b4, 14, 29, 'šitoje dykumoje kris jūsų lavonai; ir visi iš jūsų suskaičiuotieji, pagal visą jūsų skaičių, nuo dvidešimties metų ir vyresni, kurie murmėjote prieš mane,'),
  (@b4, 14, 30, 'neabejotinai neįeisite į šalį, dėl kurios prisiekiau padaryti, kad joje gyventumėte, išskyrus Jefunės sūnų Kalebą ir Nūno sūnų Jozuę.'),
  (@b4, 14, 31, 'Tačiau jūsų mažylius, apie kuriuos sakėte, kad jie bus grobiu, juos aš įvesiu, ir jie pažins šalį, kurią jūs paniekinote.'),
  (@b4, 14, 32, 'Bet dėl jūsų, jūsų lavonai kris šitoje dykumoje.'),
  (@b4, 14, 33, 'O jūsų vaikai klaidžios šioje dykumoje keturiasdešimt metų ir nešios jūsų paleistuvystes, kol jūsų lavonai sunyks dykumoje.'),
  (@b4, 14, 34, 'Pagal skaičių dienų, kuriomis ištyrėte šalį, keturiasdešimt dienų, už kiekvieną dieną po metus, keturiasdešimt metų nešiosite savo neteisybes ir pažinsite mano pažado spragą.'),
  (@b4, 14, 35, 'Aš, VIEŠPATS, pasakiau, tikrai aš tai padarysiu visam šitam piktam susirinkimui, susirinkusiam prieš mane; šitoje dykumoje jie bus sunaikinti ir ten jie išmirs“.'),
  (@b4, 14, 36, 'O tie vyrai, kuriuos Mozė siuntė šalies ištirti, kurie sugrįžo ir padarė, kad visas susirinkimas murmėtų prieš jį, atnešdami blogą atsiliepimą apie tą šalį,'),
  (@b4, 14, 37, 'būtent tie vyrai, kurie atnešė piktą gandą apie šalį, mirė nuo rykštės VIEŠPATIES akivaizdoje.'),
  (@b4, 14, 38, 'Bet Nūno sūnus Jozuė ir Jefunės sūnus Kalebas, kurie buvo iš tų vyrų, kurie ėjo šalies ištirti, išliko gyvi.'),
  (@b4, 14, 39, 'Ir Mozė kalbėjo šituos pasakymus visiems Izraelio vaikams; ir tauta didžiai raudojo.'),
  (@b4, 14, 40, 'Ir jie atsikėlė anksti ryte ir užlipo ant kalno viršaus, sakydami: „Štai mes esame čia ir eisime aukštyn į vietą, kurią VIEŠPATS pažadėjo; nes mes nusidėjome“.'),
  (@b4, 14, 41, 'O Mozė tarė: „Kodėl nusižengiate VIEŠPATIES įsakymui? Tai nesiseks.'),
  (@b4, 14, 42, 'Neikite aukštyn, nes VIEŠPATS nėra tarp jūsų; kad nebūtumėte sumušti savo priešų akivaizdoje.'),
  (@b4, 14, 43, 'Nes amalekiečiai ir kanaaniečiai ten yra jūsų akivaizdoje, ir jūs krisite nuo kalavijo; kadangi nusigręžėte nuo VIEŠPATIES, todėl VIEŠPATS nebus su jumis“.'),
  (@b4, 14, 44, 'Bet jie drįso eiti aukštyn ant kalvos viršaus; tačiau VIEŠPATIES Sandoros skrynia ir Mozė neišėjo iš stovyklos.'),
  (@b4, 14, 45, 'Tada nusileido amalekiečiai ir kanaaniečiai, gyvenantys toje kalvoje, ir juos sumušė ir nugalėjo iki Hormos.'),
  (@b4, 15, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 15, 2, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Kai būsite įėję į jūsų buveinių šalį, kurią jums duodu,'),
  (@b4, 15, 3, 'ir norėsite atnašauti VIEŠPAČIUI ugnies atnašą, deginamąją atnašą ar auką atliekant įžadą, arba aukojant laisvos valios atnaša, arba savo iškilmingomis šventėmis, idant darytumėte gardų kvapą VIEŠPAČIUI iš bandos ar iš kaimenės;'),
  (@b4, 15, 4, 'tuomet tas, kuris atnašauja savo atnašą VIEŠPAČIUI, atneš maisto atnašą iš dešimtadalio miltų, sumaišytų su ketvirtadaliu hino aliejaus.'),
  (@b4, 15, 5, 'Ir ketvirtadalį hino vyno geriamajai atnašai paruoši su deginamąja atnaša ar auka vienam avinėliui.'),
  (@b4, 15, 6, 'Arba avinui paruoši kaip maisto atnašą du dešimtadalius miltų, sumaišytų su trečdaliu hino aliejaus.'),
  (@b4, 15, 7, 'O kaip geriamąją atnašą atnašausi trečdalį hino vyno, kaip gardų kvapą VIEŠPAČIUI.'),
  (@b4, 15, 8, 'O kai ruoši jautuką kaip deginamąją atnašą ar kaip auką atliekant įžadą, ar taikos atnašas VIEŠPAČIUI;'),
  (@b4, 15, 9, 'tuomet jis atneš su jautuku maisto atnašą iš trijų dešimtadalių miltų, sumaišytų su puse hino aliejaus.'),
  (@b4, 15, 10, 'O geriamajai atnašai atnešk pusę hino vyno, ugnies atnašą, kaip gardų kvapą VIEŠPAČIUI.'),
  (@b4, 15, 11, 'Taip bus daroma vienam jautukui ar vienam avinui, ar avinėliui, ar ožiukui.'),
  (@b4, 15, 12, 'Pagal skaičių, kuriuos paruošite, taip darykite kiekvienam pagal jų skaičių.'),
  (@b4, 15, 13, 'Kiekvienas tėvynainis tokiu būdu darys šiuos dalykus, atnašaudamas ugnies atnašą, kaip gardų kvapą VIEŠPAČIUI.'),
  (@b4, 15, 14, 'O jei ateivis laikinai apsigyvens pas jus arba kas tarp jūsų būtų jūsų kartose ir norėtų atnašauti ugnies atnašą kaip gardų kvapą VIEŠPAČIUI, tai, kaip jūs darote, taip ir jis darys.'),
  (@b4, 15, 15, 'Vienas įsakas bus tiek jums iš susirinkimo, tiek ir ateiviui, laikinai apsigyvenusiam pas jus, – amžinas įsakas jūsų kartose; kokie jūs esate, toks bus ir ateivis VIEŠPATIES akivaizdoje.'),
  (@b4, 15, 16, 'Vienas įstatymas ir vienas būdas bus jums ir ateiviui, laikinai apsigyvenusiam pas jus’“.'),
  (@b4, 15, 17, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 15, 18, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Kai ateisite į šalį, į kurią jus įvesiu,'),
  (@b4, 15, 19, 'tuomet bus, kai valgysite tos žemės duonos, atnašaukite iškeliamąją atnašą VIEŠPAČIUI.'),
  (@b4, 15, 20, 'Atnašaukite pyragą iš savo tešlos pirmienų kaip iškeliamąją atnašą; kaip keliate iškeliamąją atnašą klojimo, taip ją iškelkite.'),
  (@b4, 15, 21, 'Iš savo tešlos pirmienų duokite VIEŠPAČIUI keliamąją atnašą per savo kartas.'),
  (@b4, 15, 22, 'O jei klysite ir nesilaikysite visų šitų įsakymų, kuriuos VIEŠPATS yra kalbėjęs Mozei,'),
  (@b4, 15, 23, 'tai yra viso to, ką VIEŠPATS yra jums įsakęs per Mozės ranką nuo tos dienos, kai VIEŠPATS įsakė Mozei, ir po to jūsų kartų tarpe;'),
  (@b4, 15, 24, 'tuomet bus, jei kas bus padaryta per nežinojimą, susirinkimui nežinant, visas susirinkimas atnašaus vieną jauniklį jautuką deginamajai atnašai, kaip gardų kvapą VIEŠPAČIUI, su jo maisto atnaša bei jo geriamąja atnaša pagal būdą, ir vieną ožiuką nuodėmės atnašai.'),
  (@b4, 15, 25, 'Ir kunigas atliks sutaikinimą už visą Izraelio vaikų susirinkimą, ir jiems bus atleista; nes tai yra nežinojimas; o jie atneš savo atnašą, ugnies auką VlEŠPAČIUI ir savo nuodėmės atnašą VIEŠPATIES akivaizdon dėl savo nežinojimo;'),
  (@b4, 15, 26, 'ir bus atleista visam Izraelio vaikų susirinkimui ir ateiviui, laikinai apsigyvenusiam tarp jų; kadangi visa tauta buvo nežinojime.'),
  (@b4, 15, 27, 'O jei kuri siela nusideda per nežinojimą, tuomet ji atves pirmųjų metų ožką kaip nuodėmės atnašą.'),
  (@b4, 15, 28, 'O kunigas atliks sutaikinimą už sielą, nusižengusią nežinant, kai ji nusideda VIEŠPATIES akivaizdoje per nežinojimą, kad atliktų už ją sutaikinimą; ir jai bus atleista.'),
  (@b4, 15, 29, 'Turėkite vieną įstatymą tam, kuris nusideda per nežinojimą, tiek gimusiajam tarp Izraelio vaikų, tiek ir ateiviui, laikinai apsigyvenusiam tarp jų.'),
  (@b4, 15, 30, 'Bet siela, kuri ką nors daro sąmoningai, ar tai būtų gimusysis šalyje, ar ateivis, ji užtraukė VIEŠPAČIUI gėdą; ir ta siela bus iškirsta iš savo tautos tarpo.'),
  (@b4, 15, 31, 'Kadangi ji paniekino VIEŠPATIES žodį ir sulaužė jo įsakymą, ta siela bus visiškai iškirsta; jos neteisybė bus ant jos“.'),
  (@b4, 15, 32, 'Ir būdami dykumoje, Izraelio vaikai užtiko vyrą, renkantį pagalius sabato dieną.'),
  (@b4, 15, 33, 'O tie, kurie užtiko jį renkant pagalius, atvedė jį pas Mozę, Aaroną ir pas visą susirinkimą.'),
  (@b4, 15, 34, 'Ir jie uždarė jį saugoti, nes nebuvo paskelbta, kas jam turi būti padaryta.'),
  (@b4, 15, 35, 'Ir VIEŠPATS tarė Mozei: „Tas vyras tikrai bus užmuštas; visas susirinkimas jį užmėtys akmenimis už stovyklos“.'),
  (@b4, 15, 36, 'Ir visas susirinkimas jį išvedė už stovyklos ir užmėtė jį akmenimis, ir jis mirė; kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 15, 37, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 15, 38, '„Kalbėk Izraelio vaikams ir jiems įsakyk, kad jie pasidarytų kutus prie savo drabužių kraštų savo kartose, ir kad ant krašto kuto jie uždėtų juostą iš mėlyno:'),
  (@b4, 15, 39, 'ir tai jums bus kaip kutas, kad pažiūrėję į jį prisimintumėte visus VIEŠPATIES įsakymus ir juos vykdytumėte; ir kad jūs nesivaikytumėte savo širdies ir savo akių, paskui kurias jūs sekiodavote paleistuvauti;'),
  (@b4, 15, 40, 'kad atsimintumėte ir vykdytumėte visus mano įsakymus ir būtumėte šventi savo Dievui.'),
  (@b4, 15, 41, 'Aš esu VIEŠPATS, jūsų Dievas, kuris jus išvedžiau iš Egipto šalies, kad būčiau jūsų Dievas: aš esu VIEŠPATS, jūsų Dievas“.'),
  (@b4, 16, 1, 'Na, o Korachas – sūnus Iccharo, sūnus Kehato, sūnus Levio, ir Datanas bei Abiramas – sūnūs Eliabo, ir Onas, sūnus Peleto, – sūnūs Rubeno, paėmė vyrų;'),
  (@b4, 16, 2, 'ir jie pakilo prieš Mozę su kai kuriais iš Izraelio vaikų, dviem šimtais penkiasdešimt susirinkimo kunigaikščių, gerai žinomais susirinkime, garsiais vyrais;'),
  (@b4, 16, 3, 'ir jie susirinko prieš Mozę ir prieš Aaroną ir jiems tarė: „Jūs sau per daug prisiimate, nes visas susirinkimas, jie visi, yra šventi ir tarp jų yra VIEŠPATS; tai kodėl keliatės aukščiau VIEŠPATIES susirinkimo?“'),
  (@b4, 16, 4, 'Ir Mozė tai išgirdęs, parpuolė veidu žemėn;'),
  (@b4, 16, 5, 'ir jis kalbėjo Korachui bei visai jo draugijai, sakydamas: „Rytoj VIEŠPATS parodys, kas yra jo ir kas yra šventas; ir lieps jam prieiti prie savęs; tam, kurį jis išsirinko, lieps prieiti prie savęs.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b4, 16, 6, 'Tai darykite: Korachai, ir visa jo draugija, pasiimkite smilkytuvus;'),
  (@b4, 16, 7, 'ir rytoj įdėkite į juos ugnies ir įdėkite į juos smilkalų VIEŠPATIES akivaizdoje; ir bus, kad tas, kurį VIEŠPATS išsirinks, bus šventas; jūs sau per daug prisiimate, Levio sūnūs“.'),
  (@b4, 16, 8, 'Ir Mozė tarė Korachui: „Klausykite, meldžiu jus, Levio sūnūs;'),
  (@b4, 16, 9, 'atrodo jums per maža, kad Izraelio Dievas jus išskyrė iš Izraelio susirinkimo, kad jus priartintų prie savęs, idant atliktumėte VIEŠPATIES padangtės tarnystę ir stovėtumėte susirinkimo akivaizdoje jiems patarnauti?'),
  (@b4, 16, 10, 'Ir jis priartino tave prie savęs ir visus tavo brolius Levio sūnus su tavimi; o jūs siekiate ir kunigystės?'),
  (@b4, 16, 11, 'Dėl kokios priežasties tu ir visa tavo draugija susirinkote prieš VIEŠPATĮ; ir kas gi yra Aaronas, kad murmate prieš jį?“'),
  (@b4, 16, 12, 'Ir Mozė pasiuntė pašaukti Eliabo sūnus Dataną ir Abiramą; kurie tarė: „Mes neisime aukštyn;'),
  (@b4, 16, 13, 'ar per maža, kad mus atvedei aukštyn iš šalies, plūstančios pienu ir medumi, kad mus nužudytum dykumoje, kad dar pasidarytum ir mūsų kunigaikščiu?'),
  (@b4, 16, 14, 'Be to, tu neįvedei mūsų į šalį, plūstančią pienu ir medumi, nei nedavei mums paveldėti laukų ir vynuogynų; ar nori išlupti šitiems žmonėms akis? Mes neisime aukštyn“.'),
  (@b4, 16, 15, 'Ir labai užsirūstinęs Mozė tarė VIEŠPAČIUI: „Neatsižvelk į jų atnašą; aš nei vieno asilo neėmiau iš jų ir nei vienam iš jų nepadariau žalos“.'),
  (@b4, 16, 16, 'Ir Mozė tarė Korachui: „Tu ir visa tavo draugija būkite rytoj VIEŠPATIES akivaizdoje – tu, jie ir Aaronas;'),
  (@b4, 16, 17, 'ir kiekvienas imkite savo smilkytuvą ir įdėkite į juos smilkalų, ir kiekvienas atneškite VIEŠPATIES akivaizdon savo smilkytuvą, du šimtus penkiasdešimt smilkytuvų; taip pat tu ir Aaronas – kiekvienas iš jūsų savo smilkytuvą“.'),
  (@b4, 16, 18, 'Ir jie kiekvienas ėmė savo smilkytuvą, įdėjo į juos ugnies, uždėjo ant jų smilkalų ir atsistojo prie susirinkimo padangtės durų su Moze ir Aaronu.'),
  (@b4, 16, 19, 'Ir Korachas surinko prieš juos visą susirinkimą prie susirinkimo padangtės durų; ir VIEŠPATIES šlovė pasirodė visam susirinkimui.'),
  (@b4, 16, 20, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b4, 16, 21, '„Atsiskirkite iš šito susirinkimo tarpo, kad juos sunaikinčiau per vieną akimirką“.'),
  (@b4, 16, 22, 'Ir jie parpuolė veidais žemyn ir tarė: „O, Dieve, visų kūnų dvasių Dieve, ar vienam žmogui nusidėjus, užsirūstinsi ant viso susirinkimo?“'),
  (@b4, 16, 23, 'O VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 16, 24, '„Kalbėk susirinkimui, sakydamas: ‘Atsitraukite iš visų pusių nuo Koracho, Datano ir Abiramo padangčių’“.'),
  (@b4, 16, 25, 'Ir pakilęs Mozė ėjo pas Dataną ir Abiramą; o Izraelio vyresnieji ėjo paskui jį.'),
  (@b4, 16, 26, 'Ir jis kalbėjo susirinkimui, sakydamas: „Pasišalinkite, meldžiu jus, nuo šitų nedorų žmonių palapinių ir nelieskite nieko, kas yra jų, kad nebūtumėte sunaikinti visose jų nuodėmėse“.'),
  (@b4, 16, 27, 'Taigi jie atsitraukė nuo Koracho, Datano ir Abiramo padangčių iš visų pusių; o Datanas ir Abiramas išėję stovėjo savo palapinių duryse su savo žmonomis, savo sūnumis ir savo mažais vaikais.'),
  (@b4, 16, 28, 'Ir Mozė tarė: „Iš to pažinsite, kad VIEŠPATS mane siuntė daryti visus šiuos darbus; nes aš jų nedariau savo paties noru.'),
  (@b4, 16, 29, 'Jei šitie mirs įprasta visų žmonių mirtimi arba jeigu jie bus aplankyti kaip visi žmonės yra aplankomi; tuomet VIEŠPATS nėra manęs siuntęs.'),
  (@b4, 16, 30, 'Bet jei VIEŠPATS padarys naują dalyką, ir žemė, atvėrusi savo burną, juos praris su viskuo, kas jiems priklauso, ir jie gyvi nužengs į duobę; tuomet jūs suprasite, kad šitie žmonės kurstė VIEŠPATĮ“.'),
  (@b4, 16, 31, 'Ir įvyko, kad jam baigus kalbėti visus šituos žodžius, prasiskyrė žemė, kuri buvo po jais;'),
  (@b4, 16, 32, 'ir žemė atvėrė savo burną ir prarijo juos ir jų namus, ir visus žmones, priklausančius Korachui, ir visą jų turtą.'),
  (@b4, 16, 33, 'Jie ir visa, kas jiems priklausė, gyvi nužengė žemyn į duobę, ir žemė uždengė juos; ir jie pražuvo iš susirinkimo tarpo.'),
  (@b4, 16, 34, 'O visas Izraelis, kurie buvo aplink juos, jiems šaukiant, bėgo; nes jie sakė: „Kad žemė ir mūsų neprarytų“.'),
  (@b4, 16, 35, 'Ir ugnis išėjo nuo VIEŠPATIES ir prarijo du šimtus penkiasdešimt vyrų, kurie atnašavo smilkalus.'),
  (@b4, 16, 36, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 16, 37, '„Sakyk kunigo Aarono sūnui Eleazarui, kad jis iškeltų smilkytuvus iš degėsių, ir išsklaidyk ugnį ten; nes jie yra pašvęsti.'),
  (@b4, 16, 38, 'Smilkytuvus tų, nusidėjusiųjų prieš savo pačių sielas, teperdaro į plačias plokštes aukurui apdengti; nes jie atnašavo juos VIEŠPATIES akivaizdoje, todėl jie yra pašvęsti; ir jie bus ženklas Izraelio vaikams“.'),
  (@b4, 16, 39, 'Ir kunigas Eleazaras paėmė žalvarinius smilkytuvus, kuriais sudegintieji atnašavo; ir jie buvo perdaryti į plačias plokštes aukurui uždengti;'),
  (@b4, 16, 40, 'kad būtų atminimas Izraelio vaikams, kad joks svetimas, kuris nėra iš Aarono sėklos, nepriartėtų atnašauti smilkalų VIEŠPATIES akivaizdoje; kad jis nebūtų kaip Korachas ir jo draugija; kaip VIEŠPATS jam sakė per Mozės ranką.'),
  (@b4, 16, 41, 'Bet rytojaus dieną visas Izraelio vaikų susirinkimas murmėjo prieš Mozę ir prieš Aaroną, sakydamas: „Jūs nužudėte VIEŠPATIES tautą“.'),
  (@b4, 16, 42, 'Ir įvyko, kad susirinkimui susibūrus prieš Mozę bei Aaroną, jie pažiūrėjo į susirinkimo padangtę; ir štai debesis ją apdengė ir pasirodė VIEŠPATIES šlovė.'),
  (@b4, 16, 43, 'O Mozė ir Aaronas atėjo prieš susirinkimo padangtę.'),
  (@b4, 16, 44, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 16, 45, '„Išsikelkite iš šito susirinkimo tarpo, kad aš juos sunaikinčiau per vieną akimirką“. Ir jie parpuolė veidais žemyn.'),
  (@b4, 16, 46, 'Ir Mozė tarė Aaronui: „Imk smilkytuvą, įdėk į jį ugnies nuo aukuro, uždėk smilkalų ir skubiai nueik prie susirinkimo ir atlik už juos sutaikinimą; nes rūstybė yra išėjusi nuo VIEŠPATIES; prasidėjo rykštė“.'),
  (@b4, 16, 47, 'Ir Aaronas paėmė, kaip Mozė įsakė, ir nubėgo į susirinkimo vidurį; ir štai rykštė buvo prasidėjusi tautos tarpe; ir jis uždėjo smilkalų ir atliko sutaikinimą už tautą.'),
  (@b4, 16, 48, 'Ir jis stovėjo tarp mirusiųjų ir gyvųjų; ir rykštė liovėsi.'),
  (@b4, 16, 49, 'Na, o mirusiųjų nuo rykštės buvo keturiolika tūkstančių septyni šimtai neskaitant tų, kurie mirė dėl Koracho reikalo.'),
  (@b4, 16, 50, 'Ir Aaronas sugrįžo pas Mozę prie susirinkimo padangtės durų; ir rykštė liovėsi.'),
  (@b4, 17, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 17, 2, '„Kalbėk Izraelio vaikams ir imk iš kiekvieno iš jų po lazdą pagal jų tėvų namus, iš visų jų kunigaikščių pagal jų tėvų namus dvylika lazdų; užrašyk kiekvieno vardą ant jo lazdos.'),
  (@b4, 17, 3, 'Ir užrašyk Aarono vardą ant Levio lazdos; nes viena lazda bus kiekvienai jų tėvų namų galvai.'),
  (@b4, 17, 4, 'Ir padėk jas susirinkimo padangtėje priešais Liudijimą, kur aš susitiksiu su jumis.'),
  (@b4, 17, 5, 'Ir įvyks, kad lazda vyro, kurį aš išsirinksiu, sužydės; ir aš nutildysiu Izraelio vaikų murmėjimus, kuriais jie murma prieš jus“.'),
  (@b4, 17, 6, 'Ir Mozė kalbėjo Izraelio vaikams, ir visi jų kunigaikščiai jam davė po lazdą, po vieną už kiekvieną kunigaikštį, dvylika lazdų pagal jų tėvų namus; ir Aarono lazda buvo tarp jų lazdų.'),
  (@b4, 17, 7, 'Ir Mozė padėjo lazdas VIEŠPATIES akivaizdoje, Liudijimo padangtėje.'),
  (@b4, 17, 8, 'Ir įvyko, kad rytojaus dieną Mozė įėjo į Liudijimo padangtę; ir štai Aarono lazda už Levio namus buvo supumpuravusi, išleido pumpurus, pražydo žiedais ir davė migdolų.'),
  (@b4, 17, 9, 'Ir Mozė išnešė visas lazdas iš VIEŠPATIES akivaizdos pas visus Izraelio vaikus; ir jie pažiūrėjo ir kiekvienas pasiėmė savo lazdą.'),
  (@b4, 17, 10, 'Ir VIEŠPATS tarė Mozei: „Atnešk atgal Aarono lazdą priešais Liudijimą, kad būtų saugoma kaip ženklas prieš maištautojus; ir visiškai pašalink jų murmėjimus nuo manęs, kad jie nemirtų“.'),
  (@b4, 17, 11, 'Ir Mozė taip padarė; kaip VIEŠPATS jam įsakė, taip jis padarė.'),
  (@b4, 17, 12, 'Ir Izraelio vaikai kalbėjo Mozei, sakydami: „Štai mes mirštame, mes žūstame, mes visi žūstame.'),
  (@b4, 17, 13, 'Kiekvienas, kuris nors kiek priartėja prie VIEŠPATIES padangtės, mirs; ar mes būsime sunaikinti mirtimi?“'),
  (@b4, 18, 1, 'Ir VIEŠPATS tarė Aaronui: „Tu, tavo sūnūs ir tavo tėvų namai su tavimi nešiosite šventovės neteisingumą; tu ir tavo sūnūs su tavimi nešiosite savo kunigystės neteisingumą.'),
  (@b4, 18, 2, 'Taip pat savo brolius iš Levio genties, tavo tėvo genties, atsivesk su savimi, kad jie prisijungtų prie tavęs ir tau tarnautų; bet tu ir tavo sūnūs su tavimi tarnausite priešais Liudijimo padangtę.'),
  (@b4, 18, 3, 'Ir jie laikysis tavo pareigų ir visos padangtės pareigų; tik jie nepriartės prie šventovės įrankių ir aukuro, kad nei jie, nei jūs nemirtumėte.'),
  (@b4, 18, 4, 'Ir jie prisijungs prie tavęs ir laikysis susirinkimo padangtės pareigų, dėl viso padangtės tarnavimo; o svetimas nepriartės prie jūsų.'),
  (@b4, 18, 5, 'Ir laikykitės šventovės pareigų ir aukuro pareigų; kad daugiau nebebūtų rūstybės ant Izraelio vaikų.'),
  (@b4, 18, 6, 'Ir štai aš paėmiau jūsų brolius levitus iš Izraelio vaikų tarpo; jums jie yra duoti kaip dovana VIEŠPAČIUI, kad atliktų susirinkimo padangtės tarnavimą.'),
  (@b4, 18, 7, 'Todėl tu ir tavo sūnūs su tavimi vykdysite savo kunigystės tarnybą viskam, kas yra aukuro ir kas už uždangos; ir tarnaukite; aš daviau jums jūsų kunigystės tarnybą kaip dovanos tarnybą; o svetimas, kuris priartės, bus užmuštas“.'),
  (@b4, 18, 8, 'Ir VIEŠPATS kalbėjo Aaronui: „Štai taip pat aš tave įpareigojau dėl mano iškeliamų atnašų iš visų Izraelio vaikų pašvęstų dalykų; tau jas daviau dėl patepimo ir tavo sūnums, amžinu įsaku.'),
  (@b4, 18, 9, 'Tai bus tavo iš švenčiausių dalykų, išsaugotų nuo ugnies: kiekviena jų auka, kiekviena jų maisto atnaša, kiekviena jų nuodėmės atnaša ir kiekviena jų nusižengimo atnaša, kurias jie man duos, bus švenčiausia tau ir tavo sūnums.'),
  (@b4, 18, 10, 'Švenčiausioje vietoje tai valgyk; kiekvienas vyriškos lyties tai valgys; tau tai bus šventa.'),
  (@b4, 18, 11, 'Ir tai yra tavo: iškeliamoji atnaša jų dovanos su visomis Izraelio vaikų mosuojamomis atnašomis; tau jas daviau ir tavo sūnums bei tavo dukterims su tavimi amžinu įstatu; kiekvienas, kas yra švarus tavo namuose, tai valgys.'),
  (@b4, 18, 12, 'Visa, kas geriausia iš aliejaus, ir visa, kas geriausia iš vyno bei kviečių, jų pirmavaisiai, kuriuos jie atnašaus VIEŠPAČIUI, juos daviau tau.'),
  (@b4, 18, 13, 'Kas šalyje pirmiausia prinokę, kuriuos jie atneš VIEŠPAČIUI, bus tavo; tas, kuris yra švarus tavo šeimoje, tai valgys.'),
  (@b4, 18, 14, 'Visa, kas pašvęsta Izraelyje, bus tavo.'),
  (@b4, 18, 15, 'Visa, kas praveria gimdą iš visų kūnų, ar tai būtų iš žmonių, ar gyvulių, kuriuos jie atneša VIEŠPAČIUI, bus tavo; tačiau žmogaus pirmagimį visiškai atpirk ir nešvarių gyvulių pirmagimį atpirk.'),
  (@b4, 18, 16, 'O tuos, kurie turi būti atpirkti nuo mėnesio amžiaus, atpirk pagal savo įvertinimą už penkių šekelių pinigus, pagal šventovės šekelį, kuris yra dvidešimt gerų.'),
  (@b4, 18, 17, 'Tačiau neatpirk karvės pirmagimio ar avies pirmagimio, ar ožkos pirmagimio: jie yra šventi; jų kraują šlakstyk ant aukuro ir jų taukus sudegink kaip ugnies atnašą, kaip gardų kvapą VIEŠPAČIUI.'),
  (@b4, 18, 18, 'O jų mėsa bus tavo, kaip mosuojamoji krūtinė ir kaip dešinysis petys yra tavo.'),
  (@b4, 18, 19, 'Visas šventųjų dalykų iškeliamąsias atnašas, kurias Izraelio vaikai atnašauja VIEŠPAČIUI, daviau tau ir tavo sūnums bei tavo dukterims su tavimi amžinu įstatu; tai yra amžina druskos sandora VIEŠPATIES akivaizdoje tau ir tavo sėklai su tavimi“.'),
  (@b4, 18, 20, 'Ir VIEŠPATS kalbėjo Aaronui: „Jų šalyje neturėsi jokio paveldo nei neturėsi jokios dalies tarp jų: aš esu tavo dalis ir tavo paveldas tarp Izraelio vaikų.'),
  (@b4, 18, 21, 'O štai Levio vaikams daviau visas dešimtines Izraelyje kaip paveldą už jų tarnystę, kuria jie tarnauja, tai yra susirinkimo padangtės tarnystę.'),
  (@b4, 18, 22, 'Taip pat Izraelio vaikams nuo šiol nebegalima artintis prie susirinkimo padangtės, kad neneštų nuodėmės ir nemirtų.'),
  (@b4, 18, 23, 'Bet levitai atliks susirinkimo padangtės tarnystę, ir jie nešios jų neteisybę; tai bus amžinas įstatas per jūsų kartas, kad tarp Izraelio vaikų jie neturėtų paveldo.'),
  (@b4, 18, 24, 'Bet Izraelio vaikų dešimtines, kurias jie atnašauja VIEŠPAČIUI kaip iškeliamąją atnašą, aš daviau levitams paveldėti; todėl pasakiau jiems: ‘Tarp Izraelio vaikų jie neturės paveldo“.'),
  (@b4, 18, 25, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 18, 26, '„Taip kalbėk levitams ir jiems sakyk: ‘Kai imate iš Izraelio vaikų dešimtines, kurias jums daviau iš jų kaip jūsų paveldą, tuomet atnašaukite iš jų iškeliamąją atnašą VIEŠPAČIUI, tai yra, dešimtadalį dešimtinės.'),
  (@b4, 18, 27, 'Ir ši jūsų iškeliamoji atnaša bus jums įskaityta tartum tai būtų javai iš klojimo ir kaip pilnuma iš vyno spaustuvo.'),
  (@b4, 18, 28, 'Taip atnašaukite ir iškeliamąją atnašą VIEŠPAČIUI iš visų jūsų dešimtinių, kurias gaunate iš Izraelio vaikų; ir duokite iš tų VIEŠPATIES iškeliamąją atnašą kunigui Aaronui.'),
  (@b4, 18, 29, 'Iš visų jūsų dovanų atnašaukite kiekvieną VIEŠPATIES iškeliamąją atnašą, iš viso, kas jų geriausia – iš jų pašvęstą jų dalį“.'),
  (@b4, 18, 30, 'Todėl sakyk jiems: „Kai būsite iškėlę iš jų tai, kas jų geriausia, tuomet tai bus priskaičiuota levitams kaip klojimo prieaugis ir kaip vyno spaustuvo prieaugis.'),
  (@b4, 18, 31, 'Ir valgykite tai bet kurioje vietoje, jūs ir jūsų namiškiai; nes tai yra jūsų atlyginimas už jūsų tarnystę susirinkimo padangtėje.'),
  (@b4, 18, 32, 'Ir jūs dėl to nenešite nuodėmės, kai būsite iškėlę iš jų tai, kas jų geriausia; ir nesuterškite Izraelio vaikų šventų dalykų, kad nemirtumėte“.'),
  (@b4, 19, 1, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui, sakydamas:'),
  (@b4, 19, 2, '„Šitas yra įstatymo įsakas, kurį VIEŠPATS yra įsakęs, sakydamas: ‘Kalbėk Izraelio vaikams, kad jie tau atvestų žalą telyčią, be dėmės, neturinčią trūkumų, ant kurios dar nebuvo užėjęs jungas.'),
  (@b4, 19, 3, 'Ir duokite ją kunigui Eleazarui, kad jis išvestų ją už stovyklos ir ją kas papjautų prieš jo akis;'),
  (@b4, 19, 4, 'ir kunigas Eleazaras paims savo pirštu jos kraujo ir septynis kartus pašlakstys jos kraujo tiesiai prieš susirinkimo padangtę;'),
  (@b4, 19, 5, 'ir telyčią kuris tai vienas sudegins jo akyse; sudegins jos odą, jos mėsą ir jos kraują su jos mėšlu;'),
  (@b4, 19, 6, 'ir kunigas paims kedro medžio, yzopo ir skaisčiai raudono ir juos įmes į degančios telyčios vidurį.'),
  (@b4, 19, 7, 'Po to kunigas išplaus savo drabužius ir nusiplaus savo kūną vandenyje, o paskui jis įeis į stovyklą, ir kunigas bus nešvarus iki vakaro.'),
  (@b4, 19, 8, 'Ir tas, kuris ją sudegino, išplaus savo drabužius vandenyje ir nuplaus savo kūną vandenyje, ir bus nešvarus iki vakaro.'),
  (@b4, 19, 9, 'O švarus vyras susems telyčios pelenus ir juos padės švarioje vietoje už stovyklos, ir jie bus saugomi Izraelio vaikų susirinkimui, atskyrimo vandeniui; tai yra apsivalymas už nuodėmę.'),
  (@b4, 19, 10, 'O tas, kuris susems telyčios pelenus, išplaus savo drabužius, ir bus nešvarus iki vakaro; ir tai bus Izraelio vaikams ir ateiviui, laikinai apsigyvenusiam tarp jų, amžinas įstatas.'),
  (@b4, 19, 11, 'Kas palies kokio nors žmogaus mirusį kūną, bus nešvarus septynias dienas.'),
  (@b4, 19, 12, 'Jis juo apsivalys trečiąją dieną, o septintąją dieną jis bus švarus; bet jei jis neapsivalys trečiąją dieną, tuomet septintąją dieną jis nebus švarus.'),
  (@b4, 19, 13, 'Kas paliečia kokio nors mirusio žmogaus lavoną ir neapsivalo, tas suteršia VIEŠPATIES padangtę; ir ta siela bus iškirsta iš Izraelio; kadangi ant jo nebuvo apšlakstytas atskyrimo vanduo, jis bus nešvarus; jo nešvarumas tebėra ant jo.'),
  (@b4, 19, 14, 'Šitas yra įstatymas, kai žmogus miršta palapinėje: visi, kurie įeina į tą palapinę, ir visa, kas yra toje palapinėje, bus nešvaru septynias dienas.'),
  (@b4, 19, 15, 'Ir kiekvienas atviras indas, kuris neturi ant jo pririšto dangčio, yra nešvarus.'),
  (@b4, 19, 16, 'Ir kas palies užmuštąjį kalaviju atvirame lauke ar lavoną, ar žmogaus kaulus, ar kapą, bus nešvarus septynias dienas.'),
  (@b4, 19, 17, 'Ir nešvariajam asmeniui paims sudegintos telyčios apsivalymo už nuodėmę pelenų ir inde užpils ant jų tekančio vandens;'),
  (@b4, 19, 18, 'o švarus asmuo paims yzopo, jį pamerks į vandenį ir juo apšlakstys palapinę, visus indus, visus ten buvusius asmenis ir tą, kuris palietė kaulus ar užmuštąjį, ar mirusį, ar kapą;'),
  (@b4, 19, 19, 'ir švarusis asmuo apšlakstys nešvarųjį trečiąją dieną ir septintąją dieną; o septintąją dieną jis apsivalys, išplaus savo drabužius, nusiplaus vandenyje, ir vakare bus švarus.'),
  (@b4, 19, 20, 'Bet tas, kuris bus nešvarus ir neapsivalys, ta siela bus iškirsta iš susirinkimo tarpo, nes ji yra suteršusi VIEŠPATIES šventovę; atskyrimo vandens nebuvo apšlakstyta ant jos; ji yra nešvari.'),
  (@b4, 19, 21, 'Ir tai jiems bus amžinas įstatas, kad tas, kuris šlaksto atskyrimo vandenį, išplaus savo drabužius; ir tas, kuris palies atskyrimo vandenį, bus nešvarus iki vakaro.'),
  (@b4, 19, 22, 'Ir ką nešvarusis asmuo palies, bus nešvaru; ir siela, kuri tai palies, bus nešvari iki vakaro’“.'),
  (@b4, 20, 1, 'Tuomet pirmąjį mėnesį Izraelio vaikai, tai yra visas susirinkimas, atvyko į Cino dykumą; ir tauta apsistojo Kadeše; ir mirė ten Mirjama, ir ten buvo palaidota.'),
  (@b4, 20, 2, 'Ir susirinkimui nebuvo vandens; ir jie susirinko prieš Mozę ir prieš Aaroną.'),
  (@b4, 20, 3, 'Ir tauta barėsi su Moze ir kalbėjo, sakydami: „O, kad būtume mirę, kai mūsų broliai mirė VIEŠPATIES akivaizdoje!'),
  (@b4, 20, 4, 'Ir kodėl atvedėte VIEŠPATIES susirinkimą aukštyn į šitą dykumą, kad mes ir mūsų galvijai čia mirtume?'),
  (@b4, 20, 5, 'Ir kodėl padarėte, kad išeitume aukštyn iš Egipto, kad mus atvestumėte į šitą blogą vietą? Tai vieta ne sėklų, ne figmedžių, ne vynmedžių ir ne granatmedžių; nei vandens nėra gerti“.'),
  (@b4, 20, 6, 'Ir Mozė bei Aaronas nuėjo nuo susirinkimo akivaizdos prie susirinkimo padangtės durų ir jie parpuolė veidais žemyn; ir jiems pasirodė VIEŠPATIES šlovė.'),
  (@b4, 20, 7, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 20, 8, '„Paimk lazdą ir surink susirinkimą, tu ir tavo brolis Aaronas, ir kalbėkite uolai jų akyse; ir ji išleis savo vandenį, ir tu jiems išgausi vandens iš uolos; taip pagirdysi susirinkimą ir jų gyvulius’“.'),
  (@b4, 20, 9, 'Ir Mozė paėmė lazdą iš VIEŠPATIES akivaizdos, kaip jis jam įsakė.'),
  (@b4, 20, 10, 'Ir Mozė bei Aaronas surinko susirinkimą priešais uolą, ir jis jiems tarė: „Na, klausykite jūs, maištininkai; ar mes turime iš šitos uolos jums išgauti vandens?“'),
  (@b4, 20, 11, 'Ir Mozė pakėlė savo ranką ir du kartus smogė savo lazda į uolą; ir gausiai išsiliejo vanduo, ir susirinkimas gėrė, ir taip pat jų gyvuliai.'),
  (@b4, 20, 12, 'Ir VIEŠPATS tarė Mozei ir Aaronui: „Kadangi netikėjote manimi, kad mane pašvęstumėte Izraelio vaikų akyse, todėl neįvesite šito susirinkimo į šalį, kurią jiems daviau“.'),
  (@b4, 20, 13, 'Tai Meribos vanduo; nes Izraelio vaikai vaidijosi su VIEŠPAČIU, ir jis buvo pašvęstas juose.'),
  (@b4, 20, 14, 'Ir Mozė išsiuntė pasiuntinius iš Kadešo pas Edomo karalių: „Taip sako tavo brolis Izraelis: Tu žinai visą vargą, kuris mus ištiko;'),
  (@b4, 20, 15, 'kaip mūsų tėvai nusileido į Egiptą, ir mes ilgą laiką gyvenome Egipte; ir egiptiečiai spaudė mus bei mūsų tėvus;'),
  (@b4, 20, 16, 'ir mums šaukiantis VIEŠPATIES, jis išgirdo mūsų balsą ir pasiuntė angelą, ir mus išvedė iš Egipto; ir štai mes esame Kadeše, tavo tolimiausių ribų mieste;'),
  (@b4, 20, 17, 'meldžiu tave, leisk mums pereiti per tavo šalį; mes neisime per laukus ar vynuogynus nei negersime šulinių vandens; mes eisime karaliaus vieškeliu, nepasuksime nei į dešinę, nei į kairę, kol pereisime tavo ribas“.'),
  (@b4, 20, 18, 'O Edomas jam tarė: „Tu neisi per mane, kad neišeičiau prieš tave su kalaviju“.'),
  (@b4, 20, 19, 'O Izraelio vaikai jam tarė: „Mes eisime vieškeliu; o jei aš ir mano galvijai gersime tavo vandens, tuomet aš sumokėsiu už jį; aš tik pereisiu pėsčias, nieko kita nedarydamas“.'),
  (@b4, 20, 20, 'O jis tarė: „Tu nepereisi“. Ir Edomas išėjo prieš jį su daug liaudies ir stipria ranka.'),
  (@b4, 20, 21, 'Taip Edomas atsisakė leisti Izraeliui pereiti per jo ribas; todėl Izraelis pasuko šalin nuo jo.'),
  (@b4, 20, 22, 'Ir Izraelio vaikai, tai yra visas susirinkimas, keliavo iš Kadešo ir atvyko prie Horo kalno.'),
  (@b4, 20, 23, 'Ir VIEŠPATS kalbėjo Mozei ir Aaronui Horo kalne, prie Edomo šalies ribos, sakydamas:'),
  (@b4, 20, 24, '„Aaronas bus surinktas prie savo tautos; nes jis neįeis į šalį, kurią daviau Izraelio vaikams, kadangi jūs priešinotės mano žodžiui prie Meribos vandens.'),
  (@b4, 20, 25, 'Imk Aaroną ir jo sūnų Eleazarą ir užvesk juos ant Horo kalno.'),
  (@b4, 20, 26, 'Ir nuvilk nuo Aarono jo drabužius ir apvilk jais jo sūnų Eleazarą; o Aaronas bus surinktas prie savo tautos ir ten mirs“.'),
  (@b4, 20, 27, 'Ir Mozė padarė, kaip VIEŠPATS įsakė; ir jie užlipo į Horo kalną viso susirinkimo akyse.'),
  (@b4, 20, 28, 'Ir Mozė nuvilko nuo Aarono jo drabužius ir apvilko jais jo sūnų Eleazarą; ir Aaronas ten mirė kalno viršūnėje; o Mozė ir Eleazaras nulipo nuo kalno.'),
  (@b4, 20, 29, 'Ir matydamas, kad Aaronas miręs, visas susirinkimas apraudojo Aaroną trisdešimt dienų, būtent visi Izraelio namai.'),
  (@b4, 21, 1, 'O kanaanietis karalius Aradas, gyvenantis pietuose, išgirdęs kalbant, kad Izraelis atėjo žvalgų keliu; susikovė su Izraeliu ir paėmė kai kuriuos iš jų į nelaisvę.'),
  (@b4, 21, 2, 'Ir Izraelis davė VIEŠPAČIUI įžadą, sakydamas: „Jei tikrai atiduosi šitą tautą į mano ranką, tuomet visiškai sunaikinsiu jų miestus“.'),
  (@b4, 21, 3, 'Ir VIEŠPATS išklausė Izraelio balso ir atidavė kanaaniečius; ir jie visiškai sunaikino juos ir jų miestus; ir jis praminė tą vietą vardu Horma.'),
  (@b4, 21, 4, 'Ir jie keliavo nuo Horo kalno Raudonosios jūros keliu, kad aplenktų Edomo šalį; o tautos siela neteko daug drąsos dėl kelio.'),
  (@b4, 21, 5, 'Ir tauta kalbėjo prieš Dievą ir prieš Mozę: „Kodėl jūs mus išvedėte aukštyn iš Egipto, kad mirtume dykumoje? Nes nėra nei duonos, nei vandens; ir mūsų siela bjaurisi šita lengva duona“.'),
  (@b4, 21, 6, 'Ir VIEŠPATS siuntė į tautos tarpą ugningas gyvates, ir jos gėlė tautai; ir daug Izraelio tautos išmirė.'),
  (@b4, 21, 7, 'Todėl tauta atėjo pas Mozę ir tarė: „Mes nusidėjome, nes kalbėjome prieš VIEŠPATĮ ir prieš tave; melskis VIEŠPAČIUI, kad jis pašalintų nuo mūsų gyvates“. Ir Mozė meldėsi už tautą.'),
  (@b4, 21, 8, 'Ir VIEŠPATS tarė Mozei: „Pasidirbk ugningą gyvatę ir pritaisyk ją prie karties; ir įvyks, kad kiekvienas įgeltasis, pažvelgęs į ją, išliks gyvas“.'),
  (@b4, 21, 9, 'Ir Mozė padarė žalvario gyvatę ir pritaisė ją prie karties, ir įvyko, jei gyvatė ką įgėlė, tai tas, pažvelgęs į žalvarinę gyvatę, išliko gyvas.'),
  (@b4, 21, 10, 'Ir Izraelio vaikai išvyko ir stovyklavo Obote.'),
  (@b4, 21, 11, 'Ir jie iškeliavo iš Oboto ir stovyklavo Ije-Abarime, dykumoje, esančioje prieš Moabą, saulėtekio link.'),
  (@b4, 21, 12, 'Iš ten pasitraukę, jie stovyklavo Zaredo slėnyje.'),
  (@b4, 21, 13, 'Iš ten pasitraukę, jie stovyklavo anapus Arnono, kuris yra dykumoje, išeinančioje iš amoritų ribų; nes Arnonas yra Moabo riba tarp Moabo ir amoritų.'),
  (@b4, 21, 14, 'Todėl VIEŠPATIES karų knygoje sakoma: „Ką jis padarė Raudonojoje jūroje ir Arnono upeliuose,'),
  (@b4, 21, 15, 'ir srovėje upelių, kurie teka žemyn į Aro buveinę ir prisišlieja prie Moabo ribos“.'),
  (@b4, 21, 16, 'Ir iš ten jie vyko į Beerą; tai tas šulinys, apie kurį VIEŠPATS kalbėjo Mozei: „Surink tautą, o aš jiems duosiu vandens“.'),
  (@b4, 21, 17, 'Tada Izraelis giedojo šitą giesmę: „Patvink, o šuliny; giedokite jam;'),
  (@b4, 21, 18, 'kunigaikščiai iškasė šulinį, jį iškasė tautos kilmingieji savo lazdomis, įstatymleidžio nurodymu“. Ir iš dykumos jie ėjo į Mataną;'),
  (@b4, 21, 19, 'o iš Matano į Nahalielį; o iš Nahalielio į Bamotą;'),
  (@b4, 21, 20, 'o iš Bamoto, esančio slėnyje, Moabo šalyje, į Pisgos viršūnę, kuri žvelgia link Ješimono.'),
  (@b4, 21, 21, 'Ir Izraelis siuntė pasiuntinius pas amoritų karalių Sihoną, sakydamas:'),
  (@b4, 21, 22, '„Leisk man pereiti per tavo šalį; mes nesuksime nei į laukus, nei į vynuogynus; negersime iš šulinio vandenų; bet eisime karaliaus vieškeliu, kol būsime perėję tavo ribas“.'),
  (@b4, 21, 23, 'O Sihonas neleido Izraeliui pereiti per savo ribas; bet Sihonas surinko visą savo tautą ir išėjo prieš Izraelį į dykumą; ir jis atvyko į Jahacą ir kovojo prieš Izraelį.'),
  (@b4, 21, 24, 'O Izraelis jį sumušė kalavijo ašmenimis ir pasisavino jo šalį nuo Arnono iki Jaboko, iki Amono vaikų; nes Amono vaikų riba buvo stipri.'),
  (@b4, 21, 25, 'Ir Izraelis paėmė visus šituos miestus; ir Izraelis apsigyveno visuose amoritų miestuose, Hešbone ir visuose jo kaimuose.'),
  (@b4, 21, 26, 'Nes Hešbonas buvo miestas amoritų karaliaus Sihono, kuris buvo kariavęs prieš buvusį Moabo karalių ir paėmęs iš jo rankos visą jo šalį iki Arnono.'),
  (@b4, 21, 27, 'Todėl patarlėmis kalbantys sako: „Ateikite į Hešboną, tebūna pastatytas ir paruoštas Sihono miestas;'),
  (@b4, 21, 28, 'nes ugnis yra išėjusi iš Hešbono, liepsna iš Sihono miesto; ji prarijo Moabo Arą, Arnono aukštumų viešpačius.'),
  (@b4, 21, 29, 'Vargas tau, Moabai! Tu esi pražuvusi, o Kemošo tauta; jis atidavė savo pabėgusius sūnus ir savo dukteris į nelaisvę amoritų karaliui Sihonui.'),
  (@b4, 21, 30, 'Mes juos apšaudėme; Hešbonas yra pražuvęs iki Dibono, ir mes juos nuniokojome iki Nofacho, kuris siekia iki Medebos“.'),
  (@b4, 21, 31, 'Taip Izraelis gyveno amoritų šalyje.'),
  (@b4, 21, 32, 'Ir Mozė pasiuntė išžvalgyti Jazerį, ir jie paėmė jo kaimus ir išvarė ten esančius amoritus.'),
  (@b4, 21, 33, 'Ir jie pasuko ir ėjo aukštyn Bašano keliu; o Bašano karalius Ogas išėjo prieš juos, jis ir visa jo tauta į mūšį Edrėjuje.'),
  (@b4, 21, 34, 'Ir VIEŠPATS tarė Mozei: „Nebijok jo; nes atidaviau į tavo ranką jį ir visą jo tautą bei jo šalį; ir tu jam padaryk, kaip padarei amoritų karaliui Sihonui, kuris gyveno Hešbone“.'),
  (@b4, 21, 35, 'Taigi jie sumušė jį, jo sūnus ir visą jo tautą, kol jam nebeliko nei vieno gyvo; ir jie pasisavino jo šalį.'),
  (@b4, 22, 1, 'Ir Izraelio vaikai išvyko ir stovyklavo Moabo lygumose šiapus Jordano prie Jericho.'),
  (@b4, 22, 2, 'Ir Ciporo sūnus Balakas matė visa, ką Izraelis buvo padaręs amoritams.'),
  (@b4, 22, 3, 'Ir Moabas labai bijojo tos tautos, nes jų buvo daug; ir Moabą apėmė sielvartas dėl Izraelio vaikų.'),
  (@b4, 22, 4, 'Ir Moabas tarė Midjano vyresniesiems: „Dabar šitas pulkas sulaižys visa, kas yra aplink mus, kaip jautis sulaižo lauko žolę“. O Ciporo sūnus Balakas tuo metu buvo moabiečių karalius.'),
  (@b4, 22, 5, 'Todėl jis siuntė pasiuntinius pas Beoro sūnų Balaamą į Petorą, esantį prie jo tautos vaikų šalies upės, jo pasikviesti, sakydamas: „Štai tauta, išėjus iš Egipto; štai jie apdengė žemės paviršių ir apsistojo priešais mane;'),
  (@b4, 22, 6, 'taigi dabar ateik, meldžiu tave, prakeik man šitą tautą; nes man jie yra per galingi; gal nugalėsiu, kad juos sumuštume, ir kad juos išvaryčiau iš šalies; nes žinau, kad tas, kurį tu laimini, yra palaimintas, o tas, kurį prakeiki, yra prakeiktas“.'),
  (@b4, 22, 7, 'Ir Moabo vyresnieji ir Midjano vyresnieji išvyko su būrimo užmokesčiu savo rankoje; ir atėję pas Balaamą kalbėjo jam Balako žodžius.'),
  (@b4, 22, 8, 'O jis jiems tarė: „Nakvokite čia šiąnakt, ir aš jums parnešiu atsakymą, kaip man VIEŠPATS kalbės“; ir Moabo kunigaikščiai pasiliko pas Balaamą.'),
  (@b4, 22, 9, 'Ir Dievas atėjo pas Balaamą ir tarė: „Kas yra šitie vyrai pas tave?“'),
  (@b4, 22, 10, 'Ir Balaamas tarė Dievui: „Ciporo sūnus Balakas, Moabo karalius, atsiuntė pas mane, sakydamas:'),
  (@b4, 22, 11, '‘Štai tauta, išėjusi iš Egipto, kuri apdengė žemės paviršių; dabar ateik, prakeik man juos; gal aš pajėgsiu juos nugalėti ir išvaryti’“.'),
  (@b4, 22, 12, 'Ir Dievas tarė Balaamui: „Neik su jais; neprakeik tos tautos, nes jie yra palaiminti“.'),
  (@b4, 22, 13, 'Ir Balaamas, ryte atsikėlęs, tarė Balako kunigaikščiams: „Eikite į savo šalį; nes VIEŠPATS atsisakė leisti man vykti su jumis“.'),
  (@b4, 22, 14, 'Ir Moabo kunigaikščiai pakilo ir nuėjo pas Balaką ir tarė: „Balaamas atsisakė ateiti su mumis“.'),
  (@b4, 22, 15, 'Ir Balakas dar kartą siuntė daugiau kunigaikščių ir garbingesnių už anuos.'),
  (@b4, 22, 16, 'Ir atvykę pas Balaamą, jie jam tarė: „Taip sako Ciporo sūnus Balakas: ‘Meldžiu tave, niekas tenetrukdo tavęs ateiti pas mane;'),
  (@b4, 22, 17, 'nes aš tave paaukštinsiu labai didžia garbe ir, ką tik man sakysi, aš padarysiu; taigi ateik, meldžiu tave, prakeik man šitą tautą“.'),
  (@b4, 22, 18, 'Ir Balaamas atsakydamas tarė Balako tarnams: „Jei Balakas man duotų savo namus pilnus sidabro ir aukso, aš negaliu peržengti VIEŠPATIES, mano Dievo, žodžio, kad daryčiau mažiau ar daugiau.'),
  (@b4, 22, 19, 'Todėl dabar, meldžiu jus, taip pat pasilikite čia šiąnakt, kad sužinočiau, ką dar VIEŠPATS man pasakys“.'),
  (@b4, 22, 20, 'Ir atėjo Dievas naktį pas Balaamą ir jam tarė: „Jei šitie vyrai ateis tavęs pakviesti, kelkis ir eik su jais; tačiau vykdyk žodį, kurį aš tau pasakysiu“.'),
  (@b4, 22, 21, 'Ir Balaamas ryte atsikėlęs pabalnojo savo asilą ir ėjo su Moabo kunigaikščiais.'),
  (@b4, 22, 22, 'Ir Dievo pyktis užsidegė dėl to, kad jis ėjo; ir VIEŠPATIES angelas atsistojo ant kelio jam pasipriešinti. Na, o jis jojo ant savo asilės, o su juo buvo du jo tarnai.'),
  (@b4, 22, 23, 'O asilė pamatė VIEŠPATIES angelą, stovintį ant kelio, ir jo rankoje ištrauktą jo kalaviją; ir asilė pasuko iš kelio ir ėjo ant lauko; ir Balaamas mušė asilę, kad ją pasuktų į kelią.'),
  (@b4, 22, 24, 'Bet VIEŠPATIES angelas atsistojo ant vynuogynų tako, vienoje pusėje esant sienai ir kitoje pusėje esant sienai.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b4, 22, 25, 'Ir asilė, pamačiusi VIEŠPATIES angelą, spraudėsi sienos link ir prispaudė prie sienos Balaamo koją; ir jis vėl ją mušė.'),
  (@b4, 22, 26, 'Ir VIEŠPATIES angelas paėjo toliau ir atsistojo siauroje vietoje, kur nebuvo kelio pasukti nei į dešinę, nei į kairę.'),
  (@b4, 22, 27, 'Ir asilė, pamačiusi VIEŠPATIES angelą, griuvo po Balaamu; ir užsidegė Balaamo pyktis, ir jis mušė asilę lazda.'),
  (@b4, 22, 28, 'Ir VIEŠPATS atvėrė asilės nasrus, ir ji tarė Balaamui: „Ką tau padariau, kad šituos tris kartus mane mušei?“'),
  (@b4, 22, 29, 'Ir Balaamas tarė asilei: „Kadangi tyčiojaisi iš manęs; o kad turėčiau rankoje kalaviją, nes dabar tave užmuščiau“.'),
  (@b4, 22, 30, 'O asilė tarė Balaamui: „Argi aš ne tavo asilė, ant kurios tu jodavai nuo to laiko, kai esu tavo iki šios dienos? Ar buvau kada įpratusi tau taip daryti?“ Ir jis tarė: „Ne“.'),
  (@b4, 22, 31, 'Tada VIEŠPATS atvėrė Balaamui akis, ir jis pamatė VIEŠPATIES angelą, atsistojusį kelyje, ir jo rankoje ištrauktą jo kalaviją; ir jis nulenkė savo galvą ir krito veidu į žemę.'),
  (@b4, 22, 32, 'Ir VIEŠPATIES angelas jam tarė: „Kodėl šiuos tris kartus mušei savo asilę? Štai aš išėjau tau pasipriešinti, nes tavo kelias mano akivaizdoje yra priešgynus;'),
  (@b4, 22, 33, 'ir asilė mane matė ir šituos tris kartus pasisuko nuo manęs; jei ji nebūtų pasisukusi nuo manęs, tikrai jau dabar būčiau tave nužudęs, o ją palaikęs gyvą“.'),
  (@b4, 22, 34, 'Ir Balaamas tarė VIEŠPATIES angelui: „Aš nusidėjau; nes nežinojau, kad tu stovėjai prieš mane ant kelio; todėl dabar, jei tau tai nepatinka, aš sugrįšiu“.'),
  (@b4, 22, 35, 'Ir VIEŠPATIES angelas tarė Balaamui: „Eik su tais vyrais, tačiau kalbėk tik tą žodį, kurį tau pasakysiu“. Taip Balaamas nuėjo su Balako kunigaikščiais.'),
  (@b4, 22, 36, 'Ir Balakas, išgirdęs, kad Balaamas atėjęs, išėjo jo pasitikti į Moabo miestą, esantį ribose Arnono, kuris yra prie tolimiausio krašto.'),
  (@b4, 22, 37, 'Ir Balakas tarė Balaamui: „Argi uoliai nesiunčiau pas tave tavęs pakviesti? Kodėl neatėjai pas mane? Argi iš tiesų negaliu tavęs paaukštinti garbe?“'),
  (@b4, 22, 38, 'Ir Balaamas tarė Balakui: „Štai aš atėjau pas tave; ar aš iš viso dabar galiu ką kalbėti? Žodį, kurį Dievas įdės man į burną, tai aš kalbėsiu“.'),
  (@b4, 22, 39, 'Ir Balaamas ėjo su Balaku, ir jie atėjo į Kirjat-Hucotą.'),
  (@b4, 22, 40, 'Ir Balakas atnašavo jaučių bei avių ir siuntė Balaamui ir su juo buvusiems kunigaikščiams.'),
  (@b4, 22, 41, 'Ir įvyko rytojaus dieną, kad Balakas paėmė Balaamą ir jį užvedė ant Baalo aukštumų, kad iš ten jis matytų tautos tolimiausią dalį.'),
  (@b4, 23, 1, 'Ir Balaamas tarė Balakui: „Pastatyk man čia septynis aukurus ir paruošk man čia septynis jaučius bei septynis avinus“.'),
  (@b4, 23, 2, 'Ir Balakas padarė, kaip Balaamas buvo sakęs; ir Balakas, ir Balaamas atnašavo po jautuką ir aviną ant kiekvieno aukuro.'),
  (@b4, 23, 3, 'Ir Balaamas tarė Balakui: „Atsistok prie savo deginamosios atnašos, o aš eisiu; gal VIEŠPATS ateis susitikti su manimi; ir ką jis man parodys, aš tau pranešiu“. Ir jis nuėjo į aukštumą.'),
  (@b4, 23, 4, 'Ir Dievas susitiko su Balaamu; ir jis jam tarė: „Paruošiau septynis aukurus ir paaukojau ant kiekvieno aukuro po jautuką ir aviną“.'),
  (@b4, 23, 5, 'Ir VIEŠPATS įdėjo žodį į Balaamo burną ir tarė: „Sugrįžk pas Balaką ir šitaip kalbėk“.'),
  (@b4, 23, 6, 'Ir jis sugrįžo pas jį, ir štai jis stovėjo prie savo deginamosios aukos, jis ir visi Moabo kunigaikščiai.'),
  (@b4, 23, 7, 'Ir jis ėmėsi savo palyginimo ir tarė: „Iš Aramo mane atvedė Balakas, Moabo karalius, iš rytų kalnų, sakydamas: ‘Ateik, prakeik man Jokūbą, ateik, mesk iššūkį Izraeliui.'),
  (@b4, 23, 8, 'Kaip aš prakeiksiu, kurio Dievas neprakeikė? Arba, kaip aš mesiu iššūkį tam, kuriam VIEŠPATS nemetė iššūkio?'),
  (@b4, 23, 9, 'Nes nuo uolų viršūnės jį matau ir nuo kalvų jį stebiu; štai ta tauta gyvens atskirai ir nebus priskirta tarp tautų.'),
  (@b4, 23, 10, 'Kas gali suskaičiuoti Jokūbo dulkes ir Izraelio ketvirtadalio skaičių? Temirsiu teisiųjų mirtimi, ir mano baigtis tebūna kaip jo!“'),
  (@b4, 23, 11, 'Ir Balakas tarė Balaamui: „Ką man padarei? Aš tave paėmiau, kad prakeiktum mano priešus, o štai tu juos be perstojo laiminai“.'),
  (@b4, 23, 12, 'Ir jis atsakydamas tarė: „Argi neturiu saugotis, kad kalbėčiau tai, ką VIEŠPATS deda man į burną?“'),
  (@b4, 23, 13, 'Ir Balakas jam tarė: „Ateik, meldžiu tave, su manimi į kitą vietą, iš kur juos pamatysi; tik kraštinę jų dalį pamatysi, o jų visų nepamatysi; ir prakeik juos man iš ten“.'),
  (@b4, 23, 14, 'Ir jis atvedė jį į Cofimo lauką, į Pisgos viršūnę, pastatė septynis aukurus ir atnašavo jautuką bei aviną ant kiekvieno aukuro.'),
  (@b4, 23, 15, 'Ir jis tarė Balakui: „Stovėk čia prie savo deginamosios atnašos, kol aš ten susitiksiu su VIEŠPAČIU“.'),
  (@b4, 23, 16, 'Ir VIEŠPATS susitiko su Balaamu, įdėjo žodį į jo burną ir tarė: „Sugrįžk pas Balaką ir šitaip kalbėk“.'),
  (@b4, 23, 17, 'Ir kai jis atėjo pas jį, štai jis stovėjo prie savo deginamosios atnašos, o Moabo kunigaikščiai su juo. Ir Balakas jam tarė: „Ką kalbėjo VIEŠPATS?“'),
  (@b4, 23, 18, 'Ir jis ėmėsi savo palyginimo ir tarė: „Kelkis, Balakai, ir klausykis; klausyk manęs, Ciporo sūnau;'),
  (@b4, 23, 19, 'Dievas ne žmogus, kad meluotų; nei žmogaus sūnus, kad apsigalvotų; ar jis pasakė, o to nepadarytų, ar jis kalbėjo, o neištesėtų?'),
  (@b4, 23, 20, 'Štai aš gavau įsakymą laiminti; jis yra palaiminęs; o aš negaliu to atšaukti.'),
  (@b4, 23, 21, 'Jis nepastebėjo neteisybės Jokūbe nei nematė iškrypimo Izraelyje; VIEŠPATS, jo Dievas, yra su juo, ir karaliaus šauksmas yra tarp jų.'),
  (@b4, 23, 22, 'Dievas išvedė juos iš Egipto; jis turi tarsi vienaragio stiprybę.'),
  (@b4, 23, 23, 'Tikrai nėra kerų prieš Jokūbą nei jokio būrimo prieš Izraelį; šituo laiku bus sakoma apie Jokūbą ir apie Izraelį: ‘Ką Dievas padarė!'),
  (@b4, 23, 24, 'Štai tauta atsikels kaip didis liūtas ir atsistos kaip jaunas liūtas; jis neatsiguls, kol nepriės grobio ir neprigers užmuštųjų kraujo“.'),
  (@b4, 23, 25, 'Ir Balakas tarė Balaamui: „Nei jų visiškai neprakeik, nei jų visiškai nepalaimink“.'),
  (@b4, 23, 26, 'Bet Balaamas atsakydamas tarė Balakui: „Argi aš tau nekalbėjau, sakydamas: ‘Visa, ką VIEŠPATS kalba, tai aš turiu daryti’?“'),
  (@b4, 23, 27, 'Ir Balakas tarė Balaamui: „Ateik, meldžiu tave, aš tave nuvesiu į kitą vietą; gal tai patiks Dievui, kad tu iš ten man juos prakeiktum“.'),
  (@b4, 23, 28, 'Ir Balakas atvedė Balaamą į Peoro viršūnę, žvelgiančią Ješimono link.'),
  (@b4, 23, 29, 'Ir Balaamas tarė Balakui: „Pastatyk man čia septynis aukurus ir paruošk man čia septynis jautukus bei septynis avinus“.'),
  (@b4, 23, 30, 'Ir Balakas padarė, kaip Balaamas buvo pasakęs, ir atnašavo jautuką ir aviną ant kiekvieno aukuro.'),
  (@b4, 24, 1, 'Ir Balaamas, matydamas, kad VIEŠPAČIUI patiko laiminti Izraelį, nėjo, kaip kitais kartais, ieškoti kerų, bet nukreipė savo veidą į dykumą.'),
  (@b4, 24, 2, 'Ir Balaamas pakėlė savo akis ir pamatė Izraelį, apsistojusį savo palapinėse pagal savo gentis; ir Dievo Dvasia atėjo ant jo.'),
  (@b4, 24, 3, 'Ir jis ėmėsi savo palyginimo ir tarė: „Beoro sūnus Balaamas pasakė, ir žmogus, kurio akys atvertos, pasakė;'),
  (@b4, 24, 4, 'pasakė tas, kuris girdėjo Dievo žodžius, kuris matė Visagalio regėjimą įpuolęs į transą, bet atidengtomis akimis:'),
  (@b4, 24, 5, '‘Kokios gražios tavo palapinės, o Jokūbai, ir tavo padangtės, o Izraeli!'),
  (@b4, 24, 6, 'Kaip slėniai jos nusitiesę, kaip sodai paupyje, kaip alavijų medžiai, kuriuos VIEŠPATS pasodino, kaip kedrai šalia vandenų.'),
  (@b4, 24, 7, 'Jis išlies vandenį iš savo kibirų, ir jo sėkla bus daugelyje vandenų, ir jo karalius bus aukštesnis už Agagą, ir jo karalystė bus išaukštinta.'),
  (@b4, 24, 8, 'Dievas jį išvedė iš Egipto; jis turi tarsi vienaragio stiprybę; jis suės tautas, savo priešes, sulaužys jų kaulus ir pervers juos savo strėlėmis.'),
  (@b4, 24, 9, 'Jis prigulė, jis atsigulė kaip liūtas ir kaip didis liūtas; kas jį pažadins? Palaimintas tas, kuris tave laimina, ir prakeiktas tas, kuris tave prakeikia’“.'),
  (@b4, 24, 10, 'Ir užsidegė Balako pyktis prieš Balaamą, ir jis suplojo rankomis; ir Balakas tarė Balaamui: „Mano priešų prakeikti tave pakviečiau, o štai tu šituos tris kartus juos be perstojo laiminai.'),
  (@b4, 24, 11, 'Todėl dabar bėk į savo vietą; maniau tave didžiai pagerbti; bet štai VIEŠPATS tave sulaikė nuo garbės“.'),
  (@b4, 24, 12, 'Ir Balaamas tarė Balakui: „Argi nekalbėjau ir tavo pasiuntiniams, kuriuos siuntei pas mane, sakydamas:'),
  (@b4, 24, 13, '‘Jei Balakas man duotų savo namus pilnus sidabro ir aukso, aš negaliu peržengti VIEŠPATIES įsakymo, kad daryčiau gera ar pikta savo noru; bet ką VIEŠPATS sako, tai aš kalbėsiu?'),
  (@b4, 24, 14, 'O dabar, štai einu pas savo tautą; todėl ateik, aš tau paskelbsiu, ką šita tauta padarys tavo tautai paskutinėmis dienomis“.'),
  (@b4, 24, 15, 'Ir jis ėmėsi savo palyginimo ir tarė: „Beoro sūnus Balaamas pasakė, ir žmogus, kurio akys atvertos, pasakė;'),
  (@b4, 24, 16, 'pasakė tas, kuris girdėjo Dievo žodžius ir pažino Aukščiausiojo pažinimą, kuris regėjo Visagalio regėjimą įpuolęs į transą, bet atvertomis akimis:'),
  (@b4, 24, 17, '‘Aš jį matysiu, bet ne dabar; aš į jį žiūrėsiu, bet ne arti; Žvaigždė išeis iš Jokūbo, ir Skeptras pakils iš Izraelio ir sutriuškins Moabo dalis, ir sunaikins visus Šeto vaikus.'),
  (@b4, 24, 18, 'Ir Edomas bus nuosavybė, taip pat Seyras bus nuosavybė jo priešams; ir Izraelis elgsis narsiai.'),
  (@b4, 24, 19, 'Iš Jokūbo ateis tas, kuris viešpataus ir išnaikins išlikusį iš miesto’“.'),
  (@b4, 24, 20, 'Ir pažiūrėjęs į Amaleką, jis ėmėsi savo palyginimo ir tarė: „Amalekas buvo pirmutinis iš tautų; bet jo galas bus, kad jis pražus amžiams“.'),
  (@b4, 24, 21, 'Ir pažiūrėjęs į kenitus, jis ėmėsi savo palyginimo ir tarė: „Tvirta tavo gyvenamoji vieta, ir krauni savo lizdą uoloje.'),
  (@b4, 24, 22, 'Tačiau kenitas bus suniokotas, kol Ašūras tave nusives į nelaisvę“.'),
  (@b4, 24, 23, 'Ir jis ėmėsi savo palyginimo ir tarė: „Ach, kas išliks gyvas, kai Dievas tai darys!?'),
  (@b4, 24, 24, 'Ir atplauks laivai iš Kitimo krantų ir kamuos Ašūrą bei kamuos Eberą, ir jis taip pat pražus amžiams“.'),
  (@b4, 24, 25, 'Ir Balaamas pakilo, nuėjo ir sugrįžo į savo vietą; taip pat Balakas nuėjo savo keliu.'),
  (@b4, 25, 1, 'Ir Izraelis apsistojo Šitime, ir tauta pradėjo paleistuvauti su Moabo dukterimis.'),
  (@b4, 25, 2, 'Ir jos kvietė tautą prie savo dievų aukų; o tauta valgė ir lenkėsi jų dievams.'),
  (@b4, 25, 3, 'Ir Izraelis prisijungė prie Baal-Peoro; ir VIEŠPATIES pyktis užsidegė prieš Izraelį.'),
  (@b4, 25, 4, 'Ir VIEŠPATS tarė Mozei: „Paimk visas tautos galvas ir juos pakark prieš saulę VIEŠPATIES akivaizdoje, kad įnirtingas VIEŠPATIES pyktis nusigręžtų nuo Izraelio“.'),
  (@b4, 25, 5, 'Ir Mozė tarė Izraelio teisėjams: „Kiekvienas nužudykite savo žmones, prisijungusius prie Baal-Peoro“.'),
  (@b4, 25, 6, 'Ir štai vienas iš Izraelio vaikų atėjo ir atvedė savo broliams midjanietę moterį, matant Mozei ir matant visam Izraelio vaikų susirinkimui, kurie verkė priešais susirinkimo padangtės duris.'),
  (@b4, 25, 7, 'Ir Finehasas, kunigo Aarono sūnaus Eleazaro sūnus, tai pamatęs, pakilo iš susirinkimo tarpo ir paėmė į savo ranką ietį;'),
  (@b4, 25, 8, 'ir jis įėjo paskui Izraelio vyrą į palapinę ir perdūrė juos abu, Izraelio vyrą ir moterį per jos pilvą. Taip rykštė buvo sulaikyta nuo Izraelio vaikų.'),
  (@b4, 25, 9, 'O mirusiųjų nuo rykštės buvo dvidešimt keturi tūkstančiai.'),
  (@b4, 25, 10, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 25, 11, '„Finehasas, kunigo Aarono sūnaus Eleazaro sūnus, nugręžė mano rūstybę nuo Izraelio vaikų, būdamas tarp jų uolus dėl manęs, kad aš nesunaikinau Izraelio vaikų savo pavydu.'),
  (@b4, 25, 12, 'Todėl sakyk: ‘Štai aš jam duodu savo taikos sandorą;'),
  (@b4, 25, 13, 'jis ir jo sėkla po jo turės amžinos kunigystės sandorą; kadangi jis buvo uolus dėl savo Dievo ir atliko sutaikinimą už Izraelio vaikus’“.'),
  (@b4, 25, 14, 'Na, o užmuštojo izraelito, kuris buvo užmuštas su midjaniete moterimi, vardas buvo Zimris, Saluvo sūnus, vyriausiųjų namų kunigaikštis simeonų tarpe.'),
  (@b4, 25, 15, 'O užmuštosios midjanietės moters vardas buvo Kozbė, duktė Cūro; jis buvo galva tautos ir vyriausių namų Midjane.'),
  (@b4, 25, 16, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 25, 17, '„Spauskite midjaniečius ir juos sumuškite;'),
  (@b4, 25, 18, 'nes jie jus spaudė savo klastomis, kuriomis jie suviliojo jus Peoro dalyku ir dalyku Kozbės, Midjano kunigaikščio dukters, jų sesers, kuri buvo užmušta dėl Peoro, rykštės dieną“.'),
  (@b4, 26, 1, 'Ir po rykštės įvyko, kad VIEŠPATS kalbėjo Mozei ir kunigo Aarono sūnui Eleazarui, sakydamas:'),
  (@b4, 26, 2, '„Susumuokite visą Izraelio vaikų susirinkimą, nuo dvidešimties metų ir vyresnius, jų tėvų namuose, visus pajėgius eiti į karą Izraelyje“.'),
  (@b4, 26, 3, 'Ir Mozė bei kunigas Eleazaras kalbėjo su jais Moabo lygumose prie Jordano šalia Jericho, sakydami:'),
  (@b4, 26, 4, 'Susumuokite tautą nuo dvidešimties metu ir vyresnius; kaip VIEŠPATS įsakė Mozei ir Izraelio vaikams, kurie išėjo iš Egipto šalies.'),
  (@b4, 26, 5, 'Rubenas, Izraelio vyriausias sūnus; Rubeno vaikai: Hanochas, iš kurio kilo hanochų šeima; iš Paluvo – paluvų šeima;'),
  (@b4, 26, 6, 'iš Hecrono – hecronų šeima; iš Karmio – karmių šeima.'),
  (@b4, 26, 7, 'Šitos yra rubenų šeimos; ir iš jų suskaičiuotųjų buvo keturiasdešimt trys tūkstančiai septyni šimtai trisdešimt.'),
  (@b4, 26, 8, 'O Paluvo sūnūs: Eliabas.'),
  (@b4, 26, 9, 'O Eliabo sūnūs: Nemuelis, Datanas ir Abiramas. Tai tie Datanas ir Abiramas, kurie buvo gerai žinomi susirinkime, kurie ginčijosi prieš Mozę ir prieš Aaroną Koracho draugijoje, jiems ginčijantis prieš VIEŠPATĮ;'),
  (@b4, 26, 10, 'ir žemė pravėrė savo burną ir prarijo juos kartu su Korachu, kai ta draugija numirė, ugniai prarijus du šimtus penkiasdešimt žmonių; ir jie tapo ženklu.'),
  (@b4, 26, 11, 'Tačiau Koracho vaikai nenumirė.'),
  (@b4, 26, 12, 'Simeono sūnūs pagal savo šeimas: iš Nemuelio – nemuelių šeima; iš Jamino – jaminų šeima; iš Jachino – jachinų šeima;'),
  (@b4, 26, 13, 'iš Zeracho – zerachų šeima; iš Šauliaus – šaulių šeima.'),
  (@b4, 26, 14, 'Šitos yra simeonų šeimos – dvidešimt du tūkstančiai du šimtai.'),
  (@b4, 26, 15, 'Gado vaikai pagal savo šeimas: iš Sefono – sefonų šeima; iš Hagio – hagių šeima; iš Šūnio – šūnių šeima;'),
  (@b4, 26, 16, 'iš Oznio – oznių šeima; iš Erio – erių šeima;'),
  (@b4, 26, 17, 'iš Arodo – arodų šeima; iš Arelio – arelių šeima.'),
  (@b4, 26, 18, 'Šitos yra Gado vaikų šeimos pagal jų suskaičiuotuosius – keturiasdešimt tūkstančių penki šimtai.'),
  (@b4, 26, 19, 'Judos sūnūs buvo Eras ir Onanas; o Eras ir Onanas mirė Kanaano šalyje.'),
  (@b4, 26, 20, 'O Judos sūnūs pagal savo šeimas buvo: iš Šelos – šelų šeima; iš Pereso – peresų šeima; iš Zeracho – zerachų šeima.'),
  (@b4, 26, 21, 'O Pereso sūnūs buvo: iš Hecrono – hecronų šeima; iš Hamulo – hamulų šeima.'),
  (@b4, 26, 22, 'Šitos yra Judos šeimos pagal jų suskaičiuotuosius – septyniasdešimt šeši tūkstančiai penki šimtai.'),
  (@b4, 26, 23, 'Iš Isacharo sūnų pagal savo šeimas: iš Tolos – tolų šeima; iš Pūvos – pūvų šeima;'),
  (@b4, 26, 24, 'iš Jašubo – jašubų šeima; iš Šimrono – šimronų šeima.'),
  (@b4, 26, 25, 'Šitos yra Isacharo šeimos pagal jų suskaičiuotuosius – šešiasdešimt keturi tūkstančiai trys šimtai.'),
  (@b4, 26, 26, 'Iš Zebulono sūnų pagal savo šeimas: iš Seredo – seredų šeima; iš Elono – elonų šeima; iš Jachleelio – jachleelių šeima.'),
  (@b4, 26, 27, 'Šitos yra zebulonų šeimos pagal jų suskaičiuotuosius – šešiasdešimt tūkstančių penki šimtai.'),
  (@b4, 26, 28, 'Juozapo sūnūs pagal savo šeimas buvo: Manasas ir Efraimas.'),
  (@b4, 26, 29, 'Iš Manaso sūnų: iš Machyro – machyrų šeima; o Machyras pagimdė Gileadą; iš Gileado kilo gileadų šeima.'),
  (@b4, 26, 30, 'Šitie yra Gileado sūnūs: iš Jezero – jezerų šeima; iš Heleko – helekų šeima;'),
  (@b4, 26, 31, 'o iš Asrielio – asrielių šeima; o iš Šechemo – šechemų šeima;'),
  (@b4, 26, 32, 'o iš Šemidos – šemidų šeima; o iš Hefero – heferų šeima.'),
  (@b4, 26, 33, 'O Hefero sūnus Celofechadas neturėjo sūnų, tik dukteris; ir Celofechado dukterų vardai buvo: Machla ir Noja, Hogla, Milka ir Tirca.'),
  (@b4, 26, 34, 'Šitos yra Manaso šeimos, ir jų suskaičiuotieji – penkiasdešimt du tūkstančiai septyni šimtai.'),
  (@b4, 26, 35, 'Šitie yra Efraimo sūnūs pagal savo šeimas: iš Šutelacho – šutelachų šeima; iš Bechero – becherų šeima; iš Tahano – tahanų šeima.'),
  (@b4, 26, 36, 'O šitie yra Šutelacho sūnūs: iš Erano – eranų šeima.'),
  (@b4, 26, 37, 'Šitos yra Efraimo sūnų šeimos pagal jų suskaičiuotuosius – trisdešimt du tūkstančiai penki šimtai. Šitie yra Juozapo sūnūs pagal savo šeimas.'),
  (@b4, 26, 38, 'Benjamino sūnūs pagal savo šeimas: iš Belos – belų šeima; iš Ašbelio – ašbelių šeima; iš Ahiramo – ahiramų šeima;'),
  (@b4, 26, 39, 'iš Šufamo – šufamų šeima; iš Hufamo – hufamų šeima.'),
  (@b4, 26, 40, 'O Belos sūnūs buvo Ardas ir Naamanas: iš Ardo – ardų šeima; o iš Naamano – naamanų šeima.'),
  (@b4, 26, 41, 'Šitie yra Benjamino sūnūs pagal savo šeimas; o jų suskaičiuotųjų buvo keturiasdešimt penki tūkstančiai šeši šimtai.'),
  (@b4, 26, 42, 'Šitie yra Dano sūnūs pagal savo šeimas: iš Šuhamo – šuhamų šeima. Šitos yra Dano šeimos pagal savo šeimas.'),
  (@b4, 26, 43, 'Visų šuhamų šeimų pagal jų suskaičiuotuosius buvo šešiasdešimt keturi tūkstančiai keturi šimtai.'),
  (@b4, 26, 44, 'Iš Ašero vaikų pagal savo šeimas: iš Imnos – imnų šeima; iš Išvio – išvių šeima; iš Berijos – berijų šeima.'),
  (@b4, 26, 45, 'Iš Berijos sūnų: iš Hebero – heberų šeima; iš Malkielio – malkielių šeima.'),
  (@b4, 26, 46, 'O Ašero duktės vardas buvo Sara.'),
  (@b4, 26, 47, 'Šitos yra Ašero sūnų šeimos pagal jų suskaičiuotuosius; kurių buvo penkiasdešimt trys tūkstančiai keturi šimtai.'),
  (@b4, 26, 48, 'Iš Naftalio sūnų pagal savo šeimas: iš Jachseelio – jachseelių šeima; iš Gunio – gunių šeima;'),
  (@b4, 26, 49, 'iš Jesero – jeserų šeima; iš Šilemo – šilemų šeima.'),
  (@b4, 26, 50, 'Šitos yra Naftalio šeimos pagal jų šeimas; ir jų suskaičiuotųjų buvo keturiasdešimt penki tūkstančiai keturi šimtai.'),
  (@b4, 26, 51, 'Šitie buvo Izraelio vaikų suskaičiuotieji: šeši šimtai vienas tūkstantis septyni šimtai trisdešimt.'),
  (@b4, 26, 52, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 26, 53, '„Šitiems bus padalinta šalis paveldėjimui pagal vardų skaičių.'),
  (@b4, 26, 54, 'Daugumai duosi didesnį paveldą, o mažumai duosi mažesnį paveldą; kiekvienam bus duodamas jo paveldas pagal jo suskaičiuotuosius.'),
  (@b4, 26, 55, 'Tačiau šalis bus padalinta burtu: pagal jų tėvų genčių vardus jie paveldės.'),
  (@b4, 26, 56, 'Burtu bus padalinta kiekvieno nuosavybė tarp daugumos ir mažumos“.'),
  (@b4, 26, 57, 'O šitie yra levitų suskaičiuotieji pagal savo šeimas: iš Geršono – geršonų šeima; iš Kehato – kehatų šeima; iš Merario – merarių šeima.'),
  (@b4, 26, 58, 'Šitos yra levitų šeimos: libnių šeima, hebronų šeima, machlių šeima, mušių šeima, korių šeima. O Kehatas pagimdė Amramą.'),
  (@b4, 26, 59, 'O Amramo žmonos vardas buvo Jochebeda, Levio duktė, kurią jos motina pagimdė Leviui Egipte; ir ji pagimdė Amramui Aaroną, Mozę ir jų seserį Mirjamą.'),
  (@b4, 26, 60, 'O Aaronui gimė Nadabas ir Abihuvas, Eleazaras ir Itamaras.'),
  (@b4, 26, 61, 'O Nadabas ir Abihuvas numirė, kai atnašavo svetimą ugnį VIEŠPATIES akivaizdoje.'),
  (@b4, 26, 62, 'Ir jų suskaičiuotųjų buvo dvidešimt trys tūkstančiai, visi vyriškos lyties, nuo mėnesio amžiaus ir vyresni; nes jie nebuvo suskaičiuoti tarp Izraelio vaikų, nes jiems nebuvo duotas paveldas tarp Izraelio vaikų.'),
  (@b4, 26, 63, 'Šitie yra suskaičiuotieji Mozės ir kunigo Eleazaro, kurie suskaičiavo Izraelio vaikus Moabo lygumose prie Jordano šalia Jericho.'),
  (@b4, 26, 64, 'Bet tarp jų nebuvo nei vieno iš Mozės ir kunigo Aarono suskaičiuotųjų, kai jie suskaičiavo Izraelio vaikus Sinajaus dykumoje.'),
  (@b4, 26, 65, 'Nes VIEŠPATS buvo pasakęs apie juos: „Jie tikrai mirs dykumoje“. Ir nei vieno iš jų nebeliko, išskyrus Jefunės sūnų Kalebą ir Nūno sūnų Jozuę.'),
  (@b4, 27, 1, 'Tada atėjo dukterys Celofechado, sūnaus Hefero, sūnaus Gileado, sūnaus Machyro, sūnaus Manaso, iš Juozapo sūnaus Manaso šeimų; o šitie yra jo dukterų vardai: Machla, Noja, Hogla, Milka ir Tirca.'),
  (@b4, 27, 2, 'Ir jos atsistojo Mozės akivaizdoje, kunigo Eleazaro akivaizdoje ir viso susirinkimo kunigaikščių akivaizdoje prie susirinkimo padangtės durų, sakydamos:'),
  (@b4, 27, 3, '„Mūsų tėvas mirė dykumoje ir jis nebuvo draugijoje tų, kurie buvo susibūrę prieš VIEŠPATĮ Koracho draugijoje; bet mirė savo paties nuodėmėje ir neturėjo sūnų.'),
  (@b4, 27, 4, 'Kodėl mūsų tėvo vardas turėtų išnykti iš jo šeimos tarpo dėl to, kad jis neturi sūnaus? Todėl duok mums nuosavybę tarp mūsų tėvo brolių“.'),
  (@b4, 27, 5, 'Ir Mozė atnešė jų reikalą VIEŠPATIES akivaizdon.'),
  (@b4, 27, 6, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 27, 7, '„Celofechado dukterys kalba teisingai; tikrai duok joms paveldo nuosavybę tarp jų tėvo brolių; ir padaryk, kad joms pereitų jų tėvo paveldas.'),
  (@b4, 27, 8, 'Ir Izraelio vaikams kalbėk, sakydamas: ‘Jei kas miršta neturėdamas sūnaus, tuomet padarykite, kad jo paveldas pereitų jo dukteriai.'),
  (@b4, 27, 9, 'O jei jis neturi dukters, tuomet duokite jo paveldą jo broliams.'),
  (@b4, 27, 10, 'O jei jis neturi brolių, tuomet duokite jo paveldą jo tėvo broliams.'),
  (@b4, 27, 11, 'O jei jo tėvas neturi brolių, tuomet duokite jo paveldą jo giminaičiui, kuris yra artimiausias iš jo šeimos, ir jis jį pasisavins; ir tai bus Izraelio vaikams teismo įstatas, kaip VIEŠPATS įsakė Mozei’“.'),
  (@b4, 27, 12, 'Ir VIEŠPATS tarė Mozei: „Užlipk į šitą Abarimo kalną ir apžiūrėk šalį, kurią daviau Izraelio vaikams.'),
  (@b4, 27, 13, 'Ir ją pamatęs, tu taip pat būsi surinktas prie savo tautos, kaip buvo surinktas tavo brolis Aaronas.'),
  (@b4, 27, 14, 'Nes jūs maištavote prieš mano įsakymą Cino dykumoje, susirinkimui vaidijantis, kad mane pašvęstumėte prie vandens jų akyse“; tai yra Meribos vanduo Kadeše, Cino dykumoje.'),
  (@b4, 27, 15, 'Ir Mozė kalbėjo VIEŠPAČIUI, sakydamas:'),
  (@b4, 27, 16, '„Tegul VIEŠPATS, visų kūnų dvasių Dievas, paskiria susirinkimui vadovauti vyrą,'),
  (@b4, 27, 17, 'kuris išeitų jų priešakyje ir kuris įeitų jų priešakyje, ir kuris juos išvestų, ir kuris juos įvestų; kad VIEŠPATIES susirinkimas nebūtų kaip avys, neturinčios piemens“.'),
  (@b4, 27, 18, 'Ir VIEŠPATS tarė Mozei: „Pasiimk Nūno sūnų Jozuę, vyrą, kuriame yra dvasia, uždėk ant jo savo ranką;'),
  (@b4, 27, 19, 'ir pastatyk jį kunigo Eleazaro akivaizdoje ir viso susirinkimo akivaizdoje; ir įpareigok jį jiems matant.'),
  (@b4, 27, 20, 'Ir uždėk ant jo dalį savo garbės, kad visas Izraelio vaikų susirinkimas būtų paklusnus.'),
  (@b4, 27, 21, 'Ir jis stovės priešakyje kunigo Eleazaro, kuris prašys jam patarimo pagal Urimo teismą VIEŠPATIES akivaizdoje; pagal jo žodį jie išeis ir pagal jo žodį jie įeis, tiek jis, tiek visi Izraelio vaikai su juo, būtent visas susirinkimas“.'),
  (@b4, 27, 22, 'Ir Mozė padarė, kaip VIEŠPATS jam įsakė; ir jis ėmė Jozuę ir pastatė jį kunigo Eleazaro akivaizdon ir viso susirinkimo akivaizdon;'),
  (@b4, 27, 23, 'ir jis uždėjo ant jo savo rankas ir jį įpareigojo, kaip VIEŠPATS įsakė per Mozės ranką.'),
  (@b4, 28, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 28, 2, '„Įsakyk Izraelio vaikams ir jiems sakyk: ‘Mano atnašos ir mano duonos mano ugnies aukoms, kaip gardaus kvapo man, laikysitės, kad man atnašautumėte jų skirtu laiku’.'),
  (@b4, 28, 3, 'Ir jiems sakyk: ‘Ši yra ugnies atnaša, kurią atnašausite VIEŠPAČIUI: kasdien du pirmųjų metų avinėlius be dėmės kaip nuolatinę deginamąją atnašą.'),
  (@b4, 28, 4, 'Vieną avinėlį atnašauk ryte, o kitą avinėlį atnašauk vakare;'),
  (@b4, 28, 5, 'ir dešimtadalį efos miltų, kaip maisto atnašą, sumaišytų su ketvirtadaliu hino sugrūsto aliejaus.'),
  (@b4, 28, 6, 'Tai nuolatinė deginamoji atnaša, kuri buvo nustatyta Sinajaus kalne, gardžiam kvapui, ugnies auka VIEŠPAČIUI.'),
  (@b4, 28, 7, 'O jos geriamoji atnaša bus ketvirtadalis hino vienam avinėliui; padaryk, kad šventojoje vietoje išlietų stipraus vyno VIEŠPAČIUI kaip geriamąją atnašą.'),
  (@b4, 28, 8, 'O kitą avinėlį atnašauk vakare; kaip rytmečio maisto atnašą, ir kaip jo geriamąją atnašą ją atnašauk, ugnies auką, gardų kvapą VIEŠPAČIUI.'),
  (@b4, 28, 9, 'O sabato dieną – du pirmųjų metų avinėlius be dėmės ir maisto atnašai du dešimtadalius miltų, sumaišytų su aliejumi, ir jos geriamąją atnašą;'),
  (@b4, 28, 10, 'šita yra kiekvieno sabato deginamoji atnaša, neskaitant nuolatinės deginamosios atnašos ir jos geriamosios atnašos.'),
  (@b4, 28, 11, 'O jūsų mėnesių pradžiose atnašaukite deginamąją atnašą VIEŠPAČIUI: du jauniklius jautukus, vieną aviną, septynis pirmųjų metų avinėlius be dėmės;'),
  (@b4, 28, 12, 'ir tris dešimtadalius miltų, sumaišytų su aliejumi, kaip maisto atnašą vienam jautukui; ir du dešimtadalius miltų, sumaišytų su aliejumi, kaip maisto atnašą vienam avinui;'),
  (@b4, 28, 13, 'po dešimtadalį miltų, sumaišytų su aliejumi, kaip maisto atnašą vienam avinėliui; kaip deginamąją gardaus kvapo atnašą, ugnies auką VIEŠPAČIUI.'),
  (@b4, 28, 14, 'O jų geriamosios atnašos bus pusė hino vyno jautukui, trečdalis hino avinui ir ketvirtadalis hino avinėliui; ši yra kiekvieno mėnesio deginamoji atnaša per metų mėnesius.'),
  (@b4, 28, 15, 'Ir kaip nuodėmės atnaša VIEŠPAČIUI bus atnašaujamas vienas ožiukas, neskaitant nuolatinės deginamosios atnašos, ir jo geriamoji atnaša.'),
  (@b4, 28, 16, 'O pirmojo mėnesio keturioliktąją dieną yra VIEŠPATIES Apėjimas.'),
  (@b4, 28, 17, 'O penkioliktą to mėnesio dieną yra šventė; septynias dienas bus valgoma nerauginta duona.'),
  (@b4, 28, 18, 'Pirmąją dieną bus šventas sušaukimas; nedirbkite joje jokio tarnavimo darbo;'),
  (@b4, 28, 19, 'bet atnašaukite ugnies auką, kaip deginamąją atnašą VIEŠPAČIUI: du jauniklius jautukus, vieną aviną ir septynis pirmųjų metų avinėlius – jie bus jums be trūkumų;'),
  (@b4, 28, 20, 'o jų maisto atnaša bus iš miltų, sumaišytų su aliejumi: tris dešimtadalius atnašaukite jautukui, o du dešimtadalius avinui;'),
  (@b4, 28, 21, 'po dešimtadalį atnašauk kiekvienam avinėliui per visus septynis avinėlius;'),
  (@b4, 28, 22, 'ir vieną nuodėmės atnašos ožį, sutaikinimui už jus atlikti.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b4, 28, 23, 'Šituos atnašaukite neskaitant deginamosios atnašos ryte, kuri yra nuolatinei deginamajai atnašai.'),
  (@b4, 28, 24, 'Tokiu būdu kasdien atnašaukite per septynias dienas ugnies aukos maistą, kaip gardų kvapą VIEŠPAČIUI; tai bus atnašaujama neskaitant nuolatinės deginamosios atnašos ir jos geriamosios atnašos.'),
  (@b4, 28, 25, 'O septintąją dieną turėsite šventą sušaukimą; nedirbkite jokio tarnavimo darbo.'),
  (@b4, 28, 26, 'Taip pat Pirmavaisių dieną, kai atnešate naują maisto atnašą VIEŠPAČIUI, jūsų savaitėms pasibaigus, turėsite šventą sušaukimą; nedirbkite jokio tarnavimo darbo;'),
  (@b4, 28, 27, 'bet atnašaukite deginamąją atnašą kaip gardų kvapą VIEŠPAČIUI: du jauniklius jautukus, vieną aviną, septynis pirmųjų metų avinėlius;'),
  (@b4, 28, 28, 'ir jų maisto atnašą iš miltų, sumaišytų su aliejumi, tris dešimtadalius vienam jautukui, du dešimtadalius vienam avinui,'),
  (@b4, 28, 29, 'po dešimtadalį vienam avinėliui, per visus septynis avinėlius;'),
  (@b4, 28, 30, 'ir vieną ožiuką, sutaikinimui už jus atlikti.'),
  (@b4, 28, 31, 'atnašaukite juos neskaitant nuolatinės deginamosios atnašos ir jos maisto atnašos (jie bus jums be trūkumų), ir jų geriamąsias atnašas.'),
  (@b4, 29, 1, 'O septintąjį mėnesį, to mėnesio pirmąją dieną, turėsite šventą sušaukimą; nedirbkite jokio tarnavimo darbo; tai jums yra trimitavimo diena.'),
  (@b4, 29, 2, 'Ir atnašaukite deginamąją atnašą kaip gardų kvapą VIEŠPAČIUI: vieną jauniklį jautuką, vieną aviną ir septynis pirmųjų metų avinėlius be trūkumų;'),
  (@b4, 29, 3, 'o jų maisto atnaša bus iš miltų, sumaišytų su aliejumi, trys dešimtadaliai jautukui, o du dešimtadaliai avinui,'),
  (@b4, 29, 4, 'ir vienas dešimtadalis vienam avinėliui per visus septynis avinėlius;'),
  (@b4, 29, 5, 'ir vieną ožiuką nuodėmės atnašai, sutaikinimui už jus atlikti;'),
  (@b4, 29, 6, 'neskaitant mėnesio deginamosios atnašos su jos maisto atnaša ir kasdienės deginamosios atnašos su jos maisto atnaša, ir jų geriamųjų atnašų, pagal jų būdą, kaip gardų kvapą, ugnies auką VIEŠPAČIUI.'),
  (@b4, 29, 7, 'O šito, septintojo, mėnesio dešimtąją dieną turėsite šventą sušaukimą; ir varginsite savo sielas; ir nedirbsite joje jokio darbo;'),
  (@b4, 29, 8, 'bet atnašaukite VIEŠPAČIUI deginamąją atnašą, kaip gardų kvapą: vieną jauniklį jautuką, vieną aviną ir septynis pirmųjų metų avinėlius; jie bus jums be trūkumų;'),
  (@b4, 29, 9, 'o jų maisto atnaša bus iš miltų, sumaišytų su aliejumi, trys dešimtadaliai jautukui, o du dešimtadaliai vienam avinui,'),
  (@b4, 29, 10, 'po dešimtadalį vienam avinėliui per visus septynis avinėlius;'),
  (@b4, 29, 11, 'vieną ožiuką nuodėmės atnašai; neskaitant sutaikinimo nuodėmės atnašos ir nuolatinės deginamosios atnašos su jos maisto atnaša, ir jų geriamųjų atnašų.'),
  (@b4, 29, 12, 'O septintojo mėnesio penkioliktą dieną turėsite šventą sušaukimą; nedirbkite jokio tarnavimo darbo, o švęskite šventę VIEŠPAČIUI septynias dienas;'),
  (@b4, 29, 13, 'ir atnašaukite deginamąją atnašą, ugnies auką, gardų kvapą VIEŠPAČIUI: trylika jauniklių jautukų, du avinus ir keturiolika pirmų metų avinėlių; jie bus be trūkumų;'),
  (@b4, 29, 14, 'o jų maisto atnaša bus iš miltų, sumaišytų su aliejumi, trys dešimtadaliai kiekvienam jautukui iš trylikos jautukų, du dešimtadaliai kiekvienam avinui iš abiejų avinų,'),
  (@b4, 29, 15, 'ir po dešimtadalį kiekvienam avinėliui iš keturiolikos avinėlių;'),
  (@b4, 29, 16, 'ir vieną ožiuką kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos, jos maisto atnašos bei jos geriamosios atnašos.'),
  (@b4, 29, 17, 'O antrąją dieną atnašaukite dvylika jauniklių jautukų, du avinus, keturiolika pirmų metų avinėlių be dėmės;'),
  (@b4, 29, 18, 'o jų maisto atnaša ir jų geriamosios atnašos jautukams, avinams ir avinėliams bus atsižvelgiant į jų skaičių, pagal tą būdą;'),
  (@b4, 29, 19, 'ir vieną ožiuką kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos ir jos maisto atnašos bei jų geriamųjų atnašų.'),
  (@b4, 29, 20, 'O trečiąją dieną – vienuolika jautukų, du avinus, keturiolika pirmų metų avinėlių be trūkumų;'),
  (@b4, 29, 21, 'o jų maisto atnaša bei jų geriamosios atnašos jautukams, avinams ir avinėliams bus pagal jų skaičių, pagal tą būdą;'),
  (@b4, 29, 22, 'ir vieną ožį kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos su jos maisto atnaša bei jos geriamąja atnaša.'),
  (@b4, 29, 23, 'O ketvirtąją dieną – dešimt jautukų, du avinus ir keturiolika pirmų metų avinėlių be trūkumų;'),
  (@b4, 29, 24, 'jų maisto atnaša bei jų geriamosios atnašos jautukams, avinams ir avinėliams bus pagal jų skaičių, pagal tą būdą;'),
  (@b4, 29, 25, 'ir vieną ožiuką kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos, jos maisto atnašos bei jos geriamosios atnašos.'),
  (@b4, 29, 26, 'O penktąją dieną – devynis jautukus, du avinus ir keturiolika pirmų metų avinėlių be dėmės;'),
  (@b4, 29, 27, 'o jų maisto atnaša bei jų geriamosios atnašos jautukams, avinams ir avinėliams bus pagal jų skaičių, pagal tą būdą;'),
  (@b4, 29, 28, 'ir vieną ožį kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos su jos maisto atnaša bei jos geriamąja atnaša.'),
  (@b4, 29, 29, 'O šeštąją dieną – aštuonis jautukus, du avinus ir keturiolika pirmų metų avinėlių be trūkumų;'),
  (@b4, 29, 30, 'o jų maisto atnaša bei jų geriamosios atnašos jautukams, avinams ir avinėliams, bus pagal jų skaičių, pagal tą būdą;'),
  (@b4, 29, 31, 'ir vieną ožį kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos, jos maisto atnašos bei jos geriamosios atnašos.'),
  (@b4, 29, 32, 'O septintąją dieną – septynis jautukus, du avinus ir keturiolika pirmų metų avinėlių be trūkumų;'),
  (@b4, 29, 33, 'o jų maisto atnaša bei jų geriamosios atnašos jautukams, avinams ir avinėliams, bus pagal jų skaičių, pagal tą būdą;'),
  (@b4, 29, 34, 'ir vieną ožį kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos, jos maisto atnašos bei jos geriamosios atnašos.'),
  (@b4, 29, 35, 'Aštuntąją dieną turėsite iškilmingą susirinkimą; nedirbkite joje jokio tarnavimo darbo;'),
  (@b4, 29, 36, 'bet atnašaukite deginamąją atnašą, ugnies auką, gardų kvapą VIEŠPAČIUI: vieną jautuką, vieną aviną, septynis pirmų metų avinėlius be trūkumų;'),
  (@b4, 29, 37, 'jų maisto atnaša bei jų geriamosios atnašos jautukui, avinui ir avinėliams bus pagal jų skaičių, pagal tą būdą;'),
  (@b4, 29, 38, 'ir vieną ožį kaip nuodėmės atnašą; neskaitant nuolatinės deginamosios atnašos su jos maisto atnaša bei jos geriamąja atnaša.'),
  (@b4, 29, 39, 'Šituos dalykus darykite VIEŠPAČIUI savo paskirtose šventėse, neskaitant jūsų įžadų ir jūsų laisvos valios atnašų jūsų deginamosioms atnašoms, jūsų maisto atnašoms, jūsų geriamosioms atnašoms bei jūsų taikos atnašoms’“.'),
  (@b4, 29, 40, 'Ir Mozė pasakė Izraelio vaikams pagal visa tai, ką VIEŠPATS įsakė Mozei.'),
  (@b4, 30, 1, 'Ir Mozė kalbėjo genčių galvoms dėl Izraelio vaikų, sakydamas: „Štai dalykas, kurį VIEŠPATS yra įsakęs:'),
  (@b4, 30, 2, 'Jei vyras duoda įžadą VIEŠPAČIUI ar prisiekia priesaika, surišdamas savo sielą saitu; jis tenesulaužo savo žodžio, jis tedaro pagal visa tai, kas išėjo iš jo burnos.'),
  (@b4, 30, 3, 'Jei ir moteris duoda įžadą VIEŠPAČIUI ir suriša save saitu, būdama savo tėvo namuose savo jaunystėje;'),
  (@b4, 30, 4, 'o jos tėvas išgirsta jos įžadą ir jos saitą, kuriuo ji surišo savo sielą, ir jos tėvas tyli prieš ją; tuomet visi jos įžadai galioja, ir kiekvienas saitas, kuriuo ji yra surišusi savo sielą, galios.'),
  (@b4, 30, 5, 'Bet jei jos tėvas jai uždraudžia tą dieną, kai jis išgirsta; nei vienas iš jos įžadų ar iš jos saitų, kuriais ji yra surišusi savo sielą, negalios; o VIEŠPATS jai atleis, nes jos tėvas jai uždraudė.'),
  (@b4, 30, 6, 'O jeigu ji tikrai turėjo vyrą, kai ji pasižadėjo ar ištarė priesaiką iš savo lūpų, kuria ji surišo savo sielą;'),
  (@b4, 30, 7, 'o jos vyras tai išgirdo ir tylėjo prieš ją tą dieną, kai jis tai išgirdo; tuomet jos įžadai galios, ir jos saitai, kuriais ji surišo savo sielą, galios.'),
  (@b4, 30, 8, 'Bet jei jos vyras tą dieną, kai tai išgirdo, jai uždraudė; tuomet jis padarys negaliojančiu jos įžadą, kurį ji davė, ir tai, ką ji ištarė savo lūpomis, kuo ji surišo savo sielą; o VIEŠPATS jai atleis.'),
  (@b4, 30, 9, 'Bet kiekvienas našlės ir išsiskyrusios įžadas, kuo jos surišo savo sielas, joms galios.'),
  (@b4, 30, 10, 'O jei ji savo vyro namuose davė įžadą ar surišo saitu savo sielą su priesaika;'),
  (@b4, 30, 11, 'ir jos vyras, tai išgirdo ir tylėjo prieš ją, ir jai neuždraudė; tuomet galios visi jos įžadai, ir kiekvienas saitas, kuriuo ji surišo savo sielą, galios.'),
  (@b4, 30, 12, 'Bet jei jos vyras, tą dieną kai juos išgirdo, visiškai juos padarė negaliojančiais; tuomet kas išėjo iš jos lūpų dėl jos įžadų ar dėl jos sielos surišimo, negalios; jos vyras padarė juos negaliojančiais; o VIEŠPATS jai atleis.'),
  (@b4, 30, 13, 'Kiekvieną įžadą ir kiekvieną surišančią priesaiką sielai varginti jos vyras gali įtvirtinti arba jos vyras gali tai padaryti negaliojančiu.'),
  (@b4, 30, 14, 'Bet jei jos vyras diena iš dienos prieš ją visiškai tyli; tuomet jis įtvirtina visus jos įžadus arba visus ant jos esančius saitus; jis juos patvirtina, nes jis prieš ją tylėjo tą dieną, kai jis juos išgirdo.'),
  (@b4, 30, 15, 'Bet jei jis visiškai padarys juos negaliojančiais po to, kai juos buvo girdėjęs; tuomet jis nešios jos neteisingumą“.'),
  (@b4, 30, 16, 'Šitie yra įstatai, kuriuos VIEŠPATS įsakė Mozei, tarp vyro ir jo žmonos, tarp tėvo ir jo dukters, dar esančios savo jaunystėje savo tėvo namuose.'),
  (@b4, 31, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 31, 2, '„Atkeršyk midjaniečiams už Izraelio vaikus; paskui tu būsi surinktas prie savo tautos“.'),
  (@b4, 31, 3, 'Ir Mozė kalbėjo tautai, sakydamas: „Apginkluokite kai kuriuos iš jūsų karui, ir jie teeina prieš midjaniečius ir teatkeršija Midjanui už VIEŠPATĮ.'),
  (@b4, 31, 4, 'Pasiųskite į karą iš kiekvienos genties po tūkstantį, iš visų Izraelio genčių“.'),
  (@b4, 31, 5, 'Taip buvo pateikta iš Izraelio tūkstančių po tūkstantį iš kiekvienos genties, dvylika tūkstančių apginkluotų karui.'),
  (@b4, 31, 6, 'Ir Mozė juos pasiuntė į karą po tūkstantį iš kiekvienos genties – juos ir kunigo Eleazaro sūnų Finehasą į karą su šventaisiais įrankiais ir trimitais savo rankose, kad pūstų.'),
  (@b4, 31, 7, 'Ir jie kariavo prieš midjaniečius, kaip VIEŠPATS įsakė Mozei; ir jie išžudė visus vyriškosios lyties.'),
  (@b4, 31, 8, 'Neskaitant kitų nužudytųjų, jie nužudė Midjano karalius; tai yra Evį, Rekemą, Cūrą, Hūrą ir Rebą – penkis Midjano karalius; taip pat jie nužudė kalaviju Beoro sūnų Balaamą.'),
  (@b4, 31, 9, 'Ir Izraelio vaikai paėmė į nelaisvę visas Midjano moteris ir jų mažylius ir pasigrobė visus jų galvijus, visas jų kaimenes ir visą jų turtą.'),
  (@b4, 31, 10, 'O visus jų miestus, kur jie gyveno, ir visas jų gražias pilis jie sudegino ugnimi.'),
  (@b4, 31, 11, 'Ir jie paėmė visą grobį ir visa, ką prisiplėšė, tiek iš žmonių tiek iš gyvulių.'),
  (@b4, 31, 12, 'Ir pas Mozę, kunigą Eleazarą ir pas Izraelio vaikų susirinkimą jie pargabeno belaisvius, grobį ir tai, ko prisiplėšė, į stovyklą Moabo lygumose, esančiose prie Jordano šalia Jericho.'),
  (@b4, 31, 13, 'O Mozė, kunigas Eleazaras ir visi susirinkimo kunigaikščiai išėjo jų pasitikti už stovyklos.'),
  (@b4, 31, 14, 'Ir Mozė buvo užsirūstinęs ant kariuomenės pareigūnų, tūkstančių vadų bei šimtų vadų, kurie parvyko iš mūšio.'),
  (@b4, 31, 15, 'Ir Mozė jiems tarė: „Ar palikote visas moteris gyvas?'),
  (@b4, 31, 16, 'Štai šitos padarė, kad Izraelio vaikai per Balaamo patarimą nusižengtų VIEŠPAČIUI Peoro dalyku, ir buvo rykštė VIEŠPATIES susirinkimo tarpe.'),
  (@b4, 31, 17, 'Todėl dabar nužudykite visus vyriškos lyties tarp mažylių ir nužudykite kiekvieną moterį, kuri pažino vyrą su juo suguldama.'),
  (@b4, 31, 18, 'Tačiau visus moteriškos lyties vaikus, kurie dar nėra pažinę vyro su juo sugulant, palikite sau gyvus.'),
  (@b4, 31, 19, 'Ir pasilikite septynias dienas už stovyklos; kas nužudėte kokį asmenį ir kas palietėte kokį nužudytą, apsivalykite jūs patys ir jūsų belaisviai trečiąją ir septintąją dieną.'),
  (@b4, 31, 20, 'Ir apsivalykite visus savo drabužius ir visa, kas padaryta iš odų, visus ožkų šerių dirbinius ir visus dalykus, padarytus iš medžio“.'),
  (@b4, 31, 21, 'Ir kunigas Eleazaras tarė karo vyrams, ėjusiems į mūšį: „Šitas yra įstatymo įsakas, kurį VIEŠPATS įsakė Mozei:'),
  (@b4, 31, 22, 'tik auksą, sidabrą, varį, geležį, alavą ir šviną,'),
  (@b4, 31, 23, 'kiekvieną daiktą, kuris gali išlikti ugnyje, perleiskite per ugnį, ir jis bus švarus; tačiau jis bus apvalytas atskyrimo vandeniu; o visa, kas neišlieka ugnyje, perleiskite per vandenį.'),
  (@b4, 31, 24, 'Ir septintąją dieną išplaukite savo drabužius, ir būsite švarūs, o paskui ateikite į stovyklą“.'),
  (@b4, 31, 25, 'Ir VIEŠPATS tarė Mozei, sakydamas:'),
  (@b4, 31, 26, '„Susumuok paimtą grobį tiek iš žmonių, tiek ir iš gyvulių – tu, kunigas Eleazaras ir susirinkimo vyriausi tėvai;'),
  (@b4, 31, 27, 'ir padalyk grobį į dvi dalis tarp tų, kurie prisiėmė kariauti, kurie išėjo į mūšį, ir tarp viso susirinkimo;'),
  (@b4, 31, 28, 'ir surink duoklę VIEŠPAČIUI iš karo vyrų, ėjusių į mūšį: iš penkių šimtų po vieną sielą tiek iš žmonių, tiek iš galvijų, tiek iš asilų, tiek ir iš avių;'),
  (@b4, 31, 29, 'iš pusės jų paimk tai ir duok kunigui Eleazarui kaip VIEŠPATIES iškeliamąją atnašą.'),
  (@b4, 31, 30, 'O iš pusės Izraelio vaikų paimk po vieną dalį iš penkiasdešimties, iš žmonių, iš galvijų, iš asilų ir iš kaimenių, iš visokiausių gyvulių, ir duok juos levitams, kurie laikosi VIEŠPATIES padangtės pareigų“.'),
  (@b4, 31, 31, 'Ir Mozė bei kunigas Eleazaras padarė, kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 31, 32, 'O prisiplėštas turtas – likęs grobis, kurį karo vyrai buvo pagavę, – buvo šeši šimtai septyniasdešimt penki tūkstančiai avių,'),
  (@b4, 31, 33, 'septyniasdešimt du tūkstančiai galvijų,'),
  (@b4, 31, 34, 'šešiasdešimt vienas tūkstantis asilų'),
  (@b4, 31, 35, 'ir iš viso trisdešimt du tūkstančiai asmenų iš moterų, kurios nebuvo pažinusios vyro, sugulant su juo.'),
  (@b4, 31, 36, 'O pusė, kuri buvo dalis tų, kurie ėjo į karą, skaičiumi buvo trys šimtai trisdešimt septyni tūkstančiai penki šimtai avių;'),
  (@b4, 31, 37, 'o VIEŠPATIES duoklė iš avių buvo šeši šimtai septyniasdešimt penkios.'),
  (@b4, 31, 38, 'O galvijų buvo trisdešimt šeši tūkstančiai; iš kurių VIEŠPATIES duoklė buvo septyniasdešimt du.'),
  (@b4, 31, 39, 'O asilų buvo trisdešimt tūkstančių penki šimtai; iš kurių VIEŠPATIES duoklė buvo šešiasdešimt vienas.'),
  (@b4, 31, 40, 'O žmonių buvo šešiolika tūkstančių; iš kurių VIEŠPATIES duoklė buvo trisdešimt du asmenys.'),
  (@b4, 31, 41, 'Ir Mozė davė duoklę, kuri buvo iškeliamoji VIEŠPATIES atnaša, kunigui Eleazarui, kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 31, 42, 'O iš Izraelio vaikų pusės, kurią Mozė buvo atidalijęs nuo kariavusių vyrų'),
  (@b4, 31, 43, '(na, o susirinkimui priklausanti pusė buvo trys šimtai trisdešimt septyni tūkstančiai penki šimtai avių,'),
  (@b4, 31, 44, 'trisdešimt šeši tūkstančiai galvijų,'),
  (@b4, 31, 45, 'trisdešimt tūkstančių penki šimtai asilų'),
  (@b4, 31, 46, 'ir šešiolika tūkstančių žmonių),'),
  (@b4, 31, 47, 'būtent iš pusės Izraelio vaikų, Mozė paėmė po vieną dalį iš penkiasdešimties, tiek iš žmonių, tiek iš gyvulių, ir juos davė levitams, kurie laikėsi VIEŠPATIES padangtės pareigų; kaip VIEŠPATS įsakė Mozei.'),
  (@b4, 31, 48, 'Ir priėjo prie Mozės pareigūnai, vadovaujantys kariuomenės tūkstančiams, tūkstančių vadai bei šimtų vadai;'),
  (@b4, 31, 49, 'ir jie tarė Mozei: „Tavo tarnai suskaičiavo karo vyrus, kurie yra mums pavaldūs, ir nei vieno mūsų netrūko.'),
  (@b4, 31, 50, 'Todėl atnešėme auką VIEŠPAČIUI, ką kiekvienas įsigijo iš aukso brangenybių, grandinėlių, apyrankių, žiedų, auskarų ir plokštelių, atlikti sutaikinimą už mūsų sielas VIEŠPATIES akivaizdoje“.'),
  (@b4, 31, 51, 'Ir Mozė ir kunigas Eleazaras paėmė iš jų auksą, tai yra visas pagamintas brangenybes.'),
  (@b4, 31, 52, 'O viso atnašaujamo aukso, kurį jie atnašavo VIEŠPAČIUI iš tūkstantininkų ir iš šimtininkų, buvo šešiolika tūkstančių septyni šimtai penkiasdešimt šekelių'),
  (@b4, 31, 53, '(nes karo vyrai buvo paėmę grobio kiekvienas sau).'),
  (@b4, 31, 54, 'O Mozė ir kunigas Eleazaras paėmė tą auksą iš tūkstančių bei šimtų vadų ir įnešė jį į susirinkimo padangtę kaip atminimą Izraelio vaikams VIEŠPATIES akivaizdoje.'),
  (@b4, 32, 1, 'Na, o Rubeno vaikai ir Gado vaikai turėjo didelę daugybę galvijų; ir jiems pamačius Jazero šalį ir Gileado šalį, štai ta vieta buvo vieta galvijams;'),
  (@b4, 32, 2, 'Gado vaikai ir Rubeno vaikai atėję kalbėjo Mozei, kunigui Eleazarui ir susirinkimo kunigaikščiams, sakydami:'),
  (@b4, 32, 3, '„Atarotas, Dibonas, Jazeras, Nimra, Hešbonas, Elealė, Šebamas, Nebas ir Beonas,'),
  (@b4, 32, 4, 'būtent šalis, kurią VIEŠPATS sumušė Izraelio susirinkimo akivaizdoje, yra šalis galvijams, o tavo tarnai turi galvijų;'),
  (@b4, 32, 5, 'todėl, – tarė jie, – jei radome malonę tavo akyse, tebūna ši šalis duota tavo tarnams nuosavybėn, ir nevesk mūsų per Jordaną“.'),
  (@b4, 32, 6, 'Ir Mozė tarė Gado vaikams ir Rubeno vaikams: „Ar jūsų broliai eis į karą, o jūs čia sėdėsite?'),
  (@b4, 32, 7, 'Ir kodėl atimate drąsą Izraelio vaikų širdims, kad nepereitų į šalį, kurią VIEŠPATS yra jiems davęs?'),
  (@b4, 32, 8, 'Taip darė jūsų tėvai, kai juos siunčiau iš Kadeš-Barnėjos tos šalies apžiūrėti.'),
  (@b4, 32, 9, 'Nes nuėję aukštyn į Eškolo slėnį ir apžiūrėję tą šalį, jie atėmė drąsą Izraelio vaikų širdims, kad jie neitų į šalį, kurią VIEŠPATS buvo jiems davęs.'),
  (@b4, 32, 10, 'Ir tuo pačiu metu užsidegė VIEŠPATIES pyktis, ir jis prisiekė, sakydamas:'),
  (@b4, 32, 11, '‘Nei vienas iš tų žmonių, kurie atėjo aukštyn iš Egipto, nuo dvidešimties metų ir vyresni, tikrai nematys tos šalies, kurią prisiekiau Abraomui, Izaokui ir Jokūbui; nes jie ne pilnai sekė manimi;'),
  (@b4, 32, 12, 'išskyrus kenazo Jefunės sūnų Kalebą ir Nūno sūnų Jozuę; nes jie pilnai sekė VIEŠPAČIU.'),
  (@b4, 32, 13, 'Ir užsidegė VIEŠPATIES pyktis prieš Izraelį, ir jis padarė, kad šis keturiasdešimt metų klaidžiojo dykumoje, kol buvo sunaikinta visa karta, kuri darė pikta VIEŠPATIES akyse.'),
  (@b4, 32, 14, 'O štai jūs, nusidėjėlių prieaugi, pakilote į savo tėvų vietą dar padidinti VIEŠPATIES įnirtingą pyktį prieš Izraelį.'),
  (@b4, 32, 15, 'Nes jei nusigręšite nuo sekimo paskui jį, jis vėl juos paliks dykumoje; ir jūs sunaikinsite visą šitą tautą“.'),
  (@b4, 32, 16, 'Ir prie jo priartėję, jie tarė: „Mes čia statysime avides savo galvijams ir miestus savo mažyliams;'),
  (@b4, 32, 17, 'bet mes patys eisime apsiginklavę Izraelio vaikų priešakyje, kol atvesime juos į jų vietą; o mūsų mažyliai gyvens aptvertuose miestuose dėl šalies gyventojų.'),
  (@b4, 32, 18, 'Mes negrįšime į savo namus, kol Izraelio vaikai nebus paveldėję kiekvienas savo paveldo.'),
  (@b4, 32, 19, 'Nes mes nepaveldėsime su jais anapus Jordano ar toliau; kadangi mums atiteko mūsų paveldas šiapus Jordano į rytus“.'),
  (@b4, 32, 20, 'Ir Mozė jiems tarė: „Jei tai darysite, jei apsiginklavę eisite į karą VIEŠPATIES akivaizdoje,'),
  (@b4, 32, 21, 'ir visi iš jūsų apsiginklavę pereis Jordaną VIEŠPATIES akivaizdoje, kol jis išvarys iš savo akivaizdos savo priešus,'),
  (@b4, 32, 22, 'ir šalis bus pajungta VIEŠPATIES akivaizdoje; tada paskui sugrįšite ir būsite nekalti VIEŠPATIES akivaizdoje ir Izraelio akivaizdoje; ir šita šalis bus jūsų nuosavybė VIEŠPATIES akivaizdoje.'),
  (@b4, 32, 23, 'Bet jei taip nepadarysite, štai jūs nusidėjote VIEŠPAČIUI; ir žinokite, kad jūsų nuodėmė jus atras.'),
  (@b4, 32, 24, 'Statykite miestus savo mažyliams ir avides savo avims; ir vykdykite tai, kas yra išėję iš jūsų burnos“.'),
  (@b4, 32, 25, 'Ir Gado vaikai bei Rubeno vaikai kalbėjo Mozei, sakydami: „Tavo tarnai darys, kaip mano viešpats įsako.'),
  (@b4, 32, 26, 'Mūsų mažyliai, mūsų žmonos, mūsų kaimenės ir visi mūsų galvijai bus ten Gileado miestuose;'),
  (@b4, 32, 27, 'bet tavo tarnai, kiekvienas apsiginklavęs karui, pereis VIEŠPATIES akivaizdoje į mūšį, kaip mano viešpats sako“.'),
  (@b4, 32, 28, 'Taigi Mozė įsakė dėl jų kunigui Eleazarui, Nūno sūnui Jozuei ir Izraelio vaikų genčių vyriausiems tėvams;'),
  (@b4, 32, 29, 'ir Mozė jiems tarė: „Jei Gado vaikai ir Rubeno vaikai pereis su jumis Jordaną kiekvienas apsiginklavęs į mūšį VIEŠPATIES akivaizdoje, ir šalis bus pavergta jūsų akivaizdoje; tuomet duokite jiems Gileado šalį nuosavybėn;'),
  (@b4, 32, 30, 'bet jei jie nepereis apsiginklavę su jumis, jie turės nuosavybę tarp jūsų Kanaano šalyje“.'),
  (@b4, 32, 31, 'Ir Gado vaikai bei Rubeno vaikai atsiliepė, tardami: „Kaip VIEŠPATS kalbėjo tavo tarnams, taip mes darysime.'),
  (@b4, 32, 32, 'Mes pereisime apsiginklavę VIEŠPATIES akivaizdoje į Kanaano šalį, kad mūsų paveldo nuosavybė šiapus Jordano būtų mūsų“.'),
  (@b4, 32, 33, 'Ir Mozė davė jiems, tai yra, Gado vaikams, Rubeno vaikams ir Juozapo sūnaus Manaso pusei genties, amoritų karaliaus Sihono karalystę ir Bašano karaliaus Ogo karalystę – šalį su jos ribose esančiais jos miestais, tai yra, aplinkinio krašto miestus.'),
  (@b4, 32, 34, 'Ir Gado vaikai pastatė Diboną, Atarotą, Aroerį,'),
  (@b4, 32, 35, 'Atrotą, Šofaną, Jazerą, Jogbehą,'),
  (@b4, 32, 36, 'Bet-Nimrą, Bet-Haraną, aptvertus miestus; ir aptvarus avims.'),
  (@b4, 32, 37, 'O Rubeno vaikai pastatė Hešboną, Elealę, Kirjataimą,'),
  (@b4, 32, 38, 'Nebą ir Baal-Meoną (jų vardai pakeisti) ir Sibmą; ir davė kitus vardus miestams, kuriuos jie pastatė.'),
  (@b4, 32, 39, 'Ir Manaso sūnaus Machyro vaikai nuėjo į Gileadą ir paėmė jį bei atėmė nuosavybę iš amoritų, esančių jame.'),
  (@b4, 32, 40, 'Ir Mozė davė Gileadą Manaso sūnui Machyrui; ir jis apsigyveno jame.'),
  (@b4, 32, 41, 'O Manaso sūnus Jayras nuėjęs paėmė jo mažus miestelius ir juos pavadino Havot-Jayru.'),
  (@b4, 32, 42, 'O Nobachas nuvykęs paėmė Kenatą bei jo kaimus ir jį pavadino Nobachu, pagal savo paties vardą.'),
  (@b4, 33, 1, 'Šitos yra kelionės Izraelio vaikų, kurie, Mozės ir Aarono rankai vadovaujant, savo kariuomenėmis išėjo iš Egipto šalies.'),
  (@b4, 33, 2, 'Ir Mozė užrašė jų išvykimus pagal jų keliones, pagal VIEŠPATIES įsakymą; ir šitos yra jų kelionės pagal jų išvykimus.'),
  (@b4, 33, 3, 'Ir jie išvyko iš Ramzio pirmąjį mėnesį, penkioliktąją pirmojo mėnesio dieną; rytojaus dieną po Apėjimo Izraelio vaikai išvyko per aukštą ranką visų egiptiečių akyse.'),
  (@b4, 33, 4, 'Nes egiptiečiai laidojo visus savo pirmagimius, kuriuos VIEŠPATS buvo užmušęs tarp jų; taip pat jų dievams VIEŠPATS įvykdė teismą.'),
  (@b4, 33, 5, 'Ir Izraelio vaikai, pasitraukę iš Ramzio, stovyklavo Sukote.'),
  (@b4, 33, 6, 'Ir išvykę iš Sukoto, jie stovyklavo Etame, esančiame dykumos pakraštyje.'),
  (@b4, 33, 7, 'Ir pasitraukę iš Etamo, jie apsigręžė į Pi-Hahirotą, esantį priešais Baal-Sefoną; ir jie stovyklavo priešais Migdolą.'),
  (@b4, 33, 8, 'Ir išvykę iš Pi-Hahiroto, jie perėjo per jūros vidurį į dykumą ir, nuėję trijų dienų kelionę Etamo dykumoje, stovyklavo Maroje.'),
  (@b4, 33, 9, 'Ir pasitraukę iš Maros, jie atvyko į Elimą; o Elime buvo dvylika vandens šaltinių ir septyniasdešimt palmių; ir jie ten stovyklavo.'),
  (@b4, 33, 10, 'Ir pasitraukę iš Elimo, jie stovyklavo prie Raudonosios jūros.'),
  (@b4, 33, 11, 'Ir pasitraukę nuo Raudonosios jūros, jie stovyklavo Sino dykumoje.'),
  (@b4, 33, 12, 'Ir iškeliavę iš Sino dykumos, jie stovyklavo Dofkoje.'),
  (@b4, 33, 13, 'Ir išvykę iš Dofkos, jie stovyklavo Aluše.'),
  (@b4, 33, 14, 'Ir pasitraukę iš Alušo, jie stovyklavo Refidime, kur nebuvo vandens tautai gerti.'),
  (@b4, 33, 15, 'Ir išvykę iš Refidimo, jie stovyklavo Sinajaus dykumoje.'),
  (@b4, 33, 16, 'Ir pasitraukę iš Sinajaus dykumos, jie stovyklavo Kibrot-Hataavoje.'),
  (@b4, 33, 17, 'Ir išvykę iš Kibrot-Hataavos, jie stovyklavo Hacerote.'),
  (@b4, 33, 18, 'Ir išvykę iš Haceroto, jie stovyklavo Ritmoje.'),
  (@b4, 33, 19, 'Ir išvykę iš Ritmos, jie stovyklavo Rimon-Perese.'),
  (@b4, 33, 20, 'Ir išvykę iš Rimon-Pereso, jie stovyklavo Libnoje.'),
  (@b4, 33, 21, 'Ir pasitraukę iš Libnos, jie stovyklavo Risoje.'),
  (@b4, 33, 22, 'Ir iškeliavę iš Risos, jie stovyklavo Kehelatoje.'),
  (@b4, 33, 23, 'Ir išvykę iš Kehelatos, jie stovyklavo Šefero kalne.'),
  (@b4, 33, 24, 'Ir pasitraukę iš Šefero kalno, jie stovyklavo Haradoje.'),
  (@b4, 33, 25, 'Ir pasitraukę iš Harados, jie stovyklavo Makhelote.'),
  (@b4, 33, 26, 'Ir pasitraukę iš Makheloto, jie stovyklavo Tahate.'),
  (@b4, 33, 27, 'Ir išvykę iš Tahato, jie stovyklavo Terache.'),
  (@b4, 33, 28, 'Ir pasitraukę iš Teracho, jie stovyklavo Mitkoje.'),
  (@b4, 33, 29, 'Ir išvykę iš Mitkos, jie stovyklavo Hašmonoje.'),
  (@b4, 33, 30, 'Ir išvykę iš Hašmonos, jie stovyklavo Moserote.'),
  (@b4, 33, 31, 'Ir išvykę iš Moseroto, jie stovyklavo Bene-Jaakane.'),
  (@b4, 33, 32, 'Ir pasitraukę iš Bene-Jaakano, jie stovyklavo Hor-Hagidgade.'),
  (@b4, 33, 33, 'Ir išvykę iš Hor-Hagidgado, jie stovyklavo Jotbatoje.'),
  (@b4, 33, 34, 'Ir pasitraukę iš Jotbatos, jie stovyklavo Ebronoje.'),
  (@b4, 33, 35, 'Ir išvykę iš Ebronos, jie stovyklavo Ecjon-Gebere.'),
  (@b4, 33, 36, 'Ir pasitraukę iš Ecjon-Gebero, jie stovyklavo Cino dykumoje, kuris yra Kadešas.'),
  (@b4, 33, 37, 'Ir pasitraukę iš Kadešo, jie stovyklavo Horo kalne, Edomo šalies pakraštyje.'),
  (@b4, 33, 38, 'Ir VIEŠPAČIUI įsakius, kunigas Aaronas užlipo į Horo kalną ir ten mirė keturiasdešimtaisiais metais po Izraelio vaikų išėjimo iš Egipto šalies, penktojo mėnesio pirmąją dieną.'),
  (@b4, 33, 39, 'O Aaronas buvo šimto dvidešimt trejų metų amžiaus, kai jis mirė Horo kalne.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b4, 33, 40, 'O kanaanietis, Arado karalius, gyvenantis pietuose, Kanaano šalyje, išgirdo ateinant Izraelio vaikus.'),
  (@b4, 33, 41, 'Ir išvykę nuo Horo kalno, jie stovyklavo Calmonoje.'),
  (@b4, 33, 42, 'Ir išvykę iš Calmonos, jie stovyklavo Punone.'),
  (@b4, 33, 43, 'Ir išvykę iš Punono, jie stovyklavo Obote.'),
  (@b4, 33, 44, 'Ir išvykę iš Oboto, jie stovyklavo Ije-Abarime, Moabo pasienyje.'),
  (@b4, 33, 45, 'Ir išvykę iš Ijimo, jie stovyklavo Dibon-Gade.'),
  (@b4, 33, 46, 'Ir pasitraukę iš Dibon-Gado, jie stovyklavo Almon-Diblataime.'),
  (@b4, 33, 47, 'Ir pasitraukę iš Almon-Diblataimo, jie stovyklavo Abarimo kalnuose priešais Nebą.'),
  (@b4, 33, 48, 'Ir išvykę iš Abarimo kalnų, jie stovyklavo Moabo lygumose prie Jordano šalia Jericho.'),
  (@b4, 33, 49, 'Ir jie stovyklavo prie Jordano nuo Bet-Ješimoto iki Abel-Šitimo, Moabo lygumose.'),
  (@b4, 33, 50, 'Ir VIEŠPATS kalbėjo Mozei Moabo lygumose prie Jordano šalia Jericho, sakydamas:'),
  (@b4, 33, 51, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Kai būsite perėję per Jordaną į Kanaano šalį,'),
  (@b4, 33, 52, 'išvarykite nuo savo akivaizdos visus šalies gyventojus ir sunaikinkite visus jų paveikslus, sunaikinkite visus jų nulietus atvaizdus ir visiškai išgriaukite visas jų aukštumas;'),
  (@b4, 33, 53, 'ir atimkite nuosavybę iš šalies gyventojų ir joje gyvenkite; nes jums daviau tą šalį, kad ją pasisavintumėte.'),
  (@b4, 33, 54, 'Ir burtu padalinkite tą šalį paveldui tarp savo šeimų: daugumai duokite didesnį paveldą, o mažumai duokite mažesnį paveldą; kiekvieno paveldas bus toje vietoje, kur kris jo burtas; paveldėsite pagal savo tėvų gentis.'),
  (@b4, 33, 55, 'Bet jei neišvarysite nuo savo akivaizdos šalies gyventojų, tuomet įvyks, kad tie, kuriuos iš jų paliksite, bus spygliais jūsų akyse ir dygliais jūsų šonuose, ir jus spaus šalyje, kurioje gyvensite.'),
  (@b4, 33, 56, 'Be to, įvyks, kad aš jums padarysiu taip, kaip sumaniau padaryti jiems’“.'),
  (@b4, 34, 1, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 34, 2, '„Įsakyk Izraelio vaikams ir jiems sakyk: ‘Kai ateisite į Kanaano šalį (tai yra šalis, kuri atiteks jums kaip paveldas, tai yra Kanaano šalis su jos ribomis),'),
  (@b4, 34, 3, 'tada jūsų pietinė pusė bus nuo Cino dykumos palei Edomo ribą, o jūsų pietinė riba bus Druskos jūros tolimiausia riba rytų link;'),
  (@b4, 34, 4, 'ir jūsų riba pasisuks nuo pietų į Akrabimo pakilimą, paeis toliau į Ciną; ir jos išėjimas bus nuo pietų iki Kadeš-Barnėjos, tęsis į Hacar-Adarą ir eis toliau į Acmoną;'),
  (@b4, 34, 5, 'ir ta riba eis aplink nuo Acmono iki Egipto upės ir ji baigsis ties jūra.'),
  (@b4, 34, 6, 'O dėl vakarinės ribos, jums riba bus Didžioji jūra; šita bus jūsų vakarinė riba.'),
  (@b4, 34, 7, 'O ši bus jūsų šiaurinė riba: nuo Didžiosios jūros atsižymėkite sau Horo kalną;'),
  (@b4, 34, 8, 'nuo Horo kalno atsižymėkite savo ribą iki Hamato įėjimo; ir tos ribos išėjimas bus iki Zedado;'),
  (@b4, 34, 9, 'ir riba eis tolyn į Zifroną, ir jos galas bus ties Hacar-Enanu; šita bus jūsų šiaurinė riba.'),
  (@b4, 34, 10, 'Ir atsižymėkite savo rytinę ribą nuo Hacar-Enano iki Šefamo;'),
  (@b4, 34, 11, 'ir riba eis žemyn nuo Šefamo iki Riblos, rytinėje Aino pusėje; ir riba nusileis ir sieks rytinį Kinereto jūros šoną;'),
  (@b4, 34, 12, 'ir riba eis žemyn į Jordaną, ir jos galas bus ties Druskos jūra; tai bus jūsų šalis su savo ribomis aplinkui’“.'),
  (@b4, 34, 13, 'Ir Mozė įsakė Izraelio vaikams, sakydamas: „Šita yra šalis, kurią paveldėsite burtu, kurią VIEŠPATS įsakė duoti devynioms gentims ir pusei genties;'),
  (@b4, 34, 14, 'nes Rubeno vaikų gentis pagal savo tėvų namus ir Gado vaikų gentis pagal savo tėvų namus gavo savąjį paveldą; ir pusė Manaso genties gavo savo paveldą;'),
  (@b4, 34, 15, 'dvi gentys ir pusė genties gavo savąjį paveldą šiapus Jordano šalia Jericho, rytuose, į saulėtekio pusę“.'),
  (@b4, 34, 16, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 34, 17, '„Šitie yra vardai vyrų, kurie jums padalins šalį: kunigas Eleazaras ir Nūno sūnus Jozuė.'),
  (@b4, 34, 18, 'Ir paimkite po vieną kunigaikštį iš kiekvienos genties, kad padalintų šalį pagal paveldą.'),
  (@b4, 34, 19, 'O šitie yra vyrų vardai: iš Judos genties – Jefunės sūnus Kalebas;'),
  (@b4, 34, 20, 'iš Simeono vaikų genties – Amihudo sūnus Semuelis;'),
  (@b4, 34, 21, 'iš Benjamino genties – Kislono sūnus Elidadas;'),
  (@b4, 34, 22, 'o Dano vaikų genties kunigaikštis Bukis, Joglio sūnus;'),
  (@b4, 34, 23, 'Juozapo vaikų kunigaikštis dėl Manaso vaikų genties, Efodo sūnus Hanielis;'),
  (@b4, 34, 24, 'o Efraimo vaikų genties kunigaikštis Kemuelis, Šiftano sūnus;'),
  (@b4, 34, 25, 'o Zebulono vaikų genties kunigaikštis Elicafanas, Parnacho sūnus;'),
  (@b4, 34, 26, 'o Isacharo vaikų genties kunigaikštis Paltielis, Azano sūnus;'),
  (@b4, 34, 27, 'o Ašero vaikų genties kunigaikštis Ahihudas, Šelomio sūnus;'),
  (@b4, 34, 28, 'o Naftalio vaikų genties kunigaikštis Pedahelis, Amihudo sūnus“.'),
  (@b4, 34, 29, 'Šitie yra tie, kuriems VIEŠPATS įsakė padalinti Izraelio vaikams paveldą Kanaano šalyje.'),
  (@b4, 35, 1, 'Ir VIEŠPATS kalbėjo Mozei Moabo lygumose prie Jordano šalia Jericho, sakydamas:'),
  (@b4, 35, 2, '„Įsakyk Izraelio vaikams, kad jie iš savo nuosavybės paveldo duotų levitams miestų apsigyvenimui; ir taip pat duokite levitams priemiesčius miestams aplink juos.'),
  (@b4, 35, 3, 'Ir jie turės miestus gyvenimui juose; o jų priemiesčiai bus jų galvijams, jų turtui ir visiems jų gyvuliams.'),
  (@b4, 35, 4, 'Ir miestų priemiesčiai, kuriuos duosite levitams, sieks nuo miesto sienos į išorę tūkstantį uolekčių aplinkui.'),
  (@b4, 35, 5, 'Ir atmatuokite nuo miesto išorės du tūkstančius uolekčių rytinėje pusėje, du tūkstančius uolekčių pietinėje pusėje, du tūkstančius uolekčių vakarinėje pusėje ir du tūkstančius uolekčių šiaurinėje pusėje; o miestas bus viduryje; tai jiems bus miestų priemiesčiai.'),
  (@b4, 35, 6, 'O tarp miestų, kuriuos duosite levitams, bus šeši miestai prieglobsčiui, kuriuos paskirsite užmušusiajam žmogų, kad jis ten galėtų pabėgti; ir prie jų pridėkite keturiasdešimt du miestus.'),
  (@b4, 35, 7, 'Taigi iš viso miestų, kuriuos duosite levitams, bus keturiasdešimt aštuoni miestai; juos duosite su jų priemiesčiais.'),
  (@b4, 35, 8, 'Ir miestai, kuriuos duosite, bus iš Izraelio vaikų nuosavybės; iš tų, kurie turi daug, duosite daug; bet iš turinčių mažai, duosite mažai; kiekvienas duos iš savo miestų levitams pagal savo paveldėtą paveldą“.'),
  (@b4, 35, 9, 'Ir VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b4, 35, 10, '„Kalbėk Izraelio vaikams ir jiems sakyk: ‘Kai pereisite per Jordaną į Kanaano šalį,'),
  (@b4, 35, 11, 'paskirkite sau miestus, kad būtų jums prieglobsčio miestai; kad galėtų ten pabėgti užmušėjas, netyčiomis užmušęs žmogų.'),
  (@b4, 35, 12, 'Ir jie jums bus miestai prieglobsčiui nuo keršytojo; kad žmogaus užmušėjas nemirtų, kol jis stos susirinkimo akivaizdon į teismą.'),
  (@b4, 35, 13, 'Ir iš šitų miestų, kuriuos duosite, šešis miestus turėsite prieglobsčiui.'),
  (@b4, 35, 14, 'Tris miestus duokite šiapus Jordano ir tris miestus duokite Kanaano šalyje, kurie bus prieglobsčio miestai.'),
  (@b4, 35, 15, 'Šitie šeši miestai bus prieglobstis tiek Izraelio vaikams, tiek ateiviui, tiek laikinai apsigyvenusiam tarp jų; kad ten galėtų pabėgti kiekvienas, kuris netyčiomis užmuša žmogų.'),
  (@b4, 35, 16, 'O jei jis jį muštų geležiniu įrankiu taip, kad tas mirtų, tai jis yra žmogžudys; žmogžudys tikrai bus užmuštas.'),
  (@b4, 35, 17, 'Ir jei jis jį muštų mesdamas akmenį, nuo ko galima mirti, ir tas mirtų, tai jis yra žmogžudys; žmogžudys tikrai bus užmuštas.'),
  (@b4, 35, 18, 'Arba jei jis jį muštų mediniu rankiniu ginklu, nuo kurio galima mirti, ir tas mirtų, tai jis yra žmogžudys; žmogžudys tikrai bus užmuštas.'),
  (@b4, 35, 19, 'Pats kraujo keršytojas užmuš žmogžudį; jį sutikęs, jis jį užmuš.'),
  (@b4, 35, 20, 'Bet jei jis iš neapykantos jį pastumtų ar mestų į jį tykodamas, kad tas mirtų;'),
  (@b4, 35, 21, 'ar priešiškai nusistatęs muštų jį savo ranka, kad tas mirtų; tas, kuris jį mušė, tikrai bus užmuštas; nes jis yra žmogžudys; kraujo keršytojas užmuš žmogžudį, jį sutikęs.'),
  (@b4, 35, 22, 'Bet jei jis pastumtų jį netikėtai, nenusistatęs priešiškai, ar mestų ant jo ką nors netykodamas,'),
  (@b4, 35, 23, 'ar jo nepastebėjęs užmestų ant jo kokį nors akmenį, nuo kurio galima mirti, taip, kad jis mirtų, bet nebuvęs jo priešas nei nesiekęs jam pakenkti;'),
  (@b4, 35, 24, 'tuomet susirinkimas teis tarp užmušėjo ir kraujo keršytojo pagal šituos teismus;'),
  (@b4, 35, 25, 'ir susirinkimas išgelbės užmušėją iš kraujo keršytojo rankos, ir susirinkimas jį sugrąžins į jo prieglobsčio miestą, į kurį jis buvo pabėgęs; ir jis jame pasiliks iki mirties aukščiausiojo kunigo, kuris buvo pateptas šventu aliejumi.'),
  (@b4, 35, 26, 'Bet jei užmušėjas kada nors išeis už jo prieglobsčio miesto ribos, į kurį jis buvo pabėgęs;'),
  (@b4, 35, 27, 'ir kraujo keršytojas aptiks jį už jo prieglobsčio miesto ribų, ir kraujo keršytojas nužudys užmušėją; tai jis nebus kaltas dėl kraujo;'),
  (@b4, 35, 28, 'kadangi anas turėjo pasilikti savo prieglobsčio mieste iki aukščiausiojo kunigo mirties; bet po aukščiausiojo kunigo mirties užmušėjas sugrįš į savo nuosavybės žemę.'),
  (@b4, 35, 29, 'Taigi šitie dalykai jums bus teismo įstatas per jūsų kartas visose jūsų buveinėse.'),
  (@b4, 35, 30, 'Kas užmuš žmogų, pagal liudininkų burną žudikas bus užmuštas; bet vienas liudininkas neliudys prieš jokį asmenį, kad priverstų jį mirti.'),
  (@b4, 35, 31, 'Be to, neimkite atsiteisimo už gyvybę žudiko, kuris yra kaltas mirtimi; bet jis tikrai bus užmuštas.'),
  (@b4, 35, 32, 'Ir neimkite atsiteisimo už pabėgusį į savo prieglobsčio miestą, kad jis sugrįžtų gyventi šalyje iki kunigo mirties.'),
  (@b4, 35, 33, 'Taip jūs neteršite šalies, kurioje esate; nes kraujas – jis suteršia šalį; ir šalis negali būti apvalyta nuo joje pralieto kraujo, tik krauju to, kuris jį praliejo.'),
  (@b4, 35, 34, 'Todėl neterškite šalies, kurioje jūs apsigyvensite, kurioje aš gyvenu; nes aš, VIEŠPATS, gyvenu tarp Izraelio vaikų’“.'),
  (@b4, 36, 1, 'O Manaso sūnaus Machyro sūnaus Gileado vaikų šeimų vyriausieji tėvai iš Juozapo sūnų šeimų priėjo ir kalbėjo Mozės akivaizdoje bei kunigaikščių, Izraelio vaikų vyriausiųjų tėvų, akivaizdoje;'),
  (@b4, 36, 2, 'ir jie tarė: „Mano viešpačiui VIEŠPATS įsakė duoti burtu šalį kaip paveldą Izraelio vaikams; ir mano viešpačiui buvo VIEŠPATIES įsakyta duoti mūsų brolio Celofechado paveldą jo dukterims.'),
  (@b4, 36, 3, 'Ir jei jos ištekės už kurio iš kitų Izraelio vaikų genčių sūnų, tuomet jų paveldas bus atimtas nuo mūsų tėvų paveldo, o bus pridėtas prie paveldo tos genties, į kurią jos yra priimtos; taip bus atimta nuo mūsų burto paveldo.'),
  (@b4, 36, 4, 'Ir kai bus Izraelio vaikų jubiliejus, tuomet jų paveldas bus pridėtas prie paveldo tos genties, į kurią jos yra priimtos; taip jų paveldas bus atimtas nuo mūsų tėvų genties paveldo“.'),
  (@b4, 36, 5, 'Ir Mozė įsakė Izraelio vaikams pagal VIEŠPATIES žodį, sakydamas: „Juozapo sūnų gentis pasakė gerai.'),
  (@b4, 36, 6, 'Štai ką VIEŠPATS įsako apie Celofechado dukteris, sakydamas: ‘Tegul jos išteka už to, kuris joms patinka; tik už jų tėvo genties šeimos jos teišteka.'),
  (@b4, 36, 7, 'Taip Izraelio vaikų paveldas nepereis iš genties į gentį; nes kiekvienas iš Izraelio vaikų laikysis prie savo tėvų genties paveldo.'),
  (@b4, 36, 8, 'Ir kiekviena duktė, turinti paveldą kurioje nors Izraelio vaikų gentyje, bus žmona vienos iš jos tėvo genties šeimos, kad Izraelio vaikai kiekvienas turėtų savo tėvų paveldą.'),
  (@b4, 36, 9, 'Taip pat paveldas nepereis iš vienos genties į kitą gentį; bet kiekvienas iš Izraelio vaikų genčių laikysis prie savo paties paveldo’“.'),
  (@b4, 36, 10, 'Kaip VIEŠPATS įsakė Mozei, taip padarė Celofechado dukterys;'),
  (@b4, 36, 11, 'nes Machla, Tirca, Hogla, Milka ir Noja, Celofechado dukterys, ištekėjo už savo tėvo brolių sūnų;'),
  (@b4, 36, 12, 'ir jos ištekėjo į Juozapo sūnaus Manaso sūnų šeimas, ir jų paveldas pasiliko jų tėvo šeimos gentyje.'),
  (@b4, 36, 13, 'Šitie yra įsakymai ir teismai, kuriuos VIEŠPATS įsakė per Mozės ranką Izraelio vaikams Moabo lygumose prie Jordano šalia Jericho.'),
  (@b5, 1, 1, 'Šitie yra žodžiai, kuriuos Mozė kalbėjo visam Izraeliui šioje Jordano pusėje, dykumoje, lygumoje priešais Raudonąją jūrą, tarp Parano ir Tofelio, ir Labano, ir Haceroto, ir Dizahabo'),
  (@b5, 1, 2, '(nuo Horebo iki Kadeš-Barnėjos Seyro kalno keliu yra vienuolikos dienų kelionė).'),
  (@b5, 1, 3, 'Ir įvyko keturiasdešimtaisiais metais, vienuoliktąjį mėnesį, to mėnesio pirmąją dieną, kad Mozė kalbėjo Izraelio vaikams pagal visa, ką VIEŠPATS jam buvo davęs įsakymu jiems;'),
  (@b5, 1, 4, 'po to, kai jis buvo užmušęs amoritų karalių Sihoną, gyvenusį Hešbone, ir Bašano karalių Ogą, gyvenusį Aštarote, Edrėjuje;'),
  (@b5, 1, 5, 'šioje Jordano pusėje, Moabo šalyje, Mozė pradėjo skelbti šitą įstatymą, sakydamas:'),
  (@b5, 1, 6, '„VIEŠPATS, mūsų Dievas, mums kalbėjo Horebe, sakydamas: ‘Užtektinai ilgai gyvenote šiame kalne;'),
  (@b5, 1, 7, 'gręžkitės, leiskitės į kelionę ir eikite į amoritų kalną ir į visas jam artimas vietoves, į lygumą, į kalvas, į slėnį, į pietus ir palei jūros krantą, į kanaaniečių šalį ir iki Libano, iki Didžiosios upės – Eufrato upės.'),
  (@b5, 1, 8, 'Štai aš padėjau prieš jus tą šalį; įeikite ir pasisavinkite tą šalį, kurią VIEŠPATS prisiekė jūsų tėvams, Abraomui, Izaokui ir Jokūbui, duoti jiems ir jų sėklai po jų.'),
  (@b5, 1, 9, 'Ir anuo metu jums kalbėjau, sakydamas: ‘Aš pats vienas nepajėgiu jūsų nešti;'),
  (@b5, 1, 10, 'VIEŠPATS, jūsų Dievas, jus padaugino, ir štai jūs šią dieną dėl daugybės esate kaip dangaus žvaigždės'),
  (@b5, 1, 11, '(VIEŠPATS, jūsų tėvų Dievas, tepadaugina jus tūkstantį kartų daugiau negu esate ir jus tepalaimina, kaip jis yra jums pažadėjęs!).'),
  (@b5, 1, 12, 'Kaip aš vienas pats galiu pakelti jūsų apsunkinimą, jūsų naštą ir jūsų vaidus?'),
  (@b5, 1, 13, 'Paimkite išmintingų vyrų, suprantančių ir žinomų tarp jūsų genčių, ir aš juos paskirsiu jūsų valdovais’.'),
  (@b5, 1, 14, 'Ir jūs man atsakėte ir tarėte: ‘Tas dalykas, kurį sakei, yra geras mums daryti’.'),
  (@b5, 1, 15, 'Taigi ėmiau jūsų genčių vyriausiuosius, išmintingus vyrus ir žinomus, ir juos paskyriau jums galvomis, tūkstančių vadais, šimtų vadais, penkiasdešimčių vadais, dešimčių vadais ir pareigūnais tarp jūsų genčių.'),
  (@b5, 1, 16, 'Ir tuo metu aš įpareigojau jūsų teisėjus, sakydamas: ‘Išklausykite bylas tarp savo brolių ir teiskite teisingai tarp kiekvieno žmogaus ir jo brolio bei ateivio, esančio pas jį.'),
  (@b5, 1, 17, 'Teisme neatsižvelkite į asmenis; bet išklausykite tiek mažą, tiek didelį; nebijokite žmogaus veido; nes teismas yra Dievo; o bylą, kuri yra jums per sunki, atneškite man, ir aš ją išklausysiu’.'),
  (@b5, 1, 18, 'Ir anuo metu jums įsakiau visus dalykus, kuriuos turite daryti.'),
  (@b5, 1, 19, 'Ir išėję iš Horebo, mes ėjome per visą tą didžiulę ir baisią dykumą, kurią matėte amoritų kalno kelyje, kaip VIEŠPATS, mūsų Dievas, mums įsakė; ir mes atėjome į Kadeš-Barnėją.'),
  (@b5, 1, 20, 'Ir aš jums sakiau: ‘Jūs atėjote į amoritų kalną, kurį VIEŠPATS, mūsų Dievas, mums duoda.'),
  (@b5, 1, 21, 'Štai VIEŠPATS, tavo Dievas, padėjo prieš tave tą šalį; eik aukštyn ir pasisavink ją, kaip VIEŠPATS, tavo tėvų Dievas, yra tau sakęs; nebijok ir neprarask drąsos.'),
  (@b5, 1, 22, 'Ir jūs visi priėjote prie manęs ir sakėte: ‘Mes pasiųsime vyrus pirma savęs, ir jie mums ištirts tą šalį ir parneš mums žinią, kokiu keliu mes turime eiti aukštyn ir į kokius miestus ateisime’.'),
  (@b5, 1, 23, 'Ir tas pasakymas man labai patiko; ir aš paėmiau iš jūsų dvylika vyrų, po vieną iš genties;'),
  (@b5, 1, 24, 'ir pasisukę jie ėjo aukštyn į kalną, ir atėjo į Eškolo slėnį ir jį ištyrė.'),
  (@b5, 1, 25, 'Ir jie paėmė į savo rankas iš tos šalies vaisių ir atnešė juos žemyn pas mus bei parnešė mums žinią ir sakė: ‘Tai gera šalis, kurią VIEŠPATS, mūsų Dievas, mums duoda’.'),
  (@b5, 1, 26, 'Tačiau jūs nenorėjote eiti aukštyn, bet maištavote prieš VIEŠPATIES, savo Dievo, įsakymą;'),
  (@b5, 1, 27, 'ir jūs murmėjote savo palapinėse, sakydami: ‘Kadangi VIEŠPATS nekentė mūsų, jis mus išvedė iš Egipto šalies, kad mus atiduotų į amoritų rankas, kad mus sunaikintų.'),
  (@b5, 1, 28, 'Kur mes eisime aukštyn? Mūsų broliai atėmė mūsų širdžių drąsą, sakydami: ‘Ta tauta yra didesnė ir aukštesnė už mus; miestai dideli ir apsupti sienomis iki dangaus; ir be to, ten matėme anakų sūnus’.'),
  (@b5, 1, 29, 'Tada jums sakiau: ‘Nenusigąskite ir nebijokite jų.'),
  (@b5, 1, 30, 'VIEŠPATS, jūsų Dievas, einantis pirma jūsų, kovos už jus pagal visa tai, ką jis dėl jūsų darė jūsų akyse Egipte;'),
  (@b5, 1, 31, 'ir dykumoje, kur matei, kaip VIEŠPATS, tavo Dievas, tave nešė, kaip žmogus neša savo sūnų, visame kelyje, kuriuo ėjote, kol atėjote į šią vietą’.'),
  (@b5, 1, 32, 'Tačiau ir tame jūs netikėjote VIEŠPAČIU, savo Dievu,'),
  (@b5, 1, 33, 'kuris ėjo pirma jūsų kelyje, kad surastų jums vietą jūsų palapinėms statyti – naktį ugnyje, kad jums rodytų, kuriuo keliu turite eiti, o dieną debesyje.'),
  (@b5, 1, 34, 'Ir VIEŠPATS, išgirdęs jūsų žodžių balsą, užsirūstino ir prisiekė, sakydamas:'),
  (@b5, 1, 35, '‘Tikrai, nei vienas iš šitų šitos piktos kartos žmonių nematys šios geros šalies, kurią prisiekiau duoti jūsų tėvams,'),
  (@b5, 1, 36, 'išskyrus Jefunės sūnų Kalebą; jis ją pamatys, ir jam duosiu tą šalį, kuria jis buvo žengęs, ir jo vaikams, nes jis pilnai sekė paskui VIEŠPATĮ’.'),
  (@b5, 1, 37, 'Taip pat VIEŠPATS dėl jūsų buvo supykęs ant manęs, sakydamas: ‘Tu irgi ten neįeisi.'),
  (@b5, 1, 38, 'Bet Nūno sūnus Jozuė, kuris stovi tavo akivaizdoje, jis ten įeis; padrąsink jį; nes jis padarys, kad Izraelis ją paveldėtų.'),
  (@b5, 1, 39, 'Be to, jūsų mažyliai, apie kuriuos sakėte, kad jie bus grobiu, ir jūsų vaikai, kurie tą dieną nežinojo skirtumo tarp gero ir blogo, jie ten įeis, ir jiems aš ją duosiu, ir jie ją pasisavins.'),
  (@b5, 1, 40, 'Bet kas dėl jūsų, jūs sukitės ir leiskitės kelionėn į dykumą Raudonosios jūros keliu’.'),
  (@b5, 1, 41, 'Tada jūs atsakėte ir man tarėte: ‘Mes nusidėjome VIEŠPAČIUI, mes eisime aukštyn ir kovosime pagal visa tai, ką VIEŠPATS, mūsų Dievas, mums įsakė’. Ir jūs, kiekvienas apsijuosęs savo kovos ginklais, buvote pasiruošę eiti aukštyn į kalvą.'),
  (@b5, 1, 42, 'Ir VIEŠPATS man tarė: ‘Sakyk jiems: „Neikite aukštyn nei nekovokite; nes aš nesu tarp jūsų; kad nebūtumėte sumušti savo priešų akivaizdoje“’.'),
  (@b5, 1, 43, 'Taip jums kalbėjau; o jūs nenorėjote klausyti, bet priešinotės VIEŠPATIES įsakymui ir, pernelyg pasitikėdami savimi, ėjote aukštyn į kalvą.'),
  (@b5, 1, 44, 'Ir amoritai, gyvenantys tame kalne, išėjo prieš jus ir jus vijosi, kaip bitės daro, ir jus sunaikino Seyre, tai yra iki Hormos.'),
  (@b5, 1, 45, 'Ir sugrįžę jūs verkėte VIEŠPATIES akivaizdoje, bet VIEŠPATS nenorėjo klausyti jūsų balso nei prilenkti jums savo ausies.'),
  (@b5, 1, 46, 'Taip daugelį dienų pasilikote Kadeše – pagal dienas, kurias ten išbuvote“.'),
  (@b5, 2, 1, '„Paskui pasukome ir leidomės kelionėn į dykumą Raudonosios jūros keliu, kaip VIEŠPATS man kalbėjo; ir daugelį dienų ėjome aplink Seyro kalną.'),
  (@b5, 2, 2, 'Ir VIEŠPATS man kalbėjo, sakydamas:'),
  (@b5, 2, 3, '‘Jūs užtektinai ilgai ėjote aplinkui šitą kalną; sukitės į šiaurę.'),
  (@b5, 2, 4, 'Ir įsakyk tautai, sakydamas: „Dabar pereisite per ribą savo brolių, Ezavo vaikų, gyvenančių Seyre; ir jie bijos jūsų; todėl labai žiūrėkitės savęs;'),
  (@b5, 2, 5, 'neprasidėkite su jais; nes aš jums neduosiu iš jų šalies nei tiek, kiek pėdos plotis; nes daviau Seyro kalną Ezavui nuosavybėn.'),
  (@b5, 2, 6, 'Pirkite iš jų maisto už pinigus, kad valgytumėte; ir taip pat vandens pirkite iš jų už pinigus, kad gertumėte.'),
  (@b5, 2, 7, 'Nes VIEŠPATS, tavo Dievas, tave palaimino visuose tavo rankos darbuose; jis pažįsta tavo vaikščiojimą per šitą didžiulę dykumą; šituos keturiasdešimt metų VIEŠPATS, tavo Dievas, buvo su tavimi; tau nieko nestigo’.'),
  (@b5, 2, 8, 'Ir praėję šalimais nuo savo brolių, Ezavo vaikų, gyvenančių Seyre, lygumos keliu nuo Elato ir nuo Ecjon-Gebero, mes pasisukę praėjome šalimais Moabo dykumos keliu.'),
  (@b5, 2, 9, 'Ir VIEŠPATS man tarė: ‘Nevargink moabiečių nei nekovok su jais mūšyje; nes nieko iš jo šalies tau neduosiu nuosavybėn; kadangi esu davęs Arą Loto vaikams nuosavybėn’.'),
  (@b5, 2, 10, 'Praeityje joje gyveno emai, didelė ir gausi tauta, aukšta kaip anakiečiai;'),
  (@b5, 2, 11, 'jie irgi buvo laikomi milžinais kaip anakiečiai; bet moabiečiai juos vadina emais.'),
  (@b5, 2, 12, 'Taip pat Seyre anksčiau gyveno horai; bet Ezavo vaikai juos pasisavino, išnaikinę juos iš savo akivaizdos, ir gyveno jų vietoje; kaip Izraelis padarė savo nuosavybės šaliai, kurią jiems davė VIEŠPATS.'),
  (@b5, 2, 13, '‘Dabar kelkitės, – tariau, – ir pereikite Zeredo upelį’. Ir mes perėjome Zeredo upelį.'),
  (@b5, 2, 14, 'O laiko tarpas, kuriuo atėjome iš Kadeš-Barnėjos, kol perėjome Zeredo upelį, buvo trisdešimt aštuoneri metai; kol visa karo vyrų karta išgaišo iš kariuomenės tarpo, kaip VIEŠPATS jiems prisiekė.'),
  (@b5, 2, 15, 'Nes tikrai VIEŠPATIES ranka buvo prieš juos, kad juos išnaikintų iš kariuomenės tarpo, kol jie buvo sunaikinti.'),
  (@b5, 2, 16, 'Taigi įvyko, kai visi karo vyrai buvo sunaikinti ir išmirę iš tautos tarpo,'),
  (@b5, 2, 17, 'VIEŠPATS man kalbėjo, sakydamas:'),
  (@b5, 2, 18, '‘Tu šią dieną pereisi per Arą, Moabo ribą;'),
  (@b5, 2, 19, 'ir priartėjęs prie Amono vaikų, nevargink jų ir neprasidėk su jais; nes iš Amono vaikų šalies neduosiu tau jokios nuosavybės; kadangi esu ją davęs Loto vaikams nuosavybėn’'),
  (@b5, 2, 20, '(ta taip pat buvo laikoma milžinų šalimi; senais laikais milžinai gyveno joje; o amoritai juos vadino zamzumais;'),
  (@b5, 2, 21, 'tauta didelė, gausi ir aukšta, kaip anakiečiai; bet VIEŠPATS juos išnaikino iš jų akivaizdos; ir jie pasisavino juos ir apsigyveno jų vietoje;'),
  (@b5, 2, 22, 'kaip jis padarė Ezavo vaikams, gyvenantiems Seyre, kai jis išnaikino horus iš jų akivaizdos; o jie pasisavino juos ir apsigyveno jų vietoje iki šios dienos;'),
  (@b5, 2, 23, 'ir avus, gyvenusius Hacerime iki Gazos, kaftoriečiai, išėję iš Kaftoro, juos išnaikino ir apsigyveno jų vietoje).'),
  (@b5, 2, 24, '‘Kelkitės, leiskitės kelionėn ir pereikite Arnono upę; štai aš daviau į tavo ranką amoritą Sihoną, Hešbono karalių ir jo šalį; pradėk ją savintis ir kovok su juo mūšyje.'),
  (@b5, 2, 25, 'Šią dieną pradėsiu dėti tavo išgąstį ir tavo baimę ant tautų, esančių po visu dangumi, kurios išgirs gandą apie tave ir drebės, ir bus kupinos sielvarto dėl tavęs’.'),
  (@b5, 2, 26, 'Ir aš siunčiau pasiuntinius iš Kedemoto dykumos pas Hešbono karalių Sihoną su taikos žodžiais, sakydamas:'),
  (@b5, 2, 27, '‘Leisk man pereiti per tavo šalį; aš eisiu išilgai vieškelio, nepasuksiu nei į dešinę, nei į kairę.'),
  (@b5, 2, 28, 'Parduok man maisto už pinigus, kad valgyčiau; ir duok man vandens už pinigus, kad gerčiau; aš tik pereisiu pėsčias'),
  (@b5, 2, 29, '(kaip man darė Ezavo vaikai, gyvenantys Seyre, ir moabiečiai, gyvenantys Are); kol pereisiu Jordaną į šalį, kurią VIEŠPATS, mūsų Dievas, mums duoda’.'),
  (@b5, 2, 30, 'Bet Hešbono karalius Sihonas neleido mums pereiti per jį; nes VIEŠPATS, tavo Dievas, užkietino jo dvasią ir padarė jo širdį užsispyrusią, kad atiduotų jį į tavo ranką, kaip matyti šią dieną.'),
  (@b5, 2, 31, 'Ir VIEŠPATS man tarė: ‘Štai aš pradėjau duoti Sihoną ir jo šalį tavo akivaizdoje; pradėk savintis, kad paveldėtum jo šalį’.'),
  (@b5, 2, 32, 'Tada Sihonas išėjo priešais mus, jis ir visa jo tauta, kautis Jahase.'),
  (@b5, 2, 33, 'O VIEŠPATS, mūsų Dievas, atidavė jį mūsų akivaizdoje; ir mes sumušėme jį, jo sūnus ir visą jo tautą.'),
  (@b5, 2, 34, 'Ir anuo metu ėmėme visus jo miestus ir iš kiekvieno miesto visiškai išnaikinome vyrus, moteris ir mažylius, nepalikome nei vieno, kad liktų;'),
  (@b5, 2, 35, 'tik pasiėmėme kaip grobį galvijus ir grobį miestų, kuriuos buvome paėmę.'),
  (@b5, 2, 36, 'Nuo Aroero, esančio prie Arnono upės kranto, ir nuo miesto, esančio prie upės, iki Gileado, nebuvo nei vieno miesto, kuris mums būtų per stiprus; visus mums atidavė VIEŠPATS, mūsų Dievas;'),
  (@b5, 2, 37, 'tik iki Amono vaikų šalies tu neatėjai nei iki jokios Jaboko upės vietos, nei iki miestų kalnuose, nei iki to, ką VIEŠPATS, mūsų Dievas, mums uždraudė“.'),
  (@b5, 3, 1, '„Paskui pasisukę, mes ėjome aukštyn keliu į Bašaną; o Bašano karalius Ogas išėjo prieš mus, jis ir visa jo tauta, kautis Edrėjuje.'),
  (@b5, 3, 2, 'Ir VIEŠPATS man tarė: ‘Nebijok jo; nes aš atiduosiu jį, visą jo tautą ir jo šalį į tavo ranką; o tu padaryk jam, kaip padarei amoritų karaliui Sihonui, gyvenusiam Hešbone’.'),
  (@b5, 3, 3, 'Taip VIEŠPATS, mūsų Dievas, atidavė į mūsų rankas ir Bašano karalių Ogą bei visą jo tautą; ir mes jį sumušėme, kol jam nebeliko nei vieno išlikusio.'),
  (@b5, 3, 4, 'Ir anuo metu paėmėme visus jo miestus, nebuvo nei vieno miesto, kurio nebūtume iš jų paėmę – šešiasdešimt miestų, visą Argobo kraštą, Ogo karalystę Bašane.'),
  (@b5, 3, 5, 'Visi tie miestai buvo aptverti aukštomis sienomis, vartais ir skląsčiais; neskaitant labai daug miestų be sienų.'),
  (@b5, 3, 6, 'Ir juos visiškai sunaikinome, kaip padarėme Hešbono karaliui Sihonui, visiškai išnaikindami iš kiekvieno miesto vyrus, moteris ir vaikus.'),
  (@b5, 3, 7, 'Bet visus galvijus ir miestų grobį pasiėmėme kaip išplėšas.'),
  (@b5, 3, 8, 'Ir anuo metu atėmėme iš dviejų amoritų karalių rankos šalį, buvusią šiapus Jordano, nuo Arnono upės iki Hermono kalno'),
  (@b5, 3, 9, '(sidoniečiai Hermoną vadina Sirjonu; o amoritai jį vadina Seniru);'),
  (@b5, 3, 10, 'visus lygumos miestus, visą Gileadą ir visą Bašaną iki Salchos ir Edrėjo, Ogo karalystės miestus Bašane.'),
  (@b5, 3, 11, 'Nes tik Bašano karalius Ogas buvo išlikęs iš milžinų likučio; štai jo lova buvo lova iš geležies; ar ji ne Amono vaikų Raboje? Jos ilgis buvo devynios uolektys, o jos plotis – keturios uolektys, pagal žmogaus uolektį.'),
  (@b5, 3, 12, 'Ir šitą šalį, kurią anuo metu pasisavinome iš Aroero, esančio prie Arnono upės, pusę Gileado kalno ir jo miestus daviau rubenams ir gadams.'),
  (@b5, 3, 13, 'O likusį Gileadą ir visą Bašaną – Ogo karalystę, daviau pusei Manaso genties; visą Argobo kraštą su visu Bašanu, vadinamu milžinų šalimi.'),
  (@b5, 3, 14, 'Manaso sūnus Jayras paėmė visą Argobo kraštą iki gešūriečių ir maakų ribų; ir tai praminė savo vardu, Bašan-Havot-Jayru, iki šios dienos.'),
  (@b5, 3, 15, 'O Machyrui daviau Gileadą,'),
  (@b5, 3, 16, 'o rubenams ir gadams daviau pusę slėnio nuo Gileado iki Arnono upės ir ribas iki Jaboko upės, kuri yra Amono vaikų riba;'),
  (@b5, 3, 17, 'taip pat lygumą ir Jordaną bei jo ribas nuo Kinereto iki Lygumos jūros, tai yra Druskos jūros, Ašdoto-Pisgos apačioje į rytus.'),
  (@b5, 3, 18, 'Ir anuo metu jums įsakiau, sakydamas: ‘VIEŠPATS, jūsų Dievas, davė jums šitą šalį, kad ją pasisavintumėte; pereikite apsiginklavę savo brolių Izraelio vaikų akivaizdoje visi, kurie esate tinkami karui.'),
  (@b5, 3, 19, 'Bet jūsų žmonos, jūsų mažyliai ir jūsų galvijai (nes aš žinau, kad turite daug galvijų) pasiliks jūsų miestuose, kuriuos esu jums davęs;'),
  (@b5, 3, 20, 'kol VIEŠPATS bus davęs poilsį jūsų broliams, kaip ir jums, ir kol jie irgi pasisavins šalį, kurią VIEŠPATS, jūsų Dievas, yra jiems davęs anapus Jordano; ir tuomet kiekvienas sugrįžkite į savo nuosavybę, kurią esu jums davęs.'),
  (@b5, 3, 21, 'Ir Jozuei anuo metu įsakiau, sakydamas: ‘Tavo akys matė viską, ką VIEŠPATS, jūsų Dievas, padarė šitiems dviems karaliams; taip VIEŠPATS padarys visoms karalystėms, į kurias tu eini.'),
  (@b5, 3, 22, 'Nebijokite jų; nes VIEŠPATS, jūsų Dievas, pats kariaus už jus’.'),
  (@b5, 3, 23, 'Ir anuo metu maldavau VIEŠPATĮ, sakydamas:'),
  (@b5, 3, 24, '‘O Viešpatie DIEVE, tu savo tarnui pradėjai rodyti savo didybę ir savo galingą ranką: nes koks yra danguje ar žemėje Dievas, kuris galėtų padaryti pagal tavo darbus ir pagal tavo galią?');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b5, 3, 25, 'Meldžiu tave, leisk man pereiti ir pamatyti tą gerąją šalį, esančią anapus Jordano, tą gražųjį kalną ir Libaną’.'),
  (@b5, 3, 26, 'Bet VIEŠPATS buvo užsirūstinęs ant manęs dėl jūsų ir nenorėjo manęs išklausyti; ir VIEŠPATS man tarė: ‘Gana tau; nekalbėk man daugiau apie šitą dalyką.'),
  (@b5, 3, 27, 'Užlipk į Pisgos viršūnę ir pakelk savo akis į vakarus, į šiaurę, į pietus ir į rytus, ir pamatyk tai savo akimis; nes tu nepereisi per šitą Jordaną.'),
  (@b5, 3, 28, 'Bet įpareigok Jozuę, padrąsink ir pastiprink jį; nes jis pereis šitos tautos priešakyje ir padarys, kad jie paveldėtų šalį, kurią tu pamatysi’.'),
  (@b5, 3, 29, 'Taip mes pasilikome slėnyje priešais Bet-Peorą“.'),
  (@b5, 4, 1, '„Todėl dabar, o Izraeli, klausyk įstatų ir teismų, kurių jus mokau, kad juos vykdytumėte, kad gyventumėte ir įėję pasisavintumėte šalį, kurią VIEŠPATS, jūsų tėvų Dievas, jums duoda.'),
  (@b5, 4, 2, 'Nieko nepridėkite prie žodžio, kurį jums įsakau, nei nieko neatimkite iš jo, kad laikytumėtės VIEŠPATIES, jūsų Dievo, įsakymų, kuriuos jums įsakau.'),
  (@b5, 4, 3, 'Jūsų akys matė, ką VIEŠPATS padarė dėl Baal-Peoro; nes visus sekusius paskui Baal-Peorą, VIEŠPATS, tavo Dievas, išnaikino iš jūsų tarpo.'),
  (@b5, 4, 4, 'Bet jūs, kurie prilipote prie VIEŠPATIES, savo Dievo, šiandien visi esate gyvi.'),
  (@b5, 4, 5, 'Štai aš jus išmokiau įstatų ir teismų, kaip man įsakė VIEŠPATS, mano Dievas, kad taip darytumėte šalyje, į kurią einate jos pasisavinti.'),
  (@b5, 4, 6, 'Todėl laikykitės jų ir juos vykdykite; nes tai yra jūsų išmintis ir jūsų supratimas akyse tautų, kurios, išgirdusios visus šituos įstatus, sakys: ‘Tikrai šita didelė tauta yra išmintinga ir supratinga liaudis’.'),
  (@b5, 4, 7, 'Kuri gi yra tokia didelė tauta, kuri turi Dievą taip arti prie jos, kaip VIEŠPATS, mūsų Dievas, yra visuose dalykuose, dėl kurių mes jo šaukiamės?'),
  (@b5, 4, 8, 'Ir kuri gi yra tokia didelė tauta, kuri turi tokių teisingų įstatų ir teismų, kaip visas šitas įstatymas, kurį šią dieną išstatau jūsų akivaizdon?'),
  (@b5, 4, 9, 'Tik žiūrėk savęs ir stropiai saugok savo sielą, kad nepamirštum tų dalykų, kuriuos matė tavo akys, ir kad jie neatsitrauktų nuo tavo širdies per visas tavo gyvenimo dienas; bet jų mokyk savo sūnus ir savo sūnų sūnus;'),
  (@b5, 4, 10, 'ypatingai tos dienos, kurią stovėjai VIEŠPATIES, savo Dievo, akivaizdoje Horebe, kai VIEŠPATS man sakė: ‘Surink man tautą, o aš jiems duosiu išgirsti savo žodžius, kad jie išmoktų bijoti manęs per visas dienas, kurias jie gyvens žemėje, ir kad jie mokytų savo vaikus’.'),
  (@b5, 4, 11, 'Ir priartėję jūs sustojote kalno apačioje; o kalnas degė ugnimi iki dangaus vidurio, ir buvo tamsa, debesys ir tiršta tamsa.'),
  (@b5, 4, 12, 'Ir VIEŠPATS kalbėjo jums iš ugnies vidurio; žodžių balsą girdėjote, bet pavidalo nematėte; girdėjote tik balsą.'),
  (@b5, 4, 13, 'Ir jis paskelbė jums savo sandorą, kurią jis jums įsakė vykdyti, tai yra dešimt įsakymų; ir jis užrašė juos dviejose akmeninėse plokštėse.'),
  (@b5, 4, 14, 'Ir anuo metu VIEŠPATS man įsakė jus mokyti įstatų ir teismų, kad vykdytumėte juos toje šalyje, į kurią einate jos pasisavinti.'),
  (@b5, 4, 15, 'Todėl labai žiūrėkite savęs; nes jūs nematėte jokio pavidalo tą dieną, kai VIEŠPATS jums kalbėjo Horebe iš ugnies vidurio;'),
  (@b5, 4, 16, 'kad nesugestumėte ir nepasidarytumėte raižyto atvaizdo, kokios statulos pavidalo, vyriškos ar moteriškos lyties panašumo,'),
  (@b5, 4, 17, 'kokio nors gyvulio, esančio žemėje, panašumo, kokio nors ore skrajojančio sparnuoto skrajūno panašumo,'),
  (@b5, 4, 18, 'kokio nors ant žemės ropojančio padaro panašumo, kokios nors vandenyse, po žeme, esančios žuvies panašumo;'),
  (@b5, 4, 19, 'ir kad nepakeltum savo akių į dangų ir, pamatęs saulę, mėnulį ir žvaigždes, tai yra visą dangaus kariuomenę, nebūtum vedamas jų garbinti ir jiems tarnauti, kuriuos VIEŠPATS, tavo Dievas, padalijo visoms tautoms po visu dangumi.'),
  (@b5, 4, 20, 'Bet VIEŠPATS paėmė jus ir išvedė iš geležies krosnies, tai yra iš Egipto, kad jam būtumėte paveldo tauta, kaip kad šią dieną esate.'),
  (@b5, 4, 21, 'Be to, VIEŠPATS supyko ant manęs dėl jūsų ir prisiekė, kad aš nepereisiu per Jordaną ir neįeisiu į tą gerą šalį, kurią VIEŠPATS, tavo Dievas, tau duoda kaip paveldą;'),
  (@b5, 4, 22, 'bet aš turiu mirti šioje šalyje, man negalima pereiti per Jordaną; bet jūs pereisite ir pasisavinsite tą gerą šalį.'),
  (@b5, 4, 23, 'Žiūrėkite savęs, kad nepamirštumėte VIEŠPATIES, savo Dievo, sandoros, kurią jis sudarė su jumis, ir kad nepasidirbtumėte raižyto atvaizdo ar kieno tai panašumo, ką VIEŠPATS, tavo Dievas, yra tau uždraudęs.'),
  (@b5, 4, 24, 'Nes VIEŠPATS, tavo Dievas, yra ryjanti ugnis – pavydulingas Dievas.'),
  (@b5, 4, 25, 'Kai pagimdysi vaikus ir vaikų vaikus, ir ilgai išliksite toje šalyje, ir sugesite, ir pasidirbsite raižytą atvaizdą ar kieno tai panašumą, ir darysite pikta VIEŠPATIES savo Dievo akyse jį pykdydami;'),
  (@b5, 4, 26, 'tai aš šaukiu dangų ir žemę liudyti šią dieną prieš jus, kad greitai visiškai pražūsite iš šalies, į kurią einate per Jordaną jos pasisavinti; jūs neprailginsite joje savo dienų, bet visiškai būsite sunaikinti.'),
  (@b5, 4, 27, 'Ir VIEŠPATS jus išsklaidys tarp tautų, ir jūsų teišliks mažas skaičius tarp pagonių, pas kuriuos VIEŠPATS jus nuves.'),
  (@b5, 4, 28, 'Ir ten tarnausite dievams, padarytiems žmonių rankomis, medžiui ir akmeniui, kurie nei mato, nei girdi, nei valgo, nei užuodžia.'),
  (@b5, 4, 29, 'Bet jei iš ten ieškosi VIEŠPATIES, savo Dievo, tu jį rasi, jei ieškosi jo visa savo širdimi ir visa savo siela.'),
  (@b5, 4, 30, 'Kai būsi suspaudime ir tave ištiks visi šitie dalykai, būtent paskutinėmis dienomis, jei tu atsigręši į VIEŠPATĮ, savo Dievą, ir paklusi jo balsui'),
  (@b5, 4, 31, '(nes VIEŠPATS, tavo Dievas, yra gailestingas Dievas); jis tavęs nepaliks ir tavęs nesunaikins nei nepamirš tavo tėvų sandoros, kurią jis jiems prisiekė.'),
  (@b5, 4, 32, 'Nes dabar paklausk praeities dienų, buvusių pirma tavęs, nuo tos dienos, kai Dievas sutvėrė žmogų žemėje, ir paklausk nuo vieno dangaus krašto iki kito, ar yra buvęs toks didelis dalykas, kaip šitas, ar kas panašaus girdėta?'),
  (@b5, 4, 33, 'Ar kada nors girdėjo kokia tauta Dievo balsą, kalbantį iš ugnies vidurio, kaip tu girdėjai, ir liko gyva?'),
  (@b5, 4, 34, 'Arba ar Dievas bandė eiti, pasiimti sau tautą iš kitos tautos tarpo su gundymais, ženklais ir stebuklais, karu, galinga ranka bei ištiesta ranka ir su dideliais siaubais, pagal visa tai, ką VIEŠPATS, jūsų Dievas, jums padarė Egipte jūsų akyse?'),
  (@b5, 4, 35, 'Tau tai buvo parodyta, kad žinotum, jog VIEŠPATS, jis yra Dievas; be jo nėra kito.'),
  (@b5, 4, 36, 'Iš dangaus jis davė tau išgirsti savo balsą, kad tave pamokytų; o žemėje jis tau parodė savo didžią ugnį; ir jo žodžius išgirdai iš ugnies vidurio.'),
  (@b5, 4, 37, 'Ir kadangi jis mylėjo tavo tėvus, todėl išsirinko jų sėklą po jų ir išvedė tave savo akivaizdoje iš Egipto savo galinga jėga;'),
  (@b5, 4, 38, 'kad išvarytų iš tavo akivaizdos tautas, didesnes ir galingesnes už tave, kad tave įvestų, kad tau duotų jų šalį paveldui, kaip yra šią dieną.'),
  (@b5, 4, 39, 'Todėl šią dieną žinok ir apsvarstyk tai savo širdyje, kad VIEŠPATS, jis yra Dievas aukštai danguje ir žemai žemėje; kito nėra.'),
  (@b5, 4, 40, 'Todėl laikykis jo įstatų ir jo įsakymų, kuriuos tau šią dieną įsakau, kad gerai sektųsi tau ir tavo vaikams po tavęs ir kad prailgintum savo dienas žemėje, kurią VIEŠPATS, tavo Dievas, tau duoda amžiams“.'),
  (@b5, 4, 41, 'Tada Mozė atskyrė tris miestus šiapus Jordano saulėtekio link;'),
  (@b5, 4, 42, 'kad ten galėtų pabėgti užmušėjas, kuris netyčia būtų užmušęs savo artimą, bet praeityje nejautęs jam neapykantos; ir kad jis, pabėgęs į vieną iš šitų miestų, gyventų:'),
  (@b5, 4, 43, 'Becerą dykumoje, lygumos šalyje, iš rubenų; o Ramotą Gileade iš gadų; o Golaną Bašane iš manasų.'),
  (@b5, 4, 44, 'Ir šitas yra įstatymas, kurį Mozė pateikė Izraelio vaikų akivaizdon;'),
  (@b5, 4, 45, 'šitie yra liudijimai, įstatai ir teismai, kuriuos Mozė kalbėjo Izraelio vaikams, jiems išėjus iš Egipto,'),
  (@b5, 4, 46, 'šioje Jordano pusėje, slėnyje priešais Bet-Peorą, šalyje amoritų karaliaus Sihono, gyvenusio Hešbone, kurį sumušė Mozė ir Izraelio vaikai, kai jie buvo išėję iš Egipto;'),
  (@b5, 4, 47, 'ir jie pasisavino jo šalį ir Bašano karaliaus Ogo šalį, dviejų amoritų karalių, buvusių šiapus Jordano saulėtekio link:'),
  (@b5, 4, 48, 'nuo Aroerio, esančio prie Arnono upės kranto, iki Siono kalno, kuris yra Hermonas,'),
  (@b5, 4, 49, 'ir visą lygumą šioje Jordano pusėje į rytus iki Lygumos jūros, Pisgos šaltinių apačioje.'),
  (@b5, 5, 1, 'Ir Mozė sušaukė visą Izraelį ir jiems tarė: „Klausyk, o Izraeli, įstatų ir teismų, kuriuos šią dieną kalbu jums į ausis, kad jų išmoktumėte, jų laikytumėtės ir juos vykdytumėte.'),
  (@b5, 5, 2, 'VIEŠPATS, mūsų Dievas, sudarė su mumis sandorą Horebe.'),
  (@b5, 5, 3, 'Ne su mūsų tėvais VIEŠPATS sudarė šitą sandorą, bet su mumis, tai yra su mumis, kurie čia visi šią dieną esame gyvi.'),
  (@b5, 5, 4, 'Veidas į veidą VIEŠPATS kalbėjo su jumis kalne iš ugnies vidaus'),
  (@b5, 5, 5, '(aš anuomet stovėjau tarp VIEŠPATIES ir jūsų, kad jums išdėstyčiau VIEŠPATIES žodį; nes jūs bijojote dėl ugnies ir nelipote į kalną), sakydamas:'),
  (@b5, 5, 6, '‘Aš esu VIEŠPATS, tavo Dievas, kuris tave išvedžiau iš Egipto šalies, iš vergystės namų.'),
  (@b5, 5, 7, 'Neturėk kitų dievų mano akivaizdoje.'),
  (@b5, 5, 8, 'Nesidaryk sau jokio raižyto atvaizdo ar kokio nors panašumo to, kas yra aukštai danguje ar kas žemai žemėje, ar kas vandenyse po žeme;'),
  (@b5, 5, 9, 'jiems nesilenk nei jiems tarnauk; nes aš, VIEŠPATS, tavo Dievas, esu pavydulingas Dievas, aplankantis tėvų kaltę ant vaikų iki trečios ir ketvirtos kartos tų, kurie nekenčia manęs,'),
  (@b5, 5, 10, 'ir rodantis gailestingumą tūkstančiams tų, kurie mane myli ir laikosi mano įsakymų.'),
  (@b5, 5, 11, 'Tuščiai nevartok VIEŠPATIES, savo Dievo, vardo; nes VIEŠPATS nelaikys nekaltu to, kuris tuščiai vartoja jo vardą.'),
  (@b5, 5, 12, 'Švęsk sabato dieną, kad ją pašvęstum, kaip VIEŠPATS, tavo Dievas, yra tau įsakęs.'),
  (@b5, 5, 13, 'Šešias dienas dirbk ir daryk visą savo darbą;'),
  (@b5, 5, 14, 'bet septintoji diena yra VIEŠPATIES, tavo Dievo, sabatas; joje nedirbk jokio darbo nei tu, nei tavo sūnus, nei tavo duktė, nei tavo tarnas, nei tavo tarnaitė, nei tavo jautis, nei tavo asilas, nei joks tavo galvijas, nei tavo ateivis, esantis tavo vartuose; kad tavo tarnas ir tavo tarnaitė ilsėtųsi taip pat, kaip ir tu.'),
  (@b5, 5, 15, 'Ir prisimink, kad tu buvai tarnas Egipto šalyje, ir kad VIEŠPATS, tavo Dievas, tave išvedė iš ten galinga ranka ir ištiesta ranka; todėl VIEŠPATS, tavo Dievas, tau įsakė švęsti sabato dieną.'),
  (@b5, 5, 16, 'Gerbk savo tėvą ir savo motiną, kaip VIEŠPATS, tavo Dievas, yra tau įsakęs; kad būtų prailgintos tavo dienos, ir kad tau gerai sektųsi šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda.'),
  (@b5, 5, 17, 'Nežudyk.'),
  (@b5, 5, 18, 'Nei nesvetimauk.'),
  (@b5, 5, 19, 'Nei nevok.'),
  (@b5, 5, 20, 'Nei melagingai neliudyk prieš savo artimą.'),
  (@b5, 5, 21, 'Nei negeisk savo artimo žmonos, nei negeisk savo artimo namų, jo lauko ar jo tarno, ar jo tarnaitės, jo jaučio ar jo asilo, ar ko nors, kas yra tavo artimo’.'),
  (@b5, 5, 22, 'Šituos žodžius VIEŠPATS kalbėjo didžiu balsu visam jūsų susirinkimui kalne iš vidurio ugnies, iš debesies ir iš tirštos tamsos; ir jis nieko daugiau nepridėjo. Ir jis juos užrašė dviejose akmens plokštėse ir įteikė jas man.'),
  (@b5, 5, 23, 'Ir įvyko, kad išgirdę balsą iš tamsos vidurio (nes kalnas degė ugnimi), jūs, visos jūsų genčių galvos ir jūsų vyresnieji, priėjote prie manęs;'),
  (@b5, 5, 24, 'ir sakėte: ‘Štai VIEŠPATS, mūsų Dievas, mums parodė savo šlovę ir savo didybę, ir mes girdėjome jo balsą iš ugnies vidurio; šią dieną pamatėme, kad Dievas kalba su žmogumi, ir tas lieka gyvas.'),
  (@b5, 5, 25, 'Taigi dabar, kodėl turėtume mirti? Nes šita didelė ugnis mus praris; jei dar ilgiau klausysimės VIEŠPATIES, mūsų Dievo, balso, tuomet mirsime.'),
  (@b5, 5, 26, 'Nes kas yra iš visų kūnų išgirdęs, kaip mes, gyvojo Dievo balsą, kalbančio iš ugnies vidurio, ir išlikęs gyvas?'),
  (@b5, 5, 27, 'Priartėk ir išgirsk viską, ką VIEŠPATS, mūsų Dievas, sakys; ir mums kalbėk viską, ką VIEŠPATS, mūsų Dievas, tau kalbės; o mes klausysime to ir tai vykdysime’.'),
  (@b5, 5, 28, 'Ir VIEŠPATS girdėjo jūsų žodžių balsą, kai man kalbėjote; ir VIEŠPATS man tarė: ‘Aš girdėjau šios tautos žodžių balsą, kuriuos jie tau kalbėjo; jie gerai sakė viską, ką jie kalbėjo.'),
  (@b5, 5, 29, 'O kad juose būtų tokia širdis, kad jie visada bijotų manęs ir visada laikytųsi visų mano įsakymų, kad gerai sektųsi jiems ir jų vaikams per amžius!'),
  (@b5, 5, 30, 'Eik, jiems sakyk: „Sugrįžkite į savo palapines“.'),
  (@b5, 5, 31, 'Bet kas dėl tavęs, atsistok čia prie manęs, o aš tau kalbėsiu visus įsakymus, įstatus ir teismus, kurių juos išmokyk, kad jie juos vykdytų šalyje, kurią duodu jiems pasisavinti’.'),
  (@b5, 5, 32, 'Todėl laikykitės, kad vykdytumėte, kaip VIEŠPATS, jūsų Dievas, yra jums įsakęs; nenukrypkite nei į dešinę, nei į kairę.'),
  (@b5, 5, 33, 'Vaikščiokite visais tais keliais, kuriuos VIEŠPATS, jūsų Dievas, yra jums įsakęs, kad gyventumėte, kad jums gerai sektųsi ir kad prailgintumėte savo dienas šalyje, kurią pasisavinsite“.'),
  (@b5, 6, 1, '„Na, o šitie yra įsakymai, įstatai ir teismai, kurių VIEŠPATS, jūsų Dievas, įsakė jus mokyti, kad juos vykdytumėte šalyje, į kurią jūs einate jos pasisavinti;'),
  (@b5, 6, 2, 'kad bijotum VIEŠPATIES, savo Dievo, idant laikytumeisi visų jo įstatų ir jo įsakymų, kuriuos įsakau tau, tu, tavo sūnus, tavo sūnaus sūnus per visas tavo gyvenimo dienas; ir kad tavo dienos būtų prailgintos.'),
  (@b5, 6, 3, 'Taigi klausyk, o Izraeli, ir laikykis, kad juos vykdytum; kad tau gerai sektųsi ir kad labai pagausėtumėte, kaip VIEŠPATS, tavo tėvų Dievas, yra tau pažadėjęs, šalyje plūstančioje pienu ir medumi.'),
  (@b5, 6, 4, 'Klausyk, o Izraeli: ‘VIEŠPATS, mūsų Dievas, yra vienas VIEŠPATS;'),
  (@b5, 6, 5, 'ir mylėk VIEŠPATĮ, savo Dievą, visa savo širdimi, visa savo siela ir visomis savo jėgomis.'),
  (@b5, 6, 6, 'Ir šitie žodžiai, kuriuos tau šią dieną įsakau, tebus tavo širdyje;'),
  (@b5, 6, 7, 'ir uoliai mokyk jų savo vaikus ir apie juos kalbėk, sėdėdamas savo namuose ir eidamas keliu, kai gulsiesi ir kai kelsiesi.'),
  (@b5, 6, 8, 'Ir pririšk juos kaip ženklą sau ant rankos, ir jie bus kaip galvaraištis tarp tavo akių.'),
  (@b5, 6, 9, 'Ir užrašyk juos ant savo namo staktų ir ant savo vartų.'),
  (@b5, 6, 10, 'Ir kai VIEŠPATS, tavo Dievas, bus tave įvedęs į tą šalį, kurią prisiekė tavo tėvams, Abraomui, Izaokui ir Jokūbui, tau duoti didelius ir gražius miestus, kurių nestatei,'),
  (@b5, 6, 11, 'ir visokių gėrybių pilnus namus, kurių nepripildei, iškastus šulinius, kurių nekasei, vynuogynus ir alyvmedžius, kurių nesodinai; kai būsi pavalgęs ir sotus;'),
  (@b5, 6, 12, 'tuomet saugokis, kad nepamirštum VIEŠPATIES, kuris tave išvedė iš Egipto šalies, iš vergystės namų.'),
  (@b5, 6, 13, 'Bijok VIEŠPATIES, savo Dievo, jam tarnauk ir prisiek jo vardu.'),
  (@b5, 6, 14, 'Nesekite paskui kitus dievus, dievus tautų, kurios yra aplink jus'),
  (@b5, 6, 15, '(nes VIEŠPATS, tavo Dievas, yra pavydulingas Dievas jūsų tarpe), kad neužsidegtų prieš tave VIEŠPATIES, tavo Dievo, pyktis, ir neišnaikintų tavęs nuo žemės paviršiaus.'),
  (@b5, 6, 16, 'Negundykite VIEŠPATIES, savo Dievo, kaip jį gundėte Masoje.'),
  (@b5, 6, 17, 'Uoliai laikykitės VIEŠPATIES, savo Dievo, įsakymų, jo liudijimų ir jo įstatų, kuriuos jis yra tau įsakęs.'),
  (@b5, 6, 18, 'Ir daryk tai, kas teisinga ir gera VIEŠPATIES akyse; kad tau gerai sektųsi, ir kad įeitum ir pasisavintum tą gerą šalį, kurią VIEŠPATS prisiekė tavo tėvams,'),
  (@b5, 6, 19, 'kad išvarys iš tavo akivaizdos visus tavo priešus, kaip VIEŠPATS yra pasakęs.'),
  (@b5, 6, 20, 'Ir kai ateinančiais laikais tavo sūnus paklaus tavęs, sakydamas: ‘Ką reiškia tie liudijimai, įstatai ir teismai, kuriuos VIEŠPATS, mūsų Dievas, yra jums įsakęs?’,'),
  (@b5, 6, 21, 'tuomet sakyk savo sūnui: ‘Mes buvome faraono vergai Egipte; o VIEŠPATS mus išvedė iš Egipto galinga ranka;'),
  (@b5, 6, 22, 'ir VIEŠPATS mūsų akyse parodė ženklų ir stebuklų, didelių ir skaudžių, ant Egipto, ant faraono ir ant visų jo namiškių;'),
  (@b5, 6, 23, 'ir jis mus išvedė iš ten, kad mus įvedęs, duotų mums šalį, kurią prisiekė mūsų tėvams.'),
  (@b5, 6, 24, 'Ir VIEŠPATS mums įsakė vykdyti visus šiuos įstatus, bijoti VIEŠPATIES, mūsų Dievo, mums dėl gero visiems laikams, kad jis išsaugotų mus gyvus, kaip yra šią dieną.'),
  (@b5, 6, 25, 'Ir tai bus mūsų teisumas, jei laikysimės, kad vykdytume visus šituos įsakymus VIEŠPATIES, mūsų Dievo, akivaizdoje, kaip jis yra mums įsakęs’“.'),
  (@b5, 7, 1, '„Kai VIEŠPATS, tavo Dievas, tave įves į šalį, į kurią eini jos pasisavinti, ir išvarys iš tavo akivaizdos daug tautų: hetitus, girgašus, amoritus, kanaaniečius, perizus, hivus ir jebusiečius, septynias tautas, didesnes ir galingesnes už tave;'),
  (@b5, 7, 2, 'ir kai VIEŠPATS, tavo Dievas, jas atiduos tavo akivaizdoje; tu jas sumušk, jas visiškai sunaikink; nesudaryk su jomis jokios sandoros nei neparodyk joms gailestingumo;'),
  (@b5, 7, 3, 'nei nesudaryk su jomis santuokų: savo dukters neduok jo sūnui nei jo dukters neimk savo sūnui,'),
  (@b5, 7, 4, 'nes jos nukreips tavo sūnų nuo sekimo paskui mane, kad tarnautų kitiems dievams; taip VIEŠPATIES pyktis užsidegs prieš jus, ir jis netikėtai sunaikins tave.'),
  (@b5, 7, 5, 'Bet šitaip pasielkite su jomis: sugriaukite jų aukurus, sudaužykite jų atvaizdus, iškirskite jų giraites, o jų raižytus atvaizdus sudeginkite ugnimi.'),
  (@b5, 7, 6, 'Nes tu esi VIEŠPAČIUI, savo Dievui, šventa tauta; VIEŠPATS, tavo Dievas, tave išsirinko, kad būtum jam ypatinga tauta virš visų tautų, esančių ant žemės paviršiaus.'),
  (@b5, 7, 7, 'VIEŠPATS pamilo jus ir jus išsirinko ne todėl, kad buvote gausesni už kitas tautas; nes jūs buvote mažiausia iš visų tautų;'),
  (@b5, 7, 8, 'bet todėl, kad VIEŠPATS jus pamilo ir kad jis ištesėtų priesaiką, kurią jis prisiekė jūsų tėvams, VIEŠPATS jus išvedė galinga ranka ir jus atpirko iš vergų namų, iš Egipto karaliaus faraono rankos.'),
  (@b5, 7, 9, 'Taigi žinok, kad VIEŠPATS, tavo Dievas, jis yra Dievas, ištikimas Dievas, išlaikantis sandorą ir gailestingumą iki tūkstančio kartų tiems, kurie jį myli ir laikosi jo įsakymų;'),
  (@b5, 7, 10, 'ir atlyginantis tiems, kurie jo nekenčia, jiems į akis, kad juos sunaikintų; jis nebus lėtas tam, kuris jo nekenčia, jis atlygins jam į akis.'),
  (@b5, 7, 11, 'Todėl laikykis įsakymų, įstatų ir teismų, kuriuos tau šią dieną įsakau, kad juos vykdytum.'),
  (@b5, 7, 12, 'Todėl įvyks, jei klausysite šitų teismų, jų laikysitės ir juos vykdysite, tai VIEŠPATS, tavo Dievas, išlaikys tau sandorą ir gailestingumą, kuriuos jis prisiekė tavo tėvams;'),
  (@b5, 7, 13, 'ir jis mylės tave, laimins tave ir daugins tave; taip pat jis laimins tavo įsčių vaisių ir tavo šalies vaisių, tavo javus, tavo vyną, tavo aliejų, tavo galvijų prieaugį ir tavo avių kaimenes šalyje, kurią jis prisiekė tavo tėvams tau duoti.'),
  (@b5, 7, 14, 'Tu būsi palaimintas labiau už visas tautas; nebus nevaisingo nei vyriškos, nei moteriškos lyties tarp jūsų ar tarp jūsų galvijų.'),
  (@b5, 7, 15, 'Ir VIEŠPATS pašalins nuo tavęs visas ligas ir neuždės ant tavęs jokios iš tau žinomų piktų Egipto ligų; bet jas uždės ant visų tų, kurie nekenčia tavęs.'),
  (@b5, 7, 16, 'Ir tu prarysi visas tautas, kurias VIEŠPATS, tavo Dievas, tau atiduos; tavo akis jų tenesigaili; nei netarnauk jų dievams; nes tai bus tau žabangos.'),
  (@b5, 7, 17, 'Jei sakysi savo širdyje: ‘Šitų tautų yra daugiau už mane; kaip aš galiu jas išvaryti iš jų nuosavybės?’,'),
  (@b5, 7, 18, 'nebijok jų; bet gerai prisimink, ką VIEŠPATS, tavo Dievas, padarė faraonui ir visam Egiptui:'),
  (@b5, 7, 19, 'dideles pagundas, kurias matė tavo akys, ženklus, stebuklus, galingą ranką ir ištiestą ranką, kuria VIEŠPATS, tavo Dievas, išvedė tave; taip VIEŠPATS, tavo Dievas, padarys visoms tautoms, kurių bijai.'),
  (@b5, 7, 20, 'Be to, VIEŠPATS, tavo Dievas, pasiųs į jų tarpą širšių, kol bus sunaikinti išlikusieji ir tie, kurie slepiasi nuo tavęs.'),
  (@b5, 7, 21, 'Neišsigąsk jų; nes VIEŠPATS, tavo Dievas, jūsų tarpe, galingas ir baisus Dievas.'),
  (@b5, 7, 22, 'Ir VIEŠPATS, tavo Dievas, pamažu išvarys šitas tautas tavo akivaizdoje; tu negalėsi jų sunaikinti iš karto, kad tau nepadaugėtų lauko žvėrių.'),
  (@b5, 7, 23, 'Bet VIEŠPATS, tavo Dievas, jas tau atiduos ir naikins jas galingu naikinimu, kol jos bus sunaikintos.'),
  (@b5, 7, 24, 'Ir jis atiduos jų karalius į tavo rankas, ir tu sunaikinsi jų vardą iš po dangaus; niekas nepajėgs prieš tave atsilaikyti, kol būsi jas sunaikinęs.'),
  (@b5, 7, 25, 'Raižytus jų dievų atvaizdus sudeginsite ugnimi; negeisk ant jų esančio sidabro ar aukso nei jų nepasiimk, kad į tai neįsipainiotum; nes tai yra pasibjaurėjimas VIEŠPAČIUI, tavo Dievui.'),
  (@b5, 7, 26, 'Taip pat neįnešk pasibjaurėjimo į savo namus, kad nebūtum prakeiktas dalykas kaip tas; bet juo visiškai šlykštėkis ir visiškai bjaurėkis; nes tai yra prakeikta“.'),
  (@b5, 8, 1, '„Laikykitės, kad vykdytumėte visus įsakymus, kuriuos šią dieną tau įsakau, kad gyventumėte, daugintumėtės, įeitumėte ir pasisavintumėte šalį, kurią VIEŠPATS prisiekė jūsų tėvams.'),
  (@b5, 8, 2, 'Ir atsimink visą tą kelią, kuriuo VIEŠPATS, tavo Dievas, tave vedė per tuos keturiasdešimt metų dykumoje, kad tave nužemintų ir išmėgintų, idant sužinotų, kas buvo tavo širdyje, ar laikysies jo įsakymų, ar ne.'),
  (@b5, 8, 3, 'Ir jis tave nužemino ir leido tau alkti ir tave maitino mana, kurios nepažinojai nei tu, nei nepažinojo tavo tėvai; kad jis tau duotų žinoti, kad žmogus negyvena vien duona, bet kad žmogus gyvena kiekvienu žodžiu, išeinančiu iš VIEŠPATIES burnos.'),
  (@b5, 8, 4, 'Tavo apdaras ant tavęs nepaseno nei tavo kojos nesutino per šituos keturiasdešimt metų.'),
  (@b5, 8, 5, 'Taip pat apsvarstyk savo širdyje, kad kaip žmogus pabaudžia savo sūnų, taip VIEŠPATS, tavo Dievas, pabaudžia tave.'),
  (@b5, 8, 6, 'Taigi laikykis VIEŠPATIES, savo Dievo, įsakymų, kad vaikščiotum jo keliais ir jo bijotum.'),
  (@b5, 8, 7, 'Nes VIEŠPATS, tavo Dievas, tave įveda į gerą šalį, į šalį vandens upelių, šaltinių ir gelmių, išsiveržiančių iš slėnių ir kalvų;'),
  (@b5, 8, 8, 'į kviečių, miežių, vynmedžių, figmedžių ir granatmedžių šalį; į aliejingų alyvmedžių ir medaus šalį;'),
  (@b5, 8, 9, 'į šalį, kurioje valgysi duonos be nepritekliaus, joje tau nieko nestigs; į šalį, kurios akmenys yra geležis, ir iš kurios kalvų gali kasti varį.'),
  (@b5, 8, 10, 'Kai pavalgysi ir pasisotinsi, tuomet laiminsi VIEŠPATĮ, savo Dievą, už gerą šalį, kurią jis tau yra davęs.'),
  (@b5, 8, 11, 'Saugokis, kad nepamirštum VIEŠPATIES, savo Dievo, nesilaikydamas jo įsakymų, jo teismų ir jo įstatų, kuriuos šią dieną tau įsakau;'),
  (@b5, 8, 12, 'kad, kai pavalgysi ir pasisotinsi, ir būsi pasistatęs gražių namų ir juose apsigyvenęs;'),
  (@b5, 8, 13, 'kai tavo bandos ir kaimenės padaugės, tavo sidabras ir auksas padaugės, ir visa, ką turi, padaugės;'),
  (@b5, 8, 14, 'kad tada nepasididžiuotų tavo širdis ir tu nepamirštum VIEŠPATIES, savo Dievo, kuris tave išvedė iš Egipto šalies, iš vergystės namų;'),
  (@b5, 8, 15, 'kuris tave vedė per tą didžiulę ir baisią dykumą, kurioje buvo ugningų gyvačių, skorpionų ir sausra, kur nebuvo vandens; kuris tau išgavo vandens iš titnago uolos;'),
  (@b5, 8, 16, 'kuris tave maitino dykumoje mana, kurios nepažinojo tavo tėvai, idant jis tave pažemintų ir tave išmėgintų, kad tau padarytų gera tavo pabaigoje;'),
  (@b5, 8, 17, 'ir tu nesakytum savo širdyje: ‘Mano jėga ir mano rankos galia man įgijo šitą turtą’.'),
  (@b5, 8, 18, 'Bet atsimink VIEŠPATĮ, savo Dievą; nes tai jis, kuris tau duoda jėgą turtui įgyti, kad jis įtvirtintų savo sandorą, kurią prisiekė tavo tėvams, kaip yra šią dieną.'),
  (@b5, 8, 19, 'Ir bus, jei visiškai pamirši VIEŠPATĮ, savo Dievą, ir vaikščiosi paskui kitus dievus, jiems tarnausi ir juos garbinsi, aš liudiju šią dieną prieš jus, kad tikrai žūsite.'),
  (@b5, 8, 20, 'Kaip tautos, kurias VIEŠPATS naikina jūsų akyse, taip ir jūs pražūsite; dėl to, kad nenorėjote paklusti VIEŠPATIES, savo Dievo, balsui“.'),
  (@b5, 9, 1, '„Klausyk, o Izraeli; tu šią dieną pereisi per Jordaną, kad įeitum užvaldyti tautų, didesnių ir galingesnių už save, miestų didelių ir aptvertų iki dangaus,'),
  (@b5, 9, 2, 'didelės ir aukštaūgės tautos, anakų vaikų, kuriuos žinai ir apie kuriuos girdėjai sakant: ‘Kas gali atsilaikyti prieš Anako vaikus?!’'),
  (@b5, 9, 3, 'Taigi šią dieną suprask, kad VIEŠPATS, tavo Dievas, yra tas, kuris pereina pirma tavęs; kaip ryjanti ugnis jis juos sunaikins, ir jis juos parblokš tavo akyse; taip tu juos greitai išvarysi ir sunaikinsi, kaip VIEŠPATS yra tau pasakęs.'),
  (@b5, 9, 4, 'Po to, kai VIEŠPATS, tavo Dievas, juos išvarys iš tavo akivaizdos, nekalbėk savo širdyje, sakydamas: ‘Dėl mano teisumo VIEŠPATS mane įvedė šitos šalies pasisavinti’; bet dėl šitų tautų nedorumo VIEŠPATS jas išvaro iš tavo akivaizdos.'),
  (@b5, 9, 5, 'Ne dėl savo teisumo ar savo širdies tiesumo eini jų šalies pasisavinti; bet dėl šitų tautų nedorumo VIEŠPATS, tavo Dievas, jas išvaro iš tavo akivaizdos, ir kad įvykdytų žodį, kurį VIEŠPATS prisiekė tavo tėvams, Abraomui, Izaokui ir Jokūbui.'),
  (@b5, 9, 6, 'Todėl suprask, kad ne dėl tavo teisumo VIEŠPATS, tavo Dievas, tau duoda pasisavinti šitą gerą šalį; nes tu kietasprandė tauta.'),
  (@b5, 9, 7, 'Atsimink ir nepamiršk, kaip tu kurstei VIEŠPATIES, savo Dievo, rūstybę dykumoje; nuo tos dienos, kai išėjai iš Egipto šalies, kol atėjote į šitą vietą, jūs buvote maištingi prieš VIEŠPATĮ.'),
  (@b5, 9, 8, 'Taip pat Horebe taip užrūstinote VIEŠPATĮ, kad VIEŠPATS supyko ant jūsų, idant jus sunaikintų.'),
  (@b5, 9, 9, 'Kai užlipau į kalną priimti akmens plokščių, tai yra plokščių sandoros, kurią VIEŠPATS sudarė su jumis, tada aš pasilikau kalne keturiasdešimt dienų ir keturiasdešimt naktų, nevalgiau duonos nei negėriau vandens;'),
  (@b5, 9, 10, 'o VIEŠPATS man įteikė dvi akmens plokštes, užrašytas Dievo pirštu; ir jose buvo surašyta pagal visus tuos žodžius, kuriuos VIEŠPATS susirinkimo dieną jums kalbėjo kalne iš ugnies vidurio.'),
  (@b5, 9, 11, 'Ir įvyko, kad, pasibaigus keturiasdešimčiai dienų ir keturiasdešimčiai naktų, VIEŠPATS man davė dvi akmens plokštes – sandoros plokštes.'),
  (@b5, 9, 12, 'Ir VIEŠPATS man tarė: ‘Kelkis, skubiai lipk žemyn iš čia; nes tavo tauta, kurią išvedei iš Egipto, sugedo; jie greitai nukrypo nuo to kelio, kurį jiems įsakiau: jie pasidirbo nulietą atvaizdą’.'),
  (@b5, 9, 13, 'VIEŠPATS man dar kalbėjo, sakydamas: ‘Aš mačiau šitą tautą, ir štai, tai kietasprandė tauta;'),
  (@b5, 9, 14, 'palik mane, kad juos sunaikinčiau ir išdildyčiau jų vardą iš po dangaus; o iš tavęs padarysiu tautą, galingesnę ir didesnę už juos’.'),
  (@b5, 9, 15, 'Taigi aš pasisukau ir nulipau nuo kalno, o kalnas degė ugnimi; ir mano abiejose rankose buvo dvi sandoros plokštės.'),
  (@b5, 9, 16, 'Ir aš pažiūrėjau, ir štai jūs buvote nusidėję VIEŠPAČIUI, savo Dievui, ir pasidirbote nulietą veršį; jūs greitai nukrypote nuo to kelio, kurį VIEŠPATS jums buvo įsakęs.'),
  (@b5, 9, 17, 'Ir paėmęs abi plokštes, aš jas išmečiau iš abiejų savo rankų ir sudaužiau jas jūsų akyse.'),
  (@b5, 9, 18, 'Ir parpuoliau VIEŠPATIES akivaizdoje, kaip pirmąjį kartą, keturiasdešimt dienų ir keturiasdešimt naktų; aš nei valgiau duonos, nei gėriau vandens dėl visų jūsų nuodėmių, kuriomis nusidėjote, darydami pikta VIEŠPATIES akyse, kurstydami jam pyktį.'),
  (@b5, 9, 19, 'Nes aš bijojausi pykčio ir įniršio, kuriuo VIEŠPATS buvo užsirūstinęs ant jūsų, kad jus sunaikintų. Bet ir tą kartą VIEŠPATS išklausė mane.'),
  (@b5, 9, 20, 'Ir ant Aarono VIEŠPATS buvo labai supykęs, kad jį sunaikintų; ir tuo metu meldžiausi ir už Aaroną.'),
  (@b5, 9, 21, 'Ir paėmiau jūsų nuodėmę, veršį, kurį buvote padarę, ir jį sudeginau ugnimi, jį sutrypiau, labai smulkiai sutryniau – iki jis buvo smulkus kaip dulkė; ir jo dulkes subėriau į upelį, nutekantį nuo kalno.'),
  (@b5, 9, 22, 'Ir Taberoje, Masoje ir Kibrot-Hataavoje jūs kurstėte VIEŠPATIES rūstybę.'),
  (@b5, 9, 23, 'Taip pat, kai VIEŠPATS jus siuntė iš Kadeš-Barnėjos, sakydamas: ‘Eikite aukštyn ir pasisavinkite šalį, kurią jums daviau’, jūs maištavote prieš VIEŠPATIES, savo Dievo, įsakymą, netikėjote juo nei neklausėte jo balso.'),
  (@b5, 9, 24, 'Jūs buvote maištaujantys prieš VIEŠPATĮ nuo tos dienos, kai jus pažinau’.'),
  (@b5, 9, 25, 'Taip aš išbuvau parpuolęs VIEŠPATIES akivaizdoje keturiasdešimt dienų ir keturiasdešimt naktų, kaip aš pirmą kartą parpuoliau; nes VIEŠPATS buvo sakęs, kad nori jus sunaikinti.'),
  (@b5, 9, 26, 'Todėl meldžiausi VIEŠPAČIUI ir tariau: ‘O Viešpatie DIEVE, nesunaikink savo tautos ir savo paveldo, kurį atpirkai savo didybe, kurį išvedei iš Egipto galinga ranka.'),
  (@b5, 9, 27, 'Atsimink savo tarnus Abraomą, Izaoką ir Jokūbą; nežiūrėk į šitos tautos užsispyrimą nei į jų piktybę, nei į jų nuodėmę;'),
  (@b5, 9, 28, 'kad šalis, iš kurios mus išvedei, nesakytų: „Kadangi VIEŠPATS nepajėgė jų įvesti į šalį, kurią jiems pažadėjo, ir kadangi jų nekentė, išvedė juos išžudyti dykumoje“.'),
  (@b5, 9, 29, 'Tačiau jie yra tavo tauta ir tavo paveldas, kurį išvedei savo galinga jėga ir savo ištiesta ranka’“.'),
  (@b5, 10, 1, '„Anuo metu VIEŠPATS man tarė: ‘Išsikalk dvi akmens plokštes, tokias kaip pirmosios, ir užlipk pas mane į kalną, ir pasidirbk medinę skrynią.'),
  (@b5, 10, 2, 'O aš užrašysiu ant plokščių žodžius, kurie buvo pirmosiose plokštėse, kurias sudaužei, ir įdėk jas į skrynią’.'),
  (@b5, 10, 3, 'Ir aš padariau iš šitimo medžio skrynią ir iškaliau dvi akmens plokštes, tokias kaip pirmosios, ir užlipau į kalną, turėdamas savo rankoje abi plokštes.'),
  (@b5, 10, 4, 'Ir jis užrašė ant plokščių pagal pirmąjį raštą, dešimt įsakymų, kuriuos VIEŠPATS susirinkimo dieną jums kalbėjo kalne iš ugnies vidurio; ir VIEŠPATS man davė juos.'),
  (@b5, 10, 5, 'Ir atsigręžęs aš nulipau nuo kalno ir įdėjau plokštes į skrynią, kurią buvau padaręs; ir ten jos yra, kaip man VIEŠPATS įsakė.'),
  (@b5, 10, 6, 'Ir Izraelio vaikai leidosi kelionėn iš Jaakano vaikų Beroto į Moserą; ten mirė Aaronas ir ten jis buvo palaidotas; o jo sūnus Eleazaras tarnavo jo vietoje kunigo tarnystėje.'),
  (@b5, 10, 7, 'Iš ten jie keliavo į Gudgodą; o iš Gudgodos į Jotbatą, vandenų upių šalį.'),
  (@b5, 10, 8, 'Anuo metu VIEŠPATS išskyrė Levio gentį, kad nešiotų VIEŠPATIES Sandoros skrynią, kad stovėtų VIEŠPATIES akivaizdoje jam tarnauti ir laiminti jo vardu iki šios dienos.'),
  (@b5, 10, 9, 'Todėl Levis neturi dalies nei paveldo su savo broliais: VIEŠPATS yra jo paveldas – pagal tai, kaip VIEŠPATS, tavo Dievas, jam pažadėjo.'),
  (@b5, 10, 10, 'Ir aš stovėjau kalne, kaip pirmąjį kartą, keturiasdešimt dienų ir keturiasdešimt naktų; ir VIEŠPATS išklausė mane ir anuo metu, ir VIEŠPATS nenorėjo tavęs sunaikinti.'),
  (@b5, 10, 11, 'Ir VIEŠPATS man tarė: ‘Kelkis, leiskis į kelionę tautos priešakyje, kad jie įeitų ir pasisavintų šalį, kurią jų tėvams prisiekiau jiems duoti’.'),
  (@b5, 10, 12, 'O dabar, Izraeli, ko VIEŠPATS, tavo Dievas, reikalauja iš tavęs, tai tik bijoti VIEŠPATIES, savo Dievo, vaikščioti visais jo keliais, jį mylėti ir tarnauti VIEŠPAČIUI, savo Dievui, visa savo širdimi ir visa savo siela,'),
  (@b5, 10, 13, 'laikytis VIEŠPATIES įsakymų ir jo įstatų, kuriuos šią dieną tau įsakau tavo labui.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b5, 10, 14, 'Štai dangus ir dangų dangus yra VIEŠPATIES, tavo Dievo, taip pat žemė ir visa, kas joje.'),
  (@b5, 10, 15, 'VIEŠPATS tik gėrėjosi tavo tėvais, kad juos mylėtų, ir jis išrinko jų sėklą po jų, tai yra jus, virš visų tautų, kaip yra šią dieną.'),
  (@b5, 10, 16, 'Todėl apipjaustykite savo širdies prieodę ir nebebūkite kietasprandžiai.'),
  (@b5, 10, 17, 'Nes VIEŠPATS, jūsų Dievas, yra dievų Dievas ir viešpačių Viešpats, didis Dievas, galingas ir baisus, kuris neatsižvelgia į asmenis nei neima užmokesčio;'),
  (@b5, 10, 18, 'jis vykdo teismą našlaičių ir našlių, myli ateivį, duodamas jam maisto ir drabužį.'),
  (@b5, 10, 19, 'Todėl mylėkite ateivį; nes jūs buvote ateiviai Egipto šalyje.'),
  (@b5, 10, 20, 'Bijok VIEŠPATIES, savo Dievo; jam tarnauk ir prie jo prilipk, ir prisiek jo vardu.'),
  (@b5, 10, 21, 'Jis yra tavo gyrius ir jis yra tavo Dievas, kuris tau padarė šitų didelių ir baisių dalykų, kuriuos matė tavo akys.'),
  (@b5, 10, 22, 'Tavo tėvai su septyniasdešimčia asmenų nusileido į Egiptą; o dabar VIEŠPATS, tavo Dievas, yra padaręs tave tokia daugybe, kaip dangaus žvaigždės“.'),
  (@b5, 11, 1, '„Todėl nuolat mylėk VIEŠPATĮ, savo Dievą, ir laikykis jo įpareigojimo, jo įstatų, jo teismų ir jo įsakymų.'),
  (@b5, 11, 2, 'Ir žinokite šią dieną; nes aš kalbu ne su jūsų vaikais, kurie nepažino ir nematė VIEŠPATIES, jūsų Dievo, bausmės, jo didybės, jo galingos rankos ir jo ištiestos rankos,'),
  (@b5, 11, 3, 'jo stebuklų ir jo darbų, kuriuos jis padarė vidury Egipto faraonui, Egipto karaliui, ir visai jo šaliai;'),
  (@b5, 11, 4, 'ir ką jis padarė Egipto kariuomenei, jų žirgams ir jų vežimams; kaip jis padarė, kad Raudonosios jūros vanduo juos užplūstų jiems vejantis jus, ir kaip VIEŠPATS juos sunaikino iki šios dienos;'),
  (@b5, 11, 5, 'ir ką jis padarė jums dykumoje, kol atėjote į šią vietą;'),
  (@b5, 11, 6, 'ir ką jis padarė Datanui ir Abiramui, Rubeno sūnaus Eliabo sūnums; kaip žemė atvėrė savo burną ir juos prarijo su jų namiškiais, jų palapinėmis ir visa jų turima nuosavybe, viso Izraelio viduryje;'),
  (@b5, 11, 7, 'bet jūsų akys matė visus didžius VIEŠPATIES darbus, kuriuos jis padarė.'),
  (@b5, 11, 8, 'Todėl laikykitės visų įsakymų, kuriuos jums šią dieną įsakau, kad būtumėte stiprūs ir įeitumėte, ir pasisavintumėte šalį, į kurią einate jos pasisavinti;'),
  (@b5, 11, 9, 'ir kad prailgintumėte savo dienas šalyje, kurią VIEŠPATS jūsų tėvams prisiekė duoti jiems ir jų sėklai, šalį, plūstančią pienu ir medumi.'),
  (@b5, 11, 10, 'Nes ta šalis, į kurią įeini jos pasisavinti, nėra kaip Egipto šalis, iš kurios išėjote, kurioje sėjai savo sėklą, drėkinai ją savo koja kaip žolių daržą;'),
  (@b5, 11, 11, 'bet ta šalis, į kurią einate jos pasisavinti, yra kalvų ir slėnių šalis, gerianti dangaus lietaus vandenį;'),
  (@b5, 11, 12, 'šalis, kuria VIEŠPATS, tavo Dievas, rūpinasi: VIEŠPATIES, tavo Dievo, akys visados yra ant jos nuo metų pradžios iki metų pabaigos.'),
  (@b5, 11, 13, 'Ir įvyks, jei uoliai klausysite mano įsakymų, kuriuos jums šią dieną įsakau, idant mylėtumėte VIEŠPATĮ, savo Dievą, ir jam tarnautumėte visa savo širdimi ir visa savo siela,'),
  (@b5, 11, 14, 'tada jums duosiu jūsų šalies lietų jam skirtu laiku, ankstyvąjį lietų ir vėlyvąjį lietų, kad surinktum savo javus, savo vyną ir savo aliejų.'),
  (@b5, 11, 15, 'Ir pasiųsiu žolę į tavo laukus tavo galvijams, kad valgytum ir pasisotintum.'),
  (@b5, 11, 16, 'Žiūrėkite savęs, kad jūsų širdis nebūtų suklaidinta, ir nenukryptumėte, ir netarnautumėte kitiems dievams, ir jų negarbintumėte;'),
  (@b5, 11, 17, 'ir tada užsidegtų prieš jus VIEŠPATIES rūstybė, ir jis uždarytų dangų, kad nebebūtų lietaus, ir žemė nebeduotų savo vaisiaus; ir kad greitai nepražūtumėte iš šios geros šalies, kurią VIEŠPATS jums duoda.'),
  (@b5, 11, 18, 'Todėl dėkitės šituos mano žodžius į savo širdį ir į savo sielą, ir prisiriškite juos kaip ženklą ant savo rankos, kad jie būtų kaip galvaraištis tarp jūsų akių.'),
  (@b5, 11, 19, 'Ir mokykite jų savo vaikus, kalbėdami apie juos, kai sėdėsi savo namuose ir kai eisi keliu, kai gulsies ir kai kelsies.'),
  (@b5, 11, 20, 'Ir užrašyk juos ant savo namų staktų ir ant savo vartų;'),
  (@b5, 11, 21, 'kad būtų padaugintos jūsų dienos ir jūsų vaikų dienos šalyje, kurią VIEŠPATS jūsų tėvams prisiekė jiems duoti, kaip dangaus dienos žemėje.'),
  (@b5, 11, 22, 'Nes jei uoliai laikysitės visų šitų įsakymų, kuriuos jums įsakau, kad juos vykdytumėte, kad mylėtumėte VIEŠPATĮ, savo Dievą, kad vaikščiotumėte visais jo keliais ir kad prie jo priliptumėte;'),
  (@b5, 11, 23, 'tuomet VIEŠPATS išvarys iš jūsų akivaizdos visas šitas tautas, ir jūs užvaldysite tautas didesnes ir galingesnes už jus.'),
  (@b5, 11, 24, 'Kiekviena vieta, kurią užmins jūsų kojų padai, bus jūsų; nuo dykumos ir Libano, nuo upės, Eufrato upės, iki tolimiausios jūros bus jūsų ribos.'),
  (@b5, 11, 25, 'Niekas nepajėgs atsilaikyti prieš jus: nes VIEŠPATS, jūsų Dievas, uždės jūsų baimę ir jūsų išgąstį ant visos tos šalies, kuria žengsite, kaip jis yra jums sakęs.'),
  (@b5, 11, 26, 'Štai šią dieną padedu prieš jus palaiminimą ir prakeikimą:'),
  (@b5, 11, 27, 'palaiminimą, jei paklusite VIEŠPATIES, savo Dievo, įsakymams, kuriuos jums šią dieną įsakau;'),
  (@b5, 11, 28, 'ir prakeikimą, jei nepaklusite VIEŠPATIES, savo Dievo, įsakymams, bet nukrypsite nuo to kelio, kurį jums šią dieną įsakau, sekdami paskui kitus dievus, kurių nesate pažinę.'),
  (@b5, 11, 29, 'Ir įvyks, kai VIEŠPATS, tavo Dievas, bus įvedęs tave į šalį, į kurią eini jos pasisavinti, tada išdėstysi palaiminimą ant Gerizimo kalno, o prakeikimą ant Ebalo kalno.'),
  (@b5, 11, 30, 'Argi jie nėra anapus Jordano, kelyje, kur leidžiasi saulė, šalyje kanaaniečių, gyvenančių atvirame lauke priešais Gilgalą, šalia Morės lygumų?'),
  (@b5, 11, 31, 'Nes jūs pereisite per Jordaną, kad įeitumėte pasisavinti šalies, kurią VIEŠPATS, jūsų Dievas, jums duoda, ir ją pasisavinsite ir joje gyvensite.'),
  (@b5, 11, 32, 'Ir žiūrėkite, kad vykdytumėte visus įstatus ir teismus, kuriuos šią dieną pateikiu jūsų akivaizdon“.'),
  (@b5, 12, 1, '„Šitie yra įstatai ir teismai, kurių laikykitės, kad vykdytumėte toje šalyje, kurią VIEŠPATS, tavo tėvų Dievas, tau duoda pasisavinti, per visas dienas, kurias gyvensite žemėje.'),
  (@b5, 12, 2, 'Visiškai sunaikinkite visas vietas, kur tautos, kurias pasisavinsite, tarnavo savo dievams: aukštuose kalnuose, kalvose ir po kiekvienu žaliuojančiu medžiu;'),
  (@b5, 12, 3, 'ir sugriaukite jų aukurus, sudaužykite jų stulpus ir sudeginkite jų giraites ugnimi; nukirskite jų dievų raižytus atvaizdus ir išnaikinkite jų vardus iš tos vietos.'),
  (@b5, 12, 4, 'Taip nedarykite VIEŠPAČIUI, savo Dievui.'),
  (@b5, 12, 5, 'Bet tos vietos, kurią VIEŠPATS, jūsų Dievas, išrinks iš visų jūsų genčių, kad ten pastatytų savo vardą, tai yra jo buveinės, ieškokite ir ten ateikite:'),
  (@b5, 12, 6, 'ir ten atneškite savo deginamąsias atnašas ir savo aukas, savo dešimtines, savo rankos iškeliamąsias atnašas, savo įžadus, savo laisvos valios atnašas ir savo bandų bei savo kaimenių pirmagimius;'),
  (@b5, 12, 7, 'ir ten valgykite VIEŠPATIES, savo Dievo, akivaizdoje ir džiaukitės jūs ir jūsų namiškiai visu tuo, prie ko pridėjote savo ranką, kuo VIEŠPATS, tavo Dievas, palaimino tave.'),
  (@b5, 12, 8, 'Nedarykite pagal visa tai, ką čia šią dieną darome kiekvienas, kas jo akyse atrodo teisinga.'),
  (@b5, 12, 9, 'Nes dar neatėjote į poilsį ir į paveldą, kurį VIEŠPATS, jūsų Dievas, jums duoda.'),
  (@b5, 12, 10, 'Bet kai pereisite per Jordaną ir apsigyvensite šalyje, kurią VIEŠPATS, jūsų Dievas, duoda jums paveldėti, ir kai jis jums duos poilsį nuo visų jūsų aplinkinių priešų taip, kad saugiai gyvensite;'),
  (@b5, 12, 11, 'tuomet ten bus vieta, kurią VIEŠPATS, jūsų Dievas, išrinks, kad ten apgyvendintų savo vardą; ten atneškite viską, ką jums įsakau: savo deginamąsias atnašas ir savo aukas, savo dešimtines, savo rankos iškeliamąsias atnašas ir visus savo rinktinius įžadus, kuriuos pasižadėsite VIEŠPAČIUI;'),
  (@b5, 12, 12, 'ir džiaukitės VIEŠPATIES, savo Dievo, akivaizdoje jūs, jūsų sūnūs, jūsų dukterys, jūsų tarnai, jūsų tarnaitės ir levitas, esantis jūsų vartuose; kadangi jis neturi nei dalies, nei paveldo su jumis.'),
  (@b5, 12, 13, 'Žiūrėk savęs, kad neatnašautum savo deginamųjų atnašų kiekvienoje vietoje, kurią pamatysi;'),
  (@b5, 12, 14, 'bet toje vietoje, kurią VIEŠPATS išrinks vienoje iš tavo genčių, ten atnašauk savo deginamąsias atnašas ir ten daryk viską, ką tau įsakau.'),
  (@b5, 12, 15, 'Tačiau galėsi pjauti ir valgyti mėsos, kokios tik geidžia tavo siela, visuose savo vartuose pagal VIEŠPATIES, tavo Dievo, palaiminimą, kurį jis tau yra davęs: nešvarus ir švarus gali jos valgyti, kaip stirną ir elnią.'),
  (@b5, 12, 16, 'Tik nevalgykite kraujo; išliekite jį ant žemės kaip vandenį.'),
  (@b5, 12, 17, 'Tau negalima valgyti savo vartuose dešimtinės iš savo javų ar savo vyno, ar iš savo aliejaus, ar savo bandų ar kaimenių pirmagimių nei jokių savo pasižadėtų įžadų, nei savo laisvos valios atnašų ar savo rankos iškeliamosios atnašos;'),
  (@b5, 12, 18, 'bet turi juos valgyti VIEŠPATIES, savo Dievo, akivaizdoje, toje vietoje, kurią VIEŠPATS, tavo Dievas, išsirinks, tu, tavo sūnus, tavo duktė, tavo tarnas, tavo tarnaitė ir levitas, esantis tavo vartuose; ir džiaukis VIEŠPATIES, savo Dievo, akivaizdoje visu tuo, prie ko pridėjai savo rankas.'),
  (@b5, 12, 19, 'Žiūrėk savęs, kad neapleistum levito tol, kol gyvensi žemėje.'),
  (@b5, 12, 20, 'Kai VIEŠPATS, tavo Dievas, praplės tavo ribas, kaip jis yra tau pažadėjęs, ir tu sakysi: ‘Noriu valgyti mėsos’, nes tavo siela trokšta valgyti mėsos; tu gali valgyti mėsos, ko trokšta tavo siela.'),
  (@b5, 12, 21, 'Jei per toli nuo tavęs bus vieta, kurią VIEŠPATS, tavo Dievas, bus išsirinkęs, kad ten pastatytų savo vardą, tuomet papjauk iš savo bandos ir iš savo kaimenės, kurias VIEŠPATS tau yra davęs, kaip tau esu įsakęs, ir valgyk savo vartuose, ko tik geidžia tavo siela.'),
  (@b5, 12, 22, 'Kaip valgoma stirna ir elnias, taip juos valgyk: nešvarus juos tevalgo kaip ir švarus.'),
  (@b5, 12, 23, 'Tik būk užsitikrinęs, kad nevalgysi kraujo; nes kraujas yra gyvybė; o tau negalima valgyti gyvybės su mėsa.'),
  (@b5, 12, 24, 'Nevalgyk jo; išliek jį ant žemės kaip vandenį.'),
  (@b5, 12, 25, 'Nevalgyk jo; kad gerai sektųsi tau ir tavo vaikams po tavęs, kai darysi tai, kas teisinga VIEŠPATIES akyse.'),
  (@b5, 12, 26, 'Tik savo šventus dalykus, kurių turėsi, ir savo įžadus paimk ir eik į tą vietą, kurią VIEŠPATS išsirinks;'),
  (@b5, 12, 27, 'ir atnašauk savo deginamąsias atnašas, mėsą ir kraują ant VIEŠPATIES, savo Dievo, aukuro; o tavo aukų kraujas bus išlietas ant VIEŠPATIES, tavo Dievo, aukuro, o mėsą valgyk.'),
  (@b5, 12, 28, 'Laikykis ir klausyk visų šitų žodžių, kuriuos tau įsakau, kad gerai sektųsi tau ir tavo vaikams po tavęs per amžius, kai darysi tai, kas gera ir teisinga VIEŠPATIES, tavo Dievo, akyse.'),
  (@b5, 12, 29, 'Kai VIEŠPATS, tavo Dievas, iškirs iš tavo akivaizdos tautas, pas kurias eisi jų pasisavinti, ir, jas paveldėjęs, apsigyvensi jų šalyje;'),
  (@b5, 12, 30, 'žiūrėk savęs, kad neįsipainiotum sekdamas jomis, kai jos bus išnaikintos iš tavo akivaizdos; ir kad neklausinėtum apie jų dievus, sakydamas: ‘Kaip šitos tautos tarnavo savo dievams, taip ir aš darysiu’.'),
  (@b5, 12, 31, 'Taip nedaryk VIEŠPAČIUI, savo Dievui; nes jos darė savo dievams viską, kas VIEŠPAČIUI pasibjaurėjimas, ko jis nekenčia; jos net savo sūnus ir savo dukteris degino ugnyje savo dievams“.'),
  (@b5, 12, 32, 'Visa, ką jums įsakau, laikykitės, kad tai vykdytumėte; prie to nepridėk nei nuo to neatimk.'),
  (@b5, 13, 1, 'Jei jūsų tarpe kils pranašas ar sapnų sapnuotojas ir tau duos ženklą ar stebuklą,'),
  (@b5, 13, 2, 'o ženklas ar stebuklas įvyks, apie kurį jis tau kalbėjo, sakydamas: ‘Eikime paskui kitus dievus, kurių nesi pažinęs, ir tarnaukime jiems’;'),
  (@b5, 13, 3, 'neklausyk žodžių to pranašo ar to sapnų sapnuotojo; nes VIEŠPATS, jūsų Dievas, jus bando, kad sužinotų, ar mylite VIEŠPATĮ, savo Dievą, visa savo širdimi ir visa savo siela.'),
  (@b5, 13, 4, 'Vaikščiokite paskui VIEŠPATĮ, savo Dievą, bijokite jo, laikykitės jo įsakymų, pakluskite jo balsui, tarnaukite jam ir prie jo prilipkite.'),
  (@b5, 13, 5, 'O tas pranašas ar tas sapnų sapnuotojas bus užmuštas; nes jis kalbėjo, kad nukreiptų jus nuo VIEŠPATIES, jūsų Dievo, jus išvedusio iš Egipto šalies ir jus atpirkusio iš vergystės namų, kad tave nuvarytų nuo kelio, kuriuo VIEŠPATS, tavo Dievas, tau įsakė vaikščioti. Taip pašalink pikta iš savo tarpo.'),
  (@b5, 13, 6, 'Jei tavo brolis, tavo motinos sūnus, ar tavo sūnus, ar tavo duktė, ar tavo prieglobsčio žmona, ar tavo draugas, kuris yra kaip tavo paties siela, slapta tave vilios, sakydamas: ‘Eikime ir tarnaukime kitiems dievams, kurių nesi pažinęs nei tu, nei tavo tėvai;'),
  (@b5, 13, 7, 'būtent iš dievų tų tautų, kurios yra aplink jus, arti tavęs ar toli nuo tavęs, nuo vieno žemės krašto iki kito žemės krašto;'),
  (@b5, 13, 8, 'nesutik su juo nei jo neklausyk; ir tavo akys teneužjaučia jo, nesigailėk ir jo neslėpk;'),
  (@b5, 13, 9, 'bet tikrai jį užmušk; tavo ranka bus ant jo pirma, kad jį užmuštum, o paskui visos tautos ranka.'),
  (@b5, 13, 10, 'Ir užmėtyk jį akmenimis, kad jis mirtų; nes jis siekė nuvaryti tave nuo VIEŠPATIES, tavo Dievo, kuris išvedė tave iš Egipto šalies, iš vergystės namų.'),
  (@b5, 13, 11, 'Ir visas Izraelis išgirs ir bijos, ir daugiau nebedarys tokios nedorybės, kaip kad ši yra tarp jūsų.'),
  (@b5, 13, 12, 'Jei išgirsi sakant viename iš tavo miestų, kuriuos VIEŠPATS, tavo Dievas, tau bus davęs, kad ten gyventum:'),
  (@b5, 13, 13, '‘Iš jūsų tarpo yra išėję kai kurie žmonės, Belialo vaikai, ir yra atitraukę jų miesto gyventojus, sakydami: Eikime ir tarnaukime kitiems dievams, kurių nesate pažinę’;'),
  (@b5, 13, 14, 'tuomet teiraukis, ištyrinėk ir kruopščiai išklausinėk; ir štai jei tai tiesa, ir tai yra tikra, kad tokia bjaurystė yra padaryta tarp jūsų;'),
  (@b5, 13, 15, 'tai tikrai sumušk to miesto gyventojus kalavijo ašmenimis, visiškai sunaikindamas jį ir visa, kas yra jame, ir jo galvijus kalavijo ašmenimis.'),
  (@b5, 13, 16, 'O visą jo grobį surink į jo gatvės vidurį ir sudegink miestą bei visą jo grobį ugnimi iki dulkelės VIEŠPAČIUI, savo Dievui; ir jis bus amžina krūva; jis nebus atstatomas.'),
  (@b5, 13, 17, 'Ir niekas iš prakeiktų daiktų teneprilips prie tavo rankos; kad VIEŠPATS nusigręžtų nuo savo pykčio įniršio ir tau parodytų gailestingumą, tavęs pasigailėtų ir tave padaugintų, kaip jis yra prisiekęs tavo tėvams;'),
  (@b5, 13, 18, 'kai klausysi VIEŠPATIES, savo Dievo, balso, kad laikytumeisi visų jo įsakymų, kuriuos tau šią dieną įsakau, kad darytum tai, kas teisinga VIEŠPATIES, tavo Dievo, akyse“.'),
  (@b5, 14, 1, '„Jūs esate VIEŠPATIES, savo Dievo, vaikai; nesusipjaustykite ir nesidarykite plikės tarp akių dėl mirusio.'),
  (@b5, 14, 2, 'Nes tu esi šventa tauta VIEŠPAČIUI, savo Dievui, ir VIEŠPATS tave išsirinko, kad būtum jam ypatinga tauta virš visų tautų, esančių žemėje.'),
  (@b5, 14, 3, 'Nevalgyk nieko bjauraus.'),
  (@b5, 14, 4, 'Šitie yra gyvuliai, kuriuos valgysite: jautis, avis, ožka,'),
  (@b5, 14, 5, 'elnias, stirna, rudai geltonas elnias, laukinė ožka, dišonas, laukinis jautis ir kalnų ožka.'),
  (@b5, 14, 6, 'Ir kiekvieną gyvulį, kuris dalija kanopą ir skelia nagą į dvi nagas, ir gromuliuoja tarp gyvulių, – tą valgysite.'),
  (@b5, 14, 7, 'Tačiau iš gromuliuojančių ar iš dalijančių skeltą kanopą, šitų nevalgysite: kupranugario, kiškio ir triušio; nes, nors jie gromuliuoja, bet nedalija kanopos; todėl jie yra jums nešvarūs;'),
  (@b5, 14, 8, 'ir kiaulės, nes, nors ji dalija kanopą, tačiau negromuliuoja, ji jums yra nešvari; nevalgykite jų mėsos nei nelieskite jų lavonų.'),
  (@b5, 14, 9, 'Iš visko, kas yra vandenyse, valgykite šituos: viską, kas turi pelekus ir žvynus, valgykite;'),
  (@b5, 14, 10, 'o kas neturi pelekų ir žvynų, to jums negalima valgyti; tai jums yra nešvaru.'),
  (@b5, 14, 11, 'Visus švarius paukščius valgykite.'),
  (@b5, 14, 12, 'Bet šitie yra tie, iš kurių nevalgykite: erelio, grifo, erelio žuvininko,'),
  (@b5, 14, 13, 'sakalo, peslio ir maitvanagių pagal jų rūšis,'),
  (@b5, 14, 14, 'jokių varnų pagal jų rūšis,'),
  (@b5, 14, 15, 'pelėdos, naktinio vanago, gegutės, vanagų pagal jų rūšis,'),
  (@b5, 14, 16, 'mažosios pelėdos, didžiosios pelėdos, gulbės,'),
  (@b5, 14, 17, 'pelikano, jūrinio erelio, kormorano,'),
  (@b5, 14, 18, 'gandro, garnių pagal jų rūšis, pempės ir šikšnosparnio.'),
  (@b5, 14, 19, 'Ir visi ropojantys padarai, kurie skraido, jums yra nešvarūs: jie nebus valgomi.'),
  (@b5, 14, 20, 'Bet visus švarius skrajūnus galite valgyti.'),
  (@b5, 14, 21, 'Nevalgykite jokios dvėselienos; duok tai ateiviui, esančiam tavo vartuose, kad jis jos valgytų; arba gali ją parduoti svetimšaliui; nes tu esi šventa tauta VIEŠPAČIUI, savo Dievui. Nevirk ožiuko jo motinos piene.'),
  (@b5, 14, 22, 'Tikrai paimk dešimtinę nuo viso savo sėklos prieaugio, kurį laukas atneša kasmet.'),
  (@b5, 14, 23, 'Ir valgyk VIEŠPATIES, savo Dievo, akivaizdoje, toje vietoje, kurią jis išsirinks savo vardui ten apgyvendinti, dešimtinę savo javų, savo vyno ir savo aliejaus, ir pirmagimius savo bandų bei savo kaimenių; kad mokytumeisi visuomet bijoti VIEŠPATIES, savo Dievo.'),
  (@b5, 14, 24, 'O jei kelias bus tau per ilgas, kad negalėsi jos atgabenti, arba jei per toli bus nuo tavęs ta vieta, kurią VIEŠPATS, tavo Dievas, išsirinks ten pastatyti savo vardą, kai VIEŠPATS, tavo Dievas, bus tave palaiminęs;'),
  (@b5, 14, 25, 'tuomet paversk ją pinigais ir surišk pinigus savo rankoje, ir eik į tą vietą, kurią VIEŠPATS, tavo Dievas, išsirinks;'),
  (@b5, 14, 26, 'ir atiduok tuos pinigus už viską, ko geidžia tavo siela: už jaučius ar už avis, ar už vyną, ar už stiprų gėrimą, ar už viską, ko trokšta tavo siela; ir ten valgyk VIEŠPATIES, savo Dievo, akivaizdoje, ir džiaukis tu ir tavo namiškiai,'),
  (@b5, 14, 27, 'ir levitas, esantis tavo vartuose, – jo nepalik – nes jis neturi nei dalies, nei paveldo su tavimi.'),
  (@b5, 14, 28, 'Trijų metų pabaigoje tais metais išnešk visą savo prieaugio dešimtinę ir atidėk ją savo vartuose;'),
  (@b5, 14, 29, 'ir teateina levitas (nes jie neturi su tavimi nei dalies, nei paveldo), ir tavo vartuose esantis ateivis, našlaitis ir našlė, ir tevalgo ir pasisotina; kad VIEŠPATS, tavo Dievas, tave laimintų visuose tavo rankų darbuose, kuriuos tu darai“.'),
  (@b5, 15, 1, '„Kiekvieniems septyneriems metams pasibaigus atlik atleidimą.'),
  (@b5, 15, 2, 'O šitoks yra atleidimas: kiekvienas skolintojas, ką nors paskolinęs savo artimui, tai atleis; tenereikalauja jis to iš savo artimo ar iš savo brolio; nes tai vadinama VIEŠPATIES atleidimu.'),
  (@b5, 15, 3, 'Iš svetimšalio gali tai išreikalauti; bet tai, kas tavo yra pas tavo brolį, tavo ranka atleis;'),
  (@b5, 15, 4, 'nebent kai nebus tarp jūsų vargšų; nes VIEŠPATS tave didžiai laimins šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda paveldui, kad ją pasisavintum;'),
  (@b5, 15, 5, 'jei tik atidžiai klausysi VIEŠPATIES, savo Dievo, balso, kad laikytumeisi vykdydamas visus šiuos įsakymus, kuriuos tau įsakau šią dieną.'),
  (@b5, 15, 6, 'Nes VIEŠPATS, tavo Dievas, laimina tave, kaip jis tau pažadėjo; tu skolinsi daugeliui tautų, bet pats nesiskolinsi; ir viešpatausi daugeliui tautų, bet tau jos neviešpataus.'),
  (@b5, 15, 7, 'Jei tarp jūsų bus beturtis, vienas iš tavo brolių, vienuose iš tavo vartų, tavo šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda, tai neužkietink savo širdies nei neužgniaužk savo rankos savo beturčiui broliui;'),
  (@b5, 15, 8, 'bet plačiai atverk jam savo ranką ir tikrai jam skolink pakankamai jo poreikiams tai, ko jam stinga.'),
  (@b5, 15, 9, 'Saugokis, kad tavo nedoroje širdyje nebūtų minties, sakančios: ‘Čia pat septintieji metai, atleidimo metai’; ir tavo akis būtų pikta prieš tavo beturtį brolį, ir tu jam nieko neduotum; o jis šauksis VIEŠPATIES prieš tave, ir tau bus nuodėmė.'),
  (@b5, 15, 10, 'Tikrai jam duok, ir teneliūdi tavo širdis, kai jam duodi, nes už tai VIEŠPATS, tavo Dievas, tave laimins visuose tavo darbuose ir visur, kur bepridėsi savo ranką.'),
  (@b5, 15, 11, 'Nes beturčiai niekada nepradings iš šalies; todėl tau įsakau, sakydamas: ‘Plačiai atverk ranką savo broliui, savo beturčiui ir savo nepasiturinčiam savo šalyje’.'),
  (@b5, 15, 12, 'Jei tau būtų parsidavęs tavo brolis, hebrajas ar hebrajė, ir tau tarnautų šešerius metus; tuomet septintaisiais metais paleisk jį nuo savęs į laisvę.'),
  (@b5, 15, 13, 'O kai paleisi jį nuo savęs į laisvę, nepaleisk jo tuščiomis;'),
  (@b5, 15, 14, 'dosniai aprūpink jį iš savo kaimenės, iš savo klojimo ir iš savo vyno spaustuvo; duok jam iš to, kuo VIEŠPATS, tavo Dievas, yra tave palaiminęs.'),
  (@b5, 15, 15, 'Ir atsimink, kad buvai vergas Egipto šalyje, o VIEŠPATS, tavo Dievas, atpirko tave: todėl šiandien tau tai įsakau.'),
  (@b5, 15, 16, 'Ir bus, jei jis tau sakys: ‘Nenoriu iš tavęs išeiti’; dėl to, kad jis myli tave ir tavo namus, nes jam gerai pas tave;'),
  (@b5, 15, 17, 'tuomet paimk ylą ir ja durk per jo ausį prie durų, ir jis bus tavo tarnas per amžius. Taip pat padaryk ir savo tarnaitei.'),
  (@b5, 15, 18, 'Teneatrodo tau sunku, kai jį paleidi nuo savęs į laisvę; nes šešerius metus tau tarnaudamas jis buvo tau vertas dvigubo samdinio; o VIEŠPATS, tavo Dievas, tave laimins visame, ką tu darai.'),
  (@b5, 15, 19, 'Visus pirmagimius patinus, gimusius iš tavo bandos ir iš tavo kaimenės, pašvęsk VIEŠPAČIUI, savo Dievui; nedirbk darbo su savo jaučių pirmagimiu nei nekirpk savo avių pirmagimio.'),
  (@b5, 15, 20, 'Tu ir tavo namiškiai kasmet valgykite tai VIEŠPATIES, savo Dievo, akivaizdoje, toje vietoje, kurią VIEŠPATS išsirinks.'),
  (@b5, 15, 21, 'O jei būtų jame koks trūkumas, tartum būtų raišas ar aklas, ar turėtų kokį blogą trūkumą, neaukok to VIEŠPAČIUI, savo Dievui.'),
  (@b5, 15, 22, 'Valgyk jį savo vartuose; nešvarus asmuo jį valgys taip pat, kaip ir švarus, kaip stirną ir kaip elnią.'),
  (@b5, 15, 23, 'Tik jo kraujo nevalgyk; išliek jį ant žemės kaip vandenį“.'),
  (@b5, 16, 1, '„Laikykis Abibo mėnesio ir švęsk Apėjimą VIEŠPAČIUI, savo Dievui; nes Abibo mėnesį VIEŠPATS, tavo Dievas, nakčia išvedė tave iš Egipto.'),
  (@b5, 16, 2, 'Todėl aukok Apėjimą VIEŠPAČIUI, savo Dievui, iš kaimenės ir bandos, toje vietoje, kurią VIEŠPATS išsirinks, kad ten apgyvendintų savo vardą.'),
  (@b5, 16, 3, 'Nevalgyk su juo raugintos duonos; septynias dienas valgyk su juo neraugintą duoną, tai yra vargo duoną; nes paskubomis išėjai iš Egipto šalies; kad per visas savo gyvenimo dienas atsimintum tą dieną, kai išėjai iš Egipto šalies.'),
  (@b5, 16, 4, 'Ir septynias dienas pas tave neturi būti matoma raugintos duonos visose tavo ribose; nei neturi likti per visą naktį iki ryto nieko iš tos mėsos, kurią aukojai pirmąją dieną vakare.'),
  (@b5, 16, 5, 'Negalėsi aukoti Apėjimo nei vienuose iš savo vartų, kuriuos VIEŠPATS, tavo Dievas, tau duoda;'),
  (@b5, 16, 6, 'bet toje vietoje, kurią VIEŠPATS, tavo Dievas, išsirinks, kad ten apgyvendintų savo vardą, ten aukosi Apėjimą vakare, saulei leidžiantis, tuo metu, kuriuo išvykai iš Egipto.'),
  (@b5, 16, 7, 'Kepk ir valgyk jį toje vietoje, kurią VIEŠPATS, tavo Dievas, išsirinks; o ryte apsigręžęs eik į savo palapines.'),
  (@b5, 16, 8, 'Šešias dienas valgyk neraugintą duoną; o septintąją dieną bus iškilmingas susirinkimas VIEŠPAČIUI, tavo Dievui; joje nedirbk darbo.'),
  (@b5, 16, 9, 'Atskaičiuok sau septynias savaites: pradėk skaičiuoti septynias savaites nuo to laiko, kai pradėsi dėti pjautuvą prie javų.'),
  (@b5, 16, 10, 'Ir švęsk Savaičių šventę VIEŠPAČUI, savo Dievui, su savo rankos laisvos valios atnašos dovana, kurią duosi VIEŠPAČIUI, savo Dievui, pagal tai, kaip VIEŠPATS, tavo Dievas, yra tave palaiminęs;'),
  (@b5, 16, 11, 'ir džiaukis VIEŠPATIES, savo Dievo, akivaizdoje, tu, tavo sūnus, tavo duktė, tavo tarnas, tavo tarnaitė, levitas, esantis tavo vartuose, ateivis, našlaitis ir našlė, esantys tarp jūsų, vietoje, kurią VIEŠPATS, tavo Dievas, yra išsirinkęs, kad ten apgyvendintų savo vardą.'),
  (@b5, 16, 12, 'Ir atsimink, kad buvai vergas Egipte; ir laikykis ir vykdyk šituos įstatus.'),
  (@b5, 16, 13, 'Surinkęs savo javus ir savo vyną, septynias dienas švęsk Padangčių šventę;'),
  (@b5, 16, 14, 'ir džiaukis savo šventėje tu, tavo sūnus, tavo duktė, tavo tarnas, tavo tarnaitė, levitas, ateivis, našlaitis ir našlė, esantys tavo vartuose.'),
  (@b5, 16, 15, 'Septynias dienas švęsk iškilmingą šventę VIEŠPAČIUI, savo Dievui, toje vietoje, kurią VIEŠPATS išsirinks; nes VIEŠPATS, tavo Dievas, laimins tave visuose tavo prieaugiuose ir visuose tavo rankų darbuose, todėl tikrai džiaukis.'),
  (@b5, 16, 16, 'Tris kartus metuose visi tavo vyriškos lyties turi pasirodyti VIEŠPATIES, tavo Dievo, akivaizdoje, toje vietoje, kurią jis išsirinks: per Neraugintos duonos šventę, per Savaičių šventę ir per Padangčių šventę; ir jie tenepasirodo VIEŠPATIES akivaizdoje tuščiomis:'),
  (@b5, 16, 17, 'kiekvienas duos tiek, kiek pajėgia pagal VIEŠPATIES, tavo Dievo, palaiminimą, kurį jis yra tau davęs.'),
  (@b5, 16, 18, 'Paskirk sau teisėjų ir pareigūnų savo gentyse, visuose savo vartuose, kuriuos VIEŠPATS, tavo Dievas, tau duoda; ir jie teis tautą teisingu teismu.'),
  (@b5, 16, 19, 'Neiškreipk teismo; neatsižvelk į asmenis nei neimk dovanos; nes dovana apakina išmintingųjų akis ir iškraipo teisiųjų žodžius.'),
  (@b5, 16, 20, 'Sek tuo, kas tikrai teisu, kad gyventum ir paveldėtum šalį, kurią VIEŠPATS, tavo Dievas, tau duoda.'),
  (@b5, 16, 21, 'Nesisodink giraitės iš jokių medžių šalia VIEŠPATIES, tavo Dievo, aukuro, kurį pasidarysi.'),
  (@b5, 16, 22, 'Nei nesistatyk jokio atvaizdo, kurio nekenčia VIEŠPATS, tavo Dievas“.'),
  (@b5, 17, 1, '„Neaukok VIEŠPAČIUI, savo Dievui, jokio jaučio ar avies, kuriuose yra trūkumai ar kokia nors yda; nes tai yra pasibjaurėjimas VIEŠPAČIUI, tavo Dievui.'),
  (@b5, 17, 2, 'Jei atsiras jūsų tarpe, bet kuriuose iš tavo vartų, kuriuos VIEŠPATS, tavo Dievas, tau duoda, vyras ar moteris, kuris padarė nedorybę VIEŠPATIES, tavo Dievo, akyse, pažeisdamas jo sandorą,'),
  (@b5, 17, 3, 'ir nuėjęs tarnavo kitiems dievams ir juos garbino, ar tai saulę, ar mėnulį, ar ką iš dangaus kariuomenės, ko nesu jums įsakęs;'),
  (@b5, 17, 4, 'o tai tau praneša, ir tu esi apie tai išgirdęs bei kruopščiai išklausinėjęs, ir štai, tai yra tiesa, dalykas tikras, kad tokia bjaurastis yra padaryta Izraelyje;'),
  (@b5, 17, 5, 'tuomet išvesk tą vyrą ar tą moterį, kurie padarė tą nedorybę, prie savo vartų, tai yra tą vyrą ar tą moterį, ir juos užmėtyk akmenimis, kol jie mirs.'),
  (@b5, 17, 6, 'Dviejų ar trijų liudytojų burna bus užmuštas tas, kuris yra vertas mirties; bet jis nebus užmuštas vieno liudytojo burna.'),
  (@b5, 17, 7, 'Liudytojų rankos bus pirmos ant jo, jį užmušti, o paskui visos tautos rankos. Taip pašalink pikta iš savo tarpo.'),
  (@b5, 17, 8, 'O jei iškiltų reikalas, tau per sunkus teisti, tarp kraujo ir kraujo, tarp bylinėjimosi ir bylinėjimosi ir tarp smūgio ir smūgio, esant ginčytiniems reikalams tavo vartuose; tuomet pakilk ir eik aukštyn į tą vietą, kurią VIEŠPATS, tavo Dievas, išsirinks;'),
  (@b5, 17, 9, 'ir ateik pas kunigus levitus ir pas teisėją, kuris bus tomis dienomis, ir teiraukis; ir jie tau paskelbs teismo nuosprendį;'),
  (@b5, 17, 10, 'ir daryk pagal nuosprendį, kurį jie tau paskelbs iš tos vietos, kurią VIEŠPATS išsirinks; ir laikykis, kad darytum pagal visa tai, ko jie tave pamokys;'),
  (@b5, 17, 11, 'daryk pagal įstatymo nuosprendį, kurio tave mokys, ir pagal teismą, kurį tau pasakys; nenukrypk nuo nuosprendžio, kurį jie tau paskelbs, nei į dešinę, nei į kairę.'),
  (@b5, 17, 12, 'O kas pasielgs įžūliai ir neklausys kunigo, stovinčio ten tarnauti VIEŠPATIES, tavo Dievo, akivaizdoje, ar teisėjo, tas turės mirti; ir tu pašalinsi pikta iš Izraelio.'),
  (@b5, 17, 13, 'Ir visa tauta išgirs ir bijos, ir įžūliai nebesielgs.'),
  (@b5, 17, 14, 'Kai būsi atėjęs į šalį, kurią VIEŠPATS, tavo Dievas, tau duoda, ir ją pasisavinsi, ir joje apsigyvensi, ir sakysi: ‘Pastatysiu virš savęs karalių, kaip visos tautos, esančios aplink mane’;'),
  (@b5, 17, 15, 'tikrai pasistatyk karaliumi tą, kurį VIEŠPATS, tavo Dievas, išrinks: pasistatyk karaliumi vieną iš savo brolių tarpo; negali pasistatyti virš savęs svetimšalio, kuris nėra tavo brolis.'),
  (@b5, 17, 16, 'Bet jis nedaugins sau žirgų ir nedarys, kad tauta sugrįžtų į Egiptą tam, kad padaugintų žirgų; kadangi VIEŠPATS yra jums pasakęs: ‘Nuo šiol nebegrįžkite tuo keliu’.'),
  (@b5, 17, 17, 'Taip pat jis nedaugins sau žmonų, kad nenukryptų jo širdis; ir nedaugins labai sau sidabro bei aukso.'),
  (@b5, 17, 18, 'Ir bus, kai jis sėdės savo karalystės soste, jis nusirašys sau į knygą šito įstatymo kopiją iš to, kuris yra kunigų levitų akivaizdoje;'),
  (@b5, 17, 19, 'ir ji bus pas jį, ir jis ją skaitys per visas savo gyvenimo dienas; kad išmoktų bijoti VIEŠPATIES, savo Dievo, laikytis visų šito įstatymo žodžių ir šitų įstatų, kad juos vykdytų;'),
  (@b5, 17, 20, 'kad jo širdis nepasikeltų virš jo brolių, ir kad jis nenukryptų nuo to įsakymo nei į dešinę, nei į kairę; idant jis prailgintų savo dienas savo karalystėje, jis ir jo vaikai Izraelio tarpe“.'),
  (@b5, 18, 1, '„Kunigai levitai, visa Levio gentis, neturės nei dalies, nei paveldo su Izraeliu; jie valgys VIEŠPATIES ugnies atnašas ir jo paveldą.'),
  (@b5, 18, 2, 'Todėl jie neturės paveldo tarp savo brolių: VIEŠPATS yra jų paveldas, kaip jis yra jiems sakęs’.'),
  (@b5, 18, 3, 'O ta bus kunigų dalis nuo tautos, nuo tų, kurie atnašauja auką, ar tai būtų jautis, ar avis: kunigui jie duos petį, du žandus ir skrandį.'),
  (@b5, 18, 4, 'Taip pat jam duok pirmavaisius savo javų, savo vyno, savo aliejaus ir pirmienas iš savo avių vilnų.'),
  (@b5, 18, 5, 'Nes VIEŠPATS, tavo Dievas, jį išsirinko iš visų tavo genčių, kad stovėtų tarnauti VIEŠPATIES vardu, jis ir jo sūnūs per amžius.'),
  (@b5, 18, 6, 'Ir jei levitas ateis iš bet kurių tavo vartų, iš viso Izraelio, kur jis laikinai apsigyveno, ir ateis visu savo dvasios troškimu į tą vietą, kurią VIEŠPATS išsirinks;'),
  (@b5, 18, 7, 'tuomet jis tarnaus VIEŠPATIES, savo Dievo, vardu, kaip daro visi jo broliai levitai, kurie ten stovi VIEŠPATIES akivaizdoje.'),
  (@b5, 18, 8, 'Jie turės tokią pat dalį valgymui neskaitant to, ką gaus pardavę iš savo tėvų palikimo.'),
  (@b5, 18, 9, 'Kai būsi atėjęs į šalį, kurią VIEŠPATS, tavo Dievas, tau duoda, nesimokyk daryti pagal tų tautų bjaurystes.'),
  (@b5, 18, 10, 'Teneatsiranda jūsų tarpe nei vieno, kuris leistų savo sūnų ar savo dukterį per ugnį ar užsiimančio būrimu, ar laikų aiškintojo, ar kerėtojo, ar raganos,'),
  (@b5, 18, 11, 'ar žavėtojo, ar namų dvasių klausinėtojo, ar mago, ar to, kuris klausinėja numirėlių.'),
  (@b5, 18, 12, 'Nes visi, kurie daro tuos dalykus, yra pasibjaurėjimas VIEŠPAČIUI; ir dėl tų bjaurasčių VIEŠPATS, tavo Dievas, juos išvaro iš tavo akivaizdos.'),
  (@b5, 18, 13, 'Būk tobulas su VIEŠPAČIU, savo Dievu.'),
  (@b5, 18, 14, 'Nes šitos tautos, kurias tu pasisavinsi, klausė laikų aiškintojų ir būrėjų; bet kas dėl tavęs, VIEŠPATS, tavo Dievas, tau neleido taip daryti.'),
  (@b5, 18, 15, 'VIEŠPATS, tavo Dievas, tau prikels iš tavo tarpo, iš tavo brolių, Pranašą, tokį, kaip aš; jo klausysite;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b5, 18, 16, 'pagal visa tai, ko prašei VIEŠPATIES, savo Dievo, Horebe susirinkimo dieną, sakydamas: ‘Tenegirdėsiu daugiau VIEŠPATIES, savo Dievo, balso ir tenematysiu daugiau tos didelės ugnies, kad nemirčiau’.'),
  (@b5, 18, 17, 'Ir VIEŠPATS man tarė: ‘Jie gerai kalbėjo tai, ką jie kalbėjo.'),
  (@b5, 18, 18, 'Aš jiems prikelsiu iš jų brolių tarpo Pranašą, tokį, kaip tu, ir įdėsiu savo žodžius į jo burną; ir jis jiems kalbės viską, ką jam įsakysiu.'),
  (@b5, 18, 19, 'Ir įvyks, kad kas neklausys mano žodžių, kuriuos jis kalbės mano vardu, aš iš to tai pareikalausiu.'),
  (@b5, 18, 20, 'Bet pranašas, kuris drįstų mano vardu kalbėti žodį, kurio kalbėti nesu jam įsakęs, ar kuris kalbės kitų dievų vardu, tas pranašas mirs.'),
  (@b5, 18, 21, 'O jei sakysi savo širdyje: ‘Kaip mes pažinosime žodį, kurio VIEŠPATS nekalbėjo’?'),
  (@b5, 18, 22, 'Kai pranašas kalba VIEŠPATIES vardu, o tas dalykas neįvyksta ir neatsitinka, tai yra dalykas, kurio VIEŠPATS nekalbėjo, tas pranašas kalbėjo tai pernelyg pasitikėdamas savimi; tu jo nebijok“.'),
  (@b5, 19, 1, '„Kai VIEŠPATS, tavo Dievas, bus iškirtęs tautas, kurių šalį VIEŠPATS, tavo Dievas, tau duoda, ir tu jas paveldėsi ir apsigyvensi jų miestuose bei jų namuose;'),
  (@b5, 19, 2, 'atskirk sau tris miestus viduryje savo šalies, kurią VIEŠPATS, tavo Dievas, tau duoda pasisavinti.'),
  (@b5, 19, 3, 'Paruošk sau kelią ir padalink į tris dalis ribas savo šalies, kurią VIEŠPATS, tavo Dievas, tau duoda paveldėti, kad ten galėtų pabėgti kiekvienas užmušėjas.'),
  (@b5, 19, 4, 'O šitas yra reikalas užmušėjo, kuris ten pabėgs, kad išliktų gyvas: kas iš nežinojimo užmuš savo artimą, kurio praeityje nebuvo nekentęs;'),
  (@b5, 19, 5, 'kaip kad kas eitų su savo artimu į mišką malkų kirsti, ir jo ranka užsimotų kirviu medžiui nukirsti, o pentis nusmuktų nuo koto ir nukristų ant jo artimo, kad tas mirtų; jis pabėgs į vieną iš tų miestų ir išliks gyvas;'),
  (@b5, 19, 6, 'kad kraujo keršytojas, įsikarščiavęs širdyje, nesivytų užmušėjo ir jo nepavytų dėl to, kad kelias ilgas, ir jo neužmuštų; kai tuo tarpu jis nebuvo vertas mirties, kadangi nebuvo praeityje jo nekentęs.'),
  (@b5, 19, 7, 'Todėl tau įsakau, sakydamas: atskirk sau tris miestus.'),
  (@b5, 19, 8, 'O jei VIEŠPATS, tavo Dievas, praplės tavo ribas, kaip jis yra prisiekęs tavo tėvams, ir tau duos visą šalį, kurią jis pažadėjo duoti tavo tėvams;'),
  (@b5, 19, 9, 'jei laikysiesi visų šitų įsakymų, kad juos vykdytum, kuriuos tau šią dieną įsakau, kad mylėtum VIEŠPATĮ, savo Dievą, ir visuomet vaikščiotum jo keliais; tuomet sau pridėk dar tris miestus prie šitų trijų:'),
  (@b5, 19, 10, 'kad nekaltas kraujas nebūtų pralietas tavo šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda paveldui, ir taip kraujas nebūtų ant tavęs.'),
  (@b5, 19, 11, 'Bet jei kas, nekęsdamas savo artimo, tykos jo, pakils prieš jį ir muš jį mirtinai, kad šis mirs, ir pabėgs į vieną iš šitų miestų;'),
  (@b5, 19, 12, 'tada jo miesto vyresnieji pasiųs ir jį iš ten atves, ir atiduos jį į kraujo keršytojo rankas, kad jis mirtų.'),
  (@b5, 19, 13, 'Tavo akis jo tenesigaili, bet pašalink iš Izraelio nekalto kraujo kaltę, kad tau gerai sektųsi.'),
  (@b5, 19, 14, 'Neperkelk savo artimo riboženklio, kurį senoliai yra pastatę tavo pavelde, kurį paveldėsi toje šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda pasisavinti.'),
  (@b5, 19, 15, 'Vienas liudytojas nesikels prieš žmogų dėl kokios nors neteisybės ar kokios nuodėmės, iš visokios nuodėmės, kuria jis nusideda: dviejų liudytojų burna ar trijų liudytojų burna bus patvirtintas reikalas.'),
  (@b5, 19, 16, 'Jei melagingas liudytojas kils prieš žmogų, kad liudytų prieš jį tai, kas neteisinga;'),
  (@b5, 19, 17, 'tuomet abu tie žmonės, tarp kurių yra nesutarimas, atsistos VIEŠPATIES akivaizdoje, akivaizdoje kunigų ir teisėjų, kurie bus tomis dienomis;'),
  (@b5, 19, 18, 'o teisėjai kruopščiai ištardys: ir štai jei liudytojas yra melagingas liudytojas, melagingai liudijęs prieš savo brolį;'),
  (@b5, 19, 19, 'tuomet jam padarykite taip, kaip jis buvo sumanęs padaryti savo broliui; taip pašalinsi pikta iš savo tarpo.'),
  (@b5, 19, 20, 'O likusieji girdės ir bijos, ir nuo tol nebedarys tokios piktybės jūsų tarpe.'),
  (@b5, 19, 21, 'O tavo akis tenesigaili: bet gyvybė už gyvybę, akis už akį, dantis už dantį, ranka už ranką, koja už koją“.'),
  (@b5, 20, 1, '„Kai išeisi į mūšį prieš savo priešus ir išvysi žirgus, vežimus ir tautą, gausesnę už tave, nebijok jų; nes VIEŠPATS, tavo Dievas, kuris tave išvedė aukštyn iš Egipto šalies, yra su tavimi.'),
  (@b5, 20, 2, 'Ir bus, kad, jums artėjant į mūšį, kunigas prieis ir kalbės tautai,'),
  (@b5, 20, 3, 'ir jiems sakys: ‘Klausyk, o Izraeli, šią dieną artėjate į mūšį prieš savo priešus: tenenusilpsta jūsų širdys, nebijokite, nedrebėkite, nei neįsibauginkite dėl jų;'),
  (@b5, 20, 4, 'nes VIEŠPATS, jūsų Dievas, yra tas, kuris eina su jumis kovoti už jus prieš jūsų priešus, kad jus išgelbėtų’.'),
  (@b5, 20, 5, 'Ir pareigūnai kalbės tautai, sakydami: ‘Ar yra kas, kuris pastatė naujus namus ir nėra jų pašventęs? Tas tegul eina ir grįžta į savo namus, kad nežūtų mūšyje ir kitas jų nepašvęstų.'),
  (@b5, 20, 6, 'Ar yra kas, kuris pasodino vynuogyną ir dar nevalgė nuo jo? Jis irgi tegul eina ir grįžta į savo namus, kad nežūtų mūšyje ir kitas nevalgytų nuo jo.'),
  (@b5, 20, 7, 'Ar yra kas, kuris susižadėjo su žmona, bet jos nebuvo paėmęs? Tas tegul eina ir grįžta į savo namus, kad nežūtų mūšyje ir kitas jos nepaimtų’.'),
  (@b5, 20, 8, 'Ir pareigūnai toliau kalbės tautai ir sakys: ‘Ar yra kas baikštus ir silpnos širdies? Tegul jis eina ir grįžta į savo namus, kad jo brolių širdis nealptų kaip jo širdis’.'),
  (@b5, 20, 9, 'Ir bus, kai pareigūnai bus baigę kalbėti tautai, jie paskirs kariuomenių vadus, kad vestų tautą.'),
  (@b5, 20, 10, 'Kai priartėsi prie miesto, kariauti prieš jį, tuomet paskelbk jam taiką.'),
  (@b5, 20, 11, 'Ir bus, jei jis taikingai tau atsakys ir tau atidarys, tada bus, kad visa tauta, kuri bus jame rasta, mokės tau duoklę ir tau tarnaus.'),
  (@b5, 20, 12, 'O jei jis nesudarys taikos su tavimi, bet kariaus su tavimi, tuomet jį apgulk;'),
  (@b5, 20, 13, 'ir kai VIEŠPATS, tavo Dievas, jį atiduos į tavo rankas, tai iškapok kalavijo ašmenimis visus jo, esančius vyriškos lyties;'),
  (@b5, 20, 14, 'bet moteris, mažylius, galvijus ir viską, kas yra mieste, visa, kas išplėšta iš jo, pasiimk; ir valgyk, kas išplėšta iš tavo priešų, ką VIEŠPATS, tavo Dievas, yra tau davęs.'),
  (@b5, 20, 15, 'Taip daryk visiems miestams, esantiems labai toli nuo tavęs, kurie nėra iš šitų tautų miestų.'),
  (@b5, 20, 16, 'Bet iš šitų tautų miestų, kuriuos VIEŠPATS, tavo Dievas, tau duoda paveldėti, nepalik nieko gyvo, kas kvėpuoja;'),
  (@b5, 20, 17, 'bet visiškai sunaikink juos: hetitus, amoritus, kanaaniečius, perizus, hivus ir jebusiečius; kaip VIEŠPATS, tavo Dievas, yra tau įsakęs;'),
  (@b5, 20, 18, 'kad jie neišmokytų jūsų daryti pagal visas jų bjaurystes, kurias jie darė savo dievams; taip jūs nusidėtumėte VIEŠPAČIUI, savo Dievui.'),
  (@b5, 20, 19, 'Kai ilgą laiką būsi apgulęs miestą, kariaudamas prieš jį, kad jį paimtum, neišnaikink jo medžių jėga panaudodamas prieš juos kirvį; nes gali valgyti nuo jų, nenukirsk jų (nes lauko medis yra žmogaus gyvybė), kad juos panaudotum apgultyje;'),
  (@b5, 20, 20, 'tik medžius, kuriuos pažįsti, kad jie nėra medžiai valgymui, sunaikink ir nukirsk; ir pasidaryk pylimus prieš miestą, kuris kariaus su tavimi, kol jis bus pavergtas“.'),
  (@b5, 21, 1, '„Jei šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda pasisavinti, bus rastas užmuštas žmogus, gulintis lauke, bet nebus žinoma, kas jį užmušė;'),
  (@b5, 21, 2, 'tada tavo vyresnieji ir tavo teisėjai išeis ir išmatuos iki miestų, esančių aplinkui užmuštąjį;'),
  (@b5, 21, 3, 'ir bus, kad miestas, esantis arčiausiai užmuštojo, tai yra to miesto vyresnieji, paims telyčią, su kuria nebuvo dirbta, kuri nebuvo traukusi jungo;'),
  (@b5, 21, 4, 'ir to miesto vyresnieji nuves telyčią žemyn į nelygų slėnį, kuris nei artas, nei sėtas, ir ten slėnyje nukirs telyčiai sprandą;'),
  (@b5, 21, 5, 'ir prieis kunigai, Levio sūnūs; nes VIEŠPATS, tavo Dievas, juos išsirinko, kad jam tarnautų ir laimintų VIEŠPATIES vardu; ir jų žodžiu bus išbandytas kiekvienas nesutarimas ir kiekvienas kirtis;'),
  (@b5, 21, 6, 'ir visi to miesto vyresnieji, esantys arčiausiai užmuštojo, nuplaus savo rankas viršum telyčios, kuriai buvo nukirsta galva slėnyje;'),
  (@b5, 21, 7, 'ir jie atsakydami tars: ‘Mūsų rankos neišliejo šito kraujo ir mūsų akys to nematė.'),
  (@b5, 21, 8, 'Būk gailestingas, o VIEŠPATIE, savo tautai Izraeliui, kurį tu atpirkai, nekaltink savo tautos, Izraelio, dėl nekalto kraujo’. Ir jiems bus atleistas kraujas.'),
  (@b5, 21, 9, 'Taip pašalinsi iš jūsų tarpo nekalto kraujo kaltę, kai darysi tai, kas teisinga VIEŠPATIES akyse.'),
  (@b5, 21, 10, 'Kai išeisi į karą prieš savo priešus, ir VIEŠPATS, tavo Dievas, juos bus atidavęs į tavo rankas, ir būsi juos paėmęs į nelaisvę,'),
  (@b5, 21, 11, 'o tarp belaisvių pamatysi gražią moterį ir jos trokši, kad panorėsi ją turėti sau į žmonas;'),
  (@b5, 21, 12, 'tada parsivesk ją namo į savo namus; o ji nusiskus galvą ir nusipjaustys nagus;'),
  (@b5, 21, 13, 'ir nusimes nuo savęs savo belaisvės drabužius ir pasiliks tavo namuose, ir visą mėnesį apraudos savo tėvą bei savo motiną; o po to įeik pas ją ir būk jos vyras, o ji bus tavo žmona.'),
  (@b5, 21, 14, 'Ir bus, jei ji tau nepatiks, tuomet leisi jai eiti, kur ji nori; bet jokiu būdu jos neparduok už pinigus, nepaversk jos preke, nes tu ją esi nužeminęs.'),
  (@b5, 21, 15, 'Jei kas turės dvi žmonas, vieną mylimą, o kita nekenčiamą, ir jos, tiek mylimoji, tiek nekenčiamoji jam pagimdys vaikų; ir jei pirmagimis sūnus bus nekenčiamosios;'),
  (@b5, 21, 16, 'tuomet, kai jis duos savo sūnums paveldėti tai, ką jis turi, jis negalės mylimosios sūnaus padaryti pirmagimiu akivaizdoje nekenčiamosios sūnaus, kuris iš tikrųjų yra pirmagimis;'),
  (@b5, 21, 17, 'bet jis pripažins nekenčiamosios sūnų pirmagimiu, jam duodamas dvigubą dalį iš visko, ką turi; nes jis yra jo stiprybės pradžia; jo yra pirmagimystės teisė.'),
  (@b5, 21, 18, 'Jei kas turės užsispyrusį ir maištaujantį sūnų, kuris nepaklus savo tėvo balsui ar savo motinos balsui, ir jiems jį pabaudus jų neklausys;'),
  (@b5, 21, 19, 'tada jo tėvas ir jo motina jį nutvers ir išves pas jo miesto vyresniuosius ir prie jo vietos vartų;'),
  (@b5, 21, 20, 'ir sakys jo miesto vyresniesiems: ‘Šitas mūsų sūnus yra užsispyręs ir maištaujantis, jis nenori paklusti mūsų balsui; jis besotis ir girtuoklis’.'),
  (@b5, 21, 21, 'Ir visi jo miesto žmonės užmėtys jį akmenimis, kad jis mirtų; taip pašalinsi pikta iš jūsų tarpo; o visas Izraelis girdės ir bijos.'),
  (@b5, 21, 22, 'O jei kas bus padaręs nuodėmę, vertą mirties, ir turės būti užmuštas, ir jį pakarsi ant medžio;'),
  (@b5, 21, 23, 'jo kūnas nepasiliks per visą naktį ant medžio, bet būtinai jį palaidosi tą dieną (nes kabantysis yra Dievo prakeiktas); kad nebūtų suteršta tavo šalis, kurią VIEŠPATS, tavo Dievas, tau duoda paveldui“.'),
  (@b5, 22, 1, '„Pamatęs paklydusius savo brolio jautį ar avį, nesislėpk nuo jų; visiškai juos sugrąžink savo broliui.'),
  (@b5, 22, 2, 'O jei tavo brolio nėra arti tavęs arba jei jo nepažįsti, tuomet parsivesk jį į savo namus, ir jis bus pas tave, kol tavo brolis jo ieškos, ir tu jį sugrąžinsi jam.'),
  (@b5, 22, 3, 'Taip daryk su jo asilu; taip daryk su jo drabužiu; ir taip daryk su visais savo brolio pamestais daiktais, kuriuos jis pametė, o tu radai; tu negali slėptis.'),
  (@b5, 22, 4, 'Pamatęs savo brolio asilą ar jo jautį, parkritusius kelyje, nuo jų nesislėpk; tikrai jam padėk juos pakelti.'),
  (@b5, 22, 5, 'Moteris nenešios to, kas dera vyrui, o vyras nesivilks moters rūbų; nes visi, kurie taip daro, yra pasibjaurėjimas VIEŠPAČIUI, tavo Dievui.'),
  (@b5, 22, 6, 'Jei užtiksi paukščio lizdą, esantį priešais tave pakelėje, medyje ar ant žemės, ar tai būtų jaunikliai, ar kiaušiniai, ir patelė, tupinti ant jauniklių ar kiaušinių, neimk patelės su jaunikliais;'),
  (@b5, 22, 7, 'bet būtinai paleisk patelę, o jauniklius pasiimk; kad tau gerai sektųsi ir kad prailgintum savo dienas.'),
  (@b5, 22, 8, 'Kai statysi naują namą, tuomet padaryk užtvarą savo stogui, kad neužtrauktum kraujo ant savo namo, jei kas nukristų nuo jo.'),
  (@b5, 22, 9, 'Nesėk savo vynuogyno įvairiomis sėklomis: kad vaisius tavo sėklos, kurią pasėjai, ir tavo vynuogyno vaisius nebūtų suteršti.'),
  (@b5, 22, 10, 'Neark drauge jaučiu ir asilu.'),
  (@b5, 22, 11, 'Nedėvėk įvairių rūšių drabužio – kaip iš vilnos ir lino kartu.'),
  (@b5, 22, 12, 'Pasidaryk kutų ant keturių kampų savo rūbo, kuriuo apsidengsi.'),
  (@b5, 22, 13, 'Jei kas ima žmoną ir įeina pas ją, ir jos nebeapkenčia,'),
  (@b5, 22, 14, 'ir suteikia progų ją apkalbėti, ir užtraukia jai blogą vardą, sakydamas: ‘Aš ėmiau šitą moterį, ir kai pas ją įėjau, radau, kad ji ne mergelė’;'),
  (@b5, 22, 15, 'tada tos panelės tėvas ir jos motina paims ir išneš tos panelės nekaltybės žymes pas miesto vyresniuosius prie vartų;'),
  (@b5, 22, 16, 'ir panelės tėvas sakys vyresniesiems: ‘Savo dukterį daviau šitam vyrui į žmonas, o jis neapkenčia jos;'),
  (@b5, 22, 17, 'ir štai jis suteikė progų ją apkalbėti, sakydamas: „Radau, kad tavo duktė – ne mergelė“; tačiau šitos yra mano dukters nekaltybės žymės’. Ir jie išties tą audeklą miesto vyresniųjų akivaizdoje.'),
  (@b5, 22, 18, 'Ir to miesto vyresnieji tą vyrą paėmę jį nubaus;'),
  (@b5, 22, 19, 'ir nubaus jį šimtu sidabro šekelių, ir duos juos panelės tėvui, kadangi jis užtraukė blogą vardą Izraelio mergelei; o ji bus jo žmona; jis negalės jos atleisti per visas savo dienas.'),
  (@b5, 22, 20, 'Bet jei tas dalykas yra tiesa, ir tos panelės nekaltybės žymės nebūtų rastos;'),
  (@b5, 22, 21, 'tada jie išves tą panelę prie jos tėvo namų durų ir jos miesto žmonės užmėtys ją akmenimis, kad ji mirtų; nes ji padarė kvailystę Izraelyje, paleistuvaudama savo tėvo namuose; taip pašalinsi pikta iš jūsų tarpo.'),
  (@b5, 22, 22, 'Jei bus užtiktas vyras begulįs su moterimi, ištekėjusia už vyro, tuomet jie abu turi mirti, tiek vyras, kuris gulėjo su moterimi, tiek moteris: taip pašalinsi pikta iš Izraelio.'),
  (@b5, 22, 23, 'Jei mergina, kuri yra mergelė, yra susižadėjusi su vyru, ir koks vyras, ją užtikęs mieste, su ja suguls;'),
  (@b5, 22, 24, 'tuomet išvesite juos abu prie to miesto vartų ir juos užmėtysite akmenimis, kad jie mirtų: tą panelę dėl to, kad ji nešaukė, būdama mieste; ir tą vyrą dėl to, kad jis pažemino savo artimo žmoną: taip pašalinsi pikta iš jūsų tarpo.'),
  (@b5, 22, 25, 'Bet jei vyras ant lauko užtinka susižadėjusią panelę, ir tas vyras ją priverčia ir su ja sugula; tuomet mirs tik tas vyras, kuris su ja sugulė;'),
  (@b5, 22, 26, 'bet tai panelei nieko nedarysi: panelėje nėra nuodėmės, kuri būtų verta mirties; nes šis atvejis yra, kaip kad žmogus pakiltų prieš savo artimą ir jį nužudytų;'),
  (@b5, 22, 27, 'nes jis ją užtiko ant lauko ir susižadėjusi panelė šaukė, bet nebuvo kas ją išgelbėtų.'),
  (@b5, 22, 28, 'Jei vyras užtinka merginą, kuri yra mergelė, kuri nėra susižadėjusi, ir ją nutveria, ir sugula su ja, ir juos užtinka;'),
  (@b5, 22, 29, 'tuomet tas vyras, kuris sugulė su ja, duos tos panelės tėvui penkiasdešimt sidabro šekelių, o ji bus jo žmona; nes jis ją pažemino; jis negalės jos atleisti per visas savo dienas.'),
  (@b5, 22, 30, 'Nei vienas neims savo tėvo žmonos nei neatidengs savo tėvo skverno“.'),
  (@b5, 23, 1, 'Tas, kurio sėklidės sužeistos ar kurio lytinis organas nupjautas, neįeis į VIEŠPATIES susirinkimą.'),
  (@b5, 23, 2, 'Pavainikis neįeis į VIEŠPATIES susirinkimą; net iki jo dešimtos kartos jis neįeis į VIEŠPATIES susirinkimą.'),
  (@b5, 23, 3, 'Amonietis ar moabietis neįeis į VIEŠPATIES susirinkimą; net iki jų dešimtos kartos jie neįeis į VIEŠPATIES susirinkimą amžinai;'),
  (@b5, 23, 4, 'nes jie nepasitiko jūsų kelyje su duona ir vandeniu, kai išėjote iš Egipto; ir kadangi jie pasamdė prieš tave Beoro sūnų Balaamą iš Mesopotamijos Petoro, kad tave prakeiktų.'),
  (@b5, 23, 5, 'Tačiau VIEŠPATS, tavo Dievas, nenorėjo klausyti Balaamo; bet VIEŠPATS, tavo Dievas, pavertė tau prakeikimą į palaiminimą, nes VIEŠPATS, tavo Dievas, pamilo tave.'),
  (@b5, 23, 6, 'Nesiek nei jų taikos, nei jų gerovės per visas savo dienas per amžius.'),
  (@b5, 23, 7, 'Nesibjaurėk edomitu; nes jis tavo brolis; nesibjaurėk egiptiečiu, nes buvai ateivis jo šalyje.'),
  (@b5, 23, 8, 'Jų pagimdyti vaikai įeis į VIEŠPATIES susirinkimą jų trečioje kartoje.'),
  (@b5, 23, 9, 'Kai kariuomenė išeina prieš tavo priešus, tuomet saugokis nuo visų piktybių.'),
  (@b5, 23, 10, 'Jei kas tarp jūsų būtų nešvarus dėl nešvarumo, kuris jam atsitinka naktį, tada jis išeis už stovyklos, jis neįeis į stovyklos vidų;'),
  (@b5, 23, 11, 'bet artėjant vakarui jis nusiplaus vandeniu; o saulei nusileidus jis sugrįš į stovyklą.'),
  (@b5, 23, 12, 'Taip pat turėk vietą už stovyklos, kur galėtum lauke išeiti:'),
  (@b5, 23, 13, 'turėk lopetėlę prie savo ginklo; ir bus, kai norėsi nusilengvinti lauke, ja iškask ir atsigręžęs apdenk tai, kas iš tavęs išeina;'),
  (@b5, 23, 14, 'nes VIEŠPATS, tavo Dievas, vaikšto tavo stovyklos viduryje, kad tave išgelbėtų ir paduotų tavo priešus tavo akivaizdoje; todėl tavo stovykla bus šventa; kad jis nieko nešvaraus nematytų tavyje ir nenusigręžtų nuo tavęs.'),
  (@b5, 23, 15, 'Tarno, kuris yra pabėgęs nuo savo šeimininko pas tave, neatiduok jo šeimininkui;'),
  (@b5, 23, 16, 'jis gyvens pas tave, tai yra jūsų tarpe, toje vietoje, kurią jis pasirinks vienuose iš tavo vartų, kur jam labiausiai patinka; tu jo neenk.'),
  (@b5, 23, 17, 'Nebus nei paleistuvės iš Izraelio dukterų, nei sodomiečio iš Izraelio sūnų.'),
  (@b5, 23, 18, 'Neatnešk paleistuvės algos ar šuns kainos į VIEŠPATIES, tavo Dievo, namus kaip įžado; nes abu šitie yra pasibjaurėjimas VIEŠPAČIUI, tavo Dievui.'),
  (@b5, 23, 19, 'Neskolink savo broliui už palūkanas: už pinigų palūkanas, už maisto palūkanas, už kokio nors palūkanoms skolinamo daikto palūkanas;'),
  (@b5, 23, 20, 'svetimšaliui gali skolinti už palūkanas; bet savo broliui neskolink už palūkanas; kad VIEŠPATS, tavo Dievas, laimintų tave visame, prie ko pridėsi savo ranką, šalyje, į kurią eini jos pasisavinti.'),
  (@b5, 23, 21, 'Kai duosi įžadą VIEŠPAČIUI, savo Dievui, nedelsk jo ištesėti; nes VIEŠPATS, tavo Dievas, tikrai pareikalaus jo iš tavęs; ir tai būtų tavyje nuodėmė.'),
  (@b5, 23, 22, 'Bet jei susilaikysi nuo įžado, tai nebus nuodėmė tavyje.'),
  (@b5, 23, 23, 'To, kas išėjo iš tavo lūpų, laikykis ir vykdyk; tai yra, laisvos valios atnašos pagal tai, kaip davei įžadą VIEŠPAČIUI, savo Dievui, tai, ką žadėjai savo burna.'),
  (@b5, 23, 24, 'Įėjęs į savo artimo vynuogyną, gali valgyti vynuogių iki soties, kiek nori; bet nei kiek jų nedėk į savo indą.'),
  (@b5, 23, 25, 'Įėjęs į savo artimo stovinčius javus, gali savo ranka skinti varpas; bet neslinksi pjautuvo į savo artimo stovinčius javus“.'),
  (@b5, 24, 1, '„Kai kas nors ims žmoną ir ją ves, ir įvyks, kad ji neras palankumo jo akyse dėl to, jog jis rado joje ką nešvaraus; tada jis teparašo jai skyrybų raštą ir tepaduoda tai jai į rankas ir ją teišleidžia iš savo namų.'),
  (@b5, 24, 2, 'Ir išėjusi iš jo namų, ji gali eiti ir būti kito vyro žmona.'),
  (@b5, 24, 3, 'O jei paskutinysis vyras jos neapkęs ir parašys jai skyrybų raštą, ir paduos jai tai į rankas, ir išleis ją iš savo namų; arba jei paskutinysis vyras, ėmęs ją, kad būtų jo žmona, numirs;'),
  (@b5, 24, 4, 'tai jos pirmasis vyras, kuris ją paleido, nebegali jos vėl imti, kad būtų jo žmona, po to, kai ji yra suteršta; nes tai yra pasibjaurėjimas VIEŠPATIES akivaizdoje; nedaryk, kad nusidėtų šalis, kurią VIEŠPATS, tavo Dievas, tau duoda paveldui.'),
  (@b5, 24, 5, 'Kai vyras bus ėmęs naują žmoną, jis teneišeina į karą, ir tenebūna įpareigotas jokiu reikalu; bet vienerius metus jis bus laisvas namuose ir linksmins savo žmoną, kurią yra paėmęs.'),
  (@b5, 24, 6, 'Niekas teneima užstatui apatinės ar viršutinės girnos, nes jis imtų užstatui žmogaus gyvybę.'),
  (@b5, 24, 7, 'Jei kas būtų užtiktas vagiant kurį iš savo brolių, iš Izraelio vaikų, ir juo prekiaujant ar jį parduodant; tuomet tas vagis mirs; ir pašalinsi pikta iš jūsų tarpo.'),
  (@b5, 24, 8, 'Žiūrėk, raupsų negandoje, kad stropiai laikytumeisi ir darytum pagal visa tai, ką jus mokys kunigai levitai: kaip jiems įsakiau, taip jūs laikykitės, kad vykdytumėte.'),
  (@b5, 24, 9, 'Atsimink, ką VIEŠPATS, tavo Dievas, padarė Mirjamai kelyje, kai buvote išėję iš Egipto.'),
  (@b5, 24, 10, 'Kai skolinsi ką nors savo broliui, neik į jo namus užstato pasiimti.'),
  (@b5, 24, 11, 'Stovėk lauke, o tas žmogus, kuriam skolinai, išneš užstatą tau į lauką.'),
  (@b5, 24, 12, 'O jei tas žmogus būtų neturtingas, nemiegok su jo užstatu:'),
  (@b5, 24, 13, 'saulei leidžiantis būtinai jam sugrąžink užstatą, kad jis miegotų savo paties rūbuose ir tave laimintų; ir tai tau bus teisumas VIEŠPATIES, tavo Dievo, akivaizdoje.'),
  (@b5, 24, 14, 'Neenk neturtingo ir nepasiturinčio samdinio, ar jis būtų iš tavo brolių, ar iš tavo ateivių, esančių tavo šalyje, tavo vartuose;'),
  (@b5, 24, 15, 'jo dieną jam duosi jo algą, saulei dar ant jos nenusileidus; nes jis neturtingas, ir į ją nukreipia savo širdį; kad jis nesišauktų VIEŠPATIES prieš tave, ir tau tai nebūtų nuodėmė.'),
  (@b5, 24, 16, 'Tėvai nebus užmušami už vaikus, nei vaikai nebus užmušami už tėvus: kiekvienas bus užmušamas už savo paties nuodėmę.'),
  (@b5, 24, 17, 'Neiškraipyk nei ateivio, nei našlaičio teismo; ir neimk užstatui našlės drabužio;'),
  (@b5, 24, 18, 'bet atsimink, kad buvai vergas Egipte, ir VIEŠPATS, tavo Dievas, iš ten tave išpirko: todėl tau įsakau tai vykdyti.'),
  (@b5, 24, 19, 'Kai pjausi savo derlių savo lauke ir būsi pamiršęs pėdą lauke, negrįžk jo paimti: jis bus ateiviui, našlaičiui ir našlei; kad VIEŠPATS, tavo Dievas, tave laimintų visuose tavo rankų darbuose.'),
  (@b5, 24, 20, 'Kai nudaužysi savo alyvmedį, nebeperieškok šakų: tai bus ateiviui, našlaičiui ir našlei.'),
  (@b5, 24, 21, 'Kai surinksi savo vynuogyno vynuoges, vėliau jo nebenurankiok: tai bus ateiviui, našlaičiui ir našlei.'),
  (@b5, 24, 22, 'Ir atsimink, kad buvai vergas Egipto šalyje, todėl tau įsakau tai daryti“.'),
  (@b5, 25, 1, '„Jei bus ginčas tarp žmonių, ir jie ateis į teismą, kad teisėjai juos teistų, tada jie turės išteisinti teisųjį, o nedorąjį pasmerkti.'),
  (@b5, 25, 2, 'Ir bus, jei nedorasis bus nusipelnęs plakimo, tai teisėjas lieps jį paguldyti ir plakti jo akyse atitinkamu skaičiumi pagal jo nusižengimą.'),
  (@b5, 25, 3, 'Jis gali jam duoti keturiasdešimt kirčių, ir neviršyti; kad, jei jis viršytų ir toliau jį plaktų daugeliu kirčių, tavo brolis tau neatrodytų bjaurus.'),
  (@b5, 25, 4, 'Neužrišk nasrų jaučiui, kai jis mindo javus.'),
  (@b5, 25, 5, 'Jei broliai gyvena drauge, o vienas iš jų miršta neturėdamas vaikų, tai mirusiojo žmona neištekės išorėje už svetimo: jos vyro brolis įeis pas ją, ją ims į žmonas ir jai atliks vyro brolio pareigą.'),
  (@b5, 25, 6, 'Ir bus, jog pirmagimis, kurį ji pagimdys, paveldės jo mirusio brolio vardą, kad jo vardas neišnyktų iš Izraelio.'),
  (@b5, 25, 7, 'O jei tas vyras nenorės imti savo brolio žmonos, tuomet jo brolio žmona tenueina aukštyn prie vartų pas vyresniuosius ir sako: ‘Mano vyro brolis atsisako prikelti savo broliui vardą Izraelyje, jis nenori atlikti mano vyro brolio pareigos’.'),
  (@b5, 25, 8, 'Tada jo miesto vyresnieji jį pašauks ir jam kalbės; bet jei jis to laikysis ir sakys: ‘Nenoriu jos imti’;'),
  (@b5, 25, 9, 'tada jo brolio žmona ateis prie jo vyresniųjų akyse, numaus jam nuo kojos apavą, spjaus jam į veidą ir atsakydama tars: ‘Taip bus daroma tam vyrui, kuris nenori pastatyti savo brolio namų’.'),
  (@b5, 25, 10, 'Ir jo vardas Izraelyje bus pramintas: ‘Namai to, kuriam nuautas apavas’.'),
  (@b5, 25, 11, 'Kai vyrai susivaidys vienas su kitu ir prieis vieno žmona, kad išgelbėtų savo vyrą iš jį mušančio rankos, ir ištiesusi savo ranką, paims už jo intymių organų;'),
  (@b5, 25, 12, 'tuomet nukirsk jai ranką, tavo akis jos tenesigaili.'),
  (@b5, 25, 13, 'Neturėk savo maišelyje skirtingų svarsčių, didelių ir mažų.'),
  (@b5, 25, 14, 'Neturėk savo namuose skirtingų matų, didelių ir mažų.'),
  (@b5, 25, 15, 'Bet turėk tobulą ir teisingą svarstį, turėk tobulą ir teisingą matą; kad tavo dienos būtų prailgintos šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda.'),
  (@b5, 25, 16, 'Nes visi, kurie taip daro, visi, kurie neteisiai elgiasi, yra pasibjaurėjimas VIEŠPAČIUI, tavo Dievui.'),
  (@b5, 25, 17, 'Atsimink, ką tau padarė Amalekas kelyje, kai išėjote iš Egipto;'),
  (@b5, 25, 18, 'kaip jis sutiko tave kelyje ir sumušė tavo atsilikusiuosius, tai yra visus silpnuosius, buvusius paskui tave, kai tu buvai nusilpęs ir nuvargęs; ir jis nebijojo Dievo.'),
  (@b5, 25, 19, 'Todėl bus, kai VIEŠPATS, tavo Dievas, bus tau davęs poilsį nuo visų tavo aplinkinių priešų šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda paveldui, kad ją pasisavintum, tada išdildysi Amaleko atminimą iš po dangaus; to nepamiršk“.'),
  (@b5, 26, 1, '„Ir bus, kai būsi įėjęs į šalį, kurią VIEŠPATS, tavo Dievas, tau duoda paveldui, ir būsi ją pasisavinęs bei joje apsigyvenęs;'),
  (@b5, 26, 2, 'tada paimk iš visų pirmųjų žemės vaisių, kuriuos atneši iš savo šalies, kurią VIEŠPATS, tavo Dievas, tau duoda, ir sudėk juos į pintinę, ir nueik į tą vietą, kurią VIEŠPATS, tavo Dievas, išsirinks, kad ten apgyvendintų savo vardą.'),
  (@b5, 26, 3, 'Ir nueik pas kunigą, kuris bus tomis dienomis, ir jam sakyk: ‘Šią dieną išpažįstu VIEŠPAČIUI, tavo Dievui, kad atvykau į kraštą, kurį VIEŠPATS prisiekė mūsų tėvams mums duoti’.'),
  (@b5, 26, 4, 'O kunigas paims pintinę iš tavo rankos ir ją padės prieš VIEŠPATIES, tavo Dievo, aukurą.'),
  (@b5, 26, 5, 'O tu kalbėk ir sakyk VIEŠPATIES, savo Dievo, akivaizdoje: ‘Mano tėvas buvo bepražūstantis siras ir jis nusileido į Egiptą, ir ten laikinai apsigyveno su keletu, ir ten tapo didele, galinga ir gausia tauta;'),
  (@b5, 26, 6, 'o egiptiečiai piktai elgėsi su mumis, spaudė mus ir uždėjo mums sunkią vergovę;'),
  (@b5, 26, 7, 'o kai mes šaukėmės VIEŠPATIES, savo tėvų Dievo, VIEŠPATS išgirdo mūsų balsą ir pažvelgė į mūsų vargą, į mūsų triūsą ir į mūsų priespaudą;'),
  (@b5, 26, 8, 'ir VIEŠPATS mus išvedė iš Egipto galinga ranka ir ištiesta ranka, dideliu siaubu, ženklais bei stebuklais;'),
  (@b5, 26, 9, 'ir jis mus atvedė į šitą vietą ir mums davė šią šalį – šalį, plūstančią pienu ir medumi.'),
  (@b5, 26, 10, 'O dabar, štai atnešiau pirmavaisius šios šalies, kurią tu, o VIEŠPATIE, man davei’. Ir padėk juos prieš VIEŠPATĮ, savo Dievą, ir garbink prieš VIEŠPATĮ, savo Dievą;'),
  (@b5, 26, 11, 'ir džiaukis visu geru, kurį VIEŠPATS, tavo Dievas, yra davęs tau ir tavo namams – tu, levitas ir ateivis, esantis jūsų tarpe.'),
  (@b5, 26, 12, 'Baigęs atsidėti visas savo prieaugio dešimtines trečiaisiais metais, tai yra, dešimtinių atsidėjimo metais, ir tai davęs levitui, ateiviui, našlaičiui ir našlei, kad jie valgytų tavo vartuose ir pasisotintų;'),
  (@b5, 26, 13, 'sakyk VIEŠPATIES, savo Dievo, akivaizdoje: ‘Išnešiau tai, kas pašvęsta, iš savo namų ir taip pat tai daviau levitui, ateiviui, našlaičiui ir našlei pagal visus tavo įsakymus, kuriuos man įsakei; nenusižengiau tavo įsakymams ir jų nepamiršau;'),
  (@b5, 26, 14, 'nevalgiau iš to gedėdamas nei nieko iš to nepaėmiau jokiam nešvariam naudojimui, ir nieko iš to nedaviau už mirusius; bet klausiau VIEŠPATIES, savo Dievo, balso ir dariau pagal visa tai, ką esi man įsakęs.'),
  (@b5, 26, 15, 'Pažvelk žemyn iš savo šventosios buveinės, iš dangaus, ir palaimink savo tautą Izraelį bei šalį, kurią mums davei, kaip prisiekei mūsų tėvams, šalį, plūstančią pienu ir medumi’.'),
  (@b5, 26, 16, 'Šią dieną VIEŠPATS, tavo Dievas, tau įsakė vykdyti šituos įstatus ir teismus; todėl laikykis ir vykdyk juos visa savo širdimi ir visa savo siela.'),
  (@b5, 26, 17, 'Šią dieną patvirtinai VIEŠPATĮ esant tavo Dievu, ir kad vaikščiosi jo keliais, laikysiesi jo įstatų, jo įsakymų bei jo teismų ir klausysi jo balso;'),
  (@b5, 26, 18, 'ir VIEŠPATS šią dieną patvirtino tave esant jo ypatinga tauta, kaip jis yra tau pažadėjęs, ir kad turi laikytis visų jo įsakymų;'),
  (@b5, 26, 19, 'ir kad už visas jo padarytas tautas jis padarys tave aukštesniu gyriumi, vardu ir garbe; ir kad būtum šventa tauta VIEŠPAČIUI, savo Dievui, kaip jis yra kalbėjęs“.'),
  (@b5, 27, 1, 'Ir Mozė su Izraelio vyresniaisiais įsakė tautai, sakydami: „Laikykitės visų įsakymų, kuriuos jums šią dieną įsakau.'),
  (@b5, 27, 2, 'Ir bus tą dieną, kai pereisite per Jordaną į šalį, kurią VIEŠPATS, tavo Dievas, tau duoda, tada pasistatyk sau didelių akmenų ir aptinkuok juos tinku;'),
  (@b5, 27, 3, 'ir užrašyk ant jų visus šio įstatymo žodžius, kai būsi perėjęs, kad įeitum į šalį, kurią VIEŠPATS, tavo Dievas, tau duoda, šalį, plūstančią pienu ir medumi; kaip VIEŠPATS, tavo tėvų Dievas, yra tau pažadėjęs.'),
  (@b5, 27, 4, 'Todėl bus, kai būsite perėję per Jordaną, pastatykite šituos akmenis, apie kuriuos šią dieną jums įsakau, Ebalo kalne, ir aptinkuok juos tinku.'),
  (@b5, 27, 5, 'Ir ten pastatyk aukurą VIEŠPAČIUI, savo Dievui, aukurą akmenų; nepakelk ant jų jokio geležinio įrankio.'),
  (@b5, 27, 6, 'Pastatyk VIEŠPATIES, savo Dievo, aukurą iš sveikų akmenų; ir atnašauk ant jo deginamąsias atnašas VIEŠPAČIUI, savo Dievui;'),
  (@b5, 27, 7, 'ir atnašauk taikos atnašas ir ten valgyk, ir džiaukis VIEŠPATIES, savo Dievo, akivaizdoje.'),
  (@b5, 27, 8, 'Ir užrašyk ant akmenų visus šito įstatymo žodžius labai aiškiai“.'),
  (@b5, 27, 9, 'Ir Mozė ir kunigai levitai kalbėjo visam Izraeliui, sakydami: „Būk atidus ir išklausyk, o Izraeli; šią dieną tapai VIEŠPATIES, savo Dievo, tauta.'),
  (@b5, 27, 10, 'Todėl paklusk VIEŠPATIES, savo Dievo, balsui ir vykdyk jo įsakymus bei jo įstatus, kuriuos tau šią dieną įsakau“.'),
  (@b5, 27, 11, 'Ir tą pačią dieną Mozė įpareigojo tautą, sakydamas:'),
  (@b5, 27, 12, '„Jums perėjus per Jordaną, šitie stovės ant Gerizimo kalno, kad laimintų tautą: Simeonas, Levis, Juda, Isacharas, Juozapas ir Benjaminas;'),
  (@b5, 27, 13, 'o šitie stovės ant Ebalo kalno, kad prakeiktų: Rubenas, Gadas, Ašeras, Zebulonas, Danas ir Naftalis.'),
  (@b5, 27, 14, 'O levitai kalbės ir sakys visiems Izraelio žmonėms garsiu balsu:');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b5, 27, 15, '‘Tebūna prakeiktas tas žmogus, kuris padirba kokį raižytą ar nulietą atvaizdą, bjaurystę VIEŠPAČIUI, amatininko rankų darbą, ir pastato jį slaptoje vietoje’. Ir visa tauta atsiliepdama sakys: ‘Amen’.'),
  (@b5, 27, 16, '‘Tebūna prakeiktas tas, kuris nepaiso savo tėvo ar motinos’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 17, '‘Tebūna prakeiktas tas, kuris perkelia savo artimo riboženklį’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 18, '‘Tebūna prakeiktas tas, kuris daro, kad aklas nuklystų nuo kelio’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 19, '‘Tebūna prakeiktas tas, kuris iškreipia ateivio, našlaičio ir našlės teismą’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 20, '‘Tebūna prakeiktas tas, kuris sugula su savo tėvo žmona; nes jis atidengia savo tėvo skverną’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 21, '‘Tebūna prakeiktas tas, kuris sugula su kokiu nors gyvuliu’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 22, '‘Tebūna prakeiktas tas, kuris sugula su savo seserimi, savo tėvo dukterimi ar savo motinos dukterimi’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 23, '‘Tebūna prakeiktas tas, kuris sugula su savo uošve’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 24, '‘Tebūna prakeiktas tas, kuris slapta užmuša savo artimą’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 25, '‘Tebūna prakeiktas tas, kuris ima apdovanojimą, kad užmuštų nekaltą asmenį’. Ir visa tauta sakys: ‘Amen’.'),
  (@b5, 27, 26, '‘Tebūna prakeiktas tas, kuris nepatvirtina visų šito įstatymo žodžių, kad juos vykdytų’. Ir visa tauta sakys: ‘Amen’“.'),
  (@b5, 28, 1, '„Ir įvyks, jei stropiai klausysi VIEŠPATIES, savo Dievo, balso, kad laikytumeisi ir vykdytum visus jo įsakymus, kuriuos tau šią dieną įsakau, tada VIEŠPATS, tavo Dievas, iškels tave aukščiau visų žemės tautų;'),
  (@b5, 28, 2, 'ir visi šitie palaiminimai ateis ant tavęs ir pasivys tave, jei klausysi VIEŠPATIES, savo Dievo, balso.'),
  (@b5, 28, 3, 'Palaimintas būsi mieste ir palaimintas būsi ant lauko.'),
  (@b5, 28, 4, 'Palaimintas bus tavo kūno vaisius, tavo dirvos vaisius, tavo galvijų vaisius, tavo karvių prieaugis ir tavo avių kaimenės.'),
  (@b5, 28, 5, 'Palaimintas bus tavo krepšys ir tavo atsargos.'),
  (@b5, 28, 6, 'Palaimintas būsi įeidamas ir palaimintas būsi išeidamas.'),
  (@b5, 28, 7, 'VIEŠPATS padarys, kad tavo priešai, kurie kelsis prieš tave, būtų sumušti tavo akyse; vienu keliu jie išeis prieš tave, o septyniais keliais bėgs tavo akivaizdoje.'),
  (@b5, 28, 8, 'VIEŠPATS įsakys palaiminimui būti ant tavęs tavo sandėliuose ir visame, prie ko pridėsi savo ranką; ir jis tave laimins šalyje, kurią VIEŠPATS, tavo Dievas, tau duoda.'),
  (@b5, 28, 9, 'VIEŠPATS įtvirtins tave sau šventa tauta, kaip jis yra tau prisiekęs, jei laikysies VIEŠPATIES, savo Dievo, įsakymų ir vaikščiosi jo keliais.'),
  (@b5, 28, 10, 'Ir visos žemės tautos matys, kad tu esi vadinamas VIEŠPATIES vardu; ir jos bijos tavęs.'),
  (@b5, 28, 11, 'Ir VIEŠPATS padarys tave gausiu gėrybėmis, tavo kūno vaisiumi, tavo galvijų vaisiumi ir tavo dirvos vaisiumi, šalyje, kurią VIEŠPATS prisiekė tavo tėvams tau duoti.'),
  (@b5, 28, 12, 'VIEŠPATS tau atidarys savo gerąjį lobyną, dangų, kad duotų tavo šaliai lietaus jo metu ir palaimintų kiekvieną tavo rankų darbą: ir tu skolinsi daugeliui tautų, o pats nesiskolinsi.'),
  (@b5, 28, 13, 'Ir VIEŠPATS padarys tave galva, o ne uodega: tu būsi tik viršuje, o nebūsi apačioje; jei klausysi VIEŠPATIES, savo Dievo, įsakymų, kuriuos šią dieną tau įsakau jų laikytis ir juos vykdyti;'),
  (@b5, 28, 14, 'ir nenukrypk nei nuo vieno iš žodžių, kuriuos šią dieną tau įsakau, nei į dešinę, nei į kairę, eiti paskui kitus dievus, kad jiems tarnautum.'),
  (@b5, 28, 15, 'Bet įvyks, jei neklausysi VIEŠPATIES, savo Dievo, balso, kad laikytumeisi vykdydamas visus jo įsakymus ir įstatus, kuriuos šią dieną tau įsakau; tada visi šie prakeikimai ateis ant tavęs ir tave užklups:'),
  (@b5, 28, 16, 'prakeiktas būsi mieste ir prakeiktas būsi ant lauko.'),
  (@b5, 28, 17, 'Prakeiktas bus tavo krepšys ir tavo atsargos.'),
  (@b5, 28, 18, 'Prakeiktas bus tavo kūno vaisius, tavo žemės vaisius, tavo karvių prieaugis ir tavo avių kaimenės.'),
  (@b5, 28, 19, 'Prakeiktas būsi įeidamas ir prakeiktas būsi išeidamas.'),
  (@b5, 28, 20, 'VIEŠPATS pasiųs ant tavęs prakeikimą, priespaudą ir papeikimą visame, prie ko pridėsi savo ranką ką nors daryti, kol būsi sunaikintas ir kol greitai pražūsi; dėl nedorybės savo darbų, kuriais esi mane palikęs.'),
  (@b5, 28, 21, 'VIEŠPATS padarys, kad maras priliptų prie tavęs, iki jis bus tave išnaikinęs iš šalies, į kurią eini jos pasisavinti.'),
  (@b5, 28, 22, 'VIEŠPATS ištiks tave išsekimu, karštlige, uždegimu, svilinančia kaitra, kalaviju, džiovinančiu pūtimu ir pelėsiais; ir jie persekios tave kol pražūsi.'),
  (@b5, 28, 23, 'Ir tavo dangus, esantis viršum tavo galvos, bus žalvaris, o po tavimi esanti žemė – geležis.'),
  (@b5, 28, 24, 'VIEŠPATS pavers tavo šalies lietų smiltimis ir dulkėmis: iš dangaus jos kris ant tavęs, kol būsi sunaikintas.'),
  (@b5, 28, 25, 'VIEŠPATS padarys, kad būsi sumuštas savo priešų akivaizdoje: vienu keliu išeisi prieš juos, o septyniais keliais bėgsi jų akivaizdoje; ir būsi išsklaidytas po visas žemės karalystes.'),
  (@b5, 28, 26, 'Ir tavo lavonai bus maistas visiems oro skrajūnams ir žemės žvėrims, ir niekas jų nenubaidys.'),
  (@b5, 28, 27, 'VIEŠPATS tave ištiks Egipto votimis, hemorojumi, šašais ir niežais, nuo kurių negalėsi būti išgydytas.'),
  (@b5, 28, 28, 'VIEŠPATS tave ištiks pamišimu, aklumu ir širdies apstulbimu;'),
  (@b5, 28, 29, 'ir vidudienį grabaliosi, kaip aklas grabalioja tamsoje, ir neturėsi klestėjimo savo keliuose; ir visada būsi tik engiamas ir apiplėšiamas, ir niekas tavęs neišgelbės.'),
  (@b5, 28, 30, 'Susižadėsi su žmona, o kitas vyras suguls su ja; pastatysi namus, bet negyvensi juose; pasodinsi vynuogyną, bet nerinksi jo vynuogių.'),
  (@b5, 28, 31, 'Tavo jautis bus papjautas tavo akyse, bet tu jo nevalgysi; tavo asilas bus prievarta atimtas iš tavo akių ir nebus tau sugrąžintas; tavo avys bus duotos tavo priešams, ir neturėsi kas jas išgelbėtų.'),
  (@b5, 28, 32, 'Tavo sūnūs ir tavo dukterys bus atiduoti kitai tautai, o tavo akys žiūrės ir nusilps besiilgėdamos jų visą dieną; ir nebus jėgos tavo rankoje.'),
  (@b5, 28, 33, 'Tavo šalies vaisių ir visą tavo triūsą valgys tauta, kurios nepažinai; ir nuolatos būsi tik engiamas ir triuškinamas;'),
  (@b5, 28, 34, 'taip, kad išprotėsi dėl savo akių reginio, kurį matysi.'),
  (@b5, 28, 35, 'VIEŠPATS tave ištiks keliuose ir kojose piktomis votimis, kurios negali būti išgydomos, nuo tavo kojų padų iki tavo viršugalvio.'),
  (@b5, 28, 36, 'VIEŠPATS nuves tave ir tavo karalių, kurį virš savęs pasistatysi, pas tautą, kurios nepažinote nei tu, nei tavo tėvai; ir ten tarnausi kitiems dievams, medžiui ir akmeniui.'),
  (@b5, 28, 37, 'Ir tapsi nuostaba, patarle ir priežodžiu tarp visų tautų, pas kurias VIEŠPATS tave nuves.'),
  (@b5, 28, 38, 'Daug sėklos išneši į lauką, bet mažai surinksi; nes skėriai tai suės.'),
  (@b5, 28, 39, 'Pasodinsi vynuogynų ir juos įdirbsi, bet nei vyno negersi, nei vynuogių nesurinksi; nes kirminai juos nuės.'),
  (@b5, 28, 40, 'Turėsi alyvmedžių visose savo ribose, bet aliejumi nesitepsi; nes tavo alyvmedžiai nubarstys savo vaisių.'),
  (@b5, 28, 41, 'Pagimdysi sūnų ir dukterų, bet jais nesidžiaugsi; nes jie eis į nelaisvę.'),
  (@b5, 28, 42, 'Visus tavo medžius ir tavo šalies vaisių suės skėriai.'),
  (@b5, 28, 43, 'Ateivis, esantis tavo tarpe, iškils virš tavęs labai aukštai; o tu nusileisi labai žemai.'),
  (@b5, 28, 44, 'Jis tau skolins, o tu jam neskolinsi; jis bus galva, o tu būsi uodega.'),
  (@b5, 28, 45, 'Be to, visi šitie prakeikimai užeis ant tavęs, persekios tave ir užklups tave, kol būsi sunaikintas; nes neklausei VIEŠPATIES, savo Dievo, balso, kad laikytumeisi jo įsakymų ir jo įstatų, kuriuos jis tau įsakė;'),
  (@b5, 28, 46, 'ir jie bus ant tavęs ir ant tavo sėklos ženklu ir nuostaba per amžius.'),
  (@b5, 28, 47, 'Kadangi netarnavai VIEŠPAČIUI, savo Dievui, su džiaugsmu ir džiugia širdimi dėl visko gausybės;'),
  (@b5, 28, 48, 'todėl tarnausi savo priešams, kuriuos VIEŠPATS siųs prieš tave, badaudamas, trokšdamas, nuogume ir visko stokodamas; ir jis uždės geležies jungą tau ant sprando, kol bus tave sunaikinęs.'),
  (@b5, 28, 49, 'VIEŠPATS atves prieš tave tautą iš toli, iš žemės pakraščio, greitą kaip skrendantį erelį; tautą, kurios kalbos nesuprasi;'),
  (@b5, 28, 50, 'pikto veido tautą, kuri neatsižvelgs į seną asmenį ir neparodys palankumo jaunam;'),
  (@b5, 28, 51, 'ir ji suvalgys tavo galvijų vaisių ir tavo šalies vaisių, kol būsi sunaikintas; taip pat ji nepaliks tau nei javų, nei vyno, nei aliejaus, nei tavo karvių prieaugio, nei tavo avių kaimenių, kol bus tave sunaikinusi.'),
  (@b5, 28, 52, 'Ir ji apguls tave visuose tavo vartuose, kol sugrius tavo aukštos ir aptvertos sienos, kuriomis tu pasitiki, visoje tavo šalyje; ir ji apguls tave visuose tavo vartuose, visoje tavo šalyje, kurią VIEŠPATS, tavo Dievas, yra tau davęs.'),
  (@b5, 28, 53, 'Ir valgysi savo paties kūno vaisių, kūnus savo sūnų ir savo dukterų, kuriuos VIEŠPATS, tavo Dievas, yra tau davęs, apgulime ir prispaudime, kuriais tavo priešai tave vargins;'),
  (@b5, 28, 54, 'taip, kad vyras, kuris yra švelnus tarp jūsų ir labai išlepęs, jo akis žiūrės piktai į savo brolį ir į savo glėbio žmoną, ir į savo likusius vaikus, kuriuos jis paliks;'),
  (@b5, 28, 55, 'taip, kad nei vienam iš jų neduos savo vaikų kūno, kuriuos jis valgys; nes jam nieko nebus palikę apgulime ir prispaudime, kuriais tave vargins tavo priešai visuose tavo vartuose.'),
  (@b5, 28, 56, 'Švelni ir išlepusi moteris tarp jūsų, kuri nedrįstų padėti savo kojos pado ant žemės dėl lepumo ir švelnumo, jos akis piktai žiūrės į savo glėbio vyrą, į savo sūnų, į savo dukterį,'),
  (@b5, 28, 57, 'į savo jauniklį, išeinantį iš jos tarpkojo, ir į savo vaikus, kuriuos ji pagimdys; nes ji juos slapta valgys dėl visko stokos apgulime ir prispaudime, kuriais tavo priešas tave vargins tavo vartuose.'),
  (@b5, 28, 58, 'Jei nesilaikysi, kad vykdytum visus šito įstatymo žodžius, užrašytus šitoje knygoje, kad bijotum šito šlovingo ir baisaus vardo – VIEŠPATS, TAVO DIEVAS;'),
  (@b5, 28, 59, 'tuomet VIEŠPATS padarys tavo rykštes nuostabias ir tavo sėklos rykštes – dideles rykštes ir ilgai besitęsiančias, ir sunkias ligas, ir ilgai besitęsiančias.'),
  (@b5, 28, 60, 'Be to, jis užleis ant tavęs visas Egipto ligas, kurių tu bijojai; ir jos prilips prie tavęs.'),
  (@b5, 28, 61, 'Taip pat kiekvieną ligą ir kiekvieną rykštę, neužrašytą šito įstatymo knygoje, jas VIEŠPATS užleis ant tavęs, kol būsi sunaikintas.'),
  (@b5, 28, 62, 'Ir nors daugybe buvote kaip dangaus žvaigždės, jūsų išliks mažas skaičius; kadangi nepaklusai VIEŠPATIES, savo Dievo, balsui.'),
  (@b5, 28, 63, 'Ir įvyks, kaip VIEŠPATS džiaugėsi jumis, darydamas jums gera ir jus daugindamas; taip VIEŠPATS džiaugsis jumis, jus sunaikindamas ir jus paversdamas niekais; ir būsite išplėšti iš šalies, į kurią eini jos pasisavinti.'),
  (@b5, 28, 64, 'Ir VIEŠPATS išsklaidys tave tarp visų tautų nuo vieno žemės krašto iki kito; ir ten tarnausi kitiems dievams, kurių nei tu, nei tavo tėvai nepažinote, – medžiui ir akmeniui.'),
  (@b5, 28, 65, 'Ir tarp tų tautų nerasi poilsio, nei tavo kojos padas neturės poilsio; bet ten VIEŠPATS tau duos drebančią širdį, nusilpusias akis ir dvasios liūdesį;'),
  (@b5, 28, 66, 'ir tavo gyvybė kabės ant siūlo priešais tave; ir tu bijosi dieną bei naktį ir nebūsi tikras dėl savo gyvybės;'),
  (@b5, 28, 67, 'ryte sakysi: ‘O, kad būtų vakaras!’, o vakare sakysi: ‘O, kad būtų rytas!’ dėl savo širdies baimės, kuria bijosi, ir dėl savo akių reginio, kurį matysi.'),
  (@b5, 28, 68, 'Ir VIEŠPATS sugrąžins tave laivais į Egiptą tavo keliu, apie kurį tau kalbėjau: ‘Jo daugiau nebematysi’; ir ten parsidavinėsite savo priešams vergais ir vergėmis, bet niekas jūsų nepirks“.'),
  (@b5, 29, 1, 'Šitie yra žodžiai sandoros, kurią VIEŠPATS įsakė Mozei sudaryti su Izraelio vaikais Moabo šalyje neskaitant sandoros, kurią jis sudarė su jais Horebe.'),
  (@b5, 29, 2, 'Ir Mozė sušaukė visą Izraelį ir jiems tarė: „Jūs matėte viską, ką VIEŠPATS priešais jūsų akis padarė Egipto šalyje faraonui, visiems jo tarnams ir visai jo šaliai;'),
  (@b5, 29, 3, 'didelius gundymus, kuriuos matė tavo akys, ženklus ir anuos didelius stebuklus;'),
  (@b5, 29, 4, 'tačiau VIEŠPATS iki šios dienos nėra jums davęs širdies suprasti, akių matyti ir ausų girdėti.'),
  (@b5, 29, 5, 'Ir keturiasdešimt metų jus vedžiojau dykumoje: jūsų drabužiai nepaseno ant jūsų, ir tavo apavas nepaseno ant tavo kojos.'),
  (@b5, 29, 6, 'Nevalgėte duonos ir negėrėte vyno ar stipraus gėrimo; kad žinotumėte, jog aš esu VIEŠPATS, jūsų Dievas.'),
  (@b5, 29, 7, 'Ir kai atėjote į šią vietą, Hešbono karalius Sihonas ir Bašano karalius Ogas išėjo prieš mus į mūšį, o mes juos sumušėme;'),
  (@b5, 29, 8, 'ir paėmėme jų šalį ir ją davėme paveldu rubenams, gadams ir pusei Manaso genties.'),
  (@b5, 29, 9, 'Taigi laikykitės šitos sandoros žodžių ir juos vykdykite, kad klestėtumėte visame, ką darote.'),
  (@b5, 29, 10, 'Šią dieną jūs visi stovite VIEŠPATIES, savo Dievo, akivaizdoje: jūsų vadai jūsų genčių, jūsų vyresnieji ir jūsų pareigūnai, su visais Izraelio žmonėmis,'),
  (@b5, 29, 11, 'jūsų mažyliai, jūsų žmonos ir tavo ateivis, esantis tavo stovykloje, nuo tavo malkų kirtėjo iki tavo vandens sėmėjo;'),
  (@b5, 29, 12, 'kad įeitum į sandorą su VIEŠPAČIU, savo Dievu, ir į jo priesaiką, kurią VIEŠPATS, tavo Dievas, šią dieną sudaro su tavimi;'),
  (@b5, 29, 13, 'kad jis šiandien tave įtvirtintų sau kaip tautą, ir kad jis būtų tau Dievas, kaip yra tau kalbėjęs, ir kaip yra prisiekęs tavo tėvams: Abraomui, Izaokui ir Jokūbui.'),
  (@b5, 29, 14, 'Ne tik su jumis sudarau šią sandorą ir šią priesaiką;'),
  (@b5, 29, 15, 'bet su tuo, kuris šią dieną čia stovi su mumis VIEŠPATIES, mūsų Dievo, akivaizdoje, ir taip pat su tuo, kurio šią dieną čia nėra su mumis'),
  (@b5, 29, 16, '(nes jūs žinote, kaip gyvenome Egipto šalyje; ir kaip perėjome per tautas, kurias jūs perėjote;'),
  (@b5, 29, 17, 'ir matėte jų bjaurystes ir jų stabus, medį ir akmenį, sidabrą ir auksą, kurie buvo tarp jų);'),
  (@b5, 29, 18, 'kad nebūtų tarp jūsų vyro ar moters, ar šeimos, ar genties, kurio širdis šią dieną nusigręžtų nuo VIEŠPATIES, mūsų Dievo, jog nueitų ir tarnautų šitų tautų dievams; kad nebūtų tarp jūsų šaknies, duodančios tūlžį ir metėlę;'),
  (@b5, 29, 19, 'ir neįvyktų, kad išgirdęs šito prakeikimo žodžius jis laimins save širdyje, sakydamas: ‘Aš turėsiu ramybę, nors ir vaikštau pagal savo širdies sumanymus’, pridėdamas girtuokliavimą prie troškulio;'),
  (@b5, 29, 20, 'VIEŠPATS jo nesigailės, bet tada VIEŠPATIES pyktis ir jo pavydas rūks prieš tą žmogų, ir visi prakeikimai, užrašyti šitoje knygoje, užguls jį, ir VIEŠPATS išdildys jo vardą iš po dangaus.'),
  (@b5, 29, 21, 'Ir VIEŠPATS jį atskirs dėl pikto iš visų Izraelio genčių pagal visus sandoros prakeikimus, užrašytus šioje įstatymo knygoje;'),
  (@b5, 29, 22, 'kad ateinanti karta iš jūsų vaikų, kurie iškils po jūsų, ir ateivis, kuris ateis iš tolimos šalies, sakys, kai jie matys tos šalies rykštes ir ligas, kurias VIEŠPATS yra ant jos užleidęs;'),
  (@b5, 29, 23, 'ir kad visa jos šalis yra siera ir druska, ir išdeginimas, kuri neapsėta ir nieko neduodanti, ir jokia žolė joje neauga, kaip sugriovimas Sodomos ir Gomoros, Admos ir Ceboimo, kuriuos VIEŠPATS sugriovė savo pyktyje ir savo rūstybėje;'),
  (@b5, 29, 24, 'visos tautos sakys: ‘Kodėl VIEŠPATS taip padarė šitai šaliai? Ką reiškia šito didelio pykčio įkarštis?’'),
  (@b5, 29, 25, 'Tada sakys: ‘Kadangi jie paliko VIEŠPATIES, savo tėvų Dievo, sandorą, kurią jis sudarė su jais, išvedęs juos iš Egipto šalies;'),
  (@b5, 29, 26, 'nes jie nuėjo ir tarnavo kitiems dievams, ir garbino juos, dievus, kurių jie nepažinojo ir kurių jis nebuvo jiems davęs;'),
  (@b5, 29, 27, 'ir VIEŠPATIES pyktis užsidegė prieš šią šalį, kad užleistų ant jos visus prakeikimus, užrašytus šioje knygoje;'),
  (@b5, 29, 28, 'ir supykęs, užsirūstinęs ir smarkiai įnirtęs, VIEŠPATS juos išrovė iš jų šalies ir juos įmetė į kitą šalį, kaip yra šią dieną’.'),
  (@b5, 29, 29, 'Kas paslėpta, priklauso VIEŠPAČIUI, mūsų Dievui; o tai, kas apreikšta, priklauso mums ir mūsų vaikams per amžius, kad vykdytume visus šio įstatymo žodžius“.'),
  (@b5, 30, 1, '„Ir įvyks, kai ant tavęs ateis visi šie dalykai, palaiminimas ir prakeikimas, kuriuos išstačiau tavo akivaizdon, ir tu juos prisiminsi tarp visų tautų, kur VIEŠPATS, tavo Dievas, bus tave išvaręs,'),
  (@b5, 30, 2, 'ir sugrįši pas VIEŠPATĮ, savo Dievą, ir paklusi jo balsui tu ir tavo vaikai visa savo širdimi ir visa savo siela visame, ką aš šią dieną tau įsakau;'),
  (@b5, 30, 3, 'tada VIEŠPATS, tavo Dievas, nukreips tavo nelaisvę ir pasigailės tavęs, ir sugrįš bei surinks tave iš visų tautų, kur VIEŠPATS, tavo Dievas, buvo tave išsklaidęs.'),
  (@b5, 30, 4, 'Jei kas iš tavųjų būtų išvaryti į tolimiausius dangaus pakraščius, iš ten VIEŠPATS, tavo Dievas, tave surinks ir iš ten tave atves;'),
  (@b5, 30, 5, 'ir VIEŠPATS, tavo Dievas, tave nuves į šalį, kurią buvo pasisavinę tavo tėvai, ir tu ją pasisavinsi; ir jis darys tau gera ir padaugins tave daugiau už tavo tėvus.'),
  (@b5, 30, 6, 'Ir VIEŠPATS, tavo Dievas, apipjaustys tavo širdį ir tavo sėklos širdį, kad mylėtum VIEŠPATĮ, savo Dievą, visa savo širdimi ir visa savo siela, kad gyventum.'),
  (@b5, 30, 7, 'Ir VIEŠPATS, tavo Dievas, uždės visus šiuos prakeikimus ant tavo priešų ir ant tų, kurie tavęs nekenčia, kurie persekiojo tave.'),
  (@b5, 30, 8, 'Ir tu sugrįši ir paklusi VIEŠPATIES balsui ir vykdysi visus jo įsakymus, kuriuos šią dieną tau įsakau.'),
  (@b5, 30, 9, 'Ir VIEŠPATS, tavo Dievas, padarys tave gausiu kiekviename tavo rankos darbe, tavo kūno vaisiuje, tavo galvijų vaisiuje ir tavo šalies vaisiuje, dėl gero; nes VIEŠPATS vėl džiaugsis tavimi dėl gero, kaip jis džiaugėsi tavo tėvais;'),
  (@b5, 30, 10, 'jei klausysi VIEŠPATIES, savo Dievo, balso, kad laikytumeisi jo įsakymų ir jo įstatų, kurie yra užrašyti šioje įstatymo knygoje, ir jei atsigręši į VIEŠPATĮ, savo Dievą, visa savo širdimi ir visa savo siela.'),
  (@b5, 30, 11, 'Nes šis įsakymas, kurį šią dieną tau įsakau, nėra nuo tavęs paslėptas, ir nėra toli.'),
  (@b5, 30, 12, 'Jis ne danguje, kad sakytum: ‘Kas už mus pakils į dangų ir mums jį atneš, kad jį girdėtume ir vykdytume?’'),
  (@b5, 30, 13, 'Ir jis nėra už jūros, kad sakytum: ‘Kas už mus pereis jūrą ir mums jį atneš, kad jį girdėtume ir vykdytume?’'),
  (@b5, 30, 14, 'Bet tas žodis labai arti tavęs, tavo burnoje ir tavo širdyje, kad jį vykdytum.'),
  (@b5, 30, 15, 'Štai šią dieną išstačiau tavo akivaizdon gyvenimą ir gėrį, mirtį ir blogį;'),
  (@b5, 30, 16, 'tuo, kad tau šią dieną įsakau mylėti VIEŠPATĮ, savo Dievą, vaikščioti jo keliais ir laikytis jo įsakymų, jo įstatų ir jo teismų, kad gyventum ir daugintumeisi; ir VIEŠPATS, tavo Dievas, tave laimins šalyje, į kurią eini jos pasisavinti.'),
  (@b5, 30, 17, 'Bet jei nukryps tavo širdis, kad nebeklausysi, bet būsi atitrauktas ir garbinsi kitus dievus, ir jiems tarnausi;'),
  (@b5, 30, 18, 'tai jums šią dieną paskelbiu, kad tikrai pražūsite, ir neprailginsite savo dienų šalyje, į kurią eini per Jordaną, kad eitum jos pasisavinti.'),
  (@b5, 30, 19, 'Šią dieną šaukiu dangų ir žemę, kad liudytų prieš jus, jog išstačiau prieš jus gyvenimą ir mirtį, palaiminimą ir prakeikimą; taigi pasirink gyvenimą, kad gyventum, tu ir tavo sėkla;'),
  (@b5, 30, 20, 'kad mylėtum VIEŠPATĮ, savo Dievą, kad paklustum jo balsui ir kad prie jo priliptum; nes jis yra tavo gyvenimas ir tavo dienų ilgis; kad gyventum šalyje, kurią VIEŠPATS prisiekė tavo tėvams: Abraomui, Izaokui ir Jokūbui, jiems duoti“.'),
  (@b5, 31, 1, 'Ir Mozė nuėjo ir kalbėjo šituos žodžius visam Izraeliui.'),
  (@b5, 31, 2, 'Ir jis jiems tarė: „Šią dieną esu šimto dvidešimties metų; nebegaliu išeiti ir įeiti; taip pat VIEŠPATS yra man pasakęs: ‘Tu nepereisi per šitą Jordaną’.'),
  (@b5, 31, 3, 'VIEŠPATS, tavo Dievas, jis pereis tavo priešakyje ir išnaikins šitas tautas iš tavo akivaizdos, ir tu jas pasisavinsi; Jozuė pereis tavo priešakyje, kaip VIEŠPATS yra pasakęs.'),
  (@b5, 31, 4, 'Ir VIEŠPATS jiems padarys, kaip jis padarė Sihonui ir Ogui, amoritų karaliams, ir šaliai tų, kuriuos jis sunaikino.'),
  (@b5, 31, 5, 'Ir VIEŠPATS juos atiduos jūsų akyse, kad jiems padarytumėte pagal visus įsakymus, kuriuos esu jums įsakęs.'),
  (@b5, 31, 6, 'Būkite stiprūs ir drąsūs, nebijokite ir neišsigąskite jų; nes VIEŠPATS, tavo Dievas, jis yra tas, kuris eina su tavimi; jis tavęs neapvils ir nepaliks tavęs“.'),
  (@b5, 31, 7, 'Ir Mozė pašaukė Jozuę ir jam tarė viso Izraelio akyse: „Būk stiprus ir drąsus; nes turi eiti su šita tauta į šalį, kurią jiems duoti VIEŠPATS prisiekė jų tėvams; tu padarysi, kad jie ją paveldėtų.'),
  (@b5, 31, 8, 'Ir VIEŠPATS, jis yra tas, kuris eina tavo priešakyje; jis bus su tavimi, jis tavęs neapvils ir nepaliks tavęs; nebijok ir nesunerimk“.'),
  (@b5, 31, 9, 'Ir Mozė užrašė šitą įstatymą ir įteikė jį kunigams, Levio sūnums, kurie neša VIEŠPATIES Sandoros skrynią, ir visiems Izraelio vyresniesiems.'),
  (@b5, 31, 10, 'Ir Mozė jiems įsakė, sakydamas: „Kiekvienų septynerių metų pabaigoje, atleidimo metų iškilmėse, per Padangčių šventę,'),
  (@b5, 31, 11, 'kai visas Izraelis ateis pasirodyti VIEŠPATIES, tavo Dievo, akivaizdoje, vietoje, kurią jis išsirinks, skaitysi šitą įstatymą viso Izraelio priešakyje, jiems girdint.'),
  (@b5, 31, 12, 'Surink tautą, vyrus, moteris, vaikus ir savo ateivius, esančius tavo vartuose, kad jie girdėtų ir kad jie išmoktų, ir bijotų VIEŠPATIES, jūsų Dievo, ir laikytųsi vykdydami visus šito įstatymo žodžius;'),
  (@b5, 31, 13, 'ir kad jų vaikai, kurie nėra nieko pažinę, išgirstų ir išmoktų bijoti VIEŠPATIES, jūsų Dievo, tol, kol jūs gyvenate šalyje, į kurią einate per Jordaną jos pasisavinti“.'),
  (@b5, 31, 14, 'Ir VIEŠPATS tarė Mozei: „Štai artėja tavo dienos, kad mirtumei; pašauk Jozuę ir atsistokite susirinkimo padangtėje, kad jam duočiau įpareigojimą“. Ir Mozė bei Jozuė nuėjo ir atsistojo susirinkimo padangtėje.'),
  (@b5, 31, 15, 'Ir VIEŠPATS pasirodė padangtėje debesies stulpe; o debesies stulpas stovėjo virš padangtės durų.'),
  (@b5, 31, 16, 'Ir VIEŠPATS tarė Mozei: „Štai tu užmigsi prie savo tėvų; o šita tauta pakils ir nueis paleistuvaudama paskui dievus svetimšalių šalies, į kurią eina būti tarp jų, ir paliks mane, ir sulaužys mano sandorą, kurią sudariau su jais.'),
  (@b5, 31, 17, 'Tada tą dieną mano pyktis užsidegs prieš juos, ir aš juos paliksiu ir paslėpsiu nuo jų savo veidą, ir jie bus praryti, ir juos ištiks daug piktybių ir bėdų; kad jie tą dieną sakys: ‘Ar ne dėl to mus ištiko šitos piktybės, kad mūsų Dievo nėra tarp mūsų?’'),
  (@b5, 31, 18, 'Ir tą dieną visiškai paslėpsiu savo veidą dėl visų piktybių, kurias jie padarė, nukrypdami pas kitus dievus.'),
  (@b5, 31, 19, 'Todėl dabar užrašyk sau šitą giesmę ir jos mokyk Izraelio vaikus: įdėk ją į jų burnas, kad šita giesmė man būtų liudijimas prieš Izraelio vaikus.'),
  (@b5, 31, 20, 'Nes kai juos būsiu įvedęs į šalį, plūstančią pienu ir medumi, kurią prisiekiau jų tėvams; ir kai jie bus pavalgę, pasisotinę ir nutukę; tada jie nusigręš į kitus dievus, jiems tarnaus, mane kurstys ir sulaužys mano sandorą.'),
  (@b5, 31, 21, 'Ir įvyks, kai juos ištiks daug piktybių ir bėdų, šita giesmė liudys prieš juos kaip liudytojas; nes ji nebus pamiršta iš jų sėklos burnos; nes žinau jų sumanymus, ką jie ketina netgi dabar, prieš man juos įvedant į šalį, kurią prisiekiau“.'),
  (@b5, 31, 22, 'Taigi tą pačią dieną Mozė užrašė šitą giesmę ir jos mokė Izraelio vaikus.'),
  (@b5, 31, 23, 'Ir jis įpareigojo Nūno sūnų Jozuę ir tarė: „Būk stiprus ir geros drąsos; nes tu įvesi Izraelio vaikus į šalį, kurią jiems prisiekiau; o aš būsiu su tavimi“.'),
  (@b5, 31, 24, 'Ir įvyko, kai Mozė buvo baigęs rašyti į knygą šito įstatymo žodžius, kol jie buvo užbaigti,'),
  (@b5, 31, 25, 'Mozė įsakė levitams, kurie neša VIEŠPATIES Sandoros skrynią, sakydamas:'),
  (@b5, 31, 26, '„Imkite šitą įstatymo knygą ir ją padėkite VIEŠPATIES, savo Dievo, Sandoros skrynios šone, kad ten ji būtų kaip liudijimas prieš tave.'),
  (@b5, 31, 27, 'Nes aš žinau tavo maištingumą ir tavo kietasprandiškumą; štai man dar tebesant gyvam su jumis šią dieną, jūs buvote maištingi prieš VIEŠPATĮ; o kiek dar labiau po mano mirties!?'),
  (@b5, 31, 28, 'Surinkite pas mane visus savo genčių vyresniuosius ir savo pareigūnus, kad kalbėčiau šituos žodžius jiems į ausis ir šaukčiausi dangų ir žemę liudyti prieš juos.'),
  (@b5, 31, 29, 'Nes žinau, kad po mano mirties jūs visiškai sugadinsite save ir nukrypsite nuo to kelio, kurį esu jums įsakęs; ir paskutinėmis dienomis jus ištiks nelaimė; nes darysite, kas pikta VIEŠPATIES akyse, kurstydami jo pyktį savo rankų darbu“.'),
  (@b5, 31, 30, 'Ir Mozė kalbėjo visam Izraelio susirinkimui į ausis šitos giesmės žodžius, kol jie buvo užbaigti.'),
  (@b5, 32, 1, '„Palenkite ausį, o jūs, dangūs, o aš kalbėsiu; ir klausyk, o žeme, mano burnos žodžių.'),
  (@b5, 32, 2, 'Mano mokslas varvės kaip lietus, mano kalba lašės kaip rasa, kaip smulkus lietus ant gležnų žolių ir kaip liūtys ant žolės;'),
  (@b5, 32, 3, 'nes paskelbsiu VIEŠPATIES vardą; priskirkite didybę mūsų Dievui.'),
  (@b5, 32, 4, 'Jis yra Uola, tobulas jo darbas; nes visi jo keliai yra teismas: jis yra tiesos Dievas ir be jokios neteisybės, teisus ir teisingas.'),
  (@b5, 32, 5, 'Jie sugedo, jų dėmė nėra jo vaikų dėmė; jie yra iškrypusi ir sukta karta.'),
  (@b5, 32, 6, 'Ar taip atsilyginate VIEŠPAČIUI, o kvaila ir neišmintinga tauta? Argi ne jis tavo tėvas, kuris tave nupirko? Argi ne jis tave padarė ir tave įtvirtino?'),
  (@b5, 32, 7, 'Atsimink senovės dienas, apmąstyk daugelių kartų metus; paklausk savo tėvo, ir jis tau išdėstys; savo vyresniųjų, ir jie tau papasakos.'),
  (@b5, 32, 8, 'Kai Aukščiausiasis padalino tautoms jų paveldą, kai jis perskyrė Adomo sūnus, jis nustatė tautų ribas pagal Izraelio vaikų skaičių.'),
  (@b5, 32, 9, 'Nes VIEŠPATIES dalis yra jo tauta; Jokūbas yra jo paveldo sklypas.'),
  (@b5, 32, 10, 'Jis rado jį dykumos šalyje, tuščioje staugiančioje dykumoje; jis jį vedžiojo, mokė jį, saugojo jį kaip savo akies obuolį.'),
  (@b5, 32, 11, 'Kaip erelis išjudina savo lizdą, plasnoja viršum savo jauniklių, išskleidžia savo sparnus, juos paima, juos neša ant savo sparnų,'),
  (@b5, 32, 12, 'taip VIEŠPATS vienas jį vedė, ir nebuvo su juo svetimo dievo.'),
  (@b5, 32, 13, 'Padarė, kad jis jotų ant žemės aukštumų, kad valgytų laukų prieaugį; ir davė jam čiulpti medų iš uolos ir aliejų iš titnaginės uolos;'),
  (@b5, 32, 14, 'karvių sviestą ir avių pieną su avinėlių taukais, Bašano veislės avinų ir ožių su kviečių inkstų taukais; ir tu gėrei gryną vynuogių kraują.'),
  (@b5, 32, 15, 'Bet Ješurūnas nutuko ir spardėsi; tu nutukęs, sustorėjęs, aptekęs riebalais; tada jis paliko Dievą, kuris jį padarė, ir paniekino savo išgelbėjimo Uolą.'),
  (@b5, 32, 16, 'Jie kurstė jo pavydą svetimais dievais, bjaurystėmis kurstė jo pyktį.'),
  (@b5, 32, 17, 'Jie aukojo velniams, ne Dievui; dievams, kurių jie nepažino, naujiems dievams, naujai atėjusiems, kurių nebijojo jūsų tėvai.'),
  (@b5, 32, 18, 'Uolos, kuri tave pagimdė, neatsimeni ir esi pamiršęs Dievą, kuris tave suformavo.'),
  (@b5, 32, 19, 'Ir kai VIEŠPATS tai matė, jis bjaurėjosi jais dėl savo sūnų ir savo dukterų kurstymo.'),
  (@b5, 32, 20, 'Ir jis tarė: ‘Aš paslėpsiu nuo jų savo veidą, aš pamatysiu, koks bus jų galas; nes jie yra labai priešgyni karta, vaikai, kuriuose nėra tikėjimo.'),
  (@b5, 32, 21, 'Jie sukėlė man pavydą tuo, kas ne Dievas; jie kurstė mano pyktį savo tuštybėmis; ir aš jiems sukelsiu pavydą tais, kurie nėra tauta; sukurstysiu jiems pyktį kvailąja tauta.'),
  (@b5, 32, 22, 'Nes mano pyktyje užsidegė ugnis, ir degs iki žemiausio pragaro, ir praris žemę su jos prieaugiu, ir padegs kalnų pamatus.'),
  (@b5, 32, 23, 'Aš krausiu ant jų nelaimes; savo strėles išeikvosiu ant jų.'),
  (@b5, 32, 24, 'Jie bus bado sudeginti, suėsti deginančio karščio ir kartaus naikinimo; taip pat siųsiu ant jų žvėrių dantis su dulkių gyvačių nuodais.'),
  (@b5, 32, 25, 'Lauke kalavijas, o viduje siaubas sunaikins tiek jaunuolį, tiek mergelę, tiek ir žinduklį su žilagalviu.'),
  (@b5, 32, 26, 'Aš sakiau: „Aš juos išsklaidyčiau į pakampes, padaryčiau, kad liautųsi jų atminimas tarp žmonių“;'),
  (@b5, 32, 27, 'jei nebūčiau bijojęs priešo rūstybės, kad kartais jų priešininkai nesielgtų svetimai, kad jie nesakytų: „Mūsų ranka aukšta, VIEŠPATS viso to nepadarė“’.'),
  (@b5, 32, 28, 'Nes jie tauta, neturinti patarimo, ir nėra juose jokio supratimo.'),
  (@b5, 32, 29, 'O, kad jie būtų išmintingi, kad jie tai suprastų, kad jie apsvarstytų savo galą!'),
  (@b5, 32, 30, 'Kaip galėtų vienas vytis tūkstantį, o du priversti bėgti dešimt tūkstančių, jei jų Uola nebūtų jų pardavusi, jei VIEŠPATS nebūtų jų užrakinęs?'),
  (@b5, 32, 31, 'Nes jų uola nėra kaip mūsų Uola, net patiems mūsų priešams sprendžiant.'),
  (@b5, 32, 32, 'Nes jų vynmedis yra iš Sodomos vynmedžio ir iš Gomoros laukų; jų vynuogės – tulžies vynuogės, jų kekės karčios;'),
  (@b5, 32, 33, 'jų vynas – slibinų nuodai ir baisūs gyvačių nuodai.'),
  (@b5, 32, 34, '‘Ar tai ne pas mane sukaupta ir užantspauduota tarp mano lobynų?'),
  (@b5, 32, 35, 'Mano yra kerštas ir atlyginimas; jų koja paslys tinkamu laiku; nes jų didžiulės nelaimės diena yra arti, ir atskuba tai, kas juos ištiks’.'),
  (@b5, 32, 36, 'Nes VIEŠPATS teis savo tautą ir apgailestaus dėl savo tarnų, kai pamatys, kad išsekusios jų jėgos ir nebėra užrakinto ar palikto.'),
  (@b5, 32, 37, 'Ir jis sakys: ‘Kur yra jų dievai, jų uola, kuria jie pasitikėjo?'),
  (@b5, 32, 38, 'Kurie ėdė jų aukų taukus ir gėrė jų geriamųjų atnašų vyną? Tegul jie keliasi ir jums padeda, ir tebūna jūsų apsauga’.'),
  (@b5, 32, 39, '‘Matykite dabar, kad aš, būtent aš esu jis, ir nėra dievo šalia manęs; aš užmušu ir aš atgaivinu; aš sužeidžiu ir aš pagydau; nei vieno nėra, kuris galėtų išgelbėti iš mano rankos.'),
  (@b5, 32, 40, 'Nes aš pakeliu į dangų savo ranką ir sakau: „Aš gyvenu per amžius.'),
  (@b5, 32, 41, 'Jei aš pagaląsiu savo žibantį kalaviją ir mano ranka stversis teismo; aš atkeršysiu savo priešams ir atlyginsiu tiems, kurie manęs nekenčia.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b5, 32, 42, 'Aš nugirdysiu savo strėles krauju, o mano kalavijas rys kūną; krauju užmuštųjų ir belaisvių, nuo kerštų priešui pradžios“.'),
  (@b5, 32, 43, 'Džiaukitės, o jūs tautos, su jo tauta; nes jis atkeršys už savo tarnų kraują ir atsilygins kerštu savo priešininkams, ir bus gailestingas savo šaliai ir savo tautai’“.'),
  (@b5, 32, 44, 'Ir Mozė atėjo ir kalbėjo visus šitos giesmės žodžius tautai į ausis, jis ir Nūno sūnus Ošėja.'),
  (@b5, 32, 45, 'Ir Mozė baigė kalbėti visus šituos žodžius visam Izraeliui;'),
  (@b5, 32, 46, 'ir jis jiems tarė: „Pakreipkite savo širdis į visus žodžius, kuriuos šią dieną liudiju tarp jūsų, kuriuos įsakysite savo vaikams laikytis, kad vykdytų visus šito įstatymo žodžius.'),
  (@b5, 32, 47, 'Nes tai nėra jums tuščias dalykas; kadangi tai yra jūsų gyvenimas; ir per šitą dalyką jūs prailginsite savo dienas šalyje, į kurią einate per Jordaną jos pasisavinti“.'),
  (@b5, 32, 48, 'Ir tą pačią dieną VIEŠPATS kalbėjo Mozei, sakydamas:'),
  (@b5, 32, 49, '„Užlipk į šitą Abarimo kalną, į Nebo kalną, esantį Moabo šalyje priešais Jerichą; ir apžvelk Kanaano šalį, kurią duodu Izraelio vaikams nuosavybėn;'),
  (@b5, 32, 50, 'ir numirk tame kalne, į kurį įkopsi, ir būk surinktas prie savo tautos; kaip tavo brolis Aaronas mirė Horo kalne ir buvo surinktas prie savo tautos;'),
  (@b5, 32, 51, 'kadangi man nusižengėte tarp Izraelio vaikų prie Meriba-Kadešo vandenų Cino dykumoje; kadangi manęs nepašventėte Izraelio vaikų tarpe.'),
  (@b5, 32, 52, 'Tačiau pamatysi tą šalį priešais save; bet neisi ten į šalį, kurią duodu Izraelio vaikams“.'),
  (@b5, 33, 1, 'Ir šis yra palaiminimas, kuriuo Dievo vyras Mozė palaimino Izraelio vaikus prieš savo mirtį.'),
  (@b5, 33, 2, 'Ir jis tarė: „VIEŠPATS atėjo iš Sinajaus ir jiems patekėjo iš Seyro; jis spinduliavo nuo Parano kalno, ir atėjo su dešimčia tūkstančių šventųjų; iš jo dešinės ėjo jiems ugningas įstatymas.'),
  (@b5, 33, 3, 'Taip, jis pamilo tą tautą; visi jo šventieji yra tavo rankoje; jie atsisėdo prie tavo kojų; kiekvienas gaus iš tavo žodžių.'),
  (@b5, 33, 4, 'Mozė mums įsakė įstatymą, būtent Jokūbo susirinkimo paveldą.'),
  (@b5, 33, 5, 'Ir jis buvo karaliumi Ješurūne, kai susirinko tautos galvos su Izraelio gentimis.'),
  (@b5, 33, 6, 'Tegyvena Rubenas ir tenemiršta; ir tenebūna jo žmonių mažai“.'),
  (@b5, 33, 7, 'O šis yra Judos palaiminimas: ir jis tarė: „Išgirsk, VIEŠPATIE, Judos balsą ir atvesk jį pas jo tautą; jo rankų jam tepakanka; ir būk jam pagalba nuo jo priešų“.'),
  (@b5, 33, 8, 'O apie Levį jis pasakė: „Tavo Tumimas ir tavo Urimas tebūna su tavo šventuoju, kurį mėginai Masoje ir su kuriuo ginčijaisi prie Meribos vandenų;'),
  (@b5, 33, 9, 'kuris sakė savo tėvui ir savo motinai: ‘Nemačiau jo’; ir jis nepripažino savo brolių, ir nepažinojo savo vaikų; nes jis laikėsi tavo žodžio ir laikėsi tavo sandoros.'),
  (@b5, 33, 10, 'Jie mokys Jokūbą tavo teismų ir Izraelį tavo įstatymo; jie dės smilkalus tavo akivaizdoje ir visą deginamąją auką ant tavo aukuro.'),
  (@b5, 33, 11, 'Palaimink, VIEŠPATIE, jo turtą ir priimk jo rankų darbą; sutriuškink strėnas tų, kurie keliasi prieš jį, ir tų, kurie jo nekenčia, kad jie nebepakiltų“.'),
  (@b5, 33, 12, 'Apie Benjaminą jis pasakė: „VIEŠPATIES mylimasis saugiai prie jo gyvens; VIEŠPATS jį apdengs per visą dieną, ir jis gyvens tarp jo pečių“.'),
  (@b5, 33, 13, 'O apie Juozapą jis pasakė: „Jo žemė tebūna VIEŠPATIES palaiminta brangiais dangaus dalykais, rasa ir gelmėmis, gulinčiomis apačioje,'),
  (@b5, 33, 14, 'brangiais saulės atneštais vaisiais, brangiais mėnulio duodamais dalykais,'),
  (@b5, 33, 15, 'geriausiais senovės kalnų dalykais ir brangiais amžinųjų kalvų dalykais,'),
  (@b5, 33, 16, 'brangiais žemės ir jos pilnumo dalykais, ir geranoriškumu to, kuris gyveno krūme; tegul palaiminimas ateina ant Juozapo galvos, ant viršugalvio to, kuris buvo atskirtas nuo savo brolių.'),
  (@b5, 33, 17, 'Jo šlovė kaip jo jaučio pirmagimis, o jo ragai kaip vienaragių ragai: jais jis badys tautas drauge iki žemės pakraščių; o jie yra Efraimo tūkstančiai ir jie yra Manaso tūkstančiai“.'),
  (@b5, 33, 18, 'O apie Zebuloną jis pasakė: „Džiaukis, Zebulonai, savo išėjimais; ir, Isacharai, savo palapinėmis.'),
  (@b5, 33, 19, 'Jie pakvies tautą į kalną; ten jie aukos teisumo aukas; nes jie čiulps iš jūrų gausos ir iš smėlyje paslėptų lobių“.'),
  (@b5, 33, 20, 'O apie Gadą jis pasakė: „Palaimintas tebūna tas, kuris praplečia Gadą; jis gyvena kaip liūtas ir sudrasko ranką ir galvos viršugalvį.'),
  (@b5, 33, 21, 'Ir jis sau parūpino pirmąją dalį, nes ten, ant įstatymleidžio dalies, jis buvo pasodintas; ir jis atėjo su tautos galvomis, jis vykdė VIEŠPATIES teisingumą ir jo teismus su Izraeliu“.'),
  (@b5, 33, 22, 'O apie Daną jis pasakė: „Danas – liūto jauniklis; jis iššoks iš Bašano“.'),
  (@b5, 33, 23, 'O apie Naftalį jis pasakė: „O Naftali, pasotintas palankumu ir pilnas VIEŠPATIES palaiminimo; pasisavink vakarus ir pietus“.'),
  (@b5, 33, 24, 'O apie Ašerą jis pasakė: „Ašeras tebūna palaimintas vaikais; jis tebūna priimtinas savo broliams ir temirko aliejuje savo koją.'),
  (@b5, 33, 25, 'Tavo apavas bus geležis ir žalvaris; o tavo stiprybė bus tokia, kaip tavo dienos“.'),
  (@b5, 33, 26, '„Nėra lygaus Ješurūno Dievui, kuris joja ant dangaus tau į pagalbą ir savo didybe ant padangės.'),
  (@b5, 33, 27, 'Amžinasis Dievas yra tavo prieglobstis, o apačioje – amžinos rankos; ir jis išvarys priešą iš tavo akivaizdos; ir sakys: ‘Sunaikink juos’.'),
  (@b5, 33, 28, 'Izraelis tada saugiai gyvens pats vienas; Jokūbo šaltinis bus javų ir vyno šalyje; taip pat jo dangūs lašės rasa.'),
  (@b5, 33, 29, 'Laimingas tu, o Izraeli; kas yra toks, kaip tu, o tauta, išgelbėta VIEŠPATIES, tavo pagalbos skydo, ir kuris yra tavo puikybės kalavijas! ir tavo priešai rasis tau meluojantys; o tu mindysi jų aukštumas“.'),
  (@b5, 34, 1, 'Ir Mozė nuo Moabo lygumų ėjo aukštyn į Nebo kalną, į viršūnę Pisgos, esančios priešais Jerichą. Ir VIEŠPATS jam parodė visą Gileado šalį iki Dano,'),
  (@b5, 34, 2, 'visą Naftalį, Efraimo bei Manaso šalį ir visą Judos šalį iki tolimiausios jūros;'),
  (@b5, 34, 3, 'pietus, palmių miesto Jericho slėnio lygumą iki Coaro.'),
  (@b5, 34, 4, 'Ir VIEŠPATS jam tarė: „Šita yra šalis, kurią prisiekiau Abraomui, Izaokui ir Jokūbui, sakydamas: ‘Tavo sėklai ją duosiu’; tau daviau ją pamatyti tavo paties akimis, bet ten nepereisi“.'),
  (@b5, 34, 5, 'Taip VIEŠPATIES tarnas Mozė numirė ten Moabo šalyje, pagal VIEŠPATIES žodį.'),
  (@b5, 34, 6, 'Ir jis palaidojo jį slėnyje, Moabo šalyje priešais Bet-Peorą; bet niekas nežino jo kapo iki šios dienos.'),
  (@b5, 34, 7, 'O Mozė buvo šimto dvidešimties metų, kai jis mirė; jo akis nebuvo aptemusi, nei sumažėjusi jo jėga.'),
  (@b5, 34, 8, 'Ir Izraelio vaikai trisdešimt dienų apverkė Mozę Moabo lygumose; taip pasibaigė Mozės apraudojimo ir gedulo dienos.'),
  (@b5, 34, 9, 'O Nūno sūnus Jozuė buvo pilnas išminties dvasios; nes Mozė buvo uždėjęs ant jo savo rankas; ir Izraelio vaikai jo klausė ir darė, kaip VIEŠPATS įsakė Mozei.'),
  (@b5, 34, 10, 'Ir nuo to laiko nepakilo Izraelyje tokio pranašo kaip Mozė, kurį VIEŠPATS pažinojo veidas į veidą,'),
  (@b5, 34, 11, 'visais ženklais ir stebuklais, kuriuos VIEŠPATS jį siuntė daryti Egipto šalyje faraonui, visiems jo tarnams ir visai jo šaliai,'),
  (@b5, 34, 12, 'ir visa ta galinga ranka ir visu tuo didžiu siaubu, kurį Mozė parodė viso Izraelio akyse.'),
  (@b6, 1, 1, 'Na, o VIEŠPATIES tarnui Mozei mirus, įvyko, kad VIEŠPATS kalbėjo Nūno sūnui Jozuei, Mozės tarnui, sakydamas:'),
  (@b6, 1, 2, '„Mano tarnas Mozė yra miręs; taigi dabar kelkis, eik per šitą Jordaną, tu ir visa šita tauta į šalį, kurią duodu jiems – Izraelio vaikams.'),
  (@b6, 1, 3, 'Kiekvieną vietą, ant kurios užmins jūsų kojų padai, ją esu jums davęs, kaip sakiau Mozei.'),
  (@b6, 1, 4, 'Nuo dykumos ir šito Libano iki Didžiosios upės, Eufrato upės, visa hetitų šalis, ir iki Didžiosios jūros link saulėlydžio bus jūsų ribos.'),
  (@b6, 1, 5, 'Niekas nepajėgs atsilaikyti prieš tave per visas tavo gyvenimo dienas; kaip aš buvau su Moze, taip būsiu su tavimi: neapvilsiu ir nepaliksiu tavęs.'),
  (@b6, 1, 6, 'Būk stiprus ir drąsus; nes šitai tautai padalinsi paveldėjimui šalį, kurią jiems duoti prisiekiau jų tėvams.'),
  (@b6, 1, 7, 'Tik būk stiprus ir labai drąsus, kad laikytumeisi darydamas pagal visą įstatymą, kurį mano tarnas Mozė tau įsakė; nenukrypk nuo jo nei į dešinę, nei į kairę, kad tau sektųsi, kur tik eisi.'),
  (@b6, 1, 8, 'Tenepasitraukia šita įstatymo knyga nuo tavo burnos; bet mąstyk joje dieną ir naktį, kad laikytumeisi darydamas pagal viską, kas joje parašyta; nes tada padarysi savo kelią klestintį ir tada tau gerai seksis.'),
  (@b6, 1, 9, 'Argi tau neįsakiau: ‘Būk stiprus ir drąsus; nenusigąsk ir nebūk sunerimęs; nes VIEŠPATS, tavo Dievas, yra su tavimi, kur tik eini’?“'),
  (@b6, 1, 10, 'Tada Jozuė įsakė tautos pareigūnams, sakydamas:'),
  (@b6, 1, 11, '„Pereikite per kariuomenę ir įsakykite tautai, sakydami: ‘Paruoškite sau maisto; nes per tris dienas pereisite per šitą Jordaną, kad įeitumėte pasisavinti šalies, kurią VIEŠPATS, jūsų Dievas, jums duoda pasisavinti’“.'),
  (@b6, 1, 12, 'O rubenams, gadams ir pusei Manaso genties Jozuė kalbėjo, sakydamas:'),
  (@b6, 1, 13, '„Atsiminkite žodį, kurį jums įsakė VIEŠPATIES tarnas Mozė, sakydamas: ‘VIEŠPATS, jūsų Dievas, jums yra davęs poilsį ir jums yra davęs šitą šalį’.'),
  (@b6, 1, 14, 'Jūsų žmonos, jūsų mažyliai ir jūsų galvijai pasiliks šalyje, kurią Mozė jums davė šiapus Jordano; o jūs, visi galingi narsūs vyrai, apsiginklavę pereikite savo brolių priešakyje ir jiems padėkite;'),
  (@b6, 1, 15, 'kol VIEŠPATS duos poilsį jūsų broliams, kaip jis yra davęs jums, ir kol jie irgi bus pasisavinę šalį, kurią VIEŠPATS, jūsų Dievas, jiems duoda; tada sugrįžkite į savo nuosavybės šalį ir turėkite ją, kurią VIEŠPATIES tarnas Mozė jums davė šiapus Jordano saulėtekio link“.'),
  (@b6, 1, 16, 'Ir jie atsakė Jozuei, sakydami: „Viską, ką mums įsakai, darysime, ir visur, kur mus siųsi, eisime.'),
  (@b6, 1, 17, 'Kaip visuose dalykuose klausėme Mozės, taip ir tavęs klausysime; tik tebūna VIEŠPATS, tavo Dievas, su tavimi, kaip jis buvo su Moze.'),
  (@b6, 1, 18, 'Kiekvienas, kuris priešinsis tavo įsakymui ir neklausys tavo žodžių visame, ką jam įsakysi, tas bus užmuštas; tik būk stiprus ir drąsus“.'),
  (@b6, 2, 1, 'Ir Nūno sūnus Jozuė siuntė iš Šitimo du vyrus slapta ištirti, sakydamas: „Eikite, apžiūrėkite šalį, tai yra Jerichą“. Ir jie ėjo ir atėjo į namus paleistuvės, vardu Rahaba, ir ten nakvojo.'),
  (@b6, 2, 2, 'Ir buvo pasakyta Jericho karaliui, sakant: „Štai naktį čia atėjo vyrai iš Izraelio vaikų, šalies ištirti“.'),
  (@b6, 2, 3, 'Ir Jericho karalius siuntė pas Rahabą, sakydamas: „Išvesk vyrus, atėjusius pas tave, kurie yra įėję į tavo namus; nes jie atėjo visos šalies ištirti“.'),
  (@b6, 2, 4, 'O ta moteris paėmė tuos du vyrus ir juos paslėpė, ir taip tarė: „Buvo atėję pas mane vyrai, bet nežinau, iš kur jie buvo;'),
  (@b6, 2, 5, 'ir įvyko, kad maždaug vartų užrakinimo laiku, kai buvo tamsu, tie vyrai išėjo; aš nežinau, kur tie vyrai nuėjo; skubiai juos vykitės; nes pasivysite juos“.'),
  (@b6, 2, 6, 'Bet ji buvo juos užvedusi ant namo stogo ir paslėpusi linų stagarais, kuriuos ji buvo išguldžiusi ant stogo.'),
  (@b6, 2, 7, 'O tie vyrai juos vijosi keliu į Jordaną iki brastos; ir kai tik išėjo tie, kurie juos vijosi, užrakino vartus.'),
  (@b6, 2, 8, 'O jiems dar neatsigulus, ji užlipo pas juos ant stogo;'),
  (@b6, 2, 9, 'ir tarė tiems vyrams: „Žinau, kad VIEŠPATS jums yra davęs tą šalį ir kad mus apėmė siaubas dėl jūsų, ir kad visi tos šalies gyventojai alpsta dėl jūsų.'),
  (@b6, 2, 10, 'Nes esame girdėję, kaip VIEŠPATS, jums išėjus iš Egipto, išdžiovino jums Raudonosios jūros vandenį; ir ką padarėte dviems anapus Jordano esantiems amoritų karaliams, Sihonui ir Ogui, kuriuos visiškai sunaikinote.'),
  (@b6, 2, 11, 'Ir kai tik išgirdome šiuos dalykus, sutirpo mūsų širdys, ir nei viename nebeliko drąsos dėl jūsų; nes VIEŠPATS, jūsų Dievas, jis yra Dievas aukštai danguje ir žemai žemėje.'),
  (@b6, 2, 12, 'Taigi dabar, meldžiu jus, prisiekite man VIEŠPAČIU, kadangi aš parodžiau jums gerumą, tai ir jūs parodysite gerumą mano tėvo namams ir man duosite tikrą ženklą;'),
  (@b6, 2, 13, 'ir kad paliksite gyvus mano tėvą, mano motiną, mano brolius ir mano seseris bei viską, ką jie turi, ir išgelbėsite mūsų gyvybes nuo mirties“.'),
  (@b6, 2, 14, 'Ir tie vyrai jai atsakė: „Mūsų gyvybė bus už jūsų, jei neprasitarsite apie šitą mūsų reikalą. Ir bus, kai VIEŠPATS bus mums davęs tą šalį, mes gerai ir teisingai pasielgsime su tavimi“.'),
  (@b6, 2, 15, 'Tada ji nuleido juos virve pro langą; nes jos namai buvo ant miesto sienos, ji gyveno ant sienos.'),
  (@b6, 2, 16, 'Ir ji tarė jiems: „Eikite į kalną, kad jūsų nesutiktų tie persekiotojai; ir ten slapstykitės tris dienas, kol sugrįš persekiotojai; o paskui galėsite eiti savo keliu“.'),
  (@b6, 2, 17, 'Ir tie vyrai jai tarė: „Mes būsime nekalti dėl šitos tavo priesaikos, kuria mus prisaikdinai.'),
  (@b6, 2, 18, 'Štai mums ateinant į šalį, pririšk šitą virvę iš skaisčiai raudonų siūlų prie lango, pro kurį mus nuleidai; ir surink pas save į namus savo tėvą, savo motiną, savo brolius ir visus savo tėvo namiškius.'),
  (@b6, 2, 19, 'Ir bus, kad kiekvienas, kuris išeis į gatvę iš tavo namų durų, jo kraujas bus ant jo galvos, o mes būsime nekalti; o jei kuri ranka būtų ant to, kuris bus su tavimi namuose, jo kraujas bus ant mūsų galvos.'),
  (@b6, 2, 20, 'O jei prasitarsi apie šitą mūsų reikalą, tada mes būsime laisvi nuo tavo priesaikos, kuria mus prisaikdinai“.'),
  (@b6, 2, 21, 'Ir ji tarė: „Tebūna tai pagal jūsų žodžius“. Ir ji išleido juos, ir jie nuėjo; ir ji pririšo skaisčiai raudoną virvę prie lango.'),
  (@b6, 2, 22, 'Ir jie ėjo ir atėjo į kalną ir ten pasiliko tris dienas, kol sugrįžo tie persekiotojai; o persekiotojai ieškojo jų po visą kelią, bet nerado.'),
  (@b6, 2, 23, 'Taip tuodu vyrai grįžo ir nulipo nuo kalno, ir perėjo, ir atėję pas Nūno sūnų Jozuę jam papasakojo viską, kas jiems atsitiko;'),
  (@b6, 2, 24, 'ir jie sakė Jozuei: „Tikrai VIEŠPATS atidavė į mūsų rankas visą tą šalį; nes netgi visi tos šalies gyventojai alpsta dėl mūsų“.'),
  (@b6, 3, 1, 'Ir Jozuė atsikėlė anksti ryte; ir jie pasitraukė iš Šitimo ir atėjo prie Jordano, jis ir visi Izraelio vaikai, ir ten, prieš pereidami, apsinakvojo.'),
  (@b6, 3, 2, 'Ir įvyko, kad po trijų dienų pareigūnai ėjo per kariuomenę;'),
  (@b6, 3, 3, 'ir jie įsakė tautai, sakydami: „Kai pamatysite VIEŠPATIES, savo Dievo, Sandoros skrynią ir kunigus levitus ją nešant, traukitės iš savo vietos ir eikite paskui ją.'),
  (@b6, 3, 4, 'Tačiau tarp jūsų ir jos turi būti atstumas maždaug dviejų tūkstančių uolekčių matu; neprieikite prie jos arti, kad žinotumėte kelią, kuriuo turite eiti; nes anksčiau dar nesate ėję tuo keliu“.'),
  (@b6, 3, 5, 'Ir Jozuė tarė tautai: „Pasišvęskite, nes rytoj VIEŠPATS darys tarp jūsų nuostabas“.'),
  (@b6, 3, 6, 'Ir Jozuė kalbėjo kunigams, sakydamas: „Pakelkite Sandoros skrynią ir pereikite tautos priešakyje“. Ir jie pakėlė Sandoros skrynią ir ėjo tautos priešakyje.'),
  (@b6, 3, 7, 'Ir VIEŠPATS tarė Jozuei: „Šią dieną pradėsiu tave išaukštinti viso Izraelio akyse, kad jie žinotų, jog kaip aš buvau su Moze, taip būsiu su tavimi.'),
  (@b6, 3, 8, 'Ir tu įsakyk kunigams, nešantiems Sandoros skrynią, sakydamas: ‘Kai būsite priėję Jordano vandens kraštą, sustokite Jordane’“.'),
  (@b6, 3, 9, 'Ir Jozuė tarė Izraelio vaikams: „Ateikite čia ir klausykite VIEŠPATIES, savo Dievo, žodžių“.'),
  (@b6, 3, 10, 'Ir Jozuė tarė: „Iš to pažinosite, kad gyvasis Dievas yra tarp jūsų ir kad jis visiškai išvarys nuo jūsų veido kanaaniečius, hetitus, hivus, perizus, girgašus, amoritus ir jebusiečius.'),
  (@b6, 3, 11, 'Štai visos žemės Viešpaties Sandoros skrynia eina į Jordaną jūsų priešakyje.'),
  (@b6, 3, 12, 'Todėl dabar pasiimkite dvylika vyrų iš Izraelio genčių, iš kiekvienos genties po vyrą.'),
  (@b6, 3, 13, 'Ir įvyks, kai tik kunigų, nešančių VIEŠPATIES, visos žemės Viešpaties, skrynią, kojų padai ilsėsis Jordano vandenyse, tada Jordano vandenys bus atkirsti nuo vandenų, atitekančių žemyn iš aukšto; ir jie sustos į krūvą“.'),
  (@b6, 3, 14, 'Ir įvyko, kai tauta traukėsi nuo savo palapinių, kad pereitų per Jordaną, ir kunigai, nešantys Sandoros skrynią tautos priešakyje;'),
  (@b6, 3, 15, 'ir kai skrynią nešantieji atėjo prie Jordano, ir kai skrynią nešančių kunigų kojos įbrido į vandens kraštą (nes Jordanas užlieja visus savo krantus visu pjūties metu),'),
  (@b6, 3, 16, 'tada vandenys, tekantys žemyn iš viršaus, sustojo ir pakilo į krūvą labai toli nuo Adomo miesto, esančio šalia Cartano; o tekantys žemyn Lygumos jūros, tai yra Druskos jūros, link, išseko, buvo atkirsti; ir tauta perėjo tiesiai prieš Jerichą.'),
  (@b6, 3, 17, 'Ir kunigai, nešantys VIEŠPATIES Sandoros skrynią, tvirtai stovėjo ant sausos žemės Jordano viduryje, ir visi izraelitai perėjo sausa žeme, kol visa tauta visiškai perėjo per Jordaną.'),
  (@b6, 4, 1, 'Ir įvyko, kai visa tauta buvo visiškai perėjusi per Jordaną, VIEŠPATS kalbėjo Jozuei, sakydamas:'),
  (@b6, 4, 2, '„Pasiimkite iš tautos dvylika vyrų, iš kiekvienos genties po vyrą,'),
  (@b6, 4, 3, 'ir jiems įsakykite, sakydami: ‘Pasiimkite iš čia, iš Jordano vidurio, iš tos vietos, kur tvirtai stovėjo kunigų kojos, dvylika akmenų ir juos perneškite su savimi, ir juos palikite nakvynės vietoje, kur šiąnakt nakvosite’“.'),
  (@b6, 4, 4, 'Tada Jozuė pašaukė dvylika vyrų, kuriuos buvo paruošęs iš Izraelio vaikų, iš kiekvienos genties po vyrą;'),
  (@b6, 4, 5, 'ir Jozuė jiems tarė: „Nueikite VIEŠPATIES, jūsų Dievo, skrynios priešakin, į Jordano vidurį, ir užsikelkite kiekvienas iš jūsų po akmenį ant peties pagal Izraelio vaikų genčių skaičių;'),
  (@b6, 4, 6, 'kad tai būtų ženklas tarp jūsų, kad, kai ateinančiais laikais jūsų vaikai paklaus savo tėvų, sakydami: ‘Ką norite pasakyti šitais akmenimis?’,'),
  (@b6, 4, 7, 'tuomet atsakysite jiems, kad Jordano vandenys buvo atkirsti priešais VIEŠPATIES Sandoros skrynią; jai pereinant per Jordaną buvo atkirsti Jordano vandenys; o šitie akmenys bus Izraelio vaikams atminimas per amžius“.'),
  (@b6, 4, 8, 'Ir Izraelio vaikai padarė taip, kaip Jozuė įsakė, ir iškėlė dvylika akmenų iš Jordano vidurio, kaip VIEŠPATS kalbėjo Jozuei, pagal Izraelio vaikų genčių skaičių, ir pernešė juos su savimi į jų nakvynės vietą, ir ten juos padėjo.'),
  (@b6, 4, 9, 'O Jozuė pastatė dvylika akmenų Jordano viduryje, toje vietoje, kur stovėjo kojos kunigų, nešusių Sandoros skrynią; ir jie ten yra iki šios dienos.'),
  (@b6, 4, 10, 'Nes kunigai, nešantys skrynią, stovėjo Jordano viduryje, kol viskas buvo užbaigta, ką VIEŠPATS Jozuei įsakė kalbėti tautai, pagal visa tai, ką Mozė įsakė Jozuei; ir tauta pasiskubino ir perėjo.'),
  (@b6, 4, 11, 'Ir įvyko, kai visa tauta buvo visiškai perėjusi, tuomet perėjo VIEŠPATIES skrynia ir kunigai tautos akivaizdoje.'),
  (@b6, 4, 12, 'O Rubeno vaikai, Gado vaikai ir pusė Manaso genties, apsiginklavę perėjo Izraelio vaikų priešakyje, kaip Mozė jiems kalbėjo;'),
  (@b6, 4, 13, 'apie keturiasdešimt tūkstančių, pasiruošusių karui, perėjo VIEŠPATIES akivaizdoje mūšiui į Jericho lygumas.'),
  (@b6, 4, 14, 'Tą dieną VIEŠPATS išaukštino Jozuę viso Izraelio akyse; ir jie bijojo jo, kaip bijojo Mozės, per visas jo gyvenimo dienas.'),
  (@b6, 4, 15, 'Ir VIEŠPATS kalbėjo Jozuei, sakydamas:'),
  (@b6, 4, 16, '„Įsakyk kunigams, nešantiems Liudijimo skrynią, kad jie išliptų iš Jordano“.'),
  (@b6, 4, 17, 'Taigi Jozuė įsakė kunigams, sakydamas: „Išlipkite iš Jordano“.'),
  (@b6, 4, 18, 'Ir įvyko, kad kunigams, nešantiems VIEŠPATIES Sandoros skrynią, išlipus iš Jordano vidurio, ir kunigų kojų padams išsikėlus į sausumą, Jordano vandenys sugrįžo į savo vietą ir liejosi, kaip anksčiau, per visus savo krantus.'),
  (@b6, 4, 19, 'Ir tauta išlipo iš Jordano pirmojo mėnesio dešimtąją dieną ir stovyklavo Gilgale, Jericho rytinėje riboje.'),
  (@b6, 4, 20, 'O tuos dvylika akmenų, kuriuos jie paėmė iš Jordano, Jozuė pastatė Gilgale.'),
  (@b6, 4, 21, 'Ir jis kalbėjo Izraelio vaikams, sakydamas: „Kai ateinančiais laikais jūsų vaikai paklaus savo tėvų, sakydami: ‘Ką reiškia šitie akmenys?’,'),
  (@b6, 4, 22, 'tuomet duokite savo vaikams žinoti, sakydami: ‘Sausuma Izraelis perėjo per šitą Jordaną’.'),
  (@b6, 4, 23, 'Nes VIEŠPATS, jūsų Dievas, išdžiovino Jordano vandenis jūsų priešakyje, kol perėjote, kaip VIEŠPATS, jūsų Dievas, padarė Raudonajai jūrai, kurią jis išdžiovino mūsų priešakyje, kol perėjome;'),
  (@b6, 4, 24, 'kad visos žemės tautos žinotų VIEŠPATIES ranką, jog ji yra galinga; kad jūs amžinai bijotumėte VIEŠPATIES, savo Dievo“.'),
  (@b6, 5, 1, 'Ir įvyko, kai visi karaliai amoritų, esančių Jordano pusėje į vakarus, ir visi karaliai kanaaniečių, esančių palei jūrą, išgirdo, kad VIEŠPATS buvo išdžiovinęs Jordano vandenis Izraelio vaikų priešakyje, kol mes perėjome, tuomet jų širdis sutirpo, ir juose nebeliko dvasios dėl Izraelio vaikų.'),
  (@b6, 5, 2, 'Tuo laiku VIEŠPATS tarė Jozuei: „Pasidaryk aštrių peilių ir vėl, antrą kartą, apipjaustyk Izraelio vaikus“.'),
  (@b6, 5, 3, 'Ir Jozuė pasidarė aštrių peilių ir apipjaustė Izraelio vaikus prie Apyvarpių kalvos.'),
  (@b6, 5, 4, 'O šita yra priežastis, dėl kurios Jozuė apipjaustė: visa tauta, kuri išėjo iš Egipto, kurie buvo vyriškos lyties, tai yra visi karo vyrai, išmirė pakeliui dykumoje, kai išėjo iš Egipto.'),
  (@b6, 5, 5, 'Na, o visa išėjusi tauta buvo apipjaustyti; bet visos tautos, kuri gimė pakeliui dykumoje, jiems išėjus iš Egipto, jie neapipjaustė.'),
  (@b6, 5, 6, 'Nes Izraelio vaikai keturiasdešimt metų vaikščiojo dykumoje, kol visa tauta, kurie buvo karo vyrai, kurie išėjo iš Egipto, buvo sunaikinta, kadangi jie nepakluso VIEŠPATIES balsui; kuriems VIEŠPATS prisiekė, kad neparodys jiems šalies, kurią mums duoti VIEŠPATS buvo prisiekęs jų tėvams, šalį, plūstančią pienu ir medumi.'),
  (@b6, 5, 7, 'Ir jų vaikus, kuriuos jis prikėlė į jų vietą, tuos Jozuė apipjaustė; nes jie buvo neapipjaustyti, kadangi jie jų neapipjaustė pakeliui.'),
  (@b6, 5, 8, 'Ir įvyko, kai baigė apipjaustyti visą tautą, jie pasiliko savo vietose stovykloje, kol pasveiko.'),
  (@b6, 5, 9, 'Ir VIEŠPATS tarė Jozuei: „Šią dieną nuritinau nuo jūsų Egipto gėdą“. Todėl tą vietą vadina Gilgalo vardu iki šios dienos.'),
  (@b6, 5, 10, 'Ir stovyklaudami Gilgale, Izraelio vaikai šventė Apėjimą to mėnesio keturioliktąją dieną, vakare, Jericho lygumose.'),
  (@b6, 5, 11, 'O rytojaus dieną po Apėjimo jie valgė iš tos šalies senų javų, neraugintų pyragų ir paskrudintų grūdų tą pačią dieną.'),
  (@b6, 5, 12, 'Ir mana liovėsi kitą dieną po to, kai jie valgė iš tos šalies senų javų; ir Izraelio vaikai daugiau nebeturėjo manos; bet tais metais jie valgė iš Kanaano šalies vaisių.'),
  (@b6, 5, 13, 'Ir įvyko, kad būdamas prie Jericho Jozuė pakėlė akis ir žiūrėjo, ir štai priešais jį stovėjo vyras su ištrauktu kalaviju savo rankoje; ir Jozuė nuėjo prie jo ir jam tarė: „Ar tu už mus, ar už mūsų priešininkus?“'),
  (@b6, 5, 14, 'O jis tarė: „Ne; aš atėjau dabar kaip VIEŠPATIES kariuomenės vadas“. Ir Jozuė puolė veidu į žemę, pagarbino ir jam tarė: „Ką mano viešpats sako savo tarnui?“'),
  (@b6, 5, 15, 'Ir VIEŠPATIES kariuomenės vadas tarė Jozuei: „Nusiauk apavą nuo savo kojų; nes vieta, kurioje tu stovi, yra šventa“. Ir Jozuė taip padarė.'),
  (@b6, 6, 1, 'Na, o Jerichas buvo tvirtai užsirakinęs dėl Izraelio vaikų: niekas neišėjo, ir niekas neįėjo.'),
  (@b6, 6, 2, 'Ir VIEŠPATS tarė Jozuei: „Štai aš padaviau į tavo ranką Jerichą ir jo karalių, ir galingus narsuolius.'),
  (@b6, 6, 3, 'Ir apeikite miestą, visi jūs karo vyrai, eikite aplink miestą vieną sykį. Taip daryk šešias dienas.'),
  (@b6, 6, 4, 'O septyni kunigai neš skrynios priešakyje septynis avinų ragų trimitus; o septintąją dieną apeikite miestą septynis kartus, o kunigai pūs trimitus.'),
  (@b6, 6, 5, 'Ir įvyks, kad, ilgai pučiant avino ragą, kai išgirsite trimito garsą, visa tauta šauks didžiu šauksmu; ir sugrius miesto siena visiškai, ir tauta užlips, kiekvienas tiesiai priešais save“.'),
  (@b6, 6, 6, 'Ir Nūno sūnus Jozuė pašaukė kunigus ir jiems tarė: „Pakelkite Sandoros skrynią, o septyni kunigai tegul neša septynis avinų ragų trimitus VIEŠPATIES skrynios priešakyje“.'),
  (@b6, 6, 7, 'Ir jis tarė tautai: „Eikite pirmyn ir apeikite miestą, o kuris apsiginklavęs, tegul eina pirmyn VIEŠPATIES skrynios priešakyje“.'),
  (@b6, 6, 8, 'Ir įvyko, kai Jozuė buvo pakalbėjęs tautai, tada septyni kunigai, nešini septyniais avinų ragų trimitais, ėjo pirmyn VIEŠPATIES akivaizdoje ir pūtė trimitais; o VIEŠPATIES Sandoros skrynia sekė paskui juos.'),
  (@b6, 6, 9, 'Ir ginkluotieji ėjo priešakyje kunigų, pučiančių trimitais, o užnugaris ėjo paskui skrynią, kunigams einant ir pučiant trimitais.'),
  (@b6, 6, 10, 'Ir Jozuė buvo įsakęs tautai, sakydamas: „Nešaukite ir neišleiskite jokio garso savo balsu, ir teneišeina joks žodis iš jūsų burnos iki tos dienos, kai jums pasakysiu šaukti; tada šauksite“.'),
  (@b6, 6, 11, 'Taigi VIEŠPATIES skrynia apėjo miestą, einant aplinkui jį vienąkart; ir jie atėjo į stovyklą ir nakvojo stovykloje.'),
  (@b6, 6, 12, 'Ir Jozuė atsikėlė anksti ryte, o kunigai pakėlė VIEŠPATIES skrynią.'),
  (@b6, 6, 13, 'Ir septyni kunigai, septyniais avinų ragų trimitais nešini VIEŠPATIES skrynios priešakyje, be perstojo ėjo ir pūtė trimitais; o ginkluotieji ėjo jų priešakyje; bet užnugaris ėjo paskui VIEŠPATIES skrynią, kunigams einant ir pučiant trimitais.'),
  (@b6, 6, 14, 'Ir antrąją dieną jie apėjo miestą vienąkart ir sugrįžo į stovyklą: taip jie darė šešias dienas.'),
  (@b6, 6, 15, 'Ir įvyko septintąją dieną, kad jie atsikėlė anksti, dienai auštant, ir tokiu pat būdu apėjo miestą septynis kartus – vien tik tą dieną jie apėjo miestą septynis kartus.'),
  (@b6, 6, 16, 'Ir įvyko septintąjį kartą, kai kunigai pūtė trimitais, Jozuė tarė tautai: „Šaukite; nes VIEŠPATS jums davė tą miestą.'),
  (@b6, 6, 17, 'O tas miestas bus prakeiktas VIEŠPAČIUI, jis ir visa, kas yra jame; tik paleistuvė Rahaba gyvens, ji ir visi, esantys su ja namuose, nes ji paslėpė pasiuntinius, kuriuos buvome pasiuntę.'),
  (@b6, 6, 18, 'O jūs visais būdais saugokitės nuo prakeikto daikto, kad nepasidarytumėte prakeikti, imdami prakeiktą daiktą, ir nepadarytumėte Izraelio stovyklos prakeikimu ir jos nedrumstumėte.'),
  (@b6, 6, 19, 'Bet visas sidabras, auksas ir žalvario bei geležies indai yra pašvęsti VIEŠPAČIUI: jie įeis į VIEŠPATIES iždą“.'),
  (@b6, 6, 20, 'Taigi tauta šaukė, kai kunigai pūtė trimitais; ir įvyko, kai tauta išgirdo trimito garsą, ir tauta šaukė didžiu šauksmu, tada siena sugriuvo visiškai, taip, kad tauta užlipo į miestą, kiekvienas tiesiai prieš save, ir jie paėmė miestą.'),
  (@b6, 6, 21, 'Ir kalavijo ašmenimis jie visiškai išnaikino viską, kas buvo mieste, vyrus ir moteris, jaunus ir senus, jaučius, avis ir asilus.'),
  (@b6, 6, 22, 'Bet abiems vyrams, ištyrusiems tą šalį, Jozuė pasakė: „Įeikite į paleistuvės namus ir išveskite iš ten tą moterį ir visa, ką ji turi, kaip jai prisiekėte“.'),
  (@b6, 6, 23, 'Ir tie jaunuoliai, žvalgai, įėjo ir išvedė Rahabą, jos tėvą, jos motiną, jos brolius ir visa, ką ji turėjo; ir jie išvedė visus jos giminaičius ir juos paliko už Izraelio stovyklos.'),
  (@b6, 6, 24, 'Ir jie sudegino ugnimi miestą ir viską, kas buvo jame; tik sidabrą, auksą ir žalvario bei geležies indus jie padėjo į VIEŠPATIES namų iždą.'),
  (@b6, 6, 25, 'Ir Jozuė paliko gyvą paleistuvę Rahabą ir jos tėvo namiškius bei viską, ką ji turėjo; ir ji gyvena Izraelyje iki šios dienos; nes ji paslėpė pasiuntinius, kuriuos Jozuė siuntė Jericho ištirti.'),
  (@b6, 6, 26, 'Ir tuo laiku Jozuė juos prisaikdino, sakydamas: „Prakeiktas tebūna VIEŠPATIES akivaizdoje tas žmogus, kuris pakils ir statys šitą miestą Jerichą; jis dės jo pamatus ant savo pirmagimio, ir ant savo jauniausiojo sūnaus jis pastatys jo vartus“.'),
  (@b6, 6, 27, 'Taip VIEŠPATS buvo su Jozue; ir garsas apie jį pasklido po visą šalį.'),
  (@b6, 7, 1, 'Bet Izraelio vaikai įvykdė nusižengimą prakeiktu dalyku; nes Achanas, Zeracho sūnaus Zabdžio sūnaus Karmio sūnus iš Judos genties, paėmė iš to, kas prakeikta; ir VIEŠPATIES pyktis užsidegė prieš Izraelio vaikus.'),
  (@b6, 7, 2, 'Ir Jozuė siuntė vyrus iš Jericho į Ają, esantį šalia Bet-Aveno, rytinėje Bet-Elio pusėje, ir jiems kalbėjo, sakydamas: „Eikite aukštyn ir apžiūrėkite tą šalį“. Ir tie vyrai ėjo aukštyn ir apžiūrėjo Ają.'),
  (@b6, 7, 3, 'Ir jie sugrįžo pas Jozuę ir jam tarė: „Teneina aukštyn visa tauta; bet tegul eina aukštyn apie du ar tris tūkstančius vyrų ir sumuša Ają; neįdarbink ten visos tautos; nes jų tėra maža“.'),
  (@b6, 7, 4, 'Taip iš tautos ten aukštyn ėjo apie tris tūkstančius vyrų; bet jie bėgo Ajo vyrų akivaizdoje.'),
  (@b6, 7, 5, 'Ir Ajo vyrai išmušė iš jų apie trisdešimt šešis vyrus; nes jie juos vijosi nuo vartų priekio iki Šebarimo ir juos sumušė nusileidime; todėl sutirpo tautos širdys ir pasidarė kaip vanduo.'),
  (@b6, 7, 6, 'Ir Jozuė persiplėšė drabužius ir parpuolė veidu žemyn priešais VIEŠPATIES skrynią iki vakaro, jis ir Izraelio vyresnieji, ir apsibarstė galvas dulkėmis.'),
  (@b6, 7, 7, 'Ir Jozuė tarė: „Ak, Viešpatie DIEVE, kodėl iš viso pervedei šitą tautą per Jordaną, kad mus atiduotum į amoritų ranką mus sunaikinti? O, kad būtume pasitenkinę ir gyvenę anapus Jordano!'),
  (@b6, 7, 8, 'O Viešpatie, ką man sakyti, kai Izraelis atsuko nugaras savo priešų akivaizdoje?'),
  (@b6, 7, 9, 'Nes kanaaniečiai ir visi šalies gyventojai apie tai išgirs ir apsups mus, ir iškirs iš žemės mūsų vardą; ir ką darysi savo didžiajam vardui?“'),
  (@b6, 7, 10, 'Ir VIEŠPATS tarė Jozuei: „Kelkis; ko taip guli veidu žemyn?'),
  (@b6, 7, 11, 'Izraelis nusidėjo, ir taip pat jie nusižengė mano sandorai, kurią jiems įsakiau; nes jie paėmė iš to, kas prakeikta, ir pavogė, ir paslėpė, ir padėjo tai tarp savo pačių daiktų.'),
  (@b6, 7, 12, 'Todėl Izraelio vaikai negalėjo atsilaikyti savo priešų akivaizdoje, bet atsuko savo nugaras savo priešų akivaizdoje, nes jie buvo prakeikti; ir aš nebebūsiu su jumis, jei nesunaikinsite prakeikto iš jūsų tarpo.'),
  (@b6, 7, 13, 'Kelkis, pašvęsk tautą ir sakyk: ‘Pasišvęskite rytojui; nes taip sako VIEŠPATS, Izraelio Dievas: Tavo tarpe yra prakeiktas daiktas, o Izraeli; negalėsi atsilaikyti savo priešų akivaizdoje, kol nepašalinsite iš savo tarpo prakeikto daikto.'),
  (@b6, 7, 14, 'Taigi ryte būsite atvesti pagal savo gentis; ir bus, kad ta gentis, kurią VIEŠPATS paims, ateis pagal savo šeimas; o ta šeima, kurią VIEŠPATS paims, ateis namais; o tie namai, kuriuos VIEŠPATS paims, ateis po vieną žmogų.'),
  (@b6, 7, 15, 'Ir bus, kad tas, kuris bus paimtas su prakeiktu daiktu, bus sudegintas ugnimi, jis ir visa, ką jis turi; nes jis nusižengė VIEŠPATIES sandorai ir padarė beprotystę Izraelyje’“.'),
  (@b6, 7, 16, 'Taigi Jozuė atsikėlė anksti ryte ir atvedė Izraelį jų gentimis; ir buvo paimta Judos gentis;'),
  (@b6, 7, 17, 'ir jis privedė Judos šeimą; ir jis paėmė zerachų šeimą; ir jis privedė zerachų šeimą po vieną žmogų; ir buvo paimtas Zabdis;'),
  (@b6, 7, 18, 'ir jis privedė jo namus po vieną žmogų; ir buvo paimtas Zeracho sūnaus Zabdžio sūnaus Karmio sūnus Achanas iš Judos genties.'),
  (@b6, 7, 19, 'Ir Jozuė tarė Achanui: „Mano sūnau, meldžiu tave, duok VIEŠPAČIUI, Izraelio Dievui, šlovę ir atlik jam išpažintį; ir dabar man pasakyk, ką padarei; neslėpk to nuo manęs“.'),
  (@b6, 7, 20, 'Ir Achanas atsakydamas Jozuei tarė: „Iš tiesų aš nusidėjau prieš VIEŠPATĮ, Izraelio Dievą, ir padariau taip ir taip:'),
  (@b6, 7, 21, 'pamatęs tarp pagrobtų daiktų gražų babilonietišką rūbą ir du šimtus šekelių sidabro, ir penkiasdešimties šekelių svorio pleišto formos aukso gabalą, aš jų geidžiau ir juos paėmiau; ir štai jie yra paslėpti žemėje, mano palapinės viduryje, o sidabras yra po tuo“.'),
  (@b6, 7, 22, 'Taigi Jozuė siuntė pasiuntinius, ir jie nubėgo į palapinę; ir štai tai buvo paslėpta jo palapinėje, o sidabras po tuo.'),
  (@b6, 7, 23, 'Ir jie paėmė juos iš palapinės vidurio ir atnešė pas Jozuę ir pas visus Izraelio vaikus, ir juos padėjo VIEŠPATIES akivaizdoje.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b6, 7, 24, 'O Jozuė ir visas Izraelis su juo, paėmė Zeracho sūnų Achaną, sidabrą, rūbą, pleišto formos aukso gabalą, jo sūnus, jo dukteris, jo jaučius, jo asilus, jo avis, jo palapinę ir viską, ką jis turėjo; ir jie nuvedė juos į Achoro slėnį.'),
  (@b6, 7, 25, 'Ir Jozuė tarė: „Kodėl mus sudrumstei? VIEŠPATS šią dieną sudrums tave“. Ir visas Izraelis užmėtė jį akmenimis, ir sudegino juos ugnimi po to, kai buvo juos užmėtę akmenimis.'),
  (@b6, 7, 26, 'Ir jie pastatė virš jo didelę akmenų krūvą iki šios dienos. Taip VIEŠPATS nusigręžė nuo savo nuožmaus pykčio. Todėl tą vietą iki šios dienos vadina Achoro slėnio vardu.'),
  (@b6, 8, 1, 'Ir VIEŠPATS tarė Jozuei: „Nebijok ir nebūk sunerimęs; paimk su savimi visą karo tautą ir pakilęs eik aukštyn į Ają; štai aš padaviau į tavo ranką Ajo karalių, jo tautą, jo miestą ir jo šalį;'),
  (@b6, 8, 2, 'ir padaryk Ajui ir jo karaliui, kaip padarei Jerichui ir jo karaliui; tik jo išplėšas ir jo galvijus pasiimkite sau grobiu; pasistatyk miestui pasalą jo užnugaryje“.'),
  (@b6, 8, 3, 'Taigi pakilo Jozuė ir visa karo tauta eiti aukštyn prieš Ają; ir Jozuė išsirinko trisdešimt tūkstančių galingų narsuolių ir išsiuntė juos nakčia.'),
  (@b6, 8, 4, 'Ir jis įsakė jiems, sakydamas: „Štai jūs tykosite prieš tą miestą, to miesto užnugaryje; nenutolkite per daug nuo miesto, bet visi būkite pasiruošę;'),
  (@b6, 8, 5, 'o aš ir visa su manimi esanti tauta artinsimės prie miesto; ir įvyks, kai jie išeis prieš mus, kaip pirmąkart, tada mes bėgsime jų priešakyje'),
  (@b6, 8, 6, '(nes jie išeis paskui mus), kol juos atitrauksime nuo miesto; nes jie sakys: ‘Jie bėga mūsų priešakyje, kaip pirmąkart’; todėl mes bėgsime jų priešakyje.'),
  (@b6, 8, 7, 'Tuomet jūs kelkitės iš pasalų ir užimkite miestą; nes VIEŠPATS, jūsų Dievas, jį atiduos į jūsų ranką.'),
  (@b6, 8, 8, 'Ir bus, kai būsite paėmę miestą, padekite miestą; darykite pagal VIEŠPATIES įsakymą. Štai jums įsakiau“.'),
  (@b6, 8, 9, 'Taigi Jozuė juos išsiuntė; ir jie nuėjo tykoti pasaloje ir pasiliko tarp Bet-Elio ir Ajo, vakarinėje Ajo pusėje; bet Jozuė nakvojo tą naktį tautos tarpe.'),
  (@b6, 8, 10, 'Ir Jozuė atsikėlė anksti ryte, suskaičiavo tautą, ir ėjo aukštyn į Ają jis ir Izraelio vyresnieji tautos priešakyje.'),
  (@b6, 8, 11, 'Ir visa tauta, karo tauta, esanti su juo, ėjo aukštyn, prisiartino ir atėjo priešais miestą, ir stovyklavo šiaurinėje Ajo pusėje; na, o tarp jų ir Ajo buvo slėnis.'),
  (@b6, 8, 12, 'Ir jis, paėmęs apie penkis tūkstančius vyrų, sustatė juos tykoti pasaloje tarp Bet-Elio ir Ajo, vakarinėje miesto pusėje.'),
  (@b6, 8, 13, 'Ir kai jie sustatė tautą, tai yra visą kariuomenę, esančią į šiaurę nuo miesto, o jų tykotojus į vakarus nuo miesto, Jozuė tą naktį nuėjo į slėnio vidurį.'),
  (@b6, 8, 14, 'Ir įvyko, kad, Ajo karaliui tai pamačius, jie pasiskubino ir anksti atsikėlė, ir miesto vyrai išėjo į mūšį prieš Izraelį, jis ir visa jo tauta, sutartu laiku priešais lygumą; bet jis nežinojo, kad prieš jį buvo tykotojai pasaloje už miesto.'),
  (@b6, 8, 15, 'O Jozuė ir visas Izraelis dėjosi, tarsi jie buvo sumušti jų akivaizdoje ir bėgo dykumos keliu.'),
  (@b6, 8, 16, 'Ir visa Ajuje buvusi tauta buvo sušaukta jų vytis; ir jie vijosi Jozuę ir buvo atitraukti nuo miesto.'),
  (@b6, 8, 17, 'Ajuje ar Bet-Elyje nepasiliko nei vieno vyro, kuris nebūtų išėjęs paskui Izraelį; ir palikę miestą atvirą, jie vijosi Izraelį.'),
  (@b6, 8, 18, 'Ir VIEŠPATS tarė Jozuei: „Ištiesk tavo rankoje esančią ietį Ajo link; nes į tavo ranką jį duosiu“. Ir Jozuė ištiesė savo rankoje esančią ietį miesto link.'),
  (@b6, 8, 19, 'Ir pasala skubiai pakilo iš savo vietos ir bėgo, kai tik jis ištiesė savo ranką; ir jie įėjo į miestą ir jį paėmė, ir skubėjo, ir padegė miestą.'),
  (@b6, 8, 20, 'O Ajo vyrai pažvelgę atgal pamatė, ir štai miesto dūmai kilo į dangų, ir jie neturėjo jėgų bėgti nei šen, nei ten; o tauta, bėgusi į dykumą, atsisuko prieš persekiotojus.'),
  (@b6, 8, 21, 'Ir Jozuė ir visas Izraelis pamatę, kad pasala buvo paėmusi miestą ir kad kilo miesto dūmai, atsigręžė ir žudė Ajo vyrus.'),
  (@b6, 8, 22, 'O kiti išėjo iš miesto prieš juos; taip jie buvo Izraelio viduryje, vieniems iš tos pusės, o kitiems iš kitos pusės; ir jie sumušė juos taip, kad jie nedavė nei vienam iš jų išlikti ar pabėgti.'),
  (@b6, 8, 23, 'O Ajo karalių jie paėmė gyvą ir atvedė jį pas Jozuę.'),
  (@b6, 8, 24, 'Ir įvyko, kad, Izraeliui baigus žudyti visus Ajo gyventojus lauke, dykumoje, kur jie buvo nusiviję juos, ir jiems visiems kritus ant kalavijo ašmenų, kol buvo sunaikinti, visi izraelitai sugrįžo į Ają ir jį sumušė kalavijo ašmenimis.'),
  (@b6, 8, 25, 'Ir buvo, kad iš viso tą dieną kritusių vyrų ir moterų buvo dvylika tūkstančių, tai yra visi Ajo žmonės.'),
  (@b6, 8, 26, 'Nes Jozuė neatitraukė savo rankos, kuria buvo ištiesęs ietį, kol visiškai nesunaikino visų Ajo gyventojų.'),
  (@b6, 8, 27, 'Tik galvijus ir to miesto grobį Izraelis pasiėmė kaip laimikį pagal VIEŠPATIES žodį, kurį jis įsakė Jozuei.'),
  (@b6, 8, 28, 'Ir Jozuė sudegino Ają ir jį padarė amžina krūva – dykyne iki šios dienos.'),
  (@b6, 8, 29, 'O Ajo karalių jis pakorė ant medžio iki vakaro; ir vos tik saulei nusileidus, Jozuė įsakė, kad jie nuimtų jo lavoną nuo medžio ir numestų jį prie miesto vartų įėjimo, ir ant jo sukrautų didelę akmenų krūvą, kuri išliko iki šios dienos.'),
  (@b6, 8, 30, 'Tada Jozuė pastatė aukurą VIEŠPAČIUI, Izraelio Dievui, Ebalo kalne,'),
  (@b6, 8, 31, 'kaip VIEŠPATIES tarnas Mozė įsakė Izraelio vaikams, kaip yra parašyta Mozės įstatymo knygoje, aukurą iš sveikų akmenų, virš kurių niekas nebuvo pakėlęs jokios geležies; ir jie atnašavo ant jo deginamąsias atnašas VIEŠPAČIUI ir aukojo taikos atnašas.'),
  (@b6, 8, 32, 'Ir ten jis užrašė ant akmenų Mozės įstatymo kopiją, kurią jis užrašė Izraelio vaikų akivaizdoje.'),
  (@b6, 8, 33, 'O visas Izraelis, jų vyresnieji, pareigūnai ir jų teisėjai stovėjo šiame ir kitame skrynios šone priešais kunigus levitus, kurie neša VIEŠPATIES Sandoros skrynią, kaip ateivis, taip ir tarp jų gimęs: pusė jų priešais Gerizimo kalną ir pusė jų priešais Ebalo kalną; kaip VIEŠPATIES tarnas Mozė buvo anksčiau įsakęs, kad jie laimintų Izraelio tautą.'),
  (@b6, 8, 34, 'O po to jis perskaitė visus įstatymo žodžius, palaiminimus ir prakeikimus, pagal visa tai, kas parašyta įstatymo knygoje.'),
  (@b6, 8, 35, 'Iš viso to, ką Mozė įsakė, nebuvo nei vieno žodžio, kurio Jozuė nebūtų perskaitęs akivaizdoje viso Izraelio susirinkimo su moterimis, mažyliais bei ateiviais, bendraujančiais tarp jų.'),
  (@b6, 9, 1, 'Ir įvyko, kad tai išgirdę visi karaliai, esantys šiapus Jordano, kalvose, slėniuose ir visuose Didžiosios jūros pakraščiuose priešais Libaną: hetitai, amoritai, kanaaniečiai, perizai, hivai ir jebusiečiai;'),
  (@b6, 9, 2, 'vieningai susirinko kovoti su Jozue ir Izraeliu.'),
  (@b6, 9, 3, 'O Gibeono gyventojai išgirdę, ką Jozuė buvo padaręs Jerichui ir Ajui,'),
  (@b6, 9, 4, 'gudriai pasielgė ir nuėję dėjosi esą pasiuntiniai, ir ėmė senų maišų ant savo asilų, senų, suplyšusių ir apraišiotų vyno indų;'),
  (@b6, 9, 5, 'seną, sulopytą apavą ant savo kojų ir senus drabužius ant savęs; ir visa jų atsargų duona buvo sudžiūvusi ir supelėjusi.'),
  (@b6, 9, 6, 'Ir jie nuėjo pas Jozuę į stovyklą Gilgale ir sakė jam ir Izraelio žmonėms: „Mes esame atėję iš tolimos šalies; taigi dabar padarykite su mumis sąjungą“.'),
  (@b6, 9, 7, 'O Izraelio žmonės tarė hivams: „Galbūt jūs gyvenate tarp mūsų; ir kaip mes sudarysime sąjungą su jumis?“'),
  (@b6, 9, 8, 'Ir jie tarė Jozuei: „Mes esame tavo tarnai“. O Jozuė jiems tarė: „Kas jūs ir iš kur atėjote?“'),
  (@b6, 9, 9, 'O jie jam tarė: „Iš labai tolimos šalies yra atėję tavo tarnai dėl VIEŠPATIES, tavo Dievo, vardo; nes mes esame girdėję garsą apie jį ir viską, ką jis padarė Egipte,'),
  (@b6, 9, 10, 'ir viską, ką jis padarė dviems amoritų karaliams, esantiems anapus Jordano: Hešbono karaliui Sihonui ir Bašano karaliui Ogui, buvusiam Aštarote.'),
  (@b6, 9, 11, 'Todėl mūsų vyresnieji ir visi mūsų šalies gyventojai mums kalbėjo, sakydami: ‘Pasiimkite su savimi maisto kelionei ir eikite jų sutikti, ir jiems sakykite: „Mes esame jūsų tarnai; taigi dabar sudarykite su mumis sąjungą“.'),
  (@b6, 9, 12, 'Šitą mūsų duoną mes pasiėmėme dar karštą iš savo namų mūsų atsargoms tą dieną, kai išvykome, kad eitume pas jus; bet dabar štai ji yra sudžiūvusi ir supelėjusi;'),
  (@b6, 9, 13, 'o šitie vyno indai, kuriuos prisipylėme, buvo nauji; ir štai jie suplyšę; o šitie mūsų drabužiai ir mūsų apavas paseno dėl labai ilgos kelionės“.'),
  (@b6, 9, 14, 'Ir vyrai paėmė jų maistą, bet nepasiklausė VIEŠPATIES burnos patarimo.'),
  (@b6, 9, 15, 'Ir Jozuė sudarė su jais taiką ir sudarė su jais sąjungą, kad leis jiems gyventi; ir susirinkimo kunigaikščiai jiems prisiekė.'),
  (@b6, 9, 16, 'Ir įvyko, jog, praėjus trims dienoms po to, kai jie buvo sudarę su jais sąjungą, jie išgirdo, kad tie buvo jų kaimynai ir kad jie gyveno tarp jų.'),
  (@b6, 9, 17, 'Ir Izraelio vaikai keliavo ir atvyko trečiąją dieną į jų miestus. Na, o jų miestai buvo Gibeonas, Kefyra, Beerotas ir Kirjat-Jearimas.'),
  (@b6, 9, 18, 'Ir Izraelio vaikai nesumušė jų, nes susirinkimo kunigaikščiai jiems buvo prisiekę VIEŠPAČIU, Izraelio Dievu. Ir visas susirinkimas murmėjo prieš kunigaikščius.'),
  (@b6, 9, 19, 'Bet visi kunigaikščiai tarė visam susirinkimui: „Mes esame jiems prisiekę VIEŠPAČIU, Izraelio Dievu; todėl dabar negalime jų liesti.'),
  (@b6, 9, 20, 'Jiems tai padarysime: paliksime juos gyvus, kad nebūtų ant mūsų rūstybės, dėl priesaikos, kurią esame jiems prisiekę“.'),
  (@b6, 9, 21, 'Ir kunigaikščiai jiems sakė: „Tegul jie gyvena; bet tegul jie būna medkirčiais ir vandens sėmėjais visam susirinkimui“; kaip kunigaikščiai jiems buvo pažadėję.'),
  (@b6, 9, 22, 'Ir Jozuė juos pasišaukė ir jiems kalbėjo, sakydamas: „Kodėl mus apgavote, sakydami: ‘Mes esame labai toli nuo jūsų’, nors jūs gyvenate tarp mūsų?'),
  (@b6, 9, 23, 'Todėl dabar jūs esate prakeikti, ir nei vienas iš jūsų nebus išlaisvintas iš buvimo vergais, medkirčiais ir vandens sėmėjais mano Dievo namams“.'),
  (@b6, 9, 24, 'O jie atsakydami Jozuei tarė: „Kadangi tavo tarnams buvo tikrai pasakyta, kaip VIEŠPATS, tavo Dievas, įsakė savo tarnui Mozei jums duoti visą tą šalį ir išnaikinti jums iš akivaizdos visus tos šalies gyventojus, todėl mes labai bijojome jūsų dėl savo gyvybių, ir tai padarėme.'),
  (@b6, 9, 25, 'O dabar, štai mes esame tavo rankoje; daryk mums, kaip tau atrodo gera ir teisinga daryti“.'),
  (@b6, 9, 26, 'Ir taip jis jiems padarė ir išgelbėjo juos iš Izraelio vaikų rankos, kad tie jų neišžudytų.'),
  (@b6, 9, 27, 'Ir tą dieną Jozuė juos padarė medkirčiais ir vandens sėmėjais susirinkimui ir VIEŠPATIES aukurui iki šios dienos toje vietoje, kurią jis išsirinks.'),
  (@b6, 10, 1, 'Na, o įvyko, kai Jeruzalės karalius Adoni-Cedekas išgirdo, kaip Jozuė buvo paėmęs Ają ir buvo visiškai jį sunaikinęs; kaip jis buvo padaręs Jerichui ir jo karaliui, taip jis padarė Ajui ir jo karaliui; ir kaip Gibeono gyventojai buvo sudarę taiką su Izraeliu ir buvo tarp jų;'),
  (@b6, 10, 2, 'tuomet jie labai bijojo, kadangi Gibeonas buvo didelis miestas, kaip vienas iš karališkųjų miestų, ir kadangi jis buvo didesnis už Ają, o visi jo vyrai buvo galingi.'),
  (@b6, 10, 3, 'Todėl Jeruzalės karalius Adoni-Cedekas pasiuntė Hebrono karaliui Hohamui, Jarmuto karaliui Piramui, Lachišo karaliui Jafijui ir Eglono karaliui Debyrui, sakydamas:'),
  (@b6, 10, 4, '„Ateikite aukštyn pas mane ir padėkite man, kad sumuštume Gibeoną; nes jis sudarė taiką su Jozue ir su Izraelio vaikais“.'),
  (@b6, 10, 5, 'Todėl susirinkę penki amoritų karaliai, Jeruzalės karalius, Hebrono karalius, Jarmuto karalius, Lachišo karalius, Eglono karalius, ėjo aukštyn, jie ir visos jų kariuomenės, ir stovyklavo prieš Gibeoną ir kariavo prieš jį.'),
  (@b6, 10, 6, 'O Gibeono žmonės pasiuntė Jozuei į stovyklą, į Gilgalą, sakydami: „Nesulėtink savo tarnams savo rankos; skubiai ateik pas mus aukštyn, išgelbėk mus ir padėk mums; nes prieš mus susirinko visi amoritų karaliai, gyvenantys kalnuose“.'),
  (@b6, 10, 7, 'Taigi Jozuė kilo iš Gilgalo aukštyn, jis ir su juo visa karo tauta, visi galingi narsuoliai.'),
  (@b6, 10, 8, 'Ir VIEŠPATS tarė Jozuei: „Nebijok jų; nes juos padaviau į tavo ranką; nei vienas iš jų neatsilaikys prieš tave“.'),
  (@b6, 10, 9, 'Taigi Jozuė juos užpuolė staiga, visą naktį ėjęs aukštyn iš Gilgalo.'),
  (@b6, 10, 10, 'Ir VIEŠPATS juos sutrikdė Izraelio akivaizdoje ir žudė juos didelėmis žudynėmis Gibeone, ir juos vijosi keliu, einančiu aukštyn į Bet-Horoną, ir juos mušė iki Azekos ir Makedos.'),
  (@b6, 10, 11, 'Ir įvyko, kad, jiems bėgant nuo Izraelio akivaizdos ir būnant ant nusileidimo į Bet-Horoną, VIEŠPATS mėtė ant jų didelius akmenis iš dangaus iki Azekos, ir jie žuvo; daugiau buvo tų, kurie žuvo nuo krušos akmenų, negu tų, kuriuos Izraelio vaikai išžudė kalaviju.'),
  (@b6, 10, 12, 'Tada Jozuė kalbėjo VIEŠPAČIUI tą dieną, kai VIEŠPATS atidavė amoritus Izraelio vaikų akivaizdoje, ir jis tarė Izraelio akyse: „Saule, sustok Gibeone; ir tu, Mėnuli, Ajalono slėnyje“.'),
  (@b6, 10, 13, 'Ir saulė sustojo, ir mėnulis stovėjo, kol tauta atkeršijo savo priešams. Argi tai neparašyta Jašero knygoje? Taip saulė stovėjo nejudėdama dangaus viduryje ir neskubėjo nusileisti beveik visą dieną.'),
  (@b6, 10, 14, 'Ir nėra buvę tokios dienos kaip ta, nei prieš ją, nei po jos, kad VIEŠPATS būtų klausęs žmogaus balso; nes VIEŠPATS kovojo už Izraelį.'),
  (@b6, 10, 15, 'Ir sugrįžo Jozuė ir visas Izraelis su juo stovyklon į Gilgalą.'),
  (@b6, 10, 16, 'Bet tie penki karaliai pabėgo ir pasislėpė oloje, Makedoje.'),
  (@b6, 10, 17, 'Ir buvo pasakyta Jozuei, sakant: „Tie penki karaliai rasti pasislėpę oloje, Makedoje“.'),
  (@b6, 10, 18, 'Ir Jozuė tarė: „Užritinkite didelius akmenis ant olos angos ir pastatykite prie jos vyrus, kad juos saugotų;'),
  (@b6, 10, 19, 'o jūs nestovėkite, bet vykitės savo priešus ir muškite jų užnugarį; neleiskite jiems įeiti į jų miestus; nes VIEŠPATS, jūsų Dievas, juos atidavė į jūsų ranką“.'),
  (@b6, 10, 20, 'Ir įvyko, kai Jozuė ir Izraelio vaikai užbaigė juos žudyti labai smarkiomis žudynėmis, kol jie buvo sunaikinti, tada likusieji, kurie iš jų išliko, įėjo į aptvertus miestus.'),
  (@b6, 10, 21, 'Ir visa tauta sugrįžo ramybėje į stovyklą pas Jozuę į Makedą; niekas nepajudino savo liežuvio nei prieš vieną iš Izraelio vaikų.'),
  (@b6, 10, 22, 'Paskui Jozuė tarė: „Atidarykite olos angą ir išveskite iš olos pas mane tuos penkis karalius“.'),
  (@b6, 10, 23, 'Ir jie taip padarė ir išvedė iš olos pas jį tuos penkis karalius: Jeruzalės karalių, Hebrono karalių, Jarmuto karalių, Lachišo karalių ir Eglono karalių.'),
  (@b6, 10, 24, 'Ir įvyko, kad, jiems išvedus tuos karalius pas Jozuę, Jozuė sušaukė visus Izraelio vyrus ir sakė karo vyrų vadams, ėjusiems su juo: „Priartėkite, uždėkite savo kojas šitiems karaliams ant sprandų“. Ir jie priartėjo ir uždėjo savo kojas jiems ant sprandų.'),
  (@b6, 10, 25, 'Ir Jozuė jiems tarė: „Nebijokite ir nebūkite sunerimę, būkite stiprūs ir drąsūs; nes taip VIEŠPATS padarys visiems jūsų priešams, prieš kuriuos jūs kovojate“.'),
  (@b6, 10, 26, 'O po to Jozuė jiems smogė, juos užmušė ir juos pakorė ant penkių medžių; ir jie kabėjo ant medžių iki vakaro.'),
  (@b6, 10, 27, 'Ir įvyko, kad saulei leidžiantis Jozuė įsakė, ir jie nuėmė juos nuo medžių ir įmetė į olą, kurioje jie buvo pasislėpę, ir uždėjo ant olos angos didelius akmenis, kurie išliko iki pat šios dienos.'),
  (@b6, 10, 28, 'Ir tą dieną Jozuė paėmė Makedą ir sutriuškino ją kalavijo ašmenimis ir visiškai sunaikino jos karalių, juos ir visas joje esančias sielas; nei vieno nepaliko; ir padarė Makedos karaliui, kaip padarė Jericho karaliui.'),
  (@b6, 10, 29, 'Paskui Jozuė ir visas Izraelis su juo perėjo iš Makedos į Libną ir kovojo prieš Libną;'),
  (@b6, 10, 30, 'o VIEŠPATS ir ją, ir jos karalių atidavė į Izraelio ranką; ir jis išmušė ją bei visas joje esančias sielas kalavijo ašmenimis; jis nei vieno nepaliko joje; bet jos karaliui jis padarė, kaip buvo padaręs Jericho karaliui.'),
  (@b6, 10, 31, 'Ir Jozuė ir visas Izraelis su juo perėjo iš Libnos į Lachišą ir priešais jį stovyklavo, ir prieš jį kovojo;'),
  (@b6, 10, 32, 'ir VIEŠPATS atidavė Lachišą į ranką Izraelio, kuris, antrąją dieną jį paėmęs, išmušė kalavijo ašmenimis jį ir visas jame esančias sielas pagal tai, kaip buvo padaręs Libnai.'),
  (@b6, 10, 33, 'Tada Gezero karalius Horamas atėjo aukštyn padėti Lachišui; o Jozuė mušė jį ir jo tautą, kol jis jam nepaliko nei vieno išlikusio.'),
  (@b6, 10, 34, 'O iš Lachišo Jozuė ir visas Izraelis su juo perėjo į Egloną; ir jie priešais jį stovyklavo ir prieš jį kovojo;'),
  (@b6, 10, 35, 'ir tą dieną jie paėmė jį ir išmušė jį kalavijo ašmenimis, ir visas jame esančias sielas tą dieną visiškai sunaikino pagal visa tai, kaip jis buvo padaręs Lachišui.'),
  (@b6, 10, 36, 'Ir Jozuė ir visas Izraelis su juo nuėjo aukštyn iš Eglono į Hebroną; ir jie kovojo prieš jį;'),
  (@b6, 10, 37, 'ir jie paėmė ir iškirto kalavijo ašmenimis jį ir jo karalių, ir visus jo miestus, ir visas jame esančias sielas; nepaliko nei vieno išlikusio, pagal visa tai, kaip jis buvo padaręs Eglonui; bet visiškai sunaikino jį ir visas jame esančias sielas.'),
  (@b6, 10, 38, 'Ir Jozuė ir su juo visas Izraelis sugrįžo į Debyrą; ir prieš jį kovojo;'),
  (@b6, 10, 39, 'ir jis paėmė jį, jo karalių ir visus jo miestus; ir jie iškapojo juos kalavijo ašmenimis, ir visiškai sunaikino visas jame esančias sielas; jis nei vieno nepaliko išlikusio; kaip jis buvo padaręs Hebronui, taip padarė Debyrui ir jo karaliui; kaip jis buvo padaręs ir Libnai ir jos karaliui.'),
  (@b6, 10, 40, 'Taip Jozuė sutriuškino visą kalvų, pietų, slėnio ir šaltinių šalį ir visus jų karalius; nei vieno jis nepaliko išlikusio, bet visiškai sunaikino visa, kas kvėpuoja, kaip VIEŠPATS, Izraelio Dievas, įsakė.'),
  (@b6, 10, 41, 'Ir Jozuė juos sutriuškino nuo Kadeš-Barnėjos iki Gazos, ir visą Gošeno šalį iki Gibeono.'),
  (@b6, 10, 42, 'Ir visus šituos karalius ir jų šalį Jozuė paėmė vienu metu, nes VIEŠPATS, Izraelio Dievas, kovojo už Izraelį.'),
  (@b6, 10, 43, 'Ir Jozuė ir su juo visas Izraelis sugrįžo stovyklon, į Gilgalą.'),
  (@b6, 11, 1, 'Ir įvyko, kad tai išgirdęs Hacoro karalius Jabinas pasiuntė Madono karaliui Jobabui, Šimrono karaliui, Achšafo karaliui'),
  (@b6, 11, 2, 'ir karaliams, esantiems kalnų šiaurėje ir lygumose į pietus nuo Kineroto, ir slėnyje, ir Doro ribose, vakaruose,'),
  (@b6, 11, 3, 'ir kanaaniečiams rytuose ir vakaruose, amoritams, hetitams, perizams, jebusiečiams kalnuose ir hivams Hermono apačioje, Micpės šalyje.'),
  (@b6, 11, 4, 'Ir jie išėjo, jie ir visos jų kariuomenės su jais, tiek daug liaudies, kiek gausiai yra smėlio, esančio jūros pakrantėje, su labai daug žirgų bei vežimų.'),
  (@b6, 11, 5, 'Ir kai visi šitie karaliai susitiko, jie atėjo ir stovyklavo drauge prie Meromo vandenų, kad kovotų prieš Izraelį.'),
  (@b6, 11, 6, 'Ir VIEŠPATS tarė Jozuei: „Nebijok dėl jų; nes rytoj apie šitą laiką aš juos atiduosiu visus nužudytus Izraelio akivaizdon; jų žirgams perpjauk kojų gyslas ir sudegink jų vežimus ugnimi“.'),
  (@b6, 11, 7, 'Taip Jozuė ir visa karo tauta su juo staiga atėjo prieš juos prie Meromo vandenų; ir jie juos puolė.'),
  (@b6, 11, 8, 'Ir VIEŠPATS juos atidavė į ranką Izraelio, kuris juos sumušė ir vijosi iki didžiojo Sidono, iki Misrefot-Maimo, ir iki Micpės slėnio rytuose; ir jie mušė juos, kol jie nepaliko jiems nei vieno išlikusio.'),
  (@b6, 11, 9, 'Ir Jozuė jiems padarė, kaip VIEŠPATS jam liepė: jų žirgams jis perpjovė kojų gyslas, o jų vežimus sudegino ugnimi.'),
  (@b6, 11, 10, 'Ir tuo metu Jozuė apsisukęs paėmė Hacorą ir jo karalių nužudė kalaviju; nes Hacoras anksčiau buvo visų šitų karalysčių galva.'),
  (@b6, 11, 11, 'Ir jie iškirto kalavijo ašmenimis visas jame esančias sielas, visiškai jas sunaikindami; nei vienos neišliko kvėpuoti; o Hacorą jis sudegino ugnimi.'),
  (@b6, 11, 12, 'Ir visus šitų karalių miestus ir visus jų karalius Jozuė paėmė ir iškirto juos kalavijo ašmenimis; ir jis juos visiškai sunaikino, kaip VIEŠPATIES tarnas Mozė įsakė.'),
  (@b6, 11, 13, 'Tačiau Izraelis nesudegino nei vieno iš miestų, vis stovinčių savo tvirtumu, išskyrus vieną Hacorą, kurį Jozuė sudegino.'),
  (@b6, 11, 14, 'O visą šitų miestų grobį ir galvijus Izraelio vaikai pasiėmė sau kaip laimikį; bet visus žmones jie išžudė kalavijo ašmenimis, kol juos sunaikino, nieko nepaliko kvėpuoti.'),
  (@b6, 11, 15, 'Kaip VIEŠPATS įsakė savo tarnui Mozei, taip Mozė įsakė Jozuei, ir taip Jozuė padarė; jis nieko nepaliko nepadaryto iš viso to, ką VIEŠPATS įsakė Mozei.'),
  (@b6, 11, 16, 'Taip Jozuė paėmė visą šitą šalį, kalvas, visą pietų kraštą, visą Gošeno šalį, slėnį, lygumą, Izraelio kalną ir jo slėnį;'),
  (@b6, 11, 17, 'tai yra nuo Halako kalno, einančio aukštyn į Seyrą, iki Baal-Gado, Libano slėnyje, Hermono kalno apačioje; o visus jų karalius jis paėmė, sumušė juos ir užmušė.'),
  (@b6, 11, 18, 'Ilgą laiką Jozuė kariavo su visais šitais karaliais.'),
  (@b6, 11, 19, 'Nebuvo miesto, kuris būtų sudaręs taiką su Izraelio vaikais, išskyrus hivus, Gibeono gyventojus: visus kitus jie paėmė mūšyje.'),
  (@b6, 11, 20, 'Nes tai buvo iš VIEŠPATIES, kad sukietintų jų širdis, kad jie ateitų į mūšį prieš Izraelį, kad jis juos visiškai sunaikintų ir kad jie neturėtų palankumo, bet kad jis juos išnaikintų, kaip VIEŠPATS įsakė Mozei.'),
  (@b6, 11, 21, 'Ir tuo laiku atėjo Jozuė ir iškirto anakiečius iš kalnų, iš Hebrono, iš Debyro, iš Anabo, iš visų Judos kalnų ir iš visų Izraelio kalnų; Jozuė visiškai sunaikino juos su jų miestais.'),
  (@b6, 11, 22, 'Neišliko nei vieno iš anakiečių Izraelio vaikų šalyje; išliko tik Gazoje, Gate ir Ašdode.'),
  (@b6, 11, 23, 'Taip Jozuė paėmė visą šalį pagal visa tai, ką VIEŠPATS sakė Mozei; ir Jozuė ją davė kaip paveldą Izraeliui pagal jų pasidalijimus jų gentimis. Ir šalis ilsėjosi nuo karo.'),
  (@b6, 12, 1, 'Na, o šitie yra šalies karaliai, kuriuos Izraelio vaikai sumušė ir pasisavino jų šalį anapus Jordano, saulėtekio link, nuo Arnono upės iki Hermono kalno, ir visą lygumą rytuose:'),
  (@b6, 12, 2, 'amoritų karalius Sihonas, gyvenęs Hešbone ir valdęs nuo Aroero, esančio ant Arnono upės kranto ir nuo upės vidurio, nuo pusės Gileado iki Jaboko upės, kuri yra Amono vaikų riba;'),
  (@b6, 12, 3, 'ir nuo lygumos iki Kineroto jūros rytuose ir iki Lygumos jūros, tai yra Druskos jūros rytuose, keliu į Bet-Ješimotą; ir nuo pietų, Ašdot-Pisgos apačioje;'),
  (@b6, 12, 4, 'ir riba Bašano karaliaus Ogo, buvusio iš milžinų likučio, kuris gyveno Aštarote bei Edrėjyje'),
  (@b6, 12, 5, 'ir karaliavo Hermono kalne, Salche ir visame Bašane iki gešūriečių ir maakų ribos, ir pusės Gileado, Hešbono karaliaus Sihono ribos.'),
  (@b6, 12, 6, 'VIEŠPATIES tarnas Mozė ir Izraelio vaikai juos sumušė; ir VIEŠPATIES tarnas Mozė ją davė nuosavybėn rubenams, gadams ir pusei Manaso genties.'),
  (@b6, 12, 7, 'O šitie yra šalies karaliai, kuriuos Jozuė ir Izraelio vaikai sumušė šioje Jordano pusėje vakaruose, nuo Baal-Gado Libano slėnyje iki Halako kalno, kylančio į Seyrą; tai Jozuė davė nuosavybėn Izraelio gentims pagal jų pasidalijimus;'),
  (@b6, 12, 8, 'kalnuose, slėniuose, lygumose, šaltiniuose, dykumoje ir pietų šalyje; hetitus, amoritus, kanaaniečius, perizus, hivus ir jebusiečius:'),
  (@b6, 12, 9, 'vienas Jericho karalius; vienas karalius Ajo, esančio šalia Bet-Elio;'),
  (@b6, 12, 10, 'vienas Jeruzalės karalius; vienas Hebrono karalius;'),
  (@b6, 12, 11, 'vienas Jarmuto karalius; vienas Lachišo karalius;'),
  (@b6, 12, 12, 'vienas Eglono karalius; vienas Gezero karalius;'),
  (@b6, 12, 13, 'vienas Debyro karalius; vienas Gedero karalius;'),
  (@b6, 12, 14, 'vienas Hormos karalius; vienas Arado karalius;'),
  (@b6, 12, 15, 'vienas Libnos karalius; vienas Adulamo karalius;'),
  (@b6, 12, 16, 'vienas Makedos karalius; vienas Bet-Elio karalius;'),
  (@b6, 12, 17, 'vienas Tapuacho karalius; vienas Hefero karalius;'),
  (@b6, 12, 18, 'vienas Afeko karalius; vienas Lašarono karalius;'),
  (@b6, 12, 19, 'vienas Madono karalius; vienas Hacoro karalius;'),
  (@b6, 12, 20, 'vienas Šimron-Merono karalius; vienas Achšafo karalius;'),
  (@b6, 12, 21, 'vienas Taanacho karalius; vienas Megido karalius;'),
  (@b6, 12, 22, 'vienas Kedešo karalius; vienas Jokneamo iš Karmelio karalius;'),
  (@b6, 12, 23, 'vienas Doro karalius Doro ribose; vienas Gilgalo tautų karalius;'),
  (@b6, 12, 24, 'vienas Tircos karalius: iš viso trisdešimt vienas karalius.'),
  (@b6, 13, 1, 'Na, o Jozuė buvo senas ir metų palaužtas; ir VIEŠPATS jam tarė: „Tu esi senas ir metų palaužtas, o dar lieka labai daug žemės pasisavinti.'),
  (@b6, 13, 2, 'Šita yra žemė, kuri dar lieka: visos filistinų ribos ir visi gešūriečiai'),
  (@b6, 13, 3, 'nuo Šihoro, esančio prieš Egiptą, iki Ekrono ribų šiaurėje, kuri yra priskiriama kanaaniečiams; penki filistinų viešpačiai, gazai, ašdotai, aškelonai, gatai ir ekronai; taip pat avai;'),
  (@b6, 13, 4, 'nuo pietų visa kanaaniečių šalis, Meara, esanti šalia sidoniečių, iki Afeko, iki amoritų ribų;'),
  (@b6, 13, 5, 'gebaliečių šalis ir visas Libanas saulėtekio link, nuo Baal-Gado, esančio Hermono kalno apačioje, iki įėjimo į Hamatą;'),
  (@b6, 13, 6, 'visi gyventojai kalvų krašto nuo Libano iki Misrefot-Maimo ir visi sidoniečiai; juos aš išvarysiu nuo Izraelio vaikų akivaizdos; tik ją padalink burtu izraelitams kaip paveldą, kaip esu tau įsakęs.'),
  (@b6, 13, 7, 'Taigi dabar padalyk šitą šalį kaip paveldą devynioms gentims ir pusei Manaso genties“,'),
  (@b6, 13, 8, 'su kuria rubenai ir gadai yra gavę savo paveldą, kurį Mozė jiems davė anapus Jordano, į rytus, kaip VIEŠPATIES tarnas Mozė jiems davė:'),
  (@b6, 13, 9, 'nuo Aroero, esančio ant Arnono upės kranto, miestą, esantį upės viduryje, ir visą Medebos lygumą iki Dibono;'),
  (@b6, 13, 10, 'visus miestus amoritų karaliaus Sihono, karaliavusio Hešbone, iki Amono vaikų ribos;'),
  (@b6, 13, 11, 'Gileadą, gešūriečių ir maakų ribą, visą Hermono kalną, visą Bašaną iki Salchos;'),
  (@b6, 13, 12, 'visą Bašane esančią karalystę Ogo, karaliavusio Aštarote ir Edrėjyje, kuris buvo išlikęs iš milžinų likučio; nes Mozė šituos sumušė ir juos išvarė.'),
  (@b6, 13, 13, 'Tačiau Izraelio vaikai neišvarė gešūriečių ir maakų; bet gešūriečiai ir maakai gyvena tarp izraelitų iki šios dienos.'),
  (@b6, 13, 14, 'Tik Levio genčiai jis nedavė jokio paveldo; jų paveldas yra VIEŠPATIES, Izraelio Dievo, ugnies aukos, kaip jis jiems sakė.'),
  (@b6, 13, 15, 'Ir Mozė davė Rubeno vaikų genčiai paveldą pagal jų šeimas.'),
  (@b6, 13, 16, 'Ir jų riba buvo nuo Aroero, esančio ant Arnono upės kranto, miestas, esantis upės viduryje, ir visa lyguma prie Medebos;'),
  (@b6, 13, 17, 'Hešbonas ir visi jo miestai, esantys lygumoje; Dibonas, Bamot-Baalas, Bet-Baal-Meonas,'),
  (@b6, 13, 18, 'Jahacas, Kedemotas, Mefaatas,'),
  (@b6, 13, 19, 'Kirjataimas, Sibma, Caret-Šaharas slėnio kalne,'),
  (@b6, 13, 20, 'Bet-Peoras, Ašdot-Pisga, Bet-Ješimotas'),
  (@b6, 13, 21, 'ir visi lygumos miestai, ir visa karalystė amoritų karaliaus Sihono, karaliavusio Hešbone, kurį Mozė sumušė su Midjano kunigaikščiais: Eviu, Rekemu, Cūru, Hūru ir Rebu, kurie buvo Sihono kunigaikščiai, gyvenusieji šalyje.'),
  (@b6, 13, 22, 'Taip pat pranašautoją Balaamą, Beoro sūnų, Izraelio vaikai nužudė kalaviju tarp kitų jų nužudytųjų.'),
  (@b6, 13, 23, 'O Rubeno vaikų riba buvo Jordanas ir jo riba. Tas buvo Rubeno vaikų paveldas pagal jų šeimas, miestai ir jų kaimai.'),
  (@b6, 13, 24, 'Ir Mozė davė paveldą Gado genčiai, būtent Gado vaikams pagal jų šeimas.'),
  (@b6, 13, 25, 'Ir jų riba buvo Jazeras, visi Gileado miestai ir pusė Amono vaikų šalies iki Aroero, esančio prieš Rabą;'),
  (@b6, 13, 26, 'ir nuo Hešbono iki Ramat-Micpės bei Betonimo; ir nuo Mahanaimo iki Debyro ribos;'),
  (@b6, 13, 27, 'o slėnyje Bet-Haramas, Bet-Nimra, Sukotas ir Cafonas, likusioji Hešbono karaliaus Sihono karalystės dalis, Jordanas ir jo riba, tai yra iki Kinereto jūros krašto kitoje Jordano pusėje į rytus.'),
  (@b6, 13, 28, 'Šis yra paveldas Gado vaikų pagal jų šeimas, miestai ir jų kaimai.'),
  (@b6, 13, 29, 'Ir Mozė davė paveldą pusei Manaso genties; ir šita buvo nuosavybė pusės Manaso vaikų genties pagal jų šeimas.'),
  (@b6, 13, 30, 'Ir jų riba buvo nuo Mahanaimo visas Bašanas, visa Bašano karaliaus Ogo karalystė ir visi Jayro miesteliai, esantys Bašane – šešiasdešimt miestų;'),
  (@b6, 13, 31, 'o pusė Gileado, Aštarotas ir Edrėjas, Ogo karalystės miestai Bašane, priklausė Manaso sūnaus Machyro vaikams, tai yra pusei Machyro vaikų pagal jų šeimas.'),
  (@b6, 13, 32, 'Šitos yra šalys, kurias Mozė Moabo lygumose išdalino paveldėjimui anapus Jordano, prie Jericho, rytuose.'),
  (@b6, 13, 33, 'Bet Levio genčiai Mozė nedavė jokio paveldo: VIEŠPATS, Izraelio Dievas, buvo jų paveldas, kaip jis jiems sakė.'),
  (@b6, 14, 1, 'O šitos yra šalys, kurias Izraelio vaikai paveldėjo Kanaano krašte, kurias jiems išdalino paveldui kunigas Eleazaras, Nūno sūnus Jozuė ir Izraelio vaikų genčių tėvų galvos.'),
  (@b6, 14, 2, 'Burtu buvo jų paveldas, kaip VIEŠPATS įsakė per Mozės ranką, devynioms gentims ir pusei genties.'),
  (@b6, 14, 3, 'Nes Mozė buvo davęs dviejų genčių ir pusės genties paveldą anapus Jordano; bet levitams jis nedavė jokio paveldo tarp jų.'),
  (@b6, 14, 4, 'Nes Juozapo vaikų buvo dvi gentys, Manasas ir Efraimas; todėl jie nedavė levitams jokios dalies šalyje, išskyrus miestus apsigyventi su jų priemiesčiais jų galvijams ir jų turtui.'),
  (@b6, 14, 5, 'Kaip VIEŠPATS įsakė Mozei, taip Izraelio vaikai padarė, ir jie padalijo šalį.'),
  (@b6, 14, 6, 'Tada Judos vaikai atėjo pas Jozuę į Gilgalą; ir Jefunės sūnus Kalebas, kenazas, jam tarė: „Tu žinai tai, ką VIEŠPATS kalbėjo Dievo vyrui Mozei apie mane ir tave Kadeš-Barnėjoje.'),
  (@b6, 14, 7, 'Aš buvau keturiasdešimties metų, kai VIEŠPATIES tarnas Mozė mane siuntė iš Kadeš-Barnėjos šalies išžvalgyti; ir jam parnešiau žinią pagal tai, kas buvo mano širdyje.'),
  (@b6, 14, 8, 'Tačiau mano broliai, kurie ėjo aukštyn su manimi, tirpdė tautos širdį; bet aš pilnai sekiau VIEŠPAČIU, savo Dievu.'),
  (@b6, 14, 9, 'Ir Mozė tą dieną prisiekė, sakydamas: ‘Tikrai ta šalis, kurią mindė tavo kojos, bus amžinai tavo ir tavo vaikų paveldas, nes tu pilnai sekei VIEŠPAČIU, mano Dievu’.'),
  (@b6, 14, 10, 'O dabar, štai VIEŠPATS išlaikė mane gyvą, kaip jis sakė, šituos keturiasdešimt penkerius metus nuo to laiko, kai VIEŠPATS pasakė šitą žodį Mozei, kol Izraelio vaikai tebeklaidžiojo dykumoje; o dabar, štai aš esu šią dieną aštuoniasdešimt penkių metų.'),
  (@b6, 14, 11, 'Aš šią dieną tebesu toks stiprus, koks buvau tą dieną, kai Mozė mane siuntė; kokia tąsyk buvo mano jėga, tokia ir dabar mano jėga kariauti, tiek išeiti, tiek ir įeiti.'),
  (@b6, 14, 12, 'Taigi dabar duok man šitą kalną, apie kurį VIEŠPATS aną dieną kalbėjo; nes aną dieną girdėjai, kad ten esą anakų, ir kad miestai dideli ir aptverti; jei VIEŠPATS bus su manimi, tuomet aš pajėgsiu juos išvaryti, kaip VIEŠPATS sakė“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b6, 14, 13, 'Ir Jozuė palaimino jį ir davė Jefunės sūnui Kalebui paveldėjimui Hebroną.'),
  (@b6, 14, 14, 'Todėl Hebronas tapo Jefunės sūnaus Kalebo, kenazo, paveldu iki šios dienos, nes jis pilnai sekė VIEŠPAČIU, Izraelio Dievu.'),
  (@b6, 14, 15, 'O Hebrono vardas anksčiau buvo Kirjat-Arba; šis Arba buvo didis žmogus tarp anakų. Ir šalis ilsėjosi nuo karo.'),
  (@b6, 15, 1, 'Tad šis buvo Judos vaikų genties burtas pagal jų šeimas: prie Edomo ribos Cino dykuma į pietus buvo atokiausia pietų ribos dalis.'),
  (@b6, 15, 2, 'Ir jų pietinė riba buvo nuo Druskos jūros kranto, nuo įlankos, žiūrinčios į pietus;'),
  (@b6, 15, 3, 'ir ji išėjo į pietų pusę, į Malech-Akrabimą, perėjo tolyn į Ciną ir pietinėje pusėje pakilo į Kadeš-Barnėją ir perėjo tolyn į Hecroną, pakilo į Adarą, ėjo aplink į Karką;'),
  (@b6, 15, 4, 'iš čia ji perėjo link Acmono ir išėjo į Egipto upę; ir tos ribos pabaiga buvo ties jūra; šita bus jūsų pietinė riba.'),
  (@b6, 15, 5, 'O rytinė riba buvo Druskos jūra iki Jordano galo. O jų riba šiaurinėje pusėje buvo nuo jūros įlankos tolimiausioje Jordano dalyje;'),
  (@b6, 15, 6, 'ir riba ėjo aukštyn į Bet-Hoglą ir toliau perėjo šiaurine Bet-Arabos puse; ir riba kilo iki Rubeno sūnaus Bohano akmens;'),
  (@b6, 15, 7, 'ir riba kilo iš Achoro slėnio link Debyro ir taip link šiaurės, atsisukusi į Gilgalą, esantį prieš pakilimą į Adumimą, esantį pietinėje upės pusėje; ir riba perėjo link En-Šemešo vandenų ir ji pasibaigė ties En-Rogeliu;'),
  (@b6, 15, 8, 'ir riba kilo Hinomo sūnaus slėniu iki pietinės jebusiečių pusės; ji yra Jeruzalė; ir riba kilo į viršūnę kalno, esančio vakaruose, prieš Hinomo slėnį, kuris yra milžinų slėnio šiauriniame gale;'),
  (@b6, 15, 9, 'ir riba nuo kalvos viršūnės traukė į Neftoacho vandens šaltinį ir išėjo į Efrono kalno miestus; ir riba traukė į Baalą, kuris yra Kirjat-Jearimas;'),
  (@b6, 15, 10, 'ir riba sukosi nuo Baalos į vakarus, į Seyro kalną, ir perėjo tolyn iki Jearimo kalno, tai yra Chesalono šono, šiaurinėje pusėje, ir nusileido į Bet-Šemešą ir perėjo į Timną;'),
  (@b6, 15, 11, 'ir riba išėjo į šiaurinį Ekrono šoną; ir riba traukė į Šikroną, toliau perėjo į Baalos kalną ir išėjo į Jabneelį; ir riba pasibaigė ties jūra.'),
  (@b6, 15, 12, 'O vakarinė riba buvo prie Didžiosios jūros ir jos kranto. Šita yra aplinkui einanti Judos vaikų riba pagal jų šeimas.'),
  (@b6, 15, 13, 'O Jefunės sūnui Kalebui jis davė dalį tarp Judos vaikų pagal VIEŠPATIES įsakymą Jozuei – Anako tėvo Arbos miestą, kuris yra Hebrono miestas.'),
  (@b6, 15, 14, 'Ir Kalebas išvarė iš ten tris Anako sūnus: Šešają, Ahimaną ir Talmają, Anako vaikus.'),
  (@b6, 15, 15, 'Ir iš ten jis ėjo aukštyn pas Debyro gyventojus; o Debyro vardas anksčiau buvo Kirjat-Seferas.'),
  (@b6, 15, 16, 'Ir Kalebas tarė: „Kas sumuš Kirjat-Seferą ir jį paims, tam duosiu į žmonas savo dukterį Achsą“.'),
  (@b6, 15, 17, 'Ir jį paėmė Kalebo brolio Kenazo sūnus Otnielis; ir jis jam davė savo dukterį Achsą į žmonas.'),
  (@b6, 15, 18, 'Ir įvyko, jai atėjus pas jį, ji paskatino jį prašyti jos tėvą lauko; ir jai nulipus nuo asilo, Kalebas jai tarė: „Ko nori?“'),
  (@b6, 15, 19, 'Ji atsakė: „Duok man palaiminimą; nes tu man davei pietų šalį; duok man ir vandens šaltinius“. Ir jis jai davė viršutinius ir žemutinius šaltinius.'),
  (@b6, 15, 20, 'Šitas yra Judos vaikų genties paveldas pagal jų šeimas.'),
  (@b6, 15, 21, 'Ir tolimiausi miestai Judos vaikų genties link Edomo ribos į pietus buvo Kabceelis, Ederas, Jagūras,'),
  (@b6, 15, 22, 'Kina, Dimona, Adada,'),
  (@b6, 15, 23, 'Kedešas, Hacoras, Itnanas,'),
  (@b6, 15, 24, 'Zifas, Telemas, Bealotas,'),
  (@b6, 15, 25, 'Hacor Hadatas, Kerijotas, Hecronas, kuris yra Hacoras,'),
  (@b6, 15, 26, 'Amamas, Šema, Molada,'),
  (@b6, 15, 27, 'Hacar-Gada, Hešmonas, Bet-Peletas,'),
  (@b6, 15, 28, 'Hacar-Šualas, Beer-Šeba, Biziotija,'),
  (@b6, 15, 29, 'Baala, Jimas, Ecemas,'),
  (@b6, 15, 30, 'Eltoladas, Kesilas, Horma,'),
  (@b6, 15, 31, 'Ciklagas, Madmana, Sansana,'),
  (@b6, 15, 32, 'Lebaotas, Šilhimas, Ainas ir Rimonas – iš viso dvidešimt devyni miestai su jų kaimais;'),
  (@b6, 15, 33, 'o slėnyje: Eštaolas, Cora, Ašna,'),
  (@b6, 15, 34, 'Zanoachas, En-Ganimas, Tapuachas, Enamas,'),
  (@b6, 15, 35, 'Jarmutas, Adulamas, Sochojas, Azeka,'),
  (@b6, 15, 36, 'Šaraimas, Aditaimas, Gedera ir Gederotaimas – keturiolika miestų su jų kaimais;'),
  (@b6, 15, 37, 'Cenanas, Hadaša, Migdal-Gadas,'),
  (@b6, 15, 38, 'Dileanas, Micpė, Jokteelis,'),
  (@b6, 15, 39, 'Lachišas, Bockatas, Eglonas,'),
  (@b6, 15, 40, 'Kabonas, Lachmasas, Kitlišas,'),
  (@b6, 15, 41, 'Gederotas, Bet-Dagonas, Naama ir Makeda – šešiolika miestų su jų kaimais;'),
  (@b6, 15, 42, 'Libna, Eteras, Ašanas,'),
  (@b6, 15, 43, 'Iftachas, Ašna, Necibas,'),
  (@b6, 15, 44, 'Keila, Achzibas ir Mareša – devyni miestai su jų kaimais;'),
  (@b6, 15, 45, 'Ekronas su jo miesteliais bei jo kaimais;'),
  (@b6, 15, 46, 'nuo Ekrono iki jūros viskas, kas yra šalia Ašdodo su jo kaimais;'),
  (@b6, 15, 47, 'Ašdodas su jo miesteliais ir jo kaimais, Gaza su jos miesteliais ir jos kaimais iki Egipto upės ir Didžiosios jūros bei jos ribos;'),
  (@b6, 15, 48, 'o kalnuose: Šamyras, Jatyras, Sochojas,'),
  (@b6, 15, 49, 'Dana ir Kirjat-Sana, kuri yra Debyras,'),
  (@b6, 15, 50, 'Anabas, Eštemojas, Animas,'),
  (@b6, 15, 51, 'Gošenas, Holonas ir Gilojas – vienuolika miestų su jų kaimais;'),
  (@b6, 15, 52, 'Arabas, Dūma, Ešeanas,'),
  (@b6, 15, 53, 'Janumas, Bet-Tapuachas, Afeka,'),
  (@b6, 15, 54, 'Humta, Kirjat-Arba, kuri yra Hebronas, ir Cioras – devyni miestai su jų kaimais;'),
  (@b6, 15, 55, 'Maonas, Karmelis, Zifas, Juta,'),
  (@b6, 15, 56, 'Jezreelis, Jokdeamas, Zanoachas,'),
  (@b6, 15, 57, 'Kainas, Gibėja ir Timna – dešimt miestų su jų kaimais;'),
  (@b6, 15, 58, 'Halhulas, Bet-Cūras, Gedoras,'),
  (@b6, 15, 59, 'Maaratas, Bet-Anotas ir Eltekonas – šeši miestai su jų kaimais;'),
  (@b6, 15, 60, 'Kirjat-Baalas, kuris yra Kirjat-Jearimas, ir Raba – du miestai su jų kaimais;'),
  (@b6, 15, 61, 'dykumoje: Bet-Araba, Midinas, Sechacha,'),
  (@b6, 15, 62, 'Nibšanas, Druskos miestas ir En-Gedis – šeši miestai su jų kaimais.'),
  (@b6, 15, 63, 'Tačiau jebusiečių, Jeruzalės gyventojų, Judos vaikai negalėjo išvaryti; bet jebusiečiai gyvena su Judos vaikais iki šios dienos.'),
  (@b6, 16, 1, 'O Juozapo vaikų burtas iškrito nuo Jordano prie Jericho iki Jericho vandens rytuose, į dykumą, kuri kyla iš Jericho per Bet-Elio kalną'),
  (@b6, 16, 2, 'ir išeina iš Bet-Elio į Lūzą, ir pereina tolyn iki arkų ribos, iki Ataroto,'),
  (@b6, 16, 3, 'ir leidžiasi į vakarus, į jafletų ribas, iki žemutiniojo Bet-Horono ribos ir iki Gezero; o jos galas ties jūra.'),
  (@b6, 16, 4, 'Taip Juozapo vaikai, Manasas ir Efraimas paėmė savo paveldą.'),
  (@b6, 16, 5, 'O Efraimo vaikų riba pagal jų šeimas buvo tokia: jų paveldo riba rytų pusėje buvo Atarot-Adaras iki aukštutiniojo Bet-Horono;'),
  (@b6, 16, 6, 'ir riba išėjo link jūros į Michmetatą šiaurinėje pusėje; ir riba ėjo lanku į rytus, į Taanat-Šiloją, ir praėjo pro jį rytuose į Janochą;'),
  (@b6, 16, 7, 'ir ji nusileido nuo Janocho į Atarotą ir į Naaratą, atėjo į Jerichą ir išėjo ties Jordanu.'),
  (@b6, 16, 8, 'Riba išėjo iš Tapuacho į vakarus, į Kanos upę; o jos galas buvo ties jūra. Šitas yra Efraimo vaikų genties paveldas pagal jų šeimas.'),
  (@b6, 16, 9, 'O atskiri miestai Efraimo vaikams buvo tarp Manaso vaikų paveldo, visi miestai su jų kaimais.'),
  (@b6, 16, 10, 'Ir jie neišvarė kanaaniečių, gyvenančių Gezeryje; bet kanaaniečiai gyvena efraimų tarpe iki šios dienos ir tarnauja, mokėdami duoklę.'),
  (@b6, 17, 1, 'Taip pat buvo burtas Manaso genčiai; nes jis buvo Juozapo pirmagimis; tai yra Manaso pirmagimiui Machyrui, Gileado tėvui; kadangi jis buvo karo vyras, todėl jis gavo Gileadą ir Bašaną.'),
  (@b6, 17, 2, 'Taip pat buvo burtas likusiems Manaso vaikams pagal jų šeimas: Abiezero vaikams, Heleko vaikams, Asrielio vaikams, Šechemo vaikams, Hefero vaikams ir Šemidos vaikams – šitie buvo Juozapo sūnaus Manaso vyriškos lyties vaikai pagal jų šeimas.'),
  (@b6, 17, 3, 'Bet Manaso sūnaus Machyro sūnaus Gileado sūnaus Hefero sūnus Celofechadas neturėjo sūnų, tik dukteris; o šitie yra jo dukterų vardai: Machla, Noja, Hogla, Milka ir Tirca.'),
  (@b6, 17, 4, 'Ir jos priartėjo kunigo Eleazaro akivaizdon, Nūno sūnaus Jozuės akivaizdon ir kunigaikščių akivaizdon, sakydamos: „VIEŠPATS įsakė Mozei, kad duotų mums paveldą tarp mūsų brolių“. Todėl pagal VIEŠPATIES įsakymą jis joms davė paveldą tarp jų tėvo brolių.'),
  (@b6, 17, 5, 'Ir Manasui teko dešimt dalių, neskaitant Gileado šalies ir Bašano, esančių anapus Jordano;'),
  (@b6, 17, 6, 'nes Manaso dukterys turėjo paveldą tarp jo sūnų; o likusieji Manaso sūnūs turėjo Gileado šalį.'),
  (@b6, 17, 7, 'Ir Manaso riba buvo nuo Ašero iki Michmetato, esančio prieš Šechemą; ir toliau riba ėjo po dešine ranka iki En-Tapuacho gyventojų.'),
  (@b6, 17, 8, 'Na, o Manasas turėjo Tapuacho šalį; bet Tapuachas ant Manaso ribos priklausė Efraimo vaikams;'),
  (@b6, 17, 9, 'ir riba nusileido į Kanos upę, upės pietuose; šitie Efraimo miestai yra tarp Manaso miestų; Manaso riba taip pat buvo šiaurinėje upės pusėje, o jos pabaiga buvo ties jūra;'),
  (@b6, 17, 10, 'į pietus tai buvo Efraimo, o į šiaurę tai buvo Manaso, o jūra yra jo riba; ir jie susitiko Ašere šiaurėje, o Isachare rytuose.'),
  (@b6, 17, 11, 'Ir Manasas turėjo Isachare ir Ašere Bet-Šeaną ir jo miestelius, Ibleamą ir jo miestelius, Doro gyventojus ir jo miestelius, En-Doro gyventojus ir jo miestelius, Taanacho gyventojus ir jo miestelius ir Megido gyventojus ir jo miestelius, tai yra tris šalis.'),
  (@b6, 17, 12, 'Tačiau Manaso vaikai negalėjo išvaryti tų miestų gyventojų; bet kanaaniečiai norėjo gyventi šitoje šalyje.'),
  (@b6, 17, 13, 'Dar įvyko, kad, kai Izraelio vaikai sustiprėjo, jie uždėjo kanaaniečiams mokesčius; bet neišvarė jų visiškai.'),
  (@b6, 17, 14, 'Ir Juozapo vaikai kalbėjo Jozuei, sakydami: „Kodėl man davei tik vieną burtą ir tik vieną dalį paveldėti, atsižvelgiant į tai, kad aš esu didelė tauta, nes VIEŠPATS iki šiol mane laimino?“'),
  (@b6, 17, 15, 'O Jozuė jiems atsakė: „Jei tu esi didelė tauta, tuomet eik aukštyn į miško šalį ir ten sau išsikirsk perizų ir milžinų šalyje, jei Efraimo kalnas tau per ankštas“.'),
  (@b6, 17, 16, 'Ir Juozapo vaikai tarė: „Tos kalvos mums nepakanka; ir visi kanaaniečiai, gyvenantys slėnio šalyje, turi geležinių vežimų – tiek esantys iš Bet-Šeano ir jo miestelių, tiek esantys iš Jezreelio slėnio“.'),
  (@b6, 17, 17, 'Ir Jozuė kalbėjo Juozapo namams – Efraimui ir Manasui – sakydamas: „Tu esi didelė tauta ir turi didelę galią; turėsi ne tik vieną burtą;'),
  (@b6, 17, 18, 'bet kalnas bus tavo; nes jis yra miškas, o tu jį iškirsi; ir jo galas bus tavo; nes tu išvarysi kanaaniečius, nors jie turi geležinių vežimų, nors jie galingi“.'),
  (@b6, 18, 1, 'Ir visas Izraelio vaikų susirinkimas susirinko Šilojuje ir ten pastatė susirinkimo padangtę. Ir šalis jų akivaizdoje buvo pavergta.'),
  (@b6, 18, 2, 'Ir tarp Izraelio vaikų liko septynios gentys, kurios dar nebuvo gavusios savo paveldo.'),
  (@b6, 18, 3, 'Ir Jozuė tarė Izraelio vaikams: „Kaip ilgai delsite eiti ir pasisavinti šalį, kurią jums davė VIEŠPATS, jūsų tėvų Dievas?'),
  (@b6, 18, 4, 'Duokite iš savo tarpo po tris vyrus kiekvienai genčiai; ir aš juos išsiųsiu, o jie pakils ir pereis šalį, ir aprašys ją pagal jų paveldą; ir jie sugrįš pas mane.'),
  (@b6, 18, 5, 'Ir jie padalins ją į septynias dalis: Juda pasiliks savo ribose – pietuose, o Juozapo namai pasiliks savo ribose – šiaurėje.'),
  (@b6, 18, 6, 'Todėl aprašykite šalį septyniomis dalimis ir atneškite man čia aprašymą, kad mesčiau čia jums burtą VIEŠPATIES, mūsų Dievo, akivaizdoje.'),
  (@b6, 18, 7, 'Bet levitai neturi dalies tarp jūsų; nes VIEŠPATIES kunigystė yra jų paveldas; o Gadas, Rubenas ir pusė Manaso genties yra gavę savo paveldą anapus Jordano, rytuose, kurį jiems davė VIEŠPATIES tarnas Mozė“.'),
  (@b6, 18, 8, 'Ir tie vyrai pakilo ir išėjo; ir Jozuė įpareigojo einančius šalies aprašyti, sakydamas: „Eikite, pereikite tą šalį, aprašykite ją ir sugrįžkite pas mane, kad čia, Šilojuje, mesčiau jums burtą VIEŠPATIES akivaizdoje“.'),
  (@b6, 18, 9, 'Ir tie vyrai ėjo, perėjo tą šalį, aprašė ją knygoje pagal miestus septyniomis dalimis ir sugrįžo pas Jozuę į kariuomenę Šilojuje.'),
  (@b6, 18, 10, 'Ir Jozuė jiems metė burtą Šilojuje, VIEŠPATIES akivaizdoje; ir ten Jozuė padalijo šalį Izraelio vaikams pagal jų pasidalijimus.'),
  (@b6, 18, 11, 'Ir Benjamino vaikų genties burtas išėjo pagal jų šeimas; ir jų burto riba išėjo tarp Judos vaikų ir Juozapo vaikų.'),
  (@b6, 18, 12, 'Ir jų riba šiaurinėje pusėje buvo nuo Jordano; ir riba pakilo į Jericho šoną šiaurinėje pusėje ir kilo per kalnus į vakarus; o jos pabaiga buvo ties Bet-Aveno dykuma.'),
  (@b6, 18, 13, 'O iš ten riba perėjo Lūzo link, į šoną Lūzo, kuris yra Bet-Elis, pietų link; ir riba nusileido į Atarot-Adarą, šalia kalvos, esančios žemutiniojo Bet-Horono pietinėje pusėje.'),
  (@b6, 18, 14, 'O iš ten riba traukė ir apėjo jūros kampą pietų link, nuo kalvos, esančios prieš Bet-Horoną į pietus; o jos galas buvo ties Kirjat-Baalu, kuris yra Kirjat-Jearimas, Judos vaikų miestas; tai buvo vakarinė pusė.'),
  (@b6, 18, 15, 'O pietinė pusė buvo nuo Kirjat-Jearimo pakraščio, ir riba išėjo į vakarus ir išėjo į Neftoacho vandenų šaltinį;'),
  (@b6, 18, 16, 'ir riba nusileido iki pabaigos kalno, esančio prieš Hinomo sūnaus slėnį, kuris yra milžinų slėnyje, šiaurėje, ir nusileido į Hinomo slėnį, į jebusiečių pietinę pusę, ir ėjo žemyn į En-Rogelį,'),
  (@b6, 18, 17, 'tęsėsi nuo šiaurės ir išėjo į En-Šemešą, išėjo Geliloto, esančio priešais Adumimo pakilimą, link ir nusileido iki Rubeno sūnaus Bohano akmens,'),
  (@b6, 18, 18, 'toliau perėjo į šoną priešais Arabą šiaurės link ir leidosi į Arabą;'),
  (@b6, 18, 19, 'ir riba toliau perėjo į Bet-Hoglos pusę į šiaurę; o ribos pabaiga buvo ties Druskos jūros šiaurine įlanka, prie Jordano pietinio galo; šita buvo pietinė riba.'),
  (@b6, 18, 20, 'O Jordanas buvo jo riba rytinėje pusėje. Šitas buvo Benjamino vaikų paveldas pagal jo aplink einančias ribas, pagal jų šeimas.'),
  (@b6, 18, 21, 'Na, o Benjamino vaikų genties miestai pagal jų šeimas buvo Jerichas, Bet-Hogla, Kecico slėnis,'),
  (@b6, 18, 22, 'Bet-Araba, Cemaraimas, Bet-Elis,'),
  (@b6, 18, 23, 'Avimas, Para, Ofra,'),
  (@b6, 18, 24, 'Kefar-Amona, Ofnis ir Gaba – dvylika miestų su jų kaimais;'),
  (@b6, 18, 25, 'Gibeonas, Rama, Beerotas,'),
  (@b6, 18, 26, 'Micpė, Kefyra, Moca,'),
  (@b6, 18, 27, 'Rekemas, Irpeelis, Tarala,'),
  (@b6, 18, 28, 'Cela, Elefas, jebusiečiai, kurie yra Jeruzalė, Gibeatas ir Kirjatas – keturiolika miestų su jų kaimais. Šitas yra Benjamino vaikų paveldas pagal jų šeimas.'),
  (@b6, 19, 1, 'O antrasis burtas išėjo Simeonui, tai yra Simeono vaikų genčiai pagal jų šeimas; ir jų paveldas buvo Judos vaikų paveldo viduryje.'),
  (@b6, 19, 2, 'Ir jie turėjo savo pavelde Beer-Šebą arba Šebą, Moladą,'),
  (@b6, 19, 3, 'Hacar-Šualą, Balą, Azemą,'),
  (@b6, 19, 4, 'Eltoladą, Betulą, Hormą,'),
  (@b6, 19, 5, 'Ciklagą, Bet-Markabotą, Hacar-Susą,'),
  (@b6, 19, 6, 'Bet-Lebaotą ir Šaruheną – trylika miestų ir jų kaimus;'),
  (@b6, 19, 7, 'Ainą, Rimoną, Eterą ir Ašaną – keturis miestus ir jų kaimus;'),
  (@b6, 19, 8, 'ir visus kaimus, esančius aplink šituos miestus, iki Baalat-Beero, pietų Ramato. Šitas yra Simeono vaikų genties paveldas pagal jų šeimas.'),
  (@b6, 19, 9, 'Simeono vaikų paveldas buvo iš Judos vaikų dalies; nes Judos vaikų dalies buvo jiems per daug; todėl Simeono vaikai turėjo savo paveldą jų paveldo viduryje.'),
  (@b6, 19, 10, 'O trečiasis burtas išėjo Zebulono vaikams pagal jų šeimas; ir jų paveldo riba buvo iki Sarido;'),
  (@b6, 19, 11, 'ir jų riba kilo jūros ir Maralo link, ir siekė Dabašetą, ir siekė upę, esančią prieš Jokneamą;'),
  (@b6, 19, 12, 'pasisuko nuo Sarido į rytus link saulėtekio iki Kislot-Taboro ribos, paskui išėjo į Daberatą, pakilo į Jafiją,'),
  (@b6, 19, 13, 'iš ten perėjo tolyn į rytus, į Gat-Heferą, į Et-Kaciną ir išėjo į Rimon-Metoarą, į Nėją;'),
  (@b6, 19, 14, 'ir riba sukosi šiaurinėje pusėje į Hanatoną; o jos pabaiga yra Iftach-Elio slėnyje;'),
  (@b6, 19, 15, 'Katatas, Nahalalas, Šimronas, Idala ir Betliejus – dvylika miestų su jų kaimais.'),
  (@b6, 19, 16, 'Šitas yra Zebulono vaikų paveldas pagal jų šeimas, šitie miestai su jų kaimais.'),
  (@b6, 19, 17, 'O ketvirtasis burtas išėjo Isacharui, Isacharo vaikams pagal jų šeimas.'),
  (@b6, 19, 18, 'Ir jų riba buvo link Jezreelio, Kesuloto, Šunemo,'),
  (@b6, 19, 19, 'Hafaraimo Šiono, Anaharato,'),
  (@b6, 19, 20, 'Rabito, Kišjono, Ebeco,'),
  (@b6, 19, 21, 'Remeto, En-Ganimo, En-Hado ir Bet-Paceco;'),
  (@b6, 19, 22, 'ir riba siekė Taborą, Šahacimą ir Bet-Šemešą; o jų ribos galas buvo ties Jordanu – šešiolika miestų su jų kaimais.'),
  (@b6, 19, 23, 'Šitas yra Isacharo vaikų genties paveldas pagal jų šeimas, miestai ir jų kaimai.'),
  (@b6, 19, 24, 'O penktasis burtas išėjo Ašero vaikų genčiai pagal jų šeimas.'),
  (@b6, 19, 25, 'Ir jų riba buvo Helkata, Halis, Betenas, Achšafa,'),
  (@b6, 19, 26, 'Alamelechas, Amadas ir Mišalas; ir siekė Karmelį vakaruose ir Šihor-Libnatą;'),
  (@b6, 19, 27, 'ir pasisuko saulėtekio link, į Bet-Dagoną, siekė Zebuloną ir Iftach-Elio slėnį, Bet-Emeko šiaurinės pusės link, ir Nejelį, ir išėjo į Kabulą po kaire ranka,'),
  (@b6, 19, 28, 'į Hebroną, Rehobą, Hamoną ir Kaną iki Didžiojo Sidono;'),
  (@b6, 19, 29, 'o tada riba sukosi į Ramą ir į stiprųjį Tyro miestą; ir riba sukosi į Hosą; o jos pabaiga yra ties jūra, nuo ribos iki Achzibo;'),
  (@b6, 19, 30, 'taip pat Uma, Afekas ir Rehobas – dvidešimt du miestai su jų kaimais.'),
  (@b6, 19, 31, 'Šitas yra Ašero vaikų genties paveldas pagal jų šeimas, šitie miestai su jų kaimais.'),
  (@b6, 19, 32, 'Šeštasis burtas išėjo Naftalio vaikams, tai yra Naftalio vaikams pagal jų šeimas.'),
  (@b6, 19, 33, 'O jų riba buvo nuo Helefo, nuo Alono iki Caananimo, Adamio, Nekebo, Jabneelio iki Lakumo; o jos galas buvo ties Jordanu;'),
  (@b6, 19, 34, 'o paskui riba sukosi į vakarus, į Aznot-Taborą, iš ten išėjo į Hukoką, siekė Zebuloną pietų pusėje, siekė Ašerą vakarų pusėje ir Judą prie Jordano saulėtekio link.'),
  (@b6, 19, 35, 'O aptverti miestai yra Cidimas, Ceras, Hamatas, Rakatas, Kineretas,'),
  (@b6, 19, 36, 'Adama, Rama, Hacoras,'),
  (@b6, 19, 37, 'Kedešas, Edrejis, En-Hacoras,'),
  (@b6, 19, 38, 'Ironas, Migdal-Elis, Horemas, Bet-Anatas ir Bet-Šemešas – devyniolika miestų su jų kaimais.'),
  (@b6, 19, 39, 'Šitas yra Naftalio vaikų genties paveldas pagal jų šeimas, miestai ir jų kaimai.'),
  (@b6, 19, 40, 'O septintasis burtas išėjo Dano vaikų genčiai pagal jų šeimas.'),
  (@b6, 19, 41, 'Ir jų paveldo riba buvo Cora, Eštaolas, Ir-Šemešas,'),
  (@b6, 19, 42, 'Šaalabinas, Ajalonas, Itla,'),
  (@b6, 19, 43, 'Elonas, Timnata, Ekronas,'),
  (@b6, 19, 44, 'Eltekė, Gibetonas, Baalatas,'),
  (@b6, 19, 45, 'Jehudas, Bene-Berakas ir Gat-Rimonas,'),
  (@b6, 19, 46, 'Me-Jarkonas ir Rakonas, su riba priešais Jafą.'),
  (@b6, 19, 47, 'O Dano vaikų riba išėjo jiems per maža; todėl Dano vaikai ėjo aukštyn kovoti prieš Lešemą, ir jį paėmė, ir iškirto jį kalavijo ašmenimis, ir pasisavino jį, ir jame apsigyveno, ir pavadino Lešemą Danu pagal jų tėvo vardą Daną.'),
  (@b6, 19, 48, 'Šitas yra Dano vaikų genties paveldas pagal jų šeimas, šitie miestai su jų kaimais.'),
  (@b6, 19, 49, 'Baigę dalinti šalį paveldui pagal jų ribas, Izraelio vaikai davė Nūno sūnui Jozuei paveldą savo tarpe;'),
  (@b6, 19, 50, 'pagal VIEŠPATIES žodį jie davė jam miestą, kurio jis prašė – Timnat-Serachą Efraimo kalne; ir jis pastatė miestą ir apsigyveno jame.'),
  (@b6, 19, 51, 'Šitie yra paveldai, kuriuos paveldėjimui burtu padalijo kunigas Eleazaras, Nūno sūnus Jozuė ir Izraelio vaikų genčių tėvų galvos Šilojuje, VIEŠPATIES akivaizdoje, prie susirinkimo padangtės durų. Taip jie baigė dalyti šalį.'),
  (@b6, 20, 1, 'VIEŠPATS dar kalbėjo Jozuei, sakydamas:'),
  (@b6, 20, 2, '„Kalbėk Izraelio vaikams, sakydamas: ‘Pasiskirkite sau prieglobsčio miestų, apie kuriuos jums kalbėjau per Mozės ranką,'),
  (@b6, 20, 3, 'kad ten galėtų pabėgti užmušėjas, kuris užmuša kurį asmenį netyčia, nežinodamas; ir jie bus jūsų prieglobstis nuo kraujo keršytojo.'),
  (@b6, 20, 4, 'Ir jis, pabėgęs į kurį nors iš šitų miestų, atsistos prie miesto vartų įėjimo ir išdėstys savo bylą to miesto vyresniesiems į ausis, tada jie jį paims pas save į miestą ir duos jam vietą, kad jis tarp jų gyventų.'),
  (@b6, 20, 5, 'O jei jį atsivys kraujo keršytojas, tuomet jie neatiduos užmušėjo į ano ranką; nes jis nežinodamas užmušė savo artimą ir nebuvo jo anksčiau nekentęs.'),
  (@b6, 20, 6, 'Ir jis gyvens tame mieste iki stos į teismą susirinkimo akivaizdoje ir iki mirties aukščiausiojo kunigo, kuris bus tomis dienomis; paskui užmušėjas sugrįš ir ateis į savo miestą bei savo namus ir į tą miestą, iš kurio jis buvo pabėgęs’“.'),
  (@b6, 20, 7, 'Ir jie paskyrė Kedešą Galilėjoje, Naftalio kalne, Šechemą Efraimo kalne ir Kirjat-Arbą, kuris yra Hebronas, Judos kalne.'),
  (@b6, 20, 8, 'O anapus Jordano, į rytus prie Jericho, jie paskyrė Becerą dykumoje, lygumoje, iš Rubeno genties, Ramotą Gileade iš Gado genties ir Golaną Bašane iš Manaso genties.'),
  (@b6, 20, 9, 'Šitie buvo miestai, paskirti visiems Izraelio vaikams ir ateiviams, laikinai apsigyvenusiems tarp jų, kad į juos galėtų pabėgti kiekvienas, užmušęs kurį asmenį netyčia, kad nemirtų nuo kraujo keršytojo rankos, kol stos susirinkimo akivaizdon.'),
  (@b6, 21, 1, 'Tada levitų tėvų galvos prisiartino prie kunigo Eleazaro, Nūno sūnaus Jozuės ir Izraelio vaikų genčių tėvų galvų;'),
  (@b6, 21, 2, 'ir jiems kalbėjo Šilojuje, Kanaano šalyje, sakydami: „VIEŠPATS įsakė per Mozės ranką duoti mums miestų apsigyventi su jų priemiesčiais mūsų galvijams“.'),
  (@b6, 21, 3, 'Ir Izraelio vaikai davė levitams iš savo paveldo VIEŠPATIES įsakymu šituos miestus ir jų priemiesčius.'),
  (@b6, 21, 4, 'Ir burtas išėjo kehatų šeimoms; ir kunigo Aarono vaikai, esantys iš levitų, burtu gavo iš Judos genties, iš Simeono genties ir iš Benjamino genties, trylika miestų.'),
  (@b6, 21, 5, 'O likusieji iš Kehato vaikų burtu gavo iš Efraimo genties šeimų, iš Dano genties ir iš pusės Manaso genties, dešimt miestų.'),
  (@b6, 21, 6, 'O Geršono vaikai burtu gavo iš Isacharo genties šeimų, iš Ašero genties, iš Naftalio genties ir iš pusės Manaso genties Bašane, trylika miestų.'),
  (@b6, 21, 7, 'Merario vaikai, pagal jų šeimas, gavo iš Rubeno genties, iš Gado genties ir iš Zebulono genties, dvylika miestų.'),
  (@b6, 21, 8, 'Ir Izraelio vaikai burtu davė levitams šituos miestus su jų priemiesčiais, kaip VIEŠPATS įsakė per Mozės ranką.'),
  (@b6, 21, 9, 'Ir jie davė iš Judos vaikų genties ir iš Simeono vaikų genties šiuos miestus, kurie čia paminėti vardais,'),
  (@b6, 21, 10, 'kuriuos gavo Aarono vaikai, esantys iš kehatų šeimų, kurie yra iš Levio vaikų; nes jų buvo pirmasis burtas.'),
  (@b6, 21, 11, 'Ir jie davė jiems Anako tėvo Arbos miestą, kuris yra Hebronas, Judos kalvų krašte su jo priemiesčiais aplink jį.'),
  (@b6, 21, 12, 'Bet miesto laukus ir jo kaimus jie davė Jefunės sūnui Kalebui jo nuosavybėn.'),
  (@b6, 21, 13, 'Taip kunigo Aarono vaikams jie davė Hebroną su jo priemiesčiais, būti prieglobsčio miestu užmušėjui; ir Libną su jos priemiesčiais,'),
  (@b6, 21, 14, 'Jatyrą su jo priemiesčiais, Eštemoją su jos priemiesčiais,'),
  (@b6, 21, 15, 'Holoną su jo priemiesčiais, Debyrą su jo priemiesčiais,'),
  (@b6, 21, 16, 'Ainą su jo priemiesčiais, Jutą su jos priemiesčiais ir Bet-Šemešą su jo priemiesčiais – devynis miestus iš šitų abiejų genčių.'),
  (@b6, 21, 17, 'O iš Benjamino genties – Gibeoną su jo priemiesčiais, Gebą su jos priemiesčiais,'),
  (@b6, 21, 18, 'Anatotą su jo priemiesčiais ir Almoną su jo priemiesčiais – keturis miestus.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b6, 21, 19, 'Kunigų, Aarono vaikų, miestų iš viso buvo trylika miestų su jų priemiesčiais.'),
  (@b6, 21, 20, 'O Kehato vaikų šeimos, levitai, likę iš Kehato vaikų, gavo jų burto miestus iš Efraimo genties.'),
  (@b6, 21, 21, 'Nes jie davė jiems Šechemą su jo priemiesčiais Efraimo kalne, būti užmušėjui prieglobsčio miestu; ir Gezerą su jo priemiesčiais,'),
  (@b6, 21, 22, 'Kibcaimą su jo priemiesčiais ir Bet-Horoną su jo priemiesčiais – keturis miestus.'),
  (@b6, 21, 23, 'O iš Dano genties – Eltekę su jos priemiesčiais, Gibetoną su jo priemiesčiais,'),
  (@b6, 21, 24, 'Ajaloną su jo priemiesčiais, Gat-Rimoną su jo priemiesčiais – keturis miestus.'),
  (@b6, 21, 25, 'O iš pusės Manaso genties – Tanachą su jo priemiesčiais ir Gat-Rimoną su jo priemiesčiais – du miestus.'),
  (@b6, 21, 26, 'Iš viso buvo dešimt miestų su jų priemiesčiais likusioms Kehato vaikų šeimoms.'),
  (@b6, 21, 27, 'O Geršono vaikams iš levitų šeimų iš kitos pusės Manaso genties jie davė Bašane esantį Golaną su jo priemiesčiais, būti prieglobsčio miestu užmušėjui; ir Beeš-Terą su jos priemiesčiais – du miestus.'),
  (@b6, 21, 28, 'O iš Isacharo genties – Kišjoną su jo priemiesčiais, Daberatą su jo priemiesčiais,'),
  (@b6, 21, 29, 'Jarmutą su jo priemiesčiais, En-Ganimą su jo priemiesčiais – keturis miestus.'),
  (@b6, 21, 30, 'O iš Ašero genties – Mišalą su jo priemiesčiais, Abdoną su jo priemiesčiais,'),
  (@b6, 21, 31, 'Helkatą su jo priemiesčiais ir Rehobą su jo priemiesčiais – keturis miestus.'),
  (@b6, 21, 32, 'O iš Naftalio genties – Kedešą Galilėjoje su jo priemiesčiais, būti prieglobsčio miestu užmušėjui; Hamot-Dorą su jo priemiesčiais ir Kartaną su jo priemiesčiais – tris miestus.'),
  (@b6, 21, 33, 'Geršonų pagal jų šeimas miestų iš viso buvo trylika miestų su jų priemiesčiais.'),
  (@b6, 21, 34, 'O Merario vaikų šeimoms, likusiems levitams, iš Zebulono genties davė Jokneamą su jo priemiesčiais, Kartą su jos priemiesčiais,'),
  (@b6, 21, 35, 'Dimną su jos priemiesčiais, Nahalalą su jo priemiesčiais – keturis miestus.'),
  (@b6, 21, 36, 'O iš Rubeno genties – Becerą su jo priemiesčiais, Jahcą su jos priemiesčiais,'),
  (@b6, 21, 37, 'Kedemotą su jo priemiesčiais ir Mefaatą su jo priemiesčiais – keturis miestus.'),
  (@b6, 21, 38, 'O iš Gado genties – Ramotą Gileade su jo priemiesčiais, būti prieglobsčio miestu užmušėjui; Mahanaimą su jo priemiesčiais,'),
  (@b6, 21, 39, 'Hešboną su jo priemiesčiais, Jazerą su jo priemiesčiais – iš viso keturis miestus.'),
  (@b6, 21, 40, 'Taigi iš viso miestų Merario vaikams, likusiems iš levitų šeimų, pagal jų šeimas, jų burtu buvo dvylika miestų.'),
  (@b6, 21, 41, 'Iš viso levitų miestų Izraelio vaikų nuosavybės viduje buvo keturiasdešimt aštuoni miestai su jų priemiesčiais.'),
  (@b6, 21, 42, 'Kiekvienas iš šitų miestų buvo su savo priemiesčiais, esančiais aplink juos; tokie buvo visi šitie miestai.'),
  (@b6, 21, 43, 'Ir VIEŠPATS davė Izraeliui visą šalį, kurią jis prisiekė duoti jų tėvams; ir jie ją pasisavino ir gyveno joje.'),
  (@b6, 21, 44, 'Ir VIEŠPATS jiems aplinkui davė poilsį pagal visa tai, ką jis prisiekė jų tėvams; ir nei vienas iš visų jų priešų neatsilaikė prieš juos; visus jų priešus VIEŠPATS atidavė į jų ranką.'),
  (@b6, 21, 45, 'Nepristigo nei vieno iš visų gerų dalykų, kuriuos VIEŠPATS buvo kalbėjęs Izraelio namams; viskas įvyko.'),
  (@b6, 22, 1, 'Tada Jozuė pasišaukė rubenus, gadus ir pusę Manaso genties'),
  (@b6, 22, 2, 'ir tarė jiems: „Jūs laikėtės visko, ką VIEŠPATIES tarnas Mozė jums įsakė, ir paklusote mano balsui visame, ką jums įsakiau;'),
  (@b6, 22, 3, 'jūs nepalikote savo brolių per šitas daugelį dienų iki šios dienos, bet laikėtės VIEŠPATIES, savo Dievo, įsakymo įpareigojimo.'),
  (@b6, 22, 4, 'O dabar VIEŠPATS, jūsų Dievas, yra davęs jūsų broliams poilsį, kaip jiems pažadėjo; taigi dabar sugrįžkite ir eikite į savo palapines, į savo nuosavybės šalį, kurią VIEŠPATIES tarnas Mozė jums davė anapus Jordano.'),
  (@b6, 22, 5, 'Tik stropiai žiūrėkite, kad vykdytumėte įsakymą ir įstatymą, kurį VIEŠPATIES tarnas Mozė jums įpareigojo: mylėti VIEŠPATĮ, jūsų Dievą, vaikščioti visais jo keliais, laikytis jo įsakymų, prilipti prie jo ir jam tarnauti visa savo širdimi ir visa savo siela“.'),
  (@b6, 22, 6, 'Taigi Jozuė juos palaimino ir išleido; ir jie ėjo į savo palapines.'),
  (@b6, 22, 7, 'Na, o vienai Manaso genties pusei Mozė buvo davęs nuosavybę Bašane, o kitai jos pusei Jozuė davė jų brolių tarpe šiapus Jordano į vakarus. Ir kai Jozuė juos paleido į jų palapines, tuomet ir juos palaimino'),
  (@b6, 22, 8, 'ir kalbėjo jiems, sakydamas: „Su dideliais turtais grįžkite į savo palapines, su labai daug galvijų, su sidabru, su auksu, su žalvariu, su geležimi ir su labai daug drabužių; pasidalykite savo priešų grobiu su savo broliais“.'),
  (@b6, 22, 9, 'O Rubeno vaikai, Gado vaikai ir pusė Manaso genties sugrįžo ir išėjo nuo Izraelio vaikų iš Šilojaus, esančio Kanaano šalyje, kad eitų į Gileado kraštą, į savo nuosavybės šalį, kurią jie buvo pasisavinę, pagal VIEŠPATIES žodį per Mozės ranką.'),
  (@b6, 22, 10, 'Ir atėję prie Jordano ribų, esančių Kanaano šalyje, Rubeno vaikai, Gado vaikai ir pusė Manaso genties ten prie Jordano pastatė aukurą, matomą didžiulį aukurą.'),
  (@b6, 22, 11, 'Ir Izraelio vaikai išgirdo sakant: „Štai Rubeno vaikai, Gado vaikai ir pusė Manaso genties pastatė aukurą priešais Kanaano šalį, Jordano ribose, prie Izraelio vaikų praėjimo“.'),
  (@b6, 22, 12, 'Ir kai Izraelio vaikai tai išgirdo, visas Izraelio vaikų susirinkimas susirinko į Šilojų, kad eitų prieš juos į karą.'),
  (@b6, 22, 13, 'Ir Izraelio vaikai siuntė pas Rubeno vaikus, pas Gado vaikus ir pas pusę Manaso genties į Gileado šalį kunigo Eleazaro sūnų Finehasą'),
  (@b6, 22, 14, 'ir su juo dešimt kunigaikščių, iš kiekvienų vyriausiųjų namų po kunigaikštį iš visų Izraelio genčių; ir kiekvienas jų buvo savo tėvų namų galva tarp Izraelio tūkstančių.'),
  (@b6, 22, 15, 'Ir jie atėjo pas Rubeno vaikus, Gado vaikus ir pas pusę Manaso genties į Gileado šalį ir jiems kalbėjo, sakydami:'),
  (@b6, 22, 16, '„Taip sako visas VIEŠPATIES susirinkimas: ‘Kas tai per nusižengimas, kurį padarėte prieš Izraelio Dievą, nusigręždami šią dieną nuo sekimo paskui VIEŠPATĮ, statydamiesi aukurą, kad šią dieną maištautumėte prieš VIEŠPATĮ?'),
  (@b6, 22, 17, 'Argi mums per maža Peoro neteisybės, nuo kurios mes nesame apsivalę iki šios dienos, nors ir buvo rykštė VIEŠPATIES susirinkime,'),
  (@b6, 22, 18, 'kad nusigręžiate šią dieną nuo sekimo paskui VIEŠPATĮ? Ir bus, kadangi jūs šiandien maištaujate prieš VIEŠPATĮ, tai rytoj jis užsirūstins ant viso Izraelio susirinkimo.'),
  (@b6, 22, 19, 'Tačiau jei jūsų nuosavybės šalis nešvari, tai pereikite į VIEŠPATIES nuosavybės šalį, kurioje gyvena VIEŠPATIES padangtė, ir pasiimkite nuosavybę tarp mūsų; bet nemaištaukite prieš VIEŠPATĮ ir nemaištaukite prieš mus, statydamiesi aukurą šalia VIEŠPATIES, mūsų Dievo, aukuro.'),
  (@b6, 22, 20, 'Argi Zeracho sūnus Achanas nenusižengė prakeiktu dalyku, ir ar neištiko rūstybė ant viso Izraelio susirinkimo? Ir tas žmogus ne vienas pražuvo savo neteisybėje.’“'),
  (@b6, 22, 21, 'Tada Rubeno vaikai, Gado vaikai ir pusė Manaso genties atsakydami kalbėjo Izraelio tūkstančių galvoms:'),
  (@b6, 22, 22, '„VIEŠPATS dievų Dievas, VIEŠPATS dievų Dievas, jis žino, ir pats Izraelis žinos; jei tai būtų maištu ar nusižengimu prieš VIEŠPATĮ (šią dieną negelbėk mūsų),'),
  (@b6, 22, 23, 'kad pasistatėme aukurą, kad nusigręžtume nuo sekimo paskui VIEŠPATĮ ar jei atnašautume ant jo deginamąsias atnašas ar maisto atnašas, ar jei atnašautume ant jo taikos atnašas, tai pats VIEŠPATS to tepareikalauja;'),
  (@b6, 22, 24, 'jei mes to nepadarėme bijodami to dalyko, sakydami: Ateityje jūsų vaikai kalbėtų mūsų vaikams, sakydami: ‘Kas jums darbo su VIEŠPAČIU, Izraelio Dievu?'),
  (@b6, 22, 25, 'Nes VIEŠPATS padarė Jordaną riba tarp mūsų ir jūsų, jūs, Rubeno vaikai ir Gado vaikai; jūs neturite dalies VIEŠPATYJE’; taip jūsų vaikai padarytų, kad mūsų vaikai liautųsi bijoję VIEŠPATIES.'),
  (@b6, 22, 26, 'Todėl mes sakėmė: ‘Ruoškimės pasistatyti aukurą ne deginamajai atnašai ir ne aukai;'),
  (@b6, 22, 27, 'bet kad jis būtų liudytojas tarp mūsų ir jūsų ir tarp mūsų kartų po mūsų, kad mes galėtume atlikti VIEŠPATIES tarnystę jo akivaizdoje savo deginamosiomis atnašomis, savo aukomis ir savo taikos atnašomis; kad ateinančiais laikais jūsų vaikai nesakytų mūsų vaikams: ‘Jūs neturite dalies VIEŠPATYJE’.'),
  (@b6, 22, 28, 'Todėl sakėme, kad bus, kai ateinančiais laikais jie taip sakys mums ar mūsų kartoms, tada mes atsakysime: ‘Pažiūrėkite į VIEŠPATIES aukuro pavyzdį, kurį padarė mūsų tėvai ne deginamosioms atnašoms ir ne aukoms; bet jis yra liudytojas tarp mūsų ir jūsų’.'),
  (@b6, 22, 29, 'Gink Dieve, kad mes maištautume prieš VIEŠPATĮ ir šią dieną nusigręžtume nuo sekimo paskui VIEŠPATĮ, statydami aukurą deginamosioms atnašoms, maisto atnašoms ar aukoms šalia VIEŠPATIES, mūsų Dievo, aukuro, esančio prieš jo padangtę“.'),
  (@b6, 22, 30, 'Ir kai kunigas Finehasas ir su juo esantys susirinkimo kunigaikščiai bei Izraelio tūkstančių galvos išgirdo žodžius, kuriuos kalbėjo Rubeno vaikai, Gado vaikai ir Manaso vaikai, jiems tai patiko.'),
  (@b6, 22, 31, 'Ir Finehasas, kunigo Eleazaro sūnus, tarė Rubeno vaikams, Gado vaikams ir Manaso vaikams: „Šią dieną supratome, kad VIEŠPATS yra tarp mūsų, kadangi jūs nepadarėte šio nusižengimo prieš VIEŠPATĮ; dabar jūs išgelbėjote Izraelio vaikus iš VIEŠPATIES rankos“.'),
  (@b6, 22, 32, 'Ir kunigo Eleazaro sūnus Finehasas ir kunigaikščiai sugrįžo nuo Rubeno vaikų ir nuo Gado vaikų iš Gileado šalies į Kanaano šalį pas Izraelio vaikus ir jiems parnešė žinią.'),
  (@b6, 22, 33, 'Ir tas dalykas patiko Izraelio vaikams; ir Izraelio vaikai laimino Dievą ir neketino eiti prieš juos aukštyn į mūšį, kad sunaikintų šalį, kurioje gyveno Rubeno ir Gado vaikai.'),
  (@b6, 22, 34, 'O Rubeno vaikai ir Gado vaikai praminė tą aukurą Edu; „nes jis bus liudytojas tarp mūsų, kad VIEŠPATS yra Dievas“.'),
  (@b6, 23, 1, 'Ir ilgam laikui praslinkus po to, kai VIEŠPATS buvo davęs Izraeliui poilsį nuo visų jų aplinkinių priešų, įvyko, kad Jozuė paseno palaužtas amžiaus.'),
  (@b6, 23, 2, 'Ir Jozuė sušaukė visą Izraelį, jo vyresniuosius, jo galvas, jo teisėjus ir jo pareigūnus ir jiems tarė: „Aš esu senas ir palaužtas amžiaus;'),
  (@b6, 23, 3, 'ir jūs matėte viską, ką VIEŠPATS, jūsų Dievas, padarė visoms šitoms tautoms dėl jūsų; nes VIEŠPATS, jūsų Dievas, yra tas, kuris kariavo už jus.'),
  (@b6, 23, 4, 'Štai aš jums burtu padalinau šitas likusias tautas, kad būtų paveldas jūsų gentims, nuo Jordano su visomis tautomis, kurias iškirtau, iki Didžiosios jūros į vakarus.'),
  (@b6, 23, 5, 'O VIEŠPATS, jūsų Dievas, jis jas išvys jums iš akivaizdos ir išvarys jas iš jūsų akių; ir jūs pasisavinsite jų šalį, kaip VIEŠPATS, jūsų Dievas, jums pažadėjo.'),
  (@b6, 23, 6, 'Todėl būkite labai drąsūs, kad laikytumėtės ir vykdytumėte viską, kas parašyta Mozės įstatymo knygoje, kad nenukryptumėte nuo to nei į dešinę, nei į kairę;'),
  (@b6, 23, 7, 'kad neateitumėte į tarpą šitų tautų, tų, kurios liko tarp jūsų; taip pat neminėkite jų dievų vardo nei prisaikdinkite jais, nei tarnaukite jiems, nei lenkitės prieš juos;'),
  (@b6, 23, 8, 'bet prilipkite prie VIEŠPATIES, savo Dievo, kaip esate darę iki šios dienos.'),
  (@b6, 23, 9, 'Nes VIEŠPATS išvarė jums iš akivaizdos dideles ir stiprias tautas; bet dėl jūsų, niekas nepajėgė jūsų akivaizdoje išsilaikyti iki šios dienos.'),
  (@b6, 23, 10, 'Jūsų vienas vysis tūkstantį, nes VIEŠPATS, jūsų Dievas, jis yra tas, kuris kovoja už jus, kaip jums yra pažadėjęs.'),
  (@b6, 23, 11, 'Todėl labai žiūrėkite savęs, kad mylėtumėte VIEŠPATĮ, savo Dievą.'),
  (@b6, 23, 12, 'Priešingu atveju, jei kokiu būdu sugrįšite ir prilipsite prie likučio šitų tautų, tai yra likusių tarp jūsų, ir sudarysite su jomis santuokas, įeisite pas jas, o jos pas jus;'),
  (@b6, 23, 13, 'tvirtai žinokite, kad VIEŠPATS, jūsų Dievas, nebeišvarys jokių iš šitų tautų iš jūsų akivaizdos; bet jos bus jums spąstai ir žabangos, ir rimbai jūsų šonuose, ir dygliai jūsų akyse, kol pražūsite iš šitos geros šalies, kurią VIEŠPATS, jūsų Dievas, jums davė.'),
  (@b6, 23, 14, 'Ir štai šią dieną aš einu visos žemės keliu; o jūs žinote visa savo širdimi ir visa savo siela, kad nestigo nei vieno iš visų gerų dalykų, kuriuos VIEŠPATS, jūsų Dievas, kalbėjo dėl jūsų; visi jums įvyko, nei vieno dalyko iš jų nepristigo.'),
  (@b6, 23, 15, 'Todėl įvyks, kad kaip jums atėjo visi geri dalykai, kuriuos VIEŠPATS, jūsų Dievas, jums pažadėjo; taip VIEŠPATS jums atneš visus blogus dalykus, kol jus išnaikins iš šitos geros šalies, kurią VIEŠPATS, jūsų Dievas, jums yra davęs.'),
  (@b6, 23, 16, 'Kai būsite nusižengę VIEŠPATIES, savo Dievo, sandorai, kurią jis jums įsakė, ir būsite nuėję bei tarnavę kitiems dievams ir jiems lankstęsi, tada VIEŠPATIES pyktis užsidegs prieš jus, ir jūs greitai pražūsite iš tos geros šalies, kurią jis jums yra davęs“.'),
  (@b6, 24, 1, 'Ir Jozuė surinko visas Izraelio gentis į Šechemą ir sušaukė Izraelio vyresniuosius, jo galvas, jo teisėjus bei jo pareigūnus; ir jie prisistatė Dievo akivaizdoje.'),
  (@b6, 24, 2, 'Ir Jozuė tarė visai tautai: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Senais laikais anapus upės gyveno jūsų tėvai, tai yra Teras – Abraomo tėvas ir Nahoro tėvas, ir jie tarnavo kitiems dievams.'),
  (@b6, 24, 3, 'Ir aš paėmiau jūsų tėvą Abraomą iš anapus upės ir jį vedžiau per visą Kanaano šalį, ir padauginau jo sėklą, ir daviau jam Izaoką.'),
  (@b6, 24, 4, 'O Izaokui daviau Jokūbą ir Ezavą; o Ezavui daviau Seyro kalną, kad jį pasisavintų; bet Jokūbas ir jo vaikai nusileido į Egiptą.'),
  (@b6, 24, 5, 'Taip pat nusiunčiau Mozę bei Aaroną ir ištikau rykštėmis Egiptą pagal tai, ką tarp jų dariau; o paskui jus išvedžiau.'),
  (@b6, 24, 6, 'Ir aš išvedžiau jūsų tėvus iš Egipto; ir jūs atėjote prie jūros; o egiptiečiai vijosi jūsų tėvus su vežimais ir raiteliais iki Raudonosios jūros.'),
  (@b6, 24, 7, 'Ir jiems šaukiantis VIEŠPATIES, jis pastatė tamsą tarp jūsų ir egiptiečių, ir užleido ant jų jūrą, ir apdengė juos; ir jūsų akys matė, ką padariau Egipte; ir jūs ilgą laiką gyvenote dykumoje.'),
  (@b6, 24, 8, 'Ir atvedžiau jus į šalį amoritų, gyvenusių anapus Jordano; ir jie kovojo su jumis; o aš juos padaviau į jūsų ranką, kad pasisavintumėte jų šalį; ir juos išnaikinau iš jūsų akivaizdos.'),
  (@b6, 24, 9, 'Paskui pakilo Ciporo sūnus Balakas, Moabo karalius, ir kariavo prieš Izraelį, ir pasiuntęs pasišaukė Beoro sūnų Balaamą, kad jus prakeiktų;'),
  (@b6, 24, 10, 'bet aš nenorėjau klausyti Balaamo; todėl jis jus vis laimino; taip jus išvadavau iš jo rankos.'),
  (@b6, 24, 11, 'Ir jūs perėjote per Jordaną ir atėjote į Jerichą; ir Jericho žmonės, amoritai, perizai, kanaaniečiai, hetitai, girgašai, hivai ir jebusiečiai kovojo prieš jus; o aš juos atidaviau į jūsų ranką.'),
  (@b6, 24, 12, 'Ir siunčiau pirma jūsų širšes, kurios išvarė jums iš akivaizdos juos – du amoritų karalius; bet ne tavo kalaviju ir ne tavo lanku.'),
  (@b6, 24, 13, 'Ir daviau jums šalį, dėl kurios nedirbote, ir miestus, kurių nestatėte, o juose gyvenate; jūs maitinatės iš vynuogynų ir alyvmedžių sodų, kurių nesodinote’.'),
  (@b6, 24, 14, 'Taigi dabar bijokite VIEŠPATIES ir nuoširdumu bei tiesa jam tarnaukite; ir pašalinkite dievus, kuriems tarnavo jūsų tėvai anapus upės ir Egipte; ir tarnaukite VIEŠPAČIUI.'),
  (@b6, 24, 15, 'O jei jums atrodo bloga tarnauti VIEŠPAČIUI, šią dieną pasirinkite, kam norite tarnauti: ar dievams, kuriems tarnavo jūsų tėvai, buvusieji anapus upės, ar dievams amoritų, kurių šalyje jūs gyvenate; bet aš ir mano namai, mes tarnausime VIEŠPAČIUI“.'),
  (@b6, 24, 16, 'Ir tauta atsakydama tarė: „Apsaugok Dieve, kad paliktume VIEŠPATĮ ir tarnautume kitiems dievams;'),
  (@b6, 24, 17, 'nes VIEŠPATS, mūsų Dievas, jis yra tas, kuris išvedė aukštyn mus ir mūsų tėvus iš Egipto šalies, iš vergijos namų, ir kuris darė mūsų akyse šituos didžius ženklus ir saugojo mus visame kelyje, kuriuo ėjome, ir tarp visų tautų, per kurias perėjome;'),
  (@b6, 24, 18, 'ir VIEŠPATS išvarė mums iš akivaizdos visas tautas, amoritus, gyvenusius šalyje; todėl mes irgi tarnausime VIEŠPAČIUI; nes jis yra mūsų Dievas“.'),
  (@b6, 24, 19, 'O Jozuė tarė tautai: „Jūs negalite tarnauti VIEŠPAČIUI; nes jis yra šventas Dievas; jis yra pavydus Dievas; jis neatleis jūsų nusižengimų ir jūsų nuodėmių.'),
  (@b6, 24, 20, 'Jei paliksite VIEŠPATĮ ir tarnausite svetimiems dievams, tada jis atsigręš ir darys jums pikta, ir jus sunaikins po to, kai bus jums daręs gera“.'),
  (@b6, 24, 21, 'O tauta tarė Jozuei: „Ne; mes tarnausime VIEŠPAČIUI“.'),
  (@b6, 24, 22, 'O Jozuė tarė tautai: „Jūs esate liudytojai prieš save, kad pasirinkote VIEŠPATĮ, jam tarnauti“. Ir jie tarė: „Mes esame liudininkai“.'),
  (@b6, 24, 23, '„Todėl dabar, sako jis, pašalinkite svetimus dievus, esančius tarp jūsų, ir palenkite savo širdis į VIEŠPATĮ, Izraelio Dievą“.'),
  (@b6, 24, 24, 'Ir tauta tarė Jozuei: „VIEŠPAČIUI, savo Dievui, tarnausime ir jo balsui paklusime“.'),
  (@b6, 24, 25, 'Taip tą dieną Jozuė sudarė su tauta sandorą ir jai paskyrė įstatą ir įsaką Šecheme.'),
  (@b6, 24, 26, 'Ir Jozuė įrašė šituos žodžius į Dievo įstatymo knygą, paėmė didžiulį akmenį ir jį ten pastatė po ąžuolu, esančiu prie VIEŠPATIES šventovės.'),
  (@b6, 24, 27, 'Ir Jozuė tarė visai tautai: „Štai šis akmuo bus mums liudytojas; nes jis girdėjo visus VIEŠPATIES žodžius, kuriuos jis mums kalbėjo; todėl jis bus jums liudytojas, kad neišsigintumėte savo Dievo“.'),
  (@b6, 24, 28, 'Taigi Jozuė paleido tautą, kiekvieną į savąjį paveldą.'),
  (@b6, 24, 29, 'Ir įvyko po šitų dalykų, kad mirė Nūno sūnus Jozuė, VIEŠPATIES tarnas, būdamas šimto dešimties metų.'),
  (@b6, 24, 30, 'Ir jie palaidojo jį jo paveldo ribose, Timnat-Serache, esančiame Efraimo kalne, Gaašo kalvos šiaurinėje pusėje.'),
  (@b6, 24, 31, 'Ir Izraelis tarnavo VIEŠPAČIUI per visas Jozuės dienas ir per visas dienas vyresniųjų, kurie gyveno ilgiau už Jozuę ir kurie žinojo visus VIEŠPATIES darbus, kuriuos jis buvo padaręs Izraeliui.'),
  (@b6, 24, 32, 'O Juozapo kaulus, kuriuos Izraelio vaikai atgabeno iš Egipto, jie palaidojo Šecheme, žemės sklype, kurį Jokūbas nupirko iš Šechemo tėvo Hamoro sūnų už šimtą sidabrinių; ir tai tapo Juozapo vaikų paveldu.'),
  (@b6, 24, 33, 'Ir mirė Aarono sūnus Eleazaras; ir jie jį palaidojo kalvoje, priklausančioje jo sūnui Finehasui, kuri jam buvo duota Efraimo kalne.'),
  (@b7, 1, 1, 'Na, o po Jozuės mirties įvyko, kad Izraelio vaikai klausė VIEŠPATIES, sakydami: „Kas mums pirmas eis aukštyn prieš kanaaniečius kovoti prieš juos?“'),
  (@b7, 1, 2, 'Ir VIEŠPATS tarė: „Juda eis aukštyn; štai aš atidaviau šalį į jo ranką“.'),
  (@b7, 1, 3, 'Ir Juda sakė savo broliui Simeonui: „Eik aukštyn su manimi į mano burtą, kad mes kovotume prieš kanaaniečius; ir aš taip pat eisiu su tavimi į tavo burtą“. Taigi Simeonas nuėjo su juo.'),
  (@b7, 1, 4, 'Ir Juda ėjo aukštyn; ir VIEŠPATS atidavė į jų ranką kanaaniečius ir perizus; ir jie išžudė iš jų Bezeke dešimt tūkstančių vyrų.'),
  (@b7, 1, 5, 'Ir Bezeke jie rado Adoni-Bezeką; ir jie kariavo prieš jį ir sumušė kanaaniečius ir perizus.'),
  (@b7, 1, 6, 'Bet Adoni-Bezekas pabėgo; ir jie vijosi jį, sugavo jį ir nukapojo jam rankų nykščius bei kojų nykščius.'),
  (@b7, 1, 7, 'Ir Adoni-Bezekas tarė: „Septyniasdešimt karalių su nukapotais jų rankų nykščiais bei jų kojų nykščiais rinkdavosi po mano stalu sau maisto; kaip aš padariau, taip Dievas man atlygino“. Ir jie nuvedė jį į Jeruzalę, ir ten jis mirė.'),
  (@b7, 1, 8, 'Na, o Judos vaikai kariavo prieš Jeruzalę ir paėmė ją, ir iškirto ją kalavijo ašmenimis, o miestą padegė.'),
  (@b7, 1, 9, 'O paskui Judos vaikai ėjo žemyn kariauti prieš kanaaniečius, gyvenančius kalne, pietuose ir slėnyje.'),
  (@b7, 1, 10, 'Ir Juda ėjo prieš kanaaniečius, gyvenančius Hebrone (na, o Hebrono vardas anksčiau buvo Kirjat-Arba); ir jie sumušė Šešają, Ahimaną ir Talmają.'),
  (@b7, 1, 11, 'O iš ten jis ėjo prieš Debyro gyventojus; o Debyro vardas anksčiau buvo Kirjat-Seferas;'),
  (@b7, 1, 12, 'ir Kalebas sakė: „Kas sumuš Kirjat-Seferą ir jį paims, tam duosiu savo dukterį Achsą į žmonas“.'),
  (@b7, 1, 13, 'Ir jį paėmė Otnielis, jaunesniojo Kalebo brolio Kenazo sūnus; ir jis jam davė savo dukterį Achsą į žmonas.'),
  (@b7, 1, 14, 'Ir įvyko, kad atėjusi pas jį ji paskatino jį prašyti jos tėvo lauko; ir ji nulipo nuo savo asilo; ir Kalebas jai tarė: „Ko nori?“'),
  (@b7, 1, 15, 'Ir ji jam tarė: „Duok man palaiminimą; nes tu man davei pietų šalį; duok man ir vandens šaltinius“. Ir Kalebas jai davė aukštutinius šaltinius ir žemutinius šaltinius.'),
  (@b7, 1, 16, 'Ir Mozės uošvio kenito vaikai ėjo aukštyn iš Palmių miesto su Judos vaikais į Judos dykumą, esančią Arado pietuose; ir jie nuėjo ir apsigyveno tautos tarpe.'),
  (@b7, 1, 17, 'Ir Juda nuėjo su savo broliu Simeonu, ir jie sumušė kanaaniečius, gyvenančius Cefate, ir jį visiškai sunaikino. Ir tas miestas buvo pavadintas vardu Horma.'),
  (@b7, 1, 18, 'Taip pat Juda paėmė Gazą su jos ribomis, Aškeloną su jo ribomis ir Ekroną su jo ribomis.'),
  (@b7, 1, 19, 'Ir VIEŠPATS buvo su Juda; ir jis išvarė kalno gyventojus; bet negalėjo išvaryti slėnio gyventojų, nes jie turėjo geležinių vežimų.'),
  (@b7, 1, 20, 'Ir jie davė Kalebui Hebroną, kaip Mozė sakė; ir iš ten jis išvarė tris Anako sūnus.'),
  (@b7, 1, 21, 'O Benjamino vaikai neišvarė jebusiečių, gyvenančių Jeruzalėje; bet jebusiečiai gyvena su Benjamino vaikais Jeruzalėje iki šios dienos.'),
  (@b7, 1, 22, 'Ir Juozapo namai taip pat ėjo aukštyn prieš Bet-Elį; o VIEŠPATS buvo su jais.'),
  (@b7, 1, 23, 'Ir Juozapo namai siuntė Bet-Elio išžvalgyti (na, o to miesto vardas anksčiau buvo Lūzas).'),
  (@b7, 1, 24, 'Ir žvalgai, pamatę žmogų, išeinantį iš miesto, tarė jam: „Parodyk mums, meldžiame tave, įėjimą į miestą, o mes tau parodysime gailestingumą“.'),
  (@b7, 1, 25, 'O kai jis jiems parodė įėjimą į miestą, jie iškirto miestą kalavijo ašmenimis; bet tą žmogų ir visą jo šeimą paleido.'),
  (@b7, 1, 26, 'Ir tas žmogus nuėjo į hetitų šalį, pastatė miestą ir praminė jį vardu Lūzas; tas yra jo vardas iki šios dienos.'),
  (@b7, 1, 27, 'Taip pat ir Manasas neišvarė gyventojų Bet-Šeano ir jo miestelių, nei Taanacho ir jo miestelių, nei Doro ir jo miestelių gyventojų, nei Ibleamo ir jo miestelių gyventojų, nei Megido ir jo miestelių gyventojų; bet kanaaniečiai norėjo gyventi toje šalyje.'),
  (@b7, 1, 28, 'Ir įvyko, kai Izraelis buvo stiprus, jis uždėjo kanaaniečiams duoklę, bet visiškai jų neišvarė.'),
  (@b7, 1, 29, 'Nei Efraimas neišvarė kanaaniečių, gyvenusių Gezeryje; bet kanaaniečiai gyveno tarp jų Gezeryje.'),
  (@b7, 1, 30, 'Taip pat Zebulonas neišvarė nei Kitrono gyventojų, nei Nahalolo gyventojų; bet kanaaniečiai gyveno tarp jų ir tapo duoklės mokėtojais.'),
  (@b7, 1, 31, 'Taip pat Ašeras neišvarė nei Ako gyventojų, nei Sidono, nei Ahlabo, nei Achzibo, nei Helbos, nei Afiko, nei Rehobo gyventojų;'),
  (@b7, 1, 32, 'bet ašerai gyveno tarp kanaaniečių, šalies gyventojų; nes jie neišvarė jų.'),
  (@b7, 1, 33, 'Taip pat Naftalis neišvarė nei Bet-Šemešo gyventojų, nei Bet-Anato gyventojų; bet jis gyveno tarp kanaaniečių, šalies gyventojų; tačiau Bet-Šemešo ir Bet-Anato gyventojai jiems tapo duoklės mokėtojais.'),
  (@b7, 1, 34, 'O amoritai spaudė Dano vaikus į kalną; nes jie neleido jiems nusileisti į slėnį;'),
  (@b7, 1, 35, 'bet amoritai norėjo gyventi Hereso kalne Ajalone ir Šaalbime; tačiau Juozapo namų ranka nugalėjo taip, kad jie tapo duoklės mokėtojais.'),
  (@b7, 1, 36, 'O amoritų riba buvo nuo pakilimo į Akrabimą, nuo uolos aukštyn.'),
  (@b7, 2, 1, 'Ir VIEŠPATIES angelas atėjo aukštyn iš Gilgalo į Bochimą ir tarė: „Aš išvedžiau jus aukštyn iš Egipto ir atvedžiau jus į šalį, kurią buvau prisiekęs jūsų tėvams; ir pasakiau: ‘Aš niekada nelaužysiu savo sandoros su jumis.'),
  (@b7, 2, 2, 'O jūs nesudarykite sąjungos su šitos šalies gyventojais; nugriaukite jų aukurus’; bet jūs nepaklusote mano balsui; kodėl tai padarėte?'),
  (@b7, 2, 3, 'Todėl ir aš pasakiau: ‘Neišvarysiu jų iš jūsų akivaizdos; bet jie bus kaip dygliai jūsų šonuose, o jų dievai bus jums žabangos’“.'),
  (@b7, 2, 4, 'Ir įvyko, kai VIEŠPATIES angelas kalbėjo šituos žodžius visiems Izraelio vaikams, tada tauta pakėlė savo balsus ir verkė.'),
  (@b7, 2, 5, 'Ir jie praminė tą vietą vardu Bochimas; ir ten jie aukojo VIEŠPAČIUI.'),
  (@b7, 2, 6, 'Ir kai Jozuė paleido tautą, Izraelio vaikai nuėjo kiekvienas į savo paveldą šalies pasisavinti.'),
  (@b7, 2, 7, 'Ir tauta tarnavo VIEŠPAČIUI per visas Jozuės dienas ir per visas dienas vyresniųjų, kurie gyveno ilgiau už Jozuę, kurie buvo matę visus didžius VIEŠPATIES darbus, kuriuos jis padarė Izraeliui.'),
  (@b7, 2, 8, 'O Nūno sūnus Jozuė, VIEŠPATIES tarnas, mirė būdamas šimto dešimties metų.'),
  (@b7, 2, 9, 'Ir jie jį palaidojo jo paveldo ribose, Timnat-Herese, Efraimo kalne, Gaašo kalvos šiaurinėje pusėje.'),
  (@b7, 2, 10, 'Taip pat visa ta karta buvo surinkta pas savo tėvus; ir po jų kilo kita karta, kuri nepažino nei VIEŠPATIES, nei darbų, kuriuos jis buvo padaręs Izraeliui.'),
  (@b7, 2, 11, 'Ir Izraelio vaikai darė pikta VIEŠPATIES akyse ir tarnavo Baalams.'),
  (@b7, 2, 12, 'Ir jie paliko VIEŠPATĮ, savo tėvų Dievą, juos išvedusį iš Egipto šalies, ir nusekė paskui kitus dievus iš dievų tautų, esančių aplink juos, ir lenkėsi jiems, ir kurstė VIEŠPATIES pyktį.'),
  (@b7, 2, 13, 'Ir jie paliko VIEŠPATĮ ir tarnavo Baalui bei Astarotei.'),
  (@b7, 2, 14, 'Ir VIEŠPATIES pyktis užsidegė prieš Izraelį, ir jis juos atidavė į rankas plėšikų, kurie juos apiplėšdavo, ir jis pardavė juos į jų aplinkinių priešų rankas taip, kad jie nebegalėjo atsilaikyti prieš savo priešus.'),
  (@b7, 2, 15, 'Kur tik jie išeidavo, VIEŠPATIES ranka būdavo prieš juos dėl pikto, kaip VIEŠPATS buvo sakęs ir kaip VIEŠPATS jiems buvo prisiekęs; ir jie buvo labai spaudžiami.'),
  (@b7, 2, 16, 'Tačiau VIEŠPATS prikeldavo teisėjų, kurie juos išgelbėdavo iš jų plėšikų rankų.'),
  (@b7, 2, 17, 'Tačiau savo teisėjų jie neklausė, bet nuėjo paleistuvaudami paskui kitus dievus ir jiems lenkėsi; jie greitai nukrypo nuo kelio, kuriuo vaikščiojo jų tėvai, paklusdami VIEŠPATIES įsakymams; bet jie taip nedarė.'),
  (@b7, 2, 18, 'O kai VIEŠPATS jiems prikeldavo teisėjų, tada VIEŠPATS būdavo su teisėju ir išvaduodavo juos iš jų priešų rankos per visas teisėjo dienas; nes VIEŠPAČIUI buvo gaila, kadangi jie dejavo dėl savo engėjų ir prispaudėjų.'),
  (@b7, 2, 19, 'Ir įvyko, kad teisėjui mirus jie sugrįždavo ir sugadindavo save daugiau už savo tėvus, sekdami paskui kitus dievus jiems tarnauti ir jiems lenktis; jie nepaliovė nuo savo pačių darbų ir nuo savo užsispyrusio kelio.'),
  (@b7, 2, 20, 'Ir VIEŠPATIES pyktis užsidegė prieš Izraelį; ir jis tarė: „Kadangi ši tauta nusižengė mano sandorai, kurią įsakiau jų tėvams, ir neklausė mano balso;'),
  (@b7, 2, 21, 'tai ir aš nuo šiol nebeišvarysiu iš jų akivaizdos nei vienos iš tautų, kurias Jozuė mirdamas paliko;'),
  (@b7, 2, 22, 'kad per jas išmėginčiau Izraelį, ar jie laikysis VIEŠPATIES kelio, kad juo vaikščiotų, kaip jo laikėsi jų tėvai, ar ne“.'),
  (@b7, 2, 23, 'Todėl VIEŠPATS paliko šitas tautas, paskubomis jų neišvarydamas; taip pat jis jų neatidavė į Jozuės ranką.'),
  (@b7, 3, 1, 'Na, o šitos yra tautos, kurias VIEŠPATS paliko, kad jomis išmėgintų Izraelį, tai yra visus iš Izraelio, kurie nebuvo pažinę jokių Kanaano karų;'),
  (@b7, 3, 2, 'tik tam, kad Izraelio vaikų kartos žinotų, kad pamokytų juos kariauti, bent tuos, kurie anksčiau nieko apie tai nežinojo:'),
  (@b7, 3, 3, 'penki filistinų viešpačiai, visi kanaaniečiai, sidoniečiai ir hivai, gyvenantys Libano kalne nuo Baal-Hermono kalno iki Hamato įėjimo.'),
  (@b7, 3, 4, 'Ir jie buvo tam, kad jais išmėgintų Izraelį, kad sužinotų, ar jie klausys VIEŠPATIES įsakymų, kuriuos jis įsakė jų tėvams per Mozės ranką.'),
  (@b7, 3, 5, 'Ir Izraelio vaikai gyveno tarp kanaaniečių, hetitų, amoritų, perizų, hivų ir jebusiečių;'),
  (@b7, 3, 6, 'ir jie ėmė jų dukteris, kad būtų jų žmonomis, o savo dukteris davė jų sūnums ir tarnavo jų dievams.'),
  (@b7, 3, 7, 'Ir Izraelio vaikai darė pikta VIEŠPATIES akyse, pamiršo VIEŠPATĮ, savo Dievą, ir tarnavo Baalams ir giraitėms.'),
  (@b7, 3, 8, 'Todėl VIEŠPATIES pyktis užsidegė prieš Izraelį, ir jis juos pardavė į Mesopotamijos karaliaus Kušan-Rišataimo rankas; ir Izraelio vaikai tarnavo Kušan-Rišataimui aštuonerius metus.'),
  (@b7, 3, 9, 'O kai Izraelio vaikai šaukėsi VIEŠPATIES, VIEŠPATS prikėlė Izraelio vaikams gelbėtoją, kuris juos išgelbėjo – jaunesniojo Kalebo brolio Kenazo sūnų Otnielį.'),
  (@b7, 3, 10, 'Ir VIEŠPATIES Dvasia nužengė ant jo, ir jis teisė Izraelį, ir išėjo į karą; ir VIEŠPATS atidavė į jo ranką Mesopotamijos karalių Kušan-Rišataimą; ir jo ranka nugalėjo Kušan-Rišataimą.'),
  (@b7, 3, 11, 'Ir šalis keturiasdešimt metų ilsėjosi. Ir Kenazo sūnus Otnielis mirė.'),
  (@b7, 3, 12, 'Ir Izraelio vaikai vėl darė pikta VIEŠPATIES akyse; ir VIEŠPATS sustiprino Moabo karalių Egloną prieš Izraelį, nes jie darė pikta VIEŠPATIES akyse.'),
  (@b7, 3, 13, 'Ir jis surinko pas save Amono bei Amaleko vaikus ir nuėjęs sumušė Izraelį ir pasisavino Palmių miestą.'),
  (@b7, 3, 14, 'Taip Izraelio vaikai tarnavo Moabo karaliui Eglonui aštuoniolika metų.'),
  (@b7, 3, 15, 'Bet kai Izraelio vaikai šaukėsi VIEŠPATIES, VIEŠPATS jiems prikėlė gelbėtoją, Geros sūnų Ehudą, benjaminą, kairiarankį vyrą; ir Izraelio vaikai nusiuntė per jį dovaną Moabo karaliui Eglonui.'),
  (@b7, 3, 16, 'Bet Ehudas pasidarė uolekties ilgio dviašmenį durklą; ir užsijuosė jį po savo drabužiais ant dešinės šlaunies.'),
  (@b7, 3, 17, 'Ir jis atnešė dovaną Moabo karaliui Eglonui; o Eglonas buvo labai nutukęs vyras.'),
  (@b7, 3, 18, 'Ir kai jis buvo baigęs teikti dovaną, paleido žmones, nešusius dovaną.'),
  (@b7, 3, 19, 'Bet jis pats sugrįžo nuo karjerų, esančių prie Gilgalo, ir tarė: „Turiu slaptą pavedimą tau, o karaliau“; šis tarė: „Tylėk“. Ir išėjo nuo jo visi, kurie prie jo stovėjo.'),
  (@b7, 3, 20, 'Ir Ehudas atėjo pas jį; o šis sėdėjo vasaros kambaryje, kurį turėjo sau vienam. Ir Ehudas tarė: „Turiu tau žinią nuo Dievo“. Ir jis atsikėlė nuo kėdės.'),
  (@b7, 3, 21, 'O Ehudas ištiesė savo kairiąją ranką, paėmė durklą nuo savo dešinės šlaunies ir įsmeigė jį į jo pilvą;'),
  (@b7, 3, 22, 'taip pat ir rankena įlindo paskui ašmenis; ir taukai užsidarė ant ašmenų taip, kad jis negalėjo ištraukti durklo iš jo pilvo; ir nešvarumai išėjo.'),
  (@b7, 3, 23, 'Tada Ehudas išėjo per prieangį ir uždarė kambario duris už savęs, ir užrakino jas.'),
  (@b7, 3, 24, 'Jam išėjus, atėjo jo tarnai; ir pamatę, kad štai kambario durys buvo užrakintos, jie tarė: „Tikrai jis apdengė savo kojas savo vasaros kambaryje“.'),
  (@b7, 3, 25, 'Ir jie laukė, kol susigėdo; o štai jis neatidarė kambario durų; todėl paėmę raktą jie atrakino jas; ir štai jų viešpats buvo nugriuvęs ant žemės negyvas.'),
  (@b7, 3, 26, 'O Ehudas pabėgo, kol jie delsė, ir praėjo anapus karjerų, ir pabėgo į Seyrą.'),
  (@b7, 3, 27, 'Ir įvyko, kad atėjęs jis pūtė trimitą Efraimo kalne, ir Izraelio vaikai leidosi su juo nuo kalno, o jis pirma jų.'),
  (@b7, 3, 28, 'Ir jis jiems tarė: „Sekite paskui mane; nes VIEŠPATS atidavė į jūsų rankas jūsų priešus moabiečius“. Ir jie leidosi paskui jį ir paėmė Jordano brastas link Moabo, ir niekam neleido pereiti.'),
  (@b7, 3, 29, 'Ir tuo metu jie išžudė iš Moabo apie dešimt tūkstančių vyrų, visus smarkius ir narsius vyrus; ir nei vienas nepabėgo.'),
  (@b7, 3, 30, 'Taip tą dieną Moabas buvo pavergtas po Izraelio ranka. Ir šalis ilėjosi aštuoniasdešimt metų.'),
  (@b7, 3, 31, 'O po jo buvo Anato sūnus Šamgaras, kuris užmušė iš filistinų šešis šimtus vyrų jaučių badikliu; jis irgi išgelbėjo Izraelį.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b7, 4, 1, 'O Ehudui mirus, Izraelio vaikai vėl darė pikta VIEŠPATIES akyse.'),
  (@b7, 4, 2, 'Ir VIEŠPATS juos pardavė į rankas Jabino, Kanaano karaliaus, kuris karaliavo Hacore; jo kariuomenės vadas buvo Sisera, kuris gyveno pagonių Harošete.'),
  (@b7, 4, 3, 'Ir Izraelio vaikai šaukėsi VIEŠPATIES; nes jis turėjo devynis šimtus geležinių vežimų; ir dvidešimt metų jis galingai engė Izraelio vaikus.'),
  (@b7, 4, 4, 'Ir pranašė Debora, Lapidoto žmona, tuo metu teisė Izraelį.'),
  (@b7, 4, 5, 'Ir ji gyveno po Deboros palme tarp Ramos ir Bet-Elio, Efraimo kalne; o Izraelio vaikai eidavo pas ją aukštyn į teismą.'),
  (@b7, 4, 6, 'Ir pasiuntusi ji pasišaukė Abinoamo sūnų Baraką iš Kedeš-Naftalio ir jam tarė: „Argi VIEŠPATS, Izraelio Dievas, neįsakė, sakydamas: ‘Eik, trauk į Taboro kalną, ir paimk su savimi dešimt tūkstančių vyrų iš Naftalio vaikų ir iš Zebulono vaikų?'),
  (@b7, 4, 7, 'O aš atitrauksiu pas tave prie Kišono upės Jabino kariuomenės vadą Siserą su jo vežimais bei jo daugybe; ir jį atiduosiu į tavo rankas’“.'),
  (@b7, 4, 8, 'Ir Barakas jai tarė: „Jei eisi su manimi, tai ir aš eisiu; bet jei neisi su manimi, tai ir aš neisiu“.'),
  (@b7, 4, 9, 'O ji tarė: „Aš tikrai eisiu su tavimi; tačiau kelionė, į kurią leisiesi, nebus tavo garbei; nes į moters rankas VIEŠPATS parduos Siserą“. Ir Debora atsikėlė ir ėjo su Baraku į Kedešą.'),
  (@b7, 4, 10, 'Ir Barakas sušaukė Zebuloną ir Naftalį į Kedešą; ir jis pėsčias ėjo aukštyn su dešimčia tūkstančių vyrų; ir Debora ėjo su juo aukštyn.'),
  (@b7, 4, 11, 'Na, o kenitas Heberas, kuris buvo iš Mozės uošvio Hobabo vaikų, buvo atsiskyręs nuo kainitų ir pasistatęs savo palapinę prie Caanaimo lygumos, esančios šalia Kedešo.'),
  (@b7, 4, 12, 'Ir Siserai pranešė, kad Abinoamo sūnus Barakas užlipęs į Taboro kalną.'),
  (@b7, 4, 13, 'Ir Sisera surinko visus savo vežimus, tai yra devynis šimtus geležinių vežimų, ir visą su juo esančią tautą iš pagonių Harošeto iki Kišono upės.'),
  (@b7, 4, 14, 'Ir Debora tarė Barakui: „Kelkis; nes šita yra diena, kurioje VIEŠPATS atidavė Siserą į tavo rankas; argi ne VIEŠPATS yra išėjęs pirma tavęs?“ Taigi Barakas ėjo žemyn nuo Taboro kalno, ir dešimt tūkstančių vyrų jam iš paskos.'),
  (@b7, 4, 15, 'Ir VIEŠPATS sutrikdė Siserą, visus jo vežimus ir visą jo kariuomenę kalavijo ašmenimis Barako akivaizdoje; taip, kad Sisera, nulipęs nuo savo vežimo, pabėgo pėsčias.'),
  (@b7, 4, 16, 'Bet Barakas vijosi vežimus ir kariuomenę iki pagonių Harošeto; ir visa Siseros kariuomenė krito nuo kalavijo ašmenų; nei vieno neišliko.'),
  (@b7, 4, 17, 'Tačiau Sisera pėsčias pabėgo į kenito Hebero žmonos Jaelės palapinę; nes tarp Hacoro karaliaus Jabino ir kainito Hebero namų buvo taika.'),
  (@b7, 4, 18, 'Ir Jaelė išėjo pasitikti Siseros ir jam tarė: „Užsuk, mano viešpatie, užsuk pas mane; nebijok“. Ir jam užsukus pas ją į palapinę, ji apdengė jį dangalu.'),
  (@b7, 4, 19, 'Ir jis tarė jai: „Meldžiu tave, duok man truputį vandens atsigerti; nes esu ištroškęs“. Ir atidariusi pieno indą ji davė jam atsigerti ir jį apdengė.'),
  (@b7, 4, 20, 'Jis vėl jai tarė: „Atsistok palapinės duryse, ir tebus, jei kas ateitų ir tavęs paklaustų, sakydamas: ‘Ar čia yra kas nors?’, tai sakyk: ‘Ne’“.'),
  (@b7, 4, 21, 'Tada Hebero žmona Jaelė paėmė palapinės vinį, pasiėmė į ranką kūjį ir įėjo pas jį tylomis, ir įkalė jam į smilkinius vinį, ir prismeigė ją prie žemės; nes jis kietai miegojo ir buvo nuvargęs. Taip jis mirė.'),
  (@b7, 4, 22, 'O štai kai Barakas vijosi Siserą, Jaelė išėjo jo pasitikti ir tarė jam: „Ateik, parodysiu tau vyrą, kurio ieškai“. Ir, jam įėjus į jos palapinę, štai Sisera guli negyvas, ir vinis jo smilkiniuose.'),
  (@b7, 4, 23, 'Taip tą dieną Dievas pavergė Kanaano karalių Jabiną Izraelio vaikų akivaizdoje.'),
  (@b7, 4, 24, 'Ir Izraelio vaikų ranka klestėjo ir ėmė viršų prieš Kanaano karalių Jabiną, kol jie sunaikino Kanaano karalių Jabiną.'),
  (@b7, 5, 1, 'Tada giedojo Debora ir Abinoamo sūnus Barakas tą dieną, sakydami:'),
  (@b7, 5, 2, '„Girkite VIEŠPATĮ dėl atkeršijimo už Izraelį, kai tauta savanoriškai aukojosi.'),
  (@b7, 5, 3, 'Klausykite, o karaliai; palenkite ausį, o kunigaikščiai; aš, aš VIEŠPAČIUI giedosiu; aš giedosiu gyrių VIEŠPAČIUI, Izraelio Dievui.'),
  (@b7, 5, 4, 'VIEŠPATIE, kai tu išėjai iš Seyro, kai išžygiavai iš Edomo lauko, žemė drebėjo ir dangūs lašėjo, taip pat ir debesys lašino vandenį.'),
  (@b7, 5, 5, 'Kalnai tirpo nuo VIEŠPATIES akivaizdos, net tas Sinajus, nuo VIEŠPATIES, Izraelio Dievo, akivaizdos.'),
  (@b7, 5, 6, 'Anato sūnaus Šamgaro dienomis, Jaelės dienomis, vieškeliai buvo tušti, o keliautojai vaikščiojo aplinkiniais keliais.'),
  (@b7, 5, 7, 'Išnyko kaimų gyventojai, jie išnyko Izraelyje, kol aš, Debora, pakilau, pakilau aš – motina Izraelyje.'),
  (@b7, 5, 8, 'Jie pasirinko naujus dievus; tada karas buvo vartuose; ar matėsi skydas, ar ietis tarp keturiasdešimties tūkstančių Izraelyje?'),
  (@b7, 5, 9, 'Mano širdis palinkusi link Izraelio valdytojų, kurie savanoriškai aukojosi tautos tarpe. Girkite VIEŠPATĮ.'),
  (@b7, 5, 10, 'Kalbėkite jūs, kurie jojate ant baltų asilų, kurie sėdite teisme ir einate keliu.'),
  (@b7, 5, 11, 'Išgelbėtieji iš lankininkų garsų vandens sėmimo vietose, ten jie atpasakos VIEŠPATIES teisius darbus – teisius darbus jo kaimų gyventojams Izraelyje; tada VIEŠPATIES tauta eis žemyn prie vartų.'),
  (@b7, 5, 12, 'Pabusk, pabusk, Debora; pabusk, pabusk, tark giesmę; kelkis, Barake, ir vesk nelaisvėn savo nelaisvę, Abinoamo sūnau.'),
  (@b7, 5, 13, 'Tada tam, kuris išliko, jis davė valdyti kilminguosius tautos tarpe; VIEŠPATS davė man valdyti galinguosius.'),
  (@b7, 5, 14, 'Iš Efraimo buvo šaknis tų prieš Amaleką; po tavęs, Benjaminai, tavo tautos tarpe; iš Machyro atėjo žemyn valdytojai, o iš Zebulono tie, kurie valdo rašytojo plunksną.'),
  (@b7, 5, 15, 'O Isacharo kunigaikščiai buvo su Debora; Isacharas ir taip pat Barakas; jis buvo pasiųstas į slėnį pėsčias. Rubeno pasidalijimams buvo dideli širdies apmąstymai.'),
  (@b7, 5, 16, 'Kodėl pasilikai tarp avių gardų, klausytis kaimenių bliovimų? Rubeno pasidalijimams buvo dideli širdies ištyrimai.'),
  (@b7, 5, 17, 'Gileadas apsigyveno anapus Jordano; o kodėl Danas pasiliko laivuose? Ašeras liko ant jūros kranto ir apsigyveno savo spragose.'),
  (@b7, 5, 18, 'Zebulonas ir Naftalis buvo tauta, kuri statė į pavojų savo gyvybes iki mirties lauko aukštumose.'),
  (@b7, 5, 19, 'Atėję karaliai kariavo, tada kariavo Kanaano karaliai Taanache prie Megido vandenų; jie neėmė pinigų pelno.'),
  (@b7, 5, 20, 'Jie kariavo iš dangaus; žvaigždės iš savo takų kariavo prieš Siserą.'),
  (@b7, 5, 21, 'Kišono upė juos nušlavė, ta senovės upė, Kišono upė. O mano siela, tu sutrypei stiprybę.'),
  (@b7, 5, 22, 'Tada žirgų kanopos sutrupėjo dėl šuoliavimų, dėl šuoliavimų jų galingųjų.'),
  (@b7, 5, 23, 'Prakeikite Merozą, – tarė VIEŠPATIES angelas, – smarkiai keikite jos gyventojus; nes jie neatėjo į VIEŠPATIES pagalbą, į VIEŠPATIES pagalbą prieš galinguosius.'),
  (@b7, 5, 24, 'Kenito Hebero žmona Jaelė bus labiau palaiminta už moteris, palaiminta ji bus palapinėje labiau už moteris.'),
  (@b7, 5, 25, 'Vandens jis prašė, o ji pieno jam davė; ji išnešė sviesto viešpatiškoje lėkštėje.'),
  (@b7, 5, 26, 'Savo ranką ji ištiesė į vinį, o savo dešinę ranką į darbininkų kūjį; ir kūju ji trenkė Siserai, sudaužė jo galvą, perdūrusi ir perkirtusi jo smilkinius.'),
  (@b7, 5, 27, 'Prie jos kojų jis palinko, pargriuvo, gulėjo; prie jos kojų jis palinko, pargriuvo; kur jis palinko, ten pargriuvo negyvas.'),
  (@b7, 5, 28, 'Pro langą žiūrėjo Siseros motina, verkė pro lango groteles: ‘Kodėl taip ilgai neparvažiuoja jo vežimas? Kodėl užtrunka jo vežimų ratai?’'),
  (@b7, 5, 29, 'Jos išmintingosios ponios jai atsakė, taip, ir ji pati sau atsakinėjo:'),
  (@b7, 5, 30, '‘Argi jie nerado, argi jie nedalijo grobio: po vieną ar po dvi paneles kiekvienam vyrui? Margaspalvis grobis Siserai, margaspalvio siuvinio grobis, abipusis margaspalvis siuvinys, tinkantis grobėjų kaklui’.'),
  (@b7, 5, 31, 'Taip tepražūna visi tavo priešai, o VIEŠPATIE; bet jį mylintieji tebūna kaip saulė, patekanti savo galybėje“. Ir šalis keturiasdešimt metų ilsėjosi.'),
  (@b7, 6, 1, 'Ir Izraelio vaikai darė pikta VIEŠPATIES akyse; ir VIEŠPATS juos padavė septyneriems metams į Midjano ranką.'),
  (@b7, 6, 2, 'Ir Midjano ranka įsigalėjo prieš Izraelį; dėl midjaniečių Izraelio vaikai pasidarė urvų, esančių kalnuose, olų ir tvirtovių.'),
  (@b7, 6, 3, 'Ir taip būdavo – kai Izraelis pasėdavo, atkildavo midjaniečiai, amalekiečiai ir rytų vaikai, jie atkildavo prieš juos;'),
  (@b7, 6, 4, 'ir jie prieš juos stovyklaudavo, sunaikindavo žemės prieaugį, kur ateinama iki Gazos, ir nepalikdavo pragyvenimo Izraeliui: nei avies, nei jaučio, nei asilo.'),
  (@b7, 6, 5, 'Nes jie atkildavo su savo galvijais ir savo palapinėmis ir ateidavo tokia daugybe, kaip žiogai; nes nei jie, nei jų kupranugariai nesuskaičiuojami; ir jie įeidavo į šalį, kad ją sunaikintų.'),
  (@b7, 6, 6, 'Ir Izraelis labai nuskurdo dėl midjaniečių; ir Izraelio vaikai šaukėsi VIEŠPATIES.'),
  (@b7, 6, 7, 'Ir įvyko, kai Izraelio vaikai šaukėsi VIEŠPATIES dėl midjaniečių,'),
  (@b7, 6, 8, 'VIEŠPATS atsiuntė Izraelio vaikams pranašą, kuris jiems tarė: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Aš vedžiau jus aukštyn iš Egipto ir išvedžiau jus iš vergovės namų;'),
  (@b7, 6, 9, 'ir išvadavau jus iš egiptiečių rankos ir iš visų jūsų engėjų rankos, ir išvariau juos iš jūsų akivaizdos, ir daviau jums jų šalį;'),
  (@b7, 6, 10, 'ir pasakiau jums: ‘Aš esu VIEŠPATS, jūsų Dievas; nebijokite dievų amoritų, kurių šalyje jūs gyvenate’; bet jūs nepaklusote mano balsui“.'),
  (@b7, 6, 11, 'Ir atėjo VIEŠPATIES angelas ir atsisėdo po Ofroje esančiu ąžuolu, priklausančiu abiezeriui Joašui; o jo sūnus Gideonas kūlė kviečius prie vyno spaustuvo, kad juos paslėptų nuo midjaniečių.'),
  (@b7, 6, 12, 'Ir jam pasirodė VIEŠPATIES angelas ir tarė jam: „VIEŠPATS yra su tavimi, galingas narsuoli“.'),
  (@b7, 6, 13, 'O Gideonas jam tarė: „O, mano Viešpatie, jei VIEŠPATS yra su mumis, tai kodėl mums visa tai atsitiko? Ir kur yra visi jo stebuklai, apie kuriuos mums pasakojo mūsų tėvai, sakydami: ‘Argi ne VIEŠPATS mus išvedė aukštyn iš Egipto? Bet dabar VIEŠPATS yra mus palikęs ir atidavęs į midjaniečių rankas“.'),
  (@b7, 6, 14, 'O VIEŠPATS pažiūrėjo į jį ir tarė: „Eik su šita savo galia ir išgelbėk Izraelį iš midjaniečių rankos; ar aš tavęs nesiunčiu?“'),
  (@b7, 6, 15, 'O jis jam tarė: O, mano Viešpatie, kuo aš išgelbėsiu Izraelį? Štai mano šeima yra neturtinga Manase, o aš esu mažiausias savo tėvo namuose“.'),
  (@b7, 6, 16, 'O VIEŠPATS jam tarė: „Tikrai aš būsiu su tavimi, ir tu sumuši midjaniečius kaip vieną vyrą“.'),
  (@b7, 6, 17, 'O jis jam tarė: „Jei dabar radau malonę tavo akyse, tai parodyk man ženklą, kad tu kalbi su manimi.'),
  (@b7, 6, 18, 'Meldžiu tave, nesitrauk iš čia, kol ateisiu pas tave ir išnešiu savo dovaną, ir padėsiu ją prieš tave“. Ir jis tarė: „Aš pasiliksiu, kol sugrįši“.'),
  (@b7, 6, 19, 'Ir Gideonas įėjęs paruošė ožiuką ir neraugintų pyragų iš efos miltų; mėsą sudėjo į pintinę, o sultinį supylė į puodą ir išnešė tai pas jį po ąžuolu ir pateikė.'),
  (@b7, 6, 20, 'Ir Dievo angelas jam tarė: „Paimk mėsą bei neraugintus pyragus ir padėk juos ant šitos uolos, o sultinį išpilk“. Ir jis taip padarė.'),
  (@b7, 6, 21, 'Tada VIEŠPATIES angelas ištiesė galą lazdos, esančios jo rankoje, ir palietė mėsą bei neraugintus pyragus; ir ugnis iškilo iš uolos ir surijo mėsą bei neraugintus pyragus. Tada VIEŠPATIES angelas pasitraukė jam iš akių.'),
  (@b7, 6, 22, 'Ir kai Gideonas suprato, kad tas buvo VIEŠPATIES angelas, Gideonas tarė: „Vargas, o Viešpatie DIEVE! Kadangi mačiau VIEŠPATIES angelą veidas į veidą“.'),
  (@b7, 6, 23, 'O VIEŠPATS jam tarė: „Tebūna ramybė tau; nebijok; nemirsi“.'),
  (@b7, 6, 24, 'Tada Gideonas ten pastatė aukurą VIEŠPAČIUI ir jį praminė „Jehova-Šalom“; iki šios dienos jis tebėra abiezerių Ofroje.'),
  (@b7, 6, 25, 'Ir įvyko tą pačią naktį, kad VIEŠPATS jam tarė: „Paimk savo tėvo jauniklį jautuką, antrąjį jautuką septynių metų ir nugriauk Baalo aukurą, kurį turi tavo tėvas, ir nukirsk prie jo esančią giraitę;'),
  (@b7, 6, 26, 'ir pastatyk aukurą VIEŠPAČIUI, savo Dievui, ant šios uolos viršūnės, sutvarkytoje vietoje, ir paėmęs antrąjį jautį, atnašauk deginamąją auką su malkomis giraitės, kurią nukirsi“.'),
  (@b7, 6, 27, 'Tada Gideonas paėmė dešimt vyrų iš savo tarnų ir padarė, kaip VIEŠPATS jam buvo pasakęs; ir buvo, kadangi jis bijojo savo tėvo namiškių bei miesto žmonių, tai jis negalėjo to padaryti dieną, tad jis padarė tai naktį.'),
  (@b7, 6, 28, 'O kai to miesto žmonės atsikėlė anksti ryte, štai Baalo aukuras buvo nugriautas, o prie jo esanti giraitė iškirsta, ir antrasis jautis buvo paaukotas ant pastatyto aukuro“.'),
  (@b7, 6, 29, 'Ir jie sakė vienas kitam: „Kas tai padarė?“ Ir ištyrę ir išklausinėję, jie sakė: „Joašo sūnus Gideonas tai padarė“.'),
  (@b7, 6, 30, 'Tada to miesto žmonės tarė Joašui: „Išvesk savo sūnų, idant jis mirtų; kadangi jis nugriovė Baalo aukurą ir kadangi iškirto prie jo esančią giraitę“.'),
  (@b7, 6, 31, 'O Joašas tarė visiems, kurie stovėjo prieš jį: „Ar norite ginti Baalą? Ar norite jį išgelbėti? Kas nori jį ginti, tas tebūna užmuštas, kol dar yra rytas; jei jis yra dievas, tegul gina save dėl to, kad nugriovė jo aukurą“.'),
  (@b7, 6, 32, 'Todėl tą dieną jis praminė jį Jerubaalu, sakydamas: „Tegul Baalas bylinėjasi su juo“, nes jis nugriovė jo aukurą.'),
  (@b7, 6, 33, 'Tada visi midjaniečiai, amalekiečiai ir rytų vaikai susirinko, perėjo ir stovyklavo Jezreelio slėnyje.'),
  (@b7, 6, 34, 'Bet VIEŠPATIES Dvasia atėjo ant Gideono, ir jis pūtė trimitą; ir Abi-Ezeras susirinko paskui jį.'),
  (@b7, 6, 35, 'Ir jis išsiuntė pasiuntinius po visą Manasą; kuris irgi buvo susirinkęs paskui jį; ir jis išsiuntė pasiuntinius į Ašerą, į Zebuloną ir į Naftalį; ir jie atėjo aukštyn jų pasitikti.'),
  (@b7, 6, 36, 'Ir Gideonas tarė Dievui: „Jei mano ranka išgelbėsi Izraelį, kaip esi pasakęs,'),
  (@b7, 6, 37, 'štai aš padėsiu vilnos kirpinį klojime; jei rasa bus vien tik ant kirpinio, o ant visos žemės šalimais bus sausa, tada aš žinosiu, kad tu išgelbėsi Izraelį mano ranka, kaip esi pasakęs“.'),
  (@b7, 6, 38, 'Ir taip buvo; nes rytojaus dieną anksti atsikėlęs, jis sugniaužė kirpinį ir išgręžė rasą iš kirpinio – pilną dubenį vandens.'),
  (@b7, 6, 39, 'Ir Gideonas tarė Dievui: „Teneužsidega tavo pyktis prieš mane, ir aš dar tik vieną kartą prabilsiu; leisk man, meldžiu tave, dar tik vieną kartą išmėginti su kirpiniu; dabar tebūna sausa vien tik ant kirpinio, o ant visos žemės tebūna rasa“.'),
  (@b7, 6, 40, 'Ir Dievas tą naktį taip padarė, nes sausa buvo vien tik ant kirpinio, o ant visos žemės buvo rasa.'),
  (@b7, 7, 1, 'Tada Jerubaalas, kuris yra Gideonas, ir visa su juo esanti tauta, atsikėlė anksti ir stovyklavo šalia Harodo šaltinio; kad midjaniečių kariuomenė buvo šiaurinėje jų pusėje, šalia Morės kalvos, slėnyje.'),
  (@b7, 7, 2, 'Ir VIEŠPATS tarė Gideonui: „Man yra per daug su tavimi esančios liaudies, kad duočiau midjaniečius į jų rankas, idant Izraelis nesigirtų prieš mane, sakydamas: ‘Mano paties ranka išgelbėjo mane’.'),
  (@b7, 7, 3, 'Taigi dabar eik, skelbk tautai į ausis, sakydamas: ‘Kas yra baugštus ir bijo, tegul grįžta ir anksti išeina nuo Gileado kalno“. Ir sugrįžo dvidešimt du tūkstančiai iš tautos; o dešimt tūkstančių pasiliko.'),
  (@b7, 7, 4, 'Ir VIEŠPATS tarė Gideonui: „Dar per daug liaudies; nuvesk juos žemyn prie vandens ir ten juos tau išmėginsiu; ir bus, apie kurį tau pasakysiu: ‘Šitas eis su tavimi’, tuomet tas eis su tavimi; o apie kurį tau pasakysiu: ‘Šitas neis su tavimi’, tas neis“.'),
  (@b7, 7, 5, 'Taigi jis nuvedė žemyn tautą prie vandens; ir VIEŠPATS tarė Gideonui: „Kiekvieną, kuris laks vandenį liežuviu, kaip šuo laka, pastatyk atskirai; panašiai kiekvieną, kuris klaupsis ant kelių gerti“.'),
  (@b7, 7, 6, 'Ir skaičius tų, kurie lakė pridėdami ranką prie savo burnos, buvo trys šimtai vyrų; bet visi likusieji iš tautos atsiklaupė ant kelių vandens gerti.'),
  (@b7, 7, 7, 'Ir VIEŠPATS tarė Gideonui: „Tais trimis šimtais vyrų, kurie lakė, jus išgelbėsiu ir atiduosiu midjaniečius į tavo ranką; o visi kiti iš tautos tegul kiekvienas eina į savo vietą“.'),
  (@b7, 7, 8, 'Taigi tauta pasiėmė maisto į rankas ir savo trimitus; ir jis paleido visą likusį Izraelį, kiekvieną į savo palapinę, o tuos tris šimtus vyrų palaikė; o Midjano kariuomenė buvo jo apačioje, slėnyje.'),
  (@b7, 7, 9, 'Ir įvyko tą pačią naktį, kad VIEŠPATS jam tarė: „Kelkis, leiskis link kariuomenės; nes aš ją atidaviau į tavo ranką.'),
  (@b7, 7, 10, 'Bet jei bijai eiti žemyn, eik žemyn į kariuomenę su savo tarnu Pura;'),
  (@b7, 7, 11, 'ir išgirsi, ką jie kalba; o po to bus sustiprintos tavo rankos, kad eitum žemyn į kariuomenę“. Tada jis nuėjo žemyn su savo tarnu Pura prie išorinės pusės ginkluotųjų vyrų, esančių kariuomenėje.'),
  (@b7, 7, 12, 'Midjaniečiai, amalekiečiai ir visi rytų vaikai gulėjo slėnyje, tokia daugybė, kaip žiogų; o jų kupranugarių buvo be skaičiaus, tokia daugybė, kaip smėlio jūros pakrantėje.'),
  (@b7, 7, 13, 'Ir kai Gideonas atėjo, štai buvo vyras, kuris pasakojo savo draugui sapną, sakydamas: „Štai aš sapnavau sapną, ir štai miežinės duonos pyragas atriedėjo į Midjano kariuomenę, pasiekė palapinę ir į ją trenkė, kad ji nugriuvo, ir ją apvertė, kad palapinė gulėjo“.'),
  (@b7, 7, 14, 'O jo draugas atsakė ir tarė: „Tai ne kas kita, kaip Joašo sūnaus Gideono, Izraelio vyro, kalavijas; nes Dievas atidavė į jo ranką Midjaną ir visą kariuomenę“.'),
  (@b7, 7, 15, 'Ir buvo, kai Gideonas išgirdo to sapno pasakojimą ir jo aiškinimą, jis pagarbino ir sugrįžo į Izraelio kariuomenę, ir tarė: „Kelkitės; nes VIEŠPATS atidavė į jūsų ranką Midjano kariuomenę“.'),
  (@b7, 7, 16, 'Ir jis padalijo tris šimtus vyrų į tris būrius ir įdavė kiekvienam vyrui į rankas trimitą ir tuščius ąsočius su žibintais ąsočių viduje.'),
  (@b7, 7, 17, 'Ir jis jiems tarė: „Žiūrėkite į mane ir taip pat darykite; ir štai, kai aš ateisiu prie stovyklos išorinės pusės, tada bus – kaip aš darysiu, taip ir jūs darykite.'),
  (@b7, 7, 18, 'Kai pūsiu trimitu aš ir visi su manimi esantys, tuomet ir jūs pūskite trimitus iš visų visos stovyklos pusių ir sakykite: ‘Kalavijas VIEŠPATIES ir Gideono’“.'),
  (@b7, 7, 19, 'Taip Gideonas ir šimtas su juo esančių vyrų atėjo prie stovyklos išorinės pusės, prasidedant vidurinei nakties sargybai; o jie ką tik buvo pastatę sargybą; ir jie pūtė trimitus ir daužė ąsočius, esančius jų rankose.'),
  (@b7, 7, 20, 'Ir tie trys būriai pūtė trimitus bei daužė ąsočius, ir kairiąja ranka jie laikė žibintus, o dešiniąja ranka trimitus, kad jais pūstų; ir jie šaukė: „Kalavijas VIEŠPATIES ir Gideono“.'),
  (@b7, 7, 21, 'Ir jie kiekvienas stovėjo savo vietoje aplink stovyklą, o visa kariuomenė lakstė, šaukė ir bėgo.'),
  (@b7, 7, 22, 'O tie trys šimtai pūtė trimitus, ir VIEŠPATS atkreipė kalaviją vieno prieš kitą visoje kariuomenėje; ir kariuomenė bėgo į Bet-Šitą Cerere, iki Abel-Meholos ribos, iki Tabato.'),
  (@b7, 7, 23, 'Ir Izraelio vyrai susirinko iš Naftalio, iš Ašero ir iš viso Manaso ir vijosi midjaniečius.'),
  (@b7, 7, 24, 'Ir Gideonas išsiuntė pasiuntinius po visą Efraimo kalną, sakydamas: „Ateikite žemyn prieš midjaniečius ir paimkite jų priešakyje vandenis iki Bet-Baros bei Jordano“. Tada susirinko visi Efraimo vyrai ir paėmė vandenis iki Bet-Baros bei Jordano.'),
  (@b7, 7, 25, 'Ir jie paėmė du midjaniečių kunigaikščius: Orebą ir Zeebą; ir jie užmušė Orebą ant Orebo uolos, o Zeebą užmušė Zeebo vyno spaudykloje, ir vijosi Midjaną, ir nunešė Orebo ir Zeebo galvas Gideonui anapus Jordano.'),
  (@b7, 8, 1, 'Ir Efraimo vyrai jam tarė: „Kodėl taip padarei mums, kad nepasikvietei mūsų, kai ėjai kovoti su midjaniečiais?“ Ir jie smarkiai su juo susibarė.'),
  (@b7, 8, 2, 'O jis jiems tarė: „Ką dabar padariau lyginant su jumis? Argi Efraimo likusiųjų vynuogių parankos nėra geresnės už Abi-Ezero vynuogių derlių?'),
  (@b7, 8, 3, 'Į jūsų rankas Dievas atidavė Midjano kunigaikščius Orebą ir Zeebą; o ką aš pajėgiau padaryti lyginant su jumis?“ Tai jam pasakius, atsileido jų pyktis jam.'),
  (@b7, 8, 4, 'Ir Gideonas atėjo prie Jordano ir perėjo, jis ir trys šimtai su juo esančių vyrų, nusilpę, dar besivydami juos.'),
  (@b7, 8, 5, 'Ir jis tarė Sukoto žmonėms: „Duokite, meldžiu jus, duonos kepalų tautai, sekančiai paskui mane; nes jie yra nusilpę, o aš vejuosi Zebachą ir Calmuną, Midjano karalius“.'),
  (@b7, 8, 6, 'O Sukoto kunigaikščiai tarė: „Ar Zebacho ir Calmunos rankos jau yra tavo rankoje, kad turėtume duoti duonos tavo kariuomenei?“'),
  (@b7, 8, 7, 'Ir Gideonas tarė: „Taigi, kai VIEŠPATS bus atidavęs Zebachą ir Calmuną į mano ranką, tada aš draskysiu jūsų kūną dykumos dygliais ir erškėčiais“.'),
  (@b7, 8, 8, 'Ir jis iš ten ėjo aukštyn į Penuelį ir jiems panašiai kalbėjo; o Penuelio žmonės jam atsakė taip, kaip buvo atsakę Sukoto žmonės.'),
  (@b7, 8, 9, 'O jis tarė ir Penuelio žmonėms, sakydamas: „Kai sugrįšiu ramybėje, aš nugriausiu šitą bokštą“.'),
  (@b7, 8, 10, 'Na, o Zebachas ir Calmuna buvo Karkore, ir jų kariuomenės su jais, apie penkiolika tūkstančių vyrų, visi išlikusieji iš visų rytų vaikų kariuomenių; nes krito šimtas dvidešimt tūkstančių vyrų, išsitraukiančių kalaviją.'),
  (@b7, 8, 11, 'Ir Gideonas ėjo aukštyn keliu tų, kurie gyveno palapinėse, Nobacho ir Jogbehos rytuose, ir smogė kariuomenei; nes kariuomenė buvo saugi.'),
  (@b7, 8, 12, 'O kai Zebachas ir Calmuna pabėgo, jis vijosi juos ir sugavo abu Midjano karalius, Zebachą ir Calmuną, ir sutrikdė visą kariuomenę.'),
  (@b7, 8, 13, 'Ir Joašo sūnus Gideonas grįžo iš mūšio prieš patekant saulei,'),
  (@b7, 8, 14, 'ir pagavo jaunuolį iš Sukoto žmonių, ir jį išklausinėjo; ir jis jam surašė Sukoto kunigaikščius ir jo vyresniuosius – septyniasdešimt septynis vyrus.'),
  (@b7, 8, 15, 'Ir atėjęs pas Sukoto žmones, jis tarė: „Štai Zebachas ir Calmuna, dėl kurių prikaišiojote man, sakydami: ‘Ar Zebacho ir Calmunos rankos jau tavo rankoje, kad turėtume duoti duonos tavo nusilpusiems vyrams?’'),
  (@b7, 8, 16, 'Ir jis paėmė miesto vyresniuosius ir dykumos dyglių bei erškėčių ir jais pamokė Sukoto žmones.'),
  (@b7, 8, 17, 'Ir jis nugriovė Penuelio bokštą ir išžudė miesto žmones.'),
  (@b7, 8, 18, 'Paskui jis tarė Zebachui ir Calmunai: „Kokie tai buvo vyrai, kuriuos užmušėte Tabore?“ O jie atsakė: „Koks tu esi, tokie jie buvo; kiekvienas atrodė kaip karaliaus vaikai“.'),
  (@b7, 8, 19, 'Ir jis tarė: „Jie buvo mano broliai, tai yra mano motinos sūnūs; kaip gyvas VIEŠPATS, jei būtumėte palikę juos gyvus, neužmuščiau jūsų“.'),
  (@b7, 8, 20, 'Ir jis tarė savo pirmagimiui Jeteriui: „Kelkis, užmušk juos“. Bet jaunuolis neišsitraukė savo kalavijo; nes bijojo, kadangi jis dar buvo jaunuolis.'),
  (@b7, 8, 21, 'Tada Zebachas ir Calmuna tarė: „Kelkis tu pats ir pulk mus; nes koks vyras, tokia ir jo jėga“. Ir pakilęs Gideonas užmušė Zebachą bei Calmuną ir paėmė papuošalus, buvusius ant jų kupranugarių kaklų.'),
  (@b7, 8, 22, 'Paskui Izraelio žmonės sakė Gideonui: „Viešpatauk mums, tu ir tavo sūnus, ir taip pat tavo sūnaus sūnus; nes tu išvadavai mus iš Midjano rankos“.'),
  (@b7, 8, 23, 'O Gideonas jiems tarė: „Aš neviešpatausiu jums, nei mano sūnus neviešpataus jums: VIEŠPATS jums viešpataus“.'),
  (@b7, 8, 24, 'Ir Gideonas jiems tarė: „Norėčiau prašyti iš jūsų, kad duotumėte man kiekvienas iš savo grobio auskarus“ (nes jie turėjo auksinius auskarus, kadangi jie buvo išmaeliai).'),
  (@b7, 8, 25, 'Ir jie atsakė: „Mielai duosime“. Ir patiesę drabužį, jie sumetė ant jo kiekvienas savo grobio auskarus.'),
  (@b7, 8, 26, 'O svoris auksinių auskarų, kurių jis prašė, buvo tūkstantis septyni šimtai šekelių aukso; neskaitant papuošalų, karolių ir purpurinių drabužių, buvusių ant Midjano karalių, ir neskaitant grandinėlių, buvusių aplink jų kupranugarių kaklus.'),
  (@b7, 8, 27, 'Ir iš jo Gideonas padarė efodą ir jį padėjo savo mieste, tai yra Ofroje; ir visas Izraelis ten ėjo paleistuvaudami paskui tą; tai tapo žabangomis Gideonui ir jo namams.'),
  (@b7, 8, 28, 'Taip Midjanas buvo pavergtas Izraelio vaikų akivaizdoje, kad net nebepakėlė savo galvos. Ir keturiasdešimt metų šalyje buvo ramybė Gideono dienomis.'),
  (@b7, 8, 29, 'Ir Joašo sūnus Jerubaalas nuėjo ir gyveno savo namuose.'),
  (@b7, 8, 30, 'O Gideonas turėjo septyniasdešimt sūnų, iš jo kūno pagimdytų; nes jis turėjo daug žmonų.'),
  (@b7, 8, 31, 'Ir jo sugulovė, kuri buvo Šecheme, jam taip pat pagimdė sūnų, kurį jis pavadino vardu Abimelechas.'),
  (@b7, 8, 32, 'Ir Joašo sūnus Gideonas mirė geroje senatvėje ir buvo palaidotas savo tėvo Joašo kape abiezerių Ofroje.'),
  (@b7, 8, 33, 'Ir įvyko, kai tik Gideonas buvo miręs, Izraelio vaikai gręžėsi atgal ir nuėjo paleistuvaudami paskui Baalus ir padarė Baal-Beritą savo dievu.'),
  (@b7, 8, 34, 'Ir Izraelio vaikai neatsiminė VIEŠPATIES, savo Dievo, kuris buvo juos išvadavęs iš visų jų aplinkinių priešų rankų;'),
  (@b7, 8, 35, 'ir jie neparodė gerumo namams Jerubaalo, tai yra Gideono, dėl viso to gero, kurį jis buvo parodęs Izraeliui.'),
  (@b7, 9, 1, 'O Jerubaalo sūnus Abimelechas, nuėjęs į Šechemą pas savo motinos brolius, kalbėjo su jais ir su visa savo motinos tėvo namų šeima, sakydamas:'),
  (@b7, 9, 2, '„Kalbėkite, meldžiu jus, visiems Šechemo žmonėms į ausis: ‘Kas jums geriau: ar kad jums viešpatautų visi Jerubaalo sūnūs, septyniasdešimt asmenų, ar kad jums viešpatautų vienas?’ Taip pat atsiminkite, kad aš esu jūsų kaulas ir kūnas“.'),
  (@b7, 9, 3, 'Ir jo motinos broliai kalbėjo apie jį visus šituos žodžius visiems Šechemo žmonėms į ausis; ir jų širdys palinko sekti paskui Abimelechą; nes jie sakė: „Jis yra mūsų brolis“.'),
  (@b7, 9, 4, 'Ir jie davė jam iš Baal-Berito namų septyniasdešimt sidabrinių, kuriais Abimelechas pasisamdė niekingų ir pasileidusių asmenų, kurie sekė paskui jį.'),
  (@b7, 9, 5, 'Ir atėjęs į savo tėvo namus Ofroje, jis nužudė savo brolius, Jerubaalo sūnus, septyniasdešimt asmenų, ant vieno akmens; tačiau dar išliko Jerubaalo jauniausiasis sūnus Jotamas; nes jis pasislėpė.'),
  (@b7, 9, 6, 'Ir susirinko visi Šechemo žmonės ir visi Milo namai ir nuėję paskyrė Abimelechą karaliumi prie stulpo, esančio Šecheme, lygumos.'),
  (@b7, 9, 7, 'Ir kai jie tai pasakė Jotamui, jis nuėjo ir atsistojo Gerizimo kalno viršūnėje, ir pakeltu balsu šaukdamas jiems tarė: „Klausykite manęs, Šechemo žmonės, kad Dievas jūsų klausytųsi.'),
  (@b7, 9, 8, 'Vieną kartą medžiai išėjo patepti sau karaliaus; ir jie sakė alyvmedžiui: ‘Karaliauk mums’.'),
  (@b7, 9, 9, 'Bet alyvmedis jiems tarė: ‘Argi turėčiau palikti savo riebumą, kuriuo per mane pagerbia Dievą ir žmogų, ir eiti ir būti paaukštintu viršum medžių?’'),
  (@b7, 9, 10, 'Ir medžiai tarė figmedžiui: ‘Eikš, karaliauk mums’.'),
  (@b7, 9, 11, 'Bet figmedis jiems tarė: ‘Argi turėčiau palikti savo saldumą, savo geruosius vaisius, ir eiti ir būti paaukštintu viršum medžių?’'),
  (@b7, 9, 12, 'Tada medžiai tarė vynmedžiui: ‘Eikš, karaliauk mums’.'),
  (@b7, 9, 13, 'O vynmedis jiems tarė: ‘Argi turėčiau palikti savo vyną, linksminantį Dievą ir žmogų, ir eiti ir būti paaukštintu viršum medžių?’'),
  (@b7, 9, 14, 'Tada visi medžiai tarė gervuogei: ‘Eikš, karaliauk mums’.'),
  (@b7, 9, 15, 'O gervuogė tarė medžiams: ‘Jei iš tiesų patepate mane sau karaliumi, tuomet ateikite, pasitikėkite mano šešėliu; o jei ne, tegul išeina ugnis iš gervuogės ir tesuryja Libano kedrus’.'),
  (@b7, 9, 16, 'Taigi dabar, jei padarėte teisingai ir nuoširdžiai, paskirdami Abimelechą karaliumi, ir jei gerai pasielgėte su Jerubaalu bei jo namais, ir jei jam padarėte pagal tai, kaip jo rankos nusipelnė'),
  (@b7, 9, 17, '(nes mano tėvas kovojo už jus, rizikavo savo gyvybe ir išvadavo jus iš Midjano rankos;'),
  (@b7, 9, 18, 'o jūs šią dieną sukilote prieš mano tėvo namus ir nužudėte jo sūnus, septyniasdešimt asmenų, ant vieno akmens, ir padarėte jo tarnaitės sūnų Abimelechą Šechemo žmonių karaliumi dėl to, kad jis yra jūsų brolis);'),
  (@b7, 9, 19, 'tad jei šią dieną teisingai ir nuoširdžiai pasielgėte su Jerubaalu bei jo namais, tai džiaukitės Abimelechu, ir taip pat jis tesidžiaugia jumis;'),
  (@b7, 9, 20, 'bet jei ne, tuomet ugnis teišeina iš Abimelecho ir suryja Šechemo žmones bei Milo namus; ir teišeina ugnis iš Šechemo žmonių bei Milo namų ir suryja Abimelechą“.'),
  (@b7, 9, 21, 'Ir išbėgo Jotamas ir pabėgo, ir nuėjo į Beerą bei ten apsigyveno dėl savo brolio Abimelecho baimės.'),
  (@b7, 9, 22, 'Kai Abimelechas buvo valdęs Izraelį trejus metus,'),
  (@b7, 9, 23, 'Dievas siuntė piktą dvasią tarp Abimelecho ir Šechemo žmonių; ir Šechemo žmonės ėmė klastingai elgtis su Abimelechu;'),
  (@b7, 9, 24, 'kad žiaurumas, atliktas septyniasdešimčiai Jerubaalo sūnų, ateitų, ir jų kraujas būtų uždėtas ant jų brolio Abimelecho, kuris juos nužudė; ir ant Šechemo žmonių, kurie padėjo jam išžudyti jo brolius.'),
  (@b7, 9, 25, 'Ir Šechemo žmonės pastatė prieš jį kalnų viršūnėse tykotojų, ir jie apiplėšdavo visus, kurie praeidavo pro juos tuo keliu; ir tai buvo pranešta Abimelechui.'),
  (@b7, 9, 26, 'Ir atėjo Ebedo sūnus Gaalas su savo broliais ir perėjo į Šechemą; o Šechemo žmonės pasitikėjo juo.'),
  (@b7, 9, 27, 'Ir jie išėjo į laukus, nurinko savo vynuogynus ir sumindę vynuogių linksminosi, ir iėję į savo dievo namus valgė, gėrė ir keikė Abimelechą.'),
  (@b7, 9, 28, 'O Ebedo sūnus Gaalas sakė: „Kas yra Abimelechas ir kas yra Šechemas, kad turėtume jam tarnauti? Ar jis ne Jerubaalo sūnus ir ar ne Zebulas jo pareigūnas? Tarnaukite Šechemo tėvo Hamoro žmonėms; kodėl mes turėtume jam tarnauti?'),
  (@b7, 9, 29, 'O, kad šita tauta būtų mano rankos valdžioje! Tada pašalinčiau Abimelechą. Ir jis pasakė Abimelechui: ‘Padidink savo kariuomenę ir išeik’“.'),
  (@b7, 9, 30, 'O kai miesto valdovas Zebulas išgirdo Ebedo sūnaus Gaalo žodžius, užsidegė jo pyktis.'),
  (@b7, 9, 31, 'Ir jis slapta siuntė pas Abimelechą pasiuntinius, sakydamas: „Štai Ebedo sūnus Gaalas ir jo broliai yra atėję į Šechemą; ir štai jie sustiprina miestą prieš tave.'),
  (@b7, 9, 32, 'Taigi dabar kelkis naktį, tu ir su tavimi esanti liaudis, ir tykokite ant lauko;'),
  (@b7, 9, 33, 'ir bus, kad ryte, kai tik saulė patekės, anksti atsikėlęs pulk miestą; ir štai kai jis ir su juo esanti liaudis išeis prieš tave, tuomet galėsi padaryti jiems, kaip tau rasis galimybė“.'),
  (@b7, 9, 34, 'Ir Abimelechas ir visa su juo esanti liaudis naktį pakilo ir tykojo prieš Šechemą keturiais būriais.'),
  (@b7, 9, 35, 'Ir Ebedo sūnus Gaalas išėjęs atsistojo miesto vartų įėjime; o Abimelechas bei su juo esanti liaudis pakilo iš tykojimo.'),
  (@b7, 9, 36, 'Ir pamatęs liaudį, Gaalas tarė Zebului: „Štai žmonės leidžiasi nuo kalnų viršūnių“. O Zebulas jam tarė: „Tu matai kalnų šešėlius tarsi žmones“.'),
  (@b7, 9, 37, 'O Gaalas vėl kalbėjo, sakydamas: „Štai žmonės leidžiasi šalies viduriu, o kitas būrys ateina Meonenimo lyguma“.'),
  (@b7, 9, 38, 'Tada Zebulas jam tarė: „Kurgi dabar yra tavo burna, kuria sakei: ‘Kas yra Abimelechas, kad turėtume jam tarnauti?’ Ar ne šita yra liaudis, kurią niekinai? Meldžiu dabar, išeik ir kovok su jais“.'),
  (@b7, 9, 39, 'Ir Gaalas išėjo Šechemo žmonių priešakyje ir kovojo su Abimelechu.'),
  (@b7, 9, 40, 'Ir Abimelechas jį vijosi, o šis bėgo jo priešakyje, ir daug buvo išguldytų ir sužeistų iki vartų įėjimo.'),
  (@b7, 9, 41, 'Ir Abimelechas gyveno Arumoje; o Zebulas išvarė Gaalą ir jo brolius, kad jie negyventų Šecheme.'),
  (@b7, 9, 42, 'Ir įvyko rytojaus dieną, kad liaudis išėjo ant lauko; ir jie pasakė Abimelechui.'),
  (@b7, 9, 43, 'Ir jis ėmė liaudį, padalijo juos į tris būrius ir tykojo lauke, ir žiūri, štai liaudis buvo išėjusi iš miesto; ir jis pakilo prieš juos ir juos sumušė.'),
  (@b7, 9, 44, 'Ir Abimelechas bei su juo esantis būrys išskubėjo į priekį ir atsistojo miesto vartų įėjime; o kiti du būriai puolė visą liaudį, esančią laukuose, ir ją išžudė.'),
  (@b7, 9, 45, 'Ir Abimelechas kovojo prieš miestą visą tą dieną; jis paėmė miestą ir išžudė joje esančią liaudį, ir sugriovė miestą, ir apsėjo jį druska.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b7, 9, 46, 'Ir visi Šechemo bokšto žmonės tai išgirdę įėjo į dievo Berito namų tvirtovę.'),
  (@b7, 9, 47, 'Ir Abimelechui buvo pranešta, kad susirinko visi Šechemo bokšto žmonės.'),
  (@b7, 9, 48, 'Ir Abimelechas užlipo į Calmono kalną, jis ir visa su juo esanti liaudis; ir Abimelechas, pasiėmęs kirvį į ranką, nukirto nuo medžio šaką, paėmė ją ir užsidėjęs ant peties tarė su juo esančiai liaudžiai: „Ką matėte mane darant, skubinkitės, darykite, kaip aš“.'),
  (@b7, 9, 49, 'Ir visa liaudis taip pat nusikirto kiekvienas savo šaką ir sekė paskui Abimelechą, ir sudėjo jas prie tvirtovės, ir padegė tvirtovę ant jų; taip, kad mirė ir visi Šechemo bokšto žmonės, apie tūkstantį vyrų ir moterų.'),
  (@b7, 9, 50, 'Paskui Abimelechas nuėjo į Tebecą ir stovyklavo prieš Tebecą, ir jį paėmė.'),
  (@b7, 9, 51, 'Bet miesto viduje buvo stiprus bokštas, ir į ten pabėgo visi vyrai, moterys ir visi iš miesto, ir užsirakinę paskui save jie užlipo į bokšto viršų.'),
  (@b7, 9, 52, 'Ir Abimelechas atėjo prie bokšto ir kovojo prieš jį, ir atkakliai ėjo prie bokšto durų, kad padegtų jį ugnimi.'),
  (@b7, 9, 53, 'O viena moteris numetė ant Abimelecho galvos girnų akmens gabalą ir visai sulaužė jo kaukolę.'),
  (@b7, 9, 54, 'Tuomet jis skubiai pasišaukė jaunuolį, savo ginklanešį, ir jam tarė: „Išsitrauk kalaviją ir nužudyk mane, kad niekas nesakytų apie mane: ‘Moteris jį užmušė’.“ Ir jo jaunuolis jį perdūrė, ir jis mirė.'),
  (@b7, 9, 55, 'O Izraelio vaikai pamatę, kad Abimelechas nebegyvas, kiekvienas išėjo į savo vietą.'),
  (@b7, 9, 56, 'Taip Dievas atlygino už Abimelecho nedorybę, kurią jis padarė savo tėvui, nužudydamas septyniasdešimt savo brolių;'),
  (@b7, 9, 57, 'ir visą Šechemo žmonių piktybę Dievas atlygino ant jų galvos; ant jų atėjo Jerubaalo sūnaus Jotamo prakeikimas.'),
  (@b7, 10, 1, 'O po Abimelecho Izraelio ginti pakilo Dodo sūnaus Pūvos sūnus Tola, vyras iš Isacharo; ir jis gyveno Šamyre, Efraimo kalne.'),
  (@b7, 10, 2, 'Ir jis teisė Izraelį dvidešimt trejus metus ir mirė, ir buvo palaidotas Šamyre.'),
  (@b7, 10, 3, 'O po jo iškilo gileadietis Jayras, ir teisė Izraelį dvidešimt dvejus metus.'),
  (@b7, 10, 4, 'Ir jis turėjo trisdešimt sūnų, jojančių ant trisdešimties asiliukų, o jie turėjo trisdešimt miestų, kurie iki šios dienos yra vadinami Havot-Jayru, kurie yra Gileado krašte.'),
  (@b7, 10, 5, 'Ir Jayras mirė ir buvo palaidotas Kamone.'),
  (@b7, 10, 6, 'Ir Izraelio vaikai vėl darė pikta VIEŠPATIES akyse ir tarnavo Baalams, Astarotei, Sirijos dievams, Sidono dievams, Moabo dievams, Amono vaikų dievams ir filistinų dievams, ir paliko VIEŠPATĮ, ir jam netarnavo.'),
  (@b7, 10, 7, 'Ir VIEŠPATIES pyktis užsidegė prieš Izraelį, ir jis juos pardavė į filistinų rankas ir į Amono vaikų rankas.'),
  (@b7, 10, 8, 'Ir tais metais jie spaudė ir engė Izraelio vaikus, aštuoniolika metų visus Izraelio vaikus, esančius anapus Jordano amoritų šalyje, esančioje Gileade.'),
  (@b7, 10, 9, 'Be to, Amono vaikai perėjo Jordaną, kad kovotų prieš Judą, prieš Benjaminą ir prieš Efraimo namus; taip, kad Izraelis buvo labai suspaustas.'),
  (@b7, 10, 10, 'Ir Izraelio vaikai šaukėsi VIEŠPATIES, sakydami: „Prieš tave nusidėjome, nes palikome savo Dievą ir taip pat tarnavome Baalams“.'),
  (@b7, 10, 11, 'O VIEŠPATS tarė Izraelio vaikams: „Argi neišgelbėjau jūsų iš egiptiečių, iš amoritų, iš Amono vaikų ir iš filistinų?'),
  (@b7, 10, 12, 'Taip pat sidoniečiai, amalekiečiai ir maonitai jus engė; ir jūs šaukėtės manęs, o aš jus išgelbėjau iš jų rankų.'),
  (@b7, 10, 13, 'Tačiau jūs palikote mane ir tarnavote kitiems dievams; todėl daugiau nebegelbėsiu jūsų.'),
  (@b7, 10, 14, 'Eikite ir šaukitės dievų, kuriuos pasirinkote; tegul jie jus išgelbėja jūsų suspaudimo metu“.'),
  (@b7, 10, 15, 'O Izraelio vaikai tarė VIEŠPAČIUI: „Mes nusidėjome; daryk mums, kas tau atrodo tinkama; tik išgelbėk, meldžiame tave, mus šią dieną“.'),
  (@b7, 10, 16, 'Ir jie pašalino iš savo tarpo svetimus dievus ir tarnavo VIEŠPAČIUI; ir jo siela liūdėjo dėl Izraelio nelaimės.'),
  (@b7, 10, 17, 'Tada Amono vaikai susirinko ir stovyklavo Gileade. O Izraelio vaikai susirinko ir stovyklavo Micpėje.'),
  (@b7, 10, 18, 'Ir Gileado tauta ir kunigaikščiai sakė vienas kitam: „Kas tas vyras, kuris pradės kovoti prieš Amono vaikus? Tas bus visų Gileado gyventojų galva“.'),
  (@b7, 11, 1, 'Na, o gileadietis Jefta buvo galingas narsuolis, ir jis buvo paleistuvės sūnus; Gileadas pagimdė Jeftą.'),
  (@b7, 11, 2, 'Ir Gileado žmona jam pagimdė sūnų; o jo žmonos sūnūs užaugo ir išvarė Jeftą, sakydami jam: „Tu nepaveldėsi mūsų tėvo namuose; nes tu esi svetimos moters sūnus“.'),
  (@b7, 11, 3, 'Tada Jefta pabėgo nuo savo brolių ir apsigyveno Tobo šalyje; ir pas Jeftą susirinko niekingi žmonės ir išėjo su juo.'),
  (@b7, 11, 4, 'Ir įvyko, kuriam laikui praslinkus, kad Amono vaikai kariavo su Izraeliu.'),
  (@b7, 11, 5, 'Ir buvo, kai Amono vaikai kariavo su Izraeliu, Gileado vyresnieji ėjo atsivesti Jeftos iš Tobo šalies;'),
  (@b7, 11, 6, 'ir jie sakė Jeftai: „Ateik ir būk mūsų vadas, kad kariautume su Amono vaikais“.'),
  (@b7, 11, 7, 'O Jefta tarė Gileado vyresniesiems: „Ar ne jūs manęs nekentėte ir išvarėte mane iš mano tėvo namų? Tai kodėl atėjote pas mane dabar, kai esate bėdoje?“'),
  (@b7, 11, 8, 'Ir Gileado vyresnieji tarė Jeftai: „Dėl to dabar kreipiamės į tave, kad eitum su mumis, kovotum prieš Amono vaikus ir būtum mūsų galva visiems Gileado gyventojams“.'),
  (@b7, 11, 9, 'Ir Jefta tarė Gileado vyresniesiems: „Jei mane sugrąžinsite namo kariauti prieš Amono vaikus, ir jei VIEŠPATS juos atiduos mano priešakyje, ar aš būsiu jūsų galva?“'),
  (@b7, 11, 10, 'O Gileado vyresnieji tarė Jeftai: „VIEŠPATS tebūna tarp mūsų liudytojas, jei taip nedarysime pagal tavo žodžius“.'),
  (@b7, 11, 11, 'Tada Jefta nuėjo su Gileado vyresniaisiais, ir tauta jį paskyrė sau galva ir vadu; ir Jefta pasakė visus savo žodžius VIEŠPATIES akivaizdoje, Micpėje.'),
  (@b7, 11, 12, 'Ir Jefta siuntė pasiuntinius pas Amono vaikų karalių, sakydamas: „Kas tau darbo su manimi, kad atėjai prieš mane kovoti mano šalyje?“'),
  (@b7, 11, 13, 'O Amono vaikų karalius atsakė Jeftos pasiuntiniams: „Dėl to, kad Izraelis, eidamas aukštyn iš Egipto, atėmė mano šalį nuo Arnono iki Jaboko ir Jordano; taigi dabar sugrąžink tas žemes taikingai“.'),
  (@b7, 11, 14, 'O Jefta vėl siuntė pasiuntinius pas Amono vaikų karalių'),
  (@b7, 11, 15, 'ir jam sakė: „Taip sako Jefta: Izraelis neatėmė Moabo šalies nei Amono vaikų šalies;'),
  (@b7, 11, 16, 'bet kai Izraelis ėjo aukštyn iš Egipto ir ėjo per dykumą iki Raudonosios jūros ir atvyko į Kadešą;'),
  (@b7, 11, 17, 'tada Izraelis siuntė pasiuntinius pas Edomo karalių, sakydamas: ‘Leisk, meldžiu tave, pereiti per tavo šalį’; bet Edomo karalius nenorėjo to klausyti. Ir tokiu pat būdu jie siuntė pas Moabo karalių; bet jis nenorėjo leisti; ir Izraelis pasiliko Kadeše.'),
  (@b7, 11, 18, 'Paskui jie ėjo per dykumą ir apėjo Edomo šalį bei Moabo šalį, ir atėjo prie Moabo šalies rytinės pusės, ir stovyklavo anapus Arnono, bet nėjo į Moabo ribas; nes Arnonas buvo Moabo riba.'),
  (@b7, 11, 19, 'Ir Izraelis siuntė pasiuntinius pas amoritų karalių Sihoną, Hešbono karalių; ir Izraelis jam sakė: „Meldžiame tave, leisk mums pereiti per tavo šalį į mano vietą“.'),
  (@b7, 11, 20, 'Bet Sihonas nepasitikėjo Izraeliu, kad pereitų per jo ribą; bet Sihonas surinko visą savo tautą ir stovyklavo Jahace, ir kovojo prieš Izraelį.'),
  (@b7, 11, 21, 'O VIEŠPATS, Izraelio Dievas, atidavė Sihoną ir visą jo tautą į Izraelio ranką, ir jie sumušė juos; taip Izraelis pasisavino visą amoritų, to krašto gyventojų, šalį.'),
  (@b7, 11, 22, 'Ir jie pasisavino visas amoritų ribas nuo Arnono iki Jaboko ir nuo dykumos iki Jordano.'),
  (@b7, 11, 23, 'Taip VIEŠPATS, Izraelio Dievas, atėmė amoritų nuosavybę savo tautos Izraelio akivaizdoje, o tu ar turėtum ją pasisavinti?'),
  (@b7, 11, 24, 'Argi nepasisavintum to, ką tavo dievas Kemošas tau duoda pasisavinti? Taigi kuriuos VIEŠPATS, mūsų Dievas, išvarys iš mūsų akivaizdos, tuos mes pasisavinsime.'),
  (@b7, 11, 25, 'O dabar, ar esi kažkuo geresnis už Ciporo sūnų Balaką, Moabo karalių? Ar jis kada nors vaidijosi su Izraeliu? Ar jis kada nors kovojo prieš juos,'),
  (@b7, 11, 26, 'Izraeliui gyvenant Hešbone ir jo miesteliuose, Aroeryje ir jo miesteliuose, ir visuose miestuose, esančiuose palei Arnono ribas, tris šimtus metų? Tai kodėl per tą laiką jų nesusigrąžinote?'),
  (@b7, 11, 27, 'Todėl aš nenusidėjau prieš tave, bet tu darai man pikta, kad kariauji prieš mane; VIEŠPATS, Teisėjas, teteisia šią dieną tarp Izraelio vaikų ir Amono vaikų“.'),
  (@b7, 11, 28, 'Tačiau Amono vaikų karalius neklausė Jeftos žodžių, kuriuos jis jam nusiuntė.'),
  (@b7, 11, 29, 'Tada VIEŠPATIES Dvasia atėjo ant Jeftos, ir jis perėjo Gileadą ir Manasą, perėjo Gileado Micpę, ir iš Gileado Micpės perėjo Amono vaikų link.'),
  (@b7, 11, 30, 'Ir Jefta padarė VIEŠPAČIUI įžadą ir sakė: „Jei visiškai atiduosi Amono vaikus į mano rankas,'),
  (@b7, 11, 31, 'tada, man ramybėje grįžus iš Amono vaikų, kas išeis iš mano namų durų manęs pasitikti, tikrai bus VIEŠPATIES, ir aš jį atnašausiu kaip deginamąją atnašą“.'),
  (@b7, 11, 32, 'Taigi Jefta perėjo Amono vaikų link, prieš juos kovoti; ir VIEŠPATS juos atidavė į jo rankas.'),
  (@b7, 11, 33, 'Ir jis mušė juos nuo Aroerio einant iki Minito, dvidešimt miestų, ir iki vynuogynų lygumos, labai smarkiomis žudynėmis. Taip Amono vaikai buvo pavergti Izraelio vaikų akivaizdoje.'),
  (@b7, 11, 34, 'Ir Jefta atėjo į Micpę, į savo namus, ir štai jo duktė išėjo jo pasitikti su tambūrinu ir šokiais; o ji buvo jo vienintelis vaikas; be jos jis neturėjo nei sūnaus, nei dukters.'),
  (@b7, 11, 35, 'Ir atsitiko, kai jis ją pamatė, jis perplėšė savo drabužius ir tarė: „Ak, mano dukra! Tu mane visiškai parkniubdei, tu iš tų, kurie mane drumsčia; nes aš atvėriau savo burną VIEŠPAČIUI ir nebegaliu atšaukti“.'),
  (@b7, 11, 36, 'O ji jam tarė: „Mano tėve, jei atvėrei savo burną VIEŠPAČIUI, padaryk man pagal tai, kas išėjo iš tavo burnos; kadangi VIEŠPATS yra atkeršijęs už tave tavo priešams, tai yra Amono vaikams“.'),
  (@b7, 11, 37, 'Ir ji tarė savo tėvui: „Tebūna man tai leista: palik mane du mėnesius, kad vaikštinėčiau po kalnus ir apraudočiau savo nekaltybę, aš ir mano draugės“.'),
  (@b7, 11, 38, 'Ir jis tarė: „Eik“. Ir jis ją paleido dviems mėnesiams; o ji nuėjo su savo draugėmis ir apraudojo savo mergystę kalnuose.'),
  (@b7, 11, 39, 'Ir įvyko, kad pasibaigus dviems mėnesiams ji sugrįžo pas savo tėvą, kuris įvykdė jai pagal savo įžadą, kurį buvo padaręs; ir ji nepažino vyro. Ir Izraelyje tai buvo paprotys,'),
  (@b7, 11, 40, 'kad kasmet, keturias dienas metuose, Izraelio dukterys eidavo apraudoti gileadiečio Jeftos dukters.'),
  (@b7, 12, 1, 'Ir susirinko Efraimo vyrai ir nuėję į šiaurę sakė Jeftai: „Kodėl, perėjai kovoti prieš Amono vaikus, o nepasišaukei mūsų eiti su tavimi? Mes sudeginsime ugnimi tavo namus ant tavęs“.'),
  (@b7, 12, 2, 'O Jefta jiems tarė: „Aš ir mano liaudis labai susivaidijome su Amono vaikais; ir kai jus šaukiau, jūs manęs neišgelbėjote iš jų rankų.'),
  (@b7, 12, 3, 'Ir matydamas, kad manęs neišgelbėjote, aš padėjau savo gyvybę į savo rankas ir perėjau prieš Amono vaikus, o VIEŠPATS juos atidavė į mano ranką; tad kodėl šią dieną atkilote pas mane kovoti prieš mane?“'),
  (@b7, 12, 4, 'Tada Jefta surinko visus Gileado vyrus ir kovojo su Efraimu; ir Gileado vyrai sumušė efraimus, nes jie sakė: „Jūs, gileadiečiai, esate Efraimo pabėgėliai tarp efraimų ir tarp manasų“.'),
  (@b7, 12, 5, 'Ir gileadiečiai paėmė Jordano perėjimus priešais efraimus; ir buvo, kai pabėgę efraimai sakydavo: „Leiskite man pereiti“, tada Gileado žmonės jam sakydavo: „Ar tu efraimas?“ Jei jis sakydavo: „Ne“,'),
  (@b7, 12, 6, 'tuomet jie jam sakydavo: „Sakyk dabar ‘Šibolet’“; o jis tardavo „Sibolet“, nes negalėdavo teisingai ištarti. Tada jie paimdavo jį ir nužudydavo prie Jordano perėjimų; ir tuo metu iš efraimų krito keturiasdešimt du tūkstančiai.'),
  (@b7, 12, 7, 'Jefta teisė Izraelį šešerius metus. Paskui gileadietis Jefta mirė ir buvo palaidotas viename iš Gileado miestų.'),
  (@b7, 12, 8, 'O po jo Izraelį teisė Ibcanas iš Betliejaus.'),
  (@b7, 12, 9, 'Jis turėjo trisdešimt sūnų ir trisdešimt dukterų, kurias išsiuntė svetur, ir priėmė iš svetur trisdešimt dukterų savo sūnums. Ir jis teisė Izraelį septynerius metus.'),
  (@b7, 12, 10, 'Paskui Ibcanas mirė ir buvo palaidotas Betliejuje.'),
  (@b7, 12, 11, 'O po jo Izraelį teisė zebulonas Elonas; ir jis teisė Izraelį dešimt metų.'),
  (@b7, 12, 12, 'Ir zebulonas Elonas mirė ir buvo palaidotas Ajalone, Zebulono krašte.'),
  (@b7, 12, 13, 'O po jo Izraelį teisė Hilelio sūnus Abdonas, piratonietis.'),
  (@b7, 12, 14, 'Ir jis turėjo keturiasdešimt sūnų ir trisdešimt vaikaičių, jojančių ant septyniasdešimties asiliukų; ir jis teisė Izraelį aštuonerius metus.'),
  (@b7, 12, 15, 'Ir Hilelio sūnus Abdonas, piratonietis, mirė ir buvo palaidotas Piratone, Efraimo krašte, amalekiečių kalne.'),
  (@b7, 13, 1, 'Ir Izraelio vaikai vėl darė pikta VIEŠPATIES akyse; ir VIEŠPATS juos padavė į filistinų ranką keturiasdešimčiai metų.'),
  (@b7, 13, 2, 'Ir buvo vienas vyras iš Coros, iš danų šeimos, vardu Manoachas; o jo žmona buvo nevaisinga ir negimdė.'),
  (@b7, 13, 3, 'Ir VIEŠPATIES angelas pasirodė tai moteriai ir jai tarė: „Štai tu dabar esi nevaisinga ir negimdai; bet tu pastosi ir pagimdysi sūnų.'),
  (@b7, 13, 4, 'Taigi dabar saugokis, meldžiu tave, negerk nei vyno, nei stipraus gėrimo ir nevalgyk nieko nešvaraus;'),
  (@b7, 13, 5, 'nes štai tu pastosi ir pagimdysi sūnų; skustuvas neturi užeiti ant jo galvos; nes vaikas bus naziras Dievui nuo pat įsčių; ir jis pradės gelbėti Izraelį iš filistinų rankos“.'),
  (@b7, 13, 6, 'Tada ta moteris atėjusi tarė savo vyrui, sakydama: „Dievo vyras atėjo pas mane, ir jo veidas buvo kaip Dievo angelo veidas, labai bauginantis; bet aš jo nepaklausiau, iš kur jis esąs, nei jis man nepasakė savo vardo;'),
  (@b7, 13, 7, 'bet jis man tarė: ‘Štai tu pastosi ir pagimdysi sūnų; ir dabar negerk nei vyno, nei stipraus gėrimo, nei nevalgyk nieko nešvaraus; nes vaikas bus naziras Dievui nuo pat įsčių iki savo mirties dienos’“.'),
  (@b7, 13, 8, 'Tada Manoachas maldavo VIEŠPATĮ ir sakė: „O, mano Viešpatie, tesugrįžta Dievo vyras, kurį buvai atsiuntęs pas mus, ir tepamoko mus, ką turime daryti vaikui, kuris gims“.'),
  (@b7, 13, 9, 'Ir Dievas išklausė Manoacho balsą; ir Dievo angelas sugrįžo pas tą moterį, kai ji sėdėjo ant lauko; bet jos vyro Manoacho nebuvo su ja.'),
  (@b7, 13, 10, 'Ir moteris pasiskubino, nubėgo ir pranešė savo vyrui, ir jam tarė: „Štai man pasirodė tas vyras, kuris aną dieną buvo atėjęs pas mane“.'),
  (@b7, 13, 11, 'Ir pakilęs Manoachas ėjo paskui savo žmoną ir, atėjęs pas tą vyrą, jam tarė: „Ar tu esi tas vyras, kuris kalbėjai tai moteriai?“ Ir jis tarė: „Aš“.'),
  (@b7, 13, 12, 'Ir Manoachas tarė: „Tegul dabar įvyksta tavo žodžiai. Kaip mums tvarkytis su vaiku ir kaip mums su juo elgtis?“'),
  (@b7, 13, 13, 'Ir VIEŠPATIES angelas tarė Manoachui: „Nuo visko, ką pasakiau moteriai, ji tesisaugo.'),
  (@b7, 13, 14, 'Jai nieko negalima valgyti iš to, kas išeina iš vynmedžio, nei gerti vyno ar stipraus gėrimo, nei valgyti ko nors nešvaraus; ji tesilaiko visko, ką jai įsakiau“.'),
  (@b7, 13, 15, 'Ir Manoachas tarė VIEŠPATIES angelui: „Meldžiu tave, leisk mums užlaikyti tave, kol tau paruošime ožiuką“.'),
  (@b7, 13, 16, 'O VIEŠPATIES angelas tarė Manoachui: „Nors mane užlaikysi, bet aš nevalgysiu tavo duonos; o jei nori atnašauti deginamąją atnašą, VIEŠPAČIUI turi ją atnašauti“. Nes Manoachas nežinojo, kad jis buvo VIEŠPATIES angelas.'),
  (@b7, 13, 17, 'Ir Manoachas tarė VIEŠPATIES angelui: „Kuo tu vardu? Kad, tavo pasakymams įvykus, galėtume tave pagerbti“.'),
  (@b7, 13, 18, 'O VIEŠPATIES angelas jam tarė: „Kodėl taip klausinėji mano vardo, kadangi jis yra paslaptis?“'),
  (@b7, 13, 19, 'Taigi Manoachas, paėmęs ožiuką su maisto atnaša, atnašavo tai ant uolos VIEŠPAČIUI; ir angelas padarė nuostabiai; o Manoachas ir jo žmona stebėjo.'),
  (@b7, 13, 20, 'Nes įvyko, kad, liepsnai kylant nuo aukuro į dangų, VIEŠPATIES angelas pakilo aukuro liepsnoje. O tai matydami, Manoachas ir jo žmona parpuolė veidais į žemę.'),
  (@b7, 13, 21, 'Bet VIEŠPATIES angelas daugiau nebepasirodė Manoachui ir jo žmonai. Tada Manoachas pažino, kad jis buvo VIEŠPATIES angelas.'),
  (@b7, 13, 22, 'Ir Manoachas tarė savo žmonai: „Mes tikrai mirsime, nes regėjome Dievą“.'),
  (@b7, 13, 23, 'Bet jo žmona jam tarė: „Jei VIEŠPATS būtų norėjęs mus nužudyti, jis nebūtų priėmęs iš mūsų rankų deginamosios atnašos ir maisto atnašos nei nebūtų mums viso to parodęs nei dabar mums paskelbęs tokių dalykų, kaip šitie“.'),
  (@b7, 13, 24, 'Ir ta moteris pagimdė sūnų ir jį praminė vardu Samsonas; ir vaikas augo, ir VIEŠPATS jį laimino.'),
  (@b7, 13, 25, 'Ir VIEŠPATIES Dvasia pradėjo jį retkarčiais skatinti Dano stovykloje tarp Coros ir Eštaolio.'),
  (@b7, 14, 1, 'Ir Samsonas, nusileidęs į Timną, pamatė Timnoje moterį iš filistinų dukterų.'),
  (@b7, 14, 2, 'Ir atėjęs aukštyn, papasakojo savo tėvui ir motinai, ir sakė: „Mačiau Timnoje moterį iš filistinų dukterų; taigi dabar paimkite ją man į žmonas“.'),
  (@b7, 14, 3, 'Tada jo tėvas ir jo motina jam tarė: „Argi tarp tavo brolių dukterų ar visos mano tautos tarpe nėra moters, kad eini imti žmonos iš neapipjaustytų filistinų?“ O Samsonas tarė savo tėvui: „Paimk ją man; nes ji man labai patinka“.'),
  (@b7, 14, 4, 'Bet jo tėvas ir jo motina nežinojo, kad tai buvo iš VIEŠPATIES, kad jis ieškojo progos prieš filistinus; nes tuo metu filistinai viešpatavo Izraeliui.'),
  (@b7, 14, 5, 'Paskui Samsonas leidosi su savo tėvu ir savo motina į Timną, ir atėjo prie Timnos vynuogynų; ir štai prieš jį riaumojo jaunas liūtas.'),
  (@b7, 14, 6, 'Ir VIEŠPATIES Dvasia galingai atėjo ant jo, ir jis suplėšė jį, kaip būtų suplėšęs ožiuką, nors jis nieko neturėjo savo rankoje; bet jis nepasakė savo tėvui ar savo motinai, ką buvo padaręs.'),
  (@b7, 14, 7, 'Ir nuėjęs žemyn, jis kalbėjo su ta moterimi; ir ji labai patiko Samsonui.'),
  (@b7, 14, 8, 'O po kurio laiko jis sugrįžo jos paimti, ir jis pasuko į šoną, kad pamatytų liūto lavoną; ir štai liūto lavone buvo bičių spiečius ir medaus.'),
  (@b7, 14, 9, 'Ir jis paėmė jo sau į rankas ir ėjo toliau valgydamas, ir atėjęs pas savo tėvą ir motiną, jiems davė, ir jie valgė; bet jis jiems nepasakė, kad paėmė medaus iš liūto lavono.'),
  (@b7, 14, 10, 'Taigi jo tėvas nuėjo žemyn pas tą moterį; ir ten Samsonas suruošė puotą; nes taip buvo įpratę daryti jaunuoliai.'),
  (@b7, 14, 11, 'Ir įvyko, kad, pamatę jį, jie atvedė trisdešimt draugų, kad būtų su juo.'),
  (@b7, 14, 12, 'Ir Samsonas jiems tarė: „Aš dabar užminsiu jums mįslę; jei man ją tikrai galėsite įminti ir išsiaiškinti per septynias puotos dienas, tai aš jums duosiu trisdešimt drobulių ir trisdešimt drabužių pakaitų;'),
  (@b7, 14, 13, 'bet jei negalėsite man jos įminti, tada jūs man duosite trisdešimt drobulių ir trisdešimt drabužių pakaitų“. Ir jie jam tarė: „Užmink savo mįslę, kad ją išgirstume“.'),
  (@b7, 14, 14, 'Ir jis jiems tarė: „Iš ėdiko išėjo valgis, ir iš stipruolio išėjo saldumas“. Ir jie negalėjo įminti mįslės per tris dienas.'),
  (@b7, 14, 15, 'Ir įvyko septintąją dieną, jog jie sakė Samsono žmonai: „Suviliok savo vyrą, kad jis mums įmintų mįslę, kitaip sudeginsime tave ir tavo tėvo namus ugnimi; ar mus pasikvietėte, kad atimtumėte tai, ką turime? Argi ne?“'),
  (@b7, 14, 16, 'Ir Samsono žmona verkė jo akivaizdoje ir sakė: „Tu tik nekenti manęs ir manęs nemyli; tu užminei mįslę mano tautos vaikams, o man jos nepasakei“. O jis jai tarė: „Štai aš nepasakiau jos nei savo tėvui, nei savo motinai, argi tau turėčiau pasakyti?“'),
  (@b7, 14, 17, 'Ir ji verkė jo akivaizdoje septynias dienas, kol tęsėsi jų puota; o septintąją dieną atsitiko, kad jis jai pasakė, nes ji labai jį užgulė; ir ji pasakė mįslę savo tautos vaikams.'),
  (@b7, 14, 18, 'Ir septintąją dieną, prieš saulei nusileidžiant, miesto vyrai jam tarė: „Kas yra saldesnis už medų? Ir kas yra stipresnis už liūtą?“ O jis jiems tarė: „Jei nebūtumėte arę su mano telyčia, nebūtumėte išsiaiškinę mano mįslės“.'),
  (@b7, 14, 19, 'Ir ant jo atėjo VIEŠPATIES Dvasia, ir jis, nusileidęs į Aškeloną, užmušė iš jų trisdešimt vyrų, paėmė jų grobį ir davė drabužių pakaitas tiems, kurie įminė mįslę. Ir užsidegė jo pyktis, ir jis nuėjo aukštyn į savo tėvo namus.'),
  (@b7, 14, 20, 'Bet Samsono žmona buvo duota jo draugui, su kuriuo jis elgdavosi kaip su savo bičiuliu.'),
  (@b7, 15, 1, 'Bet įvyko po kiek laiko, kviečių pjūties metu, kad Samsonas su ožiuku aplankė savo žmoną; ir jis tarė: „Noriu įeiti į kambarį pas savo žmoną“. Bet jos tėvas neleido jam įeiti.'),
  (@b7, 15, 2, 'Ir jos tėvas tarė: „Tikrai maniau, kad visiškai jos nekenti; todėl ją daviau tavo draugui; argi jos jaunesnioji sesuo nėra gražesnė už ją? Meldžiu tave, imk tą vietoj jos“.'),
  (@b7, 15, 3, 'Ir Samsonas apie juos tarė: „Dabar būsiu nekaltesnis už filistinus, nors ir padarysiu jiems nemalonę“.'),
  (@b7, 15, 4, 'Ir nuėjęs Samsonas sugavo tris šimtus lapių ir, paėmęs deglų, atsuko uodegą į uodegą ir padėjo po deglą viduryje tarp abiejų uodegų.'),
  (@b7, 15, 5, 'Ir uždegęs deglus, paleido jas į filistinų stovinčius javus ir sudegino tiek gubas, tiek stovinčius javus su vynuogynais bei alyvmedžiais.'),
  (@b7, 15, 6, 'Tada filistinai tarė: „Kas tai padarė?“ Ir jie atsakė: „Samsonas, timniečio žentas, dėl to, kad jis buvo paėmęs jo žmoną ir ją davęs jo draugui“. Ir atėję į viršų filistinai sudegino ją ir jos tėvą ugnimi.'),
  (@b7, 15, 7, 'Ir Samsonas jiems tarė: „Nors jūs taip padarėte, tačiau aš jums atkeršysiu, o po to liausiuos“.'),
  (@b7, 15, 8, 'Ir smarkiomis žudynėmis jis sumušė jiems klubus ir šlaunis; ir jis nuėjo žemyn ir gyveno Etamo uolos viršūnėje.'),
  (@b7, 15, 9, 'Tada filistinai, nuėję aukštyn, stovyklavo Judoje ir pasklido Lehyje.'),
  (@b7, 15, 10, 'Ir Judos žmonės tarė: „Kodėl atėjote į viršų prieš mus?“ Ir jie atsakė: „Atėjome į viršų Samsono surišti, padaryti jam taip, kaip jis mums padarė“.'),
  (@b7, 15, 11, 'Tada trys tūkstančiai Judos vyrų nuėjo į Etamo uolos viršūnę ir tarė Samsonui: „Argi nežinai, kad mus valdo filistinai? Kas tai, ką mums padarei?“ O jis jiems tarė: „Kaip jie man padarė, taip aš jiems padariau“.'),
  (@b7, 15, 12, 'O jie jam tarė: „Mes atėjome žemyn tavęs surišti, kad tave atiduotume į filistinų rankas“. O Samsonas jiems tarė: „Prisiekite man, kad patys ant manęs nepulsite“.'),
  (@b7, 15, 13, 'Ir jie jam kalbėjo, sakydami: „Ne; tik norime tave tvirtai surišti ir atiduoti į jų ranką; bet tikrai tavęs nenužudysime“. Ir jie surišo jį dviem naujomis virvėmis ir vedė jį nuo uolos aukštyn.'),
  (@b7, 15, 14, 'Ir jam atėjus prie Lehio, filistinai šaukė prieš jį; ir VIEŠPATIES Dvasia galingai atėjo ant jo, ir virvės, buvusios ant jo rankų, pasidarė kaip ugnimi sudegę linai, ir jo raiščiai atsirišo nuo jo rankų.'),
  (@b7, 15, 15, 'Ir suradęs šviežią asilo žandikaulį, jis ištiesė savo ranką ir, jį pasiėmęs, juo užmušė tūkstantį vyrų.'),
  (@b7, 15, 16, 'Ir Samsonas tarė: „Asilo žandikauliu krūvas ant krūvų, asilo žandikauliu nužudžiau tūkstantį vyrų“.'),
  (@b7, 15, 17, 'Ir įvyko, kad baigęs kalbėti jis išmetė žandikaulį iš savo rankos ir praminė tą vietą Ramat-Lehiu.'),
  (@b7, 15, 18, 'Ir labai ištroškęs, jis šaukėsi VIEŠPATIES ir sakė: „Tu davei savo tarnui į ranką šitą didelį išgelbėjimą; o ar dabar aš mirsiu iš troškulio ir pateksiu į neapipjaustytųjų ranką?“'),
  (@b7, 15, 19, 'Bet Dievas perskėlė žandikaulyje esančią kiaurymę, ir iš jos ištekėjo vanduo; ir jam atsigėrus, sugrįžo jo dvasia, ir jis atgijo; todėl ją pavadino En-Hakore vardu, kuri yra Lehyje iki šios dienos.'),
  (@b7, 15, 20, 'Ir filistinų dienomis jis teisė Izraelį dvidešimt metų.'),
  (@b7, 16, 1, 'Po to Samsonas nuėjo į Gazą ir ten pamatęs paleistuvę įėjo pas ją.'),
  (@b7, 16, 2, 'Ir tai buvo pranešta gaziečiams, sakant: „Samsonas yra čia atėjęs“. Ir jie apsupo jį ir visą naktį jo tykojo miesto vartuose, ir visą naktį buvo tylūs, sakydami: „Ryte, kai prašvis, mes jį užmušime“.'),
  (@b7, 16, 3, 'O Samsonas gulėjo iki vidurnakčio, ir vidurnaktį atsikėlęs paėmė miesto vartų duris bei abi staktas ir jas iškėlė su sklende ir, užsidėjęs ant pečių, užnešė jas ant viršūnės kalvos, esančios prieš Hebroną.'),
  (@b7, 16, 4, 'O paskui įvyko, kad Soreko slėnyje jis pamilo moterį, kurios vardas buvo Delila.'),
  (@b7, 16, 5, 'Ir filistinų viešpačiai atėjo aukštyn pas ją ir jai tarė: „Suviliok jį ir išsiaiškink, kur glūdi jo didelė jėga, ir kokiu būdu galėtume jį įveikti, kad galėtume jį surišti, idant jį kamuotume; o mes tau duosime kiekvienas po tūkstantį šimtą sidabrinių“.'),
  (@b7, 16, 6, 'Ir Delila tarė Samsonui: „Pasakyk man, meldžiu tave, kame glūdi tavo didelė jėga, ir kuo būtų galima tave surišti, idant tave kamuotų“.'),
  (@b7, 16, 7, 'Ir Samsonas jai tarė: „Jei mane surištų septyniomis šviežiomis vytelėmis, kurios niekada nebuvo išdžiūvusios, tada būčiau silpnas ir būčiau kaip bet kuris žmogus“.'),
  (@b7, 16, 8, 'Tada filistinų viešpačiai atnešė aukštyn pas ją septynias šviežias vyteles, kurios nebuvo išdžiūvusios, ir ji jomis surišo jį.'),
  (@b7, 16, 9, 'Na, o buvo tykotojų, pasilikusių pas ją kambaryje. Ir ji jam tarė: „Filistinai ant tavęs, Samsonai“. Ir jis sutraukė vyteles, kaip sutrūksta pakulų gija, palietusi ugnį. Taip jo jėga nebuvo pažinta.'),
  (@b7, 16, 10, 'Ir Delila tarė Samsonui: „Štai tu tyčiojaisi iš manęs ir man kalbėjai melus; dabar pasakyk man, meldžiu tave, kuo būtų galima tave surišti“.'),
  (@b7, 16, 11, 'O jis jai tarė: „Jei mane tvirtai surištų naujomis virvėmis, kurios dar nebuvo naudotos, tada būčiau silpnas ir būčiau kaip bet kuris žmogus“.'),
  (@b7, 16, 12, 'Taigi Delila, paėmusi naujas virves, jomis surišo jį ir jam tarė: „Filistinai ant tavęs, Samsonai“. Ir buvo tykotojai pasilikę kambaryje. O jis jas sutraukė nuo savo rankų lyg siūlą.'),
  (@b7, 16, 13, 'Ir Delila tarė Samsonui: „Lig šiol tyčiojaisi iš manęs ir man kalbėjai melus; pasakyk man, kuo tave galima surišti“. Ir jis jai tarė: „Jei supinsi septynias mano galvos kasas su audeklu“.'),
  (@b7, 16, 14, 'Ir ji prismeigė jas kuoleliu ir jam tarė: „Filistinai ant tavęs, Samsonai“. O jis, pabudęs iš miego, nuėjo su sijos kuoleliu ir su audeklu.'),
  (@b7, 16, 15, 'Ir ji tarė jam: „Kaip tu gali sakyti: ‘Aš myliu tave’, kai tavo širdis nėra su manimi? Tuos tris kartus pasityčiojai iš manęs ir man nepasakei, kame glūdi tavo didelė jėga“.'),
  (@b7, 16, 16, 'Ir kai ji kasdien jį spaudė savo žodžiais ir primygtinai jo reikalavo, kad jo siela buvo mirtinai nuvarginta, įvyko,'),
  (@b7, 16, 17, 'kad jis jai išpasakojo visą savo širdį, sakydamas jai: „Skustuvas nėra užėjęs ant mano galvos; nes aš buvau naziras Dievui nuo savo motinos įsčių; jei būčiau nuskustas, tada nuo manęs atstotų mano jėga, ir aš pasidaryčiau silpnas ir būčiau kaip bet kuris žmogus“.'),
  (@b7, 16, 18, 'O Delila pamačiusi, kad jis jai išpasakojo visą savo širdį, siuntė ir pakvietė filistinų viešpačius, sakydama: „Dar sykį ateikite aukštyn, nes jis man parodė visą savo širdį“. Tada filistinų viešpačiai atėjo aukštyn pas ją ir atsinešė rankose pinigų.'),
  (@b7, 16, 19, 'Ir ji užmigdė jį ant savo kelių; ir ji pašaukė vyrą ir davė jam nuskusti septynias jo galvos kasas; ir ji pradėjo jį kamuoti, ir jo jėga atstojo nuo jo.'),
  (@b7, 16, 20, 'Ir ji tarė: „Filistinai ant tavęs, Samsonai“. Ir pabudęs iš miego, jis tarė: „Išeisiu, kaip prieš tai kitais kartais, ir nusikratysiu“. O jis nežinojo, kad VIEŠPATS buvo atsitraukęs nuo jo.'),
  (@b7, 16, 21, 'Bet jį paėmę, filistinai išlupo jam akis ir nuvedė jį žemyn į Gazą, ir surišo jį žalvario grandinėmis; ir jis malė kalėjimo namuose.'),
  (@b7, 16, 22, 'Tačiau po jo nuskutimo jo galvos plaukai vėl pradėjo augti.'),
  (@b7, 16, 23, 'Tada filistinų viešpačiai susirinko atnašauti didelę auką savo dievui Dagonui ir džiaugtis; nes jie sakė: „Mūsų dievas atidavė į mūsų ranką Samsoną, mūsų priešą“.'),
  (@b7, 16, 24, 'Ir tauta, jį pamačiusi, gyrė savo dievą; nes jie sakė: „Mūsų dievas atidavė į mūsų rankas mūsų priešą ir mūsų šalies naikintoją, kuris daugelį iš mūsų užmušė“.'),
  (@b7, 16, 25, 'Ir įvyko, kai jų širdys buvo linksmos, jie tarė: „Pašaukite Samsoną, kad jis mus palinksmintų“. Ir jie pašaukė Samsoną iš kalėjimo namų; ir jis juos linksmino; ir jie pastatė jį tarp stulpų.'),
  (@b7, 16, 26, 'Ir Samsonas tarė berniukui, laikančiam jį už rankos: „Leisk man, kad pačiupinėčiau stulpus, ant kurių stovi namas, kad atsiremčiau į juos“.'),
  (@b7, 16, 27, 'Na, o namas buvo pilnas vyrų ir moterų; ten buvo visi filistinų viešpačiai; o ant stogo buvo apie tris tūkstančius vyrų ir moterų, žiūrinčių, kaip Samsonas linksmino.'),
  (@b7, 16, 28, 'Ir Samsonas šaukėsi VIEŠPATIES ir tarė: „O Viešpatie DIEVE, atsimink mane, meldžiu tave, ir sustiprink mane, meldžiu, tik šitą vieną kartą, o Dieve, kad atkeršyčiau filistinams vienu kartu už abi mano akis“.'),
  (@b7, 16, 29, 'Ir Samsonas nutvėrė abu vidurinius stulpus, ant kurių stovėjo namas ir ant kurių laikėsi, vieną savo dešine ranka, o kitą savo kaire.'),
  (@b7, 16, 30, 'Ir Samsonas tarė: „Temirsiu su filistinais“. Ir jis pasilenkė visa savo galybe; ir namas griuvo ant viešpačių ir ant visos jame esančios liaudies. Taip mirusiųjų, kuriuos jis užmušė mirdamas, buvo daugiau negu tų, kuriuos jis užmušė gyvendamas.'),
  (@b7, 16, 31, 'Tada atėjo žemyn jo broliai bei visi jo tėvo namai ir pasiėmė jį, ir nunešė jį aukštyn, ir palaidojo tarp Coros ir Eštaolio, jo tėvo Manoacho laidojimo vietoje. Jis dvidešimt metų teisė Izraelį.'),
  (@b7, 17, 1, 'Ir buvo vyras iš Efraimo kalno, kurio vardas buvo Mikajas.'),
  (@b7, 17, 2, 'Ir jis tarė savo motinai: „Tūkstantis šimtas sidabro šekelių, kurie buvo paimti iš tavęs, dėl kurių tu prakeikei ir apie kuriuos taip pat kalbėjai man į ausis, štai tas sidabras yra pas mane; aš tai paėmiau. O jo motina tarė: „Būk VIEŠPATIES palaimintas, mano sūnau“.'),
  (@b7, 17, 3, 'Ir kai jis sugrąžino savo motinai tūkstantį šimtą sidabro šekelių, jo motina tarė: „Aš visiškai pašvenčiau tą sidabrą VIEŠPAČIUI iš savo rankos dėl savo sūnaus, kad būtų padarytas raižytas atvaizdas bei nulietas atvaizdas; todėl dabar grąžinu tai tau“.'),
  (@b7, 17, 4, 'Tačiau jis sugrąžino tuos pinigus savo motinai; o jo motina paėmė du šimtus sidabro šekelių ir davė juos liejikui, kuris iš jų padarė raižytą atvaizdą bei nulietą atvaizdą; ir jie buvo Mikajo namuose.'),
  (@b7, 17, 5, 'Ir tas vyras Mikajas turėjo dievų namus ir padarė efodą bei terafimą, ir įšventino vieną iš savo sūnų, kuris tapo jo kunigu.'),
  (@b7, 17, 6, 'Tomis dienomis nebuvo karaliaus Izraelyje, bet kiekvienas darė tai, kas buvo teisinga jo paties akyse.'),
  (@b7, 17, 7, 'Ir buvo vienas jaunuolis iš Judos Betliejaus, iš Judos šeimos, kuris buvo levitas, ir jis ten laikinai gyveno.'),
  (@b7, 17, 8, 'Ir tas vyras išėjo iš miesto, iš Judos Betliejaus, kad laikinai apsigyventų, kur ras vietos; ir keliaudamas jis atėjo į Efraimo kalną, prie Mikajo namų.'),
  (@b7, 17, 9, 'Ir Mikajas jam tarė: „Iš kur ateini?“ Ir jis jam tarė: „Aš esu levitas iš Judos Betliejaus ir einu, kad laikinai apsigyvenčiau, kur rasiu vietos“.'),
  (@b7, 17, 10, 'Ir Mikajas jam tarė: „Gyvenk pas mane ir būk man tėvas bei kunigas, o aš tau duosiu kasmet dešimt sidabro šekelių, eilutę drabužių ir prasimaitinimą“. Taip levitas įėjo.'),
  (@b7, 17, 11, 'Ir levitas sutiko gyventi pas tą vyrą; ir tas jaunuolis jam buvo kaip vienas iš jo sūnų.'),
  (@b7, 17, 12, 'Ir Mikajas įšventino levitą; ir tas jaunuolis tapo jo kunigu ir buvo Mikajo namuose.'),
  (@b7, 17, 13, 'Tada Mikajas tarė: „Dabar žinau, kad VIEŠPATS darys man gera, nes turiu levitą sau kunigu“.'),
  (@b7, 18, 1, 'Tomis dienomis nebuvo karaliaus Izraelyje; ir tomis dienomis danų gentis ieškojo sau paveldo, kur gyventų; nes iki tos dienos jiems nebuvo išpuolęs visas jų paveldas tarp Izraelio genčių.'),
  (@b7, 18, 2, 'Ir Dano vaikai išsiuntė iš savo šeimos penkis vyrus iš savo ribų, narsius vyrus, iš Coros ir Eštaolio, šalies išžvalgyti ir jos ištirti; ir jie jiems tarė: „Eikite, ištirkite tą šalį“; atėję į Efraimo kalną prie Mikajo namų jie ten apsinakvojo.'),
  (@b7, 18, 3, 'Būdami prie Mikajo namų jie pažino jaunuolio levito balsą; ir ten užsukę, jam tarė: „Kas tave čia atvedė? Ką čia veiki? Ką čia turi?“'),
  (@b7, 18, 4, 'Ir jis jiems tarė: „Taip ir taip Mikajas pasielgė su manimi ir mane pasamdė, ir aš esu jo kunigas“.'),
  (@b7, 18, 5, 'O jie jam tarė: „Paklausk Dievo patarimo, meldžiame tave, kad žinotume, ar mūsų kelias, kuriuo einame, bus sėkmingas“.'),
  (@b7, 18, 6, 'Ir kunigas jiems tarė: „Eikite ramybėje; VIEŠPATIES akivaizdoje yra jūsų kelias, kuriuo einate“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b7, 18, 7, 'Tada tie penki vyrai išėjo ir atėjo į Laišą ir pamatė jame esančią liaudį, kaip jie nerūpestingai gyveno pagal sidoniečių būdą, ramiai ir saugiai; ir nebuvo šalyje valdytojo, kuris juos kuo nors sugėdytų; ir jie buvo toli nuo sidoniečių ir nei su niekuo neturėjo jokių reikalų.'),
  (@b7, 18, 8, 'Ir jie atėjo pas savo brolius į Corą ir Eštaolį; o jų broliai jiems tarė: „Ką sakote?“'),
  (@b7, 18, 9, 'Ir jie tarė: „Kelkitės, kad eitume aukštyn prieš juos; nes mes matėme tą šalį, ir štai ji labai gera; o jūs tylite? Netingėkite eiti ir įeiti pasisavinti tą šalį.'),
  (@b7, 18, 10, 'Kai eisite, jūs ateisite pas saugią tautą ir į didelę šalį; nes Dievas ją davė į jūsų rankas; vietą, kurioje nieko netrūksta, kas yra žemėje“.'),
  (@b7, 18, 11, 'Ir iš ten, iš danų šeimos, iš Coros ir Eštaolio, ėjo šeši šimtai vyrų, apsirūpinusių karo ginklais.'),
  (@b7, 18, 12, 'Ir nuėję aukštyn jie stovyklavo Kirjat-Jearime, Judoje; todėl tą vietą vadino Mahanai-Danu iki šios dienos; štai jis yra už Kirjat-Jearimo.'),
  (@b7, 18, 13, 'O iš ten jie ėjo į Efraimo kalną ir atėjo iki Mikajo namų.'),
  (@b7, 18, 14, 'Tada tie penki vyrai, kurie ėjo Laišo šalies išžvalgyti, atsiliepdami sakė savo broliams: „Ar žinote, kad šituose namuose yra efodas, terafimas, raižytas atvaizdas ir lietas atvaizdas? Taigi dabar pagalvokite, ką jums reiktų daryti“.'),
  (@b7, 18, 15, 'Ir jie pasuko ten ir atėjo į jaunuolio levito namus – Mikajo namus, ir jį pasveikino.'),
  (@b7, 18, 16, 'Ir šeši šimtai vyrų, apsirūpinę karo ginklais, esantys iš Dano vaikų, sustojo prie vartų įėjimo.'),
  (@b7, 18, 17, 'O tie penki vyrai, ėjusieji šalies išžvalgyti, nuėjo aukštyn ir, ten įėję, paėmė raižytą atvaizdą, efodą, terafimą ir lietą atvaizdą; o kunigas stovėjo vartų įėjime su tais šešiais šimtais vyrų, apsirūpinusių karo ginklais.'),
  (@b7, 18, 18, 'Ir šitie įėjo į Mikajo namus ir atnešė drožtą atvaizdą, efodą, terafimą ir lietą atvaizdą. Tada kunigas jiems tarė: „Ką darote?“'),
  (@b7, 18, 19, 'O jie jam tarė: „Tylėk, užsidenk ranka savo burną ir eik su mumis, ir būk mums tėvu ir kunigu; ar tau geriau būti kunigu vieno žmogaus namams, ar būti kunigu genčiai ir šeimai Izraelyje?“'),
  (@b7, 18, 20, 'Ir nudžiugo kunigo širdis, ir jis paėmė efodą, terafimą bei raižytą atvaizdą ir ėjo tautos tarpe.'),
  (@b7, 18, 21, 'Taip jie pasisuko ir išėjo, ir pasistatė savo priešakyje mažylius, galvijus ir mantą.'),
  (@b7, 18, 22, 'O kai jie buvo gerai nutolę nuo Mikajo namų, tai vyrai, esantys namuose greta Mikajo namų, susirinko ir pasivijo Dano vaikus.'),
  (@b7, 18, 23, 'Ir jie šaukė Dano vaikams. O tie atgręžė savo veidus ir tarė Mikajui: „Kas tau yra, kad atėjai su tokiu būriu?“'),
  (@b7, 18, 24, 'Ir jis tarė: „Jūs atėmėte mano dievus, kuriuos aš padariau, bei kunigą ir nuėjote; ir ką gi daugiau beturiu? Ir kas gi tai yra, kad man sakote: „Kas tau yra?“'),
  (@b7, 18, 25, 'O Dano vaikai jam tarė: „Tenepasigirsta tarp mūsų tavo balso, kad pikti vyrai neužpultų tavęs ir tu neprarastum savo gyvybės su savo namiškių gyvybėmis“.'),
  (@b7, 18, 26, 'Ir Dano vaikai ėjo savo keliu; o Mikajas, matydamas, kad jie buvo jam per stiprūs, pasuko ir grįžo į savo namus.'),
  (@b7, 18, 27, 'Ir paėmę daiktus, kuriuos Mikajas buvo padirbęs, ir kunigą, kurį jis turėjo, jie atėjo į Laišą, pas ramią ir saugią tautą; ir iškapojo juos kalavijo ašmenimis, o miestą sudegino ugnimi.'),
  (@b7, 18, 28, 'Ir nebuvo gelbėtojo, nes jis buvo toli nuo Sidono, ir jie su niekuo neturėjo jokių reikalų; ir jis buvo slėnyje, esančiame prie Bet-Rehobo. Ir jie pastatė miestą ir apsigyveno jame.'),
  (@b7, 18, 29, 'Ir jie praminė tą miestą Dano vardu, pagal vardą Dano savo tėvo, kuris buvo gimęs Izraeliui; nors pirmiau to miesto vardas buvo Laišas.'),
  (@b7, 18, 30, 'Ir Dano vaikai pastatė raižytą atvaizdą; o Manaso sūnaus Geršomo sūnus Jonatanas, jis ir jo sūnūs, buvo kunigai Dano genčiai iki šalies nelaisvės dienos.'),
  (@b7, 18, 31, 'Ir jie pasistatė Mikajo raižytą atvaizdą, kurį jis padarė, visą tą laiką, kai Dievo namai buvo Šilojuje.'),
  (@b7, 19, 1, 'Ir įvyko tomis dienomis, kai nebuvo karaliaus Izraelyje, kad Efraimo kalno šone buvo laikinai apsigyvenęs vienas levitas, kuris ėmė sau sugulovę iš Judos Betliejaus.'),
  (@b7, 19, 2, 'O jo sugulovė prieš jį paleistuvavo ir pabėgo nuo jo į savo tėvo namus, į Judos Betliejų, ir ten išbuvo visus keturis mėnesius.'),
  (@b7, 19, 3, 'Ir pakilo jos vyras ir nuėjo jai iš paskos, kad jai palankiai kalbėtų, kad ją parsivestų; su savimi jis turėjo savo tarną ir pora asilų; ir ji įvedė jį į savo tėvo namus; ir tos panelės tėvas, jį pamatęs, džiaugėsi jį sutikdamas.'),
  (@b7, 19, 4, 'Ir jo uošvis, tos panelės tėvas, jį užlaikė; ir jis pasiliko pas jį tris dienas; taigi jie valgė ir gėrė, ir ten nakvojo.'),
  (@b7, 19, 5, 'Ir įvyko ketvirtąją dieną, jiems atsikėlus anksti ryte, jis pakilo išeiti; o tos panelės tėvas tarė savo žentui: „Pastiprink savo širdį duonos kąsniu, o paskui eikite sau“.'),
  (@b7, 19, 6, 'Ir jie susėdo, abu drauge valgė ir gėrė; nes panelės tėvas buvo sakęs tam vyrui: „Sutik, meldžiu tave, pasilik visą naktį ir tesilinksmina tavo širdis“.'),
  (@b7, 19, 7, 'Ir tam vyrui pakilus išeiti, jo uošvis prispyrė jį; todėl jis vėl ten nakvojo.'),
  (@b7, 19, 8, 'Ir jis atsikėlė anksti ryte, penktąją dieną, išeiti; o panelės tėvas tarė: „Meldžiu tave, pastiprink savo širdį“. Ir jie pasiliko iki popietės ir abu valgė.'),
  (@b7, 19, 9, 'O kai tas vyras pakilo išeiti, jis, jo sugulovė ir jo tarnas, tai jo uošvis, tos panelės tėvas, jam tarė: „Štai diena jau eina vakarop, meldžiu jus, pasilikite visą naktį; štai diena eina galop, nakvok čia, kad pasilinksmintų tavo širdis; o rytoj anksti atsikelkite į savo kelią, kad eitum namo“.'),
  (@b7, 19, 10, 'Bet tas vyras nenorėjo pasilikti tą naktį, bet pakilęs išėjo ir atėjo priešais Jebusą, kuris yra Jeruzalė; o su juo buvo du pabalnoti asilai, ir taip pat jo sugulovė buvo su juo.'),
  (@b7, 19, 11, 'Jiems esant prie Jebuso, diena buvo prie pabaigos; ir tarnas tarė savo šeimininkui: „Eikš, meldžiu tave, pasukime į šitą jebusiečių miestą ir pernakvokime jame“.'),
  (@b7, 19, 12, 'O jo šeimininkas jam tarė: „Mes nesuksime čia į miestą svetimšalių, nesančių iš Izraelio vaikų; mes pereisime į Gibėją“.'),
  (@b7, 19, 13, 'Ir jis tarė savo tarnui: „Eikš, prisiartinkime prie vienos iš tų vietovių, kad visą naktį nakvotume Gibėjoje arba Ramoje“.'),
  (@b7, 19, 14, 'Ir jie ėjo toliau ir leidosi savo keliu; ir saulė jiems nusileido jiems esant prie Gibėjos, priklausančios Benjaminui.'),
  (@b7, 19, 15, 'Ir ten jie pasuko, kad įeitų nakvoti Gibėjoje; ir įėjęs jis atsisėdo miesto gatvėje; nes nebuvo nei vieno, kuris juos paimtų į savo namus nakvoti.'),
  (@b7, 19, 16, 'O štai vakare ėjo iš savo darbo, iš lauko, senas vyras, kuris taip pat buvo iš Efraimo kalno; jis buvo laikinai apsigyvenęs Gibėjoje; bet tos vietos žmonės buvo benjaminai.'),
  (@b7, 19, 17, 'Ir pakėlęs akis, jis pamatė pakeleivį miesto gatvėje; ir senis tarė: „Kur eini ir iš kur ateini?“'),
  (@b7, 19, 18, 'Ir jis jam tarė: „Mes praeiname iš Judos Betliejaus link Efraimo kalno šono; iš ten aš esu; aš ėjau į Judos Betliejų, bet dabar einu į VIEŠPATIES namus; ir nėra nei vieno, kuris mane priimtų į namus.'),
  (@b7, 19, 19, 'Dar yra ir šiaudų, ir pašaro mūsų asilams; taip pat yra ir duonos bei vyno man, tavo tarnaitei ir jaunam vyrui, esančiam su tavo tarnais; nieko netrūksta“.'),
  (@b7, 19, 20, 'Ir senis tarė: „Ramybė tebūna su tavimi; tačiau visi tavo poreikiai tegula ant manęs; tik nenakvok gatvėje“.'),
  (@b7, 19, 21, 'Taigi jis įvedė jį į savo namus ir davė pašaro asilams; ir nusiplovę kojas, jie valgė ir gėrė.'),
  (@b7, 19, 22, 'Na, o jiems belinksminant savo širdis, štai miesto vyrai, Belialo sūnūs, apsupo namą, daužė į duris ir kalbėjo seniui, namų šeimininkui, sakydami: „Išvesk tą vyrą, kuris atvyko į tavo namus, kad jį pažintume“.'),
  (@b7, 19, 23, 'O tas vyras, namų šeimininkas, išėjo pas juos ir jiems tarė: „Ne, mano broliai, ne, meldžiu jus, nedarykite taip piktai; kadangi šitas vyras yra atėjęs į mano namus, nedarykite šios kvailystės“.'),
  (@b7, 19, 24, 'Štai yra mano dukra, mergelė, ir jo sugulovė; jas dabar išvesiu jums, jas žeminkite ir joms darykite, kas jums atrodo gerai; bet šitam vyrui nedarykite tokio bjauraus dalyko.'),
  (@b7, 19, 25, 'Bet tie vyrai nenorėjo jo klausyti; taigi tas vyras, paėmęs savo sugulovę, ją išvedė pas juos; ir jie pažino ją ir ją prievartavo visą naktį iki ryto; o aušrai brėkštant ją paleido.'),
  (@b7, 19, 26, 'Tada, rytui auštant, ta moteris atėjo ir parkrito prie durų to vyro namų, kur buvo jos viešpats, kol pasidarė šviesu.'),
  (@b7, 19, 27, 'Ir jos viešpats ryte atsikėlė, atidarė namų duris ir išėjo eiti savo keliu; ir štai ta moteris, jo sugulovė, buvo parkritusi ties namų durimis, o jos rankos buvo ant slenksčio.'),
  (@b7, 19, 28, 'Ir jis jai tarė: „Kelkis, eikime“. Bet niekas neatsakė. Tada tas vyras, užkėlęs ją ant asilo, pakilo ir vyko į savo vietą.'),
  (@b7, 19, 29, 'Ir atėjęs į savo namus, jis paėmė peilį ir, nutvėręs savo sugulovę, ją padalijo kartu su jos kaulais į dvylika gabalų ir ją išsiuntė į visas Izraelio ribas.'),
  (@b7, 19, 30, 'Ir buvo taip, kad visi tai matę sakė: „Nebuvo nieko tokio nei padaryta, nei regėta nuo tos dienos, kai Izraelio vaikai atėjo aukštyn iš Egipto šalies, iki šios dienos; tai apmąstykite, pasitarkite ir pasisakykite’“.'),
  (@b7, 20, 1, 'Tada išėjo visi Izraelio vaikai, ir susirinkimas susirinko kaip vienas žmogus nuo Dano iki Beer-Šebos su Gileado šalimi pas VIEŠPATĮ į Micpę.'),
  (@b7, 20, 2, 'Ir visos tautos, tai yra visų Izraelio genčių, vadai prisistatė Dievo tautos susirinkime – keturi šimtai tūkstančių pėstininkų, traukiančių kalaviją'),
  (@b7, 20, 3, '(na, o Benjamino vaikai išgirdo, kad Izraelio vaikai buvo atėję viršun į Micpę). Tada Izraelio vaikai tarė: „Sakykite, kaip įvyko šita nedorybė?“'),
  (@b7, 20, 4, 'Ir levitas, nužudytos moters vyras, atsakydamas tarė: „Aš su savo sugulove atėjau nakvoti į Gibėją, priklausančią Benjaminui.'),
  (@b7, 20, 5, 'O Gibėjos žmonės pakilo prieš mane ir naktį dėl manęs apsupo namus, ketindami mane nužudyti; ir mano sugulovę išprievartavo, kad ji mirė.'),
  (@b7, 20, 6, 'Ir aš paėmiau savo sugulovę, ją supjausčiau į gabalus ir išsiunčiau ją po visą Izraelio paveldo šalį; nes jie padarė nešvankybę ir beprotystę Izraelyje.'),
  (@b7, 20, 7, 'Štai visi esate Izraelio vaikai, duokite čia savo patarimą ir nutarkite“.'),
  (@b7, 20, 8, 'Ir visa tauta pakilo kaip vienas žmogus, sakydami: „Niekas iš mūsų neis į savo palapinę ir niekas iš mūsų nepasuksime į savo namus.'),
  (@b7, 20, 9, 'Bet dabar štai dalykas, kurį darysime Gibėjai: eisime aukštyn prieš ją pagal burtą;'),
  (@b7, 20, 10, 'ir paimsime iš visų Izraelio genčių po dešimt vyrų iš šimto, po šimtą iš tūkstančio ir po tūkstantį iš dešimt tūkstančių, kad atneštų maisto tautai, kuri, atėjusi į Benjamino Gibėją, padarytų pagal visą tą beprotystę, kurią jie padarė Izraelyje“.'),
  (@b7, 20, 11, 'Taip visi Izraelio vyrai, susijungę kaip vienas vyras, susirinko prieš tą miestą.'),
  (@b7, 20, 12, 'Ir Izraelio gentys išsiuntė vyrus po visą Benjamino gentį, sakydami: „Kokia yra ta nedorybė, kuri padaryta tarp jūsų?'),
  (@b7, 20, 13, 'Taigi dabar atiduokite mums tuos vyrus, Belialo vaikus, esančius Gibėjoje, kad juos užmuštume ir pašalintume pikta iš Izraelio“. Bet Benjamino vaikai nenorėjo klausyti savo brolių Izraelio vaikų balso;'),
  (@b7, 20, 14, 'bet Benjamino vaikai susirinko iš miestų į Gibėją, kad išeitų į mūšį prieš Izraelio vaikus.'),
  (@b7, 20, 15, 'Ir tuo metu Benjamino vaikų iš miestų buvo suskaičiuota dvidešimt šeši tūkstančiai vyrų, traukiančių kalaviją, neskaitant Gibėjos gyventojų, kurių buvo suskaičiuota septyni šimtai rinktinių vyrų.'),
  (@b7, 20, 16, 'Visos tos tautos tarpe buvo septyni šimtai rinktinių vyrų kairiarankių; kiekvienas galėjo mėtyti akmenis į plauką, nepramesdami pro šalį.'),
  (@b7, 20, 17, 'O Izraelio vaikų, neskaitant Benjamino vaikų, buvo suskaičiuota keturi šimtai tūkstančių vyrų, traukiančių kalaviją; tie visi buvo karo vyrai.'),
  (@b7, 20, 18, 'Ir Izraelio vaikai pakilę nuėjo aukštyn į Dievo namus ir klausė Dievo nutarimo, sakydami: „Kuris iš mūsų pirmas eis aukštyn į mūšį prieš Benjamino vaikus?“ Ir VIEŠPATS tarė: „Juda eis aukštyn pirmas“.'),
  (@b7, 20, 19, 'Ir Izraelio vaikai ryte atsikėlė ir stovyklavo prieš Gibėją.'),
  (@b7, 20, 20, 'Ir Izraelio vyrai išėjo į mūšį prieš Benjaminą; ir Izraelio vyrai išsirikiavo kovoti prieš juos Gibėjoje.'),
  (@b7, 20, 21, 'Ir Benjamino vaikai išėjo iš Gibėjos ir tą dieną sunaikino iki žemės iš izraelitų dvidešimt du tūkstančius vyrų.'),
  (@b7, 20, 22, 'O tauta, Izraelio vyrai, pasidrąsino ir vėl išsirikiavo mūšiui toje vietoje, kur jie buvo išsirikiavę pirmąją dieną'),
  (@b7, 20, 23, '(ir Izraelio vaikai, nuėję aukštyn, verkė VIEŠPATIES akivaizdoje iki vakaro ir klausė VIEŠPATIES patarimo, sakydami: „Ar man vėl eiti aukštyn į mūšį prieš mano brolio Benjamino vaikus?“ Ir VIEŠPATS tarė: „Eik aukštyn prieš jį“).'),
  (@b7, 20, 24, 'Ir antrąją dieną Izraelio vaikai prisiartino prieš Benjamino vaikus.'),
  (@b7, 20, 25, 'Ir Benjaminas antrąją dieną išėjo prieš juos iš Gibėjos ir vėl sunaikino iki žemės aštuoniolika tūkstančių vyrų iš Izraelio vaikų; tie visi traukė kalaviją.'),
  (@b7, 20, 26, 'Tada visi Izraelio vaikai ir visa tauta ėjo aukštyn ir atėjo į Dievo namus, ir verkė, ir sėdėjo VIEŠPATIES akivaizdoje, ir tą dieną pasninkavo iki vakaro, ir atnašavo deginamąsias atnašas ir taikos atnašas VIEŠPATIES akivaizdoje.'),
  (@b7, 20, 27, 'Ir Izraelio vaikai klausė VIEŠPATIES (nes tomis dienomis ten buvo Dievo Sandoros skrynia,'),
  (@b7, 20, 28, 'o Aarono sūnaus Eleazaro sūnus Finehasas tomis dienomis stovėjo priešais ją), sakydami: „Ar man dar kartą išeiti į mūšį prieš mano brolio Benjamino vaikus, ar man liautis?“ Ir VIEŠPATS tarė: „Eik aukštyn; nes rytoj juos atiduosiu į tavo ranką“.'),
  (@b7, 20, 29, 'Ir Izraelis išstatė tykotojus aplinkui Gibėją.'),
  (@b7, 20, 30, 'Ir trečiąją dieną Izraelio vaikai ėjo aukštyn prieš Benjamino vaikus ir, kaip kitais kartais, išsirikiavo prieš Gibėją.'),
  (@b7, 20, 31, 'Ir Benjamino vaikai išėjo prieš tautą ir atsitraukė nuo miesto; ir, kaip kitais kartais, jie pradėjo mušti iš tautos, žudyti ant vieškelių, kurių vienas veda aukštyn į Dievo namus, o kitas į Gibėją lauke, apie trisdešimt Izraelio vyrų.'),
  (@b7, 20, 32, 'Ir Benjamino vaikai sakė: „Jie mūsų akivaizdoje sumušti, kaip anksčiau“. Bet Izraelio vaikai sakė: „Bėkime ir atitraukime juos nuo miesto į vieškelius“.'),
  (@b7, 20, 33, 'Ir visi Izraelio vyrai pakilo iš savo vietos ir išsirikiavo Baal-Tamare; o Izraelio tykotojai išėjo iš savo vietų, tai yra iš Gibėjos pievų.'),
  (@b7, 20, 34, 'Ir prieš Gibėją atėjo dešimt tūkstančių rinktinių vyrų iš viso Izraelio, ir mūšis buvo smarkus; bet jie nežinojo, kad arti jų buvo nelaimė.'),
  (@b7, 20, 35, 'Ir VIEŠPATS sumušė Benjaminą Izraelio akivaizdoje; ir tą dieną Izraelio vaikai sunaikino iš benjaminų dvidešimt penkis tūkstančius ir šimtą vyrų; tie visi traukė kalaviją.'),
  (@b7, 20, 36, 'Taigi Benjamino vaikai pamatė, kad jie buvo sumušti; nes Izraelio vyrai davė benjaminams vietos, kadangi pasitikėjo tykotojais, kuriuos buvo pastatę šalia Gibėjos.'),
  (@b7, 20, 37, 'Ir tykotojai pasiskubino ir metėsi į Gibėją; ir tykotojai ėjo į priekį ir iškapojo visą miestą kalavijo ašmenimis.'),
  (@b7, 20, 38, 'Na, o buvo sutartas ženklas tarp Izraelio vyrų ir tykotojų, kad jie sukels didelę liepsną su dūmais, kylančiais iš miesto.'),
  (@b7, 20, 39, 'O kai Izraelio vyrai traukėsi iš mūšio, Benjaminas pradėjo smogti ir užmušė iš Izraelio vyrų apie trisdešimt asmenų; nes jie sakė: „Tikrai jie yra sumušti mūsų akivaizdoje, kaip pirmajame mūšyje“.'),
  (@b7, 20, 40, 'Bet kai pradėjo kilti iš miesto liepsna su dūmų stulpu, benjaminai pažvelgė atgal, ir štai miesto liepsna kilo į dangų.'),
  (@b7, 20, 41, 'Ir kai Izraelio vyrai atsigręžė, Benjamino vyrai buvo apstulbę; nes jie pamatė, kad juos ištiko nelaimė.'),
  (@b7, 20, 42, 'Taigi jie pasisuko prieš Izraelio vyrus savo nugaromis dykumos kelio link; bet mūšis pasivijo juos; o išėjusiuosius iš miestų, jie naikino savo tarpe.'),
  (@b7, 20, 43, 'Taip jie, apsupę benjaminus, vijosi juos ir lengvai juo trypė priešais Gibėją saulėtekio link.'),
  (@b7, 20, 44, 'Ir iš Benjamino krito aštuoniolika tūkstančių vyrų; visi šitie buvo narsūs vyrai.'),
  (@b7, 20, 45, 'Ir jie nusisukę bėgo dykumos link, iki Rimono uolos; ir jie vieškeliuose surankiojo iš jų penkis tūkstančius vyrų; ir vijosi juos įkandin iki Gidomo ir išžudė iš jų du tūkstančius vyrų.'),
  (@b7, 20, 46, 'Taip iš viso tų, kurie tą dieną krito iš Benjamino, buvo dvidešimt penki tūkstančiai vyrų, traukiančių kalaviją; visi šitie buvo narsūs vyrai.'),
  (@b7, 20, 47, 'Bet šeši šimtai vyrų nusisukę bėgo į dykumą iki Rimono uolos ir pasiliko Rimono uoloje keturis mėnesius.'),
  (@b7, 20, 48, 'O Izraelio vyrai sugrįžo pas Benjamino vaikus ir juos iškirto kalavijo ašmenimis, tiek kiekvieno miesto žmones, tiek gyvulius ir visa, kas pasitaikė po ranka; jie taip pat padegė visus miestus, į kuriuos atėjo.'),
  (@b7, 21, 1, 'Na, o Izraelio žmonės buvo prisiekę Micpėje, sakydami: „Nė vienas iš mūsų neduos savo dukters Benjaminui į žmonas“.'),
  (@b7, 21, 2, 'Ir tauta atėjo į Dievo namus ir ten pasiliko iki vakaro Dievo akivaizdoje, ir pakėlę savo balsus, smarkiai verkė;'),
  (@b7, 21, 3, 'ir sakė: „O VIEŠPATIE, Izraelio Dieve, kodėl tai įvyko Izraelyje, kad šiandien trūksta Izraelyje vienos genties?“'),
  (@b7, 21, 4, 'Ir įvyko rytojaus dieną, kad tauta anksti atsikėlė ir ten pastatė aukurą, ir atnašavo deginamąsias atnašas bei taikos atnašas.'),
  (@b7, 21, 5, 'Ir Izraelio vaikai tarė: „Kas iš visų Izraelio genčių neatėjo aukštyn su susirinkimu pas VIEŠPATĮ?“ Nes jie davė didelę priesaiką apie tą, kuris neateis aukštyn pas VIEŠPATĮ į Micpę, sakydami: „Jis tikrai bus užmuštas”.'),
  (@b7, 21, 6, 'Ir Izraelio vaikai gailėjosi jų brolio Benjamino ir sakė: „Šią dieną viena gentis yra iškirsta iš Izraelio.'),
  (@b7, 21, 7, 'Kaip mes darysime dėl žmonų tiems, kurie išlikę, kadangi esame prisiekę VIEŠPAČIU, kad jiems neduosime iš savo dukterų į žmonas“.'),
  (@b7, 21, 8, 'Ir jie tarė: „Katras iš Izraelio genčių, kuris neatėjo aukštyn pas VIEŠPATĮ į Micpę?“ Ir štai nei vienas neatvyko į stovyklą, į susirinkimą, iš Jabeš-Gileado.'),
  (@b7, 21, 9, 'Nes tauta buvo suskaičiuota, ir štai ten nebuvo nei vieno iš Jabeš-Gileado gyventojų.'),
  (@b7, 21, 10, 'Ir susirinkimas ten pasiuntė dvylika tūkstančių vyrų iš narsiausių ir jiems įsakė, sakydami: „Eikite ir iškapokite kalavijo ašmenimis Jabeš-Gileado gyventojus su moterimis ir vaikais.'),
  (@b7, 21, 11, 'Ir štai dalykas, kurį padarykite: visiškai sunaikinkite kiekvieną vyriškos lyties ir kiekvieną moterį, gulėjusią šalia vyro“.'),
  (@b7, 21, 12, 'Ir jie rado tarp Jabeš-Gileado gyventojų keturis šimtus jaunų mergelių, kurios nebuvo pažinusios jokio vyro, sugulant su vyriška lytimi; ir jie atvedė jas stovyklon į Šilojų, esantį Kanaano šalyje.'),
  (@b7, 21, 13, 'Ir visas susirinkimas pasiuntė kelis kalbėti Benjamino vaikams, esantiems Rimono uoloje, ir taikiai juos pasikviesti.'),
  (@b7, 21, 14, 'Ir tuo metu Benjaminas sugrįžo; ir jie davė jiems žmonų, kurias buvo palikę gyvas iš Jabeš-Gileado moterų; bet jiems neužteko jų.'),
  (@b7, 21, 15, 'Ir tauta gailėjosi Benjamino, nes VIEŠPATS padarė spragą Izraelio gentyse.'),
  (@b7, 21, 16, 'Tada susirinkimo vyresnieji tarė: „Kaip darysime dėl žmonų tiems, kurie išlikę, kadangi iš Benjamino moterys yra išnaikintos?“'),
  (@b7, 21, 17, 'Ir jie tarė: „Benjamino pabėgėliams turi būti paveldas, kad gentis nebūtų išnaikinta iš Izraelio.'),
  (@b7, 21, 18, 'Tačiau negalime jiems duoti žmonų iš savo dukterų; nes Izraelio vaikai buvo prisiekę, sakydami: ‘Tebūna prakeiktas, kas duos žmoną Benjaminui’“.'),
  (@b7, 21, 19, 'Tada jie tarė: „Štai yra metinė VIEŠPATIES šventė Šilojuje, vietoje, esančioje šiaurinėje Bet-Elio pusėje, rytinėje pusėje vieškelio, einančio iš Bet-Elio aukštyn į Šechemą, ir Lebonos pietuose“.'),
  (@b7, 21, 20, 'Taigi jie įsakė Benjamino vaikams, sakydami: „Nuėję tykokite vynuogynuose;'),
  (@b7, 21, 21, 'ir žiūrėkite, ir štai jei Šilojaus dukterys išeis šokių šokti, tada išeikite iš vynuogynų ir pasigaukite kiekvienas savo žmoną iš Šilojaus dukterų ir eikite į Benjamino šalį.'),
  (@b7, 21, 22, 'Ir bus, kai jų tėvai ar jų broliai ateis pas mus skųstis, tada mes jiems sakysime: ‘Būkite jiems malonūs dėl mūsų; nes mes neatidėjome kiekvienam jo žmonos kare; nes jūs nedavėte jiems šį kartą, kad jūs būtumėte kalti“.'),
  (@b7, 21, 23, 'Ir Benjamino vaikai taip padarė, ir ėmė sau žmonų pagal jų skaičių iš šokusių, kurias jie pasigavo; ir nuėję jie sugrįžo į savo paveldą, ir atstatė miestus, ir gyveno juose.'),
  (@b7, 21, 24, 'Ir tuo metu Izraelio vaikai iš ten išėjo, kiekvienas į savo gentį ir į savo šeimą, ir jie išėjo iš ten kiekvienas į savo paveldą.'),
  (@b7, 21, 25, 'Tomis dienomis nebuvo karaliaus Izraelyje: kiekvienas darė tai, kas buvo teisinga jo paties akyse.'),
  (@b8, 1, 1, 'Na, o tomis dienomis, kai valdė teisėjai, atsitiko, kad šalyje buvo badas. Ir vienas vyras iš Judos Betliejaus ėjo laikinai apsigyventi Moabo šalyje, jis, jo žmona ir jo abu sūnūs.'),
  (@b8, 1, 2, 'To vyro vardas buvo Elimelechas, jo žmonos vardas Naomė, o jo abiejų sūnų vardai Machlonas ir Kiljonas, efratai iš Judos Betliejaus. Ir jie atėjo į Moabo šalį ir ten pasiliko.'),
  (@b8, 1, 3, 'Ir mirė Elimelechas, Naomės vyras; ir ji pasiliko su savo abiem sūnumis.'),
  (@b8, 1, 4, 'Ir jie ėmė sau žmonas iš Moabo moterų; vienos vardas buvo Orpa, o kitos vardas Rūta; ir jie ten gyveno apie dešimtį metų.'),
  (@b8, 1, 5, 'Taip pat mirė tuodu, Machlonas ir Kiljonas; ir ta moteris liko be savo abiejų sūnų ir be savo vyro.'),
  (@b8, 1, 6, 'Tada ji pakilo su savo marčiomis grįžti iš Moabo šalies; nes ji girdėjo Moabo šalyje, kad VIEŠPATS aplankė savo tautą, duodamas jiems duonos.'),
  (@b8, 1, 7, 'Todėl ji išvyko iš tos vietos, kurioje ji buvo, ir abi jos marčios su ja; ir jos ėjo keliu, kad sugrįžtų į Judos šalį.'),
  (@b8, 1, 8, 'Ir Naomė tarė savo abiem marčioms: „Eikite, grįžkite kiekviena į savo motinos namus; VIEŠPATS tesielgia su jumis gerai, kaip jūs elgėtės su mirusiaisiais ir su manimi.'),
  (@b8, 1, 9, 'Teduoda VIEŠPATS jums, kad rastumėte poilsį kiekviena savo vyro namuose“. Tada ji pabučiavo jas; o jos pakeltu balsu verkė.'),
  (@b8, 1, 10, 'Ir jos tarė jai: „Mes tikrai norime grįžti su tavimi pas tavo tautą“.'),
  (@b8, 1, 11, 'O Naomė tarė: „Grįžkite, mano dukterys; kodėl norite eiti su manimi? Argi dar yra sūnų mano įsčiose, kad jie būtų jūsų vyrais?'),
  (@b8, 1, 12, 'Grįžkite, mano dukterys, eikite savo keliu, nes aš per sena turėti vyrą. Jei sakyčiau: ‘Aš turiu viltį, jei šiąnakt turėčiau vyrą ir dar pagimdyčiau sūnų;'),
  (@b8, 1, 13, 'argi lauktumėte jų, kol jie užaugs? Argi dėl jų susilaikytumėte ir neturėtumėte vyrų? Ne, mano dukterys; nes man labai skaudu dėl jūsų, kad VIEŠPATIES ranka yra išėjusi prieš mane’“.'),
  (@b8, 1, 14, 'Ir jos vėl pakeltu balsu verkė; ir Orpa pabučiavo savo anytą; bet Rūta prilipo prie jos.'),
  (@b8, 1, 15, 'Ir ji tarė: „Štai tavo brolienė sugrįžo pas savo tautą ir pas savo dievus; sugrįžk paskui savo brolienę“.'),
  (@b8, 1, 16, 'O Rūta tarė: „Nemaldauk manęs tave palikti ar kad sugrįžčiau nuo sekimo paskui tave; nes kur tu eisi, aš eisiu; ir kur tu apsigyvensi, aš apsigyvensiu; tavo tauta bus mano tauta, ir tavo Dievas – mano Dievas;'),
  (@b8, 1, 17, 'kur tu mirsi, aš mirsiu ir ten būsiu palaidota; tegul VIEŠPATS man padaro taip ir dar daugiau, jei ne mirtis atskirs mane nuo tavęs“.'),
  (@b8, 1, 18, 'Matydama, kad ji buvo tvirtai nusiteikusi eiti su ja, ji liovėsi jai kalbėjusi.'),
  (@b8, 1, 19, 'Taip jos abi ėjo, kol atėjo į Betliejų. Ir joms atėjus į Betliejų įvyko, kad visas miestas sujudo dėl jų, ir jie sakė: „Ar šita yra Naomė?“'),
  (@b8, 1, 20, 'O ji jiems tarė: „Nevadinkite manęs Naome, mane vadinkite Mara; nes Visagalis mane labai apkartino.'),
  (@b8, 1, 21, 'Aš išvykau pilnomis, o namo VIEŠPATS mane sugrąžino tuščiomis; tai kodėl vadinate mane Naome, kai tuo tarpu VIEŠPATS paliudijo prieš mane, Visagalis sukėlė man skausmą?“'),
  (@b8, 1, 22, 'Taip sugrįžo Naomė ir su ja moabietė Rūta, jos marti, kuri sugrįžo iš Moabo šalies; ir jos atvyko į Betliejų miežių pjūties pradžioje.'),
  (@b8, 2, 1, 'O Naomė turėjo savo vyro giminaitį, galingą turtuolį iš Elimelecho šeimos; o jo vardas buvo Boazas.'),
  (@b8, 2, 2, 'Ir moabietė Rūta tarė Naomei: „Leisk man dabar eiti į lauką ir rankioti javų varpas paskui tą, kurio akyse rasiu malonę“. O ji tarė jai: „Eik, mano dukra“.'),
  (@b8, 2, 3, 'Ir ji ėjo ir atėjusi rankiojo lauke paskui pjovėjus; ir jai netyčia pasitaikė užtikti dalį lauko, priklausančio Boazui, esančiam iš Elimelecho giminaičių.'),
  (@b8, 2, 4, 'Ir štai Boazas atėjo iš Betliejaus ir tarė pjovėjams: „VIEŠPATS tebūna su jumis“. O jie jam atsakė: „Telaimina tave VIEŠPATS“.'),
  (@b8, 2, 5, 'Tada Boazas tarė savo tarnui, paskirtam pjovėjams prižiūrėti: „Kieno šita panelė?“'),
  (@b8, 2, 6, 'O tas tarnas, paskirtas pjovėjams prižiūrėti, atsakė ir tarė: „Tai moabietė panelė, sugrįžusi su Naome iš Moabo šalies;'),
  (@b8, 2, 7, 'ir ji tarė: ‘Meldžiu tave, leisk man rankioti ir pasirinkti tarp pėdų paskui pjovėjus’; taigi ji atėjo ir pasiliko nuo ryto iki dabar, ji trumpai teužtruko namuose“.'),
  (@b8, 2, 8, 'Tada Boazas tarė Rūtai: „Ar negirdėjai, mano dukra? Neik į kitą lauką rankioti ir neik iš čia, bet laikykis čia prie mano tarnaičių;'),
  (@b8, 2, 9, 'tavo akys tebūna nukreiptos į lauką, kurį jie pjauna, ir eik paskui juos; argi neįpareigojau jaunų vyrų, kad jie tavęs neliestų? O ištroškusi nueik prie indų ir gerk iš to, ką jauni vyrai bus pasėmę“.'),
  (@b8, 2, 10, 'Tada ji parpuolė veidu žemyn ir nusilenkusi iki žemės jam tarė: „Kodėl radau malonę tavo akyse, kad manimi susidomėjai, nors aš esu svetimšalė?“'),
  (@b8, 2, 11, 'O Boazas jai atsakė ir tarė: „Man pilnai papasakota visa, ką esi padariusi savo anytai nuo tada, kai mirė tavo vyras; ir kaip tu, palikusi savo tėvą, savo motiną ir gimtąją šalį, atėjai pas tautą, kurios anksčiau nepažinojai.'),
  (@b8, 2, 12, 'Teatlygina tau VIEŠPATS už tavo darbą, ir pilnas užmokestis tebūna tau duodamas nuo VIEŠPATIES, Izraelio Dievo, po kurio sparnais atėjai pasitikėti“.'),
  (@b8, 2, 13, 'Tada ji tarė: „Leisk man rasti palankumą tavo akyse, mano viešpatie; nes tu mane paguodei ir draugiškai kalbėjai savo tarnaitei, nors aš ir nesu tokia, kaip viena iš tavo tarnaičių“.'),
  (@b8, 2, 14, 'O Boazas jai tarė: „Valgymo laiku prieik čia, valgyk duonos ir dažyk savo kąsnį acte“. Ir ji atsisėdo šalia pjovėjų; o jis ištiesė jai paskrudintų grūdų, ir ji valgė, ir pasisotino, ir paliko.'),
  (@b8, 2, 15, 'O jai atsikėlus rinkti, Boazas įsakė savo jaunuoliams, sakydamas: „Tegul ji renka ir tarp pėdų, ir nepriekaištaukite jai;'),
  (@b8, 2, 16, 'ir taip pat tegul tyčia krenta jai saujomis, ir palikite, kad ji tai susirinktų, ir nebarkite jos“.'),
  (@b8, 2, 17, 'Taip ji rinko ant lauko iki vakaro ir iškūlė, ką buvo surinkusi; ir buvo maždaug efa miežių.'),
  (@b8, 2, 18, 'Ir juos užsikėlusi ji nuėjo į miestą; o jos anyta pamatė, ką ji buvo surinkusi; ir ji ištraukė ir jai davė tai, ką buvo pasilaikiusi po to, kai pasisotino.'),
  (@b8, 2, 19, 'Ir jos anyta jai tarė: „Kur šiandien rinkai? Kur dirbai? Tebūna palaimintas tas, kuris susidomėjo tavimi“. Ir ji papasakojo savo anytai, pas ką ji dirbo, ir tarė: „To vyro, pas kurį šiandien dirbau, vardas yra Boazas“.'),
  (@b8, 2, 20, 'Ir Naomė tarė savo marčiai: „Tebūna jis palaimintas VIEŠPATIES, kuris neužmiršo savo gerumo gyviesiems ir mirusiems“. Ir Naomė jai tarė: „Tas vyras yra mums artimas giminaitis, vienas iš mūsų artimiausių giminaičių“.'),
  (@b8, 2, 21, 'O moabietė Rūta tarė: „Jis man dar sakė: ‘Laikykis šalia mano jaunų vyrų, kol jie pabaigs visą mano pjūtį’“.'),
  (@b8, 2, 22, 'Ir Naomė tarė savo marčiai Rūtai: „Tai yra gerai, mano dukra, kad išeini su jo tarnaitėmis, kad nesutiktų tavęs ant kokio kito lauko“.'),
  (@b8, 2, 23, 'Taip ji laikėsi šalia Boazo tarnaičių rinkdama iki miežių pjūties bei kviečių pjūties pabaigos; ir gyveno pas savo anytą.'),
  (@b8, 3, 1, 'Tada jos anyta Naomė jai tarė: „Mano dukra, argi neturėčiau tau paieškoti poilsio, kad tau gerai klotųsi?'),
  (@b8, 3, 2, 'O dabar, argi Boazas, su kurio tarnaitėmis buvai, nėra iš mūsų giminaičių? Štai jis šiąnakt vėtys miežius klojime.'),
  (@b8, 3, 3, 'Taigi nusiprausk, pasitepk, apsivilk drabužį ir eik žemyn į klojimą; bet nesiduok atpažįstama tam vyrui, iki jis bus baigęs valgyti ir gerti.'),
  (@b8, 3, 4, 'Ir bus, kai jis gulsis, įsidėmėk tą vietą, kur jis atsiguls, ir įėjusi atidenk jo kojas ir atsigulk; o jis tau pasakys, ką tau daryti“.'),
  (@b8, 3, 5, 'Ir ji jai tarė: „Darysiu viską, ką man sakai“.'),
  (@b8, 3, 6, 'Ir ji nuėjo žemyn į klojimą ir padarė pagal visa tai, ką jos anyta jai prisakė.'),
  (@b8, 3, 7, 'Ir kai Boazas pavalgė, atsigėrė, ir jo širdis buvo linksma, jis nuėjo atsigulti javų krūvos gale; o ji tyliai atėjo, atidengė jo kojas ir atsigulė.'),
  (@b8, 3, 8, 'Ir vidurnaktį įvyko, kad tas vyras išsigandęs pasisuko; ir štai moteris guli prie jo kojų.'),
  (@b8, 3, 9, 'Ir jis tarė: „Kas tu esi?“ O ji atsakė: „Aš esu tavo tarnaitė Rūta; todėl ištiesk savo skverną ant savo tarnaitės; nes tu esi artimas giminaitis.'),
  (@b8, 3, 10, 'Ir jis tarė: „Būk VIEŠPATIES palaiminta, mano dukra; nes tu parodei daugiau gerumo pabaigoje negu pradžioje, kadangi nenuėjai paskui jaunus vyrus, ar tai beturčius, ar turtingus.'),
  (@b8, 3, 11, 'O dabar, mano dukra, nebijok; aš tau padarysiu viską, ko prašai; nes visas mano tautos miestas žino, kad esi dorybinga moteris.'),
  (@b8, 3, 12, 'O dabar, yra tiesa, kad esu tavo artimas giminaitis; tačiau yra giminaitis, artimesnis už mane.'),
  (@b8, 3, 13, 'Pasilik šiąnakt, o ryte bus, jei jis tau atliks giminaičio pareigą, gerai; tegul jis atlieka giminaičio pareigą; bet jei jis tau neatliks giminaičio pareigos, tai, kaip VIEŠPATS gyvas, aš tau atliksiu giminaičio pareigą; gulėk iki ryto“.'),
  (@b8, 3, 14, 'Ir ji gulėjo prie jo kojų iki ryto; ir ji atsikėlė, kol dar negalėjo vienas kito atpažinti. Ir jis tarė: „Tenebūna žinoma, kad moteris buvo atėjusi į klojimą“.'),
  (@b8, 3, 15, 'Taip pat jis tarė: „Atnešk dangalą, kurį turi ant savęs, ir laikyk jį“. Ir kai ji laikė jį, jis atseikėjo šešis saikus miežių ir uždėjo tai ant jos; o ji nuėjo į miestą.'),
  (@b8, 3, 16, 'Ir jai parėjus pas savo anytą, ji tarė: „Kas tu esi, mano dukra?“ Ir ji papasakojo jai viską, ką tas vyras jai buvo padaręs.'),
  (@b8, 3, 17, 'Ir ji tarė: „Šituos šešis saikus miežių jis man davė; nes jis man sakė: ‘Neik tuščiomis pas savo anytą’“.'),
  (@b8, 3, 18, 'Tada ji tarė: „Sėdėk ramiai, mano dukra, kol sužinosi, kaip tas dalykas išpuls; nes tas vyras nenurims, kol neužbaigs to dalyko šią dieną.'),
  (@b8, 4, 1, 'Tada Boazas nuėjo aukštyn prie vartų ir ten atsisėdo; ir štai pro šalį ėjo tas giminaitis, apie kurį Boazas kalbėjo; kuriam jis tarė: „Ei, toks ir toks! Pasuk į šalį ir sėskis čia“. Ir jis pasukęs į šalį, atsisėdo.'),
  (@b8, 4, 2, 'Ir paėmęs dešimt vyrų iš miesto vyresniųjų, jis tarė: „Sėskitės čia!“ Ir jie atsisėdo.'),
  (@b8, 4, 3, 'Ir jis tarė giminaičiui: „Naomė, kuri grįžo iš Moabo šalies, parduoda žemės sklypą, buvusį mūsų brolio Elimelecho;'),
  (@b8, 4, 4, 'ir aš pagalvojau tau paskelbti, sakydamas: „Nupirk jį gyventojų akivaizdoje ir mano tautos vyresniųjų akivaizdoje. Jei nori jį išpirkti, išpirk; bet jei nenori jo išpirkti, tai pasakyk man, kad žinočiau; nes be tavęs nėra nei vieno, kuris jį išpirktų; o aš esu po tavęs“. Ir jis tarė: „Aš jį išpirksiu“.'),
  (@b8, 4, 5, 'Tada Boazas tarė: „Tą dieną, kai pirksi lauką iš Naomės rankų, turėsi jį pirkti ir iš moabietės Rūtos, mirusiojo žmonos, kad prikeltum mirusiojo vardą jo paveldui“.'),
  (@b8, 4, 6, 'O tas giminaitis tarė: „Negaliu tai sau išpirkti, kad nepakenkčiau savo paties paveldui; tu išpirk mano teisę sau; nes aš negaliu to išpirkti“.'),
  (@b8, 4, 7, 'Na, o toks seniau Izraelyje buvo paprotys dėl atpirkimo ir dėl mainymo, kad patvirtintų kiekvieną dalyką: vienas nusiaudavo apavą ir paduodavo jį savo artimui; ir tai buvo liudijimas Izraelyje.'),
  (@b8, 4, 8, 'Todėl tas giminaitis tarė Boazui: „Pirk tai sau“. Taigi jis nusiavė apavą.'),
  (@b8, 4, 9, 'Ir Boazas tarė vyresniesiems ir visai tautai: „Jūs šią dieną esate liudytojai, kad aš nupirkau iš Naomės rankų viską, kas buvo Elimelecho, ir viską, kas buvo Kiljono ir Machlono.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b8, 4, 10, 'Be to, moabietę Rūtą, Machlono žmoną, nupirkau, kad būtų mano žmona, kad prikelčiau mirusiojo vardą jo paveldui, kad mirusiojo vardas nebūtų iškirstas iš jo brolių tarpo ir iš jo vietovės vartų; jūs šią dieną esate liudytojai“.'),
  (@b8, 4, 11, 'Ir visa tauta, esanti vartuose, ir vyresnieji sakė: „Mes esame liudytojai. VIEŠPATS tepadaro moterį, ateinančią į tavo namus, kaip Rachelę ir kaip Lėją, kurios abi pastatė Izraelio namus; o tu tapk elkis garbingai Efratoje ir būk garsus Betliejuje;'),
  (@b8, 4, 12, 'ir tebūna tavo namai kaip namai Pereso, kurį Tamara pagimdė Judai, iš tos sėklos, kurią VIEŠPATS tau duos iš šitos jaunos moters“.'),
  (@b8, 4, 13, 'Taip Boazas ėmė Rūtą, ir ji buvo jo žmona; ir jam įėjus pas ją, VIEŠPATS suteikė jai pastojimą, ir ji pagimdė sūnų.'),
  (@b8, 4, 14, 'Ir moterys tarė Naomei: „Tebūna palaimintas VIEŠPATS, kuris šią dieną nepaliko tavęs be giminaičio, kad jo vardas būtų garsus Izraelyje.'),
  (@b8, 4, 15, 'Ir jis tau bus tavo gyvybės atgaivintojas ir maitintojas tavo senatvėje; nes jį pagimdė tavo marti, kuri myli tave, kuri tau geresnė nei septyni sūnūs“.'),
  (@b8, 4, 16, 'Ir paėmusi vaiką, Naomė jį paguldė į savo glėbį ir tapo jam aukle.'),
  (@b8, 4, 17, 'Ir jos kaimynės moterys davė jam vardą, sakydamos: „Sūnus gimė Naomei“; ir jos praminė jį Obedo vardu; jis yra Dovydo tėvo Jesės tėvas.'),
  (@b8, 4, 18, 'Na, o šita yra Pereso genealogija: Peresas pagimdė Hecroną,'),
  (@b8, 4, 19, 'o Hecronas pagimdė Ramą, o Ramas pagimdė Aminadabą,'),
  (@b8, 4, 20, 'o Aminadabas pagimdė Nachšoną, o Nachšonas pagimdė Salmoną,'),
  (@b8, 4, 21, 'o Salmonas pagimdė Boazą, o Boazas pagimdė Obedą,'),
  (@b8, 4, 22, 'o Obedas pagimdė Jesę, o Jesė pagimdė Dovydą.'),
  (@b9, 1, 1, 'Na, o buvo vienas vyras iš Ramataim-Cofimo, iš Efraimo kalno, kurio vardas buvo Elkana, Cūfo sūnaus Tohuvo sūnaus Elihuvo sūnaus Jerohamo sūnus, efratietis;'),
  (@b9, 1, 2, 'ir jis turėjo dvi žmonas: vienos vardas buvo Ona, o kitos vardas – Penina; Penina turėjo vaikų, bet Ona neturėjo vaikų.'),
  (@b9, 1, 3, 'Ir tas vyras kasmet eidavo aukštyn iš savo miesto garbinti ir aukoti kariuomenių VIEŠPAČIUI Šilojuje. Ir ten buvo du Elio sūnūs, Hofnis ir Finehasas, VIEŠPATIES kunigai.'),
  (@b9, 1, 4, 'Ir kuomet buvo laikas, kai Elkana atnašavo, jis davė dalis savo žmonai Peninai ir visiems jos sūnums bei jos dukterims;'),
  (@b9, 1, 5, 'bet Onai jis davė prideramą dalį; nes jis mylėjo Oną; bet VIEŠPATS uždarė jos įsčias.'),
  (@b9, 1, 6, 'Ir jos priešininkė taip pat ją labai kurstė, kad ją suerzintų, kadangi VIEŠPATS buvo užrakinęs jos įsčias.'),
  (@b9, 1, 7, 'Ir kai jis taip darydavo kas metai, kada ji eidavo aukštyn į VIEŠPATIES namus, anoji taip ją kurstydavo; todėl ji verkdavo ir nevalgydavo.'),
  (@b9, 1, 8, 'Tada jos vyras Elkana jai tarė: „Ona, kodėl verki ir kodėl nevalgai? Ko liūdi tavo širdis? Argi aš nesu tau geresnis už dešimtį sūnų?“'),
  (@b9, 1, 9, 'Taigi jiems pavalgius ir jiems atsigėrus Šilojuje, Ona atsikėlė. Na, o kunigas Elis sėdėjo krėsle prie VIEŠPATIES šventyklos staktos.'),
  (@b9, 1, 10, 'O ji buvo apkartusia siela ir meldėsi VIEŠPAČIUI ir labai verkė.'),
  (@b9, 1, 11, 'Ir ji davė įžadą, sakydama: „O, kariuomenių VIEŠPATIE, jei tikrai pažvelgsi į savo tarnaitės sielvartą, mane atsiminsi ir nepamirši savo tarnaitės, bet duosi savo tarnaitei vyriškos lyties vaiką, tai aš jį duosiu VIEŠPAČIUI per visas jo gyvenimo dienas, ir skustuvas neužeis ant jo galvos“.'),
  (@b9, 1, 12, 'Ir įvyko, kai ji pasiliko besimelsdama VIEŠPATIES akivaizdoje, Elis stebėjo jos burną.'),
  (@b9, 1, 13, 'Na, o Ona kalbėjo savo širdyje; tik jos lūpos judėjo, bet jos balso nesigirdėjo; todėl Elis pamanė ją esant girtą.'),
  (@b9, 1, 14, 'Ir Elis tarė jai: „Kaip ilgai būsi girta? Pašalink savo vyną nuo savęs“.'),
  (@b9, 1, 15, 'O Ona atsakydama tarė: „Ne, mano viešpatie, aš esu sielvartingos dvasios moteris; aš negėriau nei vyno, nei stipraus gėrimo, bet išliejau savo sielą VIEŠPATIES akivaizdoje.'),
  (@b9, 1, 16, 'Nelaikyk savo tarnaitės Belialo dukterimi, nes iš gausos savo nusiskundimo ir sielvarto iki šiol kalbėjau“.'),
  (@b9, 1, 17, 'Tada Elis atsakė ir tarė: „Eik ramybėje; o Izraelio Dievas patenkins tavo prašymą, ko tu jo prašei“.'),
  (@b9, 1, 18, 'Ir ji tarė: „Teranda tavo tarnaitė malonę tavo akyse“. Taip ta moteris nuėjo savo keliu ir valgė, ir jos veidas nebebuvo liūdnas.'),
  (@b9, 1, 19, 'Ir ankstų rytą atsikėlę ir pagarbinę VIEŠPATIES akivaizdoje, jie grįžo ir atėjo į savo namus, į Ramą; ir Elkana pažino savo žmoną Oną; ir VIEŠPATS atsiminė ją.'),
  (@b9, 1, 20, 'Taigi įvyko, kai praėjo laikas po Onos pastojimo, ji pagimdė sūnų ir praminė jį Samuelio vardu, sakydama: „Nes iš VIEŠPATIES jo prašiau“.'),
  (@b9, 1, 21, 'Ir tas vyras Elkana su visais savo namais ėjo aukštyn atnašauti VIEŠPAČIUI metinę auką ir savo įžadą.'),
  (@b9, 1, 22, 'Bet Ona nėjo aukštyn; nes ji sakė savo vyrui: „Aš neisiu aukštyn, iki vaikas bus nujunkytas, ir paskui jį nuvesiu, kad jis pasirodytų VIEŠPATIES akivaizdoje ir ten pasiliktų per amžius“.'),
  (@b9, 1, 23, 'O jos vyras Elkana jai tarė: „Daryk, kaip tau atrodo gerai; pasilik, iki būsi jį nujunkiusi; tik VIEŠPATS teįtvirtina savo žodį“. Taip ta moteris pasiliko ir žindė savo sūnų, kol jį nujunkė.'),
  (@b9, 1, 24, 'O kai ji buvo jį nujunkiusi, pasiėmė jį su savimi, su trimis jaučiais, viena efa miltų ir vyno indu, ir atvedė jį į VIEŠPATIES namus Šilojuje; o vaikas buvo jaunutėlis.'),
  (@b9, 1, 25, 'Ir jie papjovė jautį ir atvedė vaiką pas Elį.'),
  (@b9, 1, 26, 'Ir ji tarė: „O, mano viešpatie, kaip tavo siela gyva, mano viešpatie, aš esu ta moteris, kuri čia stovėjo šalia tavęs, melsdamasi VIEŠPAČIUI.'),
  (@b9, 1, 27, 'Šito vaiko aš meldžiau; ir VIEŠPATS patenkino mano prašymą, ko jo prašiau;'),
  (@b9, 1, 28, 'todėl ir aš paskolinau jį VIEŠPAČIUI; kol jis gyvens, jis bus paskolintas VIEŠPAČIUI“. Ir jis ten garbino VIEŠPATĮ.'),
  (@b9, 2, 1, 'Ir Ona melsdamasi tarė: „Mano širdis džiaugiasi VIEŠPATYJE, mano ragas išaukštintas VIEŠPATYJE; mano burna plačiai atsivėrė prieš mano priešus; nes džiaugiuosi tavo išgelbėjimu.'),
  (@b9, 2, 2, 'Niekas nėra šventas, kaip VIEŠPATS; nes be tavęs nėra kito; ir nėra kitos uolos, kaip mūsų Dievas.'),
  (@b9, 2, 3, 'Nebekalbėkite taip nepaprastai išdidžiai; teneišeina įžūlumas iš jūsų burnos; nes VIEŠPATS yra pažinojimo Dievas, ir jis pasveria darbus.'),
  (@b9, 2, 4, 'Galiūnų lankai sulaužomi, o tie, kurie suklumpa, yra apjuosiami jėga.'),
  (@b9, 2, 5, 'Kurie buvo sotūs, parsisamdė už duoną; o alkanųjų nebeliko; taip, kad nevaisingoji pagimdė septynis; o turinti daug vaikų nusilpo.'),
  (@b9, 2, 6, 'VIEŠPATS nužudo ir atgaivina; jis nuveda žemyn į kapą ir atveda aukštyn.'),
  (@b9, 2, 7, 'VIEŠPATS padaro beturtį ir padaro turtingą; jis nužemina ir išaukština.'),
  (@b9, 2, 8, 'Jis pakelia iš dulkių beturtį ir iš mėšlo krūvos išaukština elgetą, kad juos pasodintų tarp kunigaikščių ir duotų jiems paveldėti šlovės sostą; nes žemės stulpai yra VIEŠPATIES, ir ant jų jis pastatė pasaulį.'),
  (@b9, 2, 9, 'Jis apsaugos savo šventųjų kojas, o nedorėliai tylės tamsoje; nes jėga nei vienas žmogus nenugalės.'),
  (@b9, 2, 10, 'VIEŠPATIES priešininkai bus sutrupinti; jis griaudės ant jų iš dangaus; VIEŠPATS teis žemės pakraščius; jis duos stiprybės savo karaliui ir išaukštins savo pateptojo ragą“.'),
  (@b9, 2, 11, 'Ir Elkana ėjo į Ramą, į savo namus. O tas vaikas tarnavo VIEŠPAČIUI kunigo Elio akivaizdoje.'),
  (@b9, 2, 12, 'Na, o Elio sūnūs buvo Belialo sūnūs – jie nepažino VIEŠPATIES.'),
  (@b9, 2, 13, 'Ir tų kunigų paprotys su tauta buvo, kad, kai kas nors atnašaudavo auką, kai mėsa tebevirdavo, ateidavo kunigo tarnas su trišake mėsos šakute savo rankoje;'),
  (@b9, 2, 14, 'ir įsmeigdavo ją į kaistuvą ar į katilą, ar į virintuvą, ar į puodą; viską, ką iškeldavo mėsos šakutė, pasiimdavo kunigas. Taip jie darė Šilojuje visiems izraelitams, kurie ten ateidavo.'),
  (@b9, 2, 15, 'Be to, prieš jiems sudeginant taukus, kunigo tarnas ateidavo ir sakydavo tam, kuris aukoja: „Duok mėsos, pakepti kunigui; nes jis neims iš tavęs virtos mėsos, tik žalią“.'),
  (@b9, 2, 16, 'O jei jam kas sakydavo: „Tegul jie dabar sudegina taukus, o paskui pasiimk, kiek geidžia tavo siela“; tada jis jam atsakydavo: „Ne; dabar man ją duok; o jei ne, paimsiu ją prievarta“.'),
  (@b9, 2, 17, 'Todėl tų jaunuolių nuodėmė buvo labai didelė VIEŠPATIES akivaizdoje; nes žmonės bjaurėjosi VIEŠPATIES atnaša.'),
  (@b9, 2, 18, 'Bet Samuelis tarnavo VIEŠPATIES akivaizdoje būdamas vaikas, apsijuosęs lininiu efodu.'),
  (@b9, 2, 19, 'Be to, jo motina jam padarydavo mažą apsiaustą ir kasmet jam jį atnešdavo, ateidama aukštyn su savo vyru metinės aukos atnašauti.'),
  (@b9, 2, 20, 'Ir Elis laimino Elkaną ir jo žmoną, ir tarė: „VIEŠPATS tau teduoda sėklą iš šitos moters už paskolą, kuri yra paskolinta VIEŠPAČIUI“. Ir jie ėjo į savo namus.'),
  (@b9, 2, 21, 'Ir VIEŠPATS aplankė Oną, jog ji pastojo ir pagimdė tris sūnus ir dvi dukteris. O tas vaikas Samuelis augo VIEŠPATIES akivaizdoje.'),
  (@b9, 2, 22, 'Na, o Elis buvo labai senas ir girdėjo viską, ką jo sūnūs darė visam Izraeliui; ir kaip jie suguldavo su moterimis, kurios susirinkdavo prie Susirinkimo padangtės durų.'),
  (@b9, 2, 23, 'Ir jis jiems tarė: „Kodėl darote tokius dalykus? Nes aš girdžiu iš visos šitos tautos apie jūsų piktus darbus.'),
  (@b9, 2, 24, 'Ne, mano sūnūs; nes tai yra negeras gandas, kurį girdžiu; jūs skatinate VIEŠPATIES tautą nusižengti.'),
  (@b9, 2, 25, 'Jei vienas nusideda prieš kitą, teisėjas jį teis; bet jei kas nusideda prieš VIEŠPATĮ, kas už jį maldaus?“ Tačiau jie neklausė savo tėvo balso, nes VIEŠPATS norėjo juos nužudyti.'),
  (@b9, 2, 26, 'O vaikas Samuelis vis augo ir turėjo palankumą ir pas VIEŠPATĮ, ir pas žmones.'),
  (@b9, 2, 27, 'Ir Dievo vyras atėjo pas Elį ir jam tarė: „Taip sako VIEŠPATS: ‘Ar aš aiškiai pasirodžiau tavo tėvo namams, kai jie buvo Egipte, faraono namuose?'),
  (@b9, 2, 28, 'Ar aš jį išsirinkau iš visų Izraelio genčių būti mano kunigu, kad atnašautų ant mano aukuro, kad degintų smilkalus, kad nešiotų efodą mano akivaizdoje? Ar aš daviau tavo tėvo namams visas Izraelio vaikų ugnies atnašas?'),
  (@b9, 2, 29, 'Kodėl spardote mano auką ir mano atnašą, kuriuos įsakiau savo buveinėje; ir kodėl gerbi savo sūnus labiau už mane, kad penėtumėtės pačiomis geriausiomis iš visų mano tautos Izraelio atnašų?’'),
  (@b9, 2, 30, 'Todėl VIEŠPATS, Izraelio Dievas, sako: ‘Aš tikrai sakiau, kad tavo namai ir tavo tėvo namai turi vaikščioti mano akivaizdoje per amžius’; bet dabar VIEŠPATS sako: ‘Tai tebūna toli nuo manęs; nes tuos, kurie mane gerbia, aš pagerbsiu, o tie, kurie mane niekina, bus paniekinti.'),
  (@b9, 2, 31, 'Štai ateina dienos, kai nukirsiu tavo ranką ir tavo tėvo namų ranką, kad nebus seno žmogaus tavo namuose.'),
  (@b9, 2, 32, 'Ir tu matysi priešą mano buveinėje, visuose turtuose, kuriuos Dievas duos Izraeliui; ir per amžius nebus seno žmogaus tavo namuose.'),
  (@b9, 2, 33, 'O tavo žmogus, kurio neatkirsiu nuo savo aukuro, bus tam, kad temdytų tavo akis ir liūdintų tavo širdį; ir visas tavo namų prieaugis mirs pačiame savo jėgų žydėjime.'),
  (@b9, 2, 34, 'O tai, kas atsitiks abiems tavo sūnums, Hofniui ir Finehasui, bus tau ženklas: tą pačią dieną jie abu mirs.'),
  (@b9, 2, 35, 'O aš sau prikelsiu ištikimą kunigą, kuris darys pagal tai, kas yra mano širdyje ir mano mintyse; ir aš jam pastatysiu tvirtus namus; ir jis vaikščios mano pateptojo akivaizdoje per amžius.'),
  (@b9, 2, 36, 'Ir įvyks, kad, kas tik bus išlikęs tavo namuose, ateis ir nusilenks prieš jį už sidabrinį ir duonos kąsnelį ir tars: Paskirk mane, meldžiu tave, į vieną iš kunigų pareigų, kad valgyčiau gabalėlį duonos’“.'),
  (@b9, 3, 1, 'Ir vaikas Samuelis tarnavo VIEŠPAČIUI Elio akivaizdoje. O VIEŠPATIES žodis buvo brangus tomis dienomis; nebuvo atviro regėjimo.'),
  (@b9, 3, 2, 'Ir įvyko tuo metu, kai Elis gulėjo savo vietoje, ir jo akys buvo pradėjusios temti, kad jis negalėjo matyti;'),
  (@b9, 3, 3, 'o Samuelis buvo atsigulęs miegoti, kol Dievo žibintas dar nebuvo užgesęs VIEŠPATIES šventykloje, kur buvo Dievo skrynia;'),
  (@b9, 3, 4, 'VIEŠPATS pašaukė Samuelį; o jis atsakė: „Aš čia“.'),
  (@b9, 3, 5, 'Ir nubėgęs pas Elį, jis tarė: „Aš čia; nes mane šaukei“. O jis tarė: „Aš nešaukiau; eik atgal gultis“. Ir nuėjęs jis atsigulė.'),
  (@b9, 3, 6, 'Ir VIEŠPATS vėl pašaukė: „Samueli!“ Ir atsikėlęs Samuelis nuėjo pas Elį ir tarė: „Aš čia; nes mane šaukei“. O jis atsakė: „Aš nešaukiau, mano sūnau; eik atgal gultis“.'),
  (@b9, 3, 7, 'Na, o Samuelis dar nebuvo pažinęs VIEŠPATIES, ir jam dar nebuvo apreikštas VIEŠPATIES žodis.'),
  (@b9, 3, 8, 'Ir VIEŠPATS trečią kartą vėl pašaukė Samuelį. Ir atsikėlęs jis nuėjo pas Elį ir tarė: „Aš čia; nes mane šaukei“. Ir Elis suprato, kad VIEŠPATS šaukė vaiką.'),
  (@b9, 3, 9, 'Todėl Elis tarė Samueliui: „Eik, atsigulk; ir bus, jei jis tave pašauks, tai tu sakyk: ‘Kalbėk, VIEŠPATIE, nes tavo tarnas klauso‘.“ Taigi Samuelis nuėjęs atsigulė į savo vietą.'),
  (@b9, 3, 10, 'Ir VIEŠPATS atėjo, atsistojo ir pašaukė, kaip anais kartais: „Samueli, Samueli!“ Tada Samuelis atsiliepė: „Kalbėk, nes tavo tarnas klauso“.'),
  (@b9, 3, 11, 'Ir VIEŠPATS tarė Samueliui: „Štai aš darysiu Izraelyje dalyką, nuo kurio kiekvienam, kuris tai išgirs, spengs abi ausys.'),
  (@b9, 3, 12, 'Tą dieną įvykdysiu prieš Elį viską, ką esu kalbėjęs apie jo namus; kai aš pradedu, aš ir pabaigiu.'),
  (@b9, 3, 13, 'Nes jam sakiau, kad nuteisiu jo namus visam laikui dėl neteisybės, apie kurią jis žino; dėl to, kad jo sūnūs apsibjaurino, o jis jų nesulaikė.'),
  (@b9, 3, 14, 'Ir todėl prisiekiau Elio namams, kad Elio namų neteisybė per amžius nebus apvalyta nei auka, nei atnaša’“.'),
  (@b9, 3, 15, 'Ir Samuelis gulėjo iki ryto ir atidarė VIEŠPATIES namų duris. Ir Samuelis bijojo paskelbti Eliui tą regėjimą.'),
  (@b9, 3, 16, 'Tada Elis, pasišaukęs Samuelį, tarė: „Samueli, mano sūnau“. Ir jis atsakė: „Aš čia“.'),
  (@b9, 3, 17, 'Ir jis tarė: „Koks tas dalykas, kurį VIEŠPATS tau kalbėjo? Meldžiu tave, nenuslėpk jo nuo manęs; Dievas tepadaro tau tai ir dar daugiau, jei ką nuslėpsi nuo manęs iš visų tų dalykų, kuriuos jis tau kalbėjo“.'),
  (@b9, 3, 18, 'Ir Samuelis jam išpasakojo viską ir nieko nuo jo nenuslėpė. Ir jis tarė: „Tai VIEŠPATS; tegul jis daro, kas jam atrodo gera“.'),
  (@b9, 3, 19, 'O Samuelis augo, ir VIEŠPATS buvo su juo ir neleido nei vienam iš savo žodžių nukristi žemėn.'),
  (@b9, 3, 20, 'Ir visas Izraelis nuo Dano iki Beer-Šebos žinojo, kad Samuelis buvo patvirtintas būti VIEŠPATIES pranašu.'),
  (@b9, 3, 21, 'Ir VIEŠPATS vėl pasirodė Šilojuje; nes VIEŠPATS apsireiškė Samueliui Šilojuje VIEŠPATIES žodžiu.'),
  (@b9, 4, 1, 'Ir Samuelio žodis atėjo į visą Izraelį. Na, o Izraelis išėjo prieš filistinus į mūšį ir stovyklavo prie Eben-Ezero; o filistinai stovyklavo Afeke.'),
  (@b9, 4, 2, 'Ir filistinai išsirikiavo prieš Izraelį; ir kai jie stojo į mūšį, Izraelis buvo sumuštas filistinų akivaizdoje; ir jie išmušė lauke iš kariuomenės apie keturis tūkstančius vyrų.'),
  (@b9, 4, 3, 'Ir tautai parėjus į stovyklą, Izraelio vyresnieji sakė: „Kodėl VIEŠPATS mus šiandien sumušė filistinų akivaizdoje? Atneškime iš Šilojaus pas save VIEŠPATIES Sandoros skrynią, kad ji, atėjusi į mūsų tarpą, išgelbėtų mus iš mūsų priešų rankos“.'),
  (@b9, 4, 4, 'Taigi tauta pasiuntė į Šilojų, kad jie iš ten atneštų kariuomenių VIEŠPATIES, gyvenančio tarp kerubų, Sandoros skrynią; o abu Elio sūnūs, Hofnis ir Finehasas, buvo prie Dievo Sandoros skrynios.'),
  (@b9, 4, 5, 'Ir kai VIEŠPATIES Sandoros skrynia atėjo į stovyklą, visas Izraelis šaukė tokiu dideliu šauksmu, kad žemė aidėjo.'),
  (@b9, 4, 6, 'Ir išgirdę šauksmo garsą, filistinai tarė: „Ką reiškia šito didelio šauksmo garsas hebrajų stovykloje?“ Ir jie suprato, kad VIEŠPATIES skrynia buvo atėjusi į stovyklą.'),
  (@b9, 4, 7, 'Ir filistinai išsigando, nes jie tarė: „Dievas yra atėjęs į stovyklą“. Ir jie sakė: „Vargas mums! Nes anksčiau nėra buvę tokio dalyko.'),
  (@b9, 4, 8, 'Vargas mums! Kas mus išgelbės iš šitų galingų Dievų rankos? Šitie yra Dievai, kurie smogė egiptiečiams visomis rykštėmis dykumoje.'),
  (@b9, 4, 9, 'Būkite stiprūs ir elkitės kaip vyrai, o filistinai, kad nebūtumėte tarnai hebrajams, kaip jie jums buvo; elkitės kaip vyrai ir kovokite“.'),
  (@b9, 4, 10, 'Ir filistinai kovojo, ir Izraelis buvo sumuštas, ir jie bėgo kiekvienas į savo palapinę; ir buvo labai didelės žudynės, nes iš Izraelio krito trisdešimt tūkstančių pėstininkų.'),
  (@b9, 4, 11, 'Ir Dievo skrynia buvo paimta; ir abu Elio sūnūs, Hofnis ir Finehasas, buvo nužudyti.'),
  (@b9, 4, 12, 'Ir vyras iš Benjamino, išbėgęs iš kariuomenės, tą pačią dieną atėjo į Šilojų su perplėštais drabužiais ir su žemėmis ant galvos.'),
  (@b9, 4, 13, 'Ir jam atėjus, štai Elis sėdėjo krėsle prie pakelės, žiūrėdamas; nes jo širdis drebėjo dėl Dievo skrynios. Ir kai tas vyras atėjęs tai pranešė mieste, visas miestas ėmė rėkti.'),
  (@b9, 4, 14, 'Ir išgirdęs šauksmo garsą, Elis tarė: „Ką reiškia šito triukšmo garsas?“ Ir tas vyras skubiai atėjęs pranešė Eliui.'),
  (@b9, 4, 15, 'Na, o Elis buvo devyniasdešimt aštuonerių metų; ir jo akys buvo aptemusios, kad jis nebegalėjo matyti.'),
  (@b9, 4, 16, 'Ir tas vyras tarė Eliui: „Aš esu atėjęs iš kariuomenės, šiandien pabėgau iš kariuomenės“. Ir jis tarė: „Kas ten atsitiko, mano sūnau?“'),
  (@b9, 4, 17, 'Ir pasiuntinys atsakydamas tarė: „Izraelis bėgo filistinų akivaizdoje, ir taip pat buvo didelės žudynės tautos tarpe, o taip pat ir tavo abu sūnūs Hofnis ir Finehasas yra mirę, ir Dievo skrynia yra paimta“.'),
  (@b9, 4, 18, 'Ir įvyko, kai jis paminėjo Dievo skrynią, jis atbulas nukrito nuo krėslo šalia vartų ir jo sprandas lūžo, ir jis mirė; nes jis buvo senas vyras ir sunkus. Keturiasdešimt metų jis teisė Izraelį.'),
  (@b9, 4, 19, 'O jo marti, Finehaso žmona, buvo nėščia, prieš pat gimdymą; ir išgirdusi žinią, kad Dievo skrynia paimta ir kad jos uošvis bei jos vyras mirę, ji susilenkė ir pagimdė; nes ją buvo suėmę jos skausmai.'),
  (@b9, 4, 20, 'O jai mirštant, prie jos stovėjusios moterys jai sakė: „Nebijok; nes tu pagimdei sūnų“. Bet ji neatsakė ir nekreipė į tai dėmesio.'),
  (@b9, 4, 21, 'Ir ji praminė vaiką Ikabodu, sakydama: „Šlovė pasitraukė iš Izraelio“; dėl to, kad Dievo skrynia buvo paimta ir dėl savo uošvio bei savo vyro.'),
  (@b9, 4, 22, 'Ir ji tarė: „Šlovė pasitraukė iš Izraelio; nes Dievo skrynia paimta“.'),
  (@b9, 5, 1, 'O filistinai paėmė Dievo skrynią ir ją nugabeno iš Eben-Ezero į Ašdodą.'),
  (@b9, 5, 2, 'Paėmę Dievo skrynią, filistinai ją įnešė į Dagono namus ir pastatė šalia Dagono.'),
  (@b9, 5, 3, 'Ir kai tie iš Ašdodo atsikėlė anksti rytojaus dieną, štai Dagonas buvo nugriuvęs veidu į žemę prieš VIEŠPATIES skrynią. Ir paėmę Dagoną, jie pastatė jį atgal į jo vietą.'),
  (@b9, 5, 4, 'O rytojaus dieną jiems anksti ryte atsikėlus, štai Dagonas buvo nugriuvęs veidu į žemę prieš VIEŠPATIES skrynią; o Dagono galva ir abi jo rankų plaštakos buvo nukirstos ant slenksčio; tik Dagono liemuo buvo jam likęs.'),
  (@b9, 5, 5, 'Todėl nei Dagono kunigai, nei visi įeinantieji į Dagono namus iki šios dienos neužmina Dagono slenksčio Ašdode.'),
  (@b9, 5, 6, 'Bet VIEŠPATIES ranka buvo sunki tiems iš Ašdodo, ir jis juos naikino ir ištiko juos skauduliais, tai yra Ašdodą ir jo ribas.'),
  (@b9, 5, 7, 'Ir Ašdodo žmonės matydami, kad taip darosi, sakė: „Izraelio Dievo skrynia nepasiliks pas mus; nes jo ranka yra sunki ant mūsų ir ant mūsų dievo Dagono“.'),
  (@b9, 5, 8, 'Todėl jie pasiuntę surinko pas save visus filistinų viešpačius ir tarė: „Ką darysime su Izraelio Dievo skrynia?“ Ir jie atsakė: „Tegul Izraelio Dievo skrynia būna gabenama aplinkui į Gatą“. Ir Izraelio Dievo skrynią gabeno į ten aplinkui.'),
  (@b9, 5, 9, 'Ir buvo, kad po to, kai ją aplinkui nugabeno, VIEŠPATIES ranka buvo prieš tą miestą labai dideliu naikinimu; ir jis ištiko miesto žmones, tiek mažus, tiek didelius, ir jie turėjo skaudulius jų slaptose vietose.'),
  (@b9, 5, 10, 'Todėl jie pasiuntė Dievo skrynią į Ekroną. Ir įvyko, kai Dievo skrynia atėjo į Ekroną, ekroniečiai šaukė, sakydami: „Jie atnešė aplinkui pas mus Izraelio Dievo skrynią, kad nužudytų mus ir mūsų tautą“.'),
  (@b9, 5, 11, 'Taigi jie pasiuntę surinko visus filistinų viešpačius ir sakė: „Paleiskite Izraelio Dievo skrynią, ir ji tesugrįžta į savo pačios vietą, kad ji nenužudytų mūsų bei mūsų tautos“; nes buvo mirtinas naikinimas po visą miestą; Dievo ranka ten buvo labai sunki.'),
  (@b9, 5, 12, 'O žmonės, kurie nemirė, buvo ištikti skauduliais; ir miesto šauksmas kilo į dangų.'),
  (@b9, 6, 1, 'Ir VIEŠPATIES skrynia filistinų krašte buvo septynis mėnesius.'),
  (@b9, 6, 2, 'Ir filistinai pašaukė kunigus ir būrėjus, sakydami: „Ką darysime su VIEŠPATIES skrynia? Pasakykite mums, su kuo ją turime pasiųsti į jos vietą“.'),
  (@b9, 6, 3, 'Ir jie tarė: „Jei išsiųsite Izraelio Dievo skrynią, nesiųskite jos tuščiomis; bet visiškai atsilyginkite jam nusižengimo atnaša; tada būsite išgydyti, ir jums bus žinoma, kodėl jo ranka neatsitraukė nuo jūsų“.'),
  (@b9, 6, 4, 'Tada jie tarė: „Kokia turės būti nusižengimo atnaša, kuria jam atsilyginsime?“ Jie atsakė: ‘ Penki auksiniai skauduliai ir penkios auksinės pelės, pagal filistinų viešpačių skaičių; nes ta pati rykštė buvo ant jūsų visų ir ant jūsų viešpačių.'),
  (@b9, 6, 5, 'Todėl padirbkite atvaizdus savo skaudulių ir atvaizdus savo pelių, darkančių šalį; ir duokite Izraelio Dievui šlovę; gal jis palengvins savo ranką jums, jūsų dievams ir jūsų šaliai.'),
  (@b9, 6, 6, 'Tad kodėl užkietinate savo širdis, kaip egiptiečiai ir faraonas užkietino savo širdis? Kai jis padarė tarp jų nuostabius darbus, argi jie neišleido tautos, ir argi jie neišėjo?'),
  (@b9, 6, 7, 'Taigi dabar padarykite naują vežimą ir paimkite dvi žindančias karves, ant kurių nebuvo užėjęs jungas, ir įkinkykite karves į vežimą, o jų veršiukus parveskite nuo jų į namus;'),
  (@b9, 6, 8, 'ir paėmę VIEŠPATIES skrynią, uždėkite ją ant vežimo; o auksines brangenybes, kuriomis jam atsilyginsite kaip nusižengimo atnaša, padėkite į dėžę šalia jos; ir paleiskite ją, kad ji galėtų eiti.'),
  (@b9, 6, 9, 'Ir žiūrėkite, jei ji eis aukštyn savo ribų keliu į Bet-Šemešą, tai jis yra mums padaręs šitą didelę piktybę; o jei ne, tuomet žinosime, kad tai ne jo ranka, kuri mus ištiko; tai atsitiktinai buvo mums įvykę“.'),
  (@b9, 6, 10, 'Ir žmonės taip padarė: paėmė dvi žindančias karves ir įkinkė jas į vežimą, o jų veršiukus uždarė namuose;'),
  (@b9, 6, 11, 'ir jie uždėjo ant vežimo VIEŠPATIES skrynią ir dėžę su aukso pelėmis bei savo skaudulių atvaizdais.'),
  (@b9, 6, 12, 'Ir karvės ėjo tiesiu keliu į Bet-Šemešo kelią, ėjo tolyn vieškeliu ir eidamos baubė, nepasukdamos nei į dešinę, nei į kairę; o filistinų viešpačiai ėjo paskui jas iki Bet-Šemešo ribos.'),
  (@b9, 6, 13, 'O tie iš Bet-Šemešo pjovė savo kviečių derlių slėnyje; ir pakėlę akis ir pamatę skrynią, džiaugėsi ją matydami.'),
  (@b9, 6, 14, 'Ir vežimas atvažiavo į betšemiečio Jozuės lauką ir ten sustojo, kur buvo didžiulis akmuo; ir jie suskaldė vežimo medieną ir atnašavo karves kaip deginamąją atnašą VIEŠPAČIUI.'),
  (@b9, 6, 15, 'Ir levitai nukėlė VIEŠPATIES skrynią ir prie jos buvusią dėžę, kurioje buvo auksinės brangenybės, ir padėjo jas ant didžiojo akmens; ir tą pačią dieną Bet-Šemešo žmonės atnašavo deginamąsias atnašas ir aukojo aukas VIEŠPAČIUI.'),
  (@b9, 6, 16, 'O tai pamatę, penki filistinų viešpačiai tą pačią dieną sugrįžo į Ekroną.'),
  (@b9, 6, 17, 'O tie yra auksiniai skauduliai, kuriais filistinai atsilygino kaip nusižengimo atnaša VIEŠPAČIUI: vienas už Ašdodą, vienas už Gazą, vienas už Aškeloną, vienas už Gatą, vienas už Ekroną;'),
  (@b9, 6, 18, 'ir auksinės pelės pagal skaičių visų filistinų miestų, priklausančių penkiems viešpačiams, tiek aptvertų miestų, tiek šalies kaimų iki didžiojo Abelio akmens, ant kurio jie padėjo VIEŠPATIES skrynią; šis akmuo išlikęs iki šios dienos bet-šemiečio Jozuės lauke.'),
  (@b9, 6, 19, 'Ir jis išmušė Bet-Šemešo žmones, nes jie pažiūrėjo vidun į VIEŠPATIES skrynią, jis išmušė iš tautos penkiasdešimt tūkstančių septyniasdešimt žmonių; ir tauta raudojo, nes VIEŠPATS buvo ištikęs daugelį iš tautos didelėmis žudynėmis.'),
  (@b9, 6, 20, 'Ir Bet-Šemešo žmonės tarė: „Kas pajėgus išsilaikyti šito šventojo VIEŠPATIES Dievo akivaizdoje? Ir pas ką ji eis nuo mūsų aukštyn?“'),
  (@b9, 6, 21, 'Ir jie siuntė pasiuntinius pas Kirjat-Jearimo gyventojus, sakydami: „Filistinai sugrąžino VIEŠPATIES skrynią; ateikite žemyn ir nuneškite ją aukštyn pas save“.'),
  (@b9, 7, 1, 'Ir atėjo Kirjat-Jearimo žmonės ir nunešė VIEŠPATIES skrynią aukštyn, ir įnešė ją į Abinadabo namus ant kalvos, o jo sūnų Eleazarą pašventė saugoti VIEŠPATIES skrynią.'),
  (@b9, 7, 2, 'Ir įvyko, kad nuo tada, kai skrynia pasiliko Kirjat-Jearime, buvo praėję daug laiko – dvidešimt metų; ir visi Izraelio namai raudojo VIEŠPAČIUI iš paskos.'),
  (@b9, 7, 3, 'Ir Samuelis kalbėjo visiems Izraelio namams, sakydamas: „Jei grįžtate pas VIEŠPATĮ visomis savo širdimis, tuomet pašalinkite iš savo tarpo svetimus dievus bei Astarotę ir paruoškite savo širdis VIEŠPAČIUI, ir jam vienam tarnaukite; ir jis jus išvaduos iš filistinų rankos“.'),
  (@b9, 7, 4, 'Tada Izraelio vaikai pašalino Baalus bei Astarotę ir tarnavo vien tik VIEŠPAČIUI.'),
  (@b9, 7, 5, 'Ir Samuelis tarė: „Surinkite visą Izraelį į Micpę, ir aš melsiuosi už jus VIEŠPAČIUI“.'),
  (@b9, 7, 6, 'Ir susirinkę į Micpę, jie sėmė vandenį ir išliejo jį VIEŠPATIES akivaizdoje, ir tą dieną pasninkavo, ir ten sakė: „Mes nusidėjome prieš VIEŠPATĮ“. Ir Samuelis teisė Izraelio vaikus Micpėje.'),
  (@b9, 7, 7, 'Ir kai filistinai išgirdo, kad Izraelio vaikai buvo susirinkę į Micpę, filistinų viešpačiai ėjo aukštyn prieš Izraelį. Ir tai išgirdę, Izraelio vaikai išsigando filistinų.'),
  (@b9, 7, 8, 'Ir Izraelio vaikai tarė Samueliui: „Nepaliauk šauktis už mus VIEŠPATIES, mūsų Dievo, kad jis mus išgelbėtų iš filistinų rankos“.'),
  (@b9, 7, 9, 'Ir Samuelis ėmė žindantį avinėlį ir atnašavo jį visą kaip deginamąją atnašą VIEŠPAČIUI; ir Samuelis šaukėsi VIEŠPATIES už Izraelį; ir VIEŠPATS jį išklausė.'),
  (@b9, 7, 10, 'Ir Samueliui beaukojant deginamąją atnašą, filistinai artinosi į mūšį prieš Izraelį; bet tą dieną VIEŠPATS griaudėjo ant filistinų didžiu griausmu ir juos sutrikdė; ir jie buvo sumušti Izraelio akivaizdoje.'),
  (@b9, 7, 11, 'Ir Izraelio vyrai, išėję iš Micpės, vijosi filistinus ir juos mušė, kol jie atėjo iki Bet-Karo apačios.'),
  (@b9, 7, 12, 'Paskui Samuelis, paėmęs akmenį, pastatė jį tarp Micpės ir Šeno, ir pavadino jį vardu Eben-Ezeris, sakydamas: „Iki čia VIEŠPATS mums padėjo“.'),
  (@b9, 7, 13, 'Taip filistinai buvo numalšinti ir daugiau nebeatėjo į Izraelio ribas; ir VIEŠPATIES ranka buvo prieš filistinus per visas Samuelio dienas.'),
  (@b9, 7, 14, 'O miestai, kuriuos filistinai buvo paėmę iš Izraelio, buvo sugrąžinti Izraeliui nuo Ekrono iki Gato; ir jų ribas Izraelis išvadavo iš filistinų rankų. Ir buvo taika tarp Izraelio ir amoritų.'),
  (@b9, 7, 15, 'Ir Samuelis teisė Izraelį per visas savo gyvenimo dienas.'),
  (@b9, 7, 16, 'Ir kasmet jis eidavo ratu į Bet-Elį, Gilgalą bei Micpę ir teisdavo Izraelį visose tose vietose.'),
  (@b9, 7, 17, 'Ir jis grįždavo į Ramą; nes ten buvo jo namai; ir ten jis teisdavo Izraelį; ir jis ten pastatė aukurą VIEŠPAČIUI.'),
  (@b9, 8, 1, 'Ir įvyko, kai Samuelis buvo pasenęs, jis paskyrė savo sūnus teisėjais Izraeliui.'),
  (@b9, 8, 2, 'Na, o jo pirmagimio vardas buvo Joelis; o jo antrojo vardas Abija; jie buvo teisėjai Beer-Šeboje.'),
  (@b9, 8, 3, 'O jo sūnūs nevaikščiojo jo keliais, bet nukrypo paskui pelną, ėmė kyšius ir iškraipė teismą.'),
  (@b9, 8, 4, 'Tada susirinko visi Izraelio vyresnieji, atėjo pas Samuelį į Ramą'),
  (@b9, 8, 5, 'ir jam tarė: „Štai tu esi senas, o tavo sūnūs nevaikšto tavo keliais; paskirk mums dabar karalių, kad mus teistų, kaip turi visos tautos“.'),
  (@b9, 8, 6, 'Bet Samueliui nepatiko tas dalykas, kai jie pasakė: „Duok mums karalių, kad mus teistų“. Ir Samuelis meldėsi VIEŠPAČIUI.'),
  (@b9, 8, 7, 'Ir VIEŠPATS tarė Samueliui: „Klausyk tautos balso visame, ką jie tau sako; nes ne tave jie atmetė, bet mane atmetė, kad aš jiems nekaraliaučiau.'),
  (@b9, 8, 8, 'Pagal visus darbus, kuriuos jie darė nuo tos dienos, kai juos išvedžiau aukštyn iš Egipto, iki šios dienos, palikdami mane ir tarnaudami kitiems dievams, taip jie daro ir tau.'),
  (@b9, 8, 9, 'Taigi dabar išklausyk jų balso; tačiau griežtai jiems tvirtink ir jiems paskelbk būdą karaliaus, kuris jiems karaliaus“.'),
  (@b9, 8, 10, 'Ir Samuelis pasakė visus VIEŠPATIES žodžius tautai, kuri prašė iš jo karaliaus.'),
  (@b9, 8, 11, 'Ir jis sakė: „Toks bus būdas karaliaus, kuris jums karaliaus: jis paims jūsų sūnus ir pasistatys juos sau, savo vežimams bei savo raiteliams; ir vieni bėgs pirma jo vežimų.'),
  (@b9, 8, 12, 'Ir jis paskirs sau vadus tūkstančiams bei vadus penkiasdešimtims; ir paskirs juos arti jo žemę, pjauti jo derlių ir gaminti jo karo prietaisus bei jo vežimų reikmenis.'),
  (@b9, 8, 13, 'Ir jis paims jūsų dukteris, kad būtų vaistininkės, virėjos ir kepėjos.'),
  (@b9, 8, 14, 'Ir jis paims geriausius jūsų laukus, jūsų vynuogynus ir jūsų alyvmedžių sodus ir duos juos savo tarnams.'),
  (@b9, 8, 15, 'Iš jūsų sėklos ir iš jūsų vynuogynų jis ims dešimtinę ir duos savo pareigūnams bei savo tarnams.'),
  (@b9, 8, 16, 'Ir jis paims jūsų tarnus, jūsų tarnaites, jūsų geriausius jaunuolius bei jūsų asilus ir pristatys juos prie savo darbo.'),
  (@b9, 8, 17, 'Jis paims jūsų avių dešimtadalį; o jūs būsite jo tarnais.'),
  (@b9, 8, 18, 'Ir tą dieną jūs šauksite dėl savo karaliaus, kurį išsirinkote; bet tą dieną VIEŠPATS neišklausys jūsų“.'),
  (@b9, 8, 19, 'Tačiau tauta atsisakė paklusti Samuelio balsui; ir jie sakė: „Ne; mes norime turėti sau karalių;'),
  (@b9, 8, 20, 'kad ir mes būtume kaip visos tautos; ir kad mūsų karalius mus teistų ir eitų mūsų priešakyje bei kovotų mūsų kovas“.'),
  (@b9, 8, 21, 'Ir Samuelis išklausė visus tautos žodžius ir juos pakartojo į VIEŠPATIES ausis.'),
  (@b9, 8, 22, 'Ir VIEŠPATS tarė Samueliui: „Paklausyk jų balso ir paskirk jiems karalių“. Ir Samuelis tarė Izraelio žmonėms: „Eikite kiekvienas į savo miestą“.'),
  (@b9, 9, 1, 'Na, o buvo vyras iš Benjamino, kurio vardas Kišas, sūnus Abielio, sūnaus Ceroro, sūnaus Bekorato, sūnaus Afiacho, benjaminas, galingas jėga vyras.'),
  (@b9, 9, 2, 'Ir jis turėjo sūnų, kurio vardas buvo Saulius, rinktinį jaunuolį ir gražų; ir Izraelio vaikų tarpe nebuvo gražesnio už jį; nuo savo pečių į viršų jis buvo aukštesnis už bet kurį iš tautos.'),
  (@b9, 9, 3, 'Ir dingo Sauliaus tėvo Kišo asilai. Ir Kišas tarė savo sūnui Sauliui: „Imk dabar su savimi vieną iš tarnų ir pakilęs eik ieškoti asilų“.'),
  (@b9, 9, 4, 'Ir jis perėjo per Efraimo kalną ir perėjo per Šališos šalį, bet jie jų nerado; tada jie perėjo per Šalimo šalį, bet jų ten nebuvo; ir jis perėjo per benjaminų šalį, bet jie jų nerado.'),
  (@b9, 9, 5, 'Ir jiems atėjus į Cufo šalį, Saulius tarė savo tarnui, esančiam su juo: „Eikš, grįžkime; kad mano tėvas, paliovęs rūpintis dėl asilų, neimtų rūpintis dėl mūsų“.'),
  (@b9, 9, 6, 'O jis jam tarė: „Štai Dievo vyras yra šiame mieste, ir jis yra gerbiamas vyras; viskas, ką jis kalba, tikrai įvyksta; dabar ten eikime; gal jis mums parodys mūsų kelią, kuriuo turime eiti“.'),
  (@b9, 9, 7, 'Tada Saulius tarė savo tarnui: „Bet štai jei eisime, ką nunešime tam vyrui? Nes duona pasibaigė mūsų induose, ir nėra dovanos tam Dievo vyrui nunešti; ką mes turime?“'),
  (@b9, 9, 8, 'O tarnas vėl Sauliui atsakydamas tarė: „Štai aš turiu rankoje sidabro šekelio ketvirtadalį; tą duosiu Dievo vyrui, kad mums nurodytų mūsų kelią“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b9, 9, 9, '(Seniau Izraelyje kas nors eidamas Dievo pasiklausti, taip sakydavo: „Ateikite, eime pas regėtoją“; nes tą, kurį dabar vadina pranašu, seniau vadindavo regėtoju.)'),
  (@b9, 9, 10, 'Tada Saulius tarė savo tarnui: „Gerai pasakyta; ateik, eikime“. Taip jie nuėjo į miestą, kur buvo Dievo vyras.'),
  (@b9, 9, 11, 'Ir eidami aukštyn kalva į miestą, jie užtiko jaunas mergaites, beišeinančias vandens semti, ir joms tarė: „Ar yra čia regėtojas?“'),
  (@b9, 9, 12, 'Ir jos atsakydamos jiems tarė: „Yra; štai jis jūsų priešakyje; dabar skubėkite, nes šiandien jis atėjo į miestą; nes tautos auka šiandien yra aukštumoje.'),
  (@b9, 9, 13, 'Kai tik įeisite į miestą, tuoj pat jį rasite, prieš jam einant aukštyn į aukštumą valgyti; nes tauta nevalgys, kol jis neateis, kadangi jis palaimina auką; o paskui valgo pakviestieji. Taigi dabar eikite aukštyn; nes kaip tik šiuo metu jį rasite“.'),
  (@b9, 9, 14, 'Ir jie ėjo aukštyn į miestą; ir jiems įėjus į miestą, štai Samuelis išėjo jiems priešais, kad eitų aukštyn į aukštumą.'),
  (@b9, 9, 15, 'Na, o dieną prieš Sauliaus atėjimą, VIEŠPATS buvo kalbėjęs Samueliui į ausį, sakydamas:'),
  (@b9, 9, 16, '„Rytoj apie tą laiką atsiųsiu tau vyrą iš Benjamino šalies, o tu jį patepsi būti vadu mano tautos Izraelio, kad jis išgelbėtų mano tautą iš filistinų rankos; nes aš pažvelgiau į savo tautą, kadangi jos šauksmas atėjo pas mane“.'),
  (@b9, 9, 17, 'Ir kai Samuelis pamatė Saulių, VIEŠPATS jam tarė: „Štai tas vyras, apie kurį tau kalbėjau! Šitas karaliaus mano tautai“.'),
  (@b9, 9, 18, 'Tada Saulius priartėjo prie Samuelio vartuose ir tarė: „Pasakyk man, meldžiu tave, kur yra regėtojo namai“.'),
  (@b9, 9, 19, 'O Samuelis atsakė Sauliui ir tarė: „Aš esu regėtojas; eik aukštyn pirma manęs į aukštumą; nes šiandien valgysite su manimi, o rytoj tave išleisiu ir tau pasakysiu viską, kas yra tavo širdyje.'),
  (@b9, 9, 20, 'O dėl tavo asilų, kurie dingo prieš tris dienas, nesirūpink jais; nes jie atsirado. O ant ko yra visas Izraelio troškimas? Argi ne ant tavęs ir ant visų tavo tėvo namų?“'),
  (@b9, 9, 21, 'Ir Saulius atsakydamas tarė: „Argi aš ne benjaminas iš mažiausios Izraelio genčių, ir argi mano šeima nėra mažiausia iš visų Benjamino genties šeimų? Tai kodėl man taip sakai?“'),
  (@b9, 9, 22, 'Ir Samuelis paėmė Saulių ir jo tarną ir juos įvedė į kambarį, ir juos pasodino į garbingiausią vietą tarp pakviestųjų, kurių buvo apie trisdešimt asmenų.'),
  (@b9, 9, 23, 'Ir Samuelis tarė virėjui: „Paduok tą dalį, kurią tau daviau, apie kurią tau sakiau: ‘Atidėk ją pas save’.“'),
  (@b9, 9, 24, 'Ir virėjas pakėlė petį ir tai, kas buvo ant jo, ir padėjo tai priešais Saulių. Ir Samuelis tarė: „Štai tai, kas liko! Padėk tai prieš save ir valgyk; nes iki šio laiko tai buvo tau palaikyta nuo tada, kai pasakiau: „Aš pakviečiau tautą“. Taip Saulius tą dieną valgė su Samueliu.'),
  (@b9, 9, 25, 'Ir jiems atėjus žemyn nuo aukštumos į miestą, Samuelis kalbėjosi su Sauliumi ant namo stogo.'),
  (@b9, 9, 26, 'Ir jie anksti atsikėlė; ir įvyko, kad aušrai brėkštant Samuelis pašaukė Saulių ant namo stogo, sakydamas: „Kelkis, kad tave išleisčiau“. Ir Sauliui atsikėlus, jie abu išėjo laukan, jis ir Samuelis.'),
  (@b9, 9, 27, 'Ir jiems einant žemyn į miesto pakraštį, Samuelis tarė Sauliui: „Pasakyk tarnui paeiti toliau pirma mūsų (ir jis paėjo toliau), o tu kuriam laikui sustok, kad tau paskelbčiau Dievo žodį“.'),
  (@b9, 10, 1, 'Paskui Samuelis paėmė aliejaus buteliuką ir išliejo jį jam ant galvos, pabučiavo jį ir tarė: „Ar tai ne dėl to, kad VIEŠPATS tave patepė būti vadu jo paveldui?'),
  (@b9, 10, 2, 'Šiandien nuo manęs nuėjęs, tu užtiksi du vyrus prie Rachelės kapo, Benjamino ribose, Celcache; ir jie tau sakys: ‘Atsirado asilai, kurių ėjai ieškoti; ir štai tavo tėvas nebesirūpina asilais, bet sielojasi dėl jūsų, sakydamas: Ką darysiu dėl savo sūnaus?’'),
  (@b9, 10, 3, 'Paskui eidamas iš ten toliau, tu ateisi į Taboro lygumą, ir ten tave sutiks trys vyrai, einantys aukštyn pas Dievą į Bet-Elį: vienas trimis ožiukais nešinas, kitas trimis duonos kepalais nešinas, o kitas vyno indu nešinas;'),
  (@b9, 10, 4, 'ir jie tave pasveikins ir tau duos du duonos kepalus; kuriuos tu imk iš jų rankų.'),
  (@b9, 10, 5, 'Po to tu ateisi į Dievo kalvą, kur yra filistinų įgula; ir įvyks, kai įeisi ten į miestą, sutiksi būrį pranašų, ateinančių žemyn nuo aukštumos su psalteriais, būgneliais, dūdomis ir arfomis jų priešakyje; ir jie pranašaus;'),
  (@b9, 10, 6, 'ir VIEŠPATIES Dvasia ateis ant tavęs, ir tu pranašausi su jais, ir tapsi kitu žmogumi.'),
  (@b9, 10, 7, 'Ir tebūna, kai šitie ženklai tau ateis, daryk, kaip tau pasitarnaus galimybė; nes Dievas yra su tavimi.'),
  (@b9, 10, 8, 'Ir eik žemyn pirma manęs į Gilgalą; o štai aš ateisiu žemyn pas tave atnašauti deginamųjų atnašų ir aukoti taikos atnašų aukų; septynias dienas lauk, kol ateisiu pas tave ir tau nurodysiu, ką tu turi daryti“.'),
  (@b9, 10, 9, 'Ir buvo, kai jis pasuko savo nugarą eiti nuo Samuelio, Dievas jam davė kitą širdį; ir visi šitie ženklai įvyko tą dieną.'),
  (@b9, 10, 10, 'Ir kai jie atėjo ten prie kalvos, štai jį pasitiko pranašų būrys; ir ant jo atėjo Dievo Dvasia, ir jis pranašavo tarp jų.'),
  (@b9, 10, 11, 'Ir įvyko, kai visi, kurie jį anksčiau pažinojo, pamatė jį pranašaujant tarp pranašų, tada tautoje sakė vienas kitam: „Kas gi tai, kas atsitiko Kišo sūnui? Ar ir Saulius tarp pranašų?“'),
  (@b9, 10, 12, 'Ir vienas iš tos pačios vietos atsiliepdamas tarė: „O kas yra jų tėvas?“ Todėl tai tapo patarle: „Ar ir Saulius tarp pranašų?“'),
  (@b9, 10, 13, 'Ir baigęs pranašauti, jis atėjo į aukštumą.'),
  (@b9, 10, 14, 'Ir Sauliaus dėdė tarė jam ir jo tarnui: „Kur buvote nuėję?“ O jis tarė: „Asilų ieškoti; ir matydami, kad jų niekur nėra, mes atėjome pas Samuelį“.'),
  (@b9, 10, 15, 'Ir Sauliaus dėdė tarė: „Meldžiu tave, papasakok man, ką jums sakė Samuelis“.'),
  (@b9, 10, 16, 'Ir Saulius tarė savo dėdei: „Jis mums tiesiai pasakė, kad asilai atsiradę“. Bet apie karalystės dalyką, apie kurį Samuelis kalbėjo, jis jam nepasakojo.'),
  (@b9, 10, 17, 'Ir Samuelis sušaukė tautą pas VIEŠPATĮ į Micpę;'),
  (@b9, 10, 18, 'ir sakė Izraelio vaikams: „Taip sako VIEŠPATS, Izraelio Dievas: Aš išvedžiau Izraelį aukštyn iš Egipto ir jus išgelbėjau iš egiptiečių rankos ir iš visų karalysčių rankos ir iš tų, kurie jus engė;'),
  (@b9, 10, 19, 'o jūs šią dieną atmetėte savo Dievą, kuris pats jus išgelbėjo iš visų jūsų nelaimių ir jūsų suspaudimų; ir jūs jam sakėte: ‘Ne, paskirk mums karalių’. Taigi dabar stokite VIEŠPATIES akivaizdoje savo gentimis ir savo tūkstančiais“.'),
  (@b9, 10, 20, 'Ir kai Samuelis liepė prieiti visoms Izraelio gentims, buvo paimta Benjamino gentis.'),
  (@b9, 10, 21, 'Kai jis liepė prieiti Benjamino genčiai jų šeimomis, buvo paimta Matrio šeima ir buvo paimtas Kišo sūnus Saulius; ir kai jie ieškojo jo, nebuvo galima jo rasti.'),
  (@b9, 10, 22, 'Todėl jie toliau teiravosi VIEŠPATIES, ar tas vyras dar čia ateis. O VIEŠPATS atsakė: „Štai jis pasislėpęs tarp daiktų“.'),
  (@b9, 10, 23, 'Ir nubėgę jie atvedė jį iš ten; ir atsistojęs tautos tarpe, jis nuo pečių į viršų buvo aukštesnis už bet kurį iš tautos.'),
  (@b9, 10, 24, 'Ir Samuelis tarė visai tautai: „Ar matote tą, kurį VIEŠPATS išsirinko, kad nėra jam lygaus visoje tautoje?“ Ir visa tauta šaukė ir tarė: „Tegyvuoja karalius“.'),
  (@b9, 10, 25, 'Tada Samuelis išdėstė tautai karalystės būdą ir surašė tai į knygą, ir padėjo tai VIEŠPATIES akivaizdoje. Ir Samuelis paleido visą tautą, kiekvieną į savo namus.'),
  (@b9, 10, 26, 'O Saulius irgi ėjo namo į Gibėją; ir su juo ėjo būrys vyrų, kurių širdis Dievas buvo palietęs.'),
  (@b9, 10, 27, 'Bet Belialo vaikai sakė: „Kaip šitas mus išgelbės?“ Ir jie paniekino jį ir jam neatnešė dovanų. Bet jis išsilaikė ramus.'),
  (@b9, 11, 1, 'Tada atėjo aukštyn amonietis Nahašas ir stovyklavo prieš Jabeš-Gileadą; ir visi Jabešo žmonės sakė Nahašui: „Sudaryk su mumis sandorą, o mes tau tarnausime“.'),
  (@b9, 11, 2, 'O amonietis Nahašas jiems atsakė: „Su ta sąlyga sudarysiu su jumis sandorą, kad galėsiu išdurti visų jūsų dešines akis, ir tai uždėsiu kaip gėdą visam Izraeliui“.'),
  (@b9, 11, 3, 'Ir Jabešo vyresnieji jam tarė: „Duok mums septynias dienas atsikvėpti, kad nusiųstume pasiuntinius į visas Izraelio ribas; o tada, jei nebus kas mus gelbėtų, mes išeisime pas tave“.'),
  (@b9, 11, 4, 'Tada pasiuntiniai atėjo į Sauliaus Gibėją ir pranešė žinią tautai į ausis; ir visa tauta pakeltais balsais verkė.'),
  (@b9, 11, 5, 'O štai Saulius atėjo iš lauko paskui bandą; ir Saulius tarė: „Kas yra tautai, kad jie verkia?“ Ir jie papasakojo jam Jabešo žmonių žinią.'),
  (@b9, 11, 6, 'Ir jam išgirdus šitą žinią, Dievo Dvasia atėjo ant Sauliaus, ir smarkiai užsidegė jo pyktis.'),
  (@b9, 11, 7, 'Ir paėmęs jaučių jungą ir juos supjaustęs į gabalus, jis išsiuntė juos per pasiuntinių rankas į visas Izraelio ribas, sakydamas: „Kas neišeis paskui Saulių ir paskui Samuelį, taip bus padaryta jo jaučiams“. Ir VIEŠPATIES baimė apėmė tautą, ir jie išėjo visi kaip vienas.'),
  (@b9, 11, 8, 'Ir kai jis juos suskaičiavo Bezeke, Izraelio vaikų buvo trys šimtai tūkstančių, o Judos vyrų trisdešimt tūkstančių.'),
  (@b9, 11, 9, 'Ir jie tarė atvykusiems pasiuntiniams: „Taip sakykite Jabeš-Gileado žmonėms: ‘Rytoj, kai saulė įkais, jūs turėsite pagalbą’. Ir pasiuntiniai parėjo ir pranešė tai Jabešo žmonėms; ir jie apsidžiaugė.'),
  (@b9, 11, 10, 'Todėl Jabešo žmonės tarė: „Rytoj ateisime pas jus, o jūs darykite su mumis viską, kas tik jums atrodys gerai“.'),
  (@b9, 11, 11, 'Ir rytojaus dieną buvo taip, kad Saulius sustatė tautą į tris būrius; ir per rytinį budėjimą jie atėjo į kariuomenės vidurį ir žudė amoniečius iki dienos kaitros; ir įvyko, kad išlikusieji taip išsisklaidė, jog iš jų neliko nei dviejų drauge.'),
  (@b9, 11, 12, 'Ir tauta tarė Samueliui: „Kas yra tas, kuris sakė: ‘Ar Saulius mums karaliaus? Atveskite tuos vyrus, kad juos užmuštume“.'),
  (@b9, 11, 13, 'O Saulius tarė: „Šią dieną nei vienas nebus užmuštas; nes šiandien VIEŠPATS atliko išgelbėjimą Izraelyje“.'),
  (@b9, 11, 14, 'Paskui Samuelis sakė tautai: „Ateikite, eikime į Gilgalą ir ten atnaujinkime karalystę“.'),
  (@b9, 11, 15, 'Ir visa tauta nuėjo į Gilgalą; ir ten jie paskyrė Saulių karaliumi VIEŠPATIES akivaizdoje, Gilgale; ir jie ten aukojo taikos atnašų aukas VIEŠPATIES akivaizdoje; ir ten labai džiaugėsi Saulius bei visi Izraelio žmonės.'),
  (@b9, 12, 1, 'Ir Samuelis tarė visam Izraeliui: „Štai aš paklausiau jūsų balso visame, ką man sakėte, ir jums paskyriau karalių.'),
  (@b9, 12, 2, 'O dabar štai karalius vaikšto jūsų akivaizdoje; o aš esu senas ir žilagalvis; ir štai mano sūnūs yra su jumis; o aš vaikščiojau jūsų akivaizdoje nuo savo vaikystės iki šios dienos.'),
  (@b9, 12, 3, 'Štai aš čia; paliudykite prieš mane VIEŠPATIES akivaizdoje ir jo pateptojo akivaizdoje; ar kieno jautį esu paėmęs? Ar kieno asilą esu paėmęs? Ar kurį apgavau? Ar ką engiau? Ar iš kieno rankos ėmiau kokį kyšį, kad juo apakinčiau sau akis? Aš jums grąžinsiu“.'),
  (@b9, 12, 4, 'Ir jie tarė: „Nei tu mus apgavai, nei mus engei, nei ką paėmei iš kieno nors rankos“.'),
  (@b9, 12, 5, 'Ir jis jiems tarė: „VIEŠPATS yra liudytojas prieš jus, ir jo pateptasis šią dieną yra liudytojas, kad jūs nieko neradote mano rankoje“. Ir jie atsakė: „Jis yra liudytojas“.'),
  (@b9, 12, 6, 'Ir Samuelis sakė tautai: „Tai yra VIEŠPATS, kuris paaukštino Mozę bei Aaroną ir kuris išvedė jūsų tėvus aukštyn iš Egipto šalies.'),
  (@b9, 12, 7, 'Taigi dabar stovėkite nejudėdami, kad bylinėčiausi su jumis VIEŠPATIES akivaizdoje dėl visų VIEŠPATIES teisių darbų, kuriuos jis padarė jums ir jūsų tėvams.'),
  (@b9, 12, 8, 'Kai Jokūbas buvo atėjęs į Egiptą, ir jūsų tėvai šaukėsi VIEŠPATIES, tada VIEŠPATS siuntė Mozę ir Aaroną, kurie išvedė jūsų tėvus iš Egipto ir padarė, kad jie gyventų šioje vietoje.'),
  (@b9, 12, 9, 'Ir kai jie pamiršo VIEŠPATĮ, savo Dievą, jis juos pardavė į Siseros, Hacoro kariuomenės vado, rankas ir į filistinų rankas, ir į Moabo karaliaus rankas, ir jie kariavo prieš juos.'),
  (@b9, 12, 10, 'Ir jie šaukėsi VIEŠPATIES ir sakė: ‘Mes nusidėjome, nes palikome VIEŠPATĮ ir tarnavome Baalams bei Astarotei; bet dabar išgelbėk mus iš mūsų priešų rankos, o mes tau tarnausime.'),
  (@b9, 12, 11, 'Ir VIEŠPATS siuntė Jerubaalą, Bedaną, Jeftą ir Samuelį ir jus išgelbėjo iš jūsų priešų rankos iš visų pusių, ir jūs saugiai gyvenote.'),
  (@b9, 12, 12, 'O matydami, kad Amono vaikų karalius Nahašas atėjo prieš jus, jūs man sakėte: „Ne; tegul karalius mums karaliauja“; kai VIEŠPATS, jūsų Dievas, buvo jūsų karalius.'),
  (@b9, 12, 13, 'Taigi dabar, štai karalius, kurį išsirinkote, kurio troškote! ir štai VIEŠPATS pastatė virš jūsų karalių.'),
  (@b9, 12, 14, 'Jei bijosite VIEŠPATIES, jam tarnausite, paklusite jo balsui ir nemaištausite prieš VIEŠPATIES įsakymą, tada tiek jūs, tiek ir karalius, kuris jums karaliaus, toliau seksite paskui VIEŠPATĮ, savo Dievą.'),
  (@b9, 12, 15, 'Bet jei nepaklusite VIEŠPATIES balsui, bet maištausite prieš VIEŠPATIES įsakymą, tada VIEŠPATIES ranka bus prieš jus, kaip ji buvo prieš jūsų tėvus.'),
  (@b9, 12, 16, 'Taigi dabar stovėkite ir matykite tą didį dalyką, kurį VIEŠPATS padarys prieš jūsų akis.'),
  (@b9, 12, 17, 'Argi šiandien ne kviečių pjūtis? Aš šauksiuos VIEŠPATIES, o jis pasiųs griaustinį ir lietų; kad suprastumėte ir pamatytumėte, kad jūsų nedorybė yra didelė, kurią padarėte VIEŠPATIES akyse, prašydami sau karaliaus“.'),
  (@b9, 12, 18, 'Taigi Samuelis šaukėsi VIEŠPATIES; ir VIEŠPATS tą dieną siuntė griaustinį ir lietų; ir visa tauta labai bijojo VIEŠPATIES ir Samuelio.'),
  (@b9, 12, 19, 'Ir visa tauta tarė Samueliui: „Melskis už savo tarnus VIEŠPAČIUI, tavo Dievui, kad nemirtume; nes prie visų savo nuodėmių mes pridėjome šitą piktybę, kad prašėme sau karaliaus“.'),
  (@b9, 12, 20, 'Ir Samuelis sakė tautai: „Nebijokite; jūs padarėte visą šitą nedorybę, tačiau nenukrypkite nuo sekimo VIEŠPAČIU, bet tarnaukite VIEŠPAČIUI visa savo širdimi;'),
  (@b9, 12, 21, 'ir nenukrypkite į šoną; nes tada nueisite paskui niekingus dalykus, kurie nei gali duoti naudos, nei išgelbėti; nes jie yra tušti.'),
  (@b9, 12, 22, 'Nes VIEŠPATS nepaliks savo tautos dėl savo didžiojo vardo; kadangi VIEŠPAČIUI patiko jus padaryti savo tauta.'),
  (@b9, 12, 23, 'O kas dėl manęs, apsaugok Dieve, kad nusidėčiau prieš VIEŠPATĮ, paliaudamas melstis už jus; bet aš jus mokysiu gero ir teisingo kelio;'),
  (@b9, 12, 24, 'tik bijokite VIEŠPATIES ir jam tikrai tarnaukite visa savo širdimi; nes pasvarstykite, kokių didžių dalykų jis yra jums padaręs.'),
  (@b9, 12, 25, 'Bet jei vis dar darysite pikta, būsite sunaikinti, tiek jūs, tiek jūsų karalius“.'),
  (@b9, 13, 1, 'Saulius karaliavo vienus metus; o kai jis buvo karaliavęs Izraeliui du metus,'),
  (@b9, 13, 2, 'Saulius išsirinko iš Izraelio tris tūkstančius vyrų; iš kurių du tūkstančiai buvo su Sauliumi Michmaše ir Bet-Elio kalne, o tūkstantis buvo su Jonatanu Benjamino Gibėjoje; o likusią tautą jis paleido, kiekvieną į savo palapinę.'),
  (@b9, 13, 3, 'Ir Jonatanas sumušė filistinų įgulą, buvusią Geboje, o filistinai tai išgirdo. Ir Saulius pūtė trimitą po visą šalį, sakydamas: „Tegul išgirsta hebrajai“.'),
  (@b9, 13, 4, 'Ir visas Izraelis išgirdo sakant, kad Saulius sumušė filistinų įgulą, ir kad Izraelis pasidarė pasibjaurėjimu filistinams“. Ir tauta buvo sušaukta paskui Saulių į Gilgalą.'),
  (@b9, 13, 5, 'Ir filistinai susirinko kovoti su Izraeliu: trisdešimt tūkstančių vežimų, šeši tūkstančiai raitelių ir daugybė liaudies, kaip smėlio, esančio ant jūros kranto; ir jie atėjo aukštyn ir stovyklavo Michmaše, į rytus nuo Bet-Aveno.'),
  (@b9, 13, 6, 'Kai Izraelio vyrai pamatė, kad jie yra sunkioje padėtyje (nes tauta buvo suspausta), tada tauta pasislėpė olose, tankumynuose, uolose, aukštumose ir duobėse.'),
  (@b9, 13, 7, 'O kai kurie hebrajai perėjo per Jordaną į Gado ir Gileado šalį. O Saulius, jis dar buvo Gilgale, ir visa tauta sekė paskui jį drebėdama.'),
  (@b9, 13, 8, 'Ir jis septynias dienas laukė pagal nustatytą laiką, kurį Samuelis buvo paskyręs; bet Samuelis neatėjo į Gilgalą; ir tauta išsiskirstė nuo jo.'),
  (@b9, 13, 9, 'Ir Saulius tarė: „Atneškite čia pas mane deginamąją atnašą ir taikos atnašas“. Ir jis atnašavo deginamąją atnašą.'),
  (@b9, 13, 10, 'Ir įvyko, kad, jam tik baigus atnašauti deginamąją atnašą, štai Samuelis atėjo; ir Saulius išėjo jį sutikti, kad jį pasveikintų.'),
  (@b9, 13, 11, 'Ir Samuelis tarė: „Ką tu padarei?“ O Saulius tarė: „Kadangi mačiau, kad tauta nuo manęs išsiskirstė, ir kad tu neatėjai per paskirtas dienas, ir kad filistinai susirinko Michmaše;'),
  (@b9, 13, 12, 'todėl tariau: ‘Dabar filistinai ateis žemyn ant manęs į Gilgalą, o aš nebūsiu maldavęs VIEŠPATIES’; todėl priverčiau save ir atnašavau deginamąją atnašą“.'),
  (@b9, 13, 13, 'Ir Samuelis tarė Sauliui: „Tu kvailai padarei; tu nesilaikei VIEŠPATIES, savo Dievo, įsakymo, kurį jis tau įsakė; nes dabar VIEŠPATS būtų įtvirtinęs tavo karalystę Izraeliui amžiams.'),
  (@b9, 13, 14, 'Bet dabar tavo karalystė nebetvers; VIEŠPATS pasiieškojo vyrą pagal savo paties širdį, ir VIEŠPATS jam įsakė būti vadu savo tautai, nes tu nesilaikei to, ką VIEŠPATS tau įsakė“.'),
  (@b9, 13, 15, 'Ir Samuelis pakilo ir ėjo iš Gilgalo aukštyn į Benjamino Gibėją. Ir Saulius suskaičiavo tautą, esančią su juo, apie šešis šimtus vyrų.'),
  (@b9, 13, 16, 'Ir Saulius, jo sūnus Jonatanas ir su jais esanti tauta, pasiliko Benjamino Gibėjoje; bet filistinai stovyklavo Michmaše.'),
  (@b9, 13, 17, 'Ir grobikai išėjo iš filistinų stovyklos trim būriais: vienas būrys pasuko keliu, vedančiu į Ofrą, į Šualo šalį;'),
  (@b9, 13, 18, 'kitas būrys pasuko keliu į Bet-Horoną; o kitas būrys pasuko ribos keliu, žvelgiančiu į Ceboimo slėnį, link dykumos.'),
  (@b9, 13, 19, 'Na, o visoje Izraelio šalyje nebuvo galima rasti kalvio; nes filistinai tarė: „Kad hebrajai nepasidirbtų kalavijų ar iečių“;'),
  (@b9, 13, 20, 'bet visi izraelitai ėjo žemyn pas filistinus, kiekvienas pasigaląsti savo noragą, savo kaplį, savo kirvį ir savo kirtiklį.'),
  (@b9, 13, 21, 'Jie dar turėjo dildes kirtikliams, kapliams, šakėms, kirviams bei badikliams pagaląsti.'),
  (@b9, 13, 22, 'Taigi įvyko mūšio dieną, kad nebuvo rasta nei kalavijo, nei ieties rankoje pas nei vieną iš tautos, buvusios su Sauliumi ir Jonatanu; bet radosi pas Saulių ir jo sūnų Jonataną.'),
  (@b9, 13, 23, 'Ir filistinų įgula išėjo į Michmašo perėją.'),
  (@b9, 14, 1, 'Na, o įvyko vieną dieną, kad Sauliaus sūnus Jonatanas tarė jaunuoliui, kuris nešiojo jo ginklus: „Eikš, pereikime iki filistinų įgulos, esančios kitoje pusėje“. Bet jis nesakė savo tėvui.'),
  (@b9, 14, 2, 'O Saulius pasiliko tolimiausiame Gibėjos pakraštyje po granatmedžiu, esančiu Migrone; o su juo buvusios tautos buvo apie šešis šimtus vyrų;'),
  (@b9, 14, 3, 'ir Achija, sūnus Ikabodo brolio Ahitubo, sūnaus Finehaso, sūnaus Elio, VIEŠPATIES kunigas Šilojuje, nešiojantis efodą. Ir tauta nežinojo, kad Jonatanas buvo išėjęs.'),
  (@b9, 14, 4, 'O tarp perėjų, per kurias Jonatanas siekė pereiti iki filistinų įgulos, buvo aštri uola vienoje pusėje ir aštri uola kitoje pusėje; vienos vardas buvo Bocecas, o kitos vardas Senė.'),
  (@b9, 14, 5, 'Vienos priekis kyšojo į šiaurę, priešais Michmašą, o kitos į pietus, priešais Gibėją.'),
  (@b9, 14, 6, 'Ir Jonatanas tarė jaunuoliui, kuris nešiojo jo ginklus: „Eikš, pereikime iki šitų neapipjaustytųjų įgulos; gal VIEŠPATS veiks dėl mūsų; nes nėra VIEŠPAČIUI ribų, kad išgelbėtų per daugelį ar per keletą“.'),
  (@b9, 14, 7, 'Ir jo ginklanešys jam tarė: „Daryk viską, kas yra tavo širdyje; suk; štai aš su tavimi pagal tavo širdį“.'),
  (@b9, 14, 8, 'Tada Jonatanas tarė: „Štai mes pereisime pas tuos vyrus ir jiems pasirodysime.'),
  (@b9, 14, 9, 'Jei jie taip mums sakys: ‘Palaukite, kol ateisime pas jus’; tada mes stovėsime savo vietoje ir neisime aukštyn pas juos.'),
  (@b9, 14, 10, 'Bet jei jie taip sakys: ‘Ateikite aukštyn pas mus’; tada mes eisime aukštyn; nes VIEŠPATS yra juos atidavęs į mūsų rankas; ir tai bus mums ženklas“.'),
  (@b9, 14, 11, 'Ir jie abu pasirodė filistinų įgulai; ir filistinai sakė: „Štai hebrajai išlenda iš landynių, kuriose jie buvo pasislėpę“.'),
  (@b9, 14, 12, 'Ir įgulos vyrai atsakė Jonatanui ir jo ginklanešiui ir tarė: „Ateikite aukštyn pas mus, o mes jums kai ką parodysime“. Ir Jonatanas tarė savo ginklanešiui: „Eik aukštyn paskui mane; nes VIEŠPATS juos atidavė į Izraelio rankas“.'),
  (@b9, 14, 13, 'Ir Jonatanas užlipo savo rankomis ir savo kojomis, o jo ginklanešys paskui jį; ir jie krito Jonatano priešakyje; o jo ginklanešys žudė jam iš paskos.'),
  (@b9, 14, 14, 'Ir tos pirmosios žudynės, kurias įvykdė Jonatanas ir jo ginklanešys, buvo apie dvidešimt vyrų, kaip per pusę akro žemės, kurią galėtų suarti jaučių jungas.'),
  (@b9, 14, 15, 'Ir buvo drebėjimas kariuomenėje, ant lauko ir visoje tautoje; įgula ir grobikai, jie irgi drebėjo, ir drebėjo žemė; taigi tai buvo labai didelis drebėjimas.'),
  (@b9, 14, 16, 'Ir Sauliaus sargybiniai Benjamino Gibėjoje pažiūrėjo; ir štai daugybė sutirpo, ir jie ėjo mušdami vienas kitą.'),
  (@b9, 14, 17, 'Tada Saulius tarė su juo esančiai tautai: „Dabar suskaičiuokite ir pažiūrėkite, kas yra išėjęs iš mūsų“. Ir jiems suskaičiavus, štai nebuvo Jonatano ir jo ginklanešio.'),
  (@b9, 14, 18, 'Ir Saulius tarė Achijai: „Atnešk čia Dievo skrynią“. Nes tuo metu Dievo skrynia buvo pas Izraelio vaikus.'),
  (@b9, 14, 19, 'Ir kol Saulius kalbėjo kunigui, įvyko, kad triukšmas, buvęs filistinų kariuomenėje, vis plito ir didėjo; ir Saulius tarė kunigui: „Ištrauk savo ranką“.'),
  (@b9, 14, 20, 'Ir Saulius ir visa su juo esanti tauta susirinko ir atėjo į mūšį; ir štai kiekvieno kalavijas buvo atgręžtas prieš saviškį, ir buvo labai didelis sumišimas.'),
  (@b9, 14, 21, 'Be to hebrajai, kurie anksčiau buvo pas filistinus, kurie ėjo su jais aukštyn į stovyklą iš aplinkinio krašto, jie irgi apsigręžė, kad būtų pas izraelitus, esančius su Sauliumi ir Jonatanu.'),
  (@b9, 14, 22, 'Taip pat visi Izraelio vyrai, kurie buvo pasislėpę Efraimo kalne, išgirdę, kad filistinai bėga, irgi uoliai sekė paskui juos mūšyje.'),
  (@b9, 14, 23, 'Taip VIEŠPATS tą dieną išgelbėjo Izraelį; ir mūšis perėjo iki Bet-Aveno.'),
  (@b9, 14, 24, 'Ir tą dieną Izraelio vyrai buvo pavargę; nes Saulius buvo prisaikdinęs tautą, sakydamas: „Prakeiktas tebūna vyras, kuris valgytų bet kokio maisto iki vakaro, kol aš atkeršysiu savo priešams“. Taigi nei vienas iš tautos neparagavo jokio maisto.'),
  (@b9, 14, 25, 'Ir visi iš šalies atėjo į mišką; ir buvo medus ant žemės.'),
  (@b9, 14, 26, 'Ir tautai atėjus į mišką, štai medus varvėjo; bet niekas nepridėjo rankos prie savo burnos; nes tauta bijojo priesaikos.'),
  (@b9, 14, 27, 'Bet Jonatanas negirdėjo, kai jo tėvas įpareigojo tautą su priesaika; todėl jis ištiesė galą lazdos, esančios jo rankoje, ir padažė jį į medaus korį ir pridėjo ranką prie savo burnos; ir jo akys prašvito.'),
  (@b9, 14, 28, 'Tada vienas iš tautos atsiliepdamas tarė: „Tavo tėvas griežtai įpareigojo tautą su priesaika, sakydamas: ‘Prakeiktas tebūna vyras, kuris šią dieną valgytų kokio maisto’. O tauta buvo nusilpusi“.'),
  (@b9, 14, 29, 'Tada Jonatanas tarė: „Mano tėvas sudrumstė šalį; meldžiu jus, žiūrėkite, kaip prašvito mano akys, kadangi paragavau truputį šito medaus.'),
  (@b9, 14, 30, 'Kaip juo labiau, jei šiandien tauta būtų laisvai prisivalgiusi iš jų priešų grobio, kurį jie rado; nes argi dabar nebūtų buvę daug didesnių žudynių tarp filistinų?'),
  (@b9, 14, 31, 'Ir tą dieną jie mušė filistinus nuo Michmašo iki Ajalono; ir tauta buvo labai nusilpusi.'),
  (@b9, 14, 32, 'Ir tauta bėgo prie grobio ir ėmė avis, jaučius ir veršius, ir juos pjovė ant žemės; ir tauta juos valgė su krauju.'),
  (@b9, 14, 33, 'Tada jie pranešė Sauliui, sakydami: „Štai tauta nusideda prieš VIEŠPATĮ, valgydami su krauju“. Ir jis tarė: „Jūs nusižengėte; atriskite man šią dieną didelį akmenį“.'),
  (@b9, 14, 34, 'Ir Saulius tarė: „Išsiskirstykite tarp tautos ir jiems sakykite: ‘Atveskite kiekvienas pas mane savo jautį ir kiekvienas savo avį ir čia juos papjaukite, ir valgykite; ir nenusidėkite prieš VIEŠPATĮ, valgydami su krauju“. Ir visa tauta tą naktį kiekvienas atvedė savo jautį su savimi ir juos ten papjovė.'),
  (@b9, 14, 35, 'Ir Saulius pastatė aukurą VIEŠPAČIUI; tas buvo pirmasis aukuras, kurį jis pastatė VIEŠPAČIUI.'),
  (@b9, 14, 36, 'Ir Saulius tarė: „Eikime žemyn naktį paskui filistinus ir juos apiplėškime iki ryto šviesos, ir nepalikime nei vieno iš jų“. Ir jie tarė: „Daryk viską, kas tau rodosi gera“. Tada kunigas tarė: „Prisiartinkime čia prie Dievo“.'),
  (@b9, 14, 37, 'Ir Saulius klausė Dievo patarimo: „Ar man eiti žemyn paskui filistinus? Ar juos atiduosi į Izraelio rankas?“ Bet jis tą dieną jam neatsakė.'),
  (@b9, 14, 38, 'Ir Saulius tarė: „Prisiartinkite čia visi tautos vadai; sužinokite ir pamatykite, kame šią dieną buvo šita nuodėmė.'),
  (@b9, 14, 39, 'Nes kaip VIEŠPATS gyvas, kuris gelbėja Izraelį, nors ji būtų mano sūnuje Jonatane, jis tikrai mirs“. Bet iš visos tautos nebuvo nei vieno, kuris jam atsakytų.'),
  (@b9, 14, 40, 'Tada jis tarė visam Izraeliui: „Jūs būkite vienoje pusėje, o aš ir mano sūnus Jonatanas būsime kitoje pusėje“. Ir tauta sakė Sauliui: „Daryk tai, kas tau atrodo gera“.'),
  (@b9, 14, 41, 'Taigi Saulius tarė VIEŠPAČIUI, Izraelio Dievui: „Duok tobulą burtą“. Ir buvo paimti Saulius ir Jonatanas; o tauta išsigelbėjo.'),
  (@b9, 14, 42, 'Ir Saulius tarė: „Meskite burtą tarp manęs ir mano sūnaus Jonatano“. Ir buvo paimtas Jonatanas.'),
  (@b9, 14, 43, 'Tada Saulius tarė Jonatanui: „Pasakyk man, ką tu padarei“. O Jonatanas, jam sakydamas, tarė: „Aš tik paragavau truputį medaus galu lazdos, buvusios mano rankoje, ir štai aš turiu mirti“.'),
  (@b9, 14, 44, 'Ir Saulius atsakė: „Tegul Dievas padaro taip ir dar daugiau; nes tu tikrai mirsi, Jonatanai“.'),
  (@b9, 14, 45, 'O tauta tarė Sauliui: „Ar turėtų mirti Jonatanas, kuris įvykdė šitą didelį išgelbėjimą Izraelyje? Apsaugok Dieve; kaip VIEŠPATS gyvas, nei vienas jo galvos plaukas nenukris žemėn; nes su Dievu jis šią dieną veikė“. Taip tauta išgelbėjo Jonataną, kad jis nemirė.'),
  (@b9, 14, 46, 'Paskui Saulius nuėjo aukštyn, nebesekdamas filistinų; o filistinai nuėjo į savo vietą.'),
  (@b9, 14, 47, 'Taigi Saulius ėmė karalystę Izraeliui valdyti ir kiekvienoje pusėje kovojo prieš visus savo priešus: prieš Moabą, prieš Amono vaikus, prieš Edomą, prieš Cobos karalius ir prieš filistinus; ir kur tik jis pasisukdavo, jis juos vargindavo.'),
  (@b9, 14, 48, 'Ir jis surinko kariuomenę ir sumušė amalekus, ir išgelbėjo Izraelį iš rankų tų, kurie jį apiplėšė.'),
  (@b9, 14, 49, 'Na, o Sauliaus sūnūs buvo Jonatanas, Išvis ir Malki-Šūva; o jo dviejų dukterų vardai buvo šitie: pirmagimės vardas Meraba, o jaunesniosios vardas Mikala;'),
  (@b9, 14, 50, 'o Sauliaus žmonos vardas buvo Ahinoama, Achimaaco duktė; o jo kariuomenės vado vardas buvo Abneras, Sauliaus dėdės Nero sūnus.'),
  (@b9, 14, 51, 'O Sauliaus tėvas buvo Kišas; o Abnero tėvas Neras buvo Abielio sūnus.'),
  (@b9, 14, 52, 'Ir per visas Sauliaus dienas buvo smarkus karas prieš filistinus; ir kai Saulius pamatydavo kokį stiprų vyrą ar kokį narsų vyrą, jis paimdavo jį pas save.'),
  (@b9, 15, 1, 'Samuelis dar tarė Sauliui: „VIEŠPATS mane siuntė tavęs patepti, kad būtum karaliumi jo tautai, Izraeliui; taigi dabar klausyk VIEŠPATIES žodžių balso.'),
  (@b9, 15, 2, 'Taip sako kariuomenių VIEŠPATS: ‘Aš atsiminiau tai, ką Amalekas padarė Izraeliui, kaip jis tykojo jo kelyje, kai tas ėjo aukštyn iš Egipto.'),
  (@b9, 15, 3, 'Eik dabar, sumušk Amaleką ir visiškai sunaikink viską, ką jie turi, ir jų nesigailėk; bet išžudyk vyrus ir moteris, kūdikius ir žinduklius, jaučius ir avis, kupranugarius ir asilus’“.'),
  (@b9, 15, 4, 'Ir Saulius surinko tautą ir juos suskaičiavo Telaime, du šimtus tūkstančių pėstininkų ir dešimt tūkstančių Judos vyrų.'),
  (@b9, 15, 5, 'Ir Saulius atėjo į Amaleko miestą ir tykojo slėnyje.'),
  (@b9, 15, 6, 'Ir Saulius pasakė kenitams: „Eikite, pasitraukite, eikite žemyn iš amalekiečių tarpo, kad nesunaikinčiau jūsų su jais; nes jūs parodėte gerumą visiems Izraelio vaikams, kai jie atėjo aukštyn iš Egipto“. Taip kenitai pasitraukė iš amalekiečių tarpo.'),
  (@b9, 15, 7, 'Ir Saulius mušė amalekiečius, nuo Havilos einant iki Šūro, esančio priešais Egiptą.'),
  (@b9, 15, 8, 'Ir jis paėmė amalekiečių karalių Agagą gyvą, o visą tą tautą visiškai sunaikino kalavijo ašmenimis.'),
  (@b9, 15, 9, 'Bet Saulius ir tauta pasigailėjo Agago ir geriausių avių bei jaučių, ir peniukšlių, ir avinėlių, ir visko, kas buvo gera, ir nenorėjo jų visiškai sunaikinti; bet viską, kas buvo bjauru ir atmestina, tai jie visiškai sunaikino.'),
  (@b9, 15, 10, 'Tada VIEŠPATIES žodis atėjo Samueliui, sakydamas:'),
  (@b9, 15, 11, '„Gailiuosi, kad paskyriau Saulių būti karaliumi; nes jis nusigręžė nuo sekimo paskui mane ir neįvykdė mano įsakymų“. Ir tai nuliūdino Samuelį; ir jis šaukėsi VIEŠPATIES visą naktį.'),
  (@b9, 15, 12, 'Ir Samueliui anksti ryte atsikėlus Sauliaus pasitikti, Samueliui buvo pranešta, sakant: „Saulius atėjo į Karmelį, ir štai jis pastatė sau vietą ir pavaikščiojęs nuėjo toliau ir atėjo žemyn į Gilgalą“.'),
  (@b9, 15, 13, 'Ir Samuelis atėjo pas Saulių; ir Saulius jam tarė: „Būk VIEŠPATIES palaimintas; aš įvykdžiau VIEŠPATIES įsakymą“.'),
  (@b9, 15, 14, 'O Samuelis tarė: „Tai ką reiškia šitas avių bliovimas mano ausyse ir jaučių baubimas, kurį aš girdžiu?“'),
  (@b9, 15, 15, 'Ir Saulius tarė: „Iš amalekiečių jie atvedė juos; nes tauta pasigailėjo geriausių iš avių ir jaučių, kad aukotų VIEŠPAČIUI, tavo Dievui; o visa kita mes visiškai sunaikinome“.'),
  (@b9, 15, 16, 'Tada Samuelis tarė Sauliui: „Palauk, o aš tau pasakysiu, ką VIEŠPATS šiąnakt man kalbėjo“. Ir jis jam tarė: „Kalbėk“.'),
  (@b9, 15, 17, 'Ir Samuelis tarė: „Kai buvai mažas savo akyse, argi nebuvai paskirtas Izraelio genčių galva, ir argi VIEŠPATS tavęs nepatepė Izraelio karaliumi?'),
  (@b9, 15, 18, 'Ir VIEŠPATS tave siuntė į kelionę ir tarė: ‘Eik ir visiškai sunaikink tuos nusidėjėlius amalekiečius ir kovok prieš juos, kol jie bus sunaikinti.'),
  (@b9, 15, 19, 'Tai kodėl nepaklusai VIEŠPATIES balsui, bet nulėkei prie grobio ir padarei pikta VIEŠPATIES akyse?“'),
  (@b9, 15, 20, 'O Saulius tarė Samueliui: „Taip, aš paklusau VIEŠPATIES balsui ir ėjau keliu, kuriuo VIEŠPATS mane siuntė, ir atvedžiau Amaleko karalių Agagą, o amalekiečius visiškai sunaikinau.'),
  (@b9, 15, 21, 'Bet tauta paėmė iš grobio avių ir jaučių, geriausių iš to, kas turėjo būti visiškai sunaikinta, kad aukotų VIEŠPAČIUI, tavo Dievui, Gilgale“.'),
  (@b9, 15, 22, 'O Samuelis tarė: „Argi VIEŠPATS gėrisi deginamosiomis atnašomis ir aukomis taip didžiai, kaip ir paklusnumu VIEŠPATIES žodžiui? Štai paklusti yra geriau už auką, ir klausyti yra geriau už avinų taukus.'),
  (@b9, 15, 23, 'Nes maištavimas yra kaip raganavimo nuodėmė, o užsispyrimas – kaip neteisybė ir stabmeldystė. Kadangi tu atmetei VIEŠPATIES žodį, tai ir jis tave atmetė, kad nebūtum karaliumi“.'),
  (@b9, 15, 24, 'Ir Saulius tarė Samueliui: „Aš nusidėjau; nes nusižengiau VIEŠPATIES įsakymui ir tavo žodžiams; nes aš bijojau tautos ir paklusau jų balsui.'),
  (@b9, 15, 25, 'Todėl dabar, meldžiu tave, atleisk mano nuodėmę ir grįžk su manimi, kad pagarbinčiau VIEŠPATĮ“.'),
  (@b9, 15, 26, 'O Samuelis tarė Sauliui: „Negrįšiu su tavimi; nes tu atmetei VIEŠPATIES žodį, o VIEŠPATS atmetė tave, kad nebūtum karaliumi Izraeliui“.'),
  (@b9, 15, 27, 'Ir Samueliui apsisukus eiti šalin, jis nutvėrė jo apsiausto skverną, ir tas suplyšo.'),
  (@b9, 15, 28, 'Ir Samuelis jam tarė: „VIEŠPATS šią dieną atplėšė nuo tavęs Izraelio karalystę ir davė ją tavo artimui, geresniam už tave.'),
  (@b9, 15, 29, 'Be to, Izraelio Stiprybė nemeluos ir nepersigalvos; nes jis ne žmogus, kad persigalvotų“.'),
  (@b9, 15, 30, 'Tada jis tarė: „Aš nusidėjau; tačiau dabar, meldžiu tave, pagerbk mane mano tautos vyresniųjų akivaizdoje ir Izraelio akivaizdoje ir grįžk su manimi, kad pagarbinčiau VIEŠPATĮ, tavo Dievą“.'),
  (@b9, 15, 31, 'Taigi Samuelis grįžo paskui Saulių; ir Saulius pagarbino VIEŠPATĮ.'),
  (@b9, 15, 32, 'Tada Samuelis tarė: „Atveskite čia pas mane amalekiečių karalių Agagą“. O Agagas atėjo pas jį tyliai. Ir Agagas sakė: „Tikrai mirties kartumas praėjęs“.'),
  (@b9, 15, 33, 'Ir Samuelis tarė: „Kaip tavo kalavijas padarė moteris bevaikes, taip ir tavo motina bus bevaikė tarp moterų“. Ir Samuelis sukapojo Agagą į gabalus VIEŠPATIES akivaizdoje Gilgale.'),
  (@b9, 15, 34, 'Paskui Samuelis nuėjo į Ramą; o Saulius nuėjo aukštyn į savo namus, į Sauliaus Gibėją.'),
  (@b9, 15, 35, 'Ir Samuelis daugiau nebeatėjo pasimatyti su Sauliumi iki savo mirties dienos; tačiau Samuelis liūdėjo dėl Sauliaus; o VIEŠPATS gailėjosi, kad buvo padaręs Saulių Izraelio karaliumi.'),
  (@b9, 16, 1, 'Ir VIEŠPATS tarė Samueliui: „Kaip ilgai liūdėsi dėl Sauliaus, nes atmečiau jį, kad nekaraliautų Izraeliui? Pripildyk savo ragą aliejaus ir eik, aš tave pasiųsiu pas betliejietį Jesę; nes iš jo sūnų parūpinau sau karalių“.'),
  (@b9, 16, 2, 'O Samuelis tarė: „Kaip aš galiu eiti? Jei Saulius tai išgirs, jis mane nužudys“. Ir VIEŠPATS tarė: „Paimk su savimi telyčią ir sakyk: ‘Atėjau VIEŠPAČIUI aukoti.'),
  (@b9, 16, 3, 'Ir pasikviesk Jesę prie aukos, o aš tau parodysiu, ką turėsi daryti; ir patepk man tą, kurį tau įvardysiu“.'),
  (@b9, 16, 4, 'Ir Samuelis padarė tai, ką VIEŠPATS kalbėjo, ir atėjo į Betliejų. O miesto vyresnieji drebėjo dėl jo atėjimo ir tarė: „Ar taikingai ateini?“');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b9, 16, 5, 'Ir jis tarė: „Taikingai; aš atėjau VIEŠPAČIUI aukoti; pasišvęskite ir ateikite su manimi prie aukos. Ir jis pašventė Jesę bei jo sūnus ir juos pakvietė prie aukos.'),
  (@b9, 16, 6, 'Ir įvyko, kai jie atėjo, jis pažiūrėjo į Eliabą ir tarė: „Tikrai jo akivaizdoje yra VIEŠPATIES pateptasis“.'),
  (@b9, 16, 7, 'Bet VIEŠPATS tarė Samueliui: Nežiūrėk į jo veidą ar į jo aukštą ūgį; nes jį atmečiau; nes VIEŠPATS mato ne taip, kaip žmogus mato; nes žmogus žiūri į išorę, bet VIEŠPATS žiūri į širdį“.'),
  (@b9, 16, 8, 'Paskui Jesė pašaukė Abinadabą ir jam davė praeiti Samuelio akivaizdoje. Ir jis tarė: „Nei šito VIEŠPATS neišsirinko“.'),
  (@b9, 16, 9, 'Po to Jesė liepė praeiti Šamai. O jis tarė: „Nei šito VIEŠPATS neišsirinko“.'),
  (@b9, 16, 10, 'Vėlgi Jesė liepė praeiti savo septyniems sūnums Samuelio akivaizdoje. O Samuelis tarė Jesei: „VIEŠPATS šitų neišsirinko“.'),
  (@b9, 16, 11, 'Ir Samuelis tarė Jesei: „Ar čia visi tavo vaikai?“ O jis tarė: „Dar liko jauniausiasis, bet štai, jis gano avis“. Ir Samuelis tarė Jesei: „Siųsk ir atvesk jį; nes mes nesusėsime, kol jis čia neateis“.'),
  (@b9, 16, 12, 'Ir jis pasiuntė ir jį įvedė. Na, o jis buvo rausvas, gražaus veido ir dailus pažiūrėti. Ir VIEŠPATS tarė: „Kelkis, patepk jį; nes tai yra jis“.'),
  (@b9, 16, 13, 'Tada Samuelis paėmė ragą aliejaus ir patepė jį tarp jo brolių; ir VIEŠPATIES Dvasia atėjo ant Dovydo nuo tos dienos ir po to. Taigi Samuelis pakilo ir ėjo į Ramą.'),
  (@b9, 16, 14, 'Bet VIEŠPATIES Dvasia pasitraukė nuo Sauliaus, ir pikta dvasia nuo VIEŠPATIES neramino jį.'),
  (@b9, 16, 15, 'Ir Sauliaus tarnai jam tarė: „Štai dabar pikta dvasia nuo Dievo neramina tave.'),
  (@b9, 16, 16, 'Tegul mūsų viešpats dabar įsako savo tarnams, esantiems tavo akivaizdoje, paieškoti vyro, sumaniai grojančio arfa; ir įvyks, kai tik pikta dvasia iš Dievo bus ant tavęs, tada jis pagros savo ranka, ir tau bus gerai“.'),
  (@b9, 16, 17, 'Ir Saulius tarė savo tarnams: „Parūpinkite man dabar vyrą, mokantį gerai groti, ir atveskite jį pas mane“.'),
  (@b9, 16, 18, 'Tada vienas iš tarnų atsiliepdamas tarė: „Štai mačiau betliejiečio Jesės sūnų, sumaniai grojantį, galingą narsuolį, karo vyrą, protingą reikaluose ir gražų vyrą, ir VIEŠPATS yra su juo“.'),
  (@b9, 16, 19, 'Todėl Saulius siuntė pasiuntinius pas Jesę ir sakė: „Atsiųsk man savo sūnų Dovydą, esantį prie avių“.'),
  (@b9, 16, 20, 'Ir Jesė paėmė asilą, užkrautą duona, vyno indą, ožiuką, ir siuntė juos Sauliui per savo sūnų Dovydą.'),
  (@b9, 16, 21, 'Ir Dovydas atėjo pas Saulių ir stovėjo jo akivaizdoje; ir jis jį labai pamilo; ir jis tapo jo ginklanešiu.'),
  (@b9, 16, 22, 'Ir Saulius siuntė pas Jesę, sakydamas: „Leisk Dovydui, meldžiu tave, stovėti mano akivaizdoje; nes jis rado palankumą mano akyse“.'),
  (@b9, 16, 23, 'Ir įvyko, kai pikta dvasia iš Dievo būdavo ant Sauliaus, Dovydas tada paimdavo arfą ir grodavo savo ranka; taip Saulius atsigaivindavo, ir jam būdavo gerai, ir nuo jo atsitraukdavo pikta dvasia.'),
  (@b9, 17, 1, 'Na, o filistinai surinko savo kariuomenes mūšiui ir susirinko Judai priklausančiame Soche, ir stovyklavo tarp Socho ir Azekos, Efes-Damime.'),
  (@b9, 17, 2, 'O Saulius ir Izraelio vyrai susirinkę stovyklavo šalia Elos slėnio ir išsirikiavo mūšiui prieš filistinus.'),
  (@b9, 17, 3, 'Ir filistinai stovėjo ant kalno vienoje pusėje, o Izraelis stovėjo ant kalno kitoje pusėje, o tarp jų buvo slėnis.'),
  (@b9, 17, 4, 'Ir iš filistinų stovyklos išėjo kovotojas, vardu Galijotas, iš Gato, kurio ūgis buvo šešios uolektys ir vienas sprindis.'),
  (@b9, 17, 5, 'Ir jis turėjo žalvario šalmą ant savo galvos ir buvo apsišarvavęs šarvuotais marškiniais; o marškinių svoris buvo penki tūkstančiai šekelių žalvario.'),
  (@b9, 17, 6, 'Ir jis turėjo žalvario antblauzdžius ant savo kojų ir žalvario skydą tarp savo pečių.'),
  (@b9, 17, 7, 'Ir jo ieties kotas buvo kaip audėjo riestuvas; o jo ieties antgalis svėrė šešis šimtus šekelių geležies; ir pirma jo ėjo skydo nešiotojas.'),
  (@b9, 17, 8, 'Ir jis sustojo ir šaukė Izraelio kariuomenėms, jiems tardamas: „Kodėl išėjote išsirikiuoti savo mūšiui? Ar aš ne filistinas, o jūs ar ne Sauliui tarnai? Išsirinkite sau vyrą, ir tegul jis ateina žemyn pas mane.'),
  (@b9, 17, 9, 'Jei jis pajėgs kovoti su manimi ir mane užmušti, tada mes būsime jūsų tarnai; bet jei aš jį nugalėsiu ir jį užmušiu, tada jūs būsite mūsų tarnai ir mums tarnausite“.'),
  (@b9, 17, 10, 'Ir filistinas tarė: „Šią dieną aš metu iššūkį Izraelio kariuomenėms; duokite man vyrą, kad kovotume kartu“.'),
  (@b9, 17, 11, 'Saulius ir visas Izraelis, išgirdę šituos filistino žodžius, išsigando ir labai bijojo.'),
  (@b9, 17, 12, 'Na, o Dovydas buvo sūnus to efratiečio iš Judos Betliejaus, kurio vardas buvo Jesė; ir jis turėjo aštuonis sūnus; ir Sauliaus dienomis tas vyras buvo senas tarp vyrų.'),
  (@b9, 17, 13, 'Ir trys vyresnieji Jesės sūnūs nuėję sekė paskui Saulių į mūšį; o vardai jo trijų sūnų, kurie ėjo į mūšį, buvo pirmagimis Eliabas, kitas po jo – Abinadabas, o trečiasis – Šama.'),
  (@b9, 17, 14, 'O Dovydas buvo jauniausiasis; ir trys vyresnieji ėjo paskui Saulių.'),
  (@b9, 17, 15, 'Bet Dovydas nueidavo ir sugrįždavo iš Sauliaus savo tėvo avių ganyti Betliejuje.'),
  (@b9, 17, 16, 'Ir tas filistinas ryte ir vakare prisiartindavo ir prisistatydavo per keturiasdešimt dienų.'),
  (@b9, 17, 17, 'Ir Jesė tarė savo sūnui Dovydui: „Na, paimk savo broliams efą šitų paskrudintų grūdų bei šituos dešimt kepalų ir bėk į stovyklą pas savo brolius;'),
  (@b9, 17, 18, 'ir nunešk šituos dešimt sūrių jų tūkstančio vadui ir pažiūrėk, kaip sekasi tavo broliams, ir paimk jų užstatą“.'),
  (@b9, 17, 19, 'Na, o Saulius ir jie, ir visi Izraelio vyrai buvo Elos slėnyje, kovojo su filistinais.'),
  (@b9, 17, 20, 'Ir Dovydas atsikėlė anksti ryte, paliko avis pas sargą, paėmė ir nuėjo, kaip Jesė jam buvo įsakęs; ir jis atėjo į apkasą, kai kariuomenė buvo beišeinanti kovoti ir šaukė į mūšį.'),
  (@b9, 17, 21, 'Nes Izraelis ir filistinai išsirikiavo mūšiui, kariuomenė prieš kariuomenę.'),
  (@b9, 17, 22, 'O Dovydas savo naštą paliko naštos sargo rankose ir nubėgo į kariuomenę, ir atėjęs pasveikino savo brolius.'),
  (@b9, 17, 23, 'Ir jam su jais kalbant, štai atėjo aukštyn kovotojas, filistinas iš Gato, vardu Galijotas, iš filistinų kariuomenių, ir kalbėjo pagal tuos pačius žodžius, o Dovydas juos išgirdo.'),
  (@b9, 17, 24, 'Ir visi Izraelio vyrai, pamatę tą vyrą, bėgo nuo jo ir labai bijojo.'),
  (@b9, 17, 25, 'Ir Izraelio vyrai tarė: „Ar matėte tą vyrą, atėjusį aukštyn? Jis tikrai yra atėjęs aukštyn mesti Izraeliui iššūkį; ir bus, kad, kas jį užmuš, tą karalius praturtins dideliais turtais ir jam duos savo dukterį, ir jo tėvo namus padarys laisvus Izraelyje“.'),
  (@b9, 17, 26, 'Ir Dovydas kalbėjo šalia jo stovintiems vyrams, sakydamas: „Kas bus padaryta tam vyrui, kuris užmuš šitą filistiną ir pašalins priekaištą nuo Izraelio? Nes kas yra tas neapipjaustytas filistinas, kad jis mestų iššūkį gyvojo Dievo kariuomenėms?“'),
  (@b9, 17, 27, 'Ir tauta jam atsakė taip, sakydama: „Taip bus daroma tam vyrui, kuris jį užmuš“.'),
  (@b9, 17, 28, 'O jo vyriausiasis brolis Eliabas išgirdo jį kalbant vyrams; ir Eliabo pyktis užsidegė prieš Dovydą, ir jis tarė: „Kodėl atėjai čia žemyn ir pas ką palikai keletą tų avių dykumoje? Žinau tavo išdidumą ir tavo širdies nelabumą; nes tu atėjai žemyn, kad pamatytum mūšį“.'),
  (@b9, 17, 29, 'Ir Dovydas tarė: „Ką gi dabar padariau? Ar nėra priežasties?“'),
  (@b9, 17, 30, 'Ir jis pasuko nuo jo prie kito ir taip pat kalbėjo; o tauta vėl jam atsakė, kaip ir pirma.'),
  (@b9, 17, 31, 'Ir kai buvo išgirsti žodžiai, kuriuos Dovydas kalbėjo, jie atpasakojo juos Sauliaus akivaizdoje; ir jis išsiuntė jį atvesti.'),
  (@b9, 17, 32, 'Ir Dovydas tarė Sauliui: „Nei vieno širdis tenenusilpsta dėl jo; tavo tarnas eis ir kovos su šituo filistinu“.'),
  (@b9, 17, 33, 'O Saulius tarė Dovydui: „Tu nepajėgus eiti prieš šitą filistiną kovoti su juo; nes tu esi tik jaunuolis, o jis yra karo vyras nuo pat savo jaunystės“.'),
  (@b9, 17, 34, 'Ir Dovydas tarė Sauliui: „Tavo tarnas saugojo savo tėvo avis, ir ateidavo liūtas, ir meška, ir paimdavo avinėlį iš kaimenės;'),
  (@b9, 17, 35, 'o aš eidavau jam iš paskos, jį sumušdavau ir išgelbėdavau jį iš jo nasrų; o kai jis pakildavo prieš mane, aš jį nutverdavau jam už barzdos ir jį mušdamas užmušdavau.'),
  (@b9, 17, 36, 'Tavo tarnas užmušė tiek liūtą, tiek mešką; o šitas neapipjaustytas filistinas bus kaip vienas iš jų, nes jis metė iššūkį gyvojo Dievo kariuomenėms“.'),
  (@b9, 17, 37, 'Dovydas toliau sakė: „VIEŠPATS, kuris mane išvadavo iš liūto letenos ir iš meškos letenos, mane išvaduos iš šito filistino rankos“. Ir Saulius tarė Dovydui: „Eik, ir VIEŠPATS tebūna su tavimi“.'),
  (@b9, 17, 38, 'Ir Saulius apvilko Dovydą savo šarvais, ir jis uždėjo žalvario šalmą jam ant galvos; taip pat jis apvilko jį šarviniais marškiniais.'),
  (@b9, 17, 39, 'Ir Dovydas prisijuosė kalaviją prie savo šarvų ir bandė eiti; nes jis nebuvo jų išmėginęs. Ir Dovydas tarė Sauliui: „Aš negaliu eiti su šitais; nes nesu jų išmėginęs“. Ir Dovydas juos nusiėmė nuo savęs.'),
  (@b9, 17, 40, 'Ir jis pasiėmė į ranką savo lazdą, pasirinko iš upelio penkis glotnius akmenis ir juos įdėjo į piemens maišelį, kurį jis turėjo, tai yra į kelionmaišį; o jo rankoje buvo jo mėtyklė; ir jis artinosi prie filistino.'),
  (@b9, 17, 41, 'Ir filistinas ateidamas artinosi prie Dovydo; o vyras, kuris nešė skydą, ėjo pirma jo.'),
  (@b9, 17, 42, 'Ir filistinas, pažvelgęs aplink ir pamatęs Dovydą, žiūrėjo į jį su panieka; nes jis tebuvo jaunuolis, rausvas ir gražaus veido.'),
  (@b9, 17, 43, 'Ir filistinas tarė Dovydui: „Ar aš šuo, kad ateini pas mane su lazdomis?“ Ir filistinas keikė Dovydą savo dievais.'),
  (@b9, 17, 44, 'Ir filistinas tarė Dovydui: „Eikš pas mane ir aš įduosiu tavo kūną dangaus skrajūnams ir lauko žvėrims“.'),
  (@b9, 17, 45, 'Tada Dovydas tarė filistinui: „Tu ateini pas mane su kalaviju, ietimi ir skydu; bet aš ateinu pas tave vardu kariuomenių VIEŠPATIES, Izraelio kariuomenių Dievo, kuriam tu metei įššūkį.'),
  (@b9, 17, 46, 'Šią dieną VIEŠPATS tave atiduos į mano rankas; aš tave sumušiu ir nuimsiu nuo tavęs tavo galvą; ir šią dieną filistinų kariuomenės lavonus duosiu oro skrajūnams ir laukiniams žemės žvėrims; kad visa žemė žinotų, kad Izraelyje yra Dievas.'),
  (@b9, 17, 47, 'Ir visas šitas susirinkimas žinos, kad VIEŠPATS gelbėja ne kalaviju ir ietimi; nes mūšis yra VIEŠPATIES, ir jis atiduos jus į mūsų rankas“.'),
  (@b9, 17, 48, 'Ir įvyko, kai filistinas pakilo ir ateidamas artinosi Dovydo pasitikti, tada Dovydas pasiskubino ir bėgo link kariuomenės filistino pasitikti.'),
  (@b9, 17, 49, 'Ir Dovydas, įkišęs ranką į savo maišelį ir iš ten paėmęs akmenį, sviedė jį mėtykle ir kirto filistinui į kaktą, kad akmuo įsmigo jam į kaktą; ir jis pargriuvo veidu į žemę.'),
  (@b9, 17, 50, 'Taip Dovydas nugalėjo filistiną mėtykle ir akmeniu, ir kirto filistinui, ir jį užmušė; bet nebuvo kalavijo Dovydo rankoje.'),
  (@b9, 17, 51, 'Todėl Dovydas nubėgo, atsistojo ant filistino, paėmė jo kalaviją, ištraukė jį iš jo makšties ir jį nužudė, ir juo nukirto jam galvą. Ir filistinai, pamatę, kad jų kovotojas miręs, pabėgo.'),
  (@b9, 17, 52, 'O Izraelio ir Judos vyrai pakilo ir šaukė, ir vijosi filistinus iki ten, kur einama į slėnį ir iki Ekrono vartų. Ir filistinų sužeistieji krito prie kelio į Šaaraimą, iki Gato ir iki Ekrono.'),
  (@b9, 17, 53, 'Ir Izraelio vaikai sugrįžo nuo vijimosi paskui filistinus ir apiplėšė jų palapines.'),
  (@b9, 17, 54, 'O Dovydas, paėmęs filistino galvą, atnešė ją į Jeruzalę; bet jo ginklus padėjo į savo palapinę.'),
  (@b9, 17, 55, 'Ir kai Saulius pamatė Dovydą, išeinant prieš filistiną, jis tarė kariuomenės vadui Abnerui: „Abnerai, kieno sūnus yra tas jaunuolis?“ Ir Abneras tarė: „Kaip gyva tavo siela, o karaliau, aš nežinau“.'),
  (@b9, 17, 56, 'Ir karalius tarė: „Paklausk, kieno sūnus tas jaunuolis“.'),
  (@b9, 17, 57, 'Ir kai Dovydas sugrįžo po filistino nužudymo, Abneras ėmė jį ir atvedė jį Sauliaus akivaizdon su filistino galva jo rankoje.'),
  (@b9, 17, 58, 'Ir Saulius jam tarė: „Kieno tu sūnus, jaunuoli?“ O Dovydas atsakė: „Aš esu tavo tarno betliejiečio Jesės sūnus“.'),
  (@b9, 18, 1, 'Ir įvyko, kad, jam baigus kalbėti su Sauliumi, Jonatano siela prisirišo prie Dovydo sielos, ir Jonatanas mylėjo jį kaip savo paties sielą.'),
  (@b9, 18, 2, 'Ir tą dieną Saulius jį paėmė ir jam nebeleido eiti į jo tėvo namus.'),
  (@b9, 18, 3, 'Tada Jonatanas padarė sandorą su Dovydu, nes jis mylėjo jį kaip savo paties sielą.'),
  (@b9, 18, 4, 'Ir Jonatanas nusivilko apsiaustą, kuris buvo ant jo, ir jį davė Dovydui, taip pat savo drabužius, net iki savo kalavijo, iki savo lanko ir iki savo diržo.'),
  (@b9, 18, 5, 'Ir Dovydas išeidavo, kur tik Saulius jį pasiųsdavo, ir išmintingai elgdavosi; ir Saulius jį paskyrė karo vyrų vadovu, ir jis buvo priimtinas visos tautos akyse ir taip pat Sauliaus tarnų akyse.'),
  (@b9, 18, 6, 'Ir jiems ateinant, Dovydui grįžtant nuo filistino nužudymo, įvyko, kad moterys išėjo iš visų Izraelio miestų dainuodamos ir šokdamos karaliaus Sauliaus pasitikti su būgneliais, su džiaugsmu ir su muzikos instrumentais.'),
  (@b9, 18, 7, 'Ir moterys atsakė viena kitai grodamos ir sakė: „Saulius nužudė savo tūkstančius, o Dovydas savo dešimtis tūkstančių“.'),
  (@b9, 18, 8, 'Ir Saulius labai užsirūstino, ir jam nepatiko šitas pasakymas; ir jis tarė: „Dovydui jos priskyrė dešimtis tūkstančių, o man tepriskyrė tūkstančius; ir ko jam betrūksta, tai tik karalystės“.'),
  (@b9, 18, 9, 'Ir nuo tos dienos ir toliau Saulius nenuleido nuo Dovydo akių.'),
  (@b9, 18, 10, 'Ir įvyko rytojaus dieną, kad pikta dvasia iš Dievo atėjo ant Sauliaus, ir jis pranašavo namų viduje; o Dovydas grojo savo ranka, kaip kitais kartais; o Sauliaus rankoje buvo ietis.'),
  (@b9, 18, 11, 'Ir Saulius sviedė ietį; nes jis sakė: „Prismeigsiu ja Dovydą prie sienos“. Ir Dovydas du kartus išsisuko nuo jo akivaizdos.'),
  (@b9, 18, 12, 'Ir Saulius bijojo Dovydo, nes VIEŠPATS buvo su juo, o nuo Sauliaus buvo atsitraukęs.'),
  (@b9, 18, 13, 'Todėl Saulius pašalino jį nuo savęs ir paskyrė jį savo vadu tūkstančiui; ir jis išeidavo ir įeidavo tautos priešakyje.'),
  (@b9, 18, 14, 'Ir Dovydas išmintingai elgėsi visuose savo keliuose; ir VIEŠPATS buvo su juo.'),
  (@b9, 18, 15, 'Todėl Saulius, matydamas, kad jis elgiasi labai išmintingai, bijojo jo.'),
  (@b9, 18, 16, 'Tačiau visas Izraelis ir Juda mylėjo Dovydą, nes jis išeidavo ir įeidavo jų priešakyje.'),
  (@b9, 18, 17, 'Ir Saulius tarė Dovydui: „Štai mano vyresnioji duktė Meraba, ją tau duosiu į žmonas; tik būk man narsus ir kovok VIEŠPATIES kovas“. Nes Saulius tarė: „Tegul ne mano ranka būna ant jo, bet tegul ant jo būna filistinų ranka“.'),
  (@b9, 18, 18, 'Ir Dovydas tarė Sauliui: „Kas aš ir kas yra mano gyvybė ar mano tėvo šeima Izraelyje, kad būčiau karaliaus žentu?“'),
  (@b9, 18, 19, 'Tačiau įvyko tuo laiku, kai Sauliaus duktė Meraba turėjo būti duota Dovydui, ji buvo duota meholiečiui Adrieliui į žmonas.'),
  (@b9, 18, 20, 'Ir Sauliaus duktė Mikalė pamilo Dovydą; ir tai pranešė Sauliui, ir tai jam patiko.'),
  (@b9, 18, 21, 'Ir Saulius tarė: „Aš jam duosiu ją, kad ji jam būtų žabangos, ir kad filistinų ranka būtų prieš jį. Todėl Saulius tarė Dovydui: „Tu šią dieną būsi mano žentu su viena iš dviejų“.'),
  (@b9, 18, 22, 'Ir Saulius įsakė savo tarnams, sakydamas: „Slaptai kalbėkite Dovydui, sakydami: ‘Štai karalius tavimi gėrisi, ir visi jo tarnai myli tave; taigi dabar būk karaliaus žentu’“.'),
  (@b9, 18, 23, 'Ir Sauliaus tarnai kalbėjo šituos žodžius Dovydui į ausis. O Dovydas tarė: „Ar jums atrodo lengva būti karaliaus žentu, turint omenyje, kad aš esu neturtingas ir negerbiamas žmogus?“'),
  (@b9, 18, 24, 'Ir Sauliaus tarnai jam pranešė, sakydami: „Šitaip Dovydas kalbėjo“.'),
  (@b9, 18, 25, 'Ir Saulius tarė: „Taip sakykite Dovydui: ‘Karalius nenori jokio kraičio, o tik šimto filistinų apyvarpių, kad būtų atkeršyta karaliaus priešams’“. Bet Saulius galvojo, kad privers Dovydą kristi nuo filistinų rankų.'),
  (@b9, 18, 26, 'Ir kai jo tarnai pranešė Dovydui šituos žodžius, Dovydui labai patiko būti karaliaus žentu; o dienos dar nebuvo pasibaigusios.'),
  (@b9, 18, 27, 'Todėl Dovydas pakilęs nuėjo, jis ir jo vyrai, ir užmušė iš filistinų du šimtus vyrų; ir Dovydas atnešė jų apyvarpes ir pilną jų skaičių jie padavė karaliui, kad jis būtų karaliaus žentas. Ir Saulius jam davė savo dukterį Mikalę į žmonas.'),
  (@b9, 18, 28, 'Ir Saulius matė ir žinojo, kad VIEŠPATS buvo su Dovydu ir kad Mikalė, Sauliaus duktė, jį mylėjo.'),
  (@b9, 18, 29, 'Ir Saulius dar labiau bijojo Dovydo; ir Saulius tapo nuolatiniu Dovydo priešu.'),
  (@b9, 18, 30, 'Tada išėjo filistinų kunigaikščiai; ir įvyko, jog jiems išėjus Dovydas elgėsi daug išmintingiau už visus Sauliaus tarnus; taip, kad jo vardas buvo labai gerbiamas.'),
  (@b9, 19, 1, 'Ir Saulius kalbėjo savo sūnui Jonatanui ir visiems savo tarnams, kad jie nužudytų Dovydą.'),
  (@b9, 19, 2, 'Bet Sauliaus sūnus Jonatanas labai gėrėjosi Dovydu; ir Jonatanas pranešė Dovydui, sakydamas: „Mano tėvas Saulius siekia tave nužudyti; todėl dabar, meldžiu tave, saugokis iki ryto, lik slaptoje vietoje ir pasislėpk;'),
  (@b9, 19, 3, 'o aš išėjęs stovėsiu šalia savo tėvo ant lauko, kur tu esi, ir kalbėsiu apie tave savo tėvui; ir, ką pamatęs, tau tai pranešiu“.'),
  (@b9, 19, 4, 'Jonatanas gerai kalbėjo apie Dovydą savo tėvui Sauliui ir jam tarė: „Tenenusideda karalius prieš savo tarną, Dovydą; kadangi jis prieš tave nenusidėjo, ir kadangi jo darbai tau buvo labai geri;'),
  (@b9, 19, 5, 'nes jis padėjo savo gyvybę į savo rankas ir užmušė filistiną, ir VIEŠPATS įvykdė didelį išgelbėjimą visam Izraeliui; tu tai matei ir džiaugeis; tai kodėl nori nusidėti prieš nekaltą kraują, nužudydamas Dovydą be priežasties?“'),
  (@b9, 19, 6, 'Ir Saulius paklausė Jonatano balso; ir Saulius prisiekė: „Kaip VIEŠPATS gyvas, jis nebus nužudytas“.'),
  (@b9, 19, 7, 'Jonatanas pašaukė Dovydą, ir Jonatanas jam pranešė visus šituos dalykus. Ir Jonatanas atvedė Dovydą pas Saulių, ir jis buvo jo akivaizdoje, kaip ir praeityje.'),
  (@b9, 19, 8, 'Ir vėl buvo karas; ir Dovydas išėjo ir kovojo su filistinais, ir juos žudė didelėmis žudynėmis; ir jie bėgo nuo jo.'),
  (@b9, 19, 9, 'Ir pikta dvasia nuo VIEŠPATIES buvo ant Sauliaus, kai jis sėdėjo savo namuose su ietimi savo rankoje; o Dovydas grojo savo ranka.'),
  (@b9, 19, 10, 'Ir Saulius siekė ietimi prismeigti Dovydą prie sienos; bet jis paspruko iš Sauliaus akivaizdos, ir jis įsmeigė ietį į sieną; ir Dovydas pabėgo ir išsigelbėjo tą naktį.'),
  (@b9, 19, 11, 'Saulius dar siuntė pasiuntinius į Dovydo namus, kad jį stebėtų ir ryte jį nužudytų; ir Dovydo žmona Mikalė jam pranešė, sakydama: „Jei šiąnakt negelbėsi savo gyvybės, rytoj būsi nužudytas“.'),
  (@b9, 19, 12, 'Taigi Mikalė nuleido Dovydą pro langą; ir jis nuėjęs pabėgo ir išsigelbėjo.'),
  (@b9, 19, 13, 'Ir Mikalė, paėmusi atvaizdą, paguldė jį į lovą, jo priegalviui padėjo ožkos šerių pagalvę ir apklojo jį audeklu.'),
  (@b9, 19, 14, 'Ir kai Saulius atsiuntė pasiuntinius Dovydo suimti, ji tarė: „Jis serga“.'),
  (@b9, 19, 15, 'Ir Saulius vėl siuntė pasiuntinius Dovydo pamatyti, sakydamas: „Atneškite jį aukštyn su lova pas mane, kad nužudyčiau jį“.'),
  (@b9, 19, 16, 'Ir pasiuntiniams įėjus, štai lovoje buvo atvaizdas su ožkos šerių pagalve jo priegalviui.'),
  (@b9, 19, 17, 'Ir Saulius tarė Mikalei: „Kodėl mane taip apgavai ir išleidai mano priešą, kad jis išsigelbėtų?“ O Mikalė atsakė Sauliui: „Jis man sakė: ‘Paleisk mane; kodėl turėčiau nužudyti tave’?“'),
  (@b9, 19, 18, 'Taip Dovydas, pabėgęs ir išsigelbėjęs, atėjo pas Samuelį į Ramą ir jam papasakojo viską, ką Saulius jam buvo padaręs. Ir jis bei Samuelis nuėję apsigyveno Najote.'),
  (@b9, 19, 19, 'Ir Sauliui buvo pranešta, sakant: „Štai Dovydas yra Najote, Ramoje“.'),
  (@b9, 19, 20, 'Ir Saulius siuntė pasiuntinius Dovydo suimti; ir kai jie pamatė būrį pranašaujančių pranašų ir Samuelį stovintį, jiems paskirtą vadovauti, Dievo Dvasia buvo ant Sauliaus pasiuntinių, ir jie taip pat pranašavo.'),
  (@b9, 19, 21, 'Ir kai Sauliui tai buvo pranešta, jis siuntė kitus pasiuntinius, bet ir jie taip pat pranašavo. Ir Saulius vėl siuntė pasiuntinius trečią kartą, bet jie irgi pranašavo.'),
  (@b9, 19, 22, 'Po to ir jis ėjo į Ramą ir atėjo prie didžiojo šulinio, esančio Sechuve; ir jis paklausė, sakydamas: „Kur yra Samuelis ir Dovydas?“ Ir vienas tarė: „Štai jie yra Najote, Ramoje“.'),
  (@b9, 19, 23, 'Ir jis ėjo ten į Najotą Ramoje; ir Dievo Dvasia buvo taip pat ir ant jo, ir jis ėjo toliau ir pranašavo, kol atėjo į Najotą Ramoje.'),
  (@b9, 19, 24, 'Ir jis irgi nusivilko savo drabužius ir taip pat pranašavo Samuelio akivaizdoje, ir gulėjo nuogas visą tą dieną ir visą tą naktį. Todėl sako: „Ar ir Saulius yra tarp pranašų?“'),
  (@b9, 20, 1, 'Ir Dovydas pabėgo iš Najoto Ramoje ir atėjęs tarė Jonatano akivaizdoje: „Ką aš padariau? Kokia yra mano neteisybė? Ir kokia mano nuodėmė tavo tėvo akivaizdoje, kad jis ieško mano gyvybės?“'),
  (@b9, 20, 2, 'Ir jis jam tarė: „Gink Dieve; tu nemirsi; štai mano tėvas nedarys nieko didelio ar menko, man to nepasakęs; ir kodėl mano tėvas turėtų slėpti nuo manęs šitą dalyką? Taip nėra“.'),
  (@b9, 20, 3, 'Ir Dovydas dar prisiekė ir tarė: „Tavo tėvas gerai žino, kad esu radęs malonę tavo akyse; ir jis sako: ‘Tegul Jonatanas to nežino, kad nesisielotų’; bet tikrai, kaip VIEŠPATS gyvas ir kaip gyva tavo siela, tarp manęs ir mirties yra tik žingsnis“.'),
  (@b9, 20, 4, 'Tada Jonatanas tarė Dovydui: „Aš tau padarysiu, ko tik trokšta tavo siela“.'),
  (@b9, 20, 5, 'Ir Dovydas tarė Jonatanui: „Štai rytoj yra jaunas mėnulis, ir aš turėsiu sėstis su karaliumi prie valgio; bet leisk man eiti, kad pasislėpčiau lauke iki trečios dienos vakaro.'),
  (@b9, 20, 6, 'Jei tavo tėvas tikrai manęs pasiges, tada sakyk: ‘Dovydas labai prašė manęs leidimo, kad galėtų nubėgti į savo miestą Betliejų; nes ten yra metinė auka visai šeimai’.'),
  (@b9, 20, 7, 'Jei jis taip sakys: ‘Gerai’; tai tavo tarnas turės ramybę; bet jei jis bus labai užsirūstinęs, tada žinok, kad jis yra numatęs pikta.'),
  (@b9, 20, 8, 'Todėl pasielk palankiai su savo tarnu; nes tu įtraukei savo tarną į VIEŠPATIES sandorą su tavimi; tačiau jei manyje yra neteisybė, tu pats nužudyk mane; nes kodėl turėtum mane nuvesti pas savo tėvą?“'),
  (@b9, 20, 9, 'Ir Jonatanas tarė: „Tai tebūna toli nuo tavęs; nes jei tikrai žinočiau, kad mano tėvas yra numatęs, kad tave ištiktų pikta, tai argi tau to nepraneščiau?“'),
  (@b9, 20, 10, 'Tada Dovydas tarė Jonatanui: „Kas man praneš? O ką, jei tavo tėvas šiurkščiai tau atsakys?“'),
  (@b9, 20, 11, 'Ir Jonatanas tarė Dovydui: „Eikš, išeikime ant lauko“. Ir jie abu išėjo ant lauko.'),
  (@b9, 20, 12, 'Ir Jonatanas tarė Dovydui: „O VIEŠPATIE, Izraelio Dieve, kai bet kuriuo laiku rytoj ar trečią dieną būsiu ištyręs savo tėvą, ir štai jei yra gerai dėl Dovydo, ir tada aš nesiųsiu pas tave ir tau nepranešiu;'),
  (@b9, 20, 13, 'tegul VIEŠPATS padaro Jonatanui taip ir dar daugiau; bet jei mano tėvui patiktų tau daryti pikta, tada aš tau tai pranešiu ir tave išleisiu, kad galėtum eiti ramybėje; ir VIEŠPATS tebūna su tavimi, kaip jis buvo su mano tėvu.'),
  (@b9, 20, 14, 'O tu man parodyk VIEŠPATIES gerumą ne tik kol dar esu gyvas, kad aš nemirčiau;'),
  (@b9, 20, 15, 'bet taip pat neatkirsk per amžius savo gerumo nuo mano namų, net ir tada, kai VIEŠPATS bus iškirtęs Dovydo priešus, kiekvieną nuo žemės paviršiaus“.'),
  (@b9, 20, 16, 'Taip Jonatanas sudarė sandorą su Dovydo namais, sakydamas: „Tegul VIEŠPATS to pareikalauja iš Dovydo priešų rankos“.'),
  (@b9, 20, 17, 'Ir Jonatanas vėl prisaikdino Dovydą, nes mylėjo jį; nes jis mylėjo jį, kaip mylėjo savo paties sielą.'),
  (@b9, 20, 18, 'Po to Jonatanas tarė Dovydui: „Rytoj jaunas mėnulis; ir tavęs pasiges, nes tavo vieta bus tuščia.'),
  (@b9, 20, 19, 'Ir išbuvęs tris dienas, greitai eik žemyn ir ateik į tą vietą, kurioje pasislėpei kai buvo vykdomas anas reikalas, ir pasilik šalia Ezelio akmens.'),
  (@b9, 20, 20, 'O aš iššausiu tris strėles į jo pusę, lyg šaučiau į taikinį.'),
  (@b9, 20, 21, 'Ir štai aš siųsiu berniuką, sakydamas: ‘Eik, surask strėles’. Jei aiškiai pasakysiu berniukui: ‘Štai strėlės yra šioje pusėje nuo tavęs, paimk jas’, tada tu ateik, nes tau yra taika, ir nėra žalos; kaip VIEŠPATS gyvas.'),
  (@b9, 20, 22, 'Bet jei taip sakysiu jaunuoliui: ‘Štai strėlės yra už tavęs’, tai eik savo keliu; nes VIEŠPATS tave išsiunčia.'),
  (@b9, 20, 23, 'O dėl dalyko, apie kurį aš ir tu kalbėjome, štai VIEŠPATS tebūna tarp tavęs ir manęs per amžius“.'),
  (@b9, 20, 24, 'Taigi Dovydas pasislėpė laukuose; o jaunam mėnuliui atėjus, karalius atsisėdo valgyti maisto.'),
  (@b9, 20, 25, 'Ir karalius atsisėdo į savo vietą, kaip kitais kartais – į vietą prie sienos; Jonatanas atsistojo ir Abneras atsisėdo prie Sauliaus pusės, o Dovydo vieta buvo tuščia.'),
  (@b9, 20, 26, 'Tačiau tą dieną Saulius nieko nesakė; nes jis manė: „Kas nors jam bus atsitikę, jis yra nešvarus; tikrai jis yra nešvarus“.'),
  (@b9, 20, 27, 'Ir įvyko rytojaus dieną, antrąją mėnesio dieną, kad Dovydo vieta buvo tuščia; ir Saulius tarė savo sūnui Jonatanui: „Kodėl Jesės sūnus nei vakar, nei šiandien neatėjo prie valgio?“'),
  (@b9, 20, 28, 'Ir Jonatanas atsakė Sauliui: „Dovydas labai prašė manęs leidimo eiti į Betliejų;'),
  (@b9, 20, 29, 'ir jis sakė: ‘Leisk man eiti, meldžiu tave; nes mūsų šeima turi auką mieste; ir mano brolis man įsakė ten būti; o dabar, jei radau palankumą tavo akyse, meldžiu tave, leisk man išeiti ir aplankyti savo brolius’. Todėl jis neatėjo prie karaliaus stalo“.'),
  (@b9, 20, 30, 'Tada užsidegė Sauliaus pyktis ant Jonatano, ir jis jam tarė: „Tu, iškrypusios ir maištingos moters sūnau, argi nežinau, kad esi išsirinkęs Jesės sūnų savo paties gėdai ir savo motinos nuogumo gėdai?'),
  (@b9, 20, 31, 'Nes kol Jesės sūnus gyvena ant žemės, neįsitvirtinsi nei tu, nei tavo karalystė. Taigi dabar nusiųsk ir jį atvesk pas mane, nes jis tikrai mirs“.'),
  (@b9, 20, 32, 'Ir Jonatanas atsakė savo tėvui Sauliui ir jam tarė: „Kodėl jis turi būti nužudytas? Ką jis padarė?“'),
  (@b9, 20, 33, 'Ir Saulius metė į jį ietį, kad jį užmuštų; pagal tai Jonatanas suprato, kad jo tėvas buvo nutaręs nužudyti Dovydą.'),
  (@b9, 20, 34, 'Taigi smarkiai įpykęs, Jonatanas atsistojo nuo stalo ir nevalgė maisto antrąją mėnesio dieną; nes jis sielojosi dėl Dovydo, kadangi jo tėvas padarė jam gėdą.'),
  (@b9, 20, 35, 'Ir įvyko ryte, kad Jonatanas išėjo ant lauko nustatytu su Dovydu laiku, ir mažas berniukas su juo.'),
  (@b9, 20, 36, 'Ir jis tarė savo berniukui: „Bėk, surask dabar strėles, kurias aš šaunu“. Ir berniukui bėgant, jis iššovė strėlę anapus jo.'),
  (@b9, 20, 37, 'Ir berniukui atėjus į vietą strėlės, kurią Jonatanas buvo iššovęs, Jonatanas šaukė berniukui iš paskos, ir sakė: „Ar strėlė nėra anapus tavęs?“'),
  (@b9, 20, 38, 'Ir Jonatanas šaukė berniukui iš paskos: „Lėk, skubėk, nestovėk“. Ir Jonatano berniukas surinko strėles ir atėjo pas savo šeimininką.'),
  (@b9, 20, 39, 'Bet berniukas nieko nežinojo; tik Jonatanas ir Dovydas žinojo tą reikalą.'),
  (@b9, 20, 40, 'Ir Jonatanas davė savo ginklus savo berniukui ir jam tarė: „Eik, nunešk juos į miestą“.'),
  (@b9, 20, 41, 'Ir kai tik berniukas nuėjo, Dovydas pakilo iš vietos pietų link, parpuolė veidu ant žemės ir tris kartus nusilenkė; ir jie vienas kitą pabučiavo ir vienas su kitu verkė, kol Dovydas pralenkė.'),
  (@b9, 20, 42, 'Ir Jonatanas tarė Dovydui: „Eik ramybėje, kadangi mes abu esame prisiekę VIEŠPATIES vardu, sakydami: ‘VIEŠPATS tebūna tarp manęs ir tavęs, ir tarp mano sėklos bei tavo sėklos per amžius. Ir jis pakilo ir išėjo; o Jonatanas nuėjo į miestą’“.'),
  (@b9, 21, 1, 'Tada Dovydas atėjo į Nobą pas kunigą Ahimelechą; o Ahimelechas išsigando sutikdamas Dovydą, ir jam tarė: „Kodėl tu esi vienas, ir nei vieno nėra su tavimi?“'),
  (@b9, 21, 2, 'Ir Dovydas tarė kunigui Ahimelechui: „Karalius man įsakė vieną reikalą ir man sakė: ‘Niekas neturi nieko žinoti apie tą reikalą, dėl kurio tave siunčiu ir ką tau įsakiau; ir aš paskyriau savo tarnus tokioje ir tokioje vietoje.'),
  (@b9, 21, 3, 'Taigi dabar, kas yra po tavo ranka? Duok man į ranką penkis kepalus duonos arba kas šiaip atsiras“.'),
  (@b9, 21, 4, 'Ir kunigas atsakė Dovydui ir tarė: „Nėra paprastos duonos po mano ranka, bet yra pašvęsta duona; jei tik tie jaunuoliai buvo susilaikę bent nuo moterų“.'),
  (@b9, 21, 5, 'Ir Dovydas atsakydamas kunigui, tarė: „Iš tiesų, moterys buvo sulaikytos nuo mūsų apie šias tris dienas, nuo tada, kai aš išėjau, ir jaunuolių indai yra šventi, ir duona tam tikra prasme paprasta, taip, nors šią dieną ji buvo pašvęsta inde“.'),
  (@b9, 21, 6, 'Taigi kunigas jam davė pašvęstos duonos; nes ten nebuvo kitos duonos, kaip tik parodomoji duona, kuri buvo paimta iš VIEŠPATIES akivaizdos, kad būtų padėta karšta duona tą dieną, kai ana buvo pašalinta.'),
  (@b9, 21, 7, 'Na, o tą dieną ten buvo sulaikytas VIEŠPATIES akivaizdoje vienas vyras iš Sauliaus tarnų; o jo vardas buvo Doegas, edomietis, vyriausias iš kerdžių, priklausančių Sauliui.'),
  (@b9, 21, 8, 'Ir Dovydas tarė Ahimelechui: „Ar neturi čia po ranka ieties ar kalavijo? Nes nei savo kalavijo, nei savo ginklų nepasiėmiau, kadangi karaliaus reikalas buvo skubus“.'),
  (@b9, 21, 9, 'Ir kunigas tarė: „Kalavijas filistino Galijoto, kurį nužudei Elos slėnyje, štai jis yra čia įvyniotas į audinį už efodo; jei nori jį pasiimti, tai imk; nes be jo čia kito nėra“. Ir Dovydas tarė: „Nėra jam lygaus; duok man jį“.'),
  (@b9, 21, 10, 'Ir tą dieną Dovydas pakilęs bėgo bijodamas Sauliaus ir nuėjo pas Gato karalių Achišą.'),
  (@b9, 21, 11, 'Ir Achišo tarnai jam sakė: „Argi šitas ne Dovydas, šalies karalius? Argi ne apie jį jos dainavo viena kitai šokdamos ir sakydamos: ‘Saulius užmušė savo tūkstančius, o Dovydas savo dešimtis tūkstančių’?“'),
  (@b9, 21, 12, 'Ir Dovydas įsidėjo šituos žodžius į širdį ir labai bijojo Gato karaliaus Achišo.'),
  (@b9, 21, 13, 'Ir jis pakeitė savo elgesį jų akivaizdoje ir apsimetė pamišėliu jų rankose, ir braižė ant vartų durų, ir varvino seiles ant savo barzdos.'),
  (@b9, 21, 14, 'Tada Achišas tarė savo tarnams: „Štai matote, tas vyras yra pamišėlis; tai kodėl jį atvedėte pas mane?'),
  (@b9, 21, 15, 'Ar man reikia pamišėlių, kad atvedėte šitą, kad elgtųsi kaip beprotis mano akivaizdoje? Ar šitas turėtų ateiti į mano namus?“'),
  (@b9, 22, 1, 'Taigi Dovydas išėjo iš ten ir paspruko į Adulamo olą; ir tai išgirdę jo broliai ir visi jo tėvo namai, nuėjo ten žemyn pas jį.'),
  (@b9, 22, 2, 'Ir pas jį rinkosi kiekvienas prislėgtasis, kiekvienas prasiskolinęs ir kiekvienas nepatenkintasis; ir jis tapo jiems vadu; ir su juo buvo apie keturis šimtus vyrų.'),
  (@b9, 22, 3, 'Ir iš ten Dovydas nuėjo į Moabo Micpę; ir jis tarė Moabo karaliui: „Leisk, meldžiu tave, mano tėvui ir mano motinai išeiti ir būti pas jus, kol sužinosiu, ką Dievas man darys“.'),
  (@b9, 22, 4, 'Ir jis atvedė juos Moabo karaliaus akivaizdon; ir jie apsigyveno pas jį, kol Dovydas buvo tvirtovėje.'),
  (@b9, 22, 5, 'Ir pranašas Gadas tarė Dovydui: „Nepasilik tvirtovėje; išeik ir eik į Judos šalį“. Tada Dovydas išėjo ir atėjo į Hereto mišką.'),
  (@b9, 22, 6, 'Kai Saulius išgirdo, kad Dovydas surastas ir su juo esantys vyrai (na, o Saulius pasiliko Gibėjoje po medžiu Ramoje, turėdamas rankoje savo ietį ir visiems jo tarnams stovint aplink jį),'),
  (@b9, 22, 7, 'tada Saulius tarė savo tarnams, stovintiems aplink jį: „Na, klausykite, benjaminai; ar jums visiems Jesės sūnus duos laukų bei vynuogynų ir jus visus padarys tūkstančių vadais ir šimtų vadais;'),
  (@b9, 22, 8, 'kad visi susimokėte prieš mane ir nėra nei vieno, kuris būtų man pranešęs, kad mano sūnus padarė sąjungą su Jesės sūnumi, ir nėra iš jūsų nei vieno, kuris būtų manęs gailėjęsis ar man pranešęs, kad mano sūnus sukurstė prieš mane mano tarną, kad tykotų, kaip šią dieną?“'),
  (@b9, 22, 9, 'Tada edomietis Doegas, kuris buvo paskirtas vadovauti Sauliaus tarnams, atsiliepdamas tarė: „Aš mačiau Jesės sūnų ateinantį į Nobą pas Ahitubo sūnų Ahimelechą.'),
  (@b9, 22, 10, 'Ir jis dėl jo teiravosi VIEŠPATIES ir davė jam maisto, ir davė jam filistino Galijoto kalaviją“.'),
  (@b9, 22, 11, 'Tada Saulius siuntė pakviesti kunigą Ahimelechą, Ahitubo sūnų ir visus jo tėvo namus, kunigus, esančius Nobe; ir jie visi atėjo pas karalių.'),
  (@b9, 22, 12, 'Ir Saulius tarė: „Klausyk dabar, Ahitubo sūnau“. Ir jis atsakė: „Aš čia, mano viešpatie“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b9, 22, 13, 'Ir Saulius jam tarė: „Kodėl susimokėte prieš mane, tu ir Jesės sūnus, kad davei jam duonos bei kalaviją ir dėl jo klausei Dievo, kad jis pakiltų prieš mane, kad tykotų, kaip šią dieną?“'),
  (@b9, 22, 14, 'Tada Ahimelechas, atsakydamas karaliui, tarė: „O kuris tarp visų tavo tarnų yra toks ištikimas, kaip Dovydas, kuris yra karaliaus žentas, ir tau įsakius eina ir yra gerbiamas tavo namuose?'),
  (@b9, 22, 15, 'Ar aš tada pradėjau klausti Dievo dėl jo? Tebūna tai toli nuo manęs; tegul karalius nieko neprimeta savo tarnui nei visiems mano tėvo namams; nes tavo tarnas nežinojo apie visa tai nieko, nei mažai, nei daug“.'),
  (@b9, 22, 16, 'Ir karalius tarė: „Tu tikrai mirsi, Ahimelechai, tu ir visi tavo tėvo namai“.'),
  (@b9, 22, 17, 'Ir karalius tarė pėstininkams, stovintiems aplink jį: „Pasisukite ir nužudykite VIEŠPATIES kunigus; kadangi ir jų ranka yra su Dovydu ir kadangi jie žinojo, kai jis pabėgo, o man nepranešė“. Bet karaliaus tarnai nenorėjo ištiesti rankų, kad užpultų VIEŠPATIES kunigus.'),
  (@b9, 22, 18, 'Ir karalius tarė Doegui: „Tu pasisuk ir pulk kunigus“. Ir edomietis Doegas pasisuko ir užpuolė kunigus, ir tą dieną nužudė aštuoniasdešimt penkis asmenis, kurie nešiojo lininį efodą.'),
  (@b9, 22, 19, 'Ir kunigų miestą Nobą jis iškirto kalavijo ašmenimis: vyrus ir moteris, vaikus ir žinduklius, jaučius, asilus ir avis, kalavijo ašmenimis.'),
  (@b9, 22, 20, 'O vienas iš Ahitubo sūnaus Ahimelecho sūnų, vardu Abjataras, išsigelbėjo ir nubėgo paskui Dovydą.'),
  (@b9, 22, 21, 'Ir Abjataras pranešė Dovydui, kad Saulius išžudė VIEŠPATIES kunigus.'),
  (@b9, 22, 22, 'Ir Dovydas tarė Abjatarui: „Aš žinojau tą dieną, kai ten buvo edomietis Doegas, kad jis tikrai praneš Sauliui; aš esu visų tavo tėvo namų asmenų mirties priežastis.'),
  (@b9, 22, 23, 'Pasilik pas mane, nebijok; nes kas ieško mano gyvybės, ieško ir tavo gyvybės; bet su manimi tu būsi saugus“.'),
  (@b9, 23, 1, 'Tada jie pranešė Dovydui, sakydami: „Štai filistinai kovoja prieš Keilą, ir jie plėšia klojimus“.'),
  (@b9, 23, 2, 'Todėl Dovydas teiravosi VIEŠPATIES, sakydamas: „Ar man eiti ir sumušti šituos filistinus?“ Ir VIEŠPATS tarė Dovydui: „Eik, sumušk filistinus ir išgelbėk Keilą“.'),
  (@b9, 23, 3, 'Ir Dovydo vyrai jam tarė: „Štai mes čia, Judoje, bijome; tai kaip dar labiau, jei ateisime į Keilą prieš filistinų kariuomenes?“'),
  (@b9, 23, 4, 'Tada Dovydas vėl pasiklausė VIEŠPATIES. Ir VIEŠPATS jam atsakė ir tarė: „Kelkis, eik žemyn į Keilą; nes aš atiduosiu filistinus į tavo rankas“.'),
  (@b9, 23, 5, 'Taip Dovydas ir jo vyrai nuėjo į Keilą, kovojo su filistinais, nuvarė jų galvijus ir sumušė juos smarkiomis žudynėmis. Taip Dovydas išgelbėjo Keilos gyventojus.'),
  (@b9, 23, 6, 'Ir įvyko, kai Ahimelecho sūnus Abjataras pabėgo pas Dovydą į Keilą, jis atėjo žemyn su efodu savo rankoje.'),
  (@b9, 23, 7, 'O Sauliui buvo pranešta, kad Dovydas atėjo į Keilą. Ir Saulius tarė: „Dievas jį atidavė į mano rankas; nes jis yra užrakintas, įeidamas į miestą, turintį vartus ir skląsčius“.'),
  (@b9, 23, 8, 'Ir Saulius sušaukė visą tautą į karą, kad eitų žemyn į Keilą, Dovydo ir jo vyrų apgulti.'),
  (@b9, 23, 9, 'Ir Dovydas sužinojo, kad Saulius slapčia planavo pikta prieš jį; ir jis tarė kunigui Abjatarui: „Atnešk čia efodą“.'),
  (@b9, 23, 10, 'Tada Dovydas tarė: „O VIEŠPATIE, Izraelio Dieve, tavo tarnas tikrai išgirdo, kad Saulius siekia ateiti į Keilą, kad sunaikintų miestą dėl manęs.'),
  (@b9, 23, 11, 'Ar Keilos žmonės atiduos mane į jo rankas? Ar Saulius ateis žemyn, kaip tavo tarnas yra girdėjęs? O VIEŠPATIE, Izraelio Dieve, meldžiu tave, pranešk savo tarnui“. Ir VIEŠPATS tarė: „Jis ateis žemyn“.'),
  (@b9, 23, 12, 'Tada Dovydas tarė: „Ar Keilos žmonės atiduos mane ir mano vyrus į Sauliaus rankas?“ Ir VIEŠPATS tarė: „Jie tave atiduos“.'),
  (@b9, 23, 13, 'Tada Dovydas ir jo vyrai, kurių buvo apie šešis šimtus vyrų, pakilę išėjo iš Keilos ir ėjo, kur galėjo eiti. Ir Sauliui buvo pranešta, kad Dovydas pabėgęs iš Keilos; ir jis liovėsi ir nebeišėjo.'),
  (@b9, 23, 14, 'Ir Dovydas apsistojo dykumoje, tvirtovėse ir pasiliko kalne, Zifo dykumoje. Ir Saulius kiekvieną dieną jo ieškojo, bet Dievas jo neatidavė į jo rankas.'),
  (@b9, 23, 15, 'Ir Dovydas matė, kad Saulius buvo išėjęs jo gyvybės ieškoti; o Dovydas buvo Zifo dykumoje, miške.'),
  (@b9, 23, 16, 'Ir Sauliaus sūnus Jonatanas pakilęs nuėjo pas Dovydą į mišką ir sustiprino jo ranką Dieve.'),
  (@b9, 23, 17, 'Ir jis jam tarė: „Nebijok; nes tavęs neatras mano tėvo Sauliaus ranka; ir tu būsi karaliumi Izraeliui, o aš būsiu antras po tavęs; ir tai žino ir mano tėvas Saulius“.'),
  (@b9, 23, 18, 'Ir jie abu sudarė sandorą VIEŠPATIES akivaizdoje; ir Dovydas pasiliko miške, o Jonatanas nuėjo į savo namus.'),
  (@b9, 23, 19, 'Tada atėjo aukštyn zifiečiai pas Saulių į Gibėją, sakydami: „Argi Dovydas nesislapsto pas mus tvirtovėse, miške, Hachilos kalvoje, esančioje Ješimono pietuose?'),
  (@b9, 23, 20, 'Taigi dabar, o karaliau, ateik žemyn pagal visą savo sielos troškimą ateiti žemyn; o mūsų reikalas bus jį atiduoti į karaliaus rankas“.'),
  (@b9, 23, 21, 'Ir Saulius tarė: „Būkite VIEŠPATIES palaiminti; nes pasigailėjote manęs.'),
  (@b9, 23, 22, 'Eikite, meldžiu jus, dar paruoškite, sužinokite ir stebėkite jo vietą, kur jis dažnai ateina, ir kas jį ten matė; nes man buvo pranešta, kad jis gudriai elgiasi.'),
  (@b9, 23, 23, 'Todėl stebėkite ir sužinokite visas slėptuves, kuriose jis slepiasi, ir sugrįžkite pas mane su tikrumu, ir aš eisiu su jumis; ir įvyks, jei jis bus šalyje, tai aš jo ieškosiu visuose Judos tūkstančiuose“.'),
  (@b9, 23, 24, 'Ir pakilę jie nuėjo į Zifą pirma Sauliaus; bet Dovydas ir jo vyrai buvo Maono dykumoje, lygumoje, į pietus nuo Ješimono.'),
  (@b9, 23, 25, 'Taip pat Saulius ir jo vyrai ėjo jo ieškoti. Ir pranešė Dovydui; todėl jis atėjo žemyn į uolą ir apsistojo Maono dykumoje. Ir tai išgirdęs, Saulius vijosi Dovydą Maono dykumoje.'),
  (@b9, 23, 26, 'Ir Saulius ėjo šia kalno puse, o Dovydas ir jo vyrai ana kalno puse; ir Dovydas pasiskubino, kad paspruktų dėl Sauliaus baimės; nes Saulius ir jo vyrai apsupo Dovydą ir jo vyrus, kad juos sugautų.'),
  (@b9, 23, 27, 'Bet atėjo pasiuntinys pas Saulių, sakydamas: „Paskubėk, ateik; nes filistinai įsiveržė į šalį“.'),
  (@b9, 23, 28, 'Todėl Saulius sugrįžo nuo vijimosi paskui Dovydą ir ėjo prieš filistinus; todėl tą vietą pavadino Sela-Hamachlekotu.'),
  (@b9, 23, 29, 'Ir Dovydas ėjo iš ten aukštyn ir gyveno En-Gedžio tvirtovėse.'),
  (@b9, 24, 1, 'Ir įvyko, kai Saulius buvo sugrįžęs nuo vijimosi paskui filistinus, jam buvo pranešta, sakant: „Štai Dovydas yra En-Gedžio dykumoje“.'),
  (@b9, 24, 2, 'Tada Saulius pasiėmė tris tūkstančius rinktinių vyrų iš viso Izraelio ir ėjo ieškoti Dovydo ir jo vyrų ant laukinių ožkų uolų.'),
  (@b9, 24, 3, 'Ir jis atėjo prie avidžių, prie kelio, kur buvo ola; ir Saulius įėjo apdengti savo pėdas; o Dovydas ir jo vyrai pasiliko olos šonuose.'),
  (@b9, 24, 4, 'Ir Dovydo vyrai jam tarė: „Štai diena, apie kurią VIEŠPATS tau pasakė: ‘Štai aš atiduosiu tavo priešą į tavo rankas, kad jam darytum taip, kaip tau atrodo gerai’“. Tada Dovydas pakilo ir slapta atpjovė Sauliaus apsiausto skverną.'),
  (@b9, 24, 5, 'Ir paskui įvyko, kad Dovydo širdis ištiko jį dėl to, jog jis atpjovė Sauliaus skverną.'),
  (@b9, 24, 6, 'Ir jis sakė savo vyrams: „Apsaugok, VIEŠPATIE, kad daryčiau tokį dalyką savo valdovui, VIEŠPATIES pateptajam, kad ištiesčiau prieš jį savo ranką, nes jis yra VIEŠPATIES pateptasis“.'),
  (@b9, 24, 7, 'Taip Dovydas sustabdė savo tarnus šitais žodžiais ir jiems neleido pakilti prieš Saulių. Bet Saulius pakilo iš olos ir ėjo savo keliu.'),
  (@b9, 24, 8, 'Paskui ir Dovydas pakilo, išėjo iš olos ir šaukė Sauliui iš paskos, sakydamas: „Mano viešpatie, karaliau“. Ir Sauliui pažvelgus atgal, Dovydas palinko veidu į žemę ir nusilenkė.'),
  (@b9, 24, 9, 'Ir Dovydas tarė Sauliui: „Kodėl klausai žmonių kalbų, sakant: ‘Štai Dovydas siekia tau pakenkti’?'),
  (@b9, 24, 10, 'Štai šią dieną pamatė tavo akys, kaip VIEŠPATS šiandien atidavė tave į mano rankas oloje; ir kai kurie sakė man tave nužudyti; bet mano akys pasigailėjo tavęs; ir aš sakiau: ‘Neištiesiu rankos prieš savo viešpatį; nes jis yra VIEŠPATIES pateptasis’.'),
  (@b9, 24, 11, 'Be to, mano tėve, pažiūrėk, taip, pažiūrėk į savo apsiausto skverną mano rankoje; iš to, kad atpjoviau tavo apsiausto skverną, o tavęs nenužudžiau, žinok ir matyk, jog mano rankoje nėra nei pikto, nei nusižengimo, ir aš nesu prieš tave nusidėjęs; tačiau tu medžioji mano sielą, kad ją atimtum.'),
  (@b9, 24, 12, 'Tegul VIEŠPATS teisia tarp manęs ir tavęs, ir tegul VIEŠPATS tau atkeršija už mane; bet mano ranka nebus ant tavęs.'),
  (@b9, 24, 13, 'Kaip senolių patarlė sako: ‘Iš nedorėlių išeina nedorybė’; bet mano ranka nebus ant tavęs.'),
  (@b9, 24, 14, 'Paskui ką išėjo Izraelio karalius? Ką tu vejiesi? Padvėsusį šunį, blusą.'),
  (@b9, 24, 15, 'Todėl VIEŠPATS tebūna teisėjas ir tegul teisia tarp manęs ir tavęs, ir tepamato, ir tegina mano bylą, ir teišgelbsti mane iš tavo rankos“.'),
  (@b9, 24, 16, 'Ir įvyko, kai Dovydas baigė kalbėti šituos žodžius Sauliui, Saulius tarė: „Ar tai tavo balsas, mano sūnau Dovydai?“ Ir Saulius pakeltu balsu verkė.'),
  (@b9, 24, 17, 'Ir jis tarė Dovydui: „Tu esi teisesnis už mane; nes tu man atlyginai geru, kai aš tau atlyginau piktu.'),
  (@b9, 24, 18, 'Ir tu šią dieną parodei, kaip gerai pasielgei su manimi: nors VIEŠPATS buvo atidavęs mane į tavo rankas, tačiau manęs nenužudei.'),
  (@b9, 24, 19, 'Nes jei kas aptinka savo priešą, ar jis paleidžia jį sveiką eiti? Todėl VIEŠPATS teatlygina tau geru už tai, ką šią dieną man padarei.'),
  (@b9, 24, 20, 'O dabar, štai aš gerai žinau, kad tu tikrai būsi karaliumi ir kad Izraelio karalystė bus įtvirtinta tavo rankoje.'),
  (@b9, 24, 21, 'Todėl dabar man prisiek VIEŠPAČIU, kad neiškirsi mano sėklos po manęs ir kad neišnaikinsi mano vardo iš mano tėvo namų“.'),
  (@b9, 24, 22, 'Ir Dovydas prisiekė Sauliui. Ir Saulius nuėjo namo; bet Dovydas ir jo vyrai nuėjo aukštyn į tvirtovę.'),
  (@b9, 25, 1, 'Ir Samuelis mirė; ir susirinko visi izraelitai, apraudojo jį ir palaidojo jį jo namuose Ramoje. Ir Dovydas pakilo ir nuėjo žemyn į Parano dykumą.'),
  (@b9, 25, 2, 'Ir Maone buvo vyras, kurio nuosavybė buvo Karmelyje; o tas vyras buvo labai didis, jis turėjo tris tūkstančius avių ir tūkstantį ožkų; ir jis kirpo savo avis Karmelyje.'),
  (@b9, 25, 3, 'Na, o to vyro vardas buvo Nabalas; o jo žmonos vardas Abigailė; ir ji buvo gerai suprantanti moteris ir gražaus veido; bet tas vyras buvo šiurkštus ir piktas savo darbais; ir jis buvo iš Kalebo namų.'),
  (@b9, 25, 4, 'Ir Dovydas išgirdo dykumoje, kad Nabalas kerpąs savo avis.'),
  (@b9, 25, 5, 'Ir Dovydas siuntė dešimt jaunų vyrų, ir Dovydas sakė jaunuoliams: „Eikite aukštyn į Karmelį ir, nuėję pas Nabalą, pasveikinkite jį mano vardu;'),
  (@b9, 25, 6, 'ir taip sakykite gyvenančiam gerovėje: ‘Ramybė tebūna tau, ramybė tebūna tavo namams ir ramybė tebūna viskam, ką tu turi.'),
  (@b9, 25, 7, 'Dabar išgirdau, kad tu turi avių kirpėjų; na, o tavo piemenims, buvusiems su mumis, mes nepadarėme žalos, ir jie nieko nepasigedo visą laiką, kol buvo Karmelyje.'),
  (@b9, 25, 8, 'Pasiklausk savo jaunuolių, ir jie tau pasakys. Tad tegul jaunuoliai randa palankumą tavo akyse; nes atėjome gerą dieną; duok, meldžiu tave, tai, ką ras tavo ranka, savo tarnams ir savo sūnui Dovydui’“.'),
  (@b9, 25, 9, 'Ir Dovydo jaunuoliai atėję kalbėjo Nabalui pagal visus tuos žodžius Dovydo vardu ir nutilo.'),
  (@b9, 25, 10, 'Ir Nabalas atsakė Dovydo tarnams ir tarė: „Kas yra Dovydas? Kas yra Jesės sūnus? Šiandien yra daug tarnų, kurie atitrūkę kiekvienas nuo savo valdovo.'),
  (@b9, 25, 11, 'Tad ar man imti savo duoną, savo vandenį ir savo mėsą, kurią papjoviau savo avių kirpėjams, ir duoti tai vyrams, apie kuriuos nežinau, iš kur jie yra?“'),
  (@b9, 25, 12, 'Taip Dovydo jaunuoliai pasuko savo keliu, sugrįžo ir atėję jam pranešė visus šituos pasakymus.'),
  (@b9, 25, 13, 'Ir Dovydas tarė savo vyrams: „Prisijuoskite kiekvienas savo kalaviją“. Ir jie prisijuosė kiekvienas savo kalaviją; Dovydas irgi prisijuosė savo kalaviją; ir ėjo aukštyn paskui Dovydą apie keturis šimtus vyrų; o du šimtai pasiliko prie daiktų.'),
  (@b9, 25, 14, 'Bet vienas iš jaunuolių pranešė Nabalo žmonai Abigailei, sakydamas: „Štai Dovydas siuntė pasiuntinius iš dykumos mūsų valdovo pasveikinti; o jis išplūdo juos.'),
  (@b9, 25, 15, 'Bet tie vyrai buvo mums labai geri, mums nebuvo padaryta jokios žalos, ir nieko nepasigedome, kol bendravome su jais, būdami laukuose;'),
  (@b9, 25, 16, 'siena jie buvo mums ir naktį, ir dieną, visą tą laiką, kol buvome su jais ganydami avis.'),
  (@b9, 25, 17, 'Taigi dabar žinok ir apgalvok, ką darysi; nes nelaimė nulemta mūsų valdovui ir visiems jo namiškiams; nes jis yra toks Belialo sūnus, kad su juo niekas negali kalbėtis“.'),
  (@b9, 25, 18, 'Tada Abigailė pasiskubino ir paėmė du šimtus kepalų, du indus vyno, penkias paruoštas avis, penkis saikus paskrudintų grūdų, šimtą razinų kekių ir du šimtus figų pyragaičių, ir juos sukrovė ant asilų.'),
  (@b9, 25, 19, 'Ir ji tarė savo tarnams: „Eikite pirma manęs; štai ateinu paskui jus“. Bet ji nesakė savo vyrui Nabalui.'),
  (@b9, 25, 20, 'Ir jai jojant ant asilo, ji leidosi žemyn kalvos priedanga, ir štai Dovydas ir jo vyrai ėjo žemyn jai priešais; ir ji susitiko su jais.'),
  (@b9, 25, 21, 'Na, o Dovydas buvo sakęs: „Iš tikrųjų veltui saugojau viską, ką šitas turi dykumoje, taip, kad niekas neprapuolė iš viso to, kas jam priklauso; o jis man atsilygino piktu už gera.'),
  (@b9, 25, 22, 'Taip ir dar daugiau Dievas tepadaro Dovydo priešams, jei iki ryto šviesos paliksiu iš viso to, kas jam priklauso, bent vieną, kuris šlapinasi į sieną“.'),
  (@b9, 25, 23, 'Ir pamačiusi Dovydą, Abigailė suskubo ir nulipo nuo asilo, parpuolė veidu prieš Dovydą ir nusilenkė iki žemės,'),
  (@b9, 25, 24, 'ir parpuolė prie jo kojų, ir tarė: „Ant manęs, mano viešpatie, ant manęs tebūna ta neteisybė; leisk, meldžiu tave, tavo tarnaitei kalbėti tau klausantis, ir išklausyk savo tarnaitės žodžius.'),
  (@b9, 25, 25, 'Mano viešpats, meldžiu, tenekreipia dėmesio į tą Belialo žmogų Nabalą; nes jis yra toks, koks jo vardas; Nabalas yra jo vardas, ir kvailybė yra su juo; bet aš, tavo tarnaitė, nemačiau savo viešpaties jaunuolių, kuriuos buvai atsiuntęs.'),
  (@b9, 25, 26, 'Taigi dabar, mano viešpatie, kaip VIEŠPATS gyvas ir kaip gyva tavo siela, kadangi VIEŠPATS sulaikė tave, kad neateitum išlieti kraujo ir kad neatkeršytum už save savo paties ranka, tai dabar tavo priešai ir tie, kurie siekia pikto mano viešpačiui, tebūna kaip Nabalas.'),
  (@b9, 25, 27, 'O dabar šitas palaiminimas, kurį tavo tarnaitė atgabeno savo viešpačiui, tebūna paduotas jaunuoliams, kurie seka paskui mano viešpatį.'),
  (@b9, 25, 28, 'Meldžiu tave, atleisk savo tarnaitės nusižengimą; nes VIEŠPATS tikrai padarys mano viešpačiui tvirtus namus; nes mano viešpats kovoja VIEŠPATIES kovas, ir tavyje nerasta pikto per visas tavo dienas.'),
  (@b9, 25, 29, 'Nors žmogus yra pakilęs tavęs persekioti ir tavo sielos ieškoti; bet mano viešpaties siela bus įvyniota į gyvybės ryšulėlį pas VIEŠPATĮ, tavo Dievą; o tavo priešų sielas, jis jas nusvies kaip nuo mėtyklės vidurio.'),
  (@b9, 25, 30, 'Ir įvyks, kai VIEŠPATS bus padaręs mano viešpačiui pagal visą tą gera, kurį jis yra kalbėjęs apie tave, ir bus tave paskyręs valdovu Izraeliui;'),
  (@b9, 25, 31, 'tada tai nebus tau liūdesys nei širdies papiktinimas mano viešpačiui, kad be priežasties išliejai kraują ar kad mano viešpats už save atkeršijo; bet kai VIEŠPATS bus gerai pasielgęs su mano viešpačiu, tada atsimink savo tarnaitę“.'),
  (@b9, 25, 32, 'Ir Dovydas tarė Abigailei: „Tebūna palaimintas VIEŠPATS, Izraelio Dievas, kuris šią dieną atsiuntė tave manęs pasitikti;'),
  (@b9, 25, 33, 'ir tebūna palaimintas tavo patarimas, ir būk palaiminta tu, kuri šią dieną mane sulaikei, kad neateičiau kraujo išlieti ir kad neatkeršyčiau už save savo paties ranka.'),
  (@b9, 25, 34, 'Nes tikrų tikriausiai, kaip gyvas VIEŠPATS, Izraelio Dievas, kuris mane sulaikė, kad tau nepakenkčiau, jei nebūtum paskubėjusi ir atėjusi manęs pasitikti, tikrai iki ryto aušros nebūtų išlikę Nabalui nei vieno, kuris šlapinasi į sieną“.'),
  (@b9, 25, 35, 'Taigi Dovydas priėmė iš jos rankos tai, ką ji jam buvo atgabenusi, ir jai tarė: „Eik aukštyn ramybėje į savo namus; štai aš paklausiau tavo balso ir priėmiau tavo veidą“.'),
  (@b9, 25, 36, 'Ir Abigailė atėjo pas Nabalą; ir štai jis buvo iškėlęs savo namuose puotą, kaip karaliaus puotą; ir Nabalo širdis buvo linksma jo viduje, nes jis buvo labai girtas; todėl ji jam nieko nesakė, nei mažai, nei daug, iki ryto aušros.'),
  (@b9, 25, 37, 'Bet ryte įvyko, kai vynas išgaravo iš Nabalo, ir jo žmona jam papasakojo šituos dalykus, tada apmirė jo širdis jo viduje, ir jis pasidarė kaip akmuo.'),
  (@b9, 25, 38, 'Ir įvyko, kad maždaug po dešimties dienų VIEŠPATS ištiko Nabalą, jog jis mirė.'),
  (@b9, 25, 39, 'Ir išgirdęs, kad Nabalas miręs, Dovydas tarė: „Tebūna palaimintas VIEŠPATS, kuris apgynė bylą dėl mano gėdos iš Nabalo rankos ir sulaikė savo tarną nuo pikto; nes VIEŠPATS sugrąžino Nabalo nedorybę ant jo paties galvos“. Ir Dovydas pasiuntęs kalbėjo Abigailei, kad imtų ją sau į žmonas.'),
  (@b9, 25, 40, 'Ir Dovydo tarnai, atėję pas Abigailę į Karmelį, jai kalbėjo, sakydami: „Dovydas mus atsiuntė pas tave, kad imtų tave sau į žmonas“.'),
  (@b9, 25, 41, 'Ir ji atsikėlė, nusilenkė veidu į žemę ir tarė: „Štai tavo tarnaitė tebūna tarnaitė, kad nuplautų savo viešpaties tarnų kojas“.'),
  (@b9, 25, 42, 'Ir Abigailė pasiskubino, ir atsikėlė, ir jojo ant asilo su savo penkiomis panelėmis, kurios ėjo paskui ją; ir ji ėjo paskui Dovydo pasiuntinius, ir tapo jo žmona.'),
  (@b9, 25, 43, 'Dovydas taip pat ėmė Ahinoamą iš Jezreelio; ir jos abi buvo jo žmonos.'),
  (@b9, 25, 44, 'Bet Saulius davė savo dukterį Mikalę, Dovydo žmoną, Laišo sūnui Palčiui, esančiam iš Galimo.'),
  (@b9, 26, 1, 'Ir zifiečiai atėjo pas Saulių į Gibėją, sakydami: „Argi Dovydas nesislapsto Hachilos kalvoje, esančioje prieš Ješimoną?“'),
  (@b9, 26, 2, 'Tada pakilo Saulius ir ėjo žemyn į Zifo dykumą, su savimi turėdamas tris tūkstančius Izraelio rinktinių vyrų, Dovydo ieškoti Zifo dykumoje.'),
  (@b9, 26, 3, 'Ir Saulius stovyklavo Hachilos kalvoje, esančioje prieš Ješimoną, palei kelią. Bet Dovydas pasiliko dykumoje, ir jis matė, kad Saulius atėjo paskui jį į dykumą.'),
  (@b9, 26, 4, 'Todėl Dovydas išsiuntė žvalgus ir suprato, kad Saulius tikrai buvo atėjęs.'),
  (@b9, 26, 5, 'Ir Dovydas pakilęs atėjo į vietą, kurioje Saulius stovyklavo; ir Dovydas pamatė vietą, kurioje gulėjo Saulius ir Nero sūnus Abneras, jo kariuomenės vadas; ir Saulius gulėjo apkase, o tauta stovyklavo aplink jį.'),
  (@b9, 26, 6, 'Tada Dovydas atsakydamas tarė hetitui Ahimelechui ir Cerujos sūnui Abišajui, Joabo broliui, sakydamas: „Kas eis su manimi žemyn pas Saulių į stovyklą?“ Ir Abišajis tarė: „Aš eisiu žemyn su tavimi“.'),
  (@b9, 26, 7, 'Taip Dovydas ir Abišajis naktį atėjo prie tautos; ir štai Saulius guli užmigęs apkase, o jo ietis įsmeigta į žemę jam prie jo galvavietės; bet Abneras ir tauta gulėjo aplink jį.'),
  (@b9, 26, 8, 'Tada Abišajis tarė Dovydui: „Dievas šią dieną atidavė tavo priešą į tavo ranką; taigi dabar, meldžiu tave, leisk man jį prismeigti ietimi prie žemės vienąkart, ir aš jam nesmeigsiu antrą kartą“.'),
  (@b9, 26, 9, 'O Dovydas tarė Abišajui: „Nenaikink jo; nes kas galėtų ištiesti savo ranką prieš VIEŠPATIES pateptąjį ir būti nekaltas?“'),
  (@b9, 26, 10, 'Dovydas dar tarė: „Kaip VIEŠPATS gyvas, VIEŠPATS jam smogs; arba ateis jo diena mirti, arba nusileidęs į mūšį jis žus.'),
  (@b9, 26, 11, 'Apsaugok VIEŠPATIE, kad ištiesčiau savo ranką prieš VIEŠPATIES pateptąjį; bet dabar, meldžiu tave, paimk prie jo galvavietės esančią ietį bei vandens ąsotį ir eikime“.'),
  (@b9, 26, 12, 'Taip Dovydas paėmė ietį ir vandens ąsotį nuo Sauliaus galvavietės; ir jie išėjo, ir niekas to nematė nei nežinojo ir nepabudo; nes jie visi miegojo; kadangi ant jų nupuolė gilus miegas nuo VIEŠPATIES.'),
  (@b9, 26, 13, 'Tada Dovydas perėjo į kitą pusę ir iš tolo atsistojo kalvos viršūnėje, kad didelis tarpas buvo tarp jų;'),
  (@b9, 26, 14, 'ir Dovydas šaukė tautai ir Nero sūnui Abnerui, sakydamas: „Argi neatsiliepsi, Abnerai?“ Tada Abneras atsiliepdamas tarė: „Kas tu esi, kad šauki karaliui?“'),
  (@b9, 26, 15, 'Ir Dovydas tarė Abnerui: „Argi tu ne narsuolis? Ir kas yra tau lygus Izraelyje? Tai kodėl nesaugojai savo viešpaties karaliaus? Nes vienas iš tautos įėjo karaliaus, tavo valdovo, sunaikinti.'),
  (@b9, 26, 16, 'Tai, ką tu padarei, yra negerai. Kaip VIEŠPATS gyvas, jūs esate verti mirties, nes nesaugojote savo valdovo, VIEŠPATIES pateptojo. O dabar žiūrėk, kur yra karaliaus ietis ir vandens ąsotis, kuris buvo prie jo galvavietės“.'),
  (@b9, 26, 17, 'Ir Saulius pažino Dovydo balsą ir tarė: „Ar tai tavo balsas, mano sūnau Dovydai?“ Ir Dovydas tarė: „Tai mano balsas, o mano viešpatie, karaliau!“'),
  (@b9, 26, 18, 'Ir jis tarė: „Kodėl gi mano viešpats taip persekioja savo tarną? Ką gi padariau? Kokia gi piktybė mano rankose?'),
  (@b9, 26, 19, 'Taigi dabar, meldžiu tave, tegul mano viešpats karalius išklauso savo tarno žodžius. Jei VIEŠPATS tave sukurstė prieš mane, tegul jis priima atnašą; bet jei jie būtų žmonių vaikai, tebūna jie prakeikti VIEŠPATIES akivaizdoje; nes jie yra mane šią dieną išvarę, kad nepasilikčiau VIEŠPATIES pavelde, sakydami: ‘Eik, tarnauk kitiems dievams’.'),
  (@b9, 26, 20, 'Taigi dabar tenekrenta žemėn mano kraujas VIEŠPATIES akivaizdoje; nes Izraelio karalius yra išėjęs blusos ieškoti, kaip tas, kuris medžioja kurapką kalnuose“.'),
  (@b9, 26, 21, 'Tada Saulius tarė: „Aš nusidėjau; sugrįžk, mano sūnau Dovydai; nes aš tau nebedarysiu pikto, kadangi šią dieną mano siela buvo brangi tavo akyse; štai aš kvailai pasielgiau ir labai klydau“.'),
  (@b9, 26, 22, 'Ir Dovydas atsakydamas tarė: „Štai karaliaus ietis! Tegul ateina vienas iš jaunuolių ir ją paima.'),
  (@b9, 26, 23, 'VIEŠPATS teatmoka kiekvienam jo teisumą ir jo ištikimybę; nes VIEŠPATS šiandien atidavė tave į mano rankas, bet aš nenorėjau ištiesti savo rankos prieš VIEŠPATIES pateptąjį.'),
  (@b9, 26, 24, 'Ir štai, kaip šią dieną tavo gyvybė buvo verta mano akyse, taip mano gyvybė tebūna verta VIEŠPATIES akyse, ir jis teišvaduoja mane iš viso suspaudimo“.'),
  (@b9, 26, 25, 'Tada Saulius tarė Dovydui: „Būk palaimintas, mano sūnau Dovydai; tu darysi didžius dalykus ir tikrai dar įsigalėsi“. Taigi Dovydas nuėjo savo keliu, o Saulius sugrįžo į savo vietą.'),
  (@b9, 27, 1, 'Ir Dovydas sakė savo širdyje: „Aš dabar vieną dieną pražūsiu nuo Sauliaus rankos; man nieko nėra geriau, kaip tik skubiai sprukti į filistinų šalį; ir Saulius praras viltį toliau manęs ieškoti visose Izraelio ribose; taip išsigelbėsiu iš jo rankų“.'),
  (@b9, 27, 2, 'Ir pakilo Dovydas, ir perėjo su šešiais šimtais vyrų, esančių su juo, pas Maocho sūnų Achišą, Gato karalių.'),
  (@b9, 27, 3, 'Ir Dovydas apsigyveno pas Achišą Gate, jis ir jo vyrai, kiekvienas su savo namiškiais; Dovydas su abiem savo žmonom: jezreeliete Ahinoama ir karmeliete Abigaile, Nabalo žmona.'),
  (@b9, 27, 4, 'Ir Sauliui buvo pranešta, kad Dovydas pabėgęs į Gatą; ir jis daugiau jo nebeieškojo.'),
  (@b9, 27, 5, 'Ir Dovydas tarė Achišui: „Jei dabar radau malonę tavo akyse, tegul man duoda vietą kokiame nors šalies miestelyje, kad ten gyvenčiau; nes kodėl tavo tarnas turėtų gyventi su tavimi karališkame mieste?“'),
  (@b9, 27, 6, 'Tad tą dieną Achišas jam davė Ciklagą; todėl Ciklagas priklauso Judos karaliams iki šios dienos.'),
  (@b9, 27, 7, 'O laiko, kurį Dovydas gyveno filistinų šalyje, buvo pilni metai ir keturi mėnesiai.'),
  (@b9, 27, 8, 'Ir Dovydas nuėjo aukštyn su savo vyrais ir užpuolė gešuriečius, girzus ir amalekiečius; nes šitos tautos nuo seno buvo gyventojai tos šalies, kur einama į Šūrą, iki Egipto šalies.'),
  (@b9, 27, 9, 'Ir Dovydas sutriuškino tą šalį ir nepaliko gyvo nei vyro, nei moters, ir pasiėmė avis, jaučius, asilus, kupranugarius ir drabužius, ir sugrįžęs atėjo pas Achišą.'),
  (@b9, 27, 10, 'Ir Achišas tarė: „Kur šiandien buvote užpuolę?“ Ir Dovydas tarė: „Judos pietinę dalį, jerahmeelių pietinę dalį ir kenitų pietinę dalį“.'),
  (@b9, 27, 11, 'Ir Dovydas nepaliko gyvo nei vyro, nei moters, kad neatneštų žinios į Gatą, sakydamas: „Kad jie neįskųstų mūsų, sakydami: ‘Taip padarė Dovydas, ir taip jis elgsis visą laiką, kol gyvena filistinų šalyje’“.'),
  (@b9, 27, 12, 'Ir Achišas tikėjo Dovydu, sakydamas: „Jis pasidarė visiškai pasibjaurėtinas savo tautai Izraeliui; todėl jis bus mano tarnas per amžius“.'),
  (@b9, 28, 1, 'Ir įvyko tomis dienomis, kad filistinai surinko savo kariuomenes karui, kovoti su Izraeliu. Ir Achišas tarė Dovydui: „Tvirtai žinok, kad tu eisi su manimi į mūšį, tu ir tavo vyrai’“.'),
  (@b9, 28, 2, 'Ir Dovydas tarė Achišui: „Tu tikrai sužinosi, ką gali padaryti tavo tarnas“. O Achišas tarė Dovydui: „Todėl visam laikui tave padarysiu mano galvos sargybiniu“.'),
  (@b9, 28, 3, 'Na, o Samuelis buvo miręs, ir visas Izraelis jį buvo apraudojęs ir palaidojęs Ramoje, tai yra jo paties mieste. Ir Saulius buvo pašalinęs iš šalies turinčius namų dvasias ir magus.'),
  (@b9, 28, 4, 'Ir susirinkę filistinai atėjo ir stovyklavo Šuneme; o Saulius surinko visą Izraelį, ir jie stovyklavo Gilbojoje.'),
  (@b9, 28, 5, 'Ir pamatęs filistinų kariuomenę, Saulius išsigando, ir jo širdis labai drebėjo.'),
  (@b9, 28, 6, 'Ir kai Saulius teiravosi VIEŠPATIES, VIEŠPATS jam neatsakė nei per sapnus, nei per Urimą, nei per pranašus.'),
  (@b9, 28, 7, 'Tada Saulius tarė savo tarnams: „Paieškokite man moterį, turinčią namų dvasią, kad pas ją nueičiau ir jos pasiklausčiau“. Ir jo tarnai jam tarė: „Štai En-dore yra moteris, turinti namų dvasią“.'),
  (@b9, 28, 8, 'Ir Saulius užsimaskavo, apsivilko kitais drabužiais ir nuėjo, ir du vyrai su juo, ir jie atėjo naktį pas tą moterį; ir jis tarė: „Meldžiu tave, paburk man per namų dvasią ir pašauk man tą, kurį tau paminėsiu“.'),
  (@b9, 28, 9, 'O ta moteris jam tarė: „Štai tu žinai, ką Saulius padarė, kaip jis iškirto iš šalies turinčius namų dvasias ir magus; tai kodėl spendi spąstus mano gyvybei, kad priverstum mane mirti?“'),
  (@b9, 28, 10, 'Ir Saulius jai prisiekė VIEŠPAČIU, sakydamas: „Kaip VIEŠPATS gyvas, jokia bausmė tavęs neištiks dėl šito dalyko“.'),
  (@b9, 28, 11, 'Tada ta moteris tarė: „Ką tau turiu atvesti aukštyn?“ Ir jis tarė: „Atvesk man aukštyn Samuelį“.'),
  (@b9, 28, 12, 'Ir pamačiusi Samuelį, ta moteris garsiu balsu sušuko; ir moteris kalbėjo Sauliui, sakydama: „Kodėl mane apgavai? Nes tu esi Saulius“.'),
  (@b9, 28, 13, 'O karalius jai tarė: „Nebijok; ką matei?“ Ir moteris tarė Sauliui: „Mačiau dievus, kylančius iš žemės“.'),
  (@b9, 28, 14, 'Ir jis jai tarė: „Koks jo pavidalas?“ Ir ji tarė: „Ateina aukštyn senas vyras; jis apsidengęs mantija“. Ir Saulius suprato, kad tai buvo Samuelis, ir jis pasilenkė veidu žemyn ir nusilenkė.'),
  (@b9, 28, 15, 'Ir Samuelis tarė Sauliui: „Kodėl sudrumstei man ramybę, atvesdamas mane aukštyn?“ O Saulius atsakė: „Esu labai prislėgtas; nes filistinai kariauja prieš mane, o Dievas atsitraukęs nuo manęs ir man daugiau nebeatsako nei per pranašus, nei per sapnus; todėl pašaukiau tave, kad man duotum žinoti, ką turiu daryti“.'),
  (@b9, 28, 16, 'Tada Samuelis tarė: „Tai kodėl manęs klausi, kadangi VIEŠPATS yra atsitraukęs nuo tavęs ir tapęs tavo priešu?'),
  (@b9, 28, 17, 'VIEŠPATS sau padarė, kaip per mane kalbėjo; nes VIEŠPATS išplėšė iš tavo rankų karalystę ir ją davė tavo artimui, tai yra Dovydui;'),
  (@b9, 28, 18, 'kadangi nepaklusai VIEŠPATIES balsui nei neįvykdei jo smarkios rūstybės Amalekui, todėl VIEŠPATS šią dieną tau padarė šitą dalyką.'),
  (@b9, 28, 19, 'Be to, VIEŠPATS atiduos su tavimi Izraelį į filistinų rankas; ir rytoj tu ir tavo sūnūs būsite su manimi; taip pat Izraelio kariuomenę VIEŠPATS atiduos į filistinų rankas“.'),
  (@b9, 28, 20, 'Tada Saulius tuojau parpuolė visu ūgiu ant žemės ir buvo labai išsigandęs dėl Samuelio žodžių; ir jame nebuvo jėgų; nes jis visą dieną ir visą naktį nebuvo valgęs duonos.'),
  (@b9, 28, 21, 'Ir ta moteris, atėjusi pas Saulių ir pamačiusi, kad jis buvo labai sunerimęs, jam tarė: „Štai tavo tarnaitė pakluso tavo balsui, ir aš padėjau savo gyvybę į savo ranką, ir klausiau tavo žodžių, kuriuos man kalbėjai.'),
  (@b9, 28, 22, 'Todėl dabar, meldžiu tave, paklausyk ir tu savo tarnaitės balso ir leisk man padėti priešais tave kąsnį duonos; ir valgyk, kad turėtum jėgų, kai eisi savo keliu“.'),
  (@b9, 28, 23, 'Bet jis atsisakė ir tarė: „Nevalgysiu“. Bet jo tarnai kartu su ta moterimi jį vertė; ir jis paklausė jų balso. Taigi jis atsikėlė nuo žemės ir atsisėdo ant lovos.'),
  (@b9, 28, 24, 'O ta moteris turėjo namuose riebų veršį; ir ji pasiskubino, jį papjovė ir, paėmusi miltų, juos suminkė, ir iš jų iškepė neraugintos duonos;'),
  (@b9, 28, 25, 'ir ji atnešė tai priešais Saulių ir priešais jo tarnus; ir jie valgė. Po to jie pakilo ir tą naktį išėjo.'),
  (@b9, 29, 1, 'Na, o filistinai surinko visas savo kariuomenes į Afeką; o izraelitai stovyklavo prie Jezreelyje esančios versmės.'),
  (@b9, 29, 2, 'Ir filistinų viešpačiai ėjo šimtais bei tūkstančiais; bet Dovydas ir jo vyrai ėjo užnugaryje su Achišu.'),
  (@b9, 29, 3, 'Tada filistinų kunigaikščiai tarė: „Ką čia daro šitie hebrajai?“ Ir Achišas tarė filistinų kunigaikščiams: „Argi tai ne Dovydas, Izraelio karaliaus Sauliaus tarnas, kuris buvo su manimi šias dienas ar šiuos metus, ir aš jame neradau jokios kaltės nuo tada, kai jis persimetė pas mane, iki šios dienos?“'),
  (@b9, 29, 4, 'O filistinų kunigaikščiai užsirūstino ant jo; ir filistinų kunigaikščiai jam tarė: „Sugrąžink tą vyrą, kad jis grįžtų į savo vietą, kurią jam paskyrei, ir tegul jis neina žemyn su mumis į mūšį, kad mūšyje jis mums nebūtų priešininku; nes kuo gi jis galėtų susitaikinti su savo valdovu? Argi ne šitų vyrų galvomis?'),
  (@b9, 29, 5, 'Argi tai ne tas Dovydas, apie kurį jos dainavo viena kitai šokiuose, sakydamos: ‘Saulius užmušė savo tūkstančius, o Dovydas savo dešimtis tūkstančių?“'),
  (@b9, 29, 6, 'Tada Achišas pašaukęs Dovydą jam tarė: „Tikrai, kaip VIEŠPATS gyvas, tu buvai tiesus, ir tavo išėjimas ir tavo įėjimas su manimi kariuomenėje yra geras mano akyse; nes tavyje neradau pikta nuo tos dienos, kai atėjai pas mane, iki šios dienos; tačiau viešpačiams tu nepatinki.'),
  (@b9, 29, 7, 'Todėl dabar grįžk ir eik ramybėje, kad neerzintum filistinų viešpačių“.'),
  (@b9, 29, 8, 'Ir Dovydas tarė Achišui: „Bet ką aš padariau? Ir ką radai savo tarne, kol buvau su tavimi iki šios dienos, kad negaliu eiti ir kovoti prieš mano viešpaties karaliaus priešus?“'),
  (@b9, 29, 9, 'Ir Achišas atsakydamas tarė Dovydui: „Aš žinau, kad mano akyse esi geras kaip Dievo angelas; tačiau filistinų kunigaikščiai yra pasakę: ‘Jis neis su mumis aukštyn į mūšį’.'),
  (@b9, 29, 10, 'Todėl dabar atsikelk anksti ryte su savo valdovo tarnais, kurie yra atėję su tavimi; ir kai tik būsite anksti ryte atsikėlę ir jums prašvis, išeikite.'),
  (@b9, 29, 11, 'Taigi Dovydas ir jo vyrai atsikėlė anksti, kad ryte išeitų, kad grįžtų į filistinų šalį. O filistinai ėjo aukštyn į Jezreelį.'),
  (@b9, 30, 1, 'Ir įvyko, kai trečiąją dieną Dovydas ir jo vyrai atėjo į Ciklagą, amalekiečiai buvo įsiveržę į pietus ir į Ciklagą, ir sumušė Ciklagą, ir sudegino jį ugnimi;'),
  (@b9, 30, 2, 'ir buvo paėmę į nelaisvę moteris, buvusias jame; jie nenužudė nei vieno, nei didelio, nei mažo, bet nusivedė juos ir nuėjo savo keliu.'),
  (@b9, 30, 3, 'Taigi Dovydas ir jo vyrai atėjo į miestą, ir štai jis buvo sudegintas ugnimi; o jų žmonos ir jų sūnūs, ir jų dukterys buvo paimti nelaisvėn.'),
  (@b9, 30, 4, 'Tada Dovydas ir su juo esanti tauta pakeltu balsu verkė, kol nebeturėjo jėgų verkti.'),
  (@b9, 30, 5, 'Ir abi Dovydo žmonos buvo paimtos į nelaisvę: jezreelietė Ahinoama ir Abigailė, karmeliečio Nabalo žmona.'),
  (@b9, 30, 6, 'Ir Dovydas buvo labai prislėgtas; kadangi tauta tarėsi jį užmėtyti akmenimis, nes visos tautos siela buvo nuliūdusi, kiekvieno dėl savo sūnų ir dėl savo dukterų; bet Dovydas padrąsino save VIEŠPAČIU, savo Dievu.'),
  (@b9, 30, 7, 'Ir Dovydas tarė kunigui Abjatarui, Ahimelecho sūnui: „Meldžiu tave, atnešk man čia efodą“. Ir Abjataras atnešė efodą Dovydui.'),
  (@b9, 30, 8, 'Ir Dovydas pasiklausė VIEŠPATIES, sakydamas: „Ar man vytis šitą pulką? Ar juos pasivysiu?“ Ir jis jam atsakė: „Vykis; nes tikrai juos pasivysi ir tikrai visus susigrąžinsi“.'),
  (@b9, 30, 9, 'Taigi Dovydas nuėjo, jis ir šeši šimtai su juo esančių vyrų, ir atėjo prie Besoro upelio, kur pasiliko paliktieji užnugaryje.'),
  (@b9, 30, 10, 'Bet Dovydas vijosi, jis ir keturi šimtai vyrų; nes du šimtai, kurie buvo tokie išvargę, kad nebegalėjo pereiti per Besoro upelį, pasiliko užnugaryje.'),
  (@b9, 30, 11, 'Ir jie rado egiptietį ant lauko, atvedė jį pas Dovydą ir davė jam duonos, ir jis valgė; ir jie pagirdė jį vandeniu;'),
  (@b9, 30, 12, 'ir jie davė jam gabalą figų pyrago ir dvi razinų kekes; ir kai jis pavalgė, sugrįžo pas jį jo dvasia; nes tris dienas ir tris naktis jis nebuvo valgęs duonos ir nebuvo gėręs vandens.'),
  (@b9, 30, 13, 'Ir Dovydas jam tarė: „Kieno tu esi ir iš kur tu esi?“ Ir jis tarė: „Aš esu jaunuolis iš Egipto, amalekiečio tarnas; o mano valdovas paliko mane, nes prieš tris dienas aš susirgau.'),
  (@b9, 30, 14, 'Mes įsiveržėme į keretų pietus, į ribas, priklausančias Judai, ir į Kalebo pietus; ir sudeginome Ciklagą ugnimi“.'),
  (@b9, 30, 15, 'Ir Dovydas jam tarė: „Ar gali nuvesti mane žemyn prie to būrio?“ Ir jis tarė: „Prisiek man Dievu, kad manęs nenužudysi nei atiduosi į mano šeimininko rankas, ir aš tave nuvesiu žemyn prie to būrio“.'),
  (@b9, 30, 16, 'Ir kai jis nuvedė jį žemyn, štai jie buvo pasklidę po visą žemę, valgė, gėrė ir šoko dėl viso didelio grobio, kurį jie buvo paėmę iš filistinų šalies ir iš Judos šalies.'),
  (@b9, 30, 17, 'Ir Dovydas juos mušė nuo vakaro prietemos iki kitos dienos vakaro; ir nei vienas iš jų neištrūko, išskyrus keturis šimtus jaunuolių, kurie, jodami ant kupranugarių, pabėgo.'),
  (@b9, 30, 18, 'Ir Dovydas susigrąžino viską, ką amalekiečiai buvo nusinešę; ir Dovydas išvadavo abi savo žmonas.'),
  (@b9, 30, 19, 'Ir jie nieko nepasigedo, nei mažo, nei didelio, nei sūnų, nei dukterų, nei grobio, nei nieko, ką jie buvo pasiėmę; Dovydas viską susigrąžino.'),
  (@b9, 30, 20, 'Ir Dovydas paėmė visas kaimenes bei bandas, kurias jie varė pirma kitų galvijų, ir tarė: „Tai Dovydo grobis“.'),
  (@b9, 30, 21, 'Ir Dovydas atėjo pas tuos du šimtus vyrų, kurie buvo taip nusilpę, kad negalėjo sekti paskui Dovydą, kuriuos jie buvo ir palikę prie Besoro upelio; ir jie išėjo pasitikti Dovydo ir pasitikti su juo esančios liaudies; ir Dovydas, priartėjęs prie liaudies, juos pasveikino.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b9, 30, 22, 'Tada visi pikti vyrai ir Belialo vyrai, iš tų, kurie ėjo su Dovydu, atsiliepdami tarė: „Kadangi jie nėjo su mumis, mes jiems nieko neduosime iš grobio, kurį atgavome, tik kiekvienam jo žmoną ir jo vaikus, kad jie juos nuvestų ir išeitų“.'),
  (@b9, 30, 23, 'Tada Dovydas tarė: „Mano broliai, nedarykite taip su tuo, ką mums davė VIEŠPATS, kuris mus apsaugojo ir atidavė į mūsų rankas būrį, kuris atėjo prieš mus.'),
  (@b9, 30, 24, 'Nes kas jūsų klausys šiame dalyke? Tačiau kokia yra dalis to, kuris eina žemyn į mūšį, tokia pat bus ir dalis to, kuris pasilieka prie daiktų; jie pasidalins po lygiai“.'),
  (@b9, 30, 25, 'Ir taip buvo nuo tos dienos ir paskui, kad jis tai padarė Izraeliui įstatu ir įsaku iki šios dienos.'),
  (@b9, 30, 26, 'Ir atėjęs į Ciklagą, Dovydas pasiuntė iš grobio Judos vyresniesiems, tai yra savo draugams, sakydamas: „Štai jums dovana iš VIEŠPATIES priešų grobio“;'),
  (@b9, 30, 27, 'esantiems Bet-Elyje, esantiems pietiniame Ramote, esantiems Jatyre,'),
  (@b9, 30, 28, 'esantiems Aroere, esantiems Sifmote, esantiems Eštemojoje,'),
  (@b9, 30, 29, 'esantiems Rachale, esantiems jerachmeelitų miestuose, esantiems kenitų miestuose,'),
  (@b9, 30, 30, 'esantiems Hormoje, esantiems Chor-Ašane, esantiems Atache,'),
  (@b9, 30, 31, 'esantiems Hebrone ir visoms vietovėms, kur pats Dovydas ir jo vyrai buvo įpratę lankytis.'),
  (@b9, 31, 1, 'Na, o filistinai kovojo prieš Izraelį; ir Izraelio vyrai bėgo nuo filistinų akivaizdos ir krito nužudyti Gilbojos kalne.'),
  (@b9, 31, 2, 'Ir filistinai sekė įkandin Sauliui ir jo sūnums; ir filistinai užmušė Jonataną, Abinadabą ir Malki-Šūvą, Sauliaus sūnus.'),
  (@b9, 31, 3, 'Ir vyko smarkus mūšis prieš Saulių, ir lankininkai pataikė į jį; ir jis buvo lankininkų sunkiai sužeistas.'),
  (@b9, 31, 4, 'Tada Saulius tarė savo ginklanešiui: „Išsitrauk savo kalaviją ir juo perdurk mane; kad šitie neapipjaustytieji atėję neperdurtų manęs ir nepasityčiotų iš manęs“. Bet jo ginklanešys nenorėjo; nes jis labai bijojo. Todėl Saulius paėmė kalaviją ir krito ant jo.'),
  (@b9, 31, 5, 'O kai jo ginklanešys pamatė, kad Saulius miręs, jis taip pat krito ant savo kalavijo ir mirė su juo.'),
  (@b9, 31, 6, 'Taip tą dieną kartu mirė Saulius, jo trys sūnūs, jo ginklanešys ir visi jo vyrai.'),
  (@b9, 31, 7, 'Ir Izraelio vyrai, esantys kitoje slėnio pusėje ir esantys kitoje Jordano pusėje, pamatę, kad Izraelio vyrai pabėgo ir kad Saulius bei jo sūnūs mirę, paliko miestus ir pabėgo; o filistinai atėjo ir gyveno juose.'),
  (@b9, 31, 8, 'Ir įvyko rytojaus dieną, kai filistinai atėjo apiplėšti užmuštųjų, jie rado Saulių ir tris jo sūnus, kritusius Gilbojos kalne.'),
  (@b9, 31, 9, 'Ir jie nukirto jo galvą, nuėmė jo ginklus ir pasiuntė aplinkui po filistinų šalį, kad paskelbtų tai savo stabų namuose ir tautos tarpe.'),
  (@b9, 31, 10, 'Ir jie padėjo jo ginklus Astarotės namuose; o jo kūną jie pritvirtino prie Bet-Šano sienos.'),
  (@b9, 31, 11, 'Ir kai Jabeš-Gileado gyventojai išgirdo apie tai, ką filistinai buvo padarę Sauliui;'),
  (@b9, 31, 12, 'tada visi narsūs vyrai pakilę ėjo visą naktį ir nuėmė Sauliaus kūną bei jo sūnų kūnus nuo Bet-Šano sienos ir, atėję į Jabešą, juos ten sudegino.'),
  (@b9, 31, 13, 'Ir paėmę jų kaulus, jie palaidojo juos po medžiu Jabeše ir pasninkavo septynias dienas.'),
  (@b10, 1, 1, 'Na, o atsitiko po Sauliaus mirties, Dovydui sugrįžus nuo amalekiečių žudynių, ir Dovydui pasilikus dvi dienas Ciklage;'),
  (@b10, 1, 2, 'trečiąją dieną įvyko, kad štai vyras atėjo iš stovyklos nuo Sauliaus su perplėštais drabužiais ir žemėmis ant galvos; ir atėjęs pas Dovydą, jis parpuolė ant žemės ir išreiškė pagarbą.'),
  (@b10, 1, 3, 'Ir Dovydas jam tarė: „Iš kur ateini?“ O jis jam tarė: „Pabėgau iš Izraelio stovyklos“.'),
  (@b10, 1, 4, 'Ir Dovydas jam tarė: „Kaip ėjosi? Pasakyk man, meldžiu tave“. Ir jis atsakė: „Tauta pabėgusi iš mūšio, ir daugelis iš tautos taip pat kritę ir žuvę; taip pat Saulius ir jo sūnus Jonatanas yra mirę“.'),
  (@b10, 1, 5, 'Ir Dovydas tarė jaunuoliui, kuris jam pranešė: „Iš kur žinai, kad Saulius ir jo sūnus Jonatanas mirę?“'),
  (@b10, 1, 6, 'Ir jaunuolis, kuris jam pranešė, tarė: „Visai atsitiktinai buvau ant Gilbojos kalno ir žiūriu, Saulius pasirėmęs ant savo ieties; ir štai vežimai ir raiteliai sekė jam įkandin.'),
  (@b10, 1, 7, 'Ir pažvelgęs sau už nugaros ir mane pamatęs, jis pašaukė mane. Ir aš atsiliepiau: ‘Aš čia’.'),
  (@b10, 1, 8, 'O jis man tarė: ‘Kas tu esi?’ Ir aš jam atsakiau: ‘Aš esu amalekietis’.'),
  (@b10, 1, 9, 'Jis man vėl tarė: ‘Stokis, meldžiu tave, prie manęs ir nužudyk mane; nes didžiulis skausmas yra mane apėmęs, kadangi visa gyvybė tebėra manyje’.'),
  (@b10, 1, 10, 'Taigi, atsistojęs prie jo, aš jį nužudžiau, nes buvau tikras, kad jis kritęs nebegalės gyventi; ir paėmęs karūną, buvusią ant jo galvos, ir apyrankę, buvusią ant jo rankos, jas čia atnešiau savo viešpačiui“.'),
  (@b10, 1, 11, 'Tada Dovydas, nutvėręs savo drabužius, persiplėšė juos; taip pat ir visi su juo buvę vyrai;'),
  (@b10, 1, 12, 'ir jie raudojo, verkė ir iki vakaro pasninkavo dėl Sauliaus, dėl jo sūnaus Jonatano, dėl VIEŠPATIES tautos ir dėl Izraelio namų; nes jie buvo kritę nuo kalavijo.'),
  (@b10, 1, 13, 'Ir Dovydas tarė jaunuoliui, kuris jam buvo pranešęs: „Iš kur tu esi?“ Ir jis atsakė: „Aš esu ateivio sūnus, amalekietis“.'),
  (@b10, 1, 14, 'Ir Dovydas jam tarė: „Kaip tu nebijojai ištiesti savo rankos VIEŠPATIES pateptajam sunaikinti?“'),
  (@b10, 1, 15, 'Ir Dovydas pašaukė vieną iš jaunuolių ir tarė: „Prieik, pulk jį“. Ir jis jam smogė, kad jis mirė.'),
  (@b10, 1, 16, 'Ir Dovydas jam tarė: „Tavo kraujas tebūna ant tavo galvos; nes tavo burna paliudijo prieš tave, sakydama: ‘Aš nužudžiau VIEŠPATIES pateptąjį’“.'),
  (@b10, 1, 17, 'Ir Dovydas raudojo šia rauda dėl Sauliaus ir dėl jo sūnaus Jonatano'),
  (@b10, 1, 18, '(taip pat jis sakė, kad jie mokytų Judos vaikus naudotis lanku; štai tai yra užrašyta Jašero knygoje):'),
  (@b10, 1, 19, '„Izraelio grožybė yra užmušta tavo aukštumose; kaip yra kritę galingieji!'),
  (@b10, 1, 20, 'Nepraneškite to Gate, neskelbkite to Aškelono gatvėse; kad nesidžiaugtų filistinų dukterys, kad nešvęstų pergalės neapipjaustytųjų dukterys.'),
  (@b10, 1, 21, 'Jūs, Gilbojos kalnai, tenebūna rasos nei lietaus ant jūsų, nei atnašų laukų; nes ten yra niekšiškai atmestas galingųjų skydas, Sauliaus skydas, tarsi jis nebūtų buvęs pateptas aliejumi.'),
  (@b10, 1, 22, 'Nuo užmuštųjų kraujo, nuo galingųjų riebalų Jonatano lankas neatsigręždavo, ir Sauliaus kalavijas nesugrįždavo tuščias.'),
  (@b10, 1, 23, 'Saulius ir Jonatanas buvo numylėti ir mieli jų gyvenime, ir jų mirtyje jie nebuvo perskirti; jie buvo greitesni negu ereliai, stipresni negu liūtai.'),
  (@b10, 1, 24, 'Jūs, Izraelio dukterys, raudokite dėl Sauliaus, kuris jus apvilkdavo skaisčiai raudonu ir kitais malonumais, kuris uždėdavo aukso papuošalus ant jūsų drabužių.'),
  (@b10, 1, 25, 'Kaip krito galingieji mūšio vidury! O Jonatanai, tu buvai užmuštas tavo aukštumose.'),
  (@b10, 1, 26, 'Aš sielvartauju dėl tavęs, mano broli Jonatanai; labai mielas man buvai; tavo meilė man buvo nuostabesnė už moterų meilę.'),
  (@b10, 1, 27, 'Kaip krito galingieji ir pražuvo karo ginklai!“'),
  (@b10, 2, 1, 'Ir po to įvyko, kad Dovydas pasiklausė VIEŠPATIES, sakydamas: „Ar man eiti aukštyn į kurį nors iš Judos miestų?“ Ir VIEŠPATS jam tarė: „Eik aukštyn“. Ir Dovydas tarė: „Kur man eiti aukštyn?“ Ir jis tarė: „Į Hebroną“.'),
  (@b10, 2, 2, 'Taigi Dovydas nuėjo ten aukštyn, ir taip pat abi jo žmonos: jezreelietė Ahinoama ir karmelietė Abigailė, Nabalo žmona.'),
  (@b10, 2, 3, 'Ir Dovydas atsivedė aukštyn savo vyrus, esančius su juo, kiekvieną su jo namiškiais; ir jie apsigyveno Hebrono miestuose.'),
  (@b10, 2, 4, 'Ir atėjo Judos vyrai ir patepė ten Dovydą Judos namų karaliumi. Ir Dovydui pranešė, sakydami: „Jabeš-Gileado žmonės buvo tie, kurie palaidojo Saulių“.'),
  (@b10, 2, 5, 'Ir Dovydas siuntė pasiuntinius pas Jabeš-Gileado žmones ir jiems sakė: „Būkite VIEŠPATIES palaiminti, kad parodėte šitą gerumą savo viešpačiui, tai yra Sauliui, ir jį palaidojote.'),
  (@b10, 2, 6, 'O dabar VIEŠPATS jums teparodo gerumą ir tiesą; o aš irgi jums atsilyginsiu šiuo gerumu, kadangi padarėte tą dalyką.'),
  (@b10, 2, 7, 'Todėl dabar tebūna jūsų rankos sustiprintos ir būkite narsūs; nes jūsų valdovas Saulius yra miręs, ir Judos namai patepė mane savo karaliumi“.'),
  (@b10, 2, 8, 'Bet Nero sūnus Abneras, Sauliaus kariuomenės vadas, paėmęs Sauliaus sūnų Iš-Bošetą, nuvedė jį į Mahanaimą;'),
  (@b10, 2, 9, 'ir padarė jį karaliumi Gileadui, ašuriečiams, Jezreeliui, Efraimui, Benjaminui ir visam Izraeliui.'),
  (@b10, 2, 10, 'Sauliaus sūnus Iš-Bošetas buvo keturiasdešimties metų, kai pradėjo karaliauti Izraeliui, ir karaliavo dvejus metus. Bet Judos namai sekė paskui Dovydą.'),
  (@b10, 2, 11, 'O laiko, kuriuo Dovydas buvo Judos namų karalius Hebrone, buvo septyneri metai ir šeši mėnesiai.'),
  (@b10, 2, 12, 'Ir Nero sūnus Abneras ir Sauliaus sūnaus Iš-Bošeto tarnai išėjo iš Mahanaimo į Gibeoną.'),
  (@b10, 2, 13, 'Ir Cerujos sūnus Joabas ir Dovydo tarnai išėjo ir susitiko prie Gibeono tvenkinio; ir vieni susėdo vienoje tvenkinio pusėje, o kiti kitoje tvenkinio pusėje.'),
  (@b10, 2, 14, 'Ir Abneras tarė Joabui: „Teatsikelia dabar jaunuoliai ir tepažaidžia mūsų akivaizdoje“. Ir Joabas tarė: „Teatsikelia“.'),
  (@b10, 2, 15, 'Tada atsikėlė ir perėjo skaičiumi: dvylika iš Benjamino, kurie priklausė Sauliaus sūnui Iš-Bošetui, ir dvylika iš Dovydo tarnų.'),
  (@b10, 2, 16, 'Ir jie nutvėrė vienas kitą už galvos ir įsmeigė savo kalaviją vienas kitam į šoną; taip jie krito drauge; todėl tą vietą pavadino Helkat-Hazurimu, kuris yra Gibeone.'),
  (@b10, 2, 17, 'Ir tą dieną buvo labai smarkus mūšis; Abneras ir Izraelio vyrai buvo sumušti Dovydo tarnų akivaizdoje.'),
  (@b10, 2, 18, 'Ir ten buvo trys Cerujos sūnūs: Joabas, Abišajas ir Asaelis; o Asaelis buvo tokių lengvų kojų, kaip laukinė stirna.'),
  (@b10, 2, 19, 'Ir Asaelis vijosi Abnerą; ir eidamas nepasuko nei į dešinę, nei į kairę nuo sekimo paskui Abnerą.'),
  (@b10, 2, 20, 'Tada Abneras pažvelgė sau už nugaros ir tarė: „Ar tu esi Asaelis?“ Ir jis atsakė: „Aš“.'),
  (@b10, 2, 21, 'Ir Abneras jam tarė: „Pasuk į dešinę ar į kairę, pagriebk vieną iš jaunuolių ir pasiimk jo ginklus“. Bet Asaelis nenorėjo pasukti į šalį nuo sekimo paskui jį.'),
  (@b10, 2, 22, 'Ir Abneras vėl pasakė Asaeliui: „Pasuk į šalį nuo sekimo paskui mane; kodėl turėčiau tave pamušti žemėn? Kaip tada galėčiau pakelti savo veidą į tavo brolį Joabą?“'),
  (@b10, 2, 23, 'Tačiau jis nesutiko pasukti į šalį; todėl Abneras ieties storgaliu smogė jam žemiau penktojo šonkaulio, kad ietis išlindo jam iš nugaros; ir jis ten krito ir mirė toje vietoje; ir įvyko, kad visi, atėjusieji į tą vietą, kur Asaelis buvo kritęs ir miręs, sustojo.'),
  (@b10, 2, 24, 'Taip pat Joabas ir Abišajas vijosi Abnerą; ir saulė nusileido, kai jie atėjo į Amos kalvą, esančią prieš Giachą, prie Gibeono dykumos kelio.'),
  (@b10, 2, 25, 'Ir Benjamino vaikai susirinko paskui Abnerą ir pasidarė vienas pulkas, ir sustojo kalvos viršūnėje.'),
  (@b10, 2, 26, 'Tada Abneras pašaukė Joabą ir tarė: „Argi amžinai ris kalavijas? Argi nežinai, kad karti bus pabaiga? Tad iki kol nesakysi tautai gręžtis nuo sekimo paskui savo brolius?“'),
  (@b10, 2, 27, 'Ir Joabas tarė: „Kaip Dievas gyvas, jei nebūtum kalbėjęs, tai tikrai ryte tauta būtų nuėjusi aukštyn, kiekvienas nuo sekimo paskui savo brolius“.'),
  (@b10, 2, 28, 'Taigi Joabas pūtė trimitą, ir visa tauta sustojo ir nebesivijo Izraelio, ir jie nebekovojo.'),
  (@b10, 2, 29, 'O Abneras ir jo vyrai visą tą naktį ėjo per lygumą, perėjo per Jordaną, ėjo per visą Bitroną ir atėjo į Mahanaimą.'),
  (@b10, 2, 30, 'Ir Joabas sugrįžo nuo sekimo paskui Abnerą; ir kai jis surinko visą tautą, iš Dovydo tarnų trūko devyniolika vyrų ir Asaelio.'),
  (@b10, 2, 31, 'Bet Dovydo tarnai buvo sumušę iš Benjamino ir iš Abnero vyrų taip, kad mirė trys šimtai šešiasdešimt vyrų.'),
  (@b10, 2, 32, 'Ir jie paėmė Asaelį ir jį palaidojo jo tėvo kape, esančiame Betliejuje. O Joabas ir jo vyrai ėjo visą naktį, ir brėkštant dienai jie atėjo į Hebroną.'),
  (@b10, 3, 1, 'Na, o buvo ilgas karas tarp Sauliaus namų ir Dovydo namų; bet Dovydas vis labiau ir labiau stiprėjo, o Sauliaus namai vis labiau ir labiau silpnėjo.'),
  (@b10, 3, 2, 'Ir Hebrone Dovydui gimė sūnų: jo pirmagimis buvo Amnonas iš jezreelietės Ahinoamos;'),
  (@b10, 3, 3, 'jo antrasis – Kileabas iš Abigailės, karmeliečio Nabalo žmonos; trečiasis – Abšalomas, Gešūro karaliaus Talmajo dukters Maakos sūnus;'),
  (@b10, 3, 4, 'ketvirtasis – Adonijas, Hagitos sūnus; penktasis – Šefatijas, Abitalės sūnus;'),
  (@b10, 3, 5, 'o šeštasis – Itramas iš Dovydo žmonos Eglos. Šitie gimė Dovydui Hebrone.'),
  (@b10, 3, 6, 'Ir atsitiko, kad, tebevykstant karui tarp Sauliaus namų ir Dovydo namų, Abneras sustiprėjo dėl Sauliaus namų.'),
  (@b10, 3, 7, 'O Saulius turėjo sugulovę, kurios vardas buvo Ricpa, Ajo duktė; ir Iš-Bošetas tarė Abnerui: „Kodėl įėjai pas mano tėvo sugulovę?“'),
  (@b10, 3, 8, 'Tada Abneras labai užsirūstino dėl Iš-Bošeto žodžių ir tarė: „Ar aš esu šuns galva? Aš prieš Judą šią dieną rodau gerumą tavo tėvo Sauliaus namams, jo broliams ir jo draugams, ir neatidaviau tavęs į Dovydo rankas, o tu mane šiandien kaltini nusižengimu dėl tos moters.'),
  (@b10, 3, 9, 'Tepadaro Dievas Abnerui taip ir dar daugiau, jei nepadarysiu Dovydui, kaip VIEŠPATS yra jam prisiekęs:'),
  (@b10, 3, 10, 'perkelti karalystę iš Sauliaus namų ir pastatyti Dovydo sostą Izraeliui ir Judai nuo Dano iki Beer-Šebos“.'),
  (@b10, 3, 11, 'Ir jis negalėjo nei žodžio atsakyti Abnerui, nes bijojo jo.'),
  (@b10, 3, 12, 'Ir Abneras siuntė nuo savęs pasiuntinius pas Dovydą, sakydamas: „Kieno yra šalis?“ Taip pat sakydamas: „Sudaryk sąjungą su manimi, ir štai mano ranka bus su tavimi, visam Izraeliui atvesti pas tave“.'),
  (@b10, 3, 13, 'Ir jis tarė: „Gerai; aš sudarysiu sąjungą su tavimi; bet vieno dalyko reikalauju iš tavęs, tai yra, tu neišvysi mano veido, jei, ateidamas mano veido pamatyti, pirmiau neatvesi Sauliaus dukters Mikalės“.'),
  (@b10, 3, 14, 'Ir Dovydas siuntė pasiuntinius pas Sauliaus sūnų Iš-Bošetą, sakydamas: „Atiduok man mano žmoną Mikalę, kurią vedžiau už šimtą filistinų apyvarpių“.'),
  (@b10, 3, 15, 'Ir Iš-Bošetas siuntė ir paėmė ją iš jos vyro – iš Laišo sūnaus Paltielio.'),
  (@b10, 3, 16, 'Ir jos vyras ėjo su ja verkdamas paskui ją iki Bahurimo. Tada Abneras jam pasakė: „Eik, grįžk“. Ir jis sugrįžo.'),
  (@b10, 3, 17, 'Ir Abneras kalbėjosi su Izraelio vyresniaisiais, sakydamas: „Praeityje jūs siekėte Dovydo, kad būtų jums karaliumi.'),
  (@b10, 3, 18, 'Tad dabar padarykite tai; nes VIEŠPATS yra kalbėjęs apie Dovydą, sakydamas: ‘Savo tarno Dovydo ranka aš išgelbėsiu savo tautą Izraelį iš filistinų rankos ir iš visų jų priešų rankos’“.'),
  (@b10, 3, 19, 'Ir Abneras taip pat kalbėjo Benjaminui į ausis; ir Abneras taip pat ėjo kalbėti Dovydui į ausis Hebrone, viską, kas atrodė gera Izraeliui ir visiems Benjamino namams.'),
  (@b10, 3, 20, 'Taigi Abneras ir su juo dvidešimt vyrų atėjo pas Dovydą į Hebroną. Ir Dovydas iškėlė puotą Abnerui ir su juo buvusiems vyrams.'),
  (@b10, 3, 21, 'Ir Abneras sakė Dovydui: „Aš pakilęs eisiu ir surinksiu pas savo viešpatį karalių visą Izraelį, kad jie sudarytų su tavimi sąjungą ir kad tu karaliautum viskam, ko geidžia tavo širdis“. Ir Dovydas išleido Abnerą; ir jis nuėjo ramybėje.'),
  (@b10, 3, 22, 'Ir štai Dovydo tarnai ir Joabas atėjo nuo pulko persekiojimo ir pargabeno su savimi didelį grobį; bet Abnero nebuvo pas Dovydą Hebrone; nes jis buvo jį išleidęs, ir jis buvo išėjęs ramybėje.'),
  (@b10, 3, 23, 'Kai Joabas ir visa su juo esanti kariuomenė atėjo, Joabui pranešė, sakydami: „Buvo atėjęs Nero sūnus Abneras pas karalių, o jis jį išleido, ir jis yra išėjęs ramybėje“.'),
  (@b10, 3, 24, 'Tada Joabas, atėjęs pas karalių, tarė: „Ką padarei? Štai Abneras buvo atėjęs pas tave; tai kodėl jį paleidai, ir jis laisvai išėjo?'),
  (@b10, 3, 25, 'Tu pažįsti Nero sūnų Abnerą, kad jis atėjo tavęs apgauti ir sužinoti tavo išėjimą ir tavo įėjimą, ir sužinoti viską, ką tu darai“.'),
  (@b10, 3, 26, 'Ir išėjęs iš Dovydo, Joabas siuntė paskui Abnerą pasiuntinius, kurie jį sugrąžino nuo Siros šulinio; bet Dovydas to nežinojo.'),
  (@b10, 3, 27, 'Ir Abnerui sugrįžus į Hebroną, Joabas jį pasivedė nuošaliai į vartų vidų, kad kalbėtųsi su juo tylomis, ir dėl jo brolio Asaelio kraujo ten jam smogė žemiau penktojo šonkaulio, kad jis mirė.'),
  (@b10, 3, 28, 'O vėliau tai išgirdęs, Dovydas tarė: „Aš ir mano karalystė esame amžinai nekalti VIEŠPATIES akivaizdoje dėl Nero sūnaus Abnero kraujo;'),
  (@b10, 3, 29, 'tegul jis guli ant Joabo galvos ir ant visų jo tėvo namų; ir tenetrūksta Joabo namuose turinčio plūdimą ar raupsuoto, ar besiremiančio į lazdą, ar krentančio nuo kalavijo, ar stokojančio duonos“.'),
  (@b10, 3, 30, 'Taip Joabas ir jo brolis Abišajas nužudė Abnerą, kadangi jis buvo užmušęs jų brolį Asaelį mūšyje Gibeone.'),
  (@b10, 3, 31, 'Ir Dovydas tarė Joabui ir visai su juo esančiai tautai: „Persiplėškite savo drabužius, apsijuoskite ašutinėmis ir raudokite prieš Abnerą“. O pats karalius Dovydas ėjo paskui karsto neštuvus.'),
  (@b10, 3, 32, 'Ir jie palaidojo Abnerą Hebrone; ir karalius pakeltu balsu verkė prie Abnero kapo; ir verkė visa tauta.'),
  (@b10, 3, 33, 'Ir karalius raudojo dėl Abnero ir sakė: „Ar Abneras mirė, kaip kvailys miršta?'),
  (@b10, 3, 34, 'Tavo rankos nebuvo surištos, ir tavo kojos nebuvo sukaustytos grandinėmis; tu kritai, kaip žmogus krenta nuo nedorėlių“. Ir visa tauta vėl verkė dėl jo.'),
  (@b10, 3, 35, 'Ir kai visa tauta atėjo paskatinti, kad Dovydas valgytų maisto, kai tebebuvo diena, Dovydas prisiekė, sakydamas: „Tepadaro man Dievas taip ir dar daugiau, jei prieš saulei nusileidžiant paragaučiau duonos ar ko nors kito“.'),
  (@b10, 3, 36, 'Ir visa tauta tai pastebėjo, ir jiems tai patiko; kaip ir viskas, ką karalius darė, patiko visai tautai.'),
  (@b10, 3, 37, 'Nes tą dieną visa tauta ir visas Izraelis suprato, kad tai nebuvo nuo karaliaus, kad nužudytų Nero sūnų Abnerą.'),
  (@b10, 3, 38, 'Ir karalius tarė savo tarnams: „Ar nežinote, kad šią dieną Izraelyje krito kunigaikštis ir didis vyras?'),
  (@b10, 3, 39, 'O aš šiandien esu silpnas, nors pateptas karaliumi; o šitie vyrai, Cerujos sūnūs, yra per stiprūs man; VIEŠPATS atlygins piktadariui pagal jo nedorybę“.'),
  (@b10, 4, 1, 'Ir kai Sauliaus sūnus išgirdo, kad Abneras miręs Hebrone, jo rankos nusilpo, ir visi izraelitai sunerimo.'),
  (@b10, 4, 2, 'O Sauliaus sūnus turėjo du vyrus, būrių vadus: vieno vardas buvo Baana, o kito vardas – Rechabas, beerotiečio Rimono sūnūs iš Benjamino vaikų (nes Beerotas irgi buvo priskirtas prie Benjamino;'),
  (@b10, 4, 3, 'ir beerotiečiai pabėgo į Gitaimą ir ten buvo laikinai apsigyvenusieji iki šios dienos);'),
  (@b10, 4, 4, 'ir Sauliaus sūnus Jonatanas turėjo sūnų, luošą kojomis. Jis buvo penkerių metų amžiaus, kai atėjo iš Jezreelio žinia apie Saulių ir Jonataną; ir jo auklė jį paėmusi pabėgo; ir atsitiko, kai ji skubėjo bėgti, jis krito ir tapo luošas. O jo vardas buvo Mefibošetas.'),
  (@b10, 4, 5, 'Ir beerotiečio Rimono sūnūs Rechabas ir Baana ėjo ir pačioje dienos kaitroje atėjo į Iš-Bošeto, kuris vidurdienį gulėjo lovoje, namus.'),
  (@b10, 4, 6, 'Ir jie įėjo ten į namų vidų, tarsi jie norėjo atnešti kviečių; ir jie smogė jam žemiau penktojo šonkaulio; ir Rechabas ir jo brolis Baana pabėgo.'),
  (@b10, 4, 7, 'Nes kai jie atėjo į namus, jis gulėjo ant savo lovos savo miegamajame; ir jie smogė jam, užmušė jį, nukirto jam galvą, paėmė jo galvą ir visą naktį atsitraukinėjo per lygumą.'),
  (@b10, 4, 8, 'Ir jie atnešė Iš-Bošeto galvą pas Dovydą į Hebroną ir tarė karaliui: „Štai galva Iš-Bošeto, sūnaus tavo priešo Sauliaus, kuris ieškojo tavo gyvybės; VIEŠPATS šią dieną atkeršijo Sauliui ir jo sėklai už mano viešpatį karalių“.'),
  (@b10, 4, 9, 'Ir Dovydas atsakė Rechabui ir jo broliui Baanai, beerotiečio Rimono sūnums, jiems tardamas: „Kaip gyvas VIEŠPATS, kuris atpirko mano sielą iš visokių nelaimių,'),
  (@b10, 4, 10, 'kai man vienas žmogus pranešė, sakydamas: ‘Štai Saulius miręs’, galvodamas, kad atnešė gerą žinią, aš jį nutvėręs nužudžiau Ciklage, o jis galvojo, kad jam turėčiau duoti apdovanojimą už jo žinią;'),
  (@b10, 4, 11, 'tai kaip juo labiau, kai nedori žmonės nužudė teisų žmogų jo paties namuose, jo paties lovoje? Taigi ar dabar neturėčiau pareikalauti jo kraujo iš jūsų rankų ir jūsų pašalinti nuo žemės?“'),
  (@b10, 4, 12, 'Ir Dovydas įsakė savo jaunuoliams, ir jie juos nužudė ir, nukapoję jų rankas ir jų kojas, pakorė juos virš tvenkinio Hebrone. Bet Iš-Bošeto galvą jie paėmė ir palaidojo Abnero kape, Hebrone.'),
  (@b10, 5, 1, 'Tada visos Izraelio gentys atėjo pas Dovydą į Hebroną ir kalbėjo, sakydamos: „Štai mes esame tavo kaulas ir tavo kūnas.'),
  (@b10, 5, 2, 'Taip pat praeityje, kai Saulius buvo mūsų karalius, tu buvai tas, kuris išvesdavai ir įvesdavai Izraelį; ir VIEŠPATS tau sakė: ‘Tu ganysi mano tautą Izraelį ir būsi vadas Izraeliui’“.'),
  (@b10, 5, 3, 'Taip visi Izraelio vyresnieji atėjo pas karalių į Hebroną; ir karalius Dovydas sudarė su jais sąjungą Hebrone VIEŠPATIES akivaizdoje; ir jie patepė Dovydą Izraelio karaliumi.'),
  (@b10, 5, 4, 'Dovydas buvo trisdešimties metų, kai pradėjo karaliauti, ir jis karaliavo keturiasdešimt metų.'),
  (@b10, 5, 5, 'Hebrone jis karaliavo Judai septynerius metus ir šešis mėnesius; o Jeruzalėje jis karaliavo trisdešimt trejus metus visam Izraeliui ir Judai.'),
  (@b10, 5, 6, 'Ir karalius bei jo vyrai ėjo į Jeruzalę pas jebusiečius, tos šalies gyventojus; kurie kalbėjo Dovydui, sakydami: „Jei nepašalinsi aklų ir luošų, tu neįeisi čia“; galvodami: „Dovydas negali čia įeiti“.'),
  (@b10, 5, 7, 'Tačiau Dovydas paėmė Siono tvirtovę; tas yra Dovydo miestas.'),
  (@b10, 5, 8, 'Ir tą dieną Dovydas tarė: „Kas nueis aukštyn prie griovio ir sumuš jebusiečius, luošus ir akluosius, kurių nekenčia Dovydo siela, tas bus vyriausias ir vadas. Todėl sako: „Aklas ir luošas neįeis į namus“.'),
  (@b10, 5, 9, 'Taip Dovydas apsigyveno forte ir jį praminė Dovydo miestu. Ir Dovydas statė aplinkui nuo Milo ir vidun.'),
  (@b10, 5, 10, 'Ir Dovydas ėjo pirmyn ir tapo didis, o VIEŠPATS, kariuomenių Dievas, buvo su juo.'),
  (@b10, 5, 11, 'Ir Tyro karalius Hiramas siuntė pas Dovydą pasiuntinius, kedro medžius, dailides ir mūrininkus; ir jie pastatė Dovydui namus.'),
  (@b10, 5, 12, 'Ir Dovydas suprato, kad VIEŠPATS jį įtvirtino Izraelio karaliumi ir kad jis išaukštino jo karalystę dėl savo tautos Izraelio.'),
  (@b10, 5, 13, 'Ir po to, kai atėjo iš Hebrono, Dovydas pasiėmė daugiau sugulovių ir žmonų iš Jeruzalės; ir Dovydui dar gimė sūnų ir dukterų.'),
  (@b10, 5, 14, 'O šitie yra vardai tų, kurie jam gimė Jeruzalėje: Šamuva, Šobabas, Natanas, Saliamonas,'),
  (@b10, 5, 15, 'taip pat Ibharas, Elišūva, Nefegas, Jafija,'),
  (@b10, 5, 16, 'Elišama, Eljada ir Elifeletas.'),
  (@b10, 5, 17, 'Bet kai filistinai išgirdo, kad jie patepė Dovydą Izraelio karaliumi, visi filistinai ėjo aukštyn Dovydo ieškoti; o Dovydas, tai išgirdęs, nuėjo žemyn į tvirtovę.'),
  (@b10, 5, 18, 'Filistinai irgi atėjo ir pasklido po Refaimo slėnį.'),
  (@b10, 5, 19, 'Ir Dovydas pasiklausė VIEŠPATIES, sakydamas: „Ar man eiti aukštyn pas filistinus? Ar juos atiduosi į mano rankas?“ O VIEŠPATS tarė Dovydui: „Eik aukštyn; nes aš tikrai atiduosiu filistinus į tavo rankas“.'),
  (@b10, 5, 20, 'Ir Dovydas atėjo į Baal-Peracimą, ir Dovydas ten juos sumušė ir tarė: „VIEŠPATS prasilaužė ant mano priešų mano akivaizdoje kaip vandenų pralauža“. Todėl tą vietą praminė Baal-Peracimo vardu.'),
  (@b10, 5, 21, 'Ir jie ten paliko savo atvaizdus, o Dovydas bei jo vyrai juos sudegino.'),
  (@b10, 5, 22, 'Ir filistinai dar kartą atėjo aukštyn ir pasklido Refaimo slėnyje.'),
  (@b10, 5, 23, 'Ir kai Dovydas pasiklausė VIEŠPATIES, jis tarė: „Neik aukštyn; bet apeik juos iš užnugario ir užpulk juos priešais šilkmedžius.'),
  (@b10, 5, 24, 'Ir tebus, kai išgirsi šilkmedžių viršūnėse ėjimo garsą, tada pajudėk; nes tada VIEŠPATS išeis tavo priekyje filistinų kariuomenės mušti“.'),
  (@b10, 5, 25, 'Ir Dovydas padarė taip, kaip VIEŠPATS jam buvo įsakęs; ir mušė filistinus nuo Gebos iki kur ateinama į Gazerą.'),
  (@b10, 6, 1, 'Dovydas vėl surinko visus Izraelio rinktinius vyrus – trisdešimt tūkstančių.'),
  (@b10, 6, 2, 'Ir Dovydas pakilo ir ėjo su visa tauta, esančia su juo, iš Judos Baalo, kad iš ten atgabentų aukštyn Dievo skrynią, kurios vardą vadina vardu kariuomenių VIEŠPATIES, gyvenančio tarp kerubų.'),
  (@b10, 6, 3, 'Ir jie pastatė Dievo skrynią ant naujo vežimo ir ją gabeno iš Abinadabo namų, esančių Gibėjoje; o Uza ir Achjojas, Abinadabo sūnūs, varė tą naują vežimą.'),
  (@b10, 6, 4, 'Ir jie išgabeno ją iš Abinadabo namų, esančių Gibėjoje, lydėdami Dievo skrynią; o Achjojas ėjo skrynios priešakyje.'),
  (@b10, 6, 5, 'O Dovydas ir visi Izraelio namai grojo VIEŠPATIES akivaizdoje visokiais instrumentais, padarytais iš eglės medžio – arfomis, psalteriais, tambūrinais, kornetais ir cimbolais.'),
  (@b10, 6, 6, 'Ir jiems atėjus į Nachono klojimą, Uza ištiesė savo ranką į Dievo skrynią ir už jos nusitvėrė; nes jaučiai ją kratė.'),
  (@b10, 6, 7, 'Ir VIEŠPATIES pyktis užsidegė prieš Uzą; ir ten Dievas jį ištiko už jo klaidą; ir jis ten mirė šalia Dievo skrynios.'),
  (@b10, 6, 8, 'Ir Dovydas buvo nepatenkintas, kadangi VIEŠPATS padarė spragą Uzui; ir tą vietą iki šios dienos tebevadina Peres-Uzo vardu.'),
  (@b10, 6, 9, 'Ir tą dieną Dovydas išsigando VIEŠPATIES ir tarė: „Kaipgi VIEŠPATIES skrynia ateis pas mane?“'),
  (@b10, 6, 10, 'Taigi Dovydas nenorėjo perkelti VIEŠPATIES skrynios pas save į Dovydo miestą; bet Dovydas ją nugabeno į šalį, į gatiečio Obed-Edomo namus.'),
  (@b10, 6, 11, 'Ir VIEŠPATIES skrynia tris mėnesius pasiliko gatiečio Obed-Edomo namuose; ir VIEŠPATS laimino Obed-Edomą bei visus jo namiškius.'),
  (@b10, 6, 12, 'Ir karaliui Dovydui buvo pranešta, sakant: „VIEŠPATS palaimino Obed-Edomo namus ir viską, kas jam priklauso, dėl Dievo skrynios“. Taigi Dovydas nuėjo ir su džiaugsmu gabeno aukštyn Dievo skrynią iš Obed-Edomo namų į Dovydo miestą.'),
  (@b10, 6, 13, 'Ir buvo, kad VIEŠPATIES skrynios nešėjams paėjus šešetą žingsnių, jis aukodavo jaučius ir peniukšlius.'),
  (@b10, 6, 14, 'Ir Dovydas šoko prieš VIEŠPATĮ iš visų jėgų; ir Dovydas buvo apsijuosęs lininiu efodu.'),
  (@b10, 6, 15, 'Taip Dovydas ir visi Izraelio namai gabeno aukštyn VIEŠPATIES skrynią su šauksmu ir trimito garsu.'),
  (@b10, 6, 16, 'Ir VIEŠPATIES skryniai įėjus į Dovydo miestą, Sauliaus duktė Mikalė pažvelgė pro langą ir pamatė karalių Dovydą, šokinėjantį ir šokantį VIEŠPATIES akivaizdoje; ir ji paniekino jį savo širdyje.'),
  (@b10, 6, 17, 'Ir jie įnešė VIEŠPATIES skrynią ir ją padėjo į jos vietą viduryje padangtės, kurią Dovydas jai buvo pastatęs; ir Dovydas atnašavo deginamąsias atnašas ir taikos atnašas VIEŠPATIES akivaizdoje.'),
  (@b10, 6, 18, 'Ir baigęs atnašauti deginamąsias atnašas ir taikos atnašas, Dovydas palaimino tautą kariuomenių VIEŠPATIES vardu.'),
  (@b10, 6, 19, 'Ir padalijo visos tautos tarpe, tai yra visos Izraelio daugybės tarpe, tiek vyrams, tiek moterims, kiekvienam po duonos pyragą, po gerą gabalą mėsos ir po ąsotį vyno. Taip visa tauta išėjo, kiekvienas į savo namus.'),
  (@b10, 6, 20, 'Tada Dovydas sugrįžo savo namų laiminti. Ir Sauliaus duktė Mikalė išėjo Dovydo pasitikti ir tarė: „Koks šlovingas šiandien buvo Izraelio karalius, kuris šiandien apsinuogino savo tarnų tarnaičių akyse, kaip begėdiškai apsinuogina vienas iš beverčių žmonių!“'),
  (@b10, 6, 21, 'Ir Dovydas tarė Mikalei: „Tai buvo VIEŠPATIES akivaizdoje, kuris išrinko mane vietoje tavo tėvo ir vietoje visų jo namų, kad mane paskirtų valdovu VIEŠPATIES tautai, Izraeliui; todėl aš grosiu VIEŠPATIES akivaizdoje.'),
  (@b10, 6, 22, 'Ir būsiu dar begėdiškesnis negu šitoks, ir būsiu žemas savo paties akyse; o tarnaičių, apie kurias kalbėjai, aš būsiu gerbiamas“.'),
  (@b10, 6, 23, 'Todėl Sauliaus duktė Mikalė neturėjo vaiko iki savo mirties dienos.'),
  (@b10, 7, 1, 'Ir įvyko, kai karalius sėdėjo savo namuose, ir VIEŠPATS jam buvo suteikęs poilsį nuo visų jo aplinkinių priešų;'),
  (@b10, 7, 2, 'tada karalius tarė pranašui Natanui: „Štai aš gyvenu kedro namuose, bet Dievo skrynia gyvena tarp uždangalų“.'),
  (@b10, 7, 3, 'Ir Natanas tarė karaliui: „Eik, daryk viską, kas yra tavo širdyje; nes VIEŠPATS yra su tavimi“.'),
  (@b10, 7, 4, 'Ir įvyko tą pačią naktį, kad Natanui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b10, 7, 5, '„Eik ir pasakyk mano tarnui Dovydui: ‘Taip sako VIEŠPATS: Ar tu statysi man namus man juose gyventi?'),
  (@b10, 7, 6, 'Kai tuo tarpu negyvenau jokiuose namuose nuo to laiko, kai išvedžiau aukštyn Izraelio vaikus iš Egipto, iki šios dienos, bet vaikščiojau palapinėje ir padangtėje.'),
  (@b10, 7, 7, 'Visur, kur vaikščiojau su visais Izraelio vaikais, ar aš kalbėjau žodį su kuria nors iš Izraelio genčių, kuriai įsakiau ganyti mano tautą Izraelį, sakydamas: „Kodėl man nepastatėte kedro namų?“'),
  (@b10, 7, 8, 'Taigi dabar taip sakyk mano tarnui Dovydui: ‘Taip sako kariuomenių VIEŠPATS: „Aš tave paėmiau iš avidės, nuo sekimo paskui avis, kad būtum valdovas mano tautos, Izraelio;'),
  (@b10, 7, 9, 'ir buvau su tavimi visur, kur ėjai, ir iškirtau visus tavo priešus tau iš akivaizdos ir padariau tau didį vardą, lygų žemėje esančių didžiūnų vardui.'),
  (@b10, 7, 10, 'Be to, aš paskirsiu vietą savo tautai Izraeliui ir juos įsodinsiu, kad jie gyventų savo pačių vietoje ir nebepersikėlinėtų; ir kad nedorybės vaikai jų nebespaustų kaip anksčiau'),
  (@b10, 7, 11, 'ir kaip nuo to laiko, kai įsakiau teisėjams valdyti mano tautą Izraelį, ir padariau, kad ilsėtumeisi nuo visų savo priešų. Taip pat VIEŠPATS tau sako, kad jis padarys tau namus.'),
  (@b10, 7, 12, 'Ir kai išsipildys tavo dienos ir tu užmigsi prie savo tėvų, aš pakelsiu po tavęs tavo sėklą, kuri išeis iš tavo vidurių, ir aš įtvirtinsiu jo karalystę.'),
  (@b10, 7, 13, 'Jis pastatys mano vardui namus, o aš įtvirtinsiu jo karalystės sostą amžiams.'),
  (@b10, 7, 14, 'Aš būsiu jo tėvas, o jis bus mano sūnus. Jei jis vykdys neteisybę, aš jį bausiu žmonių lazda ir žmonių vaikų kirčiais;'),
  (@b10, 7, 15, 'bet mano gailestingumas nepasitrauks nuo jo, kaip jį atėmiau nuo Sauliaus, kurį pašalinau tavo akivaizdoje.'),
  (@b10, 7, 16, 'Ir tavo namai ir tavo karalystė bus amžinai įtvirtinti tavo akivaizdoje; tavo sostas bus amžiams įtvirtintas“.'),
  (@b10, 7, 17, 'Natanas kalbėjo Dovydui visus šituos žodžius ir pagal visą šitą regėjimą.'),
  (@b10, 7, 18, 'Tada karalius Dovydas, įėjęs ir atsisėdęs VIEŠPATIES akivaizdoje, tarė: „Kas aš esu, o Viešpatie DIEVE, ir kas yra mano namai, kad čia mane atvedei?'),
  (@b10, 7, 19, 'Ir tai buvo dar per maža tavo akyse, o Viešpatie DIEVE; bet tu dar kalbėjai ir apie savo tarno namus tolimoje ateityje. Ar toks yra žmogaus būdas, o Viešpatie DIEVE?');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b10, 7, 20, 'Ir ką gi daugiau Dovydas gali tau sakyti? Nes tu, Viešpatie DIEVE, žinai savo tarną.'),
  (@b10, 7, 21, 'Dėl tavo žodžio ir pagal tavo paties širdį tu padarei visus šituos didžius dalykus, kad praneštum juos savo tarnui.'),
  (@b10, 7, 22, 'Todėl tu esi didis, o VIEŠPATIE Dieve; nes nėra nei vieno tau lygaus, ir be tavęs nėra kito Dievo, pagal visa tai, ką esame girdėję savo ausimis.'),
  (@b10, 7, 23, 'Ir kokia kita tauta žemėje prilygsta tavo tautai – Izraeliui, kurią Dievas ėjo atpirkti sau kaip tautą, ir padaryti sau vardą, ir padaryti jums didžių ir baisių dalykų tavo šaliai, akivaizdoje tavo tautos, kurią išpirkai sau iš Egipto, iš tautų ir jų dievų?'),
  (@b10, 7, 24, 'Nes tu sau patvirtinai savo tautą Izraelį, kad būtų tau tauta per amžius; ir tu, VIEŠPATIE, tapai jų Dievu.'),
  (@b10, 7, 25, 'O dabar, o VIEŠPATIE Dieve, įtvirtink amžiams tą žodį, kurį kalbėjai apie savo tarną ir apie jo namus, ir padaryk, kaip sakei.'),
  (@b10, 7, 26, 'Ir tegul tavo vardas būna aukštinamas per amžius, sakant: ‘Kariuomenių VIEŠPATS yra Dievas Izraeliui’; ir tavo tarno Dovydo namai tebūna įtvirtinti tavo akivaizdoje.'),
  (@b10, 7, 27, 'Nes tu, o kariuomenių VIEŠPATIE, Izraelio Dieve, apreiškei savo tarnui, sakydamas: ‘Aš tau pastatysiu namus’; todėl tavo tarno širdyje radosi, kad melstųsi tau šia malda.'),
  (@b10, 7, 28, 'O dabar, o Viešpatie DIEVE, tu esi tas Dievas, ir tavo žodžiai yra tiesa, ir tu esi pažadėjęs savo tarnui šitą gerumą;'),
  (@b10, 7, 29, 'todėl dabar tepatinka tau laiminti savo tarno namus, kad jie amžinai išliktų tavo akivaizdoje; nes tu, o Viešpatie DIEVE, esi tai kalbėjęs; ir tavo palaiminimu tegul bus palaiminti tavo tarno namai per amžius“.'),
  (@b10, 8, 1, 'Ir po to įvyko, kad Dovydas sumušė filistinus ir juos pavergė; ir Dovydas paėmė Meteg-Amą iš filistinų rankos.'),
  (@b10, 8, 2, 'Ir jis sumušė Moabą ir, juos guldydamas ant žemės, matavo juos virve; dviem virvėm jis atmatavo užmušimui, o viena pilna virve – kad paliktų gyvus. Ir taip moabiečiai tapo Dovydo tarnais ir nešė dovanas.'),
  (@b10, 8, 3, 'Dovydas sumušė ir Rehobo sūnų Hadadezerą, Cobos karalių, kai jis ėjo atgauti savo ribų prie Eufrato upės.'),
  (@b10, 8, 4, 'Ir Dovydas atėmė iš jo tūkstantį vežimų, septynis šimtus raitelių ir dvidešimt tūkstančių pėstininkų; ir Dovydas perpjovė pakinklių sausgysles visiems vežimų arkliams, bet iš jų paliko šimtui vežimų.'),
  (@b10, 8, 5, 'Ir kai Damasko sirai atėjo pagelbėti Cobos karaliui Hadadezerui, Dovydas užmušė iš sirų dvidešimt du tūkstančius vyrų.'),
  (@b10, 8, 6, 'Paskui Dovydas padėjo įgulas Damasko Sirijoje; ir sirai tapo Dovydui tarnais ir nešė dovanas. Ir VIEŠPATS saugojo Dovydą visur, kur jis ėjo.'),
  (@b10, 8, 7, 'Ir Dovydas paėmė aukso skydus, buvusius ant Hadadezero tarnų, ir juos atgabeno į Jeruzalę.'),
  (@b10, 8, 8, 'Ir iš Hadadezero miestų Betacho ir Berotajo, karalius Dovydas paėmė nepaprastai daug žalvario.'),
  (@b10, 8, 9, 'Kai Hamato karalius Tojas išgirdo, kad Dovydas buvo sumušęs visą Hadadezero kariuomenę,'),
  (@b10, 8, 10, 'Tojas siuntė savo sūnų Joramą pas karalių Dovydą jo pasveikinti ir jį palaiminti, kadangi jis kovojo prieš Hadadezerą ir jį sumušė; nes Hadadezeras kariaudavo su Tojumi. Ir Joramas atgabeno su savimi sidabro indų, aukso indų ir žalvario indų;'),
  (@b10, 8, 11, 'kuriuos karalius Dovydas taip pat pašventė VIEŠPAČIUI su sidabru ir auksu, jo pašvęstu iš visų jo pavergtų tautų:'),
  (@b10, 8, 12, 'iš Sirijos, iš Moabo, iš Amono vaikų, iš filistinų, iš Amaleko ir iš grobio Rehobo sūnaus Hadadezero, Cobos karaliaus.'),
  (@b10, 8, 13, 'Ir Dovydas įsigijo vardą, kai sugrįžo sumušęs Druskos slėnyje sirus, aštuoniolika tūkstančių vyrų.'),
  (@b10, 8, 14, 'Ir jis pastatė Edome įgulas; visame Edome jis pastatė įgulas, ir visi iš Edomo tapo Dovydo tarnais. Ir VIEŠPATS saugojo Dovydą visur, kur jis ėjo.'),
  (@b10, 8, 15, 'Ir Dovydas karaliavo visam Izraeliui; ir Dovydas vykdė teismą ir teisingumą visai savo tautai.'),
  (@b10, 8, 16, 'Ir Cerujos sūnus Joabas vadovavo kariuomenei; o Ahiludo sūnus Jehozapatas buvo metraštininkas;'),
  (@b10, 8, 17, 'Ahitubo sūnus Cadokas ir Abjataro sūnus Ahimelechas buvo kunigai; o Seraja buvo raštininkas;'),
  (@b10, 8, 18, 'Ir Jehojados sūnus Benajas vadovavo keretams ir peletams; o Dovydo sūnūs buvo vyriausi valdovai.'),
  (@b10, 9, 1, 'Ir Dovydas tarė: „Ar yra dar kas likęs iš Sauliaus namų, kad jam padaryčiau gerumą dėl Jonatano?“'),
  (@b10, 9, 2, 'Ir iš Sauliaus namų buvo tarnas, kurio vardas buvo Ciba. Ir kai jį pašaukė pas Dovydą, karalius jam tarė: „Ar tu esi Ciba?“ Ir jis tarė: „Jis yra tavo tarnas“.'),
  (@b10, 9, 3, 'Ir karalius tarė: „Ar yra dar kas iš Sauliaus namų, kad jam parodyčiau Dievo gerumą?“ Ir Ciba tarė karaliui: „Jonatanas dar turi sūnų, raišą kojomis“.'),
  (@b10, 9, 4, 'Ir karalius jam tarė: „Kur jis yra?“ O Ciba tarė karaliui: „Štai jis yra Amielio sūnaus Machyro namuose, Lo-Debare“.'),
  (@b10, 9, 5, 'Tada karalius Dovydas pasiuntė ir atvedė jį iš Amielio sūnaus Machyro namų, iš Lo-Debaro.'),
  (@b10, 9, 6, 'Na, o Sauliaus sūnaus Jonatano sūnus Mefibošetas, įėjęs pas Dovydą, parpuolė veidu žemėn ir išreiškė pagarbą. Ir Dovydas tarė: „Mefibošetai“. O jis atsakė: „Štai tavo tarnas!“'),
  (@b10, 9, 7, 'Ir Dovydas jam tarė: „Nebijok; nes aš tikrai tau parodysiu gerumą dėl tavo tėvo Jonatano ir tau sugrąžinsiu visą tavo tėvo Sauliaus žemę; o tu nuolat valgysi duoną prie mano stalo“.'),
  (@b10, 9, 8, 'Ir jis nusilenkęs tarė: „Kas yra tavo tarnas, kad atsižvelgtum į tokį pastipusį šunį, kaip aš?“'),
  (@b10, 9, 9, 'Tada karalius pašaukė Cibą, Sauliaus tarną, ir jam tarė: „Viską, kas priklausė Sauliui ir visiems jo namams, aš atidaviau tavo valdovo sūnui.'),
  (@b10, 9, 10, 'Todėl tu, tavo sūnūs ir tavo tarnai dirbsite jam žemę ir tu įneši vaisius, kad tavo valdovo sūnus turėtų maisto valgyti; bet tavo valdovo sūnus Mefibošetas nuolat valgys duoną prie mano stalo“. Na, o Ciba turėjo penkiolika sūnų ir dvidešimt tarnų.'),
  (@b10, 9, 11, 'Tada Ciba tarė karaliui: „Tavo tarnas padarys pagal visa tai, ką mano viešpats karalius įsakė savo tarnui“. „Dėl Mefibošeto, – karalius sakė, – jis valgys prie mano stalo kaip vienas iš karaliaus sūnų“.'),
  (@b10, 9, 12, 'O Mefibošetas turėjo jauną sūnų, kurio vardas buvo Micha. Ir visi gyvenantys Cibos namuose buvo Mefibošetui tarnai.'),
  (@b10, 9, 13, 'Taip Mefibošetas gyveno Jeruzalėje; nes jis nuolat valgė prie karaliaus stalo; ir buvo raišas abiem kojomis.'),
  (@b10, 10, 1, 'Ir po to atsitiko, kad mirė Amono vaikų karalius, o jo sūnus Hanūnas karaliavo jo vietoje.'),
  (@b10, 10, 2, 'Tada Dovydas tarė: „Aš parodysiu Nahašo sūnui Hanūnui gerumą, kaip jo tėvas man parodė gerumą“. Ir per savo tarnų ranką Dovydas pasiuntė jo paguosti dėl jo tėvo. Ir Dovydo tarnai atėjo į Amono vaikų šalį.'),
  (@b10, 10, 3, 'Ir Amono vaikų kunigaikščiai tarė savo viešpačiui Hanūnui: „Ar manai, kad Dovydas gerbia tavo tėvą, kad atsiuntė tau guodėjų? Argi ne tam Dovydas atsiuntė savo tarnus pas tave, kad ištirtų miestą, jį išžvalgytų ir jį nugriautų?“'),
  (@b10, 10, 4, 'Todėl Hanūnas, paėmęs Dovydo tarnus, nuskuto vieną pusę jų barzdų, atpjovė jų drabužius per vidurį, tai yra iki jų sėdmenų, ir juos paleido.'),
  (@b10, 10, 5, 'Kai Dovydui tai pranešė, jis siuntė jų pasitikti, nes tie vyrai buvo labai sugėdyti; ir karalius tarė: „Pasilikite Jeriche, kol ataugs jūsų barzdos, ir tada sugrįžkite“.'),
  (@b10, 10, 6, 'Ir kai Amono vaikai pamatė, kad jie smirdėjo Dovydo akivaizdoje, Amono vaikai siuntė ir pasamdė Bet-Rehobo sirus ir Cobos sirus – dvidešimt tūkstančių pėstininkų, iš Maako karaliaus tūkstantį vyrų ir iš Iš-Tobo dvylika tūkstančių vyrų.'),
  (@b10, 10, 7, 'Ir tai išgirdęs, Dovydas pasiuntė Joabą ir visą galiūnų kariuomenę.'),
  (@b10, 10, 8, 'Ir išėję Amono vaikai išsirikiavo mūšiui vartų įėjime; o Cobos ir Rehobo sirai, Iš-Tobas ir Maaka buvo atskirai ant lauko.'),
  (@b10, 10, 9, 'Joabas, pamatęs, kad mūšio frontas buvo prieš jį iš priekio ir iš užnugario, išsirinko iš visų Izraelio rinktinių vyrų ir juos išrikiavo prieš sirus;'),
  (@b10, 10, 10, 'o likusią tautą davė savo broliui Abišajui į rankas, kad jis juos išrikiuotų prieš Amono vaikus.'),
  (@b10, 10, 11, 'Ir jis tarė: „Jei sirai bus man per stiprūs, tada tu man padėsi; bet jei Amono vaikai bus tau per stiprūs, tada aš ateisiu ir tau padėsiu.'),
  (@b10, 10, 12, 'Būk drąsus, ir elkimės vyriškai už mūsų tautą ir už mūsų Dievo miestus; ir VIEŠPATS tedaro tai, kas jam atrodo gerai“.'),
  (@b10, 10, 13, 'Ir priartėjo Joabas ir su juo esanti tauta į mūšį prieš sirus; ir jie bėgo jo akivaizdoje.'),
  (@b10, 10, 14, 'Ir kai Amono vaikai pamatė, kad sirai buvo pabėgę, tai jie irgi bėgo Abišajo akivaizdoje ir įėjo į miestą. Taip Joabas grįžo nuo Amono vaikų ir atėjo į Jeruzalę.'),
  (@b10, 10, 15, 'Ir pamatę, kad buvo sumušti Izraelio akivaizdoje, sirai susirinko.'),
  (@b10, 10, 16, 'Ir Hadarezeras pasiuntė ir išvedė sirus, esančius anapus upės; ir jie atėjo į Helamą; o Hadarezero kariuomenės vadas Šobachas ėjo jų priešakyje.'),
  (@b10, 10, 17, 'Ir kai tai buvo pranešta Dovydui, jis surinko visą Izraelį, perėjo per Jordaną ir atėjo į Helamą. O sirai išsirikiavo prieš Dovydą ir kovojo su juo.'),
  (@b10, 10, 18, 'Ir sirai bėgo Izraelio akivaizdoje; o Dovydas išžudė vyrus iš septynių šimtų sirų vežimų ir keturiasdešimt tūkstančių raitelių, ir sumušė jų kariuomenės vadą Šobachą, kuris ten mirė.'),
  (@b10, 10, 19, 'O visi karaliai, kurie buvo Hadarezero tarnai, matydami, kad buvo sumušti Izraelio akivaizdoje, sudarė taiką su Izraeliu ir jiems tarnavo. Taigi sirai bijojo vėl padėti Amono vaikams.'),
  (@b10, 11, 1, 'Ir įvyko, metams pasibaigus, tuo laiku, kai karaliai išeina į mūšį, Dovydas siuntė Joabą, su juo savo tarnus ir visą Izraelį; ir jie sunaikino Amono vaikus ir apgulė Rabą. Bet Dovydas dar pasiliko Jeruzalėje.'),
  (@b10, 11, 2, 'Ir atsitiko vakare, kad Dovydas atsikėlė nuo savo lovos ir vaikščiojo ant karaliaus namų stogo; ir nuo stogo jis pamatė besimaudančią moterį; o ta moteris buvo labai gražios išvaizdos.'),
  (@b10, 11, 3, 'Ir Dovydas siuntė ir teiravosi apie tą moterį; ir vienas tarė: „Ar tai ne Eliamo duktė Bat-Šeba, hetito Ūrijos žmona?“'),
  (@b10, 11, 4, 'Ir Dovydas siuntė pasiuntinius ir ją paėmė; ji įėjo pas jį, ir jis sugulė su ja; nes ji buvo apsivaliusi nuo savo nešvarumo; ir ji sugrįžo į savo namus.'),
  (@b10, 11, 5, 'Ir ta moteris pastojo ir pasiuntė bei pranešė Dovydui, sakydama: „Aš nėščia“.'),
  (@b10, 11, 6, 'Ir Dovydas pasiuntė Joabui, sakydamas: „Atsiųsk pas mane hetitą Ūriją“. Ir Joabas pasiuntė Ūriją pas Dovydą.'),
  (@b10, 11, 7, 'Ir Ūrijai pas jį atėjus, Dovydas jo paklausė, kaip sekasi Joabui, kaip sekasi tautai ir kaip sekasi karas.'),
  (@b10, 11, 8, 'Ir Dovydas tarė Ūrijai: „Eik žemyn į savo namus ir nusiplauk kojas“. Ir Ūrijai išėjus iš karaliaus namų, paskui jį pasekė valgis nuo karaliaus.'),
  (@b10, 11, 9, 'Bet Ūrija miegojo prie karaliaus namų durų su visais savo viešpaties tarnais ir nėjo žemyn į savo namus.'),
  (@b10, 11, 10, 'Ir kai Dovydui pranešė, sakydami: „Ūrija nėjo žemyn į savo namus“, Dovydas tarė Ūrijai: „Argi neparėjai iš savo kelionės? Tai kodėl nenuėjai žemyn į savo namus?“'),
  (@b10, 11, 11, 'Ir Ūrija tarė Dovydui: „Skrynia, Izraelis ir Juda pasilikę palapinėse; ir mano viešpats Joabas ir mano viešpaties tarnai stovyklauja atvirame lauke; tai ar man eiti į savo namus valgyti, gerti ir gulėti su savo žmona? Kaip tu gyvas ir kaip gyva tavo siela, aš to nedarysiu“.'),
  (@b10, 11, 12, 'Ir Dovydas tarė Ūrijai: „Pasilik čia dar ir šiandien, o rytoj tave paleisiu“. Taip Ūrija pasiliko Jeruzalėje tą dieną ir rytojaus dieną.'),
  (@b10, 11, 13, 'Ir kai Dovydas jį pakvietė, jis valgė ir gėrė jo akivaizdoje; ir jis jį prigirdė; o vakare jis išėjo gulti į savo patalą su savo viešpaties tarnais, bet nenuėjo žemyn į savo namus.'),
  (@b10, 11, 14, 'Ir ryte įvyko, kad Dovydas parašė Joabui laišką ir jį nusiuntė per Ūrijos ranką.'),
  (@b10, 11, 15, 'Ir jis rašė laiške, sakydamas: „Pastatyk Ūriją karščiausios kovos priekyje ir atsitraukite nuo jo, kad jis būtų sumuštas ir mirtų“.'),
  (@b10, 11, 16, 'Ir įvyko, kai Joabas stebėjo miestą, jis paskyrė Ūriją į vietą, apie kurią žinojo, kad ten buvo narsūs vyrai.'),
  (@b10, 11, 17, 'Ir to miesto vyrai išėjo ir kovojo su Joabu; ir krito keletas iš tautos, iš Dovydo tarnų; žuvo ir hetitas Ūrija.'),
  (@b10, 11, 18, 'Tada Joabas pasiuntė ir pranešė Dovydui visus dalykus apie tą karą;'),
  (@b10, 11, 19, 'ir įpareigojo pasiuntinį, sakydamas: „Kai būsi baigęs pasakoti karaliui to karo reikalus'),
  (@b10, 11, 20, 'ir, jei bus, kad karalius užsirūstins ir tau sakys: ‘Kodėl priėjote taip arti prie miesto kovodami? Argi nežinojote, kad jie gali šaudyti nuo sienos?'),
  (@b10, 11, 21, 'Kas užmušė Jerubešeto sūnų Abimelechą? Argi ne moteris numetė ant jo girnų akmens gabalą nuo sienos, kad jis mirė Tebece? Kodėl priartėjote prie sienos?’ Tada sakyk: ‘Tavo tarnas hetitas Ūrija irgi žuvo’“.'),
  (@b10, 11, 22, 'Taigi pasiuntinys nuėjo ir atėjęs pranešė Dovydui viską, dėl ko Joabas buvo jį siuntęs.'),
  (@b10, 11, 23, 'Ir pasiuntinys tarė Dovydui: „Tikrai tie vyrai įveikė mus ir išėjo pas mus į lauką, o mes buvome prieš juos iki vartų įėjimo.'),
  (@b10, 11, 24, 'Ir šauliai šaudė į tavo tarnus nuo sienos; ir žuvo keletas iš karaliaus tarnų, taip pat žuvo ir tavo tarnas hetitas Ūrija“.'),
  (@b10, 11, 25, 'Tada Dovydas tarė pasiuntiniui: „Taip sakyk Joabui: ‘Tavęs tenepykina tas dalykas, nes kalavijas ryja ir vieną, ir kitą; sustiprink savo kovą prieš miestą ir sugriauk jį’; ir jį padrąsink“.'),
  (@b10, 11, 26, 'Ir Ūrijos žmona, išgirdusi, kad jos vyras Ūrija žuvęs, gedėjo dėl savo vyro.'),
  (@b10, 11, 27, 'O gedului praėjus, Dovydas siuntė ir ją atvedė į savo namus, ir ji tapo jo žmona, ir pagimdė jam sūnų. Bet tas dalykas, kurį Dovydas buvo padaręs, nepatiko VIEŠPAČIUI.'),
  (@b10, 12, 1, 'Ir VIEŠPATS siuntė Nataną pas Dovydą. Ir pas jį atėjęs, jis jam tarė: „Du vyrai buvo viename mieste; vienas turtingas, o kitas beturtis.'),
  (@b10, 12, 2, 'Turtingasis turėjo be galo daug kaimenių ir bandų;'),
  (@b10, 12, 3, 'o beturtis nieko neturėjo, tik vieną avytę, kurią buvo nusipirkęs ir augino; ir ji užaugo pas jį ir su jo vaikais; ji valgė iš jo maisto, gėrė iš jo taurės ir gulėjo jam prie krūtinės, ir buvo jam kaip duktė.'),
  (@b10, 12, 4, 'Ir atėjus keleiviui pas turtingąjį vyrą, šis pagailėjo imti iš savo paties kaimenės ir iš savo paties bandos, kad paruoštų pas jį atėjusiam keleiviui; bet paėmė beturčio avytę ir ją paruošė pas jį atėjusiam vyrui“.'),
  (@b10, 12, 5, 'Ir Dovydo pyktis smarkiai užsidegė ant to vyro; ir jis tarė Natanui: „Kaip VIEŠPATS gyvas, tas vyras, kuris tai padarė, tikrai mirs;'),
  (@b10, 12, 6, 'o už avytę jis keturgubai atlygins, kadangi padarė tokį dalyką ir kadangi nepasigailėjo“.'),
  (@b10, 12, 7, 'Ir Natanas tarė Dovydui: „Tu esi tas vyras. Taip sako VIEŠPATS Izraelio Dievas: ‘Aš tave patepiau Izraelio karaliumi ir išgelbėjau tave iš Sauliaus rankos;'),
  (@b10, 12, 8, 'ir daviau tau tavo valdovo namus ir į tavo prieglobstį tavo valdovo žmonas, ir daviau tau Izraelio ir Judos namus; o jei to buvo per maža, aš dar būčiau tau tiek ir tiek davęs.'),
  (@b10, 12, 9, 'Kodėl paniekinai VIEŠPATIES įsakymą, darydamas pikta jo akyse? Tu nužudei kalaviju hetitą Ūriją ir jo žmoną paėmei sau į žmonas, ir jį nužudei Amono vaikų kalaviju.'),
  (@b10, 12, 10, 'Todėl dabar kalavijas niekada neatsitrauks nuo tavo namų; kadangi mane paniekinai ir paėmei hetito Ūrijos žmoną, kad būtų tavo žmona’.'),
  (@b10, 12, 11, 'Taip sako VIEŠPATS: ‘Štai aš sukelsiu prieš tave pikta iš tavo paties namų ir paimsiu tavo žmonas tavo paties akyse ir jas duosiu tavo artimui, ir jis suguls su tavo žmonomis šitos saulės akyse.'),
  (@b10, 12, 12, 'Nes tu tai padarei slaptai; bet aš tai padarysiu viso Izraelio akivaizdoje ir saulės akivaizdoje“.'),
  (@b10, 12, 13, 'Ir Dovydas tarė Natanui: „Nusidėjau prieš VIEŠPATĮ“. Ir Natanas tarė Dovydui: „VIEŠPATS taipogi yra pašalinęs tavo nuodėmę; tu nemirsi.'),
  (@b10, 12, 14, 'Tačiau, kadangi šituo poelgiu tu suteikei VIEŠPATIES priešams didelę progą piktžodžiauti, tau gimęs vaikas tikrai mirs“.'),
  (@b10, 12, 15, 'Ir Natanas išėjo į savo namus. Ir VIEŠPATS ištiko vaiką, kurį Ūrijos žmona pagimdė Dovydui, ir jis sunkiai susirgo.'),
  (@b10, 12, 16, 'Todėl Dovydas maldavo Dievą dėl vaiko; ir Dovydas pasninkavo ir įėjęs visą naktį gulėjo ant žemės.'),
  (@b10, 12, 17, 'Ir jo namų vyresnieji pakilę nuėjo prie jo, kad jį pakeltų nuo žemės; bet jis nenorėjo ir nevalgė su jais duonos.'),
  (@b10, 12, 18, 'Ir septintąją dieną atsitiko, kad vaikas mirė. Ir Dovydo tarnai bijojo jam pranešti, kad vaikas miręs; nes jie sakė: „Štai vaikui dar tebesant gyvam, jam kalbėjome, bet jis neklausė mūsų balso; kaip jis tada save vargins, jeigu jam pasakysime, kad vaikas miręs?“'),
  (@b10, 12, 19, 'Bet kai Dovydas pamatė, kad jo tarnai šnibždėjosi, Dovydas suprato, kad vaikas miręs; todėl Dovydas tarė savo tarnams: „Ar vaikas miręs?“ Ir jie tarė: „Jis miręs“.'),
  (@b10, 12, 20, 'Tada Dovydas, atsikėlęs nuo žemės, nusiprausė, pasitepė, pasikeitė savo drabužius ir atėjo į VIEŠPATIES namus, ir pagarbino; po to jis parėjo į savo namus; ir jam paprašius, jie padėjo prieš jį duonos, ir jis valgė.'),
  (@b10, 12, 21, 'Tada jo tarnai jam tarė: „Kas tai yra, ką tu padarei? Kol vaikas buvo gyvas, tu pasninkavai ir verkei dėl jo; bet kai vaikas mirė, tu atsikėlei ir valgei duonos“.'),
  (@b10, 12, 22, 'Ir jis tarė: „Vaikui tebesant gyvam aš pasninkavau ir verkiau, nes aš sakiau: ‘Kas žino, gal DIEVAS man bus malonus, kad vaikas gyventų’.'),
  (@b10, 12, 23, 'Bet dabar jis miręs, kodėl turėčiau pasninkauti? Argi aš galiu jį sugrąžinti? Aš eisiu pas jį, bet jis nesugrįš pas mane“.'),
  (@b10, 12, 24, 'Ir Dovydas paguodė savo žmoną Bat-Šebą ir, įėjęs pas ją, sugulė su ja; ir ji pagimdė sūnų ir praminė jį Saliamono vardu; ir VIEŠPATS jį mylėjo.'),
  (@b10, 12, 25, 'Ir jis pasiuntė per pranašo Natano ranką; ir dėl VIEŠPATIES jis praminė jį vardu Jedidijas.'),
  (@b10, 12, 26, 'Ir Joabas kovojo prieš Amono vaikų Rabą ir paėmė karališkąjį miestą.'),
  (@b10, 12, 27, 'Ir Joabas siuntė pasiuntinius pas Dovydą ir sakė: „Aš kovojau prieš Rabą ir paėmiau vandenų miestą.'),
  (@b10, 12, 28, 'Taigi dabar surink likusią tautą, stovyklauk prieš tą miestą ir paimk jį; kad aš nepaimčiau to miesto ir jis nebūtų pavadintas mano vardu“.'),
  (@b10, 12, 29, 'Ir Dovydas, surinkęs visą tautą, nuėjo į Rabą ir kovojo prieš ją, ir ją paėmė.'),
  (@b10, 12, 30, 'Ir jis nuėmė jų karaliaus karūną nuo jo galvos, kuri svėrė talentą aukso su brangakmeniais; ir ji buvo uždėta ant Dovydo galvos. Ir jis išgabeno iš miesto didelę gausybę grobio.'),
  (@b10, 12, 31, 'O jame buvusią tautą jis išvedė ir pakišo po pjūklais, po geležinėmis akėčiomis, po geležiniais kirviais, ir privertė juos eiti per plytų degimo krosnis; ir taip jis padarė visiems Amono vaikų miestams. Taip Dovydas ir visa tauta sugrįžo į Jeruzalę.'),
  (@b10, 13, 1, 'Ir po to atsitiko, kad Dovydo sūnus Abšalomas turėjo gražią seserį, kurios vardas buvo Tamara; ir ją pamilo Dovydo sūnus Amnonas.'),
  (@b10, 13, 2, 'Ir Amnonas taip sielojosi, kad jautėsi sergąs dėl savo sesers Tamaros; nes ji buvo mergelė; ir Amnonui atrodė sunku ką nors jai padaryti.'),
  (@b10, 13, 3, 'Bet Amnonas turėjo draugą, kurio vardas buvo Jonadabas, Dovydo brolio Šimos sūnų; o Jonadabas buvo labai gudrus vyras.'),
  (@b10, 13, 4, 'Ir jis jam tarė: „Kodėl tu, būdamas karaliaus sūnus, eini liesyn diena iš dienos? Ar man nepasakysi?“ Ir Amnonas jam tarė: „Aš myliu Tamarą, savo brolio Abšalomo seserį“.'),
  (@b10, 13, 5, 'Ir Jonadabas jam tarė: „Atsigulk į savo lovą ir dėkis sergąs; ir tavo tėvui atėjus tavęs pamatyti, jam sakyk: ‘Tegul ateina, meldžiu tave, mano sesuo Tamara ir teduoda man valgyti, ir teparuošia valgį mano akyse, kad galėčiau tai matyti ir valgyti iš jos rankos’“.'),
  (@b10, 13, 6, 'Taigi Amnonas atsigulė ir dėjosi sergąs; ir, karaliui atėjus jo aplankyti, Amnonas tarė karaliui: „Tegul ateina, meldžiu tave, mano sesuo Tamara ir tepadaro man matant pora pyragaičių, kad galėčiau valgyti iš jos rankos“.'),
  (@b10, 13, 7, 'Tada Dovydas siuntė Tamarai į namus, sakydamas: „Na, eik į savo brolio Amnono namus ir jam paruošk valgį“.'),
  (@b10, 13, 8, 'Taigi Tamara nuėjo į savo brolio Amnono namus; o jis gulėjo. Ir ji ėmė miltų, suminkė juos, padarė jo akyse pyragaičių ir iškepė tuos pyragaičius.'),
  (@b10, 13, 9, 'Ir paėmusi keptuvę, ji juos išėmė jo akivaizdoje; bet jis atsisakė valgyti. Ir Amnonas tarė: „Tegul visi išeina nuo manęs“. Ir jie visi išėjo nuo jo.'),
  (@b10, 13, 10, 'Ir Amnonas tarė Tamarai: „Įnešk valgį į kambarį, kad valgyčiau iš tavo rankos“. Ir Tamara paėmė pyragaičius, kuriuos buvo padariusi, ir įnešė juos savo broliui Amnonui į kambarį.'),
  (@b10, 13, 11, 'O jai atnešus juos jam valgyti, jis ją nutvėrė ir jai tarė: „Ateik, gulkis su manimi, mano seserie“.'),
  (@b10, 13, 12, 'O ji jam atsakė: „Ne, mano broli, neprievartauk manęs; nes taip neturi būti daroma Izraelyje; nedaryk šitos kvailystės.'),
  (@b10, 13, 13, 'O aš, kur aš nunešiu savo gėdą? O tu, tu būsi kaip vienas iš kvailių Izraelyje. Todėl dabar, meldžiu tave, kalbėk karaliui; nes jis nesulaikys manęs nuo tavęs“.'),
  (@b10, 13, 14, 'Tačiau jis nenorėjo klausyti jos balso, bet, būdamas stipresnis už ją, išprievartavo ją ir sugulė su ja.'),
  (@b10, 13, 15, 'Po to Amnonas jos be galo neapkentė; taip, kad neapykanta, kuria jis jos neapkentė, buvo didesnė už meilę, kuria jis ją mylėjo. Ir Amnonas jai tarė: „Kelkis, nešdinkis“.'),
  (@b10, 13, 16, 'O ji jam tarė: „Nėra priežasties; manęs išvarymas yra didesnė piktybė už kitą, kurią man padarei“. Bet jis nenorėjo jos klausyti.'),
  (@b10, 13, 17, 'Tada jis pašaukė savo tarną, kuris jam patarnavo, ir tarė: „Išvaryk dabar šitą moterį nuo manęs ir užsklęsk duris paskui ją“.'),
  (@b10, 13, 18, 'O ant savęs ji turėjo įvairiaspalvį drabužį; nes tokiais apsiaustais rengėsi karaliaus dukterys, kurios buvo mergelės. Tada jo tarnas ją išvedė laukan ir užsklendė duris paskui ją.'),
  (@b10, 13, 19, 'Ir Tamara apsibarstė galvą pelenais ir perplėšė savo įvairiaspalvį drabužį, buvusį ant jos, ir užsidėjusi ranką ant galvos ėjo verkdama.'),
  (@b10, 13, 20, 'Ir jos brolis Abšalomas jai tarė: „Ar tavo brolis Amnonas buvo su tavimi? Bet dabar tylėk, mano sese; jis yra tavo brolis; nepaisyk to dalyko“. Taigi Tamara paliko vieniša savo brolio Abšalomo namuose.'),
  (@b10, 13, 21, 'Bet karalius Dovydas išgirdęs visus tuos dalykus labai užsirūstino.'),
  (@b10, 13, 22, 'O Abšalomas nekalbėjo savo broliui Amnonui nei gero, nei blogo; nes Abšalomas nekentė Amnono, kadangi jis išprievartavo jo seserį Tamarą.'),
  (@b10, 13, 23, 'Ir įvyko po pilnų dviejų metų, kad Abšalomui buvo avikirpis Baal-Hacore, esančiame šalia Efraimo; ir Abšalomas pakvietė visus karaliaus sūnus.'),
  (@b10, 13, 24, 'Ir atėjęs pas karalių, Abšalomas tarė: „Dabar štai pas tavo tarną avikirpis; meldžiu tave, tegul eina karalius ir jo tarnai su tavo tarnu“.'),
  (@b10, 13, 25, 'Ir karalius tarė Abšalomui: „Ne, mano sūnau, visi teneisime, kad tavęs neapsunkintume“. O jis primygtinai jį prašė; tačiau jis nenorėjo eiti, bet palaimino jį.'),
  (@b10, 13, 26, 'Tada Abšalomas tarė: „Jei ne, tai leisk, meldžiu tave, mano broliui Amnonui eiti su mumis“. Ir karalius jam tarė: „Kodėl jis turėtų eiti su tavimi?“'),
  (@b10, 13, 27, 'Bet Abšalomas primygtinai jį prašė, kad jis leistų Amnonui ir visiems karaliaus sūnums eiti su juo.'),
  (@b10, 13, 28, 'Na, o Abšalomas buvo įsakęs savo tarnams, sakydamas: „Dabar stebėkite, kai Amnono širdis bus linksma nuo vyno ir kai jums pasakysiu: ‘Smokite Amnonui’; tada nužudykite jį, nebijokite; argi ne aš jums įsakiau? Būkite drąsūs ir narsūs“.'),
  (@b10, 13, 29, 'Ir Abšalomo tarnai padarė Amnonui, kaip Abšalomas buvo įsakęs. Tada visi karaliaus sūnūs atsikėlę užsėdo kiekvienas ant savo mulo ir pabėgo.'),
  (@b10, 13, 30, 'Ir įvyko, kad, jiems tebesant kelyje, žinia atėjo iki Dovydo, sakanti: „Abšalomas užmušė visus karaliaus sūnus, ir nei vieno iš jų neišliko“.'),
  (@b10, 13, 31, 'Tada karalius atsikėlė, perplėšė savo drabužius ir atsigulė ant žemės; ir visi jo tarnai stovėjo šalia su perplėštais savo drabužiais.'),
  (@b10, 13, 32, 'O Dovydo brolio Šimos sūnus Jonadabas atsiliepdamas tarė: „Tegul mano viešpats nemano, kad jie nužudė visus jaunuolius, karaliaus sūnus; nes tik Amnonas yra miręs; nes Abšalomo paskyrimu tai buvo nuspręsta nuo tos dienos, kai jis išprievartavo jo seserį Tamarą.'),
  (@b10, 13, 33, 'Taigi dabar tegul mano viešpats karalius neima to sau į širdį, manydamas, kad visi karaliaus sūnūs yra mirę; nes tik Amnonas yra miręs“.'),
  (@b10, 13, 34, 'Bet Abšalomas pabėgo. Ir jaunuolis, einantis sargybą, pakėlė akis ir pažiūrėjo, ir štai jam už nugaros, kalvos šlaito keliu, ateina daug liaudies.'),
  (@b10, 13, 35, 'Ir Jonadabas tarė karaliui: „Štai karaliaus sūnūs atėjo; kaip tavo tarnas sakė, taip ir yra“.'),
  (@b10, 13, 36, 'Ir įvyko, vos tik jam baigus kalbėti, štai atėjo karaliaus sūnūs ir pakeltu balsu verkė; taip pat karalius ir visi jo tarnai labai skaudžiai verkė.'),
  (@b10, 13, 37, 'Bet Abšalomas pabėgo ir nuėjo pas Gešūro karalių, Amihudo sūnų Talmają. Ir Dovydas kiekvieną dieną gedėjo savo sūnaus.'),
  (@b10, 13, 38, 'Taip Abšalomas pabėgo, nuėjo į Gešūrą ir ten išbuvo trejus metus.'),
  (@b10, 13, 39, 'O karaliaus Dovydo siela troško išeiti pas Abšalomą; nes jis buvo pasiguodęs dėl Amnono, kadangi jis buvo miręs.'),
  (@b10, 14, 1, 'Na, o Cerujos sūnus Joabas suprato, kad karaliaus širdis buvo nukreipta Abšalomo link.'),
  (@b10, 14, 2, 'Ir Joabas, pasiuntęs į Tekoją, atvedė iš ten išmintingą moterį ir jai tarė: „Meldžiu tave, dėkis gedinti ir apsivilk dabar gedulo drabužiais, nepasitepk aliejumi, bet būk kaip moteris, kuri daug laiko gedėjo dėl mirusiojo;'),
  (@b10, 14, 3, 'ir ateik pas karalių ir jam šitaip kalbėk“. Taigi Joabas įdėjo žodžius jai į burną.'),
  (@b10, 14, 4, 'Ir Tekojos moteris, kalbėdama karaliui, parpuolė veidu į žemę, išreiškė pagarbą ir tarė: „Padėk, o karaliau“.'),
  (@b10, 14, 5, 'Ir karalius jai tarė: „Kas tau yra?“ O ji atsakė: „Aš tikrai esu našlė, ir mano vyras miręs.'),
  (@b10, 14, 6, 'Ir tavo tarnaitė turėjo du sūnus, ir jie abu susivaidijo ant lauko ir, niekam nesant jų perskirti, vienas smogė kitam ir jį užmušė.'),
  (@b10, 14, 7, 'Ir štai visa šeima sukilusi prieš tavo tarnaitę, ir jie sakė: ‘Atiduok tą, kuris užmušė savo brolį, kad jį nužudytume už gyvybę jo brolio, kurį jis nužudė; ir taip pat sunaikinsime paveldėtoją’; ir taip jie užgesins mano likusią žariją ir nepaliks mano vyrui nei vardo, nei likučio ant žemės“.'),
  (@b10, 14, 8, 'Ir karalius tarė moteriai: „Eik į savo namus, o aš duosiu įpareigojimą apie tave“.'),
  (@b10, 14, 9, 'Ir Tekojos moteris tarė karaliui: „Mano viešpatie, o karaliau, ant manęs tebūna neteisybė ir ant mano tėvo namų; o karalius ir jo sostas tebūna nekaltas“.'),
  (@b10, 14, 10, 'Ir karalius tarė: „Kas tau ką kalbės, tą atvesk pas mane, ir jis daugiau tavęs nebelies“.'),
  (@b10, 14, 11, 'Tada ji tarė: „Tegul karalius, meldžiu tave, atsimena VIEŠPATĮ, savo Dievą, kad nebeleistum kraujo keršytojams naikinti, kad jie nesunaikintų mano sūnaus“. Ir jis tarė: „Kaip VIEŠPATS gyvas, nei vienas tavo sūnaus plaukas nenukris ant žemės“.'),
  (@b10, 14, 12, 'Tada moteris tarė: „Leisk, meldžiu tave, savo tarnaitei pasakyti vieną žodį mano viešpačiui karaliui“. Ir jis tarė: „Kalbėk“.'),
  (@b10, 14, 13, 'Ir ta moteris tarė: „Tad kodėl sumanei tokį dalyką prieš Dievo tautą? Nes karalius kalba šitą dalyką kaip kaltasis – tuo, kad karalius neparveda namo savo ištremtojo.'),
  (@b10, 14, 14, 'Nes mes būtinai turėsime mirti, ir esame kaip ant žemės išlietas vanduo, kurio nebegalima susemti; taip pat Dievas neatsižvelgia į jokį asmenį; tačiau jis sugalvoja būdą, kad jo ištremtieji nebūtų nuo jo atstumti“.'),
  (@b10, 14, 15, 'Taigi dabar, kad atėjau kalbėti karaliui, savo viešpačiui, apie šitą dalyką, tai dėl to, kad tauta mane įbaugino; ir tavo tarnaitė sakė: ‘Kalbėsiu dabar karaliui; gal karalius įvykdys savo tarnaitės prašymą.'),
  (@b10, 14, 16, 'Nes karalius išklausys, kad išvaduotų savo tarnaitę iš rankos vyro, norinčio išnaikinti mane ir kartu mano sūnų iš Dievo paveldo’.'),
  (@b10, 14, 17, 'Tada tavo tarnaitė tarė: ‘Mano viešpaties karaliaus žodis bus paguodžiantis; nes mano viešpats karalius yra toks, kaip Dievo angelas, skiriantis gera ir bloga’; todėl VIEŠPATS, tavo Dievas, bus su tavimi“.'),
  (@b10, 14, 18, 'Tada karalius atsakydamas tarė tai moteriai: „Meldžiu tave, neslėpk nuo manęs to dalyko, kurio tavęs paklausiu“. Ir ta moteris tarė: „Tegul kalba mano viešpats karalius“.'),
  (@b10, 14, 19, 'Ir karalius tarė: „Ar ne Joabo ranka yra su tavimi visame tame?“ Ir ta moteris atsakė ir tarė: „Kaip gyva tavo siela, mano viešpatie karaliau, niekas negali pasukti nei į dešinę, nei į kairę nuo to, ką mano viešpats karalius yra pasakęs; nes tavo tarnas Joabas, jis man įsakė ir įdėjo į tavo tarnaitės burną visus šituos žodžius;'),
  (@b10, 14, 20, 'kad tokiu pavidalu išdėstytų kalbą, tavo tarnas Joabas padarė šitą dalyką; o mano viešpats yra išmintingas pagal Dievo angelo išmintį, kad žinotų visa, kas yra žemėje“.'),
  (@b10, 14, 21, 'Ir karalius tarė Joabui: „Štai dabar padariau tą dalyką; taigi eik, parvesk jaunuolį Abšalomą“.'),
  (@b10, 14, 22, 'Ir Joabas, parpuolęs veidu į žemę, nusilenkė ir dėkojo karaliui; ir Joabas tarė: „Šiandien tavo tarnas žino, kad radau malonę tavo akyse, mano viešpatie, o karaliau, nes karalius patenkino savo tarno prašymą“.'),
  (@b10, 14, 23, 'Taigi Joabas pakilo, nuėjo į Gešūrą ir atvedė Abšalomą į Jeruzalę.'),
  (@b10, 14, 24, 'Ir karalius sakė: „Tegul jis grįžta į savo paties namus, bet tegul nemato mano veido“. Taip Abšalomas sugrįžo į savo paties namus, tačiau karaliaus veido neišvydo.'),
  (@b10, 14, 25, 'Bet visame Izraelyje nebuvo tokio labai giriamo dėl grožio, kaip Abšalomas: nuo kojų padų iki viršugalvio jame nebuvo jokio trūkumo.'),
  (@b10, 14, 26, 'Ir jam apsikirpus galvą (nes kiekvienų metų pabaigoje jis ją apsikirpdavo; kadangi plaukai būdavo sunkūs ant jo, todėl jis ją apsikirpdavo), jo galvos plaukai sverdavo du šimtus šekelių pagal karaliaus svorį.'),
  (@b10, 14, 27, 'Ir Abšalomui buvo gimę trys sūnūs ir viena duktė, kurios vardas buvo Tamara; ji buvo gražaus veido moteris.'),
  (@b10, 14, 28, 'Taip Abšalomas išgyveno Jeruzalėje dvejus pilnus metus, nematydamas karaliaus veido.'),
  (@b10, 14, 29, 'Todėl Abšalomas siuntė pas Joabą, kad siųstų jį pas karalių; bet jis nenorėjo ateiti pas jį; ir kai jis vėl siuntė antrą kartą, jis nenorėjo ateiti.'),
  (@b10, 14, 30, 'Todėl jis tarė savo tarnams: „Štai Joabo laukas yra šalia manojo, ir ten jis turi miežių; eikite ir jį padekite“. Ir Abšalomo tarnai padegė tą lauką.'),
  (@b10, 14, 31, 'Tada Joabas pakilo, atėjo pas Abšalomą į jo namus ir jam tarė: „Kodėl tavo tarnai padegė mano lauką?“'),
  (@b10, 14, 32, 'Ir Abšalomas atsakė Joabui: „Štai aš siunčiau pas tave, sakydamas: Ateik čionai, kad tave nusiųsčiau pas karalių, pasakyti: ‘Kodėl atėjau iš Gešūro? Man būtų buvę geriau, jei ten tebebūčiau’; taigi dabar leisk man išvysti karaliaus veidą; o jei manyje būtų kokia neteisybė, tegul jis nužudo mane“.'),
  (@b10, 14, 33, 'Taigi Joabas, atėjęs pas karalių, jam pranešė; ir kai jis pašaukė Abšalomą, jis atėjo pas karalių ir nusilenkė veidu į žemę karaliaus akivaizdoje; ir karalius pabučiavo Abšalomą.'),
  (@b10, 15, 1, 'Ir po to įvyko, kad Abšalomas pasiruošė vežimų, žirgų ir penkiasdešimt vyrų, idant bėgtų pirma jo.'),
  (@b10, 15, 2, 'Ir Abšalomas anksti atsikeldavo ir atsistodavo šalia vartų kelio; ir būdavo, kai koks nors ginčą turintis žmogus ateidavo pas karalių į teismą, tada Abšalomas jį pasišaukdavo ir sakydavo: „Iš kokio tu miesto?“ Ir jis sakydavo: „Tavo tarnas yra iš vienos Izraelio genčių“.'),
  (@b10, 15, 3, 'Ir Abšalomas jam sakydavo: „Štai tavo reikalai geri ir teisingi; bet nėra karaliaus įgalioto žmogaus, kad tave išklausytų“.'),
  (@b10, 15, 4, 'Abšalomas dar sakydavo: „O, kad mane paskirtų teisėju šalyje, kad kiekvienas, turintis bylą ar reikalą, galėtų ateiti pas mane, ir aš įvykdyčiau jam teisingumą!“'),
  (@b10, 15, 5, 'Ir buvo, kai prie jo kas nors prieidavo jam išreikšti pagarbą, jis ištiesdavo savo ranką, paimdavo jį ir pabučiuodavo.'),
  (@b10, 15, 6, 'Ir šitaip Abšalomas darė visam Izraeliui, atėjusiam pas karalių į teismą; taip Abšalomas pavogė Izraelio žmonių širdis.'),
  (@b10, 15, 7, 'Ir įvyko po keturiasdešimties metų, kad Abšalomas tarė karaliui: „Meldžiu tave, leisk man eiti ir ištesėti savo įžadą, kurį esu davęs VIEŠPAČIUI Hebrone.'),
  (@b10, 15, 8, 'Nes tavo tarnas davė įžadą gyvendamas Gešūre, Sirijoje, sakydamas: ‘Jei VIEŠPATS tikrai mane sugrąžins į Jeruzalę, tada aš tarnausiu VIEŠPAČIUI“.'),
  (@b10, 15, 9, 'Ir karalius jam tarė: „Eik ramybėje“. Taigi jis pakilęs nuėjo į Hebroną.'),
  (@b10, 15, 10, 'Bet Abšalomas išsiuntė žvalgus po visas Izraelio gentis, sakydamas: „Kai tik išgirsite trimito garsą, sakykite: ‘Abšalomas karaliauja Hebrone’“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b10, 15, 11, 'Ir su Abšalomu iš Jeruzalės ėjo du šimtai vyrų, kurie buvo pakviesti; ir jie ėjo iš paprastumo ir nieko nežinojo.'),
  (@b10, 15, 12, 'Ir Abšalomas, kai jis atnašavo aukas, siuntė pakviesti gilonietį Ahitofelį, Dovydo patarėją, iš jo miesto, tai yra iš Gilo. Ir sąmokslas buvo smarkus; nes tauta nuolat gausėjo pas Abšalomą.'),
  (@b10, 15, 13, 'Ir atėjo pasiuntinys pas Dovydą, sakydamas: „Izraelio žmonių širdys seka Abšalomą“.'),
  (@b10, 15, 14, 'Ir Dovydas tarė visiems savo tarnams, esantiems su juo Jeruzalėje: „Pakilkite ir bėkime; nes kitaip neišsigelbėsime nuo Abšalomo; paskubėkite išeiti, kad jis staiga neužkluptų mūsų, neatvestų ant mūsų pikto ir neišmuštų miesto kalavijo ašmenimis“.'),
  (@b10, 15, 15, 'Ir karaliaus tarnai tarė karaliui: „Štai tavo tarnai pasiruošę daryti visa, ką mano viešpats karalius nurodys“.'),
  (@b10, 15, 16, 'Ir karalius išėjo, ir visi jo namiškiai jam iš paskos. Ir karalius paliko dešimt moterų, sugulovių, namams saugoti.'),
  (@b10, 15, 17, 'Ir išėjo karalius bei visa tauta paskui jį ir apsistojo tolimoje vietoje.'),
  (@b10, 15, 18, 'Ir visi jo tarnai ėjo šalia jo; ir visi keretai, visi peletai ir visi gatiečiai – šeši šimtai žmonių, atėjusių paskui jį iš Gato, ėjo pirma karaliaus.'),
  (@b10, 15, 19, 'Tada karalius tarė gatiečiui Itajui: „Kodėl ir tu eini su mumis? Grįžk į savo vietovę ir pasilik pas karalių; nes tu esi svetimšalis ir tremtinys.'),
  (@b10, 15, 20, 'Kadangi tik vakar atvykai, ar šią dieną turėčiau tave versti, kad eitum pirmyn ir atgal su mumis? Kadangi aš einu kur galiu, grįžk ir parvesk savo brolius; tebūna su tavimi gailestingumas ir tiesa“.'),
  (@b10, 15, 21, 'O Itajas atsakydamas karaliui tarė: „Kaip VIEŠPATS gyvas ir kaip mano viešpats karalius gyvas, kur tik bus mano viešpats karalius, ar mirtyje, ar gyvenime, tikrai ten bus ir tavo tarnas“.'),
  (@b10, 15, 22, 'Ir Dovydas tarė Itajui: „Eik ir pereik“. Ir gatietis Itajas perėjo su visais savo vyrais ir su visais mažyliais, esančiais su juo.'),
  (@b10, 15, 23, 'Ir visa šalis garsiu balsu verkė, ir visa tauta perėjo; taip pat ir pats karalius perėjo per Kidrono upelį, ir visa tauta perėjo link dykumos kelio.'),
  (@b10, 15, 24, 'Ir štai ir Cadokas bei su juo visi levitai, nešantys Dievo Sandoros skrynią; ir jie pastatė Dievo skrynią; ir Abjataras ėjo aukštyn, kol visa tauta baigė išeiti iš miesto.'),
  (@b10, 15, 25, 'Ir karalius tarė Cadokui: „Nešk Dievo skrynią atgal į miestą; jei rasiu palankumą VIEŠPATIES akyse, jis mane sugrąžins ir parodys man ją bei jos buveinę;'),
  (@b10, 15, 26, 'bet jei jis taip pasakys: ‘Tu man nepatinki; štai aš čia, tegul jis man daro, kaip jam atrodo gerai“.'),
  (@b10, 15, 27, 'Taip pat karalius tarė kunigui Cadokui: „Ar tu ne regėtojas? Grįžk į miestą ramybėje, ir su jumis jūsų abu sūnūs, tavo sūnus Ahimaacas ir Abjataro sūnus Jonatanas.'),
  (@b10, 15, 28, 'Štai aš apsistosiu dykumos lygumoje, kol ateis iš jūsų žodis man paliūdyti“.'),
  (@b10, 15, 29, 'Taigi Cadokas ir Abjataras pargabeno Dievo skrynią į Jeruzalę; ir jie ten pasiliko.'),
  (@b10, 15, 30, 'O Dovydas lipo aukštyn Alyvų kalno pakilimu ir lipdamas verkė, ir buvo užsidengęs galvą, ir jis ėjo basas; ir visa su juo esanti tauta, kiekvienas užsidengė galvą, lipo aukštyn ir lipdami verkė.'),
  (@b10, 15, 31, 'Ir Dovydui pranešė, sakydami: „Ahitofelis yra tarp sąmokslininkų su Abšalomu“. Ir Dovydas tarė: „O VIEŠPATIE, meldžiu tave, paversk Ahitofelio patarimą kvailyste“.'),
  (@b10, 15, 32, 'Ir atsitiko, kad, Dovydui atėjus į kalno viršūnę, kur garbindavo Dievą, štai jo pasitikti atėjo arkietis Hušajas, su savo perplėštu rūbu ir žemėmis ant savo galvos;'),
  (@b10, 15, 33, 'jam Dovydas tarė: „Jei eisi su manimi, būsi man našta;'),
  (@b10, 15, 34, 'bet jei sugrįši į miestą ir sakysi Abšalomui: ‘Aš būsiu tavo tarnas, o karaliau; kaip ligi šiol buvau tavo tėvo tarnas, taip dabar būsiu ir tavo tarnas“, tada galėsi dėl manęs sužlugdyti Ahitofelio patarimą.'),
  (@b10, 15, 35, 'Ir argi nėra ten su tavimi kunigų Cadoko ir Abjataro? Todėl bus, kai tu ką nugirsi iš karaliaus namų, pranešk tai kunigams Cadokui ir Abjatarui.'),
  (@b10, 15, 36, 'Štai ten yra su jais abu jų sūnūs, Cadoko sūnus Ahimaacas ir Abjataro sūnus Jonatanas; ir per juos man siųsite kiekvieną dalyką, kurį išgirsite“.'),
  (@b10, 15, 37, 'Taigi Dovydo draugas Hušajas atėjo į miestą, ir Abšalomas atėjo į Jeruzalę.'),
  (@b10, 16, 1, 'Ir Dovydui paėjus truputį toliau nuo kalvos viršūnės, štai jį sutiko Mefibošeto tarnas Ciba su pora pabalnotų asilų, o ant jų – du šimtai duonos kepalų, šimtas ryšulių razinų bei šimtas vasarinių vaisių ir indas vyno.'),
  (@b10, 16, 2, 'Ir karalius tarė Cibai: „Ką tu šitais turi galvoje?“ Ir Ciba tarė: „Asilai karaliaus namiškiams joti; duona ir vasaros vaisiai jaunuoliams valgyti; o vynas – nusilpusiam dykumoje atsigerti“.'),
  (@b10, 16, 3, 'Ir karalius tarė: „O kur yra tavo valdovo sūnus?“ Ir Ciba tarė karaliui: „,Štai jis lieka Jeruzalėje; nes jis sakė: ‘Šiandien Izraelio namai man sugrąžins mano tėvo karalystę’“.'),
  (@b10, 16, 4, 'Tada karalius tarė Cibai: „Štai tavo yra viskas, kas priklauso Mefibošetui“. Ir Ciba tarė: „Aš nuolankiai maldauju tave, kad rasčiau malonę tavo akyse, mano viešpatie, o karaliau“.'),
  (@b10, 16, 5, 'Ir karaliui Dovydui atėjus į Bahurimą, štai iš ten išėjo vyras iš Sauliaus namų šeimos, kurio vardas Šimis, Geros sūnus; jis išėjo ir eidamas vis keikė.'),
  (@b10, 16, 6, 'Ir jis mėtė akmenimis į Dovydą bei į visus karaliaus Dovydo tarnus; ir visa tauta ir visi galingi vyrai buvo jo dešinėje ir kairėje.'),
  (@b10, 16, 7, 'Ir Šimis taip keikdamas sakė: „Išeik, išeik, kraugery, tu Belialo žmogau;'),
  (@b10, 16, 8, 'VIEŠPATS sugrąžino ant tavęs visą kraują Sauliaus namų, kurio vietoje tu karaliavai; ir VIEŠPATS atidavė karalystę į tavo sūnaus Abšalomo rankas; ir štai tu esi patekęs į savo nelaimę, nes tu kraugerys“.'),
  (@b10, 16, 9, 'Tada Cerujos sūnus Abišajas tarė karaliui: „Kodėl šitas pastipęs šuo turėtų keikti mano viešpatį karalių? Leisk man, meldžiu tave, nueiti ir nuimti jam galvą“.'),
  (@b10, 16, 10, 'O karalius tarė: „Kas man darbo su jumis, Cerujos sūnūs? Jis tegul taip keikia, kadangi VIEŠPATS jam pasakė: ‘Keik Dovydą’. Kas gi tuomet pasakys: ‘Kodėl taip padarei?’“'),
  (@b10, 16, 11, 'Ir Dovydas tarė Abišajui ir visiems savo tarnams: „Štai mano sūnus, išėjęs iš mano vidurių, ieško mano gyvybės; tai kaip dar labiau dabar šis benjaminas gali tai daryti? Palikite jį, ir tegul jis keikia; nes VIEŠPATS jam liepė.'),
  (@b10, 16, 12, 'Galbūt VIEŠPATS pažvelgs į mano sielvartą ir VIEŠPATS man atmokės geru už jo šios dienos keiksmą“.'),
  (@b10, 16, 13, 'Ir Dovydui bei jo vyrams einant keliu, Šimis ėjo kalvos šlaitu priešais jį ir eidamas keikė, mėtydamas į jį akmenimis ir barstydamas dulkes.'),
  (@b10, 16, 14, 'Ir karalius bei visa su juo esanti tauta atėjo išvargę ir ten atsigaivino.'),
  (@b10, 16, 15, 'O Abšalomas ir visa tauta, Izraelio žmonės, atėjo į Jeruzalę, ir Ahitofelis su juo.'),
  (@b10, 16, 16, 'Ir įvyko, kai arkietis Hušajas, Dovydo draugas, atėjo pas Abšalomą, Hušajas tarė Abšalomui: „Tegyvuoja karalius! Tegyvuoja karalius!“'),
  (@b10, 16, 17, 'Ir Abšalomas tarė Hušajui: „Ar toks tavo gerumas tavo draugui? Kodėl nėjai su savo draugu?“'),
  (@b10, 16, 18, 'Ir Hušajas tarė Abšalomui: „Ne; tačiau kurį VIEŠPATS, šita tauta ir visi Izraelio žmonės išsirinko, to aš būsiu ir pas tą pasiliksiu.'),
  (@b10, 16, 19, 'O, antra vertus, kam aš turėčiau tarnauti? Ar neturėčiau tarnauti jo sūnaus akivaizdoje? Kaip tarnavau tavo tėvo akivaizdoje, taip aš būsiu tavo akivaizdoje“.'),
  (@b10, 16, 20, 'Tada Abšalomas tarė Ahitofeliui: „Duokite iš savo tarpo patarimą, ką mums daryti“.'),
  (@b10, 16, 21, 'Ir Ahitofelis sakė Abšalomui: „Įeik pas savo tėvo suguloves, kurias jis paliko namų saugoti; ir visas Izraelis išgirs, kad tu esi neapkenčiamas savo tėvo; tada visų su tavimi esančių rankos sustiprės“.'),
  (@b10, 16, 22, 'Taigi jie ištiesė Abšalomui palapinę ant namo stogo; ir Abšalomas, visam Izraeliui matant, įėjo pas savo tėvo suguloves.'),
  (@b10, 16, 23, 'O Ahitofelio patarimas, kurį jis tomis dienomis duodavo, buvo tarsi kas pasiklaustų Dievo žodžio; toks buvo kiekvienas Ahitofelio patarimas ir Dovydui, ir Abšalomui.'),
  (@b10, 17, 1, 'Ahitofelis dar tarė Abšalomui: „Leisk man dabar išsirinkti dvylika tūkstančių vyrų, ir pakilęs šiąnakt vysiuosi Dovydą;'),
  (@b10, 17, 2, 'ir jį užpulsiu, kol jis tebėra nuvargęs ir nusilpusiomis rankomis, ir jį išgąsdinsiu; ir pabėgs visa su juo esanti tauta; o aš užmušiu tik karalių;'),
  (@b10, 17, 3, 'ir sugrąžinsiu visą tautą pas tave; vyras, kurio ieškai, – tai tarsi visi sugrįžtų; taip visa tauta bus ramybėje“.'),
  (@b10, 17, 4, 'Ir tas pasakymas labai patiko Abšalomui ir visiems Izraelio vyresniesiems.'),
  (@b10, 17, 5, 'Tada Abšalomas tarė: „Dabar pakvieskite ir arkietį Hušają ir taip pat paklausykime, ką jis sako“.'),
  (@b10, 17, 6, 'Ir Hušajui atėjus pas Abšalomą, Abšalomas jam tarė, sakydamas: „Taip kalbėjo Ahitofelis; ar mums daryti pagal jo pasakymą? Jei ne; tu kalbėk“.'),
  (@b10, 17, 7, 'Ir Hušajas tarė Abšalomui: „Šįkart patarimas, kurį davė Ahitofelis, nėra geras.'),
  (@b10, 17, 8, 'Nes, – tarė Hušajas, – tu žinai savo tėvą ir jo vyrus, kad jie yra galingi vyrai ir kad jie yra susierzinę kaip meška, kuriai atėmė jauniklius ant lauko; ir tavo tėvas yra karo vyras ir nenakvos su tauta.'),
  (@b10, 17, 9, 'Štai dabar jis yra pasislėpęs kokioje nors duobėje ar kokioje kitoje vietoje; ir atsitiks, kai pradžioje kai kurie iš jų kris, tada kas nors tai išgirdęs pasakys: ‘Žudynės tarp žmonių, sekančių paskui Abšalomą’.'),
  (@b10, 17, 10, 'Taip pat ir narsuolis, kurio širdis yra kaip liūto širdis, visiškai sutirps; nes visas Izraelis žino, kad tavo tėvas yra galingas vyras ir kad su juo esantieji yra narsūs vyrai.'),
  (@b10, 17, 11, 'Todėl aš patariu, kad būtų pilnai surinktas pas tave visas Izraelis nuo Dano iki Beer-Šebos, kaip pajūrio smėlio daugybė; ir kad tu pats asmeniškai eitum į mūšį.'),
  (@b10, 17, 12, 'Taip mes jį užpulsime kokioje nors vietoje, kur jis bus rastas, ir pulsime ant jo, kaip rasa krenta ant žemės; ir nei vieno nebeišliks – nei iš jo, nei iš su juo esančių vyrų.'),
  (@b10, 17, 13, 'Be to, jei jis bus įėjęs į miestą, tada visas Izraelis atsineš prie to miesto virves, ir mes jį nutempsime į upę, kol ten nebus galima rasti nei akmenėlio“.'),
  (@b10, 17, 14, 'Ir Abšalomas ir visi Izraelio žmonės tarė: „Arkiečio Hušajo patarimas geresnis už Ahitofelio patarimą“. Nes VIEŠPATS buvo pasirūpinęs sužlugdyti gerąjį Ahitofelio patarimą tuo tikslu, kad VIEŠPATS užtrauktų ant Abšalomo nelaimę.'),
  (@b10, 17, 15, 'Tada Hušajas tarė kunigams Cadokui ir Abjatarui: „Taip ir taip Ahitofelis patarė Abšalomui ir Izraelio vyresniesiems; o taip ir taip aš patariau.'),
  (@b10, 17, 16, 'Taigi dabar skubiai siųskite ir praneškite Dovydui, sakydami: ‘Šiąnakt nenakvok dykumos lygumose, bet greitai pereik; kad nebūtų prarytas karalius ir visa su juo esanti liaudis’“.'),
  (@b10, 17, 17, 'Na, o Jonatanas ir Ahimaacas apsistojo prie En-Rogelio; nes jie negalėjo pasirodyti įeiną į miestą; ir tarnaitė nuėjo ir jiems pranešė; o jie nuėjo ir pranešė karaliui Dovydui.'),
  (@b10, 17, 18, 'Tačiau vienas berniukas juos pamatė ir pranešė Abšalomui; bet juodu skubiai nuėjo ir atėjo į vieno žmogaus namus Bahurime, turinčio šulinį savo kieme; jie nusileido į jį.'),
  (@b10, 17, 19, 'Ir moteris paėmusi užtiesė dangalą ant šulinio angos ir pabarstė ant jo maltų grūdų; ir tai nebuvo žinoma.'),
  (@b10, 17, 20, 'Ir Abšalomo tarnams atėjus pas tą moterį į namus, jie tarė: „Kur yra Ahimaacas ir Jonatanas?“ O ta moteris jiems tarė: „Jie perėjo vandens upelį“. Ir išieškoję ir negalėję jų rasti, jie sugrįžo į Jeruzalę.'),
  (@b10, 17, 21, 'Ir įvyko, kad jiems nuėjus anie išlipo iš to šulinio ir nuėję pranešė karaliui Dovydui, ir tarė Dovydui: „Kelkis ir skubiai pereik per vandenį; nes taip Ahitofelis patarė prieš jus“.'),
  (@b10, 17, 22, 'Tada pakilo Dovydas ir visa su juo esanti tauta ir perėjo per Jordaną; iki ryto aušros neliko nei vieno iš jų, kuris nebūtų perėjęs per Jordaną.'),
  (@b10, 17, 23, 'O Ahitofelis, pamatęs, kad jo patarimas nebuvo vykdomas, pasibalnojo asilą, pakilo, parvyko namo į savo namą, į savo miestą, sutvarkė savo namų reikalus ir pasikorė, ir mirė, ir buvo palaidotas savo tėvo kape.'),
  (@b10, 17, 24, 'Tada Dovydas atvyko į Mahanaimą. O Abšalomas perėjo per Jordaną, jis ir visi Izraelio vyrai su juo.'),
  (@b10, 17, 25, 'Ir Abšalomas paskyrė Amasą kariuomenės vadu vietoj Joabo; tas Amasa buvo sūnus vyro, kurio vardas buvo Itra, izraelitas, kuris įėjo pas Abigailę, Nahašo dukterį, Joabo motinos Cerujos seserį.'),
  (@b10, 17, 26, 'Taigi Izraelis ir Abšalomas stovyklavo Gileado šalyje.'),
  (@b10, 17, 27, 'Ir įvyko, kad Dovydui atvykus į Mahanaimą, Nahašo sūnus Šobis iš Amono vaikų Rabos ir Machyras, sūnus Amielio iš Lo-Debaro, ir gileadietis Barzilajas iš Rogelimo'),
  (@b10, 17, 28, 'atgabeno patalų, dubenų, molinių indų, kviečių, miežių, miltų, paskrudintų grūdų, pupų, lęšių, paskrudintų ankščių,'),
  (@b10, 17, 29, 'medaus, sviesto, avių ir karvės sūrio Dovydui ir su juo esančiai liaudžiai, kad valgytų; nes jie sakė: „Tauta išalkusi, nuvargusi ir ištroškusi dykumoje“.'),
  (@b10, 18, 1, 'Ir Dovydas suskaičiavo su juo buvusią liaudį ir paskyrė jiems tūkstančių vadus bei šimtų vadus.'),
  (@b10, 18, 2, 'Ir Dovydas išsiuntė trečdalį tautos Joabo rankai vadovaujant, trečdalį Cerujos sūnaus Joabo brolio Abišajo rankai vadovaujant ir trečdalį gatiečio Itajaus rankai vadovaujant. Ir karalius tarė tautai: „Tikrai aš pats irgi eisiu su jumis“.'),
  (@b10, 18, 3, 'Bet liaudis atsakė: „Tu neisi; nes jei mes pabėgsime, jiems mes nerūpėsime; ir jei pusė mūsų žūtų, jiems mes nerūpėsime; bet tu dabar esi vertas dešimties tūkstančių mūsų; todėl dabar yra geriau, kad tu mums padėtum iš miesto“.'),
  (@b10, 18, 4, 'Ir karalius jiems tarė: „Darysiu, kas jums atrodo geriausia“. Ir karalius atsistojo šalia vartų, o visa tauta išėjo šimtais ir tūkstančiais.'),
  (@b10, 18, 5, 'Ir karalius įsakė Joabui, Abišajui ir Itajui, sakydamas: „Švelniai dėl manęs pasielkite su jaunuoliu, tai yra Abšalomu“. Ir visa tauta girdėjo, kai karalius įpareigojo visus vadus dėl Abšalomo.'),
  (@b10, 18, 6, 'Taigi tauta išėjo ant lauko prieš Izraelį; ir mūšis buvo Efraimo miške,'),
  (@b10, 18, 7, 'kur Izraelio tauta buvo žudoma Dovydo tarnų akivaizdoje, ir ten tą dieną buvo didelės dvidešimties tūkstančių vyrų žudynės.'),
  (@b10, 18, 8, 'Nes mūšis ten išplito po visą šalies paviršių; ir tą dieną miškas prarijo daugiau liaudies negu kalavijas.'),
  (@b10, 18, 9, 'Ir Abšalomas susitiko su Dovydo tarnais. Ir Abšalomas jojo ant mulo, o mului paėjus po didelio ąžuolo tankiomis šakomis, jo galva įstrigo į ąžuolą, ir jis pakibo tarp dangaus ir žemės; o po juo buvęs mulas nuėjo.'),
  (@b10, 18, 10, 'Ir vienas vyras tai pamatęs, pranešė Joabui ir tarė: „Štai aš mačiau Abšalomą, pakibusį ąžuole“.'),
  (@b10, 18, 11, 'Ir Joabas tarė tam vyrui, kuris jam pranešė: „Štai tu jį matei, o kodėl jo nenumušei ten žemėn? Aš būčiau tau davęs dešimt sidabro šekelių ir diržą“.'),
  (@b10, 18, 12, 'O tas vyras tarė Joabui: „Nors ir gaučiau tūkstantį sidabro šekelių į savo rankas, tačiau neištiesčiau savo rankos prieš karaliaus sūnų; nes mums girdint karalius įpareigojo tave, Abišają ir Itają, sakydamas: ‘Saugokitės, kad niekas neliestų jaunuolio Abšalomo’.'),
  (@b10, 18, 13, 'Kitaip būčiau padaręs melagingai prieš savo paties gyvybę; nes nuo karaliaus nieko nėra paslėpta, ir tu pats būtum nusistatęs prieš mane“.'),
  (@b10, 18, 14, 'Tada Joabas tarė: „Aš taip negaišiu su tavimi“. Ir pasiėmęs tris ietis į ranką, jis persmeigė jomis Abšalomo širdį, kol šis dar buvo gyvas ąžuolo viduryje.'),
  (@b10, 18, 15, 'Ir dešimt jaunuolių, nešusių Joabo ginklus, apsupo ir mušė Abšalomą, ir jį nužudė.'),
  (@b10, 18, 16, 'Ir Joabas pūtė trimitą, ir tauta sugrįžo nuo vijimosi paskui Izraelį; nes Joabas sulaikė tautą.'),
  (@b10, 18, 17, 'Ir paėmę Abšalomą, jie įmetė jį miške į didelę duobę ir sukrovė ant jo labai didelę akmenų krūvą; ir visas Izraelis pabėgo kiekvienas į savo palapinę.'),
  (@b10, 18, 18, 'Na, o per savo gyvenimą Abšalomas buvo paėmęs ir pasistatęs sau stulpą, esantį Karaliaus slėnyje; nes jis sakė: „Neturiu sūnaus, kuris išlaikytų mano vardą atminimui“; ir jis praminė stulpą savo vardu; ir jis iki šios dienos vadinamas Abšalomo vieta.'),
  (@b10, 18, 19, 'Tada Cadoko sūnus Ahimaacas tarė: „Leisk man dabar bėgti ir nunešti karaliui žinią, kad VIEŠPATS atkeršijo už jį jo priešams“.'),
  (@b10, 18, 20, 'O Joabas jam tarė: „Tu neneši šią dieną žinios, bet nuneši žinią kitą dieną; bet šią dieną neneši žinios, nes karaliaus sūnus yra miręs“.'),
  (@b10, 18, 21, 'Tada Joabas tarė kušiečiui: „Eik, pranešk karaliui, ką matei“. Ir kušietis nusilenkė Joabui ir nubėgo.'),
  (@b10, 18, 22, 'Tada Cadoko sūnus Ahimaacas dar kartą tarė Joabui: „Bet vis dėlto, meldžiu tave, leisk ir man bėgti paskui kušietį“. Ir Joabas tarė: „Kodėl nori bėgti, mano sūnau? Juk neturi tinkamos žinios.“'),
  (@b10, 18, 23, '„Bet vis dėlto, – tarė jis, – leisk man bėgti“. Ir jis tarė jam: „Bėk“. Tada Ahimaacas nubėgo lygumos keliu ir pralenkė kušietį.'),
  (@b10, 18, 24, 'O Dovydas sėdėjo tarp dviejų vartų; ir sargybinis nuėjo aukštyn ant vartų stogo ant sienos ir pakėlęs akis žiūrėjo, ir štai bėga vienas vyras.'),
  (@b10, 18, 25, 'Ir sargybinis šaukdamas pranešė karaliui. Ir karalius tarė: „Jei jis vienas, tai žinia jo burnoje“. Ir jis sparčiai ėjo ir artinosi.'),
  (@b10, 18, 26, 'Ir sargybinis pamatė kitą bėgantį vyrą; ir sargybinis sušuko vartininkui, sakydamas: „Štai kitas vyras, bėga vienas“. Ir karalius tarė: „Jis irgi atneša žinią’“.'),
  (@b10, 18, 27, 'Ir sargybinis tarė: „Aš manau, pirmojo bėgimas – kaip Cadoko sūnaus Ahimaaco bėgimas“. Ir karalius tarė: „Jis geras vyras ir ateina su gera žinia“.'),
  (@b10, 18, 28, 'Ir Ahimaacas pašaukė ir tarė karaliui: „Ramybė“. Ir jis parpuolė veidu žemėn prieš karalių ir tarė: „Tebūna palaimintas VIEŠPATS, tavo Dievas, kuris atidavė tuos vyrus, kurie pakėlė savo rankas prieš mano viešpatį karalių“.'),
  (@b10, 18, 29, 'Ir karalius tarė: „Ar jaunuolis Abšalomas sveikas?“ O Ahimaacas atsakė: „Kai Joabas pasiuntė karaliaus tarną ir mane, tavo tarną, aš mačiau didelį sąmyšį, bet nežinojau, kas tai buvo“.'),
  (@b10, 18, 30, 'Ir karalius tarė jam: „Pasuk į šalį ir atsistok čia“. Ir jis pasuko į šalį ir stovėjo.'),
  (@b10, 18, 31, 'Ir štai atvyko kušietis; ir kušietis tarė: „Žinia, mano viešpatie karaliau; nes VIEŠPATS šią dieną atkeršijo už tave visiems, sukilusiems prieš tave“.'),
  (@b10, 18, 32, 'Ir karalius tarė kušiečiui: „Ar jaunuolis Abšalomas sveikas?“ Ir kušietis atsakė: „Mano viešpaties karaliaus priešams ir visiems, kurie sukyla prieš tave, kad darytų tau pikta, tebūna, kaip yra tam jaunuoliui“.'),
  (@b10, 18, 33, 'Ir karalius labai susijaudino ir nuėjo aukštyn į kambarį virš vartų, ir verkė; ir eidamas taip sakė: „O mano sūnau Abšalomai, mano sūnau, mano sūnau Abšalomai! O kad aš būčiau miręs tavo vietoje, o Abšalomai, mano sūnau, mano sūnau!“'),
  (@b10, 19, 1, 'Ir buvo pranešta Joabui: „Štai karalius verkia ir gedi Abšalomo“.'),
  (@b10, 19, 2, 'Ir tą dieną pergalė virto gedulu visai tautai; nes tą dieną tauta girdėjo sakant, kaip karalius liūdi savo sūnaus.'),
  (@b10, 19, 3, 'Ir tą dieną tauta vogčiomis įėjo į miestą, kaip susigėdę išslenka žmonės, kai jie pabėga iš mūšio.'),
  (@b10, 19, 4, 'Bet karalius apsidengė savo veidą, ir garsiu balsu karalius šaukė: „O, mano sūnau, Abšalomai, o Abšalomai, mano sūnau, mano sūnau!“'),
  (@b10, 19, 5, 'Ir Joabas atėjo pas karalių į namus ir tarė: „Tu šią dieną sugėdinai veidus visų savo tarnų, kurie šią dieną išgelbėjo tavo gyvybę, tavo sūnų ir tavo dukterų gyvybes, tavo žmonų gyvybes ir tavo sugulovių gyvybes;'),
  (@b10, 19, 6, 'mylėdamas savo priešus ir nekęsdamas savo draugų. Nes tu šią dieną pareiškei, kad nepaisai nei kunigaikščių, nei tarnų; nes šią dieną aš matau, kad jei Abšalomas būtų gyvas, o mes visi šią dieną būtume žuvę, tai tuo būtum labai patenkintas.'),
  (@b10, 19, 7, 'Taigi dabar kelkis, išeik ir paguodžiančiai kalbėk savo tarnams; nes, prisiekiu VIEŠPAČIU, jei neišeisi, tai šiąnakt nei vienas nepasiliks su tavimi; o tai tau bus blogiau už visas nelaimes, kurios tave ištiko nuo pat tavo jaunystės iki šiol“.'),
  (@b10, 19, 8, 'Tada karalius atsikėlė ir atsisėdo vartuose. Ir visai tautai pranešė, sakydami: „Štai karalius sėdi vartuose“. Ir visa tauta atėjo karaliaus akivaizdon; nes Izraelis buvo pabėgęs, kiekvienas į savo palapinę.'),
  (@b10, 19, 9, 'Ir visa tauta ginčijosi visose Izraelio gentyse, sakydami: „Karalius mus išvadavo iš mūsų priešų rankų ir jis mus išvadavo iš filistinų rankų; o dabar yra pabėgęs iš šalies dėl Abšalomo.'),
  (@b10, 19, 10, 'Ir Abšalomas, kurį buvome patepę mums valdyti, žuvęs mūšyje. Tai kodėl dabar nesakote nei žodžio apie karaliaus sugrąžinimą?“'),
  (@b10, 19, 11, 'Ir karalius Dovydas pasiuntė kunigams Cadokui ir Abjatarui, sakydamas: „Kalbėkite Judos vyresniesiems, sakydami: ‘Kodėl jūs esate paskutiniai sugrąžinti karalių į jo namus? Kadangi viso Izraelio kalba atėjo iki karaliaus, tai yra iki jo namų.'),
  (@b10, 19, 12, 'Jūs esate mano broliai, jūs – mano kaulai ir mano kūnas; tai kodėl jūs esate paskutiniai sugrąžinti karalių?’'),
  (@b10, 19, 13, 'Ir Amasai sakykite: ‘Argi tu nesi iš mano kaulo ir iš mano kūno? Tegul man Dievas padaro taip ir dar daugiau, jei tu visam laikui nebūsi mano akivaizdoje kariuomenės vadas Joabo vietoje’“.'),
  (@b10, 19, 14, 'Ir jis palenkė visų Judos žmonių širdis tarsi vieno žmogaus širdį; taip, kad jie nusiuntė karaliui šią žinią: „Sugrįžk tu ir visi tavo tarnai“.'),
  (@b10, 19, 15, 'Taigi karalius sugrįžo ir atėjo iki Jordano. Ir Juda atėjo į Gilgalą, kad eitų karaliaus pasitikti, kad pervestų karalių per Jordaną.'),
  (@b10, 19, 16, 'Ir Gero sūnus Šimis, benjaminas iš Bahurimo, skubėjo ir leidosi su Judos vyrais karaliaus Dovydo pasitikti.'),
  (@b10, 19, 17, 'Ir su juo buvo tūkstantis vyrų iš Benjamino, Sauliaus namų tarnas Ciba ir su juo penkiolika jo sūnų bei dvidešimt jo tarnų; ir jie perėjo Jordaną pirma karaliaus.'),
  (@b10, 19, 18, 'Ir persikėlė plaustas, kad perkeltų karaliaus namiškius ir padarytų, kas jam atrodė gera. Ir Gero sūnus Šimis parpuolė žemėn prieš karalių, kai jis buvo perėjęs per Jordaną;'),
  (@b10, 19, 19, 'ir tarė karaliui: „Tegul mano viešpats neįskaito man neteisybės, ir neprisimink to, ką tavo tarnas ydingai darė tą dieną, kai mano viešpats karalius išėjo iš Jeruzalės, ir karalius teneima to į savo širdį.'),
  (@b10, 19, 20, 'Nes tavo tarnas žino, kad nusidėjau; tad štai šią dieną atvykau pirmas iš visų Juozapo namų, kad nueičiau žemyn savo viešpaties karaliaus pasitikti“.'),
  (@b10, 19, 21, 'Bet Cerujos sūnus Abišajas atsakydamas tarė: „Ar Šimis neturėtų būti užmuštas už tai, kad keikė VIEŠPATIES pateptąjį?“'),
  (@b10, 19, 22, 'O Dovydas tarė: „Kas man darbo su jumis, Cerujos sūnūs, kad man šią dieną būtumėte mano priešininkai? Ar kas nors šią dieną turėtų būti užmuštas Izraelyje? Ar aš nežinau, kad šią dieną esu Izraelio karalius?“'),
  (@b10, 19, 23, 'Taigi karalius tarė Šimiui: „Tu nemirsi“. Ir karalius jam prisiekė.'),
  (@b10, 19, 24, 'Ir Sauliaus sūnus Mefibošetas atėjo žemyn karaliaus pasitikti. Jis nebuvo apsitvarkęs savo pėdų nei kirpęs savo barzdos, nei plovęs savo drabužių nuo tos dienos, kai išvyko karalius, iki tos dienos, kai jis sugrįžo ramybėje.'),
  (@b10, 19, 25, 'Ir įvyko, kad jam atvykus į Jeruzalę karaliaus pasitikti, karalius jam tarė: „Kodėl nevykai su manimi, Mefibošetai?“'),
  (@b10, 19, 26, 'Ir jis atsakė: „Mano viešpatie, o karaliau, mano tarnas mane apgavo; nes tavo tarnas sakė: ‘Pasibalnosiu asilą, kad galėčiau ant jo joti ir vykti pas karalių; nes tavo tarnas yra luošas.'),
  (@b10, 19, 27, 'Ir jis apšmeižė tavo tarną mano viešpačiui karaliui; bet mano viešpats karalius yra kaip Dievo angelas; taigi daryk, kas atrodo gera tavo akyse.'),
  (@b10, 19, 28, 'Nes visi iš mano tėvo namų tebuvo mirę žmonės mano viešpaties karaliaus akivaizdoje; tačiau tu pasodinai savo tarną tarp valgančiųjų prie tavo stalo. Tai kokią dar turiu teisę verkti karaliui?“'),
  (@b10, 19, 29, 'Ir karalius jam tarė: „Ko dar kalbi apie savo reikalus? Aš sakiau: tu ir Ciba pasidalinkite žemę“.'),
  (@b10, 19, 30, 'Ir Mefibošetas tarė karaliui: „Taip, tegul jis viską pasiima, kadangi mano viešpats karalius yra sugrįžęs į savo namus ramybėje“.'),
  (@b10, 19, 31, 'Ir gileadietis Barzilajas atėjo žemyn iš Rogelimo ir su karaliumi perėjo Jordaną, kad jį palydėtų per Jordaną.'),
  (@b10, 19, 32, 'Na, o Barzilajas buvo labai senas žmogus, aštuoniasdešimties metų; ir jis buvo aprūpinęs maistu karalių, kai jis buvo Machanaime; nes jis buvo labai didis žmogus.'),
  (@b10, 19, 33, 'Ir karalius tarė Barzilajui: „Pereik su manimi, ir aš maitinsiu tave pas save Jeruzalėje“.'),
  (@b10, 19, 34, 'O Barzilajas tarė karaliui: „Kiek man beliko gyventi, kad eičiau su karaliumi aukštyn į Jeruzalę?'),
  (@b10, 19, 35, 'Šią dieną esu aštuoniasdešimties metų; ar aš galiu atskirti tarp gero ir blogo? Ar tavo tarnas gali pajusti skonį to, ką valgau ar ką geriu? Ar begaliu išgirsti dainuojančių vyrų ir dainuojančių moterų balsus? Tai kodėl tavo tarnas dar turėtų būti našta mano viešpačiui karaliui?'),
  (@b10, 19, 36, 'Tavo tarnas nueis su karaliumi trumpą kelią per Jordaną; ir kodėl karalius turėtų man atmokėti tokiu atlyginimu?'),
  (@b10, 19, 37, 'Meldžiu tave, leisk grįžti savo tarnui, kad galėčiau mirti savo mieste ir būčiau palaidotas šalia savo tėvo ir savo motinos kapo. Bet štai tavo tarnas Kimhamas; jis tegul pereina su mano viešpačiu karaliumi; ir jam daryk, kas tau atrodo gera“.'),
  (@b10, 19, 38, 'Ir karalius atsakė: „Kimhamas pereis su manimi, ir aš jam darysiu tai, kas tau atrodo gera; ir ko tik prašysi manęs, tai tau padarysiu“.'),
  (@b10, 19, 39, 'Ir visa tauta perėjo per Jordaną. Ir kai karalius buvo perėjęs, karalius pabučiavo Barzilają ir jį palaimino; o jis sugrįžo į savo vietą.'),
  (@b10, 19, 40, 'Paskui karalius ėjo toliau į Gilgalą, ir Kimhamas ėjo toliau su juo; ir visa Judos tauta bei pusė Izraelio tautos lydėjo karalių.'),
  (@b10, 19, 41, 'Ir štai visi Izraelio vyrai atėjo pas karalių ir sakė karaliui: „Kodėl mūsų broliai, Judos vyrai, pasivogė tave ir pervedė per Jordaną karalių, jo namiškius ir visus Dovydo vyrus su juo?“'),
  (@b10, 19, 42, 'Ir visi Judos vyrai atsakė Izraelio vyrams: „Todėl, kad karalius yra mums artimas giminaitis; tad kodėl pykstate dėl to dalyko? Ar mes iš viso valgėme iš karaliaus sąskaitos? Ar jis davė mums kokią dovaną?“'),
  (@b10, 19, 43, 'O Izraelio vyrai atsakė Judos vyrams, sakydami: „Mes turime dešimt dalių karaliuje, ir Dovyde taip pat turime daugiau teisių už jus; tai kodėl mus paniekinote, kad mūsų patarimas sugrąžinti mūsų karalių nebūtų pirmas?“ Bet Judos vyrų žodžiai buvo smarkesni už Izraelio vyrų žodžius.'),
  (@b10, 20, 1, 'Ir ten atsitiktinai buvo Belialo žmogus, kurio vardas buvo Šeba, Bichrio sūnus, benjaminas; ir jis papūtė ragą ir tarė: „Mes neturime dalies Dovyde ir neturime paveldo Jesės sūnuje; kiekvienas į savo palapines, o Izraeli“.'),
  (@b10, 20, 2, 'Taigi visi Izraelio žmonės, paliovę sekti paskui Dovydą, ėjo aukštyn, sekdami Bichrio sūnų Šebą; bet Judos žmonės prilipo prie savo karaliaus nuo Jordano iki Jeruzalės.'),
  (@b10, 20, 3, 'Ir Dovydas atėjo į savo namus Jeruzalėje; ir karalius, paėmęs dešimt moterų savo sugulovių, kurias jis buvo palikęs namų saugoti, patalpino jas į sargybos namus ir maitino jas, tačiau neįėjo pas jas. Taip jos buvo uždarytos iki savo mirties dienos, gyvendamos našlystėje.'),
  (@b10, 20, 4, 'Tada karalius tarė Amasai: „Surink man per tris dienas Judos žmones ir pats čia būk“.'),
  (@b10, 20, 5, 'Taigi Amasa ėjo Judos žmonių surinkti; bet jis užtruko ilgiau negu nustatytas laikas, kurį jis jam buvo paskyręs.'),
  (@b10, 20, 6, 'Ir Dovydas tarė Abišajui: „Dabar Bichrio sūnus Šeba padarys mums daugiau žalos negu Abšalomas; imk savo viešpaties tarnus ir vykis jį, kad jis nepasiektų aptvertų miestų ir nepabėgtų nuo mūsų.'),
  (@b10, 20, 7, 'Ir paskui jį išėjo Joabo vyrai, keretai, peletai ir visi galingi vyrai; ir jie išėjo iš Jeruzalės, kad vytųsi Bichrio sūnų Šebą.'),
  (@b10, 20, 8, 'Kai jie buvo prie didžiojo akmens, esančio Gibeone, Amasa ėjo priešais juos. Ir Joabo drabužis, kurį jis turėjo apsivilkęs, buvo ant jo apjuostas, o ant jo juosta su kalaviju, pritvirtintu prie juosmens savo makštyje; ir jam einant pirmyn, jis iškrito.'),
  (@b10, 20, 9, 'Ir Joabas tarė Amasai: „Ar tu sveikas, mano broli?“ Ir Joabas nutvėrė dešine ranka Amasą už barzdos, kad jį pabučiuotų.'),
  (@b10, 20, 10, 'Bet Amasa nepasisaugojo kalavijo, buvusio Joabo rankoje; taigi jis juo smeigė jam į penktąjį šonkaulį ir išleido jo vidurius ant žemės, ir nebedūrė jam antrą kartą; ir jis mirė. Taigi Joabas ir jo brolis Abišajas vijosi Bichrio sūnų Šebą.'),
  (@b10, 20, 11, 'Ir vienas iš Joabo vyrų stovėjo prie jo ir tarė: „Kas palankus Joabui ir kas už Dovydą, tegul seka Joabą“.'),
  (@b10, 20, 12, 'O Amasa skendėjo kraujyje vieškelio viduryje. Ir kai tas vyras pamatė, kad visa tauta sustojo, jis patraukė Amasą nuo vieškelio į lauką ir užmetė ant jo drabužį, matydamas, kad kiekvienas praeinantis pro jį sustojo.'),
  (@b10, 20, 13, 'Kai jis buvo pašalintas nuo vieškelio, visa liaudis ėjo toliau paskui Joabą, vytis Bichrio sūnaus Šebos.'),
  (@b10, 20, 14, 'Ir jis ėjo per visas Izraelio gentis iki Abelio ir iki Bet-Maakos, ir per visus beritus; ir jie susirinko ir taip pat ėjo paskui jį.'),
  (@b10, 20, 15, 'Ir jie atėję apgulė jį Bet-Maakos Abelyje, ir supylė pylimą prieš miestą, ir tas stovėjo apkasuose; ir visa su Joabu esanti liaudis daužė sieną, kad ją nugriautų.'),
  (@b10, 20, 16, 'Tada išmintinga moteris sušuko iš miesto: „Klausykite, klausykite; meldžiu jus, sakykite Joabui: ‘Prisiartink čia, kad kalbėčiau su tavimi’“.'),
  (@b10, 20, 17, 'Ir jam prisiartinus prie jos, ta moteris tarė: „Ar tu Joabas?“ Ir jis atsakė: „Aš“. Tada ji jam tarė: „Paklausyk savo tarnaitės žodžių“. Ir jis atsakė: „Aš klausau“.'),
  (@b10, 20, 18, 'Tada ji kalbėjo, sakydama: „Senovėje buvo įpratę kalbėti, sakydami: ‘Jie tikrai pasiklaus patarimo Abelyje; ir taip jie užbaigdavo reikalą’.'),
  (@b10, 20, 19, 'Aš esu viena iš taikingų ir ištikimų Izraelyje; tu sieki sunaikinti miestą ir motiną Izraelyje; kodėl nori praryti VIEŠPATIES paveldą?“'),
  (@b10, 20, 20, 'O Joabas atsakydamas tarė: „Tai tebūna toli, tai tebūna toli nuo manęs, kad praryčiau ar sunaikinčiau.'),
  (@b10, 20, 21, 'Čia ne toks reikalas; bet vyras iš Efraimo kalno, vardu Šeba, Bichrio sūnus, pakėlė ranką prieš karalių – prieš Dovydą; tik jį atiduokite, ir aš pasitrauksiu nuo miesto“. Ir moteris tarė Joabui: „Štai jo galva bus tau numesta per sieną“.'),
  (@b10, 20, 22, 'Tada ta moteris nuėjo pas visą tautą savo išmintimi. Ir jie nukirto Bichrio sūnaus Šebos galvą ir ją numetė Joabui. Ir jis papūtė trimitą, ir jie pasitraukė nuo miesto, kiekvienas į savo palapinę. Ir Joabas sugrįžo į Jeruzalę pas karalių.'),
  (@b10, 20, 23, 'Na, o Joabas vadovavo visai Izraelio kariuomenei; o Jehojados sūnus Benajas vadovavo keretams bei peletams;'),
  (@b10, 20, 24, 'Adoramas vadovavo duoklei; Ahiludo sūnus Jehozapatas buvo metraštininkas;'),
  (@b10, 20, 25, 'Ševa buvo raštininkas; Cadokas ir Abjataras buvo kunigai;'),
  (@b10, 20, 26, 'taip pat jayritas Ira buvo vyriausias valdovas pas Dovydą.'),
  (@b10, 21, 1, 'Po to Dovydo dienomis buvo badas trejus metus, metai po metų; ir Dovydas klausė VIEŠPATIES. Ir VIEŠPATS atsakė: „Tai dėl Sauliaus ir dėl jo kraugeriškų namų, nes jis žudė gibeoniečius“.'),
  (@b10, 21, 2, 'Ir karalius pašaukė gibeoniečius ir jiems tarė (na, o gibeoniečiai nebuvo iš Izraelio vaikų, bet iš amoritų likučio; ir Izraelio vaikai buvo jiems prisiekę; o Saulius iš savo uolumo Izraelio ir Judos vaikams, siekė juos išžudyti);'),
  (@b10, 21, 3, 'todėl Dovydas tarė gibeoniečiams: „Ką turiu jums padaryti, ir kuo galiu atlikti sutaikinimą, kad palaimintumėte VIEŠPATIES paveldą?“'),
  (@b10, 21, 4, 'Ir gibeoniečiai jam tarė: „Mums nereikia nei sidabro, nei aukso iš Sauliaus nei iš jo namų; ir dėl mūsų nieko nežudyk Izraelyje“. Ir jis tarė: „Ką pasakysite, tai padarysiu dėl jūsų“.'),
  (@b10, 21, 5, 'Ir jie atsakė karaliui: „Vyro, kuris mus ėdė ir kuris sumanė prieš mus, kad būtume išnaikinti, kad mūsų nebeliktų visose Izraelio ribose,'),
  (@b10, 21, 6, 'tebūna duoti mums septyni vyrai iš jo sūnų, ir mes pakarsime juos VIEŠPAČIUI Gibėjoje Sauliaus, kurį VIEŠPATS išsirinko“. Ir karalius tarė: „Aš juos duosiu“.'),
  (@b10, 21, 7, 'Bet karalius pagailėjo Sauliaus sūnaus Jonatano sūnaus Mefibošeto dėl VIEŠPATIES priesaikos, buvusios tarp jų, tarp Dovydo ir Sauliaus sūnaus Jonatano.'),
  (@b10, 21, 8, 'Bet karalius paėmė du Ajos dukters Ricpos sūnus, kuriuos ji pagimdė Sauliui, Armonį ir Mefibošetą; ir penkis Sauliaus dukters Mikalės sūnus, kuriuos ji pagimdė meholiečio Barzilajo sūnui Adrieliui;'),
  (@b10, 21, 9, 'ir jis juos atidavė į gibeoniečių rankas, ir jie juos pakorė ant kalvos VIEŠPATIES akivaizdoje; ir jie krito visi septyni drauge, ir buvo užmušti pjūties dienomis, pirmosiomis dienomis, miežių pjūties pradžioje.'),
  (@b10, 21, 10, 'Ir Ajos duktė Ricpa paėmusi ašutinę pasitiesė ją ant uolos nuo pjūties pradžios iki tol, kol pasipylė ant jų vanduo iš dangaus, ir neleido nei oro paukščiams nusileisti ant jų dieną, nei lauko žvėrims naktį.'),
  (@b10, 21, 11, 'Ir Dovydui buvo pranešta, ką padarė Ajos duktė Ricpa, Sauliaus sugulovė.'),
  (@b10, 21, 12, 'Ir Dovydas nuėjęs paėmė Sauliaus kaulus ir jo sūnaus Jonatano kaulus iš Jabeš-Gileado žmonių, kurie juos buvo pavogę iš Bet-Šano gatvės, kur filistinai juos buvo pakorę, kai filistinai užmušė Saulių Gilbojoje;'),
  (@b10, 21, 13, 'ir iš ten jis atgabeno aukštyn Sauliaus kaulus ir jo sūnaus Jonatano kaulus; ir jie surinko pakartųjų kaulus.'),
  (@b10, 21, 14, 'Ir jie palaidojo Sauliaus bei jo sūnaus Jonatano kaulus Benjamino šalyje, Celoje, jo tėvo Kišo kape; ir jie įvykdė viską, ką karalius įsakė. Ir po to Dievas išklausė maldavimus už šalį.'),
  (@b10, 21, 15, 'Be to, filistinai vėl kariavo prieš Izraelį; ir Dovydas nuėjo žemyn ir su juo jo tarnai, ir kovojo prieš filistinus; ir Dovydas nusilpo.'),
  (@b10, 21, 16, 'Ir Išbi-Benobas, kuris buvo iš milžinų sūnų, kurio ietis svėrė tris šimtus žalvario šekelių svorio, kuris buvo prisijuosęs nauju kalaviju, ketino užmušti Dovydą.'),
  (@b10, 21, 17, 'Bet Cerujos sūnus Abišajas jam pagelbėjo ir smogė filistinui, ir jį užmušė. Tada Dovydo vyrai jam prisiekė, sakydami: „Daugiau nebeisi su mumis į mūšį, kad neužgesintum Izraelio žiburio“.'),
  (@b10, 21, 18, 'Ir po to įvyko, kad vėl buvo mūšis su filistinais Gobe; tada hušatitas Sibechajas užmušė Safą, kuris buvo iš milžinų sūnų.'),
  (@b10, 21, 19, 'Ir vėl buvo mūšis su filistinais Gobe, kur betliejietis Jaare-Oregimo sūnus Elhananas užmušė gatiečio Galijoto brolį, kurio ieties kotas buvo kaip audėjų riestuvas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b10, 21, 20, 'Ir dar buvo mūšis Gate, kur buvo aukšto ūgio vyras, kuris turėjo ant kiekvienos rankos po šešis pirštus ir ant kiekvienos kojos po šešis pirštus, dvidešimt keturis skaičiumi; jis irgi buvo gimęs milžinui.'),
  (@b10, 21, 21, 'Ir kai jis metė iššūkį Izraeliui, jį užmušė Jonatanas, Dovydo brolio Šimio sūnus.'),
  (@b10, 21, 22, 'Šitie keturi buvo gimę milžinui Gate ir krito nuo Dovydo rankos bei jo tarnų rankų.'),
  (@b10, 22, 1, 'Ir Dovydas kalbėjo VIEŠPAČIUI šitos giesmės žodžius tą dieną, kai VIEŠPATS jį išgelbėjo iš visų jo priešų rankų ir iš Sauliaus rankų;'),
  (@b10, 22, 2, 'ir jis tarė: „VIEŠPATS yra mano uola, mano tvirtovė ir mano gelbėtojas;'),
  (@b10, 22, 3, 'mano uolos Dievas; juo pasitikėsiu; jis mano skydas ir mano išgelbėjimo ragas, mano aukštasis bokštas ir mano prieglobstis, mano gelbėtojas; tu mane gelbėji iš smurto.'),
  (@b10, 22, 4, 'Šauksiuosi VIEŠPATIES, kuris vertas, kad būtų giriamas; taip aš būsiu išgelbėtas nuo savo priešų.'),
  (@b10, 22, 5, 'Kai mane apsupo mirties bangos, bedievių upės išgąsdino mane;'),
  (@b10, 22, 6, 'pragaro kančios apsupo mane; mirties pinklės pasitiko mane;'),
  (@b10, 22, 7, 'savo sielvarte šaukiausi VIEŠPATIES ir savo Dievui šaukiau; ir jis išgirdo iš savo šventyklos mano balsą, ir mano šauksmas įėjo į jo ausis.'),
  (@b10, 22, 8, 'Tada kratėsi ir drebėjo žemė; dangaus pamatai judėjo ir kratėsi, nes jis užsirūstino.'),
  (@b10, 22, 9, 'Kilo dūmai iš jo šnervių, iš jo burnos rijo ugnis; nuo jos užsidegė anglys.'),
  (@b10, 22, 10, 'Jis taip pat palenkė dangus ir nužengė; ir tamsa buvo po jo kojomis.'),
  (@b10, 22, 11, 'Jis jojo ant kerubo ir skrido; ir jis matėsi ant vėjo sparnų.'),
  (@b10, 22, 12, 'Tamsą jis padarė palapinėmis aplink save, tamsius vandenis ir tirštus dangaus debesis.'),
  (@b10, 22, 13, 'Nuo spindesio jo priešakyje užsidegė ugnies anglys.'),
  (@b10, 22, 14, 'Iš dangaus sugriaudė VIEŠPATS, ir Aukščiausiasis ištarė savo balsą.'),
  (@b10, 22, 15, 'Jis išsiuntė strėles ir juos išsklaidė; žaibus, ir juos sutrikdė.'),
  (@b10, 22, 16, 'Pasirodė jūros vagos, atsidengė pasaulio pamatai nuo VIEŠPATIES barimo, nuo jo šnervių kvapo pūtimo.'),
  (@b10, 22, 17, 'Jis siuntė iš aukštybės, jis paėmė mane; jis ištraukė mane iš daugybės vandenų;'),
  (@b10, 22, 18, 'jis mane išgelbėjo iš mano stipraus priešo, iš tų, kurie nekentė manęs; nes jie buvo man per stiprūs.'),
  (@b10, 22, 19, 'Jie mane pasitiko mano nelaimės dieną; bet VIEŠPATS buvo mano atrama.'),
  (@b10, 22, 20, 'Jis mane išvedė ir į plačią vietą; jis išvadavo mane, nes gėrėjosi manimi.'),
  (@b10, 22, 21, 'VIEŠPATS man atlygino pagal mano teisumą; pagal mano rankų švarumą jis man atmokėjo.'),
  (@b10, 22, 22, 'Nes aš laikiausi VIEŠPATIES kelių ir nedorai neatsitraukiau nuo savo Dievo.'),
  (@b10, 22, 23, 'Nes visi jo teismai buvo mano priešakyje; ir nuo jo įstatų neatsitraukiau.'),
  (@b10, 22, 24, 'Taip pat buvau tiesus prieš jį ir saugojausi nuo savo neteisybės.'),
  (@b10, 22, 25, 'Todėl VIEŠPATS man atmokėjo pagal mano teisumą; pagal mano švarumą jo akyse.'),
  (@b10, 22, 26, 'Gailestingam tu pasirodai gailestingas, tiesiam tu pasirodai tiesus.'),
  (@b10, 22, 27, 'Tyram tu pasirodai tyras; o priešgyniam tu pasirodai nemalonus.'),
  (@b10, 22, 28, 'Tu išgelbėsi suspaustuosius; bet tavo akys nukreiptos prieš išdidžiuosius, kad juos pažemintum.'),
  (@b10, 22, 29, 'Nes tu esi mano žiburys, o VIEŠPATIE; ir VIEŠPATS nušvies mano tamsą.'),
  (@b10, 22, 30, 'Nes su tavimi aš bėgau per pulką; su savo Dievu aš peršokau per sieną.'),
  (@b10, 22, 31, 'O Dievas, jo kelias yra tobulas; VIEŠPATIES žodis yra išbandytas; jis yra skydas visiems, kurie juo pasitiki.'),
  (@b10, 22, 32, 'Nes kas yra Dievas, jei ne VIEŠPATS? Ir kas yra uola, jei ne mūsų Dievas?'),
  (@b10, 22, 33, 'Dievas yra mano stiprybė ir jėga; ir jis padaro mano kelią tobulą.'),
  (@b10, 22, 34, 'Jis padaro mano kojas kaip stirnos; ir mane pastato ant mano aukštumų.'),
  (@b10, 22, 35, 'Jis moko mano rankas kariauti; taip, kad plieninis lankas yra sulaužomas mano rankomis.'),
  (@b10, 22, 36, 'Taip pat man davei ir savo išgelbėjimo skydą; ir tavo gerumas padarė mane didį.'),
  (@b10, 22, 37, 'Tu praplatinai mano žingsnius po manimi; kad mano kojos nepaslystų.'),
  (@b10, 22, 38, 'Aš vijausi savo priešus ir juos sunaikinau; ir nepasukau atgal, kol nebuvau jų išnaikinęs.'),
  (@b10, 22, 39, 'Aš juos sunaikinau ir sužeidžiau, kad jie nebegalėjo atsikelti; taip, jie krito po mano kojomis.'),
  (@b10, 22, 40, 'Nes tu apjuosei mane jėga mūšiui; pavergei po manimi tuos, kurie sukilo prieš mane.'),
  (@b10, 22, 41, 'Taip pat man davei mano priešų sprandus, kad sunaikinčiau tuos, kurie nekenčia manęs.'),
  (@b10, 22, 42, 'Jie ieškojo, tačiau nebuvo nei vieno, kad išgelbėtų, tai yra VIEŠPATIES, bet jis neatsiliepė jiems.'),
  (@b10, 22, 43, 'Tada juos sutryniau smulkiai kaip žemės dulkes, kaip gatvės purvą juos sutrypiau, ir juos išsklaidžiau.'),
  (@b10, 22, 44, 'Taip pat tu išvadavai mane iš mano tautos vaidijimųsi, tu išsaugojai mane, kad būčiau pagonių galva; tauta, kurios nepažinau, man tarnaus.'),
  (@b10, 22, 45, 'Svetimšaliai man pasiduos; kai tik jie išgirs, jie paklus man.'),
  (@b10, 22, 46, 'Svetimšaliai išblykš, ir jie bijos iš savo slaptų vietų.'),
  (@b10, 22, 47, 'VIEŠPATS gyvas; tebūna palaiminta mano uola; tebūna išaukštintas mano išgelbėjimo uolos Dievas.'),
  (@b10, 22, 48, 'Tai Dievas, kuris atkeršija už mane ir kuris pargriauna po manimi tautas,'),
  (@b10, 22, 49, 'kuris mane išveda iš mano priešų; tu taip pat iškėlei mane aukščiau tų, kurie sukilo prieš mane; tu mane išvadavai iš smurtininko.'),
  (@b10, 22, 50, 'Todėl aš dėkosiu tau, o VIEŠPATIE, tarp pagonių ir giedosiu gyrių tavo vardui.'),
  (@b10, 22, 51, 'Jis yra išgelbėjimo bokštas savo karaliui; ir parodo gailestingumą savo pateptajam – Dovydui ir jo sėklai per amžius“.'),
  (@b10, 23, 1, 'Na, o šitie yra paskutiniai Dovydo žodžiai: „Sakė Dovydas, Jesės sūnus, vyras, kuris buvo aukštai iškeltas, Jokūbo Dievo pateptasis, mielas Izraelio psalmininkas tarė:'),
  (@b10, 23, 2, 'VIEŠPATIES Dvasia kalbėjo per mane, ir jo žodis buvo ant mano liežuvio.'),
  (@b10, 23, 3, 'Pasakė Izraelio Dievas, man kalbėjo Izraelio Uola: ‘Kas valdo žmones, turi būti teisingas, valdantis Dievo baimėje.'),
  (@b10, 23, 4, 'Ir jis bus kaip ryto šviesa saulei tekant, tai yra, rytas be debesų; kaip gležna žolė, dygstanti iš žemės nuo šviesaus švytėjimo po lietaus.'),
  (@b10, 23, 5, 'Nors mano namai ir nėra tokie su Dievu; tačiau jis su manimi sudarė amžiną sandorą, visais dalykais sutvarkytą ir užtikrintą; nes tai yra visas mano išgelbėjimas ir visas mano troškimas, nors jis ir neleidžia jam augti.'),
  (@b10, 23, 6, 'Bet Belialo sūnūs visi bus kaip atmesti erškėčiai, nes jų negalima paimti rankomis;'),
  (@b10, 23, 7, 'bet kas juos liečia, turi būti apsitvėręs geležimi ir ieties kotu; ir jie bus visiškai sudeginti ugnimi toje pačioje vietoje“.'),
  (@b10, 23, 8, 'Šitie yra vardai galingų vyrų, kuriuos turėjo Dovydas: tachmonitas, kuris sėdėjo krasėje, vyriausias tarp vadų; tas buvo ecenitas Adinas: jis pakėlė savo ietį prieš aštuonis šimtus, kuriuos nužudė vienu metu.'),
  (@b10, 23, 9, 'O po jo buvo Dodo sūnus Eleazaras, ahohitas, vienas iš trijų galingų vyrų su Dovydu, kai jie metė iššūkį filistinams, ten susirinkusiems mūšiui, o Izraelio vyrai buvo atsitraukę;'),
  (@b10, 23, 10, 'jis pakilo ir mušė filistinus, kol pavargo jo ranka, ir jo ranka prilipo prie kalavijo; ir VIEŠPATS tą dieną įvykdė didelę pergalę; o tauta grįžo jam iš paskos vien tik grobti.'),
  (@b10, 23, 11, 'O po jo buvo hararito Agės sūnus Šama. Filistinai buvo susirinkę į pulką, kur buvo žemės sklypas, pilnas lęšių; ir tauta pabėgo nuo filistinų.'),
  (@b10, 23, 12, 'Bet jis stovėjo žemės viduryje ir ją gynė, ir žudė filistinus; ir VIEŠPATS įvykdė didelę pergalę.'),
  (@b10, 23, 13, 'Ir nusileido trys iš trisdešimties vyriausiųjų, ir atėjo pjūties metu pas Dovydą į Adulamo olą; o filistinų pulkas stovyklavo Refaimo slėnyje.'),
  (@b10, 23, 14, 'Dovydas tada buvo tvirtovėje, o filistinų įgula tada buvo Betliejuje.'),
  (@b10, 23, 15, 'Ir Dovydas ilgėjosi ir tarė: „Ak, kad kas man duotų atsigerti vandens iš Betliejaus šulinio, esančio prie vartų!“'),
  (@b10, 23, 16, 'Ir tie trys galingi vyrai prasilaužė pro filistinų kariuomenę, pasėmė vandens iš Betliejaus šulinio, esančio prie vartų, ir paėmę atnešė jo Dovydui; tačiau jis nenorėjo jo gerti, bet išliejo jį VIEŠPAČIUI.'),
  (@b10, 23, 17, 'Ir jis tarė: „Tebūna tai toli nuo manęs, o VIEŠPATIE, kad tai daryčiau; argi tai ne kraujas tų vyrų, kurie nuėjo, statydami pavojun savo gyvybes?“ Todėl jis nenorėjo jo gerti. Šituos dalykus padarė tie trys galiūnai.'),
  (@b10, 23, 18, 'O Joabo brolis Abišajas, Cerujos sūnus, buvo vyriausias tarp trijų. Ir jis pakėlė savo ietį prieš tris šimtus, nužudė juos ir pagarsėjo tarp trijų.'),
  (@b10, 23, 19, 'Argi jis nebuvo labiausiai gerbiamas iš trijų? Todėl jis buvo jų vadas; tačiau jis neprilygo pirmiems trims.'),
  (@b10, 23, 20, 'Ir Jehojados sūnus Benajas, narsaus vyro sūnus iš Kabceelio, nuveikęs daug darbų, jis užmušė du Moabo vyrus kaip liūtus; taip pat sniego metu jis nulipo žemyn ir užmušė liūtą duobės viduryje.'),
  (@b10, 23, 21, 'Ir jis užmušė egiptietį, išvaizdų vyrą; egiptietis turėjo rankoje ietį; bet jis nuėjo žemyn pas jį su lazda, išplėšė ietį iš egiptiečio rankos ir nužudė jį jo paties ietimi.'),
  (@b10, 23, 22, 'Šituos dalykus padarė Jehojados sūnus Benajas ir pagarsėjo tarp trijų galiūnų.'),
  (@b10, 23, 23, 'Jis buvo labiau gerbiamas negu trisdešimt, bet jis neprilygo pirmiems trims. Ir Dovydas jį paskyrė savo sargybai vadovauti.'),
  (@b10, 23, 24, 'Vienas iš trisdešimties buvo Joabo brolis Asaelis; Dodo sūnus Elhananas iš Betliejaus,'),
  (@b10, 23, 25, 'harodietis Šama, harodietis Elika,'),
  (@b10, 23, 26, 'paltietis Helecas, tekojiečio Ikešo sūnus Ira,'),
  (@b10, 23, 27, 'anatotietis Abiezeras, hušietis Mebunajas,'),
  (@b10, 23, 28, 'ahohitas Calmonas, netofietis Mahrajas,'),
  (@b10, 23, 29, 'netofietis Helebas, Baano sūnus, Ribajo sūnus Itajas iš Benjamino vaikų Gibėjos,'),
  (@b10, 23, 30, 'piratonietis Benajas, Hidajas iš Gaašo upelių,'),
  (@b10, 23, 31, 'arbatitas Abi-Albonas, barhumitas Azmavetas,'),
  (@b10, 23, 32, 'šaalbonietis Eljachba, iš Jašeno sūnų, Jonatanas,'),
  (@b10, 23, 33, 'hararitas Šama, hararito Šararo sūnus Ahiamas,'),
  (@b10, 23, 34, 'Ahasbajo sūnus Elifeletas, maako sūnus; giloniečio Ahitofelio sūnus Eliamas,'),
  (@b10, 23, 35, 'karmelietis Hecrajas, arbitas Paarajas,'),
  (@b10, 23, 36, 'Igalas – sūnus Natano iš Cobos, gadas Banis,'),
  (@b10, 23, 37, 'amonietis Celekas, beerotietis Nacharajas, Cerujos sūnaus Joabo ginklanešys;'),
  (@b10, 23, 38, 'itritas Ira, itritas Garebas,'),
  (@b10, 23, 39, 'hetitas Ūrija – iš viso trisdešimt septyni.'),
  (@b10, 24, 1, 'Ir VIEŠPATIES pyktis vėl užsidegė prieš Izraelį, ir jis paskatino Dovydą prieš juos, kad sakytų: „Eik, suskaičiuok Izraelį ir Judą“.'),
  (@b10, 24, 2, 'Nes karalius tarė Joabui, kariuomenės vadui, esančiam su juo: „Eik dabar per visas Izraelio gentis nuo Dano iki Beer-Šebos ir suskaičiuokite tautą, kad žinočiau tautos skaičių“.'),
  (@b10, 24, 3, 'Ir Joabas tarė karaliui: „VIEŠPATS, tavo Dievas, tepridės prie tautos šimtąkart tiek, kiek jų yra, kad mano viešpaties karaliaus akys tai matytų; bet kodėl mano viešpats karalius gėrisi šiuo dalyku?“'),
  (@b10, 24, 4, 'Tačiau karaliaus žodis nugalėjo Joabą ir kariuomenės vadus. Ir Joabas bei kariuomenės vadai išėjo nuo karaliaus akivaizdos Izraelio tautos suskaičiuoti.'),
  (@b10, 24, 5, 'Ir perėję per Jordaną, jie stovyklavo Aroeryje, dešinėje pusėje miesto, esančio Gado upės viduryje, ir Jazerio link;'),
  (@b10, 24, 6, 'paskui jie atėjo į Gileadą ir į Tachtim-Hodši šalį; ir jie atėjo į Dan-Jaaną ir aplink į Sidoną,'),
  (@b10, 24, 7, 'ir atėjo į Tyro tvirtovę ir į visus hivų bei kanaaniečių miestus; ir jie išėjo į Judos pietus – į Beer-Šebą.'),
  (@b10, 24, 8, 'Taigi kai jie buvo perėję visą šalį, devyniems mėnesiams ir dvidešimčiai dienų pasibaigus, jie atvyko į Jeruzalę.'),
  (@b10, 24, 9, 'Ir Joabas davė karaliui tautos skaičiaus sumą: ir Izraelyje buvo aštuoni šimtai tūkstančių narsių vyrų, traukiančių kalaviją; o Judos vyrų buvo penki šimtai tūkstančių vyrų.'),
  (@b10, 24, 10, 'Ir Dovydo širdis jį ištiko po to, kai jis buvo skaičiavęs tautą. Ir Dovydas tarė VIEŠPAČIUI: „Aš labai nusidėjau tuo, ką padariau; o dabar, o VIEŠPATIE, meldžiu tave, pašalink savo tarno neteisybę; nes labai kvailai padariau“.'),
  (@b10, 24, 11, 'Dovydui ryte atsikėlus, VIEŠPATIES žodis atėjo pranašui Gadui, Dovydo regėtojui, sakydamas:'),
  (@b10, 24, 12, '„Eik ir kalbėk Dovydui: ‘Taip sako VIEŠPATS: Aš tau siūlau tris dalykus; pasirink vieną iš jų, kad tau tai daryčiau’“.'),
  (@b10, 24, 13, 'Taigi Gadas atėjo pas Dovydą, jam pasakė ir tarė: „Ar teateina tau septyni bado metai į tavo šalį, ar nori tris mėnesius bėgti savo priešų priešakyje, kol jie tave persekios, ar kad tris dienas maras būtų tavo šalyje? Dabar pasitark ir pagalvok, kokį atsakymą turiu parnešti tam, kuris mane siuntė“.'),
  (@b10, 24, 14, 'Ir Dovydas tarė Gadui: „Esu labai spaudžiamas; pulkime į VIEŠPATIES rankas; nes dideli jo gailestingumai; tenepulsiu į žmogaus rankas“.'),
  (@b10, 24, 15, 'Taigi VIEŠPATS siuntė ant Izraelio marą nuo ryto iki nustatyto laiko; ir išmirė iš tautos nuo Dano iki Beer-Šebos septyniasdešimt tūkstančių žmonių.'),
  (@b10, 24, 16, 'Ir kai angelas ištiesė ranką į Jeruzalę jos naikinti, VIEŠPATS gailėjosi dėl nelaimės ir tarė angelui, naikinančiam tautą: „Gana; sulaikyk dabar savo ranką“. O VIEŠPATIES angelas buvo prie jebusiečio Araunos klojimo.'),
  (@b10, 24, 17, 'Ir pamatęs angelą, užmušinėjantį tautą, Dovydas kalbėjo VIEŠPAČIUI, sakydamas: „Štai aš nusidėjau ir nedorai pasielgiau; bet šitos avys, ką jos padarė? Meldžiu tave, tegul tavo ranka būna prieš mane ir prieš mano tėvo namus“.'),
  (@b10, 24, 18, 'Ir tą dieną Gadas atėjo pas Dovydą ir tarė jam: „Eik aukštyn, pastatyk VIEŠPAČIUI aukurą jebusiečio Araunos klojime“.'),
  (@b10, 24, 19, 'Ir Dovydas pagal Gado pasakymą ėjo aukštyn, kaip VIEŠPATS įsakė.'),
  (@b10, 24, 20, 'Ir Arauna pažiūrėjo ir pamatė karalių ir jo tarnus, ateinančius jo link; ir Arauna išėjo ir nusilenkė prieš karalių veidu iki žemės.'),
  (@b10, 24, 21, 'Ir Arauna tarė: „Kodėl mano viešpats karalius atėjo pas savo tarną?“ O Dovydas tarė: „Pirkti iš tavęs klojimo, kad VIEŠPAČIUI aukurą pastatyčiau, kad ta rykštė būtų sulaikyta nuo tautos“.'),
  (@b10, 24, 22, 'Ir Arauna tarė Dovydui: „Tegul mano viešpats karalius ima ir atnašauja, kas jam atrodo gera; štai čia yra jaučiai deginamajai aukai, kuliamieji įrankiai ir kiti jaučių įrankiai malkoms.'),
  (@b10, 24, 23, 'Visa tai Arauna, kaip karalius, davė karaliui. Ir Arauna tarė karaliui: „VIEŠPATS, tavo Dievas, tave tepriima“.'),
  (@b10, 24, 24, 'O karalius tarė Araunai: „Ne; aš tikrai pirksiu tai iš tavęs už kainą; aš neaukosiu VIEŠPAČIUI, savo Dievui, deginamųjų atnašų iš to, kas man nieko nekainuoja“. Taip Dovydas nupirko klojimą ir jaučius už penkiasdešimt sidabro šekelių.'),
  (@b10, 24, 25, 'Ir Dovydas ten pastatė aukurą VIEŠPAČIUI ir atnašavo deginamąsias atnašas ir taikos atnašas. Taip VIEŠPATS buvo permaldautas už šalį, ir rykštė buvo sulaikyta nuo Izraelio.'),
  (@b11, 1, 1, 'Na, o karalius Dovydas buvo pasenęs, metų pakirstas; ir jie apklodavo jį drobėmis, bet jis nebesušildavo.'),
  (@b11, 1, 2, 'Todėl jo tarnai jam tarė: „Tepaieško mano viešpačiui karaliui jauną mergelę; ir ji testovi karaliaus akivaizdoje, tegul ji prižiūri jį ir teguli ji tavo glėbyje, kad mano viešpats karalius sušiltų“.'),
  (@b11, 1, 3, 'Taigi jie ieškojo gražios panelės visose Izraelio ribose ir, suradę šunamietę Abišagą, atvedė ją pas karalių.'),
  (@b11, 1, 4, 'O ta panelė buvo labai graži ir prižiūrėjo karalių, ir jam patarnavo; bet karalius jos nepažino.'),
  (@b11, 1, 5, 'Tada Hagitos sūnus Adonijas išaukštino save, sakydamas: „Aš būsiu karalius“; ir jis pasiruošė vežimų bei raitelių ir penkiasdešimt vyrų, kad bėgtų pirma jo.'),
  (@b11, 1, 6, 'O jo tėvas niekada nesukėlė jam nepasitenkinimo, sakydamas: „Kodėl taip padarei?“ Jis irgi buvo labai gražus vyras; ir jo motina pagimdė jį po Abšalomo.'),
  (@b11, 1, 7, 'Ir jis susitarė su Cerujos sūnumi Joabu ir su kunigu Abjataru; o jie, sekdami Adoniją, jam padėjo.'),
  (@b11, 1, 8, 'Bet kunigas Cadokas, Jehojados sūnus Benajas, pranašas Natanas, Šimis, Rėjas ir galingi vyrai, priklausantys Dovydui, nebuvo su Adoniju.'),
  (@b11, 1, 9, 'Ir Adonijas papjovė avis, jaučius ir riebius galvijus prie Cokeleto akmens, esančio šalia En-Rogelio, ir pakvietė visus savo brolius, karaliaus sūnus, ir visus Judos vyrus, karaliaus tarnus;'),
  (@b11, 1, 10, 'bet pranašo Natano, Benajo, galingųjų vyrų ir savo brolio Saliamono jis nepakvietė.'),
  (@b11, 1, 11, 'Todėl Natanas tarė Saliamono motinai Bat-Šebai, sakydamas: „Ar negirdėjai, kad Hagitos sūnus Adonijas karaliauja, o mūsų viešpats Dovydas to nežino?'),
  (@b11, 1, 12, 'Taigi dabar eikš, leisk man, meldžiu tave, tau duoti patarimą, kad išgelbėtum savo gyvybę ir savo sūnaus Saliamono gyvybę.'),
  (@b11, 1, 13, 'Eik ir, įėjusi pas karalių Dovydą, jam sakyk: ‘Argi tu, mano viešpatie, o karaliau, neprisiekei savo tarnaitei, sakydamas: „Tikrai tavo sūnus Saliamonas karaliaus po manęs, ir jis sėdės mano soste?“ Tai kodėl Adonijas karaliauja?’'),
  (@b11, 1, 14, 'Štai tau ten tebekalbant su karaliumi, aš irgi įeisiu paskui tave ir patvirtinsiu tavo žodžius“.'),
  (@b11, 1, 15, 'Ir Bat-Šeba įėjo pas karalių į kambarį; o karalius buvo labai senas; ir šunamietė Abišaga tarnavo karaliui.'),
  (@b11, 1, 16, 'Ir Bat-Šeba nusilenkė ir išreiškė pagarbą karaliui. Ir karalius tarė: „Ko nori?“'),
  (@b11, 1, 17, 'O ji jam tarė: „Mano viešpatie, tu prisiekei VIEŠPAČIU, savo Dievu, savo tarnaitei, sakydamas: ‘Tikrai tavo sūnus Saliamonas karaliaus po manęs, ir jis sėdės mano soste.'),
  (@b11, 1, 18, 'O dabar, štai Adonijas karaliauja; na, o tu, mano viešpatie karaliau, to nežinai;'),
  (@b11, 1, 19, 'ir jis papjovė daugybę jaučių, nupenėtų galvijų bei avių ir pakvietė visus karaliaus sūnus, kunigą Abjatarą ir kariuomenės vadą Joabą; bet tavo tarno Saliamono jis nepakvietė.'),
  (@b11, 1, 20, 'O tu, mano viešpatie, o karaliau, į tave yra nukreiptos viso Izraelio akys, kad jiems paskelbtum, kas turės sėdėti mano viešpaties karaliaus soste po jo.'),
  (@b11, 1, 21, 'Kitaip atsitiks, kai mano viešpats karalius užmigs prie savo tėvų, tada aš ir mano sūnus Saliamonas būsime laikomi nusikaltėliais“.'),
  (@b11, 1, 22, 'Ir štai jai tebekalbant su karaliumi, atėjo ir pranašas Natanas.'),
  (@b11, 1, 23, 'Ir pranešė karaliui, sakydami: „Štai pranašas Natanas“. Ir atėjęs karaliaus akivaizdon jis nusilenkė prieš karalių veidu iki žemės.'),
  (@b11, 1, 24, 'Ir Natanas tarė: „Mano viešpatie, o karaliau, ar tu sakei: ‘Adonijas karaliaus po manęs, ir sėdės mano soste?’'),
  (@b11, 1, 25, 'Nes jis šią dieną nuėjo žemyn, papjovė daugybę jaučių, nupenėtų galvijų bei avių ir pasikvietė visus karaliaus sūnus, kariuomenės vadus ir kunigą Abjatarą; ir štai jie valgo ir geria jo akivaizdoje, ir sako: ‘Tegyvuoja karalius Adonijas’.'),
  (@b11, 1, 26, 'Bet manęs, būtent manęs, tavo tarno, kunigo Cadoko, Jehojados sūnaus Benajo ir tavo tarno Saliamono jis nepakvietė.'),
  (@b11, 1, 27, 'Ar šitas dalykas padarytas mano viešpaties karaliaus, o tu nepranešei to savo tarnui, kas turės sėdėti mano viešpaties karaliaus soste po jo?“'),
  (@b11, 1, 28, 'Tada karalius Dovydas atsakydamas tarė: „Pašaukite man Bat-Šebą“. Ir ji, atėjusi karaliaus akivaizdon, atsistojo prieš karalių.'),
  (@b11, 1, 29, 'Ir karalius prisiekdamas tarė: „Kaip gyvas VIEŠPATS, kuris atpirko mano sielą iš visokių bėdų,'),
  (@b11, 1, 30, 'kaip aš tau prisiekiau VIEŠPAČIU, Izraelio Dievu, tardamas: ‘Tikrai tavo sūnus Saliamonas karaliaus po manęs, ir jis sėdės mano soste mano vietoje’; būtent taip aš šią dieną tikrai padarysiu“.'),
  (@b11, 1, 31, 'Tada Bat-Šeba, nusilenkusi veidu iki žemės ir išreiškusi karaliui pagarbą, tarė: „Tegyvuoja mano viešpats karalius Dovydas per amžius“.'),
  (@b11, 1, 32, 'Ir karalius Dovydas tarė: „Pašaukite man kunigą Cadoką, pranašą Nataną ir Jehojados sūnų Benają“. Ir jie atėjo karaliaus akivaizdon.'),
  (@b11, 1, 33, 'Ir karalius jiems tarė: „Imkite su savimi savo viešpaties tarnus, užsodinkite mano sūnų Saliamoną ant mano paties mulo ir nuveskite jį žemyn į Gihoną;'),
  (@b11, 1, 34, 'ir tegul kunigas Cadokas ir pranašas Natanas jį ten patepa Izraelio karaliumi; ir pūskite trimitu ir sakykite: ‘Tegyvuoja karalius Saliamonas’.'),
  (@b11, 1, 35, 'Tada ateikite aukštyn paskui jį, kad jis ateitų ir atsisėstų į mano sostą; nes jis bus karalius mano vietoje; aš jį paskyriau būti valdovu Izraeliui ir Judai“.'),
  (@b11, 1, 36, 'Ir Jehojados sūnus Benajas atsakydamas karaliui tarė: „Amen; taip tesako VIEŠPATS, mano viešpaties karaliaus Dievas.'),
  (@b11, 1, 37, 'Kaip VIEŠPATS buvo su mano viešpačiu karaliumi, taip jis tebūna su Saliamonu ir tepadaro jo sostą didesnį už mano viešpaties karaliaus Dovydo sostą“.'),
  (@b11, 1, 38, 'Taigi kunigas Cadokas, pranašas Natanas, Jehojados sūnus Benajas, keretai ir peletai nuėjo žemyn, užsodino Saliamoną ant karaliaus Dovydo mulo ir jį nuvedė į Gihoną.'),
  (@b11, 1, 39, 'Ir kunigas Cadokas paėmė ragą aliejaus iš padangtės ir patepė Saliamoną. Ir jie pūtė trimitą; o visa tauta tarė: „Tegyvuoja karalius Saliamonas“.'),
  (@b11, 1, 40, 'Ir visa tauta atėjo aukštyn paskui jį, ir grodama dūdelėmis tauta džiaugėsi dideliu džiaugsmu, kad net žemė plyšinėjo nuo jų garso.'),
  (@b11, 1, 41, 'Ir tai išgirdo Adonijas ir visi su juo esantys svečiai, kai jie buvo baigę valgyti. O Joabas, išgirdęs trimito garsą, tarė: „Kodėl šis šurmuliuojančio miesto triukšmas?“'),
  (@b11, 1, 42, 'Ir jam tebekalbant štai atėjo kunigo Abjataro sūnus Jonatanas; ir Adonijas jam tarė: „Įeik; nes tu esi narsus vyras ir atneši gerą žinią“.'),
  (@b11, 1, 43, 'Ir Jonatanas atsakydamas tarė Adonijui: „Tikrai mūsų viešpats, karalius Dovydas, paskyrė karaliumi Saliamoną.'),
  (@b11, 1, 44, 'Ir karalius siuntė su juo kunigą Cadoką, pranašą Nataną, Jehojados sūnų Benają, keretus bei peletus, ir jie užsodino jį ant karaliaus mulo;'),
  (@b11, 1, 45, 'ir kunigas Cadokas bei pranašas Natanas jį patepė karaliumi Gihone; ir iš ten jie atėjo aukštyn džiaugdamiesi, kad net miestas aidėjo. Tai yra tas triukšmas, kurį girdėjote.'),
  (@b11, 1, 46, 'Be to, Saliamonas sėdi karalystės soste.'),
  (@b11, 1, 47, 'Ir dar karaliaus tarnai atėjo palaiminti mūsų viešpaties karaliaus Dovydo, sakydami: ‘Tegul Dievas padaro Saliamono vardą geresnį už tavo vardą, ir jo sostą tepadaro didesnį už tavo sostą’. Ir karalius nusilenkė lovoje.'),
  (@b11, 1, 48, 'Ir karalius taipogi šitaip tarė: ‘Tebūna palaimintas VIEŠPATS, Izraelio Dievas, kuris, mano akims matant, šią dieną davė tą, kuris sėdės mano soste’“.'),
  (@b11, 1, 49, 'Ir visi pas Adoniją esantys svečiai išsigando ir pakilę nuėjo kiekvienas savo keliu.'),
  (@b11, 1, 50, 'O Adonijas bijojo dėl Saliamono ir pakilęs nuėjo ir nusitvėrė už aukuro ragų.'),
  (@b11, 1, 51, 'Ir buvo pranešta Saliamonui, sakant: „Štai Adonijas bijo karaliaus Saliamono; nes štai jis nusitvėręs laikosi aukuro ragų, sakydamas: ‘Tegul karalius Saliamonas šiandien man prisiekia, kad nenužudys savo tarno kalaviju“.'),
  (@b11, 1, 52, 'Ir Saliamonas tarė: „Jei jis pasirodys vertas vyras, nenukris žemėn nei vienas jo plaukas; bet jei jame bus rasta nedorybė, jis mirs“.'),
  (@b11, 1, 53, 'Taigi karalius Saliamonas pasiuntė, ir jie nuvedė jį žemyn nuo aukuro. Ir jis atėjęs nusilenkė karaliui Saliamonui; ir Saliamonas jam tarė: „Eik į savo namus“.'),
  (@b11, 2, 1, 'Na, o artėjo Dovydo dienos, kad jis turėjo mirti; ir jis įpareigojo savo sūnų Saliamoną, sakydamas:'),
  (@b11, 2, 2, '„Aš einu visos žemės keliu; taigi būk stiprus ir būk vyriškas;'),
  (@b11, 2, 3, 'ir laikykis VIEŠPATIES, savo Dievo, įpareigojimo, kad vaikščiotum jo keliais, kad laikytumeisi jo įstatų, jo įsakymų, jo teismų ir jo liudijimų, kaip yra parašyta Mozės įstatyme, kad tau sektųsi visame, ką darysi, ir visur, kur pasisuksi;'),
  (@b11, 2, 4, 'kad VIEŠPATS ištesėtų savo žodį, kurį jis kalbėjo apie mane, sakydamas: ‘Jei tavo vaikai žiūrės savo kelio, kad vaikščiotų mano akivaizdoje tiesoje visa savo širdimi ir visa savo siela, tai tau niekada (jis tarė) nepristigs vyro Izraelio soste’.'),
  (@b11, 2, 5, 'Be to, tu žinai, ką man padarė Cerujos sūnus Joabas ir ką jis padarė dviems Izraelio kariuomenių vadams, Nero sūnui Abnerui ir Jetero sūnui Amasai, kuriuos jis nužudė ir išliejo karo kraują taikos metu ir uždėjo karo kraujo ant savo juostos, esančios aplink jo strėnas, ir ant savo apavo, esančio ant jo kojų.'),
  (@b11, 2, 6, 'Todėl padaryk pagal savo išmintį ir neleisk jo žilai galvai nužengti į kapą ramybėje.'),
  (@b11, 2, 7, 'Bet gileadiečio Barzilajo sūnums parodyk gerumą, ir jie tebūna tarp valgančiųjų prie tavo stalo; nes taip jie atėjo pas mane, kai aš bėgau dėl tavo brolio Abšalomo.'),
  (@b11, 2, 8, 'Ir štai pas tave yra Gero sūnus Šimis, benjaminas iš Bahurimo, kuris mane keikė smarkiu keiksmu tą dieną, kai vykau į Mahanaimą; bet jis atėjo žemyn manęs pasitikti prie Jordano, ir aš jam prisiekiau VIEŠPAČIU, sakydamas: ‘Aš tavęs nenužudysiu kalaviju’.'),
  (@b11, 2, 9, 'Taigi dabar nelaikyk jo nekaltu; nes tu esi išmintingas vyras ir žinai, ką turi jam padaryti: nuleisk jo žilą galvą į kapą su krauju“.'),
  (@b11, 2, 10, 'Taigi Dovydas užmigo prie savo tėvų ir buvo palaidotas Dovydo mieste.'),
  (@b11, 2, 11, 'O dienų, kurias Dovydas karaliavo Izraeliui, buvo keturiasdešimt metų; septynerius metus jis karaliavo Hebrone, o trisdešimt trejus metus karaliavo Jeruzalėje.'),
  (@b11, 2, 12, 'Tada Saliamonas atsisėdo į savo tėvo Dovydo sostą; ir jo karalystė buvo labai sutvirtinta.'),
  (@b11, 2, 13, 'Ir Hagitos sūnus Adonijas atėjo pas Saliamono motiną Bat-Šebą. Ir ji tarė: „Ar ateini taikingai?“ Ir jis tarė: „Taikingai“.'),
  (@b11, 2, 14, 'Jis dar tarė: „Turiu tau kai ką pasakyti“. Ir ji tarė: „Sakyk“.'),
  (@b11, 2, 15, 'Ir jis tarė: „Tu žinai, kad karalystė buvo mano ir kad visas Izraelis nukreipė savo veidus į mane, idant aš karaliaučiau; tačiau karalystė apsigręžė ir tapo mano brolio; nes ji buvo jo nuo VIEŠPATIES.'),
  (@b11, 2, 16, 'O dabar turiu tau vieną prašymą, neatmesk manęs“. Ir ji tarė jam: „Kalbėk“.'),
  (@b11, 2, 17, 'Ir jis tarė: „Kalbėk, meldžiu tave, karaliui Saliamonui (nes jis tau neatsakys), kad jis man duotų šunamietę Abišagą į žmonas“.'),
  (@b11, 2, 18, 'Ir Bat-Šeba tarė: „Gerai; aš kalbėsiu už tave karaliui“.'),
  (@b11, 2, 19, 'Taigi Bat-Šeba atėjo pas karalių Saliamoną, kad jam kalbėtų už Adoniją. Ir karalius atsistojo jos pasitikti, jai nusilenkė, atsisėdo į savo sostą ir liepė pastatyti sostą karaliaus motinai; ir ji atsisėdo jo dešinėje.'),
  (@b11, 2, 20, 'Tada ji tarė: „Tau turiu vieną mažą prašymą; meldžiu tave, neatsakyk man. Ir karalius jai tarė: „Prašyk, mano motina; nes tau neatsakysiu“.'),
  (@b11, 2, 21, 'Ir ji tarė: „Tebūna šunamietė Abišaga duota tavo broliui Adonijui į žmonas“.'),
  (@b11, 2, 22, 'Ir karalius Saliamonas atsakė ir tarė savo motinai: „Kodėl prašai Adonijui šunamietės Abišagos? Prašyk jam ir karalystės; nes jis yra mano vyresnysis brolis; tai yra jam, kunigui Abjatarui ir Cerujos sūnui Joabui“.'),
  (@b11, 2, 23, 'Tada karalius Saliamonas prisiekė VIEŠPAČIU, sakydamas: „Tegul Dievas padaro man taip ir dar daugiau, jei Adonijas nebus ištaręs šito žodžio prieš savo paties gyvybę.'),
  (@b11, 2, 24, 'Taigi dabar, kaip gyvas VIEŠPATS, kuris mane įtvirtino ir mane pasodino mano tėvo Dovydo soste ir kuris man padarė namus, kaip jis pažadėjo, šią dieną Adonijas bus užmuštas“.'),
  (@b11, 2, 25, 'Ir karalius Saliamonas siuntė per Jehojados sūnaus Benajos ranką; ir jis puolė jį, jog tas mirė.'),
  (@b11, 2, 26, 'Ir kunigui Abjatarui karalius tarė: „Eik į Anatotą, į savo laukus; nes tu vertas mirties; bet šiuo metu tavęs neužmušiu, kadangi nešiojai Viešpaties DIEVO skrynią mano tėvo Dovydo akivaizdoje ir kadangi kentėjai visame tame, kame kentėjo mano tėvas“.'),
  (@b11, 2, 27, 'Taip Saliamonas išvarė Abjatarą, kad nebebūtų kunigu VIEŠPAČIUI; kad išpildytų VIEŠPATIES žodį, kurį jis kalbėjo apie Elio namus Šilojuje.'),
  (@b11, 2, 28, 'Tada žinia atėjo pas Joabą; nes Joabas buvo pasukęs paskui Adoniją, nors jis nesuko paskui Abšalomą. Ir Joabas pabėgo į VIEŠPATIES padangtę ir nusitvėrė už aukuro ragų.'),
  (@b11, 2, 29, 'Ir karaliui Saliamonui buvo pranešta, kad Joabas pabėgo į VIEŠPATIES padangtę; ir štai jis yra šalia aukuro. Tada Saliamonas pasiuntė Jehojados sūnų Benają, sakydamas: „Eik, pulk jį“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b11, 2, 30, 'Ir atėjęs į VIEŠPATIES padangtę, Benajas jam tarė: „Taip sako karalius: ‘Išeik’“. Ir jis tarė: „Ne; čia mirsiu“. Ir Benajas parnešė karaliui žodį, sakydamas: „Taip kalbėjo Joabas ir taip jis man atsakė“.'),
  (@b11, 2, 31, 'Ir karalius jam tarė: „Daryk, kaip jis sakė, pulk jį ir palaidok jį; kad pašalintum nuo manęs ir nuo mano tėvo namų nekaltą kraują, kurį Joabas išliejo.'),
  (@b11, 2, 32, 'VIEŠPATS sugrąžins jo kraują ant jo paties galvos; jis užpuolė du vyrus, teisesnius ir geresnius už jį, ir juos nužudė kalaviju mano tėvui Dovydui apie tai nežinant – Nero sūnų Abnerą, Izraelio kariuomenės vadą, ir Jetero sūnų Amasą, Judos kariuomenės vadą.'),
  (@b11, 2, 33, 'Todėl jų kraujas sugrįš ant Joabo galvos ir ant jo sėklos galvos per amžius; bet Dovydui, jo sėklai, jo namams ir jo sostui bus ramybė nuo VIEŠPATIES per amžius“.'),
  (@b11, 2, 34, 'Taigi Jehojados sūnus Benajas nuėjęs aukštyn puolė ant jo ir jį nužudė; ir jis buvo palaidotas savo namuose dykumoje.'),
  (@b11, 2, 35, 'Ir karalius paskyrė į jo vietą kariuomenės vadu Jehojados sūnų Benają; o kunigą Cadoką karalius paskyrė į Abjataro vietą.'),
  (@b11, 2, 36, 'Ir karalius pasiuntęs pakvietė Šimį ir jam tarė: „Pasistatyk namus Jeruzalėje ir ten gyvenk, ir niekur iš ten neišeik.'),
  (@b11, 2, 37, 'Nes tą dieną, kai išeisi ir pereisi Kidrono upelį, tikrai žinok, kad tikrai mirsi; tavo kraujas bus ant tavo paties galvos“.'),
  (@b11, 2, 38, 'Ir Šimis tarė karaliui: „Tas pasakymas geras; kaip mano viešpats karalius pasakė, taip tavo tarnas darys“. Ir Šimis gyveno Jeruzalėje daug dienų.'),
  (@b11, 2, 39, 'O trejiems metams pasibaigus atsitiko, kad du iš Šimio tarnų išbėgo pas Gato karaliaus Maakos sūnų Achišą. Ir Šimiui pranešė, sakydami: „Štai tavo tarnai yra Gate“.'),
  (@b11, 2, 40, 'Ir Šimis, pakilęs ir pabalnojęs savo asilą, vyko į Gatą pas Achišą savo tarnų ieškoti; ir Šimis nuvyko ir parsivedė savo tarnus iš Gato.'),
  (@b11, 2, 41, 'Ir buvo pranešta Saliamonui, kad Šimis buvo išvykęs iš Jeruzalės į Gatą ir sugrįžęs.'),
  (@b11, 2, 42, 'Ir karalius pasiuntęs pakvietė Šimį ir jam tarė: „Argi tavęs neprisaikdinau VIEŠPAČIU ir tau netvirtinau, sakydamas: ‘Tikrai žinok, kad tą dieną, kai išvyksi ir kur nors vaikščiosi, tikrai mirsi’? O tu man sakei: ‘Žodis, kurį girdėjau, yra geras’.'),
  (@b11, 2, 43, 'Tai kodėl nesilaikei VIEŠPATIES priesaikos ir įsakymo, kuriuo buvau tave įpareigojęs?“'),
  (@b11, 2, 44, 'Karalius dar tarė Šimiui: „Tu žinai visą nedorybę, tavo širdžiai žinomą, kurią padarei mano tėvui Dovydui; todėl VIEŠPATS sugrąžins tavo nedorybę ant tavo paties galvos;'),
  (@b11, 2, 45, 'o karalius Saliamonas bus palaimintas, ir Dovydo sostas bus įtvirtintas VIEŠPATIES akivaizdoje per amžius“.'),
  (@b11, 2, 46, 'Taigi karalius įsakė Jehojados sūnui Benajui; šis išėjęs puolė jį, kad tas mirė. Ir karalystė buvo įtvirtinta Saliamono rankoje.'),
  (@b11, 3, 1, 'Ir Saliamonas susigiminiavo su faraonu, Egipto karaliumi, ir ėmė faraono dukterį, ir atvedė ją į Dovydo miestą, kol pabaigė statyti savo namus, VIEŠPATIES namus ir Jeruzalės sieną aplinkui.'),
  (@b11, 3, 2, 'Tauta vis dar aukojo aukštumose, nes iki tų dienų nebuvo pastatyti namai VIEŠPATIES vardui.'),
  (@b11, 3, 3, 'Ir Saliamonas mylėjo VIEŠPATĮ, vaikščiodamas savo tėvo Dovydo įstatais; išskyrus tai, kad jis aukojo ir degino smilkalus aukštumose.'),
  (@b11, 3, 4, 'Ir nuėjo karalius į Gibeoną, kad ten aukotų; nes tai buvo didi aukštuma; tūkstantį deginamųjų atnašų Saliamonas atnašavo ant to aukuro.'),
  (@b11, 3, 5, 'Gibeone VIEŠPATS naktį pasirodė Saliamonui sapne; ir Dievas tarė: „Prašyk, ką turėčiau tau duoti“.'),
  (@b11, 3, 6, 'Ir Saliamonas tarė: „Tu parodei savo tarnui Dovydui, mano tėvui, didelį gailestingumą pagal tai, kaip jis vaikščiojo tavo akivaizdoje tiesoje, teisume ir tiesumu širdies su tavimi; ir tu jam išlaikei šitą didelį gerumą, duodamas jam sūnų, kad sėdėtų jo soste, kaip yra šią dieną.'),
  (@b11, 3, 7, 'Ir dabar, o VIEŠPATIE, mano Dieve, tu paskyrei karaliumi savo tarną mano tėvo Dovydo vietoje; o aš tesu jaunas vaikas; nežinau, kaip išeiti ar įeiti.'),
  (@b11, 3, 8, 'Ir tavo tarnas viduryje tavo tautos, kurią išsirinkai, didelės tautos, kurios negalima suskaičiuoti nei suskaityti dėl daugybės.'),
  (@b11, 3, 9, 'Todėl duok savo tarnui suprantančią širdį tavo tautai teisti, kad atskirčiau tarp gero ir blogo; nes kas yra pajėgus teisti šią tavo tokią didelę tautą?“'),
  (@b11, 3, 10, 'Ir Viešpačiui patiko ta kalba, kad Saliamonas prašė šito dalyko.'),
  (@b11, 3, 11, 'Ir Dievas jam tarė: „Kadangi prašei šito dalyko, o neprašei sau ilgo gyvenimo; nei neprašei sau turtų ir neprašei savo priešų gyvybės; bet prašei sau supratimo teismams atskirti;'),
  (@b11, 3, 12, 'štai aš padariau pagal tavo žodžius; štai daviau tau išmintingą ir supratingą širdį; taip, kad tau lygaus nebuvo pirma tavęs, nei po tavęs neiškils tau lygaus.'),
  (@b11, 3, 13, 'Ir taip pat daviau tau tai, ko neprašei, tiek turtų, tiek garbės; taip, kad niekas tau neprilygs tarp karalių per visas tavo dienas.'),
  (@b11, 3, 14, 'Ir jei vaikščiosi mano keliais, laikydamasis mano įstatų ir įsakymų, kaip vaikščiojo tavo tėvas Dovydas, tuomet prailginsiu tavo dienas“.'),
  (@b11, 3, 15, 'Ir Saliamonas atsibudo; ir štai, tai buvo sapnas. Ir jis atėjo į Jeruzalę ir, atsistojęs prieš VIEŠPATIES Sandoros skrynią, atnašavo deginamąsias atnašas, atnašavo taikos atnašas ir iškėlė puotą visiems savo tarnams.'),
  (@b11, 3, 16, 'Tada dvi moterys, paleistuvės, atėjo pas karalių ir atsistojo jo akivaizdoje.'),
  (@b11, 3, 17, 'Ir viena moteris tarė: „O, mano viešpatie, aš ir šita moteris gyvename vienuose namuose; ir pagimdžiau vaiką pas ją tuose namuose.'),
  (@b11, 3, 18, 'Ir trečiąją dieną po mano gimdymo įvyko, kad pagimdė ir šita moteris; ir mes buvome drauge; jokio pašalinio nebuvo su mumis namuose, tik mes dvi namuose.'),
  (@b11, 3, 19, 'Ir šitos moters vaikas naktį mirė; nes ji nugulė jį.'),
  (@b11, 3, 20, 'Ir vidurnaktį atsikėlusi, tavo tarnaitei miegant, ji paėmė mano sūnų nuo mano pašonės ir paguldė jį sau į glėbį, o savo mirusį vaiką paguldė man į glėbį.'),
  (@b11, 3, 21, 'Ir man ryte atsikėlus savo vaiko žindyti, štai jis buvo miręs; bet man ryte gerai įsižiūrėjus, štai tai nebuvo mano sūnus, kurį pagimdžiau“.'),
  (@b11, 3, 22, 'Ir kita moteris tarė: „Ne; gyvasis yra mano sūnus, o mirusysis yra tavo sūnus“. O šita sakė: „Ne; mirusysis yra tavo sūnus, o gyvasis yra mano sūnus“. Taip jos kalbėjo karaliaus akivaizdoje.'),
  (@b11, 3, 23, 'Tada karalius tarė: „Viena sako: ‘Šitas, gyvasis, yra mano sūnus, o tavo sūnus yra mirusysis’, o kita sako: ‘Ne; tavo sūnus yra mirusysis, o mano sūnus yra gyvasis’“.'),
  (@b11, 3, 24, 'Ir karalius tarė: „Atneškite man kalaviją“. Ir atnešė kalaviją karaliaus akivaizdon.'),
  (@b11, 3, 25, 'Ir karalius tarė: „Padalykite gyvąjį kūdikį į dvi dalis ir duokite pusę vienai, o pusę kitai“.'),
  (@b11, 3, 26, 'Tada ta moteris, kurios vaikas buvo gyvasis, tarė karaliui, nes jos viduriai kankinosi dėl savo sūnaus, ir ji tarė: „O, mano viešpatie, duok jai gyvąjį vaiką ir jokiu būdu nežudyk jo“. Bet kita sakė: „Tegul jis nebus nei mano, nei tavo, padalykite jį“.'),
  (@b11, 3, 27, 'Tada karalius atsiliepdamas tarė: „Atiduokite jai gyvąjį vaiką ir jokiu būdu jo nežudykite; ji yra jo motina“.'),
  (@b11, 3, 28, 'Ir visas Izraelis išgirdo apie tą teismą, kuriuo teisė karalius; ir jie bijojo karaliaus; nes matė, kad Dievo išmintis buvo jame, kad įvykdytų teismą.'),
  (@b11, 4, 1, 'Taip karalius Saliamonas buvo karalius visam Izraeliui.'),
  (@b11, 4, 2, 'Ir šitie buvo kunigaikščiai, kuriuos jis turėjo: kunigo Cadoko sūnus Azarijas,'),
  (@b11, 4, 3, 'Šišos sūnūs Elihorefas ir Ahija – raštininkai; Ahiludo sūnus Jehozapatas – metraštininkas.'),
  (@b11, 4, 4, 'Jehojados sūnus Benajas vadovavo kariuomenei; Cadokas ir Abjataras buvo kunigai;'),
  (@b11, 4, 5, 'Natano sūnus Azarijas vadovavo pareigūnams; Natano sūnus Zabudas buvo vyriausiasis pareigūnas ir karaliaus draugas;'),
  (@b11, 4, 6, 'Ahišaras – namų viršininkas; o Abdos sūnus Adoniramas vadovavo duoklei.'),
  (@b11, 4, 7, 'Saliamonas turėjo dvylika pareigūnų visam Izraeliui, kurie aprūpindavo maistu karalių ir jo namiškius: kiekvienas aprūpindavo per savąjį mėnesį metuose.'),
  (@b11, 4, 8, 'O šitie yra jų vardai: Huro sūnus Efraimo kalne,'),
  (@b11, 4, 9, 'Dekerio sūnus Makace, Šaalbime, Bet-Šemeše ir Elon-Bet-Hanane,'),
  (@b11, 4, 10, 'Hesedo sūnus Arubote; jam priklausė Sokas ir visa Hefero šalis;'),
  (@b11, 4, 11, 'Abinadabo sūnus visoje Doro srityje; jis turėjo Saliamono dukterį Tafatą už žmoną;'),
  (@b11, 4, 12, 'Ahiludo sūnus Baana; jam priklausė Taanachas, Megidas ir visas Bet-Šeanas, esantis šalia Caretano, žemiau Jezreelio, nuo Bet-Šeano iki Abel-Meholos, iki vietos anapus Jokneamo;'),
  (@b11, 4, 13, 'Gebero sūnus Ramot-Gileade; jam priklausė Manaso sūnaus Jayro miestai, esantys Gileade; jam priklausė ir Argobo sritis, esanti Bašane, šešiasdešimt didelių miestų su sienomis ir žalvariniais skląsčiais;'),
  (@b11, 4, 14, 'Ido sūnus Ahinadabas turėjo Mahanaimą;'),
  (@b11, 4, 15, 'Ahimaacas buvo Naftalyje; jis taip pat ėmė Saliamono dukterį Basmatą į žmonas;'),
  (@b11, 4, 16, 'Hušajo sūnus Baana buvo Ašeryje ir Alote;'),
  (@b11, 4, 17, 'Paruacho sūnus Jehozapatas Isachare;'),
  (@b11, 4, 18, 'Elos sūnus Šimis Benjamine;'),
  (@b11, 4, 19, 'Ūrio sūnus Geberas buvo Gileado šalyje, amoritų karaliaus Sihono ir Bašano karaliaus Ogo šalyje; ir jis buvo vienintelis pareigūnas, esantis šalyje.'),
  (@b11, 4, 20, 'Judos ir Izraelio buvo daug, kaip daugybė smėlio pajūryje, valgančių, geriančių ir besilinksminančių.'),
  (@b11, 4, 21, 'Saliamonas karaliavo visoms karalystėms nuo upės iki filistinų šalies ir iki Egipto ribos; jie nešė dovanas ir tarnavo Saliamonui per visas jo gyvenimo dienas.'),
  (@b11, 4, 22, 'O Saliamono aprūpinimas vienai dienai buvo trisdešimt saikų smulkių miltų ir šešiasdešimt saikų miltų,'),
  (@b11, 4, 23, 'dešimt riebių jaučių, dvidešimt jaučių iš ganyklų ir šimtas avių, neskaitant elnių, stirnų, rudųjų stirnų ir nupenėtų skrajūnų.'),
  (@b11, 4, 24, 'Nes jis viešpatavo visai sričiai šiapus upės, nuo Tifsacho iki Azos, visiems karaliams šiapus upės; ir jis turėjo ramybę visose pusėse aplink jį.'),
  (@b11, 4, 25, 'Ir Juda bei Izraelis saugiai gyveno, kiekvienas po savo vynmedžiu ir po savo figmedžiu, nuo Dano iki Beer-Šebos per visas Saliamono dienas.'),
  (@b11, 4, 26, 'Saliamonas turėjo keturiasdešimt tūkstančių gardų savo vežimų žirgams ir dvylika tūkstančių raitelių.'),
  (@b11, 4, 27, 'Ir tie pareigūnai aprūpindavo maistu karalių Saliamoną ir visus, atėjusius prie karaliaus Saliamono stalo, kiekvienas savo mėnesį; jiems nieko netrūko.'),
  (@b11, 4, 28, 'Jie taip pat atgabendavo miežių ir šiaudų žirgams ir dromedarams į tą vietą, kur pareigūnai buvo kiekvienas pagal savąją pareigą.'),
  (@b11, 4, 29, 'Ir Dievas davė Saliamonui išminties ir supratimo be galo daug, ir širdies platumą kaip smėlio jūros pakrantėje.'),
  (@b11, 4, 30, 'Ir Saliamono išmintis pranoko visų rytų šalies vaikų išmintį ir visą Egipto išmintį.'),
  (@b11, 4, 31, 'Nes jis buvo išmintingesnis už visus žmones; už ezrahitą Etaną ir už Maholo sūnus Hemaną, Kalkolą ir Dardą; ir jis buvo pagarsėjęs visose aplinkinėse tautose.'),
  (@b11, 4, 32, 'Ir jis kalbėjo tris tūkstančius patarlių; o jo giesmių buvo tūkstantis ir penkios.'),
  (@b11, 4, 33, 'Ir jis kalbėjo apie medžius, nuo Libane esančio kedro iki yzopo, augančio iš sienos; jis kalbėjo ir apie žvėris, skrajūnus, roplius ir žuvis.'),
  (@b11, 4, 34, 'Ir iš visų tautų ateidavo pasiklausyti Saliamono išminties, iš visų žemės karalių, kurie buvo girdėję apie jo išmintį.'),
  (@b11, 5, 1, 'Ir siuntė Tyro karalius Hiramas savo tarnus pas Saliamoną; nes jis išgirdo, kad jį patepė karaliumi jo tėvo vietoje; nes Hiramas visada buvo Dovydo mylėtojas.'),
  (@b11, 5, 2, 'Ir Saliamonas siuntė pas Hiramą, sakydamas:'),
  (@b11, 5, 3, '„Tu žinai, kad mano tėvas Dovydas negalėjo statyti namų VIEŠPATIES, savo Dievo, vardui dėl karų, kurie buvo aplink jį iš visų pusių, kol VIEŠPATS nepadėjo jų po jo kojų padais.'),
  (@b11, 5, 4, 'Bet dabar VIEŠPATS, mano Dievas, man davė poilsį iš visų pusių taip, kad nebėra nei priešininko, nei blogų įvykių.'),
  (@b11, 5, 5, 'Ir štai ketinu statyti namus VIEŠPATIES, savo Dievo, vardui, kaip VIEŠPATS kalbėjo mano tėvui Dovydui, sakydamas: ‘Tavo sūnus, kurį tavo vietoj pasodinsiu į tavo sostą, pastatys namus mano vardui’.'),
  (@b11, 5, 6, 'Taigi dabar įsakyk, kad man prikirstų kedrų iš Libano; ir mano tarnai bus su tavo tarnais; o už tavo tarnus aš tau duosiu užmokestį pagal visa tai, kaip nustatysi; nes žinai, kad tarp mūsų nėra nei vieno taip mokančio kirsti medieną, kaip sidoniečiai“.'),
  (@b11, 5, 7, 'Ir atsitiko, kad Hiramas išgirdęs Saliamono žodžius labai apsidžiaugė ir tarė: „Tebūna šią dieną palaimintas VIEŠPATS, kuris davė Dovydui išmintingą sūnų šitai didelei tautai valdyti“.'),
  (@b11, 5, 8, 'Ir Hiramas siuntė Saliamonui, sakydamas: „Atsižvelgiau į reikalus, dėl kurių siuntei pas mane; aš patenkinsiu visą tavo norą dėl kedro rąstų ir eglės rąstų.'),
  (@b11, 5, 9, 'Mano tarnai nugabens juos žemyn nuo Libano į jūrą; o aš juos nugabensiu sieliais jūra iki tos vietos, kurią man nurodysi, ir ten juos iškrausiu, o tu juos paimsi; ir tu patenkinsi mano norą, duodamas maisto mano namiškiams“.'),
  (@b11, 5, 10, 'Taip Hiramas davė Saliamonui kedro medžių ir eglės medžių, kiek tik jis norėjo.'),
  (@b11, 5, 11, 'O Saliamonas davė Hiramui dvidešimt tūkstančių saikų kviečių jo namiškiams maistui ir dvidešimt saikų gryno aliejaus; taip Saliamonas davė Hiramui kasmet.'),
  (@b11, 5, 12, 'Ir VIEŠPATS davė Saliamonui išminties, kaip jam pažadėjo; ir buvo taika tarp Hiramo ir Saliamono; ir juodu sudarė sąjungą.'),
  (@b11, 5, 13, 'Ir karalius Saliamonas pakėlė rinkliavą visam Izraeliui; o rinkliava buvo trisdešimt tūkstančių vyrų.'),
  (@b11, 5, 14, 'Jis juos siųsdavo į Libaną, kas mėnesį po dešimtį tūkstančių paeiliui; mėnesį jie būdavo Libane, o du mėnesius namie; o Adoniramas vadovavo tai rinkliavai.'),
  (@b11, 5, 15, 'Saliamonas turėjo septyniasdešimt tūkstančių, nešančių naštas, ir aštuoniasdešimt tūkstančių tašytojų kalnuose;'),
  (@b11, 5, 16, 'neskaitant trijų tūkstančių ir trijų šimtų Saliamono vyriausių pareigūnų, vadovaujančių darbui, kurie vadovavo liaudžiai, atliekančiai darbą.'),
  (@b11, 5, 17, 'Karaliui įsakius jie atgabeno didelius akmenis, brangius akmenis ir tašytus akmenis, kad padėtų namų pamatus.'),
  (@b11, 5, 18, 'Saliamono statytojai ir Hiramo statytojai juos tašė, ir akmens tašytojai; taip jie paruošė rąstus ir akmenis namų statybai.'),
  (@b11, 6, 1, 'Ir įvyko, kad keturi šimtai aštuoniasdešimtaisiais metais po Izraelio vaikų išėjimo iš Egipto šalies, ketvirtaisiais Saliamono karaliavimo Izraeliui metais, Zivo mėnesį, kuris yra antras mėnuo, jis pradėjo statyti VIEŠPATIES namus.'),
  (@b11, 6, 2, 'Ir tie namai, kuriuos karalius Saliamonas statė VIEŠPAČIUI, buvo šešiasdešimties uolekčių ilgio, dvidešimties uolekčių pločio ir trisdešimties uolekčių aukščio.'),
  (@b11, 6, 3, 'O prieangis priešais namų šventyklą buvo dvidešimties uolekčių ilgio, pagal namų plotį; o jo plotis priešais namus buvo dešimt uolekčių.'),
  (@b11, 6, 4, 'Ir namams jis padarė siaurų šviesų langus.'),
  (@b11, 6, 5, 'O prie namų sienos jis aplinkui pastatė kambarius, aplinkui prie namų sienų, tiek šventyklos, tiek orakulo; ir aplinkui padarė kambarius:'),
  (@b11, 6, 6, 'apatinis kambarys buvo penkių uolekčių pločio, vidurinis buvo šešių uolekčių pločio, o trečiasis buvo septynių uolekčių pločio; nes namų sienoje iš išorės aplinkui padarė siauras atramas, kad sijų nereikėtų tvirtinti prie namų sienų.'),
  (@b11, 6, 7, 'Ir kai namai buvo statomi, jie buvo statomi iš akmenų, paruoštų prieš jų atgabenimą čia; taip, kad juos statant nesigirdėjo namuose nei kūjo, nei kirvio, nei jokio geležinio įrankio.'),
  (@b11, 6, 8, 'Durys viduriniam kambariui buvo dešiniajame namų šone; ir spiraliniais laiptais ėjo aukštyn į vidurinį kambarį, o iš vidurinio į trečiąjį.'),
  (@b11, 6, 9, 'Taip jis statė namus ir juos užbaigė; ir apdengė namus kedro sijomis ir lentomis.'),
  (@b11, 6, 10, 'Ir tada jis pastatė kambarius prie visų namų, penkių uolekčių aukščio; ir jie laikėsi ant namo kedro sijomis.'),
  (@b11, 6, 11, 'Ir atėjo Saliamonui VIEŠPATIES žodis, sakydamas:'),
  (@b11, 6, 12, '„Dėl šitų namų, kuriuos tu statai: jei vaikščiosi pagal mano įstatus, vykdysi mano teismus ir laikysiesi visų mano įsakymų, kad vaikščiotum pagal juos; tuomet vykdysiu savo žodį su tavimi, kurį kalbėjau tavo tėvui Dovydui;'),
  (@b11, 6, 13, 'ir gyvensiu tarp Izraelio vaikų ir nepaliksiu savo tautos Izraelio“.'),
  (@b11, 6, 14, 'Taip Saliamonas statė namus ir juos užbaigė.'),
  (@b11, 6, 15, 'Ir jis pastatė sienas namų viduje iš kedro lentų, tiek namų grindis, tiek lubų sienas; ir jis jas apdengė iš vidaus medžiu ir apdengė namų grindis eglinėmis lentomis.'),
  (@b11, 6, 16, 'Ir pastatė dvidešimt uolekčių ant namo šonų, tiek grindis, tiek sienas kedro lentomis; pastatė jas viduje jam, tai yra orakului, visų švenčiausiajai.'),
  (@b11, 6, 17, 'O namai, tai yra šventykla priešais juos, buvo keturiasdešimties uolekčių ilgio.'),
  (@b11, 6, 18, 'O kedras namų viduje buvo išdrožinėtas bumbulais ir išsiskleidusiomis gėlėmis; viskas buvo iš kedro; nebuvo matyti akmens.'),
  (@b11, 6, 19, 'O orakulą paruošė namų viduje, kad ten pastatytų VIEŠPATIES Sandoros skrynią.'),
  (@b11, 6, 20, 'Orakulas priešakinėje dalyje buvo dvidešimties uolekčių ilgio, dvidešimties uolekčių pločio ir dvidešimties uolekčių savojo aukščio; ir padengė jį grynu auksu; ir taip apdengė kedrinį aukurą.'),
  (@b11, 6, 21, 'Taip Saliamonas padengė namus iš vidaus grynu auksu; ir padarė pertvarą aukso grandinėmis prieš orakulą; ir jį padengė auksu.'),
  (@b11, 6, 22, 'Ir visus namus jis padengė auksu, kol užbaigė visus namus; taip pat visą aukurą, esantį šalia orakulo, jis padengė auksu.'),
  (@b11, 6, 23, 'O orakulo viduje padarė du kerubus iš alyvmedžio, kiekvieną dešimties uolekčių aukščio.'),
  (@b11, 6, 24, 'Penkių uolekčių buvo vienas kerubo sparnas ir penkių uolekčių kitas kerubo sparnas; nuo vieno sparno galo iki kito sparno galo buvo dešimt uolekčių.'),
  (@b11, 6, 25, 'Ir kitas kerubas buvo dešimties uolekčių; abu kerubai buvo vienodų matmenų ir vienodo dydžio.'),
  (@b11, 6, 26, 'Vieno kerubo aukštis buvo dešimt uolekčių, ir toks pat buvo kito kerubo.'),
  (@b11, 6, 27, 'Ir jis pastatė kerubus vidinių namų viduje; ir jie taip išskėtė kerubų sparnus, kad vieno sparnas lietė vieną sieną, o kito kerubo sparnas lietė kitą sieną; o jų sparnai lietė vienas kitą namų viduryje.'),
  (@b11, 6, 28, 'Ir jis padengė kerubus auksu.'),
  (@b11, 6, 29, 'Visas namų sienas aplinkui, viduje ir išorėje, jis išraižė kerubų, palmių ir išsiskleidusių gėlių išraižytais atvaizdais.'),
  (@b11, 6, 30, 'O namų grindis jis išklojo auksu iš vidaus ir iš išorės.'),
  (@b11, 6, 31, 'Orakulo įėjimui jis padarė duris iš alyvmedžio; sąrama ir šoninės staktos buvo penktadalis sienos.'),
  (@b11, 6, 32, 'Dvejos durys irgi buvo iš alyvmedžio; ir jis išraižė ant jų kerubų, palmių ir išsiskleidusių gėlių rėžinius ir juos padengė auksu, ir padengė auksu kerubus ir palmes.'),
  (@b11, 6, 33, 'Taip jis padarė ir šventyklos durims staktas iš alyvmedžio, ketvirtadalį sienos.'),
  (@b11, 6, 34, 'Ir dvejos durys buvo iš eglės medžio; abi vienerių durų sąvaros buvo suveriamos, ir abi kitų durų sąvaros buvo suveriamos.'),
  (@b11, 6, 35, 'Ir jis išraižė ant jų kerubus, palmes ir išsiskleidusias gėles; ir padengė tuos auksu, pritaikytu tam raižiniui.'),
  (@b11, 6, 36, 'Ir pastatė vidinį kiemą iš trijų tašyto akmens eilių ir eilės kedro sijų.'),
  (@b11, 6, 37, 'Ketvirtaisiais metais, Zivo mėnesį, buvo padėtas VIEŠPATIES namų pamatas;'),
  (@b11, 6, 38, 'o vienuoliktaisiais metais, Bulo mėnesį, kuris yra aštuntas mėnuo, buvo užbaigti namai su visomis jų dalimis ir pagal visą jų pavyzdį. Taigi jis juos statė septynerius metus.'),
  (@b11, 7, 1, 'Bet savo paties namus Saliamonas statė trylika metų ir užbaigė visus savo namus.'),
  (@b11, 7, 2, 'Taip pat jis pastatė Libano miško namus šimto uolekčių ilgio, penkiasdešimties uolekčių pločio ir trisdešimties uolekčių aukščio, ant keturių eilių kedro stulpų su kedro sijomis ant stulpų.'),
  (@b11, 7, 3, 'Ir jie buvo apdengti kedru iš viršaus ant sijų, gulinčių ant keturiasdešimt penkių stulpų, kurių po penkiolika eilėje.'),
  (@b11, 7, 4, 'Ir buvo langai trimis eilėmis, ir šviesa buvo priešais šviesą trimis eilėmis.'),
  (@b11, 7, 5, 'O visos durys ir staktos buvo keturkampės kartu su langais; ir šviesa priešais šviesą trimis eilėmis.'),
  (@b11, 7, 6, 'Ir jis padarė stulpų prieangį penkiasdešimties uolekčių ilgio ir trisdešimties uolekčių pločio; ir prieš juos buvo prieangis; o kiti stulpai ir stora sija buvo priešais juos.'),
  (@b11, 7, 7, 'Tada jis padarė prieangį sostui, kur galėtų teisti – teismo prieangį; ir jis buvo padengtas kedru nuo vieno grindų krašto iki kito.'),
  (@b11, 7, 8, 'O jo namai, kuriuose jis gyveno, turėjo kitą kiemą, vidinėje prieangio pusėje, lygiai taip pat padarytą. Saliamonas padarė namus, tokius pat, kaip šis prieangis, ir faraono dukteriai, kurią buvo paėmęs į žmonas.'),
  (@b11, 7, 9, 'Visi šitie buvo iš brangių akmenų, pagal matą nutašytų akmenų, pjūklais nupjautų iš vidaus ir iš lauko, nuo pamato iki lubų, ir taip iš lauko iki didžiojo kiemo.'),
  (@b11, 7, 10, 'O pamatas buvo iš brangių akmenų, didelių akmenų, dešimties uolekčių akmenų ir aštuonių uolekčių akmenų.'),
  (@b11, 7, 11, 'Ir viršuje buvo brangūs akmenys, pagal nutašytų akmenų matus, ir kedrai.'),
  (@b11, 7, 12, 'O didysis kiemas aplinkui buvo iš trijų eilių tašytų akmenų ir eilės kedro sijų; tiek VIEŠPATIES namų vidiniam kiemui, tiek namų prieangiui.'),
  (@b11, 7, 13, 'Ir karalius Saliamonas pasiuntė ir atsigabeno iš Tyro Hiramą.'),
  (@b11, 7, 14, 'Jis buvo našlės sūnus iš Naftalio genties, o jo tėvas buvo Tyro vyras, dirbantis su žalvariu; jis buvo pripildytas išminties, supratimo ir sugebėjimo atlikti visus žalvario darbus. Ir, atvykęs pas karalių Saliamoną, jis atliko visą savo darbą.'),
  (@b11, 7, 15, 'Nes jis nuliejo du žalvario stulpus, kiekvieną aštuoniolikos uolekčių aukščio; dvylikos uolekčių virvė juosė kiekvieną iš jų.'),
  (@b11, 7, 16, 'Ir jis dar padarė du lieto žalvario kapitelius, uždėti ant stulpų viršaus; penkios uolektys buvo vieno kapitelio aukštis ir penkios uolektys buvo kito kapitelio aukštis;'),
  (@b11, 7, 17, 'languoto darbo tinklelius ir grandinėlių dirbinio pynes kapiteliams, esantiems ant stulpų viršaus: septynis vienam kapiteliui ir septynis kitam kapiteliui.'),
  (@b11, 7, 18, 'Ir jis padarė stulpus ir dvi eiles granatų aplinkui ant vieno tinklo, kad apdengtų kapitelius, esančius ant viršaus; ir taip jis padarė kitam kapiteliui.'),
  (@b11, 7, 19, 'O kapiteliai prieangyje, esantys ant stulpų viršaus, buvo lelijų dirbinys, keturių uolekčių.'),
  (@b11, 7, 20, 'O ant dviejų stulpų esantys kapiteliai viršuje turėjo ir granatų priešais iškilimą, esantį prie tinklelio; o granatų buvo du šimtai eilėmis aplinkui ant kito kapitelio.'),
  (@b11, 7, 21, 'Ir jis pastatė stulpus šventyklos prieangyje; jis pastatė dešinįjį stulpą ir pavadino jį Jachino vardu; ir jis pastatė kairįjį stulpą ir pavadino jį Boazo vardu.'),
  (@b11, 7, 22, 'O ant stulpų viršaus buvo lelijų dirbinys; taip buvo baigtas stulpų darbas.'),
  (@b11, 7, 23, 'Ir jis padarė nulietą jūrą dešimties uolekčių nuo vienos briaunos iki kitos; ji buvo apskrita aplinkui, ir ji buvo penkių uolekčių aukščio; ir aplinkui ją apjuosė trisdešimties uolekčių virvė.'),
  (@b11, 7, 24, 'O aplink po jos briauna buvo ją apjuosiantys bumbulai, po dešimt uolektyje, apjuosiantys jūrą aplinkui; bumbulai buvo išlieti dviem eilėmis, kai ji buvo išlieta.'),
  (@b11, 7, 25, 'Ji stovėjo ant dvylikos jaučių, trys žiūrintys į šiaurę, trys žiūrintys į vakarus, trys žiūrintys į pietus ir trys žiūrintys į rytus; o jūra buvo padėta ant jų viršuje; o visos jų užpakalinės dalys buvo nukreiptos į vidų.'),
  (@b11, 7, 26, 'O ji buvo plaštakos storio, ir jos briauna buvo padaryta kaip taurės briauna, su lelijos žiedais; joje buvo du tūkstančiai batų.'),
  (@b11, 7, 27, 'Ir jis padarė dešimt žalvario stovų; vienas stovas buvo keturių uolekčių ilgio, keturių uolekčių pločio ir trijų uolekčių aukščio.'),
  (@b11, 7, 28, 'Ir tie stovai buvo padaryti šitaip: jie turėjo kraštus, o kraštai buvo tarp atbrailų.'),
  (@b11, 7, 29, 'Ir ant kraštų, esančių tarp atbrailų, buvo liūtai, jaučiai ir kerubai; o ant atbrailų viršaus buvo stovai; o apačioje liūtų ir jaučių buvo tam tikri plono dirbinio priedai.'),
  (@b11, 7, 30, 'Ir kiekvienas stovas turėjo keturis žalvarinius ratus ir žalvario plokštes; o keturi jo kampai turėjo atramas; po praustuve buvo lietos atramos prie kiekvieno priedo šono.'),
  (@b11, 7, 31, 'O jo anga kapitelio vidaus pusėje ir viršuje buvo per uolektį; bet jo anga buvo apskrita, pagal stovo padarymą, pusantros uolekties; taip pat ant jo angos buvo rėžiniai su jų kraštais, keturkampiai, ne apskriti.'),
  (@b11, 7, 32, 'O kraštų apačioje buvo keturi ratai; ratų ašys buvo prijungtos prie stovo; o rato aukštis buvo pusantros uolekties.'),
  (@b11, 7, 33, 'Ir ratai buvo padaryti, kaip padaromas vežimo ratas: jų ašys, jų stebulės, jų ratlankiai ir jų stipinai, viskas buvo nulieta.'),
  (@b11, 7, 34, 'O prie keturių stovo kampų buvo keturios atramos; atramos buvo iš paties stovo.'),
  (@b11, 7, 35, 'O stovo viršuje buvo pusės uolekties aukščio apskritas lankas; stovo viršuje jo atbrailos ir jo kraštai buvo iš to paties.'),
  (@b11, 7, 36, 'Nes jo atbrailų plokštėse ir jo kraštuose jis išraižė kerubus, liūtus ir palmes, pagal kiekvieno proporciją ir priedus aplinkui.'),
  (@b11, 7, 37, 'Tokiu būdu jis padarė dešimt stovų: jie visi buvo vienodo liejimo, vienodo mato, vienodo dydžio.'),
  (@b11, 7, 38, 'Po to jis padarė dešimt žalvario praustuvių; vienoje praustuvėje buvo keturiasdešimt batų; kiekviena praustuvė buvo keturių uolekčių; ant kiekvieno iš dešimties stovų viena praustuvė.'),
  (@b11, 7, 39, 'Jis pastatė penkis stovus dešiniajame namų šone ir penkis kairiajame namų šone; o jūrą jis pastatė dešiniajame namų šone į rytus priešais pietus.'),
  (@b11, 7, 40, 'Ir Hiramas padarė praustuves, semtuvus ir dubenis. Taigi Hiramas baigė daryti visą darbą, kurį jis atliko karaliui Saliamonui VIEŠPATIES namams:'),
  (@b11, 7, 41, 'du stulpus ir du kapitelių rutulius, esančius ant dviejų stulpų viršaus; ir du tinklus apdengti dviems kapitelių rutuliams, esantiems ant stulpų viršaus;'),
  (@b11, 7, 42, 'keturis šimtus granatų dviems tinklams, po dvi eiles granatų vienam tinklui, apdengti dviems kapitelių rutuliams, esantiems ant stulpų;'),
  (@b11, 7, 43, 'dešimt stovų ir dešimt praustuvių ant stovų;'),
  (@b11, 7, 44, 'vieną jūrą ir dvylika jaučių po jūra;'),
  (@b11, 7, 45, 'puodus, semtuvus ir dubenis; visi šitie indai, kuriuos Hiramas padarė karaliui Saliamonui VIEŠPATIES namams, buvo iš skaistaus žalvario.'),
  (@b11, 7, 46, 'Karalius juos nuliejo Jordano lygumoje, molinėje žemėje tarp Sukoto ir Cartano.'),
  (@b11, 7, 47, 'Ir Saliamonas paliko visus indus nepasvertus, nes jų buvo be galo daug; žalvario svoris nebuvo nustatytas.'),
  (@b11, 7, 48, 'Ir Saliamonas padarė visus indus, priklausančius VIEŠPATIES namams: aukso aukurą, aukso stalą, ant kurio buvo parodomoji duona,'),
  (@b11, 7, 49, 'žvakides iš gryno aukso, penkias dešinėje pusėje ir penkias kairėje, priešais orakulą, su gėlių žiedais, žibintais ir aukso žnyplėmis,'),
  (@b11, 7, 50, 'taures, gnybtuvus, dubenis, šaukštus, gryno aukso smilkytuvus; aukso vyrius tiek vidinių namų, švenčiausiosios, durims, tiek namų, būtent šventyklos, durims.'),
  (@b11, 7, 51, 'Taip buvo užbaigtas visas darbas, kurį karalius Saliamonas atliko VIEŠPATIES namams. Ir Saliamonas atgabeno savo tėvo Dovydo pašvęstus dalykus; tai yra sidabrą, auksą ir indus jis sudėjo tarp VIEŠPATIES namų lobių.'),
  (@b11, 8, 1, 'Tada Saliamonas surinko Izraelio vyresniuosius, visas genčių galvas, Izraelio vaikų tėvų vyriausiuosius, pas karalių Saliamoną į Jeruzalę, kad jie neštų aukštyn VIEŠPATIES Sandoros skrynią iš Dovydo miesto, kuris yra Sionas.'),
  (@b11, 8, 2, 'Ir visi Izraelio vyrai susirinko pas karalių Saliamoną per šventę Etanimo mėnesį, kuris yra septintasis mėnuo.'),
  (@b11, 8, 3, 'Ir visiems Izraelio vyresniesiems atvykus, kunigai pakėlė skrynią.'),
  (@b11, 8, 4, 'Ir jie nešė aukštyn VIEŠPATIES skrynią, susirinkimo padangtę ir visus šventus indus, buvusius padangtėje, juos nešė aukštyn kunigai ir levitai.'),
  (@b11, 8, 5, 'O karalius Saliamonas ir visas pas jį susirinkęs Izraelio susirinkimas, buvo su juo priešais skrynią, aukodami avis ir jaučius, kurių nebuvo galima nei suskaityti, nei suskaičiuoti dėl daugybės.'),
  (@b11, 8, 6, 'Ir kunigai įnešė VIEŠPATIES Sandoros skrynią į jos vietą, į namų orakulą, į švenčiausiąją vietą – po kerubų sparnais.'),
  (@b11, 8, 7, 'Nes kerubai išskėtė savo abu sparnus virš skrynios vietos, ir kerubai dengė iš viršaus skrynią ir jos kartis.'),
  (@b11, 8, 8, 'Ir ištraukė kartis, kad karčių galai matėsi šventojoje vietoje prieš orakulą, o jų nesimatė iš lauko; ir jos ten yra iki šios dienos.'),
  (@b11, 8, 9, 'Skrynioje nebuvo nieko, išskyrus dvi akmens plokštes, kurias Mozė ten įdėjo Horebe, kai VIEŠPATS sudarė sandorą su Izraelio vaikais, kai jie išėjo iš Egipto šalies.'),
  (@b11, 8, 10, 'Ir kunigams išėjus iš šventosios vietos, atsitiko, kad debesis pripildė VIEŠPATIES namus taip,'),
  (@b11, 8, 11, 'kad kunigai dėl debesies negalėjo stovėti, kad tarnautų; nes VIEŠPATIES šlovė pripildė VIEŠPATIES namus.'),
  (@b11, 8, 12, 'Tada Saliamonas tarė: „VIEŠPATS sakė, kad jis nori gyventi tirštoje tamsoje.'),
  (@b11, 8, 13, 'Aš tau tikrai pastačiau namus juose gyventi, nuolatinę vietą tau joje gyventi per amžius“.'),
  (@b11, 8, 14, 'Ir karalius atsukęs veidą palaimino visą Izraelio susirinkimą (o visas Izraelio susirinkimas stovėjo);');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b11, 8, 15, 'ir jis tarė: „Tebūna palaimintas VIEŠPATS, Izraelio Dievas, kuris savo burna kalbėjo mano tėvui Dovydui ir savo ranka tai ištesėjo, sakydamas:'),
  (@b11, 8, 16, '‘Nuo tos dienos, kai išvedžiau savo tautą Izraelį iš Egipto, aš neišsirinkau jokio miesto iš visų Izraelio genčių statyti namams, kad ten būtų mano vardas; bet išsirinkau Dovydą, kad valdytų mano tautą Izraelį’.'),
  (@b11, 8, 17, 'Ir mano tėvo Dovydo širdyje buvo statyti namus VIEŠPATIES, Izraelio Dievo, vardui.'),
  (@b11, 8, 18, 'Ir VIEŠPATS sakė mano tėvui Dovydui: ‘Kadangi tavo širdyje buvo statyti namus mano vardui, gerai darei, kad tai buvo tavo širdyje.'),
  (@b11, 8, 19, 'Tačiau tu nestatysi tų namų; bet tavo sūnus, kuris išeis iš tavo strėnų, jis pastatys namus mano vardui’.'),
  (@b11, 8, 20, 'Ir VIEŠPATS įvykdė savo žodį, kurį kalbėjo, ir aš iškilau į savo tėvo Dovydo vietą ir atsisėdau į Izraelio sostą, kaip VIEŠPATS pažadėjo, ir pastačiau namus VIEŠPATIES, Izraelio Dievo, vardui.'),
  (@b11, 8, 21, 'Ir ten paruošiau vietą skryniai, kurioje yra VIEŠPATIES sandora, kurią jis sudarė su mūsų tėvais, kai išvedė juos iš Egipto šalies“.'),
  (@b11, 8, 22, 'Ir Saliamonas atsistojo prieš VIEŠPATIES aukurą viso Izraelio susirinkimo akivaizdoje, išskėtė rankas į dangų'),
  (@b11, 8, 23, 'ir tarė: „VIEŠPATIE, Izraelio Dieve, nei aukštai danguje, nei žemai žemėje nėra tokio Dievo, kaip tu, kuris laikaisi sandoros ir gailestingumo su savo tarnais, kurie vaikšto tavo akivaizdoje visa širdimi;'),
  (@b11, 8, 24, 'kuris ištesėjai savo tarnui Dovydui, mano tėvui, ką jam pažadėjai; taip pat kalbėjai savo burna ir tai ištesėjai savo ranka, kaip yra šią dieną.'),
  (@b11, 8, 25, 'Taigi dabar, VIEŠPATIE, Izraelio Dieve, ištesėk savo tarnui Dovydui, mano tėvui, ką jam esi pažadėjęs, sakydamas: ‘Tau nepristigs mano akivaizdoje vyro, kad sėdėtų Izraelio soste; tik kad tavo vaikai žiūrėtų savo kelio, kad jie vaikščiotų mano akivaizdoje, kaip tu vaikščiojai mano akivaizdoje’.'),
  (@b11, 8, 26, 'O dabar, o Izraelio Dieve, meldžiu tave, tepasitvirtina tavo žodis, kurį kalbėjai savo tarnui Dovydui, mano tėvui.'),
  (@b11, 8, 27, 'Bet ar tikrai Dievas gyvens žemėje? Štai dangus ir dangų dangus negali tavęs sutalpinti; tai kaip juo mažiau šitie namai, kuriuos pastačiau?'),
  (@b11, 8, 28, 'Tačiau atsižvelk į savo tarno maldą ir jo prašymą, o VIEŠPATIE, mano Dieve, kad klausytumeisi šauksmo ir maldos, kuria tavo tarnas šiandien meldžiasi tavo akivaizdoje;'),
  (@b11, 8, 29, 'kad naktį ir dieną tavo akys būtų atvertos link šitų namų – link tos vietos, apie kurią esi sakęs: ‘Ten bus mano vardas’; kad klausytumeisi maldos, kuria tavo tarnas melsis šitos vietos link.'),
  (@b11, 8, 30, 'Ir išklausyk savo tarno ir savo tautos Izraelio prašymo, kai jie melsis šitos vietos link; ir išgirsk danguje, savo gyvenamoje vietoje; ir išgirdęs atleisk.'),
  (@b11, 8, 31, 'Jei kas nusižengs prieš savo artimą, ir iš jo bus pareikalauta prisiekti priesaiką, ir priesaika ateis prieš tavo aukurą šiuose namuose;'),
  (@b11, 8, 32, 'tuomet tu išgirsk danguje, veik ir teisk savo tarnus, pasmerkdamas nedorėlį, kad užtrauktum jo kelią ant jo paties galvos; ir išteisindamas teisųjį, kad jam duotum pagal jo teisumą.'),
  (@b11, 8, 33, 'Kai tavo tauta Izraelis bus sumušta priešo akivaizdoje dėl to, kad jie bus prieš tave nusidėję, ir sugrįš pas tave, išpažins tavo vardą, melsis ir tavęs prašys šiuose namuose;'),
  (@b11, 8, 34, 'tuomet išgirsk danguje ir atleisk savo tautos Izraelio nuodėmę, ir sugrąžink juos į tą šalį, kurią davei jų tėvams.'),
  (@b11, 8, 35, 'Kai dangus bus uždarytas ir nebus lietaus, nes jie bus prieš tave nusidėję; jei jie melsis šitos vietos link, išpažins tavo vardą ir nusigręš nuo savo nuodėmės, kai juos kamuosi;'),
  (@b11, 8, 36, 'tuomet išgirsk danguje ir atleisk savo tarnų ir savo tautos Izraelio nuodėmę, kad juos mokytum gerojo kelio, kuriuo jie turi vaikščioti, ir duok lietaus savo šaliai, kurią davei savo tautai paveldėti.'),
  (@b11, 8, 37, 'Jei šalyje bus badas, jei bus maras, džiovinantis pūtimas, pelėsiai, skėriai ar vikšrai; jei jų priešas juos apgultų jų miestų šalyje; kokia bebūtų rykštė, kokia bebūtų liga;'),
  (@b11, 8, 38, 'kokią maldą ar prašymą kas nors atliktų, ar visa tavo tauta Izraelis, kurie kiekvienas žino savo širdies rykštę, ir išskėstų savo rankas šitų namų link;'),
  (@b11, 8, 39, 'tuomet išklausyk danguje, savo gyvenamoje vietoje, ir atleisk, ir veik, ir duok kiekvienam pagal kelius jo, kurio širdį tu pažįsti (nes tik tu vienas pažįsti visų žmonių vaikų širdis);'),
  (@b11, 8, 40, 'kad jie tavęs bijotų per visas dienas, kurias jie gyvena šalyje, kurią davei mūsų tėvams.'),
  (@b11, 8, 41, 'Taip pat dėl ateivio, kuris nėra iš tavo tautos Izraelio, bet ateis iš tolimo krašto dėl tavo vardo'),
  (@b11, 8, 42, '(nes jie išgirs apie tavo didį vardą, apie tavo stiprią ranką ir apie tavo ištiestą ranką); kai jis ateis ir melsis šitų namų link;'),
  (@b11, 8, 43, 'tuomet tu išgirsk danguje, savo gyvenamoje vietoje, ir daryk pagal visa tai, dėl ko ateivis tavęs šaukiasi; kad visos žemės tautos pažintų tavo vardą, kad tavęs bijotų, kaip tavo tauta Izraelis; ir kad jie žinotų, jog šitie namai, kuriuos pastačiau, vadinami tavo vardu.'),
  (@b11, 8, 44, 'Jei tavo tauta išeis į mūšį prieš savo priešą, kur juos bepasiųstum, ir melsis VIEŠPAČIUI miesto link, kurį esi išsirinkęs, ir link namų, kuriuos pastačiau tavo vardui;'),
  (@b11, 8, 45, 'tuomet išgirsk danguje jų maldą bei jų prašymą ir paremk jų reikalą.'),
  (@b11, 8, 46, 'Jei jie prieš tave nusidės (nes nėra žmogaus, kuris nenusidėtų), ir tu, supykęs ant jų, atiduosi juos priešui, kad jie juos nuves nelaisvėn į priešo šalį, tolimą ar artimą;'),
  (@b11, 8, 47, 'tačiau jei jie susipras toje šalyje, į kurią jie bus išvesti nelaisvėn, atsivers ir tavęs prašys šalyje tų, kurie bus juos išvedę į nelaisvę, sakydami: ‘Mes nusidėjome ir elgėmės iškrypusiai, mes padarėme nedorybę’;'),
  (@b11, 8, 48, 'ir taip sugrįš pas tave visa savo širdimi ir visa savo siela šalyje savo priešų, kurie buvo juos išvedę į nelaisvę, ir melsis tau link savo šalies, kurią davei jų tėvams, link miesto, kurį esi išsirinkęs, ir link namų, kuriuos pastačiau tavo vardui;'),
  (@b11, 8, 49, 'tuomet išklausyk danguje, savo gyvenamoje vietoje, jų maldą ir prašymą ir paremk jų reikalą,'),
  (@b11, 8, 50, 'ir atleisk savo tautai, kuri prieš tave nusidėjo, ir visus jų nusižengimus, kuriais jie nusižengė prieš tave, ir suteik jiems pasigailėjimą akivaizdoje tų, kurie juos išvedė į nelaisvę, kad jie jų pasigailėtų;'),
  (@b11, 8, 51, 'nes jie yra tavo tauta ir tavo paveldas, kuriuos išvedei iš Egipto, iš geležies krosnies vidurio;'),
  (@b11, 8, 52, 'kad tavo akys būtų atvertos tavo tarno prašymui ir tavo tautos Izraelio prašymui, kad juos išklausytum visame tame, dėl ko jie šaukiasi tavęs.'),
  (@b11, 8, 53, 'Nes tu juos atskyrei iš visų žemės tautų tarpo būti tavo paveldu, kaip kalbėjai per savo tarno Mozės ranką, kai išvedei mūsų tėvus iš Egipto, o Viešpatie DIEVE“.'),
  (@b11, 8, 54, 'Ir buvo, kai Saliamonas baigė melstis VIEŠPAČIUI visa šita malda ir prašymu, jis atsikėlė nuo VIEŠPATIES aukuro priekio, nuo klūpojimo ant kelių išskėstomis rankomis į dangų.'),
  (@b11, 8, 55, 'Ir atsistojęs jis garsiu balsu palaimino visą Izraelio susirinkimą, sakydamas:'),
  (@b11, 8, 56, '„Tebūna palaimintas VIEŠPATS, kuris davė poilsį savo tautai Izraeliui pagal visa tai, ką buvo pažadėjęs; nepristigo nei vieno žodžio iš viso jo gerojo pažado, kurį jis kalbėjo per savo tarno Mozės ranką.'),
  (@b11, 8, 57, 'VIEŠPATS, mūsų Dievas, tebūna su mumis, kaip jis buvo su mūsų tėvais; tegul jis nepalieka ir neapleidžia mūsų;'),
  (@b11, 8, 58, 'kad palenktų mūsų širdis į save, idant vaikščiotume visais jo keliais ir laikytumėmės jo įsakymų, jo įstatų ir jo teismų, kuriuos jis įsakė mūsų tėvams.'),
  (@b11, 8, 59, 'Ir šitie mano žodžiai, kuriais prašiau VIEŠPATIES akivaizdoje, tebūna arti VIEŠPATIES, mūsų Dievo, dieną ir naktį, kad jis paremtų savo tarno reikalą ir savo tautos Izraelio reikalą visais laikais, kaip to prireiks;'),
  (@b11, 8, 60, 'kad vìsos žemės tautos žinotų, kad VIEŠPATS yra Dievas ir nėra kito.'),
  (@b11, 8, 61, 'Todėl tebūna jūsų širdis tobula su VIEŠPAČIU, mūsų Dievu, kad vaikščiotumėte pagal jo įstatus ir laikytumėtės jo įsakymų, kaip šią dieną“.'),
  (@b11, 8, 62, 'Ir karalius bei su juo visas Izraelis atnašavo auką VIEŠPATIES akivaizdoje.'),
  (@b11, 8, 63, 'Ir Saliamonas atnašavo taikos atnašų auką, kurią jis atnašavo VIEŠPAČIUI: dvidešimt du tūkstančius jaučių ir šimtą dvidešimt tūkstančių avių. Taip karalius ir visi Izraelio vaikai pašventė VIEŠPATIES namus.'),
  (@b11, 8, 64, 'Tą pačią dieną karalius pašventė vidurį kiemo, esančio prieš VIEŠPATIES namus; nes ten jis atnašavo deginamąsias atnašas, maisto atnašas ir taikos atnašų taukus; kadangi žalvarinis aukuras, esantis VIEŠPATIES akivaizdoje, buvo per mažas, kad sutalpintų deginamąsias atnašas, maisto atnašas ir taikos atnašų taukus.'),
  (@b11, 8, 65, 'Ir tuo laiku Saliamonas ir su juo visas Izraelis, didžiulis susirinkimas, nuo Hamato įėjimo iki Egipto upės šventė šventę VIEŠPATIES, mūsų Dievo, akivaizdoje septynias dienas ir septynias dienas – keturiolika dienų.'),
  (@b11, 8, 66, 'Aštuntąją dieną jis paleido tautą; ir jie palaimino karalių, ir nuėjo į savo palapines linksmi ir džiugia širdimi dėl viso gerumo, kurį VIEŠPATS padarė savo tarnui Dovydui ir savo tautai Izraeliui.'),
  (@b11, 9, 1, 'Ir Saliamonui baigus statyti VIEŠPATIES namus ir karaliaus namus, ir viską, ką Saliamonas troško padaryti,'),
  (@b11, 9, 2, 'įvyko, kad VIEŠPATS antrą kartą pasirodė Saliamonui, kaip jam buvo pasirodęs Gibeone.'),
  (@b11, 9, 3, 'Ir VIEŠPATS jam tarė: „Aš girdėjau tavo maldą ir tavo prašymą, kuriuos atlikai mano akivaizdoje; aš pašvenčiau šituos namus, kuriuos pastatei, kad ten amžiams padėčiau savo vardą; mano akys ir mano širdis bus ten nuolatos.'),
  (@b11, 9, 4, 'Ir jei vaikščiosi mano akivaizdoje, kaip vaikščiojo tavo tėvas Dovydas, dora širdimi ir tiesumu, kad darytumei pagal visa tai, ką tau įsakiau, ir laikysies mano įstatų ir mano teismų;'),
  (@b11, 9, 5, 'tada aš įtvirtinsiu tavo karalystės Izraeliui sostą amžiams, kaip pažadėjau tavo tėvui Dovydui, sakydamas: ‘Tau nepritrūks nei vieno vyro Izraelio soste’.'),
  (@b11, 9, 6, 'Bet jei iš tikrųjų jūs patys ar jūsų vaikai nusigręšite nuo sekimo paskui mane ir nesilaikysite mano įsakymų bei mano įstatų, kuriuos padėjau jūsų priešakyje, bet nuėję tarnausite kitiems dievams ir juos garbinsite,'),
  (@b11, 9, 7, 'tada iškirsiu Izraelį iš tos šalies, kurią jiems daviau; o šituos namus, kuriuos pašvenčiau savo vardui, numesiu šalin nuo savo akių; ir Izraelis bus patarle ir priežodžiu visų tautų tarpe.'),
  (@b11, 9, 8, 'O dėl šitų namų, kurie yra aukšti, kiekvienas pro juos praeinantis stebėsis ir švilpaus; ir jie sakys: ‘Kodėl VIEŠPATS taip padarė šitai šaliai ir šitiems namams?’'),
  (@b11, 9, 9, 'Ir atsakys: ‘Kadangi jie paliko VIEŠPATĮ, savo Dievą, kuris išvedė jų tėvus iš Egipto šalies, ir įsikibo į kitus dievus, ir garbino juos, ir jiems tarnavo; todėl VIEŠPATS atvedė ant jų visą tą nelaimę’“.'),
  (@b11, 9, 10, 'Ir pasibaigus dvidešimčiai metų, kai Saliamonas pastatė dvejus namus, VIEŠPATIES namus ir karaliaus namus'),
  (@b11, 9, 11, '(na, o Tyro karalius Hiramas aprūpino Saliamoną kedrų medžiais bei eglių medžiais ir auksu pagal visą jo norą), įvyko, kad karalius Saliamonas davė Hiramui dvidešimt miestų Galilėjos šalyje.'),
  (@b11, 9, 12, 'Ir išėjo Hiramas iš Tyro apžiūrėti miestų, kuriuos Saliamonas jam buvo davęs; ir jie jam nepatiko.'),
  (@b11, 9, 13, 'Ir jis tarė: „Kas tai per miestai, kuriuos man davei, mano broli?“ Ir juos pavadino Kabulo šalimi, iki šios dienos.'),
  (@b11, 9, 14, 'Ir Hiramas nusiuntė karaliui šimtą dvidešimt talentų aukso.'),
  (@b11, 9, 15, 'Ir šita yra priežastis rinkliavos, kurią pakėlė karalius Saliamonas; kad pastatytų VIEŠPATIES namus, savo paties namus, Milojų, Jeruzalės sieną, Hacorą, Megidą ir Gezerą.'),
  (@b11, 9, 16, 'Nes Egipto karalius faraonas buvo nuėjęs aukštyn, paėmęs Gezerą, jį sudeginęs ugnimi, išžudęs kanaaniečius, gyvenančius mieste, ir jį davęs kaip dovaną savo dukteriai, Saliamono žmonai.'),
  (@b11, 9, 17, 'Ir Saliamonas pastatė Gezerą, žemutinį Bet-Horoną,'),
  (@b11, 9, 18, 'Baalatą ir Tadmorą dykumoje, toje šalyje,'),
  (@b11, 9, 19, 'visus sandėlių miestus, kuriuos turėjo Saliamonas, miestus jo vežimams, miestus jo raiteliams ir tai, ką Saliamonas norėjo statyti Jeruzalėje, Libane ir visoje savo viešpatystės šalyje.'),
  (@b11, 9, 20, 'O visą liaudį, išlikusią iš amoritų, hetitų, perizų, hivų ir jebusiečių, kurie nebuvo iš Izraelio vaikų,'),
  (@b11, 9, 21, 'jų vaikus, kurie po jų buvo išlikę šalyje, kurių Izraelio vaikai taip pat nepajėgė visiškai sunaikinti, tuos Saliamonas apdėjo vergystės duokle iki šios dienos.'),
  (@b11, 9, 22, 'Tačiau iš Izraelio vaikų Saliamonas nedarė vergų; bet jie buvo karo vyrai, jo tarnai, jo kunigaikščiai, jo vadai, jo vežimų valdytojai ir jo raiteliai.'),
  (@b11, 9, 23, 'Šitie buvo vyriausieji iš pareigūnų, vadovavusių Saliamono darbui – penki šimtai penkiasdešimt, valdančių liaudį, atliekančią darbą.'),
  (@b11, 9, 24, 'Bet faraono duktė atėjo aukštyn iš Dovydo miesto į savo namus, kuriuos Saliamonas buvo jai pastatęs; tada jis pastatė Milą.'),
  (@b11, 9, 25, 'Ir tris kartus metuose Saliamonas atnašavo deginamąsias atnašas ir taikos atnašas ant aukuro, kurį pastatė VIEŠPAČIUI, ir jis degino smilkalus ant aukuro, esančio VIEŠPATIES akivaizdoje. Taip jis užbaigė namus.'),
  (@b11, 9, 26, 'Ir pastatė karalius Saliamonas laivyną Ecjon-Geberyje, esančiame prie Eloto, ant Raudonosios jūros kranto, Edomo šalyje.'),
  (@b11, 9, 27, 'Ir Hiramas pasiuntė į laivyną savo tarnus, laivininkus, išmanančius apie jūrą, su Saliamono tarnais.'),
  (@b11, 9, 28, 'Ir jie atvyko į Ofyrą ir iš ten atgabeno keturis šimtus dvidešimt talentų aukso ir atnešė jį karaliui Saliamonui.'),
  (@b11, 10, 1, 'Ir Šebos karalienė, išgirdusi garsą apie Saliamoną dėl VIEŠPATIES vardo, atvyko jo išmėginti sunkiais klausimais.'),
  (@b11, 10, 2, 'Ir ji atvyko į Jeruzalę su labai didele palyda, su kupranugariais, nešančiais kvepalus, labai daug aukso ir brangių akmenų; ir atvykusi pas Saliamoną ji kalbėjosi su juo apie viską, kas buvo jos širdyje.'),
  (@b11, 10, 3, 'O Saliamonas jai paaiškino visus jos klausimus; nieko nebuvo paslėpta karaliui, ko jis nebūtų jai paaiškinęs.'),
  (@b11, 10, 4, 'Ir kai Šebos karalienė pamatė visą Saliamono išmintį ir namus, kuriuos jis buvo pastatęs,'),
  (@b11, 10, 5, 'ir jo stalo valgius, jo tarnų sėdėjimą, jo tarnų patarnavimą, jų drabužius, jo taurininkus ir jo pakilimą, kuriuo jis ėjo aukštyn į VIEŠPATIES namus; ji neteko žado.'),
  (@b11, 10, 6, 'Ir ji tarė karaliui: „Kalbos, kurias girdėjau savo šalyje apie tavo darbus ir apie tavo išmintį, buvo tiesa.'),
  (@b11, 10, 7, 'Tačiau aš netikėjau tais žodžiais, kol neatvykau, ir mano akys to nepamatė; ir štai nei pusės man nebuvo pasakyta; tavo išmintis ir gerovė viršija garsą, kurį girdėjau.'),
  (@b11, 10, 8, 'Laimingi tavo žmonės, laimingi šitie tavo tarnai, kurie nuolat stovi tavo akivaizdoje ir girdi tavo išmintį.'),
  (@b11, 10, 9, 'Tebūna palaimintas VIEŠPATS, tavo Dievas, kuris gėrėjosi tavimi, kad pasodintų tave į Izraelio sostą; kadangi VIEŠPATS mylėjo Izraelį per amžius, todėl jis tave paskyrė karaliumi, kad vykdytum teismą ir teisingumą“.'),
  (@b11, 10, 10, 'Ir ji davė karaliui šimtą dvidešimt talentų aukso, didelę gausybę kvepalų ir brangiųjų akmenų; daugiau nebeatėjo tokia gausybė kvepalų, kaip šitie, kuriuos Šebos karalienė davė karaliui Saliamonui.'),
  (@b11, 10, 11, 'Taip pat Hiramo laivynas, kuris atgabeno auksą iš Ofyro, atgabeno iš Ofyro didelę gausą almugo medžių ir brangiųjų akmenų.'),
  (@b11, 10, 12, 'Ir padarė karalius iš almugo medžių stulpus VIEŠPATIES namams ir karaliaus namams, taip pat arfas ir psalterius giesmininkams; tokių almugo medžių nėra atėję nei matyta iki šios dienos.'),
  (@b11, 10, 13, 'Ir karalius Saliamonas davė Šebos karalienei viską, ko ji norėjo, ko ji prašė, neskaitant to, ką Saliamonas jai davė iš savo karališko dosnumo. Taip apsisukusi ji vyko į savo šalį, ji ir jos tarnai.'),
  (@b11, 10, 14, 'Na, o svoris aukso, kuris ateidavo Saliamonui per vienerius metus, buvo šeši šimtai šešiasdešimt šeši aukso talentai,'),
  (@b11, 10, 15, 'neskaitant to, ką jis turėjo iš prekybininkų, iš žolininkų pirklių prekybos, iš visų Arabijos karalių ir iš krašto valdytojų.'),
  (@b11, 10, 16, 'Ir karalius Saliamonas padarė du šimtus didžiųjų skydų iš kalto aukso; šeši šimtai šekelių aukso suėjo vienam skydui.'),
  (@b11, 10, 17, 'Ir jis padarė tris šimtus mažųjų skydų iš kalto aukso; trys svarai aukso suėjo vienam skydui; ir karalius juos sudėjo Libano miško namuose.'),
  (@b11, 10, 18, 'Karalius dar padarė didelį sostą iš dramblio kaulo ir jį padengė geriausiu auksu.'),
  (@b11, 10, 19, 'Sostas turėjo šešis laiptus, ir sosto viršus užpakalinėje dalyje buvo apvalus; ir atramos buvo abiejose sėdimos vietos pusėse, ir du liūtai stovėjo šalia atramų.'),
  (@b11, 10, 20, 'Ir dvylika liūtų stovėjo ant šešių laiptų, vienoje ir kitoje pusėje; jam lygaus nebuvo padaryta jokioje karalystėje.'),
  (@b11, 10, 21, 'Ir visi karaliaus Saliamono geriamieji indai buvo iš aukso, ir visi Libano miško namų indai buvo iš gryno aukso; nieko nebuvo iš sidabro: jis Saliamono dienomis buvo laikomas nieku.'),
  (@b11, 10, 22, 'Nes karalius turėjo jūroje Taršišo laivyną su Hiramo laivynu; kartą per trejus metus atplaukdavo Taršišo laivynas, atgabendamas aukso ir sidabro, dramblio kaulo, beždžionių ir povų.'),
  (@b11, 10, 23, 'Taip karalius Saliamonas pralenkė visus žemės karalius turtais ir išmintimi.'),
  (@b11, 10, 24, 'Ir visa žemė siekė Saliamono, kad išgirstų jo išminties, kurią Dievas buvo įdėjęs į jo širdį.'),
  (@b11, 10, 25, 'Ir jie nešė kiekvienas savo dovaną: sidabro indų ir aukso indų, rūbų, ginklų, kvepalų, žirgų ir mulų, kasmetinę normą.'),
  (@b11, 10, 26, 'Ir Saliamonas surinko vežimus ir raitelius; jis turėjo tūkstantį keturis šimtus vežimų ir dvylika tūkstančių raitelių, kuriuos jis paskyrė miestuose vežimams ir pas karalių Jeruzalėje.'),
  (@b11, 10, 27, 'Ir karalius padarė, kad sidabro Jeruzalėje buvo kaip akmenų, o kedrų padarė, kad būtų, kaip gausybė slėnyje esančių sikomorų.'),
  (@b11, 10, 28, 'Ir Saliamonas buvo parsigabenęs žirgų iš Egipto ir lininių siūlų; karaliaus pirkliai gaudavo lininių siūlų už kainą.'),
  (@b11, 10, 29, 'O vežimas ateidavo aukštyn ir išeidavo iš Egipto už šešis šimtus šekelių sidabro, o žirgas už šimtą penkiasdešimt; ir taip jie savais būdais išgabendavo juos visiems hetitų karaliams ir Sirijos karaliams.'),
  (@b11, 11, 1, 'Bet karalius Saliamonas mylėjo daug svetimšalių moterų kartu su faraono dukterimi: moabietes, amonietes, edomites, sidonietes ir hetites moteris;'),
  (@b11, 11, 2, 'iš tautų, apie kurias VIEŠPATS pasakė Izraelio vaikams: „Neįeikite pas jas ir jos teneįeina pas jus; nes jos tikrai nukreips jūsų širdį sekti paskui jų dievus“; prie jų Saliamonas prilipo su meile.'),
  (@b11, 11, 3, 'Jis turėjo septynis šimtus žmonų, kunigaikštienių, ir tris šimtus sugulovių; ir jo žmonos nukreipė jo širdį.'),
  (@b11, 11, 4, 'Nes kai Saliamonas paseno, atsitiko, kad jo žmonos nukreipė jo širdį paskui kitus dievus; ir jo širdis nebuvo tobula su VIEŠPAČIU, jo Dievu, kaip buvo jo tėvo Dovydo širdis.'),
  (@b11, 11, 5, 'Nes Saliamonas nusekė paskui sidoniečių deivę Astoretę ir amoniečių bjaurybę Milkomą.'),
  (@b11, 11, 6, 'Ir Saliamonas darė pikta VIEŠPATIES akyse ir nėjo paskui VIEŠPATĮ pilnai, kaip jo tėvas Dovydas.'),
  (@b11, 11, 7, 'Tada Saliamonas pastatė aukštumą Moabo bjaurybei Chemošui, kalvoje, esančioje prieš Jeruzalę, ir Amono vaikų bjaurybei Molechui.'),
  (@b11, 11, 8, 'Ir taip jis padarė visoms savo svetimšalėms žmonoms, kurios degino smilkalus ir aukojo savo dievams.'),
  (@b11, 11, 9, 'Ir VIEŠPATS supyko ant Saliamono, kadangi jo širdis buvo nusisukusi nuo VIEŠPATIES, Izraelio Dievo, kuris du kartus jam buvo pasirodęs,'),
  (@b11, 11, 10, 'ir buvo jam apie tai įsakęs, kad jis neitų paskui kitus dievus; bet jis nesilaikė to, ką VIEŠPATS įsakė.'),
  (@b11, 11, 11, 'Todėl VIEŠPATS tarė Saliamonui: „Kadangi tai yra tavo padaryta, ir tu nesilaikei mano sandoros bei mano įstatų, kuriuos tau įsakiau, tai aš tikrai išplėšiu iš tavęs karalystę ir duosiu ją tavo tarnui.'),
  (@b11, 11, 12, 'Tačiau to nedarysiu tavo dienomis dėl tavo tėvo Dovydo; bet išplėšiu ją iš tavo sūnaus rankos.'),
  (@b11, 11, 13, 'Vis dėlto visos karalystės neišplėšiu; bet vieną gentį duosiu tavo sūnui dėl mano tarno Dovydo ir dėl Jeruzalės, kurią esu išsirinkęs“.'),
  (@b11, 11, 14, 'Ir VIEŠPATS sukurstė Saliamonui priešininką, edomitą Hadadą; jis buvo iš karaliaus sėklos Edome.'),
  (@b11, 11, 15, 'Nes kai Dovydas buvo Edome ir kariuomenės vadas Joabas buvo nuėjęs aukštyn laidoti užmuštųjų po to, kai jis buvo išžudęs visus iš vyriškosios lyties Edome'),
  (@b11, 11, 16, '(nes šešis mėnesius ten pasiliko Joabas su visu Izraeliu, kol iškirto visus iš vyriškosios lyties Edome);'),
  (@b11, 11, 17, 'įvyko, kad Hadadas pabėgo, jis pats ir su juo kai kurie edomitai iš jo tėvo tarnų, kad įeitų į Egiptą; Hadadas buvo dar mažas vaikas.'),
  (@b11, 11, 18, 'Ir pakilę iš Midjano, jie atvyko į Paraną; ir paėmę su savimi vyrų iš Parano, jie atvyko į Egiptą, pas Egipto karalių faraoną; kuris jam davė namus, paskyrė jam maistą ir jam davė žemės.'),
  (@b11, 11, 19, 'Ir Hadadas rado didelį palankumą faraono akyse taip, kad šis jam davė į žmonas savo paties žmonos seserį, karalienės Tachpenesės seserį.'),
  (@b11, 11, 20, 'O Tachpenesės sesuo jam pagimdė jo sūnų Genubatą, kurį Tachpenesė nujunkė faraono namuose; ir Genubatas buvo faraono namuose tarp faraono sūnų.'),
  (@b11, 11, 21, 'Ir kai Hadadas išgirdo Egipte, kad Dovydas užmigo prie savo tėvų ir kad kariuomenės vadas Joabas miręs, Hadadas tarė faraonui: „Leisk man išeiti, kad eičiau į savo šalį“.'),
  (@b11, 11, 22, 'Tada faraonas jam tarė: „Bet ko tau trūksta pas mane, kad štai tu sieki eiti į savo šalį?“ O jis atsakė: „Nieko; bet vis tiek leisk man eiti“.'),
  (@b11, 11, 23, 'Ir Dievas jam sukurstė kitą priešininką, Eljados sūnų Rezoną, kuris pabėgo nuo savo viešpaties Hadadezerio, Cobos karaliaus;'),
  (@b11, 11, 24, 'ir surinkęs sau vyrų, jis tapo būrio vadu, kai Dovydas žudė juos iš Cobos; ir jie nuėjo į Damaską, apsigyveno jame ir karaliavo Damaske.'),
  (@b11, 11, 25, 'Ir jis buvo Izraeliui priešininkas per visas Saliamono dienas, neskaitant pikto, kurį darė Hadadas; jis bjaurėjosi Izraeliu ir karaliavo Sirijai.'),
  (@b11, 11, 26, 'Ir Nebato sūnus Jeroboamas, efraimas iš Ceredos, Saliamono tarnas, kurio motinos vardas buvo Ceruva, našlė, būtent jis pakėlė ranką prieš karalių.'),
  (@b11, 11, 27, 'O šita buvo priežastis, dėl ko jis pakėlė ranką prieš karalių: Saliamonas statė Milojų ir taisė savo tėvo Dovydo miesto spragas.'),
  (@b11, 11, 28, 'O tas vyras Jeroboamas buvo galingas narsuolis; ir Saliamonas, pamatęs, kad tas jaunuolis stropus, jį paskyrė visų Juozapo namų pareigų prižiūrėtoju.'),
  (@b11, 11, 29, 'Ir tuo metu, kai Jeroboamas išėjo iš Jeruzalės, įvyko, kad jį užtiko kelyje šilonietis pranašas Ahija; o jis buvo apsirengęs nauju rūbu; ir juodu buvo vieni ant lauko;'),
  (@b11, 11, 30, 'ir Ahija nutvėrė naują rūbą, kuris buvo ant jo, ir jį suplėšė į dvylika gabalų;'),
  (@b11, 11, 31, 'ir jis tarė Jeroboamui: „Pasiimk dešimt dalių; nes taip sako VIEŠPATS, Izraelio Dievas: ‘Štai aš išplėšiu karalystę iš Saliamono rankos ir tau duosiu dešimt genčių'),
  (@b11, 11, 32, '(bet jis turės vieną gentį dėl mano tarno Dovydo ir dėl Jeruzalės – miesto, kurį esu išsirinkęs iš visų Izraelio genčių);'),
  (@b11, 11, 33, 'dėl to, kad jie paliko mane ir garbino sidoniečių deivę Astoretę, moabiečių dievą Chemošą bei Amono vaikų dievą Milkomą ir nevaikščiojo mano keliais, kad darytų tai, kas teisinga mano akyse, ir kad laikytųsi mano įstatų ir teismų, kaip jo tėvas Dovydas.'),
  (@b11, 11, 34, 'Tačiau aš neatimsiu iš jo rankos visos karalystės; bet paskirsiu jį kunigaikščiu per visas jo gyvenimo dienas dėl mano tarno Dovydo, kurį išsirinkau, kadangi jis laikėsi mano įsakymų ir įstatų;'),
  (@b11, 11, 35, 'bet aš atimsiu karalystę iš jo sūnaus rankos ir ją tau duosiu, tai yra dešimt genčių.'),
  (@b11, 11, 36, 'O jo sūnui duosiu vieną gentį, kad mano tarnas Dovydas nuolat turėtų žiburį mano akivaizdoje Jeruzalėje, mieste, kurį sau išsirinkau, kad ten padėčiau savo vardą.'),
  (@b11, 11, 37, 'Ir tave paimsiu, ir tu karaliausi pagal visa tai, ko geidžia tavo siela, ir būsi Izraelio karalius.'),
  (@b11, 11, 38, 'Ir bus, jei klausysi visko, ką tau įsakysiu, ir vaikščiosi mano keliais, ir darysi, kas teisinga mano akyse, laikydamasis mano įstatų ir įsakymų, kaip darė mano tarnas Dovydas; tai aš būsiu su tavimi ir pastatysiu tau tikrus namus, kaip pastačiau Dovydui, ir duosiu tau Izraelį.'),
  (@b11, 11, 39, 'Ir dėl to aš ištiksiu Dovydo sėklą, tačiau ne visam laikui“.'),
  (@b11, 11, 40, 'Todėl Saliamonas siekė nužudyti Jeroboamą. O Jeroboamas pakilęs pabėgo į Egiptą pas Egipto karalių Šišaką ir buvo Egipte iki Saliamono mirties.'),
  (@b11, 11, 41, 'O kiti Saliamono darbai ir visa, ką jis darė, ir jo išmintis, argi jie nėra užrašyti Saliamono darbų knygoje?'),
  (@b11, 11, 42, 'Ir laiko, kuriuo Saliamonas karaliavo visam Izraeliui Jeruzalėje, buvo keturiasdešimt metų.'),
  (@b11, 11, 43, 'Ir Saliamonas užmigo prie savo tėvų ir buvo palaidotas savo tėvo Dovydo mieste; o jo vietoje karaliavo jo sūnus Rehoboamas.'),
  (@b11, 12, 1, 'Ir Rehoboamas nuvyko į Šechemą; nes į Šechemą buvo atėjęs visas Izraelis, kad padarytų jį karaliumi.'),
  (@b11, 12, 2, 'Ir įvyko, kai Nebato sūnus Jeroboamas, kuris tebebuvo Egipte, išgirdo apie tai (nes jis buvo pabėgęs nuo karaliaus Saliamono akivaizdos, ir Jeroboamas apsigyveno Egipte),'),
  (@b11, 12, 3, 'tuomet jie siuntė ir pašaukė jį. Ir Jeroboamas ir visas Izraelio susirinkimas atvyko ir kalbėjo Rehoboamui, sakydami:'),
  (@b11, 12, 4, '„Tavo tėvas padarė mūsų jungą sunkų; taigi tu dabar palengvink savo tėvo sunkią tarnystę ir jo sunkų jungą, kurį jis mums uždėjo, ir mes tau tarnausime“.'),
  (@b11, 12, 5, 'O jis jiems tarė: „Išeikite trims dienoms, paskui sugrįžkite pas mane“. Ir tauta išėjo.'),
  (@b11, 12, 6, 'Ir karalius Rehoboamas tarėsi su senesniaisiais, kurie stovėdavo priešais jo tėvą Saliamoną, kai jis dar buvo gyvas, ir tarė: „Kaip jūs patariate, kad atsakyčiau šitai tautai?“'),
  (@b11, 12, 7, 'Ir jie jam kalbėjo, sakydami: „Jei šią dieną būsi tarnas šitai tautai, jiems tarnausi, jiems atsakysi ir jiems kalbėsi gerus žodžius, tada jie visados bus tavo tarnai“.'),
  (@b11, 12, 8, 'Bet jis atmetė senųjų patarimą, kurį jie buvo jam davę, ir tarėsi su jaunuoliais, kurie buvo užaugę su juo ir kurie stovėjo priešais jį;'),
  (@b11, 12, 9, 'ir jis tarė jiems: „Ką patariate, kad atsakytume šitai tautai, kurie man kalbėjo, sakydami: ‘Palengvink jungą, kurį mums uždėjo tavo tėvas’?“'),
  (@b11, 12, 10, 'Ir tie jaunuoliai, kurie buvo užaugę su juo, jam kalbėjo, sakydami: „Taip sakyk šitai tautai, kurie tau kalbėjo, sakydami: ‘Tavo tėvas padarė mūsų jungą sunkų, bet tu jį mums palengvink’; – taip jiems kalbėk: ‘Mano mažasis pirštas bus storesnis už mano tėvo strėnas.'),
  (@b11, 12, 11, 'O dabar, kadangi mano tėvas jus užkrovė sunkiu jungu, tai aš pridėsiu prie jūsų jungo; mano tėvas jus baudė botagais, o aš jus bausiu skorpionais’“.'),
  (@b11, 12, 12, 'Taigi trečią dieną Jeroboamas ir visa tauta atėjo pas Rehoboamą, kaip karalius buvo paskyręs, sakydamas: „Sugrįžkite pas mane trečią dieną“.'),
  (@b11, 12, 13, 'Ir karalius atsakė tautai šiurkščiai, atmetęs senųjų patarimą, kurį jie buvo jam davę;'),
  (@b11, 12, 14, 'ir jiems kalbėjo pagal jaunuolių patarimą, sakydamas: „Mano tėvas padarė jūsų jungą sunkų, o aš pridėsiu prie jūsų jungo; mano tėvas jus baudė botagais, o aš jus bausiu skorpionais“.'),
  (@b11, 12, 15, 'Taigi karalius nepaklausė tautos; nes tas dalykas buvo iš VIEŠPATIES, kad jis įvykdytų savo pasakymą, kurį VIEŠPATS kalbėjo per šilonietį Ahiją Nebato sūnui Jeroboamui.'),
  (@b11, 12, 16, 'Taigi kai visas Izraelis pamatė, kad karalius jų neišklausė, tauta atsakė karaliui, sakydami: „Kokią gi dalį mes turime Dovyde? Mes neturime paveldo Jesės sūnuje; į savo palapines, o Izraeli; dabar žiūrėk savo namų, Dovydai“. Taip Izraelis nuėjo į savo palapines.'),
  (@b11, 12, 17, 'Bet Izraelio vaikams, gyvenantiems Judos miestuose, karaliavo Rehoboamas.'),
  (@b11, 12, 18, 'Tada karalius Rehoboamas pasiuntė Adoramą, vadovaujantį duoklei; bet visas Izraelis jį užmėtė akmenimis, kad jis mirė. Todėl karalius Rehoboamas skubiai įlipo į savo vežimą, kad pabėgtų į Jeruzalę.'),
  (@b11, 12, 19, 'Taip Izraelis maištavo prieš Dovydo namus iki šios dienos.'),
  (@b11, 12, 20, 'Ir įvyko, kai visas Izraelis išgirdo, kad Jeroboamas buvo sugrįžęs, pasiuntę jie pašaukė jį į susirinkimą ir paskyrė jį viso Izraelio karaliumi; niekas nesekė Dovydo namais, o vien tik Judos gentis.'),
  (@b11, 12, 21, 'Ir Rehoboamas, atėjęs į Jeruzalę, surinko visus Judos namus su Benjamino gentimi, šimtą aštuoniasdešimt tūkstančių rinktinių vyrų, kurie buvo kariai, kad kovotų prieš Izraelio namus, kad sugrąžintų Saliamono sūnui Rehoboamui karalystę.'),
  (@b11, 12, 22, 'Bet Dievo žodis atėjo Dievo vyrui Šemajai, sakydamas:'),
  (@b11, 12, 23, '„Kalbėk Saliamono sūnui Rehoboamui, Judos karaliui, ir visiems Judos ir Benjamino namams, ir likusiai tautai, sakydamas:'),
  (@b11, 12, 24, 'Taip sako VIEŠPATS: ‘Neikite aukštyn nei nekariaukite prieš savo brolius Izraelio vaikus; kiekvienas grįžkite į savo namus; nes tas dalykas yra iš manęs“. Taigi jie paklausė VIEŠPATIES žodžio ir išėjo, kad sugrįžtų pagal VIEŠPATIES žodį.'),
  (@b11, 12, 25, 'Tada Jeroboamas pastatė Šechemą Efraimo kalne ir ten apsigyveno; ir iš ten išėjęs, pastatė Penuelį.'),
  (@b11, 12, 26, 'Ir Jeroboamas tarė savo širdyje: „Dabar karalystė sugrįš Dovydo namams.'),
  (@b11, 12, 27, 'Jei šita tauta eis aukštyn atlikti aukos VIEŠPATIES namuose Jeruzalėje, tada šitos tautos širdis sugrįš pas jų viešpatį, tai yra pas Judos karalių Rehoboamą, ir jie nužudys mane, ir sugrįš pas Judos karalių Rehoboamą“.'),
  (@b11, 12, 28, 'Dėl to pasitarė karalius ir padarė du aukso veršius, ir jiems tarė: „Jums yra per daug eiti aukštyn į Jeruzalę; štai Izraeli, tavo dievai, kurie tave išvedė aukštyn iš Egipto šalies“.'),
  (@b11, 12, 29, 'Ir jis pastatė vieną Bet-Elyje, o kitą jis pastatė Dane.'),
  (@b11, 12, 30, 'Ir tas dalykas tapo nuodėme; nes tauta ėjo garbinti priešais vieną jų, būtent iki Dano.'),
  (@b11, 12, 31, 'Ir jis padarė aukštumų namus ir paskyrė kunigus iš tautos prasčiausiųjų, kurie nebuvo iš Levio sūnų.'),
  (@b11, 12, 32, 'Ir aštuntojo mėnesio penkioliktąją to mėnesio dieną Jeroboamas įvedė šventę, panašią į tą šventę, kuri yra Judoje, ir jis atnašavo ant aukuro. Taip jis darė Bet-Elyje, aukodamas veršiams, kuriuos buvo padaręs; ir jis pastatė Bet-Elyje kunigus aukštumų, kurias buvo padaręs.'),
  (@b11, 12, 33, 'Taigi penkioliktąją aštuntojo mėnesio dieną, tai yra to mėnesio, kurį jis buvo sumanęs savo širdyje, jis atnašavo ant aukuro, kurį buvo padaręs Bet-Elyje; ir įvedė šventę Izraelio vaikams; ir jis atnašavo ant aukuro ir degino smilkalus.'),
  (@b11, 13, 1, 'Ir štai iš Judos į Bet-Elį atėjo Dievo vyras pagal VIEŠPATIES žodį; o Jeroboamas stovėjo prie aukuro, kad degintų smilkalus.'),
  (@b11, 13, 2, 'Ir jis šaukė prieš tą aukurą VIEŠPATIES žodžiu, ir tarė: „O aukure, aukure, taip sako VIEŠPATS: ‘Štai Dovydo namams gims vaikas, vardu Jozijas; ir jis atnašaus ant tavęs aukštumų kunigus, kurie degina ant tavęs smilkalus, ir žmonių kaulai bus sudeginti ant tavęs’“.'),
  (@b11, 13, 3, 'Ir tą pačią dieną jis davė ženklą, sakydamas: „Tai yra ženklas, kurį VIEŠPATS kalbėjo: ‘Štai aukuras suskils, ir išbyrės ant jo esantys pelenai“.'),
  (@b11, 13, 4, 'Ir įvyko, kai karalius Jeroboamas išgirdo Dievo vyro pasakymą, kuris šaukė prieš Bet-Elio aukurą, jis ištiesė ranką nuo aukuro, sakydamas: „Sučiupkite jį“. Ir jo ranka, kurią jis buvo prieš jį ištiesęs, nudžiūvo taip, kad jis negalėjo pritraukti jos atgal prie savęs.'),
  (@b11, 13, 5, 'Aukuras irgi suskilo, ir pelenai išbyrėjo iš aukuro pagal ženklą, kurį Dievo vyras davė pagal VIEŠPATIES žodį.'),
  (@b11, 13, 6, 'Ir karalius atsiliepdamas tarė Dievo vyrui: „Maldauk dabar VIEŠPATIES, savo Dievo, veido ir melskis už mane, kad mano ranka būtų man atstatyta“. Ir Dievo vyras maldavo VIEŠPATIES, ir karaliaus ranka buvo jam atstatyta ir pasidarė, kokia buvo anksčiau.'),
  (@b11, 13, 7, 'Ir karalius tarė Dievo vyrui: „Ateik su manimi į namus ir pasistiprink, aš tau duosiu atlyginimą“.'),
  (@b11, 13, 8, 'O Dievo vyras tarė karaliui: „Jei man duotum pusę savo namų, aš neįeičiau su tavimi nei nevalgyčiau duonos ir negerčiau vandens šitoje vietoje;'),
  (@b11, 13, 9, 'nes taip man buvo įsakyta VIEŠPATIES žodžiu, sakant: ‘Nevalgyk duonos nei negerk vandens, nei negrįžk tuo pačiu keliu, kuriuo atėjai’“.'),
  (@b11, 13, 10, 'Taip jis nuėjo kitu keliu ir negrįžo tuo keliu, kuriuo atėjo į Bet-Elį.'),
  (@b11, 13, 11, 'Na, o Bet-Elyje gyveno senas pranašas; ir atėję jo sūnūs jam papasakojo visus darbus, kuriuos tą dieną padarė Dievo vyras Bet-Elyje; taip pat žodžius, kuriuos jis kalbėjo karaliui, juos jie pasakė savo tėvui.'),
  (@b11, 13, 12, 'Ir jų tėvas jiems tarė: „Kuriuo keliu jis nuėjo?“ Nes jo sūnūs matė, kuriuo keliu nuėjo Dievo vyras, kuris buvo atėjęs iš Judos.'),
  (@b11, 13, 13, 'Ir jis tarė savo sūnums: „Pabalnokite man asilą“. Taigi jie pabalnojo jam asilą; ir jis jojo ant jo,'),
  (@b11, 13, 14, 'ir nuvyko paskui Dievo vyrą, ir rado jį sėdintį po ąžuolu; ir jis tarė jam: „Ar tu esi tas Dievo vyras, kuris atėjai iš Judos?“ Ir jis tarė: „Aš“.'),
  (@b11, 13, 15, 'Tada jis jam tarė: „Eik su manimi į namus ir užvalgyk duonos“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b11, 13, 16, 'O jis tarė: „Aš negaliu grįžti su tavimi nei įeiti su tavimi; ir nevalgysiu duonos nei negersiu vandens su tavimi šitoje vietoje;'),
  (@b11, 13, 17, 'nes man buvo pasakyta VIEŠPATIES žodžiu: ‘Tu ten nei duonos valgysi, nei vandens gersi, nei grįši, kad eitum tuo keliu, kuriuo atėjai’“.'),
  (@b11, 13, 18, 'Jis jam tarė: „Aš irgi esu pranašas, kaip ir tu; ir angelas man kalbėjo VIEŠPATIES žodžiu, sakydamas: ‘Atvesk jį atgal su savimi į savo namus, kad jis valgytų duonos ir gertų vandens’“. Bet šis jam melavo.'),
  (@b11, 13, 19, 'Taigi jis grįžo su juo, valgė duonos jo namuose ir gėrė vandens.'),
  (@b11, 13, 20, 'Ir jiems sėdint prie stalo atsitiko, kad VIEŠPATIES žodis atėjo tam pranašui, kuris buvo jį sugrąžinęs;'),
  (@b11, 13, 21, 'ir jis šaukė Dievo vyrui, kuris buvo atėjęs iš Judos, sakydamas: „Taip sako VIEŠPATS: ‘Kadangi tu nepaklusai VIEŠPATIES burnai ir nesilaikei to įsakymo, kurį VIEŠPATS, tavo Dievas, tau įsakė,'),
  (@b11, 13, 22, 'bet sugrįžai, valgei duonos ir gėrei vandens toje vietoje, apie kurią VIEŠPATS tau kalbėjo: ‘Nevalgyk duonos ir negerk vandens; tavo lavonas neįeis į tavo tėvų kapą’“.'),
  (@b11, 13, 23, 'Jam pavalgius duonos ir atsigėrus įvyko, kad jis pabalnojo asilą jam, tai yra tam pranašui, kurį buvo sugrąžinęs.'),
  (@b11, 13, 24, 'Ir jam nuėjus liūtas jį sutiko kelyje ir jį nužudė; ir jo lavonas buvo pamestas ant kelio, o asilas stovėjo šalia jo, liūtas irgi stovėjo šalia lavono.'),
  (@b11, 13, 25, 'Ir štai žmonės ėjo pro šalį ir pamatė lavoną, pamestą ant kelio, ir liūtą, stovintį šalia lavono; ir atėję jie tai papasakojo mieste, kuriame gyveno senasis pranašas.'),
  (@b11, 13, 26, 'Ir pranašas, kuris buvo jį sugrąžinęs nuo kelio, tai išgirdęs tarė: „Tai Dievo vyras, kuris buvo nepaklusnus VIEŠPATIES žodžiui; todėl VIEŠPATS jį atidavė liūtui, kuris jį sudraskė ir nužudė pagal VIEŠPATIES žodį, kurį jis jam kalbėjo“.'),
  (@b11, 13, 27, 'Ir jis kalbėjo savo sūnums, sakydamas: „Pabalnokite man asilą“. Ir jie pabalnojo.'),
  (@b11, 13, 28, 'Ir jis nuvyko ir rado jo lavoną, pamestą ant kelio, ir asilą bei liūtą, stovinčius šalia lavono; liūtas nebuvo to lavono suėdęs nei asilo sudraskęs.'),
  (@b11, 13, 29, 'Ir pranašas, pakėlęs Dievo vyro lavoną, uždėjo jį ant asilo ir pargabeno jį; ir senasis pranašas atėjo į miestą, kad jį apraudotų ir palaidotų.'),
  (@b11, 13, 30, 'Ir jis paguldė jo lavoną savo paties kape; ir jie apraudojo jį, sakydami: „Ak, mano broli!“'),
  (@b11, 13, 31, 'Ir įvyko, kad jį palaidojęs jis tarė savo sūnums, sakydamas: „Kai numirsiu, palaidokite mane kape, kuriame palaidotas tas Dievo vyras; šalia jo kaulų paguldykite mano kaulus;'),
  (@b11, 13, 32, 'nes tikrai įvyks tas pasakymas, kurį jis šaukė VIEŠPATIES žodžiu prieš tą aukurą Bet-Elyje ir prieš visus Samarijos miestuose esančius aukštumų namus“.'),
  (@b11, 13, 33, 'Po viso to dalyko Jeroboamas nesugrįžo nuo savo pikto kelio, bet vėl paskyrė aukštumų kunigų iš tautos prasčiausiųjų; kas norėdavo, tą jis įšventindavo, ir tas tapdavo vienu iš aukštumų kunigų.'),
  (@b11, 13, 34, 'Ir šitas dalykas tapo nuodėme Jeroboamo namams, kad jie būtų iškirsti ir išnaikinti nuo žemės paviršiaus.'),
  (@b11, 14, 1, 'Tuo metu susirgo Jeroboamo sūnus Abija.'),
  (@b11, 14, 2, 'Ir Jeroboamas tarė savo žmonai: „Kelkis, meldžiu tave, persirenk, kad neatpažintų, jog tu esi Jeroboamo žmona; ir nueik į Šilojų; štai ten yra pranašas Ahija, kuris man sakė, kad aš turėsiu būti šitai tautai karaliumi.'),
  (@b11, 14, 3, 'Ir paimk su savimi dešimt kepalų, pyragaičių ir medaus ąsotį ir nueik pas jį; jis tau pasakys, kas atsitiks vaikui“.'),
  (@b11, 14, 4, 'Ir Jeroboamo žmona taip padarė, atsikėlė ir nuėjo į Šilojų, ir atėjo į Ahijos namus. Bet Ahija negalėjo matyti; nes jo akys buvo pastyrusios dėl senatvės.'),
  (@b11, 14, 5, 'Ir VIEŠPATS pasakė Ahijai: „Štai ateina Jeroboamo žmona teirautis tavęs apie savo sūnų; nes jis serga; taip ir taip jai kalbėk; nes kai ji įeis, įvyks, kad ji dėsis esanti kita moteris“.'),
  (@b11, 14, 6, 'Ir buvo, kai Ahija išgirdo jos kojų garsą, jai įeinant pro duris, jis tarė: „Įeik, Jeroboamo žmona; kodėl gi tu dediesi esanti kita? Nes aš pasiųstas pas tave su sunkia žinia.'),
  (@b11, 14, 7, 'Eik, sakyk Jeroboamui: ‘Taip sako VIEŠPATS, Izraelio Dievas: Kadangi išaukštinau tave iš tautos tarpo ir paskyriau tave kunigaikščiu savo tautai Izraeliui,'),
  (@b11, 14, 8, 'ir atplėšiau karalystę nuo Dovydo namų ir ją tau daviau; tačiau tu nebuvai kaip mano tarnas Dovydas, kuris laikėsi mano įsakymų ir kuris sekė paskui mane visa savo širdimi, kad darytų tik tai, kas yra teisinga mano akyse;'),
  (@b11, 14, 9, 'bet darei pikta labiau už visus, kurie buvo pirma tavęs; nes nuėjęs tu pasidarei kitų dievų ir nulietų atvaizdų, kad kurstytum mano pyktį, ir mane numetei sau už nugaros;'),
  (@b11, 14, 10, 'todėl štai aš užleisiu nelaimę ant Jeroboamo namų ir iškirsiu iš Jeroboamo tą, kuris šlapinasi į sieną, ir tą, kuris užrakintas ir paliktas Izraelyje, ir pašalinsiu Jeroboamo namų likutį, kaip žmogus pašalina mėšlą, kol jo visai nebelieka.'),
  (@b11, 14, 11, 'Kas iš Jeroboamo mirs mieste, tą ės šunys; o kas mirs ant lauko, tą les dangaus skrajūnai; nes VIEŠPATS tai kalbėjo.'),
  (@b11, 14, 12, 'Taigi kelkis, eik į savo namus; ir tavo kojoms įžengus į miestą, vaikas mirs.'),
  (@b11, 14, 13, 'Ir visas Izraelis jį apraudos ir palaidos; nes tik jis iš Jeroboamo ateis į kapą, nes jame rasta šiek tiek gero VIEŠPAČIUI, Izraelio Dievui, Jeroboamo namuose.'),
  (@b11, 14, 14, 'Be to, VIEŠPATS sau pakels Izraeliui karalių, kuris iškirs Jeroboamo namus tą dieną; ir ką? Netgi dabar.'),
  (@b11, 14, 15, 'Nes VIEŠPATS ištiks Izraelį, kaip nendrė siūbuojama vandenyje, ir jis išraus Izraelį iš šitos geros šalies, kurią jis davė jų tėvams, ir juos išsklaidys anapus upės, kadangi jie padarė sau giraičių, kurstydami VIEŠPATIES pyktį.'),
  (@b11, 14, 16, 'Ir jis paliks Izraelį dėl nuodėmių Jeroboamo, kuris nusidėjo ir kuris skatino Izraelį nusidėti’“.'),
  (@b11, 14, 17, 'Ir pakilusi Jeroboamo žmona išėjo ir atėjo į Tircą; o jai atėjus prie durų slenksčio, vaikas mirė;'),
  (@b11, 14, 18, 'ir jie palaidojo jį; ir visas Izraelis jį apraudojo pagal VIEŠPATIES žodį, kurį jis kalbėjo per savo tarno pranašo Ahijos ranką.'),
  (@b11, 14, 19, 'O kiti Jeroboamo darbai, kaip jis kariavo ir kaip karaliavo, štai jie yra surašyti Izraelio karalių kronikų knygoje.'),
  (@b11, 14, 20, 'Ir dienų, kuriomis Jeroboamas karaliavo, buvo dvidešimt dveji metai; ir jis užmigo pas savo tėvus, o jo sūnus Nadabas karaliavo jo vietoje.'),
  (@b11, 14, 21, 'O Saliamono sūnus Rehoboamas karaliavo Judoje. Rehoboamas buvo keturiasdešimt vienerių metų, kai pradėjo karaliauti, ir karaliavo septyniolika metų Jeruzalėje, mieste, kurį VIEŠPATS išsirinko iš visų Izraelio genčių, kad ten padėtų savo vardą. O jo motinos vardas buvo Naama, amonietė.'),
  (@b11, 14, 22, 'Ir Juda darė pikta VIEŠPATIES akyse, ir jie sukėlė jam pavydą savo nuodėmėmis, kurias jie darė, labiau negu visa, ką buvo darę jų tėvai.'),
  (@b11, 14, 23, 'Nes jie taip pat statė sau aukštumas ir atvaizdus, ir giraites ant kiekvienos aukštos kalvos ir po kiekvienu žaliuojančiu medžiu.'),
  (@b11, 14, 24, 'Taip pat šalyje buvo ir sodomitų; ir jie darė pagal visas bjaurystes tų tautų, kurias VIEŠPATS išvarė Izraelio vaikų priešakyje.'),
  (@b11, 14, 25, 'Ir penktaisiais karaliaus Rehoboamo metais įvyko, kad Egipto karalius Šišakas atėjo aukštyn prieš Jeruzalę;'),
  (@b11, 14, 26, 'ir jis atėmė VIEŠPATIES namų lobius ir karaliaus namų lobius; jis viską pasiėmė; ir jis pasiėmė visus aukso skydus, kuriuos Saliamonas buvo padaręs.'),
  (@b11, 14, 27, 'Ir karalius Rehoboamas padarė jų vietoje žalvarinius skydus ir pavedė juos į rankas sargybos vyriausiųjų, saugojusių karaliaus namų duris.'),
  (@b11, 14, 28, 'Ir buvo, kai karalius eidavo į VIEŠPATIES namus, sargyba juos nešdavo ir parnešdavo atgal į sargybos kambarį.'),
  (@b11, 14, 29, 'Na, o kiti Rehoboamo darbai ir visa, ką jis darė, argi jie nėra surašyti Judos karalių kronikų knygoje?'),
  (@b11, 14, 30, 'Ir karas tarp Rehoboamo ir Jeroboamo buvo per visas jų dienas.'),
  (@b11, 14, 31, 'Ir Rehoboamas užmigo pas savo tėvus ir buvo palaidotas pas savo tėvus Dovydo mieste. O jo motinos vardas buvo Naama, amonietė. O jo sūnus Abijamas karaliavo jo vietoje.'),
  (@b11, 15, 1, 'Na, o aštuonioliktaisiais karaliaus Jeroboamo, Nebato sūnaus, metais Abijamas karaliavo Judai.'),
  (@b11, 15, 2, 'Trejus metus jis karaliavo Jeruzalėje. O jo motinos vardas buvo Maaka, Abišalomo duktė.'),
  (@b11, 15, 3, 'Ir jis vaikščiojo visose savo tėvo nuodėmėse, kurias jis darė pirma jo; ir jo širdis nebuvo tobula su VIEŠPAČIU, savo Dievu, kaip jo tėvo Dovydo širdis.'),
  (@b11, 15, 4, 'Tačiau dėl Dovydo VIEŠPATS, jo Dievas, jam davė žibintą Jeruzalėje, kad pastatytų karaliumi jo sūnų po jo ir įtvirtintų Jeruzalę;'),
  (@b11, 15, 5, 'kadangi Dovydas darė tai, kas buvo teisinga VIEŠPATIES akyse, ir nenukrypo nuo nieko, ką jis jam įsakė, per visas savo gyvenimo dienas, išskyrus hetito Ūrijo atvejį.'),
  (@b11, 15, 6, 'Ir karas tarp Rehoboamo ir Jeroboamo buvo per visas jo gyvenimo dienas.'),
  (@b11, 15, 7, 'Na, o kiti Abijamo darbai ir visa, ką jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje? Ir tarp Abijamo ir Jeroboamo buvo karas.'),
  (@b11, 15, 8, 'Ir Abijamas užmigo prie savo tėvų; ir jį palaidojo Dovydo mieste; o jo sūnus Asa karaliavo jo vietoje.'),
  (@b11, 15, 9, 'Ir dvidešimtaisiais Izraelio karaliaus Jeroboamo metais Asa karaliavo Judai.'),
  (@b11, 15, 10, 'Ir keturiasdešimt vienerius metus jis karaliavo Jeruzalėje. O jo motinos vardas buvo Maaka, Abišalomo duktė.'),
  (@b11, 15, 11, 'Ir Asa darė tai, kas buvo teisinga VIEŠPATIES akyse, kaip darė jo tėvas Dovydas.'),
  (@b11, 15, 12, 'Ir jis pašalino iš šalies sodomitus ir pašalino visus stabus, kuriuos buvo padarę jo tėvai.'),
  (@b11, 15, 13, 'Ir taip pat savo motiną Maaką jis pašalino, kad ji nebūtų karalienė, nes ji buvo padariusi stabą giraitėje; ir Asa sunaikino jos stabą ir jį sudegino prie Kidrono upelio.'),
  (@b11, 15, 14, 'Bet aukštumos nebuvo pašalintos; tačiau Asos širdis buvo tobula su VIEŠPAČIU per visas jo dienas.'),
  (@b11, 15, 15, 'Ir jis įnešė į VIEŠPATIES namus savo tėvo pašvęstus dalykus ir savo paties pašvęstus dalykus: sidabrą, auksą ir indus.'),
  (@b11, 15, 16, 'Ir karas tarp Asos ir Izraelio karaliaus Baašos buvo per visas jų dienas.'),
  (@b11, 15, 17, 'Ir Izraelio karalius Baaša ėjo aukštyn prieš Judą ir pastatė Ramą, kad niekam neleistų išeiti ar įeiti pas Judos karalių Asą.'),
  (@b11, 15, 18, 'Tada Asa paėmė visą sidabrą ir auksą, likusius VIEŠPATIES namų lobynuose bei karaliaus namų lobynuose, ir juos padavė į savo tarnų rankas; ir karalius Asa juos pasiuntė pas Ben-Hadadą, sūnų Tabrimono, sūnų Hezjono, Sirijos karaliaus, gyvenančio Damaske, sakydamas:'),
  (@b11, 15, 19, '„Sąjunga yra tarp manęs ir tavęs, tarp mano tėvo ir tavo tėvo; štai tau siunčiu sidabro ir aukso dovaną; ateik ir sulaužyk savo sąjungą su Izraelio karaliumi Baaša, kad jis atsitrauktų nuo manęs“.'),
  (@b11, 15, 20, 'Taigi Ben-Hadadas paklausė karaliaus Asos ir pasiuntė savo turimų kariuomenių vadus prieš Izraelio miestus ir sumušė Ijoną, Daną, Abel-Bet-Maaką ir visą Kinerotą su visa Naftalio šalimi.'),
  (@b11, 15, 21, 'Ir įvyko, kad Baaša tai išgirdęs liovėsi statyti Ramą ir gyveno Tircoje.'),
  (@b11, 15, 22, 'Tada karalius Asa paskelbė po visą Judą; niekam nebuvo daroma išimčių; ir jie paėmė Ramos akmenis ir jos rąstus, kuriais Baaša statė; ir jais karalius Asa pastatė Benjamino Gebą bei Micpą.'),
  (@b11, 15, 23, 'Visi kiti Asos darbai, visa jo galybė, visa, ką jis padarė, ir jo pastatyti miestai, argi jie nėra užrašyti Judos karalių kronikų knygoje? Tačiau jo senatvėje jo kojos buvo nesveikos.'),
  (@b11, 15, 24, 'Ir Asa užmigo prie savo tėvų ir buvo palaidotas prie savo tėvų savo tėvo Dovydo mieste; o jo sūnus Jehozapatas karaliavo jo vietoje.'),
  (@b11, 15, 25, 'Ir Jeroboamo sūnus Nadabas pradėjo karaliauti Izraeliui antraisiais Judos karaliaus Asos metais ir karaliavo Izraeliui dvejus metus.'),
  (@b11, 15, 26, 'Ir jis darė pikta VIEŠPATIES akyse ir vaikščiojo savo tėvo keliu bei jo nuodėmėje, kuria jis skatino Izraelį nusidėti.'),
  (@b11, 15, 27, 'Ir Ahijos sūnus Baaša iš Isacharo namų surengė prieš jį sąmokslą; ir Baaša jį sumušė Gibetone, priklausančiame filistinams; nes Nadabas ir visas Izraelis apgulė Gibetoną.'),
  (@b11, 15, 28, 'Būtent trečiaisiais Judos karaliaus Asos metais Baaša jį nužudė ir karaliavo jo vietoje.'),
  (@b11, 15, 29, 'Ir kai jis karaliavo, atsitiko kad jis išmušė visus Jeroboamo namus; jis nepaliko Jeroboamui nei vieno kvėpuojančio, kol juos sunaikino, pagal VIEŠPATIES pasakymą, kurį jis kalbėjo per savo tarną šilonietį Ahiją;'),
  (@b11, 15, 30, 'dėl Jeroboamo nuodėmių, kuriomis jis nusidėjo ir kuriomis jis skatino Izraelį nusidėti, savo kurstymu, kuriuo jis kurstė VIEŠPATIES, Izraelio Dievo, pyktį.'),
  (@b11, 15, 31, 'Na, o kiti Nadabo darbai ir visa, ką jis darė, argi jie nėra surašyti Izraelio karalių kronikų knygoje?'),
  (@b11, 15, 32, 'Ir karas tarp Asos ir Izraelio karaliaus Baašos buvo per visas jų dienas.'),
  (@b11, 15, 33, 'Trečiaisiais Judos karaliaus Asos metais Ahijos sūnus Baaša pradėjo karaliauti visam Izraeliui Tircoje, ir karaliavo dvidešimt ketverius metus.'),
  (@b11, 15, 34, 'Ir jis darė pikta VIEŠPATIES akyse ir vaikščiojo Jeroboamo keliu ir jo nuodėmėje, kuria jis skatino Izraelį nusidėti.'),
  (@b11, 16, 1, 'Tada VIEŠPATIES žodis atėjo Hananio sūnui Jehuvui prieš Baašą, sakydamas:'),
  (@b11, 16, 2, '„Kadangi tave išaukštinau iš dulkių ir padariau tave kunigaikščiu savo tautai Izraeliui; o tu vaikščiojai Jeroboamo keliu ir darei, kad mano tauta Izraelis nusidėtų, kad kurstytum mano pyktį jų nuodėmėmis;'),
  (@b11, 16, 3, 'štai aš atimsiu Baašos palikuonis bei jo namų palikuonis; ir padarysiu tavo namus kaip Nebato sūnaus Jeroboamo namus.'),
  (@b11, 16, 4, 'Kas iš Baašos mirs mieste, tą ės šunys; o kas iš jo mirs laukuose, tą les oro skrajūnai“.'),
  (@b11, 16, 5, 'Na, o kiti Baašos darbai, ką jis darė, ir jo galybė, argi jie nėra surašyti Izraelio karalių kronikų knygoje?'),
  (@b11, 16, 6, 'Taigi Baaša užmigo prie savo tėvų ir buvo palaidotas Tircoje; o jo sūnus Ela karaliavo jo vietoje.'),
  (@b11, 16, 7, 'Taip pat per Hananio sūnaus, pranašo Jehuvo ranką, VIEŠPATIES žodis atėjo prieš Baašą ir prieš jo namus dėl viso to pikto, kurį jis darė VIEŠPATIES akyse, kurstydamas jo pyktį savo rankų darbais, būdamas kaip Jeroboamo namai; ir dėl to, kad jis jį nužudė.'),
  (@b11, 16, 8, 'Dvidešimt šeštaisiais Judos karaliaus Asos metais Baašos sūnus Ela pradėjo karaliauti Izraeliui Tircoje ir karaliavo dvejus metus.'),
  (@b11, 16, 9, 'Ir jo tarnas Zimris, pusės jo vežimų vadas, surengė prieš jį sąmokslą, kai jis buvo Tircoje, gerdamas iki nusigėrimo namuose Arcos, jo namų ūkvedžio, Tircoje.'),
  (@b11, 16, 10, 'Ir Zimris įėjo, jį sumušė ir nužudė jį dvidešimt septintais Judos karaliaus Asos metais ir karaliavo jo vietoje.'),
  (@b11, 16, 11, 'Ir įvyko, kad pradėjęs karaliauti, kai tik jis atsisėdo į jo sostą, jis išžudė visus Baašos namus; jis jam nepaliko nei vieno, kuris šlapinasi į sieną, nei jo giminaičių, nei jo draugų.'),
  (@b11, 16, 12, 'Taip Zimris sunaikino visus Baašos namus pagal VIEŠPATIES žodį, kurį jis kalbėjo prieš Baašą per pranašą Jehuvą,'),
  (@b11, 16, 13, 'dėl visų Baašos nuodėmių ir jo sūnaus Elos nuodėmių, kuriomis jie nusidėjo ir kuriomis jie skatino Izraelį nusidėti, kurstydami VIEŠPATIES, Izraelio Dievo, pyktį savo tuštybėmis.'),
  (@b11, 16, 14, 'Na, o kiti Elos darbai ir visa, ką jis darė, argi jie nėra surašyti Izraelio karalių kronikų knygoje?'),
  (@b11, 16, 15, 'Dvidešimt septintaisiais Judos karaliaus Asos metais Zimris karaliavo septynias dienas Tircoje. Ir tauta stovyklavo prieš Gibetoną, priklausantį filistinams.'),
  (@b11, 16, 16, 'Ir stovyklaujanti tauta išgirdo sakant: „Zimris surengė sąmokslą ir taip pat užmušė karalių“; todėl tą dieną visas Izraelis stovykloje paskyrė kariuomenės vadą Omrį Izraelio karaliumi.'),
  (@b11, 16, 17, 'Ir Omris ir su juo visas Izraelis ėjo aukštyn iš Gibetono ir jie apgulė Tircą.'),
  (@b11, 16, 18, 'Ir įvyko, kad Zimris matydamas, jog miestas paimtas, įėjo į karaliaus namų rūmus ir, padegęs ugnimi viršum savęs karaliaus namus, mirė'),
  (@b11, 16, 19, 'dėl savo nuodėmių, kuriomis nusidėjo, darydamas pikta VIEŠPATIES akyse, vaikščiodamas Jeroboamo keliu ir jo nuodėmėje, kurią jis darė, skatindamas Izraelį nusidėti.'),
  (@b11, 16, 20, 'Na, o kiti Zimrio darbai ir jo išdavystė, kurią jis įvykdė, argi jie nėra surašyti Izraelio karalių kronikų knygoje?'),
  (@b11, 16, 21, 'Tada Izraelio tauta pasidalijo į dvi dalis: pusė tautos sekė Ginato sūnumi Tibniu, kad padarytų jį karaliumi; o kita pusė sekė Omriu.'),
  (@b11, 16, 22, 'Bet tauta, sekusi paskui Omrį, nugalėjo tautą, sekusią paskui Ginato sūnų Tibnį; taigi Tibnis mirė, o Omris karaliavo.'),
  (@b11, 16, 23, 'Trisdešimt pirmaisiais Judos karaliaus Asos metais Omris pradėjo karaliauti Izraeliui ir karaliavo dvylika metų; Tircoje jis karaliavo šešerius metus.'),
  (@b11, 16, 24, 'Ir jis nupirko iš Šemerio Samarijos kalvą už du talentus sidabro, pastatė ant kalvos, ir jo pastatytą miestą praminė Samarijos kalvos savininko Šemerio vardu.'),
  (@b11, 16, 25, 'Bet Omris darė pikta VIEŠPATIES akyse ir elgėsi blogiau už visus buvusius prieš jį.'),
  (@b11, 16, 26, 'Nes jis vaikščiojo visu Nebato sūnaus Jeroboamo keliu ir jo nuodėmėje, kuria jis skatino Izraelį nusidėti, kad kurstytų VIEŠPATIES, Izraelio Dievo, pyktį savo tuštybėmis.'),
  (@b11, 16, 27, 'Na, o kiti Omrio darbai, kuriuos jis darė, ir jo galybė, kurią jis parodė, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b11, 16, 28, 'Taigi Omris užmigo prie savo tėvų ir buvo palaidotas Samarijoje; o jo sūnus Ahabas karaliavo jo vietoje.'),
  (@b11, 16, 29, 'Ir trisdešimt aštuntaisiais Judos karaliaus Asos metais Omrio sūnus Ahabas pradėjo karaliauti Izraeliui; ir Omrio sūnus Ahabas karaliavo Izraeliui Samarijoje dvidešimt dvejus metus.'),
  (@b11, 16, 30, 'Ir Omrio sūnus Ahabas darė pikta VIEŠPATIES akyse labiau už visus buvusius prieš jį.'),
  (@b11, 16, 31, 'Ir tarsi jam būtų nedidelis dalykas vaikščioti Nebato sūnaus Jeroboamo nuodėmėse, įvyko tai, kad jis ėmė į žmonas sidoniečių karaliaus Etbaalo dukterį Jezabelę ir nuėjęs tarnavo Baalui, ir jį garbino.'),
  (@b11, 16, 32, 'Ir jis pastatė aukurą Baalui Baalo namuose, kuriuos buvo pastatęs Samarijoje.'),
  (@b11, 16, 33, 'Ir Ahabas įrengė giraitę; ir, kad kurstytų VIEŠPATIES, Izraelio Dievo, pyktį, Ahabas darė daugiau negu visi prieš jį buvę Izraelio karaliai.'),
  (@b11, 16, 34, 'Jo dienomis bet-elietis Hielis pastatė Jerichą; jis padėjo jo pamatus ant savo pirmagimio Abiramo ir įstatė jo vartus ant savo jauniausiojo sūnaus Segubo, pagal VIEŠPATIES žodį, kurį jis kalbėjo per Nūno sūnų Jozuę.'),
  (@b11, 17, 1, 'Ir tišbietis Elijas, iš Gileado gyventojų, tarė Ahabui: „Kaip gyvas VIEŠPATS, Izraelio Dievas, kurio akivaizdoje stoviu, nebus per šituos metus nei rasos, nei lietaus, bet tik pagal mano žodį“.'),
  (@b11, 17, 2, 'Ir jam atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b11, 17, 3, '„Eik iš čia, pasisuk į rytus ir pasislėpk prie Kerito upelio, esančio prieš Jordaną.'),
  (@b11, 17, 4, 'Ir bus, kad gersi iš upelio; o varnams įsakiau ten maitinti tave“.'),
  (@b11, 17, 5, 'Taigi jis nuėjo ir padarė pagal VIEŠPATIES žodį; nes jis nuėjo ir apsigyveno prie Kerito upelio, esančio prieš Jordaną.'),
  (@b11, 17, 6, 'Ir varnai jam atnešdavo duonos bei mėsos ryte ir duonos bei mėsos vakare; ir jis atsigerdavo iš upelio.'),
  (@b11, 17, 7, 'Ir po kurio laiko atsitiko, kad upelis išdžiūvo, nes nebuvo lietaus šalyje.'),
  (@b11, 17, 8, 'Ir jam atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b11, 17, 9, '„Kelkis, eik į Sareptą, priklausančią Sidonui, ir ten apsigyvenk; štai aš ten įsakiau našlei pramaitinti tave“.'),
  (@b11, 17, 10, 'Taigi atsikėlęs jis nuėjo į Sareptą. Ir jam atėjus prie miesto vartų, štai ten buvo našlė, renkanti pagalius; ir jis sušuko jai ir tarė: „Atnešk man, meldžiu tave, truputį vandens inde, kad atsigerčiau“.'),
  (@b11, 17, 11, 'Ir jai einant jo atnešti, jis jai šūktelėjo ir tarė: „Atnešk man, meldžiu tave, duonos kąsnį savo rankoje“.'),
  (@b11, 17, 12, 'Ir ji tarė: „Kaip gyvas VIEŠPATS, tavo Dievas, aš neturiu pyrago, tik saują miltų statinėje ir truputį aliejaus ąsotyje; ir štai aš pasirenku pora pagalių, kad parėjusi tai paruoščiau sau ir savo sūnui, kad tai suvalgytume ir mirtume“.'),
  (@b11, 17, 13, 'O Elijas jai tarė: „Nebijok; eik ir padaryk, kaip kalbėjai; bet man pirma padaryk iš to mažą pyragėlį ir man atnešk, o po to padaryk sau ir savo sūnui.'),
  (@b11, 17, 14, 'Nes taip sako VIEŠPATS, Izraelio Dievas: ‘Miltų statinė neišseks ir aliejaus ąsotis neištuštės iki tos dienos, kai VIEŠPATS pasiųs lietų į žemę“.'),
  (@b11, 17, 15, 'Ir nuėjusi ji padarė pagal Elijo pasakymą; ir ji, ir jis, ir jos namai valgė daug dienų.'),
  (@b11, 17, 16, 'Ir miltų statinė neišseko, ir aliejaus ąsotis neištuštėjo pagal VIEŠPATIES žodį, kurį jis kalbėjo per Eliją.'),
  (@b11, 17, 17, 'O po tų dalykų atsitiko, kad susirgo tos moters, namų šeimininkės, sūnus; ir jo liga buvo tokia sunki, kad jame nebeliko kvapo.'),
  (@b11, 17, 18, 'Ir ji tarė Elijui: „Kas man darbo su tavimi, o Dievo vyre? Ar tu atėjai pas mane, kad mano nuodėmes primintum ir mano sūnų nužudytum?“'),
  (@b11, 17, 19, 'O jis jai tarė: „Duok man savo sūnų“. Ir jį paėmęs iš jos glėbio, jis užnešė jį į palėpę, kurioje jis gyveno, ir paguldė jį ant savo patalo.'),
  (@b11, 17, 20, 'Ir šaukdamasis VIEŠPATIES jis tarė: „O VIEŠPATIE, mano Dieve, argi ir tai našlei, pas kurią laikinai apsigyvenau, tu atnešei pikta, nužudydamas jos sūnų?“'),
  (@b11, 17, 21, 'Ir jis tris kartus išsitiesė viršum vaiko ir šaukdamasis VIEŠPATIES, tarė: „O VIEŠPATIE, mano Dieve, meldžiu tave, tesugrįžta šito vaiko siela į jį“.'),
  (@b11, 17, 22, 'Ir VIEŠPATS išklausė Elijo maldą; ir vaiko siela į jį sugrįžo, ir jis atgijo.'),
  (@b11, 17, 23, 'Ir Elijas paėmęs vaiką nunešė jį žemyn iš kambario į namus ir atidavė jį jo motinai; ir Elijas tarė: „Žiūrėk, tavo sūnus gyvas“.'),
  (@b11, 17, 24, 'Ir ta moteris tarė Elijui: „Dabar iš to žinau, kad tu esi Dievo vyras ir kad VIEŠPATIES žodis tavo burnoje yra tiesa“.'),
  (@b11, 18, 1, 'Ir po daugelio dienų įvyko, kad trečiaisiais metais Elijui atėjo VIEŠPATIES žodis, sakydamas: „Eik, pasirodyk Ahabui; aš siųsiu lietų į žemę“.'),
  (@b11, 18, 2, 'Ir Elijas ėjo pasirodyti Ahabui. O Samarijoje buvo smarkus badas.'),
  (@b11, 18, 3, 'Ir Ahabas pašaukė Abdiją, jo namų valdytoją (na, o Abdijas labai bijojo VIEŠPATIES;'),
  (@b11, 18, 4, 'nes Jezabelei iškertant VIEŠPATIES pranašus, Abdijas paėmė šimtą pranašų ir juos paslėpė po penkiasdešimt oloje, ir juos maitino duona bei vandeniu).'),
  (@b11, 18, 5, 'Ir Ahabas tarė Abdijui: „Eik per šalį prie visų vandens šaltinių ir visų upelių; gal rasime žolės, kad išlaikytume gyvus žirgus bei mulus, kad neprarastume visų gyvulių“.'),
  (@b11, 18, 6, 'Taigi jie pasidalijo tarpusavyje šalį, kad ją pereitų: Ahabas ėjo atskirai vienu keliu, o Abdijas ėjo atskirai kitu keliu.'),
  (@b11, 18, 7, 'Ir Abdijui esant kelyje, štai jį pasitiko Elijas; ir jį atpažinęs jis parpuolė veidu žemyn ir tarė: „Ar tai tu esi tas, mano viešpats Elijas?“'),
  (@b11, 18, 8, 'O jis jam atsakė: „Aš; eik, sakyk savo viešpačiui: ‘Štai Elijas yra čia’“.'),
  (@b11, 18, 9, 'Ir jis tarė: „Kuo nusidėjau, kad nori atiduoti savo tarną į Ahabo rankas, kad mane nužudytų?'),
  (@b11, 18, 10, 'Kaip gyvas VIEŠPATS, tavo Dievas, nėra tautos ar karalystės, kur mano viešpats nebūtų siuntęs tavęs ieškoti; o kai sakė: ‘Jo čia nėra’, jis prisaikdindavo tą karalystę ir tautą, kad tavęs nerado.'),
  (@b11, 18, 11, 'O dabar tu sakai: ‘Eik, sakyk savo viešpačiui: Štai Elijas yra čia’.'),
  (@b11, 18, 12, 'Ir vos tik man nuo tavęs nuėjus, atsitiks, kad VIEŠPATIES Dvasia tave nuneš, kur aš nežinau; o man atėjus pranešti Ahabui ir jam tavęs neradus, jis užmuš mane; bet aš, tavo tarnas, bijau VIEŠPATIES nuo pat savo jaunystės.'),
  (@b11, 18, 13, 'Argi nebuvo pranešta mano viešpačiui, ką padariau, Jezabelei žudant VIEŠPATIES pranašus, kaip aš paslėpiau šimtą vyrų iš VIEŠPATIES pranašų, po penkiasdešimt oloje, ir juos maitinau duona bei vandeniu?'),
  (@b11, 18, 14, 'O dabar tu sakai: ‘Eik, sakyk savo viešpačiui: Štai Elijas yra čia’; jis mane užmuš“.'),
  (@b11, 18, 15, 'Ir Elijas tarė: „Kaip gyvas kariuomenių VIEŠPATS, kurio akivaizdoje stoviu, tikrai šiandien jam pasirodysiu“.'),
  (@b11, 18, 16, 'Taigi Abdijas nuėjo Ahabo pasitikti ir jam pranešė; ir Ahabas ėjo Elijo pasitikti.'),
  (@b11, 18, 17, 'Ir įvyko, kad Ahabas pamatęs Eliją jam tarė: „Ar tai tu, kuris drumsti Izraelį?“'),
  (@b11, 18, 18, 'O jis atsakė: „Ne aš drumsčiau Izraelį; bet tu ir tavo tėvo namai tuo, kad palikote VIEŠPATIES įsakymus, ir tu nuėjai paskui Baalus.'),
  (@b11, 18, 19, 'Taigi dabar pasiuntęs surink visą Izraelį pas mane ant Karmelio kalno ir keturis šimtus penkiasdešimt Baalo pranašų, ir keturis šimtus giraičių pranašų, valgančių prie Jezabelės stalo“.'),
  (@b11, 18, 20, 'Taigi Ahabas siuntė pas visus Izraelio vaikus ir surinko pranašus ant Karmelio kalno.'),
  (@b11, 18, 21, 'Ir priėjęs prie visos tautos, Elijas tarė: „Kaip ilgai šlubuosite tarp dviejų pažiūrų? Jei VIEŠPATS yra Dievas, sekite paskui jį; bet jei Baalas, tada sekite paskui jį“. Ir tauta jam neatsakė nei žodžio.'),
  (@b11, 18, 22, 'Tada Elijas tarė tautai: „Aš vienas išlikau VIEŠPATIES pranašas; bet Baalo pranašų yra keturi šimtai penkiasdešimt vyrų.'),
  (@b11, 18, 23, 'Taigi tegul mums duoda du jaučius; ir tegul jie pasirenka vieną jautį, supjausto jį į gabalus ir tepadeda jį ant malkų, bet tegul nepakuria po juo ugnies; ir aš paruošiu kitą jautį, uždėsiu jį ant malkų, bet nepakursiu po juo ugnies;'),
  (@b11, 18, 24, 'ir jūs šaukitės savo dievų vardo, o aš šauksiuosi VIEŠPATIES vardo; ir tas Dievas, kuris atsakys ugnimi, tas tebus Dievas“. Ir visa tauta atsakydama tarė: „Gerai pasakyta“.'),
  (@b11, 18, 25, 'Ir Elijas tarė Baalo pranašams: „Išsirinkite sau vieną jautį ir jį paruoškite pirma; nes jūsų yra daug; ir šaukitės savo dievų vardo, bet nepakurkite po juo ugnies“.'),
  (@b11, 18, 26, 'Ir paėmę jautį, kuris jiems buvo duotas, ir jį paruošę, jie šaukėsi Baalo vardo nuo ryto iki vidudienio, sakydami: „O Baalai, išgirsk mus“. Bet nebuvo balso nei atsakančiojo. Ir jie šokinėjo ant padaryto aukuro.'),
  (@b11, 18, 27, 'Ir vidudienį įvyko, kad Elijas, tyčiodamasis iš jų, tarė: „Šaukite garsiai; juk jis dievas; gal jis kalbasi ar užsiėmęs, ar kelionėje, arba gal jis miega ir turi būti pažadintas“.'),
  (@b11, 18, 28, 'Ir jie garsiai šaukė ir pagal savo būdą pjaustė save peiliais ir lancetais, kol kraujas ištryško ant jų.'),
  (@b11, 18, 29, 'Ir įvyko, kad praėjus vidudieniui ir jiems pranašavus iki vakarinės aukos atnašavimo meto, nebuvo nei balso, nei atsakančiojo, nei atkreipiančio dėmesį.'),
  (@b11, 18, 30, 'Ir Elijas tarė visai tautai: „Ateikite prie manęs“. Ir visa tauta priartėjo prie jo. Ir jis sutaisė VIEŠPATIES aukurą, kuris buvo sudaužytas.'),
  (@b11, 18, 31, 'Ir Elijas paėmė dvylika akmenų, pagal skaičių genčių sūnų Jokūbo, kuriam atėjo VIEŠPATIES žodis, sakydamas: „Tavo vardas bus Izraelis“;'),
  (@b11, 18, 32, 'ir jis pastatė iš tų akmenų aukurą VIEŠPATIES vardu; ir padarė aplink tą aukurą apkasą tokio dydžio, į kurį tilptų du saikai sėklos.'),
  (@b11, 18, 33, 'Ir išklojęs malkas, jis supjaustė jautį į gabalus ir uždėjo jį ant malkų, ir tarė: „Pripildykite keturias statines vandens ir užpilkite tai ant deginamosios aukos ir ant malkų“.'),
  (@b11, 18, 34, 'Ir jis tarė: „Padarykite tai antrą kartą“. Ir jie tai padarė antrą kartą. Ir jis tarė: „Darykite tai trečią kartą“. Ir jie tai padarė trečią kartą.'),
  (@b11, 18, 35, 'Ir vanduo tekėjo aplinkui aukurą; jis ir apkasą pripildė vandeniu.'),
  (@b11, 18, 36, 'Ir įvyko, kad vakarinės aukos atnašavimo metu pranašas Elijas prisiartino ir tarė: „VIEŠPATIE, Abraomo, Izaoko ir Izraelio Dieve, tebūna šią dieną žinoma, kad tu esi Dievas Izraelyje ir kad aš esu tavo tarnas, ir kad tavo žodžiu padariau visus šiuos dalykus.'),
  (@b11, 18, 37, 'Išgirsk mane, o VIEŠPATIE, išgirsk mane, kad šita tauta žinotų, kad tu esi VIEŠPATS Dievas ir kad tu vėl atgręžei jų širdis“.'),
  (@b11, 18, 38, 'Tada nukrito VIEŠPATIES ugnis ir prarijo deginamąją auką ir malkas, ir akmenis, ir dulkes, ir sulaižė apkase buvusį vandenį.'),
  (@b11, 18, 39, 'Ir visa tauta tai pamačiusi parpuolė veidais žemyn; ir jie tarė: „VIEŠPATS, jis yra Dievas; VIEŠPATS, jis yra Dievas“.'),
  (@b11, 18, 40, 'Ir Elijas jiems tarė: „Sučiupkite Baalo pranašus; nei vienas iš jų tenepabėga“. Ir jie sučiupo juos; o Elijas juos nuvedė žemyn prie Kišono upelio ir ten juos nužudė.'),
  (@b11, 18, 41, 'Ir Elijas tarė Ahabui: „Eik aukštyn, valgyk ir gerk; nes girdėti lietaus gausybė“.'),
  (@b11, 18, 42, 'Taip Ahabas nuėjo aukštyn valgyti ir gerti. O Elijas nuėjo aukštyn į Karmelio viršūnę; ir nusilenkė prie žemės ir padėjo veidą tarp kelių,'),
  (@b11, 18, 43, 'ir tarė savo tarnui: „Eik dabar aukštyn, pažiūrėk jūros link“. Ir jis užlipęs ir pažiūrėjęs tarė: „Nieko nėra“. O jis tarė: „Vėl eik septynis kartus“.'),
  (@b11, 18, 44, 'Ir įvyko, kad septintąjį kartą jis tarė: „Štai debesėlis kaip žmogaus delnas kyla nuo jūros“. Ir jis tarė: „Eik aukštyn, sakyk Ahabui: ‘Pakinkyk savo vežimą ir leiskis žemyn, kad lietus tavęs nesulaikytų’“.'),
  (@b11, 18, 45, 'Ir tuo tarpu įvyko, kad dangus buvo juodas nuo debesų ir vėjo, ir buvo smarkus lietus. Ir Ahabas važiuodamas vyko į Jezreelį.'),
  (@b11, 18, 46, 'Ir VIEŠPATIES ranka buvo ant Elijo; ir jis susijuosė strėnas ir bėgo Ahabo priekyje link Jezreelio įėjimo.'),
  (@b11, 19, 1, 'Ir Ahabas papasakojo Jezabelei viską, ką padarė Elijas, ir kaip jis išžudė kalaviju visus pranašus.'),
  (@b11, 19, 2, 'Tada Jezabelė siuntė pasiuntinį pas Eliją, sakydama: „Tegul dievai man padaro taip ir dar daugiau, jei rytoj apie šitą laiką nepadarysiu tavo gyvybei taip, kaip vieno iš jų gyvybei“.'),
  (@b11, 19, 3, 'Ir tai pamatęs jis atsikėlė ir nuėjo, kad išgelbėtų savo gyvybę, ir atėjęs į Judai priklausančią Beer-Šebą, jis ten paliko savo tarną.'),
  (@b11, 19, 4, 'Bet jis pats ėjo į dykumą dienos kelionę ir atėjęs atsisėdo po kadagiu; ir jis prašė sau, kad mirtų; ir tarė: „Gana; dabar, o VIEŠPATIE, paimk mano gyvybę; nes aš nesu geresnis už savo tėvus“.'),
  (@b11, 19, 5, 'Ir jam atsigulus ir užmigus po kadagiu, štai angelas palietė jį ir jam tarė: „Kelkis, valgyk“.'),
  (@b11, 19, 6, 'Ir jis pažiūrėjo, ir štai prie jo galvos buvo ant žarijų iškeptas pyragas ir ąsotis vandens. Ir pavalgęs ir atsigėręs jis vėl atsigulė.'),
  (@b11, 19, 7, 'Ir VIEŠPATIES angelas atėjo dar antrą kartą ir jį palietęs tarė: „Kelkis, valgyk; kadangi kelionė tau per ilga“.'),
  (@b11, 19, 8, 'Ir atsikėlęs jis pavalgė ir atsigėrė, ir to valgio stiprumu ėjo keturiasdešimt dienų ir keturiasdešimt naktų iki Dievo kalno Horebo.'),
  (@b11, 19, 9, 'Ir ten jis įėjo į olą ir ten apsinakvojo; ir štai VIEŠPATIES žodis jam atėjo ir jam tarė: „Ką čia veiki, Elijau?“'),
  (@b11, 19, 10, 'O jis tarė: „Aš buvau labai pavydus dėl VIEŠPATIES, kariuomenių Dievo; nes Izraelio vaikai paliko tavo sandorą, nugriovė tavo aukurus ir išžudė kalaviju tavo pranašus; o aš vienas teišlikau; ir jie ieško mano gyvybės, kad ją atimtų“.'),
  (@b11, 19, 11, 'Ir jis tarė: „Išeik ir atsistok ant kalno VIEŠPATIES akivaizdoje“. Ir štai VIEŠPATS praėjo, ir didelis bei stiprus vėjas ardė kalnus ir trupino uolas į gabalus VIEŠPATIES akivaizdoje; bet VIEŠPATIES nebuvo tame vėjyje; o po šito vėjo – žemės drebėjimas; bet VIEŠPATIES nebuvo tame žemės drebėjime;'),
  (@b11, 19, 12, 'o po žemės drebėjimo – ugnis; bet VIEŠPATIES nebuvo toje ugnyje; o po ugnies – tykus silpnas balsas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b11, 19, 13, 'Ir buvo, kad jį išgirdęs Elijas apsivyniojo veidą mantija ir išėjęs atsistojo olos įėjime. Ir štai jam atėjo balsas ir tarė: „Ką čia veiki, Elijau?“'),
  (@b11, 19, 14, 'Ir jis tarė: „Aš buvau labai pavydus dėl VIEŠPATIES, kariuomenių Dievo; nes Izraelio vaikai paliko tavo sandorą, nugriovė tavo aukurus ir išžudė kalaviju tavo pranašus; o aš vienas teišlikau; ir jie ieško mano gyvybės, kad ją atimtų“.'),
  (@b11, 19, 15, 'Ir VIEŠPATS jam tarė: „Eik, grįžk savo keliu į Damasko dykumą; ir atėjęs patepk Hazaelį būti Sirijos karaliumi;'),
  (@b11, 19, 16, 'ir Nimšio sūnų Jehuvą patepk būti Izraelio karaliumi; o Šafato sūnų Elišą iš Abel-Meholos patepk būti pranašu tavo vietoje.'),
  (@b11, 19, 17, 'Ir įvyks, kas ištrūks iš Hazaelio kalavijo, tą Jehuvas nužudys; o kas ištrūks iš Jehuvo kalavijo, tą Eliša nužudys.'),
  (@b11, 19, 18, 'Tačiau aš pasilikau Izraelyje septynis tūkstančius – visus tuos kelius, kurie neklūpčiojo Baalui, ir kiekvieną burną, kuri jo nebučiavo“.'),
  (@b11, 19, 19, 'Taigi jis išėjo iš ten ir surado Šafato sūnų Elišą, ariantį su dvylika jungų jaučių pirma jo, o jis pats su dvyliktuoju; ir Elijas, praeidamas pro jį, užmetė ant jo savo mantiją.'),
  (@b11, 19, 20, 'Ir jis palikęs jaučius nubėgo paskui Eliją ir tarė: „Leisk man, meldžiu tave, pabučiuoti savo tėvą ir savo motiną, o paskui tave seksiu“. Ir jis jam tarė: „Eik, sugrįžk; nes ką aš tau padariau?“'),
  (@b11, 19, 21, 'Ir jis sugrįžo nuo jo ir, paėmęs jungą jaučių, papjovė juos, ir jų mėsą išvirė su jaučių pakinktais, ir davė žmonėms, ir jie valgė. Paskui pakilęs jis ėjo paskui Eliją ir jam tarnavo.'),
  (@b11, 20, 1, 'Ir Sirijos karalius Ben-Hadadas surinko visą savo kariuomenę; ir su juo buvo trisdešimt du karaliai ir žirgai, ir vežimai; ir nuėjęs aukštyn jis apgulė Samariją ir kariavo prieš ją.'),
  (@b11, 20, 2, 'Ir jis siuntė pasiuntinius pas Izraelio karalių Ahabą į miestą ir jam sakė: „Taip sako Ben-Hadadas:'),
  (@b11, 20, 3, '‘Tavo sidabras ir tavo auksas yra mano; taip pat tavo žmonos ir tavo vaikai, tai yra geriausieji, yra mano’“.'),
  (@b11, 20, 4, 'O Izraelio karalius atsakė ir tarė: „Mano viešpatie, o karaliau, pagal tavo pasakymą aš esu tavo ir viskas, ką aš turiu“.'),
  (@b11, 20, 5, 'Ir pasiuntiniai vėl atėjo ir tarė: „Taip sako Ben-Hadadas, sakydamas: ‘Nors aš siunčiau pas tave, sakydamas: „Atiduok man savo sidabrą ir savo auksą, savo žmonas ir savo vaikus“;'),
  (@b11, 20, 6, 'tačiau rytoj apie šitą laiką atsiųsiu pas tave savo tarnus, ir jie iškratys tavo namus ir tavo tarnų namus; ir bus, kad visa, kas geistina tavo akims, jie įsidės tai į rankas ir nusineš’“.'),
  (@b11, 20, 7, 'Tada Izraelio karalius, sušaukęs visus šalies vyresniuosius, tarė: „Stebėkite, meldžiu jus, ir matykite, kaip šitas žmogus siekia pikta; nes jis atsiuntė pas mane dėl mano žmonų ir dėl mano vaikų, dėl mano sidabro ir dėl mano aukso; o aš jam neatsisakiau“.'),
  (@b11, 20, 8, 'Ir visi vyresnieji ir visa tauta jam tarė: „Neklausyk jo ir nesutik“.'),
  (@b11, 20, 9, 'Todėl jis tarė Ben-Hadado pasiuntiniams: „Sakykite mano viešpačiui karaliui: ‘Viską, dėl ko pradžioje siuntei pas savo tarną, aš darysiu; bet šito dalyko negaliu daryti’“. Ir pasiuntiniai išėjo ir jam parnešė žinią.'),
  (@b11, 20, 10, 'Ir Ben-Hadadas siuntė pas jį ir tarė: „Tepadaro dievai man taip ir dar daugiau, jei Samarijos dulkių pakaks saujoms visų žmonių, kurie seka paskui mane“.'),
  (@b11, 20, 11, 'O Izraelio karalius atsakė ir tarė: „Sakykite jam: ‘Tenesigiria tas, kuris užsijuosia šarvuotę, kaip tas, kuris ją nusijuosia“.'),
  (@b11, 20, 12, 'Ir įvyko, kai Ben-Hadadas išgirdo šitą žinią, kai jis gėrė, jis ir karaliai palapinėse, tada jis tarė savo tarnams: „Išsirikiuokite“. Ir jie išsirikiavo prieš miestą.'),
  (@b11, 20, 13, 'Ir štai atėjo pranašas pas Izraelio karalių Ahabą, sakydamas: „Taip sako VIEŠPATS: ‘Ar matei visą šitą didžiulę minią? Štai aš ją šią dieną atiduosiu į tavo rankas; ir tu žinosi, kad aš esu VIEŠPATS’“.'),
  (@b11, 20, 14, 'Ir Ahabas tarė: „Per ką?“ Ir jis tarė: „Taip sako VIEŠPATS: ‘Per provincijų kunigaikščių jaunuolius’“. Tada jis tarė: „Kas paruoš mūšį?“ Ir jis atsakė: „Tu“.'),
  (@b11, 20, 15, 'Tada jis suskaičiavo provincijų kunigaikščių jaunuolius, ir jų buvo du šimtai trisdešimt du; o po jų jis suskaičiavo visą tautą – visus Izraelio vaikus – septynis tūkstančius.'),
  (@b11, 20, 16, 'Ir jie išėjo vidudienį. O Ben-Hadadas prisigėrė palapinėse, jis ir karaliai, tie trisdešimt du karaliai, kurie jam padėjo.'),
  (@b11, 20, 17, 'Ir provincijų kunigaikščių jaunuoliai išėjo pirmi; ir Ben-Hadadas išsiuntė, ir tie jam pranešė, sakydami: „Vyrai, išėję iš Samarijos“.'),
  (@b11, 20, 18, 'Ir jis tarė: „Jei jie išėjo dėl taikos, suimkite juos gyvus; arba jei jie išėjo kariauti, suimkite juos gyvus“.'),
  (@b11, 20, 19, 'Taip iš miesto išėjo šitie provincijų kunigaikščių jaunuoliai ir kariuomenė, einanti paskui juos.'),
  (@b11, 20, 20, 'Ir jie kiekvienas žudė savo vyrą; ir sirai bėgo; o Izraelis juos vijosi; ir Sirijos karalius Ben-Hadadas pabėgo ant žirgo su raiteliais.'),
  (@b11, 20, 21, 'Ir Izraelio karalius išėjęs sumušė žirgus bei vežimus ir žudė sirus smarkiomis žudynėmis.'),
  (@b11, 20, 22, 'Ir pranašas, atėjęs pas Izraelio karalių, jam tarė: „Eik, sustiprėk, stebėk ir žiūrėk, ką tu darai; nes metams praėjus Sirijos karalius ateis aukštyn prieš tave“.'),
  (@b11, 20, 23, 'Ir Sirijos karaliaus tarnai jam tarė: „Jų dievai yra kalvų dievai; todėl jie buvo stipresni už mus; bet kovokime prieš juos lygumoje, tai tikrai mes būsime stipresni už juos.'),
  (@b11, 20, 24, 'Ir padaryk tokį dalyką: Pašalink karalius, kiekvieną iš jo vietos, ir įstatyk į jų vietas vadus.'),
  (@b11, 20, 25, 'Ir suskaičiuok sau kariuomenę, kaip tą kariuomenę, kurią praradai, žirgą už žirgą ir vežimą už vežimą; ir mes kovosime prieš juos lygumoje, ir tikrai būsime už juos stipresni“. Ir jis paklausė jų balso ir taip padarė.'),
  (@b11, 20, 26, 'Ir įvyko, kad metams praėjus Ben-Hadadas suskaičiavo sirus ir ėjo aukštyn į Afeką kovoti prieš Izraelį.'),
  (@b11, 20, 27, 'Ir Izraelio vaikai buvo suskaičiuoti, ir buvo visi, ir ėjo prieš juos; ir Izraelio vaikai stovyklavo prieš juos kaip dvi mažos ožkų kaimenės; o sirai pripildė šalį.'),
  (@b11, 20, 28, 'Ir Dievo vyras atėjo ir kalbėjo Izraelio karaliui, sakydamas: „Taip sako VIEŠPATS: ‘Kadangi sirai sakė: „VIEŠPATS yra kalnų Dievas, bet jis nėra slėnių Dievas“, todėl aš atiduosiu visą šitą didžiulę minią į tavo rankas, ir tu žinosi, kad aš esu VIEŠPATS’“.'),
  (@b11, 20, 29, 'Ir septynias dienas jie stovyklavo vieni prieš kitus. Ir buvo taip, kad septintąją dieną prasidėjo mūšis; ir Izraelio vaikai per vieną dieną iš sirų nužudė šimtą tūkstančių pėstininkų.'),
  (@b11, 20, 30, 'Bet likusieji pabėgo į Afeką, į miestą; ir ten siena užgriuvo ant dvidešimt septynių tūkstančių išlikusių vyrų. O Ben-Hadadas pabėgo ir atėjo į miestą, į vidinį kambarį.'),
  (@b11, 20, 31, 'Ir jo tarnai jam tarė: „Štai mes girdėjome, kad Izraelio namų karaliai yra gailestingi karaliai; meldžiu tave, užsidėkime ašutines ant strėnų bei virves ant galvų ir išeikime pas Izraelio karalių; galbūt jis išsaugos tavo gyvybę“.'),
  (@b11, 20, 32, 'Taigi apsijuosę strėnas ašutinėmis ir užsidėję ant galvų virves, jie atėjo pas Izraelio karalių ir tarė: „Tavo tarnas Ben-Hadadas sako: ‘Palik, meldžiu tave, mane gyvą’“. Ir jis tarė: „Ar jis dar gyvas? Jis yra mano brolis“.'),
  (@b11, 20, 33, 'Na, o tie vyrai stropiai stebėjo, koks dalykas iš jo išeis, ir skubiai tai pagavo; ir jie tarė: „Tavo brolis Ben-Hadadas“. Tada jis tarė: „Eikite, atveskite jį“. Tada Ben-Hadadas išėjo pas jį; ir jis įlaipino jį į vežimą.'),
  (@b11, 20, 34, 'Ir Ben-Hadadas jam tarė: „Miestus, kuriuos mano tėvas atėmė iš tavo tėvo, aš grąžinsiu; ir tu pasidaryk sau gatvių Damaske, kaip mano tėvas padarė Samarijoje“. Tada Ahabas tarė: „Aš tave paleisiu su šia sandora“. Taigi jis sudarė su juo sandorą ir jį paleido.'),
  (@b11, 20, 35, 'Ir vienas vyras iš pranašų sūnų tarė savo artimui VIEŠPATIES žodžiu: „Mušk mane, meldžiu tave“. O tas vyras atsisakė jį mušti.'),
  (@b11, 20, 36, 'Tada jis jam tarė: „Kadangi nepaklusai VIEŠPATIES balsui, štai kai tik nueisi nuo manęs, liūtas tave nužudys“. Ir jam tik nuėjus nuo jo, jį užtiko liūtas ir papjovė.'),
  (@b11, 20, 37, 'Tada užtikęs kitą vyrą, jis tarė: „Mušk mane, meldžiu tave“. Ir tas vyras taip jį mušė, kad mušdamas jį sužeidė.'),
  (@b11, 20, 38, 'Taigi tas pranašas išėjo ir laukė prie kelio karaliaus, užsimaskavęs savo veidą pelenais.'),
  (@b11, 20, 39, 'Ir karaliui praeinant, jis šaukė karaliui ir tarė: „Tavo tarnas išėjo į mūšio vidurį; ir štai žmogus pasuko į šalį ir atvedė pas mane vyrą, ir tarė: ‘Saugok šitą vyrą; jei kokiu nors būdu jis dings, tada tavo gyvybė bus už jo gyvybę, arba turėsi sumokėti talentą sidabro.'),
  (@b11, 20, 40, 'Ir kai tavo tarnas buvo užsiėmęs šen bei ten, jis dingo“. Ir Izraelio karalius jam tarė: „Toks tau bus teismas; tu pats tai nusprendei“.'),
  (@b11, 20, 41, 'Ir jis skubiai nusibraukė pelenus nuo veido; ir Izraelio karalius jį atpažino, kad jis iš pranašų.'),
  (@b11, 20, 42, 'Ir jis tarė jam: „Taip sako VIEŠPATS: ‘Kadangi paleidai iš savo rankos vyrą, kurį paskyriau visiškam sunaikinimui, tavo gyvybė bus už jo gyvybę ir tavo tauta už jo tautą“.'),
  (@b11, 20, 43, 'Ir Izraelio karalius ėjo į savo namus liūdnas ir nepatenkintas, ir atvyko į Samariją.'),
  (@b11, 21, 1, 'Ir po šitų dalykų atsitiko, kad jezreelietis Nabotas turėjo vynuogyną, esantį Jezreelyje, šalia Samarijos karaliaus Ahabo rūmų.'),
  (@b11, 21, 2, 'Ir Ahabas kalbėjo Nabotui, sakydamas: „Duok man savo vynuogyną, kad turėčiau jį kaip žolių daržą, nes jis yra arti mano namų; o aš tau duosiu už jį geresnį vynuogyną nei šis; arba, jei tau atrodo geriau, aš tau duosiu jo vertę pinigais“.'),
  (@b11, 21, 3, 'Ir Nabotas tarė Ahabui: „VIEŠPATIE apsaugok mane nuo to, kad aš tau duočiau savo tėvų paveldą“.'),
  (@b11, 21, 4, 'Ir Ahabas atėjo į savo namus liūdnas ir nepatenkintas dėl žodžio, kurį jam buvo kalbėjęs jezreelietis Nabotas; nes jis sakė: „Neduosiu tau savo tėvų paveldo“. Ir jis atsigulė į savo lovą, nugręžė veidą ir nevalgė duonos.'),
  (@b11, 21, 5, 'Bet jo žmona Jezabelė atėjo pas jį ir jam tarė: „Kodėl tavo dvasia tokia liūdna, kad nevalgai duonos?“'),
  (@b11, 21, 6, 'Ir jis jai tarė: „Nes aš kalbėjau jezreeliečiui Nabotui ir jam sakiau: ‘Duok man savo vynuogyną už pinigus; arba, jei tau patinka, aš tau duosiu už jį kitą vynuogyną; o jis atsakė: ‘Aš tau neduosiu savo vynuogyno“.'),
  (@b11, 21, 7, 'Ir jo žmona Jezabelė jam tarė: „Ar tu dabar valdai Izraelio karalystę? Kelkis, valgyk duonos ir tebūna linksma tavo širdis; aš tau duosiu jezreeliečio Naboto vynuogyną“.'),
  (@b11, 21, 8, 'Taigi ji parašė Ahabo vardu laiškus, juos užantspaudavo jo antspaudu ir nusiuntė laiškus vyresniesiems bei kilmingiesiems, esantiems jo mieste, gyvenantiems su Nabotu.'),
  (@b11, 21, 9, 'Ir ji rašė tuose laiškuose, sakydama: „Paskelbkite pasninką ir pasodinkite Nabotą aukštai tautos tarpe;'),
  (@b11, 21, 10, 'ir pastatykite priešais jį du vyrus, Belialo sūnus, kad liudytų prieš jį, sakydami: ‘Tu piktžodžiavai Dievui ir karaliui‘. O paskui jį išveskite ir užmėtykite akmenimis, kad jis mirtų“.'),
  (@b11, 21, 11, 'Ir jo miesto vyrai, tai yra vyresnieji ir kilmingieji, gyvenantieji jo mieste, padarė, kaip Jezabelė buvo jiems nusiuntusi, kaip buvo parašyta tuose laiškuose, kuriuos ji buvo jiems siuntusi.'),
  (@b11, 21, 12, 'Jie paskelbė pasninką ir pasodino Nabotą aukštai tautos tarpe.'),
  (@b11, 21, 13, 'Ir atėjo du vyrai, Belialo vaikai, ir atsisėdo prieš jį; ir tie Belialo vyrai liudijo prieš jį, tai yra prieš Nabotą, tautos akivaizdoje, sakydami: „Nabotas piktžodžiavo Dievui ir karaliui“. Tada jie išvedė jį už miesto ir užmėtė akmenimis, kad jis mirė.'),
  (@b11, 21, 14, 'Paskui jie pasiuntė Jezabelei, sakydami: „Nabotas užmėtytas akmenimis ir yra miręs“.'),
  (@b11, 21, 15, 'Ir įvyko, kai Jezabelė išgirdo, kad Nabotas buvo užmėtytas akmenimis ir buvo miręs, Jezabelė tarė Ahabui: „Kelkis, pasisavink jezreeliečio Naboto vynuogyną, kurį jis atsisakė tau duoti už pinigus; nes Nabotas ne gyvas, bet miręs“.'),
  (@b11, 21, 16, 'Ir įvyko, kai Ahabas išgirdo, kad Nabotas miręs, Ahabas atsikėlė eiti žemyn į jezreeliečio Naboto vynuogyną, kad jį pasisavintų.'),
  (@b11, 21, 17, 'Ir VIEŠPATIES žodis atėjo tišbiečiui Elijui, sakydamas:'),
  (@b11, 21, 18, '„Kelkis, eik žemyn pasitikti Izraelio karalių Ahabą, kuris yra Samarijoje; štai jis yra Naboto vynuogyne, kur jis yra nuėjęs žemyn jo pasisavinti.'),
  (@b11, 21, 19, 'Ir jam kalbėk, sakydamas: ‘Taip sako VIEŠPATS: „Ar tu nužudei ir dar ėmei nuosavybę?“ Ir kalbėk jam, sakydamas: ‘Taip sako VIEŠPATS: „Toje vietoje, kurioje šunys laižė Naboto kraują, šunys laižys tavo kraują, būtent tavo’“.'),
  (@b11, 21, 20, 'Ir Ahabas tarė Elijui: „Suradai mane, o mano prieše?“ Ir jis atsakė: „Suradau tave; nes tu parsidavei, kad darytum pikta VIEŠPATIES akyse.'),
  (@b11, 21, 21, 'Štai aš užleisiu ant tavęs pikta ir atimsiu tavo palikuonis, ir iškirsiu iš Ahabo tą, kuris šlapinasi į sieną, ir tą, kuris yra užrakintas ir paliktas Izraelyje,'),
  (@b11, 21, 22, 'ir padarysiu tavo namus, kaip Nebato sūnaus Jeroboamo namus ir kaip Ahijos sūnaus Baašos namus, dėl kurstymo, kuriuo kurstei mano pyktį ir skatinai Izraelį nusidėti.'),
  (@b11, 21, 23, 'Ir apie Jezabelę VIEŠPATS taip pat kalbėjo, sakydamas: ‘Šunys ės Jezabelę prie Jezreelio sienos.'),
  (@b11, 21, 24, 'Kas iš Ahabo mirs mieste, tą ės šunys; o kas mirs ant lauko, tą les oro skrajūnai’“.'),
  (@b11, 21, 25, 'Bet nebuvo nei vieno, kaip Ahabas, kuris parsidavė, kad darytų nedorybę VIEŠPATIES akyse, kurį kurstė jo žmona Jezabelė.'),
  (@b11, 21, 26, 'Ir jis elgėsi labai pasibjaurėtinai, sekdamas paskui stabus pagal visa tai, ką darė amoritai, kuriuos VIEŠPATS išvarė Izraelio vaikų priešakyje.'),
  (@b11, 21, 27, 'Ir įvyko, kai Ahabas išgirdo šituos žodžius, jis persiplėšė savo drabužius, užsidėjo ašutinę ant savo kūno ir pasninkavo, ir gulėjo ašutinėje, ir vaikščiojo tyliai.'),
  (@b11, 21, 28, 'Ir VIEŠPATIES žodis atėjo tišbiečiui Elijui, sakydamas:'),
  (@b11, 21, 29, '„Ar matai, kaip Ahabas nusižemino prieš mane? Kadangi jis nusižemino mano akivaizdoje, tai aš neužleisiu tos nelaimės jo dienomis; bet jo sūnaus dienomis aš užleisiu tą nelaimę ant jo namų“.'),
  (@b11, 22, 1, 'Ir trejus metus jie išsilaikė be karo tarp Sirijos ir Izraelio.'),
  (@b11, 22, 2, 'O trečiaisiais metais atsitiko, kad Judos karalius Jehozapatas atėjo žemyn pas Izraelio karalių.'),
  (@b11, 22, 3, 'Ir Izraelio karalius tarė savo tarnams: „Ar žinote, kad Ramotas Gileade yra mūsų, o mes tylime ir jo neatimame iš Sirijos karaliaus rankos?“'),
  (@b11, 22, 4, 'Ir jis tarė Jehozapatui: „Ar eisi su manimi į mūšį, į Ramot-Gileadą?“ O Jehozapatas tarė Izraelio karaliui: „Aš esu kaip ir tu, mano tauta kaip tavo tauta, mano žirgai kaip tavo žirgai“.'),
  (@b11, 22, 5, 'Ir Jehozapatas tarė Izraelio karaliui: „Pasiklausk, meldžiu tave, šiandien VIEŠPATIES žodžio“.'),
  (@b11, 22, 6, 'Tada Izraelio karalius surinko pranašus, apie keturis šimtus vyrų, ir jiems tarė: „Ar man eiti į mūšį prieš Ramot-Gileadą, ar susilaikyti?“ Ir jie tarė: „Eik aukštyn; nes Viešpats jį atiduos į karaliaus rankas“.'),
  (@b11, 22, 7, 'O Jehozapatas tarė: „Ar čia nėra be to dar VIEŠPATIES pranašo, kad galėtume jo pasiklausti?“'),
  (@b11, 22, 8, 'Ir Izraelio karalius tarė Jehozapatui: „Dar yra vienas vyras, Imlos sūnus Michėjas, per kurį galėtume pasiklausti VIEŠPATIES; bet aš jo nekenčiu; nes jis nepranašauja apie mane gera, o tik bloga“. Ir Jehozapatas tarė: „Tenesako taip karalius“.'),
  (@b11, 22, 9, 'Tada Izraelio karalius pašaukęs pareigūną tarė: „Paskubink čia Imlos sūnų Michėją“.'),
  (@b11, 22, 10, 'O Izraelio karalius ir Judos karalius Jehozapatas sėdėjo kiekvienas savo soste, apsivilkę drabužiais, atviroje vietoje, Samarijos vartų įėjime; ir visi pranašai pranašavo jų akivaizdoje.'),
  (@b11, 22, 11, 'Ir Kenaanos sūnus Sedekijas pasidarė geležinius ragus; ir jis tarė: „Taip sako VIEŠPATS: ‘Šitais tu badysi sirus, kol juos sunaikinsi“.'),
  (@b11, 22, 12, 'Ir visi pranašai taip pranašavo, sakydami: „Eik aukštyn į Ramot-Gileadą ir laimėk; nes VIEŠPATS atiduos jį į karaliaus rankas“.'),
  (@b11, 22, 13, 'Ir pasiuntinys, kuris buvo nuėjęs pakviesti Michėjo, jam kalbėjo, sakydamas: „Štai pranašų žodžiai vienbalsiai skelbia gera karaliui; meldžiu tave, tavo žodis tebūna kaip vieno iš jų žodis, ir kalbėk tai, kas gera“.'),
  (@b11, 22, 14, 'O Michėjas tarė: „Kaip gyvas VIEŠPATS, ką VIEŠPATS man sako, tą kalbėsiu“.'),
  (@b11, 22, 15, 'Taigi jis atėjo pas karalių. Ir karalius jam tarė: „Michėjau, ar mums eiti į mūšį prieš Ramot-Gileadą, ar susilaikyti?“ O jis jam atsakė: „Eik ir laimėk; nes VIEŠPATS atiduos jį į karaliaus rankas“.'),
  (@b11, 22, 16, 'Ir karalius jam tarė: „Kiek kartų man reikės tave saikdinti, kad man nieko kita nekalbėtum, bet tik tiesą VIEŠPATIES vardu?“'),
  (@b11, 22, 17, 'Ir jis tarė: „Mačiau visą Izraelį išsklaidytą ant kalvų kaip avis, neturinčias ganytojo; ir VIEŠPATS tarė: ‘Šitie neturi valdovo; tegul jie kiekvienas grįžta ramybėje į savo namus’“.'),
  (@b11, 22, 18, 'Ir Izraelio karalius tarė Jehozapatui: „Argi tau nesakiau, kad jis nepranašauja apie mane gera, bet tik pikta?“'),
  (@b11, 22, 19, 'Ir jis tarė: „Todėl klausyk VIEŠPATIES žodžio: Mačiau VIEŠPATĮ, sėdintį savo soste, ir visą dangaus kariuomenę, stovinčią prie jo, jo dešinėje ir jo kairėje.'),
  (@b11, 22, 20, 'Ir VIEŠPATS tarė: ‘Kas įtikins Ahabą, kad jis eitų aukštyn ir kristų Ramot-Gileade?’ Ir vienas sakė vienaip, o kitas sakė kitaip.'),
  (@b11, 22, 21, 'Ir išėjo dvasia ir atsistojusi VIEŠPATIES akivaizdoje tarė: ‘Aš jį įtikinsiu’.'),
  (@b11, 22, 22, 'Ir VIEŠPATS jai tarė: ‘Kuo?’ O ji tarė: ‘Aš išeisiu ir būsiu melo dvasia visų jo pranašų burnoje’ Ir jis tarė: ‘Tu jį įtikinsi ir taipogi nugalėsi: išeik ir taip daryk’.'),
  (@b11, 22, 23, 'Taigi dabar, štai VIEŠPATS įdėjo melo dvasią į visų šitų tavo pranašų burną, ir VIEŠPATS kalbėjo pikta apie tave“.'),
  (@b11, 22, 24, 'Bet Kenaanos sūnus Sedekijas priėjęs trenkė Michėjui į žandą ir tarė: „Kuriuo keliu VIEŠPATIES Dvasia nuėjo nuo manęs, kad kalbėtų tau?“'),
  (@b11, 22, 25, 'O Michėjas tarė: „Štai tu matysi tą dieną, kai eisi į vidinį kambarį slėptis“.'),
  (@b11, 22, 26, 'Ir Izraelio karalius tarė: „Paimk Michėją, nuvesk jį atgal pas miesto valdytoją Amoną ir pas karaliaus sūnų Joašą;'),
  (@b11, 22, 27, 'ir sakyk: ‘Taip sako karalius: Pasodinkite šitą į kalėjimą ir maitinkite jį sielvarto duona bei sielvarto vandeniu, kol aš ateisiu ramybėje’“.'),
  (@b11, 22, 28, 'O Michėjas tarė: „Jei tikrai sugrįši ramybėje, tai VIEŠPATS nekalbėjo per mane“. Ir jis tarė: „Klausyk, o tauta, kiekvienas iš jūsų“.'),
  (@b11, 22, 29, 'Taip Izraelio karalius ir Judos karalius Jehozapatas ėjo aukštyn į Ramot-Gileadą.'),
  (@b11, 22, 30, 'Ir Izraelio karalius tarė Jehozapatui: „Aš užsimaskuosiu ir įeisiu į mūšį; bet tu apsirenk savo drabužiais“. Ir Izraelio karalius persirengęs ėjo į mūšį.'),
  (@b11, 22, 31, 'Bet Sirijos karalius įsakė savo trisdešimt dviem vadams, kurie vadovavo jo vežimams, sakydamas: „Nekovokite nei su mažais, nei su dideliais, bet tik su Izraelio karaliumi“.'),
  (@b11, 22, 32, 'Ir įvyko, kai vežimų vadai pamatė Jehozapatą, jie sakė: „Tikrai šis yra Izraelio karalius“. Ir jie pasuko į šoną kovoti prieš jį; o Jehozapatas ėmė šaukti.'),
  (@b11, 22, 33, 'Ir įvyko, kai vežimų vadai suprato, kad tai ne Izraelio karalius, jie nusigręžė nuo jo ir nebesivijo.'),
  (@b11, 22, 34, 'Ir kažkoks vyras netaikydamas įtempė lanką ir įšovė Izraelio karaliui tarp šarvuotės sujungimų; todėl jis tarė savo vežimo važiuotojui: „Atgręžk savo ranką ir išgabenk mane iš kariuomenės; nes aš esu sužeistas“.'),
  (@b11, 22, 35, 'Ir mūšis tą dieną stiprėjo; o karalius stovėjo savo vežime prieš sirus ir vakare mirė; ir kraujas iš žaizdos išsiliejo į vežimo vidų.'),
  (@b11, 22, 36, 'Ir saulei leidžiantis ėjo pranešimas po visą kariuomenę, sakantis: „Kiekvienas į savo miestą ir kiekvienas į savo kraštą“.'),
  (@b11, 22, 37, 'Taip karalius mirė ir buvo atgabentas į Samariją; ir jie palaidojo karalių Samarijoje.'),
  (@b11, 22, 38, 'Ir plovė vežimą Samarijos tvenkinyje; o šunys laižė jo kraują; ir jie plovė jo šarvus; pagal VIEŠPATIES žodį, kurį jis kalbėjo.'),
  (@b11, 22, 39, 'Na, o kiti Ahabo darbai ir visa, ką jis darė, ir dramblio kaulo namai, kuriuos jis pastatė, ir visi miestai, kuriuos jis pastatė, argi jie nėra surašyti Izraelio karalių kronikų knygoje?'),
  (@b11, 22, 40, 'Taip Ahabas užmigo prie savo tėvų; o jo sūnus Ahazijas karaliavo jo vietoje.'),
  (@b11, 22, 41, 'Ir Asos sūnus Jehozapatas pradėjo karaliauti Judai ketvirtaisiais Izraelio karaliaus Ahabo metais.'),
  (@b11, 22, 42, 'Jehozapatas buvo trisdešimt penkerių metų, kai jis pradėjo karaliauti; ir jis karaliavo dvidešimt penkerius metus Jeruzalėje. O jo motinos vardas buvo Azuba, Šilhio duktė.'),
  (@b11, 22, 43, 'Ir jis vaikščiojo visais savo tėvo Asos keliais; jis nenukrypo nuo jų, darydamas tai, kas teisinga VIEŠPATIES akyse; tačiau aukštumos nebuvo pašalintos; nes tauta tebeaukodavo ir tebedegindavo smilkalus aukštumose.'),
  (@b11, 22, 44, 'Ir Jehozapatas sudarė taiką su Izraelio karaliumi.'),
  (@b11, 22, 45, 'Na, o kiti Jehozapato darbai ir jo galybė, kurią jis parodė, ir kaip jis kariavo, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b11, 22, 46, 'Ir jis išnaikino iš šalies likusius sodomiečius, kurie buvo užsilikę jo tėvo Asos dienomis.'),
  (@b11, 22, 47, 'Tuomet Edome nebuvo karaliaus; vietininkas buvo karalius.'),
  (@b11, 22, 48, 'Jehozapatas pasidarė Taršišo laivų, kad vyktų į Ofyrą aukso; bet jie neišvyko; nes laivai sudužo Ecion-Geberyje.'),
  (@b11, 22, 49, 'Tuomet Ahabo sūnus Ahazijas tarė Jehozapatui: „Tegul eina mano tarnai laivuose su tavo tarnais“. Bet Jehozapatas nenorėjo.'),
  (@b11, 22, 50, 'Ir Jehozapatas užmigo prie savo tėvų ir buvo palaidotas prie savo tėvų savo tėvo Dovydo mieste; o jo sūnus Jehoramas karaliavo jo vietoje.'),
  (@b11, 22, 51, 'Ahabo sūnus Ahazijas pradėjo karaliauti Izraeliui Samarijoje septynioliktais Judos karaliaus Jehozapato metais ir karaliavo Izraeliui dvejus metus.'),
  (@b11, 22, 52, 'Ir jis darė pikta VIEŠPATIES akyse ir vaikščiojo savo tėvo keliu, savo motinos keliu ir keliu Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti;'),
  (@b11, 22, 53, 'nes jis tarnavo Baalui, garbino jį ir kurstė VIEŠPATIES, Izraelio Dievo, pyktį pagal visa tai, ką buvo daręs jo tėvas.'),
  (@b12, 1, 1, 'Ahabui mirus, Moabas sukilo prieš Izraelį.'),
  (@b12, 1, 2, 'Ir nukrito Ahazijas pro Samarijoje esančio savo aukštutinio kambario groteles ir susirgo; ir jis siuntė pasiuntinius ir jiems tarė: „Eikite, pasiklauskite Ekrono dievo Baal-Zebubo, ar aš pasveiksiu iš šitos ligos“.'),
  (@b12, 1, 3, 'Bet VIEŠPATIES angelas pasakė tišbiečiui Elijui: „Kelkis, eik aukštyn pasitikti Samarijos karaliaus pasiuntinių ir jiems kalbėk: ‘Ar ne dėl to, kad nėra Dievo Izraelyje, kad jūs einate klaustis Ekrono dievo Baal-Zebubo?’'),
  (@b12, 1, 4, 'Todėl dabar taip sako VIEŠPATS: ‘Iš to patalo, į kurį įlipai, neišlipsi, bet tikrai mirsi’“. Ir Elijas nuėjo.'),
  (@b12, 1, 5, 'Ir pasiuntiniams pas jį sugrįžus, jis jiems tarė: „Kodėl dabar sugrįžote?“'),
  (@b12, 1, 6, 'O jie jam tarė: „Vienas vyras atėjo aukštyn mūsų pasitikti ir mums tarė: ‘Eikite, grįžkite pas karalių, kuris jus siuntė, ir jam kalbėkite: „Taip sako VIEŠPATS: Ar ne dėl to, kad nėra Dievo Izraelyje, kad tu siunti klaustis Ekrono dievo Baal-Zebubo? Todėl iš to patalo, į kurį įlipai, neišlipsi, bet tikrai mirsi’“.'),
  (@b12, 1, 7, 'Ir jis jiems tarė: „Kas tai buvo per vyras, kuris atėjo aukštyn jūsų pasitikti ir jums pasakė šituos žodžius?“'),
  (@b12, 1, 8, 'Ir jie jam atsakė: „Jis buvo gauruotas vyras ir susijuosęs strėnas odiniu diržu“. Ir jis tarė: „Tai tišbietis Elijas“.'),
  (@b12, 1, 9, 'Tada karalius pasiuntė pas jį penkiasdešimties vadą su jo penkiomis dešimtimis. Ir jis ėjo aukštyn pas jį; ir štai jis sėdėjo ant kalvos viršūnės. Ir jis kalbėjo jam: „Dievo vyre, karalius pasakė: ‘Lipk žemyn’“.'),
  (@b12, 1, 10, 'O Elijas, atsakydamas kalbėjo penkiasdešimtininkui: „Jei aš Dievo vyras, tuomet ugnis tenusileidžia iš dangaus ir praryja tave bei tavo penkias dešimtis“. Ir nusileido iš dangaus ugnis ir prarijo jį bei jo penkias dešimtis.'),
  (@b12, 1, 11, 'Jis vėl siuntė pas jį ir kitą penkiasdešimtininką su jo penkiomis dešimtimis. Ir jis atsakydamas jam tarė: „O Dievo vyre, taip sakė karalius: ‘Skubiai lipk žemyn’“.'),
  (@b12, 1, 12, 'O Elijas atsakydamas jiems kalbėjo: „Jei aš Dievo vyras, tenusileidžia iš dangaus ugnis ir praryja tave bei tavo penkias dešimtis“. Ir Dievo ugnis nusileido iš dangaus ir prarijo jį bei jo penkias dešimtis.'),
  (@b12, 1, 13, 'Ir jis vėl siuntė trečios penkiasdešimties vadą su jo penkiomis dešimtimis. Ir trečiasis penkiasdešimtininkas, užlipęs aukštyn ir atėjęs, parkrito ant kelių prieš Eliją ir jo maldaudamas jam kalbėjo: „O Dievo vyre, meldžiu tave, tebūna brangi tavo akyse mano gyvybė ir šitų tavo penkiasdešimties tarnų gyvybė.'),
  (@b12, 1, 14, 'Štai nusileido iš dangaus ugnis ir sudegino du vadus pirmųjų penkiasdešimčių su jų penkiasdešimtimis; todėl tebūna dabar brangi mano gyvybė tavo akyse“.'),
  (@b12, 1, 15, 'Ir VIEŠPATIES angelas tarė Elijui: „Eik su juo žemyn; nebijok jo“. Ir atsikėlęs jis ėjo su juo žemyn pas karalių.'),
  (@b12, 1, 16, 'Ir jis jam kalbėjo: „Taip sako VIEŠPATS: ‘Kadangi siuntei pasiuntinius Ekrono dievo Baal-Zebubo pasiklausti (ar ne dėl to, kad Izraelyje nėra Dievo, kad jo žodžio būtų galima pasiklausti?), todėl neišlipsi iš to patalo, į kurį įlipai, bet tikrai mirsi’“.'),
  (@b12, 1, 17, 'Taip jis mirė pagal VIEŠPATIES žodį, kurį Elijas kalbėjo. O Jehoramas karaliavo jo vietoje antraisiais Judos karaliaus Jehozapato sūnaus Jehoramo metais; nes jis neturėjo sūnaus.'),
  (@b12, 1, 18, 'Na, o kiti Ahazijo darbai, kuriuos jis darė, argi jie nėra surašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 2, 1, 'Ir įvyko, kai VIEŠPATS ketino viesulu paimti Eliją į dangų, Elijas su Eliša ėjo iš Gilgalo.'),
  (@b12, 2, 2, 'Ir Elijas tarė Elišai: „Pasilik čia, meldžiu tave; nes VIEŠPATS mane siuntė į Bet-Elį“. O Eliša jam tarė: „Kaip VIEŠPATS gyvas ir kaip gyva tavo siela, aš tavęs nepaliksiu“. Taip jie ėjo žemyn į Bet-Elį.'),
  (@b12, 2, 3, 'Ir pranašų sūnūs, kurie buvo Bet-Elyje, išėję pas Elišą jam tarė: „Ar žinai, kad šiandien VIEŠPATS paims tavo valdovą nuo tavo galvos?“ Ir jis tarė: „Taip, žinau; tylėkite“.'),
  (@b12, 2, 4, 'Ir Elijas jam tarė: „Eliša, pasilik čia, meldžiu tave; nes VIEŠPATS mane pasiuntė į Jerichą“. O jis tarė: „Kaip VIEŠPATS gyvas ir kaip gyva tavo siela, aš tavęs nepaliksiu“. Taip jie atėjo į Jerichą.'),
  (@b12, 2, 5, 'Ir Jeriche esantys pranašų sūnūs atėjo pas Elišą ir jam tarė: „Ar žinai, kad šiandien VIEŠPATS paims tavo valdovą nuo tavo galvos?“ O jis atsakė: „Taip, žinau; tylėkite“.'),
  (@b12, 2, 6, 'Ir Elijas jam tarė: „Pasilik čia, meldžiu tave; nes VIEŠPATS mane pasiuntė į Jordaną“. O jis tarė: „Kaip VIEŠPATS gyvas ir kaip gyva tavo siela, aš tavęs nepaliksiu“. Ir juodu ėjo toliau.'),
  (@b12, 2, 7, 'Ir penkiasdešimt vyrų iš pranašų sūnų ėjo ir sustojo iš tolo pažiūrėti; o juodu stovėjo prie Jordano.'),
  (@b12, 2, 8, 'Ir Elijas paėmęs savo mantiją, suvyniojo ją ir sudavė į vandenis, ir jie persiskyrė į vieną ir į kitą pusę, kad juodu perėjo sausa žeme.'),
  (@b12, 2, 9, 'Ir įvyko, kad jiems perėjus, Elijas tarė Elišai: „Prašyk, ką turėčiau tau padaryti prieš tai, kai būsiu paimtas nuo tavęs“. Ir Eliša tarė: „Meldžiu tave, tebūna ant manęs dviguba tavo dvasios dalis“.'),
  (@b12, 2, 10, 'Ir jis tarė: „Prašai sunkaus dalyko; tačiau, jei matysi mane, kai aš būsiu paimtas nuo tavęs, tau taip bus; o jei ne, nebus“.'),
  (@b12, 2, 11, 'Ir atsitiko, kad jiems vis dar einant toliau ir besikalbant, štai pasirodė ugninis vežimas bei ugniniai žirgai ir juodu perskyrė; ir Elijas pakilo viesulu į dangų.'),
  (@b12, 2, 12, 'Ir Eliša tai matė ir šaukė: „Mano tėve, mano tėve, Izraelio vežimas ir jo raiteliai!“ Ir jis daugiau jo nebematė; ir nutvėręs savo drabužius, jis juos perplėšė į dvi dalis.'),
  (@b12, 2, 13, 'Taip pat jis pakėlė Elijo mantiją, kuri buvo nuo jo nukritusi, ir sugrįžęs atsistojo ant Jordano kranto.'),
  (@b12, 2, 14, 'Ir paėmęs Elijo mantiją, kuri buvo nuo jo nukritusi, jis sudavė į vandenis ir tarė: „Kur yra VIEŠPATS, Elijo Dievas?“ Ir jam sudavus į vandenis, jie persiskyrė į vieną ir į kitą pusę; ir Eliša perėjo.'),
  (@b12, 2, 15, 'O kai pranašų sūnūs, kurie buvo pažiūrėti Jeriche, jį pamatė, jie tarė: „Elijo dvasia ilsisi ant Elišos“. Ir atėję jo pasitikti, jie nusilenkė prieš jį iki žemės.'),
  (@b12, 2, 16, 'Ir jie tarė jam: „Štai su tavo tarnais yra penkiasdešimt stiprių vyrų; leisk jiems, meldžiame tave, eiti ir ieškoti tavo valdovo; gal VIEŠPATIES Dvasia yra jį pakėlusi ir numetusi ant kokio kalno ar į kokį slėnį“. O jis tarė: „Nesiųskite“.'),
  (@b12, 2, 17, 'Ir jie primygtinai prašė, kol jis susidrovėjęs tarė: „Siųskite“. Taigi jie išsiuntė penkiasdešimt vyrų; ir jie ieškojo tris dienas, bet jo nerado.'),
  (@b12, 2, 18, 'Ir jiems sugrįžus pas jį (nes jis buvo pasilikęs Jeriche), jis jiems tarė: „Argi jums nesakiau: ‘Neikite’?“'),
  (@b12, 2, 19, 'Ir miesto žmonės tarė Elišai: „Štai meldžiu tave, šio miesto padėtis gera, kaip mano viešpats mato; bet vanduo nieko vertas ir dirva nevaisinga“.'),
  (@b12, 2, 20, 'Ir jis tarė: „Atneškite man naują ąsotį ir įberkite į jį druskos“. Ir jie jam atnešė.'),
  (@b12, 2, 21, 'Ir išėjęs prie vandenų šaltinio ir įmetęs ten druskos, jis tarė: „Taip sako VIEŠPATS: ‘Aš išgydžiau šituos vandenis; nebebus nuo šiol mirties ar nevaisingos žemės’“.'),
  (@b12, 2, 22, 'Taip vandenys buvo išgydyti iki šios dienos pagal Elišos pasakymą, kurį jis kalbėjo.'),
  (@b12, 2, 23, 'Ir iš ten jis ėjo aukštyn į Bet-Elį; ir jam einant keliu aukštyn, maži vaikai išėjo iš miesto ir tyčiojosi iš jo, ir jam sakė: „Eik aukštyn, plikagalvi; eik aukštyn, plikagalvi!“'),
  (@b12, 2, 24, 'Ir atsigręžęs ir į juos pažiūrėjęs, jis juos prakeikė VIEŠPATIES vardu. Ir dvi meškos išėjo iš miško ir sudraskė iš jų keturiasdešimt du vaikus.'),
  (@b12, 2, 25, 'Ir iš ten jis ėjo į Karmelio kalną, o iš ten sugrįžo į Samariją.'),
  (@b12, 3, 1, 'Na, o Ahabo sūnus Jehoramas pradėjo karaliauti Izraeliui Samarijoje aštuonioliktaisiais Judos karaliaus Jehozapato metais ir karaliavo dvylika metų.'),
  (@b12, 3, 2, 'Ir jis darė pikta VIEŠPATIES akyse; bet ne taip, kaip jo tėvas ir kaip jo motina; nes jis pašalino Baalo atvaizdą, kurį buvo padaręs jo tėvas.'),
  (@b12, 3, 3, 'Tačiau jis prilipo prie nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti; jis neatsitraukė nuo jų.'),
  (@b12, 3, 4, 'Ir Moabo karalius Meša buvo avių augintojas ir duodavo Izraelio karaliui šimtą tūkstančių avinėlių ir šimtą tūkstančių avinų su vilna.'),
  (@b12, 3, 5, 'Bet įvyko, kad Ahabui mirus, Moabo karalius sukilo prieš Izraelio karalių.'),
  (@b12, 3, 6, 'Ir tuo pačiu metu karalius Jehoramas išėjo iš Samarijos ir suskaičiavo visą Izraelį.'),
  (@b12, 3, 7, 'Ir jis ėjo ir pasiuntė Judos karaliui Jehozapatui, sakydamas: „Moabo karalius sukilo prieš mane; ar eisi su manimi į mūšį prieš Moabą?“ Ir jis tarė: „Eisiu aukštyn; aš esu kaip ir tu; mano tauta kaip tavo tauta ir mano žirgai kaip tavo žirgai“.'),
  (@b12, 3, 8, 'Ir jis tarė: „Kuriuo keliu eisime aukštyn?“ O jis atsakė: „Keliu per Edomo dykumą“.'),
  (@b12, 3, 9, 'Taip Izraelio karalius, Judos karalius ir Edomo karalius nuėjo; ir jie ėjo aplink septynių dienų kelionę; ir nebuvo vandens kariuomenei ir galvijams, einantiems paskui juos.'),
  (@b12, 3, 10, 'Ir Izraelio karalius tarė: „Vargas! VIEŠPATS sukvietė šituos tris karalius, kad juos atiduotų į Moabo rankas!“'),
  (@b12, 3, 11, 'Bet Jehozapatas tarė: „Ar čia nėra VIEŠPATIES pranašo, kad galėtume per jį pasiklausti VIEŠPATIES?“ Ir vienas iš Izraelio karaliaus tarnų atsiliepdamas tarė: „Čia yra Šafato sūnus Eliša, kuris pildavo vandenį Elijui ant rankų“.'),
  (@b12, 3, 12, 'Ir Jehozapatas tarė: „VIEŠPATIES žodis yra su juo“. Taigi Izraelio karalius, Jehozapatas ir Edomo karalius nuėjo žemyn pas jį.'),
  (@b12, 3, 13, 'Ir Eliša tarė Izraelio karaliui: „Kas man darbo su tavimi? Eik pas savo tėvo pranašus ir pas savo motinos pranašus“. O Izraelio karalius jam pasakė: „Ne; nes VIEŠPATS sukvietė šituos tris karalius, kad juos atiduotų į Moabo rankas“.'),
  (@b12, 3, 14, 'Ir Eliša tarė: „Kaip gyvas kariuomenių VIEŠPATS, kurio akivaizdoje stoviu, tikrai, jei neatsižvelgčiau į Judos karalių Jehozapatą, nežiūrėčiau į tave ir tavęs nematyčiau.'),
  (@b12, 3, 15, 'Bet dabar atveskite man muzikantą“. Ir įvyko, kad muzikantui skambinant, ant jo atėjo VIEŠPATIES ranka.'),
  (@b12, 3, 16, 'Ir jis tarė: „Taip sako VIEŠPATS: ‘Padarykite šitą slėnį pilną griovių’.'),
  (@b12, 3, 17, 'Nes taip sako VIEŠPATS: ‘Nematysite vėjo, nematysite nei lietaus; tačiau tas slėnis bus pripildytas vandens, kad jūs gertumėte, jūs patys, jūsų galvijai ir jūsų gyvuliai.'),
  (@b12, 3, 18, 'Bet VIEŠPATIES akyse tai tėra lengvas dalykas: jis dar atiduos moabiečius į jūsų rankas.'),
  (@b12, 3, 19, 'Ir jūs sumušite visus aptvertus miestus, visus rinktinius miestus, nukirsite visus gerus medžius, užkimšite visus vandens šaltinius ir kiekvieną gerą žemės sklypą sugadinsite akmenimis’“.'),
  (@b12, 3, 20, 'Ir įvyko ryte, kai buvo atnašaujama maisto atnaša, štai atitekėjo vanduo Edomo keliu, ir kraštas buvo pripildytas vandens.'),
  (@b12, 3, 21, 'Ir kai visi moabiečiai išgirdo, kad karaliai buvo atėję aukštyn kariauti prieš juos, jie surinko visus, galinčius užsidėti ginklą, bei vyresnius ir sustojo ant ribos.'),
  (@b12, 3, 22, 'Ir ankstų rytą atsikėlę, saulei šviečiant ant vandens, moabiečiai pamatė kitoje pusėje vandenį raudoną kaip kraują;'),
  (@b12, 3, 23, 'ir jie sakė: „Tai kraujas; tikrai karaliai yra išžudyti, jie sumušė vienas kitą; tad dabar prie grobio, Moabai“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b12, 3, 24, 'Ir jiems atėjus prie Izraelio stovyklos, izraelitai pakilo ir mušė moabiečius taip, kad tie bėgo jų priešakyje; o jie vis ėjo į priekį, mušdami moabiečius jų krašte.'),
  (@b12, 3, 25, 'Ir jie sugriovė miestus, ir kiekvienas numetė po akmenį ant kiekvieno gero žemės sklypo ir jį užvertė; ir jie užkimšo visus vandens šaltinius ir iškirto visus gerus medžius; tik Kir-Haresete jie paliko jo akmenis; tačiau mėtytojai jį apsupo ir sumušė.'),
  (@b12, 3, 26, 'O Moabo karalius, matydamas, kad mūšis jam buvo per sunkus, paėmė su savimi septynis šimtus vyrų, traukiančių kalaviją, kad prasilaužtų pas Edomo karalių; bet jie negalėjo.'),
  (@b12, 3, 27, 'Tada paėmė savo vyriausiąjį sūnų, kuris turėjo karaliauti jo vietoje, ir atnašavo jį kaip deginamąją atnašą ant sienos. Ir buvo didelis pasipiktinimas Izraeliui; ir jie atsitraukė nuo jo ir sugrįžo į savo pačių šalį.'),
  (@b12, 4, 1, 'Na, o viena moteris iš pranašų sūnų žmonų šaukė Elišai, sakydama: „Tavo tarnas, mano vyras, mirė; ir tu žinai, kad tavo tarnas bijojo VIEŠPATIES; ir atėjo skolintojas pasiimti abiejų mano sūnų vergais“.'),
  (@b12, 4, 2, 'Ir Eliša jai tarė: „Ką turėčiau tau padaryti? Pasakyk man, ką turi namuose?“ Ir ji tarė: „Tavo tarnaitė nieko kito neturi namie, kaip tik puodą aliejaus“.'),
  (@b12, 4, 3, 'Tada jis tarė: „Eik, pasiskolink indų, tuščių indų, visur iš visų savo kaimynų; nemažai pasiskolink.'),
  (@b12, 4, 4, 'Ir parėjusi užsirakink duris sau ir savo sūnums iš paskos ir išpilk į visus tuos indus, o tą, kuris pilnas, atsidėk“.'),
  (@b12, 4, 5, 'Taigi nuo jo nuėjusi ji užrakino duris sau ir savo sūnums iš paskos, kurie nešiojo jai indus; o ji išpilinėjo.'),
  (@b12, 4, 6, 'Ir įvyko, kai indai buvo pilni, ji tarė savo sūnui: „Atnešk man dar vieną indą“. O jis jai tarė: „Daugiau nebėra indų“. Ir aliejus sustojo.'),
  (@b12, 4, 7, 'Tada ji atėjo ir pasakė Dievo vyrui. Ir jis tarė: „Eik, parduok tą aliejų ir sumokėk savo skolą, o tu ir tavo vaikai gyvenkite iš to, kas liks“.'),
  (@b12, 4, 8, 'Ir vieną dieną atsitiko, kad Eliša nuėjo į Šunemą, kur buvo didinga moteris; ir ji privertė jį valgyti duonos. Ir buvo, kad kiekvieną kartą praeidamas jis ten užsukdavo valgyti duonos.'),
  (@b12, 4, 9, 'Ir ji tarė savo vyrui: „Štai aš suprantu, kad tas, kuris nuolat praeina pro mus, yra šventas Dievo vyras.'),
  (@b12, 4, 10, 'Padarykime, meldžiu tave, mažą kambarį ant sienos; ir jam padėkime ten lovą, stalą, kėdę ir žvakidę; ir kai jis ateis pas mus, bus taip, kad jis ten užsuks“.'),
  (@b12, 4, 11, 'Ir atsitiko, kad vieną dieną ten atėjęs jis užsuko į tą kambarį ir ten atsigulė.'),
  (@b12, 4, 12, 'Ir jis tarė savo tarnui Gehaziui: „Pakviesk tą šunamietę“. Ir kai jis ją pakvietė, ji atsistojo jo akivaizdoje.'),
  (@b12, 4, 13, 'Ir jis jam tarė: „Dabar sakyk jai: ‘Štai tu rūpinaisi dėl mūsų visu šituo rūpesčiu; ką dėl tavęs padaryti? Ar norėtum kad už tave būtų pakalbėta karaliui ar kariuomenės vadui?’“ Ir ji atsakė: „Aš gyvenu savo tautos tarpe“.'),
  (@b12, 4, 14, 'Ir jis tarė: „Tai ką jai padaryti?“ O Gehazis atsakė: „Iš tikrųjų, ji neturi vaikų, o jos vyras senas“.'),
  (@b12, 4, 15, 'Ir jis tarė: „Pakviesk ją“. O kai jis ją pakvietė, ji atsistojo tarpduryje.'),
  (@b12, 4, 16, 'Ir jis tarė: „Apie šitą laikotarpį pagal gyvenimo metus, tu apkabinsi sūnų“. O ji tarė: „Ne, mano viešpatie, Dievo vyre, nemeluok savo tarnaitei“.'),
  (@b12, 4, 17, 'Ir ta moteris pastojo ir pagimdė sūnų tuo laikotarpiu, pagal gyvenimo metus, kaip buvo jai kalbėjęs Eliša.'),
  (@b12, 4, 18, 'Ir vaikui užaugus, vieną dieną atsitiko, kad jis išėjo pas savo tėvą prie pjovėjų.'),
  (@b12, 4, 19, 'Ir jis tarė savo tėvui: „Mano galva, mano galva“. Ir jis tarė berniukui: „Nunešk jį jo motinai“.'),
  (@b12, 4, 20, 'Ir kai jis buvo jį paėmęs ir nunešęs jo motinai, jis sėdėjo ant jos kelių iki vidudienio, o po to mirė.'),
  (@b12, 4, 21, 'Ir užlipusi ji paguldė jį ant Dievo vyro patalo, užrakino paskui jį duris ir išėjo.'),
  (@b12, 4, 22, 'Ir pašaukusi savo vyrą ji tarė: „Atsiųsk man, meldžiu tave, vieną iš jaunuolių ir vieną iš asilų, kad nulėkčiau pas Dievo vyrą ir sugrįžčiau“.'),
  (@b12, 4, 23, 'Ir jis tarė: „Kodėl nori eiti pas jį šiandien? Juk nei jaunas mėnulis, nei sabatas“. O ji tarė: „Bus gerai“.'),
  (@b12, 4, 24, 'Tada pasibalnojusi asilą ji tarė savo tarnui: „Varyk ir eik pirmyn; nesulėtink man jojimo, nebent tau paliepsiu“.'),
  (@b12, 4, 25, 'Taip ji vyko ir atėjo pas Dievo vyrą į Karmelio kalną. Ir įvyko, kad Dievo vyras, pamatęs ją iš tolo, tarė savo tarnui Gehaziui: „Štai ten ta šunamietė;'),
  (@b12, 4, 26, 'dabar bėk, meldžiu tave, jos pasitikti ir jai sakyk: ‘Ar tau viskas gerai? Ar viskas gerai tavo vyrui? Ar viskas gerai tavo vaikui?’“ Ir ji atsakė: „Gerai“.'),
  (@b12, 4, 27, 'Ir atėjusi pas Dievo vyrą į kalvą, ji nutvėrė jį už kojų; bet Gehazis priėjo ją šalin stumti. O Dievo vyras tarė: „Palik ją; nes jos siela nuliūdusi jos viduje; o VIEŠPATS tai paslėpė nuo manęs ir man nepasakė“.'),
  (@b12, 4, 28, 'Tada ji tarė: „Argi aš prašiau iš savo viešpaties sūnaus? Argi nesakiau: ‘Neapgauk manęs’?“'),
  (@b12, 4, 29, 'Tada jis tarė Gehaziui: „Susijuosk strėnas, pasiimk į ranką mano lazdą ir eik; jei ką sutiksi, nesveikink jo; o jei kas tave sveikins, neatsakyk jam; ir uždėk mano lazdą ant vaiko veido“.'),
  (@b12, 4, 30, 'Ir vaiko motina tarė: „Kaip VIEŠPATS gyvas ir kaip gyva tavo siela, tavęs nepaliksiu“. Ir jis atsikėlęs ėjo paskui ją.'),
  (@b12, 4, 31, 'O Gehazis nuėjo pirma jų ir uždėjo lazdą ant vaiko veido; bet nebuvo nei balso, nei girdėjimo. Todėl jis grįžo jo pasitikti ir jam pranešė, sakydamas: „Vaikas neprabudo“.'),
  (@b12, 4, 32, 'Ir Elišai įėjus į namus, štai vaikas miręs, paguldytas jo lovoje.'),
  (@b12, 4, 33, 'Taigi įėjęs jis užrakino duris jiems abiems iš paskos ir meldėsi VIEŠPAČIUI.'),
  (@b12, 4, 34, 'Ir užlipęs ir atsigulęs ant vaiko, jis uždėjo savo burną ant jo burnos, savo akis ant jo akių ir savo rankas ant jo rankų; ir jis išsitiesė ant vaiko; ir vaiko kūnas sušilo.'),
  (@b12, 4, 35, 'Po to jis sugrįžo ir vaikščiojo namuose ten ir atgal; ir užlipo ir išsitiesė ant jo; ir vaikas sučiaudėjo septynis kartus, ir vaikas atmerkė akis.'),
  (@b12, 4, 36, 'Ir pašaukęs Gehazį, jis tarė: „Pašauk tą šunamietę“. Taigi jis pakvietė ją. Ir jai pas jį įėjus, jis tarė: „Paimk savo sūnų“.'),
  (@b12, 4, 37, 'Tada įėjusi ji parpuolė prie jo kojų, nusilenkė iki žemės ir, paėmusi savo sūnų, išėjo.'),
  (@b12, 4, 38, 'Ir Eliša sugrįžo į Gilgalą; o šalyje buvo badas; ir pranašų sūnūs sėdėjo jo akivaizdoje; ir jis tarė savo tarnui: „Uždėk didelį puodą ir išvirk pranašų sūnums viralo“.'),
  (@b12, 4, 39, 'Ir vienas, išėjęs ant lauko žolių parinkti, rado laukinį vijoklį ir nuo jo pririnko pilną savo sterblę laukinių moliūgų ir atėjęs supjaustė juos į viralo puodą; nes jie jų nepažino.'),
  (@b12, 4, 40, 'Taigi jie įpylė vyrams valgyti. Ir įvyko, kad jiems valgant viralą, jie šaukdami tarė: „Mirtis puode, o Dievo vyre“. Ir jie negalėjo jo valgyti.'),
  (@b12, 4, 41, 'Bet jis tarė: „Tad atneškite miltų“. Ir jis subėrė juos į puodą; ir jis tarė: „Įpilk tiems žmonėms, kad jie valgytų“. Ir puode nebuvo nieko kenksmingo.'),
  (@b12, 4, 42, 'Ir atėjo vyras iš Baal-Šališos ir atnešė Dievo vyrui pirmavaisių duonos: dvidešimt miežinių kepalų ir pilnų varpų su grūdais jų lukštuose. Ir jis tarė: „Duok žmonėms, kad jie valgytų“.'),
  (@b12, 4, 43, 'Ir jo tarnas tarė: „Ką, ar aš turiu tai padėti priešais šimtą vyrų?“ Jis vėl pasakė: „Duok žmonėms, kad jie valgytų; nes taip sako VIEŠPATS: ‘Jie valgys ir dar paliks’“.'),
  (@b12, 4, 44, 'Taigi jis padėjo tai prieš juos, o jie valgė, ir jų paliko, pagal VIEŠPATIES žodį.'),
  (@b12, 5, 1, 'Na, o Sirijos karaliaus kariuomenės vadas Naamanas buvo didis žmogus pas savo valdovą ir gerbiamas, nes per jį VIEŠPATS buvo davęs išgelbėjimą Sirijai; taip pat jis buvo galingas narsuolis, bet jis buvo raupsuotas.'),
  (@b12, 5, 2, 'Ir sirai buvo išėję būriais ir parvedė iš Izraelio šalies į nelaisvę mažą mergaitę; ir ji tarnavo Naamano žmonai.'),
  (@b12, 5, 3, 'Ir ji tarė savo valdovei: „O kad mano viešpats būtų pas Samarijoje esantį pranašą, nes jis pagydytų jį nuo jo raupsų!“'),
  (@b12, 5, 4, 'Ir vienas įėjęs pranešė savo viešpačiui, sakydamas: „Taip ir taip kalbėjo mergaitė, esanti iš Izraelio šalies“.'),
  (@b12, 5, 5, 'Ir Sirijos karalius tarė: „Nagi eik, aš pasiųsiu Izraelio karaliui laišką“. Ir jis išvyko, ir paėmė su savimi dešimtį talentų sidabro, šešis tūkstančius auksinių ir dešimtį drabužių pakaitų.'),
  (@b12, 5, 6, 'Ir jis nunešė Izraelio karaliui laišką, sakantį: „Na, o kai šitas laiškas bus atėjęs pas tave, štai aš su juo atsiunčiau pas tave savo tarną Naamaną, kad jį pagydytum nuo jo raupsų“.'),
  (@b12, 5, 7, 'Ir įvyko, kad Izraelio karalius, perskaitęs laišką, perplėšė savo drabužius ir tarė: „Ar aš Dievas, kuris nužudo ir atgaivina, kad šitas žmogus siunčia pas mane pagydyti vyrą nuo jo raupsų? Todėl meldžiu jus, apgalvokite ir žiūrėkite, kaip jis ieško priekabių prie manęs“.'),
  (@b12, 5, 8, 'Ir buvo, kai Dievo vyras Eliša išgirdo, kad Izraelio karalius persiplėšė savo drabužius, jis pasiuntė karaliui, sakydamas: „Kodėl persiplėšei savo drabužius? Tegul jis dabar ateina pas mane ir sužinos, kad Izraelyje yra pranašas“.'),
  (@b12, 5, 9, 'Taigi Naamanas atvyko su savo žirgais ir savo vežimu ir sustojo prie Elišos namų durų.'),
  (@b12, 5, 10, 'Ir Eliša siuntė pas jį pasiuntinį, sakydamas: „Eik ir nusiplauk septynis kartus Jordane, ir tau sugrįš tavo kūnas, ir tu būsi švarus“.'),
  (@b12, 5, 11, 'Bet Naamanas užsirūstino ir nuėjo, sakydamas: „Štai aš galvojau: ‘Jis tikrai išeis pas mane, atsistos, šauksis VIEŠPATIES, savo Dievo, vardo, suduos savo ranka per tą vietą ir pagydys raupsuotąjį.'),
  (@b12, 5, 12, 'Argi Damasko upės Abana ir Parparas nėra geresnės už visus Izraelio vandenis? Argi negalėčiau jose nusiplauti ir būti švarus?’“ Taigi jis apsigręžė ir nuėjo įniršęs.'),
  (@b12, 5, 13, 'O jo tarnai priėję jam kalbėjo, sakydami: „Mano tėve, jei pranašas tau būtų įsakęs padaryti kokį didelį dalyką, argi nebūtum to daręs? Tai kaip juo labiau, kai jis tau sako: ‘Nusiplauk ir būk švarus’“.'),
  (@b12, 5, 14, 'Tada jis nuėjo žemyn ir pasinėrė Jordane septynis kartus, pagal Dievo vyro pasakymą; ir jo kūnas sugrįžo, kaip mažo vaiko kūnas, ir jis buvo švarus.'),
  (@b12, 5, 15, 'Ir jis sugrįžo pas Dievo vyrą, jis ir visas jo būrys, ir atėjęs atsistojo prieš jį; ir jis tarė: „Štai dabar žinau, kad nėra Dievo visoje žemėje, išskyrus Izraelyje; todėl dabar, meldžiu tave, priimk palaiminimą nuo savo tarno“.'),
  (@b12, 5, 16, 'Bet jis tarė: „Kaip gyvas VIEŠPATS, kurio akivaizdoje stoviu, aš nieko neimsiu“. O jis primygtinai jo prašė, kad paimtų tai; bet jis atsisakė.'),
  (@b12, 5, 17, 'Ir Naamanas tarė: „Tad ar negalėtų būti duodama, meldžiu tave, tavo tarnui dviejų mulų našta žemių? Nes tavo tarnas nuo šiol nebeatnašaus nei deginamosios atnašos, nei aukos kitiems dievams, bet tik VIEŠPAČIUI.'),
  (@b12, 5, 18, 'Dėl šito dalyko tegul VIEŠPATS atleidžia tavo tarnui: kai mano valdovas įeis į Rimono namus ten garbinti ir jis pasirems ant mano rankos, ir aš nusilenksiu Rimono namuose; kai aš nusilenksiu Rimono namuose, dėl šito dalyko tegul VIEŠPATS atleidžia tavo tarnui“.'),
  (@b12, 5, 19, 'Ir jis tarė jam: „Eik ramybėje“. Taigi jis nuėjo nuo jo truputį kelio.'),
  (@b12, 5, 20, 'Bet Dievo vyro Elišos tarnas Gehazis tarė: „Štai mano valdovas pagailėjo šito siro Naamano, nepriimdamas iš jo rankos to, ką jis atgabeno; bet, kaip gyvas VIEŠPATS, aš bėgsiu paskui jį ir ką nors paimsiu iš jo“.'),
  (@b12, 5, 21, 'Taigi Gehazis nuėjo paskui Naamaną. Ir Naamanas, pamatęs jį atbėgantį jam iš paskos, nulipo nuo vežimo jo pasitikti ir tarė: „Ar viskas gerai?“'),
  (@b12, 5, 22, 'O jis tarė: „Viskas gerai. Mano valdovas siuntė mane, sakydamas: ‘Štai dabar yra atėję pas mane iš pranašų sūnų du jaunuoliai iš Efraimo kalno; duok jiems, meldžiu tave, talentą sidabro ir dvi drabužių pakaitas“.'),
  (@b12, 5, 23, 'Ir Naamanas tarė: „Teikis priimti du talentus“. Ir jis primygtinai jam siūlė ir įrišo du talentus sidabro į du maišus su dviem drabužių pakaitomis, ir uždėjo juos ant dviejų jo tarnų; ir jie nešė juos pirma jo.'),
  (@b12, 5, 24, 'Ir atėjęs prie bokšto jis paėmė juos iš jų rankų ir susidėjo juos namuose; ir jis paleido tuos vyrus, ir jie nuėjo.'),
  (@b12, 5, 25, 'Bet jis įėjo ir atsistojo prieš savo valdovą. Ir Eliša jam tarė: „Iš kur ateini, Gechazi?“ O jis tarė: „Tavo tarnas niekur nėjo“.'),
  (@b12, 5, 26, 'Ir jis jam tarė: „Argi mano širdis nėjo su tavimi, kai tas vyras sugrįžo nuo savo vežimo tavęs pasitikti? Argi tai metas imti pinigus ir imti drabužius, alyvmedžių sodus ir vynuogynus, avis ir jaučius, tarnus ir tarnaites?'),
  (@b12, 5, 27, 'Todėl Naamano raupsai prilips prie tavęs ir prie tavo sėklos per amžius“. Ir jis išėjo nuo jo raupsuotas, baltas kaip sniegas.'),
  (@b12, 6, 1, 'Ir pranašų sūnūs tarė Elišai: „Štai dabar vieta, kurioje gyvename su tavimi, yra mums per ankšta.'),
  (@b12, 6, 2, 'Eikime, meldžiame tave, prie Jordano, kiekvienas paimkime iš ten po rąstą ir pasistatykime ten sau vietą, kur galėtume gyventi“. Ir jis atsakė: „Eikite“.'),
  (@b12, 6, 3, 'Ir vienas tarė: „Teikis, meldžiu tave, eiti su savo tarnais“. Ir jis atsakė: „Eisiu“.'),
  (@b12, 6, 4, 'Taigi jis su jais nuėjo. Ir atėję prie Jordano jie kirto medžius.'),
  (@b12, 6, 5, 'Bet vienam bekertant rąstą, kirvio pentis įkrito į vandenį; ir jis sušuko, tardamas: „Vargas, valdove, ji buvo paskolinta!“'),
  (@b12, 6, 6, 'Ir Dievo vyras tarė: „Kur ji įkrito?“ Ir jis jam parodė tą vietą. Ir jis nupjovė pagalį ir jį ten įmetė; ir geležis išplaukė.'),
  (@b12, 6, 7, 'Todėl jis tarė: „Pasiimk ją“. Ir jis ištiesė savo ranką ir ją paėmė.'),
  (@b12, 6, 8, 'Tada Sirijos karalius kariavo prieš Izraelį ir tarėsi su savo tarnais, sakydamas: „Tokioje ir tokioje vietoje bus mano stovykla“.'),
  (@b12, 6, 9, 'Ir Dievo vyras pasiuntė Izraelio karaliui, sakydamas: „Saugokis, kad neitum pro tokią vietą; nes ten yra atėję sirai“.'),
  (@b12, 6, 10, 'Ir Izraelio karalius pasiuntė į tą vietą, apie kurią Dievo vyras jam buvo pasakęs ir įspėjęs, ir ten išsigelbėjo ne vieną ir ne du kartus.'),
  (@b12, 6, 11, 'Todėl Sirijos karaliaus širdis labai sunerimo dėl šito dalyko; ir jis, pašaukęs savo tarnus, tarė jiems: „Ar man nepasakysite, kas iš mūsų yra už Izraelio karalių?“'),
  (@b12, 6, 12, 'Ir vienas iš jo tarnų tarė: „Niekas, mano viešpatie, o karaliau; bet pranašas Eliša, esantis Izraelyje, praneša Izraelio karaliui žodžius, kuriuos tu kalbi savo miegamajame“.'),
  (@b12, 6, 13, 'Ir jis tarė: „Eikite ir ištirkite, kur jis yra, kad nusiųsčiau ir jį atvesčiau“. Ir jam buvo pranešta, sakant: „Štai jis Dotane“.'),
  (@b12, 6, 14, 'Taigi jis ten nusiuntė žirgų bei vežimų ir didelę kariuomenę; ir atvykę nakčia, jie apsupo tą miestą.'),
  (@b12, 6, 15, 'Ir Dievo vyro tarnui anksti atsikėlus ir išėjus, štai kariuomenė, apsupusi miestą su žirgais ir vežimais. Ir jo tarnas jam tarė: „Vargas, mano viešpatie! Kaip darysime?“'),
  (@b12, 6, 16, 'Ir jis atsakė: „Nebijok; nes daugiau yra tų, kurie yra su mumis, negu tų, kurie yra su jais“.'),
  (@b12, 6, 17, 'Ir Eliša meldėsi ir tarė: „VIEŠPATIE, meldžiu tave, atverk jo akis, kad matytų“. Ir VIEŠPATS atvėrė jaunuolio akis; ir jis matė: ir štai kalnas buvo pilnas ugninių žirgų ir vežimų aplink Elišą.'),
  (@b12, 6, 18, 'Ir jiems atėjus žemyn pas jį, Eliša meldėsi VIEŠPAČIUI, sakydamas: „Ištik, meldžiu tave, šitą tautą aklumu“. Ir jis ištiko juos aklumu pagal Elišos žodį.'),
  (@b12, 6, 19, 'Ir Eliša jiems tarė: „Tai ne tas kelias ir ne tas miestas; eikite paskui mane, o aš jus nuvesiu pas tą vyrą, kurio ieškote“. Bet jis juos nuvedė į Samariją.'),
  (@b12, 6, 20, 'Ir įvyko, kad jiems atėjus į Samariją, Eliša tarė: „VIEŠPATIE, atverk šitų žmonių akis, kad jie matytų“. Ir VIEŠPATS atvėrė jiems akis, ir jie pamatė; ir štai jie buvo Samarijos viduryje.'),
  (@b12, 6, 21, 'Ir Izraelio karalius, juos pamatęs, tarė Elišai: „Ar man juos sumušti, mano tėve? Ar man juos sumušti?“'),
  (@b12, 6, 22, 'O jis atsakė: „Nesumušk jų; argi sumuštum tuos, kuriuos paėmei į nelaisvę savo kalaviju ir savo lanku? Padėk priešais juos duonos ir vandens, kad jie valgytų ir gertų, ir eitų pas savo valdovą“.'),
  (@b12, 6, 23, 'Ir jis jiems paruošė daug maisto; ir jiems pavalgius ir atsigėrus, jis juos paleido, ir jie nuėjo pas savo valdovą. Taigi Sirijos būriai daugiau nebeatėjo į Izraelio šalį.'),
  (@b12, 6, 24, 'Ir po to įvyko, kad Sirijos karalius Ben-Hadadas, surinkęs visą savo kariuomenę, nuėjo aukštyn ir apgulė Samariją.'),
  (@b12, 6, 25, 'Ir buvo didelis badas Samarijoje; ir štai jie apgulė ją, kol asilo galva buvo parduodama už aštuoniasdešimt sidabrinių, o ketvirtis kabo balandžių mėšlo – už penkis sidabrinius.'),
  (@b12, 6, 26, 'Ir Izraelio karaliui einant ant sienos pro šalį, viena moteris jam šaukė, sakydama: „Padėk, mano viešpatie, o karaliau“.'),
  (@b12, 6, 27, 'Ir jis tarė: „Jei VIEŠPATS tau nepadeda, iš kur aš tau padėsiu? Iš klojimo ar iš vyno spaustuvo?“'),
  (@b12, 6, 28, 'Ir karalius jai tarė: „Kas tau yra?“ Ir ji atsakė: „Šita moteris man tarė: ‘Duok savo sūnų, kad jį šiandien valgytume, o mano sūnų rytoj valgysime’.'),
  (@b12, 6, 29, 'Taigi išsivirėme mano sūnų ir jį suvalgėme; o kitą dieną aš jai pasakiau: ‘Duok savo sūnų, kad jį valgytume’; bet ji paslėpė savo sūnų“.'),
  (@b12, 6, 30, 'Ir įvyko, kai karalius išgirdo tos moters žodžius, jis perplėšė savo drabužius; ir jis perėjo siena, ir liaudis pažiūrėjo, ir štai jis ant savo kūno turėjo apačioje pasivilkęs ašutinę.'),
  (@b12, 6, 31, 'Tada jis tarė: „Dievas tepadaro man taip ir dar daugiau, jei Šafato sūnaus Elišos galva šią dieną pasiliks ant jo“.'),
  (@b12, 6, 32, 'Bet Eliša sėdėjo savo namuose ir vyresnieji sėdėjo su juo; ir karalius pasiuntė nuo savo akivaizdos vyrą; bet pasiuntiniui dar neatėjus pas jį, jis tarė vyresniesiems: „Ar matote, kaip šitas žmogžudžio sūnus pasiuntė mano galvos nuimti? Žiūrėkite, kai pasiuntinys ateis, uždarykite duris ir tvirtai laikykite jį duryse; argi ne jo valdovo kojų garsas jo užnugaryje?“'),
  (@b12, 6, 33, 'Ir jam su jais tebekalbant, štai pas jį žemyn atėjo pasiuntinys; ir jis tarė: „Štai šita nelaimė yra nuo VIEŠPATIES; ko man dar belaukti iš VIEŠPATIES?“'),
  (@b12, 7, 1, 'Tada Eliša tarė: „Klausykite VIEŠPATIES žodžio; taip sako VIEŠPATS: „Rytoj, apie šį laiką, Samarijos vartuose smulkių miltų saikas bus parduodamas už šekelį, ir du saikai miežių už šekelį.'),
  (@b12, 7, 2, 'Tada viešpats, į kurio ranką karalius remdavosi, atsakydamas Dievo vyrui tarė: „Štai jei VIEŠPATS padarytų langų danguje, ar galėtų įvykti tas dalykas?“ Ir jis tarė: „Štai tu pamatysi tai savo akimis, bet to nevalgysi“.'),
  (@b12, 7, 3, 'Ir buvo keturi raupsuoti vyrai prie vartų įėjimo; ir jie sakė vienas kitam: „Ko mes čia sėdime, kol mirsime?'),
  (@b12, 7, 4, 'Jei sakytume: ‘Eisime į miestą’, tai badas mieste, ir ten mirsime; o jei čia dar sėdėtume, irgi mirtume. Taigi dabar eikime ir parpulkime į sirų kariuomenę; jei jie paliks mus gyvus, gyvensime; o jei jie mus nužudys, mirsime“.'),
  (@b12, 7, 5, 'Ir prieblandoje jie pakilo eiti į sirų stovyklą; ir jiems atėjus iki tolimiausios Sirijos stovyklos dalies, štai ten nebuvo nei vieno žmogaus.'),
  (@b12, 7, 6, 'Nes Viešpats padarė, kad sirų kariuomenė išgirstų vežimų triukšmą ir žirgų triukšmą – didelės kariuomenės triukšmą; ir jie sakė vienas kitam: „Štai Izraelio karalius pasamdė prieš mus hetitų karalius ir egiptiečių karalius, kad mus užpultų“.'),
  (@b12, 7, 7, 'Todėl pakilę jie pabėgo prieblandoje ir paliko savo palapines, savo žirgus ir savo asilus – stovyklą tokią, kokia ji buvo, ir pabėgo, gelbėdami savo gyvybę.'),
  (@b12, 7, 8, 'Ir šitie raupsuotieji, atėję į tolimiausią stovyklos dalį, įėjo į vieną palapinę, valgė, gėrė ir iš ten išnešė sidabro, aukso bei drabužių ir nuėję tai paslėpė; ir sugrįžę įėjo į kitą palapinę ir iš ten taip pat išnešė ir nuėję tai paslėpė.'),
  (@b12, 7, 9, 'Tada jie tarė vienas kitam: „Mes negerai darome; ši diena – geros naujienos diena, o mes tylime; jei pasiliksime iki ryto aušros, mus užklups kokia nors bėda; taigi dabar ateikite, kad eitume ir praneštume karaliaus namiškiams“.'),
  (@b12, 7, 10, 'Taigi atėję jie pašaukė miesto durininką; ir jiems pranešė, sakydami: „Mes atėjome į sirų stovyklą, ir štai ten nebuvo nei žmogaus, nei žmogaus balso, o tik pririšti žirgai bei pririšti asilai, o palapinės tokios, kokios buvo“.'),
  (@b12, 7, 11, 'Ir jis pašaukė durininkus; ir jie pranešė tai karaliaus namams viduje.'),
  (@b12, 7, 12, 'Ir karalius, naktį atsikėlęs, tarė savo tarnams: „Dabar jums pasakysiu, ką sirai mums padarė. Jie žino, kad mes alkani; todėl jie išėję iš stovyklos, kad pasislėptų ant lauko, sakydami: „Jiems išėjus iš miesto, juos sugausime gyvus ir įeisime į miestą“.'),
  (@b12, 7, 13, 'Ir vienas iš jo tarnų, atsakydamas tarė: „Meldžiu, tegul kas nors paima penkis iš likusių žirgų, išlikusių mieste (štai jie yra kaip visa jame išlikusi Izraelio daugybė; štai jie yra, aš sakau, būtent kaip visa išnaikinta izraelitų daugybė), ir pasiuntę pažiūrėkime“.'),
  (@b12, 7, 14, 'Taigi jie paėmė du vežimų žirgus; ir karalius pasiuntė paskui sirų kariuomenę, sakydamas: „Eikite ir pažiūrėkite“.'),
  (@b12, 7, 15, 'Ir jie ėjo paskui juos iki Jordano; ir štai visas kelias buvo pilnas drabužių ir įrankių, kuriuos sirai skubėdami išmėtė. Ir pasiuntiniai sugrįžę pranešė karaliui.'),
  (@b12, 7, 16, 'Ir tauta išėjo ir apiplėšė sirų palapines. Taigi saikas smulkių miltų buvo parduodamas už šekelį ir du saikai miežių už šekelį – pagal VIEŠPATIES žodį.'),
  (@b12, 7, 17, 'Ir karalius pavedė tam viešpačiui, į kurio ranką jis remdavosi, prižiūrėti vartus; o žmonės jį sumindė vartuose, ir jis mirė, kaip sakė Dievo vyras, kuris kalbėjo karaliui nusileidus pas jį.'),
  (@b12, 7, 18, 'Ir įvyko, kai Dievo vyras kalbėjo karaliui, sakydamas: „Rytoj, apie šį laiką, Samarijos vartuose du saikai miežių bus už šekelį ir saikas smulkių miltų už šekelį“;'),
  (@b12, 7, 19, 'o tas viešpats, atsakydamas Dievo vyrui, tarė: „Štai jei VIEŠPATS padarytų langų danguje, ar galėtų būti toks dalykas?“ O jis tarė: „Štai tu tai matysi savo akimis, tačiau to nevalgysi“.'),
  (@b12, 7, 20, 'Jam taip ir atsitiko; nes tauta jį mindė vartuose, ir jis mirė.'),
  (@b12, 8, 1, 'Tada Eliša kalbėjo moteriai, kurios sūnų jis buvo atgaivinęs, sakydamas: „Kelkis ir eik, tu pati ir tavo namiškiai, ir laikinai apsigyvenk, kur galėsi laikinai apsigyventi; nes VIEŠPATS pašaukė badą; ir jis ateis į šalį septyneriems metams“.'),
  (@b12, 8, 2, 'Ir ta moteris pakilo ir padarė pagal Dievo vyro pasakymą; ir ji nuėjo su savo namiškiais ir septynerius metus laikinai gyveno filistinų šalyje.'),
  (@b12, 8, 3, 'Ir įvyko, kad septyneriems metams pasibaigus ta moteris sugrįžo iš filistinų šalies; ir išėjo maldauti karaliaus dėl savo namų ir dėl savo žemės.'),
  (@b12, 8, 4, 'Ir karalius kalbėjo su Dievo vyro tarnu Gehaziu, sakydamas: „Papasakok man, meldžiu tave, visus didžius dalykus, kuriuos padarė Eliša“.'),
  (@b12, 8, 5, 'Ir įvyko, kad jam bepasakojant karaliui, kaip jis atgaivino numirusį kūną, štai ta moteris, kurios sūnų jis buvo atgaivinęs, maldavo karaliaus dėl savo namų ir dėl savo žemės. Ir Gehazis tarė: „Mano viešpatie, o karaliau, tai ta moteris ir tai jos sūnus, kurį atgaivino Eliša“.'),
  (@b12, 8, 6, 'Ir kai karalius paklausė tos moters, ji jam papasakojo. Taigi karalius jai paskyrė vieną pareigūną, sakydamas: „Sugrąžink viską, kas buvo jos, ir visus lauko vaisius nuo tos dienos, kai ji paliko šalį, iki šiol“.'),
  (@b12, 8, 7, 'Ir Eliša atėjo į Damaską; o Sirijos karalius Ben-Hadadas sirgo; ir jam buvo pranešta, sakant: „Dievo vyras yra čia atėjęs“.'),
  (@b12, 8, 8, 'Ir karalius tarė Hazaeliui: „Pasiimk į ranką dovaną ir eik Dievo vyro pasitikti, ir per jį pasiklausk VIEŠPATIES, sakydamas: ‘Ar pasveiksiu iš šitos ligos?’“'),
  (@b12, 8, 9, 'Taigi Hazaelis ėjo jo pasitikti, pasiėmęs su savimi dovaną, tai yra visokių Damasko gėrybių, keturiasdešimt kupranugarių naštų, ir atėjęs atsistojo prieš jį ir tarė: „Tavo sūnus Ben-Hadadas, Sirijos karalius, atsiuntė mane pas tave, sakydamas: ‘Ar pasveiksiu iš šitos ligos?’“'),
  (@b12, 8, 10, 'Ir Eliša jam tarė: „Eik, jam sakyk: ‘Tu tikrai pasveiksi’; tačiau VIEŠPATS man parodė, kad jis tikrai mirs“.'),
  (@b12, 8, 11, 'Ir jis įtempė savo žvilgsnį, kol tas susigėdo; ir Dievo vyras pravirko.'),
  (@b12, 8, 12, 'Ir Hazaelis tarė: „Kodėl mano viešpats verkia?“ Ir jis atsakė: „Dėl to, kad žinau, ką pikta tu padarysi Izraelio vaikams: tu padegsi jų tvirtoves, išžudysi kalaviju jų jaunuolius, sutraiškysi jų vaikus ir perskrosi jų nėščias moteris“.'),
  (@b12, 8, 13, 'O Hazaelis tarė: „Ką, ar tavo tarnas – šuo, kad galėtų padaryti tokį didelį dalyką?“ Ir Eliša atsakė: „VIEŠPATS man parodė, kad tu būsi Sirijos karalius“.'),
  (@b12, 8, 14, 'Taigi išėjęs iš Elišos, jis atėjo pas savo valdovą, kuris jam tarė: „Ką tau pasakė Eliša?“ Ir jis atsakė: „Jis man pasakė, kad tu tikrai pasveiksi’“.'),
  (@b12, 8, 15, 'Ir įvyko, kad rytojaus dieną, paėmęs storą audinį ir pamirkęs jį vandenyje, jis užtiesė jį jam ant veido, kad jis mirė; ir Hazaelis karaliavo jo vietoje.'),
  (@b12, 8, 16, 'Ir penktaisiais Joramo, sūnaus Ahabo – Izraelio karaliaus, metais, Jehozapatui tuomet esant Judos karaliumi, pradėjo karaliauti Judos karaliaus Jehozapato sūnus Jehoramas.'),
  (@b12, 8, 17, 'Jis buvo trisdešimt dviejų metų, kai pradėjo karaliauti; ir aštuonerius metus karaliavo Jeruzalėje.'),
  (@b12, 8, 18, 'Ir jis vaikščiojo Izraelio karalių keliu, kaip darė Ahabo namai; nes Ahabo duktė buvo jo žmona; ir jis darė pikta VIEŠPATIES akyse.'),
  (@b12, 8, 19, 'Tačiau VIEŠPATS nenorėjo sunaikinti Judos dėl savo tarno Dovydo, kaip jam pažadėjo visuomet duoti žiburį – jam ir jo vaikams.'),
  (@b12, 8, 20, 'Jo dienomis Edomas sukilo iš po Judos rankos ir paskyrė sau karalių.'),
  (@b12, 8, 21, 'Taigi Joramas perėjo į Cayrą ir su juo visi vežimai; ir naktį pakilęs, jis mušė edomiečius, kurie buvo apsupę jį ir vežimų vadus; o liaudis pabėgo į savo palapines.'),
  (@b12, 8, 22, 'Edomas sukilo iš po Judos rankos iki šios dienos. Tada, tuo pačiu laiku, sukilo Libna.'),
  (@b12, 8, 23, 'O kiti Joramo darbai ir visa, ką jis darė, argi jie nėra surašyti Judos karalių kronikų knygoje?'),
  (@b12, 8, 24, 'Ir Joramas užmigo prie savo tėvų ir buvo palaidotas prie savo tėvų Dovydo mieste; o jo sūnus Ahazijas karaliavo jo vietoje.'),
  (@b12, 8, 25, 'Dvyliktaisiais Joramo, sūnaus Ahabo – Izraelio karaliaus, metais pradėjo karaliauti Judos karaliaus Jehoramo sūnus Ahazijas.'),
  (@b12, 8, 26, 'Ahazijas buvo dvidešimt dvejų metų, kai pradėjo karaliauti; ir vienerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Atalija, Izraelio karaliaus Omrio duktė.'),
  (@b12, 8, 27, 'Ir jis vaikščiojo Ahabo namų keliu ir darė pikta VIEŠPATIES akyse, kaip darė Ahabo namai; nes jis buvo Ahabo namų žentas.'),
  (@b12, 8, 28, 'Ir jis ėjo su Ahabo sūnumi Joramu į karą prieš Sirijos karalių Hazaelį Ramot-Gileade; ir sirai sužeidė Joramą.'),
  (@b12, 8, 29, 'Ir karalius Joramas sugrįžo gydytis į Jezreelį nuo žaizdų, kurių jam buvo padarę sirai Ramoje, kai jis kovojo prieš Sirijos karalių Hazaelį. Ir Judos karaliaus Jehoramo sūnus Ahazijas nuėjo žemyn į Jezreelį aplankyti Ahabo sūnaus Joramo, nes jis sirgo.'),
  (@b12, 9, 1, 'Ir pranašas Eliša pašaukė vieną iš pranašų vaikų ir jam tarė: „Susijuosk strėnas, pasiimk į ranką šitą aliejaus indą ir eik į Ramot-Gileadą;'),
  (@b12, 9, 2, 'ir ten atėjęs, ieškok Nimšio sūnaus Jehozapato sūnaus Jehuvo, ir įėjęs liepk jam pakilti iš jo brolių tarpo ir įvesk jį į vidinį kambarį;'),
  (@b12, 9, 3, 'tada, paėmęs aliejaus indą, išpilk jį jam ant galvos ir tark: „Taip sako VIEŠPATS: „Aš tave patepiau Izraelio karaliumi“. Paskui, atidaręs duris, bėk ir nelauk“.'),
  (@b12, 9, 4, 'Taigi jaunuolis, tai yra jaunuolis pranašas, ėjo į Ramot-Gileadą.'),
  (@b12, 9, 5, 'Ir kai jis atėjo, štai sėdėjo kariuomenės vadai; ir jis tarė: „Turiu tau pavedimą, o vade“. O Jehuvas tarė: „Kuriam iš mūsų visų?“ Ir jis tarė: „Tau, o vade“.'),
  (@b12, 9, 6, 'Ir atsikėlęs jis įėjo į namus; ir jis išpylė aliejų jam ant galvos, ir jam tarė: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Aš tave patepiau karaliumi VIEŠPATIES tautai – Izraeliui.'),
  (@b12, 9, 7, 'Ir tu sumuši savo valdovo Ahabo namus, kad aš atkeršyčiau už savo tarnų pranašų kraują ir už visų VIEŠPATIES tarnų kraują Jezabelės rankoje.'),
  (@b12, 9, 8, 'Nes visi Ahabo namai pražus; ir aš iškirsiu iš Ahabo tą, kuris šlapinasi į sieną, ir tą, kuris yra užrakintas ir paliktas Izraelyje;'),
  (@b12, 9, 9, 'ir padarysiu Ahabo namus kaip Nebato sūnaus Jeroboamo namus ir kaip Ahijos sūnaus Baašos namus;'),
  (@b12, 9, 10, 'ir Jezabelę ės šunys Jezreelio dalyje, ir niekas jos nelaidos’“. Ir atidaręs duris jis pabėgo.'),
  (@b12, 9, 11, 'Tada Jehuvas išėjo pas savo viešpaties tarnus; ir vienas jam tarė: „Ar viskas gerai? Ko tas beprotis atėjo pas tave?“ O jis jiems tarė: „Jūs žinote tą žmogų ir jo kalbą“.'),
  (@b12, 9, 12, 'Ir jie tarė: „Tai melas; pasakyk mums dabar“. O jis tarė: „Taip ir taip jis man kalbėjo, sakydamas: ‘Taip sako VIEŠPATS: Aš tave patepiau Izraelio karaliumi’“.'),
  (@b12, 9, 13, 'Tada jie pasiskubino ir paėmė kiekvienas savo drabužį, klojo jį po juo ant laiptų viršaus ir pūtė trimitus, sakydami: „Jehuvas yra karalius“.'),
  (@b12, 9, 14, 'Taip Nimšio sūnaus Jehozapato sūnus Jehuvas surengė sąmokslą prieš Joramą (na, o Joramas saugojo Ramot-Gileadą, jis ir visas Izraelis, dėl Sirijos karaliaus Hazaelio.'),
  (@b12, 9, 15, 'Bet karalius Joramas buvo sugrįžęs gydytis Jezreelyje nuo žaizdų, kurių jam buvo padarę sirai, kai jis kovojo su Sirijos karaliumi Hazaeliu). Ir Jehuvas tarė: „Jei tai yra jūsų noras, tuomet niekas teneišeina nei nepabėga iš miesto, kad nenueitų ir to nepraneštų Jezreelyje“.'),
  (@b12, 9, 16, 'Taigi Jehuvas važiavo vežime ir vyko į Jezreelį; nes ten gulėjo Joramas. Ir Judos karalius Ahazijas buvo atėjęs žemyn Joramo aplankyti.'),
  (@b12, 9, 17, 'Ir sargybinis stovėjo bokšte Jezreelyje ir, pamatęs Jehuvo būrį, jam beatvažiuojant, jis tarė: „Matau būrį“. O Joramas tarė: „Imk raitelį ir nusiųsk jų pasitikti, ir tegul jis sako: ‘Ar taika?’“'),
  (@b12, 9, 18, 'Taigi vienas nuvyko raitas jo pasitikti ir tarė: „Taip sako karalius: ‘Ar taika?’“ O Jehuvas pasakė: „Kas tau darbo dėl taikos? Apsisuk man iš paskos“. Ir sargybinis pranešė, sakydamas: „Pasiuntinys atvyko pas juos, bet negrįžta“.'),
  (@b12, 9, 19, 'Tada jis išsiuntė antrą raitąjį, kuris pas juos atvykęs, tarė: „Taip sako karalius: „Ar taika?“ O Jehuvas atsakė: „Kas tau darbo dėl taikos? Apsisuk man iš paskos“.'),
  (@b12, 9, 20, 'Ir sargybinis pranešė, sakydamas: „Jis atėjo pas juos, bet negrįžta; o važiavimas – kaip Nimšio sūnaus Jehuvo važiavimas; nes jis važiuoja padūkusiai“.'),
  (@b12, 9, 21, 'Ir Joramas tarė: „Pakinkykit“. Ir jam pakinkė vežimą. Ir Izraelio karalius Joramas ir Judos karalius Ahazijas išvažiavo kiekvienas savo vežimu; ir jie išvažiavo prieš Jehuvą ir jį sutiko jezreeliečio Naboto dalyje.'),
  (@b12, 9, 22, 'Ir įvyko, kai Joramas pamatė Jehuvą, jis tarė: „Ar taika, Jehuvai?“ Ir jis atsakė: „Kokia taika, kol yra tiek daug tavo motinos Jezabelės paleistuvysčių ir jos raganavimų?“'),
  (@b12, 9, 23, 'Ir Joramas apsuko savo rankas ir bėgo, sakydamas Ahazijui: „Išdavystė, o Ahazijau“.'),
  (@b12, 9, 24, 'O Jehuvas iš visų jėgų įtempęs lanką, iššovė Joramui į tarpupetį, ir strėlė pervėrė jo širdį, ir jis susmuko savo vežime.'),
  (@b12, 9, 25, 'Tada Jehuvas tarė savo vadui Bidkarui: „Pakelk jį ir numesk ant jezreeliečio Naboto lauko sklypo; nes prisimink, kai aš ir tu jojome kartu paskui jo tėvą Ahabą, VIEŠPATS uždėjo ant jo šitą naštą:'),
  (@b12, 9, 26, '‘Tikrai aš vakar mačiau Naboto kraują ir jo sūnų kraują, – sako VIEŠPATS; – aš tau atlyginsiu ant šito žemės sklypo, – sako VIEŠPATS’. Todėl dabar paimk ir numesk jį ant žemės sklypo pagal VIEŠPATIES žodį“.'),
  (@b12, 9, 27, 'Bet tai pamatęs, Judos karalius Ahazijas bėgo sodo namo keliu. Ir Jehuvas sekė paskui jį ir sakė: „Sumuškite ir jį vežime“. Ir jie taip padarė Gūro pakilime, esančiame prie Ibleamo. Ir jis pabėgo į Megidą ir ten mirė.'),
  (@b12, 9, 28, 'O jo tarnai jį pargabeno vežime į Jeruzalę ir palaidojo jį jo kape prie jo tėvų Dovydo mieste.'),
  (@b12, 9, 29, 'O vienuoliktaisiais Ahabo sūnaus Joramo metais Ahazijas pradėjo karaliauti Judai.'),
  (@b12, 9, 30, 'Ir Jehuvui atvykus į Jezreelį, tai išgirdo Jezabelė; ji išsidažė veidą, pasipuošė galvą ir žiūrėjo pro langą.'),
  (@b12, 9, 31, 'Ir Jehuvui įeinant pro vartus, ji tarė: „Ar turėjo Zimris ramybę, nužudęs savo valdovą?“'),
  (@b12, 9, 32, 'O jis pakėlė savo veidą į langą ir tarė: „Kas su manimi? Kas?“ Ir du ar trys eunuchai pažvelgė į jį.'),
  (@b12, 9, 33, 'Ir jis tarė: „Meskite ją žemyn“. Taigi jie numetė ją žemyn; ir jos kraujo užtiško ant sienos bei žirgų; ir jis ją mindė po kojomis.'),
  (@b12, 9, 34, 'Ir įėjęs į vidų jis valgė, gėrė ir tarė: „Eikite ir žiūrėkite dabar tą prakeiktąją ir ją palaidokite; nes ji yra karaliaus duktė“.'),
  (@b12, 9, 35, 'Ir jie nuėjo jos laidoti; bet jie nieko iš jos neberado, tik kaukolę, pėdas ir jos rankų plaštakas.'),
  (@b12, 9, 36, 'Todėl jie sugrįžo ir jam pranešė. Ir jis tarė: „Tai VIEŠPATIES žodis, kurį jis kalbėjo per savo tarną tišbietį Eliją, sakydamas: ‘Jezreelio dalyje šunys ės Jezabelės kūną;'),
  (@b12, 9, 37, 'ir Jezabelės lavonas bus kaip mėšlas lauko paviršiuje, Jezreelio dalyje; kad nesakytų: ‘Tai Jezabelė’“.'),
  (@b12, 10, 1, 'Ir Ahabas turėjo septyniasdešimt sūnų Samarijoje. Ir Jehuvas parašė laiškus ir nusiuntė į Samariją Jezreelio valdovams, vyresniesiems ir Ahabo vaikų augintojams, sakydamas:'),
  (@b12, 10, 2, '„Dabar, kai tik šitas laiškas pas jus ateis, kadangi pas jus yra jūsų valdovo sūnūs ir pas jus yra vežimų bei žirgų, taipogi aptvertas miestas ir ginklų;'),
  (@b12, 10, 3, 'išsirinkite geriausią ir tinkamiausią iš savo valdovo sūnų, pasodinkite jį į jo tėvo sostą ir kovokite už savo valdovo namus“.'),
  (@b12, 10, 4, 'Bet jie labai išsigando ir tarė: „Štai du karaliai neatsilaikė prieš jį; tai kaip mes atsilaikysime?“'),
  (@b12, 10, 5, 'Ir namų valdytojas, miesto valdytojas, vyresnieji ir vaikų augintojai pasiuntė Jehuvui, sakydami: „Mes esame tavo tarnai ir darysime viską, ką mums liepsi; mes nepaskirsime nei vieno karaliumi; daryk tai, kas yra gera tavo akyse“.'),
  (@b12, 10, 6, 'Tada jis jiems parašė laišką antrą kartą, sakydamas: „Jei jūs esate mano ir jei norite klausyti mano balso, paimkite vyrų, savo valdovo sūnų, galvas ir rytoj šiuo laiku ateikite pas mane į Jezreelį“. Na, o karaliaus sūnūs, septyniasdešimt asmenų, buvo pas miesto didžiūnus, kurie juos augino.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b12, 10, 7, 'Ir įvyko, kad laiškui pas juos atėjus, jie paėmė karaliaus sūnus ir užmušė tuos septyniasdešimt asmenų, sudėjo jų galvas į pintines ir nusiuntė pas jį į Jezreelį.'),
  (@b12, 10, 8, 'Ir atėjęs pasiuntinys jam pranešė, sakydamas: „Jie atnešė karaliaus sūnų galvas“. Ir jis tarė: „Sudėkite jas iki ryto į dvi krūvas vartų įėjime“.'),
  (@b12, 10, 9, 'Ir įvyko, kad ryte, išėjęs ir atsistojęs, jis tarė visai tautai: „Jūs teisūs; štai aš surengiau sąmokslą prieš savo valdovą ir jį nužudžiau; bet kas užmušė visus šituos?'),
  (@b12, 10, 10, 'Dabar žinokite, kad iš VIEŠPATIES žodžio, kurį VIEŠPATS kalbėjo apie Ahabo namus, niekas nenukris žemėn; nes VIEŠPATS padarė tai, ką jis kalbėjo per savo tarną Eliją“.'),
  (@b12, 10, 11, 'Taigi Jehuvas užmušė visus likusius iš Ahabo namų Jezreelyje, visus jo didžiūnus, jo giminaičius ir jo kunigus, kol jis nepaliko jam nei vieno išlikusio.'),
  (@b12, 10, 12, 'Ir pakilęs jis išėjo ir atvyko į Samariją. Ir jam esant kelyje prie avių kirpimo namų,'),
  (@b12, 10, 13, 'Jehuvas sutiko Judos karaliaus Ahazijo brolius ir tarė: „Kas jūs esate?“ O jie atsakė: „Mes esame Ahazijo broliai; ir mes einame žemyn pasveikinti karaliaus vaikų ir karalienės vaikų“.'),
  (@b12, 10, 14, 'Ir jis tarė: „Suimkite juos gyvus“. Ir sučiupę juos gyvus, jie nužudė juos prie avių kirpimo namų duobės – keturiasdešimt du vyrus; nei vieno iš jų jis nepaliko.'),
  (@b12, 10, 15, 'Ir iš ten išvykęs, jis užtiko Rechabo sūnų Jehonadabą, ateinantį jo pasitikti; ir jis pasveikino jį ir jam tarė: „Ar tavo širdis teisinga kaip ir mano širdis su tavo širdimi?“ Ir Jehonadabas atsakė: „Taip“. „Jei taip, tai duok man savo ranką“. Ir jis padavė jam savo ranką; ir jis užsikėlė jį pas save į vežimą.'),
  (@b12, 10, 16, 'Ir jis tarė: „Eikš su manimi ir pamatyk mano uolumą dėl VIEŠPATIES“. Taigi jie jį vežė jo vežime.'),
  (@b12, 10, 17, 'Ir atvykęs į Samariją jis užmušė visus išlikusius Ahabui Samarijoje, kol sunaikino jį pagal VIEŠPATIES pasakymą, kurį jis kalbėjo Elijui.'),
  (@b12, 10, 18, 'Ir Jehuvas, surinkęs visą tautą, jiems tarė: „Ahabas mažai tarnavo Baalui; bet Jehuvas jam daug tarnaus.'),
  (@b12, 10, 19, 'Tad dabar sušaukite pas mane visus Baalo pranašus, visus jo tarnus ir visus jo kunigus; tenetrūksta nei vieno; nes turiu aukoti Baalui didelę auką; kurio trūks, tas neišliks gyvas“. Bet Jehuvas tai darė su gudrumu, tam, kad išnaikintų Baalo garbintojus.'),
  (@b12, 10, 20, 'Ir Jehuvas tarė: „Paskelbkite Baalui iškilmingą susirinkimą“. Ir jie paskelbė.'),
  (@b12, 10, 21, 'Ir Jehuvas pasiuntė po visą Izraelį; ir atėjo visi Baalo garbintojai, kad nepaliko nei vieno, kuris nebūtų atėjęs. Ir jie atėjo į Baalo namus; ir Baalo namai buvo pilni nuo vieno galo iki kito.'),
  (@b12, 10, 22, 'Ir jis tarė drabužinės prižiūrėtojui: „Išnešk drabužius visiems Baalo garbintojams“. Ir jis išnešė jiems drabužius.'),
  (@b12, 10, 23, 'Ir Jehuvas, įėjęs su Rechabo sūnumi Jehonadabu į Baalo namus, sakė Baalo garbintojams: „Apieškokite ir žiūrėkite, kad čia nebūtų su jumis nei vieno iš VIEŠPATIES tarnų, bet vien tik Baalo garbintojai“.'),
  (@b12, 10, 24, 'Ir jiems įėjus aukų ir deginamųjų atnašų atnašauti, Jehuvas paskyrė lauke aštuoniasdešimt vyrų ir pasakė: „Jei kas iš tų vyrų, kuriuos atvesiu į jūsų rankas, pabėgs, tuomet to, kuris jį paleis, gyvybė bus už ano gyvybę“.'),
  (@b12, 10, 25, 'Ir įvyko, kad vos tik baigęs atnašauti deginamąją atnašą, Jehuvas pasakė sargybiniams ir vadams: „Įeikite, išžudykite juos; niekas teneišeina“. Ir jie išžudė juos kalavijo ašmenimis; ir sargybiniai bei vadai juos išmetė ir nuėjo į Baalo namų miestą.'),
  (@b12, 10, 26, 'Ir išnešę iš Baalo namų atvaizdus, jie juos sudegino.'),
  (@b12, 10, 27, 'Ir jie sudaužė Baalo atvaizdą, sugriovė Baalo namus ir juos padarė išviete, iki šios dienos.'),
  (@b12, 10, 28, 'Taip Jehuvas išnaikino Baalą iš Izraelio.'),
  (@b12, 10, 29, 'Tačiau nuo nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti, Jehuvas neatsitraukė, tai yra nuo sekimo paskui auksinius veršius, esančius Bet-Elyje ir esančius Dane.'),
  (@b12, 10, 30, 'Ir VIEŠPATS tarė Jehuvui: „Kadangi gerai padarei, vykdydamas tai, kas teisinga mano akyse, ir padarei Ahabo namams pagal visa tai, kas buvo mano širdyje, tai ir ketvirtosios kartos tavo vaikai sėdės Izraelio soste“.'),
  (@b12, 10, 31, 'Bet Jehuvui nerūpėjo vaikščioti VIEŠPATIES, Izraelio Dievo, įstatyme visa širdimi; nes jis neatsitraukė nuo nuodėmių Jeroboamo, kuris skatino Izraelį nusidėti.'),
  (@b12, 10, 32, 'Tomis dienomis VIEŠPATS pradėjo atkirtinėti Izraelio dalis; ir Hazaelis juos sumušė visose Izraelio ribose:'),
  (@b12, 10, 33, 'nuo Jordano į rytus, visą Gileado šalį, gadus, rubenus ir manasus, nuo Aroero, esančio prie Arnono upės, Gileadą ir Bašaną.'),
  (@b12, 10, 34, 'Na, o kiti Jehuvo darbai ir visa, ką jis darė, ir visa jo galia, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 10, 35, 'Ir Jehuvas užmigo prie savo tėvų; ir jį palaidojo Samarijoje. O jo sūnus Jehoachazas karaliavo jo vietoje.'),
  (@b12, 10, 36, 'O laiko, kuriuo Jehuvas karaliavo Izraeliui Samarijoje, buvo dvidešimt aštuoneri metai.'),
  (@b12, 11, 1, 'Ir Ahazijo motina Atalija, matydama, kad jos sūnus miręs, pakilo ir sunaikino visą karališkąją sėklą.'),
  (@b12, 11, 2, 'Bet karaliaus Joramo duktė Jehošeba, Ahazijo sesuo, paėmė Ahazijo sūnų Joašą ir jį pavogė iš tarpo karaliaus sūnų, kurie buvo žudomi; ir paslėpė jį, tai yra jį ir jo auklę, miegamajame nuo Atalijos taip, kad jis nebuvo užmuštas.'),
  (@b12, 11, 3, 'Ir jis šešerius metus buvo su ja paslėptas VIEŠPATIES namuose. O Atalija valdė šalį.'),
  (@b12, 11, 4, 'Ir septintaisias metais Jehojada pasiuntė ir atvedė šimtininkus su vadais bei sargyba ir juos įvedė pas save į VIEŠPATIES namus, ir sudarė su jais sandorą, ir prisaikdino juos VIEŠPATIES namuose, ir jiems parodė karaliaus sūnų.'),
  (@b12, 11, 5, 'Ir jis jiems įsakė, sakydamas: „Štai ką turite daryti: trečdalis jūsų, kurie įeinate per sabatą, eisite karaliaus namų sargybą;'),
  (@b12, 11, 6, 'trečdalis būsite prie Sūro vartų; o trečdalis prie vartų sargybos užnugaryje; taip jūs eisite tų namų sargybą, kad jų nesugriautų.'),
  (@b12, 11, 7, 'O dvi dalys iš visų jūsų, kurie išeinate per sabatą, turės eiti VIEŠPATIES namų sargybą aplink karalių.'),
  (@b12, 11, 8, 'Ir apsupkite karalių aplinkui, kiekvienas su savo ginklu rankoje; o kas įeis į eiles, tas tebūna nužudytas; ir jūs būkite su karaliumi jam išeinant ir jam įeinant“.'),
  (@b12, 11, 9, 'Ir šimtininkai padarė pagal visa, ką įsakė kunigas Jehojada: jie kiekvienas pasiėmė savo vyrus, įeinančius per sabatą, drauge su išeinančiais per sabatą, ir atėjo pas kunigą Jehojadą.'),
  (@b12, 11, 10, 'Ir kunigas padavė šimtininkams karaliaus Dovydo ietis ir skydus, esančius VIEŠPATIES šventykloje.'),
  (@b12, 11, 11, 'Ir sargyba stovėjo, kiekvienas su savo ginklu rankoje, aplink karalių nuo dešiniojo šventyklos šono iki kairiojo šventyklos šono, išilgai palei aukurą ir šventyklą.'),
  (@b12, 11, 12, 'Ir jis išvedė karaliaus sūnų, uždėjo jam karūną ir padavė jam liudijimą; ir jie padarė jį karaliumi ir jį patepė; ir jie plojo rankomis ir sakė: „Tegyvuoja karalius!“'),
  (@b12, 11, 13, 'O Atalija, išgirdusi sargybos ir tautos triukšmą, atėjo pas tautą į VIEŠPATIES šventyklą.'),
  (@b12, 11, 14, 'Ir ji pažiūrėjo, ir štai karalius stovėjo prie stulpo pagal paprotį, o kunigaikščiai bei trimitininkai šalia karaliaus, ir visa šalies tauta džiaugėsi ir pūtė trimitais; ir Atalija perplėšė savo drabužius ir šaukė: „Išdavystė! Išdavystė!“'),
  (@b12, 11, 15, 'Bet kunigas Jehojada įsakė šimtų vadams, kariuomenės pareigūnams, ir jiems tarė: „Išveskite ją iš eilių; o kas ją seks, tą nužudykite kalaviju“. Nes kunigas buvo pasakęs: „Tenebūna ji nužudyta VIEŠPATIES namuose“.'),
  (@b12, 11, 16, 'Ir jie uždėjo ant jos rankas; ir ji ėjo keliu, kuriuo į karaliaus namus įeina žirgai; ir ten ji buvo nužudyta.'),
  (@b12, 11, 17, 'Ir Jehojada sudarė sandorą tarp VIEŠPATIES ir karaliaus bei tautos, kad jie būtų VIEŠPATIES tauta; taip pat tarp karaliaus ir tautos.'),
  (@b12, 11, 18, 'Ir visa šalies tauta įėjo į Baalo namus ir juos sugriovė; jo aukurus ir jo atvaizdus jie visiškai sutrupino, ir Baalo kunigą Mataną nužudė prieš aukurus. Ir kunigas paskyrė pareigūnus VIEŠPATIES namams.'),
  (@b12, 11, 19, 'Ir jis paėmė šimtininkus, vadus, sargybą ir visą šalies tautą; ir jie nuvedė žemyn karalių iš VIEŠPATIES namų ir atėjo sargybos vartų keliu į karaliaus namus. Ir jis atsisėdo į karalių sostą.'),
  (@b12, 11, 20, 'Ir džiaugėsi visa šalies tauta, ir miestas buvo ramus; ir jie nužudė Ataliją kalaviju šalia karaliaus namų.'),
  (@b12, 11, 21, 'Jehoašas buvo septynerių metų, kai pradėjo karaliauti.'),
  (@b12, 12, 1, 'Septintaisiais Jehuvo metais Jehoašas pradėjo karaliauti; ir keturiasdešimt metų karaliavo Jeruzalėje. O jo motinos vardas buvo Cibija iš Beer-Šebos.'),
  (@b12, 12, 2, 'Ir Jehoašas darė tai, kas buvo teisinga VIEŠPATIES akyse per visas savo dienas, kuriose jį mokė kunigas Jehojada.'),
  (@b12, 12, 3, 'Bet aukštumos nebuvo pašalintos; tauta tebeaukojo ir tebedegino smilkalus aukštumose.'),
  (@b12, 12, 4, 'Ir Jehoašas tarė kunigams: „Visus pašvęstų dalykų pinigus, atnešamus į VIEŠPATIES namus, būtent pinigus kiekvieno, praeinančiojo atsiskaitymą, pinigus, kuriais įvertinami asmenys, ir visus pinigus, ateinančius kiekvienam į širdį, kad atneštų į VIEŠPATIES namus,'),
  (@b12, 12, 5, 'tegul juos pasiima kunigai, kiekvienas iš savo pažįstamų; ir jie teužtaiso namų spragas, kur tik atsiras kokia spraga“.'),
  (@b12, 12, 6, 'Bet buvo taip, kad dvidešimt trečiaisiais karaliaus Jehoašo metais kunigai nebuvo užtaisę namų spragų.'),
  (@b12, 12, 7, 'Tada karalius Jehoašas, pašaukęs kunigą Jehojadą ir kitus kunigus, jiems tarė: „Kodėl jūs neužtaisote namų spragų? Taigi dabar nebeimkite pinigų iš savo pažįstamų, bet atiduokite juos namų spragoms“.'),
  (@b12, 12, 8, 'Ir kunigai sutiko nebeimti pinigų iš tautos ir netaisyti namų spragų.'),
  (@b12, 12, 9, 'Bet kunigas Jehojada paėmė skrynią, išgręžė jos dangtyje skylę ir padėjo ją šalia aukuro, dešinėje pusėje, kur įeinama į VIEŠPATIES namus; o kunigai, kurie saugojo duris, įdėdavo į ją visus pinigus, atneštus į VIEŠPATIES namus.'),
  (@b12, 12, 10, 'Ir jiems pamačius, kad skrynioje buvo daug pinigų, ateidavo aukštyn karaliaus raštininkas ir aukščiausiasis kunigas; ir jie sudėdavo į maišus ir suskaičiuodavo pinigus, rastus VIEŠPATIES namuose.'),
  (@b12, 12, 11, 'Ir jie paduodavo suskaičiuotus pinigus į rankas tų, kurie atlikdavo darbą, kurie prižiūrėdavo VIEŠPATIES namus; o jie juos išleisdavo dailidėms ir statytojams, dirbantiems VIEŠPATIES namuose,'),
  (@b12, 12, 12, 'mūrininkams ir akmens tašytojams, ir medienai bei tašytiems akmenims pirkti, kad užtaisytų VIEŠPATIES namų spragas, ir visoms namų taisymo išlaidoms.'),
  (@b12, 12, 13, 'Tačiau sidabrinės taurės, gnybtuvai, dubenys, trimitai, bet kokie auksiniai ar sidabriniai indai nebuvo daromi VIEŠPATIES namams iš pinigų, atnešamų į VIEŠPATIES namus;'),
  (@b12, 12, 14, 'bet juos davė darbininkams, ir už juos taisė VIEŠPATIES namus.'),
  (@b12, 12, 15, 'Be to, jie neatsiskaitinėdavo su vyrais, į kurių rankas atiduodavo pinigus, kad būtų paduoti darbininkams; nes jie elgėsi ištikimai.'),
  (@b12, 12, 16, 'Nusižengimo pinigai ir nuodėmės pinigai nebūdavo atnešami į VIEŠPATIES namus: jie buvo kunigų.'),
  (@b12, 12, 17, 'Tada Sirijos karalius Hazaelis ėjo aukštyn ir kovojo prieš Gatą, ir jį paėmė; ir Hazaelis nukreipė savo veidą eiti aukštyn į Jeruzalę.'),
  (@b12, 12, 18, 'Ir Judos karalius Jehoašas, paėmė visus pašvęstus dalykus, kuriuos buvo pašventę jo tėvai Jehozapatas, Jehoramas ir Ahazijas, Judos karaliai, ir savo paties pašvęstus dalykus ir visą auksą, rastą VIEŠPATIES namų ižduose ir karaliaus namuose, ir nusiuntė tai Sirijos karaliui Hazaeliui; ir jis pasitraukė nuo Jeruzalės.'),
  (@b12, 12, 19, 'O kiti Joašo darbai ir visa, ką jis darė, argi jie nėra surašyti Judos karalių kronikų knygoje?'),
  (@b12, 12, 20, 'Ir jo tarnai pakilę surengė sąmokslą ir užmušė Joašą namuose Milojo, kuris nusileidžia į Silą.'),
  (@b12, 12, 21, 'Nes Šimato sūnus Jozacharas ir Šomero sūnus Jehozabadas, jo tarnai, jį sumušė, ir jis mirė; ir jį palaidojo prie jo tėvų Dovydo mieste; o jo sūnus Amacijas karaliavo jo vietoje.'),
  (@b12, 13, 1, 'Dvidešimt trečiaisiais Joašo, sūnaus Ahazijo – Judos karaliaus, metais Jehuvo sūnus Jehoachazas pradėjo karaliauti Izraeliui Samarijoje, ir karaliavo septyniolika metų.'),
  (@b12, 13, 2, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse ir sekė nuodėmėmis Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti; jis neatsitraukė nuo jų.'),
  (@b12, 13, 3, 'Ir VIEŠPATIES pyktis užsidegė prieš Izraelį, ir jis atidavė juos į Sirijos karaliaus Hazaelio rankas ir Hazaelio sūnaus Ben-Hadado rankas per visas jų dienas.'),
  (@b12, 13, 4, 'Ir Jehoachazas maldavo VIEŠPATĮ, ir VIEŠPATS jį išklausė; nes jis matė Izraelio priespaudą, nes Sirijos karalius juos engė'),
  (@b12, 13, 5, '(ir VIEŠPATS davė Izraeliui gelbėtoją, kad jie išėjo iš po sirų rankos; ir Izraelio vaikai gyveno savo palapinėse, kaip anksčiau.'),
  (@b12, 13, 6, 'Tačiau jie neatsitraukė nuo nuodėmių namų Jeroboamo, kuris skatino Izraelį nusidėti, bet vaikščiojo jose; taip pat ir giraitė išliko Samarijoje).'),
  (@b12, 13, 7, 'Ir jis nepaliko Jehoachazui iš tautos nieko, o tik penkiasdešimt raitelių, dešimt vežimų ir dešimt tūkstančių pėstininkų; nes Sirijos karalius buvo juos sunaikinęs ir padaręs juos kaip dulkes per kūlimą.'),
  (@b12, 13, 8, 'Na, o kiti Jehoachazo darbai, visa, ką jis padarė, ir jo galybė, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 13, 9, 'Ir Jehoachazas užmigo prie savo tėvų; ir jį palaidojo Samarijoje; o jo sūnus Joašas karaliavo jo vietoje.'),
  (@b12, 13, 10, 'Trisdešimt septintaisiais Judos karaliaus Joašo metais Jehoachazo sūnus Jehoašas pradėjo karaliauti Izraeliui Samarijoje, ir karaliavo šešiolika metų.'),
  (@b12, 13, 11, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse; jis neatsitraukė nuo visų nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti; bet jis vaikščiojo jose.'),
  (@b12, 13, 12, 'O kiti Joašo darbai ir visa, ką jis darė, ir jo galybė, kuria jis kovojo prieš Judos karalių Amaciją, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 13, 13, 'Ir Joašas užmigo prie savo tėvų; o Jeroboamas atsisėdo į jo sostą; ir Joašas buvo palaidotas Samarijoje prie Izraelio karalių.'),
  (@b12, 13, 14, 'Na, o Eliša susirgo savo liga, nuo kurios jis mirė. Ir pas jį atėjo žemyn Izraelio karalius Joašas ir verkdamas virš jo veido, tarė: „O mano tėve, mano tėve, Izraelio vežimai ir jo raiteliai!“'),
  (@b12, 13, 15, 'Ir Eliša jam tarė: „Paimk lanką ir strėlių“. Ir jis paėmė jam lanką ir strėlių.'),
  (@b12, 13, 16, 'Ir jis tarė Izraelio karaliui: „Uždėk savo ranką ant lanko“. Ir jis uždėjo savo ranką ant jo; o Eliša uždėjo savo rankas ant karaliaus rankų.'),
  (@b12, 13, 17, 'Ir jis tarė: „Atidaryk langą į rytus“. Ir jis atidarė. Tada Eliša tarė: „Šauk“. Ir jis šovė. Ir jis tarė: „VIEŠPATIES išvadavimo strėlė, išvadavimo iš Sirijos strėlė; nes tu sumuši sirus Afeke, kol juos sunaikinsi“.'),
  (@b12, 13, 18, 'Ir jis tarė: „Paimk strėles“. Ir jis paėmė. Ir jis tarė Izraelio karaliui: „Suduok į žemę“. Ir jis sudavė tris kartus ir sustojo.'),
  (@b12, 13, 19, 'Ir Dievo vyras užsirūstino ant jo ir tarė: „Reikėjo suduoti penkis ar šešis kartus; tada būtum sumušęs Siriją, kol ją būtum sunaikinęs; o dabar tik triskart sumuši Siriją“.'),
  (@b12, 13, 20, 'Ir Eliša mirė, ir jį palaidojo. Ir moabiečių pulkai įsiveržė į šalį metų pradžioje.'),
  (@b12, 13, 21, 'Ir jiems laidojant vyrą atsitiko, kad štai jie pamatė vyrų pulką; ir jie įmetė tą vyrą į Elišos kapą; o kai tas vyras nusileidęs palietė Elišos kaulus, jis atgijo ir atsistojo ant kojų.'),
  (@b12, 13, 22, 'Bet Sirijos karalius Hazaelis engė Izraelį per visas Jehoachazo dienas.'),
  (@b12, 13, 23, 'Ir VIEŠPATS buvo jiems maloningas, gailėjosi jų ir atsižvelgė į juos dėl savo sandoros su Abraomu, Izaoku ir Jokūbu, ir nenorėjo jų sunaikinti, ir jų dar neatmetė nuo savo veido.'),
  (@b12, 13, 24, 'Taigi mirė Sirijos karalius Hazaelis; o jo sūnus Ben-Hadadas karaliavo jo vietoje.'),
  (@b12, 13, 25, 'Ir Jehoachazo sūnus Jehoašas atsiėmė iš Hazaelio sūnaus Ben-Hadado rankos miestus, kuriuos jis karu buvo atėmęs iš jo tėvo Jehoachazo rankos. Tris kartus Joašas jį sumušė ir atgavo Izraelio miestus.'),
  (@b12, 14, 1, 'Antraisiais Izraelio karaliaus Jehoachazo sūnaus Joašo metais karaliavo Judos karaliaus Joašo sūnus Amacijas.'),
  (@b12, 14, 2, 'Jis buvo dvidešimt penkerių metų, kai pradėjo karaliauti, ir dvidešimt devynerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Jehoadina, iš Jeruzalės.'),
  (@b12, 14, 3, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, tačiau ne kaip jo tėvas Dovydas; jis darė pagal visa tai, kaip darė jo tėvas Joašas.'),
  (@b12, 14, 4, 'Tačiau aukštumos nebuvo pašalintos; tauta vis dar aukojo ir degino smilkalus aukštumose.'),
  (@b12, 14, 5, 'Ir įvyko, kai tik karalystė įsitvirtino jo rankoje, jis užmušė savo tarnus, kurie buvo nužudę jo tėvą karalių.'),
  (@b12, 14, 6, 'Bet žudikų vaikų jis nenužudė; pagal tai, kas parašyta Mozės įstatymo knygoje, kurioje VIEŠPATS įsakė, sakydamas: „Tėvai nebus užmušami už vaikus, nei vaikai nebus užmušami už tėvus; bet kiekvienas bus užmušamas už savo paties nuodėmę“.'),
  (@b12, 14, 7, 'Jis Druskos slėnyje iš Edomo užmušė dešimtį tūkstančių, karu paėmė Selą ir praminė ją Jokteelio vardu, iki šios dienos.'),
  (@b12, 14, 8, 'Tada Amacijas siuntė pasiuntinius pas Jehoašą, sūnų Jehoachazo, sūnų Jehuvo, Izraelio karalių, sakydamas: „Ateik, žiūrėkime vienas kitam į veidą“.'),
  (@b12, 14, 9, 'Ir Izraelio karalius Jehoašas pasiuntė Judos karaliui Amacijui, sakydamas: „Libane esanti usnis siuntė Libane esančiam kedrui, sakydama: ‘Duok mano sūnui savo dukterį į žmonas’; ir praėjo laukinis žvėris, esantis Libane, ir sutrypė usnį.'),
  (@b12, 14, 10, 'Tu tikrai sumušei Edomą, ir tavo širdis iškėlė tave; girkis tuo ir pasilik namie; nes kodėl gi turėtum įsivelti savo žalai, kad kristum tu pats ir Juda su tavimi?“'),
  (@b12, 14, 11, 'Bet Amacijas nenorėjo klausyti. Todėl Izraelio karalius Jehoašas ėjo aukštyn; ir jis ir Judos karalius Amacijas žiūrėjo vienas kitam į veidą Bet-Šemeše, priklausančiame Judai.'),
  (@b12, 14, 12, 'Ir Juda buvo nugalėta Izraelio akivaizdoje; ir jie kiekvienas pabėgo į savo palapines.'),
  (@b12, 14, 13, 'O Judos karalių Amaciją, Ahazijo sūnaus Jehoašo sūnų, Izraelio karalius Jehoašas paėmė Bet-Šemeše ir atėjęs į Jeruzalę nugriovė Jeruzalės sieną nuo Efraimo vartų iki Kampo vartų, keturis šimtus uolekčių.'),
  (@b12, 14, 14, 'Ir paėmęs visą auksą bei sidabrą ir visus indus, rastus VIEŠPATIES namuose ir karaliaus namų ižduose, ir įkaitus, jis sugrįžo į Samariją.'),
  (@b12, 14, 15, 'Na, o kiti Jehoašo darbai, kuriuos jis darė, ir jo galybė, ir kaip jis kovojo su Judos karaliumi Amaciju, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 14, 16, 'Ir Jehoašas užmigo prie savo tėvų ir buvo palaidotas Samarijoje prie Izraelio karalių; o jo sūnus Jeroboamas karaliavo jo vietoje.'),
  (@b12, 14, 17, 'O Amacijas, sūnus Joašo – Judos karaliaus, po Jehoašo sūnaus Jehoachazo, Izraelio karaliaus, mirties gyveno penkiolika metų.'),
  (@b12, 14, 18, 'O kiti Amacijo darbai, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 14, 19, 'Na, o prieš jį surengė sąmokslą Jeruzalėje; ir jis pabėgo į Lachišą; bet jie pasiuntė paskui jį į Lachišą ir ten jį nužudė.'),
  (@b12, 14, 20, 'Ir jie pargabeno jį ant žirgų; ir jis buvo palaidotas Jeruzalėje prie savo tėvų Dovydo mieste.'),
  (@b12, 14, 21, 'Ir visa Judos tauta paėmė Azariją, kuris buvo šešiolikos metų, ir jį padarė karaliumi vietoje jo tėvo Amacijo.'),
  (@b12, 14, 22, 'Jis pastatė Elatą ir jį sugrąžino Judai po to, kai karalius užmigo prie savo tėvų.'),
  (@b12, 14, 23, 'Penkioliktaisiais Amacijo, sūnaus Joašo – Judos karaliaus, metais Samarijoje pradėjo karaliauti Izraelio karaliaus Joašo sūnus Jeroboamas ir karaliavo keturiasdešimt vienerius metus.'),
  (@b12, 14, 24, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse: jis neatsitraukė nuo visų nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti.'),
  (@b12, 14, 25, 'Jis atgavo Izraelio ribas nuo Hamato įėjimo iki lygumos jūros pagal VIEŠPATIES, Izraelio Dievo, žodį, kurį jis kalbėjo per ranką savo tarno Jonos, Amitajo sūnaus, pranašo, esančio iš Gat-Hefero.'),
  (@b12, 14, 26, 'Nes VIEŠPATS matė Izraelio vargą, kuris buvo labai kartus: nes nebuvo nei vieno užrakinto, nei palikto, nei padėjėjo Izraeliui.'),
  (@b12, 14, 27, 'Ir VIEŠPATS nesakė, kad ištrins Izraelio vardą iš po dangaus; bet jis juos išgelbėjo per Joašo sūnaus Jeroboamo ranką.'),
  (@b12, 14, 28, 'Na, o kiti Jeroboamo darbai, visa, ką jis darė, ir jo galybė, kaip jis kariavo ir kaip atgavo Izraeliui Damaską bei Hamatą, priklausančius Judai, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 14, 29, 'Ir Jeroboamas užmigo prie savo tėvų – prie Izraelio karalių; o jo sūnus Zacharija karaliavo jo vietoje.'),
  (@b12, 15, 1, 'Dvidešimt septintaisiais Izraelio karaliaus Jeroboamo metais pradėjo karaliauti Judos karaliaus Amacijo sūnus Azarija.'),
  (@b12, 15, 2, 'Jis buvo šešiolikos metų, kai pradėjo karaliauti, ir penkiasdešimt dvejus metus karaliavo Jeruzalėje. O jo motinos vardas buvo Jekolija, iš Jeruzalės.'),
  (@b12, 15, 3, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, pagal visa tai, ką buvo daręs jo tėvas Amacijas;'),
  (@b12, 15, 4, 'tik aukštumos nebuvo pašalintos; tauta vis tebeaukojo ir tebedegino smilkalus aukštumose.'),
  (@b12, 15, 5, 'Ir VIEŠPATS taip ištiko karalių, kad jis buvo raupsuotas iki savo mirties dienos ir gyveno atskiruose namuose. O karaliaus sūnus Jotamas valdė namus, teisdamas šalies tautą.'),
  (@b12, 15, 6, 'O kiti Azarijos darbai ir visa, ką jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 15, 7, 'Taigi Azarija užmigo prie savo tėvų; ir jį palaidojo prie jo tėvų Dovydo mieste; o jo sūnus Jotamas karaliavo jo vietoje.'),
  (@b12, 15, 8, 'Trisdešimt aštuntaisiais Judos karaliaus Azarijos metais Jeroboamo sūnus Zacharija karaliavo Izraeliui Samarijoje šešis mėnesius.'),
  (@b12, 15, 9, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, kaip buvo darę jo tėvai: jis neatsitraukė nuo nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti.'),
  (@b12, 15, 10, 'Ir Jabešo sūnus Šalumas prieš jį surengė sąmokslą, sumušė jį tautos akivaizdoje ir nužudė jį, ir karaliavo jo vietoje.'),
  (@b12, 15, 11, 'O kiti Zacharijos darbai, štai jie yra užrašyti Izraelio karalių kronikų knygoje.'),
  (@b12, 15, 12, 'Šis buvo VIEŠPATIES žodis, kurį jis kalbėjo Jehuvui, sakydamas: „Iki ketvirtos kartos tavo sūnūs sėdės Izraelio soste“. Taip ir įvyko.'),
  (@b12, 15, 13, 'Jabešo sūnus Šalumas pradėjo karaliauti trisdešimt devintaisiais Judos karaliaus Uzijo metais; ir karaliavo pilną mėnesį Samarijoje.'),
  (@b12, 15, 14, 'Nes Gadžio sūnus Menahemas, ėjo aukštyn iš Tircos ir atėjo į Samariją, ir sumušė Jabešo sūnų Šalumą Samarijoje, ir jį nužudė, ir karaliavo jo vietoje.'),
  (@b12, 15, 15, 'O kiti Šalumo darbai ir jo sąmokslas, kurį jis surengė, štai jie yra užrašyti Izraelio karalių kronikų knygoje.'),
  (@b12, 15, 16, 'Tada Menahemas sumušė Tifsachą ir visa, kas buvo jame, ir jo ribas nuo Tircos; kadangi jie neatidarė jam, tai jis sumušė jį; ir perskrodė jame visas nėščias moteris.'),
  (@b12, 15, 17, 'Trisdešimt devintaisiais Judos karaliaus Azarijos metais Gadžio sūnus Menahemas pradėjo karaliauti Izraeliui ir karaliavo dešimt metų Samarijoje.'),
  (@b12, 15, 18, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse: jis per visas savo dienas neatsitraukė nuo nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti.'),
  (@b12, 15, 19, 'Ir Asirijos karalius Pulas atėjo prieš šalį; ir Menahemas davė Pului tūkstantį talentų sidabro, kad jo ranka būtų su juo, karalystei sustiprinti jo rankoje.'),
  (@b12, 15, 20, 'Ir Menahemas išreikalavo tuos pinigus iš Izraelio, tai yra iš visų galingų turtuolių, iš kiekvieno po penkiasdešimt šekelių sidabro, kad duotų Asirijos karaliui. Taip Asirijos karalius nusigręžė ir nepasiliko ten šalyje.'),
  (@b12, 15, 21, 'O kiti Menahemo darbai ir visa, ką jis darė, argi jie nėra užrašyti Izraelio karalių kronikų knygoje?'),
  (@b12, 15, 22, 'Ir Menachemas užmigo prie savo tėvų; o jo sūnus Pekachija karaliavo jo vietoje.'),
  (@b12, 15, 23, 'Penkiasdešimtaisiais Judos karaliaus Azarijos metais Menahemo sūnus Pekachija pradėjo karaliauti Izraeliui Samarijoje ir karaliavo dvejus metus.'),
  (@b12, 15, 24, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse: jis neatsitraukė nuo nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti.'),
  (@b12, 15, 25, 'Bet Remalijo sūnus Pekachas, jo vadas, surengė prieš jį sąmokslą ir sumušė jį Samarijoje karaliaus namų rūmuose su Argobu, Arjė ir penkiasdešimčia gileadiečių vyrų su juo; ir jis jį nužudė ir karaliavo jo vietoje.'),
  (@b12, 15, 26, 'O kiti Pekachijos darbai ir visa, ką jis darė, štai jie užrašyti Izraelio karalių kronikų knygoje.'),
  (@b12, 15, 27, 'Penkiasdešimt antraisiais Judos karaliaus Azarijos metais Remalijo sūnus Pekachas pradėjo karaliauti Izraeliui Samarijoje ir karaliavo dvidešimt metų.'),
  (@b12, 15, 28, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse: jis neatsitraukė nuo nuodėmių Nebato sūnaus Jeroboamo, kuris skatino Izraelį nusidėti.'),
  (@b12, 15, 29, 'Izraelio karaliaus Pekacho dienomis atėjo Asirijos karalius Tiglat-Pileseras ir paėmė Ijoną, Abel-Bet-Maaką, Janoachą, Kedešą, Hacorą, Gileadą ir Galilėją, visą Naftalio šalį, ir juos paėmė nelaisvėn į Asiriją.'),
  (@b12, 15, 30, 'O Elos sūnus Ozėja surengė sąmokslą prieš Remalijo sūnų Pekachą, sumušė jį ir nužudė, ir karaliavo jo vietoje dvidešimtaisiais Uzijo sūnaus Jotamo metais.'),
  (@b12, 15, 31, 'O kiti Pekacho darbai ir visa, ką jis darė, štai jie užrašyti Izraelio karalių kronikų knygoje.'),
  (@b12, 15, 32, 'Antraisiais Izraelio karaliaus Remalijo, Pekacho sūnaus, metais pradėjo karaliauti Judos karaliaus Uzijo sūnus Jotamas.'),
  (@b12, 15, 33, 'Jis buvo dvidešimt penkerių metų, kai pradėjo karaliauti, ir šešiolika metų karaliavo Jeruzalėje. O jo motinos vardas buvo Jeruša, Cadoko duktė.'),
  (@b12, 15, 34, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse: jis darė pagal visa tai, ką buvo daręs jo tėvas Uzijas.'),
  (@b12, 15, 35, 'Tačiau aukštumos nebuvo pašalintos: tauta vis tebeaukojo ir tebesmilkė smilkalus aukštumose. Jis pastatė aukštutinius VIEŠPATIES namų vartus.'),
  (@b12, 15, 36, 'Na, o kiti Jotamo darbai ir visa, ką jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 15, 37, 'Tomis dienomis VIEŠPATS pradėjo siųsti prieš Judą Sirijos karalių Reciną ir Remalijo sūnų Pekachą.'),
  (@b12, 15, 38, 'Ir Jotamas užmigo prie savo tėvų ir buvo palaidotas prie savo tėvų savo tėvo Dovydo mieste; o jo sūnus Ahazas karaliavo jo vietoje.'),
  (@b12, 16, 1, 'Septynioliktaisiais Remalijo sūnaus Pekacho metais pradėjo karaliauti Judos karaliaus Jotamo sūnus Ahazas.'),
  (@b12, 16, 2, 'Ahazas buvo dvidešimties metų, kai pradėjo karaliauti, ir šešiolika metų karaliavo Jeruzalėje, ir nedarė to, kas buvo teisinga VIEŠPATIES, jo Dievo, akyse, kaip jo tėvas Dovydas.'),
  (@b12, 16, 3, 'Bet jis vaikščiojo Izraelio karalių keliu, taip, ir savo sūnų perleido per ugnį, pagal bjaurystes pagonių, kuriuos VIEŠPATS išvarė iš Izraelio vaikų akivaizdos.'),
  (@b12, 16, 4, 'Ir jis aukojo ir degino smilkalus aukštumose, ant kalvų ir po kiekvienu žaliuojančiu medžiu.'),
  (@b12, 16, 5, 'Tuomet Sirijos karalius Recinas ir Izraelio karalius – Remalijo sūnus Pekachas – atėjo aukštyn į Jeruzalę kariauti; ir jie apgulė Ahazą, bet neįstengė jo nugalėti.'),
  (@b12, 16, 6, 'Tuo metu Sirijos karalius Recinas sugrąžino Elatą Sirijai ir išvarė žydus iš Elato; ir sirai atėjo į Elatą ir ten gyvena iki šios dienos.'),
  (@b12, 16, 7, 'Taigi Ahazas siuntė pasiuntinius pas Asirijos karalių Tiglat-Pileserą, sakydamas: „Aš esu tavo tarnas ir tavo sūnus; ateik aukštyn ir išgelbėk mane iš rankų Sirijos karaliaus ir iš rankų Izraelio karaliaus, kurie pakilo prieš mane“.'),
  (@b12, 16, 8, 'Ir Ahazas paėmė sidabrą ir auksą, rastą VIEŠPATIES namuose ir karaliaus namų ižduose, ir nusiuntė tai kaip dovaną Asirijos karaliui.'),
  (@b12, 16, 9, 'Ir Asirijos karalius paklausė jo; nes Asirijos karalius ėjo aukštyn prieš Damaską ir jį paėmė, ir išvedė nelaisvėn jo žmones į Kirą, o Reciną nužudė.'),
  (@b12, 16, 10, 'Ir karalius Ahazas nuvyko į Damaską pasitikti Asirijos karaliaus Tiglat-Pilesero ir pamatė Damaske buvusį aukurą; ir karalius Ahazas nusiuntė kunigui Ūrijui aukuro pavyzdį ir jo modelį, pagal visą jo padarymą.'),
  (@b12, 16, 11, 'Ir kunigas Ūrija pastatė aukurą pagal viską, ką karalius Ahazas buvo atsiuntęs iš Damasko; taigi kunigas Ūrija jį padarė prieš karaliui Ahazui ateinant iš Damasko.'),
  (@b12, 16, 12, 'Ir kai karalius atėjo iš Damasko, karalius pamatė aukurą; ir karalius priėjo prie aukuro ir ant jo atnašavo.'),
  (@b12, 16, 13, 'Ir jis degino savo deginamąją atnašą ir savo maisto atnašą, išliejo savo geriamąją atnašą ir šlakstė savo taikos atnašų kraują ant to aukuro.'),
  (@b12, 16, 14, 'O žalvarinį aukurą, esantį VIEŠPATIES akivaizdoje, jis nunešė nuo namų priekio, iš aukuro ir VIEŠPATIES namų tarpo, ir jį pastatė aukuro šiaurinėje pusėje.'),
  (@b12, 16, 15, 'Ir karalius Ahazas įsakė kunigui Ūrijai, sakydamas: „Ant didžiojo aukuro degink ryto deginamąją atnašą ir vakaro maisto atnašą, ir karaliaus deginamąją auką, ir jo maisto atnašą su šalies visos tautos deginamąja atnaša, jų maisto atnaša ir jų geriamosiomis atnašomis; ir apšlakstyk ant jo visą deginamosios atnašos kraują bei visą aukos kraują; o žalvarinis aukuras man bus, kad per jį pasiklausčiau“.'),
  (@b12, 16, 16, 'Taip kunigas Ūrija padarė pagal visa tai, ką įsakė karalius Ahazas.'),
  (@b12, 16, 17, 'Ir karalius Ahazas nupjovė stovų kraštus ir nuėmė nuo jų praustuvę; ir nukėlė jūrą nuo žalvarinių jaučių, esančių jos apačioje, ir padėjo ją ant akmeninio grindinio.'),
  (@b12, 16, 18, 'Ir dėl Asirijos karaliaus jis nuo VIEŠPATIES namų nusuko sabato pastogę, kurią buvo pastatę namuose, ir išorinį karaliaus įėjimą.'),
  (@b12, 16, 19, 'Na, o kiti Ahazo darbai, kuriuos jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 16, 20, 'Ir Ahazas užmigo prie savo tėvų ir buvo palaidotas prie savo tėvų Dovydo mieste; o jo sūnus Chezekijas karaliavo jo vietoje.'),
  (@b12, 17, 1, 'Dvyliktaisiais Judos karaliaus Ahazo metais Elos sūnus Ozėjas pradėjo karaliauti Izraeliui Samarijoje devynerius metus.'),
  (@b12, 17, 2, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, bet ne taip, kaip pirma jo buvusieji Izraelio karaliai.'),
  (@b12, 17, 3, 'Prieš jį atėjo aukštyn Asirijos karalius Šalmaneseras; ir Ozėjas tapo jo tarnu ir duodavo jam dovanas.'),
  (@b12, 17, 4, 'Ir Asirijos karalius aptiko Ozėją rengiant sąmokslą: nes jis buvo siuntęs pasiuntinius pas Egipto karalių Soją ir neatnešė Asirijos karaliui dovanos, kaip kasmet darydavo; todėl Asirijos karalius užrakino jį ir įkalino kalėjime.'),
  (@b12, 17, 5, 'Tada Asirijos karalius ėjo aukštyn per visą šalį ir nuėjo aukštyn į Samariją, ir buvo ją apgulęs trejus metus.'),
  (@b12, 17, 6, 'Devintaisiais Ozėjo metais Asirijos karalius paėmė Samariją ir išvedė Izraelį į Asiriją, ir apgyvendino juos Halache ir Habore prie Gozano upės ir medų miestuose.'),
  (@b12, 17, 7, 'Nes Izraelio vaikai nusidėjo prieš VIEŠPATĮ, savo Dievą, kuris buvo juos išvedęs aukštyn iš Egipto šalies, iš po faraono, Egipto karaliaus, rankos, ir bijojo kitų dievų,'),
  (@b12, 17, 8, 'ir vaikščiojo pagal įstatus pagonių, kuriuos VIEŠPATS išvarė iš Izraelio vaikų akivaizdos, ir pagal Izraelio karalių, kurie juos padarė.'),
  (@b12, 17, 9, 'Ir Izraelio vaikai slapta darė tai, kas nebuvo teisinga prieš VIEŠPATĮ, jų Dievą, ir jie pasistatė aukštumų visuose savo miestuose, nuo sargybos bokšto iki aptverto miesto.'),
  (@b12, 17, 10, 'Ir jie pasistatė atvaizdų ir giraičių ant kiekvienos aukštos kalvos ir po kiekvienu žaliuojančiu medžiu;'),
  (@b12, 17, 11, 'ir jie ten visose aukštumose degino smilkalus, kaip daro pagonys, kuriuos VIEŠPATS išvarė jų akivaizdoje; ir darė nedorybes, kurstydami VIEŠPATIES pyktį;'),
  (@b12, 17, 12, 'nes jie tarnavo stabams, apie kuriuos VIEŠPATS jiems buvo sakęs: „To nedarykite“.'),
  (@b12, 17, 13, 'VIEŠPATS dar liudijo prieš Izraelį ir prieš Judą per visus pranašus ir per visus regėtojus, sakydamas: „Nusisukite nuo savo piktų kelių ir laikykitės mano įsakymų bei mano įstatų, pagal visą įstatymą, kurį įsakiau jūsų tėvams ir kurį jums nusiunčiau per savo tarnus pranašus“.'),
  (@b12, 17, 14, 'Tačiau jie nenorėjo klausyti, bet užkietino savo sprandus, kaip sprandus savo tėvų, kurie netikėjo VIEŠPAČIU, savo Dievu.'),
  (@b12, 17, 15, 'Ir jie atmetė jo įstatus ir jo sandorą, kurią jis sudarė su jų tėvais, ir jo liudijimus, kuriais jis liudijo prieš juos; ir jie sekė tuštybėmis ir tapo tušti, ir nuėjo paskui aplinkui juos esančius pagonis, apie kuriuos VIEŠPATS juos buvo įpareigojęs, kad jie nedarytų kaip jie.'),
  (@b12, 17, 16, 'Ir jie paliko visus VIEŠPATIES, savo Dievo, įsakymus ir pasidarė lietų atvaizdų, tai yra du veršius, ir padarė giraitę, ir garbino visą dangaus kariuomenę, ir tarnavo Baalui.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b12, 17, 17, 'Ir jie padarė, kad jų sūnūs ir jų dukterys eitų per ugnį, ir užsiiminėjo būrimu ir kerais, ir parsidavė daryti pikta VIEŠPATIES akyse, kad kurstytų jo pyktį.'),
  (@b12, 17, 18, 'Todėl VIEŠPATS labai supyko ant Izraelio ir pašalino juos nuo savo akivaizdos; nei vieno nepaliko, vien tik Judos gentis.'),
  (@b12, 17, 19, 'Taip pat ir Juda nesilaikė VIEŠPATIES, savo Dievo, įsakymų, bet vaikščiojo pagal Izraelio įstatus, kuriuos jie padarė.'),
  (@b12, 17, 20, 'Ir VIEŠPATS atmetė visą Izraelio sėklą, vargino juos ir atidavė juos į plėšikų rankas, kol išmetė juos nuo savo akivaizdos.'),
  (@b12, 17, 21, 'Nes jis atplėšė Izraelį nuo Dovydo namų; ir jie padarė karaliumi Nebato sūnų Jeroboamą; ir Jeroboamas atitraukė Izraelį nuo sekimo paskui VIEŠPATĮ ir skatino juos nusidėti didele nuodėme.'),
  (@b12, 17, 22, 'Nes Izraelio vaikai vaikščiojo visose Jeroboamo nuodėmėse, kurias jis darė; jie neatsitraukė nuo jų;'),
  (@b12, 17, 23, 'kol VIEŠPATS pašalino Izraelį iš savo akivaizdos, kaip jis buvo kalbėjęs per visus savo tarnus pranašus. Taip Izraelis buvo išvestas iš savo pačių šalies į Asiriją iki šios dienos.'),
  (@b12, 17, 24, 'Ir Asirijos karalius atvedė žmonių iš Babilono, iš Kuto, iš Avos, iš Hamato ir iš Sefarvaimo ir apgyvendino juos Samarijos miestuose vietoje Izraelio vaikų; ir jie pasisavino Samariją ir gyveno jos miestuose.'),
  (@b12, 17, 25, 'Ir buvo taip, kad pradėję ten gyventi jie nebijojo VIEŠPATIES; todėl VIEŠPATS pasiuntė tarp jų liūtus, kurie nužudė kai kuriuos iš jų.'),
  (@b12, 17, 26, 'Todėl kalbėjo Asirijos karaliui, sakydami: „Tautos, kurias iškėlei ir apgyvendinai Samarijos miestuose, nežino tos šalies Dievo būdo; todėl jis pasiuntė tarp jų liūtus, ir štai jie žudo juos, nes jie nežino tos šalies Dievo būdo“.'),
  (@b12, 17, 27, 'Tada Asirijos karalius įsakė, sakydamas: „Atgabenkite ten vieną iš kunigų, kuriuos iš ten išvedėte; ir tenueina ten ir apsigyvena, ir jis temoko juos tos šalies Dievo būdo“.'),
  (@b12, 17, 28, 'Tada vienas iš kunigų, kuriuos jie buvo išgabenę iš Samarijos, atėjęs apsigyveno Bet-Elyje ir juos mokė, kaip jie turi bijoti VIEŠPATIES.'),
  (@b12, 17, 29, 'Tačiau kiekviena tauta pasidarė savo pačių dievų ir juos pastatė namuose aukštumų, kurias buvo padarę samariečiai, kiekviena tauta savo miestuose, kuriuose jie gyveno.'),
  (@b12, 17, 30, 'Babilono žmonės pasidarė Sukot-Benotą, Kuto žmonės pasidarė Nergalą, Hamato žmonės pasidarė Ašimą,'),
  (@b12, 17, 31, 'aviečiai pasidarė Nibhazą ir Tartaką, o sefarvaimiečiai degino ugnyje savo vaikus Sefarvaimo dievams Adramelechui ir Anamelechui.'),
  (@b12, 17, 32, 'Taigi jie bijojo VIEŠPATIES ir paskyrė sau aukštumų kunigų iš savo prasčiausiųjų, kurie jiems aukojo aukštumų namuose.'),
  (@b12, 17, 33, 'Jie bijojo VIEŠPATIES ir tarnavo savo pačių dievams pagal būdą tų tautų, kurias jie iš ten išgabeno.'),
  (@b12, 17, 34, 'Iki šios dienos jie elgiasi pagal ankstesnįjį būdą: jie nebijo VIEŠPATIES ir nesielgia pagal jų įstatus ar pagal jų potvarkius, ar pagal įstatymą ir įsakymą, kurį VIEŠPATS įsakė vaikams Jokūbo, kurį jis praminė Izraeliu;'),
  (@b12, 17, 35, 'su kuriais VIEŠPATS buvo sudaręs sandorą ir juos įpareigojęs, sakydamas: „Nebijokite kitų dievų nei nesilenkite jiems, nei netarnaukite jiems, nei jiems neaukokite;'),
  (@b12, 17, 36, 'bet VIEŠPATIES, kuris jus išvedė aukštyn iš Egipto šalies didele jėga ir ištiesta ranka, jo bijokite ir jį garbinkite, ir jam aukokite.'),
  (@b12, 17, 37, 'Laikykitės, kad visada vykdytumėte įstatus, potvarkius, įstatymą ir įsakymą, kuriuos jis jums užrašė; ir nebijokite kitų dievų.'),
  (@b12, 17, 38, 'Ir nepamirškite sandoros, kurią sudariau su jumis; nei nebijokite kitų dievų.'),
  (@b12, 17, 39, 'Bet VIEŠPATIES, savo Dievo, bijokite; ir jis jus išvaduos iš visų jūsų priešų rankų“.'),
  (@b12, 17, 40, 'Tačiau jie neklausė, bet elgėsi pagal savo ankstesnį būdą.'),
  (@b12, 17, 41, 'Taigi šitos tautos bijojo VIEŠPATIES ir tarnavo savo raižytiems atvaizdams – tiek jų vaikai, tiek jų vaikų vaikai; kaip darė jų tėvai, taip jie daro iki šios dienos.'),
  (@b12, 18, 1, 'Na, o trečiaisiais Ozėjo, sūnaus Elos – Izraelio karaliaus, metais įvyko, kad pradėjo karaliauti Judos karaliaus Ahazo sūnus Chezekijas.'),
  (@b12, 18, 2, 'Jis buvo dvidešimt penkerių metų, kai pradėjo karaliauti; ir dvidešimt devynerius metus karaliavo Jeruzalėje. Jo motinos vardas buvo Abi, Zacharijos duktė.'),
  (@b12, 18, 3, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, pagal visa tai, ką darė jo tėvas Dovydas.'),
  (@b12, 18, 4, 'Jis pašalino aukštumas, sudaužė atvaizdus, iškirto giraites, sutrupino žalvarinę gyvatę, kurią buvo padaręs Mozė; nes iki tų dienų Izraelio vaikai tebedegino jai smilkalus; ir ją vadino Nehuštanu.'),
  (@b12, 18, 5, 'Jis pasitikėjo VIEŠPAČIU, Izraelio Dievu; taip, kad nei po jo, nei prieš jį nebuvo tokio, kaip jis, tarp visų Judos karalių.'),
  (@b12, 18, 6, 'Nes jis prilipo prie VIEŠPATIES ir neatsitraukė nuo sekimo paskui jį, bet laikėsi jo įsakymų, kuriuos VIEŠPATS įsakė Mozei.'),
  (@b12, 18, 7, 'Ir VIEŠPATS buvo su juo; visur, kur tik jis išeidavo, jam sekėsi; ir jis sukilo prieš Asirijos karalių ir jam netarnavo.'),
  (@b12, 18, 8, 'Jis sumušė filistinus iki Gazos ir jos ribas nuo sargybos bokšto iki aptverto miesto.'),
  (@b12, 18, 9, 'Ir ketvirtaisiais karaliaus Chezekijo metais, kurie buvo septintieji Ozėjo, sūnaus Elos – Izraelio karaliaus, metai, įvyko, kad Asirijos karalius Šalmaneseris atėjo aukštyn prieš Samariją ir ją apgulė.'),
  (@b12, 18, 10, 'O trejų metų pabaigoje ją paėmė; tai yra šeštaisiais Chezekijo metais, tai yra, devintaisiais Izraelio karaliaus Ozėjo metais Samarija buvo paimta.'),
  (@b12, 18, 11, 'Ir Asirijos karalius išvedė Izraelį į Asiriją ir apgyvendino juos Halache, Habore prie Gozano upės ir medų miestuose;'),
  (@b12, 18, 12, 'nes jie ne pakluso VIEŠPATIES, savo Dievo, balsui, bet nusižengė jo sandorai, viskam, ką VIEŠPATIES tarnas Mozė įsakė, ir to neklausė ir nevykdė.'),
  (@b12, 18, 13, 'Na, o keturioliktaisiais karaliaus Chezekijo metais Asirijos karalius Sencheribas atėjo aukštyn prieš visus aptvertus Judos miestus ir juos paėmė.'),
  (@b12, 18, 14, 'Ir Judos karalius Chezekijas pasiuntė Asirijos karaliui į Lachišą, sakydamas: „Nusikaltau; atsitrauk nuo manęs; ką ant manęs uždėsi, nešiu“. Ir Asirijos karalius nustatė Judos karaliui Chezekijui tris šimtus talentų sidabro ir trisdešimt talentų aukso.'),
  (@b12, 18, 15, 'Ir Chezekijas davė jam visą sidabrą, rastą VIEŠPATIES namuose ir karaliaus namų ižduose.'),
  (@b12, 18, 16, 'Tuo laiku Chezekijas atkirto auksą nuo VIEŠPATIES šventyklos durų ir nuo stulpų, kuriuos Judos karalius Chezekijas buvo padengęs, ir jį davė Asirijos karaliui.'),
  (@b12, 18, 17, 'Ir Asirijos karalius siuntė iš Lachišo Tartaną, Rabsarį ir Rabšakę su didele kariuomene pas karalių Chezekiją prieš Jeruzalę. Ir jie ėjo aukštyn ir atėjo į Jeruzalę. O atėję aukštyn, jie atėjo ir sustojo prie vandentakio aukštutinio tvenkinio, esančio prie vėlėjo lauko vieškelio.'),
  (@b12, 18, 18, 'Ir jiems pašaukus karalių, pas juos išėjo Hilkijo sūnus Eljakimas, namų viršininkas, ir raštininkas Šebna, ir metraštininkas Joachas, Asafo sūnus.'),
  (@b12, 18, 19, 'Ir Rabšakė jiems tarė: „Dabar kalbėkite Chezekijui: ‘Taip sako didysis karalius, Asirijos karalius: „Kas tai per pasitikėjimas, kuriuo tu pasitiki?'),
  (@b12, 18, 20, 'Tu sakai (bet tai tėra tušti žodžiai): ‘Turiu patarimą ir galią kariauti’. Kuo gi dabar pasitiki, kad sukilai prieš mane?'),
  (@b12, 18, 21, 'Štai dabar tu pasitiki šita palūžusios nendrės lazda – Egiptu; jei kas į ją pasiremia, ji įsminga į jo ranką ir ją perduria; toks yra faraonas, Egipto karalius, visiems, kurie juo pasitiki.'),
  (@b12, 18, 22, 'Bet jei man sakysite: ‘Mes pasitikime VIEŠPAČIU, savo Dievu’, argi ne jis yra tas, kurio aukštumas ir aukurus Chezekijas pašalino ir pasakė Judai ir Jeruzalei: ‘Garbinkite prieš šitą aukurą Jeruzalėje’?“'),
  (@b12, 18, 23, 'Taigi dabar, meldžiu tave, pasižadėk mano viešpačiui, Asirijos karaliui, ir aš tau duosiu du tūkstančius žirgų, jei tik galėsi pasisodinti raitelių ant jų.'),
  (@b12, 18, 24, 'Tad kaip tu nukreipsi vieno iš mažiausių mano valdovo tarnų vado veidą ir pasitikėsi Egiptu dėl vežimų ir raitelių?'),
  (@b12, 18, 25, 'Ar aš be VIEŠPATIES dabar atėjau aukštyn prieš šitą vietą, kad ją sunaikinčiau? VIEŠPATS man sakė: ‘Eik aukštyn prieš šitą šalį ir ją sunaikink’“.'),
  (@b12, 18, 26, 'Tada Hilkijo sūnus Eljakimas, Šebna ir Joachas tarė Rabšakei: „Kalbėk, meldžiu tave, savo tarnams sirų kalba; nes mes tai suprantame; bet nekalbėk su mumis žydų kalba į ausis tautos, esančios ant sienos“.'),
  (@b12, 18, 27, 'Bet Rabšakė jiems pasakė: „Argi mano valdovas mane siuntė pas tavo valdovą ir pas tave kalbėti šituos žodžius? Argi jis nesiuntė manęs pas žmones, sėdinčius ant sienos, kad jie valgytų savo išmatas ir gertų savo šlapimą su jumis?“'),
  (@b12, 18, 28, 'Tada Rabšakė atsistojo ir garsiu balsu šaukė žydų kalba, ir kalbėjo, sakydamas: „Klausykite didžiojo karaliaus, Asirijos karaliaus, žodžio;'),
  (@b12, 18, 29, 'taip sako karalius: ‘Tegul Chezekijas neapgauna jūsų; nes jis nepajėgs jūsų išgelbėti iš jo rankų’;'),
  (@b12, 18, 30, 'taip pat Chezekijas teneverčia jūsų pasitikėti VIEŠPAČIU, sakydamas: ‘VIEŠPATS tikrai mus išgelbės ir šitas miestas nebus atiduotas į Asirijos karaliaus rankas’.'),
  (@b12, 18, 31, 'Neklausykite Chezekijo; nes taip sako Asirijos karalius: ‘Per dovaną sudarykite su manimi sutartį, išeikite pas mane ir tada kiekvienas valgykite nuo savo vynmedžio ir kiekvienas nuo savo figmedžio, ir kiekvienas gerkite vandens iš savo rezervuaro;'),
  (@b12, 18, 32, 'kol atvykęs aš išvesiu jus į šalį, į tokią šalį, kaip jūsų, javų ir vyno šalį, duonos ir vynuogynų šalį, aliejingų alyvmedžių ir medaus šalį, kad gyventumėte, o nemirtumėte; ir neklausykite Chezekijo, kai jis jus įtikinėja, sakydamas: „VIEŠPATS mus išgelbės“.'),
  (@b12, 18, 33, 'Argi kuris nors iš tautų dievų iš viso išgelbėjo savo šalį iš Asirijos karaliaus rankos?'),
  (@b12, 18, 34, 'Kur yra Hamato ir Arpado dievai? Kur yra Sefarvaimo, Henos ir Ivos dievai? Ar jie išgelbėjo Samariją iš mano rankos?'),
  (@b12, 18, 35, 'Kurie yra tarp tų šalių visų dievų, kurie išgelbėjo savo šalį iš mano rankos, kad VIEŠPATS išgelbėtų Jeruzalę iš mano rankos?’“'),
  (@b12, 18, 36, 'Bet tauta tylėjo ir jam neatsakė nei žodžio; nes toks buvo pasakytas karaliaus įsakymas: „Neatsakykite jam“.'),
  (@b12, 18, 37, 'Tada namų viršininkas Hilkijo sūnus Eljakimas, raštininkas Šebna ir Asafo sūnus Joachas, metraštininkas, atėjo pas Chezekiją perplėštais drabužiais ir jam pranešė Rabšakės žodžius.'),
  (@b12, 19, 1, 'Ir įvyko, kad tai išgirdęs, karalius Chezekijas perplėšė savo drabužius, apsidengė ašutine ir nuėjo į VIEŠPATIES namus.'),
  (@b12, 19, 2, 'Ir jis pasiuntė namų viršininką Eljakimą, raštininką Šebną ir kunigų vyresniuosius, apsidengusius ašutinėmis, pas pranašą Izaiją, Amoco sūnų.'),
  (@b12, 19, 3, 'Ir jie jam tarė: „Taip sako Chezekijas: ‘Šita diena yra vargo, papeikimo ir piktžodžiavimo diena; nes vaikai priėjo, kad gimtų, o nėra jėgų gimdyti.'),
  (@b12, 19, 4, 'Galbūt VIEŠPATS, tavo Dievas, išgirs visus žodžius Rabšakės, kurį siuntė jo valdovas Asirijos karalius priekaištauti gyvajam Dievui; ir papeiks žodžius, kuriuos girdėjo VIEŠPATS, tavo Dievas; todėl iškelk savo maldą už išlikusį likutį’“.'),
  (@b12, 19, 5, 'Taigi karaliaus Chezekijo tarnai atėjo pas Izaiją.'),
  (@b12, 19, 6, 'Ir Izaijas jiems tarė: „Taip sakykite savo valdovui: ‘Taip sako VIEŠPATS: Neišsigąsk žodžių, kuriuos girdėjai, kuriais Asirijos karaliaus tarnai man piktžodžiavo.'),
  (@b12, 19, 7, 'Štai aš pasiųsiu ant jo pūtimą, ir jis išgirs gandą ir sugrįš į savo šalį; ir padarysiu, kad jis kris nuo kalavijo savo paties šalyje’“.'),
  (@b12, 19, 8, 'Taigi Rabšakė sugrįžęs rado Asirijos karalių kariaujant prieš Libną; nes jis girdėjo, kad šis buvo pasitraukęs nuo Lachišo.'),
  (@b12, 19, 9, 'Ir kai jis išgirdo sakant apie Etiopijos karalių Tirhaką: „Štai jis išėjęs kovoti prieš tave“; jis vėl siuntė pasiuntinius pas Chezekiją, sakydamas:'),
  (@b12, 19, 10, '„Taip kalbėkite Judos karaliui Chezekijui, sakydami: ‘Tavo Dievas, kuriuo tu pasitiki, teneapgauna tavęs, sakydamas: „Jeruzalė nebus atiduota į Asirijos karaliaus ranką“.'),
  (@b12, 19, 11, 'Štai tu esi girdėjęs, ką Asirijos karaliai padarė visoms šalims, jas visiškai sunaikindami; o tu ar būsi išgelbėtas?'),
  (@b12, 19, 12, 'Argi tautų dievai jas išgelbėjo – tas, kurias sunaikino mano tėvai – Gozaną, Haraną, Recefą ir Edeno vaikus, buvusius Telasare?'),
  (@b12, 19, 13, 'Kur yra Hamato karalius, Arpado karalius ir Sefarvaimo miesto, Henos ir Ivos karalius?’“'),
  (@b12, 19, 14, 'Ir Chezekijas paėmė laišką iš pasiuntinių rankų ir jį perskaitė; ir nuėjęs aukštyn į VIEŠPATIES namus, Chezekijas jį išskleidė VIEŠPATIES akivaizdoje.'),
  (@b12, 19, 15, 'Ir Chezekijas melsdamasis VIEŠPATIES akivaizdoje tarė: „O VIEŠPATIE, Izraelio Dieve, gyvenantis tarp kerubų, tu vienas esi visų žemės karalysčių Dievas; tu padarei dangų ir žemę.'),
  (@b12, 19, 16, 'Palenk, VIEŠPATIE, savo ausį ir išgirsk; atverk, VIEŠPATIE, savo akis ir pamatyk; ir išgirsk žodžius Sancheribo, kuris siuntė jį, kad priekaištautų gyvajam Dievui.'),
  (@b12, 19, 17, 'Iš tiesų, VIEŠPATIE, Asirijos karaliai išnaikino tautas ir jų šalis'),
  (@b12, 19, 18, 'ir sumetė jų dievus į ugnį; nes jie nebuvo dievai, bet tik žmonių rankų darbas, medis ir akmuo; todėl jie juos sunaikino.'),
  (@b12, 19, 19, 'Taigi dabar, o VIEŠPATIE, mūsų Dieve, meldžiu tave, išgelbėk mus iš jo rankos, idant visos pasaulio karalystės žinotų, kad tu vienintelis esi VIEŠPATS Dievas“.'),
  (@b12, 19, 20, 'Tada Amoco sūnus Izaijas pasiuntė Chezekijui, sakydamas: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Aš girdėjau tai, apie ką man meldeisi prieš Asirijos karalių Sancheribą’.'),
  (@b12, 19, 21, 'Šis yra žodis, kurį VIEŠPATS kalbėjo apie jį: ‘Paniekino tave ir išjuokė tave mergelė, Siono duktė; Jeruzalės duktė lingavo prieš tave galvą.'),
  (@b12, 19, 22, 'Kam priekaištavai ir piktžodžiavai? Prieš ką pakėlei savo balsą ir iškėlei aukštyn akis? Būtent prieš Izraelio Šventąjį.'),
  (@b12, 19, 23, 'Per savo pasiuntinius tu priekaištavai Viešpačiui ir sakei: „Su daugybe savo vežimų atėjau aukštyn į kalnų aukštumas, į Libano pakraščius, ir iškirsiu jo aukštus kedrus ir jo rinktines egles; įeisiu į jo ribų buveines, į jo Karmelio mišką.'),
  (@b12, 19, 24, 'Aš išsikasiau ir gėriau svetimus vandenis, ir išdžiovinau savo kojų padais visas apgultų vietų upes“.'),
  (@b12, 19, 25, 'Argi negirdėjai nuo seno, kaip tai padariau, ir nuo senovės laikų, kad tai suformavau? Dabar tai įvykdžiau, kad būtum aptvertų miestų nuniokojimui, paverčiant griuvėsių krūvomis.'),
  (@b12, 19, 26, 'Todėl jų gyventojai buvo bejėgiai, jie buvo sunerimę ir pritrenkti; jie buvo kaip lauko žolė ir kaip žalios žolės, kaip žolė ant stogų ir kaip javai nudžiūna prieš jiems užaugant.'),
  (@b12, 19, 27, 'Bet aš pažįstu tavo buveinę, tavo išėjimą ir tavo įėjimą, ir tavo siautėjimą prieš mane.'),
  (@b12, 19, 28, 'Kadangi tavo siautėjimas prieš mane ir tavo triukšmas pakilo man į ausis, tai aš įdėsiu savo kablį tau į nosį ir savo apynasrį tau į lūpas, ir sugrąžinsiu tave keliu, kuriuo atvykai’.'),
  (@b12, 19, 29, 'Ir tai bus tau ženklas: šiemet valgykite, kas savaime išaugs, o antrais metais, kas išdygs iš to paties; o trečiais metais sėkite ir pjaukite, ir sodinkite vynuogynus, ir valgykite jų vaisius.'),
  (@b12, 19, 30, 'O išlikę Judos namų pabėgėliai vėl leis šaknis į apačią ir neš vaisių į viršų.'),
  (@b12, 19, 31, 'Nes iš Jeruzalės išeis likutis ir išsigelbėjusieji iš Siono kalno; kariuomenių VIEŠPATIES uolumas tai padarys.'),
  (@b12, 19, 32, 'Todėl taip sako VIEŠPATS apie Asirijos karalių: ‘Jis neateis į šitą miestą ir neiššaus ten strėlės nei neateis prieš jį su skydu, nei nesupils prieš jį pylimo.'),
  (@b12, 19, 33, 'Jis sugrįš tuo pačiu keliu, kuriuo atėjo, ir į šitą miestą neateis, – sako VIEŠPATS.'),
  (@b12, 19, 34, '– Nes aš apginsiu šitą miestą, kad jį išgelbėčiau, dėl savęs ir dėl mano tarno Dovydo’“.'),
  (@b12, 19, 35, 'Ir tą naktį atsitiko, kad VIEŠPATIES angelas išėjo ir išmušė Asirijos stovykloje šimtą aštuoniasdešimt penkis tūkstančius; ir jiems anksti ryte atsikėlus, štai jie visi buvo negyvi lavonai.'),
  (@b12, 19, 36, 'Taip Asirijos karalius Sancheribas pasitraukė ir nuėjęs sugrįžo, ir apsigyveno Ninevėje.'),
  (@b12, 19, 37, 'Ir kai jis garbino savo dievo Nisrocho namuose, įvyko, kad jo sūnūs Adramelechas ir Sareceras užmušė jį kalaviju; ir jie pabėgo į Armėnijos šalį. O jo sūnus Esar-Hadonas karaliavo jo vietoje.'),
  (@b12, 20, 1, 'Tomis dienomis Chezekijas mirtinai susirgo. Ir pas jį atėjo pranašas Izaijas, Amoco sūnus, ir jam tarė: „Taip sako VIEŠPATS: ‘Sutvarkyk savo namus; nes tu mirsi ir nebegyvensi’“.'),
  (@b12, 20, 2, 'Tada jis nugręžė savo veidą į sieną ir meldėsi VIEŠPAČIUI, sakydamas:'),
  (@b12, 20, 3, '„O VIEŠPATIE, meldžiu tave, atsimink, kaip aš vaikščiojau tavo akivaizdoje tiesoje ir tobula širdimi ir dariau tai, kas gera tavo akyse“. Ir Chezekijas labai verkė.'),
  (@b12, 20, 4, 'Ir įvyko, kad Izaijui dar neišėjus į vidurinį kiemą, pas jį atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b12, 20, 5, '„Grįžk ir sakyk mano tautos vadui Chezekijui: ‘Taip sako VIEŠPATS, tavo tėvo Dovydo Dievas: Aš girdėjau tavo maldą, mačiau tavo ašaras; štai aš tave pagydysiu; trečią dieną tu eisi aukštyn į VIEŠPATIES namus.'),
  (@b12, 20, 6, 'Ir aš pridėsiu prie tavo dienų penkiolika metų; ir išgelbėsiu iš Asirijos karaliaus rankos tave ir šitą miestą; ir apginsiu šitą miestą dėl savęs ir dėl savo tarno Dovydo’“.'),
  (@b12, 20, 7, 'Ir Izaijas tarė: „Paimkite figų gumulą“. Ir jie paėmę uždėjo tai ant voties, ir jis pasveiko.'),
  (@b12, 20, 8, 'Ir Chezekijas tarė Izaijui: „Koks bus ženklas, kad VIEŠPATS išgydys mane ir kad trečią dieną eisiu aukštyn į VIEŠPATIES namus?“'),
  (@b12, 20, 9, 'O Izaijas tarė: „Šitas bus tau ženklas nuo VIEŠPATIES, kad VIEŠPATS padarys tai, ką kalbėjo: ar šešėliui nueiti pirmyn dešimt laipsnių, ar nueiti atgal dešimt laipsnių?“'),
  (@b12, 20, 10, 'Ir Chezekijas atsakė: „Lengva šešėliui nusileisti dešimt laipsnių; ne, verčiau tegul šešėlis sugrįžta dešimt laipsnių atgal“.'),
  (@b12, 20, 11, 'Ir pranašas Izaijas šaukėsi VIEŠPATIES; ir jis sugrąžino šešėlį dešimt laipsnių atgal, kuriais jis buvo nusileidęs Ahazo skalėmis.'),
  (@b12, 20, 12, 'Tuo metu Babilono karalius Berodach-Baladanas, Baladano sūnus, atsiuntė Chezekijui laiškų ir dovaną; nes jis buvo girdėjęs, kad Chezekijas serga.'),
  (@b12, 20, 13, 'Ir Chezekijas išklausė jų ir jiems parodė visus namus savo brangenybių, sidabrą ir auksą, kvepalus ir brangų aliejų, visą savo ginklų sandėlį ir viską, kas buvo rasta jo ižduose; nebuvo nieko, ko Chezekijas nebūtų jiems parodęs savo namuose ir visose savo valdose.'),
  (@b12, 20, 14, 'Tada pranašas Izaijas atėjo pas karalių Chezekiją ir jam pasakė: „Ką sakė tie vyrai? Ir iš kur jie atėjo pas tave?“ Ir Chezekijas tarė: „Jie atėjo iš tolimos šalies – iš Babilono“.'),
  (@b12, 20, 15, 'Ir jis tarė: „Ką jie matė tavo namuose?“ Ir Chezekijas atsakė: „Jie matė viską, kas yra mano namuose; nėra nieko mano ižduose, ko nebūčiau jiems parodęs“.'),
  (@b12, 20, 16, 'Ir Izaijas tarė Chezekijui: „Klausyk VIEŠPATIES žodžio:'),
  (@b12, 20, 17, '‘Štai ateina dienos, kai bus išnešta į Babiloną viskas, kas yra tavo namuose ir ką iki šios dienos yra sukrovę tavo tėvai; nieko nebus palikta, – sako VIEŠPATS.'),
  (@b12, 20, 18, '– Ir jie paims iš tavo sūnų, kurie išeis iš tavęs, kuriuos tu pagimdysi; ir jie bus eunuchais Babilono karaliaus rūmuose’“.'),
  (@b12, 20, 19, 'Tada Chezekijas tarė Izaijui: „Geras yra VIEŠPATIES žodis, kurį kalbėjai“. Ir jis sakė: „Argi negerai, jei mano dienomis bus taika ir tiesa?“'),
  (@b12, 20, 20, 'O kiti Chezekijo darbai, visa jo galybė ir kaip jis padarė tvenkinį bei vandentakį ir atvedė vandenį į miestą, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 20, 21, 'Ir Chezekijas užmigo prie savo tėvų; o jo sūnus Manasas karaliavo jo vietoje.'),
  (@b12, 21, 1, 'Manasas buvo dvylikos metų, kai pradėjo karaliauti, ir penkiasdešimt penkerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Hefci-Ba.'),
  (@b12, 21, 2, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, pagal bjaurystes pagonių, kuriuos VIEŠPATS buvo išvaręs iš Izraelio vaikų akivaizdos.'),
  (@b12, 21, 3, 'Nes jis vėl atstatė aukštumas, kurias jo tėvas Chezekijas buvo sunaikinęs; ir jis pastatė aukurų Baalui, padarė giraitę, kaip darė Izraelio karalius Ahabas; ir garbino visą dangaus kariuomenę ir jai tarnavo.'),
  (@b12, 21, 4, 'Ir jis pastatė aukurus VIEŠPATIES namuose, apie kuriuos VIEŠPATS buvo pasakęs: „Jeruzalėje pastatysiu savo vardą“.'),
  (@b12, 21, 5, 'Ir jis pastatė aukurus visai dangaus kariuomenei dviejuose VIEŠPATIES namų kiemuose.'),
  (@b12, 21, 6, 'Ir jis darė, kad jo sūnus eitų per ugnį, ir laikėsi laikų, užsiiminėjo kerais ir bendravo su namų dvasiomis bei magais; jis darė daug nedorybės VIEŠPATIES akyse, kad kurstytų jo pyktį.'),
  (@b12, 21, 7, 'Jis pastatė raižytą giraitės atvaizdą, kurį buvo padaręs namuose, apie kuriuos VIEŠPATS pasakė Dovydui ir jo sūnui Saliamonui: „Šituose namuose ir Jeruzalėje, kurią išsirinkau iš visų Izraelio genčių, aš pastatysiu savo vardą amžiams;'),
  (@b12, 21, 8, 'ir daugiau nebeversiu Izraelio kojoms eiti iš šalies, kurią daviau jų tėvams; jei tik jie laikysis, kad darytų pagal viską, ką jiems įsakiau, ir pagal visą įstatymą, kurį jiems įsakė mano tarnas Mozė“.'),
  (@b12, 21, 9, 'Bet jie neklausė; ir Manasas juos suvedžiojo, kad jie darytų daugiau pikto negu darė tautos, kurias VIEŠPATS išnaikino Izraelio vaikų akivaizdoje.'),
  (@b12, 21, 10, 'Ir VIEŠPATS kalbėjo per savo tarnus pranašus, sakydamas:'),
  (@b12, 21, 11, '„Kadangi Judos karalius Manasas darė šitas bjaurystes ir elgėsi nedoriau už viską, ką buvo darę amoritai, buvusieji pirma jo, ir taip pat savo stabais skatino Judą nusidėti;'),
  (@b12, 21, 12, 'todėl taip sako VIEŠPATS, Izraelio Dievas: ‘Štai aš užleidžiu pikta ant Jeruzalės ir Judos, kad kiekvienam, kuris apie tai išgirs, spengs abi ausys.'),
  (@b12, 21, 13, 'Ir ištiesiu virš Jeruzalės Samarijos virvę bei Ahabo namų svambalą; ir iššluostysiu Jeruzalę, kaip žmogus iššluosto lėkštę, ją iššluosto ir apverčia.'),
  (@b12, 21, 14, 'Ir paliksiu savo paveldo likutį, ir juos atiduosiu į jų priešų rankas; ir jie taps visiems savo priešams grobiu bei laimikiu;'),
  (@b12, 21, 15, 'kadangi jie darė tai, kas buvo pikta mano akyse, ir kurstė mano pyktį nuo tos dienos, kai jų tėvai išėjo iš Egipto, iki šios dienos“.'),
  (@b12, 21, 16, 'Be to, Manasas išliejo labai daug nekalto kraujo, kol pripildė Jeruzalę nuo vieno galo iki kito; neskaitant jo nuodėmės, kuria jis skatino Judą nusidėti, darydamas tai, kas pikta VIEŠPATIES akyse.'),
  (@b12, 21, 17, 'Na, o kiti Manaso darbai ir visa, ką jis darė, ir jo nuodėmė, kuria jis nusidėjo, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 21, 18, 'Ir Manasas užmigo prie savo tėvų ir buvo palaidotas savo namų sode, Uzos sode; o jo sūnus Amonas karaliavo jo vietoje.'),
  (@b12, 21, 19, 'Amonas buvo dvidešimt dvejų metų, kai pradėjo karaliauti, ir dvejus metus karaliavo Jeruzalėje. O jo motinos vardas buvo Mešulemeta, Haruco duktė iš Jotbos.'),
  (@b12, 21, 20, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, kaip darė jo tėvas Manasas.'),
  (@b12, 21, 21, 'Ir jis vaikščiojo visu keliu, kuriuo vaikščiojo jo tėvas, ir tarnavo stabams, kuriems tarnavo jo tėvas, ir juos garbino;'),
  (@b12, 21, 22, 'ir jis paliko VIEŠPATĮ, savo tėvų Dievą, ir nevaikščiojo VIEŠPATIES keliu.'),
  (@b12, 21, 23, 'Ir Amono tarnai surengė prieš jį sąmokslą ir nužudė karalių jo namuose.'),
  (@b12, 21, 24, 'O šalies tauta užmušė visus, kurie buvo surengę sąmokslą prieš karalių Amoną; ir šalies tauta paskyrė į jo vietą karaliumi jo sūnų Joziją.'),
  (@b12, 21, 25, 'Na, o kiti Amono darbai, kuriuos jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 21, 26, 'Ir jis buvo palaidotas savo kape, Uzos sode; o jo sūnus Jozijas karaliavo jo vietoje.'),
  (@b12, 22, 1, 'Jozijas buvo aštuonerių metų, kai pradėjo karaliauti, ir trisdešimt vienerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Jedida, duktė Adajo iš Boskato.'),
  (@b12, 22, 2, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, ir vaikščiojo visu savo tėvo Dovydo keliu, ir nenukrypo nei į dešinę, nei į kairę.'),
  (@b12, 22, 3, 'Ir aštuonioliktais karaliaus Jozijo metais įvyko, kad karalius siuntė raštininką Šafaną, Mešulamo sūnaus Acalijo sūnų, į VIEŠPATIES namus, sakydamas:'),
  (@b12, 22, 4, '„Eik aukštyn pas aukščiausiąjį kunigą Hilkiją, kad jis susumuotų į VIEŠPATIES namus atneštą sidabrą, kurį durų sargai yra surinkę iš tautos;'),
  (@b12, 22, 5, 'ir tegul jį atiduoda į rankas darbo dirbėjams, prižiūrintiems VIEŠPATIES namus; o jie tegul jį duoda dirbėjams darbo, esančio VIEŠPATIES namuose, kad taisytų namų spragas,'),
  (@b12, 22, 6, 'dailidėms, statytojams, mūrininkams ir kad nupirktų medienos ir tašytų akmenų namams taisyti.'),
  (@b12, 22, 7, 'Tačiau nebuvo su jais atsiskaitoma už pinigus, atiduotus į jų rankas, nes jie ištikimai elgėsi“.'),
  (@b12, 22, 8, 'Ir aukščiausiasis kunigas Hilkijas tarė raštininkui Šafanui: „Radau įstatymo knygą VIEŠPATIES namuose“. Ir Hilkijas padavė knygą Šafanui, ir jis ją skaitė.'),
  (@b12, 22, 9, 'Ir raštininkas Šafanas, atėjęs pas karalių, parnešė karaliui žinią ir tarė: „Tavo tarnai surinko pinigus, rastus namuose, ir juos atidavė į rankas darbo dirbėjų, prižiūrinčių VIEŠPATIES namus“.'),
  (@b12, 22, 10, 'Ir raštininkas Šafanas pranešė karaliui, sakydamas: „Kunigas Hilkijas man davė knygą“. Ir Šafanas ją skaitė karaliaus akivaizdoje.'),
  (@b12, 22, 11, 'Ir įvyko, kai karalius išgirdo įstatymo knygos žodžius, jis perplėšė savo drabužius.'),
  (@b12, 22, 12, 'Ir karalius įsakė kunigui Hilkijui, Šafano sūnui Ahikamui, Mikajo sūnui Achborui, raštininkui Šafanui ir karaliaus tarnui Asajai, sakydamas:'),
  (@b12, 22, 13, '„Eikite, pasiklauskite VIEŠPATIES už mane, už tautą ir už visą Judą dėl šitos atrastos knygos žodžių; nes didelė yra VIEŠPATIES rūstybė, kuri užsidegė prieš mus dėl to, kad mūsų tėvai neklausė šitos knygos žodžių, kad elgtųsi pagal visa tai, kas dėl mūsų parašyta“.'),
  (@b12, 22, 14, 'Taigi kunigas Hilkijas, Ahikamas, Achboras, Šafanas ir Asaja nuėjo pas pranašę Huldą, žmoną Šalumo, Tikvos sūnaus, Harhaso sūnaus, drabužių saugotojo (na, o ji gyveno Jeruzalėje, mokymo namuose), ir jie kalbėjosi su ja.'),
  (@b12, 22, 15, 'Ir ji jiems tarė: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Sakykite tai vyrui, kuris jus siuntė pas mane:'),
  (@b12, 22, 16, 'Taip sako VIEŠPATS: „Štai aš užleisiu pikta ant šitos vietos ir ant jos gyventojų – visus šios knygos žodžius, kuriuos skaitė Judos karalius;'),
  (@b12, 22, 17, 'kadangi jie paliko mane ir degino smilkalus kitiems dievams, kad kurstytų mano pyktį visais savo rankų darbais; todėl mano rūstybė užsidegs prieš šitą vietą ir neužges“’.'),
  (@b12, 22, 18, 'Bet Judos karaliui, kuris siuntė jus pasiklausti VIEŠPATIES, taip jam sakykite: ‘Taip sako VIEŠPATS, Izraelio Dievas: Dėl žodžių, kuriuos girdėjai;'),
  (@b12, 22, 19, 'kadangi tavo širdis buvo minkšta ir tu nusižeminai VIEŠPATIES akivaizdoje, išgirdęs tai, ką kalbėjau prieš šitą vietą ir prieš jos gyventojus, kad jie taps nusiaubimu ir prakeikimu, ir kadangi persiplėšei savo drabužius ir verkei mano akivazdoje; tai ir aš tave išgirdau, sako VIEŠPATS.'),
  (@b12, 22, 20, 'Todėl štai aš tave surinksiu prie tavo tėvų, ir tu būsi surinktas į savo kapą ramybėje; ir tavo akys nematys visos tos nelaimės, kurią aš užleisiu ant šitos vietos’“. Ir jie parnešė žinią karaliui.'),
  (@b12, 23, 1, 'Ir karalius pasiuntė, ir jie sukvietė pas jį visus Judos ir Jeruzalės vyresniuosius.'),
  (@b12, 23, 2, 'Ir karalius nuėjo aukštyn į VIEŠPATIES namus ir su juo visi Judos žmonės bei visi Jeruzalės gyventojai, kunigai ir pranašai, ir visa tauta, tiek maži, tiek dideli; ir jis perskaitė jiems į ausis visus žodžius sandoros knygos, atrastos VIEŠPATIES namuose.'),
  (@b12, 23, 3, 'Ir karalius, atsistojęs prie stulpo, sudarė sandorą VIEŠPATIES akivaizdoje, vaikščioti paskui VIEŠPATĮ ir laikytis jo įsakymų, jo liudijimų ir jo įstatų visa jų širdimi bei visa jų siela, vykdyti šitos sandoros žodžius, užrašytus šitoje knygoje. Ir visa tauta įstojo į sandorą.'),
  (@b12, 23, 4, 'Ir karalius įsakė aukščiausiajam kunigui Hilkijui, antrosios eilės kunigams ir durų sargams išnešti iš VIEŠPATIES šventyklos visus reikmenis, padarytus Baalui ir giraitei bei visai dangaus kariuomenei; ir jis juos sudegino už Jeruzalės, Kidrono laukuose, o jų pelenus nugabeno į Bet-Elį.'),
  (@b12, 23, 5, 'Ir jis išnaikino stabmeldiškus kunigus, kuriuos Judos karaliai buvo paskyrę smilkalams deginti aukštumose, Judos miestuose ir Jeruzalės apylinkėse; taip pat tuos, kurie degino smilkalus Baalui, saulei, mėnuliui, planetoms ir visai dangaus kariuomenei.'),
  (@b12, 23, 6, 'Ir jis išnešė giraitę iš VIEŠPATIES namų už Jeruzalės prie Kidrono upelio ir ją sudegino prie Kidrono upelio, susmulkino ją į miltus ir išbarstė jos miltus ant tautos vaikų kapų.'),
  (@b12, 23, 7, 'Ir jis nugriovė sodomitų namus, buvusius prie VIEŠPATIES namų, kur moterys ausdavo užuolaidas giraitei.'),
  (@b12, 23, 8, 'Ir jis išvedė visus kunigus iš Judos miestų ir išniekino aukštumas, kuriose kunigai degino smilkalus, nuo Gebos iki Beer-Šebos, ir nugriovė vartų aukštumas, buvusias prie miesto valdytojo Jozuės vartų įėjimo, miesto vartų kairėje.'),
  (@b12, 23, 9, 'Tačiau aukštumų kunigai neateidavo aukštyn prie VIEŠPATIES aukuro Jeruzalėje, bet jie valgė neraugintos duonos tarp savo brolių.'),
  (@b12, 23, 10, 'Ir jis išniekino Tofetą, esantį Hinomo vaikų slėnyje, idant niekas nevestų savo sūnaus ar savo dukters per ugnį Molechui.'),
  (@b12, 23, 11, 'Ir jis pašalino žirgus, kuriuos Judos karaliai buvo davę saulei, prie VIEŠPATIES namų įėjimo, prie rūmininko Natan-Melecho kambario, buvusio priemiestyje, ir sudegino saulės vežimus ugnimi.'),
  (@b12, 23, 12, 'O aukurus, buvusius ant Ahazo aukštutinio kambario stogo, kuriuos buvo padarę Judos karaliai, ir aukurus, kuriuos Manasas buvo padaręs abiejuose VIEŠPATIES namų kiemuose, karalius nugriovė ir juos iš ten sutrupinęs subėrė jų dulkes į Kidrono upelį.'),
  (@b12, 23, 13, 'Ir karalius išniekino aukštumas, buvusias prieš Jeruzalę, kurios buvo Sugedimo kalno dešinėje, kurias Izraelio karalius Saliamonas buvo pastatęs sidoniečių bjaurybei Astoretei, moabiečių bjaurybei Kemošui ir Amono vaikų bjaurybei Milkomui.'),
  (@b12, 23, 14, 'Ir jis sutrupino atvaizdus, iškirto giraites ir jų vietas pripildė žmonių kaulais.'),
  (@b12, 23, 15, 'Taip pat aukurą, buvusį Bet-Elyje, ir aukštumą, kurią buvo padaręs Nebato sūnus Jeroboamas, kuris skatino Izraelį nusidėti, tiek tą aukurą, tiek aukštumą jis nugriovė ir sudegino aukštumą, sutrypė ją į miltus ir sudegino giraitę.'),
  (@b12, 23, 16, 'Ir pasisukęs Jozijas pamatė kapus, kurie buvo ten, kalne, ir pasiuntė, išėmė kaulus iš kapų, sudegino juos ant aukuro ir išniekino jį pagal VIEŠPATIES žodį, kurį paskelbė Dievo vyras, paskelbdamas šiuos žodžius.'),
  (@b12, 23, 17, 'Tada jis tarė: „Kokia tai antraštė, kurią aš matau?“ Ir miesto žmonės jam pasakė: „Tai kapas Dievo vyro, kuris atėjo iš Judos ir paskelbė šituos dalykus, kuriuos tu įvykdei prieš Bet-Elio aukurą“.'),
  (@b12, 23, 18, 'Ir jis tarė: „Palikite jį; niekas tenejudina jo kaulų“. Taip jie paliko jo kaulus drauge su kaulais to pranašo, kuris buvo atėjęs iš Samarijos.'),
  (@b12, 23, 19, 'Jozijas taip pat pašalino ir visus aukštumų namus, buvusius Samarijos miestuose, kuriuos buvo padarę Izraelio karaliai, kad kurstytų VIEŠPATIES pyktį, ir jiems padarė pagal visus tuos darbus, kuriuos buvo padaręs Bet-Elyje.'),
  (@b12, 23, 20, 'Ir jis išžudė visus aukštumų kunigus, buvusius ten, ant aukurų, ir sudegino ant jų žmonių kaulus, ir sugrįžo į Jeruzalę.'),
  (@b12, 23, 21, 'Ir karalius įsakė visai tautai, sakydamas: „Švęskite Apėjimą VIEŠPAČIUI, savo Dievui, kaip yra parašyta šitos sandoros knygoje“.'),
  (@b12, 23, 22, 'Tikrai tokio Apėjimo nebuvo švęsta nei nuo dienų teisėjų, kurie teisė Izraelį, nei per visas Izraelio karalių, nei per Judos karalių dienas;'),
  (@b12, 23, 23, 'bet aštuonioliktais karaliaus Jozijo metais, kuriais buvo švenčiamas šis Apėjimas VIEŠPAČIUI Jeruzalėje.'),
  (@b12, 23, 24, 'Be to, Jozijas pašalino užsiiminėjančius namų dvasiomis, magus, atvaizdus, stabus ir visas bjaurystes, pamatytas Judos šalyje ir Jeruzalėje, kad įvykdytų įstatymo žodžius, užrašytus knygoje, kurią kunigas Hilkijas rado VIEŠPATIES namuose.'),
  (@b12, 23, 25, 'Pirma jo nebuvo jam lygaus karaliaus, kuris atsigręžtų į VIEŠPATĮ visa savo širdimi, visa savo siela ir visa savo galybe, pagal visą Mozės įstatymą; ir po jo nebeiškilo tokio kaip jis.'),
  (@b12, 23, 26, 'Tačiau VIEŠPATS nenusigręžė nuo piktumo savo didelės rūstybės, kuria jo pyktis buvo užsidegęs prieš Judą dėl visų kurstymų, kuriais jį kurstė Manasas.'),
  (@b12, 23, 27, 'Ir VIEŠPATS pasakė: „Judą taip pat pašalinsiu sau iš akių, kaip pašalinau Izraelį, ir atmesiu šitą miestą Jeruzalę, kurį esu išsirinkęs, ir tuos namus, apie kuriuos pasakiau: ‘Ten bus mano vardas’“.'),
  (@b12, 23, 28, 'Na, o kiti Jozijo darbai ir visa, ką jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 23, 29, 'Jo dienomis faraonas-Nechojas, Egipto karalius, ėjo aukštyn prieš Asirijos karalių iki Eufrato upės; ir karalius Jozijas ėjo prieš jį; ir jis nužudė jį Megide, kai jį pamatė.'),
  (@b12, 23, 30, 'Ir jo tarnai vežė jį vežime mirusį iš Megido ir, pargabenę į Jeruzalę, jį palaidojo jo kape. O šalies tauta, paėmę Jozijo sūnų Jehoachazą, patepė jį ir padarė jį karaliumi jo tėvo vietoje.'),
  (@b12, 23, 31, 'Jehoachazas buvo dvidešimt trejų metų, kai pradėjo karaliauti; ir tris mėnesius karaliavo Jeruzalėje. O jo motinos vardas buvo Hamutala, duktė Jeremijo iš Libnos.'),
  (@b12, 23, 32, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse pagal visa tai, ką buvo darę jo tėvai.'),
  (@b12, 23, 33, 'Ir faraonas-Nechojas jį surišo Ribloje, Hamato šalyje, kad jis nekaraliautų Jeruzalėje; ir uždėjo šaliai šimto talentų sidabro ir talento aukso duoklę.'),
  (@b12, 23, 34, 'Ir faraonas-Nechojas padarė karaliumi Jozijo sūnų Eljakimą jo tėvo Jozijo vietoje ir pakeitė jo vardą į Jehojakimą, o Jehoachazą pašalino; ir jis atėjo į Egiptą ir ten mirė.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b12, 23, 35, 'Ir Jehojakimas davė sidabrą ir auksą faraonui; bet jis apmokestino šalį, kad duotų pinigus pagal faraono įsakymą; jis pareikalavo sidabro ir aukso iš šalies tautos, iš kiekvieno pagal jo mokestį, kad tai duotų faraonui-Nechojui.'),
  (@b12, 23, 36, 'Jehojakimas buvo dvidešimt penkerių metų, kai pradėjo karaliauti; ir vienuolika metų karaliavo Jeruzalėje. O jo motinos vardas buvo Zebida, duktė Pedajo iš Rumos.'),
  (@b12, 23, 37, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, pagal visa tai, ką darė jo tėvai.'),
  (@b12, 24, 1, 'Jo dienomis atėjo aukštyn Babilono karalius Nebukadnecaras, ir Jehojakimas tapo jo tarnu trejus metus; po to jis atsigręžė ir sukilo prieš jį.'),
  (@b12, 24, 2, 'Ir VIEŠPATS siuntė prieš jį kaldėjų būrius, sirų būrius, moabiečių būrius ir Amono vaikų būrius, ir siuntė juos prieš Judą, kad sunaikintų ją pagal VIEŠPATIES žodį, kurį jis kalbėjo per savo tarnus pranašus.'),
  (@b12, 24, 3, 'Tikrai VIEŠPATIES įsakymu tai atsitiko Judai, kad pašalintų juos sau iš akių dėl Manaso nuodėmių, pagal visa tai, ką jis padarė;'),
  (@b12, 24, 4, 'ir taip pat dėl nekalto kraujo, kurį jis išliejo; nes jis pripildė Jeruzalę nekalto kraujo; ko VIEŠPATS nenorėjo atleisti.'),
  (@b12, 24, 5, 'Na, o kiti Jehojakimo darbai ir visa, ką jis darė, argi jie nėra užrašyti Judos karalių kronikų knygoje?'),
  (@b12, 24, 6, 'Taigi Jehojakimas užmigo prie savo tėvų; o jo sūnus Jehojakinas karaliavo jo vietoje.'),
  (@b12, 24, 7, 'Ir Egipto karalius daugiau nebeišėjo iš savo šalies; nes Babilono karalius buvo atėmęs viską, kas priklausė Egipto karaliui, nuo Egipto upės iki Eufrato upės.'),
  (@b12, 24, 8, 'Jehojakinas buvo aštuoniolikos metų, kai pradėjo karaliauti, ir tris mėnesius karaliavo Jeruzalėje. O jo motinos vardas buvo Nehušta, duktė Elnatano iš Jeruzalės.'),
  (@b12, 24, 9, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, pagal visa tai, ką darė jo tėvas.'),
  (@b12, 24, 10, 'Tuo metu Babilono karaliaus Nebukadnecaro tarnai atėjo aukštyn prieš Jeruzalę, ir miestas buvo apgultas.'),
  (@b12, 24, 11, 'Ir Babilono karalius Nebukadnecaras atėjo prieš miestą, ir jo tarnai jį apgulė.'),
  (@b12, 24, 12, 'Ir Judos karalius Jehojakinas išėjo pas Babilono karalių, jis, jo motina, jo tarnai, jo kunigaikščiai ir jo pareigūnai; ir Babilono karalius jį paėmė aštuntaisiais savo karaliavimo metais.'),
  (@b12, 24, 13, 'Ir jis išgabeno iš ten visus VIEŠPATIES namų lobius bei karaliaus namų lobius ir sukapojo į gabalus visus auksinius indus, kuriuos Izraelio karalius Saliamonas buvo padaręs VIEŠPATIES šventykloje, kaip VIEŠPATS buvo sakęs.'),
  (@b12, 24, 14, 'Ir jis išvedė visą Jeruzalę, visus kunigaikščius ir visus narsius galiūnus – dešimt tūkstančių belaisvių, ir visus amatininkus bei kalvius; nieko neliko, tik vargingiausi iš šalies tautos.'),
  (@b12, 24, 15, 'Ir jis išvedė į Babiloną Jehojakiną, karaliaus motiną, karaliaus žmonas, jo pareigūnus ir šalies galinguosius, šituos jis išvedė iš Jeruzalės nelaisvėn į Babiloną.'),
  (@b12, 24, 16, 'Ir visus galingus vyrus – septynis tūkstančius, ir tūkstantį amatininkų bei kalvių, visus stiprius, tinkamus karui, būtent juos Babilono karalius išvedė nelaisvėn į Babiloną.'),
  (@b12, 24, 17, 'Ir Babilono karalius paskyrė jo vietoje karaliumi jo tėvo brolį Mataniją, ir jo vardą pakeitė Zedekiju.'),
  (@b12, 24, 18, 'Zedekijas buvo dvidešimt vienerių metų, kai pradėjo karaliauti, ir vienuolika metų karaliavo Jeruzalėje. O jo motinos vardas buvo Hamutala, duktė Jeremijo iš Libnos.'),
  (@b12, 24, 19, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, pagal visa tai, ką buvo daręs Jehojakimas.'),
  (@b12, 24, 20, 'Nes dėl VIEŠPATIES pykčio tai atsitiko Jeruzalėje ir Judoje, kol jis juos išmetė iš savo akivaizdos, kad Zedekijas sukilo prieš Babilono karalių.'),
  (@b12, 25, 1, 'Ir įvyko, kad devintaisiais jo karaliavimo metais, dešimtąjį mėnesį, dešimtąją to mėnesio dieną, atėjo Babilono karalius Nebukadnecaras, jis ir visa jo kariuomenė, prieš Jeruzalę ir stovyklavo prieš ją; ir jie pastatė prieš ją fortus aplinkui.'),
  (@b12, 25, 2, 'Ir miestas buvo apgultas iki vienuoliktųjų karaliaus Zedekijo metų.'),
  (@b12, 25, 3, 'O ketvirtojo mėnesio devintąją dieną mieste įsigalėjo badas, ir nebuvo duonos šalies tautai.'),
  (@b12, 25, 4, 'Ir miestas buvo pralaužtas, ir naktį visi karo vyrai pabėgo vartų keliu tarp abiejų sienų, esančių prie karaliaus sodo (na, o kaldėjai buvo aplinkui prieš miestą); ir karalius ėjo keliu link lygumos.'),
  (@b12, 25, 5, 'Ir kaldėjų kariuomenė vijosi karalių ir jį pasivijo Jericho lygumose; ir visa jo kariuomenė buvo nuo jo išsklaidyta.'),
  (@b12, 25, 6, 'Taigi jie sučiupo karalių ir nuvedė jį aukštyn į Riblą pas Babilono karalių; ir jie teisė jį.'),
  (@b12, 25, 7, 'Ir jie nužudė Zedekijo sūnus jam prieš akis, o Zedekijui išlupo akis ir sukaustė jį žalvario grandinėmis, ir nuvedė jį į Babiloną.'),
  (@b12, 25, 8, 'Ir penktąjį mėnesį, septintąją to mėnesio dieną, tai yra devynioliktaisiais karaliaus Nebukadnecaro, Babilono karaliaus, metais, į Jeruzalę atvyko Nebuzar-Adanas, sargybos vadas, Babilono karaliaus tarnas;'),
  (@b12, 25, 9, 'ir jis sudegino VIEŠPATIES namus, karaliaus namus ir visus Jeruzalės namus, ir visus didžiūnų namus jis sudegino ugnimi.'),
  (@b12, 25, 10, 'Ir visa kaldėjų kariuomenė, buvusi su sargybos vadu, išgriovė aplink Jeruzalę esančias sienas.'),
  (@b12, 25, 11, 'Na, o kitus iš tautos, likusius mieste, ir pabėgėlius, persimetusius pas Babilono karalių, su minios likučiu išsivedė sargybos vadas Nebuzar-Adanas.'),
  (@b12, 25, 12, 'Bet sargybos vadas paliko šalies vargšų, būti vynuogininkais ir žemdirbiais.'),
  (@b12, 25, 13, 'Ir žalvario stulpus, buvusius VIEŠPATIES namuose, stovus ir žalvarinę jūrą, buvusią VIEŠPATIES namuose, kaldėjai sutrupino ir jų varį išgabeno į Babiloną.'),
  (@b12, 25, 14, 'Ir jie paėmė puodus, semtuvus, gnybtuvus, šaukštus ir visus žalvario indus, kuriais tarnaudavo.'),
  (@b12, 25, 15, 'Ir sargybos vadas paėmė žarijų lovius ir taures, ir tai, kas buvo iš aukso, kaip auksą, o kas iš sidabro, kaip sidabrą.'),
  (@b12, 25, 16, 'Du stulpai, viena jūra ir stovai, kuriuos Saliamonas buvo padaręs VIEŠPATIES namams, – visų šitų reikmenų žalvario nebuvo įmanoma pasverti.'),
  (@b12, 25, 17, 'Vienas stulpas buvo aštuoniolikos uolekčių aukščio, o kapitelis ant jo buvo žalvaris; kapitelis buvo trijų uolekčių aukščio; pintas dirbinys ir granatai aplinkui ant kapitelio, visi iš žalvario; ir tokius pat turėjo antrasis stulpas su pintu dirbiniu.'),
  (@b12, 25, 18, 'Ir sargybos vadas paėmė vyriausiąjį kunigą Serają, antrąjį kunigą Sefaniją ir tris durų sargus;'),
  (@b12, 25, 19, 'o iš miesto jis paėmė pareigūną, kuris buvo paskirtas vadovauti karo vyrams, ir penkis vyrus iš tų, kurie būdavo karaliaus akivaizdoje, kuriuos rado mieste, ir kariuomenės pagrindinį raštininką, kuris surinkdavo šalies tautą, ir šešiasdešimt šalies tautos vyrų, rastų mieste;'),
  (@b12, 25, 20, 'ir sargybos vadas Nebuzar-Adanas paėmė juos ir nugabeno pas Babilono karalių į Riblą;'),
  (@b12, 25, 21, 'o Babilono karalius juos sumušė ir nužudė Ribloje, Hamato šalyje. Taip Juda buvo ištremta iš savo šalies.'),
  (@b12, 25, 22, 'O dėl Judos šalyje likusios tautos, kurią Babilono karalius Nebukadnecaras buvo palikęs, jis paskyrė jiems valdovu Gedaliją, Šafano sūnaus Ahikamo sūnų.'),
  (@b12, 25, 23, 'Ir kai visi kariuomenių vadai, jie patys ir jų vyrai, išgirdo, kad Babilono karalius paskyrė Gedaliją valdytoju, atėjo pas Gedaliją į Micpą: Netanijos sūnus Išmaelis, Kareacho sūnus Johananas, netofiečio Tanhumeto sūnus Seraja ir maako sūnus Jaazanijas – jie patys ir jų vyrai.'),
  (@b12, 25, 24, 'Ir Gedalijas prisiekė jiems ir jų vyrams, ir jiems tarė: „Nebijokite būti kaldėjų tarnais; gyvenkite šalyje ir tarnaukite Babilono karaliui; ir jums bus gerai“.'),
  (@b12, 25, 25, 'Bet septintąjį mėnesį atsitiko, kad atėjo Elišamos sūnaus Netanijos sūnus Išmaelis, iš karališkosios sėklos, ir su juo dešimt vyrų, ir sumušė Gedaliją, kad jis mirė, bei žydus ir kaldėjus, esančius su juo Micpoje.'),
  (@b12, 25, 26, 'Ir visa tauta, tiek maži, tiek dideli, ir kariuomenių vadai, pakilę atėjo į Egiptą; nes jie bijojo kaldėjų.'),
  (@b12, 25, 27, 'Ir įvyko, kad trisdešimt septintaisiais Judos karaliaus Jehojakino nelaisvės metais, dvyliktąjį mėnesį, dvidešimt septintąją to mėnesio dieną, Babilono karalius Evil-Merodachas tais metais, kai pradėjo karaliauti, iškėlė Judos karaliaus Jehojakino galvą iš kalėjimo;'),
  (@b12, 25, 28, 'ir jis maloniai jam kalbėjo, ir pastatė jo sostą aukščiau už sostą karalių, buvusių su juo Babilone;'),
  (@b12, 25, 29, 'ir pakeitė jo kalėjimo drabužius; ir jis nuolat valgė duoną jo akivaizdoje per visas savo gyvenimo dienas.'),
  (@b12, 25, 30, 'Ir jo aprūpinimas buvo nuolatinis aprūpinimas, jam duodamas nuo karaliaus, kasdieninė norma kiekvienai dienai, per visas jo gyvenimo dienas.'),
  (@b13, 1, 1, 'Adomas, Šetas, Enas,'),
  (@b13, 1, 2, 'Kenanas, Malaleelis, Jeretas,'),
  (@b13, 1, 3, 'Henochas, Matūzalis, Lamechas,'),
  (@b13, 1, 4, 'Nojus, Šemas, Chamas ir Jafetas.'),
  (@b13, 1, 5, 'Jafeto sūnūs: Gomeras, Magogas, Madajas, Javanas, Tubalas, Mešechas ir Tiras.'),
  (@b13, 1, 6, 'O Gomero sūnūs: Aškenazas, Rifatas ir Togarma.'),
  (@b13, 1, 7, 'O Javano sūnūs: Eliša, Taršišas, kitiečiai ir dodaniečiai.'),
  (@b13, 1, 8, 'Chamo sūnūs: Kušas ir Mizraimas, Putas ir Kanaanas.'),
  (@b13, 1, 9, 'O Kušo sūnūs: Seba, Havila, Sabta, Raama ir Sabtecha. O Raamos sūnūs: Šeba ir Dedanas.'),
  (@b13, 1, 10, 'Ir Kušas pagimdė Nimrodą; jis pradėjo būti galingas žemėje.'),
  (@b13, 1, 11, 'O Mizraimas pagimdė ludus, anamiečius, lehabus, naftuchiečius,'),
  (@b13, 1, 12, 'patrusiečius, kasluchus (iš kurių kilo filistinai) ir kaftoriečius.'),
  (@b13, 1, 13, 'Kanaanas pagimdė savo pirmagimį Sidoną, Hetą,'),
  (@b13, 1, 14, 'taip pat jebusietį, amoritą, girgašą,'),
  (@b13, 1, 15, 'hivą, arką, siną,'),
  (@b13, 1, 16, 'arvadietį, cemarą ir hamatietį.'),
  (@b13, 1, 17, 'Šemo sūnūs: Elamas, Ašūras, Arfaksadas, Ludas, Aramas, Ucas, Hulas, Geteras ir Mešechas.'),
  (@b13, 1, 18, 'Arfaksadas pagimdė Šelą, o Šela pagimdė Eberą.'),
  (@b13, 1, 19, 'O Eberui gimė du sūnūs: vieno vardas buvo Pelegas; nes jo dienomis žemė buvo padalyta; o jo brolio vardas buvo Joktanas.'),
  (@b13, 1, 20, 'Ir Joktanas pagimdė Almodadą, Šelefą, Hacarmavetą, Jerachą,'),
  (@b13, 1, 21, 'Hadoramą, Uzalą, Diklą,'),
  (@b13, 1, 22, 'Ebalą, Abimaelį, Šebą,'),
  (@b13, 1, 23, 'Ofyrą, Havilą ir Jobabą. Tie visi buvo Joktano sūnūs.'),
  (@b13, 1, 24, 'Šemas, Arfaksadas, Šela,'),
  (@b13, 1, 25, 'Eberas, Pelegas, Rejus,'),
  (@b13, 1, 26, 'Serugas, Nahoras, Tera,'),
  (@b13, 1, 27, 'Abramas; tas pats yra Abraomas.'),
  (@b13, 1, 28, 'Abraomo sūnūs: Izaokas ir Išmaelis.'),
  (@b13, 1, 29, 'Šita yra jų genealogija: Išmaelio pirmagimis Nebajotas; po to Kedaras, Adbeelis, Mibsamas,'),
  (@b13, 1, 30, 'Mišma, Dūma, Masa, Hadadas ir Tema,'),
  (@b13, 1, 31, 'Jetūras, Nafišas ir Kedma. Tie yra Išmaelio sūnūs.'),
  (@b13, 1, 32, 'Na, o Abraomo sugulovės Ketūros sūnūs: ji pagimdė Zimraną, Jokšaną, Medaną, Midjaną, Išbaką ir Šuachą. O Jokšano sūnūs: Šeba ir Dedanas.'),
  (@b13, 1, 33, 'O Midjano sūnūs: Efa, Eferas, Henochas, Abida ir Eldava. Tie visi yra Ketūros sūnūs.'),
  (@b13, 1, 34, 'Ir Abraomas pagimdė Izaoką. Izaoko sūnūs: Ezavas ir Izraelis.'),
  (@b13, 1, 35, 'Ezavo sūnūs: Elifazas, Reuelis, Jeušas, Jaalamas ir Korachas.'),
  (@b13, 1, 36, 'Elifazo sūnūs: Temanas ir Omaras, Sefis ir Gatamas, Kenazas ir Timna, ir Amalekas.'),
  (@b13, 1, 37, 'Reuelio sūnūs: Nahatas, Zerachas, Šama ir Miza.'),
  (@b13, 1, 38, 'O Seyro sūnūs: Lotanas, Šobalas, Cibeonas, Ana, Dišonas, Eceras ir Dišanas.'),
  (@b13, 1, 39, 'O Lotano sūnūs: Horis ir Homamas; o Lotano sesuo buvo Timna.'),
  (@b13, 1, 40, 'Šobalo sūnūs: Aljanas ir Manahatas, ir Ebalas, Šefis ir Onamas. O Cibeono sūnūs: Aja ir Ana.'),
  (@b13, 1, 41, 'Anos sūnūs: Dišonas. O Dišono sūnūs: Hamramas, Ešbanas, Itranas ir Keranas.'),
  (@b13, 1, 42, 'Ecero sūnūs: Bilhanas, Zavanas ir Jakanas. Dišano sūnūs: Ucas ir Aranas.'),
  (@b13, 1, 43, 'Na, o šitie yra karaliai, kurie karaliavo Edomo šalyje, kai dar joks karalius nekaraliavo Izraelio vaikams: Beoro sūnus Bela; o jo miesto vardas buvo Dinhaba.'),
  (@b13, 1, 44, 'Ir Belai mirus, jo vietoje karaliavo Zeracho sūnus Jobabas iš Bocros.'),
  (@b13, 1, 45, 'O Jobabui mirus, jo vietoje karaliavo Hušamas iš temaniečių šalies.'),
  (@b13, 1, 46, 'O Hušamui mirus, jo vietoje karaliavo Bedado sūnus Hadadas, kuris sumušė Midjaną Moabo lauke; o jo miesto vardas buvo Avitas.'),
  (@b13, 1, 47, 'O Hadadui mirus, jo vietoje karaliavo Samla iš Masrekos.'),
  (@b13, 1, 48, 'O Samlai mirus, jo vietoje karaliavo Šaulius iš Rehoboto, esančio prie upės.'),
  (@b13, 1, 49, 'O Šauliui mirus, jo vietoje karaliavo Achboro sūnus Baal-Hananas.'),
  (@b13, 1, 50, 'O Baal-Hananui mirus, jo vietoje karaliavo Hadadas; ir jo miesto vardas buvo Pavas; o jo žmonos vardas buvo Mehetabelė, Mezahabo dukters Matredos duktė.'),
  (@b13, 1, 51, 'Hadadas taip pat mirė. O Edomo kunigaikščiai buvo: kunigaikštis Timna, kunigaikštis Alija, kunigaikštis Jetetas,'),
  (@b13, 1, 52, 'kunigaikštis Aholibama, kunigaikštis Ela, kunigaikštis Pinonas,'),
  (@b13, 1, 53, 'kunigaikštis Kenazas, kunigaikštis Temanas, kunigaikštis Mibcaras,'),
  (@b13, 1, 54, 'kunigaikštis Magdielis, kunigaikštis Iramas. Tie yra Edomo kunigaikščiai.'),
  (@b13, 2, 1, 'Šitie yra Izraelio sūnūs: Rubenas, Simeonas, Levis ir Juda, Isacharas ir Zebulonas,'),
  (@b13, 2, 2, 'Danas, Juozapas ir Benjaminas, Naftalis, Gadas ir Ašeras.'),
  (@b13, 2, 3, 'Judos sūnūs: Eras, Onanas ir Šela; tie trys jam gimė iš Šūvos dukters, kanaanietės. O Judos pirmagimis Eras buvo blogas VIEŠPATIES akyse; ir jis užmušė jį.'),
  (@b13, 2, 4, 'O jo marti Tamara jam pagimdė Perecą ir Zerachą. Iš viso Judos sūnų buvo penki.'),
  (@b13, 2, 5, 'Pereco sūnūs: Hesronas ir Hamulas.'),
  (@b13, 2, 6, 'O Zeracho sūnūs: Zimris, Etanas, Hemanas, Kalkolas ir Dara; iš viso jų penki.'),
  (@b13, 2, 7, 'O Karmio sūnūs: Acharas, Izraelio drumstėjas, kuris nusižengė prakeiktu dalyku.'),
  (@b13, 2, 8, 'O Etano sūnūs: Azarija.'),
  (@b13, 2, 9, 'Taip pat Hesrono sūnūs, kurie jam gimė: Jerachmeelis, Ramas ir Kelubajas.'),
  (@b13, 2, 10, 'O Ramas pagimdė Aminadabą; o Aminadabas pagimdė Nachšoną, Judos vaikų kunigaikštį;'),
  (@b13, 2, 11, 'o Nachšonas pagimdė Salmą, o Salma pagimdė Boazą,'),
  (@b13, 2, 12, 'o Boazas pagimdė Obedą, o Obedas pagimdė Jesę,'),
  (@b13, 2, 13, 'o Jesė pagimdė savo pirmagimį Eliabą, antrąjį Abinadabą, trečiąjį Šimą,'),
  (@b13, 2, 14, 'ketvirtąjį Netanelį, penktąjį Radają,'),
  (@b13, 2, 15, 'šeštąjį Ocemą, septintąjį Dovydą;'),
  (@b13, 2, 16, 'kurių seserys buvo Ceruja ir Abigailė. O Cerujos sūnūs: Abišajas, Joabas ir Asaelis – trys.'),
  (@b13, 2, 17, 'O Abigailė pagimdė Amasą; o Amasos tėvas buvo išmaelitas Jeteras.'),
  (@b13, 2, 18, 'O Hesrono sūnus Kalebas pagimdė vaikų iš savo žmonos Azubos ir iš Jeriotos; šitie yra jos sūnūs: Ješeras, Šobabas ir Ardonas.'),
  (@b13, 2, 19, 'O Azubai mirus, Kalebas ėmė sau Efratą, kuri jam pagimdė Hūrą.'),
  (@b13, 2, 20, 'O Hūras pagimdė Ūrį, o Ūris pagimdė Becaleelį.'),
  (@b13, 2, 21, 'O paskui Hesronas įėjo pas Gileado tėvo Machyro dukterį, kurią jis vedė, būdamas šešiasdešimties metų; ir ji jam pagimdė Segubą.'),
  (@b13, 2, 22, 'O Segubas pagimdė Jayrą, kuris turėjo dvidešimt tris miestus Gileado šalyje.'),
  (@b13, 2, 23, 'Ir jis atėmė iš jų Gešūrą ir Aramą su Jayro miestais, su Kenatu ir jo miestais – šešiasdešimt miestų. Tie visi priklausė Gileado tėvo Machyro sūnums.'),
  (@b13, 2, 24, 'O Hesronui mirus Kaleb-Efratoje, Hesrono žmona Abija jam pagimdė Tekojos tėvą Ašūrą.'),
  (@b13, 2, 25, 'O Hesrono pirmagimio Jerachmeelio sūnūs buvo pirmagimis Ramas, Buna, Orenas, Ocemas ir Ahija.'),
  (@b13, 2, 26, 'Jerachmeelis dar turėjo kitą žmoną, kurios vardas buvo Atara; ji buvo Onamo motina.'),
  (@b13, 2, 27, 'O Jerachmeelio pirmagimio Ramo sūnūs buvo Maacas, Jaminas ir Ekeras.'),
  (@b13, 2, 28, 'O Onamo sūnūs buvo Šamajas ir Jada. O Šamajo sūnūs: Nadabas ir Abišūras.'),
  (@b13, 2, 29, 'O Abišūro žmonos vardas buvo Abihailė, ir ji jam pagimdė Achbaną ir Molidą.'),
  (@b13, 2, 30, 'O Nadabo sūnūs: Seledas ir Apajimas; bet Seledas mirė be vaikų.'),
  (@b13, 2, 31, 'O Apajimo sūnūs: Išis. O Išio sūnūs: Šešanas. O Šešano vaikai: Achlaja.'),
  (@b13, 2, 32, 'O Šamajo brolio Jados sūnūs: Jeteras ir Jonatanas; o Jeteras mirė bevaikis.'),
  (@b13, 2, 33, 'O Jonatano sūnūs: Peletas ir Zaza. Tie buvo Jerachmeelio sūnūs.'),
  (@b13, 2, 34, 'Na, o Šešanas neturėjo sūnų, tik dukteris. Ir Šešanas turėjo egiptietį tarną, kurio vardas buvo Jarcha.'),
  (@b13, 2, 35, 'Ir Šešanas davė savo dukterį savo tarnui Jarchai į žmonas; ir ji jam pagimdė Atają.'),
  (@b13, 2, 36, 'O Atajas pagimdė Nataną, o Natanas pagimdė Zabadą,'),
  (@b13, 2, 37, 'o Zabadas pagimdė Eflalą, o Eflalas pagimdė Obedą,'),
  (@b13, 2, 38, 'o Obedas pagimdė Jehuvą, o Jehuvas pagimdė Azariją,'),
  (@b13, 2, 39, 'o Azarija pagimdė Helecą, o Helecas pagimdė Eleasą,'),
  (@b13, 2, 40, 'o Eleasa pagimdė Sisamają, o Sisamajas pagimdė Šalumą,'),
  (@b13, 2, 41, 'o Šalumas pagimdė Jekamiją, o Jekamija pagimdė Elišamą.'),
  (@b13, 2, 42, 'Na, o Jerachmeelio brolio Kalebo sūnūs: jo pirmagimis Meša, kuris buvo Zifo tėvas; ir sūnūs Marešos, Hebrono tėvo.'),
  (@b13, 2, 43, 'Ir Hebrono sūnūs: Korachas, Tapuachas, Rekemas ir Šema.'),
  (@b13, 2, 44, 'O Šema pagimdė Rahamą, Jorkoamo tėvą; o Rekemas pagimdė Šamają.'),
  (@b13, 2, 45, 'O Šamajo sūnus buvo Maonas; o Maonas buvo Bet-Cūro tėvas.'),
  (@b13, 2, 46, 'O Kalebo sugulovė Efa pagimdė Haraną, Mocą ir Gazezą; o Haranas pagimdė Gazezą.'),
  (@b13, 2, 47, 'O Jahdajo sūnūs: Regemas, Jotamas, Gešamas, Peletas, Efa ir Šafas.'),
  (@b13, 2, 48, 'Kalebo sugulovė Maaka pagimdė Šeberą ir Tirhaną.'),
  (@b13, 2, 49, 'Ji dar pagimdė Madmanos tėvą Šafą, Ševą – Machbenos tėvą ir Gibėjos tėvą; o Kalebo duktė buvo Achsa.'),
  (@b13, 2, 50, 'Šitie buvo Hūro sūnaus Kalebo, Efratos pirmagimio, sūnūs: Kirjat-Jearimo tėvas Šobalas,'),
  (@b13, 2, 51, 'Betliejaus tėvas Salma, Bet-Gaderio tėvas Harefas.'),
  (@b13, 2, 52, 'Kirjat-Jearimo tėvas Šobalas turėjo sūnų: Haroję ir pusę manahetiečių.'),
  (@b13, 2, 53, 'O Kirjat-Jearimo šeimos: itrai, putai, šumatai ir mišrai; iš jų kilo coriečiai ir eštaoliečiai.'),
  (@b13, 2, 54, 'Salmos sūnūs: Betliejus ir netofiečiai, Atarotas, Joabo namai ir pusė manahetiečių, coriečiai.'),
  (@b13, 2, 55, 'O šeimos raštininkų, gyvenusių Jabece: tiratai, šimeatai ir suchatai. Šitie yra kenitai, kilę iš Hemato, Rechabo namų tėvo.'),
  (@b13, 3, 1, 'Na, o šitie buvo Dovydo sūnūs, kurie jam gimė Hebrone: pirmagimis Amnonas iš jezreelietės Ahinoamos; antrasis Danielius iš karmelietės Abigailės;'),
  (@b13, 3, 2, 'trečiasis Abšalomas, Gešūro karaliaus Talmajo dukters Maakos sūnus; ketvirtasis Adonijas, Hagitos sūnus;'),
  (@b13, 3, 3, 'penktasis Šefatija iš Abitalės; šeštasis Itreamas iš jo žmonos Eglos.'),
  (@b13, 3, 4, 'Šitie šeši jam gimė Hebrone; ten jis karaliavo septynerius metus ir šešis mėnesius; o trisdešimt trejus metus jis karaliavo Jeruzalėje.'),
  (@b13, 3, 5, 'O šitie jam gimė Jeruzalėje: Šima, Šobabas, Natanas ir Saliamonas – keturi iš Amielio dukters Bat-Šūvos;'),
  (@b13, 3, 6, 'taip pat Ibharas, Elišama, Elifeletas,'),
  (@b13, 3, 7, 'Nogahas, Nefegas, Jafija,'),
  (@b13, 3, 8, 'Elišama, Eljada ir Elifeletas – devyni.'),
  (@b13, 3, 9, 'Tie visi buvo Dovydo sūnūs, neskaitant sugulovių sūnų; ir Tamaros, jų sesers.'),
  (@b13, 3, 10, 'O Saliamono sūnus buvo Rehoboamas, jo sūnus Abija, jo sūnus Asa, jo sūnus Jehozapatas,'),
  (@b13, 3, 11, 'jo sūnus Joramas, jo sūnus Ahazijas, jo sūnus Joašas,'),
  (@b13, 3, 12, 'jo sūnus Amacijas, jo sūnus Azarija, jo sūnus Jotamas,'),
  (@b13, 3, 13, 'jo sūnus Ahazas, jo sūnus Chezekijas, jo sūnus Manasas,'),
  (@b13, 3, 14, 'jo sūnus Amonas, jo sūnus Jozijas.'),
  (@b13, 3, 15, 'O Jozijo sūnūs: pirmagimis Johananas, antrasis Jehojakimas, trečiasis Zedekijas, ketvirtasis Šalumas.'),
  (@b13, 3, 16, 'O Jehojakimo sūnūs: jo sūnus Jechonijas, jo sūnus Zedekijas.'),
  (@b13, 3, 17, 'O Jechonijo sūnūs: Asiras, jo sūnus Salatielis,'),
  (@b13, 3, 18, 'taip pat Malkiramas, Pedaja, Šenacaras, Jekamija, Hošama ir Nedabija.'),
  (@b13, 3, 19, 'O Pedajos sūnūs: Zerubabelis ir Šimis; o Zerubabelio sūnūs: Mešulamas, Hananija, o jų sesuo Šelomita;'),
  (@b13, 3, 20, 'Hašuba, Ohelis, Berechija, Hasadija ir Jušab-Hesedas – penki.'),
  (@b13, 3, 21, 'O Hananijos sūnūs: Pelatija ir Jesaja; Refajos sūnūs, Arnano sūnūs, Abdijos sūnūs, Šechanijos sūnūs.'),
  (@b13, 3, 22, 'O Šechanijos sūnūs: Šemaja; o Šemajos sūnūs: Hatušas, Igalas, Bariachas, Nearija ir Šafatas – šeši.'),
  (@b13, 3, 23, 'O Nearijos sūnūs: Eljoenajas, Chezekijas ir Azrikamas – trys.'),
  (@b13, 3, 24, 'Eljoenajo sūnūs: Hodavijas, Eljašibas, Pelaja, Akubas, Johananas, Dalaja ir Ananis – septyni.'),
  (@b13, 4, 1, 'Judos sūnūs: Perecas, Hesronas, Karmis, Hūras ir Šobalas.'),
  (@b13, 4, 2, 'O Šobalo sūnus Reaja pagimdė Jahatą; o Jahatas pagimdė Ahumają ir Lahadą. Šitos yra coriečių šeimos.'),
  (@b13, 4, 3, 'O šitie yra iš Etamo tėvo: Jezreelis, Išma ir Idbašas; o jų sesers vardas buvo Hacelelponė;'),
  (@b13, 4, 4, 'o Gedoro tėvas Penuelis, o Hušos tėvas Ezeras. Tie yra Efratos pirmagimio Hūro, Betliejaus tėvo, sūnūs.'),
  (@b13, 4, 5, 'O Tekojos tėvas Ašhūras turėjo dvi žmonas: Helą ir Naarą.'),
  (@b13, 4, 6, 'O Naara jam pagimdė Ahuzamą, Heferą, Temenį ir Haachaštarį. Tie buvo Naaros sūnūs.'),
  (@b13, 4, 7, 'O Helos sūnūs: Ceretas, Jecoharas ir Etnanas.'),
  (@b13, 4, 8, 'O Kocas pagimdė Anubą, Cobebą ir Harumo sūnaus Aharhelio šeimas.'),
  (@b13, 4, 9, 'Ir Jabecas buvo gerbiamas labiau už savo brolius; jo motina jį praminė Jabeco vardu, sakydama: „Nes aš jį pagimdžiau su sielvartu“.'),
  (@b13, 4, 10, 'Ir Jabecas šaukėsi Izraelio Dievo, sakydamas: „O kad tu mane tikrai palaimintum ir praplėstum mano ribas, ir kad tavo ranka būtų su manimi, ir kad saugotum mane nuo pikto, kad aš nesielvartaučiau!“ Ir Dievas jam suteikė tai, ko jis prašė.'),
  (@b13, 4, 11, 'Ir pagimdė Šuhos brolis Kelubas Mechyrą, kuris buvo Eštono tėvas.'),
  (@b13, 4, 12, 'O Eštonas pagimdė Bet-Rafą, Paseachą ir Tehiną, Ir-Nahašo tėvą. Tie yra Rechos žmonės.'),
  (@b13, 4, 13, 'O Kenazo sūnūs: Otnielis ir Seraja; o Otnielio sūnūs: Hatatas.'),
  (@b13, 4, 14, 'O Meonotaja pagimdė Ofrą; o Seraja pagimdė Joabą, charašimų slėnio tėvą; nes jie buvo amatininkai.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b13, 4, 15, 'O Jefunės sūnaus Kalebo sūnūs: Iruvas, Ela ir Naamas; o Elos sūnūs: Kenazas.'),
  (@b13, 4, 16, 'O Jehalelelio sūnūs: Zifas, Zifa, Tirija ir Asarelis.'),
  (@b13, 4, 17, 'O Ezros sūnūs: Jeteras, Meredas, Eferas ir Jalonas; ir ji pagimdė Mirjamą, Šamają ir Išbachą, Eštemojos tėvą.'),
  (@b13, 4, 18, 'O jo žmona Jehudija pagimdė Gedoro tėvą Jeredą, Sochojo tėvą Heberą ir Zanoacho tėvą Jekutielį. Šitie yra sūnūs faraono dukters Bitijos, kurią paėmė Meredas.'),
  (@b13, 4, 19, 'O jo žmonos Hodijos, Nahamo sesers, sūnūs: tėvas garmito Keilos ir maakas Eštemoja.'),
  (@b13, 4, 20, 'O Šimono sūnūs: Amnonas, Rina, Ben-Hananas ir Tilonas. O Išio sūnūs: Zohetas ir Ben-Zohetas.'),
  (@b13, 4, 21, 'Judos sūnaus Šelos sūnūs: Lechos tėvas Eras, Marešos tėvas Lada ir plonos drobės dirbėjų namų šeimos iš Ašbėjos namų,'),
  (@b13, 4, 22, 'ir Jokimas, Kozebos žmonės, Joašas ir Sarafas, kurie viešpatavo Moabe, ir Jašubi-Lehemas. Ir šitie yra labai seni dalykai.'),
  (@b13, 4, 23, 'Šitie buvo puodžiai ir gyvenantys tarp augalų ir tvorų; jie ten gyveno pas karalių dėl jo darbų.'),
  (@b13, 4, 24, 'Simeono sūnūs: Nemuelis, Jaminas, Jaribas, Zerachas ir Šaulius;'),
  (@b13, 4, 25, 'jo sūnus Šalumas, jo sūnus Mibsamas, jo sūnus Mišma.'),
  (@b13, 4, 26, 'O Mišmos sūnūs: jo sūnus Hamuelis, jo sūnus Zakūras, jo sūnus Šimis.'),
  (@b13, 4, 27, 'O Šimis turėjo šešiolika sūnų ir šešias dukteris; bet jo broliai neturėjo daug vaikų, taip pat visa jų šeima nedaugėjo, kaip Judos vaikai.'),
  (@b13, 4, 28, 'Ir jie gyveno Beer-Šeboje, Moladoje, Hazar-Šuale,'),
  (@b13, 4, 29, 'Bilhoje, Eceme, Tolade,'),
  (@b13, 4, 30, 'Betuelyje, Hormoje, Ciklage,'),
  (@b13, 4, 31, 'Bet-Markabote, Hacar-Susime, Bet-Biryje ir Šaaraime. Šitie buvo jų miestai iki Dovydo karaliavimo.'),
  (@b13, 4, 32, 'O jų kaimai: Etamas, Ainas, Rimonas, Tochenas ir Ašanas – penki miestai;'),
  (@b13, 4, 33, 'ir visi jų kaimai, buvusieji aplink šituos miestus iki Baalo. Tai yra jų buveinės ir jų genealogija.'),
  (@b13, 4, 34, 'Mešobabas, Jamlechas, Amacijos sūnus Joša,'),
  (@b13, 4, 35, 'Joelis, Asielio sūnaus Serajos sūnaus Josibijos sūnus Jehuvas'),
  (@b13, 4, 36, 'ir Eljoenajas, Jaakoba, Ješohaja, Asaja, Adielis, Jesimielis, Benaja'),
  (@b13, 4, 37, 'ir Šemajos sūnaus Šimrio sūnaus Jedajos sūnaus Alono sūnaus Šifio sūnus Ziza;'),
  (@b13, 4, 38, 'šitie, paminėti jų vardais, buvo kunigaikščiai savo šeimose; ir jų tėvų namai labai augo.'),
  (@b13, 4, 39, 'Ir jie ėjo prie Gedoro įėjimo, tai yra į slėnio rytinę pusę, ieškoti ganyklų savo kaimenėms.'),
  (@b13, 4, 40, 'Ir jie rado riebių ir gerų ganyklų, o šalis buvo plati, rami ir taiki; nes ten nuo seno gyveno tie iš Chamo.'),
  (@b13, 4, 41, 'Ir šitie, surašyti vardais, atėjo Judos karaliaus Chezekijo dienomis ir sumušė jų palapines ir buveines, kurias ten rado, ir juos visiškai išnaikino iki šios dienos, ir apsigyveno jų vietoje; nes ten buvo ganyklų jų kaimenėms.'),
  (@b13, 4, 42, 'Ir kai kurie iš jų, būtent iš Simeono sūnų, penki šimtai vyrų, nuėjo į Seyro kalną, turėdami sau vadus Išio sūnus: Pelatiją, Neariją, Refają ir Uzielį.'),
  (@b13, 4, 43, 'Ir jie sumušė likusius amalekiečius, kurie buvo pabėgę, ir ten apsigyveno iki šios dienos.'),
  (@b13, 5, 1, 'Na, o Izraelio pirmagimio Rubeno sūnūs (nes jis buvo pirmagimis; bet kadangi jis sutepė savo tėvo patalą, jo pirmagimio teisė buvo atiduota Izraelio sūnaus Juozapo sūnums; o genealogija neskaitoma pagal pirmagimio teisę.'),
  (@b13, 5, 2, 'Nes Juda įsigalėjo virš savo brolių, ir iš jo kilo vyriausias valdovas; bet pirmagimio teisė buvo Juozapo);'),
  (@b13, 5, 3, 'sūnūs, sakau, Izraelio pirmagimio Rubeno: Hanochas ir Paluvas, Hesronas ir Karmis.'),
  (@b13, 5, 4, 'Joelio sūnūs: jo sūnus Šemaja, jo sūnus Gogas, jo sūnus Šimis,'),
  (@b13, 5, 5, 'jo sūnus Micha, jo sūnus Reaja, jo sūnus Baalas,'),
  (@b13, 5, 6, 'jo sūnus Beera, kurį Asirijos karalius Tilgat-Pilneseras išvedė nelaisvėn; jis buvo rubenų kunigaikštis.'),
  (@b13, 5, 7, 'O jo broliai pagal jų šeimas, skaitant jų giminės genealogiją buvo vyriausieji: Jejelis ir Zacharijas,'),
  (@b13, 5, 8, 'ir Joelio sūnaus Šemos sūnaus Azazo sūnus Bela, kuris gyveno Aroeryje iki Nebojo bei Baal-Meono;'),
  (@b13, 5, 9, 'ir į rytus jis gyveno iki dykumos įėjimo nuo Eufrato upės; nes jų galvijų buvo padaugėję Gileado šalyje.'),
  (@b13, 5, 10, 'Ir Sauliaus dienomis jie kariavo su hagarais, kurie krito nuo jų rankos; ir jie gyveno jų palapinėse, visoje rytinėje Gileado šalyje.'),
  (@b13, 5, 11, 'O Gado vaikai gyveno priešais juos, Bašano šalyje iki Salchos:'),
  (@b13, 5, 12, 'viršiausiasis Joelis, po jo Šafamas, Janajas ir Šafatas Bašane.'),
  (@b13, 5, 13, 'O jų tėvų namų broliai: Mykolas, Mešulamas, Šeba, Jorajas, Jakanas, Zija ir Heberas – septyni.'),
  (@b13, 5, 14, 'Šitie yra Būzo sūnaus Jahdajo sūnaus Ješišajo sūnaus Mykolo sūnaus Gileado sūnaus Jaroacho sūnaus Hūrio sūnaus Abihailo vaikai:'),
  (@b13, 5, 15, 'Gūnio sūnaus Abdielio sūnus Ahis, jų tėvų namų vyriausiasis.'),
  (@b13, 5, 16, 'Ir jie gyveno Gileade, Bašane ir jo miestuose bei visuose Šarono priemiesčiuose iki jų ribų.'),
  (@b13, 5, 17, 'Visi šitie buvo suskaičiuoti genealogijomis Judos karaliaus Jotamo dienomis ir Izraelio karaliaus Jeroboamo dienomis.'),
  (@b13, 5, 18, 'Rubeno sūnūs, gadai ir pusė Manaso genties, iš narsuolių, vyrų, pajėgių nešioti skydą bei kalaviją, šauti iš lanko ir įgudusių kare buvo keturiasdešimt keturi tūkstančiai septyni šimtai šešiasdešimt išeinančių į karą.'),
  (@b13, 5, 19, 'Ir jie kariavo su hagarais, Jetūru, Nefišu ir Nodabu.'),
  (@b13, 5, 20, 'Ir jiems buvo pagelbėta prieš juos, ir hagarai bei visi buvusieji su jais buvo atiduoti į jų rankas; nes mūšyje jie šaukėsi Dievo, ir jis buvo jų išmelstas; nes jie pasitikėjo juo.'),
  (@b13, 5, 21, 'Ir jie paėmė jų galvijus, penkiasdešimt tūkstančių jų kupranugarių, du šimtus penkiasdešimt tūkstančių avių, du tūkstančius asilų ir šimtą tūkstančių žmonių.'),
  (@b13, 5, 22, 'Nes krito daug nužudytų, kadangi karas buvo Dievo. Ir jie apsigyveno jų vietoje iki nelaisvės.'),
  (@b13, 5, 23, 'O pusės Manaso genties vaikai gyveno toje šalyje: jie daugėjo nuo Bašano iki Baal-Hermono, Seniro ir iki Hermono kalno.'),
  (@b13, 5, 24, 'O šitie buvo jų tėvų namų galvos: Eferas, Išis, Elielis, Azrielis, Jeremijas, Hodavija ir Jachdielis – galingi narsuoliai, garsūs vyrai, jų tėvų namų galvos.'),
  (@b13, 5, 25, 'Ir jie nusižengė prieš savo tėvų Dievą ir paleistuvaudami nuėjo paskui dievus tos šalies tautų, kurias Dievas išnaikino jų akivaizdoje.'),
  (@b13, 5, 26, 'Ir Izraelio Dievas sužadino Asirijos karaliaus Pulo dvasią, ir Asirijos karaliaus Tilgat-Pilnesero dvasią, ir jis juos išvedė, būtent rubenus, gadus ir pusę Manaso genties, ir juos nuvedė į Halachą, Haborą, Harą ir prie Gozano upės, iki šios dienos.'),
  (@b13, 6, 1, 'Levio sūnūs: Geršonas, Kehatas ir Meraris.'),
  (@b13, 6, 2, 'O Kehato sūnūs: Amramas, Iccharas, Hebronas ir Uzielis.'),
  (@b13, 6, 3, 'O Amramo vaikai: Aaronas, Mozė ir Mirjama. Taip pat Aarono sūnūs: Nadabas ir Abihuvas, Eleazaras ir Itamaras.'),
  (@b13, 6, 4, 'Eleazaras pagimdė Finehasą, Finehasas pagimdė Abišūvą,'),
  (@b13, 6, 5, 'o Abišūva pagimdė Bukį, o Bukis pagimdė Uzį,'),
  (@b13, 6, 6, 'o Uzis pagimdė Zerachiją, o Zerachija pagimdė Merajotą,'),
  (@b13, 6, 7, 'Merajotas pagimdė Amariją, o Amarija pagimdė Ahitubą,'),
  (@b13, 6, 8, 'o Ahitubas pagimdė Cadoką, o Cadokas pagimdė Ahimaacą,'),
  (@b13, 6, 9, 'o Ahimaacas pagimdė Azariją, o Azarija pagimdė Johananą,'),
  (@b13, 6, 10, 'o Johananas pagimdė Azariją (jis yra tas, kuris ėjo kunigo pareigas šventykloje, kurią Saliamonas pastatė Jeruzalėje),'),
  (@b13, 6, 11, 'o Azarija pagimdė Amariją, o Amarija pagimdė Ahitubą,'),
  (@b13, 6, 12, 'o Ahitubas pagimdė Cadoką, o Cadokas pagimdė Šalumą,'),
  (@b13, 6, 13, 'o Šalumas pagimdė Hilkiją, o Hilkija pagimdė Azariją,'),
  (@b13, 6, 14, 'o Azarija pagimdė Serają, o Seraja pagimdė Jehocadaką,'),
  (@b13, 6, 15, 'o Jehocadakas išėjo į nelaisvę, kai VIEŠPATS išvedė Judą ir Jeruzalę Nebukadnecaro ranka.'),
  (@b13, 6, 16, 'Levio sūnūs: Geršomas, Kehatas ir Meraris.'),
  (@b13, 6, 17, 'O šitie yra Geršomo sūnų vardai: Libnis ir Šimis.'),
  (@b13, 6, 18, 'O Kehato sūnūs: Amramas, Iccharas, Hebronas ir Uzielis.'),
  (@b13, 6, 19, 'Merario sūnūs: Machlis ir Mušis. Šitos yra levitų šeimos pagal jų tėvus.'),
  (@b13, 6, 20, 'Iš Geršomo: jo sūnus Libnis, jo sūnus Jahatas, jo sūnus Zima,'),
  (@b13, 6, 21, 'jo sūnus Joachas, jo sūnus Idojas, jo sūnus Zerachas, jo sūnus Jeatrajas.'),
  (@b13, 6, 22, 'Kehato sūnūs: jo sūnus Aminadabas, jo sūnus Korachas, jo sūnus Asiras,'),
  (@b13, 6, 23, 'jo sūnus Elkana, jo sūnus Ebijasafas, jo sūnus Asiras,'),
  (@b13, 6, 24, 'jo sūnus Tahatas, jo sūnus Ūrielis, jo sūnus Uzija ir jo sūnus Šaulius.'),
  (@b13, 6, 25, 'O Elkanos sūnūs: Amasajas ir Ahimotas.'),
  (@b13, 6, 26, 'O Elkana, Elkanos sūnūs: jo sūnus Cofajas, jo sūnus Nahatas,'),
  (@b13, 6, 27, 'jo sūnus Eliabas, jo sūnus Jerohamas, jo sūnus Elkana.'),
  (@b13, 6, 28, 'O Samuelio sūnūs: pirmagimis Vašnis ir Abija.'),
  (@b13, 6, 29, 'Merario sūnūs: Machlis, jo sūnus Libnis, jo sūnus Šimis, jo sūnus Uza,'),
  (@b13, 6, 30, 'jo sūnus Šima, jo sūnus Hagija, jo sūnus Asaja.'),
  (@b13, 6, 31, 'O šitie yra tie, kuriuos Dovydas pastatė vadovauti giesmių tarnystei VIEŠPATIES namuose po to, kai skrynia ilsėjosi.'),
  (@b13, 6, 32, 'Ir jie tarnavo giedodami prieš susirinkimo padangtės gyvenamą vietą, kol Saliamonas pastatė VIEŠPATIES namus Jeruzalėje; ir tada jie tarnavo savo tarnyboje pagal savo tvarką.'),
  (@b13, 6, 33, 'O šitie yra tie, kurie tarnavo su savo vaikais. Iš Kehato sūnų: giesmininkas Hemanas, sūnus Joelio, sūnaus Šemuelio,'),
  (@b13, 6, 34, 'sūnaus Elkanos, sūnaus Jerohamo, sūnaus Elielio, sūnaus Toacho,'),
  (@b13, 6, 35, 'sūnaus Cūfo, sūnaus Elkanos, sūnaus Mahato, sūnaus Amasajo,'),
  (@b13, 6, 36, 'sūnaus Elkanos, sūnaus Joelio, sūnaus Azarijos, sūnaus Sofonijo,'),
  (@b13, 6, 37, 'sūnaus Tahato, sūnaus Asiro, sūnaus Ebjasafo, sūnaus Koracho,'),
  (@b13, 6, 38, 'sūnaus Iccharo, sūnaus Kehato, sūnaus Levio, sūnaus Izraelio.'),
  (@b13, 6, 39, 'Ir jo brolis Asafas, kuris stovėjo jo dešinėje, tai yra Asafas, sūnus Berechijo, sūnaus Šimos,'),
  (@b13, 6, 40, 'sūnaus Mykolo, sūnaus Baasėjos, sūnaus Malkijos,'),
  (@b13, 6, 41, 'sūnaus Etnio, sūnaus Zeracho, sūnaus Adajos,'),
  (@b13, 6, 42, 'sūnaus Etano, sūnaus Zimos, sūnaus Šimio,'),
  (@b13, 6, 43, 'sūnaus Jahato, sūnaus Geršomo, sūnaus Levio.'),
  (@b13, 6, 44, 'O jų broliai Merario sūnūs stovėjo kairėje: Etanas, sūnus Kišio, sūnaus Abdžio, sūnaus Malucho,'),
  (@b13, 6, 45, 'sūnaus Hašabijos, sūnaus Amacijos, sūnaus Hilkijos,'),
  (@b13, 6, 46, 'sūnaus Amcio, sūnaus Banio, sūnaus Šemero,'),
  (@b13, 6, 47, 'sūnaus Machlio, sūnaus Mušio, sūnaus Merario, sūnaus Levio.'),
  (@b13, 6, 48, 'Taip pat jų broliai levitai buvo paskirti visokiai Dievo namų padangtės tarnybai.'),
  (@b13, 6, 49, 'Bet Aaronas ir jo sūnūs atnašaudavo ant deginamosios atnašos aukuro ir ant smilkalų aukuro ir buvo paskirti visiems švenčiausiosios vietos darbams ir kad atliktų sutaikinimą už Izraelį pagal visa tai, ką buvo įsakęs Dievo tarnas Mozė.'),
  (@b13, 6, 50, 'O šitie yra Aarono sūnūs: jo sūnus Eleazaras, jo sūnus Finehasas, jo sūnus Abišūva,'),
  (@b13, 6, 51, 'jo sūnus Bukis, jo sūnus Uzis, jo sūnus Zerachija,'),
  (@b13, 6, 52, 'jo sūnus Merajotas, jo sūnus Amarija, jo sūnus Ahitubas,'),
  (@b13, 6, 53, 'jo sūnus Cadokas, jo sūnus Ahimaacas.'),
  (@b13, 6, 54, 'Na, o šitos yra jų gyvenamos vietos, pagal jų tvirtoves jų ribose, Aarono sūnų, kehatų šeimų; nes jų buvo burtas.'),
  (@b13, 6, 55, 'Ir jie davė jiems Judos šalyje Hebroną ir jo priemiesčius aplink jį.'),
  (@b13, 6, 56, 'Bet miesto laukus ir jo kaimus jie davė Jefunės sūnui Kalebui.'),
  (@b13, 6, 57, 'O Aarono sūnums davė Judos miestus – prieglobsčio miestą Hebroną, Libną su jos priemiesčiais, Jatyrą, Eštemoją su jų priemiesčiais,'),
  (@b13, 6, 58, 'Hileną su jo priemiesčiais, Debyrą su jo priemiesčiais,'),
  (@b13, 6, 59, 'Ašaną su jo priemiesčiais, Bet-Šemešą su jo priemiesčiais;'),
  (@b13, 6, 60, 'o iš Benjamino genties: Gebą su jos priemiesčiais, Alemetą su jo priemiesčiais ir Anatotą su jo priemiesčiais. Iš viso jų miestų pagal jų šeimas buvo trylika miestų.'),
  (@b13, 6, 61, 'O Kehato sūnums, išlikusiems iš tos genties šeimos, buvo duoti miestai iš pusės genties – iš pusės Manaso genties, burtu dešimt miestų.'),
  (@b13, 6, 62, 'O Geršomo sūnums pagal jų šeimas davė iš Isacharo genties, iš Ašero genties, iš Naftalio genties ir iš Manaso genties trylika miestų Bašane.'),
  (@b13, 6, 63, 'Merario sūnums pagal jų šeimas burtu buvo duota iš Rubeno genties, iš Gado genties ir iš Zebulono genties dvylika miestų.'),
  (@b13, 6, 64, 'Izraelio vaikai davė levitams šituos miestus su jų priemiesčiais.'),
  (@b13, 6, 65, 'Jie davė burtu iš Judos vaikų genties, iš Simeono vaikų genties ir iš Benjamino vaikų genties šituos miestus, kurie yra praminti jų vardais.'),
  (@b13, 6, 66, 'O likusieji iš Kehato sūnų šeimų turėjo savo ribų miestus iš Efraimo genties.'),
  (@b13, 6, 67, 'Jie davė jiems iš prieglobsčio miestų Šechemą Efraimo kalne su jo priemiesčiais; jie taip pat davė Gezerą su jo priemiesčiais,'),
  (@b13, 6, 68, 'Jokmeamą su jo priemiesčiais ir Bet-Horoną su jo priemiesčiais,'),
  (@b13, 6, 69, 'Ajaloną su jo priemiesčiais ir Gat-Rimoną su jo priemiesčiais;'),
  (@b13, 6, 70, 'o iš pusės Manaso genties: Anerą su jo priemiesčiais ir Bileamą su jo priemiesčiais likusiųjų Kehato sūnų šeimai.'),
  (@b13, 6, 71, 'Geršomo sūnums iš pusės Manaso genties šeimos buvo duoti: Bašane Golanas su jo priemiesčiais ir Aštarotas su jo priemiesčiais;'),
  (@b13, 6, 72, 'o iš Isacharo genties: Kedešas su jo priemiesčiais, Daberatas su jo priemiesčiais,'),
  (@b13, 6, 73, 'Ramotas su jo priemiesčiais ir Anemas su jo priemiesčiais;'),
  (@b13, 6, 74, 'o iš Ašero genties: Mišalas su jo priemiesčiais, Abdonas su jo priemiesčiais,'),
  (@b13, 6, 75, 'Hukokas su jo priemiesčiais ir Rehobas su jo priemiesčiais;'),
  (@b13, 6, 76, 'o iš Naftalio genties: Kedešas Galilėjoje su jo priemiesčiais, Hamonas su jo priemiesčiais ir Kirjataimas su jo priemiesčiais.'),
  (@b13, 6, 77, 'Likusiems Merario vaikams iš Zebulono genties buvo duoti: Rimonas su jo priemiesčiais ir Taboras su jo priemiesčiais;'),
  (@b13, 6, 78, 'o anapus Jordano prie Jericho, rytinėje Jordano pusėje, iš Rubeno genties jiems buvo duoti: Beceras dykumoje su jo priemiesčiais, Jahca su jos priemiesčiais,'),
  (@b13, 6, 79, 'taip pat Kedemotas su jo priemiesčiais ir Mefaatas su jo priemiesčiais;'),
  (@b13, 6, 80, 'o iš Gado genties: Ramotas Gileade su jo priemiesčiais, Machanaimas su jo priemiesčiais,'),
  (@b13, 6, 81, 'Hešbonas su jo priemiesčiais ir Jazeras su jo priemiesčiais.'),
  (@b13, 7, 1, 'Na, o Isacharo sūnūs buvo: Tola, Pūva, Jašubas ir Šimronas – keturi.'),
  (@b13, 7, 2, 'O Tolos sūnūs: Uzis, Refaja, Jerielis, Jachmajas, Ibsamas ir Šemuelis – galvos savo tėvų namų, tai yra Tolos; jie buvo galingi narsuoliai savo giminėje; Dovydo dienomis jų skaičius buvo dvidešimt du tūkstančiai šeši šimtai.'),
  (@b13, 7, 3, 'O Uzio sūnūs: Izrachija; o Izrachijos sūnūs: Mykolas, Abdija, Joelis ir Išija – penki; jie visi vyriausieji.'),
  (@b13, 7, 4, 'O su jais, pagal jų genealogiją, pagal jų tėvų namus, buvo kareivių pulkai karui: trisdešimt šeši tūkstančiai vyrų; nes jie turėjo daug žmonų ir sūnų.'),
  (@b13, 7, 5, 'O jų brolių visose Isacharo šeimose, galingų narsuolių, suskaičiuotų pagal jų genealogijas – aštuoniasdešimt septyni tūkstančiai.'),
  (@b13, 7, 6, 'Benjamino sūnūs: Bela, Becheras ir Jediaelis – trys.'),
  (@b13, 7, 7, 'O Belos sūnūs: Ecbonas, Uzis, Uzielis, Jerimotas ir Iris – penki, jų tėvų namų galvos, narsūs galiūnai; ir buvo suskaičiuota pagal jų genealogijas dvidešimt du tūkstančiai trisdešimt keturi.'),
  (@b13, 7, 8, 'O Bechero sūnūs: Cemira, Joašas, Eliezeras, Eljoenajas, Omris, Jeremotas, Abija, Anatotas ir Alemetas. Tie visi yra Bechero sūnūs.'),
  (@b13, 7, 9, 'O jų skaičius pagal jų genealogiją jų giminėmis, buvo dvidešimt tūkstančių du šimtai jų tėvų namų galvų, galingų narsuolių.'),
  (@b13, 7, 10, 'Taip pat Jediaelio sūnūs: Bilhanas; o Bilhano sūnūs: Jeušas, Benjaminas, Ehudas, Kenaana, Zetanas, Taršišas ir Ahišaharas.'),
  (@b13, 7, 11, 'Tie visi buvo Jediaelio sūnūs, pagal jų tėvų galvas, galingi narsuoliai, septyniolika tūkstančių du šimtai kareivių, tinkamų išeiti kariauti į mūšį.'),
  (@b13, 7, 12, 'Taip pat Šupimas ir Hupimas, Iro vaikai ir Hušimas – Ahero sūnūs.'),
  (@b13, 7, 13, 'Naftalio sūnūs: Jahacielis, Gūnis, Jeceras ir Šalumas, Bilhos sūnūs.'),
  (@b13, 7, 14, 'Manaso sūnūs: Ašrielis, kurį ji pagimdė (jo sugulovė aramietė pagimdė Machyrą, Gileado tėvą;'),
  (@b13, 7, 15, 'o Machyras paėmė į žmonas Hupimo ir Šupimo seserį, kurios vardas buvo Maaka), o antrojo vardas buvo Celofchadas; o Celofchadas turėjo dukteris.'),
  (@b13, 7, 16, 'O Machyro žmona Maaka pagimdė sūnų ir jį praminė Perešo vardu; o jo brolio vardas buvo Šerešas; o jo sūnūs buvo Ulamas ir Rekemas.'),
  (@b13, 7, 17, 'O Ulamo sūnūs: Bedanas. Tie buvo Manaso sūnaus Machyro sūnaus Gileado sūnūs.'),
  (@b13, 7, 18, 'O jo sesuo Hamoleketa pagimdė Išhodą, Abiezerą ir Machlą.'),
  (@b13, 7, 19, 'O Šemidos sūnūs buvo Achjanas, Šechemas, Likchis ir Aniamas.'),
  (@b13, 7, 20, 'O Efraimo sūnūs: Šutelachas, jo sūnus Beredas, jo sūnus Tahatas, jo sūnus Elada, jo sūnus Tahatas,'),
  (@b13, 7, 21, 'jo sūnus Zabadas, jo sūnus Šutelachas, Ezeras ir Eleadas, kuriuos nužudė Gato vyrai, gimę toje šalyje, nes jie atėjo žemyn jų galvijų nuvaryti.'),
  (@b13, 7, 22, 'Ir jų tėvas Efraimas gedėjo daug dienų, o jo broliai atėjo jį paguosti.'),
  (@b13, 7, 23, 'O jam įėjus pas savo žmoną, ji pastojo ir pagimdė sūnų, ir jis praminė jį vardu Berija, nes vyko nelaimės jo namuose'),
  (@b13, 7, 24, '(o jo duktė buvo Šeera, kuri pastatė žemutinįjį bei aukštutinįjį Bet-Horoną ir Uzen-Šeerą).'),
  (@b13, 7, 25, 'O Refachas buvo jo sūnus, taip pat Rešefas, jo sūnus Telachas, jo sūnus Tahanas,'),
  (@b13, 7, 26, 'jo sūnus Ladanas, jo sūnus Amihudas, jo sūnus Elišama,'),
  (@b13, 7, 27, 'jo sūnus Nonas, jo sūnus Jozuė.'),
  (@b13, 7, 28, 'O jų nuosavybė ir buveinės buvo Bet-Elis ir jo miesteliai, o rytuose Naaranas, o vakaruose Gezeras su jo miesteliais; taip pat Šechemas ir jo miesteliai iki Gazos su jos miesteliais;'),
  (@b13, 7, 29, 'o prie Manaso vaikų ribų buvo Bet-Šeanas su jo miesteliais, Taanachas su jo miesteliais, Megidas su jo miesteliais, Doras su jo miesteliais. Šituose gyveno Izraelio sūnaus Juozapo vaikai.'),
  (@b13, 7, 30, 'Ašero sūnūs: Imna, Išva, Išvis, Berija ir jų sesuo Seracha.'),
  (@b13, 7, 31, 'O Berijos sūnūs: Heberas ir Malkielis, kuris yra Birzajo tėvas.'),
  (@b13, 7, 32, 'O Heberas pagimdė Jafletą, Šomerą, Hotamą ir jų seserį Šūvą.'),
  (@b13, 7, 33, 'O Jafleto sūnūs: Pasachas, Bimhalas ir Ašvatas. Šitie yra Jafleto vaikai.'),
  (@b13, 7, 34, 'O Šamero sūnūs: Ahis, Rohga, Jehuba ir Aramas.'),
  (@b13, 7, 35, 'O jo brolio Helemo sūnūs: Cofachas, Imna, Šelešas ir Amalas.'),
  (@b13, 7, 36, 'Cofacho sūnūs: Suachas, Harneferas, Šualas, Beris, Imra,'),
  (@b13, 7, 37, 'Beceras, Hodas, Šama, Šilša, Itranas ir Beera.'),
  (@b13, 7, 38, 'O Jetero sūnūs: Jefunė, Pispa ir Ara.'),
  (@b13, 7, 39, 'O Ulos sūnūs: Arahas, Hanielis ir Ricija.'),
  (@b13, 7, 40, 'Šitie visi buvo Ašero vaikai, jų tėvų namų galvos, rinktiniai, narsūs galiūnai, kunigaikščių vyriausieji. O skaičius visoje genealogijoje tų, kurie buvo tinkami kariauti mūšyje, buvo dvidešimt šeši tūkstančiai vyrų.'),
  (@b13, 8, 1, 'Na, o Benjaminas pagimdė savo pirmagimį Belą, antrąjį Ašbelį, trečiąjį Ahrachą,'),
  (@b13, 8, 2, 'ketvirtąjį Nohą ir penktąjį Rafą.'),
  (@b13, 8, 3, 'O Belos sūnūs buvo: Adaras, Gera, Abihudas,'),
  (@b13, 8, 4, 'Abišūva, Naamanas, Ahoachas,'),
  (@b13, 8, 5, 'Gera, Šefufanas ir Huramas.'),
  (@b13, 8, 6, 'O šitie yra Ehudo sūnūs: šitos yra Gebos gyventojų tėvų galvos; ir juos iškėlė į Manahatą;'),
  (@b13, 8, 7, 'Naamaną, Ahiją ir Gerą, jis juos iškėlė ir pagimdė Uzą ir Ahihudą.'),
  (@b13, 8, 8, 'O Šacharaimas pagimdė vaikų Moabo šalyje po to, kai jis jas paleido: Hušima ir Baara buvo jo žmonos.'),
  (@b13, 8, 9, 'O iš savo žmonos Hodešos jis pagimdė Jobabą, Cibiją, Mešą, Malkamą,'),
  (@b13, 8, 10, 'Jeucą, Šachiją ir Mirmą. Šitie buvo jo sūnūs, tėvų galvos.'),
  (@b13, 8, 11, 'O iš Hušimos jis pagimdė Abitubą ir Elpaalį.'),
  (@b13, 8, 12, 'Elpaalio sūnūs: Eberas, Mišamas ir Šamedas, kuris pastatė Onoją ir Lodą su jo miesteliais;'),
  (@b13, 8, 13, 'taip pat Berija ir Šema, kurie buvo Ajalono gyventojų tėvų galvos, kurie išvarė Gato gyventojus;'),
  (@b13, 8, 14, 'o Ahjojas, Šašakas, Jeremotas,'),
  (@b13, 8, 15, 'Zebadija, Aradas, Ederas,'),
  (@b13, 8, 16, 'Mykolas, Išpa ir Joha – Berijos sūnūs;'),
  (@b13, 8, 17, 'o Zebadija, Mešulamas, Chizkis, Heberas,'),
  (@b13, 8, 18, 'taip pat Išmerajas, Izlija ir Jobabas – Elpaalio sūnūs;'),
  (@b13, 8, 19, 'o Jakimas, Zichris, Zabdis,'),
  (@b13, 8, 20, 'Elienajas, Ciletajas, Elielis,'),
  (@b13, 8, 21, 'Adaja, Beraja ir Šimratas – Šimio sūnūs;'),
  (@b13, 8, 22, 'o Išpanas, Heberas, Elielis,'),
  (@b13, 8, 23, 'Abdonas, Zichris, Hananas,'),
  (@b13, 8, 24, 'Hananija, Elamas, Antotija,');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b13, 8, 25, 'Ifdeja ir Penuelis – Šašako sūnūs;'),
  (@b13, 8, 26, 'o Šamšerajas, Šeharija, Atalija,'),
  (@b13, 8, 27, 'Jaarešija, Elija ir Zichris – Jerohamo sūnūs.'),
  (@b13, 8, 28, 'Šitie buvo tėvų galvos, pagal jų genealogiją, vyriausieji. Šitie gyveno Jeruzalėje.'),
  (@b13, 8, 29, 'O Gibeone gyveno Gibeono tėvas; kurio žmonos vardas buvo Maaka;'),
  (@b13, 8, 30, 'ir jo pirmagimis sūnus Abdonas, Cūras, Kišas, Baalas, Nadabas,'),
  (@b13, 8, 31, 'Gedoras, Achjojas, Zecheris.'),
  (@b13, 8, 32, 'O Miklotas pagimdė Šimą. Tie irgi gyveno su savo broliais Jeruzalėje, priešais juos.'),
  (@b13, 8, 33, 'O Neras pagimdė Kišą, o Kišas pagimdė Saulių, o Saulius pagimdė Jonataną, Malki-Šūvą, Abinadabą ir Eš-Baalą.'),
  (@b13, 8, 34, 'O Jonatano sūnus buvo Merib-Baalas; o Merib-Baalas pagimdė Michą.'),
  (@b13, 8, 35, 'O Michos sūnūs: Pitonas, Melechas, Tarėja ir Ahazas.'),
  (@b13, 8, 36, 'O Ahazas pagimdė Jehoadą; o Jehoada pagimdė Alemetą, Azmavetą ir Zimrį; o Zimris pagimdė Mocą,'),
  (@b13, 8, 37, 'o Moca pagimdė Binėją: jo sūnus buvo Rafa, jo sūnus Eleasa, jo sūnus Acelis;'),
  (@b13, 8, 38, 'o Acelis turėjo šešis sūnus, kurių vardai buvo šie: Azrikamas, Bochruva, Išmaelis, Šearija, Abdijas ir Hananas. Šitie visi buvo Acelio sūnūs.'),
  (@b13, 8, 39, 'O jo brolio Ešeko sūnūs: jo pirmagimis Ulamas, antrasis Jeušas ir trečiasis Elifeletas.'),
  (@b13, 8, 40, 'O Ulamo sūnūs buvo galingi narsuoliai, lankininkai, ir turėjo daug sūnų ir sūnų sūnų – šimtą penkiasdešimt. Visi šitie yra iš Benjamino sūnų.'),
  (@b13, 9, 1, 'Taip visas Izraelis buvo suskaičiuotas pagal genealogijas; ir štai jie surašyti knygoje karalių Izraelio ir Judos, kurie dėl savo nusižengimo buvo išvesti į Babiloną.'),
  (@b13, 9, 2, 'Na, o pirmieji gyventojai, kurie gyveno savo nuosavybėje savo miestuose, buvo izraelitai, kunigai, levitai ir netinimai.'),
  (@b13, 9, 3, 'O Jeruzalėje gyveno iš Judos vaikų, iš Benjamino vaikų, iš Efraimo ir Manaso vaikų:'),
  (@b13, 9, 4, 'Utajas, sūnus Amihudo, sūnaus Omrio, sūnaus Imrio, sūnaus Banio, iš Judos sūnaus Pereco vaikų.'),
  (@b13, 9, 5, 'O iš šilojiečių: pirmagimis Asaja ir jo sūnūs.'),
  (@b13, 9, 6, 'O iš Zeracho sūnų: Jeuelis ir jų broliai – šeši šimtai devyniasdešimt.'),
  (@b13, 9, 7, 'O iš Benjamino sūnų: Saluvas, sūnus Mešulamo, sūnus Hodavijos, sūnus Hasenuvos,'),
  (@b13, 9, 8, 'ir Jerohamo sūnus Ibnėja, ir Michrio sūnaus Uzio sūnus Ela, ir Mešulamas, sūnus Šefatijos, sūnus Reuelio, sūnus Ibnijos;'),
  (@b13, 9, 9, 'ir jų brolių, pagal jų genealogiją – devyni šimtai penkiasdešimt šeši. Šitie visi vyrai buvo tėvų vyriausieji jų tėvų namuose.'),
  (@b13, 9, 10, 'Ir iš kunigų: Jedaja, Jehojaribas, Jachinas'),
  (@b13, 9, 11, 'ir Azarija, sūnus Hilkijos, sūnaus Mešulamo, sūnaus Cadoko, sūnaus Merajoto, sūnaus Ahitubo, Dievo namų valdovas;'),
  (@b13, 9, 12, 'ir Adaja, sūnus Jerohamo, sūnaus Pašhūro, sūnaus Malkijos, ir Masajas, sūnus Adielio, sūnaus Jachzeros, sūnaus Mešulamo, sūnaus Mešilemito, sūnaus Imero;'),
  (@b13, 9, 13, 'ir jų broliai, jų tėvų namų galvos, tūkstantis septyni šimtai šešiasdešimt; labai pajėgūs vyrai Dievo namų tarnystės darbui.'),
  (@b13, 9, 14, 'O iš levitų: Šemaja, sūnus Hašubo, sūnaus Azrikamo, sūnaus Hašabijos, iš Merario sūnų;'),
  (@b13, 9, 15, 'ir Bakbakaras, Herešas ir Galalas, ir Matanija, sūnus Michos, sūnaus Zichrio, sūnaus Asafo;'),
  (@b13, 9, 16, 'ir Abdijas, sūnus Šemajos, sūnaus Galalo, sūnaus Jedutūno, ir Elkanos sūnaus Asos sūnus Berechija, kuris gyveno netofiečių kaimuose.'),
  (@b13, 9, 17, 'O durininkai buvo Šalumas, Akubas, Talmonas, Ahimanas ir jų broliai; Šalumas buvo viršininkas;'),
  (@b13, 9, 18, 'kuris iki šiol tarnavo karaliaus vartuose, rytinėje pusėje; jie buvo durininkai Levio vaikų būriuose.'),
  (@b13, 9, 19, 'O Šalumas, sūnus Korės, sūnaus Ebjasafo, sūnaus Koracho, ir jo broliai iš jo tėvo namų, korachai, padangtės vartų sargai, prižiūrėjo tarnystės darbą; o jų tėvai, prižiūrintys VIEŠPATIES kariuomenę, buvo įėjimo sargai.'),
  (@b13, 9, 20, 'O Eleazaro sūnus Finehasas praeityje buvo jų valdovas, o VIEŠPATS buvo su juo.'),
  (@b13, 9, 21, 'O Mešelemijos sūnus Zacharija buvo susirinkimo padangtės durų durininkas.'),
  (@b13, 9, 22, 'Tų visų, išrinktų būti sargais prie vartų, buvo du šimtai dvylika. Tie buvo suskaičiuoti pagal jų genealogiją savo kaimuose; juos Dovydas ir regėtojas Samuelis paskyrė į jų nustatytą tarnystę.'),
  (@b13, 9, 23, 'Taigi jie ir jų vaikai prižiūrėjo VIEŠPATIES namų vartus, būtent padangtės namų, sargybomis.'),
  (@b13, 9, 24, 'Durininkai buvo keturiose pusėse: į rytus, į vakarus, į šiaurę ir į pietus.'),
  (@b13, 9, 25, 'O jų broliai, esantys savo kaimuose, turėdavo laikas nuo laiko ateiti su jais po septynių dienų.'),
  (@b13, 9, 26, 'Nes šitie levitai, keturi vyriausieji durininkai, buvo jų nustatytoje tarnystėje ir prižiūrėjo Dievo namų kambarius ir iždus.'),
  (@b13, 9, 27, 'Ir jie nakvodavo aplink Dievo namus, nes jie turėjo tą pareigą, ir jiems priklausė kas rytą juos atidaryti.'),
  (@b13, 9, 28, 'Kai kurie iš jų buvo atsakingi už tarnavimo indus, kad jie juos suskaičiuotus įneštų ir suskaičiuotus išneštų.'),
  (@b13, 9, 29, 'Taip pat kai kurie iš jų buvo paskirti prižiūrėti indus, visus šventovės įrankius, smulkius miltus, vyną, aliejų, smilkalus ir kvepalus.'),
  (@b13, 9, 30, 'Kai kurie iš kunigų sūnų paruošdavo kvepalų tepalą.'),
  (@b13, 9, 31, 'Matitija, vienas iš levitų, kuris buvo koracho Šalumo pirmagimis, turėjo nustatytą tarnystę – prižiūrėti, kas buvo ruošiama keptuvėse.'),
  (@b13, 9, 32, 'O kiti iš jų brolių, iš Kehato sūnų, prižiūrėjo parodomąją duoną, kad ją paruoštų kiekvieną sabatą.'),
  (@b13, 9, 33, 'Šitie yra giesmininkai, levitų tėvų vyriausieji, kurie, likę kambariuose, buvo laisvi; nes dieną ir naktį jie buvo užsiėmę tame darbe.'),
  (@b13, 9, 34, 'Šitie levitų vyriausieji tėvai buvo vyriausieji savo giminėje; šitie gyveno Jeruzalėje.'),
  (@b13, 9, 35, 'O Gibeone gyveno Gibeono tėvas Jejelis, kurio žmonos vardas buvo Maaka;'),
  (@b13, 9, 36, 'ir jo pirmagimis sūnus Abdonas, paskui Cūras, Kišas, Baalas, Neras, Nadabas,'),
  (@b13, 9, 37, 'Gedoras, Achjojas, Zacharija ir Miklotas.'),
  (@b13, 9, 38, 'O Miklotas pagimdė Šimamą. Šitie irgi gyveno su savo broliais Jeruzalėje priešais savo brolius.'),
  (@b13, 9, 39, 'O Neras pagimdė Kišą; o Kišas pagimdė Saulių; o Saulius pagimdė Jonataną, Malki-Šuvą, Abinadabą ir Eš-Baalą.'),
  (@b13, 9, 40, 'O Jonatano sūnus buvo Merib-Baalas; o Merib-Baalas pagimdė Michą.'),
  (@b13, 9, 41, 'O Michos sūnūs: Pitonas, Melechas, Tachrėja ir Ahazas.'),
  (@b13, 9, 42, 'O Ahazas pagimdė Jarą; o Jara pagimdė Alemetą, Azmavetą ir Zimrį; o Zimris pagimdė Mocą;'),
  (@b13, 9, 43, 'o Moca pagimdė Binėją; o jo sūnus Refaja, jo sūnus Eleasa, jo sūnus Acelis.'),
  (@b13, 9, 44, 'O Acelis turėjo šešis sūnus, kurių vardai yra šitie: Azrikamas, Bochruva, Išmaelis, Šearija, Abdijas ir Hananas; šitie buvo Azelio sūnūs.'),
  (@b13, 10, 1, 'Na, o filistinai kovojo prieš Izraelį; o Izraelio vyrai bėgo nuo filistinų akivaizdos ir krito užmušti Gilbojos kalne.'),
  (@b13, 10, 2, 'Ir filistinai įkandin sekė paskui Saulių ir jo sūnus; ir filistinai užmušė Jonataną, Abinadabą ir Malki-Šūvą, Sauliaus sūnus.'),
  (@b13, 10, 3, 'Ir buvo smarkus mūšis prieš Saulių, ir lankininkai į jį pataikė, ir jis buvo lankininkų sužeistas.'),
  (@b13, 10, 4, 'Tada Saulius tarė savo ginklanešiui: „Išsitrauk savo kalaviją ir perdurk juo mane; kad šitie neapipjaustytieji atėję nepasityčiotų iš manęs“. Bet jo ginklanešys nenorėjo; nes jis labai bijojo. Taigi Saulius paėmė kalaviją ir krito ant jo.'),
  (@b13, 10, 5, 'O jo ginklanešys pamatęs, kad Saulius miręs, taip pat krito ant kalavijo ir mirė.'),
  (@b13, 10, 6, 'Taip mirė Saulius ir trys jo sūnūs, ir visi jo namai mirė kartu.'),
  (@b13, 10, 7, 'O visi Izraelio žmonės, esantys slėnyje, pamatę, kad jie pabėgo ir kad Saulius bei jo sūnūs mirę, paliko savo miestus ir pabėgo; o filistinai atėjo ir juose apsigyveno.'),
  (@b13, 10, 8, 'Ir rytojaus dieną įvyko, kad filistinai, atėję išrengti užmuštųjų, rado Saulių ir jo sūnus, kritusius Gilbojos kalne.'),
  (@b13, 10, 9, 'Ir jį nurengę, jie paėmė jo galvą bei jo ginklus ir siuntė aplink po filistinų šalį, kad skleistų žinią jų stabams ir tautai.'),
  (@b13, 10, 10, 'Ir jie padėjo jo ginklus savo dievų namuose, o jo galvą pritvirtino Dagono šventykloje.'),
  (@b13, 10, 11, 'Ir kai visas Jabeš-Gileadas išgirdo viską, ką filistinai buvo padarę Sauliui,'),
  (@b13, 10, 12, 'visi narsūs vyrai pakilo ir paėmė Sauliaus kūną bei jo sūnų kūnus ir, juos atgabenę į Jabešą, palaidojo jų kaulus po ąžuolu Jabeše ir pasninkavo septynias dienas.'),
  (@b13, 10, 13, 'Taip mirė Saulius už savo nusižengimą, kurį jis padarė prieš VIEŠPATĮ, tai yra prieš VIEŠPATIES žodį, kurio jis nesilaikė, ir taip pat dėl to, kad prašė patarimo iš turinčiojo namų dvasią, kad jos pasiklaustų;'),
  (@b13, 10, 14, 'o nepasiklausė VIEŠPATIES; todėl jis užmušė jį ir atidavė karalystę Jesės sūnui Dovydui.'),
  (@b13, 11, 1, 'Tada visas Izraelis susirinko pas Dovydą į Hebroną, sakydami: „Štai mes esame tavo kaulas ir tavo kūnas.'),
  (@b13, 11, 2, 'Ir, be to, anksčiau, kai Saulius buvo karalius, tu buvai tas, kuris išvesdavai ir įvesdavai Izraelį; ir VIEŠPATS, tavo Dievas, tau sakė: „Tu ganysi mano tautą Izraelį ir būsi mano tautos Izraelio valdovas’“.'),
  (@b13, 11, 3, 'Todėl visi Izraelio vyresnieji atėjo pas karalių į Hebroną; ir Dovydas sudarė su jais sandorą Hebrone VIEŠPATIES akivaizdoje; ir jie patepė Dovydą Izraelio karaliumi pagal VIEŠPATIES žodį per Samuelį.'),
  (@b13, 11, 4, 'Ir Dovydas ir visas Izraelis ėjo į Jeruzalę, kuri yra Jebusas; kur buvo tos šalies gyventojai jebusiečiai.'),
  (@b13, 11, 5, 'Ir Jebuso gyventojai tarė Dovydui: „Tu čia neateisi“. Tačiau Dovydas paėmė tvirtovę Siono, kuris yra Dovydo miestas.'),
  (@b13, 11, 6, 'Ir Dovydas tarė: „Kas pirmas sumuš jebusiečius, tas bus vyriausiasis ir vadas“. Taigi pirmas nuėjo aukštyn Cerujos sūnus Joabas ir buvo vyriausiuoju.'),
  (@b13, 11, 7, 'Ir Dovydas apsigyveno tvirtovėje; todėl ją praminė Dovydo miestu.'),
  (@b13, 11, 8, 'Ir jis pastatė miestą aplinkui, nuo Milo aplinkui; o Joabas atitaisė likusįjį miestą.'),
  (@b13, 11, 9, 'Taip Dovydas ėjo vis didyn ir didyn; nes kariuomenių VIEŠPATS buvo su juo.'),
  (@b13, 11, 10, 'Taip pat šitie yra galiūnų vyriausieji, kuriuos Dovydas turėjo, kurie sustiprėjo su juo jo karalystėje ir su visu Izraeliu, kad padarytų jį karaliumi pagal VIEŠPATIES žodį apie Izraelį.'),
  (@b13, 11, 11, 'O šitas yra skaičius galiūnų, kuriuos Dovydas turėjo: hachmonietis Jašobamas, vadų vyriausiasis; jis pakėlė savo ietį prieš tris šimtus jo paties nukautų vienu kartu.'),
  (@b13, 11, 12, 'O po jo buvo Dodojo sūnus Eleazaras, ahochas, kuris buvo vienas iš tų trijų galiūnų.'),
  (@b13, 11, 13, 'Jis buvo su Dovydu Pas-Damime, ir filistinai ten buvo susirinkę į mūšį, kur buvo žemės sklypas, pilnas miežių; ir tauta pabėgo nuo filistinų akivaizdos.'),
  (@b13, 11, 14, 'O jie, atsistoję to sklypo viduryje, jį išvadavo ir išžudė filistinus; ir VIEŠPATS juos išgelbėjo didžiu išgelbėjimu.'),
  (@b13, 11, 15, 'Na, o trys iš trisdešimties vadų nuėjo žemyn iki uolos pas Dovydą į Adulamo olą; o filistinų kariuomenė stovyklavo Refaimo slėnyje.'),
  (@b13, 11, 16, 'Ir Dovydas tada buvo tvirtovėje, o filistinų įgula tada buvo Betliejuje.'),
  (@b13, 11, 17, 'Ir Dovydas ilgėdamasis tarė: „Ak, kad kas man duotų atsigerti vandens iš Betliejaus šulinio, esančio prie vartų!“'),
  (@b13, 11, 18, 'Ir tie trys prasilaužė pro filistinų kariuomenę, pasėmė vandens iš Betliejaus šulinio, esančio prie vartų, ir paėmę atnešė jo Dovydui; bet Dovydas nenorėjo jo gerti, bet jį išliejo VIEŠPAČIUI'),
  (@b13, 11, 19, 'ir tarė: „Mano Dievas teneleidžia man, kad aš tai daryčiau; ar man gerti kraują šitų vyrų, kurie statė pavojun savo gyvybes? Nes statydami pavojun savo gyvybes jie atnešė jo“. Todėl jis nenorėjo jo gerti. Šiuos dalykus padarė šitie trys galiūnai.'),
  (@b13, 11, 20, 'O Joabo brolis Abišajas buvo tų trijų vyriausiasis; nes, pakėlęs savo ietį prieš tris šimtus, jis juos išžudė ir pagarsėjo tarp tų trijų.'),
  (@b13, 11, 21, 'Iš tų trijų jis buvo labiau gerbiamas negu du; nes jis buvo jų vadas; tačiau jis neprilygo pirmiems trims.'),
  (@b13, 11, 22, 'Jehojados sūnus Benaja, narsaus vyro iš Kabcelio sūnus, kuris padarė daug žygdarbių; jis užmušė du Moabo vyrus, panašius į liūtus; be to, jis nuėjo žemyn ir užmušė liūtą duobėje snieguotą dieną.'),
  (@b13, 11, 23, 'Ir jis užmušė egiptietį, aukštaūgį vyrą, penkių uolekčių ūgio; egiptiečio rankoje buvo ietis, panaši į audėjo riestuvą; ir jis nuėjo žemyn pas jį su lazda, išplėšė ietį iš egiptiečio rankos ir nužudė jį jo paties ietimi.'),
  (@b13, 11, 24, 'Šiuos dalykus padarė Jehojados sūnus Benaja ir pagarsėjo tarp trijų galiūnų.'),
  (@b13, 11, 25, 'Štai jis buvo gerbiamas tarp trisdešimties, bet pirmiems trims neprilygo; ir Dovydas jį paskyrė savo sargybos vadu.'),
  (@b13, 11, 26, 'Kariuomenių narsuoliais taip pat buvo Joabo brolis Asaelis, Dodojo sūnus Elhananas iš Betliejaus,'),
  (@b13, 11, 27, 'harorietis Šamotas, pelojietis Helecas,'),
  (@b13, 11, 28, 'tekojiečio Ikešo sūnus Ira, anatotietis Abiezeras,'),
  (@b13, 11, 29, 'hušietis Sibekajas, ahohitas Ilajas,'),
  (@b13, 11, 30, 'netofietis Maharajas, Baanos sūnus Heledas – netofietis,'),
  (@b13, 11, 31, 'Itajas – sūnus Ribajo iš Gibėjos, priklausančios Benjamino vaikams, piratonietis Benaja,'),
  (@b13, 11, 32, 'Hurajas iš Gaašo upelių, arbietis Abielis,'),
  (@b13, 11, 33, 'baharumietis Azmavetas, šaalbonietis Eljahba,'),
  (@b13, 11, 34, 'gizojiečio Hašemo sūnūs, hararo Šagės sūnus Jonatanas,'),
  (@b13, 11, 35, 'hararo Sacharo sūnus Ahiamas, Ūro sūnus Elifalas,'),
  (@b13, 11, 36, 'mecherietis Heferas, pelojietis Ahija,'),
  (@b13, 11, 37, 'karmelietis Hezrojas, Ezbajo sūnus Naaraja,'),
  (@b13, 11, 38, 'Natano brolis Joelis, Hagrio sūnus Mibharas,'),
  (@b13, 11, 39, 'amonietis Celekas, beerotietis Nahrajas, Cerujos sūnaus Joabo ginklanešys;'),
  (@b13, 11, 40, 'itritas Ira, itritas Garebas,'),
  (@b13, 11, 41, 'hetitas Ūrija, Achlajos sūnus Zabadas,'),
  (@b13, 11, 42, 'rubeno Šizos sūnus Adina, rubenų vadas, ir trisdešimt su juo,'),
  (@b13, 11, 43, 'Maakos sūnus Hananas ir mitnietis Juozapatas,'),
  (@b13, 11, 44, 'aštarotietis Uzija, aroeriečio Hotamo sūnūs Šama ir Jejelis,'),
  (@b13, 11, 45, 'Šimrio sūnus Jediaelis ir jo brolis ticietis Joha,'),
  (@b13, 11, 46, 'mahavietis Elielis, Elnaamo sūnūs Jeribajas bei Jošavija ir moabietis Itma,'),
  (@b13, 11, 47, 'Elielis, Obedas ir mezobaitas Jaasielis.'),
  (@b13, 12, 1, 'Na, o šitie yra tie, kurie atėjo pas Dovydą į Ciklagą, kol jis buvo užsirakinęs dėl Kišo sūnaus Sauliaus; jie buvo tarp galiūnų, padėjėjai kare.'),
  (@b13, 12, 2, 'Jie buvo apsiginklavę lankais ir galėjo dešiniąja ir kairiąja ranka svaidyti akmenis ir šaudyti strėles iš lanko; jie buvo iš Sauliaus brolių, iš Benjamino.'),
  (@b13, 12, 3, 'Vyriausiasis buvo Ahiezeras, paskui Joašas, gibėjiečio Šemavos sūnūs; Azmaveto sūnūs Jezielis ir Peletas; Beracha ir anatotietis Jehuvas;'),
  (@b13, 12, 4, 'gibeonietis Išmaja, galiūnas tarp trisdešimties, trisdešimties viršininkas; Jeremijas, Jahazielis, Johananas ir gederietis Jozabadas,'),
  (@b13, 12, 5, 'Eluzajas, Jerimotas, Bealija, Šemarija ir harufietis Šefatija,'),
  (@b13, 12, 6, 'korachai Elkana, Išija, Azarelis, Joezeras ir Jašobamas,'),
  (@b13, 12, 7, 'Jerohamo iš Gedoro sūnūs Joela ir Zebadija.'),
  (@b13, 12, 8, 'Ir iš gadų atsiskyrė pas Dovydą į tvirtovę, į dykumą, galingi vyrai, karo vyrai, tinkami mūšiui, galintys valdyti didįjį skydą ir mažąjį skydą, kurių veidai buvo kaip liūtų veidai ir kurie buvo greiti kaip stirnos kalnuose:'),
  (@b13, 12, 9, 'pirmasis Ezeras, antrasis Abdijas, trečiasis Eliabas,'),
  (@b13, 12, 10, 'ketvirtasis Mišmana, penktasis Jeremijas,'),
  (@b13, 12, 11, 'šeštasis Atajas, septintasis Elielis,'),
  (@b13, 12, 12, 'aštuntasis Johananas, devintasis Elzabadas,'),
  (@b13, 12, 13, 'dešimtasis Jeremijas, vienuoliktasis Machbanajas.'),
  (@b13, 12, 14, 'Šitie buvo iš Gado sūnų, kariuomenės vadai; vienas iš mažiausiųjų vadovavo šimtui, o didžiausiasis vadovavo tūkstančiui.'),
  (@b13, 12, 15, 'Šitie yra tie, kurie pirmąjį mėnesį perėjo per Jordaną, kai jis buvo išsiliejęs iš visų savo krantų; ir jie privertė bėgti visus, esančius iš slėnių, į rytus ir į vakarus.'),
  (@b13, 12, 16, 'Ir atėjo iš Benjamino ir iš Judos vaikų į tvirtovę pas Dovydą.'),
  (@b13, 12, 17, 'Ir Dovydas išėjo jų pasitikti ir atsiliepdamas jiems tarė: „Jei atėjote pas mane taikingai, man padėti, tai mano širdis susijungs su jumis; bet jei atėjote manęs išduoti mano priešams, nors ir nėra neteisybės mano rankose, tegul mūsų tėvų Dievas tai pamato ir papeikia“.'),
  (@b13, 12, 18, 'Tada Dvasia atėjo ant Amasajo, vadų vyriausiojo, ir jis tarė: „Tavo mes esame, Dovydai, ir su tavimi, Jesės sūnau; ramybė, ramybė tebūna tau ir ramybė tebūna tavo padėjėjams; nes tau padeda tavo Dievas“. Tada Dovydas priėmė juos ir padarė juos būrio vadais.'),
  (@b13, 12, 19, 'Ir kai kurie iš Manaso persimetė pas Dovydą, kai jis atėjo su filistinais prieš Saulių į mūšį; bet jie jiems nepadėjo; nes pasitarę filistinų viešpačiai jį paleido, sakydami: „Jis persimes pas savo valdovą Saulių, statydamas į pavojų mūsų galvas“.'),
  (@b13, 12, 20, 'Jam einant į Ciklagą, pas jį persimetė iš Manaso: Adna, Jozabadas, Jediaelis, Mykolas, Jozabadas, Elihuvas ir Ciletajas, Manaso tūkstančių vadai.'),
  (@b13, 12, 21, 'Ir jie padėjo Dovydui prieš plėšikų gaują; nes jie visi buvo narsūs galiūnai ir buvo kariuomenėje vadai.'),
  (@b13, 12, 22, 'Nes tuo laiku diena iš dienos ateidavo pas Dovydą jam padėti, kol buvo didelė kariuomenė, kaip Dievo kariuomenė.'),
  (@b13, 12, 23, 'O šitie yra skaičiai būrių, apsiginklavusių karui, atėjusių pas Dovydą į Hebroną, kad jam atiduotų Sauliaus karalystę pagal VIEŠPATIES žodį.'),
  (@b13, 12, 24, 'Judos vaikų, nešiojančių skydą ir ietį: šeši tūkstančiai aštuoni šimtai apsiginklavusių karui.'),
  (@b13, 12, 25, 'Iš Simeono vaikų, galingų narsuolių karui: septyni tūkstančiai šimtas.'),
  (@b13, 12, 26, 'Iš Levio vaikų: keturi tūkstančiai šeši šimtai.'),
  (@b13, 12, 27, 'O aaronų vadas buvo Jehojada ir su juo trys tūkstančiai septyni šimtai;'),
  (@b13, 12, 28, 'ir Cadokas, galingas narsus jaunuolis, ir iš jo tėvo namų dvidešimt du vadai.'),
  (@b13, 12, 29, 'O iš Benjamino vaikų, Sauliaus giminaičių: trys tūkstančiai; nes iki šiol didesnė jų dalis ėjo Sauliaus namų sargybą.'),
  (@b13, 12, 30, 'O iš Efraimo vaikų: dvidešimt tūkstančių aštuoni šimtai galingų narsuolių, pagarsėjusių savo tėvų namuose.'),
  (@b13, 12, 31, 'O iš pusės Manaso genties: aštuoniolika tūkstančių, kurie buvo pašaukti vardais, kad atvyktų ir padarytų Dovydą karaliumi.'),
  (@b13, 12, 32, 'O iš Isacharo vaikų, vyrų, išmanančių laikus, kad žinotų, ką Izraelis turi daryti, jų buvo du šimtai galvų; ir visi jų broliai buvo pagal jų paliepimą.'),
  (@b13, 12, 33, 'Iš Zebulono, einančių į mūšį, prityrusių kare, su visais karo ginklais: penkiasdešimt tūkstančių, galinčių laikytis rikiuotės; jie buvo nedvejojančios širdies.'),
  (@b13, 12, 34, 'O iš Naftalio: tūkstantis vadų ir su jais trisdešimt septyni tūkstančiai su skydu ir ietimi.'),
  (@b13, 12, 35, 'O iš danų, prityrusių kare: dvidešimt aštuoni tūkstančiai šeši šimtai.'),
  (@b13, 12, 36, 'O iš Ašero, einančių į mūšį, prityrusių kare: keturiasdešimt tūkstančių.'),
  (@b13, 12, 37, 'O anapus Jordano, iš rubenų, gadų ir pusės Manaso genties, su visokiais karo prietaisais mūšiui: šimtas dvidešimt tūkstančių.'),
  (@b13, 12, 38, 'Visi šitie karo vyrai, galintys laikytis rikiuotės, atėjo tobula širdimi į Hebroną, kad padarytų Dovydą viso Izraelio karaliumi; taip pat ir visas likusysis Izraelis buvo vienos širdies, kad padarytų Dovydą karaliumi.'),
  (@b13, 12, 39, 'Ir jie ten buvo pas Dovydą tris dienas valgydami ir gerdami; nes jų broliai buvo jiems paruošę.'),
  (@b13, 12, 40, 'Be to, tie, kurie buvo arti jų, būtent prie Isacharo, Zebulono ir Naftalio, atgabeno duonos ant asilų, ant kupranugarių, ant mulų ir ant jaučių, maisto, miltų, figų pyragų, razinų kekių, vyno, aliejaus, jaučių ir avių gausybę; nes buvo džiaugsmas Izraelyje.'),
  (@b13, 13, 1, 'Ir Dovydas pasitarė su tūkstantininkais ir šimtininkais, ir su visais vadais.'),
  (@b13, 13, 2, 'Ir Dovydas tarė visam Izraelio susirinkimui: „Jei jums atrodo gerai ir kad tai yra iš VIEŠPATIES, mūsų Dievo, pasiųskime visur savo broliams, pasilikusiems visoje Izraelio šalyje, ir su jais kunigams bei levitams, esantiems jų miestuose ir priemiesčiuose, kad jie susirinktų pas mus;'),
  (@b13, 13, 3, 'ir parsigabenkime pas save mūsų Dievo skrynią; nes Sauliaus dienomis jos nesiteiravome“.'),
  (@b13, 13, 4, 'Ir visas susirinkimas pasakė, kad jie nori taip padaryti; nes tas dalykas buvo teisingas visos tautos akyse.'),
  (@b13, 13, 5, 'Taigi Dovydas surinko visą Izraelį nuo Egipto Šihoro iki Hemato įėjimo, kad pargabentų Dievo skrynią iš Kirjat-Jearimo.'),
  (@b13, 13, 6, 'Dovydas ir visas Izraelis ėjo aukštyn į Baalą, tai yra į Kirjat-Jearimą, priklausantį Judai, kad iš ten atgabentų aukštyn Dievo, tarp kerubų gyvenančio VIEŠPATIES, skrynią, ant kurios minimas jo vardas.'),
  (@b13, 13, 7, 'Ir jie gabeno Dievo skrynią naujame vežime iš Abinadabo namų; o Uza ir Ahjojas varė vežimą.'),
  (@b13, 13, 8, 'Ir Dovydas ir visas Izraelis grojo Dievo akivaizdoje iš visų jėgų, su giesmėmis, su arfomis, su psalteriais, su būgneliais, su cimbolais ir su trimitais.'),
  (@b13, 13, 9, 'Ir jiems atėjus prie Kidono klojimo, Uza ištiesė ranką, kad prilaikytų skrynią; nes jaučiai suklupo.'),
  (@b13, 13, 10, 'Ir VIEŠPATIES pyktis užsidegė prieš Uzą, ir jis jį ištiko, kadangi jis ištiesė savo ranką į skrynią; ir jis ten mirė Dievo akivaizdoje.'),
  (@b13, 13, 11, 'Ir Dovydas buvo nepatenkintas, kadangi VIEŠPATS padarė spragą Uzui; todėl tą vietą vadina Perec-Uza iki šios dienos.'),
  (@b13, 13, 12, 'Ir tą dieną Dovydas bijojo Dievo, sakydamas: „Kaip aš atgabensiu pas save į namus Dievo skrynią?“'),
  (@b13, 13, 13, 'Taigi Dovydas nepargabeno skrynios pas save namo į Dovydo miestą, bet ją nunešė į šoną į gatiečio Obed-Edomo namus.'),
  (@b13, 13, 14, 'Ir Dievo skrynia pasiliko tris mėnesius pas Obed-Edomo šeimą jo namuose. Ir VIEŠPATS laimino Obed-Edomo namus ir viską, ką jis turėjo.'),
  (@b13, 14, 1, 'Na, o Tyro karalius Hiramas siuntė pasiuntinius pas Dovydą ir kedro medieną su mūrininkais ir dailidėmis, kad jam pastatytų namus.'),
  (@b13, 14, 2, 'Ir Dovydas suprato, kad VIEŠPATS jį buvo patvirtinęs Izraelio karaliumi, nes jo karalystė buvo iškelta aukštai dėl jo tautos Izraelio.'),
  (@b13, 14, 3, 'Ir Dovydas ėmė daugiau žmonų Jeruzalėje; ir Dovydas pagimdė daugiau sūnų bei dukterų.'),
  (@b13, 14, 4, 'Na, o šitie yra vardai jo vaikų, kuriuos jis turėjo Jeruzalėje: Šamūva ir Šobabas, Natanas ir Saliamonas,'),
  (@b13, 14, 5, 'Ibharas, Elišūva, Elpaletas,'),
  (@b13, 14, 6, 'Nogahas, Nefegas, Jafija,'),
  (@b13, 14, 7, 'Elišama, Beeljada ir Elifeletas.'),
  (@b13, 14, 8, 'Ir kai filistinai išgirdo, kad Dovydas buvo pateptas karaliumi visam Izraeliui, visi filistinai ėjo aukštyn Dovydo ieškoti. Ir tai išgirdęs, Dovydas išėjo prieš juos.'),
  (@b13, 14, 9, 'Ir filistinai atėję pasklido Refaimo slėnyje.'),
  (@b13, 14, 10, 'O Dovydas teiravosi Dievo, sakydamas: „Ar man eiti aukštyn prieš filistinus? Ar juos atiduosi man į rankas?“ Ir VIEŠPATS jam tarė: „Eik aukštyn; nes aš juos atiduosiu tau į rankas“.'),
  (@b13, 14, 11, 'Taigi jis nuėjo aukštyn į Baal-Peracimą; ir ten Dovydas juos sumušė. Tada Dovydas tarė: „Dievas prasilaužė pro mano priešus mano ranka, kaip vanduo prasilaužia“; todėl tą vietą praminė Baal-Peracimu.'),
  (@b13, 14, 12, 'Ir jiems ten palikus savo dievus, Dovydas įsakė, ir jie buvo sudeginti ugnimi.'),
  (@b13, 14, 13, 'O filistinai vėl pasklido slėnyje.'),
  (@b13, 14, 14, 'Todėl Dovydas vėl klausė Dievo; ir Dievas jam tarė: „Neik aukštyn paskui juos; nusisuk nuo jų ir užpulk juos priešais šilkmedžius.'),
  (@b13, 14, 15, 'Ir bus, kai tik išgirsi ėjimo garsą šilkmedžių viršūnėse, tada išeik į mūšį; nes Dievas yra išėjęs tavo priešakyje filistinų kariuomenės mušti“.'),
  (@b13, 14, 16, 'Taigi Dovydas padarė, kaip Dievas jam įsakė; ir jis mušė filistinų kariuomenę nuo Gibeono iki Gazero.'),
  (@b13, 14, 17, 'Ir garsas apie Dovydą pasklido visose šalyse; ir VIEŠPATS atnešė jo baimę ant visų tautų.'),
  (@b13, 15, 1, 'Ir pasistatęs namų Dovydo mieste, Dovydas paruošė vietą Dievo skryniai ir jai ištiesė palapinę.'),
  (@b13, 15, 2, 'Tada Dovydas tarė: „Niekas teneneša Dievo skrynios, o tik levitai; nes juos VIEŠPATS išsirinko Dievo skryniai nešioti ir jam amžinai tarnauti“.'),
  (@b13, 15, 3, 'Ir Dovydas surinko visą Izraelį į Jeruzalę, kad gabentų aukštyn VIEŠPATIES skrynią į jos vietą, kurią jis jai paruošė.'),
  (@b13, 15, 4, 'Ir Dovydas surinko Aarono vaikus ir levitus:'),
  (@b13, 15, 5, 'Iš Kehato sūnų: vyriausiąjį Ūrielį ir jo brolius, šimtą dvidešimt;'),
  (@b13, 15, 6, 'iš Merario sūnų: vyriausiąjį Asają ir jo brolius, du šimtus dvidešimt;'),
  (@b13, 15, 7, 'iš Geršomo sūnų: vyriausiąjį Joelį ir jo brolius, šimtą trisdešimt;'),
  (@b13, 15, 8, 'iš Elicafano sūnų: vyriausiąjį Šemają ir jo brolius, du šimtus;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b13, 15, 9, 'iš Hebrono sūnų: vyriausiąjį Elielį ir jo brolius, aštuoniasdešimt;'),
  (@b13, 15, 10, 'iš Uzielio sūnų: vyriausiąjį Aminadabą ir jo brolius, šimtą dvylika.'),
  (@b13, 15, 11, 'Ir Dovydas pašaukė kunigus Cadoką ir Abjatarą bei levitus Ūrielį, Asają ir Joelį, Šemają, Elielį ir Aminadabą,'),
  (@b13, 15, 12, 'ir jiems tarė: „Jūs esate levitų tėvų vyriausieji; pasišvęskite jūs ir jūsų broliai, kad galėtumėte gabenti aukštyn VIEŠPATIES, Izraelio Dievo, skrynią į vietą, kurią esu jai paruošęs.'),
  (@b13, 15, 13, 'Kadangi pirma to nepadarėte, tai VIEŠPATS, mūsų Dievas, padarė mums spragą, nes mes jo neieškojome pagal reikiamą tvarką.'),
  (@b13, 15, 14, 'Taigi kunigai ir levitai pasišventė, kad gabentų aukštyn VIEŠPATIES, Izraelio Dievo, skrynią.'),
  (@b13, 15, 15, 'Ir levitų vaikai nešė ant pečių Dievo skrynią su kartimis ant jos, kaip Mozė įsakė pagal VIEŠPATIES žodį.'),
  (@b13, 15, 16, 'Ir Dovydas kalbėjo levitų vyriausiems, kad paskirtų jų brolius būti giesmininkais su muzikos instrumentais, psalteriais, arfomis ir cimbolais, skambinti, keliant džiaugsmingai balsus.'),
  (@b13, 15, 17, 'Taigi levitai paskyrė Joelio sūnų Hemaną; o iš jo brolių – Berechijos sūnų Asafą; o iš Merario sūnų, jų brolių, – Kušajo sūnų Etaną;'),
  (@b13, 15, 18, 'o su jais jų antros eilės brolius: Zachariją, Beną, Jaazielį, Šemiramotą, Jehielį, Unį, Eliabą, Benają, Maasėją, Matitiją, Elifeletą, Miknėją, Obed-Edomą ir Jejelį, durininkus.'),
  (@b13, 15, 19, 'Taigi giesmininkai Hemanas, Asafas ir Etanas buvo paskirti skambinti žalvario cimbolais;'),
  (@b13, 15, 20, 'o Zacharija, Azielis, Šemiramotas, Jehielis, Unis, Eliabas, Maasėjas ir Benajas – psalteriais alamotu;'),
  (@b13, 15, 21, 'o Matatija, Elifeletas, Miknėjas, Obed-Edomas, Jejelis ir Azazija – arfomis šeminitu, kad pranoktų.'),
  (@b13, 15, 22, 'O Kenanijas, levitų vyriausiasis, buvo giedojimui; jis mokė apie giedojimą, nes jis buvo įgudęs.'),
  (@b13, 15, 23, 'O Berechija ir Elkana buvo skrynios durininkai.'),
  (@b13, 15, 24, 'O kunigai Šebanijas, Jehozapatas, Netanelis, Amasajas, Zacharija, Benajas ir Eliezeras pūtė trimitais prieš Dievo skrynią; o Obed-Edomas ir Jehija buvo skrynios durininkai.'),
  (@b13, 15, 25, 'Taigi Dovydas, Izraelio vyresnieji ir tūkstantininkai, nuėjo VIEŠPATIES Sandoros skrynios atgabenti aukštyn iš Obed-Edomo namų su džiaugsmu.'),
  (@b13, 15, 26, 'Ir įvyko, kai Dievas padėjo levitams, nešantiems VIEŠPATIES Sandoros skrynią, tada jie atnašavo septynis jaučius ir septynis avinus.'),
  (@b13, 15, 27, 'O Dovydas buvo apsivilkęs plono lino apsiaustu, ir visi levitai, nešantys skrynią, giesmininkai ir Kenanija, giedojimo vadovas su giesmininkais; taip pat Dovydas vilkėjo lininį efodą.'),
  (@b13, 15, 28, 'Taip visas Izraelis gabeno aukštyn VIEŠPATIES Sandoros skrynią su šauksmu, su korneto garsu, su trimitais ir su cimbolais, skleisdami garsą psalteriais ir arfomis.'),
  (@b13, 15, 29, 'Ir įvyko, kai VIEŠPATIES Sandoros skrynia atėjo į Dovydo miestą, Sauliaus duktė Mikalė, žiūrėdama pro langą, pamatė karalių Dovydą šokantį ir grojantį; ir ji paniekino jį savo širdyje.'),
  (@b13, 16, 1, 'Taip jie atnešė Dievo skrynią ir pastatė ją viduryje palapinės, kurią Dovydas jai buvo ištiesęs; ir jie atnašavo deginamąsias aukas ir taikos atnašas Dievo akivaizdoje.'),
  (@b13, 16, 2, 'Ir baigęs atnašauti deginamąsias atnašas ir taikos atnašas, Dovydas palaimino tautą VIEŠPATIES vardu.'),
  (@b13, 16, 3, 'Ir jis išdalino kiekvienam iš Izraelio, tiek vyrams, tiek moterims, kiekvienam po duonos kepalą, gerą gabalą mėsos ir po ąsotį vyno.'),
  (@b13, 16, 4, 'Ir jis paskyrė kai kuriuos iš levitų tarnauti prieš VIEŠPATIES skrynią, kad minėtų, dėkotų ir girtų VIEŠPATĮ, Izraelio Dievą:'),
  (@b13, 16, 5, 'Asafą – vyriausiąjį, po jo Zachariją, Jejelį, Šemiramotą, Jehielį, Matitiją, Eliabą, Benają, Obed-Edomą; Jejelį su psalteriais ir arfomis; bet Asafas skambino cimbolais;'),
  (@b13, 16, 6, 'taip pat kunigus Benają ir Jahazielį nuolat su trimitais prieš Dievo Sandoros skrynią.'),
  (@b13, 16, 7, 'Tada, tą dieną, Dovydas pirmą kartą įteikė šią psalmę Asafui ir jo broliams į rankas dėkoti VIEŠPAČIUI:'),
  (@b13, 16, 8, '„Dėkokite VIEŠPAČIUI, šaukitės jo vardo, skelbkite tarp tautų jo darbus.'),
  (@b13, 16, 9, 'Giedokite jam, giedokite jam psalmes, kalbėkite apie jo visus nuostabius darbus.'),
  (@b13, 16, 10, 'Girkitės jo šventuoju vardu; tegul džiaugiasi širdis tų, kurie ieško VIEŠPATIES.'),
  (@b13, 16, 11, 'Ieškokite VIEŠPATIES ir jo stiprybės, nuolat ieškokite jo veido.'),
  (@b13, 16, 12, 'Atsiminkite jo nuostabius darbus, kuriuos jis padarė, jo stebuklus ir jo burnos teismus;'),
  (@b13, 16, 13, 'o jūs, jo tarno Izraelio sėkla, Jokūbo vaikai, jo išrinktieji.'),
  (@b13, 16, 14, 'Jis yra VIEŠPATS, mūsų Dievas; visoje žemėje yra jo teismai.'),
  (@b13, 16, 15, 'Visada atminkite jo sandorą – žodį, kurį jis įsakė tūkstančiui kartų,'),
  (@b13, 16, 16, 'būtent sandorą, kurią jis sudarė su Abraomu, ir jo priesaiką Izaokui;'),
  (@b13, 16, 17, 'ir ją patvirtino Jokūbui kaip įstatymą ir Izraeliui kaip amžiną sandorą,'),
  (@b13, 16, 18, 'sakydamas: ‘Tau duosiu Kanaano šalį, jūsų paveldo dalią’;'),
  (@b13, 16, 19, 'kai jūs buvote mažuma, būtent mažuma, ir ateiviai joje.'),
  (@b13, 16, 20, 'Ir jiems einant iš tautos į tautą, iš vienos karalystės į kitą tautą;'),
  (@b13, 16, 21, 'jis niekam neleido jų skriausti; taip, jis subarė dėl jų karalius,'),
  (@b13, 16, 22, 'sakydamas: ‘Nelieskite mano pateptųjų ir mano pranašams nedarykite pikto’.'),
  (@b13, 16, 23, 'Giedokite VIEŠPAČIUI, visa žeme; skelbkite diena iš dienos jo išgelbėjimą.'),
  (@b13, 16, 24, 'Skelbkite tarp pagonių jo šlovę; jo nuostabius darbus tarp visų tautų.'),
  (@b13, 16, 25, 'Nes didis yra VIEŠPATS ir didžiai turi būti giriamas; jis taip pat turi būti bijotinas labiau už visus dievus.'),
  (@b13, 16, 26, 'Nes visi tautų dievai yra stabai; bet VIEŠPATS padarė dangus.'),
  (@b13, 16, 27, 'Šlovė ir garbė yra jo akivaizdoje; stiprybė ir džiaugsmas yra jo vietoje.'),
  (@b13, 16, 28, 'Duokite VIEŠPAČIUI, tautų giminės, duokite VIEŠPAČIUI šlovę ir stiprybę.'),
  (@b13, 16, 29, 'Duokite VIEŠPAČIUI šlovę, priklausančią jo vardui; atneškite atnašą ir ateikite jo akivaizdon; garbinkite VIEŠPATĮ šventumo grožyje.'),
  (@b13, 16, 30, 'Bijokite prieš jį, visa žeme; pasaulis taip pat bus tvirtas, kad nepajudėtų.'),
  (@b13, 16, 31, 'Tegul linksminasi dangūs ir džiūgauja žemė; ir tebūna sakoma tarp tautų: ‘VIEŠPATS karaliauja’.'),
  (@b13, 16, 32, 'Teūžauja jūra ir jos pilnybė; tedžiūgauja laukai ir visa, kas juose.'),
  (@b13, 16, 33, 'Tada miško medžiai giedos VIEŠPATIES akivaizdoje, nes jis ateina žemės teisti.'),
  (@b13, 16, 34, 'O, dėkokite VIEŠPAČIUI; nes jis yra geras; nes jo gailestingumas išlieka per amžius.'),
  (@b13, 16, 35, 'Ir sakykite: ‘Gelbėk mus, o mūsų išgelbėjimo Dieve, surink mus ir išgelbėk iš pagonių, kad dėkotume tavo šventam vardui ir kad girtumėmės tavo gyriumi.'),
  (@b13, 16, 36, 'Tebūna palaimintas VIEŠPATS, Izraelio Dievas, per amžių amžius’“. Ir visa tauta tarė: „Amen“ ir gyrė VIEŠPATĮ.'),
  (@b13, 16, 37, 'Taigi jis ten paliko prieš VIEŠPATIES Sandoros skrynią Asafą ir jo brolius, kad nuolat tarnautų prieš skrynią, kaip reikalavo kasdienis darbas;'),
  (@b13, 16, 38, 'ir Obed-Edomą su jų broliais, šešiasdešimt aštuonis; taip pat Obed-Edomą, Jedutūno sūnų, ir Hosą būti durininkais;'),
  (@b13, 16, 39, 'o kunigą Cadoką ir jo brolius kunigus prieš VIEŠPATIES padangtę aukštumoje, esančioje Gibeone,'),
  (@b13, 16, 40, 'kad nuolat, ryte ir vakare, atnašautų VIEŠPAČIUI deginamąsias atnašas ant deginamosios atnašos aukuro ir kad darytų pagal visa tai, kas parašyta VIEŠPATIES įstatyme, kurį jis įsakė Izraeliui;'),
  (@b13, 16, 41, 'o su jais Hemaną, Jedutūną ir kitus išrinktus, pašauktus vardais, kad dėkotų VIEŠPAČIUI, nes jo gailestingumas išlieka per amžius;'),
  (@b13, 16, 42, 'ir su jais Hemaną ir Jedutūną su trimitais bei cimbolais tiems, kurie skambins, ir su Dievo muzikiniais instrumentais. O Jedutūno sūnūs buvo durininkai.'),
  (@b13, 16, 43, 'Ir visa tauta išėjo, kiekvienas į savo namus; o Dovydas sugrįžo savo namų palaiminti.'),
  (@b13, 17, 1, 'Na, o Dovydui sėdint savo namuose įvyko, kad Dovydas tarė pranašui Natanui: „Štai aš gyvenu kedro namuose, bet VIEŠPATIES Sandoros skrynia pasilieka po uždangalais“.'),
  (@b13, 17, 2, 'Tada Natanas tarė Dovydui: „Daryk viską, kas tavo širdyje; nes Dievas yra su tavimi“.'),
  (@b13, 17, 3, 'Ir tą pačią naktį atsitiko, kad Natanui atėjo Dievo žodis, sakydamas:'),
  (@b13, 17, 4, '„Eik ir sakyk mano tarnui Dovydui: ‘Taip sako VIEŠPATS: Tu man nestatysi namų juose gyventi;'),
  (@b13, 17, 5, 'nes aš negyvenau namuose nuo tos dienos, kai išvedžiau aukštyn Izraelį, iki šios dienos; bet ėjau iš palapinės į palapinę ir iš vienos padangtės į kitą.'),
  (@b13, 17, 6, 'Ar aš, kur tik bevaikščiojau su visu Izraeliu, kalbėjau žodį kuriam nors iš Izraelio teisėjų, kuriems įsakiau ganyti mano tautą, sakydamas: „Kodėl man nepastatėte kedro namų?“’'),
  (@b13, 17, 7, 'Taigi dabar taip sakyk mano tarnui Dovydui: ‘Taip sako kariuomenių VIEŠPATS: Aš tave paėmiau iš avidės, nuo sekimo paskui avis, kad būtum mano tautos Izraelio valdovas;'),
  (@b13, 17, 8, 'ir buvau su tavimi visur, kur tu vaikščiojai, ir iškirtau visus tavo priešus tau iš akivaizdos, ir padariau tau vardą, kaip žemėje esančių didžiūnų vardą.'),
  (@b13, 17, 9, 'Taip pat aš paskirsiu vietą savo tautai Izraeliui ir juos įsodinsiu, ir jie gyvens savo vietoje ir nebebus judinami; taip pat nedorybės vaikai jų nebeniokos, kaip pradžioje'),
  (@b13, 17, 10, 'ir nuo to laiko, kai įsakiau teisėjams valdyti mano tautą Izraelį. Be to, aš pavergsiu visus tavo priešus. Dar aš tau sakau, kad VIEŠPATS tau pastatys namus.'),
  (@b13, 17, 11, 'Ir įvyks, kai pasibaigs tavo dienos, kad turėsi išeiti ir būti su savo tėvais, tada aš iškelsiu po tavęs tavo sėklą, kuri bus iš tavo sūnų; ir aš įtvirtinsiu jo karalystę.'),
  (@b13, 17, 12, 'Jis pastatys man namus, ir aš įtvirtinsiu jo sostą amžiams.'),
  (@b13, 17, 13, 'Aš būsiu jam tėvas, o jis bus man sūnus; ir savo gailestingumo neatimsiu nuo jo, kaip atėmiau nuo to, kuris buvo pirma tavęs;'),
  (@b13, 17, 14, 'bet jį įstatysiu savo namuose ir savo karalystėje amžiams; ir jo sostas bus įtvirtintas amžiams’“.'),
  (@b13, 17, 15, 'Pagal visus šituos žodžius ir pagal visą šitą regėjimą Natanas taip kalbėjo Dovydui.'),
  (@b13, 17, 16, 'Ir karalius Dovydas, atėjęs ir atsisėdęs VIEŠPATIES akivaizdoje, tarė: „Kas aš esu, o VIEŠPATIE Dieve, ir kas yra mano namai, kad mane iki čia atvedei?'),
  (@b13, 17, 17, 'Tačiau tai buvo mažas dalykas tavo akyse, o Dieve; nes tu dar kalbėjai apie savo tarno namus tolimoje ateityje ir atsižvelgei į mane kaip į aukštos kilmės žmogų, o VIEŠPATIE Dieve.'),
  (@b13, 17, 18, 'Ką gi daugiau Dovydas begali kalbėti dėl tavo tarno garbės? Nes tu pažįsti savo tarną.'),
  (@b13, 17, 19, 'O VIEŠPATIE, dėl savo tarno ir pagal savo paties širdį tu padarei visą šitą didybę, duodamas žinoti visus šituos didžius dalykus.'),
  (@b13, 17, 20, 'O VIEŠPATIE, nėra nei vieno tau lygaus ir nėra jokio Dievo šalia tavęs, pagal visa tai, ką girdėjome savo ausimis.'),
  (@b13, 17, 21, 'Ir kuri gi kita tokia tauta žemėje, kaip tavo tauta Izraelis, kurios Dievas ėjo atpirkti, kad būtų jo tauta, kad padarytų sau didybės ir baisumo vardą, išvarydamas tautas iš akivaizdos savo tautos, kurią atpirkai iš Egipto?'),
  (@b13, 17, 22, 'Nes savo tautą Izraelį tu padarei savo paties tauta amžiams; ir tu, o VIEŠPATIE, tapai jų Dievu.'),
  (@b13, 17, 23, 'Taigi dabar, VIEŠPATIE, tegul tas dalykas, kurį kalbėjai apie savo tarną ir apie jo namus, būna įtvirtintas amžiams, ir padaryk, kaip kalbėjai.'),
  (@b13, 17, 24, 'Tebūna tai įtvirtinta, kad tavo vardas būtų išaukštintas per amžius, sakant: ‘Kariuomenių VIEŠPATS yra Izraelio Dievas, būtent Dievas Izraeliui’; ir tegul tavo tarno Dovydo namai būna įtvirtinti tavo akivaizdoje.'),
  (@b13, 17, 25, 'Nes tu, o mano Dieve, pasakei savo tarnui, kad jam pastatysi namus; todėl tavo tarnas rado savo širdyje, kad melstųsi tavo akivaizdoje.'),
  (@b13, 17, 26, 'O dabar, VIEŠPATIE, tu esi Dievas ir pažadėjai savo tarnui tą gerumą;'),
  (@b13, 17, 27, 'taigi dabar teikis palaiminti savo tarno namus, kad jie amžinai būtų tavo akivaizdoje; nes tu, o VIEŠPATIE, palaimini, ir tai bus palaiminta per amžius“.'),
  (@b13, 18, 1, 'Na, o po to įvyko, kad Dovydas sumušė filistinus, pavergė juos ir atėmė iš filistinų rankos Gatą ir jo miestus.'),
  (@b13, 18, 2, 'Ir jis sumušė Moabą; ir moabiečiai tapo Dovydo tarnais ir nešdavo dovanas.'),
  (@b13, 18, 3, 'Ir Dovydas sumušė Cobos karalių Hadarezerą iki Hamato, kai jis ėjo savo valdžios įtvirtinti prie Eufrato upės.'),
  (@b13, 18, 4, 'Ir Dovydas atėmė iš jo tūkstantį vežimų, septynis tūkstančius raitelių ir dvidešimt tūkstančių pėstininkų; Dovydas taip pat pakirto visiems vežimų žirgams kojų gyslas, bet iš jų pasiliko šimtą vežimų.'),
  (@b13, 18, 5, 'O kai Damasko sirai atėjo į pagalbą Cobos karaliui Hadadezerui, Dovydas išžudė iš sirų dvidešimt du tūkstančius.'),
  (@b13, 18, 6, 'Tada Dovydas pastatė įgulas Sirijos Damaske; ir sirai tapo Dovydo tarnais, ir nešė dovanas. Taip VIEŠPATS saugojo Dovydą visur, kur jis ėjo.'),
  (@b13, 18, 7, 'Ir Dovydas paėmė aukso skydus, esančius ant Hadadezero tarnų, ir juos atgabeno į Jeruzalę.'),
  (@b13, 18, 8, 'Taip pat iš Tibhato ir iš Kūno, Hadadezero miestų, Dovydas pargabeno labai daug žalvario, iš kurio Saliamonas padarė žalvarinę jūrą, stulpus ir žalvario indus.'),
  (@b13, 18, 9, 'Na, o Hamato karalius Tojus, išgirdęs, kad Dovydas sumušė visą Cobos karaliaus Hadadezero kariuomenę,'),
  (@b13, 18, 10, 'siuntė savo sūnų Hadoramą su visokiais aukso, sidabro ir žalvario indais pas karalių Dovydą pasiteirauti apie jo gerovę ir jį pasveikinti, kadangi jis kovojo prieš Hadadezerą ir jį sumušė (nes Hadadezeras kariavo su Tojumi).'),
  (@b13, 18, 11, 'Taip pat ir juos karalius Dovydas pašventė VIEŠPAČIUI drauge su sidabru ir auksu, kuriuos jis parsigabeno iš visų šitų tautų: iš Edomo, iš Moabo, iš Amono vaikų, iš filistinų ir iš Amaleko.'),
  (@b13, 18, 12, 'Be to, Cerujos sūnus Abišajas išžudė iš edomiečių Druskos slėnyje aštuoniolika tūkstančių.'),
  (@b13, 18, 13, 'Ir jis pastatė Edome įgulas; ir visi edomiečiai tapo Dovydo tarnais. Taip VIEŠPATS saugojo Dovydą visur, kur jis ėjo.'),
  (@b13, 18, 14, 'Taip Dovydas karaliavo visam Izraeliui ir vykdė teismą bei teisingumą visos savo tautos tarpe.'),
  (@b13, 18, 15, 'Cerujos sūnus Joabas buvo kariuomenės vadas; o Ahiludo sūnus Jehozapatas – metraštininkas.'),
  (@b13, 18, 16, 'O Ahitubo sūnus Cadokas ir Abjataro sūnus Abimelechas buvo kunigai; o Šavša buvo raštininkas;'),
  (@b13, 18, 17, 'o Jehojados sūnus Benaja buvo keretų ir peletų viršininkas; o Dovydo sūnūs buvo vyriausieji prie karaliaus.'),
  (@b13, 19, 1, 'Na, o po to įvyko, kad mirė Amono vaikų karalius Nahašas, ir jo sūnus karaliavo jo vietoje.'),
  (@b13, 19, 2, 'Ir Dovydas tarė: „Aš parodysiu gerumą Nahašo sūnui Hanūnui, nes jo tėvas man parodė gerumą“. Ir Dovydas siuntė pasiuntinius jo paguosti dėl jo tėvo. Taigi Dovydo tarnai atvyko į Amono vaikų šalį pas Hanūną jo paguosti.'),
  (@b13, 19, 3, 'Bet Amono vaikų kunigaikščiai tarė Hanūnui: „Ar manai, kad Dovydas gerbia tavo tėvą, kad tau atsiuntė guodėjus? Argi ne tam, kad ištirtų, sunaikintų ir išžvalgytų šalį, jo tarnai atvyko pas tave?“'),
  (@b13, 19, 4, 'Todėl Hanūnas, paėmęs Dovydo tarnus, nuskuto juos ir atkirpo jų drabužius pusiau prie jų sėdmenų, ir juos paleido.'),
  (@b13, 19, 5, 'Tada vieni nuėjo ir Dovydui pranešė, kaip su tais vyrais pasielgta. Ir jis siuntė jų pasitikti; nes tie vyrai buvo labai sugėdinti. Ir karalius tarė: „Pasilikite Jeriche, kol ataugs jūsų barzdos, ir tada sugrįžkite“.'),
  (@b13, 19, 6, 'O kai Amono vaikai pamatė, kad jie tapo Dovydui nekenčiami, Hanūnas ir Amono vaikai siuntė tūkstantį talentų sidabro, kad pasisamdytų iš Mesopotamijos, iš Sirija-Maakos ir iš Cobos vežimų ir raitelių.'),
  (@b13, 19, 7, 'Taip jie pasisamdė trisdešimt du tūkstančius vežimų ir Maakos karalių bei jo tautą; kurie atėję stovyklavo prieš Medebą. O Amono vaikai, susirinkę iš savo miestų, atėjo į mūšį.'),
  (@b13, 19, 8, 'Tai išgirdęs, Dovydas pasiuntė Joabą ir visą galiūnų kariuomenę.'),
  (@b13, 19, 9, 'Ir Amono vaikai išėjo ir išsirikiavo mūšiui prieš miesto vartus; o karaliai, kurie buvo atėję, buvo atskirai ant lauko.'),
  (@b13, 19, 10, 'Na, o Joabas, pamatęs, kad mūšis buvo nukreiptas prieš jį iš priekio ir iš užnugario, išrinko iš visų Izraelio rinktinių ir išrikiavo juos prieš sirus.'),
  (@b13, 19, 11, 'O likusią tautą jis atidavė savo broliui Abišajui į rankas, ir jie išsirikiavo prieš Amono vaikus.'),
  (@b13, 19, 12, 'Ir jis tarė: „Jei sirai bus man per stiprūs, tada tu man pagelbėsi; bet jei Amono vaikai bus tau per stiprūs, tada aš tau pagelbėsiu.'),
  (@b13, 19, 13, 'Būk drąsus ir narsiai elkimės už savo tautą ir už mūsų Dievo miestus; o VIEŠPATS tegul daro tai, kas yra gera jo akyse“.'),
  (@b13, 19, 14, 'Taigi Joabas ir su juo esanti tauta artėjo į mūšį prieš sirus; o jie bėgo jo akivaizdoje.'),
  (@b13, 19, 15, 'Kai tik Amono vaikai pamatė, kad sirai pabėgo, jie irgi bėgo jo brolio Abišajo akivaizdoje ir įėjo į miestą. Tada Joabas atėjo į Jeruzalę.'),
  (@b13, 19, 16, 'O sirai, pamatę, kad jie Izraelio akivaizdoje nugalėti, siuntė pasiuntinius ir išvedė sirus, esančius anapus upės; o Hadadezero kariuomenės vadas Šofachas ėjo jų priešakyje.'),
  (@b13, 19, 17, 'Ir tai buvo pranešta Dovydui; ir jis, surinkęs visą Izraelį, perėjo per Jordaną, atėjo pas juos ir išsirikiavo mūšiui prieš juos. Taigi kai Dovydas išsirikiavo mūšiui prieš sirus, jie kovojo su juo.'),
  (@b13, 19, 18, 'Bet sirai bėgo Izraelio akivaizdoje; ir Dovydas išžudė iš sirų septynis tūkstančius vyrų, kovojančių vežimuose, ir keturiasdešimt tūkstančių pėstininkų, ir nužudė kariuomenės vadą Šofachą.'),
  (@b13, 19, 19, 'O Hadadezero tarnai pamatę, kad jie Izraelio akivaizdoje nugalėti, sudarė taiką su Dovydu ir tapo jo tarnais; ir sirai daugiau nebenorėjo padėti Amono vaikams.'),
  (@b13, 20, 1, 'Ir metams pasibaigus, tuo laiku, kai karaliai išeina į mūšį, atsitiko, kad Joabas išsivedęs kariuomenės galybę nusiaubė Amono vaikų šalį ir atėjęs apgulė Rabą. Bet Dovydas pasiliko Jeruzalėje. Ir Joabas sumušė Rabą ir ją sunaikino.'),
  (@b13, 20, 2, 'Ir Dovydas nuėmė jų karaliui karūną nuo jo galvos ir rado ją sveriant talentą aukso, ir joje buvo brangakmeniai; ir ji buvo uždėta Dovydui ant galvos; taip pat jis išgabeno iš miesto be galo daug grobio.'),
  (@b13, 20, 3, 'O jame buvusią liaudį jis išvedęs supjaustė su pjūklais, geležinėmis akėčiomis ir kirviais. Taip Dovydas pasielgė su visais Amono vaikų miestais. Ir Dovydas su visa tauta sugrįžo į Jeruzalę.'),
  (@b13, 20, 4, 'O po to įvyko, kad Gezere kilo karas su filistinais; tuo metu hušietis Šibechajas užmušė Sipają, buvusį iš milžinų vaikų; ir jie buvo pavergti.'),
  (@b13, 20, 5, 'Ir vėl buvo karas su filistinais; o Jayro sūnus Elhananas užmušė Lahmį, gatiečio Galijoto brolį, kurio ieties kotas buvo kaip audėjo riestuvas.'),
  (@b13, 20, 6, 'Ir dar kartą buvo karas Gate, kur buvo aukštaūgis vyras, kurio rankų ir kojų pirštų buvo dvidešimt keturi, po šešis ant kiekvienos rankos ir po šešis ant kiekvienos kojos; jis irgi buvo milžino sūnus.'),
  (@b13, 20, 7, 'Bet kai jis metė iššūkį Izraeliui, jį užmušė Jonatanas, Dovydo brolio Šimos sūnus.'),
  (@b13, 20, 8, 'Šitie buvo gimę milžinui Gate; ir jie krito nuo Dovydo rankos bei jo tarnų rankos.'),
  (@b13, 21, 1, 'Ir šėtonas pakilo prieš Izraelį ir sukurstė Dovydą suskaičiuoti Izraelį.'),
  (@b13, 21, 2, 'Ir Dovydas tarė Joabui ir tautos valdovams: „Eikite, suskaičiuokite Izraelį nuo Beer-Šebos iki Dano; ir atneškite man jų skaičių, kad aš jį žinočiau.'),
  (@b13, 21, 3, 'O Joabas atsakė: „VIEŠPATS tepadaugina savo tautą šimtą kartų tiek, kiek jų yra; bet, mano viešpatie karaliau, argi jie visi nėra mano viešpaties tarnai? Tai kodėl mano viešpats to reikalauja? Kodėl jis nori būti Izraeliui nusižengimo priežastimi?“'),
  (@b13, 21, 4, 'Tačiau karaliaus žodis nugalėjo Joabą. Todėl Joabas išėjęs perėjo visą Izraelį ir atėjo į Jeruzalę.'),
  (@b13, 21, 5, 'Ir Joabas pateikė Dovydui tautos skaičiaus sumą. Ir visų iš Izraelio buvo tūkstantis tūkstančių ir šimtas tūkstančių vyrų, traukiančių kalaviją; o Judos buvo keturi šimtai septyniasdešimt tūkstančių vyrų, traukiančių kalaviją.'),
  (@b13, 21, 6, 'Bet Levio ir Benjamino jis neskaičiavo tarp jų; nes karaliaus žodis buvo pasibjaurėtinas Joabui.'),
  (@b13, 21, 7, 'Ir Dievui nepatiko tas dalykas; todėl jis ištiko Izraelį.'),
  (@b13, 21, 8, 'Ir Dovydas tarė Dievui: „Labai nusidėjau, kadangi padariau šitą dalyką; bet dabar, meldžiu tave, panaikink savo tarno neteisybę; nes labai kvailai pasielgiau“.'),
  (@b13, 21, 9, 'Ir VIEŠPATS kalbėjo Gadui, Dovydo regėtojui, sakydamas:'),
  (@b13, 21, 10, '„Eik ir kalbėk Dovydui, sakydamas: ‘Taip sako VIEŠPATS: Tris dalykus tau siūlau; pasirink vieną iš jų, kad tau jį padaryčiau’“.'),
  (@b13, 21, 11, 'Taigi Gadas, atėjęs pas Dovydą, jam tarė: „Taip sako VIEŠPATS: ‘Pasirink'),
  (@b13, 21, 12, 'arba trejetą bado metų; arba trejetą mėnesių būti naikinamu savo priešininkų akivaizdoje, kai tavo priešų kalavijas tave pasivys; arba trejetą dienų VIEŠPATIES kalavijo, tai yra maro, šalyje ir VIEŠPATIES angelą, naikinantį visose Izraelio ribose. Taigi dabar pasitark, kokią žinią turiu parnešti tam, kuris mane siuntė“.'),
  (@b13, 21, 13, 'Ir Dovydas tarė Gadui: „Esu labai suspaustas; tepulsiu į VIEŠPATIES rankas; nes labai dideli jo gailestingumai; bet į žmonių rankas tenepulsiu“.'),
  (@b13, 21, 14, 'Taigi VIEŠPATS siuntė ant Izraelio marą; ir krito iš Izraelio septyniasdešimt tūkstančių žmonių.'),
  (@b13, 21, 15, 'Ir Dievas pasiuntė angelą į Jeruzalę, jos sunaikinti; o jam benaikinant, VIEŠPATS pažvelgė ir gailėjosi dėl to pikto, ir tarė naikinančiam angelui: „Gana, dabar sustabdyk savo ranką“. O VIEŠPATIES angelas stovėjo prie jebusiečio Ornano klojimo.'),
  (@b13, 21, 16, 'Ir Dovydas, pakėlęs savo akis, pamatė VIEŠPATIES angelą, stovintį tarp žemės ir dangaus, turintį savo rankoje ištrauktą kalaviją, ištiestą virš Jeruzalės. Tada Dovydas ir Izraelio vyresnieji, apsivilkę ašutinėmis, parpuolė veidais žemyn.'),
  (@b13, 21, 17, 'Ir Dovydas tarė Dievui: „Argi ne aš įsakiau suskaičiuoti tautą? Aš esu tas, kuris nusidėjau ir tikrai padariau pikta; bet šitos avys – ką jos padarė? O VIEŠPATIE, mano Dieve, meldžiu tave, tavo ranka tebūna ant manęs ir ant mano tėvo namų; bet ne ant tavo tautos, kad ji būtų ištikta rykšte“.'),
  (@b13, 21, 18, 'Tada VIEŠPATIES angelas paliepė Gadui, kad pasakytų Dovydui, kad Dovydas turi eiti aukštyn ir pastatyti aukurą VIEŠPAČIUI jebusiečio Ornano klojime.'),
  (@b13, 21, 19, 'Ir Dovydas ėjo aukštyn pagal Gado pasakymą, kurį jis kalbėjo VIEŠPATIES vardu.'),
  (@b13, 21, 20, 'Ir Ornanas atsisuko ir pamatė angelą; o jo keturi sūnūs, esantys su juo, pasislėpė. Na, o Ornanas kūlė kviečius.'),
  (@b13, 21, 21, 'Ir Dovydui atėjus pas Ornaną, Ornanas pažvelgė ir pamatė Dovydą, ir išėjo iš klojimo, ir nusilenkė Dovydui veidu iki žemės.'),
  (@b13, 21, 22, 'Tada Dovydas tarė Ornanui: „Duok man vietos iš šio klojimo, kad joje pastatyčiau aukurą VIEŠPAČIUI; duok man ją už pilną kainą; kad rykštė liautųsi nuo tautos“.'),
  (@b13, 21, 23, 'O Ornanas tarė Dovydui: „Pasiimk ją, ir mano viešpats karalius tedaro, kas gera jo akyse; štai duodu tau ir jaučių deginamosioms atnašoms, kuliamuosius įrankius malkoms ir kviečių dėl maisto atnašos; visa tai duodu“.'),
  (@b13, 21, 24, 'Ir karalius Dovydas tarė Ornanui: „Ne; aš tikrai noriu pirkti tai už pilną kainą; nes aš neimsiu VIEŠPAČIUI to, kas tavo, nei neatnašausiu deginamųjų atnašų, kurios nieko nekainuoja“.'),
  (@b13, 21, 25, 'Taigi Dovydas davė Ornanui už tą vietą šešis šimtus aukso šekelių pagal svorį.'),
  (@b13, 21, 26, 'Ir Dovydas ten pastatė aukurą VIEŠPAČIUI ir atnašavo deginamąsias atnašas bei taikos atnašas, ir šaukėsi VIEŠPATIES; ir jis jam atsakė iš dangaus ugnimi ant deginamosios atnašos aukuro.'),
  (@b13, 21, 27, 'Ir VIEŠPATS įsakė angelui; ir jis įkišo savo kalaviją atgal į jo makštį.'),
  (@b13, 21, 28, 'Tuo metu, kai Dovydas pamatė, kad VIEŠPATS jam atsakė jebusiečio Ornano klojime, jis ten aukojo.'),
  (@b13, 21, 29, 'Nes VIEŠPATIES padangtė, kurią Mozė padarė dykumoje, ir deginamosios atnašos aukuras tuo laikotarpiu buvo Gibeono aukštumoje.'),
  (@b13, 21, 30, 'Bet Dovydas negalėjo eiti priešais tą Dievo pasiklausti; nes jis išsigando dėl VIEŠPATIES angelo kalavijo.'),
  (@b13, 22, 1, 'Tada Dovydas tarė: „Čia VIEŠPATIES Dievo namai ir čia Izraelio deginamosios atnašos aukuras“.'),
  (@b13, 22, 2, 'Ir Dovydas įsakė surinkti ateivius, esančius Izraelio šalyje; ir jis paskyrė akmentašius, kad nutašytų apdorotų akmenų Dievo namams statyti.'),
  (@b13, 22, 3, 'Ir Dovydas paruošė gausiai geležies vartų durų vinims bei sujungimams; ir žalvario gausybę – be svorio;'),
  (@b13, 22, 4, 'taip pat kedro medžių gausybę; nes sidoniečiai ir tie, iš Tyro, atgabeno Dovydui daugybę kedro medienos.'),
  (@b13, 22, 5, 'Ir Dovydas tarė: „Mano sūnus Saliamonas yra jaunas ir gležnas, o namai, kurie turės būti pastatyti VIEŠPAČIUI, turi būti nepaprastai didingi garsumu ir šlove visose šalyse; todėl aš dabar jiems paruošiu“. Taigi Dovydas prieš savo mirtį gausiai paruošė.'),
  (@b13, 22, 6, 'Tada jis pašaukė savo sūnų Saliamoną ir jį įpareigojo statyti namus VIEŠPAČIUI, Izraelio Dievui.'),
  (@b13, 22, 7, 'Ir Dovydas tarė Saliamonui: „Mano sūnau, aš pats buvau sumanęs statyti namus VIEŠPATIES, savo Dievo, vardui;'),
  (@b13, 22, 8, 'bet man atėjo VIEŠPATIES žodis, sakydamas: ‘Tu išliejai gausiai kraujo ir kariavai didelius karus; tu nestatysi namų mano vardui, nes daug kraujo išliejai žemėje mano akivaizdoje.'),
  (@b13, 22, 9, 'Štai tau gims sūnus, kuris bus poilsio vyras; ir aš jam duosiu poilsį nuo visų jo aplinkinių priešų; nes jo vardas bus Saliamonas, ir jo dienomis suteiksiu tylą ir ramybę Izraeliui.'),
  (@b13, 22, 10, 'Jis pastatys namus mano vardui; ir jis bus mano sūnus, o aš būsiu jo tėvas; ir aš amžiams įtvirtinsiu jo karalystės sostą Izraeliui valdyti’.'),
  (@b13, 22, 11, 'Dabar, mano sūnau, VIEŠPATS tebūna su tavimi; klestėk ir pastatyk VIEŠPATIES, tavo Dievo, namus, kaip jis kalbėjo apie tave.'),
  (@b13, 22, 12, 'Tik VIEŠPATS tau teduoda išmintį ir supratimą ir teįpareigoja tave dėl Izraelio, kad laikytumeisi VIEŠPATIES, savo Dievo, įstatymo.'),
  (@b13, 22, 13, 'Tada tu klestėsi, jei būsi atidus, kad vykdytum įstatus ir teismus, kuriais VIEŠPATS įpareigojo Mozę dėl Izraelio: būk stiprus ir drąsus; nebijok ir nebūk sunerimęs.'),
  (@b13, 22, 14, 'Dabar štai, savo varge aš paruošiau VIEŠPATIES namams šimtą tūkstančių talentų aukso ir tūkstantį tūkstančių talentų sidabro; o žalvario ir geležies – be svorio; nes jo yra gausybė; taip pat paruošiau rąstų ir akmenų; o tu prie jų galėsi pridėti.'),
  (@b13, 22, 15, 'Be to, pas tave yra gausybė darbininkų: tašytojų ir akmens bei medienos apdirbėjų, ir visokių sumanių vyrų visokiam darbui.'),
  (@b13, 22, 16, 'Aukso, sidabro, žalvario ir geležies yra be skaičiaus. Taigi kelkis ir darbuokis, ir VIEŠPATS bus su tavimi“.'),
  (@b13, 22, 17, 'Taip pat Dovydas įsakė visiems Izraelio kunigaikščiams, kad padėtų jo sūnui Saliamonui, sakydamas:'),
  (@b13, 22, 18, '„Argi VIEŠPATS, jūsų Dievas, nėra su jumis ir argi jis nesuteikė jums ramybės iš visų pusių? Nes jis davė į mano rankas šalies gyventojus; ir šalis pavergta VIEŠPATIES akivaizdoje ir jo tautos akivaizdoje.'),
  (@b13, 22, 19, 'Dabar nukreipkite savo širdį ir savo sielą ieškoti VIEŠPATIES, savo Dievo; taigi kelkitės ir statykite VIEŠPATIES Dievo šventovę, kad atneštumėte VIEŠPATIES Sandoros skrynią ir Dievo šventuosius indus į namus, kurie turės būti pastatyti VIEŠPATIES vardui“.'),
  (@b13, 23, 1, 'Taigi kai Dovydas buvo pasenęs ir pasisotinęs dienomis, jis paskyrė savo sūnų Saliamoną Izraelio karaliumi.'),
  (@b13, 23, 2, 'Ir jis surinko visus Izraelio kunigaikščius su kunigais ir levitais.'),
  (@b13, 23, 3, 'Na, o levitai buvo suskaičiuoti nuo trisdešimties metų ir vyresni; ir jų skaičius pagal jų vyrų galvas buvo trisdešimt aštuoni tūkstančiai.'),
  (@b13, 23, 4, 'Iš kurių dvidešimt keturi tūkstančiai buvo, kad pastumėtų į priekį VIEŠPATIES namų darbą; o šeši tūkstančiai buvo pareigūnai ir teisėjai;'),
  (@b13, 23, 5, 'be to, keturi tūkstančiai buvo durininkai; o keturi tūkstančiai gyrė VIEŠPATĮ instrumentais, kuriuos padariau, sakė Dovydas, kad jais būtų giriama.'),
  (@b13, 23, 6, 'Ir Dovydas juos padalino skyriais tarp Levio sūnų, tai yra Geršono, Kehato ir Merario.'),
  (@b13, 23, 7, 'Iš geršonų buvo Ladanas ir Šimis.'),
  (@b13, 23, 8, 'Ladano sūnūs: vyriausiasis Jehielis, Zetamas ir Joelis – trys.'),
  (@b13, 23, 9, 'Šimio sūnūs: Šelomitas, Hazielis ir Haranas – trys. Šitie buvo Ladano tėvų vyriausieji.'),
  (@b13, 23, 10, 'O Šimio sūnūs: Jahatas, Zina, Jeušas ir Berija. Šitie keturi buvo Šimio sūnūs.'),
  (@b13, 23, 11, 'O Jahatas buvo vyriausiasis, o Ziza antrasis; bet Jeušas ir Berija neturėjo daug sūnų; todėl jie buvo viename skaičiuje, pagal jų tėvų namus.'),
  (@b13, 23, 12, 'Kehato sūnūs: Amramas, Iccharas, Hebronas ir Uzielis – keturi.'),
  (@b13, 23, 13, 'Amramo sūnūs: Aaronas ir Mozė; o Aaronas buvo atskirtas, kad jis ir jo sūnūs per amžius pašvęstų švenčiausius dalykus, kad degintų smilkalus VIEŠPATIES akivaizdoje, kad jam tarnautų ir laimintų jo vardu per amžius.'),
  (@b13, 23, 14, 'Na, o dėl Dievo vyro Mozės, jo sūnūs buvo vadinami iš Levio genties.'),
  (@b13, 23, 15, 'Mozės sūnūs: Geršomas ir Eliezeras.'),
  (@b13, 23, 16, 'Iš Geršomo sūnų Šebuelis buvo vyriausiasis.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b13, 23, 17, 'O Eliezero sūnūs buvo: Rehabija, vyriausiasis. Eliezeras neturėjo kitų sūnų; bet Rehabijos sūnų buvo labai daug.'),
  (@b13, 23, 18, 'Iš Iccharo sūnų: Šelomitas, vyriausiasis.'),
  (@b13, 23, 19, 'Iš Hebrono sūnų: pirmasis Jerija, antrasis Amarija, trečiasis Jahazielis ir ketvirtasis Jekamamas.'),
  (@b13, 23, 20, 'Iš Uzielio sūnų: pirmasis Micha, o antrasis Išija.'),
  (@b13, 23, 21, 'Merario sūnūs: Machlis ir Mušis. Machlio sūnūs: Eleazaras ir Kišas.'),
  (@b13, 23, 22, 'O Eleazaras mirė neturėdamas sūnų, tik dukteris; ir jas ėmė Kišo sūnūs, jų broliai.'),
  (@b13, 23, 23, 'Mušio sūnūs: Machlis, Ederas ir Jeremotas – trys.'),
  (@b13, 23, 24, 'Šitie buvo Levio sūnūs pagal jų tėvų namus; būtent tėvų vyriausieji, suskaičiuoti pagal vardų skaičių, pagal jų galvas, kurie atlikinėjo VIEŠPATIES namų tarnybos darbą, nuo dvidešimties metų ir vyresni.'),
  (@b13, 23, 25, 'Nes Dovydas pasakė: „VIEŠPATS, Izraelio Dievas, suteikė poilsį savo tautai, kad jie gyventų Jeruzalėje per amžius;'),
  (@b13, 23, 26, 'taip pat ir levitams; jie nebenešios nei padangtės, nei jokių jos indų jos tarnavimui.'),
  (@b13, 23, 27, 'Nes paskutiniais Dovydo žodžiais levitai buvo suskaičiuoti nuo dvidešimties metų amžiaus ir vyresni;'),
  (@b13, 23, 28, 'kadangi jų tarnystė buvo patarnauti Aarono sūnums dėl VIEŠPATIES namų tarnavimo kiemuose, kambariuose, visų šventų daiktų apvalyme ir dėl Dievo namų tarnavimo darbo;'),
  (@b13, 23, 29, 'dėl parodomosios duonos, dėl smulkių miltų maisto atnašai, dėl neraugintų pyragų, dėl to, kas kepama keptuvėje, dėl kepinių, dėl visokių matų ir dydžių;'),
  (@b13, 23, 30, 'ir kas rytą stotis dėkoti ir girti VIEŠPATĮ, ir taip pat vakare;'),
  (@b13, 23, 31, 'ir atnašauti visas deginamąsias aukas VIEŠPAČIUI per sabatus, jauną mėnulį, nustatytomis šventėmis, pagal skaičių, pagal jiems įsakytą tvarką, nuolat VIEŠPATIES akivaizdoje;'),
  (@b13, 23, 32, 'ir kad jie laikytųsi susirinkimo padangtės pareigų, šventosios vietos pareigų ir jų brolių, Aarono sūnų, pareigų VIEŠPATIES namų tarnavime“.'),
  (@b13, 24, 1, 'Na, o šitie yra Aarono sūnų padalijimai: Aarono sūnūs: Nadabas ir Abihuvas, Eleazaras ir Itamaras.'),
  (@b13, 24, 2, 'Bet Nadabas ir Abihuvas mirė pirma savo tėvo ir neturėjo vaikų; todėl kunigų tarnystę vykdė Eleazaras ir Itamaras.'),
  (@b13, 24, 3, 'Dovydas juos paskirstė, Cadoką iš Eleazaro sūnų ir Ahimelechą iš Itamaro sūnų, pagal jų tarnystes jų tarnavime.'),
  (@b13, 24, 4, 'O vyriausiųjų iš Eleazaro sūnų atsirado daugiau negu iš Itamaro sūnų; ir taip jie buvo padalinti. Tarp Eleazaro sūnų buvo šešiolika vyriausiųjų iš jų tėvų namų, o tarp Itamaro sūnų, pagal jų tėvų namus, aštuoni.'),
  (@b13, 24, 5, 'Taip jie buvo padalinti burtais, vieni ir kiti; nes šventovės valdytojai ir Dievo namų valdytojai buvo iš Eleazaro sūnų ir iš Itamaro sūnų.'),
  (@b13, 24, 6, 'O Netanelio sūnus Šemaja, raštininkas, vienas iš levitų, juos surašė karaliaus, kunigaikščių, kunigo Cadoko, Abjataro sūnaus Ahimelecho ir kunigų bei levitų vyriausiųjų tėvų akivaizdoje: vieni pagrindiniai namai buvo paimti Eleazarui ir vieni paimti Itamarui.'),
  (@b13, 24, 7, 'Na, o pirmasis burtas išpuolė Jehojaribui, antrasis Jedajai,'),
  (@b13, 24, 8, 'trečiasis Harimui, ketvirtasis Seorimui,'),
  (@b13, 24, 9, 'penktasis Malkijai, šeštasis Mijaminui,'),
  (@b13, 24, 10, 'septintasis Hakocui, aštuntasis Abijai,'),
  (@b13, 24, 11, 'devintasis Ješūvai, dešimtasis Šechanijai,'),
  (@b13, 24, 12, 'vienuoliktasis Eljašibui, dvyliktasis Jakimui,'),
  (@b13, 24, 13, 'tryliktasis Hupai, keturioliktasis Ješebabui,'),
  (@b13, 24, 14, 'penkioliktasis Bilgai, šešioliktasis Imerui,'),
  (@b13, 24, 15, 'septynioliktasis Hezyrui, aštuonioliktasis Afsesui,'),
  (@b13, 24, 16, 'devynioliktasis Petahijai, dvidešimtasis Jechezekeliui,'),
  (@b13, 24, 17, 'dvidešimt pirmasis Jachinui, dvidešimt antrasis Gamului,'),
  (@b13, 24, 18, 'dvidešimt trečiasis Delajai, dvidešimt ketvirtasis Maazijui.'),
  (@b13, 24, 19, 'Šita jų tvarka jų tarnavime ateiti į VIEŠPATIES namus pagal jų būdą, valdžioje jų tėvo Aarono, kaip jam buvo įsakęs VIEŠPATS, Izraelio Dievas.'),
  (@b13, 24, 20, 'O likusieji Levio sūnūs buvo šie: iš Amramo sūnų: Šubaelis; iš Šubaelio sūnų: Jechdija.'),
  (@b13, 24, 21, 'Dėl Rehabijo; iš Rehabijo sūnų: pirmasis buvo Išijas.'),
  (@b13, 24, 22, 'Iš iccharų: Šelomotas; iš Šelomoto sūnų: Jahatas.'),
  (@b13, 24, 23, 'O Hebrono sūnūs: pirmasis Jerijas, antrasis Amarijas, trečiasis Jahazielis, ketvirtasis Jekamamas.'),
  (@b13, 24, 24, 'Iš Uzielio sūnų: Micha; iš Michos sūnų: Šamyras.'),
  (@b13, 24, 25, 'Michos brolis buvo Išija; iš Išijos sūnų: Zacharija.'),
  (@b13, 24, 26, 'Merario sūnūs buvo Machlis ir Mušis; Jaazijo sūnūs: Benojas.'),
  (@b13, 24, 27, 'Merario sūnūs iš Jaazijo: Benojas, Šohamas, Zakūras ir Ibris.'),
  (@b13, 24, 28, 'Iš Machlio kilo Eleazaras, kuris neturėjo sūnų.'),
  (@b13, 24, 29, 'Dėl Kišo; Kišo sūnus buvo Jerachmeelis.'),
  (@b13, 24, 30, 'Mušio sūnūs: Machlis, Ederas ir Jerimotas. Šitie buvo levitų sūnūs pagal jų tėvų namus.'),
  (@b13, 24, 31, 'Šitie taip pat metė burtus priešais savo brolius Aarono sūnus, karaliaus Dovydo, Cadoko, Ahimelecho ir kunigų bei levitų tėvų vyriausiųjų akivaizdoje, būtent pagrindiniai tėvai priešais savo jaunesniuosius brolius.'),
  (@b13, 25, 1, 'Be to, Dovydas ir kariuomenės vadai atskyrė tarnavimui iš Asafo, iš Hemano ir iš Jedutūno sūnų, kurie turėjo pranašauti su arfomis, psalteriais ir cimbolais; o darbininkų skaičius pagal jų tarnavimą buvo:'),
  (@b13, 25, 2, 'iš Asafo sūnų: Zakūras, Juozapas, Netanija ir Asarela – Asafo sūnūs, Asafo, pranašavusio karaliaus nurodymu, rankų valdžioje.'),
  (@b13, 25, 3, 'Iš Jedutūno: Jedutūno sūnūs: Gedalija, Ceris, Ješaja, Hašabija ir Matitijas, šeši, rankų valdžioje savo tėvo Jedutūno, kuris pranašavo su arfa, kad dėkotų ir girtų VIEŠPATĮ.'),
  (@b13, 25, 4, 'Iš Hemano: Hemano sūnūs: Bukijas, Matanija, Uzielis, Šebuelis ir Jerimotas, Hananija, Hananis, Elijata, Gidaltis ir Romamti-Ezeras, Jošbekaša, Malotis, Hotyras, Mahazijotas;'),
  (@b13, 25, 5, 'visi šitie buvo sūnūs Hemano, karaliaus regėtojo Dievo žodžiais, kad iškeltų ragą. Ir Dievas davė Hemanui keturiolika sūnų ir tris dukteris.'),
  (@b13, 25, 6, 'Visi šitie buvo savo tėvo rankų valdžioje dėl giedojimo VIEŠPATIES namuose su cimbolais, psalteriais ir arfomis, dėl Dievo namų tarnavimo – pagal karaliaus nurodymą – Asafui, Jedutūnui ir Hemanui.'),
  (@b13, 25, 7, 'Taigi jų skaičius su jų broliais, kurie buvo pamokyti VIEŠPATIES giesmių, tai yra visų įgudusių, buvo du šimtai aštuoniasdešimt aštuoni.'),
  (@b13, 25, 8, 'Ir jie metė burtus, sargyba priešais sargybą, kaip mažas, taip ir didelis, kaip mokytojas, taip ir mokinys.'),
  (@b13, 25, 9, 'Na, o pirmasis burtas išpuolė dėl Asafo Juozapui; antrasis Gedalijai; jis, jo broliai ir sūnūs – jų buvo dvylika.'),
  (@b13, 25, 10, 'Trečiasis Zakūrui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 11, 'Ketvirtasis Icriui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 12, 'Penktasis Netanijai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 13, 'Šeštasis Bukijui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 14, 'Septintasis Ješarelai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 15, 'Aštuntasis Ješajai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 16, 'Devintasis Matanijai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 17, 'Dešimtasis Šimiui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 18, 'Vienuoliktasis Azareliui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 19, 'Dvyliktasis Hašabijai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 20, 'Tryliktasis Šubaeliui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 21, 'Keturioliktasis Matitijai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 22, 'Penkioliktasis Jeremotui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 23, 'Šešioliktasis Hananijai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 24, 'Septynioliktasis Jošbekašai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 25, 'Aštuonioliktasis Hananiui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 26, 'Devynioliktasis Maločiui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 27, 'Dvidešimtasis Elijatai; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 28, 'Dvidešimt pirmasis Hotyrui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 29, 'Dvidešimt antrasis Gidalčiui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 30, 'Dvidešimt trečiasis Mahazijotui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 25, 31, 'Dvidešimt ketvirtasis Romanti-Ezerui; jis, jo sūnūs ir jo broliai – dvylika.'),
  (@b13, 26, 1, 'Apie durininkų padalijimus; iš korachų buvo Korės sūnus Mešelemija iš Asafo sūnų.'),
  (@b13, 26, 2, 'Mešelemijos sūnūs: pirmagimis Zacharija, Jedijaelis – antrasis, Zebadija – trečiasis, Jatnielis – ketvirtasis,'),
  (@b13, 26, 4, 'Be to, Obed-Edomo sūnūs: pirmagimis Šemaja, Jehozabadas – antrasis, Joachas – trečiasis, Sacharas – ketvirtasis, Netanelis – penktasis,'),
  (@b13, 26, 5, 'Amielis – šeštasis, Isacharas – septintasis, Peuletajas – aštuntasis, nes Dievas jį laimino.'),
  (@b13, 26, 6, 'Taip pat jo sūnui Šemajai gimė sūnų, kurie valdė savo tėvo namuose; nes jie buvo narsūs galiūnai.'),
  (@b13, 26, 7, 'Šemajos sūnūs: Otnis, Refaelis, Obedas, Elzabadas, kurio broliai buvo stiprūs vyrai, Elihuvas ir Semachijas.'),
  (@b13, 26, 8, 'Visi šitie iš Obed-Edomo sūnų; jų pačių, jų sūnų ir jų brolių, pajėgių vyrų stiprybei dėl tarnavimo, buvo šešiasdešimt du iš Obed-Edomo.'),
  (@b13, 26, 9, 'O Mešelemija turėjo sūnų ir brolių, aštuoniolika stiprių vyrų.'),
  (@b13, 26, 10, 'Taip pat Hosa iš Merario vaikų turėjo sūnų: Šimris vyriausiasis (nors jis ir nebuvo pirmagimis, tačiau jo tėvas jį padarė vyriausiuoju),'),
  (@b13, 26, 11, 'Hilkijas – antrasis, Tebalijas – trečiasis, Zacharija – ketvirtasis; iš viso Hosos sūnų ir brolių buvo trylika.'),
  (@b13, 26, 12, 'Tarp šitų, būtent tarp vyriausiųjų vyrų, buvo durininkų padalijimai sargybai vieniems prieš kitus, kad tarnautų VIEŠPATIES namuose.'),
  (@b13, 26, 13, 'Ir jie metė burtus kiekvieniems vartams, kaip mažas, taip ir didelis, pagal jų tėvų namus.'),
  (@b13, 26, 14, 'Burtas į rytus krito Šelemijai. Tada jie metė burtus jo sūnui Zacharijai, išmintingam patarėjui; o jo burtas išpuolė į šiaurę.'),
  (@b13, 26, 15, 'Obed-Edomui į pietus; o jo sūnums asufimų namai.'),
  (@b13, 26, 16, 'Šupimui ir Hosai burtas išpuolė į vakarus su Šalecheto vartais prie aukštyn einančio grįsto kelio, sargyba priešais sargybą.'),
  (@b13, 26, 17, 'Į rytus buvo šeši levitai, į šiaurę – keturi per dieną, į pietus – keturi per dieną, o link asufimo – po du.'),
  (@b13, 26, 18, 'Prie Parbaro į vakarus – keturi prie grįsto kelio ir du prie Parbaro.'),
  (@b13, 26, 19, 'Šitie yra durininkų padalijimai tarp Korės sūnų ir tarp Merario sūnų.'),
  (@b13, 26, 20, 'O iš levitų, Ahija prižiūrėjo Dievo namų lobynus ir pašvęstųjų dalykų lobynus.'),
  (@b13, 26, 21, 'O dėl Ladano sūnų; geršono Ladano sūnūs, vyriausieji tėvai, būtent iš geršono Ladano, buvo Jehielis.'),
  (@b13, 26, 22, 'Jehielio sūnūs: Zetamas ir jo brolis Joelis, kurie prižiūrėjo VIEŠPATIES namų lobynus.'),
  (@b13, 26, 23, 'Iš amramų, iccharų, hebronų, uzielių:'),
  (@b13, 26, 24, 'Mozės sūnaus Geršomo sūnus Šebuelis buvo lobynų valdovas.'),
  (@b13, 26, 25, 'O jo broliai iš Eliezero: jo sūnus Rehabijas, jo sūnus Ješaja, jo sūnus Joramas, jo sūnus Zichris, jo sūnus Šelomitas.'),
  (@b13, 26, 26, 'Šitas Šelomitas ir jo broliai prižiūrėjo visus lobynus pašvęstųjų dalykų, kuriuos karalius Dovydas, vyriausieji tėvai, tūkstančių bei šimtų vadai ir kariuomenės vadai buvo pašventę.'),
  (@b13, 26, 27, 'Iš grobio, laimėto mūšiuose, jie pašventė VIEŠPATIES namams palaikyti.'),
  (@b13, 26, 28, 'Ir viskas, ką buvo pašventę regėtojas Samuelis, Kišo sūnus Saulius, Nero sūnus Abneras ir Cerujos sūnus Joabas; kas tik ką pašvęsdavo, tai buvo Šelomito rankos ir jo brolių priežiūroje.'),
  (@b13, 26, 29, 'Iš iccharų: Kenanija ir jo sūnūs buvo pareigūnai ir teisėjai išoriniams reikalams Izraelyje.'),
  (@b13, 26, 30, 'Iš hebronų: Hašabija ir jo broliai, tūkstantis septyni šimtai narsių vyrų, buvo pareigūnai tarp tų iš Izraelio šiapus Jordano į vakarus, visuose VIEŠPATIES reikaluose ir karaliaus tarnavime.'),
  (@b13, 26, 31, 'Tarp hebronų buvo vyriausiasis Jerija, būtent tarp hebronų, pagal savo tėvų giminę. Keturiasdešimtaisiais Dovydo karaliavimo metais jų buvo ieškoma, ir tarp jų buvo rasta narsių galiūnų Gileado Jazeryje.'),
  (@b13, 26, 32, 'O jo brolių, narsių vyrų, buvo du tūkstančiai septyni šimtai vyriausiųjų tėvų, kuriuos karalius Dovydas padarė rubenų, gadų ir pusės Manaso genties valdovais visuose Dievo reikaluose ir karaliaus reikaluose.'),
  (@b13, 26, 3, 'Elamas – penktasis, Jehohananas – šeštasis, Eljehoenajas – septintasis.'),
  (@b13, 27, 1, 'Na, o Izraelio vaikų pagal jų skaičių, būtent vyriausiųjų tėvų, tūkstantininkų, šimtininkų ir jų pareigūnų, tarnaujančių karaliui visokiuose skyrių reikaluose, kurie kas mėnesį įeidavo ir išeidavo visais metų mėnesiais, iš kiekvieno skyriaus buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 2, 'Pirmojo skyriaus vadas pirmajam mėnesiui buvo Zabdielio sūnus Jašobamas; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 3, 'Iš Pereco vaikų buvo visų kariuomenės vadų vyriausiasis pirmajam mėnesiui.'),
  (@b13, 27, 4, 'Antrojo mėnesio skyriaus vadas buvo ahochas Dodajas, o iš jo skyriaus taip pat buvo valdovas Miklotas; jo skyriuje irgi buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 5, 'Trečiasis kariuomenės vadas trečiajam mėnesiui buvo vyriausiasis kunigas Jehojados sūnus Benaja; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 6, 'Tai tas Benajas, kuris buvo galingas tarp trisdešimties, ir trisdešimties viršininkas; o jo skyriuje buvo jo sūnus Amizabadas.'),
  (@b13, 27, 7, 'Ketvirtasis vadas ketvirtajam mėnesiui buvo Joabo brolis Asaelis, o po jo – jo sūnus Zebadija; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 8, 'Penktasis vadas penktajam mėnesiui buvo izrachas Šamhutas; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 9, 'Šeštasis vadas šeštajam mėnesiui buvo tekojiečio Ikešo sūnus Ira; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 10, 'Septintasis vadas septintajam mėnesiui buvo pelonietis Helecas iš Efraimo vaikų; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 11, 'Aštuntasis vadas aštuntajam mėnesiui buvo hušietis Sibechajas iš zerachų; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 12, 'Devintasis vadas devintajam mėnesiui buvo anatotietis Abiezeras iš benjaminų; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 13, 'Dešimtasis vadas dešimtajam mėnesiui buvo netofietis Mahrajas iš zerachų; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 14, 'Vienuoliktasis vadas vienuoliktajam mėnesiui buvo piratonietis Benaja iš Efraimo vaikų; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 15, 'Dvyliktasis vadas dvyliktajam mėnesiui buvo netofietis Heldajas iš Otnielio; o jo skyriuje buvo dvidešimt keturi tūkstančiai.'),
  (@b13, 27, 16, 'Be to, dar Izraelio genčių vadai: rubenų valdovas buvo Zichrio sūnus Eliezeras; simeonų – Maakos sūnus Šefatijas;'),
  (@b13, 27, 17, 'levitų – Kemuelio sūnus Hašabija; aaronitų – Cadokas;'),
  (@b13, 27, 18, 'Judos – Elihuvas, vienas iš Dovydo brolių; Isacharo – Mykolo sūnus Omris;'),
  (@b13, 27, 19, 'Zebulono – Abdijo sūnus Išmaja; Naftalio – Azrielio sūnus Jerimotas;'),
  (@b13, 27, 20, 'Efraimo vaikų – Azazijo sūnus Ozėja; pusės Manaso genties – Pedajos sūnus Joelis;'),
  (@b13, 27, 21, 'pusės Manaso genties Gileade – Zacharijo sūnus Idojas; Benjamino – Abnero sūnus Jaasielis;'),
  (@b13, 27, 22, 'Dano – Jerohamo sūnus Azarelis. Šitie buvo Izraelio genčių kunigaikščiai.'),
  (@b13, 27, 23, 'Bet Dovydas neskaičiavo tų, kurie buvo nuo dvidešimties metų ir jaunesni; nes VIEŠPATS buvo sakęs, kad padaugins Izraelį, kaip dangų žvaigždes.'),
  (@b13, 27, 24, 'Cerujos sūnus Joabas pradėjo skaičiuoti, bet nepabaigė, nes dėl to rūstybė krito prieš Izraelį; ir skaičius nepateko į karaliaus Dovydo kronikų pasakojimą.'),
  (@b13, 27, 25, 'Ir karaliaus lobynus prižiūrėjo Adielio sūnus Azmavetas; o sandėlius laukuose, miestuose, kaimuose ir pilyse prižiūrėjo Uzijo sūnus Jehonatanas;'),
  (@b13, 27, 26, 'o dirbančiuosius lauko darbus žemei įdirbti, prižiūrėjo Kelubo sūnus Ezris;'),
  (@b13, 27, 27, 'o vynuogynus prižiūrėjo ramietis Šimis; vynuogynų prieaugį vyno sandėliams prižiūrėjo šefamietis Zabdis;'),
  (@b13, 27, 28, 'o alyvmedžius ir sikomorus, esančius žemose lygumose, prižiūrėjo gederietis Baal-Hananas; o aliejaus sandėlius prižiūrėjo Joašas;'),
  (@b13, 27, 29, 'o bandas, kurios ganėsi Šarone, prižiūrėjo šaronietis Šitrajas; o bandas, esančias slėniuose, prižiūrėjo Adlajo sūnus Šafatas;'),
  (@b13, 27, 30, 'kupranugarius prižiūrėjo išmaelitas Obilas; asilus prižiūrėjo meronotietis Jechdijas;'),
  (@b13, 27, 31, 'o kaimenes prižiūrėjo hagaras Jazizas. Šitie visi buvo karaliaus Dovydo nuosavybės valdovai.'),
  (@b13, 27, 32, 'Dovydo dėdė Jonatanas buvo patarėjas, išmintingas vyras ir raštininkas; o Hachmonio sūnus Jehielis buvo prie karaliaus sūnų;'),
  (@b13, 27, 33, 'o Ahitofelis buvo karaliaus patarėjas; o arkas Hušajas buvo karaliaus draugas;'),
  (@b13, 27, 34, 'o po Ahitofelio buvo Benajos sūnus Jehojada ir Abjataras; o karaliaus kariuomenės karvedys buvo Joabas.'),
  (@b13, 28, 1, 'Ir Dovydas surinko į Jeruzalę visus Izraelio kunigaikščius, genčių kunigaikščius, būrių vadus, tarnaujančius karaliui pagal skyrius, tūkstantininkus, šimtininkus ir viso karaliaus bei jo sūnų turto ir nuosavybės ūkvedžius su pareigūnais, su galiūnais ir su visais narsuoliais.'),
  (@b13, 28, 2, 'Tada karalius Dovydas, atsistojęs ant kojų, tarė: „Paklausykite manęs, mano broliai ir mano tauta; na, o kas dėl manęs, mano širdyje buvo, kad pastatyčiau poilsio namus VIEŠPATIES Sandoros skryniai ir mūsų Dievo pakojui, ir paruošiau statybai;'),
  (@b13, 28, 3, 'bet Dievas man tarė: ‘Tu nestatysi namų mano vardui, nes tu buvai karo vyras ir praliejai kraują’.'),
  (@b13, 28, 4, 'Tačiau VIEŠPATS, Izraelio Dievas, mane išrinko iš visų mano tėvo namų, kad per amžius būčiau Izraelio karalius; nes jis išrinko Judą būti valdovu; o iš Judos namų mano tėvo namus; o tarp mano tėvo sūnų jam patiko mane padaryti viso Izraelio karaliumi;'),
  (@b13, 28, 5, 'o iš visų mano sūnų (nes VIEŠPATS man davė daug sūnų) jis išrinko mano sūnų Saliamoną, kad sėdėtų VIEŠPATIES karalystės soste valdyti Izraelį.'),
  (@b13, 28, 6, 'Ir jis man pasakė: ‘Tavo sūnus Saliamonas, jis pastatys mano namus ir mano kiemus; nes jį išsirinkau būti mano sūnumi, ir aš jam būsiu tėvas.'),
  (@b13, 28, 7, 'Be to, aš įtvirtinsiu jo karalystę per amžius, jei jis bus pastovus, vykdydamas mano įsakymus ir mano teismus, kaip šią dieną’.'),
  (@b13, 28, 8, 'Taigi dabar viso Izraelio, VIEŠPATIES susirinkimo, akivaizdoje ir mūsų Dievui klausantis, laikykitės ir siekite visų VIEŠPATIES, savo Dievo, įsakymų; kad pasisavintumėte tą gerą šalį ir ją paliktumėte paveldui savo vaikams po jūsų per amžius.'),
  (@b13, 28, 9, 'O tu, mano sūnau Saliamonai, pažink savo tėvo Dievą ir jam tarnauk tobula širdimi ir noringa dvasia; nes VIEŠPATS ištiria visas širdis ir supranta visus minčių sumanymus; jei jo ieškosi, jis tau bus randamas; bet jei jį paliksi, jis atmes tave amžiams.'),
  (@b13, 28, 10, 'Dabar žiūrėk; nes VIEŠPATS tave išrinko, kad pastatytum šventovei namus; būk stiprus ir daryk tai“.'),
  (@b13, 28, 11, 'Tada Dovydas davė savo sūnui Saliamonui pavyzdį prieangio, jo namų, jo lobynų, jo aukštutinių kambarių, jo vidinių kambarių, gailestingumo krasės vietos'),
  (@b13, 28, 12, 'ir pavyzdį visko, ką jis turėjo per dvasią: VIEŠPATIES namų kiemų bei visų kambarių aplinkui, Dievo namų lobynų ir pašvęstųjų dalykų lobynų;'),
  (@b13, 28, 13, 'taip pat kunigų bei levitų skyriams ir visam VIEŠPATIES namų tarnavimo darbui, ir visiems tarnavimo indams VIEŠPATIES namuose.'),
  (@b13, 28, 14, 'Jis davė aukso pagal svorį aukso daiktams, visiems visokio tarnavimo įrankiams; taip pat sidabro visiems sidabro įrankiams pagal svorį, visiems visokio tarnavimo įrankiams:'),
  (@b13, 28, 15, 'būtent svorį aukso žvakidėms ir jų aukso žibintams, pagal svorį kiekvienai žvakidei ir jos žibintams; sidabro žvakidėms, pagal svorį tiek žvakidei, tiek jos žibintams, pagal kiekvienos žvakidės paskirtį.'),
  (@b13, 28, 16, 'Pagal svorį jis davė aukso parodomosios duonos stalams, kiekvienam stalui; taip pat sidabro sidabriniams stalams;'),
  (@b13, 28, 17, 'taip pat gryno aukso mėsos šakutėms, dubenėliams ir taurėms; ir auksiniams dubenims jis davė aukso, kiekvienam dubeniui pagal svorį; taip pat sidabro pagal svorį kiekvienam sidabriniam dubeniui;'),
  (@b13, 28, 18, 'ir smilkalų aukurui davė valyto aukso pagal svorį; aukso davė pavyzdžiui vežimo kerubų, kurie išskėtė savo sparnus ir apdengė VIEŠPATIES Sandoros skrynią.'),
  (@b13, 28, 19, 'Visa tai, sakė Dovydas, būtent visus šio pavyzdžio darbus, VIEŠPATS man davė suprasti raštu nuo savo rankos ant manęs.'),
  (@b13, 28, 20, 'Ir Dovydas tarė savo sūnui Saliamonui: „Būk stiprus ir drąsus ir daryk tai; nebijok ir nebūk nerimastingas; nes VIEŠPATS Dievas, būtent mano Dievas, bus su tavimi; jis tavęs neapvils ir nepaliks, kol būsi baigęs visą tą darbą VIEŠPATIES namų tarnavimui.'),
  (@b13, 28, 21, 'Ir štai kunigų ir levitų skyriai, būtent jie bus su tavimi visam Dievo namų tarnavimui; ir visokiam darbui bus su tavimi visi savanoriai meistrai bet kokiam tarnavimui; taip pat kunigaikščiai ir visa tauta bus visiškai pagal tavo įsakymą“.'),
  (@b13, 29, 1, 'Toliau karalius Dovydas tarė visam susirinkimui: „Mano sūnus Saliamonas, kurį vieną Dievas išsirinko, yra dar jaunas ir gležnas, o darbas yra didelis; nes rūmai ne žmogui, bet VIEŠPAČIUI Dievui.'),
  (@b13, 29, 2, 'Dabar aš paruošiau visa savo galybe savo Dievo namams aukso iš aukso daromiems daiktams, sidabro sidabriniams daiktams, žalvario žalvariniams daiktams, geležies geležiniams daiktams, medžio mediniams daiktams; onikso akmenų ir įstatomųjų akmenų, blizgančių akmenų ir margaspalvių, visokių brangiųjų akmenų ir marmuro akmenų gausybę.'),
  (@b13, 29, 3, 'Be to, kadangi prisirišau prie savo Dievo namų, aš turiu savo paties gėrybių iš aukso bei sidabro, kuriuos daviau savo Dievo namams, virš viso to, ką esu paruošęs šventiems namams,'),
  (@b13, 29, 4, 'būtent tris tūkstančius talentų aukso, Ofyro aukso, ir septynis tūkstančius talentų valyto sidabro namų sienoms padengti;'),
  (@b13, 29, 5, 'aukso auksiniams daiktams, sidabro sidabriniams daiktams ir visokiam amatininkų rankomis atliekamam darbui. Tad kas yra norintis šią dieną įšventinti savo tarnavimą VIEŠPAČIUI?“'),
  (@b13, 29, 6, 'Tada tėvų vyriausieji, Izraelio genčių kunigaikščiai, tūkstantininkai ir šimtininkai su karaliaus darbo valdovais noriai atnašavo'),
  (@b13, 29, 7, 'ir davė Dievo namų tarnavimui aukso penkis tūkstančius talentų ir dešimt tūkstančių drachmų, dešimt tūkstančių talentų sidabro, aštuoniolika tūkstančių talentų žalvario ir šimtą tūkstančių talentų geležies.'),
  (@b13, 29, 8, 'O tie, pas ką radosi brangiųjų akmenų, juos davė VIEŠPATIES namų lobynui per geršono Jehielio ranką.'),
  (@b13, 29, 9, 'Tada tauta džiaugėsi, kad jie atnašavo noriai, nes tobula širdimi jie noriai atnašavo VIEŠPAČIUI; ir karalius Dovydas taip pat džiaugėsi dideliu džiaugsmu.'),
  (@b13, 29, 10, 'Todėl Dovydas laimino VIEŠPATĮ viso susirinkimo akivaizdoje; ir Dovydas tarė: „Būk palaimintas, VIEŠPATIE, mūsų tėvo Izraelio Dieve, per amžių amžius.'),
  (@b13, 29, 11, 'Tavo, o VIEŠPATIE, yra didybė, jėga, šlovė, pergalė ir didenybė; nes visa, kas yra danguje ir žemėje, yra tavo; tavo yra karalystė, o VIEŠPATIE, ir tu esi išaukštintas kaip galva viršum visko.'),
  (@b13, 29, 12, 'Turtai ir garbė ateina iš tavęs, ir tu viskam karaliauji; tavo rankoje yra jėga ir galybė; ir tavo rankoje yra, kad padarytum didį ir duotum stiprybės visiems.'),
  (@b13, 29, 13, 'Taigi dabar, mūsų Dieve, mes tau dėkojame ir giriame tavo šlovingąjį vardą.'),
  (@b13, 29, 14, 'Bet kas gi aš esu ir kas mano tauta, kad pajėgtume taip noriai šitaip atnašauti? Nes iš tavęs ateina viskas, ir tau davėme iš to, kas tavo.'),
  (@b13, 29, 15, 'Nes mes esame ateiviai tavo akivaizdoje ir laikinai apsigyvenę, kaip buvo visi mūsų tėvai; mūsų dienos žemėje yra kaip šešėlis, ir nieko nėra patvaraus.'),
  (@b13, 29, 16, 'O VIEŠPATIE, mūsų Dieve, visa šita gausybė, kurią paruošėme, kad tau pastatytume namus tavo šventajam vardui, ateina iš tavo rankos, ir viskas yra tavo.'),
  (@b13, 29, 17, 'Taip pat žinau, mano Dieve, kad tu ištiri širdį ir mėgsti tiesumą. Aš pats tiesia širdimi noriai visa tai atnašavau; o dabar su džiaugsmu mačiau tavo čia esančią tautą tau noriai atnašaujančią.'),
  (@b13, 29, 18, 'O VIEŠPATIE, mūsų tėvų Abraomo, Izaoko ir Izraelio Dieve, amžinai tai išlaikyk savo tautos širdies minčių sumanyme ir paruošk jų širdį link savęs;'),
  (@b13, 29, 19, 'o mano sūnui Saliamonui duok tobulą širdį, kad laikytųsi tavo įsakymų, tavo liudijimų ir tavo įstatų, kad visa tai darytų ir pastatytų rūmus, kuriems aš parūpinau“.'),
  (@b13, 29, 20, 'Ir Dovydas tarė visam susirinkimui: „Dabar laiminkite VIEŠPATĮ, savo Dievą“. Ir visas susirinkimas laimino VIEŠPATĮ, savo tėvų Dievą, ir nulenkę galvas garbino VIEŠPATĮ ir karalių.'),
  (@b13, 29, 21, 'O po tos dienos, rytojaus dieną, jie aukojo VIEŠPAČIUI aukas ir atnašavo VIEŠPAČIUI deginamąsias atnašas: tūkstantį jaučių, tūkstantį avinų, tūkstantį avinėlių su jų geriamosiomis atnašomis ir daugybę aukų už visą Izraelį;'),
  (@b13, 29, 22, 'ir tą dieną valgė ir gėrė VIEŠPATIES akivaizdoje su dideliu džiaugsmu. Ir antrą kartą padarė karaliumi Dovydo sūnų Saliamoną ir patepė jį VIEŠPAČIUI, kad būtų vyriausiuoju valdytoju, o Cadoką, kad būtų kunigu.'),
  (@b13, 29, 23, 'Tada Saliamonas atsisėdo kaip karalius į VIEŠPATIES sostą savo tėvo Dovydo vietoje ir klestėjo; ir jam pakluso visas Izraelis.'),
  (@b13, 29, 24, 'Visi kunigaikščiai ir galiūnai, taip pat visi karaliaus Dovydo sūnūs pakluso karaliui Saliamonui.'),
  (@b13, 29, 25, 'Ir VIEŠPATS nepaprastai išaukštino Saliamoną viso Izraelio akyse ir jam suteikė tokią karališką didybę, kokios pirma jo nebuvo turėjęs joks Izraelio karalius.'),
  (@b13, 29, 26, 'Taip Jesės sūnus Dovydas karaliavo visam Izraeliui.'),
  (@b13, 29, 27, 'O laiko, kuriuo jis karaliavo Izraeliui, buvo keturiasdešimt metų; Hebrone jis karaliavo septynerius metus, o Jeruzalėje jis karaliavo trisdešimt trejus metus.'),
  (@b13, 29, 28, 'Ir jis mirė gerai pasenęs, pasisotinęs dienomis, turtais ir garbe; o jo sūnus Saliamonas karaliavo jo vietoje.'),
  (@b13, 29, 29, 'Na, o karaliaus Dovydo darbai, pirmieji ir paskutinieji, štai jie surašyti regėtojo Samuelio knygoje, pranašo Natano knygoje ir regėtojo Gado knygoje,'),
  (@b13, 29, 30, 'kartu su visu jo karaliavimu, jo galybe ir laikais, kurie perėjo per jį, per Izraelį ir per visas šalių karalystes.'),
  (@b14, 1, 1, 'Ir Dovydo sūnus Saliamonas sustiprėjo savo karalystėje, ir VIEŠPATS, jo Dievas, buvo su juo ir labai jį išaukštino.'),
  (@b14, 1, 2, 'Tada Saliamonas kalbėjo visam Izraeliui, tūkstančių vadams ir šimtininkams, teisėjams ir visiems valdytojams visame Izraelyje, tėvų vyriausiems.'),
  (@b14, 1, 3, 'Taigi Saliamonas ir visas susirinkimas su juo vyko į Gibeone esančią aukštumą; nes ten buvo Dievo susirinkimo padangtė, kurią VIEŠPATIES tarnas Mozė buvo padaręs dykumoje.'),
  (@b14, 1, 4, 'Bet Dievo skrynią Dovydas buvo nugabenęs aukštyn iš Kirjat-Jearimo į tą vietą, kurią Dovydas jai buvo paruošęs; nes jis jai buvo ištiesęs palapinę Jeruzalėje.'),
  (@b14, 1, 5, 'Be to, žalvarinį aukurą, kurį Hūro sūnaus Ūrio sūnus Becalelis buvo padaręs, jis padėjo prieš VIEŠPATIES padangtę; o jo ieškojo Saliamonas ir susirinkimas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b14, 1, 6, 'Ir Saliamonas nuėjo ten aukštyn prie žalvarinio aukuro VIEŠPATIES akivaizdoje, esančio susirinkimo padangtėje, ir ant jo atnašavo tūkstantį deginamųjų atnašų.'),
  (@b14, 1, 7, 'Tą naktį Dievas pasirodė Saliamonui ir jam tarė: „Prašyk, ką tau duoti“.'),
  (@b14, 1, 8, 'Ir Saliamonas tarė Dievui: „Tu parodei mano tėvui Dovydui didelį gailestingumą ir mane paskyrei, kad karaliaučiau jo vietoje.'),
  (@b14, 1, 9, 'Dabar, o VIEŠPATIE Dieve, tebūna įtvirtintas tavo pažadas mano tėvui Dovydui; nes tu mane padarei karaliumi tautai, kuri gausi kaip žemės dulkės.'),
  (@b14, 1, 10, 'Duok man dabar išminties ir pažinimo, kad išeičiau ir įeičiau šitos tautos akivaizdoje; nes kas galėtų teisti šitą tavo tautą, kuri yra tokia didelė?“'),
  (@b14, 1, 11, 'Ir Dievas tarė Saliamonui: „Kadangi tai buvo tavo širdyje ir neprašei turtų, lobių ar garbės nei savo priešų gyvybės ir ilgo amžiaus neprašei, bet prašei sau išminties ir pažinimo, kad galėtum teisti mano tautą, kurios karaliumi tave padariau;'),
  (@b14, 1, 12, 'tau yra suteikta išmintis ir pažinimas; ir aš tau duosiu turtų, lobių ir garbės, kokių nėra turėję pirma tavęs buvusieji karaliai ir kokių niekas po tavęs neturės“.'),
  (@b14, 1, 13, 'Paskui Saliamonas iš savo kelionės į Gibeone esančią aukštumą, nuo susirinkimo padangtės priekio, grįžo į Jeruzalę ir karaliavo Izraeliui.'),
  (@b14, 1, 14, 'Ir Saliamonas surinko vežimus ir raitelius; jis turėjo tūkstantį keturis šimtus vežimų ir dvylika tūkstančių raitelių, kuriuos jis sustatė vežimų miestuose ir pas karalių Jeruzalėje.'),
  (@b14, 1, 15, 'Ir karalius padarė, kad sidabro ir aukso Jeruzalėje buvo tiek gausu, kiek akmenų, o kedrų jis padarė, kad būtų kaip gausybė sikomorų, esančių slėnyje.'),
  (@b14, 1, 16, 'Ir Saliamonas turėjo žirgų, atgabentų iš Egipto, ir lininių verpalų; karaliaus pirkliai įsigydavo lininių verpalų už kainą.'),
  (@b14, 1, 17, 'Jie atgabendavo aukštyn ir iš Egipto išgabendavo vežimą už šešis šimtus sidabro šekelių, o žirgą už šimtą penkiasdešimt; ir taip savais būdais jie išgabendavo žirgus visiems hetitų karaliams ir Sirijos karaliams.'),
  (@b14, 2, 1, 'Ir Saliamonas nusprendė statyti namus VIEŠPATIES vardui ir namus savo karalystei.'),
  (@b14, 2, 2, 'Ir Saliamonas suskaičiavo septyniasdešimt tūkstančių vyrų naštoms nešti ir aštuoniasdešimt tūkstančių tašyti kalnuose, ir jų prižiūrėtojų – tris tūkstančius šešis šimtus.'),
  (@b14, 2, 3, 'Ir Saliamonas pasiuntė Tyro karaliui Huramui, sakydamas: „Kaip tu padarei mano tėvui Dovydui ir siuntei jam kedrų, kad pasistatytų sau namus gyventi, taip daryk ir man.'),
  (@b14, 2, 4, 'Štai aš statau namus VIEŠPATIES, savo Dievo, vardui, kad jam juos pašvęsčiau, deginimui jo akivaizdoje kvapius smilkalus ir nuolatinei parodomajai duonai bei deginamosioms atnašoms ryte ir vakare, per sabatus, per jauną mėnulį ir per VIEŠPATIES, mūsų Dievo, iškilmingas šventes. Tai amžinas potvarkis Izraeliui.'),
  (@b14, 2, 5, 'O namai, kuriuos aš statau, yra dideli, nes mūsų Dievas yra didesnis už visus dievus.'),
  (@b14, 2, 6, 'Bet kas yra pajėgus jam pastatyti namus, kadangi dangus ir dangų dangus negali jo sutalpinti? Tad kas aš esu, kad jam statyčiau namus, nebent deginti aukoms jo akivaizdoje?'),
  (@b14, 2, 7, 'Taigi dabar atsiųsk man vyrą, gabų dirbti iš aukso, sidabro, žalvario, geležies, purpuro, tamsiai raudono ir mėlyno, ir kuris mokėtų raižyti kartu su gabiais vyrais, esančiais pas mane Judoje ir Jeruzalėje, kurių parūpino mano tėvas Dovydas.'),
  (@b14, 2, 8, 'Atsiųsk man taip pat kedrų, eglių ir algumo medžių iš Libano; nes aš žinau, kad tavo tarnai moka kirsti medžius Libane; o štai mano tarnai bus su tavo tarnais,'),
  (@b14, 2, 9, 'būtent, kad man paruoštų gausiai medienos; nes tie namai, kuriuos rengiuosi statyti, bus dideli ir nuostabūs.'),
  (@b14, 2, 10, 'Štai aš duosiu tavo tarnams, kirtėjams, kertantiems medžius: dvidešimt tūkstančių saikų maltų kviečių, dvidešimt tūkstančių saikų miežių, dvidešimt tūkstančių batų vyno ir dvidešimt tūkstančių batų aliejaus“.'),
  (@b14, 2, 11, 'Tada Tyro karalius Huramas atsakė raštu, kurį jis nusiuntė Saliamonui: „Kadangi VIEŠPATS myli savo tautą, jis tave paskyrė jiems karaliumi“.'),
  (@b14, 2, 12, 'Huramas dar sakė: „Tebūna palaimintas VIEŠPATS, Izraelio Dievas, kuris padarė dangų ir žemę, kuris davė karaliui Dovydui išmintingą sūnų, apdalintą protingumu ir supratimu, kad galėtų statyti namus VIEŠPAČIUI ir namus savo karalystei.'),
  (@b14, 2, 13, 'O dabar siunčiu gabų vyrą, apdalintą supratimu, iš savo tėvo Huramo,'),
  (@b14, 2, 14, 'sūnų moters iš Dano dukterų, kurio tėvas buvo vyras iš Tyro, mokantį dirbti iš aukso ir sidabro, žalvario, geležies, akmens ir medienos, purpuro, mėlyno, plono lino ir tamsiai raudono; taip pat raižyti visokius raižinius ir pramanyti visokių dirbinių, kurie jam bus užduoti, su tavo gabiais vyrais ir su mano viešpaties, tavo tėvo Dovydo, gabiais vyrais.'),
  (@b14, 2, 15, 'Taigi dabar kviečių ir miežių, aliejaus ir vyno, apie kuriuos kalbėjo mano viešpats, tegul jis atsiunčia savo tarnams;'),
  (@b14, 2, 16, 'o mes prikirsime medžių iš Libano, kiek tau reikės: ir mes juos tau sieliais atgabensime jūra į Jopą; o tu juos nugabensi aukštyn į Jeruzalę“.'),
  (@b14, 2, 17, 'Ir Saliamonas suskaičiavo visus ateivius, esančius Izraelio šalyje, pagal tą skaičiavimą, kuriuo juos buvo suskaičiavęs jo tėvas Dovydas; ir jų radosi šimtas penkiasdešimt trys tūkstančiai šeši šimtai.'),
  (@b14, 2, 18, 'Iš jų jis paskyrė septyniasdešimt tūkstančių naštų nešikais, aštuoniasdešimt tūkstančių tašytojais kalnuose ir tris tūkstančius šešis šimtus prižiūrėtojais, kad pristatytų liaudį prie darbo.'),
  (@b14, 3, 1, 'Tada Saliamonas pradėjo statyti VIEŠPATIES namus Jeruzalėje ant Morijos kalno, kur VIEŠPATS pasirodė jo tėvui Dovydui, toje vietoje, kurią Dovydas buvo paruošęs jebusiečio Ornano klojime.'),
  (@b14, 3, 2, 'Ir jis pradėjo statyti antrojo mėnesio antrąją dieną, ketvirtaisiais savo karaliavimo metais.'),
  (@b14, 3, 3, 'Na, o šitie yra dalykai, kuriais Saliamonas buvo pamokytas Dievo namų statybai. Ilgis uolektimis buvo šešiasdešimt uolekčių pagal pirmąjį matą, o plotis dvidešimt uolekčių.'),
  (@b14, 3, 4, 'Namų priekyje esančio prieangio ilgis buvo pagal namų plotį dvidešimt uolekčių, o aukštis buvo šimtas dvidešimt; jis padengė jį iš vidaus grynu auksu.'),
  (@b14, 3, 5, 'Didžiuosius namus jis apmušė eglės mediena, kurią jis padengė geru auksu ir ant to padarė palmes bei grandinėles.'),
  (@b14, 3, 6, 'Ir jis išpuošė namus brangakmeniais dėl grožio; o auksas buvo Parvaimo auksas.'),
  (@b14, 3, 7, 'Taip pat jis padengė auksu namus, sijas, staktas, jų sienas ir jų duris; ir išraižė kerubus ant sienų.'),
  (@b14, 3, 8, 'Jis padarė švenčiausiuosius namus, kurių ilgis buvo pagal namų plotį dvidešimt uolekčių, ir jų plotis dvidešimt uolekčių; ir juos padengė geru auksu, siekiančiu šešis šimtus talentų.'),
  (@b14, 3, 9, 'O vinių svoris buvo penkiasdešimt šekelių aukso. Ir viršutinius kambarius jis padengė auksu.'),
  (@b14, 3, 10, 'O švenčiausiuose namuose padarė du kerubus, atvaizdo dirbinius, ir padengė juos auksu.'),
  (@b14, 3, 11, 'Kerubų sparnai buvo dvidešimties uolekčių ilgio: vienas vieno kerubo sparnas buvo penkių uolekčių, siekiantis namų sieną; o kitas sparnas taip pat penkių uolekčių, siekiantis kito kerubo sparną.'),
  (@b14, 3, 12, 'Ir kito kerubo vienas sparnas buvo penkių uolekčių, siekiantis namų sieną; o kitas sparnas taip pat buvo penkių uolekčių, susiliečiantis su kito kerubo sparnu.'),
  (@b14, 3, 13, 'Šitų kerubų sparnai išsiskėtė per dvidešimt uolekčių; ir jie stovėjo ant savo kojų, o jų veidai buvo nukreipti į vidų.'),
  (@b14, 3, 14, 'Ir jis padarė uždangą iš mėlyno, purpuro, tamsiai raudonojo bei plono lino ir ant jos padarė kerubų.'),
  (@b14, 3, 15, 'Taip pat namų priekyje padarė du stulpus trisdešimt penkių uolekčių aukščio, o kapitelis, kuris buvo ant kiekvieno jų viršaus, buvo penkių uolekčių.'),
  (@b14, 3, 16, 'Jis padarė grandinėlių kaip orakule ir uždėjo jas ant stulpų galvų; ir padarė šimtą granatų, ir pridėjo juos prie grandinėlių.'),
  (@b14, 3, 17, 'Ir jis pastatė stulpus šventyklos priekyje: vieną dešinėje, o kitą kairėje; dešinįjį jis pavadino vardu Jachinas, o kairįjį vardu Boazas.'),
  (@b14, 4, 1, 'Jis dar padarė žalvario aukurą dvidešimties uolekčių ilgio, dvidešimties uolekčių pločio ir dešimties uolekčių aukščio.'),
  (@b14, 4, 2, 'Taip pat jis padarė nulietą jūrą dešimties uolekčių nuo briaunos iki briaunos, apskritą ir penkių uolekčių aukščio; ir trisdešimties uolekčių virvė apjuosė ją.'),
  (@b14, 4, 3, 'O po ja buvo jaučių pavidalai, kurie supo ją aplinkui; dešimt per uolektį apsupo jūrą aplinkui. Dvi eilės jaučių buvo nulieta, kai ji buvo liejama.'),
  (@b14, 4, 4, 'Ji stovėjo ant dvylikos jaučių: trys žiūrėjo į šiaurę, trys žiūrėjo į vakarus, trys žiūrėjo į pietus, o trys žiūrėjo į rytus; jūra buvo ant jų viršuje, o visos jų užpakalinės dalys buvo nukreiptos į vidų.'),
  (@b14, 4, 5, 'Ir jos storis buvo per plaštaką, ir jos briauna buvo padaryta kaip taurės briauna, su lelijų žiedais; ji priėmė ir talpino tris tūkstančius batų.'),
  (@b14, 4, 6, 'Taip pat jis padarė dešimt praustuvių ir padėjo penkias dešinėje ir penkias kairėje, plovimui jose; jose nuplaudavo tai, ką atnašaudavo deginamajai atnašai; bet jūra buvo kunigams, kad joje nusiplautų.'),
  (@b14, 4, 7, 'Jis padarė dešimt aukso žvakidžių pagal jų formas ir pastatė jas šventykloje: penkias dešinėje ir penkias kairėje.'),
  (@b14, 4, 8, 'Jis taip pat padarė dešimt stalų ir pastatė juos šventykloje: penkis dešinėje ir penkis kairėje. Ir jis padarė šimtą auksinių dubenų.'),
  (@b14, 4, 9, 'Jis dar padarė kunigų kiemą ir didįjį kiemą bei duris kiemui, ir jų duris padengė žalvariu.'),
  (@b14, 4, 10, 'O jūrą jis pastatė rytinio galo dešinėje pusėje, priešais pietus.'),
  (@b14, 4, 11, 'Huramas padarė puodų, semtuvų ir dubenų. Ir Huramas baigė darbą, kurį jis turėjo padaryti karaliui Saliamonui Dievo namams;'),
  (@b14, 4, 12, 'tai yra du stulpus, dubenis ir kapitelius, esančius ant dviejų stulpų viršaus, ir du tinklus apdengti abiems dubenims kapitelių, esančių ant stulpų viršaus;'),
  (@b14, 4, 13, 'keturis šimtus granatų ant abiejų tinklų; dvi eiles granatų ant kiekvieno tinklo, kad apdengtų abu dubenis kapitelių, esančių ant stulpų.'),
  (@b14, 4, 14, 'Taip pat jis padarė stovus, ir praustuves padarė ant stovų;'),
  (@b14, 4, 15, 'vieną jūrą ir dvylika jaučių jos apačioje.'),
  (@b14, 4, 16, 'Taip pat puodus, semtuvus, mėsos šakes ir visus jų įrankius jo tėvas Huramas padarė karaliui Saliamonui iš blizgančio žalvario VIEŠPATIES namams.'),
  (@b14, 4, 17, 'Jordano lygumoje karalius juos nuliejo, molingoje žemėje tarp Sukoto ir Ceredos.'),
  (@b14, 4, 18, 'Taip Saliamonas padarė labai daug visų šitų indų; nes nebuvo galima apskaičiuoti žalvario svorio.'),
  (@b14, 4, 19, 'Ir Saliamonas padarė visus tuos indus, kurie buvo Dievo namams, taip pat auksinį aukurą ir stalus, ant kurių buvo dedama parodomoji duona;'),
  (@b14, 4, 20, 'dar gryno aukso žvakides su jų žibintais, kad jie degtų pagal paprotį prieš orakulą;'),
  (@b14, 4, 21, 'ir gėles, žibintus ir žnyples padarė iš aukso, iš gryniausio aukso;'),
  (@b14, 4, 22, 'gnybtuvus, dubenis, šaukštus ir smilkytuvus iš gryno aukso; o namų įėjimas, jų vidinės durys švenčiausiajai vietai ir šventyklos namų durys buvo iš aukso.'),
  (@b14, 5, 1, 'Taip buvo baigtas visas darbas, kurį Saliamonas padarė VIEŠPATIES namams; ir Saliamonas įnešė visus dalykus, kuriuos jo tėvas Dovydas pašventė; sidabrą, auksą bei visus įrankius jis sudėjo tarp Dievo namų lobių.'),
  (@b14, 5, 2, 'Tada Saliamonas surinko Izraelio vyresniuosius ir visas genčių galvas, Izraelio vaikų tėvų vyriausiuosius, į Jeruzalę, kad atgabentų aukštyn VIEŠPATIES Sandoros skrynią iš Dovydo miesto, kuris yra Sionas.'),
  (@b14, 5, 3, 'Todėl visi Izraelio vyrai susirinko pas karalių į šventę, kuri buvo septintąjį mėnesį.'),
  (@b14, 5, 4, 'Ir atvyko visi Izraelio vyresnieji; ir levitai pakėlė skrynią.'),
  (@b14, 5, 5, 'Ir jie nešė aukštyn skrynią, susirinkimo padangtę ir visus šventuosius indus, buvusius padangtėje; šituos nešė aukštyn kunigai ir levitai.'),
  (@b14, 5, 6, 'Taip pat karalius Saliamonas ir visas Izraelio susirinkimas, kurie buvo susirinkę pas jį prieš skrynią, aukojo tokią daugybę avių ir jaučių, kad jų nebuvo galima nei nustatyti, nei suskaičiuoti.'),
  (@b14, 5, 7, 'Ir kunigai įnešė VIEŠPATIES Sandoros skrynią į jos vietą, į namų orakulą, į švenčiausiąją vietą – po kerubų sparnais;'),
  (@b14, 5, 8, 'nes kerubai išskėtė savo sparnus virš skrynios vietos, ir kerubai dengė iš viršaus skrynią ir jos kartis.'),
  (@b14, 5, 9, 'Ir jie ištraukė skrynios kartis, kad karčių galai buvo matomi nuo skrynios prieš orakulą; bet jie nebuvo matomi iš lauko. Ir jos ten yra iki šios dienos.'),
  (@b14, 5, 10, 'Skrynioje nebuvo nieko, išskyrus dvi plokštes, kurias Mozė ten įdėjo Horebe, kai VIEŠPATS sudarė sandorą su Izraelio vaikais, jiems išėjus iš Egipto.'),
  (@b14, 5, 11, 'Ir įvyko, kad kunigams išėjus iš šventosios vietos (nes visi ten esantys kunigai buvo pasišventę ir tarnavo ne pagal skyrių;'),
  (@b14, 5, 12, 'taip pat levitai, kurie buvo giedotojai, visi jie iš Asafo, iš Hemano, iš Jedutūno, su jų sūnumis ir jų broliais, apsivilkę baltu linu, turėdami cimbolus, psalterius ir arfas, stovėjo rytinėje aukuro pusėje, ir su jais šimtas dvidešimt kunigų, gaudžiančių trimitais),'),
  (@b14, 5, 13, 'įvyko, kai trimitininkai ir giedotojai buvo kaip vienas, kad išleistų vieną garsą, kad būtų išgirsti giriant ir dėkojant VIEŠPAČIUI; ir kai jie pakėlė savo balsus su trimitais, cimbolais ir kitais muzikiniais instrumentais ir gyrė VIEŠPATĮ, sakydami: „Nes jis yra geras, nes jo gailestingumas išlieka per amžius“; tuomet namai, būtent VIEŠPATIES namai, buvo pripildyti debesies;'),
  (@b14, 5, 14, 'taip, kad kunigai dėl debesies negalėjo stovėti, kad tarnautų; nes VIEŠPATIES šlovė pripildė Dievo namus.'),
  (@b14, 6, 1, 'Tada Saliamonas tarė: „VIEŠPATS sakė, kad jis nori gyventi tirštoje tamsoje.'),
  (@b14, 6, 2, 'Bet aš tau pastačiau gyvenamus namus ir vietą tau gyventi per amžius“.'),
  (@b14, 6, 3, 'Ir karalius, atsukęs veidą, palaimino visą Izraelio susirinkimą; o visas Izraelio susirinkimas stovėjo.'),
  (@b14, 6, 4, 'Ir jis tarė: „Tebūna palaimintas VIEŠPATS, Izraelio Dievas, kuris savo rankomis įvykdė tai, ką savo burna kalbėjo mano tėvui Dovydui, sakydamas:'),
  (@b14, 6, 5, '‘Nuo tos dienos, kai išvedžiau savo tautą iš Egipto šalies, neišsirinkau iš visų Izraelio genčių miesto statyti namams, kad ten būtų mano vardas; ir neišsirinkau jokio vyro, kad būtų mano tautos Izraelio valdovas;'),
  (@b14, 6, 6, 'bet išsirinkau Jeruzalę, kad ten būtų mano vardas; ir išsirinkau Dovydą, kad valdytų mano tautą Izraelį’.'),
  (@b14, 6, 7, 'Na, o tai buvo mano tėvo Dovydo širdyje statyti namus VIEŠPATIES, Izraelio Dievo, vardui.'),
  (@b14, 6, 8, 'Bet VIEŠPATS tarė mano tėvui Dovydui: ‘Kadangi tai buvo tavo širdyje statyti namus mano vardui, gerai darei, kad tai buvo tavo širdyje;'),
  (@b14, 6, 9, 'tačiau tu nestatysi namų; bet tavo sūnus, kuris išeis iš tavo strėnų, jis pastatys namus mano vardui’.'),
  (@b14, 6, 10, 'Taigi VIEŠPATS įvykdė savo žodį, kurį kalbėjo, nes aš kėliausi į savo tėvo Dovydo vietą ir atsisėdau Izraelio soste, kaip VIEŠPATS pažadėjo, ir pastačiau namus VIEŠPATIES, Izraelio Dievo, vardui.'),
  (@b14, 6, 11, 'Ir juose padėjau skrynią, kurioje yra VIEŠPATIES sandora, kurią jis sudarė su Izraelio vaikais“.'),
  (@b14, 6, 12, 'Ir jis atsistojo prieš VIEŠPATIES aukurą viso Izraelio susirinkimo akivaizdoje ir išskėtė rankas;'),
  (@b14, 6, 13, 'nes Saliamonas buvo padaręs penkių uolekčių ilgio, penkių uolekčių pločio ir trijų uolekčių aukščio žalvarinę pakylą ir ją pastatė kiemo viduryje; jis atsistojo ant jos, atsiklaupė ant kelių viso Izraelio susirinkimo akivaizdoje, išskėtė rankas į dangų'),
  (@b14, 6, 14, 'ir tarė: „O VIEŠPATIE, Izraelio Dieve, nei danguje, nei žemėje nėra Dievo, kuris būtų lygus tau; kuris laikytųsi sandoros ir parodytų gailestingumą savo tarnams, vaikščiojantiems tavo akivaizdoje visa savo širdimi;'),
  (@b14, 6, 15, 'tu ištesėjai savo tarnui Dovydui, mano tėvui tai, ką jam pažadėjai; ir kalbėjai savo burna bei išpildei tai savo ranka, kaip yra šią dieną.'),
  (@b14, 6, 16, 'Taigi dabar, o VIEŠPATIE, Izraelio Dieve, ištesėk savo tarnui Dovydui, mano tėvui tai, ką jam pažadėjai, sakydamas: ‘Tau nepritrūks vyro mano akivaizdoje, kad sėdėtų Izraelio soste; jei tik tavo vaikai žiūrėsis savo kelio, kad vaikščiotų pagal mano įstatymą, kaip tu vaikščiojai mano akivaizdoje’.'),
  (@b14, 6, 17, 'Tad dabar, o VIEŠPATIE, Izraelio Dieve, tepasitvirtina tavo žodis, kurį kalbėjai savo tarnui Dovydui.'),
  (@b14, 6, 18, 'Bet ar tikrai Dievas gyvens su žmonėmis žemėje? Štai dangus ir dangų dangus negali tavęs sutalpinti; tai kaip juo mažiau šitie namai, kuriuos pastačiau?!'),
  (@b14, 6, 19, 'Taigi atsižvelk į savo tarno maldą ir į jo prašymą, o VIEŠPATIE, mano Dieve, kad išklausytum šauksmą ir maldą, kuria tavo tarnas meldžiasi tavo akivaizdoje;'),
  (@b14, 6, 20, 'kad dieną ir naktį tavo akys būtų atvertos tiems namams, tai vietai, apie kurią sakei, kad ten pastatysi savo vardą; kad išklausytum maldą, kuria tavo tarnas melsis šitos vietos link.'),
  (@b14, 6, 21, 'Todėl išklausyk savo tarno ir savo tautos Izraelio prašymų, kuriais jie melsis šitos vietos link; išgirsk iš savo buveinės – iš dangaus; o išgirdęs atleisk.'),
  (@b14, 6, 22, 'Jei kas nusidės prieš savo artimą ir jam uždės priesaiką, kad prisaikdintų jį, ir ta priesaika ateis prieš tavo aukurą šituose namuose;'),
  (@b14, 6, 23, 'tuomet išgirsk iš dangaus ir veik, ir teisk savo tarnus, atlygindamas nedorėliui, atmokėdamas jo kelią ant jo paties galvos; ir išteisindamas teisųjį, duodamas jam pagal jo teisumą.'),
  (@b14, 6, 24, 'Jei tavo tauta Izraelis bus nugalėta tavo priešo akivaizdoje dėl to, kad jie prieš tave nusidėjo; ir jei sugrįš ir išpažins tavo vardą, melsis ir prašys tavo akivaizdoje šituose namuose;'),
  (@b14, 6, 25, 'tuomet išgirsk iš dangų ir atleisk savo tautos Izraelio nuodėmę, ir juos sugrąžink į šalį, kurią davei jiems ir jų tėvams.'),
  (@b14, 6, 26, 'Kai dangus bus uždarytas ir nebus lietaus dėl to, kad jie prieš tave nusidėjo; tačiau jeigu jie melsis šitos vietos link ir išpažins tavo vardą, ir nusigręš nuo savo nuodėmės, kai tu juos varginsi;'),
  (@b14, 6, 27, 'tuomet išgirsk iš dangaus ir atleisk savo tarnų bei savo tautos Izraelio nuodėmę, pamokęs juos gerojo kelio, kuriuo jie turi vaikščioti; ir pasiųsk lietaus savo šaliai, kurią davei savo tautai kaip paveldą.'),
  (@b14, 6, 28, 'Jei badas bus šalyje, jei bus maras, jei bus džiovinantis pūtimas ar pelėsiai, skėriai ar vikšrai; jei jų priešai juos apguls jų šalies miestuose; kokia bebus žaizda ar liga;'),
  (@b14, 6, 29, 'tuomet kokia malda ar kokiu prašymu melsis koks nors žmogus ar visa tavo tauta Izraelis, kai kiekvienas pažins savo žaizdą ir savo sielvartą, ir išskės rankas šituose namuose;'),
  (@b14, 6, 30, 'tuomet išgirsk iš dangaus, savo gyvenamos vietos, ir atleisk, ir duok kiekvienam, kurio širdį tu pažįsti, pagal visus jo kelius (nes tu vienintelis pažįsti žmonių vaikų širdis);'),
  (@b14, 6, 31, 'kad jie tavęs bijotų, vaikščiodami tavo keliais tol, kol jie gyvens šalyje, kurią davei mūsų tėvams.'),
  (@b14, 6, 32, 'Taip pat dėl ateivio, kuris nėra iš tavo tautos Izraelio, bet yra atėjęs iš tolimo krašto dėl tavo didžiojo vardo, dėl tavo galingos rankos ir tavo ištiestos rankos; jei jie ateis ir melsis šiuose namuose;'),
  (@b14, 6, 33, 'tuomet išgirsk iš dangų – iš savo gyvenamos vietos, ir padaryk pagal visa tai, dėl ko ateivis tavęs šauksis; kad visos žemės tautos pažintų tavo vardą ir tavęs bijotų kaip tavo tauta Izraelis, ir kad žinotų, kad šitie namai, kuriuos pastačiau, yra vadinami tavo vardu.'),
  (@b14, 6, 34, 'Jei tavo tauta išeis į karą prieš savo priešus keliu, kuriuo tu juos pasiųsi, ir tau melsis link šito miesto, kurį išsirinkai, ir link namų, kuriuos pastačiau tavo vardui;'),
  (@b14, 6, 35, 'tuomet išgirsk iš dangų jų maldą bei jų prašymą ir paremk jų reikalą.'),
  (@b14, 6, 36, 'Jeigu jie prieš tave nusidės (nes nėra žmogaus, kuris nenusidėtų), o tu, supykęs ant jų, juos atiduosi jų priešų akivaizdoje, ir jie nusives juos nelaisvėn į tolimą ar artimą šalį;'),
  (@b14, 6, 37, 'tačiau jeigu jie susiprotės šalyje, į kurią bus išvesti į nelaisvę, ir atsigręš, ir tau melsis savo nelaisvės šalyje, sakydami: ‘Mes nusidėjome, neteisingai elgėmės ir padarėme nedorybę’,'),
  (@b14, 6, 38, 'jei jie sugrįš pas tave visa savo širdimi bei visa savo siela savo nelaisvės šalyje, į kurią juos išvedė nelaisvėn, ir melsis link savo šalies, kurią davei jų tėvams, ir link miesto, kurį išsirinkai, ir link namų, kuriuos pastačiau tavo vardui;'),
  (@b14, 6, 39, 'tuomet išgirsk iš dangų – iš savo gyvenamos vietos, jų maldą bei jų prašymus ir paremk jų reikalą, ir atleisk savo tautai, kuri tau nusidėjo.'),
  (@b14, 6, 40, 'Dabar, mano Dieve, meldžiu tave, tebūna tavo akys atviros ir tavo ausys dėmesingos maldai, atliekamai šitoje vietoje.'),
  (@b14, 6, 41, 'Taigi dabar pakilk, o VIEŠPATIE Dieve, į savo poilsio vietą, tu ir tavo stiprybės skrynia; tavo kunigai, o VIEŠPATIE Dieve, tebūna apsirengę išgelbėjimu ir tegul tavo šventieji džiaugiasi gerumu.'),
  (@b14, 6, 42, 'O VIEŠPATIE Dieve, nenugręžk savo pateptojo veido; atsimink savo tarno Dovydo gailestingumus“.'),
  (@b14, 7, 1, 'Na, o Saliamonui baigus melstis, ugnis nusileido iš dangaus ir prarijo deginamąją atnašą ir aukas; ir VIEŠPATIES šlovė pripildė namus.'),
  (@b14, 7, 2, 'Ir kunigai negalėjo įeiti į VIEŠPATIES namus, nes VIEŠPATIES šlovė buvo pripildžiusi VIEŠPATIES namus.'),
  (@b14, 7, 3, 'O visi Izraelio vaikai, pamatę kaip nusileido ugnis ir VIEŠPATIES šlovė ant namų, nusilenkė ant grindinio savo veidais iki žemės ir garbino, ir gyrė VIEŠPATĮ, sakydami: „Nes jis yra geras; nes jo gailestingumas pasilieka per amžius“.'),
  (@b14, 7, 4, 'Tada karalius ir visa tauta atnašavo aukas VIEŠPATIES akivaizdoje.'),
  (@b14, 7, 5, 'Ir karalius Saliamonas atnašavo dvidešimt dviejų tūkstančių jaučių ir šimto dvidešimties tūkstančių avių auką; taip karalius ir visa tauta pašventė Dievo namus.'),
  (@b14, 7, 6, 'O kunigai patarnavo savo tarnybose; taip pat levitai su VIEŠPATIES muzikos instrumentais, kuriuos buvo padaręs karalius Dovydas VIEŠPAČIUI girti, nes jo gailestingumas pasilieka per amžius, kai Dovydas girdavo per jų tarnystę; ir priešais juos kunigai gaudė trimitais, o visas Izraelis stovėjo.'),
  (@b14, 7, 7, 'Saliamonas dar pašventė vidurį kiemo, esančio prieš VIEŠPATIES namus; nes ten jis aukojo deginamąsias atnašas ir taikos atnašų taukus, nes žalvarinis aukuras, kurį Saliamonas buvo padaręs, nepajėgė sutalpinti deginamųjų atnašų, maisto atnašų ir taukų.'),
  (@b14, 7, 8, 'Taip pat tuo pačiu metu Saliamonas šventė šventę septynias dienas ir su juo visas Izraelis, labai didelis susirinkimas, nuo Hamato įėjimo iki Egipto upės.'),
  (@b14, 7, 9, 'O aštuntąją dieną jie suruošė iškilmingą susirinkimą; nes jie šventė aukuro pašventimą septynias dienas ir šventę septynias dienas.'),
  (@b14, 7, 10, 'O septintojo mėnesio dvidešimt trečiąją dieną jis paleido tautą į jų palapines, džiaugsmingus ir linksmus širdimi dėl gerumo, kurį VIEŠPATS buvo parodęs Dovydui, Saliamonui ir savo tautai Izraeliui.'),
  (@b14, 7, 11, 'Taip Saliamonas užbaigė VIEŠPATIES namus bei karaliaus namus; ir visa, kas atėjo į Saliamono širdį, kad padarytų VIEŠPATIES namuose ir savo namuose, jis sėkmingai atliko.'),
  (@b14, 7, 12, 'Ir VIEŠPATS naktį pasirodė Saliamonui ir jam tarė: „Aš išgirdau tavo maldą ir išsirinkau šitą vietą sau aukų namais.'),
  (@b14, 7, 13, 'Jei aš uždarysiu dangų, kad nebus lietaus, arba jei įsakysiu skėriams, kad nuėstų šalį, arba jei atsiųsiu marą į savo tautos tarpą;'),
  (@b14, 7, 14, 'jei mano tauta, kuri vadinasi mano vardu, nusižemins ir melsis, ir ieškos mano veido, ir nusisuks nuo savo piktų kelių; tada aš išgirsiu iš dangaus, atleisiu jų nuodėmę ir pagydysiu jų šalį.'),
  (@b14, 7, 15, 'Dabar mano akys bus atviros ir mano ausys dėmesingos maldai, atliktai šitoje vietoje.'),
  (@b14, 7, 16, 'Nes dabar išsirinkau ir pašvenčiau šituos namus, kad mano vardas ten būtų per amžius; ir mano akys ir mano širdis ten bus nuolatos.'),
  (@b14, 7, 17, 'O dėl tavęs, jei tu vaikščiosi mano akivaizdoje, kaip vaikščiojo tavo tėvas Dovydas, ir darysi pagal visa tai, ką tau įsakiau, ir laikysies mano įstatų bei mano teismų;'),
  (@b14, 7, 18, 'tada įtvirtinsiu tavo karalystės sostą pagal tai, kaip sudariau sandorą su tavo tėvu Dovydu, sakydamas: ‘Tau nepritrūks vyro, kad būtų valdovu Izraelyje’.'),
  (@b14, 7, 19, 'Bet jei jūs nusigręšite ir paliksite mano įstatus ir mano įsakymus, kuriuos išstačiau jūsų akivaizdoje, ir nuėję tarnausite kitiems dievams ir juos garbinsite;'),
  (@b14, 7, 20, 'tada juos išrausiu su šaknimis iš savo šalies, kurią jiems daviau; o šituos namus, kuriuos pašvenčiau savo vardui, išmesiu sau iš akių ir juos padarysiu patarle bei priežodžiu visų tautų tarpe.'),
  (@b14, 7, 21, 'Ir šitie namai, kurie yra aukšti, bus nuostaba kiekvienam, praeinančiajam jiems pro šalį; taip, kad sakys: ‘Kodėl VIEŠPATS taip padarė šitai šaliai ir šitiems namams?’'),
  (@b14, 7, 22, 'Ir bus atsakyta: ‘Kadangi jie paliko VIEŠPATĮ, savo tėvų Dievą, kuris juos išvedė iš Egipto šalies, ir, įsikibę į kitus dievus, juos garbino ir jiems tarnavo; todėl jis užleido ant jų visą šitą nelaimę’“.'),
  (@b14, 8, 1, 'Ir įvyko, kad pasibaigus dvidešimčiai metų, per kuriuos Saliamonas statė VIEŠPATIES namus bei savo namus,'),
  (@b14, 8, 2, 'Saliamonas pastatė miestus, kuriuos Huramas buvo sugrąžinęs Saliamonui, ir juose apgyvendino Izraelio vaikus.'),
  (@b14, 8, 3, 'Ir Saliamonas nuėjo į Hamat-Cobą ir ją nugalėjo.'),
  (@b14, 8, 4, 'Ir jis pastatė Tadmorą dykumoje ir visus sandėlių miestus, kuriuos jis pastatė Hamate.'),
  (@b14, 8, 5, 'Taip pat jis pastatė aukštutinįjį Bet-Horoną ir žemutinįjį Bet-Horoną, aptvertus miestus su sienomis, vartais ir skląsčiais;'),
  (@b14, 8, 6, 'ir Baalatą, ir visus sandėlių miestus, kuriuos turėjo Saliamonas, ir visus vežimų miestus, raitelių miestus ir visa, ką Saliamonas troško pastatyti Jeruzalėje, Libane ir visame savo valdžios krašte.'),
  (@b14, 8, 7, 'Visą liaudį, išlikusią iš hetitų, amoritų, perizų, hivų ir jebusiečių, kurie nebuvo iš Izraelio,'),
  (@b14, 8, 8, 'bet iš jų vaikų, išlikusių po jų šalyje, kurių Izraelio vaikai neišnaikino, tuos Saliamonas privertė mokėti duoklę iki šios dienos.'),
  (@b14, 8, 9, 'Bet iš Izraelio vaikų Saliamonas nepadarė tarnų savo darbui; bet jie buvo karo vyrai, jo vadų vyriausieji ir jo vežimų bei raitelių vadai.'),
  (@b14, 8, 10, 'Ir šitie buvo vyriausieji karaliaus Saliamono pareigūnai, būtent du šimtai penkiasdešimt, valdantys tautą.'),
  (@b14, 8, 11, 'Ir Saliamonas nuvedė faraono dukterį iš Dovydo miesto aukštyn į namus, kuriuos jis buvo jai pastatęs; nes jis sakė: „Mano žmona negyvens Izraelio karaliaus Dovydo rūmuose, nes tos vietos yra šventos, į kurias atėjo VIEŠPATIES skrynia“.'),
  (@b14, 8, 12, 'Tada Saliamonas atnašavo VIEŠPAČIUI deginamąsias atnašas ant VIEŠPATIES aukuro, kurį jis buvo pastatęs prieš prieangį,'),
  (@b14, 8, 13, 'būtent pagal tam tikrą normą, kiekvieną dieną atnašaudamas pagal Mozės įsakymą, sabatais, per jauną mėnulį ir per iškilmingas šventes tris kartus metuose, būtent per Neraugintos duonos šventę, per Savaičių šventę ir per Padangčių šventę.'),
  (@b14, 8, 14, 'Jis paskyrė, kaip jo tėvo Dovydo nustatyta, kunigų skyrius jų tarnavimui ir levitus jų pareigoms, kad girtų ir tarnautų kunigų akivaizdoje, kaip reikalavo kiekvienos dienos pareiga; taip pat durininkus pagal jų skyrius kiekvieniems vartams; nes taip buvo įsakęs Dievo vyras Dovydas.'),
  (@b14, 8, 15, 'Ir jie neatsitraukė nuo karaliaus įsakymo kunigams ir levitams jokiame dalyke nei tame, kas susiję su lobiais.'),
  (@b14, 8, 16, 'Na, o visas Saliamono darbas buvo paruoštas iki VIEŠPATIES namų pamato padėjimo dienos ir kol jis buvo užbaigtas. Taigi VIEŠPATIES namai buvo užbaigti.'),
  (@b14, 8, 17, 'Tada Saliamonas nuvyko į Ecjon-Geberą ir į Elotą, prie jūros kranto Edomo šalyje.'),
  (@b14, 8, 18, 'Ir Huramas jam nusiuntė per savo tarnų rankas laivų ir tarnų, išmanančių apie jūrą; ir nuvykę su Saliamono tarnais į Ofyrą, jie iš ten paėmė keturis šimtus penkiasdešimt talentų aukso ir jį atgabeno karaliui Saliamonui.'),
  (@b14, 9, 1, 'Ir Šebos karalienė, išgirdusi garsą apie Saliamoną, atvyko išmėginti Saliamoną sunkiais klausimais į Jeruzalę su labai dideliu būriu ir kupranugariais, nešančiais kvepalus, gausybę aukso ir brangakmenių; ir atėjusi pas Saliamoną, ji kalbėjosi su juo apie viską, kas buvo jos širdyje.'),
  (@b14, 9, 2, 'O Saliamonas jai paaiškino viską, ko ji klausė; nieko nebuvo paslėpta nuo Saliamono, ko jis nebūtų jai paaiškinęs.'),
  (@b14, 9, 3, 'Ir kai Šebos karalienė pamatė Saliamono išmintį ir namus, kuriuos jis buvo pastatęs,'),
  (@b14, 9, 4, 'jo stalo valgius, jo tarnų sėdėjimą, jo tarnų patarnavimą ir jų apdarus; taip pat jo taurininkus ir jų apdarus; ir jo pakilimą, kuriuo jis eidavo aukštyn į VIEŠPATIES namus; ji neteko žado.'),
  (@b14, 9, 5, 'Ir ji tarė karaliui: „Atsiliepimas, kurį girdėjau savo šalyje apie tavo darbus ir apie tavo išmintį, buvo tiesa;'),
  (@b14, 9, 6, 'tačiau aš netikėjau jų žodžiais, kol neatvykau, ir mano akys to nepamatė; ir štai man nebuvo pranešta nei pusės apie tavo išminties didybę; nes tu pranoksti gandą, kurį girdėjau.'),
  (@b14, 9, 7, 'Laimingi yra tavo žmonės ir laimingi yra šitie tavo tarnai, kurie nuolat stovi tavo akivaizdoje ir girdi tavo išmintį.'),
  (@b14, 9, 8, 'Tebūna palaimintas VIEŠPATS, tavo Dievas, kuris gėrėjosi tavimi, kad pasodintų tave į savo sostą, kad būtum karalius VIEŠPAČIUI, savo Dievui; kadangi tavo Dievas myli Izraelį, kad juos įtvirtintų per amžius, todėl jis tave padarė jiems karaliumi vykdyti teismą ir teisingumą“.'),
  (@b14, 9, 9, 'Ir ji davė karaliui šimtą dvidešimt talentų aukso ir didelę gausybę kvepalų, ir brangiųjų akmenų; nebuvo tokių kvepalų, kokius Šebos karalienė davė karaliui Saliamonui.'),
  (@b14, 9, 10, 'Taip pat Huramo tarnai ir Saliamono tarnai, kurie pargabeno aukso iš Ofyro, pargabeno algumo medžių ir brangiųjų akmenų.'),
  (@b14, 9, 11, 'Ir karalius padarė iš algumo medžių pakopas VIEŠPATIES namams bei karaliaus rūmams ir arfas, ir psalterius giesmininkams; nieko tokio anksčiau nebuvo matyta Judos šalyje.'),
  (@b14, 9, 12, 'Ir karalius Saliamonas davė Šebos karalienei viską, ko ji norėjo ir ko ji prašė, neskaitant to, ką ji buvo atgabenusi karaliui. Taigi ji apsigręžė ir išėjo į savo šalį, ji ir jos tarnai.'),
  (@b14, 9, 13, 'Na, o svoris aukso, kuris per vienerius metus ateidavo Saliamonui, buvo šeši šimtai šešiasdešimt šeši aukso talentai;'),
  (@b14, 9, 14, 'neskaitant to, ką atgabendavo keliaujantys pirkliai ir prekiautojai. Ir visi Arabijos karaliai ir krašto valdytojai atgabendavo Saliamonui aukso ir sidabro.'),
  (@b14, 9, 15, 'Karalius Saliamonas padarė du šimtus didžiųjų skydų iš kalto aukso; šeši šimtai kalto aukso šekelių suėjo vienam didžiajam skydui.'),
  (@b14, 9, 16, 'Ir tris šimtus mažųjų skydų jis padarė iš kalto aukso; trys šimtai aukso šekelių suėjo vienam mažajam skydui. Ir karalius juos sudėjo Libano miško namuose.'),
  (@b14, 9, 17, 'Karalius dar padarė didžiulį sostą iš dramblio kaulo ir jį padengė grynu auksu.'),
  (@b14, 9, 18, 'Prie to sosto buvo šeši laiptai su aukso pakoju, pritvirtinti prie sosto, ir atramos kiekvienoje sėdimos vietos pusėje, ir du liūtai, stovintys šalia atramų;'),
  (@b14, 9, 19, 'dvylika liūtų ten stovėjo ant šešių laiptų vienoje ir kitoje pusėje. Nebuvo tokio padaryto jokioje karalystėje.'),
  (@b14, 9, 20, 'Visi karaliaus Saliamono geriamieji indai buvo iš aukso, ir visi Libano miško namų indai buvo iš gryno aukso; nieko nebuvo iš sidabro; Saliamono dienomis jis neturėjo jokios vertės.'),
  (@b14, 9, 21, 'Nes karaliaus laivai vyko į Taršišą su Huramo tarnais; vieną kartą per trejus metus atvykdavo Taršišo laivai, atgabendami aukso ir sidabro, dramblio kaulo, beždžionių ir povų.'),
  (@b14, 9, 22, 'Ir karalius Saliamonas viršijo visus žemės karalius turtais ir išmintimi.'),
  (@b14, 9, 23, 'Ir visi žemės karaliai siekė Saliamono veido, kad išgirstų jo išmintį, kurią Dievas jam buvo įdėjęs į širdį.'),
  (@b14, 9, 24, 'Ir metai po metų jie kiekvienas atnešdavo savo dovaną: sidabrinių indų ir auksinių indų, rūbų, šarvų, kvepalų, žirgų ir mulų.'),
  (@b14, 9, 25, 'Ir Saliamonas turėjo keturis tūkstančius gardų žirgams bei vežimams ir dvylika tūkstančių raitelių; kuriuos jis paskyrė į vežimų miestus ir pas karalių Jeruzalėje.'),
  (@b14, 9, 26, 'Ir jis karaliavo visiems karaliams nuo upės iki filistinų šalies ir iki Egipto ribos.'),
  (@b14, 9, 27, 'Ir karalius padarė, kad Jeruzalėje sidabro buvo kaip akmenų, o kedrus padarė, kad būtų gausūs kaip sikomorų medžiai, esantys žemose lygumose.'),
  (@b14, 9, 28, 'Ir Saliamonui atgabendavo žirgų iš Egipto ir iš visų šalių.'),
  (@b14, 9, 29, 'Na, o kiti Saliamono darbai, pirmieji ir paskutinieji, argi jie nėra užrašyti pranašo Natano knygoje, šilojiečio Ahijos pranašystėje ir regėtojo Idojo regėjimuose prieš Nebato sūnų Jeroboamą?'),
  (@b14, 9, 30, 'Ir Saliamonas karaliavo Jeruzalėje visam Izraeliui keturiasdešimt metų.'),
  (@b14, 9, 31, 'Ir Saliamonas užmigo prie savo tėvų ir buvo palaidotas jo tėvo Dovydo mieste; o jo sūnus Rehoboamas karaliavo jo vietoje.'),
  (@b14, 10, 1, 'Ir Rehoboamas nuvyko į Šechemą; nes visas Izraelis buvo atėjęs į Šechemą, kad padarytų jį karaliumi.'),
  (@b14, 10, 2, 'Ir įvyko, kai Nebato sūnus Jeroboamas, būdamas Egipte, kur buvo pabėgęs nuo karaliaus Saliamono, tai išgirdo, Jeroboamas sugrįžo iš Egipto.'),
  (@b14, 10, 3, 'Ir jie pasiuntė ir jį pakvietė. Taigi Jeroboamas ir visas Izraelis atėjo ir kalbėjo Rehoboamui, sakydami:'),
  (@b14, 10, 4, '„Tavo tėvas padarė mūsų jungą sunkų; taigi dabar šiek tiek palengvink savo tėvo sunkią vergiją ir jo sunkų jungą, kurį jis mums uždėjo, ir mes tau tarnausime“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b14, 10, 5, 'O jis jiems tarė: „Po trijų dienų sugrįžkite pas mane“. Ir tauta išėjo.'),
  (@b14, 10, 6, 'Ir karalius Rehoboamas tarėsi su senesniaisiais, kurie stovėjo jo tėvo Saliamono akivaizdoje, kol jis dar buvo gyvas, sakydamas: „Ką man patarsite, kad atsakyčiau šitai tautai?“'),
  (@b14, 10, 7, 'Ir jie jam tarė, sakydami: „Jei būsi malonus šitai tautai, jiems įtiksi ir jiems kalbėsi gerus žodžius, jie bus tavo tarnai per amžius“.'),
  (@b14, 10, 8, 'Bet jis atsisakė patarimo, kurį jam davė senesnieji, ir tarėsi su jaunuoliais, kurie buvo užaugę su juo, kurie stovėjo jo akivaizdoje.'),
  (@b14, 10, 9, 'Ir jis jiems tarė: „Ką mums patarsite, kad atsakytume šitai tautai, kuri man kalbėjo, sakydama: ‘Šiek tiek palengvink jungą, kurį mums uždėjo tavo tėvas’?“'),
  (@b14, 10, 10, 'O tie jaunuoliai, kurie buvo užaugę su juo, jam kalbėjo, sakydami: „Taip atsakyk tautai, kuri tau kalbėjo, sakydama: ‘Tavo tėvas padarė mūsų jungą sunkų, bet tu jį mums šiek tiek palengvink’; taip jiems sakyk: ‘Mano mažasis pirštas bus storesnis už mano tėvo strėnas.'),
  (@b14, 10, 11, 'Kadangi mano tėvas jums uždėjo sunkų jungą, aš dar daugiau uždėsiu ant jūsų jungo; mano tėvas jus baudė botagais, bet aš jus bausiu skorpionais“.'),
  (@b14, 10, 12, 'Taigi trečią dieną Jeroboamas ir visa tauta atėjo pas Rehoboamą, kaip karalius liepė, sakydamas: „Sugrįškite pas mane trečią dieną“.'),
  (@b14, 10, 13, 'Ir karalius jiems šiurkščiai atsakė; ir karalius Rehoboamas atsisakė senesniųjų patarimo'),
  (@b14, 10, 14, 'ir atsakė jiems pagal jaunuolių patarimą, sakydamas: „Mano tėvas padarė jūsų jungą sunkų, bet aš prie jo pridėsiu; mano tėvas baudė jus botagais, bet aš jus bausiu skorpionais“.'),
  (@b14, 10, 15, 'Taip karalius nepaklausė tautos; nes tas dalykas buvo iš Dievo, kad VIEŠPATS įvykdytų savo žodį, kurį jis kalbėjo per šilojiečio Ahijos ranką Nebato sūnui Jeroboamui.'),
  (@b14, 10, 16, 'Ir visam Izraeliui pamačius, kad karalius nenorėjo jų klausyti, tauta atsakė karaliui, sakydama: „Kokią gi dalį mes turime Dovyde? Mes neturime paveldo Jesės sūnuje; kiekvienas į savo palapines, o Izraeli; o dabar žiūrėk savo namus, Dovydai“. Taip visas Izraelis nuėjo į savo palapines.'),
  (@b14, 10, 17, 'Bet Izraelio vaikams, gyvenantiems Judos miestuose, karaliavo Rehoboamas.'),
  (@b14, 10, 18, 'Tada karalius Rehoboamas pasiuntė Hadoramą, duoklės prižiūrėtoją; o Izraelio vaikai jį užmėtė akmenimis, jog jis mirė. Bet karalius Rehoboamas skubiai įlipo į savo vežimą, kad pabėgtų į Jeruzalę.'),
  (@b14, 10, 19, 'Ir Izraelis iki šios dienos maištavo prieš Dovydo namus.'),
  (@b14, 11, 1, 'Ir Rehoboamas, atvykęs į Jeruzalę, surinko iš Judos ir Benjamino namų šimtą aštuoniasdešimt tūkstančių rinktinių vyrų, karių, kad kariautų prieš Izraelį, kad sugrąžintų karalystę Rehoboamui.'),
  (@b14, 11, 2, 'Bet VIEŠPATIES žodis atėjo Dievo vyrui Šemajai, sakydamas:'),
  (@b14, 11, 3, '„Kalbėk Saliamono sūnui Rehoboamui, Judos karaliui, ir visam Izraeliui Judoje ir Benjamine, sakydamas:'),
  (@b14, 11, 4, 'Taip sako VIEŠPATS: ‘Neikite aukštyn ir nekovokite prieš savo brolius; kiekvienas grįžkite į savo namus; nes tas dalykas mano padarytas’“. Ir jie pakluso VIEŠPATIES žodžiams ir sugrįžo nuo ėjimo prieš Jeroboamą.'),
  (@b14, 11, 5, 'O Rehoboamas gyveno Jeruzalėje ir pastatė miestus gynybai Judoje.'),
  (@b14, 11, 6, 'Jis pastatė būtent Betliejų, Etamą, Tekoją,'),
  (@b14, 11, 7, 'Bet-Cūrą, Sokoją, Adulamą,'),
  (@b14, 11, 8, 'Gatą, Marešą, Zifą,'),
  (@b14, 11, 9, 'Adorajimą, Lachišą, Azeką,'),
  (@b14, 11, 10, 'Corą, Ajaloną ir Hebroną, kurie yra aptverti miestai Judoje ir Benjamine.'),
  (@b14, 11, 11, 'Ir jis sustiprino tvirtoves ir patalpino jose vadus ir maisto, aliejaus bei vyno sandėlius.'),
  (@b14, 11, 12, 'Ir kiekviename atskirame mieste jis sudėjo skydų, iečių ir labai juos sustiprino, turėdamas Judą ir Benjaminą savo pusėje.'),
  (@b14, 11, 13, 'O kunigai ir levitai, esantys visame Izraelyje, rinkosi pas jį iš visų savo ribų.'),
  (@b14, 11, 14, 'Nes levitai paliko savo priemiesčius bei savo nuosavybę ir atvyko į Judą bei Jeruzalę; nes Jeroboamas ir jo sūnūs buvo juos išmetę iš kunigo tarnystės VIEŠPAČIUI vykdymo;'),
  (@b14, 11, 15, 'ir jis paskyrė sau kunigų aukštumoms, velniams ir veršiams, kuriuos jis buvo padaręs.'),
  (@b14, 11, 16, 'Ir paskui juos iš visų Izraelio genčių atvyko į Jeruzalę tie, kurie nukreipė savo širdis ieškoti VIEŠPATIES, Izraelio Dievo, kad aukotų VIEŠPAČIUI, savo tėvų Dievui.'),
  (@b14, 11, 17, 'Taip jie sustiprino Judos karalystę ir padarė Saliamono sūnų Rehoboamą stiprų per trejus metus; nes trejus metus jie vaikščiojo Dovydo ir Saliamono keliu.'),
  (@b14, 11, 18, 'Ir Rehoboamas ėmė į žmonas Mahalatą, Dovydo sūnaus Jerimoto dukterį ir Jesės sūnaus Eliabo dukterį Abihailę;'),
  (@b14, 11, 19, 'kuri jam pagimdė vaikų: Jeušą, Šamariją ir Zahamą.'),
  (@b14, 11, 20, 'Po jos jis ėmė Absalomo dukterį Maaką; kuri jam pagimdė Abiją, Atają, Zizą ir Šelomitą.'),
  (@b14, 11, 21, 'Rehoboamas mylėjo Absalomo dukterį Maaką labiau už visas savo žmonas ir suguloves (nes jis ėmė aštuoniolika žmonų bei šešiasdešimt sugulovių; ir pagimdė dvidešimt aštuonis sūnus ir šešiasdešimt dukterų);'),
  (@b14, 11, 22, 'ir Rehoboamas paskyrė Maakos sūnų Abiją vyriausiuoju, kad būtų valdovu tarp jo brolių; nes jis manė padaryti jį karaliumi.'),
  (@b14, 11, 23, 'Ir jis elgėsi išmintingai ir išskirstė iš visų savo vaikų po visas Judos ir Benjamino šalis į kiekvieną aptvertą miestą; ir jis gausiai jiems davė maisto. Ir jis troško daug žmonų.'),
  (@b14, 12, 1, 'Ir įvyko, kai Rehoboamas įtvirtino karalystę ir sustiprėjo, jis paliko VIEŠPATIES įstatymą, o su juo ir visas Izraelis.'),
  (@b14, 12, 2, 'Ir įvyko, kad penktaisiais karaliaus Rehoboamo metais Egipto karalius Šišakas atėjo aukštyn prieš Jeruzalę, kadangi jie nusižengė prieš VIEŠPATĮ,'),
  (@b14, 12, 3, 'su tūkstančiu dviem šimtais vežimų ir šešiasdešimčia tūkstančių raitelių; o žmonių, kurie atėjo su juo iš Egipto, buvo be skaičiaus: libiai, sukijai ir etiopai.'),
  (@b14, 12, 4, 'Jis paėmė Judai priklausančius aptvertus miestus ir atėjo į Jeruzalę.'),
  (@b14, 12, 5, 'Tada pranašas Šemaja atėjo pas Rehoboamą ir Judos kunigaikščius, dėl Šišako susirinkusius į Jeruzalę, ir jiems tarė: „Taip sako VIEŠPATS: ‘Jūs mane palikote, todėl ir aš jus palikau Šišako rankoje’“.'),
  (@b14, 12, 6, 'Tada Izraelio kunigaikščiai ir karalius nusižemino; ir jie tarė: „VIEŠPATS yra teisus“.'),
  (@b14, 12, 7, 'Ir VIEŠPAČIUI pamačius, kad jie nusižemino, VIEŠPATIES žodis atėjo Šemajai, sakydamas: „Jie nusižemino; todėl aš jų nesunaikinsiu, bet jiems suteiksiu šiokį tokį išgelbėjimą; ir mano rūstybė neišsilies ant Jeruzalės per Šišako ranką.'),
  (@b14, 12, 8, 'Tačiau jie bus jo tarnai; kad žinotų mano tarnavimą ir šalių karalysčių tarnavimą“.'),
  (@b14, 12, 9, 'Taigi Egipto karalius Šišakas atėjo aukštyn prieš Jeruzalę ir paėmė VIEŠPATIES namų lobius bei karaliaus namų lobius; jis viską pasiėmė; jis taip pat išsinešė aukso skydus, kuriuos Saliamonas buvo padaręs.'),
  (@b14, 12, 10, 'Jų vietoje karalius Rehoboamas padarė žalvario skydus ir juos pavedė į rankas sargybos vyriausiųjų, saugojančių karaliaus namų įėjimą.'),
  (@b14, 12, 11, 'Ir karaliui įeinant į VIEŠPATIES namus, atėję sargybiniai juos nešdavo ir juos parnešdavo į sargybos kambarį.'),
  (@b14, 12, 12, 'Ir kai jis nusižemino, VIEŠPATIES rūstybė nusisuko nuo jo, kad jo visiškai nesunaikintų; ir Judoje taipogi reikalai gerai sekėsi.'),
  (@b14, 12, 13, 'Taip karalius Rehoboamas sustiprėjo Jeruzalėje ir karaliavo; nes Rehoboamas buvo keturiasdešimt vienerių metų, kai pradėjo karaliauti, ir septyniolika metų karaliavo Jeruzalėje, tame mieste, kurį VIEŠPATS buvo išsirinkęs iš visų Izraelio genčių, kad ten pastatytų savo vardą. O jo motinos vardas buvo Naama, amonietė.'),
  (@b14, 12, 14, 'Ir jis darė pikta, nes neparuošė savo širdies, kad ieškotų VIEŠPATIES.'),
  (@b14, 12, 15, 'Na, o Rehoboamo darbai, pirmieji ir paskutinieji, argi jie nėra užrašyti pranašo Šemajo ir regėtojo Idojo knygoje apie genealogijas? Ir nuolat buvo karai tarp Rehoboamo ir Jeroboamo.'),
  (@b14, 12, 16, 'Ir Rehoboamas užmigo prie savo tėvų ir buvo palaidotas Dovydo mieste; o jo sūnus Abija karaliavo jo vietoje.'),
  (@b14, 13, 1, 'Na, o aštuonioliktaisiais karaliaus Jeroboamo metais Abija pradėjo karaliauti Judai.'),
  (@b14, 13, 2, 'Jis trejus metus karaliavo Jeruzalėje. Jo motinos vardas buvo Mikaja, Urielio iš Gibėjos duktė. Ir buvo karas tarp Abijos ir Jeroboamo.'),
  (@b14, 13, 3, 'Ir Abija išsirikiavo į mūšį su narsių karo vyrų, būtent keturių šimtų tūkstančių rinktinių vyrų, kariuomene; Jeroboamas taip pat išsirikiavo į mūšį prieš jį su aštuoniais šimtais tūkstančių rinktinių vyrų, galingų narsuolių.'),
  (@b14, 13, 4, 'Ir Abija atsistojo ant Cemaraimo kalno, esančio Efraimo kalne, ir tarė: „Pasiklausyk manęs, Jeroboamai ir visas Izraeli;'),
  (@b14, 13, 5, 'argi jūs neturėtumėte žinoti, kad VIEŠPATS, Izraelio Dievas, amžiams davė karalystę Dovydui, kad valdytų Izraelį, būtent jam ir jo sūnums pagal druskos sandorą?'),
  (@b14, 13, 6, 'Tačiau Nebato sūnus Jeroboamas, Dovydo sūnaus Saliamono tarnas, pakilęs maištavo prieš savo viešpatį.'),
  (@b14, 13, 7, 'Pas jį susirinko tušti žmonės, Belialo vaikai, ir sustiprėjo prieš Saliamono sūnų Rehoboamą, kai Rehoboamas buvo jaunas bei minkštaširdis ir negalėjo atsilaikyti prieš juos.'),
  (@b14, 13, 8, 'O dabar jūs manote atsilaikyti prieš VIEŠPATIES karalystę Dovydo sūnų rankose; jūsų yra didelė daugybė ir su jumis yra auksiniai veršiai, kuriuos Jeroboamas jums padarė kaip dievus.'),
  (@b14, 13, 9, 'Argi neišvarėte VIEŠPATIES kunigų, Aarono sūnų ir levitų, ir ar nepasidarėte kunigų pagal kitų šalių tautų būdą? Taip, kad jei kas ateina save įšventinti su jaunikliu jaučiu ir septyniais avinais, tas gali būti kunigas tų, kurie nėra dievai.'),
  (@b14, 13, 10, 'Bet mes, VIEŠPATS yra mūsų Dievas, ir mes jo nepalikome; ir kunigai, kurie tarnauja VIEŠPAČIUI, yra Aarono sūnūs, o levitai patarnauja jų reikalams;'),
  (@b14, 13, 11, 'jie kas rytą ir kas vakarą degina VIEŠPAČIUI deginamąsias aukas ir kvapius smilkalus; taip pat sudėlioja parodomąją duoną ant gryno stalo; ir aukso žvakidę su jos žibintais, kad kas vakarą uždegtų; nes mes laikomės VIEŠPATIES, savo Dievo, įpareigojimo; bet jūs jį palikote.'),
  (@b14, 13, 12, 'Ir štai su mumis yra pats Dievas kaip mūsų vadas ir jo kunigai su gaudžiančiais trimitais, kad skelbtų pavojaus signalą prieš jus. O Izraelio vaikai, nekovokite prieš VIEŠPATĮ, savo tėvų Dievą; nes jums nesiseks“.'),
  (@b14, 13, 13, 'Bet Jeroboamas užvedė jiems iš užnugario pasalą; taigi jie buvo prieš Judą, o pasala buvo jų užnugaryje.'),
  (@b14, 13, 14, 'Ir Judai pažiūrėjus atgal, štai mūšis buvo priekyje ir užnugaryje; ir jie šaukėsi VIEŠPATIES, o kunigai gaudė trimitais.'),
  (@b14, 13, 15, 'Tada Judos vyrai sušuko; o Judos vyrams sušukus įvyko, kad Dievas sumušė Jeroboamą ir visą Izraelį Abijos ir Judos akivaizdoje.'),
  (@b14, 13, 16, 'Ir Izraelio vaikai bėgo Judos akivaizdoje; ir Dievas juos atidavė į jų rankas.'),
  (@b14, 13, 17, 'Ir Abija ir jo tauta juos išžudė didelėmis žudynėmis; taigi iš Izraelio krito nužudytų penki šimtai tūkstančių rinktinių vyrų.'),
  (@b14, 13, 18, 'Taip Izraelio vaikai tuo metu buvo nužeminti, o Judos vaikai nugalėjo, nes jie pasikliovė VIEŠPAČIU, savo tėvų Dievu.'),
  (@b14, 13, 19, 'Ir Abija vijosi Jeroboamą ir iš jo atėmė miestus: Bet-Elį su jo miesteliais, Ješaną su jo miesteliais ir Efrainą su jo miesteliais.'),
  (@b14, 13, 20, 'Ir Jeroboamas nebeatgavo stiprumo Abijos dienomis; o VIEŠPATS jį ištiko, ir jis mirė.'),
  (@b14, 13, 21, 'Bet Abija pasidarė galingas ir vedė keturiolika žmonų, ir pagimdė dvidešimt du sūnus ir šešiolika dukterų.'),
  (@b14, 13, 22, 'O kiti Abijos darbai, jo keliai ir jo pasakymai yra surašyti pranašo Idojo apsakyme.'),
  (@b14, 14, 1, 'Taigi Abija užmigo prie savo tėvų, ir jį palaidojo Dovydo mieste; o jo sūnus Asa karaliavo jo vietoje. Jo dienomis šalis dešimt metų buvo rami.'),
  (@b14, 14, 2, 'Ir Asa darė tai, kas buvo gera ir teisinga VIEŠPATIES, jo Dievo, akyse;'),
  (@b14, 14, 3, 'nes jis pašalino svetimų dievų aukurus ir aukštumas, sudaužė atvaizdus ir iškirto giraites;'),
  (@b14, 14, 4, 'ir įsakė Judai, kad ieškotų VIEŠPATIES, jų tėvų Dievo, ir kad vykdytų įstatymą bei įsakymą.'),
  (@b14, 14, 5, 'Taip pat jis pašalino iš visų Judos miestų aukštumas ir atvaizdus; ir karalystė buvo rami jo akivaizdoje.'),
  (@b14, 14, 6, 'Ir jis pastatė aptvertus miestus Judoje; nes šalis ilsėjosi, ir tomis dienomis jis nekariavo; nes VIEŠPATS jam suteikė poilsį.'),
  (@b14, 14, 7, 'Todėl jis tarė Judai: „Pastatykime šituos miestus ir padarykime aplink juos sienas ir bokštus, vartus ir skląsčius, kol šalis dar tebėra mūsų akivaizdoje; nes mes ieškojome VIEŠPATIES, mūsų Dievo, mes jo ieškojome, ir jis mums suteikė poilsį iš visų pusių“. Taigi jie statė ir jiems sekėsi.'),
  (@b14, 14, 8, 'Ir Asa turėjo iš Judos vyrų kariuomenę, nešančią didžiuosius skydus ir ietis – tris šimtus tūkstančių; o iš Benjamino, nešančių skydus ir įtempiančių lanką, – du šimtai aštuoniasdešimt tūkstančių; visi šitie buvo narsūs galiūnai.'),
  (@b14, 14, 9, 'Ir prieš juos išėjo etiopas Zerachas su tūkstančių tūkstančio kariuomene ir su trimis šimtais vežimų; ir atėjo į Marešą.'),
  (@b14, 14, 10, 'Tada Asa išėjo prieš jį, ir jie išsirikiavo mūšiui Cefatos slėnyje Marešoje.'),
  (@b14, 14, 11, 'Ir Asa šaukėsi VIEŠPATIES, savo Dievo, ir tarė: „VIEŠPATIE, tau nieko nereiškia padėti, ar tiems, kurių daug, ar bejėgiams; padėk mums, o VIEŠPATIE, mūsų Dieve; nes mes remiamės į tave ir tavo vardu einame prieš šitą daugybę. O VIEŠPATIE, tu esi mūsų Dievas; tenenugali tavęs žmogus“.'),
  (@b14, 14, 12, 'Taigi VIEŠPATS sumušė etiopus Asos akivaizdoje ir Judos akivaizdoje; ir etiopai pabėgo.'),
  (@b14, 14, 13, 'O Asa ir su juo esanti tauta juos vijosi iki Geraro; ir etiopai buvo nugalėti, kad jie nebeatsigavo; nes jie buvo sunaikinti VIEŠPATIES akivaizdoje ir jo kariuomenės akivaizdoje; ir jie nusinešė labai daug grobio.'),
  (@b14, 14, 14, 'Ir jie sumušė visus miestus aplink Gerarą; nes juos apėmė VIEŠPATIES baimė; ir jie apiplėšė visus miestus; nes juose buvo nepaprastai daug grobio.'),
  (@b14, 14, 15, 'Taip pat jie sumušė galvijų palapines ir nusivedė gausybę avių bei kupranugarių, ir sugrįžo į Jeruzalę.'),
  (@b14, 15, 1, 'Ir Dievo Dvasia atėjo ant Odedo sūnaus Azarijos;'),
  (@b14, 15, 2, 'ir jis išėjo Asos pasitikti ir jam tarė: „Paklausykite manęs, Asa, visa Juda ir Benjaminai; VIEŠPATS yra su jumis, kol jūs esate su juo; jei jo ieškosite, jis bus jūsų randamas; bet jei jį paliksite, jis jus paliks.'),
  (@b14, 15, 3, 'Na, o ilgą laiką Izraelis buvo be tikrojo Dievo, be kunigo, kuris mokytų, ir be įstatymo.'),
  (@b14, 15, 4, 'Bet kai jie savo varge atsigręžė į VIEŠPATĮ, Izraelio Dievą, ir jo ieškojo, jis buvo jų surandamas.'),
  (@b14, 15, 5, 'Tais laikais nebuvo ramybės nei tam, kuris išeidavo, nei tam, kuris įeidavo, bet dideli neramumai buvo visiems šalių gyventojams.'),
  (@b14, 15, 6, 'Tauta naikino tautą, ir miestas miestą; nes Dievas kėlė jiems nerimą visomis nelaimėmis.'),
  (@b14, 15, 7, 'Taigi būkite stiprūs ir tenenusilpsta jūsų rankos; nes bus atmokėta už jūsų darbą“.'),
  (@b14, 15, 8, 'Ir kai Asa išgirdo šituos žodžius ir pranašo Odedo pranašystę, jis įsidrąsino ir pašalino pasibjaurėtinus stabus iš visos Judos ir Benjamino šalies, ir iš miestų, kuriuos jis buvo paėmęs iš Efraimo kalno, ir atnaujino VIEŠPATIES aukurą, esantį prieš VIEŠPATIES prieangį.'),
  (@b14, 15, 9, 'Ir jis surinko visą Judą, Benjaminą ir su jais ateivius iš Efraimo, Manaso ir Simeono; nes gausiai jų iš Izraelio persimetė pas jį, kai jie pamatė, kad VIEŠPATS, jo Dievas, buvo su juo.'),
  (@b14, 15, 10, 'Taigi jie susirinko į Jeruzalę trečią mėnesį, penkioliktais Asos karaliavimo metais.'),
  (@b14, 15, 11, 'Ir tuo pačiu metu jie atnašavo VIEŠPAČIUI iš to grobio, kurį jie buvo atsigabenę, septynis šimtus jaučių ir septynis tūkstančius avių.'),
  (@b14, 15, 12, 'Ir jie įstojo į sandorą, kad ieškos VIEŠPATIES, savo tėvų Dievo, visa savo širdimi ir visa savo siela;'),
  (@b14, 15, 13, 'o kas neieškos VIEŠPATIES, Izraelio Dievo, tas bus užmuštas – ar mažas ar didelis, ar vyras ar moteris.'),
  (@b14, 15, 14, 'Ir jie prisiekė VIEŠPAČIUI garsiu balsu ir šauksmais, trimitais ir kornetais.'),
  (@b14, 15, 15, 'Ir visa Juda džiaugėsi priesaika; nes jie buvo prisiekę visa savo širdimi ir jo ieškojo visu savo troškimu; ir jis buvo jų surastas; ir VIEŠPATS jiems davė poilsį iš visų pusių.'),
  (@b14, 15, 16, 'Taipogi ir karaliaus Asos motiną Maaką jis pašalino, kad ji nebūtų karalienė, nes ji buvo padariusi giraitėje stabą; ir Asa nukirto jos stabą ir sutrypęs jį sudegino jį prie Kidrono upelio.'),
  (@b14, 15, 17, 'Bet aukštumos nebuvo pašalintos iš Izraelio; tačiau Asos širdis buvo tobula per visas jo dienas.'),
  (@b14, 15, 18, 'Ir jis atgabeno į Dievo namus savo tėvo pašvęstus daiktus ir savo paties pašvęstus daiktus: sidabrą, auksą ir indus.'),
  (@b14, 15, 19, 'Ir nebebuvo karo iki trisdešimt penktųjų Asos karaliavimo metų.'),
  (@b14, 16, 1, 'Trisdešimt šeštaisiais Asos karaliavimo metais Izraelio karalius Baaša atėjo aukštyn prieš Judą ir pastatė Ramą tuo tikslu, kad niekam neleistų išeiti ar įeiti pas Judos karalių Asą.'),
  (@b14, 16, 2, 'Tada Asa išnešė sidabrą bei auksą iš VIEŠPATIES namų ir karaliaus namų lobynų ir nusiuntė Sirijos karaliui Ben-Hadadui, gyvenančiam Damaske, sakydamas:'),
  (@b14, 16, 3, '„Tarp manęs ir tavęs yra sąjunga, kaip buvo tarp mano tėvo ir tavo tėvo; štai aš tau siunčiu sidabro ir aukso; eik, sulaužyk savo sąjungą su Izraelio karaliumi Baaša, kad jis atsitrauktų nuo manęs“.'),
  (@b14, 16, 4, 'Ir Ben-Hadadas, paklausęs karaliaus Asos, pasiuntė savo kariuomenių vadus prieš Izraelio miestus; ir jie sumušė Ijoną, Daną, Abel-Maimą ir visus Naftalio sandėlių miestus.'),
  (@b14, 16, 5, 'Ir įvyko, kad tai išgirdęs, Baaša liovėsi statęs Ramą ir paliovė savo darbą.'),
  (@b14, 16, 6, 'Tada karalius Asa paėmė visą Judą; ir jie išgabeno Ramos akmenis ir jos medieną, kuriais Baaša statė; ir jais jis pastatė Gebą ir Micpą.'),
  (@b14, 16, 7, 'Ir tuo metu regėtojas Hananis atėjo pas Judos karalių Asą ir jam tarė: „Kadangi tu pasikliovei Sirijos karaliumi, o nepasikliovei VIEŠPAČIU, savo Dievu, todėl Sirijos karaliaus kariuomenė ištrūko iš tavo rankų.'),
  (@b14, 16, 8, 'Argi etiopai ir libiai nebuvo didžiulė kariuomenė su labai daug vežimų ir raitelių? Tačiau, kadangi tu pasikliovei VIEŠPAČIU, jis juos atidavė į tavo rankas.'),
  (@b14, 16, 9, 'Nes VIEŠPATIES akys bėgioja ten ir atgal po visą žemę, kad pasirodytų stiprus dėl tų, kurių širdis yra tobula prieš jį. Tame tu kvailai pasielgei; todėl nuo šiol tu turėsi karų“.'),
  (@b14, 16, 10, 'Tada Asa, užsirūstinęs ant regėtojo, pasodino jį į kalėjimo namus; nes jis buvo įnirtęs ant jo dėl to dalyko. Ir tuo pačiu metu Asa engė kai kuriuos iš tautos.'),
  (@b14, 16, 11, 'Ir štai Asos darbai, pirmieji ir paskutinieji, štai jie yra surašyti Judos ir Izraelio karalių knygoje.'),
  (@b14, 16, 12, 'O trisdešimt devintaisiais savo karaliavimo metais Asa buvo nesveikas kojomis, kol jo liga buvo nepaprastai sunki; tačiau savo ligoje jis ieškojo ne VIEŠPATIES, bet gydytojų.'),
  (@b14, 16, 13, 'Ir Asa užmigo prie savo tėvų ir mirė keturiasdešimt pirmaisiais savo karaliavimo metais.'),
  (@b14, 16, 14, 'Ir jį palaidojo jo paties kape, kurį jis buvo pasidaręs Dovydo mieste, ir jį paguldė į patalą, kuris buvo pripildytas gardžių kvapų ir įvairių kvepalų, paruoštų vaistininko meistriškumu; ir dėl jo jie labai daug degino.'),
  (@b14, 17, 1, 'Ir jo sūnus Jehozapatas karaliavo jo vietoje ir sustiprėjo prieš Izraelį.'),
  (@b14, 17, 2, 'Ir jis pastatė kariuomenes visuose aptvertuose Judos miestuose ir pastatė įgulas Judos šalyje bei Efraimo miestuose, kuriuos buvo paėmęs jo tėvas Asa.'),
  (@b14, 17, 3, 'Ir VIEŠPATS buvo su Jehozapatu, nes jis vaikščiojo pirmaisiais savo tėvo Dovydo keliais ir neieškojo Baalų;'),
  (@b14, 17, 4, 'bet ieškojo VIEŠPATIES, savo tėvo Dievo, ir vaikščiojo pagal jo įsakymus, o ne pagal Izraelio darbus.'),
  (@b14, 17, 5, 'Todėl VIEŠPATS sutvirtino karalystę jo rankoje; ir visa Juda atnešė Jehozapatui dovanų; ir jis turėjo gausybę turtų bei garbės.'),
  (@b14, 17, 6, 'Ir jo širdis buvo išaukštinta VIEŠPATIES keliuose; jis dar pašalino iš Judos aukštumas ir giraites.'),
  (@b14, 17, 7, 'Taip pat trečiaisiais savo karaliavimo metais jis siuntė pas savo kunigaikščius, būtent pas Ben-Hailą, Abdiją, Zachariją, Netanelį ir Michają, kad mokytų Judos miestuose.'),
  (@b14, 17, 8, 'Ir su jais jis siuntė levitus, būtent Šemają, Netaniją, Zebadiją, Asaelį, Šemiramotą, Jehonataną, Adoniją, Tobiją ir Tob-Adoniją, levitus; o su jais kunigus Elišamą ir Jehoramą.'),
  (@b14, 17, 9, 'Ir jie mokė Judoje, turėdami su savimi VIEŠPATIES įstatymo knygą, ir ėjo aplinkui per visus Judos miestus ir mokė tautą.'),
  (@b14, 17, 10, 'Ir VIEŠPATIES baimė apėmė visas šalių karalystes, esančias aplink Judą, taip, kad jos nekariavo prieš Jehozapatą.'),
  (@b14, 17, 11, 'Taip pat kai kurie iš filistinų atgabeno Jehozapatui dovanų ir duoklės sidabrą; o arabai jam atgabeno kaimenių: septynis tūkstančius septynis šimtus avinų ir septynis tūkstančius septynis šimtus ožių.'),
  (@b14, 17, 12, 'Ir Jehozapatas pasidarė nepaprastai didis; jis pastatė Judoje pilių ir sandėlių miestų.'),
  (@b14, 17, 13, 'Jis turėjo daug darbų Judos miestuose; ir karo vyrų, narsių galiūnų buvo Jeruzalėje.'),
  (@b14, 17, 14, 'O šitie yra jų skaičiai pagal jų tėvų namus: iš Judos tūkstantininkai: vyriausiasis Adna ir su juo trys šimtai tūkstančių narsių galiūnų.'),
  (@b14, 17, 15, 'O šalia jo buvo vadas Jehohananas ir su juo du šimtai aštuoniasdešimt tūkstančių.'),
  (@b14, 17, 16, 'O šalia jo buvo Zichrio sūnus Amasija, savanoriškai pasiaukojęs VIEŠPAČIUI; ir su juo du šimtai tūkstančių narsių galiūnų.'),
  (@b14, 17, 17, 'O iš Benjamino: narsus galiūnas Eljada ir su juo du šimtai tūkstančių ginkluotųjų lanku ir skydu.'),
  (@b14, 17, 18, 'O šalia jo buvo Jehozabadas ir su juo šimtas aštuoniasdešimt tūkstančių, pasiruošusių karui.'),
  (@b14, 17, 19, 'Šitie tarnavo karaliui neskaitant tų, kuriuos karalius pastatė aptvertuose miestuose po visą Judą.'),
  (@b14, 18, 1, 'Na, o Jehozapatas turėjo gausybę turtų ir garbės, ir susigiminiavo su Ahabu.'),
  (@b14, 18, 2, 'Ir po kelerių metų jis nuėjo žemyn pas Ahabą į Samariją. O Ahabas jam ir su juo buvusiems žmonėms papjovė daugybę avių bei jaučių ir jį įtikinėjo eiti su juo aukštyn į Ramot-Gileadą.'),
  (@b14, 18, 3, 'Ir Izraelio karalius Ahabas tarė Judos karaliui Jehozapatui: „Ar eisi su manimi į Ramot-Gileadą?“ Jis jam atsakė: „Aš esu kaip ir tu, mano tauta kaip ir tavo tauta; mes būsime su tavimi kare“.'),
  (@b14, 18, 4, 'Ir Jehozapatas tarė Izraelio karaliui: „Pasiteirauk šiandien, meldžiu tave, VIEŠPATIES žodžio“.'),
  (@b14, 18, 5, 'Taigi Izraelio karalius surinko iš pranašų keturis šimtus vyrų ir jiems tarė: „Ar mums eiti į mūšį į Ramot-Gileadą, ar susilaikyti?“ Ir jie tarė: „Eik aukštyn; nes Dievas atiduos jį į karaliaus rankas“.'),
  (@b14, 18, 6, 'Bet Jehozapatas tarė: „Ar čia be to dar nėra VIEŠPATIES pranašo, kad galėtume jo pasiteirauti?“'),
  (@b14, 18, 7, 'Ir Izraelio karalius pasakė Jehozapatui: „Dar yra vienas vyras, per kurį galėtume VIEŠPATIES pasiklausti; bet aš jo nekenčiu; nes jis niekuomet nepranašavo man gero, bet visuomet pikta; tai yra Imlos sūnus Michėjas“. O Jehozapatas tarė: „Tegul taip nesako karalius“.'),
  (@b14, 18, 8, 'Ir Izraelio karalius, pašaukęs vieną iš savo pareigūnų, tarė: „Skubiai atvesk Imlos sūnų Michėją“.'),
  (@b14, 18, 9, 'O Izraelio karalius ir Judos karalius Jehozapatas, apsivilkę savo rūbais, sėdėjo kiekvienas iš jų savo soste, ir jie sėdėjo atviroje vietoje Samarijos vartų įėjime; o visi pranašai pranašavo jų akivaizdoje.'),
  (@b14, 18, 10, 'Ir Kenaanos sūnus Zedekijas, pasidaręs geležinius ragus, tarė: „Taip sako VIEŠPATS: ‘Šitais tu badysi Siriją, kol jie bus sunaikinti’“.'),
  (@b14, 18, 11, 'Ir visi pranašai taip pranašavo, sakydami: „Eik aukštyn į Ramot-Gileadą ir tesiseka tau; nes VIEŠPATS jį atiduos į karaliaus rankas“.'),
  (@b14, 18, 12, 'Ir pasiuntinys, kuris nuėjo Michėjo pakviesti, jam kalbėjo, sakydamas: „Štai pranašų žodžiai vienbalsiai skelbia gera karaliui; todėl tebūna, meldžiu tave, tavo žodis kaip vieno iš jų, ir kalbėk gera“.'),
  (@b14, 18, 13, 'O Michėjas tarė: „Kaip gyvas VIEŠPATS, ką mano Dievas sakys, tą kalbėsiu“.'),
  (@b14, 18, 14, 'Ir jam atėjus pas karalių, karalius jam tarė: „Michėjau, ar mums eiti į mūšį į Ramot-Gileadą, ar susilaikyti?“ Ir jis tarė: „Eikite aukštyn, ir tesiseka jums, ir jie bus atiduoti į jūsų rankas“.'),
  (@b14, 18, 15, 'O karalius jam tarė: „Kiek kartų aš turėsiu tave saikdinti, kad man nieko nekalbėtum, bet tik tiesą VIEŠPATIES vardu?“'),
  (@b14, 18, 16, 'Tada jis tarė: „Mačiau visą Izraelį išsisklaidžiusį ant kalnų kaip avis, neturinčias ganytojo; ir VIEŠPATS tarė: ‘Šitie neturi valdovo; todėl jie kiekvienas tegrįžta ramybėje į savo namus’“.'),
  (@b14, 18, 17, 'Ir Izraelio karalius tarė Jehozapatui: „Argi tau nesakiau, kad jis nepranašauja man gero, o tik pikta?“'),
  (@b14, 18, 18, 'Jis vėl tarė: „Todėl klausykite VIEŠPATIES žodžio: Mačiau VIEŠPATĮ, sėdintį savo soste, ir visą dangaus kariuomenę, stovinčią jo dešinėje ir jo kairėje.'),
  (@b14, 18, 19, 'Ir VIEŠPATS tarė: ‘Kas suvilios Izraelio karalių Ahabą, kad jis eitų aukštyn ir kristų Ramot-Gileade?’ Ir vienas sakė taip, o kitas sakė kitaip.'),
  (@b14, 18, 20, 'Tada išėjo dvasia ir, atsistojusi VIEŠPATIES akivaizdoje, tarė: ‘Aš jį suviliosiu’. Ir VIEŠPATS jai tarė: ‘Kuo?’'),
  (@b14, 18, 21, 'Ir ji pasakė: ‘Aš išeisiu ir būsiu melo dvasia visų jo pranašų burnoje’. Ir VIEŠPATS tarė: ‘Tu jį suviliosi ir taipogi įveiksi; išeik ir būtent taip padaryk’.'),
  (@b14, 18, 22, 'Taigi dabar, štai VIEŠPATS įdėjo meluojančią dvasią į šitų tavo pranašų burną, ir VIEŠPATS kalbėjo prieš tave pikta“.'),
  (@b14, 18, 23, 'Tada priėjo Kenaanos sūnus Zedekijas, trenkė Michėjui į žandą ir tarė: „Kuriuo keliu VIEŠPATIES Dvasia nuėjo nuo manęs, kad tau kalbėtų?“'),
  (@b14, 18, 24, 'Ir Michėjas pasakė: „Štai tu pamatysi tą dieną, kai įeisi į vidinį kambarį slėptis“.'),
  (@b14, 18, 25, 'Tada Izraelio karalius tarė: „Paimkite Michėją ir nuveskite jį atgal pas miesto valdytoją Amoną ir pas karaliaus sūnų Joašą;'),
  (@b14, 18, 26, 'ir sakykite: ‘Taip sako karalius: Pasodinkite šitą į kalėjimą ir maitinkite jį sielvarto duona bei sielvarto vandeniu, kol aš sugrįšiu ramybėje’“.'),
  (@b14, 18, 27, 'O Michėjas tarė: „Jei tikrai sugrįši ramybėje, tai VIEŠPATS nekalbėjo per mane“. Ir jis tarė: „Klausykite visi žmonės“.'),
  (@b14, 18, 28, 'Taip Izraelio karalius ir Judos karalius Jehozapatas nuėjo aukštyn į Ramot-Gileadą.'),
  (@b14, 18, 29, 'O Izraelio karalius tarė Jehozapatui: „Aš persirengęs eisiu įmūšį; bet tu apsirenk savo rūbais“. Taip Izraelio karalius persirengė; ir jie ėjo į mūšį.'),
  (@b14, 18, 30, 'Na, o Sirijos karalius buvo įsakęs su juo esantiems vežimų vadams, sakydamas: „Nekovokite nei su mažais, nei su dideliais, o vien tik su Izraelio karaliumi“.'),
  (@b14, 18, 31, 'Ir įvyko, kai vežimų vadai pamatė Jehozapatą, jie tarė: „Tai Izraelio karalius“. Todėl jie apsupo jį, kad kautųsi; bet Jehozapatas šaukė, ir VIEŠPATS jam padėjo; ir Dievas juos paskatino nuo jo pasitraukti.'),
  (@b14, 18, 32, 'Nes įvyko, kai vežimų vadai suprato, kad tai nebuvo Izraelio karalius, jie nusigręžė atgal nuo sekiojimo paskui jį.'),
  (@b14, 18, 33, 'Ir vienas vyras nesitaikydamas įtempė lanką ir įsmeigė Izraelio karaliui tarp šarvų sujungimų; todėl jis tarė savo vežėjui: „Atgręžk savo ranką, kad mane išvežtum iš kariuomenės; nes aš esu sužeistas“.'),
  (@b14, 18, 34, 'Ir mūšis tą dieną smarkėjo; tačiau Izraelio karalius stovėjo savo vežime prieš sirus iki vakaro; o saulei leidžiantis mirė.'),
  (@b14, 19, 1, 'O Judos karalius Jehozapatas sugrįžo ramybėje į savo namus, į Jeruzalę.'),
  (@b14, 19, 2, 'Ir išėjo jo pasitikti Hananio sūnus Jehuvas, regėtojas, ir tarė karaliui Jehozapatui: „Ar turėtum padėti bedieviui ir mylėti tuos, kurie nekenčia VIEŠPATIES? Todėl ant tavęs rūstybė nuo VIEŠPATIES akivaizdos.'),
  (@b14, 19, 3, 'Tačiau gerų dalykų yra rasta tavyje, kadangi pašalinai iš šalies giraites ir paruošei savo širdį ieškoti Dievo“.'),
  (@b14, 19, 4, 'O Jehozapatas gyveno Jeruzalėje; ir jis vėl išėjo pro tautą nuo Beer-Šebos iki Efraimo kalno ir juos parvedė pas VIEŠPATĮ, jų tėvų Dievą.'),
  (@b14, 19, 5, 'Jis paskyrė teisėjus šalyje, visuose aptvertuose Judos miestuose, mieste po miesto,'),
  (@b14, 19, 6, 'ir tarė teisėjams: „Žiūrėkite, ką darote; nes ne žmogui jūs teisiate, bet VIEŠPAČIUI, kuris yra su jumis teisme.'),
  (@b14, 19, 7, 'Todėl dabar tebūna VIEŠPATIES baimė ant jūsų; žiūrėkite ir tai darykite; nes pas VIEŠPATĮ, mūsų Dievą, nėra neteisybės nei atsižvelgimo į asmenis, nei dovanų ėmimo“.'),
  (@b14, 19, 8, 'Be to, Jehozapatas Jeruzalėje VIEŠPATIES teismui ir ginčams paskyrė levitų, kunigų ir Izraelio tėvų vyriausiųjų, kai jie sugrįžo į Jeruzalę.'),
  (@b14, 19, 9, 'Ir jis juos įpareigojo, sakydamas: „Taip darykite VIEŠPATIES baimėje, ištikimai ir tobula širdimi.'),
  (@b14, 19, 10, 'Kokia byla beateis pas jus nuo jūsų brolių, gyvenančių savo miestuose, ar tarp kraujo ir kraujo, ar tarp įstatymo ir įsakymo, įstatų ir teismų, jūs įspėkite juos, kad jie nenusižengtų prieš VIEŠPATĮ ir taip rūstybė neužeitų ant jūsų bei ant jūsų brolių; tai darykite, ir jūs nenusižengsite.'),
  (@b14, 19, 11, 'Ir štai vyriausiasis kunigas Amarijas yra jūsų viršininkas visuose VIEŠPATIES reikaluose; o Išmaelio sūnus Zebadijas, Judos namų valdovas, visiems karaliaus reikalams; o levitai bus pareigūnai jūsų akivaizdoje. Drąsiai elkitės, ir VIEŠPATS bus su geruoju“.'),
  (@b14, 20, 1, 'Taip pat po to įvyko, kad Moabo vaikai, Amono vaikai ir su jais kiti, neskaitant amoniečių, atėjo į mūšį prieš Jehozapatą.'),
  (@b14, 20, 2, 'Tada atėję kai kurie Jehozapatui pranešė, sakydami: „Didelė daugybė ateina prieš tave iš už jūros, šiapus Sirijos; ir štai jie yra Hacecon-Tamare, kuris yra En-Gedis.'),
  (@b14, 20, 3, 'Ir Jehozapatas išsigandęs nukreipė save ieškoti VIEŠPATIES ir paskelbė pasninką po visą Judą.'),
  (@b14, 20, 4, 'Ir Juda susirinko prašyti pagalbos iš VIEŠPATIES; būtent iš visų Judos miestų jie atėjo ieškoti VIEŠPATIES.'),
  (@b14, 20, 5, 'O Jehozapatas atsistojo Judos ir Jeruzalės susirinkime, VIEŠPATIES namuose, prieš naująjį kiemą,'),
  (@b14, 20, 6, 'ir tarė: „O VIEŠPATIE, mūsų tėvų Dieve, argi ne tu esi Dievas danguje ir argi ne tu valdai visas pagonių karalystes? Argi ne tavo rankoje yra jėga ir galybė, kad niekas negali tau pasipriešinti?'),
  (@b14, 20, 7, 'Argi ne tu, mūsų Dieve, kuris savo tautos Izraelio akivaizdoje išvarei gyventojus šitos šalies ir ją davei savo draugo Abraomo sėklai amžiams?'),
  (@b14, 20, 8, 'Ir jie gyveno joje ir joje pastatė tau šventovę tavo vardui, sakydami:'),
  (@b14, 20, 9, '‘Jei atėjus ant mūsų piktam, kaip kalavijui, teismui ar marui, ar badui, mes atsistosime prieš šituos namus ir tavo akivaizdoje (nes tavo vardas yra šituose namuose) ir tavęs šauksimės savo suspaudime, tuomet tu išgirsk ir padėk’.'),
  (@b14, 20, 10, 'O dabar, štai Amono, Moabo ir Seyro kalno vaikai, kurių tu neleidai Izraeliui užgrobti jiems išėjus iš Egipto šalies, bet jie nusisuko nuo jų ir jų nesunaikino;'),
  (@b14, 20, 11, 'štai kaip jie atmoka mums tuo, kad ateina mūsų išmesti iš tavo nuosavybės, kurią davei mums paveldėti.'),
  (@b14, 20, 12, 'O mūsų Dieve, argi tu neteisi jų? Nes mes neturime galios prieš šitą didelį būrį, ateinantį prieš mus; ir mes nežinome, ką daryti; bet mūsų akys nukreiptos į tave“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b14, 20, 13, 'Ir visa Juda stovėjo VIEŠPATIES akivaizdoje su savo mažyliais, savo žmonomis ir savo vaikais.'),
  (@b14, 20, 14, 'Tada susirinkimo viduryje VIEŠPATIES Dvasia atėjo ant Matanijos sūnaus Jejelio sūnaus Benajos sūnaus Zacharijo sūnaus Jahazielio, levito iš Asafo sūnų;'),
  (@b14, 20, 15, 'ir jis tarė: „Klausykite jūs, visa Juda, jūs, Jeruzalės gyventojai, ir tu, karaliau Jehozapatai: Taip jums sako VIEŠPATS: ‘Nebijokite ir nebūkite nerimastingi dėl šitos didelės daugybės; nes mūšis yra ne jūsų, bet Dievo.'),
  (@b14, 20, 16, 'Rytoj eikite žemyn prieš juos; štai jie ateina aukštyn Zizo skardžiu; ir juos rasite upelio gale, prieš Jeruelio dykumą.'),
  (@b14, 20, 17, 'Jums nereikės kovoti šiame mūšyje; išsirikiuokite, stovėkite nejudėdami ir stebėkite VIEŠPATIES išgelbėjimą su jumis, o Juda ir Jeruzale; nebijokite ir nebūkite nerimastingi; rytoj išeikite prieš juos; nes VIEŠPATS bus su jumis’“.'),
  (@b14, 20, 18, 'Ir Jehozapatas nulenkė savo galvą veidu iki žemės; ir visa Juda bei Jeruzalės gyventojai parpuolė prieš VIEŠPATĮ, garbindami VIEŠPATĮ.'),
  (@b14, 20, 19, 'O levitai iš kehatų vaikų ir iš korachų vaikų, atsistojo girti VIEŠPATĮ, Izraelio Dievą, dideliu balsu į aukštybes.'),
  (@b14, 20, 20, 'Ir ankstų rytą atsikėlę, jie išėjo į Tekojos dykumą; ir jiems išeinant, Jehozapatas atsistojęs tarė: „Klausykite manęs, o Juda ir Jeruzalės gyventojai; tikėkite VIEŠPAČIU, savo Dievu, taip būsite įtvirtinti; tikėkite jo pranašais, taip jūs klestėsite“.'),
  (@b14, 20, 21, 'Pasitaręs su tauta, jis paskyrė VIEŠPAČIUI giesmininkus ir kad girtų šventumo grožį, išeidami pirma kariuomenės, sakydami: „Girkite VIEŠPATĮ; nes jo gailestingumas pasilieka per amžius“.'),
  (@b14, 20, 22, 'Ir kai jie pradėjo giedoti ir girti, VIEŠPATS pastatė pasalas prieš Amono, Moabo ir Seyro kalno vaikus, atėjusius prieš Judą; ir jie buvo sumušti.'),
  (@b14, 20, 23, 'Nes Amono ir Moabo vaikai stojosi prieš Seyro kalno gyventojus, kad juos visiškai išžudytų ir sunaikintų; o kai buvo pribaigę Seyro gyventojus, jie padėjo naikinti vieni kitus.'),
  (@b14, 20, 24, 'O Judai atėjus link apžvalgos bokšto dykumoje, jie pažvelgė į minią, ir štai jie buvo ant žemės kritę lavonai, ir nei vieno ištrūkusio.'),
  (@b14, 20, 25, 'Ir kai Jehozapatas ir jo tauta atėjo paimti iš jų grobį, jie rado tarp jų gausybę turtų prie mirusių kūnų, ir brangenybių, kurių jie sau nusiplėšė daugiau nei galėjo išnešti; ir tris dienas jie rinko grobį, jo buvo tiek daug.'),
  (@b14, 20, 26, 'O ketvirtą dieną jie susirinko į Berako slėnį; nes ten jie laimino VIEŠPATĮ; todėl tą vietą iki šios dienos vadina Berako slėniu.'),
  (@b14, 20, 27, 'Paskui jie sugrįžo, visi Judos bei Jeruzalės žmonės, o jų priekyje Jehozapatas, kad grįžtų į Jeruzalę su džiaugsmu; nes VIEŠPATS padarė, kad jie džiaugtųsi dėl savo priešų.'),
  (@b14, 20, 28, 'Ir jie atėjo į Jeruzalę, į VIEŠPATIES namus, su psalteriais, arfomis ir trimitais.'),
  (@b14, 20, 29, 'Ir Dievo baimė buvo ant visų tų šalių karalysčių, kai jos išgirdo, kad VIEŠPATS kovojo prieš Izraelio priešus.'),
  (@b14, 20, 30, 'Taip Jehozapato karalystė buvo rami; nes jo Dievas jam davė poilsį iš visų pusių.'),
  (@b14, 20, 31, 'Ir Jehozapatas karaliavo Judai; jis buvo trisdešimt penkerių metų, kai pradėjo karaliauti, ir dvidešimt penkerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Azuba, Šilchio duktė.'),
  (@b14, 20, 32, 'Jis vaikščiojo savo tėvo Asos keliu ir neatsitraukė nuo jo, darydamas tai, kas buvo teisinga VIEŠPATIES akyse.'),
  (@b14, 20, 33, 'Tačiau aukštumos nebuvo pašalintos; nes tauta dar nebuvo paruošusi savo širdies savo tėvų Dievui.'),
  (@b14, 20, 34, 'Na, o kiti Jehozapato darbai, pirmieji ir paskutinieji, štai jie yra užrašyti knygoje Hananio sūnaus Jehuvo, kuris yra paminėtas Izraelio karalių knygoje.'),
  (@b14, 20, 35, 'O po to Judos karalius Jehozapatas prisijungė prie Izraelio karaliaus Ahazijo, kuris elgėsi labai nedorai;'),
  (@b14, 20, 36, 'jis prisijungė prie jo, kad statytų laivus vykti į Taršišą; ir jie statė laivus Ecjon-Gebere.'),
  (@b14, 20, 37, 'Tada Dodavos sūnus Eliezeras iš Marešos pranašavo prieš Jehozapatą, sakydamas: „Kadangi tu prisijungei prie Ahazijo, VIEŠPATS sudaužė tavo darbus“. Ir laivai sudužo, kad jie negalėjo vykti į Taršišą.'),
  (@b14, 21, 1, 'Na, o Jehozapatas užmigo prie savo tėvų ir buvo palaidotas prie savo tėvų Dovydo mieste. O jo sūnus Jehoramas karaliavo jo vietoje.'),
  (@b14, 21, 2, 'Jis turėjo brolių, Jehozapato sūnų: Azariją, Jehielį, Zachariją, Azariją, Mykolą ir Šefatiją; visi šitie buvo Judos karaliaus Jehozapato sūnūs.'),
  (@b14, 21, 3, 'Jų tėvas jiems davė didelių sidabro, aukso ir brangių daiktų dovanų su aptvertais miestais Judoje; bet karalystę jis davė Jehoramui; nes jis buvo pirmagimis.'),
  (@b14, 21, 4, 'Na, o kai Jehoramas buvo pakilęs į savo tėvo karalystę, jis sustiprėjo ir išžudė kalaviju visus savo brolius ir kai kuriuos iš Izraelio kunigaikščių.'),
  (@b14, 21, 5, 'Jehoramas buvo trisdešimt dvejų metų, kai pradėjo karaliauti, ir aštuonerius metus karaliavo Jeruzalėje.'),
  (@b14, 21, 6, 'Ir jis vaikščiojo Izraelio karalių keliu, kaip darė Ahabo namai; nes Ahabo duktė buvo jo žmona; ir jis darė tai, kas buvo pikta VIEŠPATIES akyse.'),
  (@b14, 21, 7, 'Tačiau VIEŠPATS nenorėjo sunaikinti Dovydo namų dėl sandoros, kurią jis buvo sudaręs su Dovydu, ir kaip buvo žadėjęs duoti žiburį jam ir jo sūnums per amžius.'),
  (@b14, 21, 8, 'Jo dienomis edomiečiai sukilo iš po Judos valdžios ir paskyrė sau karalių.'),
  (@b14, 21, 9, 'Tada Jehoramas išėjo su savo kunigaikščiais ir su juo visi jo vežimai; ir naktį pakilęs jis mušė edomiečius, kurie buvo apsupę jį, ir vežimų vadus.'),
  (@b14, 21, 10, 'Taip edomiečiai yra sukilę iš po Judos rankos valdžios iki šios dienos. Tuo pačiu metu ir Libna sukilo iš po jo rankos valdžios; nes jis buvo palikęs VIEŠPATĮ, savo tėvų Dievą.'),
  (@b14, 21, 11, 'Be to, jis padarė aukštumų Judos kalnuose ir skatino Jeruzalės gyventojus paleistuvauti, ir patraukė Judą į tai.'),
  (@b14, 21, 12, 'Ir jam atėjo raštas iš pranašo Elijo, sakydamas: „Taip sako VIEŠPATS, tavo tėvo Dovydo Dievas: ‘Kadangi nevaikščiojai savo tėvo Jehozapato keliais nei Judos karaliaus Asos keliais,'),
  (@b14, 21, 13, 'bet vaikščiojai Izraelio karalių keliu ir skatinai Judą bei Jeruzalės gyventojus daryti tokią paleistuvystę, kokios yra Ahabo namų paleistuvystės, ir taip pat išžudei iš savo tėvo namų savo brolius, geresnius už tave;'),
  (@b14, 21, 14, 'štai VIEŠPATS ištiks didele rykšte tavo tautą, tavo vaikus, tavo žmonas ir visą tavo turtą;'),
  (@b14, 21, 15, 'o tu sunkiai susirgsi savo vidurių liga, kol tavo viduriai iškritinės dėl ligos diena iš dienos’“.'),
  (@b14, 21, 16, 'Be to, VIEŠPATS sukurstė prieš Jehoramą filistinų ir arabų, esančių šalia etiopų, dvasią;'),
  (@b14, 21, 17, 'ir jie atėjo aukštyn į Judą ir įsilaužė į ją, ir išsigabeno visą turtą, rastą karaliaus namuose, taip pat jo sūnus ir jo žmonas; taip, kad jam nepaliko nei vieno sūnaus, išskyrus Jehoachazą, jauniausiąjį iš jo sūnų.'),
  (@b14, 21, 18, 'Ir po viso to VIEŠPATS ištiko jį jo viduriuose nepagydoma liga.'),
  (@b14, 21, 19, 'Ir įvyko, kad laikui bėgant, pasibaigus dviems metams, nuo ligos išsivertė jo viduriai; taip jis mirė nuo sunkių ligų. O jo tauta jam taip nedegino, kaip degino dėl jo tėvų.'),
  (@b14, 21, 20, 'Jis buvo trisdešimt dvejų metų, kai pradėjo karaliauti, ir aštuonerius metus karaliavo Jeruzalėje, ir išėjo kaip nepageidaujamas. Tačiau jį palaidojo Dovydo mieste, bet ne karalių kapuose.'),
  (@b14, 22, 1, 'Ir Jeruzalės gyventojai paskyrė karaliumi į jo vietą jo jauniausiąjį sūnų Ahaziją; nes visus vyresniuosius buvo išžudęs būrys vyrų, atėjusių su arabais į stovyklą. Taigi karaliavo Judos karaliaus Jehoramo sūnus Ahazijas.'),
  (@b14, 22, 2, 'O Ahazijas buvo keturiasdešimt dvejų metų, kai pradėjo karaliauti, ir vienerius metus karaliavo Jeruzalėje. Jo motinos vardas buvo Atalija, Omrio duktė.'),
  (@b14, 22, 3, 'Jis irgi vaikščiojo Ahabo namų keliais; nes jo motina buvo jo patarėja, kad jis elgtųsi nedorai.'),
  (@b14, 22, 4, 'Todėl jis darė pikta VIEŠPATIES akyse, kaip Ahabo namai; nes po jo tėvo mirties jie buvo jo patarėjais jo pražūčiai.'),
  (@b14, 22, 5, 'Jis taip pat vaikščiojo pagal jų patarimą ir su Izraelio karaliaus Ahabo sūnumi Jehoramu ėjo į karą prieš Sirijos karalių Hazaelį į Ramot-Gileadą; ir sirai sumušė Joramą.'),
  (@b14, 22, 6, 'Ir jis sugrįžo gydytis Jezreelyje dėl žaizdų, kurias jam buvo padarę Ramoje, kai jis kariavo su Sirijos karaliumi Hazaeliu. Ir Judos karaliaus Jehoramo sūnus Azarija nuėjo žemyn aplankyti Ahabo sūnaus Jehoramo Jezreelyje, nes jis sirgo.'),
  (@b14, 22, 7, 'O Ahazijo pražūtis buvo iš Dievo per atvykimą pas Joramą; nes atvykęs jis išėjo su Jehoramu prieš Nimšio sūnų Jehuvą, kurį VIEŠPATS buvo patepęs, kad iškirstų Ahabo namus.'),
  (@b14, 22, 8, 'Ir įvyko, kad Jehuvas, vykdydamas teismą Ahabo namams, aptiko Judos kunigaikščius ir Ahazijo brolių sūnus, kurie tarnavo Ahazijui, ir juos išžudė.'),
  (@b14, 22, 9, 'Ir jis ieškojo Ahazijo; ir jie jį sugavo (nes jis buvo pasislėpęs Samarijoje) ir atvedė pas Jehuvą; o kai jį nužudė, jie palaidojo jį, „nes, – sakė jie, – jis yra sūnus Jehozapato, kuris visa savo širdimi ieškojo VIEŠPATIES“. Taigi Ahazijo namai nebeturėjo galios išlaikyti karalystę.'),
  (@b14, 22, 10, 'Bet Ahazijo motina Atalija, pamačiusi, kad jos sūnus miręs, pakilo ir sunaikino visą Judos namų karališką sėklą.'),
  (@b14, 22, 11, 'Bet karaliaus duktė Jehošabata paėmė Ahazijo sūnų Joašą, jį pavogė iš tarpo karaliaus sūnų, kurie buvo žudomi, ir jį patalpino su jo aukle į miegamąjį. Taip karaliaus Jehoramo duktė Jehošabata, kunigo Jehojados žmona (nes ji buvo Ahazijo sesuo), paslėpė jį nuo Atalijos, taip, kad ji jo nenužudė.'),
  (@b14, 22, 12, 'Ir jis šešerius metus buvo pas juos paslėptas Dievo namuose; o Atalija karaliavo šalyje.'),
  (@b14, 23, 1, 'O septintaisiais metais Jehojada sustiprėjęs pasiėmė į sandorą su savimi šimtininkus: Jerohamo sūnų Azariją, Jehohanano sūnų Išmaelį, Obedo sūnų Azariją, Adajo sūnų Maasėją ir Zichrio sūnų Elišafatą.'),
  (@b14, 23, 2, 'Ir jie apėjo Judą ir surinko levitus iš visų Judos miestų bei Izraelio tėvų vyriausiuosius, ir jie atėjo į Jeruzalę.'),
  (@b14, 23, 3, 'Ir visas susirinkimas sudarė sandorą su karaliumi Dievo namuose. Ir jis jiems tarė: „Štai karaliaus sūnus karaliaus, kaip VIEŠPATS kalbėjo apie Dovydo sūnus.'),
  (@b14, 23, 4, 'Štai ką padarykite: trečdalis jūsų iš kunigų ir levitų, įeinančių per sabatą, bus durininkai;'),
  (@b14, 23, 5, 'trečdalis bus prie karaliaus namų; ir trečdalis prie pamatų vartų; o visa tauta bus VIEŠPATIES namų kiemuose.'),
  (@b14, 23, 6, 'Bet niekas teneįeina į VIEŠPATIES namus, išskyrus kunigus ir tarnaujančius iš levitų; jie įeis, nes jie yra šventi; bet visa tauta eis VIEŠPATIES sargybą.'),
  (@b14, 23, 7, 'O levitai, kiekvienas su savo ginklu rankoje, apsups ratu karalių; o kas kitas įeis į tuos namus, tas bus užmuštas; bet jūs būkite su karaliumi jam įeinant ir jam išeinant“.'),
  (@b14, 23, 8, 'Taip levitai ir visa Juda padarė pagal visa tai, ką buvo įsakęs kunigas Jehojada, ir kiekvienas ėmė savo vyrus, kurie per sabatą turėjo įeiti su tais, kurie per sabatą turėjo išeiti; nes kunigas Jehojada nepaleido skyrių.'),
  (@b14, 23, 9, 'Be to, kunigas Jehojada įteikė šimtininkams ietis, mažuosius skydus ir didžiuosius skydus, buvusius karaliaus Dovydo, kurie buvo Dievo namuose.'),
  (@b14, 23, 10, 'Ir jis sustatė visą tautą, kiekvieną, turintį rankoje savo ginklą, nuo dešiniojo šventyklos šono iki kairiojo šventyklos šono, išilgai palei aukurą ir aplinkui šventyklą prie karaliaus.'),
  (@b14, 23, 11, 'Paskui jie išvedė karaliaus sūnų, uždėjo jam karūną, įteikė jam liudijimą ir padarė jį karaliumi. Ir Jehojada bei jo sūnūs jį patepė ir tarė: „Tegyvuoja karalius!“'),
  (@b14, 23, 12, 'Na, o Atalija, išgirdusi triukšmą tautos, bėgančios ir giriančios karalių, atėjo pas tautą į VIEŠPATIES namus;'),
  (@b14, 23, 13, 'ir ji pažvelgė, ir štai karalius stovėjo prie savo stulpo, prie įėjimo, ir kunigaikščiai ir trimitai prie karaliaus; ir visa šalies tauta džiaugėsi ir gaudė trimitais, taip pat giesmininkai su muzikiniais instrumentais ir mokantys giedoti gyrių. Tada Atalija perplėšė savo drabužius ir tarė: „Išdavystė, išdavystė!“'),
  (@b14, 23, 14, 'Tada kunigas Jehojada išvedė šimtininkus, paskirtus vadovauti kariuomenei, ir jiems tarė: „Išveskite ją iš eilių; o kas ją seks, tebūna nužudytas kalaviju“. Nes kunigas pasakė: „Nenužudykite jos VIEŠPATIES namuose“.'),
  (@b14, 23, 15, 'Taigi jie pridėjo prie jos rankas; ir jai atėjus iki Arklių vartų įėjimo prie karaliaus namų, ten ją nužudė.'),
  (@b14, 23, 16, 'Ir Jehojada sudarė sandorą tarp savęs ir visos tautos bei karaliaus, kad jie turi būti VIEŠPATIES tauta.'),
  (@b14, 23, 17, 'Tada visa tauta nuėjo į Baalo namus, sugriovė juos, sutrupino jo aukurus ir jo atvaizdus, o Baalo kunigą Mataną nužudė prieš aukurus.'),
  (@b14, 23, 18, 'Taip pat Jehojada paskyrė VIEŠPATIES namų tarnystes per rankas levitų kunigų, kuriuos Dovydas buvo paskirstęs VIEŠPATIES namuose, kad atnašautų VIEŠPATIES deginamąsias atnašas, kaip yra parašyta Mozės įstatyme, su džiaugsmu ir giedojimu, kaip buvo Dovydo nustatyta.'),
  (@b14, 23, 19, 'Ir jis pastatė durininkus prie VIEŠPATIES namų vartų, kad neįeitų nei vienas, kokiu nors dalyku nešvarus.'),
  (@b14, 23, 20, 'Ir jis paėmė šimtininkus, kilminguosius, tautos valdytojus ir visą šalies tautą, ir nuvedė karalių žemyn iš VIEŠPATIES namų; ir jie atėjo pro aukštuosius vartus į karaliaus namus, ir pasodino karalių į karalystės sostą.'),
  (@b14, 23, 21, 'Ir visa šalies tauta džiaugėsi; o miestas buvo ramus po to, kai jie buvo nužudę Ataliją kalaviju.'),
  (@b14, 24, 1, 'Joašas buvo septynerių metų, kai pradėjo karaliauti, ir keturiasdešimt metų karaliavo Jeruzalėje. Jo motinos vardas buvo Cibija, iš Beer-Šebos.'),
  (@b14, 24, 2, 'Ir Joašas darė tai, kas buvo teisinga VIEŠPATIES akyse per visas kunigo Jehojados dienas.'),
  (@b14, 24, 3, 'Ir Jehojada jam ėmė dvi žmonas; ir jis pagimdė sūnų bei dukterų.'),
  (@b14, 24, 4, 'Ir po to įvyko, kad Joašas sugalvojo suremontuoti VIEŠPATIES namus.'),
  (@b14, 24, 5, 'Ir surinkęs kunigus ir levitus, jis jiems tarė: „Išeikite į Judos miestus ir rinkite iš viso Izraelio pinigus jūsų Dievo namams remontuoti iš metų į metus, ir žiūrėkite, kad paskubintumėte tą reikalą“. Tačiau levitai nepaskubino jo.'),
  (@b14, 24, 6, 'Ir karalius pašaukė Jehojadą, vyriausiąjį, ir jam tarė: „Kodėl nereikalavai iš levitų, kad atneštų iš Judos ir iš Jeruzalės rinkliavą, pagal įsakymą VIEŠPATIES tarno Mozės ir Izraelio susirinkimo, dėl Liudijimo padangtės?'),
  (@b14, 24, 7, 'Nes sūnūs Atalijos, tos nedorėlės, buvo sugriovę Dievo namus; ir taip pat visus VIEŠPATIES namų pašvęstus daiktus jie paskyrė Baalams“.'),
  (@b14, 24, 8, 'Ir karaliui įsakius, jie padarė skrynią ir pastatė ją lauke prie VIEŠPATIES namų vartų.'),
  (@b14, 24, 9, 'Ir jie paskelbė po Judą bei Jeruzalę, kad atneštų VIEŠPAČIUI rinkliavą, kurią Dievo tarnas Mozė uždėjo Izraeliui dykumoje.'),
  (@b14, 24, 10, 'Ir visi kunigaikščiai bei visa tauta džiaugėsi ir atnešę metė į skrynią, kol pabaigė.'),
  (@b14, 24, 11, 'Na, o tuo laiku, kai atnešdavo skrynią į karaliaus valdybą per levitų rankas, ir kai jie matydavo, kad joje buvo daug pinigų, karaliaus raštininkas ir aukščiausiojo kunigo pareigūnas atėję ištuštindavo skrynią ir ją paėmę nunešdavo atgal į jos vietą. Taip jie darė diena iš dienos ir surinko gausybę pinigų.'),
  (@b14, 24, 12, 'O karalius ir Jehojada juos duodavo tiems, kurie atlikdavo VIEŠPATIES namų tarnavimo darbą, ir samdydavo mūrininkų ir dailidžių VIEŠPATIES namams remontuoti, ir taip pat geležies bei žalvario kalvių VIEŠPATIES namams pataisyti.'),
  (@b14, 24, 13, 'Taigi darbininkai dirbo, ir darbas buvo jų išbaigtas, ir jie atstatė Dievo namus į jų būseną ir juos sutvirtino.'),
  (@b14, 24, 14, 'O tai pabaigę, jie atnešė likusius pinigus karaliaus ir Jehojados akivaizdon; iš jų buvo padaryti indai VIEŠPATIES namams – indai tarnavimui ir atnašavimui, šaukštai ir auksiniai bei sidabriniai indai. Ir jie nuolat atnašavo deginamąsias atnašas VIEŠPATIES namuose per visas Jehojados dienas.'),
  (@b14, 24, 15, 'Bet Jehojada paseno ir buvo pasisotinęs dienomis, kai mirė; jis buvo šimto trisdešimties metų, kai mirė.'),
  (@b14, 24, 16, 'Ir jį palaidojo Dovydo mieste tarp karalių, nes jis buvo padaręs gera Izraelyje tiek Dievui, tiek jo namams.'),
  (@b14, 24, 17, 'Na, o po Jehojados mirties Judos kunigaikščiai atėjo ir išreiškė pagarbą karaliui. Tuomet karalius išklausė juos.'),
  (@b14, 24, 18, 'Ir jie paliko VIEŠPATIES, savo tėvų Dievo, namus ir tarnavo giraitėms bei stabams; ir atėjo rūstybė ant Judos ir Jeruzalės dėl šito jų nusižengimo.'),
  (@b14, 24, 19, 'Jis dar siuntė jiems pranašų, kad sugrąžintų juos pas VIEŠPATĮ; ir jie liudijo prieš juos; bet jie nepakreipė ausies.'),
  (@b14, 24, 20, 'Ir Dievo Dvasia atėjo ant kunigo Jehojados sūnaus Zacharijos, kuris atsistojęs aukščiau tautos jiems tarė: „Taip sako Dievas: ‘Kodėl nusižengiate VIEŠPATIES įsakymams, kad jums nesisektų? Kadangi jūs palikote VIEŠPATĮ, jis irgi jus paliko’“.'),
  (@b14, 24, 21, 'O jie surengė sąmokslą prieš jį ir, karaliui įsakius, užmėtė jį akmenimis VIEŠPATIES namų kieme.'),
  (@b14, 24, 22, 'Taip karalius Joašas neatsiminė gerumo, kurį jam buvo padaręs jo tėvas Jehojada, bet nužudė jo sūnų. Ir jis mirdamas tarė: „VIEŠPATS į tai pažiūrės ir to pareikalaus“.'),
  (@b14, 24, 23, 'Ir atsitiko, kad metų gale Sirijos kariuomenė atėjo aukštyn prieš jį; ir atėję į Judą ir Jeruzalę, jie išnaikino iš tautos tarpo visus tautos kunigaikščius, ir visą jų grobį nusiuntė Damasko karaliui.'),
  (@b14, 24, 24, 'Nes sirų kariuomenė atėjo su mažu būriu vyrų, o VIEŠPATS atidavė į jų rankas labai didelę kariuomenę, kadangi jie buvo palikę VIEŠPATĮ, savo tėvų Dievą. Taip jie įvykdė teismą prieš Joašą.'),
  (@b14, 24, 25, 'O jiems pasitraukus nuo jo (nes jie paliko jį sunkiose ligose), jo paties tarnai surengė prieš jį sąmokslą dėl kunigo Jehojados sūnų kraujo ir jį nužudė jo lovoje, ir jis mirė; ir jį palaidojo Dovydo mieste, bet jo nepalaidojo karalių kapuose.'),
  (@b14, 24, 26, 'O šitie yra tie, kurie surengė prieš jį sąmokslą: amonietės Šimeatos sūnus Zabadas ir moabietės Šimritos sūnus Jehozabadas.'),
  (@b14, 24, 27, 'Na, o apie jo sūnus ir ant jo užkrautų naštų didumą, ir apie Dievo namų remontą, štai yra surašyta karalių knygos apsakyme. O jo sūnus Amacijas karaliavo jo vietoje.'),
  (@b14, 25, 1, 'Amacijas buvo dvidešimt penkerių metų, kai pradėjo karaliauti, ir dvidešimt devynerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Jehoadana iš Jeruzalės.'),
  (@b14, 25, 2, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, bet ne tobula širdimi.'),
  (@b14, 25, 3, 'Na, o kai karalystė jam buvo įtvirtinta, atsitiko, kad jis užmušė savo tarnus, nužudžiusius jo tėvą karalių.'),
  (@b14, 25, 4, 'Tačiau jų vaikų jis neužmušė, bet padarė, kaip parašyta įstatyme, Mozės knygoje, kur VIEŠPATS įsakė, sakydamas: „Tėvai nemirs dėl vaikų, nei vaikai nemirs dėl tėvų, bet kiekvienas mirs dėl savo paties nuodėmės“.'),
  (@b14, 25, 5, 'Be to, Amacijas surinko Judą ir paskyrė jiems visoje Judėjoje ir Benjamine tūkstantininkų ir šimtininkų pagal jų tėvų namus; ir jis suskaičiavo juos nuo dvidešimties metų ir vyresnius, ir jų radosi trys šimtai tūkstančių rinktinių vyrų, pajėgių išeiti į karą, galinčių valdyti ietį ir skydą.'),
  (@b14, 25, 6, 'Jis dar pasamdė iš Izraelio šimtą tūkstančių narsių galiūnų už šimtą talentų sidabro.'),
  (@b14, 25, 7, 'Bet Dievo vyras atėjo pas jį, sakydamas: „O karaliau, teneina Izraelio kariuomenė su tavimi; nes VIEŠPATS nėra su Izraeliu, tai yra su visais Efraimo vaikais.'),
  (@b14, 25, 8, 'Bet jei nori eiti, daryk tai, būk stiprus mūšiui; Dievas padarys, kad tu krisi priešo akivaizdoje; nes Dievas turi galią padėti ir pargriauti“.'),
  (@b14, 25, 9, 'Ir Amacijas tarė Dievo vyrui: „Bet ką mums daryti dėl šimto talentų, kuriuos daviau Izraelio kariuomenei?“ Ir Dievo vyras atsakė: „VIEŠPATS yra pajėgus tau duoti daug daugiau negu tai“.'),
  (@b14, 25, 10, 'Tada Amacijas atskyrė juos, tai yra kariuomenę, kuri buvo atvykusi pas jį iš Efraimo, kad grįžtų į namus; todėl jų pyktis labai užsidegė prieš Judą, ir jie grįžo į namus labai supykę.'),
  (@b14, 25, 11, 'Ir Amacijas sustiprėjęs išvedė savo tautą ir nuėjo į Druskos slėnį, ir išmušė dešimt tūkstančių Seyro vaikų.'),
  (@b14, 25, 12, 'O kitus dešimt tūkstančių, išlikusių gyvų, Judos vaikai išvedė į nelaisvę, užvedė juos ant uolos viršūnės ir numetė juos nuo uolos viršūnės, kad jie visi sutrupėjo į gabalus.'),
  (@b14, 25, 13, 'Bet kariuomenės kariai, kuriuos Amacijas pasiuntė atgal, kad jie neitų su juo į mūšį, užpuolė Judos miestus nuo Samarijos iki Bet-Horono ir išmušė iš jų tris tūkstančius, ir paėmė daug grobio.'),
  (@b14, 25, 14, 'Na, o Amacijui parvykus po edomiečių žudynių, įvyko, kad jis pargabeno Seyro vaikų dievų ir pastatė juos savo dievais, ir prieš juos lenkėsi, ir degino jiems smilkalus.'),
  (@b14, 25, 15, 'Todėl VIEŠPATIES rūstybė užsidegė prieš Amaciją, ir jis pasiuntė pas jį pranašą, kuris jam tarė: „Kodėl ieškojai tos tautos dievų, kurie negalėjo išgelbėti savo pačių tautos iš tavo rankos?“'),
  (@b14, 25, 16, 'Ir įvyko, kai jis jam kalbėjo, karalius jam tarė: „Ar tu paskirtas karaliaus patarėju? Liaukis; kodėl turėtum būti sumuštas?“ Tada pranašas paliovęs tarė: „Aš žinau, kad Dievas yra nusprendęs tave sunaikinti, nes tu tai padarei ir nepaklausei mano patarimo“.'),
  (@b14, 25, 17, 'Tada Judos karalius Amacijas pasitaręs siuntė Jehuvo sūnaus Jehoachazo sūnui Joašui, Izraelio karaliui, sakydamas: „Eikš, pažiūrėkime vienas kitam į veidą“.'),
  (@b14, 25, 18, 'O Izraelio karalius Joašas pasiuntė Judos karaliui Amacijui, sakydamas: „Usnis, esanti Libane, siuntė Libane esančiam kedrui, sakydama: ‘Duok mano sūnui savo dukterį į žmonas’; ir praėjo Libane esantis laukinis žvėris ir sumindė usnį.'),
  (@b14, 25, 19, 'Tu sakai: ‘Štai aš sumušiau edomiečius’; ir tavo širdis aukština tave, kad girtumeisi; dabar pasilik namie; kodėl turėtum įsivelti, kad sau pakenktum, idant kristum tu pats ir Juda su tavimi?“'),
  (@b14, 25, 20, 'Bet Amacijas nepaklausė; nes tai atėjo iš Dievo, kad jis juos atiduotų į jų priešų rankas, kadangi jie ieškojo Edomo dievų.'),
  (@b14, 25, 21, 'Taigi Izraelio karalius Joašas ėjo aukštyn; jis ir Judos karalius Amacijas pasimatė vienas su kitu veidais Bet-Šemeše, priklausančiame Judai.'),
  (@b14, 25, 22, 'Ir Juda buvo nugalėta Izraelio, ir jie kiekvienas pabėgo į savo palapines.'),
  (@b14, 25, 23, 'O Izraelio karalius Joašas sučiupo Judos karalių Amaciją, Jehoachazo sūnaus Joašo sūnų, Bet-Šemeše ir jį atvedė į Jeruzalę, ir nugriovė Jeruzalės sieną nuo Efraimo vartų iki Kampo vartų, keturis šimtus uolekčių.'),
  (@b14, 25, 24, 'Ir jis paėmė visą auksą, sidabrą ir visus indus, rastus Dievo namuose pas Obed-Edomą, ir karaliaus namų lobius, ir taip pat įkaitus ir sugrįžo į Samariją.'),
  (@b14, 25, 25, 'O Judos karaliaus Joašo sūnus Amacijas po Izraelio karaliaus Jehoachazo sūnaus Joašo mirties gyveno penkiolika metų.'),
  (@b14, 25, 26, 'Na, o kiti Amacijo darbai, pirmieji ir paskutinieji, štai argi jie nėra užrašyti Judos ir Izraelio karalių knygoje?'),
  (@b14, 25, 27, 'Na, o po to laiko, kai Amacijas nusuko į šoną nuo sekimo paskui VIEŠPATĮ, jie surengė prieš jį sąmokslą Jeruzalėje; ir jis pabėgo į Lachišą; bet, pasiuntę jam iš paskos į Lachišą, jie ten jį nužudė.'),
  (@b14, 25, 28, 'Ir pargabeno jį ant žirgų ir palaidojo prie jo tėvų Judos mieste.'),
  (@b14, 26, 1, 'Tada visa Judos tauta paėmė Uziją, kuris buvo šešiolikos metų, ir jį padarė karaliumi jo tėvo Amacijo vietoje.'),
  (@b14, 26, 2, 'Jis pastatė Elotą ir jį sugrąžino Judai po to, kai karalius užmigo prie savo tėvų.'),
  (@b14, 26, 3, 'Uzijas buvo šešiolikos metų, kai pradėjo karaliauti, ir penkiasdešimt dvejus metus karaliavo Jeruzalėje. Jo motinos vardas buvo Jecholija iš Jeruzalės.'),
  (@b14, 26, 4, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, pagal visa tai, ką darė jo tėvas Amacijas.'),
  (@b14, 26, 5, 'Jis ieškojo Dievo per dienas Zacharijo, kuris suprasdavo Dievo regėjimus; ir tol, kol jis ieškojo VIEŠPATIES, Dievas jam davė pasisekimą.'),
  (@b14, 26, 6, 'Ir išėjęs jis kariavo prieš filistinus ir sugriovė Gato sieną, Jabnės sieną ir Ašdodo sieną, ir pastatė miestus aplink Ašdodą ir tarp filistinų.'),
  (@b14, 26, 7, 'Ir Dievas jam padėjo prieš filistinus ir prieš arabus, gyvenančius Gūr-Baale, ir prieš meunus.'),
  (@b14, 26, 8, 'Ir amoniečiai davė Uzijui dovanas; ir jo vardas išgarsėjo iki Egipto įėjimo; nes jis nepaprastai sustiprėjo.'),
  (@b14, 26, 9, 'Be to, Uzijas pastatė Jeruzalėje bokštus prie Kampo vartų, prie Slėnio vartų ir prie sienos pasisukimo ir juos sutvirtino.'),
  (@b14, 26, 10, 'Jis taip pat pastatė bokštus dykumoje ir iškasė daug šulinių; nes jis turėjo daug galvijų tiek žemumose, tiek lygumose; taip pat žemdirbių ir vynuogininkų kalnuose ir Karmelyje; nes jis mėgo žemdirbystę.'),
  (@b14, 26, 11, 'Be to, Uzijas turėjo kariuomenę kovotojų, išeinančių į karą būriais, pagal jų skaičių, suskaičiuotą ranka raštininko Jejelio ir valdovo Maasėjo, vadovaujant rankai Hananijo, vieno iš karaliaus vadų.'),
  (@b14, 26, 12, 'Visas narsių galiūnų tėvų vyriausiųjų skaičius buvo du tūkstančiai šeši šimtai.'),
  (@b14, 26, 13, 'Ir jų rankos valdžioje buvo kariuomenė trijų šimtų septynių tūkstančių penkių šimtų, kariaujančių galinga jėga, kad padėtų karaliui prieš priešą.'),
  (@b14, 26, 14, 'Ir Uzijas paruošė jiems visoje kariuomenėje skydų, iečių, šalmų, šarvų, lankų ir svaidyklių akmenims svaidyti.'),
  (@b14, 26, 15, 'Ir jis padarė Jeruzalėje sumanių žmonių išrastų mašinų, kad jos būtų ant bokštų ir ant tvirtovių strėlėms ir dideliems akmenims šaudyti. Ir jo vardas plačiai išgarsėjo; nes jam buvo nuostabiai pagelbėta, kol jis sustiprėjo.'),
  (@b14, 26, 16, 'Bet kai jis buvo stiprus, jo širdis pasididžiavo jo sunaikinimui; nes jis nusižengė prieš VIEŠPATĮ, savo Dievą, ir įėjo į VIEŠPATIES šventyklą deginti smilkalų ant smilkalų aukuro.'),
  (@b14, 26, 17, 'O paskui jį įėjo kunigas Azarijas ir su juo aštuoniasdešimt VIEŠPATIES kunigų narsuolių;'),
  (@b14, 26, 18, 'ir jie pasipriešino karaliui Uzijui, ir jam tarė: „Ne tau, Uzijau, priklauso deginti smilkalus VIEŠPAČIUI, bet kunigams Aarono sūnums, kurie yra įšventinti smilkyti; išeik iš šventovės; nes tu nusižengei; ir tai nebus tavo garbei iš VIEŠPATIES Dievo“.'),
  (@b14, 26, 19, 'Tada Uzijas užsirūstino, o savo rankoje turėjo smilkytuvą, kad smilkytų; ir jam esant užsirūstinusiam ant kunigų, raupsai iškilo jo kaktoje kunigų akivaizdoje VIEŠPATIES namuose, prie smilkalų aukuro.'),
  (@b14, 26, 20, 'Ir vyriausiasis kunigas Azarijas ir visi kunigai į jį pažvelgė, ir štai jis buvo raupsuotas savo kaktoje, ir jie išstūmė jį iš ten; taip, ir jis pats skubėjo išeiti, nes VIEŠPATS jį buvo ištikęs.'),
  (@b14, 26, 21, 'Ir karalius Uzijas buvo raupsuotas iki savo mirties dienos ir gyveno raupsuotas atskiruose namuose; nes jis buvo iškirstas iš VIEŠPATIES namų; o jo sūnus Jotamas valdė karaliaus namus, teisdamas šalies tautą.'),
  (@b14, 26, 22, 'Na, o kitus Uzijo darbus, pirmus ir paskutinius, užrašė Amoco sūnus, pranašas Izaijas.'),
  (@b14, 26, 23, 'Taigi Uzijas užmigo prie savo tėvų, ir jį palaidojo prie jo tėvų laidojimo lauke, kuris priklausė karaliams; nes jie sakė: „Jis raupsuotas“; o jo sūnus Jotamas karaliavo jo vietoje.'),
  (@b14, 27, 1, 'Jotamas buvo dvidešimt penkerių metų, kai pradėjo karaliauti, ir šešiolika metų karaliavo Jeruzalėje. Taip pat jo motinos vardas buvo Jeruša, Cadoko duktė.'),
  (@b14, 27, 2, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, pagal visa tai, ką darė jo tėvas Uzijas; tačiau jis neįėjo į VIEŠPATIES šventyklą. O tauta vis dar sugedusiai elgėsi.'),
  (@b14, 27, 3, 'Jis pastatė aukštuosius VIEŠPATIES namų vartus ir daug statė ant Ofelio sienos.'),
  (@b14, 27, 4, 'Be to, jis pastatė miestus Judos kalnuose, o miškuose jis pastatė pilis ir bokštus.'),
  (@b14, 27, 5, 'Taip pat jis kovojo su amoniečių karaliumi ir juos nugalėjo. Ir Amono vaikai tais pačiais metais jam davė šimtą talentų sidabro, dešimt tūkstančių saikų kviečių ir dešimt tūkstančių saikų miežių. Tiek Amono vaikai jam mokėjo antraisiais ir trečiaisiais metais.'),
  (@b14, 27, 6, 'Taip Jotamas tapo galingu, nes jis paruošė savo kelius VIEŠPATIES, savo Dievo, akivaizdoje.'),
  (@b14, 27, 7, 'Na, o kiti Jotamo darbai ir visi jo karai, ir jo keliai, štai jie surašyti Izraelio ir Judos karalių knygoje.'),
  (@b14, 27, 8, 'Jis buvo dvidešimt penkerių metų, kai pradėjo karaliauti, ir šešiolika metų karaliavo Jeruzalėje.'),
  (@b14, 27, 9, 'Ir Jotamas užmigo prie savo tėvų, ir jį palaidojo Dovydo mieste; o jo sūnus Ahazas karaliavo jo vietoje.'),
  (@b14, 28, 1, 'Ahazas buvo dvidešimties metų, kai pradėjo karaliauti, ir šešiolika metų karaliavo Jeruzalėje; bet jis nedarė to, kas buvo teisinga VIEŠPATIES akyse, kaip jo tėvas Dovydas;'),
  (@b14, 28, 2, 'nes jis vaikščiojo Izraelio karalių keliais ir taip pat padarė nulietų atvaizdų Baalams.'),
  (@b14, 28, 3, 'Be to, jis smilkė Hinomo sūnaus slėnyje ir degino savo vaikus ugnyje pagal bjaurystes pagonių, kuriuos VIEŠPATS buvo išvaręs Izraelio vaikų akivaizdoje.'),
  (@b14, 28, 4, 'Taip pat jis aukojo ir smilkė aukštumose, ant kalvų ir po kiekvienu žaliuojančiu medžiu.'),
  (@b14, 28, 5, 'Todėl VIEŠPATS, jo Dievas, jį atidavė į Sirijos karaliaus ranką; o jie sumušė jį ir išvedė didelę jų minią nelaisvėn, ir nuvedė juos į Damaską. Jis taip pat buvo atiduotas į rankas Izraelio karaliaus, kuris jį sumušė didelėmis žudynėmis.'),
  (@b14, 28, 6, 'Nes Remalijo sūnus Pekachas per vieną dieną išžudė Judoje šimtą dvidešimt tūkstančių, visus, kurie buvo narsūs vyrai; nes jie buvo palikę VIEŠPATĮ, savo tėvų Dievą.'),
  (@b14, 28, 7, 'O Zichris, Efraimo galiūnas, užmušė karaliaus sūnų Maasėją, namų valdytoją Azrikamą ir Elkaną, antrąjį po karaliaus.'),
  (@b14, 28, 8, 'Ir Izraelio vaikai išsivedė nelaisvėn iš savo brolių du šimtus tūkstančių moterų, sūnų ir dukterų, ir taip pat paėmė iš jų daug grobio ir pargabeno grobį į Samariją.'),
  (@b14, 28, 9, 'Bet ten buvo VIEŠPATIES pranašas, kurio vardas buvo Odedas; ir išėjęs priešais kariuomenę, atėjusią į Samariją, jis jiems tarė: „Kadangi VIEŠPATS, jūsų tėvų Dievas, užsirūstino ant Judos, štai jis juos atidavė į jūsų rankas, o jūs juos žudėte su įniršiu, kuris pasiekia dangų.'),
  (@b14, 28, 10, 'O dabar jūs ketinate pasijungti Judos ir Jeruzalės vaikus vergais ir vergėmis; bet argi jūs patys neturite nuodėmių prieš VIEŠPATĮ, savo Dievą?'),
  (@b14, 28, 11, 'Taigi dabar paklausykite manęs ir sugrąžinkite belaisvius, kuriuos paėmėte nelaisvėn iš savo brolių; nes smarki VIEŠPATIES rūstybė yra ant jūsų“.'),
  (@b14, 28, 12, 'Tada kai kurie iš Efraimo vaikų galvų: Johanano sūnus Azarijas, Mešilemoto sūnus Berechijas, Šalumo sūnus Jehizkijas ir Hadlajo sūnus Amasa atsistojo prieš tuos, kurie parėjo iš karo,'),
  (@b14, 28, 13, 'ir jiems tarė: „Neįveskite čia belaisvių; nes atsižvelgiant į tai, kad mes jau nusikaltome VIEŠPAČIUI, jūs ketinate dar daugiau pridėti prie mūsų nuodėmių ir mūsų nusižengimų; nes mūsų nusižengimas yra didelis, ir smarki rūstybė yra prieš Izraelį“.'),
  (@b14, 28, 14, 'Taigi ginkluotieji paliko belaisvius ir grobį kunigaikščių ir viso susirinkimo akivaizdoje.'),
  (@b14, 28, 15, 'O vyrai, kurie buvo paminėti vardais, pakilę paėmė belaisvius ir visus jų nuoguosius apvilko iš grobio, aprengė juos ir apavė, pavalgydino, pagirdė, patepė juos ir, gabendami ant asilų jų silpnuosius, nuvedė juos į Jerichą, į Palmių miestą, pas jų brolius; paskui jie sugrįžo į Samariją.'),
  (@b14, 28, 16, 'Tuo metu karalius Ahazas siuntė pas Asirijos karalius, kad jam padėtų.'),
  (@b14, 28, 17, 'Nes vėl buvo atėję edomiečiai ir sumušę Judą bei išsivedę belaisvius.'),
  (@b14, 28, 18, 'Taip pat filistinai buvo įsiveržę į žemumos šalies ir pietų Judos miestus ir paėmę Bet-Šemešą, Ajaloną, Gederotą, Sokoją su jo kaimais, Timną su jos kaimais bei Gimzoją su jos kaimais; ir jie ten apsigyveno.'),
  (@b14, 28, 19, 'Nes VIEŠPATS nužemino Judą dėl Izraelio karaliaus Ahazo; nes jis apnuogino Judą ir labai nusižengė prieš VIEŠPATĮ.'),
  (@b14, 28, 20, 'Ir Asirijos karalius Tilgat-Pilneseras atėjo pas jį ir jį spaudė, bet nesustiprino.'),
  (@b14, 28, 21, 'Nes Ahazas paėmė dalį iš VIEŠPATIES namų, iš karaliaus namų ir iš kunigaikščių, ir davė tai Asirijos karaliui; bet jis jam nepadėjo.'),
  (@b14, 28, 22, 'Ir savo suspaudimo laiku jis dar labiau nusižengė VIEŠPAČIUI; šis yra tas karalius Ahazas.'),
  (@b14, 28, 23, 'Nes jis aukojo Damasko dievams, kurie jį sumušė; ir jis sakė: „Kadangi Sirijos karalių dievai jiems padėjo, todėl jiems aukosiu, kad jie man padėtų“. Bet jie buvo pražūtimi jam ir visam Izraeliui.'),
  (@b14, 28, 24, 'Ir Ahazas surinko Dievo namų indus, supjaustė Dievo namų indus, užrakino VIEŠPATIES namų duris ir pasidarė aukurų kiekviename Jeruzalės kampe.'),
  (@b14, 28, 25, 'Ir kiekviename Judos mieste jis padarė aukštumas, kad smilkytų kitiems dievams, ir jis kurstė VIEŠPATIES, savo tėvų Dievo, pyktį.'),
  (@b14, 28, 26, 'Na, o kiti jo darbai ir visi jo keliai, pirmi ir paskutiniai, štai jie surašyti Judos ir Izraelio karalių knygoje.'),
  (@b14, 28, 27, 'Ir Ahazas užmigo prie savo tėvų, ir jį palaidojo mieste – Jeruzalėje; bet jo nenešė į Izraelio karalių kapus; o jo sūnus Chezekijas karaliavo jo vietoje.'),
  (@b14, 29, 1, 'Chezekijas pradėjo karaliauti būdamas dvidešimt penkerių metų, ir dvidešimt devynerius metus karaliavo Jeruzalėje. O jo motinos vardas buvo Abija, Zacharijo duktė.'),
  (@b14, 29, 2, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, pagal visa tai, ką buvo daręs jo tėvas Dovydas.'),
  (@b14, 29, 3, 'Pirmaisiais savo karaliavimo metais, pirmąjį mėnesį, jis atidarė VIEŠPATIES namų duris ir jas pataisė.'),
  (@b14, 29, 4, 'Jis įvedė kunigus bei levitus ir juos surinkęs į rytinę gatvę'),
  (@b14, 29, 5, 'jiems tarė: „Klausykite manęs, levitai, pasišvęskite dabar ir pašvęskite VIEŠPATIES, savo tėvų Dievo, namus, ir išneškite nešvarumą iš šventosios vietos.'),
  (@b14, 29, 6, 'Nes mūsų tėvai nusižengė ir darė tai, kas buvo pikta VIEŠPATIES, mūsų Dievo, akyse, ir jį palikę nugręžė savo veidus nuo VIEŠPATIES buveinės ir atsuko savo nugaras.'),
  (@b14, 29, 7, 'Taip pat jie užrakino prieangio duris, užgesino žibintus, nebesmilkė smilkalų ir nebeatnašavo deginamųjų atnašų Izraelio Dievui šventojoje vietoje.'),
  (@b14, 29, 8, 'Todėl VIEŠPATIES rūstybė buvo ant Judos ir Jeruzalės, ir jis juos atidavė suspaudimui, pasibaisėjimui ir švilpavimui, kaip jūs matote savo akimis.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b14, 29, 9, 'Nes štai mūsų tėvai kritę nuo kalavijo ir mūsų sūnūs, mūsų dukterys ir mūsų žmonos už tai yra nelaisvėje.'),
  (@b14, 29, 10, 'Dabar mano širdyje yra, kad sudaryčiau sandorą su VIEŠPAČIU, Izraelio Dievu, kad jo smarki rūstybė nusigręžtų nuo mūsų.'),
  (@b14, 29, 11, 'Mano sūnūs, nebūkite dabar aplaidūs; nes jus VIEŠPATS išrinko, kad stovėtumėte jo akivaizdoje jam tarnauti ir kad jam tarnautumėte, ir degintumėte smilkalus“.'),
  (@b14, 29, 12, 'Tada pakilo levitai: Amasajo sūnus Mahatas ir Azarijo sūnus Joelis iš kehatų sūnų; o iš merarių sūnų – Abdžio sūnus Kišas ir Jehalelelio sūnus Azarijas; o iš geršonų – Zimos sūnus Joachas ir Joacho sūnus Edenas;'),
  (@b14, 29, 13, 'o iš Elicafano sūnų – Šimris ir Jejelis; o iš Asafo sūnų – Zacharijas ir Matanijas;'),
  (@b14, 29, 14, 'o iš Hemano sūnų – Jehielis ir Šimis; o iš Jedutūno sūnų – Šemaja ir Uzielis.'),
  (@b14, 29, 15, 'Ir surinkę savo brolius ir pasišventę, jie atėjo pagal karaliaus įsakymą, pagal VIEŠPATIES žodžius, kad apvalytų VIEŠPATIES namus.'),
  (@b14, 29, 16, 'Ir kunigai įėjo į VIEŠPATIES namų vidų jų valyti; ir visą nešvarumą, kurį rado VIEŠPATIES šventykloje, išnešė į VIEŠPATIES namų kiemą. O levitai jį paėmė, kad išneštų laukan į Kidrono upelį.'),
  (@b14, 29, 17, 'Na, o pirmojo mėnesio pirmąją dieną jie pradėjo šventinti, o to mėnesio aštuntąją dieną jie atėjo į VIEŠPATIES prieangį; taigi aštuonias dienas jie šventino VIEŠPATIES namus; o pirmojo mėnesio šešioliktąją dieną jie užbaigė.'),
  (@b14, 29, 18, 'Po to, įėję pas karalių Chezekiją, jie pasakė: „Mes išvalėme visus VIEŠPATIES namus, deginamųjų atnašų aukurą su visais jo indais ir parodomosios duonos stalą su visais jo indais.'),
  (@b14, 29, 19, 'Be to, visus indus, kuriuos karalius Ahazas karaliaudamas išmetė savo nusižengime, mes paruošėme ir pašventėme, ir štai jie yra VIEŠPATIES aukuro akivaizdoje“.'),
  (@b14, 29, 20, 'Tada karalius Chezekijas anksti atsikėlęs surinko miesto valdovus ir nuėjo aukštyn į VIEŠPATIES namus.'),
  (@b14, 29, 21, 'Ir jie atvedė septynis jaučius, septynis avinus, septynis avinėlius ir septynias ožkas nuodėmės atnašai už karalystę, už šventovę ir už Judą. Ir jis įsakė Aarono sūnums kunigams juos atnašauti ant VIEŠPATIES aukuro.'),
  (@b14, 29, 22, 'Taigi jie papjovė jaučius, o kunigai, gavę kraują, juo šlakstė aukurą; taip pat, papjovę avinus, jie šlakstė kraują ant aukuro; papjovė jie taip pat ir avinėlius ir šlakstė kraują ant aukuro.'),
  (@b14, 29, 23, 'Ir jie išvedė ožius nuodėmės atnašai karaliaus ir susirinkimo akivaizdoje; ir jie uždėjo ant jų rankas;'),
  (@b14, 29, 24, 'o kunigai juos papjovė ir su jų krauju atliko ant aukuro sutaikinimą, kad atliktų sutaikymą už visą Izraelį; nes karalius įsakė, kad atliktų deginamąją atnašą ir nuodėmės atnašą už visą Izraelį.'),
  (@b14, 29, 25, 'Ir jis pastatė VIEŠPATIES namuose levitus su cimbolais, su psalteriais ir su arfomis, pagal Dovydo, karaliaus regėtojo Gado ir pranašo Natano įsakymą; nes toks buvo VIEŠPATIES įsakymas per jo pranašus.'),
  (@b14, 29, 26, 'Ir levitai stovėjo su Dovydo instrumentais, o kunigai su trimitais.'),
  (@b14, 29, 27, 'Ir Chezekijas įsakė atnašauti ant aukuro deginamąją atnašą. O prasidėjus deginamajai atnašai, prasidėjo ir VIEŠPATIES giesmė su trimitais ir su Izraelio karaliaus Dovydo nustatytais instrumentais.'),
  (@b14, 29, 28, 'Ir visas susirinkimas garbino, giesmininkai giedojo ir trimitininkai leido garsą; ir visa tai tęsėsi, kol buvo užbaigta deginamoji atnaša.'),
  (@b14, 29, 29, 'O pabaigus atnašauti, nusilenkė karalius ir visi su juo esantieji ir pagarbino.'),
  (@b14, 29, 30, 'Be to, karalius Chezekijas ir kunigaikščiai įsakė levitams giedoti gyrių VIEŠPAČIUI Dovydo ir regėtojo Asafo žodžiais. Ir jie džiaugsmingai giedojo gyrių ir nulenkę galvas garbino.'),
  (@b14, 29, 31, 'Tada Chezekijas atsiliepdamas tarė: „Dabar jūs esate pasišventę VIEŠPAČIUI, prieikite ir atgabenkite aukas bei padėkos atnašas į VIEŠPATIES namus“. Ir susirinkimas atgabeno aukas ir padėkos atnašas; o visi, kurie buvo laisva širdimi, – deginamąsias atnašas.'),
  (@b14, 29, 32, 'O skaičius tų deginamųjų atnašų, kurias atgabeno susirinkimas, buvo: septyniasdešimt jaučių, šimtas avinų ir du šimtai avinėlių; visi šitie buvo deginamajai atnašai VIEŠPAČIUI.'),
  (@b14, 29, 33, 'O pašvęstųjų dalykų buvo šeši šimtai jaučių ir trys tūkstančiai avių.'),
  (@b14, 29, 34, 'Bet kunigų buvo per maža, taip, kad jie negalėjo nulupti visų deginamųjų atnašų; todėl jiems padėjo jų broliai levitai, kol darbas buvo baigtas ir kol pasišventė kiti kunigai; nes levitai buvo tiesesni širdimi, kad pašvęstų save, negu kunigai.'),
  (@b14, 29, 35, 'Taip pat buvo gausu deginamųjų atnašų su taikos atnašų taukais ir geriamųjų atnašų kiekvienai deginamajai atnašai. Taip buvo sutvarkytas VIEŠPATIES namų tarnavimas.'),
  (@b14, 29, 36, 'O Chezekijas ir visa tauta džiaugėsi, kad Dievas buvo paruošęs tautą; nes tai atsitiko staiga.'),
  (@b14, 30, 1, 'Ir Chezekijas išsiuntinėjo visam Izraeliui bei Judai ir taip pat parašė laiškus Efraimui ir Manasui, kad jie ateitų į VIEŠPATIES namus Jeruzalėje švęsti Apėjimo VIEŠPAČIUI, Izraelio Dievui.'),
  (@b14, 30, 2, 'Nes karalius, jo kunigaikščiai ir visas Jeruzalės susirinkimas susitarė švęsti Apėjimą antrąjį mėnesį.'),
  (@b14, 30, 3, 'Nes tuo metu jie negalėjo jo švęsti, kadangi kunigai nebuvo pakankamai pasišventę ir tauta nebuvo susirinkusi į Jeruzalę.'),
  (@b14, 30, 4, 'Ir tas dalykas patiko karaliui ir visam susirinkimui.'),
  (@b14, 30, 5, 'Taigi jie įsteigė įsaką, kad paskelbtų visame Izraelyje nuo Beer-Šebos iki Dano, kad jie ateitų švęsti Apėjimą VIEŠPAČIUI, Izraelio Dievui, Jeruzalėje; nes jie nebuvo to darę ilgą laiką taip, kaip yra parašyta.'),
  (@b14, 30, 6, 'Taigi bėgikai su laiškais iš karaliaus ir jo kunigaikščių ėjo per visą Izraelį bei Judą pagal karaliaus įsakymą, sakydami: „Izraelio vaikai, atsigręžkite į VIEŠPATĮ, Abraomo, Izaoko ir Izraelio Dievą, ir jis sugrįš pas jūsų likutį, pabėgusį iš Asirijos karalių rankos.'),
  (@b14, 30, 7, 'Nebūkite kaip jūsų tėvai ir kaip jūsų broliai, kurie nusižengė prieš VIEŠPATĮ, savo tėvų Dievą, todėl jis juos paliko suniokojimui, kaip jūs matote.'),
  (@b14, 30, 8, 'Na, o dabar nebūkite kietasprandžiai, kaip buvo jūsų tėvai, bet atiduokite save VIEŠPAČIUI ir įeikite į jo šventovę, kurią jis pašventė per amžius; ir tarnaukite VIEŠPAČIUI savo Dievui, kad nusigręžtų nuo jūsų jo rūstybės įniršis.'),
  (@b14, 30, 9, 'Nes, jei gręšitės į VIEŠPATĮ, jūsų broliai ir jūsų vaikai ras pasigailėjimą akivaizdoje tų, kurie juos išvedė į nelaisvę, taip, kad jie sugrįš į šitą šalį; nes VIEŠPATS, jūsų Dievas, yra maloningas ir gailestingas ir nenukreips savo veido nuo jūsų, jei sugrįšite pas jį“.'),
  (@b14, 30, 10, 'Taigi bėgikai ėjo iš miesto į miestą per Efraimo ir Manaso kraštą iki Zebulono; bet juos išjuokė ir tyčiojosi iš jų.'),
  (@b14, 30, 11, 'Tačiau kai kurie iš Ašero, Manaso ir Zebulono nusižemino ir atvyko į Jeruzalę.'),
  (@b14, 30, 12, 'Judoje irgi buvo VIEŠPATIES ranka, kad jiems duotų vieną širdį vykdyti karaliaus ir kunigaikščių įsakymą pagal VIEŠPATIES žodį.'),
  (@b14, 30, 13, 'Ir antrąjį mėnesį susirinko į Jeruzalę daug liaudies švęsti Neraugintos duonos šventės – labai gausus susirinkimas.'),
  (@b14, 30, 14, 'Ir pakilę jie pašalino Jeruzalėje esančius aukurus ir pašalino visus aukurus smilkalams, ir sumetė juos į Kidrono upelį.'),
  (@b14, 30, 15, 'Tada jie papjovė Apėjimą antrojo mėnesio keturioliktąją dieną; o kunigai ir levitai susigėdę pasišventė ir atgabeno deginamąsias atnašas į VIEŠPATIES namus.'),
  (@b14, 30, 16, 'Ir jie stovėjo savo vietoje pagal savo būdą, pagal Dievo vyro Mozės įstatymą: kunigai šlakstė kraują, gautą iš levitų rankų.'),
  (@b14, 30, 17, 'Nes susirinkime buvo daug tokių, kurie nebuvo pašvęsti; todėl levitų pareiga buvo pjauti Apėjimą už kiekvieną nešvarųjį, kad pašvęstų juos VIEŠPAČIUI.'),
  (@b14, 30, 18, 'Nes tautos daugybė, tai yra daugelis iš Efraimo ir Manaso, Isacharo ir Zebulono, nebuvo apsivalę, tačiau valgė Apėjimą kitaip, negu buvo parašyta. Bet Chezekijas meldėsi už juos, sakydamas: „Gerasis VIEŠPATIE, atleisk kiekvienam,'),
  (@b14, 30, 19, 'kuris paruošia savo širdį ieškoti Dievo, VIEŠPATIES, savo tėvų Dievo, nors ir nėra apvalytas pagal šventovės apvalymą“.'),
  (@b14, 30, 20, 'Ir VIEŠPATS išklausė Chezekiją ir išgydė tautą.'),
  (@b14, 30, 21, 'Ir Izraelio vaikai, esantys Jeruzalėje, septynias dienas šventė Neraugintos duonos šventę su dideliu džiaugsmu; o levitai ir kunigai diena iš dienos gyrė VIEŠPATĮ, giedodami su skambiais instrumentais VIEŠPAČIUI.'),
  (@b14, 30, 22, 'Ir Chezekijas kalbėjo paguodžiančiai visiems levitams, kurie mokė gero VIEŠPATIES pažinimo; ir jie valgė per šventę septynias dienas, atnašaudami taikos atnašas ir atlikdami išpažinimą VIEŠPAČIUI, savo tėvų Dievui.'),
  (@b14, 30, 23, 'Ir visas susirinkimas nutarė švęsti kitas septynias dienas; ir jie su džiaugsmu šventė kitas septynias dienas.'),
  (@b14, 30, 24, 'Nes Judos karalius Chezekijas davė susirinkimui tūkstantį jaučių ir septynis tūkstančius avių; o kunigaikščiai davė susirinkimui tūkstantį jaučių ir dešimt tūkstančių avių; ir didelis kunigų skaičius pašventė save.'),
  (@b14, 30, 25, 'Ir džiaugėsi visas Judos susirinkimas su kunigais, levitais bei visu susirinkimu, atvykusiu iš Izraelio, ir ateiviai, atvykę iš Izraelio šalies ir gyvenantys Judoje.'),
  (@b14, 30, 26, 'Taigi buvo didelis džiaugsmas Jeruzalėje; nes nuo Izraelio karaliaus Dovydo sūnaus Saliamono laikų nieko panašaus nėra buvę Jeruzalėje.'),
  (@b14, 30, 27, 'Paskui kunigai levitai pakilę palaimino tautą; ir jų balsas buvo išgirstas, ir jų malda nuėjo aukštyn į jo šventąją buveinę – į dangų.'),
  (@b14, 31, 1, 'Na, o kai visa tai pasibaigė, visas dalyvaujantis Izraelis, išėję į Judos miestus, sutrupino atvaizdus, iškirto giraites ir nugriovė aukštumas bei aukurus visoje Judoje ir Benjamine, taip pat Efraime ir Manase, kol jie visiškai juos visus sunaikino. Paskui visi Izraelio vaikai sugrįžo, kiekvienas į savo nuosavybę, į savo miestus.'),
  (@b14, 31, 2, 'O Chezekijas paskyrė kunigų bei levitų skyrius, pagal jų skyrius, kiekvieną pagal jo tarnavimą, kunigus ir levitus deginamosioms atnašoms ir taikos atnašoms, kad tarnautų ir dėkotų, ir girtų VIEŠPATIES palapinių vartuose.'),
  (@b14, 31, 3, 'Taip pat jis paskyrė karaliaus dalį iš savo nuosavybės deginamosioms atnašoms, tai yra deginamosioms ryto bei vakaro atnašoms ir deginamosioms atnašoms sabatams, jaunam mėnuliui ir paskirtoms šventėms, kaip yra parašyta VIEŠPATIES įstatyme.'),
  (@b14, 31, 4, 'Jis dar įsakė tautai, gyvenančiai Jeruzalėje, kad duotų kunigų ir levitų dalį, kad jie būtų padrąsinti VIEŠPATIES įstatyme.'),
  (@b14, 31, 5, 'Ir vos tik įsakymas pasklido, Izraelio vaikai gausiai atnešė pirmavaisius javų, vyno, aliejaus, medaus ir viso laukų prieaugio; jie gausiai atnešė visko dešimtinę.'),
  (@b14, 31, 6, 'O Izraelio ir Judos vaikai, gyvenantys Judos miestuose, jie irgi atgabeno dešimtinę jaučių bei avių ir dešimtinę šventų dalykų, pašvęstų VIEŠPAČIUI, jų Dievui, ir juos sudėjo krūvomis.'),
  (@b14, 31, 7, 'Trečiąjį mėnesį jie pradėjo dėti krūvų pagrindą, o septintąjį mėnesį jas užbaigė.'),
  (@b14, 31, 8, 'O Chezekijas ir kunigaikščiai, atėję ir pamatę krūvas, laimino VIEŠPATĮ ir jo tautą Izraelį.'),
  (@b14, 31, 9, 'Tada Chezekijas klausinėjo kunigų ir levitų apie krūvas.'),
  (@b14, 31, 10, 'Ir vyriausiasis kunigas Azarijas iš Cadoko namų jam atsakė ir tarė: „Nuo to laiko, kai tauta pradėjo gabenti atnašas į VIEŠPATIES namus, mes turėjome užtektinai valgyti, ir gausiai atlieka; nes VIEŠPATS palaimino savo tautą; o tai, kas atliko, yra ši didelė gausybė“.'),
  (@b14, 31, 11, 'Tada Chezekijas įsakė paruošti kambarius VIEŠPATIES namuose; ir juos paruošę'),
  (@b14, 31, 12, 'jie ištikimai įnešė atnašas, dešimtines ir pašvęstus dalykus; kurių valdovas buvo levitas Konanijas, o jo brolis Šimis buvo po jo.'),
  (@b14, 31, 13, 'O Jehielis, Azazijas, Nahatas, Asaelis, Jerimotas, Jozabadas, Elielis, Ismakijas, Mahatas ir Benajas buvo prižiūrėtojai, vadovaujant rankai Konanijo ir jo brolio Šimio pagal karaliaus Chezekijo ir Dievo namų valdovo Azarijo įsakymą.'),
  (@b14, 31, 14, 'O Imnos sūnus Korė, levitas, durininkas rytų link, prižiūrėjo laisvos valios Dievo atnašas, kad paskirstytų VIEŠPATIES aukas ir švenčiausius dalykus.'),
  (@b14, 31, 15, 'O po jo buvo Edenas, Minjaminas, Ješūva, Šemajas, Amarijas ir Šekanijas kunigų miestuose, jų paskirtoje tarnystėje, kad duotų jų broliams pagal skyrius, tiek dideliems, tiek mažiems;'),
  (@b14, 31, 16, 'šalia jų vyriškosios lyties genealogijos, nuo trejų metų ir vyresniems, būtent visiems įeinantiems į VIEŠPATIES namus, jų kasdienę dalį už jų tarnavimą jų pareigose pagal jų skyrius;'),
  (@b14, 31, 17, 'genealogijai kunigų pagal jų tėvų namus ir levitų, nuo dvidešimties metų ir vyresnių, jų pareigose pagal jų skyrius;'),
  (@b14, 31, 18, 'ir genealogijai visų jų mažylių, jų žmonų, jų sūnų ir jų dukterų, visame susirinkime; nes jų paskirtose tarnystėse jie pasišventė šventumu;'),
  (@b14, 31, 19, 'taip pat iš Aarono sūnų kunigų, esančių jų miestų priemiesčių laukuose, kiekviename atskirame mieste, vyrai, paminėti vardais, kad išduotų dalis visiems vyriškiams tarp kunigų ir visiems suskaičiuotiems pagal genealogiją tarp levitų.'),
  (@b14, 31, 20, 'Taip Chezekijas darė visoje Judoje, ir darė, kas buvo gera, teisinga ir tiesa VIEŠPATIES, jo Dievo, akyse.'),
  (@b14, 31, 21, 'Ir kiekviename darbe, kurį jis pradėjo Dievo namų tarnavime ir įstatyme bei įsakymuose, kad ieškotų savo Dievo, jis tai darė visa savo širdimi ir klestėjo.'),
  (@b14, 32, 1, 'Po šitų dalykų ir jų įtvirtinimo, atėjo Asirijos karalius Sancheribas ir įėjo į Judą, ir stovyklavo prieš aptvertus miestus, ir manė juos sau užkariauti.'),
  (@b14, 32, 2, 'Ir Chezekijas pamatęs, kad Sancheribas buvo atėjęs ir ketino kovoti prieš Jeruzalę,'),
  (@b14, 32, 3, 'tarėsi su savo kunigaikščiais ir savo galiūnais, kad užkimštų už miesto esančių šaltinių vandenis; ir jie jam padėjo.'),
  (@b14, 32, 4, 'Taigi susirinko daug liaudies, kurie užkimšo visus šaltinius ir per šalies vidurį tekantį upelį, sakydami: „Kodėl atėję Asirijos karaliai turėtų rasti daug vandens?“'),
  (@b14, 32, 5, 'Taip pat jis sustiprėjo ir pastatė visą sugriautą sieną, pakėlė ją iki bokštų, o lauko pusėje – kitą sieną ir suremontavo Miloją Dovydo mieste, ir padarė gausybę iečių bei skydų.'),
  (@b14, 32, 6, 'Jis paskyrė tautai karo vadus ir, surinkęs juos pas save į miesto vartų gatvę, kalbėjo jiems paguodžiančiai, sakydamas:'),
  (@b14, 32, 7, '„Būkite stiprūs ir drąsūs, nebijokite ir nebūkite nerimastingi dėl Asirijos karaliaus ir visos su juo esančios daugybės; nes su mumis yra daugiau negu su juo:'),
  (@b14, 32, 8, 'su juo yra kūno ranka; bet su mumis yra VIEŠPATS, mūsų Dievas, kad mums padėtų ir kovotų mūsų kovas“. Ir tauta pasirėmė Judos karaliaus Chezekijo žodžiais.'),
  (@b14, 32, 9, 'Po to Asirijos karalius Sancheribas pasiuntė savo tarnus į Jeruzalę (bet jis pats apgulė Lachišą ir su juo visa jo jėga) pas Judos karalių Chezekiją ir pas visą Judą, esančią Jeruzalėje, sakydamas:'),
  (@b14, 32, 10, '„Taip sako Asirijos karalius Sancheribas: ‘Kuo jūs pasitikite, kad pasiliekate apgultyje Jeruzalėje?'),
  (@b14, 32, 11, 'Argi ne Chezekijas įtikinėja jus atsiduoti mirčiai nuo bado ir troškulio, sakydamas: „VIEŠPATS, mūsų Dievas, mus išgelbės iš Asirijos karaliaus rankų?“'),
  (@b14, 32, 12, 'Argi ne tas pats Chezekijas pašalino jo aukštumas bei jo aukurus ir įsakė Judai bei Jeruzalei, sakydamas: „Garbinkite prieš vieną aukurą ir ant jo smilkykite?“'),
  (@b14, 32, 13, 'Argi nežinote, ką aš ir mano tėvai padarėme visoms kitų šalių tautoms? Ar tų šalių tautų dievai kaip nors galėjo išgelbėti savo šalis iš mano rankos?'),
  (@b14, 32, 14, 'Kuris tarp visų dievų tų tautų, kurias mano tėvai visiškai sunaikino, galėjo išgelbėti savo tautą iš mano rankos, kad jūsų Dievas galėtų jus išgelbėti iš mano rankos?'),
  (@b14, 32, 15, 'Taigi dabar tegul Chezekijas šiame dalyke jūsų neapgaudinėja ir neįtikinėja, nei netikėkite juo; nes joks bet kurios tautos ar karalystės dievas negalėjo išgelbėti savo tautos iš mano rankos ir iš mano tėvų rankos; tai kaip juo labiau jūsų Dievas neišgelbės jūsų iš mano rankos?’“.'),
  (@b14, 32, 16, 'Ir dar daugiau jo tarnai kalbėjo prieš VIEŠPATĮ Dievą ir prieš jo tarną Chezekiją.'),
  (@b14, 32, 17, 'Jis taip pat parašė laiškus, keikti VIEŠPATĮ, Izraelio Dievą, ir prieš jį kalbėti, sakant: „Kaip kitų šalių tautų dievai neišgelbėjo savo tautų iš mano rankos, taip ir Chezekijo Dievas neišgelbės savo tautos iš mano rankos“.'),
  (@b14, 32, 18, 'Tada jie garsiu balsu šaukė žydų kalba Jeruzalės tautai, esančiai ant sienos, kad juos įbaugintų ir sudrumstų; kad jie galėtų paimti miestą.'),
  (@b14, 32, 19, 'Ir jie kalbėjo prieš Jeruzalės Dievą kaip prieš žemės tautų dievus, kurie yra žmogaus rankų darbas.'),
  (@b14, 32, 20, 'Dėl to karalius Chezekijas ir pranašas Izaijas, Amoco sūnus, meldėsi ir šaukė į dangų.'),
  (@b14, 32, 21, 'Ir VIEŠPATS pasiuntė angelą, kuris iškirto visus narsius galiūnus, vadovus ir vadus Asirijos karaliaus stovykloje. Taip jis grįžo susigėdusiu veidu į savo šalį. Ir jam įėjus į savo dievo namus, tie, kurie buvo kilę iš jo vidurių, užmušė jį ten kalaviju.'),
  (@b14, 32, 22, 'Taip VIEŠPATS išgelbėjo Chezekiją ir Jeruzalės gyventojus iš Asirijos karaliaus Sancheribo rankos ir iš visų kitų rankos, ir vedė juos iš visų pusių.'),
  (@b14, 32, 23, 'Ir daugelis nešė dovanas VIEŠPAČIUI į Jeruzalę ir dovanas Judos karaliui Chezekijui; taip, kad nuo to laiko jis buvo išaukštintas visų tautų akyse.'),
  (@b14, 32, 24, 'Tomis dienomis Chezekijas mirtinai susirgo ir meldėsi VIEŠPAČIUI; ir jis jam kalbėjo ir jam davė ženklą.'),
  (@b14, 32, 25, 'Bet Chezekijas neatsilygino pagal jam padarytą geradarystę; nes jo širdis pasididžiavo; todėl rūstybė buvo ant jo ir ant Judos bei Jeruzalės.'),
  (@b14, 32, 26, 'Tačiau Chezekijas nusižemino dėl savo širdies išdidumo, jis pats ir Jeruzalės gyventojai, taip, kad VIEŠPATIES rūstybė neatėjo ant jų Chezekijo dienomis.'),
  (@b14, 32, 27, 'Ir Chezekijas turėjo nepaprastai daug turtų bei garbės; ir jis pasidarė lobynų sidabrui, auksui, brangiems akmenims, kvepalams, skydams ir visokioms geistinoms brangenybėms;'),
  (@b14, 32, 28, 'taip pat sandėlių javų, vyno ir aliejaus prieaugiui; ir tvartų visokiems gyvuliams ir aptvarų kaimenėms.'),
  (@b14, 32, 29, 'Be to jis parūpino sau miestų, ir gausią kaimenių ir bandų nuosavybę; nes Dievas jam davė labai daug turto.'),
  (@b14, 32, 30, 'Taip pat šitas Chezekijas užkimšo aukštutinį Gihono vandentakį ir nuvedė jį tiesiai žemyn į vakarinę Dovydo miesto pusę. Ir Chezekijas klestėjo visuose savo darbuose.'),
  (@b14, 32, 31, 'Tačiau dėl Babilono kunigaikščių pasiuntinių, jų atsiųstų pas jį teirautis dėl stebuklo, įvykusio šalyje, šiuo atveju Dievas jį paliko, kad išmėgintų jį, kad sužinotų viską, kas buvo jo širdyje.'),
  (@b14, 32, 32, 'Na, o kiti Chezekijo darbai ir jo gerumas, štai jie surašyti pranašo Izaijo, Amoco sūnaus, regėjime bei Judos ir Izraelio karalių knygoje.'),
  (@b14, 32, 33, 'Ir Chezekijas užmigo prie savo tėvų, ir jį palaidojo geriausiame iš Dovydo sūnų kapų; ir jam mirus visa Juda ir Jeruzalės gyventojai jį pagerbė. O jo sūnus Manasas karaliavo jo vietoje.'),
  (@b14, 33, 1, 'Manasas buvo dvylikos metų, kai pradėjo karaliauti, ir penkiasdešimt penkerius metus karaliavo Jeruzalėje;'),
  (@b14, 33, 2, 'bet darė tai, kas buvo pikta VIEŠPATIES akyse, panašiai į bjaurystes pagonių, kuriuos VIEŠPATS buvo išvaręs iš Izraelio vaikų akivaizdos.'),
  (@b14, 33, 3, 'Nes jis atstatė aukštumas, kurias jo tėvas Chezekijas buvo nugriovęs, pastatė aukurų Baalams, padarė giraičių, garbino visą dangaus kariuomenę ir jiems tarnavo.'),
  (@b14, 33, 4, 'Taip pat jis pastatė aukurų VIEŠPATIES namuose, apie kuriuos VIEŠPATS buvo pasakęs: „Jeruzalėje mano vardas bus per amžius“.'),
  (@b14, 33, 5, 'Jis pastatė aukurų visai dangaus kariuomenei dviejuose VIEŠPATIES namų kiemuose.'),
  (@b14, 33, 6, 'Ir jis padarė, kad jo vaikai eitų per ugnį Hinomo sūnaus slėnyje; taip pat jis laikėsi laikų, užsiiminėjo kerais, užsiiminėjo raganavimu, užsiiminėjo namų dvasiomis bei magais; jis darė daug pikto VIEŠPATIES akyse jo pykčio kurstymui.'),
  (@b14, 33, 7, 'Jis pastatė drožtą atvaizdą, stabą, kurį buvo padaręs, Dievo namuose, apie kuriuos Dievas buvo pasakęs Dovydui ir jo sūnui Saliamonui: „Šituose namuose ir Jeruzalėje, kurią išrinkau iš visų Izraelio genčių, aš amžiams pastatysiu savo vardą;'),
  (@b14, 33, 8, 'ir nebepašalinsiu Izraelio kojos nuo tos šalies, kurią paskyriau jūsų tėvams; idant jie žiūrėtų, kad vykdytų viską, ką esu jiems įsakęs, pagal visą įstatymą, įstatus ir potvarkius per Mozės ranką“.'),
  (@b14, 33, 9, 'Taigi Manasas skatino Judą ir Jeruzalės gyventojus klysti ir elgtis blogiau už pagonis, kuriuos VIEŠPATS buvo išnaikinęs Izraelio vaikų akivaizdoje.'),
  (@b14, 33, 10, 'Ir VIEŠPATS kalbėjo Manasui ir jo tautai; bet jie neklausė.'),
  (@b14, 33, 11, 'Todėl VIEŠPATS atvedė ant jų Asirijos karaliaus kariuomenės vadus, kurie sugavo Manasą tarp erškėčių, sukaustė jį grandinėmis ir nuvedė į Babiloną.'),
  (@b14, 33, 12, 'Ir būdamas suspaudime jis maldavo VIEŠPATIES, savo Dievo, ir labai nusižemino prieš savo tėvų Dievą,'),
  (@b14, 33, 13, 'ir meldėsi jam; ir jis davėsi jo išmeldžiamas ir išklausė jo prašymą, ir jį parvedė į Jeruzalę, į jo karalystę. Tada Manasas suprato, kad VIEŠPATS yra Dievas.'),
  (@b14, 33, 14, 'Na, o po to jis pastatė sieną Dovydo miesto išorėje, Gihono vakarinėje pusėje, slėnyje, iki įėjimo į Žuvų vartus, darydamas lanką aplink Ofelį, ir ją iškėlė labai aukštą, ir pastatė karo vadus visuose aptvertuose Judos miestuose.'),
  (@b14, 33, 15, 'Ir jis pašalino svetimus dievus ir stabą iš VIEŠPATIES namų bei visus aukurus, kuriuos jis buvo pastatęs ant VIEŠPATIES namų kalno ir Jeruzalėje, ir išmetė juos iš miesto.'),
  (@b14, 33, 16, 'Ir jis sutaisė VIEŠPATIES aukurą ir aukojo ant jo taikos atnašas bei padėkos atnašas, ir įsakė Judai tarnauti VIEŠPAČIUI, Izraelio Dievui.'),
  (@b14, 33, 17, 'Tačiau tauta vis dar aukojo aukštumose, bet vien tik VIEŠPAČIUI, savo Dievui.'),
  (@b14, 33, 18, 'Na, o kiti Manaso darbai, jo malda savo Dievui ir žodžiai regėtojų, kurie jam kalbėjo VIEŠPATIES, Izraelio Dievo, vardu, štai jie užrašyti Izraelio karalių knygoje.'),
  (@b14, 33, 19, 'Taip pat jo malda ir kaip Dievas davėsi jo išmeldžiamas, ir visa jo nuodėmė, ir jo nusižengimas, ir vietos, kuriose jis prieš savo nusižeminimą pastatė aukštumas ir pastatė giraites bei raižytus atvaizdus; štai jie užrašyti tarp regėtojų pasakymų.'),
  (@b14, 33, 20, 'Taigi Manasas užmigo prie savo tėvų, ir jį palaidojo jo namuose; o jo sūnus Amonas karaliavo jo vietoje.'),
  (@b14, 33, 21, 'Amonas buvo dvidešimt dvejų metų, kai pradėjo karaliauti, ir dvejus metus karaliavo Jeruzalėje.'),
  (@b14, 33, 22, 'Bet jis darė tai, kas buvo pikta VIEŠPATIES akyse, kaip darė jo tėvas Manasas; nes Amonas aukojo visiems drožtiems atvaizdams, kuriuos buvo padaręs jo tėvas Manasas, ir jiems tarnavo;'),
  (@b14, 33, 23, 'ir nenusižemino VIEŠPATIES akivaizdoje, kaip nusižemino jo tėvas Manasas; bet Amonas nusižengė vis labiau ir labiau.'),
  (@b14, 33, 24, 'Ir jo tarnai surengė prieš jį sąmokslą ir užmušė jį jo namuose.'),
  (@b14, 33, 25, 'Bet šalies tauta užmušė visus tuos, kurie buvo surengę sąmokslą prieš karalių Amoną; ir šalies tauta padarė karaliumi jo sūnų Joziją jo vietoje.'),
  (@b14, 34, 1, 'Jozijas buvo aštuonerių metų, kai pradėjo karaliauti, ir trisdešimt vienerius metus karaliavo Jeruzalėje.'),
  (@b14, 34, 2, 'Ir jis darė tai, kas buvo teisinga VIEŠPATIES akyse, ir vaikščiojo savo tėvo Dovydo keliais, ir nenukrypo nei į dešinę, nei į kairę.'),
  (@b14, 34, 3, 'Nes aštuntaisiais savo karaliavimo metais, dar būdamas jaunas, jis pradėjo ieškoti savo tėvo Dovydo Dievo; o dvyliktaisiais metais jis pradėjo valyti Judą ir Jeruzalę nuo aukštumų, giraičių, drožtų atvaizdų ir nulietų atvaizdų.'),
  (@b14, 34, 4, 'Jo akivaizdoje jie sugriovė Baalų aukurus; o atvaizdus, buvusius aukštai virš jų, jis iškirto; giraites ir drožtus atvaizdus bei nulietus atvaizdus jis sutrupino ir pavertė į dulkes, ir išbarstė jas ant kapų tų, kurie jiems aukojo.'),
  (@b14, 34, 5, 'O kunigų kaulus jis sudegino ant jų aukurų ir apvalė Judą bei Jeruzalę.'),
  (@b14, 34, 6, 'Ir taip su kirstuvais jis padarė Manaso, Efraimo ir Simeono miestuose iki Naftalio, aplinkui.'),
  (@b14, 34, 7, 'Ir nugriovęs aukurus bei giraites ir sudaužęs raižytus atvaizdus į dulkes, ir iškirtęs visus stabus visoje Izraelio šalyje, jis sugrįžo į Jeruzalę.'),
  (@b14, 34, 8, 'Na, o aštuonioliktaisiais savo karaliavimo metais, išvalęs šalį ir namus, jis siuntė Acalijo sūnų Šafaną, miesto valdytoją Maasėją ir metraštininką Joachą, Joahazo sūnų, VIEŠPATIES, savo Dievo, namų remontuoti.'),
  (@b14, 34, 9, 'Ir atėję pas aukščiausiąjį kunigą Hilkiją, jie perdavė į Dievo namus atneštus pinigus, kuriuos levitai, saugojantys duris, surinko iš Manaso, Efraimo ir iš viso likusio Izraelio, ir iš visos Judos bei Benjamino rankų; ir jie grįžo į Jeruzalę.'),
  (@b14, 34, 10, 'Ir jie juos įdėjo į rankas darbininkų, prižiūrinčių VIEŠPATIES namus, o jie davė juos darbininkams, dirbantiems VIEŠPATIES namuose, kad suremontuotų ir pataisytų namus;'),
  (@b14, 34, 11, 'būtent amatininkams ir statytojams jie davė juos, kad nupirktų tašytų akmenų ir medžių sukabinimams ir kad sudėtų grindis namuose, kuriuos Judos karaliai buvo sunaikinę.'),
  (@b14, 34, 12, 'Ir vyrai ištikimai dirbo darbą; o jų prižiūrėtojai buvo levitai Jahatas ir Abdijas iš merarių sūnų; o Zacharija ir Mešulamas iš kehatų sūnų, kad pastūmėtų tai į priekį; o kiti levitai – visi, kurie mokėjo groti muzikos instrumentais.'),
  (@b14, 34, 13, 'Taip pat jie vadovavo naštų nešikams ir prižiūrėjo visus dirbančius darbą visokiame tarnavime; o iš levitų buvo raštininkai, pareigūnai ir durininkai.'),
  (@b14, 34, 14, 'Ir jiems išimant pinigus, atneštus į VIEŠPATIES namus, kunigas Hilkijas rado VIEŠPATIES įstatymo knygą, duotą per Mozę.'),
  (@b14, 34, 15, 'Ir Hilkijas atsiliepdamas tarė raštininkui Šafanui: „Radau įstatymo knygą VIEŠPATIES namuose“. Ir Hilkijas padavė knygą Šafanui.'),
  (@b14, 34, 16, 'O Šafanas nunešė knygą karaliui ir parnešė karaliui žinią, sakydamas: „Jie daro viską, kas buvo pavesta tavo tarnams.'),
  (@b14, 34, 17, 'Ir jie surinko pinigus, rastus VIEŠPATIES namuose, ir juos perdavė į prižiūrėtojų rankas ir darbininkų rankas“.'),
  (@b14, 34, 18, 'Tada raštininkas Šafanas pranešė karaliui, sakydamas: „Kunigas Hilkijas davė man knygą“. Ir Šafanas skaitė ją karaliaus akivaizdoje.'),
  (@b14, 34, 19, 'Ir įvyko, kai karalius išgirdo įstatymo žodžius, jis perplėšė savo drabužius.'),
  (@b14, 34, 20, 'Ir karalius įsakė Hilkijui, Šafano sūnui Ahikamui, Michos sūnui Abdonui, raštininkui Šafanui ir karaliaus tarnui Asajai, sakydamas:'),
  (@b14, 34, 21, '„Eikite, pasiklauskite VIEŠPATIES už mane ir už likusiuosius Izraelyje ir Judoje dėl atrastos knygos žodžių; nes didelė VIEŠPATIES rūstybė, kuri yra išlieta ant mūsų, kadangi mūsų tėvai nesilaikė VIEŠPATIES žodžio, kad darytų pagal visa tai, kas parašyta šitoje knygoje“.'),
  (@b14, 34, 22, 'Ir Hilkijas ir tie, kuriuos karalius buvo paskyręs, nuėjo pas pranašę Huldą, žmoną drabužių saugotojo Šalumo, Hasros sūnaus Tikvato sūnaus (na, o ji gyveno Jeruzalėje, mokymo namuose), ir jie kalbėjo jai apie tai.'),
  (@b14, 34, 23, 'Ir ji jiems atsakė: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Praneškite vyrui, kuris jus atsiuntė pas mane:'),
  (@b14, 34, 24, '„Taip sako VIEŠPATS: Štai aš užleisiu nelaimę ant šitos vietos ir ant jos gyventojų, tai yra visus prakeikimus, užrašytus knygoje, kurią jie perskaitė Judos karaliaus akivaizdoje;'),
  (@b14, 34, 25, 'nes jie paliko mane ir degino smilkalus kitiems dievams, kad kurstytų mano pyktį visais savo rankų darbais; todėl mano rūstybė bus išlieta ant šitos vietos ir neužges“.'),
  (@b14, 34, 26, 'O Judos karaliui, kuris jus siuntė pasiklausti VIEŠPATIES, taip jam tarkite: Taip sako VIEŠPATS, Izraelio Dievas dėl žodžių, kuriuos tu girdėjai:'),
  (@b14, 34, 27, 'Kadangi tavo širdis buvo minkšta ir tu nusižeminai prieš Dievą, girdėdamas jo žodžius prieš šitą vietą ir prieš jos gyventojus, ir kadangi nusižeminai prieš mane, perplėšei savo drabužius ir verkei mano akivaizdoje; tai ir aš tave išgirdau, – sako VIEŠPATS.'),
  (@b14, 34, 28, '– Štai aš tave surinksiu prie tavo tėvų, ir tu būsi surinktas į savo kapą ramybėje, ir tavo akys nematys viso to pikto, kurį aš užleisiu ant šitos vietos ir ant jos gyventojų’“. Taigi jie parnešė karaliui žinią.'),
  (@b14, 34, 29, 'Tada karalius pasiuntęs surinko visus Judos ir Jeruzalės vyresniuosius.'),
  (@b14, 34, 30, 'Ir karalius nuėjo aukštyn į VIEŠPATIES namus, ir visi Judos žmonės, Jeruzalės gyventojai, kunigai, levitai, visa tauta, dideli ir maži; ir jis skaitė jiems į ausis visus žodžius sandoros knygos, atrastos VIEŠPATIES namuose.'),
  (@b14, 34, 31, 'Ir karalius, atsistojęs savo vietoje, sudarė sandorą VIEŠPATIES akivaizdoje, vaikščioti paskui VIEŠPATĮ ir laikytis jo įsakymų, jo liudijimų ir jo įstatų visa savo širdimi ir visa savo siela, kad vykdytų sandoros žodžius, užrašytus šitoje knygoje.'),
  (@b14, 34, 32, 'Ir jis padarė, kad visi, esantys Jeruzalėje ir Benjamine, į ją įstotų. Ir Jeruzalės gyventojai elgėsi pagal Dievo, jų tėvų Dievo, sandorą.'),
  (@b14, 34, 33, 'Ir Jozijas pašalino visas bjaurybes iš visų šalių, priklausančių Izraelio vaikams, ir padarė, kad visi, esantys Izraelyje, tarnautų VIEŠPAČIUI, jų Dievui. Ir per visas jo dienas jie nepasitraukė nuo sekimo paskui VIEŠPATĮ, savo tėvų Dievą.'),
  (@b14, 35, 1, 'Be to, Jozijas šventė Jeruzalėje Apėjimą VIEŠPAČIUI; ir jie papjovė Apėjimą pirmojo mėnesio keturioliktąją dieną.'),
  (@b14, 35, 2, 'Ir jis pastatė kunigus jų pareigose ir juos padrąsino VIEŠPATIES namų tarnavimui,'),
  (@b14, 35, 3, 'ir tarė levitams, kurie mokė visą Izraelį, kurie buvo šventi VIEŠPAČIUI: „Padėkite šventąją skrynią į namus, kuriuos pastatė Izraelio karaliaus Dovydo sūnus Saliamonas; ji nebus našta ant jūsų pečių; dabar tarnaukite VIEŠPAČIUI, savo Dievui, ir jo tautai Izraeliui,'),
  (@b14, 35, 4, 'ir pasiruoškite pagal savo tėvų namus, pagal savo skyrius, pagal Izraelio karaliaus Dovydo raštą ir pagal jo sūnaus Saliamono raštą.'),
  (@b14, 35, 5, 'Ir stovėkite šventojoje vietoje pagal savo tautos, savo brolių tėvų šeimų padalijimus ir pagal levitų šeimų padalijimą.'),
  (@b14, 35, 6, 'Taigi papjaukite Apėjimą, pasišvęskite ir paruoškite savo brolius, idant jie darytų pagal VIEŠPATIES žodį per Mozės ranką“.'),
  (@b14, 35, 7, 'Ir Jozijas davė tautai iš kaimenės avinėlių ir ožkiukų – visus Apėjimo atnašoms, visiems dalyvaujantiems, trisdešimties tūkstančių skaičiui, ir tris tūkstančius jaučių; šitie buvo iš karaliaus turto.'),
  (@b14, 35, 8, 'Ir jo kunigaikščiai laisva valia davė tautai, kunigams ir levitams: Hilkijas, Zacharijas ir Jehielis, Dievo namų valdovai, davė kunigams Apėjimo atnašoms du tūkstančius šešis šimtus mažų galvijų ir tris šimtus jaučių.'),
  (@b14, 35, 9, 'Taip pat Konanijas ir jo broliai Šemajas bei Netanelis, Hašabijas, Jejelis ir Jozabadas, levitų vyriausieji, davė levitams Apėjimo atnašoms penkis tūkstančius mažų galvijų ir penkis šimtus jaučių.'),
  (@b14, 35, 10, 'Taip tarnavimas buvo paruoštas, kunigai stovėjo savo vietose, o levitai savo skyriais, pagal karaliaus įsakymą.'),
  (@b14, 35, 11, 'Ir jie papjovė Apėjimą, ir kunigai šlakstė kraują iš jų rankų, o levitai juos lupo.'),
  (@b14, 35, 12, 'Ir jie pašalino deginamąsias atnašas, kad jie duotų pagal tautos šeimų padalijimus, kad atnašautų VIEŠPAČIUI, kaip parašyta Mozės knygoje. Ir taip jie padarė su jaučiais.'),
  (@b14, 35, 13, 'Ir jie kepė Apėjimą ugnimi pagal potvarkį; bet kitas šventas atnašas jie virė puoduose, katiluose ir kaistuvuose ir jas skubiai padalino visai tautai.'),
  (@b14, 35, 14, 'Po to jie paruošė sau ir kunigams; nes kunigai, Aarono sūnūs, buvo iki nakties užsiėmę deginamųjų atnašų ir taukų atnašavimu; todėl levitai paruošė sau ir Aarono sūnums kunigams.'),
  (@b14, 35, 15, 'O giesmininkai, Asafo sūnūs, buvo savo vietose pagal Dovydo, Asafo, Hemano ir Jedutūno, karaliaus regėtojo, įsakymą; o durininkai tarnavo prie kiekvienų vartų; jiems nereikėjo pasišalinti iš savo tarnavimo; nes jų broliai levitai jiems paruošė.'),
  (@b14, 35, 16, 'Taip tą pačią dieną buvo paruoštas visas VIEŠPATIES tarnavimas, kad būtų švenčiamas Apėjimas ir kad būtų atnašaujamos deginamosios atnašos ant VIEŠPATIES aukuro pagal karaliaus Jozijo įsakymą.'),
  (@b14, 35, 17, 'O dalyvaujantys Izraelio vaikai tuo laiku šventė Apėjimą ir Neraugintos duonos šventę septynias dienas.'),
  (@b14, 35, 18, 'Ir tokio Apėjimo nebuvo švęsta Izraelyje nuo pranašo Samuelio dienų; ir nei vienas Izraelio karalius nebuvo šventęs tokio Apėjimo, kokį šventė Jozijas, kunigai, levitai ir visas dalyvaujantis Juda bei Izraelis, ir Jeruzalės gyventojai.'),
  (@b14, 35, 19, 'Šis Apėjimas buvo švenčiamas aštuonioliktaisiais Jozijo karaliavimo metais.'),
  (@b14, 35, 20, 'Po viso to, kai Jozijas buvo paruošęs šventyklą, Egipto karalius Nechojas atėjo aukštyn kovoti prieš Karchemišą prie Eufrato; ir Jozijas išėjo prieš jį.'),
  (@b14, 35, 21, 'Bet jis siuntė pas jį pasiuntinius, sakydamas: „Kas man darbo su tavimi, Judos karaliau? Ne prieš tave aš šią dieną ateinu, bet prieš namus, su kuriais kariauju; nes Dievas įsakė man skubėti; susilaikyk nuo kišimosi į reikalus Dievo, kuris yra su manimi, kad jis tavęs nesunaikintų“.'),
  (@b14, 35, 22, 'Tačiau Jozijas nenukreipė savo veido nuo jo, bet persirengė, kad kariautų su juo, ir nepaklausė Necho žodžių iš Dievo burnos, ir atėjo kovoti į Megido slėnį.'),
  (@b14, 35, 23, 'Ir lankininkai šovė į karalių Joziją; ir karalius tarė savo tarnams: „Paimkite mane šalin; nes esu sunkiai sužeistas“.'),
  (@b14, 35, 24, 'Taigi jo tarnai, paėmę jį iš to vežimo, patalpino jį į antrąjį vežimą, kurį jis turėjo; ir jie nugabeno jį į Jeruzalę, ir jis mirė, ir buvo palaidotas viename iš savo tėvų kapų. Ir visa Juda ir Jeruzalė apraudojo Joziją.'),
  (@b14, 35, 25, 'Ir Jeremijas apraudojo Joziją; ir visi giesmininkai bei giesmininkės iki šios dienos kalba apie Joziją savo raudose, ir padarė jas Izraelyje potvarkiu; ir štai jos užrašytos raudose.'),
  (@b14, 35, 26, 'Na, o kiti Jozijo veiksmai ir jo gerumas pagal tai, kas buvo parašyta VIEŠPATIES įstatyme,'),
  (@b14, 35, 27, 'ir jo darbai, pirmi ir paskutiniai, štai jie surašyti Izraelio ir Judos karalių knygoje.'),
  (@b14, 36, 1, 'Tada šalies tauta paėmė Jozijo sūnų Jehoachazą ir jį padarė karaliumi jo tėvo vietoje Jeruzalėje.'),
  (@b14, 36, 2, 'Jehoachazas buvo dvidešimt trejų metų, kai pradėjo karaliauti, ir tris mėnesius karaliavo Jeruzalėje.'),
  (@b14, 36, 3, 'O Egipto karalius jį nušalino Jeruzalėje, ir pasmerkė šalį šimtu talentų sidabro ir talentu aukso.'),
  (@b14, 36, 4, 'Ir Egipto karalius padarė jo brolį Eliakimą Judos bei Jeruzalės karaliumi ir pakeitė jo vardą į Jehojakimą. O jo brolį Jehoachazą Nechojas paėmė ir jį nuvedė į Egiptą.'),
  (@b14, 36, 5, 'Jehojakimas buvo dvidešimt penkerių metų, kai pradėjo karaliauti, ir vienuolika metų karaliavo Jeruzalėje; ir jis darė tai, kas buvo pikta VIEŠPATIES, jo Dievo, akyse.'),
  (@b14, 36, 6, 'Prieš jį atėjo aukštyn Babilono karalius Nebukadnecaras ir jį sukaustė grandinėmis, kad nuvestų į Babiloną.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b14, 36, 7, 'Taip pat Nebukadnecaras nugabeno į Babiloną VIEŠPATIES namų indų ir juos padėjo savo šventykloje Babilone.'),
  (@b14, 36, 8, 'Na, o kiti Jehojakimo darbai ir jo bjaurystės, kurias jis darė ir kurios buvo jame rastos, štai jie užrašyti Izraelio ir Judos karalių knygoje; o jo sūnus Jehojakinas karaliavo jo vietoje.'),
  (@b14, 36, 9, 'Jehojakinas buvo aštuoniolikos metų, kai pradėjo karaliauti, ir tris mėnesius bei dešimt dienų karaliavo Jeruzalėje; ir jis darė tai, kas buvo pikta VIEŠPATIES akyse.'),
  (@b14, 36, 10, 'O metams pasibaigus, karalius Nebukadnecaras atsiuntė ir nugabeno jį į Babiloną su gražiais VIEŠPATIES namų indais, ir padarė jo brolį Zedekiją Judos ir Jeruzalės karaliumi.'),
  (@b14, 36, 11, 'Zedekijas buvo dvidešimt vienerių metų, kai pradėjo karaliauti, ir vienuolika metų karaliavo Jeruzalėje.'),
  (@b14, 36, 12, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES, jo Dievo, akyse, ir nenusižemino prieš pranašą Jeremiją, kalbantį iš VIEŠPATIES burnos.'),
  (@b14, 36, 13, 'Taip pat jis sukilo prieš karalių Nebukadnecarą, kuris jį buvo prisaikdinęs Dievu; bet jis užkietino savo sprandą ir užkietino savo širdį, neatsigręždamas į VIEŠPATĮ, Izraelio Dievą.'),
  (@b14, 36, 14, 'Be to, visi vyriausieji iš kunigų ir tauta labai nusižengė pagal visas pagonių bjaurystes; ir suteršė VIEŠPATIES namus, kuriuos jis buvo pašventęs Jeruzalėje.'),
  (@b14, 36, 15, 'Ir VIEŠPATS, jų tėvų Dievas, siuntė jiems per savo pasiuntinius, anksti keldamasis ir siųsdamas; nes jis gailėjosi savo tautos ir savo buveinės;'),
  (@b14, 36, 16, 'bet jie tyčiojosi iš Dievo pasiuntinių, niekino jo žodžius ir blogai elgėsi su jo pranašais, kol VIEŠPATIES rūstybė pakilo prieš jo tautą, kad buvo nebepagydoma.'),
  (@b14, 36, 17, 'Todėl jis atvedė ant jų kaldėjų karalių, kuris išžudė kalaviju jų jaunuolius jų šventovės namuose ir nepasigailėjo nei jaunuolio, nei mergaitės, nei seno, nei palinkusio dėl amžiaus – visus jis atidavė į jo rankas.'),
  (@b14, 36, 18, 'Ir visus Dievo namų indus, didelius ir mažus, VIEŠPATIES namų lobius ir karaliaus bei jo kunigaikščių lobius – visus tuos jis nugabeno į Babiloną.'),
  (@b14, 36, 19, 'Ir jie sudegino Dievo namus, sugriovė Jeruzalės sieną, sudegino visus jos rūmus ugnimi ir sunaikino visus jos gražius indus.'),
  (@b14, 36, 20, 'O išsigelbėjusius nuo kalavijo jis išvedė į Babiloną, kur jie buvo jo ir jo sūnų tarnai iki Persijos karalystės įsiviešpatavimo;'),
  (@b14, 36, 21, 'kad išpildytų VIEŠPATIES žodį per Jeremijo burną, kol šalis džiaugėsi savo sabatais; nes tol, kol ji apleista, ji laikėsi sabato, kad išpildytų septyniasdešimt metų.'),
  (@b14, 36, 22, 'Na, o pirmaisiais Persijos karaliaus Kyro metais, kad įvyktų VIEŠPATIES žodis, kalbėtas Jeremijo burna, VIEŠPATS sužadino Persų karaliaus Kyro dvasią, kad jis visoje savo karalystėje paskelbė ir taip pat užrašė raštu, sakydamas:'),
  (@b14, 36, 23, '„Taip sako Persijos karalius Kyras: ‘Visas žemės karalystes man davė VIEŠPATS, dangaus Dievas; ir jis mane įpareigojo pastatyti jam namus Jeruzalėje, kuri yra Judoje. Kas tarp jūsų yra iš visos jo tautos? VIEŠPATS, jo Dievas, tebūna su juo ir tegul jis eina aukštyn’“.'),
  (@b15, 1, 1, 'Na, o pirmaisiais Persijos karaliaus Kyro metais, kad išsipildytų VIEŠPATIES žodis per Jeremijo burną, VIEŠPATS sužadino Persijos karaliaus Kyro dvasią, kad jis visoje savo karalystėje paskelbė ir taip pat užrašė raštu, sakydamas:'),
  (@b15, 1, 2, '„Taip sako Persijos karalius Kyras: Visas žemės karalystes man davė VIEŠPATS, dangaus Dievas; ir jis mane įpareigojo pastatyti jam namus Jeruzalėje, kuri yra Judoje.'),
  (@b15, 1, 3, 'Kas tarp jūsų yra iš visos jo tautos? Jo Dievas tebūna su juo ir tegul jis eina aukštyn į Jeruzalę, esančią Judoje, ir tegul stato VIEŠPATIES, Izraelio Dievo, namus (jis yra Dievas), esančius Jeruzalėje.'),
  (@b15, 1, 4, 'Ir kas tik yra išlikęs kokioje nors vietoje, kur yra laikinai apsigyvenęs, tegul jo vietos žmonės padeda jam sidabru ir auksu, turtu ir gyvuliais, neskaitant laisvos valios atnašos Dievo namams, esantiems Jeruzalėje“.'),
  (@b15, 1, 5, 'Tada Judos ir Benjamino tėvų vyriausieji, kunigai ir levitai su visais tais, kurių dvasią Dievas buvo sužadinęs, pakilo, kad eitų aukštyn statyti VIEŠPATIES namų, esančių Jeruzalėje.'),
  (@b15, 1, 6, 'O visi, esantys aplink juos, sustiprino jų rankas sidabriniais indais, auksu, turtu, gyvuliais ir vertingais daiktais, neskaitant to, kas buvo savanoriškai paaukota.'),
  (@b15, 1, 7, 'Taip pat karalius Kyras išnešė VIEŠPATIES namų indus, kuriuos Nebukadnecaras buvo išgabenęs iš Jeruzalės ir juos padėjęs į savo dievų namus;'),
  (@b15, 1, 8, 'būtent šituos Persijos karalius Kyras išnešė per iždininko Mitredato ranką ir juos suskaičiavo Judos kunigaikščiui Šešbacarui.'),
  (@b15, 1, 9, 'O toks buvo jų skaičius: trisdešimt auksinių dubenų, tūkstantis sidabrinių dubenų, dvidešimt devyni peiliai,'),
  (@b15, 1, 10, 'trisdešimt auksinių taurių, keturi šimtai dešimt antrarūšių sidabrinių taurių ir tūkstantis kitų indų.'),
  (@b15, 1, 11, 'Iš viso auksinių ir sidabrinių indų buvo penki tūkstančiai keturi šimtai. Visus šituos Šešbacaras gabeno aukštyn su belaisviais, kurie buvo vedami aukštyn iš Babilono į Jeruzalę.'),
  (@b15, 2, 1, 'Na, o šitie yra provincijos vaikai, kurie ėjo aukštyn iš nelaisvės, iš tų, kurie buvo išvesti, kuriuos Babilono karalius Nebukadnecaras buvo išvedęs į Babiloną, kurie sugrįžo į Jeruzalę ir Judą, kiekvienas į savo miestą;'),
  (@b15, 2, 2, 'kurie parvyko su Zerubabeliu, Jėzue, Nehemiju, Seraja, Reelaja, Mordekajumi, Bilšanu, Misparu, Bigvajumi, Rehumu, Baana. Izraelio tautos žmonių skaičius:'),
  (@b15, 2, 3, 'Parošo vaikų: du tūkstančiai šimtas septyniasdešimt du;'),
  (@b15, 2, 4, 'Šefatijos vaikų: trys šimtai septyniasdešimt du;'),
  (@b15, 2, 5, 'Aracho vaikų: septyni šimtai septyniasdešimt penki;'),
  (@b15, 2, 6, 'Pahat-Moabo vaikų iš Jėzuės ir Joabo vaikų: du tūkstančiai aštuoni šimtai dvylika;'),
  (@b15, 2, 7, 'Elamo vaikų: tūkstantis du šimtai penkiasdešimt keturi;'),
  (@b15, 2, 8, 'Zatuvo vaikų: devyni šimtai keturiasdešimt penki;'),
  (@b15, 2, 9, 'Zakajo vaikų: septyni šimtai šešiasdešimt;'),
  (@b15, 2, 10, 'Banio vaikų: šeši šimtai keturiasdešimt du;'),
  (@b15, 2, 11, 'Bebajo vaikų: šeši šimtai dvidešimt trys;'),
  (@b15, 2, 12, 'Azgado vaikų: tūkstantis du šimtai dvidešimt du;'),
  (@b15, 2, 13, 'Adonikamo vaikų: šeši šimtai šešiasdešimt šeši;'),
  (@b15, 2, 14, 'Bigvajo vaikų: du tūkstančiai penkiasdešimt šeši;'),
  (@b15, 2, 15, 'Adino vaikų: keturi šimtai penkiasdešimt keturi;'),
  (@b15, 2, 16, 'Atero vaikų iš Chezekijo: devyniasdešimt aštuoni;'),
  (@b15, 2, 17, 'Becajo vaikų: trys šimtai dvidešimt trys;'),
  (@b15, 2, 18, 'Joros vaikų: šimtas dvylika;'),
  (@b15, 2, 19, 'Hašumo vaikų: du šimtai dvidešimt trys;'),
  (@b15, 2, 20, 'Gibaro vaikų: devyniasdešimt penki;'),
  (@b15, 2, 21, 'Betliejaus vaikų: šimtas dvidešimt trys;'),
  (@b15, 2, 22, 'Netofos žmonių: penkiasdešimt šeši;'),
  (@b15, 2, 23, 'Anatoto žmonių: šimtas dvidešimt aštuoni;'),
  (@b15, 2, 24, 'Azmaveto vaikų: keturiasdešimt du;'),
  (@b15, 2, 25, 'Kirjat-Arimo, Kefyros ir Beeroto vaikų: septyni šimtai keturiasdešimt trys;'),
  (@b15, 2, 26, 'Ramos ir Gabos vaikų: šeši šimtai dvidešimt vienas;'),
  (@b15, 2, 27, 'Michmaso žmonių: šimtas dvidešimt du;'),
  (@b15, 2, 28, 'Bet-Elio ir Ajo žmonių: du šimtai dvidešimt trys;'),
  (@b15, 2, 29, 'Nebo vaikų: penkiasdešimt du;'),
  (@b15, 2, 30, 'Magbišo vaikų: šimtas penkiasdešimt šeši;'),
  (@b15, 2, 31, 'kito Elamo vaikų: tūkstantis du šimtai penkiasdešimt keturi;'),
  (@b15, 2, 32, 'Harimo vaikų: trys šimtai dvidešimt;'),
  (@b15, 2, 33, 'Lodo, Hadido ir Onojo vaikų: septyni šimtai dvidešimt penki;'),
  (@b15, 2, 34, 'Jericho vaikų: trys šimtai keturiasdešimt penki;'),
  (@b15, 2, 35, 'Senavos vaikų: trys tūkstančiai šeši šimtai trisdešimt;'),
  (@b15, 2, 36, 'kunigų: Jedajos vaikų iš Jėzuės namų: devyni šimtai septyniasdešimt trys,'),
  (@b15, 2, 37, 'Imero vaikų: tūkstantis penkiasdešimt du,'),
  (@b15, 2, 38, 'Pašchūro vaikų: tūkstantis du šimtai keturiasdešimt septyni,'),
  (@b15, 2, 39, 'Harimo vaikų: tūkstantis septyniolika.'),
  (@b15, 2, 40, 'Levitų: Jėzuės ir Kadmielio vaikų iš Hodavijos vaikų: septyniasdešimt keturi.'),
  (@b15, 2, 41, 'Giesmininkų: Asafo vaikų: šimtas dvidešimt aštuoni.'),
  (@b15, 2, 42, 'Durininkų vaikai: Šalumo vaikai, Atero vaikai, Talmono vaikai, Akubo vaikai, Hatitos vaikai, Šobajo vaikai – iš viso šimtas trisdešimt devyni.'),
  (@b15, 2, 43, 'Netinimai: Cihos vaikai, Hasufos vaikai, Tabaoto vaikai,'),
  (@b15, 2, 44, 'Keroso vaikai, Siahos vaikai, Padono vaikai,'),
  (@b15, 2, 45, 'Lebanos vaikai, Hagabos vaikai, Akubo vaikai,'),
  (@b15, 2, 46, 'Hagabo vaikai, Šalmajo vaikai, Hanano vaikai,'),
  (@b15, 2, 47, 'Gidelio vaikai, Gaharo vaikai, Reajos vaikai,'),
  (@b15, 2, 48, 'Recino vaikai, Nekodos vaikai, Gazamo vaikai,'),
  (@b15, 2, 49, 'Uzos vaikai, Paseaho vaikai, Besajo vaikai,'),
  (@b15, 2, 50, 'Asnos vaikai, mehunų vaikai, nefusų vaikai,'),
  (@b15, 2, 51, 'Bakbuko vaikai, Hakufos vaikai, Harhūro vaikai,'),
  (@b15, 2, 52, 'Bacluto vaikai, Mehidos vaikai, Haršos vaikai,'),
  (@b15, 2, 53, 'Barkoso vaikai, Siseros vaikai, Tamaho vaikai,'),
  (@b15, 2, 54, 'Neciacho vaikai, Hatifos vaikai.'),
  (@b15, 2, 55, 'Saliamono tarnų vaikai: Sotajo vaikai, Sofereto vaikai, Perudos vaikai,'),
  (@b15, 2, 56, 'Jaalos vaikai, Darkono vaikai, Gidelio vaikai,'),
  (@b15, 2, 57, 'Šefatijos vaikai, Hatilo vaikai, Pochereto iš Cebaimo vaikai, Amio vaikai.'),
  (@b15, 2, 58, 'Iš viso netinimų ir Saliamono tarnų vaikų buvo trys šimtai devyniasdešimt du.'),
  (@b15, 2, 59, 'O šitie buvo tie, kurie ėjo aukštyn iš Tel-Melaho, Tel-Harsos, Kerubo, Adano ir Imero, bet negalėjo parodyti savo tėvo namų ir savo sėklos, ar jie yra iš Izraelio:'),
  (@b15, 2, 60, 'Delajos vaikai, Tobijos vaikai, Nekodos vaikai – šeši šimtai penkiasdešimt du.'),
  (@b15, 2, 61, 'O iš kunigų vaikų: Habajo vaikai, Koco vaikai, vaikai Barzilajaus, kuris ėmė žmoną iš gileadiečio Barzilajaus dukterų ir buvo vadinamas jų vardu;'),
  (@b15, 2, 62, 'šitie ieškojo savo sąrašo tarp suskaičiuotųjų pagal genealogiją, bet jie nebuvo rasti; todėl jie buvo atskirti nuo kunigystės kaip susiteršę.'),
  (@b15, 2, 63, 'Ir Tiršata jiems pasakė, kad jie nevalgytų iš švenčiausių dalykų, kol pakils kunigas su Urimu ir Tumimu.'),
  (@b15, 2, 64, 'Visas susirinkimas bendrai buvo keturiasdešimt du tūkstančiai trys šimtai šešiasdešimt,'),
  (@b15, 2, 65, 'neskaitant jų tarnų ir jų tarnaičių, kurių buvo septyni tūkstančiai trys šimtai trisdešimt septyni; ir tarp jų buvo du šimtai giesmininkų ir giesmininkių.'),
  (@b15, 2, 66, 'Jų žirgų buvo septyni šimtai trisdešimt šeši; jų mulų – du šimtai keturiasdešimt penki;'),
  (@b15, 2, 67, 'jų kupranugarių – keturi šimtai trisdešimt penki; jų asilų – šeši tūkstančiai septyni šimtai dvidešimt.'),
  (@b15, 2, 68, 'O kai kurie iš tėvų vyriausiųjų, atėję į VIEŠPATIES namus, esančius Jeruzalėje, noriai atnašavo Dievo namams, kad juos pastatytų jų vietoje;'),
  (@b15, 2, 69, 'pagal savo pajėgumą jie davė darbo iždui šešiasdešimt vieną tūkstantį drachmų aukso, penkis tūkstančius svarų sidabro ir šimtą kunigų apdarų.'),
  (@b15, 2, 70, 'Taigi kunigai, levitai ir kai kurie iš tautos, giesmininkai, durininkai bei netinimai apsigyveno savo miestuose ir visas Izraelis savo miestuose.'),
  (@b15, 3, 1, 'O kai atėjo septintasis mėnuo, ir Izraelio vaikai buvo miestuose, tauta susirinko kaip vienas žmogus į Jeruzalę.'),
  (@b15, 3, 2, 'Tada pakilo Jocadako sūnus Jėzuė, jo broliai kunigai, Šaltielio sūnus Zerubabelis ir jo broliai, ir pastatė Izraelio Dievo aukurą, kad atnašautų ant jo deginamąsias atnašas, kaip parašyta Dievo vyro Mozės įstatyme.'),
  (@b15, 3, 3, 'Jie pastatė aukurą ant jo atramų; nes baimė buvo ant jų dėl tų šalių tautų; ir jie ant jo atnašavo deginamąsias atnašas VIEŠPAČIUI būtent ryto ir vakaro deginamąsias atnašas.'),
  (@b15, 3, 4, 'Taip pat jie šventė Padangčių šventę, kaip yra parašyta, ir atnašavo kasdienes deginamąsias atnašas skaičiumi pagal paprotį, kaip reikalavo kiekvienos dienos pareiga;'),
  (@b15, 3, 5, 'o paskui atnašavo nuolatinę deginamąją atnašą jauno mėnulio ir visų paskirtų VIEŠPATIES švenčių, kurios buvo pašvęstos, ir visų noriai atnašavusių VIEŠPAČIUI savanorišką atnašą.'),
  (@b15, 3, 6, 'Nuo septintojo mėnesio pirmosios dienos jie pradėjo atnašauti VIEŠPAČIUI deginamąsias atnašas. Bet VIEŠPATIES šventyklos pamatas dar nebuvo padėtas.'),
  (@b15, 3, 7, 'Jie taip pat davė pinigų mūrininkams ir dailidėms; ir maisto, gėrimo ir aliejaus tiems iš Sidono ir tiems iš Tyro, kad atgabentų kedro medžių iš Libano į Jopės jūrą pagal leidimą, kurį jie turėjo iš Persijos karaliaus Kyro.'),
  (@b15, 3, 8, 'Na, o antraisiais jų atvykimo į Dievo namus Jeruzalėje metais, antrąjį mėnesį, pradėjo Šaltielio sūnus Zerubabelis, Jocadako sūnus Jėzuė ir likusieji iš jų brolių kunigų bei levitų, ir visi, atėję iš nelaisvės į Jeruzalę; ir paskyrė levitus, nuo dvidešimties metų ir vyresnius, pastūmėti į priekį VIEŠPATIES namų darbą.'),
  (@b15, 3, 9, 'Tada Jėzuė su savo sūnumis ir savo broliais, Kadmielis ir jo sūnūs, Judos sūnūs, stojo kartu, kad pastūmėtų į priekį dirbančius Dievo namuose; Henadado sūnūs su jų sūnumis ir jų broliai levitai.'),
  (@b15, 3, 10, 'Ir statybininkams padėjus VIEŠPATIES šventyklos pamatą, pastatė kunigus, apsirengusius savo drabužiais, su trimitais, ir Asafo sūnus levitus su cimbolais, kad girtų VIEŠPATĮ pagal Izraelio karaliaus Dovydo potvarkį.'),
  (@b15, 3, 11, 'Ir jie giedojo kartu paeiliui, girdami ir dėkodami VIEŠPAČIUI; nes jis yra geras, nes jo gailestingumas Izraeliui išlieka per amžius. Ir visa tauta šaukė dideliu šauksmu, girdami VIEŠPATĮ, kadangi buvo padėtas VIEŠPATIES namų pamatas.'),
  (@b15, 3, 12, 'Bet daugelis iš kunigų, levitų ir tėvų vyriausiųjų, kurie buvo sentėviai ir buvo matę pirmuosius namus, kai prieš jų akis buvo padėtas šitų namų pamatas, verkė garsiu balsu; o daugelis garsiai šūkavo iš džiaugsmo;'),
  (@b15, 3, 13, 'taip, kad tauta negalėjo atskirti džiaugsmo šūkavimo nuo tautos verksmo garso; nes tauta šaukė garsiu šauksmu, ir tas garsas buvo girdimas iš toli.'),
  (@b15, 4, 1, 'Na, o Judos ir Benjamino priešininkai, išgirdę, kad nelaisvės vaikai stato šventyklą VIEŠPAČIUI, Izraelio Dievui,'),
  (@b15, 4, 2, 'atėjo pas Zerubabelį ir pas tėvų vyriausiuosius ir jiems tarė: „Statykime drauge su jumis; nes mes ieškome jūsų Dievo kaip ir jūs; ir jam mes aukojame nuo dienų Esar-Hadono, Ašūro karaliaus, kuris mus čia atgabeno“.'),
  (@b15, 4, 3, 'Bet Zerubabelis, Jėzuė ir kiti iš Izraelio tėvų vyriausiųjų jiems tarė: „Jūs neturite nieko bendra su mumis, kad statytumėte mūsų Dievui namus; bet mes patys drauge statysime VIEŠPAČIUI, Izraelio Dievui, kaip mums įsakė karalius Kyras, Persijos karalius“.'),
  (@b15, 4, 4, 'Tada tos šalies tauta silpnino Judos tautos rankas ir trukdė jiems statyti;'),
  (@b15, 4, 5, 'ir pasamdė prieš juos patarėjus, kad niekais paverstų jų tikslą, per visas Persijos karaliaus Kyro dienas, iki Persijos karaliaus Darijaus karaliavimo.'),
  (@b15, 4, 6, 'O karaliaujant Ahasverui, jo karaliavimo pradžioje, jie jam parašė kaltinimą prieš Judos ir Jeruzalės gyventojus.'),
  (@b15, 4, 7, 'Ir Artakserkso dienomis Bišlamas, Mitredatas, Tabeelis ir kiti jų draugai parašė Persijos karaliui Artakserksui; o laiško raštas buvo parašytas sirų kalba, išverstas į sirų kalbą.'),
  (@b15, 4, 8, 'Kancleris Rehumas ir raštininkas Šimšajas parašė karaliui Artakserksui tokį laišką prieš Jeruzalę:'),
  (@b15, 4, 9, 'tad parašė kancleris Rehumas, raštininkas Šimšajas ir kiti jų draugai; dinajai, afarsatai, tarpelitai, afarsitai, arkai, babiloniečiai, sūsaniečiai, dehavai, elamiečiai'),
  (@b15, 4, 10, 'ir kitos tautos, kurias didysis ir kilmingasis Asnaparas atvedė ir įkūrė Samarijos miestuose, ir kiti, esantys šiapus upės ir tokiu tai laiku.'),
  (@b15, 4, 11, 'Tai kopija laiško, kurį jie jam nusiuntė, būtent karaliui Artakserksui: „Tavo tarnai, žmonės šiapus upės ir tokiu tai laiku.'),
  (@b15, 4, 12, 'Tebūna žinoma karaliui, kad žydai, atėję aukštyn nuo tavęs pas mus, atėję į Jeruzalę, stato tą maištingą ir blogą miestą, yra pastatę jo sienas ir sujungę pamatus.'),
  (@b15, 4, 13, 'Tebūna dabar žinoma karaliui, kad, jei tas miestas bus pastatytas ir tos sienos atstatytos, tuomet jie nemokės mokesčio, duoklės ir muito, ir taip tu atneši nuostolį karalių pajamoms.'),
  (@b15, 4, 14, 'Na, o kadangi mes išlaikomi karaliaus rūmų ir mums nepridera matyti karaliaus garbės apiplėšimo, todėl nusiuntėme ir patvirtinome karaliui;'),
  (@b15, 4, 15, 'kad atliktų paiešką tavo tėvų metraščių knygoje; taip tu rasi metraščių knygoje ir sužinosi, kad tas miestas yra maištingas miestas ir žalingas karaliams bei provincijoms ir kad nuo senovės jame kurstydavo maištą; dėl to tas miestas buvo sunaikintas.'),
  (@b15, 4, 16, 'Mes tvirtiname karaliui, kad, jei tas miestas bus atstatytas ir jo sienos pastatytos, tai dėl to neturėsi dalies šioje upės pusėje“.'),
  (@b15, 4, 17, 'Tada karalius nusiuntė atsakymą kancleriui Rehumui, raštininkui Šimšajui ir kitiems iš jų draugų, gyvenančių Samarijoje, ir kitiems anapus upės: „Ramybė ir tokiu tai laiku.'),
  (@b15, 4, 19, 'Ir man įsakius, buvo atlikta paieška ir rasta, kad šitas miestas nuo senovės sukildavo prieš karalius ir kad jame sukildavo ir būdavo kurstomas maištas.'),
  (@b15, 4, 20, 'Taip pat galingi karaliai viešpatavo Jeruzalei, kurie valdė visas šalis anapus upės; ir jiems buvo mokami mokesčiai, duoklė ir muitas.'),
  (@b15, 4, 21, 'Duokite dabar įsakymą, kad šitie žmonės būtų sustabdyti, ir kad tas miestas nebūtų statomas, kol bus duotas kitas mano įsakymas.'),
  (@b15, 4, 22, 'Žiūrėkite gi, kad neapleistumėte tai padaryti; kodėl turėtų padidėti žala karaliams pakenkti?“'),
  (@b15, 4, 23, 'Na, o kai karaliaus Artakserkso laiško kopija buvo perskaityta Rehumo, raštininko Šimšajo ir jų draugų akivaizdoje, jie skubiai nuėjo aukštyn į Jeruzalę pas žydus ir juos sustabdė prievarta bei jėga.'),
  (@b15, 4, 24, 'Tuomet sustojo Jeruzalėje esančių Dievo namų darbas. Taip jis sustojo iki antrųjų Persijos karaliaus Darijaus karaliavimo metų.'),
  (@b15, 4, 18, 'Laiškas, kurį mums atsiuntėte, buvo aiškiai perskaitytas mano akivaizdoje.'),
  (@b15, 5, 1, 'Tada pranašai, pranašas Agėjas ir Idojo sūnus Zacharija, pranašavo žydams, esantiems Judoje ir Jeruzalėje, būtent jiems, Izraelio Dievo vardu.'),
  (@b15, 5, 2, 'Tada pakilo Šaltielio sūnus Zerubabelis ir Jocadako sūnus Jėzuė ir pradėjo statyti Dievo namus, esančius Jeruzalėje; ir su jais buvo Dievo pranašai, jiems padėdami.'),
  (@b15, 5, 3, 'Tuo pačiu laiku pas juos atvyko Tatnajas, valdytojas šioje upės pusėje, ir Šetar-Boznajas, ir jų draugai, ir taip jiems tarė: „Kas jums įsakė statyti šituos namus ir taisyti šitą sieną?“'),
  (@b15, 5, 4, 'Tada mes taip jiems tarėme: „Kokie vardai vyrų, statančių šitą pastatą?“'),
  (@b15, 5, 5, 'Bet jų Dievo akis buvo ant žydų vyresniųjų, kad jie jų nesustabdytų, kol reikalas pasieks Darijų; ir paskui jie davė atsakymą laišku apie šitą reikalą.'),
  (@b15, 5, 6, 'Kopija laiško, kurį Tatnajas, valdytojas šioje upės pusėje, ir Šetar-Boznajas, ir jo draugai afarsakai, esantys šioje upės pusėje, nusiuntė karaliui Darijui.'),
  (@b15, 5, 7, 'Jie siuntė jam laišką, kuriame buvo taip parašyta: „Karaliui Darijui visokia ramybė!'),
  (@b15, 5, 8, 'Tebūna karaliui žinoma, kad mes nuvykome į Judėjos provinciją, prie didžiojo Dievo namų, kurie statomi iš didelių akmenų, ir rąstai dedami į sienas, ir šitas darbas greitai einasi, ir klesti jų rankose.'),
  (@b15, 5, 9, 'Tada klausėme tų vyresniųjų ir taip jiems sakėme: ‘Kas jums įsakė statyti šituos namus ir pataisyti šitas sienas?’'),
  (@b15, 5, 10, 'Taip pat klausėme jų vardų, kad tau patvirtintume, kad galėtume užrašyti vardus vyrų, kurie yra jų vyriausieji.'),
  (@b15, 5, 11, 'Ir taip jie mums davė atsakymą, sakydami: ‘Mes esame dangaus ir žemės Dievo tarnai ir statome namus, kurie prieš šituos daugelį metų buvo pastatyti, kuriuos pastatė ir įrengė didis Izraelio karalius.'),
  (@b15, 5, 12, 'Bet kai mūsų tėvai kurstė dangaus Dievo rūstybę, jis juos padavė į kaldėjo Nebukadnecaro, Babilono karaliaus, ranką, kuris sunaikino šituos namus, o tautą išvedė į Babiloną.'),
  (@b15, 5, 13, 'Bet pirmaisiais Babilono karaliaus Kyro metais tas pats karalius Kyras išleido įsaką pastatyti šituos Dievo namus.'),
  (@b15, 5, 14, 'Taip pat auksinius ir sidabrinius Dievo namų indus, kuriuos Nebukadnecaras buvo paėmęs iš Jeruzalėje esančios šventyklos ir juos nugabenęs į Babilono šventyklą, šituos karalius Kyras išėmė iš Babilono šventyklos, ir jie buvo perduoti vienam, vardu Šešbacaras, kurį jis paskyrė valdytoju;'),
  (@b15, 5, 15, 'ir jam pasakė: Paimk šituos indus, eik ir juos nugabenk į Jeruzalėje esančią šventyklą, ir tebūna statomi Dievo namai jų vietoje’.'),
  (@b15, 5, 16, 'Paskui tas pats Šešbacaras atvykęs padėjo pamatą Dievo namų, esančių Jeruzalėje; ir nuo to laiko iki šiol jie tebestatomi ir dar nebaigti.'),
  (@b15, 5, 17, 'Taigi dabar, jei karaliui atrodytų gerai, tebūna atlikta paieška karaliaus lobių namuose, esančiuose ten Babilone, ar taip yra, kad buvo išleistas karaliaus Kyro įsakas statyti tuos Dievo namus Jeruzalėje, ir tegul karalius mums atsiunčia savo valią dėl šio reikalo“.'),
  (@b15, 6, 1, 'Tada karalius Darijus davė įsaką ir buvo atlikta paieška ritinių namuose, kur būdavo sudedami lobiai Babilone.'),
  (@b15, 6, 2, 'Ir Akmetoje, medų provincijoje esančiuose rūmuose, buvo rastas ritinys, o jame buvo taip užrašytas įrašas:'),
  (@b15, 6, 3, '„Pirmaisiais karaliaus Kyro metais tas pats karalius Kyras išleido įsaką dėl Dievo namų Jeruzalėje: ‘Tebūna statomi namai, ta vieta, kur atnašaudavo aukas, ir tebūna tvirtai padėti jų pamatai; jų aukštis šešiasdešimt uolekčių, o jų plotis šešiasdešimt uolekčių;'),
  (@b15, 6, 4, 'trimis eilėmis didelių akmenų ir eile naujų rąstų; o išlaidoms apmokėti tebūna duodama iš karaliaus namų;'),
  (@b15, 6, 5, 'taip pat auksiniai ir sidabriniai Dievo namų indai, kuriuos Nebukadnecaras išėmė iš Jeruzalėje esančios šventyklos ir nugabeno į Babiloną, tebūna sugrąžinti ir pargabenti į Jeruzalėje esančią šventyklą, kiekvienas į savo vietą, ir tebūna padėti Dievo namuose’“.'),
  (@b15, 6, 6, '„Taigi dabar, Tatnajau, valdytojau anapus upės, Šetar-Boznajau ir jūsų draugai afarsakai, esantys anapus upės, laikykitės atokiai nuo tenai;'),
  (@b15, 6, 7, 'palikite tų Dievo namų darbą ramybėje; tegul žydų valdytojas ir žydų vyresnieji stato tuos Dievo namus jų vietoje.'),
  (@b15, 6, 8, 'Be to, aš išleidžiu įsaką, ką jūs turite daryti šitų žydų vyresniesiems dėl tų Dievo namų statymo: Kad iš karaliaus turto, būtent iš duoklės anapus upės, nedelsiant būtų apmokėtos tų vyrų išlaidos, kad jiems nebūtų trukdoma.'),
  (@b15, 6, 9, 'Ir ko jiems reikia: jauniklių jaučių, avinų ir avinėlių dangaus Dievo deginamosioms atnašoms, kviečių, druskos, vyno ir aliejaus, kaip nurodys Jeruzalėje esantys kunigai, jiems tebūna tai duodama kasdien, neapleidžiant;'),
  (@b15, 6, 10, 'kad jie atnašautų gardaus kvapo aukas dangaus Dievui ir melstųsi už karaliaus bei jo sūnų gyvybę.'),
  (@b15, 6, 11, 'Taip pat išleidau įsaką, kad kiekvienam, kuris pakeis šitą žodį, tebus ištrauktas rąstas iš jo namų ir pastatytas, o jis tebus pakartas ant jo; o jo namai dėl to tebus paversti mėšlo krūva.'),
  (@b15, 6, 12, 'O Dievas, kuris padarė, kad ten gyventų jo vardas, tesunaikina visus karalius ir tautas, kurie imtų į savo rankas pakeisti ir sunaikinti tuos Dievo namus, esančius Jeruzalėje. Aš, Darijus, išleidau įsaką; tebūna tai skubiai vykdoma“.'),
  (@b15, 6, 13, 'Tada Tatnajas, valdytojas šiapus upės, Šetar-Boznajas ir jų draugai skubiai vykdė pagal tai, ką karalius Darijus atsiuntė.'),
  (@b15, 6, 14, 'Ir žydų vyresnieji statė, ir jiems sekėsi per pranašo Agėjo ir Idojo sūnaus Zacharijos pranašavimą. Ir jie pastatė ir juos užbaigė pagal Izraelio Dievo įsakymą ir pagal Kyro, Darijaus ir Persijos karaliaus Artakserkso įsakymą.'),
  (@b15, 6, 15, 'Ir šitie namai buvo užbaigti Adaro mėnesio trečiąją dieną, tai buvo šeštaisiais karaliaus Darijaus karaliavimo metais.'),
  (@b15, 6, 16, 'Ir Izraelio vaikai, kunigai, levitai ir kiti nelaisvės vaikai su džiaugsmu įvykdė šitų Dievo namų pašventimą,'),
  (@b15, 6, 17, 'ir, pašvęsdami šituos Dievo namus, paaukojo šimtą jaučių, du šimtus avinų ir keturis šimtus avinėlių; o nuodėmės atnašai už visą Izraelį – dvylika ožių, pagal Izraelio genčių skaičių.'),
  (@b15, 6, 18, 'Ir jie pastatė kunigus pagal jų padalijimus, o levitus pagal jų skyrius Jeruzalėje esančio Dievo tarnavimui; kaip yra parašyta Mozės knygoje.'),
  (@b15, 6, 19, 'Ir pirmojo mėnesio keturioliktąją dieną nelaisvės vaikai šventė Apėjimą.'),
  (@b15, 6, 20, 'Nes kunigai ir levitai buvo kartu apsivalę, jie visi buvo tyri, ir papjovė Apėjimą visiems nelaisvės vaikams ir savo broliams kunigams, ir sau patiems.'),
  (@b15, 6, 21, 'Ir valgė Izraelio vaikai, sugrįžę iš nelaisvės, ir visi, kurie buvo save atskyrę jiems nuo šalies pagonių nešvarumų, kad ieškotų VIEŠPATIES, Izraelio Dievo,'),
  (@b15, 6, 22, 'ir septynias dienas su džiaugsmu šventė Neraugintos duonos šventę; nes VIEŠPATS padarė juos džiaugsmingais ir pakreipė į juos Asirijos karaliaus širdį, kad sustiprintų jų rankas Dievo, Izraelio Dievo, namų darbe.'),
  (@b15, 7, 1, 'Na, o po šitų dalykų, Persijos karaliui Artakserksui karaliaujant, Ezra – sūnus Serajos, sūnus Azarijos, sūnus Hilkijos,'),
  (@b15, 7, 2, 'sūnus Šalumo, sūnus Cadoko, sūnus Ahitubo,'),
  (@b15, 7, 3, 'sūnus Amarijos, sūnus Azarijos, sūnus Merajoto,'),
  (@b15, 7, 4, 'sūnus Zerachijos, sūnus Uzio, sūnus Bukio,'),
  (@b15, 7, 5, 'sūnus Abišūvos, sūnus Finehaso, sūnus Eleazaro, sūnus vyriausiojo kunigo Aarono, –'),
  (@b15, 7, 6, 'šitas Ezra ėjo aukštyn iš Babilono; jis buvo raštininkas, pasiruošęs Mozės įstatyme, kurį buvo davęs VIEŠPATS, Izraelio Dievas; ir karalius suteikė jam viską, ko jis prašė, pagal VIEŠPATIES, jo Dievo, ranką ant jo.'),
  (@b15, 7, 7, 'Ir septintaisiais karaliaus Artakserkso metais ėjo aukštyn į Jeruzalę kai kurie iš Izraelio vaikų, iš kunigų, levitų, giesmininkų, durininkų ir netinimų.'),
  (@b15, 7, 8, 'Ir jis atvyko į Jeruzalę penktąjį mėnesį, esantį septintaisiais karaliaus metais.'),
  (@b15, 7, 9, 'Nes pirmojo mėnesio pirmąją dieną jis pradėjo eiti aukštyn iš Babilono, o penktojo mėnesio pirmąją dieną jis atvyko į Jeruzalę, pagal jo Dievo gerą ranką ant jo.'),
  (@b15, 7, 10, 'Nes Ezra buvo paruošęs savo širdį ieškoti VIEŠPATIES įstatymo, jį vykdyti ir mokyti Izraelyje įstatų bei teismų.'),
  (@b15, 7, 11, 'Na, o šita yra kopija laiško, kurį karalius Artakserksas davė kunigui Ezrai – raštininkui, būtent VIEŠPATIES įsakymų ir jo įstatų Izraeliui žodžių raštininkui:'),
  (@b15, 7, 12, '„Artakserksas, karalių karalius, kunigui Ezrai, dangaus Dievo įstatymo raštininkui, visiška ramybė ir tokiu tai laiku.'),
  (@b15, 7, 13, 'Aš išleidžiu įsaką, kad visi iš Izraelio tautos ir iš jo kunigų bei levitų mano karalystėje, kurie savo laisva valia nusiteikę eiti aukštyn į Jeruzalę, teeina su tavimi.'),
  (@b15, 7, 14, 'Kadangi tu esi karaliaus ir jo septynių patarėjų siunčiamas pasiklausti dėl Judos bei Jeruzalės pagal tavo Dievo įstatymą, esantį tavo rankoje;'),
  (@b15, 7, 15, 'ir pergabenti sidabrą bei auksą, kurį karalius ir jo patarėjai noriai paaukojo Izraelio Dievui, kurio buveinė yra Jeruzalėje,'),
  (@b15, 7, 16, 'ir visą sidabrą ir auksą, kurį gali rasti visoje Babilono provincijoje, su laisvos valios atnaša tautos ir kunigų, noriai atnašaujančių savo Dievo namams, esantiems Jeruzalėje;'),
  (@b15, 7, 17, 'kad už šituos pinigus skubiai nupirktum jaučių, avinų, avinėlių su jų maisto atnašomis ir jų geriamosiomis atnašomis ir juos atnašautum ant aukuro jūsų Dievo namų, esančių Jeruzalėje.'),
  (@b15, 7, 18, 'O kas tau ir tavo broliams atrodys gerai daryti su likusiuoju sidabru bei auksu, darykite tai pagal jūsų Dievo valią.'),
  (@b15, 7, 19, 'Taip pat indus, kurie tau duodami tavo Dievo namų tarnavimui, pristatyk Jeruzalės Dievo akivaizdon.'),
  (@b15, 7, 20, 'O kas daugiau būtų reikalinga tavo Dievo namams, ką tau pasitaikytų proga duoti, duok tai iš karaliaus lobių namų.'),
  (@b15, 7, 21, 'Ir aš, būtent karalius Artakserksas, išleidžiu įsaką visiems iždininkams, esantiems anapus upės, kad, ko tik kunigas Ezra, dangaus Dievo įstatymo raštininkas, iš jūsų reikalaus, tai turės būti skubiai padaryta,'),
  (@b15, 7, 22, 'iki šimto talentų sidabro, iki šimto saikų kviečių, iki šimto batų vyno ir iki šimto batų aliejaus, o druskos nenurodytas kiekis.'),
  (@b15, 7, 23, 'Kas tik bus įsakyta dangaus Dievo, tebūna tai uoliai daroma dangaus Dievo namams; nes kodėl gi turėtų būti rūstybė prieš karaliaus ir jo sūnų karalystę?'),
  (@b15, 7, 24, 'Taip pat mes jums tvirtiname, kad neteisėta apdėti mokesčiais, duokle ar muitu nei vieno iš kunigų, levitų, giesmininkų, durininkų, netinimų ar šitų Dievo namų tarnų.'),
  (@b15, 7, 25, 'O tu, Ezra, pagal savo Dievo išmintį, esančią tavo rankoje, pastatyk teismo pareigūnus ir teisėjus, kurie teistų visą tautą, esančią anapus upės, visus, pažįstančius tavo Dievo įstatymus; ir mokykite tuos, kurie jų nepažįsta.'),
  (@b15, 7, 26, 'O kas nevykdys tavo Dievo įstatymo ir karaliaus įstatymo, tegul tam bus skubiai įvykdytas teismas ar tai mirtimi, ar ištrėmimu, ar turto konfiskavimu, ar įkalinimu“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b15, 7, 27, 'Tebūna palaimintas VIEŠPATS, mūsų tėvų Dievas, kuris įdėjo tokį dalyką kaip šis į karaliaus širdį, kad gražintų VIEŠPATIES namus, esančius Jeruzalėje;'),
  (@b15, 7, 28, 'ir kuris suteikė man gailestingumą karaliaus akivaizdoje, jo patarėjų ir visų galingų karaliaus kunigaikščių akivaizdoje. Ir aš buvau sustiprintas, kai VIEŠPATIES, mano Dievo, ranka buvo ant manęs, ir surinkau iš Izraelio vyriausiuosius, kad eitų su manimi aukštyn.'),
  (@b15, 8, 1, 'Šitie yra jų tėvų vyriausieji, ir šita yra genealogija tų, kurie karaliui Artakserksui karaliaujant, ėjo aukštyn su manimi iš Babilono.'),
  (@b15, 8, 2, 'Iš Finehaso sūnų – Geršomas; iš Itamaro sūnų – Danielius; iš Dovydo sūnų – Hatušas;'),
  (@b15, 8, 3, 'iš Šechanijos sūnų, iš Parošo sūnų – Zacharija; o su juo pagal genealogiją buvo suskaičiuoti šimtas penkiasdešimt iš vyriškos lyties;'),
  (@b15, 8, 4, 'iš Pahat-Moabo sūnų – Zerachijos sūnus Eljehoenajas ir su juo du šimtai iš vyriškos lyties;'),
  (@b15, 8, 5, 'iš Šechanijos sūnų – Jahazielio sūnus ir su juo trys šimtai iš vyriškos lyties;'),
  (@b15, 8, 6, 'taip pat iš Adino sūnų – Jonatano sūnus Ebedas ir su juo penkiasdešimt iš vyriškos lyties;'),
  (@b15, 8, 7, 'o iš Elamo sūnų – Atalijos sūnus Ješaja ir su juo septyniasdešimt iš vyriškos lyties;'),
  (@b15, 8, 8, 'o iš Šefatijos sūnų – Mykolo sūnus Zebadija ir su juo aštuoniasdešimt iš vyriškos lyties;'),
  (@b15, 8, 9, 'iš Joabo sūnų – Jehielio sūnus Abdijas ir su juo du šimtai aštuoniolika iš vyriškos lyties;'),
  (@b15, 8, 10, 'o iš Šelomito sūnų – Josifijos sūnus ir su juo šimtas šešiasdešimt iš vyriškos lyties;'),
  (@b15, 8, 11, 'o iš Bebajo sūnų – Bebajo sūnus Zacharija ir su juo dvidešimt aštuoni iš vyriškos lyties;'),
  (@b15, 8, 12, 'o iš Azgado sūnų – Hakatano sūnus Johananas ir su juo šimtas dešimt iš vyriškos lyties;'),
  (@b15, 8, 13, 'o iš paskutinių Adonikamo sūnų, kurių vardai yra šitie: Elifeletas, Jejelis ir Šemaja, ir su jais šešiasdešimt iš vyriškos lyties;'),
  (@b15, 8, 14, 'taip pat iš Bigvajo sūnų – Utajas ir Zabudas, ir su jais septyniasdešimt iš vyriškos lyties.'),
  (@b15, 8, 15, 'Ir aš juos surinkau prie upės, tekančios į Ahavą; ir ten mes pasilikome palapinėse tris dienas; o apžiūrėjęs tautą ir kunigus, ten neradau nei vieno iš Levio sūnų.'),
  (@b15, 8, 16, 'Tada siunčiau pakviesti Eliezerą, Arielį, Šemają, Elnataną, Jaribą, Elnataną, Nataną, Zachariją, Mešulamą, vyriausiuosius vyrus; taip pat Jojaribą ir Elnataną, suprantančius vyrus.'),
  (@b15, 8, 17, 'Ir siunčiau juos su įsakymu pas Idoją, vyriausiąjį Kasifijos vietoje, ir pasakiau jiems, ką jie turi kalbėti Idojui ir jo broliams netinimams Kasifijos vietoje, kad jie mums atvestų tarnų mūsų Dievo namams.'),
  (@b15, 8, 18, 'Ir per mūsų Dievo gerąją ranką, esančią ant mūsų, jie mums atvedė suprantantį vyrą iš Izraelio sūnaus Levio sūnaus Mahlio sūnų; ir Šerebiją su jo sūnumis ir jo broliais – aštuoniolika;'),
  (@b15, 8, 19, 'ir Hašabiją, o su juo Ješają iš Merario sūnų, jo brolius ir jų sūnus – dvidešimt;'),
  (@b15, 8, 20, 'taip pat iš netinimų, kuriuos Dovydas ir kunigaikščiai buvo paskyrę levitų tarnavimui, – du šimtus dvidešimt netinimų; jie visi buvo išvardinti vardais.'),
  (@b15, 8, 21, 'Paskui aš ten prie Ahavos upės paskelbiau pasninką, kad vargintume save savo Dievo akyse, siekdami iš jo teisingo kelio mums, mūsų mažyliams ir visam mūsų turtui.'),
  (@b15, 8, 22, 'Nes man buvo gėda iš karaliaus prašyti kareivių ir raitelių būrio, kad mums pagelbėtų nuo priešo kelyje; nes buvome kalbėję karaliui, sakydami: „Mūsų Dievo ranka yra dėl gero ant visų tų, kurie jo ieško; bet jo jėga ir jo rūstybė yra prieš visus tuos, kurie jį palieka“.'),
  (@b15, 8, 23, 'Taip mes pasninkavome ir maldavome savo Dievą dėl šito; ir jis davėsi mūsų išmeldžiamas.'),
  (@b15, 8, 24, 'Tada aš atskyriau dvylika iš kunigų vyriausiųjų: Šerebiją, Hašabiją, o su jais dešimt jų brolių,'),
  (@b15, 8, 25, 'ir jiems pasvėriau sidabrą, auksą ir indus – mūsų Dievo namų atnašą, kurią buvo paaukoję karalius, jo patarėjai, jo viešpačiai ir visas ten esantis Izraelis;'),
  (@b15, 8, 26, 'aš atsvėriau jiems į ranką šešis šimtus penkiasdešimt talentų sidabro, šimtą talentų sidabrinių indų ir šimtą talentų aukso;'),
  (@b15, 8, 27, 'taip pat dvidešimt auksinių taurių tūkstančio drachmų; ir du indus iš geriausio vario, brangaus kaip auksas.'),
  (@b15, 8, 28, 'Ir jiems pasakiau: „Jūs esate VIEŠPAČIUI šventi; indai taip pat yra šventi; o sidabras ir auksas yra savanoriška atnaša VIEŠPAČIUI, jūsų tėvų Dievui.'),
  (@b15, 8, 29, 'Budėkite ir saugokite juos, kol juos pasversite kunigų bei levitų vyriausiųjų ir Izraelio tėvų vyriausiųjų akivaizdoje Jeruzalėje, VIEŠPATIES namų kambariuose“.'),
  (@b15, 8, 30, 'Taigi kunigai ir levitai paėmė sidabro, aukso ir indų svorį, kad juos nugabentų į Jeruzalę, į mūsų Dievo namus.'),
  (@b15, 8, 31, 'Tada pirmojo mėnesio dvyliktąją dieną mes nuėjome nuo Ahavos upės, kad keliautume į Jeruzalę; ir mūsų Dievo ranka buvo ant mūsų, ir jis mus išgelbėjo iš priešo rankos ir iš tykojančių kelyje.'),
  (@b15, 8, 32, 'Ir mes atvykome į Jeruzalę ir ten pasilikome tris dienas.'),
  (@b15, 8, 33, 'Na, o ketvirtąją dieną buvo pasverti sidabras, auksas ir indai mūsų Dievo namuose per Meremoto, kunigo Ūrijos sūnaus, ranką; o su juo buvo Finehaso sūnus Eleazaras; ir su jais buvo Jėzuės sūnus Jozabadas bei Binujo sūnus Noadija, levitai;'),
  (@b15, 8, 34, 'pagal kiekvieno skaičių ir svorį; ir tuo metu visas svoris buvo užrašytas.'),
  (@b15, 8, 35, 'Taip pat vaikai išvestųjų, kurie buvo išėję iš nelaisvės, atnašavo deginamąsias atnašas Izraelio Dievui: dvylika jaučių už visą Izraelį, devyniasdešimt šešis avinus, septyniasdešimt septynis avinėlius, dvylika ožių nuodėmės atnašai; visa tai buvo deginamoji atnaša VIEŠPAČIUI.'),
  (@b15, 8, 36, 'Ir jie įteikė karaliaus pavedimus karaliaus pavaduotojams ir valdytojams šioje upės pusėje; ir jie parėmė tautą ir Dievo namus.'),
  (@b15, 9, 1, 'Na, o kai tie dalykai buvo atlikti, prie manęs priėjo kunigaikščiai, sakydami: „Izraelio tauta, kunigai ir levitai neatsiskyrė nuo šalių tautų, darydami pagal jų bjaurystes, būtent pagal kanaaniečių, hetitų, perizų, jebusiečių, amoniečių, moabiečių, egiptiečių ir amoritų.'),
  (@b15, 9, 2, 'Nes jie yra paėmę jų dukterų sau ir savo sūnums; taip, kad šventoji sėkla susimaišė su tų šalių tautomis; taip, kunigaikščių ir valdovų ranka buvo pagrindinė šiame nusižengime“.'),
  (@b15, 9, 3, 'Ir tai išgirdęs, aš perplėšiau savo drabužį ir savo mantiją, roviau savo galvos ir savo barzdos plaukus ir sėdėjau pritrenktas.'),
  (@b15, 9, 4, 'Tada susirinko prie manęs visi, kurie drebėjo prieš Izraelio Dievo žodžius dėl nusižengimo tų, kurie yra buvę išvesti; o aš sėdėjau pritrenktas iki vakarinės aukos.'),
  (@b15, 9, 5, 'Ir vakarinės aukos metu atsikėliau iš savo liūdesio; ir perplėštu drabužiu bei mantija parpuoliau ant kelių ir išskėčiau rankas į VIEŠPATĮ, savo Dievą,'),
  (@b15, 9, 6, 'ir tariau: „O mano Dieve, aš susigėdęs, ir man gėda pakelti savo veidą į tave, mano Dieve; nes mūsų neteisybės yra išaugę virš mūsų galvos ir mūsų nusižengimas yra užaugęs iki dangų.'),
  (@b15, 9, 7, 'Nuo mūsų tėvų dienų iki šios dienos mes buvome didžiuliame nusižengime; ir dėl mūsų neteisybių mes, mūsų karaliai ir mūsų kunigai, buvome atiduoti į šalių karalių rankas, kalavijui, nelaisvei, apiplėšimui ir veido susigėdijimui, kaip yra šią dieną.'),
  (@b15, 9, 8, 'O dabar trumpam laikui buvo parodyta malonė nuo VIEŠPATIES, mūsų Dievo, kad mums paliktų likutį išsigelbėti ir mums duotų vinį savo šventoje vietoje, idant mūsų Dievas mums apšviestų akis ir duotų mums nedidelę atgaivą mūsų vergystėje.'),
  (@b15, 9, 9, 'Nes mes buvome vergai; tačiau mūsų Dievas mūsų nepaliko mūsų vergystėje, bet suteikė mums gailestingumą Persijos karalių akyse, idant suteiktų mums atgaivą, kad atstatytume mūsų Dievo namus ir atitaisytume jų griuvėsius, ir kad mums duotų sieną Judoje bei Jeruzalėje.'),
  (@b15, 9, 10, 'O dabar, o mūsų Dieve, ką pasakysime po šito? Juk palikome tavo įsakymus,'),
  (@b15, 9, 11, 'kuriuos įsakei per savo tarnus pranašus, tardamas: Šalis, į kurią jūs įeisite jos pasisavinti, yra šalis, nešvari šalių tautų nešvarumais, jų bjaurystėmis, kurios ją pripildė savo nešvarumais nuo vieno galo iki kito.'),
  (@b15, 9, 12, 'Todėl dabar neduokite savo dukterų jų sūnums nei neimkite jų dukterų savo sūnums, nei nesiekite jų taikos ar jų turto per amžius; kad būtumėte stiprūs, valgytumėte šalies gėrybes ir paliktumėte ją kaip paveldą savo vaikams per amžius.'),
  (@b15, 9, 13, 'Ir po viso to, kas užėjo ant mūsų dėl mūsų piktų darbų ir dėl mūsų didelio nusižengimo, atsižvelgiant į tai, kad tu, mūsų Dievas, mus nubaudei mažiau negu nusipelnė mūsų neteisybės, ir mums davei tokį išvadavimą kaip šis;'),
  (@b15, 9, 14, 'argi mes vėl laužysime tavo įsakymus ir susigiminiuosime su šitų bjaurysčių tautomis? Argi tu nesupyktum ant mūsų, kol mus sunaikintum taip, kad nebūtų jokio likučio ar išsigelbėjimo?'),
  (@b15, 9, 15, 'O VIEŠPATIE, Izraelio Dieve, tu esi teisus; nes mes, kaip šią dieną yra, tebesame išlikę išsigelbėję; štai mes esame tavo akivaizdoje savo nusižengimuose; nes mes negalime stovėti tavo akivaizdoje dėl to“.'),
  (@b15, 10, 1, 'Na, o kai Ezra meldėsi ir išpažino, verkdamas ir parkritęs prieš Dievo namus, prie jo iš Izraelio susirinko labai didelis vyrų, moterų ir vaikų susirinkimas; nes tauta labai verkė.'),
  (@b15, 10, 2, 'Ir Jehielio sūnus Šechanijas, vienas iš Elamo sūnų, atsiliepdamas tarė Ezrai: „Mes nusižengėme prieš mūsų Dievą ir esame pasiėmę svetimtaučių žmonų iš tos šalies tautų; tačiau dabar dar yra viltis Izraelyje dėl šito dalyko.'),
  (@b15, 10, 3, 'Taigi dabar sudarykime su mūsų Dievu sandorą, kad atleisime visas tas žmonas ir tuos, kurie yra iš jų gimę, pagal patarimą mano viešpaties ir tų, kurie dreba prieš mūsų Dievo įsakymą; ir tebūna tai daroma pagal įstatymą.'),
  (@b15, 10, 4, 'Kelkis; nes tai tavo reikalas; mes irgi būsime su tavimi; būk drąsus ir daryk tai“.'),
  (@b15, 10, 5, 'Tada Ezra kėlėsi ir prisaikdino vyriausiuosius kunigus, levitus ir visą Izraelį, kad jie darytų pagal šitą žodį. Ir jie prisiekė.'),
  (@b15, 10, 6, 'Tada Ezra pakilo nuo Dievo namų priekio ir nuėjo į Eljašibo sūnaus Johanano kambarį; ir ten atėjęs, jis nevalgė duonos ir negėrė vandens; nes jis gedėjo dėl nusižengimo tų, kurie buvo išvesti.'),
  (@b15, 10, 7, 'Ir jie paskelbė Judoje ir Jeruzalėje visiems nelaisvės vaikams, kad jie turi susirinkti į Jeruzalę;'),
  (@b15, 10, 8, 'o jei kas per tris dienas neateis, visas jo turtas pagal kunigaikščių ir vyresniųjų nutarimą turi būti konfiskuotas, o jis pats atskirtas nuo susirinkimo tų, kurie yra buvę išvesti.'),
  (@b15, 10, 9, 'Tada visi Judos ir Benjamino žmonės per tris dienas susirinko į Jeruzalę. Tai buvo devintas mėnuo, dvidešimtąją to mėnesio dieną; ir visa tauta sėdėjo Dievo namų gatvėje, drebėdami dėl to dalyko ir dėl didelio lietaus.'),
  (@b15, 10, 10, 'Ir kunigas Ezra atsistojęs jiems tarė: „Jūs nusižengėte ir ėmėte svetimtautes žmonas, kad padidintumėte Izraelio nusižengimą.'),
  (@b15, 10, 11, 'Todėl dabar atlikite išpažintį VIEŠPAČIUI, savo tėvų Dievui, ir vykdykite jo norą: atsiskirkite nuo tos šalies tautų ir nuo svetimtaučių žmonų“.'),
  (@b15, 10, 12, 'Tada visas susirinkimas atsakydami tarė garsiu balsu: „Mes turime daryti taip, kaip tu pasakei.'),
  (@b15, 10, 13, 'Bet yra daug liaudies ir didelio lietaus metas, ir mes negalime stovėti lauke, be to, tai ne vienos ir ne dviejų dienų darbas; nes mūsų, nusižengusių šiame dalyke, yra daug.'),
  (@b15, 10, 14, 'Tegul dabar atsistoja mūsų valdovai viso susirinkimo ir tegul visi mūsų miestuose, paėmę svetimtautes žmonas, ateina paskirtais laikais, o su jais vyresnieji kiekvieno miesto ir jų teisėjai, kol dėl šito dalyko nuo mūsų nusisuks mūsų Dievo smarki rūstybė“.'),
  (@b15, 10, 15, 'Tik Asahelio sūnus Jonatanas ir Tikvos sūnus Jachzėjas buvo užsiėmę šituo reikalu; o Mešulamas ir levitas Šabetajas jiems padėjo.'),
  (@b15, 10, 16, 'Ir nelaisvės vaikai taip padarė. O kunigas Ezra su kai kuriais tėvų vyriausiais, pagal jų tėvų namus, ir jie visi pagal jų vardus buvo atskirti, ir dešimtojo mėnesio pirmąją dieną susėdo, kad ištirtų tą reikalą.'),
  (@b15, 10, 17, 'Ir iki pirmojo mėnesio pirmos dienos jie užbaigė su visais vyrais, ėmusiais svetimtautes žmonas.'),
  (@b15, 10, 18, 'Ir tarp kunigų sūnų atsirado paėmusiųjų svetimtautes žmonas, būtent iš Jocadako sūnaus Jėzuės sūnų ir jo brolių: Maasėja, Eliezeras, Jaribas ir Gedalija.'),
  (@b15, 10, 19, 'Ir jie padavė savo rankas, kad jie atleis savo žmonas; ir būdami kalti jie atnašavo kaimenės aviną už savo nusižengimą.'),
  (@b15, 10, 20, 'O iš Imero sūnų: Hananis ir Zebadija.'),
  (@b15, 10, 21, 'O iš Harimo sūnų: Maasėja, Elija, Šemaja, Jehielis ir Uzija.'),
  (@b15, 10, 22, 'O iš Pašhūro sūnų: Eljoenajas, Maasėja, Išmaelis, Netanelis, Jozabadas ir Elasa.'),
  (@b15, 10, 23, 'Taip pat iš levitų: Jozabadas, Šimis, Kelaja (tas pats yra Kelita), Petahija, Juda ir Eliezeras.'),
  (@b15, 10, 24, 'Taip pat iš giesmininkų: Eljašibas; o iš durininkų: Šalumas, Telemas ir Ūris.'),
  (@b15, 10, 25, 'Be to iš Izraelio: iš Parošo sūnų: Ramija, Jizija, Malkija, Mijaminas, Eleazaras, Malkija ir Benaja.'),
  (@b15, 10, 26, 'O iš Elamo sūnų: Matanija, Zacharija, Jehielis, Abdis, Jeremotas ir Elija.'),
  (@b15, 10, 27, 'O iš Zatuvo sūnų: Eljoenajas, Eljašibas, Matanija, Jeremotas, Zabadas ir Aziza.'),
  (@b15, 10, 28, 'Taip pat iš Bebajo sūnų: Jehohananas, Hananija, Zabajas, Atlajas.'),
  (@b15, 10, 29, 'O iš Banio sūnų: Mešulamas, Maluchas, Adaja, Jašubas, Šealas, Ramotas.'),
  (@b15, 10, 30, 'O iš Pahat-Moabo sūnų: Adna, Kelalas, Benaja, Maasėja, Matanija, Becalelis, Binujas ir Manasas.'),
  (@b15, 10, 31, 'O iš Harimo sūnų: Eliezeras, Išija, Malkija, Šemaja, Šimeonas,'),
  (@b15, 10, 32, 'Benjaminas, Maluchas, Šemarija.'),
  (@b15, 10, 33, 'Iš Hašumo sūnų: Matenajas, Matata, Zabadas, Elifeletas, Jeremajas, Manasas, Šimis.'),
  (@b15, 10, 34, 'Iš Banio sūnų: Maadajas, Amramas, Uelis,'),
  (@b15, 10, 35, 'Benaja, Bedija, Keluhis,'),
  (@b15, 10, 36, 'Vanija, Meremotas, Eljašibas,'),
  (@b15, 10, 37, 'Matanija, Matenajas, Jaasajas,'),
  (@b15, 10, 38, 'Banis, Binujis, Šimis,'),
  (@b15, 10, 39, 'Šelemija, Natanas ir Adaja,'),
  (@b15, 10, 40, 'Machnadbajas, Šašajas, Šarajas,'),
  (@b15, 10, 41, 'Azarelis ir Šelemija, Šemarija,'),
  (@b15, 10, 42, 'Šalumas, Amarija ir Juozapas.'),
  (@b15, 10, 43, 'Iš Nebojo sūnų: Jejelis, Matitija, Zabadas, Zebina, Jadajas ir Joelis, Benaja.'),
  (@b15, 10, 44, 'Visi šitie buvo paėmę svetimtautes žmonas; o kai kurie iš jų turėjo žmonas, iš kurių jie turėjo vaikų.'),
  (@b16, 1, 1, 'Hachalijos sūnaus Nehemijo žodžiai. Ir įvyko, kad Kislevo mėnesį, dvidešimtaisiais metais, man esant Šušano rūmuose,'),
  (@b16, 1, 2, 'Hananis, vienas iš mano brolių, atvyko su kai kuriais vyrais iš Judos; ir aš juos klausinėjau apie išsigelbėjusius žydus, kurie buvo išlikę iš nelaisvės, ir apie Jeruzalę.'),
  (@b16, 1, 3, 'Ir jie man sakė: „Likutis, kuris išliko iš nelaisvės, ten provincijoje yra dideliame varge ir gėdoje; taip pat Jeruzalės siena sugriauta, ir jos vartai sudeginti ugnimi“.'),
  (@b16, 1, 4, 'Ir įvyko, kad išgirdęs šituos žodžius aš atsisėdęs verkiau ir liūdėjau ištisas dienas, ir pasninkavau, ir meldžiausi dangaus Dievo akivaizdoje,'),
  (@b16, 1, 5, 'ir tariau: „Meldžiu tave, o VIEŠPATIE, dangaus Dieve, didysis ir baisusis Dieve, kuris laikaisi sandoros ir gailestingumo tiems, kurie jį myli ir laikosi jo įsakymų;'),
  (@b16, 1, 6, 'tebūna dabar tavo ausis dėmesinga ir tavo akys atviros, kad išgirstum savo tarno maldą, kuria aš dabar meldžiuosi tavo akivaizdoje dieną ir naktį už Izraelio vaikus, tavo tarnus, ir išpažįstu Izraelio vaikų nuodėmes, kuriomis mes prieš tave nusidėjome; tiek aš, tiek mano tėvo namai nusidėjome.'),
  (@b16, 1, 7, 'Mes labai sugedusiai prieš tave elgėmės ir nesilaikėme įsakymų, įstatų ir teismų, kuriuos įsakei savo tarnui Mozei.'),
  (@b16, 1, 8, 'Atsimink, meldžiu tave, tą žodį, kurį įsakei savo tarnui Mozei, sakydamas: ‘Jei jūs nusižengsite, aš jus išsklaidysiu tarp tautų;'),
  (@b16, 1, 9, 'bet jei gręšitės į mane, laikysitės mano įsakymų ir juos vykdysite; tai, nors iš jūsų ir būtų išvarytų į tolimiausius dangaus pakraščius, tačiau aš iš ten juos surinksiu ir parvesiu į vietą, kurią išsirinkau, kad ten pastatyčiau savo vardą’.'),
  (@b16, 1, 10, 'Na, o šitie yra tavo tarnai ir tavo tauta, kurią atpirkai savo didele jėga ir savo stipria ranka.'),
  (@b16, 1, 11, 'O Viešpatie, meldžiu tave, tebūna dabar tavo ausis dėmesinga tavo tarno maldai ir maldai tavo tarnų, kurie trokšta bijoti tavo vardo; ir duok šią dieną, meldžiu tave, savo tarnui pasisekimą ir suteik jam gailestingumą šito vyro akyse“. Nes aš buvau karaliaus taurininkas.'),
  (@b16, 2, 1, 'Ir įvyko, kad Nisano mėnesį, dvidešimtaisiais karaliaus Artakserkso metais, vynas buvo jo priešakyje; aš pakėliau vyną ir jį padaviau karaliui. Na, o anksčiau aš nebuvau liūdnas jo akivaizdoje.'),
  (@b16, 2, 2, 'Todėl karalius man tarė: „Kodėl tavo veidas liūdnas? Tu juk nesergi. Tai niekas kita, kaip tik širdies sielvartas“. Tada aš labai išsigandau'),
  (@b16, 2, 3, 'ir tariau karaliui: „Tegyvuoja karalius amžinai; kodėl mano veidas neturėtų būti liūdnas, kai tas miestas, mano tėvų kapų vieta, nuniokotas, ir jo vartai ugnies praryti?“'),
  (@b16, 2, 4, 'Tada karalius man tarė: „Ko gi tu prašai?“ Taigi aš meldžiausi dangaus Dievui.'),
  (@b16, 2, 5, 'Ir aš pasakiau karaliui: „Jei karaliui patinka ir jei tavo tarnas rado palankumą tavo akyse, siųsk mane į Judą, į mano tėvų kapų miestą, kad jį statyčiau“.'),
  (@b16, 2, 6, 'Ir karalius (karalienei irgi sėdint šalia jo) man tarė: „Kaip ilgai užtruks tavo kelionė ir kada sugrįši?“ Taigi karaliui patiko mane siųsti; ir aš nustačiau jam laiką.'),
  (@b16, 2, 7, 'Be to, sakiau karaliui: „Jei karaliui patinka, tebūna man duota laiškų valdytojams anapus upės, kad jie mane pravestų, kol atvyksiu į Judą;'),
  (@b16, 2, 8, 'ir laiškas Asafui, karaliaus miško saugotojui, kad jis man duotų medienos: rūmų, priklausančių namams, vartų sijoms padaryti, taip pat miesto sienai ir namams, į kuriuos aš įeisiu“. Ir karalius man davė pagal gerą mano Dievo ranką ant manęs.'),
  (@b16, 2, 9, 'Tada atvykau pas valdytojus anapus upės ir jiems padaviau karaliaus laiškus. Na, o karalius buvo pasiuntęs su manimi kariuomenės vadus ir raitelius.'),
  (@b16, 2, 10, 'Kai horonietis Sanbalatas ir amonietis tarnas Tobija tai išgirdo, jiems nepaprastai sukėlė sielvartą, kad buvo atvykęs žmogus siekti Izraelio vaikų gerovės.'),
  (@b16, 2, 11, 'Taigi atvykęs į Jeruzalę, ten buvau tris dienas.'),
  (@b16, 2, 12, 'Ir atsikėliau naktį, aš ir keli vyrai su manimi; aš niekam nesakiau, ką mano Dievas man įdėjo į širdį, kad daryčiau Jeruzalėje; ir su manimi nebuvo jokio gyvulio, išskyrus tą gyvulį, ant kurio aš jojau.'),
  (@b16, 2, 13, 'Ir naktį išvykau pro Slėnio vartus, priešais Slibino šaltinį, į Mėšlo vartus, apžiūrinėdamas Jeruzalės išgriautas sienas, kurių vartai buvo ugnies praryti.'),
  (@b16, 2, 14, 'Tada ėjau toliau iki Šaltinio vartų ir iki Karaliaus tvenkinio; bet gyvuliui, esančiam po manimi, nebuvo vietos praeiti.'),
  (@b16, 2, 15, 'Tada naktį ėjau aukštyn palei upelį, apžiūrėdamas sieną, ir pasukęs atgal įėjau pro Slėnio vartus, ir taip sugrįžau.'),
  (@b16, 2, 16, 'O valdovai nežinojo, kur ėjau ir ką dariau; nei žydams aš to dar nebuvau sakęs, nei kunigams, nei kilmingiesiems, nei valdovams, nei kitiems, atliekantiems darbą.'),
  (@b16, 2, 17, 'Tada jiems tariau: „Jūs matote, kokiame varge mes esame, kad Jeruzalė nuniokota ir jos vartai sudeginti ugnimi; eime ir pastatykime Jeruzalės sieną, kad mes nebebūtume priekaištu“.'),
  (@b16, 2, 18, 'Tada jiems papasakojau apie mano Dievo ranką, kuri buvo ant manęs gera; taip pat karaliaus žodžius, kuriuos jis man pasakė. Ir jie tarė: „Kelkimės ir statykime“. Taip jie sustiprino savo rankas šiam geram darbui.'),
  (@b16, 2, 19, 'Bet kai horonietis Sanbalatas, amonietis tarnas Tobija ir arabas Gešemas tai išgirdo, jie mus išjuokė ir, mus niekindami, tarė: „Ką gi jūs čia darote? Ar jūs maištausite prieš karalių?“'),
  (@b16, 2, 20, 'Tada aš atsakiau ir jiems tariau: „Dangaus Dievas, jis mums duos pasisekimą; todėl mes, jo tarnai, pakilę statysime; bet jūs neturite nei dalies, nei teisės, nei atminimo Jeruzalėje“.'),
  (@b16, 3, 1, 'Tada aukščiausiasis kunigas Eljašibas pakilo su savo broliais kunigais ir jie pastatė Avių vartus; jie pašventė juos ir įstatė jų duris; jie pašventė juos iki Mejos bokšto, iki Hananelio bokšto.'),
  (@b16, 3, 2, 'O šalia jo statė Jericho vyrai. O šalia jų statė Imrio sūnus Zakūras.'),
  (@b16, 3, 3, 'Bet Žuvų vartus statė Hasenajo sūnūs, kurie taipogi sudėjo jų sijas ir įstatė jų duris, jų užraktus ir jų skląsčius.'),
  (@b16, 3, 4, 'O šalia jų taisė Koco sūnaus Ūrijo sūnus Meremotas. O šalia jų taisė Mešezabelio sūnaus Berechijos sūnus Mešulamas. O šalia jų taisė Baanos sūnus Cadokas.'),
  (@b16, 3, 5, 'O šalia jų taisė tekojiečiai; bet jų kilmingieji nepalenkė savo sprandų prie savo Viešpaties darbo.'),
  (@b16, 3, 6, 'Senuosius vartus dar taisė Paseacho sūnus Jehojada ir Besodijos sūnus Mešulamas; jie sudėjo jų sijas, įstatė jų duris ir jų užraktus, ir jų skląsčius.'),
  (@b16, 3, 7, 'O šalia jų taisė gibeonietis Malatija ir meronotietis Jadonas, Gibeono ir Micpos vyrai, iki valdytojo sosto šioje upės pusėje.'),
  (@b16, 3, 8, 'Šalia jo taisė Harhajos sūnus Uzielis iš auksakalių. Šalia jo taisė Hananijas, vieno iš vaistininkų sūnus, ir jie sutvirtino Jeruzalę iki Plačiosios sienos.'),
  (@b16, 3, 9, 'O šalia jų taisė Hūro sūnus Refaja, pusės Jeruzalės dalies valdovas.'),
  (@b16, 3, 10, 'O šalia jų taisė Harumafo sūnus Jedaja priešais savo namus. O šalia jo taisė Hašabnėjo sūnus Hatušas.'),
  (@b16, 3, 11, 'Harimo sūnus Malkija ir Pahat-Moabo sūnus Hašubas taisė kitą dalį ir Krosnių bokštą.'),
  (@b16, 3, 12, 'O šalia jo taisė Halohešo sūnus Šalumas, pusės Jeruzalės dalies valdovas, jis ir jo dukterys.'),
  (@b16, 3, 13, 'Slėnio vartus taisė Hanūnas ir Zanoacho gyventojai; jie pastatė juos, įstatė jų duris, jų užraktus ir jų skląsčius, ir pristatė tūkstantį uolekčių prie sienos iki Mėšlo vartų.'),
  (@b16, 3, 14, 'Bet Mėšlo vartus taisė Rechabo sūnus Malkija, Bet-Hakeremo dalies valdovas; jis juos pastatė, įstatė jų duris ir jų užraktus, ir jų skląsčius.'),
  (@b16, 3, 15, 'Bet Šaltinio vartus taisė Kol-Hozės sūnus Šalunas, Micpos dalies valdovas; jis juos pastatė, apdengė juos ir įstatė jų duris, jų užraktus ir jų skląsčius, ir Siloacho tvenkinio sieną prie karaliaus sodo ir iki laiptų, nusileidžiančių iš Dovydo miesto.'),
  (@b16, 3, 16, 'Už jo taisė Azbuko sūnus Nehemijas, pusės Bet-Cūro dalies valdovas, iki vietos priešais Dovydo kapus ir iki padaryto tvenkinio, ir iki galiūnų namų.'),
  (@b16, 3, 17, 'Už jo taisė levitai: Banio sūnus Rehumas. Šalia jo taisė Hašabija, pusės Keilos dalies valdovas, savo dalyje.'),
  (@b16, 3, 18, 'Už jo taisė jų broliai: Henadado sūnus Bavajis, pusės Keilos dalies valdovas.'),
  (@b16, 3, 19, 'O šalia jo taisė Jėzuės sūnus Ezeras, Micpos valdovas, kitą dalį priešais užkilimą į ginklų sandėlį prie sienos pasisukimo.'),
  (@b16, 3, 20, 'Už jo Zabajo sūnus Baruchas uoliai taisė kitą dalį nuo sienos pasisukimo iki aukščiausiojo kunigo Eljašibo namų durų.'),
  (@b16, 3, 21, 'Už jo Meremotas, Koco sūnaus Ūrijos sūnus, taisė kitą dalį nuo Eljašibo namų durų iki Eljašibo namų galo.'),
  (@b16, 3, 22, 'O už jo taisė kunigai, lygumos vyrai.'),
  (@b16, 3, 23, 'Už jų taisė Benjaminas ir Hašubas priešais savo namus. Už jo taisė Azarija, Ananijos sūnaus Maasėjo sūnus, šalia savo namų.'),
  (@b16, 3, 24, 'Už jo Henadado sūnus Binujis taisė kitą dalį nuo Azarijos namų iki sienos pasisukimo, būtent iki kampo.'),
  (@b16, 3, 25, 'Uzajo sūnus Palalas – priešais sienos pasisukimą ir bokštą, išsikišantį iš karaliaus aukštųjų namų, esančių prie kalėjimo kiemo. Už jo – Parošo sūnus Pedaja.'),
  (@b16, 3, 26, 'Be to, netinimai gyveno Ofelyje, iki vietos priešais Vandens vartus link rytų ir išsikišusio bokšto.'),
  (@b16, 3, 27, 'Už jų tekojiečiai taisė kitą dalį priešais išsikišusį didįjį bokštą iki Ofelio sienos.'),
  (@b16, 3, 28, 'Nuo Žirgų vartų viršaus taisė kunigai, kiekvienas priešais savo namus.'),
  (@b16, 3, 29, 'Už jų taisė Imerio sūnus Cadokas priešais savo namus. Už jo taisė Šechanijo sūnus Šemajas, rytinių vartų sargas.'),
  (@b16, 3, 30, 'Už jo Šelemijo sūnus Hananija ir Calafo šeštasis sūnus Hanūnas taisė kitą dalį. Už jo taisė Berechijo sūnus Mešulamas priešais savo kambarį.'),
  (@b16, 3, 31, 'Už jo taisė auksakalio sūnus Malkija iki netinimų ir pirklių vietos priešais Mifkado vartus ir iki kampo užkilimo.'),
  (@b16, 3, 32, 'O tarp kampo užkilimo ir Avių vartų taisė auksakaliai ir pirkliai.'),
  (@b16, 4, 1, 'Bet įvyko, kai Sanbalatas išgirdo, kad mes statome sieną, jis užsirūstino ir labai pasipiktinęs tyčiojosi iš žydų.'),
  (@b16, 4, 2, 'Ir jis kalbėjo savo brolių ir Samarijos kariuomenės akivaizdoje, sakydamas: „Ką daro tie silpni žydai? Ar jie sustiprės? Ar jie aukos? Ar jie užbaigs per dieną? Ar jie atgaivins iš šiukšlių krūvų akmenis, kurie yra sudegę?“'),
  (@b16, 4, 3, 'Na, o amonietis Tobija, esantis šalia jo, tarė: „Tai, ką jie stato, jei užliptų lapė, nugriautų jų akmeninę sieną“.'),
  (@b16, 4, 4, '„Išgirsk, o mūsų Dieve; nes mes esame niekinami; ir nukreipk jų priekaištus ant jų pačių galvos ir atiduok juos kaip grobį į nelaisvės šalį;'),
  (@b16, 4, 5, 'neuždenk jų neteisybės, ir teneišdyla jų nuodėmė tavo akivaizdoje; nes jie kurstė tavo pyktį statytojų akivaizdoje“.'),
  (@b16, 4, 6, 'Taip mes statėme sieną; ir visa siena iki pusės buvo sujungta; nes tauta dirbo nusiteikusiai.'),
  (@b16, 4, 7, 'Bet įvyko, kai Sanbalatas, Tobija, arabai, amoniečiai ir ašdodiečiai išgirdo, kad Jeruzalės sienos atstatomos, kad pradėjo užsidaryti spragos, jie labai užsirūstino'),
  (@b16, 4, 8, 'ir visi drauge susimokė ateiti ir kovoti prieš Jeruzalę ir jai trukdyti.'),
  (@b16, 4, 9, 'Tačiau mes meldėmės savo Dievui ir pastatėme prieš juos sargybą dieną bei naktį dėl jų.'),
  (@b16, 4, 10, 'Ir Juda tarė: „Išseko naštų nešėjų jėgos, o šiukšlių daug; taip, kad mes neįstengsime sienos pastatyti“.'),
  (@b16, 4, 11, 'Ir mūsų priešininkai sakė: „Jie nesužinos ir nepamatys, kol įeisime į jų tarpą ir išžudysime juos, ir padarysime, kad liautųsi šis darbas“.'),
  (@b16, 4, 12, 'Ir įvyko, kai šalia jų gyvenantys žydai atėjo, jie mums dešimt kartų sakė: „Iš visų vietų, į kurias jūs pas mus sugrįšite, jie jus užpuls“.'),
  (@b16, 4, 13, 'Todėl pastačiau žemutinėse vietose už sienos ir aukštesnėse vietose, aš pastačiau tautą pagal jų šeimas su jų kalavijais, jų ietimis ir jų lankais.'),
  (@b16, 4, 14, 'Ir apžiūrėjęs pakilau ir tariau kilmingiesiems, valdovams ir likusiai tautai: „Nebijokite jų; atsiminkite Viešpatį, didįjį ir baisų, ir kovokite už savo brolius, savo sūnus ir savo dukteris, savo žmonas ir savo namus“.'),
  (@b16, 4, 15, 'Ir įvyko, kai mūsų priešai išgirdo, kad mums tai buvo žinoma, ir kad Dievas pavertė jų sumanymą niekais, mes visi sugrįžome prie sienos, kiekvienas prie savo darbo.'),
  (@b16, 4, 16, 'Ir įvyko, kad nuo to laiko pusė mano tarnų dirbo tame darbe, o kita jų pusė laikė ietis, skydus, lankus ir šarvus; o valdovai buvo visų Judos namų užnugaryje.'),
  (@b16, 4, 17, 'Tie, kurie statė sieną, ir tie, kurie nešė naštas su tais, kurie krovė, kiekvienas viena ranka dirbo tame darbe, o kita laikė ginklą.'),
  (@b16, 4, 18, 'Nes statytojai kiekvienas turėjo savo kalaviją prisijuosęs prie šono ir taip statė. O gaudžiantis trimitu buvo šalia manęs.'),
  (@b16, 4, 19, 'Ir aš pasakiau kilmingiesiems, valdovams ir likusiai tautai: „Darbas yra didelis ir platus, o mes ant sienos esame atskirti, toli vienas nuo kito.'),
  (@b16, 4, 20, 'Todėl iš kurios vietos išgirsite trimito garsą, ten susirinkite prie mūsų; mūsų Dievas kovos už mus“.'),
  (@b16, 4, 21, 'Taip mes triūsėme darbe; pusė jų laikė ietis nuo ryto aušros iki žvaigždžių pasirodymo.'),
  (@b16, 4, 22, 'Taip pat tuo pačiu metu pasakiau tautai: „Tegul kiekvienas su savo tarnu nakvoja Jeruzalėje, kad naktį jie būtų mums sargyba, o dieną dirbtų.'),
  (@b16, 4, 23, 'Taigi nei aš, nei mano broliai, nei mano tarnai, nei sargybiniai, kurie sekė paskui mane, niekas iš mūsų nenusivilkdavome savo drabužių, išskyrus kai kiekvienas juos nusivilkdavo nusiprausimui.'),
  (@b16, 5, 1, 'Ir buvo didelis tautos ir jų žmonų šauksmas prieš jų brolius žydus.'),
  (@b16, 5, 2, 'Nes buvo tokių, kurie sakė: „Mūsų, mūsų sūnų ir mūsų dukterų yra daug; todėl įsigysime jiems grūdų, kad valgytume ir gyventume“.'),
  (@b16, 5, 3, 'Taip pat buvo vieni, kurie sakė: „Mes užstatėme dėl bado savo žemes, vynuogynus ir namus, kad nusipirktume grūdų“.'),
  (@b16, 5, 4, 'Taip pat buvo tokių, kurie sakė: „Mes pasiskolinome pinigų karaliaus duoklei, užstatydami savo žemes ir vynuogynus.'),
  (@b16, 5, 5, 'Tačiau dabar mūsų kūnai yra kaip mūsų brolių kūnai, mūsų vaikai kaip jų vaikai; ir štai mes vedame savo sūnus ir savo dukteris į vergystę būti tarnais, o kai kurios mūsų dukterys jau yra nuvestos į vergystę; ir ne mūsų jėgose jas atpirkti; nes kiti turi mūsų žemes ir vynuogynus“.'),
  (@b16, 5, 6, 'Ir aš labai supykau, kai išgirdau jų šauksmą ir šituos žodžius.'),
  (@b16, 5, 7, 'Tada, pasitaręs savyje, bariau kilminguosius bei valdovus ir jiems sakiau: „Jūs kiekvienas iš savo brolio reikalaujate palūkanų“. Ir aš surengiau prieš juos didelį susirinkimą.'),
  (@b16, 5, 8, 'Ir jiems tariau: „Mes pagal mūsų išgales išpirkome savo brolius žydus, parduotus pagonims; ar jūs parduosite savo brolius, ar jie bus mums parduoti?“ Tada jie tylėjo ir nerado atsakymo.'),
  (@b16, 5, 9, 'Taip pat aš tariau: „Negerai tai, ką jūs darote; argi neturėtumėte vaikščioti mūsų Dievo baimėje dėl mūsų priešų pagonių priekaištų?'),
  (@b16, 5, 10, 'Taip pat aš, mano broliai ir mano tarnai galime reikalauti iš jų pinigų ir grūdų; meldžiu jus, palikime šias palūkanas.'),
  (@b16, 5, 11, 'Grąžinkite jiems, meldžiu jus, šią dieną jų žemes, jų vynuogynus, jų alyvmedžių sodus, ir jų namus, taip pat šimtadalį pinigų, javų, vyno ir aliejaus, ką jūs reikalavote iš jų“.'),
  (@b16, 5, 12, 'Tada jie tarė: „Grąžinsime jiems ir nieko iš jų nereikalausime; padarysime taip, kaip tu sakai“. Tada pašaukiau kunigus ir juos prisaikdinau, kad jie darytų pagal šitą pažadą.'),
  (@b16, 5, 13, 'Taip pat, iškratęs savo skverną, tariau: „Tegul Dievas taip iškrato kiekvieną, kuris nevykdo šito pažado, iš jo namų ir iš jo triūso, būtent taip tegul jis bus iškratytas ir ištuštintas“. Ir visas susirinkimas tarė: „Amen“ ir gyrė VIEŠPATĮ. Ir tauta darė pagal šitą pažadą.'),
  (@b16, 5, 14, 'Be to, nuo to laiko, kai buvau paskirtas būti jų valdytoju Judos šalyje, nuo dvidešimtųjų iki trisdešimt antrųjų karaliaus Artakserkso metų, tai yra dvylika metų, aš ir mano broliai nevalgėme valdytojo duonos.'),
  (@b16, 5, 15, 'Bet ankstesnieji valdytojai, buvusieji pirma manęs, apmokestino tautą ir ėmė iš jų duoną ir vyną, neskaitant keturiasdešimties šekelių sidabro; taip, net jų tarnai valdė tautą; bet aš taip nedariau dėl Dievo baimės.'),
  (@b16, 5, 16, 'Taip, aš taipogi tęsiau šitos sienos darbe, ir nenusipirkome jokios žemės; ir visi mano tarnai buvo ten susirinkę prie darbo.'),
  (@b16, 5, 17, 'Be to, prie mano stalo buvo šimtas penkiasdešimt žydų ir valdovų, neskaitant tų, kurie ateidavo pas mus iš tarpo pagonių, esančių aplink mus.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b16, 5, 18, 'Na, o tai, kas kasdien būdavo man paruošiama, buvo vienas jautis ir šešios rinktinės avys; taip pat skrajūnai būdavo man paruošiami ir kas dešimt dienų gausiai visokio vyno; tačiau dėl viso to aš nereikalavau valdytojo duonos, nes vergystė buvo sunki ant šitos tautos.'),
  (@b16, 5, 19, 'Atsimink mane, mano Dieve, dėl gero, pagal visa tai, ką nuveikiau šitai tautai.'),
  (@b16, 6, 1, 'Na, o kai Sanbalatas, Tobija, arabas Gešemas ir kiti mūsų priešai išgirdo, kad buvau pastatęs sieną ir kad joje nebuvo likę jokios spragos (nors tuo laiku dar nebuvau įstatęs durų vartuose);'),
  (@b16, 6, 2, 'įvyko, kad Sanbalatas ir Gešemas atsiuntė pas mane, sakydami: „Ateik, susitikime kuriame nors iš kaimų Ono lygumoje“. Bet jie manė man padaryti pikta.'),
  (@b16, 6, 3, 'Ir aš nusiunčiau pas juos pasiuntinius, sakydamas: „Aš dirbu didelį darbą taip, kad negaliu ateiti žemyn; kodėl turėtų sustoti darbas, kol aš jį paliksiu ir ateisiu pas jus žemyn?“'),
  (@b16, 6, 4, 'Jie dar keturis kartus man siuntė tą patį; o aš jiems taip pat atsakiau.'),
  (@b16, 6, 5, 'Tada panašiu būdu Sanbalatas penktą kartą atsiuntė pas mane savo tarną su atviru laišku jo rankoje;'),
  (@b16, 6, 6, 'jame buvo parašyta: „Tarp pagonių eina kalbos, ir Gašmus tai sako, kad tu ir žydai ketinate maištauti; dėl ko tu ir pastatei sieną, kad galėtum būti jų karaliumi, pagal šiuos žodžius.'),
  (@b16, 6, 7, 'Tu paskyrei ir pranašų, kad skelbtų apie tave Jeruzalėje, sakydami: ‘Karalius yra Judoje’; o dabar pagal šituos žodžius tai bus paskelbta karaliui. Taigi dabar ateik, pasitarkime drauge“.'),
  (@b16, 6, 8, 'Tada aš nusiunčiau jam, sakydamas: „Neįvyko nieko panašaus į tai, ką tu sakai, bet tu tai prasimanei savo paties širdyje“.'),
  (@b16, 6, 9, 'Nes jie visi mus įbaugino, sakydami: „Jų rankos nusilps nuo darbo, kad jis nebūtų atliktas“. Taigi dabar, o Dieve, sustiprink mano rankas.'),
  (@b16, 6, 10, 'Paskui aš atėjau į Mehetabelio sūnaus Delajos sūnaus Šemajos namus, kuris buvo užsirakinęs; ir jis tarė: „Susitikime Dievo namuose, šventyklos viduje, ir užrakinkime šventyklos duris; nes jie ateis tavęs nužudyti; taip, naktį jie ateis tavęs nužudyti“.'),
  (@b16, 6, 11, 'O aš sakiau: „Ar toks vyras, kaip aš, turėčiau bėgti? Ir kas toks, būdamas kaip aš, eitų į šventyklą gelbėti savo gyvybę? Aš neisiu“.'),
  (@b16, 6, 12, 'Ir štai aš supratau, kad Dievas jo nebuvo siuntęs; bet kad jis paskelbė šią pranašystę prieš mane, nes Tobija ir Sanbalatas jį buvo pasamdę.'),
  (@b16, 6, 13, 'Jis buvo pasamdytas todėl, kad aš išsigandęs taip pasielgčiau ir nusidėčiau, ir kad jie turėtų dingstį piktam atsiliepimui, kad jie galėtų man priekaištauti.'),
  (@b16, 6, 14, 'Mano Dieve, atsimink Tobiją ir Sanbalatą pagal šituos jų darbus, ir pranašę Noadiją, ir kitus pranašus, kurie norėjo mane įbauginti.'),
  (@b16, 6, 15, 'Taigi siena buvo užbaigta Elulo mėnesio dvidešimt penktąją dieną, per penkiasdešimt dvi dienas.'),
  (@b16, 6, 16, 'Ir įvyko, kai tai išgirdo visi mūsų priešai, ir visi aplink mus esantys pagonys pamatė šituos dalykus, jie labai krito savo pačių akyse; nes jie suprato, kad šitas darbas buvo atliktas mūsų Dievo.'),
  (@b16, 6, 17, 'Be to, tomis dienomis Judos kilmingieji siųsdavo daug laiškų Tobijai, o Tobijos laiškai ateidavo pas juos.'),
  (@b16, 6, 18, 'Nes daugelis Judoje buvo jam prisiekę, nes jis buvo Araho sūnaus Šechanijos žentas; o jo sūnus Johananas buvo paėmęs Berechijos sūnaus Mešulamo dukterį.'),
  (@b16, 6, 19, 'Jie taip pat pasakodavo jo gerus darbus mano akivaizdoje, o mano žodžius jam pasakydavo. O Tobija siuntė laiškus mane įbauginti.'),
  (@b16, 7, 1, 'Na, o kai siena buvo pastatyta ir aš buvau įstatęs duris, ir buvo paskirti durininkai, giesmininkai ir levitai,'),
  (@b16, 7, 2, 'įvyko, kad aš daviau savo broliui Hananiui ir rūmų valdovui Hananijai įpareigojimą dėl Jeruzalės; nes jis buvo ištikimas vyras ir bijojo Dievo labiau už daugelį.'),
  (@b16, 7, 3, 'Ir jiems sakiau: „Tenebūna atidaryti Jeruzalės vartai iki saulės kaitros; ir kol jie stovi, teuždaro duris ir jas teužsklendžia; ir paskirkite sargybas iš Jeruzalės gyventojų, kiekvieną savo sargyboje ir kiekvieną būti priešais savo namus“.'),
  (@b16, 7, 4, 'Na, o miestas buvo platus ir didelis; bet liaudies jame buvo mažai, ir namai nepastatyti.'),
  (@b16, 7, 5, 'Ir mano Dievas man įdėjo į širdį surinkti kilminguosius, valdovus ir tautą, kad jie būtų suskaičiuoti pagal genealogijas. Ir aš radau genealoginį sąrašą tų, kurie buvo atėję aukštyn pradžioje, ir radau jame parašyta:'),
  (@b16, 7, 6, 'Šitie yra provincijos vaikai, kurie ėjo aukštyn iš nelaisvės, iš tų, kurie buvo išvesti, kuriuos Babilono karalius Nebukadnecaras buvo išvedęs, ir sugrįžo į Jeruzalę bei Judą, kiekvienas į savo miestą;'),
  (@b16, 7, 7, 'kurie atėjo su Zerubabeliu, Jėzue, Nehemiju, Azarija, Raamija, Nahamaniu, Mordekaju, Bilšanu, Misperetu, Bigvaju, Nehumu, Baana. Izraelio tautos žmonių skaičius, aš sakau, buvo šis:'),
  (@b16, 7, 8, 'Parošo vaikų: du tūkstančiai šimtas septyniasdešimt du;'),
  (@b16, 7, 9, 'Šefatijos vaikų: trys šimtai septyniasdešimt du;'),
  (@b16, 7, 10, 'Aracho vaikų: šeši šimtai penkiasdešimt du;'),
  (@b16, 7, 11, 'Pahat-Moabo vaikų iš Jėzuės ir Joabo vaikų: du tūkstančiai aštuoni šimtai aštuoniolika;'),
  (@b16, 7, 12, 'Elamo vaikų: tūkstantis du šimtai penkiasdešimt keturi;'),
  (@b16, 7, 13, 'Zatuvo vaikų: aštuoni šimtai keturiasdešimt penki;'),
  (@b16, 7, 14, 'Zakajo vaikų: septyni šimtai šešiasdešimt;'),
  (@b16, 7, 15, 'Binujo vaikų: šeši šimtai keturiasdešimt aštuoni;'),
  (@b16, 7, 16, 'Bebajo vaikų: šeši šimtai dvidešimt aštuoni;'),
  (@b16, 7, 17, 'Azgado vaikų: du tūkstančiai trys šimtai dvidešimt du;'),
  (@b16, 7, 18, 'Adonikamo vaikų: šeši šimtai šešiasdešimt septyni;'),
  (@b16, 7, 19, 'Bigvajo vaikų: du tūkstančiai šešiasdešimt septyni;'),
  (@b16, 7, 20, 'Adino vaikų: šeši šimtai penkiasdešimt penki;'),
  (@b16, 7, 21, 'Atero vaikų iš Chezekijo: devyniasdešimt aštuoni;'),
  (@b16, 7, 22, 'Hašumo vaikų: trys šimtai dvidešimt aštuoni;'),
  (@b16, 7, 23, 'Becajo vaikų: trys šimtai dvidešimt keturi;'),
  (@b16, 7, 24, 'Harifo vaikų: šimtas dvylika;'),
  (@b16, 7, 25, 'Gibeono vaikų: devyniasdešimt penki;'),
  (@b16, 7, 26, 'Betliejaus ir Netofos žmonių: šimtas aštuoniasdešimt aštuoni;'),
  (@b16, 7, 27, 'Anatoto žmonių: šimtas dvidešimt aštuoni;'),
  (@b16, 7, 28, 'Bet-Azmaveto žmonių: keturiasdešimt du;'),
  (@b16, 7, 29, 'Kirjat-Jearimo, Kefyros ir Beeroto žmonių: septyni šimtai keturiasdešimt trys;'),
  (@b16, 7, 30, 'Ramos ir Gebos žmonių: šeši šimtai dvidešimt vienas;'),
  (@b16, 7, 31, 'Michmaso žmonių: šimtas dvidešimt du;'),
  (@b16, 7, 32, 'Bet-Elio ir Ajo žmonių: šimtas dvidešimt trys;'),
  (@b16, 7, 33, 'kito Nebojo žmonių: penkiasdešimt du;'),
  (@b16, 7, 34, 'kito Elamo vaikų: tūkstantis du šimtai penkiasdešimt keturi;'),
  (@b16, 7, 35, 'Harimo vaikų: trys šimtai dvidešimt;'),
  (@b16, 7, 36, 'Jericho vaikų: trys šimtai keturiasdešimt penki;'),
  (@b16, 7, 37, 'Lodo, Hadido ir Onojo vaikų: septyni šimtai dvidešimt vienas;'),
  (@b16, 7, 38, 'Senavos vaikų: trys tūkstančiai devyni šimtai trisdešimt.'),
  (@b16, 7, 39, 'Kunigų: Jedajos vaikų iš Jėzuės namų: devyni šimtai septyniasdešimt trys;'),
  (@b16, 7, 40, 'Imero vaikų: tūkstantis penkiasdešimt du;'),
  (@b16, 7, 41, 'Pašchūro vaikų: tūkstantis du šimtai keturiasdešimt septyni;'),
  (@b16, 7, 42, 'Harimo vaikų: tūkstantis septyniolika;'),
  (@b16, 7, 43, 'levitų: Jėzuės vaikų iš Kadmielio, ir iš Hodvos vaikų: septyniasdešimt keturi.'),
  (@b16, 7, 44, 'Giesmininkų: Asafo vaikų: šimtas keturiasdešimt aštuoni.'),
  (@b16, 7, 45, 'Durininkų: Šalumo vaikų, Atero vaikų, Talmono vaikų, Akubo vaikų, Hatitos vaikų, Šobajo vaikų: šimtas trisdešimt aštuoni.'),
  (@b16, 7, 46, 'Netinimai: Cihos vaikai, Hašufos vaikai, Tabaoto vaikai,'),
  (@b16, 7, 47, 'Keroso vaikai, Sijos vaikai, Padono vaikai,'),
  (@b16, 7, 48, 'Lebanos vaikai, Hagabos vaikai, Šalmajo vaikai,'),
  (@b16, 7, 49, 'Hanano vaikai, Gidelio vaikai, Gaharo vaikai,'),
  (@b16, 7, 50, 'Reajos vaikai, Recino vaikai, Nekodos vaikai,'),
  (@b16, 7, 51, 'Gazamo vaikai, Uzos vaikai, Paseacho vaikai,'),
  (@b16, 7, 52, 'Besajo vaikai, meunų vaikai, nefišų vaikai,'),
  (@b16, 7, 53, 'Bakbuko vaikai, Hakufos vaikai, Harhūro vaikai,'),
  (@b16, 7, 54, 'Baclito vaikai, Mehidos vaikai, Haršos vaikai,'),
  (@b16, 7, 55, 'Barkoso vaikai, Siseros vaikai, Temacho vaikai,'),
  (@b16, 7, 56, 'Neciacho vaikai, Hatifos vaikai.'),
  (@b16, 7, 57, 'Saliamono tarnų vaikai: Sotajo vaikai, Sofereto vaikai, Peridos vaikai,'),
  (@b16, 7, 58, 'Jaalos vaikai, Darkono vaikai, Gidelio vaikai,'),
  (@b16, 7, 59, 'Šefatijos vaikai, Hatilo vaikai, Pochereto iš Cebaimo vaikai, Amono vaikai.'),
  (@b16, 7, 60, 'Iš viso netinimų ir Saliamono tarnų vaikų buvo trys šimtai devyniasdešimt du.'),
  (@b16, 7, 61, 'O šitie buvo tie, kurie irgi ėjo aukštyn iš Tel-Melacho, Tel-Harešos, Kerubo, Adono ir Imero; bet jie negalėjo parodyti nei savo tėvo namų, nei savo sėklos, ar jie yra iš Izraelio:'),
  (@b16, 7, 62, 'Delajos vaikai, Tobijos vaikai, Nekodos vaikai – šeši šimtai keturiasdešimt du.'),
  (@b16, 7, 63, 'O iš kunigų: Habajos vaikai, Koco vaikai, vaikai Barzilajaus, kuris buvo paėmęs į žmonas vieną iš gileadiečio Barzilajaus dukterų ir buvo pavadintas jų vardu.'),
  (@b16, 7, 64, 'Šitie ieškojo savo sąrašo tarp suskaičiuotųjų pagal genealogiją, bet jis nebuvo rastas; todėl jie buvo atskirti nuo kunigystės kaip susiteršę.'),
  (@b16, 7, 65, 'Ir Tiršata jiems sakė, kad jie nevalgytų to, kas švenčiausia, kol pakils kunigas su Urimu ir Tumimu.'),
  (@b16, 7, 66, 'Visas susirinkimas kartu buvo keturiasdešimt du tūkstančiai trys šimtai šešiasdešimt,'),
  (@b16, 7, 67, 'neskaitant jų tarnų ir jų tarnaičių, kurių buvo septyni tūkstančiai trys šimtai trisdešimt septyni; ir jie turėjo giesmininkų ir giesmininkių du šimtus keturiasdešimt penkis.'),
  (@b16, 7, 68, 'Jų žirgų – septyni šimtai trisdešimt šeši; jų mulų – du šimtai keturiasdešimt penki;'),
  (@b16, 7, 69, 'jų kupranugarių – keturi šimtai trisdešimt penki; asilų – šeši tūkstančiai septyni šimtai dvidešimt.'),
  (@b16, 7, 70, 'Ir kai kurie tėvų vyriausieji davė darbui. Tiršata davė iždui tūkstantį drachmų aukso, penkiasdešimt taurių ir penkis šimtus trisdešimt kunigų apdarų.'),
  (@b16, 7, 71, 'O kai kurie tėvų vyriausieji davė darbo iždui dvidešimt tūkstančių drachmų aukso ir du tūkstančius du šimtus svarų sidabro.'),
  (@b16, 7, 72, 'O tai, ką davė likusi tauta, buvo dvidešimt tūkstančių drachmų aukso, du tūkstančiai svarų sidabro ir šešiasdešimt septyni kunigų apdarai.'),
  (@b16, 7, 73, 'Taigi kunigai, levitai, durininkai, giesmininkai, dalis tautos, netinimai ir visas Izraelis apsigyveno savo miestuose; o kai atėjo septintasis mėnuo, Izraelio vaikai buvo savo miestuose.'),
  (@b16, 8, 1, 'Ir visa tauta kaip vienas žmogus susirinko į gatvę, esančią prieš Vandens vartus; ir jie sakė raštininkui Ezrai atnešti knygą Mozės įstatymo, kurį VIEŠPATS buvo įsakęs Izraeliui.'),
  (@b16, 8, 2, 'Ir kunigas Ezra atnešė įstatymą prieš susirinkimą vyrų, moterų ir visų, kurie klausydamiesi gali suprasti, septintojo mėnesio pirmąją dieną.'),
  (@b16, 8, 3, 'Ir jis skaitė iš jos prieš gatvę, esančią prieš Vandens vartus, nuo ryto iki vidudienio vyrų, moterų ir galinčių suprasti akivaizdoje; ir visos tautos ausys buvo dėmesingos įstatymo knygai.'),
  (@b16, 8, 4, 'Ir raštininkas Ezra stovėjo ant medinės sakyklos, kurią buvo padarę tam tikslui; ir šalia jo, jo dešinėje, stovėjo Matitija, Šema, Anaja, Ūrija, Hilkija ir Maasėja; o jo kairėje – Pedaja, Mišaelis, Malkija, Hašumas, Hašbadana, Zacharija ir Mešulamas.'),
  (@b16, 8, 5, 'Ir Ezra atvėrė knygą visos tautos akyse (nes jis buvo aukščiau visos tautos); ir kai jis atvėrė ją, visa tauta atsistojo;'),
  (@b16, 8, 6, 'ir Ezra palaimino VIEŠPATĮ, didįjį Dievą. O visa tauta pakeldama rankas atsakė: „Amen, amen“; ir jie nulenkė galvas ir pagarbino VIEŠPATĮ veidais į žemę.'),
  (@b16, 8, 7, 'Taip pat Jėzuė, Banis, Šerebija, Jaminas, Akubas, Šabetajas, Hodija, Maasėja, Kelita, Azarija, Jozabadas, Hananas, Pelaja ir levitai davė tautai suprasti įstatymą; o tauta stovėjo savo vietose.'),
  (@b16, 8, 8, 'Taigi jie skaitė iš knygos, iš Dievo įstatymo, aiškiai, suteikdami prasmę, ir davė jiems suprasti, kas buvo skaitoma.'),
  (@b16, 8, 9, 'O Nehemijas, kuris yra Tiršata, kunigas ir raštininkas Ezra ir levitai, kurie mokė tautą, tarė visai tautai: „Šita diena yra šventa VIEŠPAČIUI, jūsų Dievui; neliūdėkite ir neverkite“. Nes visa tauta, išgirdusi įstatymo žodžius, verkė.'),
  (@b16, 8, 10, 'Tada jis jiems tarė: „Eikite sau, valgykite tai, kas riebu, gerkite tai, kas saldu, ir pasiųskite dalį tiems, kuriems nieko nėra paruošta; nes ši diena yra šventa mūsų Viešpačiui; ir neliūdėkite; nes VIEŠPATIES džiaugsmas yra jūsų stiprybė“.'),
  (@b16, 8, 11, 'Taigi levitai nuramino visą tautą, sakydami: „Tylėkite, nes ta diena yra šventa; ir nesisielokite“.'),
  (@b16, 8, 12, 'Ir visa tauta nuėjo sau valgyti, gerti, dalių siuntinėti ir didžiai linksmintis, nes jie suprato žodžius, kurie jiems buvo paskelbti.'),
  (@b16, 8, 13, 'O antrąją dieną pas raštininką Ezrą susirinko visos tautos tėvų vyriausieji, kunigai ir levitai, kad suprastų įstatymo žodžius.'),
  (@b16, 8, 14, 'Ir jie rado parašyta įstatyme, kurį VIEŠPATS buvo įsakęs per Mozę, kad Izraelio vaikai per septintojo mėnesio šventę turi gyventi pastogėse;'),
  (@b16, 8, 15, 'ir kad jie turi paskelbti ir pagarsinti visuose jų miestuose ir Jeruzalėje, sakydami: „Išeikite į kalną ir parsineškite alyvmedžio šakų, pušies šakų, mirtos šakų, palmių šakų ir tankių medžių šakų pastogėms padaryti, kaip yra parašyta“.'),
  (@b16, 8, 16, 'Taigi tauta išėjo ir jų parsinešė, ir pasidarė pastoges, kiekvienas ant savo namų stogo ir savo kiemuose, ir Dievo namų kiemuose, ir Vandens vartų gatvėje, ir Efraimo vartų gatvėje.'),
  (@b16, 8, 17, 'Ir visas iš nelaisvės sugrįžusiųjų susirinkimas pasidarė pastoges ir sėdėjo po pastogėmis; nes nuo Nūno sūnaus Jėzuės dienų iki tos dienos Izraelio vaikai nebuvo taip darę. Ir buvo labai didelis džiaugsmas.'),
  (@b16, 8, 18, 'Taip pat, diena iš dienos, nuo pirmos dienos iki paskutinės dienos skaitė iš Dievo įstatymo knygos. Ir jie šventė šventę septynias dienas; o aštuntąją dieną buvo iškilmingas susirinkimas, pagal paprotį.'),
  (@b16, 9, 1, 'Na, o šito mėnesio dvidešimt ketvirtąją dieną Izraelio vaikai susirinko pasninkaudami ir su ašutinėmis, ir žemėmis ant savęs.'),
  (@b16, 9, 2, 'Ir Izraelio sėkla atsiskyrė nuo visų svetimtaučių ir atsistoję išpažino savo nuodėmes bei savo tėvų neteisybes.'),
  (@b16, 9, 3, 'Ir stovėdami savo vietose, jie ketvirtadalį dienos skaitė iš VIEŠPATIES, savo Dievo, įstatymo knygos; o kitą ketvirtadalį jie išpažino ir garbino VIEŠPATĮ, savo Dievą.'),
  (@b16, 9, 4, 'Tada atsistojo ant laiptų iš levitų: Jėzuė ir Banis, Kadmielis, Šebanija, Būnis, Šerebija, Banis ir Kenanis – ir garsiu balsu šaukėsi VIEŠPATIES, savo Dievo.'),
  (@b16, 9, 5, 'Tada levitai: Jėzuė, Kadmielis, Banis, Hašabnėja, Šerebija, Hodija, Šebanija ir Petachija tarė: „Kelkitės, palaiminkite VIEŠPATĮ, savo Dievą per amžių amžius; palaimintas tebūna tavo šlovingas vardas, kuris yra išaukštintas virš visokio palaiminimo ir gyriaus“.'),
  (@b16, 9, 6, 'Tu, VIEŠPATIE, esi vienintelis; tu padarei dangų, dangų dangų su visa jų kariuomene, žemę ir visa, kas yra joje, jūras ir visa, kas yra jose, ir tu juos visus išlaikai; ir dangaus kariuomenė garbina tave.'),
  (@b16, 9, 7, 'Tu esi VIEŠPATS Dievas, kuris išsirinkai Abramą, jį išvedei iš kaldėjų Ūro ir jam davei Abraomo vardą;'),
  (@b16, 9, 8, 'ir radai jo širdį ištikimą tavo akivaizdoje, sudarei su juo sandorą, kad duosi kanaaniečių, hetitų, amoritų, perizų, jebusiečių ir girgašų šalį, kad ją duosi jo sėklai, ir įvykdei savo žodžius; nes tu esi teisus;'),
  (@b16, 9, 9, 'ir matei mūsų tėvų vargą Egipte ir išgirdai jų šauksmą prie Raudonosios jūros;'),
  (@b16, 9, 10, 'ir parodei ženklų ir stebuklų ant faraono ir visų jo tarnų, ir ant visos jo šalies tautos; nes žinojai, kad jie didžiavosi prieš juos. Taip tu įsigijai vardą, kaip yra šią dieną.'),
  (@b16, 9, 11, 'Ir padalijai jūrą jų akivaizdoje, kad jie perėjo per jūros vidurį sausuma; o jų persekiotojus įmetei į gelmes kaip akmenį į galingus vandenis.'),
  (@b16, 9, 12, 'Be to, debesies stulpu juos vedei dieną; o ugnies stulpu naktį, kad šviestum jiems kelyje, kuriuo jie turi eiti.'),
  (@b16, 9, 13, 'Taip pat tu nužengei ant Sinajaus kalno ir kalbėjai su jais iš dangaus, ir jiems davei teisingus teismus ir tikrus įstatymus, gerus įstatus ir įsakymus;'),
  (@b16, 9, 14, 'ir davei jiems pažinti savo šventąjį sabatą, įsakei jiems prisakymų, įstatų bei įstatymų per savo tarno Mozės ranką;'),
  (@b16, 9, 15, 'ir davei jiems duonos iš dangaus jų alkiui, ir išvedei vandenį jiems iš uolos jų troškuliui, ir jiems pažadėjai, kad jie įeis pasisavinti šalies, kurią prisiekei jiems duoti.'),
  (@b16, 9, 16, 'Bet jie ir mūsų tėvai elgėsi išdidžiai, užkietino savo sprandus ir neklausė tavo įsakymų,'),
  (@b16, 9, 17, 'atsisakė paklusti ir neatsiminė tavo stebuklų, kuriuos padarei jų tarpe; bet užkietino savo sprandus ir maištaudami paskyrė vadą, kad grįžtų į savo vergystę; bet tu esi Dievas, pasiruošęs atleisti, maloningas ir gailestingas, lėtas pykti ir didžiai geras, ir jų nepalikai.'),
  (@b16, 9, 18, 'Taip, kai jie pasidarė nulietą veršį ir sakė: „Šitas yra tavo Dievas, kuris tave išvedė aukštyn iš Egipto“, ir darė didelius kurstymus;'),
  (@b16, 9, 19, 'tačiau tu savo daugeriopais gailestingumais jų nepalikai dykumoje; debesies stulpas neatsitraukė nuo jų dieną, kad juos vestų kelyje; nei ugnies stulpas naktį, kad jiems parodytų šviesą ir kelią, kuriuo jie turi eiti.'),
  (@b16, 9, 20, 'Taip pat tu davei savo gerąją Dvasią jiems pamokyti ir nesulaikei savo manos nuo jų burnos, ir davei jiems vandens jų troškuliui.'),
  (@b16, 9, 21, 'Taip, keturiasdešimt metų juos išlaikei dykumoje, jog jiems nieko netrūko; jų drabužiai nepaseno, ir jų kojos nesutino.'),
  (@b16, 9, 22, 'Tu jiems dar davei karalystes bei tautas ir jas padalinai dalimis: taip jie pasisavino Sihono šalį, Hešbono karaliaus šalį ir Bašano karaliaus Ogo šalį.'),
  (@b16, 9, 23, 'Taip pat jų vaikus padauginai kaip dangaus žvaigždes ir juos įvedei į šalį, apie kurią pažadėjai jų tėvams, kad jie įeis jos pasisavinti.'),
  (@b16, 9, 24, 'Taip vaikai įėjo ir pasisavino tą šalį, ir tu jų akivaizdoje pavergei šalies gyventojus, kanaaniečius, ir juos padavei į jų rankas su jų karaliais ir šalies tautomis, kad jie pasielgtų su jais kaip jiems patinka.'),
  (@b16, 9, 25, 'Ir jie paėmė tvirtus miestus ir riebią žemę ir pasisavino namus, pilnus visokių gėrybių, iškastus šulinius, vynuogynus, alyvmedžių sodus ir gausybę vaismedžių; taigi jie valgė, pasisotino ir nutuko, ir gėrėjosi tavo dideliu gerumu.'),
  (@b16, 9, 26, 'Tačiau jie buvo nepaklusnūs ir maištavo prieš tave, ir numetė tavo įstatymą sau už nugarų, ir užmušė tavo pranašus, kurie liudijo prieš juos, kad juos sugrąžintų pas tave, ir jie darė didelius kurstymus.'),
  (@b16, 9, 27, 'Todėl tu juos atidavei į jų priešų rankas, kurie juos slėgė; ir savo vargo metu, kai jie šaukėsi tavęs, tu juos išgirdai iš dangaus; ir pagal savo daugeriopus gailestingumus jiems davei gelbėtojus, kurie juos išgelbėjo iš jų priešų rankos.'),
  (@b16, 9, 28, 'Bet kai tik jie turėdavo poilsį, jie vėl darydavo pikta tavo akivaizdoje; todėl tu juos palikdavai jų priešų rankoje, kad jie jiems viešpatavo; tačiau kai jie sugrįždavo ir šaukdavosi tavęs, tu išgirsdavai juos iš dangaus; ir daug kartų juos išgelbėdavai pagal savo gailestingumus;'),
  (@b16, 9, 29, 'ir prieš juos liudydavai, kad juos sugrąžintum prie savo įstatymo; tačiau jie išdidžiai elgdavosi ir neklausydavo tavo įsakymų, bet nusidėdavo prieš tavo teismus (kuriuos, jei žmogus vykdys, jais gyvens) ir atitraukė petį, ir užkietino savo sprandą, ir neklausė.'),
  (@b16, 9, 30, 'Nors daugelį metų tu juos pakentei ir prieš juos liudydavai per savo Dvasią savo pranašuose; tačiau jie neatsukdavo ausies; todėl juos atiduodavai į šalių tautų rankas.'),
  (@b16, 9, 31, 'Tačiau dėl savo didžių gailestingumų tu jų nesunaikinai visiškai ir jų nepalikai; nes tu esi maloningas ir gailestingas Dievas.'),
  (@b16, 9, 32, 'Todėl dabar, mūsų Dieve, didysis, galingasis ir baisusis Dieve, kuris laikaisi sandoros ir gailestingumo, teneatrodo tavo akivaizdoje mažas visas tas vargas, kuris ištiko mus, mūsų karalius, mūsų kunigaikščius, mūsų kunigus, mūsų pranašus, mūsų tėvus ir visą tavo tautą nuo Asirijos karalių laikų iki šios dienos.'),
  (@b16, 9, 33, 'Tačiau tu esi teisus visame tame, kas ant mūsų yra užleista; nes tu darei teisingai, bet mes nedorai elgėmės;'),
  (@b16, 9, 34, 'nei mūsų karaliai, nei mūsų kunigaikščiai, nei mūsų kunigai, nei mūsų tėvai nesilaikė tavo įstatymo ir neklausė tavo įsakymų bei tavo liudijimų, kuriais tu prieš juos liudijai.'),
  (@b16, 9, 35, 'Nes jie tau netarnavo savo karalystėje ir tavo dideliame gerume, kurį jiems davei, ir plačioje bei riebioje šalyje, kurią davei jų akivaizdoje, ir jie nenusigręžė nuo savo piktų darbų.'),
  (@b16, 9, 36, 'Štai mes šią dieną esame tarnai, o dėl šalies, kurią davei mūsų tėvams, kad valgytų jos vaisius ir jos gėrybes, štai mes esame tarnai joje;'),
  (@b16, 9, 37, 'ir ji davė gausų prieaugį karaliams, kuriuos paskyrei mus valdyti dėl mūsų nuodėmių; taip pat jie viešpatauja mūsų kūnams ir mūsų galvijams, kaip jiems patinka, o mes esame dideliame suspaudime.'),
  (@b16, 9, 38, 'Ir dėl viso to mes darome tvirtą sandorą ir ją užrašome; o mūsų kunigaikščiai, levitai ir kunigai ją užantspauduoja“.'),
  (@b16, 10, 1, 'Na, o užantspaudavo šitie: Nehemijas – Tiršata, Hachalijos sūnus ir Zidkija,'),
  (@b16, 10, 2, 'Seraja, Azarija, Jeremijas,'),
  (@b16, 10, 3, 'Pašchūras, Amarija, Malkija,'),
  (@b16, 10, 4, 'Hatušas, Šebanija, Maluchas,'),
  (@b16, 10, 5, 'Harimas, Meremotas, Abdijas,'),
  (@b16, 10, 6, 'Danielius, Ginetonas, Baruchas,'),
  (@b16, 10, 7, 'Mešulamas, Abija, Mijaminas,'),
  (@b16, 10, 8, 'Maazija, Bilgajas, Šemaja: šitie buvo kunigai.'),
  (@b16, 10, 9, 'O levitai: Azanijos sūnus Jėzuė, Binujas iš Henadado sūnų, Kadmielis;'),
  (@b16, 10, 10, 'o jų broliai: Šebanija, Hodija, Kelita, Pelaja, Hananas,'),
  (@b16, 10, 11, 'Mika, Rehobas, Hašabija,'),
  (@b16, 10, 12, 'Zakūras, Šerebija, Šebanija,'),
  (@b16, 10, 13, 'Hodija, Banis, Beninuvas.'),
  (@b16, 10, 14, 'Tautos vyriausieji: Parošas, Pahat-Moabas, Elamas, Zatuvas, Banis,'),
  (@b16, 10, 15, 'Būnis, Azgadas, Bebajas,'),
  (@b16, 10, 16, 'Adonija, Bigvajas, Adinas,'),
  (@b16, 10, 17, 'Ateras, Chizkija, Azūras,'),
  (@b16, 10, 18, 'Hodija, Hašumas, Becajas,'),
  (@b16, 10, 19, 'Harifas, Anatotas, Nebajas,'),
  (@b16, 10, 20, 'Magpiašas, Mešulamas, Hezyras,'),
  (@b16, 10, 21, 'Mešezabelis, Cadokas, Jadūva,'),
  (@b16, 10, 22, 'Pelatija, Hananas, Anaja,'),
  (@b16, 10, 23, 'Ozėja, Hananija, Hašubas,'),
  (@b16, 10, 24, 'Halohešas, Pilha, Šobekas,'),
  (@b16, 10, 25, 'Rehumas, Hašabna, Maasėja,'),
  (@b16, 10, 26, 'ir Ahija, Hananas, Ananas,'),
  (@b16, 10, 27, 'Maluchas, Harimas, Baana.'),
  (@b16, 10, 28, 'Ir likusi tauta, kunigai, levitai, durininkai, giesmininkai, netinimai ir visi, kurie buvo atsiskyrę nuo šalių tautų prie Dievo įstatymo, jų žmonos, jų sūnūs ir jų dukterys, kiekvienas turintis pažinimą ir turintis supratimą;'),
  (@b16, 10, 29, 'jie prilipo prie savo brolių, savo kilniųjų, ir įstojo į prakeikimą ir į priesaiką, kad vaikščios pagal Dievo įstatymą, kuris buvo duotas per Dievo tarną Mozę, ir kad laikysis bei vykdys visus VIEŠPATIES, mūsų Viešpaties, įsakymus, jo teismus ir jo įstatus;'),
  (@b16, 10, 30, 'ir kad mes neduosime savo dukterų tos šalies tautoms ir jų dukterų neimsime savo sūnums;'),
  (@b16, 10, 31, 'ir jei tos šalies tautos sabato dieną atgabens prekių ar kokio maisto parduoti, tai mes to iš jų nepirksime per sabatą ar per šventąją dieną; ir kad paliksime septintuosius metus ir bet kokios skolos išreikalavimą.'),
  (@b16, 10, 32, 'Taip pat paskyrėme sau potvarkių, kad įsipareigotume kas metai trečdaliu šekelio savo Dievo namų tarnavimui;'),
  (@b16, 10, 33, 'parodomajai duonai, nuolatinei maisto atnašai ir sabatų bei jauno mėnulio nuolatinei deginamajai atnašai dėl nustatytų švenčių, ir šventiesiems dalykams, ir nuodėmės atnašoms, atlikti sutaikinimui už Izraelį, ir visam mūsų Dievo namų darbui.'),
  (@b16, 10, 34, 'Ir mes metėme burtus tarp kunigų, levitų ir tautos dėl malkų atnašavimo, kad jas atgabentume į mūsų Dievo namus pagal savo tėvų namus, nustatytais laikais, kasmet – deginti ant VIEŠPATIES, mūsų Dievo, aukuro, kaip yra parašyta įstatyme;'),
  (@b16, 10, 35, 'ir kad kasmet atgabentume į VIEŠPATIES namus savo dirvos pirmavaisius ir visų medžių visų vaisių pirmavaisius;'),
  (@b16, 10, 36, 'taip pat, kad į savo Dievo namus pristatytume savo sūnų ir savo galvijų pirmagimius, kaip yra parašyta įstatyme, ir savo bandų bei savo kaimenių pirmagimius kunigams, tarnaujantiems mūsų Dievo namuose;'),
  (@b16, 10, 37, 'ir kad mūsų tešlos pirmavaisius, mūsų atnašas ir visokių medžių, vyno ir aliejaus vaisius mes atneštume kunigams į mūsų Dievo namų kambarius; o mūsų dirvos dešimtines – levitams, kad tie levitai turėtų dešimtines visuose mūsų dirbamos žemės miestuose.'),
  (@b16, 10, 38, 'O levitams renkant dešimtines, Aarono sūnus kunigas turi būti su levitais; ir levitai gabens dešimtinių dešimtinę į mūsų Dievo namus, į kambarius, į iždinę.'),
  (@b16, 10, 39, 'Nes Izraelio vaikai ir Levio vaikai atneš javų, jauno vyno ir aliejaus atnašą į kambarius, kur yra šventovės indai, tarnaujantys kunigai, durininkai ir giesmininkai; ir mes neapleisime mūsų Dievo namų.'),
  (@b16, 11, 1, 'Ir tautos valdovai apsigyveno Jeruzalėje; tautos likusieji taip pat metė burtus, kad vieną iš dešimties atvestų apsigyventi Jeruzalėje, šventajame mieste, o devynias dalis apsigyventi kituose miestuose.'),
  (@b16, 11, 2, 'Ir tauta laimino visus žmones, noriai pasiaukojusius gyventi Jeruzalėje.'),
  (@b16, 11, 3, 'Na, o šitie yra provincijos vyriausieji, gyvenantys Jeruzalėje; bet Judos miestuose kiekvienas gyveno savo nuosavybėje, savo miestuose, būtent Izraelis, kunigai, levitai, netinimai ir Saliamono tarnų vaikai.'),
  (@b16, 11, 4, 'O Jeruzalėje gyveno kai kurie iš Judos vaikų ir iš Benjamino vaikų. Iš Judos vaikų: Ataja – sūnus Uzijo, sūnus Zacharijos, sūnus Amarijos, sūnus Šefatijos, sūnus Malaleelio iš Pereso vaikų;'),
  (@b16, 11, 5, 'ir Maasėja – sūnus Barucho, sūnus Kol-Hozės, sūnus Hazajos, sūnus Adajos, sūnus Jojaribo, sūnus Zacharijos, sūnus Šilonio.'),
  (@b16, 11, 6, 'Iš viso Pereso sūnų, gyvenusių Jeruzalėje, buvo keturi šimtai šešiasdešimt aštuoni narsūs vyrai.'),
  (@b16, 11, 7, 'O šitie yra Benjamino sūnūs: Saluvas – sūnus Mešulamo, sūnus Joedo, sūnus Pedajos, sūnus Kolajos, sūnus Maasėjos, sūnus Itielio, sūnus Jesajos.'),
  (@b16, 11, 8, 'O po jo Gabajas ir Salajas – devyni šimtai dvidešimt aštuoni.'),
  (@b16, 11, 9, 'O Zichrio sūnus Joelis buvo jų prižiūrėtojas; o Senūvos sūnus Juda buvo antrasis miesto valdyme.'),
  (@b16, 11, 10, 'Iš kunigų: Jojaribo sūnus Jedaja, Jachinas.'),
  (@b16, 11, 11, 'Seraja – sūnus Hilkijos, sūnus Mešulamo, sūnus Cadoko, sūnus Merajoto, sūnus Ahitubo, – buvo Dievo namų valdovas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b16, 11, 12, 'O jų brolių, atliekančių namų darbą, buvo aštuoni šimtai dvidešimt du; ir Adaja – sūnus Jerohamo, sūnus Pelalijos, sūnus Amcio, sūnus Zacharijos, sūnus Pašchūro, sūnus Malkijos,'),
  (@b16, 11, 13, 'o jo brolių, tėvų vyriausiųjų – du šimtai keturiasdešimt du; ir Amašajas – sūnus Azarelio, sūnus Achzajo, sūnus Mešilemoto, sūnus Imero,'),
  (@b16, 11, 14, 'o jų brolių, galingų narsuolių – šimtas dvidešimt aštuoni; o jų prižiūrėtojas buvo Zabdielis, vieno iš didžiūnų sūnus.'),
  (@b16, 11, 15, 'Taip pat iš levitų: Šemajas – sūnus Hašubo, sūnus Azrikamo, sūnus Hašabijos, sūnus Būnio;'),
  (@b16, 11, 16, 'o Šabetajas ir Jozabadas, iš levitų vyriausiųjų, prižiūrėjo Dievo namų išorinius darbus.'),
  (@b16, 11, 17, 'O Matanija – sūnus Michos, sūnus Zabdžio, sūnus Asafo, – buvo vadovas, kad pradėtų maldoje padėką; ir Bakbukija, antrasis tarp savo brolių, ir Abda – sūnus Šamūvos, sūnus Galalo, sūnus Jedutūno.'),
  (@b16, 11, 18, 'Iš viso levitų šventajame mieste buvo du šimtai aštuoniasdešimt keturi.'),
  (@b16, 11, 19, 'Be to, durininkai: Akubas, Talmonas ir jų broliai, saugojantys vartus – šimtas septyniasdešimt du.'),
  (@b16, 11, 20, 'O Izraelio, kunigų ir levitų likutis buvo visuose Judos miestuose, kiekvienas savo pavelde.'),
  (@b16, 11, 21, 'Bet netinimai gyveno Ofelyje; o Ciha ir Gišpa buvo netinimų vadovai.'),
  (@b16, 11, 22, 'Levitų prižiūrėtojas Jeruzalėje buvo Uzis, sūnus Banio, sūnaus Hašabijos, sūnaus Matanijos, sūnaus Michos. Iš Asafo sūnų, giesmininkai vadovavo Dievo namų reikalams.'),
  (@b16, 11, 23, 'Nes tai buvo karaliaus įsakymas dėl jų, kad tam tikra dalis turi būti giesmininkams, kas priklauso kiekvienai dienai.'),
  (@b16, 11, 24, 'Ir Mešezabelio sūnus Petachija, iš Judos sūnaus Zeracho vaikų, buvo karaliui prie rankos visuose reikaluose dėl tautos.'),
  (@b16, 11, 25, 'O dėl kaimų su jų laukais: kai kurie iš Judos vaikų gyveno Kirjat-Arboje ir jos kaimuose, Dibone ir jo kaimuose, Jekabceelyje ir jo kaimuose,'),
  (@b16, 11, 26, 'Jėzuėje, Moladoje, Bet-Pelete,'),
  (@b16, 11, 27, 'Hacar-Šuale, Beer-Šeboje ir jos kaimuose,'),
  (@b16, 11, 28, 'Ciklage, Mekonoje ir jos kaimuose,'),
  (@b16, 11, 29, 'En-Rimone, Caroje, Jarmute,'),
  (@b16, 11, 30, 'Zanoache, Adulame ir jų kaimuose, Lachiše ir jo laukuose, Azekoje ir jos kaimuose. Ir jie gyveno nuo Beer-Šebos iki Hinomo slėnio.'),
  (@b16, 11, 31, 'Taip pat Benjamino vaikai iš Gebos gyveno Michmaše, Ajyje, Bet-Elyje ir jų kaimuose,'),
  (@b16, 11, 32, 'ir Anatote, Nobe, Ananijoje,'),
  (@b16, 11, 33, 'Hacore, Ramoje, Gitaime,'),
  (@b16, 11, 34, 'Hadide, Ceboime, Nebalate,'),
  (@b16, 11, 35, 'Lode ir Onojuje, Amatininkų slėnyje.'),
  (@b16, 11, 36, 'Ir iš levitų buvo padalijimai Judoje ir Benjamine.'),
  (@b16, 12, 1, 'Na, o šitie yra kunigai ir levitai, kurie ėjo aukštyn su Šealtielio sūnumi Zerubabeliu ir Jėzue: Seraja, Jeremijas, Ezra,'),
  (@b16, 12, 2, 'Amarija, Maluchas, Hatušas,'),
  (@b16, 12, 3, 'Šechanija, Rehumas, Meremotas,'),
  (@b16, 12, 4, 'Idojas, Ginetonas, Abija,'),
  (@b16, 12, 5, 'Mijaminas, Maadija, Bilga,'),
  (@b16, 12, 6, 'Šemaja ir Jojaribas, Jedaja,'),
  (@b16, 12, 7, 'Saluvas, Amokas, Hilkija, Jedajas. Šitie buvo kunigų ir jų brolių vyriausieji Jėzuės dienomis.'),
  (@b16, 12, 8, 'Be to, levitai: Jėzuė, Binujas, Kadmielis, Šerebija, Juda ir Matanija, kuris vadovavo dėkojimui, jis ir jo broliai.'),
  (@b16, 12, 9, 'Taip pat Bakbukijas ir Unis, jų broliai, buvo priešais juos sargybose.'),
  (@b16, 12, 10, 'O Jėzuė pagimdė Jojakimą, Jojakimas pagimdė Eljašibą, o Eljašibas pagimdė Jojadą,'),
  (@b16, 12, 11, 'o Jojada pagimdė Jonataną, o Jonatanas pagimdė Jadūvą.'),
  (@b16, 12, 12, 'Ir Jojakimo dienomis buvo kunigai, tėvų vyriausieji: iš Serajos – Meraja, iš Jeremijo – Hananija,'),
  (@b16, 12, 13, 'iš Ezros – Mešulamas, iš Amarijo – Jehohananas,'),
  (@b16, 12, 14, 'iš Malichuvo – Jonatanas, iš Šebanijo – Juozapas,'),
  (@b16, 12, 15, 'iš Harimo – Adna, iš Merajoto – Helkajas,'),
  (@b16, 12, 16, 'iš Idojo – Zacharija, iš Ginetono – Mešulamas,'),
  (@b16, 12, 17, 'iš Abijos – Zichris, iš Minjamino, iš Moadijos – Piltajas,'),
  (@b16, 12, 18, 'iš Bilgos – Šamūva, iš Šemajo – Jehonatanas,'),
  (@b16, 12, 19, 'iš Jojaribo – Matenajas, iš Jedajos – Uzis,'),
  (@b16, 12, 20, 'iš Salajo – Kalajas, iš Amoko – Eberas,'),
  (@b16, 12, 21, 'iš Hilkijos – Hašabija, iš Jedajos – Netanelis.'),
  (@b16, 12, 22, 'Eljašibo, Jojados, Johanano ir Jadūvos dienomis levitai buvo surašyti tėvų vyriausiais, taip pat ir kunigai, perso Darijaus karaliavimui.'),
  (@b16, 12, 23, 'Levio sūnūs, tėvų vyriausieji, buvo surašyti kronikų knygoje iki Eljašibo sūnaus Johanano dienų.'),
  (@b16, 12, 24, 'Levitų vyriausieji: Hašabija, Šerebija ir Kadmielio sūnus Jėzuė su savo broliais priešais juos, kad girtų ir dėkotų pagal Dievo vyro Dovydo įsakymą, sargyba priešais sargybą.'),
  (@b16, 12, 25, 'Matanija ir Bakbukija, Abdijas, Mešulamas, Talmonas ir Akubas buvo durininkai, einantys sargybą prie vartų slenksčių.'),
  (@b16, 12, 26, 'Šitie buvo Jocadako sūnaus Jėzuės sūnaus Jojakimo dienomis ir valdytojo Nehemijo bei kunigo Ezros, raštininko, dienomis.'),
  (@b16, 12, 27, 'Ir pašvenčiant Jeruzalės sieną ieškojo levitų visose jų vietose, kad juos atvestų į Jeruzalę, kad atliktų pašventimą su džiaugsmu, su padėkomis ir su giesmėmis, su cimbolais, psalteriais ir arfomis.'),
  (@b16, 12, 28, 'Ir giesmininkų sūnūs susirinko tiek iš lygumos krašto aplink Jeruzalę, tiek iš netofiečių kaimų;'),
  (@b16, 12, 29, 'taip pat iš Gilgalo namų ir iš Gebos bei Azmaveto laukų; nes giesmininkai buvo pasistatę kaimų aplink Jeruzalę.'),
  (@b16, 12, 30, 'O kunigai ir levitai apsivalė, apvalė tautą, vartus ir sieną.'),
  (@b16, 12, 31, 'Tada aš atvedžiau aukštyn Judos kunigaikščius ant sienos ir paskyriau du didelius dėkojančiųjų būrius, kurių vienas ėjo dešinėje sienos viršumi, Mėšlo vartų link;'),
  (@b16, 12, 32, 'o paskui juos ėjo Hošaja ir pusė Judos kunigaikščių,'),
  (@b16, 12, 33, 'ir Azanija, Ezra ir Mešulamas,'),
  (@b16, 12, 34, 'Juda, Benjaminas, Šemaja, Jeremijas'),
  (@b16, 12, 35, 'ir kai kurie iš kunigų sūnų su trimitais, būtent Zacharija – sūnus Jonatano, sūnus Šemajos, sūnus Matanijos, sūnus Michajo, sūnus Zakūro, sūnus Asafo;'),
  (@b16, 12, 36, 'ir jo broliai: Šemaja ir Azarelis, Milalajas, Gilalajas, Maajas, Netanelis ir Juda, Hananis su Dievo vyro Dovydo muzikiniais instrumentais, o raštininkas Ezra jų priekyje.'),
  (@b16, 12, 37, 'Ir prie Šaltinio vartų, esančių priešais juos, jie lipo aukštyn Dovydo miesto laiptais sienos pakyla, viršuje Dovydo namų, iki Vandens vartų rytuose.'),
  (@b16, 12, 38, 'O kitas dėkojančiųjų būrys ėjo priešais juos, ir aš paskui juos su puse tautos sienos viršumi iš anapus Krosnių bokšto iki Plačiosios sienos;'),
  (@b16, 12, 39, 'ir nuo viršaus Efraimo vartų, nuo viršaus Senųjų vartų, nuo viršaus Žuvų vartų, Hananelio bokšto ir Mejos bokšto iki Avių vartų; ir jie sustojo kalėjimo vartuose.'),
  (@b16, 12, 40, 'Taigi abu dėkojančiųjų būriai sustojo Dievo namuose ir aš bei pusė valdovų su manimi;'),
  (@b16, 12, 41, 'ir kunigai: Eljakimas, Maasėja, Minjaminas, Mikaja, Eljoenajas, Zacharija ir Hananija su trimitais;'),
  (@b16, 12, 42, 'ir Maasėja, Šemaja, Eleazaras, Uzis, Jehohananas, Malkija, Elamas ir Ezeras. O giesmininkai su savo prižiūrėtoju Jezrachija garsiai giedojo.'),
  (@b16, 12, 43, 'Taip pat tą dieną jie atnašavo dideles aukas ir džiaugėsi; nes Dievas juos buvo pradžiuginęs dideliu džiaugsmu; taip pat žmonos ir vaikai džiaugėsi; taip, kad Jeruzalės džiaugsmas girdėjosi iš toli.'),
  (@b16, 12, 44, 'Ir tuo metu kai kurie buvo paskirti prižiūrėti kambarius lobiams, atnašoms, pirmavaisiams ir dešimtinėms, kad į juos iš miestų laukų surinktų įstatymo dalį kunigams bei levitams; nes Juda džiaugėsi dėl kunigų ir levitų, kurie tarnavo.'),
  (@b16, 12, 45, 'Ir tiek giesmininkai, tiek durininkai ėjo savo Dievo sargybą ir apvalymo sargybą pagal Dovydo ir jo sūnaus Saliamono įsakymą.'),
  (@b16, 12, 46, 'Nes nuo seno, Dovydo ir Asafo dienomis, buvo giesmininkų vyresnieji ir gyriaus bei padėkos giesmės Dievui.'),
  (@b16, 12, 47, 'O Zerubabelio dienomis ir Nehemijo dienomis visas Izraelis davė giesmininkų ir durininkų dalį, kasdienę jų dalį; ir jie pašventė šventus dalykus levitams; o levitai juos pašventė Aarono vaikams.'),
  (@b16, 13, 1, 'Tą dieną, tautai klausantis, skaitė iš Mozės knygos; o joje buvo rasta parašyta, kad joks amonietis ir moabietis niekada teneįeina į Dievo susirinkimą;'),
  (@b16, 13, 2, 'nes jie nepasitiko Izraelio vaikų su duona ir vandeniu, bet pasamdė prieš juos Balaamą, kad jis juos prakeiktų; tačiau mūsų Dievas prakeikimą pakeitė į palaiminimą.'),
  (@b16, 13, 3, 'Na, o įvyko, kad išklausę įstatymą jie atskyrė nuo Izraelio visą mišrią daugybę.'),
  (@b16, 13, 4, 'O prieš tai kunigas Eljašibas, prižiūrintis mūsų Dievo namų kambarius, buvo Tobijos giminaitis;'),
  (@b16, 13, 5, 'ir buvo jam paruošęs didelį kambarį, kur anksčiau sudėdavo maisto atnašas, smilkalus, indus ir javų, jauno vyno bei aliejaus dešimtines, įsakytas duoti levitams, giesmininkams ir durininkams; ir kunigų atnašas.'),
  (@b16, 13, 6, 'Bet per visą tą laiką aš nebuvau Jeruzalėje; nes trisdešimt antraisiais Babilono karaliaus Artakserkso metais aš atėjau pas karalių ir po kiek tai dienų gavau iš karaliaus leidimą;'),
  (@b16, 13, 7, 'ir, atvykęs į Jeruzalę, sužinojau apie pikta, kurį Eljašibas padarė Tobijai, paruošdamas jam kambarį Dievo namų kiemuose.'),
  (@b16, 13, 8, 'Ir mane tai labai liūdino; todėl aš išmečiau laukan iš kambario visus Tobijos namų daiktus.'),
  (@b16, 13, 9, 'Paskui įsakiau, ir jie apvalė kambarius; ir ten atgal sunešiau Dievo namų indus su maisto atnaša ir smilkalais.'),
  (@b16, 13, 10, 'Ir sužinojau, kad levitų dalis jiems nebuvo duota; nes levitai ir giesmininkai, atliekantys darbą, buvo pabėgę kiekvienas į savo lauką.'),
  (@b16, 13, 11, 'Tada ginčijausi su valdovais ir sakiau: „Kodėl apleisti Dievo namai?“ Ir juos surinkau ir pastačiau į jų vietą.'),
  (@b16, 13, 12, 'Tada visa Juda atnešė į lobynus javų, jauno vyno ir aliejaus dešimtines.'),
  (@b16, 13, 13, 'Ir aš paskyriau lobynams saugotojais kunigą Šelemiją, raštininką Cadoką ir Pedają iš levitų; o po jų buvo Matanijos sūnaus Zakūro sūnus Hananas; nes jie buvo laikomi ištikimais, ir jų tarnyba buvo išdalinti savo broliams.'),
  (@b16, 13, 14, 'Atsimink dėl šito mane, o mano Dieve, ir neištrink mano gerų darbų, kuriuos esu padaręs savo Dievo namams ir jų tarnyboms.'),
  (@b16, 13, 15, 'Tomis dienomis mačiau Judoje kai kuriuos, mindančius vyno spaustuvus per sabatą ir įnešančius pėdus, ir kraunančius ant asilų; taip pat vyną, vynuoges, figas ir visokias naštas, kurias jie per sabato dieną gabeno į Jeruzalę; ir aš liudijau prieš juos tą dieną, kai jie pardavinėjo maistą.'),
  (@b16, 13, 16, 'Ten joje gyveno ir Tyro žmonės, kurie atgabendavo žuvies bei visokių prekių ir per sabatą parduodavo Judos vaikams ir Jeruzalėje.'),
  (@b16, 13, 17, 'Tada aš vaidijausi su Judos kilmingaisiais ir jiems sakiau: „Kas tai per piktadarystė, kurią jūs darote ir suteršiate sabato dieną?'),
  (@b16, 13, 18, 'Argi taip nedarė jūsų tėvai ir argi mūsų Dievas neužleido ant mūsų ir ant šito miesto visos šitos nelaimės? Tačiau jūs, suteršdami sabatą, užtraukiate dar daugiau rūstybės Izraeliui“.'),
  (@b16, 13, 19, 'Ir įvyko, kai tik Jeruzalės vartai prieš sabatą pradėjo temti, aš įsakiau užrakinti vartus ir įpareigojau, kad jų neatidarytų iki po sabato; ir pastačiau kai kuriuos iš savo tarnų prie vartų, kad sabato dieną nebūtų įnešta jokia našta.'),
  (@b16, 13, 20, 'Taip pirkliai ir visokių prekių pardavėjai vieną ar du kartus nakvojo už Jeruzalės.'),
  (@b16, 13, 21, 'Tada aš liudijau prieš juos ir jiems pasakiau: „Kodėl nakvojate palei sieną? Jei vėl taip padarysite, aš uždėsiu ant jūsų rankas“. Nuo to laiko jie nebeateidavo per sabatą.'),
  (@b16, 13, 22, 'Ir aš įsakiau levitams, kad apsivalytų ir ateitų vartų saugoti, kad pašvęstų sabato dieną. Atsimink mane ir dėl šito, o mano Dieve, ir pasigailėk manęs pagal savo gailestingumo didybę.'),
  (@b16, 13, 23, 'Taip pat tomis dienomis mačiau žydus, kurie buvo vedę žmonas iš Ašdodo, iš Amono ir iš Moabo;'),
  (@b16, 13, 24, 'o jų vaikai kalbėjo pusiau Ašdodo kalba, ir nebemokėjo kalbėti žydų kalba, bet kiekvienos tautos kalba.'),
  (@b16, 13, 25, 'Ir aš vaidijausi su jais, keikiau juos, kai kuriuos sumušiau, roviau jų plaukus ir prisaikdinau juos Dievu, sakydamas: „Neduokite savo dukterų jų sūnums nei neimkite jų dukterų savo sūnums ar sau patiems.'),
  (@b16, 13, 26, 'Argi ne šitais dalykais nusidėjo Izraelio karalius Saliamonas? Nors tarp daugelio tautų nebuvo jam lygaus karaliaus; jis buvo savo Dievo mylimasis, ir Dievas jį padarė karaliumi visam Izraeliui; tačiau net jį svetimšalės moterys paskatino nusidėti.'),
  (@b16, 13, 27, 'Tad argi turėtume klausyti jūsų, kad darytume visą šitą didelę piktybę, kad nusižengtume prieš mūsų Dievą, vesdami svetimšales žmonas?“'),
  (@b16, 13, 28, 'Ir vienas iš aukščiausiojo kunigo Eljašibo sūnaus Jojados sūnų buvo horoniečio Sanbalato žentas; todėl aš jį išvariau nuo savęs.'),
  (@b16, 13, 29, 'Atsimink juos, o mano Dieve, nes jie suteršė kunigystę ir kunigystės bei levitų sandorą.'),
  (@b16, 13, 30, 'Taip juos apvaliau nuo visų svetimšalių ir paskyriau kunigų bei levitų sargybas, kiekvieną jo darbe;'),
  (@b16, 13, 31, 'ir dėl malkų atnašos nustatytais laikais, ir dėl pirmavaisių. Atsimink mane, o mano Dieve, dėl gero.'),
  (@b17, 1, 1, 'Na, o tai įvyko Ahasvero dienomis (tai tas Ahasveras, kuris karaliavo nuo Indijos iki Etiopijos šimtui dvidešimt septynioms provincijoms),'),
  (@b17, 1, 2, 'tomis dienomis, kai karalius Ahasveras sėdėjo savo karalystės soste, esančiame Šušano rūmuose,'),
  (@b17, 1, 3, 'trečiaisiais savo karaliavimo metais jis surengė puotą visiems savo kunigaikščiams ir tarnams; Persijos ir Medijos valdžiai, provincijų kilmingiesiems ir kunigaikščiams esantiems jo akivaizdoje;'),
  (@b17, 1, 4, 'kai jis daugelį dienų, būtent šimtą aštuoniasdešimt dienų, rodė savo šlovingos karalystės turtus ir savo puikios didybės garbę.'),
  (@b17, 1, 5, 'Ir toms dienoms pasibaigus, karalius suruošė visai tautai, esančiai Šušano rūmuose, tiek dideliems, tiek mažiems, septynių dienų puotą karaliaus rūmų sodo kieme;'),
  (@b17, 1, 6, 'ten buvo baltos, žalios ir mėlynos užuolaidos, prikabintos plono lino ir purpuro virvelėmis prie sidabrinių žiedų ir marmurinių stulpų; auksiniai ir sidabriniai gultai buvo ant raudono, mėlyno, balto ir juodo marmuro grindinio.'),
  (@b17, 1, 7, 'Ir davė jiems gerti auksiniuose induose (indai buvo skirtingi vienas nuo kito), ir karališko vyno gausiai, pagal karaliaus išgales.'),
  (@b17, 1, 8, 'Buvo geriama pagal įstatymą; niekas nevertė; nes taip karalius buvo nurodęs visiems savo namų pareigūnams, kad jie darytų pagal kiekvieno pageidavimą.'),
  (@b17, 1, 9, 'Taip pat karalienė Vaštė suruošė puotą moterims karališkuose namuose, priklausančiuose karaliui Ahasverui.'),
  (@b17, 1, 10, 'Septintąją dieną, kai karaliaus širdis buvo linksma nuo vyno, jis įsakė Mehumanui, Biztai, Harbonai, Bigtai ir Abagtai, Zetarui ir Karkasui, septyniems rūmininkams, tarnaujantiems karaliaus Ahasvero akivaizdoje,'),
  (@b17, 1, 11, 'atvesti karalienę Vaštę karaliaus akivaizdon su karališka karūna, kad parodytų tautoms ir kunigaikščiams jos grožį; nes ji buvo graži pažiūrėti.'),
  (@b17, 1, 12, 'Bet karalienė Vaštė nesutiko ateiti pagal karaliaus įsakymą per jo rūmininkus; todėl karalius labai užsirūstino, ir jo pyktis užsidegė jame.'),
  (@b17, 1, 13, 'Tada karalius tarė išminčiams, pažįstantiems laikus (nes toks buvo karaliaus būdas visiems žinantiems įstatymą ir teismą;'),
  (@b17, 1, 14, 'o šalia jo buvo Karšena, Šetaras, Admata, Taršišas, Meresas, Marsena ir Memuchanas, septyni Persijos ir Medijos kunigaikščiai, matantys karaliaus veidą ir sėdintys pirmi karalystėje):'),
  (@b17, 1, 15, '„Ką pagal įstatymą darysime karalienei Vaštei dėl to, kad ji nevykdė karaliaus Ahasvero įsakymo per rūmininkus?“'),
  (@b17, 1, 16, 'Ir Memuchanas atsakė karaliaus ir kunigaikščių akivaizdoje: „Karalienė Vaštė padarė blogai ne vien karaliui, bet ir visiems kunigaikščiams ir visoms tautoms, esančioms visose karaliaus Ahasvero provincijose.'),
  (@b17, 1, 17, 'Nes šis karalienės poelgis pasieks visas moteris, taip, kad jos paniekins savo vyrus savo akyse, kai bus pranešta: ‘Karalius Ahasveras įsakė atvesti jo akivaizdon karalienę Vaštę, bet ji neatėjo’.'),
  (@b17, 1, 18, 'Persijos ir Medijos kunigaikštienės, išgirdusios apie karalienės poelgį, šią dieną taip pat sakys visiems karalių kunigaikščiams. Šitaip kils per daug paniekinimo ir rūstybės.'),
  (@b17, 1, 19, 'Jei karaliui patinka, teišeina nuo jo karališkas įsakymas ir tebūna jis įrašytas tarp persų bei medų įstatymų, kuris nebūtų pakeistas: ‘Kad Vaštė nebeateis karaliaus Ahasvero akivaizdon; ir tegul karalius suteikia jos karališkąją padėtį kitai, geresnei už ją’.'),
  (@b17, 1, 20, 'O kai karaliaus įsakas, kurį jis paruoš, bus paskelbtas visoje jo imperijoje (nes ji yra didelė), visos žmonos suteiks savo vyrams pagarbą, tiek dideliems, tiek ir mažiems“.'),
  (@b17, 1, 21, 'Ir tas pasakymas patiko karaliui bei kunigaikščiams; ir karalius padarė pagal Memuchano žodį:'),
  (@b17, 1, 22, 'nes jis nusiuntė laiškus į visas karaliaus provincijas, į kiekvieną provinciją jos raštu ir į kiekvieną tautą pagal jos kalbą, kad kiekvienas vyras viešpatautų savo namuose ir kad tai būtų paskelbta kiekvienos tautos kalba.'),
  (@b17, 2, 1, 'Po šitų dalykų, kai karaliaus Ahasvero rūstybė nurimo, jis atsiminė Vaštę, ką ji buvo padariusi, ir koks įsakas buvo paskelbtas prieš ją.'),
  (@b17, 2, 2, 'Tada karaliaus tarnai, kurie jam tarnavo, tarė: „Tepaieško karaliui gražių, jaunų mergelių;'),
  (@b17, 2, 3, 'ir tepaskiria karalius visose savo karalystės provincijose pareigūnus, kad jie surinktų visas gražias jaunas mergeles į Šušano rūmus, į moterų namus, karaliaus rūmininko Hegajo, moterų saugotojo, globon; ir tebūna joms suteikta tai, ko reikia apsivalymui;'),
  (@b17, 2, 4, 'o panelė, kuri patiks karaliui, tebūna karaliene Vaštės vietoje“. Tas dalykas patiko karaliui; ir jis taip padarė.'),
  (@b17, 2, 5, 'Na, o Šušano rūmuose buvo vienas žydas, kurio vardas buvo Mordekajas – sūnus Jayro, sūnus Šimio, sūnus Kišo, benjaminas;'),
  (@b17, 2, 6, 'kuris buvo išvestas iš Jeruzalės su belaisviais, kurie buvo išvesti su Judos karaliumi Jechoniju, kurį buvo išvedęs Babilono karalius Nebukadnecaras.'),
  (@b17, 2, 7, 'Ir jis užaugino Hadasą, tai yra Esterą, savo dėdės dukterį; nes ji neturėjo nei tėvo, nei motinos; ir ta panelė buvo dailiai nuaugusi ir graži; jos tėvui ir motinai mirus, Mordekajas ją pasiėmė kaip savo dukrą.'),
  (@b17, 2, 8, 'Taigi įvyko, kai karaliaus įsakymas ir jo įsakas buvo išgirsti, ir kai daug panelių susirinko į Šušano rūmus Hegajo globon, Estera irgi buvo nuvesta į karaliaus namus moterų sargo Hegajo globon.'),
  (@b17, 2, 9, 'Ir ta panelė jam patiko ir įgavo jo palankumą; ir jis skubiai davė jai jos dalykus apsivalymui, su tais dalykais, kurie jai priklausė, ir septynias paneles, tinkamas jai duoti iš karaliaus namų; ir jis paaukštino ją bei jos paneles į geriausią moterų namų vietą.'),
  (@b17, 2, 10, 'Estera nesakė apie savo tautą ir savo giminę; nes Mordekajas buvo ją įpareigojęs, kad ji nesakytų.'),
  (@b17, 2, 11, 'O Mordekajas kiekvieną dieną vaikščiodavo prieš moterų namų kiemą, kad sužinotų, kaip Esterai sekasi ir kas jai nutinka.'),
  (@b17, 2, 12, 'Na, o atėjus kiekvienos panelės eilei įeiti pas karalių Ahasverą po to, kai ji dvylika mėnesių išbuvo pagal moterų būdą (nes taip buvo atliekamos jų apsivalymo dienos, būtent šešis mėnesius miros aliejumi ir šešis mėnesius gardžiais aromatais ir kitais moterų apsivalymo dalykais),'),
  (@b17, 2, 13, 'tada taip ateidavo kiekviena panelė pas karalių; viskas, ko ji norėdavo, jai būdavo duodama išėjimui su ja iš moterų namų į karaliaus namus.'),
  (@b17, 2, 14, 'Vakare ji eidavo, o rytojaus dieną sugrįždavo į antruosius moterų namus, karaliaus rūmininko Šaašgazo, sugulovių sargo, globon; ji nebeįeidavo pas karalių, nebent karalius ją pamėgdavo ir ji būdavo pašaukiama vardu.'),
  (@b17, 2, 15, 'Na, o kai atėjo eilė Esteros – dukters Abihailo, kuris buvo dėdė Mordekajo, paėmusio ją sau į dukras – įeiti pas karalių, ji nieko neprašė, bet tik tai, ką paskyrė karaliaus rūmininkas Hegajas, moterų sargas. Ir Estera įgavo palankumą akyse visų tų, kurie į ją pažiūrėdavo.'),
  (@b17, 2, 16, 'Taip Estera buvo paimta pas karalių Ahasverą į jo karališkuosius namus dešimtąjį mėnesį, kuris yra Tebeto mėnuo, septintaisiais jo karaliavimo metais.'),
  (@b17, 2, 17, 'Ir karalius pamilo Esterą labiau už visas moteris, ir ji įgijo jo akyse malonės ir palankumo daugiau negu visos mergelės; taip, kad jis uždėjo jai ant galvos karališką karūną ir padarė ją karaliene Vaštės vietoje.'),
  (@b17, 2, 18, 'Tada karalius suruošė didelę puotą visiems savo kunigaikščiams ir savo tarnams, būtent Esteros puotą; ir jis suteikė provincijoms poilsį ir davė dovanų pagal karaliaus išgales.'),
  (@b17, 2, 19, 'O mergelėms susirinkus antrą kartą, Mordekajas sėdėjo karaliaus vartuose.'),
  (@b17, 2, 20, 'Estera dar nebuvo pasakiusi nei apie savo giminę, nei apie savo tautą; kaip Mordekajas ją buvo įpareigojęs; nes Estera vykdė Mordekajo įsakymą, kaip tada, kai ji buvo jo auginama.'),
  (@b17, 2, 21, 'Tomis dienomis, Mordekajui sėdint karaliaus vartuose, du karaliaus rūmininkai, Bigtanas ir Terešas, iš durų sargų, užsirūstino ir siekė uždėti rankas ant karaliaus Ahasvero.'),
  (@b17, 2, 22, 'O tą dalyką sužinojęs, Mordekajas pranešė karalienei Esterai; o Estera tai patvirtino karaliui Mordekajo vardu.'),
  (@b17, 2, 23, 'Ir tas dalykas buvo ištirtas ir išaiškintas; todėl jie abu buvo pakarti ant medžio; ir tai buvo užrašyta į kronikų knygą karaliaus akivaizdoje.'),
  (@b17, 3, 1, 'Po šitų dalykų karalius Ahasveras paaukštino Hamedatos sūnų Hamaną, agagą, ir jį pakėlė, ir pastatė jo sostą aukščiau visų su juo esančių kunigaikščių.'),
  (@b17, 3, 2, 'Ir visi karaliaus tarnai, kurie buvo karaliaus vartuose, nusilenkdavo ir pagerbdavo Hamaną; nes taip karalius buvo įsakęs dėl jo. Bet Mordekajas nesilenkdavo nei jo nepagerbdavo.'),
  (@b17, 3, 3, 'Tada karaliaus tarnai, esantys karaliaus vartuose, tarė Mordekajui: „Kodėl nusižengi karaliaus įsakymui?“'),
  (@b17, 3, 4, 'Na, o kai jie kasdien jam sakė, o jis jų neklausė, įvyko, kad jie pranešė Hamanui, idant pamatytų, ar Mordekajo reikalai išsilaikys; nes jis buvo jiems pasisakęs esąs žydas.'),
  (@b17, 3, 5, 'Ir Hamanas matydamas, kad Mordekajas nesilenkdavo nei jo nepagerbdavo, Hamanas buvo pilnas rūstybės.'),
  (@b17, 3, 6, 'Ir jis manė, kad niekinga uždėti rankas ant vieno Mordekajo; nes jie jam buvo pasakę apie Mordekajo tautą; todėl Hamanas siekė išnaikinti visus žydus, esančius visoje Ahasvero karalystėje, būtent Mordekajo tautą.'),
  (@b17, 3, 7, 'Pirmąjį mėnesį, tai yra Nisano mėnesį, dvyliktaisiais karaliaus Ahasvero metais, jie metė Purą, tai yra burtą, Hamano akivaizdoje diena iš dienos, mėnuo iš mėnesio iki dvyliktojo mėnesio, tai yra Adaro mėnesio.'),
  (@b17, 3, 8, 'Ir Hamanas tarė karaliui Ahasverui: „Yra viena tauta, išsisklaidžiusi ir išsibarsčiusi tarp tautų visose tavo karalystės provincijose; ir jų įstatymai skiriasi nuo visų tautų įstatymų; ir karaliaus įstatymų jie nesilaiko; todėl karaliui nenaudinga juos pakęsti.'),
  (@b17, 3, 9, 'Jei karaliui patinka, tebūna parašoma, kad jie būtų sunaikinti; o aš sumokėsiu dešimt tūkstančių talentų sidabro į rankas tų, kurie yra įpareigoti dėl šio reikalo, kad tai pristatytų į karaliaus lobynus“.'),
  (@b17, 3, 10, 'Ir karalius paėmė nuo savo rankos savo žiedą ir jį padavė Hamedatos sūnui Hamanui, agagui, žydų priešui.'),
  (@b17, 3, 11, 'Ir karalius tarė Hamanui: „Sidabras tau duotas, taip pat ta tauta, kad pasielgtum su jais, kaip tau atrodo gerai“.'),
  (@b17, 3, 12, 'Tada, pirmojo mėnesio tryliktą dieną, buvo sušaukti karaliaus raštininkai ir buvo parašyta pagal visa tai, ką įsakė Hamanas karaliaus pavaduotojams, kiekvienos provincijos valdytojams ir kiekvienos provincijos tautos valdovams pagal jų raštą ir kiekvienai tautai pagal jos kalbą; karaliaus Ahasvero vardu tai buvo parašyta ir užantspauduota karaliaus žiedu.'),
  (@b17, 3, 13, 'Ir laiškai buvo išsiųsti per bėgikus į visas karaliaus provincijas, kad sunaikintų, išžudytų ir pražudytų visus žydus, tiek jaunus, tiek senus, tiek mažus vaikus, tiek moteris, per vieną dieną, būtent dvyliktojo mėnesio, tai yra Adaro mėnesio, tryliktą dieną; ir kas iš jų išplėšta, paimti kaip grobį.'),
  (@b17, 3, 14, 'To rašto kopija, kad būtų duodama kaip įsakymas kiekvienoje provincijoje, buvo paskelbta visoms tautoms, idant jos būtų pasiruošusios tai dienai.'),
  (@b17, 3, 15, 'Karaliaus įsakymo paskubinti bėgikai išvyko, ir įsakas buvo išleistas Šušano rūmuose. O karalius ir Hamanas sėdosi gerti; bet Šušano miestas buvo sumišęs.'),
  (@b17, 4, 1, 'Kai Mordekajas sužinojo visa tai, kas buvo padaryta, Mordekajas persiplėšė savo drabužius, apsivilko ašutine su pelenais, išėjo į miesto vidurį ir šaukė garsiu bei karčiu verksmu;'),
  (@b17, 4, 2, 'ir atėjo prieš karaliaus vartus; nes niekas negalėjo įeiti į karaliaus vartus apsirengęs ašutine.'),
  (@b17, 4, 3, 'Ir kiekvienoje provincijoje, kur tik atėjo karaliaus įsakymas ir jo įsakas, tarp žydų buvo didelis gedulas, pasninkas, verksmas ir dejonės; ir daugelis gulėjo su ašutine ir pelenuose.'),
  (@b17, 4, 4, 'Taigi Esteros panelės ir jos rūmininkai atėjo ir tai jai pranešė. Tada karalienė nepaprastai nuliūdo; ir ji nusiuntė drabužius, kad apvilktų Mordekają ir nuo jo nuimtų jo ašutinę; bet jis jų nepriėmė.'),
  (@b17, 4, 5, 'Tada Estera pasišaukė Hatachą, vieną iš karaliaus rūmininkų, kurį jis buvo paskyręs ja rūpintis, ir davė jam įsakymą Mordekajui, kad sužinotų, kas tai yra ir kodėl tai yra.'),
  (@b17, 4, 6, 'Taigi Hatachas išėjo pas Mordekają į miesto gatvę, esančią prieš karaliaus vartus.'),
  (@b17, 4, 7, 'Ir Mordekajas jam papasakojo viską, kas jam buvo atsitikę, ir apie pinigų sumą, kurią Hamanas buvo pažadėjęs sumokėti į karaliaus iždines už žydus, kad juos išnaikintų.'),
  (@b17, 4, 8, 'Taip pat jis jam davė rašto kopiją įsako, kuris buvo išleistas Šušane jiems sunaikinti, kad parodytų Esterai ir jai tai paskelbtų, ir įpareigotų ją, kad ji įeitų pas karalių jo maldauti ir prašyti jo akivaizdoje už savo tautą.'),
  (@b17, 4, 9, 'Ir Hatachas atėjęs pranešė Esterai Mordekajo žodžius.'),
  (@b17, 4, 10, 'Vėl Estera kalbėjo Hatachui ir davė jam įsakymą Mordekajui:'),
  (@b17, 4, 11, '„Visi karaliaus tarnai ir karaliaus provincijų tautos žino, kad kiekvienam, vyrui ar moteriai, kuris, nebūdamas pakviestas, įeina pas karalių į vidinį kiemą, tėra vienas jo įstatymas – užmušti jį, išskyrus tą, kuriam karalius ištiesia auksinį skeptrą, kad jis išliktų gyvas; bet aš šias trisdešimt dienų nesu buvusi pašaukta įeiti pas karalių“.'),
  (@b17, 4, 12, 'Ir Esteros žodžius pranešė Mordekajui.'),
  (@b17, 4, 13, 'Tada Mordekajas liepė atsakyti Esterai: „Nemanyk savyje, kad tu karaliaus namuose išsigelbėsi labiau už visus žydus.'),
  (@b17, 4, 14, 'Nes jei šiuo metu visiškai tylėsi, tai padidėjimas ir išvadavimas kils žydams iš kitos vietos; bet tu ir tavo tėvo namai būsite sunaikinti; o kas žino, ar kaip tik ne šitokiam laikui tu atėjusi į karalystę?“'),
  (@b17, 4, 15, 'Tada Estera liepė taip atsakyti Mordekajui:'),
  (@b17, 4, 16, '„Eik, surink visus žydus, esančius Šušane, ir pasninkaukite dėl manęs, ir tris dienas, naktį ir dieną, nieko nevalgykite ir negerkite; aš irgi su savo panelėmis taip pat pasninkausiu; ir taip aš įeisiu pas karalių, kas nėra pagal įstatymą; o jei pražūsiu, tai pražūsiu“.'),
  (@b17, 4, 17, 'Taigi Mordekajas nuėjo sau ir padarė pagal visa tai, ką jam buvo įsakiusi Estera.'),
  (@b17, 5, 1, 'Na, o trečiąją dieną įvyko, kad Estera apsivilko savo karališkais drabužiais ir atsistojo karaliaus namų vidiniame kieme, priešais karaliaus namus; o karalius sėdėjo savo karališkame soste, karališkuose namuose, priešais namų vartus.'),
  (@b17, 5, 2, 'Ir buvo, kai karalius pamatė karalienę Esterą, stovinčią kieme, ji įgijo palankumą jo akyse; ir karalius ištiesė Esterai auksinį skeptrą, esantį jo rankoje. Taigi Estera priėjusi palietė skeptro viršutinį galą.'),
  (@b17, 5, 3, 'Tada karalius jai tarė: „Kas tau, karaliene Estera? Ir koks tavo prašymas? Tau bus tai duota iki pusės karalystės“.'),
  (@b17, 5, 4, 'Ir Estera atsakė: „Jei karaliui atrodo gera, tegul šią dieną karalius su Hamanu ateina į pokylį, kurį esu jam paruošusi“.'),
  (@b17, 5, 5, 'Tada karalius tarė: „Liepkite Hamanui pasiskubinti, kad jis padarytų, kaip pasakė Estera“. Taigi karalius ir Hamanas atėjo į pokylį, kurį paruošė Estera.'),
  (@b17, 5, 6, 'Ir karalius vyno pokylyje tarė Esterai: „Koks tavo prašymas? Tai tau bus suteikta; koks tavo pageidavimas? Tai bus įvykdyta iki pusės karalystės“.'),
  (@b17, 5, 7, 'Tada Estera atsakydama tarė: „Mano prašymas ir mano pageidavimas yra:'),
  (@b17, 5, 8, 'jei radau palankumą karaliaus akyse ir jei karaliui patinka patenkinti mano prašymą ir įvykdyti mano pageidavimą, tegul karalius ateina su Hamanu į pokylį, kurį jiems paruošiu, o rytoj padarysiu, kaip karalius sakė“.'),
  (@b17, 5, 9, 'Tada Hamanas išėjo tą dieną linksmas ir džiugia širdimi; bet kai Hamanas pamatė Mordekają karaliaus vartuose, kad jis neatsistojo ir dėl jo nepasijudino, jis buvo pilnas pasipiktinimo prieš Mordekają.'),
  (@b17, 5, 10, 'Tačiau Hamanas susilaikė; ir parėjęs į namus, pasiuntė ir pašaukė savo draugus ir savo žmoną Zerešą.'),
  (@b17, 5, 11, 'Ir Hamanas jiems pasakojo apie savo turtų šlovę, apie savo vaikų daugybę ir apie visa tai, kame karalius jį pakėlęs ir kaip jį paaukštinęs virš karaliaus kunigaikščių ir tarnų.'),
  (@b17, 5, 12, 'Hamanas dar pasakė: „Taip, karalienė Estera neleido niekam įeiti su karaliumi į pokylį, kurį buvo paruošusi, bet tik man; taip pat rytoj esu pakviestas pas ją su karaliumi.'),
  (@b17, 5, 13, 'Tačiau visa tai neduoda man jokios naudos, kol matau žydą Mordekają sėdintį prie karaliaus vartų“.'),
  (@b17, 5, 14, 'Tada jo žmona Zereša ir visi jo draugai jam tarė: „Tebūna padarytos penkiasdešimties uolekčių aukščio kartuvės, ir rytoj kalbėk karaliui, kad ant jų būtų pakartas Mordekajas; tada linksmas įeik su karaliumi į pokylį“. Ir tas dalykas patiko Hamanui; ir jis liepė pastatyti kartuves.'),
  (@b17, 6, 1, 'Tą naktį karalius negalėjo miegoti, ir jis įsakė atnešti knygą kronikų įrašų; ir jie buvo skaitomi karaliaus akivaizdoje.'),
  (@b17, 6, 2, 'Ir buvo rasta užrašyta, kad Mordekajas buvo pranešęs apie Bigtaną ir Terešą, du karaliaus rūmininkus, durų sargus, kurie siekė uždėti rankas ant karaliaus Ahasvero.'),
  (@b17, 6, 3, 'Ir karalius tarė: „Kokia garbė ir išaukštinimas buvo už tai suteikti Mordekajui?“ Tada karaliaus tarnai, kurie jam patarnavo, pasakė: „Jam nieko nebuvo padaryta“.'),
  (@b17, 6, 4, 'Ir karalius tarė: „Kas yra kieme?“ Na, o Hamanas buvo įėjęs į išorinį karaliaus namų kiemą kalbėti su karaliumi, kad pakartų Mordekają ant kartuvių, kurias jis buvo jam paruošęs.'),
  (@b17, 6, 5, 'Ir karaliaus tarnai jam tarė: „Štai Hamanas stovi kieme“. Ir karalius tarė: „Tegul jis įeina“.'),
  (@b17, 6, 6, 'Taigi Hamanas įėjo. Ir karalius jam tarė: „Ką reikėtų padaryti vyrui, kurį karaliui patinka pagerbti?“ Na, o Hamanas pagalvojo savo širdyje: „Ką gi karalius su malonumu nori pagerbti labiau už mane?“');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b17, 6, 7, 'Ir Hamanas atsakė karaliui: „Vyrui, kurį karaliui patinka pagerbti,'),
  (@b17, 6, 8, 'tebūna atnešti karališki rūbai, kuriais vilki karalius, ir atvestas žirgas, ant kurio joja karalius, ir karališka karūna, kuri uždėta ant jo galvos;'),
  (@b17, 6, 9, 'ir šie rūbai bei žirgas tebūna perduoti vienam iš karaliaus kilmingiausių kunigaikščių į rankas, kad tą vyrą, kurį karaliui patinka pagerbti, aprengtų ir jį vestų ant žirgo per miesto gatvę, ir pirma jo skelbtų: ‘Taip bus daroma vyrui, kurį karaliui patinka pagerbti’“.'),
  (@b17, 6, 10, 'Tada karalius tarė Hamanui: „Skubėk, paimk rūbus ir žirgą, kaip kalbėjai, ir padaryk taip žydui Mordekajui, sėdinčiam prie karaliaus vartų; nieko nepalik nepadaręs iš viso to, ką kalbėjai“.'),
  (@b17, 6, 11, 'Tada Hamanas, paėmęs rūbus ir žirgą, aprengė Mordekają ir vedė jį raitą per miesto gatvę, ir pirma jo skelbė: „Taip bus daroma vyrui, kurį karaliui patinka pagerbti“.'),
  (@b17, 6, 12, 'Ir Mordekajas sugrįžo prie karaliaus vartų. Bet Hamanas nuskubėjo į savo namus nuliūdęs ir apsigaubęs galvą.'),
  (@b17, 6, 13, 'Ir Hamanas papasakojo savo žmonai Zerešai bei visiems savo draugams viską, kas jam buvo atsitikę. Tada jo išminčiai ir jo žmona Zereša jam tarė: „Jei Mordekajas, prieš kurį tu pradėjai kristi, yra iš žydų sėklos, tu jo neįveiksi, bet tikrai krisi prieš jį“.'),
  (@b17, 6, 14, 'Ir jiems dar su juo besikalbant, atėjo karaliaus rūmininkai ir skubėjo nuvesti Hamaną į pokylį, kurį buvo paruošusi Estera.'),
  (@b17, 7, 1, 'Taigi karalius ir Hamanas atėjo į pokylį pas karalienę Esterą.'),
  (@b17, 7, 2, 'Ir antrąją dieną vyno pokylyje karalius vėl tarė Esterai: „Koks tavo prašymas, karaliene Estera? Tai tau bus suteikta; ir koks tavo pageidavimas? Tai bus įvykdyta iki pusės karalystės“.'),
  (@b17, 7, 3, 'Tada karalienė Estera atsakydama tarė: „Jei radau palankumą tavo akyse, o karaliau, ir jei karaliui patinka, tebūna mano prašymu man duota mano gyvybė, ir mano pageidavimu – mano tauta;'),
  (@b17, 7, 4, 'nes mes, aš ir mano tauta, esame parduoti, kad būtume sunaikinti, užmušti ir pražudyti. Bet jei būtume buvę parduoti vergais ir vergėmis, aš būčiau sulaikiusi savo liežuvį, nors priešas neišlygintų karaliaus nuostolių“.'),
  (@b17, 7, 5, 'Tada karalius Ahasveras atsakydamas tarė karalienei Esterai: „Kas jis yra ir kur jis yra, kuris išdrįso savo širdyje taip daryti?“'),
  (@b17, 7, 6, 'Ir Estera tarė: „Priešininkas ir priešas yra šitas nedorėlis Hamanas“. Tada Hamanas išsigando karaliaus ir karalienės akivaizdoje.'),
  (@b17, 7, 7, 'Ir karalius užsirūstinęs atsikėlė iš vyno pokylio ir nuėjo į rūmų sodą; o Hamanas atsistojo prašyti dėl savo gyvybės iš karalienės Esteros; nes jis matė, kad jam buvo karaliaus nulemta nelaimė.'),
  (@b17, 7, 8, 'Tada karalius sugrįžo iš rūmų sodo į vyno pokylio vietą; o Hamanas buvo parpuolęs ant gulto, ant kurio buvo Estera. Tada karalius tarė: „Ar jis ir karalienę prievartaus namuose mano akivaizdoje?“ Vos tik žodžiui išėjus iš karaliaus burnos, jie uždengė Hamano veidą.'),
  (@b17, 7, 9, 'O Harbona, vienas iš rūmininkų, karaliaus akivaizdoje tarė: „Štai Hamano namuose stovi penkiasdešimties uolekčių aukščio kartuvės, kurias Hamanas buvo pastatęs Mordekajui, kalbėjusiam gera dėl karaliaus“. Tada karalius tarė: „Pakarkite jį ant jų“.'),
  (@b17, 7, 10, 'Taigi jie pakorė Hamaną ant kartuvių, kurias jis buvo paruošęs Mordekajui. Tada karaliaus rūstybė buvo numalšinta.'),
  (@b17, 8, 1, 'Tą dieną karalius Ahasveras davė karalienei Esterai žydų priešo Hamano namus. O Mordekajas atėjo karaliaus akivaizdon; nes Estera buvo pranešusi, kas jis jai esąs.'),
  (@b17, 8, 2, 'Ir karalius nusimovė savo žiedą, kurį buvo paėmęs iš Hamano, ir padavė jį Mordekajui. O Estera pastatė Mordekają Hamano namų prižiūrėtoju.'),
  (@b17, 8, 3, 'Ir Estera dar kartą kalbėjo karaliaus akivaizdoje ir, parpuolusi prie jo kojų, su ašaromis maldavo jo, kad pašalintų agago Hamano piktybę ir jo kėslą, kurį jis buvo sumanęs prieš žydus.'),
  (@b17, 8, 4, 'Tada karalius ištiesė į Esterą auksinį skeptrą. Taip Estera atsikėlė ir atsistojusi prieš karalių'),
  (@b17, 8, 5, 'tarė: „Jei karaliui patinka ir jei radau palankumą jo akyse, ir jei tas dalykas karaliaus aivaizdoje atrodo geras, ir jei esu miela jo akyse, tebūna rašoma, kad būtų atšaukti laiškai, sumanyti Hamedatos sūnaus Hamano, agago, kuriuos jis parašė, kad išnaikintų žydus, esančius visose karaliaus provincijose;'),
  (@b17, 8, 6, 'nes kaip galėčiau ištverti, matydama nelaimę, kuri ištiktų mano tautą? Arba kaip galėčiau ištverti, matydama savo giminės sunaikinimą?“'),
  (@b17, 8, 7, 'Tada karalius Ahasveras tarė karalienei Esterai ir žydui Mordekajui: „Štai aš daviau Esterai Hamano namus, o jį patį pakorė ant kartuvių dėl to, kad jis uždėjo savo ranką ant žydų.'),
  (@b17, 8, 8, 'Jūs irgi parašykite žydams, kaip jums patinka, karaliaus vardu, ir užantspauduokite tai karaliaus žiedu; nes rašto, parašyto karaliaus vardu ir užantspauduoto karaliaus žiedu, niekas negali atšaukti“.'),
  (@b17, 8, 9, 'Tada, tuo metu, trečiąjį mėnesį, tai yra Sivano mėnesį, jo dvidešimt trečiąją dieną, buvo sušaukti karaliaus raštininkai; ir buvo parašyta pagal visa tai, ką Mordekajas įsakė žydams, karaliaus pavaduotojams bei vietininkams ir valdovams provincijų, esančių nuo Indijos iki Etiopijos, šimto dvidešimt septynių provincijų, kiekvienai provincijai jos raštu ir kiekvienai tautai jos kalba, ir žydams jų raštu ir jų kalba.'),
  (@b17, 8, 10, 'Ir jis parašė karaliaus Ahasvero vardu ir užantspaudavo tai karaliaus žiedu, ir išsiuntė laiškus per raituosius pasiuntinius, raitelius ant mulų, kupranugarių bei jaunų dromedarų:'),
  (@b17, 8, 11, 'kad karalius leido žydams, esantiems kiekviename mieste, susirinkti ir ginti savo gyvybę, išnaikinti, išžudyti ir pražudyti visokią tautos ir provincijos galybę, kurie puola juos, tiek mažylius, tiek moteris, ir jų išplėšas pasiimti kaip grobį,'),
  (@b17, 8, 12, 'vieną dieną visose karaliaus Ahasvero provincijose, būtent dvyliktojo mėnesio, tai yra Adaro mėnesio, tryliktąją dieną.'),
  (@b17, 8, 13, 'To rašto kopija, kad būtų išleista kaip įsakymas kiekvienoje provincijoje, buvo paskelbta visoms tautoms, ir kad žydai būtų pasiruošę tai dienai atkeršyti savo priešams.'),
  (@b17, 8, 14, 'Taigi pasiuntiniai, jojantys ant mulų ir kupranugarių, karaliaus įsakymo paskubinti ir paskatinti, išvyko. Ir tas įsakas buvo išleistas Šušano rūmuose.'),
  (@b17, 8, 15, 'Ir Mordekajas išėjo nuo karaliaus akivaizdos karališku drabužiu iš mėlyno bei balto ir su dideliu aukso vainiku, ir plonos drobės bei purpuro apdaru; ir Šušano miestas džiaugėsi ir buvo linksmas.'),
  (@b17, 8, 16, 'Žydai turėjo šviesą, linksmybę, džiaugsmą ir pagerbimą.'),
  (@b17, 8, 17, 'Ir kiekvienoje provincijoje ir kiekviename mieste, kur tik atėjo karaliaus įsakymas ir jo įsakas, pas žydus buvo džiaugsmas, linksmybė, puota ir gera diena. Ir daugelis iš tos šalies tautų tapo žydais; nes juos apėmė žydų baimė.'),
  (@b17, 9, 1, 'Na, o dvyliktąjį mėnesį, tai yra Adaro mėnesį, jo tryliktąją dieną, kai artėjo karaliaus įsakymo ir jo įsako įvykdymas, tą dieną, kai žydų priešai tikėjosi juos užvaldyti (nors atsitiko priešingai – žydai valdė tuos, kurie jų nekentė),'),
  (@b17, 9, 2, 'žydai susirinko savo miestuose, visose karaliaus Ahasvero provincijose, kad uždėtų rankas ant tų, kurie siekė jiems pakenkti; ir niekas negalėjo atsilaikyti prieš juos; nes visas tautas apėmė jų baimė.'),
  (@b17, 9, 3, 'Ir visi provincijų valdovai, pavaduotojai, vietininkai ir karaliaus pareigūnai padėjo žydams; nes juos buvo apėmusi Mordekajo baimė.'),
  (@b17, 9, 4, 'Nes Mordekajas buvo didis karaliaus namuose, ir garsas apie jį pasklido visose provincijose; nes tas vyras Mordekajas darėsi vis didesnis ir didesnis.'),
  (@b17, 9, 5, 'Taip žydai mušė visus savo priešus kalavijo kirčiu, žudynėmis ir naikinimu, ir darė, ką norėjo tiems, kurie jų nekentė.'),
  (@b17, 9, 6, 'Ir Šušano rūmuose žydai išžudė ir sunaikino penkis šimtus žmonių.'),
  (@b17, 9, 7, 'O Paršandatą, Dalfoną, Aspatą,'),
  (@b17, 9, 8, 'Poratą, Adaliją, Aridatą,'),
  (@b17, 9, 9, 'Parmaštą, Arisają, Aridają ir Vaizatą,'),
  (@b17, 9, 10, 'dešimt Hamedatos sūnaus Hamano, žydų priešo, sūnų jie užmušė; bet prie grobio jie nepridėjo rankų.'),
  (@b17, 9, 11, 'Tą dieną Šušano rūmuose užmuštųjų skaičius buvo praneštas karaliaus akivaizdon.'),
  (@b17, 9, 12, 'Ir karalius tarė karalienei Esterai: „Šušano rūmuose žydai užmušė ir sunaikino penkis šimtus žmonių ir dešimt Hamano sūnų; ką jie padarė kitose karaliaus provincijose? Koks dabar tavo prašymas? Tau tai bus suteikta; koks tolimesnis tavo pageidavimas? Tai bus įvykdyta“.'),
  (@b17, 9, 13, 'Tada Estera tarė: „Jei karaliui patinka, tebūna leidžiama Šušane esantiems žydams rytoj taip pat daryti pagal šios dienos įsaką, ir dešimt Hamano sūnų tebūna pakarti ant kartuvių“.'),
  (@b17, 9, 14, 'Ir karalius įsakė, kad taip būtų padaryta; ir Šušane buvo išleistas įsakas; ir jie pakorė dešimt Hamano sūnų.'),
  (@b17, 9, 15, 'Nes Šušane esantys žydai susirinko taipogi keturioliktąją Adaro mėnesio dieną ir užmušė Šušane tris šimtus žmonių; bet prie grobio jie nepridėjo rankų.'),
  (@b17, 9, 16, 'Bet kiti žydai, esantys karaliaus provincijose, susirinko ir gynė savo gyvybes, ir ilsėjosi nuo savo priešų, ir užmušė septyniasdešimt penkis tūkstančius savo priešų, bet prie grobio jie neprikišo rankų,'),
  (@b17, 9, 17, 'Adaro mėnesio tryliktąją dieną; o jo keturioliktąją dieną jie ilsėjosi ir ją padarė pokylio bei džiaugsmo diena.'),
  (@b17, 9, 18, 'Bet Šušane esantys žydai susirinko jo tryliktąją ir jo keturioliktąją dieną; o jo penkioliktąją dieną ilsėjosi ir padarė ją pokylio ir džiaugsmo diena.'),
  (@b17, 9, 19, 'Todėl kaimų žydai, gyvenantys neaptvertuose miesteliuose, Adaro mėnesio keturioliktąją dieną padarė džiaugsmo ir pokylio diena, gera, vienas kitam dovanų siuntinėjimo, diena.'),
  (@b17, 9, 20, 'Ir Mordekajas surašė šituos dalykus ir nusiuntė laiškus visiems žydams, esantiems visose karaliaus Ahasvero provincijose, arti ir toli,'),
  (@b17, 9, 21, 'kad tai įtvirtintų tarp jų, kad jie kasmet švęstų Adaro mėnesio keturioliktą dieną ir jo penkioliktą dieną,'),
  (@b17, 9, 22, 'kaip dienas, kuriose žydai ilsėjosi nuo savo priešų, ir kaip mėnesį, kuris jiems pasikeitė iš sielvarto į džiaugsmą ir iš gedulo į gerą dieną; kad jas darytų dienomis pokyliavimo ir džiaugsmo, ir siuntinėjimo vienas kitam davinių bei dovanų beturčiams.'),
  (@b17, 9, 23, 'Ir žydai ėmėsi daryti, kaip jie buvo pradėję ir kaip Mordekajas jiems buvo rašęs;'),
  (@b17, 9, 24, 'nes Hamedatos sūnus Hamanas, agagas, visų žydų priešas, buvo sumanęs prieš žydus juos sunaikinti ir metė Purą, tai yra burtą, kad juos sunaikintų ir juos išžudytų;'),
  (@b17, 9, 25, 'bet kai Estera atėjo karaliaus akivaizdon, jis įsakė laiškais, kad jo piktas sumanymas, kurį jis sumanė prieš žydus, turi sugrįžti ant jo paties galvos ir kad jis bei jo sūnūs turi būti pakarti ant kartuvių“.'),
  (@b17, 9, 26, 'Todėl šitas dienas praminė Purimu pagal Puro pavadinimą. Todėl, dėl visų šito laiško žodžių ir to, ką jie šituo reikalu matė ir kas jiems buvo atsitikę,'),
  (@b17, 9, 27, 'žydai nustatė ir prisiėmė sau, savo sėklai ir visiems prisijungusiems prie jų, taip, kad tai nepranyktų, jog jie kasmet švęstų šitas abi dienas pagal jų raštą ir pagal jų paskirtą laiką;'),
  (@b17, 9, 28, 'ir kad šitos dienos būtų atmenamos bei švenčiamos kiekvienoje kartoje, kiekvienoje šeimoje, kiekvienoje provincijoje ir kiekviename mieste; ir kad šitos Purimo dienos neturi išnykti iš žydų tarpo nei jų atminimas neturi pražūti jų sėkloje.'),
  (@b17, 9, 29, 'Paskui karalienė Estera, Abihailo duktė, ir žydas Mordekajas rašė su visu įgaliojimu, kad patvirtintų šitą antrąjį Purimo laišką.'),
  (@b17, 9, 30, 'Ir išsiuntė laiškus visiems žydams į šimtą dvidešimt septynias Ahasvero karalystės provincijas su taikos ir tiesos žodžiais,'),
  (@b17, 9, 31, 'kad patvirtintų šitas Purimo dienas jų paskirtu laiku pagal tai, kaip žydas Mordekajas bei karalienė Estera įsakė ir kaip jie buvo išleidę įsaką sau bei savo sėklai dėl pasninkų ir jų raudojimo reikalų.'),
  (@b17, 9, 32, 'Ir Esteros įsakas patvirtino šituos Purimo reikalus; ir tai buvo įrašyta į knygą.'),
  (@b17, 10, 1, 'Ir Karalius Ahasveras uždėjo duoklę šaliai ir jūros saloms.'),
  (@b17, 10, 2, 'Ir visi jo valdžios ir jo galybės darbai ir paskelbimas Mordekajo didybės, į kurią jį pakėlė karalius, argi jie nėra surašyti Medijos ir Persijos karalių kronikų knygoje?'),
  (@b17, 10, 3, 'Nes žydas Mordekajas buvo antras po karaliaus Ahasvero, didis tarp žydų ir daugybės savo brolių priimtinas, siekiantis savo tautos gerovės ir kalbantis taiką visai savo sėklai.'),
  (@b18, 1, 1, 'Uco šalyje buvo vyras, kurio vardas buvo Jobas; tas vyras buvo tobulas ir tiesus, bijantis Dievo ir vengiantis pikto.'),
  (@b18, 1, 2, 'Ir jam gimė septyni sūnūs ir trys dukterys.'),
  (@b18, 1, 3, 'Jo turtas taipogi buvo: septyni tūkstančiai avių, trys tūkstančiai kupranugarių, penki šimtai jaučių jungų, penki šimtai asilių ir labai didelė šeimyna; taip, kad šis vyras buvo didingiausias iš visų rytų žmonių.'),
  (@b18, 1, 4, 'Ir jo sūnūs nuėję puotaudavo savo namuose, kiekvienas savo dieną; ir pasiuntę pasikviesdavo savo tris seseris, kad valgytų ir gertų su jais.'),
  (@b18, 1, 5, 'Ir buvo, kad jų puotavimo dienoms pasibaigus, Jobas nusiųsdavo ir juos pašvęsdavo, ir anksti ryte atsikėlęs atnašaudavo deginamąsias atnašas pagal jų visų skaičių; nes Jobas sakė: „Gal mano sūnūs nusidėjo ir keikė Dievą savo širdyse“. Taip Jobas nuolat darydavo.'),
  (@b18, 1, 6, 'Na, o buvo diena, kai Dievo sūnūs atėjo prisistatyti VIEŠPATIES akivaizdon, atėjo ir šėtonas tarp jų.'),
  (@b18, 1, 7, 'Ir VIEŠPATS tarė šėtonui: „Iš kur ateini?“ Tada šėtonas atsakė VIEŠPAČIUI ir tarė: „Iš vaikščiojimo ten ir atgal po žemę ir iš vaikštinėjimo po ją“.'),
  (@b18, 1, 8, 'Ir VIEŠPATS tarė šėtonui: „Ar įsižiūrėjai į mano tarną Jobą, kad žemėje nėra nei vieno jam lygaus, tobulo ir tiesaus vyro, bijančio Dievo ir vengiančio pikta?“'),
  (@b18, 1, 9, 'Tada šėtonas atsakė VlEŠPAČIUI ir tarė: „Argi už nieką Jobas bijo Dievo?'),
  (@b18, 1, 10, 'Argi nepadarei tvoros aplink jį ir aplink jo namus, ir aplink viską, ką jis turi, iš visų pusių? Tu palaiminai jo rankų darbą, ir jo turtas pagausėjo šalyje.'),
  (@b18, 1, 11, 'Bet dabar ištiesk savo ranką ir paliesk viską, ką jis turi, ir jis keiks tave tau į akis“.'),
  (@b18, 1, 12, 'Ir VIEŠPATS tarė šėtonui: „Štai viskas, ką jis turi, tavo valdžioje; tik į jį patį neištiesk savo rankos“. Taigi šėtonas nuėjo iš VIEŠPATIES akivaizdos.'),
  (@b18, 1, 13, 'Ir buvo diena, kai jo sūnūs ir jo dukterys valgė ir gėrė vyną jų vyriausiojo brolio namuose;'),
  (@b18, 1, 14, 'ir pasiuntinys atėjo pas Jobą ir tarė: „Jaučiams ariant ir asilams besiganant šalia jų,'),
  (@b18, 1, 15, 'užpuolė ant jų šebiečiai ir juos atėmė; taip, tarnus užmušė kalavijo ašmenimis; tik aš vienas ištrūkau, kad tau praneščiau“.'),
  (@b18, 1, 16, 'Jam tebekalbant, atėjo dar kitas ir tarė: „Dievo ugnis krito iš dangaus, sudegino avis, tarnus ir juos prarijo; tik aš vienas ištrūkau, kad tau praneščiau“.'),
  (@b18, 1, 17, 'Jam tebekalbant, atėjo dar kitas ir tarė: „Kaldėjai, pasiskirstę į tris būrius, puolė kupranugarius ir juos išvedė, taip, o tarnus užmušė kalavijo ašmenimis; tik aš vienas ištrūkau, kad tau praneščiau“.'),
  (@b18, 1, 18, 'Jam tebekalbant, atėjo dar kitas ir tarė: „Tavo sūnūs ir tavo dukterys valgė ir gėrė vyną jų vyriausiojo brolio namuose;'),
  (@b18, 1, 19, 'ir štai atėjo smarkus vėjas iš dykumos ir smogė į keturis namo kampus, ir tas užgriuvo ant jaunuolių, ir jie numirė; tik aš vienas ištrūkau, kad tau praneščiau“.'),
  (@b18, 1, 20, 'Tada Jobas atsikėlęs perplėšė savo mantiją, nusiskuto galvą ir parpuolęs ant žemės garbino'),
  (@b18, 1, 21, 'ir tarė: „Nuogas išėjau iš savo motinos įsčių ir nuogas ten sugrįšiu; VIEŠPATS davė ir VIEŠPATS atėmė; tebūna palaimintas VIEŠPATIES vardas“.'),
  (@b18, 1, 22, 'Visame tame Jobas nenusidėjo nei kvailai neapkaltino Dievo.'),
  (@b18, 2, 1, 'Vėl buvo diena, kai Dievo sūnūs atėjo prisistatyti VIEŠPATIES akivaizdon, atėjo ir šėtonas tarp jų, kad prisistatytų VIEŠPATIES akivaizdon.'),
  (@b18, 2, 2, 'Ir VIEŠPATS tarė šėtonui: „Iš kur ateini?“ O šėtonas atsakė VIEŠPAČIUI ir tarė: „Iš vaikščiojimo ten ir atgal po žemę ir iš vaikštinėjimo po ją“.'),
  (@b18, 2, 3, 'Ir VIEŠPATS tarė šėtonui: „Ar įsižiūrėjai į mano tarną Jobą, kad žemėje nėra nei vieno jam lygaus, tobulo ir tiesaus vyro, bijančio Dievo ir vengiančio pikta?“ Jis ir toliau tvirtai laikosi savo dorumo, nors tu mane ir paskatinai prieš jį, kad jį be priežasties sunaikinčiau“.'),
  (@b18, 2, 4, 'Ir šėtonas atsakė VIEŠPAČIUI ir tarė: „Oda už odą, taip, viską, ką žmogus turi, atiduos už savo gyvybę.'),
  (@b18, 2, 5, 'Bet dabar ištiesk savo ranką ir paliesk jo kaulus bei jo kūną, ir jis keiks tave tau į akis“.'),
  (@b18, 2, 6, 'Ir VIEŠPATS tarė šėtonui: „Štai jis tavo rankoje; tik išsaugok jo gyvybę“.'),
  (@b18, 2, 7, 'Taigi šėtonas išėjo iš VIEŠPATIES akivaizdos ir ištiko Jobą skaudžiomis votimis nuo jo kojų padų iki jo viršugalvio.'),
  (@b18, 2, 8, 'Ir jis pasiėmė šukę, ja nusigrandyti; ir jis atsisėdo tarp pelenų.'),
  (@b18, 2, 9, 'Tada jo žmona jam tarė: „Ar vis dar laikaisi savo dorumo? Keik Dievą ir mirk“.'),
  (@b18, 2, 10, 'Bet jis jai tarė: „Tu kalbi, kaip kalba viena iš kvailų moterų. Ką? Ar gera priimsime iš Dievo rankos, o pikta nepriimsime?“ Visame tame Jobas nenusidėjo lūpomis.'),
  (@b18, 2, 11, 'Na, o trys Jobo draugai, išgirdę apie visą tą nelaimę, kuri buvo jį ištikusi, jie atėjo kiekvienas iš savo vietos: temanas Elifazas, šuachas Bildadas ir naamatietis Cofaras; nes jie susitarė susitikti, kad ateitų gedėti su juo ir jį paguosti.'),
  (@b18, 2, 12, 'Ir pakėlę savo akis iš tolo ir jo nepažinę, jie pakėlę savo balsus verkė; ir jie kiekvienas perplėšė savo mantiją ir barstė dulkes ant savo galvų į dangų.'),
  (@b18, 2, 13, 'Taip jie sėdėjo su juo ant žemės septynias dienas ir septynias naktis, ir nei vienas nepratarė jam nei žodžio; nes jie matė, kad jo sielvartas buvo labai didelis.'),
  (@b18, 3, 1, 'Po to Jobas atvėrė savo burną ir prakeikė savo dieną.'),
  (@b18, 3, 2, 'Ir Jobas kalbėjo ir tarė:'),
  (@b18, 3, 3, '„Tepražūna diena, kurioje gimiau, ir naktis, kurioje tarė: ‘Pradėtas berniukas’.'),
  (@b18, 3, 4, 'Ta diena tebūna tamsybė; teneatsižvelgia į ją Dievas iš aukštai ir tenenušvinta ant jos šviesa.'),
  (@b18, 3, 5, 'Tesutepa ją tamsa ir mirties šešėlis; tegul debesis ant jos gyvena; teįbaugina ją dienos juodumas.'),
  (@b18, 3, 6, 'O ta naktis – tepagriebia ją tamsa; teneprijungia jos prie metų dienų, teneįeina ji į mėnesių skaičių.'),
  (@b18, 3, 7, 'Štai ta naktis tebūna nuošali, džiaugsmingas balsas teneateina į ją.'),
  (@b18, 3, 8, 'Teprakeikia ją dienos prakeikėjai, kurie pasiruošę pažadinti savąjį gedulą.'),
  (@b18, 3, 9, 'Teužtemsta jos prietemio žvaigždės; telaukia ji šviesos, bet teneturi jos; ir teneišvysta ji dienos aušros;'),
  (@b18, 3, 10, 'nes ji neužvėrė mano motinos įsčių durų nei nepaslėpė sielvarto nuo mano akių.'),
  (@b18, 3, 11, 'Kodėl nemiriau iš įsčių, kodėl neatidaviau dvasios, išėjęs iš pilvo?'),
  (@b18, 3, 12, 'Kodėl mane aplenkę pasitiko keliai ir kodėl krūtys, kad žįsčiau?'),
  (@b18, 3, 13, 'Nes dabar gulėčiau nejudėdamas ir būčiau tylus, aš miegočiau; tada ilsėčiausi'),
  (@b18, 3, 14, 'su žemės karaliais ir patarėjais, kurie sau statė apleistas vietas;'),
  (@b18, 3, 15, 'arba su kunigaikščiais, kurie turėjo aukso, kurie pripildė savo namus sidabro;'),
  (@b18, 3, 16, 'arba kaip paslėpto prieš laiką gimusio manęs nebūtų buvę; kaip kūdikių, niekada neregėjusių šviesos.'),
  (@b18, 3, 17, 'Ten nedorėliai liaujasi varginę; ir ten ilsisi pavargę.'),
  (@b18, 3, 18, 'Ten kaliniai ilsisi kartu; jie nebegirdi engėjo balso.'),
  (@b18, 3, 19, 'Maži ir dideli ten yra; ir tarnas yra laisvas nuo savo šeimininko.'),
  (@b18, 3, 20, 'Kodėl šviesa duodama tam, kuris kenčia, ir gyvybė tam, kurio siela apkartusi,'),
  (@b18, 3, 21, 'kuris ilgisi mirties, bet ji neateina; ir jos kasinėja labiau nei paslėptų lobių;'),
  (@b18, 3, 22, 'kurie be galo džiaugiasi ir yra patenkinti, kai pavyksta surasti kapą?'),
  (@b18, 3, 23, 'Kodėl šviesa duodama žmogui, kurio kelias paslėptas ir kurį Dievas aptvėrė?'),
  (@b18, 3, 24, 'Nes mano dūsavimai ateina prieš man valgant, ir mano kauksmai liejasi kaip vandenys.'),
  (@b18, 3, 25, 'Nes tai, ko labiausiai bijojau, užėjo ant manęs ir tai, ko baiminausi, man atėjo.'),
  (@b18, 3, 26, 'Aš nebuvau saugus nei neturėjau poilsio, nei nebuvau ramus; tačiau bėda atėjo“.'),
  (@b18, 4, 1, 'Tada temanas Elifazas atsakydamas tarė:'),
  (@b18, 4, 2, '„Jei bandysime su tavimi kalbėtis, ar nenuliūsi? Tačiau kas gali susilaikyti nekalbėjęs?'),
  (@b18, 4, 3, 'Štai tu pamokei daugelį ir sustiprinai silpnas rankas.'),
  (@b18, 4, 4, 'Griūnantį parėmė tavo žodžiai, ir silpnus kelius sustiprinai.'),
  (@b18, 4, 5, 'Bet dabar tai atėjo ant tavęs, ir tu silpsti; paliečia tave, ir tu sunerimęs.'),
  (@b18, 4, 6, 'Argi ne tai tavo baimė, tavo pasitikėjimas, tavo viltis ir tiesumas tavo kelių?'),
  (@b18, 4, 7, 'Prisimink, meldžiu tave, kuris, būdamas nekaltas, pražuvo? Arba, kur teisusis buvo iškirstas?'),
  (@b18, 4, 8, 'Kaip ir mačiau, tie, kurie aria neteisybę ir sėja blogybę, tą patį ir pjauna.'),
  (@b18, 4, 9, 'Nuo Dievo pūtimo jie žūva ir jo šnervių kvapu jie sunaikinti.'),
  (@b18, 4, 10, 'Liūto riaumojimas, pikto liūto balsas ir jaunų liūtų dantys yra sulaužomi.'),
  (@b18, 4, 11, 'Senas liūtas žūva dėl grobio stokos, ir stipraus liūto jaunikliai išsisklaido.'),
  (@b18, 4, 12, 'Na, o reikalas buvo slapta atneštas pas mane, ir mano ausis priėmė truputėlį jo.'),
  (@b18, 4, 13, 'Mintyse dėl nakties regėjimų, kai gilus miegas apima žmones,'),
  (@b18, 4, 14, 'mane apėmė baimė ir drebulys, kurie privertė drebėti visus mano kaulus.'),
  (@b18, 4, 15, 'Tada dvasia praėjo prieš mano veidą; mano kūno plaukai atsistojo;'),
  (@b18, 4, 16, 'ji stovėjo, bet negalėjau atpažinti jos pavidalo; atvaizdas buvo prieš mano akis, buvo tyla, ir aš išgirdau balsą, sakantį:'),
  (@b18, 4, 17, '‘Ar mirtingas žmogus bus teisesnis už Dievą? Ar žmogus bus tyresnis už jį padariusįjį?'),
  (@b18, 4, 18, 'Štai savo tarnais jis nepasikliauja; savo angelus jis kaltina kvailyste;'),
  (@b18, 4, 19, 'kaip juo labiau tais, kurie gyvena molio namuose, kurių pamatas yra dulkėse, kurie sutriuškinami prieš kandį?'),
  (@b18, 4, 20, 'Jie naikinami nuo ryto iki vakaro; jie amžiams pražūva niekam to nepastebint.'),
  (@b18, 4, 21, 'Ar jų puikumas, esantis juose, neišnyksta? Jie miršta, ir be išminties’“.'),
  (@b18, 5, 1, '„Šauk dabar, jei yra, kas tau atsakytų; į kurį iš šventųjų kreipsiesi?'),
  (@b18, 5, 2, 'Nes kvailąjį nužudo rūstybė, o paikąjį užmuša pavydas.'),
  (@b18, 5, 3, 'Mačiau kvailąjį leidžiant šaknis; bet tuoj pat prakeikiau jo buveinę.'),
  (@b18, 5, 4, 'Jo vaikai toli nuo saugumo, jie sutriuškinami vartuose, ir nėra kas juos išgelbėtų.'),
  (@b18, 5, 5, 'Jų derlių suvalgo alkanasis ir net iš erškėčių tai pasiima, ir plėšikas praryja jų turtą.'),
  (@b18, 5, 6, 'Nors sielvartas neišeina iš dulkių ir vargas neišauga iš žemės;'),
  (@b18, 5, 7, 'tačiau žmogus yra gimęs vargui, kaip kibirkštys lekia aukštyn.'),
  (@b18, 5, 8, 'Aš siekčiau Dievo ir patikėčiau savo bylą Dievui,'),
  (@b18, 5, 9, 'kuris daro didžius dalykus ir neištiriamus; nuostabius dalykus be skaičiaus;'),
  (@b18, 5, 10, 'kuris duoda lietaus ant žemės ir siunčia vandenis ant laukų;'),
  (@b18, 5, 11, 'kad pastatytų aukštai žemuosius; kad gedintys būtų pakelti į saugią vietą.'),
  (@b18, 5, 12, 'Jis suardo klastingųjų kėslus, kad jų rankos negali įvykdyti jų sumanymo.'),
  (@b18, 5, 13, 'Jis sugauna išmintinguosius jų pačių klastoje; ir priešgyniųjų ketinimas eina strimgalviu.'),
  (@b18, 5, 14, 'Dienos metu jie susitinka su tamsa ir vidudienį grabaliojasi kaip naktį.'),
  (@b18, 5, 15, 'Bet jis išgelbėja beturtį nuo kalavijo, nuo jų burnos ir nuo galingojo rankos.'),
  (@b18, 5, 16, 'Taip beturtis turi viltį, o neteisybė užčiaupia savo burną.'),
  (@b18, 5, 17, 'Štai laimingas žmogus, kurį Dievas pataiso; todėl neniekink Visagalio bausmės;'),
  (@b18, 5, 18, 'nes jis padaro žaizdą ir aptvarsto; jis sužeidžia, ir jo rankos pagydo.'),
  (@b18, 5, 19, 'Šešiose bėdose jis tave išgelbės; taip, septyniose pikta nepalies tavęs.'),
  (@b18, 5, 20, 'Bado metu jis tave atpirks iš mirties; o kare – iš kalavijo galios.'),
  (@b18, 5, 21, 'Nuo liežuvio botago būsi paslėptas; nei nebijosi sunaikinimo, kai jis ateis.'),
  (@b18, 5, 22, 'Iš sunaikinimo ir bado juoksiesi; nei nebijosi žemės žvėrių.'),
  (@b18, 5, 23, 'Nes būsi sąjungoje su lauko akmenimis; ir laukiniai žvėrys bus taikoje su tavimi.'),
  (@b18, 5, 24, 'Ir tu pažinsi, kad tavo padangtė bus ramybėje; ir lankysiesi savo buveinėje ir nenusidėsi.'),
  (@b18, 5, 25, 'Taip pat pažinsi, kad tavo sėkla bus gausi ir tavo palikuonys kaip žemės žolė.'),
  (@b18, 5, 26, 'Tu ateisi į savo kapą būdamas pilno amžiaus, kaip kad javų pėdai įeina savo laiku.'),
  (@b18, 5, 27, 'Štai mes tai ištyrėme, taip yra; išgirsk tai ir žinok tai savo labui“.'),
  (@b18, 6, 1, 'Bet Jobas atsakė ir tarė:'),
  (@b18, 6, 2, '„O, kad pilnai pasvertų mano sielvartą ir mano nelaimę kartu uždėtų ant svarstyklių!'),
  (@b18, 6, 3, 'Nes dabar jie būtų sunkesni už jūros smėlį; todėl mano žodžiai nuryti.'),
  (@b18, 6, 4, 'Nes Visagalio strėlės yra manyje, jų nuodus geria mano dvasia; Dievo bauginimai išsirikiavę prieš mane.'),
  (@b18, 6, 5, 'Ar bliauna laukinis asilas, turėdamas žolės? Arba, ar baubia jautis prie savo pašaro?'),
  (@b18, 6, 6, 'Ar galima valgyti beskonį dalyką be druskos? Arba, ar kiaušinio baltymas turi kokį skonį?'),
  (@b18, 6, 7, 'Dalykai, kurių mano siela atsisakydavo paliesti, yra kaip mano sielvartingas maistas.'),
  (@b18, 6, 8, 'O kad gaučiau tai, ko prašau; ir kad Dievas suteiktų man tai, ko ilgiuosi!'),
  (@b18, 6, 9, 'Būtent, kad patiktų Dievui sunaikinti mane; kad jis paleistų savo ranką ir mane iškirstų!'),
  (@b18, 6, 10, 'Tada dar turėčiau paguodos; taip, aš užsigrūdinčiau sielvarte; tenesigaili jis; nes nenuslėpiau Šventojo žodžių.'),
  (@b18, 6, 11, 'Kokia gi mano stiprybė, kad tikėčiausi? Ir koks mano galas, kad turėčiau prailginti savo gyvenimą?'),
  (@b18, 6, 12, 'Ar mano stiprybė – akmenų stiprybė? Ar mano kūnas iš žalvario?'),
  (@b18, 6, 13, 'Argi mano pagalba ne manyje? Ar išmintis visiškai pasitraukė nuo manęs?'),
  (@b18, 6, 14, 'Sielvartaujančiam gailestį turi parodyti jo draugas; bet jis atsisako Visagalio baimės.'),
  (@b18, 6, 15, 'Mano broliai pasielgė apgaulingai kaip upelis, kaip upelių srovė jie nuteka;'),
  (@b18, 6, 16, 'kurie yra juodoki dėl ledo, kuriuose pasislėpęs sniegas;'),
  (@b18, 6, 17, 'tuo laiku, kai jie įšyla, jie dingsta; kai yra karšta, jie išnyksta iš savo vietos.'),
  (@b18, 6, 18, 'Jų kelio takai pasukę į šalį; jie eina į tuštumą ir žūsta.'),
  (@b18, 6, 19, 'Temos pulkai žiūrėjo, Šebos būriai jų laukė.'),
  (@b18, 6, 20, 'Jie buvo sugėdinti, nes jie tikėjosi; jie ten atėjo ir susigėdo.'),
  (@b18, 6, 21, 'Nes dabar jūs esate niekas; jūs matote, kad aš prislėgtas, ir išsigandote.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b18, 6, 22, 'Argi sakiau: ‘Atneškite man’ arba: ‘Duokite man atlygį iš savo turto?’'),
  (@b18, 6, 23, 'Arba: ‘Išgelbėkite mane iš priešo rankos’, ar: ‘Išpirkite mane iš galingojo rankos?’'),
  (@b18, 6, 24, 'Pamokykite mane, ir aš sulaikysiu savo liežuvį; ir duokite man suprasti, kur suklydau.'),
  (@b18, 6, 25, 'Kokie įtikinami yra teisingi žodžiai! Tačiau ką jūsų įrodinėjimas subara?'),
  (@b18, 6, 26, 'Ar jūs manote pabarti bevilčio žodžius ir kalbas, kurie tėra kaip vėjas?'),
  (@b18, 6, 27, 'Taip, jūs triuškinate našlaitį ir kasate duobę savo draugui.'),
  (@b18, 6, 28, 'Taigi dabar teikitės, pažvelkite į mane; nes jums akivaizdu, jei aš meluoju.'),
  (@b18, 6, 29, 'Sugrįžkite, meldžiu jus, tenebūna tai neteisybė; taip, sugrįžkite, mano teisumas yra tame.'),
  (@b18, 6, 30, 'Ar yra neteisybė mano liežuvyje? Ar mano skonio pojūtis neatskiria iškreiptų dalykų?“'),
  (@b18, 7, 1, '„Ar nėra žmogui paskirto laiko žemėje? Ar jo dienos nėra kaip samdinio dienos?'),
  (@b18, 7, 2, 'Kaip tarnas uoliai trokšta pavėsio ir kaip samdinys laukia savo darbo atlygio;'),
  (@b18, 7, 3, 'taip aš esu padarytas, kad gaučiau nuosavybėn tuštybės mėnesius, ir man skirtos varginančios naktys.'),
  (@b18, 7, 4, 'Kai atsigulu, sakau: ‘Kada atsikelsiu, ir naktis bus pasibaigus?’ Aš prisisotinęs blaškymosi ten ir atgal iki dienos aušros.'),
  (@b18, 7, 5, 'Mano kūnas aprengtas kirmėlėmis ir dulkių grumstais; mano oda sutrūkinėjusi ir pasidarė pasibjaurėtina.'),
  (@b18, 7, 6, 'Mano dienos greitesnės už audėjo šaudyklę ir praleistos be vilties.'),
  (@b18, 7, 7, 'O, atsimink, kad mano gyvenimas – vėjas; mano akis neberegės gero.'),
  (@b18, 7, 8, 'Akis to, kuris mane matė, nebematys manęs; tavo akys nukreiptos į mane, o manęs nėra.'),
  (@b18, 7, 9, 'Kaip debesis išretėja ir dingsta; taip ir nužengiantis į kapą – nebeužžengia.'),
  (@b18, 7, 10, 'Jis nebegrįš į savo namus, nei jo vieta jo nebepažins.'),
  (@b18, 7, 11, 'Todėl nesulaikysiu savo burnos: kalbėsiu savo dvasios kančioje; skųsiuosi savo sielos kartume.'),
  (@b18, 7, 12, 'Ar aš esu jūra, ar banginis, kad statai man sargybą?'),
  (@b18, 7, 13, 'Kai sakau: ‘Mano patalas paguos mane, mano guolis palengvins mano skundą’;'),
  (@b18, 7, 14, 'tada tu gąsdini mane sapnais ir baugini mane per regėjimus;'),
  (@b18, 7, 15, 'taip, kad mano siela pasirenka pasmaugimą ir verčiau mirtį, nei mano gyvenimą.'),
  (@b18, 7, 16, 'Aš bjauriuosi juo; nenorėčiau visada gyventi; palik mane ramybėje; nes mano dienos yra tuštybė.'),
  (@b18, 7, 17, 'Kas yra žmogus, kad jį aukštintum ir kad nukreiptum į jį savo širdį,'),
  (@b18, 7, 18, 'kad aplankytum jį kas rytą ir kas akimirką jį mėgintum?'),
  (@b18, 7, 19, 'Kiek ilgai nuo manęs nepasitrauksi ir nepaliksi manęs ramybėje, kol nurysiu seiles?'),
  (@b18, 7, 20, 'Aš nusidėjau; ką tau padaryti, o žmonių sarge? Kodėl pasistatei mane prieš save taikiniu, taip, kad esu sau našta?'),
  (@b18, 7, 21, 'Ir kodėl neatleidi mano nusižengimo ir nepašalini mano neteisybės? Nes dabar miegosiu dulkėse; ir tu manęs ieškosi ryte, bet manęs nebus“.'),
  (@b18, 8, 1, 'Tada šuachas Bildadas atsakė ir tarė:'),
  (@b18, 8, 2, '„Kaip ilgai kalbėsi šituos dalykus? Ir kaip ilgai tavo burnos žodžiai bus kaip stiprus vėjas?'),
  (@b18, 8, 3, 'Argi Dievas iškreipia teismą, ar Visagalis iškreipia teisingumą?'),
  (@b18, 8, 4, 'Jei tavo vaikai prieš jį nusidėjo, ir jis juos atmetė už jų nusižengimą;'),
  (@b18, 8, 5, 'jei laiku ieškotum Dievo ir maldautum Visagalį;'),
  (@b18, 8, 6, 'jei buvai tyras ir tiesus; tai jis tikrai dabar dėl tavęs atsibustų ir padarytų tavo teisumo buveinę klestinčią.'),
  (@b18, 8, 7, 'Nors tavo pradžia buvo maža, tačiau tavo pabaiga labai išaugtų.'),
  (@b18, 8, 8, 'Nes pasiklausk, meldžiu tave, apie ankstesnį amžių ir pasiruošk tam, ką ištyrė jų tėvai'),
  (@b18, 8, 9, '(nes mes esame tik nuo vakar ir nieko nežinome, nes mūsų dienos žemėje yra šešėlis);'),
  (@b18, 8, 10, 'argi jie tavęs nepamokys ir tau nepasakys, ir neištars žodžių iš savo širdies?'),
  (@b18, 8, 11, 'Ar gali vikšris išaugti be purvynės? Ar gali vilkdalgis augti be vandens?'),
  (@b18, 8, 12, 'Dar žaliuodamas ir nenupjautas jis sudžiūsta pirmiau už bet kokią kitą žolę.'),
  (@b18, 8, 13, 'Tokie yra takai visų, kurie pamiršta Dievą; ir veidmainio viltis pražus;'),
  (@b18, 8, 14, 'jų viltis bus iškirsta, ir jų pasitikėjimas bus voratinklis.'),
  (@b18, 8, 15, 'Jis atsirems į savo namus, bet jie neišstovės; jis tvirtai nusitvers už jų, bet jie neišsilaikys.'),
  (@b18, 8, 16, 'Jis žaliuoja prieš saulę, ir jo šaka auga savo sode.'),
  (@b18, 8, 17, 'Jo šaknys apsivyniojusios aplink krūvą ir mato akmenų vietą.'),
  (@b18, 8, 18, 'Jei jis sunaikins jį iš jo vietos, tada ji išsigins jo, sakydama: ‘Aš tavęs nemačiau’.'),
  (@b18, 8, 19, 'Štai šis yra jo kelio džiaugsmas, o iš žemės augs kiti.'),
  (@b18, 8, 20, 'Štai Dievas neatmes tobulojo nei nepadės piktadariams;'),
  (@b18, 8, 21, 'kol pripildys tavo burną juoko ir tavo lūpas džiūgavimo.'),
  (@b18, 8, 22, 'Tie, kurie tavęs nekenčia, bus aprengti gėda; ir nedorėlių gyvenama vieta nueis niekais“.'),
  (@b18, 9, 1, 'Tada Jobas atsakė ir tarė:'),
  (@b18, 9, 2, '„Tikrai žinau, kad taip yra; bet kaip žmogui būti teisiam prieš Dievą?'),
  (@b18, 9, 3, 'Jei jis ginčytųsi su juo, negalėtų jam atsakyti nei į vieną iš tūkstančio.'),
  (@b18, 9, 4, 'Jis išmintingas širdimi ir galingas jėga; kas, užsikietinęs prieš jį, turėjo sėkmę?'),
  (@b18, 9, 5, 'Jis perkelia kalnus jiems nežinant; jis supykęs juos apverčia.'),
  (@b18, 9, 6, 'Jis išpurto žemę iš jos vietos, ir dreba jos stulpai.'),
  (@b18, 9, 7, 'Jis įsako saulei, ir ji nepateka; ir užantspauduoja žvaigždes.'),
  (@b18, 9, 8, 'Jis vienas išskleidžia dangus ir žingsniuoja jūros bangomis.'),
  (@b18, 9, 9, 'Jis padaro Grįžulo ratus, Orioną ir Sietyną bei pietų kambarius.'),
  (@b18, 9, 10, 'Jis daro didžių, neištiriamų dalykų; taip, ir stebuklų be skaičiaus.'),
  (@b18, 9, 11, 'Štai jis praeina pro mane, o aš jo nematau; jis dar paeina toliau, bet aš jo nepastebiu.'),
  (@b18, 9, 12, 'Štai jis atima, kas gali jam sutrukdyti? Kas jam pasakys: ‘Ką darai?’'),
  (@b18, 9, 13, 'Jei Dievas neatitrauks savo pykčio, išdidūs padėjėjai nusilenks po juo.'),
  (@b18, 9, 14, 'Kaip juo mažiau aš jam atsakyčiau ir parinkčiau savo žodžius, samprotauti su juo?'),
  (@b18, 9, 15, 'Nors ir būčiau teisus, tačiau neatsakyčiau jam, bet maldaučiau savo teisėjo.'),
  (@b18, 9, 16, 'Jei šaukčiau, ir jis man atsilieptų, netikėčiau, kad jis išklausė mano balso.'),
  (@b18, 9, 17, 'Nes jis palaužia mane audra ir daugina mano žaizdas be priežasties.'),
  (@b18, 9, 18, 'Jis neleidžia man įkvėpti, bet pripildo mane kartybės.'),
  (@b18, 9, 19, 'Jei kalbėčiau apie stiprybę, štai jis yra stiprus; o jei apie teismą, kas paskirs man laiką apsigynimui?'),
  (@b18, 9, 20, 'Jei teisinčiau save, mano paties burna mane pasmerktų; jei sakyčiau: „Aš tobulas“, ji įrodytų mane esant iškrypusį.'),
  (@b18, 9, 21, 'Nors ir būčiau tobulas, tačiau nepažinočiau savo sielos; aš niekinčiau savo gyvybę.'),
  (@b18, 9, 22, 'Tai vienas dalykas, todėl tai pasakiau: ‘Jis sunaikina tobuląjį ir nedorėlį’.'),
  (@b18, 9, 23, 'Jei rykštė staiga užmuša, jis juoksis iš nekaltųjų išbandymo.'),
  (@b18, 9, 24, 'Žemė yra duota į nedorėlio ranką; jis apdengia jos teisėjų veidą; jei ne, tai kur ir kas jis?'),
  (@b18, 9, 25, 'Na, o mano dienos greitesnės už bėgiką: jos nubėga, jos nemato gero.'),
  (@b18, 9, 26, 'Jos praėjo kaip greiti laivai, kaip erelis, kuris skuba prie grobio.'),
  (@b18, 9, 27, 'Jei sakau: ‘Pamiršiu savo skundą, paliksiu savo sunkumą ir paguosiu save’;'),
  (@b18, 9, 28, 'aš bijau visų savo sielvartų, žinau, kad tu manęs nelaikysi nekaltu.'),
  (@b18, 9, 29, 'Jei esu nedorėlis, tai kam veltui triūsiu?'),
  (@b18, 9, 30, 'Jei nusiplaučiau sniego vandeniu ir padaryčiau savo rankas švarias kaip niekada;'),
  (@b18, 9, 31, 'vis tiek įstumtum mane į griovį, ir mano paties drabužiai bjaurėtųsi manimi.'),
  (@b18, 9, 32, 'Nes jis nėra žmogus kaip aš, kad jam galėčiau atsakyti ir kartu galėtume ateiti į teismą.'),
  (@b18, 9, 33, 'Ir nėra tarp mūsų tarpininko, kuris galėtų uždėti savo ranką ant mūsų abiejų.'),
  (@b18, 9, 34, 'Tepatraukia jis nuo manęs savo lazdą, ir jo baimė tenebaugina manęs;'),
  (@b18, 9, 35, 'tada kalbėčiau ir jo nebijočiau; bet taip nėra su manimi.'),
  (@b18, 10, 1, 'Mano siela pavargo nuo mano gyvenimo; paliksiu savo skundą sau; kalbėsiu savo sielos kartybėje.'),
  (@b18, 10, 2, 'Sakysiu Dievui: ‘Nesmerk manęs; parodyk man, kodėl kovoji su manimi.'),
  (@b18, 10, 3, 'Ar tau gera, kad engtum, kad niekintum savo rankų darbą ir šviestum ant nedorėlių sumanymo?'),
  (@b18, 10, 4, 'Ar tu turi kūno akis? Ar matai, kaip žmogus mato?'),
  (@b18, 10, 5, 'Ar tavo dienos kaip žmogaus dienos? Ar tavo metai kaip žmogaus dienos,'),
  (@b18, 10, 6, 'kad teiraujiesi apie mano neteisybę ir ieškai mano nuodėmės?'),
  (@b18, 10, 7, 'Tu žinai, kad nesu nedorėlis; ir nėra nei vieno, kuris išgelbėtų iš tavo rankos.'),
  (@b18, 10, 8, 'Tavo rankos mane padarė ir suformavo mane iš visų pusių; tačiau tu mane sunaikini.'),
  (@b18, 10, 9, 'Atsimink, meldžiu tave, kad mane padarei kaip molį; ar į dulkes mane sugrąžinsi?'),
  (@b18, 10, 10, 'Argi neišliejai manęs kaip pieno ir nesutraukinai manęs kaip sūrio?'),
  (@b18, 10, 11, 'Apvilkai mane oda ir kūnu, kaulais bei gyslomis mane aptvėrei.'),
  (@b18, 10, 12, 'Gyvybę ir palankumą man suteikei, ir tavo aplankymas saugojo mano dvasią.'),
  (@b18, 10, 13, 'Ir šituos dalykus slėpei savo širdyje; žinau, kad tai yra pas tave.'),
  (@b18, 10, 14, 'Jei nusidedu, tu pasižymi mane ir manęs neišteisinsi dėl mano neteisybės.'),
  (@b18, 10, 15, 'Jei aš nedorėlis, vargas man; o jei esu teisus, vis tiek nepakelsiu savo galvos. Aš esu pilnas gėdos; todėl pažiūrėk į mano vargą;'),
  (@b18, 10, 16, 'nes jis didėja. Tu medžioji mane kaip piktas liūtas; ir vėl pasirodai nuostabus ant manęs.'),
  (@b18, 10, 17, 'Tu atnaujini savo liudytojus prieš mane ir padidini savo pasipiktinimą ant manęs: permainos ir karas yra prieš mane.'),
  (@b18, 10, 18, 'Tai kodėl mane išvedei iš įsčių? O kad būčiau atidavęs dvasią ir jokia akis manęs nebūtų mačiusi!'),
  (@b18, 10, 19, 'Būčiau tarsi manęs nebuvo: iš įsčių būčiau buvęs nuneštas į kapą.'),
  (@b18, 10, 20, 'Argi ne mažai mano dienų? Tad liaukis, palik mane ramybėje, kad galėčiau truputį pasiguosti'),
  (@b18, 10, 21, 'prieš eidamas ten, iš kur negrįšiu, būtent į tamsos šalį ir mirties šešėlį;'),
  (@b18, 10, 22, 'į šalį tamsos, kaip pati tamsa, ir į mirties šešėlio, be jokios tvarkos, kur šviesa yra kaip tamsa’“.'),
  (@b18, 11, 1, 'Tada naamatietis Cofaras atsakė ir tarė:'),
  (@b18, 11, 2, '„Ar į žodžių gausybę neturi būti atsakyta? Ar daug kalbantis turi būti išteisintas?'),
  (@b18, 11, 3, 'Ar tavo melai turėtų nutildyti žmones? Ir kai tyčiojiesi, ar niekas tavęs nesugėdins?'),
  (@b18, 11, 4, 'Nes tu sakei: ‘Mano mokslas tyras’ ir: ‘Aš esu švarus tavo akyse’.'),
  (@b18, 11, 5, 'O kad Dievas kalbėtų ir atvertų savo lūpas prieš tave;'),
  (@b18, 11, 6, 'ir kad tau parodytų išminties paslaptis, kad jų yra dvigubai daugiau negu yra! Todėl žinok, kad Dievas iš tavęs reikalauja mažiau, negu nusipelnė tavo neteisybė.'),
  (@b18, 11, 7, 'Ar tu gali tyrinėdamas sužinoti apie Dievą? Ar gali iki tobulumo sužinoti apie Visagalį?'),
  (@b18, 11, 8, 'Jis yra aukštas, kaip dangus; ką tu gali padaryti? Gilesnis už pragarą; ką tu gali žinoti?'),
  (@b18, 11, 9, 'Jo matas ilgesnis už žemę ir platesnis už jūrą.'),
  (@b18, 11, 10, 'Jei jis iškerta, užrakina ar surenka, tai kas jam gali sutrukdyti?'),
  (@b18, 11, 11, 'Nes jis pažįsta tuščius žmones; jis mato ir nedorybę; tai ar jis į tai neatsižvelgs?'),
  (@b18, 11, 12, 'Nes tuščias žmogus nori būti išmintingas, nors žmogus gimsta kaip laukinio asilo jauniklis.'),
  (@b18, 11, 13, 'Jei paruoši savo širdį ir ištiesi savo rankas į jį;'),
  (@b18, 11, 14, 'jei neteisybė yra tavo rankoje, atitolink ją ir neleisk nedorybei gyventi savo padangtėse.'),
  (@b18, 11, 15, 'Nes tada pakelsi savo veidą be dėmės; taip, tu būsi tvirtas ir nebijosi;'),
  (@b18, 11, 16, 'kadangi pamirši savo vargą ir jį atsiminsi kaip vandenis, kurie nuteka;'),
  (@b18, 11, 17, 'ir tavo amžius bus šviesesnis už vidudienį; tu nušvisi, tu būsi kaip rytas.'),
  (@b18, 11, 18, 'Ir būsi saugus, nes yra viltis; taip, tu apsikasi ir saugiai ilsėsies.'),
  (@b18, 11, 19, 'Taipogi atsigulsi, ir niekas tavęs neišgąsdins; taip, daugelis nuolankiai tavęs prašys.'),
  (@b18, 11, 20, 'Bet nedorėlių akys nusilps, ir jie nepabėgs, o jų viltis bus kaip dvasios atidavimas“.'),
  (@b18, 12, 1, 'Ir Jobas atsakė ir tarė:'),
  (@b18, 12, 2, '„Be abejonės jūs esate tik žmonės, ir su jumis mirs išmintis.'),
  (@b18, 12, 3, 'Bet aš turiu supratimą, kaip ir jūs; aš nesu už jus menkesnis; taip, kas nežino tokių dalykų, kaip šie?'),
  (@b18, 12, 4, 'Esu kaip savo artimo išjuoktas, kuris šaukiasi Dievo, o jis jam atsako; teisus, tiesus žmogus yra išjuoktas.'),
  (@b18, 12, 5, 'Tas, kuris yra bepaslystantis kojomis, yra kaip žibintas, paniekintas mintyse to, kuris yra ramybėje.'),
  (@b18, 12, 6, 'Plėšikų padangtės klesti, ir kurstantys Dievą yra saugūs; į jų ranką Dievas gausiai atneša.'),
  (@b18, 12, 7, 'Bet paklausk dabar gyvulių, ir jie tave pamokys; ir oro skrajūnų, ir jie tau pasakys;'),
  (@b18, 12, 8, 'arba kalbėk žemei, ir ji tave pamokys; ir tau paskelbs jūros žuvys.'),
  (@b18, 12, 9, 'Kas visame tame nežino, kad tai padarė VIEŠPATIES ranka?'),
  (@b18, 12, 10, 'Jo rankoje yra kiekvieno gyvio siela ir visos žmonijos kvapas.'),
  (@b18, 12, 11, 'Argi ne ausis mėgina žodžius ir ne burna ragauja savo valgį?'),
  (@b18, 12, 12, 'Su senoliu yra išmintis; ir dienų ilgume – supratimas.'),
  (@b18, 12, 13, 'Su juo yra išmintis ir stiprybė, jis turi patarimą ir supratimą.'),
  (@b18, 12, 14, 'Štai jis nugriauna, ir negali būti atstatyta; jis užrakina žmogų, ir negali būti atidaroma.'),
  (@b18, 12, 15, 'Štai jis sulaiko vandenis, ir jie išdžiūsta; taip pat jis juos išsiunčia, ir jie apverčia žemę.'),
  (@b18, 12, 16, 'Su juo stiprybė ir išmintis; suklaidintasis ir klaidintojas yra jo.'),
  (@b18, 12, 17, 'Jis nuveda patarėjus apiplėštus ir teisėjus padaro kvailiais.'),
  (@b18, 12, 18, 'Jis atriša karalių pančius ir apjuosia jų strėnas juosta.'),
  (@b18, 12, 19, 'Jis nuveda kunigaikščius apiplėštus ir nuverčia galinguosius.'),
  (@b18, 12, 20, 'Jis pašalina kalbą nuo patikimųjų ir iš senųjų atima supratimą.'),
  (@b18, 12, 21, 'Jis išlieja panieką ant kunigaikščių ir susilpnina galingųjų stiprybę.'),
  (@b18, 12, 22, 'Jis atidengia gylybes iš tamsos ir išveda švieson mirties šešėlį.'),
  (@b18, 12, 23, 'Jis padaugina tautas ir jas sunaikina; jis praplatina tautas ir vėl jas paankština.'),
  (@b18, 12, 24, 'Jis atima širdį žemės tautų vadams ir padaro, kad jie klaidžiotų dykumoje, kur nėra jokio kelio.'),
  (@b18, 12, 25, 'Jie grabalioja tamsoje be šviesos, ir jis padaro, kad jie svirduliuotų kaip girti.'),
  (@b18, 13, 1, 'Štai mano akis visa tai matė, mano ausis girdėjo ir tai suprato.'),
  (@b18, 13, 2, 'Ką jūs žinote, tą ir aš žinau; aš ne menkesnis už jus.'),
  (@b18, 13, 3, 'Aš tikrai kalbėčiau Visagaliui, ir noriu samprotauti su Dievu.'),
  (@b18, 13, 4, 'Bet jūs esate melų kalviai, jūs visi beverčiai gydytojai.'),
  (@b18, 13, 5, 'O kad jūs visiškai nutiltumėte! Tai būtų jūsų išmintis.'),
  (@b18, 13, 6, 'Dabar paklausykite mano samprotavimų ir klausykite mano lūpų apsigynimo.'),
  (@b18, 13, 7, 'Ar kalbėsite nedorai už Dievą ir kalbėsite apgaulingai už jį?'),
  (@b18, 13, 8, 'Ar jūs atsižvelgsite į jo asmenybę, ar jūs kovosite už Dievą?'),
  (@b18, 13, 9, 'Ar gerai, kai jis jus ištirtų? Ar pasijuoksite iš jo, kaip žmonės juokiasi vienas iš kito?'),
  (@b18, 13, 10, 'Jis tikrai jus bars, jei slapčia atsižvelgiate į asmenis.'),
  (@b18, 13, 11, 'Ar jo didybė jūsų neišgąsdins, ar jo didelė baimė jūsų neužpuls?'),
  (@b18, 13, 12, 'Jūsų priminimai prilygsta pelenams, jūsų kūnai – molio kūnams.'),
  (@b18, 13, 13, 'Nutilkite, palikite mane ramybėje, kad galėčiau kalbėti, ir man teatsitinka, kas beatsitiks.'),
  (@b18, 13, 14, 'Kodėl imu savo kūną į savo dantis ir savo gyvybę dedu į savo ranką?'),
  (@b18, 13, 15, 'Nors jis mane ir užmuštų, vis tiek juo pasitikėsiu; bet aš išlaikysiu savo kelius jo akivaizdoje.'),
  (@b18, 13, 16, 'Jis taipogi bus mano išgelbėjimas; nes veidmainis neateis jo akivaizdon.'),
  (@b18, 13, 17, 'Atidžiai paklausykite mano kalbos ir mano skelbimo savo ausimis.'),
  (@b18, 13, 18, 'Štai aš paruošiau savo bylą; žinau, kad būsiu išteisintas.'),
  (@b18, 13, 19, 'Kas yra tas, kuris bylinėsis su manimi? Nes dabar, jei sulaikysiu savo liežuvį, atiduosiu dvasią.'),
  (@b18, 13, 20, 'Tik nedaryk man dviejų dalykų; tada nesislėpsiu nuo tavęs.'),
  (@b18, 13, 21, 'Atitolink nuo manęs savo ranką; ir tavo didelė baimė tenegąsdina manęs.'),
  (@b18, 13, 22, 'Tada pašauk, ir aš atsiliepsiu; arba leisk man kalbėti, o tu man atsakyk.'),
  (@b18, 13, 23, 'Kiek yra mano neteisybių ir nuodėmių? Duok man pažinti mano nusižengimą ir mano nuodėmę.'),
  (@b18, 13, 24, 'Kodėl slepi savo veidą ir mane laikai savo priešu?'),
  (@b18, 13, 25, 'Ar sulaužysi ten ir atgal gainiojamą lapą ir vysies sudžiūvusį šiaudą?'),
  (@b18, 13, 26, 'Nes tu rašai prieš mane karčius dalykus ir darai, kad paveldėčiau savo jaunystės neteisybes.'),
  (@b18, 13, 27, 'Taip pat tu įtveri mano kojas į trinką ir įdėmiai stebi visus mano takus; tu uždedi žymę ant mano kojų kulnų.'),
  (@b18, 13, 28, 'O jis kaip supuvęs daiktas sunyksta, kaip drabužis, suėstas kandžių.'),
  (@b18, 14, 1, 'Žmogus, gimęs iš moters, yra nedaugelio dienų ir kupinas vargų.'),
  (@b18, 14, 2, 'Jis išdygsta kaip gėlė ir yra nupjaunamas; jis pabėga kaip šešėlis ir nepasilieka.'),
  (@b18, 14, 3, 'Ar tu atveri savo akis į tokį ir nuvedi mane į teismą su tavimi?'),
  (@b18, 14, 4, 'Kas gali iš nešvaraus dalyko išgauti švarų? Nei vienas.'),
  (@b18, 14, 5, 'Kadangi nustatytos jo dienos, jo mėnesių skaičius yra pas tave, tu nustatei jo ribas, kurių jis negali peržengti;'),
  (@b18, 14, 6, 'nusigręžk nuo jo, kad jis pailsėtų, kol jis kaip samdinys užbaigs savo dieną.'),
  (@b18, 14, 7, 'Nes medžiui yra viltis, jei jį nukerta, kad jis atžels, ir kad jo gležna šaka nesiliaus.'),
  (@b18, 14, 8, 'Nors žemėje jo šaknys pasensta ir dirvoje numiršta jo kelmas;'),
  (@b18, 14, 9, 'tačiau nuo vandens kvapo jis išleis pumpurus ir išleis šakas kaip sodinys.'),
  (@b18, 14, 10, 'Bet žmogus miršta ir suyra; taip, žmogus išleidžia dvasią, ir kur jis yra?'),
  (@b18, 14, 11, 'Kaip vandenys dingsta iš jūros ir kaip upė išsenka ir išdžiūsta;'),
  (@b18, 14, 12, 'taip atsigula žmogus ir nebeatsikelia: kol dangūs nepasibaigs, jie neatsibus nei nebus prikelti iš savo miego.'),
  (@b18, 14, 13, 'O kad paslėptum mane kape, kad laikytum mane slaptoje, kol praeis tavo rūstybė, kad paskirtum man nustatytą laiką ir mane atsimintum!'),
  (@b18, 14, 14, 'Jei žmogus miršta, ar jis vėl begyvens? Visas savo paskirto laiko dienas lauksiu, kol man ateis permaina.'),
  (@b18, 14, 15, 'Tu pašauksi, o aš tau atsiliepsiu; tu trokši savo rankų darbo.'),
  (@b18, 14, 16, 'Nes dabar skaičiuoji mano žingsnius; ar tu nestebi mano nuodėmės?'),
  (@b18, 14, 17, 'Mano nusižengimas užantspauduotas maišelyje, ir tu užsiuvai mano neteisybę.'),
  (@b18, 14, 18, 'Ir tikrai kalnas griūdamas nueina niekais, ir uola pasitraukia iš savo vietos.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b18, 14, 19, 'Vandenys nutrina akmenis; tu nuplauni tai, kas išauga iš žemės dulkių; ir tu sunaikini žmogaus viltį.'),
  (@b18, 14, 20, 'Tu nugali jį visą laiką, ir jis dingsta; tu pakeiti jo veidą ir jį išvarai.'),
  (@b18, 14, 21, 'Jo sūnūs bus gerbiami, o jis to nežino; jie nužeminti, bet jis to apie juos nepastebi.'),
  (@b18, 14, 22, 'Bet jo kūnas ant jo turės skausmus, ir jo siela jo viduje – liūdės“.'),
  (@b18, 15, 1, 'Tada temanas Elifazas atsakė ir tarė:'),
  (@b18, 15, 2, '„Ar išmintingas žmogus taria tuščią pažinimą ir pripildo savo pilvą rytų vėjo?'),
  (@b18, 15, 3, 'Ar jis samprotauja nenaudinga šneka ar kalbomis, kuriomis negali daryti nieko gero?'),
  (@b18, 15, 4, 'Taip, tu atmeti baimę ir sulaikai maldą Dievo akivaizdoje.'),
  (@b18, 15, 5, 'Nes tavo burna ištaria tavo neteisybę, ir tu pasirenki klastingųjų liežuvį.'),
  (@b18, 15, 6, 'Tavo paties burna pasmerkia tave, o ne aš; taip, tavo paties lūpos liudija prieš tave.'),
  (@b18, 15, 7, 'Ar tu pirmas gimęs žmogus? Ar pirmiau kalvų buvai padarytas?'),
  (@b18, 15, 8, 'Ar girdėjai Dievo paslaptį, ar sau pasilaikei išmintį?'),
  (@b18, 15, 9, 'Ką žinai, ko mes nežinome? Ką supranti, ko nebūtų mumyse?'),
  (@b18, 15, 10, 'Pas mus yra ir žilagalvių, ir labai senų, daug senesnių už tavo tėvą.'),
  (@b18, 15, 11, 'Ar per menkos tau Dievo paguodos, ar turi kokią paslaptį?'),
  (@b18, 15, 12, 'Kodėl tavo širdis tave nusineša? Ir į ką mirkčioja tavo akys,'),
  (@b18, 15, 13, 'kad nukreipi savo dvasią prieš Dievą ir leidi tokiems žodžiams išeiti iš tavo burnos?'),
  (@b18, 15, 14, 'Kas yra žmogus, kad būtų švarus, ir gimęs iš moters, kad būtų teisus?'),
  (@b18, 15, 15, 'Štai savo šventaisiais jis nepasikliauja; taip, dangūs nėra švarūs jo akyse.'),
  (@b18, 15, 16, 'Tai kiek bjauresnis ir purvinesnis yra žmogus, geriantis neteisybę kaip vandenį?'),
  (@b18, 15, 17, 'Aš tau apsakysiu, paklausyk manęs; ir tai, ką mačiau, paskelbsiu;'),
  (@b18, 15, 18, 'ką išminčiai papasakojo iš savo tėvų ir to neslėpė;'),
  (@b18, 15, 19, 'jiems vieniems buvo duota žemė, ir joks svetimšalis nevaikščiojo tarp jų.'),
  (@b18, 15, 20, 'Nedorėlis su skausmu triūsia per visas savo dienas, ir metų skaičius paslėptas nuo engėjo.'),
  (@b18, 15, 21, 'Labai bauginantis garsas jo ausyse; klestėjimo metu jį užpuls naikintojas.'),
  (@b18, 15, 22, 'Jis netiki, kad sugrįš iš tamsos, ir jis yra laukiamas kalavijo.'),
  (@b18, 15, 23, 'Jis klaidžioja visur ieškodamas duonos, sakydamas: „Kur ji?“ Jis žino, kad tamsos diena paruošta jo rankoje.'),
  (@b18, 15, 24, 'Jį gąsdins vargas ir kančia; jie nugalės jį kaip karalius, pasiruošęs mūšiui.'),
  (@b18, 15, 25, 'Nes jis ištiesia prieš Dievą savo ranką ir stiprina save prieš Visagalį.'),
  (@b18, 15, 26, 'Jis bėga ant jo – ant jo sprando, ant jo skydų iškilumų.'),
  (@b18, 15, 27, 'Nes jis apdengia savo veidą riebalais ir užsiaugina riebalų klostes ant savo šonų.'),
  (@b18, 15, 28, 'Jis gyvena nuniokotuose miestuose, namuose, kuriuose niekas negyvena, kurie jau bepasidarantys krūvomis.'),
  (@b18, 15, 29, 'Jis nebus turtingas, nei jo turtas neišliks, nei neprailgins jis jo tobulumo žemėje.'),
  (@b18, 15, 30, 'Jis neišeis iš tamsos; jo šakas sudžiovins liepsna, ir nuo jo burnos kvapo jis išnyks.'),
  (@b18, 15, 31, 'Tegul apgautasis nepasitiki tuštybe; nes tuštybė bus jo atlygis.'),
  (@b18, 15, 32, 'Tai bus įvykdyta dar prieš jo laiką, ir jo šaka nežaliuos.'),
  (@b18, 15, 33, 'Jis kaip vynmedis nupurtys savo neprinokusias vynuoges ir kaip alyvmedis numes savo žiedus.'),
  (@b18, 15, 34, 'Nes veidmainių susirinkimas bus nuniokotas, ir ugnis suris kyšininkavimo padangtes.'),
  (@b18, 15, 35, 'Jie pastoja piktu ir pagimdo tuštybę, ir jų pilvas paruošia apgaulę“.'),
  (@b18, 16, 1, 'Tada Jobas atsakė ir tarė:'),
  (@b18, 16, 2, '„Tokių dalykų daug esu girdėjęs; apgailėtini guodėjai jūs visi.'),
  (@b18, 16, 3, 'Ar tušti žodžiai turės pabaigą? Arba kas tave padrąsina, kad atsakai?'),
  (@b18, 16, 4, 'Aš irgi galėčiau kalbėti kaip jūs; jei jūsų siela būtų mano sielos vietoje, aš galėčiau užversti jus žodžiais ir kraipyti savo galvą prieš jus.'),
  (@b18, 16, 5, 'Bet aš jus pastiprinčiau savo burna, ir mano lūpų judesiai palengvintų jūsų sielvartą.'),
  (@b18, 16, 6, 'Nors aš ir kalbu, mano sielvartas nepalengvėjo; nors ir susilaikau, kuo man lengviau?'),
  (@b18, 16, 7, 'Bet dabar jis išvargino mane; tu ištuštinai visą mano būrį.'),
  (@b18, 16, 8, 'Tu pripildei mane raukšlių, kas yra liudijimas prieš mane; ir mano liesumas, kylantis manyje, liudija man į veidą.'),
  (@b18, 16, 9, 'Jis, kuris nekenčia manęs, savo rūstybėje drasko mane; jis griežia ant manęs savo dantimis; mano priešas aštrina savo akis į mane.'),
  (@b18, 16, 10, 'Jie išsižiojo prieš mane savo burna; jie smogė man į skruostą priekaištingai; jie susirinko prieš mane.'),
  (@b18, 16, 11, 'Dievas atidavė mane bedieviams ir perdavė mane į nedorėlių rankas.'),
  (@b18, 16, 12, 'Buvau ramybėje, bet jis perlaužė mane pusiau; taip pat, nutvėręs mane už sprando, išpurtė mane į gabalus ir pastatė mane sau taikiniu.'),
  (@b18, 16, 13, 'Jo lankininkai apsupa mane, jis perskelia mano inkstus ir nesigaili; jis išlieja ant žemės mano tulžį.'),
  (@b18, 16, 14, 'Jis pralaužia mane spraga po spragos, jis bėga į mane kaip milžinas.'),
  (@b18, 16, 15, 'Užsiuvau ašutinę sau ant odos ir suteršiau dulkėse savo ragą.'),
  (@b18, 16, 16, 'Mano veidas subjuręs nuo verkimo, o ant mano akių vokų – mirties šešėlis;'),
  (@b18, 16, 17, 'ne dėl kokio tai neteisingumo mano rankose; taipogi mano malda yra tyra.'),
  (@b18, 16, 18, 'O žeme, neuždenk mano kraujo, ir tenebūna vietos mano šauksmui.'),
  (@b18, 16, 19, 'Ir dabar, štai danguje yra mano liudytojas, mano liudijimas aukštumoje.'),
  (@b18, 16, 20, 'Mano draugai paniekina mane; bet mano akis lieja ašaras Dievui.'),
  (@b18, 16, 21, 'O kad kas apgintų žmogų prieš Dievą, kaip žmogus apgina savo artimą!'),
  (@b18, 16, 22, 'Keliems metams praėjus nueisiu keliu, kuriuo nebesugrįšiu.'),
  (@b18, 17, 1, 'Mano kvėpavimas sugedęs, mano dienos užgesusios, kapai man paruošti.'),
  (@b18, 17, 2, 'Argi išjuokėjai nėra su manimi? Ir argi mano akys nepasilieka jų kurstyme.'),
  (@b18, 17, 3, 'Padėk dabar, padėk mane užstatu pas save; kas sukirs su manimi rankomis?'),
  (@b18, 17, 4, 'Nes tu paslėpei jų širdis nuo supratimo; todėl jų neišaukštinsi.'),
  (@b18, 17, 5, 'Kas kalba meilikaujančiai savo draugams, to vaikų akys nusilps.'),
  (@b18, 17, 6, 'Jis mane dar padarė liaudies priežodžiu; o seniau aš buvau kaip būgnelis.'),
  (@b18, 17, 7, 'Taipogi aptemo nuo sielvarto ir mano akis, ir visi mano nariai kaip šešėlis.'),
  (@b18, 17, 8, 'Tiesieji bus nuo to apstulbę, o nekaltasis sužadins save prieš veidmainį.'),
  (@b18, 17, 9, 'Taip pat teisusis laikysis savo kelio, o tas, kas turi švarias rankas, stiprės ir stiprės.'),
  (@b18, 17, 10, 'Bet kas dėl jūsų visų, grįžkite ir dabar ateikite; nes negaliu rasti nei vieno išmintingo tarp jūsų.'),
  (@b18, 17, 11, 'Mano dienos praėjo, sudužo mano ketinimai – mano širdies mintys.'),
  (@b18, 17, 12, 'Naktį jie paverčia diena; šviesa yra trumpa dėl tamsos.'),
  (@b18, 17, 13, 'Jei laukiu, kapas yra mano namai; tamsybėje pasiklojau savo patalą.'),
  (@b18, 17, 14, 'Aš tariau sugedimui: ‘Tu mano tėvas’; kirmėlei: ‘Tu mano motina ir mano sesuo’.'),
  (@b18, 17, 15, 'Ir kur dabar mano viltis? O kas dėl mano vilties – kas ją bepamatys?'),
  (@b18, 17, 16, 'Jos nužengs prie duobės skląsčių, kai mūsų poilsis kartu bus dulkėse“.'),
  (@b18, 18, 1, 'Tada šuachas Bildadas atsakė ir tarė:'),
  (@b18, 18, 2, '„Kaip ilgai tai dar bus, kol baigsite žodžius? Stebėkite, o po to kalbėsime.'),
  (@b18, 18, 3, 'Kodėl mes laikomi gyvuliais ir laikomi bjauriais jūsų akyse?'),
  (@b18, 18, 4, 'Jis draskosi iš pykčio; ar dėl tavęs žemė bus apleista? Ar uola pasitrauks iš savo vietos?'),
  (@b18, 18, 5, 'Taip, nedorėlio šviesa užges, ir nebešvies jo ugnies kibirkštis.'),
  (@b18, 18, 6, 'Šviesa jo padangtėje bus tamsi, ir jo žvakė užges su juo.'),
  (@b18, 18, 7, 'Bus suvaržyti jo stiprybės žingsniai, ir jo paties sumanymas jį parblokš.'),
  (@b18, 18, 8, 'Nes savo paties kojomis jis įmestas į tinklą, ir jis vaikšto žabangomis.'),
  (@b18, 18, 9, 'Jį nutvers už kulno spąstai, ir plėšikas jį įveiks.'),
  (@b18, 18, 10, 'Žabangos padėtos jam ant žemės ir spąstai jam ant kelio.'),
  (@b18, 18, 11, 'Siaubai jį gąsdins iš visų pusių ir nuvarys jį nuo kojų.'),
  (@b18, 18, 12, 'Jo stiprybė bus bado išsekinta, ir žlugimas bus pasiruošęs prie jo šono.'),
  (@b18, 18, 13, 'Tai suės jo odos stiprumą; mirties pirmagimis suės jo stiprybę.'),
  (@b18, 18, 14, 'Jo užtikrintumas bus išrautas iš jo padangtės, ir tai nuves jį pas siaubų karalių.'),
  (@b18, 18, 15, 'Tai gyvens jo padangtėje, nes ji nėra jo; siera bus apibarstyta ant jo buveinės.'),
  (@b18, 18, 16, 'Jo šaknys nudžius apačioje, o jo šaka bus iškirsta viršuje.'),
  (@b18, 18, 17, 'Jo atminimas pradings iš žemės, ir jis neturės vardo gatvėje.'),
  (@b18, 18, 18, 'Jis bus išvytas iš šviesos į tamsą ir išvarytas iš pasaulio.'),
  (@b18, 18, 19, 'Jis neturės nei sūnaus, nei vaikaičio savo tautoje, nei jokio išlikusio savo buveinėse.'),
  (@b18, 18, 20, 'Po jo atėję bus apstulbinti jo dienos, kaip prieš tai vaikščioję buvo išgąsdinti.'),
  (@b18, 18, 21, 'Tikrai tokios yra nedorėlio buveinės, ir tai yra vieta to, kuris nepažįsta Dievo“.'),
  (@b18, 19, 1, 'Tada Jobas atsakė ir tarė:'),
  (@b18, 19, 2, '„Kaip ilgai varginsite mano sielą ir plėšysite mane į gabalus žodžiais?'),
  (@b18, 19, 3, 'Šiuos dešimt kartų jūs man priekaištavote; jūs nesigėdijate tapdami man svetimi.'),
  (@b18, 19, 4, 'O jei iš tikrųjų suklydau, mano suklydimas pasilieka su manimi.'),
  (@b18, 19, 5, 'Jei iš tikrųjų norite didžiuotis prieš mane ir prieš mane iškelti mano gėdą,'),
  (@b18, 19, 6, 'tai žinokite, kad Dievas mane pargriovė ir savo tinklu mane apsupo.'),
  (@b18, 19, 7, 'Štai šaukiu dėl skriaudos, bet nesu išgirstas; šaukiu garsiai, bet nėra teismo.'),
  (@b18, 19, 8, 'Jis užtvėrė man kelią, kad negaliu praeiti, ir ant mano takų užleido tamsą.'),
  (@b18, 19, 9, 'Jis nuplėšė nuo manęs mano šlovę ir nuėmė vainiką nuo mano galvos.'),
  (@b18, 19, 10, 'Jis mane naikino iš visų pusių, ir aš dingęs; ir pašalino mano viltį kaip medį.'),
  (@b18, 19, 11, 'Jis uždegė prieš mane savo rūstybę, ir jis laiko mane vienu iš savo priešų.'),
  (@b18, 19, 12, 'Jo pulkai ateina kartu, iškelia savo kelią prieš mane ir stovyklauja aplink mano padangtę.'),
  (@b18, 19, 13, 'Jis atitolino mano brolius nuo manęs, ir mano pažįstami tikrai nutolę nuo manęs.'),
  (@b18, 19, 14, 'Mano giminaičiai dingo ir mano artimi draugai mane pamiršo.'),
  (@b18, 19, 15, 'Mano namuose gyvenantys ir mano tarnaitės laiko mane svetimu; esu svetimas jų akyse.'),
  (@b18, 19, 16, 'Pašaukiau savo tarną, bet jis neatsakė; savo burna jį maldavau.'),
  (@b18, 19, 17, 'Mano kvapas svetimas mano žmonai, nors aš maldavau dėl savo paties kūno vaikų.'),
  (@b18, 19, 18, 'Taip, jauni vaikai mane niekino: aš atsikėliau, o jie kalbėjo prieš mane.'),
  (@b18, 19, 19, 'Manimi bjaurėjosi visi mano artimiausi draugai; o tie, kuriuos mylėjau, atsigręžė prieš mane.'),
  (@b18, 19, 20, 'Prie mano odos ir mano kūno prilipo mano kaulai, ir aš išsigelbėjau tik su savo dantų oda.'),
  (@b18, 19, 21, 'O jūs, mano draugai, pasigailėkite manęs, pasigailėkite manęs; nes Dievo ranka palietė mane.'),
  (@b18, 19, 22, 'Kodėl mane persekiojate kaip Dievas ir nepasisotinate mano kūnu?'),
  (@b18, 19, 23, 'O kad dabar mano žodžiai būtų užrašyti! O kad jie būtų išspausdinti knygoje!'),
  (@b18, 19, 24, 'Kad jie būtų įrėžti geležiniu braižikliu ir švinu amžiams į uolą!'),
  (@b18, 19, 25, 'Nes žinau, kad mano atpirkėjas gyvas ir kad jis paskutinę dieną atsistos ant žemės;'),
  (@b18, 19, 26, 'ir nors po mano odos kirminai sunaikins šį kūną, tačiau savo kūne aš regėsiu Dievą;'),
  (@b18, 19, 27, 'aš pats jį pamatysiu, mano akys žiūrės, o ne kitas; nors mano inkstai nyksta mano viduje.'),
  (@b18, 19, 28, 'Bet jūs turėtumėte sakyti: ‘Kodėl mes jį persekiojame?’, kadangi to dalyko šaknis aptikta manyje.'),
  (@b18, 19, 29, 'Bijokite kalavijo; nes rūstybė atneša kalavijo bausmes, kad žinotumėte, jog yra teismas“.'),
  (@b18, 20, 1, 'Tada naamatietis Cofaras atsakė ir tarė:'),
  (@b18, 20, 2, '„Todėl mano mintys verčia mane atsakyti ir dėl to aš skubu.'),
  (@b18, 20, 3, 'Girdėjau mano priekaišto atkirtį, ir mano supratimo dvasia verčia mane atsakyti.'),
  (@b18, 20, 4, 'Ar nežinai to nuo seno, nuo tada, kai žmogus buvo pastatytas žemėje,'),
  (@b18, 20, 5, 'kad nedorėlių triumfas yra trumpas, ir veidmainių džiaugsmas tik akimirkai?'),
  (@b18, 20, 6, 'Nors jo puikybė pakiltų iki dangų ir jo galva paliestų debesis;'),
  (@b18, 20, 7, 'tačiau jis amžiams pražus kaip jo paties mėšlas; tie, kurie jį matė, sakys: ‘Kur jis?’'),
  (@b18, 20, 8, 'Kaip sapnas jis nuskris ir nebebus atrastas; taip, jis bus nuvytas kaip nakties regėjimas.'),
  (@b18, 20, 9, 'Taip pat akis, kuri jį matė, jo nebematys; ir jo nebeišvys jo vieta.'),
  (@b18, 20, 10, 'Jo vaikai sieks įtikti beturčiams, ir jo rankos sugrąžins jų turtą.'),
  (@b18, 20, 11, 'Jo kaulai pilni jo jaunystės nuodėmės, kuri gulsis su juo į dulkes.'),
  (@b18, 20, 12, 'Nors nedorybė saldi jo burnoje, nors jis ją slepia po liežuviu,'),
  (@b18, 20, 13, 'nors jis ją tausoja ir jos neatsisako, bet ją vis laiko savo burnoje;'),
  (@b18, 20, 14, 'tačiau jo valgis pasikeis jo viduriuose, tai nuodingų gyvačių tulžis jo viduje.'),
  (@b18, 20, 15, 'Jis prarijo turtus ir juos vėl išvems; iš jo pilvo Dievas juos išmes.'),
  (@b18, 20, 16, 'Jis čiulps nuodingų gyvačių nuodus; jį nužudys angies liežuvis.'),
  (@b18, 20, 17, 'Jis nematys medaus ir sviesto upių, srovių ir upelių.'),
  (@b18, 20, 18, 'Tai, dėl ko jis triūsė, jis turės sugrąžinti ir to nepraryti; sugrąžinimas bus pagal jo nuosavybę, ir jis tuo nepasidžiaugs.'),
  (@b18, 20, 19, 'Nes jis engė ir paliko beturtį; nes jis prievarta paėmė namus, kurių nestatė;'),
  (@b18, 20, 20, 'jis tikrai nejaus ramumo savo pilve, jis neišsaugos iš to, ko jis geidė.'),
  (@b18, 20, 21, 'Iš jo valgio nieko neliks; todėl niekas neieškos jo turto.'),
  (@b18, 20, 22, 'Savo pakankamumo pilnatvėje jam bus ankšta; ant jo ateis kiekviena nedorėlio ranka.'),
  (@b18, 20, 23, 'Kai jis ruošis prikimšti savo pilvą, Dievas mes į jį savo įtūžusią rūstybę, ir ja lis ant jo jam bevalgant.'),
  (@b18, 20, 24, 'Jis bėgs nuo geležinio ginklo, ir jį pervers plieninis lankas.'),
  (@b18, 20, 25, 'Jis ištrauktas ir išlenda iš kūno; taip, žibantis kalavijas išlenda iš jo tulžies; jį apima siaubai.'),
  (@b18, 20, 26, 'Visa tamsa bus paslėpta jo slaptose vietose; jį prarys neįpūsta ugnis; bus blogai išlikusiam jo padangtėje.'),
  (@b18, 20, 27, 'Dangus atskleis jo neteisybę; ir žemė sukils prieš jį.'),
  (@b18, 20, 28, 'Jo namų prieaugis pasitrauks, ir jo turtas išplauks jo rūstybės dieną.'),
  (@b18, 20, 29, 'Tai nedorėlio dalis nuo Dievo ir Dievo jam skirtas palikimas“.'),
  (@b18, 21, 1, 'Bet Jobas atsakė ir tarė:'),
  (@b18, 21, 2, '„Atidžiai paklausykite mano kalbos, ir tai tebūna jūsų paguodos.'),
  (@b18, 21, 3, 'Pakęskite mane, kad kalbėčiau; o kai būsiu pakalbėjęs, tyčiokitės.'),
  (@b18, 21, 4, 'Kas dėl manęs, argi mano skundas žmogui? O jei taip būtų, kodėl mano dvasiai nebūti sunerimusiai?'),
  (@b18, 21, 5, 'Pažvelkite į mane ir apstulbkite, ir užsidėkite ranką ant burnos.'),
  (@b18, 21, 6, 'Net prisiminęs išsigąstu, ir drebulys suima mano kūną.'),
  (@b18, 21, 7, 'Kodėl nedorėliai gyvena, pasensta, taip, yra galingi jėga?'),
  (@b18, 21, 8, 'Jų sėkla įtvirtinta su jais jų akyse, jų palikuonys jų akyse.'),
  (@b18, 21, 9, 'Jų namai apsaugoti nuo baimės, ir Dievo lazda nėra ant jų.'),
  (@b18, 21, 10, 'Jų bulius apvaisina ir neišsenka; jų karvė apsiveršiuoja ir neišsimeta.'),
  (@b18, 21, 11, 'Jie išleidžia savo mažylius kaip kaimenę, ir jų vaikai šoka.'),
  (@b18, 21, 12, 'Jie ima tambūriną bei arfą ir džiaugiasi skambant vargonams.'),
  (@b18, 21, 13, 'Jie praleidžia savo dienas turtuose ir per akimirksnį nužengia į kapą.'),
  (@b18, 21, 14, 'Todėl jie sako Dievui: ‘Atsitrauk nuo mūsų; nes mes nenorime pažinti tavo kelių.'),
  (@b18, 21, 15, 'Kas yra Visagalis, kad jam tarnautume, ir kokią naudą turėsime, jei melsimės jam?’'),
  (@b18, 21, 16, 'Štai jų gerovė nėra jų rankoje; nedorėlių patarimas yra toli nuo manęs.'),
  (@b18, 21, 17, 'Kaip dažnai užgęsta nedorėlių žvakė! Kaip dažnai ant jų užeina jų sunaikinimas! Dievas supykęs išdalija sielvartus.'),
  (@b18, 21, 18, 'Jie yra kaip ražiena prieš vėją ir kaip pelai, kuriuos nuneša audra.'),
  (@b18, 21, 19, 'Dievas kaupia jo vaikams jo neteisybę; jis jam atlygina, ir jis tai žinos.'),
  (@b18, 21, 20, 'Jo akys pamatys jo pražūtį, ir jis gers iš Visagalio rūstybės.'),
  (@b18, 21, 21, 'Nes kokį pasitenkinimą jis turi savo namais po savęs, kai jo mėnesių skaičius nukirstas ties viduriu?'),
  (@b18, 21, 22, 'Ar kas pamokys Dievą pažinimo? Juk jis teisia tuos, kurie yra aukštai?'),
  (@b18, 21, 23, 'Vienas miršta kupinas jėgų, būdamas visiškai be rūpesčių ir tylus.'),
  (@b18, 21, 24, 'Jo krūtys pilnos pieno ir jo kaulai sudrėkinti kaulų smegenų.'),
  (@b18, 21, 25, 'O kitas miršta su apkartusia siela ir niekada nevalgęs su malonumu.'),
  (@b18, 21, 26, 'Jie vienodai atsiguls į dulkes, ir kirmėlės juos apdengs.'),
  (@b18, 21, 27, 'Štai aš žinau jūsų mintis ir užmačias, kurias neteisėtai prieš mane sugalvojate.'),
  (@b18, 21, 28, 'Nes jūs sakote: ‘Kur kunigaikščių namai ir kur nedorėlių buveinės?’'),
  (@b18, 21, 29, 'Ar nepasiklausėte einančių tuo keliu? Ar nežinote jų ženklų,'),
  (@b18, 21, 30, 'kad nedorėlis palaikomas pražūties dienai? Jie bus išvesti į rūstybės dieną.'),
  (@b18, 21, 31, 'Kas paskelbs jo kelią jam į akis? Kas jam atmokės tai, ką jis yra padaręs?'),
  (@b18, 21, 32, 'Tačiau jis bus nugabentas į kapą, ir pasiliks kape.'),
  (@b18, 21, 33, 'Saldūs jam bus slėnio grumstai, ir paskui jį trauks kiekvienas žmogus, kaip yra prieš jį nesuskaičiuojami.'),
  (@b18, 21, 34, 'Kaip tad jūs mane tuščiai guodžiate, kadangi jūsų atsakymuose pasilieka melas?'),
  (@b18, 22, 1, 'Tada temanas Elifazas atsakė ir tarė:'),
  (@b18, 22, 2, '„Argi žmogus gali būti naudingas Dievui, kaip išmintingasis gali būti naudingas sau pačiam?'),
  (@b18, 22, 3, 'Ar Visagaliui yra koks pasitenkinimas, kad esi teisus? Ar jam nauda, kad darai savo kelius tobulus?'),
  (@b18, 22, 4, 'Ar jis tave bars tavęs bijodamas? Ar jis įeis su tavimi į teismą?'),
  (@b18, 22, 5, 'Argi tavo nedorybė nėra didelė ir tavo neteisybių – begalybė?'),
  (@b18, 22, 6, 'Nes už nieką ėmei užstatą iš savo brolio ir nurengei nuogiesiems drabužius.'),
  (@b18, 22, 7, 'Nuvargusiam nedavei gerti vandens ir sulaikei nuo alkano duoną.'),
  (@b18, 22, 8, 'Bet galingasis žmogus, jis turėjo žemę; ir garbingasis joje gyveno.'),
  (@b18, 22, 9, 'Tu išsiuntei našles tuščiomis, ir našlaičių rankos buvo sulaužytos.'),
  (@b18, 22, 10, 'Todėl aplink tave žabangos, ir netikėta baimė neramina tave,');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b18, 22, 11, 'arba tamsa, kad negali matyti; ir vandenų gausybė apdengė tave.'),
  (@b18, 22, 12, 'Argi Dievas ne dangaus aukštybėje? Pažvelk į žvaigždžių aukštybę, kaip aukštai jos yra!'),
  (@b18, 22, 13, 'Ir tu sakai: ‘Kaip gi Dievas žino? Ar jis gali teisti pro tamsų debesį?'),
  (@b18, 22, 14, 'Tiršti debesys yra jo dangalas, kad jis nemato; ir jis vaikšto dangaus apskritimu’.'),
  (@b18, 22, 15, 'Ar įsidėmėjai seną kelią, kuriuo žengė nedorėliai,'),
  (@b18, 22, 16, 'kurie nelaiku buvo iškirsti, kurių pamatą užliejo potvynis?'),
  (@b18, 22, 17, 'Jie sakė Dievui: ‘Atsitrauk nuo mūsų’; ir ką Visagalis gali jiems padaryti?'),
  (@b18, 22, 18, 'Nors jis pripildė jų namus gėrybių; bet nedorėlių patarimas yra toli nuo manęs.'),
  (@b18, 22, 19, 'Teisieji tai mato ir džiaugiasi; ir nekaltas juos išjuokia.'),
  (@b18, 22, 20, 'Tuo tarpu mūsų turtai neiškirsti, bet jų likutį suryja ugnis.'),
  (@b18, 22, 21, 'Susipažink gi su juo ir būk ramybėje; per tai tau ateis gerovė.'),
  (@b18, 22, 22, 'Priimk, meldžiu tave, įstatymą iš jo burnos ir kaupk jo žodžius širdyje.'),
  (@b18, 22, 23, 'Jei sugrįši pas Visagalį, būsi pastatytas, pašalinsi neteisybę toli nuo savo padangčių.'),
  (@b18, 22, 24, 'Tada krausi auksą kaip dulkes ir Ofyro auksą kaip upelių akmenis.'),
  (@b18, 22, 25, 'Taip, Visagalis bus tavo apsauga ir turėsi gausybę sidabro.'),
  (@b18, 22, 26, 'Nes tada gėrėsies Visagaliu ir pakelsi savo veidą į Dievą.'),
  (@b18, 22, 27, 'Tu melsies jam, ir jis tave išgirs, ir ištesėsi savo įžadus.'),
  (@b18, 22, 28, 'Taipogi tu ką nors nuspręsi, ir tau tai įsitvirtins; ir ant tavo kelių švies šviesa.'),
  (@b18, 22, 29, 'Kai žmonės prislėgti, tu sakysi: „Yra išaukštinimas“; ir jis išgelbės nusižeminusį žmogų.'),
  (@b18, 22, 30, 'Jis išvaduos nekaltųjų salą; ji išvaduota tavo rankų tyrumu“.'),
  (@b18, 23, 1, 'Tada Jobas atsakė ir tarė:'),
  (@b18, 23, 2, '„Dar ir šiandien mano skundas kartus: mano kirtis sunkesnis už mano vaitojimą.'),
  (@b18, 23, 3, 'O kad žinočiau, kur jį rasti, kad ateičiau net iki jo vietos!'),
  (@b18, 23, 4, 'Aš išdėstyčiau jo akivaizdoje savo bylą ir savo burną pripildyčiau įrodymų.'),
  (@b18, 23, 5, 'Žinočiau žodžius, kuriais jis man atsakytų, ir suprasčiau, ką jis man kalbėtų.'),
  (@b18, 23, 6, 'Ar jis bylinėtųsi prieš mane su didele galia? Ne; jis tik įdėtų į mane stiprybės.'),
  (@b18, 23, 7, 'Ten teisusis galėtų ginčytis su juo; taip būčiau amžiams išlaisvintas nuo savo teisėjo.'),
  (@b18, 23, 8, 'Štai einu pirmyn, bet ten jo nėra; ir atgal, bet jo nepastebiu;'),
  (@b18, 23, 9, 'į kairę, kur jis darbuojasi, bet jo nematau; jis pasislėpęs dešinėje, kad jo nematau;'),
  (@b18, 23, 10, 'bet jis žino kelią, kurį renkuosi; kai jis bus mane išmėginęs, aš išeisiu kaip auksas.'),
  (@b18, 23, 11, 'Mano koja laikėsi jo žingsnių, aš laikiausi jo kelio ir nenukrypau.'),
  (@b18, 23, 12, 'Nuo jo lūpų įsakymo neatsitraukiau; jo burnos žodžius vertinau labiau už savo būtiną maistą.'),
  (@b18, 23, 13, 'Bet jis yra vienos nuomonės, ir kas gali jį nukreipti? Ir ko trokšta jo siela, tą jis padaro.'),
  (@b18, 23, 14, 'Nes jis vykdo tai, kas man skirta; ir daug tokių dalykų yra pas jį.'),
  (@b18, 23, 15, 'Todėl esu neramus jo akivaizdoje; kai pagalvoju, bijau jo.'),
  (@b18, 23, 16, 'Nes Dievas minkština mano širdį, Visagalis neramina mane;'),
  (@b18, 23, 17, 'nes nebuvau iškirstas prieš tamsą, ir jis nepaslėpė tamsos nuo mano veido.'),
  (@b18, 24, 1, 'Kadangi laikai nepaslėpti nuo Visagalio, tai kodėl tie, kurie jo nepažįsta, mato jo dienas?'),
  (@b18, 24, 2, 'Kai kurie perkelia riboženklius; jie prievarta atima kaimenes ir maitinasi iš jų.'),
  (@b18, 24, 3, 'Našlaičių asilą jie nusivaro, našlės jautį jie paima kaip užstatą.'),
  (@b18, 24, 4, 'Jie nukreipia nuo kelio nepasiturinčius; žemės beturčiai slepiasi kartu.'),
  (@b18, 24, 5, 'Štai, kaip laukiniai asilai dykumoje jie išeina į savo darbą; anksti keliasi dėl grobio; dykuma duoda maisto jiems ir jų vaikams.'),
  (@b18, 24, 6, 'Lauke jie pjauna kiekvienas savo javus; ir nurenka nedorėlio vynuogių derlių.'),
  (@b18, 24, 7, 'Jie verčia nuogus nakvoti be drabužių taip, kad jie neturi kuo apsidengti šaltyje.'),
  (@b18, 24, 8, 'Jie šlapi nuo kalnų liūčių ir stokodami prieglobsčio apkabina uolą.'),
  (@b18, 24, 9, 'Jie atplėšia nuo krūties našlaitį ir ima užstatą iš beturčio.'),
  (@b18, 24, 10, 'Jie priverčia jį vaikščioti nuogą be drabužio ir atima pėdus iš alkanų;'),
  (@b18, 24, 11, 'kurie tarp jų sienų spaudžia aliejų, mina jų vyno spaustuvus ir kenčia troškulį.'),
  (@b18, 24, 12, 'Žmonės dejuoja iš miesto, ir sužeistųjų siela šaukiasi; tačiau Dievas nepriskiria jiems kvailystės.'),
  (@b18, 24, 13, 'Jie yra iš tų, kurie maištauja prieš šviesą; jie nepažįsta jos kelių ir nepasilieka jos takuose.'),
  (@b18, 24, 14, 'Žudikas, atsikėlęs su šviesa, nužudo beturtį ir nepasiturintį, o naktį yra kaip vagis.'),
  (@b18, 24, 15, 'Taipogi svetimautojo akis laukia sutemos, sakydama: ‘Jokia akis manęs nepamatys’; ir slepia savo veidą.'),
  (@b18, 24, 16, 'Tamsoje jie rausiasi po namus, kuriuos jie įsidėmėjo dienos metu; jie nežino šviesos.'),
  (@b18, 24, 17, 'Nes rytas jiems yra kaip mirties šešėlis; jei kas juos pažįsta, tai jie yra apimti mirties šešėlio siaubo.'),
  (@b18, 24, 18, 'Jis greitas kaip vandenys; jų dalis prakeikta žemėje; jis nežiūri į vynuogynų kelią.'),
  (@b18, 24, 19, 'Sausra ir kaitra praryja sniego vandenis; taip ir kapas tuos, kurie nusidėjo.'),
  (@b18, 24, 20, 'Įsčios jį pamirš; kirmėlė saldžiai juo maitinsis; jo nebeatsimins; ir nedorybė bus sulaužyta kaip medis.'),
  (@b18, 24, 21, 'Jis piktai elgiasi su nevaisingąja, kuri negimdo; ir nedaro gera našlei.'),
  (@b18, 24, 22, 'Taip pat jis nutempia galinguosius savo jėga; jis pakyla, ir niekas nebesitiki gyventi.'),
  (@b18, 24, 23, 'Nors jam duota būti saugume, kuriuo jis remiasi; tačiau jo akys nukreiptos į jų kelius.'),
  (@b18, 24, 24, 'Jie išaukštinti trumpam, bet dingsta ir yra nužeminti; jie pašalinami iš kelio kaip visi kiti, ir iškertami kaip javų varpų viršūnės.'),
  (@b18, 24, 25, 'O jei taip dabar nėra, tai kas padarys mane melagiu ir pavers mano kalbą nieko verta?“'),
  (@b18, 25, 1, 'Tada šuachas Bildadas atsakė ir tarė:'),
  (@b18, 25, 2, '„Viešpatavimas ir baimė yra pas jį, jis daro taiką savo aukštumose.'),
  (@b18, 25, 3, 'Ar jo kariuomenės turi skaičių? Ir ant ko neužteka jo šviesa?'),
  (@b18, 25, 4, 'Kaip tad žmogus gali būti išteisintas prieš Dievą? Arba kaip gimęs iš moters gali būti švarus?'),
  (@b18, 25, 5, 'Štai net mėnulis, ir jis nešviečia; taip, žvaigždės nėra tyros jo akyse.'),
  (@b18, 25, 6, 'Tai kiek mažiau žmogus, kuris yra kirminas, ir žmogaus sūnus, kuris yra kirmėlė?“'),
  (@b18, 26, 1, 'Bet Jobas atsakė ir tarė:'),
  (@b18, 26, 2, '„Kaip tu padėjai bejėgiui, kaip išgelbėjai stiprybės neturinčią ranką?'),
  (@b18, 26, 3, 'Kaip tu patarei neturinčiajam išminties? Ir kaip gausiai paskelbei dalykus, kaip jie yra?'),
  (@b18, 26, 4, 'Kam tu ištarei žodžius? Kieno dvasia atėjo iš tavęs?'),
  (@b18, 26, 5, 'Negyvi dalykai suformuoti iš po vandenų ir jų gyventojai.'),
  (@b18, 26, 6, 'Pragaras yra nuogas prieš jį, ir pražūtis neturi dangalo.'),
  (@b18, 26, 7, 'Jis ištiesia šiaurę virš tuštumos ir pakabina žemę ant nieko.'),
  (@b18, 26, 8, 'Jis suriša vandenis savo tirštuose debesyse; ir debesis neplyšta po jais.'),
  (@b18, 26, 9, 'Jis sulaiko savo sosto veidą ir išskleidžia ant jo savo debesį.'),
  (@b18, 26, 10, 'Jis apsupo vandenis ribomis, kol diena ir naktis ateis į pabaigą.'),
  (@b18, 26, 11, 'Dangaus stulpai dreba ir yra apstulbę nuo jo barimo.'),
  (@b18, 26, 12, 'Savo jėga jis padalija jūrą ir savo supratimu jis smogia išdidžiajam.'),
  (@b18, 26, 13, 'Savo Dvasia jis papuošė dangus; jo ranka suformavo susirietusią gyvatę.'),
  (@b18, 26, 14, 'Štai tos yra dalys jo kelių; bet kokia maža dalis tėra girdėta apie jį. Bet kas gali suprasti jo galybės griaustinį?“'),
  (@b18, 27, 1, 'Dar daugiau Jobas tęsė savo palyginimą, sakydamas:'),
  (@b18, 27, 2, '„Kaip gyvas Dievas, kuris atėmė mano teismą; ir Visagalis, kuris vargino mano sielą;'),
  (@b18, 27, 3, 'kol mano kvapas manyje, ir Dievo dvasia mano šnervėse;'),
  (@b18, 27, 4, 'mano lūpos nekalbės nedorybės, ir mano liežuvis neištars apgaulės.'),
  (@b18, 27, 5, 'Gink Dieve, kad aš jus teisinčiau; kol mirsiu, neatitrauksiu savo dorumo nuo savęs.'),
  (@b18, 27, 6, 'Savo teisumo tvirtai laikausi ir jo nepaleisiu: mano širdis man nepriekaištaus, kol gyvenu.'),
  (@b18, 27, 7, 'Tegul mano priešas bus kaip nedorėlis, ir tas, kuris sukyla prieš mane, kaip neteisusis.'),
  (@b18, 27, 8, 'Nes kokia veidmainio viltis, nors jis ir išlošia, kai Dievas atima jo sielą?'),
  (@b18, 27, 9, 'Ar Dievas išklausys jo šauksmą, kai ant jo užeis bėda?'),
  (@b18, 27, 10, 'Ar jis gėrėsis Visagaliu? Ar jis visada šauksis Dievo?'),
  (@b18, 27, 11, 'Aš jus pamokysiu Dievo ranka; nenuslėpsiu to, kas pas Visagalį.'),
  (@b18, 27, 12, 'Štai jūs patys visa tai matėte; tai kodėl jūs taip visiškai tušti?'),
  (@b18, 27, 13, 'Šita yra nedorėlio dalis pas Dievą ir engėjų palikimas, kurį jie gaus iš Visagalio.'),
  (@b18, 27, 14, 'Jei jo vaikų padaugėja, tai bus kalavijui; ir jo palikuonys nepasisotins duona.'),
  (@b18, 27, 15, 'Išlikusieji iš jo bus laidojami mirtyje; ir jo našlės neraudos.'),
  (@b18, 27, 16, 'Nors jis susikraus sidabro kaip dulkių ir pasiruoš drabužių kaip molio;'),
  (@b18, 27, 17, 'jis gali tai paruošti, tačiau teisusis jais apsivilks, ir sidabrą padalins nekaltasis.'),
  (@b18, 27, 18, 'Jis stato savo namus kaip kandis ir kaip pastogę, kurią pasidaro sargas.'),
  (@b18, 27, 19, 'Turtuolis atsiguls, bet nebus surinktas; jis atveria akis, ir jo nėra.'),
  (@b18, 27, 20, 'Siaubai jį pasigriebia kaip vandenys, naktį jį pasigrobia audra.'),
  (@b18, 27, 21, 'Jį nusineša rytų vėjas, ir jis nueina; kaip audra nusviedžia jį iš jo vietos.'),
  (@b18, 27, 22, 'Nes Dievas užmes ant jo ir nesigailės; jis mielai pabėgtų iš jo rankos.'),
  (@b18, 27, 23, 'Žmonės plos savo rankomis prieš jį ir iššvilps jį iš jo vietos“.'),
  (@b18, 28, 1, 'Tikrai sidabrui yra gysla, ir vieta auksui, kur jį valo.'),
  (@b18, 28, 2, 'Geležis imama iš žemės, o iš akmens išlydomas žalvaris.'),
  (@b18, 28, 3, 'Jis nustato galą tamsai ir ištiria kiekvieną tobulumą, tamsos akmenis ir mirties šešėlį.'),
  (@b18, 28, 4, 'Srovė atitrūksta nuo gyventojų, vandenys – pamiršti kojų; jie išdžiūvę, atsitraukę nuo žmonių.'),
  (@b18, 28, 5, 'O žemė – iš jos išauga duona; o apačioje ji apversta tarsi ugnis.'),
  (@b18, 28, 6, 'Jos akmenys – safyro vieta; ir ji turi aukso dulkių.'),
  (@b18, 28, 7, 'Yra takas, kurio nežino nei vienas skrajūnas ir kurio nematė maitvanagio akis;'),
  (@b18, 28, 8, 'jo nemindė liūto jaunikliai ir juo nepraėjo piktas liūtas.'),
  (@b18, 28, 9, 'Jis ištiesia ranką į uolą; jis išvarto kalnus su šaknimis.'),
  (@b18, 28, 10, 'Tarp uolų jis iškerta upes; ir jo akis mato kiekvieną brangų daiktą.'),
  (@b18, 28, 11, 'Jis suriša sroves, kad neišsilietų; ir išneša švieson tai, kas paslėpta.'),
  (@b18, 28, 12, 'Bet kur randama išmintis, ir kur yra supratimo vieta?'),
  (@b18, 28, 13, 'Žmogus nežino jos kainos; ir ji nerandama gyvųjų šalyje.'),
  (@b18, 28, 14, 'Gelmės sako: „Jos nėra manyje“; o jūra sako: „Jos nėra su manimi“.'),
  (@b18, 28, 15, 'Jos negalima įgyti už auksą, ir nepasversi sidabro už jo kainą.'),
  (@b18, 28, 16, 'Negalima jos įkainoti Ofyro auksu, brangiu oniksu ar safyru.'),
  (@b18, 28, 17, 'Jai negali prilygti auksas ir krištolas; ir jos mainai nebus į puikaus aukso brangenybes.'),
  (@b18, 28, 18, 'Koralų ir perlų neverta minėti; nes išminties kaina aukštesnė už rubinus.'),
  (@b18, 28, 19, 'Jai neprilygsta Etiopijos topazas, ir jos neįkainosi grynu auksu.'),
  (@b18, 28, 20, 'Iš kur tad ateina išmintis, ir kur yra supratimo vieta?'),
  (@b18, 28, 21, 'Kadangi ji yra paslėpta nuo akių visų gyvųjų ir laikoma paslaptyje nuo oro skrajūnų.'),
  (@b18, 28, 22, 'Pražūtis ir mirtis sako: „Mes girdėjome savo ausimis garsą apie ją“.'),
  (@b18, 28, 23, 'Dievas supranta jos kelią ir žino jos vietą.'),
  (@b18, 28, 24, 'Nes jis žvelgia į žemės pakraščius ir mato po visu dangumi;'),
  (@b18, 28, 25, 'kad padarytų vėjams svorį; ir jis pasveria vandenis saiku.'),
  (@b18, 28, 26, 'Kai paskyrė lietui įsaką ir kelią griaustinio žaibui,'),
  (@b18, 28, 27, 'tada jis ją matė ir ją paskelbė; jis ją paruošė, taip, ir ją ištyrė.'),
  (@b18, 28, 28, 'O žmogui jis tarė: ‘Štai Viešpaties baimė – tai yra išmintis; ir šalintis nuo pikto yra supratimas’“.'),
  (@b18, 29, 1, 'Jobas toliau tęsė savo palyginimą, sakydamas:'),
  (@b18, 29, 2, '„O kad būčiau kaip ankstesniais mėnesiais, kaip dienomis, kai Dievas mane saugojo;'),
  (@b18, 29, 3, 'kai jo žvakė švietė virš mano galvos ir kai jo šviesa vaikščiojau per tamsą;'),
  (@b18, 29, 4, 'kaip buvau savo jaunystės dienomis, kai Dievo paslaptis buvo ant mano padangtės;'),
  (@b18, 29, 5, 'kai Visagalis dar buvo su manimi, kai mano vaikai buvo aplink mane;'),
  (@b18, 29, 6, 'kai savo žingsnius ploviau sviestu, ir uola man išliejo aliejaus upes;'),
  (@b18, 29, 7, 'kai išeidavau per miestą iki vartų, kai gatvėje paruošdavau savo sėdėjimo vietą!'),
  (@b18, 29, 8, 'Jaunuoliai mane pamatę slėpdavosi; o seniai atsikėlę stovėdavo.'),
  (@b18, 29, 9, 'Kunigaikščiai susilaikydavo nuo kalbėjimo ir uždėdavo ranką sau ant burnos.'),
  (@b18, 29, 10, 'Kilmingieji nutildavo, ir jų liežuvis prilipdavo prie gomurio.'),
  (@b18, 29, 11, 'Kai ausis mane išgirdo, laimino mane; ir kai akis mane pamatė, ji man liudijo;'),
  (@b18, 29, 12, 'nes aš išgelbėdavau beturtį, kuris šaukdavo, ir našlaitį, ir tą, kuris neturėjo, kas jam padėtų.'),
  (@b18, 29, 13, 'Man ateidavo palaiminimas to, kuris buvo bepražūstantis; ir padarydavau, kad našlės širdis giedotų iš džiaugsmo.'),
  (@b18, 29, 14, 'Apsivilkau teisumu, ir jis mane aprengė; mano teismas buvo kaip apsiaustas ir karūna.'),
  (@b18, 29, 15, 'Buvau akys aklam ir kojos raišam.'),
  (@b18, 29, 16, 'Buvau tėvas beturčiams; ir ištirdavau bylą, kurios nežinodavau.'),
  (@b18, 29, 17, 'Sulaužydavau nedorėlio žandikaulius ir iš jo dantų išplėšdavau grobį.'),
  (@b18, 29, 18, 'Tuomet sakiau: ‘Savo lizde mirsiu ir padauginsiu savo dienas kaip smėlį.'),
  (@b18, 29, 19, 'Mano šaknis išsikerojo prie vandenų, ir rasa visą naktį gulėjo ant mano šakos.'),
  (@b18, 29, 20, 'Mano šlovė buvo šviežia manyje, ir mano lankas atsinaujindavo mano rankoje.'),
  (@b18, 29, 21, 'Žmonės man atsukdavo ausį ir laukdavo, ir tylėdavo man patariant.'),
  (@b18, 29, 22, 'Po mano žodžių jie nebekalbėdavo; ant jų lašėdavo mano kalba.'),
  (@b18, 29, 23, 'Jie laukdavo manęs kaip lietaus; jie plačiai praverdavo burną kaip dėl vėlyvojo lietaus.'),
  (@b18, 29, 24, 'Jei jiems juokdavausi, jie netikėdavo; ir mano veido šviesos netemdydavo.'),
  (@b18, 29, 25, 'Aš parinkdavau jiems kelią ir sėdėdavau vyriausiuoju, ir gyvendavau kaip karalius kariuomenėje, kaip tas, kuris guodžia raudotojus.'),
  (@b18, 30, 1, 'Bet dabar išjuokia mane jaunesni už mane, kurių tėvų nebūčiau sutikęs paskirti prie savo kaimenės šunų.'),
  (@b18, 30, 2, 'Taip, kokia man nauda iš rankų jėgos jų, kuriuose pražuvo senatvė?'),
  (@b18, 30, 3, 'Dėl stokos ir bado jie buvo atsiskyrę, pabėgę į dykumą, seniau tuščią ir dyką.'),
  (@b18, 30, 4, 'Jie skabydavo dedešvas prie krūmų ir kadagio šaknis savo maistui.'),
  (@b18, 30, 5, 'Jie buvo varomi iš žmonių tarpo (jiems šaukdavo iš paskos kaip ant vagių),'),
  (@b18, 30, 6, 'kad gyventų slėnių skardžiuose, žemės urvuose ir uolose.'),
  (@b18, 30, 7, 'Tarp krūmų jie rėkdavo; susirinkdavo po dilgėlėmis.'),
  (@b18, 30, 8, 'Jie buvo kvailių vaikai, taip, žemų žmonių vaikai; jie buvo bjauresni už žemę.'),
  (@b18, 30, 9, 'O dabar esu jų daina, taip, esu jų priežodis.'),
  (@b18, 30, 10, 'Jie bjaurisi manimi, bėga tolyn nuo manęs ir nesulaiko spjūvio man į veidą.'),
  (@b18, 30, 11, 'Kadangi jis atleido mano virvę ir ištiko mane, jie irgi nusimetė apynasrį prieš mane.'),
  (@b18, 30, 12, 'Mano dešinėje pakyla jaunuoliai; jie nustumia į šalį mano kojas ir iškelia prieš mane savo pražūties kelius.'),
  (@b18, 30, 13, 'Jie sudarkė mano taką, pastūmėjo į priekį mano nelaimę, jie neturi pagalbininko.'),
  (@b18, 30, 14, 'Jie užėjo ant manęs kaip platus vandenų įsilaužimas; suniokojime jie ritosi ant manęs.'),
  (@b18, 30, 15, 'Siaubai atsigręžė į mane; jie persekioja mano sielą kaip vėjas; ir mano gerovė praeina kaip debesis.'),
  (@b18, 30, 16, 'Ir dabar mano siela išsiliejo ant manęs; mane suėmė sielvarto dienos.'),
  (@b18, 30, 17, 'Nakties metu manyje veria mano kaulus; ir mano gyslos nesiilsi.'),
  (@b18, 30, 18, 'Dėl didelio mano ligos stiprumo pasikeitė mano drabužis; tai apjuosia mane kaip mano apsiausto apykaklė.'),
  (@b18, 30, 19, 'Jis įmetė mane į purvą, ir tapau kaip dulkės ir pelenai.'),
  (@b18, 30, 20, 'Šaukiuosi tavęs, o tu manęs negirdi; atsistojau, o tu nekreipi dėmesio į mane.'),
  (@b18, 30, 21, 'Tu tapai man žiaurus; savo stipria ranka man priešinies.'),
  (@b18, 30, 23, 'Nes žinau, kad nuvesi mane į mirtį ir į namus, paskirtus visiems gyviesiems.'),
  (@b18, 30, 24, 'Tačiau jis neišties savo rankos į kapą, nors jie šaukia jo naikinime.'),
  (@b18, 30, 25, 'Ar aš neverkiau dėl to, kuris buvo varge? Ar mano siela neliūdėjo dėl beturčio?'),
  (@b18, 30, 26, 'Kai laukiau gero, tuomet ant manęs atėjo pikta; ir kai laukiau šviesos, atėjo tamsa.'),
  (@b18, 30, 27, 'Mano viduriai virė ir nesiilsėjo; mane aplenkę pasitiko vargo dienos.'),
  (@b18, 30, 28, 'Aš vaikščiojau gedėdamas, be saulės; atsistojęs šaukiau susirinkime.'),
  (@b18, 30, 29, 'Aš brolis slibinams ir draugas pelėdoms.'),
  (@b18, 30, 30, 'Mano oda ant manęs juoda, ir mano kaulai dega nuo karščio.'),
  (@b18, 30, 31, 'Taip pat mano arfa virto rauda, o mano vargonai – verkiančiųjų balsu.'),
  (@b18, 30, 22, 'Tu pakeli mane į vėją, verti mane ant jo joti ir ištirpdai mano turinį.'),
  (@b18, 31, 1, 'Sudariau sandorą su savo akimis; tad kodėl turėčiau galvoti apie merginą?'),
  (@b18, 31, 2, 'Kokia gi Dievo dalis iš viršaus ir koks Visagalio paveldas iš aukšto?'),
  (@b18, 31, 3, 'Argi ne nedorėliui pražūtis? Ir argi ne neteisybės vykdytojams neįprasta bausmė?'),
  (@b18, 31, 4, 'Argi jis nemato mano kelių ir neskaičiuoja visų mano žingsnių?'),
  (@b18, 31, 5, 'Jei vaikščiojau su tuštybe ar jei mano koja skubėjo į apgaulę,'),
  (@b18, 31, 6, 'tepasveria mane lygiomis svarstyklėmis, kad Dievas sužinotų mano dorumą.'),
  (@b18, 31, 7, 'Jei mano žingsnis nukrypo nuo kelio ir mano širdis vaikščiojo paskui mano akis, ir jei prie mano rankų prilipo kokia dėmė,'),
  (@b18, 31, 8, 'tuomet tegul aš sėsiu, o kitas tevalgo; taip, tebūna išrauta su šaknimis mano atžala.'),
  (@b18, 31, 9, 'Jei mano širdis buvo moters apgauta ar jei tykojau prie savo artimo durų,'),
  (@b18, 31, 10, 'tuomet mano žmona temala kitam ir tegul kiti pasilenkia virš jos.'),
  (@b18, 31, 11, 'Nes tai bjaurus nusikaltimas; taip, tai neteisybė, kuri turi būti baudžiama teisėjų.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b18, 31, 12, 'Nes tai ugnis, kuri ėda iki sunaikinimo, ir visą mano prieaugį išrautų su šaknimis.'),
  (@b18, 31, 13, 'Jei niekinau savo tarno ar savo tarnaitės bylą, kai jie ginčyjosi su manimi,'),
  (@b18, 31, 14, 'tai ką darysiu, kai Dievas pakils? Ką jam atsakysiu, kai jis aplankys?'),
  (@b18, 31, 15, 'Ar ne tas, kuris padarė mane įsčiose, padarė ir jį? Argi ne vienas mus padarė įsčiose?'),
  (@b18, 31, 16, 'Jei sulaikiau beturčius nuo to, ko jie norėjo, arba daviau užgesti našlės akims,'),
  (@b18, 31, 17, 'arba vienas valgiau savo kąsnį, o našlaitis nevalgė iš jo'),
  (@b18, 31, 18, '(nes nuo mano jaunystės jis užaugo su manimi kaip su tėvu, ir nuo savo motinos įsčių ją vedžiojau),'),
  (@b18, 31, 19, 'jei mačiau kurį pražūstantį dėl drabužio stokos ar kokį beturtį be apdangalo,'),
  (@b18, 31, 20, 'jei manęs nelaimino jo strėnos ir jei jis nebuvo sušildytas mano avių vilnomis,'),
  (@b18, 31, 21, 'jei pakėliau savo ranką prieš našlaitį, matydamas vartuose sau pagalbą,'),
  (@b18, 31, 22, 'tuomet tegul mano ranka išnyra iš mano peties mentės ir mano ranka tenulūžta nuo kaulo.'),
  (@b18, 31, 23, 'Nes sunaikinimas nuo Dievo man buvo siaubas, ir dėl jo didybės negalėjau ištverti.'),
  (@b18, 31, 24, 'Jei auksą padariau savo viltimi arba jei tariau puikiam auksui: ‘Tu mano užtikrintumas’,'),
  (@b18, 31, 25, 'jei džiaugiausi, kad didelis mano turtas ir kad daug įsigijo mano ranka,'),
  (@b18, 31, 26, 'jei man žvelgiant į saulę, kai ji švietė, ar į mėnulį, einantį skaistume,'),
  (@b18, 31, 27, 'mano širdis slapta susigundė ar mano burna bučiavo mano ranką,'),
  (@b18, 31, 28, 'tai irgi būtų neteisybė, kuri turi būti baudžiama teisėjo; nes būčiau išsigynęs viršuje esančio Dievo.'),
  (@b18, 31, 29, 'Jei džiaugiausi dėl pražūties to, kuris manęs nekentė, ar išsikėliau, kai jį aptiko pikta;'),
  (@b18, 31, 30, 'neleidau savo burnai nusidėti, linkėdamas jo sielai prakeikimo.'),
  (@b18, 31, 31, 'Jei mano padangtės žmonės nesakė: ‘O, kad turėtume jo mėsos! Mes negalime pasisotinti’.'),
  (@b18, 31, 32, 'Gatvėje nenakvojo ateivis; bet savo duris atidarydavau keleiviui.'),
  (@b18, 31, 33, 'Jei dangsčiau savo nusižengimus kaip Adomas, slėpdamas savo užantyje savo neteisybę;'),
  (@b18, 31, 34, 'ar bijojau didelės minios arba, ar šeimų panieka taip gąsdino mane, kad tylėjau ir neišėjau pro duris?'),
  (@b18, 31, 35, 'O kad kas išklausytų mane! Štai mano troškimas, kad Visagalis man atsakytų ir kad mano priešininkas parašytų knygą.'),
  (@b18, 31, 36, 'Tikrai ant peties ją užsidėčiau ir prisiriščiau ją sau kaip vainiką.'),
  (@b18, 31, 37, 'Jam paskelbčiau savo žingsnių skaičių, kaip kunigaikštis prie jo prisiartinčiau.'),
  (@b18, 31, 38, 'Jei mano žemė šaukia prieš mane, arba jos vagos taipogi skundžiasi,'),
  (@b18, 31, 39, 'jei be pinigų valgiau jos vaisius, arba padariau, kad jos savininkai netektų gyvybės,'),
  (@b18, 31, 40, 'tai kviečių vietoje teauga usnys, o vietoj miežių – svidrės“. Pasibaigė Jobo žodžiai.'),
  (@b18, 32, 1, 'Taigi tie trys vyrai liovėsi atsakinėję Jobui, nes jis buvo teisus savo paties akyse.'),
  (@b18, 32, 2, 'Tada užsidegė buzito Barachelio sūnaus Elihuvo iš Ramo giminės rūstybė; jo rūstybė užsidegė prieš Jobą, nes jis verčiau teisino save, o ne Dievą.'),
  (@b18, 32, 3, 'Taip pat jo rūstybė užsidegė prieš jo tris draugus, nes jie nesurado atsakymo, tačiau kaltino Jobą.'),
  (@b18, 32, 4, 'Na, o Elihuvas laukė, kol kalbėjo Jobas, nes jie buvo vyresni už jį.'),
  (@b18, 32, 5, 'Kai Elihuvas pamatė, kad nebuvo atsakymo tų trijų vyrų burnoje, užsidegė jo rūstybė.'),
  (@b18, 32, 6, 'Ir buzito Barachelio sūnus Elihuvas atsakydamas tarė: „Aš jaunas, o jūs labai seni; todėl bijojau ir nedrįsau jums pareikšti savo nuomonės.'),
  (@b18, 32, 7, 'Aš sakiau: ‘Tekalba dienos, ir daugybė metų turi mokyti išminties’.'),
  (@b18, 32, 8, 'Tačiau žmoguje yra dvasia, ir Visagalio įkvėpimas duoda jiems supratimą.'),
  (@b18, 32, 9, 'Didžiūnai ne visuomet išmintingi; nei seniai supranta teismą.'),
  (@b18, 32, 10, 'Todėl sakiau: ‘Paklausykite manęs; aš irgi pareikšiu savo nuomonę’.'),
  (@b18, 32, 11, 'Štai aš laukiau jūsų žodžių; atsukau ausį į jūsų samprotavimus, kai ieškojote, ką pasakyti.'),
  (@b18, 32, 12, 'Taip, kreipiau dėmesį į jus, ir štai nei vienas iš jūsų neįtikino Jobo nei neatsakė į jo žodžius;'),
  (@b18, 32, 13, 'kad nesakytumėte: ‘Radome išmintį; Dievas jį atstumia, ne žmogus’.'),
  (@b18, 32, 14, 'Na, o jis nenukreipė savo žodžių prieš mane; ir jūsų žodžiais jam neatsakysiu.'),
  (@b18, 32, 15, 'Jie nustebo, nebeatsakė; nustojo kalbėję.'),
  (@b18, 32, 16, 'Kai palaukiau (nes jie nekalbėjo, bet stovėjo nejudėdami ir nebeatsakė),'),
  (@b18, 32, 17, 'aš sakiau: ‘Aš irgi atsakysiu iš savo pusės, aš irgi pareikšiu savo nuomonę.'),
  (@b18, 32, 18, 'Nes esu kupinas dalykų, dvasia mano viduje verčia mane.'),
  (@b18, 32, 19, 'Štai mano pilvas kaip vynas, neturintis angos; jis pasiruošęs pratrūkti kaip nauji indai.'),
  (@b18, 32, 20, 'Kalbėsiu, kad atsigaivinčiau; atversiu savo lūpas ir atsakysiu.'),
  (@b18, 32, 21, 'Meldžiu jus, tenebūsiu niekam šališkas ir niekam tenesuteikinėsiu pataikaujančių titulų.'),
  (@b18, 32, 22, 'Nes nemoku suteikti pataikaujančių titulų; jei taip daryčiau, mane padariusysis greitai mane pašalintų“.'),
  (@b18, 33, 1, '„Todėl, Jobai, meldžiu tave, išklausyk mano kalbų ir klausyk visų mano žodžių.'),
  (@b18, 33, 2, 'Štai dabar atvėriau savo burną, mano liežuvis prabilo mano burnoje.'),
  (@b18, 33, 3, 'Mano žodžiai bus iš mano širdies tiesumo; ir mano lūpos aiškiai ištars pažinimą.'),
  (@b18, 33, 4, 'Dievo Dvasia mane padarė, Visagalio kvapas davė man gyvybę.'),
  (@b18, 33, 5, 'Jei gali man atsakyti, išdėstyk savo žodžius prieš mane, stokis.'),
  (@b18, 33, 6, 'Štai pagal tavo norą esu Dievo vietoje; aš irgi suformuotas iš molio.'),
  (@b18, 33, 7, 'Štai mano bauginimas tavęs neišgąsdins, ir mano ranka nebus ant tavęs sunki.'),
  (@b18, 33, 8, 'Tikrai tu sakei man girdint, ir aš girdėjau tavo žodžių balsą, sakant:'),
  (@b18, 33, 9, '‘Aš švarus, be nusižengimų, aš nekaltas; ir nėra manyje neteisybės.'),
  (@b18, 33, 10, 'Štai jis randa priežasčių prieš mane, laiko mane savo priešu,'),
  (@b18, 33, 11, 'įtveria mano kojas į trinkas, stebi visus mano takus’.'),
  (@b18, 33, 12, 'Štai tame tu nesi teisus; aš tau atsakysiu, kad Dievas didesnis už žmogų.'),
  (@b18, 33, 13, 'Kodėl kovoji prieš jį? Nes jis neatsiskaito už jokius savo reikalus.'),
  (@b18, 33, 14, 'Nes Dievas kalba vieną kartą, taip, dukart, tačiau žmogus to nepastebi.'),
  (@b18, 33, 15, 'Sapne, nakties regėjime, kai gilus miegas ištinka žmones, snaudžiant lovoje;'),
  (@b18, 33, 16, 'tada jis atidaro žmonių ausis ir užantspauduoja jų pamokymą,'),
  (@b18, 33, 17, 'kad atitrauktų žmogų nuo jo tikslo ir paslėptų nuo žmogaus išdidumą.'),
  (@b18, 33, 18, 'Jis sulaiko jo sielą nuo duobės ir jo gyvybę nuo pražuvimo kalaviju.'),
  (@b18, 33, 19, 'Jis taip pat baudžiamas skausmu savo lovoje, ir jo kaulų daugybė – stipriu skausmu;'),
  (@b18, 33, 20, 'taip, kad jo gyvybė bjaurisi duona, ir jo siela – skaniausiu valgiu.'),
  (@b18, 33, 21, 'Jo kūnas sunyksta, kad nebegalima jo matyti; ir išsikiša jo kaulai, kurie nesimatydavo.'),
  (@b18, 33, 22, 'Taip, jo siela artėja prie kapo, ir jo gyvybė – prie naikintojų.'),
  (@b18, 33, 23, 'Jei pas jį yra pasiuntinys, aiškintojas, vienas iš tūkstančio, kad parodytų žmogui jo tiesumą,'),
  (@b18, 33, 24, 'tai jis jam maloningas ir sako: ‘Išgelbėk jį nuo nužengimo į duobę: aš radau išpirką’.'),
  (@b18, 33, 25, 'Jo kūnas bus šviežesnis už vaiko; jis sugrįš į savo jaunystės dienas;'),
  (@b18, 33, 26, 'jis melsis Dievui, ir jis bus jam palankus; ir jis regės jo veidą su džiaugsmu; nes jis atiduos žmogui jo teisumą.'),
  (@b18, 33, 27, 'Jis žiūri į žmones, ir jei kas sakys: ‘Nusidėjau ir iškreipiau tai, kas teisinga, ir tai man nebuvo naudinga’,'),
  (@b18, 33, 28, 'tai jis išgelbės jo sielą nuo ėjimo į duobę, ir jo gyvybė matys šviesą.'),
  (@b18, 33, 29, 'Štai Dievas visa tai dažnai daro su žmogumi,'),
  (@b18, 33, 30, 'kad sugrąžintų jo sielą nuo duobės, kad būtų apšviestas gyvųjų šviesa.'),
  (@b18, 33, 31, 'Gerai įsidėmėk, o Jobai, paklausyk manęs; tylėk, o aš kalbėsiu.'),
  (@b18, 33, 32, 'Jei turi ką pasakyti, atsakyk man; kalbėk, nes noriu tave išteisinti.'),
  (@b18, 33, 33, 'Jei ne, paklausyk manęs; tylėk, o aš tave pamokysiu išminties“.'),
  (@b18, 34, 1, 'Elihuvas toliau atsakydamas tarė:'),
  (@b18, 34, 2, '„Paklausykite, o išminčiai, mano žodžių; ir jūs, turintys pažinimą, palenkite man ausį.'),
  (@b18, 34, 3, 'Nes ausis mėgina žodžius, kaip burna ragauja valgį.'),
  (@b18, 34, 4, 'Pasirinkime teismą; tarp savęs atpažinkime, kas yra gera.'),
  (@b18, 34, 5, 'Nes Jobas pasakė: ‘Aš esu teisus, ir Dievas atėmė mano teismą.'),
  (@b18, 34, 6, 'Ar turiu meluoti prieš savo teisę? Mano žaizda nepagydoma be nusižengimo’.'),
  (@b18, 34, 7, 'Koks žmogus yra kaip Jobas, kuris geria paniekinimus kaip vandenį,'),
  (@b18, 34, 8, 'kuris eina draugijoje su vykdančiais neteisybę ir vaikšto su nedorėliais?'),
  (@b18, 34, 9, 'Nes jis pasakė: ‘Žmogui nėra jokios naudos, kad jis gėrėtųsi Dievu’.'),
  (@b18, 34, 10, 'Todėl jūs, suprantantys vyrai, paklausykite manęs; toli tebūna nuo Dievo, kad jis darytų nedorybę, ir nuo Visagalio, kad jis vykdytų neteisybę.'),
  (@b18, 34, 11, 'Jis žmogui atlygins už jo darbus ir padarys, kad kiekvienas žmogus atrastų pagal savo kelius.'),
  (@b18, 34, 12, 'Taip, tikrai Dievas nesielgs nedorai, ir Visagalis neiškreips teismo.'),
  (@b18, 34, 13, 'Kas jį įpareigojo dėl žemės arba kas perdavė visą pasaulį?'),
  (@b18, 34, 14, 'Jei jis nukreiptų savo širdį į žmogų, jei susirinktų jo dvasią ir jo kvapą,'),
  (@b18, 34, 15, 'tai visi kūnai kartu pražūtų, ir žmogus sugrįžtų į dulkes.'),
  (@b18, 34, 16, 'Jei turi supratimą, išgirsk tai; paklausyk mano žodžių balso.'),
  (@b18, 34, 17, 'Argi net tas, kuris nekenčia teisingumo, valdys? Ar pasmerksi tą, kuris yra visų teisingiausias?'),
  (@b18, 34, 18, 'Ar dera sakyti karaliui: ‘Tu nedorėlis’, o kunigaikščiams: ‘Jūs bedieviai’?'),
  (@b18, 34, 19, 'Tai juo labiau tam, kuris neatsižvelgia į kunigaikščių asmenis ir neatsižvelgia į turtuolius labiau negu į vargšus; nes jie visi jo rankų darbas.'),
  (@b18, 34, 20, 'Akimirksniu jie mirs, ir tautos nerimaus vidurnaktį ir pranyks; ir galingieji bus pašalinti ne rankomis.'),
  (@b18, 34, 21, 'Nes jo akys nukreiptos į žmogaus kelius, ir jis mato visus jo ėjimus.'),
  (@b18, 34, 22, 'Nėra nei tamsos, nei mirties šešėlio, kur galėtų pasislėpti darantys neteisybę.'),
  (@b18, 34, 23, 'Nes jis neuždės ant žmogaus daugiau negu teisinga; kad jis įeitų pas Dievą į teismą.'),
  (@b18, 34, 24, 'Jis sutrupins galingųjų be skaičiaus, o į jų vietą pastatys kitus.'),
  (@b18, 34, 25, 'Todėl jis žino jų darbus ir nuverčia naktį juos taip, kad jie sunaikinami.'),
  (@b18, 34, 26, 'Kaip nedorėlius jis juos muša atvirai kitų akivaizdoje,'),
  (@b18, 34, 27, 'nes jie nusisuko nuo jo ir neapsvarstė nei vieno iš jo kelių;'),
  (@b18, 34, 28, 'jie padarė taip, kad beturčio šauksmas atėjo pas jį, ir jis išgirdo kamuojamųjų šauksmą.'),
  (@b18, 34, 29, 'Kai jis duoda ramybę, kas gali sutrikdyti? Ir kai jis paslepia savo veidą, kas gali jį išvysti? Ar tai būtų padaryta tautai, ar tiktai žmogui;'),
  (@b18, 34, 30, 'kad nekaraliautų veidmainis, idant tauta nebūtų pagauta spąstais.'),
  (@b18, 34, 31, 'Tikrai derėtų sakyti Dievui: ‘Aš pakenčiau bausmę, daugiau nebenusikalsiu;'),
  (@b18, 34, 32, 'pamokyk mane to, ko nematau; jei dariau neteisybę, daugiau nebedarysiu’.'),
  (@b18, 34, 33, 'Ar turėtų tai būti pagal tavo nuomonę? Jis tai atlygins – ar tu atmeti, ar renkiesi – o ne aš; todėl kalbėk, ką žinai.'),
  (@b18, 34, 34, 'Suprantantys žmonės man tesako, ir išmintingasis manęs tesiklauso.'),
  (@b18, 34, 35, 'Jobas kalbėjo be pažinimo, ir jo žodžiai buvo be išminties.'),
  (@b18, 34, 36, 'Norėčiau, kad Jobas būtų mėginamas iki galo, dėl jo atsakymų už nedorėlius.'),
  (@b18, 34, 37, 'Nes prie savo nuodėmės jis prideda maištą, tarp mūsų jis ploja rankomis ir daugina savo žodžius prieš Dievą“.'),
  (@b18, 35, 1, 'Elihuvas toliau kalbėjo, sakydamas:'),
  (@b18, 35, 2, '„Ar manai tai esant teisinga, kad pasakei: ‘Mano teisumas didesnis už Dievo’?'),
  (@b18, 35, 3, 'Nes tu pasakei: ‘Kokia tau bus nauda? Kokią turėsiu naudą, jei būsiu apvalytas nuo savo nuodėmės?’'),
  (@b18, 35, 4, 'Aš atsakysiu tau ir tavo draugams su tavimi.'),
  (@b18, 35, 5, 'Pažvelk į dangus ir žiūrėk; ir stebėk debesis, esančius aukščiau tavęs.'),
  (@b18, 35, 6, 'Jei nusidedi, ką padarai prieš jį? Arba, jei padaugėja tavo nusižengimų, ką jam padarai?'),
  (@b18, 35, 7, 'Jei esi teisus, ką jam duodi, arba ką jis gauna iš tavo rankos?'),
  (@b18, 35, 8, 'Tavo nedorybė gali pakenkti tokiam žmogui kaip tu; ir tavo teisumas gali duoti naudą žmogaus sūnui.'),
  (@b18, 35, 9, 'Dėl daugybės engimų jie priverčia engiamuosius šaukti; jie šaukiasi dėl galiūnų rankos.'),
  (@b18, 35, 10, 'Bet nei vienas nesako: ‘Kur yra Dievas, mano Kūrėjas, kuris duoda giesmių naktį,'),
  (@b18, 35, 11, 'kuris mus moko daugiau už žemės gyvulius ir daro mus išmintingesnius už dangaus skrajūnus?’'),
  (@b18, 35, 12, 'Ten jie šaukia, bet niekas neatsako dėl piktų žmonių išdidumo.'),
  (@b18, 35, 13, 'Tikrai Dievas neklauso tuštybės, Visagalis jos nepaiso.'),
  (@b18, 35, 14, 'Nors tu sakai jo nematysiąs, tačiau teismas yra jo priešakyje; todėl juo pasitikėk.'),
  (@b18, 35, 15, 'Bet dabar, kadangi taip nėra, jis aplankė savo pykčiu; tačiau jis to nepažįsta aukščiausiame laipsnyje;'),
  (@b18, 35, 16, 'todėl Jobas tuščiai atveria savo burną; jis daugina žodžius be pažinimo“.'),
  (@b18, 36, 1, 'Elihuvas tęsė ir tarė:'),
  (@b18, 36, 2, '„Pakęsk mane truputį ir aš tau parodysiu, kad dar turiu kalbėti už Dievą.'),
  (@b18, 36, 3, 'Atsinešiu savo pažinimą iš toli, ir savo Kūrėjui priskirsiu teisumą.'),
  (@b18, 36, 4, 'Nes tikrai mano žodžiai nebus melas; su tavimi yra tas, kuris tobulas pažinimu.'),
  (@b18, 36, 5, 'Štai Dievas galingas ir nei vieno neniekina; jis galingas jėga ir išmintimi.'),
  (@b18, 36, 6, 'Jis nesaugo nedorėlio gyvybės; bet suteikia beturčiui teises.'),
  (@b18, 36, 7, 'Jis neatitraukia akių nuo teisiųjų; bet jos yra su karaliais soste; taip, jis juos amžiams įtvirtina, ir jie yra išaukštinami.'),
  (@b18, 36, 8, 'O jei jie sukaustyti grandinėmis ir laikomi priespaudos virvėmis,'),
  (@b18, 36, 9, 'tada jis parodo jiems jų darbą ir jų nusižengimus, kad jie viršija.'),
  (@b18, 36, 10, 'Jis taip pat atveria jų ausį drausmei ir įsako jiems gręžtis nuo neteisybės.'),
  (@b18, 36, 11, 'Jeigu jie jam paklūsta ir tarnauja, jie praleis savo dienas klestėjime ir savo metus malonumuose.'),
  (@b18, 36, 12, 'Bet jei jie nepaklūsta, jie pražus nuo kalavijo ir mirs be pažinimo.'),
  (@b18, 36, 13, 'Bet veidmainiai širdyje kaupia rūstybę; jie nešaukia, kai jis supančioja juos.'),
  (@b18, 36, 14, 'Jie miršta jaunystėje, ir jų gyvenimas tarp nešvariųjų.'),
  (@b18, 36, 15, 'Jis išgelbsti beturtį jo varge ir atveria jų ausis priespaudoje.'),
  (@b18, 36, 16, 'Jis ir tave taip perkeltų iš ankštos į plačią vietą, kur nėra ankštumo; o tai, kas būtų padėta ant tavo stalo, būtų pilna riebumo.'),
  (@b18, 36, 17, 'Bet tu išpildei nedorėlio teismą; teismas ir teisingumas nutvėrė tave.'),
  (@b18, 36, 18, 'Kadangi yra rūstybė, saugokis, kad jis tavęs nepašalintų savo kirčiu; tada didžiulė išpirka negalės tavęs išgelbėti.'),
  (@b18, 36, 19, 'Ar jis vertins tavo turtus? Ne, nei aukso, nei visos stiprybės galios.'),
  (@b18, 36, 20, 'Netrokšk tos nakties, kai tautos yra iškertamos savo vietoje.'),
  (@b18, 36, 21, 'Žiūrėk, nepaisyk neteisybės; nes tu verčiau pasirinkai ją negu kančią.'),
  (@b18, 36, 22, 'Štai Dievas išaukština savo galia; kas moko taip, kaip jis?'),
  (@b18, 36, 23, 'Kas jam nurodė jo kelią arba kas gali pasakyti: ‘Tu padarei neteisybę’?'),
  (@b18, 36, 24, 'Atsimink, kad aukštintum jo darbą, kurį žmonės mato.'),
  (@b18, 36, 25, 'Visi žmonės gali jį matyti; žmogus gali jį stebėti iš tolo.'),
  (@b18, 36, 26, 'Štai Dievas yra didis, o mes jo nepažįstame, ir jo metų skaičius neištiriamas.'),
  (@b18, 36, 27, 'Nes jis susmulkina vandens lašus; jie pila lietų pagal jų garą;'),
  (@b18, 36, 28, 'juos lašina debesys, ir gausiai varvina ant žmonių.'),
  (@b18, 36, 29, 'Ar kas gali suprasti debesų pasklidimą ar jo padangtės triukšmą?'),
  (@b18, 36, 30, 'Štai jis paskleidžia ant jos savo šviesą ir apdengia jūros dugną.'),
  (@b18, 36, 31, 'Nes jais jis teisia tautas; jis apsčiai duoda maisto.'),
  (@b18, 36, 32, 'Debesimis jis apdengia šviesą; ir įsako jai nešviesti per ateinantį į tarpą debesį.'),
  (@b18, 36, 33, 'Jo triukšmas skelbia apie jį, ir galvijai apie garą.'),
  (@b18, 37, 1, 'Dėl to dreba mano širdis ir pajudėjo iš savo vietos.'),
  (@b18, 37, 2, 'Įdėmiai klausykite jo balso triukšmo ir garso, išeinančio iš jo burnos.'),
  (@b18, 37, 3, 'Jis nukreipia jį po visu dangumi, o savo žaibą iki žemės pakraščių.'),
  (@b18, 37, 4, 'Po to riaumoja balsas; jis griaudėja savo didybės balsu; ir jis nesustabdo jų, kai pasigirsta jo balsas.'),
  (@b18, 37, 5, 'Dievas nuostabiai griaudėja savo balsu; jis daro didžių dalykų, kurių negalime suvokti.'),
  (@b18, 37, 6, 'Nes sniegui jis sako: ‘Būk ant žemės’; taip pat mažam lietui ir jo stiprybės dideliam lietui’.'),
  (@b18, 37, 7, 'Jis užantspauduoja kiekvieno žmogaus ranką, kad visi žmonės pažintų jo darbą.'),
  (@b18, 37, 8, 'Tada žvėrys eina į urvus ir pasilieka savo vietose.'),
  (@b18, 37, 9, 'Iš pietų ateina viesulas; o šaltis iš šiaurės.'),
  (@b18, 37, 10, 'Dievo kvapu duodama šalna; ir vandenų platybė suvaržoma.'),
  (@b18, 37, 11, 'Taip pat drėkindamas jis nuvargina tirštą debesį; jis išsklaido savo šviesų debesį;'),
  (@b18, 37, 12, 'ir jis apsukamas pagal jo sumanymus; kad jie darytų, ką jis jiems įsako ant pasaulio paviršiaus žemėje.'),
  (@b18, 37, 13, 'Jis priverčia jį ateiti ar dėl pabaudimo, ar dėl savo šalies, ar dėl gailestingumo.'),
  (@b18, 37, 14, 'Paklausyk tai, o Jobai; stovėk ir apsvarstyk nuostabius Dievo darbus.'),
  (@b18, 37, 15, 'Ar žinai, kada Dievas juos išdėstė ir davė šviesti savo debesies šviesai?'),
  (@b18, 37, 16, 'Ar žinai debesų pusiausvyrą, nuostabius darbus to, kuris yra tobulas pažinimu?'),
  (@b18, 37, 17, 'Kaip įšyla tavo drabužiai, kai jis nuramina žemę pietų vėju?'),
  (@b18, 37, 18, 'Ar tu su juo išskleidei dangų, kuris yra tvirtas ir kaip nulietas veidrodis?'),
  (@b18, 37, 19, 'Pamokyk mus, ką turėtume jam sakyti; nes dėl tamsos negalime surikiuoti savo kalbos.'),
  (@b18, 37, 20, 'Ar jam bus pasakyta, kad aš kalbu? Jei žmogus kalbėtų, tikrai jis būtų prarytas.'),
  (@b18, 37, 21, 'O dabar žmonės nemato skaisčios šviesos, esančios debesyse; bet praūžia vėjas ir juos išvalo.'),
  (@b18, 37, 22, 'Iš šiaurės ateina giedra; pas Dievą yra baisi didybė.'),
  (@b18, 37, 23, 'Na, o Visagalis – mes negalime apie jį išsiaiškinti; jis puikus galia ir teismu, ir teisingumo gausybe; jis nevargina.'),
  (@b18, 37, 24, 'Todėl žmonės jo bijo; jis nepaiso nei vieno išmintingo širdimi“.'),
  (@b18, 38, 1, 'Tada VIEŠPATS atsakė Jobui iš viesulo ir tarė:'),
  (@b18, 38, 2, '„Kas yra tas, kuris aptemdo patarimą žodžiais be pažinimo?'),
  (@b18, 38, 3, 'Susijuosk dabar strėnas kaip vyras; nes aš tavęs klausiu, o tu man atsakyk.'),
  (@b18, 38, 4, 'Kur buvai, kai dėjau žemės pamatus? Pareikšk, jei turi supratimą.'),
  (@b18, 38, 5, 'Kas padėjo jos matmenis, jei žinai? Arba kas ištiesė ant jos virvę?'),
  (@b18, 38, 6, 'Ant ko pritvirtinti jos pamatai? Arba kas padėjo jos kertinį akmenį,');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b18, 38, 7, 'kai kartu giedojo ryto žvaigždės ir šaukė iš džiaugsmo visi Dievo sūnūs?'),
  (@b18, 38, 8, 'Arba kas užrakino durimis jūrą, kai ji išsiveržė, tarsi išeidama iš įsčių?'),
  (@b18, 38, 9, 'Kai padariau debesį jos drabužiu ir tirštą tamsą jos vystyklais,'),
  (@b18, 38, 10, 'ir pralaužiau jai mano nustatytą vietą, ir įdėjau skląsčius bei duris,'),
  (@b18, 38, 11, 'ir pasakiau: ‘Iki čia ateisi, bet ne toliau; ir čia sustos tavo išdidžios bangos’?'),
  (@b18, 38, 12, 'Ar kada nuo savo dienų įsakei rytui ar davei aušrai pažinti jos vietą,'),
  (@b18, 38, 13, 'kad ji nutvertų žemės pakraščius, kad iš jos būtų iškratyti nedorėliai?'),
  (@b18, 38, 14, 'Ji pasikeičia kaip molis į antspaudą; ir jie stovi kaip drabužis.'),
  (@b18, 38, 15, 'O nuo nedorėlių sulaikoma jų šviesa, ir aukšta ranka bus sulaužyta.'),
  (@b18, 38, 16, 'Ar įėjai į jūros šaltinius? Ar vaikščiojai gelmių tyrinėjime?'),
  (@b18, 38, 17, 'Ar tau atsivėrė mirties vartai? Ar matei mirties šešėlio duris?'),
  (@b18, 38, 18, 'Ar suvokei žemės plotį? Pareikšk, jei visa tai žinai.'),
  (@b18, 38, 19, 'Kur yra kelias, kur gyvena šviesa? O tamsa – kur yra jos vieta,'),
  (@b18, 38, 20, 'kad ją nuvestum iki jos ribos ir sužinotum takus į jos namus?'),
  (@b18, 38, 21, 'Ar tai žinai dėl to, kad tada jau buvai gimęs? Ar dėl to, kad tavo dienų skaičius yra didelis?'),
  (@b18, 38, 22, 'Ar buvai įėjęs į sniego saugyklas? Ar matei lobynus krušos,'),
  (@b18, 38, 23, 'kurią laikau bėdos metui, mūšio ir karo dienai?'),
  (@b18, 38, 24, 'Kokiu keliu persiskiria šviesa, kuri rytų vėją išsklaido po žemę?'),
  (@b18, 38, 25, 'Kas padalino vandentakį vandenų išsiliejimui ar kelią griaustinio žaibui,'),
  (@b18, 38, 26, 'kad leistų lyti ant žemės, kur nėra žmonių; ant dykumos, kur nėra žmonių,'),
  (@b18, 38, 27, 'kad numalšintų apleistą ir tuščią žemę ir leistų išsprogti gležnų žolių pumpurams?'),
  (@b18, 38, 28, 'Ar lietus turi tėvą? Arba, kas pagimdė rasos lašus?'),
  (@b18, 38, 29, 'Iš kieno įsčių išėjo ledas? Ir kas pagimdė žilą dangaus šerkšną?'),
  (@b18, 38, 30, 'Vandenys paslėpti tarsi akmeniu, ir gelmių paviršius užšalęs.'),
  (@b18, 38, 31, 'Ar galėtum suvaržyti mielus Sietyno poveikius ar atrišti Oriono pančius?'),
  (@b18, 38, 32, 'Ar galėtum išvesti Mazarotą jo laiku? Ar galėtum vedžioti Arktūrą su jo sūnumis?'),
  (@b18, 38, 33, 'Ar pažįsti dangaus nuostatus? Ar galėtum nustatyti jo viešpatavimą žemėje?'),
  (@b18, 38, 34, 'Ar gali pakelti savo balsą į debesis, kad vandenų gausybė tave apdengtų?'),
  (@b18, 38, 35, 'Ar gali pasiųsti žaibus, kad jie eitų ir tau sakytų: ‘Štai, mes čia’?'),
  (@b18, 38, 36, 'Kas įdėjo išmintį į vidų arba, kas davė supratimą širdžiai?'),
  (@b18, 38, 37, 'Kas gali išmintimi suskaičiuoti debesis? Arba, kas gali sustabdyti dangaus indus,'),
  (@b18, 38, 38, 'kai dulkės susilieja į kietumą, ir grumstai tvirtai sulimpa?'),
  (@b18, 38, 39, 'Ar tu sumedžiosi liūtui grobį? Arba, ar patenkinsi jaunų liūtų apetitą,'),
  (@b18, 38, 40, 'kai jie guli savo urvuose ir pasilieka slėptuvėje, kad tykotų?'),
  (@b18, 38, 41, 'Kas parūpina varnui jo maistą? Kai jo jaunikliai šaukiasi Dievo, jie klaidžioja dėl maisto stokos.'),
  (@b18, 39, 1, 'Ar žinai laiką, kada laukinės uolų ožkos gimdo? Ar gali pastebėti, kai elnės atsiveda jauniklius?'),
  (@b18, 39, 2, 'Ar gali suskaičiuoti mėnesius, kuriuos jos išpildo? Arba, ar žinai laiką, kai jos gimdo?'),
  (@b18, 39, 3, 'Jos pasilenkia, pagimdo savo jauniklius, išmeta savo sielvartus.'),
  (@b18, 39, 4, 'Jų jaunikliai geros būklės, užauga su javais; jie išeina ir nesugrįžta pas jas.'),
  (@b18, 39, 5, 'Kas išleido laukinį asilą į laisvę? Arba, kas atrišo pančius laukinio asilo,'),
  (@b18, 39, 6, 'kurio namais paskyriau dykumą ir jo buveinėmis nederlingą žemę?'),
  (@b18, 39, 7, 'Jis išjuokia miesto minią ir vežiko šauksmo nepaiso.'),
  (@b18, 39, 8, 'Kalnų virtinė yra jo ganykla, ir jis ieško visokios žalumos.'),
  (@b18, 39, 9, 'Ar vienaragis norės tau tarnauti arba pasilikti prie tavo ėdžių?'),
  (@b18, 39, 10, 'Ar gali pririšti vienaragį prie vagos jo virve? Arba, ar jis akės slėnius tau iš paskos?'),
  (@b18, 39, 11, 'Ar juo pasitikėsi, kadangi didelė jo jėga? Arba, ar jam paliksi savo triūsą?'),
  (@b18, 39, 12, 'Ar juo tikėsi, kad jis atgabens į namus tavo sėklą ir ją surinks į tavo klojimą?'),
  (@b18, 39, 13, 'Ar tu davei povui gražius sparnus arba sparnus ir plunksnas stručiui?'),
  (@b18, 39, 14, 'Jis palieka savo kiaušinius žemėje ir dulkėse juos šildo,'),
  (@b18, 39, 15, 'ir pamiršta, kad koja gali juos sutraiškyti arba, kad laukinis žvėris gali juos sudaužyti.'),
  (@b18, 39, 16, 'Jis šiurkštus su savo jaunikliais, tarsi jie būtų ne jo; jis nebijo, kad triūsia veltui,'),
  (@b18, 39, 17, 'nes Dievas jam atėmė išmintį ir nedavė jam supratimo.'),
  (@b18, 39, 18, 'Kai jis pasikelia į aukštį, pasijuokia iš žirgo ir jo raitelio.'),
  (@b18, 39, 19, 'Ar tu davei žirgui stiprybę? Ar apvilkai jo sprandą griausmu?'),
  (@b18, 39, 20, 'Ar gali jį išgąsdinti kaip žiogą? Baisi jo šnervių šlovė.'),
  (@b18, 39, 21, 'Jis tranko kanopa slėnyje ir džiaugiasi savo jėga; jis eina pasitikti ginkluotus vyrus.'),
  (@b18, 39, 22, 'Jis išjuokia baimę ir neišsigąsta nei nenusigręžia nuo kalavijo.'),
  (@b18, 39, 23, 'Priešais jį barška strėlinė, žvilganti ietis ir skydas.'),
  (@b18, 39, 24, 'Su piktumu ir įniršiu jis ryja žemę; ir netiki, kad tai trimito garsas.'),
  (@b18, 39, 25, 'Tarp trimitų jis taria: Y-ha-ha! Ir iš tolo užuodžia mūšį, vadų griausmą ir šauksmą.'),
  (@b18, 39, 26, 'Ar tavo išmintimi skrenda vanagas ir išskečia savo sparnus į pietus?'),
  (@b18, 39, 27, 'Ar tavo įsakymu pakyla erelis ir aukštumoje pasidaro lizdą?'),
  (@b18, 39, 28, 'Ant uolos jis gyvena ir pasilieka, ant uolos statumo ir tvirtoje vietoje.'),
  (@b18, 39, 29, 'Iš ten jis ieško grobio, ir jo akys mato toli.'),
  (@b18, 39, 30, 'Jo jaunikliai taip pat geria kraują; ir kur yra užmuštųjų, ten ir jis“.'),
  (@b18, 40, 1, 'VIEŠPATS dar atsakė Jobui ir tarė:'),
  (@b18, 40, 2, '„Ar tas, kuris ginčijasi su Visagaliu, jį pamokys? Kas peikia Dievą, teatsako“.'),
  (@b18, 40, 3, 'Tada Jobas atsakė VIEŠPAČIUI, tardamas:'),
  (@b18, 40, 4, '„Štai aš niekingas; ką tau atsakysiu? Aš uždėsiu ranką sau ant burnos.'),
  (@b18, 40, 5, 'Kartą kalbėjau; bet nebeatsakysiu; taip, du kartus; bet toliau nebetęsiu“.'),
  (@b18, 40, 6, 'Tada VIEŠPATS atsakė Jobui iš viesulo ir tarė:'),
  (@b18, 40, 7, '„Susijuosk dabar savo strėnas kaip vyras; aš tavęs klausiu, o tu man pareikšk.'),
  (@b18, 40, 8, 'Ar panaikinsi ir mano teismą? Ar mane pasmerksi, kad tu būtum teisus?'),
  (@b18, 40, 9, 'Ar turi tokią ranką kaip Dievo? Ar gali griaudėti balsu kaip jis?'),
  (@b18, 40, 10, 'Pasipuošk dabar didybe ir puikybe; apsirenk šlove ir grožiu.'),
  (@b18, 40, 11, 'Išliek savo rūstybės įniršį; pažvelk į kiekvieną išdidų ir jį pažemink.'),
  (@b18, 40, 12, 'Pažvelk į kiekvieną išdidų ir jį nužemink; ir sutrypk nedorėlius jų vietoje.'),
  (@b18, 40, 13, 'Paslėpk juos kartu dulkėse; aprišk jų veidus slaptoje.'),
  (@b18, 40, 14, 'Tada ir aš tau išpažinsiu, kad tavo paties dešinė gali tave išgelbėti.'),
  (@b18, 40, 15, 'Štai begemotas, kurį padariau kartu su tavimi; jis ėda žolę kaip jautis.'),
  (@b18, 40, 16, 'Štai jo jėga yra jo strėnose, ir jo galia jo pilvo bamboje.'),
  (@b18, 40, 17, 'Jis judina savo uodegą kaip kedrą; jo sėklidžių gyslos susipynusios.'),
  (@b18, 40, 18, 'Jo kaulai kaip tvirti žalvario gabalai; jo kaulai kaip geležiniai strypai.'),
  (@b18, 40, 19, 'Jis yra Dievo kelių pirmasis; tas, kuris jį padarė, gali priartinti prie jo savo kalaviją.'),
  (@b18, 40, 20, 'Tikrai kalnai jam atneša maisto, kur žaidžia visi lauko žvėrys.'),
  (@b18, 40, 21, 'Jis guli po ūksmingais medžiais, nendrių ir pelkių slėptuvėje.'),
  (@b18, 40, 22, 'Ūksmingi medžiai apdengia jį savo šešėliu; jį apsupa upelio gluosniai.'),
  (@b18, 40, 23, 'Štai jis geria upę ir neskuba; jis tikisi, kad gali įtraukti Jordaną į savo nasrus.'),
  (@b18, 40, 24, 'Jis ima jį savo akimis; jo nosis perveria žabangas.'),
  (@b18, 41, 1, 'Ar gali ištraukti leviataną kabliu? Ar jo liežuvį virve, kurią nuleidi žemyn?'),
  (@b18, 41, 2, 'Ar gali įverti kablį į jo nosį? Arba dygliu perdurti jo nasrus?'),
  (@b18, 41, 3, 'Ar jis daug tavęs maldaus? Ar tau kalbės švelnius žodžius?'),
  (@b18, 41, 4, 'Ar jis sudarys su tavimi sandorą? Ar paimsi jį kaip tarną amžiams?'),
  (@b18, 41, 5, 'Ar žaisi su juo kaip su paukščiu? Ar jį suriši savo mergaitėms?'),
  (@b18, 41, 6, 'Ar draugai surengs iš jo puotą? Ar padalins jį tarp pirklių?'),
  (@b18, 41, 7, 'Ar gali pripildyti jo odą dygliuotais kapliais? Ar jo galvą žvejybiniais žeberklais?'),
  (@b18, 41, 8, 'Uždėk ant jo savo ranką, prisimink mūšį, daugiau to nebedaryk.'),
  (@b18, 41, 9, 'Štai jo viltis tuščia; argi nenugriūna vien jį pamatę?'),
  (@b18, 41, 10, 'Niekas nėra toks nuožmus, kad drįstų jį kurstyti; kas tada gali atsilaikyti prieš mane?'),
  (@b18, 41, 11, 'Kas mane aplenkė, kad jam atlyginčiau? Viskas po visu dangumi yra mano.'),
  (@b18, 41, 12, 'Nenuslėpsiu jo narių nei jo jėgos, nei jo gražaus sudėjimo.'),
  (@b18, 41, 13, 'Kas gali atidengti jo drabužio išorinę pusę? Arba kas gali prieiti prie jo su jo dvigubu apynasriu?'),
  (@b18, 41, 14, 'Kas gali atidaryti jo veido duris? Jo dantys baisūs aplinkui.'),
  (@b18, 41, 15, 'Jo žvynai – jo pasididžiavimas, užspausti tarsi aklinu antspaudu.'),
  (@b18, 41, 16, 'Vienas taip arti kito, kad joks oras negali patekti tarp jų.'),
  (@b18, 41, 17, 'Jie susijungę vienas su kitu, laikosi kartu taip, kad yra neatskiriami.'),
  (@b18, 41, 18, 'Nuo jo čiaudėjimo švyti šviesa, ir jo akys lyg ryto akių vokai.'),
  (@b18, 41, 19, 'Iš jo nasrų eina degantys žibintai ir iššoksta ugnies kibirkštys.'),
  (@b18, 41, 20, 'Iš jo šnervių išeina dūmai kaip iš verdančio puodo ar katilo.'),
  (@b18, 41, 21, 'Jo kvapas uždega anglis, ir liepsna išeina iš jo nasrų.'),
  (@b18, 41, 22, 'Jo sprande lieka stiprybė, ir jo akivaizdoje liūdesys pavirsta džiaugsmu.'),
  (@b18, 41, 23, 'Jo kūno sluoksniai susijungę; jie tvirti savyje; jie nepajudinami.'),
  (@b18, 41, 24, 'Jo širdis kieta kaip akmuo; taip, kieta kaip apatinis girnų akmuo.'),
  (@b18, 41, 25, 'Kai jis pasikelia, išsigąsta galiūnai; dėl laužymų jie apsivalo.'),
  (@b18, 41, 26, 'Kalavijas to, kuris prie jo prideda, negali išsilaikyti; nei ietis, nei strėlė, nei šarvažiedžiai marškiniai.'),
  (@b18, 41, 27, 'Geležį jis laiko šiaudu, o varį – supuvusiu medžiu.'),
  (@b18, 41, 28, 'Strėlė neprivers jo bėgti; svaidyklės akmenys jam yra virtę ražiena.'),
  (@b18, 41, 29, 'Strėlės laikomos ražiena; jis juokiasi iš ieties virpesio.'),
  (@b18, 41, 30, 'Po juo yra aštrūs akmenys; jis išskleidžia smaigalius klampynėje.'),
  (@b18, 41, 31, 'Jis padaro, kad gelmės verda kaip puodas; jis padaro jūrą kaip tepalo puodą.'),
  (@b18, 41, 32, 'Paskui save jis padaro spindintį taką; kas nors manytų gelmes esant žilas.'),
  (@b18, 41, 33, 'Nieko nėra žemėje jam lygaus, kuris padarytas bebaimiu.'),
  (@b18, 41, 34, 'Jis žvelgia į viską, kas aukšta; jis yra visų išdidumo vaikų karalius“.'),
  (@b18, 42, 1, 'Tada Jobas atsakė VIEŠPAČIUI, tardamas:'),
  (@b18, 42, 2, '„Žinau, kad tu viską gali, ir kad jokia mintis negali būti nuo tavęs sulaikyta.'),
  (@b18, 42, 3, 'Kas yra tas, kuris paslepia patarimą be pažinimo?’ Todėl aš ištariau tai, ko nesupratau; tai, kas man per daug nuostabu, ko aš nežinojau.'),
  (@b18, 42, 4, 'Klausyk, meldžiu tave, o aš kalbėsiu; aš tave klausiu, o tu man pareikšk.'),
  (@b18, 42, 5, 'Girdėjau apie tave ausies girdėjimu; bet dabar mano akis mato tave.'),
  (@b18, 42, 6, 'Todėl bjauriuosi savimi ir atgailauju dulkėse ir pelenuose“.'),
  (@b18, 42, 7, 'Ir buvo po to, kai VIEŠPATS iškalbėjo šituos žodžius Jobui, VIEŠPATS tarė temaniui Elifazui: „Mano rūstybė užsidegė prieš tave ir prieš abu tavo draugus; nes jūs nekalbėjote apie mane to, kas teisinga, kaip mano tarnas Jobas.'),
  (@b18, 42, 8, 'Todėl pasiimkite dabar septynis jaučius ir septynis avinus, nueikite pas mano tarną Jobą ir atnašaukite deginamąją atnašą už save; o mano tarnas Jobas melsis už jus; nes jį priimsiu; kad su jumis nepasielgčiau pagal jūsų kvailystę tame, kad nekalbėjote apie mane to, kas teisinga, kaip mano tarnas Jobas“.'),
  (@b18, 42, 9, 'Taip temanas Elifazas, šuachas Bildadas ir naamatietis Cofaras nuėjo ir padarė pagal tai, kaip VIEŠPATS buvo jiems įsakęs; taip pat VIEŠPATS priėmė Jobą.'),
  (@b18, 42, 10, 'Ir VIEŠPATS nukreipė Jobo nelaisvę, kai jis meldėsi už savo draugus; taip pat VIEŠPATS davė Jobui dvigubai daugiau, negu jis anksčiau turėjo.'),
  (@b18, 42, 11, 'Tada pas jį atėjo visi jo broliai, visos jo seserys ir visi jo pirmiau buvusieji pažįstami ir valgė su juo duoną jo namuose; ir jie apraudojo jį ir jį paguodė dėl viso to pikto, kurį VIEŠPATS buvo ant jo užleidęs; taip pat kiekvienas jam davė po monetą ir kiekvienas po auksinį auskarą.'),
  (@b18, 42, 12, 'Taigi VIEŠPATS palaimino Jobo pabaigą labiau už jo pradžią; nes jis turėjo keturiolika tūkstančių avių, šešis tūkstančius kupranugarių, tūkstantį jungų jaučių ir tūkstantį asilių.'),
  (@b18, 42, 13, 'Taip pat jis turėjo septynis sūnus ir tris dukteris.'),
  (@b18, 42, 14, 'Pirmąją jis praminė vardu Jemima, antrąją – vardu Kecija, o trečiąją – vardu Keren-Hapucha.'),
  (@b18, 42, 15, 'Visoje šalyje neatsirado moterų, tokių gražių, kaip Jobo dukterys; ir jų tėvas joms davė paveldą tarp jų brolių.'),
  (@b18, 42, 16, 'Po to Jobas gyveno šimtą keturiasdešimt metų ir matė savo sūnus ir savo sūnų sūnus – keturias kartas.'),
  (@b18, 42, 17, 'Taigi Jobas mirė, būdamas senas ir pilnas dienų.'),
  (@b19, 1, 1, 'Palaimintas žmogus, kuris nevaikšto pagal bedievių patarimą nei nestovi nusidėjėlių kelyje, nei nesėdi apjuokėjų vietose.'),
  (@b19, 1, 2, 'Bet jis gėrisi VIEŠPATIES įstatymu; ir mąsto jo įstatymu dieną ir naktį.'),
  (@b19, 1, 3, 'Jis bus kaip medis, pasodintas prie vandens upių, kuris duoda savo vaisių savo metu; ir jo lapai nenuvys; ir ką jis bedaro, tai klestės.'),
  (@b19, 1, 4, 'Ne tokie yra bedieviai; bet kaip pelai, kuriuos nuveja vėjas.'),
  (@b19, 1, 5, 'Todėl bedieviai neišstovės teisme, nei nusidėjėliai teisiųjų susirinkime.'),
  (@b19, 1, 6, 'Nes VIEŠPATS žino teisiųjų kelią; bet bedievių kelias pražus.'),
  (@b19, 2, 1, 'Kodėl pagonys siaučia ir tauta sumano tuštybę?'),
  (@b19, 2, 2, 'Sukyla žemės karaliai, ir valdovai tariasi prieš VIEŠPATĮ ir prieš jo pateptąjį, sakydami:'),
  (@b19, 2, 3, '„Sutraukykime jų pančius, nusimeskime nuo savęs jų virves“.'),
  (@b19, 2, 4, 'Tas, kuris sėdi danguose, juoksis; Viešpats tyčiosis iš jų.'),
  (@b19, 2, 5, 'Tada jis kalbės jiems savo rūstybėje ir savo stipriu nepasitenkinimu juos neramins.'),
  (@b19, 2, 6, '„Tačiau pastačiau savo karalių ant savo šventos Siono kalvos.'),
  (@b19, 2, 7, 'Aš paskelbsiu įsaką; VIEŠPATS man tarė: ‘Tu mano Sūnus; šią dieną tave pagimdžiau.'),
  (@b19, 2, 8, 'Prašyk manęs, ir duosiu tau pagonis tavo paveldui ir tavo nuosavybei tolimiausius žemės kraštus.'),
  (@b19, 2, 9, 'Tu sudaužysi juos geležine lazda; kaip puodžiaus indą juos sutrupinsi’“.'),
  (@b19, 2, 10, 'Taigi dabar, o karaliai, būkite išmintingi; pasimokykite jūs, žemės teisėjai.'),
  (@b19, 2, 11, 'Tarnaukite VIEŠPAČIUI su baime ir džiaukitės drebėdami.'),
  (@b19, 2, 12, 'Bučiuokite Sūnų, kad jis nesupyktų, ir jūs nepražūtumėte kelyje, tik truputį užsiliepsnojus jo rūstybei. Palaiminti visi, kurie juo pasitiki.'),
  (@b19, 3, 1, 'Dovydo psalmė, kai jis pabėgo nuo savo sūnaus Abšalomo. VIEŠPATIE, kaip padaugėjo mane varginančiųjų! Daug tų, kurie sukyla prieš mane.'),
  (@b19, 3, 2, 'Daug tų, kurie sako apie mano sielą: „Nėra jam pagalbos Dieve“. Sela.'),
  (@b19, 3, 3, 'Bet tu, o VIEŠPATIE, esi man skydas; mano šlovė ir tas, kuris pakelia mano galvą.'),
  (@b19, 3, 4, 'Savo balsu šaukiausi VIEŠPATIES, ir jis išgirdo mane nuo savo šventos kalvos. Sela.'),
  (@b19, 3, 5, 'Aš atsiguliau ir užmigau; aš atsibudau; nes VIEŠPATS mane palaikė.'),
  (@b19, 3, 6, 'Aš neišsigąsiu dešimčių tūkstančių žmonių, kurie aplinkui sustoję prieš mane.'),
  (@b19, 3, 7, 'Kelkis, o VIEŠPATIE; išgelbėk mane, o mano Dieve; nes tu smogei visiems mano priešams į žandikaulį; tu sutrupinai bedievių dantis.'),
  (@b19, 3, 8, 'Išgelbėjimas priklauso VIEŠPAČIUI; tavo palaiminimas ant tavo tautos. Sela.'),
  (@b19, 4, 1, 'Vyriausiajam muzikantui Neginotu. Dovydo psalmė. Kai šaukiuosi, išgirsk mane, o mano teisumo Dieve; kai būdavau suspaustas, tu išplėsdavai mane; pasigailėk manęs ir išklausyk mano maldą.'),
  (@b19, 4, 2, 'O žmonių sūnūs, kaip ilgai mano šlovę versite į gėdą? Kaip ilgai mylėsite tuštybę ir ieškosite melo? Sela.'),
  (@b19, 4, 3, 'Bet žinokite, kad VIEŠPATS sau atskyrė dievotąjį; VIEŠPATS išgirs, kai jo šauksiuos.'),
  (@b19, 4, 4, 'Pagarbiai bijokite ir nenusidėkite; kalbėkite su savo širdimi savo lovoje ir būkite ramūs. Sela.'),
  (@b19, 4, 6, 'Daugelis sako: „Kas parodys mums ką gera?“ VIEŠPATIE, pakelk viršum mūsų savo veido šviesą.'),
  (@b19, 4, 7, 'Tu į mano širdį įdėjai linksmybės daugiau negu tuo laiku, kai padaugėjo jų javų ir jų vyno.'),
  (@b19, 4, 8, 'Aš ir atsigulsiu ramybėje, ir miegosiu; nes tu vienintelis, VIEŠPATIE, padarai, kad saugiai gyvenčiau.'),
  (@b19, 4, 5, 'Atnašaukite teisumo aukas ir pasikliaukite VIEŠPAČIU.'),
  (@b19, 5, 1, 'Vyriausiajam muzikantui Nehilotu. Dovydo psalmė. Palenk ausį mano žodžiams, o VIEŠPATIE, atsižvelk į mano apmąstymą.'),
  (@b19, 5, 2, 'Išklausyk mano šauksmo balso, mano Karaliau ir mano Dieve; nes tau melsiuos.'),
  (@b19, 5, 3, 'O VIEŠPATIE, ryte išgirsi mano balsą; ryte į tave nukreipsiu savo maldą ir dairysiuos.'),
  (@b19, 5, 4, 'Nes tu nesi Dievas, kuriam patiktų nedorybė; nei pikta negyvens pas tave.'),
  (@b19, 5, 5, 'Kvaili neišstovės tavo akyse; tu nekenti visų, darančių neteisybę.'),
  (@b19, 5, 6, 'Tu sunaikinsi tuos, kurie kalba melą; VIEŠPATS bjaurėsis kraugeriu ir apgaviku.'),
  (@b19, 5, 7, 'Bet aš, aš įeisiu į tavo namus tavo gailestingumo daugybėje; tavo baimėje garbinsiu tavo šventos šventyklos link.'),
  (@b19, 5, 8, 'O VIEŠPATIE, vesk mane savo teisume dėl mano priešų; ištiesink prieš mano veidą savo kelią.'),
  (@b19, 5, 9, 'Nes nėra ištikimybės jų burnoje; jų vidus – pati nedorybė; jų gerklė – atviras kapas; jie pataikauja savo liežuviu.'),
  (@b19, 5, 10, 'Sunaikink juos, o Dieve; tegul jie griūna nuo savo pačių patarimų; išmesk juos dėl daugybės jų nusižengimų; nes jie prieš tave maištavo.'),
  (@b19, 5, 11, 'Bet tesidžiaugia visi, kurie pasikliauja tavimi; visados jie tešaukia iš džiaugsmo, nes tu juos apgini; ir tebūna džiaugsmingi tavyje tie, kurie myli tavo vardą.'),
  (@b19, 5, 12, 'Nes tu, VIEŠPATIE, laiminsi teisųjį; apsupsi jį palankumu lyg skydu.'),
  (@b19, 6, 1, 'Vyriausiajam muzikantui Neginotu, Šeminitu. Dovydo psalmė. O VIEŠPATIE, nebark manęs savo pyktyje, nei nebausk manęs įširdęs.'),
  (@b19, 6, 2, 'Pasigailėk manęs, o VIEŠPATIE; nes aš esu silpnas; pagydyk mane, o VIEŠPATIE; nes mano kaulai sukrėsti.'),
  (@b19, 6, 3, 'Ir mano siela labai sukrėsta; bet tu, o VIEŠPATIE, kaip ilgai?'),
  (@b19, 6, 4, 'Sugrįžk, o VIEŠPATIE, išvaduok mano sielą; išgelbėk mane dėl savo gailestingumų.'),
  (@b19, 6, 5, 'Nes mirtyje nėra prisiminimo apie tave; kas dėkos tau kape?'),
  (@b19, 6, 6, 'Aš nuvargau nuo savo dejavimo; visą naktį maudau savo patalą, ašaromis laistau savo guolį.'),
  (@b19, 6, 7, 'Nuo širdgėlos sunyko mano akys; jos paseno dėl visų mano priešų.'),
  (@b19, 6, 8, 'Atsitraukite nuo manęs, visi neteisybės darytojai; nes VIEŠPATS išgirdo mano verksmo balsą.'),
  (@b19, 6, 9, 'VIEŠPATS išgirdo mano prašymą; VIEŠPATS priims mano maldą.'),
  (@b19, 6, 10, 'Tegul visi mano priešai susigėsta ir tebūna labai sukrėsti; tegul jie sugrįžta ir staiga susigėsta.'),
  (@b19, 7, 1, 'Dovydo Šigajonas, kurį jis giedojo VIEŠPAČIUI dėl benjamino Kušo žodžių. O VIEŠPATIE, mano Dieve, tavimi pasikliauju; gelbėk mane nuo visų mano persekiotojų ir išvaduok mane;'),
  (@b19, 7, 2, 'kad nesudraskytų mano sielos kaip liūtas, draskantis ją į gabalus, kai nėra kam išvaduoti.'),
  (@b19, 7, 3, 'O VIEŠPATIE, mano Dieve, jei aš tai padariau; jei neteisybė yra mano rankose;'),
  (@b19, 7, 4, 'jei atsilyginau piktu tam, kuris buvo taikoje su manimi (taip, aš išvadavau tą, kuris be priežasties yra mano priešas);');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 7, 5, 'tegul priešas persekioja mano sielą ir ją sugauna; taip, tesutrypia į žemę mano gyvybę ir tepaguldo mano garbę į dulkes. Sela.'),
  (@b19, 7, 6, 'Kelkis, o VIEŠPATIE, savo pyktyje, pakilk dėl mano priešų įniršio; ir pabusk dėl manęs į teismą, kurį įsakei.'),
  (@b19, 7, 7, 'Taip tautų susirinkimas apsups tave; todėl dėl jų sugrįžk į aukštybę.'),
  (@b19, 7, 8, 'VIEŠPATS teis tautas; teisk mane, o VIEŠPATIE, pagal mano teisumą ir pagal mano dorumą, esantį manyje.'),
  (@b19, 7, 9, 'Teužsibaigia nedorėlių nedorybė; tačiau sutvirtink teisųjį; nes teisusis Dievas mėgina širdis ir inkstus.'),
  (@b19, 7, 10, 'Mano apsauga yra iš Dievo, kuris išgelbėja tiesiaširdžius.'),
  (@b19, 7, 11, 'Dievas teisia teisius, ir Dievas kasdien pyksta ant nedorėlių.'),
  (@b19, 7, 12, 'Jei neatsigręžia, jis galanda savo kalaviją; jis įtempė savo lanką ir jį paruošė.'),
  (@b19, 7, 13, 'Jis jam paruošė ir mirties įrankius; jis paskiria savo strėles prieš persekiotojus.'),
  (@b19, 7, 14, 'Štai jis pradeda neteisybę, yra nėščias piktadarybe ir pagimdė melą.'),
  (@b19, 7, 15, 'Jis padarė duobę ir ją iškasė, ir įkrito į griovį, kurį padarė.'),
  (@b19, 7, 16, 'Jo piktadarybė sugrįš ant jo paties galvos, ir jo smurtas nusileis ant jo paties viršugalvio.'),
  (@b19, 7, 17, 'Aš girsiu VIEŠPATĮ pagal jo teisumą; ir giedosiu gyrių aukščiausiojo VIEŠPATIES vardui.'),
  (@b19, 8, 1, 'Vyriausiajam muzikantui, gitietišku. Dovydo psalmė. O VIEŠPATIE, mūsų Viešpatie, koks puikus tavo vardas visoje žemėje! Tu pastatei savo šlovę virš dangų.'),
  (@b19, 8, 2, 'Iš kūdikių ir žindomųjų burnos tu paruošei stiprybę dėl savo priešų, kad nutildytum priešą ir keršytoją.'),
  (@b19, 8, 3, 'Kai įsižiūriu į tavo dangus, tavo pirštų darbą, į mėnulį ir žvaigždes, kurias tu išdėstei;'),
  (@b19, 8, 4, 'kas yra žmogus, kad jį atsimeni, ir žmogaus sūnus, kad jį aplankai?'),
  (@b19, 8, 5, 'Nes tu padarei jį truputį žemesnį už angelus ir apvainikavai jį šlove ir garbe.'),
  (@b19, 8, 6, 'Tu davei jam valdyti tavo rankų darbus; tu visa padėjai po jo kojomis:'),
  (@b19, 8, 7, 'visas avis ir jaučius, taip, ir lauko žvėris;'),
  (@b19, 8, 8, 'oro skrajūnus, jūros žuvis ir visa, kas eina jūrų takais.'),
  (@b19, 8, 9, 'O VIEŠPATIE, mūsų Viešpatie, koks puikus yra tavo vardas visoje žemėje!'),
  (@b19, 9, 1, 'Vyriausiajam muzikantui. Mūt labenu. Dovydo psalmė. Girsiu tave, o VIEŠPATIE, visa savo širdimi; skelbsiu visus tavo nuostabius darbus.'),
  (@b19, 9, 2, 'Aš būsiu linksmas ir džiūgausiu tavyje; giedosiu gyrių tavo vardui, o Aukščiausiasis.'),
  (@b19, 9, 3, 'Kai mano priešai bus pasukę atgal, jie pargrius ir pražus tavo akivaizdoje.'),
  (@b19, 9, 4, 'Nes tu išlaikei mano teisę ir mano bylą; tu sėdėjai soste, teisingai teisdamas.'),
  (@b19, 9, 5, 'Tu barei pagonis, sunaikinai nedorėlius, ištrynei jų vardą amžių amžiams.'),
  (@b19, 9, 6, 'O prieše, sunaikinimai atėjo į amžiną pabaigą; tu sugriovei miestus; jų atminimas pražuvo su jais.'),
  (@b19, 9, 7, 'Bet VIEŠPATS pasiliks per amžius; jis paruošė teismui savo sostą.'),
  (@b19, 9, 8, 'Ir jis teis pasaulį teisumu, jis vykdys teismą tautoms tiesumu.'),
  (@b19, 9, 9, 'VIEŠPATS bus ir prieglobstis engiamiems, prieglobstis vargo laikais.'),
  (@b19, 9, 10, 'Ir pasikliaus tavimi tie, kurie pažįsta tavo vardą; nes tu, VIEŠPATIE, nepalikai tų, kurie tavęs ieško.'),
  (@b19, 9, 11, 'Giedokite gyrių VIEŠPAČIUI, gyvenančiam Sione; skelbkite tautose jo darbus.'),
  (@b19, 9, 12, 'Kai jis atlieka tardymą dėl kraujo, jis atsimena juos; jis nepamiršta nusižeminusiųjų šauksmo.'),
  (@b19, 9, 13, 'Pasigailėk manęs, o VIEŠPATIE; pažvelk į mano vargą, kurį aš kenčiu nuo tų, kurie manęs nekenčia, tu, kuris mane pakeli iš mirties vartų;'),
  (@b19, 9, 14, 'kad skelbčiau visą tavo gyrių Siono dukters vartuose; aš džiaugsiuosi tavo išgelbėjimu.'),
  (@b19, 9, 15, 'Pagonys nugrimzdo į duobę, kurią jie padarė; į tinklą, kurį jie paslėpė, įkliuvo jų pačių koja.'),
  (@b19, 9, 16, 'VIEŠPATS pažįstamas pagal teismą, kurį jis vykdo; nedorėlis įsipainiojo į savo paties rankų darbą. Higajon. Sela.'),
  (@b19, 9, 17, 'Nedorėliai bus nukreipti į pragarą, ir visos tautos, kurios užmiršta Dievą.'),
  (@b19, 9, 18, 'Nes nepasiturintis nebus pamirštas visam laikui; beturčių lūkestis nepražus amžiams.'),
  (@b19, 9, 19, 'Kelkis, o VIEŠPATIE; teneįsigali žmogus; tebūna teisiami pagonys tavo akyse.'),
  (@b19, 9, 20, 'Įvaryk, o VIEŠPATIE, jiems baimę; kad žinotų tautos, kad jie tėra žmonės. Sela.'),
  (@b19, 10, 1, 'Kodėl tu, o VIEŠPATIE, stovi toli, kodėl bėdos laikais slepiesi?'),
  (@b19, 10, 2, 'Nedorėlis savo išdidume persekioja beturtį; tebūna jie sugauti tais kėslais, kuriuos sumanė.'),
  (@b19, 10, 3, 'Nes nedorėlis giriasi savo širdies troškimu ir laimina godųjį, kuriuo bjaurisi VIEŠPATS.'),
  (@b19, 10, 4, 'Nedorėlis dėl savo veido išdidumo neieškos Dievo; nėra Dievo visose jo mintyse.'),
  (@b19, 10, 5, 'Jo keliai visuomet sielvartingi; tavo teismai per aukštai, jam nematomi; o visi jo priešai – jis pasipučia prieš juos.'),
  (@b19, 10, 6, 'Jis pasakė savo širdyje: „Aš nesvyruosiu; nes niekada nepatirsiu nelaimės“.'),
  (@b19, 10, 7, 'Jo burna pilna keiksmo, apgaulės ir suktybės; po jo liežuviu – piktadarystė ir tuštybė.'),
  (@b19, 10, 8, 'Jis sėdi kaimų tykojimo vietose; slaptavietėse jis nužudo nekaltąjį; jo akys slapta nukreiptos prieš vargšą.'),
  (@b19, 10, 9, 'Jis tykoja paslapčiomis kaip liūtas savo urve; jis tykoja, kad sugautų vargšą; jis sugauna vargšą, įtraukdamas jį į savo tinklą.'),
  (@b19, 10, 10, 'Jis pritūpia ir prigula, kad vargšas kristų nuo jo stipriųjų.'),
  (@b19, 10, 11, 'Jis tarė savo širdyje: „Dievas pamiršo; slepia savo veidą; jis niekada to nepamatys“.'),
  (@b19, 10, 12, 'Kelkis, o VIEŠPATIE; o Dieve, pakelk savo ranką; nepamiršk nuolankiųjų.'),
  (@b19, 10, 13, 'Kodėl nedorėlis niekina Dievą? Jis kalbėjo savo širdyje: „Tu to nepareikalausi“.'),
  (@b19, 10, 14, 'Tu tai pamatei; nes tu žiūri į piktadarystę ir pagiežą, kad tai atlygintum savo ranka; vargšas tau save patiki; tu esi našlaičio padėjėjas.'),
  (@b19, 10, 15, 'Sulaužyk nedorėlio ir piktojo ranką; suieškok jo nedorybę, kol nieko neberasi.'),
  (@b19, 10, 16, 'VIEŠPATS yra Karalius per amžių amžius; pagonys pražuvę iš jo šalies.'),
  (@b19, 10, 17, 'VIEŠPATIE, tu išgirdai nuolankiųjų troškimą; tu paruoši jų širdį, tu padarysi, kad tavo ausis išgirs;'),
  (@b19, 10, 18, 'kad teistum našlaitį ir engiamąjį, kad žemės žmogus daugiau nebeengtų.'),
  (@b19, 11, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. VIEŠPAČIU pasikliauju; kaip jūs sakote mano sielai: „Pabėk kaip paukštis į jūsų kalną“?'),
  (@b19, 11, 2, 'Nes štai nedorėliai įtempia savo lanką, savo strėlę paruošia ant templės, kad slapta šaudytų į tiesiaširdžius.'),
  (@b19, 11, 3, 'Jei pamatai nugriauti, ką begali padaryti teisusis?“'),
  (@b19, 11, 4, 'VIEŠPATS yra savo šventoje šventykloje, VIEŠPATIES sostas danguje; jo akys stebi, jo akių vokai mėgina žmonių vaikus.'),
  (@b19, 11, 5, 'VIEŠPATS mėgina teisųjį; bet nedorėlio ir to, kuris mėgsta smurtą, nekenčia jo siela.'),
  (@b19, 11, 6, 'Ant nedorėlių jis lis žabangomis, ugnimi, siera ir siaubinga audra, tai bus jų taurės dalis.'),
  (@b19, 11, 7, 'Nes teisusis VIEŠPATS myli teisumą; jo veidas stebi tiesųjį.'),
  (@b19, 12, 1, 'Vyriausiajam muzikantui, Šeminitu. Dovydo psalmė. Padėk, VIEŠPATIE; nes nebelieka dievotųjų; nes pradingsta ištikimieji iš žmonių vaikų tarpo.'),
  (@b19, 12, 2, 'Kiekvienas su savo artimu kalba tuštybę; jie kalba pataikaujančiomis lūpomis ir dvilype širdimi.'),
  (@b19, 12, 3, 'VIEŠPATS iškirs visas pataikaujančias lūpas ir liežuvį, kalbantį pasididžiavimus;'),
  (@b19, 12, 4, 'kurie sakė: „Savo liežuviu nugalėsime; mūsų lūpos yra mūsų pačių; kas yra mūsų viešpats?“'),
  (@b19, 12, 5, '„Dėl vargšų engimo, dėl stokojančiųjų dejavimo dabar pakilsiu, – sako VIEŠPATS. – Aš pastatysiu jį į saugią vietą nuo to, kuris prieš jį pučiasi“.'),
  (@b19, 12, 6, 'VIEŠPATIES žodžiai yra tyri žodžiai, kaip sidabras, išmėgintas žemės krosnyje, septynis kartus išvalytas.'),
  (@b19, 12, 7, 'Tu juos išlaikysi, o VIEŠPATIE, tu juos išsaugosi nuo šitos kartos per amžius.'),
  (@b19, 12, 8, 'Nedorėliai vaikšto visose pusėse, kai niekšiški žmonės yra išaukštinti.'),
  (@b19, 13, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Kaip ilgai mane pamirši, o VIEŠPATIE? Ar amžinai? Kaip ilgai slėpsi nuo manęs savo veidą?'),
  (@b19, 13, 2, 'Kaip ilgai tarsiuos savo sieloje, kasdien liūdėdamas savo širdyje? Kaip ilgai mano priešas bus išaukštintas virš manęs?'),
  (@b19, 13, 3, 'Atsižvelk ir išklausyk mane, o VIEŠPATIE, mano Dieve; apšviesk mano akis, kad neužmigčiau mirties miegu;'),
  (@b19, 13, 4, 'kad mano priešas nesakytų: „Aš jį nugalėjau“; ir mano vargintojai nedžiūgautų, kai aš susvyruoju.'),
  (@b19, 13, 5, 'Bet aš pasitikėjau tavo gailestingumu; mano širdis džiaugsis tavo išgelbėjimu.'),
  (@b19, 13, 6, 'Giedosiu VIEŠPAČIUI, nes jis dosniai elgiasi su manimi.'),
  (@b19, 14, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Kvailys pasakė savo širdyje: „Nėra Dievo“. Jie sugedę, jie darė bjaurius darbus, nėra kas gera darytų.'),
  (@b19, 14, 2, 'VIEŠPATS pažvelgė žemyn iš dangaus į žmonių vaikus, kad pamatytų, ar yra kas supranta ir ieško Dievo.'),
  (@b19, 14, 3, 'Jie visi nukrypo į šoną, jie visi kartu tapo purvini; nėra kas darytų gera, nėra nei vieno.'),
  (@b19, 14, 4, 'Argi nežino visi, darantys neteisybę, tie, kurie ryja mano tautą, kaip jie valgo duoną, ir nesišaukia VIEŠPATIES?'),
  (@b19, 14, 5, 'Ten jie labai bijojo; nes Dievas yra teisiųjų kartoje.'),
  (@b19, 14, 6, 'Jūs sugėdinote vargšo patarimą, nes VIEŠPATS yra jo prieglobstis.'),
  (@b19, 14, 7, 'O kad Izraelio išgelbėjimas ateitų iš Siono! Kai VIEŠPATS grąžins savo tautos nelaisvę, džiaugsis Jokūbas ir linksminsis Izraelis.'),
  (@b19, 15, 1, 'Dovydo psalmė. VIEŠPATIE, kas pasiliks tavo padangtėje? Kas gyvens tavo šventojoje kalvoje?'),
  (@b19, 15, 2, 'Tas, kuris vaikšto tiesumu, daro teisumą ir kalba tiesą savo širdyje.'),
  (@b19, 15, 3, 'Kuris nešmeižia savo liežuviu, nedaro pikto savo artimui ir nesiima priekaišto prieš savo artimą;'),
  (@b19, 15, 4, 'kurio akyse niekšiškas asmuo yra paniekinamas; bet jis gerbia tuos, kurie bijo VIEŠPATIES. Kuris prisiekia savo paties žalai ir nekeičia.'),
  (@b19, 15, 5, 'Kuris neskolina savo pinigų palūkanoms ir neima dovanos prieš nekaltąjį. Kas tai daro, niekada nesusvyruos.'),
  (@b19, 16, 1, 'Dovydo miktam. Saugok mane, o Dieve; nes tavimi aš pasikliauju.'),
  (@b19, 16, 2, 'O mano siela, tu tarei VIEŠPAČIUI: „Tu esi mano Viešpats; mano gerovė tiesiasi ne į tave,'),
  (@b19, 16, 3, 'bet į šventuosius, esančius žemėje, ir į puikiuosius, kuriuose yra visas mano pasigėrėjimas.'),
  (@b19, 16, 4, 'Padaugės sielvartų tiems, kurie nuskuba paskui kitą dievą; aš neaukosiu jų geriamųjų kraujo atnašų nei neimsiu jų vardų į savo lūpas.'),
  (@b19, 16, 5, 'VIEŠPATS yra mano paveldo ir mano taurės dalis; tu išlaikai mano burtą.'),
  (@b19, 16, 6, 'Virvės man krito į geistinas vietas; taip, aš turiu gražų palikimą.'),
  (@b19, 16, 7, 'Laiminsiu VIEŠPATĮ, kuris man davė patarimą; taip pat nakties laikais mane pamoko mano inkstai.'),
  (@b19, 16, 8, 'Nuolatos statau VIEŠPATĮ prieš save; kadangi jis mano dešinėje, aš nesusvyruosiu.'),
  (@b19, 16, 9, 'Todėl linksminasi mano širdis ir džiūgauja mano šlovė; ir mano kūnas ilsėsis viltyje.'),
  (@b19, 16, 10, 'Nes tu nepaliksi mano sielos pragare; ir neleisi savo Šventajam pamatyti gedimo.'),
  (@b19, 16, 11, 'Tu man parodysi gyvenimo taką; tavo akivaizdoje yra džiaugsmo pilnatvė; tavo dešinėje – malonumai per amžius.'),
  (@b19, 17, 1, 'Dovydo malda. Išgirsk teisę, o VIEŠPATIE, išklausyk mano šauksmą, atkreipk ausį į mano maldą, išeinančią iš neapsimetančių lūpų.'),
  (@b19, 17, 2, 'Iš tavo akivaizdos teišeina mano nuosprendis: tavo akys temato tai, kas teisinga.'),
  (@b19, 17, 3, 'Tu išbandei mano širdį; aplankei mane naktį; mane išmėginai ir nieko neradai; aš nusprendžiau, kad mano burna nenusižengs.'),
  (@b19, 17, 4, 'O dėl žmonių darbų, – tavo lūpų žodžiu aš saugojausi nuo naikintojo takų.'),
  (@b19, 17, 5, 'Palaikyk mano ėjimus savo takuose, kad mano žingsniai nepaslystų.'),
  (@b19, 17, 6, 'Aš tavęs šaukiausi, nes tu, o Dieve, išgirsi mane; palenk prie manęs savo ausį ir išgirsk mano kalbą.'),
  (@b19, 17, 7, 'Parodyk savo nuostabų mylintį gerumą, tu, kuris savo dešine ranka gelbsti tavimi pasikliaujančius nuo tų, kurie sukyla prieš juos.'),
  (@b19, 17, 8, 'Saugok mane kaip akies obuolį, paslėpk mane savo sparnų šešėlyje'),
  (@b19, 17, 9, 'nuo nedorėlių, kurie engia mane, nuo mano mirtinų priešų, kurie mane apsupa.'),
  (@b19, 17, 10, 'Jie užsidarę savo taukuose; savo burna išdidžiai kalba.'),
  (@b19, 17, 11, 'Dabar jie mus apsupo mūsų žingsniuose; jie nukreipė savo akis, pasilenkdami prie žemės,'),
  (@b19, 17, 12, 'kaip liūtas, geidžiantis savo grobio, ir kaip jaunas liūtas, tykojantis slaptavietėse.'),
  (@b19, 17, 13, 'Kelkis, o VIEŠPATIE, sužlugdyk jo viltis, nuversk jį; išvaduok mano sielą nuo nedorėlio, kuris yra tavo kalavijas;'),
  (@b19, 17, 14, 'nuo žmonių, kurie yra tavo ranka, o VIEŠPATIE, nuo pasaulio žmonių, turinčių savo dalį šiame gyvenime, kurių pilvą tu pripildai savo slaptu lobiu; jie pilni vaikų, ir likusį savo turtą palieka savo kūdikiams.'),
  (@b19, 17, 15, 'O aš tavo veidą matysiu teisume; prabudęs pasisotinsiu tavo panašumu.'),
  (@b19, 18, 1, 'Vyriausiajam muzikantui. Psalmė VIEŠPATIES tarno Dovydo, kuris kalbėjo VIEŠPAČIUI šitos giesmės žodžius tą dieną, kai VIEŠPATS jį išvadavo iš visų jo priešų rankų ir iš Sauliaus rankų. Jis kalbėjo: Mylėsiu tave, o VIEŠPATIE, mano stiprybe.'),
  (@b19, 18, 2, 'VIEŠPATS yra mano uola, mano tvirtovė ir mano išvaduotojas; mano Dievas, mano stiprybė, kuriuo pasitikėsiu; mano skydas, mano išgelbėjimo ragas ir mano aukštas bokštas.'),
  (@b19, 18, 3, 'Šauksiuosi VIEŠPATIES, kuris vertas gyriaus; taip būsiu išgelbėtas iš savo priešų.'),
  (@b19, 18, 4, 'Mirties kančios apsupo mane, ir bedievių srovės gąsdino mane.'),
  (@b19, 18, 5, 'Pragaro kančios apsupo mane; mirties pinklės aplenkę pasitiko mane.'),
  (@b19, 18, 6, 'Savo suspaudime šaukiausi VIEŠPATIES ir šaukiau savo Dievui; jis išgirdo iš savo šventyklos mano balsą, ir mano šauksmas atėjo jo akivaizdon – į jo ausis.'),
  (@b19, 18, 7, 'Tada kratėsi ir drebėjo žemė; taip pat kalvų pamatai judėjo ir kratėsi, nes jis užsirūstino.'),
  (@b19, 18, 8, 'Pakilo dūmai iš jo šnervių, ir rijo ugnis iš jo burnos; nuo jos užsidegė anglys.'),
  (@b19, 18, 9, 'Jis palenkė dangus ir nužengė; tamsa buvo po jo kojomis.'),
  (@b19, 18, 10, 'Jis lėkė ant kerubo ir skrido; taip, jis skrido ant vėjo sparnų.'),
  (@b19, 18, 11, 'Tamsą jis padarė savo slaptaviete; jo palapinė aplink jį buvo tamsūs vandenys ir tiršti padangių debesys.'),
  (@b19, 18, 12, 'Nuo spindesio, esančio jo priešaky, slinko jo tiršti debesys, krušos ledokšniai ir ugnies žarijos.'),
  (@b19, 18, 13, 'Sugriaudė danguose VIEŠPATS, ir Aukščiausiasis išleido savo balsą, krušos ledokšnius ir ugningas žarijas.'),
  (@b19, 18, 14, 'Taip, jis išsiuntė savo strėles ir juos išsklaidė; jis šaudė žaibus ir juos sutrikdė.'),
  (@b19, 18, 15, 'Tada pasimatė vandenų vagos ir atsiskleidė pasaulio pamatai nuo tavo barimo, o VIEŠPATIE, nuo tavo šnervių kvapo pūtimo.'),
  (@b19, 18, 16, 'Jis pasiuntė iš viršaus, mane paėmė, jis mane ištraukė iš daugybės vandenų.'),
  (@b19, 18, 17, 'Jis išvadavo mane iš mano stipraus priešo ir iš tų, kurie manęs nekentė; nes jie buvo man per stiprūs.'),
  (@b19, 18, 18, 'Jie aplenkę pasitiko mane mano nelaimės dieną; bet VIEŠPATS buvo mano atrama.'),
  (@b19, 18, 19, 'Jis išvedė mane į plačią vietą; jis mane išvadavo, nes manimi gėrėjosi.'),
  (@b19, 18, 20, 'VIEŠPATS man atlygino pagal mano teisumą; pagal mano rankų švarumą jis man atmokėjo.'),
  (@b19, 18, 21, 'Nes aš laikiausi VIEŠPATIES kelių ir neatsitraukiau nedorai nuo savo Dievo.'),
  (@b19, 18, 22, 'Nes visi jo teismai buvo mano priešakyje, ir jo įstatų nuo savęs neatmečiau.'),
  (@b19, 18, 23, 'Tiesus buvau jo akivaizdoje ir saugojausi nuo savo neteisybės.'),
  (@b19, 18, 24, 'Todėl VIEŠPATS man atmokėjo pagal mano teisumą, pagal mano rankų švarumą jo akyse.'),
  (@b19, 18, 25, 'Gailestingam tu pasirodai gailestingas; tiesiam tu pasirodai tiesus;'),
  (@b19, 18, 26, 'tyram tu pasirodai tyras; priešgyniam tu pasirodai priešgynus.'),
  (@b19, 18, 27, 'Nes tu gelbėji varginamus žmones; bet pažemini išdidžius žvilgsnius.'),
  (@b19, 18, 28, 'Nes tu uždegsi mano žvakę; VIEŠPATS, mano Dievas, apšvies mano tamsą.'),
  (@b19, 18, 29, 'Nes su tavimi perbėgau pulką; su savo Dievu peršokau sieną.'),
  (@b19, 18, 30, 'O Dievas – tobulas jo kelias; VIEŠPATIES žodis yra išbandytas; jis yra skydas visiems, kurie juo pasitiki.'),
  (@b19, 18, 31, 'Juk kas yra Dievas, jei ne VIEŠPATS? Arba, kas yra uola, jei ne mūsų Dievas?'),
  (@b19, 18, 32, 'Tai Dievas, kuris apjuosia mane jėga ir padaro mano kelią tobulą.'),
  (@b19, 18, 33, 'Jis padaro mano kojas kaip elnės ir pastato mane mano aukštumose.'),
  (@b19, 18, 34, 'Jis moko mano rankas kovoti taip, kad mano rankomis sulaužomas plieninis lankas.'),
  (@b19, 18, 35, 'Tu man davei ir tavo išgelbėjimo skydą; ir tavo dešinė mane palaikė, o tavo švelnumas mane padarė didį.'),
  (@b19, 18, 36, 'Tu praplatinai mano žingsnius po manimi, kad mano kojos nepaslystų.'),
  (@b19, 18, 37, 'Aš persekiojau savo priešus ir juos pasivijau; ir neapsigręžiau, kol jie nebuvo sunaikinti.'),
  (@b19, 18, 38, 'Aš juos sužeidžiau, kad jie nebegalėjo atsikelti; jie krito po mano kojomis.'),
  (@b19, 18, 39, 'Nes tu apjuosei mane stiprybe mūšiui; tu pajungei po manimi tuos, kurie pakilo prieš mane.'),
  (@b19, 18, 40, 'Tu man davei ir mano priešų sprandus; kad sunaikinčiau tuos, kurie manęs nekenčia.'),
  (@b19, 18, 41, 'Jie šaukėsi, bet nebuvo, kas juos gelbėtų; – VIEŠPATIES, bet jis jiems neatsiliepė.'),
  (@b19, 18, 42, 'Tada aš juos sutryniau smulkiai kaip dulkes prieš vėją; išmečiau juos kaip purvą gatvėse.'),
  (@b19, 18, 43, 'Tu mane išvadavai iš tautos vaidų; ir paskyrei mane pagonių galva; tauta, kurios nebuvau pažinęs, man tarnaus.'),
  (@b19, 18, 44, 'Kai tik išgirs apie mane, jie man paklus; svetimšaliai man pasiduos.'),
  (@b19, 18, 45, 'Svetimšaliai išblykš ir bijos iš savo slaptų vietų.'),
  (@b19, 18, 46, 'VIEŠPATS gyvas; tebūna palaiminta mano uola; tebūna aukštinamas mano išgelbėjimo Dievas.'),
  (@b19, 18, 47, 'Tai Dievas, kuris atkeršija už mane ir pavergia man tautas.'),
  (@b19, 18, 48, 'Jis išvaduoja mane iš mano priešų; taip, tu mane iškeli viršum tų, kurie prieš mane pakyla; tu mane išvadavai iš smurtininko.'),
  (@b19, 18, 49, 'Todėl dėkosiu tau, o VIEŠPATIE, tarp pagonių ir giedosiu gyrių tavo vardui.'),
  (@b19, 18, 50, 'Didelį išvadavimą jis suteikia savo karaliui; ir parodo gailestingumą savo pateptajam, Dovydui, ir jo sėklai per amžius.'),
  (@b19, 19, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Dangūs skelbia Dievo šlovę; ir tvirtuma praneša apie jo rankų darbą.'),
  (@b19, 19, 2, 'Diena ištaria kalbą dienai, o naktis praneša nakčiai pažinimą.'),
  (@b19, 19, 3, 'Nėra nei kalbos, nei tarmės, kur nebūtų girdimas jų balsas.'),
  (@b19, 19, 4, 'Jų virvė išėjo po visą žemę, ir jų žodžiai iki pasaulio krašto. Juose jis pastatė padangtę saulei,'),
  (@b19, 19, 5, 'kuri kaip jaunikis išeinantis iš savo kambario ir džiaugiasi kaip stipruolis, bėgsiantis lenktynėse.'),
  (@b19, 19, 6, 'Jos išėjimas yra nuo dangaus krašto ir jos ėjimas ratu į jo pakraščius; ir nieko nėra paslėpta nuo jos kaitros.'),
  (@b19, 19, 7, 'VIEŠPATIES įstatymas tobulas, atverčiantis sielą; VIEŠPATIES liudijimas tikras, padarantis paikuosius išmintingais.'),
  (@b19, 19, 8, 'VIEŠPATIES įstatai teisingi, džiuginantys širdį; VIEŠPATIES įsakymas tyras, apšviečiantis akis.'),
  (@b19, 19, 9, 'VIEŠPATIES baimė švari, pasiliekanti per amžius; VIEŠPATIES teismai teisingi ir visumoje teisūs.'),
  (@b19, 19, 10, 'Jie turi būti geistini labiau už auksą, taip, už daug gryno aukso; taip pat saldesni už medų ir medaus korį.'),
  (@b19, 19, 11, 'Be to, tavo tarnas jais įspėjamas: jų besilaikant yra didelis atlygis.'),
  (@b19, 19, 12, 'Kas gali suprasti savo paklydimus? Apvalyk mane nuo slaptų kalčių.'),
  (@b19, 19, 13, 'Sulaikyk savo tarną ir nuo tyčinių nuodėmių; teneviešpatauja jos man; tada aš būsiu tiesus ir būsiu nekaltas dėl didelio nusižengimo.'),
  (@b19, 19, 14, 'Tebūna priimtini tavo akyse mano burnos žodžiai ir mano širdies apmąstymas, o VIEŠPATIE, mano stiprybe ir mano atpirkėjau.'),
  (@b19, 20, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. VIEŠPATS tegirdi tave bėdos dieną; teapgina tave Jokūbo Dievo vardas;'),
  (@b19, 20, 2, 'tau tesiunčia pagalbą iš šventovės ir tesustiprina tave iš Siono;'),
  (@b19, 20, 3, 'teprisimena visas tavo atnašas ir tepriima tavo deginamąją auką; Sela.'),
  (@b19, 20, 4, 'Tau tesuteikia pagal tavo paties širdį ir teišpildo visą tavo sumanymą.'),
  (@b19, 20, 5, 'Mes džiaugsimės tavo išgelbėjimu ir mūsų Dievo vardu iškelsime mūsų vėliavas; VIEŠPATS teįvykdo visus tavo prašymus.'),
  (@b19, 20, 6, 'Dabar žinau, kad VIEŠPATS gelbsti savo pateptąjį; jis išgirs jį iš savo šventojo dangaus savo dešinės gelbėjančia stiprybe.'),
  (@b19, 20, 7, 'Vieni pasitiki vežimais, kiti žirgais; bet mes prisiminsime VIEŠPATIES, mūsų Dievo, vardą.'),
  (@b19, 20, 8, 'Jie pargriauti ir kritę; bet mes pakilę ir stovime tiesūs.'),
  (@b19, 20, 9, 'Išgelbėk, VIEŠPATIE; tegul karalius mus išgirsta, kai šaukiamės.'),
  (@b19, 21, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. O VIEŠPATIE, tavo stiprybe džiaugsis karalius; ir kaip didžiai jis džiūgaus tavo išgelbėjimu!'),
  (@b19, 21, 2, 'Tu jam davei jo širdies troškimą, ir jo lūpų prašymo nesulaikei. Sela.'),
  (@b19, 21, 3, 'Nes jį pasitikai gerumo palaiminimais; uždėjai jam ant galvos gryno aukso karūną.'),
  (@b19, 21, 4, 'Jis prašė tavęs gyvenimo, ir tu jį davei jam – dienų ilgumą per amžių amžius.'),
  (@b19, 21, 5, 'Didelė jo šlovė tavo išgelbėjime; garbę ir didybę tu uždėjai ant jo.'),
  (@b19, 21, 6, 'Nes jį padarei labiausiai palaimintu amžiams; tu savo veidu padarei jį nepaprastai džiugiu.'),
  (@b19, 21, 7, 'Nes karalius pasitiki VIEŠPAČIU, ir dėl Aukščiausiojo gailestingumo jis nesvyruos.'),
  (@b19, 21, 8, 'Tavo ranka suras visus tavo priešus; tavo dešinė suras tuos, kurie tavęs nekenčia.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 21, 9, 'Savo pykčio metu tu juos padarysi kaip liepsnojančią krosnį; VIEŠPATS savo rūstybėje juos praris, ir juos suris ugnis.'),
  (@b19, 21, 10, 'Jų vaisių tu išnaikinsi nuo žemės ir jų sėklą iš žmonių vaikų tarpo.'),
  (@b19, 21, 11, 'Nes jie planavo prieš tave pikta; jie sumanė piktą sumanymą, kurio jie nepajėgia įvykdyti.'),
  (@b19, 21, 12, 'Todėl tu priversi juos atsukti nugaras, kai paruoši savo strėles ant savo templės priešais jų veidus.'),
  (@b19, 21, 13, 'Būk išaukštintas, VIEŠPATIE, savo stiprybe; taip mes giedosime ir girsime tavo jėgą.'),
  (@b19, 22, 1, 'Vyriausiajam muzikantui Aijelet Šacharu. Dovydo psalmė. Mano Dieve, mano Dieve, kodėl mane palikai? Kodėl esi taip toli nuo pagalbos man ir nuo mano kauksmo žodžių?'),
  (@b19, 22, 2, 'O mano Dieve, šaukiu aš dieną, bet tu negirdi; ir nakties laiku, ir netyliu.'),
  (@b19, 22, 3, 'Bet tu esi šventas, tu, kuris gyveni Izraelio gyriuje.'),
  (@b19, 22, 4, 'Tavimi pasitikėjo mūsų tėvai; jie pasitikėjo, ir tu juos išvadavai.'),
  (@b19, 22, 5, 'Jie šaukėsi tavęs ir buvo išvaduoti; jie tavimi pasitikėjo ir nebuvo sugėdinti.'),
  (@b19, 22, 6, 'Bet aš esu kirminas, o ne žmogus; žmonių priekaištas ir tautos paniekintas.'),
  (@b19, 22, 7, 'Visi tie, kurie mane mato, išjuokia mane; jie atkiša lūpas, kraipo galvą, sakydami:'),
  (@b19, 22, 8, '„Jis pasitikėjo VIEŠPAČIU, kad jis jį išvaduos; tegul jis išvaduoja jį, nes juo gėrėjosi“.'),
  (@b19, 22, 9, 'Bet tu esi tas, kuris mane ištraukei iš įsčių; tu padarei, kad vilčiausi, kai buvau prie savo motinos krūtų.'),
  (@b19, 22, 10, 'Ant tavęs buvau užmestas nuo pat įsčių; nuo pat mano motinos pilvo tu esi mano Dievas.'),
  (@b19, 22, 11, 'Nebūk toli nuo manęs, nes bėda arti, nes nėra kas padėtų.'),
  (@b19, 22, 12, 'Daug jaučių mane apsupo; stiprūs Bašano jaučiai mane apstojo.'),
  (@b19, 22, 13, 'Jie išsižiojo prieš mane savo nasrais kaip plėšrus ir riaumojantis liūtas.'),
  (@b19, 22, 14, 'Aš išlietas kaip vanduo, ir visi mano kaulai išsinarstę; mano širdis kaip vaškas; ištirpo mano viduriuose.'),
  (@b19, 22, 15, 'Mano stiprybė išdžiūvo kaip šukė; ir mano liežuvis limpa man prie žandikaulių; tu atvedei mane į mirties dulkes.'),
  (@b19, 22, 16, 'Nes mane apsupo šunys; nedorėlių sambūris mane apsupo; jie perdūrė mano rankas ir mano kojas.'),
  (@b19, 22, 17, 'Galiu suskaičiuoti visus savo kaulus; jie žiūri ir spokso į mane.'),
  (@b19, 22, 18, 'Jie dalijasi tarpusavyje mano drabužius ir dėl mano apdaro meta burtą.'),
  (@b19, 22, 19, 'Bet tu, o VIEŠPATIE, nebūk toli nuo manęs; o mano stiprybe, skubėk man padėti.'),
  (@b19, 22, 20, 'Nuo kalavijo išvaduok mano sielą; mano brangiausiąją nuo šuns galios.'),
  (@b19, 22, 21, 'Gelbėk mane iš liūto nasrų; nes tu išgirdai mane nuo vienaragių ragų.'),
  (@b19, 22, 22, 'Aš paskelbsiu tavo vardą savo broliams; susirinkimo viduryje tave girsiu.'),
  (@b19, 22, 23, 'Jūs, kurie bijote VIEŠPATIES, girkite jį; visi, jūs – Jokūbo sėkla, šlovinkite jį; ir bijokite jo visi, jūs – Izraelio sėkla.'),
  (@b19, 22, 24, 'Nes jis nepaniekino ir nesibjaurėjo kamuojamojo kančia; ir nepaslėpė nuo jo savo veido; bet kai jis jo šaukėsi, jis išgirdo.'),
  (@b19, 22, 25, 'Mano gyrius dideliame susirinkime bus apie tave; savo įžadus ištesėsiu akivaizdoje tų, kurie jo bijo.'),
  (@b19, 22, 26, 'Romusis valgys ir pasisotins; VIEŠPATĮ girs tie, kurie jo ieško; jūsų širdis gyvens per amžius.'),
  (@b19, 22, 27, 'Visi žemės pakraščiai prisimins ir gręšis į VIEŠPATĮ; visos tautų giminės garbins tavo akivaizdoje.'),
  (@b19, 22, 28, 'Nes karalystė yra VIEŠPATIES; ir jis yra valdytojas tautų tarpe.'),
  (@b19, 22, 29, 'Visi žemės riebieji valgys ir garbins; nusilenks prieš jį visi, kurie nužengia į dulkes, ir niekas negali išlaikyti savo sielos gyvos.'),
  (@b19, 22, 30, 'Sėkla tarnaus jam; ji bus Viešpačiui laikoma kaip karta.'),
  (@b19, 22, 31, 'Jie ateis ir skelbs jo teisumą gimsiančiai tautai, kad jis tai padarė.'),
  (@b19, 23, 1, 'Dovydo psalmė. VIEŠPATS yra mano ganytojas; aš nestokosiu.'),
  (@b19, 23, 2, 'Jis paguldo mane žaliuojančiose ganyklose; jis vedžioja mane prie tylių vandenų.'),
  (@b19, 23, 3, 'Jis atstato mano sielą; jis veda mane teisumo takais dėl savo vardo.'),
  (@b19, 23, 4, 'Taip, nors aš eičiau per mirties šešėlio slėnį, nebijosiu pikto; nes tu su manimi; tavo lazda ir tavo ramstis paguodžia mane.'),
  (@b19, 23, 5, 'Tu paruoši prieš mane stalą mano priešų akivaizdoje; aliejumi man patepi galvą; mano taurė liejasi per kraštus.'),
  (@b19, 23, 6, 'Tikrai gerumas ir gailestingumas mane seks per visas mano gyvenimo dienas; ir aš gyvensiu VIEŠPATIES namuose per amžius.'),
  (@b19, 24, 1, 'Dovydo psalmė. VIEŠPATIES yra žemė ir jos pilnumas, pasaulis ir jame gyvenantys.'),
  (@b19, 24, 2, 'Nes jis ant jūrų ją pastatė, ant srovių ją įtvirtino.'),
  (@b19, 24, 3, 'Kas pakils į VIEŠPATIES kalvą? Arba kas atsistos jo šventoje vietoje?'),
  (@b19, 24, 4, 'Tas, kas turi švarias rankas ir tyrą širdį; kas nekėlė savo sielos į tuštybę ir neprisiekė apgaulingai.'),
  (@b19, 24, 5, 'Tas gaus palaiminimą iš VIEŠPATIES ir teisumą iš savo išgelbėjimo Dievo.'),
  (@b19, 24, 6, 'Tai yra karta tų, kurie jo ieško, kurie ieško tavo veido, o Jokūbai. Sela.'),
  (@b19, 24, 7, 'Pakelkite savo galvas, o vartai; ir pasikelkite, amžinosios durys; ir šlovės Karalius įeis.'),
  (@b19, 24, 8, 'Kas yra tas šlovės Karalius? VIEŠPATS stiprus ir galingas, VIEŠPATS galingas mūšyje.'),
  (@b19, 24, 9, 'Pakelkite savo galvas, o vartai; pakelkite jas, amžinosios durys; ir šlovės Karalius įeis.'),
  (@b19, 24, 10, 'Kas yra tas šlovės Karalius? Kariuomenių VIEŠPATS – jis yra šlovės Karalius. Sela.'),
  (@b19, 25, 1, 'Dovydo psalmė. VIEŠPATIE, į tave keliu savo sielą.'),
  (@b19, 25, 2, 'O mano Dieve, tavimi pasitikiu: tenebūsiu sugėdintas, tenetriumfuoja prieš mane mano priešai.'),
  (@b19, 25, 3, 'Taip, tenebūna sugėdintas nei vienas, kuris tavęs laukia; tebūna sugėdinti tie, kurie nusižengia be priežasties.'),
  (@b19, 25, 4, 'Parodyk, o VIEŠPATIE, man savo kelius; pamokyk mane savo takų.'),
  (@b19, 25, 5, 'Vesk mane savo tiesa ir mokyk mane; nes tu esi mano išgelbėjimo Dievas; tavęs aš laukiau visą dieną.'),
  (@b19, 25, 6, 'Atsimink, o VIEŠPATIE, savo švelnius gailestingumus ir savo mylinčius gerumus; nes jie visada yra buvę nuo seno.'),
  (@b19, 25, 7, 'Neatsimink mano jaunystės nuodėmių nei mano nusižengimų; o VIEŠPATIE, atsimink mane pagal savo gailestingumą dėl savo gerumo.'),
  (@b19, 25, 8, 'Geras ir tiesus yra VIEŠPATS; todėl jis pamokys nusidėjėlius kelyje.'),
  (@b19, 25, 9, 'Romiuosius jis ves teismu; romiuosius jis mokys savo kelio.'),
  (@b19, 25, 10, 'Visi VIEŠPATIES takai yra gailestingumas ir tiesa tiems, kurie laikosi jo sandoros ir jo liudijimų.'),
  (@b19, 25, 11, 'Dėl savo vardo, o VIEŠPATIE, atleisk mano neteisybę, nes ji didelė.'),
  (@b19, 25, 12, 'Kas yra tas žmogus, kuris bijo VIEŠPATIES? Tą jis pamokys kelyje, kurį šis pasirinks.'),
  (@b19, 25, 13, 'Jo siela ramiai gyvens; ir jo sėkla paveldės žemę.'),
  (@b19, 25, 14, 'VIEŠPATIES paslaptis su tais, kurie jo bijo; ir jiems jis paskelbs savo sandorą.'),
  (@b19, 25, 15, 'Mano akys visada nukreiptos į VIEŠPATĮ; nes jis ištrauks mano kojas iš tinklo.'),
  (@b19, 25, 16, 'Atsigręžk į mane ir pasigailėk manęs; nes aš apleistas ir kamuojuosi.'),
  (@b19, 25, 17, 'Mano širdies neramumai padidėjo; išvesk mane iš mano sielvartų.'),
  (@b19, 25, 18, 'Pažvelk į mano kančią ir mano skausmą; ir atleisk visas mano nuodėmes.'),
  (@b19, 25, 19, 'Pažiūrėk į mano priešus; nes jų yra daug; jie manęs nekenčia žiauria neapykanta.'),
  (@b19, 25, 20, 'Saugok mano sielą ir išvaduok mane; tenebūsiu sugėdintas; nes pasikliauju tavimi.'),
  (@b19, 25, 21, 'Dorumas ir tiesumas teišsaugo mane; nes aš laukiu tavęs.'),
  (@b19, 25, 22, 'O Dieve, atpirk Izraelį iš visų jo bėdų.'),
  (@b19, 26, 1, 'Dovydo psalmė. Teisk mane, o VIEŠPATIE; nes aš vaikščiojau savo dorume; ir pasitikėjau VIEŠPAČIU; todėl aš nepaslysiu.'),
  (@b19, 26, 2, 'Ištirk mane, o VIEŠPATIE, ir išmėgink mane; išbandyk mano inkstus ir širdį.'),
  (@b19, 26, 3, 'Nes tavo mylintis gerumas man prieš akis; ir aš vaikščiojau tavo tiesoje.'),
  (@b19, 26, 4, 'Aš nesėdėjau su tuščiais žmonėmis ir neinu su apsimetėliais.'),
  (@b19, 26, 5, 'Aš nekenčiau piktadarių susirinkimo; ir nesisėsiu su nedorėliais.'),
  (@b19, 26, 6, 'Aš plausiu savo rankas nekaltume; taip eisiu aplink tavo aukurą, o VIEŠPATIE;'),
  (@b19, 26, 7, 'kad skelbčiau padėkos balsu ir pasakočiau apie visus tavo nuostabius darbus.'),
  (@b19, 26, 8, 'VIEŠPATIE, aš pamilau tavo namų buveinę ir vietą, kur tavo garbė gyvena.'),
  (@b19, 26, 9, 'Nesurink mano sielos su nusidėjėliais nei mano gyvybės su kraugeriais,'),
  (@b19, 26, 10, 'kurių rankose piktadarybė, ir jų dešinė pilna kyšių.'),
  (@b19, 26, 11, 'Bet aš, aš vaikščiosiu savo dorume; atpirk mane ir būk man gailestingas.'),
  (@b19, 26, 12, 'Mano koja stovi lygioje vietoje; susirinkimuose aš laiminsiu VIEŠPATĮ.'),
  (@b19, 27, 1, 'Dovydo psalmė. VIEŠPATS – mano šviesa ir mano išgelbėjimas: ko man bijoti? VIEŠPATS – mano gyvenimo stiprybė: ko man išsigąsti?'),
  (@b19, 27, 2, 'Kai nedorėliai, tai yra, mano priešai ir mano priešininkai užpuolė mane, kad suėstų mano kūną, jie suklupo ir griuvo.'),
  (@b19, 27, 3, 'Nors stovyklautų prieš mane kariuomenė, nenusigąs mano širdis; nors karas kiltų prieš mane, tame aš būsiu užtikrintas.'),
  (@b19, 27, 4, 'Vieno dalyko trokšiu iš VIEŠPATIES, to aš sieksiu: kad galėčiau gyventi VIEŠPATIES namuose per visas savo gyvenimo dienas, kad stebėčiau VIEŠPATIES grožį ir klausinėčiau jo šventykloje.'),
  (@b19, 27, 5, 'Nes jis paslėps mane savo palapinėje nelaimės dieną; paslėps mane savo padangtės slaptoje vietoje; ant uolos pastatys mane.'),
  (@b19, 27, 6, 'O dabar mano galva bus pakelta virš mano priešų, esančių aplink mane; todėl aš atnašausiu jo padangtėje džiaugsmo aukas; aš giedosiu, taip, aš giedosiu VIEŠPAČIUI gyrių.'),
  (@b19, 27, 7, 'Išgirsk, o VIEŠPATIE, kai šaukiu savo balsu; pasigailėk manęs ir man atsakyk.'),
  (@b19, 27, 8, 'Kai tu sakei: „Ieškokite mano veido“, mano širdis tau tarė: „Tavo veido, VIEŠPATIE, aš ieškosiu“.'),
  (@b19, 27, 9, 'Neslėpk savo veido toli nuo manęs; neatstumk pyktyje savo tarno; tu buvai mano pagalba; nepalik manęs ir neapleisk manęs, o mano išgelbėjimo Dieve.'),
  (@b19, 27, 10, 'Kai mano tėvas ir mano motina apleis mane, tada VIEŠPATS mane priims.'),
  (@b19, 27, 11, 'O VIEŠPATIE, mokyk mane savo kelio ir vesk mane lygiu taku dėl mano priešų.'),
  (@b19, 27, 12, 'Neatiduok manęs mano priešų valiai; nes sukilo prieš mane melagingi liudytojai ir iškvepiantys žiaurumą.'),
  (@b19, 27, 13, 'Būčiau nusilpęs, jei nebūčiau tikėjęs, kad matysiu VIEŠPATIES gerumą gyvųjų šalyje.'),
  (@b19, 27, 14, 'Lauk VIEŠPATIES; būk drąsus, ir jis sustiprins tavo širdį; lauk, aš sakau, VIEŠPATIES.'),
  (@b19, 28, 1, 'Dovydo psalmė. Tavęs šauksiuosi, o VIEŠPATIE, mano uola; man netylėk; kad, jei man tylėsi, aš netapčiau kaip tie, kurie eina žemyn į duobę.'),
  (@b19, 28, 2, 'Išgirsk mano prašymų balsą, kai šaukiuosi tavęs, kai pakeliu savo rankas į tavo šventą orakulą.'),
  (@b19, 28, 3, 'Neatstumk manęs su nedorėliais ir su tais, kurie daro neteisybę, kurie kalba taiką savo artimiems, bet piktadarystė jų širdyse.'),
  (@b19, 28, 4, 'Duok jiems pagal jų darbus ir pagal jų siekių nedorybę; duok jiems pagal jų rankų darbą; atiduok jiems jų nuopelnus.'),
  (@b19, 28, 5, 'Kadangi jie nepaiso VIEŠPATIES darbų nei jo rankų veikimo, jis juos sunaikins ir jų nestatys.'),
  (@b19, 28, 6, 'Tebūna palaimintas VIEŠPATS, nes jis išgirdo mano prašymų balsą.'),
  (@b19, 28, 7, 'VIEŠPATS yra mano stiprybė ir mano skydas; juo pasitikėjo mano širdis, ir man yra pagelbėta; todėl didžiai džiūgauja mano širdis; ir savo giesme aš jį girsiu.'),
  (@b19, 28, 8, 'VIEŠPATS yra jų stiprybė, ir jis yra jo pateptojo gelbstinti stiprybė.'),
  (@b19, 28, 9, 'Gelbėk savo tautą ir laimink savo paveldą; ganyk juos ir iškelk juos per amžius.'),
  (@b19, 29, 1, 'Dovydo psalmė. Suteikite VIEŠPAČIUI, o jūs, galiūnai, suteikite VIEŠPAČIUI šlovę ir stiprybę.'),
  (@b19, 29, 2, 'Suteikite VIEŠPAČIUI jo vardui priklausančią šlovę; garbinkite VIEŠPATĮ šventumo grožyje.'),
  (@b19, 29, 3, 'VIEŠPATIES balsas viršum vandenų; šlovės Dievas griaudėja; VIEŠPATS viršum daugybės vandenų.'),
  (@b19, 29, 4, 'VIEŠPATIES balsas galingas; VIEŠPATIES balsas pilnas didybės.'),
  (@b19, 29, 5, 'VIEŠPATIES balsas laužo kedrus; taip, VIEŠPATS laužo Libano kedrus.'),
  (@b19, 29, 6, 'Jis šokdina juos kaip veršius; Libaną ir Sirjoną, kaip jauną vienaragį.'),
  (@b19, 29, 7, 'VIEŠPATIES balsas ugnies liepsnas padalija.'),
  (@b19, 29, 8, 'VIEŠPATIES balsas sudrebina dykumą; VIEŠPATS sudrebina Kadešo dykumą.'),
  (@b19, 29, 9, 'VIEŠPATIES balsas skatina elnes gimdyti ir atidengia miškus; ir jo šventykloje visi apie jo šlovę kalba.'),
  (@b19, 29, 10, 'VIEŠPATS sėdi viršum tvano; taip, VIEŠPATS sėdi Karaliumi per amžius.'),
  (@b19, 29, 11, 'VIEŠPATS suteiks stiprybę savo tautai; VIEŠPATS palaimins savo tautą taika.'),
  (@b19, 30, 1, 'Psalmė ir Giesmė pašvenčiant Dovydo namus. Liaupsinsiu tave, o VIEŠPATIE; nes tu mane iškėlei, ir neleidai mano priešams džiaugtis dėl manęs.'),
  (@b19, 30, 2, 'O VIEŠPATIE, mano Dieve, šaukiausi tavęs, ir tu išgydei mane.'),
  (@b19, 30, 3, 'O VIEŠPATIE, tu išvedei iš kapo mano sielą; išlaikei mane gyvą, kad nenužengčiau į duobę.'),
  (@b19, 30, 4, 'Giedokite VIEŠPAČIUI, o jūs, jo šventieji, ir dėkokite prisiminę jo šventumą.'),
  (@b19, 30, 5, 'Nes tik akimirksnį trunka jo pyktis; jo palankume yra gyvenimas; verksmas gali trukti naktį, tačiau ryte ateina džiaugsmas.'),
  (@b19, 30, 6, 'Klestėdamas aš sakiau: „Niekada nesvyruosiu“.'),
  (@b19, 30, 7, 'VIEŠPATIE, savo palankumu tu padarei, kad mano kalnas stovėtų tvirtai; tu paslėpei savo veidą, ir aš sunerimau.'),
  (@b19, 30, 8, 'Tavęs, o VIEŠPATIE, šaukiausi; ir VIEŠPATĮ maldavau.'),
  (@b19, 30, 9, 'Kokia nauda iš mano kraujo, kai nužengiu į duobę? Ar girs tave dulkės? Ar jos skelbs tavo tiesą?'),
  (@b19, 30, 10, 'Išgirsk, o VIEŠPATIE, ir pasigailėk manęs; VIEŠPATIE, būk man padėjėjas.'),
  (@b19, 30, 11, 'Tu man pavertei mano raudą šokiu; nuvilkai man ašutinę ir apjuosei mane linksmybe'),
  (@b19, 30, 12, 'tam, kad mano šlovė tau giedotų gyrių ir netylėtų. O VIEŠPATIE, mano Dieve, per amžius tau dėkosiu.'),
  (@b19, 31, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Tavimi, o VIEŠPATIE, pasikliauju; niekados tenebūsiu sugėdintas; išvaduok mane savo teisumu.'),
  (@b19, 31, 2, 'Palenk prie manęs savo ausį; skubiai išvaduok mane; būk man stipri uola, apsaugos namais mane išgelbėti.'),
  (@b19, 31, 3, 'Nes tu esi mano uola ir mano tvirtovė; todėl dėl savo vardo vesk mane ir vadovauk man.'),
  (@b19, 31, 4, 'Ištrauk mane iš tinklo, kurį slaptai man padėjo; nes tu esi mano stiprybė.'),
  (@b19, 31, 5, 'Į tavo ranką pavedu savo dvasią; tu atpirkai mane, o VIEŠPATIE, tiesos Dieve.'),
  (@b19, 31, 6, 'Nekenčiau tų, kurie atsižvelgia į apgaulingas tuštybes; bet aš pasitikiu VIEŠPAČIU.'),
  (@b19, 31, 7, 'Linksminsiuos ir džiūgausiu tavo gailestingume; nes tu pažvelgei į mano bėdą; tu pažinai mano sielą nelaimėse;'),
  (@b19, 31, 8, 'ir manęs neuždarei priešo rankoje; tu pastatei mano kojas plačioje vietoje.'),
  (@b19, 31, 9, 'Pasigailėk manęs, o VIEŠPATIE, nes esu bėdoje; iš sielvarto išseko mano akis, taip, mano siela ir mano pilvas.'),
  (@b19, 31, 10, 'Nes su širdgėla praleistas mano gyvenimas ir mano metai su vaitojimu; išseko mano jėgos dėl mano neteisybės ir mano kaulai sunykę.'),
  (@b19, 31, 11, 'Aš buvau priekaištas tarp visų savo priešų, bet ypač tarp savo kaimynų, ir baimė savo pažįstamiems; tie, kurie mane matė lauke, bėgo nuo manęs.'),
  (@b19, 31, 12, 'Kaip numirėlis esu pamirštas iš atminties; esu kaip sudužęs indas.'),
  (@b19, 31, 13, 'Nes aš girdėjau daugelio šmeižtą; baimė buvo iš visų pusių; kai jie tarėsi kartu prieš mane, jie sugalvojo atimti man gyvybę.'),
  (@b19, 31, 14, 'Bet aš tavimi, o VIEŠPATIE, pasitikėjau; aš sakiau: „Tu esi mano Dievas“.'),
  (@b19, 31, 15, 'Tavo rankoje yra mano laikai; išvaduok mane iš mano priešų rankos ir iš mano persekiotojų.'),
  (@b19, 31, 16, 'Šviesk savo veidu į savo tarną; išgelbėk mane dėl savo gailestingumų.'),
  (@b19, 31, 17, 'O VIEŠPATIE, tenebūsiu sugėdintas; nes aš tavęs šaukiausi; tebūna sugėdinti nedorėliai ir tenutyla jie kape.'),
  (@b19, 31, 18, 'Tebūna nutildytos meluojančios lūpos, kurios išdidžiai ir paniekinamai kalba sunkius dalykus prieš teisųjį.'),
  (@b19, 31, 19, 'O, koks didis tavo gerumas, kurį atidėjai tiems, kurie tavęs bijo; kurį padarei tiems, kurie pasitiki tavimi žmonių sūnų akivaizdoje!'),
  (@b19, 31, 20, 'Tu paslėpsi juos savo akivaizdos slaptoje vietoje nuo žmogaus išdidumo; juos slaptai saugosi palapinėje nuo liežuvių vaidų.'),
  (@b19, 31, 21, 'Palaimintas tebūna VIEŠPATS; nes jis man parodė savo nuostabų gerumą stipriame mieste.'),
  (@b19, 31, 22, 'Nes aš skubotai pasakiau: „Esu atkirstas nuo tavo akių“; tačiau tu išgirdai mano prašymų balsą, kai šaukiausi tavęs.'),
  (@b19, 31, 23, 'Mylėkite VIEŠPATĮ, visi jo šventieji; nes VIEŠPATS apsaugo ištikimuosius ir gausiai atlygina tam, kuris elgiasi išdidžiai.'),
  (@b19, 31, 24, 'Būkite drąsūs, ir jis sustiprins jūsų širdį, jūs visi, kurie viliatės VIEŠPAČIU.'),
  (@b19, 32, 1, 'Dovydo psalmė. Maskyl. Palaimintas tas, kuriam atleistas nusižengimas, kurio nuodėmė uždengta.'),
  (@b19, 32, 2, 'Palaimintas žmogus, kuriam VIEŠPATS neįskaito neteisybės ir kurio dvasioje nėra apgaulės.'),
  (@b19, 32, 3, 'Kol tylėjau, senėjo mano kaulai, man kaukiant per visą dieną.'),
  (@b19, 32, 4, 'Nes dieną ir naktį sunki buvo ant manęs tavo ranka; mano drėgnumas pavirto į vasaros sausrą. Sela.'),
  (@b19, 32, 5, 'Pripažinau tau savo nuodėmę ir nenuslėpiau savo neteisybės. Tariau: „Aš išpažinsiu savo nusižengimus VIEŠPAČIUI“; ir tu atleidai mano nuodėmės neteisybę. Sela.'),
  (@b19, 32, 6, 'Dėl to kiekvienas dievotasis melsis tau tuo laiku, kai tave galima rasti; tikrai, didelių vandenų potvyniuose jie prie jo nepriartės.'),
  (@b19, 32, 7, 'Tu esi mano slėptuvė; nuo bėdos mane apsaugosi; apsupsi mane išvadavimo giesmėmis. Sela.'),
  (@b19, 32, 8, 'Aš tave pamokysiu ir tave mokysiu kelio, kuriuo turi eiti; vesiu tave savo akimi.'),
  (@b19, 32, 9, 'Nebūk kaip arklys ar kaip mulas, neturintis supratimo; kurių nasrai turi būti sulaikomi žąslais ir apynasriu, kad jie nesiartintų prie tavęs.'),
  (@b19, 32, 10, 'Daug sielvartų bus nedorėliui; bet tas, kuris pasitiki VIEŠPAČIU, bus apsuptas gailestingumo.'),
  (@b19, 32, 11, 'Linksminkitės VIEŠPATYJE ir džiūgaukite, teisieji; ir šaukite iš džiaugsmo, visi tiesiaširdžiai.'),
  (@b19, 33, 1, 'Džiūgaukite VIEŠPATYJE, jūs teisieji, nes tiesiesiems pritinka gyrius.'),
  (@b19, 33, 2, 'Girkite VIEŠPATĮ arfa; giedokite jam psalteriu ir dešimčiastygiu instrumentu.'),
  (@b19, 33, 3, 'Giedokite jam naują giesmę; meistriškai grokite garsiu skambesiu.'),
  (@b19, 33, 4, 'Nes VIEŠPATIES žodis yra teisingas; ir visi jo darbai atlikti tiesoje.'),
  (@b19, 33, 5, 'Jis mėgsta teisumą ir teismą; VIEŠPATIES gerumo yra pilna žemė.'),
  (@b19, 33, 6, 'VIEŠPATIES žodžiu padaryti dangūs; ir jo burnos kvapu – visa jų kariuomenė.'),
  (@b19, 33, 7, 'Jis surenka jūros vandenis kaip krūvą; į sandėlius sudeda gelmes.'),
  (@b19, 33, 8, 'Tebijo VIEŠPATIES visa žemė; pagarbiai jo tebijo visi pasaulio gyventojai.'),
  (@b19, 33, 9, 'Nes jis tarė, ir tai pasidarė; jis įsakė, ir tai tvirtai stovėjo.'),
  (@b19, 33, 10, 'VIEŠPATS paverčia niekais pagonių sumanymą; tautų kėslus padaro bergždžius.'),
  (@b19, 33, 11, 'VIEŠPATIES sumanymas stovi per amžius, jo širdies mintys – kartų kartoms.'),
  (@b19, 33, 12, 'Palaiminta tauta, kurios Dievas yra VIEŠPATS; ir tauta, kurią jis išsirinko savo paveldu.'),
  (@b19, 33, 13, 'Iš dangaus žvelgia VIEŠPATS; jis mato visus žmonių sūnus.'),
  (@b19, 33, 14, 'Iš savo gyvenamos vietos jis žiūri į visus žemės gyventojus.'),
  (@b19, 33, 15, 'Jis suformuoja jų širdis vienodai; jis stebi visus jų darbus.'),
  (@b19, 33, 16, 'Nėra karaliaus, išgelbėto kariuomenės gausybe; galiūnas neišvaduojamas didele jėga.'),
  (@b19, 33, 17, 'Žirgas tuščias dalykas dėl saugumo, ir nei vieno neišgelbės savo didele jėga.'),
  (@b19, 33, 18, 'Štai VIEŠPATIES akis nukreipta į tuos, kurie jo bijo, į tuos, kurie viliasi jo gailestingumu;'),
  (@b19, 33, 19, 'kad išgelbėtų nuo mirties jų sielą ir išlaikytų juos gyvus bado metu.'),
  (@b19, 33, 20, 'Mūsų siela laukia VIEŠPATIES: jis yra mūsų pagalba ir mūsų skydas.'),
  (@b19, 33, 21, 'Nes juo džiaugsis mūsų širdis, kadangi mes pasitikėjome jo šventuoju vardu.'),
  (@b19, 33, 22, 'Tavo gailestingumas, o VIEŠPATIE, tebūna ant mūsų pagal tai, kaip mes viliamės tavimi.'),
  (@b19, 34, 1, 'Dovydo psalmė, kai jis pakeitė savo elgseną Abimelecho akivaizdoje. Tas jį nuvarė, ir jis nuėjo. Laiminsiu VIEŠPATĮ visais laikais; jo gyrius nuolat bus mano burnoje.'),
  (@b19, 34, 2, 'VIEŠPAČIU girsis mano siela; nuolankieji tai išgirs ir linksminsis.'),
  (@b19, 34, 3, 'Aukštinkite VIEŠPATĮ su manimi, kartu iškelkime jo vardą.'),
  (@b19, 34, 4, 'Aš ieškojau VIEŠPATIES, ir jis mane išgirdo, ir išvadavo mane iš visų mano baimių.'),
  (@b19, 34, 5, 'Jie žvelgė į jį ir prašviesėjo; ir jų veidai nebuvo sugėdinti.'),
  (@b19, 34, 6, 'Šis vargšas šaukėsi, ir VIEŠPATS jį išgirdo, ir jį išgelbėjo iš visų jo bėdų.'),
  (@b19, 34, 7, 'VIEŠPATIES angelas stovyklauja aplink tuos, kurie jo bijo, ir juos išvaduoja.'),
  (@b19, 34, 8, 'Ragaukite ir pamatykite, kad VIEŠPATS yra geras; palaimintas žmogus, kuris juo pasitiki.'),
  (@b19, 34, 9, 'Bijokite VIEŠPATIES, jo šventieji; nes nieko nestokoja tie, kurie jo bijo.'),
  (@b19, 34, 10, 'Jauni liūtai pritrūksta ir kenčia badą; bet tie, kurie ieško VIEŠPATIES, nestokos jokio gero dalyko.'),
  (@b19, 34, 11, 'Ateikite, vaikai, klausykite manęs; aš jus mokysiu VIEŠPATIES baimės.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 34, 12, 'Koks yra tas žmogus, kuris trokšta gyvenimo ir mėgsta daug dienų, kad pamatytų gera?'),
  (@b19, 34, 13, 'Sulaikyk savo liežuvį nuo pikto ir savo lūpas nuo klastingų kalbų.'),
  (@b19, 34, 14, 'Šalinkis pikto ir daryk gera; ieškok taikos ir ją vykis.'),
  (@b19, 34, 15, 'VIEŠPATIES akys nukreiptos į teisiuosius ir jo ausys atvertos jų šauksmui.'),
  (@b19, 34, 16, 'VIEŠPATIES veidas prieš darančius pikta, kad iškirstų nuo žemės jų atminimą.'),
  (@b19, 34, 17, 'Teisieji šaukia, ir VIEŠPATS išgirsta ir juos išvaduoja iš visų jų vargų.'),
  (@b19, 34, 18, 'VIEŠPATS yra arti tų, kurių širdis sudužusi; išgelbsti tuos, kurių dvasia palaužta.'),
  (@b19, 34, 19, 'Daug kančių turi teisusis; bet iš jų visų jį išvaduoja VIEŠPATS.'),
  (@b19, 34, 20, 'Jis saugo visus jo kaulus: nei vienas iš jų nesulaužomas.'),
  (@b19, 34, 21, 'Nedorėlį nužudys piktybė; ir tie, kurie nekenčia teisiojo, bus suniokoti.'),
  (@b19, 34, 22, 'VIEŠPATS atperka savo tarnų sielas; ir nebus suniokotas nei vienas, kuris juo pasitiki.'),
  (@b19, 35, 1, 'Dovydo psalmė. O VIEŠPATIE, apgink mano bylą prieš tuos, kurie vaidijasi su manimi; kovok prieš tuos, kurie kovoja prieš mane.'),
  (@b19, 35, 2, 'Nutverk mažąjį bei didįjį skydą ir stokis man padėti.'),
  (@b19, 35, 3, 'Išsitrauk ir ietį, ir užkirsk mane persekiojantiems kelią; tark mano sielai: „Aš esu tavo išgelbėjimas“.'),
  (@b19, 35, 4, 'Tebūna sugluminti ir sugėdinti tie, kurie vaikosi mano sielos; tesigręžia atgal ir tesutrinka tie, kurie sumano man pakenkti.'),
  (@b19, 35, 5, 'Tebūna jie kaip pelai prieš vėją; ir VIEŠPATIES angelas juos tesiveja.'),
  (@b19, 35, 6, 'Jų kelias tebūna tamsus ir slidus; ir VIEŠPATIES angelas juos tepersekioja.'),
  (@b19, 35, 7, 'Nes be priežasties jie man paslėpė savo tinklą duobėje, kurią be priežasties iškasė mano sielai.'),
  (@b19, 35, 8, 'Tegul nelauktai jį užklumpa pražūtis; ir jo tinklas, kurį jis paslėpė, tepagauna jį patį; jis teįpuola į tą pačią pražūtį.'),
  (@b19, 35, 9, 'O mano siela džiūgaus VIEŠPATYJE; ji džiaugsis jo išgelbėjimu.'),
  (@b19, 35, 10, 'Visi mano kaulai sakys: „VIEŠPATIE, kas prilygsta tau, kuris išvaduoji vargšą iš to, kuris yra jam per stiprus, taip, vargšą ir nepasiturintį iš to, kuris jį apiplėšia?“'),
  (@b19, 35, 11, 'Pakilo melagingi liudytojai: jie kaltino mane tuo, ko nežinojau.'),
  (@b19, 35, 12, 'Jie man atlygino piktu už gera, kad apiplėštų mano sielą.'),
  (@b19, 35, 13, 'O kas dėl manęs, jiems sergant ašutinė buvo mano drabužis; žeminau savo sielą pasninku; o mano malda sugrįžo į mano krūtinę.'),
  (@b19, 35, 14, 'Elgiausi, lyg jis būtų mano draugas ar brolis; aš susilenkiau smarkiai, kaip gedintis motinos.'),
  (@b19, 35, 15, 'Bet man esant nelaimėje jie džiūgavo ir susirinko; taip, niekingieji susirinko prieš mane, o aš to nežinojau; jie be paliovos mane draskė;'),
  (@b19, 35, 16, 'veidmainiškais pasityčiojimais puotose jie griežė prieš mane dantimis.'),
  (@b19, 35, 17, 'Viešpatie, kaip ilgai žiūrėsi? Gelbėk mano sielą nuo jų naikinimų, mano brangiausiąją nuo liūtų.'),
  (@b19, 35, 18, 'Aš tau dėkosiu dideliame susirinkime; tarp liaudies gausybės tave girsiu.'),
  (@b19, 35, 19, 'Tenesidžiaugia neteisėtai dėl manęs mano priešai; tenemirkčioja akimis tie, kurie nekenčia manęs be priežasties.'),
  (@b19, 35, 20, 'Nes jie nekalba taikos, bet prieš šalies tyliuosius sugalvoja apgaulingus dalykus.'),
  (@b19, 35, 21, 'Taip, jie plačiai atvėrę prieš mane burną, kalbėjo: „Aha, aha, mūsų akys tai matė“.'),
  (@b19, 35, 22, 'Tu tai matei, o VIEŠPATIE; netylėk; o Viešpatie, nebūk toli nuo manęs.'),
  (@b19, 35, 23, 'Pasižadink ir pabusk mano teismui, būtent mano bylai, mano Dieve ir mano Viešpatie.'),
  (@b19, 35, 24, 'O VIEŠPATIE, mano Dieve, teisk mane pagal savo teisumą; ir jie tenedžiūgauja dėl manęs.'),
  (@b19, 35, 25, 'Tenesako jie savo širdyse: „O! Taip ir norėjome“; tenesako jie: „Mes jį prarijome“.'),
  (@b19, 35, 26, 'Tesusigėsta ir tebūna susigėdę kartu tie, kurie džiaugiasi dėl mano nuoskaudos; gėda ir negarbe tebūna aprengti tie, kurie aukštinasi prieš mane.'),
  (@b19, 35, 27, 'Tešaukia iš džiaugsmo ir tesilinksmina tie, kurie pritaria teisiai mano bylai; taip, tegul jie nuolat sako: „Tebūna išaukštintas VIEŠPATS, kuriam patinka jo tarno klestėjimas“.'),
  (@b19, 35, 28, 'O mano liežuvis kalbės apie tavo teisumą ir apie tavo gyrių visą dieną.'),
  (@b19, 36, 1, 'Vyriausiajam muzikantui. VIEŠPATIES tarno Dovydo psalmė. Nedorėlio nusižengimas sako mano širdies viduje, kad nėra Dievo baimės prieš jo akis.'),
  (@b19, 36, 2, 'Nes jis pataikauja sau savo paties akyse, kol jo neteisybė randama, kad būtų nekenčiama.'),
  (@b19, 36, 3, 'Jo burnos žodžiai – neteisybė ir apgaulė; jis liovėsi būti išmintingas ir daryti gera.'),
  (@b19, 36, 4, 'Piktadarybę jis sumano savo lovoje; jis stovi negerame kelyje; jis nesibjauri piktu.'),
  (@b19, 36, 5, 'O VIEŠPATIE, tavo gailestingumas danguose; ir tavo ištikimybė siekia debesis.'),
  (@b19, 36, 6, 'Tavo teisumas – kaip dideli kalnai; tavo teismai – didžiulės gelmės; o VIEŠPATIE, tu išsaugai žmogų ir gyvulį.'),
  (@b19, 36, 7, 'Koks puikus tavo mylintis gerumas, o Dieve! Todėl žmonių vaikai pasikliauja tavo sparnų šešėlyje.'),
  (@b19, 36, 8, 'Jie bus gausiai pasotinti tavo namų riebumu; ir tu juos pagirdysi iš savo malonumų upės.'),
  (@b19, 36, 9, 'Nes pas tave yra gyvenimo šaltinis; tavo šviesoje mes matysime šviesą.'),
  (@b19, 36, 10, 'Pratęsk savo mylintį gerumą tiems, kurie pažįsta tave; ir savo teisumą tiesiaširdžiams.'),
  (@b19, 36, 11, 'Teneateina prieš mane išdidumo koja, ir nedorėlio ranka tenepašalina manęs.'),
  (@b19, 36, 12, 'Neteisybę darantys kritę; jie parblokšti ir nepajėgs atsikelti.'),
  (@b19, 37, 1, 'Dovydo psalmė. Nesierzink dėl piktadarių nei nepavydėk tiems, kurie daro neteisybę.'),
  (@b19, 37, 2, 'Nes jie greitai bus nupjauti kaip žolė, ir nuvys kaip žaliuojančios žolės.'),
  (@b19, 37, 3, 'Pasitikėk VIEŠPAČIU ir daryk gera; taip gyvensi šalyje ir tikrai būsi pamaitintas.'),
  (@b19, 37, 4, 'Taipogi gėrėkis VIEŠPAČIU; ir jis tau duos tavo širdies troškimus.'),
  (@b19, 37, 5, 'Pavesk VIEŠPAČIUI savo kelią; taipogi pasitikėk juo; ir jis tai įvykdys.'),
  (@b19, 37, 6, 'Ir jis išves tavo teisumą kaip šviesą ir tavo teismą kaip vidudienį.'),
  (@b19, 37, 7, 'Ilsėkis VIEŠPATYJE ir kantriai jo lauk; nesierzink dėl to, kuris klesti savo kelyje, dėl žmogaus, kuris įvykdo nedorus kėslus.'),
  (@b19, 37, 8, 'Liaukis pykęs ir palik rūstybę; jokiu būdu nesierzink, kad nedarytum pikto.'),
  (@b19, 37, 9, 'Nes piktadariai bus iškirsti; bet tie, kurie laukia VIEŠPATIES, paveldės žemę.'),
  (@b19, 37, 10, 'Nes dar trumpai, ir nebeliks nedorėlio; taip, tu atidžiai žiūrėsi į jo vietą, ir jos nebebus.'),
  (@b19, 37, 11, 'Bet romieji paveldės žemę; ir gėrėsis taikos apstumu.'),
  (@b19, 37, 12, 'Nedorėlis rengia teisiajam pikta ir griežia prieš jį dantimis.'),
  (@b19, 37, 13, 'Viešpats juoksis iš jo; nes jis mato, kad ateina jo diena.'),
  (@b19, 37, 14, 'Nedorėliai išsitraukė kalaviją ir įtempė savo lanką, kad pargriautų vargšą ir nepasiturintį ir kad nužudytų tuos, kurie tiesios gyvensenos.'),
  (@b19, 37, 15, 'Jų kalavijas įsmigs į jų pačių širdį, ir jų lankai bus sulaužyti.'),
  (@b19, 37, 16, 'Truputis, kurį turi teisusis, yra geriau negu daugelio nedorėlių turtai.'),
  (@b19, 37, 17, 'Nes nedorėlių rankos bus sulaužytos; bet teisiuosius paremia VIEŠPATS.'),
  (@b19, 37, 18, 'VIEŠPATS žino tiesiųjų dienas; ir jų paveldas bus per amžius.'),
  (@b19, 37, 19, 'Jie nebus sugėdinti piktu laiku; ir bado dienomis bus sotūs.'),
  (@b19, 37, 20, 'Bet pražus nedorėliai, ir VIEŠPATIES priešai bus kaip avių taukai; jie pranyks; jie dūmais pranyks.'),
  (@b19, 37, 21, 'Nedorėliai skolinasi ir negrąžina; bet teisusis parodo gailestingumą ir duoda.'),
  (@b19, 37, 22, 'Nes jo palaimintieji paveldės žemę; o jo prakeiktieji bus iškirsti.'),
  (@b19, 37, 23, 'Gero žmogaus žingsniai yra sutvarkyti VIEŠPATIES; ir jis gėrisi jo keliu.'),
  (@b19, 37, 24, 'Nors jis ir krinta, jis nebus visiškai pargriautas; nes VIEŠPATS palaiko jį savo ranka.'),
  (@b19, 37, 25, 'Buvau jaunas, o dabar esu senas; tačiau nemačiau, kad teisusis būtų paliktas, o jo sėkla elgetautų duonos.'),
  (@b19, 37, 26, 'Jis visuomet gailestingas ir skolina; ir jo sėkla yra palaiminta.'),
  (@b19, 37, 27, 'Traukis nuo pikto ir daryk gera; ir gyvenk per amžius.'),
  (@b19, 37, 28, 'Nes VIEŠPATS myli teismą ir nepalieka savo šventųjų; jie išsaugoti per amžius; bet nedorėlių sėkla bus iškirsta.'),
  (@b19, 37, 29, 'Teisieji paveldės šalį ir gyvens joje amžinai.'),
  (@b19, 37, 30, 'Teisiojo burna kalba išmintį, ir jo liežuvis kalba apie teismą.'),
  (@b19, 37, 31, 'Jo Dievo įstatymas yra jo širdyje; nei vienas jo žingsnis nepaslys.'),
  (@b19, 37, 32, 'Nedorėlis stebi teisųjį ir siekia jį užmušti.'),
  (@b19, 37, 33, 'VIEŠPATS jo nepaliks ano rankoje ir jo nepasmerks, kai jis bus teisiamas.'),
  (@b19, 37, 34, 'Lauk VIEŠPATIES ir laikykis jo kelio, ir jis tave išaukštins, kad paveldėtum šalį; tu pamatysi, kai nedorėliai bus iškirsti.'),
  (@b19, 37, 35, 'Mačiau nedorėlį didžiulėje galioje ir išsiplėtusį kaip žaliuojantį lauro medį.'),
  (@b19, 37, 36, 'Tačiau jis praėjo, ir štai jo nebuvo; taip, jo ieškojau, bet nebuvo galima jo rasti.'),
  (@b19, 37, 37, 'Stebėk tobuląjį ir žiūrėk į tiesųjį; nes tokių galas – ramybė.'),
  (@b19, 37, 38, 'Bet nusižengėliai kartu bus sunaikinti; nedorėlių galas bus iškirstas.'),
  (@b19, 37, 39, 'Bet teisiųjų išgelbėjimas yra iš VIEŠPATIES; jis yra jų stiprybė bėdos metu.'),
  (@b19, 37, 40, 'Ir VIEŠPATS jiems padės, ir juos išvaduos; jis juos išvaduos iš nedorėlių ir juos išgelbės, nes jie pasitiki juo.'),
  (@b19, 38, 1, 'Dovydo psalmė. Priminimui. O VIEŠPATIE, nebark manęs savo rūstybėje; ir nebausk manęs savo karštame nepasitenkinime.'),
  (@b19, 38, 2, 'Nes tavo strėlės tvirtai įsmigo į mane ir tavo ranka stipriai slegia mane.'),
  (@b19, 38, 3, 'Nėra nieko sveiko mano kūne dėl tavo pykčio; nėra jokio poilsio mano kauluose dėl mano nuodėmės.'),
  (@b19, 38, 4, 'Nes mano neteisybės iškilo virš mano galvos; kaip sunki našta jos man yra per sunkios.'),
  (@b19, 38, 5, 'Dvokia ir pūna mano žaizdos dėl mano kvailumo.'),
  (@b19, 38, 6, 'Aš sunerimęs; aš labai sulinkęs; vaikštau liūdėdamas visą dieną.'),
  (@b19, 38, 7, 'Nes mano strėnos pilnos bjaurios ligos; ir nėra nieko sveiko mano kūne.'),
  (@b19, 38, 8, 'Esu nusilpęs ir labai sulaužytas; kaukiau dėl savo širdies nerimo.'),
  (@b19, 38, 9, 'Viešpatie, visas mano troškimas yra tavo akivaizdoje; ir mano dejavimas nėra paslėptas nuo tavęs.'),
  (@b19, 38, 10, 'Mano širdis smarkiai plaka, mane palieka mano jėgos; o mano akių šviesa – ji irgi paliko mane.'),
  (@b19, 38, 11, 'Mano mylėtojai ir mano draugai stovi atsitolinę nuo mano žaizdos; ir mano giminaičiai stovi iš tolo.'),
  (@b19, 38, 12, 'Taipogi tie, kurie ieško mano gyvybės, spendžia man žabangas; kurie siekia man pakenkti, kalba piktus dalykus ir visą dieną galvoja apgaules.'),
  (@b19, 38, 13, 'Bet aš kaip kurčias, negirdėjau; ir buvau kaip nebylys, kuris neatveria savo burnos.'),
  (@b19, 38, 14, 'Taip aš buvau kaip žmogus, kuris negirdi ir kurio burnoje nėra pabarimų.'),
  (@b19, 38, 15, 'Nes tavimi, o VIEŠPATIE, aš viliuosi; tu išgirsi, o Viešpatie, mano Dieve.'),
  (@b19, 38, 16, 'Nes aš sakiau: „Išgirsk mane, kad jie nedžiūgautų dėl manęs; kad, mano kojai paslydus, jie nesiaukštintų prieš mane“.'),
  (@b19, 38, 17, 'Nes aš esu pasiruošęs šlubuoti, ir mano sielvartas nuolat yra mano akivaizdoje.'),
  (@b19, 38, 18, 'Nes aš pripažinsiu savo neteisybę; aš apgailestausiu dėl savo nuodėmės.'),
  (@b19, 38, 19, 'Bet mano priešai gyvibingi, ir jie stiprūs; ir padaugėjo tų, kurie neteisėtai manęs nekenčia.'),
  (@b19, 38, 20, 'Taip pat tie, kurie atlygina piktu už gera, yra mano priešininkai; kadangi aš seku tuo, kas gera.'),
  (@b19, 38, 21, 'Nepalik manęs, o VIEŠPATIE; o mano Dieve, nebūk toli nuo manęs.'),
  (@b19, 38, 22, 'Skubėk padėti man, o Viešpatie, mano išgelbėjime.'),
  (@b19, 39, 1, 'Vyriausiajam muzikantui Jedutūnui. Dovydo psalmė. Aš sakiau: „Žiūrėsiu savo kelius, kad nenusidėčiau savo liežuviu; saugosiu savo burną apynasriu, kol nedorėlis mano akivaizdoje“.'),
  (@b19, 39, 2, 'Buvau nebylus tylėjimu, tylėjau netgi apie gera; mano sielvartas sujudo.'),
  (@b19, 39, 3, 'Įkaito širdis mano viduje, man bemąstant užsidegė ugnis; tada prabilau liežuviu:'),
  (@b19, 39, 4, '„Duok man, VIEŠPATIE, sužinoti mano galą ir mano dienų saiką – koks jis; kad žinočiau, koks aš trapus.'),
  (@b19, 39, 5, 'Štai tu padarei mano dienas plaštakos pločio; ir mano amžius yra kaip niekas tavo akivaizdoje; tikrai kiekvienas žmogus savo geriausioje būklėje yra visiška tuštybė. Sela.'),
  (@b19, 39, 6, 'Tikrai kiekvienas žmogus vaikšto kaip tuščias vaizdinys; tikrai jie veltui nerimauja; jis krauna turtus ir nežino, kas juos susirinks.'),
  (@b19, 39, 7, 'O dabar, Viešpatie, ko aš laukiu? Mano viltis yra tavyje.'),
  (@b19, 39, 8, 'Išvaduok mane iš visų mano nusižengimų; nepadaryk manęs kvailojo priekaištu.'),
  (@b19, 39, 9, 'Buvau nebylys, neatvėriau burnos; nes tu tai padarei.'),
  (@b19, 39, 10, 'Atitrauk nuo manęs savo kirtį; nuo tavo rankos smūgio aš nykstu.'),
  (@b19, 39, 11, 'Kai pabarimais pataisai žmogų už neteisybę, tu padarai, kad jo grožis išnyktų kaip kandis; tikrai kiekvienas žmogus yra tuštybė. Sela.'),
  (@b19, 39, 12, 'Išgirsk mano maldą, o VIEŠPATIE, ir pasuk ausį į mano šauksmą; netylėk dėl mano ašarų; nes aš esu ateivis pas tave ir laikinai apsigyvenęs, kaip visi mano tėvai buvo.'),
  (@b19, 39, 13, 'Pagailėk manęs, kad atnaujinčiau jėgas prieš tai, kai ten išeisiu ir nebebūsiu.'),
  (@b19, 40, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Kantriai laukiau VIEŠPATIES; ir jis pasilenkė prie manęs, ir išgirdo mano šauksmą.'),
  (@b19, 40, 2, 'Taip pat jis ištraukė mane iš baisios duobės, iš klampaus dumblo, ir pastatė ant uolos mano kojas, ir sutvirtino mano žingsnius.'),
  (@b19, 40, 3, 'Ir jis įdėjo man į burną naują giesmę – gyrių mūsų Dievui. Daugelis tai matys ir bijosis, ir pasitikės VIEŠPAČIU.'),
  (@b19, 40, 4, 'Palaimintas tas žmogus, kuris daro VIEŠPATĮ savo pasitikėjimu ir nepaiso išdidžiųjų nei tų, kurie nukrypsta į melus.'),
  (@b19, 40, 5, 'Daug, o VIEŠPATIE, mano Dieve, yra padarytų tavo nuostabių darbų ir tavo minčių į mus; paeiliui tau jų nesuskaičiuosi; jei norėčiau juos paskelbti ir išpasakoti, jų yra daugiau, negu galima suskaičiuoti.'),
  (@b19, 40, 6, 'Aukos ir atnašos tu nenorėjai; mano ausis atvėrei; deginamosios atnašos ir nuodėmės atnašos tu nereikalavai.'),
  (@b19, 40, 7, 'Tada aš tariau: „Štai ateinu; knygos ritinyje apie mane parašyta.'),
  (@b19, 40, 8, 'Man pasigėrėjimas vykdyti tavo valią, o mano Dieve; taip, tavo įstatymas yra mano širdies viduje“.'),
  (@b19, 40, 9, 'Skelbiau teisumą dideliame susirinkime; štai savo lūpų nesulaikiau, o VIEŠPATIE, tu žinai.'),
  (@b19, 40, 10, 'Tavo teisumo nepaslėpiau savo širdies viduje; skelbiau tavo ištikimybę ir tavo išgelbėjimą; nenuslėpiau tavo mylinčio gerumo ir tavo tiesos nuo didelio susirinkimo.'),
  (@b19, 40, 11, 'O VIEŠPATIE, nesulaikyk nuo manęs savo švelnių gailestingumų; tavo mylintis gerumas ir tavo tiesa nuolat tesaugo mane.'),
  (@b19, 40, 12, 'Nes mane apsupo nesuskaičiuojamos piktybės; mano neteisybės nutvėrė mane taip, kad neįstengiu žiūrėti aukštyn; jų yra daugiau nei mano galvos plaukų; todėl mano širdis mane apvylė.'),
  (@b19, 40, 13, 'Teikis, o VIEŠPATIE, išvaduoti mane; o VIEŠPATIE, skubėk man padėti.'),
  (@b19, 40, 14, 'Tesusigėsta ir tebūna suglumę drauge tie, kurie vaikosi mano sielos, kad ją sunaikintų; tebūna nuvyti atgalios ir sugėdinti tie, kurie linki man pikto.'),
  (@b19, 40, 15, 'Tebūna jie suniokoti atlygiui už savo gėdą, kurie man sako: „Aha, aha“.'),
  (@b19, 40, 16, 'Tedžiūgauja visi, kurie tavęs ieško, ir tesilinksmina tavyje; mylintys tavo išgelbėjimą nuolat tesako: „Tebūna išaukštintas VIEŠPATS“.'),
  (@b19, 40, 17, 'Bet aš vargšas ir nepasiturintis; tačiau Viešpats galvoja apie mane; tu esi mano pagalba ir mano išvaduotojas; o mano Dieve, nedelsk.'),
  (@b19, 41, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Palaimintas tas, kuris atsižvelgia į vargšą; bėdos metu VIEŠPATS jį išvaduos.'),
  (@b19, 41, 2, 'VIEŠPATS jį apsaugos ir išlaikys gyvą; jis bus palaimintas žemėje; ir tu jo neatiduosi į jo priešų valią.'),
  (@b19, 41, 3, 'VIEŠPATS jį sustiprins silpnumo patale; jam sergant tu pakeisi visą jo patalą.'),
  (@b19, 41, 4, 'Aš sakiau: „VIEŠPATIE, būk man gailestingas; išgydyk mano sielą; nes aš nusidėjau prieš tave“.'),
  (@b19, 41, 5, 'Mano priešai kalba pikta apie mane: „Kada jis mirs ir jo vardas pražus?“'),
  (@b19, 41, 6, 'Ir jei jis ateina manęs aplankyti, kalba tuštybę; jo širdis kaupia savyje neteisybę; išėjęs laukan jis tai išpasakoja.'),
  (@b19, 41, 7, 'Šnibždasi prieš mane visi, kurie manęs nekenčia; prieš mane jie galvoja man pakenkti.'),
  (@b19, 41, 8, 'Jie sako: „Pikta liga stipriai prie jo prilipo; o dabar, kadangi jis guli, jis daugiau nebeatsikels“.'),
  (@b19, 41, 9, 'Taip, mano paties artimas draugas, kuriuo pasitikėjau, kuris valgė mano duonos, pakėlė kulną prieš mane.'),
  (@b19, 41, 10, 'Bet tu, o VIEŠPATIE, būk man gailestingas ir pakelk mane, kad jiems atlyginčiau.'),
  (@b19, 41, 11, 'Iš to žinosiu, kad esi man palankus, nes mano priešas netriumfuos prieš mane.'),
  (@b19, 41, 12, 'O mane tu palaikai mano dorume ir amžiams mane pastatai prieš savo veidą.'),
  (@b19, 41, 13, 'Tebūna palaimintas VIEŠPATS, Izraelio Dievas, nuo amžių ir iki amžių. Amen ir amen.'),
  (@b19, 42, 1, 'Vyriausiajam muzikantui. Maskylas Koracho sūnums. Kaip elnė trokšta vandens upelių, taip mano siela trokšta tavęs, o Dieve.'),
  (@b19, 42, 2, 'Mano siela ištroškusi Dievo, gyvojo Dievo: kada aš ateisiu ir pasirodysiu Dievo akivaizdoje?'),
  (@b19, 42, 3, 'Mano ašaros buvo mano valgis dieną ir naktį, kai jie nuolat man sakė: „Kur yra tavo Dievas?“'),
  (@b19, 42, 4, 'Kai šituos dalykus prisimenu, išlieju savyje savo sielą: nes aš eidavau su daugybe, eidavau su jais į Dievo namus džiaugsmo ir gyriaus balsu, su daugybe, kurie šventė šventadienį.'),
  (@b19, 42, 5, 'Kodėl esi prislėgta, o mano siela, ir kodėl nerimauji manyje? Vilkis Dievu; nes aš jį dar girsiu už jo veido pagalbą.'),
  (@b19, 42, 6, 'O mano Dieve, mano siela prislėgta mano viduje; todėl prisiminsiu tave iš Jordano šalies ir iš hermonitų, nuo Micaro kalvos.'),
  (@b19, 42, 7, 'Gelmės šaukiasi gelmes, triukšmaujant tavo vandens viesului; visos tavo bangos ir tavo vilnys praėjo virš manęs.'),
  (@b19, 42, 8, 'Tačiau dienos metu VIEŠPATS įsakys savo mylinčiam gerumui, ir naktį jo giesmė bus su manimi, mano malda mano gyvybės Dievui.'),
  (@b19, 42, 9, 'Sakysiu Dievui, savo uolai: „Kodėl mane pamiršai? Kodėl vaikštau gedėdamas dėl priešo engimo?“'),
  (@b19, 42, 10, 'Kaip kalaviju mano kauluose man priekaištauja mano priešai, kasdien man sakydami: „Kur yra tavo Dievas?“'),
  (@b19, 42, 11, 'Kodėl esi prislėgta, o mano siela, ir kodėl nerimauji mano viduje? Vilkis Dievu; nes aš dar girsiu jį, kuris yra mano veido sveikata ir mano Dievas.'),
  (@b19, 43, 1, 'Teisk mane, o Dieve, ir gink mano bylą prieš bedievę tautą; išvaduok mane nuo apgaulingo ir neteisingo žmogaus.'),
  (@b19, 43, 2, 'Nes tu esi mano stiprybės Dievas; kodėl mane atstumi? Kodėl vaikštau gedėdamas dėl priešo engimo?'),
  (@b19, 43, 3, 'Išsiųsk savo šviesą ir savo tiesą, tegul jos veda mane; tegul jos mane nuveda į tavo šventąją kalvą ir į tavo padangtes.'),
  (@b19, 43, 4, 'Tada eisiu prie Dievo aukuro, pas Dievą, mano beribį džiaugsmą; taip, girsiu tave arfa, o Dieve, mano Dieve.'),
  (@b19, 43, 5, 'Kodėl esi prislėgta, o mano siela, ir kodėl nerimauji mano viduje? Vilkis Dievu; nes aš dar girsiu jį, kuris yra mano veido sveikata ir mano Dievas.'),
  (@b19, 44, 1, 'Vyriausiajam muzikantui. Koracho sūnums, Maskylas. O Dieve, savo ausimis girdėjome, mūsų tėvai pasakojo mums, kokį darbą atlikai jų dienomis, senovės laikais.'),
  (@b19, 44, 2, 'Kaip tu savo ranka išvarei pagonis ir juos įsodinai; kaip tu kamavai tautas ir jas išvarei.'),
  (@b19, 44, 3, 'Nes ne savo kalaviju jie gavo nuosavybėn šalį, ir ne jų ranka juos išgelbėjo; bet tavo dešinė ir tavo ranka, ir tavo veido šviesa, nes tu jiems buvai palankus.'),
  (@b19, 44, 4, 'Tu esi mano Karalius, o Dieve; įsakyk išvadavimus Jokūbui.'),
  (@b19, 44, 5, 'Per tave mes nublokšime savo priešus; per tavo vardą mes paminsime tuos, kurie kyla prieš mus.'),
  (@b19, 44, 6, 'Nes ne savo lanku pasitikėsiu, ir ne mano kalavijas mane išgelbės.'),
  (@b19, 44, 7, 'Bet tu mus išgelbėjai nuo mūsų priešų ir tuos, kurie mūsų nekenčia, sugėdinai.'),
  (@b19, 44, 8, 'Dievu giriamės per visą dieną ir tavo vardą girsime per amžius. Sela.'),
  (@b19, 44, 9, 'Bet tu mus atstūmei ir mus sugėdinai; ir neišeini su mūsų kariuomenėmis.'),
  (@b19, 44, 10, 'Tu priverti mus nusigręžti nuo priešo; ir tie, kurie mūsų nekenčia, prisigrobia sau.'),
  (@b19, 44, 11, 'Tu davei mus kaip maistui skirtas avis; ir išsklaidei mus tarp pagonių.'),
  (@b19, 44, 12, 'Tu parduodi savo tautą už nieką ir nuo jų vertės nepraturtėji.'),
  (@b19, 44, 13, 'Tu padarai mus priekaištu mūsų kaimynams, panieka ir pajuoka tiems, kurie yra aplink mus.'),
  (@b19, 44, 14, 'Tu padarai mus priežodžiu tarp pagonių, galvos kratymu tarp tautų.'),
  (@b19, 44, 15, 'Nuolatos prieš mane yra mano negarbė, ir mano veido gėda apdengė mane'),
  (@b19, 44, 16, 'dėl priekaištautojo ir piktžodžiautojo balso; dėl priešo ir keršytojo.'),
  (@b19, 44, 17, 'Visa tai užėjo ant mūsų; tačiau tavęs nepamiršome ir nesielgėme apgaulingai tavo sandoroje.'),
  (@b19, 44, 18, 'Mūsų širdis neatsitraukė, ir mūsų žingsniai nenukrypo nuo tavo kelio;'),
  (@b19, 44, 19, 'nors tu mus smarkiai sudaužei slibinų vietoje ir mus apdengei mirties šešėliu.'),
  (@b19, 44, 20, 'Jei esame pamiršę mūsų Dievo vardą ar ištiesę savo rankas į svetimą dievą;'),
  (@b19, 44, 21, 'argi Dievas to nesuieškos? Nes jis žino širdies paslaptis.'),
  (@b19, 44, 22, 'Taip, dėl tavęs esame žudomi visą dieną; mes laikomi pjautinomis avimis.'),
  (@b19, 44, 23, 'Atsibusk, kodėl miegi, o Viešpatie? Kelkis, neatstumk mūsų amžinai.'),
  (@b19, 44, 24, 'Kodėl slepi savo veidą ir pamiršti mūsų sielvartą bei mūsų priespaudą?'),
  (@b19, 44, 25, 'Nes į dulkes yra nulinkusi mūsų siela; mūsų pilvas prilipęs prie žemės.'),
  (@b19, 44, 26, 'Pakilk mums į pagalbą ir atpirk mus dėl savo gailestingumų.'),
  (@b19, 45, 1, 'Vyriausiajam muzikantui, Šošanimu. Koracho sūnums. Maskylas. Meilių giesmė. Mano širdis išreiškia puikų dalyką: kalbu apie tai, ką padariau dėl karaliaus; mano liežuvis yra pasiruošusio raštininko plunksna.'),
  (@b19, 45, 2, 'Tu esi gražesnis už žmonių vaikus; malonė išlieta į tavo lūpas; todėl Dievas tave palaimino amžiams.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 45, 3, 'Prisijuosk savo kalaviją prie šlaunies, o galingiausiasis, savo šlove ir savo didybe.'),
  (@b19, 45, 4, 'Ir lėk savo didybėje sėkmingai dėl tiesos, romumo ir teisumo; ir tavo dešinė mokys tave baisių dalykų.'),
  (@b19, 45, 5, 'Aštrios tavo strėlės karaliaus priešų širdyse, nuo jų tautos krinta po tavimi.'),
  (@b19, 45, 6, 'Tavo sostas, o Dieve, yra per amžių amžius; tavo karalystės skeptras – teisingas skeptras.'),
  (@b19, 45, 7, 'Tu myli teisumą ir nekenti nedorybės; todėl Dievas, tavo Dievas, tave patepė džiaugsmo aliejumi daugiau už tavo bendrus.'),
  (@b19, 45, 8, 'Visi tavo drabužiai kvepia mira, alaviju ir kasija iš dramblio kaulo rūmų, kuriais jie linksmino tave.'),
  (@b19, 45, 9, 'Karalių dukterys tarp tavo garbingų moterų; tavo dešinėje stovėjo karalienė, pasipuošusi Ofyro auksu.'),
  (@b19, 45, 10, 'Klausyk, o dukra, apgalvok ir palenk savo ausį; taip pat pamiršk savo tautą ir savo tėvo namus;'),
  (@b19, 45, 11, 'taip karalius didžiai trokš tavo grožio; nes jis yra tavo Viešpats; ir garbink jį.'),
  (@b19, 45, 12, 'Tyro dukra ten bus su dovana; liaudies turtingieji maldaus tavo palankumo.'),
  (@b19, 45, 13, 'Karaliaus dukra visa šlovinga viduje; jos apdarai apdirbto aukso.'),
  (@b19, 45, 14, 'Ji bus atvesta pas karalių išsiuvinėtais drabužiais; paskui ją einančios mergelės, jos draugės, bus atvestos pas tave.'),
  (@b19, 45, 15, 'Jos bus atvestos su linksmybe ir džiūgavimu; jos įeis į karaliaus rūmus.'),
  (@b19, 45, 16, 'Vietoj tavo tėvų bus tavo vaikai, kuriuos tu galėsi paskirti kunigaikščiais visoje žemėje.'),
  (@b19, 45, 17, 'Aš padarysiu, kad tavo vardą atsimintų per visas kartas; todėl liaudis tave girs per amžių amžius.'),
  (@b19, 46, 1, 'Vyriausiajam muzikantui. Koracho sūnums. Giesmė alamotu. Dievas yra mūsų prieglobstis ir stiprybė, labai artima pagalba bėdoje.'),
  (@b19, 46, 2, 'Todėl mes nebijosime, nors žemė pasitrauktų, ir nors kalnai būtų nunešti į jūros vidurį;'),
  (@b19, 46, 3, 'nors ūžtų ir drumstųsi jos vandenys, nors ir drebėtų kalnai jai banguojant. Sela.'),
  (@b19, 46, 4, 'Štai upė, jos srovės džiugins Dievo miestą, Aukščiausiojo padangčių šventąją vietą.'),
  (@b19, 46, 5, 'Dievas yra jo viduje: jis nesvyruos; Dievas jam padės, ir tai pačiame ankstume.'),
  (@b19, 46, 6, 'Siautė pagonys, svyravo karalystės; jis ištarė savo balsą – ištirpo žemė.'),
  (@b19, 46, 7, 'Kariuomenių VIEŠPATS yra su mumis; Jokūbo Dievas yra mūsų prieglobstis. Sela.'),
  (@b19, 46, 8, 'Ateikite, pažvelkite į VIEŠPATIES darbus, kokių suniokojimų jis padarė žemėje.'),
  (@b19, 46, 9, 'Jis sustabdo karus ligi žemės krašto; jis sulaužo lanką ir perkerta ietį; jis vežimą sudegina ugnyje.'),
  (@b19, 46, 10, '„Nurimkite ir žinokite, kad aš esu Dievas; aš būsiu išaukštintas tarp pagonių, būsiu išaukštintas žemėje“.'),
  (@b19, 46, 11, 'Kariuomenių VIEŠPATS yra su mumis; Jokūbo Dievas yra mūsų prieglobstis. Sela.'),
  (@b19, 47, 1, 'Vyriausiajam muzikantui. Psalmė Koracho sūnums. Visos tautos, plokite rankomis; šaukite Dievui triumfo balsu.'),
  (@b19, 47, 2, 'Nes aukščiausiasis VIEŠPATS yra baisus, jis yra didis visos žemės Karalius.'),
  (@b19, 47, 3, 'Jis pajungs mums tautas ir tautybes po mūsų kojomis.'),
  (@b19, 47, 4, 'Jis mums išrinks mūsų paveldą – puikumą Jokūbo, kurį jis pamilo. Sela.'),
  (@b19, 47, 5, 'Dievas užžengė su šauksmu, VIEŠPATS – trimito gaudimu.'),
  (@b19, 47, 6, 'Giedokite gyrių Dievui, giedokite gyrių; giedokite gyrių mūsų Karaliui, giedokite gyrių.'),
  (@b19, 47, 7, 'Nes Dievas yra visos žemės Karalius; giedokite gyrių su supratimu.'),
  (@b19, 47, 8, 'Dievas karaliauja pagonims; Dievas sėdi savo šventumo soste.'),
  (@b19, 47, 9, 'Tautos kunigaikščiai yra susirinkę – Abraomo Dievo tauta; nes Dievui priklauso žemės skydai; jis labai išaukštintas.'),
  (@b19, 48, 1, 'Giesmė ir psalmė Koracho sūnums. Didis yra VIEŠPATS ir labai girtinas turi būti mūsų Dievo mieste, jo šventumo kalne.'),
  (@b19, 48, 2, 'Gražus išsidėstymu, visos žemės džiaugsmas yra Siono kalnas šiaurės šonuose, didžiojo Karaliaus miestas.'),
  (@b19, 48, 3, 'Jo rūmuose Dievas žinomas kaip prieglobstis.'),
  (@b19, 48, 4, 'Nes štai karaliai susirinkę, jie praėjo drauge.'),
  (@b19, 48, 5, 'Jie tai pamatė ir taip stebėjosi; jie sunerimo ir išskubėjo.'),
  (@b19, 48, 6, 'Baimė juos ten apėmė ir skausmai kaip gimdančią moterį.'),
  (@b19, 48, 7, 'Rytų vėju tu sudaužai Taršišo laivus.'),
  (@b19, 48, 8, 'Kaip buvome girdėję, taip ir pamatėme kariuomenių VIEŠPATIES mieste, mūsų Dievo mieste: Dievas jį įtvirtins per amžius. Sela.'),
  (@b19, 48, 9, 'Mes mąstėme, o Dieve, apie tavo mylintį gerumą tavo šventyklos viduje.'),
  (@b19, 48, 10, 'Kaip tavo vardas, o Dieve, taip ir tavo gyrius iki žemės pakraščių; tavo dešinė pilna teisumo.'),
  (@b19, 48, 11, 'Tedžiūgauja Siono kalnas, tebūna linksmos Judos dukterys dėl tavo teismų.'),
  (@b19, 48, 12, 'Vaikščiokite aplink Sioną, apeikite aplink jį; skaičiuokite jo bokštus.'),
  (@b19, 48, 13, 'Gerai įsidėmėkite jo pylimus, apžiūrėkite jo rūmus; kad galėtumėte papasakoti būsimai kartai.'),
  (@b19, 48, 14, 'Nes šis Dievas yra mūsų Dievas per amžių amžius; jis bus mūsų vedlys iki mirties.'),
  (@b19, 49, 1, 'Vyriausiajam muzikantui. Psalmė Koracho sūnums. Girdėkite tai, visos tautos; palenkite ausį, visi pasaulio gyventojai;'),
  (@b19, 49, 2, 'tiek žemieji, tiek ir aukštieji, tiek turtingieji, tiek ir beturčiai kartu.'),
  (@b19, 49, 3, 'Mano burna kalbės apie išmintį; ir mano širdies apmąstymai bus apie supratimą.'),
  (@b19, 49, 4, 'Aš palenksiu savo ausį palyginimui; atversiu su arfa savo paslaptingą pasakymą.'),
  (@b19, 49, 5, 'Kodėl turėčiau bijoti pikto dienomis, kai mane apsupa mano kulnų neteisybė?'),
  (@b19, 49, 6, 'Tie, kurie pasitiki savo turtu ir giriasi savo turtų daugybe,'),
  (@b19, 49, 7, 'nei vienas iš jų jokiu būdu negali atpirkti savo brolio nei duoti Dievui išpirkos už jį'),
  (@b19, 49, 8, '(nes brangus jų sielos išpirkimas, ir jo neliks per amžius),'),
  (@b19, 49, 9, 'idant jis galėtų dar amžinai gyventi ir nematyti sugedimo.'),
  (@b19, 49, 10, 'Nes jis mato, kad išminčiai miršta, kvailiai bei neprotingi taip pat pražūna ir palieka savo turtą kitiems.'),
  (@b19, 49, 11, 'Tai jų vidinės mintys, kad jų namai pasiliks per amžius, ir jų gyvenamos vietos per kartų kartas; savo žemes jie vadina savo vardais.'),
  (@b19, 49, 12, 'Tačiau žmogus, būdamas garbėje, neišlieka; jis yra kaip gyvuliai, kurie pražūna.'),
  (@b19, 49, 13, 'Šitas jų kelias yra jų kvailystė; tačiau jų palikuonys pritaria jų pasakymams. Sela.'),
  (@b19, 49, 14, 'Kaip avys jie suguldyti kape, mirtis jais maitinsis; ir tiesieji jiems viešpataus ryte; ir jų grožis sudūlės kape iš jų buveinės.'),
  (@b19, 49, 15, 'Bet Dievas išpirks mano sielą iš kapo valdžios; nes jis priims mane. Sela.'),
  (@b19, 49, 16, 'Nebijok, kai kas nors praturtėja, kai jo namų šlovė pagausėja;'),
  (@b19, 49, 17, 'nes mirdamas jis nieko neišsineš; jo šlovė paskui jį nenusileis.'),
  (@b19, 49, 18, 'Nors gyvendamas jis laimino savo sielą; ir žmonės tave girs, kai tu sau darysi gera.'),
  (@b19, 49, 19, 'Jis nueis pas savo tėvų kartą; jie niekada neregės šviesos.'),
  (@b19, 49, 20, 'Žmogus, kuris yra gerbiamas, bet neturi supratimo, yra kaip gyvuliai, kurie pražūna.'),
  (@b19, 50, 1, 'Asafo psalmė. Galingasis Dievas, tai yra VIEŠPATS, kalbėjo ir šaukė žemę nuo saulės patekėjimo iki jos nusileidimo.'),
  (@b19, 50, 2, 'Iš Siono, grožio tobulumo, Dievas spindėjo.'),
  (@b19, 50, 3, 'Mūsų Dievas ateis ir netylės; ugnis rys pirma jo, ir bus labai šėlstanti aplink jį.'),
  (@b19, 50, 4, 'Jis sušuks dangums iš viršaus ir žemei, kad teistų savo tautą.'),
  (@b19, 50, 5, '„Surinkite man mano šventuosius; tuos, kurie per auką sudarė su manimi sandorą“.'),
  (@b19, 50, 6, 'Ir dangūs paskelbs jo teisumą; nes pats Dievas yra teisėjas. Sela.'),
  (@b19, 50, 7, '„Išgirsk, o mano tauta, ir aš kalbėsiu; o Izraeli, ir aš liudysiu prieš tave; aš esu Dievas – tavo Dievas.'),
  (@b19, 50, 8, 'Nebarsiu tavęs dėl tavo aukų ar dėl tavo deginamųjų atnašų, nuolat turėjusių būti mano akivaizdoje.'),
  (@b19, 50, 9, 'Aš neimsiu jaučio iš tavo namų nei ožių iš tavo aptvarų.'),
  (@b19, 50, 10, 'Nes kiekvienas miško žvėris yra mano ir galvijai ant tūkstančio kalvų.'),
  (@b19, 50, 11, 'Aš pažįstu visus kalnų skrajūnus; ir laukiniai lauko žvėrys yra mano.'),
  (@b19, 50, 12, 'Jei būčiau alkanas, tau nesakyčiau; nes mano yra pasaulis ir jo pilnumas.'),
  (@b19, 50, 13, 'Argi aš valgysiu jaučių mėsą, ar gersiu ožių kraują?'),
  (@b19, 50, 14, 'Atnašauk Dievui padėką; ir ištesėk Aukščiausiajam savo įžadus;'),
  (@b19, 50, 15, 'ir šaukis manęs bėdos dieną; aš tave išvaduosiu, ir tu mane šlovinsi“.'),
  (@b19, 50, 16, 'Bet nedorėliui Dievas sako: „Kas tau darbo, kad skelbtum mano įstatus ar kad imtum mano sandorą į savo burną,'),
  (@b19, 50, 17, 'kadangi tu nekenti pamokymo ir numeti už savęs mano žodžius?'),
  (@b19, 50, 18, 'Pamatęs vagį jam pritarei ir buvai dalininkas su svetimautojais.'),
  (@b19, 50, 19, 'Savo burną duodi piktam, ir tavo liežuvis kuria apgaulę.'),
  (@b19, 50, 20, 'Sėdi ir kalbi prieš savo brolį; apšmeiži savo motinos sūnų.'),
  (@b19, 50, 21, 'Tu tuos dalykus darei, o aš tylėjau; tu manei, kad aš esu visiškai toks, kaip tu; bet aš tave barsiu ir juos išdėstysiu tau prieš akis.'),
  (@b19, 50, 22, 'Na, apsvarstykite tai jūs, kurie pamirštate Dievą, kad jūsų nesudraskyčiau, ir nebūtų kas išvaduoja.'),
  (@b19, 50, 23, 'Kas atnašauja gyrių, šlovina mane; ir kas teisingai sutvarko savo elgesį, tam parodysiu Dievo išgelbėjimą“.'),
  (@b19, 51, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Pranašui Natanui atėjus pas jį po to, kai tas buvo įėjęs pas Bat-Šebą. Pasigailėk manęs, o Dieve, pagal savo mylintį gerumą; pagal savo švelnių gailestingumų gausybę išdildyk mano nusižengimus.'),
  (@b19, 51, 2, 'Visai nuplauk mane nuo mano neteisybės ir apvalyk mane nuo mano nuodėmės.'),
  (@b19, 51, 3, 'Nes aš pripažįstu savo nusižengimus; ir mano nuodėmė yra nuolat mano priešakyje.'),
  (@b19, 51, 4, 'Prieš tave, prieš tave vienintelį nusidėjau ir padariau tą pikta tavo akyse; kad būtum išteisintas, kai kalbi, ir būtum švarus, kai teisi.'),
  (@b19, 51, 5, 'Štai buvau padarytas neteisybėje; ir nuodėmėje mane pradėjo mano motina.'),
  (@b19, 51, 6, 'Štai tu trokšti tiesos viduje; ir vidaus slaptumoje duosi man pažinti išmintį.'),
  (@b19, 51, 7, 'Apvalyk mane yzopu, ir būsiu švarus; nuplauk mane, ir būsiu baltesnis už sniegą.'),
  (@b19, 51, 8, 'Duok man išgirsti džiaugsmą ir linksmybę; kad džiūgautų kaulai, kuriuos sulaužei.'),
  (@b19, 51, 9, 'Paslėpk savo veidą nuo mano nuodėmių ir išdildyk visas mano neteisybes.'),
  (@b19, 51, 10, 'Sutverk manyje švarią širdį, o Dieve; ir teisingą dvasią atnaujink manyje.'),
  (@b19, 51, 11, 'Neatmesk manęs iš savo akivaizdos; ir savo šventos Dvasios neatimk iš manęs.'),
  (@b19, 51, 12, 'Grąžink man tavo išgelbėjimo džiaugsmą; ir paremk mane savo laisva dvasia.'),
  (@b19, 51, 13, 'Tada mokysiu nusižengėlius tavo kelių; ir nusidėjėliai atsivers į tave.'),
  (@b19, 51, 14, 'Išvaduok mane nuo kraujo kaltės, o Dieve, mano išgelbėjimo Dieve; ir mano liežuvis garsiai giedos apie tavo teisumą.'),
  (@b19, 51, 15, 'O Viešpatie, praverk mano lūpas; ir mano burna skelbs tavo gyrių.'),
  (@b19, 51, 16, 'Nes tu nenori aukos; priešingu atveju tau ją duočiau; tu nesimėgauji deginamąja atnaša.'),
  (@b19, 51, 17, 'Dievo aukos yra sudužusi dvasia; sudužusios ir palūžusios širdies tu, Dieve, nepaniekinsi.'),
  (@b19, 51, 18, 'Savo gera valia daryk gera Sionui: pastatyk Jeruzalės sienas.'),
  (@b19, 51, 19, 'Tada tu būsi patenkintas teisumo aukomis, deginamąja atnaša ir visai sudeginama atnaša; tada jie atnašaus jaučius ant tavo aukuro.'),
  (@b19, 52, 1, 'Vyriausiajam muzikantui. Maskylas. Dovydo psalmė, kai edomietis Doegas atėjęs pranešė Sauliui, jam sakydamas: „Dovydas yra atėjęs į Ahimelecho namus“. Kodėl giriesi piktadarybe, o galiūne? Dievo gerumas išlieka nuolatos.'),
  (@b19, 52, 2, 'Tavo liežuvis sumano piktadarybes, kaip aštrus skustuvas besidarbuojantis klastingai.'),
  (@b19, 52, 3, 'Tu mėgsti pikta labiau už gera; ir meluoti labiau nei kalbėti teisumą. Sela.'),
  (@b19, 52, 4, 'Tu mėgsti visus ryjančius žodžius, o klastingas liežuvi.'),
  (@b19, 52, 5, 'Taip ir Dievas tave sunaikins amžiams, tave pašalins ir tave išplėš iš tavo gyvenamos vietos, ir išraus tave su šaknimis iš gyvųjų šalies. Sela.'),
  (@b19, 52, 6, 'Teisieji taipogi matys ir bijosis, ir iš jo juoksis:'),
  (@b19, 52, 7, '„Štai žmogus, kuris nepadarė Dievo savo stiprybe; bet pasitikėjo savo turtų gausa ir sustiprino save savo nedorybėje“.'),
  (@b19, 52, 8, 'Bet aš esu kaip žaliuojantis alyvmedis Dievo namuose; aš pasitikiu Dievo gailestingumu per amžių amžius.'),
  (@b19, 52, 9, 'Aš girsiu tave per amžius, nes tu tai padarei; ir lauksiu tavo vardo; nes tai gerai prieš tavo šventuosius.'),
  (@b19, 53, 1, 'Vyriausiajam muzikantui. Machalatu, maskylas. Dovydo psalmė. Kvailys tarė savo širdyje: „Nėra Dievo“. Jie sugedę ir darė bjaurią neteisybę; nėra, kas gera darytų.'),
  (@b19, 53, 2, 'Dievas pažiūrėjo žemyn iš dangaus į žmonių vaikus, kad pamatytų, ar yra kas supranta, kas ieško Dievo.'),
  (@b19, 53, 3, 'Jie visi atsitraukė; jie visiškai tapo nešvarūs; nėra gera darančio, ne, nei vieno.'),
  (@b19, 53, 4, 'Argi neteisybę darantys neturi pažinimo, kurie valgo mano tautą kaip valgo duoną? Jie nesišaukė Dievo.'),
  (@b19, 53, 5, 'Jie labai bijojo ten, kur nebuvo baimės; nes Dievas išsklaidė kaulus to, kuris stovyklauja prieš tave; tu juos sugėdinai, nes Dievas juos paniekino.'),
  (@b19, 53, 6, 'O kad Izraelio išgelbėjimas ateitų iš Siono! Kai Dievas sugrąžins savo tautos nelaisvę, Jokūbas džiūgaus, ir linksminsis Izraelis.'),
  (@b19, 54, 1, 'Vyriausiajam muzikantui, Neginotu, maskylas. Dovydo psalmė, kai zifiečiai atėję pasakė Sauliui: „Argi Dovydas ne pas mus pasislėpęs?“ O Dieve, savo vardu išgelbėk mane ir savo stiprybe teisk mane.'),
  (@b19, 54, 2, 'O Dieve, išgirsk mano maldą; palenk ausį mano burnos žodžiams.'),
  (@b19, 54, 3, 'Nes svetimšaliai sukilę prieš mane, ir engėjai ieško mano sielos; jie nepastatė prieš save Dievo. Sela.'),
  (@b19, 54, 4, 'Štai Dievas yra mano padėjėjas; Viešpats yra su tais, kurie palaiko mano sielą.'),
  (@b19, 54, 5, 'Jis atlygins piktu mano priešams; iškirsk juos savo tiesa.'),
  (@b19, 54, 6, 'Aš laisvai tau aukosiu; aš girsiu tavo vardą, o VIEŠPATIE, nes jis yra geras.'),
  (@b19, 54, 7, 'Nes jis mane išvadavo iš visos bėdos; ir mano akis matė jo norą ant mano priešų.'),
  (@b19, 55, 1, 'Vyriausiajam muzikantui, Neginotu, maskylas. Dovydo psalmė. Palenk ausį, o Dieve, į mano maldą; ir nesislėpk nuo mano prašymo.'),
  (@b19, 55, 2, 'Kreipk dėmesį į mane ir išgirsk mane; aš raudu savo nusiskundime ir leidžiu garsą;'),
  (@b19, 55, 3, 'dėl priešo balso, dėl nedorėlių engimo; nes jie meta ant manęs neteisybę ir užsirūstinę neapkenčia manęs.'),
  (@b19, 55, 4, 'Mano širdžiai labai skauda manyje; ir mirties siaubai nupuolė ant manęs.'),
  (@b19, 55, 5, 'Baimė ir drebėjimas mane ištiko, ir siaubas apėmė mane.'),
  (@b19, 55, 6, 'Ir aš sakiau: „O, kad turėčiau sparnus kaip karvelis! Tada nuskrisčiau ir būčiau ramybėje.'),
  (@b19, 55, 7, 'Štai tada aš nuklajočiau toli ir pasilikčiau dykumoje. Sela.'),
  (@b19, 55, 8, 'Pasiskubinčiau pabėgti nuo siaučiančio vėjo ir audros.'),
  (@b19, 55, 9, 'Sunaikink, o Viešpatie, ir padalink jų liežuvius; nes mačiau smurtą ir vaidus mieste.'),
  (@b19, 55, 10, 'Dieną ir naktį jie eina aplink jį ant jo sienų; piktadarybė ir sielvartas yra jo viduje.'),
  (@b19, 55, 11, 'Nedorybė yra jo viduje; apgaulė ir klasta nesitraukia nuo jo gatvių.'),
  (@b19, 55, 12, 'Nes ne priešas man prikaišiojo; nes tada būčiau tai pakentęs; ir ne tas, kuris nekenčia manęs, aukštinosi prieš mane; nes tada būčiau pasislėpęs nuo jo;'),
  (@b19, 55, 13, 'bet tai buvai tu – žmogus man lygus, mano vedlys ir mano pažįstamas.'),
  (@b19, 55, 14, 'Mūsų pasitarimai buvo malonūs, ir mes būriu vaikščiodavome į Dievo namus.'),
  (@b19, 55, 15, 'Tesučiumpa juos mirtis ir tenužengia jie į pragarą gyvi; nes nedorybė yra jų buveinėse ir tarp jų.'),
  (@b19, 55, 16, 'O aš, aš šauksiuosi Dievo; ir VIEŠPATS mane išgelbės.'),
  (@b19, 55, 17, 'Vakare, ryte ir vidudienį aš melsiuosi ir garsiai šauksiu; ir jis išgirs mano balsą.'),
  (@b19, 55, 18, 'Jis taikoje išvadavo mano sielą nuo mūšio, buvusio prieš mane; nes daug buvo su manimi.'),
  (@b19, 55, 19, 'Dievas išgirs ir juos ištiks – tas, kuris išlieka nuo seno. Sela. Kadangi nėra juose pasikeitimų, todėl jie nebijo Dievo.'),
  (@b19, 55, 20, 'Jis ištiesė savo ranką prieš tuos, kurie yra taikoje su juo; jis sulaužė savo sandorą.'),
  (@b19, 55, 21, 'Jo burnos žodžiai buvo slidesni už sviestą, tačiau karas buvo jo širdyje; jo žodžiai buvo švelnesni už aliejų, tačiau jie buvo ištraukti kalavijai.'),
  (@b19, 55, 22, 'Mesk ant VIEŠPATIES savo naštą, ir jis tave palaikys; jis niekados neleis teisiajam svyruoti.'),
  (@b19, 55, 23, 'Bet tu, o Dieve, juos nuvesi į pražūties duobę; kraugeriai ir apgavikai neišgyvens pusės savo dienų; bet aš pasitikėsiu tavimi.'),
  (@b19, 56, 1, 'Vyriausiajam muzikantui, Jonat-Elem-Rechokimu. Dovydo miktamas, kai filistinai jį suėmė Gate. Būk man gailestingas, o Dieve; nes žmogus nori mane praryti; jis kovodamas kas dieną mane engia.'),
  (@b19, 56, 2, 'Mano priešai kasdien nori mane praryti; nes daug tų, kurie kovoja prieš mane, o Aukščiausiasis.'),
  (@b19, 56, 3, 'Kai bijau, tavimi pasitikėsiu.'),
  (@b19, 56, 4, 'Dieve aš girsiu jo žodį, Dievu pasikliauju; nebijosiu, ką gali man padaryti kūnas.'),
  (@b19, 56, 5, 'Kiekvieną dieną jie kraipo mano žodžius; visos jų mintys yra prieš mane dėl pikto.'),
  (@b19, 56, 6, 'Jie susirenka, pasislepia, stebi mano žingsnius, laukdami mano sielos.'),
  (@b19, 56, 7, 'Ar jie pabėgs per neteisybę? Savo pyktyje parblokšk tautas, o Dieve.'),
  (@b19, 56, 8, 'Tu skaičiuoji mano klajojimus; sudėk mano ašaras į savo indą; argi jų nėra tavo knygoje?'),
  (@b19, 56, 9, 'Kai tavęs šaukiuosi, sukasi atgal mano priešai; tai aš žinau; nes Dievas yra už mane.'),
  (@b19, 56, 10, 'Dieve girsiu jo žodį; VIEŠPATYJE girsiu jo žodį.'),
  (@b19, 56, 11, 'Dievu pasikliauju; nebijosiu, ką gali man padaryti žmogus.'),
  (@b19, 56, 12, 'Tavo įžadai ant manęs, o Dieve: tau atmokėsiu gyriumi.'),
  (@b19, 56, 13, 'Nes tu išvadavai mano sielą iš mirties; ar neišvaduosi mano kojų nuo griuvimo, kad vaikščiočiau Dievo akivaizdoje, gyvųjų šviesoje?'),
  (@b19, 57, 1, 'Vyriausiajam muzikantui, Al-Taschitas. Dovydo miktamas, kai jis bėgo nuo Sauliaus į olą. Būk man gailestingas, o Dieve, būk man gailestingas; nes mano siela pasitiki tavimi; taip, tavo sparnų šešėlyje pasidarysiu sau prieglobstį, kol praeis šitos nelaimės.'),
  (@b19, 57, 2, 'Aš šauksiuosi aukščiausiojo Dievo, Dievo, kuris dėl manęs viską daro.'),
  (@b19, 57, 3, 'Jis siųs iš dangaus ir mane išgelbės nuo priekaištų to, kuris nori mane praryti. Sela. Dievas išsiųs savo gailestingumą ir savo tiesą.'),
  (@b19, 57, 4, 'Mano siela yra tarp liūtų; ir guliu tarp padegtųjų – žmonių sūnų, kurių dantys yra ietys ir strėlės, o jų liežuvis – aštrus kalavijas.'),
  (@b19, 57, 5, 'Būk išaukštintas virš dangų, o Dieve; tavo šlovė tebūna virš visos žemės.'),
  (@b19, 57, 6, 'Jie paruošė tinklą mano žingsniams; mano siela sulinkusi; jie iškasė prieš mane duobę, į kurią jie patys įkrito. Sela.'),
  (@b19, 57, 7, 'Sutvirtinta mano širdis, o Dieve, sutvirtinta mano širdis; aš giedosiu ir girsiu.'),
  (@b19, 57, 8, 'Pabusk, mano šlove; pabuskite, psalteri ir arfa; aš pats pabusiu anksti.'),
  (@b19, 57, 9, 'Girsiu tave, o Viešpatie, tautose; giedosiu tau tautybėse.'),
  (@b19, 57, 10, 'Nes tavo gailestingumas yra didis iki dangų, ir tavo tiesa iki debesų.'),
  (@b19, 57, 11, 'Būk išaukštintas virš dangų, o Dieve; tavo šlovė tebūna virš visos žemės.'),
  (@b19, 58, 1, 'Vyriausiajam muzikantui, Al-Taschitas. Dovydo miktamas. Ar iš tikrųjų jūs kalbate teisumą, o susirinkime? Ar jūs tiesumu teisiate, o žmonių sūnūs?'),
  (@b19, 58, 2, 'Taip, jūs darote nedorybę širdyje; jūs sveriate savo rankų smurtą žemėje.'),
  (@b19, 58, 3, 'Nedorėliai atitolę nuo pat įsčių; vos gimę jie nuklysta kalbėdami melą.'),
  (@b19, 58, 4, 'Jų nuodai kaip gyvatės nuodai; jie kaip kurčia angis, kuri užsikemša ausis;'),
  (@b19, 58, 5, 'kuri neklausys kerėtojų balso, niekada taip išmintingai nekerinčių.'),
  (@b19, 58, 6, 'O Dieve, sulaužyk jiems dantis jų burnoje; išlaužk didelius jaunų liūtų dantis, o VIEŠPATIE.'),
  (@b19, 58, 7, 'Jie teištirpsta kaip nuolat tekantys vandenys; kai jis įtempia savo lanką strėlėms šauti, tebūna jie kaip nukapoti.'),
  (@b19, 58, 8, 'Jie kiekvienas tedingsta kaip pranykstanti sraigė; kad jie nematytų saulės, kaip priešlaikinis moters pagimdytasis.'),
  (@b19, 58, 9, 'Prieš tai, kai jūsų puodai pajus erškėčius, jis tarsi viesulu nuneš juos gyvus ir savo rūstybėje.'),
  (@b19, 58, 10, 'Teisusis džiaugsis, kai pamatys kerštą; jis plaus savo kojas nedorėlio kraujyje.'),
  (@b19, 58, 11, 'Taip, kad žmogus sakys: „Tikrai yra atlygis teisiajam; tikrai jis yra Dievas, kuris teisia žemėje“.'),
  (@b19, 59, 1, 'Vyriausiajam muzikantui, Al-Taschitas. Dovydo miktamas. Kai Saulius pasiuntė, ir tie saugojo namus, kad jį nužudytų. Išvaduok mane iš mano priešų, o mano Dieve; apgink mane nuo tų, kurie sukyla prieš mane.'),
  (@b19, 59, 2, 'Išvaduok mane nuo darančių neteisybę ir išgelbėk mane nuo kraugerių.'),
  (@b19, 59, 3, 'Nes štai jie tykoja mano sielos; susirinko prieš mane galingieji; ne dėl mano nusižengimo ir ne dėl mano nuodėmės, o VIEŠPATIE.'),
  (@b19, 59, 4, 'Be mano kaltės jie bėga ir pasiruošia; pabusk man padėti ir pasižiūrėk.'),
  (@b19, 59, 5, 'Todėl tu, o VIEŠPATIE, kariuomenių Dieve, Izraelio Dieve, pabusk aplankyti visus pagonis; nesigailėk nei vieno nedoro nusižengėlio. Sela.'),
  (@b19, 59, 6, 'Jie sugrįžta vakare, leidžia garsą kaip šuo ir eina aplink miestą.'),
  (@b19, 59, 7, 'Štai jie raugėja savo burna; kalavijai jų lūpose, nes jie sako: „Kas gi girdi?“'),
  (@b19, 59, 8, 'Bet tu, o VIEŠPATIE, juoksiesi iš jų; tu pajuoksi visus pagonis.'),
  (@b19, 59, 9, 'Dėl jo stiprybės tavęs aš lauksiu; nes Dievas yra mano apsauga.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 59, 10, 'Mano gailestingumo Dievas mane aplenkęs pasitiks; Dievas leis man pamatyti mano norą ant mano priešų.'),
  (@b19, 59, 11, 'Nenužudyk jų, idant mano tauta nepamirštų; išsklaidyk juos savo jėga; ir juos pargriauk, o Viešpatie, mūsų skyde.'),
  (@b19, 59, 12, 'Už nuodėmę jų burnos ir už žodžius jų lūpų tebūna jie pagauti savo išdidume; ir už prakeikimą ir melą, kuriuos jie kalba.'),
  (@b19, 59, 13, 'Sunaikink juos rūstybėje, sunaikink, kad jų nebūtų; ir težino jie, kad Dievas valdo Jokūbe iki žemės pakraščių. Sela.'),
  (@b19, 59, 14, 'Tesugrįžta jie vakare; ir teleidžia garsą kaip šuo, ir eina aplink miestą.'),
  (@b19, 59, 15, 'Teklaidžioja jie ten ir atgal dėl maisto, ir tejaučia nepasitenkinimą, jei nepasisotina.'),
  (@b19, 59, 16, 'Bet aš giedosiu apie tavo stiprybę; taip, aš garsiai giedosiu ryte apie tavo gailestingumą; nes tu buvai mano apsauga ir prieglobstis mano vargo dieną.'),
  (@b19, 59, 17, 'O mano stiprybe, tau giedosiu; nes Dievas yra mano apsauga ir mano gailestingumo Dievas.'),
  (@b19, 60, 1, 'Vyriausiajam muzikantui, Šušan-Edutu. Dovydo miktamas pamokymui; kai jis kovojo su Aram-Naharaimu ir Aram-Coba, kai sugrįžęs Joabas sumušė iš Edomo dvylika tūkstančių Druskos slėnyje. O Dieve, tu mus atstūmei, mus išsklaidei, tu buvai nepatenkintas; o atsigręžk į mus vėl.'),
  (@b19, 60, 2, 'Tu sudrebinai žemę; ją suskaldei; užgydyk jos plyšius, nes ji kratosi.'),
  (@b19, 60, 3, 'Tu parodei savo tautai sunkių dalykų; mus girdei nustebimo vynu.'),
  (@b19, 60, 4, 'Tu davei vėliavą tiems, kurie tavęs bijo, kad ji būtų iškelta dėl tiesos. Sela.'),
  (@b19, 60, 5, 'Kad tavo mylimieji būtų išvaduoti; išgelbėk savo dešine ir išgirsk mane.'),
  (@b19, 60, 6, 'Dievas kalbėjo savo šventume: „Aš džiūgausiu, aš padalinsiu Šechemą ir atmatuosiu Sukoto slėnį.'),
  (@b19, 60, 7, 'Mano yra Gileadas ir mano Manasas; Efraimas yra mano galvos stiprybė; Juda – mano įstatymleidys;'),
  (@b19, 60, 8, 'Moabas yra mano praustuvas; ant Edomo aš numesiu savo apavą; Filistija, džiaukis dėl manęs“.'),
  (@b19, 60, 9, 'Kas mane įves į tvirtą miestą? Kas mane nuves į Edomą?'),
  (@b19, 60, 10, 'Argi ne tu, o Dieve, kuris mus atstūmei, ir ar ne tu, o Dieve, kuris neišėjai su mūsų kariuomenėmis?'),
  (@b19, 60, 11, 'Suteik mums pagalbą nuo bėdos; nes tuščia yra žmogaus pagalba.'),
  (@b19, 60, 12, 'Per Dievą mes narsiai elgsimės; nes jis yra tas, kuris sumindys mūsų priešus.'),
  (@b19, 61, 1, 'Vyriausiajam muzikantui, Negina. Dovydo psalmė. Išgirsk, o Dieve, mano šauksmą; kreipk dėmesį į mano maldą.'),
  (@b19, 61, 2, 'Nuo žemės krašto tavęs šauksiuosi mano širdžiai alpstant; nuvesk mane prie uolos, kuri yra aukštesnė už mane.'),
  (@b19, 61, 3, 'Nes tu buvai man prieglauda ir stiprus bokštas nuo priešo.'),
  (@b19, 61, 4, 'Aš gyvensiu tavo padangtėje amžinai; aš pasitikėsiu tavo sparnų prieglauda. Sela.'),
  (@b19, 61, 5, 'Nes tu, o Dieve, girdėjai mano įžadus: tu davei man paveldą tų, kurie bijo tavo vardo.'),
  (@b19, 61, 6, 'Tu prailginsi karaliaus gyvenimą ir jo metus kaip kartų kartas.'),
  (@b19, 61, 7, 'Jis gyvens per amžius Dievo akivaizdoje; paruošk gailestingumą ir tiesą, kurie jį apsaugotų.'),
  (@b19, 61, 8, 'Taip aš giedosiu gyrių tavo vardui per amžius, kad kasdien vykdyčiau savo įžadus.'),
  (@b19, 62, 1, 'Vyriausiajam muzikantui. Jedutūnui. Dovydo psalmė. Tikrai mano siela laukia Dievo; iš jo ateina mano išgelbėjimas.'),
  (@b19, 62, 2, 'Jis vienintelis yra mano uola ir mano išgelbėjimas; jis yra mano apsauga; aš labai nesvyruosiu.'),
  (@b19, 62, 3, 'Kaip ilgai galvosite piktadarystę prieš žmogų? Jūs visi būsite nužudyti; jūs būsite kaip palinkusi siena ir kaip svyruojanti tvora.'),
  (@b19, 62, 4, 'Jie tik tariasi jį nugriauti iš jo puikumo; jie gėrisi melu; savo burna jie laimina, o savo viduje keikia. Sela.'),
  (@b19, 62, 5, 'Tik Dievo lauk, mano siela; nes mano tikėjimasis yra iš jo.'),
  (@b19, 62, 6, 'Tik jis yra mano uola ir mano išgelbėjimas; jis yra mano apsauga; aš nesvyruosiu.'),
  (@b19, 62, 7, 'Dieve yra mano išgelbėjimas ir mano šlovė; mano stiprybės uola ir mano prieglobstis yra Dieve.'),
  (@b19, 62, 8, 'Pasitikėkite juo visais laikais; tauta, išliekite jo akivaizdoje savo širdį; Dievas yra mums prieglobstis. Sela.'),
  (@b19, 62, 9, 'Tikrai žemos kilmės žmonės yra tuštybė, o aukštos kilmės žmonės yra melas; sudėti ant svarstyklių jie visi drauge lengvesni už tuštybę.'),
  (@b19, 62, 10, 'Nepasitikėkite engimu ir nepasidarykite tušti plėšikavimu; jei gausėja turtai, nepakreipkite į juos savo širdies.'),
  (@b19, 62, 11, 'Kartą Dievas kalbėjo; du kartus tai girdėjau, kad jėga priklauso Dievui.'),
  (@b19, 62, 12, 'Tau, o Viešpatie, priklauso ir gailestingumas; nes tu atlygini kiekvienam pagal jo darbą.'),
  (@b19, 63, 1, 'Dovydo psalmė, kai jis buvo Judos dykumoje. O Dieve, tu esi mano Dievas; anksti tavęs ieškosiu; tavęs trokšta mano siela, tavęs ilgisi mano kūnas sausoje ir ištroškusioje žemėje, kur nėra vandens;'),
  (@b19, 63, 2, 'kad pamatyčiau tavo jėgą ir tavo šlovę, kaip mačiau tave šventovėje.'),
  (@b19, 63, 3, 'Kadangi tavo mylintis gerumas – geresnis už gyvenimą, mano lūpos girs tave.'),
  (@b19, 63, 4, 'Taip aš laiminsiu tave, kol gyvensiu; tavo vardu pakelsiu savo rankas.'),
  (@b19, 63, 5, 'Mano siela bus pasotinta kaip kaulų smegenimis ir riebalais; ir mano burna girs tave džiaugsmingomis lūpomis,'),
  (@b19, 63, 6, 'kai prisiminsiu tave savo patale ir mąstysiu apie tave nakties budėjimuose.'),
  (@b19, 63, 7, 'Kadangi tu buvai man pagalba, todėl džiaugsiuosi tavo sparnų šešėlyje.'),
  (@b19, 63, 8, 'Mano siela seka įkandin paskui tave; tavo dešinė palaiko mane.'),
  (@b19, 63, 9, 'Bet tie, kurie siekia mano sielos, kad ją sunaikintų, nueis į žemesnes žemės dalis.'),
  (@b19, 63, 10, 'Jie kris nuo kalavijo; jie bus dalimi lapėms.'),
  (@b19, 63, 11, 'Bet karalius džiaugsis Dievu; girsis kiekvienas, kuris juo prisiekia; bet melą kalbančių burna bus užčiaupta.'),
  (@b19, 64, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Išgirsk, o Dieve, mano balsą mano maldoje; nuo priešo baimės saugok mano gyvybę.'),
  (@b19, 64, 2, 'Paslėpk mane nuo nedorėlių slapto pasitarimo; nuo neteisybę darančių maišto;'),
  (@b19, 64, 3, 'kurie galanda savo liežuvį kaip kalaviją, ir įtempia savo lankus, kad šautų savo strėles – karčius žodžius;'),
  (@b19, 64, 4, 'kad slapta šautų į tobuląjį; staiga jie šauna į jį ir nebijo.'),
  (@b19, 64, 5, 'Jie drąsina save piktam tikslui; jie kalbasi, kaip slaptai padėti žabangas; jie sako: „Kas juos pamatys?'),
  (@b19, 64, 6, 'Jie suieško neteisybes; atlieka kruopštų ieškojimą; kiekvieno jų vidinės mintys ir širdis – gilios.'),
  (@b19, 64, 7, 'Bet Dievas šaus į juos strėle; staiga jie bus sužeisti.'),
  (@b19, 64, 8, 'Taip jie savo liežuviu pargrius ant savęs pačių; visi, kurie juos matys, bėgs šalin.'),
  (@b19, 64, 9, 'Visi žmonės bijos ir skelbs Dievo darbą; nes jie išmintingai apsvarstys apie jo darbą.'),
  (@b19, 64, 10, 'Teisusis džiaugsis VIEŠPAČIU ir juo pasitikės; ir girsis visi tiesiaširdžiai.'),
  (@b19, 65, 1, 'Vyriausiajam muzikantui. Dovydo psalmė ir giesmė. Gyrius laukia tavęs Sione, o Dieve; ir tau bus įvykdytas įžadas.'),
  (@b19, 65, 2, 'O tu, kuris išklausai maldą, pas tave ateis visi kūnai.'),
  (@b19, 65, 3, 'Neteisybės įveikia mane; o mūsų nusižengimus – tu juos nuvalysi.'),
  (@b19, 65, 4, 'Palaimintas žmogus, kurį tu išsirenki ir priartini prie savęs, kad jis gyventų tavo kiemuose; mes pasitenkinsime gėrybėmis tavo namų – tavo šventos šventyklos.'),
  (@b19, 65, 5, 'Baisiais dalykais teisume tu mums atsakysi, o mūsų išgelbėjimo Dieve, kuris esi užtikrintumas visų žemės pakraščių ir esančių toli jūroje;'),
  (@b19, 65, 6, 'tu tvirtai padėjai kalnus savo stiprybe, susijuosęs galybe;'),
  (@b19, 65, 7, 'tu nutildai jūrų ūžimą, jų bangų šniokštimą ir tautų triukšmą.'),
  (@b19, 65, 8, 'Taip pat gyvenantys tolimiausiuose pakraščiuose bijosi tavo ženklų; ryto ir vakaro išėjimus tu priverti džiaugtis.'),
  (@b19, 65, 9, 'Tu aplankai žemę ir ją palaistai; labai ją praturtini Dievo upe, kuri yra pilna vandens; tu paruoši jiems javus, taip jai parūpindamas.'),
  (@b19, 65, 10, 'Tu gausiai palaistai jos vagų gūbrius, sulygini jos vagas, liūtimis ją suminkštini, jos želmenis palaimini.'),
  (@b19, 65, 11, 'Tu apvainikuoji metus savo gerumu; ir tavo takai varva riebalais.'),
  (@b19, 65, 12, 'Jie varva ant dykumos ganyklų; ir iš visų pusių džiūgauja mažos kalvos.'),
  (@b19, 65, 13, 'Ganyklos apsivilkusios kaimenėmis; ir slėniai apsidengę javais; jie šaukia iš džiaugsmo ir gieda.'),
  (@b19, 66, 1, 'Vyriausiajam muzikantui. Giesmė arba psalmė. Džiaugsmingai šaukite Dievui, visos šalys;'),
  (@b19, 66, 2, 'giedokite jo vardo garbę; darykite jo gyrių šlovingą.'),
  (@b19, 66, 3, 'Sakykite Dievui: „Koks tu baisus savo darbais! Dėl tavo galios didybės tau paklus tavo priešai.'),
  (@b19, 66, 4, 'Visa žemė garbins tave ir tau giedos; jie giedos tavo vardui“. Sela.'),
  (@b19, 66, 5, 'Ateikite ir pamatykite Dievo darbus; jis baisus savo darbuose žmonių vaikams.'),
  (@b19, 66, 6, 'Jis pavertė jūrą sausuma; per upę jie ėjo pėsti; ten mes džiaugėmės juo.'),
  (@b19, 66, 7, 'Jis viešpatauja savo galybe per amžius; jo akys stebi tautas; maištininkai tenesiaukština. Sela.'),
  (@b19, 66, 8, 'Laiminkite, tautos, mūsų Dievą ir darykite, kad girdėtųsi jo gyriaus balsas;'),
  (@b19, 66, 9, 'jis išlaiko mūsų sielą gyvybėje ir neleidžia svyruoti mūsų kojoms.'),
  (@b19, 66, 10, 'Nes tu mus išmėginai, o Dieve; išbandei mus, kaip sidabras yra bandomas.'),
  (@b19, 66, 11, 'Tu mus įvedei į tinklą; uždėjai sielvartą mums ant strėnų.'),
  (@b19, 66, 12, 'Tu leidai žmonėms joti per mūsų galvas; mes ėjome per ugnį ir per vandenį; bet tu mus išvedei į turtingą vietą.'),
  (@b19, 66, 13, 'Aš įeisiu į tavo namus su deginamosiomis atnašomis; tau ištesėsiu savo įžadus,'),
  (@b19, 66, 14, 'kuriuos ištarė mano lūpos ir kalbėjo mano burna, kai buvau bėdoje.'),
  (@b19, 66, 15, 'Tau atnašausiu peniukšlių deginamąsias aukas su avinų smilkalais; atnašausiu jaučius su ožiais. Sela.'),
  (@b19, 66, 16, 'Jūs visi, kurie bijote Dievo, ateikite ir klausykite, ir aš paskelbsiu, ką jis padarė mano sielai.'),
  (@b19, 66, 17, 'Jo šaukiausi savo burna, ir jis buvo liaupsinamas mano liežuviu.'),
  (@b19, 66, 18, 'Jei paisyčiau neteisybę savo širdyje, tai Viešpats manęs neišgirstų;'),
  (@b19, 66, 19, 'bet tikrai Dievas išgirdo mane; jis atsižvelgė į mano maldos balsą.'),
  (@b19, 66, 20, 'Tebūna palaimintas Dievas, kuris nenukreipė mano maldos ir savo gailestingumo nuo manęs.'),
  (@b19, 67, 1, 'Vyriausiajam muzikantui, Neginotu. Psalmė arba giesmė. Dievas tebūna mums gailestingas ir tepalaimina mus; ir tešviečia ant mūsų savo veidu. Sela.'),
  (@b19, 67, 2, 'Kad žemėje būtų žinomas tavo kelias, tavo gelbėjanti sveikata tarp visų tautų.'),
  (@b19, 67, 3, 'O Dieve, tegiria tave tautos; tegiria tave visos tautos.'),
  (@b19, 67, 4, 'Tesilinksmina ir tegieda iš džiaugsmo tautos; nes tu teisi tautas teisiai ir valdysi tautas žemėje. Sela.'),
  (@b19, 67, 5, 'Tautos tegiria tave, o Dieve; tegiria tave visos tautos.'),
  (@b19, 67, 6, 'Tada žemė duos savo prieaugį; ir Dievas, mūsų pačių Dievas, mus palaimins.'),
  (@b19, 67, 7, 'Dievas mus palaimins; ir jo bijos visi žemės pakraščiai.'),
  (@b19, 68, 1, 'Vyriausiajam muzikantui. Dovydo psalmė arba giesmė. Tepakyla Dievas, tebūna išsklaidyti jo priešai; ir tebėga iš jo akivaizdos tie, kurie jo nekenčia.'),
  (@b19, 68, 2, 'Kaip dūmai išsklaidomi, taip juos išsklaidyk; kaip vaškas sutirpsta nuo ugnies, taip tepražūna nedorėliai Dievo akivaizdoje.'),
  (@b19, 68, 3, 'Bet teisieji tegul linksminasi; tedžiūgauja jie Dievo akivaizdoje; taip, tegul jie be galo džiūgauja.'),
  (@b19, 68, 4, 'Giedokite Dievui, giedokite jo vardui gyrių; liaupsinkite jį, kuris važinėja ant dangų, jo vardas JAH, ir džiūgaukite jo akivaizdoje.'),
  (@b19, 68, 5, 'Našlaičių tėvas ir našlių teisėjas yra Dievas savo šventoje buveinėje.'),
  (@b19, 68, 6, 'Dievas apgyvendina vienišus šeimose; jis išveda tuos, kurie sukaustyti grandinėmis; bet maištininkai gyvena išdžiūvusioje žemėje.'),
  (@b19, 68, 7, 'O Dieve, kai tu išėjai savo tautos priešakyje, kai žygiavai per dykumą; Sela;'),
  (@b19, 68, 8, 'žemė drebėjo, taip pat dangūs lašėjo Dievo akivaizdoje; net pats Sinajus judėjo Dievo, Izraelio Dievo, akivaizdoje.'),
  (@b19, 68, 9, 'Tu, o Dieve, siuntei gausų lietų, kuriuo tu sustiprinai savo paveldą, kai jis buvo nuvargęs.'),
  (@b19, 68, 10, 'Tavo susirinkimas gyveno ten; tu, o Dieve, paruošei iš savo gerumo vargšams.'),
  (@b19, 68, 11, 'Viešpats davė žodį; didelis buvo būrys tų, kurie jį skelbė.'),
  (@b19, 68, 12, 'Kariuomenių karaliai greitai pabėgo; o pasilikusioji namuose padalino grobį.'),
  (@b19, 68, 13, 'Nors jūs gulėjote tarp puodų, tačiau būsite kaip karvelio sparnai, padengti sidabru, ir jo plunksnos – geltonu auksu.'),
  (@b19, 68, 14, 'Kai Visagalis išsklaidė joje karalius, ji buvo balta kaip sniegas Salmone.'),
  (@b19, 68, 15, 'Dievo kalva yra kaip Bašano kalva; aukšta kalva kaip Bašano kalva.'),
  (@b19, 68, 16, 'Kodėl šokinėjate jūs, aukštosios kalvos? Tai kalva, kurioje Dievas nori gyventi; taip, VIEŠPATS gyvens joje per amžius.'),
  (@b19, 68, 17, 'Dievo vežimų – dvidešimt tūkstančių, tai yra, tūkstančiai angelų; Viešpats yra tarp jų kaip Sinajuje, šventoje vietoje.'),
  (@b19, 68, 18, 'Tu užžengei į aukštybę, vedei nelaisvėn nelaisvę; gavai žmonėms dovanų; taip, ir maištautojams, kad VIEŠPATS Dievas gyventų tarp jų.'),
  (@b19, 68, 19, 'Tebūna palaimintas Viešpats, kuris kasdien mus apkrauna geradarystėmis, tai yra, mūsų išgelbėjimo Dievas. Sela.'),
  (@b19, 68, 20, 'Tas, kuris yra mūsų Dievas, yra išgelbėjimo Dievas; Viešpats DIEVAS turi išeitis iš mirties.'),
  (@b19, 68, 21, 'Bet Dievas sužeis galvą savo priešams ir plaukuotą skalpą tam, kuris toliau vis tebedaro savo nusižengimus.'),
  (@b19, 68, 22, 'Viešpats tarė: „Iš Bašano aš sugrąžinsiu, sugrąžinsiu savo tautą iš jūros gilumų;'),
  (@b19, 68, 23, 'kad tavo koja būtų įmerkta į tavo priešų kraują, ir tavo šunų liežuvis į tą patį“.'),
  (@b19, 68, 24, 'Jie matė tavo ėjimus, o Dieve; tai yra, ėjimus mano Dievo, mano Karaliaus, į šventovę.'),
  (@b19, 68, 25, 'Priešakyje ėjo giesmininkai, iš paskos ėjo grojantys instrumentais; tarp jų buvo panelės, grojančios tambūrinais.'),
  (@b19, 68, 26, 'Laiminkite Dievą susirinkimuose, tai yra, Viešpatį iš Izraelio šaltinio.'),
  (@b19, 68, 27, 'Ten yra mažasis Benjaminas su jų valdovu, Judos kunigaikščiai bei jų taryba, Zebulono kunigaikščiai ir Naftalio kunigaikščiai.'),
  (@b19, 68, 28, 'Tavo Dievas įsakė tavo stiprybei; sustiprink, o Dieve, tai, ką padarei dėl mūsų.'),
  (@b19, 68, 29, 'Dėl tavo šventyklos Jeruzalėje karaliai tau neš dovanas.'),
  (@b19, 68, 30, 'Subark ietininkų būrį, daugybę bulių su tautų veršiais, kol paklus visi su sidabriniais; išsklaidyk tautas, kurios gėrisi karu.'),
  (@b19, 68, 31, 'Kunigaikščiai ateis iš Egipto; netrukus Etiopija išties savo rankas į Dievą.'),
  (@b19, 68, 32, 'Žemės karalystės, giedokite Dievui; giedokite gyrių Viešpačiui; Sela;'),
  (@b19, 68, 33, 'tam, kuris važinėja ant dangų dangų, kurie buvo nuo seno; štai jis išsiunčia savo balsą, galingą balsą.'),
  (@b19, 68, 34, 'Pripažinkite Dievui stiprybę; viršum Izraelio yra jo didybė, ir jo stiprybė yra debesyse.'),
  (@b19, 68, 35, 'Tu baisus, o Dieve, iš savo šventų vietų; Izraelio Dievas yra tas, kuris teikia stiprybę ir galią savo tautai. Tebūna palaimintas Dievas.'),
  (@b19, 69, 1, 'Vyriausiajam muzikantui, Šašanimu. Dovydo psalmė. Gelbėk mane, o Dieve; nes vandenys atėjo iki mano sielos.'),
  (@b19, 69, 2, 'Grimstu į gilų dumblą, kur nėra ant ko atsistoti; įėjau į gilius vandenis, kur srovės užlieja mane.'),
  (@b19, 69, 3, 'Aš nuvargau bešaukdamas; išdžiūvo mano gerklė; išseko mano akys belaukiant mano Dievo.'),
  (@b19, 69, 4, 'Daugiau nei mano galvos plaukų yra tų, kurie be priežasties manęs nekenčia; galingi yra tie, kurie nori mane sunaikinti, neteisėtai būdami mano priešais; tada aš grąžinau tai, ko nebuvau atėmęs.'),
  (@b19, 69, 5, 'O Dieve, tu žinai mano kvailystę; ir mano nuodėmės nepaslėptos nuo tavęs.'),
  (@b19, 69, 6, 'Tenebūna gėdinami dėl manęs tie, kurie laukia tavęs, o Viešpatie, kariuomenių DIEVE; tenebūna sugluminami dėl manęs tie, kurie ieško tavęs, o Izraelio Dieve.'),
  (@b19, 69, 7, 'Kadangi dėl tavęs pakenčiau priekaištus; gėda apdengė mano veidą.'),
  (@b19, 69, 8, 'Svetimas tapau savo broliams ir pašalinis savo motinos vaikams.'),
  (@b19, 69, 9, 'Nes tavo namų uolumas suėdė mane; ir priekaištai tų, kurie tau priekaištauja, krito ant manęs.'),
  (@b19, 69, 10, 'Kai verkiau ir baudžiau savo sielą pasninku, tai buvo, kad man priekaištautų.'),
  (@b19, 69, 11, 'Taip pat padariau ašutinę savo drabužiu; ir tapau jiems patarle.'),
  (@b19, 69, 12, 'Tie, kurie sėdi vartuose, kalba prieš mane; ir aš buvau girtuoklių daina.'),
  (@b19, 69, 13, 'Bet aš, mano malda yra tau, o VIEŠPATIE, priimtinu metu; o Dieve, savo gailestingumo gausybėje išgirsk mane, savo išgelbėjimo tiesoje.'),
  (@b19, 69, 14, 'Išvaduok mane iš dumblo, ir tenenuskęsiu; tebūsiu išvaduotas iš tų, kurie manęs nekenčia, ir iš gilių vandenų.'),
  (@b19, 69, 15, 'Teneužlieja manęs vandens srovė ir tenepraryja manęs gelmės, ir tenesučiaupia duobė viršum manęs savo burnos.'),
  (@b19, 69, 16, 'Išgirsk mane, o VIEŠPATIE; nes geras tavo mylintis gerumas; gręžkis į mane pagal savo švelnių gailestingumų gausybę.'),
  (@b19, 69, 17, 'Ir neslėpk savo veido nuo savo tarno; nes esu bėdoje; skubiai išklausyk mane.'),
  (@b19, 69, 18, 'Priartėk prie mano sielos ir atpirk ją; dėl mano priešų išvaduok mane.'),
  (@b19, 69, 19, 'Tu žinai mano priekaištą, mano gėdą ir mano negarbę; mano priešininkai visi tavo akivaizdoje.'),
  (@b19, 69, 20, 'Priekaištas sudaužė mano širdį; aš pilnas sunkumo; aš laukiau, kad kas pasigailėtų, bet nei vieno nebuvo, ir guodėjų, bet nesuradau.'),
  (@b19, 69, 21, 'Jie davė man tulžies maistui; ir man ištroškus jie man davė gerti acto.'),
  (@b19, 69, 22, 'Tepavirsta jų stalas jų akivaizdoje spąstais; ir tai, kas turėtų būti jų gerovė, tepavirsta žabangomis.'),
  (@b19, 69, 23, 'Teaptemsta jų akys, kad jie neregėtų; ir padaryk, kad jų strėnos nuolat drebėtų.'),
  (@b19, 69, 24, 'Išliek ant jų savo pasipiktinimą, ir tavo rūstus pyktis tenutveria juos.'),
  (@b19, 69, 25, 'Jų buveinė teištuštėja; ir niekas tenegyvena jų palapinėse.'),
  (@b19, 69, 26, 'Nes jie persekioja tą, kurį tu sumušei; ir jie kalba skausmui tų, kuriuos tu sužeidei.'),
  (@b19, 69, 27, 'Pridėk neteisybę prie jų neteisybės; ir teneįeina jie į tavo teisumą.'),
  (@b19, 69, 28, 'Tebūna jie išdildyti iš gyvųjų knygos ir tenebūna užrašyti su teisiaisiais.'),
  (@b19, 69, 29, 'Bet aš esu vargšas ir sielvartaujantis; tavo išgelbėjimas, o Dieve, tepastato mane aukštai.'),
  (@b19, 69, 30, 'Aš girsiu Dievo vardą giesme ir jį aukštinsiu dėkojimu.'),
  (@b19, 69, 31, 'Ir tai VIEŠPAČIUI patiks labiau už jautį ar jautuką, turintį ragus ir nagus.'),
  (@b19, 69, 32, 'Nuolankieji tai matys ir džiaugsis; ir gyvens širdis jūsų, kurie ieškote Dievo.'),
  (@b19, 69, 33, 'Nes VIEŠPATS girdi vargšą ir neniekina savo belaisvių.'),
  (@b19, 69, 34, 'Tegul jį giria dangus ir žemė, jūros ir visa, kas juda jose.'),
  (@b19, 69, 35, 'Nes Dievas išgelbės Sioną ir pastatys Judos miestus; kad jie ten gyventų ir turėtų tai kaip nuosavybę.'),
  (@b19, 69, 36, 'Ir jo tarnų sėkla tai paveldės; o jo vardą mylintys ten gyvens.'),
  (@b19, 70, 1, 'Vyriausiajam muzikantui. Dovydo psalmė priminimui. Paskubėk, o Dieve, mane išvaduoti; skubėk, o VIEŠPATIE, man padėti.'),
  (@b19, 70, 2, 'Tegul susigėsta ir būna sugluminti tie, kurie vaikosi mano sielos; tesigręžia atgal ir tebūna sugėdinti tie, kurie trokšta man pakenkti.'),
  (@b19, 70, 3, 'Tebūna nugręžti atgal kaip atlygis dėl jų gėdos tie, kurie sako: „Aha, aha!“'),
  (@b19, 70, 4, 'Tegul džiaugiasi ir linksminasi tavyje visi, kurie tavęs ieško; ir nuolat tesako: „Tebūna išaukštintas Dievas“ tie, kurie myli tavo išgelbėjimą.'),
  (@b19, 70, 5, 'Bet aš vargšas ir stokojantis; o Dieve, skubėk pas mane; tu esi mano pagalba ir mano išvaduotojas; o VIEŠPATIE, nedelsk.'),
  (@b19, 71, 1, 'Tavimi, o VIEŠPATIE, aš pasikliauju; niekada tenebūsiu sugėdintas.'),
  (@b19, 71, 2, 'Savo teisumu išvaduok mane ir duok man pabėgti; palenk prie manęs savo ausį ir išgelbėk mane.'),
  (@b19, 71, 3, 'Būk man tvirta buveinė, kurioje galėčiau nuolat lankytis; tu davei įsakymą išgelbėti mane; nes tu esi mano uola ir mano tvirtovė.'),
  (@b19, 71, 4, 'O mano Dieve, išvaduok mane iš nedorėlio rankos, iš rankos neteisaus ir žiauraus žmogaus.'),
  (@b19, 71, 5, 'Nes tu, o Viešpatie DIEVE, esi mano viltis; tu mano pasitikėjimas nuo pat mano jaunystės.'),
  (@b19, 71, 6, 'Tavimi aš buvau palaikomas nuo pat įsčių; tu esi tas, kuris mane ištraukei iš mano motinos vidurių; mano gyrius nuolat bus apie tave.'),
  (@b19, 71, 7, 'Aš esu kaip nuostaba daugeliui; bet tu esi mano tvirtas prieglobstis.'),
  (@b19, 71, 8, 'Mano burna tebūna pripildyta tavo gyriaus ir tavo garbės visą dieną.'),
  (@b19, 71, 9, 'Neatstumk manęs senatvės metu; nepalik manęs mano jėgoms senkant.'),
  (@b19, 71, 10, 'Nes mano priešai kalba prieš mane; ir kurie tyko mano sielos, tariasi,'),
  (@b19, 71, 11, 'sakydami: „Dievas jį paliko; persekiokite ir sugaukite jį; nes nėra kas jį išvaduotų“.'),
  (@b19, 71, 12, 'O Dieve, nebūk toli nuo manęs; o mano Dieve, skubėk man į pagalbą.'),
  (@b19, 71, 13, 'Tebūna sugluminti ir sunaikinti mano sielos priešininkai; teapsigaubia jie priekaištu ir negarbe, kurie siekia man pakenkti.'),
  (@b19, 71, 14, 'Bet aš nuolat vilsiuosi ir girsiu tave vis labiau ir labiau.'),
  (@b19, 71, 15, 'Mano burna skelbs tavo teisumą ir tavo išgelbėjimą visą dieną; nes aš nežinau jų skaičiaus.'),
  (@b19, 71, 16, 'Aš eisiu Viešpaties DIEVO stiprybėje; aš minėsiu tavo teisumą – tavo vieno.'),
  (@b19, 71, 17, 'O Dieve, tu mane mokei nuo pat mano jaunystės; ir iki šiol skelbiau tavo nuostabius darbus.'),
  (@b19, 71, 18, 'Ir dabar, kai esu senas ir pražilęs, o Dieve, nepalik manęs, kol paskelbsiu tavo stiprybę šitai kartai ir tavo jėgą visiems ateisiantiems.'),
  (@b19, 71, 19, 'Taip pat tavo teisumas yra labai aukštai, o Dieve, kuris padarei didžių dalykų; o Dieve, kas yra tau lygus?!'),
  (@b19, 71, 20, 'Tu, kuris man parodei didelių ir skaudžių bėdų, mane vėl atgaivinsi ir vėl mane iškelsi iš žemės gilybių.'),
  (@b19, 71, 21, 'Tu pagausinsi mano didybę ir paguosi mane iš visų pusių.'),
  (@b19, 71, 22, 'Taip pat aš girsiu psalteriu tave, tai yra, tavo tiesą, o mano Dieve; tau giedosiu su arfa, o Izraelio Šventasis.'),
  (@b19, 71, 23, 'Labai džiūgaus mano lūpos, kai tau giedosiu; ir mano siela, kurią atpirkai.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 71, 24, 'Taip pat mano liežuvis visą dieną kalbės apie tavo teisumą; nes jie yra sugluminti, nes jie sugėdinti, kurie siekia man pakenkti.'),
  (@b19, 72, 1, 'Psalmė Saliamonui. O Dieve, suteik karaliui savo teismus ir savo teisumą karaliaus sūnui.'),
  (@b19, 72, 2, 'Jis teis tavo tautą teisumu ir tavo vargšus teismu.'),
  (@b19, 72, 3, 'Kalnai atneš taiką tautai, ir mažosios kalvos – teisumu.'),
  (@b19, 72, 4, 'Jis teis tautos vargšus, jis išgelbės nepasiturinčiųjų vaikus ir sutriuškins engėją.'),
  (@b19, 72, 5, 'Jie bijos tavęs, kol saulė ir mėnulis išliks, per kartų kartas.'),
  (@b19, 72, 6, 'Jis nusileis kaip lietus ant nupjautos žolės, kaip liūtys, drėkinančios žemę.'),
  (@b19, 72, 7, 'Jo dienomis teisusis klestės; ir taikos apstumas tol, kol išliks mėnulis.'),
  (@b19, 72, 8, 'Taip pat jis viešpataus nuo jūros iki jūros ir nuo upės iki žemės pakraščių.'),
  (@b19, 72, 9, 'Prieš jį nusilenks gyvenantys dykumoje; ir jo priešai laižys dulkes.'),
  (@b19, 72, 10, 'Taršišo ir salų karaliai atneš dovanų; Šebos ir Sebos karaliai atnašaus dovanas.'),
  (@b19, 72, 11, 'Taip, prieš jį parpuls visi karaliai; visos tautos jam tarnaus.'),
  (@b19, 72, 12, 'Nes jis išvaduos nepasiturintį, kai šis šaukiasi; ir vargšą bei tą, kuris neturi padėjėjo.'),
  (@b19, 72, 13, 'Jis pasigailės vargšo bei nepasiturinčiojo ir išgelbės nepasiturinčiųjų sielas.'),
  (@b19, 72, 14, 'Jis atpirks jų sielas iš apgaulės ir smurto; ir jų kraujas bus brangus jo akyse.'),
  (@b19, 72, 15, 'Jis gyvens, ir jam bus duota iš Šebos aukso; taip pat nuolatos bus atliekama malda už jį; ir kasdien jis bus giriamas.'),
  (@b19, 72, 16, 'Saujos javų bus žemėje, kalnų viršūnėse; jų vaisiai drebės kaip Libanas; ir tie iš miesto klestės kaip žemės žolė.'),
  (@b19, 72, 17, 'Jo vardas išliks per amžius; jo vardas pasiliks tiek ilgai, kiek saulė; ir žmonės bus palaiminti jame; visos tautos vadins jį palaimintu.'),
  (@b19, 72, 18, 'Tebūna palaimintas VIEŠPATS Dievas, Izraelio Dievas, kuris vienintelis daro nuostabius dalykus.'),
  (@b19, 72, 19, 'Ir tebūna palaimintas jo šlovingasis vardas per amžius; visa žemė tebūna pripildyta jo šlovės; Amen ir Amen.'),
  (@b19, 72, 20, 'Pasibaigė Jesės sūnaus Dovydo maldos.'),
  (@b19, 73, 1, 'Asafo psalmė. Tikrai geras yra Dievas Izraeliui, tai yra tokiems, kurie yra švarios širdies.'),
  (@b19, 73, 2, 'O aš – mano kojos beveik išsekę; mano žingsniai beveik paslydo.'),
  (@b19, 73, 3, 'Nes aš pavydėjau kvailiams, matydamas nedorėlių klestėjimą.'),
  (@b19, 73, 4, 'Nes jiems mirštant nėra pančių; bet jų stiprybė tvirta.'),
  (@b19, 73, 5, 'Jie nėra bėdoje, kaip kiti žmonės; ir jie neištinkami rykšte, kaip kiti žmonės.'),
  (@b19, 73, 6, 'Todėl išdidumas juos apjuosia kaip grandinė; smurtas juos gaubia kaip drabužis.'),
  (@b19, 73, 7, 'Nuo riebalų išsiverčia jų akys; jie turi daugiau, negu geidžia širdis.'),
  (@b19, 73, 8, 'Jie sugedę ir kalba nedorai dėl engimo; jie kalba išdidžiai.'),
  (@b19, 73, 9, 'Jie nukreipia savo burną prieš dangus, ir jų liežuvis vaikštinėja po žemę.'),
  (@b19, 73, 10, 'Todėl jo tauta čia sugrįžta; ir pilnos taurės vandenys yra jiems išgręžiami.'),
  (@b19, 73, 11, 'Jie sako: „Kaip Dievas žino? Ar Aukščiausiajame yra pažinimas?“'),
  (@b19, 73, 12, 'Štai šitie yra bedieviai, kurie klesti pasaulyje; jie praturtėja.'),
  (@b19, 73, 13, 'Tikrai aš veltui apvaliau savo širdį ir ploviau savo rankas nekaltume.'),
  (@b19, 73, 14, 'Nes visą dieną buvau ištiktas rykšte ir baudžiamas kas rytą.'),
  (@b19, 73, 15, 'Jei sakyčiau: „Šitaip kalbėsiu“, štai nusikalsčiau tavo vaikų kartai.'),
  (@b19, 73, 16, 'Kai aš galvojau, kad tai suprasčiau, man buvo tai per sunku,'),
  (@b19, 73, 17, 'kol įėjau į Dievo šventovę; tada supratau jų baigtį.'),
  (@b19, 73, 18, 'Tikrai tu pastatei juos slidžiose vietose; tu juos nuvertei į pražūtį.'),
  (@b19, 73, 19, 'Kaip jie buvo nuniokoti, kaip akimirksniu! Jie visiškai praryti siaubų.'),
  (@b19, 73, 20, 'Kaip sapną atsibudus, taip tu, o Viešpatie, pabudęs paniekinsi jų atvaizdą.'),
  (@b19, 73, 21, 'Taip sielvartavo mano širdis, ir vėrė man inkstus.'),
  (@b19, 73, 22, 'Buvau toks kvailas ir neišmanėlis; buvau kaip gyvulys tavo akivaizdoje.'),
  (@b19, 73, 23, 'Tačiau aš nuolat esu su tavimi; tu palaikei mane už mano dešinės rankos.'),
  (@b19, 73, 24, 'Savo patarimu tu vesi mane, ir paskui priimsi mane į šlovę.'),
  (@b19, 73, 25, 'Ką turiu danguje, jei ne tave? Ir be tavęs nieko netrokštu žemėje.'),
  (@b19, 73, 26, 'Mano kūnas ir mano širdis senka; bet Dievas yra mano širdies stiprybė ir mano dalis per amžius.'),
  (@b19, 73, 27, 'Nes štai tie, kurie yra toli nuo tavęs, pražus; tu sunaikinai visus, kurie nueina nuo tavęs paleistuvaudami.'),
  (@b19, 73, 28, 'Bet man gera artėti prie Dievo; aš pasiklioviau Viešpačiu DIEVU, kad paskelbčiau visus tavo darbus.'),
  (@b19, 74, 1, 'Asafo maskylas. O Dieve, kodėl atstūmei mus amžiams? Kodėl tavo pyktis rūksta prieš tavo ganyklos avis?'),
  (@b19, 74, 2, 'Atsimink savo susirinkimą, kurį nusipirkęs esi nuo seno; savo paveldo lazdą, kurią atpirkai; šitą Siono kalną, kuriame gyvenai.'),
  (@b19, 74, 3, 'Pakelk savo kojas į amžinus griuvėsius, į visa, ką priešas nedorai padarė šventovėje.'),
  (@b19, 74, 4, 'Tavo priešai riaumoja tavo susirinkimų viduryje; jie pastatė savo vėliavas kaip ženklus.'),
  (@b19, 74, 5, 'Žmogus išgarsėjo pagal tai, kaip jis kilnojo kirvį prie tankių medžių.'),
  (@b19, 74, 6, 'Bet dabar jie vienu kartu kirviais ir kūjais sudaužė jos drožinius.'),
  (@b19, 74, 7, 'Jie mėtė ugnį į tavo šventovę, jie suteršė nuversdami tavo vardo buveinę žemėn.'),
  (@b19, 74, 8, 'Jie sakė savo širdyse: „Sunaikinkime juos kartu“; jie sudegino visas Dievo sinagogas šalyje.'),
  (@b19, 74, 9, 'Mes nematome savo ženklų; nebėra jokio pranašo; ir nėra tarp mūsų, kuris žinotų, kaip ilgai.'),
  (@b19, 74, 10, 'O Dieve, kaip ilgai priešininkas priekaištaus? Ar priešas amžinai piktžodžiaus tavo vardui?'),
  (@b19, 74, 11, 'Kodėl atitrauki savo ranką, tai yra, savo dešinę? Ištrauk ją sau iš užanties.'),
  (@b19, 74, 12, 'Nes Dievas yra mano Karalius nuo seno, vykdantis išgelbėjimą žemės viduryje.'),
  (@b19, 74, 13, 'Tu savo galybe padalinai jūrą; sudaužei vandenyse slibinams galvas.'),
  (@b19, 74, 14, 'Tu sutrupinai Leviatano galvas ir davei jį, kad būtų maistas dykumoje gyvenančiai liaudžiai.'),
  (@b19, 74, 15, 'Tu išskėlei šaltinį ir srovę; tu išdžiovinai galingas upes.'),
  (@b19, 74, 16, 'Tavo yra diena, naktis irgi tavo; tu paruošei šviesą ir saulę.'),
  (@b19, 74, 17, 'Tu nustatei visas žemės ribas; tu padarei vasarą ir žiemą.'),
  (@b19, 74, 18, 'Atsimink, o VIEŠPATIE, tai, kad priešas prikaišiojo, ir kad kvaili žmonės piktžodžiavo tavo vardui.'),
  (@b19, 74, 19, 'Neatiduok savo balandėlio sielos nedorėlių miniai; savo vargšų susirinkimo nepamiršk per amžius.'),
  (@b19, 74, 20, 'Atsižvelk į sandorą; nes tamsiosios žemės vietos yra pilnos žiaurumo buveinių.'),
  (@b19, 74, 21, 'Engiamasis tenesugrįžta sugėdintas; tegul vargšas ir stokojantis giria tavo vardą.'),
  (@b19, 74, 22, 'Pakilk, o Dieve, gink savo bylą; atsimink, kaip kvailys kas dieną tau prikaišioja.'),
  (@b19, 74, 23, 'Nepamiršk savo priešų balso; nuolat didėja triukšmas tų, kurie sukyla prieš tave.'),
  (@b19, 75, 1, 'Vyriausiajam muzikantui, Al-Tashitas. Asafo psalmė arba giesmė. Mes dėkojome tau, o Dieve, tau mes dėkojome; tavo nuostabius darbus skelbia, kadangi tavo vardas arti.'),
  (@b19, 75, 2, 'Kai priimsiu susirinkimą, aš tiesumu teisiu.'),
  (@b19, 75, 3, 'Žemė ir visi jos gyventojai ištirpo; aš laikau jos stulpus. Sela.'),
  (@b19, 75, 4, 'Aš sakiau kvailiams: ‘Nesielkite kvailai’; ir nedorėliams: ‘Nekelkite rago;'),
  (@b19, 75, 5, 'nekelkite savo rago į aukštį; nekalbėkite užkietėjusiu sprandu’.'),
  (@b19, 75, 6, 'Nes paaukštinimas neateina nei iš rytų, nei iš vakarų, nei iš pietų.'),
  (@b19, 75, 7, 'Bet Dievas yra teisėjas: jis vieną pažemina, o kitą išaukština.'),
  (@b19, 75, 8, 'Nes VIEŠPATIES rankoje yra taurė, ir vynas yra raudonas; ji yra pilna mišinių; ir jis pila iš jos; bet jos nuosėdas visi žemės nedorėliai turės išgręžti ir jas išgerti.'),
  (@b19, 75, 9, 'Bet aš skelbsiu per amžius; aš giedosiu gyrių Jokūbo Dievui.'),
  (@b19, 75, 10, 'Ir visus nedorėlių ragus aš nukaposiu; bet teisiųjų ragai bus išaukštinti.'),
  (@b19, 76, 1, 'Vyriausiajam muzikantui, Neginotu. Asafo psalmė arba giesmė. Judoje Dievas yra pažįstamas; jo vardas yra didis Izraelyje.'),
  (@b19, 76, 2, 'Taip pat Saleme yra jo padangtė, ir jo buveinė Sione.'),
  (@b19, 76, 3, 'Ten jis sulaužo lanko strėles, skydą, kalaviją ir mūšį. Sela.'),
  (@b19, 76, 4, 'Tu esi šlovingesnis ir puikesnis už grobio kalnus.'),
  (@b19, 76, 5, 'Drąsiaširdžiai apiplėšti, jie užmigo savo miegu; ir nei vienas galiūnas nerado savo rankos.'),
  (@b19, 76, 6, 'Nuo tavo barimo, o Jokūbo Dieve, tiek vežimas, tiek žirgas įmestas į mirtiną miegą.'),
  (@b19, 76, 7, 'Tavęs, būtent tavęs reikia bijoti; ir kas gali išsilaikyti tavo akivaizdoje, kai esi supykęs?'),
  (@b19, 76, 8, 'Iš dangaus tu davei išgirsti teismą; žemė bijojo ir tylėjo,'),
  (@b19, 76, 9, 'kai Dievas kėlėsi į teismą, visų žemės romiųjų gelbėti. Sela.'),
  (@b19, 76, 10, 'Tikrai žmogaus rūstybė girs tave; rūstybės likutį tu sulaikysi.'),
  (@b19, 76, 11, 'Darykite įžadus ir ištesėkite VIEŠPAČIUI, savo Dievui; visi aplink jį esantys teneša dovanas tam, kurio reikia bijoti.'),
  (@b19, 76, 12, 'Jis iškirs kunigaikščių dvasią; jis yra baisus žemės karaliams.'),
  (@b19, 77, 1, 'Vyriausiajam muzikantui. Jedutūnui. Asafo psalmė. Šaukiausi Dievo savo balsu, būtent Dievo savo balsu; ir jis pakreipė į mane ausį.'),
  (@b19, 77, 2, 'Savo bėdos dieną ieškojau Viešpaties; naktį nenustodama varvėjo mano žaizda; mano siela atsisakė būti guodžiama.'),
  (@b19, 77, 3, 'Aš atsiminiau Dievą ir buvau nerimastingas; aš skundžiausi, ir alpo mano dvasia. Sela.'),
  (@b19, 77, 4, 'Tu laikai budrias mano akis; aš taip sunerimęs, kad negaliu kalbėti.'),
  (@b19, 77, 5, 'Aš apgalvojau senas dienas, senovės laikų metus.'),
  (@b19, 77, 6, 'Naktį prisimenu savo giesmę; kalbuosi su savo širdimi; ir mano dvasia kruopščiai tyrinėjo.'),
  (@b19, 77, 7, 'Ar Viešpats atstums amžiams ir nebebus palankus?'),
  (@b19, 77, 8, 'Ar jo gailestingumas visiškai nustojo amžiams? Ar jo pažadas amžinai neišsipildys?'),
  (@b19, 77, 9, 'Ar Dievas pamiršo būti maloningas? Ar supykęs jis užgniaužė savo švelnius gailestingumus? Sela.'),
  (@b19, 77, 10, 'Ir aš sakiau: „Tai mano negalia; bet aš prisiminsiu Aukščiausiojo dešinės rankos metus“.'),
  (@b19, 77, 11, 'Aš atsiminsiu VIEŠPATIES darbus; tikrai atsiminsiu tavo senovės stebuklus.'),
  (@b19, 77, 12, 'Taip pat apmąstysiu visą tavo darbą ir kalbėsiu apie tavo veiksmus.'),
  (@b19, 77, 13, 'Tavo kelias, o Dieve, yra šventovėje; Kuris Dievas yra toks didis, kaip mūsų Dievas?'),
  (@b19, 77, 14, 'Tu esi Dievas, kuris daro stebuklus; tu apreiškei liaudyje savo galią.'),
  (@b19, 77, 15, 'Savo ranka tu atpirkai savo tautą, Jokūbo ir Juozapo sūnus. Sela.'),
  (@b19, 77, 16, 'Pamatė tave vandenys, o Dieve, pamatė tave vandenys; jie išsigando; taip pat gelmės sunerimo.'),
  (@b19, 77, 17, 'Debesys pylė vandenį; padangės skleidė garsą; tavo strėlės išlėkė.'),
  (@b19, 77, 18, 'Tavo griaustinio balsas buvo danguje; žaibai apšvietė pasaulį; drebėjo ir kratėsi žemė.'),
  (@b19, 77, 19, 'Tavo kelias jūroje, tavo takas didžiuose vandenyse ir tavo žingsniai nežinomi.'),
  (@b19, 77, 20, 'Tu vedei savo tautą kaip kaimenę Mozės ir Aarono ranka.'),
  (@b19, 78, 1, 'Asafo maskylas. Pakreipk ausį, o mano tauta, į mano įstatymą; palenkite savo ausis į mano burnos žodžius.'),
  (@b19, 78, 2, 'Aš praversiu savo burną palyginimu, ištarsiu paslaptingus senovės pasakymus,'),
  (@b19, 78, 3, 'kuriuos girdėjome ir žinojome, ir mūsų tėvai mums pasakojo.'),
  (@b19, 78, 4, 'Neslėpsime jų nuo jų vaikų, pasakodami ateinančiai kartai VIEŠPATIES gyrių, jo stiprybę ir jo nuostabius darbus, kuriuos jis padarė.'),
  (@b19, 78, 5, 'Nes jis įtvirtino liudijimą Jokūbe ir paskyrė Izraelyje įstatymą, kurį jis įsakė mūsų tėvams, kad jie duotų juos pažinti savo vaikams;'),
  (@b19, 78, 6, 'kad juos pažintų ateinanti karta – vaikai, kurie gims, kurie pakilę juos skelbtų savo vaikams,'),
  (@b19, 78, 7, 'kad jie sudėtų savo viltį į Dievą ir nepamirštų Dievo darbų, bet laikytųsi jo įsakymų;'),
  (@b19, 78, 8, 'ir nebūtų, kaip jų tėvai, užsispyrusi ir maištinga karta; karta, kuri nenukreipė savo širdies teisingai ir kurios dvasia nebuvo tvirta Dievui.'),
  (@b19, 78, 9, 'Efraimo vaikai, ginkluoti ir nešini lankais, gręžėsi atgal mūšio dieną.'),
  (@b19, 78, 10, 'Jie nesilaikė Dievo sandoros ir atsisakė vaikščioti jo įstatyme;'),
  (@b19, 78, 11, 'ir pamiršo jo darbus ir jo nuostabas, kuriuos jis jiems parodė.'),
  (@b19, 78, 12, 'Jų tėvams matant, jis padarė nuostabių dalykų Egipto šalyje, Coano lauke.'),
  (@b19, 78, 13, 'Jis padalino jūrą ir juos pervedė; ir pastatė vandenis kaip krūvą.'),
  (@b19, 78, 14, 'Taip pat jis vedė juos dieną debesimi, o visą naktį ugnies šviesa.'),
  (@b19, 78, 15, 'Jis perskėlė uolas dykumoje ir davė jiems gerti kaip iš didelių gelmių.'),
  (@b19, 78, 16, 'Taip pat jis išvedė sroves iš uolos ir privertė vandenis tekėti žemyn kaip upes.'),
  (@b19, 78, 17, 'O jie dar daugiau prieš jį nusidėjo, kurstydami Aukščiausiąjį dykumoje.'),
  (@b19, 78, 18, 'Jie gundė Dievą savo širdyje, reikalaudami maisto dėl savo geismo.'),
  (@b19, 78, 19, 'Taip, jie kalbėjo prieš Dievą; jie sakė: „Ar Dievas gali paruošti stalą dykumoje?'),
  (@b19, 78, 20, 'Štai jis smogė į uolą, jog ištryško vandenys, ir pasipylė srovės; ar jis gali ir duonos duoti? Ar jis gali parūpinti mėsos savo tautai?“'),
  (@b19, 78, 21, 'Todėl tai išgirdęs VIEŠPATS užsirūstino; taip ugnis užsidegė prieš Jokūbą, ir pyktis pakilo prieš Izraelį;'),
  (@b19, 78, 22, 'nes jie netikėjo Dievu ir nepasitikėjo jo išgelbėjimu;'),
  (@b19, 78, 23, 'nors jis įsakė debesims iš aukštai ir atidarė dangaus duris,'),
  (@b19, 78, 24, 'ir lijo ant jų maną valgymui, ir davė jiems dangaus javų.'),
  (@b19, 78, 25, 'Žmogus valgė angelų maistą; jis jiems siuntė maisto iki soties.'),
  (@b19, 78, 26, 'Jis privertė rytų vėją pūsti danguje; ir savo galia jis atvedė pietų vėją.'),
  (@b19, 78, 27, 'Taip pat jis lijo ant jų mėsą kaip dulkes ir sparnuotus skrajūnus kaip jūros smiltis;'),
  (@b19, 78, 28, 'ir jis leido jiems kristi į jų stovyklos vidurį, aplink jų buveines.'),
  (@b19, 78, 29, 'Taigi jie valgė ir labai pasisotino; nes jis jiems davė jų pačių troškimą;'),
  (@b19, 78, 30, 'jie nebuvo atsitolinę nuo savo geidulio. Bet kai jų valgis tebebuvo jų burnose,'),
  (@b19, 78, 31, 'Dievo rūstybė atėjo ant jų ir išžudė jų riebiausius, ir parkniubdė Izraelio išrinktuosius.'),
  (@b19, 78, 32, 'Dėl viso to jie vis dar nuodėmiavo ir netikėjo dėl jo nuostabių darbų.'),
  (@b19, 78, 33, 'Todėl jis pražudė jų dienas tuštybėje ir jų metus neramumuose.'),
  (@b19, 78, 34, 'Kai jis juos žudė, tada jie jo ieškojo; ir jie sugrįžo, ir anksti teiravosi Dievo.'),
  (@b19, 78, 35, 'Ir jie atsiminė, kad Dievas yra jų uola ir aukščiausiasis Dievas jų atpirkėjas.'),
  (@b19, 78, 36, 'Tačiau jie pataikavo jam savo burna ir savo liežuviais jam melavo.'),
  (@b19, 78, 37, 'Nes jų širdis nebuvo teisi prieš jį, ir jie nebuvo tvirti jo sandoroje.'),
  (@b19, 78, 38, 'Bet jis, būdamas kupinas gailestingumo, atleido jų neteisybę ir jų nesunaikino; taip, daugelį kartų jis nukreipė savo pyktį ir nežadino visos savo rūstybės.'),
  (@b19, 78, 39, 'Nes jis atsiminė, kad jie tėra kūnas; vėjas, kuris nueina ir nebegrįžta.'),
  (@b19, 78, 40, 'Kaip dažnai jie kurstė jį tyruose ir liūdino jį dykumoje!'),
  (@b19, 78, 41, 'Taip, jie atsigręžė ir gundė Dievą, ir apribojo Izraelio Šventąjį.'),
  (@b19, 78, 42, 'Jie neatsiminė jo rankos nei tos dienos, kai jis juos išvadavo iš priešo.'),
  (@b19, 78, 43, 'Kaip jis darė Egipte savo ženklus ir savo nuostabas Coano lauke'),
  (@b19, 78, 44, 'ir pavertė į kraują jų upes ir jų sroves, kad jie negalėtų gerti.'),
  (@b19, 78, 45, 'Jis siuntė tarp jų įvairios rūšies muses, kurios juos ėdė; ir varles, kurios juos naikino.'),
  (@b19, 78, 46, 'Taip pat jis davė jų prieaugį vikšrui, ir jų triūsą skėriui.'),
  (@b19, 78, 47, 'Jis išnaikino jų vynmedžius kruša ir jų sikomorus – šalna.'),
  (@b19, 78, 48, 'Jis atidavė krušai jų galvijus ir jų kaimenes ugningiems žaibams.'),
  (@b19, 78, 49, 'Jis metė ant jų savo nuožmų pyktį, rūstybę, pasipiktinimą ir bėdą, siųsdamas piktus angelus tarp jų.'),
  (@b19, 78, 50, 'Jis padarė kelią savo pykčiui; jis nesaugojo jų sielos nuo mirties, bet jų gyvybę atidavė marui;'),
  (@b19, 78, 51, 'ir išmušė visus pirmagimius Egipte; jų stiprybės pradžią Chamo padangtėse;'),
  (@b19, 78, 52, 'bet išvedė savo tautą kaip avis, ir juos vedė dykumoje kaip kaimenę.'),
  (@b19, 78, 53, 'Jis saugiai juos vedė, jog jie nebijojo; bet jų priešus jūra apdengė.'),
  (@b19, 78, 54, 'Ir jis juos nuvedė prie savo šventovės ribų – prie šito kalno, kurį buvo įsigijusi jo dešinė.'),
  (@b19, 78, 55, 'Taip pat jis išvarė jų akivaizdoje pagonis ir virve jiems padalino paveldą, ir Izraelio gentis apgyvendino jų palapinėse.'),
  (@b19, 78, 56, 'Tačiau jie gundė ir kurstė aukščiausiąjį Dievą ir nesilaikė jo liudijimų,'),
  (@b19, 78, 57, 'bet gręžėsi atgal ir elgėsi neištikimai kaip jų tėvai; jie nukrypo į šalį kaip apgaulingas lankas.'),
  (@b19, 78, 58, 'Nes jie kurstė jo pyktį savo aukštumomis ir savo raižytais atvaizdais sukėlė jam pavydą.'),
  (@b19, 78, 59, 'Dievas tai išgirdęs užsirūstino ir labai pasibjaurėjo Izraeliu;'),
  (@b19, 78, 60, 'taip, kad jis paliko Šilojaus padangtę, palapinę, kurią jis buvo padėjęs tarp žmonių;'),
  (@b19, 78, 61, 'ir atidavė savo stiprybę į nelaisvę ir savo šlovę į priešo ranką.'),
  (@b19, 78, 62, 'Jis perdavė savo tautą kalavijui; ir užsirūstino ant savo paveldo.'),
  (@b19, 78, 63, 'Jų jaunuolius rijo ugnis, o jų mergaitės liko netekėjusios.'),
  (@b19, 78, 64, 'Jų kunigai krito nuo kalavijo, o jų našlės neapraudojo.'),
  (@b19, 78, 65, 'Tada Viešpats pabudo kaip žmogus iš miego ir kaip galiūnas, šūkaujantis nuo vyno.'),
  (@b19, 78, 66, 'Ir jis mušė savo priešus užnugaryje; amžinam priekaištui juos perdavė.'),
  (@b19, 78, 67, 'Jis dar atmetė Juozapo padangtę ir neišsirinko Efraimo genties;'),
  (@b19, 78, 68, 'bet išsirinko Judos gentį, Siono kalną, kurį pamilo.'),
  (@b19, 78, 69, 'Ir jis pastatė savo šventovę kaip aukštus rūmus, kaip žemę, kurią jis įtvirtino amžiams.'),
  (@b19, 78, 70, 'Taip pat jis išsirinko Dovydą, savo tarną, ir jį paėmė nuo avių gardų,'),
  (@b19, 78, 71, 'nuo sekimo paskui avis su jaunikliais jis atvedė jį, kad ganytų jo tautą Jokūbą ir Izraelį, jo paveldą.'),
  (@b19, 78, 72, 'Taigi jis juos ganė pagal savo širdies dorumą; ir savo sumaniomis rankomis juos vedė.'),
  (@b19, 79, 1, 'Asafo psalmė. O Dieve, pagonys atėjo į tavo paveldą; jie suteršė tavo šventąją šventyklą; jie pavertė Jeruzalę krūvomis.'),
  (@b19, 79, 2, 'Jie atidavė tavo tarnų lavonus dangaus skrajūnams maistui, tavo šventųjų kūnus žemės žvėrims.'),
  (@b19, 79, 3, 'Jie išliejo jų kraują kaip vandenį aplink Jeruzalę; ir nebuvo kas juos palaidotų.'),
  (@b19, 79, 4, 'Mes tapome priekaištu savo kaimynams, panieka ir pajuoka, esantiems aplinkui.'),
  (@b19, 79, 5, 'Kaip ilgai, VIEŠPATIE? Ar amžinai pyksi? Ar kaip ugnis degs tavo pavydas?'),
  (@b19, 79, 6, 'Išliek savo rūstybę ant pagonių, kurie tavęs nėra pažinę, ir ant karalysčių, kurios nesišaukė tavo vardo.'),
  (@b19, 79, 7, 'Nes jos surijo Jokūbą ir jo gyvenvietę nusiaubė.'),
  (@b19, 79, 8, 'Neprisimink iš priešiškumo mums ankstesniųjų neteisybių; skubiai aplenkę tepasitinka mus tavo švelnūs gailestingumai; nes mes esame labai pažeminti.'),
  (@b19, 79, 9, 'Padėk mums, o mūsų išgelbėjimo Dieve, dėl savo vardo šlovės; mus išvaduok ir nuvalyk mūsų nuodėmes dėl savo vardo.'),
  (@b19, 79, 10, 'Kodėl pagonys turėtų sakyti: „Kur yra jų Dievas?“ Tegul mums matant jis tampa žinomas tarp pagonių, atkeršijant už pralietą tavo tarnų kraują.'),
  (@b19, 79, 11, 'Teateina tavo akivaizdon belaisvio dūsavimas; pagal savo jėgos didybę išsaugok tuos, kurie yra paskirti mirti;'),
  (@b19, 79, 12, 'ir septyneriopai atmokėk mūsų kaimynams į jų užantį jų priekaištavimą, kuriuo jie tau prikaišiojo, o Viešpatie.'),
  (@b19, 79, 13, 'Taigi mes, tavo tauta ir tavo ganyklos avys, amžinai tau dėkosime; kartų kartoms skelbsime tavo gyrių.'),
  (@b19, 80, 1, 'Vyriausiajam muzikantui, Šošanim-Edutu. Asafo psalmė. O Izraelio Ganytojau, pakreipk ausį tu, kuris vedi Juozapą kaip kaimenę; tu, kuris gyveni tarp kerubų, suspindėk.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 80, 2, 'Ties Efraimu, Benjaminu ir Manasu pažadink savo jėgą, ateik ir išgelbėk mus.'),
  (@b19, 80, 3, 'O Dieve, atgręžk mus ir šviesk savo veidu; ir mes būsime išgelbėti.'),
  (@b19, 80, 4, 'O VIEŠPATIE, kariuomenių Dieve, kaip ilgai tu pyksi ant savo tautos maldos?'),
  (@b19, 80, 5, 'Tu juos maitini ašarų duona; ir duodi jiems gerti ašaras dideliu saiku.'),
  (@b19, 80, 6, 'Tu mus padarei ginču mūsų kaimynams; ir mūsų priešai tarpusavyje kvatoja.'),
  (@b19, 80, 7, 'O kariuomenių Dieve, atgręžk mus ir šviesk savo veidu; ir mes būsime išgelbėti.'),
  (@b19, 80, 8, 'Tu vynmedį nešei iš Egipto; tu išvarei pagonis ir jį pasodinai.'),
  (@b19, 80, 9, 'Tu pirma jo paruošei vietą ir davei jam giliai suleisti šaknis, ir jis pripildė šalį.'),
  (@b19, 80, 10, 'Kalvos buvo apdengtos jo šešėliu, ir jo šakos buvo kaip gražūs kedrai.'),
  (@b19, 80, 11, 'Jis išleido savo šakas ligi jūros ir savo atžalas iki upės.'),
  (@b19, 80, 12, 'Tai kodėl nugriovei jo tvoras taip, kad jį skabytų visi, kurie praeina keliu?'),
  (@b19, 80, 13, 'Šernas iš miško jį niokoja, ir laukinis laukų žvėris jį ėda.'),
  (@b19, 80, 14, 'O kariuomenių Dieve, meldžiame tave, sugrįžk; pažvelk iš dangaus ir pamatyk, ir aplankyk šitą vynmedį;'),
  (@b19, 80, 15, 'ir tą vynuogyną, kurį pasodino tavo dešinė, ir atžalą, kurią sustiprinai dėl savęs.'),
  (@b19, 80, 16, 'Jis sudegintas ugnimi, nukirstas; jie žūna nuo tavo veido barimo.'),
  (@b19, 80, 17, 'Tebūna tavo ranka ant tavo dešinės žmogaus, ant žmogaus sūnaus, kurį sustiprinai dėl savęs.'),
  (@b19, 80, 18, 'Tai mes neatsitrauksime nuo tavęs; atgaivink mus, ir mes šauksimės tavo vardo.'),
  (@b19, 80, 19, 'O VIEŠPATIE, kariuomenių Dieve, atgręžk mus, šviesk savo veidu, ir mes būsime išgelbėti.'),
  (@b19, 81, 1, 'Vyriausiajam muzikantui, gitietišku. Asafo psalmė. Garsiai giedokite Dievui, mūsų stiprybei; kelkite džiaugsmingą triukšmą Jokūbo Dievui.'),
  (@b19, 81, 2, 'Imkite psalmę ir atneškite tambūriną, malonią arfą su psalteriu.'),
  (@b19, 81, 3, 'Pūskite trimitą per jauną mėnulį, skirtu laiku, mūsų iškilmingos šventės dieną.'),
  (@b19, 81, 4, 'Nes tai įstatas Izraeliui ir Jokūbo Dievo įstatymas.'),
  (@b19, 81, 5, 'Jis tai nustatė Juozape dėl liudijimo, kai jis išėjo per Egipto šalį; kur aš išgirdau nesuprantamą kalbą.'),
  (@b19, 81, 6, '„Aš patraukiau jo petį nuo naštos; jo rankos buvo išlaisvintos nuo puodų.'),
  (@b19, 81, 7, 'Tu šaukeisi bėdoje, ir aš tave išvadavau; tau atsakiau griaustinio slėptuvėje; tave mėginau prie Meribos vandenų. Sela.'),
  (@b19, 81, 8, 'Klausyk, o mano tauta, ir aš tau liudysiu; o Izraeli, jei manęs paklausysi;'),
  (@b19, 81, 9, 'nebus tavyje svetimo dievo; nei negarbinsi jokio svetimo dievo.'),
  (@b19, 81, 10, 'Aš esu VIEŠPATS, tavo Dievas, kuris tave išvedžiau iš Egipto šalies; plačiai atverk savo burną, ir aš ją pripildysiu.'),
  (@b19, 81, 11, 'Bet mano tauta nenorėjo klausyti mano balso; Izraelis nenorėjo manęs.'),
  (@b19, 81, 12, 'Tad aš atidaviau juos jų širdžių geismams; ir jie vaikščiojo pagal savo sumanymus.'),
  (@b19, 81, 13, 'O, kad mano tauta manęs klausytų ir kad Izraelis vaikščiotų mano keliais!'),
  (@b19, 81, 14, 'Aš greit pavergčiau jų priešus ir nukreipčiau savo ranką prieš jų priešininkus.'),
  (@b19, 81, 15, 'Nekenčiantys VIEŠPATIES jam nusilenktų; bet jų laikas truktų amžinai.'),
  (@b19, 81, 16, 'Jis maitintų juos geriausiais kviečiais; ir medumi iš uolos tave pasotinčiau“.'),
  (@b19, 82, 1, 'Asafo psalmė. Dievas stovi galingųjų susirinkime; tarp dievų jis teisia:'),
  (@b19, 82, 2, 'Kaip ilgai teisite neteisingai ir būsite palankūs nedorėlio asmenybei? Sela.'),
  (@b19, 82, 3, 'Ginkite vargšą ir našlaitį; vykdykite teisingumą kamuojamam ir nepasiturinčiam.'),
  (@b19, 82, 4, 'Išvaduokite vargšus ir nepasiturinčius; iš nedorėlių rankos juos išplėškite.'),
  (@b19, 82, 5, 'Jie nežino ir nenori suprasti; jie vis vaikšto tamsoje; visi žemės pamatai išėję iš vietos.'),
  (@b19, 82, 6, 'Aš tariau: „Jūs esate dievai; ir visi esate Aukščiausiojo vaikai.'),
  (@b19, 82, 7, 'Tačiau jūs mirsite kaip žmonės ir krisite kaip vienas iš kunigaikščių“.'),
  (@b19, 82, 8, 'Pakilk, o Dieve, teisk žemę; nes tu paveldėsi visas tautas.'),
  (@b19, 83, 1, 'Asafo giesmė arba psalmė. O Dieve, netylėk; o Dieve, netylėk ir nebūk ramus.'),
  (@b19, 83, 2, 'Nes štai tavo priešai triukšmauja; ir tie, kurie tavęs nekenčia, pakėlė galvą.'),
  (@b19, 83, 3, 'Prieš tavo tautą jie surengė klastingą pasitarimą ir tarėsi prieš tavo paslėptuosius.'),
  (@b19, 83, 4, 'Jie sakė: „Eime, iškirskime juos, kad jie nebebūtų tauta; kad Izraelio vardo nebeprisimintų“.'),
  (@b19, 83, 5, 'Nes jie vieningai susitarė; jie prieš tave sudarė sąjungą;'),
  (@b19, 83, 6, 'Edomo padangtės ir išmaelitai, Moabo ir hagarai;'),
  (@b19, 83, 7, 'Gebalas, Amonas ir Amalekas; filistinai su Tyro gyventojais;'),
  (@b19, 83, 8, 'taip pat Ašūras prisijungė prie jų; jie padėjo Loto vaikams. Sela.'),
  (@b19, 83, 9, 'Padaryk jiems kaip midjaniečiams; kaip Siserai, kaip Jabinui prie Kisono upelio;'),
  (@b19, 83, 10, 'kurie žuvo prie En-Doro; jie tapo kaip mėšlas žemei.'),
  (@b19, 83, 11, 'Padaryk jų kilminguosius kaip Orebą ir Zeebą; taip, visus jų kunigaikščius kaip Zebachą bei Calmuną;'),
  (@b19, 83, 12, 'kurie sakė: „Imkime Dievo namus sau nuosavybėn“.'),
  (@b19, 83, 13, 'O mano Dieve, padaryk juos kaip ratą; kaip ražieną prieš vėją.'),
  (@b19, 83, 14, 'Kaip ugnis sudegina mišką, ir kaip liepsna padega kalnus,'),
  (@b19, 83, 15, 'taip persekiok juos savo audra ir gąsdink juos savo vėtra.'),
  (@b19, 83, 16, 'Pripildyk jų veidus gėdos; kad jie ieškotų tavo vardo, o VIEŠPATIE.'),
  (@b19, 83, 17, 'Tebūna jie suglumę ir tenerimauja per amžius; taip, tebūna jie sugėdinti ir tepražūna;'),
  (@b19, 83, 18, 'kad žmonės žinotų, jog tu, kurio vienintelio vardas JEHOVA, esi aukščiausiasis visai žemei.'),
  (@b19, 84, 1, 'Vyriausiajam muzikantui, gitietišku. Psalmė Koracho sūnums. Kokios mielos tavo padangtės, o kariuomenių VIEŠPATIE!'),
  (@b19, 84, 2, 'Mano siela ilgisi, taip, alpsta VIEŠPATIES kiemų; mano širdis ir mano kūnas šaukiasi gyvojo Dievo.'),
  (@b19, 84, 3, 'Taip, žvirblis rado namus ir kregždė sau lizdą, kur ji galėtų sudėti savo jauniklius, tai yra tavo aukurus, o kariuomenių VIEŠPATIE, mano Karaliau ir mano Dieve.'),
  (@b19, 84, 4, 'Palaiminti, kurie gyvena tavo namuose: jie nuolat girs tave. Sela.'),
  (@b19, 84, 5, 'Palaimintas žmogus, kurio stiprybė yra tavyje; kurių širdyje yra jų keliai;'),
  (@b19, 84, 6, 'kurie eidami per Bachos slėnį padaro jį šaltiniu; taip pat lietus pripildo tvenkinius.'),
  (@b19, 84, 7, 'Jie eina iš stiprybės į stiprybę, kiekvienas iš jų pasirodo Dievo akivaizdoje Sione.'),
  (@b19, 84, 8, 'O VIEŠPATIE, kariuomenių Dieve, išgirsk mano maldą; pakreipk ausį, o Jokūbo Dieve. Sela.'),
  (@b19, 84, 9, 'Pamatyk, o Dieve, mūsų skyde, ir pažvelk į savo pateptojo veidą.'),
  (@b19, 84, 10, 'Nes viena diena tavo kiemuose yra geresnė už tūkstantį. Verčiau būsiu durininkas savo Dievo namuose, negu gyvensiu nedorybės palapinėse.'),
  (@b19, 84, 11, 'Nes VIEŠPATS Dievas yra saulė ir skydas; VIEŠPATS duos malonę ir šlovę; joks geras dalykas nebus sulaikytas nuo tų, kurie vaikšto tiesiai.'),
  (@b19, 84, 12, 'O kariuomenių VIEŠPATIE, palaimintas žmogus, kuris pasitiki tavimi.'),
  (@b19, 85, 1, 'Vyriausiajam muzikantui. Psalmė Koracho sūnums. Tu, VIEŠPATIE, buvai palankus savo šaliai; tu sugrąžinai Jokūbo nelaisvę.'),
  (@b19, 85, 2, 'Tu atleidai savo tautos neteisybę, uždengei visą jų nuodėmę. Sela.'),
  (@b19, 85, 3, 'Tu atitraukei visą savo rūstybę; tu nusigręžei nuo savo pykčio įniršio.'),
  (@b19, 85, 4, 'Atgręžk mus, o mūsų išgelbėjimo Dieve, ir paliauk mums savo pyktį.'),
  (@b19, 85, 5, 'Ar amžinai pyksi ant mūsų? Ar pratęsi savo pyktį kartų kartoms?'),
  (@b19, 85, 6, 'Argi vėl mūsų neatgaivinsi; kad tavo tauta džiaugtųsi tavimi?'),
  (@b19, 85, 7, 'Parodyk mums, o VIEŠPATIE, savo gailestingumą ir suteik mums savo išgelbėjimą.'),
  (@b19, 85, 8, 'Aš klausysiuos, ką VIEŠPATS Dievas kalbės; nes jis kalbės taiką savo tautai ir savo šventiesiems; bet jie tegul nesugrįžta į kvailystę.'),
  (@b19, 85, 9, 'Tikrai jo išgelbėjimas yra arti tiems, kurie jo bijo; kad šlovė gyventų mūsų šalyje.'),
  (@b19, 85, 10, 'Gailestingumas ir tiesa susitiko; teisumas ir taika pasibučiavo.'),
  (@b19, 85, 11, 'Tiesa žels iš žemės; ir teisumas žvelgs žemyn iš dangaus.'),
  (@b19, 85, 12, 'Taip, VIEŠPATS duos tai, kas gera; ir mūsų šalis duos savo prieaugį.'),
  (@b19, 85, 13, 'Teisumas eis pirma jo ir pastatys mus į jo žingsnių kelią.'),
  (@b19, 86, 1, 'Dovydo malda. Palenk, o VIEŠPATIE, savo ausį, išklausyk mane; nes aš esu vargšas ir stokojantis.'),
  (@b19, 86, 2, 'Apsaugok mano sielą; nes aš esu šventas; o mano Dieve, gelbėk savo tarną, kuris pasitiki tavimi.'),
  (@b19, 86, 3, 'Būk man gailestingas, o Viešpatie; nes kas dieną tavęs šaukiuosi.'),
  (@b19, 86, 4, 'Pralinksmink savo tarno sielą; nes į tave, o Viešpatie, keliu savo sielą.'),
  (@b19, 86, 5, 'Nes tu, Viešpatie, esi geras ir pasiruošęs atleisti; ir kupinas gailestingumo visiems tiems, kurie tavęs šaukiasi.'),
  (@b19, 86, 6, 'Pakreipk ausį, o VIEŠPATIE, į mano maldą; ir atsižvelk į mano prašymų balsą.'),
  (@b19, 86, 7, 'Savo bėdos dieną šauksiuos tavęs; nes tu man atsakysi.'),
  (@b19, 86, 8, 'Nėra tau lygaus tarp dievų, o Viešpatie; ir nėra tokių darbų, kaip tavo darbai.'),
  (@b19, 86, 9, 'Visos tautos, kurias tu padarei, ateis ir garbins priešais tave, o Viešpatie; ir šlovins tavo vardą.'),
  (@b19, 86, 10, 'Nes tu esi didis ir darai stebuklingus dalykus; tu vienas esi Dievas.'),
  (@b19, 86, 11, 'Pamokyk mane, o VIEŠPATIE, savo kelio; aš vaikščiosiu tavo tiesoje; suvienyk mano širdį, kad bijotų tavo vardo.'),
  (@b19, 86, 12, 'Girsiu tave, o Viešpatie, mano Dieve, visa širdimi; ir amžinai šlovinsiu tavo vardą.'),
  (@b19, 86, 13, 'Nes tavo gailestingumas man yra didelis; ir tu išgelbėjai mano sielą iš žemiausio pragaro.'),
  (@b19, 86, 14, 'O Dieve, išdidieji sukilo prieš mane, ir smurtininkų sambūriai ieškojo mano sielos, ir tavęs nestatė prieš save.'),
  (@b19, 86, 15, 'Bet tu, o Viešpatie, esi Dievas, pilnas užuojautos ir maloningas, ilgai pakantus ir kupinas gailestingumo bei tiesos.'),
  (@b19, 86, 16, 'Gręžkis į mane ir būk man gailestingas; duok savo stiprybės savo tarnui ir išgelbėk savo tarnaitės sūnų.'),
  (@b19, 86, 17, 'Parodyk man ženklą dėl gero; kad tie, kurie manęs nekenčia, tai matytų ir susigėstų; nes tu, VIEŠPATIE, esi man padėjęs ir mane paguodęs.'),
  (@b19, 87, 1, 'Psalmė arba giesmė Koracho sūnums. Jo pamatas yra šventuose kalnuose.'),
  (@b19, 87, 2, 'VIEŠPATS myli Siono vartus labiau už visas Jokūbo buveines.'),
  (@b19, 87, 3, 'Šlovingi dalykai kalbami apie tave, o Dievo mieste. Sela.'),
  (@b19, 87, 4, 'Aš minėsiu apie Rahabą ir Babiloną tiems, kurie mane pažįsta; štai Filistija ir Tyras su Etiopija; šitas buvo ten gimęs.'),
  (@b19, 87, 5, 'O apie Sioną bus sakoma: „Tas ir anas žmogus buvo jame gimęs; ir pats aukščiausiasis jį įtvirtins“.'),
  (@b19, 87, 6, 'VIEŠPATS skaičiuos surašydamas tautą, kad šitas buvo ten gimęs. Sela.'),
  (@b19, 87, 7, 'Ten bus ir giedotojai, ir grojantys instrumentais; visos mano versmės yra tavyje.'),
  (@b19, 88, 1, 'Giesmė arba psalmė Koracho sūnums. Vyriausiajam muzikantui. Machalat leanotu. Ezracho Hemano maskylas. O VIEŠPATIE, mano išgelbėjimo Dieve, dieną ir naktį šaukiausi tavo akivaizdoje;'),
  (@b19, 88, 2, 'tegul mano malda ateina tavo akivaizdon; palenk savo ausį mano šauksmui;'),
  (@b19, 88, 3, 'nes mano siela pilna vargų; ir mano gyvybė artėja prie kapo.'),
  (@b19, 88, 4, 'Aš priskaičiuotas prie nužengiančių į duobę; aš kaip bejėgis žmogus;'),
  (@b19, 88, 5, 'laisvas tarp mirusiųjų, kaip užmuštieji, kurie guli kape, kurių tu nebeatsimeni; jie nuo tavo rankos atkirsti.'),
  (@b19, 88, 6, 'Tu paguldei mane į žemiausią duobę, į tamsą, į gelmes.'),
  (@b19, 88, 7, 'Mane sunkiai užgulusi tavo rūstybė, ir mane kamavai visomis savo bangomis. Sela.'),
  (@b19, 88, 8, 'Tu atitolinai nuo manęs mano pažįstamus; mane padarei jiems bjaurastimi; esu uždarytas ir negaliu išeiti.'),
  (@b19, 88, 9, 'Mano akis gedi dėl sielvarto; kasdien šaukiausi tavęs, VIEŠPATIE, ištiesiau į tave savo rankas.'),
  (@b19, 88, 10, 'Ar tu parodysi stebuklus mirusiesiems? Ar mirusieji kelsis ir girs tave? Sela.'),
  (@b19, 88, 11, 'Ar tavo mylintis gerumas bus skelbiamas kape arba tavo ištikimybė – pražūtyje?'),
  (@b19, 88, 12, 'Ar bus žinomi tavo stebuklai tamsoje ir tavo teisumas užmiršimo šalyje?'),
  (@b19, 88, 13, 'Bet aš tavęs, o VIEŠPATIE, šaukiausi; ir ryte mano malda tave aplenkusi pasitiks.'),
  (@b19, 88, 14, 'Kodėl tu, VIEŠPATIE, atstumi mano sielą? Kodėl slepi nuo manęs savo veidą?'),
  (@b19, 88, 15, 'Aš kamuojamas ir esu pasiruošęs mirti nuo pat jaunystės; kentėdamas tavo siaubus esu suglumintas.'),
  (@b19, 88, 16, 'Per mane eina tavo įnirtinga rūstybė; tavo siaubai atkirto mane.'),
  (@b19, 88, 17, 'Jie kas dieną ėjo aplink mane kaip vanduo; jie kartu apsupo mane.'),
  (@b19, 88, 18, 'Tu atitolinai nuo manęs mylėtoją ir draugą, ir mano pažįstamus į tamsą.'),
  (@b19, 89, 1, 'Ezracho Etano maskylas. Amžinai giedosiu apie VIEŠPATIES gailestingumus; kartų kartoms savo burna skelbsiu tavo ištikimybę.'),
  (@b19, 89, 2, 'Nes aš sakiau: „Gailestingumas bus pastatytas per amžius; tu įtvirtinsi savo ištikimybę pačiuose danguose“.'),
  (@b19, 89, 3, '„Aš sudariau sandorą su savo išrinktuoju, aš prisiekiau Dovydui, savo tarnui:'),
  (@b19, 89, 4, '‘Per amžius įtvirtinsiu tavo sėklą ir kartų kartoms tavo sostą pastatysiu’“. Sela.'),
  (@b19, 89, 5, 'Dangūs girs tavo stebuklus, o VIEŠPATIE; ir tavo ištikimybę šventųjų susirinkime.'),
  (@b19, 89, 6, 'Nes kas danguje gali būti prilygintas VIEŠPAČIUI? Kas tarp galingojo sūnų gali prilygti VIEŠPAČIUI?'),
  (@b19, 89, 7, 'Dievas turi būti labai bijotinas šventųjų sueigoje ir būti gerbtinas visų aplink jį esančių.'),
  (@b19, 89, 8, 'O VIEŠPATIE, kariuomenių Dieve, kas yra stiprus VIEŠPATS, lygus tau ar tavo ištikimybei aplink tave?'),
  (@b19, 89, 9, 'Tu valdai jūros šėlimą; kai sukyla jos bangos, tu jas nuramini.'),
  (@b19, 89, 10, 'Tu sutriuškinai Rahabą kaip nužudytąjį; savo galinga ranka išsklaidei savo priešus.'),
  (@b19, 89, 11, 'Tavo yra dangūs, žemė irgi tavo; o pasaulis ir jo pilnumas, tu padėjai jiems pamatą.'),
  (@b19, 89, 12, 'Šiaurė ir pietūs – tu juos sutvėrei; Taboras ir Hermonas džiaugsis tavo vardu.'),
  (@b19, 89, 13, 'Tu turi galingą ranką; stipri tavo ranka ir aukšta yra tavo dešinė.'),
  (@b19, 89, 14, 'Teisingumas ir teismas yra tavo sosto buveinė; gailestingumas ir tiesa eis priekyje tavo veido.'),
  (@b19, 89, 15, 'Palaiminta tauta, kuri pažįsta džiaugsmingą garsą; o VIEŠPATIE, jie vaikščios tavo veido šviesoje.'),
  (@b19, 89, 16, 'Tavo vardu jie džiaugsis visą dieną; ir jie bus išaukštinti tavo teisumu.'),
  (@b19, 89, 17, 'Nes tu esi jų stiprybės šlovė; ir tavo palankumu bus išaukštintas mūsų ragas.'),
  (@b19, 89, 18, 'Nes VIEŠPATS yra mūsų apsauga; ir Izraelio Šventasis – mūsų karalius.'),
  (@b19, 89, 19, 'Tada tu regėjime kalbėjai savo šventajam ir pasakei: „Aš suteikiau pagalbą galingajam; aš išaukštinau išrinktąjį iš tautos.'),
  (@b19, 89, 20, 'Suradau Dovydą, savo tarną; savo šventu aliejumi jį patepiau;'),
  (@b19, 89, 21, 'mano ranka bus įtvirtinta su juo; taip pat mano ranka jį stiprins.'),
  (@b19, 89, 22, 'Priešas iš jo neišieškos; nei nedorybės sūnus jo nekamuos.'),
  (@b19, 89, 23, 'Aš sumušiu jo akivaizdoje jo priešininkus ir ištiksiu rykšte tuos, kurie jo nekenčia.'),
  (@b19, 89, 24, 'Bet mano ištikimybė ir mano gailestingumas bus su juo; ir mano vardu bus išaukštintas jo ragas.'),
  (@b19, 89, 25, 'Aš padėsiu ant jūros jo ranką ir ant upių jo dešinę.'),
  (@b19, 89, 26, 'Jis manęs šauksis: ‘Tu esi mano tėvas, mano Dievas ir mano išgelbėjimo uola!’'),
  (@b19, 89, 27, 'Taip pat aš jį padarysiu savo pirmagimiu, aukštesniu už žemės karalius.'),
  (@b19, 89, 28, 'Per amžius jam išlaikysiu savo gailestingumą, ir mano sandora su juo tvirtai stovės.'),
  (@b19, 89, 29, 'Taip pat padarysiu, kad jo sėkla išliks amžinai ir jo sostas kaip dangaus dienos.'),
  (@b19, 89, 30, 'Jei jo vaikai paliks mano įstatymą ir nevaikščios pagal mano teismus,'),
  (@b19, 89, 31, 'jei jie laužys mano įstatus ir nesilaikys mano įsakymų,'),
  (@b19, 89, 32, 'tada aš aplankysiu jų nusižengimą su lazda ir jų neteisybę kirčiais.'),
  (@b19, 89, 33, 'Tačiau savo mylinčio gerumo aš iš jo visiškai neatimsiu ir nesulaužysiu savo ištikimybės.'),
  (@b19, 89, 34, 'Aš nesulaužysiu savo sandoros ir nekeisiu to, kas išėjo iš mano lūpų.'),
  (@b19, 89, 35, 'Kartą prisiekiau savo šventumu, kad Dovydui nemeluosiu.'),
  (@b19, 89, 36, 'Jo sėkla išliks per amžius, ir jo sostas – kaip saulė priešais mane.'),
  (@b19, 89, 37, 'Tai bus įtvirtinta per amžius kaip mėnulis ir kaip ištikimas liudytojas danguje“. Sela.'),
  (@b19, 89, 38, 'Bet tu atstūmei ir bjaurėjaisi, tu užsirūstinai ant savo pateptojo.'),
  (@b19, 89, 39, 'Tu panaikinai savo tarno sandorą; suteršei jo karūną, nusviedęs ją žemėn.'),
  (@b19, 89, 40, 'Tu sugriovei visas jo tvoras; pavertei griuvėsiais jo tvirtoves.'),
  (@b19, 89, 41, 'Jį plėšia visi praeinantys keliu; jis yra priekaištas savo kaimynams.'),
  (@b19, 89, 42, 'Tu pakėlei jo priešininkų dešinę; tu padarei, kad visi jo priešai džiaugtųsi.'),
  (@b19, 89, 43, 'Taip pat tu nukreipei jo kalavijo ašmenis ir neparėmei jo mūšyje.'),
  (@b19, 89, 44, 'Tu padarei, kad užsibaigtų jo šlovė, ir jo sostą nuvertei ant žemės.'),
  (@b19, 89, 45, 'Tu sutrumpinai jo jaunystės dienas; apdengei jį gėda. Sela.'),
  (@b19, 89, 46, 'Kaip ilgai, VIEŠPATIE? Ar slėpsiesi amžinai? Ar degs kaip ugnis tavo rūstybė?'),
  (@b19, 89, 47, 'Atsimink, koks trumpas yra mano laikas; kodėl tuščiai padarei visus žmones?'),
  (@b19, 89, 48, 'Koks žmogus gyvena ir nemato mirties? Ar jis išgelbės savo sielą iš kapo rankos? Sela.'),
  (@b19, 89, 49, 'Viešpatie, kur yra tavo ankstesni mylintys gerumai, kuriais prisiekei savo tiesa Dovydui?'),
  (@b19, 89, 50, 'Viešpatie, atsimink savo tarnų priekaištą; kaip nešioju savo krūtinėje visų galingų tautų priekaištą,'),
  (@b19, 89, 51, 'kuriuo tavo priešai, o VIEŠPATIE, priekaištavo; kuriuo jie prikaišiojo tavo pateptojo žingsniams.'),
  (@b19, 89, 52, 'Tebūna palaimintas VIEŠPATS per amžius. Amen, Amen.'),
  (@b19, 90, 1, 'Dievo vyro Mozės malda. Viešpatie, tu buvai mūsų buveinė per kartų kartas.'),
  (@b19, 90, 2, 'Prieš gimstant kalnams ir kai dar nebuvai suformavęs žemės bei pasaulio, nuo amžinybės iki amžinybės tu esi Dievas.'),
  (@b19, 90, 3, 'Tu grąžini žmogų į suirimą; ir sakai: „Sugrįžkite, žmonių vaikai“.'),
  (@b19, 90, 4, 'Nes tūkstantis metų tavo akyse – kaip praėjusi vakarykštė diena ir kaip sargyba naktį.'),
  (@b19, 90, 5, 'Tu juos nuneši kaip potvyniu; jie yra kaip miegas; ryte jie yra kaip žolė, kuri auga.'),
  (@b19, 90, 6, 'Ryte ji veši ir auga; vakare ji nupjaunama ir sudžiūsta.'),
  (@b19, 90, 7, 'Nes mes esame naikinami tavo pykčio ir neraminami tavo rūstybės.'),
  (@b19, 90, 8, 'Tu statei mūsų neteisybes prieš save, mūsų slaptas nuodėmes savo veido šviesoje.'),
  (@b19, 90, 9, 'Nes visos mūsų dienos praėjo tavo rūstybėje; mes praleidžiame savo metus kaip pasektą pasaką.'),
  (@b19, 90, 10, 'Mūsų metų dienos – septyniasdešimt metų; o jei pasižymi stiprumu – aštuoniasdešimt metų, tačiau jų stiprybė – triūsas ir sielvartas; nes tai greitai iškertama, ir mes nuskrendame.'),
  (@b19, 90, 11, 'Kas pažįsta tavo pykčio galią? Kokia tavo baimė, tokia tavo rūstybė.'),
  (@b19, 90, 12, 'Taigi pamokyk mus skaičiuoti savo dienas, kad mes palenktume savo širdis prie išminties.'),
  (@b19, 90, 13, 'Sugrįžk, o VIEŠPATIE, kaip ilgai? gailėkis dėl savo tarnų.'),
  (@b19, 90, 14, 'Anksti mus pasotink savo gailestingumu; kad mes džiūgautume ir linksmintumėmės per visas savo dienas.'),
  (@b19, 90, 15, 'Palinksmink mus už dienas, per kurias mus varginai, ir už metus, per kuriuos matėme pikta.'),
  (@b19, 90, 16, 'Tepasirodo tavo tarnams tavo darbas ir tavo šlovė jų vaikams.'),
  (@b19, 90, 17, 'Ir VIEŠPATIES, mūsų Dievo, grožis tebūna ant mūsų; ir įtvirtink mūsų rankų darbą ant mūsų; taip, įtvirtink mūsų rankų darbą.'),
  (@b19, 91, 1, 'Kas gyvena Aukščiausiojo slaptavietėje, tas pasiliks Visagalio šešėlyje.'),
  (@b19, 91, 2, 'Aš sakysiu apie VIEŠPATĮ: „Jis mano prieglobstis ir mano tvirtovė, mano Dievas; juo pasitikėsiu“.'),
  (@b19, 91, 3, 'Tikrai jis tave išvaduos iš paukščių medžiotojo kilpos ir iš pražūtingo maro.'),
  (@b19, 91, 4, 'Savo plunksnomis jis tave apdengs, ir po jo sparnais tu pasitikėsi; jo tiesa bus tavo didysis ir mažasis skydas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 91, 5, 'Tu naktį nebijosi dėl siaubo; nei dėl strėlės, kuri skraido dieną;'),
  (@b19, 91, 6, 'nei dėl maro, kuris vaikšto tamsoje; nei dėl sunaikinimo, kuris nusiaubia vidurdienyje.'),
  (@b19, 91, 7, 'Tavo pašonėje kris tūkstantis ir dešimt tūkstančių tavo dešinėje; bet prie tavęs tai nepriartės.'),
  (@b19, 91, 8, 'Tik savo akimis žiūrėsi ir matysi nedorėlių atlyginimą.'),
  (@b19, 91, 9, 'Kadangi tu padarei VIEŠPATĮ, kuris yra mano prieglobstis, tai yra Aukščiausiąjį savo buveine,'),
  (@b19, 91, 10, 'tau neatsitiks nieko pikto, ir jokia rykštė nepriartės prie tavo buveinės.'),
  (@b19, 91, 11, 'Nes jis įpareigos savo angelus dėl tavęs, kad saugotų tave visuose tavo keliuose.'),
  (@b19, 91, 12, 'Ant rankų jie tave nešios, kad neužsigautum kojos į akmenį.'),
  (@b19, 91, 13, 'Tu mindysi liūtą ir gyvatę; sutrypsi po kojomis jauniklį liūtą ir slibiną.'),
  (@b19, 91, 14, '„Kadangi jis pamilo mane, todėl aš jį išvaduosiu; pastatysiu jį ant aukštumos, nes jis pažinojo mano vardą.'),
  (@b19, 91, 15, 'Jis šauksis manęs, ir aš jam atsakysiu; aš būsiu su juo varge; jį išvaduosiu ir pagerbsiu.'),
  (@b19, 91, 16, 'Ilgu gyvenimu jį pasotinsiu ir parodysiu jam savo išgelbėjimą“.'),
  (@b19, 92, 1, 'Psalmė arba giesmė sabato dienai. Geras dalykas yra dėkoti VlEŠPAČIUI ir giedoti gyrių tavo vardui, o Aukščiausiasis;'),
  (@b19, 92, 2, 'skelbti rytmetį tavo mylintį gerumą ir tavo ištikimybę kiekvieną naktį;'),
  (@b19, 92, 3, 'dešimčiastygiu instrumentu ir psalteriu; arfa iškilmingu garsu.'),
  (@b19, 92, 4, 'Nes tu, VIEŠPATIE, mane pralinksminai savo darbu; aš triumfuosiu tavo rankų darbuose.'),
  (@b19, 92, 5, 'Kokie didingi tavo darbai, o VIEŠPATIE! Ir labai gilios tavo mintys!'),
  (@b19, 92, 6, 'Neprotingas žmogus nežino; nei kvailys to nesupranta.'),
  (@b19, 92, 7, 'Kai nedorėliai želia kaip žolė ir kai klesti visi darantys neteisybę, tai yra tam, kad jie būtų sunaikinti amžiams;'),
  (@b19, 92, 8, 'bet tu, VIEŠPATIE, esi aukščiausiasis per amžius.'),
  (@b19, 92, 9, 'Nes štai tavo priešai, o VIEŠPATIE, nes štai tavo priešai pražus; bus išsklaidyti visi, darantys neteisybę.'),
  (@b19, 92, 10, 'Bet tu iškelsi mano ragą kaip vienaragio; aš būsiu pateptas šviežiu aliejumi.'),
  (@b19, 92, 11, 'Taip pat mano akis pamatys mano troškimą ant mano priešų, o mano ausys girdės mano norą apie nedorėlius, kurie sukyla prieš mane.'),
  (@b19, 92, 12, 'Teisusis klestės kaip palmė; jis augs kaip Libane kedras.'),
  (@b19, 92, 13, 'VIEŠPATIES namuose pasodintieji klestės mūsų Dievo kiemuose.'),
  (@b19, 92, 14, 'Jie vis dar neš vaisių senatvėje; jie bus riebūs ir klestintys,'),
  (@b19, 92, 15, 'kad skelbtų, jog tiesus yra VIEŠPATS; jis yra mano uola, ir jame nėra neteisumo.'),
  (@b19, 93, 1, 'VIEŠPATS karaliauja, jis apsivilkęs didybe; VIEŠPATS apsivilkęs stiprybe, ja susijuosęs; pasaulis taipogi sutvirtintas, kad būtų nepajudinamas.'),
  (@b19, 93, 2, 'Nuo seno įtvirtintas tavo sostas; tu esi nuo amžinybės.'),
  (@b19, 93, 3, 'Pakėlė potvyniai, o VIEŠPATIE, pakėlė potvyniai savo balsą; potvyniai pakelia savo bangas.'),
  (@b19, 93, 4, 'Galingesnis už daugybės vandenų šniokštimą, taip, už galingas jūros bangas yra VIEŠPATS aukštybėje.'),
  (@b19, 93, 5, 'Tavo liudijimai labai patikimi; tavo namams pritinka šventumas, o VIEŠPATIE, per amžius.'),
  (@b19, 94, 1, 'O VIEŠPATIE Dieve, kuriam priklauso keršijimas; o Dieve, kuriam priklauso keršijimas, pasirodyk.'),
  (@b19, 94, 2, 'Kelkis, žemės teisėjau; atmokėk išdidiesiems atpildu.'),
  (@b19, 94, 3, 'VIEŠPATIE, kaip ilgai nedorėliai, kaip ilgai nedorėliai džiūgaus?'),
  (@b19, 94, 4, 'Kaip ilgai jie tars ir kalbės sunkius dalykus, ir didžiuosis visi, darantys neteisybę?'),
  (@b19, 94, 5, 'Jie triuškina tavo tautą, o VIEŠPATIE, ir spaudžia tavo paveldą.'),
  (@b19, 94, 6, 'Jie užmuša našlę ir ateivį, ir žudo našlaičius.'),
  (@b19, 94, 7, 'Jie dar sako: „VIEŠPATS nematys ir Jokūbo Dievas neatsižvelgs“.'),
  (@b19, 94, 8, 'Supraskite, neprotingieji tautoje; ir jūs, kvailiai, kada būsite išmintingi?'),
  (@b19, 94, 9, 'Argi tas, kuris įsodino ausį, negirdės, ir tas, kuris suformavo akį, nematys?'),
  (@b19, 94, 10, 'Argi tas, kuris baudžia pagonis, nepabaus? Tas, kuris moko žmogų pažinimo, argi nežinos?'),
  (@b19, 94, 11, 'VIEŠPATS žino žmonių mintis, kad jos yra tuštybė.'),
  (@b19, 94, 12, 'Palaimintas žmogus, kurį tu, o VIEŠPATIE, baudi ir mokai savo įstatymo,'),
  (@b19, 94, 13, 'kad jam duotum poilsį nuo nelaimės dienų, kol nedorėliui kasama duobė.'),
  (@b19, 94, 14, 'Nes VIEŠPATS neatmes savo tautos nei nepaliks savo paveldo.'),
  (@b19, 94, 15, 'Bet teismas sugrįš prie teisumo; ir juo paseks visi tiesiaširdžiai.'),
  (@b19, 94, 16, 'Kas kelsis už mane prieš piktadarius? Arba, kas stos už mane prieš darančius neteisybę?'),
  (@b19, 94, 17, 'Jei VIEŠPATS nebūtų buvęs mano pagalba, mano siela beveik būtų apsigyvenusi tyloje.'),
  (@b19, 94, 18, 'Kai sakiau: „Slysta mano koja“, tavo gailestingumas, o VIEŠPATIE, palaikė mane.'),
  (@b19, 94, 19, 'Mano minčių gausybėje mano viduje, tavo paguodos džiugina mano sielą.'),
  (@b19, 94, 20, 'Argi su tavimi turės bendrystę neteisybės sostas, per įstatymą sugalvojantis piktadarybę?'),
  (@b19, 94, 21, 'Jie kartu susirenka prieš teisiojo sielą ir pasmerkia nekaltą kraują.'),
  (@b19, 94, 22, 'Bet VIEŠPATS yra mano apsauga; ir mano Dievas – mano prieglobsčio uola.'),
  (@b19, 94, 23, 'Jis ant jų užves jų pačių neteisybę ir juos iškirs jų pačių nedorybėje; taip, VIEŠPATS, mūsų Dievas, juos iškirs.'),
  (@b19, 95, 1, 'Ateikite, giedokime VIEŠPAČIUI; džiaugsmingą triukšmą kelkime mūsų išgelbėjimo uolai.'),
  (@b19, 95, 2, 'Ateikime jo akivaizdon su padėka ir kelkime jam džiaugsmingą triukšmą psalmėmis.'),
  (@b19, 95, 3, 'Nes VIEŠPATS yra didis Dievas ir didis Karalius viršum visų dievų.'),
  (@b19, 95, 4, 'Jo rankoje yra gìliosios žemės vietos; kalvų tvirtumas taip pat yra jo.'),
  (@b19, 95, 5, 'Jo yra jūra – jis ją padarė; ir sausumą suformavo jo rankos.'),
  (@b19, 95, 6, 'Ateikite, garbinkime ir nusilenkime; klaupkimės prieš VIEŠPATĮ, mūsų Kūrėją.'),
  (@b19, 95, 7, 'Nes jis yra mūsų Dievas; o mes – jo ganyklos tauta ir jo rankos avys. Šiandien, jei išgirsite jo balsą:'),
  (@b19, 95, 8, '„Neužkietinkite savo širdies kaip kurstyme ir kaip gundymo dieną dykumoje;'),
  (@b19, 95, 9, 'kai jūsų tėvai mane gundė, mane bandė, ir matė mano darbą.'),
  (@b19, 95, 10, 'Keturiasdešimt metų mane liūdino ta karta, ir sakiau: ‘Tai tauta, kuri klysta savo širdyje, ir jie nepažino mano kelių’;'),
  (@b19, 95, 11, 'kuriems savo rūstybėje prisiekiau, kad jie neįeis į mano poilsį“.'),
  (@b19, 96, 1, 'Giedokite VIEŠPAČIUI naują giesmę; Giedok VIEŠPAČIUI, visa žeme.'),
  (@b19, 96, 2, 'Giedokite VIEŠPAČIUI, laiminkite jo vardą; diena iš dienos skelbkite jo išgelbėjimą.'),
  (@b19, 96, 3, 'Skelbkite tarp pagonių jo šlovę, visose tautose jo stebuklus.'),
  (@b19, 96, 4, 'Nes didis yra VIEŠPATS ir didžiai girtinas; jis bijotinas labiausiai už visus dievus.'),
  (@b19, 96, 5, 'Nes visi tautų dievai yra stabai; bet VIEŠPATS padarė dangus.'),
  (@b19, 96, 6, 'Garbė ir didybė jo priešakyje; stiprybė ir grožis jo šventovėje.'),
  (@b19, 96, 7, 'Duokite VIEŠPAČIUI, tautų giminės, duokite VIEŠPAČIUI šlovę ir stiprybę.'),
  (@b19, 96, 8, 'Duokite VIEŠPAČIUI jo vardui priklausančią šlovę; atneškite atnašą ir ateikite į jo kiemus.'),
  (@b19, 96, 9, 'Garbinkite VIEŠPATĮ šventumo grožyje; bijok prieš jį, visa žeme.'),
  (@b19, 96, 10, 'Sakykite tarp pagonių, kad VIEŠPATS karaliauja; nepajudinamai bus įtvirtintas pasaulis; jis teis tautas teisiai.'),
  (@b19, 96, 11, 'Tegul džiūgauja dangūs ir linksminasi žemė; tešniokščia jūra ir jos pilnumas.'),
  (@b19, 96, 12, 'Tebūna džiaugsmingi laukai ir visa, kas yra juose; tada visi miško medžiai džiūgaus'),
  (@b19, 96, 13, 'VIEŠPATIES akivaizdoje; nes jis ateina, jis ateina žemės teisti; jis teis pasaulį teisumu ir liaudį savo tiesa.'),
  (@b19, 97, 1, 'VIEŠPATS karaliauja; tedžiūgauja žemė; tesilinksmina tuo salų daugybė.'),
  (@b19, 97, 2, 'Debesys ir tamsa aplink jį; teisumas ir teismas yra jo sosto buveinė.'),
  (@b19, 97, 3, 'Ugnis eina pirma jo ir sudegina aplinkui jo priešus.'),
  (@b19, 97, 4, 'Jo žaibai nušvietė pasaulį; žemė matė ir drebėjo.'),
  (@b19, 97, 5, 'Kalvos sutirpo kaip vaškas nuo VIEŠPATIES akivaizdos, nuo visos žemės Viešpaties akivaizdos.'),
  (@b19, 97, 6, 'Dangūs skelbia jo teisumą, ir visa liaudis mato jo šlovę.'),
  (@b19, 97, 7, 'Tesusigėsta visi, kurie tarnauja raižytiems atvaizdams, kurie giriasi stabais; garbinkite jį jūs, visi dievai.'),
  (@b19, 97, 8, 'Sionas girdėjo ir džiaugėsi; ir Judos dukterys džiūgavo dėl tavo teismų, o VIEŠPATIE.'),
  (@b19, 97, 9, 'Nes tu, VIEŠPATIE, esi aukštai virš visos žemės; tu esi išaukštintas daug aukščiau visų dievų.'),
  (@b19, 97, 10, 'Jūs, kurie mylite VIEŠPATĮ, nekęskite pikto; jis saugo savo šventųjų sielas; iš nedorėlių rankos jas išvaduoja.'),
  (@b19, 97, 11, 'Šviesa sėjama teisiajam, ir tiesiaširdžiams džiaugsmas.'),
  (@b19, 97, 12, 'Džiūgaukite, teisieji, VIEŠPATYJE; ir dėkokite prisimindami jo šventumą.'),
  (@b19, 98, 1, 'Psalmė. Giedokite VIEŠPAČIUI naują giesmę; nes jis padarė nuostabių dalykų; jo dešinė ir jo šventoji ranka jam atnešė pergalę.'),
  (@b19, 98, 2, 'VIEŠPATS apreiškė savo išgelbėjimą; pagonių akyse jis atvirai parodė savo teisumą.'),
  (@b19, 98, 3, 'Jis atsiminė savo gailestingumą ir savo tiesą Izraelio namams; visi žemės pakraščiai pamatė mūsų Dievo išgelbėjimą.'),
  (@b19, 98, 4, 'Džiaugsmingą triukšmą kelkite VIEŠPAČIUI, visa žeme; garsiai triukšmaukite, džiūgaukite ir giedokite gyrių.'),
  (@b19, 98, 5, 'Giedokite VIEŠPAČIUI su arfa; su arfa ir psalmės balsu.'),
  (@b19, 98, 6, 'Su trimitais ir korneto garsu kelkite džiaugsmingą triukšmą VIEŠPATIES, Karaliaus, akivaizdoje.'),
  (@b19, 98, 7, 'Teūžia jūra ir jos pilnuma; pasaulis ir jame gyvenantys.'),
  (@b19, 98, 8, 'Tegul upės ploja rankomis; kartu tedžiūgauja kalnai'),
  (@b19, 98, 9, 'VIEŠPATIES akivaizdoje; nes jis ateina žemės teisti; jis teis pasaulį teisumu ir liaudį bešališkai.'),
  (@b19, 99, 1, 'VIEŠPATS karaliauja; tedreba liaudis; jis sėdi tarp kerubų; tesvyruoja žemė.'),
  (@b19, 99, 2, 'VIEŠPATS yra didis Sione; ir jis aukštai virš visos liaudies.'),
  (@b19, 99, 3, 'Tegul jie giria tavo didį ir baisų vardą; nes jis yra šventas.'),
  (@b19, 99, 4, 'Karaliaus galybė myli teismą: tu įtvirtini bešališkumą; tu vykdai teismą ir teisumą Jokūbe.'),
  (@b19, 99, 5, 'Aukštinkite VIEŠPATĮ, mūsų Dievą, ir garbinkite prie jo pakojo; nes jis yra šventas.'),
  (@b19, 99, 6, 'Mozė ir Aaronas tarp jo kunigų, ir Samuelis tarp tų, kurie šaukiasi jo vardo; jie šaukėsi VIEŠPATIES, ir jis jiems atsakė.'),
  (@b19, 99, 7, 'Debesuotame stulpe jis jiems kalbėjo; jie laikėsi jo liudijimų ir įsakų, kuriuos jis jiems davė.'),
  (@b19, 99, 8, 'O VIEŠPATIE, mūsų Dieve, tu jiems atsakei; tu buvai Dievas, kuris jiems atleidai, nors ir keršijai už jų prasimanymus.'),
  (@b19, 99, 9, 'Aukštinkite VIEŠPATĮ, mūsų Dievą, ir garbinkite prie jo šventosios kalvos; nes VIEŠPATS, mūsų Dievas, yra šventas.'),
  (@b19, 100, 1, 'Gyriaus psalmė. Kelkite džiaugsmingą triukšmą VIEŠPAČIUI, jūs, visos šalys.'),
  (@b19, 100, 2, 'Tarnaukite VIEŠPAČIUI su džiaugsmu; giedodami ateikite jo akivaizdon.'),
  (@b19, 100, 3, 'Žinokite, kad VIEŠPATS, jis yra Dievas; tai jis mus padarė, o ne mes patys; mes esame jo tauta ir jo ganyklos avys.'),
  (@b19, 100, 4, 'Įeikite į jo vartus su dėkojimu ir į jo kiemus su gyriumi; būkite jam dėkingi ir laiminkite jo vardą.'),
  (@b19, 100, 5, 'Nes geras yra VIEŠPATS; jo gailestingumas amžinas; ir jo tiesa išlieka kartų kartoms.'),
  (@b19, 101, 1, 'Dovydo psalmė. Apie gailestingumą ir teismą giedosiu; tau, o VIEŠPATIE, giedosiu.'),
  (@b19, 101, 2, 'Išmintingai elgsiuosi tobulu keliu. Kada tu ateisi pas mane? Aš vaikščiosiu tobula širdimi savo namų viduje.'),
  (@b19, 101, 3, 'Nestatysiu sau prieš akis jokio nedoro dalyko; nekenčiu darbo tų, kurie nukrypsta į šalį; jis neprilips prie manęs.'),
  (@b19, 101, 4, 'Priešgyni širdis pasitrauks nuo manęs; nepažinosiu nedorėlio.'),
  (@b19, 101, 5, 'Kas šmeižia slapta savo artimą, tą aš iškirsiu; kas žiūri iš aukšto ir turi išdidžią širdį, to nepakęsiu.'),
  (@b19, 101, 6, 'Mano akys bus ant šalies ištikimųjų, kad jie gyventų su manimi; kas vaikšto tobulu keliu, tas man tarnaus.'),
  (@b19, 101, 7, 'Kas daro klastą, negyvens mano namuose; kas kalba melus, nepasiliks mano akyse.'),
  (@b19, 101, 8, 'Anksti išnaikinsiu visus šalies nedorėlius, kad iškirsčiau visus, darančius nedorybę, iš VIEŠPATIES miesto.'),
  (@b19, 102, 1, 'Kenčiančio malda, kai jis priblokštas išlieja prieš VIEŠPATĮ savo skundą. O VIEŠPATIE, išgirsk mano maldą, ir mano šauksmas teateina pas tave.'),
  (@b19, 102, 2, 'Neslėpk savo veido nuo manęs tą dieną, kai esu bėdoje; palenk prie manęs savo ausį; tą dieną, kai šaukiuosi, skubiai man atsakyk.'),
  (@b19, 102, 3, 'Nes mano dienos pranyko kaip dūmai, ir mano kaulai degė kaip židinys.'),
  (@b19, 102, 4, 'Mano širdis sumušta, sudžiūvusi kaip žolė; kad net pamirštu valgyti savo duoną.'),
  (@b19, 102, 5, 'Dėl mano vaitojimo balso mano kaulai prilipo prie mano odos.'),
  (@b19, 102, 6, 'Aš panašus į tyrų pelikaną; esu kaip dykumos pelėda.'),
  (@b19, 102, 7, 'Budžiu ir esu kaip vienišas žvirblis ant namo stogo.'),
  (@b19, 102, 8, 'Visą dieną man priekaištauja mano priešai; ir tie, kurie įširdę ant manęs, yra prieš mane prisiekę.'),
  (@b19, 102, 9, 'Nes pelenus valgiau kaip duoną ir savo gėrimą maišiau su verksmu'),
  (@b19, 102, 10, 'dėl tavo pasipiktinimo ir tavo rūstybės; nes tu pakėlei mane ir nubloškei žemėn.'),
  (@b19, 102, 11, 'Mano dienos – kaip nykstantis šešėlis; ir aš išdžiūvęs kaip žolė.'),
  (@b19, 102, 12, 'Bet tu, o VIEŠPATIE, išliksi per amžius; ir tavo prisiminimas visoms kartoms.'),
  (@b19, 102, 13, 'Tu pakilsi ir pasigailėsi Siono; nes laikas suteikti jam palankumą, taip, paskirtas laikas, atėjo.'),
  (@b19, 102, 14, 'Nes jo akmenys teikia malonumą tavo tarnams, ir jie palankūs jo dulkėms.'),
  (@b19, 102, 15, 'Taigi pagonys bijosis VIEŠPATIES vardo ir visi žemės karaliai tavo šlovės.'),
  (@b19, 102, 16, 'Kai VIEŠPATS pastatys Sioną, jis pasirodys savo šlovėje.'),
  (@b19, 102, 17, 'Jis atsižvelgs į beturčių maldą ir nepaniekins jų maldos.'),
  (@b19, 102, 18, 'Tai bus užrašyta ateinančiai kartai; ir tauta, kuri bus sutverta, girs VIEŠPATĮ.'),
  (@b19, 102, 19, 'Nes jis pažvelgė žemyn iš savo šventovės aukščio; VIEŠPATS iš dangaus pažiūrėjo į žemę,'),
  (@b19, 102, 20, 'kad išgirstų belaisvių dejavimą, kad išlaisvintų paskirtuosius mirčiai,'),
  (@b19, 102, 21, 'kad Sione skelbtų VIEŠPATIES vardą ir jo gyrių Jeruzalėje,'),
  (@b19, 102, 22, 'kai susirinkusios kartu tautos ir karalystės VIEŠPAČIUI tarnauti.'),
  (@b19, 102, 23, 'Jis susilpnino kelyje mano jėgas; jis sutrumpino mano dienas.'),
  (@b19, 102, 24, 'Aš sakiau: „O, mano Dieve, nepašalink manęs viduryje mano dienų; tavo metai yra per visas kartas.'),
  (@b19, 102, 25, 'Nuo seno tu padėjai žemės pamatą; ir dangūs – tavo rankų darbas.'),
  (@b19, 102, 26, 'Jie pražus, bet tu pasiliksi; taip, jie visi pasens kaip drabužis; kaip rūbą tu juos pakeisi, ir jie bus pakeisti;'),
  (@b19, 102, 27, 'bet tu esi tas pats, ir tavo metai nesibaigs.'),
  (@b19, 102, 28, 'Tavo tarnų vaikai pasiliks, ir jų sėkla bus įtvirtinta tavo akivaizdoje“.'),
  (@b19, 103, 1, 'Dovydo psalmė. Laimink, mano siela, VIEŠPATĮ; ir visa, kas yra manyje, laimink jo šventą vardą.'),
  (@b19, 103, 2, 'Laimink, mano siela, VIEŠPATĮ ir nepamiršk visų jo geradarysčių;'),
  (@b19, 103, 3, 'jis atleidžia visas tavo neteisybes; jis gydo visas tavo ligas;'),
  (@b19, 103, 4, 'jis atperka tavo gyvybę iš pražūties; jis tave vainikuoja mylinčiu gerumu ir švelniais gailestingumais;'),
  (@b19, 103, 5, 'jis pasotina tavo burną gėrybėmis, jog atsinaujina tavo jaunystė kaip erelio.'),
  (@b19, 103, 6, 'VIEŠPATS vykdo teisumą ir teismą visiems engiamiesiems.'),
  (@b19, 103, 7, 'Jis davė pažinti savo kelius Mozei, savo darbus Izraelio vaikams.'),
  (@b19, 103, 8, 'Gailestingas ir maloningas yra VIEŠPATS, lėtas pykti ir gausus gailestingumo.'),
  (@b19, 103, 9, 'Ne visada jis barsis; ir ne amžinai jis laikys savo pyktį.'),
  (@b19, 103, 10, 'Jis nesielgė su mumis pagal mūsų nuodėmes; ir neatlygino mums pagal mūsų neteisybes.'),
  (@b19, 103, 11, 'Nes kaip dangus yra aukštai virš žemės, taip didis yra jo gailestingumas tiems, kurie jo bijo.'),
  (@b19, 103, 12, 'Kaip toli rytai yra nuo vakarų, taip jis nuo mūsų atitolino mūsų nusižengimus.'),
  (@b19, 103, 13, 'Kaip tėvas gailisi savo vaikų, taip VIEŠPATS gailisi tų, kurie jo bijo.'),
  (@b19, 103, 14, 'Nes jis žino mūsų sandarą; jis atsimena, kad mes esame dulkės.'),
  (@b19, 103, 15, 'O žmogus – jo dienos yra kaip žolė; jis klesti taip, kaip lauko gėlė.'),
  (@b19, 103, 16, 'Nes virš jos praeina vėjas, ir jos nebėra; ir jos nebepažįsta jos vieta.'),
  (@b19, 103, 17, 'Bet VIEŠPATIES gailestingumas nuo amžinybės iki amžinybės ant tų, kurie jo bijo, ir jo teisumas vaikų vaikams;'),
  (@b19, 103, 18, 'tiems, kurie laikosi jo sandoros, ir tiems, kurie atsimena jo įsakymus, kad juos vykdytų.'),
  (@b19, 103, 19, 'VIEŠPATS paruošė savo sostą danguose; ir jo karalystė valdo viską.'),
  (@b19, 103, 20, 'Laiminkite VIEŠPATĮ, jūs, jo angelai, kurie pranokstate jėga, kurie vykdote jo įsakymus, klausydami jo žodžio balso.'),
  (@b19, 103, 21, 'Laiminkite VIEŠPATĮ, jūs, visos jo kariuomenės, jūs, jo tarnai, kurie vykdote jo norą.'),
  (@b19, 103, 22, 'Laiminkite VIEŠPATĮ, visi jo darbai visose jo viešpatystės vietose; o mano siela, laimink VIEŠPATĮ.'),
  (@b19, 104, 1, 'O mano siela, laimink VIEŠPATĮ. O VIEŠPATIE, mano Dieve, tu esi labai didingas; garbe ir didybe esi apsirengęs.'),
  (@b19, 104, 2, 'Tu apsigaubi šviesa kaip drabužiu; tu ištiesi dangus kaip uždangalą;'),
  (@b19, 104, 3, 'tu padedi savo kambarių sijas vandenyse; darai debesis savo vežimu; tu vaikštai ant vėjo sparnų;'),
  (@b19, 104, 4, 'tu darai savo angelus dvasiomis, savo tarnus – liepsnojančia ugnimi;'),
  (@b19, 104, 5, 'tu padėjai žemės pamatus, kad ji nebūtų pajudinta per amžius.'),
  (@b19, 104, 6, 'Tu ją apdengei gelmėmis kaip drabužiu; vandenys stovėjo virš kalnų.'),
  (@b19, 104, 7, 'Tau barantis jie bėgo; nuo tavo griaustinio balso jie išskubėjo.'),
  (@b19, 104, 8, 'Jie kyla kalnais; jie nusileidžia slėniais į vietą, kurią jiems pastatei ant pamato.'),
  (@b19, 104, 9, 'Tu ribą nustatei, kad jie neperžengtų; kad jie nebesugrįžtų žemės apdengti.'),
  (@b19, 104, 10, 'Jis siunčia į slėnius šaltinius, kurie teka tarp kalvų.'),
  (@b19, 104, 11, 'Jie girdo visus lauko žvėris; laukiniai asilai numalšina savo troškulį.'),
  (@b19, 104, 12, 'Prie jų turės savo buveinę dangaus skrajūnai, kurie čiulba tarp šakų.'),
  (@b19, 104, 13, 'Jis palaisto kalvas iš savo kambarių; tavo darbų vaisiais pasisotina žemė.'),
  (@b19, 104, 14, 'Jis augina žolę galvijams ir žoles, kad žmogui tarnautų; kad jis iš žemės išgautų maisto;'),
  (@b19, 104, 15, 'ir vyno, kuris linksmina žmogaus širdį, ir aliejaus, kad jo veidas spindėtų, ir duonos, kuri sustiprina žmogaus širdį.'),
  (@b19, 104, 16, 'VIEŠPATIES medžiai pilni sulos, Libano kedrai, kuriuos jis pasodino;'),
  (@b19, 104, 17, 'kur paukščiai sukasi lizdus; na, o gandras – eglės jo namai.'),
  (@b19, 104, 18, 'Aukštos kalvos – prieglobstis laukinėms ožkoms, o uolos – triušiams.'),
  (@b19, 104, 19, 'Jis paskyrė mėnulį laikams; saulė žino savo nusileidimą.'),
  (@b19, 104, 20, 'Tu padarai tamsą, ir yra naktis; joje išslenka visi miško žvėrys.'),
  (@b19, 104, 21, 'Jauni liūtai riaumoja grobio ir ieško sau maisto iš Dievo.'),
  (@b19, 104, 22, 'Patekėjus saulei, jie susirenka ir sugula savo urvuose.'),
  (@b19, 104, 23, 'Žmogus išeina į savo darbą ir į savo triūsą iki vakaro.'),
  (@b19, 104, 24, 'O VIEŠPATIE, kokie daugeriopi tavo darbai! Juos visus tu išmintimi padarei; žemė pilna tavo turtų.'),
  (@b19, 104, 25, 'Tokia yra ši didelė ir plati jūra, kurioje ropoja be skaičiaus padarų, tiek mažų, tiek didelių gyvūnų.'),
  (@b19, 104, 26, 'Ten plaukioja laivai; ten yra tas leviatanas, kurį tu padarei žaisti joje.'),
  (@b19, 104, 27, 'Jie visi tavęs laukia, kad duotum jiems jų maisto reikiamu metu.'),
  (@b19, 104, 28, 'Ką jiems duodi, jie surenka; tu atveri savo ranką, jie pasisotina geru.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 104, 29, 'Tu paslepi savo veidą, jie nerimauja; tu atimi jų kvapą, jie miršta ir sugrįžta į savo dulkes.'),
  (@b19, 104, 30, 'Tu išsiunti savo Dvasią – jie sutveriami; ir tu atnaujini žemės paviršių.'),
  (@b19, 104, 31, 'VIEŠPATIES šlovė pasiliks per amžius; VIEŠPATS džiaugsis savo darbais.'),
  (@b19, 104, 32, 'Jis pažvelgia į žemę, ir ji dreba; jis paliečia kalvas, ir jos rūksta.'),
  (@b19, 104, 33, 'Giedosiu VIEŠPAČIUI, kol gyvensiu; giedosiu gyrių savo Dievui, kol gyvenu.'),
  (@b19, 104, 34, 'Mano apmąstymai apie jį bus malonūs; Aš džiaugsiuosi VIEŠPAČIU.'),
  (@b19, 104, 35, 'Tegul nusidėjėliai dingsta iš žemės ir tenebūna daugiau nedorėlių. O mano siela, laimink VIEŠPATĮ. Girkite VIEŠPATĮ.'),
  (@b19, 105, 1, 'Dėkokite VIEŠPAČIUI; šaukitės jo vardo; skelbkite liaudyje jo darbus.'),
  (@b19, 105, 2, 'Giedokite jam, giedokite jam psalmes; kalbėkite apie visus jo stebuklingus darbus.'),
  (@b19, 105, 3, 'Didžiuokitės jo šventu vardu; tegul džiaugiasi širdis tų, kurie ieško VIEŠPATIES.'),
  (@b19, 105, 4, 'Ieškokite VIEŠPATIES ir jo stiprybės; nuolatos ieškokite jo veido.'),
  (@b19, 105, 5, 'Atsiminkite jo nuostabius darbus, kuriuos jis yra padaręs; jo stebuklus ir jo burnos teismus,'),
  (@b19, 105, 6, 'o jūs, jo tarno Abraomo sėkla, jo išrinktojo Jokūbo vaikai.'),
  (@b19, 105, 7, 'Jis yra VIEŠPATS, mūsų Dievas; visoje žemėje yra jo teismai.'),
  (@b19, 105, 8, 'Jis per amžius atsimena savo sandorą, tą žodį, kurį jis įsakė tūkstančiui kartų.'),
  (@b19, 105, 9, 'Tą sandorą jis sudarė su Abraomu, ir savo priesaiką Izaokui;'),
  (@b19, 105, 10, 'ir ją patvirtino kaip įstatymą Jokūbui ir kaip amžiną sandorą Izraeliui,'),
  (@b19, 105, 11, 'sakydamas: „Tau duosiu Kanaano šalį, jūsų paveldo dalį“;'),
  (@b19, 105, 12, 'kai jie buvo nedidelis skaičius žmonių, taip, labai mažas, ir ateiviai joje.'),
  (@b19, 105, 13, 'Kai jie ėjo iš vienos tautos į kitą, iš vienos karalystės į kitą tautą,'),
  (@b19, 105, 14, 'jis niekam neleido jų skriausti; taip, jis bardavo dėl jų karalius,'),
  (@b19, 105, 15, 'sakydamas: „Nelieskite mano pateptųjų ir mano pranašams nedarykite pikto“.'),
  (@b19, 105, 16, 'Taip pat jis pašaukė šaliai badą; jis sulaužė visą duonos ramstį.'),
  (@b19, 105, 17, 'Jis pirma jų pasiuntė vyrą – Juozapą, kuris buvo parduotas tarnu;'),
  (@b19, 105, 18, 'kurio kojas jie žalojo pančiais; jis buvo paguldytas į geležį'),
  (@b19, 105, 19, 'iki to laiko, kai atėjo jo žodis; VIEŠPATIES žodis jį išbandė.'),
  (@b19, 105, 20, 'Karalius siuntė ir jį paleido, būtent tautos valdovas, ir jį išlaisvino.'),
  (@b19, 105, 21, 'Jis padarė jį savo namų viešpačiu ir viso savo turto valdovu,'),
  (@b19, 105, 22, 'surišti jo kunigaikščius pagal savo norą ir jo vyresniuosius pamokyti išminties.'),
  (@b19, 105, 23, 'Taip pat Izraelis atvyko į Egiptą; ir Jokūbas laikinai apsigyveno Chamo šalyje.'),
  (@b19, 105, 24, 'Jis labai pagausino savo tautą; ir juos padarė stipresniais už jų priešus.'),
  (@b19, 105, 25, 'Jis nukreipė jų širdį nekęsti jo tautos, gudriai elgtis su jo tarnais.'),
  (@b19, 105, 26, 'Jis siuntė Mozę, savo tarną, ir Aaroną, kurį buvo išsirinkęs.'),
  (@b19, 105, 27, 'Jie rodė tarp jų jo ženklus ir stebuklus Chamo šalyje.'),
  (@b19, 105, 28, 'Jis pasiuntė tamsą ir aptemdė; ir jie nemaištavo prieš jo žodį.'),
  (@b19, 105, 29, 'Jis pavertė jų vandenis į kraują ir išmarino jų žuvis.'),
  (@b19, 105, 30, 'Jų šalis gausiai išgavo varlių jų karalių kambariuose.'),
  (@b19, 105, 31, 'Jis tarė, ir atlėkė įvairios musės ir utėlės visose jų ribose.'),
  (@b19, 105, 32, 'Jis jiems davė krušą vietoje lietaus ir liepsnojančią ugnį jų šalyje.'),
  (@b19, 105, 33, 'Jis išdaužė jų vynmedžius ir figmedžius; ir sulaužė jų ribų medžius.'),
  (@b19, 105, 34, 'Jis tarė, ir atėjo skėriai bei vikšrai, ir tai be skaičiaus,'),
  (@b19, 105, 35, 'ir suėdė visas žoles jų šalyje, ir surijo jų dirvos vaisių.'),
  (@b19, 105, 36, 'Taip pat jis ištiko visus pirmagimius jų šalyje, visos jų stiprybės pradmenį.'),
  (@b19, 105, 37, 'Jis išvedė juos su sidabru ir auksu; ir jų gentyse nebuvo nei vieno paliegusio.'),
  (@b19, 105, 38, 'Džiaugėsi Egiptas jiems išėjus, nes juos ištiko baimė dėl jų.'),
  (@b19, 105, 39, 'Jis išskleidė debesį kaip dangalą; ir ugnį, kad šviestų per naktį.'),
  (@b19, 105, 40, 'Tauta prašė, ir jis atgabeno putpelių ir dangaus duona juos pasotino.'),
  (@b19, 105, 41, 'Jis atvėrė uolą, ir ištryško vandenys; jie tekėjo per sausumas kaip upė.'),
  (@b19, 105, 42, 'Nes jis atsiminė savo šventą pažadą ir Abraomą, savo tarną.'),
  (@b19, 105, 43, 'Ir jis išvedė savo tautą su džiaugsmu ir savo išrinktuosius su linksmumu;'),
  (@b19, 105, 44, 'ir davė jiems pagonių šalis; ir jie paveldėjo tautų triūsą,'),
  (@b19, 105, 45, 'kad laikytųsi jo įstatų ir vykdytų jo įstatymus. Girkite VIEŠPATĮ.'),
  (@b19, 106, 1, 'Girkite VIEŠPATĮ. Dėkokite VIEŠPAČIUI; nes jis yra geras; nes jo gailestingumas išlieka per amžius.'),
  (@b19, 106, 2, 'Kas gali išsakyti VIEŠPATIES galingus darbus? Kas gali paskelbti visą jo gyrių?'),
  (@b19, 106, 3, 'Palaiminti, kurie laikosi teismo ir tas, kuris visą laiką daro teisumą.'),
  (@b19, 106, 4, 'Atsimink mane, o VIEŠPATIE, su palankumu, kurio laikaisi savo tautai; aplankyk mane savo išgelbėjimu;'),
  (@b19, 106, 5, 'kad matyčiau tavo išrinktųjų gerovę, kad džiūgaučiau tavo tautos džiaugsmu, kad didžiuočiausi su tavo paveldu.'),
  (@b19, 106, 6, 'Mes nusidėjome su savo tėvais, vykdėme neteisybę, nedorai elgėmės.'),
  (@b19, 106, 7, 'Mūsų tėvai Egipte nesuprato tavo stebuklų; jie neprisiminė tavo gailestingumų daugybės; bet kurstė jį prie jūros – prie Raudonosios jūros.'),
  (@b19, 106, 8, 'Tačiau jis juos išgelbėjo dėl savo vardo, kad duotų pažinti savo galingą jėgą.'),
  (@b19, 106, 9, 'Taip pat jis papeikė Raudonąją jūrą, ir ji išdžiūvo; taip jis vedė juos per gelmes kaip per dykumą.'),
  (@b19, 106, 10, 'Ir jis juos išgelbėjo iš rankos to, kuris jų nekentė, ir juos atpirko iš priešo rankos.'),
  (@b19, 106, 11, 'Vandenys apdengė jų priešus; nei vienas jų neišliko.'),
  (@b19, 106, 12, 'Tada jie tikėjo jo žodžiais; giedojo jo gyrių.'),
  (@b19, 106, 13, 'Jie greitai pamiršo jo darbus; jie nelaukė jo patarimo;'),
  (@b19, 106, 14, 'bet be galo geidė dykumoje ir gundė Dievą tyruose.'),
  (@b19, 106, 15, 'Ir jis jiems davė, ko jie prašė; bet siuntė liesumą į jų sielą.'),
  (@b19, 106, 16, 'Taipogi jie pavydėjo Mozei stovykloje ir Aaronui, VIEŠPATIES šventajam.'),
  (@b19, 106, 17, 'Atsivėrė žemė ir prarijo Dataną, ir apdengė Abiramo draugiją.'),
  (@b19, 106, 18, 'Ugnis užsidegė jų draugijoje; liepsna sudegino nedorėlius.'),
  (@b19, 106, 19, 'Jie padarė veršį Horebe ir garbino nulietą atvaizdą.'),
  (@b19, 106, 20, 'Taip jie iškeitė savo šlovę į pavidalą jaučio, ėdančio žolę.'),
  (@b19, 106, 21, 'Jie pamiršo Dievą, savo gelbėtoją, padariusį didžių dalykų Egipte;'),
  (@b19, 106, 22, 'nuostabių darbų Chamo šalyje ir baisių dalykų prie Raudonosios jūros.'),
  (@b19, 106, 23, 'Todėl jis sakė, kad juos būtų sunaikinęs, jei Mozė, jo išrinktasis, nebūtų stojęs į spragą jo akivaizdon, kad nukreiptų jo rūstybę, idant jis jų neišnaikintų.'),
  (@b19, 106, 24, 'Taip, jie paniekino maloniąją šalį, netikėjo jo žodžiu;'),
  (@b19, 106, 25, 'bet murmėjo savo palapinėse ir neklausė VIEŠPATIES balso.'),
  (@b19, 106, 26, 'Todėl jis pakėlė prieš juos savo ranką, kad juos dykumoje pargriautų;'),
  (@b19, 106, 27, 'kad pargriautų jų sėklą tarp tautų ir juos išsklaidytų po šalis.'),
  (@b19, 106, 28, 'Taip pat jie prisijungė prie Baal-Peoro ir valgė mirusiųjų aukas.'),
  (@b19, 106, 29, 'Taip jie kurstė jo pyktį savo prasimanymais; ir ant jų išsiveržė rykštė.'),
  (@b19, 106, 30, 'Tada atsistojo Finehasas ir įvykdė teismą; ir taip rykštė buvo sustabdyta.'),
  (@b19, 106, 31, 'Ir tai jam buvo įskaityta teisumu per visas kartas per amžius.'),
  (@b19, 106, 32, 'Jie jį įpykino prie kivirčų vandenų taip, kad Mozė dėl jų nukentėjo;'),
  (@b19, 106, 33, 'nes jie kurstė jo dvasią taip, kad jis neapgalvotai kalbėjo savo lūpomis.'),
  (@b19, 106, 34, 'Jie nesunaikino tautų, apie kurias VIEŠPATS jiems buvo įsakęs;'),
  (@b19, 106, 35, 'bet susimaišė su pagonimis ir išmoko jų darbų.'),
  (@b19, 106, 36, 'Ir jie tarnavo jų stabams, kurie jiems buvo žabangomis.'),
  (@b19, 106, 37, 'Taip, jie aukojo savo sūnus ir savo dukteris velniams,'),
  (@b19, 106, 38, 'ir išliejo nekaltą kraują – kraują savo sūnų ir savo dukterų, kuriuos jie aukojo Kanaano stabams; ir šalis buvo suteršta krauju.'),
  (@b19, 106, 39, 'Taip jie susiteršė savo darbais ir paleistuvavo savo prasimanymais.'),
  (@b19, 106, 40, 'Todėl VIEŠPATIES rūstybė užsidegė prieš savo tautą taip, kad jis bjaurėjosi savo paveldu.'),
  (@b19, 106, 41, 'Ir jis juos padavė į pagonių ranką; ir tie, kurie jų nekentė, juos valdė.'),
  (@b19, 106, 42, 'Juos engė jų priešai, ir jie buvo pavergti po jų ranka.'),
  (@b19, 106, 43, 'Daug kartų jis juos išvadavo; bet jie kurstė jį savo sumanymu ir dėl savo neteisybės buvo pažeminti.'),
  (@b19, 106, 44, 'Tačiau jis atsižvelgė į jų sielvartą, išgirdęs jų šauksmą;'),
  (@b19, 106, 45, 'ir jis atsiminė dėl jų savo sandorą ir gailėjosi pagal savo gailestingumų gausybę.'),
  (@b19, 106, 46, 'Jis padarė, kad jų pasigailėtų visi, kurie juos išgabeno į nelaisvę.'),
  (@b19, 106, 47, 'Išgelbėk mus, o VIEŠPATIE, mūsų Dieve, ir surink mus iš pagonių tarpo, kad dėkotume tavo šventam vardui ir džiaugtumėmės tavo gyriumi.'),
  (@b19, 106, 48, 'Tebūna palaimintas VIEŠPATS, Izraelio Dievas, nuo amžinybės iki amžinybės; ir visa tauta tegul sako: „Amen“. Girkite VIEŠPATĮ.'),
  (@b19, 107, 1, 'Dėkokite VIEŠPAČIUI, nes jis yra geras, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 107, 2, 'Tegul taip sako VIEŠPATIES atpirktieji, kuriuos jis atpirko iš priešo rankos;'),
  (@b19, 107, 3, 'ir surinko juos iš šalių, iš rytų ir iš vakarų, iš šiaurės ir iš pietų.'),
  (@b19, 107, 4, 'Jie klaidžiojo po dykumą nuošaliu keliu; jie nerado miesto, kad apsigyventų.'),
  (@b19, 107, 5, 'Išalkę ir ištroškę, jų siela nusilpo juose.'),
  (@b19, 107, 6, 'Tada savo varge jie šaukėsi VIEŠPATIES, ir jis juos išvadavo iš jų sielvartų.'),
  (@b19, 107, 7, 'Ir jis juos vedė teisingu keliu, kad jie nueitų į gyvenamą miestą.'),
  (@b19, 107, 8, 'O kad žmonės girtų VIEŠPATĮ už jo gerumą ir už jo nuostabius darbus žmonių vaikams!'),
  (@b19, 107, 9, 'Nes jis patenkina išsiilgusią sielą ir išalkusią sielą pripildo gerumo.'),
  (@b19, 107, 10, 'Tie, kurie sėdi tamsoje ir mirties šešėlyje, sukaustyti vargu ir geležimi;'),
  (@b19, 107, 11, 'nes jie maištavo prieš Dievo žodžius ir niekino Aukščiausiojo patarimą;'),
  (@b19, 107, 12, 'todėl triūsu jis nužemino jų širdį; jie griuvo, ir nebuvo kas padėtų.'),
  (@b19, 107, 13, 'Tada savo varge jie šaukėsi VIEŠPATIES, ir jis juos išgelbėjo iš jų sielvartų.'),
  (@b19, 107, 14, 'Jis juos išvedė iš tamsos ir mirties šešėlio ir sutraukė jų pančius.'),
  (@b19, 107, 15, 'O kad žmonės girtų VIEŠPATĮ už jo gerumą ir už jo nuostabius darbus žmonių vaikams!'),
  (@b19, 107, 16, 'Nes jis sudaužė žalvarinius vartus ir geležinius skląsčius supjaustė.'),
  (@b19, 107, 17, 'Kvailiai dėl savo nusižengimo ir dėl savo neteisybių kenčia.'),
  (@b19, 107, 18, 'Jų siela bjaurisi bet kokiu valgiu; ir jie priartėjo prie mirties vartų.'),
  (@b19, 107, 19, 'Tada savo varge jie šaukiasi VIEŠPATIES, ir jis juos išgelbėja iš jų sielvartų.'),
  (@b19, 107, 20, 'Jis siuntė savo žodį ir juos išgydė, ir juos išvadavo iš jų pražūties.'),
  (@b19, 107, 21, 'O kad žmonės girtų VIEŠPATĮ už jo gerumą ir už jo nuostabius darbus žmonių vaikams!'),
  (@b19, 107, 22, 'Ir tegul jie aukoja padėkos aukas ir džiūgaudami skelbia jo darbus.'),
  (@b19, 107, 23, 'Tie, kurie laivais plaukia žemyn į jūrą, kurie užsiiminėja veikla dideliuose vandenyse;'),
  (@b19, 107, 24, 'šitie mato VIEŠPATIES darbus ir jo stebuklus gelmėse.'),
  (@b19, 107, 25, 'Nes jis įsako ir sukelia audringą vėją, kuris iškelia jos bangas.'),
  (@b19, 107, 26, 'Jie kyla į dangų, į gelmes vėl leidžiasi; jų siela sutirpo dėl nelaimės.'),
  (@b19, 107, 27, 'Jie svirduliuoja pirmyn atgal ir svyruoja kaip girtas, ir jų sumanumas išsekęs.'),
  (@b19, 107, 28, 'Tada jie savo bėdoje šaukiasi VIEŠPATIES, ir jis juos išveda iš jų sielvartų.'),
  (@b19, 107, 29, 'Jis paverčia audrą tyla taip, kad jos bangos nurimsta.'),
  (@b19, 107, 30, 'Tada jie džiaugiasi, nes jos nurimusios; taip jis juos nuveda į jų geidžiamą uostą.'),
  (@b19, 107, 31, 'O kad žmonės girtų VIEŠPATĮ už jo gerumą ir už jo nuostabius darbus žmonių vaikams!'),
  (@b19, 107, 32, 'Jie teaukština jį ir tautos susirinkime ir tegiria jį vyresniųjų sueigoje.'),
  (@b19, 107, 33, 'Jis paverčia upes į dykumą ir vandens šaltinius į sausumą;'),
  (@b19, 107, 34, 'vaisingą žemę į nederlingumą dėl nedorybės tų, kurie joje gyvena.'),
  (@b19, 107, 35, 'Jis paverčia dykumą į stovintį vandenį ir sausą žemę į vandens šaltinius.'),
  (@b19, 107, 36, 'Jis ten apgyvendina alkanuosius, kad paruoštų miestą apsigyvenimui,'),
  (@b19, 107, 37, 'apsėtų laukus ir pasodintų vynuogynų, kurie duotų prieaugio vaisių.'),
  (@b19, 107, 38, 'Taip pat jis juos palaimina, kad jie labai dauginasi; ir jų galvijams neleidžia mažėti.'),
  (@b19, 107, 39, 'Vėlgi, jie sumažėję ir yra pažeminti engimu, sielvartu.'),
  (@b19, 107, 40, 'Jis išlieja panieką ant kunigaikščių ir padaro, kad jie klaidžiotų dykumoje, kur nėra kelio.'),
  (@b19, 107, 41, 'Tačiau jis iškelia vargšą aukštai iš sielvarto ir padaro jam šeimas kaip kaimenę.'),
  (@b19, 107, 42, 'Teisieji tai matys ir džiaugsis; o visa nedorybė užčiaups savo burną.'),
  (@b19, 107, 43, 'Kas išmintingas ir laikysis šitų dalykų, tas supras VIEŠPATIES mylintį gerumą.'),
  (@b19, 108, 1, 'Dovydo giesmė arba psalmė. O Dieve, mano širdis sutvirtinta; aš giedosiu ir girsiu, būtent savo šlove.'),
  (@b19, 108, 2, 'Pabuskite, psalteri ir arfa; aš pats anksti pabusiu.'),
  (@b19, 108, 3, 'Aš girsiu tave, o VIEŠPATIE, tarp tautų; ir giedosiu tau gyrių tarp tautybių.'),
  (@b19, 108, 4, 'Nes didelis tavo gailestingumas, aukščiau dangų; ir tavo tiesa siekia iki debesų.'),
  (@b19, 108, 5, 'O Dieve, būk išaukštintas viršum dangų; ir tavo šlovė virš visos žemės;'),
  (@b19, 108, 6, 'kad tavo mylimieji būtų išvaduoti; išgelbėk savo dešine ir atsakyk man.'),
  (@b19, 108, 7, 'Dievas kalbėjo savo šventume: „Aš džiūgausiu, aš padalinsiu Šechemą ir išmatuosiu Sukoto slėnį.'),
  (@b19, 108, 8, 'Mano yra Gileadas; mano yra Manasas; ir Efraimas yra mano galvos stiprybė; Juda yra mano įstatymleidys;'),
  (@b19, 108, 9, 'Moabas yra mano prausimosi puodas; ant Edomo aš numesiu savo apavą; prieš Filistiją triumfuosiu“.'),
  (@b19, 108, 10, 'Kas mane nuves į tvirtą miestą? Kas mane nulydės į Edomą?'),
  (@b19, 108, 11, 'Ar ne tu, o Dieve, kuris mus atstūmei? Ar ne tu, o Dieve, išeisi su mūsų kariuomenėmis?'),
  (@b19, 108, 12, 'Suteik mums pagalbą bėdoje; nes žmogaus pagalba yra bevertė.'),
  (@b19, 108, 13, 'Per Dievą mes elgsimės narsiai; nes jis yra tas, kuris sumindys mūsų priešus.'),
  (@b19, 109, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. Netylėk, o mano gyriaus Dieve;'),
  (@b19, 109, 2, 'nes nedorėlio burna ir klastingojo burna atsivėrė prieš mane; jie kalbėjo prieš mane melagingu liežuviu.'),
  (@b19, 109, 3, 'Taip pat neapykantos žodžiais jie mane apsupo ir kovojo prieš mane be priežasties.'),
  (@b19, 109, 4, 'Už mano meilę jie yra mano priešininkai; bet aš atsiduodu maldai.'),
  (@b19, 109, 5, 'Jie man atlygino piktu už gera ir neapykanta už mano meilę.'),
  (@b19, 109, 6, 'Paskirk nedorėlį jo viršininku; ir tegul šėtonas atsistoja jo dešinėje.'),
  (@b19, 109, 7, 'Kai jis bus teisiamas, tebūna jis pasmerktas; ir jo malda tetampa nuodėme.'),
  (@b19, 109, 8, 'Tebūna mažai jo dienų; ir kitas tepaima jo tarnystę.'),
  (@b19, 109, 9, 'Jo vaikai tebūna našlaičiai ir jo žmona našlė.'),
  (@b19, 109, 10, 'Tegul jo vaikai nuolat bastosi ir elgetauja; ir teieško jie sau duonos iš savo suniokotų vietų.'),
  (@b19, 109, 11, 'Plėšikas tepasiglemžia visa, ką jis turi; ir svetimieji teišplėšia jo triūsą.'),
  (@b19, 109, 12, 'Tenebūna nei vieno, kuris jam suteiktų gailestingumą; ir tenebūna nei vieno, rodančio palankumą jo našlaičiams.'),
  (@b19, 109, 13, 'Jo palikuonys tebūna iškirsti; ir kitoje kartoje tebūna išdildytas jų vardas.'),
  (@b19, 109, 14, 'Jo tėvų neteisybė tebūna atmenama pas VIEŠPATĮ; ir jo motinos nuodėmė tenebūna išdildyta.'),
  (@b19, 109, 15, 'Jie nuolat tebūna VIEŠPATIES akivaizdoje, kad jis iškirstų iš žemės jų atminimą.'),
  (@b19, 109, 16, 'Kadangi jis neprisiminė parodyti gailestingumo, bet persekiojo vargšą ir stokojantį, kad nužudytų sudužusį širdyje.'),
  (@b19, 109, 17, 'Kaip jis pamilo prakeikimą, taip tas teateina ant jo; kaip jis nesigėrėjo palaiminimu, taip tas tebūna toli nuo jo.'),
  (@b19, 109, 18, 'Kaip jis apsivilko prakeikimu lyg savo drabužiu, taip tas teįeina kaip vanduo į jo vidurius ir kaip aliejus į jo kaulus.'),
  (@b19, 109, 19, 'Jis tebūna jam kaip jį dengiantis drabužis ir kaip juosta, kuria jis nuolat susijuosia.'),
  (@b19, 109, 20, 'Tai tebūna nuo VIEŠPATIES atlygis mano priešininkams ir tiems, kurie kalba pikta prieš mano sielą.'),
  (@b19, 109, 21, 'Bet padaryk mano labui, o DIEVE Viešpatie, dėl savo vardo; kadangi geras tavo gailestingumas, išvaduok mane.'),
  (@b19, 109, 22, 'Nes aš esu vargšas ir nepasiturintis, ir mano širdis sužeista mano viduje.'),
  (@b19, 109, 23, 'Aš dingau kaip nykstantis šešėlis; aš blaškomas pirmyn atgal kaip skėrys.'),
  (@b19, 109, 24, 'Mano keliai silpni nuo pasninko; ir mano kūnas netekęs riebalų.'),
  (@b19, 109, 25, 'Aš jiems tapau priekaištu; matydami mane, jie kratė savo galvas.'),
  (@b19, 109, 26, 'Padėk man, o VIEŠPATIE, mano Dieve; išgelbėk mane pagal savo gailestingumą;'),
  (@b19, 109, 27, 'kad jie žinotų, jog tai yra tavo ranka, jog tu, VIEŠPATIE, tai padarei.'),
  (@b19, 109, 28, 'Tegul jie keikia, bet tu laimink; kai jie pakyla, tebūna sugėdinti; bet tavo tarnas tesidžiaugia.'),
  (@b19, 109, 29, 'Tegul mano priešininkai apsivelka gėda, ir teapsidengia savo pačių gėda kaip mantija.'),
  (@b19, 109, 30, 'Aš didžiai girsiu VIEŠPATĮ savo burna; taip, tarp daugybės jį girsiu.'),
  (@b19, 109, 31, 'Nes jis stovės vargšo dešinėje, kad jį išgelbėtų iš tų, kurie smerkia jo sielą.'),
  (@b19, 110, 1, 'Dovydo psalmė. VIEŠPATS tarė mano Viešpačiui: „Sėskis mano dešinėje, kol padarysiu tavo priešus tavo pakoju“.'),
  (@b19, 110, 2, 'VIEŠPATS iš Siono siųs tavo stiprybės lazdą; valdyk savo priešų tarpe.'),
  (@b19, 110, 3, 'Tavo tauta bus savanoriška tavo galybės dieną, šventumo grožiuose iš ryto įsčių; tu turi savo jaunystės rasą.'),
  (@b19, 110, 4, 'VIEŠPATS prisiekė ir nepersigalvos: „Tu esi kunigas per amžius pagal Melkizedeko tvarką“.'),
  (@b19, 110, 5, 'Viešpats tavo dešinėje sumuš karalius savo rūstybės dieną.'),
  (@b19, 110, 6, 'Jis teis tarp pagonių, pripildys vietoves lavonais; jis sužeis daugelio šalių galvas.'),
  (@b19, 110, 7, 'Jis gers kelyje iš upelio; todėl jis iškels galvą.'),
  (@b19, 111, 1, 'Girkite VIEŠPATĮ. Aš girsiu VIEŠPATĮ visa širdimi tiesiųjų sambūryje ir susirinkime.'),
  (@b19, 111, 2, 'Dideli yra VIEŠPATIES darbai, ieškomi visų, kurie jais gėrisi.'),
  (@b19, 111, 3, 'Garbingas ir šlovingas jo darbas; ir jo teisumas pasilieka per amžius.'),
  (@b19, 111, 4, 'Jis padarė savo nuostabius darbus atsimintinais; VIEŠPATS yra maloningas ir pilnas užuojautos.'),
  (@b19, 111, 5, 'Jis davė maisto tiems, kurie jo bijo; jis per amžius atsimins savo sandorą.'),
  (@b19, 111, 6, 'Savo darbų galią jis parodė savo tautai, kad jiems duotų pagonių palikimą.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 111, 7, 'Jo rankų darbai – tiesa ir teismas; visi jo įsakymai tikri.'),
  (@b19, 111, 8, 'Jie per amžių amžius stovi tvirtai ir vykdomi tiesa ir tiesumu.'),
  (@b19, 111, 9, 'Jis siuntė atpirkimą savo tautai; amžiams įsakė savo sandorą; šventas ir gerbtinas yra jo vardas.'),
  (@b19, 111, 10, 'VIEŠPATIES baimė – išminties pradžia; gerą supratimą turi visi, kurie vykdo jo įsakymus; jo gyrius išlieka per amžius.'),
  (@b19, 112, 1, 'Girkite VIEŠPATĮ. Palaimintas žmogus, kuris bijo VIEŠPATIES, kuris labai gėrisi jo įsakymais.'),
  (@b19, 112, 2, 'Jo sėkla bus galinga žemėje; tiesiųjų karta bus palaiminta.'),
  (@b19, 112, 3, 'Gerovė ir turtai bus jo namuose; o jo teisumas pasilieka per amžius.'),
  (@b19, 112, 4, 'Tiesiajam nušvinta tamsoje šviesa; jis yra maloningas ir pilnas užuojautos, ir teisus.'),
  (@b19, 112, 5, 'Geras žmogus parodo palankumą ir skolina; jis apdairiai tvarkys savo reikalus.'),
  (@b19, 112, 6, 'Tikrai jis nesvyruos per amžius; amžinai bus atmenamas teisusis.'),
  (@b19, 112, 7, 'Jis nebijos piktų žinių; sutvirtinta jo širdis, pasitikinti VIEŠPAČIU.'),
  (@b19, 112, 8, 'Jo širdis įsitvirtinusi, jis nebijos, kol pamatys savo norą ant savo priešų.'),
  (@b19, 112, 9, 'Jis išbarstė, jis davė vargšams; jo teisumas pasilieka per amžius; jo ragas bus išaukštintas su garbe.'),
  (@b19, 112, 10, 'Nedorėlis tai matys ir sielosis; jis grieš dantimis ir sutirps; nedorėlių troškimas pražus.'),
  (@b19, 113, 1, 'Girkite VIEŠPATĮ. Girkite, o jūs, VIEŠPATIES tarnai, girkite VIEŠPATIES vardą.'),
  (@b19, 113, 2, 'Tebūna palaimintas VIEŠPATIES vardas nuo dabar ir per amžius.'),
  (@b19, 113, 3, 'Nuo saulės patekėjimo iki jos nusileidimo girtinas VIEŠPATIES vardas.'),
  (@b19, 113, 4, 'VIEŠPATS aukštai viršum visų tautų, ir jo šlovė viršum dangų.'),
  (@b19, 113, 5, 'Kas yra toks kaip VIEŠPATS, mūsų Dievas, kuris gyvena aukštybėje,'),
  (@b19, 113, 6, 'kuris nusižemina, kad pažiūrėtų į tai, kas danguje ir žemėje?'),
  (@b19, 113, 7, 'Jis pakelia iš dulkių vargšą ir iš mėšlo krūvos iškelia stokojantį,'),
  (@b19, 113, 8, 'kad jį pasodintų su kunigaikščiais – su savo tautos kunigaikščiais.'),
  (@b19, 113, 9, 'Jis padaro, kad nevaisingoji moteris prižiūrėtų namus ir kad būtų džiaugsminga vaikų motina. Girkite VIEŠPATĮ.'),
  (@b19, 114, 1, 'Kai Izraelis išėjo iš Egipto, Jokūbo namai iš svetimkalbės tautos;'),
  (@b19, 114, 2, 'Juda buvo jo šventovė ir Izraelis jo viešpatystė.'),
  (@b19, 114, 3, 'Jūra tai pamatė ir pabėgo; Jordanas pasitraukė atgal.'),
  (@b19, 114, 4, 'Kalnai straksėjo kaip avinai, o mažos kalvos – kaip ėriukai.'),
  (@b19, 114, 5, 'Kas tau yra, o jūra, kad pabėgai, tau, Jordane, kad atsitraukei atgal?'),
  (@b19, 114, 6, 'Kas yra jums, kalnai, kad straksėjote kaip avinai; ir jūs, mažos kalvos, kaip avinėliai?'),
  (@b19, 114, 7, 'Drebėk, žeme, nuo Viešpaties akivaizdos, nuo Jokūbo Dievo akivaizdos,'),
  (@b19, 114, 8, 'kuris pavertė uolą stovinčiu vandeniu, titnagą vandenų šaltiniu.'),
  (@b19, 115, 1, 'Ne mums, o VIEŠPATIE, ne mums, bet savo vardui duok šlovę dėl savo gailestingumo ir dėl savo tiesos.'),
  (@b19, 115, 2, 'Kodėl turėtų sakyti pagonys: „Kurgi dabar jų Dievas?“'),
  (@b19, 115, 3, 'Bet mūsų Dievas danguose; jis padarė visa, kas jam patiko.'),
  (@b19, 115, 4, 'Jų stabai – sidabras ir auksas, žmonių rankų darbas.'),
  (@b19, 115, 5, 'Jie turi burnas, bet nekalba; turi akis, bet nemato;'),
  (@b19, 115, 6, 'jie turi ausis, bet negirdi; turi nosis, bet neužuodžia;'),
  (@b19, 115, 7, 'jie turi rankas, bet nenutveria; jie turi kojas, bet nevaikšto; ir jie nekalba savo gerkle.'),
  (@b19, 115, 8, 'Panašūs į juos yra tie, kurie juos daro; toks yra kiekvienas, kuris jais pasitiki.'),
  (@b19, 115, 9, 'O Izraeli, pasitikėk VIEŠPAČIU; jis yra jų pagalba ir jų skydas.'),
  (@b19, 115, 10, 'O Aarono namai, pasitikėkite VIEŠPAČIU; jis yra jų pagalba ir jų skydas.'),
  (@b19, 115, 11, 'Jūs, kurie bijote VIEŠPATIES, pasitikėkite VIEŠPAČIU; jis yra jų pagalba ir jų skydas.'),
  (@b19, 115, 12, 'VIEŠPATS atsiminė mus; jis mus palaimins; jis palaimins Izraelio namus; jis palaimins Aarono namus.'),
  (@b19, 115, 13, 'Jis palaimins tuos, kurie bijo VIEŠPATIES, ir mažus, ir didelius.'),
  (@b19, 115, 14, 'VIEŠPATS jus padaugins labiau ir labiau, jus ir jūsų vaikus.'),
  (@b19, 115, 15, 'Jūs esate palaiminti VIEŠPATIES, kuris padarė dangų ir žemę.'),
  (@b19, 115, 16, 'Dangus, būtent dangūs yra VIEŠPATIES; bet žemę jis davė žmonių vaikams.'),
  (@b19, 115, 17, 'Mirusieji VIEŠPATIES negiria, nei tie, kurie nužengia į tylumą.'),
  (@b19, 115, 18, 'Bet mes laiminsime VIEŠPATĮ nuo dabar ir per amžius. Girkite VIEŠPATĮ.'),
  (@b19, 116, 1, 'Aš myliu VIEŠPATĮ, nes jis išgirdo mano balsą ir mano prašymus.'),
  (@b19, 116, 2, 'Kadangi jis palenkė į mane savo ausį, todėl jo šauksiuos, kol gyvenu.'),
  (@b19, 116, 3, 'Mane apsupo mirties sielvartai, ir pragaro skausmai apėmė mane; aš radau vargą ir sielvartą.'),
  (@b19, 116, 4, 'Tada aš šaukiausi VIEŠPATIES vardo: „O VIEŠPATIE, meldžiu tave, išvaduok mano sielą“.'),
  (@b19, 116, 5, 'Maloningas yra VIEŠPATS ir teisus; taip, mūsų Dievas yra gailestingas.'),
  (@b19, 116, 6, 'VIEŠPATS apsaugo paprastuosius: aš buvau nužemintas, o jis man padėjo.'),
  (@b19, 116, 7, 'Sugrįžk į savo poilsį, o mano siela; nes VIEŠPATS dosniai elgėsi su tavimi.'),
  (@b19, 116, 8, 'Nes tu išvadavai mano sielą iš mirties, mano akis nuo ašarų ir mano kojas nuo griuvimo.'),
  (@b19, 116, 9, 'Aš vaikščiosiu VIEŠPATIES akivaizdoje gyvųjų šalyje.'),
  (@b19, 116, 10, 'Aš tikėjau, todėl tariau: „Aš buvau labai kamuojamas“;'),
  (@b19, 116, 11, 'aš paskubomis sakiau: „Visi žmonės melagiai“.'),
  (@b19, 116, 12, 'Kuo atlyginsiu VIEŠPAČIUI už visas jo geradarystes man?'),
  (@b19, 116, 13, 'Aš paimsiu išgelbėjimo taurę ir šauksiuosi VIEŠPATIES vardo.'),
  (@b19, 116, 14, 'Ištesėsiu savo įžadus VIEŠPAČIUI dabar visos jo tautos akivaizdoje.'),
  (@b19, 116, 15, 'Brangi yra VIEŠPATIES akyse jo šventųjų mirtis.'),
  (@b19, 116, 16, 'O VIEŠPATIE, tikrai aš esu tavo tarnas; aš tavo tarnas ir tavo tarnaitės sūnus; tu atrišai mano pančius.'),
  (@b19, 116, 17, 'Tau atnašausiu padėkos auką ir šauksiuosi VIEŠPATIES vardo.'),
  (@b19, 116, 18, 'Ištesėsiu savo įžadus VIEŠPAČIUI dabar visos jo tautos akivaizdoje,'),
  (@b19, 116, 19, 'VIEŠPATIES namų kiemuose, tavo viduryje, o Jeruzale. Girkite VIEŠPATĮ.'),
  (@b19, 117, 1, 'Girkite VIEŠPATĮ, visos tautybės; girkite jį, visos tautos.'),
  (@b19, 117, 2, 'Nes jo gailestingas gerumas mums yra didis; ir VIEŠPATIES tiesa išlieka per amžius. Girkite VIEŠPATĮ.'),
  (@b19, 118, 1, 'Dėkokite VIEŠPAČIUI; nes jis yra geras; nes jo gailestingumas išlieka per amžius.'),
  (@b19, 118, 2, 'Tegul dabar Izraelis sako, kad jo gailestingumas išlieka per amžius.'),
  (@b19, 118, 3, 'Tegul dabar Aarono namai sako, kad jo gailestingumas išlieka per amžius.'),
  (@b19, 118, 4, 'Tegul dabar tie, kurie bijo VIEŠPATIES, sako, kad jo gailestingumas išlieka per amžius.'),
  (@b19, 118, 5, 'Sielvarte šaukiausi VIEŠPATIES; VIEŠPATS man atsakė ir pastatė mane į plačią vietą.'),
  (@b19, 118, 6, 'VIEŠPATS yra mano pusėje; aš nebijosiu; ką gali man padaryti žmogus?'),
  (@b19, 118, 7, 'VIEŠPATS stoja mano pusėn su tais, kurie man padeda; todėl aš matysiu savo norą ant tų, kurie manęs nekenčia.'),
  (@b19, 118, 8, 'Yra geriau pasitikėti VIEŠPAČIU, negu pasikliauti žmonėmis.'),
  (@b19, 118, 9, 'Yra geriau pasitikėti VIEŠPAČIU, negu pasikliauti kunigaikščiais.'),
  (@b19, 118, 10, 'Visos tautos mane apsupo; bet VIEŠPATIES vardu aš juos sunaikinsiu.'),
  (@b19, 118, 11, 'Jie mane apsupo; taip, jie mane apsupo; bet VIEŠPATIES vardu aš juos sunaikinsiu.'),
  (@b19, 118, 12, 'Jie mane apsupo kaip bitės; jie užgeso kaip erškėčių ugnis; nes VIEŠPATIES vardu aš juos sunaikinsiu.'),
  (@b19, 118, 13, 'Tu mane stipriai stūmei, kad pargriūčiau; bet VIEŠPATS man padėjo.'),
  (@b19, 118, 14, 'VIEŠPATS yra mano stiprybė ir giesmė, ir tapo mano išgelbėjimu.'),
  (@b19, 118, 15, 'Džiūgavimo ir išgelbėjimo balsas yra teisiųjų padangtėse; VIEŠPATIES dešinė vykdo narsumą.'),
  (@b19, 118, 16, 'VIEŠPATIES dešinė yra išaukštinta; VIEŠPATIES dešinė vykdo narsumą.'),
  (@b19, 118, 17, 'Aš nemirsiu, bet gyvensiu ir skelbsiu VIEŠPATIES darbus.'),
  (@b19, 118, 18, 'Griežtai mane baudė VIEŠPATS; bet jis manęs neatidavė mirčiai.'),
  (@b19, 118, 19, 'Atverkite man teisumo vartus; aš įeisiu į juos ir girsiu VIEŠPATĮ;'),
  (@b19, 118, 20, 'tai VIEŠPATIES vartai, į kuriuos įeis teisieji.'),
  (@b19, 118, 21, 'Aš girsiu tave; nes tu mane išgirdai ir tapai man išgelbėjimu.'),
  (@b19, 118, 22, 'Akmuo, kurį statytojai atmetė, tapo kertiniu akmeniu.'),
  (@b19, 118, 23, 'Tai VIEŠPATIES darbas; tai nuostabu mūsų akyse.'),
  (@b19, 118, 24, 'Tai diena, kurią VIEŠPATS padarė; džiūgausime ir linksminsimės joje.'),
  (@b19, 118, 25, 'O VIEŠPATIE, meldžiu tave, išgelbėk; o VIEŠPATIE, meldžiu tave, siųsk klestėjimą.'),
  (@b19, 118, 26, 'Tebūna palaimintas, kuris ateina VIEŠPATIES vardu; mes jus laiminome iš VIEŠPATIES namų.'),
  (@b19, 118, 27, 'Dievas yra VIEŠPATS, parodęs mums šviesą: suriškite auką virvėmis prie aukuro ragų.'),
  (@b19, 118, 28, 'Tu mano Dievas, ir aš tave girsiu; tu mano Dievas, aš tave aukštinsiu.'),
  (@b19, 118, 29, 'Dėkokite VIEŠPAČIUI; nes jis yra geras; nes jo gailestingumas išlieka per amžius.'),
  (@b19, 119, 1, 'Alef Palaiminti nesusiteršę kelyje, kurie vaikšto VIEŠPATIES įstatymu.'),
  (@b19, 119, 2, 'Palaiminti, kurie laikosi jo liudijimų ir visa širdimi jo ieško.'),
  (@b19, 119, 3, 'Taip pat jie nedaro neteisybės; jie vaikšto jo keliais.'),
  (@b19, 119, 4, 'Tu mums įsakei uoliai laikytis tavo prisakymų.'),
  (@b19, 119, 5, 'O kad mano keliai būtų nukreipti laikytis tavo įstatų!'),
  (@b19, 119, 6, 'Tada aš nesigėdysiu, paisydamas visų tavo įsakymų.'),
  (@b19, 119, 7, 'Širdies tiesumu tave girsiu, kai išmoksiu tavo teisių teismų.'),
  (@b19, 119, 8, 'Tavo įstatų laikysiuosi; neapleisk manęs visiškai.'),
  (@b19, 119, 9, 'Kaip jaunuoliui apvalyti savo kelią? Atkreipiant į tai dėmesį pagal tavo žodį.'),
  (@b19, 119, 10, 'Visa širdimi tavęs ieškojau; neleisk man nuklysti nuo tavo įsakymų.'),
  (@b19, 119, 11, 'Savo širdyje paslėpiau tavo žodį, kad prieš tave nenusidėčiau.'),
  (@b19, 119, 12, 'Tu esi palaimintas, o VIEŠPATIE; mokyk mane savo įstatų.'),
  (@b19, 119, 13, 'Savo lūpomis skelbiau visus tavo burnos teismus.'),
  (@b19, 119, 14, 'Džiaugiausi tavo liudijimų keliu kaip visais turtais.'),
  (@b19, 119, 15, 'Mąstysiu apie tavo prisakymus ir paisysiu tavo kelių.'),
  (@b19, 119, 16, 'Tavo įstatais gėrėsiuos; nepamiršiu tavo žodžio.'),
  (@b19, 119, 17, 'Dosniai elkis su savo tarnu, kad gyvenčiau ir laikyčiausi tavo žodžio.'),
  (@b19, 119, 18, 'Atverk man akis, kad pamatyčiau nuostabas iš tavo įstatymo.'),
  (@b19, 119, 19, 'Aš svetimas žemėje; neslėpk nuo manęs savo įsakymų.'),
  (@b19, 119, 20, 'Palūžo mano siela, besiilgėdama tavo teismų visais laikais.'),
  (@b19, 119, 21, 'Tu subarei išdidžiuosius – prakeiktus, kurie nuklysta nuo tavo įsakymų.'),
  (@b19, 119, 22, 'Nuimk nuo manęs priekaištą ir panieką; nes aš laikiausi tavo liudijimų.'),
  (@b19, 119, 23, 'Taip pat kunigaikščiai susėdę kalbėjo prieš mane; bet tavo tarnas mąstė apie tavo įstatus.'),
  (@b19, 119, 24, 'Be to, tavo liudijimai yra mano pasigėrėjimas ir mano patarėjai.'),
  (@b19, 119, 25, 'Mano siela prilipo prie dulkių; atgaivink mane pagal savo žodį.'),
  (@b19, 119, 26, 'Savo kelius paskelbiau, ir tu išklausei mane; mokyk mane savo įstatų.'),
  (@b19, 119, 27, 'Duok man suprasti tavo prisakymų kelią; taip aš kalbėsiu apie tavo nuostabius darbus.'),
  (@b19, 119, 28, 'Mano siela tirpsta iš sielvarto; sustiprink mane pagal savo žodį.'),
  (@b19, 119, 29, 'Melo kelią pašalink nuo manęs; ir suteik man savo įstatymą maloningai.'),
  (@b19, 119, 30, 'Tiesos kelią pasirinkau; tavo teismus pasidėjau priešais save.'),
  (@b19, 119, 31, 'Prilipau prie tavo liudijimų; o VIEŠPATIE, nesugėdink manęs.'),
  (@b19, 119, 32, 'Tavo įsakymų keliu bėgsiu, kai praplėsi mano širdį.'),
  (@b19, 119, 33, 'Mokyk mane, o VIEŠPATIE, savo įstatų kelio, ir jo laikysiuosi iki galo.'),
  (@b19, 119, 34, 'Duok man supratimą, ir tavo įstatymą saugosiu; taip, visa širdimi jo laikysiuos.'),
  (@b19, 119, 35, 'Padaryk, kad eičiau tavo įsakymų taku; nes juo gėriuosi.'),
  (@b19, 119, 36, 'Palenk mano širdį prie savo liudijimų, o ne prie godumo.'),
  (@b19, 119, 37, 'Nukreipk mano akis, kad nematytų tuštybių; ir atgaivink mane savo kelyje.'),
  (@b19, 119, 38, 'Sutvirtink savo žodį savo tarnui, kuris atsidavęs tavo baimei.'),
  (@b19, 119, 39, 'Nukreipk mano priekaištą, kurio bijausi; nes tavo teismai yra geri.'),
  (@b19, 119, 40, 'Štai aš ilgėjausi tavo prisakymų; atgaivink mane savo teisumu.'),
  (@b19, 119, 41, 'Tegul ir man ateina tavo gailestingumai, o VIEŠPATIE, būtent tavo išgelbėjimas, pagal tavo žodį.'),
  (@b19, 119, 42, 'Taip aš turėsiu kuo atsakyti tam, kuris man priekaištauja; nes aš pasitikiu tavo žodžiu.'),
  (@b19, 119, 43, 'Ir visiškai neatimk nuo mano burnos tiesos žodžio; nes tikėjausi tavo teismų.'),
  (@b19, 119, 44, 'Taip nuolat laikysiuosi tavo įstatymo per amžių amžius.'),
  (@b19, 119, 45, 'Ir vaikščiosiu laisvas; nes siekiu tavo prisakymų.'),
  (@b19, 119, 46, 'Kalbėsiu apie tavo liudijimus ir karalių akivaizdoje ir nesigėdinsiu.'),
  (@b19, 119, 47, 'Gėrėsiuosi tavo įsakymais, kuriuos pamilau.'),
  (@b19, 119, 48, 'Taip pat pakelsiu rankas į tavo įsakymus, kuriuos pamilau; ir mąstysiu apie tavo įstatus.'),
  (@b19, 119, 49, 'Atsimink žodį savo tarnui, kuriuo viltis paskatinai mane.'),
  (@b19, 119, 50, 'Tai yra paguoda mano varge; nes tavo žodis atgaivino mane.'),
  (@b19, 119, 51, 'Išdidieji mane labai išjuokė; tačiau nuo tavo įstatymo nenukrypau.'),
  (@b19, 119, 52, 'Atsiminiau tavo senus teismus, o VIEŠPATIE, ir pasiguodžiau.'),
  (@b19, 119, 53, 'Mane apėmė siaubas dėl nedorėlių, kurie paliko tavo įstatymą.'),
  (@b19, 119, 54, 'Tavo įstatai buvo mano giesmėmis mano kelionės namuose.'),
  (@b19, 119, 55, 'Atsiminiau naktį tavo vardą, o VIEŠPATIE, ir laikiausi tavo įstatymo.'),
  (@b19, 119, 56, 'Tai turėjau, kadangi laikiausi tavo prisakymų.'),
  (@b19, 119, 57, 'Tu esi mano dalis, o VIEŠPATIE; aš sakiau, kad laikysiuosi tavo žodžių.'),
  (@b19, 119, 58, 'Visa širdimi maldavau tavo palankumo; būk man gailestingas pagal savo žodį.'),
  (@b19, 119, 59, 'Galvojau apie savo kelius ir nukreipiau savo kojas į tavo liudijimus.'),
  (@b19, 119, 60, 'Skubėjau ir nedelsiau laikytis tavo įsakymų.'),
  (@b19, 119, 61, 'Nedorėlių gaujos mane apiplėšė; bet tavo įstatymo nepamiršau.'),
  (@b19, 119, 62, 'Vidurnaktį atsikelsiu tau dėkoti dėl teisių tavo teismų.'),
  (@b19, 119, 63, 'Aš draugas visų, kurie tavęs bijo, ir tų, kurie laikosi tavo prisakymų.'),
  (@b19, 119, 64, 'Žemė pilna tavo gailestingumo, o VIEŠPATIE; mokyk mane savo įstatų.'),
  (@b19, 119, 65, 'Tu gerai pasielgei su savo tarnu, o VIEŠPATIE, pagal savo žodį.'),
  (@b19, 119, 66, 'Mokyk mane gero teismo ir pažinimo; nes aš tikėjau tavo įsakymais.'),
  (@b19, 119, 67, 'Pirmiau savo kančios, aš paklysdavau; bet dabar laikiausi tavo žodžio.'),
  (@b19, 119, 68, 'Tu esi geras ir darai gera; pamokyk mane savo įstatų.'),
  (@b19, 119, 69, 'Išdidieji suklastojo prieš mane melą; bet aš visa širdimi laikysiuosi tavo prisakymų.'),
  (@b19, 119, 70, 'Jų širdis nutukusi kaip riebalai; bet aš gėriuosi tavo įstatymu.'),
  (@b19, 119, 71, 'Man gerai, kad aš kentėjau, idant išmokčiau tavo įstatų.'),
  (@b19, 119, 72, 'Tavo burnos įstatymas man geresnis už tūkstančius aukso ir sidabro.'),
  (@b19, 119, 73, 'Tavo rankos mane padarė ir suformavo; duok man supratimą, kad išmokčiau tavo įsakymų.'),
  (@b19, 119, 74, 'Tie, kurie tavęs bijo, džiaugsis mane matydami; nes aš vyliausi tavo žodžio.'),
  (@b19, 119, 75, 'Žinau, o VIEŠPATIE, kad teisingi tavo teismai ir kad būdamas ištikimas sukėlei man kančias.'),
  (@b19, 119, 76, 'Meldžiu tave, tegul tavo gailestingas gerumas būna mano paguodai, pagal tavo žodį tavo tarnui.'),
  (@b19, 119, 77, 'Tegul man ateina tavo švelnūs gailestingumai, kad gyvenčiau; nes tavo įstatymas – mano pasigėrėjimas.'),
  (@b19, 119, 78, 'Tesusigėsta išdidieji; nes jie be priežasties iškreiptai elgėsi su manimi; bet aš mąstysiu apie tavo prisakymus.'),
  (@b19, 119, 79, 'Tegul gręžiasi į mane tie, kurie tavęs bijo, ir tie, kurie pažinojo tavo liudijimus.'),
  (@b19, 119, 80, 'Tegul mano širdis būna sveika tavo įstatuose, kad nebūčiau sugėdintas.'),
  (@b19, 119, 81, 'Mano siela alpsta dėl tavo išgelbėjimo; bet aš viliuosi tavo žodžiu.'),
  (@b19, 119, 82, 'Mano akys išblėso dėl tavo žodžio, sakydamos: „Kada mane paguosi?“'),
  (@b19, 119, 83, 'Nes aš pasidariau kaip indas dūmuose; tačiau tavo įstatų nepamirštu.'),
  (@b19, 119, 84, 'Kiek yra tavo tarno dienų? Kada vykdysi teismą mano persekiotojams?'),
  (@b19, 119, 85, 'Išdidieji man iškasė duobių, kurios nėra pagal tavo įstatymą.'),
  (@b19, 119, 86, 'Visi tavo įsakymai patikimi; neteisėtai jie persekioja mane; padėk man.'),
  (@b19, 119, 87, 'Jie beveik sunaikino mane žemėje; bet aš nepalikau tavo prisakymų.'),
  (@b19, 119, 88, 'Pagal savo mylintį gerumą atgaivink mane; taip pat aš vykdysiu tavo burnos liudijimą.'),
  (@b19, 119, 89, 'Per amžius, o VIEŠPATIE, tavo žodis įtvirtintas danguje.'),
  (@b19, 119, 90, 'Tavo ištikimybė kartų kartoms: tu įtvirtinai žemę, ir ji pasilieka.'),
  (@b19, 119, 91, 'Jie pasilieka šią dieną pagal tavo nustatymus; nes visi yra tavo tarnai.'),
  (@b19, 119, 92, 'Jei tavo įstatymas nebūtų buvęs mano pasigėrėjimas, tai būčiau pražuvęs savo varge.'),
  (@b19, 119, 93, 'Niekada nepamiršiu tavo prisakymų; nes jais mane atgaivinai.'),
  (@b19, 119, 94, 'Aš esu tavo, gelbėk mane; nes siekiau tavo prisakymų.'),
  (@b19, 119, 95, 'Nedorėliai manęs laukė, kad mane sunaikintų; bet aš apsvarstysiu tavo liudijimus.'),
  (@b19, 119, 96, 'Mačiau visokio tobulumo galą; bet tavo įsakymas be galo platus.'),
  (@b19, 119, 97, 'Kaip aš myliu tavo įstatymą! Jis visą dieną yra mano apmąstymas.'),
  (@b19, 119, 98, 'Per savo įsakymus mane padarei išmintingesnį už mano priešus; nes jie visados yra su manimi.'),
  (@b19, 119, 99, 'Turiu daugiau supratimo už visus savo mokytojus; nes tavo liudijimai yra mano apmąstymas.'),
  (@b19, 119, 100, 'Aš suprantu daugiau už senolius, nes laikausi tavo prisakymų.'),
  (@b19, 119, 101, 'Nuo kiekvieno pikto kelio sulaikiau savo kojas, kad laikyčiausi tavo žodžio.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 119, 102, 'Nuo tavo teismų neatsitraukiau; nes tu mokei mane.'),
  (@b19, 119, 103, 'Kokie saldūs mano skoniui tavo žodžiai, taip, saldesni už medų mano burnai!'),
  (@b19, 119, 104, 'Per tavo prisakymus įgyju supratimą; todėl neapkenčiu jokio apgaulingo kelio.'),
  (@b19, 119, 105, 'Tavo žodis yra žibintas mano kojoms ir šviesa mano takui.'),
  (@b19, 119, 106, 'Aš prisiekiau ir tai vykdysiu, kad laikysiuosi tavo teisių teismų.'),
  (@b19, 119, 107, 'Esu labai prislėgtas; o VIEŠPATIE, atgaivink mane pagal savo žodį.'),
  (@b19, 119, 108, 'Priimk, meldžiu tave, mano burnos savanoriškas aukas, o VIEŠPATIE, ir mokyk mane savo teismų.'),
  (@b19, 119, 109, 'Mano siela yra nuolat mano rankoje; tačiau tavo įstatymo nepamirštu.'),
  (@b19, 119, 110, 'Nedorėliai paspendė man žabangas; tačiau nuo tavo prisakymų nenuklydau.'),
  (@b19, 119, 111, 'Tavo liudijimus paėmiau kaip paveldą amžiams; nes jie yra mano širdies džiaugsmas.'),
  (@b19, 119, 112, 'Aš palenkiau savo širdį nuolat vykdyti tavo įstatus – iki galo.'),
  (@b19, 119, 113, 'Nekenčiu tuščių minčių; bet tavo įstatymą myliu.'),
  (@b19, 119, 114, 'Tu esi mano slėptuvė ir skydas; aš viliuosi tavo žodžiu.'),
  (@b19, 119, 115, 'Pasitraukite nuo manęs, piktadariai; nes aš laikysiuosi savo Dievo įsakymų.'),
  (@b19, 119, 116, 'Paremk mane pagal savo žodį, kad gyvenčiau; ir neleisk man gėdytis dėl mano vilties.'),
  (@b19, 119, 117, 'Palaikyk mane ir aš būsiu saugus; ir nuolat atsižvelgsiu į tavo įstatus.'),
  (@b19, 119, 118, 'Tu sutrypei visus, kurie nuklydo nuo tavo įstatų; nes jų apgaulė – melas.'),
  (@b19, 119, 119, 'Visus žemės nedorėlius tu pašalini kaip atliekas; todėl aš myliu tavo liudijimus.'),
  (@b19, 119, 120, 'Mano kūnas dreba dėl tavo baimės; ir aš bijau tavo teismų.'),
  (@b19, 119, 121, 'Vykdžiau teismą ir teisingumą; nepalik manęs mano engėjams.'),
  (@b19, 119, 122, 'Būk užtikrintumu savo tarnui dėl gero; tegul išdidieji neengia manęs.'),
  (@b19, 119, 123, 'Mano akys išblėso dėl tavo išgelbėjimo ir dėl tavo teisumo žodžio.'),
  (@b19, 119, 124, 'Pasielk su savo tarnu pagal savo gailestingumą ir mokyk mane savo įstatų.'),
  (@b19, 119, 125, 'Aš tavo tarnas; suteik man supratimą, kad pažinčiau tavo liudijimus.'),
  (@b19, 119, 126, 'Metas tau veikti, VIEŠPATIE, nes jie pavertė niekais tavo įstatymą.'),
  (@b19, 119, 127, 'Todėl aš myliu tavo įsakymus labiau už auksą; taip, labiau už geriausią auksą.'),
  (@b19, 119, 128, 'Todėl visus tavo prisakymus dėl visų dalykų laikau teisingais; ir nekenčiu visų melagingų kelių.'),
  (@b19, 119, 129, 'Nuostabūs tavo liudijimai; todėl jų laikosi mano siela.'),
  (@b19, 119, 130, 'Tavo žodžiai įžengę apšviečia, paikiesiems suteikia supratimą.'),
  (@b19, 119, 131, 'Aš atvėriau savo burną ir troškau; nes ilgėjausi tavo įsakymų.'),
  (@b19, 119, 132, 'Pažvelk į mane ir būk man gailestingas, kaip esi pratęs daryti tiems, kurie myli tavo vardą.'),
  (@b19, 119, 133, 'Sutvarkyk mano žingsnius pagal savo žodį; ir neleisk jokiai neteisybei man viešpatauti.'),
  (@b19, 119, 134, 'Išvaduok mane iš žmonių engimo; taip laikysiuosi tavo prisakymų.'),
  (@b19, 119, 135, 'Šviesk savo veidu ant savo tarno; ir mokyk mane savo įstatų.'),
  (@b19, 119, 136, 'Vandenų upės teka iš mano akių, nes jie nesilaikė tavo įstatymo.'),
  (@b19, 119, 137, 'Teisus tu, o VIEŠPATIE, ir tiesūs tavo teismai.'),
  (@b19, 119, 138, 'Tavo įsakyti liudijimai yra teisūs ir labai ištikimi.'),
  (@b19, 119, 139, 'Mano uolumas suėdė mane, nes mano priešai pamiršo tavo žodžius.'),
  (@b19, 119, 140, 'Tavo žodis labai tyras; todėl tavo tarnas jį myli.'),
  (@b19, 119, 141, 'Aš mažas ir paniekintas; tačiau nepamirštu tavo prisakymų.'),
  (@b19, 119, 142, 'Tavo teisumas yra amžinas teisumas, ir tavo įstatymas – tiesa.'),
  (@b19, 119, 143, 'Vargas ir kančia sugriebė mane; tačiau tavo įsakymai yra mano pasigėrėjimas.'),
  (@b19, 119, 144, 'Tavo liudijimų teisumas yra amžinas; duok man supratimo, ir aš gyvensiu.'),
  (@b19, 119, 145, 'Visa širdimi šaukiau: „Išgirsk mane, o VIEŠPATIE; aš laikysiuosi tavo įstatų“.'),
  (@b19, 119, 146, 'Tavęs šaukiausi; išgelbėk mane, ir aš laikysiuos tavo liudijimų.'),
  (@b19, 119, 147, 'Aplenkęs pasitikau ryto aušrą ir šaukiausi: vyliausi tavo žodžiu.'),
  (@b19, 119, 148, 'Mano akys aplenkę pasitinka nakties budėjimus, kad mąstyčiau apie tavo žodį.'),
  (@b19, 119, 149, 'Išgirsk mano balsą pagal savo mylintį gerumą; o VIEŠPATIE, atgaivink mane pagal savo teismą.'),
  (@b19, 119, 150, 'Artėja tie, kurie seka piktadaryste; jie toli nuo tavo įstatymo.'),
  (@b19, 119, 151, 'Arti esi tu, o VIEŠPATIE; ir visi tavo įsakymai yra tiesa.'),
  (@b19, 119, 152, 'Apie tavo liudijimus nuo seno žinau, kad tu amžiams juos pastatei ant pamato.'),
  (@b19, 119, 153, 'Pažvelk į mano sielvartą ir išvaduok mane; nes nepamirštu tavo įstatymo.'),
  (@b19, 119, 154, 'Apgink mano bylą ir išvaduok mane; atgaivink mane pagal savo žodį.'),
  (@b19, 119, 155, 'Išgelbėjimas toli nuo nedorėlių; nes jie neieško tavo įstatų.'),
  (@b19, 119, 156, 'Dideli tavo švelnūs gailestingumai, o VIEŠPATIE; atgaivink mane pagal savo teismus.'),
  (@b19, 119, 157, 'Daug mano persekiotojų ir mano priešų; tačiau aš nenukrypstu nuo tavo liudijimų.'),
  (@b19, 119, 158, 'Žiūrėjau į nusižengėlius ir sielojausi; nes jie nesilaikė tavo žodžio.'),
  (@b19, 119, 159, 'Žiūrėk, kaip aš myliu tavo prisakymus; o VIEŠPATIE, atgaivink mane pagal savo mylintį gerumą.'),
  (@b19, 119, 160, 'Tavo žodis teisingas nuo pradžios; ir kiekvienas tavo teisus teismas išlieka per amžius.'),
  (@b19, 119, 161, 'Kunigaikščiai be priežasties mane persekiojo; bet mano širdis pagarbiai bijo tavo žodžio.'),
  (@b19, 119, 162, 'Džiaugiuosi tavo žodžiu kaip tas, kuris randa didelį grobį.'),
  (@b19, 119, 163, 'Melo nekenčiu ir bjauriuosi: bet tavo įstatymą myliu.'),
  (@b19, 119, 164, 'Septynis kartus per dieną tave giriu dėl tavo teisių teismų.'),
  (@b19, 119, 165, 'Didelę ramybę turi tie, kurie myli tavo įstatymą; ir niekas jų nepapiktins.'),
  (@b19, 119, 166, 'Aš vyliausi tavo išgelbėjimo, VIEŠPATIE, ir tavo įsakymus vykdžiau.'),
  (@b19, 119, 167, 'Mano siela laikėsi tavo liudijimų; ir juos be galo myliu.'),
  (@b19, 119, 168, 'Laikiausi tavo prisakymų ir tavo liudijimų; nes visi mano keliai yra tavo akivaizdoje.'),
  (@b19, 119, 169, 'Tegul mano šauksmas priartėja tavo akivaizdon, o VIEŠPATIE; duok man supratimą pagal savo žodį.'),
  (@b19, 119, 170, 'Tegul mano prašymas ateina tavo akivaizdon; išvaduok mane pagal savo žodį.'),
  (@b19, 119, 171, 'Mano lūpos tars gyrių, kai tu mane būsi išmokęs savo įstatų.'),
  (@b19, 119, 172, 'Mano liežuvis kalbės apie tavo žodį; nes visi tavo įsakymai yra teisumas.'),
  (@b19, 119, 173, 'Tavo ranka tepadeda man; nes aš pasirinkau tavo prisakymus.'),
  (@b19, 119, 174, 'Ilgėjausi tavo išgelbėjimo, o VIEŠPATIE; ir tavo įstatymas yra mano pasigėrėjimas.'),
  (@b19, 119, 175, 'Tegyvena mano siela, ir ji girs tave; ir tavo teismai tepadeda man.'),
  (@b19, 119, 176, 'Aš paklydęs kaip pražuvusi avis; ieškok savo tarno; nes aš nepamirštu tavo įsakymų.'),
  (@b19, 120, 1, 'Savo suspaudime šaukiausi VIEŠPATIES, ir jis mane išklausė.'),
  (@b19, 120, 2, '„O VIEŠPATIE, išvaduok mano sielą nuo meluojančių lūpų ir nuo apgaulingo liežuvio“.'),
  (@b19, 120, 3, 'Ką tau duos? Arba, ką tau padarys, apgaulingas liežuvi?'),
  (@b19, 120, 4, 'Aštrias galingojo strėles su kadagio žarijomis.'),
  (@b19, 120, 5, 'Vargas man, kad laikinai gyvenu Meseche, kad gyvenu Kedaro palapinėse!'),
  (@b19, 120, 6, 'Mano siela ilgai gyveno su tuo, kuris nekenčia taikos.'),
  (@b19, 120, 7, 'Aš esu už taiką; bet kai aš kalbu, jie yra už karą.'),
  (@b19, 121, 1, 'Laipsninė giesmė. Aš pakelsiu savo akis į kalvas, iš kur ateina mano pagalba.'),
  (@b19, 121, 2, 'Mano pagalba ateina iš VIEŠPATIES, kuris padarė dangų ir žemę.'),
  (@b19, 121, 3, 'Jis neleis svyruoti tavo kojai; nesnaus tas, kuris tave saugo.'),
  (@b19, 121, 4, 'Štai tas, kuris saugo Izraelį, nei snaus, nei miegos.'),
  (@b19, 121, 5, 'VIEŠPATS yra tavo sargas; VIEŠPATS yra tavo pavėsis tavo dešinėje.'),
  (@b19, 121, 6, 'Dieną neištiks tavęs saulė nei mėnulis naktį.'),
  (@b19, 121, 7, 'VIEŠPATS saugos tave nuo viso pikto; jis saugos tavo sielą.'),
  (@b19, 121, 8, 'VIEŠPATS saugos tavo išėjimą ir tavo įėjimą nuo dabar ir per amžius.'),
  (@b19, 122, 1, 'Dovydo laipsninė giesmė. Džiaugiausi, kai jie man sakė: „Eikime į VIEŠPATIES namus“.'),
  (@b19, 122, 2, 'Mūsų kojos stovės tavo vartuose, o Jeruzale.'),
  (@b19, 122, 3, 'Jeruzalė pastatyta kaip glaudžiai sujungtas miestas;'),
  (@b19, 122, 4, 'kur eina aukštyn gentys, VIEŠPATIES gentys, prie Izraelio liudijimo dėkoti VIEŠPATIES vardui.'),
  (@b19, 122, 5, 'Nes ten yra pastatyti teismo sostai, Dovydo namų sostai.'),
  (@b19, 122, 6, 'Melskite taikos Jeruzalei; klestės tie, kurie tave myli.'),
  (@b19, 122, 7, 'Tebūna taika viduje tavo sienų ir klestėjimas tavo rūmuose.'),
  (@b19, 122, 8, 'Dėl savo brolių ir draugų dabar sakysiu: „Taika tebūna tavo viduje“.'),
  (@b19, 122, 9, 'Dėl VIEŠPATIES, mūsų Dievo, namų sieksiu tau gero.'),
  (@b19, 123, 1, 'Laipsninė giesmė. Keliu akis į tave, kuris gyveni danguose.'),
  (@b19, 123, 2, 'Štai – kaip tarnų akys žvelgia į savo valdovų ranką ir kaip tarnaitės akys į savo valdovės ranką, taip mūsų akys laukia VIEŠPATIES, mūsų Dievo, kol jis mūsų pasigailės.'),
  (@b19, 123, 3, 'Pasigailėk mūsų, o VIEŠPATIE, pasigailėk mūsų; nes mes apsčiai pasisotinome panieka.'),
  (@b19, 123, 4, 'Mūsų siela apsčiai pasisotino nerūpestingųjų pajuoka ir išdidžiųjų panieka.'),
  (@b19, 124, 1, 'Dovydo laipsninė giesmė. Jei ne VIEŠPATS, kuris buvo mūsų pusėje, – tesako dabar Izraelis, –'),
  (@b19, 124, 2, 'jei ne VIEŠPATS, kuris buvo už mus, kai žmonės sukilo prieš mus,'),
  (@b19, 124, 3, 'tada jie mus gyvus būtų prariję, kai jų rūstybė buvo užsidegusi prieš mus;'),
  (@b19, 124, 4, 'tada vandenys būtų mus užlieję, srovė būtų praėjusi virš mūsų sielos;'),
  (@b19, 124, 5, 'tada išdidūs vandenys būtų praėję virš mūsų sielos.'),
  (@b19, 124, 6, 'Tebūna palaimintas VIEŠPATS, kuris mūsų neatidavė kaip grobio jų dantims.'),
  (@b19, 124, 7, 'Mūsų siela ištrūko kaip paukštis iš paukščių medžiotojų žabangų; žabangos sutrūko, ir mes išsigelbėjome.'),
  (@b19, 124, 8, 'Mūsų pagalba yra varde VIEŠPATIES, kuris padarė dangų ir žemę.'),
  (@b19, 125, 1, 'Laipsninė giesmė. Tie, kurie pasitiki VIEŠPAČIU, bus kaip Siono kalnas, kuris nepajudinamas, bet pasilieka per amžius.'),
  (@b19, 125, 2, 'Kaip kalnai yra aplink Jeruzalę, taip VIEŠPATS yra aplink savo tautą nuo dabar ir per amžius.'),
  (@b19, 125, 3, 'Nes nedorėlių lazda nepasiliks ant teisiųjų burto; kad teisieji savo rankų netiestų į neteisybę.'),
  (@b19, 125, 4, 'Daryk, o VIEŠPATIE, gera geriesiems ir tiesiaširdžiams.'),
  (@b19, 125, 5, 'O tokius, kurie nukrypsta į savo kreivus kelius, VIEŠPATS išves su darančiais neteisybę; tačiau Izraeliui bus taika.'),
  (@b19, 126, 1, 'Laipsninė giesmė. Kai VIEŠPATS sugrąžino Siono nelaisvę, mes buvome kaip sapnuojantys.'),
  (@b19, 126, 2, 'Tada mūsų burna buvo pripildyta juoko, o mūsų liežuvis – giedojimo; tada kalbėjo tarp pagonių: „VIEŠPATS didžių dalykų jiems padarė“.'),
  (@b19, 126, 3, 'VIEŠPATS didžių dalykų mums padarė, dėl kurių esame linksmi.'),
  (@b19, 126, 4, 'Atgręžk, o VIEŠPATIE, mūsų nelaisvę, kaip upelius pietuose.'),
  (@b19, 126, 5, 'Kurie sėja su ašaromis, su džiaugsmu pjaus.'),
  (@b19, 126, 6, 'Kas išeina verkdamas, nešinas brangia sėkla, neabejotinai sugrįš džiūgaudamas, nešdamas savo pėdus su savimi.'),
  (@b19, 127, 1, 'Laipsninė giesmė Saliamonui. Jei VIEŠPATS nestato namų, veltui triūsia jų statytojai; jei VIEŠPATS nesaugo miesto, veltui budi sargas.'),
  (@b19, 127, 2, 'Veltui jūs keliatės anksti, kad vėlai atsisėstumėte, kad valgytumėte sielvarto duoną; nes taip jis duoda savo mylimajam miegą.'),
  (@b19, 127, 3, 'Štai vaikai yra VIEŠPATIES palikimas, įsčių vaisius – jo atlygis.'),
  (@b19, 127, 4, 'Kaip strėlės galiūno rankoje, taip yra jaunystės vaikai.'),
  (@b19, 127, 5, 'Laimingas žmogus, kuris turi jų pilną savo strėlinę; jie nebus sugėdinti, bet kalbėsis su priešais vartuose.'),
  (@b19, 128, 1, 'Laipsninė giesmė. Palaimintas kiekvienas, kuris bijo VIEŠPATIES, kuris vaikšto jo keliais.'),
  (@b19, 128, 2, 'Nes tu valgysi savo rankų triūsą; tu būsi laimingas, ir tau gerai seksis.'),
  (@b19, 128, 3, 'Tavo žmona bus kaip vaisingas vynmedis prie tavo namų šonų; tavo vaikai kaip alyvmedžių sodinukai aplink tavo stalą.'),
  (@b19, 128, 4, 'Štai, kad taip būtų palaimintas žmogus, kuris bijo VIEŠPATIES.'),
  (@b19, 128, 5, 'VIEŠPATS palaimins tave iš Siono; ir matysi Jeruzalės gerovę per visas savo gyvenimo dienas.'),
  (@b19, 128, 6, 'Taip, tu pamatysi savo vaikų vaikus ir taiką Izraeliui.'),
  (@b19, 129, 1, 'Daug kartų jie mane vargino nuo pat mano jaunystės, – tesako dabar Izraelis, –'),
  (@b19, 129, 2, 'daug kartų jie mane vargino nuo pat mano jaunystės; tačiau manęs nenugalėjo.'),
  (@b19, 129, 3, 'Artojai arė ant mano nugaros; jie išvarė ilgas savo vagas.'),
  (@b19, 129, 4, 'VIEŠPATS teisus; jis sukapojo nedorėlių virves.'),
  (@b19, 129, 5, 'Tegul susigėsta ir traukiasi atgal visi, kurie nekenčia Siono.'),
  (@b19, 129, 6, 'Jie tebūna kaip žolė ant stogų, kuri dar neužaugusi nudžiūna;'),
  (@b19, 129, 7, 'kuria pjovėjas nepripildo savo rankos, ir pėdų rišėjas savo užančio.'),
  (@b19, 129, 8, 'Ir praeinantys nesako: „VIEŠPATIES palaiminimas tebūna ant jūsų; mes jus laiminame VIEŠPATIES vardu“.'),
  (@b19, 130, 1, 'Laipsninė giesmė. Iš gilybių šaukiausi tavęs, o VIEŠPATIE.'),
  (@b19, 130, 2, 'Viešpatie, išgirsk mano balsą; tavo ausys tebūna dėmesingos mano prašymų balsui.'),
  (@b19, 130, 3, 'Jei tu, VIEŠPATIE, pasižymėsi neteisybes, kas, Viešpatie, išsilaikys?'),
  (@b19, 130, 4, 'Bet pas tave yra atleidimas, kad tavęs bijotų.'),
  (@b19, 130, 5, 'Laukiu VIEŠPATIES, mano siela laukia, ir viliuosi jo žodžiais.'),
  (@b19, 130, 6, 'Mano siela laukia Viešpaties labiau, negu sargai – ryto; aš sakau, labiau, negu sargai – ryto.'),
  (@b19, 130, 7, 'Tegul Izraelis viliasi VIEŠPAČIU; nes pas VIEŠPATĮ yra gailestingumas ir pas jį yra gausus atpirkimas.'),
  (@b19, 130, 8, 'Ir jis atpirks Izraelį iš visų jo neteisybių.'),
  (@b19, 131, 1, 'Dovydo laipsninė giesmė. VIEŠPATIE, mano širdis neišpuikusi nei mano akys neišdidžios; ir aš neužsiimu dideliais ar man per aukštais dalykais.'),
  (@b19, 131, 2, 'Tikrai aš suvaldžiau ir nuraminau save, kaip motinos nujunkytą vaiką; mano siela – kaip nujunkytas vaikas.'),
  (@b19, 131, 3, 'Tegul Izraelis viliasi VIEŠPAČIU nuo dabar ir per amžius.'),
  (@b19, 132, 1, 'Laipsninė giesmė. VIEŠPATIE, atsimink Dovydą ir visus jo sielvartus;'),
  (@b19, 132, 2, 'kaip jis prisiekė VIEŠPAČIUI ir pasižadėjo Jokūbo galingajam Dievui:'),
  (@b19, 132, 3, '„Aš tikrai neisiu į savo namų padangtę ir nelipsiu į savo lovą;'),
  (@b19, 132, 4, 'neduosiu miego savo akims ar snaudulio savo akių vokams,'),
  (@b19, 132, 5, 'kol nesurasiu vietos VIEŠPAČIUI, buveinės Jokūbo galingajam Dievui“.'),
  (@b19, 132, 6, 'Štai girdėjome apie ją Efratoje; ją radome miško laukuose.'),
  (@b19, 132, 7, 'Mes eisime į jo padangtes; garbinsime prie jo pakojo.'),
  (@b19, 132, 8, 'Pakilk, o VIEŠPATIE, į savo poilsį; tu ir tavo stiprybės skrynia.'),
  (@b19, 132, 9, 'Tegul tavo kunigai apsivelka teisumu; ir tavo šventieji tešaukia iš džiaugsmo.'),
  (@b19, 132, 10, 'Dėl savo tarno Dovydo nenugręžk veido tavo pateptojo.'),
  (@b19, 132, 11, 'VIEŠPATS prisiekė Dovydui tiesoje; nuo jos jis nenusisuks: „Iš tavo kūno vaisiaus aš pasodinsiu į tavo sostą.'),
  (@b19, 132, 12, 'Jei tavo vaikai laikysis mano sandoros ir mano liudijimo, kurių juos mokysiu, tai ir jų vaikai per amžius sėdės tavo soste“.'),
  (@b19, 132, 13, 'Nes VIEŠPATS išsirinko Sioną; jis jo troško savo buveinei.'),
  (@b19, 132, 14, '„Tai yra mano poilsis per amžius, čia gyvensiu, nes jo troškau.'),
  (@b19, 132, 15, 'Jo aprūpinimą gausiai palaiminsiu; jo vargšus pasotinsiu duona.'),
  (@b19, 132, 16, 'Taip pat jo kunigus apvilksiu išgelbėjimu; o jo šventieji garsiai šauks iš džiaugsmo.'),
  (@b19, 132, 17, 'Ten duosiu apsipumpuruoti Dovydo ragui; aš paruošiau savo pateptajam žibintą.'),
  (@b19, 132, 18, 'Jo priešus apvilksiu gėda; bet ant jo žydės jo karūna“.'),
  (@b19, 133, 1, 'Dovydo laipsninė giesmė. Štai kaip gera ir kaip miela broliams kartu vienybėje gyventi!'),
  (@b19, 133, 2, 'Tai – kaip brangus tepalas ant galvos, kuris varvėjo ant barzdos – Aarono barzdos, kuris varvėjo ant jo drabužių kraštų;'),
  (@b19, 133, 3, 'kaip Hermono rasa ir kaip rasa, kuri nusileido ant Siono kalnų; nes ten VIEŠPATS įsakė palaiminimą, tai yra, gyvenimą per amžius.'),
  (@b19, 134, 1, 'Laipsninė giesmė. Štai laiminkite VIEŠPATĮ, visi VIEŠPATIES tarnai, kurie stovite naktį VIEŠPATIES namuose.'),
  (@b19, 134, 2, 'Pakelkite savo rankas šventovėje ir laiminkite VIEŠPATĮ.'),
  (@b19, 134, 3, 'VIEŠPATS, kuris padarė dangų ir žemę, telaimina tave iš Siono.'),
  (@b19, 135, 1, 'Girkite VIEŠPATĮ. Girkite VIEŠPATIES vardą; girkite jį, o jūs, VIEŠPATIES tarnai.'),
  (@b19, 135, 2, 'Jūs, kurie stovite VIEŠPATIES namuose, mūsų Dievo namų kiemuose,'),
  (@b19, 135, 3, 'girkite VIEŠPATĮ, nes VIEŠPATS yra geras; giedokite gyrių jo vardui, nes jis mielas.'),
  (@b19, 135, 4, 'Nes Jokūbą sau išsirinko VIEŠPATS ir Izraelį – kaip savo ypatingą brangenybę.'),
  (@b19, 135, 5, 'Nes aš žinau, kad VIEŠPATS yra didis ir kad mūsų Viešpats yra aukščiau visų dievų.'),
  (@b19, 135, 6, 'Visa, ko norėjo VIEŠPATS, jis padarė danguje ir žemėje, jūrose ir visose giliose vietose.'),
  (@b19, 135, 7, 'Jis priverčia pakilti garams nuo žemės pakraščių; jis padaro žaibus lietui; jis išveda vėją iš savo lobynų.'),
  (@b19, 135, 8, 'Jis ištiko Egipto pirmagimius tiek žmonių, tiek gyvulių.'),
  (@b19, 135, 9, 'Jis siuntė ženklų ir stebuklų į tavo vidurį, o Egipte, ant faraono ir ant visų jo tarnų.'),
  (@b19, 135, 10, 'Jis sumušė dideles tautas ir užmušė galingus karalius:'),
  (@b19, 135, 11, 'amoritų karalių Sihoną ir Bašano karalių Ogą, ir visas Kanaano karalystes;'),
  (@b19, 135, 12, 'ir davė jų šalį kaip palikimą, palikimą Izraeliui, savo tautai.'),
  (@b19, 135, 13, 'O VIEŠPATIE, tavo vardas išlieka per amžius; ir tavo atsiminimas, o VIEŠPATIE, per kartų kartas.'),
  (@b19, 135, 14, 'Nes VIEŠPATS teis savo tautą ir gailėsis dėl savo tarnų.'),
  (@b19, 135, 15, 'Pagonių stabai – sidabras ir auksas, žmogaus rankų darbas.'),
  (@b19, 135, 16, 'Jie turi burnas, bet nekalba; jie turi akis, bet nemato;'),
  (@b19, 135, 17, 'jie turi ausis, bet negirdi; ir nėra jų burnose kvapo.'),
  (@b19, 135, 18, 'Panašūs į juos tie, kurie juos daro; tokie yra visi, kurie jais pasitiki.'),
  (@b19, 135, 19, 'Izraelio namai, laiminkite VIEŠPATĮ; Aarono namai, laiminkite VIEŠPATĮ;'),
  (@b19, 135, 20, 'Levio namai, laiminkite VIEŠPATĮ; jūs, kurie bijote VIEŠPATIES, laiminkite VIEŠPATĮ.'),
  (@b19, 135, 21, 'Palaimintas tebūna VIEŠPATS iš Siono, gyvenantis Jeruzalėje. Girkite VIEŠPATĮ.'),
  (@b19, 136, 1, 'Dėkokite VIEŠPAČIUI, nes jis yra geras, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 2, 'Dėkokite dievų Dievui, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 3, 'Dėkokite viešpačių Viešpačiui, nes jo gailestingumas išlieka per amžius.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 136, 4, 'Tam, kuris vienas daro didelius stebuklus, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 5, 'Tam, kuris išmintimi padarė dangus, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 6, 'Tam, kuris virš vandenų ištiesė žemę, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 7, 'Tam, kuris padarė dideles šviesas, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 8, 'saulę, kad valdytų dieną, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 9, 'mėnulį ir žvaigždes, kad valdytų naktį, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 10, 'Tam, kuris ištiko Egiptą jo pirmagimiuose, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 11, 'ir išvedė Izraelį iš jų tarpo, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 12, 'tvirta ranka ir ištiesta ranka, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 13, 'Tam, kuris padalijo Raudonąją jūrą į dalis, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 14, 'ir pervedė Izraelį per jos vidurį, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 15, 'bet parbloškė faraoną ir jo kariuomenę Raudonojoje jūroje, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 16, 'Tam, kuris vedė savo tautą per dykumą, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 17, 'Tam, kuris sumušė didelius karalius, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 18, 'ir užmušė garsius karalius, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 19, 'amoritų karalių Sihoną, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 20, 'ir Bašano karalių Ogą, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 21, 'ir davė jų šalį kaip palikimą, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 22, 'būtent paveldą Izraeliui, savo tarnui, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 23, 'Kuris atsiminė mus mūsų žemoje padėtyje, nes jo gailestingumas išlieka per amžius;'),
  (@b19, 136, 24, 'ir mus atpirko iš mūsų priešų, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 25, 'Kuris duoda maisto kiekvienam kūnui, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 136, 26, 'Dėkokite dangaus Dievui, nes jo gailestingumas išlieka per amžius.'),
  (@b19, 137, 1, 'Prie Babilono upių, ten sėdėjome, taip, verkėme atsiminę Sioną.'),
  (@b19, 137, 2, 'Ant gluosnių jo tarpe pakabinome savo arfas.'),
  (@b19, 137, 3, 'Nes ten reikalavo iš mūsų giesmių tie, kurie mus išvedė į nelaisvę; ir tie, kurie mus niokojo, reikalavo iš mūsų linksmybės, sakydami: „Pagiedokite mums vieną iš Siono giesmių“.'),
  (@b19, 137, 4, 'Kaip giedosime VIEŠPATIES giesmę svetimoje šalyje?'),
  (@b19, 137, 5, 'Jei pamiršiu tave, o Jeruzale, tepamiršta mano dešinė savo sugebėjimus.'),
  (@b19, 137, 6, 'Tegul mano liežuvis prilimpa man prie gomurio, jei tavęs neatsiminsiu; jei nelaikysiu Jeruzalės aukščiau už savo viršiausią džiaugsmą.'),
  (@b19, 137, 7, 'O VIEŠPATIE, Jeruzalės dienoje atsimink Edomo vaikus, kurie sakė: „Nugriaukite, nugriaukite ją iki jos pamatų“.'),
  (@b19, 137, 8, 'O Babilono dukra, kuri būsi sunaikinta; laimingas bus tas, kuris tau atlygins, kaip tu mums padarei.'),
  (@b19, 137, 9, 'Laimingas bus tas, kuris nutvers ir sudaužys tavo mažylius į akmenis.'),
  (@b19, 138, 1, 'Dovydo psalmė. Girsiu tave visa savo širdimi; dievų akivaizdoje tau giedosiu gyrių.'),
  (@b19, 138, 2, 'Garbinsiu tavo šventos šventyklos link ir girsiu tavo vardą už tavo mylintį gerumą ir tavo tiesą; nes tu išaukštinai savo žodį labiau negu visą savo vardą.'),
  (@b19, 138, 3, 'Dieną, kai šaukiau, tu man atsakei ir sustiprinai mane stiprybe mano sieloje.'),
  (@b19, 138, 4, 'Tave girs, o VIEŠPATIE, visi žemės karaliai, išgirdę tavo burnos žodžius.'),
  (@b19, 138, 5, 'Taip, jie giedos pagal VIEŠPATIES kelius; nes didelė yra VIEŠPATIES šlovė.'),
  (@b19, 138, 6, 'Nors VIEŠPATS yra aukštas, tačiau jis atsižvelgia į nusižeminusį; bet išdidųjį pažįsta iš tolo.'),
  (@b19, 138, 7, 'Nors aš vaikščiosiu vidury bėdos, tu mane atgaivinsi; tu ištiesi savo ranką prieš mano priešų rūstybę, ir tavo dešinė mane išgelbės.'),
  (@b19, 138, 8, 'VIEŠPATS užbaigs tai, kas dėl manęs; o VIEŠPATIE, tavo gailestingumas išlieka per amžius; nepalik savo rankų darbų.'),
  (@b19, 139, 1, 'Vyriausiajam muzikantui. Dovydo psalmė. O VIEŠPATIE, tu ištyrei mane ir pažįsti mane.'),
  (@b19, 139, 2, 'Tu žinai mano atsisėdimą ir mano atsikėlimą, tu supranti mano mintį iš toli.'),
  (@b19, 139, 3, 'Tu apsupi mano taką ir mano atsigulimą, ir su visais mano keliais esi susipažinęs.'),
  (@b19, 139, 4, 'Nes dar nėra žodžio ant mano liežuvio, bet štai tu, o VIEŠPATIE, jį visiškai žinai.'),
  (@b19, 139, 5, 'Tu mane apsupai iš užpakalio ir iš priekio ir uždėjai ant manęs savo ranką.'),
  (@b19, 139, 6, 'Toks pažinimas man yra per nuostabus; jis aukštai – negaliu jo pasiekti.'),
  (@b19, 139, 7, 'Kur aš eisiu nuo tavo Dvasios? Arba, kur pabėgsiu nuo tavo akivaizdos?'),
  (@b19, 139, 8, 'Jei užkilčiau į dangų, tu ten esi; jei pasikločiau patalą pragare, štai tu ten esi.'),
  (@b19, 139, 9, 'Jei pasiimčiau ryto sparnus ir gyvenčiau tolimiausiuose jūros pakraščiuose;'),
  (@b19, 139, 10, 'ir ten tavo ranka mane vedžiotų ir mane laikytų tavo dešinė.'),
  (@b19, 139, 11, 'Jei sakyčiau: „Tikrai tamsa apdengs mane; net naktis bus šviesa aplink mane“.'),
  (@b19, 139, 12, 'Taip, tamsa nepasislepia nuo tavęs; bet naktis šviečia kaip diena; tamsa ir šviesa tau abi vienodos.'),
  (@b19, 139, 13, 'Nes mano inkstai tavo nuosavybėje; tu mane apdengei mano motinos įsčiose.'),
  (@b19, 139, 14, 'Tave girsiu; nes esu baimę keliančiai ir nuostabiai padarytas; nuostabūs tavo darbai; ir mano siela tai labai gerai žino.'),
  (@b19, 139, 15, 'Mano turinys nebuvo paslėptas nuo tavęs, kai buvau daromas slaptoje ir suaustas žemiausiose žemės dalyse.'),
  (@b19, 139, 16, 'Tavo akys matė mano turinį dar neužbaigtą; ir tavo knygoje buvo surašytos visos mano dalys, kurios buvo formuojamos sekoje, kai dar nei vienos jų nebuvo.'),
  (@b19, 139, 17, 'Kokios brangios man yra tavo mintys, o Dieve! Koks didelis jų skaičius!'),
  (@b19, 139, 18, 'Jei jas skaičiuočiau, skaičiumi jų būtų daugiau negu smėlio; kai atsibundu, aš tebesu su tavimi.'),
  (@b19, 139, 19, 'O Dieve, tu tikrai užmuši nedorėlį; todėl pasitraukite nuo manęs, kraugeriai.'),
  (@b19, 139, 20, 'Nes jie nedorai kalba prieš tave, ir tavo priešai tuščiai vartoja tavo vardą.'),
  (@b19, 139, 21, 'Argi aš nekenčiau tų, kurie nekenčia tavęs, o VIEŠPATIE? Ir argi neliūdžiu dėl tų, kurie sukyla prieš tave?'),
  (@b19, 139, 22, 'Nekenčiu jų pilna neapykanta; laikau juos savo priešais.'),
  (@b19, 139, 23, 'Ištirk mane, o Dieve, ir pažink mano širdį; išmėgink mane ir pažink mano mintis;'),
  (@b19, 139, 24, 'ir pažiūrėk, ar yra manyje koks nedoras kelias, ir vesk mane amžinuoju keliu.'),
  (@b19, 140, 1, 'Vyriausiajam muzikantui, Dovydo psalmė. Išvaduok mane, o VIEŠPATIE, nuo pikto žmogaus; apsaugok mane nuo smurtininko;'),
  (@b19, 140, 2, 'kurie sumano piktadarystes savo širdyje; jie nuolat susirenka karui.'),
  (@b19, 140, 3, 'Jie aštrino savo liežuvius kaip gyvatė; angių nuodai po jų lūpomis. Sela.'),
  (@b19, 140, 4, 'Saugok mane, o VIEŠPATIE, nuo nedorėlių rankų; apsaugok mane nuo smurtininkų, kurie ketina suardyti mano ėjimus.'),
  (@b19, 140, 5, 'Išdidieji paslėpė man spąstus ir virves; prie šalikelės jie ištiesė tinklą; jie pastatė man pinkles. Sela.'),
  (@b19, 140, 6, 'Tariau VIEŠPAČIUI: „Tu esi mano Dievas; išgirsk, o VIEŠPATIE, mano maldavimų balsą.'),
  (@b19, 140, 7, 'O DIEVE, Viešpatie, mano išgelbėjimo stiprybe, tu apdengei mano galvą mūšio dieną.'),
  (@b19, 140, 8, 'Nepatenkink, o VIEŠPATIE, nedorėlio norų; neparemk jo nedorų užmačių; kad jie nesiaukštintų“. Sela.'),
  (@b19, 140, 9, 'Na, o dėl galvų tų, kurie mane apsupa, – teapdengia juos jų pačių lūpų piktybė.'),
  (@b19, 140, 10, 'Tekrenta ant jų degančios žarijos; tebūna jie įmesti į ugnį; į gilias duobes, kad jie nebeatsikeltų.'),
  (@b19, 140, 11, 'Pikta kalbantis teneįsitvirtina žemėje; pikta medžios smurtininką, kad jį parblokštų.'),
  (@b19, 140, 12, 'Žinau, kad VIEŠPATS parems prispaustojo bylą ir vargšų teises.'),
  (@b19, 140, 13, 'Tikrai teisieji dėkos tavo vardui; tiesieji gyvens tavo akivaizdoje.'),
  (@b19, 141, 1, 'Dovydo psalmė. VIEŠPATIE, tavęs šaukiuosi; skubėk pas mane; pakreipk ausį į mano balsą, kai tavęs šaukiuosi.'),
  (@b19, 141, 2, 'Tebūna mano malda išstatyta prieš tave kaip smilkalai; o mano rankų pakėlimas – kaip vakarinė auka.'),
  (@b19, 141, 3, 'Pastatyk, o VIEŠPATIE, sargybą prieš mano burną; saugok mano lūpų duris.'),
  (@b19, 141, 4, 'Nelenk mano širdies į jokį piktą dalyką, užsiiminėti nedorais darbais su darančiais neteisybę; ir tenevalgysiu iš jų skanėstų.'),
  (@b19, 141, 5, 'Temuša mane teisusis; tai bus gerumas; ir tebara jis mane; tai bus puikus aliejus, kuris nesužeis mano galvos; nes ir mano malda dar bus jų nelaimėse.'),
  (@b19, 141, 6, 'Kai jų teisėjai parblokšti akmenuotose vietose, jie išgirs mano žodžius; nes jie yra mieli.'),
  (@b19, 141, 7, 'Kaip kad kas nukerta ir skaldo medį ant žemės, taip mūsų kaulai išbarstyti prie kapo angos.'),
  (@b19, 141, 8, 'Bet mano akys nukreiptos į tave, o DIEVE, Viešpatie; tavyje mano pasitikėjimas; nepalik mano sielos skurstančios.'),
  (@b19, 141, 9, 'Apsaugok mane nuo spąstų, kuriuos jie man padėjo, ir nuo pinklių tų, kurie daro neteisybę.'),
  (@b19, 141, 10, 'Tegul nedorėliai įkliūna į savo pačių tinklus, kai aš tuo tarpu pabėgsiu.'),
  (@b19, 142, 1, 'Dovydo maskylas; Malda, kai jis buvo oloje. Balsu šaukiausi VIEŠPATIES; balsu maldavau VIEŠPATĮ.'),
  (@b19, 142, 2, 'Jo akivaizdoje išliejau savo skundą; jo akivaizdoje išsakiau savo bėdą.'),
  (@b19, 142, 3, 'Kai manyje buvo sukrėsta mano dvasia, tu žinojai mano taką. Kelyje, kuriuo vaikščiojau, slapta jie padėjo man spąstus.'),
  (@b19, 142, 4, 'Pažvelgiau į savo dešinę ir mačiau, bet nebuvo nei vieno, kas mane pažintų; dingo mano prieglobstis; niekas nesirūpino mano siela.'),
  (@b19, 142, 5, 'Šaukiausi tavęs, o VIEŠPATIE; sakiau: „Tu esi mano prieglobstis ir mano dalis gyvųjų šalyje“.'),
  (@b19, 142, 6, 'Atkreipk dėmesį į mano šauksmą, nes esu labai pažemintas; išvaduok mane nuo mano persekiotojų, nes jie stipresni už mane.'),
  (@b19, 142, 7, 'Išvesk mano sielą iš kalėjimo, kad girčiau tavo vardą; susiburs aplink mane teisieji; nes tu dosniai su manimi pasielgsi.'),
  (@b19, 143, 1, 'Dovydo psalmė. O VIEŠPATIE, išgirsk mano maldą, atverk ausį mano prašymams; atsakyk man savo ištikimybe ir savo teisumu.'),
  (@b19, 143, 2, 'Ir neik į teismą su savo tarnu; nes nei vienas gyvasis nebus išteisintas tavo akyse.'),
  (@b19, 143, 3, 'Nes priešas persekiojo mano sielą; jis sutrypė į žemę mano gyvybę; apgyvendino mane tamsybėje, kaip seniai mirusiuosius.'),
  (@b19, 143, 4, 'Todėl sukrėsta manyje mano dvasia; mano viduje nyksta mano širdis.'),
  (@b19, 143, 5, 'Atsimenu senąsias dienas; mąstau apie visus tavo darbus; apmąstau tavo rankų darbą.'),
  (@b19, 143, 6, 'Savo rankas tiesiu į tave; mano siela trokšta tavęs kaip ištroškusi žemė. Sela.'),
  (@b19, 143, 7, 'Skubiai išklausyk mane, o VIEŠPATIE: silpsta mano dvasia; neslėpk nuo manęs savo veido, kad nebūčiau kaip tie, kurie nužengia į duobę.'),
  (@b19, 143, 8, 'Duok man ryte išgirsti tavo mylintį gerumą, nes tavimi pasitikiu; duok man pažinti kelią, kuriuo turiu vaikščioti, nes į tave keliu savo sielą.'),
  (@b19, 143, 9, 'Išvaduok mane nuo mano priešų, o VIEŠPATIE: pas tave bėgu slėptis.'),
  (@b19, 143, 10, 'Mokyk mane vykdyti tavo valią, nes tu esi mano Dievas; gera yra tavo Dvasia; vesk mane į tiesumo šalį.'),
  (@b19, 143, 11, 'Dėl savo vardo, o VIEŠPATIE, atgaivink mane; dėl savo teisumo išvesk mano sielą iš bėdos.'),
  (@b19, 143, 12, 'Iš savo gailestingumo iškirsk mano priešus ir sunaikink visus mano sielos vargintojus; nes aš esu tavo tarnas.'),
  (@b19, 144, 1, 'Dovydo psalmė. Tebūna palaimintas VIEŠPATS, mano stiprybė, kuris moko mano rankas kariauti ir mano pirštus kovoti;'),
  (@b19, 144, 2, 'mano gerumas ir mano tvirtovė, mano aukštas bokštas ir mano išvaduotojas; mano skydas ir tas, kuriuo pasitikiu; kuris pajungė man mano tautą.'),
  (@b19, 144, 3, 'VIEŠPATIE, kas yra žmogus, kad apie jį žinai, ar žmogaus sūnus, kad kreipi į jį dėmesį?'),
  (@b19, 144, 4, 'Žmogus panašus į tuštybę; jo dienos kaip praeinantis šešėlis.'),
  (@b19, 144, 5, 'O VIEŠPATIE, palenk savo dangus ir nuženk; paliesk kalnus, ir jie rūks.'),
  (@b19, 144, 6, 'Svaidyk žaibą ir juos išsklaidyk; iššauk savo strėles ir juos sunaikink.'),
  (@b19, 144, 7, 'Siųsk savo ranką iš aukštai; išgelbėk ir išvaduok mane iš didelių vandenų, iš svetimšalių vaikų rankos;'),
  (@b19, 144, 8, 'kurių burna kalba tuštybę, ir jų dešinė – melagystės dešinė.'),
  (@b19, 144, 9, 'O Dieve, naują giesmę tau giedosiu; psalteriu ir dešimčiastygiu instrumentu giedosiu tau gyrių.'),
  (@b19, 144, 10, 'Tai jis, kuris duoda išgelbėjimą karaliams, kuris išvaduoja Dovydą, savo tarną, nuo žalojančio kalavijo.'),
  (@b19, 144, 11, 'Išgelbėk mane ir išvaduok mane iš rankos svetimšalių vaikų, kurių burna kalba tuštybę, ir jų dešinė – melagystės dešinė;'),
  (@b19, 144, 12, 'kad mūsų sūnūs būtų kaip augalai užaugę savo jaunystėje; kad mūsų dukterys būtų kaip kertiniai akmenys, nugludinti pagal rūmų panašumą;'),
  (@b19, 144, 13, 'kad mūsų svirnai būtų pilni, turintys visokių atsargų; kad mūsų avys atsivestų tūkstančius ir dešimtis tūkstančių mūsų gatvėse;'),
  (@b19, 144, 14, 'kad mūsų jaučiai būtų stiprūs dirbti; kad nebūtų įsibrovimų ir išėjimų; kad nebūtų nusiskundimų mūsų gatvėse.'),
  (@b19, 144, 15, 'Laiminga ta tauta, kuriai taip yra; taip, laiminga ta tauta, kurios Dievas yra VIEŠPATS.'),
  (@b19, 145, 1, 'Dovydo gyriaus psalmė. Aš tave liaupsinsiu, mano Dieve, o karaliau; ir laiminsiu tavo vardą per amžių amžius.'),
  (@b19, 145, 2, 'Kasdien laiminsiu tave ir girsiu tavo vardą per amžių amžius.'),
  (@b19, 145, 3, 'Didis yra VIEŠPATS ir didžiai girtinas, ir jo didybė neištiriama.'),
  (@b19, 145, 4, 'Viena karta girs tavo darbus kitai ir skelbs tavo galingus darbus.'),
  (@b19, 145, 5, 'Aš kalbėsiu apie šlovingą tavo didingumo garbę ir apie tavo nuostabius darbus.'),
  (@b19, 145, 6, 'Ir žmonės kalbės apie tavo baisių darbų galią; ir aš skelbsiu tavo didybę.'),
  (@b19, 145, 7, 'Jie gausiai tars atminimą apie tavo didelį gerumą, ir giedos apie tavo teisumą.'),
  (@b19, 145, 8, 'VIEŠPATS yra maloningas ir pilnas užuojautos; lėtas pykti ir didžiai gailestingas.'),
  (@b19, 145, 9, 'VIEŠPATS yra geras visiems; jo švelnūs gailestingumai yra viršum visų jo darbų.'),
  (@b19, 145, 10, 'Visi tavo darbai girs tave, o VIEŠPATIE; ir laimins tave tavo šventieji.'),
  (@b19, 145, 11, 'Jie kalbės apie tavo karalystės šlovę ir šnekės apie tavo galią,'),
  (@b19, 145, 12, 'kad duotų pažinoti žmonių sūnums jo galingus veiksmus ir jo karalystės šlovingą didingumą.'),
  (@b19, 145, 13, 'Tavo karalystė – amžina karalystė, ir tavo valdžia išlieka per kartų kartas.'),
  (@b19, 145, 14, 'VIEŠPATS palaiko visus krentančius ir pakelia visus palinkusius.'),
  (@b19, 145, 15, 'Visų akys tavęs laukia; ir tu jiems duodi jų maistą tinkamu laiku.'),
  (@b19, 145, 16, 'Tu atveri savo ranką ir patenkini kiekvienos gyvos būtybės norą.'),
  (@b19, 145, 17, 'VIEŠPATS yra teisus visuose savo keliuose ir šventas visuose savo darbuose.'),
  (@b19, 145, 18, 'VIEŠPATS yra arti visiems, kurie jo šaukiasi, visiems, kurie jo šaukiasi tiesoje.'),
  (@b19, 145, 19, 'Jis išpildys norą tų, kurie jo bijo; taipogi jis išgirs jų šauksmą ir juos išgelbės.'),
  (@b19, 145, 20, 'VIEŠPATS saugo visus jį mylinčius, bet visus nedorėlius sunaikins.'),
  (@b19, 145, 21, 'Mano burna kalbės VIEŠPATIES gyrių; ir tegul kiekvienas kūnas laimina jo šventą vardą per amžių amžius.'),
  (@b19, 146, 1, 'Girkite VIEŠPATĮ; girk VIEŠPATĮ, o mano siela.'),
  (@b19, 146, 2, 'Girsiu VIEŠPATĮ, kol gyvenu; giedosiu gyrių savo Dievui, kol esu.'),
  (@b19, 146, 3, 'Nepasikliaukite kunigaikščiais nei žmonių sūnumis, kurie negali pagelbėti.'),
  (@b19, 146, 4, 'Išeina jo kvapas, jis sugrįžta į savo žemę; tą pačią dieną žūva jo sumanymai.'),
  (@b19, 146, 5, 'Laimingas tas, kurio pagalba yra Jokūbo Dievas, kurio viltis VIEŠPATYJE, savo Dieve;'),
  (@b19, 146, 6, 'kuris padarė dangų ir žemę, jūrą ir visa, kas yra juose; kuris išsaugo tiesą per amžius;'),
  (@b19, 146, 7, 'kuris vykdo teismą dėl engiamųjų, kuris duoda maisto alkaniesiems. VIEŠPATS išlaisvina kalinius;'),
  (@b19, 146, 8, 'VIEŠPATS atveria akis akliesiems; VIEŠPATS pakelia palinkusius; VIEŠPATS myli teisiuosius;'),
  (@b19, 146, 9, 'VIEŠPATS saugo ateivius; jis paremia našlaitį ir našlę; bet nedorėlių kelią apverčia aukštyn kojom.'),
  (@b19, 146, 10, 'VIEŠPATS karaliaus per amžius – tavo Dievas, o Sione, per kartų kartas. Girkite VIEŠPATĮ.'),
  (@b19, 147, 1, 'Girkite VIEŠPATĮ; nes gera giedoti gyrių mūsų Dievui; nes tai malonu; ir gyrius yra mielas.'),
  (@b19, 147, 2, 'VIEŠPATS pastato Jeruzalę; jis surenka Izraelio išvarytuosius.'),
  (@b19, 147, 3, 'Jis išgydo tuos, kurių širdis sudaužyta, ir apriša jų žaizdas.'),
  (@b19, 147, 4, 'Jis suskaičiuoja žvaigždžių skaičių; jas visas jų vardais vadina.'),
  (@b19, 147, 5, 'Didis yra mūsų Viešpats ir didelės jėgos; jo supratimas begalinis.'),
  (@b19, 147, 6, 'VIEŠPATS pakelia romiuosius; jis parbloškia nedorėlius ant žemės.'),
  (@b19, 147, 7, 'Giedokite VIEŠPAČIUI su padėka; su arfa giedokite gyrių mūsų Dievui;'),
  (@b19, 147, 8, 'kuris apdengia dangų debesimis, kuris paruošia žemei lietų, kuris augina žolę kalnuose.'),
  (@b19, 147, 9, 'Jis duoda žvėriui jo maistą ir bešaukiantiems jauniems varniukams.'),
  (@b19, 147, 10, 'Ne žirgo stiprumu jis gėrisi; ne žmogaus kojos jam teikia malonumą.'),
  (@b19, 147, 11, 'VIEŠPAČIUI teikia malonumą tie, kurie jo bijo, tie, kurie viliasi jo gailestingumu.'),
  (@b19, 147, 12, 'Girk, Jeruzale, VIEŠPATĮ; girk savo Dievą, o Sione.'),
  (@b19, 147, 13, 'Nes jis sutvirtino tavo vartų skląsčius, palaimino tavo vaikus tavo viduje.'),
  (@b19, 147, 14, 'Jis padaro tavo ribose taiką ir geriausiais iš kviečių tave pasotina.'),
  (@b19, 147, 15, 'Jis išsiunčia į žemę savo įsakymą; labai greitai bėga jo žodis.'),
  (@b19, 147, 16, 'Jis duoda sniegą kaip vilną, šerkšną kaip pelenus išbarsto.'),
  (@b19, 147, 17, 'Jis mėto savo ledus kaip kąsnius; kas gali išstovėti prieš jo šaltį?'),
  (@b19, 147, 18, 'Jis išsiunčia savo žodį ir juos sutirpdo; jis pučia savo vėją, ir vandenys teka.'),
  (@b19, 147, 19, 'Jis skelbia savo žodį Jokūbui, savo įstatus ir savo teismus Izraeliui.'),
  (@b19, 147, 20, 'Taip jis nesielgė su jokia kita tauta, o dėl jo teismų – jos jų nežinojo. Girkite VIEŠPATĮ.'),
  (@b19, 148, 1, 'Girkite VIEŠPATĮ. Girkite VIEŠPATĮ iš dangų; girkite jį aukštybėse.'),
  (@b19, 148, 2, 'Girkite jį, visi jo angelai, girkite jį, visos jo kariuomenės.'),
  (@b19, 148, 3, 'Girkite jį, saule ir mėnuli; girkite jį, vìsos šviesos žvaigždės.'),
  (@b19, 148, 4, 'Girkite jį, dangų dangūs ir vandenys, kurie esate virš dangų.'),
  (@b19, 148, 5, 'Jie tegiria VIEŠPATIES vardą, nes jis įsakė, ir jie buvo sutverti.'),
  (@b19, 148, 6, 'Jis juos sutvirtino amžių amžiams; jis išleido įsaką, kuris nepraeis.'),
  (@b19, 148, 7, 'Girkite VIEŠPATĮ nuo žemės, jūs slibinai ir visos gelmės;'),
  (@b19, 148, 8, 'ugnie ir kruša, sniege ir gare, audringas vėjau, vykdantis jo žodį;'),
  (@b19, 148, 9, 'kalnai ir visos kalvos, vaisingi medžiai ir visi kedrai,'),
  (@b19, 148, 10, 'žvėrys ir visi galvijai, ropliai ir sparnuotieji skrajūnai;'),
  (@b19, 148, 11, 'žemės karaliai ir visos tautos, kunigaikščiai ir visi žemės teisėjai,'),
  (@b19, 148, 12, 'ir jaunuoliai, ir merginos, seniai ir vaikai;'),
  (@b19, 148, 13, 'tegiria jie VIEŠPATIES vardą, nes jo vienintelio vardas yra didingas; jo šlovė yra virš žemės ir dangaus.'),
  (@b19, 148, 14, 'Taipogi jis iškelia savo tautos ragą, gyrių visų savo šventųjų – Izraelio vaikų, jam artimós tautos. Girkite VIEŠPATĮ.'),
  (@b19, 149, 1, 'Girkite VIEŠPATĮ. Giedokite VIEŠPAČIUI naują giesmę ir jo gyrių šventųjų susirinkime.'),
  (@b19, 149, 2, 'Izraelis tesidžiaugia jį padariusiuoju; Siono vaikai tebūna džiaugsmingi savo Karaliumi.'),
  (@b19, 149, 3, 'Tegiria jo vardą šokiu; tegieda jam gyrių tambūrinu ir arfa.'),
  (@b19, 149, 4, 'Nes VIEŠPAČIUI teikia malonumą jo tauta; jis romiuosius išgražins išgelbėjimu.'),
  (@b19, 149, 5, 'Šventieji tebūna džiaugsmingi šlove; tegul jie garsiai gieda savo pataluose.'),
  (@b19, 149, 6, 'Aukštas Dievo gyrius tebūna jų burnoje, ir dviašmenis kalavijas jų rankoje;'),
  (@b19, 149, 7, 'kad vykdytų kerštą pagonims ir bausmes tautoms;'),
  (@b19, 149, 8, 'kad surištų jų karalius grandinėmis ir jų kilminguosius geležiniais pančiais;'),
  (@b19, 149, 9, 'kad jiems įvykdytų užrašytą teismą; šią garbę turi visi jo šventieji. Girkite VIEŠPATĮ.'),
  (@b19, 150, 1, 'Girkite VIEŠPATĮ; Girkite Dievą jo šventovėje; girkite jį jo jėgos tvirtumoje.'),
  (@b19, 150, 2, 'Girkite jį už jo galingus darbus; girkite jį pagal jo pranokstančią didybę.'),
  (@b19, 150, 3, 'Girkite jį trimito garsu; girkite jį psalteriu ir arfa.'),
  (@b19, 150, 4, 'Girkite jį tambūrinu ir šokiu; girkite jį styginiais instrumentais ir vargonais.'),
  (@b19, 150, 5, 'Girkite jį skambiais cimbolais; girkite jį aukštai skambančiais cimbolais.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b19, 150, 6, 'Visa, kas kvėpuoja, tegiria VIEŠPATĮ. Girkite VIEŠPATĮ.'),
  (@b20, 1, 1, 'Saliamono, Dovydo sūnaus, Izraelio karaliaus, patarlės;'),
  (@b20, 1, 2, 'išminčiai ir pamokymui pažinti, supratimo žodžiams suvokti,'),
  (@b20, 1, 3, 'priimti pamokymą išminties, teisingumo, teismo ir bešališkumo;'),
  (@b20, 1, 4, 'paikiesiems suteikti gudrybės, jaunuoliui – pažinimo ir apdairumo.'),
  (@b20, 1, 5, 'Išmintingasis išklausys ir daugiau pasimokys; ir suprantantis gaus išmintingų patarimų;'),
  (@b20, 1, 6, 'kad suprastų patarlę ir aiškinimą, išmintingųjų žodžius ir jų paslaptingus pasakymus.'),
  (@b20, 1, 7, 'VIEŠPATIES baimė yra pažinimo pradžia, bet kvailiai niekina išmintį ir pamokymą.'),
  (@b20, 1, 8, 'Mano sūnau, klausyk savo tėvo pamokymo ir nepalik savo motinos įstatymo;'),
  (@b20, 1, 9, 'nes jie bus malonės papuošalas tavo galvai ir grandinėlė aplink tavo kaklą.'),
  (@b20, 1, 10, 'Mano sūnau, jei tave vilioja nusidėjėliai, nesutik.'),
  (@b20, 1, 11, 'Jei jie sako: „Eikš su mumis, tykokime kraujo, slapta be priežasties sėlinkime prie nekaltojo;'),
  (@b20, 1, 12, 'prarykime juos gyvus, kaip kapas, ir sveikus kaip tuos, kurie nužengia į duobę;'),
  (@b20, 1, 13, 'mes rasime visokio brangaus turto, pripildysime savo namus grobio;'),
  (@b20, 1, 14, 'savo burtą mesk tarp mūsų, vieną piniginę turėkime visi“;'),
  (@b20, 1, 15, 'mano sūnau, nevaikščiok keliu su jais, sulaikyk savo koją nuo jų tako;'),
  (@b20, 1, 16, 'nes jų kojos bėga į pikta ir skuba kraują pralieti.'),
  (@b20, 1, 17, 'Tikrai veltui tiesiamas tinklas bet kuriam paukščiui matant.'),
  (@b20, 1, 18, 'Jie tykoja savo pačių kraujo; jie slapta tykoja savo pačių gyvybės.'),
  (@b20, 1, 19, 'Tokie yra keliai kiekvieno, kuris godus pelno, kuris atima jo savininko gyvybę.'),
  (@b20, 1, 20, 'Išmintis šaukia lauke; ji gatvėse ištaria savo balsą;'),
  (@b20, 1, 21, 'ji šaukia svarbiausiose susibūrimo vietose, vartų ertmėse, mieste ji taria savo žodžius, sakydama:'),
  (@b20, 1, 22, '„Paikieji, kaip ilgai mylėsite paikybę? Ir kaip ilgai išjuokėjai mėgausis išjuokimu ir kvailiai nekęs pažinimo?'),
  (@b20, 1, 23, 'Gręžkitės į mano pabarimą; štai aš jums išliesiu savo dvasią, duosiu jums pažinti savo žodžius.'),
  (@b20, 1, 24, 'Kadangi šaukiau, o jūs atsisakėte; ištiesiau savo ranką, ir niekas nekreipė dėmesio;'),
  (@b20, 1, 25, 'bet jūs visą mano patarimą pavertėte nieku ir nenorėjote nei vieno mano pabarimo;'),
  (@b20, 1, 26, 'tai ir aš juoksiuosi iš jūsų nelaimės, tyčiosiuosi, kai ateis jūsų baimė;'),
  (@b20, 1, 27, 'kai ateis jūsų baimė lyg suniokojimas ir ateis jūsų sunaikinimas kaip viesulas; kai ant jūsų užeis sielvartas ir kančia.'),
  (@b20, 1, 28, 'Tada jie šauksis manęs, bet aš neatsakysiu; jie anksti manęs ieškos, bet neras manęs;'),
  (@b20, 1, 29, 'todėl, kad jie nekentė pažinimo ir nepasirinko VIEŠPATIES baimės;'),
  (@b20, 1, 30, 'jie nenorėjo nieko iš mano patarimo, jie paniekino visą mano pabarimą.'),
  (@b20, 1, 31, 'Todėl jie valgys savo pačių kelio vaisių ir pasisotins savo pačių sumanymais.'),
  (@b20, 1, 32, 'Nes paikųjų nusigręžimas juos nužudys ir kvailųjų klestėjimas juos sunaikins.'),
  (@b20, 1, 33, 'Bet kas manęs klauso, tas saugiai gyvens ir bus ramus, nebijodamas pikto“.'),
  (@b20, 2, 1, 'Mano sūnau, jei priimsi mano žodžius ir paslėpsi pas save mano įsakymus;'),
  (@b20, 2, 2, 'taip, jog palenksi savo ausį išminčiai ir nukreipsi savo širdį į supratimą;'),
  (@b20, 2, 3, 'taip, jei šauksies pažinimo ir pakelsi balsą dėl supratimo;'),
  (@b20, 2, 4, 'jei jo ieškosi kaip sidabro ir ieškosi jo kaip paslėptų lobių;'),
  (@b20, 2, 5, 'tada tu suprasi VIEŠPATIES baimę ir rasi Dievo pažinimą.'),
  (@b20, 2, 6, 'Nes VIEŠPATS duoda išmintį; iš jo burnos ateina pažinimas ir supratimas.'),
  (@b20, 2, 7, 'Jis kaupia sveiką išmintį teisiesiems; jis yra skydas tiems, kurie vaikšto tiesiai.'),
  (@b20, 2, 8, 'Jis saugo teismo takus ir išsaugo savo šventųjų kelią.'),
  (@b20, 2, 9, 'Tada tu suprasi teisumą, teismą ir bešališkumą, taip, kiekvieną gerą taką.'),
  (@b20, 2, 10, 'Kai išmintis įeina į tavo širdį, ir pažinimas yra malonus tavo sielai;'),
  (@b20, 2, 11, 'apdairumas tave apsaugos, supratimas tave saugos;'),
  (@b20, 2, 12, 'kad tave išgelbėtų nuo piktųjų kelio, nuo žmonių, kalbančių priešgynius dalykus;'),
  (@b20, 2, 13, 'kurie palieka tiesumo takus, kad vaikščiotų tamsybės keliais;'),
  (@b20, 2, 14, 'kurie džiaugiasi daryti pikta ir gėrisi nedorėlių priešgyniavimu;'),
  (@b20, 2, 15, 'kurių keliai kreivi, ir jie priešgyniaujantys savo takuose;'),
  (@b20, 2, 16, 'kad išvaduotų tave nuo svetimos moters, nuo svetimosios, viliojančios savo žodžiais;'),
  (@b20, 2, 17, 'kuri palieka savo jaunystės vadovą ir pamiršta savo Dievo sandorą.'),
  (@b20, 2, 18, 'Nes jos namai linksta į mirtį ir jos takai – į mirusiuosius.'),
  (@b20, 2, 19, 'Nei vienas, įeinantis pas ją, nesugrįžta ir nenutveria gyvenimo takų.'),
  (@b20, 2, 20, 'Kad tu vaikščiotum gerųjų keliu ir laikytumeisi teisiojo takų.'),
  (@b20, 2, 21, 'Nes tiesieji gyvens šalyje, ir tobulieji pasiliks joje.'),
  (@b20, 2, 22, 'Bet nedorėliai bus iškirsti iš žemės, ir nusižengėliai bus iš jos išrauti.'),
  (@b20, 3, 1, 'Mano sūnau, nepamiršk mano įstatymo; bet tavo širdis tesaugo mano įsakymus;'),
  (@b20, 3, 2, 'nes jie tau pridės dienų ilgumo, ilgą gyvenimą ir ramybę.'),
  (@b20, 3, 3, 'Gailestingumas ir tiesa tenepalieka tavęs: apsirišk jais savo kaklą; įrašyk juos į savo širdies plokštę;'),
  (@b20, 3, 4, 'taip rasi palankumą ir gerą supratimą Dievo ir žmonių akyse.'),
  (@b20, 3, 5, 'Pasitikėk VIEŠPAČIU visa savo širdimi; ir nesiremk savo supratimu.'),
  (@b20, 3, 6, 'Visuose savo keliuose pripažink jį, ir jis nukreips tavo takus.'),
  (@b20, 3, 7, 'Nebūk išmintingas savo akyse: bijok VIEŠPATIES ir atsitrauk nuo pikto.'),
  (@b20, 3, 8, 'Tai bus sveikata tavo bambai ir kaulų smegenys tavo kaulams.'),
  (@b20, 3, 9, 'Gerbk VIEŠPATĮ savo turtu ir viso savo prieaugio pirmavaisiais;'),
  (@b20, 3, 10, 'taip tavo svirnai prisipildys gausa, ir tavo spaustuvai pratrūks jaunu vynu.'),
  (@b20, 3, 11, 'Mano sūnau, nepaniekink VIEŠPATIES bausmės ir nebūk nuvargęs nuo jo pataisymų;'),
  (@b20, 3, 12, 'nes ką VIEŠPATS myli, tą pataiso; būtent kaip tėvas sūnų, kuriuo jis gėrisi.'),
  (@b20, 3, 13, 'Laimingas žmogus, kuris randa išmintį, ir žmogus, kuris įgauna supratimo.'),
  (@b20, 3, 14, 'Nes ja prekiauti geriau, negu prekiauti sidabru, ir jos pelnas vertingesnis už geriausią auksą.'),
  (@b20, 3, 15, 'Ji brangesnė už rubinus; ir visa, ko galėtum trokšti, jai neprilygsta.'),
  (@b20, 3, 16, 'Dienų ilgis jos dešinėje; o jos kairėje turtai ir garbė.'),
  (@b20, 3, 17, 'Jos keliai – malonūs keliai, ir visi jos takai – ramybė.'),
  (@b20, 3, 18, 'Ji yra gyvybės medis tiems, kurie ją nutveria; ir laimingas kiekvienas, kuris ją išlaiko.'),
  (@b20, 3, 19, 'VIEŠPATS išmintimi pastatė žemę ant pamato; supratimu įtvirtino dangus.'),
  (@b20, 3, 20, 'Jo pažinimu perskirtos gilybės, ir debesys laša rasa.'),
  (@b20, 3, 21, 'Mano sūnau, tenepasitraukia jie nuo tavo akių; saugok sveiką išmintį ir apdairumą;'),
  (@b20, 3, 22, 'taip jie bus gyvybė tavo sielai ir malonė tavo kaklui.'),
  (@b20, 3, 23, 'Tada saugiai vaikščiosi savo keliu, ir tavo koja nesuklups.'),
  (@b20, 3, 24, 'Atsigulęs nebijosi; taip, tu atsigulsi, ir tavo miegas bus saldus.'),
  (@b20, 3, 25, 'Nebijok staigios baimės ir nedorėlių niokojimo, kai tai ateis.'),
  (@b20, 3, 26, 'Nes VIEŠPATS bus tavo užtikrintumas ir apsaugos tavo koją, kad nebūtų sugauta.'),
  (@b20, 3, 27, 'Nesulaikyk gero nuo to, kuriam tai priklauso, kai tavo rankos valdžioje tai padaryti.'),
  (@b20, 3, 28, 'Nesakyk savo artimui: „Eik ir vėl ateik, ir rytoj tau duosiu“, kai tu turi su savimi.'),
  (@b20, 3, 29, 'Nesumanyk pikta prieš savo artimą, kadangi jis saugiai gyvena šalia tavęs.'),
  (@b20, 3, 30, 'Nesivaidyk be reikalo su žmogumi, jei jis tau jokios žalos nepadarė.'),
  (@b20, 3, 31, 'Nepavydėk engėjui ir nesirink nei vieno iš jo kelių.'),
  (@b20, 3, 32, 'Nes priešgyniaujantysis yra pasibjaurėjimas VIEŠPAČIUI, bet jo paslaptis yra su teisiuoju.'),
  (@b20, 3, 33, 'VIEŠPATIES prakeikimas yra nedorėlio namuose, bet teisiojo buveinę jis laimina.'),
  (@b20, 3, 34, 'Tikrai jis išjuokia pašaipūnus, bet nuolankiesiems duoda malonę.'),
  (@b20, 3, 35, 'Išmintingieji paveldės šlovę, bet kvailųjų paaukštinimas bus gėda.'),
  (@b20, 4, 1, 'Vaikai, klausykite tėvo pamokymo ir būkite atidūs, kad pažintumėte supratimą.'),
  (@b20, 4, 2, 'Nes aš duodu jums gerą mokslą, nepalikite mano įstatymo.'),
  (@b20, 4, 3, 'Nes aš buvau savo tėvo sūnus, gležnas ir vienintelis numylėtasis savo motinos akyse.'),
  (@b20, 4, 4, 'Taipogi jis mane mokė ir man sakė: „Tavo širdis teišlaiko mano žodžius; saugok mano įsakymus ir gyvenk.'),
  (@b20, 4, 5, 'Įsigyk išmintį, įsigyk supratimą; nepamiršk jų; ir nenukrypk nuo mano burnos žodžių.'),
  (@b20, 4, 6, 'Nepalik jos, ir ji tave apsaugos; mylėk ją, ir ji tave saugos.'),
  (@b20, 4, 7, 'Išmintis yra svarbiausias dalykas: todėl įsigyk išmintį; ir su viskuo, ką įsigysi, įsigyk supratimą.'),
  (@b20, 4, 8, 'Išaukštink ją, ir ji tave paaukštins; ji atves tave į garbę, kai ją apsikabinsi.'),
  (@b20, 4, 9, 'Ji tavo galvai duos malonės papuošalą; šlovės vainiką ji tau duos“.'),
  (@b20, 4, 10, 'Klausyk, mano sūnau, ir priimk mano pasakymus; ir daug bus tavo gyvenimo metų.'),
  (@b20, 4, 11, 'Išminties kelio tave mokiau, vedžiau tave teisingais takais.'),
  (@b20, 4, 12, 'Tau einant, nebus varžomi tavo žingsniai; ir kai bėgsi, nesuklupsi.'),
  (@b20, 4, 13, 'Tvirtai nusitverk pamokymo; jo nepaleisk; saugok jį; nes jis yra tavo gyvybė.'),
  (@b20, 4, 14, 'Į nedorėlių taką neįeik, ir neik piktųjų keliu.'),
  (@b20, 4, 15, 'Venk jo, neik juo, nusisuk nuo jo ir praeik pro šalį.'),
  (@b20, 4, 16, 'Nes jie neužmiega, nepadarę piktadarystės; ir atimamas jų miegas, jeigu jie nėra ko pargriovę.'),
  (@b20, 4, 17, 'Nes jie valgo nedorybės duoną ir geria smurto vyną.'),
  (@b20, 4, 18, 'Bet teisiųjų takas yra kaip spindinti šviesa, kuri šviečia vis labiau ir labiau iki tobulos dienos.'),
  (@b20, 4, 19, 'Nedorėlių kelias yra kaip tamsa: jie nežino, ant ko suklups.'),
  (@b20, 4, 20, 'Mano sūnau, kreipk dėmesį į mano žodžius; palenk ausį mano pasakymams.'),
  (@b20, 4, 21, 'Teneatsitraukia jie nuo tavo akių; saugok juos savo širdies viduje.'),
  (@b20, 4, 22, 'Nes jie yra gyvybė tiems, kurie juos randa, ir sveikata visam jų kūnui.'),
  (@b20, 4, 23, 'Visu stropumu saugok savo širdį; nes iš jos yra gyvenimo versmės.'),
  (@b20, 4, 24, 'Pašalink nuo savęs priešgyniaujančią burną, ir iškrypusias lūpas pašalink toli nuo savęs.'),
  (@b20, 4, 25, 'Tavo akys težvelgia tiesiai į priekį, ir tavo akių vokai težiūri tiesiai prieš tave.'),
  (@b20, 4, 26, 'Apgalvok savo kojų taką, ir visi tavo keliai tebūna įtvirtinti.'),
  (@b20, 4, 27, 'Nesuk nei į dešinę, nei į kairę; atitrauk savo koją nuo pikto.'),
  (@b20, 5, 1, 'Mano sūnau, būk dėmesingas mano išminčiai ir palenk ausį mano supratimui;'),
  (@b20, 5, 2, 'kad paisytum apdairumo ir kad tavo lūpos saugotų pažinimą.'),
  (@b20, 5, 3, 'Nes svetimos moters lūpos varva kaip medaus korys ir jos burna švelnesnė už aliejų;'),
  (@b20, 5, 4, 'bet jos galas yra kartus kaip metėlė, aštrus kaip dviašmenis kalavijas.'),
  (@b20, 5, 5, 'Jos kojos eina žemyn į mirtį; jos žingsniai nusitveria pragaro.'),
  (@b20, 5, 6, 'Kad tu nemąstytum apie gyvenimo taką, jos keliai nepastovūs, jog tu negali jų pažinti.'),
  (@b20, 5, 7, 'Taigi dabar, vaikai, klausykite manęs ir neatsitraukite nuo mano burnos žodžių.'),
  (@b20, 5, 8, 'Atitolink nuo jos savo kelią ir nesiartink prie jos namų durų;'),
  (@b20, 5, 9, 'kad neatiduotum savo garbės kitiems ir savo metų žiauriajam;'),
  (@b20, 5, 10, 'kad svetimieji nesisotintų tavo turtais; ir kad tavo triūsas nebūtų svetimojo namuose;'),
  (@b20, 5, 11, 'ir galiausiai neliūdėtum, kai sunyks tavo mėsa ir tavo kūnas,'),
  (@b20, 5, 12, 'ir nesakytum: „O, kaip nekenčiau pamokymo, ir mano širdis paniekino pabarimą;'),
  (@b20, 5, 13, 'ir nepaklusau savo mokytojų balsui, ir nepalenkiau savo ausies tiems, kurie mane mokė!'),
  (@b20, 5, 14, 'Aš vos nepatekau į visokią blogybę susirinkimo ir sueigos viduryje“.'),
  (@b20, 5, 15, 'Gerk vandenis iš savo paties rezervuaro ir tekančius vandenis iš savo paties šulinio.'),
  (@b20, 5, 16, 'Teišsilieja tavo šaltiniai lauke ir vandenų upės gatvėse.'),
  (@b20, 5, 17, 'Tebūna jie tik tavo, o ne svetimųjų su tavimi.'),
  (@b20, 5, 18, 'Tebūna tavo šaltinis palaimintas; ir džiaukis su savo jaunystės žmona.'),
  (@b20, 5, 19, 'Ji tebūna kaip mylinti elnė ir maloni stirna; jos krūtys tepatenkina tave visais laikais; ir visada mėgaukis jos meile.'),
  (@b20, 5, 20, 'Ir kodėl, mano sūnau, nori mėgautis svetima moterimi, apkabinti svetimosios krūtinę?'),
  (@b20, 5, 21, 'Nes prieš VIEŠPATIES akis yra žmogaus keliai, ir jis apsvarsto visus jo ėjimus.'),
  (@b20, 5, 22, 'Nedorėlį sugaus jo paties neteisybės, ir jis bus sulaikomas savo nuodėmių virvėmis.'),
  (@b20, 5, 23, 'Jis mirs nepamokytas; ir dėl savo didelės kvailybės jis nuklys.'),
  (@b20, 6, 1, 'Mano sūnau, jei laiduoji už savo draugą, jei sukirtai rankas su svetimu,'),
  (@b20, 6, 2, 'tu įsipainiojai savo burnos žodžiais, tu esi sugautas savo burnos žodžiais.'),
  (@b20, 6, 3, 'Daryk šitaip, mano sūnau, ir išsivaduok, kai pateksi į savo draugo rankas: eik, nusižemink ir užsitikrink dėl savo draugo.'),
  (@b20, 6, 4, 'Neduok miegoti savo akims nei snausti savo akių vokams.'),
  (@b20, 6, 5, 'Išsivaduok kaip stirna iš medžiotojo rankos ir kaip paukštis iš paukštgaudžio rankos.'),
  (@b20, 6, 6, 'Eik pas skruzdėlę, tinginy; įsižiūrėk į jos kelius ir būk išmintingas;'),
  (@b20, 6, 7, 'ji, neturėdama vadovo, prižiūrėtojo ar valdovo,'),
  (@b20, 6, 8, 'parūpina savo valgį vasarą, ir pjūties metu renka savo maistą.'),
  (@b20, 6, 9, 'Kaip ilgai miegosi, tinginy? Kada kelsiesi iš savo miego?'),
  (@b20, 6, 10, 'Dar truputį miego, truputį pasnausi, truputį susidėjęs rankas pamiegosi;'),
  (@b20, 6, 11, 'taip ateis tavo skurdas kaip pakeleivis ir tavo stoka kaip ginkluotas vyras.'),
  (@b20, 6, 12, 'Nenaudėlis žmogus, nedoras žmogus, vaikštinėja su priešgyniaujančia burna.'),
  (@b20, 6, 13, 'Jis mirkčioja akimis, kalba kojomis, moko pirštais;'),
  (@b20, 6, 14, 'priešgyniavimas jo širdyje, jis nuolat planuoja piktadarystę; jis sėja nesutarimus.'),
  (@b20, 6, 15, 'Todėl staiga ateis jo nelaimė; staiga jis bus sulaužytas nepagydomai.'),
  (@b20, 6, 16, 'VIEŠPATS nekenčia šitų šešių dalykų; taip, septyni yra jam pasibjaurėjimas:'),
  (@b20, 6, 17, 'išdidus žvilgsnis, meluojantis liežuvis ir rankos, praliejančios nekaltą kraują,'),
  (@b20, 6, 18, 'širdis, sugalvojanti nedorus sumanymus, kojos, greitos bėgti į piktadarybę,'),
  (@b20, 6, 19, 'melagingas liudytojas, kalbantis melus, ir tas, kuris sėja nesutarimus tarp brolių.'),
  (@b20, 6, 20, 'Mano sūnau, saugok savo tėvo įsakymą ir neatsižadėk savo motinos įstatymo;'),
  (@b20, 6, 21, 'nuolat juos prisirišk prie širdies ir apsirišk juos aplinkui kaklą.'),
  (@b20, 6, 22, 'Tau einant jie lydės tave; tau miegant jie saugos tave; o tau atsibudus jie kalbės su tavimi.'),
  (@b20, 6, 23, 'Nes įsakymas yra žibintas; o įstatymas – šviesa; o pamokantys pabarimai – gyvenimo kelias;'),
  (@b20, 6, 24, 'kad tave saugotų nuo piktos moters, nuo svetimos moters liežuvio meilikavimo.'),
  (@b20, 6, 25, 'Negeisk jos grožio savo širdyje, ir tenesugauna ji tavęs savo akių vokais.'),
  (@b20, 6, 26, 'Nes dėl paleistuvaujančios moters vyras lieka tik su duonos kąsniu; o svetimautoja medžioja brangią gyvybę.'),
  (@b20, 6, 27, 'Ar gali žmogus paimti ugnį į savo užantį ir nesudeginti savo drabužių?'),
  (@b20, 6, 28, 'Ar gali kas vaikščioti ant karštų žarijų ir nenudegti kojų?'),
  (@b20, 6, 29, 'Taip ir tas, kuris įeina pas savo artimo žmoną; kas paliečia ją, neliks nekaltas.'),
  (@b20, 6, 30, 'Žmonės nepaniekina vagies, jei jis vagia, kad patenkintų savo sielą, kai yra alkanas;'),
  (@b20, 6, 31, 'bet jei jį užtiks, jis atlygins septyneriopai; jis duos visą savo namų turtą.'),
  (@b20, 6, 32, 'Bet kas svetimauja su moterimi, tam stinga supratimo; kuris tai daro, tas pražudo savo sielą.'),
  (@b20, 6, 33, 'Jis įgis žaizdą ir negarbę; ir jo priekaištas nebus išdildytas.'),
  (@b20, 6, 34, 'Nes pavydas yra vyro įniršis; todėl jis nepasigailės keršto dieną.'),
  (@b20, 6, 35, 'Jis nepaisys jokios išpirkos; ir neliks pasitenkinęs, nors ir duotum jam daug dovanų.'),
  (@b20, 7, 1, 'Mano sūnau, saugok mano žodžius ir mano įsakymus kaupk pas save.'),
  (@b20, 7, 2, 'Saugok mano įsakymus ir gyvenk, ir mano įstatymą kaip savo akies obuolį.'),
  (@b20, 7, 3, 'Užsirišk juos sau ant pirštų, įsirašyk juos į savo širdies plokštę.'),
  (@b20, 7, 4, 'Sakyk išminčiai: „Tu mano sesuo“; o supratimą vadink giminaičiu;'),
  (@b20, 7, 5, 'kad jie saugotų tave nuo svetimos moters, nuo pašalietės, meilikaujančios savo žodžiais.'),
  (@b20, 7, 6, 'Nes prie savo namų lango žiūrėjau pro savo groteles'),
  (@b20, 7, 7, 'ir mačiau tarp paikųjų, pastebėjau jaunų tarpe neturintį supratimo jaunuolį,'),
  (@b20, 7, 8, 'einantį per gatvę arti jos kampo; ir jis ėjo keliu jos namų link,'),
  (@b20, 7, 9, 'prieblandoje, vakare, juodą ir tamsią naktį;'),
  (@b20, 7, 10, 'ir štai jį pasitiko moteris paleistuvės drabužiais ir klastinga širdimi'),
  (@b20, 7, 11, '(ji triukšminga ir užsispyrusi; jos kojos nepasilieka jos namuose;'),
  (@b20, 7, 12, 'ji tai lauke, tai gatvėse, ir tykoja prie kiekvieno kampo).'),
  (@b20, 7, 13, 'Taigi ji nutvėrė jį ir pabučiavo, ir begėdišku veidu jam tarė:'),
  (@b20, 7, 14, '„Aš turiu taikos atnašas; šią dieną ištesėjau savo įžadus.'),
  (@b20, 7, 15, 'Todėl išėjau tavęs pasitikti, uoliai tavo veido ieškoti, ir suradau tave.'),
  (@b20, 7, 16, 'Aš paklojau savo lovą gobeleno apklotu, išmargintais dirbiniais, plonu Egipto linu.'),
  (@b20, 7, 17, 'Iškvėpinau savo patalą mira, alaviju ir cinamonu.'),
  (@b20, 7, 18, 'Eikš, sotinkimės meile iki ryto; pasiguoskime meilėmis.'),
  (@b20, 7, 19, 'Nes vyro nėra namuose, jis išvyko į tolimą kelionę;'),
  (@b20, 7, 20, 'jis pasiėmė su savimi pinigų maišelį ir parvyks namo nustatytą dieną“.'),
  (@b20, 7, 21, 'Daugybe gražių kalbų ji paskatino jį pasiduoti, savo lūpų meilikavimu jį privertė.'),
  (@b20, 7, 22, 'Jis nedelsiant nueina paskui ją, kaip jautis eina, kad būtų papjautas, arba kaip kvailys, kad būtų nubaustas trinkose;'),
  (@b20, 7, 23, 'kol strėlė pervers jo kepenis; kaip paukštis skuba į spąstus ir nesupranta, kad tie yra jo gyvybei.'),
  (@b20, 7, 24, 'Taigi dabar, vaikai, klausykite manęs ir būkite dėmesingi mano burnos žodžiams.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b20, 7, 25, 'Tegul tavo širdis nepalinksta į jos kelius, nenuklysk jos takais.'),
  (@b20, 7, 26, 'Nes ji parbloškė daug sužeistųjų; taip, daug stipruolių yra jos nužudytų.'),
  (@b20, 7, 27, 'Jos namai – kelias į pragarą, einantis žemyn į mirties kambarius.'),
  (@b20, 8, 1, 'Argi išmintis nešaukia ir supratimas neišleidžia savo balso?'),
  (@b20, 8, 2, 'Viršuje aukštumų, prie kelio, takų vietose ji stovi.'),
  (@b20, 8, 3, 'Prie vartų, prie miesto įėjimo, prie įėjimo pro duris ji šaukia:'),
  (@b20, 8, 4, '„Žmonės, jūsų šaukiuosi, ir mano balsas žmonių sūnums:'),
  (@b20, 8, 5, 'Jūs, paikieji, supraskite išmintį; ir jūs, kvailiai, būkite supratinga širdimi.'),
  (@b20, 8, 6, 'Klausykite, nes kalbėsiu apie puikius dalykus; ir mano lūpos prasivers tuo, kas teisinga.'),
  (@b20, 8, 7, 'Nes mano burna kalbės tiesą; ir nedorybė yra pasibjaurėjimas mano lūpoms.'),
  (@b20, 8, 8, 'Visi mano burnos žodžiai yra teisume; nėra juose nieko priešgyningo ar iškreipto.'),
  (@b20, 8, 9, 'Jie visi yra aiškūs suprantantiems ir teisingi randantiems pažinimą.'),
  (@b20, 8, 10, 'Priimkite mano pamokymą, o ne sidabrą; ir verčiau pažinimą, negu rinktinį auksą.'),
  (@b20, 8, 11, 'Nes išmintis yra geresnė už rubinus; ir jai neprilygsta niekas iš viso to, ko galima trokšti.'),
  (@b20, 8, 12, 'Aš, išmintis, gyvenu drauge su protingumu, ir atrandu sąmojingų sumanymų pažinimą.'),
  (@b20, 8, 13, 'VIEŠPATIES baimė – nekęsti pikto; išdidumo, išpuikimo, pikto kelio ir priešgynios burnos aš nekenčiu.'),
  (@b20, 8, 14, 'Mano yra patarimas ir sveika išmintis; aš esu supratimas; aš turiu stiprybę.'),
  (@b20, 8, 15, 'Manimi karaliai karaliauja ir kunigaikščiai paskelbia teisingumą.'),
  (@b20, 8, 16, 'Manimi valdo kunigaikščiai ir kilmingieji – visi žemės teisėjai.'),
  (@b20, 8, 17, 'Aš myliu tuos, kurie mane myli; ir kas anksti manęs ieško, suras mane.'),
  (@b20, 8, 18, 'Turtai ir garbė yra pas mane; taip, išliekantys turtai ir teisumas.'),
  (@b20, 8, 19, 'Mano vaisiai geresni už auksą, taip, už gryną auksą; ir mano pajamos – už rinktinį sidabrą.'),
  (@b20, 8, 20, 'Aš vedu teisumo keliu, teismo takų viduriu,'),
  (@b20, 8, 21, 'idant mane mylintiems duočiau paveldėti turtą; ir aš pripildysiu jų lobynus.'),
  (@b20, 8, 22, 'VIEŠPATS turėjo mane savo kelio pradžioje, pirmiau savo senųjų darbų.'),
  (@b20, 8, 23, 'Nuo amžinybės aš pastatyta, nuo pradžios, prieš žemės buvimą.'),
  (@b20, 8, 24, 'Aš buvau pagimdyta, kai dar nebuvo gelmių; kai dar nebuvo šaltinių, gausių vandens.'),
  (@b20, 8, 25, 'Prieš tai, kai buvo padėti kalnai, pirma kalvų aš buvau pagimdyta;'),
  (@b20, 8, 26, 'kol jis dar nebuvo padaręs nei žemės, nei laukų, nei pasaulio dulkių pirmučiausios dalies.'),
  (@b20, 8, 27, 'Kai jis ruošė dangus, aš ten buvau; kai jis nustatė apskritimą ant gelmių paviršiaus;'),
  (@b20, 8, 28, 'kai jis įtvirtino debesis aukštai; kai jis sutvirtino gelmių šaltinius;'),
  (@b20, 8, 29, 'kai jis davė jūrai savo įsaką, kad vandenys neperžengtų jo įsakymo; kai jis nustatė žemės pamatus;'),
  (@b20, 8, 30, 'tada aš buvau šalia jo kaip pas jį išauklėta; ir kasdien buvau jo pasigėrėjimas, visuomet džiūgaudama jo akivaizdoje;'),
  (@b20, 8, 31, 'džiūgaudama jo žemės gyvenamoje vietoje; ir mano pasigėrėjimai buvo su žmonių sūnumis.'),
  (@b20, 8, 32, 'Taigi dabar, vaikai, klausykite manęs; nes palaiminti tie, kurie saugo mano kelius.'),
  (@b20, 8, 33, 'Klausykite pamokymo ir būkite išmintingi, ir neatmeskite jo.'),
  (@b20, 8, 34, 'Palaimintas žmogus, kuris manęs klauso, kasdien budėdamas prie mano vartų, laukdamas prie mano durų statramsčių.'),
  (@b20, 8, 35, 'Nes kas randa mane, randa gyvenimą ir įgis VIEŠPATIES palankumą.'),
  (@b20, 8, 36, 'Bet kas nusideda prieš mane, tas kenkia savo paties sielai; visi, kurie manęs nekenčia, myli mirtį“.'),
  (@b20, 9, 1, 'Išmintis pastatė savo namus, ji iškirto savo septynis stulpus;'),
  (@b20, 9, 2, 'ji papjovė savo gyvulius; sumaišė savo vyną; taip pat paruošė savo stalą.'),
  (@b20, 9, 3, 'Ji išsiuntė savo tarnaites; ji šaukia miesto aukščiausiose vietose:'),
  (@b20, 9, 4, '„Kas paikas, tas teužsuka čia“; kam stinga supratimo, tam ji sako:'),
  (@b20, 9, 5, '„Ateikite, valgykite mano duonos ir gerkite vyno, kurį sumaišiau.'),
  (@b20, 9, 6, 'Palikite kvailąjį ir gyvenkite; ir eikite supratimo keliu“.'),
  (@b20, 9, 7, 'Kas pabara pašaipūną, tas užsitraukia gėdą; ir kas pabara nedorėlį, tas užsitraukia dėmę.'),
  (@b20, 9, 8, 'Nebark pašaipūno, kad jis neimtų tavęs nekęsti; pabark išmintingą, ir jis tave mylės.'),
  (@b20, 9, 9, 'Pamokyk išmintingąjį, ir jis bus dar išmintingesnis; mokyk teisųjį, ir jis daugiau išmoks.'),
  (@b20, 9, 10, 'VIEŠPATIES baimė – išminties pradžia; ir šventojo pažinimas – supratimas.'),
  (@b20, 9, 11, 'Nes per mane padaugės tavo dienų ir padaugės tavo gyvenimo metų.'),
  (@b20, 9, 12, 'Jei esi išmintingas, esi išmintingas sau pačiam; bet jei pajuoki, tu vienas turėsi tai pakęsti.'),
  (@b20, 9, 13, 'Kvaila moteris yra triukšminga, ji paika ir nieko nežinanti.'),
  (@b20, 9, 14, 'Nes ji sėdi prie savo namų durų, ant krėslo aukštose miesto vietose,'),
  (@b20, 9, 15, 'kad pašauktų keleivius, tiesiai einančius savo keliais:'),
  (@b20, 9, 16, '„Kas paikas, teužsuka čia“; ir kam stinga supratimo, tam ji sako:'),
  (@b20, 9, 17, '„Vogti vandenys saldūs, ir slaptoje valgoma duona maloni“.'),
  (@b20, 9, 18, 'Bet jis nežino, kad ten yra mirusieji ir kad jos svečiai yra pragaro gilumose.'),
  (@b20, 10, 1, 'Saliamono patarlės. Išmintingas sūnus džiugina tėvą, bet kvailas sūnus – liūdesys jo motinai.'),
  (@b20, 10, 2, 'Nedorybės lobiai neduoda jokios naudos, bet teisumas išvaduoja nuo mirties.'),
  (@b20, 10, 3, 'VIEŠPATS neleis badauti teisiojo sielai, bet jis atmeta nedorėlių turtą.'),
  (@b20, 10, 4, 'Kas tvarko reikalus tingia ranka, tas tampa beturčiu, bet stropiųjų ranka praturtina.'),
  (@b20, 10, 5, 'Kas renka vasaros metu, tas yra išmintingas sūnus, bet kas pjūties metu miega, tas yra sūnus, darantis gėdą.'),
  (@b20, 10, 6, 'Palaiminimai yra ant teisiojo galvos, bet nedorėlių burną dengia smurtas.'),
  (@b20, 10, 7, 'Teisiojo atminimas yra palaimintas, bet nedorėlio vardas supus.'),
  (@b20, 10, 8, 'Išmintingas širdimi priims įsakymus, bet tauškantis kvailys pargrius.'),
  (@b20, 10, 9, 'Kas vaikšto tiesiai, užtikrintai vaikšto, bet kas iškraipo savo kelius, bus žinomas.'),
  (@b20, 10, 10, 'Kas mirkčioja akimi, sukelia sielvartą, bet tauškantis kvailys pargrius.'),
  (@b20, 10, 11, 'Teisiojo burna yra gyvenimo šaltinis, bet nedorėlių burną dengia smurtas.'),
  (@b20, 10, 12, 'Neapykanta sukelia vaidus, bet meilė apdengia visas nuodėmes.'),
  (@b20, 10, 13, 'Suprantančiojo lūpose randama išmintis, bet lazda yra nesuprantančiojo nugarai.'),
  (@b20, 10, 14, 'Išmintingieji kaupia pažinimą, bet kvailojo burna arti pražūties.'),
  (@b20, 10, 15, 'Turtingojo turtas yra jo stiprus miestas, vargšų pražūtis – jų neturtas.'),
  (@b20, 10, 16, 'Teisiojo triūsas veda į gyvenimą, nedorėlio vaisius – į nuodėmę.'),
  (@b20, 10, 17, 'Kas laikosi pamokymo, tas yra gyvenimo kelyje; bet kas atmeta pabarimą – klysta.'),
  (@b20, 10, 18, 'Kas slepia neapykantą meluojančiomis lūpomis ir kas ištaria šmeižtą, tas yra kvailys.'),
  (@b20, 10, 19, 'Žodžių daugybėje nestinga nuodėmės, bet kas sulaiko savo lūpas, yra išmintingas.'),
  (@b20, 10, 20, 'Teisiojo liežuvis – kaip rinktinis sidabras, nedorėlio širdis – mažavertė.'),
  (@b20, 10, 21, 'Teisiojo lūpos gano daugelį, bet kvailieji miršta dėl išminties stokos.'),
  (@b20, 10, 22, 'VIEŠPATIES palaiminimas daro turtingą, ir jis prie to neprideda sielvarto.'),
  (@b20, 10, 23, 'Kvailiui daryti pikta – pramoga, bet suprantantis žmogus turi išmintį.'),
  (@b20, 10, 24, 'Nedorėlio baimė – ji ateis ant jo, bet teisiojo troškimas bus patenkintas.'),
  (@b20, 10, 25, 'Kaip viesulas praeina, taip nebelieka nedorėlio; bet teisusis yra amžinas pamatas.'),
  (@b20, 10, 26, 'Kaip actas dantims ir dūmai akims, taip tinginys tiems, kurie jį siunčia.'),
  (@b20, 10, 27, 'VIEŠPATIES baimė prailgina dienas, bet nedorėlių metai bus sutrumpinti.'),
  (@b20, 10, 28, 'Teisiųjų viltis bus džiaugsmas, bet nedorėlių lūkestis pražus.'),
  (@b20, 10, 29, 'VIEŠPATIES kelias yra stiprybė tiesiesiems, bet pražūtis bus darantiems neteisybę.'),
  (@b20, 10, 30, 'Teisusis niekada nebus pašalintas, bet nedorėlis nepaveldės žemės.'),
  (@b20, 10, 31, 'Teisiojo burna skleidžia išmintį, bet priešgyniaujantis liežuvis bus išpjautas.'),
  (@b20, 10, 32, 'Teisiojo lūpos žino, kas yra priimtina, bet nedorėlių burna kalba priešgyniavimą.'),
  (@b20, 11, 1, 'Melagingos svarstyklės – pasibjaurėjimas VIEŠPAČIUI, bet teisingos svarstyklės jam pasigėrėjimas.'),
  (@b20, 11, 2, 'Atėjus išdidumui, ateina ir gėda, bet su nuolankiaisiais yra išmintis.'),
  (@b20, 11, 3, 'Tiesiųjų nekaltumas juos vedžios, bet nusižengėlių iškrypimas juos sunaikins.'),
  (@b20, 11, 4, 'Turtai nėra naudingi rūstybės dieną, bet teisumas išvaduoja nuo mirties.'),
  (@b20, 11, 5, 'Tobulojo teisumas nukreips jo kelią, bet nedorėlis pargrius per savo nedorumą.'),
  (@b20, 11, 6, 'Tiesiųjų teisumas juos išvaduos, bet nusižengėliai bus sugauti savo pačių nepaklusnume.'),
  (@b20, 11, 7, 'Nedorėliui mirštant, jo lūkesčiai pražus, ir neteisiųjų viltis pražūsta.'),
  (@b20, 11, 8, 'Teisusis išvaduojamas iš bėdos, o nedorėlis atsiduria jo vietoje.'),
  (@b20, 11, 9, 'Veidmainys savo burna sunaikina savo artimą, bet teisusis bus išvaduotas per pažinimą.'),
  (@b20, 11, 10, 'Kai gerai sekasi teisiesiems, džiūgauja miestas, o nedorėliams žūstant, būna šūksniai.'),
  (@b20, 11, 11, 'Tiesiųjų palaiminimu miestas išaukštinamas, bet nedorėlių burna jis yra sugriaunamas.'),
  (@b20, 11, 12, 'Kas neturi išminties, tas niekina savo artimą, bet suprantantis žmogus tyli.'),
  (@b20, 11, 13, 'Liežuvautojas atskleidžia paslaptis, bet kas yra ištikimos dvasios, tas reikalą slepia.'),
  (@b20, 11, 14, 'Kai nėra patarimo, tauta nupuola, bet saugumas – kai daug patarėjų.'),
  (@b20, 11, 15, 'Kas laiduoja už svetimąjį, už tai nukentės, o kas nekenčia laidavimo, yra saugus.'),
  (@b20, 11, 16, 'Maloninga moteris išlaiko garbę, o stiprieji išlaiko turtus.'),
  (@b20, 11, 17, 'Gailestingas žmogus daro gera savo sielai, bet žiaurusis vargina savo kūną.'),
  (@b20, 11, 18, 'Nedorėlis daro apgaulingą darbą, bet kas sėja teisumą, tam bus užtikrintas užmokestis.'),
  (@b20, 11, 19, 'Kaip teisumas veda į gyvenimą, taip tas, kuris vejasi pikta, vejasi tai savo mirčiai.'),
  (@b20, 11, 20, 'Tie, kurie yra priešgynios širdies, yra pasibjaurėjimas VIEŠPAČIUI, bet tiesieji savo kelyje yra jo pasigėrėjimas.'),
  (@b20, 11, 21, 'Nors ir susijungtų rankos, nedorėliai neliks nenubausti; bet teisiųjų sėkla bus išvaduota.'),
  (@b20, 11, 22, 'Kaip auksinė brangenybė kiaulės knyslėje, taip graži moteris, neturinti supratimo.'),
  (@b20, 11, 23, 'Teisiųjų troškimas yra tik gera, bet nedorėlių lūkestis – rūstybė.'),
  (@b20, 11, 24, 'Yra kas beria, tačiau priauga; ir yra kas pasilaiko daugiau negu dera, bet nuskursta.'),
  (@b20, 11, 25, 'Dosni siela bus nupenėta, ir kas pagirdo, pats bus pagirdytas.'),
  (@b20, 11, 26, 'Kas sulaiko javus, tą tauta prakeiks; bet palaiminimas bus ant galvos to, kuris juos parduoda.'),
  (@b20, 11, 27, 'Kas stropiai ieško gero, tas įgyja palankumą; bet kas siekia piktadarystės, ta jį užklups.'),
  (@b20, 11, 28, 'Kas pasitiki savo turtais, tas nupuls; bet teisusis vešės kaip šaka.'),
  (@b20, 11, 29, 'Kas vargina savo namus, paveldės vėją; ir kvailys bus tarnas išmintingajam širdimi.'),
  (@b20, 11, 30, 'Teisiojo vaisius yra gyvenimo medis; ir kas laimi sielas, yra išmintingas.'),
  (@b20, 11, 31, 'Štai teisiajam bus atlyginta žemėje; juo labiau nedorėliui ir nusidėjėliui.'),
  (@b20, 12, 1, 'Kas myli pamokymą, myli pažinimą, bet kas nekenčia pabarimo, yra neprotingas.'),
  (@b20, 12, 2, 'Geras žmogus įgyja VIEŠPATIES palankumą, bet nedorų užmačių žmogų jis pasmerks.'),
  (@b20, 12, 3, 'Žmogus neįsitvirtins nedorybe, bet teisiųjų šaknis nepajudinama.'),
  (@b20, 12, 4, 'Dorybinga moteris yra vainikas jos vyrui, bet ta, kuri daro gėdą, yra kaip puvinys jo kauluose.'),
  (@b20, 12, 5, 'Teisiųjų mintys yra teisingos, bet nedorėlių patarimai – apgaulė.'),
  (@b20, 12, 6, 'Nedorėlių žodžiai – kraujo tykojimas, bet tiesiųjų burna juos išvaduos.'),
  (@b20, 12, 7, 'Nedorėliai pargriaunami, ir jų nebėra, bet teisiųjų namai stovės.'),
  (@b20, 12, 8, 'Žmogus giriamas pagal jo išmintį; bet kas yra iškreiptos širdies, bus paniekintas.'),
  (@b20, 12, 9, 'Kas niekinamas ir turi tarną, yra geresnis už tą, kuris save gerbia ir stokoja duonos.'),
  (@b20, 12, 10, 'Teisusis atsižvelgia į savo gyvulio gyvybę, bet nedorėlio švelnūs gailestingumai yra žiaurūs.'),
  (@b20, 12, 11, 'Kas įdirba savo žemę, tas pasisotins duona, bet kas seka tuščiais žmonėmis, tas neturi supratimo.'),
  (@b20, 12, 12, 'Nedorėlis trokšta piktųjų tinklo, bet teisiųjų šaknis duoda vaisių.'),
  (@b20, 12, 13, 'Nedorėlis įkliūna į savo lūpų nusižengimą, bet teisusis išeis iš bėdos.'),
  (@b20, 12, 14, 'Žmogus pasisotins geru iš savo burnos vaisių, ir žmogui bus atlyginta jo rankų atpildu.'),
  (@b20, 12, 15, 'Kvailojo kelias teisingas jo paties akyse, bet kas klauso patarimo, yra išmintingas.'),
  (@b20, 12, 16, 'Kvailio rūstybė tuoj pat žinoma, bet protingas žmogus pridengia gėdą.'),
  (@b20, 12, 17, 'Kas kalba tiesą, skelbia teisumą, bet melagingas liudytojas – apgaulę.'),
  (@b20, 12, 18, 'Yra kas kalba tarsi kalavijo dūriais, bet išmintingųjų liežuvis yra sveikata.'),
  (@b20, 12, 19, 'Tiesos lūpos bus įtvirtintos amžiams, bet meluojantis liežuvis tik akimirksniui.'),
  (@b20, 12, 20, 'Apgaulė yra širdyje tų, kurie sumano pikta, bet taikos patarėjams – džiaugsmas.'),
  (@b20, 12, 21, 'Teisiajam neatsitiks nieko pikto; bet nedorėliai bus pripildyti nelaimių.'),
  (@b20, 12, 22, 'Meluojančios lūpos yra pasibjaurėjimas VIEŠPAČIUI, bet kurie teisingai elgiasi, tie yra jo pasigėrėjimas.'),
  (@b20, 12, 23, 'Protingas žmogus nuslepia pažinimą; bet kvailio širdis skelbia kvailystę.'),
  (@b20, 12, 24, 'Stropiųjų ranka valdys, bet tinginiams bus uždėta duoklė.'),
  (@b20, 12, 25, 'Liūdesys žmogaus širdyje ją smukdo, bet geras žodis ją pradžiugina.'),
  (@b20, 12, 26, 'Teisusis pranoksta savo artimą, bet nedorėlių kelias juos suvedžioja.'),
  (@b20, 12, 27, 'Tinginys nekepa to, ką sumedžiojo, bet brangus darbštaus žmogaus turtas.'),
  (@b20, 12, 28, 'Teisumo kelyje – gyvenimas, ir ant jo tako nėra mirties.'),
  (@b20, 13, 1, 'Išmintingas sūnus išklauso savo tėvo pamokymo, bet pašaipūnas neklauso barimo.'),
  (@b20, 13, 2, 'Savo burnos vaisiumi žmogus valgys tai, kas gera, bet nusižengėlių siela valgys smurtą.'),
  (@b20, 13, 3, 'Kas saugo savo burną, saugo savo gyvybę, bet kas plačiai atveria savo lūpas, tam bus pražūtis.'),
  (@b20, 13, 4, 'Tinginio siela trokšta, o nieko neturi, bet darbščiojo siela bus nupenėta.'),
  (@b20, 13, 5, 'Teisusis nekenčia melo, bet nedorėlis yra pasibjaurėtinas ir užsitraukia gėdą.'),
  (@b20, 13, 6, 'Teisumas saugo tiesųjį kelyje, bet nedorumas pargriauna nusidėjėlį.'),
  (@b20, 13, 7, 'Yra kas dedasi turtingas, tačiau nieko neturi; yra kas dedasi vargšas, tačiau turi daug turtų.'),
  (@b20, 13, 8, 'Žmogaus gyvybės išpirka yra jo turtai, bet vargšas negirdi pabarimo.'),
  (@b20, 13, 9, 'Teisiųjų šviesa džiūgauja, bet nedorėlių žibintas užges.'),
  (@b20, 13, 10, 'Tik per išdidumą kyla ginčas, bet pas tuos, kuriems gerai patarta, – išmintis.'),
  (@b20, 13, 11, 'Tuštybe įgytas turtas sumažės, bet kas renka triūsdamas, jį padaugins.'),
  (@b20, 13, 12, 'Atidėliojama viltis susargdina širdį, bet išsipildęs troškimas yra gyvybės medis.'),
  (@b20, 13, 13, 'Kas niekina žodį, bus sunaikintas; bet kas bijo įsakymo, tam bus atlyginta.'),
  (@b20, 13, 14, 'Išmintingojo įstatymas – gyvenimo šaltinis, atitraukiantis nuo mirties žabangų.'),
  (@b20, 13, 15, 'Geras supratimas suteikia palankumą, bet nusižengėlių kelias yra sunkus.'),
  (@b20, 13, 16, 'Kiekvienas protingas žmogus elgiasi pažinimu, bet kvailys viešai išstato savo kvailystę.'),
  (@b20, 13, 17, 'Nedoras pasiuntinys įpuola į nelaimę, bet ištikimas pasiuntinys – sveikata.'),
  (@b20, 13, 18, 'Skurdas ir gėda bus tam, kuris atmeta pamokymą, bet kas paiso pabarimo, bus gerbiamas.'),
  (@b20, 13, 19, 'Išpildytas troškimas malonus sielai; bet kvailiams pasibjaurėtina trauktis nuo pikto.'),
  (@b20, 13, 20, 'Kas vaikšto su išmintingais, bus išmintingas, bet kvailių draugas pražus.'),
  (@b20, 13, 21, 'Nusidėjėlius persekioja pikta, bet teisiesiems bus atlyginta geru.'),
  (@b20, 13, 22, 'Geras žmogus palieka paveldą savo vaikų vaikams, o nusidėjėlio turtas yra sukauptas teisiajam.'),
  (@b20, 13, 23, 'Daug maisto vargšų arimuose, bet yra pražuvusių dėl teismo stokos.'),
  (@b20, 13, 24, 'Kas gailisi savo rykštės, nekenčia savo sūnaus; bet kas jį myli, laiku jį baudžia.'),
  (@b20, 13, 25, 'Teisusis valgo savo sielai patenkinti, bet nedorėlių pilvas stokos.'),
  (@b20, 14, 1, 'Kiekviena išmintinga moteris stato savo namus, bet kvaila nugriauna juos savo rankomis.'),
  (@b20, 14, 2, 'Kas vaikšto savo tiesume, bijo VIEŠPATIES, bet kas iškrypęs savo keliuose, jį niekina.'),
  (@b20, 14, 3, 'Kvailojo burnoje – išdidumo lazda, bet išmintingųjų lūpos juos apsaugos.'),
  (@b20, 14, 4, 'Kur nėra jaučių, ėdžios švarios, bet daug prieaugio yra per jaučio jėgą.'),
  (@b20, 14, 5, 'Ištikimas liudytojas nemeluos, bet melagingas liudytojas ištars melą.'),
  (@b20, 14, 6, 'Išjuokėjas ieško išminties ir jos neranda, bet suprantančiajam pažinimas yra lengvas.'),
  (@b20, 14, 7, 'Eik šalin nuo kvailo žmogaus, pastebėjęs, kad jame nėra pažinimo lūpų.'),
  (@b20, 14, 8, 'Protingojo išmintis – suprasti savo kelią, bet kvailųjų kvailystė – apgaulė.'),
  (@b20, 14, 9, 'Kvailiai tyčiojasi iš nuodėmės, bet tarp teisiųjų yra palankumas.'),
  (@b20, 14, 10, 'Širdis pažįsta savo pačios kartumą, ir svetimasis neįsimaišo į jos džiaugsmą.'),
  (@b20, 14, 11, 'Nedorėlių namai bus nugriauti, bet tiesiųjų padangtė klestės.'),
  (@b20, 14, 12, 'Yra kelias, kuris žmogui atrodo teisingas, bet jo galas – mirties keliai.'),
  (@b20, 14, 13, 'Net juokiantis širdis sielvartauja; ir to džiaugsmo galas – liūdesys.'),
  (@b20, 14, 14, 'Pasisotins savo paties keliais atsimetėlis širdimi, o geras žmogus pasitenkins nuo savęs.'),
  (@b20, 14, 15, 'Paikas tiki kiekvienu žodžiu, bet protingas žmogus gerai apžiūri savo ėjimą.'),
  (@b20, 14, 16, 'Išmintingasis bijo ir pasitraukia nuo pikto, bet kvailys niršta ir yra pasitikintis.'),
  (@b20, 14, 17, 'Kas greitai supyksta, kvailai elgiasi, o nedorybę planuojantis žmogus yra nekenčiamas.'),
  (@b20, 14, 18, 'Paikieji paveldi kvailystę, bet protingieji apvainikuoti pažinimu.'),
  (@b20, 14, 19, 'Piktieji nusilenkia prieš geruosius, ir nedorėliai – prie teisiojo vartų.'),
  (@b20, 14, 20, 'Vargšo nekenčia net jo artimas, bet turtuolis turi daug draugų.'),
  (@b20, 14, 21, 'Kas niekina savo artimą, nusideda; bet, kas pasigaili vargšų, tas laimingas.'),
  (@b20, 14, 22, 'Argi neklysta tie, kurie sumano pikta? Bet gailestingumas ir tiesa bus tiems, kurie sumano gera.'),
  (@b20, 14, 23, 'Kiekvienas triūsas duoda pelną, bet lūpų šneka veda tik į skurdą.'),
  (@b20, 14, 24, 'Išmintingųjų vainikas – jų turtai, bet kvailųjų kvailumas – kvailybė.'),
  (@b20, 14, 25, 'Teisingas liudytojas išvaduoja sielas, bet apgaulingas liudytojas kalba melus.'),
  (@b20, 14, 26, 'VIEŠPATIES baimėje yra tvirtas užtikrintumas; ir jo vaikai turės prieglobsčio vietą.'),
  (@b20, 14, 27, 'VIEŠPATIES baimė yra gyvenimo šaltinis, atitraukiantis nuo mirties žabangų.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b20, 14, 28, 'Tautos daugybėje yra karaliaus garbė, bet žmonių stygiuje – kunigaikščio žlugimas.'),
  (@b20, 14, 29, 'Kas lėtas rūstauti, tas daug suprantantis, bet skubotas dvasia – išaukština kvailybę.'),
  (@b20, 14, 30, 'Sveika širdis yra kūno gyvybė, bet pavydas – kaulų puvinys.'),
  (@b20, 14, 31, 'Kas engia vargšą, niekina jo Kūrėją; bet, kas jį gerbia, tas pasigaili vargšo.'),
  (@b20, 14, 32, 'Nedorėlis yra išvarytas savo nedorybe, bet teisusis turi viltį savo mirtyje.'),
  (@b20, 14, 33, 'Supratimą turinčiojo širdyje ilsisi išmintis; bet tai, kas yra kvailių tarpe, darosi žinoma.'),
  (@b20, 14, 34, 'Teisumas išaukština tautą, bet nuodėmė yra negarbė bet kokiai tautai.'),
  (@b20, 14, 35, 'Karaliaus palankumas išmintingam tarnui, bet jo rūstybė užtraukiančiam gėdą.'),
  (@b20, 15, 1, 'Švelnus atsakymas nukreipia rūstybę, bet skausmingi žodžiai sukelia pyktį.'),
  (@b20, 15, 2, 'Išmintingųjų liežuvis teisingai vartoja pažinimą, bet kvailųjų burna liejasi kvailystėmis.'),
  (@b20, 15, 3, 'VIEŠPATIES akys visose vietose, stebinčios piktuosius ir geruosius.'),
  (@b20, 15, 4, 'Sveikas liežuvis – gyvybės medis, bet iškrypimas jame – spraga dvasioje.'),
  (@b20, 15, 5, 'Kvailys paniekina savo tėvo pamokymą, bet kas paiso pabarimo, yra protingas.'),
  (@b20, 15, 6, 'Teisiojo namuose daug turto, bet nedorėlio pajamose – vargas.'),
  (@b20, 15, 7, 'Išmintingųjų lūpos išplatina pažinimą, bet kvailųjų širdis taip nedaro.'),
  (@b20, 15, 8, 'Nedorėlio auka – pasibjaurėjimas VIEŠPAČIUI, bet tiesiojo malda jo pasigėrėjimas.'),
  (@b20, 15, 9, 'Nedorėlio kelias – pasibjaurėjimas VIEŠPAČIUI, bet jis myli tą, kuris eina paskui teisumą.'),
  (@b20, 15, 10, 'Pabaudimas yra sunkus tam, kuris atsižada kelio; ir kas nekenčia pabarimo, tas mirs.'),
  (@b20, 15, 11, 'Pragaras ir pražūtis VIEŠPATIES akivaizdoje; tai kaip juo labiau žmonių vaikų širdys?'),
  (@b20, 15, 12, 'Išjuokėjas nemėgsta jį barančio, ir pas išmintinguosius jis neis.'),
  (@b20, 15, 13, 'Džiugi širdis padaro linksmą veidą, bet širdies sielvartas slegia dvasią.'),
  (@b20, 15, 14, 'Supratimą turinčiojo širdis ieško pažinimo, bet kvailių burna maitinasi kvailybe.'),
  (@b20, 15, 15, 'Visos kenčiančiojo dienos piktos, bet kas yra linksmos širdies, pas tą nuolat pokylis.'),
  (@b20, 15, 16, 'Geriau mažai su VIEŠPATIES baime, negu didelis lobis ir su juo neramumai.'),
  (@b20, 15, 17, 'Geriau žolių pietūs, kur yra meilė, negu nupenėtas jautis ir su juo neapykanta.'),
  (@b20, 15, 18, 'Užsirūstinęs žmogus sukelia vaidus, o lėtas pykti nuramina vaidus.'),
  (@b20, 15, 19, 'Tinginio kelias yra dyglių tvora, bet teisiųjų kelias išlygintas.'),
  (@b20, 15, 20, 'Išmintingas sūnus džiugina tėvą, bet kvailas žmogus niekina savo motiną.'),
  (@b20, 15, 21, 'Kvailybė yra džiaugsmas stokojančiajam išminties, bet suprantantis žmogus vaikšto tiesiai.'),
  (@b20, 15, 22, 'Be patarimo ketinimai žlunga, bet kur daug patarėjų, jie įtvirtinami.'),
  (@b20, 15, 23, 'Žmogus džiaugiasi dėl savo burnos atsakymo; ir koks geras yra žodis, pasakytas tinkamu laiku!'),
  (@b20, 15, 24, 'Gyvenimo kelias išmintingajam aukštai, kad atsitrauktų nuo pragaro žemai.'),
  (@b20, 15, 25, 'VIEŠPATS sunaikins išdidžiųjų namus, bet jis įtvirtins našlės ribas.'),
  (@b20, 15, 26, 'Nedorėlio mintys – pasibjaurėjimas VIEŠPAČIUI, bet tyrųjų žodžiai – malonūs žodžiai.'),
  (@b20, 15, 27, 'Kas godus pelno, vargina savo namus, bet kas nekenčia dovanų, gyvens.'),
  (@b20, 15, 28, 'Teisiojo širdis mąsto, kaip atsakyti, bet nedorėlio burna liejasi piktybėmis.'),
  (@b20, 15, 29, 'VIEŠPATS toli nuo nedorėlių, bet teisiųjų maldą jis išklauso.'),
  (@b20, 15, 30, 'Akių šviesa pradžiugina širdį; o gera žinia nupeni kaulus.'),
  (@b20, 15, 31, 'Ausis, klausanti gyvenimo pabarimo, pasilieka tarp išmintingųjų.'),
  (@b20, 15, 32, 'Kas atsisako pamokymo, paniekina savo paties sielą, bet kas klauso pabarimo, įgyja supratimo.'),
  (@b20, 15, 33, 'VIEŠPATIES baimė yra išminties pamokymas; ir pirma garbės yra nuolankumas.'),
  (@b20, 16, 1, 'Širdies paruošimas – žmoguje, o liežuvio atsakymas – iš VIEŠPATIES.'),
  (@b20, 16, 2, 'Visi žmogaus keliai yra švarūs jo paties akyse; bet VIEŠPATS pasveria dvasias.'),
  (@b20, 16, 3, 'Pavesk savo darbus VIEŠPAČIUI, ir tavo mintys bus įtvirtintos.'),
  (@b20, 16, 4, 'VIEŠPATS viską padarė sau; taip, net ir nedorėlį pikto dienai.'),
  (@b20, 16, 5, 'Kiekvienas išdidus širdyje yra pasibjaurėjimas VIEŠPAČIUI; nors ir susijungtų rankos, jis neliks nenubaustas.'),
  (@b20, 16, 6, 'Gailestingumu ir tiesa apvaloma neteisybė; ir VIEŠPATIES baime žmonės pasitraukia nuo pikto.'),
  (@b20, 16, 7, 'Kai žmogaus keliai patinka VIEŠPAČIUI, jis padaro, kad net jo priešai būtų taikoje su juo.'),
  (@b20, 16, 8, 'Geriau mažai su teisumu, negu didelės pajamos be teisės.'),
  (@b20, 16, 9, 'Žmogaus širdis sugalvoja savo kelią, bet VIEŠPATS nukreipia jo žingsnius.'),
  (@b20, 16, 10, 'Dieviškas nuosprendis yra karaliaus lūpose; jo burna nenusižengia teisme.'),
  (@b20, 16, 11, 'Teisingi svarsčiai ir svarstyklės yra VIEŠPATIES; visi maišelio svarsčiai – jo darbas.'),
  (@b20, 16, 12, 'Karaliams yra pasibjaurėjimas daryti nedorybę; nes sostas yra įtvirtintas teisumu.'),
  (@b20, 16, 13, 'Teisios lūpos – karalių pasigėrėjimas, ir jie myli teisingai kalbančius.'),
  (@b20, 16, 14, 'Karaliaus rūstybė kaip mirties pasiuntiniai; bet išmintingas žmogus ją nuramins.'),
  (@b20, 16, 15, 'Karaliaus veido šviesoje gyvenimas, ir jo palankumas – kaip vėlyvojo lietaus debesis.'),
  (@b20, 16, 16, 'Įgyti išmintį yra daug geriau už auksą ir verčiau pasirinkti supratimo negu sidabro įsigijimą!'),
  (@b20, 16, 17, 'Tiesiųjų vieškelis – pasitraukti nuo pikto; kas saugo savo kelią, išsaugo savo sielą.'),
  (@b20, 16, 18, 'Išdidumas eina pirma sunaikinimo, ir išpuikusi dvasia – pirmiau griuvimo.'),
  (@b20, 16, 19, 'Geriau būti nusižeminusia dvasia su nuolankiaisiais, negu dalintis grobį su išdidžiaisiais.'),
  (@b20, 16, 20, 'Kas išmintingai tvarko reikalą, ras gera; ir kas pasitiki VIEŠPAČIU, tas laimingas.'),
  (@b20, 16, 21, 'Išmintingas širdyje bus vadinamas protingu; ir lūpų saldumas gausina mokytumą.'),
  (@b20, 16, 22, 'Supratimas yra gyvybės šaltinis tam, kas jį turi; bet kvailių pamokymas – kvailybė.'),
  (@b20, 16, 23, 'Išmintingojo širdis moko jo burną ir jo lūpoms prideda mokytumo.'),
  (@b20, 16, 24, 'Malonūs žodžiai kaip medaus korys, saldūs sielai ir sveikata kaulams.'),
  (@b20, 16, 25, 'Yra kelias, kuris žmogui atrodo teisingas, bet jo galas – mirties keliai.'),
  (@b20, 16, 26, 'Kas triūsia, dėl savęs triūsia; nes to iš jo reikalauja jo burna.'),
  (@b20, 16, 27, 'Bedievis žmogus iškasa pikta; ir jo lūpose tarsi deganti ugnis.'),
  (@b20, 16, 28, 'Priešgynus žmogus sėja vaidus; o šnabždūnas išskiria svarbiausius draugus.'),
  (@b20, 16, 29, 'Smurtininkas suvilioja savo artimą ir jį veda į negerą kelią.'),
  (@b20, 16, 30, 'Jis užmerkia akis, kad planuotų priešgyningus dalykus; judindamas lūpas, jis įvykdo pikta.'),
  (@b20, 16, 31, 'Žila galva – šlovės vainikas, jei randamas teisumo kelyje.'),
  (@b20, 16, 32, 'Lėtas pykti geresnis už galiūną; ir suvaldantis savo dvasią – už tą, kuris užima miestą.'),
  (@b20, 16, 33, 'Burtas metamas į sterblę; bet visas jo išsidėstymas – nuo VIEŠPATIES.'),
  (@b20, 17, 1, 'Geriau sausas kąsnis ir su juo ramybė, negu namai, pilni aukų, su vaidais.'),
  (@b20, 17, 2, 'Išmintingas tarnas valdys gėdą darantį sūnų ir turės paveldo dalį tarp brolių.'),
  (@b20, 17, 3, 'Tiglis yra sidabrui ir krosnis auksui, bet širdis išmėgina VIEŠPATS.'),
  (@b20, 17, 4, 'Piktadarys paiso melagingų lūpų; ir melagis atveria ausį piktam liežuviui.'),
  (@b20, 17, 5, 'Kas tyčiojasi iš vargšo, prikaišioja jo Kūrėjui; ir kas džiaugiasi nelaimėmis, neliks nenubaustas.'),
  (@b20, 17, 6, 'Vaikų vaikai yra senių vainikas; o vaikų šlovė – jų tėvai.'),
  (@b20, 17, 7, 'Netinka kvailiui puiki kalba, juo labiau kunigaikščiui – meluojančios lūpos.'),
  (@b20, 17, 8, 'Dovana yra kaip brangakmenis jį turinčiojo akyse: kur tik jis pasisuka, jam sekasi.'),
  (@b20, 17, 9, 'Kas pridengia nusižengimą, siekia meilės; bet kas tą dalyką kartoja, išskiria pačius draugus.'),
  (@b20, 17, 10, 'Pabarimas įeina į išmintingąjį labiau negu šimtas kirčių į kvailį.'),
  (@b20, 17, 11, 'Piktas žmogus siekia tik maišto; todėl žiaurus pasiuntinys bus pasiųstas prieš jį.'),
  (@b20, 17, 12, 'Verčiau sutikti mešką, kuriai atimti jos jaunikliai, negu kvailį jo kvailystėje.'),
  (@b20, 17, 13, 'Kas atlygina piktu už gera, pikta neatsitrauks nuo jo namų.'),
  (@b20, 17, 14, 'Kivirčo pradžia, tai tarsi kas paleistų vandenį; todėl palik ginčą prieš įsiveliant į jį.'),
  (@b20, 17, 15, 'Išteisinantis nedorėlį ir pasmerkiantis teisųjį, tie abu yra pasibjaurėjimas VIEŠPAČIUI.'),
  (@b20, 17, 16, 'Kam gi kvailio rankoje užmokestis išminties įsigijimui, kai jos link netraukia jo širdis?'),
  (@b20, 17, 17, 'Draugas visais laikais myli, o brolis gimsta nelaimei.'),
  (@b20, 17, 18, 'Supratimo neturintis žmogus sukerta rankas ir laiduoja savo draugo akivaizdoje.'),
  (@b20, 17, 19, 'Nusižengimą myli mėgstantis ginčus; ir kas išaukština savo vartus, ieško pražūties.'),
  (@b20, 17, 20, 'Kas turi priešgyniaujančią širdį, neranda gero; ir kieno iškreiptas liežuvis, tas įpuola į nelaimę.'),
  (@b20, 17, 21, 'Kas pagimdo kvailį, tai padaro savo sielvartui; ir nesidžiaugia kvailio tėvas.'),
  (@b20, 17, 22, 'Linksma širdis daro gera kaip vaistai; bet prislėgta dvasia džiovina kaulus.'),
  (@b20, 17, 23, 'Nedorėlis ima dovaną iš užančio, kad iškreiptų teismo kelius.'),
  (@b20, 17, 24, 'Išmintis yra priešakyje to, kuris turi supratimą; bet kvailio akys yra žemės pakraščiuose.'),
  (@b20, 17, 25, 'Kvailas sūnus – sielvartas tėvui ir kartybė tai, kuri jį pagimdė.'),
  (@b20, 17, 26, 'Taipogi negerai yra bausti teisųjį ir mušti kunigaikščius už teisingumą.'),
  (@b20, 17, 27, 'Turintis pažinimą tausoja savo žodžius; ir suprantantis žmogus yra puikios dvasios.'),
  (@b20, 17, 28, 'Net kvailys, kai jis tyli, laikomas išmintingu; ir kas sučiaupia lūpas, laikomas suprantančiu žmogumi.'),
  (@b20, 18, 1, 'Per geismą atsiskyręs žmogus siekia ir įsikiša į visokią išmintį.'),
  (@b20, 18, 2, 'Kvailiui nepatinka supratimas, o tik kad jo širdis atskleistų save.'),
  (@b20, 18, 3, 'Kai ateina nedorėlis, ateina ir panieka, ir su negarbe – priekaištas.'),
  (@b20, 18, 4, 'Žmogaus burnos žodžiai – kaip gilūs vandenys, ir išminties šaltinis – kaip tekantis upelis.'),
  (@b20, 18, 5, 'Negerai būti šališku nedorėliui, kad būtų nuverstas teisusis teisme.'),
  (@b20, 18, 6, 'Kvailio lūpos eina į ginčą, ir jo burna prisišaukia mušimą.'),
  (@b20, 18, 7, 'Kvailio burna – jo pražūtis, ir jo lūpos – jo sielos žabangos.'),
  (@b20, 18, 8, 'Liežuvininko žodžiai yra kaip žaizdos, ir jie nueina į pačias giliausias pilvo dalis.'),
  (@b20, 18, 9, 'Tingusis savo darbe yra daug eikvojančiojo brolis.'),
  (@b20, 18, 10, 'VIEŠPATIES vardas – stiprus bokštas; teisusis į jį bėga ir yra saugus.'),
  (@b20, 18, 11, 'Turtuolio turtai – jo stiprus miestas ir, jo įsivaizdavimu, kaip aukšta siena.'),
  (@b20, 18, 12, 'Prieš žlugimą žmogaus širdis išdidi, ir pirma garbės yra nuolankumas.'),
  (@b20, 18, 13, 'Kas atsako neišklausęs, tam yra kvailystė ir gėda.'),
  (@b20, 18, 14, 'Žmogaus dvasia palaiko jo negalią; bet kas pakels sužeistą dvasią?'),
  (@b20, 18, 15, 'Protingojo širdis įgyja pažinimo; ir išmintingojo ausis ieško pažinimo.'),
  (@b20, 18, 16, 'Žmogaus dovana suteikia jam erdvės ir nuveda jį didžiūnų akivaizdon.'),
  (@b20, 18, 17, 'Pirmas savo byloje atrodo teisus; bet ateina jo artimas ir jį ištiria.'),
  (@b20, 18, 18, 'Burtas ginčus užbaigia ir perskiria tarp galingųjų.'),
  (@b20, 18, 19, 'Papiktintas brolis yra labiau neprieinamas negu tvirtas miestas; ir jų ginčai yra kaip pilies skląsčiai.'),
  (@b20, 18, 20, 'Žmogaus pilvas pasitenkins savo burnos vaisiais; ir jis pasisotins savo lūpų derliumi.'),
  (@b20, 18, 21, 'Mirtis ir gyvenimas liežuvio galioje: kas jį myli, valgys jo vaisius.'),
  (@b20, 18, 22, 'Kas randa žmoną, randa gera ir įgyja VIEŠPATIES palankumą.'),
  (@b20, 18, 23, 'Vargšas kalba maldaudamas, bet turtingas atsako šiurkščiai.'),
  (@b20, 18, 24, 'Žmogus, turintis draugų, turi pasirodyti draugiškas; ir būna draugas, prisirišęs labiau už brolį.'),
  (@b20, 19, 1, 'Geriau beturtis, vaikštantis savo nekaltume, negu iškreiptasis savo lūpomis ir kvailys.'),
  (@b20, 19, 2, 'Taip pat, kad siela be pažinimo – negerai; ir kas skuba kojomis, nusideda.'),
  (@b20, 19, 3, 'Žmogaus kvailystė iškreipia jo kelią; ir jo širdis niršta prieš VIEŠPATĮ.'),
  (@b20, 19, 4, 'Turtas parūpina daug draugų; bet vargšas atskiriamas nuo jo artimo.'),
  (@b20, 19, 5, 'Melagingas liudytojas neliks nenubaustas, ir kas kalba melus, neišsigelbės.'),
  (@b20, 19, 6, 'Daugelis maldauja iš kunigaikščio palankumo; ir visi yra draugai tam, kuris duoda dovanų.'),
  (@b20, 19, 7, 'Visi vargšo broliai jo nekenčia, tai kiek labiau jo draugai tolinasi nuo jo? Jis vejasi juos žodžiais, tačiau jų trūkstama.'),
  (@b20, 19, 8, 'Kas įgyja išminties, myli savo sielą; kas saugo supratimą, tas ras gera.'),
  (@b20, 19, 9, 'Melagingas liudytojas neliks nenubaustas, ir kas kalba melus, pražus.'),
  (@b20, 19, 10, 'Netinka kvailiui pasigėrėjimas, juo labiau tarnui – valdyti kunigaikščius.'),
  (@b20, 19, 11, 'Žmogaus apdairumas atideda jo pyktį, ir jam yra šlovė apeiti nusižengimą.'),
  (@b20, 19, 12, 'Karaliaus rūstybė – kaip liūto riaumojimas, bet jo palankumas – kaip rasa ant žolės.'),
  (@b20, 19, 13, 'Kvailas sūnus – jo tėvo nelaimė, o žmonos ginčai – nesiliaujantis lašėjimas.'),
  (@b20, 19, 14, 'Namai ir turtai – paveldas iš tėvų, o protinga žmona – nuo VIEŠPATIES.'),
  (@b20, 19, 15, 'Tinginystė nugramzdina į gilų miegą, ir dykinėjanti siela kęs alkį.'),
  (@b20, 19, 16, 'Kas laikosi įsakymo, saugo savo sielą; bet kas niekina savo kelius, mirs.'),
  (@b20, 19, 17, 'Kas pasigaili beturčio, skolina VIEŠPAČIUI; ir tai, ką jis davė, jis jam atlygins.'),
  (@b20, 19, 18, 'Bausk savo sūnų, kol yra vilties, ir tavo siela tenesigaili dėl jo šauksmo.'),
  (@b20, 19, 19, 'Didelės rūstybės žmogus kentės bausmę; nes jei jį išvaduosi, turėsi vėl tai daryti.'),
  (@b20, 19, 20, 'Klausyk patarimo ir priimk pamokymą, kad savo pabaigoje būtum išmintingas.'),
  (@b20, 19, 21, 'Daug sumanymų žmogaus širdyje; tačiau tik VIEŠPATIES ketinimas išstovės.'),
  (@b20, 19, 22, 'Žmogaus troškimas yra jo gerumas; o vargšas yra geresnis už melagį.'),
  (@b20, 19, 23, 'VIEŠPATIES baimė veda į gyvenimą; ir kas jos turi, liks patenkintas; pikta jo neaplankys.'),
  (@b20, 19, 24, 'Tinginys slepia savo ranką užantyje ir net prie burnos jos nesugrąžina.'),
  (@b20, 19, 25, 'Mušk išjuokėją, ir paikasis saugosis; bark turintįjį supratimą, ir jis supras pažinimą.'),
  (@b20, 19, 26, 'Kas daro nuostolį savo tėvui ir išveja savo motiną, yra darantis gėdą ir atnešantis priekaištą sūnus.'),
  (@b20, 19, 27, 'Mano sūnau, liaukis klaũsęs pamokymo, kuris skatina nuklysti nuo pažinimo žodžių.'),
  (@b20, 19, 28, 'Bedievis liudytojas tyčiojasi iš teismo; ir nedorėlių burna ryja neteisybę.'),
  (@b20, 19, 29, 'Teismai paruošti išjuokėjams ir kirčiai kvailių nugaroms.'),
  (@b20, 20, 1, 'Vynas – išjuokėjas, stiprus gėrimas – pašėlęs; ir kas jais apsigauna, nėra išmintingas.'),
  (@b20, 20, 2, 'Karaliaus baimė – kaip liūto riaumojimas; kas kursto jo pyktį, nusideda prieš savo sielą.'),
  (@b20, 20, 3, 'Garbė žmogui paliauti ginčą; bet kiekvienas kvailys įsivelia.'),
  (@b20, 20, 4, 'Tinginys nears dėl šalčio; todėl pjūties metu elgetaus ir nieko neturės.'),
  (@b20, 20, 5, 'Patarimas žmogaus širdyje yra kaip gilus vanduo, bet suprantantis žmogus jį sems.'),
  (@b20, 20, 6, 'Dauguma žmonių skelbia savo pačių gerumą, bet kas suras ištikimą žmogų?'),
  (@b20, 20, 7, 'Teisusis vaikšto savo nekaltume; jo vaikai palaiminti po jo.'),
  (@b20, 20, 8, 'Karalius, sėdintis teismo soste, savo akimis išsklaido visa, kas pikta.'),
  (@b20, 20, 9, 'Kas gali sakyti: „Apvaliau savo širdį, esu švarus nuo savo nuodėmės?“'),
  (@b20, 20, 10, 'Skirtingi svarsčiai ir skirtingi saikai – abu vienodai bjaurūs VIEŠPAČIUI.'),
  (@b20, 20, 11, 'Netgi vaiką galima pažinti iš jo veiksmų, ar jo darbas tyras, ar jis teisingas.'),
  (@b20, 20, 12, 'Girdinčią ausį ir reginčią akį – VIEŠPATS padarė abi.'),
  (@b20, 20, 13, 'Nemylėk miego, kad nenuskurstum; atverk akis ir pasisotinsi duona.'),
  (@b20, 20, 14, '„Niekam tikęs, niekam tikęs!“ – sako pirkėjas, bet nuėjęs giriasi.'),
  (@b20, 20, 15, 'Yra auksas ir daugybė rubinų, bet pažinimo lūpos – vertinga brangenybė.'),
  (@b20, 20, 16, 'Paimk drabužį to, kuris laidavo už svetimą, ir paimk iš jo užstatą už svetimą moterį.'),
  (@b20, 20, 17, 'Žmogui gardi apgavystės duona, bet paskui jo burna prisipildys žvyro.'),
  (@b20, 20, 18, 'Kiekvienas ketinimas įtvirtinamas pasitarimu; ir kariauk pagal gerą patarimą.'),
  (@b20, 20, 19, 'Kas vaikšto kaip liežuvininkas, atskleidžia paslaptis; todėl nesusidėk su tuo, kuris pataikauja savo lūpomis.'),
  (@b20, 20, 20, 'Kas keikia savo tėvą ar savo motiną, to žibintas užges visiškoje tamsoje.'),
  (@b20, 20, 21, 'Paveldas pradžioje gali būti gautas paskubomis, bet jo pabaiga nebus palaiminta.'),
  (@b20, 20, 22, 'Nesakyk: „Atlyginsiu už pikta“; bet lauk VIEŠPATIES, ir jis tave išgelbės.'),
  (@b20, 20, 23, 'Skirtingi svarsčiai yra pasibjaurėjimas VIEŠPAČIUI; ir melagingos svarstyklės yra negerai.'),
  (@b20, 20, 24, 'Žmogaus ėjimai yra iš VIEŠPATIES; tad kaip žmogus gali suprasti savo kelią?'),
  (@b20, 20, 25, 'Pinklės tam žmogui, kuris suryja tai, kas šventa, o po įžadų teiraujasi.'),
  (@b20, 20, 26, 'Išmintingas karalius išsklaido nedorėlius ir užleidžia ant jų ratą.'),
  (@b20, 20, 27, 'Žmogaus dvasia yra VIEŠPATIES žvakė, tirianti visas vidines pilvo dalis.'),
  (@b20, 20, 28, 'Gailestingumas ir tiesa apsaugo karalių; ir jo sostas palaikomas gailestingumu.'),
  (@b20, 20, 29, 'Jaunuolių šlovė yra jų jėga; o senių grožis – žila galva.'),
  (@b20, 20, 30, 'Žaizdos mėlynė nuvalo šalin pikta; taip ir kirčiai vidines pilvo dalis.'),
  (@b20, 21, 1, 'Karaliaus širdis VIEŠPATIES rankoje kaip vandens upės: jis ją nukreipia, kur nori.'),
  (@b20, 21, 2, 'Kiekvienas žmogaus kelias yra teisingas jo paties akyse; bet VIEŠPATS svarsto širdis.'),
  (@b20, 21, 3, 'Teisingumo ir teismo vykdymas VIEŠPAČIUI yra priimtinesnis už auką.'),
  (@b20, 21, 4, 'Išdidus žvilgsnis, pasipūtusi širdis ir nedorėlių arimas yra nuodėmė.'),
  (@b20, 21, 5, 'Stropiojo mintys veda tik į apstybę, bet skubraus – tik į stoką.'),
  (@b20, 21, 6, 'Lobių įgijimas melagingu liežuviu – tai tuštybė, blaškoma ten ir atgal tų, kurie ieško mirties.'),
  (@b20, 21, 7, 'Nedorėlių plėšikavimas juos sunaikins, nes jie atsisako laikytis teismo.'),
  (@b20, 21, 8, 'Žmogaus kelias priešgynus ir svetimas; bet tyrojo darbas teisingas.'),
  (@b20, 21, 9, 'Geriau gyventi kampe ant stogo, negu su triukšminga moterimi erdviuose namuose.'),
  (@b20, 21, 10, 'Nedorėlio siela geidžia pikto, jo artimas neranda palankumo jo akyse.'),
  (@b20, 21, 11, 'Kai nubaudžiamas išjuokėjas, paikas darosi išmintingas; ir kai išmintingasis pamokomas, jis gauna pažinimo.'),
  (@b20, 21, 12, 'Teisusis išmintingai apsvarsto nedorėlio namus, bet Dievas parbloškia nedorėlius už jų piktybę.'),
  (@b20, 21, 13, 'Kas užkemša savo ausis vargšo šauksmui, tas irgi šauks, bet nebus išgirstas.'),
  (@b20, 21, 14, 'Slapta dovana nuramina pyktį, o apdovanojimas į užantį – stiprią rūstybę.'),
  (@b20, 21, 15, 'Teisiajam yra džiaugsmas laikytis teismo; bet darantiems neteisybę bus sunaikinimas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b20, 21, 16, 'Žmogus, nuklydęs nuo supratimo kelio, pasiliks mirusiųjų susirinkime.'),
  (@b20, 21, 17, 'Kas mėgsta malonumą, bus vargšas; kas mėgsta vyną ir aliejų, nebus turtingas.'),
  (@b20, 21, 18, 'Nedorėlis bus išpirka už teisųjį, o nusižengėlis už tiesųjį.'),
  (@b20, 21, 19, 'Geriau gyventi dykumoje negu su mėgstančia barnius ir pykstančia moterimi.'),
  (@b20, 21, 20, 'Trokštamas lobis ir aliejus yra išmintingojo buveinėje; bet kvailas žmogus jį išeikvoja.'),
  (@b20, 21, 21, 'Kas seka teisumu ir gailestingumu, randa gyvenimą, teisumą ir garbę.'),
  (@b20, 21, 22, 'Išmintingasis užlipa į galingųjų miestą ir nugriauna jo užtikrintumo stiprybę.'),
  (@b20, 21, 23, 'Kas saugo savo burną ir savo liežuvį, saugo savo sielą nuo bėdų.'),
  (@b20, 21, 24, 'Kas elgiasi išdidžia rūstybe, to vardas – išdidus ir išpuikęs išjuokėjas.'),
  (@b20, 21, 25, 'Tinginio troškimas jį nužudo, nes jo rankos atsisako dirbti.'),
  (@b20, 21, 26, 'Jis godžiai geidžia visą dieną, bet teisusis duoda negailėdamas.'),
  (@b20, 21, 27, 'Nedorėlio auka – pasibjaurėjimas, tai kiek labiau kai jis ją atneša su nedorais ketinimais?'),
  (@b20, 21, 28, 'Melagingas liudytojas pražus, bet žmogus, kuris girdi, nuolat kalba.'),
  (@b20, 21, 29, 'Nedoras žmogus sukietina savo veidą, bet tiesusis nukreipia savo kelią.'),
  (@b20, 21, 30, 'Prieš VIEŠPATĮ nėra nei išminties, nei supratimo, nei patarimo.'),
  (@b20, 21, 31, 'Žirgas paruošiamas mūšio dienai, bet saugumas yra iš VIEŠPATIES.'),
  (@b20, 22, 1, 'Verčiau pasirinkti gerą vardą nei didelius turtus ir verčiau mylintį palankumą nei sidabrą ir auksą.'),
  (@b20, 22, 2, 'Turtingas ir vargšas kartu susitinka: jų visų Kūrėjas yra VIEŠPATS.'),
  (@b20, 22, 3, 'Protingasis numato pikta ir pasislepia; bet paikasis eina toliau ir yra nubaudžiamas.'),
  (@b20, 22, 4, 'Per nuolankumą bei VIEŠPATIES baimę yra turtai, garbė ir gyvenimas.'),
  (@b20, 22, 5, 'Erškėčiai ir pinklės yra priešgyniautojo kelyje; kas saugo savo sielą, bus toli nuo jų.'),
  (@b20, 22, 6, 'Išmokyk vaiką kelio, kuriuo jis turi eiti, ir pasenęs jis nesitrauks nuo jo.'),
  (@b20, 22, 7, 'Turtingasis viešpatauja vargšui, ir skolininkas yra skolintojo tarnas.'),
  (@b20, 22, 8, 'Kas sėja neteisybę, pjaus tuštybę; ir jo pykčio lazda prapuls.'),
  (@b20, 22, 9, 'Kas turi dosnią akį, bus palaimintas; nes jis duoda savo duonos vargšui.'),
  (@b20, 22, 10, 'Išvaryk apjuokėją, ir išeis vaidai, taip, liausis ginčai ir priekaištai.'),
  (@b20, 22, 11, 'Kas myli širdies tyrumą, už jo lūpų malonę karalius bus jo draugas.'),
  (@b20, 22, 12, 'VIEŠPATIES akys saugo pažinimą, ir nusižengėlio žodžius jis parbloškia.'),
  (@b20, 22, 13, 'Tinginys sako: „Liūtas lauke; mane užmuš gatvėse“.'),
  (@b20, 22, 14, 'Svetimų moterų burna – gili duobė; tas, kuriuo VIEŠPATS bjaurisi, įkris į ją.'),
  (@b20, 22, 15, 'Kvailystė prisirišusi prie vaiko širdies; bet pataisymo rykštė ją atitolins nuo jo.'),
  (@b20, 22, 16, 'Kas engia vargšą, idant praturtėtų ir kas duoda turtingajam, tikrai nuskurs.'),
  (@b20, 22, 17, 'Palenk savo ausį ir klausyk išmintingojo žodžių, ir pakreipk savo širdį į mano pažinimą.'),
  (@b20, 22, 18, 'Nes tai yra malonu, jei juos saugoji savo viduje; jie be to tiks tavo lūpose.'),
  (@b20, 22, 19, 'Kad tavo pasitikėjimas būtų VIEŠPAČIU, aš tau šią dieną daviau pažinti, būtent tau.'),
  (@b20, 22, 20, 'Ar aš neparašiau tau puikių dalykų patarimais ir pažinimu,'),
  (@b20, 22, 21, 'kad tau duočiau pažinti tiesos žodžių tikrumą; kad galėtum atsakyti tiesos žodžiais tiems, kurie pas tave siunčia?'),
  (@b20, 22, 22, 'Neapiplėšk vargšo dėl to, kad jis vargšas, ir neenk vargstančiojo vartuose;'),
  (@b20, 22, 23, 'nes VIEŠPATS gins jų bylą ir apiplėš sielas tų, kurie juos apiplėšė.'),
  (@b20, 22, 24, 'Nedraugauk su pykstančiu žmogumi ir neik su įtūžusiu žmogumi,'),
  (@b20, 22, 25, 'idant neišmoktum jo kelių ir negautum žabangų savo sielai.'),
  (@b20, 22, 26, 'Nebūk iš tų, kurie sukerta rankomis, ar iš tų, kurie laiduoja už skolas.'),
  (@b20, 22, 27, 'Jei neturi kuo sumokėti, kodėl jis turėtų atimti tavo lovą iš po tavęs?'),
  (@b20, 22, 28, 'Neperkelk senojo riboženklio, kurį pastatė tavo tėvai.'),
  (@b20, 22, 29, 'Ar matai žmogų stropų savo reikaluose? Jis stovės karalių akivaizdoje; jis nestovės prastų žmonių akivaizdoje.'),
  (@b20, 23, 1, 'Kai sėdiesi valgyti su valdovu, kruopščiai apžiūrėk, kas prieš tave padėta;'),
  (@b20, 23, 2, 'ir pridėk peilį prie savo gerklės, jei esi valdomas apetito.'),
  (@b20, 23, 3, 'Negeisk jo skanėstų, nes tai apgaulingas maistas.'),
  (@b20, 23, 4, 'Netriūsk, norėdamas praturtėti; palik savo paties išmintį.'),
  (@b20, 23, 5, 'Ar nukreipsi savo akis į tai, ko nėra? Nes turtai tikrai pasidaro sparnus; jie išskrenda kaip erelis į dangų.'),
  (@b20, 23, 6, 'Nevalgyk duonos to, kurio akis pikta, ir negeisk jo skanumynų;'),
  (@b20, 23, 7, 'nes kaip jis galvoja savo širdyje, toks jis ir yra; „Valgyk ir gerk“, – jis tau sako, bet jo širdis nėra su tavimi.'),
  (@b20, 23, 8, 'Savo suvalgytą kąsnį tu išvemsi ir prarasi savo malonius žodžius.'),
  (@b20, 23, 9, 'Nekalbėk į kvailio ausis, nes jis paniekins tavo žodžių išmintį.'),
  (@b20, 23, 10, 'Neperkelk senojo riboženklio; ir neįženk į našlaičių laukus;'),
  (@b20, 23, 11, 'nes jų atpirkėjas yra galingas; jis gins jų bylą prieš tave.'),
  (@b20, 23, 12, 'Pakreipk savo širdį į pamokymą ir savo ausis į pažinimo žodžius.'),
  (@b20, 23, 13, 'Nesulaikyk nuo vaiko bausmės; nes jei jį muši rykšte, jis nemirs.'),
  (@b20, 23, 14, 'Tu muši jį rykšte, ir išgelbėsi jo sielą nuo pragaro.'),
  (@b20, 23, 15, 'Mano sūnau, jei tavo širdis bus išmintinga, džiaugsis mano širdis, būtent mano.'),
  (@b20, 23, 16, 'Taip, mano inkstai džiaugsis, kai tavo lūpos kalbės, kas teisinga.'),
  (@b20, 23, 17, 'Tenepavydi tavo širdis nusidėjėliams; bet būk VIEŠPATIES baimėje visą dieną.'),
  (@b20, 23, 18, 'Nes galas tikrai yra; ir tavo lūkestis nebus iškirstas.'),
  (@b20, 23, 19, 'Klausyk, mano sūnau, būk išmintingas ir vesk savo širdį tuo keliu.'),
  (@b20, 23, 20, 'Nebūk tarp vyno gėrėjų, tarp mėsos rajūnų;'),
  (@b20, 23, 21, 'nes girtuoklis ir rajūnas nuskurs; ir mieguistumas aprengs žmogų skarmalais.'),
  (@b20, 23, 22, 'Klausyk savo tėvo, kuris tave pagimdė, ir nepaniekink savo motinos, kai ji pasenusi.'),
  (@b20, 23, 23, 'Pirk tiesą ir jos neparduok; taip pat išmintį, pamokymą ir supratimą.'),
  (@b20, 23, 24, 'Teisiojo tėvas didžiai džiūgaus; ir tas, kuris pagimdo išmintingą vaiką, juo džiaugsis.'),
  (@b20, 23, 25, 'Tavo tėvas ir tavo motina linksminsis, ir džiūgaus ta, kuri tave pagimdė.'),
  (@b20, 23, 26, 'Mano sūnau, duok man savo širdį, ir tegul tavo akys stebi mano kelius.'),
  (@b20, 23, 27, 'Nes paleistuvė yra gilus griovys; ir svetima moteris – siaura duobė.'),
  (@b20, 23, 28, 'Ji ir tyko, tarsi grobio, ir daugina nusižengėlius tarp žmonių.'),
  (@b20, 23, 29, 'Kas vargsta? Kas sielojasi? Kas vaidijasi? Kas plepa? Kas turi žaizdas be priežasties? Kieno paraudusios akys?'),
  (@b20, 23, 30, 'Tie, kurie ilgai užtrunka prie vyno, kurie eina ieškoti maišyto vyno.'),
  (@b20, 23, 31, 'Nežiūrėk į vyną, kai jis raudonas, kai jis suteikia savo spalvą taurėje, kai jis tinkamai nuslysta.'),
  (@b20, 23, 32, 'Galiausiai jis įkanda kaip gyvatė ir įgelia kaip angis.'),
  (@b20, 23, 33, 'Tavo akys žiūrės į svetimas moteris, ir tavo širdis ištars iškrypusius dalykus.'),
  (@b20, 23, 34, 'Taip, tu būsi kaip gulintis jūros viduryje ar kaip gulintis laivo stiebo viršūnėje.'),
  (@b20, 23, 35, 'Tu sakysi: „Jie man smogė, o aš nesusirgau; jie mane mušė, o aš to nejaučiau; kada aš pabusiu? Vėl jo ieškosiu“.'),
  (@b20, 24, 1, 'Nepavydėk piktiems žmonėms ir nenorėk būti su jais.'),
  (@b20, 24, 2, 'Nes jų širdis mąsto apie sunaikinimą, ir jų lūpos kalba apie piktadarystę.'),
  (@b20, 24, 3, 'Išmintimi pastatomi namai ir supratimu jie įtvirtinami;'),
  (@b20, 24, 4, 'pažinimu kambariai pripildomi visokių brangių ir malonių turtų.'),
  (@b20, 24, 5, 'Išmintingas žmogus yra stiprus; taip, pažinimo žmogus padidina jėgas.'),
  (@b20, 24, 6, 'Nes išmintingu patarimu tu vesi savo karą; ir patarėjų daugybėje yra saugumas.'),
  (@b20, 24, 7, 'Per aukšta kvailiui išmintis: vartuose jis neatveria burnos.'),
  (@b20, 24, 8, 'Kas planuoja daryti pikta, tas bus vadinamas piktadariu žmogumi.'),
  (@b20, 24, 9, 'Kvailystės mintis yra nuodėmė; ir išjuokėjas – pasibjaurėjimas žmonėms.'),
  (@b20, 24, 10, 'Jei nusilpsti nelaimės dieną, silpna tavo jėga.'),
  (@b20, 24, 11, 'Jei tu susilaikysi, kad neišvaduotum tų, kurie vedami į mirtį, ir tų, kurie parengti nužudymui;'),
  (@b20, 24, 12, 'jei sakysi: „Štai mes to nežinojome“; argi tas, kuris svarsto širdį, to neapgalvoja? Argi tas, kuris saugo tavo sielą, to nežino? Ir argi jis neatlygins kiekvienam žmogui pagal jo darbus?'),
  (@b20, 24, 13, 'Mano sūnau, valgyk medų, nes jis geras; ir medaus korį, kuris yra saldus tavo skoniui;'),
  (@b20, 24, 14, 'taip išminties pažinimas bus tavo sielai; kai būsi ją radęs, tada bus atpildas, ir tavo lūkestis nebus iškirstas.'),
  (@b20, 24, 15, 'Netykok, nedorėli, teisiojo buveinės; neapiplėšk jo poilsio vietos;'),
  (@b20, 24, 16, 'nes teisusis septynis kartus pargriūna ir vėl atsikelia; bet nedorėlis įpuls į nelaimę.'),
  (@b20, 24, 17, 'Nesidžiauk, kai tavo priešas pargriūna, ir tenesilinksmina tavo širdis jam suklumpant;'),
  (@b20, 24, 18, 'kad VIEŠPATS to nepamatytų, ir tai jam nesukeltų pykčio, ir jis neatitrauktų nuo jo savo rūstybės.'),
  (@b20, 24, 19, 'Nesusierzink dėl piktųjų ir nepavydėk nedorėliams;'),
  (@b20, 24, 20, 'nes piktajam nebus užmokesčio; nedorėlio žvakė užges.'),
  (@b20, 24, 21, 'Mano sūnau, bijok VIEŠPATIES ir karaliaus; ir nesusidėk su linkusiais pakeisti;'),
  (@b20, 24, 22, 'nes jų nelaimė kils netikėtai; ir kas žino pražūtį tų abiejų?'),
  (@b20, 24, 23, 'Šitie dalykai irgi priklauso išmintingiems. Būti šališkam teisme negerai.'),
  (@b20, 24, 24, 'Kas nedorėliui sako: „Tu esi teisus“, tą prakeiks tautos, juo bjaurėsis tautybės;'),
  (@b20, 24, 25, 'bet tiems, kurie jį bars, bus pasigėrėjimas, ir jiems ateis geri palaiminimai.'),
  (@b20, 24, 26, 'Kiekvienas bučiuos lūpas to, kuris teisingai atsako.'),
  (@b20, 24, 27, 'Atlik savo darbą lauke ir tinkamai paruošk jį sau ant lauko; o paskui statyk sau namus.'),
  (@b20, 24, 28, 'Nebūk liudytoju prieš savo artimą be priežasties ir neapgaudinėk savo lūpomis.'),
  (@b20, 24, 29, 'Nesakyk: „Kaip jis man padarė, taip aš jam padarysiu; atlyginsiu tam žmogui pagal jo darbą“.'),
  (@b20, 24, 30, 'Aš ėjau palei tinginio lauką ir palei neturinčio supratimą žmogaus vynuogyną;'),
  (@b20, 24, 31, 'ir štai jis visas buvo apaugęs erškėčiais, jo paviršių dengė dilgynės, ir jo akmeninė siena buvo išgriauta.'),
  (@b20, 24, 32, 'Tada aš pamačiau ir gerai apmąsčiau; žiūrėjau į tai ir pasimokiau.'),
  (@b20, 24, 33, 'Dar truputį miego, truputį pasnausti, truputį susidėti rankas pamiegoti;'),
  (@b20, 24, 34, 'šitaip ateis tavo skurdas kaip pakeleivis ir tavo stoka kaip ginkluotas vyras.'),
  (@b20, 25, 1, 'Šitos irgi yra Saliamono patarlės, kurių kopijas padarė Judos karaliaus Chezekijo vyrai.'),
  (@b20, 25, 2, 'Dievo šlovė – paslėpti dalyką; bet karalių garbė – ištirti dalyką.'),
  (@b20, 25, 3, 'Dangus dėl aukščio, žemė dėl gylio ir karalių širdis – neištiriami.'),
  (@b20, 25, 4, 'Pašalink nuodegas iš sidabro, ir sidabro valytojui išeis indas.'),
  (@b20, 25, 5, 'Pašalink nedorėlį iš karaliaus akivaizdos, ir jo sostas įsitvirtins teisume.'),
  (@b20, 25, 6, 'Neišstatyk savęs karaliaus akivaizdoje ir nestok didžiūnų vieton;'),
  (@b20, 25, 7, 'nes geriau, kad tau sakytų: „Ateik čia aukščiau“, negu kad būtum pažemintas akivaizdoje kunigaikščio, kurį matė tavo akys.'),
  (@b20, 25, 8, 'Neišeik skubomis vaidytis, nes nežinosi, ką daryti to pabaigoje, kai tavo artimas sugėdins tave.'),
  (@b20, 25, 9, 'Apsvarstyk savo bylą su savo artimu ir neatskleisk paslapties kitam;'),
  (@b20, 25, 10, 'kad tavęs nesugėdintų tas, kuris tai išgirs, ir tada tavo negarbė neatsitrauktų.'),
  (@b20, 25, 11, 'Tinkamai pasakytas žodis yra kaip auksiniai obuoliai sidabriniuose paveiksluose.'),
  (@b20, 25, 12, 'Išmintingas pabarėjas paklusniai ausiai yra kaip auksinis auskaras ir geriausio aukso papuošalas.'),
  (@b20, 25, 13, 'Kaip sniego šaltumas pjūties metu, taip ištikimas pasiuntinys savo siuntėjui; nes jis atgaivina savo valdovų sielą.'),
  (@b20, 25, 14, 'Kas giriasi melaginga dovana, yra kaip debesys ir vėjas be lietaus.'),
  (@b20, 25, 15, 'Ilgu pakantumu įtikinamas kunigaikštis, ir švelnus liežuvis sulaužo kaulus.'),
  (@b20, 25, 16, 'Ar radai medaus? Valgyk, kiek tau pakanka, kad juo prisisotinęs jo neišvemtum.'),
  (@b20, 25, 17, 'Atitrauk savo koją nuo savo artimo namų, kad jis nuo tavęs nenuvargtų ir nepradėtų tavęs nekęsti.'),
  (@b20, 25, 18, 'Žmogus, kuris melagingai liudija prieš savo artimą, yra kūlė, kalavijas ir aštri strėlė.'),
  (@b20, 25, 19, 'Pasitikėjimas neištikimu žmogumi bėdos metu yra kaip išlūžęs dantis ir išnirusi koja.'),
  (@b20, 25, 20, 'Kaip atimantis drabužį šaltą dieną, ir kaip actas ant salietros, toks yra giedantis giesmes nuliūdusiai širdžiai.'),
  (@b20, 25, 21, 'Jei tavo priešas alkanas, duok jam duonos valgyti; ir jei jis ištroškęs, duok jam gerti vandens;'),
  (@b20, 25, 22, 'nes tu krausi žarijas ant jo galvos, ir VIEŠPATS tau atlygins.'),
  (@b20, 25, 23, 'Šiaurės vėjas nuveja lietų; taip ir piktas veidas apkalbantį liežuvį.'),
  (@b20, 25, 24, 'Geriau gyventi kampe ant stogo, negu su triukšminga moterimi erdviuose namuose.'),
  (@b20, 25, 25, 'Kaip šalti vandenys ištroškusiai sielai, taip gera žinia iš tolimos šalies.'),
  (@b20, 25, 26, 'Teisusis, krintantis prieš nedorėlį, yra kaip sudrumstas šaltinis ir sugędusi versmė.'),
  (@b20, 25, 27, 'Negerai valgyti daug medaus, taip siekti sau šlovės nėra šlovė.'),
  (@b20, 25, 28, 'Kas nesuvaldo savo dvasios, yra kaip sugriautas miestas ir be sienų.'),
  (@b20, 26, 1, 'Kaip sniegas vasarą ir kaip lietus pjūties metu, taip garbė netinka kvailiui.'),
  (@b20, 26, 2, 'Kaip paukštis klajoja, kaip kregždė skrajoja, taip neateis nepagrįstas prakeikimas.'),
  (@b20, 26, 3, 'Botagas arkliui, apynasris asilui, o rykštė kvailio nugarai.'),
  (@b20, 26, 4, 'Neatsakyk kvailiui pagal jo kvailystę, kad ir tu nebūtum panašus į jį.'),
  (@b20, 26, 5, 'Atsakyk kvailiui pagal jo kvailystę, kad jis nebūtų išmintingas savo paties akyse.'),
  (@b20, 26, 6, 'Kas siunčia žinią per kvailio ranką, nusikerta kojas ir geria nuostolį.'),
  (@b20, 26, 7, 'Raišo kojos nevienodos; taip ir palyginimas kvailių burnoje.'),
  (@b20, 26, 8, 'Kaip pririšantis akmenį prie svaidyklės, toks ir tas, kuris suteikia garbę kvailiui.'),
  (@b20, 26, 9, 'Kaip dyglys sminga į girtojo ranką, taip ir palyginimas kvailių burnoje.'),
  (@b20, 26, 10, 'Didysis Dievas, kuris suformavo visus dalykus, atlygina kvailiui ir atlygina nusižengėliui.'),
  (@b20, 26, 11, 'Kaip šuo sugrįžta prie savo vėmalo, taip kvailys sugrįžta prie savo kvailybės.'),
  (@b20, 26, 12, 'Ar matai žmogų, išmintingą savo paties akyse? Kvailys teikia daugiau vilties negu anas.'),
  (@b20, 26, 13, 'Tinginys sako: „Liūtas kelyje; liūtas gatvėse“.'),
  (@b20, 26, 14, 'Kaip durys vartosi ant savo vyrių, taip tinginys savo lovoje.'),
  (@b20, 26, 15, 'Tinginys paslepia savo ranką užantyje; jam sunku ją vėl pritraukti prie burnos.'),
  (@b20, 26, 16, 'Tinginys savo akyse išmintingesnis už septynis, galinčius duoti patarimą.'),
  (@b20, 26, 17, 'Kas praeidamas įsikiša į ginčą, kuris nesusijęs su juo, yra kaip tas, kuris nutveria šunį už ausų.'),
  (@b20, 26, 18, 'Kaip beprotis, kuris mėto nuodėgulius, strėles ir mirtį,'),
  (@b20, 26, 19, 'toks yra žmogus, kuris apgauna savo artimą ir sako: „Argi aš nejuokauju?“'),
  (@b20, 26, 20, 'Kai nėra malkų, užgęsta ugnis; taip ir kai nėra liežuvininko, baigiasi ginčas.'),
  (@b20, 26, 21, 'Kaip anglys žarijoms ir malkos ugniai, taip ir vaidingas žmogus ginčui užkurti.'),
  (@b20, 26, 22, 'Liežuvininko žodžiai yra kaip žaizdos, ir jie įeina į giliausias pilvo dalis.'),
  (@b20, 26, 23, 'Ugningos lūpos ir nedora širdis yra kaip puodo šukė, aptraukta sidabro šlaku.'),
  (@b20, 26, 24, 'Kas neapkenčia, slepia savo lūpomis ir savo viduje kaupia apgaulę;'),
  (@b20, 26, 25, 'kai jis gražiai kalba, juo netikėk, nes septynios bjaurystės yra jo širdyje.'),
  (@b20, 26, 26, 'Kieno neapykanta pridengta apgavyste, to nedorybė pasimatys viso susirinkimo akivaizdoje.'),
  (@b20, 26, 27, 'Kas kasa duobę, į ją įkris; ir kas ritina akmenį, ant to jis sugrįš.'),
  (@b20, 26, 28, 'Meluojantis liežuvis nekenčia tų, kurie nuo jo nukenčia; ir pataikaujanti burna sukelia pražūtį.'),
  (@b20, 27, 1, 'Nesigirk rytojumi, nes nežinai, ką diena pagimdys.'),
  (@b20, 27, 2, 'Tegiria tave kitas, o ne tavo paties burna; svetimas, o ne tavo lūpos.'),
  (@b20, 27, 3, 'Akmuo yra sunkus ir smėlis svarus, bet kvailio rūstybė sunkesnė už abu.'),
  (@b20, 27, 4, 'Rūstybė yra žiauri ir pyktis siaubingas; bet kas gali atsilaikyti prieš pavydą?'),
  (@b20, 27, 5, 'Viešas papeikimas geriau negu slapta meilė.'),
  (@b20, 27, 6, 'Ištikimos yra draugo žaizdos, bet priešo bučiniai klastingi.'),
  (@b20, 27, 7, 'Soti siela bjaurisi medaus koriu, bet alkanai sielai kiekvienas kartus daiktas yra saldus.'),
  (@b20, 27, 8, 'Kaip paukštis, nuklydęs nuo savo lizdo, taip yra žmogus, nuklydęs nuo savo vietos.'),
  (@b20, 27, 9, 'Tepalas ir kvepalai džiugina širdį; taip ir draugo švelnumas nuoširdžiu patarimu.'),
  (@b20, 27, 10, 'Nepalik savo draugo ir savo tėvo draugo; ir neik į savo brolio namus savo nelaimės dieną: nes geriau kaimynas, kuris arti, negu brolis toli.'),
  (@b20, 27, 11, 'Mano sūnau, būk išmintingas ir pralinksmink mano širdį, kad galėčiau atsakyti tam, kuris man priekaištauja.'),
  (@b20, 27, 12, 'Protingas numato pikta ir pasislepia; bet paikasis eina toliau ir yra nubaudžiamas.'),
  (@b20, 27, 13, 'Paimk drabužį to, kuris laiduoja už svetimą; ir paimk iš jo užstatą už svetimą moterį.'),
  (@b20, 27, 14, 'Kas atsikėlęs ankstų rytą garsiu balsu laimina savo draugą, tai bus jam užskaityta prakeikimu.'),
  (@b20, 27, 15, 'Nuolatinis varvėjimas labai lietingą dieną ir vaidinga moteris yra vienodi.'),
  (@b20, 27, 16, 'Kas ją slepia, slepia vėją, ir savo dešinės rankos tepalą, kuris išsiduoda.'),
  (@b20, 27, 17, 'Geležis geležį galanda; taip žmogus aštrina savo draugo veidą.'),
  (@b20, 27, 18, 'Kas saugo figmedį, valgys jo vaisius; taip ir kas patarnauja savo valdovui, bus gerbiamas.'),
  (@b20, 27, 19, 'Kaip vandenyje veidas atspindi veidą, taip žmogaus širdis žmogų.'),
  (@b20, 27, 20, 'Pragaras ir pražūtis niekada nepilni; taip žmogaus akys niekada nepasitenkina.'),
  (@b20, 27, 21, 'Kaip tiglis sidabrui ir krosnis auksui; taip žmogus savo gyriui.'),
  (@b20, 27, 22, 'Nors ir sugrūstum kvailį grūstuve piestoje tarp kviečių, tačiau nuo jo neatsiskirtų jo kvailystė.'),
  (@b20, 27, 23, 'Būk stropus, kad pažintum savo kaimenių būklę, ir gerai prižiūrėk savo bandas.'),
  (@b20, 27, 24, 'Nes turtai neamžini; ir ar karūna išlieka visoms kartoms?'),
  (@b20, 27, 25, 'Šienas pasirodo, pasirodo minkšta žolė, ir renkamos kalnų žolės.'),
  (@b20, 27, 26, 'Avinėliai yra tavo apdarui ir ožiai yra lauko kaina.'),
  (@b20, 27, 27, 'Ir tu pakankamai turėsi ožkų pieno maistui tau, maistui tavo namams, ir tavo tarnaitėms išlaikyti.'),
  (@b20, 28, 1, 'Nedorėlis bėga niekam nesivejant; bet teisusis yra drąsus kaip liūtas.'),
  (@b20, 28, 2, 'Dėl šalies nusižengimo yra daug jos kunigaikščių; bet per supratimo ir pažinimo žmogų jos padėtis prasitęs.'),
  (@b20, 28, 3, 'Vargšas, kuris engia vargšą, yra panašus į nuplaunantį lietų, kuris nepalieka maisto.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b20, 28, 4, 'Kurie atsižada įstatymo, giria nedorėlius; bet kurie laikosi įstatymo, kovoja su jais.'),
  (@b20, 28, 5, 'Pikti žmonės nesupranta teismo, bet ieškantieji VIEŠPATIES viską supranta.'),
  (@b20, 28, 6, 'Geriau vargšas, vaikščiojantis savo tiesumu, negu tas, kuris iškrypęs savo keliuose, nors jis ir turtingas.'),
  (@b20, 28, 7, 'Kas laikosi įstatymo, yra išmintingas sūnus, bet lėbautojų draugas daro gėdą savo tėvui.'),
  (@b20, 28, 8, 'Kas daugina savo turtą palūkanomis ir neteisingu pasipelnymu, tas kaupia jį tam, kuris pasigailės vargšų.'),
  (@b20, 28, 9, 'Kas nusuka savo ausį, kad negirdėtų įstatymo, to malda bus pasibjaurėjimas.'),
  (@b20, 28, 10, 'Kas skatina teisųjį nuklysti į piktą kelią, pats įkris į savo duobę; bet tiesieji gaus nuosavybėn gerų dalykų.'),
  (@b20, 28, 11, 'Turtingas žmogus išmintingas savo paties akyse, bet turintis supratimą vargšas jį ištiria.'),
  (@b20, 28, 12, 'Kai teisieji džiūgauja – didelė šlovė; bet kai nedorėliai iškyla, žmonės slepiasi.'),
  (@b20, 28, 13, 'Kas slepia savo nuodėmes, tam nesiseks; bet kas jas išpažįsta ir jas palieka, susilauks gailestingumo.'),
  (@b20, 28, 14, 'Laimingas žmogus, kuris nuolat bijo; bet kas užkietina savo širdį, įpuls į nelaimę.'),
  (@b20, 28, 15, 'Kaip riaumojantis liūtas ir klajojanti meška, toks yra nedoras neturtingos tautos valdovas.'),
  (@b20, 28, 16, 'Kunigaikštis, kuriam stinga supratimo, yra ir didelis engėjas; bet, kas nekenčia godumo, prailgins savo dienas.'),
  (@b20, 28, 17, 'Žmogus, kuris smurtauja iki žmogaus kraujo, pabėgs į duobę; niekas jo tenesulaiko.'),
  (@b20, 28, 18, 'Kas vaikšto tiesumu, bus išgelbėtas; bet kas yra iškrypęs savo keliuose, iškart pargrius.'),
  (@b20, 28, 19, 'Kas įdirba savo žemę, turės gausiai duonos; bet kas seka paskui tuščius žmones, turės pakankamai skurdo.'),
  (@b20, 28, 20, 'Ištikimas žmogus turės gausiai palaiminimų; bet kas skuba praturtėti, neliks nekaltas.'),
  (@b20, 28, 21, 'Būti šališkam yra negerai; nes dėl duonos gabalėlio toks žmogus nusižengs.'),
  (@b20, 28, 22, 'Kas skuba praturtėti, turi piktą akį ir nepagalvoja, kad jam ateis skurdas.'),
  (@b20, 28, 23, 'Kas bara žmogų, po to ras daugiau palankumo negu tas, kuris pataikauja liežuviu.'),
  (@b20, 28, 24, 'Kas apiplėšia savo tėvą ar savo motiną ir sako: „Tai – ne nusižengimas“, tas yra naikintojo draugas.'),
  (@b20, 28, 25, 'Kas yra išdidžios širdies, sukelia nesantaiką; bet, kas pasikliauja VIEŠPAČIU, bus nupenėtas.'),
  (@b20, 28, 26, 'Kas pasitiki savo širdimi, yra kvailys; bet kas išmintingai vaikšto, tas bus išgelbėtas.'),
  (@b20, 28, 27, 'Kas duoda vargšui, nestokos; bet kas paslepia savo akis, susilauks daug prakeikimų.'),
  (@b20, 28, 28, 'Kai pakyla nedorėliai, žmonės slepiasi; bet kai jie pražūna, padaugėja teisiųjų.'),
  (@b20, 29, 1, 'Kas dažnai baramas užkietina savo sprandą, bus staiga sunaikintas ir nepagydomai.'),
  (@b20, 29, 2, 'Kai teisieji valdžioje, tauta džiaugiasi, bet kai nedorėliai valdo, tauta gedi.'),
  (@b20, 29, 3, 'Kas myli išmintį, džiugina savo tėvą, bet kas susideda su paleistuvėmis, išeikvoja savo turtą.'),
  (@b20, 29, 4, 'Karalius teismu įtvirtina šalį, bet kas ima dovanas, ją sugriauna.'),
  (@b20, 29, 5, 'Žmogus, pataikaujantis savo artimui, ištiesia tinklą jo kojoms.'),
  (@b20, 29, 6, 'Pikto žmogaus nusižengime yra spąstai, bet teisusis gieda ir džiaugiasi.'),
  (@b20, 29, 7, 'Teisusis apsvarsto vargšo bylą, bet nedorėlis neatsižvelgia, kad ją pažintų.'),
  (@b20, 29, 8, 'Išjuokėjai įtraukia miestą į žabangas, bet išmintingieji nukreipia rūstybę.'),
  (@b20, 29, 9, 'Jei išmintingas susiginčija su kvailiu, ar tas niršta, ar juokiasi, – nėra ramybės.'),
  (@b20, 29, 10, 'Kraujo trokštantis nekenčia tiesiojo, bet teisieji ieško jo sielos.'),
  (@b20, 29, 11, 'Kvailys kalba viską, ką galvoja, bet išmintingasis tai susilaiko iki vėliau.'),
  (@b20, 29, 12, 'Jei valdovas klauso melų, visi jo tarnai yra nedorėliai.'),
  (@b20, 29, 13, 'Vargšas ir apgavikas susitinka kartu: VIEŠPATS apšviečia jų abiejų akis.'),
  (@b20, 29, 14, 'Karaliaus, kuris ištikimai teisia vargšus, sostas įsitvirtins per amžius.'),
  (@b20, 29, 15, 'Rykštė ir pabarimas teikia išmintį; bet vaikas, paliktas savo valiai, daro gėdą savo motinai.'),
  (@b20, 29, 16, 'Daugėjant nedorėliams, daugėja nusižengimų, bet teisieji matys jų griuvimą.'),
  (@b20, 29, 17, 'Pataisyk savo sūnų, ir jis tau suteiks ramybę; taip, jis suteiks pasigėrėjimą tavo sielai.'),
  (@b20, 29, 18, 'Kai nėra regėjimo, žūsta tauta; bet kas laikosi įstatymo, tas laimingas.'),
  (@b20, 29, 19, 'Žodžiais tarno nepataisysi, nes nors jis supranta, jis neatsakys.'),
  (@b20, 29, 20, 'Ar matai žmogų, skubantį savo žodžiais? Iš kvailio daugiau vilties negu iš jo.'),
  (@b20, 29, 21, 'Kas prabangiai augina nuo vaikystės savo tarną, tam jis galiausiai taps jo sūnumi.'),
  (@b20, 29, 22, 'Supykęs žmogus sukelia ginčą, ir įnirtęs žmogus gausėja nusižengimais.'),
  (@b20, 29, 23, 'Žmogaus išdidumas jį nužemins, bet garbė palaikys nuolankųjį dvasioje.'),
  (@b20, 29, 24, 'Kas yra bendrininkas su vagimi, nekenčia savo sielos; jis girdi prakeikimą, bet to nepraneša.'),
  (@b20, 29, 25, 'Žmonių baimė atneša žabangas, bet kas pasitiki VIEŠPAČIU, bus saugus.'),
  (@b20, 29, 26, 'Daugelis ieško valdovo palankumo, bet kiekvieno žmogaus teismas ateina iš VIEŠPATIES.'),
  (@b20, 29, 27, 'Neteisus žmogus yra pasibjaurėjimas teisiesiems, o tiesusis kelyje yra pasibjaurėjimas nedorėliui.'),
  (@b20, 30, 1, 'Žodžiai Agūro, Jakės sūnaus, tai yra, pranašystė; tas žmogus kalbėjo Itieliui, tai yra Itieliui ir Ukalui:'),
  (@b20, 30, 2, 'Tikrai aš bukesnis už bet kokį žmogų ir neturiu žmogaus supratimo.'),
  (@b20, 30, 3, 'Aš neišmokau išminties nei neturiu šventųjų pažinimo.'),
  (@b20, 30, 4, 'Kas užžengė į dangų arba nužengė? Kas surinko vėją į savo saujas? Kas surišo vandenis į drabužį? Kas įtvirtino visus žemės pakraščius? Kuo jis vardu ir kuo vardu jo sūnus, jei žinai?“'),
  (@b20, 30, 5, 'Kiekvienas Dievo žodis yra tyras; jis yra skydas tiems, kurie juo pasikliauja.'),
  (@b20, 30, 6, 'Nepridėk prie jo žodžių, kad jis tavęs nepapeiktų ir nebūtum rastas melagiu.'),
  (@b20, 30, 7, 'Dviejų dalykų prašiau tavęs; neužgink man jų pirmiau nei mirsiu:'),
  (@b20, 30, 8, 'atitolink nuo manęs tuštybę ir melus; neduok man nei skurdo, nei turtų; maitink mane man tinkamu maistu;'),
  (@b20, 30, 9, 'kad pasisotinęs neišsiginčiau tavęs ir nesakyčiau: „Kas yra VIEŠPATS?“ Arba, kad būdamas vargšas nevogčiau ir tuščiai nevartočiau savo Dievo vardo.'),
  (@b20, 30, 10, 'Neapkaltink tarno jo valdovui, kad jis tavęs nekeiktų ir nebūtum rastas kaltu.'),
  (@b20, 30, 11, 'Yra karta, kuri keikia savo tėvą ir nelaimina savo motinos.'),
  (@b20, 30, 12, 'Yra karta, kuri yra tyra savo pačių akyse, tačiau nenuplauta nuo savų nešvarumų.'),
  (@b20, 30, 13, 'Yra karta, oi kokios išdidžios jų akys! Ir jų akių vokai pakelti.'),
  (@b20, 30, 14, 'Yra karta, kurių dantys kaip kalavijai ir jų žandikaulių dantys kaip peiliai, kad surytų vargšus iš žemės ir beturčius iš žmonių tarpo.'),
  (@b20, 30, 15, 'Siurbėlė turi dvi dukteris, šaukiančias: „Duok, duok“. Yra trys dalykai, kurie niekada nepasitenkina, taip, keturi dalykai nesako: „Gana“ –'),
  (@b20, 30, 16, 'kapas; nevaisingos įsčios; žemė, neprisigerianti vandens; ir ugnis, kuri nesako: „Gana“.'),
  (@b20, 30, 17, 'Akį, kuri tyčiojasi iš savo tėvo ir niekina paklusnumą motinai, slėnio varnai iškapos ir suės jauni ereliai.'),
  (@b20, 30, 18, 'Yra trys dalykai man perdaug nuostabūs, taip, keturi, kurių nežinau:'),
  (@b20, 30, 19, 'erelio kelias ore; gyvatės kelias ant uolos; laivo kelias jūros viduryje ir vyro kelias su mergina.'),
  (@b20, 30, 20, 'Toks yra svetimaujančios moters kelias: ji pavalgo, nusišluosto burną ir sako: „Nepadariau nieko nedoro“.'),
  (@b20, 30, 21, 'Dėl trijų dalykų nerimsta žemė ir dėl keturių, kurių ji negali pakelti:'),
  (@b20, 30, 22, 'dėl tarno, kai jis karaliauja; ir kvailio, kai jis pasisotina maistu;'),
  (@b20, 30, 23, 'dėl neapkenčiamos moters, kai ji išteka; ir tarnaitės, kuri yra savo valdovės įpėdinė.'),
  (@b20, 30, 24, 'Yra keturi mažiausi žemėje, bet jie yra be galo išmintingi:'),
  (@b20, 30, 25, 'skruzdės – nestipri tauta, tačiau jos vasarą pasiruošia savo maistą;'),
  (@b20, 30, 26, 'triušiai – tik silpna liaudis, tačiau pasidaro namus uolose;'),
  (@b20, 30, 27, 'skėriai neturi karaliaus, tačiau jie visi išskrenda būriais;'),
  (@b20, 30, 28, 'voras čiumpa savo rankomis, ir yra karalių rūmuose.'),
  (@b20, 30, 29, 'Yra trys, kurie gerai eina, taip, keturi, kurie gražiai vaikšto:'),
  (@b20, 30, 30, 'liūtas, kuris yra stipriausias tarp žvėrių, ir nepasitraukia nei dėl vieno;'),
  (@b20, 30, 31, 'kurtas; taipogi ožys; ir karalius, prieš kurį nesukyla.'),
  (@b20, 30, 32, 'Jei kvailai padarei aukštindamas save, arba jei galvojai pikta, uždėk ranką ant savo burnos.'),
  (@b20, 30, 33, 'Tikrai pieno mušimas išgauna sviestą, ir nosies spaudimas išgauna kraują; taip ir rūstybės skatinimas pagimdo ginčą.'),
  (@b20, 31, 1, 'Karaliaus Lemuelio žodžiai, pranašystė, kurios jį mokė jo motina.'),
  (@b20, 31, 2, 'Ką, mano sūnau? Ką, mano įsčių sūnau? Ką, mano įžadų sūnau?'),
  (@b20, 31, 3, 'Neatiduok savo stiprybės moterims nei savo kelių tam, kas pražudo karalius.'),
  (@b20, 31, 4, 'Ne karaliams, o Lemueli, ne karaliams gerti vyną; nei kunigaikščiams stiprų gėrimą;'),
  (@b20, 31, 5, 'kad jie gerdami nepamirštų įstatymo ir neiškraipytų teismo nei vieno iš prispaustųjų.'),
  (@b20, 31, 6, 'Duok stiprų gėrimą bepražūstančiam ir vyną tiems, kurių širdys nuliūdusios.'),
  (@b20, 31, 7, 'Jis tegeria ir tepamiršta savo neturtą ir savo vargo tenebeatsimena.'),
  (@b20, 31, 8, 'Atverk už nebylį savo burną byloje visų tų, kurie paskirti pražūčiai.'),
  (@b20, 31, 9, 'Atverk savo burną, teisk teisingai ir gink vargšų bei nepasiturinčiųjų bylą.'),
  (@b20, 31, 10, 'Kas gali rasti dorybingą moterį? Nes ji daug vertingesnė už rubinus.'),
  (@b20, 31, 11, 'Jos vyro širdis užtikrintai ja pasitiki, taip, kad jam netrūks pelno.'),
  (@b20, 31, 12, 'Ji darys jam gera, o ne pikta, per visas savo gyvenimo dienas.'),
  (@b20, 31, 13, 'Ji ieško vilnos, lino ir noriai dirba savo rankomis.'),
  (@b20, 31, 14, 'Ji yra kaip pirklių laivai: iš toli ji pargabena savo maistą.'),
  (@b20, 31, 15, 'Taipogi ji keliasi kai dar naktis, duoda maisto savo namiškiams ir dalį savo tarnaitėms.'),
  (@b20, 31, 16, 'Ji apsvarsto lauką ir jį nuperka; savo rankų vaisiumi ji pasodina vynuogyną.'),
  (@b20, 31, 17, 'Ji apjuosia savo strėnas stiprybe ir sustiprina savo rankas.'),
  (@b20, 31, 18, 'Ji pastebi, kad jos prekiavimas geras; jos žvakė neužgęsta naktį.'),
  (@b20, 31, 19, 'Ji prideda savo rankas prie verpsto, ir jos rankos laiko verpstę.'),
  (@b20, 31, 20, 'Ji ištiesia savo ranką vargšui; taip, ji ištiesia savo rankas stokojančiam.'),
  (@b20, 31, 21, 'Ji nebijo sniego dėl savo namiškių; nes visi jos namiškiai aprengti skaisčiai raudonu.'),
  (@b20, 31, 22, 'Ji pasidaro gobeleno apdangalų; jos drabužis – šilkas ir purpuras.'),
  (@b20, 31, 23, 'Jos vyras yra žinomas vartuose, kai jis sėdi tarp šalies vyresniųjų.'),
  (@b20, 31, 24, 'Ji padaro plonų drobių ir jas parduoda; ir pristato juostų pirkliui.'),
  (@b20, 31, 25, 'Stiprybė ir garbė – jos drabužis; ir ji džiaugsis ateinančiu laiku.'),
  (@b20, 31, 26, 'Ji atveria savo burną išmintimi; ir ant jos liežuvio – gerumo įstatymas.'),
  (@b20, 31, 27, 'Ji gerai prižiūri savo namiškių kelius ir nevalgo tinginystės duonos.'),
  (@b20, 31, 28, 'Jos vaikai pakyla ir vadina ją palaiminta; jos vyras irgi – ir jis ją giria:'),
  (@b20, 31, 29, '„Daug dukterų elgėsi dorybingai, bet tu pranoksti jas visas“.'),
  (@b20, 31, 30, 'Palankumas yra apgaulingas ir grožis yra tuščias; bet moteris, bijanti VIEŠPATIES, bus giriama.'),
  (@b20, 31, 31, 'Duok jai jos rankų vaisių; ir tegul jos darbai giria ją vartuose.'),
  (@b21, 1, 1, 'Žodžiai Pamokslininko, Dovydo sūnaus, karaliaus Jeruzalėje.'),
  (@b21, 1, 2, 'Tuštybių tuštybė, – sako Pamokslininkas, – tuštybių tuštybė; viskas tuštybė.'),
  (@b21, 1, 3, 'Kokia nauda žmogui iš viso jo triūso, kurio jis imasi po saule?'),
  (@b21, 1, 4, 'Viena karta praeina, kita karta ateina; bet žemė pasilieka per amžius.'),
  (@b21, 1, 5, 'Saulė pateka, saulė nusileidžia ir skuba į savo vietą, iš kur ji patekėjo.'),
  (@b21, 1, 6, 'Vėjas eina į pietus ir suka aplink į šiaurę; jis nuolat sukasi aplink, ir vėjas atgal sugrįžta pagal savo apsisukimus.'),
  (@b21, 1, 7, 'Visos upės teka į jūrą, tačiau jūra nepilna; į vietą, iš kur upės atiteka, ten jos vėl sugrįžta.'),
  (@b21, 1, 8, 'Visi dalykai pilni triūso, žmogus negali jų išsakyti; akys nepasisotina matymu, ir ausys neprisipildo girdėjimu.'),
  (@b21, 1, 9, 'Dalykai, kurie buvo, yra tai, kas bus; ir kas buvo daroma, yra tai, kas bus daroma; nieko naujo nėra po saule.'),
  (@b21, 1, 10, 'Ar yra kas, apie ką galima pasakyti: „Žiūrėk, tai nauja“? Tai jau buvo senais laikais, kurie buvo pirma mūsų.'),
  (@b21, 1, 11, 'Neatmenama tai, kas buvo anksčiau; ir to, kas bus ateityje, neatsimins tie, kurie po to ateis.'),
  (@b21, 1, 12, 'Aš, Pamokslininkas, buvau Izraelio karalius Jeruzalėje.'),
  (@b21, 1, 13, 'Aš atidaviau savo širdį, kad ieškočiau ir tyrinėčiau išmintimi viską, kas vyksta po dangumi; šį sunkų triūsą Dievas davė žmogaus sūnums, kad juo užsiimtų.'),
  (@b21, 1, 14, 'Mačiau visus darbus, kurie daromi po saule; ir štai viskas yra tuštybė ir dvasios varginimas.'),
  (@b21, 1, 15, 'To, kas kreiva, negalima ištiesinti; ir ko trūksta, negalima suskaičiuoti.'),
  (@b21, 1, 16, 'Aš kalbėjau su savo širdimi, sakydamas: „Štai aš įgijau aukštą padėtį ir įgijau daugiau išminties už visus, kurie pirma manęs buvo Jeruzalėje; taip, mano širdis turėjo didelę išminties ir pažinimo patirtį“.'),
  (@b21, 1, 17, 'Ir atidaviau savo širdį, kad pažinčiau išmintį ir pažinčiau beprotybę ir kvailystę; aš pastebėjau, kad ir tai yra dvasios varginimas.'),
  (@b21, 1, 18, 'Nes daugybėje išminties yra daug sielvarto; ir kas įgyja daugiau pažinimo, įgyja daugiau ir širdgėlos“.'),
  (@b21, 2, 1, 'Tariau savo širdyje: „Na, išbandysiu tave linksmybe, todėl džiaukis malonumais“; ir štai tai irgi tuštybė.'),
  (@b21, 2, 2, 'Apie juoką sakiau: „Jis beprotis“; ir apie linksmybę: „Ką ji daro?“'),
  (@b21, 2, 3, 'Siekiau savo širdyje atsiduoti vynui, tačiau supažindinant savo širdį su išmintimi; ir nusitverti kvailybę, kol pamatysiu, kas buvo gera žmonių sūnums, ką jie turėtų daryti po dangumi per visas savo gyvenimo dienas.'),
  (@b21, 2, 4, 'Atlikau sau didelių darbų: pasistačiau namų, pasisodinau vynuogynų;'),
  (@b21, 2, 5, 'pasidariau sodų bei vaismedžių sodų ir juose pasodinau įvairių vaisių medžių;'),
  (@b21, 2, 6, 'pasidariau vandens tvenkinių, kad jais laistyčiau mišką, išauginantį medžius;'),
  (@b21, 2, 7, 'įsigijau tarnų bei tarnaičių ir turėjau savo namuose gimusių tarnų; taip pat turėjau didelių ir mažų galvijų, daugiau už visus, kurie pirma manęs buvo Jeruzalėje;'),
  (@b21, 2, 8, 'taip pat prisirinkau sidabro bei aukso ir ypatingo karalių bei provincijų turto; pasirūpinau giesmininkų bei giesmininkių ir to, kuo gėrisi žmonių sūnūs – visų rūšių muzikinių instrumentų.'),
  (@b21, 2, 9, 'Taigi aš buvau didis ir išaugau labiau už visus, kurie buvo prieš mane Jeruzalėje; taip pat mano išmintis pasiliko su manimi.'),
  (@b21, 2, 10, 'Ir ko tik troško mano akys, nieko joms neatsakiau, nesulaikiau savo širdies nuo jokio džiaugsmo; nes mano širdis džiaugėsi visu mano triūsu; ir tai buvo viso mano triūso dalis.'),
  (@b21, 2, 11, 'Tada aš pažiūrėjau į visus darbus, kuriuos padarė mano rankos, ir į triūsą, kuriame triūsiau dirbdamas; ir štai viskas buvo tuštybė ir dvasios varginimas, ir nebuvo jokios naudos po saule.'),
  (@b21, 2, 12, 'Ir pasisukau pasižiūrėti į išmintį, į beprotybę ir kvailystę; nes ką gali padaryti žmogus, kuris ateis po karaliaus? Būtent tai, kas jau buvo padaryta.'),
  (@b21, 2, 13, 'Tada pamačiau, kad išmintis tiek pralenkia kvailystę, kiek šviesa pralenkia tamsą.'),
  (@b21, 2, 14, 'Išmintingojo akys yra jo galvoje; bet kvailys vaikšto tamsoje; ir aš taip pat pastebėjau, kad vienodi atsitikimai nutinka jiems visiems.'),
  (@b21, 2, 15, 'Tada tariau savo širdyje: „Kaip atsitinka kvailiui, taip ir man atsitinka; tad kodėl buvau išmintingesnis?“ Tada tariau savo širdyje, kad tai irgi tuštybė.'),
  (@b21, 2, 16, 'Nes neatsimins išmintingojo daugiau nei kvailio per amžius; nes tai, kas yra dabar, ateinančiomis dienomis viskas bus pamiršta. O kaip miršta išmintingasis? Kaip kvailys.'),
  (@b21, 2, 17, 'Todėl nekenčiau gyvenimo; nes darbas, kuris daromas po saule, man sielvartingas; nes viskas yra tuštybė ir dvasios varginimas.'),
  (@b21, 2, 18, 'Taip, aš nekenčiau viso savo triūso, kurio aš ėmiausi po saule; nes turiu tai palikti žmogui, kuris bus po manęs.'),
  (@b21, 2, 19, 'Ir kas žino, ar jis bus išmintingas, ar kvailys? Tačiau jis valdys visą mano triūsą, kuriuo triūsiau ir kuriuo pasirodžiau išmintingas po saule. Tai irgi tuštybė.'),
  (@b21, 2, 20, 'Todėl aš nusigręžiau, kad sukelčiau savo širdžiai nusivylimą visu triūsu, kurio ėmiausi po saule.'),
  (@b21, 2, 21, 'Nes yra žmogus, kurio triūsas yra išmintimi, pažinimu ir bešališkumu; tačiau žmogui, kuris tuo netriūsė, jis tai paliks jo daliai. Tai irgi tuštybė ir didelė blogybė.'),
  (@b21, 2, 22, 'Nes ką gi žmogus turi iš viso savo triūso ir iš savo širdies varginimo, kuriuo jis triūsė po saule?'),
  (@b21, 2, 23, 'Nes visos jo dienos – sielvartai, ir jo triūsas – širdgėla; taip, naktį jo širdis neturi poilsio. Tai irgi tuštybė.'),
  (@b21, 2, 24, 'Nieko nėra geresnio žmogui, kaip valgyti, gerti, ir kad jis džiugintų savo sielą savo triūse. Aš ir tai mačiau, kad tai buvo iš Dievo rankos.'),
  (@b21, 2, 25, 'Nes kas gali valgyti arba kas gali prie to skubėti labiau už mane?'),
  (@b21, 2, 26, 'Nes Dievas žmogui, kuris yra geras jo akyse, duoda išminties, pažinimo ir džiaugsmo; bet nusidėjėliui jis duoda sunkų darbą rinkti ir krauti, kad šis duotų tam, kuris yra geras Dievo akivaizdoje. Tai irgi tuštybė ir dvasios varginimas.'),
  (@b21, 3, 1, 'Viskam yra laikotarpis, ir laikas kiekvienam tikslui po dangumi:'),
  (@b21, 3, 2, 'laikas gimti ir laikas mirti; laikas sodinti ir laikas išrauti, kas pasodinta;'),
  (@b21, 3, 3, 'laikas žudyti ir laikas gydyti; laikas griauti ir laikas statyti;'),
  (@b21, 3, 4, 'laikas verkti ir laikas juoktis; laikas gedėti ir laikas šokti;'),
  (@b21, 3, 5, 'laikas išmėtyti akmenis ir laikas surinkti akmenis; laikas apkabinti ir laikas susilaikyti nuo apkabinimo;'),
  (@b21, 3, 6, 'laikas įgyti ir laikas prarasti; laikas laikyti ir laikas išmesti;'),
  (@b21, 3, 7, 'laikas perplėšti ir laikas susiūti; laikas tylėti ir laikas kalbėti;'),
  (@b21, 3, 8, 'laikas mylėti ir laikas nekęsti; laikas karui ir laikas taikai.'),
  (@b21, 3, 9, 'Kokią naudą dirbantis turi iš to, kame jis triūsia?'),
  (@b21, 3, 10, 'Mačiau sunkų darbą, kurį Dievas davė žmonių sūnums, kad lavintųsi jame.'),
  (@b21, 3, 11, 'Visus dalykus jis padarė gražius savo laiku; taip pat jis įdėjo pasaulį į jų širdį, kad joks žmogus negalėtų išsiaiškinti Dievo daromo darbo nuo pradžios iki galo.'),
  (@b21, 3, 12, 'Žinau, kad nieko geresnio juose nėra, kaip tik žmogui džiaugtis ir daryti gera savo gyvenime.'),
  (@b21, 3, 13, 'Ir taip pat, kad kiekvienas žmogus valgytų, gertų ir džiaugtųsi geru iš viso savo triūso; tai Dievo dovana.'),
  (@b21, 3, 14, 'Žinau, kad viskas, ką Dievas daro, bus per amžius; prie to nieko negalima pridėti ir nuo to nieko negalima atimti; ir Dievas tai daro, kad žmonės bijotų jo akivaizdoje.'),
  (@b21, 3, 15, 'Tai, kas yra buvę, yra dabar; ir tai, kas bus, jau yra buvę; ir Dievas reikalauja to, kas yra praeitis.'),
  (@b21, 3, 16, 'Dar mačiau po saule teismo vietą, kad ten buvo nedorybė; ir teisumo vietą, kad ten buvo neteisybė.'),
  (@b21, 3, 17, 'Tariau savo širdyje: „Dievas teis teisųjį ir nedorėlį; nes ten yra laikas kiekvienam tikslui ir kiekvienam darbui“.'),
  (@b21, 3, 18, 'Tariau savo širdyje dėl žmonių sūnų padėties, kad Dievas jiems apreikštų, ir jie pamatytų, kad patys jie yra gyvuliai.'),
  (@b21, 3, 19, 'Nes kas atsitinka žmonių sūnums, atsitinka ir gyvuliams; jiems atsitinka būtent tas pats dalykas: kaip vienas miršta, taip ir kitas miršta; taip, jie visi turi vieną kvėpavimą; taip, kad žmogus nepranašesnis už gyvulį; nes viskas yra tuštybė.'),
  (@b21, 3, 20, 'Visi eina į vieną vietą; visi yra iš dulkių ir visi vėl pavirsta į dulkes.'),
  (@b21, 3, 21, 'Kas žino žmogaus dvasią, kuri kyla aukštyn, ir gyvulio dvasią, kuri eina žemyn į žemę?'),
  (@b21, 3, 22, 'Todėl pastebėjau, kad žmogui nieko nėra geresnio, kaip džiaugtis savo darbais; nes tai yra jo dalis; nes kas jį atves pamatyti, kas bus po jo?'),
  (@b21, 4, 1, 'Taigi atsigręžiau ir apžiūrėjau visus engimus, daromus po saule: ir štai engiamųjų ašaros, ir jie neturėjo guodėjo; o jų engėjų pusėje buvo jėga, bet jie neturėjo guodėjo.'),
  (@b21, 4, 2, 'Todėl mirusiuosius, kurie jau mirę, gyriau labiau už gyvuosius, kurie tebegyvena.'),
  (@b21, 4, 3, 'Taip, geriau už juos abu yra tam, kurio dar nebuvo, kuris nematė piktų darbų, kurie daromi po saule.'),
  (@b21, 4, 4, 'Vėlgi, apžiūrėjau visą triūsą ir kiekvieną teisingą darbą, kad dėl to žmogui pavydi jo artimas. Tai irgi tuštybė ir dvasios varginimas.'),
  (@b21, 4, 5, 'Kvailys susideda rankas ir valgo savo kūną.'),
  (@b21, 4, 6, 'Geriau sauja su ramybe, negu abi pilnos rankos su triūsu ir dvasios varginimu.'),
  (@b21, 4, 7, 'Tada atsigręžiau ir pamačiau tuštybę po saule.'),
  (@b21, 4, 8, 'Yra vienas vienišas ir nėra antrojo; taip, jis neturi nei vaiko, nei brolio; tačiau visam jo triūsui nėra galo; taip pat jo akis nepasisotina turtais; ir jis nesako: ‘Kieno labui aš triūsiu ir atimu gera iš savo sielos?’ Tai irgi tuštybė, taip, tai sunkus triūsas.'),
  (@b21, 4, 9, 'Du yra geriau negu vienas, nes jie turi gerą atpildą už savo triūsą.'),
  (@b21, 4, 10, 'Nes jei jie parkrinta, vienas pakelia savo draugą; bet vargas vienišam, kai jis parkrinta, nes nėra antrojo jam pakelti.'),
  (@b21, 4, 11, 'Vėlgi, jei du guli drauge, tada jie sušyla; bet kaip sušilti vienam?'),
  (@b21, 4, 12, 'Ir jei kas vieną nugali, tai du jam pasipriešins; ir triguba virvė negreit pertrūksta.'),
  (@b21, 4, 13, 'Geriau vargšas ir išmintingas vaikas, negu senas ir kvailas karalius, kuris nebenori priimti patarimų.'),
  (@b21, 4, 14, 'Nes iš kalėjimo jis ateina karaliauti; tuo tarpu gimusysis jo karalystėje tampa vargšu.'),
  (@b21, 4, 15, 'Mačiau visus gyvuosius, vaikščiojančius po saule, su antruoju vaiku, kuris stosis į jo vietą.'),
  (@b21, 4, 16, 'Nėra galo visiems žmonėms – visiems, kurie yra buvę prieš juos; ir vėliau atėjusieji nebesidžiaugs juo. Tikrai tai irgi tuštybė ir dvasios varginimas.'),
  (@b21, 5, 1, 'Saugok savo koją, kai eini į Dievo namus, ir būk labiau pasiruošęs klausytis, negu duoti kvailių auką; nes jie neapgalvoja, kad daro pikta.'),
  (@b21, 5, 2, 'Nebūk skubus savo burna, ir tavo širdis teneskuba ko nors ištarti Dievo akivaizdoje; nes Dievas yra danguje, o tu žemėje; todėl mažai tebūna tavo žodžių.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b21, 5, 3, 'Nes sapnas ateina dėl daugybės rūpesčių; ir kvailio balsas pažįstamas iš daugybės žodžių.'),
  (@b21, 5, 4, 'Kai duodi Dievui įžadą, negaišk jo ištesėti; nes jam nepatinka kvailiai; ištesėk tai, ką pasižadėjai.'),
  (@b21, 5, 5, 'Geriau tau neduoti įžado, negu davus įžadą – neištesėti.'),
  (@b21, 5, 6, 'Neleisk savo burnai skatinti tavo kūną nusidėti; ir nesakyk angelo akivaizdoje, kad tai buvo klaida; kodėl Dievas turėtų supykti dėl tavo balso ir sunaikinti tavo rankų darbą?'),
  (@b21, 5, 7, 'Nes sapnų daugybėje ir daugybėje žodžių yra ir įvairios tuštybės; bet tu bijok Dievo.'),
  (@b21, 5, 8, 'Jei provincijoje matai beturčio engimą ir stiprų teismo ir teisingumo iškraipymą, tuo nesistebėk; nes prižiūri aukštesnis už aukščiausią; ir yra dar aukštesnis už juos.'),
  (@b21, 5, 9, 'Be to nauda iš žemės yra visiems; pats karalius aptarnaujamas laukų.'),
  (@b21, 5, 10, 'Kas myli sidabrą, nepasitenkina sidabru; nei mylintis gausą – prieaugiu; tai irgi tuštybė.'),
  (@b21, 5, 11, 'Kai padaugėja turtų, padaugėja ir jų valgytojų; ir kokia nauda jų savininkui, nebent, kad jis mato juos savo akimis?'),
  (@b21, 5, 12, 'Saldus darbininko miegas, ar jis daug, ar mažai valgo; bet turtuolio gausa neleidžia jam miegoti.'),
  (@b21, 5, 13, 'Yra skaudi blogybė, kurią mačiau po saule, būtent turtai, saugojami jų savininkui jo paties žalai.'),
  (@b21, 5, 14, 'Bet šitie turtai pražūna nuo pikto triūso; jis pagimdo sūnų, ir nieko nėra jo rankoje.'),
  (@b21, 5, 15, 'Kaip jis išėjo iš savo motinos įsčių, nuogas jis sugrįš, kad eitų, kaip atėjo, ir nieko nepasiims iš savo triūso, ką galėtų išsinešti savo rankoje.'),
  (@b21, 5, 16, 'Tai irgi skaudi blogybė, kad jis visais atžvilgiais išeis taip, kaip ir atėjo; ir kokia nauda tam, kuris triūsė vėjui?'),
  (@b21, 5, 17, 'Be to, per visas savo dienas jis valgo tamsoje, turi daug sielvarto ir rūstybių su savo liga.'),
  (@b21, 5, 18, 'Štai ką aš mačiau: gera ir miela žmogui yra valgyti, gerti ir džiaugtis geru iš viso savo triūso, kurio jis imasi po saule per visas savo gyvenimo dienas, kurias Dievas jam duoda; nes tai yra jo dalis.'),
  (@b21, 5, 19, 'Taip pat kiekvienam žmogui, kuriam Dievas davė turtų bei gausos ir jam davė valdžią iš to valgyti ir pasiimti savo dalį, ir džiaugtis savo triūsu; tai yra Dievo dovana.'),
  (@b21, 5, 20, 'Nes jis nedaug atsimins savo gyvenimo dienų; nes Dievas jam atsako jo širdies džiaugsme.'),
  (@b21, 6, 1, 'Yra blogybė, kurią mačiau po saule, ir ji dažna tarp žmonių:'),
  (@b21, 6, 2, 'žmogus, kuriam Dievas davė turtų, gausos ir garbės, kad jam nieko netrūksta jo sielai iš visko, ko jis geidžia, tačiau Dievas jam neduoda valdžios iš to valgyti, bet svetimas tai valgo; tai tuštybė ir tai pikta liga.'),
  (@b21, 6, 3, 'Jei žmogus pagimdytų šimtą vaikų ir gyventų daug metų, kad jo metų dienų būtų daug, o jo siela nepasisotintų geru ir jis neturėtų palaidojimo; aš sakyčiau, kad priešlaikis gimimas geriau už jį.'),
  (@b21, 6, 4, 'Nes jis ateina su tuštybe ir išeina tamsoje, ir jo vardas bus uždengtas tamsa.'),
  (@b21, 6, 5, 'Be to, jis nematė saulės nei nieko nepažino; šis turi daugiau poilsio negu anas.'),
  (@b21, 6, 6, 'Taip, nors jis gyventų dukart tūkstantį metų, tačiau nematytų gero; argi ne visi eina į vieną vietą?'),
  (@b21, 6, 7, 'Visas žmogaus triūsas yra jo burnai, tačiau apetitas nepasisotina.'),
  (@b21, 6, 8, 'Nes ko išminčius turi daugiau už kvailį? Ką turi vargšas, mokantis vaikščioti gyvųjų akivaizdoje?'),
  (@b21, 6, 9, 'Geriau akių matymas nei troškimo klajojimas; tai irgi tuštybė ir dvasios varginimas.'),
  (@b21, 6, 10, 'Tai, kas yra buvę, jau yra pavadinta, ir yra žinoma, kad tai – žmogus; ir jis negali varžytis su tuo, kuris galingesnis už jį.'),
  (@b21, 6, 11, 'Kadangi yra daug dalykų, kurie padaugina tuštybes, kuo geresnis žmogus?'),
  (@b21, 6, 12, 'Nes kas žino, kas gerai žmogui šiame gyvenime per visas jo tuščio gyvenimo dienas, kurias jis praleidžia kaip šešėlį? Nes kas gali pasakyti žmogui, kas po jo bus po saule?'),
  (@b21, 7, 1, 'Geras vardas geresnis už brangų tepalą; ir mirties diena už gimimo dieną.'),
  (@b21, 7, 2, 'Geriau eiti į gedulo namus, negu eiti į puotavimo namus; nes tai yra visų žmonių galas; ir gyvieji tai dėsis į širdį.'),
  (@b21, 7, 3, 'Liūdesys geriau už juoką; nes liūdnas veidas daro širdį geresnę.'),
  (@b21, 7, 4, 'Išmintingųjų širdis yra gedulo namuose; bet kvailių širdis – linksmybės namuose.'),
  (@b21, 7, 5, 'Geriau išgirsti išmintingojo pabarimą, negu klausytis kvailių giesmės.'),
  (@b21, 7, 6, 'Nes kaip erškėčiai spragsi po puodu, toks yra kvailio juokas; tai irgi tuštybė.'),
  (@b21, 7, 7, 'Tikrai engimas išmintingąjį padaro bepročiu; o dovana sužlugdo širdį.'),
  (@b21, 7, 8, 'Dalyko pabaiga yra geriau negu jo pradžia; ir kantrus dvasia yra geriau negu išdidus dvasia.'),
  (@b21, 7, 9, 'Nebūk savo dvasioje greitas pykti; nes pyktis ilsisi kvailių užantyje.'),
  (@b21, 7, 10, 'Nesakyk: „Kokia priežastis, kad ankstesnės dienos buvo geresnės už šias?“, nes neišmintingai apie tai klausi.'),
  (@b21, 7, 11, 'Išmintis yra gera su paveldėjimu, ir per ją yra nauda tiems, kurie mato saulę.'),
  (@b21, 7, 12, 'Nes išmintis yra apsauga ir pinigai yra apsauga; bet pažinimo pranašumas tas, kad išmintis duoda gyvenimą tiems, kurie ją turi.'),
  (@b21, 7, 13, 'Apsvarstyk Dievo darbą, nes kas gali ištiesinti tai, ką jis padarė kreivą?'),
  (@b21, 7, 14, 'Klestėjimo dieną būk džiaugsmingas, bet nelaimės dieną – apgalvok: Dievas ir sustatė vieną priešais kitą tam, kad žmogus nieko po savęs nerastų.'),
  (@b21, 7, 15, 'Visko mačiau savo tuštybės dienomis: čia teisusis, žūstantis savo teisume, ir čia nedorėlis, kuris prailgina savo gyvenimą savo nedorybėje.'),
  (@b21, 7, 16, 'Nebūk per daug teisus ir nedaryk savęs perdaug išmintingu; kodėl turėtum save pražudyti?'),
  (@b21, 7, 17, 'Nebūk per daug nedoras nei nebūk kvailas; kodėl turėtum mirti prieš savo laiką?'),
  (@b21, 7, 18, 'Gerai, kad nutversi tai, taip, ir nuo to nepatrauk rankos; nes kas bijo Dievo, išeis iš viso to.'),
  (@b21, 7, 19, 'Išmintis sustiprina išmintingąjį daugiau negu dešimt galiūnų, esančių mieste.'),
  (@b21, 7, 20, 'Nes nėra žemėje teisaus žmogaus, kuris darytų gera ir nenusidėtų.'),
  (@b21, 7, 21, 'Taip pat nekreipk dėmesio į visus žodžius, kuriuos kalba, kad neišgirstum savo tarno tave keikiant;'),
  (@b21, 7, 22, 'nes dažnai ir tavo širdis žino, kad ir tu taip pat keikei kitus.'),
  (@b21, 7, 23, 'Visa tai išmėginau išmintimi; aš sakiau: „Būsiu išmintingas“; bet tai buvo toli nuo manęs.'),
  (@b21, 7, 24, 'Tai, kas yra toli ir be galo giliai, kas gali tai ištirti?'),
  (@b21, 7, 25, 'Nukreipiau savo širdį pažinti, ištirti ir ieškoti išminties ir dalykų priežasties, ir pažinti nedorybę kvailybės, būtent kvailystės ir beprotybės;'),
  (@b21, 7, 26, 'ir aš randu kartesnę už mirtį moterį, kurios širdis yra spąstai ir tinklai, kurios rankos kaip pančiai; kas patinka Dievui, tas pabėgs iš jos; bet nusidėjėlis bus jos pagautas.'),
  (@b21, 7, 27, 'Štai tai aš radau, – sako pamokslininkas, skaičiuodamas viena po kito, kad išsiaiškinčiau priežastį, –'),
  (@b21, 7, 28, 'ko vis ieško mano siela, bet aš nerandu: radau vieną vyrą iš tūkstančio; bet moters tarp visų šitų neradau.'),
  (@b21, 7, 29, 'Štai vien tik tai radau, kad Dievas padarė žmogų tiesų; bet jie ieškojo daugybės prasimanymų.'),
  (@b21, 8, 1, 'Kas yra kaip išminčius? Ir kas moka dalyką išaiškinti? Žmogaus išmintis padaro jo veidą švytinį, ir pasikeičia jo veido drąsumas.'),
  (@b21, 8, 2, 'Aš tau patariu laikytis karaliaus įsakymo, ir tai dėl Dievo priesaikos.'),
  (@b21, 8, 3, 'Neskubėk išeiti iš jo akivaizdos; nestovėk piktame dalyke, nes jis daro viską, kas jam patinka.'),
  (@b21, 8, 4, 'Kur yra karaliaus žodis, ten valdžia; ir kas gali jam sakyti: ‘Ką darai?’'),
  (@b21, 8, 5, 'Kas laikosi įsakymo, nepatirs pikto dalyko; išmintingojo širdis atpažįsta laiką ir teismą.'),
  (@b21, 8, 6, 'Nes kiekvienam tikslui yra laikas ir teismas, todėl didelis ant žmogaus yra jo vargas.'),
  (@b21, 8, 7, 'Nes jis nežino to, kas bus; nes kas jam gali pasakyti, kada tai bus?'),
  (@b21, 8, 8, 'Nėra žmogaus, kuris turėtų galią dvasiai, kad sulaikytų dvasią; ir jis neturi galios mirties dieną; ir nėra paleidimo tame kare; ir nedorybė neišvaduos tų, kurie jai atsidavę.'),
  (@b21, 8, 9, 'Visa tai mačiau ir kreipiau savo širdį kiekvienam darbui, kuris daromas po saule; yra laikas, kai vienas žmogus valdo kitą sau pakenkti.'),
  (@b21, 8, 10, 'Ir taip mačiau laidojant nedorėlius, kurie ateidavo ir nueidavo nuo šventųjų vietos, ir buvo pamiršti mieste, kuriame taip darė; tai irgi tuštybė.'),
  (@b21, 8, 11, 'Kadangi nuosprendis už pikta darbą ne tuojau įvykdomas, todėl žmonių sūnų širdys juose yra pilnai nukreiptos daryti pikta.'),
  (@b21, 8, 12, 'Nors nusidėjėlis šimtąkart daro pikta ir jo dienos prailgintos, tačiau aš tikrai žinau, kad gerai bus Dievo bijantiems, kurie bijo jo akivaizdoje;'),
  (@b21, 8, 13, 'bet nedorėliui nebus gerai, ir jis neprailgins savo dienų, kurios yra kaip šešėlis; nes jis nebijo Dievo akivaizdoje.'),
  (@b21, 8, 14, 'Yra tuštybė, kuri vyksta žemėje: kad yra teisiųjų, kuriems atsitinka pagal nedorėlių darbą; vėlgi, yra nedorėlių, kuriems atsitinka pagal teisiųjų darbą; aš sakiau, kad tai irgi tuštybė.'),
  (@b21, 8, 15, 'Tada aš gyriau linksmybę, nes žmogui po saule nieko nėra geriau, kaip tik valgyti, gerti ir būti linksmam; nes tai pasiliks su juo nuo jo triūso per jo gyvenimo dienas, kurias Dievas jam duoda po saule.'),
  (@b21, 8, 16, 'Kai pakreipiau savo širdį pažinti išmintį ir apžvelgti reikalus, vykstančius žemėje (nes yra kas nei dieną, nei naktį nemato miego savo akimis);'),
  (@b21, 8, 17, 'tada pamačiau visą Dievo darbą, kad žmogus negali išsiaiškinti darbo, kuris vyksta po saule; nes, nors žmogus ir triūsia, kad jį suieškotų, tačiau jis jo nesuras; ir be to, nors išmintingas galvoja jį pažįstąs, tačiau jis negali jo surasti.'),
  (@b21, 9, 1, 'Dėl viso to apsvarsčiau savo širdyje visa tai pareikšti, kad teisieji bei išmintingieji ir jų darbai yra Dievo rankoje; žmogus nežino nei meilės, nei neapykantos iš viso to, kas yra jo akivaizdoje.'),
  (@b21, 9, 2, 'Visi dalykai ateina visiems vienodai; vienodai atsitinka teisiajam ir nedorėliui; gerajam, švariajam ir nešvariajam; aukojančiam ir neaukojančiam; kaip gerajam, taip ir nusidėjėliui; kaip prisiekiančiam, taip ir bijančiam priesaikos.'),
  (@b21, 9, 3, 'Tai yra blogybė tarp visų dalykų, vykstančių po saule, kad visiems vienodai nutinka; taip, ir žmonių sūnų širdis yra pilna pikto, ir beprotybė yra jų širdyje, kol jie gyvena, o po to jie eina pas mirusiuosius.'),
  (@b21, 9, 4, 'Nes tam, kuris susijungęs su visais gyvaisiais, yra vilties; nes gyvas šuo geriau už negyvą liūtą.'),
  (@b21, 9, 5, 'Nes gyvieji žino, kad mirs; bet mirusieji nieko nežino, nei jiems nebėra atlyginimo; nes pamirštas jų atminimas.'),
  (@b21, 9, 6, 'Taip pat jų meilė, jų neapykanta ir jų pavydas jau išnykę; ir jie per amžius nebeturi dalies jokiame dalyke, kuris vyksta po saule.'),
  (@b21, 9, 7, 'Eik savo keliu, valgyk su džiaugsmu savo duoną ir linksma širdimi gerk savo vyną; nes Dievas dabar priima tavo darbus.'),
  (@b21, 9, 8, 'Tebūna tavo drabužiai visados balti; ir tenetrūksta tavo galvai tepalo.'),
  (@b21, 9, 9, 'Gyvenk džiaugsmingai su žmona, kurią myli, per visas savo tuštybės gyvenimo dienas, kurias jis tau davė po saule, per visas tavo tuštybės dienas; nes tai yra tavo dalis šiame gyvenime ir tavo triūse, kurio imiesi po saule.'),
  (@b21, 9, 10, 'Ką tik tavo ranka aptinka nuveikti, daryk tai savo jėga; nes nėra nei darbo, nei planų, nei pažinimo, nei išminties kape, į kurį tu eini.'),
  (@b21, 9, 11, 'Aš atsigręžiau ir mačiau po saule, kad bėgimas ne greitiesiems, nei mūšis stipriesiems, nei duona išmintingiesiems, nei turtai turintiems supratimą, nei palankumas sumaniesiems; bet laikas ir atsitiktinumas atsitinka jiems visiems.'),
  (@b21, 9, 12, 'Nes žmogus nežino savo laiko; kaip žuvys, sugaunamos piktu tinklu, ir kaip paukščiai, sugaunami žabangomis; taip ir žmonių sūnūs įsipainioja piktame laike, kai jis staiga juos užpuola.'),
  (@b21, 9, 13, 'Mačiau ir šią išmintį po saule, ir ji man atrodė didelė:'),
  (@b21, 9, 14, 'buvo nedidelis miestas ir nedaug žmonių jame; ir prieš jį atėjo didis karalius, apgulė jį ir pastatė prieš jį didelius pylimus;'),
  (@b21, 9, 15, 'na, o atsirado jame neturtingas, išmintingas žmogus ir savo išmintimi išvadavo miestą; tačiau joks žmogus neprisiminė to beturčio žmogaus.'),
  (@b21, 9, 16, 'Tada aš tariau: „Išmintis geriau už jėgą“; tačiau vargšo išmintis paniekinama, ir jo žodžių nesigirdi.'),
  (@b21, 9, 17, 'Išmintingųjų žodžiai tyloje išgirstami labiau nei šauksmas to, kuris valdo tarp kvailių.'),
  (@b21, 9, 18, 'Išmintis geriau negu karo ginklai; bet vienas nusidėjėlis sunaikina daug gero.'),
  (@b21, 10, 1, 'Negyvos musės padaro, kad vaistininkų tepalas skleistų dvokiantį kvapą; taip ir maža kvailybė padaro tam, kuris pagarsėjęs išmintimi ir garbe.'),
  (@b21, 10, 2, 'Išmintingojo širdis yra jo dešinėje; bet kvailio širdis jo kairėje.'),
  (@b21, 10, 3, 'Taip pat, kai kvailys eina keliu, jam trūksta išminties, ir jis kiekvienam sako, kad jis kvailys.'),
  (@b21, 10, 4, 'Jei valdovo dvasia pakyla prieš tave, nepalik savo vietos; nes nusileidimas numalšina didelius nusižengimus.'),
  (@b21, 10, 5, 'Yra blogybė, kurią mačiau po saule, kaip klaida išeinanti iš valdovo:'),
  (@b21, 10, 6, 'kvailybė pastatyta didžioje garbėje, o turtingieji sėdi žemai.'),
  (@b21, 10, 7, 'Mačiau tarnus ant žirgų, o kunigaikščius vaikščiojančius žeme kaip tarnus.'),
  (@b21, 10, 8, 'Kas kasa duobę, į ją įkris; ir kas griauna tvorą, tam įgels gyvatė.'),
  (@b21, 10, 9, 'Kas išima akmenis, jais susižeis; ir kas skaldo malkas, jomis kelia sau grėsmę.'),
  (@b21, 10, 10, 'Jei geležis atšipusi ir jis negalanda ašmenų, tuomet jis turi įdėti daugiau jėgų; bet išmintis naudinga nukreipimui.'),
  (@b21, 10, 11, 'Tikrai gyvatė įgels be kerėjimo; ir plepys ne geresnis.'),
  (@b21, 10, 12, 'Išmintingojo burnos žodžiai maloningi; bet kvailio lūpos praryja jį patį.'),
  (@b21, 10, 13, 'Jo burnos žodžių pradžia – kvailystė; o jo kalbos pabaiga – kenksminga beprotybė.'),
  (@b21, 10, 14, 'Kvailys dar ir pilnas žodžių; žmogus negali pasakyti, kas bus; ir kas gali jam pasakyti, kas bus po jo?'),
  (@b21, 10, 15, 'Kvailių triūsas išsekina kiekvieną iš jų, nes jis nežino kaip nueiti į miestą.'),
  (@b21, 10, 16, 'Vargas tau, o šalie, kai tavo karalius yra vaikas, ir kai tavo kunigaikščiai valgo ryte!'),
  (@b21, 10, 17, 'Palaiminta esi, o šalie, kai tavo karalius yra kilmingųjų sūnus, ir kai tavo kunigaikščiai valgo tinkamu laiku, pasistiprinimui, o ne girtuokliavimui!'),
  (@b21, 10, 18, 'Per didelę tinginystę pastatas suyra; ir per rankų dykinėjimą pravarva namas.'),
  (@b21, 10, 19, 'Puota ruošiama juokui, ir vynas pralinksmina; bet pinigai už viską atsako.'),
  (@b21, 10, 20, 'Net mintyse nekeik karaliaus; ir savo miegamajame nekeik turtuolio; nes oro paukštis nuneš balsą ir turintis sparnus papasakos tą dalyką.'),
  (@b21, 11, 1, 'Mesk savo duoną ant vandens; nes tu ją rasi po daugelio dienų.'),
  (@b21, 11, 2, 'Duok dalį septyniems ir aštuoniems; nes nežinai, kokia nelaimė bus žemėje.'),
  (@b21, 11, 3, 'Jei debesys pilni lietaus, jie išsilieja ant žemės; ir jei medis krinta link pietų ar link šiaurės, ten, kur medis krinta, toje vietoje jis ir bus.'),
  (@b21, 11, 4, 'Kas seka vėją, nesės; ir kas atsižvelgia į debesis, nepjaus.'),
  (@b21, 11, 5, 'Kaip nežinai, koks yra dvasios kelias ir kaip auga kaulai nėščiosios įsčiose, taip nežinai ir darbų Dievo, kuris viską daro.'),
  (@b21, 11, 6, 'Ryte sėk savo sėklą ir vakare nesulaikyk savo rankos, nes nežinai ar šita, ar ana užderės, ar abi bus vienodai geros.'),
  (@b21, 11, 7, 'Tikrai šviesa yra miela, ir malonu akims matyti saulę;'),
  (@b21, 11, 8, 'bet jei ir daug metų žmogus gyventų ir džiaugtųsi jais visais, tačiau tegul prisimena tamsias dienas, nes jų bus daug. Visa, kas ateina, yra tuštybė.'),
  (@b21, 11, 9, 'Džiaukis, jaunuoli, savo jaunystėje; ir tavo širdis tave tedžiugina tavo jaunystės dienomis, ir vaikščiok savo širdies keliais ir savo akių regėjimu; tačiau žinok, kad už visa tai Dievas atves tave į teismą.'),
  (@b21, 11, 10, 'Todėl pašalink liūdesį iš savo širdies ir atitolink pikta nuo savo kūno, nes vaikystė ir jaunystė yra tuštybė.'),
  (@b21, 12, 1, 'Atsimink savo Sutvėrėją savo jaunystės dienomis, kol dar neatėjo piktosios dienos ir neprisiartino metai, kai tu sakysi: „Neturiu jose pasitenkinimo“;'),
  (@b21, 12, 2, 'kol dar neaptemo saulė ar šviesa, ar mėnulis, ar žvaigždės ir debesys nesugrįžo po lietaus;'),
  (@b21, 12, 3, 'tą dieną, kai drebės namų sargai ir stipruoliai susilenks, ir malėjai liausis, nes jų mažai, ir kurie žiūri pro langus, aptems,'),
  (@b21, 12, 4, 'ir užsidarys durys gatvėse, kai malimo garsas susilpnės, ir jis atsikels nuo paukščio balso, ir vìsos muzikos dukterys bus nužemintos;'),
  (@b21, 12, 5, 'taipogi, kai jie bijos aukštumos, ir baimės bus kelyje, ir migdolo medis žydės, ir žiogas bus našta, ir noras pradings; nes žmogus eina į savo ilgalaikius namus, ir raudotojai vaikštinėja po gatves;'),
  (@b21, 12, 6, 'arba kol dar neatsirišo sidabrinė virvė ar nesudužo auksinis dubuo, ar ąsotis nesudužo prie šaltinio, ar nesulūžo ratas prie rezervuaro.'),
  (@b21, 12, 7, 'Tada dulkės sugrįš į žemę, kaip buvo; o dvasia sugrįš pas Dievą, kuris ją davė.'),
  (@b21, 12, 8, 'Tuštybių tuštybė, – sako pamokslininkas; viskas yra tuštybė.'),
  (@b21, 12, 9, 'Ir be to, kadangi pamokslininkas buvo išmintingas, jis vis mokė tautą pažinimo; taip, jis kreipė didelį dėmesį ir suieškojo, ir sudėliojo daug patarlių.'),
  (@b21, 12, 10, 'Pamokslininkas ieškojo, kad surastų priimtinų žodžių; ir, kas buvo surašyta, buvo tiesu, būtent tiesos žodžiai.'),
  (@b21, 12, 11, 'Išmintingųjų žodžiai yra kaip badikliai ir kaip susirinkimų valdovų įkaltos vinys, kurie yra duoti nuo vieno ganytojo.'),
  (@b21, 12, 12, 'Ir toliau, mano sūnau, per šituos būk įspėtas; daugybės knygų sudarymui nėra galo; o daug studijavimo nuvargina kūną.'),
  (@b21, 12, 13, 'Pasiklausykime viso dalyko išvados: bijok Dievo ir laikykis jo įsakymų, nes tai visa žmogaus pareiga.'),
  (@b21, 12, 14, 'Nes Dievas atves į teismą kiekvieną darbą su kiekvienu paslėptu dalyku, ar jis būtų geras, ar blogas.'),
  (@b22, 1, 1, 'Giesmių giesmė, kuri yra Saliamono.'),
  (@b22, 1, 2, 'Tegul jis mane bučiuoja savo burnos bučiniais; nes tavo meilė geresnė už vyną.'),
  (@b22, 1, 3, 'Dėl tavo gerų tepalų kvapo tavo vardas yra kaip išlietas tepalas, todėl mergelės myli tave.'),
  (@b22, 1, 4, 'Trauk mane artyn, mes bėgsime paskui tave; karalius mane atvedė į savo kambarius; mes linksminsimės ir džiaugsimės tavimi, mes prisiminsime tavo meilę labiau už vyną; tiesieji myli tave.'),
  (@b22, 1, 5, 'Aš juoda, bet graži, o jūs, Jeruzalės dukterys, kaip Kedaro palapinės, kaip Saliamono uždangos.'),
  (@b22, 1, 6, 'Nežiūrėkite į mane, kad aš juoda, nes saulė žiūrėjo į mane; mano motinos vaikai supyko ant manęs; jie mane paskyrė vynuogynų saugotoja; bet savojo vynuogyno aš nesaugojau.'),
  (@b22, 1, 7, 'Pasakyk man tu, kurį myli mano siela, kur ganai, kur vidurdienį pailsini savo kaimenę; nes kodėl turėčiau būti kaip ta, kuri pasuka į šoną prie tavo draugų kaimenių?'),
  (@b22, 1, 8, 'Jei tu nežinai, o gražiausioji tarp moterų, išeik kaimenės pėdsakais ir ganyk savo ožiukus prie piemenų palapinių.'),
  (@b22, 1, 9, 'O mano meile, aš tave palyginau su žirgų būriu faraono vežimuose.'),
  (@b22, 1, 10, 'Tavo skruostai gražūs su brangenybių eilėmis, tavo kaklas su aukso grandinėlėmis.'),
  (@b22, 1, 11, 'Tau padarysime auksinių apsiuvų su sidabriniais blizgučiais.'),
  (@b22, 1, 12, 'Karaliui sėdint prie savo stalo, mano nardas skleidžia savo kvapą.'),
  (@b22, 1, 13, 'Mano karštai mylimas man yra kaip miros ryšulėlis; jis gulės visą naktį tarp mano krūtų.'),
  (@b22, 1, 14, 'Mano mylimasis man yra kaip kamparo kekė En-Gedžio vynuogynuose.'),
  (@b22, 1, 15, 'Štai tu esi graži, mano meile; štai tu esi graži; tu turi karvelio akis.'),
  (@b22, 1, 16, 'Štai tu esi gražus, mano mylimasis, tikrai mielas; ir mūsų guolis žalias.'),
  (@b22, 1, 17, 'Mūsų namų sijos – kedrai, ir mūsų gegnės iš eglės.'),
  (@b22, 2, 1, 'Aš esu Šarono rožė ir slėnių lelija.'),
  (@b22, 2, 2, 'Kaip lelija tarp erškėčių, taip ir mano meilė tarp dukterų.'),
  (@b22, 2, 3, 'Kaip obelis tarp miško medžių, taip ir mano mylimasis tarp sūnų. Aš sėdėjau jo šešėlyje su didžiu pasigėrėjimu, ir jo vaisius buvo saldus mano skoniui.'),
  (@b22, 2, 4, 'Jis atvedė mane į puotos namus, ir jo vėliava virš manęs buvo meilė.'),
  (@b22, 2, 5, 'Pastiprinkite mane ąsočiais, atgaivinkite mane obuoliais; nes aš sergu iš meilės.'),
  (@b22, 2, 6, 'Jo kairė ranka yra po mano galva, o jo dešinė apkabina mane.'),
  (@b22, 2, 7, 'Aš įpareigoju jus, o Jeruzalės dukterys, stirnomis ir lauko elnėmis, kad jūs nežadintumėte ir nekeltumėte mano meilės, kol nepanorės.'),
  (@b22, 2, 8, 'Mano mylimojo balsas! Štai jis ateina, šuoliuodamas per kalnus, šokinėdamas per kalvas.'),
  (@b22, 2, 9, 'Mano mylimasis yra lyg stirna ar jaunas elnias; štai jis stovi už mūsų sienos, jis žiūri prie langų, pasirodydamas pro groteles.'),
  (@b22, 2, 10, 'Mano mylimasis kalbėjo ir man tarė: „Kelkis, mano meile, mano gražuole, ir išeik.'),
  (@b22, 2, 11, 'Nes štai žiema jau praėjo, lietus nustojo ir nuėjo;'),
  (@b22, 2, 12, 'gėlės pasirodo žemėje; atėjo paukščių čiulbėjimo metas, ir purplelio balsas girdimas mūsų šalyje;'),
  (@b22, 2, 13, 'figmedis išleido savo žalias figas, ir vynmedžiai su gležnomis vynuogėmis skleidžia gerą kvapą. Kelkis, mano meile, mano gražuole, ir išeik.'),
  (@b22, 2, 14, 'O mano balandėle, esanti uolos plyšiuose, laiptų slaptavietėse, leisk man pamatyti tavo veidą, leisk man išgirsti tavo balsą; nes tavo balsas malonus ir tavo veidas gražus.'),
  (@b22, 2, 15, 'Sugaukite mums lapes, mažas lapes, kurios gadina vynmedžius; nes mūsų vynmedžiai turi gležnas vynuoges.'),
  (@b22, 2, 16, 'Mano mylimasis yra mano, o aš esu jo; jis gano tarp lelijų.'),
  (@b22, 2, 17, 'Kol išauš diena ir nubėgs šešėliai, atsisuk, mano mylimasai, ir būk kaip stirna ar jaunas elnias ant Beterio kalnų.'),
  (@b22, 3, 1, 'Naktį savo lovoje ieškojau to, kurį myli mano siela; jo ieškojau, bet neradau.'),
  (@b22, 3, 2, 'Dabar kelsiuosi ir vaikštinėsiu aplink miestą, po gatves, ir plačiuose keliuose ieškosiu to, kurį myli mano siela; jo ieškojau, bet neradau.'),
  (@b22, 3, 3, 'Mane aptiko sargai, vaikščiojantys aplink miestą, kuriems tariau: „Ar matėte tą, kurį myli mano siela?“'),
  (@b22, 3, 4, 'Tik truputį nuo jų paėjusi suradau tą, kurį myli mano siela; jį nutvėriau ir nepaleidau jo, kol neatvedžiau jo į savo motinos namus, į savo gimdytojos kambarį.'),
  (@b22, 3, 5, 'Aš įpareigoju jus, o Jeruzalės dukterys, stirnomis ir lauko elnėmis, kad jūs nežadintumėte ir nekeltumėte mano meilės, kol nepanorės.'),
  (@b22, 3, 6, 'Kas yra tas, kuris ateina iš dykumos kaip dūmų stulpai, iškvėpintas mira ir smilkalais, visokiais pirklio milteliais?'),
  (@b22, 3, 7, 'Štai jo lova, kuri yra Saliamono; šešiasdešimt narsių vyrų yra aplink ją – iš Izraelio narsuolių.'),
  (@b22, 3, 8, 'Jie visi laiko kalavijus, prityrę kare; kiekvienas turi savo kalaviją prie savo šlaunies dėl baimės naktį.'),
  (@b22, 3, 9, 'Karalius Saliamonas padarė sau vežimą iš Libano medžių.'),
  (@b22, 3, 10, 'Jis padarė jo stulpus iš sidabro, jo dugną iš aukso, jo dangą iš purpuro, jo vidus buvo išklotas meile, – dėl Jeruzalės dukterų.'),
  (@b22, 3, 11, 'Išeikite, Siono dukterys, ir pažvelkite į karalių Saliamoną su karūna, kuria jo motina jį karūnavo jo vestuvių dieną ir jo širdies linksmybės dieną.'),
  (@b22, 4, 1, 'Štai tu esi graži, mano meile; štai tu esi graži; tu tarp savo garbanų turi balandėlės akis; tavo plaukai kaip kaimenė ožkų, kurios pasirodo nuo Gileado kalno.'),
  (@b22, 4, 2, 'Tavo dantys kaip kaimenė lygiai nukirptų avių, kurios atėjo aukštyn iš maudyklės; kurių kiekviena veda dvynukus, ir tarp jų nei vienos nėra bergždžios.'),
  (@b22, 4, 3, 'Tavo lūpos kaip skaisčiai raudonas siūlas, ir tavo kalba miela; kaip granato skiltis tavo smilkiniai tarp tavo garbanų.'),
  (@b22, 4, 4, 'Tavo kaklas kaip Dovydo bokštas, pastatytas ginklų sandėliui, ant kurio kabo tūkstantis mažųjų skydų, visi galiūnų skydai.'),
  (@b22, 4, 5, 'Tavo abi krūtys kaip dvi jaunos stirnos, dvynukės, besiganančios tarp lelijų.'),
  (@b22, 4, 6, 'Kol išauš diena ir nubėgs šešėliai, aš eisiu į miros kalną ir į smilkalų kalvą.'),
  (@b22, 4, 7, 'Tu visa graži, mano meile; nėra tavyje dėmės.'),
  (@b22, 4, 8, 'Ateik su manimi iš Libano, mano sutuoktine, su manimi iš Libano; žiūrėk nuo Amanos viršūnės, nuo Šenyro ir Hermono viršūnės, nuo liūtų urvų, nuo leopardų kalnų.'),
  (@b22, 4, 9, 'Tu sužavėjai mano širdį, mano sese, mano sutuoktine; tu sužavėjai mano širdį viena iš savo akių, viena savo kaklo grandinėle.'),
  (@b22, 4, 10, 'Kokia graži tavo meilė, mano sese, mano sutuoktine! Tavo meilė daug geresnė už vyną ir tavo tepalų kvapas už visus kvapus!'),
  (@b22, 4, 11, 'O mano sutuoktine, tavo lūpos varva kaip medaus korys; medus ir pienas yra po tavo liežuviu; ir tavo drabužių kvapas yra kaip Libano kvapas.'),
  (@b22, 4, 12, 'Mano sesuo, mano sutuoktinė, yra uždaras sodas, užrakinta versmė, užantspauduotas šaltinis.'),
  (@b22, 4, 13, 'Tavo sodinukai – granatmedžių sodas su mielais vaisiais: kamparas su nardu,'),
  (@b22, 4, 14, 'nardas ir šafranas, ajeras ir cinamonas su visais smilkalų medžiais: mira ir alavijas su visais pagrindiniais kvapais;'),
  (@b22, 4, 15, 'sodų šaltinis, gyvų vandenų šulinys ir upeliai iš Libano.'),
  (@b22, 4, 16, 'Atsibusk, o šiaurės vėjau, ir ateik, piety; pūsk į mano sodą, kad pasklistų jo kvapai. Tegul mano mylimasis ateina į savo sodą ir valgo savo mielų vaisių.'),
  (@b22, 5, 1, 'Aš atėjau į savo sodą, mano sese, mano sutuoktine; rinkau savo mirą su savo kvapais; valgiau savo korį su savo medumi; gėriau savo vyną su savo pienu; valgykite, draugai; gerkite, taip, gausiai gerkite, mylimieji.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b22, 5, 2, 'Aš miegu, bet mano širdis būdrauja; tai mano mylimojo balsas beldžiasi, sakydamas: „Atidaryk man, mano sese, mano meile, mano balandėle, mano nesuterštoji; nes mano galva pripildyta rasos, mano garbanos – nakties lašų“.'),
  (@b22, 5, 3, 'Aš nusivilkau savo apsiaustą; kaip jį apsivilksiu? Nusiploviau savo kojas; kaip jas suteršiu?'),
  (@b22, 5, 4, 'Mano mylimasis įkišo ranką pro durų angą, ir mano viduriai sujudo dėl jo.'),
  (@b22, 5, 5, 'Aš atsikėliau atidaryti savo mylimajam; o mano rankos varvėjo mira, mano pirštai gardžiai kvepiančia mira ant spynos rankenų.'),
  (@b22, 5, 6, 'Aš atidariau savo mylimajam; bet mano mylimasis buvo pasitraukęs ir nuėjęs; mano siela alpo, kai jis kalbėjo; jo ieškojau, bet negalėjau rasti; jį šaukiau, bet jis man neatsiliepė.'),
  (@b22, 5, 7, 'Mane rado sargybiniai, einantys aplink miestą; jie mane mušė, jie mane sužeidė; sienų sargai atėmė iš manęs mano šydą.'),
  (@b22, 5, 8, 'Aš įpareigoju jus, Jeruzalės dukterys, jei rasite mano mylimąjį, kad jam sakytumėte, jog aš sergu meile.'),
  (@b22, 5, 9, 'Kuo tavo mylimasis geresnis už kitą mylimąjį, o gražiausioji tarp moterų? Kuo tavo mylimasis geresnis už kitą mylimąjį, kad tu mus taip įpareigoji?'),
  (@b22, 5, 10, 'Mano mylimasis yra baltas ir rausvas, viršiausias tarp dešimt tūkstančių.'),
  (@b22, 5, 11, 'Jo galva kaip geriausias auksas, jo garbanos tankios ir juodos kaip varnas.'),
  (@b22, 5, 12, 'Jo akys kaip balandėlio prie vandens upių, nuplautos piene ir tinkamai įstatytos.'),
  (@b22, 5, 13, 'Jo skruostai kaip kvapniųjų augalų lysvės, kaip kvepiančios gėlės; jo lūpos kaip lelijos, varvančios gardžiai kvepiančia mira.'),
  (@b22, 5, 14, 'Jo rankos kaip aukso žiedai, nusagstyti berilu; jo pilvas kaip šviesus dramblio kaulas, padengtas safyrais.'),
  (@b22, 5, 15, 'Jo kojos kaip marmuro stulpai, pastatyti ant geriausio aukso movų; jo išvaizda kaip Libanas, puikus kaip kedrai.'),
  (@b22, 5, 16, 'Jo burna labai saldi; taip, jis visas – žavingas. Tai mano mylimasis, tai mano draugas, o Jeruzalės dukterys.'),
  (@b22, 6, 1, 'Kur nuėjo tavo mylimasis, o gražiausioji tarp moterų? Kur pasuko tavo mylimasis, kad galėtume jo ieškoti su tavimi?'),
  (@b22, 6, 2, 'Mano mylimasis nuėjo žemyn į savo sodą, prie kvapniųjų augalų lysvių, ganyti soduose ir skinti lelijų.'),
  (@b22, 6, 3, 'Aš esu savo mylimojo, ir mano mylimasis yra mano; jis gano tarp lelijų.'),
  (@b22, 6, 4, 'Tu esi graži, o mano meile, kaip Tirca, miela kaip Jeruzalė, siaubinga kaip kariuomenė su vėliavomis.'),
  (@b22, 6, 5, 'Nukreipk savo akis nuo manęs, nes jos mane nugalėjo; tavo plaukai kaip kaimenė ožkų, pasirodančių nuo Gileado.'),
  (@b22, 6, 6, 'Tavo dantys kaip kaimenė avių, kurios eina aukštyn iš maudyklės; kurių kiekviena veda dvynukus, ir tarp jų nei vienos nėra bergždžios.'),
  (@b22, 6, 7, 'Kaip granato skiltis yra tavo smilkiniai tarp tavo garbanų.'),
  (@b22, 6, 8, 'Yra šešiasdešimt karalienių, aštuoniasdešimt sugulovių ir mergelių be skaičiaus.'),
  (@b22, 6, 9, 'Bet tik viena yra mano balandėlė, mano nesuterštoji; ji savo motinos vienintelė, ji savo gimdytojos rinktinė. Dukterys ją matė ir ją laimino; taip, karalienės ir sugulovės – ir jos ją gyrė.'),
  (@b22, 6, 10, 'Kas yra ta, kuri žvelgia į priekį kaip rytas, graži kaip mėnulis, šviesi kaip saulė ir siaubinga kaip kariuomenė su vėliavomis?'),
  (@b22, 6, 11, 'Aš nuėjau žemyn į riešutų sodą pasižiūrėti slėnio vaisių, pažiūrėti, ar vynmedis žydi, ar išsprogo granatmedžiai.'),
  (@b22, 6, 12, 'Aš nesusivokiau, kaip mano siela mane padarė kaip Aminadabo vežimus.'),
  (@b22, 6, 13, 'Sugrįžk, sugrįžk, o šulamiete! Sugrįžk, sugrįžk, kad pažiūrėtume į tave. Ką gi šulamietėje matysite? Tarsi dviejų kariuomenių būrį.'),
  (@b22, 7, 1, 'Kokios gražios tavo kojos su apavu, o kunigaikščio dukra! Tavo šlaunų sąnariai kaip brangenybės, sumanaus meistro rankų darbas.'),
  (@b22, 7, 2, 'Tavo bamba kaip apskrita taurė, kuriai nestinga gėrimo; tavo pilvas kaip kviečių krūva, apkaišyta lelijomis.'),
  (@b22, 7, 3, 'Tavo abi krūtys kaip dvi jaunos stirnos, dvynukės.'),
  (@b22, 7, 4, 'Tavo kaklas kaip dramblio kaulo bokštas; tavo akys kaip žuvies tvenkiniai Hešbone prie Bat-Rabimo vartų; tavo nosis kaip Libano bokštas, žiūrintis link Damasko.'),
  (@b22, 7, 5, 'Tavo galva ant tavęs kaip Karmelis, ir tavo galvos plaukai kaip purpuras; karalius sulaikytas galerijose.'),
  (@b22, 7, 6, 'Kokia graži ir kokia tu miela, o meile, pasigėrėjimui!'),
  (@b22, 7, 7, 'Šis tavo stotas prilygsta palmei, ir tavo krūtys vynuogių kekėms.'),
  (@b22, 7, 8, 'Sakiau: „Lipsiu į palmę, nusitversiu už jos šakų; ir tavo krūtys bus kaip vynmedžio kekės, ir tavo nosies kvapas kaip obuolių;'),
  (@b22, 7, 9, 'ir tavo gomurys kaip geriausias vynas mano mylimajam, maloniai nuslystantis, prakalbinantis miegančiųjų lūpas.'),
  (@b22, 7, 10, 'Aš esu savo mylimojo, ir jo noras nukreiptas į mane.'),
  (@b22, 7, 11, 'Eikš, mano mylimasis, išeikime į laukus; nakvokime kaimuose.'),
  (@b22, 7, 12, 'Anksti kilkime į vynuogynus; pažiūrėkime, ar vynmedis žydi, ar pasirodė gležnos vynuogės, ar išsprogę granatai; ten aš tau duosiu savo meiles.'),
  (@b22, 7, 13, 'Mandragorai skleidžia kvapą, ir prie mūsų vartų yra visokiausių mielų vaisių, naujų ir senų, kurių sukaupiau tau, o mano mylimasai.'),
  (@b22, 8, 1, 'O kad tu būtum kaip mano brolis, kuris žindo mano motinos krūtis! Tada, tave radusi lauke aš tave bučiuočiau; taip, aš nebūčiau paniekinta.'),
  (@b22, 8, 2, 'Tave vesčiau ir atgabenčiau į savo motinos namus, tu pamokytum mane; aš tave pagirdyčiau kvapniu vynu iš savo granatų sulčių.'),
  (@b22, 8, 3, 'Jo kairė ranka būtų po mano galva, o jo dešinė apkabintų mane.'),
  (@b22, 8, 4, 'Įpareigoju jus, o Jeruzalės dukterys, kad jūs nežadintumėte ir nekeltumėte mano meilės, kol nepanorės.'),
  (@b22, 8, 5, 'Kas yra ta, kuri ateina iš dykumos, pasirėmusi į savo mylimąjį? Po obelimi tave pakėliau; ten tave pagimdė tavo motina; ten tave pagimdė tavo gimdytoja.'),
  (@b22, 8, 6, 'Uždėk mane kaip antspaudą ant savo širdies, kaip antspaudą ant savo rankos; nes meilė stipri kaip mirtis; pavydas žiaurus kaip kapas; jos žarijos yra ugnies žarijos, turinčios karščiausią liepsną.'),
  (@b22, 8, 7, 'Daug vandenų negali užgesinti meilės, nei srovės jos negali paskandinti; jei žmogus duotų visą savo namų turtą už meilę, tai būtų visiškai paniekinta.'),
  (@b22, 8, 8, 'Mes turime mažą seserį, ir ji neturi krūtų; ką darysime savo seserei tą dieną, kai už ją bus kalbama?'),
  (@b22, 8, 9, 'Jei ji būtų siena, pastatytume ant jos sidabrinius rūmus; o jei ji būtų durys, mes ją aptvertume kedro lentomis.'),
  (@b22, 8, 10, 'Aš esu siena, ir mano krūtys kaip bokštai; tada jo akyse buvau kaip ta, kuri rado palankumą.'),
  (@b22, 8, 11, 'Saliamonas turėjo vynuogyną Baal-Hamone; jis išnuomojo vynuogyną sargams; už jo vaisius kiekvienas turėjo atnešti tūkstantį sidabrinių.'),
  (@b22, 8, 12, 'Mano vynuogynas, kuris yra mano, yra mano akivaizdoje; o Saliamonai, turėk tūkstantį, o saugojantieji jo vaisius – du šimtus.'),
  (@b22, 8, 13, 'Tu, kuri gyveni soduose, draugai klausosi tavo balso; leisk man jį išgirsti.'),
  (@b22, 8, 14, 'Skubėk, mano mylimasai, ir būk kaip stirna ar jaunas elnias ant kvapiųjų augalų kalnų.'),
  (@b23, 1, 1, 'Izaijo, Amoco sūnaus, regėjimas, kurį jis matė apie Judą ir Jeruzalę Judos karalių Uzijo, Jotamo, Ahazo ir Chezekijo dienomis.'),
  (@b23, 1, 2, 'Klausykitės, o dangūs, ir atverk ausį, o žeme, nes VIEŠPATS kalbėjo: „Aš maitinau ir užauginau vaikus, o jie sukilo prieš mane.'),
  (@b23, 1, 3, 'Jautis pažįsta savo savininką ir asilas savo valdovo ėdžias; bet Izraelis nepažįsta, mano tauta neapgalvoja“.'),
  (@b23, 1, 4, 'O nuodėminga tauta, nuo neteisybės apsunkusi liaudis, piktadarių sėkla, vaikai, kurie sugadina; jie paliko VIEŠPATĮ, jie kurstė Izraelio Šventojo pyktį, jie pasuko atgal.'),
  (@b23, 1, 5, 'Kodėl jūs daugiau beturėtumėte būti mušami? Jūs vis labiau ir labiau maištausite; visa galva nesveika ir visa širdis alpsta.'),
  (@b23, 1, 6, 'Nuo kojų padų iki galvos nieko sveiko nėra joje; tik žaizdos, mėlynės bei pūnančios opos; jos nei užsiūtos, nei apraišiotos, nei suminkštintos tepalu.'),
  (@b23, 1, 7, 'Jūsų kraštas ištuštėjęs, jūsų miestai sudeginti ugnimi; jūsų šalį svetimieji ryja jūsų akivaizdoje, ir ji ištuštėjusi, kaip sunaikinta svetimųjų.'),
  (@b23, 1, 8, 'Ir Siono duktė palikta kaip lūšnelė vynuogyne, kaip sarginė agurkyne, kaip apgultas miestas.'),
  (@b23, 1, 9, 'Jei kariuomenių VIEŠPATS nebūtų mums palikęs labai mažo likučio, mes būtume buvę kaip Sodoma, mes būtume panašūs į Gomorą.'),
  (@b23, 1, 10, 'Klausykitės VIEŠPATIES žodžio, jūs, Sodomos valdovai; atverkite ausį mūsų Dievo įstatymui, jūs, Gomoros tauta.'),
  (@b23, 1, 11, '„Kam man jūsų aukų daugybė? – sako VIEŠPATS, – aš sotus avinų deginamosiomis atnašomis ir peniukšlių taukais; aš nemėgstu jaučių ar avinėlių, ar ožių kraujo.'),
  (@b23, 1, 12, 'Kai ateinate pasirodyti mano akivaizdoje, kas reikalavo iš jūsų rankos, kad tryptumėte mano kiemus?'),
  (@b23, 1, 13, 'Nebeneškite tuščių aukų; smilkalai man yra pasibjaurėjimas; aš negaliu pakęsti jauno mėnulio ir sabatų, sueigų sušaukimo; netgi iškilmingas susirinkimas yra neteisybė.'),
  (@b23, 1, 14, 'Jūsų jauno mėnulio ir jūsų paskirtų švenčių mano siela nekenčia; jie man yra sunkumas: pavargau juos nešti.'),
  (@b23, 1, 15, 'Ir kai išskečiate savo rankas, aš paslepiu savo akis nuo jūsų; taip, kai atliekate daug maldų, aš nesiklausau: jūsų rankos pilnos kraujo.'),
  (@b23, 1, 16, 'Nusiplaukite, apsivalykite; pašalinkite savo darbų piktybę iš po mano akių; liaukitės darę pikta;'),
  (@b23, 1, 17, 'mokykitės daryti gera; ieškokite teismo, padėkite engiamiems, teisėjaukite našlaičiams, užtarkite našles.'),
  (@b23, 1, 18, 'Dabar ateikite, ir samprotaukime kartu, – sako VIEŠPATS, – nors jūsų nuodėmės būtų kaip skaisčiai raudona, jos bus baltos kaip sniegas; nors jos būtų raudonos kaip tamsiai raudona, jos bus kaip vilna.'),
  (@b23, 1, 19, 'Jei būsite noringi ir paklusnūs, jūs valgysite šalies gėrybes;'),
  (@b23, 1, 20, 'bet jei nesutiksite ir maištausite, būsite kalavijo praryti“; nes VIEŠPATIES burna tai kalbėjo.'),
  (@b23, 1, 21, 'Kaip ištikimas miestas tapo paleistuve! Jis buvo pilnas teismo; teisumas buvo apsigyvenęs jame, bet dabar – žmogžudžiai.'),
  (@b23, 1, 22, 'Tavo sidabras pavirto nuodegomis, tavo vynas sumaišytas su vandeniu;'),
  (@b23, 1, 23, 'tavo kunigaikščiai – maištininkai ir vagių draugai; visi mėgsta dovanas ir seka paskui apdovanojimus; jie neteisėjauja našlaičiams, ir našlės byla neateina iki jų.'),
  (@b23, 1, 24, 'Todėl sako Viešpats, kariuomenių VIEŠPATS, Izraelio Galingasis: „O, palengvinsiu save nuo savo priešininkų ir atkeršysiu savo priešams;'),
  (@b23, 1, 25, 'ir aš nukreipsiu savo ranką į tave ir visiškai išvalysiu tavo nuodegas ir pašalinsiu visą tavo alavą;'),
  (@b23, 1, 26, 'aš grąžinsiu tavo teisėjus, kaip pirma, ir tavo patarėjus, kaip pradžioje; paskui tave vadins: ‘Teisumo miestas, ištikimas miestas’.'),
  (@b23, 1, 27, 'Sionas bus atpirktas teismu, o jo atsivertėliai – teisumu.'),
  (@b23, 1, 28, 'Ir nusižengėliai bei nusidėjėliai pražus kartu, ir tie, kurie palieka VIEŠPATĮ, bus sunaikinti.'),
  (@b23, 1, 29, 'Nes jie gėdysis ąžuolų, kurių jūs troškote, ir jūs susigėsite dėl sodų, kuriuos esate išsirinkę.'),
  (@b23, 1, 30, 'Nes jūs būsite kaip ąžuolas, kurio lapai suvysta, ir kaip sodas, kuris neturi vandens.'),
  (@b23, 1, 31, 'Ir stiprusis bus kaip pakulos, o jų darytojas kaip kibirkštis, ir jie sudegs kartu, ir niekas jų neužgesins“.'),
  (@b23, 2, 1, 'Žodis, kurį matė Amoco sūnus Izaijas apie Judą ir Jeruzalę.'),
  (@b23, 2, 2, 'Ir paskutinėmis dienomis įvyks, kad VIEŠPATIES namų kalnas bus įtvirtintas kalnų viršūnėje ir bus išaukštintas virš kalvų; ir į jį plauks visos tautos.'),
  (@b23, 2, 3, 'Daug tautų eis ir sakys: „Ateikite, eikime aukštyn į VIEŠPATIES kalną, į Jokūbo Dievo namus; ir jis mus mokys savo kelių ir mes vaikščiosime jo takais“; nes iš Siono išeis įstatymas, VIEŠPATIES žodis – iš Jeruzalės.'),
  (@b23, 2, 4, 'Ir jis teis tautybių tarpe ir bars daugelį tautų; ir jie perkals savo kalavijus į noragus ir savo ietis į genėjimo peilius: tauta nekels kalavijo prieš tautą, ir jos nesimokys kariauti.'),
  (@b23, 2, 5, 'O Jokūbo namai, ateikite, ir vaikščiokime VIEŠPATIES šviesoje.'),
  (@b23, 2, 6, 'Todėl tu palikai savo tautą, Jokūbo namus, nes jie prisipildę iš rytų ir yra pranašautojai kaip filistinai, ir save patenkina svetimšalių vaikais.'),
  (@b23, 2, 7, 'Taip pat jų šalis pilna sidabro ir aukso, ir nėra jų turtams galo; jų šalis taipogi pilna žirgų, ir nėra galo jų vežimams;'),
  (@b23, 2, 8, 'jų šalis taip pat pilna stabų; jie garbina savo rankų darbą, tai, ką padarė jų pačių pirštai;'),
  (@b23, 2, 9, 'ir prastas žmogus nusilenkia, ir didis žmogus nusižemina; todėl neatleisk jiems.'),
  (@b23, 2, 10, 'Įeik į uolą ir pasislėpk dulkėse dėl VIEŠPATIES baimės ir dėl jo didybės šlovės.'),
  (@b23, 2, 11, 'Išdidūs žmonių žvilgsniai bus nužeminti, ir žmonių puikybė bus palenkta, ir tik vienas VIEŠPATS bus išaukštintas tą dieną.'),
  (@b23, 2, 12, 'Nes kariuomenių VIEŠPATIES diena bus ant kiekvieno, kuris išdidus ir išpuikęs, ir ant kiekvieno išsiaukštinusio; ir jis bus pažemintas;'),
  (@b23, 2, 13, 'ir ant visų Libano kedrų, aukštų ir išsiaukštinusių, ir ant visų Bašano ąžuolų,'),
  (@b23, 2, 14, 'ir ant visų aukštųjų kalnų, ir ant visų išsiaukštinusių kalvų,'),
  (@b23, 2, 15, 'ir ant kiekvieno aukšto bokšto, ir ant kiekvienos aptvertos sienos,'),
  (@b23, 2, 16, 'ir ant visų Taršišo laivų, ir ant visų geistinų paveikslų.'),
  (@b23, 2, 17, 'Ir žmogaus išpuikimas bus palenktas, ir žmonių išdidumas bus pažemintas; ir tik vienas VIEŠPATS bus išaukštintas tą dieną.'),
  (@b23, 2, 18, 'Ir stabus jis visiškai panaikins.'),
  (@b23, 2, 19, 'Ir jie eis į uolų angas ir į žemės urvus dėl VIEŠPATIES baimės ir dėl jo didybės šlovės, kai jis pakils baisingai sudrebinti žemės.'),
  (@b23, 2, 20, 'Tą dieną žmogus numes savo sidabro stabus ir savo aukso stabus, kurių kiekvieną jis buvo pasidaręs garbinimui, kurmiams ir šikšnosparniams;'),
  (@b23, 2, 21, 'kad eitų į uolų plyšius ir ant suplyšusių uolų viršūnių dėl VIEŠPATIES baimės ir dėl jo didybės šlovės, kai jis pakils baisingai sudrebinti žemės.'),
  (@b23, 2, 22, 'Atsitraukite nuo žmogaus, kurio kvapas yra jo šnervėse; nes kuo jis laikomas?'),
  (@b23, 3, 1, 'Nes štai Viešpats, kariuomenių VIEŠPATS, atims iš Jeruzalės ir iš Judos ramstį ir lazdą: visą duonos ramstį ir visą vandens ramstį,'),
  (@b23, 3, 2, 'galiūną ir karo vyrą, teisėją ir pranašą, protingąjį ir senolį,'),
  (@b23, 3, 3, 'penkiasdešimtininką, garbingą žmogų, patarėją, sumanų amatininką ir iškalbingą kalbėtoją.'),
  (@b23, 3, 4, 'Ir aš duosiu vaikus, kad būtų jų kunigaikščiai, ir juos valdys kūdikiai.'),
  (@b23, 3, 5, 'Ir tautoje bus vieni kitų engiami, kiekvienas savo artimo; vaikas išdidžiai elgsis su senoliu, o prastuolis su gerbiamu.'),
  (@b23, 3, 6, 'Kai žmogus nutvers savo brolį iš savo tėvo namų, sakydamas: „Tu turi drabužį, būk mūsų valdovu, ir šitie griuvėsiai tebūna po tavo ranka“;'),
  (@b23, 3, 7, 'tą dieną jis prisieks, sakydamas: „Aš nebūsiu gydytojas; nes mano namuose nėra nei duonos, nei drabužio; nedarykite manęs tautos valdovu“.'),
  (@b23, 3, 8, 'Nes Jeruzalė sugriauta ir Juda kritusi; nes jų liežuvis ir jų darbai yra prieš VIEŠPATĮ, kad erzintų jo šlovės akis.'),
  (@b23, 3, 9, 'Jų veido išraiška liudija prieš juos; ir savo nuodėmę jie skelbia kaip Sodoma, jie neslepia jos. Vargas jų sieloms! Nes jie patys sau atlygino piktu.'),
  (@b23, 3, 10, 'Sakykite teisiesiems, kad jiems bus gerai; nes jie valgys savo darbų vaisių.'),
  (@b23, 3, 11, 'Vargas nedorėliui! Jam bus blogai; nes jam bus duotas jo rankų atlygis.'),
  (@b23, 3, 12, 'O mano tautą, vaikai juos engia ir moterys juos valdo. O mano tauta, tie, kurie tave veda, verčia tave klysti ir naikina tavo takų kelią.'),
  (@b23, 3, 13, 'VIEŠPATS stojasi bylinėtis ir stojasi teisti tautą.'),
  (@b23, 3, 14, 'VIEŠPATS įeis į teismą su savo tautos senoliais ir jos kunigaikščiais: nes jūs suvalgėte vynuogyną; iš beturčių grobis jūsų namuose.'),
  (@b23, 3, 15, '„Ką galvojate, sutrupindami mano tautą ir sumaldami beturčių veidus?“ – sako Viešpats, kariuomenių DIEVAS.'),
  (@b23, 3, 16, 'VIEŠPATS dar sako: „Kadangi Siono dukterys išpuikusios ir vaikšto ištiestais kaklais bei ištvirkusiomis akimis, vaikšto ir eidamos tipena, ir savo kojomis žvangina;'),
  (@b23, 3, 17, 'todėl Viešpats ištiks Siono dukterų viršugalvius šašlige, ir VIEŠPATS atidengs jų slaptas vietas.'),
  (@b23, 3, 18, 'Tą dieną Viešpats atims puikumą jų žvangančių papuošalų aplink jų pėdas, jų galvos tinklelius ir apvalius kaip mėnuliukus jų papuošalus,'),
  (@b23, 3, 19, 'grandinėles, apyrankes, nuometus,'),
  (@b23, 3, 20, 'kepuraites, kojų papuošalus, galvos raiščius, dėžutes ir auskarus,'),
  (@b23, 3, 21, 'žiedus ir nosies brangenybes,'),
  (@b23, 3, 22, 'skirtingas drabužių eilutes, mantijas, galvos apdangalus, plaukų suktukus,'),
  (@b23, 3, 23, 'veidrodėlius, ploną liną, gobtuvus ir šydus.'),
  (@b23, 3, 24, 'Ir atsitiks, kad vietoje gardaus kvapo bus smarvė; vietoje juostos – įplyšimas; vietoje dailios šukuosenos – plikė; vietoje korsažo – ašutinis apjuostis; vietoje grožio – apdeginimas.'),
  (@b23, 3, 25, 'Tavo vyrai kris nuo kalavijo ir tavo galiūnai kare.'),
  (@b23, 3, 26, 'Ir jos vartai raudos ir gedės; ir apleista ji sėdės ant žemės.'),
  (@b23, 4, 1, 'Ir tą dieną septynios moterys nutvers vieną vyrą, sakydamos: „Mes valgysime savo pačių duoną ir dėvėsime savo pačių drabužį; tik leisk mums vadintis tavo vardu, kad mūsų gėda būtų nuimta“.'),
  (@b23, 4, 2, 'Tą dieną VIEŠPATIES Atžala bus graži ir šlovinga, o žemės vaisius bus puikus ir gražus Izraelio pabėgusiems.'),
  (@b23, 4, 3, 'Ir įvyks, kad kas išliks Sione ir kas pasiliks Jeruzalėje, bus vadinamas šventu, tai yra kiekvienas, užrašytas tarp gyvenančiųjų Jeruzalėje;'),
  (@b23, 4, 4, 'kai Viešpats bus nuplovęs Siono dukterų nešvarumus ir išvalęs Jeruzalės kraują iš jos tarpo teismo dvasia ir deginimo dvasia.'),
  (@b23, 4, 5, 'Ir ant kiekvienos gyvenamos Siono kalno vietos ir ant jo susirinkimų VIEŠPATS sutvers debesį ir dūmus dieną bei liepsnojančios ugnies spindesį naktį; nes ant visos šlovės bus apsauga.'),
  (@b23, 4, 6, 'Ir bus padangtė priedangai dienos metu nuo kaitros ir prieglobsčio vietai bei prieglaudai nuo audros ir lietaus.'),
  (@b23, 5, 1, 'Nagi giedosiu savo karštai mylimam savo mylimojo giesmę apie jo vynuogyną. Mano karštai mylimas turėjo vynuogyną labai vaisingoje kalvoje;'),
  (@b23, 5, 2, 'jis jį aptvėrė, išrinko iš jo akmenis, apsodino jį rinktiniais vynmedžiais, jo viduryje pastatė bokštą ir padirbo jame vyno spaustuvą; ir jis tikėjosi, kad šis atneš vynuogių, bet jis atnešė laukinių vynuogių.'),
  (@b23, 5, 3, 'O dabar, Jeruzalės gyventojai ir Judos žmonės, meldžiu jus, teiskite tarp manęs ir mano vynuogyno.'),
  (@b23, 5, 4, 'Ką daugiau bebuvo galima padaryti mano vynuogynui, ko aš jame nepadariau? Kodėl, kai aš tikėjausi, kad jis duos vynuogių, jis davė laukinių vynuogių?'),
  (@b23, 5, 5, 'O dabar aš jums pasakysiu, ką aš padarysiu savo vynuogynui: aš pašalinsiu jo tvorą, ir jis bus nuėstas; ir nugriausiu jo sieną, ir jis bus sumindytas;'),
  (@b23, 5, 6, 'ir jį paliksiu dyką: jo neapgenės nei apkas; bet ten sudygs erškėčiai bei usnys; taip pat debesims įsakysiu nelyti ant jo lietaus.'),
  (@b23, 5, 7, 'Nes kariuomenių VIEŠPATIES vynuogynas yra Izraelio namai, o Judos žmonės – jo mielas sodinys; ir jis tikėjosi teismo, bet štai – engimas; teisumo, bet štai – šauksmas.'),
  (@b23, 5, 8, 'Vargas tiems, kurie jungia namą prie namo, kurie lauką priduria prie lauko, kol nebelieka vietos, kad jie vieni būtų apgyvendinti žemės viduryje!'),
  (@b23, 5, 9, 'Man į ausis kariuomenių VIEŠPATS pasakė: „Iš tiesų daug namų, didelių ir gražių, bus tušti be gyventojų.'),
  (@b23, 5, 10, 'Taip, dešimt akrų vynuogyno duos vieną batą, o homeras sėklos duos efą.'),
  (@b23, 5, 11, 'Vargas tiems, kurie keliasi anksti ryte sekioti paskui stiprų gėrimą, kurie pasilieka iki nakties, kol vynas juos įkaitina!'),
  (@b23, 5, 12, 'Jų pokyliuose yra arfa, viola, būgneliai, dūda bei vynas; bet jie nepaiso VIEŠPATIES darbo ir nežiūri jo rankų veikimo.'),
  (@b23, 5, 13, 'Todėl mano tauta nuėjo į nelaisvę, kadangi jie neturi pažinimo; jų garbingieji badauja, ir jų minia išsekusi nuo troškulio.'),
  (@b23, 5, 14, 'Todėl pragaras išsiplėtė, be ribų atvėrė savo nasrus; ir į jį nužengs jų šlovė, jų minia, jų pasipūtimas ir džiūgautojai.'),
  (@b23, 5, 15, 'Ir prastas žmogus bus pažemintas, ir galingasis bus nužemintas, ir išdidžiųjų akys bus nužemintos;'),
  (@b23, 5, 16, 'bet kariuomenių VIEŠPATS bus išaukštintas teisme, ir Dievas, kuris yra šventas, bus pašvęstas teisume.'),
  (@b23, 5, 17, 'Tada avinėliai ganysis pagal savo įprotį, ir riebiųjų dykvietėmis svetimieji maitinsis.'),
  (@b23, 5, 18, 'Vargas tiems, kurie traukia neteisybę tuštybės virvėmis ir nuodėmę tarsi vežimo vadžiomis;'),
  (@b23, 5, 19, 'kurie sako: „Tepaskuba jis ir tepagreitina savo darbą, kad mes tai matytume; ir tepriartėja, ir teateina Izraelio Šventojo sumanymas, kad jį pažintume!“'),
  (@b23, 5, 20, 'Vargas tiems, kurie pikta vadina geru ir gera piktu, kurie tamsą palaiko šviesa ir šviesą tamsa, kurie kartų palaiko saldžiu ir saldų karčiu!'),
  (@b23, 5, 21, 'Vargas tiems, kurie išmintingi savo pačių akyse ir protingi savo pačių akivaizdoje!'),
  (@b23, 5, 22, 'Vargas tiems, kurie yra galingi vyną gerti ir stiprūs vyrai maišyti stiprius gėrimus;'),
  (@b23, 5, 23, 'kurie išteisina nedorėlį už atlygį ir iš teisiojo atima jo teisumą!'),
  (@b23, 5, 24, 'Todėl, kaip ugnis suryja ražienas ir liepsna praryja pelus, taip jų šaknis bus kaip puvėsiai ir jų žiedai pakils kaip dulkės; kadangi jie atmetė kariuomenių VIEŠPATIES įstatymą ir paniekino Izraelio Šventojo žodį.'),
  (@b23, 5, 25, 'Todėl VIEŠPATIES pyktis užsidegė prieš jo tautą, ir jis ištiesė prieš ją savo ranką ir ją sumušė; ir drebėjo kalvos, ir jų lavonai buvo sudraskyti gatvių viduryje. Dėl viso to nenusigręžė jo pyktis, bet jo ranka tebėra ištiesta.'),
  (@b23, 5, 26, 'Ir jis iškels vėliavą tolimoms tautoms ir joms sušvilps iš žemės pakraščio; ir štai jie skubiai, greitai ateis;'),
  (@b23, 5, 27, 'tarp jų nebus pavargusio nei suklumpančio; nei vienas nesnaus nei miegos; nei jų strėnų juosta atsiriš, nei jų apavo dirželis nutrūks;'),
  (@b23, 5, 28, 'jų strėlės aštrios ir visi jų lankai įtempti; jų žirgų kanopos laikomos titnagu, ir jų ratai – kaip viesulas;'),
  (@b23, 5, 29, 'jų riaumojimas kaip liūto, jie riaumos kaip jauni liūtai; taip, jie riaumos ir nusitvers grobį, ir saugiai jį nusineš, ir niekas jo neišgelbės.'),
  (@b23, 5, 30, 'Ir tą dieną jie riaumos prieš juos kaip jūros ūžimas; ir pažvelgus į šalį, štai tamsa, sielvartas, ir šviesa aptemusi jos danguose.'),
  (@b23, 6, 1, 'Tais metais, kai mirė karalius Uzijas, mačiau Viešpatį, sėdintį aukštame ir pakeltame soste, ir jo šleifas pripildė šventyklą.'),
  (@b23, 6, 2, 'Viršum jo stovėjo serafai; kiekvienas turėjo po šešis sparnus: dviem dengė savo veidą, dviem dengė savo kojas ir dviem skrido.'),
  (@b23, 6, 3, 'Ir vienas kitam šaukė, tardami: „Šventas, šventas, šventas kariuomenių VIEŠPATS; visa žemė pilna jo šlovės“.'),
  (@b23, 6, 4, 'Ir nuo šaukiančiųjų balso svyravo durų staktos, ir namai prisipildė dūmų.'),
  (@b23, 6, 5, 'Tada aš tariau: „Vargas man! Nes aš esu žuvęs; kadangi aš esu žmogus nešvariomis lūpomis ir gyvenu nešvarių lūpų tautos tarpe; nes mano akys matė Karalių, kariuomenių VIEŠPATĮ“.'),
  (@b23, 6, 6, 'Tada pas mane atskrido vienas iš serafų, turėdamas savo rankoje degančią anglį, kurią jis replėmis buvo paėmęs nuo aukuro;'),
  (@b23, 6, 7, 'ir jis uždėjo ją ant mano burnos ir tarė: „Štai ji palietė tavo lūpas; ir tavo neteisybė pašalinta, ir tavo nuodėmė apvalyta“.'),
  (@b23, 6, 8, 'Taip pat aš girdėjau Viešpaties balsą, sakantį: „Ką aš siųsiu, kas eis už mus?“ Tada aš pasakiau: „Štai aš; siųsk mane“.'),
  (@b23, 6, 9, 'Ir jis tarė: „Eik ir sakyk šitai tautai: ‘Jūs tikrai girdite, bet nesuprantate; ir jūs tikrai matote, bet nepastebite’.'),
  (@b23, 6, 10, 'Nutukink šitos tautos širdį, jų ausis apsunkink ir jų akis užmerk; kad jie nematytų akimis, negirdėtų ausimis, nesuprastų savo širdimis ir neatsiverstų, ir nebūtų pagydyti“.'),
  (@b23, 6, 11, 'Tada aš tariau: „Kiek ilgai, Viešpatie?“ Ir jis atsakė: „Kol miestai bus ištuštėję, be gyventojų, ir namai be žmonių, ir šalis bus visiškai tuščia,'),
  (@b23, 6, 12, 'ir VIEŠPATS bus perkėlęs žmones toli, ir bus didelis ištuštėjimas šalies viduje.'),
  (@b23, 6, 13, 'Tačiau joje bus dešimtadalis, ir jis sugrįš, ir bus ėdamas; kaip uosis ir kaip ąžuolas, kurių kamienas tebėra juose jiems numetus lapus; taip šventa sėkla bus jos kamienas“.'),
  (@b23, 7, 1, 'Ir Judos karaliaus Ahazo – Uzijo sūnaus, Jotamo sūnaus – dienomis įvyko, kad Sirijos karalius Recinas ir Izraelio karalius Pekachas, Remalijo sūnus, ėjo aukštyn į Jeruzalę, kad kariautų prieš ją, bet negalėjo jos įveikti.'),
  (@b23, 7, 2, 'Ir buvo pranešta Dovydo namams, sakant: „Sirija sudarė sąjungą su Efraimu“. Ir sudrebėjo jo širdis ir jo tautos širdis, kaip miško medžiai dreba nuo vėjo.'),
  (@b23, 7, 3, 'Tada VIEŠPATS tarė Izaijui: „Išeik Ahazo pasitikti, tu ir tavo sūnus Šear-Jašubas, prie aukštutinio tvenkinio vandentiekio galo, į vėlėjo lauko vieškelį;'),
  (@b23, 7, 4, 'ir jam tark: ‘Žiūrėk ir būk ramus; nebijok, ir tavo širdis teneišsigąsta dėl šitų dviejų rūkstančių nuodėgulių uodegų: dėl Recino su Sirija ir Remalijo sūnaus smarkaus pykčio’.'),
  (@b23, 7, 5, 'Kadangi Sirija, Efraimas ir Remalijo sūnus suplanavo prieš tave pikta, sakydami:'),
  (@b23, 7, 6, '„Eikime aukštyn prieš Judą, sudrumskime ją, prasilaužkime į ją ir pastatykime jos viduryje karaliumi Tabealio sūnų“;'),
  (@b23, 7, 7, 'taip sako Viešpats DIEVAS: „Tai neišsilaikys ir tai neįvyks.'),
  (@b23, 7, 8, 'Nes Sirijos galva yra Damaskas, o Damasko galva yra Recinas; ir per šešiasdešimt penkerius metus Efraimas bus taip sužlugdytas, kad jis nebebus tauta.'),
  (@b23, 7, 9, 'Efraimo galva yra Samarija, o Samarijos galva – Remalijo sūnus. Jei netikėsite, jūs tikrai neįsitvirtinsite“.'),
  (@b23, 7, 10, 'Toliau VIEŠPATS vėl kalbėjo Ahazui, sakydamas:'),
  (@b23, 7, 11, '„Prašyk iš VIEŠPATIES, savo Dievo, ženklo; prašyk jo gilumoje ar viršuje aukštybėje“.'),
  (@b23, 7, 12, 'Bet Ahazas tarė: „Aš neprašysiu ir negundysiu VIEŠPATIES“.'),
  (@b23, 7, 13, 'Ir jis tarė: „Nagi klausykite, o Dovydo namai; ar jums per maža varginti žmones, bet ar jūs varginsite ir mano Dievą?'),
  (@b23, 7, 14, 'Todėl pats Viešpats duos jums ženklą: štai mergelė pastos ir pagimdys sūnų ir pramins jį Emanuelio vardu.'),
  (@b23, 7, 15, 'Jis maitinsis sviestu ir medumi, kad mokėtų atmesti pikta ir pasirinkti gera.'),
  (@b23, 7, 16, 'Nes prieš vaikui išmokus atmesti pikta ir pasirinkti gera, šalis, kuria tu bjauriesi, bus palikta abiejų jos karalių.'),
  (@b23, 7, 17, 'VIEŠPATS atves ant tavęs, ant tavo tautos ir ant tavo tėvo namų dienas, kokių nėra atėję nuo tos dienos, kai Efraimas pasitraukė nuo Judos, tai yra, Asirijos karalių“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b23, 7, 18, 'Ir tą dieną atsitiks, kad VIEŠPATS sušvilps musėms, esančioms Egipto upių tolimiausiame gale, ir bitėms, esančioms Asirijos krašte.'),
  (@b23, 7, 19, 'Ir jos ateis ir visos apguls tuščius slėnius, uolų plyšius, visus erškėčius ir visus krūmus.'),
  (@b23, 7, 20, 'Tą dieną Viešpats nuskus pasamdytu skustuvu, esančiu anapus upės, tai yra, Asirijos karaliumi, galvą ir kojų plaukus; taip pat ir barzdą sunaikins.'),
  (@b23, 7, 21, 'Ir tą dieną atsitiks, kad žmogus maitins jauną karvę ir dvi avis;'),
  (@b23, 7, 22, 'ir įvyks, kad dėl gausos pieno, kurio jos duos, jis valgys sviesto; nes sviestą ir medų valgys kiekvienas, kuris bus išlikęs šalyje.'),
  (@b23, 7, 23, 'Ir tą dieną atsitiks, kad kiekviena vieta, kurioje buvo tūkstantis vynmedžių už tūkstantį sidabrinių, bus erškėčiams ir usnims.'),
  (@b23, 7, 24, 'Žmonės ten ateis su strėlėmis ir lankais; nes visa šalis taps erškėčiais ir usnimis.'),
  (@b23, 7, 25, 'Ir ant visų kalvų, kurias apkas kapliu, neateis erškėčių ir usnių baimė; bet jos bus jaučiams pasiųsti ir mažiems galvijams nutrypti.'),
  (@b23, 8, 1, 'Toliau VIEŠPATS man tarė: „Pasiimk didelį ritinį ir užrašyk jame žmogaus rašikliu apie Maher-Šalal-Haš-Baz“.'),
  (@b23, 8, 2, 'Ir aš pasiėmiau ištikimus liudytojus, kad patvirtintų: kunigą Ūriją ir Jeberechijo sūnų Zachariją.'),
  (@b23, 8, 3, 'Ir aš nuėjau pas pranašę; ir ji pastojo bei pagimdė sūnų. Tuomet VIEŠPATS man tarė: „Pramink jį vardu Maher-Šalal-Haš-Baz.'),
  (@b23, 8, 4, 'Nes vaikui dar neišmokus šaukti ‘mano tėvas’ ir ‘mano motina’, Damasko turtai ir Samarijos grobis bus atimti Asirijos karaliaus akivaizdoje“.'),
  (@b23, 8, 5, 'Ir vėl VIEŠPATS man kalbėjo, sakydamas:'),
  (@b23, 8, 6, '„Kadangi šita tauta atsisako Šiloacho vandenų, kurie tyliai teka, ir džiaugiasi Recinu ir Remalijo sūnumi;'),
  (@b23, 8, 7, 'todėl dabar štai Viešpats užleidžia ant jų upės vandenis, galingus ir gausius – Asirijos karalių ir visą jo šlovę; ir jis pakils viršum visų savo vagų ir apsems visus savo krantus;'),
  (@b23, 8, 8, 'ir eis per Judą; jis užtvindys ir užlies, net iki kaklo pasieks; ir jo išskėsti sparnai užpildys tavo šalies platybę, o Emanueli“.'),
  (@b23, 8, 9, 'Junkitės, tautos, ir jūs būsite sutriuškintos; atverkite ausį, visi jūs iš tolimų šalių; susijuoskite ir būsite sutriuškintos; susijuoskite ir būsite sutriuškintos.'),
  (@b23, 8, 10, 'Susitarkite, ir tai nueis niekais; tarkite žodį – ir jis neišsilaikys; nes Dievas yra su mumis.'),
  (@b23, 8, 11, 'Nes taip man kalbėjo VIEŠPATS stipria ranka ir mane pamokė, kad nevaikščiočiau šitos tautos keliu, sakydamas:'),
  (@b23, 8, 12, '„Nesakykite ‘sąmokslas’ visiems tiems, kuriems šita tauta sakys ‘sąmokslas’, nei nebijokite to, ko ji bijosi, nei neišsigąskite.'),
  (@b23, 8, 13, 'Pašvęskite patį kariuomenių VIEŠPATĮ; ir jis tebūna jūsų baimė, ir jis tebūna jūsų išgąstis.'),
  (@b23, 8, 14, 'Ir jis bus šventovė; bet suklupimo akmuo ir papiktinimo uola abiems Izraelio namams, žabangos ir spąstai Jeruzalės gyventojams.'),
  (@b23, 8, 15, 'Ir daugelis tarp jų suklups, kris, suduš, įsipainios ir bus pagauti.'),
  (@b23, 8, 16, 'Surišk liudijimą, užantspauduok įstatymą tarp mano mokinių“.'),
  (@b23, 8, 17, 'O aš lauksiu VIEŠPATIES, kuris slepia savo veidą nuo Jokūbo namų, ir jo ieškosiu.'),
  (@b23, 8, 18, 'Štai aš ir vaikai, kuriuos man davė VIEŠPATS, esame ženklams ir stebuklams Izraelyje nuo kariuomenių VIEŠPATIES, gyvenančio Siono kalne.'),
  (@b23, 8, 19, 'Ir kai jie jums sakys: „Ieškokite turinčiųjų namų dvasias ir magų, kurie cypsi ir murma“; argi tauta neturi ieškoti savo Dievo? Dėl gyvųjų pas mirusiuosius?'),
  (@b23, 8, 20, 'Įstatymo ir liudijimo; jei jie nekalba pagal šitą žodį, tai todėl, kad juose nėra šviesos.'),
  (@b23, 8, 21, 'Ir jie eis per ją labai prislėgti ir alkani; ir įvyks, kai bus alkani, jie susierzins ir keiks savo karalių ir savo Dievą, ir žiūrės aukštyn.'),
  (@b23, 8, 22, 'Ir jie žiūrės į žemę; ir štai vargas ir tamsa, aptemdantis sielvartas; ir jie bus nuvaryti į tamsą.'),
  (@b23, 9, 1, 'Tačiau aptemimas nebus, koks buvo jos varginime, kai jis iš pradžių lengvai pavargino Zebulono šalį ir Naftalio šalį, o vėliau labiau ją vargino palei jūros kelią, už Jordano, tautų Galilėjoje.'),
  (@b23, 9, 2, 'Tauta, vaikščiojanti tamsoje, išvydo didelę šviesą; ant gyvenančių mirties šešėlio šalyje nušvito šviesa.'),
  (@b23, 9, 3, 'Tu padauginai tautą, o nepadidinai džiaugsmo; jie džiaugiasi tavo akivaizdoje, kaip džiaugiasi pjūties metu, ir kaip džiūgaujama dalijantis grobį.'),
  (@b23, 9, 4, 'Nes tu sulaužei jos naštos jungą ir jos pečių lazdą, jos engėjo rykštę kaip Midjano dieną.'),
  (@b23, 9, 5, 'Nes kiekvienas kario mūšis yra su sąmyšio triukšmu ir drabužiais, išvoliotais kraujyje; bet šitas bus su sudeginimu ir ugnies kuru.'),
  (@b23, 9, 6, 'Nes kūdikis mums gimė, sūnus yra mums duotas; ir valdžia bus ant jo peties; ir jis bus vadinamas vardu: Nuostabus, Patarėjas, Galingasis Dievas, Amžinasis Tėvas, Taikos Kunigaikštis.'),
  (@b23, 9, 7, 'Jo valdžios augimui ir taikai nebus galo Dovydo soste ir jo karalystėje, kad tvarkytų ją ir įtvirtintų ją teismu ir teisingumu nuo dabar ir per amžius. Kariuomenių VIEŠPATIES uolumas tai įvykdys.'),
  (@b23, 9, 8, 'Viešpats siuntė į Jokūbą žodį, ir jis nusileido ant Izraelio.'),
  (@b23, 9, 9, 'Ir sužinos visa tauta – Efraimas ir Samarijos gyventojai, kurie sako su išdidumu ir širdies atkaklumu:'),
  (@b23, 9, 10, '„Plytos nugriuvo, bet mes pastatysime iš tašytų akmenų; sikomorai nukirsti, bet mes juos pakeisime kedrais“.'),
  (@b23, 9, 11, 'Todėl VIEŠPATS sukels prieš ją Recino priešininkus ir suvienys jos priešus:'),
  (@b23, 9, 12, 'sirus iš priekio ir filistinus iš užnugario; ir jie prarys Izraelį praverta burna. Dėl viso to jo pyktis nenusigręžė, bet jo ranka tebėra ištiesta.'),
  (@b23, 9, 13, 'Nes tauta neatsigręžia į tą, kuris ją sumuša, ir jie neieško kariuomenių VIEŠPATIES.'),
  (@b23, 9, 14, 'Todėl VIEŠPATS atkirs nuo Izraelio galvą ir uodegą, šaką ir vikšrį per vieną dieną.'),
  (@b23, 9, 15, 'Senoliai ir garbingieji – jie yra galva; o pranašas, kuris moko melo, – jis yra uodega.'),
  (@b23, 9, 16, 'Nes šitos tautos vadovai skatina juos klysti; o jų vedamieji – pražuvę.'),
  (@b23, 9, 17, 'Todėl Viešpats nesidžiaugs jų jaunuoliais nei nepasigailės jų našlaičių bei našlių; nes jie visi veidmainiai ir piktadariai, ir kiekviena burna kalba kvailystes. Dėl viso to jo pyktis nenusigręžė, bet jo ranka tebėra ištiesta.'),
  (@b23, 9, 18, 'Nes nedorybė dega kaip ugnis; ji prarys erškėčius bei usnis ir padegs miško tankmes, ir tai pakils kaip kylantys dūmai.'),
  (@b23, 9, 19, 'Dėl kariuomenių VIEŠPATIES rūstybės aptemo šalis, ir tauta bus kaip ugnies kuras; nei vienas nesigailės savo brolio.'),
  (@b23, 9, 20, 'Jis griebs dešinėje, bet bus alkanas; jis valgys kairėje, bet nepasisotins; jie kiekvienas valgys savo rankos kūną:'),
  (@b23, 9, 21, 'Manasas Efraimą ir Efraimas Manasą; o jie drauge bus prieš Judą. Dėl viso to jo pyktis nenusigręžė, bet jo ranka tebėra ištiesta.'),
  (@b23, 10, 1, 'Vargas tiems, kurie leidžia neteisius įsakus ir kurie rašo jų parašytus apsunkinimus;'),
  (@b23, 10, 2, 'kad atitrauktų nepasiturinčius nuo teismo ir atimtų teises iš mano tautos beturčių, kad našlės būtų jų grobis ir kad jie apiplėštų našlaičius!'),
  (@b23, 10, 3, 'Ir ką jūs darysite aplankymo dieną ir per suniokojimą, kuris ateis iš toli? Pas ką bėgsite pagalbos? Ir kur paliksite savo šlovę?'),
  (@b23, 10, 4, 'Be manęs jie nusilenks po belaisviais ir kris po užmuštaisiais. Dėl viso to jo pyktis nenusigręžė, bet jo ranka tebėra ištiesta.'),
  (@b23, 10, 5, '„O, asire, mano pykčio rykšte; ir lazda jų rankoje yra mano pasipiktinimas.'),
  (@b23, 10, 6, 'Aš pasiųsiu jį prieš veidmainingą tautą ir įpareigosiu jį prieš mano rūstybės tautą, kad prisigrobtų grobio ir prisiplėštų plėšimo ir kad sumindytų ją kaip gatvių purvą.'),
  (@b23, 10, 7, 'Tačiau jis ne taip galvoja, ir jo širdis ne taip mano; bet jo širdyje yra sunaikinti ir iškirsti nemažai tautų.'),
  (@b23, 10, 8, 'Nes jis sako: ‘Argi ne visi mano kunigaikščiai yra karaliai?'),
  (@b23, 10, 9, 'Argi Kalnė ne kaip Karkemišas? Argi Hamatas ne kaip Arpadas? Argi Samarija ne kaip Damaskas?'),
  (@b23, 10, 10, 'Kaip mano ranka surado stabų karalystes, kurių raižytų atvaizdų buvo daugiau negu Jeruzalės ir Samarijos;'),
  (@b23, 10, 11, 'argi aš nepadarysiu Jeruzalei ir jos stabams taip, kaip aš padariau Samarijai ir jos stabams?’'),
  (@b23, 10, 12, 'Todėl atsitiks, kai Viešpats įvykdys visą savo darbą Siono kalne ir Jeruzalėje, aš nubausiu Asirijos karaliaus atkaklios širdies vaisių ir jo pakelto žvilgsnio šlovę.'),
  (@b23, 10, 13, 'Nes jis sako: ‘Savo rankos jėga tai padariau ir savo išmintimi; nes aš esu protingas; ir pašalinau tautų ribas, išplėšiau jų lobius ir kaip narsuolis pažeminau gyventojus;'),
  (@b23, 10, 14, 'ir mano ranka surado tautų turtus kaip lizdus; kaip surenka paliktus kiaušinius, aš surinkau visą žemę; ir nei vienas nepajudino sparno ir nepražiojo burnos, ir nesucypsėjo’.'),
  (@b23, 10, 15, 'Ar kirvis giriasi prieš tą, kuris juo kerta? Ar pjūklas aukštinasi prieš tą, kuris jį judina? Tartum rykštė mosikuotų prieš tą, kuris ją pakelia, ar tartum lazda pasikeltų, tarsi nebūdama medis.'),
  (@b23, 10, 16, 'Todėl Viešpats, kariuomenių Viešpats, pasiųs tarp jo riebiųjų suliesėjimą; ir po jo šlove užkurs degimą, kaip ugnies degimą.'),
  (@b23, 10, 17, 'Izraelio šviesa bus ugnimi, jo Šventasis – liepsna; ir ji sudegins ir suris jo usnis bei jo erškėčius per vieną dieną;'),
  (@b23, 10, 18, 'ir sunaikins jo miško šlovę ir jo vaisingo lauko sielą ir kūną; ir jie bus kaip kad silpsta vėliavnešys.'),
  (@b23, 10, 19, 'O likusių jo miško medžių bus tiek mažai, kad vaikas galės juos surašyti.'),
  (@b23, 10, 20, 'Ir tą dieną atsitiks, kad Izraelio likutis ir Jokūbo namų pabėgėliai daugiau nebesirems tuo, kuris juos mušė; bet tiesoje remsis VIEŠPAČIU, Izraelio Šventuoju.'),
  (@b23, 10, 21, 'Likutis sugrįš, tai yra, Jokūbo likutis, pas galingąjį Dievą.'),
  (@b23, 10, 22, 'Nors ir būtų tavo tautos, Izraeli, kiek jūros smilčių, tačiau tik jų likutis sugrįš; nutartas sunaikinimas užtvindys teisumu.'),
  (@b23, 10, 23, 'Nes Viešpats, kariuomenių DIEVAS, įvykdys nuspręstą sunaikinimą visos šalies viduryje.'),
  (@b23, 10, 24, 'Todėl taip sako Viešpats, kariuomenių DIEVAS: „O, mano tauta, gyvenanti Sione, nebijok asiro; jis muš tave rykšte ir savo lazdą pakels prieš tave pagal Egipto būdą.'),
  (@b23, 10, 25, 'Nes dar labai trumpai, ir baigsis pasipiktinimas ir mano pyktis jų sunaikinimu.'),
  (@b23, 10, 26, 'Ir kariuomenių VIEŠPATS sukels jam rimbą pagal Midjano žudynes prie Orebo uolos; ir kaip jo lazda buvo virš jūros, taip jis ją pakels pagal Egipto būdą.'),
  (@b23, 10, 27, 'Ir tą dieną įvyks, kad jo našta bus pašalinta nuo tavo peties ir jo jungas nuo tavo kaklo; ir jungas bus sunaikintas dėl patepimo.'),
  (@b23, 10, 28, 'Jis atėjo į Ajatą, perėjo į Migroną; Michmaše pasidėjo savo mantą;'),
  (@b23, 10, 29, 'jie perėjo praėjimą; jie nakvojo Geboje; Rama išsigando; Sauliaus Gibėja pabėgo.'),
  (@b23, 10, 30, 'Kelk balsą, o Galimo dukra; padaryk, kad jis girdėtųsi Laišoje, o vargšas Anatote.'),
  (@b23, 10, 31, 'Madmena pasitraukė; Gebimo gyventojai susirinko bėgti.'),
  (@b23, 10, 32, 'Jis dar pasiliks tą dieną Nobe; jis mojuos ranka prieš Siono dukters kalną, Jeruzalės kalvą.'),
  (@b23, 10, 33, 'Štai Viešpats, kariuomenių VIEŠPATS, nugenės šakas su siaubu; ir aukštaūgiai bus nukirsti, ir išdidieji bus pažeminti.'),
  (@b23, 10, 34, 'Ir jis iškirs miško tankumynus geležimi, ir Libanas kris nuo galingojo.'),
  (@b23, 11, 1, 'Ir iš Jesės kamieno išdygs rykštė, ir iš jo šaknų išaugs Atžala;'),
  (@b23, 11, 2, 'ir ant jo ilsėsis VIEŠPATIES Dvasia, išminties ir supratimo Dvasia, patarimo ir galios Dvasia, pažinimo ir VIEŠPATIES baimės Dvasia;'),
  (@b23, 11, 3, 'ir padarys jį greito supratimo VIEŠPATIES baimėje; ir jis neteis pagal tai, ką jo akys mato, ir nebars pagal tai, ką jo ausys girdi;'),
  (@b23, 11, 4, 'bet jis teisumu teis vargšus ir bešališkai bars už žemės romiuosius; jis ištiks žemę savo burnos lazda, ir savo lūpų kvapu nužudys nedorėlį.'),
  (@b23, 11, 5, 'Ir teisumas bus jo strėnų juosta, ir ištikimybė jo inkstų juosta.'),
  (@b23, 11, 6, 'Taipogi vilkas gyvens su ėriuku, ir leopardas atsiguls su ožiuku; veršis, jaunas liūtas ir peniukšlis drauge; ir mažas vaikas juos vedžios.'),
  (@b23, 11, 7, 'Karvė ir meška ganysis, drauge gulės jų jaunikliai; ir liūtas ės šiaudus kaip jautis.'),
  (@b23, 11, 8, 'O žindomas vaikas žais prie nuodingos gyvatės olos, ir nujunkytas vaikas kiš savo ranką į angies lindynę.'),
  (@b23, 11, 9, 'Niekas nekenks ir nenaikins visame mano šventajame kalne; nes žemė bus pilna VIEŠPATIES pažinimo kaip vandenys apdengia jūrą.'),
  (@b23, 11, 10, 'Ir tą dieną bus Jesės šaknis, kuri stovės kaip tautos vėliava; pagonys jos ieškos; ir jos poilsis bus šlovingas.'),
  (@b23, 11, 11, 'Ir tą dieną įvyks, kad Viešpats antrą kartą vėl nukreips savo ranką, kad susigrąžintų savo tautos likutį, kuris bus išlikęs nuo Asirijos, nuo Egipto, nuo Patroso, nuo Kušo, nuo Elamo, nuo Šinaro, nuo Hamato ir nuo jūros salų.'),
  (@b23, 11, 12, 'Ir jis iškels vėliavą tautoms, ir surinks Izraelio atstumtuosius, ir surinks Judos išsklaidytuosius iš keturių žemės kampų.'),
  (@b23, 11, 13, 'Taipogi Efraimo pavydas pasitrauks, ir Judos priešininkai bus iškirsti; Efraimas nepavydės Judai, ir Juda nevargins Efraimo.'),
  (@b23, 11, 14, 'Bet jie skris ant filistinų pečių į vakarus; jie kartu apiplėš rytiečius: jie pridės rankas prie Edomo ir Moabo; ir Amono vaikai jiems paklus.'),
  (@b23, 11, 15, 'Ir VIEŠPATS visiškai sunaikins egiptiečių jūros liežuvį; ir savo galingu vėju jis mosuos ranką virš upės ir ją perskels į septynis upelius, ir perves žmones nesušlampant kojų.'),
  (@b23, 11, 16, 'Ir bus vieškelis jo tautos likučiui, kuris išliks nuo Asirijos; kaip tai buvo Izraeliui tą dieną, kai jis ėjo aukštyn iš Egipto šalies.'),
  (@b23, 12, 1, 'Ir tą dieną tu sakysi: „O, VIEŠPATIE, aš tave girsiu; nors tu buvai supykęs ant manęs, tavo pyktis nusigręžė, ir tu mane paguodei.'),
  (@b23, 12, 2, 'Štai Dievas yra mano išgelbėjimas; aš pasitikėsiu ir nebijosiu; nes VIEŠPATS JEHOVA yra mano stiprybė ir mano giesmė; taip pat jis tapo mano išgelbėjimu“.'),
  (@b23, 12, 3, 'Todėl jūs su džiaugsmu semsite vandens iš išgelbėjimo šaltinių.'),
  (@b23, 12, 4, 'Ir tą dieną jūs sakysite: „Girkite VIEŠPATĮ, šaukitės jo vardo, skelbkite tautose jo darbus, minėkite, kad jo vardas yra išaukštintas.'),
  (@b23, 12, 5, 'Giedokite VIEŠPAČIUI, nes jis padarė puikių dalykų; tai žinoma visoje žemėje.'),
  (@b23, 12, 6, 'Šauk ir šūkauk, Siono gyventojau; nes didis tavo tarpe Izraelio Šventasis“.'),
  (@b23, 13, 1, 'Babilono našta, kurią regėjo Amoco sūnus Izaijas.'),
  (@b23, 13, 2, 'Iškelkite vėliavą ant aukšto kalno, pakelkite į juos balsą, mojuokite ranka, kad jie eitų į kilmingųjų vartus.'),
  (@b23, 13, 3, 'Aš įsakiau savo pašvęstiesiems, taip pat pašaukiau savo galinguosius dėl savo pykčio, būtent tuos, kurie džiaugiasi mano didingumu.'),
  (@b23, 13, 4, 'Minios triukšmas kalnuose kaip didelės tautos; audringas triukšmas susirinkusių tautų karalysčių; kariuomenių VIEŠPATS renka mūšio kariuomenę.'),
  (@b23, 13, 5, 'Jie ateina iš tolimos šalies, nuo dangaus krašto, tai yra VIEŠPATS ir jo pasipiktinimo ginklai, kad sunaikintų visą šalį.'),
  (@b23, 13, 6, 'Kaukite, nes VIEŠPATIES diena arti; ji ateis kaip sunaikinimas nuo Visagalio.'),
  (@b23, 13, 7, 'Todėl visos rankos nusilps ir kiekvieno žmogaus širdis sutirps;'),
  (@b23, 13, 8, 'ir jie išsigąs; juos suims kančios ir sielvartai; juos suims skausmai kaip gimdančią moterį; jie stebėsis vienas kitu; jų veidai bus kaip liepsnos.'),
  (@b23, 13, 9, 'Štai ateina VIEŠPATIES diena, žiauri, su rūstybe ir dideliu pykčiu, kad suniokotų šalį; ir jis iš jos išnaikins jos nusidėjėlius.'),
  (@b23, 13, 10, 'Nes dangaus žvaigždės ir jo žvaigždynai neduos savo šviesos; saulė užtems savo patekėjime, ir mėnulis nebespindės savo šviesos.'),
  (@b23, 13, 11, 'Ir aš bausiu pasaulį už jų piktybę ir nedorėlius už jų neteisybę; ir padarysiu galą išdidžiųjų puikybei ir pažeminsiu baisiųjų išdidumą.'),
  (@b23, 13, 12, 'Padarysiu žmogų brangesnį už grynąjį auksą; būtent žmogų – už Ofyro aukso gabalą.'),
  (@b23, 13, 13, 'Todėl aš sudrebinsiu dangus, ir žemė pajudės iš savo vietos kariuomenių VIEŠPATIES rūstybėje ir jo didelio pykčio dieną.'),
  (@b23, 13, 14, 'Ir bus kaip išvaikytos stirnos ir kaip avys, kurių niekas nesurenka, – jie kiekvienas gręšis į savo tautą ir kiekvienas bėgs į savo šalį.'),
  (@b23, 13, 15, 'Kiekvienas, kuris bus aptiktas, bus perdurtas; ir kiekvienas, prie jų prisijungęs, kris nuo kalavijo.'),
  (@b23, 13, 16, 'Taip pat jų vaikai bus triuškinami jų akyse; jų namai bus apiplėšti ir jų žmonos išprievartautos.'),
  (@b23, 13, 17, 'Štai aš sukurstysiu prieš juos medus, kurie nevertina sidabro; ir auksas jų nedžiugina.'),
  (@b23, 13, 18, 'Taipogi jų lankai sutriuškins jaunuolius; ir įsčių vaisiaus jie nesigailės; jų akis nepagailės vaikų.'),
  (@b23, 13, 19, 'Ir Babilonas, karalysčių šlovė, kaldėjų puikybės grožis, bus kaip kad Dievas sugriovė Sodomą ir Gomorą.'),
  (@b23, 13, 20, 'Jis niekada nebus apgyvendintas, ir niekas negyvens jame per kartų kartas; nei arabas neties ten palapinės; nei piemenys nestatys ten savo aptvarų.'),
  (@b23, 13, 21, 'Bet laukiniai dykumos žvėrys ten gulės; ir jų namai bus pilni graudulingų sutvėrimų; ten gyvens pelėdos, ir satyrai ten šoks.'),
  (@b23, 13, 22, 'Ir laukiniai salų žvėrys šauks savo tuščiuose namuose, ir slibinai savo puikiuose rūmuose; priartėjo jo laikas, ir jo dienos nebus prailgintos.'),
  (@b23, 14, 1, 'Nes VIEŠPATS pasigailės Jokūbo ir vėl išsirinks Izraelį ir juos apgyvendins jų pačių šalyje; ateiviai prisijungs prie jų, ir jie prilips prie Jokūbo namų.'),
  (@b23, 14, 2, 'Ir tautos juos paims ir parves į jų vietą; ir Izraelio namai juos pasisavins tarnais ir tarnaitėmis VIEŠPATIES šalyje; jie paims į nelaisvę tuos, kurių belaisviais jie buvo; ir jie valdys savo engėjus.'),
  (@b23, 14, 3, 'Ir įvyks tą dieną, kai VIEŠPATS tau suteiks poilsį nuo tavo sielvarto ir nuo tavo baimės, ir nuo kietos vergijos, kurioje buvai priverstas tarnauti,'),
  (@b23, 14, 4, 'tada tu imsiesi šios patarlės prieš Babilono karalių, ir sakysi: „Kaip liovėsi engėjas! Auksinio miesto nebeliko!'),
  (@b23, 14, 5, 'VIEŠPATS sulaužė nedorėlio lazdą, valdovų skeptrą.'),
  (@b23, 14, 6, 'Tas, kuris rūstybėje mušė tautas nesiliaujančiais kirčiais, kuris pyktyje valdė tautas, yra persekiojamas, ir niekas netrukdo.'),
  (@b23, 14, 7, 'Visa žemė ilsisi ir yra rami; jie pratrūksta giedojimu.'),
  (@b23, 14, 8, 'Taip, eglės džiaugiasi dėl tavęs bei Libano kedrai, sakydami: ‘Nuo tada, kai atsigulei, joks kirtėjas nebeateina aukštyn prieš mus’.'),
  (@b23, 14, 9, 'Pragaras apačioje sujudo dėl tavęs, kad pasitiktų tave ateinantį; dėl tavęs jis pažadino mirusius, tai yra, visus žemės viršiausius; jis pakėlė nuo jų sostų visus tautų karalius.'),
  (@b23, 14, 10, 'Jie visi kalbės ir sakys tau: ‘Ar tu irgi tapai silpnas kaip ir mes? Ar tu tapai mums lygus?’'),
  (@b23, 14, 11, 'Nustumta žemyn į kapą tavo puikybė bei tavo violų triukšmas; po tavimi paklotas kirminas, ir kirminai tave apkloja.'),
  (@b23, 14, 12, 'Kaip tu iškritai iš dangaus, o liuciferi, ryto sūnau! Kaip tu nukirstas žemėn, kuris susilpninai tautas!'),
  (@b23, 14, 13, 'Nes tu buvai sakęs savo širdyje: ‘Aš pakilsiu į dangų, aš iškelsiu savo sostą virš Dievo žvaigždžių; aš taipogi atsisėsiu ant susirinkimo kalno, šiaurės šonuose;'),
  (@b23, 14, 14, 'aš pakilsiu virš debesų aukštybių; aš būsiu lygus Aukščiausiajam’.'),
  (@b23, 14, 15, 'Tačiau tu būsi nustumtas į pragarą, į duobės šonus.'),
  (@b23, 14, 16, 'Tie, kurie tave matys, įdėmiai žiūrės į tave ir galvos apie tave, sakydami: ‘Ar tai tas žmogus, kuris privertė žemę drebėti, kuris sukrėtė karalystes;'),
  (@b23, 14, 17, 'kuris padarė pasaulį kaip dykumą ir sugriovė jo miestus; kuris neatvėrė savo belaisvių namų?’'),
  (@b23, 14, 18, 'Visi tautų karaliai, visi jie guli šlovėje, kiekvienas savo namuose.'),
  (@b23, 14, 19, 'Bet tu esi išmestas iš savo kapo kaip bjauri atžala ir kaip drabužis užmuštųjų, perdurtų kalaviju, kurie nužengia į duobės akmenis; kaip po kojomis sumindytas lavonas.'),
  (@b23, 14, 20, 'Tu nesusivienysi su jais laidojime, nes sunaikinai savo šalį ir išžudei savo tautą; piktadarių sėkla niekada nebus minima.'),
  (@b23, 14, 21, 'Paruoškite jo vaikams žudynes už jų tėvų neteisybę; kad jie nepakiltų ir nepasisavintų šalies, ir nepripildytų pasaulio paviršiaus miestais.'),
  (@b23, 14, 22, '„Nes aš pakilsiu prieš juos, – sako kariuomenių VIEŠPATS, – ir iškirsiu iš Babilono vardą ir likutį, ir sūnų, ir vaikaitį“, – sako VIEŠPATS.'),
  (@b23, 14, 23, '„Taip pat padarysiu jį baublių nuosavybe bei vandens balomis; ir jį iššluosiu sunaikinimo šluota“, – sako kariuomenių VIEŠPATS.'),
  (@b23, 14, 24, 'Kariuomenių VIEŠPATS prisiekė, sakydamas: „Iš tiesų, kaip sumaniau, taip ir įvyks; ir kaip nutariau, taip ir išsilaikys:'),
  (@b23, 14, 25, 'kad sudaužysiu asirą savo šalyje ir jį sutrypsiu po kojomis ant savo kalnų; tada jo jungas pasitrauks nuo jų, ir jo našta pasišalins nuo jų pečių.'),
  (@b23, 14, 26, 'Šitoks yra sumanymas, kuris yra nutartas visai žemei; ir šita yra ranka, ištiesta į visas tautas.'),
  (@b23, 14, 27, 'Nes kariuomenių VIEŠPATS nutarė, kas tai panaikins? Ir jo ranka ištiesta, kas ją nukreips atgal?'),
  (@b23, 14, 28, 'Karaliaus Ahazo mirties metais buvo šita našta.'),
  (@b23, 14, 29, '„Nesidžiauk tu, visa Palestina, kad sulūžo lazda to, kuris tave mušė; nes iš gyvatės šaknies išeis angis, ir jos vaisius bus skraidanti ugninga gyvatė.'),
  (@b23, 14, 30, 'Vargšų pirmagimiai ganysis ir nepasiturintys saugiai gulės; o tavo šaknį nužudysiu badu, ir jis užmuš tavo likutį.'),
  (@b23, 14, 31, 'Kaukite, o vartai; šauk, o mieste; tu, visa Palestina, esi sunaikinta; nes iš šiaurės ateis dūmai, ir nei vienas nebus vienišas savo paskirtu laiku.'),
  (@b23, 14, 32, 'Tai ką atsakys tautos pasiuntiniams? Kad VIEŠPATS pastatė Sioną ant pamato, kuriuo pasitikės jo tautos vargšai“.'),
  (@b23, 15, 1, 'Moabo našta. Kadangi naktį buvo nuniokotas ir nutildytas Moabo Aras; kadangi naktį buvo nuniokotas ir nutildytas Moabo Kiras;'),
  (@b23, 15, 2, 'jis nuėjo aukštyn į Bajitą ir į Diboną, į aukštumas raudoti; Moabas kauks dėl Nebo ir dėl Medebos; ant visų jų galvų bus plikės, ir kiekviena barzda nukirpta.'),
  (@b23, 15, 3, 'Jų gatvėse jie apsijuos ašutine; ant jų namų stogų ir jų gatvėse kiekvienas kauks, gausiai verkdamas.'),
  (@b23, 15, 4, 'Šauks Hešbonas ir Elealė; jų balsas bus girdimas iki Jahaco; todėl šauksis ginkluoti Moabo kariai; jo gyvybė bus jam sielvartinga.'),
  (@b23, 15, 5, 'Mano širdis šauksis dėl Moabo; jo pabėgėliai bėgs į Coarą, trijų metų telyčią; nes su verksmu jie eis aukštyn Luhito įkalne; nes Horonaimo kelyje jie kels sunaikinimo šauksmą.'),
  (@b23, 15, 6, 'Nes Nimrimo vandenys bus suniokoti; nes sudžiūvo šienas, sunyko žolė, nėra jokios žalumos.'),
  (@b23, 15, 7, 'Todėl perteklių, kurį buvo įsigyję, ir tai, ką buvo sukaupę, jie išneš į gluosnių upelį.'),
  (@b23, 15, 8, 'Nes šauksmas pasklido po Moabo ribas; jo kauksmas iki Eglaimo ir jo kauksmas iki Beer-Elimo.'),
  (@b23, 15, 9, 'Nes Dimono vandenys bus pilni kraujo; nes aš atvesiu ant Dimono dar daugiau: liūtų ant pabėgusių iš Moabo ir ant likusiųjų šalyje.'),
  (@b23, 16, 1, 'Siųskite avinėlį šalies valdovui iš Selos į dykumą Siono dukters kalnui.'),
  (@b23, 16, 2, 'Nes bus – kaip klaidžiojantis paukštis, išmestas iš lizdo, taip bus Moabo dukterys prie Arnono brastų.'),
  (@b23, 16, 3, 'Sušauk pasitarimą, įvykdyk teismą; padaryk, kad tavo šešėlis būtų kaip naktis per patį vidurdienį; paslėpk atstumtuosius; neišduok klaidžiojančių.'),
  (@b23, 16, 4, 'Tegul mano atstumtieji gyvena pas tave, Moabai; būk jiems prieglauda nuo plėšiko veido; nes prievartautojo nebėra, plėšikas liaujasi, engėjai išnaikinti iš šalies.'),
  (@b23, 16, 5, 'Gailestingumu bus įtvirtintas sostas; ir jis sėdės jame tiesoje, Dovydo padangtėje, teisdamas ir ieškodamas teismo, ir paskubindamas teisumą.'),
  (@b23, 16, 6, 'Mes girdėjome apie Moabo išdidumą; jis labai išdidus; būtent apie jo puikybę, jo išdidumą ir jo rūstybę; bet jo melai ne tokie.'),
  (@b23, 16, 7, 'Todėl Moabas kauks dėl Moabo, kiekvienas kauks; dėl Kir-Hareseto pamatų jūs gedėsite; tikrai jie sumušti.'),
  (@b23, 16, 8, 'Nes išdžiūvo Hešbono laukai ir Sibmos vynmedis; pagonių viešpačiai nulaužė jo pagrindinius sodinukus, jie atėjo iki Jazero, jie klaidžiojo per dykumą; jo šakos išsiplėtusios, jos perėjusios anapus jūros.'),
  (@b23, 16, 9, 'Todėl raudosiu Jazero verksmu dėl Sibmos vynmedžio; aš laistysiu tave savo ašaromis, o Hešbone ir Eleale; nes šauksmas dėl tavo vasaros vaisių ir dėl tavo pjūties nupuolė.'),
  (@b23, 16, 10, 'Džiaugsmas ir džiūgavimas pašalinti iš derlingo lauko; vynuogynuose nebus giesmių ir nebus ten šūkavimų; mindytojai nemindys vyno savo spaudyklose; aš padariau galą jų vynuogių rinkimo šūkavimui.'),
  (@b23, 16, 11, 'Todėl mano viduriai skambės kaip arfa dėl Moabo, ir mano vidus dėl Kir-Harešo.'),
  (@b23, 16, 12, 'Ir įvyks, kai pasirodys, kad Moabas nusivarginęs aukštumoje, jis ateis į savo šventovę melstis; bet jis nieko nelaimės.'),
  (@b23, 16, 13, 'Tai yra žodis, kurį VIEŠPATS nuo ano laiko yra kalbėjęs apie Moabą.'),
  (@b23, 16, 14, 'Bet dabar VIEŠPATS kalbėjo, sakydamas: „Per trejus metus, kaip samdinio metus, Moabo šlovė bus paniekinta su visa ta didžiule minia; o likutis bus labai mažas ir silpnas“.'),
  (@b23, 17, 1, 'Damasko našta. „Štai Damaskas pašalintas, kad nebebūtų miestu, ir jis bus griuvėsių krūva.'),
  (@b23, 17, 2, 'Palikti Aroero miestai; jie bus kaimenėms, kurios gulės, ir niekas jų nebaidys.'),
  (@b23, 17, 3, 'Taipogi dings tvirtovės iš Efraimo ir karalystė iš Damasko, ir Sirijos likutis; jie bus kaip Izraelio vaikų šlovė“, – sako kariuomenių VIEŠPATS.'),
  (@b23, 17, 4, '„Ir tą dieną atsitiks, kad sumenkės Jokūbo šlovė ir jo kūno riebalai suliesės.'),
  (@b23, 17, 5, 'Ir bus, kaip kad pjovėjas nuima javus ir savo ranka nupjauna varpas; ir bus, kaip renkančiam varpas Refaimo slėnyje.'),
  (@b23, 17, 6, 'Tačiau jame išliks vynuogių parankos, kaip kad nukračius alyvmedį: dvi ar trys alyvos – viršutinės šakos viršūnėje, keturios ar penkios – jos tolimiausiose vaisingose šakose“, – sako VIEŠPATS, Izraelio Dievas.'),
  (@b23, 17, 7, 'Tą dieną žmogus žiūrės į savo Kūrėją, ir jo akys atsižvelgs į Izraelio Šventąjį.'),
  (@b23, 17, 8, 'Ir jis nežiūrės į aukurus – savo rankų darbą, ir neatsižvelgs į tai, ką padarė jo pirštai, nei į giraites, nei į atvaizdus.'),
  (@b23, 17, 9, 'Tą dieną jo tvirti miestai bus kaip apleista šaka, aukščiausia atžala, kurią jie paliko dėl Izraelio vaikų, ir ten bus suniokojimas.'),
  (@b23, 17, 10, 'Kadangi tu pamiršai savo išgelbėjimo Dievą ir neatsiminei savo stiprybės uolos, todėl tu pasodinsi geistinus sodinius ir apsodinsi tai svetimais daigais;'),
  (@b23, 17, 11, 'dieną tu auginsi savo sodinius, o ryte darysi, kad tavo sėkla vešėtų; bet derlius bus krūva tą liūdesio ir didelio sielvarto dieną.'),
  (@b23, 17, 12, 'Vargas daugelio tautų miniai, kurios triukšmauja kaip jūrų ūžimas; ir tautų veržimuisi, kurios veržiasi kaip veržiasi galingi vandenys!'),
  (@b23, 17, 13, 'Tautos veršis kaip veržiasi vandenų daugybė; bet Dievas juos subars, ir jie bėgs tolyn, ir bus vaikomi kaip kalnų pelai nuo vėjo ir kaip riedulys nuo viesulo.'),
  (@b23, 17, 14, 'Ir štai vakare – bėda; o prieš rytą jo nėra. Toks likimas tų, kurie mus apiplėšia, ir burtas tų, kurie mus apgrobia.'),
  (@b23, 18, 1, 'Vargas šaliai, kuri užtraukia šešėlį sparnais, kuri yra už Etiopijos upių;'),
  (@b23, 18, 2, 'kuri siunčia pasiuntinius jūra, meldų laivuose vandenimis, sakydama: „Eikite, greiti pasiuntiniai, pas tautą, išsklaidytą ir nuluptą, pas liaudį, baisią nuo jos pradžios iki dabar, tautą, išmatuotą ir sutryptą, kurios šalį apiplėšė upės!');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b23, 18, 3, 'Visi pasaulio gyventojai ir gyvenantys žemėje, žiūrėkite, kai iškels vėliavą ant kalnų; kai sugaudžia trimitu, klausykitės.'),
  (@b23, 18, 4, 'Nes taip VIEŠPATS man pasakė: „Aš ilsėsiuosi ir žiūrėsiu savo gyvenamoje vietoje kaip šviesi kaitra ant žolių ir kaip rasos debesis pjūties kaitroje“.'),
  (@b23, 18, 5, 'Nes prieš pjūtį, kai pumpurai užsibaigę ir rūgščios vynuogės noksta žieduose, jis nupjaustys ūglius genėjimo peiliais ir pašalins bei nupjaus atžalas.'),
  (@b23, 18, 6, 'Jie bus palikti kalnų skrajūnams ir žemės žvėrims; skrajūnai ant jų vasaros ir visi žemės žvėrys ant jų žiemos.'),
  (@b23, 18, 7, 'Tuo metu bus atnešta dovana kariuomenių VIEŠPAČIUI nuo tautos, išsklaidytos ir nuluptos, nuo liaudies, baisios nuo jos pradžios iki dabar, nuo tautos, išmatuotos ir sutryptos po kojomis, kurios šalį apiplėšė upės, į kariuomenių VIEŠPATIES vardo vietą – į Siono kalną.'),
  (@b23, 19, 1, 'Egipto našta. Štai VIEŠPATS joja ant greito debesies ir atvyks į Egiptą; ir Egipto stabai sujudės jo akivaizdoje, ir Egipto širdis tirps jo viduje.'),
  (@b23, 19, 2, '„Aš nukreipsiu egiptiečius prieš egiptiečius; ir jie kovos kiekvienas prieš savo brolį ir kiekvienas prieš savo artimą; miestas prieš miestą ir karalystė prieš karalystę.'),
  (@b23, 19, 3, 'Išseks Egipto dvasia jo viduje; ir aš sunaikinsiu jo patarimą; jie kreipsis į stabus, į kerėtojus, į turinčius namų dvasias ir į magus.'),
  (@b23, 19, 4, 'Aš egiptiečius perduosiu į žiauraus viešpaties ranką; ir piktas karalius juos valdys“, – sako Viešpats, kariuomenių VIEŠPATS.'),
  (@b23, 19, 5, 'Išseks jūros vandenys, ir upė bus išsekusi ir išdžiūvusi.'),
  (@b23, 19, 6, 'Ir jie nukreips tolyn upes; ištuštės ir išdžius apsaugos upeliai; nendrės ir vilkdalgiai sudžius.'),
  (@b23, 19, 7, 'Papirusai prie upelių, prie upelių žiočių, ir visa, kas apsėta prie upelių, išdžius, bus išsklaidyta ir nebebus.'),
  (@b23, 19, 8, 'Taipogi gedės žvejai ir raudos visi, kurie meta į upelius meškerę; ir nusilps tie, kurie tiesia tinklus vandenyse.'),
  (@b23, 19, 9, 'Be to, bus suglumę tie, kurie dirba iš plono lino ir kurie audžia tinklus.'),
  (@b23, 19, 10, 'Ir sužlugs savo ketinimais visi, kurie daro vandentakius ir tvenkinius žuvims.'),
  (@b23, 19, 11, 'Tikrai Coano kunigaikščiai yra kvailiai; išmintingų faraono patarėjų patarimas tapo neprotingas; kaipgi jūs sakote faraonui: „Aš esu išmintingojo sūnus, senovės karalių sūnus?“'),
  (@b23, 19, 12, 'Kur jie yra? Kur yra tavo išminčiai? Tegul jie dabar tau pasako ir tegul jie žino, ką kariuomenių VIEŠPATS yra nutaręs dėl Egipto.'),
  (@b23, 19, 13, 'Coano kunigaikščiai tapo kvailiais, Nofo kunigaikščiai apgauti; jie suvedžiojo ir Egiptą – tie, kurie yra jo genčių ramstis.'),
  (@b23, 19, 14, 'VIEŠPATS įmaišė į jų vidų iškreiptą dvasią; ir jie privertė Egiptą klysti visuose jo darbuose, kaip kad girtas svirduliuoja savo vėmaluose.'),
  (@b23, 19, 15, 'Nebus Egiptui jokio darbo, kurį galėtų daryti galva ar uodega, šaka ar nendrė.'),
  (@b23, 19, 16, 'Tą dieną Egiptas bus lygus moterims; jis išsigąs ir bijos dėl kariuomenių VIEŠPATIES rankos mosavimo, kuria jis mosuos virš jo.'),
  (@b23, 19, 17, 'Ir Judos šalis bus siaubas Egiptui, kiekvienas ją paminėjęs išsigąs savyje dėl kariuomenių VIEŠPATIES ketinimo, kurį jis nusprendė prieš juos.'),
  (@b23, 19, 18, 'Tą dieną penki miestai Egipto šalyje kalbės Kanaano kalba ir prisieks kariuomenių VIEŠPAČIUI; vienas bus vadinamas sunaikinimo miestu.'),
  (@b23, 19, 19, 'Tą dieną bus aukuras VIEŠPAČIUI Egipto šalies viduryje ir stulpas VIEŠPAČIUI ant jos ribos.'),
  (@b23, 19, 20, 'Ir tai bus ženklui ir liudijimui kariuomenių VIEŠPAČIUI Egipto šalyje: nes jie šauksis VIEŠPATIES dėl engėjų, ir jis siųs jiems gelbėtoją, didįjį, ir jis juos išvaduos.'),
  (@b23, 19, 21, 'Ir VIEŠPATS bus žinomas Egiptui, ir egiptiečiai tą dieną pažins VIEŠPATĮ ir atliks auką ir aukojimą; taip, jie duos VIEŠPAČIUI įžadus ir juos ištesės.'),
  (@b23, 19, 22, 'Ir VIEŠPATS sumuš Egiptą; jis sumuš ir jį išgydys; ir jie sugrįš pas VIEŠPATĮ, ir jis duosis jų išmeldžiamas ir juos išgydys.'),
  (@b23, 19, 23, 'Tą dieną bus vieškelis iš Egipto į Asiriją; ir asiras ateis į Egiptą, o egiptietis į Asiriją, ir egiptiečiai tarnaus su asirais.'),
  (@b23, 19, 24, 'Tą dieną Izraelis bus trečias su Egiptu ir Asirija – palaiminimas šalies viduryje;'),
  (@b23, 19, 25, 'juos kariuomenių VIEŠPATS palaimins, sakydamas: „Tebūna palaimintas Egiptas, mano tauta, ir Asirija, mano rankų darbas, ir Izraelis, mano paveldas“.'),
  (@b23, 20, 1, 'Tais metais, kai Tartanas atvyko į Ašdodą (kai jį siuntė Asirijos karalius Sargonas) ir kariavo prieš Ašdodą, ir jį paėmė;'),
  (@b23, 20, 2, 'tuo pačiu metu VIEŠPATS kalbėjo per Amoco sūnų Izaiją, sakydamas: „Eik, nusirišk ašutinę nuo savo strėnų ir nusiauk savo apavą nuo kojų“. Ir jis taip padarė: vaikščiojo nuogas ir basas.'),
  (@b23, 20, 3, 'Ir VIEŠPATS tarė: „Kaip mano tarnas Izaijas trejus metus vaikščiojo nuogas ir basas kaip ženklas ir stebuklas Egiptui ir Etiopijai,'),
  (@b23, 20, 4, 'taip Asirijos karalius nusives egiptiečius kalinius ir etiopus belaisvius, jaunus ir senus, nuogus ir basus, tai yra, su apnuogintais sėdmenimis, Egipto gėdai.'),
  (@b23, 20, 5, 'Ir jie bijos ir gėdysis Etiopijos, savo lūkesčio, ir Egipto, savo šlovės.'),
  (@b23, 20, 6, 'Ir šitos salos gyventojai tą dieną sakys: ‘Štai toks yra mūsų lūkestis, pas kurį bėgame pagalbos, kad būtume išvaduoti iš Asirijos karaliaus; ir kaip mes pabėgsime?’“'),
  (@b23, 21, 1, 'Jūros dykumos našta. Kaip viesulai praeina pietuose, taip ji ateina iš dykumos, iš baisios šalies.'),
  (@b23, 21, 2, 'Sunkus regėjimas man paskelbtas: klastingasis elgiasi klastingai ir plėšikas plėšia. Eik aukštyn, o Elamai; apgulk, o Medija; visam dūsavimui aš padariau galą.'),
  (@b23, 21, 3, 'Todėl mano strėnos prisipildė skausmo; skausmai suėmė mane, kaip gimdančios moters skausmai; aš susilenkiau tai girdėdamas; aš sunerimau tai matydamas.'),
  (@b23, 21, 4, 'Tvinkčiojo mano širdis, mane gąsdino baimė; mano malonumų naktį jis man pavertė baime.'),
  (@b23, 21, 5, 'Paruošk stalą, budėk sargybos bokšte, valgyk, gerk; kelkitės, kunigaikščiai ir patepkite skydą.'),
  (@b23, 21, 6, 'Nes taip man pasakė Viešpats: „Eik, pastatyk sargą, tegul jis praneša, ką mato.'),
  (@b23, 21, 7, 'Ir jis pamatė vežimą su pora raitelių, asilų vežimą ir kupranugarių vežimą; ir jis stropiai klausėsi, labai atidžiai;'),
  (@b23, 21, 8, 'ir jis sušuko: „Liūtas; mano viešpatie, aš be perstojo dienos metu stoviu sargybos bokšte ir aš pastatytas saugoti per ištisas naktis;'),
  (@b23, 21, 9, 'ir štai atvyksta vyrų vežimas su pora raitelių“. Ir jis atsiliepdamas tarė: „Krito, krito Babilonas; ir visus raižytus jo dievų atvaizdus jis sudaužė ant žemės“.'),
  (@b23, 21, 10, 'O mano kūlime, mano klojimo javai; ką girdėjau iš kariuomenių VIEŠPATIES, Izraelio Dievo, aš jums paskelbiau.'),
  (@b23, 21, 11, 'Dūmos našta. Jis man šaukia iš Seyro: „Sarge, kiek nakties? Sarge, kiek nakties?“'),
  (@b23, 21, 12, 'Sargas tarė: „Ateina rytas, ir taip pat naktis; jei norite klausti, klauskite; grįžkite, ateikite“.'),
  (@b23, 21, 13, 'Našta Arabijai. Jūs nakvosite miške Arabijoje, o jūs, keliaujantys Dedano būriai.'),
  (@b23, 21, 14, 'Temos šalies gyventojai atnešė ištroškusiems vandens, jie su duona pasitiko pabėgėlius.'),
  (@b23, 21, 15, 'Nes jie pabėgo nuo kalavijų, nuo ištraukto kalavijo, nuo įtempto lanko ir nuo karo smarkumo.'),
  (@b23, 21, 16, 'Nes taip man pasakė Viešpats: „Per vienerius metus, pagal samdinio metus, pranyks visa Kedaro šlovė.'),
  (@b23, 21, 17, 'Ir lankininkų, Kedaro vaikų galiūnų, skaičiaus likutis sumažės, nes VIEŠPATS, Izraelio Dievas, tai kalbėjo.'),
  (@b23, 22, 1, 'Regėjimo slėnio našta. Kas tau atsitiko, kad tu visas užlipai ant namų stogų?'),
  (@b23, 22, 2, 'Tu, pilnas sąmyšių, triukšmingas mieste, linksmas mieste; tavo užmuštieji ne kalaviju užmušti ir ne mūšyje žuvę.'),
  (@b23, 22, 3, 'Visi tavo valdovai pabėgo drauge, jie yra lankininkų surišti: visi, kurie surasti tavyje, yra kartu surišti, jie iš toli pabėgę.'),
  (@b23, 22, 4, 'Todėl pasakiau: „Žvelkite į šalį nuo manęs; aš karčiai verksiu, nesistenkite manęs guosti dėl mano tautos dukters apiplėšimo“.'),
  (@b23, 22, 5, 'Nes tai diena vargo, sutrypimo ir sąmyšio nuo Viešpaties, kariuomenių DIEVO, Regėjimo slėnyje, diena sienų griovimo ir šauksmo į kalnus.'),
  (@b23, 22, 6, 'Ir Elamas nešė strėlinę su žmonių ir raitelių vežimais, ir Kiras apnuogino skydą.'),
  (@b23, 22, 7, 'Ir atsitiks, kad tavo rinktiniai slėniai bus pilni vežimų, o raiteliai išsirikiuos prie vartų.'),
  (@b23, 22, 8, 'Ir jis atidengė Judos apdangalą, ir tą dieną tu žvelgei į Miško namų ginklus.'),
  (@b23, 22, 9, 'Taipogi jūs matėte Dovydo miesto spragas, kad jų yra daug; ir jūs surinkote žemutinio tvenkinio vandenis.'),
  (@b23, 22, 10, 'Jūs suskaičiavote Jeruzalės namus ir nugriovėte namus, kad sutvirtintumėte sieną.'),
  (@b23, 22, 11, 'Taip pat jūs padarėte griovį tarp abiejų sienų senojo tvenkinio vandeniui; bet jūs nepažvelgėte į tą, kuris tai padarė, ir neatsižvelgėte į tą, kuris seniai tai suformavo.'),
  (@b23, 22, 12, 'Ir tą dieną Viešpats, kariuomenių DIEVAS, kvietė verkti, gedėti, nusiskusti galvą ir susijuosti ašutine;'),
  (@b23, 22, 13, 'bet štai džiaugsmas ir linksmybė, jaučių užmušimas ir avių pjovimas, mėsos valgymas ir vyno gėrimas: „valgykime ir gerkime, nes rytoj mirsime“.'),
  (@b23, 22, 14, 'Ir buvo apreikšta mano ausyse kariuomenių VIEŠPATIES: „Tikrai šita neteisybė nebus nuo jūsų apvalyta iki numirsite, – sako Viešpats, kariuomenių DIEVAS“.'),
  (@b23, 22, 15, 'Taip sako Viešpats kariuomenių DIEVAS: „Eik, įeik pas šitą iždininką – Šebną, namų viršininką, ir sakyk:'),
  (@b23, 22, 16, '‘Ką čia turi? Kas pas tave, kad išsikirtai čia kapą, kaip tas, kuris išsikerta kapą aukštybėje, kuris išsikaldina uoloje buveinę?'),
  (@b23, 22, 17, 'Štai VIEŠPATS tave išves galinga nelaisve ir tikrai tave apdengs.'),
  (@b23, 22, 18, 'Jis tikrai tave smarkiai pasuks ir mes kaip kamuolį į didelę šalį; ten tu mirsi ir ten tavo šlovės vežimai bus tavo viešpaties namų gėda.'),
  (@b23, 22, 19, 'Ir aš išvarysiu tave iš tavo vietos, ir nuo tavo padėties tave nutemps.'),
  (@b23, 22, 20, 'Ir tą dieną atsitiks, kad aš pašauksiu savo tarną Eljakimą, Hilkijo sūnų;'),
  (@b23, 22, 21, 'ir jį apvilksiu tavo rūbu, ir sustiprinsiu jį tavo juosta, ir tavo valdžią patikėsiu į jo ranką; ir jis bus tėvu Jeruzalės gyventojams ir Judos namams.'),
  (@b23, 22, 22, 'Ir Dovydo namų raktą aš padėsiu ant jo peties; taip jis atrakins, ir niekas neužrakins; jis užrakins, ir niekas neatrakins.'),
  (@b23, 22, 23, 'Ir aš įkalsiu jį kaip vinį tikroje vietoje; ir jis bus šlovės sostu savo tėvo namams.'),
  (@b23, 22, 24, 'Ir ant jo pakabins visą jo tėvo namų šlovę, palikuonis ir vaikus, visus mažos talpos indus, nuo puodukų indų iki ąsočių indų.'),
  (@b23, 22, 25, 'Tą dieną, – sako kariuomenių VIEŠPATS, – vinis, įkalta tikroje vietoje, bus ištraukta, nukirsta ir nukris; ir našta, kuri buvo ant jo, bus iškirsta; nes VIEŠPATS tai kalbėjo’“.'),
  (@b23, 23, 1, 'Tyro našta. Kaukite, jūs, Taršišo laivai; nes jis taip suniokotas, kad nėra nei namo, nei įėjimo; iš Kitimo šalies jiems tai pranešta.'),
  (@b23, 23, 2, 'Nutilkite, gyventojai salos, kurią pripildė Sidono pirkliai, plaukiojantys po jūrą.'),
  (@b23, 23, 3, 'Sihoro sėklos, upės derlius, yra jos pajamos per plačius vandenis; ir ji yra tautų prekyvietė.'),
  (@b23, 23, 4, 'Susigėsk, o Sidone; nes jūra, būtent jūros stiprybė, kalbėjo, sakydama: „Aš neturėjau gimdymo skausmų, negimdžiau vaikų, nemaitinau jaunikaičių ir neišauginau mergelių“.'),
  (@b23, 23, 5, 'Kaip dėl žinios apie Egiptą, taip jiems labai skaudės dėl žinios apie Tyrą.'),
  (@b23, 23, 6, 'Pereikite į Taršišą; kaukite, jūs, salos gyventojai.'),
  (@b23, 23, 7, 'Ar šitas yra jūsų linksmasis miestas, kurio senumas yra nuo senų dienų? Jo paties kojos nuneš jį tolyn laikinai apsigyventi.'),
  (@b23, 23, 8, 'Kas tai sumanė prieš Tyrą, vainikuojantį miestą, kurio pirkliai – kunigaikščiai, kurio prekiautojai – žemės garbingieji?'),
  (@b23, 23, 9, 'Kariuomenių VIEŠPATS tai nutarė, kad suteptų visos šlovės išdidumą, kad paniekintų visus žemės garbinguosius.'),
  (@b23, 23, 10, 'Pereik savo šalį kaip upė, o Taršišo dukra; nebėra stiprybės.'),
  (@b23, 23, 11, 'Jis ištiesė savo ranką virš jūros, jis supurtė karalystes; VIEŠPATS davė įsakymą prieš pirklių miestą, kad sunaikintų jo tvirtoves.'),
  (@b23, 23, 12, 'Ir jis tarė: „Tu daugiau nebesilinksminsi, o engiama mergele, Sidono dukra; kelkis, pereik į Kitimus; ten irgi neturėsi poilsio“.'),
  (@b23, 23, 13, 'Štai kaldėjų šalis; šios tautos nebuvo, kol asiras jos neįkūrė gyvenantiems dykumoje; jie pastatė jos bokštus, pastatė jos rūmus; o jis ją pavertė griuvėsiais.'),
  (@b23, 23, 14, 'Kaukite, Taršišo laivai, nes jūsų stiprybė nusiaubta.'),
  (@b23, 23, 15, 'Ir tą dieną atsitiks, kad Tyras bus pamirštas septyniasdešimt metų, pagal vieno karaliaus dienas; pasibaigus septyniasdešimčiai metų, Tyras giedos kaip paleistuvė.'),
  (@b23, 23, 16, 'Pasiimk arfą, vaikščiok po miestą, tu, pamiršta paleistuve; melodingai grok, daug giesmių giedok, kad tave atsimintų.'),
  (@b23, 23, 17, 'Ir septyniasdešimčiai metų pasibaigus įvyks, kad VIEŠPATS aplankys Tyrą, ir jis sugrįš prie savo samdos ir paleistuvaus su visomis pasaulio karalystėmis ant žemės paviršiaus.'),
  (@b23, 23, 18, 'Ir jo prekiavimas ir jo samda bus šventumas VIEŠPAČIUI; tai nebus nei kaupiama, nei taupoma; nes jo prekės bus tiems, kurie gyvena VIEŠPATIES akivaizdoje, kad pakankamai valgytų ir turėtų patvarius drabužius.'),
  (@b23, 24, 1, 'Štai VIEŠPATS daro žemę tuščią ir daro ją dyką, ir apverčia ją aukštyn kojomis, ir išsklaido jos gyventojus.'),
  (@b23, 24, 2, 'Ir tai bus kaip tautai, taip ir kunigui; kaip tarnui, taip ir jo šeimininkui; kaip tarnaitei, taip ir jos šeimininkei; kaip pirkėjui, taip ir pardavėjui; kaip skolintojui, taip ir skolininkui; kaip imančiam palūkanas, taip ir tam, kuris jam duoda palūkanas.'),
  (@b23, 24, 3, 'Šalis bus visiškai ištuštinta ir visiškai apiplėšta, nes VIEŠPATS kalbėjo šitą žodį.'),
  (@b23, 24, 4, 'Žemė gedi ir nyksta, pasaulis silpsta ir nyksta, žemės išdidieji silpsta.'),
  (@b23, 24, 5, 'Taip pat žemė suteršta po savo gyventojais; nes jie nusižengė įstatymams, pakeitė įsaką, sulaužė amžinąją sandorą.'),
  (@b23, 24, 6, 'Todėl prakeikimas rijo žemę, ir joje gyvenantys yra nusiaubti; todėl žemės gyventojai sudeginti ir žmonių mažai beliko.'),
  (@b23, 24, 7, 'Jaunas vynas gedi, vynmedis nyksta, dūsauja visi linksmaširdžiai.'),
  (@b23, 24, 8, 'Būgnelių linksmumas liaujasi, džiūgaujančių triukšmas baigiasi, arfos džiaugsmas liaujasi.'),
  (@b23, 24, 9, 'Nebegers vyno giedodami; stiprus gėrimas bus kartus jį geriantiems.'),
  (@b23, 24, 10, 'Sugriautas sumaišties miestas; visi namai užrakinti, kad niekas neįeitų.'),
  (@b23, 24, 11, 'Verkia dėl vyno gatvėse; visas džiaugsmas aptemo, šalies linksmybė dingo.'),
  (@b23, 24, 12, 'Mieste telikęs suniokojimas, ir vartai ištikti sunaikinimo.'),
  (@b23, 24, 13, 'Taip bus šalies viduryje tarp tautų, kaip kad purto alyvmedį, ir kaip vynuogių parankos, kai vynuogių rinkimas pasibaigęs.'),
  (@b23, 24, 14, 'Jie pakels savo balsą, giedos dėl VIEŠPATIES didybės, jie garsiai šūkaus nuo jūros.'),
  (@b23, 24, 15, 'Todėl šlovinkite VIEŠPATĮ ugnyse, tai yra, VIEŠPATIES, Izraelio Dievo, vardą jūros salose.'),
  (@b23, 24, 16, 'Nuo tolimiausio žemės krašto girdėjome giesmes, būtent šlovę teisiajam. Bet aš tariau: „Mano liesumas, mano liesumas, vargas man! Klastingieji elgėsi klastingai; taip, klastingieji elgėsi labai klastingai“.'),
  (@b23, 24, 17, 'Išgąstis, duobė ir žabangos yra ant tavęs, o žemės gyventojau.'),
  (@b23, 24, 18, 'Ir įvyks – kas bėgs nuo išgąstingo triukšmo, įkris į duobę; o kas išlips iš duobės, pateks į žabangas; nes atsivėrę langai aukštybėje, ir žemės pamatai dreba.'),
  (@b23, 24, 19, 'Žemė visiškai sudaužyta, žemė visiškai suskaidyta, žemė stipriai judinama.'),
  (@b23, 24, 20, 'Žemė svirduliuos ten ir atgal kaip girtas ir bus kilnojama kaip lūšna; ją apsunkins jos nusižengimas; ir ji grius ir nebeatsikels.'),
  (@b23, 24, 21, 'Ir tą dieną įvyks, kad VIEŠPATS nubaus kariuomenę aukštųjų, esančių aukštybėje, ir žemės karalius žemėje.'),
  (@b23, 24, 22, 'Ir jie bus surinkti, kaip kaliniai yra surenkami į duobę, ir bus užrakinti kalėjime, ir po daugelio dienų jie bus aplankyti.'),
  (@b23, 24, 23, 'Tada mėnulis bus sugėdintas ir saulė susigės, kai kariuomenių VIEŠPATS karaliaus Siono kalne, Jeruzalėje, ir savo senųjų akivaizdoje šlovingai.'),
  (@b23, 25, 1, 'O VIEŠPATIE, tu esi mano Dievas; aš tave aukštinsiu, aš girsiu tavo vardą; nes tu padarei nuostabių dalykų; tavo patarimai nuo seno yra ištikimybė ir tiesa.'),
  (@b23, 25, 2, 'Nes tu pavertei miestą krūva, sutvirtintą miestą griuvėsiais; kad svetimšalių rūmai nebebūtų miestas; jis niekada nebus atstatytas.'),
  (@b23, 25, 3, 'Todėl stipri tauta šlovins tave, baisių tautų miestas tavęs bijos.'),
  (@b23, 25, 4, 'Nes tu buvai stiprybė vargšui, stiprybė nepasiturinčiajam jo varge, prieglobstis nuo audros, šešėlis nuo kaitros, kai baisiųjų pūtimas yra kaip audra prieš sieną.'),
  (@b23, 25, 5, 'Tu numalšinsi svetimšalių triukšmą kaip kaitrą sausoje vietoje; būtent kaitrą debesies šešėliu; baisiųjų atžala bus nužeminta.'),
  (@b23, 25, 6, 'Ir kariuomenių VIEŠPATS šiame kalne suruoš visoms tautoms riebalų pokylį, pokylį nusistovėjusių vynų, kaulų smegenimis gausių riebalų, gerai išvalytų nusistovėjusių vynų.'),
  (@b23, 25, 7, 'Ir jis sunaikins šiame kalne paviršių dangos, apdengusios visas tautas, šydą, užtiestą ant visų tautybių.'),
  (@b23, 25, 8, 'Jis prarys mirtį pergalėje; ir Viešpats DIEVAS nušluostys ašaras nuo visų veidų; ir savo tautos papeikimą jis pašalins nuo visos žemės; nes VIEŠPATS tai kalbėjo.'),
  (@b23, 25, 9, 'Ir tą dieną sakys: „Štai tai mūsų Dievas; mes jo laukėme, ir jis mus išgelbės; tai VIEŠPATS; mes jo laukėme, mes linksminsimės ir džiaugsimės jo išgelbėjimu.'),
  (@b23, 25, 10, 'Nes VIEŠPATIES ranka ilsėsis šiame kalne, o Moabas bus po juo sumindytas, kaip suminami šiaudai mėšlo krūvai.'),
  (@b23, 25, 11, 'Ir jis išskės savo rankas jų viduryje, kaip plaukiantysis išskečia rankas plaukti; ir jis pažemins jų išdidumą kartu su jų rankų grobiu.'),
  (@b23, 25, 12, 'Ir tavo sienų aukšto forto tvirtovę jis pažemins, nuvers, nustums žemėn į dulkes.'),
  (@b23, 26, 1, 'Tą dieną šita giesmė bus giedama Judos šalyje: „Mes turime tvirtą miestą: Dievas paskirs išgelbėjimą sienoms ir pylimams.'),
  (@b23, 26, 2, 'Atidarykite vartus, kad įeitų teisi tauta, kuri saugo tiesą.'),
  (@b23, 26, 3, 'Tu išsaugosi tobulą ramybę tam, kurio mintys pasilieka su tavimi; nes jis pasitiki tavimi.'),
  (@b23, 26, 4, 'Pasitikėkite VIEŠPAČIU per amžius; nes VIEŠPATYJE JEHOVOJE yra amžina stiprybė;'),
  (@b23, 26, 5, 'nes jis nužemina gyvenančius aukštai; didingą miestą jis pažemina; jis pažemina jį iki žemės; jis nuverčia jį į dulkes.'),
  (@b23, 26, 6, 'Jį sutryps koja – vargšų kojos, nepasiturinčiųjų žingsniai.'),
  (@b23, 26, 7, 'Teisiojo kelias – tiesumas; tu, pats tiesiausias, pasveri teisiojo takus.'),
  (@b23, 26, 8, 'Taip, tavo teismų kelyje, o VIEŠPATIE, mes laukėme tavęs; mūsų siela troško tavo vardo ir prisiminimo apie tave.'),
  (@b23, 26, 9, 'Savo siela troškau tavęs naktį; taip, savo dvasia mano viduje anksti ieškosiu tavęs; nes kai tavo teismai yra žemėje, pasaulio gyventojai mokysis teisumo.'),
  (@b23, 26, 10, 'Teparodo nedorėliui palankumą, tačiau jis neišmoks teisumo; tiesumo šalyje jis elgsis neteisiai ir nežiūrės į VIEŠPATIES didybę.'),
  (@b23, 26, 11, 'VIEŠPATIE, tavo ranka pakelta, tačiau jie nemato; bet jie matys ir susigės dėl savo pavydo tautai; taip, tavo priešų ugnis juos prarys.'),
  (@b23, 26, 12, 'VIEŠPATIE, tu mums paskirsi ramybę; nes tu mumyse taipogi atlikai visus mūsų darbus.'),
  (@b23, 26, 13, 'O VIEŠPATIE, mūsų Dieve, be tavęs mums viešpatavo kiti viešpačiai; tačiau tik per tave mes minėsime tavo vardą.'),
  (@b23, 26, 14, 'Jie mirę, jie negyvens; jie mirę, jie neatsikels; todėl tu juos aplankei ir sunaikinai, ir visą jų atminimą pražudei.'),
  (@b23, 26, 15, 'Tu padauginai tautą, o VIEŠPATIE, padauginai tautą; tu pašlovintas; tu ją perkėlei toli, iki visų žemės pakraščių.'),
  (@b23, 26, 16, 'VIEŠPATIE, bėdoje jie aplankė tave, jie liejo maldą, kai tavo bausmė buvo ant jų.'),
  (@b23, 26, 17, 'Kaip nėščia moteris artėjant jos gimdymui yra skausmuose ir šaukia savo skausmuose, tokie mes buvome tavo akyse, o VIEŠPATIE.'),
  (@b23, 26, 18, 'Mes buvome nėšti, buvome skausmuose, mes tarsi pagimdėme vėją; mes neįvykdėme žemėje jokio išlaisvinimo; nei pasaulio gyventojai nekrito.'),
  (@b23, 26, 19, 'Tavo mirusieji gyvens, kartu su mano mirusiu kūnu jie kelsis. Pabuskite ir giedokite, gyvenantys dulkėse; nes tavo rasa yra kaip žolių rasa, ir žemė išmes mirusiuosius.'),
  (@b23, 26, 20, 'Ateik, mano tauta, įeik į savo kambarius ir užrakink savo duris paskui save; pasislėpk tarsi trumpam akimirksniui, kol praeis pasipiktinimas.'),
  (@b23, 26, 21, 'Nes štai VIEŠPATS išeina iš savo vietos bausti žemės gyventojų už jų neteisybę; žemė irgi atidengs savo kraują ir nebeslėps savo užmuštųjų“.'),
  (@b23, 27, 1, 'Tą dieną VIEŠPATS savo sunkiu, dideliu ir stipriu kalaviju nubaus leviataną, prasiskverbiančią gyvatę, tai yra, leviataną, tą susirietusią gyvatę; ir jis nužudys slibiną, esantį jūroje.'),
  (@b23, 27, 2, 'Tą dieną giedokite jam, raudono vyno vynuogynui.'),
  (@b23, 27, 3, '„Aš, VIEŠPATS, jį saugoju; kiekvieną akimirką jį laistau; kad jam kas nepakenktų, naktį ir dieną jį saugau.'),
  (@b23, 27, 4, 'Nėra manyje įtūžio; kas nukreiptų prieš mane erškėčius ir usnis mūšyje? Aš praeičiau pro juos, aš juos kartu sudeginčiau.'),
  (@b23, 27, 5, 'Arba tegul jis nusitveria mano stiprybę, kad darytų taiką su manimi; ir jis darys taiką su manimi“.'),
  (@b23, 27, 6, 'Jis padarys, kad atėjusieji iš Jokūbo įleis šaknis; Izraelis žydės ir pumpuruos, ir pasaulio paviršių pripildys vaisių.'),
  (@b23, 27, 7, 'Ar jis jį mušė, kaip jis mušė jo mušėjus? Ar jis nužudytas pagal žudynes tų, kurie yra jo nužudyti?'),
  (@b23, 27, 8, 'Kai jis išsprogsta, tu bylinėsiesi su juo saikingai; jis sulaiko savo žvarbų vėją rytų vėjo dieną.'),
  (@b23, 27, 9, 'Taigi tuo bus nuvalyta Jokūbo neteisybė; ir šis yra visas vaisius jo nuodėmei pašalinti: kai jis padarys visus aukuro akmenis kaip sutrupintus kalkakmenius, giraitės ir atvaizdai nebestovės.'),
  (@b23, 27, 10, 'Tačiau sutvirtintas miestas bus tuščias, apleista buveinė, ir paliktas kaip dykuma; ten ganysis veršis, ten jis atsiguls ir nuės jo šakas.'),
  (@b23, 27, 11, 'Kai jo šakos nudžius, jos bus nulaužtos; ateis moterys ir jas uždegs; nes tai tauta, neturinti supratimo; todėl jų nepasigailės tas, kuris juos padarė, ir neparodys jiems palankumo tas, kuris juos suformavo.'),
  (@b23, 27, 12, 'Ir tą dieną atsitiks, kad VIEŠPATS kuls nuo upės vagos iki Egipto upelio, ir jūs būsite surinkti vienas po kito, o Izraelio vaikai.'),
  (@b23, 27, 13, 'Ir tą dieną įvyks, kad bus pučiama didžiu trimitu, ir ateis bepražūstantys Asirijos šalyje ir atstumtieji Egipto šalyje, ir šlovins VIEŠPATĮ šventajame kalne Jeruzalėje.'),
  (@b23, 28, 1, 'Vargas išdidumo vainikui, Efraimo girtuokliams, kurio šlovingas grožis yra vystanti gėlė, esanti ant riebių slėnių galvos tų, kurie yra vyno įveikti!'),
  (@b23, 28, 2, 'Štai Viešpats turi stiprųjį ir galingąjį, kuris kaip audringa kruša ir kaip naikinanti audra, kaip užliejantis galingų vandenų potvynis ranka nublokš ant žemės.'),
  (@b23, 28, 3, 'Išdidumo vainikas, Efraimo girtuokliai, bus mindomi po kojomis;'),
  (@b23, 28, 4, 'ir šlovingas grožis, esantis ant riebaus slėnio galvos, bus vystanti gėlė ir kaip skubotas vaisius prieš vasarą, kurį pamatęs suvalgo į jį bežiūrintysis, kol šis dar yra jo rankoje.'),
  (@b23, 28, 5, 'Tą dieną kariuomenių VIEŠPATS bus šlovės vainikas, grožio diadema savo tautos likučiui'),
  (@b23, 28, 6, 'ir teismo dvasia tam, kuris sėdasi teisti, ir stiprybė tiems, kurie nukreipia mūšį vartų link.'),
  (@b23, 28, 7, 'Bet taipogi jie suklydo nuo vyno, ir nuo stipraus gėrimo yra nuklydę iš kelio; kunigas ir pranašas klysta nuo stipraus gėrimo, jie yra vyno praryti, jie yra nuklydę iš kelio nuo stipraus gėrimo; jie klysta regėjime, jie suklumpa teisme.'),
  (@b23, 28, 8, 'Nes visi stalai pilni vėmalų ir nešvarumų, jog nėra švarios vietos.'),
  (@b23, 28, 9, 'Ką jis pamokys pažinimo? Kam jis duos suprasti mokslą? Nujunkytiems nuo pieno, atitrauktiems nuo krūtų.'),
  (@b23, 28, 10, 'Nes prisakymas turi būti po prisakymo, prisakymas po prisakymo; eilutė po eilutės, eilutė po eilutės; čia truputį, ten truputį;'),
  (@b23, 28, 11, 'nes mikčiojančiomis lūpomis ir kita kalba jis kalbės šitai tautai.'),
  (@b23, 28, 12, 'Kuriai jis pasakė: „Tai poilsis, kuriuo galite duoti pailsėti pavargusiems; ir tai atgaiva“; tačiau jie nenorėjo klausyti.'),
  (@b23, 28, 13, 'Bet VIEŠPATIES žodis jiems buvo prisakymas po prisakymo, prisakymas po prisakymo; eilutė po eilutės, eilutė po eilutės; čia truputį, ten truputį; kad jie eitų ir pargriūtų atbuli, ir susikultų, ir įsipainiotų, ir būtų sugauti.'),
  (@b23, 28, 14, 'Todėl klausykite VIEŠPATIES žodžio, jūs, išjuokėjai, kurie valdote šitą tautą, esančią Jeruzalėje.'),
  (@b23, 28, 15, 'Kadangi jūs sakėte: „Mes sudarėme sandorą su mirtimi, ir su pragaru sudarėme sutartį; kai sunaikinantis rimbas praeis, jis neateis ant mūsų; nes melą padarėme savo prieglobsčiu ir pasislėpėme po melagyste“;'),
  (@b23, 28, 16, 'todėl taip sako Viešpats DIEVAS: „Štai aš dedu Sione pamatui akmenį, išbandytą akmenį, brangų kertinį akmenį, tikrą pamatą: kas tiki, nesiskubins.'),
  (@b23, 28, 17, 'Taip pat aš teismą paskirsiu pagal virvę, o teisumą – pagal svambalą; ir kruša nušluos melo prieglobstį, ir vandenys užlies slaptavietę.'),
  (@b23, 28, 18, 'Ir bus panaikinta jūsų sandora su mirtimi, ir jūsų sutartis su pragaru neišsilaikys; kai sunaikinantis rimbas praeis, jūs būsite jo sutrypti.'),
  (@b23, 28, 19, 'Nuo to laiko, kai jis išeis, jis jus pagaus; nes jis praeidinės rytas po ryto, dieną bei naktį; ir bus nerimas vien sužinojus žinią“.'),
  (@b23, 28, 20, 'Nes lova per trumpa, kad žmogus galėtų joje išsitiesti; ir apdangalas per siauras, kad galėtų į jį įsivynioti.'),
  (@b23, 28, 21, 'Nes VIEŠPATS pakils kaip Peracimo kalne, jis užsirūstins kaip Gibeono slėnyje, kad jis darytų savo darbą, savo neįprastą darbą; ir įvykdytų savo veiksmą, sau neįprastą veiksmą.'),
  (@b23, 28, 22, 'Taigi dabar nebūkite pašaipūnai, kad nesustiprėtų jūsų pančiai; nes aš girdėjau iš Viešpaties, kariuomenių DIEVO, sunaikinimą, nulemtą visai žemei.'),
  (@b23, 28, 23, 'Pakreipkite ausį ir išgirskite mano balsą; klausykite ir išgirskite mano kalbą.'),
  (@b23, 28, 24, 'Argi artojas visą dieną aria, kad sėtų? Ar jis praaria ir sutrupina savo dirvos grumstus?'),
  (@b23, 28, 25, 'Argi sulyginęs jos paviršių jis neišbarsto vikių, nebarsto kmynų, neberia rinktinių kviečių ir paskirtų miežių, ir rugių į jų vietą?'),
  (@b23, 28, 26, 'Nes jo Dievas jį pamoko apdairumo ir jį moko.'),
  (@b23, 28, 27, 'Nes vikiai nekuliami kuliamaisiais įrankiais, ir vežimo ratų nesukioja ant kmynų; bet vikius iškulia lazda, o kmynus – pagaliu.'),
  (@b23, 28, 28, 'Duonos javus sutrina; nes niekas jų visą laiką nekulia ir nedaužo savo vežimo ratu, ir jų netrina raiteliais.'),
  (@b23, 28, 29, 'Tai irgi išeina nuo kariuomenių VIEŠPATIES, kuris yra nuostabus patarimais ir puikus darbais.'),
  (@b23, 29, 1, 'Vargas Arieliui, Arieliui, miestui, kur gyveno Dovydas! Dėkite metus prie metų; tegul jie pjauna aukas.'),
  (@b23, 29, 2, 'Bet aš prispausiu Arielį, ir ten bus nusiminimas bei sielvartas; ir jis man bus kaip Arielis.'),
  (@b23, 29, 3, 'Aš stovyklausiu prieš tave aplinkui, apgulsiu tave kalnu ir iškelsiu prieš tave fortus.'),
  (@b23, 29, 4, 'Ir tu būsi pažemintas ir kalbėsi iš žemės, ir tavo kalba bus tyli iš dulkių, ir tavo balsas bus kaip turinčiojo namų dvasią, iš žemės, ir tavo kalba šnibždės iš dulkių.'),
  (@b23, 29, 5, 'Be to, tavo svetimšalių daugybė bus kaip smulkios dulkės, ir baisiųjų daugybė bus kaip praskrendantys pelai; taip, tai bus akimirksniu, staiga.'),
  (@b23, 29, 6, 'Kariuomenių VIEŠPATIES tu būsi aplankytas su griausmu, žemės drebėjimu ir dideliu triukšmu, su vėtra, audra ir ryjančios ugnies liepsna.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b23, 29, 7, 'Kaip nakties regėjimo sapnas bus gausybė visų tautų, kurios kariauja prieš Arielį, būtent visų kariaujančių prieš jį bei jo sutvirtinimus, ir kurios jį prispaudžia.'),
  (@b23, 29, 8, 'Bus taip, kaip kad alkanas sapnuoja, kad jis valgo; bet jis pabunda, ir jo siela tuščia; arba kaip kad ištroškęs sapnuoja, kad jis geria; bet jis pabunda ir štai, yra nusilpęs, ir jo siela išalkusi; taip bus daugybei visų tautų, kariaujančių prieš Siono kalną.'),
  (@b23, 29, 9, 'Sustokite ir stebėkitės; šūkaukite ir šaukite; jie girti, bet ne nuo vyno; jie svirduliuoja, bet ne nuo stipraus gėrimo.'),
  (@b23, 29, 10, 'Nes VIEŠPATS išliejo ant jūsų gilaus miego dvasią ir užmerkė jūsų akis; pranašus ir jūsų valdovus, regėtojus jis apdengė.'),
  (@b23, 29, 11, 'Ir regėjimas apie visa jums tapo kaip žodžiai užantspauduotos knygos, kurią paduoda mokytajam, sakydami: „Meldžiu tave, paskaityk tai“; o jis sako: „Negaliu, nes ji užantspauduota“.'),
  (@b23, 29, 12, 'Ir paduoda knygą nemokytajam, sakydami: „Meldžiu tave, paskaityk tai“; o jis sako: „Aš neišmokytas“.'),
  (@b23, 29, 13, 'Todėl Viešpats tarė: „Kadangi šita tauta artinasi prie manęs savo burna, ir savo lūpomis mane gerbia, bet savo širdis atitraukė toli nuo manęs, ir jų baimė man yra mokoma žmonių prisakymais,'),
  (@b23, 29, 14, 'todėl štai aš toliau darysiu nuostabų darbą šioje tautoje – nuostabų darbą ir stebuklą; nes jų išmintingųjų išmintis pražus ir jų protingųjų supratimas pasislėps“.'),
  (@b23, 29, 15, 'Vargas tiems, kurie siekia giliai paslėpti savo ketinimą nuo VIEŠPATIES, ir jų darbai yra tamsoje, ir jie sako: „Kas mus mato ir kas mus žino?“'),
  (@b23, 29, 16, 'Tikrai tai, kad jūs apverčiate dalykus aukštyn kojomis, bus laikoma puodžiaus moliu; nes argi dirbinys sakys apie tą, kuris jį padarė: „Jis manęs nepadarė“? Ar suformuotas daiktas sakys apie tą, kuris jį suformavo: „Jis nieko nesupranta“?'),
  (@b23, 29, 17, 'Argi ne po labai trumpo laiko Libanas bus paverstas vaisingu lauku, o vaisingas laukas bus laikomas mišku?'),
  (@b23, 29, 18, 'Ir tą dieną kurčiai girdės knygos žodžius, ir aklųjų akys praregės iš miglotumo ir iš tamsos.'),
  (@b23, 29, 19, 'Taip pat ir romieji dar labiau džiaugsis VIEŠPAČIU, ir beturčiai tarp žmonių džiūgaus Izraelio Šventuoju.'),
  (@b23, 29, 20, 'Nes baisieji paversti niekais, ir pašaipūnai sunaikinti, ir visi, kurie tyko dėl neteisybės, iškirsti;'),
  (@b23, 29, 21, 'kurie padaro žmogų pažeidėju dėl žodžio ir spendžia spąstus tam, kuris bara vartuose, ir atstumia teisųjį kaip nieką.'),
  (@b23, 29, 22, 'Todėl taip sako VIEŠPATS, kuris atpirko Abraomą, apie Jokūbo namus: „Jokūbas dabar nebus sugėdytas, ir dabar jo veidas nebeišblykš.'),
  (@b23, 29, 23, 'Bet kai jis matys savo vaikus, mano rankų darbą, savo tarpe, jie pašvęs mano vardą ir pašvęs Jokūbo Šventąjį, ir bijos Izraelio Dievo.'),
  (@b23, 29, 24, 'Taip pat ir tie, kurie klydo dvasioje, įgis supratimą, o tie, kurie murmėjo, mokysis mokslo“.'),
  (@b23, 30, 1, '„Vargas maištaujantiems vaikams, – sako VIEŠPATS, – kurie ima patarimą, bet ne iš manęs; ir kurie dengia apdangalu, bet ne mano dvasios, kad jie pridėtų nuodėmę prie nuodėmės;'),
  (@b23, 30, 2, 'kurie eina, kad leistųsi į Egiptą, mano burnos nepasiklausę, kad sustiprintų save faraono stiprybe ir pasitikėtų Egipto šešėliu!'),
  (@b23, 30, 3, 'Todėl faraono stiprybė bus jūsų gėda ir pasitikėjimas Egipto šešėliu – jūsų negarbe.'),
  (@b23, 30, 4, 'Nes jo kunigaikščiai buvo Coane ir jo pasiuntiniai atėjo į Hanesą.'),
  (@b23, 30, 5, 'Jie visi gėdijosi tauta, kuri negalėjo nei duoti jiems naudos, nei būti pagalba nei nauda, o tik gėda ir priekaištu“.'),
  (@b23, 30, 6, 'Pietų žvėrių našta: į vargo ir skausmo šalį, iš kurios ateina jaunas ir senas liūtas, angis ir ugninga skraidanti gyvatė, jie gabens ant jaunų asilų pečių savo turtus ir ant kupranugarių kuprų savo lobius tautai, kuri jiems neduos naudos.'),
  (@b23, 30, 7, 'Nes egiptiečių pagalba bus bergždžia ir betikslė; todėl šaukiau apie tai: „Jų stiprybė – ramiai sėdėti“.'),
  (@b23, 30, 8, 'Dabar eik, užrašyk tai plokštėje jų akivaizdoje ir įrašyk tai knygoje, kad tai būtų ateinančiam laikui per amžių amžius;'),
  (@b23, 30, 9, 'kad ji yra maištaujanti tauta, meluojantys vaikai, vaikai, kurie nenori klausyti VIEŠPATIES įstatymo;'),
  (@b23, 30, 10, 'kurie sako regėtojams: „Neregėkite“; ir pranašams: „Nepranašaukite mums teisingų dalykų, kalbėkite mums tai, kas malonu, pranašaukite apgavystes;'),
  (@b23, 30, 11, 'nukrypkite nuo kelio, pasukite iš tako, pašalinkite Izraelio Šventąjį iš mūsų akivaizdos“.'),
  (@b23, 30, 12, 'Todėl taip sako Izraelio Šventasis: „Kadangi jūs niekinate šitą žodį ir pasitikite engimu, iškreiptumu, ir tuo remiatės;'),
  (@b23, 30, 13, 'todėl šita neteisybė jums bus kaip besirengianti griūti pralauža, išsigaubusi aukštoje sienoje, kurios lūžis ateis staiga, per akimirką.'),
  (@b23, 30, 14, 'Ir jis ją pralauš kaip sudaužomas puodžių indas, kuris sutrupinamas; jis nepasigailės; taip, kad neberas jo sutrupėjime šukės ugniai paimti iš židinio ar vandens pasisemti iš duobės“.'),
  (@b23, 30, 15, 'Nes taip sako Viešpats DIEVAS, Izraelio Šventasis: „Sugrįžimu ir poilsiu jūs būsite išgelbėti; tylume ir pasitikėjime bus jūsų stiprybė; o jūs nenorėjote.'),
  (@b23, 30, 16, 'Bet jūs sakėte: ‘Ne; nes mes bėgsime ant žirgų’; todėl jūs bėgsite; ir: ‘Ant greitųjų josime’; todėl greiti bus tie, kurie jus vysis.'),
  (@b23, 30, 17, 'Vienas tūkstantis bėgs vienam barant; penkiems barant jūs bėgsite, kol liksite kaip švyturys ant kalno viršūnės ir kaip vėliava ant kalvos“.'),
  (@b23, 30, 18, 'Ir todėl VIEŠPATS lauks, kad jis būtų jums maloningas, ir todėl jis bus išaukštintas, kad jis jūsų pasigailėtų; nes VIEŠPATS yra teismo Dievas; palaiminti visi, kurie jo laukia.'),
  (@b23, 30, 19, 'Nes tauta gyvens Sione, Jeruzalėje; tu nebeverksi; jis bus tau labai maloningas tau šaukiant balsu; kai jis tai išgirs, jis tau atsilieps.'),
  (@b23, 30, 20, 'Ir nors Viešpats jums duoda nelaimės duonos ir priespaudos vandens, tačiau tavo mokytojai daugiau nebebus nukelti į kampą, bet tavo akys matys tavo mokytojus;'),
  (@b23, 30, 21, 'ir tavo ausys girdės žodį tau už nugaros, sakantį: „Tai yra kelias, vaikščiokite juo“, kai pasukate į dešinę ir kai pasukate į kairę.'),
  (@b23, 30, 22, 'Taip pat jūs suteršite savo sidabrinių raižytų atvaizdų dangą ir savo nulietų auksinių atvaizdų papuošalą; tu juos išmesi kaip mėnesinių skudurą; tu jiems pasakysi: „Eik iš čia“.'),
  (@b23, 30, 23, 'Tada jis duos tavo sėklos lietų, kad ja apsėtum dirvą; ir duonos iš žemės prieaugio, ir jis bus riebus ir gausus; tą dieną tavo galvijai ganysis plačiose ganyklose.'),
  (@b23, 30, 24, 'Taip pat jaučiai ir jauni asilai, kurie apdirba dirvą, ės gryną pašarą, išvėtytą kastuvu ir vėtykle.'),
  (@b23, 30, 25, 'Ir ant kiekvieno aukšto kalno ir ant kiekvienos aukštos kalvos bus upės ir vandenų srovės didžiųjų žudynių dieną, kai bokštai grius.'),
  (@b23, 30, 26, 'Ir mėnulio šviesa bus kaip saulės šviesa, ir saulės šviesa bus septyneriopa, kaip septynių dienų šviesa, tą dieną, kai VIEŠPATS aptvarstys savo tautos spragą ir pagydys jų žaizdos kirtį.'),
  (@b23, 30, 27, 'Štai VIEŠPATIES vardas ateina iš toli, degantis savo pykčiu, ir sunki jo našta; jo lūpos pilnos pasipiktinimo, ir jo liežuvis kaip ryjanti ugnis;'),
  (@b23, 30, 28, 'o jo kvapas, kaip užliejanti srovė, sieks iki vidurio kaklo, kad sijotų tautas tuštybės sietu; ir tautų nasruose bus juos klaidinantis apynasris.'),
  (@b23, 30, 29, 'Jūsų giesmė bus kaip naktį, kai laikomasi šventų iškilmių; ir širdies džiaugsmas kaip tam, kuris eina su dūda, kad ateitų į VIEŠPATIES kalną, pas Izraelio Galingąjį.'),
  (@b23, 30, 30, 'Ir VIEŠPATS duos išgirsti savo šlovingą balsą ir parodys savo nusileidžiančią ranką su savo pykčio įtūžiu ir ryjančios ugnies liepsna, su išsklaidymu, audra ir krušos ledokšniais.'),
  (@b23, 30, 31, 'Nes VIEŠPATIES balsu bus sumuštas asiras, kuris smogė lazda.'),
  (@b23, 30, 32, 'Ir visur, kur pereis pagrįsta lazda, kurią VIEŠPATS nuleis ant jo, tai bus su būgneliais bei arfomis; ir sudrebinimo mūšiuose jis kovos su ja.'),
  (@b23, 30, 33, 'Nes jau seniai yra paruoštas Tofetas; taip, jis paruoštas karaliui; jis padarė jį gilų ir platų; jo laužas yra ugnis ir daug malkų; VIEŠPATIES kvapas kaip sieros srovė jį uždegs.'),
  (@b23, 31, 1, 'Vargas tiems, kurie leidžiasi į Egiptą pagalbos; ir remiasi žirgais, ir pasitiki vežimais, nes jų daug, ir raiteliais, nes jie labai stiprūs; bet jie nesikreipia į Izraelio Šventąjį nei VIEŠPATIES neieško!'),
  (@b23, 31, 2, 'Tačiau jis irgi išmintingas ir atves nelaimę, ir savo žodžių neatšauks; bet pakils prieš piktadarių namus ir prieš pagalbą tų, kurie daro neteisybę.'),
  (@b23, 31, 3, 'Na, o egiptiečiai yra žmonės, o ne Dievas; ir jų žirgai – kūnas, o ne dvasia. Kai VIEŠPATS išties savo ranką, pargrius padėjėjas ir kris tas, kuriam padedama, ir jie visi kartu pražus.'),
  (@b23, 31, 4, 'Nes taip man pasakė VIEŠPATS: „Kaip liūtas ir jaunas liūtas, riaumojantis ant savo grobio, kai šaukia prieš jį piemenų daugybė, jis neišsigąsta jų balso ir nuo jų triukšmo nesižemina; taip kariuomenių VIEŠPATS nužengs kovoti dėl Siono kalno ir dėl jo kalvos.'),
  (@b23, 31, 5, 'Kaip paukščiai skraido, taip kariuomenių VIEŠPATS gins Jeruzalę; taipogi gindamas ją išvaduos ir praeidamas ją išsaugos.'),
  (@b23, 31, 6, 'Atsigręžkite į tą, prieš kurį Izraelio vaikai labai maištavo.'),
  (@b23, 31, 7, 'Nes tą dieną kiekvienas numes šalin savo sidabrinius stabus ir savo auksinius stabus, kuriuos jūsų rankos jums padarė nuodėmei.'),
  (@b23, 31, 8, 'Tada asiras kris ne nuo galiūno kalavijo, ir ne prastuolio kalavijas jį rys; bet jis bėgs nuo kalavijo, ir jo jaunuoliai bus pakrikę.'),
  (@b23, 31, 9, 'Ir iš baimės jis perbėgs į savo tvirtovę, ir jo kunigaikščiai išsigąs vėliavos“, – sako VIEŠPATS, kurio ugnis yra Sione, ir jo krosnis Jeruzalėje.'),
  (@b23, 32, 1, 'Štai karalius karaliaus teisumu, ir kunigaikščiai valdys teismu.'),
  (@b23, 32, 2, 'Ir kiekvienas bus kaip slėptuvė nuo vėjo ir kaip prieglauda nuo audros; kaip vandens upės sausumoje, kaip didžiulės uolos šešėlis nuvargusioje žemėje.'),
  (@b23, 32, 3, 'Ir matančiųjų akys nebus aptemusios, ir girdinčiųjų ausys klausysis.'),
  (@b23, 32, 4, 'Taip pat ir skubotųjų širdis supras pažinimą, ir mikčiojančių liežuvis bus pasiruošęs aiškiai kalbėti.'),
  (@b23, 32, 5, 'Niekšo nebevadins kilniu, ir apie šykštuolį nebesakys, kad jis dosnus.'),
  (@b23, 32, 6, 'Nes niekšas kalba niekšybes, ir jo širdis rezga neteisybę, kad vykdytų veidmainystę ir ištartų prieš VIEŠPATĮ kas klaidinga; kad paliktų alkano sielą tuščią, ir jis padaro, kad trokštančiajam pritrūktų gėrimo.'),
  (@b23, 32, 7, 'Ir šykštuolio priemonės piktos; jis sumano nedorų planų, kad pražudytų vargšą melagingais žodžiais, net kai beturtis kalba teisingai.'),
  (@b23, 32, 8, 'Bet kilnusis sumano, kas kilnu, ir stovės tuo, kas kilnu.'),
  (@b23, 32, 9, 'Kelkitės, nerūpestingos moterys; klausykitės mano balso jūs, nerūpestingos dukterys; atsukite ausį mano kalbai.'),
  (@b23, 32, 10, 'Daug dienų ir metų nerimausite jūs, nerūpestingos moterys; nes baigsis vynuogių derlius, rinkimas nebeateis.'),
  (@b23, 32, 11, 'Drebėkite, moterys, kurios neturite rūpesčių; nerimaukite jūs, nerūpestingos; nusivilkite ir apsinuoginkite, ir apsijuoskite strėnas ašutine.'),
  (@b23, 32, 12, 'Jos gedės dėl spenių, dėl geistinų laukų, dėl vaisingo vynmedžio.'),
  (@b23, 32, 13, 'Ant mano tautos šalies užeis erškėčiai ir usnys; taip, ant visų džiaugsmo namų džiaugsmingame mieste;'),
  (@b23, 32, 14, 'nes rūmai bus palikti; miesto minia bus palikta; fortai ir bokštai bus lindynėmis per amžius, laukinių asilų džiaugsmu, kaimenių ganykla;'),
  (@b23, 32, 15, 'iki kol bus išlieta ant mūsų Dvasia iš aukštybės, ir dykuma bus vaisingas laukas, o vaisingas laukas bus laikomas mišku.'),
  (@b23, 32, 16, 'Tada teismas gyvens dykumoje, ir teisumas pasiliks vaisingame lauke.'),
  (@b23, 32, 17, 'Ir teisumo darbas bus taika; ir teisumo padarinys – ramybė ir saugumas per amžius.'),
  (@b23, 32, 18, 'Ir mano tauta gyvens taikioje gyvenamoje vietoje ir tikrose buveinėse, ir ramiose poilsio vietose;'),
  (@b23, 32, 19, 'kai kruša kris ant miško, ir miestas bus žemas žemoje vietoje.'),
  (@b23, 32, 20, 'Palaiminti jūs, kurie sėjate prie visų vandenų, kurie išsiunčiate ten jaučių ir asilų kojas.'),
  (@b23, 33, 1, 'Vargas tau, kuris plėši, bet pats nebuvai apiplėštas; ir klastingai besielgiantis, su kuriuo klastingai nepasielgė! Kai paliausi plėšti, tu būsi apiplėštas; ir kai nustosi elgtis klastingai, su tavimi klastingai pasielgs.'),
  (@b23, 33, 2, 'O VIEŠPATIE, būk mums maloningas; mes tavęs laukėme; būk jų ranka kas rytą, ir mūsų išgelbėjimas bėdos metu.'),
  (@b23, 33, 3, 'Nuo sumišimo triukšmo pabėgo tautos; tau keliantis išsisklaidė tautybės.'),
  (@b23, 33, 4, 'Ir jūsų grobį surinks, kaip vikšras surenka; kaip skėriai lakioja ten ir atgal, taip jis lėks ant jų.'),
  (@b23, 33, 5, 'VIEŠPATS išaukštintas; nes jis gyvena aukštybėje; jis pripildė Sioną teismo ir teisumo.'),
  (@b23, 33, 6, 'Išmintis ir pažinimas bus tavo laikų tvirtumas ir išgelbėjimo stiprumas; VIEŠPATIES baimė yra jo lobis.'),
  (@b23, 33, 7, 'Štai jų narsuoliai šauks lauke; taikos pasiuntiniai karčiai verks.'),
  (@b23, 33, 8, 'Ištuštėjo vieškeliai, nebeliko keliautojų; jis sulaužė sandorą, išniekino miestus, nepaiso žmonių.'),
  (@b23, 33, 9, 'Žemė gedi ir nyksta; Libanas susigėdęs ir nukirstas; Šaronas kaip dykuma; Bašanas ir Karmelis nukrato savo vaisius.'),
  (@b23, 33, 10, '„Dabar aš kelsiuos, – sako VIEŠPATS, – dabar aš būsiu išaukštintas, dabar save iškelsiu.'),
  (@b23, 33, 11, 'Jūs pastosite pelais, jūs pagimdysite ražieną; jūsų kvapas jus praris kaip ugnis.'),
  (@b23, 33, 12, 'Ir tautos bus kaip degančios kalkės; kaip sukapoti erškėčiai jos bus sudegintos ugnyje.'),
  (@b23, 33, 13, 'Išgirskite, esantys toli, ką aš padariau; ir jūs, esantys arti, pripažinkite mano galią“.'),
  (@b23, 33, 14, 'Sione nusidėjėliai išsigandę; šiurpas užklupo veidmainius. Kas iš mūsų gali gyventi prie ryjančios ugnies? Kas iš mūsų gali gyventi prie amžinų deginimų?'),
  (@b23, 33, 15, 'Kas vaikšto teisiai ir kalba tiesiai; kas niekina engimo pelną, kas nusipurto rankas, kad neimtų kyšių, kas užsikemša ausis, kad nesiklausytų apie kraują, ir užmerkia akis, kad nežiūrėtų į pikta;'),
  (@b23, 33, 16, 'tas gyvens aukštumoje; jo apsaugos vieta bus uolų tvirtovės; jam duos duonos; jo vandenys bus užtikrinti.'),
  (@b23, 33, 17, 'Tavo akys matys karalių jo grožyje; jos matys labai toli esančią šalį.'),
  (@b23, 33, 18, 'Tavo širdis mąstys apie siaubą: „Kur yra raštininkas? Kur yra gavėjas? Kur tas, kuris skaičiavo bokštus?“'),
  (@b23, 33, 19, 'Tu nebematysi nuožmios tautos, tautos su gilia tau nesuvokiama kalba, su mikčiojančiu, tau nesuprantamu liežuviu.'),
  (@b23, 33, 20, 'Žvelk į Sioną, mūsų iškilmių miestą; tavo akys matys Jeruzalę, ramią gyvenamą vietą, padangtę, kuri nebus nugriauta; nei vienas jos kuolas niekada nebebus ištrauktas ir nei viena jos virvė nenutrūks.'),
  (@b23, 33, 21, 'Bet ten šlovingasis VIEŠPATS mums bus plačių upių, srovių vieta, kur neplauks joks irklinis laivas nei nepraplauks pro šalį didingas laivas.'),
  (@b23, 33, 22, 'Nes VIEŠPATS yra mūsų teisėjas, VIEŠPATS yra mūsų įstatymleidys, VIEŠPATS yra mūsų karalius; jis mus išgelbės.'),
  (@b23, 33, 23, 'Tavo laivavirvės atsileidusios; jos negali gerai sutvirtinti stiebo, jos negali išskleisti burės; tada bus dalinamas didelio grobio laimikis; luošieji ims laimikį.'),
  (@b23, 33, 24, 'Ir joks gyventojas nesakys: „Aš sergu“; čia gyvenančiai tautai bus atleista jų neteisybė.'),
  (@b23, 34, 1, 'Priartėkite, tautybės, klausytis; ir klausykite jūs, tautos; teišgirsta žemė ir visa, kas joje; pasaulis ir visa, kas gimsta iš jo.'),
  (@b23, 34, 2, 'Nes VIEŠPATIES pasipiktinimas yra ant visų tautų ir jo įtūžis ant visų jų kariuomenių; jis jas visiškai sunaikino, jis jas atidavė paskerdimui.'),
  (@b23, 34, 3, 'Jų užmuštieji bus išmesti, ir nuo jų lavonų pakils smarvė, ir kalnai sutirps nuo jų kraujo.'),
  (@b23, 34, 4, 'Ir visa dangaus kariuomenė sutirps, ir dangūs bus suvynioti kaip ritinys; ir visa jų kariuomenė nukris žemyn, kaip lapas krinta nuo vynmedžio, ir kaip figa krentanti nuo figmedžio.'),
  (@b23, 34, 5, 'Nes mano kalavijas bus nuplautas danguje; štai jis nusileis ant Idumėjos, ant mano prakeikimo tautos, teismui.'),
  (@b23, 34, 6, 'VIEŠPATIES kalavijas prisipildęs kraujo, aptekęs riebalais, avinėlių ir ožių krauju, avinų inkstų riebalais; nes VIEŠPATS turi auką Bocroje, dideles skerdynes Idumėjos šalyje.'),
  (@b23, 34, 7, 'Ir vienaragiai nužengs su jais ir jaučiai su buliais; ir jų šalis bus permirkusi kraujo, ir jų dulkės aptekusios taukais.'),
  (@b23, 34, 8, 'Nes tai VIEŠPATIES keršto diena ir atlyginimo metai dėl Siono ginčo.'),
  (@b23, 34, 9, 'Jos upeliai pavirs derva, ir jos dulkės – siera, ir jos šalis pavirs degančia derva.'),
  (@b23, 34, 10, 'Nei naktį, nei dieną ji neužges; amžinai kils jos dūmai; iš kartos į kartą ji liks dyka; niekas neis per ją per amžių amžius.'),
  (@b23, 34, 11, 'Bet ją pasisavins kormoranas ir baublys; taip pat pelėda ir varnas joje gyvens; ir jis išties ant jos sumaišties virvę ir tuštumos akmenis.'),
  (@b23, 34, 12, 'Jos kilminguosius pašauks į karalystę, bet ten nebus nei vieno, ir visi jos kunigaikščiai bus niekas.'),
  (@b23, 34, 13, 'Jos rūmai apaugs erškėčiais, jos tvirtovės dilgėlėmis ir gervuogėmis; ir ji bus slibinų buveine ir kiemu pelėdoms.'),
  (@b23, 34, 14, 'Dykumos laukiniai žvėrys susitiks su salos laukiniais žvėrimis, ir satyrai šauks vienas kitam; ten ilsėsis ir ūbaujanti pelėda bei ras sau poilsio vietą.'),
  (@b23, 34, 15, 'Ten susisuks savo lizdą didžioji pelėda ir dės kiaušinius, ir išperės, ir surinks savo prieglobstyje; ten susirinks ir maitvanagiai vienas prie kito.'),
  (@b23, 34, 16, 'Suieškokite VIEŠPATIES knygoje ir skaitykite; nei vieno iš jų netrūks, nei vienas nepasiges kito; nes mano burna tai įsakė, ir jo dvasia juos surinko.'),
  (@b23, 34, 17, 'Jis jiems metė burtą, ir jo ranka jiems ją padalino virve; jie turės ją savo nuosavybe per amžius, iš kartos į kartą jie gyvens joje.'),
  (@b23, 35, 1, 'Tyrlaukis ir nuošali vieta džiaugsis dėl jų; dykuma džiūgaus ir žydės kaip rožė.'),
  (@b23, 35, 2, 'Ji gausiai žydės ir džiaugsis džiūgaudama bei giedodama; Libano šlovė bus jai duota, Karmelio ir Šarono didybė, jie matys VIEŠPATIES šlovę ir mūsų Dievo didybę.'),
  (@b23, 35, 3, 'Sustiprinkite silpnas rankas ir sutvirtinkite silpnus kelius.'),
  (@b23, 35, 4, 'Tarkite esantiems baugščios širdies: „Būkite stiprūs, nebijokite; štai ateis jūsų Dievas kerštaudamas, tai yra, Dievas su atlygiu; jis ateis ir jus išgelbės“.'),
  (@b23, 35, 5, 'Tada atsimerks aklųjų akys, ir kurčiųjų ausys atsivers.'),
  (@b23, 35, 6, 'Tada raišas šokinės kaip elnias ir nebylio liežuvis giedos; nes vandenys ištrykš tyrlaukyje ir upeliai dykumoje.'),
  (@b23, 35, 7, 'Perdžiūvusi dirva pavirs tvenkiniu ir ištroškusi žemė – vandens šaltiniais; slibinų gyvenamoje vietoje, kur jie guli, bus žolė su nendrėmis ir vikšriais.'),
  (@b23, 35, 8, 'Ten bus vieškelis, kelias, ir bus vadinamas šventumo Keliu; juo neis nešvarusis; bet jis bus tiems; keliaujantys, nors ir kvailiai, nepaklys jame.'),
  (@b23, 35, 9, 'Ten nebus liūto, ir joks plėšrus žvėris neužeis ant jo, ten jo neužtiks; bet atpirktieji ten vaikščios;'),
  (@b23, 35, 10, 'ir VIEŠPATIES išpirktieji sugrįš ir ateis į Sioną su giesmėmis ir amžinu džiaugsmu ant savo galvų; jie įgis džiaugsmą ir linksmybę, o sielvartas ir dūsavimas pabėgs.'),
  (@b23, 36, 1, 'Na, o keturioliktais karaliaus Chezekijo metais įvyko, kad Asirijos karalius Sancheribas atėjo aukštyn prieš visus sutvirtintus Judos miestus ir juos paėmė.'),
  (@b23, 36, 2, 'Ir Asirijos karalius siuntė Rabšakę iš Lachišo į Jeruzalę pas karalių Chezekiją su didele kariuomene. Ir jis sustojo prie aukštutinio tvenkinio vandentiekio, vėlėjo lauko vieškelyje.'),
  (@b23, 36, 3, 'Tada pas jį išėjo Hilkijo sūnus Eljakimas, kuris buvo namų viršininkas, ir raštininkas Šebna bei metraštininkas Joachas, Asafo sūnus.'),
  (@b23, 36, 4, 'Ir Rabšakė jiems tarė: „Sakykite Chezekijui: Taip sako didysis karalius, Asirijos karalius: ‘Kas tai per pasitikėjimas, kuriuo tu pasitiki?'),
  (@b23, 36, 5, '„Aš sakau, – tu sakai (bet tai vien tik tušti žodžiai), – aš turiu patarimą ir stiprybę kariauti“; kuo tu dabar pasitiki, kad maištauji prieš mane?'),
  (@b23, 36, 6, 'Štai tu pasitiki Egiptu, šita sulūžusia nendrine lazda; jei kas į ją remiasi, tam ji įsminga į ranką ir ją perduria; toks yra faraonas, Egipto karalius, visiems, kurie juo pasitiki.'),
  (@b23, 36, 7, 'Bet jei tu man sakysi: „Mes pasitikime VIEŠPAČIU, mūsų Dievu“; ar tai ne jis, kurio aukštumas ir kurio aukurus Chezekijas pašalino ir pasakė Judai bei Jeruzalei: „Jūs garbinkite prie šito aukuro“?'),
  (@b23, 36, 8, 'Taigi dabar, meldžiu tave, pasižadėk mano valdovui, Asirijos karaliui, ir aš tau duosiu du tūkstančius žirgų, jei tu iš savo pusės pajėgsi susodinti ant jų raitelius.'),
  (@b23, 36, 9, 'Tad kaip tu nukreipsi mano valdovo mažiausių tarnų vieno vado veidą ir pasitikėsi Egiptu dėl vežimų ir dėl raitelių?'),
  (@b23, 36, 10, 'Ir argi aš atėjau aukštyn be VIEŠPATIES prieš šitą šalį jos sunaikinti? VIEŠPATS man sakė: Eik aukštyn prieš šitą šalį ir ją sunaikink’“.'),
  (@b23, 36, 11, 'Tada Eljakimas, Šebna ir Joachas tarė Rabšakei: „Kalbėk, meldžiu tave, savo tarnams sirų kalba, nes mes ją suprantame; ir nekalbėk mums žydų kalba į ausis tautos, kuri yra ant sienos“.'),
  (@b23, 36, 12, 'Bet Rabšakė tarė: „Argi mano valdovas mane siuntė pas tavo valdovą ir pas tave kalbėti šituos žodžius? Argi jis nesiuntė manęs pas žmones, kurie sėdi ant sienos, kad jie su jumis valgytų savo išmatas ir gertų savo šlapimą?“'),
  (@b23, 36, 13, 'Tada Rabšakė atsistojo ir garsiu balsu šaukė žydų kalba, tardamas: „Klausykite didžiojo karaliaus, Asirijos karaliaus, žodžių.'),
  (@b23, 36, 14, 'Taip sako karalius: Tegul Chezekijas jūsų neapgauna; nes jis negalės jūsų išvaduoti.'),
  (@b23, 36, 15, 'Ir teneskatina Chezekijas jūsų pasitikėti VIEŠPAČIU, sakydamas: ‘VIEŠPATS tikrai mus išvaduos; šitas miestas nebus atiduotas į Asirijos karaliaus ranką’.'),
  (@b23, 36, 16, 'Neklausykite Chezekijo; nes taip sako Asirijos karalius: ‘Sudarykite su manimi sutartį per dovaną ir išeikite pas mane; ir kiekvienas valgykite nuo savo vynmedžio ir kiekvienas nuo savo figmedžio, ir kiekvienas gerkite vandenis iš savo rezervuaro;'),
  (@b23, 36, 17, 'kol aš atvyksiu ir jus paimsiu į šalį, į tokią, kaip jūsų šalį, į javų ir vyno šalį, į duonos ir vynuogynų šalį’.'),
  (@b23, 36, 18, 'Saugokitės, kad Chezekijas jūsų neįtikintų, sakydamas: ‘VIEŠPATS mus išvaduos’. Ar kuris iš tautų dievų išvadavo savo šalį iš Asirijos karaliaus rankos?'),
  (@b23, 36, 19, 'Kur yra Hamato ir Arpado dievai? Kur Sefarvaimo dievai? Ar jie išvadavo Samariją iš mano rankos?'),
  (@b23, 36, 20, 'Kuris yra iš šitų šalių visų dievų, kuris išvadavo savo šalį iš mano rankos, kad VIEŠPATS išvaduotų Jeruzalę iš mano rankos?’“'),
  (@b23, 36, 21, 'Bet jie tylėjo ir jam neatsakė nei žodžio, nes karaliaus įsakymas buvo, sakant: „Neatsakykite jam“.'),
  (@b23, 36, 22, 'Tada Hilkijo sūnus Eljakimas, namų viršininkas, ir raštininkas Šebna bei metraštininkas Joachas, Asafo sūnus, atėjo pas Chezekiją su perplėštais drabužiais ir jam pasakė Rabšakės žodžius.'),
  (@b23, 37, 1, 'Ir įvyko, kai karalius Chezekijas tai išgirdo, jis perplėšė savo drabužius, apsigaubė ašutine ir nuėjo į VIEŠPATIES namus.'),
  (@b23, 37, 2, 'Ir jis siuntė namų viršininką Eljakimą, raštininką Šebną ir kunigų vyresniuosius, apsigaubusius ašutinėmis, pas pranašą Izaiją, Amoco sūnų.'),
  (@b23, 37, 3, 'Ir jie jam tarė: „Taip sako Chezekijas: ‘Šita diena yra bėdos, barimo ir piktžodžiavimo diena; nes vaikai yra atėję, kad gimtų, bet nėra jėgų gimdyti.'),
  (@b23, 37, 4, 'Galbūt VIEŠPATS, tavo Dievas, išgirs žodžius Rabšakės, kurį Asirijos karalius, jo valdovas, siuntė priekaištauti gyvajam Dievui, ir papeiks žodžius, kuriuos VIEŠPATS, tavo Dievas, girdėjo; todėl iškelk savo maldą už likutį, kuris yra išlikęs’“.'),
  (@b23, 37, 5, 'Taigi karaliaus Chezekijo tarnai atėjo pas Izaiją.'),
  (@b23, 37, 6, 'Ir Izaijas jiems tarė: „Taip sakykite savo valdovui: Taip sako VIEŠPATS: ‘Nebijok žodžių, kuriuos girdėjai, kuriais man piktžodžiavo Asirijos karaliaus tarnai.'),
  (@b23, 37, 7, 'Štai aš siųsiu ant jo pūtimą, ir jis išgirs gandą, ir sugrįš į savo šalį; ir padarysiu, kad jis kris nuo kalavijo savo šalyje’“.'),
  (@b23, 37, 8, 'Taigi Rabšakė sugrįžo ir rado Asirijos karalių kariaujantį prieš Libną, nes jis girdėjo, kad šis pasitraukė nuo Lachišo.'),
  (@b23, 37, 9, 'Ir jis išgirdo kalbant apie Etiopijos karalių Tirhaką: „Jis išėjo kariauti su tavimi“. Ir tai išgirdęs jis siuntė pasiuntinius pas Chezekiją, tardamas:'),
  (@b23, 37, 10, '„Taip kalbėkite Judos karaliui Chezekijui, sakydami: ‘Teneapgauna tavęs tavo Dievas, kuriuo tu pasitiki, sakydamas: „Jeruzalė nebus atiduota į Asirijos karaliaus ranką“.'),
  (@b23, 37, 11, 'Štai tu girdėjai, ką Asirijos karaliai yra padarę visoms šalims, jas visiškai sunaikindami; argi tu būsi išvaduotas?'),
  (@b23, 37, 12, 'Argi jas išgelbėjo dievai tautų, kurias sunaikino mano tėvai – Gozaną, Haraną, Recefą ir Edeno vaikus, buvusius Telasare?'),
  (@b23, 37, 13, 'Kur yra Hamato karalius, Arpado karalius, Sefarvaimo miesto karalius, Henos ir Ivos?’“'),
  (@b23, 37, 14, 'Ir Chezekijas gavo laišką iš pasiuntinių rankos ir jį perskaitė; ir Chezekijas nuėjo aukštyn į VIEŠPATIES namus ir išskleidė jį prieš VIEŠPATĮ.'),
  (@b23, 37, 15, 'Ir Chezekijas meldėsi VIEŠPAČIUI, tardamas:'),
  (@b23, 37, 16, '„O kariuomenių VIEŠPATIE, Izraelio Dieve, gyvenantis tarp kerubų, tu vienas esi visų žemės karalysčių Dievas; tu padarei dangų ir žemę.'),
  (@b23, 37, 17, 'Palenk, o VIEŠPATIE, savo ausį ir klausyk; atmerk, o VIEŠPATIE, savo akis ir matyk; ir išgirsk visus žodžius Sancheribo, kuris siuntė priekaištauti gyvajam Dievui.'),
  (@b23, 37, 18, 'Iš tiesų, VIEŠPATIE, Asirijos karaliai suniokojo visas tautas ir jų šalis'),
  (@b23, 37, 19, 'ir sumetė jų dievus į ugnį; nes jie nebuvo dievai, o tik žmogaus rankų darbas, medis ir akmuo; todėl jie juos sunaikino.'),
  (@b23, 37, 20, 'Taigi dabar, o VIEŠPATIE, mūsų Dieve, išgelbėk mus iš jo rankos, kad vìsos žemės karalystės žinotų, jog tu vienas esi VIEŠPATS“.'),
  (@b23, 37, 21, 'Tada Amoco sūnus Izaijas pasiuntė Chezekijui, sakydamas: „Taip sako VIEŠPATS, Izraelio Dievas: ‘Kadangi tu man meldeisi prieš Asirijos karalių Sancheribą:'),
  (@b23, 37, 22, 'šitas yra žodis, kurį VIEŠPATS kalbėjo apie jį: ‘Mergelė, Siono duktė, paniekino tave ir pasityčiojo iš tavęs; Jeruzalės dukra krato galvą prieš tave.'),
  (@b23, 37, 23, 'Kam tu priekaištavai ir piktžodžiavai? Prieš ką tu išaukštinai savo balsą ir aukštai kėlei savo akis? Būtent prieš Izraelio Šventąjį.'),
  (@b23, 37, 24, 'Per savo tarnus tu priekaištavai Viešpačiui ir sakei: „Su savo vežimų daugybe aš atvykau aukštyn į kalnų aukštumą, į Libano šonus; ir aš nukirsiu jo aukštuosius kedrus bei jo rinktines egles; ir aš įeisiu į jo ribų aukštumą, į jo Karmelio mišką.'),
  (@b23, 37, 25, 'Aš iškasiau ir gėriau vandenį; ir savo kojų padais išdžiovinau visas apgultų vietų upes“.'),
  (@b23, 37, 26, 'Argi negirdėjai nuo seno, kaip aš tai padariau, ir nuo senovės laikų, kad aš tai formavau? Dabar tai įvykdžiau, kad tu nusiaubtum sutvirtintus miestus, paversdamas griuvėsių krūvomis.'),
  (@b23, 37, 27, 'Todėl jų gyventojai buvo bejėgiai, jie sunerimo ir suglumo; jie buvo kaip lauko žolė ir kaip žalumynai, kaip žolė ant namų stogų ir kaip javai išdžiovinti pirmiau nei užaugę.'),
  (@b23, 37, 28, 'Bet aš žinau, kaip tu gyveni, tavo išėjimą ir tavo įėjimą, ir tavo šėlsmą prieš mane.'),
  (@b23, 37, 29, 'Kadangi tavo šėlsmas prieš mane ir tavo triukšmas pakilo man į ausis, aš įdėsiu savo kablį tau į nosį bei savo apynasrį tau į lūpas ir tave sugrąžinsiu atgal tuo keliu, kuriuo atėjai’.'),
  (@b23, 37, 30, 'Ir šitas bus tau ženklas: šiais metais valgysi, kas savaime užaugs; antraisiais metais – kas iš to išdygs; o trečiaisiais metais sėkite ir pjaukite, sodinkite vynuogynus ir valgykite jų vaisių.'),
  (@b23, 37, 31, 'O Judos namų pabėgėlių likutis vėl leis šaknis į apačią ir neš vaisių į viršų;'),
  (@b23, 37, 32, 'nes iš Jeruzalės išeis likutis ir pabėgėliai iš Siono kalno; tai padarys kariuomenių VIEŠPATIES uolumas.'),
  (@b23, 37, 33, 'Todėl taip sako VIEŠPATS apie Asirijos karalių: ‘Jis neateis į šitą miestą ir nepaleis ten strėlės, ir neateis prieš jį su skydais, ir nesupils prieš jį pylimo.'),
  (@b23, 37, 34, 'Jis sugrįš tuo keliu, kuriuo atėjo, ir į šitą miestą neateis, – sako VIEŠPATS.'),
  (@b23, 37, 35, 'Nes aš apginsiu šitą miestą, kad jį išgelbėčiau dėl savęs ir dėl mano tarno Dovydo’“.'),
  (@b23, 37, 36, 'Tada VIEŠPATIES angelas išėjo ir išmušė asirų stovykloje šimtą aštuoniasdešimt penkis tūkstančius; ir kai jie atsikėlė anksti ryte, štai jie visi buvo negyvi lavonai.'),
  (@b23, 37, 37, 'Taigi Asirijos karalius Sancheribas pasitraukė ir nuėjo, ir sugrįžo bei gyveno Ninevėje.'),
  (@b23, 37, 38, 'Ir kai jis garbino savo dievo Nisrocho namuose, įvyko, kad jo sūnūs Adramelechas ir Šareceras jį nužudė kalaviju; ir jie pabėgo į Armėnijos šalį; o jo sūnus Esar-Hadonas karaliavo jo vietoje.'),
  (@b23, 38, 1, 'Tomis dienomis Chezekijas mirtinai susirgo. Ir pas jį atėjo pranašas Izaijas, Amoco sūnus, ir jam tarė: „Taip sako VIEŠPATS: ‘Sutvarkyk savo namus, nes tu mirsi ir negyvensi’“.'),
  (@b23, 38, 2, 'Tada Chezekijas nugręžė savo veidą į sieną ir meldėsi VIEŠPAČIUI,'),
  (@b23, 38, 3, 'tardamas: „O VIEŠPATIE, meldžiu tave, atsimink, kaip aš vaikščiojau tavo akivaizdoje tiesoje ir tobula širdimi ir dariau tai, kas yra gera tavo akyse“. Ir Chezekijas graudžiai verkė.'),
  (@b23, 38, 4, 'Tada atėjo VIEŠPATIES žodis Izaijui, sakydamas:'),
  (@b23, 38, 5, '„Eik ir tark Chezekijui: Taip sako VIEŠPATS, tavo tėvo Dovydo Dievas: ‘Aš girdėjau tavo maldą, mačiau tavo ašaras; štai aš pridėsiu prie tavo dienų penkiolika metų.'),
  (@b23, 38, 6, 'Ir išvaduosiu tave bei šitą miestą iš Asirijos karaliaus rankos; ir aš apginsiu šitą miestą.'),
  (@b23, 38, 7, 'Ir tau bus šis ženklas nuo VIEŠPATIES, kad VIEŠPATS padarys tai, ką jis kalbėjo:'),
  (@b23, 38, 8, 'Štai aš atvesiu atgal laipsnių šešėlį, kuris yra nusileidęs Ahazo saulės laikrodžiu, dešimt laipsnių atgal’“. Taip saulė sugrįžo dešimt laipsnių pagal tuos laipsnius, kuriais buvo nusileidusi.'),
  (@b23, 38, 9, 'Judos karaliaus Chezekijo raštas, kai jis susirgo ir pasveiko iš savo ligos:');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b23, 38, 10, '„Aš sakiau, kai buvo iškertamos mano dienos: Aš eisiu prie kapo vartų; man atėmė mano likusius metus.'),
  (@b23, 38, 11, 'Aš tariau: ‘Aš nematysiu VIEŠPATIES, būtent VIEŠPATIES gyvųjų šalyje; aš nebematysiu žmogaus su pasaulio gyventojais.'),
  (@b23, 38, 12, 'Mano metai nuėjo ir pašalinti nuo manęs kaip piemens palapinė; aš iškirtau kaip audėjas savo gyvenimą; jis iškirs mane prismeigiančia liga; nuo dienos iki nakties tu darysi man galą.'),
  (@b23, 38, 13, 'Aš maniau iki ryto, kad kaip liūtas, taip jis sulaužys visus mano kaulus; nuo dienos iki nakties tu darysi man galą.'),
  (@b23, 38, 14, 'Kaip gervė ar kregždė, taip aš čirškiau; aš verkiau kaip karvelis; nusilpo mano akys bežiūrėdamos aukštyn; o VIEŠPATIE, esu engiamas; laiduok už mane.'),
  (@b23, 38, 15, 'Ką aš sakysiu? Jis man pasakė ir pats tai padarė; aš tyliai eisiu per visus savo metus savo sielos kartybėje.'),
  (@b23, 38, 16, 'O Viešpatie, tais dalykais žmogus yra gyvas, ir visuose tuose dalykuose yra mano dvasios gyvybė; taip tu išgydysi mane ir leisi man gyventi.'),
  (@b23, 38, 17, 'Štai vietoj ramybės aš turėjau didelę kartybę; bet tu iš meilės mano sielai išvadavai ją nuo gedimo duobės; nes tu visas mano nuodėmes numetei sau už nugaros.'),
  (@b23, 38, 18, 'Nes kapas tavęs negiria, mirtis tavęs negarbina; tie, kurie eina žemyn į duobę, nesivilia tavo tiesa.'),
  (@b23, 38, 19, 'Gyvieji, gyvieji, jie tave girs, kaip aš šią dieną; tėvas duos vaikams pažinti tavo tiesą.'),
  (@b23, 38, 20, 'VIEŠPATS buvo pasiruošęs mane išgelbėti; todėl giedosime mano giesmes styginiams instrumentams per visas mūsų gyvenimo dienas VIEŠPATIES namuose’“.'),
  (@b23, 38, 21, 'Nes Izaijas tarė: „Tepaima figų gniužulą ir teuždeda jį skauduliui apklijuoti, ir jis pasveiks“.'),
  (@b23, 38, 22, 'Ir Chezekijas tarė: „Koks yra ženklas, kad aš eisiu aukštyn į VIEŠPATIES namus?“'),
  (@b23, 39, 1, 'Tuo metu Baladano sūnus Merodach-Baladanas, Babilono karalius, nusiuntė laiškus ir dovaną Chezekijui; nes girdėjo, kad jis buvo susirgęs ir pasveiko.'),
  (@b23, 39, 2, 'Ir Chezekijas apsidžiaugė dėl jų ir jiems parodė savo brangenybių namus, sidabrą, auksą, kvapus, brangų tepalą, visą savo ginklų sandėlį ir viską, kas buvo rasta jo lobynuose; nebuvo nieko jo namuose ir visose jo valdose, ko Chezekijas nebūtų jiems parodęs.'),
  (@b23, 39, 3, 'Tada pranašas Izaijas atėjo pas karalių Chezekiją ir jam tarė: „Ką pasakė šitie vyrai? Ir iš kur jie atvyko pas tave?“ Ir Chezekijas tarė: „Jie atvyko pas mane iš tolimos šalies, tai yra, iš Babilono“.'),
  (@b23, 39, 4, 'Tada jis tarė: „Ką jie matė tavo namuose?“ Ir Chezekijas atsakė: „Jie matė viską, kas yra mano namuose; nėra nieko mano lobynuose, ko nebūčiau jiems parodęs“.'),
  (@b23, 39, 5, 'Tada Izaijas tarė Chezekijui: „Klausyk kariuomenių VIEŠPATIES žodžio:'),
  (@b23, 39, 6, '‘Štai ateis dienos, kai visa, kas yra tavo namuose ir ką tavo tėvai sukrovė iki šios dienos, bus nugabenta į Babiloną; nieko nepaliks, – sako VIEŠPATS.'),
  (@b23, 39, 7, 'Ir jie paims iš tavo sūnų, kurie kils iš tavęs, kuriuos tu pagimdysi; ir jie bus eunuchais Babilono karaliaus rūmuose’“.'),
  (@b23, 39, 8, 'Tada Chezekijas tarė Izaijui: „VIEŠPATIES žodis, kurį tu kalbėjai, yra geras“. Jis dar tarė: „Nes bus taika ir tiesa mano dienomis“.'),
  (@b23, 40, 1, '„Guoskite, guoskite mano tautą, – sako jūsų Dievas.'),
  (@b23, 40, 2, '– Paguodžiančiai kalbėkite Jeruzalei ir šaukite jai, kad užsibaigė jos kariavimas, kad jos neteisybė atleista; nes ji gavo iš VIEŠPATIES rankos dvigubai už visas savo nuodėmes“.'),
  (@b23, 40, 3, 'Dykumoje šaukiančiojo balsas: „Paruoškite VIEŠPATIES kelią, tiesų darykite vieškelį mūsų Dievui dykumoje.'),
  (@b23, 40, 4, 'Kiekvienas slėnis bus iškeltas, ir kiekvienas kalnas bei kalva bus pažeminti; kas kreiva, bus ištiesinta, ir nelygios vietos – išlygintos;'),
  (@b23, 40, 5, 'ir VIEŠPATIES šlovė bus apreikšta, ir ją išvys kartu visi kūnai; nes VIEŠPATIES burna tai kalbėjo“.'),
  (@b23, 40, 6, 'Balsas tarė: „Šauk“. Ir jis tarė: „Ką man šaukti?“ „Visi kūnai yra žolė, ir visas jų grožis – kaip lauko gėlė;'),
  (@b23, 40, 7, 'žolė sudžiūna, gėlė nuvysta, nes VIEŠPATIES Dvasia pučia į ją; iš tikrųjų tauta yra žolė.'),
  (@b23, 40, 8, 'Žolė sudžiūna, gėlė nuvysta, bet mūsų Dievo žodis išsilaikys per amžius“.'),
  (@b23, 40, 9, 'O Sione, kuris neši gerą žinią, užlipk į aukštą kalną; o Jeruzale, kuri neši gerą žinią, pakelk galingai savo balsą; pakelk jį, nebijok; sakyk Judos miestams: „Štai jūsų Dievas!“'),
  (@b23, 40, 10, 'Štai Viešpats DIEVAS ateis su galinga ranka, ir jo ranka dėl jo valdys; štai jo atpildas yra su juo, ir jo darbas jo priešakyje.'),
  (@b23, 40, 11, 'Jis ganys savo kaimenę kaip piemuo: savo ranka jis surinks avinėlius ir nešios juos savo užantyje, ir švelniai vedžios esančias su jaunikliais.'),
  (@b23, 40, 12, 'Kas išmatavo vandenis savo sauja ir išmatavo dangų sprindžiu, ir apėmė žemės dulkes saiku, ir pasvėrė kalnus svarstyklėmis ir kalvas svertais?'),
  (@b23, 40, 13, 'Kas nukreipė VIEŠPATIES Dvasią arba, būdamas jo patarėju, jį pamokė?'),
  (@b23, 40, 14, 'Su kuo jis tarėsi, kas jį pamokė ir išmokė jį teismo tako bei išmokė jį pažinimo ir parodė jam supratimo kelią?'),
  (@b23, 40, 15, 'Štai tautos yra kaip lašas iš kibiro ir yra laikomos smulkiomis dulkėmis ant svarstyklių; štai salas jis pakelia kaip dulkeles.'),
  (@b23, 40, 16, 'Libano nepankanka deginimui nei jo žvėrių nepakanka deginamajai atnašai.'),
  (@b23, 40, 17, 'Visos tautos prieš jį yra kaip niekas; jis jas laiko mažesnėmis už nieką ir tuštybę.'),
  (@b23, 40, 18, 'Tad su kuo palyginsite Dievą? Arba, ką panašaus jūs palyginsite su juo?'),
  (@b23, 40, 19, 'Meistras nulieja raižytą atvaizdą, o auksakalys padengia jį auksu ir išlieja sidabrines grandines.'),
  (@b23, 40, 20, 'Tas, kuris yra taip nuskurdęs, kad neturi aukos, pasirenka nepūvantį medį; jis suieško sau sumanų meistrą, kad pagamintų raižytą atvaizdą, kuris nejudėtų.'),
  (@b23, 40, 21, 'Ar nežinojote? Ar negirdėjote? Ar jums nebuvo kalbėta nuo pradžios? Ar nesupratote nuo žemės pamatų?'),
  (@b23, 40, 22, 'Tai jis, kuris sėdi ant žemės apskritimo, ir jos gyventojai yra kaip žiogai; kuris ištiesia dangus kaip uždangalą ir išskleidžia juos kaip palapinę joje gyventi;'),
  (@b23, 40, 23, 'kuris paverčia kunigaikščius niekais; žemės teisėjus jis padaro kaip tuštybę.'),
  (@b23, 40, 24, 'Taip, jie dar nebus pasisodinę; taip, jie dar nebus pasisėję; taip, jų kamienas dar nebus išleidęs šaknų į žemę, ir jis papūs į juos, ir jie nuvys, ir viesulas juos nuneš kaip ražieną.'),
  (@b23, 40, 25, '„Tad su kuo mane palyginsite, arba, kam prilygčiau?“ – sako Šventasis.'),
  (@b23, 40, 26, 'Pakelkite aukštyn savas akis ir žiūrėkite, kas sukūrė šituos dalykus, kas išveda jų kariuomenę pagal skaičių; savo galios didybe jis vadina juos visus vardais, kadangi jis yra galingas jėga; nei vieno netrūksta.'),
  (@b23, 40, 27, 'Kodėl sakai, Jokūbai, ir kalbi, Izraeli: „Mano kelias paslėptas nuo VIEŠPATIES ir mano teismas praėjęs mano Dievui pro šalį“?'),
  (@b23, 40, 28, 'Ar tu nežinojai? Ar tu negirdėjai, kad amžinasis Dievas, VIEŠPATS, žemės pakraščių Sutvėrėjas, nenusilpsta ir nepavargsta? Jo supratimas neištiriamas.'),
  (@b23, 40, 29, 'Jis duoda nusilpusiam jėgų ir bejėgiui padidina stiprybę.'),
  (@b23, 40, 30, 'Net jaunuoliai nusilpsta ir pavargsta, ir jauni vyrai visiškai pargriūna;'),
  (@b23, 40, 31, 'bet tie, kurie laukia VIEŠPATIES, atnaujins savo jėgas; jie pakils sparnais kaip ereliai; jie bėgs ir nepavargs; jie vaikščios ir nenusilps.'),
  (@b23, 41, 1, '„O salos, nutilkite prieš mane; ir tegul tautos atnaujina savo jėgas; tegul jos priartėja; paskui tegul jos kalba: ‘Kartu artinkimės į teismą’.'),
  (@b23, 41, 2, 'Kas prikėlė teisųjį iš rytų, pašaukė jį atsistoti ant kojų, davė jo akivaizdon tautas ir padarė jį karalių valdovu? Jis davė juos kaip dulkes jo kalavijui ir kaip nešiojamą ražieną jo lankui.'),
  (@b23, 41, 3, 'Jis vijosi juos ir saugiai perėjo, būtent keliu, kuriuo nebuvo ėjęs savo kojomis.'),
  (@b23, 41, 4, 'Kas tai nuveikė ir padarė, pašaukdamas kartas nuo pradžios? Aš, VIEŠPATS, pirmasis, ir su paskutiniaisiais; aš esu tas.'),
  (@b23, 41, 5, 'Salos tai matė ir bijojo; žemės pakraščiai išsigandę prisiartino ir atėjo.'),
  (@b23, 41, 6, 'Jie kiekvienas padėjo savo artimui ir kiekvienas sakė savo broliui: ‘Būk drąsus’.'),
  (@b23, 41, 7, 'Taigi, dailidė padrąsina auksakalį, o lygintojas kūju – ant priekalo kalantį, sakydamas: ‘Jis paruoštas sulitavimui’; ir jis pritvirtina jį vinimis, kad šis nejudėtų.'),
  (@b23, 41, 8, 'Bet tu, Izraeli, esi mano tarnas, Jokūbas, kurį išsirinkau, mano draugo Abraomo sėkla.'),
  (@b23, 41, 9, 'Tu, kurį paėmiau nuo žemės pakraščių ir pašaukiau tave iš jos vyriausiųjų, ir tau pasakiau: ‘Tu esi mano tarnas; aš tave išsirinkau ir tavęs neatmečiau’.'),
  (@b23, 41, 10, 'Nebijok, nes aš esu su tavimi; nebūk sunerimęs; nes aš esu tavo Dievas; aš sustiprinsiu tave; taip, aš tau padėsiu; taip, aš tave palaikysiu savo teisumo dešine.'),
  (@b23, 41, 11, 'Štai visi, kurie buvo įsiutę prieš tave, gėdysis ir bus suglumę; jie bus kaip niekas; ir pražus tie, kurie vaidijasi su tavimi.'),
  (@b23, 41, 12, 'Tu jų ieškosi ir nerasi – tų, kurie ginčijosi su tavimi; tie, kurie kariauja prieš tave, bus kaip niekas ir kaip visiškas niekas.'),
  (@b23, 41, 13, 'Nes aš VIEŠPATS, tavo Dievas, laikysiu tavo dešinę ranką, tau sakydamas: ‘Nebijok; aš tau padėsiu’.'),
  (@b23, 41, 14, 'Nebijok, tu kirmine, Jokūbai, jūs Izraelio žmonės; aš tau padėsiu, – sako VIEŠPATS ir tavo atpirkėjas, Izraelio Šventasis.'),
  (@b23, 41, 15, '– Štai aš padarysiu tave nauju, aštriu kuliamuoju įrankiu, turinčiu dantis; tu kulsi kalnus ir juos sutrupinsi, ir kalvas padarysi kaip pelus.'),
  (@b23, 41, 16, 'Tu juos vėtysi, o vėjas juos nuneš ir viesulas juos išsklaidys; ir tu džiūgausi VIEŠPAČIU ir girsiesi Izraelio Šventuoju.'),
  (@b23, 41, 17, 'Kai vargšai ir nepasiturintys ieškos vandens, bet jo nebus, ir jų liežuvis sudžius iš troškulio, aš, VIEŠPATS, juos išklausysiu, aš, Izraelio Dievas, jų nepaliksiu.'),
  (@b23, 41, 18, 'Aš atversiu upes aukštumose ir šaltinius slėnių vidury; aš padarysiu dykumą vandens telkiniu ir sausą žemę – vandens versmėmis.'),
  (@b23, 41, 19, 'Tyruose pasodinsiu kedrų, šitimų, mirtų ir alyvmedžių; aš pasodinsiu dykumoje kartu egles, pušis ir buksmedžius;'),
  (@b23, 41, 20, 'kad jie kartu matytų ir žinotų, ir apsvarstytų, ir suprastų, jog VIEŠPATIES ranka tai padarė ir Izraelio Šventasis tai sutvėrė.'),
  (@b23, 41, 21, 'Pateikite savo bylą, – sako VIEŠPATS, – išgimdykite savo tvirtus argumentus, – sako Jokūbo Karalius.'),
  (@b23, 41, 22, 'Tegul jie juos išgimdo ir mums paskelbia, kas įvyks; tepaskelbia ankstesnius dalykus, kas jie buvo, kad juos apsvarstytume ir žinotume jų baigtį; arba paskelbkite mums ateinančius dalykus.'),
  (@b23, 41, 23, 'Paskelbkite tai, kas ateis po to, kad žinotume, jog jūs esate dievai; taip, darykite gera ar darykite bloga, kad būtume sunerimę ir kartu tai pamatytume.'),
  (@b23, 41, 24, 'Štai jūs esate niekas, ir jūsų darbas yra niekas; pasibjaurėjimas yra tas, kuris pasirenka jus.'),
  (@b23, 41, 25, 'Aš pakėliau vieną iš šiaurės, ir jis ateis; iš saulėtekio jis šauksis mano vardo; ir jis ateis ant kunigaikščių kaip ant statybinio skiedinio ir kaip puodžius mina molį.'),
  (@b23, 41, 26, 'Kas paskelbė nuo pradžios, kad žinotume, ir iš anksto, kad sakytume: ‘Jis teisus’? Taip, nėra kas paskelbtų, taip, nėra kas praneštų, taip, nėra, kas girdėtų jūsų žodžius.'),
  (@b23, 41, 27, 'Pirmas sakys Sionui: ‘Štai, štai jie’; ir Jeruzalei duosiu tą, kuris neša gerą žinią.'),
  (@b23, 41, 28, 'Nes aš pažiūrėjau, bet nebuvo nei vieno; būtent tarp jų, bet nebuvo jokio patarėjo, kad man jų paklausus atsakytų nors žodį.'),
  (@b23, 41, 29, 'Štai jie visi yra tuštybė, jų darbai yra niekas; jų nulieti atvaizdai yra vėjas ir sumaištis“.'),
  (@b23, 42, 1, '„Štai mano tarnas, kurį palaikau, mano išrinktasis, kuriuo gėrisi mano siela; aš uždėjau ant jo savo Dvasią; jis išves teismą pas pagonis.'),
  (@b23, 42, 2, 'Jis nešauks nei nepakels savo balso, nei neduos savo balso išgirsti gatvėje.'),
  (@b23, 42, 3, 'Palūžusios nendrės jis nesulaužys ir rūkstančio lino neužgesins; jis išves teismą į tiesą.'),
  (@b23, 42, 4, 'Jis nenusilps ir nepraras drąsos, kol neįtvirtins žemėje teismo; ir salos lauks jo įstatymo“.'),
  (@b23, 42, 5, 'Taip sako Dievas, VIEŠPATS, tas, kuris sutvėrė dangus ir juos ištiesė; tas, kuris išskleidė žemę ir tai, kas iš jos išauga; tas, kuris duoda kvapą tautoms ant jos ir dvasią joje vaikščiojantiems:'),
  (@b23, 42, 6, '„Aš, VIEŠPATS, pašaukiau tave teisume ir laikysiu tavo ranką, ir tave saugosiu, ir duosiu tave kaip tautos sandorą, kaip pagonių šviesą;'),
  (@b23, 42, 7, 'kad atvertum aklas akis, kad išvestum iš kalėjimo belaisvius ir sėdinčius tamsoje iš kalėjimo namų.'),
  (@b23, 42, 8, 'Aš esu VIEŠPATS; tai mano vardas; ir savo šlovės aš neduosiu kitam nei savo gyriaus raižytiems atvaizdams.'),
  (@b23, 42, 9, 'Štai ankstesnieji dalykai įvyko, ir naujus dalykus aš skelbiu; prieš jiems pasirodant, aš jums pranešu apie juos“.'),
  (@b23, 42, 10, 'Giedokite VIEŠPAČIUI naują giesmę ir jo gyrių nuo žemės pakraščio jūs, kurie leidžiatės į jūrą, ir visi, esantys joje; salos ir jų gyventojai.'),
  (@b23, 42, 11, 'Tepakelia savo balsą dykuma ir jos miestai, kaimai, apgyventi Kedaro; tegieda uolos gyventojai, nuo kalnų viršūnės jie tešūkauja.'),
  (@b23, 42, 12, 'Tegul jie duoda VIEŠPAČIUI šlovę ir jo gyrių teskelbia salose.'),
  (@b23, 42, 13, 'VIEŠPATS išeis kaip galiūnas, kaip karo vyras jis sukels pavydą; jis šauks, taip, riaumos; jis nugalės savo priešus.'),
  (@b23, 42, 14, '„Aš ilgai tylėjau; aš buvau ramus ir susilaikiau; dabar aš šauksiu kaip gimdyvė; iš karto sunaikinsiu ir prarysiu.'),
  (@b23, 42, 15, 'Aš ištuštinsiu kalnus bei kalvas ir išdžiovinsiu visas jų žoles; upes padarysiu salomis ir išdžiovinsiu tvenkinius.'),
  (@b23, 42, 16, 'Aš vesiu akluosius keliu, kurio jie nežinojo; vesiu juos takais, kurių jie nėra pažinę; jų priešakyje tamsą padarysiu šviesa ir kreivus dalykus – tiesiais. Šituos dalykus aš jiems darysiu ir jų nepaliksiu.'),
  (@b23, 42, 17, 'Jie bus apsigręžę, jie bus labai susigėdę, kurie pasitiki raižytais atvaizdais, kurie sako nulietiems atvaizdams: ‘Jūs esate mūsų dievai’.'),
  (@b23, 42, 18, 'Kurtieji, klausykite; ir aklieji, žiūrėkite, kad matytumėte.'),
  (@b23, 42, 19, 'Kas yra aklas, jei ne mano tarnas? Arba kurčias kaip mano pasiuntinys, kurį siunčiau? Kas yra aklas kaip tobulasis ir aklas kaip VIEŠPATIES tarnas?'),
  (@b23, 42, 20, 'Matai daug, bet nepastebi; ausys atviros, bet jis negirdi“.'),
  (@b23, 42, 21, 'VIEŠPATS labai patenkintas dėl savo teisumo; jis išaukštins įstatymą ir padarys jį garbingą.'),
  (@b23, 42, 22, 'Bet tai yra tauta, apiplėšta ir apgrobta; jie visi pagauti olose ir paslėpti kalėjimo namuose; jie yra grobiui, ir niekas neišvaduoja, apiplėšimui, ir niekas nesako: „Grąžink“.'),
  (@b23, 42, 23, 'Kas tarp jūsų pakreips į tai ausį? Kas išklausys ir išgirs dėl ateinančių laikų?'),
  (@b23, 42, 24, 'Kas davė Jokūbą grobiui ir Izraelį plėšikams? Ar tai ne VIEŠPATS, prieš kurį nusidėjome? Nes jie nenorėjo vaikščioti jo keliais nei nepakluso jo įstatymui.'),
  (@b23, 42, 25, 'Todėl jis išliejo ant jo savo pykčio įtūžį ir mūšio stiprybę; ir tai jį uždegė aplinkui, tačiau jis nesuprato; ir jį degino, tačiau jis neėmė to į širdį.'),
  (@b23, 43, 1, 'Bet dabar taip sako VIEŠPATS, kuris sutvėrė tave, o Jokūbai, ir tas, kuris suformavo tave, o Izraeli: „Nebijok, nes aš tave atpirkau, aš tave pašaukiau tavo vardu, tu esi mano.'),
  (@b23, 43, 2, 'Kai tu eisi per vandenis, aš būsiu su tavimi, ir per upes, jos tavęs neužlies; kai vaikščiosi per ugnį, nesudegsi; ir liepsna tavęs neuždegs.'),
  (@b23, 43, 3, 'Nes aš esu VIEŠPATS, tavo Dievas, Izraelio Šventasis, tavo Gelbėtojas; aš daviau Egiptą tavo išpirkai, Etiopiją ir Sebą už tave.'),
  (@b23, 43, 4, 'Kadangi tu buvai brangus mano akyse, tu buvai gerbiamas, ir aš tave mylėjau; todėl aš duosiu žmones už tave ir tautas už tavo gyvybę.'),
  (@b23, 43, 5, 'Nebijok, nes aš esu su tavimi; iš rytų atvesiu tavo sėklą ir iš vakarų tave surinksiu;'),
  (@b23, 43, 6, 'aš sakysiu šiaurei: ‘Atiduok’; ir pietums: ‘Nesulaikyk; atvesk mano sūnus iš toli ir mano dukteris nuo žemės pakraščių;'),
  (@b23, 43, 7, 'būtent kiekvieną, kuris vadinasi mano vardu; nes aš jį sutvėriau savo šlovei, jį suformavau; taip, aš jį padariau.'),
  (@b23, 43, 8, 'Išvesk aklą tautą, turinčią akis, ir kurčią, turinčią ausis’.'),
  (@b23, 43, 9, 'Tesusirenka visos tautybės, tesusirenka tautos; kas iš jų gali tai pranešti ir paskelbti mums tai, kas buvo anksčiau? Tepristato jie savo liudytojus, kad jie būtų išteisinti; arba tegul jie klausosi ir sako: ‘Tai tiesa’“.'),
  (@b23, 43, 10, '„Jūs esate mano liudytojai, – sako VIEŠPATS, – ir mano tarnas, kurį išsirinkau; kad žinotumėte ir manimi tikėtumėte, ir suprastumėte, jog aš esu tas; pirma manęs nebuvo suformuota jokio Dievo ir po manęs nebus.'),
  (@b23, 43, 11, 'Aš – būtent aš esu VIEŠPATS, ir be manęs nėra gelbėtojo.'),
  (@b23, 43, 12, 'Aš paskelbiau, išgelbėjau ir pranešiau, kai nebuvo tarp jūsų jokio svetimo dievo; todėl jūs esate mano liudytojai, – sako VIEŠPATS, – kad aš esu Dievas.'),
  (@b23, 43, 13, 'Taip, pirmiau nei buvo diena, aš esu tas; ir nėra nei vieno, kuris galėtų išvaduoti iš mano rankos; aš darysiu, ir kas tai sutrukdys?“'),
  (@b23, 43, 14, 'Taip sako VIEŠPATS, jūsų atpirkėjas, Izraelio Šventasis: „Dėl jūsų nusiunčiau į Babiloną ir nuvedžiau žemyn visus jų kilminguosius ir kaldėjus, kurių šauksmas yra laivuose.'),
  (@b23, 43, 15, 'Aš esu VIEŠPATS, jūsų Šventasis, Izraelio sutvėrėjas, jūsų Karalius“.'),
  (@b23, 43, 16, 'Taip sako VIEŠPATS, kuris daro kelią jūroje ir taką galinguose vandenyse;'),
  (@b23, 43, 17, 'kuris išveda vežimą ir žirgą, kariuomenę ir jėgą; jie atsiguls kartu, jie nebeatsikels; jie užgesę, kaip kuodelis užgesę.'),
  (@b23, 43, 18, 'Nebeprisiminkite to, kas buvo anksčiau, ir neatsižvelkite į tai, kas buvo seniai.'),
  (@b23, 43, 19, 'Štai aš darysiu nauja; tai jau dabar išdygs; argi to nežinosite? Aš padarysiu kelią tyrlaukyje ir upes dykumoje.'),
  (@b23, 43, 20, 'Mane gerbs lauko žvėrys, slibinai ir pelėdos; nes aš duodu tyrlaukyje vandenis, dykumoje upes, kad girdyčiau savo tautą, mano išrinktąją.'),
  (@b23, 43, 21, 'Šią tautą aš suformavau sau; jie skelbs mano šlovę.'),
  (@b23, 43, 22, 'Bet tu nesišaukei manęs, o Jokūbai; tu nuvargai nuo manęs, o Izraeli.'),
  (@b23, 43, 23, 'Neatnešei man savo deginamųjų atnašų mažų galvijų; ir negerbei manęs savo aukomis. Aš neverčiau tavęs tarnauti atnaša ir nevarginau tavęs smilkalais.'),
  (@b23, 43, 24, 'Nenupirkai man saldžių nendrių už pinigus ir savo aukų riebalais manęs neprisotinai; bet tu įdarbinai mane savo nuodėmėmis, tu mane nuvarginai savo neteisybėmis.'),
  (@b23, 43, 25, 'Aš, būtent aš esu tas, kuris išdildau tavo nusižengimus dėl pačio savęs, ir tavo nuodėmių neprisiminsiu.'),
  (@b23, 43, 26, 'Primink man; bylinėkimės drauge; pareikšk, kad būtum išteisintas.'),
  (@b23, 43, 27, 'Tavo pirmasis tėvas nusidėjo ir tavo mokytojai nusižengė prieš mane.'),
  (@b23, 43, 28, 'Todėl aš suteršiau šventovės kunigaikščius ir padaviau Jokūbą prakeikimui ir Izraelį priekaištams“.'),
  (@b23, 44, 1, '„Tačiau dabar klausyk, o Jokūbai, mano tarne, Izraeli, kurį išsirinkau;'),
  (@b23, 44, 2, 'taip sako VIEŠPATS, kuris tave padarė ir suformavo tave nuo įsčių, kuris tau padės: ‘Nebijok, o Jokūbai, mano tarne, Ješurūnai, kurį išsirinkau.'),
  (@b23, 44, 3, 'Nes aš išliesiu vandenį ant ištroškusiųjų ir sroves ant sausos žemės; aš išliesiu savo Dvasią ant tavo sėklos ir savo palaiminimą ant tavo palikuonių;'),
  (@b23, 44, 4, 'ir jie išdygs kaip tarp žolės, kaip gluosniai prie vandens tėkmių.'),
  (@b23, 44, 5, 'Vienas sakys: ‘Aš esu VIEŠPATIES’, o kitas vadinsis Jokūbo vardu; o dar kitas savo ranka užsirašys VIEŠPAČIUI ir pramins save Izraelio vardu.'),
  (@b23, 44, 6, 'Taip sako VIEŠPATS, Izraelio Karalius, ir jo atpirkėjas, kariuomenių VIEŠPATS: ‘Aš esu pirmasis ir aš esu paskutinysis, ir be manęs nėra Dievo.'),
  (@b23, 44, 7, 'Ir kuris, kaip aš, pašauks ir tai paskelbs, ir man tai paruoš nuo tada, kai aš paskyriau senovės žmones? Ir tegul jiems praneša dalykus, kurie ateina ir kurie ateis.'),
  (@b23, 44, 8, 'Nebijokite ir nenusigąskite; argi aš tau nuo tada nesakiau ir to nepranešiau? Jūs esate mano liudytojai. Ar yra Dievas be manęs? Tikrai, nėra kito Dievo; aš nežinau jokio.'),
  (@b23, 44, 9, 'Visi raižytų atvaizdų dirbėjai yra niekas, ir jų žavieji dalykai neduos jokios naudos; jie patys sau yra liudytojai, jie nemato ir nesupranta; kad jie susigėstų.'),
  (@b23, 44, 10, 'Kas suformavo dievą ar nuliejo raižytą atvaizdą, kuris neduoda naudos?'),
  (@b23, 44, 11, 'Štai visi jo bendrai gėdysis; o meistrai – jie tėra iš žmonių; tegul jie visi susirenka, tegul jie sustoja; tačiau jie kartu išsigąs ir susigės.'),
  (@b23, 44, 12, 'Kalvis žnyplėmis apdirba anglyse, formuoja jį kūjais ir apdirba savo rankų stiprumu; taip, jis išalksta, ir jo jėgos išsenka, jis neatsigeria vandens ir nusilpsta.'),
  (@b23, 44, 13, 'Dailidė ištiesia savo matuoklę, nužymi jį virve; jis obliuoja jį obliumi ir nužymi jį skriestuvu, ir jį padaro pagal žmogaus atvaizdą, pagal žmogaus grožį, kad jis pasiliktų namuose.'),
  (@b23, 44, 14, 'Jis nukerta sau kedrų, paima kiparisą ir ąžuolą, kuriuos jis sustiprino sau tarp miško medžių; jis pasodina uosį, o lietus jį augina.'),
  (@b23, 44, 15, 'Tada jis žmogui bus deginimui; nes jis ims iš jų ir susišildys; taip, jis uždega jį ir kepa duoną; taip, jis padaro dievą ir jį garbina; jis padaro jį raižytu atvaizdu ir ties juo parpuola.'),
  (@b23, 44, 16, 'Dalį jo jis sudegina ugnyje; iš jo dalies jis valgo mėsą, kepa kepsnį ir pasisotina; taip, jis susišildo ir sako: ‘Aha, aš sušilau, aš mačiau ugnį’;'),
  (@b23, 44, 17, 'o iš jo likučio jis padaro dievą – jo raižytą atvaizdą; ties juo jis parpuola ir jį garbina, ir meldžiasi jam, sakydamas: ‘Išvaduok mane, nes tu esi mano dievas’.'),
  (@b23, 44, 18, 'Jie nežino ir nesupranta; nes jis užmerkė jų akis, kad jie nematytų; ir užrakino jų širdis, kad jie nesuprastų.'),
  (@b23, 44, 19, 'Ir nei vienas nepagalvoja savo širdyje, ir nėra nei pažinimo, nei supratimo, kad sakytų: ‘Dalį jo sudeginau ugnyje, taip pat iškepiau duoną ant jo anglių, iškepiau mėsą ir valgiau; argi iš jo liekanos pasidarysiu bjaurystę? Argi aš nupulsiu ties medžio kamienu?’'),
  (@b23, 44, 20, 'Jis maitinasi pelenais; apgauta širdis jį nukreipė į šalį, kad jis negali išvaduoti savo sielos nei sakyti: ‘Argi ne melas mano dešinėje?’'),
  (@b23, 44, 21, 'Atsimink šituos, o Jokūbai, Izraeli, nes tu esi mano tarnas; aš tave suformavau; tu esi mano tarnas; o Izraeli, tu nebūsi mano pamirštas.'),
  (@b23, 44, 22, 'Aš ištryniau tavo nusižengimus kaip tirštą debesį, kaip debesį tavo nuodėmes; sugrįžk pas mane; nes aš atpirkau tave“.'),
  (@b23, 44, 23, 'Giedokite, o dangūs; nes VIEŠPATS tai padarė; šūkaukite, žemės gilybės; pratrūkite giesme, kalnai, o miške, ir visi ten esantys medžiai; nes VIEŠPATS atpirko Jokūbą ir pašlovino save Izraelyje.'),
  (@b23, 44, 24, 'Taip sako VIEŠPATS, tavo atpirkėjas, ir tas, kuris tave suformavau nuo pat įsčių: „Aš esu VIEŠPATS, kuris darau visa; kuris vienas ištiesiau dangus, kuris pats išskleidžiau žemę;'),
  (@b23, 44, 25, 'kuris paverčiu niekais melagių ženklus ir ateities būrėjus padarau bepročiais; kuris apsuku išmintinguosius atgal ir jų pažinimą padarau kvailu;'),
  (@b23, 44, 26, 'kuris patvirtinu savo tarno žodį ir įvykdau savo pasiuntinių sumanymą; kuris sakau Jeruzalei: ‘Tu būsi apgyvendinta’; ir Judos miestams: ‘Jūs būsite pastatyti’, ir aš prikelsiu jos sunykusias vietas;'),
  (@b23, 44, 27, 'kuris sakau gelmėms: ‘Išdžiūkite, ir aš išdžiovinsiu jūsų upes’;'),
  (@b23, 44, 28, 'kuris sakau apie Kyrą: Jis yra mano piemuo ir įvykdys visą mano valią, sakydamas Jeruzalei: ‘Tu būsi pastatyta’, ir šventyklai: ‘Tavo pamatas bus padėtas’“.'),
  (@b23, 45, 1, 'Taip sako VIEŠPATS savo pateptajam, Kyrui, kurio dešinę aš laikiau, kad pavergčiau jo akivaizdoje tautas; ir aš nujuosiu karaliams strėnas, kad atidaryčiau jo priešakyje dvivėrius vartus; ir vartai nebus uždaryti:'),
  (@b23, 45, 2, '„Aš eisiu pirma tavęs ir ištiesinsiu kreivas vietas; aš sutrupinsiu žalvarinius vartus ir sukaposiu geležinius skląsčius;'),
  (@b23, 45, 3, 'ir tau duosiu tamsos lobius ir paslėptus slaptavietės turtus, kad žinotum, jog aš, VIEŠPATS, kuris tave šaukiu tavo vardu, esu Izraelio Dievas.'),
  (@b23, 45, 4, 'Dėl savo tarno Jokūbo, Izraelio, mano išrinktojo, aš tave pašaukiau tavo vardu; aš praminiau tave, nors tu manęs nepažinai.'),
  (@b23, 45, 5, 'Aš esu VIEŠPATS ir nėra kito; be manęs nėra Dievo; aš apjuosiau tave, nors tu manęs nepažinai;'),
  (@b23, 45, 6, 'kad jie žinotų nuo saulės patekėjimo ir nuo vakarų, jog be manęs nėra kito: aš esu VIEŠPATS, ir nėra kito.'),
  (@b23, 45, 7, 'Aš formuoju šviesą ir sutveriu tamsą; aš darau ramybę ir sutveriu pikta; aš, VIEŠPATS, visa tai darau.'),
  (@b23, 45, 8, 'Lašnokite, dangūs, iš aukšto, ir telieja padangės teisumą; teatsiveria žemė ir jie teatneša išgelbėjimą, ir teisingumas teišdygsta kartu; aš, VIEŠPATS, tai sutvėriau.'),
  (@b23, 45, 9, 'Vargas tam, kuris vaidijasi su savo Kūrėju! Tegul šukė vaidijasi su žemės šukėmis. Ar molis sakys tam, kuris iš jo formuoja: ‘Ką darai?’ Arba tavo dirbinys: ‘Jis neturi rankų?’'),
  (@b23, 45, 10, 'Vargas tam, kuris sako savo tėvui: ‘Ką gimdai?’ arba moteriai: ‘Ką pagimdei?’'),
  (@b23, 45, 11, 'Taip sako VIEŠPATS, Izraelio Šventasis ir jo Kūrėjas: ‘Paklauskite mane apie ateinančius dalykus dėl mano sūnų, ir dėl mano rankų darbo man įsakykite.'),
  (@b23, 45, 12, 'Aš padariau žemę ir ant jos sutvėriau žmogų; aš, būtent mano rankos, ištiesė dangus, ir visai jų kariuomenei aš įsakiau.'),
  (@b23, 45, 13, 'Aš jį prikėliau teisumu ir nukreipsiu visus jo kelius; jis pastatys mano miestą ir paleis mano belaisvius, ne už kainą ir ne už atlygį, sako kariuomenių VIEŠPATS.'),
  (@b23, 45, 14, 'Taip sako VIEŠPATS: ‘Egipto triūsas, Etiopijos ir aukštaūgių sebų prekyba pereis pas tave ir jie bus tavo; jie ateis paskui tave; jie ateis grandinėse ir parpuolę prieš tave maldaus tave, sakydami: ‘Tikrai tavyje yra Dievas; ir nėra nieko, jokio kito Dievo’.'),
  (@b23, 45, 15, 'Tikrai tu esi Dievas, kuris slepiesi, o Izraelio Dieve, Gelbėtojau.'),
  (@b23, 45, 16, 'Jie bus sugėdinti ir susigės – jie visi; stabų darytojai kartu eis į sumišimą.'),
  (@b23, 45, 17, 'Bet Izraelis bus išgelbėtas VIEŠPATYJE amžinu išgelbėjimu; jūs nebūsite sugėdinti nei susigėsite pasaulyje be pabaigos.'),
  (@b23, 45, 18, 'Nes taip sako VIEŠPATS, kuris sutvėrė dangus; pats Dievas, kuris suformavo žemę ir ją padarė; jis ją įtvirtino, jis nesutvėrė jos tuščiai, jis ją suformavo, kad būtų apgyvendinta; aš esu VIEŠPATS, ir nėra kito.'),
  (@b23, 45, 19, 'Aš nekalbėjau slaptomis tamsioje žemės vietoje; aš nesakiau Jokūbo sėklai: ‘Ieškokite manęs veltui’; aš, VIEŠPATS, kalbu teisumą, aš skelbiu, kas teisinga.'),
  (@b23, 45, 20, 'Susirinkite ir ateikite; priartėkite drauge, tautų pabėgėliai; neturi pažinimo tie, kurie pastato savo raižyto atvaizdo medį ir meldžiasi dievui, kuris negali išgelbėti.'),
  (@b23, 45, 21, 'Kalbėkite ir atveskite juos artyn; taip, tegul jie pasitaria drauge; kas tai paskelbė nuo senovės laikų? Kas tai pranešė nuo tų laikų? Argi ne aš, VIEŠPATS? Be manęs nėra kito Dievo; teisingo Dievo ir Gelbėtojo; nėra nei vieno be manęs.'),
  (@b23, 45, 22, 'Žiūrėkite į mane ir būkite išgelbėti, visi žemės pakraščiai; nes aš esu Dievas, ir nėra kito.'),
  (@b23, 45, 23, 'Savimi aš prisiekiau, iš mano burnos išėjo žodis teisumu ir nesugrįš, kad: ‘Man nusilenks kiekvienas kelis, prisieks kiekvienas liežuvis’.'),
  (@b23, 45, 24, '‘Iš tiesų, – sakys, – VIEŠPATYJE turiu teisumą ir stiprybę’; žmonės ateis pas jį; ir visi, kurie yra įnirtę ant jo, bus susigėdę.'),
  (@b23, 45, 25, 'Visa Izraelio sėkla bus išteisinta VIEŠPATYJE ir didžiuosis“.'),
  (@b23, 46, 1, '„Belis nusilenkia, Nebas susikūprina, jų stabai buvo ant gyvulių ir ant galvijų; jūsų naštos buvo labai apkrautos; jos yra našta pavargusiems gyvuliams.'),
  (@b23, 46, 2, 'Jie susikūprina, jie nusilenkia drauge; jie negalėjo išgelbėti naštos, bet patys išėjo į nelaisvę.'),
  (@b23, 46, 3, 'Klausykite manęs, o Jokūbo namai, ir visas Izraelio namų likuti, kurie esate mano nešiojami nuo pat pilvo, kurie esate nešiojami nuo pat įsčių;'),
  (@b23, 46, 4, 'ir iki jūsų senatvės aš esu tas; ir iki žilų plaukų aš jus nešiosiu; aš padariau ir aš nešiosiu; būtent aš jus nešiosiu ir išvaduosiu.'),
  (@b23, 46, 5, 'Su kuo mane palyginsite ir su kuo mane sulyginsite ir mane prilyginsite, kad mes būtume panašūs?'),
  (@b23, 46, 6, 'Jie švaisto auksą iš maišelio ir sidabrą pasveria svarstyklėmis, ir pasisamdo auksakalį; ir jis padaro iš to dievą; jie parpuola, taip, jie garbina.'),
  (@b23, 46, 7, 'Jie pakelia jį ant peties, jį neša ir padeda į jo vietą, ir jis stovi; iš savo vietos jis nejuda; taip, jo šaukiasi, tačiau jis negali nei atsiliepti, nei išgelbėti jo iš bėdos.'),
  (@b23, 46, 8, 'Atsiminkite tai ir pasirodykite vyrais; vėl prisiminkite tai, jūs nusižengėliai.'),
  (@b23, 46, 9, 'Atsiminkite ankstesnius dalykus nuo seno; nes aš esu Dievas, ir nėra kito; aš esu Dievas, ir nėra tokio, kaip aš,'),
  (@b23, 46, 10, 'skelbiančio pabaigą nuo pradžios ir nuo senovės laikų tai, kas dar nėra įvykę, sakančio: ‘Mano sumanymas išsilaikys, ir aš padarysiu visa, ko noriu’.'),
  (@b23, 46, 11, 'Aš šaukiu iš rytų plėšrų paukštį, iš tolimos šalies vyrą, vykdantį mano sumanymą; taip, aš kalbėjau, aš tai ir įvykdysiu; aš nutariau, aš tai ir padarysiu.'),
  (@b23, 46, 12, 'Klausykite manęs, jūs, atkakliaširdžiai, kurie esate toli nuo teisumo;'),
  (@b23, 46, 13, 'aš priartinu savo teisumą; jis nebus toli, ir mano išgelbėjimas neuždels; ir aš padėsiu Sione išgelbėjimą, Izraeliui savo šlovę“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b23, 47, 1, '„Nuženk ir atsisėsk dulkėse, o mergele, Babilono dukra, atsisėsk ant žemės; nėra sosto, o kaldėjų dukra; nes tavęs nebevadins švelnia ir išlepusia.'),
  (@b23, 47, 2, 'Paimk girnas ir malk miltus; atidenk savo garbanas, apnuogink kojas, atidenk šlaunis, pereik per upes.'),
  (@b23, 47, 3, 'Bus atidengtas tavo nuogumas, taip, tavo gėda bus matoma; aš atkeršysiu, ir aš nesusitiksiu su tavimi kaip žmogus.'),
  (@b23, 47, 4, 'Mūsų atpirkėjas – jo vardas kariuomenių VIEŠPATS, Izraelio Šventasis.'),
  (@b23, 47, 5, 'Tyliai sėdėk ir įeik į tamsybę, o kaldėjų dukra; nes tavęs nebevadins karalysčių ponia.'),
  (@b23, 47, 6, 'Aš buvau užsirūstinęs ant savo tautos, suteršiau savo paveldą ir juos padaviau į tavo ranką; tu neparodei jiems gailestingumo; ant senolio tu uždėjai labai sunkų savo jungą.'),
  (@b23, 47, 7, 'Ir tu sakei: ‘Per amžius būsiu ponia’; taip, kad tu neįsidėjai tų dalykų į savo širdį nei neprisiminei jų galo.'),
  (@b23, 47, 8, 'Todėl dabar tai išklausyk, tu, atsidavusi malonumams, kuri gyveni nerūpestingai, kuri sakai savo širdyje: ‘Aš esu, ir be manęs nėra kitos; aš nesėdėsiu kaip našlė ir nepatirsiu vaikų netekimo’;'),
  (@b23, 47, 9, 'tačiau akimirksniu, vieną dieną tave ištiks šitie du dalykai: vaikų netekimas ir našlystė; jie visu pilnumu tave ištiks dėl daugybės tavo burtų ir dėl didelės gausybės tavo kerų.'),
  (@b23, 47, 10, 'Nes tu pasitikėjai savo nedorybe; tu sakei: ‘Niekas manęs nemato’. Tavo išmintis ir tavo pažinimas – jie iškreipė tave; tu sakei savo širdyje: ‘Aš esu ir be manęs nėra kitos’.'),
  (@b23, 47, 11, 'Todėl ant tavęs užeis nelaimė; tu nežinosi, iš kur ji kyla; ir tave užpuls bėda; tu nepajėgsi jos atitraukti; ir staiga ateis ant tavęs suniokojimas, apie kurį tu nežinai.'),
  (@b23, 47, 12, 'Nagi stokis su savo kerais ir su daugybe savo burtų, kuriuose triūsei nuo savo jaunystės; gal galėsi pasinaudoti, gal tu nugalėsi.'),
  (@b23, 47, 13, 'Tu nuvargai nuo savo patarimų daugybės. Dabar teatsistoja astrologai, žvaigždžių stebėtojai ir kurie prognozuoja kas mėnesį, ir teišgelbsti tave nuo to, kas ateina ant tavęs.'),
  (@b23, 47, 14, 'Štai jie bus kaip ražiena; ugnis juos sudegins; jie neišsigelbės iš liepsnos galios; nebus anglių pasišildymui nei ugnies, prie kurios galima atsisėsti.'),
  (@b23, 47, 15, 'Tokie tau bus tie, su kuriais triūsei – tavo pirkliai nuo tavo jaunystės; jie nuklys kiekvienas į savo vietą; nei vienas tavęs neišgelbės“.'),
  (@b23, 48, 1, '„Klausykite to, o Jokūbo namai, kurie vadinatės Izraelio vardu ir esate išėję iš Judos vandenų, kurie prisiekiate VIEŠPATIES vardu ir minite Izraelio Dievą, bet ne tiesoje ir ne teisume.'),
  (@b23, 48, 2, 'Nes jie vadina save esančiais iš šventojo miesto ir remiasi Izraelio Dievu; jo vardas – kariuomenių VIEŠPATS.'),
  (@b23, 48, 3, 'Aš paskelbiau ankstesnius dalykus nuo pradžios; jie išėjo iš mano burnos, ir aš juos išdėsčiau; akimirksniu aš tai padariau, ir jie įvyko.'),
  (@b23, 48, 4, 'Kadangi aš žinojau, kad tu užsispyręs, kad tavo sprandas yra geležinė sausgyslė ir tavo kakta žalvarinė,'),
  (@b23, 48, 5, 'aš tau tai pranešiau nuo pradžios; prieš įvykstant aš tau tai paskelbiau; kad nesakytum: ‘Mano stabas tai padarė, mano raižytas atvaizdas, mano nulietas atvaizdas tai įsakė’.'),
  (@b23, 48, 6, 'Tu girdėjai, pamatyk visa tai; argi jūs to nepripažinsite? Nuo to laiko aš tau paskelbiau naujų dalykų, būtent slaptų dalykų, ir tu jų nežinojai.'),
  (@b23, 48, 7, 'Jie sutverti dabar, o ne nuo pradžios; tai yra, pirmiau tos dienos, kai tu jų negirdėjai, kad nesakytum: ‘Štai aš juos žinojau’.'),
  (@b23, 48, 8, 'Taip, tu negirdėjai, taip, nežinojai; taip, nuo to laiko, kai tavo ausis nebuvo atverta; nes aš žinojau, kad tu būtumei pasielgęs labai išdavikiškai, ir nuo įsčių tave vadino nusižengėliu.'),
  (@b23, 48, 9, 'Dėl savo vardo aš atidėsiu savo pyktį ir vardan savo gyriaus aš dėl tavęs susilaikysiu, kad tavęs neiškirsčiau.'),
  (@b23, 48, 10, 'Štai aš tave išvaliau, bet ne su sidabru; aš tave išsirinkau vargo krosnyje.'),
  (@b23, 48, 11, 'Dėl savęs – dėl savęs tai darysiu; nes kaipgi būtų suterštas mano vardas? Ir savo šlovės aš neduosiu kitam.'),
  (@b23, 48, 12, 'Klausyk manęs, o Jokūbai, Izraeli, mano pašauktasis; aš esu tas; aš esu pirmasis, aš esu ir paskutinysis.'),
  (@b23, 48, 13, 'Taipogi mano ranka padėjo žemės pamatą, ir mano dešinė sprindžiais išmatavo dangus; kai aš juos pašaukiu, jie atsistoja drauge.'),
  (@b23, 48, 14, 'Susirinkite, jūs visi, ir klausykite; kas tarp jų yra paskelbęs šituos dalykus? VIEŠPATS jį pamilo; jis įvykdys jo norą ant Babilono, ir jo ranka bus ant kaldėjų.'),
  (@b23, 48, 15, 'Aš – būtent aš kalbėjau; taip, aš jį pašaukiau; aš jį atvedžiau ir jis padarys jo kelią klestintį.'),
  (@b23, 48, 16, 'Priartėkite prie manęs, klausykite to: ‘Nuo pradžios aš nekalbėjau slaptai; nuo to laiko, kai tai buvo, aš ten esu; o dabar Viešpats DIEVAS ir jo Dvasia pasiuntė mane’.'),
  (@b23, 48, 17, 'Taip sako VIEŠPATS, tavo Atpirkėjas, Izraelio Šventasis: ‘Aš esu VIEŠPATS, tavo Dievas, kuris tave moko, kas naudinga, kuris tave veda keliu, kuriuo tu turi eiti.'),
  (@b23, 48, 18, 'O kad tu būtum klausęs mano įsakymų! Tada tavo ramybė būtų buvusi kaip upė, ir tavo teisumas – kaip jūros bangos;'),
  (@b23, 48, 19, 'taip pat ir tavo sėkla būtų buvusi kaip smėlis, ir tavo vidurių palikuonys – kaip jo smiltys; jo vardas nebūtų buvęs iškirstas nei išnaikintas iš mano akivaizdos’.'),
  (@b23, 48, 20, 'Išeikite iš Babilono, bėkite nuo kaldėjų, giedojimo balsu skelbkite, sakykite tai, tarkite tai iki žemės pakraščių; sakykite: ‘VIEŠPATS atpirko savo tarną Jokūbą’.'),
  (@b23, 48, 21, 'Ir jie netroško, kai jis juos vedė per dykumas; jis padarė, kad vandenys jiems tekėtų iš uolos; taipogi jis perskėlė uolą, ir ištryško vandenys.'),
  (@b23, 48, 22, '„Nedorėliui nėra ramybės“, – sako VIEŠPATS.'),
  (@b23, 49, 1, 'Klausykite manęs, salos; ir klausykitės, tolimos tautos; VIEŠPATS mane pašaukė nuo įsčių, nuo mano motinos vidurių jis minėjo mano vardą.'),
  (@b23, 49, 2, 'Ir jis padarė mano burną lyg aštrų kalaviją; jis paslėpė mane savo rankos šešėlyje ir padarė mane nugludinta strėle; jis paslėpė mane savo strėlinėje;'),
  (@b23, 49, 3, 'ir man tarė: „Tu esi mano tarnas, o Izraeli, kuriame aš būsiu pašlovintas“.'),
  (@b23, 49, 4, 'Tada aš tariau: „Aš veltui triūsiau, tuščiai ir veltui eikvojau savo jėgas; tačiau tikrai mano teismas yra pas VIEŠPATĮ ir mano darbas pas mano Dievą“.'),
  (@b23, 49, 5, '„O dabar, – sako VIEŠPATS, kuris nuo įsčių mane suformavo būti jo tarnu, kad sugrąžinčiau Jokūbą, – nors Izraelis nesusirinktų, tačiau aš būsiu šlovingas VIEŠPATIES akyse, ir mano Dievas bus mano stiprybė“.'),
  (@b23, 49, 6, 'Ir jis tarė: „Per maža, kad būtum mano tarnas Izraelio gentims pakelti ir Izraelio išsaugotiems sugrąžinti; aš dar tave duosiu kaip šviesą pagonims, kad būtum mano išgelbėjimas iki žemės pakraščių“.'),
  (@b23, 49, 7, 'Taip sako VIEŠPATS, Izraelio Atpirkėjas, jo Šventasis, tam, kurį žmonės niekina, tam, kuriuo bjaurisi tauta, valdovų tarnui: „Karaliai pamatys ir pakils, taip pat kunigaikščiai garbins dėl VIEŠPATIES, kuris ištikimas, ir dėl Izraelio Šventojo, ir jis tave išsirinks“.'),
  (@b23, 49, 8, 'Taip sako VIEŠPATS: „Priimtinu metu išklausiau tave ir išgelbėjimo dieną tau padėjau; aš tave išsaugosiu ir duosiu tave tautos sandorai, kad įtvirtintum žemę, kad duotum paveldėti apleistus paveldus;'),
  (@b23, 49, 9, 'kad sakytum kaliniams: ‘Išeikite’; tiems, kurie tamsoje: ‘Pasirodykite’. Jie ganysis keliuose, ir jų ganyklos bus visose aukštumose.'),
  (@b23, 49, 10, 'Jie nealks ir netrokš; ir jų neištiks nei kaitra, nei saulė; nes tas, kuris jų pasigaili, ves juos, prie vandens šaltinių juos vedžios.'),
  (@b23, 49, 11, 'Ir aš padarysiu visus savo kalnus keliu, ir mano vieškeliai bus išaukštinti.'),
  (@b23, 49, 12, 'Štai šitie ateis iš toli; ir štai šitie iš šiaurės ir iš vakarų; o šitie iš Sinimo šalies“.'),
  (@b23, 49, 13, 'Giedokite, o dangūs; ir džiūgauk, o žeme; ir pratrūkite giedojimu, o kalnai; nes VIEŠPATS paguodė savo tautą ir savo prispaustųjų pasigailės.'),
  (@b23, 49, 14, 'Bet Sionas sakė: „VIEŠPATS paliko mane, mano Viešpats pamiršo mane“.'),
  (@b23, 49, 15, 'Ar gali moteris pamiršti savo žindomą vaiką, kad nepasigailėtų savo įsčių sūnaus? Taip, jos gal ir pamirštų, tačiau aš tavęs nepamiršiu.'),
  (@b23, 49, 16, 'Štai aš tave išraižiau ant savo rankų delnų; tavo sienos nuolat yra mano akivaizdoje.'),
  (@b23, 49, 17, 'Tavo vaikai skubės; tavo naikintojai ir tave nusiaubusieji išeis iš tavęs.'),
  (@b23, 49, 18, 'Pakelk akis ir pažvelk aplinkui: tie visi susirenka ir ateina pas tave. „Kaip aš gyvas, – sako VIEŠPATS, – tu tikrai jais visais apsirengsi kaip papuošalais, ir jais apsiriši, kaip jaunoji apsiriša.'),
  (@b23, 49, 19, 'Nes tavo tuščios bei tavo negyvenamos vietos ir tavo sunaikinta šalis dabar bus per ankšta dėl gyventojų, o tie, kurie tave prarijo, bus toli.'),
  (@b23, 49, 20, 'Vaikai, kuriuos tu turėsi po to, kai būsi praradęs kitus, vėl sakys tau į ausis: ‘Man per ankšta ta vieta; duok man vietos, kad galėčiau gyventi’.'),
  (@b23, 49, 21, 'Tada tu tarsi savo širdyje: ‘Kas man pagimdė šituos? Aš juk praradau savo vaikus ir esu apleista, belaisvė, perkeliama ten ir atgal; ir kas šituos užaugino? Štai aš buvau palikta viena; šitie – kur jie buvo?’“'),
  (@b23, 49, 22, 'Taip sako Viešpats DIEVAS: „Štai aš pakelsiu savo ranką į pagonis ir iškelsiu savo vėliavą tautoms; ir jie atgabens tavo sūnus savo rankose, ir tavo dukterys bus nešamos ant jų pečių.'),
  (@b23, 49, 23, 'O karaliai bus tavo maitintojai, ir jų karalienės – tavo žindyvės; jie tau nusilenks veidu į žemę ir laižys tavo kojų dulkes; ir tu žinosi, kad aš esu VIEŠPATS; nes tie, kurie manęs laukia, nebus sugėdinti“.'),
  (@b23, 49, 24, 'Ar iš galingojo atims grobį? Ar teisėtas belaisvis bus išvaduotas?'),
  (@b23, 49, 25, 'Bet taip sako VIEŠPATS: „Net galingojo belaisviai bus atimti, ir baisiojo grobis bus išvaduotas; nes aš varžysiuos su tuo, kuris varžosi su tavimi, ir tavo vaikus išgelbėsiu.'),
  (@b23, 49, 26, 'Ir aš maitinsiu tavo engėjus jų pačių kūnu; ir jie pasigers nuo savo pačių kraujo kaip nuo saldaus vyno; ir visi kūnai žinos, kad aš, VIEŠPATS, esu tavo Gelbėtojas ir tavo Atpirkėjas, Jokūbo Galingasis“.'),
  (@b23, 50, 1, 'Taip sako VIEŠPATS: „Kur yra skyrybų raštas jūsų motinos, kurią aš atleidau? Arba kuris iš mano skolintojų yra tas, kuriam aš jus pardaviau? Štai dėl savo neteisybių jūs pardavėte save, ir dėl jūsų nusižengimų jūsų motina atleista.'),
  (@b23, 50, 2, 'Kodėl man atėjus nei vieno nebuvo? Man šaukiant, nebuvo kas atsilieptų? Ar tikrai per trumpa mano ranka, kad negali atpirkti? Arba, ar aš neturiu jėgos išvaduoti? Štai savo barimu aš išdžiovinu jūrą, upes paverčiu dykuma; jų žuvys dvokia, nes nėra vandens, ir padvesia iš troškulio.'),
  (@b23, 50, 3, 'Aš apvelku dangus juodumu ir darau ašutinę jų apdangalu“.'),
  (@b23, 50, 4, 'Viešpats DIEVAS man davė mokyto liežuvį, kad žinočiau kaip laiku kalbėti žodį pavargusiam; jis pažadina kas rytą, jis pažadina mano ausį, kad klausyčiausi kaip mokytas.'),
  (@b23, 50, 5, 'Viešpats DIEVAS atvėrė man ausį, ir aš nemaištavau ir nenusisukau atgal.'),
  (@b23, 50, 6, 'Aš daviau savo nugarą mušantiems ir savo skruostus – pešantiems plaukus; aš neslėpiau savo veido nuo sugėdinimo ir spjaudymo.'),
  (@b23, 50, 7, 'Bet Viešpats DIEVAS man padės; todėl aš nebūsiu sugėdintas; todėl padariau savo veidą kaip titnagą, ir žinau, kad neturėsiu gėdytis.'),
  (@b23, 50, 8, 'Arti yra tas, kuris mane išteisina; kas varžysis su manimi? Atsistokime kartu; kas yra mano priešininkas? Teprieina jis prie manęs.'),
  (@b23, 50, 9, 'Štai Viešpats DIEVAS man padės; kas yra tas, kuris mane pasmerks? Štai jie visi pasens kaip drabužis; kandys juos suės.'),
  (@b23, 50, 10, 'Kas yra tarp jūsų, kuris bijo VIEŠPATIES, kuris paklūsta jo tarno balsui, kuris vaikšto tamsoje ir neturi šviesos? Tas tepasitiki VIEŠPATIES vardu ir tesiremia savo Dievu.'),
  (@b23, 50, 11, 'Štai jūs visi, kurie užkuriate ugnį, kurie apsupate save žiežirbomis; vaikščiokite savo ugnies šviesoje ir žiežirbose, kurias uždegėte. Tai jūs turėsite nuo mano rankos: jūs atsigulsite į sielvartą.'),
  (@b23, 51, 1, '„Klausykitės manęs, jūs, kurie sekate paskui teisumą, jūs, kurie ieškote VIEŠPATIES; pažvelkite į uolą, iš kurios esate iškirsti, ir į duobės angą, iš kurios esate iškasti.'),
  (@b23, 51, 2, 'Pažvelkite į savo tėvą Abraomą ir į Sarą, kuri jus pagimdė; nes aš jį vienintelį pašaukiau, palaiminau jį ir jį padauginau“.'),
  (@b23, 51, 3, 'Nes VIEŠPATS paguos Sioną; jis paguos visas jo dykvietes; jis padarys jo tyrlaukius kaip Edeną, jo dykumą kaip VIEŠPATIES sodą; džiaugsmas ir linksmybė rasis jame, padėka ir melodijos garsas.'),
  (@b23, 51, 4, 'Mano tauta, klausykis manęs; ir atsuk į mane ausį, o mano tauta; nes įstatymas išeis iš manęs, ir padarysiu, kad mano teismas ilsėtųsi kaip šviesa tautoms.'),
  (@b23, 51, 5, 'Mano teisumas arti; išėjo mano išgelbėjimas, ir mano rankos teis tautas; salos lauks manęs ir jos pasitikės mano ranka.'),
  (@b23, 51, 6, 'Pakelkite savo akis į dangus ir pažvelkite į žemę apačioje; nes dangūs išnyks kaip dūmai, ir žemė pasens kaip drabužis, ir joje gyvenantys tokiu pat būdu išmirs; bet mano išgelbėjimas bus per amžius ir mano teisumas nebus panaikintas.'),
  (@b23, 51, 7, 'Klausykitės manęs, jūs, kurie pažįstate teisumą, tauta, kurių širdyje yra mano įstatymas; nebijokite žmonių priekaištavimo ir neišsigąskite jų plūdimo.'),
  (@b23, 51, 8, 'Nes kaip drabužį juos suės kandys, ir kaip vilną juos suės kirminas; bet mano teisumas bus per amžius ir mano išgelbėjimas iš kartos į kartą.'),
  (@b23, 51, 9, 'Pabusk, pabusk, apsivilk jėga, o VIEŠPATIES ranka; pabusk, kaip senovės dienomis, kaip senosiomis kartomis. Ar ne tu tas, kuris sukapojo Rahabą ir sužeidė slibiną?'),
  (@b23, 51, 10, 'Ar ne tu tas, kuris išdžiovino jūrą, didžiulių gelmių vandenis, kuris jūros gelmes padarė keliu išpirktiesiems pereiti?'),
  (@b23, 51, 11, 'Todėl VIEŠPATIES atpirktieji sugrįš ir ateis į Sioną giedodami; ir amžinas džiaugsmas bus ant jų galvos; jie įgis linksmybę ir džiaugsmą; o sielvartas ir gedėjimas išnyks.'),
  (@b23, 51, 12, 'Aš – būtent aš esu tas, kuris jus guodžia; kas tu esi, kad bijotum žmogaus, kuris mirs, žmogaus sūnaus, kuris taps kaip žolė,'),
  (@b23, 51, 13, 'ir kad pamiršti VIEŠPATĮ, savo Kūrėją, kuris ištiesė dangus ir padėjo žemės pamatus, ir kad nuolat, kiekvieną dieną bijojai dėl engėjo įtūžio, tarsi jis buvo pasiruošęs sunaikinti? Ir kur yra engėjo įtūžis?'),
  (@b23, 51, 14, 'Ištremtas belaisvis skuba, kad būtų išlaisvintas ir kad nemirtų duobėje, ir kad nestigtų jam duonos.'),
  (@b23, 51, 15, 'Bet aš esu VIEŠPATS, tavo Dievas, kuris padalijo jūrą, kurios bangos šniokštė; kariuomenių VIEŠPATS yra jo vardas.'),
  (@b23, 51, 16, 'Ir aš įdėjau savo žodžius tau į burną ir apdengiau tave savo rankos šešėliu, kad pasodinčiau dangus ir padėčiau žemės pamatus, ir sakyčiau Sionui: ‘Tu esi mano tauta’“.'),
  (@b23, 51, 17, 'Pabusk, pabusk, atsistok, o Jeruzale, kuri gėrei iš VIEŠPATIES rankos jo įtūžio taurę; tu gėrei drebėjimo taurės nuosėdas ir jas išgręžei.'),
  (@b23, 51, 18, 'Nėra kas ją vedžiotų iš visų sūnų, kuriuos ji pagimdė; ir nėra kas paimtų ją už rankos iš visų sūnų, kuriuos ji užaugino.'),
  (@b23, 51, 19, 'Tie du dalykai ištiko tave, kas tavęs gailėsis? Suniokojimas ir sunaikinimas, badas ir kalavijas; kuo aš tave paguosiu?'),
  (@b23, 51, 20, 'Tavo sūnūs nualpę, jie guli visų gatvių kampuose kaip laukinis bulius tinkle; jie pilni VIEŠPATIES įtūžio, tavo Dievo pabarimo.'),
  (@b23, 51, 21, 'Todėl dabar tai klausyk, tu, nuvargintoji ir pasigėrusioji, bet ne nuo vyno;'),
  (@b23, 51, 22, 'taip sako VIEŠPATS, tavo Viešpats ir tavo Dievas, kuris gina savo tautos bylą: „Štai aš paėmiau iš tavo rankos drebėjimo taurę, tai yra, mano įtūžio taurės drumzles; tu jos daugiau nebegersi;'),
  (@b23, 51, 23, 'bet aš ją įdėsiu į ranką tų, kurie vargina tave; kurie sakė tavo sielai: ‘Pasilenk, kad pereitume viršumi’; ir tu paguldei savo kūną kaip žemę, kaip gatvę tiems, kurie ėjo viršumi“.'),
  (@b23, 52, 1, 'Pabusk, pabusk; apsivilk savo stiprybe, o Sione; apsirenk savo gražiais drabužiais, o Jeruzale, šventasis mieste; nes nuo šiol daugiau nebeįeis į tave neapipjaustytas ir nešvarus.'),
  (@b23, 52, 2, 'Nusikratyk dulkes; kelkis ir atsisėsk, o Jeruzale; atsirišk nuo kaklo pančius, o belaisve Siono dukra.'),
  (@b23, 52, 3, 'Nes taip sako VIEŠPATS: „Jūs pardavėte save už nieką; ir būsite atpirkti be pinigų“.'),
  (@b23, 52, 4, 'Nes taip sako Viešpats DIEVAS: „Seniau mano tauta buvo nuėjusi žemyn į Egiptą ten laikinai apsigyventi; ir asiras be priežasties juos engė.'),
  (@b23, 52, 5, 'Taigi dabar, ką aš čia turiu, – sako VIEŠPATS, – kad mano tauta paimta už nieką? Ją valdantys priverčia ją kaukti, – sako VIEŠPATS, – ir nuolatos, kiekvieną dieną, piktžodžiaujama mano vardui.'),
  (@b23, 52, 6, 'Todėl mano tauta pažins mano vardą; todėl tą dieną jie žinos, kad aš esu tas, kuris kalba: ‘Štai tai aš’.'),
  (@b23, 52, 7, 'Kokios gražios kalnuose kojos to, kuris neša gerą žinią, kuris skelbia taiką; kuris neša gerą žinią apie gera, kuris skelbia išgelbėjimą; kuris sako Sionui: „Tavo Dievas karaliauja!“'),
  (@b23, 52, 8, 'Tavo sargybiniai pakels balsą; drauge jie balsu giedos; nes jie matys akis į akį, kai VIEŠPATS sugrąžins Sioną.'),
  (@b23, 52, 9, 'Pratrūkite džiaugsmu, giedokite drauge, jūs, Jeruzalės griuvėsiai; nes VIEŠPATS paguodė savo tautą, jis atpirko Jeruzalę.'),
  (@b23, 52, 10, 'VIEŠPATS apnuogino savo šventąją ranką visų tautų akyse; ir visi žemės pakraščiai matys mūsų Dievo išgelbėjimą.'),
  (@b23, 52, 11, 'Traukitės, traukitės, išeikite iš ten, nelieskite to, kas nešvaru; išeikite iš jo tarpo; būkite švarūs, jūs, kurie nešate VIEŠPATIES indus.'),
  (@b23, 52, 12, 'Nes jūs neišeisite skubėdami ir neisite bėgdami; nes pirma jūsų eis VIEŠPATS; ir Izraelio Dievas bus jūsų užnugaris.'),
  (@b23, 52, 13, 'Štai mano tarnas elgsis protingai, jis bus išaukštintas, liaupsinamas ir labai aukštas.'),
  (@b23, 52, 14, 'Kaip daugelis buvo apstulbinti tavęs; jo veidas buvo sudarkytas labiau už bet kokį žmogų, ir jo pavidalas – labiau už žmonių sūnus;'),
  (@b23, 52, 15, 'taip jis apšlakstys daugelį tautų; karaliai užčiaups prieš jį savo burnas; nes apie ką jiems nebuvo pasakota, jie pamatys; ir ko nebuvo girdėję, jie apgalvos“.'),
  (@b23, 53, 1, 'Kas tikėjo mūsų pranešimu? Ir kam yra apreikšta VIEŠPATIES ranka?'),
  (@b23, 53, 2, 'Nes jis išaugs jo akivaizdoje kaip gležnas sodinys ir kaip šaknis iš sausos žemės; jis neturi nei pavidalo, nei gražumo; ir kai žiūrime į jį, nėra jokio grožio, kad jo norėtume.'),
  (@b23, 53, 3, 'Jis yra paniekintas ir žmonių atmestas; skausmų vyras, sielvartą pažinęs; mes tarsi slėpėme nuo jo savo veidus; jis buvo paniekintas, ir mes jo nevertinome.'),
  (@b23, 53, 4, 'Tikrai jis pakėlė mūsų sielvartus ir nešiojo mūsų skausmus; o mes jį laikėme ištiktu, Dievo sumuštu ir kamuojamu.'),
  (@b23, 53, 5, 'Bet jis buvo sužeistas už mūsų nusižengimus, sumuštas už mūsų neteisybes; bausmė dėl mūsų ramybės buvo ant jo; ir jo rėžiais mes esame išgydyti.'),
  (@b23, 53, 6, 'Mes visi pasiklydę kaip avys, mes kiekvienas sukome į savo kelią; o VIEŠPATS uždėjo ant jo mūsų visų neteisybę.'),
  (@b23, 53, 7, 'Jis buvo engiamas ir kamuojamas, tačiau jis neatvėrė savo burnos; kaip avinėlis jis buvo vedamas pjauti ir kaip avis, tylinti prieš savo kirpėjus, jis neatvėrė savo burnos.'),
  (@b23, 53, 8, 'Jis buvo paimtas iš kalėjimo ir iš teismo; ir kas paskelbs jo kartą? Nes jis buvo iškirstas iš gyvųjų šalies; jis buvo ištiktas už mano tautos nusižengimą.'),
  (@b23, 53, 9, 'Jis paruošė jo kapą su nedorėliais ir su turtuoliais jam mirus; nes jis nevartojo smurto, ir jokios apgaulės nebuvo jo burnoje.'),
  (@b23, 53, 10, 'Tačiau VIEŠPATS panoro jį sumušti; jis atidavė jį sielvartui; kai tu padarysi jo sielą atnaša už nuodėmę, jis matys savo sėklą, jis prailgins savo dienas, ir VIEŠPATIES valia klestės jo rankoje.'),
  (@b23, 53, 11, 'Jis matys jo sielos kančias ir bus patenkintas; per savo pažinimą mano teisusis tarnas išteisins daugelį; nes jis nešios jų neteisybes.'),
  (@b23, 53, 12, 'Todėl aš jam padalinsiu dalį su didžiaisiais, ir jis pasidalins grobį su stipriaisiais; kadangi jis išliejo savo sielą mirčiai; ir jis buvo priskaičiuotas prie nusižengėlių; ir jis nešiojo daugelio nuodėmę ir užtarė nusižengėlius.'),
  (@b23, 54, 1, '„Giedok, o nevaisingoji, tu, kuri negimdei; pratrūk giesme ir garsiai šūkauk, tu, kuri nepatyrei gimdymo skausmų; nes daugiau yra apleistosios vaikų negu vedusios žmonos vaikų, – sako VIEŠPATS.'),
  (@b23, 54, 2, '– Praplėsk savo palapinės vietą ir tegul jie ištempia tavo buveinių uždangas; netausok, pailgink savo virves ir sustiprink savo kuolus;'),
  (@b23, 54, 3, 'nes tu išsiverši į dešinę ir į kairę; ir tavo sėkla paveldės pagonis ir apgyvendins tuščius miestus.'),
  (@b23, 54, 4, 'Nebijok, nes tau nereikės susigėsti; ir nesidrovėk, nes tu nebūsi sugėdinta; nes tu pamirši savo jaunystės gėdą ir nebeatsiminsi savo našlystės priekaištų.'),
  (@b23, 54, 5, 'Nes tavo Kūrėjas yra tavo vyras; kariuomenių VIEŠPATS yra jo vardas; ir tavo Atpirkėjas – Izraelio Šventasis; jis bus vadinamas visos žemės Dievu.'),
  (@b23, 54, 6, 'Nes VIEŠPATS pašaukė tave kaip moterį, paliktą ir sielvartaujančią dvasioje, ir kaip jaunystės žmoną, kai buvai atmesta, – sako tavo Dievas.'),
  (@b23, 54, 7, '– Trumpai akimirkai aš palikau tave; bet dideliais gailestingumais tave surinksiu.'),
  (@b23, 54, 8, 'Trumpai rūstaudamas aš akimirkai paslėpiau savo veidą nuo tavęs; bet amžinu gerumu aš tavęs pasigailėsiu, – sako VIEŠPATS, tavo Atpirkėjas.'),
  (@b23, 54, 9, '– Nes man tai yra kaip Nojaus vandenys: nes kaip aš prisiekiau, kad Nojaus vandenys nebeužlies žemės, taip aš prisiekiau, kad nerūstausiu ant tavęs ir nebarsiu tavęs.'),
  (@b23, 54, 10, 'Nes kalnai pasitrauks ir kalvos pasišalins; bet mano gerumas nepasitrauks nuo tavęs, nei mano taikos sandora nepasišalins“, – sako VIEŠPATS, kuris gailisi tavęs.'),
  (@b23, 54, 11, '„O tu varginta, audros blaškoma ir nepaguosta; štai aš sudėsiu tavo akmenis gražiomis spalvomis ir padėsiu tavo pamatus iš safyrų.'),
  (@b23, 54, 12, 'Ir aš padarysiu tavo langus iš agato ir tavo vartus iš raudonojo granato, ir visas tavo ribas iš gražių akmenų.'),
  (@b23, 54, 13, 'Ir visi tavo vaikai bus mokomi VIEŠPATIES; ir didelė bus tavo vaikų ramybė.'),
  (@b23, 54, 14, 'Teisume tu būsi įtvirtinta; tu būsi toli nuo engimo, nes tu nebijosi, ir nuo siaubo, nes jis prie tavęs nepriartės.'),
  (@b23, 54, 15, 'Štai jie tikrai susirinks, bet ne prie manęs; kas susirinks prieš tave, kris dėl tavęs.'),
  (@b23, 54, 16, 'Štai aš sutvėriau kalvį, kuris įpučia anglis ugnyje ir pagamina įrankį savo darbui; ir aš sutvėriau niokotoją, kad naikintų.'),
  (@b23, 54, 17, 'Joks ginklas, padarytas prieš tave, neturės sėkmės; ir kiekvieną liežuvį, kuris kelsis prieš tave teisme, tu pasmerksi. Tai yra VIEŠPATIES tarnų paveldas, ir jų teisumas yra iš manęs“, – sako VIEŠPATS.'),
  (@b23, 55, 1, '„Ei, visi, kurie trokštate, ateikite prie vandenų, ir kurie neturite pinigų; ateikite, pirkite ir valgykite; taip, ateikite, pirkite vyno ir pieno be pinigų ir ne už kainą.'),
  (@b23, 55, 2, 'Kodėl jūs eikvojate pinigus tam, kas nėra duona? Ir savo triūsą tam, kas nepasotina? Klausykite manęs atidžiai ir valgykite tai, kas gera, ir tesimėgauja jūsų siela riebumais.'),
  (@b23, 55, 3, 'Palenkite savo ausį ir ateikite pas mane; klausykite, ir jūsų siela gyvens; ir aš sudarysiu su jumis amžiną sandorą – tikrus Dovydo gailestingumus.'),
  (@b23, 55, 4, 'Štai aš jį daviau liudytoju tautoms, vadovu ir įsakytoju tautoms.'),
  (@b23, 55, 5, 'Štai tu pašauksi tautą, kurios nepažįsti, ir tautos, kurios nepažino tavęs, atbėgs pas tave dėl VIEŠPATIES, tavo Dievo, ir dėl Izraelio Šventojo; nes jis tave pašlovino.'),
  (@b23, 55, 6, 'Ieškokite VIEŠPATIES, kol galima jį rasti, šaukitės jo, kol jis arti;'),
  (@b23, 55, 7, 'nedorėlis tepalieka savo kelią ir neteisus žmogus savo mintis; tegrįžta jis pas VIEŠPATĮ, ir jis jo pasigailės; pas mūsų Dievą, nes jis gausiai atleis.'),
  (@b23, 55, 8, 'Nes mano mintys – ne jūsų mintys, ir jūsų keliai – ne mano keliai, – sako VIEŠPATS.'),
  (@b23, 55, 9, '– Nes kaip dangūs yra aukštesni už žemę, taip mano keliai yra aukštesni už jūsų kelius ir mano mintys – už jūsų mintis.'),
  (@b23, 55, 10, 'Nes kaip nusileidžia lietus ir sniegas iš dangaus ir ten nesugrįžta, bet sudrėkina žemę ir padaro, kad ji gimdytų ir pumpuruotų, idant ji duotų sėklos sėjėjui ir duonos valgytojui;'),
  (@b23, 55, 11, 'taip bus ir mano žodis, kuris išeina iš mano burnos: jis nesugrįš pas mane tuščias, bet įvykdys tai, ko aš noriu, ir bus sėkmingas tame, dėl ko jį siunčiu.'),
  (@b23, 55, 12, 'Nes jūs išeisite su džiaugsmu ir būsite išvedami su ramybe; kalnai ir kalvos pratrūks giedojimu jūsų akivaizdoje, ir visi lauko medžiai plos rankomis.'),
  (@b23, 55, 13, 'Erškėčių vietoje augs eglės, ir erškėtrožių vietoje augs mirtos; ir tai VIEŠPAČIUI bus dėl vardo, dėl amžino ženklo, kuris nebus iškirstas“.'),
  (@b23, 56, 1, 'Taip sako VIEŠPATS: „Laikykitės teismo ir vykdykite teisingumą; nes arti mano išgelbėjimas, kad ateitų, ir mano teisumas, kad būtų apreikštas.'),
  (@b23, 56, 2, 'Palaimintas žmogus, kuris tai daro, ir žmogaus sūnus, kuris to nusitveria; kuris saugo sabatą nuo suteršimo ir saugo savo ranką, kad nedarytų nieko pikta.'),
  (@b23, 56, 3, 'Ir tenesako svetimšalio sūnus, prisijungęs prie VIEŠPATIES, sakydamas: ‘VIEŠPATS visiškai mane atskyrė nuo savo tautos’; ir tenesako eunuchas: ‘Štai aš esu sudžiūvęs medis’.'),
  (@b23, 56, 4, 'Nes taip sako VIEŠPATS eunuchams, kurie saugo mano sabatus ir pasirenka tai, kas man patinka, ir nusitveria mano sandoros:'),
  (@b23, 56, 5, '‘Aš jiems duosiu savo namuose ir savo sienų viduje vietą ir vardą, geresnį už sūnų ir už dukterų; aš jiems duosiu amžiną vardą, kuris nebus iškirstas.'),
  (@b23, 56, 6, 'Taip pat svetimšalio sūnus, prisijungusius prie VIEŠPATIES jam tarnauti ir mylėti VIEŠPATIES vardą, būti jo tarnais, kiekvieną, saugojantį sabatą nuo suteršimo ir nusitvėrusį mano sandoros,'),
  (@b23, 56, 7, 'juos aš atvesiu į savo šventąjį kalną ir juos pradžiuginsiu savo maldos namuose; jų deginamosios atnašos ir jų aukos bus priimtinos ant mano aukuro; nes mano namai bus vadinami maldos namais visoms tautoms’“.'),
  (@b23, 56, 8, 'Viešpats DIEVAS, kuris surenka Izraelio atstumtuosius, sako: „Aš dar surinksiu prie jo kitus, be tų, kurie yra prie jo surinkti.'),
  (@b23, 56, 9, 'Visi lauko žvėrys, taip, visi miško žvėrys, ateikite ėsti.'),
  (@b23, 56, 10, 'Jo sargybiniai yra akli; visi jie neišmanėliai, jie visi yra nebyliai šunys, jie negali loti; miegantys, gulintys, mėgstantys snausti.'),
  (@b23, 56, 11, 'Taip, jie yra godūs šunys, kuriems niekada neužtenka; jie yra ganytojai, kurie neturi supratimo; jie visi žiūri į savo kelią, kiekvienas savo naudai, iš savo vietos.'),
  (@b23, 56, 12, 'Jie sako: ‘Ateikite, aš atnešiu vyno, ir mes prisigersime stipraus gėrimo; o rytoj bus kaip ši diena, ir daug gausesnė’“.'),
  (@b23, 57, 1, '„Teisusis žūva, ir nei vienas neima to į širdį; ir gailestingi žmonės atimami niekam nesusimąstant, kad teisusis atimamas iš ateinančios piktybės.'),
  (@b23, 57, 2, 'Jis įžengs į ramybę; jie ilsėsis savo guoliuose, kiekvienas vaikščiojantis savo tiesumu.'),
  (@b23, 57, 3, 'Bet jūs, burtininkės sūnūs, svetimautojos ir paleistuvės sėkla, priartėkite čionai.'),
  (@b23, 57, 4, 'Prieš ką puikuojatės? Prieš ką plačiai atveriate burną ir iškišate liežuvį? Argi jūs nesate nusižengimo vaikai, melo sėkla,'),
  (@b23, 57, 5, 'užsidegę stabais po kiekvienu žaliuojančiu medžiu, kurie pjaunate vaikus slėniuose, uolų plyšiuose?'),
  (@b23, 57, 6, 'Tavo dalis yra tarp glotnių upelio akmenų; jie, jie yra tavo burtas; būtent jiems liejai geriamąją atnašą, atnašavai maisto atnašą. Ar šitais turėčiau patirti paguodą?'),
  (@b23, 57, 7, 'Ant didingo ir aukšto kalno tu pasiklojai guolį; ten tu lipai aukos atnašauti.'),
  (@b23, 57, 8, 'Už durų ir staktų tu pastatei savo atminimą; nes tu atidengei save kitam, ne man, ir užlipai; tu praplatinai savo guolį ir sudarei su jais sandorą; tu mėgai jų guolį, kur tik jį matei.'),
  (@b23, 57, 9, 'Tu nuėjai pas karalių su tepalu ir pasidauginai savo kvepalų, ir siuntei savo pasiuntinius toli, ir pažeminai save net iki pragaro.'),
  (@b23, 57, 10, 'Tu nusivarginai savo kelio didybe; tačiau nesakei: ‘Nėra vilties’; tu radai gyvybę savo rankoje; todėl tu nesisielojai.'),
  (@b23, 57, 11, 'Kurio tu išsigandai ar bijojai, kad melavai ir neprisiminei manęs, ir neėmei to į širdį? Argi ne aš tylėjau nuo seno, ir tu manęs nebijojai?'),
  (@b23, 57, 12, 'Aš paskelbsiu tavo teisumą ir tavo darbus; nes jie tau nebus naudingi.'),
  (@b23, 57, 13, 'Tau šaukiantis, teišvaduoja tave tavo draugijos; bet juos visus nuneš vėjas; tuštybė juos pasiims; tačiau kas pasitiki manimi, pasisavins šalį, ir paveldės mano šventąjį kalną;'),
  (@b23, 57, 14, 'ir sakys: ‘Supilkite, supilkite, paruoškite kelią, pašalinkite kliūtis iš mano tautos kelio’.'),
  (@b23, 57, 15, 'Nes taip sako Aukštasis ir Išaukštintasis, gyvenantis amžinybėje, kurio vardas yra Šventas: ‘Aš gyvenu aukštoje ir šventoje vietoje, ir su tuo, kuris yra palaužtos ir nuolankios dvasios, kad atgaivinčiau nuolankiųjų dvasią ir atgaivinčiau palaužtųjų širdį.'),
  (@b23, 57, 16, 'Nes aš neamžinai vaidysiuos ir nevisada rūstausiu; nes tada mano akivaizdoje sunyktų dvasia ir sielos, kurias aš padariau.'),
  (@b23, 57, 17, 'Dėl jo godumo neteisybės aš rūstavau ir sumušiau jį; aš pasislėpiau, rūstavau, bet jis toliau priešgyningai ėjo savo širdies keliu.'),
  (@b23, 57, 18, 'Aš mačiau jo kelius, ir jį pagydysiu; taip pat aš jį vedžiosiu ir atnaujinsiu paguodas jam ir jo raudotojams.'),
  (@b23, 57, 19, 'Aš sutveriu lūpų vaisių; ramybė, ramybė esančiam toli ir esančiam arti, – sako VIEŠPATS; – ir aš jį pagydysiu.'),
  (@b23, 57, 20, 'Bet nedorėliai yra kaip sudrumsta jūra, kai ji negali nurimti, kurios vandenys išmeta dumblą ir purvą.'),
  (@b23, 57, 21, 'Nedorėliui nėra ramybės“, – sako mano Dievas.'),
  (@b23, 58, 1, '„Šauk garsiai, nesusilaikyk, pakelk savo balsą kaip trimitą ir parodyk mano tautai jų nusižengimą ir Jokūbo namams jų nuodėmes.'),
  (@b23, 58, 2, 'Tačiau jie ieško manęs kas dieną ir su malonumu nori pažinti mano kelius kaip tauta, kuri vykdė teisumą ir nepaliko savo Dievo įsako; jie mane klausinėja teisingumo įsakų; jie su malonumu artinasi prie Dievo.'),
  (@b23, 58, 3, 'Jie sako: ‘Kodėl mes pasninkavome, o tu nematai? Kodėl mes varginome savo sielas, o tu nenori žinoti?’ Štai jūsų pasninko dieną jūs ieškote malonumo ir reikalaujate, kad dirbtų visokį jūsų darbą.'),
  (@b23, 58, 4, 'Štai jūs pasninkaujate dėl vaidų ir ginčų, ir kad smogtumėte nedorybės kumščiu; jūs nepasninkaukite, kaip šią dieną, kad jūsų balsas būtų išgirstas aukštybėje.'),
  (@b23, 58, 5, 'Ar tai toks pasninkas, kurį aš išsirinkau? Ar tai diena, kad žmogus vargintų savo sielą? Ar tai, kad jis nulenktų savo galvą kaip meldas ir patiestų po savimi ašutinę bei pelenus? Ar tai tu vadini pasninku ir VIEŠPAČIUI priimtina diena?'),
  (@b23, 58, 6, 'Argi ne tai yra pasninkas, kurį pasirinkau: atrišti nedorybės pančius, panaikinti sunkias naštas, paleisti į laisvę engiamuosius ir kad sulaužytumėte kiekvieną jungą?'),
  (@b23, 58, 7, 'Argi ne išdalinti savo duoną alkaniems ir kad atsivestum į namus išvarytus beturčius? Kad pamatęs nuogą jį pridengtum ir kad nesislėptum nuo savo paties kūno?'),
  (@b23, 58, 8, 'Tada tavo šviesa prašvis kaip aušra ir tavo sveikata skubiai išaugs; ir tavo teisumas eis pirma tavęs; VIEŠPATIES šlovė bus tavo užnugaris.'),
  (@b23, 58, 9, 'Tada tu šauksiesi, ir VIEŠPATS atsakys; tu šauksi, ir jis tars: ‘Štai aš’. Jei pašalinsi iš savo tarpo jungą, rodymą pirštu ir tuštybių kalbėjimą;'),
  (@b23, 58, 10, 'jei ištrauksi savo sielą alkstančiam ir patenkinsi vargstančią sielą; tada tavo šviesa patekės tamsoje, ir tavo tamsa bus kaip vidudienis;'),
  (@b23, 58, 11, 'ir VIEŠPATS nuolat tave vedžios ir patenkins tavo sielą sausroje, ir tavo kaulus nupenės; ir tu būsi kaip palaistytas sodas ir kaip vandens šaltinis, kurio vandenys neišsenka.'),
  (@b23, 58, 12, 'Ir tavieji atstatys senas dykvietes; tu iškelsi daugelio kartų pamatus; ir tave vadins spragų užtaisytoju, takų atstatytoju, kad juose būtų gyvenama.'),
  (@b23, 58, 13, 'Jei nukreipsi savo koją nuo sabato, kad nedarytum, kas tau patinka per mano šventą dieną, ir vadinsi sabatą pasigėrėjimu, VIEŠPATIES šventu bei garbingu; ir jį gerbsi, nedarydamas savo paties kelių, neieškodamas savo paties malonumo ir nekalbėdamas savo paties žodžių;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b23, 58, 14, 'tada tu gėrėsiesi VIEŠPAČIU; ir aš tave vešiu per žemės aukštumas ir tave maitinsiu tavo tėvo Jokūbo paveldu“; nes VIEŠPATIES burna tai kalbėjo.'),
  (@b23, 59, 1, 'Štai VIEŠPATIES ranka nesutrumpėjo, kad negalėtų gelbėti; nei jo ausis neapsunko, kad negalėtų girdėti;'),
  (@b23, 59, 2, 'bet jūsų neteisybės atskyrė jus nuo jūsų Dievo, ir jūsų nuodėmės paslėpė jo veidą nuo jūsų, kad jis negirdėtų.'),
  (@b23, 59, 3, 'Nes jūsų rankos suterštos krauju ir jūsų pirštai neteisybe; jūsų lūpos kalbėjo melus, jūsų liežuvis murmėjo iškreiptumą.'),
  (@b23, 59, 4, 'Niekas nesišaukia teisingumo ir niekas negina tiesos; jie pasitiki tuštybe ir kalba melus; jie pradeda piktadarybę ir pagimdo neteisybę.'),
  (@b23, 59, 5, 'Jie peri angies kiaušinius ir audžia voratinklius; kas valgo jų kiaušinių, tas miršta, o iš to, kuris sutraiškytas, išsikala gyvatė.'),
  (@b23, 59, 6, 'Jų tinklai netinka drabužiams, ir jie neprisidengs savo darbais; jų darbai – neteisybės darbai, ir jų rankose smurto veiksmai.'),
  (@b23, 59, 7, 'Jų kojos bėga į pikta, jie skuba nekaltą kraują pralieti; jų mintys – neteisybės mintys; jų takuose niokojimas ir pražūtis.'),
  (@b23, 59, 8, 'Jie nepažįsta ramybės kelio; ir nėra teismo jų ėjimuose; jie pasidarė kreivus takus; kas jais eina, nepažins ramybės.'),
  (@b23, 59, 9, 'Todėl teismas toli nuo mūsų, ir teisingumas mūsų nepasiveja; mes laukiame šviesos, bet štai tamsa, šviesumo – bet vaikščiojame tamsoje.'),
  (@b23, 59, 10, 'Mes apgraibomis ieškome sienos kaip akli ir grabaliojame kaip neturėdami akių; mes vidudienį suklumpame kaip naktį; mes negyvenamose vietose kaip numirėliai.'),
  (@b23, 59, 11, 'Mes visi riaumojame kaip lokiai ir graudžiai raudame kaip karveliai; mes laukiame teismo, bet jo nėra, išgelbėjimo, bet jis toli nuo mūsų.'),
  (@b23, 59, 12, 'Nes mūsų nusižengimai daugėja tavo akivaizdoje ir mūsų nuodėmės liudija prieš mus; nes mūsų nusižengimai yra su mumis; ir mūsų neteisybės – mes jas pažįstame;'),
  (@b23, 59, 13, 'mes nusižengiame ir meluojame prieš VIEŠPATĮ, ir atsitraukiame nuo mūsų Dievo, kalbame engimą ir maištą, širdyje pradedame ir iš jos ištariame melagingus žodžius.'),
  (@b23, 59, 14, 'Teismas nusuktas atgal ir teisingumas stovi toli; nes tiesa parkritusi gatvėje ir bešališkumas negali įeiti.'),
  (@b23, 59, 15, 'Taip, tiesos nebeliko; o kas šalinasi nuo pikto, tampa grobiu; ir VIEŠPATS tai matė ir jam nepatiko, kad nebuvo teismo.'),
  (@b23, 59, 16, 'Jis matė, kad nebuvo žmogaus, ir stebėjosi, kad nebuvo užtarėjo; todėl jam atnešė išgelbėjimą jo ranka, ir jo teisumas jį palaikė.'),
  (@b23, 59, 17, 'Nes jis užsidėjo teisumą kaip krūtinšarvį ir išgelbėjimo šalmą ant savo galvos; jis užsivilko keršto drabužius kaip aprangą ir apsisiautė uolumu kaip apsiaustu.'),
  (@b23, 59, 18, 'Pagal jų darbus jis atitinkamai atmokės įtūžiu savo priešininkams, atpildu savo priešams; saloms jis atmokės atpildu.'),
  (@b23, 59, 19, 'Taip jie bijos VIEŠPATIES vardo vakaruose ir jo šlovės saulėtekyje. Kai priešas ateis kaip srovė, VIEŠPATIES Dvasia iškels prieš jį vėliavą.'),
  (@b23, 59, 20, '„Ir Atpirkėjas ateis į Sioną ir pas tuos, kurie nusigręžia nuo nusižengimo Jokūbe“, – sako VIEŠPATS.'),
  (@b23, 59, 21, '„O dėl manęs, tai yra mano sandora su jais, – sako VIEŠPATS. – Mano Dvasia, kuri yra ant tavęs, ir mano žodžiai, kuriuos įdėjau į tavo burną, nepasitrauks nuo tavo burnos nei nuo tavo sėklos burnos, nei nuo tavo sėklos sėklos burnos nuo dabar ir per amžius“, – sako VIEŠPATS.'),
  (@b23, 60, 1, '„Kelkis, šviesk; nes atėjo tavo šviesa ir VIEŠPATIES šlovė virš tavęs patekėjo.'),
  (@b23, 60, 2, 'Nes štai tamsa apdengs žemę ir tiršta tamsa tautas, bet VIEŠPATS patekės virš tavęs ir jo šlovė bus matoma ant tavęs.'),
  (@b23, 60, 3, 'Ir pagonys ateis į tavo šviesą, ir karaliai – į tavo patekėjimo spindesį.'),
  (@b23, 60, 4, 'Pakelk savas akis ir žiūrėk aplinkui; jie visi renkasi, jie ateina pas tave; tavo sūnūs ateis iš toli, ir tavo dukterys bus globojamos prie tavo šono.'),
  (@b23, 60, 5, 'Tada tu matysi ir plūsi kartu, tavo širdis bijos ir išsiplės; nes jūros gausa atsivers į tave, pagonių stiprybė ateis pas tave.'),
  (@b23, 60, 6, 'Daugybė kupranugarių apdengs tave, Midjano ir Efos dromedarai; visi tie iš Šebos ateis; jie atgabens aukso ir smilkalų; ir jie skelbs VIEŠPATIES gyrių.'),
  (@b23, 60, 7, 'Visos Kedaro kaimenės bus surinktos pas tave, Nebajoto avinai tau tarnaus; jie priimtini užlips ant mano aukuro, ir aš pašlovinsiu savo šlovės namus.'),
  (@b23, 60, 8, 'Kas yra tie, kurie skrenda kaip debesys ir kaip karveliai prie savo langelių?'),
  (@b23, 60, 9, 'Tikrai salos lauks manęs ir Taršišo laivai pirmi, kad pargabentų tavo sūnus iš toli, jų sidabrą ir jų auksą su jais VIEŠPATIES, tavo Dievo, vardui ir Izraelio Šventajam, nes jis tave pašlovino.'),
  (@b23, 60, 10, 'Ir svetimšalių sūnūs statys tavo sienas, ir jų karaliai tau tarnaus; nes savo rūstybėje aš tave sumušiau, bet savo palankumu tavęs pasigailėjau.'),
  (@b23, 60, 11, 'Todėl tavo vartai bus nuolatos atdari; nei dieną, nei naktį jie nebus užrakinti; kad pas tave atgabentų pagonių stiprybę ir kad būtų atvesti jų karaliai.'),
  (@b23, 60, 12, 'Nes tauta ir karalystė, kuri tau netarnaus, pražus; taip, tos tautos bus visiškai nuniokotos.'),
  (@b23, 60, 13, 'Libano šlovė ateis pas tave, eglė, pušis ir buksmedis drauge, kad išgražintų mano šventovės vietą; ir savo kojų vietą padarysiu šlovingą.'),
  (@b23, 60, 14, 'Ateis pas tave nusilenkdami sūnūs tų, kurie tave vargino; ir visi, kurie tave niekino, nusilenks prie tavo kojų padų; ir jie tave vadins VIEŠPATIES miestu, Izraelio Šventojo Sionu.'),
  (@b23, 60, 15, 'Nors tu buvai paliktas ir nekenčiamas, kad niekas nėjo per tave, aš padarysiu tave amžina puikybe, džiaugsmu kartų kartoms.'),
  (@b23, 60, 16, 'Taipogi tu žįsi pagonių pieną ir žįsi karalių krūtis; ir tu žinosi, kad aš, VIEŠPATS, esu tavo Gelbėtojas ir tavo Atpirkėjas, Jokūbo Galingasis.'),
  (@b23, 60, 17, 'Vietoj žalvario aš atgabensiu aukso ir vietoj geležies atgabensiu sidabro; vietoj medžių – žalvario ir vietoj akmenų – geležies; taipogi tavo pareigūnus padarysiu ramybe ir iš tavęs reikalaujančius – teisumu.'),
  (@b23, 60, 18, 'Tavo šalyje nebesigirdės smurto, nusiaubimo nei sunaikinimo tavo ribose; bet tu vadinsi savo sienas Išgelbėjimu ir savo vartus Gyriumi.'),
  (@b23, 60, 19, 'Saulė nebebus tau šviesa dieną, nei mėnulis nebešvies tau dėl šviesumo; bet VIEŠPATS tau bus amžina šviesa, ir tavo Dievas – tavo šlovė.'),
  (@b23, 60, 20, 'Tavo saulė nebenusileis, nei tavo mėnulis nebepasišalins; nes VIEŠPATS bus tavo amžina šviesa, ir tavo gedulo dienos pasibaigs.'),
  (@b23, 60, 21, 'Taip pat tavo tauta – visa bus teisi; jie amžiams paveldės šalį – mano pasodinta atžala, mano rankų darbas, kad aš būčiau pašlovintas.'),
  (@b23, 60, 22, 'Mažiausias taps tūkstančiu ir menkas – galinga tauta; aš, VIEŠPATS, tai paskubinsiu jo laiku“.'),
  (@b23, 61, 1, 'Viešpaties DIEVO Dvasia yra ant manęs; nes VIEŠPATS mane patepė skelbti gerą žinią romiesiems; jis mane siuntė apraišioti tų, kurių širdys sudužusios, skelbti belaisviams laisvę ir įkalintiems – kad kalėjimas atidarytas;'),
  (@b23, 61, 2, 'skelbti priimtinus VIEŠPATIES metus ir mūsų Dievo keršto dieną; paguosti visus gedinčius;'),
  (@b23, 61, 3, 'paskirti gedintiems Sione, duoti jiems grožį vietoj pelenų, džiaugsmo aliejų vietoj gedulo, gyriaus drabužį vietoj apsunkusios dvasios; kad juos vadintų teisumo medžiais, VIEŠPATIES sodiniais, kad jis būtų pašlovintas.'),
  (@b23, 61, 4, 'Ir jie atstatys senas dykvietes, atstatys anksčiau apleistas vietoves, ir jie atnaujins nuniokotus miestus, apleistus per kartų kartas.'),
  (@b23, 61, 5, 'Ateiviai stovės ir ganys jūsų kaimenes, ir svetimšalių sūnūs bus jūsų artojai ir jūsų vynuogininkai.'),
  (@b23, 61, 6, 'Bet jūs būsite vadinami VIEŠPATIES Kunigais; jus vadins mūsų Dievo Tarnais; jūs valgysite pagonių turtus ir didžiuositės jų šlove.'),
  (@b23, 61, 7, 'Už savo gėdą jūs turėsite dvigubai; ir už negarbę jie džiaugsis savo dalimi; todėl savo šalyje jie pasisavins dvigubai; jiems bus amžinas džiaugsmas.'),
  (@b23, 61, 8, 'Nes aš, VIEŠPATS, mėgstu teismą, nekenčiu plėšikavimo vietoj deginamosios atnašos; ir aš nukreipsiu jų darbą tiesoje, ir sudarysiu su jais amžiną sandorą.'),
  (@b23, 61, 9, 'Ir jų sėkla bus žinoma tarp pagonių ir jų palikuonys – tarp tautų; visi, kurie juos matys, juos pripažins, kad jie yra sėkla, kurią VIEŠPATS palaimino.'),
  (@b23, 61, 10, 'Aš didžiai džiaugsiuosi VIEŠPAČIU, mano siela džiūgaus mano Dievu; nes jis mane apvilko išgelbėjimo drabužiais, jis apsiautė mane teisumo apsiaustu, kaip jaunikis pasipuošia papuošalais ir kaip nuotaka pasipuošia savo brangenybėmis.'),
  (@b23, 61, 11, 'Nes kaip žemė išželdina savo ūglius ir kaip sodas išželdina tai, kas pasėta; taip Viešpats DIEVAS išželdins teisumą ir gyrių visų tautų akivaizdoje.'),
  (@b23, 62, 1, 'Dėl Siono aš netylėsiu ir dėl Jeruzalės nenurimsiu, kol nepasirodys jos teisumas kaip šviesa ir jos išgelbėjimas kaip degantis žibintas.'),
  (@b23, 62, 2, 'Ir pagonys pamatys tavo teisumą, ir visi karaliai tavo šlovę; ir tave vadins nauju vardu, kuriuo tave pramins VIEŠPATIES burna.'),
  (@b23, 62, 3, 'Taipogi tu būsi šlovės vainikas VIEŠPATIES rankoje ir karališka diadema tavo Dievo rankoje.'),
  (@b23, 62, 4, 'Tavęs nebevadins Palikta; ir tavo šalies nebevadins Tuščia; bet tave vadins Hefci-Ba ir tavo šalį Beūla; nes VIEŠPATS gėrisi tavimi, ir tavo šalis ištekės.'),
  (@b23, 62, 5, 'Nes kaip jaunuolis veda mergelę, taip tavo sūnūs ves tave; ir kaip jaunikis džiaugiasi jaunąja, taip tavo Dievas džiaugsis tavimi.'),
  (@b23, 62, 6, 'O Jeruzale, ant tavo sienų pastačiau sargybinius, kurie niekada netylės, nei dieną, nei naktį; jūs, kurie minite VIEŠPATĮ, netylėkite'),
  (@b23, 62, 7, 'ir neduokite jam ramybės, kol jis neįtvirtins ir kol nepadarys Jeruzalės gyriumi žemėje.'),
  (@b23, 62, 8, 'VIEŠPATS prisiekė savo dešine ir savo stiprybės ranka: „Aš tikrai nebeduosiu tavo javų tavo priešams maistui; ir svetimšalių sūnūs nebegers tavo vyno, dėl kurio triūsei.'),
  (@b23, 62, 9, 'Bet tie, kurie juos surinko, juos valgys ir girs VIEŠPATĮ; ir tie, kurie jį sugabeno, jį gers mano šventumo kiemuose“.'),
  (@b23, 62, 10, 'Praeikite, praeikite pro vartus; paruoškite tautos kelią; supilkite, supilkite vieškelį, išrinkite akmenis; ir iškelkite vėliavą tautai.'),
  (@b23, 62, 11, 'Štai VIEŠPATS paskelbė iki pasaulio pakraščių: „Sakykite Siono dukrai: ‘Štai tavo išgelbėjimas ateina; štai jo užmokestis yra su juo, ir jo darbas jo priešakyje’“.'),
  (@b23, 62, 12, 'Ir juos vadins Šventa tauta, VIEŠPATIES atpirktaisiais; o tu būsi vadinamas Ieškomas, nepaliktas miestas.'),
  (@b23, 63, 1, 'Kas yra tas, kuris ateina iš Edomo, nudažytais drabužiais iš Bocros? Ar tas, kuris yra šlovingas savo drabužiais, keliaujantis savo jėgos didybėje? „Aš, kuris kalbu teisumu, galingas gelbėti“.'),
  (@b23, 63, 2, 'Kodėl raudonas tavo apdaras ir tavo rūbai kaip minančiojo vyno spaudykloje?'),
  (@b23, 63, 3, '„Aš vienas myniau spaustuvą; ir nei vieno iš tautų nebuvo su manimi; nes aš jas mindysiu savo pyktyje ir jas trypsiu savo įtūžyje; ir jų kraujas aptaškys mano drabužius, ir aš susitepsiu visą savo apdarą.'),
  (@b23, 63, 4, 'Nes keršto diena yra mano širdyje, ir mano atpirktųjų metai atėjo.'),
  (@b23, 63, 5, 'Ir aš pažiūrėjau, ir nebuvo kas padėtų; ir aš stebėjausi, kad nebuvo, kas paremtų; todėl mano paties ranka man atnešė išgelbėjimą; ir mano įtūžis mane parėmė.'),
  (@b23, 63, 6, 'Aš savo pyktyje mindysiu tautas ir jas nugirdysiu savo įtūžyje, ir parblokšiu žemėn jų stiprybę“.'),
  (@b23, 63, 7, 'Aš minėsiu VIEŠPATIES mylinčius gerumus ir VIEŠPATIES gyrių pagal visa tai, ką VIEŠPATS yra mums suteikęs, ir didelį gerumą Izraelio namams, kurį jis yra jiems suteikęs pagal savo gailestingumus ir pagal savo mylinčių gerumų gausumą.'),
  (@b23, 63, 8, 'Nes jis tarė: „Tikrai jie yra mano tauta, vaikai, kurie nemeluos“; taigi jis buvo jų Gelbėtojas.'),
  (@b23, 63, 9, 'Jis buvo varginamas visuose jų varguose, ir jo akivaizdos angelas juos gelbėjo; savo meile ir savo gailesčiu jis juos atpirko; ir jis juos pakėlė ir nešė per visas senovės dienas.'),
  (@b23, 63, 10, 'Bet jie maištavo ir vargino jo šventą Dvasią; todėl jis pavirto jų priešu ir kovojo prieš juos.'),
  (@b23, 63, 11, 'Tada jis atsiminė senovės dienas, Mozę ir jo tautą, sakydamas: „Kur yra tas, kuris juos išvedė aukštyn iš jūros su jo kaimenės ganytoju? Kur yra tas, kuris į jį įdėjo savo šventą Dvasią?'),
  (@b23, 63, 12, 'Kuris vedė juos per Mozės dešinę ranką, savo šlovinga ranka, padalindamas vandenį jų priešakyje, kad padarytų sau amžiną vardą?'),
  (@b23, 63, 13, 'Kuris vedė juos per gelmes kaip žirgą dykumoje, kad jie nesukluptų?'),
  (@b23, 63, 14, 'Kaip gyvulys nusileidžia į slėnį ir VIEŠPATIES Dvasia duoda jam pailsėti; taip tu vedei savo tautą, kad padarytum sau šlovingą vardą.'),
  (@b23, 63, 15, 'Pažvelk iš dangaus ir pažiūrėk iš savo šventumo ir savo šlovės buveinės; kur yra tavo uolumas ir tavo stiprybė, tavo vidurių ir tavo gailestingumų gilumas man? Ar jie sulaikyti?'),
  (@b23, 63, 16, 'Neabejotinai tu esi mūsų tėvas, nors Abraomas nežino apie mus ir Izraelis nepripažįsta mūsų, tu, VIEŠPATIE, esi mūsų tėvas, mūsų atpirkėjas; tavo vardas yra nuo amžinybės.'),
  (@b23, 63, 17, 'O VIEŠPATIE, kodėl tu davei mums nuklysti nuo tavo kelių ir sukietinai mūsų širdį, kad tavęs nebijotume? Sugrįžk dėl savo tarnų, savo paveldo genčių.'),
  (@b23, 63, 18, 'Tavo šventumo tauta tik trumpam ją buvo pasisavinusi; mūsų priešai mindė tavo šventovę.'),
  (@b23, 63, 19, 'Mes esame tavo; tu niekada jų nevaldei; jie nebuvo vadinami tavo vardu“.'),
  (@b23, 64, 1, 'O kad tu praplėštum dangus, kad nužengtum, kad nuo tavo akivaizdos sutirptų kalnai,'),
  (@b23, 64, 2, 'kaip kad dega lydanti ugnis, vandenį užvirina ugnis, kad padarytų tavo vardą žinomą tavo priešininkams, kad nuo tavo akivaizdos drebėtų tautos!'),
  (@b23, 64, 3, 'Kai tu darei baisius dalykus, kurių nelaukėme, tu nužengei, ir kalnai sutirpo nuo tavo akivaizdos.'),
  (@b23, 64, 4, 'Nes nuo pasaulio pradžios niekas negirdėjo nei ausimi nepatyrė, nei akis neregėjo be tavęs, o Dieve, to, ką jis paruošė tam, kuris jo laukia.'),
  (@b23, 64, 5, 'Tu pasitinki tą, kuris džiaugiasi ir vykdo teisumą, tuos, kurie atsimena tave tavo keliuose; štai tu užsirūstinęs; nes mes nusidėjome: tame yra pastovumas, ir mes būsime išgelbėti.'),
  (@b23, 64, 6, 'Bet mes visi esame kaip nešvarumas, ir visas mūsų teisumas yra kaip purvini skudurai; mes visi vystame kaip lapai; ir mūsų neteisybės mus nunešė kaip vėjas.'),
  (@b23, 64, 7, 'Ir nėra kas šauktųsi tavo vardo, kas save paskatintų įsikibti į tave; nes tu paslėpei savo veidą nuo mūsų ir mus naikinai dėl mūsų neteisybių.'),
  (@b23, 64, 8, 'Bet dabar, o VIEŠPATIE, tu esi mūsų tėvas; mes esame molis, o tu mūsų puodžius; mes visi – tavo rankos darbas.'),
  (@b23, 64, 9, 'Nerūstauk labai smarkiai, o VIEŠPATIE, ir neatsimink neteisybės amžinai; štai pažvelk, mes meldžiame tave, mes visi esame tavo tauta.'),
  (@b23, 64, 10, 'Tavo šventieji miestai yra dykuma, Sionas yra dykuma, Jeruzalė negyvenama.'),
  (@b23, 64, 11, 'Mūsų šventieji ir mūsų šlovingieji namai, kur mūsų tėvai tave gyrė, yra sudeginti ugnimi; ir visi mūsų geistini dalykai nuniokoti.'),
  (@b23, 64, 12, 'Ar dėl tų dalykų tu susilaikysi, o VIEŠPATIE? Ar tu tylėsi ir labai stipriai mus varginsi?'),
  (@b23, 65, 1, '„Aš ieškomas tų, kurie apie mane neklausinėjo; aš surastas tų, kurie manęs neieškojo; aš sakiau: ‘Štai aš, štai aš’, tautai, kuri nebuvo vadinama mano vardu.'),
  (@b23, 65, 2, 'Visą dieną buvau ištiesęs savo rankas į maištaujančią tautą, kuri vaikšto negeru keliu, paskui savo mintis;'),
  (@b23, 65, 3, 'tautą, kuri kursto mano pyktį nuolatos man į akis; kuri aukoja soduose ir degina smilkalus ant aukurų iš plytų;'),
  (@b23, 65, 4, 'kuri pasilieka tarp kapų ir nakvoja antkapiuose; kuri valgo kiaulės mėsą, ir jų induose yra bjaurysčių sultinys;'),
  (@b23, 65, 5, 'kurie sako: ‘Stovėk, kur esi, nesiartink prie manęs, nes aš esu šventesnis už tave’. Šitie yra dūmai mano nosyje, ugnis, deganti visą dieną.'),
  (@b23, 65, 6, 'Štai yra užrašyta mano akivaizdoje: Aš netylėsiu, bet atmokėsiu, atmokėsiu jiems į užantį'),
  (@b23, 65, 7, 'jūsų neteisybes ir jūsų tėvų neteisybes, – sako VIEŠPATS, – kurie smilkėte ant kalnų ir man piktžodžiavote ant kalvų; todėl aš atseikėsiu jų ankstesnįjį darbą jiems į užantį“.'),
  (@b23, 65, 8, 'Taip sako VIEŠPATS: „Kaip jaunas vynas randamas kekėje, ir yra sakoma: ‘Nesunaikink jos, nes joje yra palaiminimas’; taip aš darysiu dėl savo tarnų, kad jų visų nesunaikinčiau.'),
  (@b23, 65, 9, 'Ir aš pagimdysiu iš Jokūbo sėklą ir iš Judos paveldėtoją, paveldėtoją mano kalnų; ir juos paveldės mano išrinktieji, ir mano tarnai ten gyvens.'),
  (@b23, 65, 10, 'Šaronas bus kaimenių aptvaras ir Achoro slėnis – vieta sugulti bandoms, mano tautai, kuri manęs ieškojo.'),
  (@b23, 65, 11, 'Bet jūs tie, kurie paliekate VIEŠPATĮ, kurie pamirštate mano šventąjį kalną, kurie paruošiate stalą šitam pulkui ir parūpinate geriamąją atnašą šitam skaičiui.'),
  (@b23, 65, 12, 'Todėl aš jus priskaičiuosiu kalavijui, ir jūs visi nusilenksite paskerdimui; nes kai aš šaukiau, jūs neatsiliepėte; kai aš kalbėjau, jūs nesiklausėte; bet darėte pikta mano akyse ir pasirinkote tai, kas man nepatiko“.'),
  (@b23, 65, 13, 'Todėl taip sako Viešpats DIEVAS: „Štai mano tarnai valgys, bet jūs alksite; štai mano tarnai gers, bet jūs trokšite; štai mano tarnai džiūgaus, bet jūs būsite sugėdinti;'),
  (@b23, 65, 14, 'štai mano tarnai giedos iš širdies džiaugsmo, bet jūs šauksite iš širdies skausmo ir kauksite iš dvasios suspaudimo.'),
  (@b23, 65, 15, 'Ir jūs paliksite mano išrinktiesiems savo vardą prakeikimui; nes Viešpats DIEVAS nužudys tave, o savo tarnus pavadins kitu vardu;'),
  (@b23, 65, 16, 'kad laiminantis save žemėje, laimins save tiesos Dievu; ir kas prisieks žemėje, prisieks tiesos Dievu; nes ankstesnieji vargai pamiršti, nes jie paslėpti nuo mano akių.'),
  (@b23, 65, 17, 'Nes štai aš kuriu naujus dangus ir naują žemę; ir ankstesnieji nebebus atsimintini nei nebeateis mintin.'),
  (@b23, 65, 18, 'Bet jūs linksminkitės ir džiūgaukite per amžius tuo, ką aš sutveriu; nes štai aš sutveriu Jeruzalę – džiūgavimu, ir jos tautą – džiaugsmu.'),
  (@b23, 65, 19, 'Ir aš džiūgausiu Jeruzale ir džiaugsiuosi savo tauta; ir nebesigirdės joje nei verksmo balso, nei raudojimo balso.'),
  (@b23, 65, 20, 'Nuo tada nebebus keleto dienų kūdikio nei senio, nesulaukusio savo dienų pilnatvės; nes vaikas mirs šimto metų amžiaus; bet šimto metų amžiaus nusidėjėlis bus prakeiktas.'),
  (@b23, 65, 21, 'Ir jie statys namus ir juose gyvens; ir sodins vynuogynus, ir valgys jų vaisių.'),
  (@b23, 65, 22, 'Jie nestatys, kad kiti gyventų; jie nesodins, kad kiti valgytų; nes mano tautos dienos bus kaip medžio dienos, ir mano išrinktieji ilgai gėrėsis savo rankų darbu.'),
  (@b23, 65, 23, 'Jie netriūs veltui ir negimdys vargui; nes jie yra VIEŠPATIES palaimintųjų sėkla ir jų palikuonys su jais.'),
  (@b23, 65, 24, 'Ir įvyks, kad prieš jiems šaukiant aš atsakysiu; ir jiems dar tebekalbant aš išgirsiu.'),
  (@b23, 65, 25, 'Vilkas ir avinėlis ganysis drauge, ir liūtas ės šiaudus kaip jautis; o dulkės bus gyvatės maistas. Jie nekenks ir nenaikins visame mano šventajame kalne“, – sako VIEŠPATS.'),
  (@b23, 66, 1, 'Taip sako VIEŠPATS: „Dangus yra mano sostas, o žemė yra mano pakojis; kur yra namai, kuriuos man statysite? Ir kur yra mano poilsio vieta?'),
  (@b23, 66, 2, 'Nes visa tai padarė mano ranka, ir visa tai buvo, – sako VIEŠPATS; – bet aš pažvelgsiu į tą, kuris yra vargšas, kuris yra palūžusios dvasios ir dreba nuo mano žodžio.'),
  (@b23, 66, 3, 'Pjaunantis jautį yra kaip žudantis žmogų; aukojantis avinėlį – kaip nukertantis šuniui sprandą; atnašaujantis auką – kaip atnašaujantis kiaulės kraują; deginantis smilkalus – kaip laiminantis stabą. Taip, jie pasirinko savo pačių kelius, ir jų siela gėrisi jų bjaurystėmis.'),
  (@b23, 66, 4, 'Taip pat ir aš pasirinksiu jų klydimus ir ant jų užleisiu jų baimes; nes kai aš šaukiau, niekas neatsiliepė; kai aš kalbėjau, jie nesiklausė; bet jie darė pikta mano akyse ir pasirinko tai, kas man nepatiko“.'),
  (@b23, 66, 5, 'Klausykite VIEŠPATIES žodžio, jūs, kurie drebate nuo jo žodžio: „Jūsų broliai, kurie jūsų nekenčia, kurie jus išmeta dėl mano vardo, sakė: ‘Tebūna pašlovintas VIEŠPATS’; bet jis pasirodys jūsų džiaugsmui, o jie bus sugėdinti“.'),
  (@b23, 66, 6, 'Triukšmingas balsas iš miesto, balsas iš šventyklos, balsas VIEŠPATIES, atmokančio atlygį savo priešams.'),
  (@b23, 66, 7, 'Jai dar nepajutus gimdymo skausmų, ji pagimdė; jos skausmams dar neatėjus, ji pagimdė vyriškos lyties vaiką.'),
  (@b23, 66, 8, 'Kas girdėjo tokį dalyką? Kas matė tokių dalykų? Ar žemė pagimdo per vieną dieną? Ar staiga gimsta tauta? Nes kai tik skausmai suėmė Sioną, jis pagimdė savo vaikus.'),
  (@b23, 66, 9, '„Ar aš, atvedęs iki gimdymo, neduosiu pagimdyti, – sako VIEŠPATS; – ar aš, davęs gimdyti, uždarysiu įsčias?“ – sako tavo Dievas.'),
  (@b23, 66, 10, 'Džiaukitės su Jeruzale ir linksminkitės su ja jūs visi, kurie ją mylite; džiaugte džiaukitės su ja visi, kurie gedite dėl jos;'),
  (@b23, 66, 11, 'kad žįstumėte ir pasisotintumėte jos paguodų krūtimis; kad melžtumėte ir gėrėtumėtės jos šlovės gausa.'),
  (@b23, 66, 12, 'Nes taip sako VIEŠPATS: „Štai aš jai ištiesiu ramybę lyg upę ir pagonių šlovę kaip tekančią srovę; tada jūs žįsite, jūs būsite nešiojami prie jos šonų ir supami ant jos kelių.'),
  (@b23, 66, 13, 'Kaip tą, kurį guodžia jo motina, taip aš jus paguosiu; ir jūs būsite paguosti Jeruzalėje.'),
  (@b23, 66, 14, 'Ir kai jūs tai matysite, džiaugsis jūsų širdis, ir jūsų kaulai vešės kaip žolės; ir VIEŠPATIES ranka bus žinoma jo tarnams, o jo pasipiktinimas – jo priešams.'),
  (@b23, 66, 15, 'Nes štai VIEŠPATS ateis su ugnimi ir kaip viesulas su savo vežimais, kad su įtūžiu atmokėtų savo pykčiu ir savo barimu ugnies liepsnomis.'),
  (@b23, 66, 16, 'Nes ugnimi ir savo kalaviju VIEŠPATS bylinėsis su visais kūnais; ir daug bus VIEŠPATIES užmuštųjų.'),
  (@b23, 66, 17, 'Tie, kurie pasišvenčia ir apsivalo soduose už vieno medžio, viduryje, valgydami kiaulieną, bjaurystes ir peles, bus sunaikinti kartu“, – sako VIEŠPATS.'),
  (@b23, 66, 18, '„Nes aš žinau jų darbus ir jų mintis; atsitiks, kad aš surinksiu visas tautas ir kalbas; ir jie ateis ir matys mano šlovę.'),
  (@b23, 66, 19, 'Ir aš pastatysiu jų tarpe ženklą, ir aš pasiųsiu jų pabėgėlius į tautas: į Taršišą, Pulą ir Ludą, įtempiančius lanką, į Tubalą ir Javaną, į tolimas salas, kurios nėra girdėjusios apie mane ir nėra mačiusios mano šlovės; ir jie paskelbs mano šlovę tarp pagonių.'),
  (@b23, 66, 20, 'Ir jie atgabens visus jūsų brolius iš visų tautų kaip atnašą VIEŠPAČIUI ant žirgų, vežimuose, neštuvuose, ant mulų ir ant greitųjų gyvulių į mano šventąjį kalną Jeruzalę, – sako VIEŠPATS, – kaip Izraelio vaikai atneša atnašą švariame inde į VIEŠPATIES namus.'),
  (@b23, 66, 21, 'Ir aš taipogi iš jų paimsiu į kunigus ir į levitus, – sako VIEŠPATS.'),
  (@b23, 66, 22, 'Nes kaip nauji dangūs ir nauja žemė, kuriuos aš padarysiu, pasiliks mano akivaizdoje, – sako VIEŠPATS, – taip pasiliks jūsų sėkla ir jūsų vardas.'),
  (@b23, 66, 23, 'Ir įvyks, kad nuo vieno jauno mėnulio iki kito ir nuo vieno sabato iki kito visi kūnai ateis garbinti mano akivaizdoje, – sako VIEŠPATS.'),
  (@b23, 66, 24, 'Ir jie išeis ir žiūrės į lavonus tų žmonių, kurie nusižengė prieš mane; nes jų kirminas nemirs ir jų ugnis neužges; ir jie bus pasibjaurėjimu visiems kūnams“.'),
  (@b24, 1, 1, 'Žodžiai Jeremijo, Hilikijo sūnaus, iš kunigų, buvusių Anatote, Benjamino šalyje;'),
  (@b24, 1, 2, 'jam VIEŠPATIES žodis atėjo Jozijo, sūnaus Amono, Judos karaliaus, dienomis, tryliktaisiais jo karaliavimo metais.'),
  (@b24, 1, 3, 'Jis taip pat atėjo Jehojakimo, sūnaus Jozijo, Judos karaliaus, dienomis iki Zedekijo, sūnaus Jozijo, Judos karaliaus, vienuoliktųjų metų pabaigos, iki Jeruzalės išvedimo į nelaisvę penktąjį mėnesį.'),
  (@b24, 1, 4, 'Tada man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 1, 5, '„Prieš formuodamas tave pilve, aš pažinau tave; ir prieš tau išeinant iš įsčių, aš pašvenčiau tave ir paskyriau tave pranašu tautoms“.'),
  (@b24, 1, 6, 'Tada aš tariau: „Ak, Viešpatie DIEVE! Štai aš nemoku kalbėti; nes aš esu vaikas“.'),
  (@b24, 1, 7, 'Bet VIEŠPATS man tarė: „Nesakyk: ‘Aš esu vaikas’; nes tu eisi pas visus, kur tave siųsiu, ir kalbėsi, ką tau įsakysiu.'),
  (@b24, 1, 8, 'Nebijok jų veidų; nes aš esu su tavimi, kad tave išvaduočiau“, – sako VIEŠPATS.'),
  (@b24, 1, 9, 'Tada VIEŠPATS ištiesė savo ranką ir palietė mano burną. Ir VIEŠPATS man tarė: „Štai aš įdėjau savo žodžius į tavo burną.'),
  (@b24, 1, 10, 'Žiūrėk, šią dieną paskyriau tave virš tautų ir virš karalysčių, išrauti su šaknimis, griauti, naikinti ir nuversti, statyti ir sodinti“.'),
  (@b24, 1, 11, 'Man dar atėjo VIEŠPATIES žodis, sakydamas: „Ką matai, Jeremijau?“ Ir aš tariau: „Matau migdolo lazdą“.'),
  (@b24, 1, 12, 'Tada VIEŠPATS man tarė: „Gerai matei; nes aš paskubinsiu savo žodį, kad jį įvykdyčiau“.'),
  (@b24, 1, 13, 'Ir antrą kartą man atėjo VIEŠPATIES žodis, sakydamas: „Ką matai?“ Ir aš tariau: „Aš matau verdantį puodą; ir jo priekinė pusė nukreipta į šiaurę“.'),
  (@b24, 1, 14, 'Tada VIEŠPATS man tarė: „Iš šiaurės išsiverš nelaimė ant visų šalies gyventojų.'),
  (@b24, 1, 15, 'Nes štai aš pašauksiu visas šiaurės karalysčių šeimas, – sako VIEŠPATS, – ir jos ateis ir kiekviena pastatys savo sostą Jeruzalės vartų įėjime ir prieš visas jos sienas aplinkui, ir prieš visus Judos miestus.'),
  (@b24, 1, 16, 'Ir aš ištarsiu savo teismus prieš juos dėl visos nedorybės jų, kurie mane paliko, degino smilkalus kitiems dievams ir garbino savo rankų darbus.'),
  (@b24, 1, 17, 'Todėl susijuosk strėnas, kelkis ir jiems kalbėk viską, ką tau įsakysiu; nebūk sunerimęs nuo jų veidų, kad tavęs neišgąsdinčiau jų akivaizdoje.'),
  (@b24, 1, 18, 'Nes štai šią dieną padariau tave sutvirtintu miestu, geležies stulpu ir žalvarinėmis sienomis prieš visą šalį, prieš Judos karalius, prieš jos kunigaikščius, prieš jos kunigus ir prieš šalies tautą.'),
  (@b24, 1, 19, 'Ir jie kovos prieš tave; bet jie tavęs nenugalės; nes aš esu su tavimi, kad tave išvaduočiau“, – sako VIEŠPATS.'),
  (@b24, 2, 1, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 2, 2, '„Eik ir šauk Jeruzalei į ausis, sakydamas: Taip sako VIEŠPATS: ‘Aš atsimenu tave, tavo jaunystės gerumą, tavo sužadėtuvių meilę, kai tu sekei paskui mane dykumoje, neapsėtoje šalyje.'),
  (@b24, 2, 3, 'Izraelis buvo šventumas VIEŠPAČIUI, jo prieaugio pirmavaisiai; visi, kurie jį valgo, nusikalsta; juos ištiks nelaimė’, – sako VIEŠPATS“.'),
  (@b24, 2, 4, 'Klausykite VIEŠPATIES žodžio, o Jokūbo namai, ir visos Izraelio namų šeimos;'),
  (@b24, 2, 5, 'taip sako VIEŠPATS: „Kokią neteisybę rado manyje jūsų tėvai, kad jie atsitolino nuo manęs ir vaikščiojo paskui tuštybę, ir tapo tušti?'),
  (@b24, 2, 6, 'Ir jie nesakė: ‘Kur yra VIEŠPATS, kuris mus išvedė aukštyn iš Egipto šalies, kuris mus vedė per tyrlaukius, per dykumų ir daubų šalį, per sausros ir mirties šešėlio šalį, šalį, per kurią niekas neina ir kurioje joks žmogus negyvena?’'),
  (@b24, 2, 7, 'Ir aš jus atvedžiau į turtingą šalį, kad valgytumėte jos vaisių ir jos gerumo; bet įėję jūs suteršėte mano šalį ir mano paveldą padarėte pasibjaurėjimu.'),
  (@b24, 2, 8, 'Kunigai nesakė: ‘Kur yra VIEŠPATS?’, įstatymo prižiūrėtojai nepažino manęs; ganytojai irgi maištavo prieš mane, pranašai pranašavo per Baalą ir vaikščiojo paskui tai, kas nenaudinga.'),
  (@b24, 2, 9, 'Todėl aš dar bylinėsiuosi su jumis, – sako VIEŠPATS, – ir bylinėsiuosi su jūsų vaikų vaikais.'),
  (@b24, 2, 10, 'Nes pereikite į Kitimų salas ir pasižiūrėkite; ir pasiųskite į Kedarą, atidžiai įsižiūrėkite ir pamatykite, ar ten yra kas nors tokio.'),
  (@b24, 2, 11, 'Ar kuri tauta pakeitė savo dievus, kurie nėra dievai? Bet mano tauta iškeitė savo šlovę į tai, kas neduoda naudos.'),
  (@b24, 2, 12, 'Būkite apstulbę dėl to, o dangūs, ir siaubingai išsigąskite, būkite labai apleisti, – sako VIEŠPATS.'),
  (@b24, 2, 13, 'Nes dvi piktybes padarė mano tauta: jie paliko mane, gyvųjų vandenų šaltinį, ir išsikirto sau rezervuarų, sudaužytų rezervuarų, kurie nesulaiko vandens.'),
  (@b24, 2, 14, 'Ar Izraelis tarnas? Ar jis namuose gimęs vergas? Kodėl jis apiplėštas?'),
  (@b24, 2, 15, 'Jauni liūtai ant jo riaumojo, kriokė ir jo šalį pavertė dyka; jo miestai sudeginti, be gyventojų.'),
  (@b24, 2, 16, 'Taip pat Nofo ir Tachpanheso vaikai sudaužė tavo galvos karūną.'),
  (@b24, 2, 17, 'Argi tu ne sau tai sukėlei, palikdamas VIEŠPATĮ, savo Dievą, kai jis tave vedė keliu?'),
  (@b24, 2, 18, 'O dabar, kas tau darbo Egipto kelyje, kad gertum Sihoro vandenis? Arba, kas tau darbo Asirijos kelyje, kad gertum upės vandenis?'),
  (@b24, 2, 19, 'Tave nubaus tavo paties nedorybė, ir tavo atsimetimai bars tave; todėl žinok ir matyk, kaip pikta ir kartu yra tai, kad palikai VIEŠPATĮ, savo Dievą, ir kad mano baimės nėra tavyje, – sako Viešpats kariuomenių DIEVAS.'),
  (@b24, 2, 20, 'Nes nuo senų laikų aš sulaužiau tavo jungą, sutraukiau tavo pančius; ir tu tarei: ‘Nenusižengsiu’; kai tuo tarpu ant kiekvienos aukštos kalvos ir po kiekvienu žaliuojančiu medžiu tu klaidžiojai paleistuvaudamas.'),
  (@b24, 2, 21, 'Aš dar buvau tave pasodinęs kaip taurų vynmedį, visiškai tikrą sėklą; tad kaip tu pavirtai į išsigimusį man svetimo vynmedžio sodinį?'),
  (@b24, 2, 22, 'Nors ir nusipraustum salietra ir sunaudotum daug muilo, tačiau tavo neteisybė pažymėta mano akivaizdoje, – sako Viešpats DIEVAS.'),
  (@b24, 2, 23, 'Kaip tu gali sakyti: ‘Aš nesusiteršęs, aš nesekiojau paskui Baalus’? Pažvelk į savo kelią slėnyje, pažink, ką padarei; tu greitasis dromedaras, raižantis savais keliais;'),
  (@b24, 2, 24, 'laukinė asilė, pripratusi prie dykumos, kuri užsigeidusi uosto vėją; kas gali ją nusukti nuo jos tikslo? Visi, kurie jos ieško, nenuvargs; jie ras ją jos mėnesį.'),
  (@b24, 2, 25, 'Sulaikyk savo koją, kad nebūtų basa, ir savo gerklę nuo troškulio; bet tu sakei: ‘Nėra vilties; ne; nes aš myliu svetimuosius ir eisiu paskui juos’.'),
  (@b24, 2, 26, 'Kaip gėdisi vagis, kai jį užtinka, taip gėdisi Izraelio namai; jie, jų karaliai, jų kunigaikščiai, jų kunigai ir jų pranašai,'),
  (@b24, 2, 27, 'kurie sako kamienui: ‘Tu mano tėvas’; ir akmeniui: ‘Tu mane pagimdei’; nes jie atgręžė man nugarą, o ne veidą; bet jų nelaimės metu jie sako: ‘Kelkis ir gelbėk mus’.'),
  (@b24, 2, 28, 'Bet kurgi tavo dievai, kuriuos pasidarei? Jie teatsikelia, jei gali tave išgelbėti tavo bėdos metu; nes kiek tavo miestų, tiek yra tavo dievų, o Juda.'),
  (@b24, 2, 29, 'Kodėl norite bylinėtis su manimi? Jūs visi nusižengėte prieš mane, – sako VIEŠPATS.'),
  (@b24, 2, 30, 'Veltui aš mušiau jūsų vaikus; jie nepriėmė pabaudimo; jūsų pačių kalavijas rijo jūsų pranašus kaip naikinantis liūtas.'),
  (@b24, 2, 31, 'O karta, stebėkite VIEŠPATIES žodį. Ar aš buvau dykuma Izraeliui, tamsos šalis? Kodėl mano tauta sako: ‘Mes esame viešpačiai, mes nebeateisime pas tave’?'),
  (@b24, 2, 32, 'Ar panelė pamiršta savo papuošalus arba nuotaka savo drabužius? Tačiau mano tauta pamiršo mane – dienų jau be skaičiaus.'),
  (@b24, 2, 33, 'Kodėl dailini savo kelią, kad ieškotum meilės? Taigi tu išmokei nedorėlius savo kelių.'),
  (@b24, 2, 34, 'Taip pat ant tavo skvernų randamas nekaltų vargšų sielų kraujas; aš jį radau ne slapta ieškodamas, bet ant visų tų.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 2, 35, 'Tačiau tu sakai: ‘Kadangi aš nekalta, tikrai jo pyktis nusigręš nuo manęs’. Štai aš bylinėsiuosi su tavimi, nes tu sakai: ‘Aš nenusidėjau’.'),
  (@b24, 2, 36, 'Kodėl tiek daug bastaisi, kad pakeistum savo kelią? Egiptu taipogi susigėsi, kaip buvai susigėdusi Asirija.'),
  (@b24, 2, 37, 'Taip, iš jo tu išeisi rankomis ant galvos; nes VIEŠPATS atmetė tavo pasitikėjimus, ir tau juose nesiseks“.'),
  (@b24, 3, 1, '„Jie sako: ‘Jei vyras atleidžia savo žmoną ir ji, nuėjusi nuo jo, tampa kito vyro žmona, ar jis gali sugrįžti pas ją? Argi ne stipriai susiterštų ta šalis?’ Bet tu paleistuvavai su daugeliu meilužių; tačiau sugrįžti pas mane, – sako VIEŠPATS.'),
  (@b24, 3, 2, '– Pakelk savo akis į aukštumas ir žiūrėk, kur su tavimi nebuvo sugulta. Keliuose tu sėdėjai dėl jų kaip arabas dykumoje; ir suteršei šalį savo paleistuvystėmis ir savo nedorybe.'),
  (@b24, 3, 3, 'Todėl liūtys buvo sulaikytos, ir nebuvo vėlyvojo lietaus; o tu turėjai paleistuvės kaktą, tu atsisakei gėdytis.'),
  (@b24, 3, 4, 'Argi tu nuo to laiko nesišauksi manęs: ‘Mano tėve, tu esi mano jaunystės vadovas!'),
  (@b24, 3, 5, 'Ar jis saugos savo pyktį per amžius, ar jį laikys iki galo?’ Štai tu kalbėjai ir darei pikta, kaip tik galėjai“.'),
  (@b24, 3, 6, 'VIEŠPATS man tarė karaliaus Jozijo dienomis: „Ar matei, ką darė atsimetėlė, Izraelis? Ji ėjo aukštyn į kiekvieną aukštą kalną ir po kiekvienu žaliuojančiu medžiu ir ten paleistuvavo.'),
  (@b24, 3, 7, 'Ir po to, kai ji visa tai buvo padariusi, aš tariau: ‘Sugrįžk pas mane’. Bet ji nesugrįžo. Ir tai matė neištikimoji jos sesuo Juda.'),
  (@b24, 3, 8, 'Ir aš mačiau, kai dėl viso to, kuo atsimetėlė, Izraelis, svetimavo, aš ją atleidau ir daviau jai skyrybų raštą; tačiau jos išdavikiškoji sesuo Juda nepabūgo, bet nuėjusi irgi paleistuvavo.'),
  (@b24, 3, 9, 'Ir įvyko, kad savo lengvabūdišku paleistuvavimu ji suteršė šalį ir svetimavo su akmenimis ir kamienais.'),
  (@b24, 3, 10, 'Tačiau dėl viso to jos išdavikiškoji sesuo Juda nesugrįžo pas mane visa širdimi, bet tik apsimestinai“, – sako VIEŠPATS.'),
  (@b24, 3, 11, 'Ir VIEŠPATS man tarė: „Atsimetėlė, Izraelis, buvo teisesnė už išdavikiškąją Judą.'),
  (@b24, 3, 12, 'Eik ir skelbk šituos žodžius šiaurės link ir tark: ‘Sugrįžk, atsimetėle, Izraeli, – sako VIEŠPATS; – ir aš jūsų neištiksiu savo pykčiu; nes aš esu gailestingas, – sako VIEŠPATS, – aš nelaikysiu pykčio amžinai.'),
  (@b24, 3, 13, 'Tik pripažink savo neteisybę, kad prieš VIEŠPATĮ, savo Dievą, nusižengei ir išbarstei savo kelius svetimiesiems po kiekvienu žaliuojančiu medžiu, ir jūs nepaklusote mano balsui, – sako VIEŠPATS.'),
  (@b24, 3, 14, 'Sugrįžkite, atsimetę vaikai, – sako VIEŠPATS, – nes aš esu jus vedęs; ir aš paimsiu jus po vieną iš miesto ir po du iš šeimos ir jus atvesiu į Sioną;'),
  (@b24, 3, 15, 'ir jums duosiu ganytojų pagal savo širdį, kurie jus ganys pažinimu ir supratimu.'),
  (@b24, 3, 16, 'Ir įvyks, kai padaugėsite ir pagausėsite šalyje, tomis dienomis, – sako VIEŠPATS, – jie nebesakys ‘VIEŠPATIES sandoros skrynia’; nei ji niekam neateis į galvą; nei ją prisimins, nei ją lankys, nei to nebus daroma.'),
  (@b24, 3, 17, 'Tuo metu Jeruzalę vadins VIEŠPATIES sostu; ir į ją susirinks visos tautos prie VIEŠPATIES vardo į Jeruzalę; ir jie nebevaikščios pagal savo piktos širdies sumanymus.'),
  (@b24, 3, 18, 'Tomis dienomis Judos namai vaikščios su Izraelio namais, ir jie drauge ateis iš šiaurės šalies į šalį, kurią daviau paveldui jūsų tėvams“.'),
  (@b24, 3, 19, 'Bet aš tariau: „Kaip aš tave pastatysiu tarp vaikų ir tau duosiu geistiną šalį, gražų tautų kariuomenių paveldą?“ Ir aš tariau: „Tu mane vadinsi ‘Mano tėve’; ir nenusisuksi nuo manęs.'),
  (@b24, 3, 20, 'Iš tikrųjų, kaip žmona neištikimai besielgdama pasitraukia nuo savo vyro, taip jūs neištikimai elgėtės su manimi, o Izraelio namai“, – sako VIEŠPATS.'),
  (@b24, 3, 21, 'Ant aukštumų girdėjosi balsas, Izraelio vaikų verksmas ir prašymai; nes jie iškreipė savo kelią, jie pamiršo VIEŠPATĮ, savo Dievą.'),
  (@b24, 3, 22, '„Sugrįžkite, atsimetę vaikai, ir aš išgydysiu jūsų atsimetimus“. Štai mes ateiname pas tave, nes tu esi VIEŠPATS, mūsų Dievas.'),
  (@b24, 3, 23, 'Iš tiesų veltui viliamasi išgelbėjimo iš kalvų ir iš kalnų daugybės; iš tiesų VIEŠPATYJE, mūsų Dieve, yra Izraelio išgelbėjimas.'),
  (@b24, 3, 24, 'Nes gėda prarijo mūsų tėvų triūsą nuo pat mūsų jaunystės: jų kaimenes ir jų bandas, jų sūnus ir jų dukteris.'),
  (@b24, 3, 25, 'Mes gulime savo gėdoje, ir mus apdengia mūsų sarmata; nes mes nusidėjome prieš VIEŠPATĮ, savo Dievą, mes ir mūsų tėvai nuo mūsų jaunystės iki šios dienos, ir nepaklusome VIEŠPATIES, savo Dievo, balsui.'),
  (@b24, 4, 1, '„Jei tu, Izraeli, nori sugrįžti, – sako VIEŠPATS, – sugrįžk pas mane; ir jei pašalinsi savo bjaurystes nuo mano akių, tuomet tu neturėsi pasitraukti.'),
  (@b24, 4, 2, 'Ir tu prisieksi: ‘VIEŠPATS gyvas tiesoje, teisme ir teisume’; ir tautos juo laiminsis ir juo girsis“.'),
  (@b24, 4, 3, 'Nes taip sako VIEŠPATS Judos ir Jeruzalės žmonėms: „Išsiplėškite savo pūdymus ir nesėkite tarp erškėčių.'),
  (@b24, 4, 4, 'Apsipjaustykite VIEŠPAČIUI ir pašalinkite savo širdies apyvarpę, Judos žmonės ir Jeruzalės gyventojai, kad neišsiveržtų mano įtūžis kaip ugnis ir nedegtų neužgesinamai dėl jūsų darbų piktumo.'),
  (@b24, 4, 5, 'Skelbkite Judoje ir praneškite Jeruzalėje; ir sakykite: ‘Pūskite trimitą šalyje; šaukite, susirinkite ir sakykite: ‘Susirinkite ir įeikime į sutvirtintus miestus’.'),
  (@b24, 4, 6, 'Iškelkite vėliavą Siono link; pasišalinkite, nestovėkite; nes nelaimę ir didelį sunaikinimą aš atvesiu iš šiaurės.'),
  (@b24, 4, 7, 'Liūtas ateina aukštyn iš savo tankumyno, ir pagonių naikintojas yra savo kelyje; jis išėjo iš savo vietos, kad paverstų tavo šalį negyvenamą; tavo miestai bus nuniokoti, be gyventojų.'),
  (@b24, 4, 8, 'Todėl apsijuoskite ašutinėmis, raudokite ir kaukite, nes nenusigręžė nuo mūsų VIEŠPATIES smarkus pyktis“.'),
  (@b24, 4, 9, '„Ir tą dieną atsitiks, – sako VIEŠPATS, – kad karaliaus širdis ir kunigaikščių širdis pražus; kunigai bus apstulbę ir pranašai stebėsis“.'),
  (@b24, 4, 10, 'Tada aš tariau: „Ak, Viešpatie DIEVE! Iš tikrųjų tu smarkiai apgavai šitą tautą ir Jeruzalę, sakydamas: ‘Jūs turėsite taiką’, tuo tarpu kalavijas siekia sielą“.'),
  (@b24, 4, 11, 'Tuo metu bus sakoma šitai tautai ir Jeruzalei: „Sausas aukštumų vėjas dykumoje nešasi link mano tautos dukros, bet ne vėtyti ir ne valyti,'),
  (@b24, 4, 12, 'pilnas vėjas iš ten ateis pas mane: dabar aš paskelbsiu jiems nuosprendį“.'),
  (@b24, 4, 13, 'Štai jis pakils kaip debesys, ir jo vežimai bus kaip viesulas; greitesni už erelius jo žirgai. Vargas mums! Nes mes apiplėšti.'),
  (@b24, 4, 14, 'O Jeruzale, nuplauk savo širdį nuo nedorybės, kad būtum išgelbėta. Kaip ilgai tavo tuščios mintys gyvens tavyje?'),
  (@b24, 4, 15, 'Nes balsas praneša iš Dano ir skelbia vargą iš Efraimo kalno.'),
  (@b24, 4, 16, '„Paminėkite tautoms; štai skelbkite prieš Jeruzalę, kad sargybiniai ateina iš tolimos šalies ir pakelia savo balsą prieš Judos miestus.'),
  (@b24, 4, 17, 'Kaip lauko sargai jie yra aplink prieš ją; nes ji prieš mane maištavo, – sako VIEŠPATS.'),
  (@b24, 4, 18, 'Tavo kelias ir tavo darbai tau tai sukėlė; tai tavo nedorybė, nes ji karti, nes ji siekia iki tavo širdies“.'),
  (@b24, 4, 19, 'Mano viduriai, mano viduriai! Skauda pačią širdį; mano širdis triukšmauja manyje; negaliu tylėti, nes išgirdai, o mano siela, trimito garsą, karo pavojų.'),
  (@b24, 4, 20, 'Šaukiamas sunaikinimas po sunaikinimo; nes apiplėšta visa šalis; staiga apiplėštos mano palapinės, akimirksniu mano uždangalai.'),
  (@b24, 4, 21, 'Kaip ilgai matysiu vėliavą ir girdėsiu trimito garsą?'),
  (@b24, 4, 22, 'Nes mano tauta kvaila, jie manęs nepažino; jie atbukę vaikai, jie neturi supratimo; jie išmintingi daryti pikta, bet nemoka daryti gera.'),
  (@b24, 4, 23, 'Aš pažvelgiau į žemę, ir štai ji buvo beformė ir tuščia, į dangus, ir juose nebuvo šviesos.'),
  (@b24, 4, 24, 'Pažvelgiau į kalnus, ir štai jie drebėjo, ir visos kalvos siūbavo.'),
  (@b24, 4, 25, 'Aš pažvelgiau, ir štai nebuvo jokio žmogaus, ir visi dangų paukščiai buvo nuskridę.'),
  (@b24, 4, 26, 'Pažvelgiau, ir štai vaisinga vieta buvo dykuma, ir visi jos miestai buvo sugriauti nuo VIEŠPATIES akivaizdos, nuo jo smarkaus pykčio.'),
  (@b24, 4, 27, 'Nes taip tarė VIEŠPATS: „Visa šalis bus tuščia; tačiau aš nepadarysiu visiško galo.'),
  (@b24, 4, 28, 'Dėl to gedės žemė ir pajuoduos aukštai dangūs; nes aš tai pasakiau, aš tai nutariau ir nesigailėsiu nei nuo to nenusigręšiu“.'),
  (@b24, 4, 29, 'Visas miestas pabėgs dėl raitelių ir lankininkų triukšmo; jie eis į tankumynus ir lips ant uolų; visi miestai bus palikti, ir niekas juose negyvens.'),
  (@b24, 4, 30, 'Ir ką tu darysi, kai esi apiplėšta? Nors apsivilktum tamsiai raudonu, nors pasipuoštum aukso papuošalais, nors paryškintum savo veidą dažais, – veltui save gražintum; tavo meilužiai paniekins tave, jie ieškos tavo gyvybės.'),
  (@b24, 4, 31, 'Nes aš girdėjau tarsi gimdančios moters balsą, kaip savo pirmą vaiką gimdančiosios skausmą – balsą Siono dukters, save apraudančios, išskėtusios rankas ir sakančios: „Vargas man! Nes mano siela nuvargusi dėl žudikų“.'),
  (@b24, 5, 1, '„Bėgiokite pirmyn ir atgal Jeruzalės gatvėmis, žiūrėkite, sužinokite ir ieškokite jos plačiose vietose, jei rasite žmogų, jei yra kas nors, kas vykdo teismą, kas siekia tiesos; ir aš jai atleisiu.'),
  (@b24, 5, 2, 'Ir nors jie sako: ‘VIEŠPATS gyvas’, iš tikrųjų jie melagingai prisiekia.'),
  (@b24, 5, 3, 'O VIEŠPATIE, argi tavo akys nenukreiptos į tiesą? Tu juos mušei, bet jie neliūdėjo; tu juos naikinai, bet jie atsisakė priimti pataisymą; jie padarė savo veidus kietesnius už uolą; jie atsisakė sugrįžti.'),
  (@b24, 5, 4, 'Todėl aš tariau: „Tikrai šitie yra vargšai; jie kvaili; nes nepažįsta VIEŠPATIES kelio nei savo Dievo teismo.'),
  (@b24, 5, 5, 'Eisiu pas didžiūnus ir jiems kalbėsiu; nes jie žino VIEŠPATIES kelią ir savo Dievo teismą“; bet jie kartu sulaužę jungą, sutraukę pančius.'),
  (@b24, 5, 6, 'Todėl juos papjaus liūtas iš miško, ir vakarinis vilkas juos apiplėš, leopardas tykos prie jų miestų; kiekvienas iš jų išėjęs bus sudraskytas; nes daug jų nusižengimų ir padaugėjo jų atsimetimų.'),
  (@b24, 5, 7, '„Kaip man tau už tai atleisti? Tavo vaikai paliko mane ir prisiekė tais, kurie nėra dievai; kai juos pasotinau, jie svetimavo ir susirinko pulkais paleistuvių namuose.'),
  (@b24, 5, 8, 'Jie buvo kaip nupenėti arkliai ryte; kiekvienas žvengė paskui savo artimo žmoną.'),
  (@b24, 5, 9, 'Ar aš neaplankysiu už visa tai, – sako VIEŠPATS, – ar šitokiai tautai neatkeršys mano siela?'),
  (@b24, 5, 10, 'Užlipkite ant jos sienų ir naikinkite, bet ne iki galo; pašalinkite jos dantytas sienas, nes jos ne VIEŠPATIES.'),
  (@b24, 5, 11, 'Nes Izraelio namai ir Judos namai elgėsi prieš mane labai neištikimai“, – sako VIEŠPATS.'),
  (@b24, 5, 12, 'Jie išsigynė VIEŠPATIES ir sakė: „Tai ne jis; ir neateis ant mūsų nelaimė; ir nematysime nei kalavijo, nei bado“;'),
  (@b24, 5, 13, 'pranašai taps vėju, ir žodžio nėra juose; taip jiems bus padaryta.'),
  (@b24, 5, 14, 'Todėl taip sako VIEŠPATS, kariuomenių Dievas: „Kadangi jūs kalbate šitą žodį, štai aš padarysiu savo žodžius tavo burnoje ugnimi, o šitą tautą malkomis, ir jis jas prarys.'),
  (@b24, 5, 15, 'Štai aš atvesiu ant jūsų tautą iš toli, o Izraelio namai, – sako VIEŠPATS; ji yra galinga tauta, ji sena tauta, tauta, kurios kalbos tu nemoki nei nesupranti, ką jie kalba.'),
  (@b24, 5, 16, 'Jų strėlinė kaip atviras kapas, jie visi galiūnai.'),
  (@b24, 5, 17, 'Ir jie suvalgys tavo derlių ir tavo duoną, kurią turėtų valgyti tavo sūnūs ir tavo dukterys; jie suvalgys tavo kaimenes ir tavo bandas; jie suvalgys tavo vynmedžius ir tavo figmedžius; jie nusiaubs kalaviju tavo aptvertus miestus, kuriais tu pasitikėjai.'),
  (@b24, 5, 18, 'Tačiau tomis dienomis, – sako VIEŠPATS, – nepadarysiu jums visiško galo.'),
  (@b24, 5, 19, 'Ir įvyks, kai jūs sakysite: ‘Kodėl VIEŠPATS, mūsų Dievas, mums visa tai daro?‘ Tada tu jiems atsakysi: ‘Kaip jūs palikote mane ir tarnavote svetimiems dievams savo šalyje, taip tarnausite svetimiems ne savo šalyje’“.'),
  (@b24, 5, 20, 'Skelbkite tai Jokūbo namuose ir praneškite tai Judoje, sakydami:'),
  (@b24, 5, 21, '„Klausykis to, o kvaila tauta, neturinti supratimo; turinti akis, bet nematanti, turinti ausis, bet negirdinti;'),
  (@b24, 5, 22, 'ar nebijote manęs? – sako VIEŠPATS, – ar nedrebėsite mano akivaizdoje, kuris padėjau smėlį būti riba jūrai amžinu įsaku, kad ji jos neperžengtų; ir nors jos bangos siaustų, tačiau jos negali įveikti; nors jos šniokštų, tačiau jos negali per ją peržengti?'),
  (@b24, 5, 23, 'Bet šita tauta turi sukylančią ir maištingą širdį; jie sukilo ir nuėjo.'),
  (@b24, 5, 24, 'Ir jie nesako savo širdyje: ‘Bijokime dabar VIEŠPATIES, mūsų Dievo, kuris duoda tiek ankstyvą, tiek vėlyvą lietų jo laiku; jis mums išsaugo skirtas pjūties savaites’.'),
  (@b24, 5, 25, 'Jūsų neteisybės nukreipė šiuos dalykus, ir jūsų nuodėmės sulaikė nuo jūsų gerus dalykus.'),
  (@b24, 5, 26, 'Nes mano tautos tarpe radosi nedorėlių; jie tykoja kaip spendžiantys žabangas; jie paspendžia spąstus, pagauna žmones.'),
  (@b24, 5, 27, 'Kaip narvelis pilnas paukščių, taip jų namai pilni apgaulės; todėl jie tapo dideli ir pralobo.'),
  (@b24, 5, 28, 'Jie nutuko, jie blizga; taip, jie aplenkia nedorėlio darbus; jie neteisia bylos, našlaičių bylos, tačiau jie klesti; ir jie neteisia dėl nepasiturinčiojo teisių.'),
  (@b24, 5, 29, 'Ar aš neaplankysiu už šituos dalykus, – sako VIEŠPATS, – ar šitokiai tautai neatkeršys mano siela?'),
  (@b24, 5, 30, 'Nuostabių ir siaubingų dalykų vyksta šalyje:'),
  (@b24, 5, 31, 'pranašai pranašauja melagingai ir kunigai valdo savais būdais; o mano tauta taip mėgsta; bet ką darysite, kai tam ateis galas?“'),
  (@b24, 6, 1, 'O Benjamino vaikai, susirinkite bėgti iš Jeruzalės tarpo, Tekojoje pūskite trimitą ir Bet-Hakereme iškelkite ugnies ženklą; nes nelaimė ir didelis sunaikinimas pasirodė iš šiaurės.'),
  (@b24, 6, 2, 'Siono dukrą aš sulyginu su gražia ir lepia moterimi.'),
  (@b24, 6, 3, 'Ganytojai su savo kaimenėmis ateis pas ją; jie pasistatys aplink prieš ją palapines; jie kiekvienas ganys savo vietoje.'),
  (@b24, 6, 4, 'Ruoškitės prieš ją kariauti; kelkitės ir eikime aukštyn vidudienį. Vargas mums! Nes baigiasi diena, nes ilgėja vakaro šešėliai.'),
  (@b24, 6, 5, 'Kelkitės ir eikime nakčia, ir sunaikinkime jos rūmus.'),
  (@b24, 6, 6, 'Nes taip sakė kariuomenių VIEŠPATS: „Iškirskite medžius ir supilkite prieš Jeruzalę kalną; tai miestas, kurį reikia aplankyti; savo viduje jis visas yra priespauda.'),
  (@b24, 6, 7, 'Kaip šaltinis išpila savo vandenis, taip ir jis pila savo nedorybę; smurtas ir apiplėšimas girdėti jame; sielvartas ir žaizdos nuolat mano akivaizdoje.'),
  (@b24, 6, 8, 'Būk pamokoma, o Jeruzale, kad nepasitrauktų nuo tavęs mano siela; kad nepaversčiau tavęs tuščia, negyvenama šalimi“.'),
  (@b24, 6, 9, 'Taip sako kariuomenių VIEŠPATS: „Jie visiškai nurankios Izraelio likutį kaip vynmedį; atgręžk savo ranką kaip vynuogių skynėjas į pintinę“.'),
  (@b24, 6, 10, 'Kam turiu kalbėti ir ką įspėti, kad jie klausytų? Štai jų ausys neapipjaustytos, jos negali išgirsti; štai VIEŠPATIES žodis jiems yra priekaištas; jiems jis nepatinka.'),
  (@b24, 6, 11, 'Todėl aš pilnas VIEŠPATIES įtūžio; aš pavargau jį laikyti viduje; aš jį išliesiu ant vaikų lauke ir kartu ant jaunuolių susirinkimo; nes ir vyras su žmona bus sugauti, pagyvenęs su tuo, kuris yra pasisotinęs dienomis.'),
  (@b24, 6, 12, '„Ir jų namai pereis kitiems kartu su laukais ir žmonomis; nes aš ištiesiu savo ranką ant šalies gyventojų, – sako VIEŠPATS.'),
  (@b24, 6, 13, 'Nes nuo jų mažiausio iki jų didžiausio jie visi atsidavę godumui; ir nuo pranašo iki kunigo jie visi elgiasi apgaulingai.'),
  (@b24, 6, 14, 'Jie taipogi gydė mano tautos dukros sužalojimą paviršutiniškai, sakydami: ‘Taika, taika’, kai nėra taikos.'),
  (@b24, 6, 15, 'Ar jie gėdijosi darydami kas bjauru? Ne, jie visiškai nesigėdijo, nei jie moka parausti; todėl jie kris tarp krintančių; tuo laiku, kai aš juos aplankysiu, jie bus parblokšti“, – sako VIEŠPATS.'),
  (@b24, 6, 16, 'Taip sako VIEŠPATS: „Stovėkite keliuose ir žiūrėkite, ir teiraukitės senų takų, kur yra geras kelias, bei juo vaikščiokite, ir jūs rasite poilsį savo sieloms. Bet jie sakė: ‘Mes juo nevaikščiosime’.'),
  (@b24, 6, 17, 'Taip pat aš pastačiau jums sargų, sakydamas: ‘Klausykitės trimito garso’. Bet jie sakė: ‘Nesiklausysime’.'),
  (@b24, 6, 18, 'Todėl klausykite, tautos, ir žinokite, o susirinkime, kas yra tarp jų.'),
  (@b24, 6, 19, 'Klausyk, o žeme; štai aš užleisiu nelaimę ant šitos tautos, būtent jų minčių vaisių, nes jie neklausė mano žodžių ir mano įstatymo, bet jį atmetė.'),
  (@b24, 6, 20, 'Dėl ko man ateina smilkalai iš Šebos ir saldi nendrė iš tolimos šalies? Jūsų deginamosios atnašos nepriimtinos, ir jūsų aukos man nemielos“.'),
  (@b24, 6, 21, 'Todėl taip sako VIEŠPATS: „Štai aš padėsiu prieš šitą tautą kliūtis, tėvai ir sūnūs kartu grius ant jų; kaimynas ir jo draugas pražus“.'),
  (@b24, 6, 22, 'Taip sako VIEŠPATS: „Štai ateina tauta iš šiaurės šalies, didelė tauta pakils iš žemės pakraščių.'),
  (@b24, 6, 23, 'Jie nusitvers lanką ir ietį; jie žiaurūs ir negailestingi; jų balsas ūžia kaip jūra; ir jie joja ant žirgų, išsirikiavę kaip vyrai karui prieš tave, o Siono dukra“.'),
  (@b24, 6, 24, 'Mes išgirdome apie ją gandą; nusilpo mūsų rankos; mus suėmė sielvartas ir skausmas kaip gimdančią moterį.'),
  (@b24, 6, 25, 'Neišeikite į laukus nei nevaikščiokite keliu; nes priešo kalavijas ir baimė yra iš visų pusių.'),
  (@b24, 6, 26, 'O mano tautos dukra, apsijuosk ašutine ir voliokis pelenuose; gedėk kaip vienintelio sūnaus, karčiausiai raudok; nes plėšikas staiga ateis ant mūsų.'),
  (@b24, 6, 27, 'Aš pastačiau tave bokštu, tvirtove savo tautos tarpe, kad pažintum ir išmėgintum jų kelią.'),
  (@b24, 6, 28, 'Jie visi didžiausi maištininkai, vaikšto liežuvaudami; jie yra žalvaris ir geležis; jie visi gadintojai.'),
  (@b24, 6, 29, 'Dumplės sudegintos, švinas ugnies prarytas; liejikas lieja veltui; nes piktieji neatskirti.'),
  (@b24, 6, 30, 'Juos vadins atmestinu sidabru, nes VIEŠPATS juos atmetė.'),
  (@b24, 7, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES, sakydamas:'),
  (@b24, 7, 2, '„Atsistok VIEŠPATIES namų vartuose ir ten paskelbk šitą žodį, ir sakyk: ‘Klausykite VIEŠPATIES žodžio, visi iš Judos, kurie įeinate pro šituos vartus VIEŠPATĮ garbinti.'),
  (@b24, 7, 3, 'Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Taisykite savo kelius ir savo darbus, ir aš duosiu jums gyventi šitoje vietoje.'),
  (@b24, 7, 4, 'Nepasitikėkite melagingais žodžiais, sakančiais: ‘Tai VIEŠPATIES šventykla, VIEŠPATIES šventykla, VIEŠPATIES šventykla’.'),
  (@b24, 7, 5, 'Nes jei jūs visiškai pataisysite savo kelius ir savo darbus; jei jūs pilnai vykdysite teismą tarp žmogaus ir jo artimo;'),
  (@b24, 7, 6, 'jei neengsite svetimšalio, našlaičio ir našlės, ir nekalto kraujo nepraliesite šitoje vietoje, ir nevaikščiosite paskui kitus dievus savo pačių žalai;'),
  (@b24, 7, 7, 'tada aš jums duosiu gyventi šitoje vietoje, šalyje, kurią daviau jūsų tėvams, per amžių amžius.'),
  (@b24, 7, 8, 'Štai jūs pasitikite melagingais žodžiais, kurie neduoda naudos.'),
  (@b24, 7, 9, 'Ar jūs vogsite, žudysite, svetimausite, melagingai prisieksite, smilkysite Baalui ir vaikščiosite paskui kitus dievus, kurių nežinote,'),
  (@b24, 7, 10, 'ir atėję atsistosite prieš mane šituose namuose, kurie pavadinti mano vardu, ir sakysite: ‘Mes išvaduoti, kad darytume visas šitas bjaurybes’?'),
  (@b24, 7, 11, 'Ar šitie namai, kurie pavadinti mano vardu, jūsų akyse tapo plėšikų lindyne? Štai aš tai mačiau, – sako VIEŠPATS.'),
  (@b24, 7, 12, 'Bet gi eikite į mano vietą, buvusią Šilojuje, kur pradžioje pastačiau savo vardą, ir pažiūrėkite, ką jai padariau dėl mano tautos Izraelio nedorybės.'),
  (@b24, 7, 13, 'O dabar, kadangi darėte visus šituos darbus, – sako VIEŠPATS, – ir aš jums kalbėjau anksti atsikeldamas ir kalbėdamas, bet jūs nesiklausėte; ir jus šaukiau, bet jūs neatsiliepėte;'),
  (@b24, 7, 14, 'todėl šitiems namams, kurie vadinami mano vardu, kuriais jūs pasitikite, ir vietai, kurią daviau jums ir jūsų tėvams, aš padarysiu taip, kaip padariau Šilojui.'),
  (@b24, 7, 15, 'Ir aš išmesiu jus iš savo akivaizdos, kaip išmečiau visus jūsų brolius, tai yra, visą Efraimo sėklą“.'),
  (@b24, 7, 16, '„Todėl nesimelsk už šitą tautą ir nepakelk už juos nei šauksmo, nei maldos ir man jų neužtark; nes aš tavęs neišklausysiu.'),
  (@b24, 7, 17, 'Ar nematai, ką jie daro Judos miestuose ir Jeruzalės gatvėse?'),
  (@b24, 7, 18, 'Vaikai prirenka malkų, tėvai sukuria ugnį, o moterys minko tešlą, kad pagamintų pyragaičių dangaus karalienei ir išlietų geriamąsias atnašas kitiems dievams, kad kurstytų mano pyktį.'),
  (@b24, 7, 19, 'Ar jie kursto mano pyktį, – sako VIEŠPATS; – argi ne save pačius kursto savo veidų susigėdinimui?“'),
  (@b24, 7, 20, 'Todėl taip sako Viešpats DIEVAS: „Štai mano pyktis ir mano įtūžis bus išlieti ant šitos vietos, ant žmogaus ir ant gyvulio, ant lauko medžių ir ant žemės vaisių; tai degs ir neužges“.'),
  (@b24, 7, 21, 'Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: „Padėkite savo deginamąsias atnašas prie savo aukų ir valgykite mėsą.'),
  (@b24, 7, 22, 'Nes aš nekalbėjau jūsų tėvams ir jiems neįsakiau dėl deginamųjų atnašų ar aukų tą dieną, kai juos išvedžiau iš Egipto šalies;'),
  (@b24, 7, 23, 'bet štai šitą dalyką jiems įsakiau, sakydamas: ‘Pakluskite mano balsui, ir aš būsiu jūsų Dievas, o jūs būsite mano tauta; ir vaikščiokite visais keliais, kuriuos jums įsakau, kad jums gerai sektųsi.'),
  (@b24, 7, 24, 'Bet jie neklausė ir nepalenkė savo ausies, bet vaikščiojo pagal savo piktos širdies ketinimus ir sumanymus ir ėjo atgal, o ne pirmyn.'),
  (@b24, 7, 25, 'Nuo tos dienos, kai jūsų tėvai išėjo iš Egipto šalies, iki šios dienos aš siunčiau pas jus visus savo tarnus, pranašus, kas dieną anksti keldamas ir juos siųsdamas;'),
  (@b24, 7, 26, 'tačiau jie neklausė manęs ir nepalenkė savo ausies, bet užkietino savo sprandą; jie darė blogiau už savo tėvus.'),
  (@b24, 7, 27, 'Todėl tu jiems kalbėsi visus šituos žodžius; bet jie tavęs neklausys; taipogi tu juos šauksi, bet jie tau neatsilieps.'),
  (@b24, 7, 28, 'Bet tu jiems sakyk: ‘Tai tauta, kuri nepaklūsta VIEŠPATIES, savo Dievo, balsui ir nepriima pamokymo; tiesa pražuvo ir iškirsta iš jų burnos.'),
  (@b24, 7, 29, 'Nukirpk savo plaukus, o Jeruzale, numesk juos ir imkis raudos aukštumose; nes VIEŠPATS atmetė ir paliko savo rūstybės kartą.'),
  (@b24, 7, 30, 'Nes Judos vaikai darė pikta mano akyse, – sako VIEŠPATS; – jie pastatė savo bjaurystes namuose, kurie vadinami mano vardu, kad juos suteptų.'),
  (@b24, 7, 31, 'Ir jie pastatė Tofeto aukštumas, esančias Hinomo sūnaus slėnyje, kad savo sūnus ir savo dukteris degintų ugnyje, ko aš jiems neįsakiau ir tai man neatėjo į širdį.'),
  (@b24, 7, 32, 'Todėl štai ateina dienos, – sako VIEŠPATS, – kad tai nebebus vadinama nei Tofetu, nei Hinomo sūnaus slėniu, bet Skerdynių slėniu; nes jie laidos Tofete, kol nebebus ten vietos.'),
  (@b24, 7, 33, 'Ir šitos tautos lavonai bus maistas dangaus skrajūnams ir žemės žvėrims; ir niekas jų nenubaidys.'),
  (@b24, 7, 34, 'Tada aš duosiu pradingti iš Judos miestų ir iš Jeruzalės gatvių džiaugsmo balsui ir linksmybės balsui, jaunojo balsui ir jaunosios balsui; nes šalis bus tuščia“.'),
  (@b24, 8, 1, '„Tuo metu, – sako VIEŠPATS, – išneš Judos karalių kaulus, jos kunigaikščių kaulus, kunigų kaulus, pranašų kaulus ir Jeruzalės gyventojų kaulus iš jų kapų;'),
  (@b24, 8, 2, 'ir juos išbarstys prieš saulę, prieš mėnulį ir prieš visą dangaus kariuomenę, kuriuos jie mylėjo, kuriems jie tarnavo, paskui kuriuos jie vaikščiojo, kurių jie ieškojo ir kuriuos jie garbino; jie nebus nei surinkti, nei palaidoti; jie bus mėšlu ant žemės paviršiaus.'),
  (@b24, 8, 3, 'Ir verčiau pasirinks mirti negu gyventi visi likusieji, kurie išliko iš šitos piktos šeimos, kurie išlikę visose vietose, kur juos buvau nuvaręs, – sako kariuomenių VIEŠPATS.'),
  (@b24, 8, 4, '– Be to, tu jiems sakyk: Taip sako VIEŠPATS: Ar jie kris ir neatsikels? Ar nusigręš ir nesugrįš?'),
  (@b24, 8, 5, 'Tad kodėl šita Jeruzalės tauta atsimeta nuolatiniu atsimetimu? Jie tvirtai laikosi apgavystės, jie atsisako sugrįžti.'),
  (@b24, 8, 6, 'Aš klausiausi ir išgirdau, bet jie kalbėjo neteisingai; niekas neapgailestavo dėl savo nedorybės, sakydamas: ‘Ką aš padariau?’ Kiekvienas pasukęs savo kryptimi, kaip žirgas skubantis į mūšį.'),
  (@b24, 8, 7, 'Taip, gandras danguje žino savo paskirtus laikus; purplelis, gervė ir kregždė laikosi savo sugrįžimo meto; bet mano tauta nežino VIEŠPATIES teismo.'),
  (@b24, 8, 8, 'Kaipgi jūs sakote: ‘Mes esame išmintingi, ir VIEŠPATIES įstatymas yra su mumis’? Štai iš tikrųjų jis pavertė tai nieku, raštininkų plunksna yra niekas.'),
  (@b24, 8, 9, 'Išmintingieji sugėdinti, jie nerimauja ir yra pagauti; štai jie atmetė VIEŠPATIES žodį; ir kokia juose išmintis?'),
  (@b24, 8, 10, 'Todėl jų žmonas duosiu kitiems, o jų laukus tiems, kurie juos paveldės; nes visi nuo mažiausiojo iki didžiausiojo atsidavę godumui, nuo pranašo iki kunigo visi elgiasi apgaulingai.'),
  (@b24, 8, 11, 'Nes jie gydė mano tautos dukters sužalojimą paviršutiniškai, sakydami: ‘Taika, taika’, kai nėra taikos.'),
  (@b24, 8, 12, 'Ar jie gėdijosi padarę, kas bjauru? Ne, jie visiškai nesigėdijo, nei jie moka parausti; todėl jie kris tarp krintančių; jų aplankymo laiku jie bus parblokšti, – sako VIEŠPATS.'),
  (@b24, 8, 13, '– Aš tikrai juos sunaikinsiu, – sako VIEŠPATS, – nebus vynuogių ant vynmedžio nei figų ant figmedžio, ir lapai nuvys; ir tai, ką jiems buvau davęs, pasitrauks nuo jų’“.'),
  (@b24, 8, 14, '„Kodėl mes sėdime? Susirinkite, įeikime į sutvirtintus miestus ir ten tylėkime; nes VIEŠPATS, mūsų Dievas, mus nutildė ir mums davė gerti tulžies vandens, nes nusidėjome prieš VIEŠPATĮ.'),
  (@b24, 8, 15, 'Mes ieškojome taikos, bet nieko gero neatėjo, ir sveikatos meto, o štai – vargas!'),
  (@b24, 8, 16, 'Nuo Dano girdisi jo žirgų prunkštimas; nuo jo stipriųjų žvengimo garso dreba visa šalis; nes jie atėjo ir prarijo šalį ir visa, kas joje, miestą ir jame gyvenančius“.'),
  (@b24, 8, 17, '„Nes štai aš pasiųsiu tarp jūsų gyvačių, angių, kurių negalima užkerėti, ir jos jums įgels“, – sako VIEŠPATS.'),
  (@b24, 8, 18, 'Kai noriu pasiguosti dėl sielvarto, mano širdis alpsta manyje.'),
  (@b24, 8, 19, 'Štai mano tautos dukters šauksmo balsas dėl gyvenančių tolimoje šalyje: „Argi nėra VIEŠPATIES Sione? Ar nėra jo karaliaus jame?“ Kodėl jie kurstė mano pyktį savo raižytais atvaizdais, svetimomis tuštybėmis?'),
  (@b24, 8, 20, 'Praėjo pjūtis, pasibaigė vasara, o mes nesame išgelbėti.'),
  (@b24, 8, 21, 'Dėl savo tautos dukters sužalojimo esu sužalotas; esu niūrus; apstulbimas suėmė mane.'),
  (@b24, 8, 22, 'Argi nėra balzamo Gileade, ar nėra ten gydytojo? Tai kodėl nesugrąžinta mano tautos dukters sveikata?'),
  (@b24, 9, 1, 'O, kad mano galva būtų vandenys ir mano akys – ašarų šaltinis, jog dieną ir naktį galėčiau apraudoti savo tautos dukters užmuštuosius!'),
  (@b24, 9, 2, 'O kad dykumoje turėčiau keliautojų buveinę; kad galėčiau palikti savo tautą ir eiti nuo jų! Nes jie visi svetimautojai, neištikimųjų sambūris.'),
  (@b24, 9, 3, '„Jie įtempia savo liežuvius melams kaip savo lanką; bet jie nėra narsūs už tiesą žemėje; nes jie eina iš pikto į pikta ir manęs nepažįsta, – sako VIEŠPATS.'),
  (@b24, 9, 4, '– Saugokitės kiekvienas savo artimo ir nepasitikėkite nei vienu broliu; nes kiekvienas brolis visiškai išstums kitą, ir kiekvienas artimas vaikščios skleisdamas šmeižtus.'),
  (@b24, 9, 5, 'Ir jie apgaudinės kiekvienas savo artimą ir nekalbės tiesos; jie išmokė savo liežuvį kalbėti melus, ir nuvargina save, darydami neteisybę.'),
  (@b24, 9, 6, 'Tavo buveinė apgaulės tarpe; per apgaulę jie atsisako pažinti mane“, – sako VIEŠPATS.'),
  (@b24, 9, 7, 'Todėl taip sako kariuomenių VIEŠPATS: „Štai aš juos išlydysiu ir išmėginsiu; nes kaipgi turėčiau daryti savo tautos dukrai?'),
  (@b24, 9, 8, 'Jų liežuvis kaip iššauta strėlė; jis kalba apgaulę; jie burna taikingai kalba savo artimui, bet širdyje jie jo tykoja.'),
  (@b24, 9, 9, 'Argi už tai neturėčiau jų aplankyti? – sako VIEŠPATS; – ar šitokiai tautai neatkeršys mano siela?'),
  (@b24, 9, 10, 'Dėl kalnų imsiu verkti ir dejuoti, ir dėl dykumos buveinių raudosiu, nes jie sudeginti taip, kad niekas negali pereiti per juos; ir niekas negirdi galvijų balso; ir dangų skrajūnai, ir žvėrys pabėgo; jie dingo.'),
  (@b24, 9, 11, 'Ir aš padarysiu Jeruzalę krūvomis ir slibinų lindyne; ir Judos miestus padarysiu tuščius, be gyventojų.'),
  (@b24, 9, 12, 'Kas yra išmintingas, kad galėtų tai suprasti? Ir kas yra tas, kuriam kalbėjo VIEŠPATIES burna, kad jis tai paskelbtų, dėl ko žūsta šalis, sudeginta kaip dykuma, jog niekas nepereina?“'),
  (@b24, 9, 13, 'Ir VIEŠPATS sako: „Kadangi jie paliko mano įstatymą, kurį padėjau jų priešakyje, ir nepakluso mano balsui, ir pagal jį nevaikščiojo;'),
  (@b24, 9, 14, 'bet vaikščiojo pagal savo širdies sumanymus ir paskui Baalus, kurių jų tėvai juos išmokė“.'),
  (@b24, 9, 15, 'Todėl taip sako kariuomenių VIEŠPATS, Izraelio Dievas: „Štai aš juos, tai yra, šią tautą, maitinsiu metėlėmis ir duosiu jiems gerti tulžies vandens.'),
  (@b24, 9, 16, 'Taipogi aš juos išsklaidysiu tarp pagonių, kurių nežinojo nei jie, nei jų tėvai; ir siųsiu paskui juos kalaviją, kol juos sunaikinsiu“.'),
  (@b24, 9, 17, 'Taip sako kariuomenių VIEŠPATS: „Apgalvokite ir pasišaukite raudotojų, kad jos ateitų; ir siųskite pas sumanias moteris, kad jos ateitų;'),
  (@b24, 9, 18, 'ir jos teatskuba ir ima dėl mūsų raudoti, idant mūsų akys lietųsi ašaromis ir mūsų akių vokai ištrykštų vandenimis“.'),
  (@b24, 9, 19, 'Nes raudojimo balsas girdisi iš Siono: Kaip mes sunaikinti! Mes labai susigėdę, nes mes palikome šalį, nes mūsų buveinės mus išmetė.'),
  (@b24, 9, 20, 'Klausykite, o moterys, VIEŠPATIES žodžio ir tepriima jūsų ausys jo burnos žodį, ir savo dukteris mokykite raudoti, ir kiekviena savo artimą – raudos.'),
  (@b24, 9, 21, 'Nes mirtis lipo pro mūsų langus ir įžengė į mūsų rūmus, kad iškirstų vaikus lauke, jaunuolius gatvėse.'),
  (@b24, 9, 22, 'Kalbėk: Taip sako VIEŠPATS: „Žmonių lavonai kris kaip mėšlas atvirame lauke, kaip saujos paskui pjovėją, ir niekas jų nesurinks“.'),
  (@b24, 9, 23, 'Taip sako VIEŠPATS: „Išmintingasis tenesigiria savo išmintimi ir galingasis tenesigiria savo galia, turtingasis tenesigiria savo turtais;'),
  (@b24, 9, 24, 'bet tas, kuris giriasi, tesigiria tuo, kad supranta ir pažįsta mane, kad aš esu VIEŠPATS, kuris vykdo mylintį gerumą, teismą ir teisumą žemėje; nes tais dalykais aš gėriuosi“, – sako VIEŠPATS.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 9, 25, '„Štai ateina dienos, – sako VIEŠPATS, – kai aš nubausiu visus apipjaustytuosius su neapipjaustytais:'),
  (@b24, 9, 26, 'Egiptą, Judą, Edomą, Amono vaikus, Moabą ir visus, esančius tolimiausiuose pakraščiuose, kurie gyvena dykumoje; nes visos šitos tautos yra neapipjaustytos, ir visi Izraelio namai – neapipjaustyti širdyje“.'),
  (@b24, 10, 1, 'Klausykite žodžio, kurį VIEŠPATS kalba jums, o Izraelio namai:'),
  (@b24, 10, 2, 'Taip sako VIEŠPATS: „Nesimokykite pagonių kelio ir neišsigąskite dangaus ženklų; nes pagonys jų išsigąsta.'),
  (@b24, 10, 3, 'Nes tautų papročiai yra tušti: nes jie išsikerta iš miško medį, meistro rankų darbą, kirviu.'),
  (@b24, 10, 4, 'Sidabru ir auksu jie jį pagražina; vinimis ir kūjais pritvirtina, kad tas nejudėtų.'),
  (@b24, 10, 5, 'Jie tiesūs kaip palmė, bet nekalba; jie turi būti nešami, nes negali eiti. Nebijokite jų; nes jie negali daryti pikta, nei gera daryti jie nepajėgia“.'),
  (@b24, 10, 6, 'Kadangi nėra tau lygaus, o VIEŠPATIE; tu esi didis, ir didžiai galingas tavo vardas.'),
  (@b24, 10, 7, 'Kas tavęs nebijotų, o tautų Karaliau? Nes tau tai priklauso; kadangi tarp visų tautų išminčių ir visose jų karalystėse nėra nei vieno tau lygaus.'),
  (@b24, 10, 8, 'Bet jie iki vieno buki ir kvaili; medžio stiebas yra tuštybių mokslas.'),
  (@b24, 10, 9, 'Sidabras suplotas į plokštes atgabentas iš Taršišo, o auksas iš Ufazo, meistro ir liejiko rankų darbas; mėlynas ir purpuras yra jų apdaras; jie visi yra sumaniųjų darbas.'),
  (@b24, 10, 10, 'Bet VIEŠPATS yra tikrasis Dievas, jis yra gyvasis Dievas ir amžinas karalius; nuo jo rūstybės drebės žemė ir tautos nepajėgs ištverti jo pasipiktinimo.'),
  (@b24, 10, 11, 'Taip jiems sakysite: „Dievai, kurie nepadarė nei dangų, nei žemės, pradings nuo žemės ir iš po šitų dangų“.'),
  (@b24, 10, 12, 'Jis padarė žemę savo jėga, jis įtvirtino pasaulį savo išmintimi, ir savo protingumu ištiesė dangus.'),
  (@b24, 10, 13, 'Kai jis ištaria savo balsą, danguose yra vandenų gausybė, ir jis padaro, kad garai pakiltų nuo žemės pakraščių; jis padaro žaibų su lietumi ir išveda vėją iš savo lobynų.'),
  (@b24, 10, 14, 'Kiekvienas žmogus yra neprotingas savo pažinimu; kiekvienas liejikas sugėdintas raižytu atvaizdu; nes jo nulietas atvaizdas yra apgaulė, ir nėra juose kvapo.'),
  (@b24, 10, 15, 'Jie yra tuštybė, paklydimų darbas; jų aplankymo metu jie pražus.'),
  (@b24, 10, 16, 'Jokūbo dalis ne tokia, kaip jie; nes jis yra visų dalykų formuotojas; ir Izraelis yra jo nuosavybės lazda; kariuomenių VIEŠPATS yra jo vardas.'),
  (@b24, 10, 17, 'Surink savo dirbinius iš šalies, o tvirtovės gyventojau.'),
  (@b24, 10, 18, 'Nes taip sako VIEŠPATS: „Štai šį kartą aš išsviesiu šalies gyventojus ir juos prispausiu, kad jie taip rastų“.'),
  (@b24, 10, 19, 'Vargas man dėl mano sužalojimo! Skausminga mano žaizda; bet aš tariau: „Tikrai tai sielvartas, ir aš turiu jį nešioti“.'),
  (@b24, 10, 20, 'Mano padangtė apiplėšta ir visos mano virvės sutraukytos; mano vaikai išėję iš manęs, ir jų nėra; daugiau nebėra, kas ištiestų mano palapinę ir pakeltų mano uždangalus.'),
  (@b24, 10, 21, 'Nes ganytojai tapo neprotingi ir neieškojo VIEŠPATIES; todėl jiems nesiseks, ir visos jų kaimenės bus išsklaidytos.'),
  (@b24, 10, 22, 'Štai gando triukšmas ateina ir didelis sambrūzdis iš šiaurės šalies, kad Judos miestus padarytų tuščiais, slibinų buveine.'),
  (@b24, 10, 23, 'O VIEŠPATIE, aš žinau, kad žmogaus kelias nėra jame pačiame; ne vaikščiojančiam žmogui nukreipti savo žingsnius.'),
  (@b24, 10, 24, 'O VIEŠPATIE, bausk mane, bet tik teismu, ir ne supykęs, kad nepaverstum manęs nieku.'),
  (@b24, 10, 25, 'Išliek savo įtūžį ant pagonių, kurie tavęs nepažįsta, ir ant šeimų, kurios nesišaukia tavo vardo; nes jos suėdė Jokūbą, jį surijo, sunaikino jį ir jo buveinę padarė tuščią.'),
  (@b24, 11, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES, sakydamas:'),
  (@b24, 11, 2, '„Klausykitės šios sandoros žodžių ir kalbėkite Judos žmonėms ir Jeruzalės gyventojams,'),
  (@b24, 11, 3, 'ir jiems tark: Taip sako VIEŠPATS, Izraelio Dievas: ‘Tebūna prakeiktas žmogus, kuris nepaklūsta šitos sandoros žodžiams,'),
  (@b24, 11, 4, 'kuriuos aš įsakiau jūsų tėvams tą dieną, kai juos išvedžiau iš Egipto šalies, iš geležies krosnies, tardamas: „Pakluskite mano balsui ir juos vykdykite pagal visa tai, ką jums įsakau; taip jūs būsite mano tauta, o aš būsiu jūsų Dievas“;'),
  (@b24, 11, 5, 'kad aš ištesėčiau priesaiką, kurią prisiekiau jūsų tėvams, – duoti jiems šalį, plūstančią pienu ir medumi, kaip yra šią dieną’“. Tada aš atsakiau ir tariau: „Tebūna taip, o VIEŠPATIE“.'),
  (@b24, 11, 6, 'Paskui VIEŠPATS man tarė: „Skelbk visus šituos žodžius Judos miestuose ir Jeruzalės gatvėse, sakydamas: ‘Klausykite šitos sandoros žodžių ir juos vykdykite.'),
  (@b24, 11, 7, 'Nes aš uoliai tvirtinau jūsų tėvams tą dieną, kai juos išvedžiau aukštyn iš Egipto šalies, ir iki šios dienos, anksti keldamasis tvirtinau, sakydamas: „Pakluskite mano balsui“.'),
  (@b24, 11, 8, 'Tačiau jie nepakluso nei nepalenkė savo ausies, bet kiekvienas vaikščiojo pagal savo piktos širdies sumanymą; todėl aš užleisiu ant jų visus šitos sandoros žodžius, kuriuos įsakiau jiems vykdyti, bet jie nevykdė jų’“.'),
  (@b24, 11, 9, 'Ir VIEŠPATS man tarė: „Radosi sąmokslas tarp Judos žmonių ir tarp Jeruzalės gyventojų.'),
  (@b24, 11, 10, 'Jie sugrįžo į neteisybes savo protėvių, kurie atsisakė klausyti mano žodžių; ir jie nuėjo paskui kitus dievus, jiems tarnauti; Izraelio namai ir Judos namai sulaužė mano sandorą, kurią sudariau su jų tėvais“.'),
  (@b24, 11, 11, 'Todėl taip sako VIEŠPATS: „Štai aš užleisiu ant jų nelaimę, iš kurios jie negalės ištrūkti; ir nors jie šauksis manęs, aš jų neišklausysiu.'),
  (@b24, 11, 12, 'Tada Judos miestai ir Jeruzalės gyventojai nueis ir šauksis dievų, kuriems jie atnašauja smilkalus; bet jie iš viso jų neišgelbės jų nelaimės metu.'),
  (@b24, 11, 13, 'Nes tavo dievų yra pagal tavo miestų skaičių, o Juda; ir pagal Jeruzalės gatvių skaičių jūs pastatėte šitam gėdingam dalykui aukurų – aukurų Baalui smilkyti.'),
  (@b24, 11, 14, 'Todėl tu nesimelsk už šitą tautą nei nekelk už juos šauksmo ar maldos; nes aš jų neklausysiu tuo metu, kai jie manęs šauksis dėl savo bėdos.'),
  (@b24, 11, 15, 'Kas mano mylimajai darbo mano namuose, atsižvelgiant į tai, kad ji vykdė nešvankybes su daugeliu, ir šventa mėsa dingo nuo tavęs? Kai tu darai pikta, tu džiaugiesi.'),
  (@b24, 11, 16, 'VIEŠPATS pavadino tave žaliuojančiu, gražiu, gražių vaisių alyvmedžiu; didžiulio sujudimo triukšmu jis uždegė jį ugnimi, ir jo šakos sulaužytos.'),
  (@b24, 11, 17, 'Nes kariuomenių VIEŠPATS, kuris pasodino tave, paskelbė prieš tave pikta dėl Izraelio namų ir Judos namų pikto, kurį jie darė prieš save, kurstydami mano pyktį smilkalų atnašavimu Baalui.'),
  (@b24, 11, 18, 'Ir VIEŠPATS man davė tai žinoti, ir aš tai žinau; tada tu man parodei jų darbus.'),
  (@b24, 11, 19, 'Bet aš buvau kaip avinėlis ar jautis, vedamas pjauti; ir aš nežinojau, kad jie sugalvojo prieš mane planus, sakydami: „Sunaikinkime medį su jo vaisiais ir iškirskime jį iš gyvųjų šalies, kad nebeatsimintų jo vardo“.'),
  (@b24, 11, 20, 'Bet, kariuomenių VIEŠPATIE, kuris teisi teisingai, kuris išmėgini inkstus ir širdį, leisk man pamatyti tavo kerštą jiems; nes tau atskleidžiau savo bylą.'),
  (@b24, 11, 21, 'Todėl taip sako VIEŠPATS apie Anatoto žmones, ieškančius tavo gyvybės ir sakančius: „Nepranašauk VIEŠPATIES vardu, kad nemirtum nuo mūsų rankos“;'),
  (@b24, 11, 22, 'todėl taip sako kariuomenių VIEŠPATS: „Štai aš juos nubausiu; jaunuoliai mirs nuo kalavijo; jų sūnūs ir jų dukterys mirs nuo bado;'),
  (@b24, 11, 23, 'ir iš jų niekas neišliks; nes aš užleisiu nelaimę ant Anatoto žmonių, būtent jų aplankymo metus“.'),
  (@b24, 12, 1, 'Teisus tu esi, o VIEŠPATIE, kai bylinėjuosi su tavimi; tačiau leisk man kalbėti su tavimi apie tavo teismus: „Kodėl klesti nedorėlių kelias? Kodėl laimingi visi, kurie labai išdavikiškai elgiasi?'),
  (@b24, 12, 2, 'Tu juos pasodinai, taip, jie įleido šaknis; jie užaugo, taip, atnešė vaisių; jų burnoje tu esi arti, bet toli nuo jų inkstų.'),
  (@b24, 12, 3, 'Bet tu, o VIEŠPATIE, pažįsti mane; tu matei mane ir išmėginai mano širdį tau; ištempk juos kaip avis pjovimui ir paruošk juos skerdynių dienai.'),
  (@b24, 12, 4, 'Kaip ilgai gedės šalis ir džius kiekvieno lauko žolės dėl jos gyventojų nedorybių? Sunaikinti gyvuliai ir paukščiai; nes jie sakė: ‘Jis nematys mūsų galo’.'),
  (@b24, 12, 5, 'Jei tu bėgai su pėstininkais, ir jie nuvargino tave, tad kaip gali varžytis su žirgais? Ir jei ramioje šalyje, kuria pasitiki, jie nuvargino tave, tai ką tu darysi patvinus Jordanui?'),
  (@b24, 12, 6, 'Nes netgi tavo broliai, tavo tėvo namai, net jie neištikimai elgėsi su tavimi; taip, jie pašaukė minią paskui tave; netikėk jais, nors jie tau kalba gražius žodžius.'),
  (@b24, 12, 7, 'Aš palikau savo namus, palikau savo paveldą; aš atidaviau savo sielos labai mylimą į jo priešų rankas.'),
  (@b24, 12, 8, 'Mano paveldas man yra kaip liūtas miške; jis šaukia prieš mane; todėl aš jo nekenčiau.'),
  (@b24, 12, 9, 'Mano paveldas man yra kaip raibas paukštis, aplink esantys paukščiai yra prieš jį; ateikite, surinkite visus lauko žvėris, ateikite ryti.'),
  (@b24, 12, 10, 'Daug ganytojų naikino mano vynuogyną, jie mindė mano dalį po kojomis, jie pavertė mano geistiną dalį tuščia dykuma.'),
  (@b24, 12, 11, 'Jie padarė ją tuščią, ir būdama tuščia ji man rauda; visa šalis ištuštinta, nes nei vienas neima to į širdį.'),
  (@b24, 12, 12, 'Ant visų aukštumų per dykumą atėjo plėšikai; nes VIEŠPATIES kalavijas rys nuo vieno šalies krašto iki kito šalies krašto; joks kūnas neturės ramybės“.'),
  (@b24, 12, 13, 'Jie pasėjo kviečius, bet pjaus erškėčius; jie nusikamavo, bet neturės naudos; ir jie gėdysis jūsų pajamomis dėl smarkaus VIEŠPATIES pykčio.'),
  (@b24, 12, 14, 'Taip sako VIEŠPATS dėl visų mano piktų kaimynų, palietusių paveldą, kurį daviau paveldėti savo tautai Izraeliui: „Štai aš juos išrausiu iš jų šalies, ir išrausiu Judos namus iš jų tarpo.'),
  (@b24, 12, 15, 'Ir kai būsiu juos išrovęs, įvyks, kad aš sugrįšiu ir jų pasigailėsiu, ir juos sugrąžinsiu kiekvieną į savo paveldą ir kiekvieną į savo šalį.'),
  (@b24, 12, 16, 'Ir įvyks, jeigu jie stropiai mokysis mano tautos kelių, kad prisiektų mano vardu: ‘VIEŠPATS gyvas’, kaip jie mokė mano tautą prisiekti Baalu, tuomet jie bus pastatyti mano tautos tarpe.'),
  (@b24, 12, 17, 'Bet jei jie nepaklus, aš visiškai išrausiu ir sunaikinsiu tą tautą“, – sako VIEŠPATS.'),
  (@b24, 13, 1, 'Taip man sako VIEŠPATS: „Eik ir įsigyk lininę juostą, ir susijuosk ja strėnas, bet neįmerk jos į vandenį“.'),
  (@b24, 13, 2, 'Taigi aš įsigijau juostą pagal VIEŠPATIES žodį ir susijuosiau ja strėnas.'),
  (@b24, 13, 3, 'Ir VIEŠPATIES žodis man atėjo antrą kartą, sakydamas:'),
  (@b24, 13, 4, '„Paimk juostą, kurią įsigijai, kuri yra ant tavo strėnų, ir atsikėlęs eik prie Eufrato, ir ten ją paslėpk uolos skylėje“.'),
  (@b24, 13, 5, 'Taigi aš nuėjau ir ją paslėpiau prie Eufrato, kaip VIEŠPATS man įsakė.'),
  (@b24, 13, 6, 'Ir įvyko, kad po daugelio dienų VIEŠPATS man tarė: „Kelkis, eik į Eufratą ir paimk iš ten juostą, kurią tau įsakiau ten paslėpti“.'),
  (@b24, 13, 7, 'Tada aš nuėjau į Eufratą, iškasiau ir paėmiau juostą iš tos vietos, kur buvau ją paslėpęs; ir štai, ta juosta buvo supuvusi, niekam tikusi.'),
  (@b24, 13, 8, 'Tada man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 13, 9, '„Taip sako VIEŠPATS: ‘Taip aš supūdysiu Judos išdidumą ir didįjį Jeruzalės išdidumą.'),
  (@b24, 13, 10, 'Šita pikta tauta, kuri atsisako klausyti mano žodžių, kuri vaikšto pagal savo širdies sumanymą ir vaikšto paskui kitus dievus, kad jiems tarnautų ir juos garbintų, bus kaip šita juosta, kuri niekam tikusi.'),
  (@b24, 13, 11, 'Nes kaip juosta prilimpa prie žmogaus strėnų, taip aš prilipdžiau prie savęs visus Izraelio namus ir visus Judos namus, – sako VIEŠPATS, – kad jie būtų man tauta, vardas, gyrius ir šlovė; bet jie nenorėjo klausyti.'),
  (@b24, 13, 12, 'Todėl kalbėk jiems šitą žodį: Taip sako VIEŠPATS, Izraelio Dievas: ‘Kiekvienas indas bus pripildytas vyno’; ir jie tau sakys: ‘Argi tikrai mes nežinome, kad kiekvienas indas bus pripildytas vyno?’'),
  (@b24, 13, 13, 'Tada jiems tark: Taip sako VIEŠPATS: ‘Štai aš pripildysiu girtybe visus šitos šalies gyventojus, būtent karalius, sėdinčius Dovydo soste, kunigus, pranašus ir visus Jeruzalės gyventojus.'),
  (@b24, 13, 14, 'Ir aš juos sudaužysiu vieną į kitą, tėvus ir sūnus kartu, – sako VIEŠPATS; – aš neužjausiu nei tausosiu, nei pasigailėsiu, bet juos sunaikinsiu’“.'),
  (@b24, 13, 15, 'Klausykite ir atsukite ausį; nebūkite išdidūs, nes VIEŠPATS kalbėjo.'),
  (@b24, 13, 16, 'Duokite VIEŠPAČIUI, savo Dievui, šlovę, kol jis neužtemdė ir kol jūsų kojos nesuklupo už tamsių kalnų, ir kad jums belaukiant šviesos jis nepaverstų jos į mirties šešėlį ir nepadarytų jos visiška tamsybe.'),
  (@b24, 13, 17, 'Bet jei jūs to neklausysite, mano siela slaptavietėse verks dėl jūsų išdidumo; ir mano akis graudžiai verks ir lies ašaras, nes VIEŠPATIES kaimenė išvesta nelaisvėn.'),
  (@b24, 13, 18, 'Sakykite karaliui ir karalienei: „Nusižeminkite, sėskite žemai; nes nukris jūsų kunigaikštystės, būtent jūsų šlovės karūna“.'),
  (@b24, 13, 19, 'Pietų miestai bus užrakinti, ir niekas jų neatidarys; visa Juda bus išvesta nelaisvėn, ji visiškai bus išvesta nelaisvėn.'),
  (@b24, 13, 20, 'Pakelkite savo akis ir žiūrėkite į ateinančius iš šiaurės; kur yra kaimenė, kuri tau buvo duota, tavo gražioji kaimenė?'),
  (@b24, 13, 21, 'Ką sakysi, kai jis tave baus? Nes tu juos mokei būti vadais ir tavo vyriausiais; argi nesuims tavęs sielvartai, kaip gimdančią moterį?'),
  (@b24, 13, 22, 'Ir jei sakysi savo širdyje: ‘Kodėl mane tai ištiko?’ Dėl tavo neteisybės didybės tavo skvernai atidengti, tavo kulnai apnuoginti.'),
  (@b24, 13, 23, 'Ar etiopas gali pakeisti savo odą arba leopardas – savo dėmes? Tai ir jūs, kurie esate įpratę daryti pikta, galėtumėte daryti gera.'),
  (@b24, 13, 24, 'Todėl aš juos išsklaidysiu kaip ražieną, išnešiojamą dykumos vėjo.'),
  (@b24, 13, 25, 'Tai yra tavo burtas, nuo manęs tau atmatuota dalis, – sako VIEŠPATS; – kadangi pamiršai mane ir pasitikėjai melu.'),
  (@b24, 13, 26, 'Todėl aš užversiu tavo skvernus tau ant veido, kad pasirodytų tavo gėda.'),
  (@b24, 13, 27, 'Aš mačiau tavo svetimavimus ir tavo žvengimus, tavo paleistuvystės gašlumą ir tavo bjaurystes ant kalvų laukuose. Vargas tau, o Jeruzale! Ar tu neapsivalysi? Kada tai pagaliau bus?“'),
  (@b24, 14, 1, 'VIEŠPATIES žodis, kuris atėjo Jeremijui apie stoką.'),
  (@b24, 14, 2, 'Juda liūdi ir jos vartai silpsta; jie pajuodę ant žemės; ir Jeruzalės šauksmas kyla aukštyn.'),
  (@b24, 14, 3, 'Ir jų kilmingieji siunčia savo mažylius prie vandenų; jie ateina prie duobių, bet neranda vandens; jie sugrįžo tuščiais indais; jie susigėdę ir suglumę, ir apsidengę galvas.'),
  (@b24, 14, 4, 'Kadangi dirva suaižėjusi, nes nebuvo žemėje lietaus, artojai susigėdę, apsidengę galvas.'),
  (@b24, 14, 5, 'Taip, ir elnė lauke atsiveda jauniklių ir juos palieka, nes nėra žolės.'),
  (@b24, 14, 6, 'Ir laukiniai asilai stovėjo ant aukštumų, uostydami vėją kaip slibinai; jų akys išsekusios, nes nebuvo žolės.'),
  (@b24, 14, 7, 'O VIEŠPATIE, nors mūsų neteisybės liudija prieš mus, daryk tai dėl savo vardo; nes daug yra mūsų atsimetimų; mes prieš tave nusidėjome.'),
  (@b24, 14, 8, 'O Izraelio viltie, jo gelbėtojau vargo metu, kodėl turėtumei būti kaip svetimšalis šalyje ir kaip keleivis, kuris pasuka į šalį pasilikti nakčiai?'),
  (@b24, 14, 9, 'Kodėl turėtumei būti kaip apstulbintas žmogus, kaip galiūnas, negalintis išgelbėti? Tačiau tu, o VIEŠPATIE, esi tarp mūsų, ir mes vadinami tavo vardu; nepalik mūsų.'),
  (@b24, 14, 10, 'Taip sako VIEŠPATS šitai tautai: „Jie taip mėgo klaidžioti, jie nesulaikė savo kojų, todėl VIEŠPATS jų nepriima; dabar jis atsimins jų neteisybę ir aplankys jų nuodėmes“.'),
  (@b24, 14, 11, 'Tada VIEŠPATS man tarė: „Nesimelsk už šitą tautą jų labui.'),
  (@b24, 14, 12, 'Kai jie pasninkauja, aš neišklausysiu jų šauksmo; ir kai jie atnašauja deginamąją atnašą ir auką, aš jų nepriimsiu; bet aš juos prarysiu kalaviju, badu ir maru“.'),
  (@b24, 14, 13, 'Tada aš tariau: „Ak, Viešpatie DIEVE! Štai pranašai jiems sako: ‘Nematysite kalavijo ir neturėsite bado, bet jums duosiu tikrą ramybę šitoje vietoje’“.'),
  (@b24, 14, 14, 'Tada VIEŠPATS man tarė: „Pranašai mano vardu pranašauja melus; aš jų nesiunčiau nei jiems įsakiau, nei jiems kalbėjau; jie jums pranašauja melagingą regėjimą ir būrimą, ir nieką, ir savo širdies suktybę.'),
  (@b24, 14, 15, 'Todėl taip sako VIEŠPATS dėl pranašų, kurie pranašauja mano vardu, nors aš jų nesiunčiau, tačiau jie sako: ‘Nebus kalavijo ir bado šitoje šalyje’, – šitie pranašai bus sunaikinti kalaviju ir badu.'),
  (@b24, 14, 16, 'O tauta, kuriems jie pranašauja, dėl bado ir kalavijo bus išmesti Jeruzalės gatvėse; ir nebus kas palaidotų juos, jų žmonas, jų sūnus ir jų dukteris; nes aš ant jų išliesiu jų nedorybę.'),
  (@b24, 14, 17, 'Todėl jiems sakyk šitą žodį: ‘Tegul mano akys plūsta ašaromis dieną bei naktį ir tenepaliauja; nes mergelė, mano tautos dukra, sulaužyta didžiule pralauža, labai smarkiu smūgiu.'),
  (@b24, 14, 18, 'Jei išeičiau ant lauko, tada štai kalavijo nužudytieji! Ir jei įeičiau į miestą, tuomet štai sergantieji nuo bado! Taip, ir pranašas, ir kunigas vaikšto po šalį, kurios jie nežino’“.'),
  (@b24, 14, 19, 'Ar tu visiškai atmetei Judą? Ar tavo siela bjaurisi Sionu? Kodėl mus sumušei, ir nėra mums išgydymo? Mes ieškojome taikos, tačiau nėra nieko gero, ir išgydymo meto, o štai neramumai!'),
  (@b24, 14, 20, 'Mes pripažįstame, o VIEŠPATIE, savo nedorybę ir savo tėvų neteisybę; nes mes prieš tave nusidėjome.'),
  (@b24, 14, 21, 'Nesibjaurėk mumis dėl savo vardo, neužtrauk negarbės savo šlovės sostui; atsimink, nesulaužyk savo sandoros su mumis.'),
  (@b24, 14, 22, 'Ar yra kas tarp pagonių tuštybių, galinčių duoti lietaus? Ar dangūs gali duoti liūčių? Argi ne tu esi tas, o VIEŠPATIE, mūsų Dieve? Todėl mes lauksime tavęs, nes tu visa tai padarei.'),
  (@b24, 15, 1, 'Tada VIEŠPATS man tarė: „Nors Mozė ir Samuelis stovėtų prieš mane, tačiau mano širdis nebūtų link šitos tautos; išvyk juos iš mano akių, ir tegul jie išeina.'),
  (@b24, 15, 2, 'Ir įvyks, jei jie tau sakys: ‘Kur mums išeiti?’ Tuomet jiems tark: ‘Taip sako VIEŠPATS: Kas paskirtas mirčiai, į mirtį, kas kalavijui – į kalaviją, kas badui – į badą, ir kas nelaisvei – į nelaisvę’.'),
  (@b24, 15, 3, 'Ir aš paskirsiu jiems keturias rūšis, – sako VIEŠPATS: – kalaviją, kad žudytų, šunis, kad draskytų, dangaus skrajūnus ir žemės žvėris, kad rytų ir naikintų.'),
  (@b24, 15, 4, 'Ir aš juos perkelsiu į visas žemės karalystes dėl Manaso, sūnaus Chezekijo, Judos karaliaus, dėl to, ką jis padarė Jeruzalėje.'),
  (@b24, 15, 5, 'Nes, kas gi gailėsis tavęs, o Jeruzale? Arba, kas tave apraudos? Arba, kas užsuks paklausti, kaip tau sekasi?'),
  (@b24, 15, 6, 'Tu mane palikai, – sako VIEŠPATS, – tu atsitraukei atgal; todėl aš ištiesiu prieš tave savo ranką ir tave sunaikinsiu; aš pavargau gailėtis.'),
  (@b24, 15, 7, 'Aš juos vėtysiu vėtykle šalies vartuose; aš atimsiu iš jų vaikus, sunaikinsiu savo tautą, kadangi jie nesugrįžta nuo savo kelių.'),
  (@b24, 15, 8, 'Man padaugėjo jų našlių daugiau negu jūros smėlio; aš užleidau ant jų, prieš jaunuolių motiną, plėšiką vidudienį; aš jam daviau staiga užpulti, ir miestą apėmė siaubas.'),
  (@b24, 15, 9, 'Pagimdžiusioji septynis nusilpo; ji atidavė dvasią; jos saulė nusileido dar tebesant dienai; ji buvo sugėdinta ir suglumusi; o jų likutį aš atiduosiu kalavijui, jų priešų akivaizdoje“, – sako VIEŠPATS.'),
  (@b24, 15, 10, 'Vargas man, mano motina, kad mane pagimdei vaidijimosi ir ginčijimosi žmogumi visai žemei! Nei aš skolinau su palūkanomis, nei man skolino su palūkanomis, tačiau jie visi keikia mane.'),
  (@b24, 15, 11, 'VIEŠPATS tarė: „Tikrai su tavo likučiu bus gerai; tikrai aš padarysiu, kad tavo priešas gerai elgsis su tavimi nelaimės metu ir sielvarto metu.'),
  (@b24, 15, 12, 'Ar gali geležis sulaužyti šiaurės geležį ir plieną?'),
  (@b24, 15, 13, 'Tavo turtą ir tavo lobius duosiu be mokesčio išplėšti už visas tavo nuodėmes visose tavo ribose.'),
  (@b24, 15, 14, 'Ir nuvesiu tave su tavo priešais į šalį, kurios nepažįsti; nes mano pyktyje užsidegė ugnis, kuri degs ant jūsų“.'),
  (@b24, 15, 15, 'O VIEŠPATIE, tu žinai; atsimink mane ir aplankyk mane, ir atkeršyk už mane mano persekiotojams; nepašalink manęs pagal savo ilgą pakantumą; žinok, kad aš dėl tavęs kenčiu barimą.'),
  (@b24, 15, 16, 'Atsirado tavo žodžiai, ir aš juos valgiau; ir tavo žodis man buvo džiaugsmas ir mano širdies džiūgavimas; nes aš vadinuosi tavo vardu, o VIEŠPATIE, kariuomenių Dieve.'),
  (@b24, 15, 17, 'Aš nesėdėjau pašaipūnų sambūryje ir nesidžiaugiau; aš sėdėjau vienišas dėl tavo rankos; nes tu pripildei mane pasipiktinimo.'),
  (@b24, 15, 18, 'Kodėl mano skausmas nuolatinis ir mano žaizda nepagydoma, nesiduodanti pagydoma? Ar tu man būsi visai kaip melagis, kaip nepatikimas vanduo?'),
  (@b24, 15, 19, 'Todėl taip sako VIEŠPATS: „Jei sugrįši, tada aš tave parvesiu, ir tu stovėsi mano akivaizdoje; ir jei išimsi tai, kas brangu, nuo to, kas bjauru, būsi kaip mano burna; tegul jie sugrįžta pas tave; bet tu nesugrįžk pas juos.'),
  (@b24, 15, 20, 'Ir aš padarysiu tave šitai tautai aptverta žalvarine siena; ir jie kovos prieš tave, bet tavęs nenugalės; nes aš esu su tavimi, kad tave išgelbėčiau ir tave išvaduočiau, – sako VIEŠPATS.'),
  (@b24, 15, 21, 'Ir aš tave išvaduosiu iš nedorėlių rankos ir tave atpirksiu iš baisiųjų rankos“.'),
  (@b24, 16, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 16, 2, '„Neimk sau žmonos ir neturėk sūnų ar dukterų šitoje vietoje.'),
  (@b24, 16, 3, 'Nes taip sako VIEŠPATS apie sūnus ir apie dukteris, gimstančius šitoje vietoje, ir apie jų motinas, juos gimdančias, ir apie jų tėvus, kurie juos pagimdo šitoje šalyje:'),
  (@b24, 16, 4, '‘Jie mirs sunkiomis mirtimis; jų neapraudos nei jų palaidos; bet jie bus kaip mėšlas ant žemės paviršiaus; ir jie bus sunaikinti kalavijo ir bado; ir jų lavonai bus maistas dangaus skrajūnams ir žemės žvėrims’“.'),
  (@b24, 16, 5, 'Nes taip sako VIEŠPATS: „Neik į gedulo namus ir neik gedėti ar jų apraudoti; nes aš atėmiau iš šitos tautos savo ramybę, – sako VIEŠPATS, – mylintį gerumą ir gailestingumus.'),
  (@b24, 16, 6, 'Tiek dideli, tiek maži mirs šitoje šalyje; jų nepalaidos ir niekas jų neapraudos, ir dėl jų nesusipjaustys, ir nesidarys plikės;'),
  (@b24, 16, 7, 'ir niekas dėl jų nesiplėšys gedėdamas, kad juos paguostų dėl mirusiojo; ir neduos jiems gerti paguodos taurės dėl jų tėvo ar dėl jų motinos.'),
  (@b24, 16, 8, 'Taip pat neik į pokylių namus, kad su jais sėdėtum valgyti ir gerti.'),
  (@b24, 16, 9, 'Nes taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Štai aš nutildysiu šitoje vietoje, jūsų akyse ir jūsų dienomis, džiaugsmo balsą ir linksmybės balsą, jaunikio balsą ir nuotakos balsą’.'),
  (@b24, 16, 10, 'Ir įvyks, kai tu paskelbsi šitai tautai visus šituos žodžius ir jie tau sakys: ‘Kodėl VIEŠPATS mums paskelbė visą šitą didelę nelaimę? Kokia yra mūsų neteisybė? Kokia mūsų nuodėmė, kuria nusidėjome prieš VIEŠPATĮ, mūsų Dievą?’'),
  (@b24, 16, 11, 'Tada jiems sakyk: ‘Kadangi jūsų tėvai paliko mane, – sako VIEŠPATS, – ir vaikščiojo paskui kitus dievus, jiems tarnavo ir juos garbino, o mane paliko ir nesilaikė mano įstatymo;'),
  (@b24, 16, 12, 'o jūs elgėtės blogiau negu jūsų tėvai; nes štai jūs kiekvienas vaikščiojate pagal savo piktos širdies sumanymą, kad manęs neklausytumėte;'),
  (@b24, 16, 13, 'todėl aš jus išmesiu iš šitos šalies į šalį, kurios nežinote nei jūs, nei jūsų tėvai; ir ten dieną bei naktį jūs tarnausite kitiems dievams; aš neparodysiu ten jums palankumo’.'),
  (@b24, 16, 14, 'Todėl, štai ateina dienos, – sako VIEŠPATS, – kai nebesakys: ‘VIEŠPATS gyvas, kuris išvedė aukštyn Izraelio vaikus iš Egipto šalies’;'),
  (@b24, 16, 15, 'bet sakys: ‘VIEŠPATS gyvas, kuris išvedė Izraelio vaikus aukštyn iš šiaurės šalies ir iš visų šalių, kur jis buvo juos išvaręs’; ir aš juos sugrąžinsiu į jų šalį, kurią daviau jų tėvams.'),
  (@b24, 16, 16, 'Štai aš pasiųsiu pas daugybę žvejų, – sako VIEŠPATS, – ir jie juos sužvejos; o paskui pasiųsiu pas daugybę medžiotojų, ir jie juos išmedžios iš kiekvieno kalno, iš kiekvienos kalvos ir iš uolų angų.'),
  (@b24, 16, 17, 'Nes mano akys nukreiptos į visus jų kelius; jie nepaslėpti nuo mano veido, ir jų neteisybė nepaslėpta nuo mano akių.'),
  (@b24, 16, 18, 'Ir pirmiausia aš dvigubai atlyginsiu už jų neteisybę ir jų nuodėmę; kadangi jie suteršė mano šalį, jie pripildė mano paveldą savo šlykštybių ir bjaurybių lavonais’“.'),
  (@b24, 16, 19, 'O VIEŠPATIE, mano stiprybe, mano tvirtove ir mano prieglobsti sielvarto dieną, pas tave ateis pagonys nuo žemės pakraščių ir sakys: ‘Tikrai mūsų tėvai buvo paveldėję melus, tuštybę ir tai, kame nėra jokios naudos’.'),
  (@b24, 16, 20, 'Ar gali žmogus pasidaryti dievų, kurie nėra dievai?'),
  (@b24, 16, 21, 'Todėl štai aš šįkart duosiu jiems pažinti, duosiu jiems pažinti savo ranką ir savo galybę; ir jie žinos, kad mano vardas yra VIEŠPATS“.'),
  (@b24, 17, 1, 'Judos nuodėmė užrašyta geležiniu rašikliu, deimantiniu raižikliu; ji įrėžta į jų širdies plokštę ir ant jūsų aukurų ragų;'),
  (@b24, 17, 2, 'kol jų vaikai prisimena jų aukurus ir jų giraites prie žaliuojančių medžių ant aukštų kalvų.'),
  (@b24, 17, 3, 'O mano kalne laukuose, aš duosiu išplėšti tavo turtą ir visus tavo lobius, ir tavo aukštumas už nuodėmę, visose tavo ribose.'),
  (@b24, 17, 4, 'O tu pats neteksi savo paveldo, kurį tau daviau; ir tave priversiu tarnauti tavo priešams šalyje, kurios nepažįsti; nes jūs mano pyktyje uždegėte ugnį, kuri degs amžinai.'),
  (@b24, 17, 5, 'Taip sako VIEŠPATS: „Tebūna prakeiktas žmogus, kuris pasitiki žmogumi ir laiko kūną savo ranka, ir kurio širdis pasitraukia nuo VIEŠPATIES.'),
  (@b24, 17, 6, 'Nes jis bus kaip viržis dykumoje ir nematys, kai ateina gera; bet gyvens išdžiūvusiose vietose tyrlaukiuose, druskingoje ir negyvenamoje šalyje.'),
  (@b24, 17, 7, 'Palaimintas žmogus, kuris pasitiki VIEŠPAČIU, kurio viltis yra VIEŠPATS.'),
  (@b24, 17, 8, 'Nes jis bus kaip medis, pasodintas prie vandenų, kuris išplečia savo šaknis prie upės, ir nematys, kai ateis kaitra, bet jo lapai bus žali; ir nesirūpins sausros metais ir nesiliaus nešęs vaisių.'),
  (@b24, 17, 9, 'Širdis apgaulingesnė už viską ir be galo nedora; kas gali ją pažinti?'),
  (@b24, 17, 10, 'Aš, VIEŠPATS, tiriu širdį, mėginu inkstus, kad kiekvienam duočiau pagal jo kelius, pagal jo darbų vaisių.'),
  (@b24, 17, 11, 'Kaip kurapka sėdi ant kiaušinių, bet jų neišperi, taip ir tas, kuris neteisėtai įsigyja turtų, juos paliks jo dienoms įpusėjus ir savo pabaigoje bus kvailys.'),
  (@b24, 17, 12, 'Šlovingas aukštas sostas nuo pradžios yra mūsų šventovės vieta.'),
  (@b24, 17, 13, 'O VIEŠPATIE, Izraelio viltie, visi, kurie palieka tave, bus sugėdinti, ir tie, kurie traukiasi nuo tavęs, bus įrašyti į žemę, nes jie paliko VIEŠPATĮ, gyvųjų vandenų šaltinį.'),
  (@b24, 17, 14, 'Pagydyk mane, o VIEŠPATIE, ir aš būsiu pagydytas; išgelbėk mane, ir aš būsiu išgelbėtas; nes tu esi mano gyrius.'),
  (@b24, 17, 15, 'Štai jie man sako: „Kur yra VIEŠPATIES žodis? Tegul jis dabar ateina“.'),
  (@b24, 17, 16, 'O aš, aš nenuskubėjau nuo buvimo ganytoju, kad sekčiau paskui tave; ir netroškau nelaimės dienos; tu žinai; kas išėjo iš mano lūpų, buvo teisinga tavo akivaizdoje.'),
  (@b24, 17, 17, 'Nebūk man išgąsčiu; tu esi mano viltis nelaimės dieną.'),
  (@b24, 17, 18, 'Tebūna suglumę mano persekiotojai, bet aš tenebūsiu suglumęs; tebūna jie sunerimę, bet aš tenebūsiu sunerimęs; užleisk ant jų nelaimės dieną ir juos sunaikink dvigubu sunaikinimu.'),
  (@b24, 17, 19, 'Taip man sako VIEŠPATS: „Eik ir atsistok tautos vaikų vartuose, pro kuriuos įeina Judos karaliai ir pro kuriuos jie išeina, ir visuose Jeruzalės vartuose;'),
  (@b24, 17, 20, 'ir jiems tark: ‘Klausykite VIEŠPATIES žodžio, Judos karaliai, visa Juda ir visi Jeruzalės gyventojai, kurie įeinate pro šituos vartus;'),
  (@b24, 17, 21, 'taip sako VIEŠPATS: ‘Saugokitės ir neneškite naštos sabato dieną, ir neįneškite jos pro Jeruzalės vartus;'),
  (@b24, 17, 22, 'ir neišneškite naštos iš savo namų sabato dieną, ir nedirbkite jokio darbo, bet pašvęskite sabato dieną, kaip įsakiau jūsų tėvams.'),
  (@b24, 17, 23, 'Tačiau jie nepakluso ir nepalenkė savo ausies, bet sukietino savo sprandą, kad negirdėtų ir nepriimtų pamokymo.'),
  (@b24, 17, 24, 'Ir įvyks, jei uoliai manęs klausysite, – sako VIEŠPATS, – ir sabato dieną neįnešite jokios naštos pro šito miesto vartus, bet pašvęsite sabato dieną, nedirbdami per jį jokio darbo,'),
  (@b24, 17, 25, 'tai pro šito miesto vartus įeis karaliai ir kunigaikščiai, sėdintys Dovydo soste, važiuojantys vežimais ir jojantys ant žirgų, jie ir jų kunigaikščiai, Judos žmonės ir Jeruzalės gyventojai; ir šitas miestas pasiliks per amžius.'),
  (@b24, 17, 26, 'Ir jie ateis iš Judos miestų, iš Jeruzalės apylinkių, iš Benjamino šalies, iš lygumos, iš kalnų ir iš pietų, atnešdami deginamąsias atnašas, aukas ir maisto atnašas, smilkalus ir atnešdami gyriaus aukas į VIEŠPATIES namus.'),
  (@b24, 17, 27, 'Bet jei manęs neklausysite, kad pašvęstumėte sabato dieną ir kad neneštumėte naštos, įeidami pro Jeruzalės vartus sabato dieną, tada aš užkursiu jos vartuose ugnį, ir ji surys Jeruzalės rūmus ir neužges’“.'),
  (@b24, 18, 1, 'Žodis, kuris atėjo iš VIEŠPATIES Jeremijui, sakydamas:'),
  (@b24, 18, 2, '„Kelkis ir eik žemyn į puodžiaus namus, ir ten tau duosiu išgirsti mano žodžius“.'),
  (@b24, 18, 3, 'Tada nuėjau žemyn į puodžiaus namus, ir štai jis dirbo darbą prie žiedžiamojo rato.'),
  (@b24, 18, 4, 'Ir indas, kurį jis padarė iš molio, puodžiaus rankoje buvo sugadintas; taigi jis vėl padarė kitą indą, kaip puodžiui atrodė tinkama padaryti.'),
  (@b24, 18, 5, 'Tada man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 18, 6, '„O Izraelio namai, ar aš negaliu su jumis padaryti, kaip šitas puodžius? – sako VIEŠPATS. – Štai kaip molis yra puodžiaus rankoje, taip ir jūs esate mano rankoje, o Izraelio namai.'),
  (@b24, 18, 7, 'Ūmai kalbėsiu apie tautą ir apie karalystę, kad ją išrausiu, nuversiu ir sunaikinsiu;'),
  (@b24, 18, 8, 'jei ta tauta, prieš kurią paskelbiau, nusisuka nuo savo piktybių, tai aš persigalvosiu dėl pikto, kurį galvojau jiems padaryti.'),
  (@b24, 18, 9, 'Ir ūmai kalbėsiu apie tautą ir apie karalystę, kad ją statysiu ir sodinsiu;'),
  (@b24, 18, 10, 'jei ji darys pikta mano akyse, nepaklusdama mano balsui, tada aš persigalvosiu dėl gero, kuriuo sakiau, kad padarysiu jiems geradarystę.'),
  (@b24, 18, 11, 'Taigi dabar sakyk Judos žmonėms ir Jeruzalės gyventojams, sakydamas: ‘Taip sako VIEŠPATS: Štai aš rengiu prieš jus pikta ir sumanau prieš jus kėslą; sugrįžkite dabar kiekvienas nuo savo pikto kelio ir gerinkite savo kelius bei savo darbus’.'),
  (@b24, 18, 12, 'Bet jie tarė: ‘Nėra vilties; mes vaikščiosime paskui savo pačių užmačias ir kiekvienas vykdysime savo piktos širdies sumanymą’.'),
  (@b24, 18, 13, 'Todėl taip sako VIEŠPATS: ‘Nagi paklauskite tarp pagonių, kas yra girdėjęs tokių dalykų; Izraelio mergelė padarė labai baisų dalyką.'),
  (@b24, 18, 14, 'Ar kas palieka Libano sniegą, krentantį nuo lauko uolos? Ar paliekami šalti iš kitos vietos atitekantys vandenys?'),
  (@b24, 18, 15, 'Kadangi mano tauta pamiršo mane, jie degino smilkalus tuštybei, jie save suklupdė savo keliuose nukrypdami nuo senų takų, kad vaikščiotų takais, nesupiltu keliu;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 18, 16, 'kad padarytų savo šalį dyką ir amžinu švilpavimu; kiekvienas pro ją praeinantis bus apstulbintas ir kraipys savo galvą.'),
  (@b24, 18, 17, 'Kaip rytų vėju aš juos išsklaidysiu priešo akivaizdoje; jiems rodysiu nugarą, o ne veidą jų nelaimės dieną’.'),
  (@b24, 18, 18, 'Tada jie tarė: ‘Ateikite, sugalvokime kėslą prieš Jeremiją; nes kunigas nepraras įstatymo, nei išminčius patarimo, nei pranašas žodžio. Ateikite, sumuškime jį liežuviu ir nekreipkime dėmesio nei į vieną jo žodį’“.'),
  (@b24, 18, 19, 'O VIEŠPATIE, atkreipk į mane dėmesį ir išgirsk balsą tų, kurie vaidijasi su manimi.'),
  (@b24, 18, 20, 'Argi atmokama piktu už gera? Nes jie iškasė duobę mano sielai. Atsimink, kad aš stovėjau tavo akivaizdoje, idant kalbėčiau gera dėl jų ir kad nukreipčiau nuo jų tavo rūstybę.'),
  (@b24, 18, 21, 'Todėl atiduok jų vaikus badui ir praliek jų kraują kalavijo galia; tegul jų žmonos netenka vaikų ir tebūna našlės; ir jų vyrai tebūna užmušti; jų jaunuoliai tebūna nužudyti kalaviju mūšyje.'),
  (@b24, 18, 22, 'Tepasigirsta šauksmas iš jų namų, kai staiga užleisi ant jų pulką; nes jie iškasė duobę, kad mane pagautų, ir paslėpė spąstus mano kojoms.'),
  (@b24, 18, 23, 'Tačiau tu, VIEŠPATIE, žinai visą jų planą prieš mane, kad mane nužudytų; neatleisk jų neteisybės ir neišdildyk jų nuodėmės iš savo akių, bet tebūna jie parblokšti tavo akivaizdoje; taip su jais elkis savo pykčio metu.'),
  (@b24, 19, 1, 'Taip sako VIEŠPATS: „Eik ir įsigyk puodžiaus molinį butelį ir pasiimk tautos senolių bei kunigų senolių;'),
  (@b24, 19, 2, 'ir išeik į Hinomo sūnaus slėnį, esantį prie rytų vartų įėjimo, ir ten paskelbk žodžius, kuriuos tau kalbėsiu,'),
  (@b24, 19, 3, 'ir sakyk: Klausykite VIEŠPATIES žodžio, o Judos karaliai ir Jeruzalės gyventojai; taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Štai aš užleisiu ant šitos vietos tokią nelaimę, kad kiekvienam, kuris išgirs apie ją, spengs jo ausyse.'),
  (@b24, 19, 4, 'Kadangi jie paliko mane ir padarė šitą vietą svetimą, ir joje degino smilkalus kitiems dievams, kurių nežinojo nei jie, nei jų tėvai, nei Judos karaliai, ir pripildė šitą vietą nekaltųjų kraujo;'),
  (@b24, 19, 5, 'taip pat jie statė Baalo aukštumas, kad degintų savo sūnus ugnimi kaip deginamąsias atnašas Baalui, ko aš neįsakiau ir nekalbėjau, ir tai man neatėjo į galvą;'),
  (@b24, 19, 6, 'todėl štai ateina dienos, – sako VIEŠPATS, – kai šitos vietos nebevadins Tofetu ar Hinomo sūnaus slėniu, bet Skerdynių slėniu.'),
  (@b24, 19, 7, 'Ir aš nieku paversiu Judos ir Jeruzalės sumanymą šitoje vietoje; ir priversiu juos kristi nuo kalavijo jų priešų akivaizdoje ir nuo rankų tų, kurie siekia jų gyvybės; ir atiduosiu jų lavonus, kad būtų maistas dangaus skrajūnams ir žemės žvėrims.'),
  (@b24, 19, 8, 'Ir aš padarysiu šitą miestą dyką ir švilpavimu: kiekvienas, praeinantis pro jį, bus apstulbintas ir švilpaus dėl visų jo rykščių.'),
  (@b24, 19, 9, 'Ir aš juos valgydinsiu jų sūnų kūnais ir jų dukterų kūnais, ir kiekvienas valgys savo draugo kūną apgultyje ir prispaudime, kuriuo juos prispaus jų priešai ir tie, kurie siekia jų gyvybės.'),
  (@b24, 19, 10, 'Paskui sudaužyk tą butelį akyse žmonių, kurie eis su tavimi,'),
  (@b24, 19, 11, 'ir jiems tark: Taip sako kariuomenių VIEŠPATS: Aš sudaužysiu šitą tautą ir šitą miestą taip, kaip sudaužomas puodžiaus indas, kurio nebepadarysi sveiku; ir jie laidos juos Tofete, kol nebebus vietos laidoti.'),
  (@b24, 19, 12, 'Taip aš padarysiu šitai vietai, – sako VIEŠPATS, – ir jos gyventojams, ir padarysiu šitą miestą kaip Tofetą;'),
  (@b24, 19, 13, 'o Jeruzalės namai ir Judos karalių namai bus suteršti kaip Tofeto vieta, dėl visų tų namų, ant kurių stogų jie degino smilkalus visai dangaus kariuomenei ir išliejo geriamąsias atnašas kitiems dievams’“.'),
  (@b24, 19, 14, 'Tada Jeremijas atėjo iš Tofeto, kur VIEŠPATS jį buvo pasiuntęs pranašauti; ir jis atsistojo VIEŠPATIES namų kieme, ir tarė visai tautai:'),
  (@b24, 19, 15, '„Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Štai aš užleisiu ant šito miesto ir ant visų jo miestų visą tą nelaimę, kurią prieš jį paskelbiau, nes jie užkietino savo sprandus, kad neklausytų mano žodžių’“.'),
  (@b24, 20, 1, 'Na, o kunigo Imero sūnus Pašhūras, kuris buvo ir vyriausias valdytojas VIEŠPATIES namuose, išgirdo, kad Jeremijas tai pranašavo.'),
  (@b24, 20, 2, 'Tada Pašhūras sumušė pranašą Jeremiją ir jį įtvėrė į trinką, buvusią aukštuosiuose Benjamino vartuose, kurie buvo prie VIEŠPATIES namų.'),
  (@b24, 20, 3, 'Ir rytojaus dieną įvyko, kad Pašhūras išleido Jeremiją iš trinkos. Tada Jeremijas jam tarė: „VIEŠPATS tave pavadino ne Pašhūru, bet Magor-Misabibu.'),
  (@b24, 20, 4, 'Nes taip sako VIEŠPATS: ‘Štai aš padarysiu tave siaubu tau pačiam ir visiems tavo draugams; ir jie kris nuo savo priešų kalavijo, o tavo akys tai matys; ir visą Judą atiduosiu į Babilono karaliaus ranką, ir jis juos išves nelaisvėn į Babiloną ir žudys juos kalaviju.'),
  (@b24, 20, 5, 'Aš dar atiduosiu visą šito miesto stiprybę, visą jo triūsą, visas jo brangenybes, ir visus Judos karalių lobius atiduosiu į rankas jų priešams, kurie juos apiplėš, pasiims ir nugabens juos į Babiloną.'),
  (@b24, 20, 6, 'O tu, Pašhūrai, ir visi gyvenantys tavo namuose, eisite į nelaisvę; ir tu ateisi į Babiloną ir ten mirsi, ir ten būsi palaidotas, tu ir visi tavo draugai, kuriems tu pranašavai melus’“.'),
  (@b24, 20, 7, 'O VIEŠPATIE, tu suklaidinai mane, ir aš buvau suklaidintas; tu stipresnis už mane ir nugalėjai; aš pajuokiamas kasdien; kiekvienas tyčiojasi iš manęs.'),
  (@b24, 20, 8, 'Nes nuo tada, kai aš kalbėjau, aš šaukiau, aš šaukiau smurtą ir plėšimą; nes VIEŠPATIES žodis man tapo priekaištu ir pajuoka kas dieną.'),
  (@b24, 20, 9, 'Tada tariau: „Apie jį nebeužsiminsiu ir nebekalbėsiu jo vardu“. Bet jo žodis mano širdyje buvo kaip deganti ugnis, uždaryta mano kauluose, ir aš nuvargau nuo susilaikymo, ir negalėjau sulaikyti.'),
  (@b24, 20, 10, 'Nes girdėjau daugelio šmeižtą, baimę iš visų pusių. „Įskųsime, – jie sako, – mes įskųsime“. Visi mano artimi draugai tykoja mano suklupimo, sakydami: „Jis gal leisis suviliojamas, ir mes jį nugalėsime ir jam atkeršysime“.'),
  (@b24, 20, 11, 'Bet VIEŠPATS yra su manimi kaip galingas ir baisusis; todėl mano persekiotojai suklups ir nenugalės; jie bus labai sugėdinti; nes jiems nesiseks; jų amžina gėda niekada nebus pamiršta.'),
  (@b24, 20, 12, 'Bet, kariuomenių VIEŠPATIE, kuris mėgini teisųjį ir matai inkstus ir širdį, leisk man pamatyti tavo kerštą jiems; nes tau aš atvėriau savo bylą.'),
  (@b24, 20, 13, 'Giedokite VIEŠPAČIUI, girkite VIEŠPATĮ; nes jis išgelbėjo vargšo sielą iš piktadarių rankos.'),
  (@b24, 20, 14, 'Prakeikta tebūna diena, kurią gimiau; diena, kurią mane pagimdė mano motina, tenebūna palaiminta.'),
  (@b24, 20, 15, 'Prakeiktas tebūna žmogus, kuris atnešė mano tėvui žinią, sakydamas: „Tau gimė vyriškos lyties vaikas“, jį labai pradžiugindamas.'),
  (@b24, 20, 16, 'Ir tebūna tas žmogus kaip miestai, kuriuos VIEŠPATS sugriovė ir nesigailėjo; tegul jis girdi šauksmą ryte ir šūkavimą vidudienį;'),
  (@b24, 20, 17, 'kadangi jis nenužudė manęs įsčiose; kad mano motina būtų buvusi mano kapas ir jos įsčios visuomet nėščios.'),
  (@b24, 20, 18, 'Kodėl išėjau iš įsčių, kad matyčiau triūsą ir sielvartą, kad mano dienos būtų prarytos gėdoje?'),
  (@b24, 21, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES, kai karalius Zedekijas siuntė pas jį Malkijos sūnų Pašhūrą ir kunigo Maasėjos sūnų Sofoniją, sakydamas:'),
  (@b24, 21, 2, '„Meldžiu tave, pasiklausk už mus VIEŠPATIES; nes Babilono karalius Nebukadrecaras kariauja prieš mus; gal VIEŠPATS elgsis su mumis pagal visus savo nuostabius darbus, kad jis eitų aukštyn nuo mūsų“.'),
  (@b24, 21, 3, 'Tada Jeremijas jiems tarė: „Taip sakykite Zedekijui:'),
  (@b24, 21, 4, 'Taip sako VIEŠPATS, Izraelio Dievas: ‘Štai aš apgręšiu karo ginklus, esančius jūsų rankose, kuriais jūs kariaujate prieš Babilono karalių ir prieš kaldėjus, jus apgulusius už sienų, ir juos surinksiu šito miesto viduryje.'),
  (@b24, 21, 5, 'Ir aš pats kariausiu prieš jus ištiesta ranka ir stipria ranka įpykęs, įtūžęs ir labai užsirūstinęs.'),
  (@b24, 21, 6, 'Ir sumušiu šito miesto gyventojus, tiek žmones, tiek gyvulius: jie mirs nuo didelio maro.'),
  (@b24, 21, 7, 'O paskui, – sako VIEŠPATS, – aš atiduosiu Judos karalių Zedekiją, jo tarnus, tautą ir išlikusius šiame mieste nuo maro, nuo kalavijo ir nuo bado, į Babilono karaliaus Nebukadrecaro ranką, į jų priešų ranką ir į ranką tų, kurie siekia jų gyvybės; ir jis juos išmuš kalavijo ašmenimis; jis jų netausos, neužjaus ir nepasigailės’.'),
  (@b24, 21, 8, 'O šitai tautai sakyk: Taip sako VIEŠPATS: ‘Štai aš jūsų akivaizdon padedu gyvenimo kelią ir mirties kelią.'),
  (@b24, 21, 9, 'Kas pasilieka šiame mieste, mirs nuo kalavijo, nuo bado ir nuo maro; bet kas išeis ir pateks pas kaldėjus, kurie jus apgulę, tas gyvens, ir jo gyvybė jam bus kaip grobis.'),
  (@b24, 21, 10, 'Nes aš nukreipiau savo veidą prieš šitą miestą dėl pikto, o ne dėl gero, – sako VIEŠPATS; – jis bus paduotas į Babilono karaliaus ranką, ir jis sudegins jį ugnimi’.'),
  (@b24, 21, 11, 'O dėl Judos karaliaus namų sakyk: ‘Klausykite VIEŠPATIES žodžio,'),
  (@b24, 21, 12, 'o Dovydo namai: Taip sako VIEŠPATS: Ryte vykdykite teismą ir išvaduokite apiplėštąjį iš engėjo rankos, kad neišsiveržtų mano įtūžis kaip ugnis ir nedegtų taip, jog niekas jo neužgesintų dėl jūsų darbų piktumo.'),
  (@b24, 21, 13, 'Štai aš esu prieš tave, o slėnio gyventoja, lygumos uola, – sako VIEŠPATS, kuri sakai: „Kas ateis žemyn prieš mus? Arba, kas įeis į mūsų buveines?“'),
  (@b24, 21, 14, 'Bet aš nubausiu jus pagal jūsų darbų vaisių, – sako VIEŠPATS, – ir užkursiu ugnį jūsų miške, ir ji prarys viską, kas yra aplinkui’“.'),
  (@b24, 22, 1, 'Taip sako VIEŠPATS: „Eik žemyn į Judos karaliaus namus ir ten kalbėk šitą žodį,'),
  (@b24, 22, 2, 'ir sakyk: ‘Klausyk VIEŠPATIES žodžio, o Judos karaliau, sėdintis Dovydo soste, tu ir tavo tarnai, ir tavo tauta, įeinantys pro šituos vartus;'),
  (@b24, 22, 3, 'taip sako VIEŠPATS: Vykdykite teismą ir teisumą, ir išvaduokite apiplėštąjį iš engėjo rankos; nedarykite skriaudos ir nedarykite prievartos nei svetimšaliui, nei našlaičiui, nei našlei ir nepraliekite nekalto kraujo šioje vietoje.'),
  (@b24, 22, 4, 'Nes jei tikrai tai vykdysite, tai pro šitų namų vartus įeis karaliai, sėdintys Dovydo soste, važiuojantys vežimais ir jojantys ant žirgų, jie, jų tarnai ir jų tauta.'),
  (@b24, 22, 5, 'Bet jei neklausysite šitų žodžių, aš prisiekiu savimi, – sako VIEŠPATS, – kad šitie namai taps tušti’“.'),
  (@b24, 22, 6, 'Nes taip VIEŠPATS sako Judos karaliaus namams: „Tu man esi Gileadas, Libano viršūnė, tačiau tikrai aš tave padarysiu dykuma, negyvenamais miestais.'),
  (@b24, 22, 7, 'Ir aš paruošiu naikintojų prieš tave, kiekvieną su savo ginklu; ir jie nukirs tavo rinktinius kedrus ir įmes juos į ugnį.'),
  (@b24, 22, 8, 'Ir daugelis tautų praeis pro šitą miestą ir kiekvienas sakys savo artimui: ‘Kodėl VIEŠPATS taip padarė šitam dideliam miestui?‘'),
  (@b24, 22, 9, 'Tada jie atsakys: ‘Kadangi jie paliko VIEŠPATIES, savo Dievo, sandorą, garbino kitus dievus ir jiems tarnavo’“.'),
  (@b24, 22, 10, 'Neverkite dėl mirusiojo ir jo neapraudokite; bet graudžiai verkite dėl to, kuris nueina; nes jis nebesugrįš ir nebematys savo gimtojo krašto.'),
  (@b24, 22, 11, 'Nes taip sako VIEŠPATS apie Judos karalių, Jozijo sūnų Šalumą, karaliavusį vietoje savo tėvo Jozijo, kuris išėjo iš šitos vietos: „Jis čia nebesugrįš,'),
  (@b24, 22, 12, 'bet mirs toje vietoje, kur jį išvedė nelaisvėn, ir šitos šalies nebematys.'),
  (@b24, 22, 13, 'Vargas tam, kuris stato savo namus neteisumu ir savo kambarius neteisybe, kuris naudojasi savo artimo tarnavimu nemokamai ir jam neduoda už jo darbą;'),
  (@b24, 22, 14, 'kuris sako: ‘Pasistatysiu plačius namus ir erdvius kambarius’, ir išsikerta langus; ir jie apkalti kedru ir nudažyti ryškiai raudonai.'),
  (@b24, 22, 15, 'Ar karaliausi dėl to, kad apsisiaubei kedru? Argi tavo tėvas nevalgė ir negėrė ir nevykdė teismo ir teisingumo, ir tada jam sekėsi?'),
  (@b24, 22, 16, 'Jis teisė vargšo ir nepasiturinčio bylą; tada jam gerai klojosi; argi ne tai reiškia pažinti mane? – sako VIEŠPATS.'),
  (@b24, 22, 17, '– Tačiau tavo akys ir tavo širdis tik tavo godumui, nekalto kraujo praliejimui, engimui bei prievartai, kad tai darytum.“'),
  (@b24, 22, 18, 'Todėl taip sako VIEŠPATS apie Judos karalių, Jozijo sūnų Jehojakimą: „Jo neapraudos, sakydami: ‘Ak, mano broli!’ Arba: ‘Ak, sese!’ Jo neapraudos, sakydami: ‘Ak, viešpatie! Ak, jo šlove!’'),
  (@b24, 22, 19, 'Jis bus palaidotas asilo laidojimu, nuvilktas ir numestas už Jeruzalės vartų“.'),
  (@b24, 22, 20, '„Eik aukštyn į Libaną ir šauk; ir pakelk savo balsą Bašane, ir šauk nuo praėjimų; nes sunaikinti visi tavo meilužiai.'),
  (@b24, 22, 21, 'Aš tau kalbėjau, kai tu klestėjai; bet tu sakei: ‘Neklausysiu’. Toks buvo tavo būdas nuo pat tavo jaunystės, jog tu nepaklusai mano balsui.'),
  (@b24, 22, 22, 'Visus tavo ganytojus suės vėjas, ir tavo meilužiai eis nelaisvėn; tikrai tada tu būsi sugėdintas ir suglumintas dėl visos savo nedorybės.'),
  (@b24, 22, 23, 'O Libano gyventojau, susisukęs lizdą kedruose, koks tu būsi maloningas, kai tave ištiks skausmai, kaip gimdančios moters skausmas!'),
  (@b24, 22, 24, 'Kaip aš gyvas, – sako VIEŠPATS, – nors Judos karalius, Jehojakimo sūnus Konijas, būtų antspaudas ant mano dešinės rankos, tai ir nuo čia tave nuplėščiau;'),
  (@b24, 22, 25, 'aš tave paduosiu į rankas tų, kurie siekia tavo gyvybės, ir į rankas tų, kurių veido tu bijai – į Babilono karaliaus Nebukadrecaro rankas ir į kaldėjų rankas.'),
  (@b24, 22, 26, 'Ir išmesiu tave bei tavo motiną, kuri tave pagimdė, į kitą šalį, kur nebuvote gimę; ir ten mirsite.'),
  (@b24, 22, 27, 'Bet į šalį, į kurią jie trokšta sugrįžti, ten nesugrįš.'),
  (@b24, 22, 28, 'Ar tas žmogus Konijas yra paniekintas, sukultas stabas? Ar jis yra indas, kuris niekam nepatinka? Kodėl jie išmesti, jis ir jo sėkla, ir įmesti į šalį, kurios nežino?'),
  (@b24, 22, 29, 'O žeme, žeme, žeme, klausyk VIEŠPATIES žodžio.'),
  (@b24, 22, 30, 'Taip sako VIEŠPATS: „Užrašykite šitą vyrą kaip bevaikį, kaip vyrą, kuriam nesiseks jo dienomis; nes nei vienam iš jo sėklos daugiau nebepavyks atsisėsti į Dovydo sostą ir valdyti Judoje“.'),
  (@b24, 23, 1, '„Vargas ganytojams, kurie naikina ir išsklaido mano ganyklos avis!“ – sako VIEŠPATS.'),
  (@b24, 23, 2, 'Todėl taip sako VIEŠPATS, Izraelio Dievas, prieš ganytojus, kurie gano mano tautą: „Jūs išsklaidėte mano kaimenę, jas išvaikėte ir jų neaplankėte; štai aš jus aplankysiu dėl jūsų darbų piktumo, – sako VIEŠPATS.'),
  (@b24, 23, 3, '– Ir surinksiu savo kaimenės likutį iš visų šalių, kur buvau jas išvaikęs, ir jas sugrąžinsiu į jų aptvarus; ir jos bus vaisingos ir dauginsis.'),
  (@b24, 23, 4, 'Ir pastatysiu joms ganytojų, kurie jas ganys; ir jos daugiau nebijos ir nebus sunerimusios, ir jų nebepritrūks“, – sako VIEŠPATS.'),
  (@b24, 23, 5, '„Štai ateina dienos, – sako VIEŠPATS, – kai aš iškelsiu Dovydui teisią Atžalą, ir Karalius karaliaus ir klestės, ir vykdys teismą ir teisingumą žemėje.'),
  (@b24, 23, 6, 'Jo dienomis Juda bus išgelbėta ir Izraelis saugiai gyvens; ir šis yra jo vardas, kuriuo jį vadins: ‘VIEŠPATS MŪSŲ TEISUMAS’.'),
  (@b24, 23, 7, 'Todėl štai ateina dienos, – sako VIEŠPATS, – kai jie nebesakys: ‘VIEŠPATS gyvas, kuris išvedė Izraelio vaikus aukštyn iš Egipto šalies’,'),
  (@b24, 23, 8, 'bet sakys: ‘VIEŠPATS gyvas, kuris išvedė aukštyn ir vedė Izraelio namų sėklą iš šiaurės šalies ir iš visų šalių’, kur buvau juos išvijęs; ir jie gyvens savo pačių šalyje“.'),
  (@b24, 23, 9, 'Mano širdis sudaužyta mano viduje dėl pranašų; dreba visi mano kaulai; esu kaip girtas žmogus ir kaip vyras, kurį įveikė vynas, dėl VIEŠPATIES ir dėl jo šventumo žodžių.'),
  (@b24, 23, 10, '„Nes šalis pilna svetimautojų; nes dėl keikimo gedi šalis; išdžiūvo gražios dykumos vietos, jų kryptis pikta ir jų jėga neteisinga.'),
  (@b24, 23, 11, 'Nes tiek pranašai, tiek kunigai susiteršę; taip, savo namuose aptikau jų nedorybę, – sako VIEŠPATS.'),
  (@b24, 23, 12, '– Todėl jų kelias jiems bus kaip slidūs keliai tamsoje; jie bus nuvaryti ir ten pargrius; nes aš užleisiu ant jų nelaimę, būtent jų aplankymo metus, – sako VIEŠPATS.'),
  (@b24, 23, 13, '– Ir Samarijos pranašuose mačiau kvailystę: jie pranašavo Baalu ir klaidino mano tautą Izraelį.'),
  (@b24, 23, 14, 'Taip pat Jeruzalės pranašuose mačiau baisų dalyką: jie svetimauja ir vaikšto melagystėse; taip pat jie sustiprina piktadarių rankas, kad niekas nesugrįžtų nuo savo nedorybės; jie visi man yra kaip Sodoma, o jos gyventojai – kaip Gomora“.'),
  (@b24, 23, 15, 'Todėl taip sako kariuomenių VIEŠPATS apie pranašus: „Štai aš juos valgydinsiu metėlėmis ir juos girdysiu tulžies vandeniu; nes iš Jeruzalės pranašų susiteršimas pasklido po visą šalį“.'),
  (@b24, 23, 16, 'Taip sako kariuomenių VIEŠPATS: „Neklausykite žodžių pranašų, kurie jums pranašauja; jie padaro jus tuščiais; jie kalba savo širdies regėjimą, o ne iš VIEŠPATIES burnos.'),
  (@b24, 23, 17, 'Jie vis sako tiems, kurie niekina mane: ‘VIEŠPATS tarė: Jūs turėsite ramybę’, ir kiekvienam, kuris vaikšto pagal savo širdies sumanymą, jie sako: ‘Neužeis ant jūsų jokia nelaimė’“.'),
  (@b24, 23, 18, 'Nes kas stovėjo VIEŠPATIES pasitarime ir pamatė bei išgirdo jo žodį? Kas įsidėmėjo jo žodį ir jį išgirdo?'),
  (@b24, 23, 19, 'Štai VIEŠPATIES viesulas išėjo įtūžęs, smarkus viesulas; jis smarkiai užgrius ant nedorėlių galvos.'),
  (@b24, 23, 20, 'VIEŠPATIES pyktis nesugrįš, kol jis nebus įvykdęs ir kol nebus atlikęs savo širdies ketinimų; paskutinėmis dienoms jūs tai tobulai suprasite.'),
  (@b24, 23, 21, 'Aš nesiunčiau šitų pranašų, tačiau jie patys bėgo; aš jiems nekalbėjau, tačiau jie pranašavo.'),
  (@b24, 23, 22, 'Bet jei jie būtų stovėję mano pasitarime ir būtų davę mano tautai išgirsti mano žodžius, tai jie būtų juos nukreipę nuo jų pikto kelio ir nuo jų darbų piktumo.'),
  (@b24, 23, 23, 'Argi esu Dievas tiktai arti, – sako VIEŠPATS, – o toli nesu Dievas?'),
  (@b24, 23, 24, 'Ar gali kas pasislėpti slaptose vietose, kad aš jo nematyčiau? – sako VIEŠPATS. – Argi ne aš pripildau dangų ir žemę? – sako VIEŠPATS.'),
  (@b24, 23, 25, '– Aš girdėjau, ką sakė pranašai, kurie mano vardu pranašauja melus, sakydami: ‘Sapnavau, sapnavau’.'),
  (@b24, 23, 26, 'Kiek ilgai tai bus širdyje pranašų, pranašaujančių melus? Taip, jie yra savo širdies apgaulės pranašai,'),
  (@b24, 23, 27, 'ketinantys padaryti, kad mano tauta pamirštų mano vardą dėl jų sapnų, kuriuos jie pasakoja kiekvienas savo artimui, kaip jų tėvai pamiršo mano vardą dėl Baalo.'),
  (@b24, 23, 28, 'Pranašas, kuris turi sapną, tepasakoja savo sapną; o kas turi mano žodį, tas tegul ištikimai kalba mano žodį. Kas yra pelai kviečiams? – sako VIEŠPATS.'),
  (@b24, 23, 29, '– Argi mano žodis nėra kaip ugnis, – sako VIEŠPATS, – ir ar jis nėra kaip kūjis, kuris sutrupina uolą?'),
  (@b24, 23, 30, 'Todėl, štai aš esu prieš pranašus, – sako VIEŠPATS, – kurie vagia mano žodžius kiekvienas iš savo artimo.'),
  (@b24, 23, 31, 'Štai aš esu prieš pranašus, – sako VIEŠPATS, – kurie naudoja savo liežuvį ir sako: ‘Jis sako’.'),
  (@b24, 23, 32, 'Štai aš prieš tuos, kurie pranašauja melagingus sapnus, – sako VIEŠPATS, – juos pasakoja ir klaidina mano tautą savo melais ir savo lengvabūdiškumu; tačiau aš jų nesiunčiau ir jiems neįsakiau; todėl jie yra visiškai nenaudingi šitai tautai“, – sako VIEŠPATS.'),
  (@b24, 23, 33, '„Ir kai šita tauta ar pranašas, ar kunigas tave paklaus, sakydami: ‘Kokia yra VIEŠPATIES našta?’, tai jiems atsakyk: ‘Kokia našta? Aš jus paliksiu’, – sako VIEŠPATS.'),
  (@b24, 23, 34, '– O pranašą, kunigą ir tautą, kurie sakys: ‘VIEŠPATIES našta’, nubausiu tą žmogų ir jo namus.'),
  (@b24, 23, 35, 'Taip sakykite kiekvienas savo artimui, kiekvienas savo broliui: ‘Ką atsakė VIEŠPATS?’ ir: ‘Ką kalbėjo VIEŠPATS?’'),
  (@b24, 23, 36, 'O VIEŠPATIES naštos nebeminėkite, nes kiekvienas žmogaus žodis bus jam našta; nes jūs iškraipėte gyvojo Dievo, kariuomenių VIEŠPATIES, mūsų Dievo, žodžius.'),
  (@b24, 23, 37, 'Taip sakyk pranašui: ‘Ką tau atsakė VIEŠPATS?’ ir: ‘Ką kalbėjo VIEŠPATS?’'),
  (@b24, 23, 38, 'Bet kadangi sakote: ‘VIEŠPATIES našta’, todėl taip sako VIEŠPATS: ‘Kadangi sakote šitą žodį: „VIEŠPATIES našta“, o aš jums siunčiau, sakydamas: Nesakykite „VIEŠPATIES našta“’,'),
  (@b24, 23, 39, 'todėl štai aš, būtent aš, jus visiškai užmiršiu ir paliksiu jus ir miestą, kurį daviau jums ir jūsų tėvams, ir išmesiu jus iš savo akivaizdos;'),
  (@b24, 23, 40, 'ir užtrauksiu ant jūsų amžiną priekaištą ir amžiną gėdą, kuri nebus pamiršta“.'),
  (@b24, 24, 1, 'VIEŠPATS man parodė, ir štai dvi figų pintinės, padėtos prieš VIEŠPATIES šventyklą, po to, kai Babilono karalius Nebukadrecaras išvedė iš Jeruzalės į nelaisvę Judos karalių, Jehojakimo sūnų Jekoniją, ir Judos kunigaikščius su dailidėmis bei kalviais ir nuvedė juos į Babiloną.'),
  (@b24, 24, 2, 'Vienoje pintinėje buvo labai gerų figų, tokių, kaip ankstyvos prinokusios figos; o kitoje pintinėje buvo labai blogų figų, tokių blogų, kurių nebegalima valgyti.'),
  (@b24, 24, 3, 'Tada VIEŠPATS man tarė: „Ką matai, Jeremijau?“ Ir aš pasakiau: „Figas; geras figas, labai geras, ir blogas, labai blogas, tokias blogas, kurių nebegalima valgyti“.'),
  (@b24, 24, 4, 'Vėl man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 24, 5, '„Taip sako VIEŠPATS, Izraelio Dievas: ‘Kaip šitas gerąsias figas aš pripažinsiu išvestuosius iš Judos į nelaisvę, kuriuos pasiunčiau jų labui iš šitos vietos į kaldėjų šalį.'),
  (@b24, 24, 6, 'Nes aš nukreipsiu į juos savo akis dėl gero, ir juos parvesiu į šitą šalį; ir juos statysiu, o ne griausiu; ir juos sodinsiu, o ne išrausiu.'),
  (@b24, 24, 7, 'Ir duosiu jiems širdį, kad mane pažintų, jog aš esu VIEŠPATS; ir jie bus mano tauta, o aš būsiu jų Dievas; nes jie sugrįš pas mane visa savo širdimi.'),
  (@b24, 24, 8, 'O kaip su blogosiomis figomis, kurios tokios blogos, kad nebegalima jų valgyti; tikrai taip sako VIEŠPATS: Taip aš paduosiu Judos karalių Zedekiją, jo kunigaikščius ir Jeruzalės likutį, pasilikusius šitoje šalyje ir gyvenančius Egipto šalyje;'),
  (@b24, 24, 9, 'ir juos atiduosiu, kad būtų perkelti į visas žemės karalystes jų pačių žalai, kad būtų gėda ir patarlė, pajuoka ir prakeikimas visose vietose, kur juos išvysiu.'),
  (@b24, 24, 10, 'Ir siųsiu tarp jų kalaviją, badą ir marą, kol jie bus išnaikinti iš šalies, kurią daviau jiems ir jų tėvams’“.'),
  (@b24, 25, 1, 'Žodis, kuris atėjo Jeremijui apie visą Judos tautą ketvirtaisiais Judos karaliaus, Jozijo sūnaus Jehojakimo, metais, kurie buvo pirmieji Babilono karaliaus Nebukadrecaro metai;'),
  (@b24, 25, 2, 'kurį pranašas Jeremijas kalbėjo visai Judos tautai ir visiems Jeruzalės gyventojams, sakydamas:'),
  (@b24, 25, 3, '„Nuo tryliktųjų Judos karaliaus, Amono sūnaus Jozijo, metų iki šios dienos, tai yra dvidešimt trejus metus, man ateidavo VIEŠPATIES žodis, ir aš jums kalbėjau, anksti keldamasis ir kalbėdamas; bet jūs neklausėte.'),
  (@b24, 25, 4, 'Ir VIEŠPATS siuntė pas jus visus savo tarnus pranašus, anksti keldamasis ir juos siųsdamas; bet jūs neklausėte ir nepalenkėte savo ausies klausyti.'),
  (@b24, 25, 5, 'Jie sakė: ‘Nagi atsigręžkite kiekvienas nuo savo pikto kelio ir nuo savo darbų piktumo ir gyvenkite šalyje, kurią VIEŠPATS davė jums ir jūsų tėvams per amžių amžius;'),
  (@b24, 25, 6, 'ir neikite paskui kitus dievus jiems tarnauti ir juos garbinti, ir nekurstykite mano pykčio savo rankų darbais; ir aš nedarysiu jums žalos’.'),
  (@b24, 25, 7, '‘Tačiau jūs neklausėte manęs, – sako VIEŠPATS; – kad kurstytumėte mano pyktį savo rankų darbais jūsų pačių žalai’.'),
  (@b24, 25, 8, 'Todėl taip sako kariuomenių VIEŠPATS: ‘Kadangi neklausėte mano žodžių,'),
  (@b24, 25, 9, 'štai aš pasiųsiu ir paimsiu visas šiaurės šeimas, – sako VIEŠPATS, – ir Babilono karalių Nebukadrecarą, mano tarną, ir juos atvesiu prieš šitą šalį, prieš jos gyventojus ir prieš visas šitas aplinkines tautas, ir juos visiškai sunaikinsiu ir juos padarysiu nuostaba ir švilpavimu, ir amžinomis dykynėmis.'),
  (@b24, 25, 10, 'Be to, aš atimsiu iš jų džiugesio balsą ir linksmybės balsą, jaunikio balsą ir nuotakos balsą, girnų garsą ir žvakės šviesą.'),
  (@b24, 25, 11, 'Ir visa šita šalis bus dykynė ir nuostaba; ir šitos tautos tarnaus Babilono karaliui septyniasdešimt metų.'),
  (@b24, 25, 12, 'Ir įvyks, kai užsibaigs septyniasdešimt metų, aš nubausiu Babilono karalių ir tą tautą už jų nedorybę, ir kaldėjų šalį, – sako VIEŠPATS, – ir ją paversiu amžina dykyne.'),
  (@b24, 25, 13, 'ir užleisiu ant tos šalies visus savo žodžius, kuriuos prieš ją paskelbiau, būtent viską, kas yra parašyta šitoje knygoje, ką Jeremijas pranašavo prieš visas tautas.'),
  (@b24, 25, 14, 'Nes ir jais apsitarnaus daugelis tautų ir didieji karaliai; ir aš jiems atmokėsiu pagal jų poelgius ir pagal jų rankų darbus’“.'),
  (@b24, 25, 15, 'Nes taip man sako VIEŠPATS, Izraelio Dievas: „Imk šito įtūžio vyno taurę iš mano rankos ir girdyk ja visas tautas, pas kurias aš tave siunčiu.'),
  (@b24, 25, 16, 'Ir jos gers, svyrinės ir bus pamišusios dėl kalavijo, kurį aš siųsiu į jų tarpą“.'),
  (@b24, 25, 17, 'Tada aš paėmiau taurę iš VIEŠPATIES rankos ir pagirdžiau visas tautas, pas kurias VIEŠPATS mane siuntė:'),
  (@b24, 25, 18, 'tai yra, Jeruzalę, Judos miestus, jos karalius ir jos kunigaikščius, kad juos padaryčiau dykyne, nuostaba, švilpavimu ir prakeikimu; kaip yra šią dieną;'),
  (@b24, 25, 19, 'Egipto karalių faraoną, jo tarnus, jo kunigaikščius, visą jo tautą;'),
  (@b24, 25, 20, 'visą susimaišiusią tautą, visus Uco šalies karalius ir visus filistinų šalies karalius, Aškeloną, Azą, Ekroną, Ašdodo likutį,'),
  (@b24, 25, 21, 'Edomą, Moabą, Amono vaikus,'),
  (@b24, 25, 22, 'visus Tyro karalius, visus Sidono karalius, už jūros esančius salų karalius,'),
  (@b24, 25, 23, 'Dedaną, Temą, Būzą, visus, esančius tolimiausiuose pakraščiuose,'),
  (@b24, 25, 24, 'visus Arabijos karalius, visus susimaišiusių tautų karalius, gyvenančius dykumoje,'),
  (@b24, 25, 25, 'visus Zimrio karalius, visus Elamo karalius, visus medų karalius,'),
  (@b24, 25, 26, 'visus šiaurės karalius, tolimuosius ir artimuosius, vieną po kito, ir visas pasaulio karalystes, esančias žemės paviršiuje; o Šešako karalius gers po jų.'),
  (@b24, 25, 27, 'Todėl tu jiems sakyk: „Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Gerkite, pasigerkite, vemkite, griūkite ir nebeatsikelkite dėl kalavijo, kurį aš siųsiu į jūsų tarpą’“.'),
  (@b24, 25, 28, 'Ir bus, jei jie nesutiks imti taurės iš tavo rankos, kad gertų, tai jiems sakyk: „Taip sako kariuomenių VIEŠPATS: Jūs tikrai gersite.'),
  (@b24, 25, 29, 'Nes štai miestui, kuris vadinamas mano vardu, aš pradedu atvesti nelaimę, ir argi jūs liksite visiškai nenubausti? Jūs neliksite nenubausti; nes aš pašauksiu kalaviją ant visų žemės gyventojų“, – sako kariuomenių VIEŠPATS.'),
  (@b24, 25, 30, 'Todėl pranašauk prieš juos visus šituos žodžius ir jiems sakyk: „VIEŠPATS riaumos iš aukštybės, iš savo šventos buveinės ištars savo balsą; jis galingai riaumos ant savo buveinės; kaip vynuogių mynėjai jis šauks prieš visus žemės gyventojus.'),
  (@b24, 25, 31, 'Triukšmas ateis iki žemės pakraščių; nes VIEŠPATS ginčijasi su tautomis, jis bylinėsis su visais kūnais; jis atiduos nedorėlius kalavijui“, – sako VIEŠPATS.'),
  (@b24, 25, 32, 'Taip sako kariuomenių VIEŠPATS: „Štai nelaimė eis iš tautos į tautą, ir didelis viesulas pakils nuo žemės pakraščių“.'),
  (@b24, 25, 33, 'Ir tą dieną VIEŠPATIES užmuštųjų bus nuo vieno žemės krašto iki kito žemės krašto; jų nei apraudos, nei surinks, nei palaidos; jie bus mėšlas ant dirvos.'),
  (@b24, 25, 34, 'Kaukite, ganytojai, ir šaukite; ir voliokitės pelenuose, kaimenės vadai; nes išsipildė jūsų skerdimo ir jūsų išsklaidymo dienos; ir jūs krisite kaip geistinas indas.'),
  (@b24, 25, 35, 'Ir ganytojams nebus kaip pabėgti, ir kaimenės vadams – kaip išsigelbėti.'),
  (@b24, 25, 36, 'Girdėsis ganytojų šauksmo balsas ir kaimenės vadų kauksmas; nes VIEŠPATS apiplėšė jų ganyklą.'),
  (@b24, 25, 37, 'Ir iškirstos taikios buveinės dėl VIEŠPATIES smarkaus pykčio.'),
  (@b24, 25, 38, 'Jis paliko savo prieglobstį kaip liūtas; nes jų šalis dyka dėl engėjo įniršio ir dėl jo smarkaus pykčio.'),
  (@b24, 26, 1, 'Judos karaliaus, Jozijo sūnaus Jehojakimo, karaliavimo pradžioje šis žodis atėjo nuo VIEŠPATIES, sakydamas:'),
  (@b24, 26, 2, '„Taip sako VIEŠPATS: ‘Atsistok VIEŠPATIES namų kieme ir kalbėk visiems Judos miestams, atėjusiems garbinti VIEŠPATIES namuose, visus žodžius, kuriuos tau įsakau jiems kalbėti; neišimk nei žodžio;'),
  (@b24, 26, 3, 'gal jie klausys ir nusisuks kiekvienas nuo savo pikto kelio, kad aš persigalvočiau dėl pikto, kurį ketinu jiems daryti dėl jų darbų piktumo.'),
  (@b24, 26, 4, 'Ir jiems sakyk: Taip sako VIEŠPATS: Jei manęs neklausysite, kad vaikščiotumėte pagal mano įstatymą, kurį pateikiau jūsų akivaizdoje,'),
  (@b24, 26, 5, 'kad klausytumėte žodžių mano tarnų pranašų, kuriuos jums siunčiau, keldamasis anksti ir juos siųsdamas, bet jūs neklausėte;'),
  (@b24, 26, 6, 'tada aš padarysiu šituos namus kaip Šilojų ir šitą miestą padarysiu prakeikimu visoms žemės tautoms’“.'),
  (@b24, 26, 7, 'Taigi kunigai, pranašai ir visa tauta girdėjo Jeremiją kalbant šituos žodžius VIEŠPATIES namuose.'),
  (@b24, 26, 8, 'Na, o kai Jeremijas baigė kalbėti viską, ką VIEŠPATS jam buvo įsakęs kalbėti visai tautai, įvyko, kad jį nutvėrė kunigai, pranašai ir visa tauta, sakydami: „Tu tikrai mirsi.'),
  (@b24, 26, 9, 'Kodėl pranašavai VIEŠPATIES vardu, sakydamas: ‘Šitie namai bus kaip Šilojus, ir šitas miestas bus tuščias, be gyventojų’?“ Ir visa tauta susirinko prieš Jeremiją VIEŠPATIES namuose.'),
  (@b24, 26, 10, 'Kai Judos kunigaikščiai išgirdo šituos dalykus, jie atėjo aukštyn iš karaliaus namų į VIEŠPATIES namus ir atsisėdo VIEŠPATIES namų Naujųjų vartų įėjime.'),
  (@b24, 26, 11, 'Tada kunigai ir pranašai kalbėjo kunigaikščiams ir visai tautai, sakydami: „Šitas vyras vertas mirties; nes jis pranašavo prieš šitą miestą, kaip jūs girdėjote savo ausimis“.'),
  (@b24, 26, 12, 'Tada Jeremijas kalbėjo visiems kunigaikščiams ir visai tautai, sakydamas: „VIEŠPATS mane siuntė pranašauti prieš šituos namus ir prieš šitą miestą visus žodžius, kuriuos girdėjote.'),
  (@b24, 26, 13, 'Taigi dabar taisykite savo kelius ir savo darbus ir pakluskite VIEŠPATIES, savo Dievo, balsui; ir VIEŠPATS persigalvos dėl nelaimės, kurią paskelbė prieš jus.'),
  (@b24, 26, 14, 'O aš, štai aš jūsų rankoje; darykite su manimi, kaip jums atrodo gera ir tinkama.'),
  (@b24, 26, 15, 'Bet tvirtai žinokite, kad jei mane užmušite, tikrai užtrauksite nekaltą kraują ant savęs, ant šito miesto ir ant jo gyventojų; nes iš tiesų VIEŠPATS mane siuntė pas jus kalbėti jums į ausis visus šituos žodžius“.'),
  (@b24, 26, 16, 'Tada kunigaikščiai ir visa tauta kalbėjo kunigams ir pranašams: „Šitas vyras nenusipelnė mirties; nes jis mums kalbėjo VIEŠPATIES, mūsų Dievo, vardu“.'),
  (@b24, 26, 17, 'Tada kai kurie iš šalies vyresniųjų atsikėlė ir kalbėjo visam tautos sambūriui, sakydami:'),
  (@b24, 26, 18, '„Morešetietis Michėjas pranašavo Judos karaliaus Chezekijo dienomis ir kalbėjo visai Judos tautai, sakydamas: ‘Taip sako kariuomenių VIEŠPATS: Sionas bus ariamas kaip laukas, ir Jeruzalė pavirs krūvomis, o namų kalnas miškuotomis aukštumomis’.'),
  (@b24, 26, 19, 'Argi Judos karalius Chezekijas ir visa Juda iš viso jį baudė mirtimi? Argi jis nebijojo VIEŠPATIES ir nemaldavo VIEŠPATIES, ir argi VIEŠPATS nepersigalvojo dėl nelaimės, kurią jis prieš juos buvo paskelbęs? Taip mes įgysime didelę blogybę savo sieloms“.'),
  (@b24, 26, 20, 'Taip pat buvo vyras, pranašaujantis VIEŠPATIES vardu, Ūrijas, sūnus Šemajo iš Kirjat-Jearimo, kuris pranašavo prieš šitą miestą ir prieš šitą šalį pagal visus Jeremijo žodžius;'),
  (@b24, 26, 21, 'o kai karalius Jehojakimas su visais savo galiūnais ir visais kunigaikščiais išgirdo jo žodžius, karalius siekė jį užmušti; bet tai išgirdęs Ūrijas išsigando ir pabėgo, ir nuėjo į Egiptą;'),
  (@b24, 26, 22, 'ir karalius Jehojakimas siuntė į Egiptą vyrus – Achboro sūnų Elnataną ir su juo kai kuriuos vyrus į Egiptą.'),
  (@b24, 26, 23, 'Ir jie išvedė Ūriją iš Egipto ir jį atvedė pas karalių Jehojakimą, kuris jį nužudė kalaviju ir numetė jo lavoną į prastųjų žmonių kapines.'),
  (@b24, 26, 24, 'Tačiau Šafano sūnaus Ahikamo ranka buvo su Jeremiju, kad jo nepaduotų į tautos rankas, jo užmušti.'),
  (@b24, 27, 1, 'Judos karaliaus, Jozijo sūnaus Jehojakimo, karaliavimo pradžioje Jeremijui atėjo nuo VIEŠPATIES šitas žodis, sakydamas:'),
  (@b24, 27, 2, '„Taip man sako VIEŠPATS: Pasidaryk pančių bei jungų ir užsidėk juos ant sprando,'),
  (@b24, 27, 3, 'ir nusiųsk juos Edomo karaliui, Moabo karaliui, amoniečių karaliui, Tyro karaliui ir Sidono karaliui per rankas pasiuntinių, atvykusių į Jeruzalę pas Judos karalių Zedekiją;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 27, 4, 'ir jiems įsakyk kalbėti savo valdovams: ‘Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Taip sakykite savo valdovams:'),
  (@b24, 27, 5, '„Aš padariau žemę, žmogų ir gyvulį, esančius ant žemės, savo didele jėga ir savo ištiesta ranka, ir tai daviau, kam tik man atrodė tinkama.'),
  (@b24, 27, 6, 'O dabar aš daviau visas šitas šalis į savo tarno Babilono karaliaus Nebukadnecaro rankas; ir lauko žvėris taipogi jam daviau, kad jam tarnautų.'),
  (@b24, 27, 7, 'Ir visos tautos tarnaus jam, jo sūnui ir jo sūnaus sūnui, kol ateis tas jo šalies laikas; ir tada daugelis tautų ir dideli karaliai juo apsitarnaus.'),
  (@b24, 27, 8, 'Ir įvyks, kad tą tautą ir karalystę, kuri netarnaus šitam Babilono karaliui Nebukadnecarui ir kuri nepalenks savo sprando po Babilono karaliaus jungu, tą tautą aš bausiu kalaviju, badu ir maru, – sako VIEŠPATS, – kol juos išnaikinsiu jo ranka.'),
  (@b24, 27, 9, 'Todėl neklausykite savo pranašų nei savo ateities būrėjų, nei savo sapnuotojų, nei savo kerėtojų, nei savo burtininkų, kurie jums kalba, sakydami: ‘Jūs netarnausite Babilono karaliui’;'),
  (@b24, 27, 10, 'nes jie jums pranašauja melą, kad jus atitolintų nuo jūsų šalies; ir kad aš jus išvaryčiau, ir jūs pražūtumėte.'),
  (@b24, 27, 11, 'Bet tautas, kurios palenks savo sprandą po Babilono karaliaus jungu ir jam tarnaus, toms aš dar leisiu pasilikti savo šalyje, – sako VIEŠPATS; ir jie įdirbs ją ir joje gyvens“’“.'),
  (@b24, 27, 12, 'Taipogi Judos karaliui Zedekijui aš kalbėjau pagal visus šituos žodžius, sakydamas: „Palenkite savo sprandus po Babilono karaliaus jungu ir tarnaukite jam bei jo tautai, ir gyvenkite.'),
  (@b24, 27, 13, 'Kodėl jums, tau ir tavo tautai, mirti nuo kalavijo, bado ir maro, kaip VIEŠPATS kalbėjo prieš tautą, kuri netarnaus Babilono karaliui?'),
  (@b24, 27, 14, 'Todėl neklausykite žodžių pranašų, kurie jums kalba, sakydami: ‘Jūs netarnausite Babilono karaliui’; nes jie jums pranašauja melą.'),
  (@b24, 27, 15, 'Nes aš jų nesiunčiau, – sako VIEŠPATS, – tačiau jie pranašauja mano vardu melą, kad aš jus išvaryčiau, ir jūs pražūtumėte, jūs ir pranašai, kurie jums pranašauja“.'),
  (@b24, 27, 16, 'Taipogi kunigams ir visai šitai tautai aš kalbėjau, sakydamas: „Taip sako VIEŠPATS: Neklausykite žodžių savo pranašų, kurie jums pranašauja, sakydami: ‘Štai VIEŠPATIES namų indai bus netrukus pargabenti atgal iš Babilono’; nes jie pranašauja jums melą.'),
  (@b24, 27, 17, 'Neklausykite jų; tarnaukite Babilono karaliui ir gyvenkite; kodėl šitas miestas turėtų pavirsti dykyne?'),
  (@b24, 27, 18, 'Bet jei jie būtų pranašai ir jei jie turėtų VIEŠPATIES žodį, tegul jie dabar užtaria prieš kariuomenių VIEŠPATĮ, kad indai, pasilikę VIEŠPATIES namuose, Judos karaliaus namuose ir Jeruzalėje, neitų į Babiloną.'),
  (@b24, 27, 19, 'Nes taip sako kariuomenių VIEŠPATS apie stulpus, apie jūrą, apie stovus ir apie likutį indų, išlikusius šiame mieste,'),
  (@b24, 27, 20, 'kurių Babilono karalius Nebukadnecaras nepaėmė, išvesdamas į nelaisvę Judos karalių, Jehojakimo sūnų Jekoniją, iš Jeruzalės į Babiloną su visais Judos bei Jeruzalės kilmingaisiais;'),
  (@b24, 27, 21, 'taip, taip sako kariuomenių VIEŠPATS, Izraelio Dievas, apie indus, išlikusius VIEŠPATIES namuose ir Judos karaliaus bei Jeruzalės namuose:'),
  (@b24, 27, 22, '‘Jie bus nugabenti į Babiloną, ir ten jie bus iki tos dienos, kai juos aplankysiu, – sako VIEŠPATS; – paskui aš juos vesiu aukštyn ir sugrąžinsiu į šitą vietą’“.'),
  (@b24, 28, 1, 'O tais pačiais metais, Judos karaliaus Zedekijo karaliavimo pradžioje, ketvirtaisiais metais, penktąjį mėnesį įvyko, kad Azūro sūnus Hananija, pranašas, kilęs iš Gibeono, kalbėjo man VIEŠPATIES namuose kunigų ir visos tautos akivaizdoje, sakydamas:'),
  (@b24, 28, 2, '„Taip kalba kariuomenių VIEŠPATS, Izraelio Dievas, sakydamas: ‘Aš sulaužiau Babilono karaliaus jungą.'),
  (@b24, 28, 3, 'Per pilnus dvejus metus aš sugrąžinsiu į šitą vietą visus VIEŠPATIES namų indus, kuriuos Babilono karalius Nebukadnecaras paėmė iš šitos vietos ir nugabeno į Babiloną;'),
  (@b24, 28, 4, 'ir Judos karalių, Jehojakimo sūnų Jekoniją, su visais Judos belaisviais, nuėjusiais į Babiloną, aš sugrąžinsiu į šitą vietą, – sako VIEŠPATS; – nes aš sulaužysiu Babilono karaliaus jungą’“.'),
  (@b24, 28, 5, 'Tada pranašas Jeremijas tarė pranašui Hananijai, akivaizdoje kunigų ir akivaizdoje visos tautos, stovinčių VIEŠPATIES namuose;'),
  (@b24, 28, 6, 'pranašas Jeremijas tarė: „Amen; taip tepadaro VIEŠPATS; teįvykdo VIEŠPATS tavo žodžius, kuriuos pranašavai, kad pargabentų VIEŠPATIES namų indus ir visus išvestus nelaisvėn iš Babilono į šitą vietą.'),
  (@b24, 28, 7, 'Tačiau dabar klausykis šito žodžio, kurį aš kalbu tau į ausis ir visai tautai į ausis:'),
  (@b24, 28, 8, 'Pranašai, buvusieji pirma manęs ir pirma tavęs nuo seno, pranašavo prieš daugelį šalių ir prieš dideles karalystes apie karą, nelaimę ir marą.'),
  (@b24, 28, 9, 'Pranašas, kuris pranašauja apie taiką, kai to pranašo žodis išsipildo, tai tas pranašas žinomas, kad VIEŠPATS tikrai jį siuntė“.'),
  (@b24, 28, 10, 'Tada pranašas Hananija nuėmė jungą nuo pranašo Jeremijo kaklo ir jį sulaužė.'),
  (@b24, 28, 11, 'Ir Hananija kalbėjo visos tautos akivaizdoje, sakydamas: „Taip sako VIEŠPATS: Taip per pilnus dvejus metus aš sulaužysiu Babilono karaliaus Nebukadnecaro jungą nuo visų tautų sprando“. Ir pranašas Jeremijas nuėjo sau.'),
  (@b24, 28, 12, 'Kai pranašas Hananija buvo sulaužęs jungą nuo pranašo Jeremijo sprando, tada Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 28, 13, '„Eik ir kalbėk Hananijai, sakydamas: ‘Taip sako VIEŠPATS: Tu sulaužei medinius jungus; bet tu jiems padarysi geležinius jungus.'),
  (@b24, 28, 14, 'Nes taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Aš uždėjau geležinį jungą ant visų šitų tautų sprando, kad jos tarnautų Babilono karaliui Nebukadnecarui; ir jos jam tarnaus; taip pat jam daviau lauko žvėris’“.'),
  (@b24, 28, 15, 'Tada pranašas Jeremijas tarė pranašui Hananijai: „Dabar klausyk, Hananija: VIEŠPATS tavęs nesiuntė; bet tu darai, kad šita tauta pasitikėtų melu.'),
  (@b24, 28, 16, 'Todėl taip sako VIEŠPATS: ‘Štai aš tave numesiu nuo žemės paviršiaus; šiais metais tu mirsi, nes mokei maištauti prieš VIEŠPATĮ!’“'),
  (@b24, 28, 17, 'Taigi pranašas Hananija mirė tų pačių metų septintą mėnesį.'),
  (@b24, 29, 1, 'Na, o šitie yra žodžiai laiško, kurį pranašas Jeremijas nusiuntė iš Jeruzalės vyriausiųjų likučiui, išvestam į nelaisvę, ir kunigams, pranašams ir visai tautai, kuriuos Nebukadnecaras buvo išvedęs nelaisvėn iš Jeruzalės į Babiloną'),
  (@b24, 29, 2, '(po to, kai karalius Jekonijas, karalienė, eunuchai, Judos ir Jeruzalės kunigaikščiai, dailidės ir kalviai buvo išėję iš Jeruzalės);'),
  (@b24, 29, 3, 'per ranką Šafano sūnaus Eleaso ir Hilkijo sūnaus Gemarijos (kuriuos Judos karalius Zedekijas siuntė pas Babilono karalių Nebukadnecarą į Babiloną), sakydamas:'),
  (@b24, 29, 4, '„Taip sako kariuomenių VIEŠPATS, Izraelio Dievas, visiems išvestiems į nelaisvę, kuriuos daviau išvesti iš Jeruzalės į Babiloną:'),
  (@b24, 29, 5, '‘Statykite namus ir gyvenkite juose; sodinkite sodus ir valgykite jų vaisių;'),
  (@b24, 29, 6, 'imkite žmonų, gimdykite sūnus bei dukteris; imkite savo sūnums žmonų, o savo dukteris leiskite už vyrų, kad jos pagimdytų sūnų ir dukterų; kad ten daugėtumėte, o ne mažėtumėte.'),
  (@b24, 29, 7, 'Siekite ramybės tam miestui, į kurį daviau jus išvesti nelaisvėn, ir melskitės už jį VIEŠPAČIUI; nes jo ramybėje jūs turėsite ramybę’.'),
  (@b24, 29, 8, 'Nes taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Tegul jūsų nesuklaidina jūsų pranašai ir jūsų ateities būrėjai, esantys tarp jūsų, ir neklausykite savo sapnų, kurie jums sapnuojasi.'),
  (@b24, 29, 9, 'Nes jie melagingai jums pranašauja mano vardu; aš jų nesiunčiau‘ – sako VIEŠPATS.'),
  (@b24, 29, 10, 'Nes taip sako VIEŠPATS: ‘Kai Babilone sueis septyniasdešimt metų, aš jus aplankysiu ir jums įvykdysiu savo gerąjį žodį, sugrąžindamas jus į šitą vietą.'),
  (@b24, 29, 11, 'Nes aš žinau mintis, kuriomis mąstau apie jus, – sako VIEŠPATS, – mintis apie ramybę, o ne apie pikta, kad jums duočiau laukiamą pabaigą.'),
  (@b24, 29, 12, 'Tada šauksitės manęs ir eisite, ir man melsitės, ir aš jus išklausysiu.'),
  (@b24, 29, 13, 'Ir manęs ieškosite ir mane rasite, kai visa savo širdimi manęs ieškosite.'),
  (@b24, 29, 14, 'Ir aš būsiu jūsų randamas, – sako VIEŠPATS; – ir nukreipsiu jūsų nelaisvę ir surinksiu jus iš visų tautų ir iš visų vietų, kur buvau jus išvijęs, – sako VIEŠPATS, – ir jus parvesiu į vietą, iš kurios daviau jus išvesti į nelaisvę.'),
  (@b24, 29, 15, 'Kadangi sakėte: „VIEŠPATS mums prikėlė pranašų Babilone“;'),
  (@b24, 29, 16, 'žinokite, kad taip VIEŠPATS sako apie karalių, sėdintį Dovydo soste ir apie visą tautą, gyvenančią šiame mieste, apie jūsų brolius, neišėjusius su jumis į nelaisvę;'),
  (@b24, 29, 17, 'taip sako kariuomenių VIEŠPATS: Štai aš siųsiu ant jų kalaviją, badą ir marą ir padarysiu juos tokius, kaip šlykščios figos, kurios tokios blogos, kad negalima jų valgyti.'),
  (@b24, 29, 18, 'Ir persekiosiu juos kalaviju, badu ir maru, ir atiduosiu juos, kad būtų perkelti į visas žemės karalystes būti prakeikimu, nuostaba, švilpavimu ir gėda tarp visų tautų, į kurias juos būsiu išvijęs;'),
  (@b24, 29, 19, 'kadangi jie neklausė mano žodžių, – sako VIEŠPATS, – kuriuos jiems siunčiau per savo tarnus pranašus, anksti keldamas ir juos siųsdamas; bet jūs nenorėjote klausyti, – sako VIEŠPATS.'),
  (@b24, 29, 20, '– Todėl klausykite VIEŠPATIES žodžio jūs, visi nelaisvėje, kuriuos siunčiau iš Jeruzalės į Babiloną’;'),
  (@b24, 29, 21, 'taip kariuomenių VIEŠPATS, Izraelio Dievas, sako apie Kolajo sūnų Ahabą ir apie Maasėjo sūnų Zedekiją, pranašaujančius jums melą mano vardu: ‘Štai aš juos atiduosiu į Babilono karaliaus Nebukadrecaro rankas; ir jis juos nužudys jūsų akyse;'),
  (@b24, 29, 22, 'ir apie juos imsis prakeikimo visi Judos belaisviai, esantys Babilone, sakydami: „VIEŠPATS tau tepadaro kaip Zedekijui ir kaip Ahabui, kuriuos Babilono karalius iškepė ugnyje“;'),
  (@b24, 29, 23, 'nes jie darė piktadarybę Izraelyje, svetimavo su savo artimų žmonomis ir mano vardu kalbėjo melagingus žodžius, kurių nebuvau jiems įsakęs; aš žinau ir esu liudytojas, – sako VIEŠPATS’“.'),
  (@b24, 29, 24, 'Ir taip kalbėk nehelamiečiui Šemajui, sakydamas:'),
  (@b24, 29, 25, '„Taip kalba kariuomenių VIEŠPATS, Izraelio Dievas, sakydamas: Kadangi tu siuntei savo vardu laiškus visai tautai, esančiai Jeruzalėje, Maasėjo sūnui kunigui Sofonijui ir visiems kunigams, sakydamas:'),
  (@b24, 29, 26, '‘VIEŠPATS tave paskyrė kunigu vietoje kunigo Jehojados, kad būtumėte pareigūnais VIEŠPATIES namuose dėl kiekvieno pamišėlio ir laikančio save pranašu, kad jį pasodintum į kalėjimą ir įtvertum į trinką.'),
  (@b24, 29, 27, 'Taigi kodėl dabar nesubarei Jeremijo iš Anatoto, kuris laiko save pranašu jums?'),
  (@b24, 29, 28, 'Nes todėl jis siuntė mums į Babiloną, sakydamas: Ši nelaisvė ilga; statykitės namus ir gyvenkite juose; sodinkite sodus ir valgykite jų vaisių’“.'),
  (@b24, 29, 29, 'Ir kunigas Sofonijas perskaitė šitą laišką pranašui Jeremijui į ausis.'),
  (@b24, 29, 30, 'Tada Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 29, 31, '„Pasiųsk visiems belaisviams, sakydamas: ‘Taip sako VIEŠPATS apie nehelamietį Šemają: Kadangi Šemajas jums pranašavo, nors aš jo nesiunčiau, ir padarė, kad jūs pasitikėtumėte melu;'),
  (@b24, 29, 32, 'todėl taip sako VIEŠPATS: Štai aš nubausiu nehelamietį Šemają ir jo sėklą: jis neturės nei vieno, kuris gyventų tarp šitos tautos; ir jis nematys gero, kurį aš padarysiu savo tautai, – sako VIEŠPATS; – nes jis mokė maištauti prieš VIEŠPATĮ’“.'),
  (@b24, 30, 1, 'Žodis, kuris atėjo iš VIEŠPATIES Jeremijui, sakydamas:'),
  (@b24, 30, 2, '„Taip kalba VIEŠPATS, Izraelio Dievas, sakydamas: ‘Užsirašyk į knygą visus žodžius, kuriuos tau kalbėjau.'),
  (@b24, 30, 3, 'Nes štai ateina dienos, – sako VIEŠPATS, – kai sugrąžinsiu savo tautą Izraelį ir Judą iš nelaisvės, – sako VIEŠPATS, – ir juos sugrąžinsiu į šalį, kurią daviau jų tėvams, ir jie ją pasisavins’“.'),
  (@b24, 30, 4, 'Ir šitie yra žodžiai, kuriuos VIEŠPATS kalbėjo apie Izraelį ir apie Judą.'),
  (@b24, 30, 5, 'Nes taip sako VIEŠPATS: „Mes girdėjome drebėjimo, baimės, o ne taikos balsą.'),
  (@b24, 30, 6, 'Klauskite gi ir pažiūrėkite, ar vyras gali gimdyti? Kodėl matau kiekvieną vyrą su rankomis ant strėnų kaip gimdančiąją, ir kiekvienas veidas išblyškęs?'),
  (@b24, 30, 7, 'O varge! Nes didi ta diena, nėra jai lygios; tai Jokūbo vargo laikas; tačiau jis bus išgelbėtas iš jo.'),
  (@b24, 30, 8, 'Nes tą dieną atsitiks, – sako kariuomenių VIEŠPATS, – kad aš sulaužysiu jo jungą nuo jo sprando ir sutraukysiu jo pančius, ir svetimšaliai juo daugiau neapsitarnaus;'),
  (@b24, 30, 9, 'bet jie tarnaus VIEŠPAČIUI, savo Dievui, ir Dovydui, savo karaliui, kurį jiems prikelsiu.'),
  (@b24, 30, 10, 'Todėl nebijok, o mano tarne Jokūbai, – sako VIEŠPATS, – ir nesunerimk, o Izraeli; nes štai aš tave išgelbėsiu iš toli ir tavo sėklą iš jų nelaisvės šalies; ir Jokūbas sugrįš ir ilsėsis, ir bus ramus, ir niekas jo negąsdins.'),
  (@b24, 30, 11, 'Nes aš esu su tavimi, – sako VIEŠPATS, – kad tave išgelbėčiau; nors padarysiu visišką galą visoms tautoms, po kurias tave išsklaidžiau, tačiau tau nepadarysiu visiško galo; bet saikingai tave pabausiu ir nepaliksiu tavęs visai nenubausto“.'),
  (@b24, 30, 12, 'Nes taip sako VIEŠPATS: „Tavo sumušimas nepagydomas, sunki tavo žaizda.'),
  (@b24, 30, 13, 'Nėra kas gintų tavo bylą, kad būtum aptvarstytas; tu neturi gydomųjų vaistų.'),
  (@b24, 30, 14, 'Visi tavo meilužiai pamiršo tave; jie neieško tavęs; nes aš sužeidžiau tave priešo žaizda, žiauriojo baudimu, dėl tavo neteisybių daugybės; nes padaugėjo tavo nuodėmių.'),
  (@b24, 30, 15, 'Kodėl šauki dėl savo sužalojimo? Tavo sielvartas nepagydomas dėl tavo neteisybių daugybės; kadangi padaugėjo tavo nuodėmių, aš tau tai padariau.'),
  (@b24, 30, 16, 'Todėl visi, kurie tave ryja, bus suryti; ir visi tavo priešininkai, visi iki vieno, eis į nelaisvę; tie, kurie tave apiplėšia, bus apiplėšti, ir visus, kurie grobia iš tavęs, atiduosiu kaip grobį.'),
  (@b24, 30, 17, 'Nes aš atstatysiu tau sveikatą ir tave išgydysiu nuo tavo žaizdų, – sako VIEŠPATS; – nes jie vadino tave Atstumtuoju, sakydami: ‘Tai Sionas, kurio niekas neieško’“.'),
  (@b24, 30, 18, 'Taip sako VIEŠPATS: „Štai aš sugrąžinsiu Jokūbo palapinių nelaisvę ir pasigailėsiu jo gyvenviečių; ir miestas bus pastatytas ant savo krūvos, o rūmai išliks kaip įprasta.'),
  (@b24, 30, 19, 'Iš jų sklis padėka ir balsas tų, kurie linksminasi; aš juos padauginsiu, ir jų nebus keletas; ir juos pašlovinsiu, ir jie nebus menki.'),
  (@b24, 30, 20, 'Ir jų vaikai bus kaip anksčiau, ir jų susirinkimas bus įtvirtintas mano akivaizdoje, ir aš nubausiu visus jų engėjus.'),
  (@b24, 30, 21, 'Jų kilmingieji bus iš jų pačių ir jų valdovas kils iš jų tarpo; aš jį priartinsiu, ir jis prisiartins prie manęs; nes kas gi patrauktų savo širdį artintis prie manęs? – sako VIEŠPATS.'),
  (@b24, 30, 22, '– Ir jūs būsite mano tauta, o aš būsiu jūsų Dievas“.'),
  (@b24, 30, 23, 'Štai išeina įtūžęs VIEŠPATIES viesulas, nenustojantis sūkurys; jis skaudžiai užgrius ant nedorėlių galvos.'),
  (@b24, 30, 24, 'Smarkus VIEŠPATIES pyktis nesugrįš, kol jis to neatliks ir kol neįvykdys savo širdies ketinimų; paskutinėmis dienomis jūs tai suprasite.'),
  (@b24, 31, 1, '„Tuo metu, – sako VIEŠPATS, – aš būsiu visų Izraelio šeimų Dievas, ir jos bus mano tauta.'),
  (@b24, 31, 2, 'Taip sako VIEŠPATS: ‘Tauta, išlikusi nuo kalavijo, rado malonę dykumoje, būtent Izraelis, kai aš ėjau duoti jam poilsį.'),
  (@b24, 31, 3, 'Nuo seno man pasirodė VIEŠPATS, sakydamas: ‘Taip, amžina meile tave pamilau; todėl su mylinčiu gerumu pritraukiau tave.'),
  (@b24, 31, 4, 'Aš vėl tave statysiu, ir tu būsi pastatyta, o Izraelio mergele; tu vėl pasipuoši savo būgneliais ir išeisi besilinksminančiųjų šokiuose.'),
  (@b24, 31, 5, 'Tu vėl sodinsi vynuogynus Samarijos kalnuose; sodintojai sodins ir valgys juos kaip įprastus dalykus.'),
  (@b24, 31, 6, 'Nes bus diena, kai šauks sargai ant Efraimo kalno: Kelkitės, eikime aukštyn į Sioną pas VIEŠPATĮ, mūsų Dievą’“.'),
  (@b24, 31, 7, 'Nes taip sako VIEŠPATS: „Linksmai giedokite dėl Jokūbo ir šaukite tarp tautų vyriausiųjų; skelbkite, girkite ir sakykite: ‘O VIEŠPATIE, išgelbėk savo tautą, Izraelio likutį’.'),
  (@b24, 31, 8, 'Štai aš juos parvesiu iš šiaurės šalies ir surinksiu juos nuo žemės pakraščių, o kartu su jais – aklus ir raišus, nėščias ir gimdančias; čia sugrįš didžiulė minia.'),
  (@b24, 31, 9, 'Jie ateis verkdami, ir aš su maldavimais juos vesiu; juos vesiu prie vandens upių tiesiu keliu, kuriame jie nesuklups; nes aš esu tėvas Izraeliui, o Efraimas yra mano pirmagimis“.'),
  (@b24, 31, 10, 'Klausykite VIEŠPATIES žodžio, o tautos, ir skelbkite jį tolimiausiose salose, ir sakykite: „Kas išsklaidė Izraelį, tas jį surinks ir jį saugos, kaip ganytojas savo kaimenę“.'),
  (@b24, 31, 11, 'Nes VIEŠPATS atpirko Jokūbą ir jį išpirko iš stipresniojo už jį rankos.'),
  (@b24, 31, 12, 'Todėl jie ateis ir giedos Siono aukštybėje, ir suplauks kartu į VIEŠPATIES gerumą dėl kviečių, dėl vyno ir dėl aliejaus, ir dėl kaimenių bei bandų jauniklių; ir jų siela bus kaip drėkinamas sodas; ir jie daugiau visiškai nesielvartaus.'),
  (@b24, 31, 13, 'Tada džiūgaus mergelė šokdama, tiek jaunuoliai, tiek seniai kartu; nes aš paversiu jų gedulą džiaugsmu, juos paguosiu ir pradžiuginsiu nuo jų sielvarto.'),
  (@b24, 31, 14, 'Ir pasotinsiu kunigų sielas riebalais, ir mano tauta bus pasotinta mano gerumu“, – sako VIEŠPATS.'),
  (@b24, 31, 15, 'Taip sako VIEŠPATS: „Ramoje girdėjosi balsas, rauda, kartus verksmas; Rachelė verkia savo vaikų, nesileidžia guodžiama dėl savo vaikų, nes jų nebėra“.'),
  (@b24, 31, 16, 'Taip sako VIEŠPATS: „Sulaikyk savo balsą nuo verksmo ir savo akis nuo ašarų, nes tavo darbas bus atlygintas, – sako VIEŠPATS; – ir jie sugrįš iš priešo šalies.'),
  (@b24, 31, 17, 'Tavo pabaigoje yra viltis, – sako VIEŠPATS, – kad tavo vaikai sugrįš į savo ribas.'),
  (@b24, 31, 18, 'Aš tikrai girdėjau Efraimą taip save apraudant: ‘Tu nubaudei mane, ir buvau nubaustas kaip jautis, nepripratęs prie jungo; nukreipk mane, ir būsiu nukreiptas; nes tu esi VIEŠPATS, mano Dievas.'),
  (@b24, 31, 19, 'Tikrai, kai buvau nukreiptas, aš atgailavau; ir po to, kai buvau pamokytas, mušiau sau per šlaunį; aš gėdijausi, taip, sarmatijausi, nes nešiojau savo jaunystės gėdą’.'),
  (@b24, 31, 20, 'Ar Efraimas yra mano brangus sūnus? Ar jis mielas vaikas? Nes nuo tada, kai prieš jį kalbėjau, nuoširdžiai jį vis prisimenu; todėl mano viduriai nerimauja dėl jo; aš tikrai jo pasigailėsiu“, – sako VIEŠPATS.'),
  (@b24, 31, 21, 'Pasistatyk kelrodžių, pasidaryk aukštų krūvų; nukreipk savo širdį į vieškelį – į kelią, kuriuo ėjai; atsigręžk, o Izraelio mergele, atsigręžk į šituos savo miestus.'),
  (@b24, 31, 22, 'Kaip ilgai vaikštinėsi, o atsimetėle dukra? Nes VIEŠPATS sutvėrė naują dalyką žemėje: moteris apglėbs vyrą.'),
  (@b24, 31, 23, 'Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: „Jie dar sakys šitą kalbą Judos šalyje ir jos miestuose, kai aš sugrąžinsiu jų nelaisvę: ‘VIEŠPATS telaimina tave, o teisingumo buveine; šventumo kalne’.'),
  (@b24, 31, 24, 'Ir pačioje Judoje ir visuose jos miestuose gyvens drauge artojai ir tie, kurie išeina su kaimenėmis.'),
  (@b24, 31, 25, 'Nes aš pasotinau nuvargusią sielą ir kiekvieną liūdną sielą pripildžiau“.'),
  (@b24, 31, 26, 'Tame aš pabudau ir žiūrėjau; ir mano miegas man buvo saldus.'),
  (@b24, 31, 27, '„Štai ateina dienos, – sako VIEŠPATS, – kai aš apsėsiu Izraelio namus ir Judos namus žmonių sėkla ir gyvulių sėkla.'),
  (@b24, 31, 28, 'Ir įvyks, kad, kaip aš budėjau prie jų, kad išraučiau, nuversčiau, sugriaučiau, sunaikinčiau ir kamuočiau, taip budėsiu prie jų, kad statyčiau ir sodinčiau, – sako VIEŠPATS.'),
  (@b24, 31, 29, '– Tomis dienomis jie nebesakys: ‘Tėvai valgė rūgščių vynuogių, o vaikų dantys atšipę’.'),
  (@b24, 31, 30, 'Bet kiekvienas mirs už savo paties neteisybę; kiekvienas, kuris valgo rūgščias vynuoges, to dantys atšips.'),
  (@b24, 31, 31, 'Štai ateina dienos, – sako VIEŠPATS, – kai sudarysiu su Izraelio namais ir su Judos namais naują sandorą:'),
  (@b24, 31, 32, 'ne tokią sandorą, kokią sudariau su jų tėvais tą dieną, kai juos paėmiau už rankos, kad juos išvesčiau iš Egipto šalies; jie sulaužė tą mano sandorą, nors aš buvau jiems vyras, – sako VIEŠPATS; –'),
  (@b24, 31, 33, 'bet šita bus sandora, kurią sudarysiu su Izraelio namais: po tų dienų, – sako VIEŠPATS, – aš įdėsiu savo įstatymą į jų vidų ir įrašysiu jį į jų širdis; ir būsiu jų Dievas, o jie bus mano tauta.'),
  (@b24, 31, 34, 'Ir jie nei vienas nebemokys savo artimo ir nei vienas savo brolio, sakydami: ‘Pažink VIEŠPATĮ’; nes jie visi mane pažins, nuo jų mažiausiojo iki jų didžiausiojo, – sako VIEŠPATS, – nes aš atleisiu jų neteisybę ir jų nuodėmės nebeatsiminsiu.'),
  (@b24, 31, 35, 'Taip sako VIEŠPATS, kuris duoda saulę, kad būtų šviesa dieną, o mėnulio ir žvaigždžių potvarkius, kad būtų šviesa naktį, kuris padalija jūrą, kai šniokščia jos bangos; kariuomenių VIEŠPATS yra jo vardas:'),
  (@b24, 31, 36, 'jei šitie potvarkiai pasitrauks iš mano akivaizdos, – sako VIEŠPATS, – tai ir Izraelio sėkla paliaus būti tauta mano akivaizdoje per amžius.'),
  (@b24, 31, 37, 'Taip sako VIEŠPATS: ‘Jei būtų galima išmatuoti dangų aukštai ir ištirti žemės pamatus žemai, tai ir aš atmesčiau visą Izraelio sėklą už viską, ką jie yra padarę, – sako VIEŠPATS.'),
  (@b24, 31, 38, '– Štai ateina dienos, – sako VIEŠPATS, – kai miestas bus pastatytas VIEŠPAČIUI nuo Hananelio bokšto iki Kampo vartų.'),
  (@b24, 31, 39, 'Ir matavimo virvė eis toliau priešais į Garebo kalvą ir pasuks į Goją.'),
  (@b24, 31, 40, 'Ir visas lavonų bei pelenų slėnis ir visi laukai iki Kidrono upelio, iki Žirgų vartų kampo rytų link, bus šventa VIEŠPAČIUI; tai nebebus raunama ir griaunama per amžius“.'),
  (@b24, 32, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES dešimtaisiais Judos karaliaus Zedekijo metais, kurie buvo aštuonioliktieji Nebukadrecaro metai.'),
  (@b24, 32, 2, 'Nes tada Babilono karaliaus kariuomenė apgulė Jeruzalę; o pranašas Jeremijas buvo uždarytas kalėjimo kieme, esančiame Judos karaliaus namuose.'),
  (@b24, 32, 3, 'Nes Judos karalius Zedekijas jį uždarė, sakydamas: „Kodėl tu pranašauji ir sakai: ‘Taip sako VIEŠPATS: Štai aš duosiu šitą miestą į Babilono karaliaus rankas, ir jis jį paims;'),
  (@b24, 32, 4, 'ir Judos karalius Zedekijas nepaspruks iš kaldėjų rankų, bet tikrai bus atiduotas į Babilono karaliaus rankas ir kalbės su juo burna į burną, ir jo akys matys jo akis;'),
  (@b24, 32, 5, 'ir jis nuves Zedekiją į Babiloną, ir ten jis bus, kol jį aplankysiu, – sako VIEŠPATS; – nors jūs ir kovosite su kaldėjais, jums nesiseks’?“'),
  (@b24, 32, 6, 'Ir Jeremijas tarė: „Man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 32, 7, '‘Štai Hanamelis, tavo dėdės Šalumo sūnus, ateis pas tave ir sakys: Pirk mano lauką, esantį Anatote, nes tu turi atpirkimo teisę jį pirkti’.'),
  (@b24, 32, 8, 'Taigi Hanamelis, mano dėdės sūnus, atėjo pas mane pagal VIEŠPATIES žodį į kalėjimo kiemą ir man tarė: ‘Pirk, meldžiu tave, mano lauką, esantį Anatote, kuris yra Benjamino šalyje; nes tu turi teisę paveldėti ir atpirkti; nusipirk jį’; tada aš žinojau, kad tai buvo VIEŠPATIES žodis.'),
  (@b24, 32, 9, 'Ir aš nupirkau iš savo dėdės sūnaus Hanamelio lauką, esantį Anatote, ir jam atsvėriau pinigus – septyniolika šekelių sidabro.'),
  (@b24, 32, 10, 'Pasirašiau įrodymą, užantspaudavau jį, paėmiau liudytojus ir jam atsvėriau sidabrą ant svarstyklių.'),
  (@b24, 32, 11, 'Taigi paėmiau pirkimo įrodymą – tiek užantspauduotąjį pagal įstatymą ir paprotį, tiek atvirąjį;'),
  (@b24, 32, 12, 'ir padaviau pirkimo įrodymą Maasėjo sūnaus Nerijo sūnui Baruchui, matant mano dėdės sūnui Hanameliui ir akivaizdoje liudytojų, pasirašiusių pirkimo knygą, prieš visus žydus, sėdinčius kalėjimo kieme.'),
  (@b24, 32, 13, 'Ir jų akivaizdoje įpareigojau Baruchą, sakydamas:'),
  (@b24, 32, 14, '‘Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: „Imk šituos įrodymus, šitą pirkimo įrodymą, tiek užantspauduotąjį, tiek šitą atvirąjį įrodymą; ir įdėk juos į molinį indą, kad jie išliktų daug dienų“.'),
  (@b24, 32, 15, 'Nes taip sako kariuomenių VIEŠPATS, Izraelio Dievas: „Namai, laukai ir vynuogynai vėl bus įsigijami šitoje šalyje“’.'),
  (@b24, 32, 16, 'Na, o atidavęs pirkimo įrodymą Nerijo sūnui Baruchui, aš meldžiausi VIEŠPAČIUI, sakydamas:'),
  (@b24, 32, 17, '‘Ak, Viešpatie DIEVE! Štai tu padarei dangų ir žemę savo didele jėga ir ištiesta ranka, ir nieko tau nėra per sunkaus;'),
  (@b24, 32, 18, 'tu rodai mylintį gerumą tūkstančiams ir už tėvų neteisybę atmoki į užantį jų vaikams po jų; Didis, Galingasis Dievas, kariuomenių VIEŠPATS yra jo vardas,'),
  (@b24, 32, 19, 'didis sumanymu ir galingas darbu; nes tavo akys atviros į visus žmonių sūnų kelius; kad kiekvienam duotum pagal jo kelius ir pagal jo darbų vaisių;'),
  (@b24, 32, 20, 'kuris įstatei ženklus bei stebuklus Egipto šalyje iki šios dienos, ir Izraelyje, ir tarp kitų žmonių; ir pasidarei vardą, kaip šią dieną;'),
  (@b24, 32, 21, 'ir išvedei savo tautą Izraelį iš Egipto šalies su ženklais, stebuklais, tvirta ranka, ištiesta ranka ir su dideliu siaubu;'),
  (@b24, 32, 22, 'ir jiems davei šitą šalį, kurią jiems duoti buvai prisiekęs jų tėvams – šalį, plūstančią pienu ir medumi;'),
  (@b24, 32, 23, 'ir jie įėjo ir ją pasisavino; bet jie nepakluso tavo balsui ir nevaikščiojo pagal tavo įstatymą; jie nedarė nieko iš viso to, ką įsakei jiems daryti; todėl tu ant jų užleidai visą šitą nelaimę;'),
  (@b24, 32, 24, 'štai pylimai yra priėję prie miesto, kad jį paimtų; ir dėl kalavijo, bado ir maro miestas yra paduotas į rankas kaldėjų, kovojančių prieš jį; ir ką tu kalbėjai, tai įvyko; ir štai tu tai matai.'),
  (@b24, 32, 25, 'O tu man sakei, o Viešpatie DIEVE: Nusipirk lauką už pinigus ir paimk liudytojus‘; nes miestas atiduotas į kaldėjų rankas.'),
  (@b24, 32, 26, 'Tada Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 32, 27, '‘Štai aš esu VIEŠPATS, visų kūnų Dievas; ar yra man kas nors per sunku?’'),
  (@b24, 32, 28, 'Todėl taip sako VIEŠPATS: Štai aš atiduosiu šitą miestą į kaldėjų rankas ir į Babilono karaliaus Nebukadrecaro rankas, ir jis jį paims;'),
  (@b24, 32, 29, 'ir kaldėjai, kariaujantys prieš šitą miestą, ateis, padegs šitą miestą ir jį sudegins su namais, ant kurių stogų jie atnašavo smilkalus Baalui ir liejo geriamąsias atnašas kitiems dievams, kad kurstytų mano pyktį.'),
  (@b24, 32, 30, 'Nes Izraelio vaikai ir Judos vaikai nuo pat savo jaunystės darė vien tik pikta mano akivaizdoje; nes Izraelio vaikai vien tik kurstė mano pyktį savo rankų darbais, – sako VIEŠPATS.'),
  (@b24, 32, 31, '– Nes šitas miestas nuo tos dienos, kai jį pastatė, iki šios dienos man buvo mano pykčio ir mano įtūžio kurstymu; kad jį pašalinčiau sau iš akių,'),
  (@b24, 32, 32, 'dėl viso Izraelio vaikų ir Judos vaikų pikto, kurį jie darė, kad kurstytų mano pyktį – jie, jų karaliai, jų kunigaikščiai, jų kunigai, jų pranašai, Judos žmonės ir Jeruzalės gyventojai.'),
  (@b24, 32, 33, 'Ir jie atsuko man nugarą, o ne veidą; nors aš juos mokiau, anksti atsikeldamas ir juos mokydamas, tačiau jie neklausė, kad priimtų pamokymą.'),
  (@b24, 32, 34, 'Bet jie pastatė savo bjaurystes namuose, kurie vadinami mano vardu, kad juos suterštų.'),
  (@b24, 32, 35, 'Ir jie pastatė Baalo aukštumas, esančias Hinomo sūnaus slėnyje, kad leistų savo sūnus ir savo dukteris per ugnį Molechui; ko aš jiems neįsakiau nei tai atėjo man į galvą, kad jie darytų tokią bjaurystę, skatindami Judą nusidėti.'),
  (@b24, 32, 36, 'Todėl dabar taip sako VIEŠPATS, Izraelio Dievas, apie šitą miestą, apie kurį jūs sakote: ‘Jis bus atiduotas į Babilono karaliaus ranką kalaviju, badu ir maru’:'),
  (@b24, 32, 37, 'Štai aš juos surinksiu iš visų šalių, į kurias juos išvariau savo pyktyje, savo įtūžyje ir didelėje rūstybėje; ir aš juos sugrąžinsiu į šitą vietą, ir duosiu jiems saugiai gyventi;'),
  (@b24, 32, 38, 'ir jie bus mano tauta, o aš būsiu jų Dievas;'),
  (@b24, 32, 39, 'ir aš jiems duosiu vieną širdį ir vieną kelią, kad jie amžinai manęs bijotų savo pačių labui ir savo vaikų po jų;'),
  (@b24, 32, 40, 'ir aš sudarysiu su jais amžiną sandorą, kad nenusigręšiu nuo jų, darydamas jiems gera; bet aš įdėsiu į jų širdis savo baimę, kad jie nesitrauktų nuo manęs.'),
  (@b24, 32, 41, 'Taip, aš džiaugsiuosi jais, darydamas jiems gera, ir visa savo širdimi ir visa savo siela tvirtai juos įsodinsiu į šitą šalį“.'),
  (@b24, 32, 42, 'Nes taip sako VIEŠPATS: „Kaip užleidau ant šitos tautos visą šią didžią blogybę, taip aš užleisiu ant jų visą gerovę, kurią aš jiems pažadėjau.'),
  (@b24, 32, 43, 'Ir laukai bus perkami šitoje šalyje, apie kurią jūs sakote: ‘Ji dyka, be žmonių ir gyvulių; ji atiduota į kaldėjų rankas’.'),
  (@b24, 32, 44, 'Pirks laukus už pinigus, pasirašinės įrodymus, juos užantspauduos, ir ims liudytojus Benjamino šalyje, Jeruzalės apylinkėse, Judos miestuose, kalnų miestuose, slėnio miestuose ir pietų miestuose; nes aš sugrąžinsiu jų nelaisvę, – sako VIEŠPATS“.'),
  (@b24, 33, 1, 'Be to, VIEŠPATIES žodis antrą kartą atėjo Jeremijui, kol jis tebebuvo uždarytas kalėjimo kieme, sakydamas:'),
  (@b24, 33, 2, '„Taip sako VIEŠPATS, kuris tai daro, VIEŠPATS, kuris tai suformavo, kad tai įtvirtintų; VIEŠPATS yra jo vardas:'),
  (@b24, 33, 3, '‘Šaukis manęs, ir aš tau atsiliepsiu, ir parodysiu tau didžių ir galingų dalykų, kurių nežinai.'),
  (@b24, 33, 4, 'Nes taip sako VIEŠPATS, Izraelio Dievas, apie šito miesto namus ir apie Judos karalių namus, nugriautus pylimu ir kalaviju:'),
  (@b24, 33, 5, 'Jie ateina kovoti su kaldėjais, bet tai tam, kad juos pripildytų lavonų žmonių, kuriuos savo pyktyje ir savo įniršyje užmušiau, ir dėl kurių visos nedorybės paslėpiau savo veidą nuo šito miesto.'),
  (@b24, 33, 6, 'Štai aš jam atnešiu sveikatą ir gydymą, ir juos išgydysiu ir jiems apreikšiu taikos bei tiesos gausybę.'),
  (@b24, 33, 7, 'Ir sugrąžinsiu Judos nelaisvę ir Izraelio nelaisvę ir juos pastatysiu kaip pirma.'),
  (@b24, 33, 8, 'Aš juos apvalysiu nuo visos jų neteisybės, kuria jie prieš mane nusidėjo; ir atleisiu visas jų neteisybes, kuriomis jie nusidėjo ir kuriomis jie nusižengė prieš mane.'),
  (@b24, 33, 9, 'Ir jis man bus džiaugsmo vardas, gyrius ir garbė prieš visas žemės tautas, kurios išgirs apie visa gera, ką aš jiems darysiu; jos bijos ir drebės dėl viso gerumo ir dėl viso suklestėjimo, kurį aš jam parūpinsiu’.'),
  (@b24, 33, 10, 'Taip sako VIEŠPATS: ‘Šitoje vietoje, apie kurią jūs sakote, kad bus tuščia, be žmonių ir gyvulių, būtent Judos miestuose ir Jeruzalės gatvėse, kurios tuščios, be žmonių, be gyventojų ir be gyvulių, vėl girdėsis'),
  (@b24, 33, 11, 'džiaugsmo balsas ir linksmybės balsas, jaunojo balsas ir jaunosios balsas, balsas tų, kurie sakys: „Girkite kariuomenių VIEŠPATĮ; nes VIEŠPATS yra geras; nes jo gailestingumas išlieka amžinai“, ir tų, kurie neš gyriaus auką į VIEŠPATIES namus. Nes aš sugrąžinsiu šalies belaisvius kaip pirma’, – sako VIEŠPATS.'),
  (@b24, 33, 12, 'Taip sako kariuomenių VIEŠPATS: ‘Šitoje vietoje, kuri yra tuščia, be žmonių ir be gyvulių, ir visuose jos miestuose vėl bus buveinė ganytojų, suguldančių savo kaimenes.'),
  (@b24, 33, 13, 'Kalnų miestuose, slėnio miestuose ir pietų miestuose, Benjamino šalyje, Jeruzalės apylinkėse ir Judos miestuose vėl praeis kaimenės po rankomis to, kuris jas skaičiuoja’, – sako VIEŠPATS.'),
  (@b24, 33, 14, '‘Štai ateina dienos, – sako VIEŠPATS, – kai aš įvykdysiu tą gerą dalyką, kurį pažadėjau Izraelio namams ir Judos namams.'),
  (@b24, 33, 15, 'Tomis dienomis ir tuo metu aš užauginsiu Dovydui teisumo Atžalą; ir jis vykdys teismą ir teisumą šalyje.'),
  (@b24, 33, 16, 'Tomis dienomis Juda bus išgelbėta ir Jeruzalė gyvens saugiai; ir šis yra vardas, kuriuo ją vadins: „VIEŠPATS – mūsų teisumas“.'),
  (@b24, 33, 17, 'Nes taip sako VIEŠPATS: Dovydui niekada nepritrūks vyro, kuris sėdėtų Izraelio namų soste;'),
  (@b24, 33, 18, 'nei levitams kunigams nepritrūks vyro mano akivaizdoje, kad atnašautų deginamąsias atnašas, kad degintų maisto atnašas ir nuolat aukotų’“.'),
  (@b24, 33, 19, 'Ir Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 33, 20, '„Taip sako VIEŠPATS: Jei galite sulaužyti mano sandorą dienos ir mano sandorą nakties, kad nebebūtų dienos ir nakties jų metu,'),
  (@b24, 33, 21, 'tuomet galėtų būti sulaužyta ir mano sandora su mano tarnu Dovydu, kad jis neturėtų sūnaus karaliauti jo soste, ir su levitais kunigais, mano tarnais.'),
  (@b24, 33, 22, 'Kaip nesuskaičiuojama dangaus kariuomenė ir nesuseikėjamas jūros smėlis, taip aš padauginsiu savo tarno Dovydo sėklą ir man tarnaujančius levitus“.'),
  (@b24, 33, 23, 'Jeremijui vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 33, 24, '„Ar nematai, ką šita tauta kalbėjo, sakydama: ‘VIEŠPATS atmetė abi šeimas, kurias jis buvo išsirinkęs’? Taip jie niekino mano tautą, kad jie nebūtų jų akivaizdoje tauta.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 33, 25, 'Taip sako VIEŠPATS: ‘Jei mano sandoros nebūtų su diena ir naktimi ir jei nebūčiau paskyręs dangaus ir žemės potvarkių,'),
  (@b24, 33, 26, 'tai aš atmesčiau Jokūbo bei savo tarno Dovydo sėklą taip, kad neimčiau nei vieno iš jo sėklos būti valdovais Abraomo, Izaoko ir Jokūbo sėklai; nes aš sugrąžinsiu jų nelaisvę ir jų pasigailėsiu’“.'),
  (@b24, 34, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES, kai Babilono karalius Nebukadnecaras ir visa jo kariuomenė, visos jo valdomos žemės karalystės ir visos tautos kariavo prieš Jeruzalę ir prieš visus jos miestus, sakydamas:'),
  (@b24, 34, 2, '„Taip sako VIEŠPATS, Izraelio Dievas: Eik ir kalbėk Judos karaliui Zedekijui, ir jam sakyk: ‘Taip sako VIEŠPATS: Štai aš perduosiu šitą miestą į Babilono karaliaus rankas, ir jis sudegins jį ugnimi;'),
  (@b24, 34, 3, 'ir tu neištrūksi iš jo rankos, bet tikrai būsi sugautas ir atiduotas į jo ranką; ir tavo akys matys Babilono karaliaus akis, ir jis kalbės su tavimi burna į burną, ir tu vyksi į Babiloną.'),
  (@b24, 34, 4, 'Tačiau klausykis VIEŠPATIES žodžio, o Judos karaliau Zedekijau: Taip VIEŠPATS sako apie tave: Tu nemirsi nuo kalavijo;'),
  (@b24, 34, 5, 'bet tu mirsi ramybėje; ir kaip degindavo tavo tėvams, ankstesniems karaliams, buvusiems pirma tavęs, taip ir tau degins aromatus; ir tave apraudos, sakydami: „Ak, viešpatie!“ Nes aš paskelbiau žodį, sako VIEŠPATS’“.'),
  (@b24, 34, 6, 'Tada pranašas Jeremijas kalbėjo visus šituos žodžius Judos karaliui Zedekijui Jeruzalėje,'),
  (@b24, 34, 7, 'kai Babilono karaliaus kariuomenė kariavo prieš Jeruzalę ir prieš visus išlikusius Judos miestus – prieš Lachišą ir prieš Azeką; nes šitie sutvirtinti miestai buvo išlikę iš Judos miestų.'),
  (@b24, 34, 8, 'Tai žodis, kuris atėjo Jeremijui iš VIEŠPATIES po to, kai karalius Zedekijas buvo sudaręs sandorą su visa Jeruzalėje esančia tauta, kad jiems paskelbtų laisvę;'),
  (@b24, 34, 9, 'kad kiekvienas išleistų savo tarną ir kiekvienas savo tarnaitę – hebrają ar hebraję – į laisvę; kad nei vienas savęs neapsitarnautų jais, tai yra, savo broliu žydu.'),
  (@b24, 34, 10, 'Na, o kai visi kunigaikščiai ir visa tauta, kurie buvo įstoję į sandorą, išgirdo, kad kiekvienas turi paleisti savo tarną ir kiekvienas savo tarnaitę į laisvę, kad nei vienas jais savęs daugiau nebeapsitarnautų, tai jie pakluso ir juos paleido.'),
  (@b24, 34, 11, 'Bet paskui jie apsigręžė ir susigrąžino tarnus ir tarnaites, kuriuos buvo paleidę į laisvę, ir pavergė juos būti tarnais ir tarnaitėmis.'),
  (@b24, 34, 12, 'Todėl VIEŠPATIES žodis atėjo Jeremijui iš VIEŠPATIES, sakydamas:'),
  (@b24, 34, 13, '„Taip sako VIEŠPATS, Izraelio Dievas: Aš sudariau sandorą su jūsų tėvais tą dieną, kai juos išvedžiau iš Egipto šalies, iš vergų namų, sakydamas:'),
  (@b24, 34, 14, '‘Baigiantis septyneriems metams kiekvienas paleiskite savo brolį hebrają, kuris buvo tau parduotas; ir kai jis tau bus atitarnavęs šešis metus, paleisk jį nuo savęs į laisvę’; bet jūsų tėvai neklausė manęs ir nepalenkė savo ausies.'),
  (@b24, 34, 15, 'Dabar jūs buvote atsigrežę ir padarę teisingai mano akyse, paskelbdami kiekvienas savo artimui laisvę; ir sudarėte sandorą mano akivaizdoje, namuose, kurie vadinami mano vardu;'),
  (@b24, 34, 16, 'bet jūs apsigręžėte ir suteršėte mano vardą, ir kiekvienas susigrąžinote savo tarną ir kiekvienas savo tarnaitę, kuriuos buvote išlaisvinę pagal jų norą, ir juos pavergėte, kad jums būtų tarnais ir tarnaitėmis.'),
  (@b24, 34, 17, 'Todėl taip sako VIEŠPATS: ‘Jūs neklausėte manęs, skelbdami laisvę kiekvienas savo broliui ir kiekvienas savo artimui; štai aš skelbiu jums laisvę kalavijui, marui ir badui, – sako VIEŠPATS; – ir jus perkelsiu į visas žemės karalystes.'),
  (@b24, 34, 18, 'Ir atiduosiu žmones, kurie nusižengė mano sandorai, kurie nevykdė žodžių sandoros, kurią jie buvo sudarę mano akivaizdoje, kai jie perpjovė veršį pusiau ir praėjo tarp jo dalių,'),
  (@b24, 34, 19, 'Judos kunigaikščius ir Jeruzalės kunigaikščius, eunuchus, kunigus ir visą šalies tautą, kurie praėjo tarp veršio dalių,'),
  (@b24, 34, 20, 'aš juos atiduosiu į jų priešų rankas, į rankas tų, kurie ieško jų gyvybės; ir jų lavonai bus maistas dangaus skrajūnams ir žemės žvėrims.'),
  (@b24, 34, 21, 'O Judos karalių Zedekiją ir jo kunigaikščius atiduosiu į jų priešų rankas, į rankas tų, kurie ieško jų gyvybės, į rankas Babilono karaliaus kariuomenės, išėjusios aukštyn nuo jūsų.'),
  (@b24, 34, 22, 'Štai aš įsakysiu, – sako VIEŠPATS, – ir juos sugrąžinsiu į šitą miestą; ir jie prieš jį kariaus, jį paims ir sudegins ugnimi; ir Judos miestus padarysiu dykuma be gyventojų’“.'),
  (@b24, 35, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES Judos karaliaus, Jozijo sūnaus Jehojakimo, dienomis, sakydamas:'),
  (@b24, 35, 2, '„Eik į rechabų namus ir kalbėk jiems, ir atvesk juos į VIEŠPATIES namus, į vieną iš kambarių, ir duok jiems gerti vyno“.'),
  (@b24, 35, 3, 'Tada aš paėmiau Habacinijo sūnaus Jeremijo sūnų Jaazaniją, jo brolius, visus jo sūnus ir visus rechabų namus;'),
  (@b24, 35, 4, 'ir atvedžiau juos į VIEŠPATIES namus, į Igdalijo sūnaus Hanano, Dievo vyro, sūnų kambarį, esantį šalia kunigaikščių kambario, kuris buvo virš Šalumo sūnaus Maasėjo, durų sargo, kambario;'),
  (@b24, 35, 5, 'ir priešais rechabų namų sūnus aš pastačiau puodus, pilnus vyno, bei taures ir jiems tariau: „Gerkite vyno“.'),
  (@b24, 35, 6, 'Bet jie tarė: „Mes negersime vyno; nes Rechabo sūnus Jonadabas, mūsų tėvas, mums įsakė, sakydamas: ‘Negerkite vyno nei jūs, nei jūsų sūnūs per amžius;'),
  (@b24, 35, 7, 'taip pat nesistatykite namų, nesėkite sėklos, nesodinkite vynuogynų ir jų neturėkite; bet per visas savo dienas gyvenkite palapinėse, idant daug dienų gyventumėte šalyje, kurioje jūs esate ateiviai’.'),
  (@b24, 35, 8, 'Taip mes paklusome Rechabo sūnaus, mūsų tėvo Jonadabo balsui visame, kuo jis mus įpareigojo, kad negertume vyno per visas mūsų dienas – nei mes, nei mūsų žmonos, nei mūsų sūnūs, nei mūsų dukterys;'),
  (@b24, 35, 9, 'ir kad nesistatytume namų juose gyventi; ir neturime nei vynuogyno, nei lauko, nei sėklos;'),
  (@b24, 35, 10, 'bet mes gyvenome palapinėse ir paklusome bei darėme pagal visa tai, ką mums įsakė mūsų tėvas Jonadabas.'),
  (@b24, 35, 11, 'Bet įvyko, kad Babilono karaliui Nebukadrecarui atėjus aukštyn į šią šalį, mes sakėme: ‘Ateikite ir eikime į Jeruzalę dėl kaldėjų kariuomenės baimės ir dėl sirų kariuomenės baimės’; taip mes gyvename Jeruzalėje“.'),
  (@b24, 35, 12, 'Tada Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 35, 13, '„Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Eik ir sakyk Judos žmonėms ir Jeruzalės gyventojams: ‘Argi nepriimsite pamokymo, kad paklausytumėte mano žodžių? – sako VIEŠPATS.'),
  (@b24, 35, 14, '– Yra vykdomi žodžiai Rechabo sūnaus Jonadabo, kuriuos jis įsakė savo sūnums, kad negertų vyno; nes iki šios dienos jie negeria, bet paklūsta savo tėvo įsakymui; nors aš jums kalbėjau anksti atsikėlęs ir kalbėdamas, bet jūs neklausėte manęs.'),
  (@b24, 35, 15, 'Taip pat aš siunčiau pas jus visus savo tarnus pranašus anksti keldamasis ir juos siųsdamas, sakydamas: „Sugrįžkite gi kiekvienas nuo savo pikto kelio, taisykite savo darbus ir neikite paskui kitus dievus jiems tarnauti, ir jūs gyvensite šalyje, kurią daviau jums ir jūsų tėvams“; bet jūs nepalenkėte savo ausies ir neklausėte manęs.'),
  (@b24, 35, 16, 'Kadangi Rechabo sūnaus Jonadabo sūnūs vykdė savo tėvo įsakymą, kurį jis jiems įsakė, bet šita tauta neklausė manęs;'),
  (@b24, 35, 17, 'todėl taip sako VIEŠPATS, kariuomenių Dievas, Izraelio Dievas: Štai aš užleisiu ant Judos ir ant visų Jeruzalės gyventojų visą nelaimę, kurią prieš juos paskelbiau; kadangi aš jiems kalbėjau, bet jie nesiklausė; ir aš jiems šaukiau, bet jie neatsiliepė’“.'),
  (@b24, 35, 18, 'Ir Jeremijas tarė rechabų namams: „Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Kadangi paklusote savo tėvo Jonadabo įsakymui, laikėtės visų jo prisakymų ir darėte pagal visa tai, ką jis jums įsakė;'),
  (@b24, 35, 19, 'todėl taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Rechabo sūnui Jonadabui nepritrūks vyro, kad stovėtų mano akivaizdoje per amžius’“.'),
  (@b24, 36, 1, 'Ir įvyko, kad ketvirtaisiais Jehojakimo, sūnaus Jozijo, Judos karaliaus, metais šitas žodis atėjo Jeremijui iš VIEŠPATIES, sakydamas:'),
  (@b24, 36, 2, '„Pasiimk knygos ritinį ir įrašyk į jį visus žodžius, kuriuos tau kalbėjau prieš Izraelį, prieš Judą ir prieš visas tautas nuo tos dienos, kai tau kalbėjau, nuo Jozijo dienų iki šios dienos.'),
  (@b24, 36, 3, 'Gal Judos namai išgirs visa pikta, kurį aš ketinu jiems daryti; kad jie sugrįžtų kiekvienas nuo savo pikto kelio; kad atleisčiau jų neteisybę ir jų nuodėmę“.'),
  (@b24, 36, 4, 'Tada Jeremijas pašaukė Nerijo sūnų Baruchą; ir Baruchas užrašė iš Jeremijo burnos visus VIEŠPATIES žodžius, kuriuos jis jam kalbėjo, į knygos ritinį.'),
  (@b24, 36, 5, 'Ir Jeremijas įsakė Baruchui, sakydamas: „Aš uždarytas; negaliu eiti į VIEŠPATIES namus;'),
  (@b24, 36, 6, 'todėl tu eik į VIEŠPATIES namus pasninko dieną ir perskaityk iš ritinio, kurį užrašei iš mano burnos, VIEŠPATIES žodžius tautai į ausis; taip pat juos perskaityk į ausis visai Judai, atėjusiai iš savo miestų.'),
  (@b24, 36, 7, 'Gal jie pristatys savo maldavimą VIEŠPATIES akivaizdoje, ir kiekvienas sugrįš nuo savo pikto kelio; nes didis yra pyktis ir įtūžis, kurį VIEŠPATS paskelbė prieš šitą tautą“.'),
  (@b24, 36, 8, 'Ir Nerijo sūnus Baruchas padarė pagal visa tai, ką pranašas Jeremijas jam įsakė, skaitydamas iš knygos VIEŠPATIES žodžius VIEŠPATIES namuose.'),
  (@b24, 36, 9, 'Ir penktaisiais Jehojakimo, sūnaus Jozijo, Judos karaliaus, metais, devintąjį mėnesį įvyko, kad jie paskelbė pasninką VIEŠPATIES akivaizdoje visai tautai, buvusiai Jeruzalėje, ir visai tautai, atėjusiai iš Judos miestų į Jeruzalę.'),
  (@b24, 36, 10, 'Tada Baruchas perskaitė iš knygos Jeremijo žodžius visai tautai į ausis VIEŠPATIES namuose, Gemarijo, sūnaus Šafano, raštininko, kambaryje, viršutiniame kieme, VIEŠPATIES namų Naujųjų vartų įėjime.'),
  (@b24, 36, 11, 'Kai Šafano sūnaus Gemarijo sūnus Mikajas išgirdo iš knygos visus VIEŠPATIES žodžius,'),
  (@b24, 36, 12, 'jis nuėjo žemyn į karaliaus namus, į raštininko kambarį; ir štai ten sėdėjo visi kunigaikščiai: raštininkas Elišama, Šemajo sūnus Delajas, Achboro sūnus Elnatanas, Šafano sūnus Gemarijas, Hananijo sūnus Zedekijas ir visi kunigaikščiai.'),
  (@b24, 36, 13, 'Tada Mikajas jiems pranešė visus žodžius, kuriuos jis buvo girdėjęs, kai Baruchas skaitė knygą tautai į ausis.'),
  (@b24, 36, 14, 'Todėl visi kunigaikščiai siuntė Jehudį, sūnų Netanijo, sūnų Šelemijo, sūnų Kušio, pas Baruchą, sakydami: „Pasiimk į ranką ritinį, iš kurio skaitei tautai į ausis, ir ateik“. Taigi Nerijo sūnus Baruchas pasiėmė į ranką ritinį ir atėjo pas juos.'),
  (@b24, 36, 15, 'Ir jie tarė jam: „Na, sėskis ir jį perskaityk mums į ausis“. Taigi Baruchas jį perskaitė jiems į ausis.'),
  (@b24, 36, 16, 'Ir įvyko, kad išgirdę visus žodžius, jie išsigando – tiek vieni, tiek kiti – ir sakė Baruchui: „Mes tikrai pranešime karaliui apie visus šituos žodžius“.'),
  (@b24, 36, 17, 'Ir jie paklausė Baruchą, sakydami: „Na pasakyk mums, kaip tu užrašei visus šituos žodžius iš jo burnos?“'),
  (@b24, 36, 18, 'Tada Baruchas jiems atsakė: „Jis savo burna man ištarė visus šituos žodžius, o aš juos užrašiau į knygą rašalu“.'),
  (@b24, 36, 19, 'Tada kunigaikščiai tarė Baruchui: „Eik, pasislėpk, tu ir Jeremijas; ir tegul niekas nežino, kur esate“.'),
  (@b24, 36, 20, 'Ir jie nuėjo pas karalių į kiemą ir pranešė visus žodžius karaliui į ausis, bet ritinį jie atidėjo raštininko Elišamos kambaryje.'),
  (@b24, 36, 21, 'Taigi karalius pasiuntė Jehudį atnešti ritinį; ir jis paėmė jį iš raštininko Elišamos kambario. Ir Jehudis jį skaitė į ausis karaliui ir į ausis visiems kunigaikščiams, stovintiems šalia karaliaus.'),
  (@b24, 36, 22, 'Na, o karalius sėdėjo žiemos namuose devintąjį mėnesį; o priešais jį židinyje degė ugnis.'),
  (@b24, 36, 23, 'Ir įvyko, kai tik Jehudis perskaitydavo tris ar keturis lapus, jis juos nupjaudavo raštininko peiliu ir numesdavo į ugnį židinyje, kol visas ritinys buvo prarytas židinio ugnyje.'),
  (@b24, 36, 24, 'Tačiau jie neišsigando ir nepersiplėšė savo drabužių – nei karalius, nei kas iš jo tarnų, kurie girdėjo visus šituos žodžius.'),
  (@b24, 36, 25, 'Nors Elnatanas, Delajas ir Gemarijas maldavo karalių nedeginti ritinio, bet jis jų neklausė.'),
  (@b24, 36, 26, 'Bet karalius įsakė Hamelecho sūnui Jerachmeeliui, Azrielio sūnui Serajui ir Abdeelio sūnui Šelemijui suimti raštininką Baruchą ir pranašą Jeremiją; bet VIEŠPATS juos paslėpė.'),
  (@b24, 36, 27, 'Po to, kai karalius sudegino ritinį ir žodžius, kuriuos Baruchas užrašė iš Jeremijo burnos, Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 36, 28, '„Vėl imk kitą ritinį ir užrašyk į jį visus ankstesnius žodžius, kurie buvo pirmajame ritinyje, kurį sudegino Judos karalius Jehojakimas.'),
  (@b24, 36, 29, 'Ir Judos karaliui Jehojakimui sakyk: ‘Taip sako VIEŠPATS: Tu sudeginai šitą ritinį, sakydamas: „Kodėl jame parašei, sakydamas: ‘Babilono karalius tikrai ateis ir sunaikins šitą šalį, ir išnaikins iš jos žmones ir gyvulius’?“'),
  (@b24, 36, 30, 'Todėl taip sako VIEŠPATS apie Judos karalių Jehojakimą: Jis neturės nei vieno, sėdinčio Dovydo soste; ir jo lavonas bus dieną išmestas kaitrai, o naktį šalčiui.'),
  (@b24, 36, 31, 'Ir aš nubausiu jį, jo sėklą ir jo tarnus dėl jų neteisybės; ir užleisiu ant jų, ant Jeruzalės gyventojų ir ant Judos žmonių visą nelaimę, kurią prieš juos paskelbiau, bet jie nesiklausė’“.'),
  (@b24, 36, 32, 'Tada Jeremijas paėmė kitą ritinį ir jį padavė raštininkui Baruchui, Nerijo sūnui, kuris iš Jeremijo burnos į jį užrašė visus žodžius knygos, kurią Judos karalius Jehojakimas buvo sudeginęs ugnyje; ir prie jų dar buvo pridėta daug panašių žodžių.'),
  (@b24, 37, 1, 'Ir Jehojakimo sūnaus Konijo vietoje karaliavo Jozijo sūnus, karalius Zedekijas, kurį Babilono karalius Nebukadrecaras paskyrė karaliumi Judos šalyje.'),
  (@b24, 37, 2, 'Bet nei jis, nei jo tarnai, nei šalies tauta neklausė VIEŠPATIES žodžių, kuriuos jis kalbėjo per pranašą Jeremiją.'),
  (@b24, 37, 3, 'Ir karalius Zedekijas siuntė Šelemijo sūnų Jehukalą ir kunigą Sofoniją, Maasėjo sūnų pas pranašą Jeremiją, sakydamas: „Melsk už mus VIEŠPATĮ, mūsų Dievą“.'),
  (@b24, 37, 4, 'Na, o Jeremijas įeidavo ir išeidavo tautos tarpe; nes jo nebuvo pasodinę į kalėjimą.'),
  (@b24, 37, 5, 'Tada faraono kariuomenė buvo išėjusi iš Egipto; ir kai Jeruzalę apgulę kaldėjai išgirdo žinią apie juos, jie atsitraukė nuo Jeruzalės.'),
  (@b24, 37, 6, 'Tada pranašui Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 37, 7, '„Taip sako VIEŠPATS, Izraelio Dievas: Taip sakykite Judos karaliui, jus atsiuntusiam pas mane manęs paklausti: ‘Štai faraono kariuomenė, išėjusi jums padėti, sugrįš į savo šalį Egiptą.'),
  (@b24, 37, 8, 'Ir kaldėjai vėl ateis, kariaus prieš šitą miestą, jį paims ir sudegins jį ugnimi.'),
  (@b24, 37, 9, 'Taip sako VIEŠPATS: Neapsigaukite, sakydami: „Kaldėjai tikrai pasitrauks nuo mūsų“; nes jie nepasitrauks.'),
  (@b24, 37, 10, 'Nors jūs ir sumuštumėte visą kaldėjų kariuomenę, kovojančią prieš jus, ir tarp jų liktų tik sužeisti vyrai, tačiau jie keltųsi kiekvienas savo palapinėje ir sudegintų šitą miestą ugnimi’“.'),
  (@b24, 37, 11, 'Ir įvyko, kai kaldėjų kariuomenė atsitraukė nuo Jeruzalės dėl faraono kariuomenės baimės,'),
  (@b24, 37, 12, 'Jeremijas išėjo iš Jeruzalės, kad nueitų į Benjamino šalį, kad iš ten atsiskirtų tautos tarpe.'),
  (@b24, 37, 13, 'Ir kai jis buvo Benjamino vartuose, ten buvo sargybos vadas, kurio vardas Irijas, Hananijo sūnaus Šelemijo sūnus; ir jis nutvėrė pranašą Jeremiją, sakydamas: „Tu persimeti pas kaldėjus“.'),
  (@b24, 37, 14, 'Tada Jeremijas tarė: „Tai netiesa; aš nepersimetu pas kaldėjus“. Bet jis jo neklausė; taigi Irijas suėmė Jeremiją ir jį nuvedė pas kunigaikščius.'),
  (@b24, 37, 15, 'Todėl kunigaikščiai užsirūstino ant Jeremijo, sumušė jį ir pasodino į kalėjimą raštininko Jonatano namuose; nes padarė juos kalėjimu.'),
  (@b24, 37, 16, 'Kai Jeremijas buvo įėjęs į požeminį kalėjimą, į vienutę, ir ten išbuvo Jeremijas daug dienų;'),
  (@b24, 37, 17, 'tada karalius Zedekijas pasiuntė ir išvedė jį; ir karalius savo namuose jį slaptai klausė ir tarė: „Ar yra koks žodis iš VIEŠPATIES?“ Ir Jeremijas tarė: „Yra, nes tu, – jis tarė, – būsi atiduotas į Babilono karaliaus rankas“.'),
  (@b24, 37, 18, 'Be to, Jeremijas tarė karaliui Zedekijui: „Kuo nusikaltau tau ar tavo tarnams, ar šitai tautai, kad mane pasodinote į kalėjimą?'),
  (@b24, 37, 19, 'Kur dabar yra jūsų pranašai, kurie jums pranašavo, sakydami: ‘Babilono karalius neateis nei prieš jus, nei prieš šitą šalį’?'),
  (@b24, 37, 20, 'Todėl dabar klausyk, meldžiu tave, o mano viešpatie karaliau; mano prašymas tebūna priimtinas tavo akivaizdoje; kad nesugrąžintum manęs į raštininko Jonatano namus, idant ten nemirčiau“.'),
  (@b24, 37, 21, 'Tada karalius Zedekijas įsakė, kad jie Jeremiją atiduotų į kalėjimo kiemą ir kasdien jam duotų gabalą duonos iš kepėjų gatvės, kol visa duona mieste pasibaigs. Taip Jeremijas liko kalėjimo kieme.'),
  (@b24, 38, 1, 'Tada Matano sūnus Šefatija, Pašhūro sūnus Gedalija, Šelemijo sūnus Jukalas ir Malkijo sūnus Pašhūras girdėjo žodžius, kuriuos Jeremijas kalbėjo visai tautai, sakydamas:'),
  (@b24, 38, 2, '„Taip sako VIEŠPATS: ‘Kas pasiliks šiame mieste, mirs nuo kalavijo, bado ir maro; o kas išeis pas kaldėjus – gyvens; nes jis turės savo gyvybę kaip grobį ir išliks gyvas’.'),
  (@b24, 38, 3, 'Taip sako VIEŠPATS: ‘Šitas miestas tikrai bus atiduotas į ranką Babilono karaliaus kariuomenės, kuri jį paims’“.'),
  (@b24, 38, 4, 'Todėl kunigaikščiai tarė karaliui: „Meldžiame tave, tebūna šitas vyras užmuštas; nes kalbėdamas jiems šitokius žodžius, jis taip susilpnina rankas karo vyrų, likusių šiame mieste, ir visos tautos rankas; nes šitas vyras siekia ne gerovės šitai tautai, bet žalos“.'),
  (@b24, 38, 5, 'Tada karalius Zedekijas tarė: „Štai jis yra jūsų rankose; nes karalius nieko negali prieš jus padaryti“.'),
  (@b24, 38, 6, 'Tada jie paėmė Jeremiją ir įmetė jį į Hamelecho sūnaus Malkijo požemį, buvusį kalėjimo kieme; ir jie nuleido Jeremiją virvėmis. O požemyje nebuvo vandens, tik purvas; taigi Jeremijas įklimpo į purvynę.'),
  (@b24, 38, 7, 'Na, o kai etiopas Ebed-Melechas, vienas iš eunuchų, kuris buvo karaliaus namuose, išgirdo, kad jie Jeremiją įmetė į požemį, karaliui tuo metu sėdint Benjamino vartuose,'),
  (@b24, 38, 8, 'Ebed-Melechas išėjo iš karaliaus namų ir kalbėjo karaliui, sakydamas:'),
  (@b24, 38, 9, '„Mano viešpatie karaliau, šitie vyrai piktai pasielgė visu tuo, ką jie padarė pranašui Jeremijui, kurį jie įmetė į požeminį kalėjimą; ir toje vietoje, kur jis yra, jis turės mirti badu; nes nebėra duonos mieste“.'),
  (@b24, 38, 10, 'Tada karalius įsakė etiopui Ebed-Melechui, sakydamas: „Paimk iš čia su savimi trisdešimt vyrų ir iškelk pranašą Jeremiją iš požemio, kol jis nenumirė“.'),
  (@b24, 38, 11, 'Taigi Ebed-Melechas, paėmęs su savimi vyrus, įėjo į karaliaus namus po saugykla ir iš ten paėmė senų susidėvėjusių drabužių ir senų sudūlėjusių skudurų ir juos virvėmis nuleido Jeremijui į požemį.'),
  (@b24, 38, 12, 'Ir etiopas Ebed-Melechas tarė Jeremijui: „Pasikišk šituos senus susidėvėjusius drabužius ir sudūlėjusius skudurus po savo pažastimis po virvėmis“. Ir Jeremijas taip padarė.'),
  (@b24, 38, 13, 'Taigi jie virvėmis ištraukė Jeremiją ir iškėlė jį iš požemio; ir Jeremijas pasiliko kalėjimo kieme.'),
  (@b24, 38, 14, 'Tada karalius Zedekijas siuntė ir pasiėmė pranašą Jeremiją pas save prie trečiojo įėjimo, esančio VIEŠPATIES namuose; ir karalius tarė Jeremijui: „Aš noriu tave kai ko paklausti; nieko neslėpk nuo manęs“.'),
  (@b24, 38, 15, 'Tada Jeremijas tarė Zedekijui: „Jei tau paskelbsiu, argi tikrai nenubausi manęs mirtimi? O jei tau patarsiu, juk nepaklausysi manęs?“'),
  (@b24, 38, 16, 'Taigi karalius Zedekijas slaptai prisiekė Jeremijui, sakydamas: „Kaip gyvas VIEŠPATS, kuris mums padarė šitą sielą, aš tavęs neužmušiu ir neatiduosiu į rankas šitų vyrų, kurie ieško tavo gyvybės“.'),
  (@b24, 38, 17, 'Tada Jeremijas tarė Zedekijui: „Taip sako VIEŠPATS, kariuomenių Dievas, Izraelio Dievas: ‘Jei tikrai išeisi pas Babilono karaliaus kunigaikščius, tai tavo siela išliks gyva ir šitas miestas nebus sudegintas ugnimi; ir išliksi gyvas tu ir tavo namai;'),
  (@b24, 38, 18, 'bet jei neišeisi pas Babilono karaliaus kunigaikščius, tai šitas miestas bus atiduotas į kaldėjų rankas ir jie sudegins jį ugnimi, ir tu neištrūksi iš jų rankų“.'),
  (@b24, 38, 19, 'Ir karalius Zedekijas tarė Jeremijui: „Aš bijau žydų, persimetusių pas kaldėjus, kad jie manęs neatiduotų į jų rankas, ir jie iš manęs nepasityčiotų“.'),
  (@b24, 38, 20, 'Bet Jeremijas tarė: „Jie tavęs neatiduos. Meldžiu tave, paklusk VIEŠPATIES balsui, kurį aš tau kalbu; tai tau bus gerai ir tavo siela išliks gyva.'),
  (@b24, 38, 21, 'Bet jei tu nesutiksi išeiti, štai žodis, kurį man parodė VIEŠPATS:'),
  (@b24, 38, 22, '‘Ir štai visos moterys, likusios Judos karaliaus namuose, bus išvestos pas Babilono karaliaus kunigaikščius, ir jos sakys: „Tavo draugai suvedžiojo tave ir tave nugalėjo; tavo kojos įklimpo į purvynę, ir jie atsitraukė“’.'),
  (@b24, 38, 23, 'Taigi visas tavo žmonas ir tavo vaikus jie išves pas kaldėjus; ir tu neištrūksi iš jų rankų, bet būsi sugautas Babilono karaliaus rankos; ir tu paskatinsi šitą miestą sudeginti ugnimi“.'),
  (@b24, 38, 24, 'Tada Zedekijas tarė Jeremijui: „Tegul niekas nežino apie šituos žodžius, ir tu nemirsi.'),
  (@b24, 38, 25, 'Bet jei kunigaikščiai išgirs, kad kalbėjausi su tavimi, ateis pas tave ir tau sakys: ‘Na paskelbk mums, ką kalbėjai karaliui, neslėpk nuo mūsų, ir mes tavęs neužmušime; ir taip pat, ką tau sakė karalius’;'),
  (@b24, 38, 26, 'tada jiems sakyk: ‘Aš pristačiau savo prašymą karaliaus akivaizdon, kad jis manęs nesugrąžintų į Jonatano namus, idant ten nemirčiau’“.'),
  (@b24, 38, 27, 'Tada visi kunigaikščiai atėjo pas Jeremiją ir jį klausė; ir jis jiems atsakė pagal visus tuos žodžius, kuriuos karalius buvo įsakęs. Taigi jie liovėsi kalbėję su juo; nes tas reikalas liko nepastebėtas.'),
  (@b24, 38, 28, 'Taip Jeremijas pasiliko kalėjimo kieme iki tos dienos, kai Jeruzalė buvo paimta; ir jis ten buvo, kai Jeruzalė buvo paimta.'),
  (@b24, 39, 1, 'Judos karaliaus Zedekijo devintaisiais metais, dešimtąjį mėnesį, Babilono karalius Nebukadrecaras ir visa jo kariuomenė atėjo prieš Jeruzalę ir ją apgulė.'),
  (@b24, 39, 2, 'O vienuoliktaisiais Zedekijo metais, ketvirtąjį mėnesį, devintąją mėnesio dieną miestas buvo pralaužtas.'),
  (@b24, 39, 3, 'Ir visi Babilono karaliaus kunigaikščiai įėjo ir susėdo viduriniuose vartuose: Nergal-Šareceras, Samgar-Nebas, Sarsechimas, Rabar-Saris, Nergal-Šareceras ir Rab-Magas su visais likusiais Babilono karaliaus kunigaikščiais.'),
  (@b24, 39, 4, 'Ir įvyko, kai Judos karalius Zedekijas ir visi karo vyrai juos pamatė, jie pabėgo, ir išėjo iš miesto nakčia karaliaus sodo keliu pro vartus tarp dviejų sienų; ir jis išėjo lygumos keliu.'),
  (@b24, 39, 5, 'Bet kaldėjų kariuomenė juos persekiojo, ir pasivijo Zedekiją Jericho lygumose; ir jį suėmę jie nuvedė jį aukštyn pas Babilono karalių Nebukadnecarą į Riblą Hamato šalyje, kur jis įvykdė jam teismą.'),
  (@b24, 39, 6, 'Tada Babilono karalius nužudė Zedekijo sūnus Ribloje jo akyse; taip pat Babilono karalius nužudė ir visus Judos kilminguosius.'),
  (@b24, 39, 7, 'Be to, jis išlupo Zedekijui akis ir jį sukaustė grandinėmis, kad jį išgabentų į Babiloną.'),
  (@b24, 39, 8, 'Ir kaldėjai sudegino karaliaus namus ir tautos namus ugnimi ir nugriovė Jeruzalės sienas.'),
  (@b24, 39, 9, 'Tada Nebuzar-Adanas, sargybos vadas, išvedė nelaisvėn į Babiloną likutį tautos, išlikusios mieste, ir persimetėlius, kurie buvo persimetę pas jį, kartu su tautos likučiu, kurie buvo pasilikę.'),
  (@b24, 39, 10, 'Bet sargybos vadas Nebuzar-Adanas paliko Judos šalyje tautos vargšų, kurie nieko neturėjo, ir tuo pačiu metu jiems davė vynuogynų ir laukų.'),
  (@b24, 39, 11, 'Na, o Babilono karalius Nebukadrecaras įpareigojo sargybos vadą Nebuzar-Adaną dėl Jeremijo, sakydamas:'),
  (@b24, 39, 12, '„Paimk jį ir gerai jį prižiūrėk, ir nedaryk jam pikto; bet padaryk jam, kaip jis tau sakys“.'),
  (@b24, 39, 13, 'Taigi sargybos vadas Nebuzar-Adanas pasiuntė, ir Nebušazbanas, Rab-Saris, Nergal-Šareceras, Rab-Magas ir visi Babilono karaliaus kunigaikščiai'),
  (@b24, 39, 14, 'pasiuntė ir paėmė Jeremiją iš kalėjimo kiemo, ir jį pavedė Šafano sūnaus Ahikamo sūnui Gedalijui, kad jis nuvestų jį namo; taip jis gyveno tautos tarpe.'),
  (@b24, 39, 15, 'Na, o kol Jeremijas dar buvo uždarytas kalėjimo kieme, jam atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 39, 16, '„Eik ir kalbėk etiopui Ebed-Melechui, sakydamas: ‘Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Štai aš užleisiu savo žodžius ant šito miesto dėl pikto, o ne dėl gero; ir tą dieną jie išsipildys tavo akivaizdoje.'),
  (@b24, 39, 17, 'Bet tą dieną aš tave išvaduosiu, – sako VIEŠPATS; – ir tu nebūsi atiduotas į rankas tų žmonių, kurių tu bijai.'),
  (@b24, 39, 18, 'Nes aš tikrai tave išvaduosiu, ir tu nekrisi nuo kalavijo, bet tavo gyvybė bus tau kaip grobis, nes pasitikėjai manimi’, – sako VIEŠPATS“.'),
  (@b24, 40, 1, 'Žodis, kuris atėjo Jeremijui iš VIEŠPATIES po to, kai sargybos vadas Nebuzar-Adanas jį paleido iš Ramos, kai jį paėmė sukaustytą grandinėse tarp visų, vedamų į nelaisvę iš Jeruzalės ir Judos, kurie buvo išvedami nelaisvėn į Babiloną.'),
  (@b24, 40, 2, 'Ir sargybos vadas, paėmęs Jeremiją, jam tarė: „VIEŠPATS, tavo Dievas, paskelbė šią nelaimę šitai vietai.'),
  (@b24, 40, 3, 'Na, o VIEŠPATS ją užleido ir padarė pagal tai, ką buvo kalbėjęs; nes jūs nusidėjote prieš VIEŠPATĮ ir nepaklusote jo balsui, todėl tas dalykas užėjo ant jūsų.'),
  (@b24, 40, 4, 'O dabar, štai šią dieną tave išlaisvinu nuo grandinių, esančių ant tavo rankų. Jei tau atrodo gerai eiti su manimi į Babiloną, eik; ir aš gerai tave prižiūrėsiu; bet jei tau atrodo negerai eiti su manimi į Babiloną, susilaikyk; štai visa šalis tavo priešakyje; kur tau atrodo gerai ir tinkama eiti, ten ir eik“.'),
  (@b24, 40, 5, 'Na, o kai jis dar nebuvo atsitraukęs, jis tarė: „Grįžk pas Šafano sūnaus Ahikamo sūnų Gedaliją, kurį Babilono karalius paskyrė valdytoju Judos miestams, ir gyvenk su juo tautos tarpe; arba eik, kur tik tau atrodo tinkama eiti“. Taigi sargybos vadas davė jam maisto bei apdovanojimą ir jį paleido.'),
  (@b24, 40, 6, 'Tada Jeremijas nuėjo pas Ahikamo sūnų Gedaliją į Micpą; ir gyveno su juo tarpe tautos, išlikusios šalyje.'),
  (@b24, 40, 7, 'Na, o kai visi kariuomenės vadai, kurie buvo laukuose – jie ir jų vyrai – išgirdo, kad Babilono karalius buvo paskyręs Ahikamo sūnų Gedaliją valdytoju šalyje ir jam pavedęs vyrus, moteris, vaikus ir šalies beturčių, iš tų, kurie nebuvo išvesti nelaisvėn į Babiloną,'),
  (@b24, 40, 8, 'jie atėjo pas Gedaliją į Micpą, būtent Netanijo sūnus Išmaelis, Kareacho sūnūs Johananas ir Jonatanas, Tanhumeto sūnus Seraja, netofiečio Efajo sūnūs ir maako sūnus Jezanijas – jie ir jų vyrai.'),
  (@b24, 40, 9, 'Ir Šafano sūnaus Ahikamo sūnus Gedalijas jiems ir jų vyrams prisiekė, sakydamas: „Nebijokite tarnauti kaldėjams; gyvenkite šalyje ir tarnaukite Babilono karaliui, ir jums bus gerai.'),
  (@b24, 40, 10, 'Aš pats štai gyvensiu Micpoje, kad tarnaučiau kaldėjams, kurie atvyks pas mus; bet jūs rinkite vyną, vasaros vaisius ir aliejų ir supilkite juos į savo indus, ir gyvenkite savo miestuose, kuriuos esate užėmę“.'),
  (@b24, 40, 11, 'Taip pat kai visi žydai, esantys Moabe, tarp amoniečių, Edome ir esantys visose šalyse, išgirdo, kad Babilono karalius buvo palikęs Judos likutį ir kad buvo paskyręs juos valdyti Šafano sūnaus Ahikamo sūnų Gedaliją;'),
  (@b24, 40, 12, 'visi žydai grįžo iš visų vietų, į kurias jie buvo išvaryti, ir atėjo į Judos šalį pas Gedaliją į Micpą; ir rinko labai daug vyno ir vasaros vaisių.'),
  (@b24, 40, 13, 'Be to, Kareacho sūnus Johananas ir visi kariuomenės vadai, buvusieji lauke, atėjo pas Gedaliją į Micpą'),
  (@b24, 40, 14, 'ir jam tarė: „Ar tikrai žinai, kad amoniečių karalius Baalis siuntė Netanijo sūnų Išmaelį tavęs nužudyti?“ Bet Ahikamo sūnus Gedalijas jais netikėjo.'),
  (@b24, 40, 15, 'Tada Kareacho sūnus Johananas slaptai kalbėjo Gedalijui Micpoje, sakydamas: „Meldžiu tave, leisk man eiti ir aš užmušiu Netanijo sūnų Išmaelį, ir niekas nesužinos; kodėl jis turėtų užmušti tave, kad visi žydai, susirinkę pas tave, būtų išsklaidyti ir Judos likutis pražūtų?“'),
  (@b24, 40, 16, 'Bet Ahikamo sūnus Gedalijas tarė Kareacho sūnui Johananui: „Nedaryk to; nes netiesą kalbi apie Išmaelį“.'),
  (@b24, 41, 1, 'Na, o septintąjį mėnesį įvyko, kad Elišamos sūnaus Netanijo sūnus Išmaelis, iš karališkos sėklos, ir karaliaus kunigaikščiai, būtent dešimt vyrų, atėjo su juo pas Ahikamo sūnų Gedaliją į Micpą; ir ten Micpoje jie drauge valgė duoną.'),
  (@b24, 41, 2, 'Tada pakilo Netanijo sūnus Išmaelis ir dešimt vyrų, esančių su juo, ir kirto Šafano sūnaus Ahikamo sūnui Gedalijui kalaviju ir jį užmušė, tą, kurį Babilono karalius buvo paskyręs šalies valdytoju.'),
  (@b24, 41, 3, 'Išmaelis išžudė ir visus žydus, esančius su juo, būtent su Gedaliju, Micpoje, ir kaldėjus, kuriuos ten rado, karo vyrus.'),
  (@b24, 41, 4, 'Ir kitą dieną, po to, kai jis buvo nužudęs Gedaliją, niekam to nežinant, įvyko, kad'),
  (@b24, 41, 5, 'atėjo kai kurie iš Šechemo, iš Šilojaus ir iš Samarijos – aštuoniasdešimt vyrų nusiskutę barzdas, persiplėšę drabužius ir susipjaustę, su atnašomis ir smilkalais rankose, kad juos nuneštų į VIEŠPATIES namus.'),
  (@b24, 41, 6, 'Ir Netanijo sūnus Išmaelis išėjo iš Micpos jų pasitikti, eidamas ir vis verkdamas; ir įvyko, kad juos sutikęs jis jiems tarė: „Ateikite pas Ahikamo sūnų Gedaliją“.'),
  (@b24, 41, 7, 'Ir buvo, kai jie atėjo į miesto vidurį, Netanijo sūnus Išmaelis juos išžudė ir sumetė į duobę – jis ir vyrai, kurie buvo su juo.'),
  (@b24, 41, 8, 'Bet tarp jų atsirado dešimt vyrų, kurie sakė Išmaeliui: „Nežudyk mūsų, nes mes turime lauke turtų: kviečių, miežių, aliejaus ir medaus“. Taigi jis susilaikė ir jų nenužudė tarp jų brolių.'),
  (@b24, 41, 9, 'Na, o duobė, į kurią Išmaelis sumetė visus lavonus vyrų, kuriuos jis išžudė dėl Gedalijo, buvo ta, kurią karalius Asa buvo padaręs dėl Izraelio karaliaus Baašos baimės; ir Netanijo sūnus Išmaelis ją pripildė nužudytųjų.'),
  (@b24, 41, 10, 'Paskui Išmaelis nusivedė nelaisvėn visą Micpoje buvusį tautos likutį, karaliaus dukteris ir visą tautą, išlikusią Micpoje, kurią sargybos vadas Nebuzar-Adanas buvo pavedęs Ahikamo sūnui Gedalijui; ir Netanijo sūnus Išmaelis juos nusivedė į nelaisvę ir išėjo, kad pereitų pas amoniečius.'),
  (@b24, 41, 11, 'Bet kai Kareacho sūnus Johananas ir visi su juo esantys kariuomenės vadai išgirdo apie visą piktą darbą, kurį Netanijo sūnus Išmaelis buvo padaręs,'),
  (@b24, 41, 12, 'jie paėmė visus vyrus ir ėjo kovoti su Netanijo sūnumi Išmaeliu, ir jį užtiko prie didžiųjų vandenų, esančių Gibeone.'),
  (@b24, 41, 13, 'Ir įvyko, kai visa su Išmaeliu esanti tauta pamatė Kareacho sūnų Johananą ir visus su juo esančius kariuomenės vadus, ji apsidžiaugė.'),
  (@b24, 41, 14, 'Taigi visa tauta, kurią Išmaelis išvedė nelaisvėn iš Micpos, pasuko atgal ir sugrįžo, ir nuėjo pas Kareacho sūnų Johananą.'),
  (@b24, 41, 15, 'Bet Netanijo sūnus Išmaelis su aštuoniais vyrais paspruko nuo Johanano ir nuėjo pas amoniečius.'),
  (@b24, 41, 16, 'Tada Kareacho sūnus Johananas ir visi su juo esantys kariuomenės vadai paėmė visą tautos likutį, kurį jis sugrąžino iš Netanijo sūnaus Išmaelio, iš Micpos po to, kai jis nužudė Ahikamo sūnų Gedaliją: būtent galingus karo vyrus, moteris, vaikus ir eunuchus, kuriuos jis sugrąžino iš Gibeono;'),
  (@b24, 41, 17, 'ir jie išėjo ir apsigyveno Kimhamo gyvenvietėje, esančioje prie Betliejaus, kad eitų ir įeitų į Egiptą,'),
  (@b24, 41, 18, 'dėl kaldėjų; nes jie bijojo jų, kadangi Netanijo sūnus Išmaelis buvo nužudęs Ahikamo sūnų Gedaliją, kurį Babilono karalius buvo paskyręs valdytoju šalyje.'),
  (@b24, 42, 1, 'Tada visi kariuomenės vadai, Kareacho sūnus Johananas, Hošajo sūnus Jezanijas ir visa tauta, nuo mažiausio iki didžiausio, priėjo'),
  (@b24, 42, 2, 'ir tarė pranašui Jeremijui: „Meldžiame tave, tegul mūsų prašymas būna priimtinas tavo akivaizdoje ir melskis už mus VIEŠPAČIUI, savo Dievui, tai yra už visą šitą likutį (nes mūsų tėra išlikę mažai iš daugelio, kaip tavo akys mus mato);'),
  (@b24, 42, 3, 'kad VIEŠPATS, tavo Dievas, mums parodytų kelią, kuriuo galime vaikščioti, ir tai, ką galime daryti“.'),
  (@b24, 42, 4, 'Tada pranašas Jeremijas jiems tarė: „Aš jus išklausiau; štai aš melsiuosi VIEŠPAČIUI, jūsų Dievui, pagal jūsų žodžius; ir įvyks, kad viską, ką VIEŠPATS jums atsakys, aš jums pranešiu; nieko nuo jūsų nenuslėpsiu“.'),
  (@b24, 42, 5, 'Tada jie tarė Jeremijui: „VIEŠPATS tebūna teisingas ir ištikimas liudytojas tarp mūsų, jei nedarysime pagal visa tai, dėl ko VIEŠPATS, tavo Dievas, tave atsiųs pas mus.'),
  (@b24, 42, 6, 'Ar tai būtų gera, ar tai būtų bloga, mes paklusime balsui VIEŠPATIES, savo Dievo, pas kurį tave siunčiame; kad mums gerai sektųsi, kai paklusime VIEŠPATIES, mūsų Dievo, balsui“.'),
  (@b24, 42, 7, 'Ir po dešimties dienų įvyko, kad VIEŠPATIES žodis atėjo Jeremijui.'),
  (@b24, 42, 8, 'Tada jis pašaukė Kareacho sūnų Johananą, visus su juo esančius kariuomenės vadus bei visą tautą, nuo mažiausio iki didžiausio,'),
  (@b24, 42, 9, 'ir jiems tarė: „Taip sako VIEŠPATS, Izraelio Dievas, pas kurį mane siuntėte jam pateikti jūsų prašymą:'),
  (@b24, 42, 10, '‘Jei tik pasiliksite šitoje šalyje, tada aš jus statysiu ir negriausiu, jus sodinsiu ir neišrausiu; nes gailiuosi dėl to pikto, kurį jums padariau.'),
  (@b24, 42, 11, 'Nebijokite Babilono karaliaus, kurio jūs bijote; nebijokite jo, – sako VIEŠPATS; – nes aš su jumis, kad jus išgelbėčiau ir jus išvaduočiau iš jo rankos.'),
  (@b24, 42, 12, 'Ir aš jums parodysiu gailestingumus, kad jis jūsų pasigailėtų ir sugrąžintų jus į jūsų pačių šalį.'),
  (@b24, 42, 13, 'Bet jei jūs sakysite: „Mes negyvensime šitoje šalyje“ ir nepaklusite VIEŠPATIES, jūsų Dievo, balsui'),
  (@b24, 42, 14, 'sakydami: „Ne; mes eisime į Egipto šalį, kur nematysime karo, negirdėsime trimito garso ir nealksime duonos; ir ten gyvensime“;'),
  (@b24, 42, 15, 'todėl dabar, Judos likuti, klausyk VIEŠPATIES žodžio: Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Jei jūs pilnai nukreipsite savo veidus įeiti į Egiptą ir nueisite ten laikinai apsigyventi;'),
  (@b24, 42, 16, 'tuomet įvyks, kad kalavijas, kurio jūs bijote, jus pavys ten Egipto šalyje, ir badas, kuris jus gąsdina, seks jus įkandin ten Egipte; ir ten jūs mirsite.'),
  (@b24, 42, 17, 'Taip bus visiems, kurie nukreips savo veidus eiti į Egiptą, kad ten apsigyventų; jie mirs nuo kalavijo, nuo bado ir nuo maro; ir nei vienas iš jų neišliks ir neištrūks nuo pikto, kurį aš ant jų užleisiu’.'),
  (@b24, 42, 18, 'Nes taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Kaip mano pyktis ir mano įtūžis buvo išlietas ant Jeruzalės gyventojų, taip mano įtūžis bus išlietas ant jūsų, kai įeisite į Egiptą; ir jūs būsite prakeikimu, nuostaba, keiksmu ir priekaištu; ir jūs nebematysite šitos vietos’.'),
  (@b24, 42, 19, 'VIEŠPATS kalbėjo apie jus, Judos likuti, neikite į Egiptą; tvirtai žinokite, kad šią dieną jus įspėjau.'),
  (@b24, 42, 20, 'Nes jūs veidmainiavote savo širdyse, kai mane siuntėte pas VIEŠPATĮ, savo Dievą, sakydami: ‘Melskis už mus VIEŠPAČIUI, mūsų Dievui; ir pagal visa tai, ką VIEŠPATS, mūsų Dievas, sakys, mums taip pranešk, ir mes tai darysime’.'),
  (@b24, 42, 21, 'Na, o aš jums šią dieną tai paskelbiau; bet jūs nepaklusote VIEŠPATIES, savo Dievo, balsui, nei tam, dėl ko jis mane siuntė pas jus.'),
  (@b24, 42, 22, 'Todėl dabar tvirtai žinokite, kad mirsite nuo kalavijo, nuo bado ir nuo maro vietoje, į kurią norite eiti ir laikinai apsigyventi“.'),
  (@b24, 43, 1, 'Ir Jeremijui baigus kalbėti visai tautai visus VIEŠPATIES, jų Dievo, žodžius, dėl kurių VIEŠPATS, jų Dievas, jį siuntė pas juos, būtent visus šituos žodžius,'),
  (@b24, 43, 2, 'įvyko, kad Hošajo sūnus Azarijas, Kareacho sūnus Johananas bei visi išdidūs žmonės kalbėjo Jeremijui sakydami: „Tu melagingai kalbi; VIEŠPATS, mūsų Dievas, tavęs nesiuntė sakyti: ‘Neikite į Egiptą ten laikinai apsigyventi’;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 43, 3, 'bet Nerijo sūnus Baruchas nuteikia tave prieš mus, kad mus atiduotų į kaldėjų rankas, kad jie mus užmuštų ir išvestų mus nelaisvėn į Babiloną“.'),
  (@b24, 43, 4, 'Taigi Kareacho sūnus Johananas, visi kariuomenės vadai ir visa tauta nepakluso VIEŠPATIES balsui, kad gyventų Judos šalyje.'),
  (@b24, 43, 5, 'Bet Kareacho sūnus Johananas ir visi kariuomenės vadai paėmė visą Judos likutį, sugrįžusį iš visų tautų, į kurias jie buvo išvaryti, kad gyventų Judos šalyje,'),
  (@b24, 43, 6, 'būtent vyrus, moteris, vaikus, karaliaus dukras ir visus asmenis, kuriuos sargybos vadas Nebuzar-Adanas buvo palikęs pas Šafano sūnaus Ahikamo sūnų Gedaliją, ir pranašą Jeremiją bei Nerijo sūnų Baruchą.'),
  (@b24, 43, 7, 'Taigi jie įėjo į Egipto šalį; nes nepakluso VIEŠPATIES balsui; taip jie atėjo į Tachpanchesą.'),
  (@b24, 43, 8, 'Tada Tachpanchese Jeremijui atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b24, 43, 9, '„Pasiimk į ranką didelių akmenų ir juos paslėpk molyje, plytų krosnyje, esančioje faraono namų įėjime, Tachpanchese, Judos žmonėms matant;'),
  (@b24, 43, 10, 'ir jiems sakyk: ‘Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Štai aš pasiųsiu ir paimsiu Babilono karalių Nebukadrecarą, mano tarną, ir pastatysiu jo sostą ant šitų akmenų, kuriuos paslėpiau; ir jis išskleis virš jų savo karališkąją palapinę.'),
  (@b24, 43, 11, 'Ir kai jis ateis, jis sumuš Egipto šalį; ir kas skirtas mirčiai, tą atiduos mirčiai; kas skirtas nelaisvei, tą nelaisvei; ir kas skirtas kalavijui, tą kalavijui.'),
  (@b24, 43, 12, 'Ir aš užkursiu ugnį Egipto dievų namuose; jis juos sudegins ir išves į nelaisvę; ir jis apsirengs Egipto šalimi, kaip piemuo apsivelka drabužį; ir iš ten jis išeis ramybėje.'),
  (@b24, 43, 13, 'Jis sudaužys ir Egipto šalyje esančius Bet-Šemešo atvaizdus; ir egiptiečių dievų namus jis sudegins ugnimi’“.'),
  (@b24, 44, 1, 'Žodis, kuris atėjo Jeremijui apie visus žydus, gyvenančius Egipto šalyje, kurie gyvena Migdole, Tachpanchese, Nofe ir Patroso šalyje, sakydamas:'),
  (@b24, 44, 2, '„Taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Jūs matėte visą nelaimę, kurią užvedžiau ant Jeruzalės ir ant visų Judos miestų; ir štai šią dieną jie ištuštėję, ir niekas juose nebegyvena'),
  (@b24, 44, 3, 'dėl jų nedorybės, kurią jie darė, kad kurstytų mano pyktį, eidami smilkyti ir tarnauti kitiems dievams, kurių nepažino nei jie, nei jūs, nei jūsų tėvai.'),
  (@b24, 44, 4, 'Nors aš siunčiau pas jus visus savo tarnus pranašus, anksti atsikeldamas ir juos siųsdamas, sakydamas: ‘Oi nedarykite šito pasibjaurėtino dalyko, kurio nekenčiu’.'),
  (@b24, 44, 5, 'Bet jie neklausė ir nepalenkė savo ausies, kad nusigręžtų nuo savo nedorybės ir nesmilkytų kitiems dievams.'),
  (@b24, 44, 6, 'Todėl mano įtūžis ir mano pyktis išsiliejo ir užsidegė Judos miestuose ir Jeruzalės gatvėse; ir jie yra nuniokoti ir tušti, kaip yra šią dieną“.'),
  (@b24, 44, 7, 'Todėl dabar taip sako VIEŠPATS, kariuomenių Dievas, Izraelio Dievas: „Kodėl jūs savo sieloms darote šią didelę piktybę, kad iš savęs iškirstumėte vyrus ir moteris, vaikus ir žinduklius iš Judos, idant sau nepaliktumėte likučio,'),
  (@b24, 44, 8, 'kurstydami mano rūstybę savo rankų darbais, degindami smilkalus kitiems dievams Egipto šalyje, į kurią jūs nuėjote gyventi, kad save iškirstumėte ir kad būtumėte prakeikimu bei priekaištu tarp visų žemės tautų?'),
  (@b24, 44, 9, 'Ar pamiršote savo tėvų nedorybę, Judos karalių nedorybę, jų žmonų nedorybę, jūsų pačių nedorybę ir jūsų žmonų nedorybę, kurią jie darė Judos šalyje ir Jeruzalės gatvėse?'),
  (@b24, 44, 10, 'Iki šios dienos jie nenusižemino, nebijojo ir nevaikščiojo pagal mano įstatymą bei mano įstatus, kuriuos išstačiau jūsų akivaizdoje ir jūsų tėvų akivaizdoje.'),
  (@b24, 44, 11, 'Todėl taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Štai aš nukreipsiu savo veidą prieš jus dėl pikto ir kad iškirsčiau visą Judą.'),
  (@b24, 44, 12, 'Ir aš paimsiu Judos likutį, nukreipusį savo veidą eiti į Egipto šalį, kad laikinai ten apsigyventų, ir jie visi bus sunaikinti ir kris Egipto šalyje; jie bus sunaikinti kalaviju ir badu; nuo mažiausio iki didžiausio jie mirs nuo kalavijo ir nuo bado; ir jie bus prakeikimas, nuostaba, keiksmas ir priekaištas.'),
  (@b24, 44, 13, 'Nes aš nubausiu gyvenančius Egipto šalyje, kaip nubaudžiau Jeruzalę – kalaviju, badu ir maru;'),
  (@b24, 44, 14, 'taip, kad niekas iš Judos likusių, nuėjusių laikinai apsigyventi ten Egipto šalyje, neišsigelbės ir neišliks, kad sugrįžtų į Judos šalį, į kurią jie trokšta sugrįžti ir ten gyventi; nes niekas nesugrįš, išskyrus tuos, kurie pabėgs“.'),
  (@b24, 44, 15, 'Tada visi vyrai, kurie žinojo, kad jų žmonos degino smilkalus kitiems dievams, ir visos šalia stovinčios moterys, didžiulė minia, būtent visa tauta, gyvenanti Egipto šalyje, Patrose, atsakė Jeremijui, sakydami:'),
  (@b24, 44, 16, '„Dėl žodžio, kurį mums kalbėjai VIEŠPATIES vardu, mes neklausysime tavęs.'),
  (@b24, 44, 17, 'Bet tikrai darysime tai, kas išeina iš mūsų pačių burnos, kad degintume smilkalus dangaus karalienei ir jai išlietume geriamąsias atnašas, kaip darėme mes ir mūsų tėvai, mūsų karaliai ir mūsų kunigaikščiai Judos miestuose ir Jeruzalės gatvėse; nes tada mes turėjome gausiai maisto, mums gerai sekėsi ir pikto nematėme.'),
  (@b24, 44, 18, 'Bet nuo tada, kai liovėmės deginę smilkalus dangaus karalienei ir jai lieję geriamąsias atnašas, mes visko stokojome ir buvome naikinami kalaviju ir badu.'),
  (@b24, 44, 19, 'O kai mes deginome smilkalus dangaus karalienei ir liejome jai geriamąsias atnašas, argi be savo vyrų jai gaminome pyragaičius, kad ją garbintume, ir liejome jai geriamąsias atnašas?“'),
  (@b24, 44, 20, 'Tada Jeremijas tarė visai tautai, vyrams ir moterims, ir visai tautai, kurie jam buvo taip atsakę, sakydamas:'),
  (@b24, 44, 21, '„Smilkalus, kuriuos deginote Judos miestuose ir Jeruzalės gatvėse jūs ir jūsų tėvai, jūsų karaliai, jūsų kunigaikščiai ir šalies tauta, argi ne juos VIEŠPATS atsiminė ir ar ne jie jam atėjo į mintį?'),
  (@b24, 44, 22, 'Taip, kad VIEŠPATS nebegalėjo pakęsti – dėl jūsų darbų piktybės ir dėl bjaurysčių, kurias darėte; todėl jūsų šalis yra dykynė, nuostaba ir prakeikimas, be gyventojų, kaip yra šią dieną.'),
  (@b24, 44, 23, 'Kadangi jūs deginote smilkalus ir kadangi nusidėjote prieš VIEŠPATĮ, nepaklusote VIEŠPATIES balsui ir nevaikščiojote pagal jo įstatymą, jo įstatus ir jo liudijimus; todėl jums atsitiko šita nelaimė, kaip yra šią dieną“.'),
  (@b24, 44, 24, 'Jeremijas dar sakė visai tautai ir visoms moterims: „Klausykite VIEŠPATIES žodžio, visa Juda, esanti Egipto šalyje:'),
  (@b24, 44, 25, '‘Taip sako kariuomenių VIEŠPATS, Izraelio Dievas, tardamas: Jūs ir jūsų žmonos kalbėjote savo burna ir įvykdėte savo rankomis, sakydami: „Mes tikrai ištesėsime savo padarytus įžadus deginti smilkalus dangaus karalienei ir jai lieti geriamąsias atnašas“; jūs tikrai ištesėsite savo įžadus ir tikrai vykdysite savo įžadus.'),
  (@b24, 44, 26, 'Todėl klausykite VIEŠPATIES žodžio, visa Juda, gyvenanti Egipto šalyje: Štai aš prisiekiau savo didžiuoju vardu, – sako VIEŠPATS, – kad mano vardas nebebus minimas nei vieno Judos žmogaus burna visoje Egipto šalyje, sakant: „Viešpats DIEVAS gyvas“.'),
  (@b24, 44, 27, 'Štai aš budėsiu prie jų dėl pikto, o ne dėl gero; ir visi Judos žmonės, esantys Egipto šalyje, bus sunaikinti kalaviju ir badu, kol ateis jiems galas.'),
  (@b24, 44, 28, 'Tačiau mažas skaičius, kurie išvengs kalavijo, sugrįš iš Egipto šalies į Judos šalį, ir visas Judos likutis, nuvykęs į Egipto šalį laikinai ten apsigyventi, žinos, kieno žodžiai išsilaikys – mano ar jų.'),
  (@b24, 44, 29, 'Ir tai bus jums ženklas, – sako VIEŠPATS, – kad aš jus nubausiu šitoje vietoje, kad žinotumėte, kad mano žodžiai tikrai išsilaikys prieš jus dėl pikto:'),
  (@b24, 44, 30, 'Taip sako VIEŠPATS: Štai aš atiduosiu faraoną Hofrą, Egipto karalių, į jo priešų rankas ir į rankas tų, kurie ieško jo gyvybės; kaip daviau Judos karalių Zedekiją į rankas Babilono karaliaus Nebukadrecaro, jo priešo ir ieškojusiojo jo gyvybės’“.'),
  (@b24, 45, 1, 'Žodis, kurį pranašas Jeremijas kalbėjo Nerijo sūnui Baruchui, kai jis šituos žodžius užrašė iš Jeremijo burnos į knygą ketvirtaisiais Jehojakimo, sūnaus Jozijo, Judos karaliaus, metais, sakantis:'),
  (@b24, 45, 2, '„Taip sako VIEŠPATS, Izraelio Dievas, tau, Baruchai:'),
  (@b24, 45, 3, 'Tu sakei: ‘Vargas man! Nes VIEŠPATS pridėjo sielvarto prie mano skausmo; aš nusilpau dūsaudamas ir neradau poilsio’.'),
  (@b24, 45, 4, 'Taip jam sakyk: ‘Taip sako VIEŠPATS: Štai ką aš pastačiau, nugriausiu, ir ką aš pasodinau, išrausiu, būtent visą šią šalį.'),
  (@b24, 45, 5, 'Ar tu sieki sau didelių dalykų? Nesiek; nes, štai aš atvesiu nelaimę ant visų kūnų, – sako VIEŠPATS; – bet tavo gyvybę aš tau duosiu kaip grobį visose vietose, kur tik eisi’“.'),
  (@b24, 46, 1, 'VIEŠPATIES žodis, kuris atėjo pranašui Jeremijui prieš pagonis:'),
  (@b24, 46, 2, 'prieš Egiptą, prieš faraono Nechojo, Egipto karaliaus, kariuomenę, kuri buvo prie Eufrato upės Karkemiše, kurią Babilono karalius Nebukadrecaras sumušė ketvirtaisiais Jehojakimo, sūnaus Jozijo, Judos karaliaus, metais:'),
  (@b24, 46, 3, '„Paruoškite mažąjį ir didįjį skydą ir artėkite į mūšį.'),
  (@b24, 46, 4, 'Pakinkykite žirgus; pakilkite, raiteliai, ir išstokite su savo šalmais; nušveiskite ietis ir apsivilkite šarvais.'),
  (@b24, 46, 5, 'Kodėl juos mačiau sunerimusius ir nusisukusius atgal? Jų galiūnai sumušti, ir sparčiai bėga, nežiūrėdami atgal; nes aplinkui buvo baimė, – sako VIEŠPATS.'),
  (@b24, 46, 6, '– Tenepabėga greitasis ir tenepasprunka galiūnas; jie suklups ir kris šiaurės link, prie Eufrato upės.'),
  (@b24, 46, 7, 'Kas yra tas, kuris pakyla kaip potvynis, kurio vandenys teka kaip upės?'),
  (@b24, 46, 8, 'Egiptas pakyla kaip potvynis ir jo vandenys teka kaip upės; ir jis sako: ‘Aš pakilsiu ir apdengsiu žemę; aš sunaikinsiu miestą ir jo gyventojus’.'),
  (@b24, 46, 9, 'Užkilkite, žirgai, siautėkite vežimai; ir teišeina galiūnai; etiopai ir libiai, valdantys skydą; ir lidijiečiai, laikantys ir įtempiantys lanką.'),
  (@b24, 46, 10, 'Nes tai yra Viešpaties, kariuomenių DIEVO diena, keršto diena, kad jis atkeršytų savo priešininkams; ir kalavijas rys ir pasisotins bei prisigers jų kraujo; nes Viešpats, kariuomenių DIEVAS, turi auką šiaurės šalyje prie Eufrato upės.'),
  (@b24, 46, 11, 'Eik aukštyn į Gileadą ir paimk balzamo, o mergele, Egipto dukra; veltui vartosi daug vaistų, nes nebūsi išgydyta.'),
  (@b24, 46, 12, 'Tautos išgirdo apie tavo gėdą, ir tavo šauksmas pripildė šalį; nes galiūnas suklupo prieš galiūną, ir jie abu kartu krito“.'),
  (@b24, 46, 13, 'Žodis, kurį VIEŠPATS kalbėjo pranašui Jeremijui, kaip Babilono karalius Nebukadrecaras turėsiąs ateiti sumušti Egipto šalies:'),
  (@b24, 46, 14, '„Praneškite Egipte, paskelbkite Migdole ir skelbkite Nofe ir Tachpanchese; sakykite: ‘Stovėk tvirtai ir pasiruošk, nes kalavijas rys aplink tave’.'),
  (@b24, 46, 15, 'Kodėl nušluoti tavo narsuoliai? Jie neišstovėjo, nes VIEŠPATS juos išvijo.'),
  (@b24, 46, 16, 'Jis daugelį pargriovė, taip, krito vienas ant kito; ir jie tarė: ‘Kelkitės ir sugrįžkime pas mūsų tautą, į mūsų gimtąją šalį nuo engiančio kalavijo’.'),
  (@b24, 46, 17, 'Jie ten šaukė: ‘Faraonas, Egipto karalius, tėra tik triukšmas; jis praleido paskirtą laiką’.'),
  (@b24, 46, 18, 'Kaip aš gyvas, – sako Karalius, kurio vardas kariuomenių VIEŠPATS, – tikrai, kaip Taboras yra tarp kalnų ir kaip Karmelis prie jūros, taip jis ateis.'),
  (@b24, 46, 19, 'O dukra, gyvenanti Egipte, apsirūpink eiti į nelaisvę; nes Nofas bus dykas ir apleistas, be gyventojų.'),
  (@b24, 46, 20, 'Egiptas yra kaip labai graži telyčia, bet sunaikinimas ateina; jis ateina iš šiaurės.'),
  (@b24, 46, 21, 'Taip pat jo samdiniai jo tarpe yra kaip nupenėti jaučiai; nes ir jie apsigręžė ir kartu pabėgo; jie neišstovėjo, nes ant jų atėjo jų nelaimės diena, jų aplankymo metas.'),
  (@b24, 46, 22, 'Jo balsas nešis kaip gyvatė; nes jie atžygiuos su kariuomene ir ateis prieš jį su kirviais, kaip medžių kirtėjai.'),
  (@b24, 46, 23, 'Jie iškirs jo mišką, – sako VIEŠPATS, – nors jis neištiriamas; nes jų yra daugiau nei žiogų ir yra nesuskaičiuojami.'),
  (@b24, 46, 24, 'Egipto duktė bus sugėdinta; ji bus atiduota į šiaurės tautos rankas“.'),
  (@b24, 46, 25, 'Kariuomenių VIEŠPATS, Izraelio Dievas, sako: „Štai aš nubausiu Nojo daugybę, faraoną ir Egiptą su jų dievais ir jų karaliais; būtent faraoną ir visus tuos, kurie juo pasitiki;'),
  (@b24, 46, 26, 'ir atiduosiu juos į rankas tų, kurie ieško jų gyvybės, į Babilono karaliaus Nebukadrecaro rankas ir į jo tarnų rankas; o po to jis bus apgyventas, kaip senovės dienomis, – sako VIEŠPATS.'),
  (@b24, 46, 27, '– Bet tu nebijok, o mano tarne Jokūbai, ir nebūk sunerimęs, o Izraeli; nes štai aš tave išgelbėsiu iš toli ir tavo sėklą iš jų nelaisvės šalies; ir Jokūbas sugrįš, ilsėsis ir bus ramus, ir niekas jo negąsdins.'),
  (@b24, 46, 28, 'Tu nebijok, o mano tarne Jokūbai, – sako VIEŠPATS, – nes aš su tavimi; nes aš padarysiu visišką galą visoms tautoms, į kurias tave išvariau; bet tau nepadarysiu visiško galo, bet saikingai nubausiu tave; tačiau nepaliksiu tavęs visiškai nenubausto“.'),
  (@b24, 47, 1, 'VIEŠPATIES žodis, kuris atėjo pranašui Jeremijui prieš filistinus, faraonui dar nesumušus Gazos.'),
  (@b24, 47, 2, 'Taip sako VIEŠPATS: „Štai vandenys pakyla iš šiaurės ir bus užliejantis potvynis, ir užlies šalį ir visa, kas joje; miestą ir jame gyvenančius; tada žmonės šauks, ir kauks visi šalies gyventojai.'),
  (@b24, 47, 3, 'Nuo jo stiprių žirgų trypiančių kanopų triukšmo, nuo jo vežimų dumimo, nuo jo ratų dundesio tėvai neatsigręš į savo vaikus dėl rankų silpnumo;'),
  (@b24, 47, 4, 'dėl dienos, kuri ateina apiplėšti visus filistinus, iš Tyro ir Sidono iškirsti kiekvieną išlikusį padėjėją; nes VIEŠPATS apiplėš filistinus, Kaftoro krašto likutį.'),
  (@b24, 47, 5, 'Gaza nupliko; Aškelonas iškirstas su jų slėnio likučiu; kiek ilgai pjaustysi save?'),
  (@b24, 47, 6, 'O VIEŠPATIES kalavijau, kiek ilgai bus, kol nurimsi? Įlįsk į savo makštį, ilsėkis ir nurimk.'),
  (@b24, 47, 7, 'Kaip jis gali nurimti, kada VIEŠPATS jį įpareigojo prieš Aškeloną ir prieš pajūrį? Jis ten jį paskyrė“.'),
  (@b24, 48, 1, 'Taip sako kariuomenių VIEŠPATS, Izraelio Dievas, prieš Moabą: „Vargas Nebojui! Nes jis apiplėštas; Kirjataimas sugėdintas ir paimtas; Misgabas sugėdintas ir sunerimęs.'),
  (@b24, 48, 2, 'Nebebus Moabo gyriaus; Hešbone sumanė prieš jį pikta: ‘Ateikite ir iškirskime jį, kad jis nebebūtų tauta’; ir tu, Madmena, būsi nukirsta; kalavijas seks tau įkandin.'),
  (@b24, 48, 3, 'Šauksmo balsas bus iš Horonaimo, apiplėšimas ir didelis sunaikinimas.'),
  (@b24, 48, 4, 'Moabas sunaikintas; girdisi jo mažylių verksmas.'),
  (@b24, 48, 5, 'Nes Luhito pakilime kils nepaliaujamas verksmas; nes Horonaimo nusileidime priešai girdėjo naikinimo šauksmą.'),
  (@b24, 48, 6, 'Bėkite, gelbėkite savo gyvybes, ir būkite kaip viržis dykumoje.'),
  (@b24, 48, 7, 'Kadangi pasitikėjai savo darbais ir savo lobiais, tai ir tu būsi paimtas; ir Kemošas išeis į nelaisvę kartu su savo kunigais ir kunigaikščiais.'),
  (@b24, 48, 8, 'Ir plėšikas užeis ant kiekvieno miesto, ir joks miestas neišsigelbės; taipogi pražus slėnis ir bus sunaikinta lyguma, – kaip pasakė VIEŠPATS.'),
  (@b24, 48, 9, '– Duokite Moabui sparnus, kad jis skristų ir pabėgtų; nes jo miestai bus ištuštėję, nebus juose gyventojų.'),
  (@b24, 48, 10, 'Tebūna prakeiktas tas, kuris melagingai dirba VIEŠPATIES darbą, ir tebūna prakeiktas tas, kuris sulaiko savo kalaviją nuo kraujo.'),
  (@b24, 48, 11, 'Moabas nuo pat savo jaunystės buvo ramybėje, įsitaisęs ant savo nuosėdų, ir nebuvo perpilamas iš indo į indą nei nėra ėjęs į nelaisvę; todėl jame išliko jo skonis, ir jo kvapas nepasikeitė.'),
  (@b24, 48, 12, 'Todėl štai ateina dienos, – sako VIEŠPATS, – kai aš siųsiu pas jį klajūnų, kurie privers jį klajoti, ištuštins jo indus ir sudaužys jų butelius.'),
  (@b24, 48, 13, 'Ir Moabas gėdysis Kemošo, kaip Izraelio namai gėdijosi Bet-Elio – jų pasitikėjimo.'),
  (@b24, 48, 14, 'Kaipgi jūs sakote: ‘Mes galiūnai ir stipruoliai karui’?'),
  (@b24, 48, 15, 'Moabas apiplėštas ir išėjęs aukštyn iš savo miestų, o jo rinktiniai jaunuoliai nuėję žemyn į paskerdimą, – sako Karalius, kurio vardas yra kariuomenių VIEŠPATS.'),
  (@b24, 48, 16, '– Artėja Moabo nelaimė, ir jo bėda greitai atskuba.'),
  (@b24, 48, 17, 'Visi, esantys aplink jį, apraudokite jį; ir jūs visi, žinantys jo vardą, sakykite: ‘Kaip sulūžo stiprioji lazda, gražioji rykštė!’'),
  (@b24, 48, 18, 'Nulipk žemyn iš savo šlovės ir sėskis į troškulį, dukra, Dibono gyventoja; nes Moabo plėšikas užeis ant tavęs ir sunaikins tavo tvirtoves.'),
  (@b24, 48, 19, 'Atsistok palei kelią ir pamatyk, o Aroerio gyventojau; klausk bėgantįjį ir ištrūkusįjį ir sakyk: ‘Kas atsitiko?’'),
  (@b24, 48, 20, 'Moabas sugėdintas; nes jis sutriuškintas; kaukite ir šaukite, praneškite Arnone, kad Moabas apiplėštas,'),
  (@b24, 48, 21, 'ir teismas atėjo lygumos kraštui: Holonui, Jahacui, Mefaatui,'),
  (@b24, 48, 22, 'Dibonui, Nebojui, Bet-Diblataimui,'),
  (@b24, 48, 23, 'Kirjataimui, Bet-Gamului, Bet-Meonui,'),
  (@b24, 48, 24, 'Kerijotui, Bocrai ir visiems Moabo šalies miestams, tolimiems ir artimiems.'),
  (@b24, 48, 25, 'Nukirstas Moabo ragas ir jo ranka sulaužyta, – sako VIEŠPATS.'),
  (@b24, 48, 26, '– Nugirdykite jį, nes jis didžiavosi prieš VIEŠPATĮ; Moabas taipogi voliosis savo vėmaluose ir taip pat jis bus pajuoka.'),
  (@b24, 48, 27, 'Nes argi Izraelis tau nebuvo pajuoka? Argi jis buvo užtiktas tarp vagių? Nes nuo tada, kai apie jį kalbėjai, tu šokinėjai iš džiaugsmo.'),
  (@b24, 48, 28, 'O Moabo gyventojai, palikite miestus ir gyvenkite uoloje, ir būkite kaip karvelis, kuris susisuka lizdą olos angos šonuose.'),
  (@b24, 48, 29, 'Mes girdėjome apie Moabo išdidumą (jis be galo išdidus), apie jo puikybę, pasipūtimą, išdidumą ir jo širdies pasididžiavimą.'),
  (@b24, 48, 30, 'Aš žinau jo rūstybę, – sako VIEŠPATS; – bet taip nebus; jo melai taip neįvykdys.'),
  (@b24, 48, 31, 'Todėl aš kauksiu dėl Moabo, šauksiu dėl viso Moabo; mano širdis gedės dėl Kir-Hereso žmonių.'),
  (@b24, 48, 32, 'Aš verksiu dėl tavęs, o Sibmos vynmedi, Jazero verksmu; tavo sodinukai nusidriekė už jūros, jie pasiekė Jazero jūrą; plėšikas užpuolė tavo vasaros vaisius ir tavo vynuogių derlių.'),
  (@b24, 48, 33, 'Džiaugsmas ir linksmybė atimti iš našaus lauko ir iš Moabo šalies; ir pašalinau vyną iš spaustuvų; niekas nebemindys su šūksniais; jų šūksniai nebebus šūksniai.'),
  (@b24, 48, 34, 'Nuo Hešbono šauksmo iki Elealės ir iki Jahaco jie ištarė savo balsą, nuo Coaro iki Horonaimo, kaip trijų metų telyčia; nes ir Nimrimo vandenys bus ištuštėję.'),
  (@b24, 48, 35, 'Be to, aš padarysiu, – sako VIEŠPATS, – kad Moabe nebeliks atnašaujančiųjų aukštumose ir deginančiųjų smilkalus savo dievams.'),
  (@b24, 48, 36, 'Todėl mano širdis skambės kaip dūdelė dėl Moabo, ir mano širdis skambės kaip dūdelė dėl Kir-Hereso žmonių; nes pražuvo jo įgyti turtai.'),
  (@b24, 48, 37, 'Nes kiekviena galva bus nuplikusi ir kiekviena barzda apkirpta; visos rankos bus suraižytos, ir ant strėnų ašutinė.'),
  (@b24, 48, 38, 'Ant visų Moabo stogų ir jo gatvėse bus visuotinė rauda; nes aš sudaužiau Moabą kaip indą, kuris niekam nepatinka, – sako VIEŠPATS.'),
  (@b24, 48, 39, '– Jie kauks, sakydami: ‘Kaip jis sugriautas! Kaip Moabas susigėdęs atsuko nugarą!’ Taip Moabas bus pajuoka ir nerimas visiems jo aplinkiniams.'),
  (@b24, 48, 40, 'Nes taip sako VIEŠPATS: Štai jis skris kaip erelis ir išskės savo sparnus virš Moabo.'),
  (@b24, 48, 41, 'Keriotas paimtas ir tvirtovės užkluptos, ir galiūnų širdys Moabe tą dieną bus kaip širdis moters jos skausmuose.'),
  (@b24, 48, 42, 'Ir Moabas bus sunaikintas, kad nebūtų tauta, nes jis aukštinosi prieš VIEŠPATĮ.'),
  (@b24, 48, 43, 'Išgąstis, duobė ir spąstai bus tau, Moabo gyventojau, – sako VIEŠPATS.'),
  (@b24, 48, 44, '– Kas pabėgs nuo išgąsčio, įkris į duobę; o kas išlips iš duobės, bus spąstais sugautas; nes aš atvesiu ant jo, ant Moabo, jų aplankymo metus, – sako VIEŠPATS.'),
  (@b24, 48, 45, '– Bėgantys sustojo po Hešbono šešėliu dėl smurto; bet ugnis išeis iš Hešbono ir liepsna iš Sihono tarpo ir praris Moabo šoną ir triukšmadarių galvos vainiką.'),
  (@b24, 48, 46, 'Vargas tebūna tau, Moabai! Pražuvo Kemošo tauta; nes tavo sūnūs paimti nelaisvėn ir tavo dukterys į nelaisvę.'),
  (@b24, 48, 47, 'Tačiau aš sugrąžinsiu Moabo nelaisvę paskutinėmis dienomis“, – sako VIEŠPATS. Iki čia yra Moabo teismas.'),
  (@b24, 49, 1, 'Apie amoniečius taip sako VIEŠPATS: „Argi Izraelis neturi sūnų? Ar jis neturi paveldėtojo? Tai kodėl jų karalius paveldėjo Gadą ir jo tauta gyvena jo miestuose?'),
  (@b24, 49, 2, 'Todėl štai ateina dienos, – sako VIEŠPATS, – kai aš duosiu amoniečių Raboje išgirsti karo pavojų; ir ji bus apleista krūva, o jos dukterys bus sudegintos ugnimi; tada Izraelis bus paveldėtojas tų, kurie buvo jo paveldėtojai, – sako VIEŠPATS.'),
  (@b24, 49, 3, '– Kauk, o Hešbone, nes Ajas apiplėštas; šaukite, Rabos dukterys, apsijuoskite ašutinėmis; raudokite ir bėgiokite ten ir atgal palei tvoras; nes jų karalius eis į nelaisvę drauge su jo kunigais ir kunigaikščiais.'),
  (@b24, 49, 4, 'Kodėl tu giriesi slėniais, savo tekančiu slėniu, o atsimetėle dukra? Ji pasitiki savo lobiais, sakydama: ‘Kas ateis pas mane?’'),
  (@b24, 49, 5, 'Štai aš užleisiu ant tavęs baimę nuo visų, esančių aplink tave, – sako Viešpats, kariuomenių DIEVAS; – ir jūs būsite išvaryti kiekvienas tiesiai į priekį, ir niekas nesurinks klaidžiojančių.'),
  (@b24, 49, 6, 'O paskui aš sugrąžinsiu Amono vaikų nelaisvę“, – sako VIEŠPATS.'),
  (@b24, 49, 7, 'Apie Edomą, taip sako kariuomenių VIEŠPATS: „Ar nebėra išminties Temane? Ar dingo patarimas iš protingųjų? Ar jų išmintis pranyko?'),
  (@b24, 49, 8, 'Bėkite, gręžkitės atgal, apsigyvenkite giliai, Dedano gyventojai; nes aš ant jo užleisiu Ezavo nelaimę, metą, kai aš juos aplankysiu.'),
  (@b24, 49, 9, 'Jei vynuogių rinkėjai ateis pas tave, ar jie nepaliks kiek vynuogių parankų? Jei vagys naktį, jie naikins tol, kol jiems bus gana.'),
  (@b24, 49, 10, 'Bet aš apnuoginau Ezavą, atidengiau jo slaptavietes, ir jis negalės pasislėpti; apiplėšta jo sėkla, jo broliai ir jo kaimynai, ir jo nebėra.'),
  (@b24, 49, 11, 'Palik savo našlaičius, aš juos išsaugosiu gyvus; ir tavo našlės tepasitiki manimi.'),
  (@b24, 49, 12, 'Nes taip sako VIEŠPATS: Štai tie, kuriems buvo nuspręsta negerti iš taurės, tikrai gėrė; ar tu liksi visiškai nenubaustas? Tu neliksi nenubaustas, bet tikrai gersi iš jos.'),
  (@b24, 49, 13, 'Nes aš prisiekiau savimi, – sako VIEŠPATS, – kad Bocra taps tuštuma, priekaištu, dykyne ir prakeikimu; o visi jos miestai bus amžinomis dykynėmis.'),
  (@b24, 49, 14, 'Išgirdau gandą iš VIEŠPATIES, ir pasiuntinys yra pasiųstas pagonims, sakantis: ‘Susirinkite ir ateikite prieš jį, ir pakilkite į mūšį’.'),
  (@b24, 49, 15, 'Nes, štai aš padarysiu tave mažą tarp pagonių ir paniekintą tarp žmonių.'),
  (@b24, 49, 16, 'Tavo baisumas apgavo tave ir tavo širdies išdidumas, o tu, gyvenantis uolos plyšiuose, kuris laikaisi kalvos aukštumoje; nors susisuktum lizdą aukštai kaip erelis, iš ten numesiu tave žemyn, – sako VIEŠPATS.'),
  (@b24, 49, 17, '– Ir Edomas bus tuštuma; kiekvienas pro jį praeinantis bus apstulbintas ir švilps dėl visų jo rykščių.'),
  (@b24, 49, 18, 'Kaip Sodomos ir Gomoros ir jos kaimyninių miestų sunaikinime, – sako VIEŠPATS, – ten niekas nepasiliks, nei žmogaus sūnus jame negyvens.'),
  (@b24, 49, 19, 'Štai kaip liūtas jis ateis aukštyn iš Jordano patvinimo prieš stipriųjų buveinę; bet staiga aš jį priversiu bėgti nuo jo; ir kas yra išrinktasis, kurį paskirčiau jį valdyti? Nes kas man lygus? Ir kas man paskirs laiką? Ir kas yra tas ganytojas, kuris išstovės mano akivaizdoje?'),
  (@b24, 49, 20, 'Todėl išgirskite VIEŠPATIES nutarimą, kurį jis priėmė prieš Edomą, ir jo ketinimus, kuriuos jis sugalvojo prieš Temano gyventojus: tikrai net menkiausi iš kaimenės juos išvilks laukan; tikrai jų buveines ištuštins nuo jų.'),
  (@b24, 49, 21, 'Nuo jų kritimo triukšmo sujudėjo žemė; nuo šauksmo jų triukšmas girdėjosi Raudonojoje jūroje.'),
  (@b24, 49, 22, 'Štai jis pakils ir skris kaip erelis, ir išskės savo sparnus virš Bocros; ir tą dieną Edomo galiūnų širdis bus kaip širdis moters jos skausmuose“.'),
  (@b24, 49, 23, 'Apie Damaską. „Hamatas ir Arpadas sumišę, nes jie išgirdo blogą žinią; jie alpsta; sielvartas jūroje; negali nusiraminti.'),
  (@b24, 49, 24, 'Damaskas nusilpo ir pasileido bėgti, jį suėmė baimė; kančia ir skausmai jį suėmė kaip gimdančią moterį.'),
  (@b24, 49, 25, 'Kaipgi neišliko gyriaus miesto, mano džiaugsmo miesto!'),
  (@b24, 49, 26, 'Taigi jo jaunuoliai kris jo gatvėse ir visi karo vyrai bus iškirsti tą dieną, – sako kariuomenių VIEŠPATS.'),
  (@b24, 49, 27, '– Ir aš užkursiu ugnį Damasko sienose, ir ji praris Ben-Hadado rūmus“.'),
  (@b24, 49, 28, 'Apie Kedarą ir apie Hacoro karalystes, kuriuos sumuš Babilono karalius Nebukadrecaras, taip sako VIEŠPATS: „Kelkitės, eikite aukštyn į Kedarą ir apiplėškite rytų žmones.'),
  (@b24, 49, 29, 'Jie paims jų palapines ir jų kaimenes; jie pasiims jų uždangalus, visus jų indus ir jų kupranugarius; ir jiems šauks: ‘Baimė iš visų pusių’.'),
  (@b24, 49, 30, 'Bėkite, nueikite toli, apsigyvenkite giliai, Hacoro gyventojai, – sako VIEŠPATS; – nes Babilono karalius Nebukadrecaras tarėsi prieš jus ir sugalvojo prieš jus sumanymą.'),
  (@b24, 49, 31, 'Kelkitės, eikite aukštyn pas turtingą tautą, kuri gyvena be rūpesčių, – sako VIEŠPATS, – kuri neturi nei vartų, nei skląsčių, kuri gyvena vieniša.'),
  (@b24, 49, 32, 'Jų kupranugariai bus grobiu ir jų galvijų daugybė laimikiu; ir aš išsklaidysiu po visus vėjus tuos, kurie yra tolimiausiuose pakraščiuose; ir iš visų jų pusių atvesiu jų nelaimę, – sako VIEŠPATS.'),
  (@b24, 49, 33, '– Ir Hacoras bus slibinų buveinė ir amžina dykuma; ten neįsikurs joks žmogus ir negyvens joks žmogaus sūnus“.'),
  (@b24, 49, 34, 'VIEŠPATIES žodis, kuris atėjo pranašui Jeremijui prieš Elamą, Judos karaliaus Zedekijo karaliavimo pradžioje, sakydamas:'),
  (@b24, 49, 35, '„Taip sako kariuomenių VIEŠPATS: Štai aš sulaužysiu Elamo lanką, jų pagrindinę galybę.'),
  (@b24, 49, 36, 'Ir aš užleisiu ant Elamo keturis vėjus iš keturių dangaus pusių ir juos išsklaidysiu po visus šituos vėjus; ir nebus tautos, į kurią neateitų Elamo išvarytieji.'),
  (@b24, 49, 37, 'Nes aš sukelsiu Elamui nerimą jų priešų akivaizdoje ir akivaizdoje tų, kurie siekia jų gyvybės; ir atvesiu ant jų nelaimę – savo smarkų pyktį, – sako VIEŠPATS; – ir aš siųsiu paskui juos kalaviją, kol juos išnaikinsiu;'),
  (@b24, 49, 38, 'ir aš pastatysiu savo sostą Elame ir išnaikinsiu iš ten karalių ir kunigaikščius, – sako VIEŠPATS.'),
  (@b24, 49, 39, '– Bet paskutinėmis dienomis įvyks, kad aš sugrąžinsiu Elamo nelaisvę, – sako VIEŠPATS“.'),
  (@b24, 50, 1, 'Žodis, kurį VIEŠPATS kalbėjo prieš Babiloną, prieš kaldėjų šalį, per pranašą Jeremiją.'),
  (@b24, 50, 2, '„Praneškite tarp tautų, skelbkite ir iškelkite vėliavą; skelbkite ir nenuslėpkite; sakykite: Babilonas paimtas, Belis sugėdintas, Merodachas sutriuškintas; jo stabai sugėdinti, jo atvaizdai sutrupinti.'),
  (@b24, 50, 3, 'Nes iš šiaurės prieš jį atkyla tauta, kuri pavers jo šalį dykyne, ir niekas joje negyvens; tiek žmonės, tiek gyvuliai pasitrauks ir išeis.'),
  (@b24, 50, 4, 'Tomis dienomis ir tuo metu, – sako VIEŠPATS, – ateis Izraelio vaikai, jie ir Judos vaikai drauge, eidami ir verkdami; jie eis ir ieškos VIEŠPATIES, savo Dievo.'),
  (@b24, 50, 5, 'Jie klaus kelio į Sioną, savo veidais į jo pusę, sakydami: ‘Ateikite, prisijunkime prie VIEŠPATIES amžina sandora, kuri nebus pamiršta’.'),
  (@b24, 50, 6, 'Mano tauta buvo pražuvusios avys; jų ganytojai jas paklaidino, jas nuvedė šalin į kalnus; jos vaikščiojo nuo kalno į kalvą, jos pamiršo savo poilsio vietą.'),
  (@b24, 50, 7, 'Visi, kas tik jas užtiko, jas rijo; ir jų priešininkai sakė: ‘Mes nenusikalstame, nes jos nusidėjo prieš VIEŠPATĮ, teisingumo buveinę, būtent VIEŠPATĮ, savo tėvų viltį’.'),
  (@b24, 50, 8, 'Pasišalinkite iš Babilono tarpo, išeikite iš kaldėjų šalies ir būkite kaip ožiai kaimenių priešakyje.'),
  (@b24, 50, 9, 'Nes štai aš pakelsiu ir atvesiu aukštyn prieš Babiloną didelių tautų sambūrį iš šiaurės šalies; ir jos išsirikiuos prieš jį; iš ten jis bus paimtas; jų strėlės bus kaip įgudusio galiūno; nei viena nesugrįš tuščiomis.'),
  (@b24, 50, 10, 'Ir Kaldėja bus apiplėšta; visi, kurie ją plėš, pasitenkins, – sako VIEŠPATS.'),
  (@b24, 50, 11, '– Kadangi jūs buvote linksmi, kadangi džiaugėtės, jūs, mano paveldo naikintojai, kadangi nutukote kaip telyčia nuo žolės ir baubiate kaip buliai;'),
  (@b24, 50, 12, 'jūsų motina bus labai sugluminta, jus pagimdžiusioji bus sugėdinta; štai paskutinioji iš tautų bus tyrlaukis, sausa žemė ir dykuma.'),
  (@b24, 50, 13, 'Dėl VIEŠPATIES rūstybės ji bus negyvenama, bet bus visiškai tuščia; visi, praeinantys pro Babiloną, bus apstulbinti ir švilps dėl visų jo rykščių.'),
  (@b24, 50, 14, 'Išsirikiuokite prieš Babiloną aplinkui; visi įtempiantys lanką, šáukite į jį, negailėkite strėlių; nes jis nusidėjo prieš VIEŠPATĮ.'),
  (@b24, 50, 15, 'Šūkaukite prieš jį aplinkui; jis padavė savo ranką; nuvirto jo pamatai, sugriautos jo sienos; nes tai VIEŠPATIES kerštas; atkeršykite jam; kaip jis darė, taip jam darykite.'),
  (@b24, 50, 16, 'Iškirskite iš Babilono sėjėją ir tą, kuris valdo pjautuvą pjūties metu; dėl engiančiojo kalavijo baimės kiekvienas gręšis į savo tautą ir kiekvienas bėgs į savo paties šalį.'),
  (@b24, 50, 17, 'Izraelis – išsklaidytos avys; liūtai jį nuvijo; pirmasis jį rijo Asirijos karalius; o paskutinis, šitas Babilono karalius Nebukadrecaras, sulaužė jo kaulus.'),
  (@b24, 50, 18, 'Todėl taip sako kariuomenių VIEŠPATS, Izraelio Dievas: Štai aš nubausiu Babilono karalių ir jo šalį, kaip nubaudžiau Asirijos karalių.'),
  (@b24, 50, 19, 'Ir aš parvesiu Izraelį į jo buveinę, ir jis ganysis Karmelyje ir Bašane, ir jo siela pasisotins Efraimo kalne bei Gileade.'),
  (@b24, 50, 20, 'Tomis dienomis ir tuo metu, – sako VIEŠPATS, – bus ieškoma Izraelio neteisybės, bet jos nebus, ir Judos nuodėmių, bet jų neras; nes aš atleisiu tiems, kuriuos išsaugosiu.'),
  (@b24, 50, 21, 'Eik aukštyn prieš Merataimo šalį, prieš ją ir prieš Pekodo gyventojus; niokok ir visiškai sunaikink paskui juos, – sako VIEŠPATS, – ir daryk pagal visa tai, ką tau įsakiau.'),
  (@b24, 50, 22, 'Šalyje garsas mūšio ir didelio sunaikinimo.'),
  (@b24, 50, 23, 'Kaip sutrupintas ir sudaužytas visos žemės kūjis! Kaip Babilonas tapo dykyne tarp tautų!'),
  (@b24, 50, 24, 'Tau padėjau spąstus, ir tu esi pagautas, o Babilone, bet tu nežinojai; tu surastas ir sugautas, nes kovojai prieš VIEŠPATĮ.'),
  (@b24, 50, 25, 'VIEŠPATS atidarė savo ginklų sandėlį ir išnešė savo pasipiktinimo ginklus; nes tai Viešpaties, kariuomenių DIEVO, darbas kaldėjų šalyje.'),
  (@b24, 50, 26, 'Ateikite prieš jį nuo tolimiausių ribų, atidarykite jo sandėlius; supilkite jį kaip krūvas ir visiškai jį sunaikinkite; nieko iš jo tenepalieka.'),
  (@b24, 50, 27, 'Užmuškite visus jo jaučius; tegul jie eina žemyn į paskerdimą; vargas jiems! Nes atėjo jų diena, jų aplankymo metas.'),
  (@b24, 50, 28, 'Balsas pabėgėlių ir ištrūkėlių iš Babilono šalies, kad paskelbtų Sione VIEŠPATIES, mūsų Dievo, kerštą, jo šventyklos kerštą.'),
  (@b24, 50, 29, 'Sušaukite prieš Babiloną lankininkus; visi, kurie įtempiate lanką, stovyklaukite prieš jį aplinkui; niekas iš jo teneištrūksta; atmokėkite jam pagal jo darbus; darykite jam pagal visa tai, ką jis darė; nes jis buvo išdidus prieš VIEŠPATĮ, prieš Izraelio Šventąjį.'),
  (@b24, 50, 30, 'Todėl jo jaunuoliai kris gatvėse, ir visi jo karo vyrai bus iškirsti tą dieną, – sako VIEŠPATS.'),
  (@b24, 50, 31, '– Štai aš esu prieš tave, tu išdidžiausiasis, – sako Viešpats, kariuomenių DIEVAS; – nes atėjo tavo diena, metas, kad tave aplankyčiau.'),
  (@b24, 50, 32, 'Ir išdidžiausiasis suklups ir kris, ir nei vienas jo nepakels; ir aš užkursiu ugnį jo miestuose, ir ji surys viską aplinkui jį“.'),
  (@b24, 50, 33, 'Taip sako kariuomenių VIEŠPATS: „Izraelio vaikai engiami drauge su Judos vaikais; ir visi, kurie juos paėmė į nelaisvę, tvirtai juos laiko; jie atsisako juos paleisti.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b24, 50, 34, 'Jų Atpirkėjas yra stiprus; kariuomenių VIEŠPATS yra jo vardas; jis pilnai apgins jų bylą, kad suteiktų poilsį šaliai ir sukeltų nerimą Babilono gyventojams.'),
  (@b24, 50, 35, 'Kalavijas yra ant kaldėjų, – sako VIEŠPATS, – ant Babilono gyventojų, ant jo kunigaikščių ir ant jo išmintingųjų.'),
  (@b24, 50, 36, 'Kalavijas ant melagių; ir jie sukvailės; kalavijas ant jo galiūnų; ir jie sunerims.'),
  (@b24, 50, 37, 'Kalavijas ant jų žirgų, ant jų vežimų ir ant visų maišytų tautų, esančių jo tarpe; ir jie taps kaip moterys; kalavijas ant jo lobių; ir jie bus apiplėšti.'),
  (@b24, 50, 38, 'Sausra ant jo vandenų; ir jie išdžius; nes tai raižytų atvaizdų šalis, ir nuo savo stabų jie pamišę.'),
  (@b24, 50, 39, 'Todėl ten gyvens laukiniai dykumų žvėrys su laukiniais salų žvėrimis, ir pelėdos ten gyvens; ir jis nebebus apgyvendintas per amžius; ir niekas jame negyvens per kartų kartas.'),
  (@b24, 50, 40, 'Kaip Dievas sugriovė Sodomą bei Gomorą ir jų kaimyninius miestus, – sako VIEŠPATS; – taip joks žmogus ten nebepasiliks ir joks žmogaus sūnus jame nebegyvens.'),
  (@b24, 50, 41, 'Štai iš šiaurės ateis tauta, didžiulė tauta, ir daug karalių pakils nuo žemės pakraščių.'),
  (@b24, 50, 42, 'Jie laikys lanką ir ietį; jie žiaurūs ir nerodys gailestingumo; jų balsas ūžia kaip jūra, ir jie joja ant žirgų, visi išsirikiavę kaip vyrai į mūšį prieš tave, o Babilono dukra.'),
  (@b24, 50, 43, 'Babilono karalius išgirdo žinią apie juos ir jo rankos nusilpo; jį suėmė sielvartas ir skausmai kaip gimdančiąją moterį.'),
  (@b24, 50, 44, 'Štai jis ateis aukštyn kaip liūtas iš Jordano patvinimo į stipriųjų buveinę; bet aš staiga juos nuvysiu nuo jo; ir kas yra išrinktasis, kurį paskirčiau jį valdyti? Nes kas yra man lygus? Ir kas man paskirs laiką? Ir kas yra tas ganytojas, kuris stosis prieš mane?'),
  (@b24, 50, 45, 'Todėl klausykite VIEŠPATIES nutarimo, kurį jis priėmė prieš Babiloną; ir jo sumanymų, kuriuos jis sugalvojo prieš kaldėjų šalį: tikrai net menkiausi iš kaimenės juos išvilks laukan; tikrai jų buveines ištuštins nuo jų.'),
  (@b24, 50, 46, 'Nuo Babilono paėmimo triukšmo sujudėjo žemė ir šauksmas girdimas tarp tautų“.'),
  (@b24, 51, 1, 'Taip sako VIEŠPATS: „Štai prieš Babiloną ir prieš gyvenančius tarp tų, kurie sukyla prieš mane, aš sukelsiu naikinantį vėją;'),
  (@b24, 51, 2, 'ir siųsiu į Babiloną vėtytojus, kurie jį vėtys ir ištuštins jo šalį; nes bėdos dieną jie bus prieš jį iš visų pusių.'),
  (@b24, 51, 3, 'Tegul lankininkas įtempia savo lanką prieš tą, kuris įtempia, ir prieš pakylantįjį su savo šarvais; ir nesigailėkite jo jaunuolių, visiškai sunaikinkite visą jo kariuomenę.'),
  (@b24, 51, 4, 'Taip užmuštieji kris kaldėjų šalyje, perdurtieji jos gatvėse.'),
  (@b24, 51, 5, 'Nes nei Izraelis, nei Juda nebuvo palikti savo Dievo, kariuomenių VIEŠPATIES; nors jų šalis buvo pripildyta nuodėmių prieš Izraelio Šventąjį.'),
  (@b24, 51, 6, 'Bėkite iš Babilono tarpo ir kiekvienas gelbėkite savo sielą; nebūkite iškirsti dėl jo neteisybės; nes tai VIEŠPATIES keršto metas; jis atmokės jam atlygiu.'),
  (@b24, 51, 7, 'Babilonas buvo VIEŠPATIES rankoje auksinė taurė, nugirdžiusi visą žemę; tautos gėrė jo vyno; todėl tautos pamišo.'),
  (@b24, 51, 8, 'Babilonas staiga kritęs ir sunaikintas; kaukite dėl jo; paimkite balzamo jo skausmui, gal jis pagis.'),
  (@b24, 51, 9, 'Mes norėjome pagydyti Babiloną, bet jis nepagijo; palikite jį ir eikime kiekvienas į savo kraštą; nes jo teismas siekia iki dangaus ir pakilo iki padangės.'),
  (@b24, 51, 10, 'VIEŠPATS išvedė mūsų teisumą; ateikite ir skelbkime Sione VIEŠPATIES, mūsų Dievo, darbą.'),
  (@b24, 51, 11, 'Nublizginkite strėles, surinkite skydus; VIEŠPATS sukėlė medų karalių dvasią; nes jo sumanymas yra prieš Babiloną, kad jį sunaikintų; nes tai VIEŠPATIES kerštas, jo šventyklos kerštas.'),
  (@b24, 51, 12, 'Iškelkite vėliavą ant Babilono sienų, sustiprinkite sargybą, pastatykite sargybinius, paruoškite pasalas; nes VIEŠPATS ir sumanė, ir padarė tai, ką jis kalbėjo prieš Babilono gyventojus.'),
  (@b24, 51, 13, 'Tu, kuris gyveni ant daugybės vandenų, gausus lobiais, atėjo tavo galas ir tavo godumo saikas.'),
  (@b24, 51, 14, 'Kariuomenių VIEŠPATS prisiekė savimi, sakydamas: ‘Tikrai aš pripildysiu tave žmonėmis kaip vikšrais; ir jie pakels prieš tave šauksmą’.'),
  (@b24, 51, 15, 'Jis padarė žemę savo jėga, jis įtvirtino pasaulį savo išmintimi ir savo supratimu ištiesė dangų.'),
  (@b24, 51, 16, 'Kai jis ištaria savo balsą, tuomet vandenų daugybė yra danguose; ir jis pakelia garus nuo žemės pakraščių; jis padaro žaibus su lietumi ir išveda vėją iš savo lobynų.'),
  (@b24, 51, 17, 'Kiekvienas žmogus neprotingas savo pažinimu; kiekvienas liejikas sugėdintas dėl raižyto atvaizdo; nes jo nulietas atvaizdas melagystė, ir nėra juose kvapo.'),
  (@b24, 51, 18, 'Jie yra tuštybė, paklydimų darbas; jų aplankymo metu jie pražus.'),
  (@b24, 51, 19, 'Jokūbo dalis ne tokia kaip jie; nes jis yra visų dalykų formuotojas; o Izraelis – jo paveldo lazda; kariuomenių VIEŠPATS yra jo vardas.'),
  (@b24, 51, 20, 'Tu esi mano kovos kirvis, karo ginklas; nes tavimi aš sutrupinsiu tautas ir tavimi sunaikinsiu karalystes;'),
  (@b24, 51, 21, 'tavimi sutrupinsiu žirgą ir jo raitelį; tavimi sutrupinsiu vežimą ir jo važnyčiotoją;'),
  (@b24, 51, 22, 'taipogi tavimi sutrupinsiu vyrą ir moterį; tavimi sutrupinsiu seną ir jauną; tavimi sutrupinsiu jaunuolį ir mergaitę;'),
  (@b24, 51, 23, 'tavimi sutrupinsiu ganytoją ir jo kaimenę; tavimi sutrupinsiu artoją ir jo jaučių jungą; ir tavimi sutrupinsiu vadus ir valdovus.'),
  (@b24, 51, 24, 'Ir aš atlyginsiu Babilonui ir visiems Kaldėjos gyventojams už visą jų piktybę, kurią jie padarė Sione, jūsų akyse, – sako VIEŠPATS.'),
  (@b24, 51, 25, '– Štai aš prieš tave, o naikinantis kalne, kuris naikini visą žemę, – sako VIEŠPATS; aš ištiesiu savo ranką į tave ir nuritinsiu tave nuo uolų, ir padarysiu tave sudegusiu kalnu.'),
  (@b24, 51, 26, 'Ir jie neims iš tavęs akmens kertei nei akmens pamatams; bet tu būsi apleista per amžius, – sako VIEŠPATS.'),
  (@b24, 51, 27, '– Iškelkite vėliavą šalyje, pūskite trimitą tarp tautų, paruoškite prieš jį tautas, sušaukite prieš jį Ararato, Minio ir Aškenazo karalystes; paskirkite prieš jį vadą; atveskite aukštyn žirgus kaip šeriuotus vikšrus.'),
  (@b24, 51, 28, 'Paruoškite prieš jį tautas su medų karaliais, jų vadais ir visais jų valdovais bei visa jų valdoma šalimi.'),
  (@b24, 51, 29, 'Šalis drebės ir sielvartaus; nes bus įvykdytas kiekvienas VIEŠPATIES sumanymas prieš Babiloną, kad padarytų Babilono šalį tuščią, be gyventojų.'),
  (@b24, 51, 30, 'Babilono galiūnai liovėsi kovoję, jie pasiliko savo tvirtovėse; išseko jų jėgos; jie tapo kaip moterys; sudegino jo gyvenvietes, sulaužyti jo skląsčiai.'),
  (@b24, 51, 31, 'Vienas bėgikas bėgs pasitikti kitą, vienas pasiuntinys bėgs pasitikti kitą, kad praneštų Babilono karaliui, kad jo miestas paimtas viename šone,'),
  (@b24, 51, 32, 'kad praėjimai užkirsti, nendrynai sudeginti ugnimi, ir karo vyrai išsigandę.'),
  (@b24, 51, 33, 'Nes taip sako kariuomenių VIEŠPATS, Izraelio Dievas: ‘Babilono duktė yra kaip klojimas, laikas ją kulti; dar trumpai, ir ateis jos derliaus metas’.'),
  (@b24, 51, 34, '‘Suėdė mane, sutraiškė mane Babilono karalius Nebukadrecaras, jis mane padarė tuščiu indu, prarijo mane kaip slibinas, pripildė savo pilvą mano skanumynais, jis mane išvarė.'),
  (@b24, 51, 35, 'Man ir mano kūnui padarytas smurtas tebūna ant Babilono, – sakys Siono gyventojas; – ir mano kraujas – ant Kaldėjos gyventojų’, – sakys Jeruzalė“.'),
  (@b24, 51, 36, 'Todėl taip sako VIEŠPATS: „Štai aš ginsiu tavo bylą ir atkeršysiu už tave; aš išdžiovinsiu jo jūrą ir išdžiovinsiu jo šaltinius.'),
  (@b24, 51, 37, 'Ir Babilonas pavirs krūvomis, slibinų gyvenviete, nuostaba ir švilpimu, be gyventojų.'),
  (@b24, 51, 38, 'Jie kartu riaumos kaip liūtai, staugs kaip liūtų jaunikliai.'),
  (@b24, 51, 39, 'Jų įkarštyje paruošiu jų puotas ir juos nugirdysiu, kad jie pralinksmėtų ir užmigtų amžinu miegu ir nebenubustų, – sako VIEŠPATS.'),
  (@b24, 51, 40, '– Aš juos nuvesiu žemyn paskerdimui kaip avinėlius, kaip avinus su ožiais.'),
  (@b24, 51, 41, 'Kaip paimtas Šešachas! Ir kaip užkluptas visos žemės gyrius! Kaip Babilonas tapo nuostaba tarp tautų!'),
  (@b24, 51, 42, 'Pakilo jūra ant Babilono; jis apdengtas jos bangų daugybe.'),
  (@b24, 51, 43, 'Jo miestai yra dykynė, sausa žemė ir dykuma, šalis, kurioje joks žmogus negyvena nei joks žmogaus sūnus per ją neina.'),
  (@b24, 51, 44, 'Aš nubausiu Belį Babilone ir ištrauksiu iš jo burnos tai, ką jis prarijo; ir tautos nebeplauks pas jį kartu; taip, Babilono siena sugrius.'),
  (@b24, 51, 45, 'Išeikite iš jo tarpo, mano tauta, ir gelbėkite kiekvienas savo sielą nuo smarkaus VIEŠPATIES pykčio.'),
  (@b24, 51, 46, 'Ir kad nenusilptų jūsų širdis ir jūs nebijotumėte gando, kuris girdėsis šalyje; gandas ateis vienais metais, o paskui gandas ateis kitais metais, ir smurtas šalyje, valdovas prieš valdovą.'),
  (@b24, 51, 47, 'Todėl štai ateina dienos, kai aš įvykdysiu teismą raižytiems Babilono atvaizdams; visa jo šalis susigės, ir visi jo užmuštieji kris jo viduje.'),
  (@b24, 51, 48, 'Tada dangus ir žemė, ir visa, kas yra juose, giedos dėl Babilono; nes iš šiaurės ant jo ateis grobikai, – sako VIEŠPATS.'),
  (@b24, 51, 49, 'Kaip Babilonas išvartė Izraelio užmuštuosius, taip ir Babilone kris visos žemės užmuštieji.'),
  (@b24, 51, 50, 'Jūs, išsigelbėjusieji iš kalavijo, išeikite, nestovėkite; atsiminkite iš toli VIEŠPATĮ, ir Jeruzalė teateina jums į širdį.'),
  (@b24, 51, 51, 'Mes susigėdę, nes išgirdome priekaištą; gėda apdengė mūsų veidus; nes svetimšaliai įėjo į VIEŠPATIES namų šventoves.'),
  (@b24, 51, 52, 'Todėl štai ateina dienos, – sako VIEŠPATS, – kai aš įvykdysiu teismą jo raižytiems atvaizdams; ir visoje jo šalyje dejuos sužeistieji.'),
  (@b24, 51, 53, 'Nors Babilonas pakiltų į dangų ir nors sustiprintų savo stiprybės aukštumą, tačiau nuo manęs pas jį ateis plėšikai, – sako VIEŠPATS.'),
  (@b24, 51, 54, 'Šauksmo garsas ateina iš Babilono ir didelis sunaikinimas iš kaldėjų šalies;'),
  (@b24, 51, 55, 'nes VIEŠPATS apiplėšė Babiloną ir iš jo išnaikino stiprų balsą; kai jo bangos ūžia kaip dideli vandenys, prabyla jų balso ūžesys;'),
  (@b24, 51, 56, 'kadangi ant jo atėjo plėšikas, būtent ant Babilono, ir jo galiūnai paimti, sulaužyti visi jų lankai; nes VIEŠPATS, atpildo Dievas, tikrai atmokės.'),
  (@b24, 51, 57, 'Ir aš nugirdysiu jo kunigaikščius, jo išminčius, jo vadus, jo valdovus ir jo galiūnus; ir jie miegos amžinu miegu ir nebepabus“, – sako Karalius, kurio vardas yra kariuomenių VIEŠPATS.'),
  (@b24, 51, 58, 'Taip sako kariuomenių VIEŠPATS: „Babilono plačiosios sienos bus visiškai nugriautos ir jo aukštieji vartai bus sudeginti ugnimi; tautos triūs veltui ir žmonės užsidegę, ir jie nuvargs“.'),
  (@b24, 51, 59, 'Žodis, kurį pranašas Jeremijas įsakė Maasėjo sūnaus Nerijo sūnui Serajai, kai jis ėjo su Judos karaliumi Zedekiju į Babiloną ketvirtaisiais jo karaliavimo metais. O šis Seraja buvo ramus kunigaikštis.'),
  (@b24, 51, 60, 'Taigi Jeremijas užrašė į knygą visą nelaimę, kuri turės ateiti ant Babilono, – visus šituos žodžius, kurie yra užrašyti prieš Babiloną.'),
  (@b24, 51, 61, 'Ir Jeremijas tarė Serajai: „Kai atvyksi į Babiloną, pamatysi ir perskaitysi visus šituos žodžius,'),
  (@b24, 51, 62, 'tuomet sakyk: ‘O VIEŠPATIE, tu kalbėjai prieš šią vietą, kad ją iškirstum, kad nieko joje nebeliktų, nei žmogaus, nei gyvulio, bet kad ji būtų amžina dykyne’.'),
  (@b24, 51, 63, 'Ir bus, kai baigsi skaityti šitą knygą, pririšk prie jos akmenį ir įmesk ją į Eufrato vidurį;'),
  (@b24, 51, 64, 'ir sakyk: ‘Taip nuskęs Babilonas ir nebeiškils iš nelaimės, kurią aš jam užleisiu; ir jie nuvargs’“. Iki čia Jeremijo žodžiai.'),
  (@b24, 52, 1, 'Zedekijas buvo dvidešimt vienerių metų, kai pradėjo karaliauti, ir jis karaliavo vienuolika metų Jeruzalėje. O jo motinos vardas buvo Hamutala, duktė Jeremijo iš Libnos.'),
  (@b24, 52, 2, 'Ir jis darė tai, kas buvo pikta VIEŠPATIES akyse, pagal visa tai, ką buvo daręs Jehojakimas.'),
  (@b24, 52, 3, 'Nes dėl VIEŠPATIES pykčio Jeruzalėje ir Judoje įvyko, kol jis atmetė juos iš savo akivaizdos, kad Zedekijas sukilo prieš Babilono karalių.'),
  (@b24, 52, 4, 'Ir devintaisiais jo karaliavimo metais, dešimtąjį mėnesį, to mėnesio dešimtąją dieną, įvyko, kad atvyko Babilono karalius Nebukadrecaras, jis ir visa jo kariuomenė, prieš Jeruzalę ir prieš ją stovyklavo ir prieš ją aplinkui pastatė fortus.'),
  (@b24, 52, 5, 'Taigi miestas buvo apgultas iki vienuoliktųjų karaliaus Zedekijo metų.'),
  (@b24, 52, 6, 'Ir ketvirtąjį mėnesį, to mėnesio devintąją dieną, mieste buvo toks smarkus badas, kad šalies tautai nebuvo duonos.'),
  (@b24, 52, 7, 'Tada miestas buvo pralaužtas, ir visi karo vyrai pabėgo ir nakčia išėjo iš miesto vartų keliu tarp dviejų sienų, esančių prie karaliaus sodo (na, o kaldėjai buvo šalia miesto aplinkui); ir jie ėjo lygumos keliu.'),
  (@b24, 52, 8, 'Bet kaldėjų kariuomenė persekiojo karalių ir pasivijo Zedekiją Jericho lygumose; ir visa jo kariuomenė buvo nuo jo išsklaidyta.'),
  (@b24, 52, 9, 'Tada jie paėmė karalių ir jį nuvedė aukštyn pas Babilono karalių į Riblą Hamato šalyje; kur jis įvykdė jam teismą.'),
  (@b24, 52, 10, 'Ir Babilono karalius nužudė Zedekijo sūnus jo akyse; jis nužudė ir visus Judos kunigaikščius Ribloje.'),
  (@b24, 52, 11, 'Tada jis išlupo Zedekijui akis; ir Babilono karalius sukaustė jį grandinėmis ir nuvedė jį į Babiloną, ir pasodino jį į kalėjimą iki jo mirties dienos.'),
  (@b24, 52, 12, 'Na, o penktąjį mėnesį, to mėnesio dešimtąją dieną, tai buvo devynioliktieji Babilono karaliaus Nebukadrecaro metai, į Jeruzalę atvyko Nebuzar-Adanas, sargybos vadas, kuris tarnavo Babilono karaliui,'),
  (@b24, 52, 13, 'ir sudegino VIEŠPATIES namus ir karaliaus namus; ir visus Jeruzalės namus ir visus didžiūnų namus jis sudegino ugnimi;'),
  (@b24, 52, 14, 'ir visa kaldėjų kariuomenė, buvusi su sargybos vadu, nugriovė visas aplink Jeruzalę esančias sienas.'),
  (@b24, 52, 15, 'Tada sargybos vadas Nebuzar-Adanas išvedė į nelaisvę kai kuriuos tautos vargšus, tautos likutį, išlikusį mieste, persimetėlius, kurie buvo persimetę pas Babilono karalių, ir likusius iš minios.'),
  (@b24, 52, 16, 'Bet sargybos vadas Nebuzar-Adanas kai kuriuos šalies vargšus paliko vynuogininkais ir žemdirbiais.'),
  (@b24, 52, 17, 'Taip pat žalvario stulpus, buvusius VIEŠPATIES namuose, stovus ir žalvarinę jūrą, esančius VIEŠPATIES namuose, kaldėjai sudaužė ir išgabeno iš jų visą varį į Babiloną.'),
  (@b24, 52, 18, 'Jie pasiėmė ir katilus, semtuvus, žnybtuvus, dubenėlius, šaukštus ir visus žalvarinius indus, kuriais jie tarnaudavo.'),
  (@b24, 52, 19, 'Ir dubenis, indus žarijoms, dubenėlius, katilus, žvakides, šaukštus ir taures; tai, kas buvo iš aukso, kaip auksą, ir tai, kas buvo iš sidabro, kaip sidabrą, pasiėmė sargybos vadas.'),
  (@b24, 52, 20, 'Du stulpus, vieną jūrą ir dvylika žalvarinių jaučių, esančių po stovais, kuriuos karalius Saliamonas buvo padaręs VIEŠPATIES namuose; visų šitų indų žalvario nebuvo įmanoma pasverti.'),
  (@b24, 52, 21, 'O dėl stulpų, vienas stulpas buvo aštuoniolikos uolekčių aukščio, ir jį juosė dvylikos uolekčių apvadas; ir jis buvo keturių pirštų storio; jis buvo tuščiaviduris.'),
  (@b24, 52, 22, 'Ir ant jo buvo žalvarinis kapitelis; vienas kapitelis buvo penkių uolekčių aukščio, su tinklu ir granatais ant kapitelio aplinkui – viskas iš žalvario. Taip pat antrasis stulpas bei granatai buvo kaip ir šitie.'),
  (@b24, 52, 23, 'Ir buvo devyniasdešimt šeši granatai ant vienos pusės; iš viso ant tinklo aplinkui buvo šimtas granatų.'),
  (@b24, 52, 24, 'Ir sargybos vadas paėmė vyriausiąjį kunigą Serają, antrąjį kunigą Sofoniją ir tris durų sargus;'),
  (@b24, 52, 25, 'iš miesto taipogi jis paėmė ir eunuchą, kuriam buvo pavesti karo vyrai; ir septynis vyrus, iš esančių prie karaliaus asmeniškai, kurie buvo atrasti mieste; ir kariuomenės pagrindinį raštininką, kuris surinkdavo šalies tautą; ir šešiasdešimt vyrų iš šalies tautos, atrastus miesto viduje.'),
  (@b24, 52, 26, 'Taigi sargybos vadas Nebuzar-Adanas juos paėmė ir atvedė pas Babilono karalių į Riblą.'),
  (@b24, 52, 27, 'Ir Babilono karalius juos sumušė ir nužudė Ribloje, Hamato šalyje. Taip Juda buvo išvesta į nelaisvę iš savo šalies.'),
  (@b24, 52, 28, 'Štai tauta, kurią Nebukadrecaras išvedė į nelaisvę: septintaisiais metais tris tūkstančius dvidešimt tris žydus;'),
  (@b24, 52, 29, 'aštuonioliktaisiais Nebukadrecaro metais jis išvedė į nelaisvę iš Jeruzalės aštuonis šimtus trisdešimt du asmenis;'),
  (@b24, 52, 30, 'dvidešimt trečiaisiais Nebukadrecaro metais sargybos vadas Nebuzar-Adanas išvedė nelaisvėn iš žydų septynis šimtus keturiasdešimt penkis asmenis; iš viso buvo keturi tūkstančiai šeši šimtai asmenų.'),
  (@b24, 52, 31, 'Ir trisdešimt septintaisiais Judos karaliaus Jehojachino nelaisvės metais, dvyliktąjį mėnesį, to mėnesio dvidešimt penktąją dieną įvyko, kad Babilono karalius Evil-Merodachas, pirmaisiais savo karaliavimo metais, pakėlė Judos karaliaus Jehojachino galvą ir jį išvedė iš kalėjimo,'),
  (@b24, 52, 32, 'ir draugiškai kalbėjo su juo, ir pastatė jo sostą aukščiau už sostą karalių, esančių su juo Babilone,'),
  (@b24, 52, 33, 'ir pakeitė jo kalėjimo drabužius; ir jis nuolat valgė duoną jo akivaizdoje per visas savo gyvenimo dienas.'),
  (@b24, 52, 34, 'O dėl jo maisto, iš Babilono karaliaus jam buvo duodamas nuolatinis maistas, kasdienis davinys, iki jo mirties dienos, per visas jo gyvenimo dienas.'),
  (@b25, 1, 1, 'Koks vienišas stovi miestas, kuris buvo pilnas žmonių! Jis pasidarė kaip našlė! Jis, kuris buvo didis tarp tautų ir kunigaikštis tarp provincijų, kaip jis tapo duoklės mokėtoju!'),
  (@b25, 1, 2, 'Jis graudžiai verkia naktį, ir jo ašaros yra ant skruostų; iš visų jo mylėtojų jis neturi nei vieno, kuris jį paguostų; visi jo draugai elgėsi su juo išdavikiškai, jie tapo jo priešai.'),
  (@b25, 1, 3, 'Juda išėjo į nelaisvę dėl vargo ir dėl sunkios vergijos; ji gyvena tarp pagonių, neranda poilsio; visi jos persekiotojai pasivijo ją tarp ankštų vietų.'),
  (@b25, 1, 4, 'Gedi Siono keliai, nes niekas neateina į iškilmingas šventes; visi jo vartai ištuštėję; jo kunigai dūsauja, jo mergelės sielvartauja, ir jis apimtas kartėlio.'),
  (@b25, 1, 5, 'Jo priešininkai yra viršininkai, jo priešai klesti; nes VIEŠPATS jam sukėlė kančias dėl jo nusižengimų daugybės; jo vaikai išėję nelaisvėn priešo akivaizdoje.'),
  (@b25, 1, 6, 'Ir iš Siono dukters pasitraukė visas jos grožis: jos kunigaikščiai tapo kaip elniai, kurie neranda ganyklos, ir jie ėjo bejėgiai persekiotojo priešakyje.'),
  (@b25, 1, 7, 'Jeruzalė savo vargo ir savo kančios dienomis atsiminė visa, kas geistina, ką ji turėjo senomis dienomis, kai jos tauta pateko į priešo rankas, ir niekas jai nepadėjo; priešininkai žiūrėjo į ją ir tyčiojosi iš jos sabatų.'),
  (@b25, 1, 8, 'Jeruzalė sunkiai nusidėjo; todėl ji pašalinta; visi, kurie ją gerbė, ją niekina, nes jie pamatė jos nuogumą; taip, ji dūsauja ir sukasi atgal.'),
  (@b25, 1, 9, 'Jos nešvarumas yra jos padurkuose; ji neprisiminė apie savo baigtį; todėl ji nuostabiai griuvo; ji neturi guodėjo. O VIEŠPATIE, pažvelk į mano vargą; nes priešas išsiaukštino.'),
  (@b25, 1, 10, 'Priešininkas ištiesė savo ranką į viską, kas jai geistina; nes ji matė, kaip pagonys įžengė į jos šventovę, kuriems tu įsakei neįeiti į tavąjį susirinkimą.'),
  (@b25, 1, 11, 'Visa jos tauta dūsauja, jie ieško duonos; jie atidavė tai, kas jiems geistina, už maistą, kad palengvintų sielai; pažiūrėk, o VIEŠPATIE, ir atsižvelk; nes aš tapau niekinga.'),
  (@b25, 1, 12, 'Ar tai nieko nereiškia jums visiems, einantiems pro šalį? Žiūrėkite ir matykite, ar yra toks skausmas kaip mano skausmas, kurį man sukėlė, kuriuo VIEŠPATS kamavo mane savo smarkaus pykčio dieną.'),
  (@b25, 1, 13, 'Iš aukštybės jis siuntė ugnį į mano kaulus, ir ji juos įveikė; jis ištiesė tinklą mano kojoms, jis apsuko mane atgal; jis padarė mane apleistą ir visą dieną nusilpusią.'),
  (@b25, 1, 14, 'Mano nusižengimų jungas pririštas jo ranka; jie supinti ir užkilo man ant sprando; jis sužlugdė mano jėgas, Viešpats mane atidavė į rankas tų, iš kurių nepajėgiu atsikelti.'),
  (@b25, 1, 15, 'Viešpats mindė po kojomis visus mano galiūnus mano viduje; jis sušaukė prieš mane sambūrį, kad sutriuškintų mano jaunuolius; Viešpats mindė mergelę, Judos dukterį, kaip vyno spaustuve.'),
  (@b25, 1, 16, 'Dėl to aš verkiu; mano akis, mano akimi teka vanduo, nes toli nuo manęs guodėjas, kuris turi atgaivinti mano sielą; mano vaikai apleisti, nes priešas nugalėjo.'),
  (@b25, 1, 17, 'Sionas išskečia savo rankas, bet nėra, kas jį paguostų; VIEŠPATS įsakė dėl Jokūbo, kad jo priešininkai būtų aplink jį; Jeruzalė tarp jų yra kaip mėnesinėmis serganti moteris.'),
  (@b25, 1, 18, 'VIEŠPATS yra teisus; nes aš maištavau prieš jo įsakymą; klausykite, meldžiu jus, visos tautos, ir matykite mano skausmą: mano mergelės ir mano jaunuoliai nuėjo į nelaisvę.'),
  (@b25, 1, 19, 'Šaukiausi savo meilužius, bet jie apgavo mane; mano kunigai ir mano vyresnieji atidavė dvasią mieste, kol jie ieškojo sau maisto, kad atgaivintų savo sielas.'),
  (@b25, 1, 20, 'Pažvelk, o VIEŠPATIE, nes aš suspausta; mano viduriai nerimauja; mano širdis apsivertė mano viduje; nes aš labai maištavau; lauke vaikus atima kalavijas, namuose – mirtis.'),
  (@b25, 1, 21, 'Jie girdėjo, kad aš dūsauju; nėra, kas mane paguostų; visi mano priešai išgirdo apie mano bėdą; jie džiaugiasi, kad tu tai padarei; tu atvesi dieną, kurią pašaukei, ir jiems bus taip, kaip man.'),
  (@b25, 1, 22, 'Teateina visa jų nedorybė tavo akivaizdon; ir daryk jiems, kaip man padarei už visus mano nusižengimus; nes daug yra mano dūsavimų, ir mano širdis nusilpusi.'),
  (@b25, 2, 1, 'Kaip Viešpats savo pyktyje apdengė debesimi Siono dukterį ir numetė iš dangaus į žemę Izraelio grožį, ir neatsiminė savo pakojo savo pykčio dieną!'),
  (@b25, 2, 2, 'Viešpats prarijo visas Jokūbo buveines ir nepasigailėjo; savo rūstybėje jis nugriovė Judos dukters tvirtoves; nuvertė jas žemėn; jis suteršė karalystę ir jos kunigaikščius.'),
  (@b25, 2, 3, 'Savo smarkiame pyktyje jis nukirto visą Izraelio ragą; jis atitraukė savo dešinę ranką iš priešo akivaizdos, ir užsidegė prieš Jokūbą kaip liepsnojanti ugnis, ryjanti aplinkui.'),
  (@b25, 2, 4, 'Jis įtempė savo lanką kaip priešas; jis stovėjo kaip priešininkas su savo dešine ir nužudė visa, kas geistina akims Siono dukters padangtėje; jis išliejo savo įtūžį kaip ugnį.'),
  (@b25, 2, 5, 'Viešpats buvo kaip priešas; jis prarijo Izraelį, prarijo visus jo rūmus; jis sunaikino jo tvirtoves ir padaugino Judos dukteryje gedėjimą ir raudojimą.'),
  (@b25, 2, 6, 'Ir jis smurtu atėmė savo padangtę tarsi iš sodo; jis sunaikino savo susirinkimo vietas; VIEŠPATS padarė, kad Sione būtų pamirštos iškilmingos šventės ir sabatai, ir savo smarkiame pyktyje paniekino karalių ir kunigą.'),
  (@b25, 2, 7, 'Viešpats atmetė savo aukurą, jis bjaurisi savo šventove, jis atidavė į priešo rankas jo rūmų sienas; jie triukšmavo VIEŠPATIES namuose kaip iškilmingos šventės dieną.'),
  (@b25, 2, 8, 'VIEŠPATS nusprendė sunaikinti Siono dukters sieną; jis ištempė virvę, jis neatitraukė savo rankos nuo sunaikinimo; todėl jis privertė raudoti sutvirtinimą ir sieną; jie drauge nusilpo.'),
  (@b25, 2, 9, 'Prasmego į žemę jos vartai; jis sunaikino ir sulaužė jos skląsčius; jos karalius ir jos kunigaikščiai yra tarp pagonių; nebėra įstatymo; taip pat ir jos pranašai neranda apreiškimo iš VIEŠPATIES.'),
  (@b25, 2, 10, 'Siono dukters vyresnieji sėdi ant žemės ir tyli; jie apsibarstę galvas dulkėmis; jie apsijuosę ašutinėmis; Jeruzalės mergelės nuleido žemyn savo galvas.'),
  (@b25, 2, 11, 'Mano akys senka nuo ašarų, nerimsta mano viduriai, mano kepenys išsiliejo ant žemės dėl mano tautos dukters sunaikinimo; nes vaikai ir žindukliai alpsta miesto gatvėse.'),
  (@b25, 2, 12, 'Jie sako savo motinoms: „Kur grūdai ir vynas?“, kai jie alpsta kaip sužeisti miesto gatvėse, kai jų sielos išsiliejo į jų motinų glėbį.'),
  (@b25, 2, 13, 'Ką man paimti, kad tau paliudyčiau? Su kuo tave palyginti, o Jeruzalės dukra? Ką tau prilyginsiu, kad tave paguosčiau, o mergele, Siono dukra? Nes tavo spraga yra didelė kaip jūra; kas gali tave pagydyti?'),
  (@b25, 2, 14, 'Tavo pranašai tau regėjo tuštybes ir kvailystes; ir jie neatidengė tavo neteisybės, kad nukreiptų tavo nelaisvę; bet tau regėjo melagingas naštas ir ištrėmimo priežastis.'),
  (@b25, 2, 15, 'Visi praeinantys ploja prieš tave rankomis; jie švilpia ir kraipo savo galvą prieš Jeruzalės dukterį, sakydami: „Ar tai miestas, kurį vadina ‘grožio tobulybe’, ‘visos žemės džiaugsmu’?“'),
  (@b25, 2, 16, 'Visi tavo priešai atvėrė burnas prieš tave; jie švilpia ir griežia dantimis; jie sako: „Mes prarijome ją; tikrai tai diena, kurios laukėme; mes radome, mes ją pamatėme“.'),
  (@b25, 2, 17, 'VIEŠPATS padarė tai, ką buvo sumanęs; jis išpildė savo žodį, kurį buvo įsakęs senovės dienomis; jis griovė ir nesigailėjo; jis tavo priešui davė džiūgauti dėl tavęs, jis išaukštino tavo priešininkų ragą.'),
  (@b25, 2, 18, 'Jų širdis šaukėsi Viešpaties, o Siono dukters siena, tegul ašaros teka žemyn kaip upė dieną ir naktį; neduok sau poilsio; tenenurimsta tavo akių obuolys.'),
  (@b25, 2, 19, 'Kelkis, šauk naktį; sargybų pradžioje išliek savo širdį kaip vandenį Viešpaties akyse; pakelk į jį savo rankas dėl gyvybės savo vaikelių, alpstančių iš bado kiekvienos gatvės gale.'),
  (@b25, 2, 20, 'Pažiūrėk, o VIEŠPATIE, ir atsižvelk, kam tu tai padarei. Argi moterys valgys savo vaisių, sprindžio ilgio vaikus? Argi kunigas ir pranašas turi būti nužudyti Viešpaties šventovėje?'),
  (@b25, 2, 21, 'Jauni ir seni guli ant žemės gatvėse; mano mergelės ir mano jaunuoliai kritę nuo kalavijo; tu juos nužudei savo pykčio dieną; tu žudei ir nesigailėjai.'),
  (@b25, 2, 22, 'Tu sušaukei kaip į iškilmingą dieną mano siaubus iš visų pusių, taip, kad VIEŠPATIES pykčio dieną niekas neištrūko ir neišliko; kuriuos vysčiau ir užauginau, tuos mano priešas sunaikino.'),
  (@b25, 3, 1, 'Aš žmogus, regėjęs vargą nuo jo rūstybės lazdos.'),
  (@b25, 3, 2, 'Jis mane vedė ir atvedė į tamsą, bet ne į šviesą.'),
  (@b25, 3, 3, 'Tikrai jis pasisuko prieš mane; jis nukreipia savo ranką prieš mane visą dieną.'),
  (@b25, 3, 4, 'Jis pasendino mano kūną ir mano odą; jis sulaužė mano kaulus.'),
  (@b25, 3, 5, 'Jis apstatė mane ir apsupo mane tulžimi ir sunkiu darbu.'),
  (@b25, 3, 6, 'Jis pasodino mane tamsiose vietose, kaip seniai mirusius.'),
  (@b25, 3, 7, 'Jis aptvėrė mane, kad negalėčiau išeiti; jis pasunkino mano grandinę.'),
  (@b25, 3, 8, 'Taipogi, kai aš šaukiu ir rėkiu, jis neįsileidžia mano maldos.'),
  (@b25, 3, 9, 'Jis užtvėrė mano kelius tašytais akmenimis, jis padarė kreivus mano takus.'),
  (@b25, 3, 10, 'Jis man buvo kaip tykojantis lokys ir kaip liūtas slaptavietėse.'),
  (@b25, 3, 11, 'Jis nukreipė į šalį mano kelius ir sudraskė mane; jis padarė mane apleistą.'),
  (@b25, 3, 12, 'Jis įtempė savo lanką ir pastatė mane kaip taikinį strėlei.'),
  (@b25, 3, 13, 'Jis įsmeigė į mano inkstus savo strėlinės strėles.'),
  (@b25, 3, 14, 'Aš buvau pajuoka visai savo tautai ir jų daina visą dieną.'),
  (@b25, 3, 15, 'Jis pasotino mane kartybėmis, prigirdė mane metėlėmis.'),
  (@b25, 3, 16, 'Taipogi jis išlaužė mano dantis žvyro akmenimis, jis apdengė mane pelenais.'),
  (@b25, 3, 17, 'Tu atitraukei mano sielą toli nuo ramybės; aš pamiršau klestėjimą.'),
  (@b25, 3, 18, 'Ir aš tariau: „Mano stiprybė ir mano viltis iš VIEŠPATIES pražuvo“;'),
  (@b25, 3, 19, 'prisimindamas mano skausmą ir mano vargą, metėles ir tulžį.'),
  (@b25, 3, 20, 'Mano siela vis apie tuos prisimena ir nusižemina manyje.'),
  (@b25, 3, 21, 'Tai prisiminiau mintyse, todėl turiu viltį.'),
  (@b25, 3, 22, 'Tai dėl VIEŠPATIES gailestingumų, kad mes nesame sunaikinti, nes jo užuojautos nesibaigia.'),
  (@b25, 3, 23, 'Kasryt jie nauji; didelė tavo ištikimybė.'),
  (@b25, 3, 24, '„VIEŠPATS yra mano dalis, – sako mano siela, – todėl vilsiuosi juo“.'),
  (@b25, 3, 25, 'VIEŠPATS yra geras tiems, kurie jo laukia, sielai, kuri jo ieško.'),
  (@b25, 3, 26, 'Gerai, kad žmogus viliasi ir tyliai laukia VIEŠPATIES išgelbėjimo.'),
  (@b25, 3, 27, 'Gerai žmogui, kad jis nešioja jungą savo jaunystėje.'),
  (@b25, 3, 28, 'Jis sėdi vienas ir tyli, nes jis jam uždėjo jį.'),
  (@b25, 3, 29, 'Jis įkiša į dulkes savo burną; gal dar yra vilties.'),
  (@b25, 3, 30, 'Jis pakiša savo skruostą jį mušančiam; jis pilnai prisisotinęs priekaištų.'),
  (@b25, 3, 31, 'Nes Viešpats neatmes amžiams;'),
  (@b25, 3, 32, 'bet nors jis sukelia sielvartą, tačiau jis pasigailės pagal savo gailestingumų daugybę.'),
  (@b25, 3, 33, 'Nes jis žmonių vaikams nenoriai sukelia kančias ir sielvartą.'),
  (@b25, 3, 34, 'Kojomis traiškyti visus žemės belaisvius,'),
  (@b25, 3, 35, 'Aukščiausiojo akivaizdoje nukreipti žmogaus teises į šalį,'),
  (@b25, 3, 36, 'parversti žmogų jo byloje, – Viešpats tam nepritaria.'),
  (@b25, 3, 37, 'Kas tas, kuris pasako, ir tai įvyksta, kai Viešpats to neįsako?'),
  (@b25, 3, 38, 'Ar ne iš Aukščiausiojo burnos išeina pikta ir gera?'),
  (@b25, 3, 39, 'Kodėl gyvenantis žmogus skundžiasi? Žmogus dėl savo nuodėmių bausmės.'),
  (@b25, 3, 40, 'Ištirkime ir išmėginkime savo kelius, ir gręžkimės į VIEŠPATĮ.'),
  (@b25, 3, 41, 'Pakelkime savo širdis su savo rankomis į Dievą danguose.'),
  (@b25, 3, 42, 'Mes nusižengėme ir maištavome; tu neatleidai.'),
  (@b25, 3, 43, 'Tu apsiautei pykčiu ir mus persekiojai; tu žudei, tu nesigailėjai.'),
  (@b25, 3, 44, 'Tu apsisiautei debesimi, kad nepraeitų mūsų malda.'),
  (@b25, 3, 45, 'Tu padarei mus atmatomis ir šiukšlėmis tautų tarpe.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b25, 3, 46, 'Visi mūsų priešai atvėrė savo burnas prieš mus.'),
  (@b25, 3, 47, 'Ant mūsų užėjo baimė ir žabangos, suniokojimas ir sunaikinimas.'),
  (@b25, 3, 48, 'Mano akis liejasi vandens upėmis dėl mano tautos dukters sunaikinimo.'),
  (@b25, 3, 49, 'Mano akis be perstojo ašaroja ir nesiliauja,'),
  (@b25, 3, 50, 'kol VIEŠPATS pažvelgs žemyn ir pamatys iš dangaus.'),
  (@b25, 3, 51, 'Mano akis paveikia mano širdį dėl visų mano miesto dukterų.'),
  (@b25, 3, 52, 'Mano priešai mane stipriai vijosi, kaip paukštį, be priežasties.'),
  (@b25, 3, 53, 'Jie atkirto mano gyvybę požemio kalėjime ir mėtė į mane akmenį.'),
  (@b25, 3, 54, 'Vandenys tekėjo virš mano galvos; tada aš tariau: „Aš esu iškirstas“.'),
  (@b25, 3, 55, 'Šaukiausi tavo vardo, o VIEŠPATIE, žemai iš požeminio kalėjimo.'),
  (@b25, 3, 56, 'Tu išgirdai mano balsą; neslėpk savo ausies nuo mano kvėpavimo, nuo mano šauksmo.'),
  (@b25, 3, 57, 'Tu priartėjai tą dieną, kai tavęs šaukiausi; tu tarei: „Nebijok“.'),
  (@b25, 3, 58, 'O Viešpatie, tu gynei mano sielos bylas; tu atpirkai mano gyvybę.'),
  (@b25, 3, 59, 'O VIEŠPATIE, tu matei mano skriaudą; teisk mano bylą.'),
  (@b25, 3, 60, 'Tu matei visą jų kerštą ir visus jų sumanymus prieš mane.'),
  (@b25, 3, 61, 'Tu girdėjai jų priekaištą, o VIEŠPATIE, ir visus jų sumanymus prieš mane;'),
  (@b25, 3, 62, 'lūpas tų, kurie sukilo prieš mane, ir jų kėslus prieš mane visą dieną.'),
  (@b25, 3, 63, 'Pastebėk jų atsisėdimą ir jų atsistojimą; aš esu jų muzika.'),
  (@b25, 3, 64, 'Atlygink jiems atpildu, o VIEŠPATIE, pagal jų rankų darbą.'),
  (@b25, 3, 65, 'Suteik jiems širdies liūdesį, tavo prakeikimą jiems.'),
  (@b25, 3, 66, 'Persekiok ir juos išnaikink pyktyje iš po VIEŠPATIES dangų.'),
  (@b25, 4, 1, 'Kaip patamsėjo auksas, kaip pasikeitė geriausias auksas! Šventovės akmenys išpilti kiekvienos gatvės gale.'),
  (@b25, 4, 2, 'Brangūs Siono sūnūs, prilygstantys grynam auksui, kaipgi jie laikomi moliniais ąsočiais, puodžiaus rankų darbu!'),
  (@b25, 4, 3, 'Net jūros pabaisos ištraukia krūtį, jie žindo savo jauniklius; mano tautos dukra tapo žiauri kaip stručiai dykumoje.'),
  (@b25, 4, 4, 'Žindomojo vaiko liežuvis iš troškulio prilipo prie gomurio; vaikeliai prašo duonos, bet niekas jiems jos neatlaužia.'),
  (@b25, 4, 5, 'Tie, kurie maitinosi gardumynais, apleisti gatvėse; tie, kurie buvo užauginti skaisčiai raudonuose, apsikabino mėšlo krūvą.'),
  (@b25, 4, 6, 'Nes mano tautos dukters neteisybės bausmė yra didesnė už nuodėmės bausmę Sodomos, kuri buvo sugriauta akimirksniu, ir rankų nebuvo prie jos pridėta.'),
  (@b25, 4, 7, 'Jos nazirai buvo skaistesni už sniegą, baltesni už pieną, jų kūnas rausvesnis už rubinus, jų blizgesys – safyro;'),
  (@b25, 4, 8, 'jų veidas juodesnis už anglį; jie neatpažįstami gatvėse; jų oda limpa prie jų kaulų; ji sudžiūvusi, pasidariusi kaip pagalys.'),
  (@b25, 4, 9, 'Užmuštiesiems kalaviju yra geriau negu užmuštiems badu; nes šitie nyksta palaužti dėl lauko vaisių stokos.'),
  (@b25, 4, 10, 'Gailestingų moterų rankos virė savo pačių vaikus; jie buvo jų maistas mano tautos dukters sunaikinime.'),
  (@b25, 4, 11, 'VIEŠPATS įvykdė savo įtūžį; jis išliejo savo smarkų pyktį ir užkūrė Sione ugnį, kuri surijo jo pamatus.'),
  (@b25, 4, 12, 'Žemės karaliai ir visi pasaulio gyventojai nebūtų tikėję, kad priešininkas ir priešas įžengs į Jeruzalės vartus.'),
  (@b25, 4, 13, 'Dėl nuodėmių jos pranašų ir neteisybių jos kunigų, kurie išliejo jos viduje teisiųjų kraują,'),
  (@b25, 4, 14, 'jie klajojo gatvėmis kaip akli, jie taip susiteršė krauju, kad nebuvo galima paliesti jų drabužių.'),
  (@b25, 4, 15, 'Šaukė jiems: „Išeikite, tai nešvaru; išeikite, išeikite, nelieskite“; kai jie pabėgo ir klaidžiojo, jie kalbėjo tarp pagonių: „Jie ten nebeapsigyvens“.'),
  (@b25, 4, 16, 'VIEŠPATIES pyktis juos padalijo; jis nebeatsižvelgs į juos: jie nepaisė kunigų asmenybių, jie nerodė palankumo vyresniesiems.'),
  (@b25, 4, 17, 'O mes, mūsų akys nusilpo dėl tuščios mūsų pagalbos; savo sargyboje mes laukėme tautos, kuri negalėjo mūsų išgelbėti.'),
  (@b25, 4, 18, 'Jie persekioja mūsų žingsnius, kad negalėtume eiti į savo gatves; mūsų galas arti, išsipildė mūsų dienos; nes atėjo mūsų galas.'),
  (@b25, 4, 19, 'Mūsų persekiotojai greitesni už dangaus erelius; jie vijosi mus kalnuose, jie tykojo mūsų dykumoje.'),
  (@b25, 4, 20, 'Mūsų šnervių kvapas, VIEŠPATIES pateptasis, buvo sugautas jų duobėse – tas, apie kurį sakėme: „Po jo šešėliu gyvensime tarp pagonių“.'),
  (@b25, 4, 21, 'Džiaukis ir linksminkis, Edomo dukra, gyvenanti Uco šalyje; pas tave irgi ateis taurė; tu pasigersi ir apsinuoginsi.'),
  (@b25, 4, 22, 'Tavo neteisybės bausmė yra įvykdyta, o Siono dukra; jis nebeišves tavęs į nelaisvę; jis aplankys tavo neteisybę, o Edomo dukra; jis atidengs tavo nuodėmes.'),
  (@b25, 5, 1, 'Atsimink, o VIEŠPATIE, kas mus ištiko; atsižvelk ir pamatyk mūsų priekaištą.'),
  (@b25, 5, 2, 'Mūsų paveldas perėjo svetimiesiems, mūsų namai – ateiviams.'),
  (@b25, 5, 3, 'Mes esame našlaičiai, be tėvo, mūsų motinos – kaip našlės.'),
  (@b25, 5, 4, 'Savo pačių vandenį gėrėme už pinigus; mums parduodami mūsų medžiai.'),
  (@b25, 5, 5, 'Mūsų sprandai persekiojami; mes triūsiame ir neturime poilsio.'),
  (@b25, 5, 6, 'Mes padavėme ranką egiptiečiams ir asirams, kad pasisotintume duona.'),
  (@b25, 5, 7, 'Mūsų tėvai nusidėjo, ir jų nebėra; o mes nešiojame jų neteisybes.'),
  (@b25, 5, 8, 'Tarnai mums viešpatauja; nėra kas mus išvaduotų iš jų rankos.'),
  (@b25, 5, 9, 'Mes įgijome savo duoną rizikuodami savo gyvybe dėl dykumos kalavijo.'),
  (@b25, 5, 10, 'Mūsų oda buvo juoda kaip krosnis nuo baisaus bado.'),
  (@b25, 5, 11, 'Jie prievartavo moteris Sione ir paneles Judos miestuose.'),
  (@b25, 5, 12, 'Kunigaikščiai pakarti jų rankomis; vyresniųjų veidai negerbiami.'),
  (@b25, 5, 13, 'Jie paėmė jaunuolius, kad maltų, o vaikai griuvinėjo po malkomis.'),
  (@b25, 5, 14, 'Vyresniųjų nebėra prie vartų, jaunuolių prie jų muzikos.'),
  (@b25, 5, 15, 'Dingo mūsų širdies džiaugsmas; mūsų šokis pavirto gedulu.'),
  (@b25, 5, 16, 'Nukrito karūna nuo mūsų galvos; vargas mums, kad nusidėjome!'),
  (@b25, 5, 17, 'Dėl to nualpo mūsų širdis; dėl šitų dalykų aptemo mūsų akys.'),
  (@b25, 5, 18, 'Dėl to, kad Siono kalnas apleistas, lapės vaikšto jame.'),
  (@b25, 5, 19, 'Tu, o VIEŠPATIE, pasilieki per amžius; tavo sostas iš kartos į kartą.'),
  (@b25, 5, 20, 'Kodėl tu mus pamiršti per amžius, mus palieki tokį ilgą laiką?'),
  (@b25, 5, 21, 'Pakreipk mus į save, o VIEŠPATIE, ir mes būsime nukreipti; atnaujink mūsų dienas, kaip seniau.'),
  (@b25, 5, 22, 'Bet tu mus visiškai atmetei; tu labai užsirūstinęs ant mūsų.'),
  (@b26, 1, 1, 'Na, o trisdešimtaisiais metais, ketvirtąjį mėnesį, penktąją to mėnesio dieną, man esant tarp belaisvių prie Kebaro upės, atsitiko, kad atsivėrė dangūs, ir aš mačiau Dievo regėjimus.'),
  (@b26, 1, 2, 'To mėnesio penktąją dieną, tai buvo penktieji karaliaus Jehoachino nelaisvės metai,'),
  (@b26, 1, 3, 'VIEŠPATIES žodis aiškiai atėjo Buzio sūnui kunigui Ezekieliui, kaldėjų šalyje prie Kebaro upės; ir ten ant jo buvo VIEŠPATIES ranka.'),
  (@b26, 1, 4, 'Aš pažiūrėjau, ir štai iš šiaurės atėjo viesulas, didelis debesis, apsupanti ugnis, ir aplinkui ją buvo šviesa, ir iš jos vidurio, iš ugnies vidurio, tarsi gintaro spalva.'),
  (@b26, 1, 5, 'Taip pat iš jos vidurio atėjo keturių gyvų sutvėrimų panašumai. Ir tokia buvo jų išvaizda: jie turėjo žmogaus panašumą.'),
  (@b26, 1, 6, 'Ir kiekvienas turėjo keturis veidus ir kiekvienas keturis sparnus.'),
  (@b26, 1, 7, 'Jų kojos buvo tiesios kojos; o jų kojų padai buvo kaip veršio kojų padai; ir jie žėrėjo tarsi nublizginto žalvario spalva.'),
  (@b26, 1, 8, 'Po jų sparnais keturiuose jų šonuose jie turėjo žmogaus rankas; ir tie keturi turėjo savo veidus ir savo sparnus.'),
  (@b26, 1, 9, 'Jų sparnai buvo sujungti vienas su kitu; jie eidami nesisukinėjo; jie kiekvienas ėjo tiesiai pirmyn.'),
  (@b26, 1, 10, 'O jų veidų išvaizda, jie visi keturi dešinėje pusėje turėjo žmogaus veidą ir liūto veidą; ir visi keturi kairėje pusėje turėjo jaučio veidą; taip pat visi keturi turėjo erelio veidą.'),
  (@b26, 1, 11, 'Tokie buvo jų veidai; ir jų sparnai buvo ištiesti į viršų; kiekvieno jų du sparnai buvo susijungę vienas su kitu, o kiti du dengė jų kūnus.'),
  (@b26, 1, 12, 'Ir jie kiekvienas ėjo tiesiai pirmyn; kur dvasia norėjo eiti – ten jie ėjo; ir eidami jie nesisukiojo.'),
  (@b26, 1, 13, 'O dėl gyvųjų sutvėrimų panašumo, jų išvaizda buvo kaip degančios ugnies žarijos ir kaip žibintų išvaizda; judėjo tarp gyvųjų sutvėrimų šen bei ten; ir ugnis buvo šviesi, o iš ugnies išėjo žaibas.'),
  (@b26, 1, 14, 'Gyvieji sutvėrimai judėjo pirmyn ir atgal, atrodydami tarsi žaibavimas.'),
  (@b26, 1, 15, 'Na, o man bežiūrint į gyvus sutvėrimus, štai vienas ratas ant žemės, šalia gyvųjų sutvėrimų su keturiais veidais.'),
  (@b26, 1, 16, 'Ratų išvaizda ir jų padarymas buvo tarsi berilo spalva; ir visi keturi buvo vienodai panašūs; jų išvaizda ir jų padarymas buvo tarsi ratas rato viduje.'),
  (@b26, 1, 17, 'Kai jie ėjo, jie ėjo į savo keturias puses; eidami jie nesisukiojo.'),
  (@b26, 1, 18, 'O dėl jų žiedų, jie buvo tokie aukšti, kad buvo bauginantys; ir jų žiedai, aplink juos visus keturis, buvo pilni akių.'),
  (@b26, 1, 19, 'Gyviems sutvėrimams einant, ratai ėjo šalia jų; o gyviems sutvėrimams pakylant nuo žemės, kilo ir ratai.'),
  (@b26, 1, 20, 'Kur dvasia norėjo eiti, jie ėjo, ten, kur jų dvasia norėjo eiti; ir ratai pakildavo priešais juos; nes gyvojo sutvėrimo dvasia buvo ratuose.'),
  (@b26, 1, 21, 'Aniems einant, ir tie ėjo; o kai anie sustodavo, tie sustodavo; aniems pakylant nuo žemės, ir ratai pakildavo priešais juos; nes gyvojo sutvėrimo dvasia buvo ratuose.'),
  (@b26, 1, 22, 'Ir tvirtumos, esančios ant gyvojo sutvėrimo galvų, panašumas buvo kaip spalva bauginančio krištolo, ištiesto aukštai virš jų galvų.'),
  (@b26, 1, 23, 'O po tvirtuma buvo jų sparnai tiesiai vienas į kitą; kiekvienas turėjo po du, jų kūnus apdengiančius šioje pusėje ir kiekvienas turėjo po du, jų kūnus apdengiančius anoje pusėje.'),
  (@b26, 1, 24, 'Ir jiems einant, girdėjau jų sparnų ūžimą, kaip didelių vandenų ūžimą, kaip Visagalio balsą, kalbos balsą, kaip kariuomenės triukšmą; sustoję, jie nuleisdavo savo sparnus.'),
  (@b26, 1, 25, 'Ir buvo balsas iš tvirtumos, esančios viršum jų galvų, kai jie sustojo ir nuleido savo sparnus.'),
  (@b26, 1, 26, 'Ir virš tvirtumos, esančios viršum jų galvų, buvo panašumas į sostą, kaip safyro akmens išvaizda; o ant sosto panašumo buvo tarsi žmogaus išvaizdos panašumas ant jo.'),
  (@b26, 1, 27, 'Ir aš mačiau tarsi gintaro spalvą, kaip ugnies išvaizdą viduje aplinkui, nuo jo juosmens išvaizdos į viršų ir nuo jo juosmens išvaizdos žemyn, aš mačiau tarsi išvaizdą ugnies, ir ji aplinkui švietė.'),
  (@b26, 1, 28, 'Kaip išvaizda lanko, esančio lietaus dieną debesyje, tokia buvo išvaizda aplinkui esančios šviesos. Tokia buvo VIEŠPATIES šlovės panašumo išvaizda. Ir tai pamatęs, aš kritau veidu žemėn ir išgirdau kalbančiojo balsą.'),
  (@b26, 2, 1, 'Ir jis man tarė: „Žmogaus sūnau, stokis ant savo kojų, ir aš tau kalbėsiu“.'),
  (@b26, 2, 2, 'Jam prakalbus į mane, Dvasia įėjo į mane ir pastatė mane ant mano kojų, kai aš girdėjau jį, kalbantį man.'),
  (@b26, 2, 3, 'Ir jis man tarė: „Žmogaus sūnau, aš tave siunčiu pas Izraelio vaikus, pas maištaujančią tautą, kurie maištavo prieš mane; jie ir jų tėvai nusižengė prieš mane iki pat šios dienos.'),
  (@b26, 2, 4, 'Nes jie įžūlūs vaikai ir kietaširdžiai. Pas juos aš tave siunčiu; ir tu jiems sakyk: ‘Taip sako Viešpats DIEVAS’.'),
  (@b26, 2, 5, 'O jie, ar jie klausys, ar jie susilaikys (nes jie yra maištaujantys namai), tačiau žinos, kad pranašas buvo tarp jų.'),
  (@b26, 2, 6, 'O tu, žmogaus sūnau, nebijok jų ir nebijok jų žodžių, nors erškėčiai ir dygliai yra su tavimi, ir tu gyveni tarp skorpionų; nebijok jų žodžių ir nebūk sunerimęs nuo jų žvilgsnių, nors jie yra maištingi namai.'),
  (@b26, 2, 7, 'Ir tu jiems kalbėk mano žodžius, ar jie klausysis, ar jie susilaikys; nes jie yra labai maištingi.'),
  (@b26, 2, 8, 'Bet tu, žmogaus sūnau, klausyk, ką aš tau kalbu: ‘Nebūk maištingas kaip anie maištingi namai; atverk savo burną ir valgyk, ką aš tau duodu’“.'),
  (@b26, 2, 9, 'Ir kai pažvelgiau, štai ranka, ištiesta į mane; ir štai joje buvo knygos ritinys;'),
  (@b26, 2, 10, 'ir jis išskleidė jį prieš mane; ir jis buvo prirašytas viduje ir išorėje; ir jame buvo užrašytos raudos, gedulas ir vargas.'),
  (@b26, 3, 1, 'Jis man dar tarė: „Žmogaus sūnau, valgyk, ką randi; valgyk šitą ritinį ir eik, kalbėk Izraelio namams“.'),
  (@b26, 3, 2, 'Taigi aš atvėriau savo burną, ir jis man davė valgyti tą ritinį.'),
  (@b26, 3, 3, 'Ir jis man tarė: „Žmogaus sūnau, pamaitink savo pilvą ir pripildyk savo vidurius šituo ritiniu, kurį aš tau duodu“. Tada aš jį valgiau; ir jis mano burnoje buvo saldus kaip medus.'),
  (@b26, 3, 4, 'Ir jis man tarė: „Žmogaus sūnau, eik, nueik į Izraelio namus ir jiems kalbėk mano žodžiais.'),
  (@b26, 3, 5, 'Nes tu nesi siunčiamas pas svetimos šnekos ir sunkios kalbos žmones, bet pas Izraelio namus;'),
  (@b26, 3, 6, 'ne pas daugelį svetimos šnekos ir sunkios kalbos tautų, kurių žodžių negali suprasti. Tikrai, jei tave siųsčiau pas jas, jos tavęs klausytų.'),
  (@b26, 3, 7, 'Bet Izraelio namai tavęs neklausys; nes jie manęs neklausys; nes visi Izraelio namai yra įžūlūs ir kietaširdžiai.'),
  (@b26, 3, 8, 'Štai aš padariau tavo veidą tvirtą prieš jų veidus ir tavo kaktą tvirtą prieš jų kaktas.'),
  (@b26, 3, 9, 'Kaip deimantas kietesnis už titnagą, tokią padariau tavo kaktą; nebijok jų ir nebūk sunerimęs nuo jų žvilgsnių, nors jie maištingi namai“.'),
  (@b26, 3, 10, 'Jis man dar tarė: „Žmogaus sūnau, visus mano žodžius, kuriuos tau kalbėsiu, priimk į savo širdį ir išgirsk savo ausimis.'),
  (@b26, 3, 11, 'Ir eik, nueik pas belaisvius, pas savo tautos vaikus, kalbėk jiems ir sakyk: ‘Taip sako Viešpats DIEVAS’; ar jie klausys, ar jie susilaikys“.'),
  (@b26, 3, 12, 'Tada Dvasia pakėlė mane ir aš išgirdau sau už nugaros didelį veržlų balsą, sakantį: „Tebūna palaiminta VIEŠPATIES šlovė iš jo vietos“.'),
  (@b26, 3, 13, 'Taip pat išgirdau garsą gyvųjų sutvėrimų sparnų, liečiančių vienas kitą, ir priešais juos esančių ratų bildesį, ir didelį veržlų garsą.'),
  (@b26, 3, 14, 'Taigi Dvasia mane pakėlė ir nunešė, ir aš ėjau apkartęs, įkaitinta dvasia; bet VIEŠPATIES ranka buvo stipri ant manęs.'),
  (@b26, 3, 15, 'Tada aš atvykau į Tel-Abibą pas belaisvius, gyvenančius prie Kebaro upės, ir sėdėjau, kur jie sėdėjo, ir pasilikau ten tarp jų apstulbęs septynias dienas.'),
  (@b26, 3, 16, 'Ir septynioms dienoms pasibaigus įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 3, 17, '„Žmogaus sūnau, aš tave paskyriau sargybiniu Izraelio namams; todėl išgirsk žodį iš mano burnos ir duok jiems įspėjimą nuo manęs.'),
  (@b26, 3, 18, 'Kai sakysiu nedorėliui: ‘Tu tikrai mirsi’, o tu jo neįspėsi ir nekalbėsi, kad įspėtum nedorėlį dėl jo nedoro kelio, kad išgelbėtum jo gyvybę; tas nedorėlis mirs savo neteisybėje, bet jo kraujo aš pareikalausiu iš tavo rankos.'),
  (@b26, 3, 19, 'Tačiau jei tu įspėsi nedorėlį, bet jis nenusisuks nuo savo nedorybės ir nuo savo nedoro kelio, jis mirs savo neteisybėje, bet tu būsi išgelbėjęs savo sielą.'),
  (@b26, 3, 20, 'Vėl gi, kai teisusis nusigręš nuo savo teisumo ir darys neteisybę, ir aš prieš jį padėsiu kliūtį, jis mirs; kadangi tu nebūsi jo įspėjęs, jis mirs savo nuodėmėje, ir nebus atsiminta jo padaryto teisumo; bet jo kraujo aš pareikalausiu iš tavo rankos.'),
  (@b26, 3, 21, 'Tačiau jei tu įspėsi teisųjį, kad teisusis nenusidėtų, ir jis nenusidės, jis tikrai išliks gyvas, nes jis įspėtas; taip pat ir tu būsi išgelbėjęs savo sielą“.'),
  (@b26, 3, 22, 'Ir ten ant manęs buvo VIEŠPATIES ranka, ir jis man tarė: „Kelkis, išeik į lygumą, ir ten aš kalbėsiu su tavimi“.'),
  (@b26, 3, 23, 'Tada aš atsikėliau ir išėjau į lygumą; ir štai ten stovėjo VIEŠPATIES šlovė, kaip ta šlovė, kurią mačiau prie Kebaro upės; ir aš parpuoliau veidu į žemę.'),
  (@b26, 3, 24, 'Tada Dvasia įėjo į mane, pastatė mane ant mano kojų, kalbėjo su manimi ir man tarė: „Eik, užsirakink savo namų viduje.'),
  (@b26, 3, 25, 'Bet tu, žmogaus sūnau, žiūrėk, jie uždės ant tavęs raiščius ir jais tave suriš, ir tu neišeisi tarp jų;'),
  (@b26, 3, 26, 'ir aš taip prilipdysiu tavo liežuvį prie tavo gomurio, kad būsi nebylys ir nebūsi jiems pabarėjas; nes jie yra maištingi namai.'),
  (@b26, 3, 27, 'Bet kai aš kalbėsiu su tavimi, aš atversiu tavo burną, ir tu jiems sakysi: ‘Taip sako Viešpats DIEVAS: ‘Kas klausosi, tas tesiklauso, o kas susilaiko, tas tesusilaiko’; nes jie yra maištingi namai“.'),
  (@b26, 4, 1, '„Taip pat tu, žmogaus sūnau, pasiimk plytą, padėk ją prieš save ir nupiešk ant jos miestą – Jeruzalę;'),
  (@b26, 4, 2, 'apgulk jį, pastatyk prieš jį fortą, supilk prieš jį kalną; taipogi pastatyk prieš jį stovyklą ir pastatyk prieš jį aplinkui mūrdaužius.'),
  (@b26, 4, 3, 'Be to, pasiimk geležinę keptuvę ir ją padėk kaip geležinę sieną tarp savęs ir miesto; nukreipk savo veidą prieš jį, ir jis bus apgultas, ir tu jį apgulk. Tai bus ženklas Izraelio namams.'),
  (@b26, 4, 4, 'Taipogi atsigulk ant savo kairiojo šono ir uždėk ant jo Izraelio namų neteisybę; kiek pagal dienų skaičių ant jo gulėsi, tiek tu neši jų neteisybę.'),
  (@b26, 4, 5, 'Nes aš ant tavęs uždėjau jų neteisybės metus pagal dienų skaičių – tris šimtus devyniasdešimt dienų; taip tu neši Izraelio namų kaltę.'),
  (@b26, 4, 6, 'O kai būsi jas išpildęs, atsigulk ant savo dešinio šono ir nešk Judos namų neteisybę keturiasdešimt dienų; aš tau nustačiau po dieną už metus.'),
  (@b26, 4, 7, 'Todėl nukreipk savo veidą į Jeruzalės apgultį, ir tavo ranka bus apnuoginta, ir pranašauk prieš ją.'),
  (@b26, 4, 8, 'Ir štai aš apdėsiu tave raiščiais, ir tu neapsiversi nuo vieno šono ant kito, kol nebūsi pabaigęs savo apgulties dienų.'),
  (@b26, 4, 9, 'Taip pat pasiimk kviečių, miežių, pupų, lęšių, sorų bei juodgrūdžių ir sudėk juos į vieną indą, ir pasidaryk iš jų duonos pagal skaičių dienų, kai gulėsi ant savo šono – valgyk ją tris šimtus devyniasdešimt dienų.'),
  (@b26, 4, 10, 'Ir tavo maistas, kurį valgysi, pagal svorį bus dvidešimt šekelių dienai; valgyk jį laikas nuo laiko.'),
  (@b26, 4, 11, 'Taip pat gerk atseikėjęs vandens – šeštą hino dalį; gerk jį laikas nuo laiko.'),
  (@b26, 4, 12, 'Ir valgyk tai kaip miežinius paplotėlius, ir jiems matant kepk tai su mėšlu, išeinančiu iš žmogaus“.'),
  (@b26, 4, 13, 'Ir VIEŠPATS tarė: „Taip Izraelio vaikai valgys savo suterštą duoną tarp pagonių, kur juos išvarysiu“.'),
  (@b26, 4, 14, 'Tada aš tariau: „Ak, Viešpatie DIEVE! Štai mano siela nebuvo suteršta: nes nuo savo jaunystės iki dabar nesu valgęs nei maitos, nei to, kas sudraskyta; ir į mano burną neįėjo pasibjaurėtina mėsa“.'),
  (@b26, 4, 15, 'Tada jis man tarė: „Štai vietoj žmogaus mėšlo tau daviau karvės mėšlą, juo paruošk sau duonos“.'),
  (@b26, 4, 16, 'Jis man dar tarė: „Žmogaus sūnau, štai aš sulaužysiu duonos ramstį Jeruzalėje; ir jie valgys duoną pagal svorį ir susirūpinę; ir jie gers vandenį atseikėtą ir apstulbę;'),
  (@b26, 4, 17, 'kad jie stokotų duonos bei vandens ir būtų apstulbę vienas kitu, ir sunyktų dėl savo neteisybės“.'),
  (@b26, 5, 1, '„O tu, žmogaus sūnau, pasiimk aštrų peilį, pasiimk kirpėjo skustuvą ir brauk juo sau per galvą ir per barzdą; paskui pasiimk svarstykles, kad pasvertum, ir padalyk plaukus.'),
  (@b26, 5, 2, 'Apgulties dienoms išsipildžius, ugnimi trečdalį sudegink miesto viduryje; paimk trečdalį ir aplink jį sukapok peiliu; o trečdalį išbarstyk į vėją; ir aš ištrauksiu paskui juos kalaviją.'),
  (@b26, 5, 3, 'Taipogi paimk iš jų mažą skaičių ir juos įrišk į savo skverną.'),
  (@b26, 5, 4, 'Paskui vėl paimk iš jų ir juos įmesk į ugnies vidurį, ir sudegink ugnyje; nes iš ten ugnis išeis į visus Izraelio namus.'),
  (@b26, 5, 5, 'Taip sako Viešpats DIEVAS: ‘Tai Jeruzalė; pastačiau ją viduryje tautų ir šalių, esančių aplink ją.'),
  (@b26, 5, 6, 'O ji mano teismus pakeitė į nedorybę labiau nei tautos, ir mano įstatus labiau nei jos aplinkinės šalys; nes jie atmetė mano teismus ir mano įstatus, jie nevaikščiojo pagal juos’.'),
  (@b26, 5, 7, 'Todėl taip sako Viešpats DIEVAS: ‘Kadangi dauginotės labiau nei jūsų aplinkinės tautos ir nevaikščiojote pagal mano įstatus, ir nesilaikėte mano teismų nei nedarėte pagal aplink jus esančių tautų teismus;'),
  (@b26, 5, 8, 'todėl taip sako Viešpats DIEVAS: Štai aš, būtent aš esu prieš tave ir tautoms matant vykdysiu tavo viduryje teismus.'),
  (@b26, 5, 9, 'Ir dėl visų tavo bjaurysčių tavyje darysiu tai, ko nesu daręs ir į ką nieko panašaus nebedarysiu.'),
  (@b26, 5, 10, 'Todėl tavo tarpe tėvai valgys sūnus, o sūnūs valgys savo tėvus; aš įvykdysiu tavyje teismus ir visą tavo likutį išsklaidysiu po visus vėjus.'),
  (@b26, 5, 11, 'Todėl, kaip aš gyvas, – sako Viešpats DIEVAS; – tikrai, kadangi tu suteršei mano šventovę visomis savo šlykštybėmis ir visomis savo bjaurystėmis, todėl aš tave taipogi sumažinsiu; ir mano akis nepasigailės, ir man nebus gaila.'),
  (@b26, 5, 12, 'Tavo trečdalis mirs nuo maro, ir nuo bado jie bus sunaikinti tavo tarpe; trečdalis kris nuo kalavijo aplink tave; o trečdalį išsklaidysiu į visus vėjus ir paskui juos ištrauksiu kalaviją.'),
  (@b26, 5, 13, 'Taip bus užbaigtas mano pyktis, ir aš ilsinsiu savo įtūžį ant jų, ir būsiu paguostas; ir jie žinos, kad aš, VIEŠPATS, kalbėjau tai savo uolume, kai būsiu užbaigęs juose savo įtūžį.'),
  (@b26, 5, 14, 'Be to, aš padarysiu tave dykyne ir priekaištu tarp tavo aplinkinių tautų, visų, praeinančiųjų pro šalį, akyse.'),
  (@b26, 5, 15, 'Taigi tai bus priekaištas ir pajuoka, pamokymas ir apstulbimas tavo aplinkinėms tautoms, kai aš supykęs, įtūžęs ir įtūžusiais barimais įvykdysiu tavyje teismus. Aš, VIEŠPATS, tai kalbėjau.'),
  (@b26, 5, 16, 'Kai paleisiu į juos piktas bado strėles, kurios bus jų sunaikinimui ir kurias paleisiu jus sunaikinti; ir ant jūsų padidinsiu badą, ir sulaužysiu jūsų duonos ramstį;'),
  (@b26, 5, 17, 'taigi aš pasiųsiu ant jūsų badą ir piktus žvėris, ir jie atims tavo vaikus; maras ir kraujas pereis per tave; ir atvesiu ant tavęs kalaviją. Aš, VIEŠPATS, tai kalbėjau’“.'),
  (@b26, 6, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 6, 2, '„Žmogaus sūnau, nukreipk savo veidą į Izraelio kalnus ir pranašauk prieš juos,'),
  (@b26, 6, 3, 'ir sakyk: Izraelio kalnai, klausykite Viešpaties DIEVO žodžio; taip sako Viešpats DIEVAS kalnams ir kalvoms, upėms ir slėniams: ‘Štai aš atvesiu ant jūsų kalaviją ir sunaikinsiu jūsų aukštumas.'),
  (@b26, 6, 4, 'Jūsų aukurai bus suniokoti ir jūsų atvaizdai bus sudaužyti; aš išvartysiu jūsų išžudytuosius prieš jūsų stabus.'),
  (@b26, 6, 5, 'Ir išguldysiu Izraelio vaikų lavonus prieš jų stabus; ir išbarstysiu jūsų kaulus aplink jūsų aukurus.'),
  (@b26, 6, 6, 'Visose jūsų gyvenvietėse miestai bus ištuštinti ir aukštumos bus suniokotos; kad jūsų aukurai būtų suniokoti ir apleisti, jūsų stabai būtų sudaužyti ir išnyktų, jūsų atvaizdai būtų iškirsti ir jūsų darbai būtų panaikinti.'),
  (@b26, 6, 7, 'Užmuštieji kris tarp jūsų, ir jūs žinosite, kad aš esu VIEŠPATS.'),
  (@b26, 6, 8, 'Tačiau aš paliksiu likutį, kad jūs turėtumėte nuo kalavijo ištrūkusiųjų tarp tautų, kai būsite išsklaidyti po šalis.'),
  (@b26, 6, 9, 'Ir jūsų ištrūkėliai atsimins mane tarp tautų, kur jie bus išvesti nelaisvėn, nes aš esu palūžęs nuo jų paleistuvingos širdies, atsitraukusios nuo manęs, ir nuo jų akių, paleistuvingai nusekusių paskui jų stabus; ir jie bjaurėsis savimi dėl piktybių, kurias jie darė visose savo bjaurystėse.'),
  (@b26, 6, 10, 'Ir jie žinos, kad aš esu VIEŠPATS ir neveltui sakiau, kad jiems padarysiu šitą nelaimę’.'),
  (@b26, 6, 11, 'Taip sako Viešpats DIEVAS: ‘Kirsk savo ranka, trypk koja ir sakyk: Vargas dėl Izraelio namų visų piktų bjaurysčių! Nes jie kris nuo kalavijo, nuo bado ir nuo maro.'),
  (@b26, 6, 12, 'Toli esantis mirs nuo maro; ir arti esantis kris nuo kalavijo; o tas, kuris yra pasilikęs ir apgultas, mirs nuo bado; taip aš ant jų įvykdysiu savo įniršį.'),
  (@b26, 6, 13, 'Tada jūs žinosite, kad aš esu VIEŠPATS, kai jų užmuštieji bus tarp jų stabų aplink jų aukurus ant kiekvienos aukštos kalvos, visose kalnų viršūnėse, po kiekvienu žaliuojančiu medžiu ir po kiekvienu tankiu ąžuolu, toje vietoje, kur jie atnašavo gardų kvapą visiems savo stabams.'),
  (@b26, 6, 14, 'Taigi aš ištiesiu ant jų savo ranką ir padarysiu šalį tuščią, taip, tuštesnę už dykumą link Diblos, visose jų gyvenvietėse; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 7, 1, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 7, 2, '„Tu, žmogaus sūnau, taip sako Viešpats DIEVAS Izraelio šaliai: ‘Atėjo galas, atėjo galas keturiems šalies pakraščiams.'),
  (@b26, 7, 3, 'Dabar atėjo tau galas, aš pasiųsiu ant tavęs savo pyktį, teisiu tave pagal tavo kelius ir ant tavęs atlyginsiu visas tavo bjaurystes.'),
  (@b26, 7, 4, 'Mano akis nesigailės tavęs, ir aš tavęs nepasigailėsiu; bet ant tavęs atlyginsiu tavo kelius, ir tavo bjaurystės bus tavo tarpe; ir jūs žinosite, kad esu VIEŠPATS’.'),
  (@b26, 7, 5, 'Taip sako Viešpats DIEVAS: ‘Nelaimė ir tik nelaimė štai atėjo.'),
  (@b26, 7, 6, 'Atėjo galas, atėjo galas; jis tavęs tykoja; štai jis atėjo.'),
  (@b26, 7, 7, 'Atėjo tau rytas, o šalies gyventojau; atėjo laikas, arti diena vargo, o ne kalnų aido.'),
  (@b26, 7, 8, 'Dabar, netrukus, ant tavęs išliesiu savo įtūžį ir ant tavęs įvykdysiu savo pyktį; ir aš tave teisiu pagal tavo kelius ir atlyginsiu tau už visas tavo bjaurystes.'),
  (@b26, 7, 9, 'Mano akis nesigailės tavęs ir aš tavęs nepasigailėsiu; aš tau atlyginsiu pagal tavo kelius ir tavo bjaurystes, esančias tavo tarpe; ir jūs žinosite, kad esu VIEŠPATS, kuris sumuša.'),
  (@b26, 7, 10, 'Štai diena, štai ji atėjo; išėjo rytas; pražydo lazda, išsprogo išdidumas.'),
  (@b26, 7, 11, 'Smurtas išaugo į nedorybės lazdą; nieko nepaliks iš jų nei iš jų daugybės, nei iš to, ką jie turi; ir nebus dėl jų raudama.'),
  (@b26, 7, 12, 'Atėjo laikas, artėja diena; tenesidžiaugia pirkėjas ir teneliūdi pardavėjas; nes rūstybė ant visos jų daugybės.'),
  (@b26, 7, 13, 'Nes pardavėjas nesugrįš prie to, kas parduota, nors jie tebebus gyvi; nes regėjimas yra apie visą jų daugybę, kurie nesugrįš; ir niekas savęs nesustiprins savo gyvenimo neteisybe.'),
  (@b26, 7, 14, 'Jie pūtė trimitą, kad viską paruošų; bet niekas neina į mūšį; nes mano rūstybė ant visos jų daugybės.'),
  (@b26, 7, 15, 'Kalavijas lauke, o maras ir badas viduje; kas yra lauke, tas mirs nuo kalavijo; o kas yra mieste, tą suės badas ir maras.'),
  (@b26, 7, 16, 'Bet jų pabėgėliai paspruks ir bus kalnuose kaip slėnių karveliai, visi raudantys, kiekvienas dėl savo neteisybės.'),
  (@b26, 7, 17, 'Visos rankos bus paliegusios ir visi keliai bus silpni kaip vanduo.'),
  (@b26, 7, 18, 'Taipogi jie apsijuos ašutinėmis, ir juos apdengs šiurpas; ant visų veidų bus gėda, ir ant visų jų galvų – plikė.'),
  (@b26, 7, 19, 'Savo sidabrą jie išmes į gatves, ir jų auksas bus pašalintas; jų sidabras ir jų auksas negalės jų išgelbėti VIEŠPATIES rūstybės dieną; jie nepatenkins savo sielų ir nepripildys savo vidurių; nes tai yra jų neteisybės kliūtis.'),
  (@b26, 7, 20, 'Jo papuošalų grožį jis papuošė didybe; bet jie iš jo padarė savo bjaurysčių ir savo šlykštybių atvaizdus; todėl jį nutolinsiu nuo jų.'),
  (@b26, 7, 21, 'Atiduosiu jį kaip laimikį į svetimšalių rankas ir kaip grobį žemės nedorėliams; ir jie išniekins jį.'),
  (@b26, 7, 22, 'Taip pat aš nukreipsiu nuo jų savo veidą, ir jie suterš mano slaptavietę; nes į ją įeis plėšikai ir išniekins ją.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b26, 7, 23, 'Padaryk grandinę; nes šalis pilna kruvinų nusikaltimų, ir miestas pilnas smurto.'),
  (@b26, 7, 24, 'Todėl aš atvesiu blogiausius iš pagonių, ir jie pasisavins jų namus; taip pat padarysiu galą stipriųjų pasipūtimui; ir jų šventos vietos bus išniekintos.'),
  (@b26, 7, 25, 'Ateina sunaikinimas; jie ieškos taikos, bet jos nebus.'),
  (@b26, 7, 26, 'Ateis nelaimė po nelaimės ir gandas bus po gando; tada jie ieškos pranašo regėjimo; bet įstatymo nebebus pas kunigą ir patarimo pas senolius.'),
  (@b26, 7, 27, 'Karalius gedės, ir kunigaikštis bus apsivilkęs sielvartu, o šalies tautos rankos bus sunerimusios; aš jiems darysiu pagal jų kelią, ir juos teisiu pagal jų nuopelnus; ir jie žinos, kad esu VIEŠPATS“.'),
  (@b26, 8, 1, 'Ir šeštaisiais metais, šeštąjį mėnesį, to mėnesio penktąją dieną, man besėdint savo namuose ir Judos vyresniesiems besėdint mano akivaizdoje įvyko, kad ten ant manęs nupuolė Viešpaties DIEVO ranka.'),
  (@b26, 8, 2, 'Tada aš pažiūrėjau, ir štai panašumas tarsi ugnies išvaizdos; nuo jo juosmens išvaizdos žemyn – ugnis, o nuo jo juosmens aukštyn – tarsi spindesio išvaizda, tarsi gintaro spalva.'),
  (@b26, 8, 3, 'Jis ištiesė tarsi rankos pavidalą ir nutvėrė mane už mano galvos garbanos; ir Dvasia mane pakėlė tarp žemės ir dangaus, ir Dievo regėjimuose nunešė mane į Jeruzalę, prie durų vidinių vartų, nukreiptų į šiaurę, kur buvo vieta pavydo atvaizdo, kurstančio pavydą.'),
  (@b26, 8, 4, 'Ir štai ten buvo Izraelio Dievo šlovė pagal tą regėjimą, kurį mačiau lygumoje.'),
  (@b26, 8, 5, 'Tada jis man tarė: „Žmogaus sūnau, pakelk savo akis į kelią šiaurės pusės link“. Taigi aš pakėliau akis į kelią šiaurės pusės link ir štai, į šiaurę prie aukuro vartų buvo šis pavydo atvaizdas įėjime.'),
  (@b26, 8, 6, 'Ir jis man toliau tarė: „Žmogaus sūnau, ar tu matai, ką jie daro, būtent dideles bjaurystes, kurias čia daro Izraelio namai, kad aš eičiau toli nuo savo šventovės? Bet tu dar atsisuk ir pamatysi didesnių bjaurysčių“.'),
  (@b26, 8, 7, 'Ir jis mane atvedė prie kiemo durų; aš pažiūrėjau, ir štai skylė sienoje.'),
  (@b26, 8, 8, 'Tada jis man tarė: „Žmogaus sūnau, prakask sieną“. Aš prakasiau sieną, ir štai buvo durys.'),
  (@b26, 8, 9, 'Ir jis man tarė: „Įeik ir pažiūrėk į piktas bjaurystes, kurias jie čia daro“.'),
  (@b26, 8, 10, 'Taigi aš įėjau ir pamačiau; ir štai visokiausi roplių ir bjaurių žvėrių pavidalai, ir visokie Izraelio namų stabai, nupiešti aplinkui ant sienos.'),
  (@b26, 8, 11, 'Ir prieš juos stovėjo septyniasdešimt vyrų iš Izraelio namų senolių, ir jų viduryje stovėjo Šafano sūnus Jaazanijas; pas kiekvieną rankoje buvo po smilkytuvą; ir kilo aukštyn tirštas smilkalų debesis.'),
  (@b26, 8, 12, 'Tada jis man tarė: „Žmogaus sūnau, ar matei, ką Izraelio namų senoliai daro tamsoje, kiekvienas savo piešinių kambaryje? Nes jie sako: ‘VIEŠPATS nemato mūsų; VIEŠPATS paliko žemę’“.'),
  (@b26, 8, 13, 'Jis man dar tarė: „Dar apsisuk, ir tu pamatysi didesnių bjaurysčių, kurias jie daro“.'),
  (@b26, 8, 14, 'Tada jis mane nuvedė prie durų VIEŠPATIES namų vartų, nukreiptų į šiaurę; ir štai ten sėdėjo moterys, apverkiančios Tamūzą.'),
  (@b26, 8, 15, 'Tada jis man tarė: „Ar matei tai, o žmogaus sūnau? Dar apsisuk, ir tu pamatysi didesnių bjaurysčių už šitas“.'),
  (@b26, 8, 16, 'Ir jis nuvedė mane į VIEŠPATIES namų vidinį kiemą, ir štai prie VIEŠPATIES šventyklos durų, tarp prieangio ir aukuro, buvo maždaug dvidešimt penki vyrai, savo nugaromis link VIEŠPATIES šventyklos, o savo veidais – rytų link; ir jie garbino saulę rytų link.'),
  (@b26, 8, 17, 'Tada jis man tarė: „Ar matei tai, žmogaus sūnau? Ar Judos namams per maža, kad jie darytų bjaurystes, kurias jie čia daro? Nes jie pripildė šalį smurto ir sugrįžo kurstyti mano pyktį; ir štai jie prideda šaką sau prie nosies.'),
  (@b26, 8, 18, 'Todėl ir aš veiksiu įtūžęs; mano akis nepagailės, ir aš nesigailėsiu; ir nors garsiu balsu jie šauks man į ausis, aš jų nesiklausysiu“.'),
  (@b26, 9, 1, 'Ir jis garsiu balsu šaukė man į ausis, sakydamas: „Priartink tuos, kurie įpareigoti dėl miesto, kiekvieną su savo naikinančiu ginklu savo rankoje“.'),
  (@b26, 9, 2, 'Ir štai šeši vyrai atėjo nuo aukštutinių vartų kelio, nukreipto į šiaurę, ir kiekvienas su žudymo ginklu savo rankoje; o tarp jų vienas vyras buvo apsivilkęs linu, su raštininko rašaline prie juosmens; jie įėjo ir atsistojo šalia žalvarinio aukuro.'),
  (@b26, 9, 3, 'Ir Izraelio Dievo šlovė buvo pakilusi nuo kerubo, ant kurio ji buvo, namų slenksčio link. Ir jis pašaukė vyrą, apsivilkusį linu, turintį raštininko rašalinę prie juosmens;'),
  (@b26, 9, 4, 'ir VIEŠPATS jam tarė: „Eik per miesto vidurį, per Jeruzalės vidurį, ir paženklink kaktas žmonių, kurie dejuoja ir šaukia dėl visų jos tarpe daromų bjaurysčių“.'),
  (@b26, 9, 5, 'O kitiems, man girdint, jis tarė: „Eikite paskui jį per miestą ir užmušinėkite; tenesigaili jūsų akis, ir nepasigailėkite;'),
  (@b26, 9, 6, 'visiškai išžudykite senus ir jaunus, merginas ir mažus vaikus, ir moteris; bet nesiartinkite prie tų, ant kurių yra ženklas; ir pradėkite nuo mano šventovės“. Tada jie pradėjo nuo vyrų senolių, esančių priešais namus.'),
  (@b26, 9, 7, 'Ir jis jiems tarė: „Suterškite namus ir pripildykite kiemus užmuštųjų; išeikite“. Ir jie išėjo ir žudė mieste.'),
  (@b26, 9, 8, 'Ir įvyko, kai jie žudė juos, ir aš buvau išlikęs, aš parpuoliau veidu į žemę ir šaukdamas tariau: „Ak, Viešpatie DIEVE! Ar tu sunaikinsi visą Izraelio likutį, išliedamas savo įtūžį ant Jeruzalės?“'),
  (@b26, 9, 9, 'Tada jis man tarė: „Izraelio namų ir Judos neteisybė yra nepaprastai didelė, ir šalis pilna kraujo, o miestas pilnas iškreiptumo; nes jie sako: ‘VIEŠPATS paliko žemę, ir VIEŠPATS nemato’.'),
  (@b26, 9, 10, 'Tad ir mano akis nepagailės, ir aš nesigailėsiu, bet atlyginsiu jų kelią jiems ant galvų“.'),
  (@b26, 9, 11, 'Ir štai vyras, apsivilkęs linu, turintis rašalinę prie juosmens, pranešė reikalą, sakydamas: „Padariau, kaip man įsakei“.'),
  (@b26, 10, 1, 'Tada aš pažiūrėjau, ir štai tvirtumoje, esančioje virš kerubų galvos, viršum jų pasirodė tarsi safyro akmuo, kaip sosto panašumo išvaizda.'),
  (@b26, 10, 2, 'Ir jis kalbėjo linu apsivilkusiam vyrui ir tarė: „Įeik į tarpą ratų, tai yra, po kerubais, ir pripildyk savo ranką ugninių anglių iš kerubų tarpo, ir išbarstyk jas ant miesto“. Ir man matant, jis įėjo.'),
  (@b26, 10, 3, 'Na, o tam vyrui įėjus, kerubai stovėjo namų dešinėje pusėje; ir debesis pripildė vidinį kiemą.'),
  (@b26, 10, 4, 'Tada VIEŠPATIES šlovė pakilo nuo kerubo ir sustojo virš namų slenksčio; ir namai prisipildė debesies, o kiemas buvo pilnas VIEŠPATIES šlovės spindesio.'),
  (@b26, 10, 5, 'Ir kerubų sparnų garsas buvo girdimas net išoriniame kieme, kaip Visagalio Dievo balsas, kai jis kalba.'),
  (@b26, 10, 6, 'Ir įvyko, kad jam įsakius linu apsivilkusiam vyrui, sakant: „Paimk ugnies iš ratų tarpo, iš kerubų tarpo“, jis įėjęs atsistojo šalia ratų.'),
  (@b26, 10, 7, 'Ir vienas kerubas ištiesė savo ranką iš kerubų tarpo į ugnį, esančią tarp kerubų, ir paėmęs ją įdėjo linu apsivilkusiajam į rankas; šis ją paėmė ir išėjo.'),
  (@b26, 10, 8, 'Ir kerubuose po jų sparnais pasirodė žmogaus rankos pavidalas.'),
  (@b26, 10, 9, 'Ir man žiūrint, štai šalia kerubų keturi ratai, vienas ratas prie vieno kerubo, o kitas ratas prie kito kerubo; ir ratų išvaizda buvo tarsi berilo akmens spalva.'),
  (@b26, 10, 10, 'O dėl jų išvaizdos, tie keturi buvo vienodai panašūs, lyg vienas ratas būtų rato viduje.'),
  (@b26, 10, 11, 'Kai jie ėjo, jie ėjo į savo keturias puses; eidami jie nesisukiojo, bet į vietą, į kurią žiūrėjo galva, jie ėjo paskui ją; eidami jie nesisukiojo.'),
  (@b26, 10, 12, 'Ir jų visas kūnas, jų nugaros, jų rankos, jų sparnai ir ratai buvo aplinkui pilni akių, būtent ratai, kuriuos tie keturi turėjo.'),
  (@b26, 10, 13, 'O ratams, man girdint, jiems buvo šaukiama: „O rate!“'),
  (@b26, 10, 14, 'Ir kiekvienas turėjo keturis veidus: pirmas veidas buvo kerubo veidas, antras veidas buvo žmogaus veidas, trečiasis – liūto veidas, o ketvirtasis – erelio veidas.'),
  (@b26, 10, 15, 'Ir kerubai pakilo. Tai tas gyvasis sutvėrimas, kurį mačiau prie Kebaro upės.'),
  (@b26, 10, 16, 'Ir kerubams einant, ratai ėjo šalia jų; o kerubams pakėlus savo sparnus, kad pakiltų nuo žemės, tie ratai irgi nesisukiojo nuo jų pašonės.'),
  (@b26, 10, 17, 'Aniems stovint, jie stovėjo, o aniems pakylant, tie irgi pakildavo; nes gyvojo sutvėrimo dvasia buvo juose.'),
  (@b26, 10, 18, 'Tada VIEŠPATIES šlovė pasitraukė nuo namų slenksčio ir atsistojo virš kerubų.'),
  (@b26, 10, 19, 'Ir kerubai pakėlė savo sparnus, ir man matant pakilo nuo žemės; kai jie išėjo, ratai irgi buvo šalia jų, ir jie sustojo prie VIEŠPATIES namų rytinių vartų durų; ir Izraelio Dievo šlovė buvo viršuje virš jų.'),
  (@b26, 10, 20, 'Tai yra tas gyvasis sutvėrimas, kurį mačiau po Izraelio Dievu prie Kebaro upės; ir aš žinojau, kad jie buvo kerubai.'),
  (@b26, 10, 21, 'Kiekvienas turėjo po keturis veidus ir kiekvienas po keturis sparnus; ir po jų sparnais buvo žmogaus rankų panašumas.'),
  (@b26, 10, 22, 'O jų veidų panašumai buvo tokie, kaip veidai, kuriuos mačiau prie Kebaro upės – jų išvaizda ir jie patys; jie kiekvienas ėjo tiesiai į priekį.'),
  (@b26, 11, 1, 'Be to, Dvasia mane pakėlė ir nunešė prie VIEŠPATIES namų rytinių vartų, nukreiptų į rytus; ir štai prie vartų durų dvidešimt penki vyrai, tarp kurių pamačiau Azūro sūnų Jaazaniją ir Benajo sūnų Pelatiją, tautos kunigaikščius.'),
  (@b26, 11, 2, 'Tada jis man tarė: „Žmogaus sūnau, tie yra vyrai, kurie sumano piktadarybę ir duoda piktą patarimą šiame mieste;'),
  (@b26, 11, 3, 'kurie sako: ‘Tai nearti; statykime namus; šis miestas yra katilas, o mes esame mėsa’.'),
  (@b26, 11, 4, 'Todėl pranašauk prieš juos, pranašauk, o žmogaus sūnau“.'),
  (@b26, 11, 5, 'Ir VIEŠPATIES Dvasia nupuolė ant manęs ir man tarė: „Kalbėk: ‘Taip sako VIEŠPATS: Jūs taip sakėte, o Izraelio namai; nes aš žinau viską, kas ateina jums į galvą.'),
  (@b26, 11, 6, 'Jūs padauginote jūsų užmuštuosius šiame mieste ir pripildėte jo gatves užmuštųjų.'),
  (@b26, 11, 7, 'Todėl taip sako Viešpats DIEVAS: Jūsų užmuštieji, kuriuos paguldėte jo viduryje, yra mėsa, o šis miestas yra katilas; bet aš jus išvesiu iš jo vidurio.'),
  (@b26, 11, 8, 'Jūs bijote kalavijo; ir aš užleisiu ant jūsų kalaviją, – sako Viešpats DIEVAS.'),
  (@b26, 11, 9, 'Aš jus išvesiu iš jo vidurio ir atiduosiu jus į svetimšalių rankas, ir jums įvykdysiu teismus.'),
  (@b26, 11, 10, 'Jūs krisite nuo kalavijo; aš jus teisiu Izraelio ribose; ir jūs žinosite, kad aš esu VIEŠPATS.'),
  (@b26, 11, 11, 'Šitas miestas nebus jūsų katilu, ir jūs nebūsite mėsa jo viduryje; bet aš jus teisiu Izraelio ribose;'),
  (@b26, 11, 12, 'ir jūs žinosite, kad aš esu VIEŠPATS; nes jūs nevaikščiojote mano įstatais ir nevykdėte mano teismų, bet elgėtės pagal aplink jus esančių pagonių būdą’“.'),
  (@b26, 11, 13, 'Ir man pranašaujant įvyko, kad Benajo sūnus Pelatijas mirė. Tada aš parpuoliau veidu į žemę ir garsiu balsu šaukiau, sakydamas: „Ak, Viešpatie DIEVE! Ar tu padarysi visišką galą Izraelio likučiui?“'),
  (@b26, 11, 14, 'Vėl man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 11, 15, '„Žmogaus sūnau, tavo broliai, būtent tavo broliai, tavo giminės žmonės ir visi Izraelio namai, visa tai yra tie, kuriems Jeruzalės gyventojai sakė: ‘Atsitolinkite nuo VIEŠPATIES, mums ši šalis duota nuosavybėn’.'),
  (@b26, 11, 16, 'Todėl sakyk: ‘Taip sako Viešpats DIEVAS: Nors aš juos numečiau toli tarp pagonių ir nors juos išsklaidžiau tarp šalių, tačiau aš jiems būsiu kaip maža šventovė šalyse, į kurias jie ateis’.'),
  (@b26, 11, 17, 'Todėl sakyk: ‘Taip sako Viešpats DIEVAS: Aš jus išrinksiu iš tautų ir surinksiu jus iš šalių, po kurias buvote išsklaidyti, ir jums duosiu Izraelio šalį.'),
  (@b26, 11, 18, 'Ir jie ten ateis ir pašalins iš ten visas jos šlykštybes bei visas jos bjaurystes.'),
  (@b26, 11, 19, 'Ir jiems duosiu vieną širdį, ir į jūsų vidų įdėsiu naują dvasią; ir išimsiu iš jų kūno akmeninę širdį, ir jiems duosiu kūno širdį;'),
  (@b26, 11, 20, 'kad jie vaikščiotų pagal mano įstatus, laikytųsi mano potvarkių ir juos vykdytų; ir jie bus mano tauta, o aš būsiu jų Dievas.'),
  (@b26, 11, 21, 'Bet tiems, kurių širdis vaikšto paskui jų šlykštybių ir jų bjaurysčių širdį, jų kelią atlyginsiu ant jų pačių galvų, – sako Viešpats DIEVAS’“.'),
  (@b26, 11, 22, 'Tada kerubai pakėlė savo sparnus, ir ratai šalia jų; ir Izraelio Dievo šlovė buvo viršuje jų.'),
  (@b26, 11, 23, 'Ir VIEŠPATIES šlovė pakilo iš miesto vidurio ir sustojo ant kalno, esančio rytinėje miesto pusėje.'),
  (@b26, 11, 24, 'Po to Dvasia mane pakėlė ir regėjime per Dievo Dvasią nunešė mane į Kaldėją pas belaisvius. Taigi regėjimas, kurį buvau matęs, pakilo nuo manęs.'),
  (@b26, 11, 25, 'Tada aš kalbėjau belaisviams visus dalykus, kuriuos VIEŠPATS man buvo parodęs.'),
  (@b26, 12, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 12, 2, '„Žmogaus sūnau, tu gyveni tarpe maištaujančių namų, kurie turi akis matyti, bet nemato; jie turi ausis girdėti, bet negirdi; nes jie yra maištingi namai.'),
  (@b26, 12, 3, 'Todėl tu, žmogaus sūnau, pasiruošk daiktus persikėlimui ir, jiems matant, dienos metu, persikelk; ir jiems matant persikelk iš savo vietos į kitą vietą; gal jie apgalvos, nors jie yra maištingi namai.'),
  (@b26, 12, 4, 'Tada, dienos metu, jiems matant, išnešk savo daiktus kaip daiktus persikėlimui; ir tu išeik vakare, jiems matant, kaip išeina į nelaisvę.'),
  (@b26, 12, 5, 'Jiems matant prasikask sieną ir išnešk pro ją.'),
  (@b26, 12, 6, 'Jiems matant nešk juos ant pečių ir sutemus išnešk; užsidenk veidą, kad nematytum žemės; nes tave paskyriau ženklu Izraelio namams“.'),
  (@b26, 12, 7, 'Ir padariau taip, kaip man buvo įsakyta: dienos metu išsinešiau savo daiktus, kaip daiktus dėl nelaisvės, ir vakare ranka prasikasiau sieną; sutemus juos išsinešiau ir, jiems matant, užsikėliau juos ant peties.'),
  (@b26, 12, 8, 'Ir ryte man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 12, 9, '„Žmogaus sūnau, argi Izraelio namai, maištingi namai, tau nesakė: ‘Ką darai?’'),
  (@b26, 12, 10, 'Jiems sakyk: ‘Taip sako Viešpats DIEVAS: Šita našta dėl Jeruzalės kunigaikščio ir dėl visų Izraelio namų, esančių tarp jų’.'),
  (@b26, 12, 11, 'Sakyk: ‘Aš esu jums ženklas; kaip aš dariau, taip jiems bus padaryta; jie persikels ir eis nelaisvėn’.'),
  (@b26, 12, 12, 'O kunigaikštis, esantis tarp jų, sutemus neš ant savo peties ir išeis; jie prakas sieną, kad pro ją išneštų; jis užsidengs veidą, kad savo akimis nematytų žemės.'),
  (@b26, 12, 13, 'Taip pat aš ištiesiu ant jo savo tinklą, ir jis bus sugautas mano žabangomis; ir aš jį nuvesiu į Babiloną, į kaldėjų šalį; tačiau jis jos nematys, nors ten ir mirs.'),
  (@b26, 12, 14, 'Ir visus, esančius aplink jį, kad jam padėtų, ir visus jo būrius aš išsklaidysiu po visus vėjus; ir ištrauksiu kalaviją paskui juos.'),
  (@b26, 12, 15, 'Ir kai juos išsklaidysiu tarp tautų ir išbarstysiu juos šalyse, jie žinos, kad aš esu VIEŠPATS.'),
  (@b26, 12, 16, 'Bet iš jų nedaug žmonių paliksiu nuo kalavijo, bado ir maro; kad jie paskelbtų visas savo bjaurystes tarp pagonių, kur jie nueis; ir jie žinos, kad aš esu VIEŠPATS“.'),
  (@b26, 12, 17, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 12, 18, '„Žmogaus sūnau, valgyk savo duoną virpėdamas ir gerk savo vandenį drebėdamas ir susirūpinęs;'),
  (@b26, 12, 19, 'ir sakyk šalies tautai: ‘Taip sako Viešpats DIEVAS apie Jeruzalės gyventojus ir apie Izraelio šalį: Jie valgys savo duoną susirūpinę ir gers savo vandenį apstulbę, kad jos šalyje ištuštėtų visa, kas joje yra, dėl visų joje gyvenančių smurto.'),
  (@b26, 12, 20, 'Ir apgyventi miestai ištuštės, o šalis bus dykynė; ir jūs žinosite, kad aš esu VIEŠPATS’“.'),
  (@b26, 12, 21, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 12, 22, '„Žmogaus sūnau, kokia tai patarlė, kuri yra pas jus Izraelio šalyje, sakanti: ‘Dienos prailgėjo, ir žlunga kiekvienas regėjimas’?'),
  (@b26, 12, 23, 'Todėl jiems tark: ‘Taip sako Viešpats DIEVAS: Aš padarysiu šitai patarlei galą, ir jos daugiau nebevartos kaip patarlės Izraelyje; bet jiems kalbėk: Čia pat yra dienos ir kiekvieno regėjimo veikimas.'),
  (@b26, 12, 24, 'Nes daugiau nebebus jokio tuščio regėjimo nei pataikūniško ateities būrimo Izraelio namų viduje.'),
  (@b26, 12, 25, 'Nes aš esu VIEŠPATS; aš kalbėsiu, ir žodis, kurį kalbėsiu, įvyks; jis daugiau nebebus atidėtas; nes jūsų dienomis, o maištingi namai, aš kalbėsiu žodį ir jį įvykdysiu’, – sako Viešpats DIEVAS“.'),
  (@b26, 12, 26, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 12, 27, '„Žmogaus sūnau, štai tie, iš Izraelio namų, sako: ‘Regėjimas, kurį jis regi, yra daugeliui ateisiančių dienų, ir jis pranašauja apie tolimus laikus’.'),
  (@b26, 12, 28, 'Todėl jiems tark: ‘Taip sako Viešpats DIEVAS: Nei vienas iš mano žodžių nebebus atidedamas, bet žodis, kurį kalbėjau, bus įvykdytas’, – sako Viešpats DIEVAS“.'),
  (@b26, 13, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 13, 2, '„Žmogaus sūnau, pranašauk prieš Izraelio pranašus, kurie pranašauja, ir sakyk tiems, kurie pranašauja iš savo pačių širdies: ‘Klausykite VIEŠPATIES žodžio;'),
  (@b26, 13, 3, 'taip sako Viešpats DIEVAS: ‘Vargas kvailiems pranašams, kurie seka savo pačių dvasia ir nieko nematė!'),
  (@b26, 13, 4, 'O Izraeli, tavo pranašai kaip lapės dykumose.'),
  (@b26, 13, 5, 'Jūs nelipote į spragas ir nepastatėte tvoros Izraelio namams, kad atsilaikytų mūšyje VIEŠPATIES dieną.'),
  (@b26, 13, 6, 'Jie regėjo tuštybę ir melagingą pranašavimą, sakydami: „VIEŠPATS sako“, bet VIEŠPATS jų nesiuntė; ir padarė, kad kiti viltųsi, jog šie patvirtins žodį.'),
  (@b26, 13, 7, 'Argi neregėjote tuščio regėjimo ir argi nekalbėjote melagingo pranašavimo, sakydami: „VIEŠPATS tai sako“; nors aš ir nekalbėjau?'),
  (@b26, 13, 8, 'Todėl taip sako Viešpats DIEVAS: Kadangi kalbėjote tuštybę ir regėjote melus, todėl štai aš esu prieš jus, – sako Viešpats DIEVAS.'),
  (@b26, 13, 9, '– Ir mano ranka bus ant pranašų, reginčių tuštybę ir pranašaujančių melus; jie nebus mano tautos susirinkime ir nebus įrašyti į Izraelio namų raštą, ir neįeis į Izraelio šalį; ir jūs žinosite, kad aš esu Viešpats DIEVAS.'),
  (@b26, 13, 10, 'Todėl, būtent todėl, kad jie suvedžiojo mano tautą, sakydami: „Taika“, bet nebuvo taikos; ir vienas statė sieną, o štai kiti aptinkavo ją nemaišytu skiediniu;'),
  (@b26, 13, 11, 'sakyk tinkuojantiems ją nemaišytu skiediniu, kad ji sugrius; bus smarki liūtis; ir jūs, dideli krušos ledokšniai, krisite; ir audringas vėjas ją perplėš.'),
  (@b26, 13, 12, 'Štai kai siena sugrius, argi jums nesakys: „Kur yra tinkas, kuriuo ją tinkavote?“'),
  (@b26, 13, 13, 'Todėl taip sako Viešpats DIEVAS: Aš savo įtūžyje ją perplėšiu audringu vėju; ir mano pyktyje bus smarki liūtis, ir mano įtūžyje – dideli krušos ledokšniai, kad ją sunaikintų.'),
  (@b26, 13, 14, 'Taip aš nugriausiu sieną, kurią užglaistėte nemaišytu skiediniu, ir ją taip pargriausiu žemėn, kad atsidengs jos pamatas, ir ji grius, ir jūs būsite sunaikinti joje; ir jūs žinosite, jog aš esu VIEŠPATS.'),
  (@b26, 13, 15, 'Taip aš įvykdysiu savo rūstybę ant sienos ir ant tų, kurie ją nutinkavo nemaišytu skiediniu, ir jums sakysiu: „Nebėra nei sienos, nei tų, kurie ją tinkavo; –'),
  (@b26, 13, 16, 'tai yra, Izraelio pranašų, pranašavusių apie Jeruzalę ir jai regėjusių taikos regėjimų, kai nėra taikos“, – sako Viešpats DIEVAS’.'),
  (@b26, 13, 17, 'Taip pat ir tu, žmogaus sūnau, nukreipk savo veidą prieš savo tautos dukteris, kurios pranašauja iš savo pačių širdies; ir pranašauk prieš jas,'),
  (@b26, 13, 18, 'ir sakyk: ‘Taip sako Viešpats DIEVAS: Vargas siuvančioms pagalvėles kiekvienai pažasties prakarpai ir darančioms skareles kiekvieno ūgio galvoms, kad sumedžiotų sielas! Ar jūs medžiosite mano tautos sielas, ar išsaugosite sielas gyvas, ateinančias pas jus?'),
  (@b26, 13, 19, 'Ar jūs mane teršite mano tautos tarpe dėl saujų miežių ir duonos kąsnių, kad nužudytumėte sielas, kurios neturėtų mirti, ir kad išsaugotumėte sielas gyvas, kurios neturėtų gyventi, meluodamos mano tautai, klausančiai jūsų melus?'),
  (@b26, 13, 20, 'Todėl taip sako Viešpats DIEVAS: Štai aš prieš jūsų pagalvėles, kuriomis jūs medžiojate sielas, kad jas skraidintumėte; ir jas išplėšiu iš jūsų rankų, ir paleisiu sielas – sielas, kurias jūs medžiojate, kad jas skraidintumėte.'),
  (@b26, 13, 21, 'Taip pat sudraskysiu jūsų skareles ir išvaduosiu savo tautą iš jūsų rankos, ir jie nebebus jūsų rankoje, kad būtų medžiojami; ir jūs žinosite, jog aš esu VIEŠPATS.'),
  (@b26, 13, 22, 'Kadangi melais nuliūdinote teisiojo širdį, kurios aš neliūdinau, ir sustiprinote nedorėlio rankas, kad jis negrįžtų nuo savo nedoro kelio, pažadėdami jam gyvybę;'),
  (@b26, 13, 23, 'todėl neberegėsite tuštybės ir nebepranašausite pranašavimų; nes aš išvaduosiu savo tautą iš jūsų rankos; ir jūs žinosite, kad aš esu VIEŠPATS’“.'),
  (@b26, 14, 1, 'Tada pas mane atėjo kai kurie iš Izraelio vyresniųjų ir atsisėdo priešais mane.'),
  (@b26, 14, 2, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 14, 3, '„Žmogaus sūnau, šitie žmonės pasistatė savo širdyse savo stabus ir pastatė prieš savo akis savo neteisybės kliuvinį; argi aš iš viso turėčiau leistis jų klausiamas?'),
  (@b26, 14, 4, 'Todėl kalbėk jiems ir jiems sakyk: ‘Taip sako Viešpats DIEVAS: Kiekvienas iš Izraelio namų, kuris statosi savo širdyje savo stabus, pastato prieš savo akis savo neteisybės kliuvinį ir ateina pas pranašą; aš, VIEŠPATS, ateinančiam atsakysiu pagal jo stabų daugybę;'),
  (@b26, 14, 5, 'kad nutverčiau Izraelio namus jų pačių širdyje, kadangi jie visi nutolo nuo manęs per savo stabus’.'),
  (@b26, 14, 6, 'Todėl sakyk Izraelio namams: ‘Taip sako Viešpats DIEVAS: Atgailaukite ir gręžkitės nuo savo stabų; ir nugręžkite savo veidus nuo visų savo bjaurysčių.'),
  (@b26, 14, 7, 'Nes kiekvienas iš Izraelio namų ar iš laikinai Izraelyje apsigyvenusių ateivių, kurie atsiskiria nuo manęs, statosi savo širdyje savo stabus, stato sau prieš akis savo neteisybės kliuvinį ir ateina pas pranašą apie mane pasiklausti, tam aš pats, VIEŠPATS, atsakysiu;'),
  (@b26, 14, 8, 'aš nukreipsiu savo veidą prieš tą žmogų, padarysiu jį ženklu bei patarle ir iškirsiu jį iš mano tautos tarpo; ir jūs žinosite, kad aš esu VIEŠPATS.'),
  (@b26, 14, 9, 'O jei pranašas yra suklaidintas, pasakydamas reikalą, aš, VIEŠPATS, būsiu suklaidinęs tą pranašą ir ištiesiu ant jo savo ranką, ir jį išnaikinsiu iš savo tautos Izraelio tarpo.'),
  (@b26, 14, 10, 'Ir jie neš savo neteisybės bausmę; pranašo bausmė bus tokia pati, kaip ir jo ieškančiojo bausmė;'),
  (@b26, 14, 11, 'kad Izraelio namai nebenuklystų nuo manęs ir nebesusiterštų visais savo nusižengimais; bet kad jie būtų mano tauta, o aš būčiau jų Dievas, – sako Viešpats DIEVAS’“.'),
  (@b26, 14, 12, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 14, 13, '„Žmogaus sūnau, kai šalis prieš mane nusideda sunkiai nusižengdama, tada aš ant jos ištiesiu savo ranką ir sulaužysiu jos duonos ramstį, ir siųsiu ant jos badą, ir iškirsiu iš jos žmogų bei gyvulį;'),
  (@b26, 14, 14, 'net jeigu joje būtų šitie trys vyrai: Nojus, Danielius ir Jobas, jie savo teisumu išgelbėtų tik savo pačių sielas, – sako Viešpats DIEVAS.'),
  (@b26, 14, 15, '– Jei leisčiau piktiems žvėrims pereiti per šalį, ir jie taip ją išplėštų, kad ji būtų dykynė, jog niekas neitų per ją dėl žvėrių;'),
  (@b26, 14, 16, 'net jei šitie trys vyrai būtų joje, kaip aš gyvas, – sako Viešpats DIEVAS, – jie neišgelbėtų nei sūnų, nei dukterų; tik jie vieni būtų išgelbėti, bet šalis būtų nuniokota.'),
  (@b26, 14, 17, 'Arba jei atvesčiau kalaviją ant tos šalies ir sakyčiau: „Kalavijau, eik per šalį“; taip, kad iškirsčiau iš jos žmones bei gyvulius;'),
  (@b26, 14, 18, 'net jei tie trys vyrai būtų joje, kaip aš gyvas, – sako Viešpats DIEVAS, – jie neišgelbėtų nei sūnų, nei dukterų, bet tik jie vieni išsigelbėtų.'),
  (@b26, 14, 19, 'Arba jei pasiųsčiau marą į tą šalį ir ant jos išliečiau savo įtūžį krauju, kad iš jos iškirsčiau žmones ir gyvulius;'),
  (@b26, 14, 20, 'net jei Nojus, Danielius ir Jobas būtų joje, kaip aš gyvas, – sako Viešpats DIEVAS, – jie neišgelbėtų nei sūnaus, nei dukters; jie savo teisumu išgelbėtų tik savo pačių sielas.'),
  (@b26, 14, 21, 'Nes taip sako Viešpats DIEVAS: Juo labiau, kai pasiųsiu ant Jeruzalės savo keturis sunkius teismus: kalaviją, badą, piktus žvėris ir marą, kad iš jos iškirsčiau žmones ir gyvulius.'),
  (@b26, 14, 22, 'Tačiau štai joje bus paliktas likutis, kuris bus išvestas – sūnūs ir dukterys; štai jie išeis pas jus ir jūs matysite jų kelią bei jų darbus; ir būsite paguosti dėl nelaimės, kurią atvedžiau ant Jeruzalės, – dėl visko, ką ant jos atvedžiau.'),
  (@b26, 14, 23, 'Ir jie jus paguos, kai matysite jų kelius ir jų darbus; ir žinosite, kad aš ne be priežasties padariau viską, ką joje padariau’, – sako Viešpats DIEVAS“.'),
  (@b26, 15, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 15, 2, '„Žmogaus sūnau, kuo vynmedis pranašesnis už kitus medžius ar už šaką, esančią tarp miško medžių?'),
  (@b26, 15, 3, 'Ar imama iš jo medienos kokiam darbui daryti? Ar kas ims iš jo kuolelį, kad ant jo pakabintų kokį nors indą?'),
  (@b26, 15, 4, 'Štai jis įmestas į ugnį kurui; jo abu galus ryja ugnis, ir jo vidurys sudegęs. Ar jis tinka kokiam darbui?'),
  (@b26, 15, 5, 'Štai būdamas sveikas jis netiko darbui; tai dar labiau jis netinka jokiam darbui, kai ugnis jį surijusi, ir jis sudegęs.'),
  (@b26, 15, 6, 'Todėl taip sako Viešpats DIEVAS: ‘Kaip tarp miško medžių vynmedis, kurį atidaviau kaip kurą ugniai, taip aš atiduosiu Jeruzalės gyventojus.'),
  (@b26, 15, 7, 'Ir nukreipsiu prieš juos savo veidą; jie išeis iš vienos ugnies, ir juos surys kita ugnis; ir žinosite, kad aš esu VIEŠPATS, kai nukreipsiu prieš juos savo veidą.'),
  (@b26, 15, 8, 'Ir paversiu šalį apleista, kadangi jie padarė nusižengimą’, – sako Viešpats DIEVAS“.'),
  (@b26, 16, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 16, 2, '„Žmogaus sūnau, duok Jeruzalei žinoti jos bjaurystes'),
  (@b26, 16, 3, 'ir sakyk: ‘Taip sako Viešpats DIEVAS Jeruzalei: Tavo gimimas ir tavo kilmė iš Kanaano šalies; tavo tėvas buvo amoritas, o tavo motina – hetitė.'),
  (@b26, 16, 4, 'O dėl tavo gimimo, tą dieną, kai gimei, tavo bamba nebuvo nupjauta ir tu nebuvai nuplauta vandeniu, kad suminkštėtum; tu visai nebuvai nei ištrinta druska, nei suvystyta.'),
  (@b26, 16, 5, 'Jokia akis tavęs nepasigailėjo, kad tau padarytų bent vieną iš tų dalykų, kad tave užjaustų; bet tu buvai išmesta į atvirą lauką, kad bjaurėtųsi tavo asmenybe, tą dieną, kai gimei.'),
  (@b26, 16, 6, 'Ir aš, praeidamas pro tave, pamačiau tave susiteršusią savo pačios kraujyje, ir tariau tau, kai buvai savo kraujyje: „Gyvenk“; taip, aš tariau tau, kai buvai savo kraujyje: „Gyvenk“.'),
  (@b26, 16, 7, 'Aš tave dauginau kaip lauko pumpurus, ir tu padaugėjai, ir padidėjai, ir tapai puikus papuošalas; tavo krūtys susiformavo ir tavo plaukai užaugo, tačiau tu buvai nuoga ir plika.'),
  (@b26, 16, 8, 'Na, o aš pro tave praeidamas pažiūrėjau į tave, ir štai tavo metas buvo meilės metas; aš išskleidžiau virš tavęs savo skverną ir apdengiau tavo nuogumą; taip, aš tau prisiekiau ir įstojau į sandorą su tavimi, – sako Viešpats DIEVAS, – ir tu tapai mano.'),
  (@b26, 16, 9, 'Tada aš apiploviau tave vandeniu; taip, aš visiškai nuploviau nuo tavęs tavo kraują ir patepiau tave aliejumi.'),
  (@b26, 16, 10, 'Taip pat tave apvilkau siuvinėtu dirbiniu, apaviau barsukų oda, apjuosiau plonu linu ir apdengiau tave šilku.'),
  (@b26, 16, 11, 'Taip pat papuošiau tave papuošalais, ant tavo rankų uždėjau apyrankes ir grandinėlę tau ant kaklo.'),
  (@b26, 16, 12, 'Ir uždėjau tau ant kaktos brangenybes, auskarus tau į ausis ir gražų vainiką tau ant galvos.'),
  (@b26, 16, 13, 'Taip tu buvai papuošta auksu bei sidabru; ir tavo apdaras buvo iš plono lino, šilko ir siuvinėto dirbinio; tu valgei smulkius miltus, medų ir aliejų; ir buvai be galo graži, ir suklestėjai ligi karalystės.'),
  (@b26, 16, 14, 'Ir tavo garbė pasklido tarp pagonių dėl tavo grožio; nes jis buvo tobulas per mano gražumą, kurį buvau uždėjęs ant tavęs, – sako Viešpats DIEVAS.'),
  (@b26, 16, 15, 'Bet tu pasitikėjai savo grožiu ir dėl savo garbės užsiiminėjai paleistuvavimu, ir išliejai savo paleistuvystes ant kiekvieno praeinančio; tai buvo jo.'),
  (@b26, 16, 16, 'Tu paėmei savo drabužių ir įvairiomis spalvomis papuošei savo aukštumas ir ant jų paleistuvavai; tokių dalykų neatsitiks ir taip nebus.'),
  (@b26, 16, 17, 'Taip pat tu ėmei savo gražias brangenybes iš mano aukso ir iš mano sidabro, kurias buvau tau davęs, ir pasidarei sau vyrų atvaizdų, ir paleistuvavai su jais,'),
  (@b26, 16, 18, 'ir ėmei savo išsiuvinėtus drabužius ir apdengei juos; ir padėjai prieš juos mano aliejų ir mano smilkalus.'),
  (@b26, 16, 19, 'Taip pat mano maistą, kurį tau daviau: smulkius miltus, aliejų ir medų, kuriais tave maitinau, – tu padėjai prieš juos kaip gardų kvapą; ir taip buvo, – sako Viešpats DIEVAS.'),
  (@b26, 16, 20, 'Tu dar ėmei savo sūnus ir savo dukteris, kuriuos buvai man pagimdžiusi, ir juos aukojai jiems surijimui. Ar tau maža buvo paleistuvysčių,'),
  (@b26, 16, 21, 'kad mano vaikus žudei ir juos atidavei darydamas, kad jie pereitų aniems per ugnį?'),
  (@b26, 16, 22, 'Ir visose savo bjaurystėse ir savo paleistuvavimuose tu neatsiminei savo jaunystės dienų, kai buvai nuoga ir plika, ir buvai susiteršusi savo kraujyje.'),
  (@b26, 16, 23, 'Ir po visų tavo nedorybių (vargas, vargas tau! – sako Viešpats DIEVAS)'),
  (@b26, 16, 24, 'įvyko, kad tu pasistatei sau iškilią vietą ir pasidarei aukštumų kiekvienoje gatvėje.'),
  (@b26, 16, 25, 'Kiekvienoje kelio pradžioje tu pastatei savo aukštumas ir padarei, kad tavo grožiu bjaurėtųsi, ir praskėtei savo kojas kiekvienam praeiviui, ir dauginai savo paleistuvavimus.'),
  (@b26, 16, 26, 'Tu paleistuvavai su savo kaimynais egiptiečiais, esančiais didelio kūno; ir padauginai savo paleistuvavimus, idant kurstytum mano pyktį.'),
  (@b26, 16, 27, 'Štai todėl aš ištiesiau savo ranką virš tavęs, sumažinau nuolatinį tavo maistą ir atidaviau tave valiai tų, kurios tavęs nekenčia, filistinų dukterims, kurios gėdijosi tavo gašlaus kelio.'),
  (@b26, 16, 28, 'Tu paleistuvavai ir su asirais, nes buvai nepasotinama; taip, tu paleistuvavai su jais, tačiau negalėjai pasitenkinti.'),
  (@b26, 16, 29, 'Tu dar dauginai savo paleistuvystę Kanaano šalyje iki Kaldėjos; tačiau ir tuo nepasitenkinai.'),
  (@b26, 16, 30, 'Kokia silpna tavo širdis, – sako Viešpats DIEVAS, – kad tu darai visa tai, ką daro valdinga paleistuvaujanti moteris;'),
  (@b26, 16, 31, 'kad pasistatai savo iškilią vietą kiekvieno kelio pradžioje ir padarai savo aukštumas kiekvienoje gatvėje; ir nebuvai kaip paleistuvė, nes paniekinai užmokestį;'),
  (@b26, 16, 32, 'bet kaip svetimaujanti žmona, kuri savo vyro vieton priima svetimus!'),
  (@b26, 16, 33, 'Jie duoda dovanas visoms paleistuvėms; bet tu duodi savo dovanas visiems savo meilužiams ir juos samdai, kad jie iš visų pusių ateitų prie tavo paleistuvavimo.'),
  (@b26, 16, 34, 'Ir savo paleistuvavimuose tu esi priešingybė kitoms moterims tuo, kad niekas neseka tau iš paskos paleistuvauti; ir tuo, kad tu duodi užmokestį, o tau nėra duodamas užmokestis, esi skirtinga.'),
  (@b26, 16, 35, 'Todėl, o paleistuve, klausyk VIEŠPATIES žodžio:'),
  (@b26, 16, 36, 'Taip sako Viešpats DIEVAS: Kadangi išsiliejo tavo nešvarumas, ir tavo nuogumas atsidengė per tavo paleistuvavimus su tavo meilužiais ir su visais tavo bjaurysčių stabais, ir per tavo vaikų kraują, kurį jiems davei;'),
  (@b26, 16, 37, 'todėl štai aš surinksiu visus tavo meilužius, su kuriais turėjai malonumą, ir visus, kuriuos mylėjai, drauge su visais, kurių nekentei; aš juos surinksiu prieš tave aplinkui ir jiems atidengsiu tavo nuogumą, kad jie pamatytų visą tavo nuogumą.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b26, 16, 38, 'Ir aš tave teisiu, kaip teisiamos laužančios santuoką ir kraują praliejančios moterys; ir įtūžiu bei pavydu tau duosiu kraujo.'),
  (@b26, 16, 39, 'Taip pat atiduosiu tave į jų rankas, ir jie nuvers tavo iškilią vietą, nugriaus tavo aukštumas; jie nutrauks nuo tavęs tavo drabužius, atims tavo gražias brangenybes ir paliks tave pliką ir nuogą.'),
  (@b26, 16, 40, 'Ir jie atves aukštyn prieš tave būrį, ir jie užmėtys tave akmenimis ir perdurs tave savo kalavijais.'),
  (@b26, 16, 41, 'Ir jie sudegins tavo namus ugnimi ir įvykdys tau teismus daugelio moterų akyse; ir padarysiu, kad tu liausies paleistuvavusi, ir taip pat tu nebeduosi užmokesčio.'),
  (@b26, 16, 42, 'Taip aš padarysiu, kad ilsėtųsi mano įtūžis, skirtas tau, ir mano pavydas pasitrauks nuo tavęs, aš būsiu ramus ir nebepyksiu.'),
  (@b26, 16, 43, 'Kadangi tu neatsiminei savo jaunystės dienų, bet visu tuo mane erzinai; todėl štai aš atmokėsiu tavo keliu tau ant galvos, – sako Viešpats DIEVAS; – ir tu nedarysi šito gašlavimo daugiau už visas savo bjaurystes.'),
  (@b26, 16, 44, 'Štai kiekvienas, vartojantis patarles, vartos šią patarlę prieš tave, sakydamas: „Kokia motina, tokia ir jos duktė“.'),
  (@b26, 16, 45, 'Tu esi savo motinos duktė, kuri bjaurisi savo vyru ir savo vaikais; ir tu esi sesuo savo seserų, kurios bjaurisi savo vyrais ir savo vaikais; jūsų motina buvo hetitė, o jūsų tėvas amoritas.'),
  (@b26, 16, 46, 'Ir tavo vyresnioji sesuo yra Samarija, ji ir jos dukterys, gyvenančios tavo kairėje; ir tavo jaunesnioji sesuo, gyvenanti tavo dešinėje, yra Sodoma su savo dukterimis.'),
  (@b26, 16, 47, 'Nors tu nevaikščiojai jų keliais ir nesielgei pagal jų bjaurystes; bet tarsi to buvo per maža, tu sugedai visuose savo keliuose labiau negu jos.'),
  (@b26, 16, 48, 'Kaip aš gyvas, – sako Viešpats DIEVAS, – tavo sesuo Sodoma, nei ji, nei jos dukterys nedarė, kaip darei tu ir tavo dukterys.'),
  (@b26, 16, 49, 'Štai tai buvo tavo sesers Sodomos neteisybė; joje ir jos dukteryse buvo išdidumas, duonos sotumas ir gausus dykinėjimas, ir rankos vargšui ir beturčiui ji nesustiprino.'),
  (@b26, 16, 50, 'Ir mano akivaizdoje jos buvo išpuikusios ir darė bjaurystes; todėl aš jas pašalinau, kai pamačiau, kad gerai.'),
  (@b26, 16, 51, 'Samarija nepadarė nei pusės tavo nuodėmių; bet tu padauginai savo bjaurystes labiau negu jos, ir visomis savo bjaurystėmis, kurias darei, tu išteisinai savo seseris.'),
  (@b26, 16, 52, 'Tu irgi, kuri teisei savo seseris, nešiok savo gėdą dėl savo nuodėmių, kurias darei bjauresnes už jų; jos yra teisesnės už tave; taip, būk sugėdinta ir nešiok savo gėdą, nes tu išteisinai savo seseris.'),
  (@b26, 16, 53, 'Kai aš sugrąžinsiu jų nelaisvę, Sodomos bei jos dukterų nelaisvę ir Samarijos bei jos dukterų nelaisvę, tada aš sugrąžinsiu nelaisvę tavo belaisvių jų tarpe;'),
  (@b26, 16, 54, 'kad neštum savo gėdą ir būtum sugėdinta visu tuo, ką esi padariusi, būdama joms paguoda.'),
  (@b26, 16, 55, 'Kai tavo seserys, Sodoma ir jos dukterys, sugrįš į savo ankstesnę būklę ir Samarija bei jos dukterys sugrįš į savo ankstesnę būklę, tada tu ir tavo dukterys sugrįšite į savo ankstesnę būklę.'),
  (@b26, 16, 56, 'Nes tavo sesuo Sodoma tavąja burna nebuvo minima tavo išdidumo dieną,'),
  (@b26, 16, 57, 'kai dar nebuvo atidengta tavo nedorybė, kaip tavo priekaišto metu nuo Sirijos dukterų ir visų jos aplinkinių, filistinų dukterų, kurios tave niekina aplinkui.'),
  (@b26, 16, 58, 'Tu nešei savo gašlumą ir savo bjaurystes’, – sako VIEŠPATS.'),
  (@b26, 16, 59, 'Nes taip sako Viešpats DIEVAS: ‘Aš pasielgsiu su tavimi, kaip pasielgei tu, kuri paniekinai priesaiką, sulaužydama sandorą.'),
  (@b26, 16, 60, 'Tačiau aš atsiminsiu savo sandorą su tavimi tavo jaunystės dienomis ir įtvirtinsiu tau amžiną sandorą.'),
  (@b26, 16, 61, 'Tada tu atsiminsi savo kelius ir būsi sugėdinta, kai priimsi savo seseris, savo vyresniąją ir savo jaunesniąją; ir jas atiduosiu tau į dukteris, bet ne per tavo sandorą.'),
  (@b26, 16, 62, 'Aš įtvirtinsiu savo sandorą su tavimi; ir tu žinosi, kad aš esu VIEŠPATS;'),
  (@b26, 16, 63, 'kad atsimintum ir susigėstum, ir niekada nebeatvertum savo burnos dėl savo gėdos, kai tave sutaikinsiu su savimi dėl visko, ką esi padariusi’, – sako Viešpats DIEVAS“.'),
  (@b26, 17, 1, 'Man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 17, 2, '„Žmogaus sūnau, užmink mįslę ir sakyk palyginimą Izraelio namams;'),
  (@b26, 17, 3, 'ir tark: ‘Taip sako Viešpats DIEVAS: Didelis erelis dideliais sparnais, ilgasparnis, pilnas įvairiaspalvių plunksnų, atskrido į Libaną ir paėmė aukščiausią kedro šaką;'),
  (@b26, 17, 4, 'jis nuskynė iš jo jaunų šakelių viršutinę ir nunešė ją į prekybos šalį; padėjo ją pirklių mieste.'),
  (@b26, 17, 5, 'Jis paėmė ir šalies sėklos ir pasodino ją derlingame lauke; padėjo ją prie didelių vandenų, kaip gluosnį ją pasodino.'),
  (@b26, 17, 6, 'Ji augo ir tapo žemaūgiu išsikerojusiu vynmedžiu, kurio šakos palinko į jį ir jo šaknys buvo po juo; taip jis tapo vynmedžiu, išleido šakas, išleido atžalas.'),
  (@b26, 17, 7, 'Buvo ir kitas didelis erelis su dideliais sparnais ir daug plunksnų; ir štai tas vynmedis palenkė į jį savo šaknis ir išleido link jo savo šakas, kad šis jį laistytų jo sodinių vagomis.'),
  (@b26, 17, 8, 'Jis buvo pasodintas į gerą dirvožemį prie didelių vandenų, kad išleistų šakas ir neštų vaisių, kad būtų puikus vynmedis’.'),
  (@b26, 17, 9, 'Sakyk: ‘Taip sako Viešpats DIEVAS: Ar jis vešės? Argi jis neišraus jo šaknų ir neiškirs jo vaisių, kad jis nuvystų? Jis nuvys visais savo išdygusiais lapais be didelės jėgos ar daugelio žmonių, kad išrautų jį su jo šaknimis.'),
  (@b26, 17, 10, 'Štai būdamas pasodintas – ar jis vešės? Ar jis visiškai nenudžius, kai jį palies rytų vėjas? Jis sudžius vagose, kur augo’“.'),
  (@b26, 17, 11, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 17, 12, '„Na, sakyk maištaujantiems namams: ‘Ar nežinote, ką tai reiškia?’ Sakyk jiems: ‘Štai Babilono karalius atvyko į Jeruzalę, paėmė jos karalių bei jos kunigaikščius ir nusivedė juos su savimi į Babiloną;'),
  (@b26, 17, 13, 'ir paėmė vieną iš karaliaus sėklos, sudarė su juo sandorą ir prisaikdino jį; jis paėmė ir šalies galiūnus;'),
  (@b26, 17, 14, 'kad karalystė būtų nužeminta, jog ji nepasikeltų, bet kad laikydamasi jo sandoros ji išstovėtų.'),
  (@b26, 17, 15, 'Bet jis maištavo prieš jį, siųsdamas savo pasiuntinius į Egiptą, kad jam duotų žirgų ir daug žmonių. Ar jam seksis? Ar išsigelbės tas, kuris tai daro? Ar jis sulaužys sandorą ir bus išvaduotas?'),
  (@b26, 17, 16, 'Kaip aš gyvas, – sako Viešpats DIEVAS, – gyvenamoje vietoje karaliaus, kuris jį padarė karaliumi, kurio priesaiką jis paniekino ir kurio sandorą jis sulaužė, jis tikrai mirs pas jį Babilono viduje.'),
  (@b26, 17, 17, 'Nei faraonas su galinga kariuomene ir dideliu pulku nieko kare dėl jo nepadarys, pildamas kalnus ir statydamas fortus, kad iškirstų daugelį žmonių;'),
  (@b26, 17, 18, 'nes jis paniekino priesaiką, sulaužydamas sandorą, kai štai jis buvo padavęs savo ranką ir visa tai padaręs; jis neišsigelbės’.'),
  (@b26, 17, 19, 'Todėl taip sako Viešpats DIEVAS: ‘Kaip aš gyvas, mano priesaiką, kurią jis paniekino, ir mano sandorą, kurią jis sulaužė, aš tikrai atlyginsiu jam ant galvos.'),
  (@b26, 17, 20, 'Aš ant jo išskleisiu savo tinklą, ir jis bus sugautas mano spąstuose, ir jį nuvesiu į Babiloną, ir ten su juo bylinėsiuosi dėl jo nusižengimo, kuriuo jis nusižengė prieš mane.'),
  (@b26, 17, 21, 'Ir visi jo pabėgėliai su visais jo būriais kris nuo kalavijo, o išlikusieji bus išsklaidyti po visus vėjus; ir jūs žinosite, kad aš, VIEŠPATS, tai kalbėjau’.'),
  (@b26, 17, 22, 'Taip sako Viešpats DIEVAS: ‘Taip pat paimsiu iš aukšto kedro aukščiausios šakos ir pasodinsiu tai; aš nuo jo jaunų šakelių viršaus nuskinsiu minkštą vytelę ir pasodinsiu ją ant aukšto ir iškilaus kalno;'),
  (@b26, 17, 23, 'Izraelio aukštumos kalne ją pasodinsiu; ir ji išleis šakas, duos vaisių ir bus puikus kedras; ir po juo gyvens visokie įvairiasparniai skrajūnai; jie gyvens jo šakų šešėlyje.'),
  (@b26, 17, 24, 'Ir visi lauko medžiai žinos, kad aš, VIEŠPATS, nužeminau aukštą medį, išaukštinau žemą medį, sudžiovinau žaliuojantį medį ir padariau, kad sausas medis vešėtų; Aš, VIEŠPATS, tai kalbėjau ir tai padariau’“.'),
  (@b26, 18, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 18, 2, '„Ką jūs turite mintyje, kai vartojate šitą patarlę apie Izraelio šalį, sakydami: ‘Tėvai valgė rūgščių vynuogių, o vaikams atšipo dantys’?'),
  (@b26, 18, 3, 'Kaip aš gyvas, – sako Viešpats DIEVAS, – jūs nebeturėsite progos vartoti šitą patarlę Izraelyje.'),
  (@b26, 18, 4, 'Štai visos sielos yra mano; kaip tėvo siela, taip ir sūnaus siela yra mano; siela, kuri nusideda, mirs.'),
  (@b26, 18, 5, 'Bet jei žmogus yra teisus ir daro, kas teisėta ir teisinga,'),
  (@b26, 18, 6, 'nėra valgęs kalnuose, nėra pakėlęs akių į Izraelio namų stabus, nesuteršė savo artimo žmonos, nebuvo prisiartinęs prie mėnesinėmis sergančios moters,'),
  (@b26, 18, 7, 'nėra nei vieno engęs, bet sugrąžino skolininkui jo užstatą, nei vieno smurtu neapiplėšė, davė savo duonos alkanam, apdengė nuogą drabužiu,'),
  (@b26, 18, 8, 'neskolino už palūkanas ir neėmė prieaugio, atitraukė savo ranką nuo neteisybės, vykdė teisingą teismą tarp žmogaus ir žmogaus,'),
  (@b26, 18, 9, 'vaikščiojo pagal mano įstatus ir laikėsi mano teismų, kad elgtųsi teisingai, – tas yra teisus; jis tikrai gyvens, – sako Viešpats DIEVAS.'),
  (@b26, 18, 10, 'Jeigu jis pagimdytų sūnų, kuris yra plėšikas, praliejantis kraują ir darantis ką panašaus į bet kurį iš šitų dalykų,'),
  (@b26, 18, 11, 'o nedarantis nieko iš anų darbų, bet yra valgęs kalnuose, suteršė savo artimo žmoną,'),
  (@b26, 18, 12, 'engė vargšą ir beturtį, smurtu plėšė, negrąžino užstato, kėlė akis į stabus, darė bjaurystes,'),
  (@b26, 18, 13, 'skolino už palūkanas ir ėmė prieaugį, – ar jis liks gyvas? Jis negyvens; jis darė visas šitas bjaurystes; jis tikrai mirs; jo kraujas bus ant jo.'),
  (@b26, 18, 14, 'Na, o štai jei jis pagimdys sūnų, kuris matys visas savo tėvo nuodėmes, kurias jis darė, ir apsvarstys, ir nieko tokio nedarys,'),
  (@b26, 18, 15, 'nevalgys kalnuose ir nepakels akių į Izraelio namų stabus, nesuterš savo artimo žmonos'),
  (@b26, 18, 16, 'ir nei vieno neengs, nesulaikys užstato ir smurtu neplėš, bet duos savo duonos alkanam ir apdengs nuogą drabužiu,'),
  (@b26, 18, 17, 'atitrauks savo ranką nuo vargšo, neims palūkanų nei prieaugio, vykdys mano teismus, vaikščios pagal mano įstatus, – tas nemirs dėl savo tėvo neteisybės, jis tikrai gyvens.'),
  (@b26, 18, 18, 'O jo tėvas, kadangi žiauriai engė, smurtu apiplėšė savo brolį ir darė tai, kas negerai savo tautos tarpe, štai jis mirs savo neteisybėje.'),
  (@b26, 18, 19, 'Tačiau jūs sakote: „Kodėl? Argi ne sūnus nešioja tėvo neteisybę?“ Kadangi sūnus darė tai, kas teisėta ir teisinga, laikėsi visų mano įstatų ir juos vykdė, jis tikrai gyvens.'),
  (@b26, 18, 20, 'Siela, kuri nusideda, ji mirs. Sūnus nenešios tėvo neteisybės, nei tėvas neneš sūnaus neteisybės; teisiojo teisumas bus ant jo paties, o nedorėlio nedorybė bus ant jo paties.'),
  (@b26, 18, 21, 'Bet jei nedorėlis nusigręš nuo visų savo nuodėmių, kurias jis darė, laikysis visų mano įstatų ir darys tai, kas teisėta ir teisinga, jis tikrai gyvens, jis nemirs.'),
  (@b26, 18, 22, 'Visi jo nusižengimai, kuriuos jis darė, – apie juos nebus jam užsiminta; jis gyvens savo teisumu, kurį jis darė.'),
  (@b26, 18, 23, 'Argi aš noriu, kad nedorėlis mirtų? – sako Viešpats DIEVAS, – argi ne to, kad jis gręžtųsi nuo savo kelių ir gyventų?'),
  (@b26, 18, 24, 'Bet kai teisusis nusigręžia nuo savo teisumo ir daro neteisybę, ir daro pagal visas bjaurystes, kurias daro nedorėlis, argi jis gyvens? Visas jo teisumas, kurį jis darė, nebus minimas; visame savo nusižengime, kuriuo jis nusižengė, ir savo nuodėmėje, kuria jis nusidėjo, juose jis mirs.'),
  (@b26, 18, 25, 'Tačiau jūs sakote: „Viešpaties kelias neteisingas“. Nagi klausykite, o Izraelio namai: Argi mano kelias neteisingas? Argi ne jūsų keliai neteisingi?'),
  (@b26, 18, 26, 'Kai teisusis nusigręžia nuo savo teisumo, daro neteisybę ir juose miršta; jis mirs dėl savo neteisybės, kurią jis darė.'),
  (@b26, 18, 27, 'Vėlgi, kai nedorėlis nusigręžia nuo savo nedorybės, kurią jis darė, ir daro tai, kas teisėta ir teisinga, jis išsaugos savo sielą gyvą.'),
  (@b26, 18, 28, 'Kadangi jis apsvarstė ir nusigręžė nuo visų savo nusižengimų, kuriuos darė, jis tikrai gyvens, jis nemirs.'),
  (@b26, 18, 29, 'Tačiau Izraelio namai sako: „Viešpaties kelias neteisingas“. O Izraelio namai, argi mano keliai neteisingi? Argi ne jūsų keliai yra neteisingi?'),
  (@b26, 18, 30, 'Todėl aš jus teisiu, o Izraelio namai, kiekvieną pagal jo kelius, – sako Viešpats DIEVAS. – Atgailaukite ir nusigręžkite nuo visų savo nusižengimų – taip neteisybė netaps jūsų pražūtimi.'),
  (@b26, 18, 31, 'Meskite nuo savęs visus savo nusižengimus, kuriais nusižengėte; ir pasidarykite naują širdį ir naują dvasią; nes kodėl turėtumėte mirti, o Izraelio namai?'),
  (@b26, 18, 32, 'Nes aš nenoriu mirštančiojo mirties, – sako Viešpats DIEVAS; – todėl gręžkitės ir gyvenkite’“.'),
  (@b26, 19, 1, '„Be to, imkis raudos dėl Izraelio kunigaikščių'),
  (@b26, 19, 2, 'ir sakyk: ‘Kas yra tavo motina? Liūtė; ji guli tarp liūtų, ji maitino savo jauniklius tarp jaunų liūtų.'),
  (@b26, 19, 3, 'Ir ji išaugino vieną iš savo jauniklių; jis tapo jaunu liūtu ir išmoko sugauti grobį; jis rijo žmones.'),
  (@b26, 19, 4, 'Tautos irgi išgirdo apie jį; jis buvo sugautas jų duobėje, ir jos grandinėse nuvedė jį į Egipto šalį.'),
  (@b26, 19, 5, 'Na, o matydama, kad ji laukė, ir jos viltis prarasta, ji paėmė kitą iš savo jauniklių ir padarė jį jaunu liūtu.'),
  (@b26, 19, 6, 'Jis vaikštinėjo tarp liūtų, jis tapo jaunu liūtu, išmoko sugauti grobį ir rijo žmones.'),
  (@b26, 19, 7, 'Jis pažino jų apleistus rūmus ir niokojo jų miestus; ir ištuštėjo šalis bei jos pilnatvė dėl jo riaumojimo garso.'),
  (@b26, 19, 8, 'Tada tautos nusistatė prieš jį iš aplinkinių provincijų ir išskleidė virš jo savo tinklą; jis buvo sugautas jų duobėje.'),
  (@b26, 19, 9, 'Jos uždarė jį saugoti grandinėse ir nuvedė jį pas Babilono karalių; jos nuvedė jį į kalėjimą, kad jo balsas nebebūtų girdimas Izraelio kalnuose.'),
  (@b26, 19, 10, 'Tavo motina yra kaip vynmedis tavo kraujyje, pasodintas prie vandenų; jis buvo vaisingas ir pilnas šakų dėl vandenų daugybės.'),
  (@b26, 19, 11, 'Jis turėjo stiprias rykštes skeptrams tų, kurie valdo, jo ūgis iškilo tarp tankių šakų, ir jis pasirodė savo aukštybėje su savo šakų daugybe.'),
  (@b26, 19, 12, 'Bet įtūžyje jis buvo išrautas, numestas žemėn, ir rytų vėjas sudžiovino jo vaisius; jo stiprios rykštės buvo nulaužtos ir sudžiūvo; ugnis jas surijo.'),
  (@b26, 19, 13, 'O dabar jis pasodintas dykumoje, sausoje ir ištroškusioje dirvoje.'),
  (@b26, 19, 14, 'Ir ugnis išėjo iš jo šakos rykščių, kuri surijo jo vaisius taip, kad ji nebeturi tvirtos rykštės būti skeptru valdymui‘“. Tai yra rauda ir bus raudai.'),
  (@b26, 20, 1, 'Ir septintaisiais metais, penktąjį mėnesį, to mėnesio dešimtąją dieną įvyko, kad kai kurie iš Izraelio vyresniųjų atėjo pasiklausti VIEŠPATIES ir atsisėdo priešais mane.'),
  (@b26, 20, 2, 'Tada man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 20, 3, '„Žmogaus sūnau, kalbėk Izraelio vyresniesiems ir sakyk jiems: ‘Taip sako Viešpats DIEVAS: Ar jūs atėjote manęs pasiklausti? Kaip aš gyvas, aš nesiduosiu jūsų klausiamas, – sako Viešpats DIEVAS.'),
  (@b26, 20, 4, '– Ar tu juos teisi, žmogaus sūnau, ar tu teisi? Duok jiems žinoti jų tėvų bjaurystes'),
  (@b26, 20, 5, 'ir sakyk jiems: Taip sako Viešpats DIEVAS: Tą dieną, kai išrinkau Izraelį ir pakėliau savo ranką Jokūbo namų sėklai ir jiems tapau žinomas Egipto šalyje, kai pakėliau jiems savo ranką, sakydamas: „Aš esu VIEŠPATS, jūsų Dievas“;'),
  (@b26, 20, 6, 'tą dieną, kai jiems pakėliau savo ranką, kad išvesčiau juos iš Egipto šalies į šalį, kurią buvau jiems ištyręs, tekančią pienu ir medumi, kuri yra visų šalių šlovė;'),
  (@b26, 20, 7, 'tada jiems pasakiau: „Meskite šalin kiekvienas savo akių bjaurystes ir nesusiterškite Egipto stabais; aš esu VIEŠPATS, jūsų Dievas“.'),
  (@b26, 20, 8, 'Bet jie maištavo prieš mane ir nenorėjo manęs klausyti; nei vienas nemetė šalin savo akių bjaurysčių ir jie nepaliko Egipto stabų; tada tariau: „Aš išliesiu ant jų savo įtūžį, kad ant jų įvykdyčiau savo pyktį Egipto šalies viduje“.'),
  (@b26, 20, 9, 'Bet aš dariau dėl savo vardo, kad jis nebūtų suterštas prieš pagonis, tarp kurių jie buvo, kurių akyse jiems tapau žinomas, išvesdamas juos iš Egipto šalies.'),
  (@b26, 20, 10, 'Tad išvedžiau juos iš Egipto šalies ir atvedžiau į dykumą.'),
  (@b26, 20, 11, 'Ir daviau jiems savo įstatus ir paskelbiau jiems savo teismus, kuriais žmogus gyvens, jei juos vykdys.'),
  (@b26, 20, 12, 'Taipogi jiems dar daviau savo sabatus, kad būtų ženklas tarp manęs ir jų, kad jie žinotų, jog aš esu VIEŠPATS, kuris juos pašvenčia.'),
  (@b26, 20, 13, 'Bet Izraelio namai maištavo prieš mane dykumoje; jie nevaikščiojo pagal mano įstatus ir atmetė mano teismus, kuriais žmogus gyvens, jei juos vykdys; ir jie labai suteršė mano sabatus; tada tariau: „Aš išliesiu ant jų savo įtūžį dykumoje, kad juos sunaikinčiau“.'),
  (@b26, 20, 14, 'Bet aš dariau dėl savo vardo, kad jis nebūtų suterštas prieš pagonis, kurių akyse juos išvedžiau.'),
  (@b26, 20, 15, 'Taipogi aš dar jiems pakėliau savo ranką dykumoje, kad jų neįvesiu į pienu ir medumi tekančią šalį, kurią buvau jiems davęs, kuri yra visų šalių šlovė;'),
  (@b26, 20, 16, 'kadangi jie niekino mano teismus ir nevaikščiojo pagal mano įstatus, bet suteršė mano sabatus; nes jų širdis nuėjo paskui jų stabus.'),
  (@b26, 20, 17, 'Tačiau mano akiai pagailo jų, kad jų nesunaikinčiau, ir nepadariau jiems galo dykumoje.'),
  (@b26, 20, 18, 'Bet aš pasakiau jų vaikams dykumoje: „Nevaikščiokite pagal savo tėvų įstatus ir nesilaikykite jų teismų, ir nesusiterškite jų stabais;'),
  (@b26, 20, 19, 'aš esu VIEŠPATS, jūsų Dievas; vaikščiokite pagal mano įstatus, laikykitės mano teismų ir juos vykdykite;'),
  (@b26, 20, 20, 'ir pašvęskite mano sabatus; jie bus ženklas tarp manęs ir jūsų, kad žinotumėte, jog aš esu VIEŠPATS, jūsų Dievas“.'),
  (@b26, 20, 21, 'Tačiau vaikai maištavo prieš mane; jie nevaikščiojo pagal mano įstatus ir nesilaikė mano teismų, kad juos vykdytų, kuriais žmogus gyvens, jei juos vykdys; jie suteršė mano sabatus; tada tariau: „Aš norėčiau ant jų išlieti savo įtūžį, kad prieš juos įvykdyčiau savo pyktį dykumoje“.'),
  (@b26, 20, 22, 'Tačiau aš atitraukiau savo ranką ir dariau dėl savo vardo, kad jis nebūtų suterštas akyse pagonių, kuriems matant juos išvedžiau.'),
  (@b26, 20, 23, 'Aš taip pat jiems pakėliau savo ranką dykumoje, kad juos išsklaidyčiau tarp pagonių ir išvaikyčiau po šalis;'),
  (@b26, 20, 24, 'kadangi jie nevykdė mano teismų, bet niekino mano įstatus, suteršė mano sabatus, ir jų akys sekė jų tėvų stabus.'),
  (@b26, 20, 25, 'Todėl jiems daviau negerų įstatų ir teismų, kuriais jie neturėtų gyventi;'),
  (@b26, 20, 26, 'ir juos suteršiau jų pačių dovanomis, jiems perleidžiant per ugnį visus atveriančius įsčias, kad juos padaryčiau apleistus, tuo tikslu, kad jie žinotų, jog aš esu VIEŠPATS.'),
  (@b26, 20, 27, 'Todėl, žmogaus sūnau, kalbėk Izraelio namams ir jiems sakyk: ‘Taip sako Viešpats DIEVAS: Dar tuo jūsų tėvai man piktžodžiavo nusižengdami prieš mane.'),
  (@b26, 20, 28, 'Nes kai juos atvedžiau į šalį, dėl kurios pakėliau savo ranką, kad jiems ją duočiau, tada jie pamatė visas aukštas kalvas ir visus tankius medžius ir ten atnašavo savo aukas, ir ten jie savo atnaša kurstė; ten jie skleidė ir savo gardų kvapą ir išliejo savo geriamąsias atnašas.'),
  (@b26, 20, 29, 'Tada jiems sakiau: „Kas yra ta aukštuma, į kurią einate?“ Iki šios dienos ją vadina Bamos vardu.'),
  (@b26, 20, 30, 'Todėl sakyk Izraelio namams: Taip sako Viešpats DIEVAS: Ar jūs susiteršėte savo tėvų būdu ir paleistuvaujate pagal jų bjaurystes?'),
  (@b26, 20, 31, 'Nes atnašaudami savo dovanas, perleisdami savo sūnus per ugnį, jūs iki šios dienos susiteršiate visais savo stabais; ar aš turėčiau duotis jūsų klausiamas, o Izraelio namai? Kaip aš gyvas, – sako Viešpats DIEVAS, – aš nesiduosiu jūsų klausiamas.'),
  (@b26, 20, 32, 'Ir tai, kas ateina jums į galvą, to visiškai nebus, kai jūs sakote: „Mes būsime kaip pagonys, kaip šalių šeimos, kad tarnautume medžiui ir akmeniui“.'),
  (@b26, 20, 33, 'Kaip aš gyvas, – sako Viešpats DIEVAS, – tikrai jus valdysiu galinga ranka ir ištiesta ranka bei išlietu įtūžiu;'),
  (@b26, 20, 34, 'ir išvesiu jus iš tautų ir surinksiu iš šalių, po kurias esate išsklaidyti, galinga ranka ir ištiesta ranka bei išlietu įtūžiu.'),
  (@b26, 20, 35, 'Ir jus atvesiu į tautų dykumą ir ten su jumis bylinėsiuosi akis į akį.'),
  (@b26, 20, 36, 'Kaip bylinėjausi su jūsų tėvais Egipto šalies dykumoje, taip bylinėsiuosi su jumis, – sako Viešpats DIEVAS.'),
  (@b26, 20, 37, '– Aš jus pervesiu po lazda, ir įvesiu jus į sandoros saitus;'),
  (@b26, 20, 38, 'ir išvalysiu iš jūsų tarpo maištininkus ir nusižengiančius prieš mane; juos išvesiu iš krašto, kur jie laikinai apsigyvenę, bet jie neįeis į Izraelio šalį; ir jūs žinosite, kad aš esu VIEŠPATS.'),
  (@b26, 20, 39, 'O dėl jūsų, o Izraelio namai, – taip sako Viešpats DIEVAS, – eikite, tarnaukite kiekvienas savo stabams, ir taip pat po to, jei manęs neklausysite; bet nebeterškite mano šventojo vardo savo dovanomis ir savo stabais.'),
  (@b26, 20, 40, 'Nes mano šventame kalne, Izraelio aukštybės kalne, – sako Viešpats DIEVAS, – ten man tarnaus visi Izraelio namai, jie visi šalyje; ten aš juos priimsiu ir ten reikalausiu jūsų atnašų ir jūsų atnašų pirmavaisių su visais jūsų šventais dalykais.'),
  (@b26, 20, 41, 'Aš jus priimsiu kartu su jūsų gardžiu kvapu, kai jus išvesiu iš tautų ir surinksiu jus iš šalių, po kurias buvote išsklaidyti; ir būsiu pašvęstas jumyse pagonių akivaizdoje.'),
  (@b26, 20, 42, 'Ir žinosite, kad aš esu VIEŠPATS, kai jus atvesiu į Izraelio šalį, į kraštą, dėl kurio pakėliau savo ranką, kad jį duočiau jūsų tėvams.'),
  (@b26, 20, 43, 'Ir ten jūs prisiminsite savo kelius ir visus savo darbus, kuriais buvote susiteršę; ir jūs pasibjaurėsite savimi savo pačių akyse dėl visų savo piktų darbų, kuriuos darėte.'),
  (@b26, 20, 44, 'Ir žinosite, kad aš esu VIEŠPATS, kai būsiu padaręs su jumis dėl savo vardo, ne pagal jūsų nedorus kelius ir jūsų sugedusius darbus, o Izraelio namai, – sako Viešpats DIEVAS’“.'),
  (@b26, 20, 45, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 20, 46, '„Žmogaus sūnau, nukreipk savo veidą pietų link, lašink savo žodį pietų link ir pranašauk prieš pietų lauko mišką;'),
  (@b26, 20, 47, 'ir sakyk pietų miškui: ‘Klausyk VIEŠPATIES žodžio: Taip sako Viešpats DIEVAS: Štai aš užkursiu tavyje ugnį, ir ji surys tavyje kiekvieną žaliuojantį medį ir kiekvieną sausą medį; liepsnojanti liepsna neužges, ir visi veidai nuo pietų iki šiaurės bus joje sudeginti.'),
  (@b26, 20, 48, 'Ir visi kūnai pamatys, kad aš, VIEŠPATS, ją užkūriau; ji neužges’“.'),
  (@b26, 20, 49, 'Tada aš tariau: „Ak, Viešpatie DIEVE! Jie sako apie mane: ‘Argi jis nekalba palyginimais‘?“'),
  (@b26, 21, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 21, 2, '„Žmogaus sūnau, nukreipk savo veidą į Jeruzalę ir lašink savo žodį link šventovių, ir pranašauk prieš Izraelio šalį,'),
  (@b26, 21, 3, 'ir sakyk Izraelio šaliai: ‘Taip sako VIEŠPATS: Štai aš prieš tave ir išsitrauksiu savo kalaviją iš jo makšties, ir iškirsiu iš tavęs teisųjį ir nedorėlį.'),
  (@b26, 21, 4, 'Kadangi iškirsiu iš tavęs teisųjį ir nedorėlį, todėl išeis mano kalavijas iš savo makšties prieš visus kūnus nuo pietų iki šiaurės;'),
  (@b26, 21, 5, 'kad visi kūnai žinotų, kad aš, VIEŠPATS, ištraukiau savo kalaviją iš jo makšties; jis nebesugrįš.'),
  (@b26, 21, 6, 'Todėl tu, žmogaus sūnau, dūsauk laužydamas savo strėnas; ir su kartumu dūsauk jų akyse.'),
  (@b26, 21, 7, 'Ir bus, kai jie tau sakys: „Kodėl tu dūsauji?“, tuomet atsakyk: „Dėl žinios, nes ji ateina“; ir sutirps kiekviena širdis, nusilps visos rankos, nualps kiekviena dvasia, ir visi keliai bus silpni kaip vanduo; štai ji ateina ir įvyks’, – sako Viešpats DIEVAS“.'),
  (@b26, 21, 8, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 21, 9, '„Žmogaus sūnau, pranašauk ir sakyk: ‘Taip sako VIEŠPATS: Sakyk: „Kalavijas, kalavijas pagaląstas ir taip pat nušveistas;'),
  (@b26, 21, 10, 'jis pagaląstas smarkioms skerdynėms vykdyti; jis nušveistas, kad žėrėtų; tad ar mums linksmintis? Jis niekina mano sūnaus lazdą kaip bet kokį medį.'),
  (@b26, 21, 11, 'Jis padavė jį nušveisti, kad būtų imamas į ranką; šis kalavijas yra pagaląstas ir nušveistas, kad jį paduotų į žudiko ranką“.'),
  (@b26, 21, 12, 'Šauk ir kauk, žmogaus sūnau; nes jis bus ant mano tautos, jis bus ant visų Izraelio kunigaikščių; siaubas dėl kalavijo apims mano tautą; todėl plok sau per šlaunį.'),
  (@b26, 21, 13, 'Nes tai išbandymas; o ką, jei kalavijas paniekins lazdą? Jos nebebus, – sako Viešpats DIEVAS.'),
  (@b26, 21, 14, '– Todėl tu, žmogaus sūnau, pranašauk ir plok ranka į ranką, ir tegul trečią kartą kalavijas padvigubėja, užmuštųjų kalavijas; tai nužudytų didžiūnų kalavijas, įeinantis į jų slaptus kambarius.'),
  (@b26, 21, 15, 'Aš nukreipiau kalavijo smaigalį prieš visus jų vartus, kad nualptų jų širdys ir padaugėtų jų griuvėsių; ak! Jis nublizgintas, paruoštas skerdynėms.'),
  (@b26, 21, 16, 'Eik vienu ar kitu keliu, į dešinę ar į kairę, kur tik nukreiptas tavo veidas.'),
  (@b26, 21, 17, 'Aš irgi suplosiu rankomis ir ilsinsiu savo įtūžį; aš, VIEŠPATS, tai pasakiau’“.'),
  (@b26, 21, 18, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 21, 19, '„Žmogaus sūnau, paskirk sau du kelius, kuriais galėtų ateiti Babilono karaliaus kalavijas; jie abu išeis iš vienos šalies; ir išrink vietą, išrink ją kelio į miestą pradžioje.'),
  (@b26, 21, 20, 'Paskirk kelią, kad kalavijas ateitų į amoniečių Rabą ir į Judą, į sutvirtintą Jeruzalę.'),
  (@b26, 21, 21, 'Nes Babilono karalius sustojo kelio išsišakojime, dviejų kelių pradžioje, kad paburtų; jis nublizgino savo strėles, tarėsi su atvaizdais, apžiūrėjo kepenis.'),
  (@b26, 21, 22, 'Jo dešinėje buvo būrimas apie Jeruzalę, kad paskirtų vadus atverti burną žudynėse, kad šauksmu keltų balsą, kad paskirtų mūrdaužius prieš vartus, kad supiltų kalną ir pastatytų fortą.'),
  (@b26, 21, 23, 'Ir jiems, davusiems priesaikas, tai bus kaip apgaulingas būrimas jų akyse; bet jis prisimins tą neteisybę, kad jie būtų pagauti.'),
  (@b26, 21, 24, 'Todėl taip sako Viešpats DIEVAS: ‘Kadangi jūs priminėte savo neteisybę savo nusižengimus atidengdami taip, kad visuose jūsų darbuose pasirodo jūsų nuodėmės; aš sakau, – kadangi jūs prisimenami, tai būsite pagauti ranka.'),
  (@b26, 21, 25, 'O tu, susiteršęs nedoras Izraelio kunigaikšti, kurio diena atėjo, kai neteisybei bus galas,'),
  (@b26, 21, 26, 'taip sako Viešpats DIEVAS: ‘Nuimk diademą, nuimk vainiką; to paties nebebus; išaukštink nužemintąjį ir pažemink aukštąjį.'),
  (@b26, 21, 27, 'Aš tai nuversiu, nuversiu, nuversiu; ir to nebebus, kol ateis tas, kuris turi teisę; ir jam tai duosiu’.'),
  (@b26, 21, 28, 'O tu, žmogaus sūnau, pranašauk ir sakyk: ‘Taip sako Viešpats DIEVAS apie amoniečius ir apie jų priekaištą; sakyk: Kalavijas, kalavijas ištrauktas; nublizgintas skerdynėms, kad rytų, nes yra žėrintis;'),
  (@b26, 21, 29, 'kai jie mato tau tuštybę, kai buria tau melą, kad tave atvestų ant sprandų užmuštųjų, nedorėlių, kurių diena atėjo, kai jų neteisybei bus galas.'),
  (@b26, 21, 30, 'Ar aš jį sugrąžinsiu į jo makštį? Tave teisiu toje vietoje, kur buvai sutvertas, tavo gimtoje šalyje.'),
  (@b26, 21, 31, 'Ir aš išliesiu ant tavęs savo pasipiktinimą, pūsiu į tave savo rūstybės ugnimi ir atiduosiu tave į žvėriškų bei įgudusių žudyti žmonių rankas.'),
  (@b26, 21, 32, 'Tu būsi kuras ugniai; tavo kraujas bus šalies viduje; tavęs nebeatsimins; nes aš, VIEŠPATS, tai kalbėjau’“.'),
  (@b26, 22, 1, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 22, 2, '„Na, o tu, žmogaus sūnau, ar tu teisi, ar tu teisi kruviną miestą? Taip, paskelbk jam visas jo bjaurystes.'),
  (@b26, 22, 3, 'Tada sakyk: ‘Taip sako Viešpats DIEVAS: Tas miestas lieja kraują savo viduje, kad ateitų jo laikas, ir prieš save daro stabus, kad susiterštų.'),
  (@b26, 22, 4, 'Tu tapai kaltas savo krauju, kurį praliejai; ir susiteršei savo stabais, kuriuos padarei; tu priartinai savo dienas ir atėjai iki savo metų; todėl padariau tave priekaištu pagonims ir pasityčiojimu visoms šalims.'),
  (@b26, 22, 5, 'Esantys arti tavęs ir esantys toli nuo tavęs, tyčiosis iš tavęs negarbingo, daug varginamo.'),
  (@b26, 22, 6, 'Štai Izraelio kunigaikščiai, kiekvienas tavyje buvo savo galioje, kad kraują pralietų.'),
  (@b26, 22, 7, 'Tavyje jie paniekino tėvą ir motiną; tavo viduje jie engė ateivį; tavyje jie vargino našlaitį ir našlę.'),
  (@b26, 22, 8, 'Tu paniekinai mano šventenybes ir suteršei mano sabatus.'),
  (@b26, 22, 9, 'Tavyje yra žmonės, šmeižiantys, kad pralietų kraują; ir tavyje jie valgo ant kalnų; tavo viduje jie daro nešvankybes.'),
  (@b26, 22, 10, 'Tavyje jie atidengė savo tėvų nuogumą; tavyje jie pažemino tą, kuri buvo atsiskyrusi dėl susiteršimo.'),
  (@b26, 22, 11, 'Vienas darė bjaurystę su savo artimo žmona; kitas nešvankiai suteršė savo marčią; kitas tavyje pažemino savo seserį, savo tėvo dukterį.'),
  (@b26, 22, 12, 'Tavyje jie ėmė dovanas, kad pralietų kraują; tu ėmei palūkanas bei prieaugį ir prievarta godžiai pasipelnei iš savo artimo, ir pamiršai mane, – sako Viešpats DIEVAS.'),
  (@b26, 22, 13, '– Štai todėl aš suplojau savo ranka dėl tavo nesąžiningo pelno, kurį įsigijai, ir dėl tavo kraujo, kuris buvo tavo tarpe.'),
  (@b26, 22, 14, 'Ar gali ištverti tavo širdis, ar gali būti stiprios tavo rankos tomis dienomis, kai užsiimsiu tavimi? Aš, VIEŠPATS, tai kalbėjau ir tai įvykdysiu.'),
  (@b26, 22, 15, 'Ir išsklaidysiu tave tarp pagonių, išvaikysiu tave šalyse ir išnaikinsiu iš tavęs tavo nešvarumą.'),
  (@b26, 22, 16, 'Ir tu imsi savo paveldą savyje pagonių akyse ir žinosi, kad aš esu VIEŠPATS’“.'),
  (@b26, 22, 17, 'Man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 22, 18, '„Žmogaus sūnau, Izraelio namai man tapo išdagomis; jie visi yra žalvaris, alavas, geležis ir švinas krosnies viduje; jie yra sidabro išdagos.'),
  (@b26, 22, 19, 'Todėl taip sako Viešpats DIEVAS: ‘Kadangi jūs visi tapote išdagomis, todėl štai aš jus surinksiu į Jeruzalės vidurį.'),
  (@b26, 22, 20, 'Kaip surenka sidabrą, varį, geležį, šviną ir alavą į krosnies vidurį, kad į juos pūstų ugnį lydymui, taip aš savo pyktyje ir savo įtūžyje jus surinksiu, ten jus paliksiu ir jus išlydysiu.'),
  (@b26, 22, 21, 'Taip, aš jus surinksiu ir pūsiu į jus savo rūstybės ugnimi, ir jūs būsite išlydyti jos viduryje.'),
  (@b26, 22, 22, 'Kaip sidabras ištirpdomas krosnies viduryje, taip jūs būsite ištirpdyti jos viduryje; ir žinosite, kad aš, VIEŠPATS, išliejau ant jūsų savo įtūžį’“.'),
  (@b26, 22, 23, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b26, 22, 24, '„Žmogaus sūnau, sakyk jai: ‘Tu esi šalis, kuri neapvalyta ir ant kurios nelijo pasipiktinimo dieną.'),
  (@b26, 22, 25, 'Jos tarpe jos pranašų sąmokslas – kaip riaumojantis liūtas, draskantis grobį; jie rijo sielas; jie pasiėmė lobį ir brangenybes; jie padarė daug našlių jos tarpe.'),
  (@b26, 22, 26, 'Jos kunigai laužė mano įstatymą ir suteršė mano šventenybes; jie nedarė skirtumo tarp to, kas šventa ir kas nešventa, ir neparodė skirtumo tarp nešvaraus ir švaraus, ir paslėpė savo akis nuo mano sabatų, ir aš esu tarp jų suterštas.'),
  (@b26, 22, 27, 'Jos kunigaikščiai jos tarpe yra kaip vilkai, draskantys grobį, kad pralietų kraują, naikintų sielas ir kad įsigytų nesąžiningą pelną.'),
  (@b26, 22, 28, 'O jos pranašai juos aptinkavo nemaišytu skiediniu, regėdami tuštybę ir jiems burdami melus, sakydami: „Taip sako Viešpats DIEVAS“, kai VIEŠPATS nekalbėjo.'),
  (@b26, 22, 29, 'Šalies tauta engė, plėšikavo ir vargino vargšą bei beturtį; taip, jie neteisėtai engė ateivį.'),
  (@b26, 22, 30, 'Ir aš ieškojau tarp jų žmogaus, kuris statytų tvorą ir atsistotų spragoje prieš mane dėl šios šalies, idant jos nesunaikinčiau; bet nei vieno neradau.'),
  (@b26, 22, 31, 'Todėl išliejau ant jų savo pasipiktinimą; savo rūstybės ugnimi juos sunaikinau; jų pačių kelią atlyginau ant jų galvų, – sako Viešpats DIEVAS’“.'),
  (@b26, 23, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 23, 2, '„Žmogaus sūnau, buvo dvi moterys, vienos motinos dukterys;'),
  (@b26, 23, 3, 'ir jos paleistuvavo Egipte; jos paleistuvavo savo jaunystėje; ten buvo spaudžiamos jų krūtys ir ten gniuždė jų mergystės spenelius.'),
  (@b26, 23, 4, 'Jų vardai buvo: vyresnioji Ohola, ir jos sesuo – Oholiba; jos buvo mano, ir jos pagimdė sūnų bei dukterų. Tokie buvo jų vardai: Ohola – tai Samarija, o Oholiba – tai Jeruzalė.'),
  (@b26, 23, 5, 'Ohola paleistuvavo, kai buvo mano; ji beprotiškai mylėjo savo meilužius, kaimynus asirus,'),
  (@b26, 23, 6, 'apsirengusius mėlynai, vadus ir valdovus; jie visi geistini jaunuoliai, raiteliai, jojantys ant žirgų.'),
  (@b26, 23, 7, 'Taip ji darė savo paleistuvystes su jais, su visais Asirijos rinktiniais vyrais ir su visais, kuriuos ji beprotiškai mylėjo; ji susiteršė visais jų stabais.'),
  (@b26, 23, 8, 'Ir ji nepaliko savo paleistuvysčių, atsineštų iš Egipto; nes jie gulėjo su ja jos jaunystėje, gniuždė jos mergystės krūtis ir išliejo ant jos savo paleistuvystę.'),
  (@b26, 23, 9, 'Todėl aš ją atidaviau į jos meilužių rankas: į rankas asirų, kuriuos ji beprotiškai mylėjo.'),
  (@b26, 23, 10, 'Jie atidengė jos nuogumą; jie paėmė jos sūnus bei jos dukteris, o ją nužudė kalaviju; ir ji tapo garsi tarp moterų; nes jie įvykdė jai teismą.'),
  (@b26, 23, 11, 'O jos sesuo Oholiba tai matydama, buvo už ją dar labiau sugedusi savo besaike meile, ir savo paleistuvavimais labiau už savo sesers paleistuvavimus.'),
  (@b26, 23, 12, 'Ji beprotiškai mylėjo savo kaimynus asirus, puošniausiai apsirengusius vadus ir valdovus, raitelius, jojančius ant žirgų; jie visi geistini jaunuoliai.'),
  (@b26, 23, 13, 'Tada aš mačiau, kad ji buvo suteršta, kad jos abi pasirinko vieną kelią'),
  (@b26, 23, 14, 'ir kad ji daugino savo paleistuvystes; nes pamačiusi sienoje nupieštus vyrus, kaldėjų atvaizdus, nupieštus ryškiai raudonai,'),
  (@b26, 23, 15, 'susijuosusius strėnas juostomis, pranokstančius dažytais raiščiais ant jų galvų, jie visi kunigaikščiai, atrodantys kaip babiloniečiai Kaldėjos, jų gimtosios šalies;'),
  (@b26, 23, 16, 'ir vos tik savo akimis juos pamačiusi, ji beprotiškai juos įsimylėjo ir siuntė pas juos pasiuntinius į Kaldėją.'),
  (@b26, 23, 17, 'Ir babiloniečiai atėjo pas ją į meilės guolį ir suteršė ją savo paleistuvavimu, ir ji susiteršė su jais, ir jos širdis nuo jų nutolo.'),
  (@b26, 23, 18, 'Taip ji atidengė savo paleistuvavimus ir atidengė savo nuogumą; tada mano širdis nuo jos nutolo, kaip mano širdis buvo nutolusi nuo jos sesers.'),
  (@b26, 23, 19, 'Tačiau ji daugino savo paleistuvystes, atsimindama savo jaunystės dienas, kai ji paleistuvavo Egipto šalyje.'),
  (@b26, 23, 20, 'Nes ji beprotiškai mylėjo savo meilužius, kurių kūnas kaip asilų kūnas, kurių sėklos išsiliejimas kaip arklių sėklos išsiliejimas.'),
  (@b26, 23, 21, 'Taip tu prisiminei savo jaunystės gašlumą, egiptiečiams gniuždant tavo spenelius dėl tavo jaunystės krūtų.'),
  (@b26, 23, 22, 'Todėl, Oholiba, taip sako Viešpats DIEVAS: Štai aš sukelsiu prieš tave tavo meilužius, nuo kurių nutolusi tavo širdis, ir juos atvesiu prieš tave iš visų pusių:'),
  (@b26, 23, 23, 'babiloniečius ir visus kaldėjus, Pekodą, Šoją, Koją, visus asirus su jais – jie visi geistini jaunuoliai, vadai ir valdovai, didūs viešpačiai ir žymūs, visi jojantys ant žirgų.'),
  (@b26, 23, 24, 'Jie ateis prieš tave su vežimais, vežėčiomis, ratais ir su žmonių sambūriu, kurie sustatys prieš tave aplinkui didžiuosius bei mažuosius skydus ir šalmus; ir aš pavesiu jiems teismą, ir jie teis tave pagal savo teismus.'),
  (@b26, 23, 25, 'Ir nukreipsiu prieš tave savo pavydą, ir jie įtūžusiai pasielgs su tavimi; jie nuplėš tavo nosį ir tavo ausis; o tavo likutis kris nuo kalavijo; jie paims tavo sūnus ir tavo dukteris; o tavo likusieji bus ugnies praryti.'),
  (@b26, 23, 26, 'Taip pat jie nuplėš tavo drabužius ir atims tavo gražias brangenybes.'),
  (@b26, 23, 27, 'Taip padarysiu galą tavo gašlumui ir tavo paleistuvavimui, kurį atsinešei iš Egipto šalies; taip, kad nebepakelsi į juos savo akių ir nebeatsiminsi Egipto.'),
  (@b26, 23, 28, 'Nes taip sako Viešpats DIEVAS: Štai aš tave atiduosiu į rankas tų, kurių tu nekenti, į rankas tų, nuo kurių atitolusi tavo širdis;'),
  (@b26, 23, 29, 'ir jie elgsis su tavimi su neapykanta, atims visą tavo triūsą ir paliks tave nuogą ir pliką; ir bus atidengtas tavo paleistuvysčių nuogumas, tiek tavo gašlumas, tiek tavo paleistuvavimai.'),
  (@b26, 23, 30, 'Tau visa tai padarysiu, kadangi ėjai paleistuvaudama paskui pagonis ir kadangi esi susiteršusi jų stabais.'),
  (@b26, 23, 31, 'Tu vaikščiojai savo sesers keliu; todėl jos taurę paduosiu į tavo ranką.'),
  (@b26, 23, 32, 'Taip sako Viešpats DIEVAS: Tu gersi iš savo sesers taurės, gilios ir plačios: tu būsi išjuokta ir pašiepta; daug joje yra.'),
  (@b26, 23, 33, 'Tu būsi pripildyta girtumo ir sielvarto, nustebimo ir nusiaubimo taurės, tavo sesers Samarijos taurės.'),
  (@b26, 23, 34, 'Tu ją gersi ir išsiurbsi, sudaužysi jos šukes ir nusiplėši sau krūtis; nes aš tai kalbėjau’, – sako Viešpats DIEVAS.'),
  (@b26, 23, 35, 'Todėl taip sako Viešpats DIEVAS: ‘Kadangi mane pamiršai ir mane numetei sau už nugaros, todėl ir tu nešiok savo gašlumą ir savo paleistuvavimus’“.'),
  (@b26, 23, 36, 'VIEŠPATS man dar tarė: „Žmogaus sūnau, ar teisi Oholą ir Oholibą? Taip, paskelbk joms jų bjaurystes;'),
  (@b26, 23, 37, 'kad jos svetimavo, ir kraujas yra ant jų rankų, ir jos svetimavo su savo stabais, ir taip pat savo sūnus, kuriuos jos man pagimdė, leido tiems per ugnį, kad juos prarytų.'),
  (@b26, 23, 38, 'Dar ir tai jos man padarė: tą pačią dieną jos suteršė mano šventovę ir išniekino mano sabatus.'),
  (@b26, 23, 39, 'Nes papjovusios savo vaikus savo stabams, tą pačią dieną jos įeidavo į mano šventovę, kad ją suterštų; ir štai taip jos darė mano namų viduryje.'),
  (@b26, 23, 40, 'Be to, jūs siuntėte vyrams, kad ateitų iš toli, pas kuriuos buvo nusiųstas pasiuntinys; ir štai jie atėjo; dėl jų tu nusiprausei, pasidažei akis ir pasipuošei papuošalais,'),
  (@b26, 23, 41, 'atsisėdai į didingą guolį, o prieš jį paruoštas stalas, ant kurio tu padėjai mano smilkalus ir mano aliejų.'),
  (@b26, 23, 42, 'Pas ją buvo nerūpestingos minios balsas; ir su paprastais žmonėmis buvo atvesti sabiečiai iš dykumos, kurie dėjo apyrankes ant jų rankų ir gražias karūnas ant jų galvų.'),
  (@b26, 23, 43, 'Tada tariau pasenusiajai svetimavimuose: „Ar dabar jie paleistuvaus su ja, o ji su jais?“'),
  (@b26, 23, 44, 'Bet jie įėjo pas ją, kaip įeina pas paleistuvaujančią moterį; taip jie įėjo pas Oholą ir pas Oholibą, gašlias moteris.'),
  (@b26, 23, 45, 'Ir teisūs žmonės jas teis kaip svetimautojas ir kaip moteris, praliejančias kraują; nes jos svetimautojos, ir kraujas yra ant jų rankų.'),
  (@b26, 23, 46, 'Nes taip sako Viešpats DIEVAS: Aš atvesiu ant jų aukštyn būrį ir jas atiduosiu, kad būtų pašalintos ir apiplėštos.'),
  (@b26, 23, 47, 'Ir būrys užmėtys jas akmenimis ir nužudys jas savo kalavijais; jie nužudys jų sūnus bei jų dukteris ir sudegins jų namus ugnimi.'),
  (@b26, 23, 48, 'Taip aš padarysiu galą gašlumui šalyje, kad visos moterys būtų išmokytos nesielgti pagal jūsų gašlumą.'),
  (@b26, 23, 49, 'Ir jūsų gašlumą atlygins ant jūsų, ir jūs nešiosite savo stabų nuodėmes; ir jūs žinosite, kad aš esu Viešpats DIEVAS’“.'),
  (@b26, 24, 1, 'Devintaisiais metais, dešimtąjį mėnesį, to mėnesio dešimtąją dieną, man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 24, 2, '„Žmogaus sūnau, užsirašyk šios dienos, būtent šitos pačios dienos, vardą; Babilono karalius šitą pačią dieną nusistatė prieš Jeruzalę.'),
  (@b26, 24, 3, 'Ir sakyk palyginimą maištaujantiems namams, ir jiems tark: ‘Taip sako Viešpats DIEVAS: Uždėk katilą, uždėk, ir įpilk į jį vandens;'),
  (@b26, 24, 4, 'surink į jį jo gabalus – visus gerus gabalus, šlaunį ir petį; pripildyk jį rinktiniais kaulais.'),
  (@b26, 24, 5, 'Paimk, kas geriausia iš kaimenės, taip pat degink po juo kaulus ir gerai jį pavirink, ir tegul išverda jo kaulai jame.'),
  (@b26, 24, 6, 'Todėl taip sako Viešpats DIEVAS: Vargas kruvinam miestui, katilui, kuriame yra jo nuoviros, kurio nuoviros nėra iš jo dingusios! Išimk juos gabalą po gabalo; tegul ant jo nekrenta burtas.'),
  (@b26, 24, 7, 'Nes jo kraujas yra jo viduje; jis padėjo jį ant uolos viršūnės; jis jo neišliejo ant žemės, kad užsidengtų dulkėmis;'),
  (@b26, 24, 8, 'kad paskatintų ateiti aukštyn įtūžį dėl atkeršijimo; aš jo kraują padėjau ant uolos viršūnės, kad jis nebūtų uždengtas.'),
  (@b26, 24, 9, 'Todėl taip sako Viešpats DIEVAS: Vargas kruvinam miestui! Aš sukrausiu didelį laužą ugniai.'),
  (@b26, 24, 10, 'Sukrauk malkas, užkurk ugnį, degink mėsą, gerai ją paskanink prieskoniais ir tesudega kaulai.'),
  (@b26, 24, 11, 'Tada pastatyk jį tuščią ant žarijų, kad jo žalvaris įkaistų ir sudegtų, ir kad jame ištirptų jo nešvarumai, idant sudegtų jo nuoviros.'),
  (@b26, 24, 12, 'Jis nuvargino save melais, ir jo didelės nuoviros neišėjo iš jo; jo nuoviros bus ugnyje.'),
  (@b26, 24, 13, 'Tavo nešvarume yra gašlumas; kadangi tave nuvaliau, o tu neapsivalei, tai daugiau nebebūsi apvalomas nuo savo nešvarumo, kol aš ilsinsiu ant tavęs savo įtūžį.'),
  (@b26, 24, 14, 'Aš, VIEŠPATS, tai kalbėjau; tai įvyks, aš tai padarysiu; aš neatsitrauksiu ir nepasigailėsiu, ir neapgailestausiu; jie tave teis pagal tavo kelius ir pagal tavo darbus, – sako Viešpats DIEVAS’“.'),
  (@b26, 24, 15, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 24, 16, '„Žmogaus sūnau, štai aš kirčiu atimsiu iš tavęs tavo akių troškimą; tačiau tu nei raudosi, nei verksi, nei liesis tavo ašaros.'),
  (@b26, 24, 17, 'Susilaikyk nuo verkimo, neapraudok mirusių, apsirišk savo galvos raiščiu, apsiauk kojas savo apavu, neuždenk savo lūpų ir nevalgyk žmonių duonos“.'),
  (@b26, 24, 18, 'Taigi ryte aš kalbėjau tautai; ir vakare mirė mano žmona; o ryte aš padariau, kaip man buvo įsakyta.'),
  (@b26, 24, 19, 'Ir tauta man tarė: „Ar mums nepasakysi, ką reiškia mums tai, ką tu darai?“'),
  (@b26, 24, 20, 'Tada aš jiems atsakiau: „Man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 24, 21, '‘Kalbėk Izraelio namams: Taip sako Viešpats DIEVAS: Štai aš suteršiu savo šventovę, jūsų stiprybės puikybę, jūsų akių troškimą, tai, ko gailisi jūsų siela; o jūsų sūnūs ir jūsų dukterys, kuriuos palikote, kris nuo kalavijo.'),
  (@b26, 24, 22, 'Ir jūs darysite, kaip aš dariau: jūs neužsidengsite savo lūpų ir nevalgysite žmonių duonos.'),
  (@b26, 24, 23, 'Jūsų raiščiai bus ant jūsų galvų ir jūsų apavas ant jūsų kojų; jūs neraudosite ir neverksite; bet sunyksite dėl savo neteisybių ir raudosite vienas kitam.'),
  (@b26, 24, 24, 'Taip Ezekielis jums yra ženklas; jūs darysite pagal visa tai, ką jis darė; ir tam įvykus, jūs žinosite, kad aš esu Viešpats DIEVAS’“.'),
  (@b26, 24, 25, 'Be to, žmogaus sūnau, argi tą dieną, kai iš jų atimsiu jų stiprybę, jų šlovės džiaugsmą, jų akių troškimą ir tai, į ką jie nukreipia savo širdis, jų sūnus ir jų dukteris,'),
  (@b26, 24, 26, 'argi nebus, kad tą dieną tas, kuris pabėgo, ateis pas tave, kad tavo ausims duotų tai išgirsti?'),
  (@b26, 24, 27, 'Tą dieną tavo burna atsivers pabėgusiajam, ir tu kalbėsi ir nebebūsi nebylus; ir tu jiems būsi ženklas; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 25, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 25, 2, '„Žmogaus sūnau, nukreipk savo veidą prieš amoniečius ir pranašauk prieš juos;'),
  (@b26, 25, 3, 'ir sakyk amoniečiams: ‘Klausykite Viešpaties DIEVO žodžio: Taip sako Viešpats DIEVAS: Kadangi tu sakei „Aha“ prieš mano šventovę, kai ji buvo suteršta; ir prieš Izraelio šalį, kai ji buvo nuniokota; ir prieš Judos namus, kai jie ėjo nelaisvėn;'),
  (@b26, 25, 4, 'todėl štai aš atiduosiu tave rytų žmonėms nuosavybėn, ir jie pasistatys tavyje savo rūmus ir pasidarys tavyje savo buveines; jie valgys tavo vaisius ir gers tavo pieną.'),
  (@b26, 25, 5, 'Ir aš padarysiu Rabą tvartu kupranugariams, o amoniečius – gulykla kaimenėms; ir jūs žinosite, kad aš esu VIEŠPATS.'),
  (@b26, 25, 6, 'Nes taip sako Viešpats DIEVAS: Kadangi plojai rankomis, trypei kojomis ir iš širdies su visa neapykanta džiaugeisi prieš Izraelio šalį;'),
  (@b26, 25, 7, 'todėl štai aš ištiesiu savo ranką į tave ir atiduosiu tave kaip grobį pagonims; aš tave iškirsiu iš tautų ir pražudysiu tave visose šalyse; aš tave sunaikinsiu; ir tu žinosi, kad aš esu VIEŠPATS’“.'),
  (@b26, 25, 8, 'Taip sako Viešpats DIEVAS: „Kadangi Moabas ir Seyras sako: ‘Štai Judos namai yra kaip visi pagonys’;'),
  (@b26, 25, 9, 'todėl štai aš atidarysiu Moabo šoną nuo miestų, nuo jo pasienio miestų – krašto šlovės: Bet-Ješimoto, Baal-Meono ir Kirjataimo,'),
  (@b26, 25, 10, 'iki rytų žmonių su amoniečiais, ir juos duosiu nuosavybėn, kad amoniečių nebebūtų atmenama tarp tautų.'),
  (@b26, 25, 11, 'Aš įvykdysiu teismus Moabui; ir jie žinos, kad aš esu VIEŠPATS“.'),
  (@b26, 25, 12, 'Taip sako Viešpats DIEVAS: „Kadangi Edomas kerštingai pasielgė su Judos namais ir labai nusikalto, ir jiems keršijo;'),
  (@b26, 25, 13, 'todėl taip sako Viešpats DIEVAS: ‘Aš irgi ištiesiu savo ranką į Edomą, iškirsiu iš jo žmones bei gyvulius ir paversiu jį dykyne nuo Temano; ir tie iš Dedano kris nuo kalavijo.'),
  (@b26, 25, 14, 'Ir aš įvykdysiu savo kerštą Edomui savo tautos Izraelio ranka; jie darys Edome pagal mano pyktį ir pagal mano įtūžį; ir jie pažins mano kerštą, – sako Viešpats DIEVAS’“.'),
  (@b26, 25, 15, 'Taip sako Viešpats DIEVAS: „Kadangi filistinai elgėsi kerštingai ir žiauria širdimi keršijo, kad sunaikintų dėl senos neapykantos;'),
  (@b26, 25, 16, 'todėl taip sako Viešpats DIEVAS: ‘Štai aš ištiesiu savo ranką į filistinus, iškirsiu keretus ir išnaikinsiu pajūrio likutį.'),
  (@b26, 25, 17, 'Ir jiems įvykdysiu didžiulį kerštą smarkiais barimais; ir jie žinos, kad aš esu VIEŠPATS, kai įvykdysiu ant jų savo kerštą’“.'),
  (@b26, 26, 1, 'Ir vienuoliktaisiais metais, pirmąją mėnesio dieną įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 26, 2, '„Žmogaus sūnau, kadangi Tyras sakė prieš Jeruzalę: ‘Aha, sugriauta ta, kuri buvo tautų vartai; ji atsisuko į mane; aš būsiu pripildytas, dabar ji ištuštėjusi’;'),
  (@b26, 26, 3, 'todėl taip sako Viešpats DIEVAS: ‘Štai aš esu prieš tave, Tyre, ir priversiu ateiti prieš tave daug tautų, kaip jūra priverčia pakilti savo bangas.'),
  (@b26, 26, 4, 'Jos sunaikins Tyro sienas ir nugriaus jo bokštus; taip pat aš nuo jo nušluosiu jo dulkes ir padarysiu jį kaip uolos viršūnę.'),
  (@b26, 26, 5, 'Jis bus tinklų ištiesimo vieta jūros viduryje; nes aš tai kalbėjau, – sako Viešpats DIEVAS; – ir jis taps grobiu tautoms.'),
  (@b26, 26, 6, 'O jo dukterys, esančios laukuose, bus nužudytos kalaviju; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 26, 7, 'Nes taip sako Viešpats DIEVAS: „Štai aš ant Tyro atvesiu iš šiaurės Babilono karalių Nebukadrecarą, karalių karalių, su žirgais, su vežimais, su raiteliais, būriais ir su daugybe liaudies.'),
  (@b26, 26, 8, 'Jis tavo dukteris nužudys laukuose kalaviju; jis pastatys prieš tave fortą, supils prieš tave kalną ir pakels prieš tave skydą.'),
  (@b26, 26, 9, 'Jis nukreips prieš tavo sienas karo mašinas ir nugriaus tavo bokštus kirviais.'),
  (@b26, 26, 10, 'Dėl jo žirgų gausos tave apdengs jų dulkės; nuo raitelių, nuo ratų ir nuo vežimų triukšmo drebės tavo sienos, kai jis įeis į tavo vartus, kaip įeinama į miestą, kuriame yra padaryta spraga.'),
  (@b26, 26, 11, 'Savo žirgų kanopomis jis sutryps visas tavo gatves; tavo tautą jis žudys kalaviju, ir tavo tvirtos įgulos nuvirs žemėn.'),
  (@b26, 26, 12, 'Jie pagrobs tavo turtus, išplėš tavo prekes; nugriaus tavo sienas, sunaikins tavo geistinus namus; ir suvers į vandenį tavo akmenis, tavo medieną bei tavo dulkes.'),
  (@b26, 26, 13, 'Ir aš padarysiu, kad liausis tavo dainų skambesys; ir nebesigirdės tavo arfų garso.'),
  (@b26, 26, 14, 'Ir padarysiu tave kaip uolos viršūnę; tu būsi vieta tinklams ištiesti; tu nebebūsi atstatytas; nes aš, VIEŠPATS, tai kalbėjau“, – sako Viešpats DIEVAS.'),
  (@b26, 26, 15, 'Taip sako Viešpats DIEVAS Tyrui: „Argi nedrebės salos nuo tavo griuvimo garso, kai šauks sužeistieji, kai skerdynės vyks tavo tarpe?'),
  (@b26, 26, 16, 'Tada visi jūros kunigaikščiai nužengs nuo savo sostų, padės į šalį savo apsiaustus ir nusivilks savo siuvinėtus drabužius; jie apsivilks drebėjimu; jie sėdės ant žemės ir kiekvienu momentu drebės, ir bus apstulbę dėl tavęs.'),
  (@b26, 26, 17, 'Jie dėl tavęs imsis raudos ir tau sakys: ‘Kaipgi tu sunaikintas, kuris buvai apgyvendintas jūreivių, garsusis mieste, kuris buvai galingas jūroje, tu ir tavo gyventojai, sukeliantys siaubą dažnai jį lankantiems!’'),
  (@b26, 26, 18, 'Na, o salos drebės tavo kritimo dieną; taip, salos, esančios jūroje, sunerims dėl tavo išėjimo.'),
  (@b26, 26, 19, 'Nes taip sako Viešpats DIEVAS: ‘Kai tave padarysiu apleistu miestu, tokiu, kaip negyvenami miestai; kai atvesiu aukštyn ant tavęs gelmes, ir dideli vandenys apdengs tave;'),
  (@b26, 26, 20, 'kai aš nugramzdinsiu tave su nužengiančiais į duobę su senų laikų tauta ir patalpinsiu tave žemutinėse žemės dalyse, senose dykvietėse, su nužengiančiais į duobę, kad tu nebūtum apgyvendintas; ir aš pastatysiu šlovę gyvųjų šalyje;'),
  (@b26, 26, 21, 'aš padarysiu tave siaubu, ir tavęs nebebus; nors tavęs ieškos, tačiau niekada neberas, – sako Viešpats DIEVAS’“.'),
  (@b26, 27, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 27, 2, '„Dabar, žmogaus sūnau, imkis raudos dėl Tyro;'),
  (@b26, 27, 3, 'ir sakyk Tyrui: ‘O tu, išsidėstęs prie jūros įėjimo, kuris esi tautų prekiautojas dėl daugelio salų, taip sako Viešpats DIEVAS: O Tyre, tu sakei: „Aš esu tobulo grožio“.'),
  (@b26, 27, 4, 'Tavo ribos jūrų viduryje, tavo statytojai ištobulino tavo grožį.'),
  (@b26, 27, 5, 'Iš Senyro eglių jie padarė visas tavo laivų lentas; jie iš Libano paėmė kedrų, kad padarytų tau laivų stiebų.'),
  (@b26, 27, 6, 'Iš Bašano ąžuolų jie padarė tavo irklus; ašurų būrys padarė tavo suolus iš dramblio kaulo, atgabento iš Kitimų salų.'),
  (@b26, 27, 7, 'Plonas siuvinėto darbo linas iš Egipto buvo tai, ką tu išskleidi, kad būtų tavo burės; mėlynas ir purpurinis iš Elišos salų buvo tavo dangalas.'),
  (@b26, 27, 8, 'Sidono ir Arvado gyventojai buvo tavo jūrininkai; tavo išminčiai, esantys tavyje, o Tyre, buvo tavo laivavedžiai.'),
  (@b26, 27, 9, 'Gebalo senoliai ir jo išminčiai tavyje buvo tavo plyšių užtaisinėtojai; visi jūros laivai su jų jūrininkais buvo tavyje, kad užsiimtų tavo prekyba.'),
  (@b26, 27, 10, 'Tie iš Persijos, iš Ludo ir iš Puto buvo tavo kariuomenėje, tavo karo vyrai; skydą ir šalmą jie pakabino tavyje; jie išstatė tavo gražumą.'),
  (@b26, 27, 11, 'Arvado vyrai su tavo kariuomene buvo aplinkui ant tavo sienų, o gamadiečiai buvo tavo bokštuose; savo skydus jie sukabino aplinkui ant tavo sienų; jie padarė tavo grožį tobulą.'),
  (@b26, 27, 12, 'Taršišas buvo tavo pirklys dėl daugybės visokiausių turtų; sidabru, geležimi, alavu ir švinu jie prekiavo tavo turguose.'),
  (@b26, 27, 13, 'Javanas, Tubalas ir Mešechas buvo tavo pirkliai; jie prekiavo tavo turguje žmonių sielomis ir žalvariniais indais.'),
  (@b26, 27, 14, 'Tie iš Togarmos namų prekiavo tavo mugėse arkliais, raiteliais ir mulais.'),
  (@b26, 27, 15, 'Dedano žmonės buvo tavo pirkliai; daugelis salų buvo tavo rankos prekyba; jie tau atgabeno dovanai dramblio kaulo ragų ir juodmedžių.'),
  (@b26, 27, 16, 'Sirija buvo tavo pirklys dėl daugybės tavo pagamintų prekių; jie užsiėmę tavo turguose smaragdais, purpuru, siuvinėtais dirbiniais, plonu linu, koralais ir agatais.'),
  (@b26, 27, 17, 'Juda ir Izraelio šalis buvo tavo pirkliai; jie prekiavo tavo turguje Minito kviečiais, Panagu, medumi, aliejumi ir balzamu.'),
  (@b26, 27, 18, 'Damaskas buvo tavo pirklys daugybe tavo pagamintų prekių, dėl daugybės visokių turtų; Helbono vynu ir balta vilna.'),
  (@b26, 27, 19, 'Taip pat Danas ir Javanas keliaudami ten ir atgal buvo užsiėmę tavo mugėse: blizganti geležis, kasija ir ajeras buvo tavo turguje.'),
  (@b26, 27, 20, 'Dedanas buvo tavo prekiautojas brangiais apdarais vežimams.'),
  (@b26, 27, 21, 'Arabija ir visi Kedaro kunigaikščiai buvo užsiėmę su tavimi ėriukais, avinais ir ožiais: jais jie buvo tavo prekiautojai.'),
  (@b26, 27, 22, 'Šebos ir Ramos pirkliai buvo tavo prekiautojai: jie užsiėmę tavo turguose svarbiausiais iš visų kvepalų, visokiais brangakmeniais ir auksu.'),
  (@b26, 27, 23, 'Haranas, Kanė ir Edenas, Šebos pirkliai, Ašuras, Kilmadas buvo tavo pirkliai.'),
  (@b26, 27, 24, 'Šitie buvo tavo prekiautojai visokiausiais daiktais, mėlynais drabužiais, siuvinėtais dirbiniais, brangių drabužių skryniomis – susuktomis virvėmis ir padarytomis iš kedro, – tarp tavo prekių.'),
  (@b26, 27, 25, 'Taršišo laivai giedojo apie tave tavo turguje; ir tu prisipildei ir tapai labai šlovingas jūrų viduryje.'),
  (@b26, 27, 26, 'Tavo irklininkai nugabeno tave į didžius vandenis; rytų vėjas sudaužė tave jūrų viduryje.'),
  (@b26, 27, 27, 'Tavo turtai ir tavo turgūs, tavo prekės, tavo jūrininkai ir tavo laivavedžiai, tavo plyšių užtaisytojai ir užsiimantys tavo prekėmis, visi tavo karo vyrai, esantys tavyje ir visoje tavo bendrijoje, kuri yra tavo tarpe, įkris į jūrų vidurį tavo pražūties dieną.'),
  (@b26, 27, 28, 'Nuo tavo laivavedžių šauksmo garso drebės priemiesčiai.'),
  (@b26, 27, 29, 'Ir iš savo laivų išlips visi valdantys irklą, jūrininkai bei visi jūros laivavedžiai – jie atsistos ant žemės;'),
  (@b26, 27, 30, 'ir padarys, kad jų balsas būtų išgirstas prieš tave, ir karčiai šauks, ir bers dulkes sau ant galvų, jie voliosis pelenuose;'),
  (@b26, 27, 31, 'jie visiškai plikai nusiskus dėl tavęs, apsijuos ašutinėmis ir verks dėl tavęs apkartusia širdimi, karčiai aimanuodami.'),
  (@b26, 27, 32, 'Aimanuodami jie dėl tavęs imsis raudos ir apraudos tave, sakydami: „Kuris miestas yra kaip Tyras, kaip sunaikintasis jūros viduryje?“'),
  (@b26, 27, 33, 'Kai tavo prekės ateidavo iš jūrų, tu pripildydavai daug tautų; savo turtų ir prekių daugybe tu praturtinai žemės karalius.'),
  (@b26, 27, 34, 'Tuo laiku, kai tu būsi jūrų sudaužytas vandenų gelmėse, tavo prekės ir visa tavo bendrija, esanti tavo tarpe, kris.'),
  (@b26, 27, 35, 'Visi salų gyventojai bus apstulbę dėl tavęs, ir jų karaliai smarkiai išsigąs, jų veidai bus neramūs.'),
  (@b26, 27, 36, 'Pirkliai tarp tautų švilps dėl tavęs; tu būsi siaubas ir niekada nebebūsi’“.'),
  (@b26, 28, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 28, 2, '„Žmogaus sūnau, sakyk Tyro kunigaikščiui: ‘Taip sako Viešpats DIEVAS: Kadangi pasididžiavo tavo širdis ir tu sakei: „Aš esu Dievas, aš sėdžiu Dievo soste, jūrų viduryje“; tačiau tu esi žmogus, o ne Dievas, nors statai savo širdį kaip Dievo širdį;'),
  (@b26, 28, 3, 'štai tu išmintingesnis už Danielių; nėra paslapties, kurią galėtų nuslėpti nuo tavęs;'),
  (@b26, 28, 4, 'savo išmintimi ir savo supratimu tu įsigijai turtų ir įsigijai aukso bei sidabro į savo lobynus;'),
  (@b26, 28, 5, 'savo didele išmintimi, savo prekyba tu padauginai savo turtus, ir tavo širdis didžiavosi dėl tavo turtų;'),
  (@b26, 28, 6, 'todėl taip sako Viešpats DIEVAS: Kadangi tu statei savo širdį, kaip Dievo širdį,'),
  (@b26, 28, 7, 'todėl štai aš atvesiu ant tavęs svetimšalius, tautų baisiuosius; jie išsitrauks kalavijus prieš tavo išminties grožį ir suterš tavo spindesį.'),
  (@b26, 28, 8, 'Jie nustums tave į duobę, ir tu mirsi mirtimi užmuštųjų jūrų viduryje.'),
  (@b26, 28, 9, 'Ar tu vis dar sakysi savo žudytojo akivaizdoje: „Aš Dievas“? Bet savo žudytojo rankoje tu būsi žmogus, o ne Dievas.'),
  (@b26, 28, 10, 'Tu mirsi neapipjaustytųjų mirtimi nuo svetimšalių rankos; nes aš tai pasakiau, – sako Viešpats DIEVAS’“.'),
  (@b26, 28, 11, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 28, 12, '„Žmogaus sūnau, imkis raudos apie Tyro karalių ir jam sakyk: ‘Taip sako Viešpats DIEVAS: Tu visumos antspaudas, pilnas išminties ir tobulo grožio.'),
  (@b26, 28, 13, 'Tu buvai Edene, Dievo sode; visokie brangūs akmenys buvo tavo apdangalas: sardis, topazas ir deimantas, berilas, oniksas ir jaspis, safyras, smaragdas, raudonasis granatas ir auksas; tavo būgneliai ir tavo dūdelės buvo meistriškai paruošti tavyje tą dieną, kai buvai sutvertas.'),
  (@b26, 28, 14, 'Tu esi pateptasis kerubas, kuris dengia; aš tave tokiu paskyriau; tu buvai šventajame Dievo kalne; tu vaikštinėjai šen bei ten ugningų akmenų tarpe.'),
  (@b26, 28, 15, 'Tu buvai tobulas savo keliuose nuo tos dienos, kai buvai sutvertas, iki kol buvo atrasta tavyje neteisybė.'),
  (@b26, 28, 16, 'Per tavo gausią prekybą jie pripildė tavo tarpą smurto, ir tu nusidėjai; todėl aš išmesiu tave iš Dievo kalno kaip suterštą; ir išnaikinsiu tave, o dengiantis kerube, iš ugningų akmenų tarpo.'),
  (@b26, 28, 17, 'Tavo širdis išsiaukštino dėl tavo grožio, tu sugadinai savo išmintį per savo spindesį; aš numesiu tave ant žemės, paguldysiu tave priešais karalius, kad jie galėtų tave matyti.'),
  (@b26, 28, 18, 'Savo neteisybių daugybe, savo prekybos neteisybe tu suteršei savo šventoves; todėl iš tavo tarpo aš išgausiu ugnį, kuri surys tave, ir visų tave matančių akyse paversiu tave pelenais ant žemės.'),
  (@b26, 28, 19, 'Visi tave pažįstantys tarp tautų bus apstulbę dėl tavęs; tu būsi siaubas ir tavęs nebebus’“.'),
  (@b26, 28, 20, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 28, 21, '„Žmogaus sūnau, nukreipk savo veidą prieš Sidoną ir pranašauk prieš jį,'),
  (@b26, 28, 22, 'ir sakyk: ‘Taip sako Viešpats DIEVAS: Štai aš esu prieš tave, o Sidone; ir aš būsiu pašlovintas tavo tarpe; ir jie žinos, kad aš esu VIEŠPATS, kai būsiu jame įvykdęs teismus ir kai būsiu jame pašvęstas.'),
  (@b26, 28, 23, 'Nes aš pasiųsiu į jį marą bei kraują į jo gatves; ir sužeistieji bus nuteisti jo tarpe kalaviju, esančiu ant jo iš visų pusių; ir jie žinos, kad aš esu VIEŠPATS.'),
  (@b26, 28, 24, 'Ir Izraelio namams nebebus badančio erškėčio nei sukeliančio sielvartą dyglio iš visų jų aplinkinių, kurie juos niekino; ir jie žinos, kad aš esu Viešpats DIEVAS’.'),
  (@b26, 28, 25, 'Taip sako Viešpats DIEVAS: ‘Kai būsiu surinkęs Izraelio namus iš tautų, tarp kurių jie yra išsklaidyti, ir būsiu juose pašvęstas pagonių akyse, tada jie gyvens savo šalyje, kurią daviau savo tarnui Jokūbui.'),
  (@b26, 28, 26, 'Ir jie saugiai joje gyvens, statys namus ir sodins vynuogynus; taip, jie gyvens su pasitikėjimu, kai būsiu įvykdęs teismus visiems jų aplinkiniams, kurie juos niekina; ir jie žinos, kad aš esu VIEŠPATS, jų Dievas’“.'),
  (@b26, 29, 1, 'Dešimtaisiais metais, dešimtąjį mėnesį, dvyliktąją to mėnesio dieną, man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 29, 2, '„Žmogaus sūnau, nukreipk savo veidą prieš Egipto karalių faraoną ir pranašauk prieš jį ir prieš visą Egiptą;'),
  (@b26, 29, 3, 'kalbėk ir sakyk: ‘Taip sako Viešpats DIEVAS: Štai aš esu prieš tave, faraone, Egipto karaliau, didysis slibine, gulintis tarp savo upių ir sakantis: „Mano upė yra mano paties, aš ją sau pasidariau“.'),
  (@b26, 29, 4, 'Bet aš įdėsiu kablius į tavo žiaunas ir tavo upių žuvis prilipinsiu prie tavo žvynų, ir tave ištrauksiu iš tavo upių vidurio, ir visos tavo upių žuvys prilips prie tavo žvynų.'),
  (@b26, 29, 5, 'Ir paliksiu tave numestą į dykumą, tave ir visas tavo upių žuvis; tu nukrisi atvirame lauke; tu nebūsi nei surinktas, nei palaidotas; aš tave atidaviau lauko žvėrims ir dangaus skrajūnams kaip maistą.'),
  (@b26, 29, 6, 'Ir visi Egipto gyventojai žinos, kad aš esu VIEŠPATS, nes jie buvo nendrės ramstis Izraelio namams.'),
  (@b26, 29, 7, 'Kai jie nutvėrė tave už rankos, tu sulūžai ir nuplėšei visą jų petį; ir kai jie atsirėmė į tave, tu sulūžai ir padarei, kad visos jų strėnos sustotų.'),
  (@b26, 29, 8, 'Todėl taip sako Viešpats DIEVAS: Štai aš atvesiu ant tavęs kalaviją ir iškirsiu iš tavęs žmogų ir gyvulį.'),
  (@b26, 29, 9, 'Ir Egipto šalis bus tuščia ir apleista; ir jie žinos, kad aš esu VIEŠPATS; kadangi jis sakė: „Mano yra upė, aš ją padariau“.'),
  (@b26, 29, 10, 'Todėl štai aš esu prieš tave bei prieš tavo upes, ir padarysiu Egipto šalį visiškai tuščią ir apleistą, nuo Sienės bokšto iki Etiopijos ribos.'),
  (@b26, 29, 11, 'Nepereis per ją žmogaus koja, ir gyvulio koja nepereis per ją, ir keturiasdešimt metų ji nebus apgyvendinta.'),
  (@b26, 29, 12, 'Padarysiu Egipto šalį tuščią tarp ištuštėjusių šalių, ir keturiasdešimt metų jos miestai bus tušti tarp apleistų miestų; aš išsklaidysiu egiptiečius tarp tautų ir išvaikysiu juos po šalis’.'),
  (@b26, 29, 13, 'Tačiau taip sako Viešpats DIEVAS: ‘Keturiasdešimčiai metų pasibaigus aš surinksiu egiptiečius iš tautų, po kurias jie buvo išsklaidyti;'),
  (@b26, 29, 14, 'aš sugrąžinsiu Egipto nelaisvę ir sugrąžinsiu juos į Patroso šalį, į jų gyvenamą šalį; ir jie ten bus menka karalystė.'),
  (@b26, 29, 15, 'Ji bus menkiausia iš karalysčių; ir ji nebesiaukštins virš tautų; nes aš juos sumažinsiu, kad jie nebeviešpatautų tautoms.'),
  (@b26, 29, 16, 'Ir ji nebebus Izraelio namų pasitikėjimas, primenantis jų neteisybę, kai jie dairysis paskui juos; bet jie žinos, kad aš esu Viešpats DIEVAS’“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b26, 29, 17, 'Ir dvidešimt septintaisiais metais, pirmąjį mėnesį, pirmąją mėnesio dieną įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 29, 18, '„Žmogaus sūnau, Babilono karalius Nebukadrecaras privertė savo kariuomenę tarnauti sunkia tarnyste prieš Tyrą; kiekviena galva nupliko ir kiekvienas petys nusitrynė; tačiau nei jis, nei jo kariuomenė negavo už Tyrą užmokesčio, už tarnystę, kuria jis prieš jį tarnavo.'),
  (@b26, 29, 19, 'Todėl taip sako Viešpats DIEVAS: Štai aš atiduosiu Babilono karaliui Nebukadrecarui Egipto šalį; jis pasiims jos daugybę ir pasiims jos laimikį, ir pasiims jos grobį; ir tai bus užmokestis jo kariuomenei.'),
  (@b26, 29, 20, 'Jam atidaviau Egipto šalį už jo triūsą, kuriuo jis prieš ją tarnavo, nes jie man dirbo, – sako Viešpats DIEVAS.'),
  (@b26, 29, 21, '– Tą dieną aš padarysiu, kad Izraelio namų ragas apsipumpuruotų ir duosiu tau jų tarpe atverti burną; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 30, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 30, 2, '„Žmogaus sūnau, pranašauk ir sakyk: ‘Taip sako Viešpats DIEVAS: Kaukite: „O vargo diena!“'),
  (@b26, 30, 3, 'Nes arti diena, arti VIEŠPATIES diena, debesuota diena; ji bus pagonių metas.'),
  (@b26, 30, 4, 'Kalavijas užeis ant Egipto, ir didelis skausmas bus Etiopijoje, kai užmuštieji kris Egipte, ir jie pašalins jo daugybę, ir jo pamatai bus sugriauti.'),
  (@b26, 30, 5, 'Etiopija, Libija, Lidija, visos maišytos tautos, Kubas ir šalies žmonės, esantys sąjungoje, kris su jais nuo kalavijo’.'),
  (@b26, 30, 6, 'Taip sako VIEŠPATS: ‘Kris ir Egipto rėmėjai; kris jo galybės išdidumas; nuo Sienės bokšto jie kris jame nuo kalavijo, – sako Viešpats DIEVAS.'),
  (@b26, 30, 7, '– Jie ištuštės tarp tuščių šalių, ir jo miestai bus tarp negyvenamų miestų.'),
  (@b26, 30, 8, 'Ir jie žinos, kad aš esu VIEŠPATS, kai užkursiu Egipte ugnį ir kai visi jo pagalbininkai bus sunaikinti.'),
  (@b26, 30, 9, 'Tą dieną nuo manęs laivais išvyks pasiuntiniai, išgąsdinti nerūpestingus etiopus, ir juos ištiks didelis skausmas, kaip Egipto dieną; nes štai jis ateina’.'),
  (@b26, 30, 10, 'Taip sako Viešpats DIEVAS: ‘Aš padarysiu galą Egipto daugybei Babilono karaliaus Nebukadrecaro ranka.'),
  (@b26, 30, 11, 'Jis ir jo tauta su juo, tautų baisieji, bus atvesti šalies sunaikinti; jie išsitrauks kalavijus prieš Egiptą ir pripildys šalį užmuštųjų.'),
  (@b26, 30, 12, 'Aš išdžiovinsiu upes ir parduosiu šalį į nedorėlių rankas; svetimšalių ranka ištuštinsiu šalį ir viską, kas yra joje; aš, VIEŠPATS, tai kalbėjau’.'),
  (@b26, 30, 13, 'Taip sako Viešpats DIEVAS: ‘Taip pat sunaikinsiu stabus ir padarysiu galą jų atvaizdams Nofe; ir nebebus Egipto šalies kunigaikščio; ir įvarysiu baimę Egipto šalyje.'),
  (@b26, 30, 14, 'Patrosą padarysiu dykyne, uždegsiu ugnį Coane ir įvykdysiu teismus Nojyje.'),
  (@b26, 30, 15, 'Ir išliesiu savo įtūžį ant Sino, Egipto stiprybės; ir iškirsiu Nojo daugybes.'),
  (@b26, 30, 16, 'Ir užkursiu Egipte ugnį; Sinas patirs didžiulį skausmą, Nojas bus suplėšytas, o Nofas bus spaudžiamas kas dieną.'),
  (@b26, 30, 17, 'Aveno ir Pi-Beseto jaunuoliai kris nuo kalavijo; o šitie miestai eis į nelaisvę.'),
  (@b26, 30, 18, 'Tachpanchese aptems diena, kai ten sulaužysiu Egipto jungus; ir jame pasibaigs jo stiprybės pasipūtimas; o jį patį apdengs debesis, ir jo dukterys eis į nelaisvę.'),
  (@b26, 30, 19, 'Taip aš įvykdysiu teismus Egipte; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 30, 20, 'Ir vienuoliktaisiais metais, pirmąjį mėnesį, to mėnesio septintąją dieną įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 30, 21, '„Žmogaus sūnau, aš sulaužiau Egipto karaliaus faraono ranką; ir štai ji nebus aprišta, kad sugytų, kad uždėtų tvarstį jai aprišti, kad ji sustiprėtų kalavijui laikyti.'),
  (@b26, 30, 22, 'Todėl taip sako Viešpats DIEVAS: ‘Štai aš esu prieš faraoną, Egipto karalių, ir sulaužysiu jo rankas, stipriąją ir tą, kuri buvo sulaužyta; ir padarysiu, kad kalavijas iškristų iš jo rankos.'),
  (@b26, 30, 23, 'Ir išsklaidysiu egiptiečius tarp tautų ir išvaikysiu juos po šalis.'),
  (@b26, 30, 24, 'Ir sustiprinsiu Babilono karaliaus rankas ir įdėsiu jam į ranką savo kalaviją; bet sulaužysiu faraono rankas, ir jis dejuos jo akivaizdoje mirtinai sužeistojo dejonėmis.'),
  (@b26, 30, 25, 'Bet aš sustiprinsiu Babilono karaliaus rankas, o faraono rankos nusileis; ir jie žinos, kad aš esu VIEŠPATS, kai įdėsiu savo kalaviją į Babilono karaliaus ranką, ir jis jį išties į Egipto šalį.'),
  (@b26, 30, 26, 'Ir aš išsklaidysiu egiptiečius tarp tautų ir išvaikysiu juos po šalis; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 31, 1, 'Ir vienuoliktaisiais metais, trečiąjį mėnesį, pirmąją to mėnesio dieną įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 31, 2, '„Žmogaus sūnau, sakyk Egipto karaliui faraonui ir jo daugybei: ‘Kam tu prilygsti savo didybe?'),
  (@b26, 31, 3, 'Štai asiras buvo kedras Libane, gražiomis šakomis, skraiste, metančia šešėlį, ir aukšto ūgio; jo viršūnė buvo tarp tankių šakų.'),
  (@b26, 31, 4, 'Vandenys jį užaugino, jį iškėlė gelmės su savo upėmis, tekančiomis aplink jo sodinukus, ir išsiuntė savo upelius į visus lauko medžius.'),
  (@b26, 31, 5, 'Todėl jo aukštis iškilo virš visų lauko medžių, jo šakos daugėjo, jo šakos ilgėjo dėl vandenų daugybės jam beaugant.'),
  (@b26, 31, 6, 'Jo šakose suko lizdus visi dangaus skrajūnai, po jo šakomis visi lauko žvėrys vedė savo jauniklius, ir jo šešėlyje gyveno visos didelės tautos.'),
  (@b26, 31, 7, 'Taip jis buvo gražus savo didumu, savo šakų ilgumu; nes jo šaknys buvo prie didelių vandenų.'),
  (@b26, 31, 8, 'Kedrai Dievo sode negalėjo jo paslėpti; eglės neprilygo jo šakoms, ir kaštonai nebuvo tokie, kaip jo šakos; ir joks medis Dievo sode jam neprilygo savo grožiu.'),
  (@b26, 31, 9, 'Padariau jį gražų daugybe jo šakų; taip, kad jam pavydėjo visi Edeno medžiai, esantys Dievo sode.'),
  (@b26, 31, 10, 'Todėl taip sako Viešpats DIEVAS: Kadangi tu išsikėlei aukščiu, ir išaugo jo viršūnė tarp tankių šakų, ir jo širdis išsiaukštino jo aukštybe;'),
  (@b26, 31, 11, 'todėl jį atidaviau į pagonių galiūno ranką; jis tikrai juo užsiims; aš jį išvariau dėl jo nedorybės.'),
  (@b26, 31, 12, 'Svetimšaliai, tautų baisieji, jį nukirto ir jį paliko; kalnuose ir visuose slėniuose nukritusios jo šakos, ir jo šakos nulaužytos šalia visų šalies upių; ir visos žemės tautos pasitraukė žemyn nuo jo paūksmės ir jį paliko.'),
  (@b26, 31, 13, 'Ant jo griuvėsių pasiliks visi dangaus skrajūnai, ir visi lauko žvėrys bus ant jo šakų;'),
  (@b26, 31, 14, 'tuo tikslu, kad nei vienas iš visų medžių prie vandenų nesiaukštintų dėl savo aukščio, neiškeltų savo viršūnių tarp tankių šakų, ir kad visi jų medžiai, geriantys vandenį, nestovėtų savo aukščiu; nes jie visi atiduoti mirčiai, žemutinėms žemės dalims, žmonių vaikų tarpe, kartu su nužengiančiais į duobę.'),
  (@b26, 31, 15, 'Taip sako Viešpats DIEVAS: Tą dieną, kai jis nužengė į kapą, aš sukėliau gedulą; dėl jo uždengiau gelmes ir sulaikiau jų sroves, ir dideli vandenys buvo sustabdyti; ir padariau, kad dėl jo gedėtų Libanas, ir visi lauko medžiai alpo dėl jo.'),
  (@b26, 31, 16, 'Nuo jo kritimo trenksmo priverčiau drebėti tautas, kai jį nustūmiau į pragarą su nužengiančiais į duobę; ir visi Edeno medžiai, Libano rinktiniai ir geriausi, visi geriantys vandenį, bus paguosti žemutinėse žemės dalyse.'),
  (@b26, 31, 17, 'Jie irgi nužengė su juo į pragarą pas kalaviju nužudytuosius; ir tie, kurie buvo jo ranka, kurie gyveno jo paūksmėje tarp pagonių.'),
  (@b26, 31, 18, 'Kam tu taip prilygsti šlove ir didybe tarp Edeno medžių? Tačiau tu būsi nustumtas žemyn su Edeno medžiais į žemutines žemės dalis; tu gulėsi tarp neapipjaustytųjų kartu su kalaviju nužudytais. Tai faraonas ir visa jo daugybė, – sako Viešpats DIEVAS’“.'),
  (@b26, 32, 1, 'Ir dvyliktaisiais metais, dvyliktąjį mėnesį, to mėnesio pirmąją dieną įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 32, 2, '„Žmogaus sūnau, imkis raudos dėl Egipto karaliaus faraono ir jam sakyk: ‘Tu esi kaip tautų jaunas liūtas ir esi kaip banginis jūrose; tu išėjai su savo upėmis, drumstei savo kojomis vandenis ir suteršei jų upes.'),
  (@b26, 32, 3, 'Taip sako Viešpats DIEVAS: ‘Todėl aš ištiesiu ant tavęs savo tinklą su daugybės tautų minia; ir jie atves tave aukštyn į mano tinklą.'),
  (@b26, 32, 4, 'Tada tave paliksiu ant žemės, numesiu tave ant atviro lauko ir padarysiu, kad visi dangaus skrajūnai pasiliktų ant tavęs, ir pasotinsiu tavimi visos žemės žvėris.'),
  (@b26, 32, 5, 'Išguldysiu tavo mėsą ant kalnų ir pripildysiu slėnius tavo aukščio.'),
  (@b26, 32, 6, 'Taip pat palaistysiu tavo krauju šalį, kurioje tu plaukioji, iki kalnų; ir upės bus pilnos tavęs.'),
  (@b26, 32, 7, 'Tave užgesinęs, aš apdengsiu dangų ir aptemdysiu jo žvaigždes; saulę apdengsiu debesimi, ir mėnulis nebešvies savo šviesa.'),
  (@b26, 32, 8, 'Visas skaisčias dangaus šviesas aptemdysiu virš tavęs ir užleisiu tamsą ant tavo šalies, – sako Viešpats DIEVAS.'),
  (@b26, 32, 9, 'Ir daugelio tautų širdims sukelsiu nerimą, kai atvesiu tavo sunaikinimą į tautų tarpą, į kraštus, kurių nepažinojai.'),
  (@b26, 32, 10, 'Taip, aš padarysiu, kad daugelis tautų nustebs dėl tavęs, ir jų karaliai siaubingai išsigąs dėl tavęs, kai aš mosikuosiu prieš juos savo kalaviju; ir kiekvienu momentu jie drebės, kiekvienas dėl savo gyvybės, tavo griūties dieną’.'),
  (@b26, 32, 11, 'Nes taip sako Viešpats DIEVAS: ‘Babilono karaliaus kalavijas ateis ant tavęs.'),
  (@b26, 32, 12, 'Galiūnų kalavijais priversiu griūti tavo daugybę, tautų baisiuosius, juos visus; jie išplėš Egipto pasipūtimą, ir visa jo daugybė bus sunaikinta.'),
  (@b26, 32, 13, 'Išnaikinsiu ir visus jo gyvulius prie didžiųjų vandenų; jų nebedrums žmogaus koja, nei gyvulio kanopa jų nebedrums.'),
  (@b26, 32, 14, 'Tada aš padarysiu jų vandenis gilius ir padarysiu, kad jų upės tekės kaip aliejus, – sako Viešpats DIEVAS.'),
  (@b26, 32, 15, '– Kai paversiu Egipto šalį dykyne, ir kraštas neteks to, ko jis buvo pilnas, kai sumušiu visus jame gyvenančius, tada jie žinos, kad aš esu VIEŠPATS.'),
  (@b26, 32, 16, 'Tai rauda, kuria jį apraudos; tautų dukterys jį apraudos; jos apraudos jį – Egiptą ir visą jo daugybę, – sako Viešpats DIEVAS’“.'),
  (@b26, 32, 17, 'Taip pat dvyliktaisiais metais, penkioliktąją to mėnesio dieną įvyko, kad man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 32, 18, '„Žmogaus sūnau, apraudok Egipto daugybę ir nustumk juos žemyn, būtent jį ir garsių tautų dukras, į žemutines žemės dalis, su nužengiančiais į duobę.'),
  (@b26, 32, 19, 'Ką tu pralenki grožiu? Nuženk ir atsigulk su neapipjaustytais.'),
  (@b26, 32, 20, 'Jie kris tarp užmuštųjų kalaviju; jis yra atiduotas kalavijui; nutempk jį ir visas jo minias.'),
  (@b26, 32, 21, 'Stiprieji tarp galingųjų jam kalbės iš pragaro su jo pagalbininkais; jie nužengę, jie guli neapipjaustyti, nužudyti kalaviju.'),
  (@b26, 32, 22, 'Ten yra Ašūras ir visas jo būrys; aplink jį yra jo kapai; jie visi užmušti, kritę nuo kalavijo;'),
  (@b26, 32, 23, 'jo kapai pastatyti duobės šonuose, o jo būrys yra aplink jo kapą; jie visi užmušti, kritę nuo kalavijo, kurie kėlė siaubą gyvųjų šalyje.'),
  (@b26, 32, 24, 'Ten yra Elamas ir visa jo minia aplink jo kapą, jie visi užmušti, kritę nuo kalavijo, kurie nužengė neapipjaustyti į žemutines žemės dalis, kurie kėlė dėl jų siaubą gyvųjų šalyje; tačiau jie nešiojo savo gėdą su nužengiančiais į duobę.'),
  (@b26, 32, 25, 'Jam paskyrė guolį tarp užmuštųjų su visa jo minia; jo kapai yra aplink jį; jie visi neapipjaustyti, nužudyti kalaviju; nors nuo jų kilo siaubas gyvųjų šalyje, tačiau jie nešiojo savo gėdą su nužengiančiais į duobę; jis paguldytas tarp užmuštųjų.'),
  (@b26, 32, 26, 'Ten yra Mešechas, Tubalas ir visa jo daugybė; jo kapai yra aplink jį; jie visi neapipjaustyti, nužudyti kalaviju, nors nuo jų kilo siaubas gyvųjų šalyje.'),
  (@b26, 32, 27, 'Ir jie negulės su kritusiais galiūnais iš neapipjaustytųjų, kurie nužengė į pragarą su savo karo ginklais; ir jie pasidėjo savo kalavijus po galvomis, bet jų neteisybės bus ant jų kaulų, nors jie buvo galiūnų siaubas gyvųjų šalyje.'),
  (@b26, 32, 28, 'Taip, tu būsi sulaužytas neapipjaustytųjų tarpe ir gulėsi su nužudytais kalaviju.'),
  (@b26, 32, 29, 'Ten yra Edomas, jo karaliai ir visi jo kunigaikščiai, kurie kartu su savo galybe paguldyti prie nužudytų kalaviju; jie gulės su neapipjaustytaisiais ir su nužengiančiais į duobę.'),
  (@b26, 32, 30, 'Ten yra šiaurės kunigaikščiai, jie visi, ir visi sidoniečiai, nužengę su užmuštaisiais; kartu su savo siaubu jie gėdijasi dėl savo galios; jie neapipjaustyti guli su nužudytais kalaviju ir nešioja savo gėdą su nužengiančiais į duobę.'),
  (@b26, 32, 31, 'Faraonas juos pamatys ir pasiguos visa savo daugybe, būtent faraonas ir visa jo kariuomenė, nužudyti kalaviju, – sako Viešpats DIEVAS.'),
  (@b26, 32, 32, '– Nes aš sukėliau savo siaubą gyvųjų šalyje; ir jis bus paguldytas tarp neapipjaustytųjų su nužudytais kalaviju, būtent faraonas ir visa jo minia, – sako Viešpats DIEVAS“.'),
  (@b26, 33, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 33, 2, '„Žmogaus sūnau, kalbėk savo tautos vaikams ir jiems sakyk: ‘Kai užleisiu ant šalies kalaviją, jei šalies tauta paims iš savo ribų vyrą ir jį paskirs savo sargybiniu;'),
  (@b26, 33, 3, 'jei jis pamatęs ateinantį ant šalies kalaviją, pūs trimitą ir įspės tautą;'),
  (@b26, 33, 4, 'tuomet kas išgirs trimito garsą, bet nepriims įspėjimo, ir jei atėjęs kalavijas jį atimtų, tai jo kraujas bus ant jo paties galvos.'),
  (@b26, 33, 5, 'Jis girdėjo trimito garsą, bet nepriėmė įspėjimo; jo kraujas bus ant jo. Bet kas priima įspėjimą, tas išgelbės savo sielą.'),
  (@b26, 33, 6, 'Bet jei sargybinis, pamatęs ateinantį kalaviją, nepūs trimito, ir tauta nebus įspėta; ir jei atėjęs kalavijas atims kurį iš jų tarpo, tai jis bus paimtas dėl savo neteisybės; tačiau jo kraujo pareikalausiu iš sargybinio rankos.'),
  (@b26, 33, 7, 'Taigi tave, o žmogaus sūnau, pastačiau sargybiniu Izraelio namams; todėl tu girdėsi iš mano burnos žodį, ir juos nuo manęs įspėsi.'),
  (@b26, 33, 8, 'Kai sakysiu nedorėliui: „O nedorėli, tu tikrai mirsi“; jei tu nekalbėsi, kad įspėtum nedorėlį gręžtis nuo savo kelio, tai tas nedorėlis mirs dėl savo neteisybės; tačiau jo kraujo pareikalausiu iš tavo rankos.'),
  (@b26, 33, 9, 'Tačiau jei įspėsi nedorėlį dėl jo kelio, kad gręžtųsi nuo jo; jei jis nenusisuks nuo savo kelio, jis mirs savo neteisybėje; bet tu būsi išgelbėjęs savo sielą’.'),
  (@b26, 33, 10, 'Taigi tu, žmogaus sūnau, sakyk Izraelio namams: ‘Jūs taip kalbate, sakydami: „Jei mūsų nusižengimai ir mūsų nuodėmės yra ant mūsų, ir mes jose nykstame, tai kaip begyvensime?“'),
  (@b26, 33, 11, 'Sakyk jiems: Kaip aš gyvas, – sako Viešpats DIEVAS, – aš nenoriu nedorėlio mirties, bet noriu, kad nedorėlis nusisuktų nuo savo kelio ir gyventų; nusigręžkite, nusigręžkite nuo savo piktų kelių; kodėl gi jūs turėtumėte mirti, o Izraelio namai?’'),
  (@b26, 33, 12, 'Todėl tu, žmogaus sūnau, sakyk savo tautos vaikams: ‘Teisiojo teisumas jo neišgelbės jo nusižengimo dieną; o dėl nedorėlio nedorybės – jis negrius dėl jos tą dieną, kai jis nusisuks nuo savo nedorybės; ir teisusis negalės išlikti gyvas dėl savo teisumo tą dieną, kai jis nusidės.'),
  (@b26, 33, 13, 'Kai sakysiu teisiajam, kad jis tikrai gyvens; ir jei jis, pasitikėdamas savo teisumu, darys neteisybę, tai visas jo teisumas nebus prisimintas; bet dėl savo neteisybės, kurią jis darė, – dėl jos jis mirs.'),
  (@b26, 33, 14, 'Vėlgi, kai sakysiu nedorėliui: „Tu tikrai mirsi“; ir jei jis nusigręš nuo savo nuodėmės ir darys, kas teisėta ir teisinga;'),
  (@b26, 33, 15, 'jei nedorėlis sugrąžins užstatą, atiduos tai, ką buvo pasigrobęs, vaikščios pagal gyvenimo įstatus, nedarydamas neteisybės, – jis tikrai gyvens, jis nemirs.'),
  (@b26, 33, 16, 'Nei apie vieną iš jo padarytų nuodėmių jam nebus užsiminta; jis darė, kas teisėta ir teisinga; jis tikrai gyvens.'),
  (@b26, 33, 17, 'Tačiau tavo tautos vaikai sako: „Viešpaties kelias neteisingas“, kai jų pačių kelias neteisingas.'),
  (@b26, 33, 18, 'Kai teisusis nusigręš nuo savo teisumo ir darys neteisybę, jis dėl to mirs.'),
  (@b26, 33, 19, 'Bet jei nedorėlis nusisuks nuo savo nedorybės ir darys, kas teisėta ir teisinga, jis dėl to gyvens.'),
  (@b26, 33, 20, 'Tačiau jūs sakote: „Viešpaties kelias neteisingas“. O jūs, Izraelio namai, aš jus teisiu, kiekvieną pagal jūsų kelią’“.'),
  (@b26, 33, 21, 'Ir dvyliktaisiais mūsų nelaisvės metais, dešimtąjį mėnesį, to mėnesio penktąją dieną nutiko, kad atvyko pas mane pabėgėlis iš Jeruzalės, sakydamas: „Miestas sutriuškintas“.'),
  (@b26, 33, 22, 'Na, o pabėgėliui dar neatvykus, VIEŠPATIES ranka buvo ant manęs vakare; ir atvėrė mano burną, prieš jam ryte ateinant pas mane; mano burna buvo atverta, ir aš nebebuvau nebylys.'),
  (@b26, 33, 23, 'Tada man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 33, 24, '„Žmogaus sūnau, šitų Izraelio šalies dykynių gyventojai kalba, sakydami: ‘Abraomas buvo vienas, ir jis paveldėjo šalį; o mūsų yra daug; mums šalis duota paveldui’.'),
  (@b26, 33, 25, 'Todėl jiems sakyk: ‘Taip sako Viešpats DIEVAS: Jūs valgote su krauju, keliate savo akis į savo stabus ir praliejate kraują, – argi jūs turėtumėte pasisavinti šalį?'),
  (@b26, 33, 26, 'Jūs remiatės savo kalaviju, darote bjaurystes ir kiekvienas suteršiate savo artimo žmoną; – argi jūs turėtumėte pasisavinti šalį?’'),
  (@b26, 33, 27, 'Taip jiems sakyk: ‘Taip sako Viešpats DIEVAS: Kaip aš gyvas, esantys dykynėse tikrai kris nuo kalavijo, ir esantį atvirame lauke aš atiduosiu žvėrims suėsti, o esantys fortuose ir urvuose mirs nuo maro.'),
  (@b26, 33, 28, 'Nes aš paversiu šalį dykynių dykyne, ir pasibaigs jos stiprybės pasipūtimas; ir Izraelio kalnai bus ištuštėję, kad niekas neis per juos.'),
  (@b26, 33, 29, 'Tada jie žinos, kad aš esu VIEŠPATS, kai būsiu pavertęs šalį dykynių dykyne dėl visų jų bjaurysčių, kurias jie darė’.'),
  (@b26, 33, 30, 'O tu, žmogaus sūnau, – tavo tautos vaikai vis kalbasi prieš tave pasieniuose bei namų tarpduriuose ir kalba vienas kitam, kiekvienas savo broliui, sakydami: ‘Meldžiu, ateikite ir pasiklausykite, koks yra tas žodis, išeinantis iš VIEŠPATIES’.'),
  (@b26, 33, 31, 'Jie ateina pas tave, kaip ateina tauta, ir sėdi priešais tave kaip mano tauta, ir klausosi tavo žodžių, bet jų nevykdo; nes savo burna jie rodo didelę meilę, bet jų širdis eina paskui jų godumą.'),
  (@b26, 33, 32, 'Ir štai tu esi jiems kaip labai graži giesmė to, kuris turi malonų balsą ir moka gerai skambinti instrumentu; nes jie klausosi tavo žodžių, bet jų nevykdo.'),
  (@b26, 33, 33, 'O kai tai įvyks (štai tai įvyks), tada jie žinos, kad tarp jų buvo pranašas“.'),
  (@b26, 34, 1, 'Ir atėjo man VIEŠPATIES žodis, sakydamas:'),
  (@b26, 34, 2, '„Žmogaus sūnau, pranašauk prieš Izraelio ganytojus, pranašauk ir jiems sakyk: ‘Taip Viešpats DIEVAS sako ganytojams: Vargas Izraelio ganytojams, kurie gano save pačius! Argi ganytojai neturėtų ganyti kaimenes?'),
  (@b26, 34, 3, 'Jūs valgote taukus ir apsivelkate vilna, jūs pjaunate nupenėtas; bet neganote kaimenės.'),
  (@b26, 34, 4, 'Ligotų nepastiprinote nei sergančių nepagydėte, nei sulaužytų neaprišote, nei išvaikytų neparvedėte, nei pražuvusių neieškojote; bet jas valdėte smurtu ir žiaurumu.'),
  (@b26, 34, 5, 'Ir jos buvo išsklaidytos, nes nebuvo ganytojo; ir kai jos buvo išsklaidytos, jos tapo maistu visiems lauko žvėrims.'),
  (@b26, 34, 6, 'Mano avys klaidžiojo po visus kalnus ir po visas aukštas kalvas; taip, mano kaimenė buvo išsklaidyta po visą žemės paviršių, ir niekas neieškojo nei nesiteiravo jų.'),
  (@b26, 34, 7, 'Todėl, ganytojai, klausykite VIEŠPATIES žodžio:'),
  (@b26, 34, 8, 'Kaip aš gyvas, – sako Viešpats DIEVAS, – kadangi mano kaimenė tapo grobiu ir kadangi, nesant ganytojo, mano kaimenė tapo maistu visiems lauko žvėrims, ir mano ganytojai neieškojo mano kaimenės, bet ganytojai ganė save pačius, o mano kaimenės neganė;'),
  (@b26, 34, 9, 'todėl, ganytojai, klausykite VIEŠPATIES žodžio:'),
  (@b26, 34, 10, 'Taip sako Viešpats DIEVAS: Štai, tikrai aš esu prieš ganytojus; ir pareikalausiu savo kaimenės iš jų rankos, ir padarysiu, kad jie liausis ganę kaimenę; ir ganytojai nebeganys patys savęs; nes aš išvaduosiu savo kaimenę iš jų nasrų, kad jos nebūtų jiems maistu.'),
  (@b26, 34, 11, 'Nes taip sako Viešpats DIEVAS: Štai aš, būtent aš, ieškosiu savo avių ir jas suieškosiu.'),
  (@b26, 34, 12, 'Kaip ganytojas suieško savo kaimenę tą dieną, kai jis yra tarp savo išsklaidytų avių; taip aš suieškosiu savo avis ir jas išvaduosiu iš visų vietų, po kurias jos buvo išsklaidytos debesuotą ir tamsią dieną.'),
  (@b26, 34, 13, 'Ir jas išvesiu iš tautų, jas surinksiu iš šalių, jas parvesiu į jų šalį ir jas ganysiu Izraelio kalnuose prie upių ir visose krašto gyvenamose vietose.'),
  (@b26, 34, 14, 'Aš jas ganysiu geroje ganykloje, ir jų aptvaras bus aukštuose Izraelio kalnuose; ten jos gulės gerame aptvare, ir jos ganysis riebioje ganykloje Izraelio kalnuose.'),
  (@b26, 34, 15, 'Aš ganysiu savo kaimenę ir jas suguldysiu, – sako Viešpats DIEVAS.'),
  (@b26, 34, 16, '– Pražuvusių ieškosiu, išvaikytas parvesiu, sulaužytas aprišiu ir ligotas sustiprinsiu; bet riebias ir stiprias sunaikinsiu; aš jas ganysiu teismu.'),
  (@b26, 34, 17, 'O dėl jūsų, o mano kaimene, taip sako Viešpats DIEVAS: Štai aš teisiu tarp galvijų ir galvijų, tarp avinų ir ožių.'),
  (@b26, 34, 18, 'Ar jums atrodo per maža suėsti gerą ganyklą, kad mindote kojomis savo ganyklų likutį? Ir ar per maža gerti gilius vandenis, kad suteršiate kojomis tai, kas liko?'),
  (@b26, 34, 19, 'O mano kaimenė maitinasi tuo, ką sumindėte kojomis; ir geria tai, ką suteršėte kojomis.'),
  (@b26, 34, 20, 'Todėl taip jiems sako Viešpats DIEVAS: Štai aš, būtent aš, teisiu tarp riebių galvijų ir liesų galvijų.'),
  (@b26, 34, 21, 'Kadangi jūs šonu ir petimi nustumiate ir savo ragais badote visas ligotas, kol jas išsklaidote laukan;'),
  (@b26, 34, 22, 'todėl aš išgelbėsiu savo kaimenę, ir jos nebebus grobiu; ir teisiu tarp galvijų ir galvijų.'),
  (@b26, 34, 23, 'Ir joms paskirsiu vieną ganytoją, kuris jas ganys – mano tarną Dovydą; jis jas ganys, ir jis bus jų ganytojas.'),
  (@b26, 34, 24, 'Ir aš, VIEŠPATS, būsiu jų Dievas, o mano tarnas Dovydas – kunigaikštis tarp jų; aš, VIEŠPATS, tai pasakiau.'),
  (@b26, 34, 25, 'Ir sudarysiu su jais taikos sandorą ir išnaikinsiu piktus žvėris iš šalies; ir jie saugiai gyvens dykumoje ir miegos miškuose.'),
  (@b26, 34, 26, 'Ir padarysiu juos bei mano kalvos apylinkes palaiminimu; ir duosiu liūčiai lyti jos metu; tai bus palaiminimo liūtys.'),
  (@b26, 34, 27, 'Ir lauko medžiai duos savo vaisius, ir žemė duos savo prieaugį, ir jie bus saugūs savo šalyje, ir žinos, kad aš esu VIEŠPATS, kai būsiu sutraukęs jų jungo raiščius ir juos išvadavęs iš rankų tų, kurie jais apsitarnavo.'),
  (@b26, 34, 28, 'Ir jie nebebus grobiu pagonims, ir šalies žvėrys jų nebeės; bet jie saugiai gyvens, ir niekas jų nebeišgąsdins.'),
  (@b26, 34, 29, 'Ir jiems prikelsiu garbingą sodinį, ir jie nebebus bado sunaikinti šalyje, ir nebenešios pagonių gėdinimo.'),
  (@b26, 34, 30, 'Taip jie žinos, kad aš VIEŠPATS, jų Dievas, esu su jais, o jie, Izraelio namai, yra mano tauta, – sako Viešpats DIEVAS.'),
  (@b26, 34, 31, '– Ir jūs, mano kaimenė, mano ganyklos kaimenė, esate žmonės, o aš esu jūsų Dievas, – sako Viešpats DIEVAS’“.'),
  (@b26, 35, 1, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 35, 2, '„Žmogaus sūnau, nukreipk savo veidą prieš Seyro kalną ir pranašauk prieš jį,'),
  (@b26, 35, 3, 'ir sakyk jam: ‘Taip sako Viešpats DIEVAS: Štai aš esu prieš tave, o Seyro kalne, ir aš ištiesiu savo ranką prieš tave ir paversiu tave visiška dykyne.'),
  (@b26, 35, 4, 'Aš nusiaubsiu tavo miestus, ir tu būsi dykyne, ir žinosi, kad aš VIEŠPATS.'),
  (@b26, 35, 5, 'Kadangi nuolat nekentei ir praliejai Izraelio vaikų kraują kalavijo galia jų nelaimės metu, jų neteisybės pabaigos metu;'),
  (@b26, 35, 6, 'todėl, kaip aš gyvas, – sako Viešpats DIEVAS, – aš paruošiu tave kraujui, ir kraujas persekios tave; kadangi neturėjai neapykantos kraujui, tai kraujas persekios tave.'),
  (@b26, 35, 7, 'Taip aš paversiu Seyro kalną dykynių dykyne ir iš jo iškirsiu išeinantį ir sugrįžtantį.'),
  (@b26, 35, 8, 'Ir pripildysiu jo kalnus jo užmuštųjų; tavo kalvose, tavo slėniuose ir visose tavo upėse kris nužudytieji kalaviju.'),
  (@b26, 35, 9, 'Tave paversiu amžina dykyne, ir tavo miestai nesugrįš; ir žinosite, kad aš VIEŠPATS.'),
  (@b26, 35, 10, 'Kadangi sakei: „Šios dvi tautos ir šios dvi šalys bus mano, ir mes jas pasisavinsime“, nors ten buvo VIEŠPATS;'),
  (@b26, 35, 11, 'todėl, kaip aš gyvas, – sako Viešpats DIEVAS, – aš pasielgsiu pagal tavo pyktį ir pagal tavo pavydą, kuriuos išreiškei iš neapykantos jiems; ir pasidarysiu tarp jų žinomas, kai tave būsiu nuteisęs.'),
  (@b26, 35, 12, 'Ir žinosi, kad aš – VIEŠPATS ir kad girdėjau visus tavo piktžodžiavimus, kuriuos ištarei prieš Izraelio kalnus, sakydamas: „Jie ištuštėję, jie mums duoti kad prarytume“.'),
  (@b26, 35, 13, 'Taip savo burna jūs didžiavotės prieš mane ir dauginote prieš mane savo žodžius; aš juos girdėjau’.'),
  (@b26, 35, 14, 'Taip sako Viešpats DIEVAS: ‘Kai visa žemė džiaugsis, aš padarysiu tave dykyne.'),
  (@b26, 35, 15, 'Kaip tu džiaugeisi Izraelio namų nuosavybe, kad ji buvo tuščia, taip aš tau padarysiu; tu būsi dykynė, o Seyro kalne ir visa Idumėja, būtent visa; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 36, 1, '„Žmogaus sūnau, pranašauk ir Izraelio kalnams ir sakyk: ‘Izraelio kalnai, klausykite VIEŠPATIES žodžio:'),
  (@b26, 36, 2, 'taip sako Viešpats DIEVAS: Kadangi priešas sakė prieš jus: „Aha! Senovinės aukštumos yra mūsų nuosavybė“,'),
  (@b26, 36, 3, 'todėl pranašauk ir sakyk: Taip sako Viešpats DIEVAS: Kadangi jie jus nusiaubė ir jus rijo iš visų pusių, kad būtumėte nuosavybe likusiems pagonims, ir patekote į kalbėtojų lūpas, ir esate žmonių negarbė;'),
  (@b26, 36, 4, 'todėl, Izraelio kalnai, klausykite Viešpaties DIEVO žodžio: Taip sako Viešpats DIEVAS kalnams, kalvoms, upėms, slėniams, negyvenamoms dykvietėms ir paliktiems miestams, kurie tapo grobiu ir pajuoka likusiems aplinkiniams pagonims;'),
  (@b26, 36, 5, 'taigi taip sako Viešpats DIEVAS: Iš tiesų savo ugningu pavydu kalbėjau prieš likusius pagonis ir prieš visą Idumėją, kurie paskyrė mano šalį savo nuosavybėn, džiaugdamiesi iš visos širdies, su gilia neapykanta, kad ją išmestų grobiui’.'),
  (@b26, 36, 6, 'Todėl pranašauk apie Izraelio šalį ir sakyk kalnams bei kalvoms, upėms ir slėniams: ‘Taip sako Viešpats DIEVAS: Štai aš kalbėjau savo pavyde ir savo įniršyje, kadangi nešiojote pagonių gėdą;'),
  (@b26, 36, 7, 'todėl taip sako Viešpats DIEVAS: Aš pakėliau savo ranką: iš tiesų jūsų aplinkiniai pagonys nešios savo gėdą.'),
  (@b26, 36, 8, 'Bet jūs, Izraelio kalnai, išleisite savo šakas ir duosite savo vaisius mano tautai Izraeliui; nes jų parėjimas čia pat.'),
  (@b26, 36, 9, 'Nes štai aš esu už jus ir atsigręžiu į jus, ir jūs būsite ariami ir sėjami;'),
  (@b26, 36, 10, 'ir padauginsiu tarp jūsų žmones, visus Izraelio namus, visus; ir miestai bus apgyventi ir tyrlaukiai apstatyti;'),
  (@b26, 36, 11, 'ir padauginsiu jumyse žmones ir gyvulius; ir jie daugės ir neš vaisių; aš jus apgyvendinsiu, kaip jūsų ankstesnėje padėtyje, ir jums darysiu geriau negu jūsų pradžioje; ir žinosite, kad aš VIEŠPATS.'),
  (@b26, 36, 12, 'Taip, padarysiu, kad jumyse vaikščios žmonės – mano tauta Izraelis; ir jie pasisavins tave, ir tu būsi jų paveldas ir nuo tada nebeatimsi jiems žmonių’.'),
  (@b26, 36, 13, 'Taip sako Viešpats DIEVAS: ‘Kadangi tau sako: „Tu, šalie, ryji žmones ir atėmei savo tautų vaikus“;'),
  (@b26, 36, 14, 'todėl neberysi žmonių ir nebeatimsi vaikų savo tautoms, – sako Viešpats DIEVAS.'),
  (@b26, 36, 15, '– Ir nebedarysiu, kad tavyje žmonės girdėtų pagonių gėdą, ir tu nebenešiosi tautų priekaištų ir nebepargriausi savo tautų, – sako Viešpats DIEVAS’“.'),
  (@b26, 36, 16, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 36, 17, '„Žmogaus sūnau, Izraelio namai, gyvendami savo šalyje, suteršė ją savo pačių keliu ir savo darbais; jų kelias mano akivaizdoje buvo kaip atsiskyrusios moters nešvarumas.'),
  (@b26, 36, 18, 'Todėl išliejau ant jų savo įtūžį dėl kraujo, kurį jie buvo pralieję šalyje, ir dėl jų stabų, kuriais ją buvo suteršę;'),
  (@b26, 36, 19, 'ir juos išsklaidžiau tarp pagonių, ir jie buvo išvaikyti po šalis; aš juos teisiau pagal jų kelią ir pagal jų darbus.'),
  (@b26, 36, 20, 'Ir įėję pas pagonis, kur jie ėjo, jie suteršė mano šventąjį vardą, kai jiems sakė: ‘Šitie yra VIEŠPATIES tauta ir yra išėję iš jo šalies’.'),
  (@b26, 36, 21, 'Bet aš gailėjausi dėl savo šventojo vardo, kurį Izraelio namai buvo suteršę tarp pagonių, kur jie ėjo.'),
  (@b26, 36, 22, 'Todėl sakyk Izraelio namams: ‘Taip sako Viešpats DIEVAS: Aš tai darau ne dėl jūsų, o Izraelio namai, bet dėl savo šventojo vardo, kurį suteršėte tarp pagonių, kur ėjote.'),
  (@b26, 36, 23, 'Ir aš pašvęsiu savo didįjį, tarp pagonių suterštą, vardą, kurį suteršėte tarp jų; ir pagonys žinos, kad aš esu VIEŠPATS, – sako Viešpats DIEVAS, – kai jų akyse būsiu pašvęstas jumyse.'),
  (@b26, 36, 24, 'Nes aš jus paimsiu iš pagonių tarpo ir surinksiu jus iš visų kraštų, ir parvesiu jus į jūsų šalį.'),
  (@b26, 36, 25, 'Tada apšlakstysiu jus švariu vandeniu, ir būsite švarūs; apvalysiu jus nuo visų jūsų nešvarumų ir nuo visų jūsų stabų.'),
  (@b26, 36, 26, 'Taip pat jums duosiu naują širdį ir įdėsiu naują dvasią į jūsų vidų; ir pašalinsiu iš jūsų kūno akmeninę širdį, ir jums duosiu kūno širdį.'),
  (@b26, 36, 27, 'Savo Dvasią įdėsiu į jūsų vidų ir padarysiu, kad vaikščiotumėte pagal mano įstatus, ir jūs laikysitės mano teismų ir juos vykdysite.'),
  (@b26, 36, 28, 'Ir gyvensite šalyje, kurią daviau jūsų tėvams; ir jūs būsite mano tauta, o aš būsiu jūsų Dievas.'),
  (@b26, 36, 29, 'Taip pat išgelbėsiu jus nuo visų jūsų nešvarumų; ir pašauksiu javus, juos padauginsiu ir nebeužleisiu ant jūsų bado.'),
  (@b26, 36, 30, 'Padauginsiu medžių vaisius ir lauko prieaugį, kad nebegautumėte priekaištų dėl bado tarp pagonių.'),
  (@b26, 36, 31, 'Tada atsiminsite savo piktus kelius bei savo negerus darbus, ir savo akyse bjaurėsitės savimi dėl savo neteisybių ir dėl savo bjaurysčių.'),
  (@b26, 36, 32, 'Ne dėl jūsų aš tai darau, – sako Viešpats DIEVAS, – tebūna jums tai žinoma; gėdykitės ir būkite susigėdę dėl savo kelių, o Izraelio namai’.'),
  (@b26, 36, 33, 'Taip sako Viešpats DIEVAS: ‘Tą dieną, kai būsiu jus apvalęs nuo visų jūsų neteisybių, aš jus apgyvendinsiu miestuose, ir dykvietės bus apstatytos.'),
  (@b26, 36, 34, 'Ir apleista šalis bus dirbama, kuri gulėjo apleista kiekvieno praeivio akyse.'),
  (@b26, 36, 35, 'Ir sakys: „Ši apleista šalis pasidarė kaip Edeno sodas; ir apleisti, nusiaubti ir sugriauti miestai tapo aptverti ir apgyvendinti“.'),
  (@b26, 36, 36, 'Tada pagonys, išlikę aplink jus, žinos, kad aš, VIEŠPATS, atstatau tai, kas sugriauta, ir apsodinu tai, kas buvo apleista; aš, VIEŠPATS, tai pasakiau ir tai įvykdysiu’.'),
  (@b26, 36, 37, 'Taip sako Viešpats DIEVAS: ‘Aš dėl šito dar leisiuosi Izraelio namų prašomas, kad jiems tai padaryčiau: aš juos padauginsiu žmonėmis kaip kaimenę.'),
  (@b26, 36, 38, 'Kaip šventa kaimenė, kaip Jeruzalės kaimenė jos iškilmingose šventėse, taip negyvenami miestai bus pripildyti žmonių kaimenėmis; ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 37, 1, 'VIEŠPATIES ranka buvo ant manęs, ir nusinešė mane VIEŠPATIES Dvasioje, ir pastatė mane viduryje slėnio, kuris buvo pilnas kaulų,'),
  (@b26, 37, 2, 'ir vedžiojo mane aplinkui pro juos; ir štai jų buvo labai daug atvirame slėnyje; ir štai jie buvo labai sudžiūvę.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b26, 37, 3, 'Ir jis man tarė: „Žmogaus sūnau, ar gali šitie kaulai gyventi?“ Ir aš atsakiau: „O Viešpatie DIEVE, tu žinai“.'),
  (@b26, 37, 4, 'Jis man vėl tarė: „Pranašauk šitiems kaulams ir jiems sakyk: ‘O, sudžiūvę kaulai, klausykite VIEŠPATIES žodžio’.'),
  (@b26, 37, 5, 'Taip sako Viešpats DIEVAS šitiems kaulams: ‘Štai aš įvesiu į jus kvapą ir jūs gyvensite;'),
  (@b26, 37, 6, 'ir apdėsiu jus sausgyslėmis, užauginsiu ant jūsų mėsą, apdengsiu jus oda, įdėsiu į jus kvapą, ir jūs gyvensite; ir žinosite, kad aš esu VIEŠPATS’“.'),
  (@b26, 37, 7, 'Taigi aš pranašavau, kaip man buvo įsakyta; ir man pranašaujant radosi triukšmas, ir štai kratėsi ir susiėjo kaulai, kaulas prie savo kaulo.'),
  (@b26, 37, 8, 'Ir man bežiūrint, štai ant jų užaugo sausgyslės ir mėsa, ir oda apdengė juos iš viršaus; bet juose nebuvo kvapo.'),
  (@b26, 37, 9, 'Tada jis man tarė: „Pranašauk vėjui, pranašauk, žmogaus sūnau, ir sakyk vėjui: ‘Taip sako Viešpats DIEVAS: Ateik nuo keturių vėjų, o kvape, ir kvėpk į šituos užmuštuosius, kad jie gyventų’“.'),
  (@b26, 37, 10, 'Taigi pranašavau, kaip jis man įsakė, ir kvapas įėjo į juos, ir jie atgijo, ir atsistojo ant kojų be galo didelė kariuomenė.'),
  (@b26, 37, 11, 'Tada jis man tarė: „Žmogaus sūnau, šitie kaulai yra visi Izraelio namai; štai jie sako: ‘Mūsų kaulai sudžiūvę ir pražuvusi mūsų viltis; esame atkirsti dėl mūsų dalių’.'),
  (@b26, 37, 12, 'Todėl pranašauk ir sakyk jiems: ‘Taip sako Viešpats DIEVAS: O mano tauta, štai aš atversiu jūsų kapus, išvesiu jus aukštyn iš jūsų kapų ir atvesiu jus į Izraelio šalį.'),
  (@b26, 37, 13, 'Ir žinosite, kad aš esu VIEŠPATS, kai būsiu atvėręs jūsų kapus, o mano tauta, ir išvedęs jus aukštyn iš jūsų kapų,'),
  (@b26, 37, 14, 'ir įdėsiu į jus savo Dvasią, ir jūs gyvensite, ir jus patalpinsiu jūsų šalyje; tada žinosite, kad aš, VIEŠPATS, tai pasakiau ir tai įvykdžiau, – sako VIEŠPATS’“.'),
  (@b26, 37, 15, 'Man vėl atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 37, 16, '„Be to, žmogaus sūnau, pasiimk vieną pagalį ir ant jo užrašyk: ‘Judai ir Izraelio vaikams – jos draugams’; paskui paimk kitą pagalį ir ant jo užrašyk: ‘Juozapui, Efraimo pagaliui, ir visiems Izraelio namams – jo draugams’;'),
  (@b26, 37, 17, 'ir sujunk juos vieną su kitu į vieną pagalį; ir jie taps viena tavo rankoje.'),
  (@b26, 37, 18, 'O kai tavo tautos vaikai tau kalbės, sakydami: ‘Argi mums nepaaiškinsi, ką šitais turi omenyje?‘'),
  (@b26, 37, 19, 'Jiems kalbėk: ‘Taip sako Viešpats DIEVAS: Štai aš paimsiu Juozapo lazdą, esančią Efraimo rankoje, ir Izraelio gentis, jo bendrininkes, ir juos pridėsiu prie jos – prie Judos lazdos, ir padarysiu juos viena lazda, ir jie bus viena mano rankoje’.'),
  (@b26, 37, 20, 'Ir lazdos, ant kurių užrašysi, bus tavo rankoje jiems prieš akis.'),
  (@b26, 37, 21, 'Ir jiems sakyk: ‘Taip sako Viešpats DIEVAS: Štai aš paimsiu Izraelio vaikus iš pagonių tarpo, kur jie buvo nuėję, surinksiu juos iš visų pusių ir parvesiu juos į jų šalį;'),
  (@b26, 37, 22, 'ir padarysiu juos viena tauta toje šalyje, Izraelio kalnuose; ir vienas karalius bus jiems visiems karalius; ir jie nebebus dvi tautos ir jie nebebus pasidaliję į dvi karalystes;'),
  (@b26, 37, 23, 'ir jie nebesusiterš nei savo stabais, nei savo bjaurystėmis, nei jokiais savo nusižengimais; bet aš juos išgelbėsiu iš visų jų gyvenamų vietų, kuriose jie nuodėmiavo, ir apvalysiu juos; taip jie bus mano tauta, o aš būsiu jų Dievas.'),
  (@b26, 37, 24, 'Ir mano tarnas Dovydas bus jiems karalius; ir jie visi turės vieną ganytoją; taipogi jie vaikščios pagal mano teismus, laikysis mano įstatų ir juos vykdys.'),
  (@b26, 37, 25, 'Ir jie gyvens šalyje, kurią daviau savo tarnui Jokūbui, kurioje gyveno jūsų tėvai; ir jie joje gyvens – jie, jų vaikai ir jų vaikų vaikai per amžius; o mano tarnas Dovydas bus jų kunigaikštis per amžius.'),
  (@b26, 37, 26, 'Be to, sudarysiu su jais taikos sandorą; ji bus amžina sandora su jais; aš juos įkurdinsiu, juos padauginsiu ir amžiams pastatysiu tarp jų savo šventovę.'),
  (@b26, 37, 27, 'Taipogi mano padangtė bus pas juos; taip, aš būsiu jų Dievas, o jie bus mano tauta.'),
  (@b26, 37, 28, 'Ir pagonys žinos, kad aš, VIEŠPATS, pašvenčiu Izraelį, kai mano šventovė bus amžinai tarp jų’“.'),
  (@b26, 38, 1, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b26, 38, 2, '„Žmogaus sūnau, nukreipk savo veidą prieš Gogą, Magogo šalį, vyriausiąjį Mešecho ir Tubalo kunigaikštį, ir pranašauk prieš jį,'),
  (@b26, 38, 3, 'ir sakyk: ‘Taip sako Viešpats DIEVAS: Štai aš prieš tave, o Gogai, vyriausiasis Mešecho ir Tubalo kunigaikšti;'),
  (@b26, 38, 4, 'aš tave apgręšiu, įdėsiu kablius į tavo nasrus ir išvesiu tave bei visą tavo kariuomenę, žirgus ir raitelius, visus apsirengusius visokiais ginklais, būtent didžiulį būrį su didžiaisiais ir mažaisiais skydais, visus valdančius kalaviją;'),
  (@b26, 38, 5, 'Persija, Etiopija ir Libija su jais; jie visi su skydais ir šalmais;'),
  (@b26, 38, 6, 'Gomeras ir visi jo pulkai; Togarmos namai iš šiaurės pusės ir visi jos pulkai; daug tautų su tavimi.'),
  (@b26, 38, 7, 'Būk pasiruošęs ir paruošk sau, tu ir visas tavo būrys, susirinkęs pas tave, ir būk jiems sargas.'),
  (@b26, 38, 8, 'Po daugelio dienų būsi aplankytas; paskutiniais metais ateisi į šalį, sugrąžintą nuo kalavijo ir surinktą iš daugelio tautų, priešais Izraelio kalnus, kurie visuomet buvo apleisti; bet yra išvesta iš tautų, ir jie visi saugiai gyvens.'),
  (@b26, 38, 9, 'Tu pakilsi ir ateisi kaip audra, tu būsi kaip debesis, šaliai apdengti, tu bei visi tavo pulkai ir daug tautų su tavimi’.'),
  (@b26, 38, 10, 'Taip sako Viešpats DIEVAS: ‘Atsitiks, kad tuo pačiu laiku tau į širdį ateis minčių, ir tu sumanysi piktą sumanymą;'),
  (@b26, 38, 11, 'ir sakysi: „Eisiu aukštyn į besienių gyvenviečių šalį; eisiu pas esančius ramybėje, saugiai gyvenančius, visus gyvenančius be sienų ir neturinčius nei skląsčių, nei vartų“,'),
  (@b26, 38, 12, 'kad prisiplėštum išplėšų ir prisigrobtum grobio; kad nukreiptum savo ranką į naujai apgyventas dykvietes ir į tautą, surinktą iš tautų, įsigijusią galvijų ir turto, gyvenančią šalies viduryje.'),
  (@b26, 38, 13, 'Šeba, Dedanas, Taršišo prekiautojai su visais jaunais jų liūtais tau sakys: „Ar atėjai išplėšų prisiplėšti? Ar surinkai savo būrį grobio grobti, išsinešti sidabro ir aukso, atimti galvijų ir turto, prisiplėšti daug išplėšų?“’'),
  (@b26, 38, 14, 'Todėl, žmogaus sūnau, pranašauk ir tark Gogui: ‘Taip sako Viešpats DIEVAS: Tą dieną, kai mano tauta Izraelis saugiai gyvens, argi to nežinosi?'),
  (@b26, 38, 15, 'Ir ateisi iš savo vietos, iš šiaurės vietovių, tu ir daug tautų su tavimi, jie visi jojantys ant žirgų, didelis būrys ir galinga kariuomenė;'),
  (@b26, 38, 16, 'ir tu ateisi aukštyn prieš mano tautą Izraelį kaip debesis šalies apdengti; tai bus paskutinėmis dienomis; ir aš tave atvesiu prieš mano šalį, kad pagonys mane pažintų, kai prieš jų akis būsiu pašvęstas tavyje, o Gogai’.'),
  (@b26, 38, 17, 'Taip sako Viešpats DIEVAS: ‘Ar tu esi tas, apie kurį kalbėjau senais laikais per savo tarnus, Izraelio pranašus, daug metų pranašavusius anomis dienomis, kad tave atvesiu prieš juos?'),
  (@b26, 38, 18, 'Ir tuo pačiu metu, kai Gogas ateis prieš Izraelio šalį, – sako Viešpats DIEVAS, – atsitiks, kad mano veide pakils mano įtūžis.'),
  (@b26, 38, 19, 'Nes savo pavyde ir savo rūstybės ugnyje aš kalbėjau: Tikrai tą dieną bus didelis drebėjimas Izraelio šalyje;'),
  (@b26, 38, 20, 'taip, kad jūros žuvys, dangaus skrajūnai, lauko žvėrys, visi žeme ropojantys ropliai, ir visi žmonės, esantys žemės paviršiuje, drebės mano akivaizdoje, ir bus nuversti kalnai, grius stačios vietovės, ir visos sienos grius ant žemės.'),
  (@b26, 38, 21, 'Ir pašauksiu prieš jį kalaviją visuose savo kalnuose, – sako Viešpats DIEVAS; – kiekvieno kalavijas bus prieš savo brolį.'),
  (@b26, 38, 22, 'Ir bylinėsiuosi prieš jį maru ir krauju; ir lysiu užliejančiu lietumi, didele kruša, ugnimi ir siera ant jo, ant jo pulkų ir ant daugybės su juo esančių tautų.'),
  (@b26, 38, 23, 'Taip aš save išaukštinsiu bei save pašvęsiu; ir būsiu žinomas daugelio tautų akyse, ir jie žinos, kad aš esu VIEŠPATS’“.'),
  (@b26, 39, 1, '„Todėl tu, žmogaus sūnau, pranašauk prieš Gogą ir sakyk: ‘Taip sako Viešpats DIEVAS: Štai aš prieš tave, o Gogai, vyriausiasis Mešecho ir Tubalo kunigaikšti;'),
  (@b26, 39, 2, 'aš apgręšiu tave, paliksiu tavo šeštąją dalį, atvesiu tave aukštyn iš šiaurės vietovių ir atvesiu tave ant Izraelio kalnų;'),
  (@b26, 39, 3, 'aš išmušiu tavo lanką iš tavo kairės rankos ir padarysiu, kad iškristų tavo strėlės iš tavo dešinės rankos.'),
  (@b26, 39, 4, 'Izraelio kalnuose krisi tu bei visi tavo pulkai ir tautos, esančios su tavimi; aš atiduosiu tave suėsti visokiems plėšriems paukščiams ir lauko žvėrims.'),
  (@b26, 39, 5, 'Tu krisi atvirame lauke; nes aš tai pasakiau, – sako Viešpats DIEVAS.'),
  (@b26, 39, 6, '– Aš pasiųsiu ugnį ant Magogo ir tarp tų, kurie nerūpestingai gyvena salose; ir jie žinos, kad aš esu VIEŠPATS.'),
  (@b26, 39, 7, 'Taip padarysiu savo šventąjį vardą žinomą savo tautos Izraelio tarpe; ir nebeleisiu jiems suteršti mano šventojo vardo; ir pagonys žinos, kad aš esu VIEŠPATS, Šventasis Izraelyje.'),
  (@b26, 39, 8, 'Štai tai ateina ir įvyks, – sako Viešpats DIEVAS, – tai yra diena, apie kurią kalbėjau.'),
  (@b26, 39, 9, 'Ir Izraelio miestuose gyvenantys išeis ir padegs bei degins ginklus, mažuosius ir didžiuosius skydus, lankus ir strėles, vėzdus bei ietis, ir degins juos ugnimi septynerius metus;'),
  (@b26, 39, 10, 'taip, kad jie neims nuo lauko medžių ir nekirs nei vieno iš miškų; nes jie degins ginklus ugnimi; jie apiplėš tuos, kurie juos apiplėšė, ir apgrobs tuos, kurie juos apgrobė, – sako Viešpats DIEVAS.'),
  (@b26, 39, 11, '– Ir tą dieną atsitiks, kad duosiu Gogui kapų vietą Izraelyje, keliautojų slėnį, į rytus nuo jūros; ir šis užkimš keliautojų nosis; ir ten jie palaidos Gogą ir visą jo daugybę; ir jį pavadins Hamon-Gogo slėniu.'),
  (@b26, 39, 12, 'Ir Izraelio namai juos laidos septynis mėnesius, kad apvalytų šalį.'),
  (@b26, 39, 13, 'Taip, visa šalies tauta juos laidos; ir jiems bus pagarsėjimas ta diena, kai aš būsiu pašlovintas, – sako Viešpats DIEVAS.'),
  (@b26, 39, 14, '– Ir jie atskirs nuolat užimtus žmones, pereinančius per šalį, kad su keliautojais laidotų likusius žemės paviršiuje, kad ją apvalytų; pasibaigus septyniems mėnesiams, jie perieškos.'),
  (@b26, 39, 15, 'Ir kai keliautojas, pereinantis per šalį, pamatys žmogaus kaulą, tada jis pastatys šalia jo ženklą, kol duobkasiai jį palaidos Hamon-Gogo slėnyje.'),
  (@b26, 39, 16, 'Taip pat ir miesto vardas bus Hamona. Taip jie apvalys šalį’.'),
  (@b26, 39, 17, 'O tu, žmogaus sūnau, taip sako Viešpats DIEVAS: ‘Sakyk visiems sparnuotiems skrajūnams ir visiems lauko žvėrims: Susirinkite ir ateikite; susieikite iš visų pusių prie mano aukos, kurią aš jums aukoju – didžiulės aukos Izraelio kalnuose, kad ėstumėte mėsą ir gertumėte kraują.'),
  (@b26, 39, 18, 'Jūs ėsite galiūnų mėsą ir gersite žemės kunigaikščių kraują, avinų, ėriukų ir ožių, jaučių – visų Bašano peniukšlių.'),
  (@b26, 39, 19, 'Jūs ėsite taukų kol pasisotinsite ir gersite kraujo kol prisigersite iš mano aukos, kurią jums aukojau.'),
  (@b26, 39, 20, 'Taip jūs pasisotinsite prie mano stalo žirgais ir vežimais, galiūnais ir visais karo vyrais, – sako Viešpats DIEVAS.'),
  (@b26, 39, 21, '– Ir aš iškelsiu savo šlovę tarp pagonių, ir visi pagonys matys mano teismą, kurį būsiu įvykdęs, ir mano ranką, kurią būsiu ant jų uždėjęs.'),
  (@b26, 39, 22, 'Nuo tos dienos ir toliau Izraelio namai žinos, kad aš esu VIEŠPATS, jų Dievas.'),
  (@b26, 39, 23, 'Ir pagonys žinos, kad Izraelio namai išėjo nelaisvėn dėl savo neteisybės; kadangi jie nusižengė prieš mane, aš paslėpiau nuo jų savo veidą ir juos padaviau į jų priešų rankas; taip jie visi krito nuo kalavijo.'),
  (@b26, 39, 24, 'Aš jiems tai padariau pagal jų nešvarumą bei pagal jų nusižengimus ir paslėpiau nuo jų savo veidą’.'),
  (@b26, 39, 25, 'Todėl taip sako Viešpats DIEVAS: ‘Dabar sugrąžinsiu Jokūbo nelaisvę, pasigailėsiu visų Izraelio namų ir būsiu pavydus dėl savo šventojo vardo;'),
  (@b26, 39, 26, 'kai jie bus panešioję savo gėdą ir visus savo nusižengimus, kuriais jie nusižengė prieš mane, kai jie bus saugiai apsigyvenę savo šalyje, ir niekas jų negąsdins.'),
  (@b26, 39, 27, 'Kai būsiu sugrąžinęs juos iš tautų, surinkęs juos iš jų priešų šalių ir juose būsiu pašvęstas daugelio tautų akyse;'),
  (@b26, 39, 28, 'tada jie žinos, kad aš esu VIEŠPATS, jų Dievas, kuris buvau juos išvedęs į nelaisvę tarp pagonių; bet juos surinkau į jų pačių šalį ir nei vieno iš jų ten nebepalikau.'),
  (@b26, 39, 29, 'Ir nebeslėpsiu nuo jų savo veido; nes aš išliejau savo Dvasią ant Izraelio namų, – sako Viešpats DIEVAS’“.'),
  (@b26, 40, 1, 'Dvidešimt penktaisiais mūsų nelaisvės metais, metų pradžioje, dešimtąją mėnesio dieną, keturioliktaisiais metais po to, kai miestas buvo sutriuškintas, tą pačią dieną VIEŠPATIES ranka buvo ant manęs ir mane ten nuvedė.'),
  (@b26, 40, 2, 'Dievo regėjimuose jis mane nuvedė į Izraelio šalį ir pastatė mane ant labai aukšto kalno, prie kurio, pietų pusėje, buvo tarsi miesto rėmai.'),
  (@b26, 40, 3, 'Jis nuvedė mane ten, ir štai ten buvo vyras, kurio išvaizda buvo kaip žalvario išvaizda, jo rankoje buvo lininė virvė ir matavimo nendrė; ir jis stovėjo vartuose.'),
  (@b26, 40, 4, 'Ir tas vyras man tarė: „Žmogaus sūnau, žiūrėk savo akimis ir klausyk savo ausimis, ir nukreipk savo širdį į viską, ką aš tau parodysiu; nes esi čia atvestas tam, kad tau tai parodyčiau; viską, ką matysi, paskelbk Izraelio namams“.'),
  (@b26, 40, 5, 'Ir štai aplinkui namus iš lauko buvo siena, ir vyro rankoje matavimo nendrė šešių uolekčių pagal uolektį ir plaštakos plotį; taigi jis išmatavo pastato plotį viena nendre ir aukštį viena nendre.'),
  (@b26, 40, 6, 'Paskui jis atėjo prie vartų, nukreiptų į rytus, ir užlipo jų laiptais, ir išmatavo vartų slenkstį, kuris buvo vienos nendrės pločio, ir kitą vartų slenkstį, kuris buvo vienos nendrės pločio.'),
  (@b26, 40, 7, 'Kiekvienas mažas kambarys buvo vienos nendrės ilgio ir vienos nendrės pločio; ir tarp mažų kambarių buvo penkios uolektys; o vartų slenkstis prie vartų prieangio iš vidaus buvo viena nendrė.'),
  (@b26, 40, 8, 'Jis išmatavo ir vartų prieangį iš vidaus viena nendre.'),
  (@b26, 40, 9, 'Tada jis išmatavo vartų prieangį aštuoniomis uolektimis ir jo stulpus dviejomis uolektimis; o vartų prieangis buvo vidinėje pusėje.'),
  (@b26, 40, 10, 'Rytinių vartų mažųjų kambarių buvo trys šioje pusėje ir trys anoje pusėje; tie trys buvo vienodo išmatavimo; ir stulpai šioje pusėje ir anoje pusėje buvo vienodo išmatavimo.'),
  (@b26, 40, 11, 'Ir jis išmatavo vartų įėjimo plotį dešimčia uolekčių, o vartų ilgį – trylika uolekčių.'),
  (@b26, 40, 12, 'Prieš mažuosius kambarius buvo vienos uolekties tarpas šioje pusėje ir vienos uolekties tarpas kitoje pusėje; ir kambarėliai buvo šešių uolekčių šioje pusėje ir šešių uolekčių anapus.'),
  (@b26, 40, 13, 'Po to jis išmatavo vartus nuo vieno kambarėlio stogo iki kito kambarėlio stogo; plotis buvo dvidešimt penkios uolektys, durims esant priešais duris.'),
  (@b26, 40, 14, 'Jis padarė ir šešiasdešimties uolekčių stulpus iki kiemo stulpo, aplinkui vartus.'),
  (@b26, 40, 15, 'O nuo įėjimo vartų priekio iki vidinių vartų prieangio priekio buvo penkiasdešimt uolekčių.'),
  (@b26, 40, 16, 'Kambarėliams, jų statramsčiams vidinėje vartų pusėje aplinkui ir taip pat arkoms buvo siauri langai; langai buvo aplinkui iš vidaus; ir ant kiekvieno statramsčio buvo palmės.'),
  (@b26, 40, 17, 'Paskui jis mane nuvedė į išorinį kiemą, ir štai ten buvo kambariai, ir kiemui aplinkui padarytas grindinys; trisdešimt kambarių buvo ant grindinio.'),
  (@b26, 40, 18, 'Grindinys prie vartų šono, išilgai vartų, buvo žemutinis grindinys.'),
  (@b26, 40, 19, 'Po to jis išmatavo plotį nuo žemutinių vartų priekio iki vidinio kiemo priekio išorės – šimtas uolekčių į rytus ir į šiaurę.'),
  (@b26, 40, 20, 'Ir jis išmatavo ilgį ir plotį išorinio kiemo vartų, nukreiptų į šiaurę.'),
  (@b26, 40, 21, 'Jų kambarėlių buvo trys šioje pusėje ir trys anoje pusėje; jų statramsčiai ir jų arkos atitiko pirmutinių vartų matmenis: jų ilgis buvo penkiasdešimt uolekčių, o plotis – dvidešimt penkios uolektys.'),
  (@b26, 40, 22, 'Jų langai, jų arkos ir jų palmės atitiko išmatavimą vartų, nukreiptų į rytus; į juos lipo septyniais laiptais; o jų arkos buvo priešais juos.'),
  (@b26, 40, 23, 'Vidinio kiemo vartai buvo priešais vartus, nukreiptus į šiaurę ir nukreiptus į rytus; ir jis išmatavo nuo vartų iki vartų šimtą uolekčių.'),
  (@b26, 40, 24, 'Po to jis nuvedė mane į pietus, ir štai vartai, nukreipti į pietus; jis išmatavo jų statramsčius ir jų arkas pagal šituos matmenis.'),
  (@b26, 40, 25, 'Juose ir jų arkose aplinkui buvo langai, kaip anie langai; ilgis buvo penkiasdešimt uolekčių, o plotis – dvidešimt penkios uolektys.'),
  (@b26, 40, 26, 'Į juos pakilti buvo septyni laiptai, o jų arkos buvo priešais juos; ir ant savo statramsčių jie turėjo palmių: vieną šioje pusėje, o kitą – anoje pusėje.'),
  (@b26, 40, 27, 'Vidiniame kieme pietų link buvo vartai; ir jis išmatavo nuo vartų iki vartų, pietų link, šimtą uolekčių.'),
  (@b26, 40, 28, 'Ir jis nuvedė mane pro pietinius vartus į vidinį kiemą; ir jis išmatavo pietinius vartus pagal šituos išmatavimus;'),
  (@b26, 40, 29, 'jų kambarėlius, jų statramsčius ir jų arkas pagal šituos išmatavimus; juose ir jų arkose aplinkui buvo langai; jie buvo penkiasdešimties uolekčių ilgio ir dvidešimt penkių uolekčių pločio.'),
  (@b26, 40, 30, 'Arkos aplinkui buvo dvidešimt penkių uolekčių ilgio ir penkių uolekčių pločio.'),
  (@b26, 40, 31, 'Jų arkos buvo nukreiptos į išorinį kiemą; ir ant jų stulpų buvo palmės; o užkilimas į juos turėjo aštuonis laiptus.'),
  (@b26, 40, 32, 'Ir jis nuvedė mane į vidinį kiemą rytų link; ir jis išmatavo vartus pagal šituos matmenis.'),
  (@b26, 40, 33, 'Jų kambarėliai, jų statramsčiai ir jų arkos buvo pagal šituos matmenis; juose ir jų arkose aplinkui buvo langai; jie buvo penkiasdešimties uolekčių ilgio ir dvidešimt penkių uolekčių pločio.'),
  (@b26, 40, 34, 'Jų arkos buvo išorinio kiemo link; ir palmės buvo ant jų statramsčių šioje pusėje ir anoje pusėje; o užkilimas į juos turėjo aštuonis laiptus.'),
  (@b26, 40, 35, 'Ir jis nuvedė mane prie šiaurinių vartų ir juos išmatavo pagal šituos matmenis;'),
  (@b26, 40, 36, 'jų kambarėliai, jų statramsčiai, jų arkos ir jų langai aplinkui; ilgis buvo penkiasdešimt uolekčių, o plotis – dvidešimt penkios uolektys.'),
  (@b26, 40, 37, 'Jų statramsčiai buvo link išorinio kiemo; ir palmės buvo ant jų statramsčių šioje pusėje ir anoje pusėje; o užkilimas į juos turėjo aštuonis laiptus.'),
  (@b26, 40, 38, 'Kambariai ir jų įėjimai buvo prie vartų statramsčių, kur plaudavo deginamąją atnašą.'),
  (@b26, 40, 39, 'O vartų prieangyje buvo du stalai šiapus ir du stalai anapus, kad ant jų pjautų deginamąją atnašą, nuodėmės atnašą ir nusižengimo atnašą.'),
  (@b26, 40, 40, 'Išorinėje pusėje, einant aukštyn link šiaurinių vartų įėjimo, buvo du stalai; ir kitoje pusėje, esančioje prie vartų prieangio, buvo du stalai.'),
  (@b26, 40, 41, 'Keturi stalai buvo šiapus ir keturi stalai anapus prie vartų šono – aštuoni stalai, ant kurių jie pjaudavo jų aukas.'),
  (@b26, 40, 42, 'Keturi stalai buvo iš tašytų akmenų deginamajai atnašai, pusantros uolekties ilgio, pusantros uolekties pločio ir vienos uolekties aukščio; ant jų padeda įrankius, kuriais pjauna deginamąsias atnašas ir aukas.'),
  (@b26, 40, 43, 'Ir viduje aplinkui buvo pritvirtinti plaštakos pločio kabliai; o ant stalų buvo atnašos mėsa.'),
  (@b26, 40, 44, 'Vidinių vartų lauko pusėje buvo giedotojų kambariai, vidiniame kieme, esančiame prie šiaurinių vartų šono; jie žvelgė į pietus, vienas – prie rytinių vartų šono – žvelgė į šiaurę.'),
  (@b26, 40, 45, 'Ir jis man tarė: „Šitas kamabarys, kuris yra priekiu į pietus, yra kunigams, atliekantiems namų įpareigojimus.'),
  (@b26, 40, 46, 'O kambarys, kuris yra priekiu į šiaurę, yra kunigams, atliekantiems aukuro įpareigojimus; tie yra Cadoko sūnūs tarp Levio sūnų, kurie artinasi prie VIEŠPATIES, kad jam tarnautų“.'),
  (@b26, 40, 47, 'Taigi jis išmatavo kiemą, šimtas uolekčių ilgio ir šimtas uolekčių pločio, buvo kvadratinis; ir aukurą, kuris buvo priešais namus.'),
  (@b26, 40, 48, 'Ir jis nuvedė mane į namų prieangį ir išmatavo kiekvieną prieangio statramstį, penkios uolektys šiapus ir penkios uolektys anapus; o vartų plotis buvo trys uolektys šioje pusėje ir trys uolektys anoje pusėje.'),
  (@b26, 40, 49, 'Prieangio ilgis buvo dvidešimt uolekčių, o plotis – vienuolika uolekčių; ir jis nuvedė mane laiptais, kuriais lipama į jį; šalia statramsčių buvo stulpai: vienas šioje pusėje, o kitas anoje pusėje.'),
  (@b26, 41, 1, 'Paskui jis atvedė mane į šventyklą ir išmatavo statramsčius: šešių uolekčių plotis vienoje pusėje ir šešių uolekčių plotis kitoje pusėje – tai buvo padangtės plotis.'),
  (@b26, 41, 2, 'Durų plotis buvo dešimt uolekčių; o durų šonai – penkios uolektys vienoje pusėje ir penkios uolektys kitoje pusėje; ir jis išmatavo jos ilgį – keturiasdešimt uolekčių, ir plotį – dvidešimt uolekčių.'),
  (@b26, 41, 3, 'Paskui jis įėjo vidun ir išmatavo durų statramstį – dvi uolektys; duris – šešios uolektys; ir durų plotį – septynios uolektys.'),
  (@b26, 41, 4, 'Taigi jis išmatavo jos ilgį, dvidešimt uolekčių, ir plotį – dvidešimt uolekčių, priešais šventyklą; ir jis man tarė: „Tai šventų švenčiausioji“.'),
  (@b26, 41, 5, 'Paskui jis išmatavo namų sieną – šešios uolektys; o kiekvieno šoninio kambario plotis – keturios uolektys, aplink namus iš visų pusių.'),
  (@b26, 41, 6, 'Šoninių kambarių buvo po tris, vienas virš kito, trisdešimt paeiliui; ir jie buvo įleisti į namų sieną šoniniams kambariams aplinkui, kad jie laikytųsi, bet jie nesilaikė namų sienoje.'),
  (@b26, 41, 7, 'Ir buvo platėjimas ir išsidėstymas ratu aukštyn link šoninių kambarių; nes namo išsidėstymas ratu kilo vis aukštyn aplink namą; todėl namas aukštyn vis platėjo ir taip didėjo nuo žemutinio kambario iki aukščiausio per vidurį.'),
  (@b26, 41, 8, 'Taip pat pamačiau namo aukštį aplinkui; šoninių kambarių pamatai buvo visa šešių pilnų uolekčių nendrė.'),
  (@b26, 41, 9, 'Išorinio šoninio kambario sienos storis buvo penkios uolektys; o tai, kas likę, buvo šoninių vidinių kambarių vieta.'),
  (@b26, 41, 10, 'Tarp kambarių buvo dvidešimties uolekčių platumas aplink namą iš visų pusių.'),
  (@b26, 41, 11, 'Šoninių kambarių durys buvo nukreiptos į likusią vietą: vienos durys nukreiptos į šiaurę, o kitos durys – į pietus; o tos likusios vietos plotis buvo penkios uolektys aplinkui.'),
  (@b26, 41, 12, 'Na, o pastatas, esantis priešais atskirą vietą gale, nukreiptą į vakarus, buvo septyniasdešimt uolekčių pločio; pastato siena buvo penkių uolekčių storio aplinkui, o jo ilgis – devyniasdešimt uolekčių.'),
  (@b26, 41, 13, 'Taigi jis išmatavo namus, šimto uolekčių ilgį; o atskiroji vieta ir pastatas su jo sienomis – šimtas uolekčių ilgio;'),
  (@b26, 41, 14, 'taip pat namų priekio bei atskirosios vietos, nukreiptos į rytus, plotis – šimtas uolekčių.'),
  (@b26, 41, 15, 'Ir jis išmatavo pastato ilgį priešais atskirą vietą, esančią jo užpakalinėje pusėje, ir jo galerijas vienoje ir kitoje pusėje, – šimtas uolekčių, su šventyklos vidumi ir kiemo prieangiais;'),
  (@b26, 41, 16, 'durų staktos, siaurieji langai ir galerijos aplink trijuose jų aukštuose, priešais duris, aplinkui apmuštos medžiu, ir nuo žemės aukštyn iki langų, ir langai buvo apdengti;'),
  (@b26, 41, 17, 'iki virš durų, iki vidinių namų ir išorės, ir aplinkui palei visą sieną, iš vidaus ir iš lauko, pagal išmatavimus.'),
  (@b26, 41, 18, 'Ir buvo padaryti su kerubais bei palmėmis, kad palmė buvo tarp kerubo ir kerubo; o kiekvienas kerubas turėjo du veidus;'),
  (@b26, 41, 19, 'taip, kad žmogaus veidas buvo nukreiptas į palmę vienoje pusėje, ir jauno liūto veidas nukreiptas į palmę kitoje pusėje; tai buvo padaryta po visą namą aplinkui.'),
  (@b26, 41, 20, 'Nuo žemės iki virš durų buvo padaryti kerubai bei palmės, ir ant šventyklos sienos.'),
  (@b26, 41, 21, 'Šventyklos staktos buvo keturkampės, ir šventovės priekis; vienos išvaizda buvo kaip ir kitos.'),
  (@b26, 41, 22, 'Medinis aukuras buvo trijų uolekčių aukščio, o jo ilgis – dvi uolektys; jo kampai, jo ilgis ir jo sienos buvo iš medžio; ir jis man tarė: „Tai stalas, esantis VIEŠPATIES akivaizdoje“.'),
  (@b26, 41, 23, 'Šventykla ir šventovė turėjo dvejas duris.'),
  (@b26, 41, 24, 'Durys turėjo po dvi sąvaras, dvi pasisukančias sąvaras; dvi sąvaros vienoms durims ir dvi sąvaros kitoms durims.'),
  (@b26, 41, 25, 'Ir ant jų, ant šventyklos durų, buvo padaryti kerubai ir palmės, kaip buvo padaryti ant sienų; ir buvo storos lentos ant prieangio priekio iš lauko.'),
  (@b26, 41, 26, 'Ir buvo siauri langai ir palmės vienoje ir kitoje pusėje prieangio šonuose ir namų šoniniuose kambariuose, ir ant storų lentų.'),
  (@b26, 42, 1, 'Paskui jis išvedė mane į išorinį kiemą, keliu šiaurės link; ir nuvedė mane į kambarį, esantį priešais atskirąją vietą ir esantį prieš pastatą, nukreiptą į šiaurę.'),
  (@b26, 42, 2, 'Prieš šimto uolekčių ilgį buvo šiaurinės durys, o plotis buvo penkiasdešimt uolekčių.'),
  (@b26, 42, 3, 'Priešais vidinio kiemo dvidešimt uolekčių ir priešais išorinio kiemo grindinį buvo galerija priešais galeriją per tris aukštus.'),
  (@b26, 42, 4, 'O prieš kambarius buvo takas, dešimties uolekčių pločio į vidų, vienos uolekties kelias; o jų durys šiaurės link.'),
  (@b26, 42, 5, 'Na, o viršutiniai kambariai buvo siauresni; nes galerijos buvo aukštesnės už šituos, už pastato apatinius ir vidurinius.'),
  (@b26, 42, 6, 'Nes jie buvo trijuose aukštuose, bet neturėjo tokių stulpų, kaip kiemo stulpai; todėl pastatas buvo siauresnis už apatinius ir vidurinius nuo žemės.'),
  (@b26, 42, 7, 'O laukinės sienos, esančios priešais kambarius, link išorinio kiemo, priekinėje kambarių dalyje, jos ilgis buvo penkiasdešimt uolekčių.'),
  (@b26, 42, 8, 'Nes kambarių, esančių išoriniame kieme, ilgis buvo penkiasdešimt uolekčių; o štai prieš šventyklą buvo šimtas uolekčių.'),
  (@b26, 42, 9, 'O iš apačios šitų kambarių buvo įėjimas rytų pusėje, kai į juos įeinama iš išorinio kiemo.'),
  (@b26, 42, 10, 'Kambariai buvo kiemo sienos storume rytų link, priešais atskirąją vietą ir priešais pastatą.'),
  (@b26, 42, 11, 'Ir kelias priešais juos buvo panašus į kambarius, esančius šiaurės link, tokio pat ilgio ir tokio pat pločio, kaip jie; ir visi jų išėjimai buvo pagal jų įrengimus ir pagal jų duris.'),
  (@b26, 42, 12, 'Tokios kaip durys kambarių, esančių pietų link, buvo ir durys pradžioje kelio, būtent kelio, esančio tiesiai priešais sieną rytų link, kur į juos įeinama.'),
  (@b26, 42, 13, 'Tada jis man tarė: „Šiauriniai kambariai ir pietiniai kambariai, esantys prieš atskirąją vietą, yra šventi kambariai, kur kunigai, kurie artinasi prie VIEŠPATIES, valgys švenčiausius dalykus; ten jie sudės švenčiausius dalykus, maisto atnašą, nuodėmės atnašą ir nusižengimo atnašą; nes ta vieta yra šventa.'),
  (@b26, 42, 14, 'Ten įėję kunigai neišeis iš šventos vietos į išorinį kiemą, bet ten jie pasidės savo drabužius, su kuriais jie tarnauja; nes jie yra šventi; ir apsivilks kitus drabužius, ir artinsis prie tų dalykų, kurie yra tautai“.'),
  (@b26, 42, 15, 'Na, o baigęs matuoti vidinį namą, jis mane išvedė link vartų, kurių priekis yra nukreiptas į rytus, ir matavo jį aplinkui.'),
  (@b26, 42, 16, 'Matavimo nendre jis išmatavo rytinę pusę, penkiais šimtais nendrių, matavimo nendre aplinkui.'),
  (@b26, 42, 17, 'Jis išmatavo šiaurinę pusę penkiais šimtais nendrių, matavimo nendre aplinkui.'),
  (@b26, 42, 18, 'Matavimo nendre jis išmatavo pietų pusę penkiais šimtais nendrių.'),
  (@b26, 42, 19, 'Pasisukęs į vakarų pusę, matavimo nendre jis išmatavo penkiais šimtais nendrių.'),
  (@b26, 42, 20, 'Jis išmatavo jį iš keturių pusių; jis turėjo aplinkui penkių šimtų nendrių ilgio ir penkių šimtų nendrių pločio sieną, kad atskirtų šventovę nuo nešventos vietos.'),
  (@b26, 43, 1, 'Po to jis nuvedė mane prie vartų, būtent vartų, nukreiptų į rytus;'),
  (@b26, 43, 2, 'ir štai Izraelio Dievo šlovė atėjo nuo rytų kelio; ir jo balsas buvo kaip daugybės vandenų ūžimas; ir žemė spindėjo nuo jo šlovės.'),
  (@b26, 43, 3, 'Tai buvo pagal vaizdą to regėjimo, kurį mačiau, būtent pagal regėjimą, kurį mačiau, kai atėjau miesto sunaikinti; ir tie regėjimai buvo kaip regėjimas, kurį mačiau prie Kebaro upės; ir aš parpuoliau veidu į žemę.'),
  (@b26, 43, 4, 'Ir VIEŠPATIES šlovė įėjo į namus vartų keliu, kurių priekis nukreiptas į rytus.'),
  (@b26, 43, 5, 'Taigi Dvasia mane pakėlė ir nunešė į vidinį kiemą; ir štai VIEŠPATIES šlovė pripildė namus.'),
  (@b26, 43, 6, 'Ir išgirdau jį kalbantį man iš namų; tas vyras stovėjo šalia manęs.'),
  (@b26, 43, 7, 'Ir jis man tarė: „Žmogaus sūnau, mano sosto vietos ir mano kojų padų vietos, kur aš per amžius gyvensiu tarp Izraelio vaikų, ir mano šventojo vardo nebesuterš Izraelio namai, nei jie, nei jų karaliai savo paleistuvavimu ir savo karalių lavonais jų aukštumose.'),
  (@b26, 43, 8, 'Pastatydami savo slenkstį prie mano slenksčių, savo durų staktas šalia mano staktų ir sieną tarp manęs ir jų, jie suteršė mano šventąjį vardą savo bjaurystėmis, kurias jie darė; todėl juos sunaikinau savo pyktyje.'),
  (@b26, 43, 9, 'Dabar tegul jie atitolina nuo manęs savo paleistuvavimą ir savo karalių lavonus, ir aš gyvensiu tarp jų per amžius.'),
  (@b26, 43, 10, 'Tu, žmogaus sūnau, paskelbk Izraelio namams apie tuos namus, kad jie gėdytųsi dėl savo nusikaltimų; ir teišmatuoja jie tą pavyzdį.'),
  (@b26, 43, 11, 'Ir jeigu jie gėdysis viso to, ką darė, parodyk jiems tų namų formą, jų išvaizdą, jų išėjimus ir jų įėjimus, ir visas jų formas, ir visus jų įsakus, visas jų formas, visus jų įstatymus; ir užrašyk tai jų akyse, kad jie laikytųsi visų jų formų, visų jų įsakų ir juos vykdytų.'),
  (@b26, 43, 12, 'Toks yra tų namų įstatymas: kalno viršūnėje visa jų riba aplink bus šventų švenčiausia. Štai šis yra tų namų įstatymas.'),
  (@b26, 43, 13, 'Ir šitie yra aukuro išmatavimai uolektimis: uolektis yra uolektis ir plaštaka; dugnas bus uolektis ir plotis uolektis, o jo briauna aplinkui palei jo kraštą bus per sprindį; ir tai bus aukuro iškilimas.'),
  (@b26, 43, 14, 'Ir nuo dugno, esančio ant žemės, iki žemutinio išsikišimo bus dvi uolektys, o plotis – viena uolektis; o nuo mažesnio išsikišimo iki didesnio išsikišimo bus keturios uolektys, o plotis – viena uolektis.'),
  (@b26, 43, 15, 'Taigi aukuras bus keturios uolektys; o nuo aukuro aukštyn bus keturi ragai.'),
  (@b26, 43, 16, 'Aukuras bus dvylikos uolekčių ilgio ir dvylikos uolekčių pločio, kvadratinis su keturiais savo šonais.'),
  (@b26, 43, 17, 'O išsikišimas bus keturiolikos uolekčių ilgio ir keturiolikos uolekčių pločio su keturiais savo šonais; ir briauna aplink jį bus pusės uolekties; o jo dugnas bus viena uolektis aplinkui; o jo laiptai bus nukreipti į rytus“.'),
  (@b26, 43, 18, 'Ir jis man tarė: „Žmogaus sūnau, taip sako Viešpats DIEVAS: ‘Šitie yra aukuro įsakai tą dieną, kai jį padarys, kad ant jo atnašautų deginamąsias atnašas ir kad ant jo šlakstytų kraują.'),
  (@b26, 43, 19, 'Ir levitams kunigams, esantiems iš Cadoko sėklos, kurie artinasi prie manęs man tarnauti, – sako Viešpats DIEVAS, – duok jauną jautį nuodėmės atnašai.'),
  (@b26, 43, 20, 'Ir paimk jo kraujo, uždėk jo ant keturių jo ragų, ant keturių išsikišimo kampų ir ant briaunos aplinkui; taip jį apiplausi ir apvalysi.'),
  (@b26, 43, 21, 'Taip pat paimk nuodėmės atnašos jautį, ir jį sudegins paskirtoje namo vietoje už šventovės ribų.'),
  (@b26, 43, 22, 'O antrąją dieną atnašauk bedėmį ožiuką iš ožių nuodėmės atnašai; ir jie apvalys aukurą, kaip jį apvalė jaučiu.'),
  (@b26, 43, 23, 'Baigęs jį apvalyti, atnašauk jauną jautį be dėmės ir iš kaimenės aviną be dėmės.'),
  (@b26, 43, 24, 'Ir juos atnašauk VIEŠPATIES akivaizdoje, o kunigai ant jų pabarstys druskos ir atnašaus juos kaip deginamąją atnašą VIEŠPAČIUI.'),
  (@b26, 43, 25, 'Septynias dienas kas dieną paruoši ožį nuodėmės atnašai; taip pat jie paruoš jauną jautį ir aviną iš kaimenės, be dėmės.'),
  (@b26, 43, 26, 'Septynias dienas jie apvalinės aukurą ir jį skaistins; ir jie save įšventins.'),
  (@b26, 43, 27, 'Ir šioms dienoms pasibaigus bus, kad aštuntąją dieną ir vėliau kunigai atliks ant aukuro jūsų deginamąsias atnašas ir jūsų taikos atnašas; ir aš jus priimsiu, – sako Viešpats DIEVAS’“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b26, 44, 1, 'Paskui jis nuvedė mane išorinės šventovės vartų, nukreiptų į rytus, keliu atgal; ir jie buvo uždaryti.'),
  (@b26, 44, 2, 'Tada VIEŠPATS man tarė: „Šitie vartai bus uždaryti, jie nebus atidaryti, ir niekas neįeis pro juos; nes VIEŠPATS, Izraelio Dievas, yra įėjęs pro juos, todėl jie bus uždari.'),
  (@b26, 44, 3, 'Jie yra kunigaikščiui; kunigaikštis – jis sėdės juose, kad valgytų duoną VIEŠPATIES akivaizdoje; jis įeis tų vartų prieangio keliu ir tuo pačiu keliu išeis“.'),
  (@b26, 44, 4, 'Paskui jis nuvedė mane šiaurinių vartų prieš namą keliu; aš pažiūrėjau, ir štai VIEŠPATIES šlovė pripildė VIEŠPATIES namą; ir aš parpuoliau veidu į žemę.'),
  (@b26, 44, 5, 'Ir VIEŠPATS man tarė: „Žmogaus sūnau, gerai įsidėmėk, žiūrėk savo akimis ir išgirsk savo ausimis viską, ką aš tau kalbėsiu apie visus VIEŠPATIES namų įsakus ir visus jų įstatymus; ir gerai įsidėmėk namų įėjimą kartu su kiekvienu išėjimu iš šventovės.'),
  (@b26, 44, 6, 'Ir sakyk maištingiesiems – Izraelio namams: ‘Taip sako Viešpats DIEVAS: O Izraelio namai, gana jums visų jūsų bjaurysčių,'),
  (@b26, 44, 7, 'tame, kad įvedėte į mano šventovę neapipjaustytus širdimi ir neapipjaustytus kūnu svetimšalius, idant jie būtų mano šventovėje, kad suterštų juos – mano namus, kai atnašaujate mano duoną, taukus ir kraują; ir jie sulaužė mano sandorą dėl visų jūsų bjaurysčių.'),
  (@b26, 44, 8, 'Ir jūs nesilaikėte pareigų dėl mano šventenybių; bet sau paskyrėte besilaikančius mano pareigų mano šventovėje’.'),
  (@b26, 44, 9, 'Taip sako Viešpats DIEVAS: ‘Joks neapipjaustytas širdimi ir neapipjaustytas kūnu svetimšalis neįeis į mano šventovę iš jokių svetimšalių, esančių tarp Izraelio vaikų.'),
  (@b26, 44, 10, 'Ir levitai, kurie atsitolino nuo manęs, kai Izraelis nuklydo, kurie nuklydo nuo manęs, sekdami paskui savo stabus; jie nešios savo neteisybę.'),
  (@b26, 44, 11, 'Tačiau jie bus tarnautojai mano šventovėje, eidami pareigas prie namų vartų ir tarnaudami namams; jie pjaus tautai deginamąją atnašą ir auką, ir jie stovės jų akivaizdoje, kad jiems tarnautų.'),
  (@b26, 44, 12, 'Kadangi jie tarnavo jiems jų stabų akivaizdoje ir paskatino Izraelio namus įpulti į neteisybę; todėl pakėliau savo ranką prieš juos, – sako Viešpats DIEVAS, – ir jie nešios savo neteisybę.'),
  (@b26, 44, 13, 'Ir jie nesiartins prie manęs, kad atliktų man kunigo tarnystę ar kad prieitų prie bet kurių mano šventenybių šventų švenčiausioje; bet jie nešios savo gėdą ir savo bjaurystes, kurias jie darė.'),
  (@b26, 44, 14, 'Tačiau juos padarysiu namų pareigų prižiūrėtojais, dėl viso jų aptarnavimo ir dėl visko, kas juose darytina.'),
  (@b26, 44, 15, 'Bet levitai kunigai, Cadoko sūnūs, kurie Izraelio vaikams nuklydus nuo manęs atlikinėjo mano šventovės pareigas, – jie artinsis prie manęs, kad tarnautų man, ir stovės mano akivaizdoje, kad atnašautų man taukus ir kraują, – sako Viešpats DIEVAS; –'),
  (@b26, 44, 16, 'jie įeis į mano šventovę, jie priartės prie mano stalo, kad man tarnautų, ir laikysis mano pareigų.'),
  (@b26, 44, 17, 'Ir įvyks, kad įeidami pro vidinio kiemo vartus, jie bus apsivilkę lininiais drabužiais; ir jiems tarnaujant vidinio kiemo vartuose ir viduje, joks vilnonis teneužsivilks ant jų.'),
  (@b26, 44, 18, 'Jie turės linines kepures ant savo galvų ir turės linines kelnes ant savo strėnų; jie neapsijuos niekuo, kas sukelia prakaitą.'),
  (@b26, 44, 19, 'Ir išeidami į išorinį kiemą, tai yra į išorinį kiemą pas tautą, jie nusivilks savo drabužius, su kuriais tarnavo, juos padės šventuosiuose kambariuose ir apsivilks kitais drabužiais; jie nepašvęs tautos savo drabužiais.'),
  (@b26, 44, 20, 'Ir jie nesiskus galvos ir neleis savo plaukams augti ilgiems; jie tik apsikirps galvas.'),
  (@b26, 44, 21, 'Ir joks kunigas negers vyno, kai jis įeina į vidinį kiemą.'),
  (@b26, 44, 22, 'Ir jie neims į žmonas nei našlės, nei atleistosios; jie ims tik mergeles iš Izraelio namų sėklos arba našlę, kurią prieš tai turėjo kunigas.'),
  (@b26, 44, 23, 'Ir jie mokys mano tautą atskirti šventa nuo nešvento ir padarys, kad jie atskirtų tarp nešvaraus ir švaraus.'),
  (@b26, 44, 24, 'Ir kilus ginčui jie stos į teismą; jie teis pagal mano teismus; jie laikysis mano įstatymų ir mano įstatų visuose mano susirinkimuose; ir jie pašvęs mano sabatus.'),
  (@b26, 44, 25, 'Ir jie neprieis nei prie vieno numirėlio, kad nesusiterštų; bet dėl tėvo ar dėl motinos, ar dėl sūnaus, ar dėl dukters, ar dėl brolio, ar dėl neturinčios vyro sesers jiems galima susiteršti.'),
  (@b26, 44, 26, 'Ir po to, kai jis apvalytas, jie atskaičiuos jam septynias dienas.'),
  (@b26, 44, 27, 'Ir tą dieną, kai jis eis į šventovę, į vidinį kiemą tarnauti šventovėje, jis atnašaus savo nuodėmės atnašą, – sako Viešpats DIEVAS.'),
  (@b26, 44, 28, '– Ir tai jiems bus kaip paveldas; aš esu jų paveldas; neduokite jiems jokios nuosavybės Izraelyje; aš esu jų nuosavybė.'),
  (@b26, 44, 29, 'Jie valgys maisto atnašą, nuodėmės atnašą ir nusižengimo atnašą; ir visa, kas Izraelyje pašvęsta, bus jų.'),
  (@b26, 44, 30, 'Ir visų dalykų visų pirmavaisių pirmienos, ir kiekviena auka iš visų, visokiausių jūsų aukų, bus kunigų; taip pat duosite kunigui savo tešlos pirmienas, kad jis duotų palaiminimui ilsėtis tavo namuose.'),
  (@b26, 44, 31, 'Kunigai nevalgys nieko, kas padvėsę ar kas sudraskyta, ar tai būtų skrajūnas, ar gyvulys’“.'),
  (@b26, 45, 1, '„Be to, kai burtu dalinsite šalį paveldėjimui, atnašaukite VIEŠPAČIUI auką, šventą šalies dalį; ilgis bus dvidešimt penkių tūkstančių nendrių ilgis, o plotis bus dešimt tūkstančių. Ji bus šventa visose savo ribose aplinkui.'),
  (@b26, 45, 2, 'Iš jos bus šventovei penkių šimtų ilgio ir penkių šimtų pločio keturkampis aplinkui; ir penkiasdešimt uolekčių aplinkui, jos priemiesčiams.'),
  (@b26, 45, 3, 'Iš šito mato atmatuok dvidešimt penkių tūkstančių ilgį ir dešimt tūkstančių plotį; ir jame bus šventovė, šventų švenčiausioji.'),
  (@b26, 45, 4, 'Šventoji šalies dalis bus kunigams, šventovės tarnautojams, kurie artinsis tarnauti VIEŠPAČIUI; ir tai bus vieta jų namams ir šventa vieta šventovei.'),
  (@b26, 45, 5, 'O dvidešimt penkių tūkstančių ilgį ir dešimt tūkstančių plotį turės namų tarnautojai levitai savo nuosavybėn, dvidešimčiai kambarių.'),
  (@b26, 45, 6, 'Ir paskirkite miesto nuosavybę penkių tūkstančių pločio ir dvidešimt penkių tūkstančių ilgio priešais šventosios dalies auką; tai bus visiems Izraelio namams.'),
  (@b26, 45, 7, 'Ir dalis bus kunigaikščiui vienoje ir kitoje šventosios dalies aukos ir miesto nuosavybės pusėje, priešais šventosios dalies auką ir priešais miesto nuosavybę, vakariniame šone į vakarus ir rytiniame šone į rytus; ir ilgis bus priešais vieną iš dalių, nuo vakarinės iki rytinės ribos.'),
  (@b26, 45, 8, 'Šioje šalyje bus jo nuosavybė Izraelyje; ir mano kunigaikščiai nebeengs mano tautos; o likusią šalį duos Izraelio namams pagal jų gentis“.'),
  (@b26, 45, 9, 'Taip sako Viešpats DIEVAS: „Gana jums, o Izraelio kunigaikščiai; pašalinkite smurtą bei grobimą ir vykdykite teismą bei teisingumą, pašalinkite savo apiplėšimus nuo mano tautos, – sako Viešpats DIEVAS.'),
  (@b26, 45, 10, '– Turėkite teisingas svarstykles, teisingą efą ir teisingą batą.'),
  (@b26, 45, 11, 'Efa ir batas turi būti vienodo saiko, kad bate būtų dešimta homero dalis ir efoje dešimta homero dalis; jo saikas bus pagal homerą.'),
  (@b26, 45, 12, 'O šekelis bus dvidešimt gerų; dvidešimt šekelių, dvidešimt penki šekeliai, penkiolika šekelių bus jums mina.'),
  (@b26, 45, 13, 'Tai yra auka, kurią atnašausite: šeštadalis efos iš homero kviečių, ir duosite šeštadalį efos iš homero miežių;'),
  (@b26, 45, 14, 'dėl aliejaus potvarkio, bato aliejaus: atnašaukite dešimtadalį bato iš koro, kuris yra homeras iš dešimt batų; nes dešimt batų yra homeras;'),
  (@b26, 45, 15, 'ir vieną avinėlį iš dviejų šimtų, iš kaimenės, iš Izraelio riebių ganyklų, maisto atnašai, deginamajai atnašai ir taikos atnašoms, kad atliktų už juos sutaikinimą, – sako Viešpats DIEVAS.'),
  (@b26, 45, 16, '– Visa šalies tauta duos šitą auką kunigaikščiui Izraelyje.'),
  (@b26, 45, 17, 'Ir tai bus kunigaikščio pareiga duoti deginamąsias atnašas, maisto atnašas ir geriamąsias atnašas per šventes, per jauną mėnulį, per sabatus visose Izraelio namų iškilmėse; jis paruoš nuodėmės atnašą, maisto atnašą, deginamąją atnašą ir taikos atnašas, kad atliktų sutaikinimą dėl Izraelio namų“.'),
  (@b26, 45, 18, 'Taip sako Viešpats DIEVAS: „Pirmąjį mėnesį, pirmąją to mėnesio dieną, paimk jauną jautį be dėmės ir apvalyk šventovę.'),
  (@b26, 45, 19, 'Ir kunigas paims nuodėmės atnašos kraujo ir uždės jo ant namų statramsčių, ant keturių aukuro išsikišimo kampų ir ant vidinio kiemo vartų statramsčių.'),
  (@b26, 45, 20, 'Taip daryk septintąją to mėnesio dieną už kiekvieną klystantį ir už paikąjį; taip sutaikinsite namus.'),
  (@b26, 45, 21, 'Pirmąjį mėnesį, keturioliktąją to mėnesio dieną pas jus bus Apėjimas, septynių dienų šventė; turės būti valgoma nerauginta duona.'),
  (@b26, 45, 22, 'Tą dieną kunigaikštis paruoš už save ir už visą šalies tautą jautį nuodėmės atnašai.'),
  (@b26, 45, 23, 'Per septynias šventės dienas jis paruoš VIEŠPAČIUI deginamąją atnašą: septynis jaučius ir septynis avinus be dėmės, kasdien, per septynias dienas; ir kasdien po ožiuką iš ožių, nuodėmės atnašai.'),
  (@b26, 45, 24, 'Jis paruoš iš efos maisto atnašą jaučiui, efą avinui ir hiną aliejaus efai.'),
  (@b26, 45, 25, 'Septintąjį mėnesį, penkioliktąją to mėnesio dieną, jis taip pat padarys per septynių dienų šventę, tokią pat nuodėmės atnašą, tokią pat deginamąją atnašą, tokią pat maisto atnašą ir tokį pat aliejų“.'),
  (@b26, 46, 1, 'Taip sako Viešpats DIEVAS: „Vidinio kiemo vartai, nukreipti į rytus, bus uždaryti per šešias darbo dienas; bet per sabatą jie bus atidaryti ir per jauną mėnulį jie bus atidaryti.'),
  (@b26, 46, 2, 'Ir kunigaikštis įeis tų išorinių vartų prieangio keliu ir sustos prie vartų staktos, o kunigai paruoš jo deginamąją atnašą ir jo taikos atnašas, ir jis pagarbins ant vartų slenkščio; tada jis išeis; bet vartai nebus uždaryti iki vakaro.'),
  (@b26, 46, 3, 'Taip pat šalies tauta pagarbins prie tų vartų durų per sabatus ir per jauną mėnulį VIEŠPATIES akivaizdoje.'),
  (@b26, 46, 4, 'Ir deginamoji atnaša, kurią kunigaikštis atnašaus VIEŠPAČIUI sabato dieną, bus šeši avinėliai be dėmės ir avinas be dėmės.'),
  (@b26, 46, 5, 'Maisto atnaša bus efa avinui, o maisto atnaša avinėliams, kiek jis galės duoti, ir hinas aliejaus efai.'),
  (@b26, 46, 6, 'Jauno mėnulio dieną tai turės būti jaunas jautis be trūkumų, šeši avinėliai ir avinas; jie turės būti be trūkumų.'),
  (@b26, 46, 7, 'Jis paruoš maisto atnašą, efą jaučiui ir efą avinui, o ėriukams tiek, kiek įsigys jo ranka, ir hiną aliejaus efai.'),
  (@b26, 46, 8, 'Ir kai kunigaikštis įeis, jis įeis tų vartų prieangio keliu ir išeis tuo pačiu keliu.'),
  (@b26, 46, 9, 'Bet kai šalies tauta ateis per iškilmingas šventes VIEŠPATIES akivaizdon, tai tas, kuris įeis pagarbinti šiaurinių vartų keliu, turės išeiti pietinių vartų keliu; o kas įeis pietinių vartų keliu, išeis šiaurinių vartų keliu; jis tenesugrįžta keliu tų vartų, pro kuriuos įėjo, bet teišeina pro jiems priešingus vartus.'),
  (@b26, 46, 10, 'O tarp jų esantis kunigaikštis jiems įeinant įeis; o jiems išeinant – išeis.'),
  (@b26, 46, 11, 'Šventėmis ir iškilmėmis maisto atnaša bus efa jaučiui, efa avinui, o avinėliams – kiek jis gali duoti, ir hinas aliejaus efai.'),
  (@b26, 46, 12, 'Na, o kai kunigaikštis paruoš laisvos valios deginamąją atnašą ar taikos atnašas savo noru VIEŠPAČIUI, tuomet jam atidarys vartus, nukreiptus į rytus, ir jis paruoš savo deginamąją atnašą ir savo taikos atnašas taip, kaip jis darė sabato dieną; paskui jis išeis; ir jam išėjus vartus uždarys.'),
  (@b26, 46, 13, 'Kasdien paruošk VIEŠPAČIUI metinio avinėlio be trūkumų deginamąją atnašą; paruošk ją kiekvieną rytą.'),
  (@b26, 46, 14, 'Ir kiekvieną rytą jai paruošk maisto atnašą: šeštadalį efos ir trečdalį hino aliejaus, sumaišymui su smulkiais miltais; amžinu įsaku nuolatinę maisto atnašą VIEŠPAČIUI.'),
  (@b26, 46, 15, 'Taip jie kiekvieną rytą paruoš avinėlį, maisto atnašą ir aliejų kaip nuolatinę deginamąją atnašą“.'),
  (@b26, 46, 16, 'Taip sako Viešpats DIEVAS: „Jei kunigaikštis duos kuriam nors iš savo sūnų dovaną, tai jos paveldas bus jo sūnų; tai bus jų nuosavybė paveldu.'),
  (@b26, 46, 17, 'Bet jei jis duos savo paveldo dovaną kuriam nors iš savo tarnų, tai ji bus jo iki laisvės metų; po to ji sugrįš kunigaikščiui; jo paveldas bus tik jo sūnų dėl jų.'),
  (@b26, 46, 18, 'Be to, kunigaikštis teneima iš tautos paveldo engdamas, kad juos išmestų iš jų nuosavybės; bet iš savo paties nuosavybės jis duos paveldą savo sūnums, kad mano tauta nebūtų išsklaidyta, kiekvienas iš savo nuosavybės“.'),
  (@b26, 46, 19, 'Paskui jis nuvedė mane pro įėjimą, esantį vartų pašonėje, į šventuosius kunigų kambarius, nukreiptus į šiaurę; ir štai ten buvo vieta dviejose pusėse į vakarus.'),
  (@b26, 46, 20, 'Tada jis man tarė: „Tai yra vieta, kur kunigai virs nusižengimo atnašą bei nuodėmės atnašą, kur jie keps maisto atnašą, kad jų neišneštų į išorinį kiemą ir nepašvęstų tautos“.'),
  (@b26, 46, 21, 'Paskui jis išvedė mane į išorinį kiemą ir pervedė mane pro keturis kiemo kampus; ir štai kiekviename kiemo kampe buvo kiemas.'),
  (@b26, 46, 22, 'Keturiuose kiemo kampuose buvo susijungę keturiasdešimties uolekčių ilgio ir trisdešimties uolekčių pločio kiemai; šitie keturi kampai buvo vienodo išmatavimo.'),
  (@b26, 46, 23, 'Ir aplinkui juose buvo mūro eilė, aplink tuos keturis, ir tai buvo padaryta su virimo vietomis eilių apačiose aplinkui.'),
  (@b26, 46, 24, 'Tada jis man tarė: „Šitos yra vietos tų, kurie verda, kur namų tarnai virs tautos auką“.'),
  (@b26, 47, 1, 'Paskui jis nuvedė mane atgal prie namų durų; ir štai vandenys tekėjo iš po namų slenksčio į rytus; nes namų priekis stovėjo nukreiptas į rytus, o vandenys tekėjo žemyn iš po apačios, iš dešiniojo namų šono, pietinėje aukuro pusėje.'),
  (@b26, 47, 2, 'Po to jis išvedė mane iš šiaurinių vartų kelio ir vedė mane aplinkui išoriniu keliu prie išorinių vartų, keliu, nukreiptu į rytus; ir štai dešinėje pusėje tekėjo vandenys.'),
  (@b26, 47, 3, 'Ir tas vyras, turintis rankoje virvę, išėjęs į rytus atmatavo tūkstantį uolekčių ir jis vedė mane per vandenis; vandenys buvo iki kulkšnių.'),
  (@b26, 47, 4, 'Jis vėl atmatavo tūkstantį ir vedė mane per vandenis; vandenys buvo iki kelių. Jis vėl atmatavo tūkstantį ir vedė mane; vandenys buvo iki strėnų.'),
  (@b26, 47, 5, 'Po to jis atmatavo tūkstantį; ir buvo upė, kurios negalėjau pereiti; nes vandenys buvo pakilę, vandenys, kuriais reikėjo plaukti, upė, kurios negalima pereiti.'),
  (@b26, 47, 6, 'Ir jis man tarė: „Žmogaus sūnau, ar tai matei?“ Tada jis nuvedė mane ir sugrąžino mane prie upės kranto.'),
  (@b26, 47, 7, 'Na, o kai sugrįžau, štai ant upės kranto buvo labai daug medžių vienoje ir kitoje pusėje.'),
  (@b26, 47, 8, 'Tada jis man tarė: „Šitie vandenys išteka rytų krašto link, nusileidžia į dykumą ir įteka į jūrą; jiems įtekėjus į jūrą, vandenys bus išgydyti.'),
  (@b26, 47, 9, 'Ir įvyks, kad visos gyvos, judančios būtybės gyvens visur, kur atitekės upės; ir bus labai daug žuvų, nes šitie vandenys ten įtekės; nes jie bus išgydyti; ir viskas bus gyva ten, kur atitekės upė.'),
  (@b26, 47, 10, 'Ir įvyks, kad žvejai stovės prie jos nuo En-Gedžio iki En-Eglaimo; tai bus vieta tinklams ištiesti; žuvys bus pagal jų rūšis, kaip Didžiosios jūros žuvys, be galo gausios.'),
  (@b26, 47, 11, 'Bet jos pelkės ir jos liūnai neišgis; šitie bus atiduoti druskai.'),
  (@b26, 47, 12, 'Ir prie upės, ant jos kranto, toje pusėje ir anoje pusėje, augs maistui visokie medžiai, kurių lapai nenuvys ir nesibaigs jų vaisiai; jie neš naujus vaisius pagal savo mėnesį, nes jų vandenys ištekės iš šventovės; ir jų vaisiai bus maistui, o jų lapai – vaistams“.'),
  (@b26, 47, 13, 'Taip sako Viešpats DIEVAS: „Šitos bus ribos, kuriose paveldėsite šalį pagal dvylika Izraelio genčių; Juozapas gaus dvi dalis.'),
  (@b26, 47, 14, 'Ją paveldėsite kaip vienas, taip ir kitas; dėl jos aš pakėliau savo ranką, kad duočiau ją jūsų tėvams; šita šalis išpuls jums paveldui.'),
  (@b26, 47, 15, 'Ir šita bus šalies riba link šiaurinės pusės nuo Didžiosios jūros, Hetlono kelias, kur einama į Cedadą;'),
  (@b26, 47, 16, 'Hamatas, Berotas, Sibraimas, esantis tarp Damasko ribos ir Hamato ribos; Hacar-Hatikonas, esantis prie Haurano ribos.'),
  (@b26, 47, 17, 'O riba nuo jūros bus Hacar-Enanas, Damasko riba ir šiaurinė į šiaurę, ir Hamato riba. Tai yra šiaurinė pusė.'),
  (@b26, 47, 18, 'Rytinę pusę atmatuosite nuo Haurano, nuo Damasko, nuo Gileado ir nuo Izraelio šalies prie Jordano, nuo ribos iki Rytų jūros. Tai yra rytinė pusė.'),
  (@b26, 47, 19, 'O pietinė pusė pietų link, eis nuo Tamaros iki kivirčų vandenų Kadeše, upe iki Didžiosios jūros. Tai yra pietinė pusė nukreipta į pietus.'),
  (@b26, 47, 20, 'Vakarinė pusė bus Didžioji jūra nuo ribos, kol ateinama priešais Hamatą. Tai yra vakarinė pusė.'),
  (@b26, 47, 21, 'Taip sau padalinsite šitą šalį pagal Izraelio gentis.'),
  (@b26, 47, 22, 'Ir įvyks, kad ją padalinsite burtu kaip paveldą sau ir ateiviams, kurie laikinai apsigyvenę tarp jūsų, kurie pagimdys vaikų tarp jūsų; ir jie bus jums kaip gimę krašte tarp Izraelio vaikų; su jumis jie turės paveldą tarp Izraelio genčių.'),
  (@b26, 47, 23, 'Ir įvyks, kad kurioje gentyje ateivis laikinai apsigyvens, ten jam duosite jo paveldą“, – sako Viešpats DIEVAS.'),
  (@b26, 48, 1, 'Na, o šitie yra genčių vardai. Nuo šiaurinio krašto iki Hetlono kelio ribos, einant į Hamatą, Hacar-Enanas, Damasko riba į šiaurę, iki Hamato ribos; nes šitie yra rytiniai ir vakariniai šonai – dalis Danui.'),
  (@b26, 48, 2, 'O šalia Dano ribos nuo rytinio šono iki vakarinio šono – dalis Ašerui.'),
  (@b26, 48, 3, 'O šalia Ašero ribos nuo rytinio šono iki vakarinio šono – dalis Naftaliui.'),
  (@b26, 48, 4, 'O šalia Naftalio ribos nuo rytinio šono iki vakarinio šono – dalis Manasui.'),
  (@b26, 48, 5, 'O šalia Manaso ribos nuo rytinio šono iki vakarinio šono – dalis Efraimui.'),
  (@b26, 48, 6, 'O šalia Efraimo ribos nuo rytinio šono iki vakarinio šono – dalis Rubenui.'),
  (@b26, 48, 7, 'O šalia Rubeno ribos nuo rytinio šono iki vakarinio šono – dalis Judai.'),
  (@b26, 48, 8, 'O šalia Judos ribos nuo rytinio šono iki vakarinio šono turės būti atnaša, kurią atnašausite dvidešimt penkių tūkstančių nendrių pločio ir tokio pat ilgio, kaip kuri kita dalis nuo rytinio šono iki vakarinio šono; ir šventovė bus jos viduryje.'),
  (@b26, 48, 9, 'Auka, kurią atnašausite VIEŠPAČIUI, bus dvidešimt penkių tūkstančių ilgio ir dešimties tūkstančių pločio.'),
  (@b26, 48, 10, 'O jiems, tai yra kunigams, bus ši šventa auka: link šiaurės – dvidešimt penkių tūkstančių ilgio, link vakarų – dešimt tūkstančių pločio, link rytų – dešimt tūkstančių pločio ir link pietų – dvidešimt penkių tūkstančių ilgio; o VIEŠPATIES šventovė bus jos viduryje.'),
  (@b26, 48, 11, 'Tai bus kunigams, pašvęstiems iš Cadoko sūnų, kurie laikėsi mano įpareigojimo, kurie, Izraelio vaikams nuklydus, nenuklydo, kaip nuklydo levitai.'),
  (@b26, 48, 12, 'Ir šita atnašauta šalies auka jiems bus šventenybių šventenybė šalia levitų ribos.'),
  (@b26, 48, 13, 'O priešais kunigų ribą levitai gaus dvidešimt penkis tūkstančius ilgio ir dešimt tūkstančių pločio; iš viso ilgis bus dvidešimt penki tūkstančiai, o plotis – dešimt tūkstančių.'),
  (@b26, 48, 14, 'Nieko iš to jie neparduos nei iškeis, nei perleis šalies pirmavaisių; nes tai yra šventa VIEŠPAČIUI.'),
  (@b26, 48, 15, 'O penki tūkstančiai, likusieji plotyje priešais dvidešimt penkis tūkstančius, bus bendra vieta miestui, apgyvenimui ir priemiesčiams; o miestas bus jos viduryje.'),
  (@b26, 48, 16, 'O šitokie bus jo matmenys: šiaurinė pusė – keturi tūkstančiai penki šimtai, pietinė pusė – keturi tūkstančiai penki šimtai, rytinė pusė – keturi tūkstančiai penki šimtai ir vakarinė pusė – keturi tūkstančiai penki šimtai.'),
  (@b26, 48, 17, 'O miesto priemiesčiai bus į šiaurę du šimtai penkiasdešimt, į pietus – du šimtai penkiasdešimt, į rytus – du šimtai penkiasdešimt ir į vakarus – du šimtai penkiasdešimt.'),
  (@b26, 48, 18, 'O ilgio likutis priešais šventosios dalies auką bus dešimt tūkstančių į rytus ir dešimt tūkstančių į vakarus; ir tai bus priešais šventosios dalies auką; ir jos prieaugis bus maistas tarnaujantiems miestui.'),
  (@b26, 48, 19, 'Tie, kurie tarnaus miestui, jam tarnaus iš visų Izraelio genčių.'),
  (@b26, 48, 20, 'Visa auka bus dvidešimt penki tūkstančiai prie dvidešimt penkių tūkstančių: atnašaukite šventąją auką kvadratinę, drauge su miesto nuosavybe.'),
  (@b26, 48, 21, 'Likutis bus kunigaikščiui, šventosios aukos ir miesto nuosavybės vienoje bei kitoje pusėje, priešais dvidešimt penkių tūkstančių auką link rytų ribos ir į vakarus priešais dvidešimt penkis tūkstančius link vakarinės ribos, priešais kunigaikščio dalis; tai bus šventoji auka; o namų šventovė bus jos viduryje.'),
  (@b26, 48, 22, 'Be to, iš levitų nuosavybės ir iš miesto nuosavybės, vidury to, kas yra kunigaikščio, tarp Judos ribos ir Benjamino ribos, bus kunigaikščiui.'),
  (@b26, 48, 23, 'O likusioms gentims: nuo rytinio šono iki vakarinio šono, Benjaminas gaus dalį.'),
  (@b26, 48, 24, 'O šalia Benjamino ribos nuo rytinio šono iki vakarinio šono, Simeonas gaus dalį.'),
  (@b26, 48, 25, 'O šalia Simeono ribos nuo rytinio šono iki vakarinio šono, Isacharas gaus dalį.'),
  (@b26, 48, 26, 'O šalia Isacharo ribos nuo rytinio šono iki vakarinio šono, Zebulonas gaus dalį.'),
  (@b26, 48, 27, 'O šalia Zebulono ribos nuo rytinio šono iki vakarinio šono, Gadas gaus dalį.'),
  (@b26, 48, 28, 'O šalia Gado ribos, pietų šone į pietus, riba bus nuo Tamaros link kivirčų vandenų Kadeše iki upės Didžiosios jūros link.'),
  (@b26, 48, 29, 'Šita yra šalis, kurią burtu padalinsite Izraelio gentims paveldėjimui, ir šitos yra jų dalys, – sako Viešpats DIEVAS.'),
  (@b26, 48, 30, '– O šitie yra miesto išėjimai šiaurinėje pusėje – keturi tūkstančiai penki šimtai matų.'),
  (@b26, 48, 31, 'O miesto vartai bus pagal Izraelio genčių vardus – treji vartai į šiaurę: vieneri Rubeno vartai, vieneri Judos vartai, vieneri Levio vartai.'),
  (@b26, 48, 32, 'O rytų pusėje keturi tūkstančiai penki šimtai; ir treji vartai: vieneri Juozapo vartai, vieneri Benjamino vartai, vieneri Dano vartai.'),
  (@b26, 48, 33, 'O pietinėje pusėje keturi tūkstančiai penki šimtai matų; ir treji vartai: vieneri Simeono vartai, vieneri Isacharo vartai, vieneri Zebulono vartai.'),
  (@b26, 48, 34, 'Vakarinėje pusėje keturi tūkstančiai penki šimtai su jų trejais vartais: vieneri Gado vartai, vieneri Ašero vartai, vieneri Naftalio vartai.'),
  (@b26, 48, 35, 'Aplink jį buvo aštuoniolika tūkstančių matų; o miesto vardas nuo tos dienos bus: ‘VIEŠPATS yra čia’“.'),
  (@b27, 1, 1, 'Trečiaisiais Judos karaliaus Jehojakimo karaliavimo metais Babilono karalius Nebukadnecaras atėjo į Jeruzalę ir ją apgulė.'),
  (@b27, 1, 2, 'Ir Viešpats atidavė į jo ranką Judos karalių Jehojakimą ir dalį Dievo namų indų, kuriuos jis nugabeno į Šinaro šalį, į savo dievo namus; ir jis įnešė tuos indus į savo dievo lobių namus.'),
  (@b27, 1, 3, 'Ir karalius kalbėjo Ašpenazui, savo eunuchų valdovui, kad jis atvestų kai kuriuos iš Izraelio vaikų, iš karaliaus sėklos ir iš kunigaikščių;'),
  (@b27, 1, 4, 'vaikus, kuriuose nėra jokios dėmės, esančius gražios išvaizdos, gabius visokia išmintimi, sumanius pažinimu, suprantančius mokslą ir turinčius savyje sugebėjimų stovėti karaliaus rūmuose, ir kuriuos galėtų išmokyti kaldėjų mokymosi ir kalbos.'),
  (@b27, 1, 5, 'Ir karalius paskyrė jiems kasdienį aprūpinimą iš karaliaus valgio ir iš vyno, kurį jis pats gėrė; taip juos maitindamas trejus metus, kad jiems pasibaigus jie galėtų stoti karaliaus akivaizdoje.'),
  (@b27, 1, 6, 'Na, o tarp jų buvo iš Judos vaikų Danielius, Hananija, Mišaelis ir Azarija;'),
  (@b27, 1, 7, 'kuriems eunuchų kunigaikštis davė vardus, nes Danieliui jis davė Beltšacaro, Hananijai – Šadracho, Mišaeliui – Mešacho, o Azarijai – Abed-Nego vardą.'),
  (@b27, 1, 8, 'Bet Danielius savo širdyje nusprendė nesusiteršti karaliaus valgio daviniu nei jo geriamu vynu; todėl jis prašė eunuchų kunigaikščio, kad galėtų nesusiteršti.'),
  (@b27, 1, 9, 'Na, o Dievas suteikė Danieliui eunuchų kunigaikščio palankumą ir meilę.'),
  (@b27, 1, 10, 'Ir eunuchų kunigaikštis tarė Danieliui: „Aš bijau savo viešpaties karaliaus, kuris paskyrė jūsų valgį ir jūsų gėrimą; nes kodėl jis turėtų matyti jūsų veidus atrodančius blogiau už kitus, tokius kaip jūs, vaikus? Tada jūs statysite mano galvą į pavojų prieš karalių“.'),
  (@b27, 1, 11, 'Tada Danielius tarė Melcarui, kurį eunuchų kunigaikštis buvo paskyręs Danieliui, Hananijai, Mišaeliui ir Azarijai prižiūrėti:'),
  (@b27, 1, 12, '„Išmėgink, meldžiu tave, savo tarnus dešimt dienų; tegul mums duoda ankštinių valgyti ir vandens gerti.'),
  (@b27, 1, 13, 'Paskui težiūri tavo akivaizdoje į mūsų veidus ir į veidus vaikų, valgančių karaliaus valgio davinio; ir kaip pamatysi, taip pasielk su savo tarnais“.'),
  (@b27, 1, 14, 'Taigi jis sutiko su jais šituo reikalu ir bandė juos dešimt dienų.'),
  (@b27, 1, 15, 'Ir dešimčiai dienų pasibaigus, jų veidai atrodė gražesni ir kūnu riebesni už visų vaikų, valgiusių karaliaus valgio davinio.'),
  (@b27, 1, 16, 'Taip Melcaras pašalino jų valgio davinį ir vyną, kurį jie turėjo gerti; ir davė jiems ankštinių.'),
  (@b27, 1, 17, 'O šitiems keturiems vaikams Dievas davė pažinimą ir sugebėjimą visokiam mokymuisi ir išminčiai; o Danielius suprasdavo visus regėjimus ir sapnus.'),
  (@b27, 1, 18, 'Na, o pasibaigus toms dienoms, kai karalius buvo pasakęs juos įvesti, eunuchų kunigaikštis juos įvedė Nebukadnecaro akivaizdon.'),
  (@b27, 1, 19, 'Ir karalius kalbėjosi su jais; ir tarp jų visų neatsirado nei vieno tokio, kaip Danielius, Hananija, Mišaelis ir Azarija; todėl jie stovėjo karaliaus akivaizdoje.'),
  (@b27, 1, 20, 'Ir visokiuose išminties ir supratimo dalykuose, apie kuriuos karalius juos klausinėjo, jis juos rado dešimt kartų geresniais už visus burtininkus ir astrologus, esančius visoje jo karalystėje.'),
  (@b27, 1, 21, 'Ir Danielius pasiliko iki pirmųjų karaliaus Kyro metų.'),
  (@b27, 2, 1, 'Ir antraisiais Nebukadnecaro karaliavimo metais Nebukadnecaras sapnavo sapnus, nuo kurių sunerimo jo dvasia, ir jo miegas pasitraukė nuo jo.'),
  (@b27, 2, 2, 'Tada karalius įsakė sušaukti burtininkus, astrologus, kerėtojus ir kaldėjus, kad išdėstytų karaliui jo sapnus. Taigi jie atėjo ir atsistojo karaliaus akivaizdoje.'),
  (@b27, 2, 3, 'Ir karalius jiems tarė: „Sapnavau sapną, ir mano dvasia sunerimo, kad sužinočiau šį sapną“.'),
  (@b27, 2, 4, 'Tada kaldėjai kalbėjo karaliui siriškai: „O karaliau, gyvuok per amžius; pasakyk sapną savo tarnams, ir mes išdėstysime aiškinimą“.'),
  (@b27, 2, 5, 'Karalius atsakė ir tarė kaldėjams: „Tas reikalas išėjęs iš manęs; jei man neduosite žinoti sapno kartu su jo aiškinimu, būsite sukapoti į gabalus ir jūsų namai bus paversti mėšlo krūva.'),
  (@b27, 2, 6, 'Bet jei išdėstysite sapną ir jo aiškinimą, gausite iš manęs dovanų, atpildą ir didelę garbę; taigi išdėstykite man sapną ir jo aiškinimą“.'),
  (@b27, 2, 7, 'Jie vėl atsakė ir tarė: „Tegul karalius pasako sapną savo tarnams, ir mes išdėstysime jo aiškinimą“.'),
  (@b27, 2, 8, 'Karalius atsakė ir tarė: „Tikrai žinau, kad norite laimėti laiko, nes pamatėte, kad tas dalykas išėjęs iš manęs.'),
  (@b27, 2, 9, 'Bet jei man neduosite žinoti sapno, jums tik vienas įsakas; nes jūs pasiruošėte kalbėti mano akivaizdoje melagingus ir iškreiptus žodžius, kol laikas pasikeis; taigi pasakykite man sapną, ir aš žinosiu, kad galite man išdėstyti jo aiškinimą“.'),
  (@b27, 2, 10, 'Kaldėjai atsakė karaliaus akivaizdoje, ir tarė: „Nėra žemėje žmogaus, kuris galėtų išdėstyti karaliaus reikalą; todėl nėra karaliaus, viešpaties ar valdovo, kuris būtų klausinėjęs tokių dalykų iš kokio nors burtininko ar astrologo, ar kaldėjo.'),
  (@b27, 2, 11, 'Dalykas, kurio karalius reikalauja, yra retas, ir nėra jokio kito, kuris galėtų jį išdėstyti karaliaus akivaizdoje, išskyrus dievus, kurių buveinė nėra tarp kūnų“.'),
  (@b27, 2, 12, 'Dėl to karalius supyko ir labai įtūžo, ir įsakė sunaikinti visus Babilono išminčius.'),
  (@b27, 2, 13, 'Ir išėjo įsakas, kad būtų išžudyti išminčiai; ir jie ieškojo Danieliaus bei jo draugų, kad būtų nužudyti.'),
  (@b27, 2, 14, 'Tada Danielius su patarimu ir išmintimi atsakė Arjochui, karaliaus sargybos vadui, kuris buvo išėjęs Babilono išminčių žudyti;'),
  (@b27, 2, 15, 'jis atsakė ir tarė karaliaus vadui Arjochui: „Kodėl šis įsakas nuo karaliaus toks skubotas?“ Tada Arjochas davė žinoti tą dalyką Danieliui.'),
  (@b27, 2, 16, 'Tada Danielius įėjo ir prašė karaliaus duoti jam laiko, kad jis išdėstytų karaliui aiškinimą.'),
  (@b27, 2, 17, 'Paskui Danielius nuėjo į savo namus ir davė tą dalyką žinoti savo draugams Hananijai, Mišaeliui ir Azarijai;'),
  (@b27, 2, 18, 'kad jie prašytų dangaus Dievo gailestingumų dėl šitos paslapties; kad Danielius ir jo draugai nepražūtų su kitais Babilono išminčiais.'),
  (@b27, 2, 19, 'Tada paslaptis buvo atskleista Danieliui nakties regėjime. Tada Danielius palaimino dangaus Dievą.'),
  (@b27, 2, 20, 'Danielius atsakė ir tarė: „Tebūna palaimintas Dievo vardas per amžių amžius, nes jo yra išmintis ir galybė;'),
  (@b27, 2, 21, 'jis pakeičia laikus ir laikotarpius; jis pašalina karalius ir pastato karalius; jis išmintingiems duoda išmintį, ir žinantiems supratimą – pažinimą;'),
  (@b27, 2, 22, 'jis atskleidžia gilybes ir paslaptis; jis žino, kas yra tamsoje, ir šviesa gyvena su juo.'),
  (@b27, 2, 23, 'Tau dėkoju ir tave giriu, o mano tėvų Dieve, kuris man davei išminties ir galybės, ir dabar man davei žinoti, ko prašėme iš tavęs; nes dabar mums davei žinoti karaliaus reikalą“.'),
  (@b27, 2, 24, 'Taigi Danielius įėjo pas Arjochą, kurį karalius buvo paskyręs išnaikinti Babilono išminčius; jis nuėjo ir taip jam tarė: „Nenaikink Babilono išminčių; nuvesk mane karaliaus akivaizdon, ir aš išdėstysiu karaliui aiškinimą“.'),
  (@b27, 2, 25, 'Tada Arjochas skubiai atvedė Danielių karaliaus akivaizdon ir taip jam tarė: „Radau vyrą iš Judos belaisvių, kuris duos karaliui žinoti aiškinimą“.'),
  (@b27, 2, 26, 'Karalius atsakė ir tarė Danieliui, kurio vardas buvo Beltšacaras: „Ar tu gali man duoti žinoti sapną, kurį mačiau, ir jo aiškinimą?“'),
  (@b27, 2, 27, 'Danielius atsakė karaliaus akivaizdoje ir tarė: „Paslapties, kurios karalius reikalavo, išminčiai, astrologai, burtininkai, pranašautojai, negali išdėstyti karaliui;'),
  (@b27, 2, 28, 'bet danguje yra Dievas, kuris atskleidžia paslaptis ir duoda žinoti karaliui Nebukadnecarui, kas bus paskutinėmis dienomis. Tavo sapnas ir regėjimai tavo galvos, tavo lovoje, yra tokie:'),
  (@b27, 2, 29, 'tau, o karaliau, esant lovoje, į galvą atėjo mintys, kas įvyks po to; ir tas, kuris atskleidžia paslaptis, tau duoda žinoti, kas įvyks.'),
  (@b27, 2, 30, 'O dėl manęs, šita paslaptis man buvo apreikšta ne dėl kokios išminties, kurios turėčiau daugiau už bet kurį gyvąjį, bet dėl tų, kurie duos žinoti aiškinimą karaliui, ir kad galėtum pažinoti savo širdies mintis.'),
  (@b27, 2, 31, 'Tu, o karaliau, matei, ir štai didžiulis atvaizdas. Tas didžiulis atvaizdas, kurio blizgesys buvo nepaprastas, stovėjo priešais tave; ir jo išvaizda buvo baisi.'),
  (@b27, 2, 32, 'Šio atvaizdo galva buvo iš gryno aukso, jo krūtinė ir jo rankos iš sidabro, jo pilvas ir jo šlaunys iš žalvario,'),
  (@b27, 2, 33, 'jo blauzdos iš geležies, jo pėdos dalinai iš geležies ir dalinai iš molio.'),
  (@b27, 2, 34, 'Tu matei, kol ne rankomis iškirstas akmuo trenkė atvaizdui į pėdas, kurios buvo iš geležies bei molio, ir jas sutrupino.'),
  (@b27, 2, 35, 'Tada geležis, molis, žalvaris, sidabras ir auksas kartu sutrupėjo ir pasidarė kaip vasaros klojimų pelai; ir juos taip išnešiojo vėjas, kad jiems nerasta jokios vietos; o akmuo, kuris smogė į atvaizdą, tapo dideliu kalnu ir pripildė visą žemę.'),
  (@b27, 2, 36, 'Toks yra sapnas; ir karaliaus akivaizdoje mes pasakysime jo aiškinimą.'),
  (@b27, 2, 37, 'Tu, o karaliau, esi karalių karalius; nes dangaus Dievas tau yra davęs karalystę, galią, stiprybę ir šlovę.'),
  (@b27, 2, 38, 'Ir visur begyvenančius žmonių vaikus, lauko žvėris ir dangaus skrajūnus jis yra atidavęs į tavo rankas ir padaręs tave visų jų valdovu. Tu esi ta auksinė galva.'),
  (@b27, 2, 39, 'O po tavęs iškils kita karalystė, menkesnė už tave, ir kita, trečia karalystė, iš žalvario, kuri viešpataus visai žemei.'),
  (@b27, 2, 40, 'O ketvirtoji karalystė bus stipri kaip geležis; kaip kad geležis viską sutrupina ir pavergia; ir kaip geležis, kuri trupina visas šitas, ji sutrupins ir sudaužys.'),
  (@b27, 2, 41, 'O kad matei pėdas ir pėdų pirštus dalinai iš puodžiaus molio ir dalinai iš geležies, tai karalystė bus pasidalinusi; bet joje bus geležies tvirtumo, kaip kad matei geležį, sumaišytą su klampiu moliu.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b27, 2, 42, 'O kaip pėdų pirštai buvo dalinai iš geležies ir dalinai iš molio, taip ir karalystė bus iš dalies stipri ir iš dalies sudužusi.'),
  (@b27, 2, 43, 'O kad matei geležį, sumaišytą su klampiu moliu, tai jie maišysis su žmonių sėkla; tačiau jie neprilips vienas prie kito, kaip ir geležis nesusimaišo su moliu.'),
  (@b27, 2, 44, 'Ir šitų karalių dienomis dangaus Dievas įkurs karalystę, kuri niekada nebus sunaikinta; ir ta karalystė nebus palikta kitai tautai, bet ji sutrupins ir sunaikins visas šitas karalystes, ir stovės per amžius.'),
  (@b27, 2, 45, 'Kaip kad matei, jog nuo kalno ne rankomis buvo iškirstas akmuo ir kad jis sutrupino geležį, varį, molį, sidabrą ir auksą; didysis Dievas davė karaliui žinoti, kas įvyks po to; tas sapnas yra tikras ir jo aiškinimas tikras“.'),
  (@b27, 2, 46, 'Tada karalius Nebukadnecaras parpuolė veidu į žemę ir pagarbino Danielių, ir įsakė, kad jam atnašautų auką ir kvapius aromatus.'),
  (@b27, 2, 47, 'Karalius atsakė Danieliui ir tarė: „Iš tikrųjų, jūsų Dievas yra dievų Dievas, karalių Viešpats ir paslapčių atskleidėjas, nes tu galėjai atskleisti šitą paslaptį“.'),
  (@b27, 2, 48, 'Tada karalius padarė Danielių didžiu žmogumi, davė jam daug didelių dovanų, padarė jį visos Babilono provincijos valdovu ir valdytojų vyriausiuoju visiems Babilono išminčiams.'),
  (@b27, 2, 49, 'Paskui Danielius prašė karaliaus ir jis paskyrė Šadrachą, Mešachą ir Abed-Negą valdyti Babilono provincijos reikalus; bet Danielius sėdėjo karaliaus vartuose.'),
  (@b27, 3, 1, 'Karalius Nebukadnecaras padarė auksinį atvaizdą šešiasdešimties uolekčių aukščio ir šešių uolekčių pločio, pastatė jį Duros lygumoje, Babilono provincijoje.'),
  (@b27, 3, 2, 'Paskui karalius Nebukadnecaras išsiuntė surinkti kunigaikščių, valdytojų, vadų, teisėjų, iždininkų, patarėjų, teismo prižiūrėtojų ir visų provincijų valdovų, kad atvyktų į pašventimą atvaizdo, kurį pastatė karalius Nebukadnecaras.'),
  (@b27, 3, 3, 'Tada kunigaikščiai, valdytojai, vadai, teisėjai, iždininkai, patarėjai, teismo prižiūrėtojai ir visi provincijų valdovai susirinko į pašventimą atvaizdo, kurį pastatė karalius Nebukadnecaras; ir jie sustojo prieš atvaizdą, kurį Nebukadnecaras pastatė.'),
  (@b27, 3, 4, 'Tada šauklys garsiai šaukė: „Jums, tautos, tautybės ir kalbos, įsakoma:'),
  (@b27, 3, 5, 'tuo metu, kai išgirsite korneto, fleitos, arfos, trombono, psalterio, cimbolų ir visokios muzikos garsą, parpulkite ir pagarbinkite auksinį atvaizdą, kurį pastatė karalius Nebukadnecaras;'),
  (@b27, 3, 6, 'o kas neparpuls ir nepagarbins, tą pačią valandą bus įmestas į degančią, liepsnojančią krosnį“.'),
  (@b27, 3, 7, 'Todėl tuo laiku, kai visos tautos išgirdo korneto, fleitos, arfos, trombono, psalterio ir visokios muzikos garsą, visos tautos, tautybės ir kalbos parpuolė ir pagarbino auksinį atvaizdą, kurį pastatė karalius Nebukadnecaras.'),
  (@b27, 3, 8, 'Todėl tuo metu priėjo kai kurie kaldėjai ir apkaltino žydus.'),
  (@b27, 3, 9, 'Jie kalbėjo ir tarė karaliui Nebukadnecarui: „O karaliau, gyvuok per amžius.'),
  (@b27, 3, 10, 'Tu, o karaliau, išleidai įsaką, kad kiekvienas, kuris išgirs korneto, fleitos, arfos, trombono, psalterio, cimbolų ir visokios muzikos garsą, turės parpulti ir pagarbinti auksinį atvaizdą;'),
  (@b27, 3, 11, 'o kas neparpuls ir nepagarbins, tas turės būti įmestas į degančią, liepsnojančią krosnį.'),
  (@b27, 3, 12, 'Yra kai kurie žydai, kuriuos paskyrei valdyti Babilono provincijos reikalus: Šadrachas, Mešachas ir Abed-Negas; šitie vyrai, o karaliau, nepaiso tavęs: jie netarnauja tavo dievams ir negarbina auksinio atvaizdo, kurį esi pastatęs“.'),
  (@b27, 3, 13, 'Tada, savo įniršyje ir įtūžyje, Nebukadnecaras įsakė atvesti Šadrachą, Mešachą ir Abed-Negą. Tada atvedė tuos vyrus karaliaus akivaizdon.'),
  (@b27, 3, 14, 'Nebukadnecaras kalbėjo ir jiems tarė: „Ar tai tiesa, Šadrachai, Mešachai ir Abed-Negai, kad jūs netarnaujate mano dievams ir negarbinate mano pastatyto auksinio atvaizdo?'),
  (@b27, 3, 15, 'Dabar, jei esate pasiruošę, tuo metu, kai išgirsite korneto, fleitos, arfos, trombono, psalterio, cimbolų ir visokios muzikos garsą, parpulsite ir pagarbinsite atvaizdą, kurį padariau, tai gerai; bet jei nepagarbinsite, tai tą pačią valandą būsite įmesti į degančią, liepsnojančią krosnį; ir koks yra tas Dievas, kuris jus išgelbės iš mano rankų?“'),
  (@b27, 3, 16, 'Šadrachas, Mešachas ir Abed-Negas atsakė ir tarė karaliui: „O Nebukadnecarai, mums nerūpi tau į tai atsakyti.'),
  (@b27, 3, 17, 'Jei taip bus, mūsų Dievas, kuriam tarnaujame, gali mus išgelbėti iš degančios, liepsnojančios krosnies, ir jis mus išvaduos iš tavo rankų, o karaliau.'),
  (@b27, 3, 18, 'O jei ne, tebūna tau žinoma, o karaliau, kad mes netarnausime tavo dievams ir negarbinsime auksinio atvaizdo, kurį pastatei“.'),
  (@b27, 3, 19, 'Tada Nebukadnecaras buvo pilnas įtūžio, ir jo veido išraiška prieš Šadrachą, Mešachą ir Abed-Negą pasikeitė; todėl jis prabilo ir įsakė, kad pakūrentų krosnį septynis kartus daugiau, negu paprastai ji būdavo kūrenama.'),
  (@b27, 3, 20, 'Ir jis įsakė galingiausiems savo kariuomenės vyrams surišti Šadrachą, Mešachą ir Abed-Negą ir įmesti juos į degančią, liepsnojančią krosnį.'),
  (@b27, 3, 21, 'Tada tie vyrai buvo surišti su savo apsiaustais, savo kelnėmis, savo kepurėmis ir kitais savo drabužiais ir buvo įmesti į degančią, liepsnojančią krosnį.'),
  (@b27, 3, 22, 'Kadangi karaliaus įsakymas buvo skubus ir krosnis nepaprastai įkaitinta, tai ugnies liepsna užmušė tuos vyrus, kurie užnešė Šadrachą, Mešachą ir Abed-Negą.'),
  (@b27, 3, 23, 'O šitie trys vyrai – Šadrachas, Mešachas ir Abed-Negas – įkrito surišti į degančią, liepsnojančią krosnį.'),
  (@b27, 3, 24, 'Tada karalius Nebukadnecaras apstulbo ir, skubiai atsistojęs, prabilo ir tarė savo patarėjams: „Argi ne tris vyrus įmetėme surištus į ugnies vidurį?“ Jie atsakydami tarė karaliui: „Tiesa, o karaliau“.'),
  (@b27, 3, 25, 'Jis atsakydamas tarė: „Štai matau keturis vyrus laisvus, vaikštančius vidury ugnies, ir nėra jiems žalos; o ketvirtojo pavidalas panašus į Dievo Sūnų“.'),
  (@b27, 3, 26, 'Tada Nebukadnecaras priėjo prie degančios, liepsnojančios krosnies angos ir prabilęs tarė: „Šadrachai, Mešachai ir Abed-Negai, aukščiausiojo Dievo tarnai, išeikite ir ateikite čia“. Tada Šadrachas, Mešachas ir Abed-Negas išėjo iš ugnies vidurio.'),
  (@b27, 3, 27, 'Ir susirinkę kunigaikščiai, valdytojai, vadai ir karaliaus patarėjai pamatė tuos vyrus, kurių kūnams ugnis neturėjo jokios galios, nei jų galvos plaukai nebuvo apsvilę, nei jų apsiaustai nebuvo pasikeitę, nei ugnies kvapas nebuvo užėjęs ant jų.'),
  (@b27, 3, 28, 'Tada Nebukadnecaras prabilo ir tarė: „Tebūna palaimintas Šadracho, Mešacho ir Abed-Nego Dievas, kuris atsiuntė savo angelą ir išvadavo savo tarnus, kurie pasitikėjo juo ir pakeitė karaliaus žodį, ir atidavė savo kūnus, kad netarnautų ir negarbintų kito dievo, išskyrus savąjį Dievą.'),
  (@b27, 3, 29, 'Todėl išleidžiu įsaką, kad kiekviena tauta, tautybė ir kalba, kuri kalbės bloga prieš Šadracho, Mešacho ir Abed-Nego Dievą, bus sukapota į gabalus ir jų namai paversti mėšlo krūva; nes nėra kito Dievo, kuris galėtų taip išgelbėti“.'),
  (@b27, 3, 30, 'Tada karalius paaukštino Šadrachą, Mešachą ir Abed-Negą Babilono provincijoje.'),
  (@b27, 4, 1, 'Karalius Nebukadnecaras visoms tautoms, tautybėms ir kalboms, kurios gyvena visoje žemėje: „Ramybė tepadaugėja jums.'),
  (@b27, 4, 2, 'Manau, gerai yra paskelbti ženklus ir stebuklus, kuriuos aukščiausiasis Dievas man padarė.'),
  (@b27, 4, 3, 'Kokie dideli jo ženklai! Kokie galingi jo stebuklai! Jo karalystė – amžina karalystė, ir jo valdžia iš kartos į kartą.'),
  (@b27, 4, 4, 'Aš, Nebukadnecaras, buvau ramybėje savo namuose ir klestėjau savo rūmuose.'),
  (@b27, 4, 5, 'Aš mačiau sapną, kuris išgąsdino mane, ir mintys mano lovoje, ir regėjimai mano galvoje kėlė man nerimą.'),
  (@b27, 4, 6, 'Todėl išleidau įsaką atvesti mano akivaizdon visus Babilono išminčius, kad jie man duotų žinoti sapno aiškinimą.'),
  (@b27, 4, 7, 'Tada atėjo burtininkai, astrologai, kaldėjai ir pranašautojai; ir aš pasakiau jų akivaizdoje sapną; bet jie nedavė man žinoti jo aiškinimo.'),
  (@b27, 4, 8, 'Bet pagaliau mano akivaizdon atėjo Danielius, kuris pagal mano dievo vardą vadinasi Beltšacaru ir kuriame yra šventųjų dievų dvasia; ir jo akivaizdoje papasakojau sapną, sakydamas:'),
  (@b27, 4, 9, '„O Beltšacarai, burtininkų valdove, kadangi žinau, kad tavyje yra šventųjų dievų dvasia ir jokia paslaptis nėra tau per sunki, išdėstyk mano sapno regėjimus, kuriuos mačiau, ir jų aiškinimą.'),
  (@b27, 4, 10, 'Tokie buvo mano galvos regėjimai lovoje: aš mačiau, ir štai medis žemės viduryje, ir jo aukštis buvo didelis.'),
  (@b27, 4, 11, 'Medis išaugo ir buvo tvirtas, ir jo aukštis pasiekė dangų, ir buvo matomas visos žemės pakraščiuose;'),
  (@b27, 4, 12, 'jo lapai buvo gražūs ir jo vaisių daug, ir ant jo buvo maisto visiems; lauko žvėrys po juo turėjo paūksmę, ir dangaus skrajūnai gyveno jo šakose, ir iš jo maitinosi visi kūnai.'),
  (@b27, 4, 13, 'Aš mačiau savo galvos regėjimuose, lovoje, štai sargas, šventasis, nusileido iš dangaus;'),
  (@b27, 4, 14, 'jis garsiai šaukė ir taip tarė: „Nukirskite medį ir nukapokite jo šakas, nukratykite jo lapus ir išbarstykite jo vaisius; tegul žvėrys bėga iš po jo ir skrajūnai iš jo šakų;'),
  (@b27, 4, 15, 'tačiau jo šaknų kelmą palikite žemėje su geležiniais ir žalvariniais raiščiais minkštoje lauko žolėje; ir jis tebūna drėkinamas dangaus rasos, ir jo dalis tebūna su žvėrimis žemės žolėje;'),
  (@b27, 4, 16, 'tebūna pakeista jo žmogiška širdis ir tebūna jam duota žvėries širdis; ir septyni laikai tegul praeina pro jį.'),
  (@b27, 4, 17, 'Šis dalykas yra pagal sargų įsaką, ir reikalavimas pagal šventųjų žodį tuo tikslu, idant gyvieji žinotų, kad Aukščiausiasis valdo žmonių karalystėje ir duoda ją tam, kam nori, ir paskiria ją valdyti žemiausiam iš žmonių“.'),
  (@b27, 4, 18, 'Šitą sapną aš, karalius Nebukadnecaras, mačiau. O tu, Beltšacarai, išdėstyk jo aiškinimą, nes visi mano karalystės išminčiai nepajėgia man pareikšti aiškinimo; bet tu gali, nes šventųjų dievų dvasia yra tavyje“.'),
  (@b27, 4, 19, 'Tada Danielius, kurio vardas Beltšacaras, buvo valandai apstulbęs, ir jo mintys kėlė jam nerimą. Karalius prabilęs tarė: „Beltšacarai, tenesukelia tau nerimo sapnas ir jo aiškinimas“. Beltšacaras atsakė ir tarė: „Mano viešpatie, sapnas yra tiems, kurie tavęs nekenčia, ir jo aiškinimas tavo priešams.'),
  (@b27, 4, 20, 'Medis, kurį matei, kuris išaugo ir buvo stiprus, kurio aukštis siekė dangų ir buvo matomas visai žemei,'),
  (@b27, 4, 21, 'kurio lapai buvo gražūs ir kurio vaisių buvo daug, kuriame buvo maisto visiems, po kuriuo gyveno lauko žvėrys ir kurio šakose dangaus skrajūnai turėjo savo buveines, –'),
  (@b27, 4, 22, 'esi tu, o karaliau, kuris išaugai ir tapai stiprus; nes tavo didybė išaugo ir siekia dangų, o tavo valdžia – iki žemės pakraščių.'),
  (@b27, 4, 23, 'O kad karalius matė sargą, šventąjį, nužengiantį iš dangaus ir sakantį: ‘Nukirskite medį ir sunaikinkite jį; tačiau jo šaknų kelmą palikite žemėje su geležiniais ir žalvariniais raiščiais minkštoje lauko žoloje; ir jis tebūna drėkinamas dangaus rasos, ir jo dalis tebūna su lauko žvėrimis, kol septyni laikai praeis pro jį’;'),
  (@b27, 4, 24, 'šitas yra aiškinimas, o karaliau, ir tas yra Aukščiausiojo įsakas, ištiksiantis mano viešpačiui karaliui:'),
  (@b27, 4, 25, 'tave išvarys iš žmonių, tavo buveinė bus su lauko žvėrimis, ir tave maitins žole kaip jaučius, ir tave drėkins dangaus rasa; ir septyni laikai praeis pro tave, kol pažinsi, kad Aukščiausiasis valdo žmonių karalystėje ir ją duoda tam, kam nori.'),
  (@b27, 4, 26, 'O kad įsakė palikti medžio šaknų kelmą, tai tavo karalystė bus tau tvirta po to, kai būsi pažinęs, kad valdo dangūs.'),
  (@b27, 4, 27, 'Todėl, o karaliau, tebūna tau priimtinas mano patarimas: nutrauk savo nuodėmes teisumu ir savo neteisybes, rodydamas gailestingumą vargšams; gal prailgės tavo ramybė“.'),
  (@b27, 4, 28, 'Visa tai atsitiko karaliui Nebukadnecarui.'),
  (@b27, 4, 29, 'Pasibaigus dvylikai mėnesių, jis vaikščiojo Babilono karalystės rūmuose.'),
  (@b27, 4, 30, 'Karalius prabilęs tarė: „Argi tai ne didysis Babilonas, kurį aš pastačiau kaip karalystės namus savo jėgos galybe ir savo didybės garbei?“'),
  (@b27, 4, 31, 'Tam žodžiui tebesant karaliaus burnoje, iš dangaus nusileido balsas, sakydamas: „Tau, karaliau Nebukadnecarai, sakoma: karalystė pasitraukė nuo tavęs.'),
  (@b27, 4, 32, 'Ir išvarys tave iš žmonių, ir tavo buveinė bus su lauko žvėrimis; tave maitins žole kaip jaučius, ir septyni laikai praeis pro tave, kol pažinsi, kad Aukščiausiasis valdo žmonių karalystėje ir ją duoda tam, kam nori“.'),
  (@b27, 4, 33, 'Tą pačią valandą tas dalykas išsipildė Nebukadnecarui; ir jis buvo išvarytas iš žmonių, valgė žolę kaip jaučiai, ir jo kūnas buvo drėkinamas dangaus rasos, kol jo plaukai išaugo, kaip erelių plunksnos, o jo nagai – kaip paukščių nagai.'),
  (@b27, 4, 34, 'O dienoms pasibaigus, aš, Nebukadnecaras, pakėliau savo akis į dangų ir mano supratimas sugrįžo pas mane, ir aš laiminau Aukščiausiąjį, gyriau ir garbinau tą, kuris amžinai gyvena, kurio valdžia – amžina valdžia ir jo karalystė iš kartos į kartą;'),
  (@b27, 4, 35, 'ir visi žemės gyventojai laikomi nieku; jis daro pagal savo valią dangaus kariuomenėje ir tarp žemės gyventojų; ir niekas negali sulaikyti jo rankos ar jam sakyti: „Ką darai?“'),
  (@b27, 4, 36, 'Tuo pačiu metu mano protas sugrįžo pas mane; ir mano karalystės šlovei mano garbė bei spindesys sugrįžo pas mane; ir mano patarėjai ir mano viešpačiai ieškojo manęs; aš buvau įtvirtintas savo karalystėje, ir man buvo pridėta pranokstanti didybė.'),
  (@b27, 4, 37, 'Dabar aš, Nebukadnecaras, giriu, liaupsinu ir garbinu dangaus Karalių, kurio visi darbai yra tiesa ir jo keliai – teismas; o tuos, kurie vaikšto išdidume, jis gali pažeminti“.'),
  (@b27, 5, 1, 'Karalius Belšacaras suruošė didelę puotą tūkstančiui savo viešpačių ir to tūkstančio akivaizdoje gėrė vyną.'),
  (@b27, 5, 2, 'Beragaudamas vyną, Belšacaras įsakė atnešti auksinius ir sidabrinius indus, kuriuos jo tėvas Nebukadnecaras buvo paėmęs iš Jeruzalėje buvusios šventyklos, kad iš jų gertų karalius ir jo kunigaikščiai, jo žmonos ir jo sugulovės.'),
  (@b27, 5, 3, 'Tada atnešė auksinius indus, paimtus iš Dievo namų šventyklos, buvusios Jeruzalėje; ir iš jų gėrė karalius ir jo kunigaikščiai, jo žmonos ir jo sugulovės.'),
  (@b27, 5, 4, 'Jie gėrė vyną ir gyrė auksinius, sidabrinius, žalvarinius, geležinius, medinius ir akmeninius dievus.'),
  (@b27, 5, 5, 'Tą pačią valandą išėjo žmogaus rankos pirštai ir rašė priešais žvakidę ant karaliaus rūmų sienos tinko; ir karalius matė tą dalį rankos, kuri rašė.'),
  (@b27, 5, 6, 'Tada karaliaus veidas pasikeitė, ir jo mintys jam taip sukėlė nerimą, kad jo strėnų sąnariai atsileido ir jo keliai daužėsi vienas į kitą.'),
  (@b27, 5, 7, 'Karalius garsiai sušuko, kad atvestų astrologus, kaldėjus ir pranašautojus. Ir karalius prabilęs tarė Babilono išminčiams: „Kas perskaitys šitą raštą ir man išdėstys jo aiškinimą, tas bus apvilktas skaisčiai raudonu ir turės apie kaklą auksinę grandinę, ir bus trečias valdovas karalystėje“.'),
  (@b27, 5, 8, 'Tada įėjo visi karaliaus išminčiai; bet jie negalėjo nei rašto perskaityti, nei davė karaliui žinoti jo aiškinimą.'),
  (@b27, 5, 9, 'Tada karalius Belšacaras labai sunerimo ir jo veidas pasikeitė jame, o jo viešpačiai buvo apstulbę.'),
  (@b27, 5, 10, 'Na, o dėl karaliaus ir jo viešpačių žodžių karalienė įėjo į puotos namus; ir karalienė prabilo ir tarė: „O karaliau, gyvuok per amžius; tenekelia tau nerimo tavo mintys ir tavo veidas tenepasikeičia;'),
  (@b27, 5, 11, 'tavo karalystėje yra vyras, kuriame yra šventųjų dievų dvasia; tavo tėvo dienomis jame buvo rasta šviesa, supratimas ir išmintis, kaip dievų išmintis; karalius Nebukadnecaras, tavo tėvas, tavo tėvas karalius jį paskyrė burtininkų, astrologų, kaldėjų ir pranašautojų valdovu;'),
  (@b27, 5, 12, 'kadangi nepaprasta dvasia, pažinimas, supratimas, sapnų aiškinimas, sunkių posakių išdėstymas ir abejonių išsprendimas buvo rasti tame Danielyje, kurį karalius pavadino Beltšacaru; dabar tepašaukia Danielių, ir jis išdėstys aiškinimą“.'),
  (@b27, 5, 13, 'Tada Danielius buvo atvestas karaliaus akivaizdon. Ir karalius prabilo bei tarė Danieliui: „Ar tu tas Danielius iš Judos nelaisvės vaikų, kuriuos karalius, mano tėvas, išvedė iš Žydijos?'),
  (@b27, 5, 14, 'Girdėjau apie tave, kad dievų dvasia yra tavyje ir kad tavyje rasta šviesa, supratimas ir nepaprasta išmintis.'),
  (@b27, 5, 15, 'Na, o išminčiai, astrologai buvo atvesti mano akivaizdon, kad perskaitytų šitą raštą ir man duotų žinoti jo aiškinimą; bet jie negalėjo išdėstyti to dalyko aiškinimo;'),
  (@b27, 5, 16, 'o aš girdėjau apie tave, kad gali pateikti aiškinimus ir išspręsti abejones; jei dabar gali perskaityti raštą ir man išdėstyti jo aiškinimą, būsi apvilktas skaisčiai raudonu, turėsi auksinę grandinę apie kaklą ir būsi trečias valdovas karalystėje“.'),
  (@b27, 5, 17, 'Tada Danielius atsakė ir tarė karaliaus akivaizdoje: „Tavo dovanos telieka pas tave, ir duok savo atpildus kitam; tačiau aš perskaitysiu raštą karaliui ir duosiu jam žinoti aiškinimą.'),
  (@b27, 5, 18, 'O karaliau, aukščiausiasis Dievas davė tavo tėvui Nebukadnecarui karalystę, didybę, šlovę ir garbę;'),
  (@b27, 5, 19, 'ir dėl didybės, kurią jis jam davė, visos tautos, tautybės ir kalbos drebėjo ir bijojo prieš jį; ką norėdavo, jis nužudydavo; ką norėdavo, jis palikdavo gyvą; ką norėdavo, jis išaukštindavo, ir ką norėdavo, jis nužemindavo.'),
  (@b27, 5, 20, 'Bet kai jo širdis pasiaukštino ir jo dvasia sukietėjo nuo išdidumo, jis buvo nuverstas nuo savo karališko sosto ir iš jo atėmė jo šlovę;'),
  (@b27, 5, 21, 'ir jis buvo išvarytas iš žmonių sūnų; ir jo širdis pasidarė kaip žvėries, jo buveinė buvo su laukiniais asilais; jį maitino žole kaip jaučius, ir jo kūnas buvo dangaus rasos drėkinamas; kol jis pažino, kad aukščiausiasis Dievas valdo žmonių karalystėje ir paskiria ją valdyti tam, kam jis nori.'),
  (@b27, 5, 22, 'O tu, jo sūnau, Belšacarai, nenužeminai savo širdies, nors visa tai žinojai,'),
  (@b27, 5, 23, 'bet išsikėlei prieš dangaus Viešpatį; jo namų indus atnešė priešais tave, ir tu bei tavo viešpačiai, tavo žmonos ir tavo sugulovės gėrėte iš jų vyną; ir tu gyrei sidabrinius, auksinius, žalvarinius, geležinius, medinius ir akmeninius dievus, kurie nemato, negirdi ir nežino; o Dievo, kurio rankoje yra tavo kvapas ir kurio yra visi tavo keliai, tu nešlovinai;'),
  (@b27, 5, 24, 'tada iš jo buvo pasiųsta rankos dalis ir buvo užrašytas šitas raštas.'),
  (@b27, 5, 25, 'Štai šis yra užrašytasis raštas: ‘MENE, MENE, TEKEL, UPARSIN’.'),
  (@b27, 5, 26, 'Šis yra to dalyko aiškinimas: ‘MENE’ – Dievas suskaičiavo tavo karalystę ir ją užbaigė.'),
  (@b27, 5, 27, '‘TEKEL’ – tu esi pasvertas svarstyklėmis ir rastas nepakankamas.'),
  (@b27, 5, 28, '‘PERES’ – tavo karalystė padalyta ir atiduota medams ir persams“.'),
  (@b27, 5, 29, 'Tada Belšacaras įsakė ir jie apvilko Danielių skaisčiai raudonu, uždėjo auksinę grandinę jam aplink kaklą ir paskelbė apie jį, kad jis turi būti trečias valdovas karalystėje.'),
  (@b27, 5, 30, 'Tą naktį kaldėjų karalius Belšacaras buvo nužudytas.'),
  (@b27, 5, 31, 'Ir medas Darijus perėmė karalystę, būdamas apie šešiasdešimt dvejų metų amžiaus.'),
  (@b27, 6, 1, 'Darijui patiko paskirti karalystei šimtą dvidešimt kunigaikščių, kurie vadovautų visai karalystei;'),
  (@b27, 6, 2, 'o jiems vadovauti – tris pirmininkus, iš kurių Danielius buvo pirmas; kad kunigaikščiai jiems atsiskaitytų, ir karalius neturėtų nuostolio.'),
  (@b27, 6, 3, 'Tada tas Danielius buvo pranašesnis už pirmininkus ir kunigaikščius, nes nepaprasta dvasia buvo jame; ir karalius manė jį paskirti visos karalystės valdovu.'),
  (@b27, 6, 4, 'Tada pirmininkai ir kunigaikščiai siekė surasti priežastį prieš Danielių dėl karalystės; bet negalėjo rasti jokios priežasties nei kaltės; nes jis buvo ištikimas, ir jokios klaidos nei kaltės nebuvo rasta jame.'),
  (@b27, 6, 5, 'Tada tie vyrai sakė: „Mes nerasime prieš šitą Danielių jokios priežasties, nebent ją rasime prieš jį dėl jo Dievo įstatymo“.'),
  (@b27, 6, 6, 'Tada tie pirmininkai ir kunigaikščiai susirinko pas karalių ir taip jam tarė: „Karaliau Darijau, gyvuok per amžius.'),
  (@b27, 6, 7, 'Visi karalystės pirmininkai, valdytojai, kunigaikščiai, patarėjai ir vadai susitarė įsteigti karališkąjį įstatą ir išleisti tvirtą įsaką, kad kiekvienas, kuris per trisdešimt dienų ko nors prašys kokio nors Dievo ar žmogaus, o ne tavęs, o karaliau, būtų įmestas į liūtų narvą.'),
  (@b27, 6, 8, 'Dabar, o karaliau, įtvirtink įsaką ir pasirašyk raštą, kad jis nebūtų pakeičiamas, pagal medų ir persų įstatymą, kuris nesikeičia“.'),
  (@b27, 6, 9, 'Todėl karalius Darijus pasirašė raštą ir įsaką.'),
  (@b27, 6, 10, 'Na, o kai Danielius sužinojo, kad raštas buvo pasirašytas, nuėjo į savo namus; ir jo kambaryje langams esant atvertiems link Jeruzalės, tris kartus per dieną jis atsiklaupdavo ant kelių, melsdavosi ir dėkodavo savo Dievo akivaizdoje, kaip jis darydavo anksčiau.'),
  (@b27, 6, 11, 'Tada šitie vyrai susirinko ir rado Danielių besimeldžiantį ir beprašantį savo Dievo akivaizdoje.'),
  (@b27, 6, 12, 'Tada jie priėjo ir kalbėjo karaliaus akivaizdoje dėl karaliaus įsako: „Argi nepasirašei įsako, kad kiekvienas, kuris per trisdešimt dienų prašys kokio nors Dievo ar žmogaus, bet ne tavęs, o karaliau, bus įmestas į liūtų narvą?“ Karalius atsakė ir tarė: „Tas dalykas tiesa pagal medų ir persų įstatymą, kuris nesikeičia“.'),
  (@b27, 6, 13, 'Tada jie atsiliepdami tarė karaliaus akivaizdoje: „Tas Danielius, iš Judos belaisvių vaikų, nepaiso tavęs, o karaliau, nei įsako, kurį pasirašei, bet tris kartus per dieną atlieka savo prašymus“.'),
  (@b27, 6, 14, 'Tada karalius, išgirdęs tuos žodžius, buvo labai nepatenkintas savimi ir nukreipė savo širdį į Danielių, kad jį išvaduotų; ir ligi saulės laidos stengėsi jį išvaduoti.'),
  (@b27, 6, 15, 'Tada tie vyrai susirinko pas karalių ir tarė karaliui: „Žinok, o karaliau, jog medų ir persų įstatymas yra toks, kad joks karaliaus patvirtintas įsakas ar įstatas negali būti pakeičiamas“.'),
  (@b27, 6, 16, 'Tada, karaliui įsakius, atvedė Danielių ir įmetė į liūtų narvą. Na, o karalius prabilęs tarė Danieliui: „Tavo Dievas, kuriam tu nuolat tarnauji, jis išvaduos tave“.'),
  (@b27, 6, 17, 'Buvo atgabentas akmuo ir uždėtas ant narvo angos; o karalius jį užantspaudavo savo antspaudu ir savo viešpačių antspaudu, kad nebūtų pakeistas ketinimas dėl Danieliaus.'),
  (@b27, 6, 18, 'Paskui karalius nuėjo į savo rūmus ir praleido naktį pasninkaudamas; nei muzikiniai instrumentai nebuvo atnešti jo akivaizdon; ir jo miegas atsitraukė nuo jo.'),
  (@b27, 6, 19, 'Tada, labai anksti ryte, karalius atsikėlė ir skubiai nuėjo prie liūtų narvo.'),
  (@b27, 6, 20, 'Ir prisiartinęs prie narvo, jis šaukė Danieliui raudančiu balsu; ir karalius prabilęs tarė Danieliui: „O Danieliau, gyvojo Dievo tarne, ar tavo Dievas, kuriam tu nuolat tarnauji, pajėgė tave išvaduoti nuo liūtų?“'),
  (@b27, 6, 21, 'Tada Danielius tarė karaliui: „O karaliau, gyvuok per amžius.'),
  (@b27, 6, 22, 'Mano Dievas atsiuntė savo angelą ir taip užčiaupė liūtų nasrus, kad jie nesužeidė manęs; nes jo akivaizdoje manyje buvo rastas nekaltumas; taip pat ir tavo akivaizdoje, o karaliau, nepadariau jokios žalos“.'),
  (@b27, 6, 23, 'Tada karalius dėl jo be galo apsidžiaugė ir įsakė iškelti Danielių iš narvo. Taigi Danielius buvo iškeltas iš narvo, ir jokio sužeidimo nebuvo rasta ant jo, nes jis tikėjo savo Dievu.'),
  (@b27, 6, 24, 'Ir karaliui įsakius, atvedė tuos vyrus, kurie buvo apkaltinę Danielių, ir juos įmetė į liūtų narvą, juos, jų vaikus ir jų žmonas; jie dar nebuvo pasiekę narvo dugno, kai liūtai su jais susidorojo ir sutriuškino visus jų kaulus.'),
  (@b27, 6, 25, 'Paskui karalius Darijus parašė visoms tautoms, tautybėms ir kalboms, kurios gyveno visoje žemėje: „Ramybė tepadaugėja jums.'),
  (@b27, 6, 26, 'Aš išleidžiu įsaką, kad visose mano karalystės valdose žmonės drebėtų ir bijotų Danieliaus Dievo akivaizdoje; nes jis yra gyvasis Dievas, tvirtas per amžius, jo karalystė nesunaikinama, ir jo valdžia bus iki pabaigos.'),
  (@b27, 6, 27, 'Jis gelbsti ir išvaduoja, daro ženklus bei stebuklus danguje ir žemėje; jis išgelbėjo Danielių iš liūtų galios“.'),
  (@b27, 6, 28, 'Taigi šitas Danielius klestėjo karaliaujant Darijui ir karaliaujant persui Kyrui.'),
  (@b27, 7, 1, 'Pirmaisiais Babilono karaliaus Belšacaro metais Danielius sapnavo ir matė savo galvos regėjimus savo lovoje; tada jis užrašė sapną ir papasakojo tų dalykų visumą.'),
  (@b27, 7, 2, 'Danielius kalbėjo ir tarė: „Naktį mačiau savo regėjime, ir štai keturi dangaus vėjai grūmėsi ant Didžiosios jūros.'),
  (@b27, 7, 3, 'Ir iš jūros išlipo keturi dideli žvėrys, kurie skyrėsi vienas nuo kito.'),
  (@b27, 7, 4, 'Pirmasis buvo kaip liūtas ir turėjo erelio sparnus; aš stebėjau, kol jo sparnai buvo nuplėšti, ir jis buvo pakeltas nuo žemės ir pastatytas ant kojų kaip žmogus, ir jam buvo duota žmogaus širdis.'),
  (@b27, 7, 5, 'Ir štai kitas, antras žvėris, panašus į lokį, ir jis buvo pasikėlęs ant vienos pusės ir turėjo tris šonkaulius savo nasruose tarp dantų; ir jam taip pasakė: „Kelkis, ėsk daug mėsos“.'),
  (@b27, 7, 6, 'Po to mačiau, ir štai kitas kaip leopardas, kuris turėjo keturis skrajūno sparnus ant nugaros; taipogi keturias galvas turėjo šis žvėris; ir jam buvo duota valdžia.'),
  (@b27, 7, 7, 'Po to mačiau nakties regėjimuose, ir štai ketvirtas žvėris, bauginantis ir baisus, ir nepaprastai stiprus; ir jis turėjo didelius geležinius dantis; jis rijo ir triuškino, ir mindė kojomis tai, kas buvo likę; jis skyrėsi nuo visų žvėrių, buvusių pirma jo; ir jis turėjo dešimt ragų.'),
  (@b27, 7, 8, 'Aš stebėjau ragus, ir štai tarp jų išdygo kitas, mažas ragas, prieš kurį buvo išrauti su šaknimis trys iš pirmųjų ragų; ir štai tame rage buvo akys lyg žmogaus akys ir burna, kalbanti didžius dalykus.'),
  (@b27, 7, 9, 'Aš mačiau, kol sostai buvo nuversti ir atsisėdo dienų Senolis, kurio drabužis buvo baltas kaip sniegas, o jo galvos plaukai – kaip gryna vilna; jo sostas buvo kaip ugnies liepsna, o jo ratai – kaip deganti ugnis.'),
  (@b27, 7, 10, 'Ugninė srovė liejosi ir tekėjo nuo jo akivaizdos; tūkstančių tūkstančiai jam tarnavo, ir dešimtys tūkstančių kart dešimt tūkstančių stovėjo jo akivaizdoje; teismas atsisėdo, ir knygos buvo atskleistos.'),
  (@b27, 7, 11, 'Tada aš žiūrėjau, nes buvo balsas didžių žodžių, kuriuos kalbėjo ragas; aš žiūrėjau, kol žvėris buvo užmuštas ir jo kūnas sunaikintas bei atiduotas deginančiai ugniai.'),
  (@b27, 7, 12, 'O iš likusių žvėrių buvo atimta jų valdžia; tačiau jiems buvo prailgintas gyvenimas laikui ir metui.'),
  (@b27, 7, 13, 'Aš mačiau nakties regėjimuose, ir štai su dangaus debesimis atėjo tarsi žmogaus Sūnus ir atėjo prie dienų Senolio ir buvo privestas jo akivaizdon.'),
  (@b27, 7, 14, 'Ir jam buvo duota valdžia, šlovė ir karalystė, kad visos tautos, tautybės ir kalbos jam tarnautų; jo valdžia – amžina valdžia, kuri nepraeis, ir jo karalystė tokia, kuri nebus sunaikinta.'),
  (@b27, 7, 15, 'Aš, Danielius, sielvartavau savo dvasioje, savo kūno viduje, ir mano galvos regėjimai kėlė man nerimą.'),
  (@b27, 7, 16, 'Aš priėjau prie vieno iš šalia stovinčių ir paklausiau jo viso to tiesos. Taigi jis man pasakė ir davė man žinoti tų dalykų aiškinimą.'),
  (@b27, 7, 17, '„Šitie dideli žvėrys, kurie yra keturi, yra keturi karaliai, kurie kils iš žemės.'),
  (@b27, 7, 18, 'Bet Aukščiausiojo šventieji ims karalystę ir turės tą karalystę per amžius, per amžių amžius“.'),
  (@b27, 7, 19, 'Tada aš norėjau sužinoti tiesą apie ketvirtąjį žvėrį, kuris skyrėsi nuo visų kitų, nepaprastai baisų, geležiniais dantimis ir žalvariniais nagais, kuris ėdė, triuškino ir mindė kojomis tai, kas buvo likę;'),
  (@b27, 7, 20, 'ir apie dešimt ragų, esančių ant jo galvos, ir apie kitą, kuris išdygo ir prieš kurį trys iškrito; būtent apię tą ragą, kuris turėjo akis bei burną, kalbančią labai didžius dalykus, kuris atrodė didesnis už kitus.'),
  (@b27, 7, 21, 'Aš žiūrėjau, ir tas ragas kariavo su šventaisiais ir juos nugalėjo;'),
  (@b27, 7, 22, 'kol atėjo dienų Senolis, ir Aukščiausiojo šventiesiems buvo duotas teismas; ir atėjo laikas, kai šventieji pasisavino karalystę.'),
  (@b27, 7, 23, 'Jis taip tarė: „Ketvirtasis žvėris bus ketvirta karalystė žemėje, kuri skirsis nuo visų karalysčių ir suris visą žemę, sumindys ją ir sutriuškins.'),
  (@b27, 7, 24, 'O dešimt ragų iš tos karalystės yra dešimt karalių, kurie iškils; o po jų iškils kitas; jis skirsis nuo pirmųjų ir pavergs tris karalius.'),
  (@b27, 7, 25, 'Jis kalbės didžius žodžius prieš Aukščiausiąjį, išsekins Aukščiausiojo šventuosius ir užsimanys pakeisti laikus ir įstatymus; ir jie bus atiduoti į jo rankas iki laiko, laikų ir pusės laiko.'),
  (@b27, 7, 26, 'Bet teismas sėsis, ir jie atims jo valdžią, kad galutinai ją sunaikintų ir sugriautų.'),
  (@b27, 7, 27, 'O karalystė, valdžia ir karalystės didybė po visu dangumi bus duota Aukščiausiojo šventųjų tautai; jo karalystė yra amžina karalystė, ir visos valdžios jam tarnaus ir paklus“.'),
  (@b27, 7, 28, 'Čia baigiasi tas dalykas. Man, Danieliui, mano apmąstymai kėlė didelį nerimą, ir mano veidas ant manęs pasikeitė; bet tą dalyką laikiau savo širdyje.'),
  (@b27, 8, 1, 'Trečiaisiais karaliaus Belšacaro karaliavimo metais man, Danieliui, pasirodė regėjimas po ano, kuris man pirma buvo pasirodęs.'),
  (@b27, 8, 2, 'Ir mačiau regėjime; kai mačiau, įvyko, kad buvau Šušane, rūmuose, esančiuose Elamo provincijoje; ir mačiau regėjime, aš buvau prie Ulajo upės.'),
  (@b27, 8, 3, 'Tada pakėliau savas akis ir pamačiau, ir štai priešais upę stovėjo avinas, turintis du ragus; abu ragai buvo aukšti, bet vienas buvo aukštesnis už kitą, ir aukštesnysis išaugo paskiausiai.'),
  (@b27, 8, 4, 'Mačiau aviną, badantį į vakarus, į šiaurę ir į pietus; kad joks žvėris negalėjo atsilaikyti prieš jį, ir nebuvo nei vieno, kuris būtų galėjęs išvaduoti iš jo rankos; bet jis darė pagal savo norą ir tapo didis.'),
  (@b27, 8, 5, 'Ir man bežiūrint, štai ožys atėjo iš vakarų per visą žemės paviršių, nepaliesdamas žemės; ožys turėjo įsidėmėtiną ragą tarpuakyje.'),
  (@b27, 8, 6, 'Jis atėjo prie du ragus turinčio avino, kurį mačiau stovintį priešais upę, ir savo jėgos įtūžyje puolė jį.'),
  (@b27, 8, 7, 'Mačiau jį priartėjant prie avino ir, prieš jį įpykęs, jis trenkė avinui ir nulaužė jo abu ragus; ir avinas neturėjo jėgų atsilaikyti prieš jį, ir jis pertrenkė jį ant žemės ir sutrypė jį; ir nebuvo nei vieno, kuris būtų galėjęs išvaduoti aviną iš jo rankos.'),
  (@b27, 8, 8, 'Todėl ožys tapo labai didis; o kai jis buvo stiprus, nulūžo didysis ragas; ir jo vietoje išdygo keturi įsidėmėtini ragai, nukreipti į keturis dangaus vėjus.'),
  (@b27, 8, 9, 'Iš vieno iš jų išdygo mažas ragas, kuris tapo nepaprastai didis, pietų, rytų ir gražiosios šalies link.'),
  (@b27, 8, 10, 'Ir jis tapo didžiulis, iki dangaus kariuomenės; jis numetė žemėn kai kuriuos iš kariuomenės ir iš žvaigždžių ir juos sumindė.'),
  (@b27, 8, 11, 'Taip, jis išsiaukštino net iki kariuomenės kunigaikščio, jis pašalino kasdienę auką ir nugriovė jo šventovės vietą.'),
  (@b27, 8, 12, 'Jam buvo duota kariuomenė prieš kasdienę auką dėl nusižengimo, ir ji nuvertė žemėn tiesą; ji veikė ir jai sekėsi.'),
  (@b27, 8, 13, 'Tada girdėjau vieną šventąjį kalbant, o kitas šventasis tarė anam šventajam, kuris kalbėjo: „Kiek ilgai bus regėjimas apie kasdienę auką ir nusiaubiantį nusižengimą, kad duotų šventovę ir kariuomenę trypti po kojomis?“'),
  (@b27, 8, 14, 'Ir jis man tarė: „Iki dviejų tūkstančių trijų šimtų dienų; po to šventovė bus apvalyta“.'),
  (@b27, 8, 15, 'Ir kai aš, Danielius, mačiau tą regėjimą ir ieškojau jo reikšmės, įvyko, kad štai prieš mane stovėjo tarsi vyro atvaizdas.'),
  (@b27, 8, 16, 'Ir išgirdau tarp Ulajo krantų vyro balsą, šaukiantį ir sakantį: „Gabrieliau, duok šitam vyrui suprasti regėjimą“.'),
  (@b27, 8, 17, 'Taigi jis priėjo ten, kur stovėjau; ir jam priėjus, aš išsigandau ir parpuoliau veidu į žemę; bet jis man tarė: „Suprask, o žmogaus sūnau; nes pabaigos laiku bus tas regėjimas“.'),
  (@b27, 8, 18, 'Na, o jam kalbant su manimi, aš buvau giliai įmigęs veidu į žemę; bet jis palietė mane ir pastatė tiesiai.'),
  (@b27, 8, 19, 'Ir jis tarė: „Štai aš tau duosiu žinoti, kas bus pačioje pasipiktinimo pabaigoje; nes pabaiga bus skirtu laiku.'),
  (@b27, 8, 20, 'Avinas, kurį matei turintį du ragus, tai Medijos ir Persijos karaliai.'),
  (@b27, 8, 21, 'O gauruotasis ožys yra Graikijos karalius; didysis ragas, esantis jo tarpuakyje, tai pirmasis karalius.'),
  (@b27, 8, 22, 'Na, o kad tam nulūžus keturi stojosi į jo vietą, tai keturios karalystės stosis iš tos tautos, bet ne su jo jėga.'),
  (@b27, 8, 23, 'Ir jų karalystės paskutiniu laiku, kai nusižengėliai pasieks pilnumą, stosis piktos veido išraiškos karalius, suprantantis paslaptingus posakius.'),
  (@b27, 8, 24, 'Jo jėga bus galinga, bet ne savo paties jėga; jis nuostabiai naikins ir klestės, ir veiks, ir naikins galinguosius ir šventąją tautą.'),
  (@b27, 8, 25, 'Savo sumanumu jis padarys, kad klasta turės pasisekimą jo rankoje; jis išsiaukštins savo širdyje ir per taiką sunaikins daugelį; jis stosis ir prieš kunigaikščių Kunigaikštį; bet jis bus sutriuškintas ne rankomis.'),
  (@b27, 8, 26, 'Papasakotas vakaro ir ryto regėjimas yra tiesa; todėl uždaryk tą regėjimą; nes jis bus daugeliui dienų“.'),
  (@b27, 8, 27, 'Ir aš, Danielius, nusilpau ir sirgau kelias dienas; paskui atsikėliau ir tvarkiau karaliaus reikalus; ir buvau apstulbintas regėjimo, bet niekas jo nesuprato.'),
  (@b27, 9, 1, 'Pirmaisiais metais Ahasvero sūnaus Darijaus, iš medų sėklos, kuris buvo paskirtas kaldėjų karalystės karaliumi;'),
  (@b27, 9, 2, 'pirmaisiais jo karaliavimo metais aš, Danielius, supratau pagal knygas metų skaičių, apie kurį VIEŠPATIES žodis atėjo pranašui Jeremijui, kad jis išpildys septyniasdešimt metų Jeruzalės apleidime.'),
  (@b27, 9, 3, 'Ir aš nukreipiau savo veidą į Viešpatį Dievą, kad siekčiau malda ir prašymais su pasninku, ašutine ir pelenais;'),
  (@b27, 9, 4, 'ir aš meldžiausi VIEŠPAČIUI, savo Dievui, ir išpažinau, sakydamas: „O Viešpatie, didis ir bauginantis Dieve, kuris laikaisi sandoros ir gailestingumo su tais, kurie tave myli ir kurie laikosi tavo įsakymų;'),
  (@b27, 9, 5, 'mes nusidėjome, darėme neteisybę, nedorai elgėmės ir maištavome, pasitraukdami nuo tavo prisakymų bei tavo teismų;'),
  (@b27, 9, 6, 'ir neklausėme tavo tarnų pranašų, kurie kalbėjo tavo vardu mūsų karaliams, mūsų kunigaikščiams, mūsų tėvams ir visai šalies tautai.'),
  (@b27, 9, 7, 'O Viešpatie, teisumas priklauso tau, bet mums – susigėdę veidai, kaip šią dieną; Judos žmonėms, Jeruzalės gyventojams ir visam Izraeliui, esantiems arti ir esantiems toli, visose šalyse, į kurias juos išvarei dėl jų nusižengimo, kuriuo jie nusižengė prieš tave.'),
  (@b27, 9, 8, 'O Viešpatie, mums priklauso susigėdęs veidas, mūsų karaliams, mūsų kunigaikščiams ir mūsų tėvams, nes mes nusidėjome prieš tave.'),
  (@b27, 9, 9, 'Viešpačiui, mūsų Dievui, priklauso gailestingumai ir atleidimai, nors mes maištavome prieš jį;'),
  (@b27, 9, 10, 'ir nepaklusome VIEŠPATIES, mūsų Dievo, balsui, kad vaikščiotume pagal jo įstatymus, kuriuos jis padėjo prieš mus per savo tarnus pranašus.'),
  (@b27, 9, 11, 'Taip, visas Izraelis nusižengė tavo įstatymui, pasitraukdami, kad nepaklustų tavo balsui; todėl ant mūsų išlietas prakeikimas ir priesaika, užrašyta Dievo tarno Mozės įstatyme, nes mes prieš jį nusidėjome.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b27, 9, 12, 'Ir jis patvirtino savo žodžius, kuriuos kalbėjo prieš mus ir prieš mūsų teisėjus, kurie mus teisė, užleisdamas ant mūsų didelę nelaimę; nes po visu dangumi nėra atsitikę taip, kaip atsitiko Jeruzalei.'),
  (@b27, 9, 13, 'Kaip yra parašyta Mozės įstatyme, visa šita nelaimė užėjo ant mūsų; tačiau mes nemaldavome VIEŠPATIES, savo Dievo, akivaizdoje, kad nusigręžtume nuo savo neteisybių ir suprastume tavo tiesą.'),
  (@b27, 9, 14, 'Todėl VIEŠPATS budėjo prie nelaimės ir užleido ją ant mūsų; nes VIEŠPATS, mūsų Dievas, yra teisus visuose savo darbuose, kuriuos jis daro; nes mes nepaklusome jo balsui.'),
  (@b27, 9, 15, 'O dabar, o Viešpatie, mūsų Dieve, kuris galinga ranka išvedei savo tautą iš Egipto šalies ir išgarsinai savo vardą, kaip šią dieną; mes nusidėjome, mes nedorai elgėmės.'),
  (@b27, 9, 16, 'O Viešpatie, pagal visą tavo teisumą, meldžiu tave, tegul tavo pyktis ir tavo įtūžis nusigręžia nuo tavo miesto Jeruzalės, tavo šventojo kalno; nes dėl mūsų nuodėmių ir dėl mūsų tėvų neteisybių Jeruzalė ir tavo tauta tapo priekaištu visiems mūsų aplinkiniams.'),
  (@b27, 9, 17, 'Taigi dabar, o mūsų Dieve, išgirsk savo tarno maldą bei prašymus ir nušvisk savo veidu į savo apleistą šventovę Viešpaties labui.'),
  (@b27, 9, 18, 'O mano Dieve, palenk savo ausį ir išgirsk; atverk savo akis ir pažvelk į mūsų dykvietes ir miestą, pavadintą tavo vardu; nes mes pateikiame prieš tave savo prašymus ne dėl savo teisumų, bet dėl didelių tavo gailestingumų.'),
  (@b27, 9, 19, 'O Viešpatie, išgirsk; o Viešpatie, atleisk; o Viešpatie, išklausyk ir veik; neatidėliok dėl savęs paties, o mano Dieve; nes tavo miestas ir tavo tauta vadinami tavo vardu“.'),
  (@b27, 9, 20, 'Ir man tebekalbant, besimeldžiant ir beišpažįstant savo nuodėmę bei mano tautos Izraelio nuodėmę, ir bepateikiant savo prašymą prieš VIEŠPATĮ, mano Dievą, dėl mano Dievo šventojo kalno;'),
  (@b27, 9, 21, 'man bekalbant maldoje, vyras Gabrielius, kurį pradžioje buvau matęs regėjime, paskatintas greitai atskristi, palietė mane vakarinės aukos metu.'),
  (@b27, 9, 22, 'Jis man pranešė, kalbėjo su manimi ir tarė: „O Danieliau, dabar išėjau tau duoti įgūdžių ir supratimo.'),
  (@b27, 9, 23, 'Tavo prašymų pradžioje išėjo įsakymas, ir aš atėjau tau pranešti; nes tu labai mylimas; todėl suprask tą dalyką ir apsvarstyk regėjimą.'),
  (@b27, 9, 24, 'Septyniasdešimt savaičių skirta tavo tautai ir tavo šventajam miestui, kad užbaigtų nusižengimą, padarytų galą nuodėmėms, atliktų sutaikymą už neteisybę, įvestų amžiną teisumą, užantspauduotų regėjimą bei pranašystę ir pateptų Švenčiausią.'),
  (@b27, 9, 25, 'Taigi žinok ir suprask, kad nuo įsakymo išėjimo atkurti ir statyti Jeruzalę, iki Kunigaikščio Mesijo bus septynios savaitės ir šešiasdešimt dvi savaitės; gatvė ir siena bus atstatyta, netgi neramiais laikais.'),
  (@b27, 9, 26, 'O po šešiasdešimt dviejų savaičių Mesijas bus iškirstas, bet ne dėl savęs; ir ateisiančio kunigaikščio tauta sunaikins miestą ir šventovę; ir to galas bus su potvyniu, ir iki karo pabaigos yra nulemti nusiaubimai.'),
  (@b27, 9, 27, 'Ir jis patvirtins sandorą su daugeliu vienai savaitei; o savaitės viduryje jis sustabdys auką bei aukojimą ir dėl bjaurysčių pasklidimo jis ją nusiaubs iki sunaikinimo, ir tas nulemtas dalykas bus išlietas ant nusiaubimo“.'),
  (@b27, 10, 1, 'Trečiaisiais Persijos karaliaus Kyro metais dalykas buvo apreikštas Danieliui, kuris buvo vadinamas Beltšacaro vardu; ir tas dalykas buvo tikras, bet skirtas laikas buvo tolimas; ir jis suprato tą dalyką, ir turėjo supratimą apie regėjimą.'),
  (@b27, 10, 2, 'Tomis dienomis aš, Danielius, gedėjau pilnas tris savaites.'),
  (@b27, 10, 3, 'Nevalgiau geistinos duonos, nei mėsa, nei vynas neįėjo į mano burną, ir aš visiškai nesitepiau, kol išsipildė trys pilnos savaitės.'),
  (@b27, 10, 4, 'Ir pirmojo mėnesio dvidešimt ketvirtąją dieną, būdamas ant Hidekelio, didžiosios upės, kranto,'),
  (@b27, 10, 5, 'pakėliau akis ir žiūrėjau, ir štai vienas vyras apsivilkęs linu ir susijuosęs strėnas grynu Ufazo auksu;'),
  (@b27, 10, 6, 'jo kūnas buvo kaip berilas, jo veidas – kaip žaibo išvaizda, jo akys – kaip ugnies žibintai, jo rankos ir jo kojos – kaip nublizginto žalvario spalvos, ir jo žodžių balsas – kaip minios balsas.'),
  (@b27, 10, 7, 'Aš, Danielius, vienas temačiau tą regėjimą; nes vyrai, kurie buvo su manimi, nematė to regėjimo; bet ant jų nupuolė didelis šiurpulys, kad jie bėgo pasislėpti.'),
  (@b27, 10, 8, 'Todėl aš pasilikau vienas ir mačiau šitą didį regėjimą, ir manyje nebeliko jėgų; nes mano gražumas manyje pasikeitė į sugedimą, ir manyje nebeliko jėgų.'),
  (@b27, 10, 9, 'Aš dar išgirdau jo žodžių balsą; ir kai išgirdau jo žodžių balsą, tada buvau giliai užmigęs ant veido, veidu į žemę.'),
  (@b27, 10, 10, 'Ir štai ranka palietė mane ir pastatė mane ant kelių ir ant mano rankų delnų.'),
  (@b27, 10, 11, 'Ir jis man tarė: „O Danieliau, didžiai mylimas žmogau, suprask žodžius, kuriuos tau kalbu, ir atsistok tiesiai; nes dabar esu atsiųstas pas tave“. Kai jis man pasakė tą žodį, aš atsistojau drebėdamas.'),
  (@b27, 10, 12, 'Tada jis man tarė: „Nebijok, Danieliau; nes nuo pirmosios dienos, kai nukreipei savo širdį suprasti ir kamuoti save prieš savo Dievą, tavo žodžiai buvo išgirsti, ir aš atėjau dėl tavo žodžių.'),
  (@b27, 10, 13, 'Bet Persijos karalystės kunigaikštis priešinosi man dvidešimt vieną dieną; bet štai Mykolas, vienas iš vyriausiųjų kunigaikščių, atėjo man padėti; ir aš ten pasilikau prie Persijos karalių.'),
  (@b27, 10, 14, 'Dabar atėjau, kad duočiau tau suprasti, kas atsitiks tavo tautai paskutinėmis dienomis; nes regėjimas yra dar daugeliui dienų“.'),
  (@b27, 10, 15, 'Ir kai jis man pasakė tokius žodžius, aš nuleidau savo veidą į žemę ir pasidariau nebylus.'),
  (@b27, 10, 16, 'Ir štai, išvaizda panašus į žmonių sūnus palietė mano lūpas; tada aš atvėriau savo burną ir kalbėjau, ir tariau stovinčiam prieš mane: „O mano viešpatie, dėl regėjimo mane ištiko sielvartas, ir manyje nebeliko jėgų.'),
  (@b27, 10, 17, 'Nes kaip gali tokio mano viešpaties tarnas kalbėti su tokiu mano viešpačiu? Nes aš, aš tuojau pat netekau jėgų, ir kvapo neliko manyje“.'),
  (@b27, 10, 18, 'Tada vėl atėjo ir mane palietė tas, kuris atrodė kaip žmogus, ir jis sustiprino mane,'),
  (@b27, 10, 19, 'ir tarė: „Nebijok, o didžiai mylimas žmogau; tebūna ramybė tau, būk stiprus, taip, būk stiprus“. Ir kai jis man pakalbėjo, aš buvau sustiprintas ir tariau: „Tekalba mano viešpats; nes tu mane sustiprinai“.'),
  (@b27, 10, 20, 'Tada jis tarė: „Ar žinai, kodėl atėjau pas tave? O dabar grįšiu kovoti su Persijos kunigaikščiu; ir kai būsiu išėjęs, štai ateis Graikijos kunigaikštis.'),
  (@b27, 10, 21, 'Bet aš tau paskelbsiu tai, kas užrašyta tiesos Rašte; ir nėra nei vieno, kuris laikytųsi su manimi šiuose dalykuose, išskyrus Mykolą, jūsų kunigaikštį“.'),
  (@b27, 11, 1, '„Taipogi pirmaisiais medo Darijaus metais aš stojausi sutvirtinti ir sustiprinti jį.'),
  (@b27, 11, 2, 'Dabar tau paskelbsiu tiesą. Štai dar trys karaliai stosis Persijoje; o ketvirtasis bus daug turtingesnis, negu jie visi; ir savo stiprybe per savo turtus jis sukels visus prieš Graikijos karalystę.'),
  (@b27, 11, 3, 'Ir stosis galingas karalius, kuris valdys didžiu viešpatavimu ir darys pagal savo valią.'),
  (@b27, 11, 4, 'Ir jam atsistojus jo karalystė subyrės ir bus padalyta keturių dangaus vėjų link; ir ne jo palikuonims, ir ne pagal jo valdžią, kuria jis valdė; nes jo karalystė bus išrauta dėl kitų, neskaitant šitų.'),
  (@b27, 11, 5, 'Ir pietų karalius bus stiprus ir vienas iš jo kunigaikščių; jis bus stipresnis už jį ir viešpataus; jo valdžia bus didelė valdžia.'),
  (@b27, 11, 6, 'Keliems metams pasibaigus, jie susijungs; nes pietų karaliaus duktė atvyks pas šiaurės karalių sudaryti sutarties; bet ji neišlaikys rankos jėgos; ir neišstovės nei jis, nei jo ranka; bet bus atiduota ji, ją atvedusieji, ją pagimdęs ir tas, kuris ją sustiprino šitais laikais.'),
  (@b27, 11, 7, 'Bet iš jos šaknų atžalos vienas stosis jo vietoje, kuris ateis su kariuomene ir įžengs į šiaurės karaliaus tvirtovę, ir imsis prieš juos veiksmų bei nugalės;'),
  (@b27, 11, 8, 'taip pat nugabens nelaisvėn į Egiptą jų dievus su jų kunigaikščiais, su jų brangiais sidabriniais ir auksiniais indais; ir jis išliks daugiau metų negu šiaurės karalius.'),
  (@b27, 11, 9, 'Taigi pietų karalius ateis į jo karalystę ir sugrįš į savo kraštą.'),
  (@b27, 11, 10, 'Bet jo sūnūs bus sukurstyti ir surinks daugybę didelių kariuomenių; vienas tikrai ateis, užlies ir pereis; paskui jis sugrįš ir bus sukurstytas net iki jo tvirtovės.'),
  (@b27, 11, 11, 'Ir pietų karalius įpykęs išeis ir kariaus su juo, būtent su šiaurės karaliumi; ir jis išstatys didelę daugybę; bet ta daugybė bus atiduota į jo rankas.'),
  (@b27, 11, 12, 'Kai jis pašalins tą daugybę, išsiaukštins jo širdis; ir jis nuvers daug dešimčių tūkstančių; bet jis dėl to nesustiprės.'),
  (@b27, 11, 13, 'Nes šiaurės karalius sugrįš ir išstatys daugybę, didesnę už pirmąją, ir po kelerių metų tikrai ateis su didele kariuomene ir su daugybe turtų.'),
  (@b27, 11, 14, 'Ir tais laikais daugelis stosis prieš pietų karalių; taip pat ir tavo tautos plėšikai išsiaukštins, kad įtvirtintų regėjimą; bet jie kris.'),
  (@b27, 11, 15, 'Taigi šiaurės karalius ateis, supils kalną ir paims labiausiai aptvertus miestus; ir pietų kariuomenės neatsilaikys ir jo išrinktieji žmonės, ir nebus jėgų pasipriešinti.'),
  (@b27, 11, 16, 'Bet prieš jį ateinantis darys pagal savo paties valią, ir niekas negalės prieš jį išstovėti; ir jis atsistos šlovingoje šalyje, kuri bus sunaikinta jo rankos.'),
  (@b27, 11, 17, 'Taipogi jis nukreips savo veidą įeiti su visos jo karalystės stiprybe, ir tiesieji su juo; jis taip padarys; ir jis jam duos moterų dukrą, ją sugadindamas; bet ji nesistos jo pusėn ir nebus už jį.'),
  (@b27, 11, 18, 'Po to jis nukreips savo veidą į salas ir paims daugelį; bet savo naudai kunigaikštis padarys galą jo pateiktam priekaištui; be savo priekaišto jis atgręš tą prieš jį patį.'),
  (@b27, 11, 19, 'Tada jis nukreips savo veidą į savo šalies fortą; bet jis suklups ir kris, ir nebus rastas.'),
  (@b27, 11, 20, 'Tada jo vietoje stosis mokesčių sukėlėjas karalystės šlovėje; bet po keleto dienų jis bus sunaikintas ne pykčiu ir ne kovoje.'),
  (@b27, 11, 21, 'Ir jo vietoje stosis niekšas, kuriam nesuteiks karalystės garbės; bet jis įeis taikiai ir įsigys karalystę meilikavimais.'),
  (@b27, 11, 22, 'Ir potvynio rankomis jie bus užlieti nuo jo akivaizdos ir bus sutriuškinti; taip, ir sandoros kunigaikštis.'),
  (@b27, 11, 23, 'Ir po to, kai su juo sudaryta sąjunga, jis veiks klastingai; nes jis ateis aukštyn ir taps stiprus su maža tauta.'),
  (@b27, 11, 24, 'Jis įeis taikiai į riebiausias provincijos vietas; ir jis darys, ko nedarė nei jo tėvai, nei jo tėvų tėvai; jis išmėtys tarp jų grobį, laimikį ir turtus; taip, ir jis sumanys planus prieš tvirtoves, kuriam laikui.'),
  (@b27, 11, 25, 'Jis sukurstys savo jėgą ir savo drąsą su didele kariuomene prieš pietų karalių; ir pietų karalius bus sukurstytas mūšiui su labai didele ir galinga kariuomene; bet jis neatsilaikys; nes prieš jį sumanys planų.'),
  (@b27, 11, 26, 'Tie, kurie maitinasi jo valgio daviniu, sunaikins jį, ir jo kariuomenė pasipils; ir kris daug užmuštų.'),
  (@b27, 11, 27, 'Abiejų šitų karalių širdys bus nusistatę daryti pikta, ir prie vieno stalo jie kalbės melus; bet nesėkmingai, nes galas dar bus paskirtu laiku.'),
  (@b27, 11, 28, 'Tada jis sugrįš į savo šalį su dideliais turtais; ir jo širdis bus prieš šventą sandorą; ir jis imsis žygių ir sugrįš į savo šalį.'),
  (@b27, 11, 29, 'Skirtu laiku jis sugrįš ir ateis link pietų; bet nebus kaip pirmąjį arba kaip paskutinįjį kartą.'),
  (@b27, 11, 30, 'Nes Kitimų laivai atplauks prieš jį; todėl jis sielosis ir sugrįš, ir pasipiktins prieš šventąją sandorą; taip jis darys: jis sugrįš ir susitars su tais, kurie paliko šventąją sandorą.'),
  (@b27, 11, 31, 'Kariuomenės stovės jo pusėje, ir jie suterš stiprybės šventovę, pašalins kasdienę auką ir pastatys nusiaubiančią bjaurybę.'),
  (@b27, 11, 32, 'Tuos, kurie nedorai elgiasi prieš sandorą, jis sugadins meilikavimais; bet tauta, pažįstanti savo Dievą, bus stipri ir imsis žygių.'),
  (@b27, 11, 33, 'Ir turintieji supratimą tautos tarpe, pamokys daugelį; tačiau daugelį dienų jie kris nuo kalavijo, nuo liepsnos, nuo nelaisvės ir nuo apiplėšimo.'),
  (@b27, 11, 34, 'Na, o jiems krentant, jiems bus padėta nedidele pagalba; bet daugelis prilips prie jų meilikaudami.'),
  (@b27, 11, 35, 'Ir kai kurie iš turinčiųjų supratimą kris, kad jie būtų išmėginti, apvalyti ir išbaltinti, iki pabaigos laiko; nes tai dar skirtam laikui.'),
  (@b27, 11, 36, 'Ir karalius elgsis pagal savo valią; jis aukštinsis, laikys save didesniu už visus dievus ir kalbės nuostabius dalykus prieš dievų Dievą, ir jam seksis, kol bus įvykdytas pasipiktinimas; nes turi būti įvykdyta tai, kas nuspręsta.'),
  (@b27, 11, 37, 'Jis nepaisys savo tėvų Dievo nei moterų noro ir nepaisys jokio dievo; nes jis laikys save didesniu už visus.'),
  (@b27, 11, 38, 'Bet jo vietoje jis gerbs jėgų Dievą; dievą, kurio nežinojo jo tėvai, jis garbins auksu, sidabru, brangakmeniais ir geistinais dalykais.'),
  (@b27, 11, 39, 'Taip jis darys stipriausiose tvirtovėse su svetimu dievu, kurį jis pripažins ir pagausins šlove; jis padarys, kad jie valdytų daugelį, ir dėl pelno dalins šalį.'),
  (@b27, 11, 40, 'Ir pabaigos metu pietų karalius badysis prieš jį; ir šiaurės karalius ateis prieš jį kaip viesulas su vežimais, raiteliais ir daugybe laivų; jis įžengs į šalis, užtvindys ir pereis per jas.'),
  (@b27, 11, 41, 'Jis įeis ir į šlovingąją šalį, ir daug šalių bus sugriauta; bet šitie išsigelbės iš jo rankos: Edomas, Moabas ir Amono vaikų vyriausieji.'),
  (@b27, 11, 42, 'Jis išties savo ranką ir į šalis; ir Egipto šalis neišsigelbės.'),
  (@b27, 11, 43, 'Bet jis užvaldys aukso ir sidabro lobius ir visas Egipto brangenybes; libiai ir etiopai seks jo pėdomis.'),
  (@b27, 11, 44, 'Bet žinios iš rytų ir iš šiaurės jam kels nerimą; todėl jis išeis didžiai įtūžęs, kad sunaikintų ir visiškai pražudytų daugelį.'),
  (@b27, 11, 45, 'Ir jis pastatys savo rūmų padangtes tarp jūrų šlovingame šventame kalne; tačiau jis prieis savo galą, ir niekas jam nepadės.'),
  (@b27, 12, 1, 'Ir tuo metu stosis Mykolas, didysis kunigaikštis, kuris užstoja tavo tautos vaikus; ir bus toks vargo laikas, kokio nėra buvę nuo tada, kai buvo tauta, iki to meto; ir tuo metu tavo tauta bus išgelbėta, kiekvienas, kuris bus rastas įrašytas knygoje.'),
  (@b27, 12, 2, 'Ir daugelis iš miegančių žemės dulkėse pabus: vieni amžinam gyvenimui, o kiti gėdai ir amžinai paniekai.'),
  (@b27, 12, 3, 'Ir išmintingieji spindės kaip tvirtumos švytėjimas; ir kurie nukreipė daugelį į teisumą, – kaip žvaigždės per amžių amžius.'),
  (@b27, 12, 4, 'Bet tu, o Danieliau, uždaryk tuos žodžius ir užantspauduok knygą iki pabaigos laiko; daugelis lakstys ten ir atgal, ir pažinimas padidės“.'),
  (@b27, 12, 5, 'Tada aš, Danielius, žiūrėjau, ir štai stovėjo kiti du, vienas ant šito upės kranto, o kitas ant ano upės kranto.'),
  (@b27, 12, 6, 'Ir vienas sakė linu vilkinčiam vyrui, esančiam ant upės vandenų: „Kiek dar ilgai iki šitų nuostabų galo?“'),
  (@b27, 12, 7, 'Ir išgirdau linu apsivilkusį vyrą, esantį ant upės vandenų, kai jis pakėlė savo dešinę ir savo kairę į dangų ir prisiekė amžinai gyvenančiuoju, kad tai bus laiką, laikus ir pusę laiko; ir kai jis užbaigs žlugdyti šventosios tautos jėgą, tada visi šie dalykai bus užbaigti.'),
  (@b27, 12, 8, 'Ir aš girdėjau, bet nesupratau; tada tariau: „O mano Viešpatie, koks bus šių dalykų galas?“'),
  (@b27, 12, 9, 'Ir jis tarė: „Eik savo keliu, Danieliau; nes tie žodžiai yra uždaryti ir užantspauduoti iki pabaigos laiko.'),
  (@b27, 12, 10, 'Daugelis bus apvalyti, išbalinti ir išmėginti; bet nedorėliai elgsis nedorai; ir nei vienas nedorėlis nesupras; bet išmintingieji supras.'),
  (@b27, 12, 11, 'Nuo to laiko, kai kasdienė auka bus pašalinta ir bus pastatyta nusiaubianti bjaurybė, bus tūkstantis du šimtai devyniasdešimt dienų.'),
  (@b27, 12, 12, 'Palaimintas, kuris laukia ir pasiekia tūkstantį tris šimtus trisdešimt penkias dienas.'),
  (@b27, 12, 13, 'Bet tu eik savo keliu, kol bus galas; nes tu ilsėsiesi ir dienų pabaigoje atsistosi ten, kur tavo burtas“.'),
  (@b28, 1, 1, 'VIEŠPATIES žodis, kuris atėjo Beerio sūnui Ozėjui Judos karalių Uzijo, Jotamo, Ahazo ir Ezekijo dienomis ir Jeroboamo, sūnaus Joašo, Izraelio karaliaus, dienomis.'),
  (@b28, 1, 2, 'VIEŠPATIES žodžio pradžia per Ozėją. Ir VIEŠPATS tarė Ozėjui: „Eik, imk sau paleistuvysčių žmoną ir paleistuvysčių vaikus; nes šalis padarė didelę paleistuvystę, pasitraukdama nuo VIEŠPATIES“.'),
  (@b28, 1, 3, 'Taigi jis nuėjo ir paėmė Gomerą, Diblaimo dukterį, kuri pastojo ir pagimdė jam sūnų.'),
  (@b28, 1, 4, 'Ir VIEŠPATS jam tarė: „Pavadink jį Jezreelio vardu; nes dar valandėlė, ir aš atkeršysiu Jehuvo namams už Jezreelio kraują ir padarysiu galą Izraelio namų karalystei.'),
  (@b28, 1, 5, 'Ir tą dieną įvyks, kad aš sulaužysiu Izraelio lanką Jezreelio slėnyje“.'),
  (@b28, 1, 6, 'Ir ji vėl pastojo ir pagimdė dukterį. Ir Dievas jam tarė: „Pavadink ją vardu Lo-Ruhama; nes daugiau nebepasigailėsiu Izraelio namų; bet juos visiškai pašalinsiu.'),
  (@b28, 1, 7, 'Bet Judos namų pasigailėsiu ir juos išgelbėsiu per VIEŠPATĮ, jų Dievą, ir juos gelbėsiu ne lanku, ne kalaviju ir ne mūšiu, ne žirgais ir ne raiteliais“.'),
  (@b28, 1, 8, 'Na, o nujunkiusi Lo-Ruhamą, ji pastojo ir pagimdė sūnų.'),
  (@b28, 1, 9, 'Tada Dievas tarė: „Pavadink jį vardu Lo-Amis, nes jūs ne mano tauta ir aš nebūsiu jūsų Dievas.'),
  (@b28, 1, 10, 'Tačiau Izraelio vaikų skaičius bus kaip jūros smėlis, nesuseikėjamas ir nesuskaičiuojamas; ir įvyks, kad toje vietoje, kur jiems buvo sakoma: ‘Jūs ne mano tauta’, ten jiems bus sakoma: ‘Jūs esate gyvojo Dievo sūnūs’.'),
  (@b28, 1, 11, 'Tada Judos vaikai ir Izraelio vaikai susirinks drauge ir paskirs sau vieną galvą, ir jie ateis aukštyn iš šalies; nes didi bus Jezreelio diena“.'),
  (@b28, 2, 1, '„Sakykite savo broliams: ‘Amnis’ ir savo seserims: ‘Ru-Hama’.'),
  (@b28, 2, 2, 'Bylinėkitės su savo motina, bylinėkitės; nes ji nėra mano žmona, o aš nesu jos vyras; todėl tepašalina ji savo paleistuvystes nuo savo akių ir savo svetimavimus iš savo krūtų tarpo;'),
  (@b28, 2, 3, 'kad nenurengčiau jos nuogai ir nepastatyčiau jos kaip tą dieną, kai ji gimė, kad nepadaryčiau jos kaip dykumos ir kad nepadaryčiau jos kaip sausos žemės ir nenumarinčiau jos troškuliu.'),
  (@b28, 2, 4, 'Nepasigailėsiu jos vaikų, nes jie yra paleistuvysčių vaikai.'),
  (@b28, 2, 5, 'Nes jų motina paleistuvavo; begėdiškai elgėsi ta, kuri buvo jais nėščia; nes ji sakė: ‘Aš eisiu paskui savo meilužius, kurie man duoda mano duonos ir mano vandens, mano vilnų ir mano linų, mano aliejaus ir mano gėrimų’.'),
  (@b28, 2, 6, 'Todėl, štai aš užtversiu tavo kelią erškėčiais ir padarysiu sieną, kad ji neberas savo takų.'),
  (@b28, 2, 7, 'Ji seks paskui savo meilužius, bet jų nepasivys; ji ieškos jų, bet neras; tada ji sakys: ‘Eisiu ir sugrįšiu pas savo pirmąjį vyrą; nes tada man buvo geriau negu dabar’.'),
  (@b28, 2, 8, 'Nes ji nežinojo, kad aš jai daviau javų, vyno ir aliejaus, ir jai padauginau sidabro bei aukso, kurį jie paruošė Baalui.'),
  (@b28, 2, 9, 'Todėl aš sugrįšiu ir atimsiu savo javus jų laiku ir savo vyną jo metu, ir susigrąžinsiu savo vilnas ir savo linus, duotus uždengti jos nuogumui.'),
  (@b28, 2, 10, 'Dabar atidengsiu jos gašlumą jos meilužių akyse, ir niekas jos neišvaduos iš mano rankos.'),
  (@b28, 2, 11, 'Taipogi padarysiu galą visai jos linksmybei, jos švenčių dienoms, jos jaunam mėnuliui, jos sabatams ir visoms jos iškilmėms.'),
  (@b28, 2, 12, 'Ir sunaikinsiu jos vynmedžius ir jos figmedžius, apie kuriuos ji sakė: ‘Tie yra mano apdovanojimai, kuriuos man davė mano meilužiai’; aš juos paversiu mišku, ir juos ės lauko žvėrys.'),
  (@b28, 2, 13, 'Aš aplankysiu ant jos Baalų dienas, kuomet ji degindavo jiems smilkalus, dabindavosi savo auskarais ir savo brangenybėmis ir eidavo paskui savo meilužius, o mane pamiršdavo, – sako VIEŠPATS.'),
  (@b28, 2, 14, '– Todėl štai aš ją viliosiu ir vesiu į dykumą ir paguodžiančiai jai kalbėsiu.'),
  (@b28, 2, 15, 'Ir iš ten jai duosiu jos vynuogynus ir Achoro slėnį kaip vilties duris; ir ji ten giedos, kaip savo jaunystės dienomis, kaip tą dieną, kai ji atėjo aukštyn iš Egipto šalies.'),
  (@b28, 2, 16, 'Ir tą dieną bus, – sako VIEŠPATS, – kad tu mane vadinsi Išiu; ir manęs nebevadinsi Baaliu.'),
  (@b28, 2, 17, 'Nes aš pašalinsiu Baalų vardus iš jos burnos, ir jų nebeprisimins jų vardu.'),
  (@b28, 2, 18, 'Ir tą dieną sudarysiu dėl jų sandorą su lauko žvėrimis, su dangaus skrajūnais ir žemės ropliais; o lanką, kalaviją ir mūšį išlaušiu iš žemės ir leisiu jiems saugiai atsigulti.'),
  (@b28, 2, 19, 'Ir susižadėsiu su tavimi amžiams; taip, susižadėsiu su tavimi teisume, teisme, mylinčiame gerume ir gailestingumuose.'),
  (@b28, 2, 20, 'Susižadėsiu su tavimi ištikimybėje; ir tu pažinsi VIEŠPATĮ.'),
  (@b28, 2, 21, 'Ir tą dieną įvyks, kad aš išgirsiu, – sako VIEŠPATS, – išgirsiu dangus, o jie išgirs žemę;'),
  (@b28, 2, 22, 'žemė išgirs javus, vyną ir aliejų; o jie išgirs Jezreelį.'),
  (@b28, 2, 23, 'Aš ją pasėsiu sau žemėje; ir pasigailėsiu tos, kurios nebuvo pasigailėta; ir sakysiu tiems, kurie nebuvo mano tauta: ‘Tu mano tauta’; o jie sakys: ‘Tu mano Dievas’“.'),
  (@b28, 3, 1, 'Po to VIEŠPATS man tarė: „Eik dar, mylėk moterį, kurią myli jos draugas, nors ji svetimautoja, kaip VIEŠPATS myli Izraelio vaikus, kurie žiūri į kitus dievus ir mėgsta vyno ąsočius“.'),
  (@b28, 3, 2, 'Taigi ją nusipirkau už penkiolika sidabrinių ir už homerą miežių bei pusę homero miežių;'),
  (@b28, 3, 3, 'ir pasakiau jai: „Daug dienų man pasiliksi; tu nepaleistuvausi ir nebūsi jokiam kitam vyrui; taip ir aš būsiu tau“.'),
  (@b28, 3, 4, 'Nes Izraelio vaikai daugelį dienų pasiliks be karaliaus, be kunigaikščio, be aukos, be atvaizdo, be efodo ir be terafimo;'),
  (@b28, 3, 5, 'paskui Izraelio vaikai sugrįš ir ieškos VIEŠPATIES, savo Dievo, ir Dovydo, savo karaliaus; ir paskutinėmis dienomis bijos VIEŠPATIES ir jo gerumo.'),
  (@b28, 4, 1, 'Klausykite VIEŠPATIES žodžio, Izraelio vaikai; nes VIEŠPATS barasi su šalies gyventojais, nes nėra nei tiesos, nei gailestingumo, nei Dievo pažinimo šalyje.'),
  (@b28, 4, 2, 'Keiksmu, melagyste, žudymu, vagyste ir svetimavimu jie pratrūksta, ir kraujas siekia kraują.'),
  (@b28, 4, 3, 'Todėl šalis gedės, ir nusilps visi joje gyvenantys drauge su lauko žvėrimis ir dangaus skrajūnais; taip, ir jūros žuvys atimtos.'),
  (@b28, 4, 4, 'Tačiau niekas tenesiginčija ir kito tenebara; nes tavo tauta yra kaip besiginčijantys su kunigu.'),
  (@b28, 4, 5, 'Todėl tu krisi dieną, taip pat ir pranašas kris su tavimi naktį, ir aš sunaikinsiu tavo motiną.'),
  (@b28, 4, 6, 'Mano tauta sunaikinta dėl pažinimo stokos; kadangi tu atmetei pažinimą, tai ir aš atmesiu tave, kad nebūtum man kunigu; kadangi pamiršai savo Dievo įstatymą, tai ir aš pamiršiu tavo vaikus.'),
  (@b28, 4, 7, 'Kuo labiau jų daugėjo, tuo daugiau jie prieš mane nusidėjo; todėl jų šlovę pakeisiu į gėdą.'),
  (@b28, 4, 8, 'Jie minta mano tautos nuodėme, ir nukreipia savo širdį į jos neteisybę.'),
  (@b28, 4, 9, 'Ir kas bus tautai, tas bus ir kunigui; ir juos nubausiu už jų kelius ir jiems atmokėsiu jų darbus.'),
  (@b28, 4, 10, 'Nes jie valgys, bet nepasisotins; jie paleistuvaus, bet nepadaugės; nes jie nustojo kreipti dėmesį į VIEŠPATĮ.'),
  (@b28, 4, 11, 'Paleistuvystė, vynas ir jaunas vynas atima širdį.'),
  (@b28, 4, 12, 'Mano tauta klausia patarimo iš savo kelmų, ir jų lazda jiems skelbia; nes paleistuvysčių dvasia juos suklaidino, ir jie paleistuvaudami pasitraukė nuo savo Dievo.'),
  (@b28, 4, 13, 'Ant kalnų viršūnių jie aukoja, ant kalvų degina smilkalus, po ąžuolais, tuopomis ir po guobomis, nes geras jų šešėlis; todėl jūsų dukterys paleistuvaus ir jūsų sutuoktinės svetimaus.'),
  (@b28, 4, 14, 'Nebausiu jūsų dukterų, kai jos paleistuvauja, nei jūsų sutuoktinių, kai jos svetimauja; nes jie patys atsiskyrę su paleistuvėmis ir aukoja su ištvirkėlėmis; todėl nesuprantanti tauta kris.'),
  (@b28, 4, 15, 'Nors tu, Izraeli, paleistuvauji, tačiau tenenusikalsta Juda; neikite į Gilgalą ir neikite aukštyn į Bet-Aveną, ir neprisiekite: ‘VIEŠPATS gyvas’.'),
  (@b28, 4, 16, 'Nes Izraelis atsimetė kaip užsispyrusi telyčia; Na, o VIEŠPATS juos ganys kaip avinėlį plačioje vietoje.'),
  (@b28, 4, 17, 'Efraimas susijungęs su stabais; palik jį sau.'),
  (@b28, 4, 18, 'Jų gėrimas rūgštus; jie nuolat paleistuvavo; jo valdovai gėdingai myli: ‘Duokite’.'),
  (@b28, 4, 19, 'Surišo jį vėjas savo sparnais, ir jie gėdysis dėl savo aukų“.'),
  (@b28, 5, 1, '„Išgirskite tai, o kunigai; išklausykite, Izraelio namai; ir jūs, o karaliaus namai, atsukite ausį; nes teismas nukreiptas į jus, nes jūs buvote spąstai Micpai ir ištiestas tinklas ant Taboro.'),
  (@b28, 5, 2, 'Sukilėliai įgudę žudyti, nors aš buvau jų visų barėjas.'),
  (@b28, 5, 3, 'Aš pažįstu Efraimą, Izraelis nepaslėptas nuo manęs; nes dabar tu, Efraimai, paleistuvauji, ir Izraelis suterštas.'),
  (@b28, 5, 4, 'Jų darbai neleidžia jiems sugrįžti pas savo Dievą; nes paleistuvysčių dvasia yra jų tarpe, ir jie nepažino VIEŠPATIES.'),
  (@b28, 5, 5, 'Izraelio išdidumas liudija jam į akis; todėl Izraelis ir Efraimas kris per savo neteisybę; su jais kris ir Juda.'),
  (@b28, 5, 6, 'Su savo kaimenėmis ir savo bandomis jie eis ieškoti VIEŠPATIES; bet jo neras: jis pasitraukė nuo jų.'),
  (@b28, 5, 7, 'Jie išdavikiškai elgėsi prieš VIEŠPATĮ; nes gimdė svetimus vaikus; dabar mėnuo praris juos su jų dalimis.'),
  (@b28, 5, 8, 'Pūskite kornetą Gibėjoje, trimitą Ramoje; garsiai šaukite Bet-Avene: ‘Paskui tave, o Benjaminai’.'),
  (@b28, 5, 9, 'Efraimas bus dykuma barimo dieną; tarp Izraelio genčių daviau žinoti tai, kas tikrai bus.'),
  (@b28, 5, 10, 'Judos kunigaikščiai buvo kaip tie, kurie perkelia ribą; todėl aš ant jų išliesiu savo rūstybę kaip vandenį.'),
  (@b28, 5, 11, 'Efraimas engiamas ir teismo palaužtas, nes noriai ėjo paskui įsakymą.'),
  (@b28, 5, 12, 'Todėl aš būsiu kaip kandis Efraimui ir kaip puvinys Judos namams.'),
  (@b28, 5, 13, 'Kai Efraimas pamatė savo ligą ir Juda pamatė savo žaizdą, tada Efraimas vyko pas asirą ir siuntė pas Jarebo karalių; tačiau jis negalėjo jūsų pagydyti nei užgydyti jūsų žaizdos.'),
  (@b28, 5, 14, 'Nes aš būsiu kaip liūtas Efraimui ir kaip jaunas liūtas Judos namams; aš, būtent aš sudraskysiu ir nueisiu; aš nusinešiu, ir niekas jo neišgelbės.'),
  (@b28, 5, 15, 'Aš eisiu ir sugrįšiu į savo vietą, kol jie pripažins savo nusikaltimą ir ieškos mano veido; savo varge jie anksti ieškos manęs“.'),
  (@b28, 6, 1, 'Ateikite, grįžkime pas VIEŠPATĮ; nes jis sudraskė, jis ir pagydys mus; jis sumušė, jis ir sutvarstys mus.'),
  (@b28, 6, 2, 'Jis atgaivins mus po dviejų dienų; trečiąją dieną jis mus prikels, ir mes gyvensime jo akivaizdoje.'),
  (@b28, 6, 3, 'Tada mes pažinsime, jei toliau seksime pažinti VIEŠPATĮ; jo išėjimas yra paruoštas kaip aušra; ir jis ateis pas mus kaip lietus, kaip vėlyvas ir ankstyvas lietus į žemę.'),
  (@b28, 6, 4, '„Ką tau padarysiu, o Efraimai? Ką tau padarysiu, o Juda? Nes jūsų gerumas kaip ryto debesis ir kaip anksti pradingstanti rasa.'),
  (@b28, 6, 5, 'Todėl tašiau juos per pranašus; žudžiau juos savo burnos žodžiais; ir tavo teismai yra kaip nušvintanti šviesa.'),
  (@b28, 6, 6, 'Nes aš norėjau gailestingumo, o ne aukos; ir Dievo pažinimo labiau negu deginamųjų atnašų.'),
  (@b28, 6, 7, 'Bet jie kaip žmonės nusižengė sandorai; ten jie elgėsi išdavikiškai prieš mane.'),
  (@b28, 6, 8, 'Gileadas – neteisybę darančiųjų miestas, suterštas krauju.'),
  (@b28, 6, 9, 'Kaip plėšikų pulkai tykoja žmogaus, taip kunigų būrys sutartinai žudo kelyje; nes jie elgiasi gašliai.'),
  (@b28, 6, 10, 'Izraelio namuose mačiau siaubingą dalyką: ten Efraimo ištvirkavimas, Izraelis suterštas.'),
  (@b28, 6, 11, 'Tau, Juda, taip pat paruošta pjūtis, kai sugrąžinsiu savo tautos nelaisvę“.'),
  (@b28, 7, 1, '„Kai norėjau pagydyti Izraelį, tada pasirodė Efraimo neteisybė ir Samarijos nedorybė; nes jie melagingai elgiasi; vagis įeina į vidų, o plėšikų pulkas apiplėšia lauke.'),
  (@b28, 7, 2, 'Ir jie neapgalvoja savo širdyse, kad aš atsimenu visą jų nedorybę; dabar juos apsupo jų pačių darbai; jie yra mano akivaizdoje.'),
  (@b28, 7, 3, 'Savo nedorybe jie linksmina karalių ir savo melais – kunigaikščius.'),
  (@b28, 7, 4, 'Jie visi svetimautojai, kaip pakūrenta krosnis kepėjo, kuris liaujasi kėlęsis po tešlos užminkymo, kol ji bus įrūgusi.'),
  (@b28, 7, 5, 'Mūsų karaliaus dieną kunigaikščiai susargdino jį buteliais vyno; jis ištiesė savo ranką su išjuokėjais.'),
  (@b28, 7, 6, 'Nes kol tykojo, jie paruošė savo širdis kaip krosnį; jų kepėjas miega visą naktį; ryte ji dega kaip liepsnojanti ugnis.'),
  (@b28, 7, 7, 'Jie visi įkaitę kaip krosnis, prarijo savo teisėjus; visi jų karaliai kritę; nei vienas tarp jų nesišaukia manęs.'),
  (@b28, 7, 8, 'Efraimas – jis įsimaišęs tarp tautų; Efraimas – neapverstas paplotis.'),
  (@b28, 7, 9, 'Svetimšaliai rijo jo stiprybę, o jis to nežino; taip, ant jo žili plaukai čia ir ten, tačiau jis nežino.'),
  (@b28, 7, 10, 'Izraelio išdidumas liudija jam į akis; bet jie negrįžta pas VIEŠPATĮ, savo Dievą, ir neieško jo dėl viso to.'),
  (@b28, 7, 11, 'Efraimas taipogi kaip kvailas karvelis, be širdies: jie šaukiasi Egipto, jie eina į Asiriją.'),
  (@b28, 7, 12, 'Kai jie eis, aš ištiesiu ant jų savo tinklą; kaip dangaus skrajūnus juos nutrauksiu žemyn; nubausiu juos, kaip girdėjo jų susirinkimas.'),
  (@b28, 7, 13, 'Vargas jiems! Nes jie pabėgo nuo manęs; sunaikinimas jiems! Nes jie nusižengė prieš mane; nors aš juos atpirkau, tačiau jie kalbėjo melus prieš mane.'),
  (@b28, 7, 14, 'Ir jie nesišaukė manęs savo širdimi, kai kaukė savo guoliuose; jie susirinko dėl javų ir vyno ir maištavo prieš mane.'),
  (@b28, 7, 15, 'Nors aš surišau ir sustiprinau jų rankas, tačiau jie sumano piktadarystę prieš mane.'),
  (@b28, 7, 16, 'Jie grįžta, bet ne pas Aukščiausiąjį; jie yra kaip apgaulingas lankas; jų kunigaikščiai kris nuo kalavijo dėl jų liežuvio įniršio; tai bus jų išjuokimas Egipto šalyje“.'),
  (@b28, 8, 1, '„Pridėk trimitą sau prie burnos. Jis ateis kaip erelis prieš VIEŠPATIES namus, kadangi jie pažeidė mano sandorą ir nusižengė prieš mano įstatymą.'),
  (@b28, 8, 2, 'Izraelis šauksis manęs: ‘Mano Dieve, mes pažįstame tave’.'),
  (@b28, 8, 3, 'Izraelis atmetė tai, kas gera; priešas jį persekios.'),
  (@b28, 8, 4, 'Jie pastatė karalius, bet ne per mane; jie paskyrė kunigaikščius, bet be mano žinios; iš savo sidabro ir savo aukso jie pasidarė stabų, kad būtų iškirsti.'),
  (@b28, 8, 5, 'Tavo veršis atmetė tave, o Samarija; mano pyktis užsidegė prieš juos; kiek dar ilgai bus, kol jie pasieks nekaltumą?');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b28, 8, 6, 'Nes ir jis iš Izraelio: meistras jį padarė; todėl jis ne Dievas; bet Samarijos veršis bus sutrupintas.'),
  (@b28, 8, 7, 'Nes jie sėjo vėją ir pjaus viesulą; jis neturi stiebo; pumpuras neduos miltų; o jei ir duotų, svetimšaliai juos surys.'),
  (@b28, 8, 8, 'Izraelis prarytas; dabar jie bus tarp pagonių kaip negeistinas indas.'),
  (@b28, 8, 9, 'Nes jie yra nuėję aukštyn į Asiriją – vienišą laukinį asilą; Efraimas pasisamdė meilužių.'),
  (@b28, 8, 10, 'Taip, nors jie samdė tarp tautų, dabar juos surinksiu, ir jie truputį sielvartaus dėl kunigaikščių karaliaus naštos.'),
  (@b28, 8, 11, 'Kadangi Efraimas pasidarė daug aukurų nuodėmiavimui, aukurai jam bus nuodėmiavimui.'),
  (@b28, 8, 12, 'Aš jam surašiau didžius savo įstatymo dalykus, bet jie buvo laikomi kaip svetimas dalykas.'),
  (@b28, 8, 13, 'Jie aukoja mėsą kaip mano atnašų aukas ir ją valgo; bet VIEŠPATS jų nepriima; dabar jis atsimins jų neteisybę ir aplankys jų nuodėmes: jie sugrįš į Egiptą.'),
  (@b28, 8, 14, 'Nes Izraelis pamiršo savo Kūrėją ir statosi šventyklas; o Juda daugino aptvertus miestus; bet aš siųsiu ugnį į jo miestus, ir ji surys jo rūmus“.'),
  (@b28, 9, 1, 'Nesidžiauk, o Izraeli, iš džiaugsmo, kaip kitos tautos; nes tu paleistuvaudamas nuėjai nuo savo Dievo, tu pamėgai užmokestį kiekviename javų klojime.'),
  (@b28, 9, 2, 'Klojimas ir vynuogių spaustuvas jų nemaitins, ir jaunas vynas baigsis jame.'),
  (@b28, 9, 3, 'Jie negyvens VIEŠPATIES šalyje; bet Efraimas grįš į Egiptą, ir Asirijoje jie valgys tai, kas nešvaru.'),
  (@b28, 9, 4, 'Jie neaukos VIEŠPAČIUI vyno atnašų nei jie jam patiks; jų aukos jiems bus kaip gedinčiųjų duona: visi, kurie jos valgys, susiterš; nes jų duona jų sielai neįeis į VIEŠPATIES namus.'),
  (@b28, 9, 5, 'Ką darysite iškilmės dieną ir VIEŠPATIES šventės dieną?'),
  (@b28, 9, 6, 'Nes štai jie išėję dėl sunaikinimo; Egiptas juos surinks, Memfis juos palaidos; geistinas vietas jų sidabrui pasisavins dilgėlės; erškėčiai bus jų padangtėse.'),
  (@b28, 9, 7, 'Atėjo aplankymo dienos, atėjo atlyginimo dienos; Izraelis tai žinos; pranašas yra kvailys, dvasinis žmogus yra pamišėlis – dėl daugybės tavo neteisybių ir didelės neapykantos.'),
  (@b28, 9, 8, 'Efraimo sargas buvo su mano Dievu; bet pranašas yra paukštgaudžio žabangos visuose jo keliuose ir neapykanta jo Dievo namuose.'),
  (@b28, 9, 9, 'Jie giliai sugedo, kaip Gibėjos dienomis; todėl jis atsimins jų neteisybę, jis aplankys jų nuodėmes.'),
  (@b28, 9, 10, 'Kaip vynuoges dykumoje aš radau Izraelį; pamačiau jūsų tėvus kaip pirmuosius sunokusius vaisius ant figmedžio jo pirmuoju laiku; bet jie nuėjo į Baal-Peorą ir atsiskyrė tai gėdai; ir jų bjaurystės buvo pagal tai, kaip jie mylėjo.'),
  (@b28, 9, 11, 'O Efraimas – jų šlovė nulėks kaip paukštis, nuo gimimo, nuo įsčių ir nuo pradėjimo.'),
  (@b28, 9, 12, 'Nors jie ir užaugintų savo vaikus, tačiau aš juos atimsiu, kad nebeliktų nei žmogaus; taip, vargas ir jiems, kai pasitrauksiu nuo jų!'),
  (@b28, 9, 13, 'Efraimas, kaip mačiau Tyrą, yra įsodintas gražioje vietoje; bet Efraimas pagimdys savo vaikus žudikui.'),
  (@b28, 9, 14, 'Duok jiems, o VIEŠPATIE; ką tu duosi? Duok jiems persileidžiančias įsčias ir išdžiūvusias krūtis.'),
  (@b28, 9, 15, 'Visa jų nedorybė yra Gilgale; nes ten jų nekenčiau; dėl jų darbų nedorumo juos išvarysiu iš savo namų, aš daugiau jų nebemylėsiu: visi jų kunigaikščiai maištininkai.'),
  (@b28, 9, 16, 'Efraimas sumuštas, jų šaknis sudžiūvusi, jie neduos vaisiaus; taip, nors jie ir pagimdytų, aš užmušiu mylimą jų įsčių vaisių.'),
  (@b28, 9, 17, 'Mano Dievas juos atmes, nes jie neklausė jo; ir jie bus klajūnai tarp tautų.'),
  (@b28, 10, 1, 'Izraelis yra tuščias vynmedis, gimdantis vaisių sau; kuo daugiau jo vaisių, tuo labiau jis daugino aukurus; kuo geresnė jo žemė, tuo gražesnius jie darė atvaizdus.'),
  (@b28, 10, 2, 'Jų širdis pasidalinusi; dabar jie rasis kalti; jis išgriaus jų aukurus, išplėš jų atvaizdus.'),
  (@b28, 10, 3, 'Nes dabar jie sakys: „Mes neturime karaliaus, nes nebijojome VIEŠPATIES; tai ką karalius mums padarytų?“'),
  (@b28, 10, 4, 'Jie kalbėjo žodžius, melagingai prisiekė, sudarydami sandorą; taip teismas išdygsta kaip mauda lauko vagose.'),
  (@b28, 10, 5, 'Dėl Bet-Aveno veršių baiminsis Samarijos gyventojai; nes dėl jų gedės jų tauta ir jų kunigai, kurie jais džiaugėsi dėl jų šlovės, nes ji išėjusi nuo jų.'),
  (@b28, 10, 6, 'Taip pat jie bus nugabenti ir į Asiriją kaip dovana Jarebo karaliui; Efraimas užsitrauks gėdą, Izraelis gėdysis dėl savo sumanymo.'),
  (@b28, 10, 7, 'O Samarija – jos karalius yra iškirstas kaip putos ant vandens.'),
  (@b28, 10, 8, 'Bus sunaikintos ir Aveno aukštumos – Izraelio nuodėmė; erškėčiai ir usnys augs ant jų aukurų; ir jie sakys kalnams: „Apdenkite mus“; ir kalvoms: „Griūkite ant mūsų“.'),
  (@b28, 10, 9, 'O Izraeli, tu nuodėmiavai nuo Gibėjos dienų; ten jie išstovėjo; mūšis Gibėjoje prieš neteisybės vaikus neužklupo jų.'),
  (@b28, 10, 10, 'Tai mano noras, kad juos bausčiau; prieš juos bus surinktos tautos, kai jie save pririš prie savo dviejų vagų.'),
  (@b28, 10, 11, 'Efraimas – kaip išmokyta telyčia, mėgstanti minti javus; bet aš užėjau ant jos gražaus sprando; aš priversiu Efraimą joti; Juda ars, o Jokūbas trupins savo grumstus.'),
  (@b28, 10, 12, 'Sėkite sau teisumu, pjaukite gailestingumu; plėškite savo pūdymą; nes laikas ieškoti VIEŠPATIES, kol jis ateis ir lis teisumu ant jūsų.'),
  (@b28, 10, 13, 'Jūs arėte nedorybę, pjovėte neteisybę; jūs valgėte melų vaisių; kadangi tu pasitikėjai savo keliu, savo galiūnų daugybe.'),
  (@b28, 10, 14, 'Todėl tavo tautos tarpe pakils triukšmas, ir visos tavo tvirtovės bus išplėštos, kaip Šalmanas išplėšė Bat-Arbelį mūšio dieną; motina bus sutraiškyta ant savo vaikų.'),
  (@b28, 10, 15, 'Taip jums padarys Bet-Elis dėl jūsų didelės nedorybės; ryte bus visiškai iškirstas Izraelio karalius.'),
  (@b28, 11, 1, '„Kai Izraelis buvo vaikas, aš jį mylėjau, ir iš Egipto pašaukiau savo sūnų.'),
  (@b28, 11, 2, 'Kaip juos pašaukė, taip jie iš jų išėjo; jie aukojo Baalams ir degino smilkalus raižytiems atvaizdams.'),
  (@b28, 11, 3, 'Taipogi aš mokiau Efraimą vaikščioti, paimdamas juos už rankų; bet jie nepažino, kad aš juos išgydžiau.'),
  (@b28, 11, 4, 'Žmonių virvėmis, meilės raiščiais juos traukiau; buvau jiems kaip tie, kurie nuima jungą nuo jų nasrų, ir padėjau jiems maisto.'),
  (@b28, 11, 5, 'Jis negrįš į Egipto šalį, bet asiras bus jo karalius, nes jie atsisakė sugrįžti.'),
  (@b28, 11, 6, 'Kalavijas pasiliks jo miestuose, sunaikins jo šakas ir jas prarys dėl jų pačių sumanymų.'),
  (@b28, 11, 7, 'Ir mano tauta linkusi atsimesti nuo manęs; nors juos kvietė pas Aukščiausiąjį, nei vienas iš viso nenorėjo jo aukštinti.'),
  (@b28, 11, 8, 'Kaipgi paliksiu tave, Efraimai? Kaipgi atiduosiu tave, Izraeli? Kaipgi tave padarysiu kaip Admą? Kaipgi tave pastatysiu kaip Ceboimą? Apsivertė manyje mano širdis, užsidegė mano gailėjimaisi.'),
  (@b28, 11, 9, 'Nevykdysiu savo įnirtingo pykčio, negrįšiu naikinti Efraimo; nes aš esu Dievas, o ne žmogus; Šventasis tavo tarpe; aš neįžengsiu į miestą.'),
  (@b28, 11, 10, 'Jie vaikščios paskui VIEŠPATĮ; jis riaumos kaip liūtas; kai jis riaumos, drebės vaikai iš vakarų.'),
  (@b28, 11, 11, 'Jie drebės kaip paukščiai iš Egipto ir kaip karveliai iš Asirijos šalies; ir aš juos apgyvendinsiu jų namuose, – sako VIEŠPATS.'),
  (@b28, 11, 12, '– Efraimas apsupa mane melais, o Izraelio namai – apgaule; Bet Juda dar viešpatauja su Dievu ir yra ištikima su šventaisiais”.'),
  (@b28, 12, 1, 'Efraimas ganosi vėju ir seka paskui rytų vėją; jis kasdien daugina melus ir suniokojimą; jie sudaro sandorą su asirais, ir gabenamas aliejus į Egiptą.'),
  (@b28, 12, 2, 'Taipogi VIEŠPATS ginčijasi su Juda ir nubaus Jokūbą pagal jo kelius; atmokės jam pagal jo darbus.'),
  (@b28, 12, 3, 'Įsčiose jis paėmė savo brolį už kulnies ir savo stiprybe jis turėjo galią su Dievu;'),
  (@b28, 12, 4, 'taip, jis turėjo galią prieš angelą ir nugalėjo; jis verkė ir jį maldavo; jis surado jį Bet-Elyje ir ten kalbėjosi su mumis;'),
  (@b28, 12, 5, 'būtent VIEŠPATS, kariuomenių Dievas; VIEŠPATS yra jo atminimas.'),
  (@b28, 12, 6, 'Todėl gręžkis į savo Dievą; laikykis gailestingumo bei teismo ir nuolat lauk savo Dievo.'),
  (@b28, 12, 7, 'Jis yra pirklys, jo rankoje melagingos svarstyklės; jis mėgsta engti.'),
  (@b28, 12, 8, 'Ir Efraimas sako: „Tačiau aš praturtėjau, įsigijau turtų; visame mano triūse neras manyje neteisybės, kuri būtų nuodėmė“.'),
  (@b28, 12, 9, '„O aš, kuris esu VIEŠPATS, tavo Dievas, nuo Egipto šalies, dar kartą tave apgyvendinsiu padangtėse kaip iškilmingos šventės dienomis.'),
  (@b28, 12, 10, 'Taipogi aš kalbėjau per pranašus, padauginau regėjimų ir vartojau palyginimus per pranašų tarnystę“.'),
  (@b28, 12, 11, 'Ar yra Gileade neteisybės? Tikrai jie yra tuštybė; Gilgale jie aukoja jaučius; taip, jų aukurai yra kaip krūvos laukų vagose.'),
  (@b28, 12, 12, 'Jokūbas pabėgo į Sirijos kraštą, Izraelis tarnavo už žmoną, ir už žmoną jis saugojo avis.'),
  (@b28, 12, 13, 'Ir per pranašą VIEŠPATS išvedė Izraelį iš Egipto, ir per pranašą jis buvo išsaugotas.'),
  (@b28, 12, 14, 'Efraimas labai smarkiai kurstė jo pyktį; todėl jis paliks jo kraują ant jo, ir jo priekaištą jo Viešpats sugrąžins ant jo.'),
  (@b28, 13, 1, 'Kai Efraimas kalbėjo drebėdamas, jis išsiaukštino Izraelyje; bet kai jis nusikalto Baalu – mirė.'),
  (@b28, 13, 2, 'O dabar jie vis labiau nusideda ir yra pasidirbę lietų atvaizdų iš savo sidabro, stabų pagal savo supratimą, visa tai – amatininkų darbas; jie sako apie juos: „Žmonės, kurie aukoja, tebučiuoja veršius“.'),
  (@b28, 13, 3, 'Todėl jie bus kaip rytmečio debesis, kaip ankstyva rasa, kuri pranyksta, kaip pelai, viesulo nunešami nuo klojimo, ir kaip dūmai iš kamino.'),
  (@b28, 13, 4, 'Tačiau aš esu VIEŠPATS, tavo Dievas, nuo Egipto šalies, ir tu nepažinsi kito dievo, tik mane; nes be manęs nėra gelbėtojo.'),
  (@b28, 13, 5, 'Aš pažinau tave dykumoje, didžiulės sausros šalyje.'),
  (@b28, 13, 6, 'Jie pasisotino pagal tai, kokia jų ganykla; jiems pasisotinus, išsiaukštino jų širdis; todėl jie pamiršo mane.'),
  (@b28, 13, 7, 'Todėl jiems būsiu kaip liūtas; kaip leopardas stebėsiu juos pakelėje;'),
  (@b28, 13, 8, 'susitiksiu juos kaip netekusi jauniklių meška ir suplėšysiu jų širdiplėvę, ir surysiu juos ten kaip liūtas; laukiniai žvėrys juos sudraskys.'),
  (@b28, 13, 9, 'O Izraeli, tu sunaikinai save; bet manyje yra tavo pagalba.'),
  (@b28, 13, 10, 'Aš būsiu tavo karalius; kur yra dar kitas, galintis tave išgelbėti visuose tavo miestuose, ir tavo teisėjai, apie kuriuos sakei: ‘Duok man karalių ir kunigaikščių’?'),
  (@b28, 13, 11, 'Aš tau daviau karalių savo pyktyje ir atėmiau jį savo rūstybėje.'),
  (@b28, 13, 12, 'Efraimo neteisybė surišta; jo nuodėmė paslėpta.'),
  (@b28, 13, 13, 'Ant jo užeis gimdančiosios sielvartai; jis yra neišmintingas sūnus: nes jis ilgai nepasiliktų toje vietoje, kur prasiveržia vaikai.'),
  (@b28, 13, 14, 'Aš juos išpirksiu iš kapo galios; aš juos atpirksiu iš mirties; o mirtie, aš būsiu tavo rykštės; o kape, aš būsiu tavo sunaikinimas; gailėjimasis bus paslėptas nuo mano akių.'),
  (@b28, 13, 15, 'Nors jis ir būtų vaisingas tarp savo brolių, ateis rytų vėjas, VIEŠPATIES vėjas pakils iš dykumos ir išsausės jo versmė, ir išdžius jo šaltinis; jis išplėš visų geistinų indų lobius.'),
  (@b28, 13, 16, 'Samarija ištuštės; nes ji maištavo prieš savo Dievą; jie kris nuo kalavijo; jų kūdikiai bus sutraiškyti ir jų nėščios moterys bus perskrostos“.'),
  (@b28, 14, 1, '„O Izraeli, grįžk pas VIEŠPATĮ, savo Dievą; nes tu kritai per savo neteisybę.'),
  (@b28, 14, 2, 'Imkite su savimi žodžius ir gręžkitės į VIEŠPATĮ; sakykite jam: ‘Pašalink visas neteisybes ir priimk mus maloningai; taip mes atmokėsime savo lūpų veršiais.'),
  (@b28, 14, 3, 'Ašuras neišgelbės mūsų; mes nejosime ant žirgų; ir nebesakysime savo rankų darbui: ‘Jūs esate mūsų dievai’; nes tavyje našlaitis randa pasigailėjimą.'),
  (@b28, 14, 4, 'Aš išgydysiu jų atsimetimą, mylėsiu juos savanoriškai; nes mano pyktis nusigręžė nuo jo.'),
  (@b28, 14, 5, 'Aš būsiu kaip rasa Izraeliui; jis augs kaip lelija ir išleis savo šaknis kaip Libanas.'),
  (@b28, 14, 6, 'Jo šakos išsikeros, jo grožis bus kaip alyvmedžio ir jo kvapas kaip Libano.'),
  (@b28, 14, 7, 'Gyvenusieji jo šešėlyje sugrįš; jie atsigaus kaip javai ir augs kaip vynmedis; jų kvapas bus kaip Libano vyno.'),
  (@b28, 14, 8, 'Efraimas sakys: ‘Kas man darbo su stabais?’ Aš jį išklausiau ir jį stebėjau; aš esu kaip žaliuojanti eglė. Iš manęs randami tavo vaisiai.'),
  (@b28, 14, 9, 'Kas yra išmintingas ir tai supras? Kas yra protingas ir tai žinos? Nes VIEŠPATIES keliai teisingi, ir teisieji vaikščios jais; bet nusižengėliai juose pargrius“.'),
  (@b29, 1, 1, 'VIEŠPATIES žodis, kuris atėjo Joeliui, Petuelio sūnui.'),
  (@b29, 1, 2, 'Išgirskite tai, seniai, ir atsukite ausį, visi šalies gyventojai. Ar tai yra buvę jūsų dienomis ar jūsų tėvų dienomis?'),
  (@b29, 1, 3, 'Apie tai pasakokite savo vaikams, jūsų vaikai tepasakoja savo vaikams, o jų vaikai – kitai kartai.'),
  (@b29, 1, 4, 'Ką paliko drugio vikšrai, surijo skėriai; ką paliko skėriai, surijo kandžių vikšrai; ką paliko kandžių vikšrai, surijo vikšrai.'),
  (@b29, 1, 5, 'Pabuskite, girtuokliai, ir verkite; kaukite, visi vyno gėrėjai, dėl jauno vyno, nes jis atkirstas nuo jūsų burnos.'),
  (@b29, 1, 6, 'Nes tauta atėjo aukštyn į mano šalį, stipri ir be skaičiaus, kurios dantys – liūto dantys, ir ji turi didelio liūto krūminius dantis.'),
  (@b29, 1, 7, 'Ji nusiaubė mano vynmedį ir nulupo žievę mano figmedžiui; padarė jį visiškai pliką ir numetė jį šalin; jo šakos pasidarė baltos.'),
  (@b29, 1, 8, 'Raudok, kaip apsijuosusi ašutine mergelė dėl savo jaunystės vyro.'),
  (@b29, 1, 9, 'Maisto atnaša ir geriamoji atnaša iškirstos iš VIEŠPATIES namų; gedi kunigai, VIEŠPATIES tarnai.'),
  (@b29, 1, 10, 'Nuniokotas laukas, šalis gedi; nes nuniokoti javai; išdžiūvo jaunas vynas, išseko aliejus.'),
  (@b29, 1, 11, 'Susigėskite, žemdirbiai; kaukite, vynuogininkai dėl kviečių ir dėl miežių; nes lauko derlius pražuvo.'),
  (@b29, 1, 12, 'Vynmedis nudžiūvo ir figmedis nuvyto; granatmedis, taip pat palmė ir obelis, visi lauko medžiai nudžiūvo; nes išdžiūvo žmonių sūnų džiaugsmas.'),
  (@b29, 1, 13, 'Apsijuoskite ir gedėkite, kunigai; kaukite, aukuro tarnai; ateikite, gulėkite visą naktį ašutinėse, mano Dievo tarnai, nes maisto atnaša ir geriamoji atnaša sulaikytos nuo jūsų Dievo namų.'),
  (@b29, 1, 14, 'Pašvęskite pasninką, sušaukite iškilmingą susirinkimą, surinkite vyresniuosius, visus šalies gyventojus į VIEŠPATIES, jūsų Dievo, namus ir šaukitės VIEŠPATIES.'),
  (@b29, 1, 15, 'Oi, kokia diena! Nes VIEŠPATIES diena čia pat, ji ateis kaip sunaikinimas nuo Visagalio.'),
  (@b29, 1, 16, 'Argi ne mūsų akyse atkirstas maistas, taip, linksmybė ir džiūgavimas iš mūsų Dievo namų?'),
  (@b29, 1, 17, 'Supuvo sėklos po savo grumstais, ištuštėję aruodai, nugriauti svirnai; nes javai išdžiūvę.'),
  (@b29, 1, 18, 'Kaip dejuoja gyvuliai! Suglumo galvijų bandos, nes jos neturi ganyklos; taip, apleistos avių kaimenės.'),
  (@b29, 1, 19, 'Tavęs, o VIEŠPATIE, šauksiuosi; nes ugnis surijo dykumos ganyklas ir liepsna sudegino visus lauko medžius.'),
  (@b29, 1, 20, 'Taipogi laukiniai žvėrys šaukiasi tavęs; nes išdžiūvo vandenų upės, ir ugnis surijo dykumos ganyklas.'),
  (@b29, 2, 1, 'Pūskite trimitą Sione ir skelbkite pavojų mano šventajame kalne; tedreba visi šalies gyventojai; nes ateina VIEŠPATIES diena, nes ji yra arti, čia pat;'),
  (@b29, 2, 2, 'tamsos ir niūrumo diena, debesų ir tirštos tamsos diena, kaip rytas apdengia kalnus, būtent didelė ir stipri tauta; panašios į ją niekada nėra buvę ir po jos nebebus per daugelio kartų̃ metus.'),
  (@b29, 2, 3, 'Jų priekyje ryja ugnis, o jų užnugaryje degina liepsna; šalis prieš juos kaip Edeno sodas, o už jų – tuščia dykuma; taip, niekas neišsigelbės nuo jų.'),
  (@b29, 2, 4, 'Jų išvaizda kaip žirgų išvaizda; ir jie lėks kaip raiteliai.'),
  (@b29, 2, 5, 'Jie šokinės kalnų viršūnėmis lyg vežimų bildesys, kaip traškėjimas ugnies liepsnos, ryjančios ražienas, kaip stipri tauta, išsirikiavusi mūšiui.'),
  (@b29, 2, 6, 'Prieš jų veidus tautoms labai skaudės; visi veidai pajuoduos.'),
  (@b29, 2, 7, 'Jie bėgs kaip galiūnai; jie lips į sieną kaip karo vyrai; jie kiekvienas žygiuos savo keliu ir nesuardys savo rikiuotės;'),
  (@b29, 2, 8, 'nei vienas nestumdys vienas kito; jie kiekvienas eis savo taku; ir kai kris ant kalavijo, jie nesusižeis.'),
  (@b29, 2, 9, 'Jie lakstys šen ir ten po miestą; jie bėgs ant sienų, lips į namus; jie įeis pro langus kaip vagis.'),
  (@b29, 2, 10, 'Prieš juos drebės žemė; virpės dangūs; saulė ir mėnulis aptems ir žvaigždės atitrauks savo spindesį;'),
  (@b29, 2, 11, 'ir VIEŠPATS ištars savo balsą savo kariuomenės priešakyje; nes jo stovykla labai didelė; nes stiprus yra tas, kuris vykdo jo žodį; nes VIEŠPATIES diena didi ir labai baisi; kas gali ją iškęsti?'),
  (@b29, 2, 12, '„Todėl ir dabar, – sako VIEŠPATS, – gręžkitės į mane visa savo širdimi, pasninku, verksmu ir gedėjimu“;'),
  (@b29, 2, 13, 'perplėškite savo širdis, o ne savo drabužius, ir gręžkitės į VIEŠPATĮ, savo Dievą; nes jis maloningas ir gailestingas, lėtas pykti ir didžiai geras, ir gailisi dėl nelaimės.'),
  (@b29, 2, 14, 'Kas žino, gal jis sugrįš, gailėsis ir paliks už savęs palaiminimą – maisto atnašą ir geriamąją atnašą VIEŠPAČIUI, jūsų Dievui?'),
  (@b29, 2, 15, 'Pūskite trimitą Sione, pašvęskite pasninką, sušaukite iškilmingą susirinkimą;'),
  (@b29, 2, 16, 'surinkite tautą, pašvęskite susirinkimą, surinkite vyresniuosius, surinkite vaikus ir žįstančius krūtis; teišeina jaunikis iš savo kambario ir jaunoji iš savo kambarėlio.'),
  (@b29, 2, 17, 'Tarp prieangio ir aukuro teverkia kunigai, VIEŠPATIES tarnai, ir tesako: „Pagailėk, o VIEŠPATIE, savo tautos ir neduok savo paveldo priekaištavimui, kad pagonys juos valdytų; kodėl jie turėtų sakyti tarp tautų: ‘Kur yra jų Dievas?’“'),
  (@b29, 2, 18, 'Tada VIEŠPATS pavydės dėl savo šalies ir pasigailės savo tautos.'),
  (@b29, 2, 19, 'Taip, VIEŠPATS atsakys ir tars savo tautai: „Štai aš jums siųsiu javų, vyno ir aliejaus, ir jūs jais pasisotinsite; ir nebedarysiu jūsų priekaištu tarp pagonių;'),
  (@b29, 2, 20, 'bet atitolinsiu nuo jūsų šiaurės kariuomenę ir išvarysiu ją į nevaisingą ir tuščią šalį, jos priekine puse nukreiptą į Rytų jūrą, o jos užpakaline puse nukreiptą į tolimiausią jūrą; ir pakils jos smarvė, pakils jos bjaurus kvapas, nes ji padarė didžių dalykų“.'),
  (@b29, 2, 21, 'Nebijok, o šalie; džiūgauk ir linksminkis; nes VIEŠPATS padarys didžių dalykų.'),
  (@b29, 2, 22, 'Nebijokite, lauko žvėrys; nes žaliuoja dykumos ganyklos, nes medžiai neša savo vaisių, figmedis ir vynmedis duoda savo stiprybę.'),
  (@b29, 2, 23, 'Tad linksminkitės, Siono vaikai, ir džiaukitės VIEŠPAČIU, savo Dievu; nes jis jums saikingai davė ankstyvojo lietaus, ir jis padarys, kad lietus jums lis – ankstyvas lietus ir vėlyvas lietus – pirmąjį mėnesį.'),
  (@b29, 2, 24, 'Ir klojimai bus pilni kviečių, ir statinės liesis per kraštus vynu ir aliejumi.'),
  (@b29, 2, 25, 'Aš jums grąžinsiu metus, kuriuos suėdė skėrys, kandies vikšras, vikšras ir drugio vikšras – mano didžiulė kariuomenė, kurią siunčiau tarp jūsų.'),
  (@b29, 2, 26, 'Ir jūs valgysite gausiai ir pasisotinsite, ir girsite vardą VIEŠPATIES, savo Dievo, kuris nuostabiai pasielgė su jumis; ir mano tauta niekada nebeturės gėdytis.'),
  (@b29, 2, 27, 'Ir jūs žinosite, kad aš esu Izraelio tarpe ir kad aš esu VIEŠPATS, jūsų Dievas, ir nėra kito; ir mano tauta niekada nebeturės gėdytis.'),
  (@b29, 2, 28, 'Ir po to atsitiks, kad aš išliesiu savo Dvasią ant visų kūnų; jūsų sūnūs ir jūsų dukterys pranašaus, jūsų seniai sapnuos sapnus, jūsų jaunuoliai matys regėjimus;'),
  (@b29, 2, 29, 'taip pat ant tarnų ir tarnaičių tomis dienomis išliesiu savo Dvasią.'),
  (@b29, 2, 30, 'Aš parodysiu stebuklų danguose ir žemėje, kraują, ugnį ir dūmų stulpus.'),
  (@b29, 2, 31, 'Saulė pavirs tamsa ir mėnulis krauju, prieš ateinant didžiajai ir baisiajai VIEŠPATIES dienai.'),
  (@b29, 2, 32, 'Ir įvyks, kad kiekvienas, kuris šauksis VIEŠPATIES vardo, bus išgelbėtas; nes Siono kalne ir Jeruzalėje bus išgelbėjimas, kaip VIEŠPATS sakė, likutyje, kurį VIEŠPATS pašauks“.'),
  (@b29, 3, 1, '„Nes štai tomis dienomis, tuo metu, kai sugrąžinsiu Judos ir Jeruzalės nelaisvę,'),
  (@b29, 3, 2, 'aš taip pat surinksiu visas tautas ir nuvesiu jas žemyn į Jehozapato slėnį ir ten bylinėsiuosi su jomis dėl savo tautos ir dėl savo paveldo Izraelio, kurį jos išsklaidė tarp tautų ir padalijo mano šalį.'),
  (@b29, 3, 3, 'Ir dėl mano tautos jie metė burtus; ir davė berniuką už paleistuvę, o mergaitę pardavė už vyną, kad galėtų gerti.'),
  (@b29, 3, 4, 'Taip, kas jums darbo su manimi, o Tyre, Sidone ir vìsos Palestinos ribos? Ar jūs man atmokėsite atlygiu? Ir jei man atlyginsite, aš greitai ir skubiai sugrąžinsiu jūsų atlygį ant jūsų pačių galvų;'),
  (@b29, 3, 5, 'kadangi jūs paėmėte mano sidabrą ir mano auksą ir pargabenote mano gražius geistinus daiktus į savo šventyklas;'),
  (@b29, 3, 6, 'taip pat Judos vaikus ir Jeruzalės vaikus jūs pardavėte graikams, kad nutolintumėte juos nuo jų ribų.'),
  (@b29, 3, 7, 'Štai aš juos iškelsiu iš tos vietos, į kurią juos pardavėte, ir sugrąžinsiu jūsų atlygį ant jūsų pačių galvos;'),
  (@b29, 3, 8, 'ir aš parduosiu jūsų sūnus ir jūsų dukteris į Judos vaikų rankas, o tie juos parduos šebiečiams, tolimai tautai; nes VIEŠPATS tai kalbėjo“.'),
  (@b29, 3, 9, 'Skelbkite tai tarp pagonių: ruoškite karą, pažadinkite galiūnus, tegul artinasi visi karo vyrai; tegul jie ateina aukštyn;'),
  (@b29, 3, 10, 'perkalkite savo noragus į kalavijus ir savo genėjimo peilius į ietis; silpnasis tesako: „Aš stiprus“.'),
  (@b29, 3, 11, 'Susirinkite ir ateikite visi pagonys, ir susirinkite aplinkui; o VIEŠPATIE, ten savo galinguosius atvesk žemyn.'),
  (@b29, 3, 12, '„Teatsikelia pagonys ir ateina aukštyn į Jehozapato slėnį; nes ten aš atsisėsiu teisti visus aplinkinius pagonis.'),
  (@b29, 3, 13, 'Pridėkite pjautuvą, nes pjūtis pribrendusi; ateikite, nusileiskite žemyn; nes spaustuvas pilnas, statinės liejasi per kraštus; nes didelė jų nedorybė“.'),
  (@b29, 3, 14, 'Minios, minios sprendimo slėnyje; nes arti VIEŠPATIES diena sprendimo slėnyje.'),
  (@b29, 3, 15, 'Saulė ir mėnulis aptems, ir žvaigždės atitrauks savo spindesį.'),
  (@b29, 3, 16, 'Taipogi VIEŠPATS riaumos iš Siono ir ištars savo balsą iš Jeruzalės; dangūs ir žemė drebės; bet VIEŠPATS bus savo tautos viltis ir Izraelio vaikų stiprybė.'),
  (@b29, 3, 17, '„Taigi jūs žinosite, kad aš esu VIEŠPATS, jūsų Dievas, gyvenantis Sione, savo šventajame kalne; tada Jeruzalė bus šventa, ir svetimieji nebepereis per ją.'),
  (@b29, 3, 18, 'Ir tą dieną įvyks, kad kalnai varvės jaunu vynu, kalvos liesis pienu, ir visos Judos upės tekės vandenimis, ir šaltinis ištekės iš VIEŠPATIES namų ir drėkins Šitimo slėnį.'),
  (@b29, 3, 19, 'Egiptas bus dykynė, o Edomas bus tuščia dykuma dėl smurto prieš Judos vaikus, kadangi jie išliejo nekaltą kraują jų šalyje.'),
  (@b29, 3, 20, 'Bet Juda gyvens per amžius, o Jeruzalė – iš kartos į kartą.'),
  (@b29, 3, 21, 'Nes aš apvalysiu jų kraują, kurio nebuvau apvalęs; nes VIEŠPATS gyvena Sione“.'),
  (@b30, 1, 1, 'Žodžiai Amoso, buvusio tarp Tekojos kerdžių, kuriuos jis regėjo apie Izraelį Judos karaliaus Uzijo dienomis ir Izraelio karaliaus Joašo sūnaus Jeroboamo dienomis, dvejiems metams prieš žemės drebėjimą.'),
  (@b30, 1, 2, 'Ir jis tarė: „VIEŠPATS riaumos iš Siono ir ištars savo balsą iš Jeruzalės; gedės piemenų buveinės ir nudžius Karmelio viršūnė“.'),
  (@b30, 1, 3, 'Taip sako VIEŠPATS: „Dėl trijų Damasko nusižengimų ir dėl keturių aš neatitrauksiu jo bausmės; nes jie kūlė Gileadą geležiniais kūlimo įrankiais;'),
  (@b30, 1, 4, 'bet aš pasiųsiu ugnį į Hazaelio namus, kuri surys Ben-Hadado rūmus.'),
  (@b30, 1, 5, 'Sulaužysiu ir Damasko skląstį, iškirsiu gyventojus iš Aveno lygumos ir laikantį skeptrą iš Edeno namų; ir Sirijos tauta eis nelaisvėn į Kirą“, – sako VIEŠPATS.'),
  (@b30, 1, 6, 'Taip sako VIEŠPATS: „Dėl trijų Gazos nusižengimų ir dėl keturių aš neatitrauksiu jos bausmės; nes jie išvedė nelaisvėn visus belaisvius, kad juos atiduotų Edomui;'),
  (@b30, 1, 7, 'bet aš pasiųsiu ugnį į Gazos sieną, kuri surys jos rūmus;'),
  (@b30, 1, 8, 'ir iškirsiu iš Ašdodo gyventojus ir iš Aškelono tą, kuris laiko skeptrą, ir atgręšiu savo ranką prieš Ekroną; ir filistinų likutis pražus“, – sako Viešpats DIEVAS.'),
  (@b30, 1, 9, 'Taip sako VIEŠPATS: „Dėl trijų Tyro nusižengimų ir dėl keturių aš neatitrauksiu jo bausmės; nes jie atidavė visus belaisvius Edomui ir neatsiminė broliškos sandoros;'),
  (@b30, 1, 10, 'bet aš pasiųsiu ugnį į Tyro sieną, kuri surys jo rūmus“.'),
  (@b30, 1, 11, 'Taip sako VIEŠPATS: „Dėl trijų Edomo nusižengimų ir dėl keturių aš neatitrauksiu jo bausmės; nes jis kalaviju persekiojo savo brolį ir atmetė visą gailestingumą, ir jo pyktis be perstojo draskė, ir jis visada išlaikė savo rūstybę;'),
  (@b30, 1, 12, 'bet aš pasiųsiu ugnį į Temaną, kuri surys Bocros rūmus“.'),
  (@b30, 1, 13, 'Taip sako VIEŠPATS: „Dėl trijų Amono vaikų nusižengimų ir dėl keturių aš neatitrauksiu jų bausmės; nes jie perskrodė nėščias Gileado moteris, kad išplėstų savo ribas;'),
  (@b30, 1, 14, 'bet aš užkursiu ugnį ant Rabos sienos, ir ji surys jos rūmus su šauksmu mūšio dieną, su audra viesulo dieną;'),
  (@b30, 1, 15, 'ir jų karalius eis nelaisvėn, jis ir jo kunigaikščiai drauge“, – sako VIEŠPATS.'),
  (@b30, 2, 1, 'Taip sako VIEŠPATS: „Dėl trijų Moabo nusižengimų ir dėl keturių neatitrauksiu jo bausmės; nes jis sudegino Edomo karaliaus kaulus iki kalkių;'),
  (@b30, 2, 2, 'bet aš pasiųsiu ugnį į Moabą, ir ji surys Kerijoto rūmus; Moabas mirs esant sumišimui, šauksmui ir trimito garsui;'),
  (@b30, 2, 3, 'ir iškirsiu teisėją iš jo tarpo, ir nužudysiu su juo visus jo kunigaikščius“, – sako VIEŠPATS.'),
  (@b30, 2, 4, 'Taip sako VIEŠPATS: „Dėl trijų Judos nusižengimų ir dėl keturių neatitrauksiu jos bausmės; nes jie niekino VIEŠPATIES įstatymą ir nesilaikė jo įsakymų, ir juos suklaidino jų melai, paskui kuriuos vaikščiojo jų tėvai;'),
  (@b30, 2, 5, 'bet aš pasiųsiu ugnį į Judą, ir ji surys Jeruzalės rūmus“.'),
  (@b30, 2, 6, 'Taip sako VIEŠPATS: „Dėl trijų Izraelio nusižengimų ir dėl keturių aš neatitrauksiu jo bausmės; nes jie pardavė teisųjį už sidabrą ir beturtį už avalynės porą;'),
  (@b30, 2, 7, 'jie trokšta, kad žemės dulkės būtų ant vargšų galvų ir nukreipia į šoną romiųjų kelią; vyras ir jo tėvas įeina pas tą pačią merginą, kad suterštų mano šventąjį vardą;'),
  (@b30, 2, 8, 'jie atsigula ant drabužių, paimtų už užstatą, prie kiekvieno aukuro ir geria pasmerktųjų vyną savo dievo namuose.'),
  (@b30, 2, 9, 'Aš dar sunaikinau jų akivaizdoje amoritą, kurio ūgis buvo kaip kedrų ūgis, ir jis buvo stiprus kaip ąžuolai; aš dar sunaikinau jo vaisius viršuje ir jo šaknis apačioje.'),
  (@b30, 2, 10, 'Taip pat aš atvedžiau jus aukštyn iš Egipto šalies ir vedžiau jus per dykumą keturiasdešimt metų, kad pasisavintumėte amorito šalį.'),
  (@b30, 2, 11, 'Aš prikėliau iš jūsų sūnų į pranašus ir iš jūsų jaunuolių – į nazirus. Ar ne taip, Izraelio vaikai? – sako VIEŠPATS.'),
  (@b30, 2, 12, '– Bet jūs davėte nazirams gerti vyno; ir pranašams įsakėte, sakydami: ‘Nepranašaukite’.'),
  (@b30, 2, 13, 'Štai aš prislėgtas po jumis, kaip prislėgtas vežimas, pilnas pėdų.'),
  (@b30, 2, 14, 'Todėl greitasis negalės pabėgti, stiprusis nesustiprins savo jėgos, ir galingasis neišsigelbės;'),
  (@b30, 2, 15, 'laikantysis lanką neišsilaikys; greitakojis neišsigelbės; ir jojantis ant žirgo neišsigelbės.'),
  (@b30, 2, 16, 'Drąsus tarp galiūnų bėgs nuogas tą dieną“, – sako VIEŠPATS.'),
  (@b30, 3, 1, 'Klausykite šito žodžio, kurį VIEŠPATS kalbėjo prieš jus, o Izraelio vaikai, prieš visą šeimą, kurią aš atvedžiau aukštyn iš Egipto šalies, sakydamas:'),
  (@b30, 3, 2, '„Tik jus aš pažinau iš visų žemės šeimų; todėl jus nubausiu už visas jūsų neteisybes.'),
  (@b30, 3, 3, 'Argi gali dviese eiti kartu, jei nėra susitarę?'),
  (@b30, 3, 4, 'Argi liūtas riaumos miške, neturėdamas grobio? Argi jaunas liūtas išleis balsą iš savo urvo, jei jis nieko nesugavo?');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b30, 3, 5, 'Argi paukštis gali įpulti į spąstus ant žemės, kur jam nėra pinklių? Ar kas pakelia spąstus nuo žemės nieko nepagavęs?'),
  (@b30, 3, 6, 'Argi trimitui mieste pučiant tauta neišsigąsta? Ar yra nelaimė mieste, VIEŠPAČIUI to nepadarius?'),
  (@b30, 3, 7, 'Tikrai Viešpats DIEVAS nieko nedaro, neatskleidęs savo paslapties savo tarnams pranašams.'),
  (@b30, 3, 8, 'Liūtas suriaumojo, kas nebijos? Viešpats DIEVAS kalbėjo, kas nepranašaus?'),
  (@b30, 3, 9, 'Skelbkite rūmuose Ašdode bei rūmuose Egipto šalyje ir sakykite: ‘Susirinkite ant Samarijos kalnų ir pamatykite didelius sąmyšius jos tarpe ir engiamuosius jos tarpe’.'),
  (@b30, 3, 10, 'Nes jie nežino, kaip teisingai elgtis, – sako VIEŠPATS, – jie kaupia smurtą ir apiplėšimą savo rūmuose“.'),
  (@b30, 3, 11, 'Todėl taip sako Viešpats DIEVAS: „Priešininkas bus aplink šalį; ir jis sumažins tavo stiprybę, ir tavo rūmai bus apiplėšti“.'),
  (@b30, 3, 12, 'Taip sako VIEŠPATS: „Kaip piemuo išplėšia iš liūto nasrų porą kojų ar ausies gabalą, taip bus ištraukti Izraelio vaikai, gyvenantys Samarijoje, guolio kampe, ir Damaske lovoje.'),
  (@b30, 3, 13, 'Klausykite ir paliudykite Jokūbo namuose, – sako Viešpats DIEVAS, kariuomenių Dievas, –'),
  (@b30, 3, 14, 'kad tą dieną, kai aplankysiu ant Izraelio jo nusižengimus, aš aplankysiu ir Bet-Elio aukurus: aukuro ragai bus nukirsti ir nukris ant žemės.'),
  (@b30, 3, 15, 'Aš sutriuškinsiu žiemos namus kartu su vasaros namais; pražus dramblio kaulo namai, ir didiesiems namams bus galas“, – sako VIEŠPATS.'),
  (@b30, 4, 1, 'Klausykite šito žodžio jūs, Bašano karvės, esančios Samarijos kalne, engiančios vargšus, slegiančios nepasiturinčiuosius, sakančios savo valdovams: „Atnešk ir gerkime“.'),
  (@b30, 4, 2, 'Viešpats DIEVAS prisiekė savo šventumu, kad štai užeis ant jūsų dienos, kai jus nuves kabliais ir jūsų palikuonis žvejų kabliukais.'),
  (@b30, 4, 3, 'Ir jūs išeisite pro spragas, kiekviena karvė pro esančią jos priešakyje; ir jas numesite į rūmus, – sako VIEŠPATS.'),
  (@b30, 4, 4, '– Ateikite į Bet-Elį ir nusiženkite, dauginkite nusižengimus Gilgale; atneškite kas rytą savo aukas, savo dešimtines po trijų metų;'),
  (@b30, 4, 5, 'atnašaukite padėkos auką su raugu ir pagarsinkite, paskelbkite laisvos valios atnašas; nes tai jums patinka, o Izraelio vaikai, – sako Viešpats DIEVAS.'),
  (@b30, 4, 6, '– Taip pat aš jums daviau švarius dantis visuose jūsų miestuose ir duonos stoką visose jūsų vietovėse; tačiau jūs nesugrįžote pas mane, – sako VIEŠPATS.'),
  (@b30, 4, 7, '– Taip pat aš sulaikiau nuo jūsų lietų, kai dar buvo trys mėnesiai iki pjūties; ir padariau, kad jis lytų ant vieno miesto, ir padariau, kad jis nelytų ant kito miesto; ant vienos dalies lijo, o ta dalis, ant kurios nelijo, išdžiūvo.'),
  (@b30, 4, 8, 'Taip du ar trys miestai klajojo vieno miesto link, vandens atsigerti; bet jie nenumalšino troškulio; tačiau jūs nesugrįžote pas mane, – sako VIEŠPATS.'),
  (@b30, 4, 9, '– Aš jus ištikau džiovinančiu pūtimu ir pelėsiais; kai padaugėjo jūsų sodų ir jūsų vynuogynų, jūsų figmedžių ir jūsų alyvmedžių, juos rijo drugio vikšras; tačiau jūs nesugrįžote pas mane, – sako VIEŠPATS.'),
  (@b30, 4, 10, '– Aš siunčiau tarp jūsų marą, tokį, kaip Egiptui; išžudžiau kalaviju jūsų jaunuolius ir atėmiau jūsų žirgus; ir pakėliau jūsų stovyklos smarvę jums į šnerves; tačiau jūs nesugrįžote pas mane, – sako VIEŠPATS.'),
  (@b30, 4, 11, '– Aš nuverčiau kai kuriuos iš jūsų, kaip Dievas nuvertė Sodomą ir Gomorą, ir jūs buvote kaip nuodėgulis, ištrauktas iš deginimo; tačiau jūs nesugrįžote pas mane, – sako VIEŠPATS.'),
  (@b30, 4, 12, '– Todėl taip tau padarysiu, o Izraeli; ir kadangi tai tau padarysiu, pasiruošk sutikti savo Dievą, o Izraeli.'),
  (@b30, 4, 13, 'Nes štai tas, kuris suformuoja kalnus, sukuria vėją ir paskelbia žmogui, kokia yra jo mintis, kuris aušrą paverčia tamsa ir trypia žemės aukštumas, VIEŠPATS, kariuomenių Dievas, yra jo vardas“.'),
  (@b30, 5, 1, 'Išgirskite šitą žodį, kurio imuosi prieš jus, – raudą, o Izraelio namai.'),
  (@b30, 5, 2, '„Kritusi Izraelio mergelė; ji nebeatsikels; ji apleista savo šalyje; nėra kas ją pakeltų“.'),
  (@b30, 5, 3, 'Nes taip sako Viešpats DIEVAS: „Miestas, kuris išėjo su tūkstančiu, paliks šimtą, o kuris išėjo su šimtu, paliks dešimtį Izraelio namams“.'),
  (@b30, 5, 4, 'Nes taip sako VIEŠPATS Izraelio namams: „Ieškokite manęs, ir jūs gyvensite;'),
  (@b30, 5, 5, 'bet neieškokite Bet-Elio, neikite į Gilgalą ir nepereikite į Beer-Šebą; nes Gilgalas tikrai eis nelaisvėn ir Bet-Elis pavirs nieku“.'),
  (@b30, 5, 6, 'Ieškokite VIEŠPATIES, ir jūs gyvensite; kad jis nepratrūktų Juozapo namuose kaip ugnis ir jo nesurytų, ir nebūtų, kam jo užgesinti Bet-Elyje.'),
  (@b30, 5, 7, 'Jūs, kurie teismą paverčiate metėlėmis ir numetate teisumą žemėje,'),
  (@b30, 5, 8, 'ieškokite to, kuris padaro septynias žvaigždes bei Orioną, ir mirties šešėlį paverčia rytu, o dieną padaro tamsią naktimi; kuris pašaukia jūros vandenis ir išlieja juos ant žemės paviršiaus; VIEŠPATS yra jo vardas;'),
  (@b30, 5, 9, 'kuris sustiprina apiplėštąjį prieš stiprųjį taip, kad apiplėštasis ateina prieš tvirtovę.'),
  (@b30, 5, 10, 'Jie nekenčia to, kuris bara vartuose, ir bjaurisi tuo, kuris kalba tiesiai.'),
  (@b30, 5, 11, 'Todėl, kadangi mindote vargšą ir imate iš jo kviečių naštas; jūs pasistatėte namus iš tašytų akmenų, bet negyvensite juose; jūs pasodinote geistinų vynuogynų, bet negersite jų vyno.'),
  (@b30, 5, 12, 'Nes aš žinau jūsų daugeriopus nusižengimus ir jūsų didžiules nuodėmes; jie sukelia kančias teisiajam, jie ima kyšius ir jie nukreipia vartuose vargšą nuo jo teisių.'),
  (@b30, 5, 13, 'Todėl protingasis tylės tuo metu; nes tai piktas metas.'),
  (@b30, 5, 14, 'Ieškokite gera, o ne pikta, kad gyventumėte; ir taip VIEŠPATS, kariuomenių Dievas, bus su jumis, kaip jūs kalbėjote.'),
  (@b30, 5, 15, 'Nekęskite pikto ir mylėkite gera, ir įtvirtinkite teismą vartuose; galbūt VIEŠPATS, kariuomenių Dievas, bus maloningas Juozapo likučiui.'),
  (@b30, 5, 16, 'Todėl taip sako VIEŠPATS, kariuomenių Dievas, Viešpats: „Visose gatvėse bus aimanavimas; ir visuose vieškeliuose sakys: ‘Vargas! Vargas!’ Žemdirbius pašauks gedėti, ir gabius raudoti – aimanavimui.'),
  (@b30, 5, 17, 'Visuose vynuogynuose bus aimanavimas; nes aš pereisiu per tave“, – sako VIEŠPATS.'),
  (@b30, 5, 18, 'Vargas jums, trokštantiems VIEŠPATIES dienos! Kam ji jums? VIEŠPATIES diena yra tamsa, o ne šviesa.'),
  (@b30, 5, 19, 'Tarsi žmogus bėgtų nuo liūto ir jį pasitiktų lokys; arba įėjus į namus ir atsirėmus ranka į sieną, jį įgeltų gyvatė.'),
  (@b30, 5, 20, 'Argi šviesa bus VIEŠPATIES diena, o ne tamsa, labai tamsi – joje jokios šviesos?'),
  (@b30, 5, 21, 'Aš nekenčiu, niekinu jūsų šventes ir neuostysiu jūsų iškilminguose susirinkimuose.'),
  (@b30, 5, 22, 'Nors jūs atnašaujate man deginamąsias atnašas ir savo maisto atnašas, aš jų nepriimsiu; ir neatsižvelgsiu į jūsų riebių gyvulių taikos atnašas.'),
  (@b30, 5, 23, 'Pašalink nuo manęs savo giesmių triukšmą; nes aš nesiklausysiu tavo violų melodijos.'),
  (@b30, 5, 24, 'Bet tegul teismas teka žemyn kaip vandenys ir teisumas – kaip galinga srovė.'),
  (@b30, 5, 25, 'Ar man atnašavote aukas ir atnašas dykumoje per keturiasdešimt metų, o Izraelio namai?'),
  (@b30, 5, 26, 'Bet jūs nešiojote savo Moloko padangtę ir Kijūną – savo atvaizdus, savo dievo žvaigždę, kuriuos sau pasidarėte.'),
  (@b30, 5, 27, 'Todėl aš išvesiu jus nelaisvėn anapus Damasko“, – sako VIEŠPATS, kurio vardas yra kariuomenių Dievas.'),
  (@b30, 6, 1, 'Vargas tiems, kurie yra be rūpesčių Sione ir pasitiki Samarijos kalnu, kurie vadinami tautų vyriausiais, pas kuriuos atėjo Izraelio namai!'),
  (@b30, 6, 2, 'Pereikite į Kalnę ir pasižiūrėkite; iš ten eikite į didįjį Hamatą; tada eikite žemyn į filistinų Gatą; ar jie geresni už šitas karalystes? Arba, ar jų ribos didesnės už jūsų ribas?'),
  (@b30, 6, 3, 'Jūs, kurie atitolinate nelaimės dieną ir priartinate smurto būstinę;'),
  (@b30, 6, 4, 'kurie gulite dramblio kaulo lovose ir išsitiesiate savo guolyje, valgote ėriukus iš kaimenės ir veršius iš gardo;'),
  (@b30, 6, 5, 'kurie dainuojate pagal violos garsą ir sau išrandate muzikos instrumentų, kaip Dovydas;'),
  (@b30, 6, 6, 'kurie geriate vyną iš taurių ir tepatės geriausiais tepalais; bet jie nesisieloja dėl Juozapo vargo.'),
  (@b30, 6, 7, 'Todėl jie dabar eis į nelaisvę su pirmaisiais, einančiais nelaisvėn, ir bus pašalintas puotavimas tų, kurie gulėjo išsitiesę.'),
  (@b30, 6, 8, '„Viešpats DIEVAS prisiekė savimi, – sako VIEŠPATS, kariuomenių Dievas, – aš bjauriuosi Jokūbo puikumu ir nekenčiu jo rūmų; todėl aš atiduosiu miestą su viskuo, kas yra jame“.'),
  (@b30, 6, 9, 'Ir įvyks, jei išliks dešimt žmonių vienuose namuose, jie mirs.'),
  (@b30, 6, 10, 'Ir žmogaus dėdė bei jį deginantis jį paims, kad išneštų iš namų kaulus, ir sakys esančiam prie namo šonų: „Ar dar yra kas su tavimi?“ O jis sakys: „Nėra“. Tada jis sakys: „Sulaikyk liežuvį; nes negalime minėti VIEŠPATIES vardo“.'),
  (@b30, 6, 11, 'Nes štai VIEŠPATS įsako, ir jis ištiks didžiuosius namus spragomis, o mažuosius namus – plyšiais.'),
  (@b30, 6, 12, 'Argi žirgai bėgs uolomis? Ar ten kas ars jaučiais? Nes jūs teismą pavertėte tulžimi ir teisumo vaisių maudos nuodais;'),
  (@b30, 6, 13, 'jūs, kurie džiaugiatės niekingais dalykais, kurie sakote: „Ar ne savo jėga pasiėmėme ragus?“'),
  (@b30, 6, 14, 'Bet štai aš sukelsiu prieš jus tautą, o Izraelio namai, – sako VIEŠPATS, kariuomenių Dievas, – ir jie prislėgs jus nuo Hamato įėjimo iki dykumos upės“.'),
  (@b30, 7, 1, 'Taip man parodė Viešpats DIEVAS: ir štai vėlyvųjų atžalų augimo pradžioje jis formavo žiogus; ir štai tai buvo vėlyvosios atžalos po karaliaus šienapjūtės.'),
  (@b30, 7, 2, 'Ir įvyko, kai jie baigė ėsti šalies žolę, aš tariau: „O Viešpatie DIEVE, atleisk, meldžiu tave; per ką Jokūbas pakils? Nes jis mažas“.'),
  (@b30, 7, 3, 'VIEŠPATS gailėjosi dėl to; „To nebus“, – sako VIEŠPATS.'),
  (@b30, 7, 4, 'Taip man parodė Viešpats DIEVAS: ir štai Viešpats DIEVAS šaukė varžytis ugnimi, ir ji surijo didžiąsias gelmes ir suėdė dalį.'),
  (@b30, 7, 5, 'Tada aš tariau: „O Viešpatie DIEVE, liaukis, meldžiu tave; per ką Jokūbas pakils? Nes jis mažas“.'),
  (@b30, 7, 6, 'VIEŠPATS gailėjosi dėl to; „To irgi nebus“, – sako Viešpats DIEVAS.'),
  (@b30, 7, 7, 'Taip jis man parodė: ir štai Viešpats su svambalu savo rankoje atsistojo ant svambalu padarytos sienos.'),
  (@b30, 7, 8, 'Ir VIEŠPATS man tarė: „Ką matai, Amosai?“ Ir aš tariau: „Svambalą“. Tada Viešpats tarė: „Štai aš padėsiu svambalą savo tautos Izraelio tarpe; aš nebepraeisiu jiems pro šalį;'),
  (@b30, 7, 9, 'Izaoko aukštumos bus nusiaubtos ir Izraelio šventovės nuniokotos; ir aš pakilsiu prieš Jeroboamo namus su kalaviju“.'),
  (@b30, 7, 10, 'Tada Bet-Elio kunigas Amacija pasiuntė Izraelio karaliui Jeroboamui, sakydamas: „Amosas suruošė prieš tave sąmokslą Izraelio namų tarpe; šalis negali pakelti visų jo žodžių.'),
  (@b30, 7, 11, 'Nes taip sako Amosas: ‘Jeroboamas mirs nuo kalavijo, o Izraelis tikrai bus išvestas nelaisvėn iš savo šalies’“.'),
  (@b30, 7, 12, 'Taip pat Amacija tarė Amosui: „O regėtojau, eik, bėk sau į Judos šalį ir ten valgyk duoną, ir ten pranašauk;'),
  (@b30, 7, 13, 'bet Bet-Elyje daugiau nebepranašauk; nes tai karaliaus koplyčia ir tai karaliaus kiemas“.'),
  (@b30, 7, 14, 'Tada Amosas atsakė ir tarė Amacijai: „Aš nebuvau pranašas nei aš buvau pranašo sūnus; bet aš buvau kerdžius ir sikamoro vaisių rinkėjas;'),
  (@b30, 7, 15, 'ir VIEŠPATS mane paėmė, kai aš ėjau paskui kaimenę, ir VIEŠPATS man tarė: ‘Eik, pranašauk mano tautai Izraeliui’.'),
  (@b30, 7, 16, 'Todėl dabar klausykis VIEŠPATIES žodžio: ‘Tu sakai: Nepranašauk prieš Izraelį, nevarvink savo žodžio prieš Izaoko namus’.'),
  (@b30, 7, 17, 'Todėl taip sako VIEŠPATS: ‘Tavo žmona bus paleistuvė mieste, o tavo sūnūs ir tavo dukterys kris nuo kalavijo, ir tavo žemė bus padalyta virve; o tu mirsi suterštoje šalyje; ir Izraelis tikrai eis į nelaisvę iš savo šalies’“.'),
  (@b30, 8, 1, 'Taip man parodė Viešpats DIEVAS: ir štai vasarinių vaisių pintinė.'),
  (@b30, 8, 2, 'Ir jis tarė: „Ką matai, Amosai?“ Aš tariau: „Vasaros vaisių pintinę“. Tada VIEŠPATS man tarė: „Atėjo galas mano tautai Izraeliui; aš nebepraeisiu jiems pro šalį.'),
  (@b30, 8, 3, 'Ir šventyklos giesmės tą dieną bus aimanomis, – sako Viešpats DIEVAS; – visur bus daug lavonų; juos išmes tylėdami“.'),
  (@b30, 8, 4, 'Klausykite tai jūs, kurie praryjate nepasiturintįjį, kad padarytumėte galą šalies vargšams,'),
  (@b30, 8, 5, 'sakydami: „Kada baigsis jaunas mėnulis, kad galėtume parduoti javus? Kada baigsis sabatas, kad galėtume pateikti kviečius, sumažindami efą, padidindami šekelį ir apgaule suklastodami svarstykles;'),
  (@b30, 8, 6, 'kad pirktume vargšą už sidabrą ir nepasiturintįjį už avalynės porą; taip, ir parduotume kviečių atliekas?“'),
  (@b30, 8, 7, 'VIEŠPATS prisiekė Jokūbo puikybe: „Tikrai niekada nepamiršiu nei vieno jų darbų.'),
  (@b30, 8, 8, 'Argi dėl to nedrebės šalis ir negedės visi joje gyvenantys? Ir ji visa pakils kaip upė; ji bus išmesta ir paskandinta lyg Egipto upe“.'),
  (@b30, 8, 9, '„Ir įvyks tą dieną, – sako Viešpats DIEVAS, – kad aš padarysiu, jog saulė nusileis vidudienį ir aptemdys žemę šviesią dieną;'),
  (@b30, 8, 10, 'ir aš paversiu jūsų šventes gedulu ir visas jūsų giesmes raudomis; ir uždėsiu ant visų strėnų ašutinę ir ant kiekvienos galvos plikę; padarysiu tai kaip gedėjimą dėl vienintelio sūnaus, ir to pabaigą – kaip karčią dieną.'),
  (@b30, 8, 11, 'Štai ateina dienos, – sako Viešpats DIEVAS, – kai aš siųsiu badą į šalį, ne duonos badą ir ne vandens troškulį, bet VIEŠPATIES žodžių girdėjimo badą;'),
  (@b30, 8, 12, 'jie klajos nuo jūros iki jūros ir nuo šiaurės iki rytų, jie lakstys ten ir atgal, ieškodami VIEŠPATIES žodžio, bet jo neras.'),
  (@b30, 8, 13, 'Tą dieną alps iš troškulio gražios mergelės ir jaunuoliai.'),
  (@b30, 8, 14, 'Kurie prisiekia Samarijos nuodėme ir sako: ‘Tavo dievas gyvas, o Danai’; ir: ‘Beer-Šebos būdas gyvas’, tie kris ir niekada nebeatsikels“.'),
  (@b30, 9, 1, 'Mačiau Viešpatį, stovintį ant aukuro; ir jis tarė: „Trenk į durų sąramą, kad sudrebėtų staktos; ir kirsk jiems į galvą, jiems visiems; o jų likusiuosius nužudysiu kalaviju; nei vienas jų bėgantis nepabėgs ir nei vienas jų besigelbėjantis neišsigelbės.'),
  (@b30, 9, 2, 'Nors jie ir prasikastų į pragarą, iš ten mano ranka juos paims; nors jie ir užliptų į dangų, iš ten juos numesiu;'),
  (@b30, 9, 3, 'ir nors jie pasislėptų Karmelio viršūnėje, aš suieškosiu juos ir iš ten paimsiu; nors jie pasislėptų nuo mano akių jūros dugne, ten įsakysiu gyvatei, ir ji jiems įgels;'),
  (@b30, 9, 4, 'ir nors jie eitų nelaisvėn savo priešų priešakyje, ten įsakysiu kalavijui, ir jis juos išžudys; aš nukreipsiu į juos savo akis blogiui, o ne gėriui“.'),
  (@b30, 9, 5, 'Viešpats, kariuomenių DIEVAS, yra tas, kuris paliečia šalį, ir ji tirpsta, ir visi joje gyvenantys gedės; ir ji visa pakils kaip upė; ji bus paskandinta lyg Egipto upe.'),
  (@b30, 9, 6, 'Tai tas, kuris stato savo aukštus danguje ir padėjo pamatą savo pulkui ant žemės; tas, kuris pašaukia jūros vandenis ir išlieja juos ant žemės paviršiaus; VIEŠPATS yra jo vardas.'),
  (@b30, 9, 7, '„O Izraelio vaikai, argi jūs nesate man kaip etiopų vaikai? – sako VIEŠPATS. – Argi aš nevedžiau aukštyn Izraelio iš Egipto šalies, filistinų iš Kaftoro ir sirų iš Kiro?'),
  (@b30, 9, 8, 'Štai Viešpaties DIEVO akys nukreiptos į nuodėmingą karalystę, ir aš ją išnaikinsiu nuo žemės paviršiaus; tik Jokūbo namų visiškai nesunaikinsiu, – sako VIEŠPATS.'),
  (@b30, 9, 9, '– Nes štai aš įsakysiu ir sijosiu Izraelio namus tarp visų tautų, kaip grūdai sijojami rėčiu, ir nei mažiausias grūdas nenukris žemėn.'),
  (@b30, 9, 10, 'Nuo kalavijo žus visi mano tautos nusidėjėliai, sakantys: ‘Nelaimė nepasivys ir aplenkusi mūsų nepasitiks’.'),
  (@b30, 9, 11, 'Tą dieną pakelsiu griuvusią Dovydo padangtę ir užtaisysiu jos spragas; ir pakelsiu jos griuvėsius, ir ją pastatysiu kaip senovės dienomis;'),
  (@b30, 9, 12, 'kad jie paveldėtų likutį Edomo ir visų pagonių, vadinamų mano vardu“, – sako VIEŠPATS, kuris tai daro.'),
  (@b30, 9, 13, '„Štai ateina dienos, – sako VIEŠPATS, – kai artojas pasivys pjovėją ir vynuogių mindytojas – sėjantįjį sėklą; ir kalnai lašės saldžiu vynu, ir visos kalvos tirps.'),
  (@b30, 9, 14, 'Ir aš sugrąžinsiu savo tautos Izraelio nelaisvę, ir jie statys apleistus miestus ir juos apgyvendins; jie sodins vynuogynus ir gers jų vyną; taipogi jie pasidarys sodų ir valgys jų vaisius.'),
  (@b30, 9, 15, 'Aš juos pasodinsiu jų šalyje, ir jie nebebus išrauti iš savo šalies, kurią jiems daviau“, – sako VIEŠPATS, tavo Dievas.'),
  (@b31, 1, 1, 'Abdijo regėjimas. Taip sako Viešpats DIEVAS apie Edomą: Girdėjome žinią iš VIEŠPATIES, ir pasiuntinys yra pasiųstas tarp pagonių: „Kelkitės, ir pakilkime prieš jį į mūšį“.'),
  (@b31, 1, 2, '„Štai aš padariau tave mažą tarp pagonių; tu labai niekinamas.'),
  (@b31, 1, 3, 'Tavo širdies išdidumas apgavo tave, kuris gyveni uolų plyšiuose, kurio buveinė aukštai, kuris sakai savo širdyje: ‘Kas nustums mane žemėn?’'),
  (@b31, 1, 4, 'Nors tu išsikeltum kaip erelis ir nors susisuktum savo lizdą tarp žvaigždžių, iš ten nustumsiu tave, – sako VIEŠPATS.'),
  (@b31, 1, 5, '– Jei vagys ateitų pas tave, jei plėšikai nakčia (kaip tu esi iškirstas!), argi jie nevogtų, kol jiems būtų gana? Jei vynuogių rinkėjai ateitų pas tave, argi jie nepaliktų keleto vynuogių?'),
  (@b31, 1, 6, 'Kaip surasti Ezavo dalykai, kaip suieškoti jo paslėpti dalykai!'),
  (@b31, 1, 7, 'Visi tavo sąjungininkai atvedė tave prie ribos; tie, kurie buvo taikoje su tavimi, apgavo tave ir nugalėjo; kurie valgė tavo duoną, sukėlė po tavimi žaizdą; nėra jame supratimo.'),
  (@b31, 1, 8, 'Argi tą dieną, – sako VIEŠPATS, – aš neišnaikinsiu išmintingųjų iš Edomo ir supratimo iš Ezavo kalno?'),
  (@b31, 1, 9, 'Ir tavo galiūnai, o Temane, bus sunerimę, kad kiekvienas iš Ezavo kalno būtų iškirstas žudynėmis.'),
  (@b31, 1, 10, 'Dėl tavo smurto prieš savo brolį Jokūbą tave apdengs gėda, ir tu būsi amžinai iškirstas.'),
  (@b31, 1, 11, 'Tą dieną, kai tu stovėjai kitoje pusėje, tą dieną, kai svetimieji išvedė nelaisvėn jo kariuomenes ir svetimšaliai įžengė į jo vartus bei dėl Jeruzalės metė burtą, tu buvai kaip vienas iš jų.'),
  (@b31, 1, 12, 'Bet tu neturėjai žiūrėti į savo brolio dieną, tą dieną, kai jis tapo svetimu; ir neturėjai džiaugtis dėl Judos vaikų jų sunaikinimo dieną; ir neturėjai išdidžiai kalbėti sielvarto dieną.'),
  (@b31, 1, 13, 'Tu neturėjai įžengti į mano tautos vartus jų nelaimės dieną; taip, tu neturėjai žiūrėti į jų sielvartą jų nelaimės dieną nei pridėti rankų prie jų turto jų nelaimės dieną;'),
  (@b31, 1, 14, 'ir neturėjai stovėti kryžkelėje, kad iškirstum jo pabėgusiuosius; ir neturėjai atiduoti tų, kurie iš jo išliko sielvarto dieną.'),
  (@b31, 1, 15, 'Nes VIEŠPATIES diena arti visiems pagonims; kaip tu darei, taip ir tau bus padaryta; tavo atlygis sugrįš ant tavo paties galvos.'),
  (@b31, 1, 16, 'Nes kaip jūs gėrėte mano šventajame kalne, taip visi pagonys nuolat gers, taip, jie gers ir nurys, ir jie bus tarsi jų nėra buvę.'),
  (@b31, 1, 17, 'Bet Siono kalne bus išgelbėjimas, ir ten bus šventumas; ir Jokūbo namai pasisavins jų nuosavybes.'),
  (@b31, 1, 18, 'Ir Jokūbo namai bus ugnimi, Juozapo namai – liepsna, o Ezavo namai – ražienomis, ir jie padegs jas ir jas prarys; ir nei vieno neišliks iš Ezavo namų; nes VIEŠPATS tai kalbėjo.'),
  (@b31, 1, 19, 'Ir tie iš pietų pasisavins Ezavo kalną; o tie iš lygumos – filistinus; ir jie pasisavins Efraimo laukus ir Samarijos laukus; o Benjaminas pasisavins Gileadą.'),
  (@b31, 1, 20, 'Ir šios Izraelio vaikų kariuomenės belaisviai pasisavins tai, kas kanaaniečių iki Carefato; o Jeruzalės belaisviai, esantys Sefarade, pasisavins pietų miestus.'),
  (@b31, 1, 21, 'Ir gelbėtojai ateis aukštyn į Siono kalną teisti Ezavo kalno; ir karalystė bus VIEŠPATIES“.'),
  (@b32, 1, 1, 'Na, o VIEŠPATIES žodis atėjo Amitajo sūnui Jonai, sakydamas:'),
  (@b32, 1, 2, '„Kelkis, eik į Ninevę, į tą didį miestą, ir šauk prieš jį; nes jų nedorybės pakilo mano akivaizdon“.'),
  (@b32, 1, 3, 'Bet Jona pakilo, kad bėgtų į Taršišą nuo VIEŠPATIES akivaizdos, ir nuėjo žemyn į Jopę; jis užtiko laivą, plaukiantį į Taršišą; taigi sumokėjo mokestį už pervežimą ir įlipo į jį, kad vyktų su jais į Taršišą nuo VIEŠPATIES akivaizdos.'),
  (@b32, 1, 4, 'Bet VIEŠPATS išsiuntė didelį vėją į jūrą, ir buvo galinga audra jūroje, kad laivas buvo besudužtąs.'),
  (@b32, 1, 5, 'Tada jūrininkai išsigando, ir kiekvienas šaukėsi savo dievo, ir išmetė laive esančius rykus į jūrą, kad jį nuo jų palengvintų. Bet Jona buvo nusileidęs prie laivo šonų; jis atsigulęs kietai miegojo.'),
  (@b32, 1, 6, 'Taigi kapitonas atėjo pas jį ir jam tarė: „Ką tai reiškia, miegaliau? Kelkis, šaukis savo Dievo, galbūt Dievas prisimins mus, kad mes nežūtume“.'),
  (@b32, 1, 7, 'Ir jie sakė vienas kitam: „Ateikite ir meskime burtus, kad sužinotume, dėl kurio šita nelaimė mus ištiko“. Taigi jie metė burtus, ir burtas krito Jonai.'),
  (@b32, 1, 8, 'Tada jie tarė jam: „Pasakyk mums, meldžiame tave, dėl kurio šita nelaimė mus ištiko; koks tavo užsiėmimas? Iš kur tu atėjęs? Kas yra tavo kraštas? Iš kurios tu tautos?“'),
  (@b32, 1, 9, 'Ir jis jiems tarė: „Aš hebrajas; ir aš bijau VIEŠPATIES, dangaus Dievo, kuris padarė jūrą ir sausumą“.'),
  (@b32, 1, 10, 'Tada tie vyrai nepaprastai išsigando ir jam tarė: „Kodėl tai padarei?“ Nes tie vyrai žinojo, kad jis bėgo nuo VIEŠPATIES akivaizdos, nes jis buvo jiems pasakęs.'),
  (@b32, 1, 11, 'Tada jie tarė jam: „Ką turime daryti su tavimi, kad jūra mums nurimtų?“, nes jūra darėsi vis audringesnė.'),
  (@b32, 1, 12, 'Ir jis jiems tarė: „Pakelkite mane ir išmeskite į jūrą; taip jūra jums nurims; nes žinau, kad dėl manęs šita didelė audra yra ant jūsų“.'),
  (@b32, 1, 13, 'Tačiau tie vyrai sunkiai yrėsi, kad priplukdytų jį prie sausumos; bet jie negalėjo; nes jūra vis labiau šėlo prieš juos.'),
  (@b32, 1, 14, 'Todėl jie šaukėsi VIEŠPATIES ir tarė: „Meldžiame tave, o VIEŠPATIE, meldžiame tave, neleisk mums žūti dėl šito žmogaus gyvybės ir nepriskirk mums nekalto kraujo; nes tu, o VIEŠPATIE, padarei, kaip tu nori“.'),
  (@b32, 1, 15, 'Taigi jie pakėlė Joną ir išmetė į jūrą; ir jūra liovėsi siautusi.'),
  (@b32, 1, 16, 'Tada tie vyrai be galo bijojo VIEŠPATIES ir atnašavo VIEŠPAČIUI auką ir davė įžadus.'),
  (@b32, 1, 17, 'Na, o VIEŠPATS paruošė didelę žuvį, kad prarytų Joną. Ir Jona buvo žuvies pilve tris dienas ir tris naktis.'),
  (@b32, 2, 1, 'Tada Jona meldėsi VIEŠPAČIUI, savo Dievui, iš žuvies pilvo,'),
  (@b32, 2, 2, 'ir sakė: „Dėl savo sielvarto šaukiausi VIEŠPATIES, ir jis išklausė mane; iš pragaro pilvo šaukiau, ir tu išgirdai mano balsą.'),
  (@b32, 2, 3, 'Nes tu įmetei mane į gelmes, į jūrų vidurį; ir srovės apsupo mane; visos tavo bangos ir tavo vilnys ėjo virš manęs.'),
  (@b32, 2, 4, 'Tada tariau: ‘Esu atmestas nuo tavo akių; tačiau vėl žiūrėsiu į tavo šventąją šventyklą.'),
  (@b32, 2, 5, 'Vandenys apsupo mane iki sielos; gelmės apdengė mane aplinkui, dumbliai apsivyniojo aplink mano galvą.'),
  (@b32, 2, 6, 'Aš nusileidau iki kalnų apačios; žemė savo skląsčiais buvo aplink mane amžiams; tačiau tu iškėlei mano gyvybę iš sugedimo, o VIEŠPATIE, mano Dieve.'),
  (@b32, 2, 7, 'Kai mano siela alpo mano viduje, aš atsiminiau VIEŠPATĮ; ir mano malda atėjo pas tave, į tavo šventąją šventyklą.'),
  (@b32, 2, 8, 'Tie, kurie laikosi melagingų tuštybių, apleidžia savo pačių gailestingumą.'),
  (@b32, 2, 9, 'Bet aš aukosiu tau padėkos balsu; tai, ką pažadėjau, ištesėsiu. Išgelbėjimas yra iš VIEŠPATIES“.'),
  (@b32, 2, 10, 'Ir VIEŠPATS kalbėjo žuviai, ir ji išvėmė Joną į sausumą.'),
  (@b32, 3, 1, 'Ir antrą kartą VIEŠPATIES žodis atėjo Jonai, sakydamas:'),
  (@b32, 3, 2, '„Kelkis, eik į Ninevę, į tą didelį miestą, ir skelbk jai tą skelbimą, kurį tau įsakiau“.'),
  (@b32, 3, 3, 'Taigi Jona pagal VIEŠPATIES žodį pakilo ir nuėjo į Ninevę. Na, o Ninevė buvo nepaprastai didelis miestas, trijų dienų kelionės.'),
  (@b32, 3, 4, 'Ir Jona pradėjo įeiti į miestą, vienos dienos kelionę, ir šaukė, sakydamas: „Dar keturiasdešimt dienų, ir Ninevė bus sunaikinta“.'),
  (@b32, 3, 5, 'Taigi Ninevės tauta patikėjo Dievu, paskelbė pasninką ir nuo jų didžiausio iki jų mažiausio apsivilko ašutinėmis.'),
  (@b32, 3, 6, 'Nes žodis atėjo iki Ninevės karaliaus, ir jis pakilo iš savo sosto, nusivilko savo rūbą, apsidengė ašutine ir atsisėdo pelenuose.'),
  (@b32, 3, 7, 'Ir jis liepė pagarsinti ir paskelbti Ninevėje karaliaus ir jo kilmingųjų įsaku, sakant: „Nei žmonės, nei gyvuliai, nei bandos, nei kaimenės nieko teneragauja; jie tenesigano ir tenegeria vandens;'),
  (@b32, 3, 8, 'bet žmonės ir gyvuliai teapsidengia ašutinėmis ir stipriai tesišaukia Dievo; taip, kiekvienas tenusigręžia nuo savo pikto kelio ir nuo savo rankų smurto.'),
  (@b32, 3, 9, 'Kas žino, gal Dievas apsigręš ir gailėsis, ir nusigręš nuo savo smarkaus pykčio, kad mes nepražūtume?“'),
  (@b32, 3, 10, 'Ir Dievas pamatė jų darbus, kad jie nusigręžė nuo savo pikto kelio; ir Dievas gailėjosi dėl pikto, kurį sakė jiems padarysiąs; ir jis to nepadarė.'),
  (@b32, 4, 1, 'Bet Jonai tai be galo nepatiko, ir jis buvo labai supykęs.'),
  (@b32, 4, 2, 'Jis meldėsi VIEŠPAČIUI ir sakė: „Meldžiu, o VIEŠPATIE, argi aš tai nesakiau, kai dar buvau savo krašte? Todėl pirma ir bėgau į Taršišą; nes žinojau, kad tu maloningas Dievas ir gailestingas, lėtas pykti, didžiai geras ir apsigalvoji dėl pikto.'),
  (@b32, 4, 3, 'Todėl dabar, o VIEŠPATIE, meldžiu tave, atimk iš manęs mano gyvybę; nes man geriau mirti negu gyventi“.'),
  (@b32, 4, 4, 'Tada VIEŠPATS tarė: „Ar gerai darai pykdamas?“'),
  (@b32, 4, 5, 'Taigi Jona išėjo iš miesto, atsisėdo rytinėje miesto pusėje, ten pasidarė pastogę ir sėdėjo po ja šešėlyje, kol pamatysiąs, kas atsitiks miestui.'),
  (@b32, 4, 6, 'Ir VIEŠPATS Dievas paruošė moliūgą ir jį išaugino viršum Jonos, kad jis būtų šešėlis virš jo galvos, kad jį išvaduotų iš sielvarto. Taigi Jona nepaprastai džiaugėsi moliūgu.'),
  (@b32, 4, 7, 'Bet kitą dieną, aušrai brėkštant, Dievas paruošė kirmėlę, ir ji pakando moliūgą, kad tas nudžiūvo.'),
  (@b32, 4, 8, 'Ir saulei patekėjus įvyko, kad Dievas paruošė smarkų rytų vėją; ir saulė spigino Jonos galvą, kad jis alpo ir geidė savyje mirties, ir sakė: „Geriau man mirti negu gyventi“.'),
  (@b32, 4, 9, 'Ir Dievas tarė Jonai: „Ar gerai darai pykdamas dėl moliūgo?“ O jis tarė: „Gerai darau pykdamas, net iki mirties“.'),
  (@b32, 4, 10, 'Tada VIEŠPATS tarė: „Tau gaila moliūgo, dėl kurio netriūsei ir kurio neauginai, kuris per vieną naktį išaugo ir per vieną naktį pražuvo;'),
  (@b32, 4, 11, 'o argi neturėčiau gailėtis Ninevės, to didelio miesto, kuriame yra daugiau negu šimtas dvidešimt tūkstančių žmonių, nemokančių atskirti savo dešinės nuo savo kairės, ir taip pat daugybė galvijų?“'),
  (@b33, 1, 1, 'VIEŠPATIES žodis, kuris atėjo morešetui Michėjui – kurį jis matė apie Samariją ir Jeruzalę – Judos karalių Jotamo, Ahazo ir Chezekijo dienomis.'),
  (@b33, 1, 2, 'Klausykitės, visos tautos; klausykis, o žeme ir visa, kas joje; ir Viešpats DIEVAS tebūna liudytojas prieš jus, Viešpats iš savo šventosios šventyklos.'),
  (@b33, 1, 3, 'Nes štai VIEŠPATS išeina iš savo vietos, nusileis ir žengs žemės aukštumomis.'),
  (@b33, 1, 4, 'Kalnai sutirps po juo ir slėniai skilinės kaip vaškas nuo ugnies, kaip vandenys, besiliejantys žemyn nuo skardžio.'),
  (@b33, 1, 5, 'Visa tai dėl Jokūbo nusižengimo ir dėl Izraelio namų nuodėmių. Kas yra Jokūbo nusižengimas? Ar ne Samarija? Ir kas yra Judos aukštumos? Ar ne Jeruzalė?'),
  (@b33, 1, 6, '„Todėl aš paversiu Samariją lauko krūva, vynuogyno sodinimu; ir išpilsiu jos akmenis į slėnį ir atidengsiu jos pamatus.'),
  (@b33, 1, 7, 'Visi raižyti jos atvaizdai bus sutrupinti, visi jos užmokesčiai bus sudeginti ugnimi, ir visus jos stabus suniokosiu; nes ji juos surinko iš paleistuvės užmokesčio, ir jie sugrįš į paleistuvės užmokestį“.'),
  (@b33, 1, 8, 'Todėl aš verksiu ir kauksiu, vaikščiosiu apiplėštas ir nuogas; verksiu kaip slibinai ir raudosiu kaip pelėdos.'),
  (@b33, 1, 9, 'Nes jos žaizda neišgydoma; nes ji pasiekė Judą, pasiekė mano tautos vartus – Jeruzalę.'),
  (@b33, 1, 10, 'Neskelbkite to Gate, visai neverkite; Afros namuose voliokitės dulkėse.'),
  (@b33, 1, 11, 'Praeik, Šafyro gyventojau, savo apnuoginta gėda; Canano gyventojas neišėjo į Bet-Ecelio gedulą; jis gaus iš jūsų savo paramą;'),
  (@b33, 1, 12, 'nes Maroto gyventojas atidžiai laukė gero; tačiau pikta nusileido nuo VIEŠPATIES į Jeruzalės vartus.'),
  (@b33, 1, 13, 'O Lachišo gyventojau, pririšk vežimą prie greito gyvulio; jis yra nuodėmės pradžia Siono dukrai; nes tavyje atrasti Izraelio nusižengimai.'),
  (@b33, 1, 14, 'Todėl tu duosi dovanas Morešet-Gatui; Achzibo namai bus apgaulė Izraelio karaliams.'),
  (@b33, 1, 15, 'Dar atvesiu pas tave paveldėtoją, o Marešos gyventojau; jis ateis į Adulamą, Izraelio šlovę.'),
  (@b33, 1, 16, 'Pasidaryk plikę, nusikirpk dėl savo mielų vaikų; praplatink savo plikę kaip erelis; nes jie nuėjo iš tavęs nelaisvėn.'),
  (@b33, 2, 1, 'Vargas tiems, kurie sumano neteisybę ir daro pikta savo lovose! Rytui išaušus jie tai įvykdo, nes tai yra jų rankos galioje.'),
  (@b33, 2, 2, 'Jie geidžia laukų ir paima juos smurtu, geidžia namų ir atima juos; taip jie engia žmogų ir jo namus, tai yra, žmogų ir jo paveldą.'),
  (@b33, 2, 3, 'Todėl taip sako VIEŠPATS: „Štai prieš šitą šeimą aš sumanau nelaimę, iš kurios neištrauksite savo sprandų; ir nevaikščiosite išdidžiai; nes šis laikas yra piktas“.'),
  (@b33, 2, 4, 'Tą dieną imsis prieš jus palyginimo ir raudos graudulingą raudą, ir sakys: „Mes visiškai apiplėšti; jis pakeitė mano tautos dalį; kaip jis atėmė ją iš manęs! Nusigręždamas jis padalijo mūsų laukus“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b33, 2, 5, 'Todėl tu neturėsi nei vieno, burtu metančio virvę VIEŠPATIES susirinkime.'),
  (@b33, 2, 6, '„Nepranašaukite“, – sako jie pranašaujantiems; jie nepranašaus jiems, kad jie neprisiimtų gėdos.'),
  (@b33, 2, 7, 'O jūs, vadinami Jokūbo namais! Ar VIEŠPATIES Dvasia apribota? Ar tai jo darbai? Argi mano žodžiai nedaro gera tam, kuris vaikšto tiesiai?'),
  (@b33, 2, 8, 'Neseniai mano tauta pakilo kaip priešas; jūs nutraukiate apsiaustą su drabužiu nuo saugiai praeinančių, nenusiteikusių kariauti.'),
  (@b33, 2, 9, 'Mano tautos moteris išvarėte iš geistinų jų namų; iš jų vaikų amžiams atėmėte mano šlovę.'),
  (@b33, 2, 10, 'Kelkitės ir išeikite; nes tai ne jūsų poilsio vieta; nes ji suteršta, ji jus sunaikins skaudžiu naikinimu.'),
  (@b33, 2, 11, 'Jei kas vaikščiodamas melo dvasioje meluotų, sakydamas: „Aš tau pranašausiu apie vyną ir apie stiprų gėrimą“, tas bus šitos tautos pranašas.'),
  (@b33, 2, 12, 'Aš tikrai surinksiu tave visą, o Jokūbai; tikrai surinksiu Izraelio likutį; surinksiu juos kaip Bocros avis, kaip kaimenę jų aptvaro viduryje; jie sukels didelį triukšmą dėl žmonių daugybės.'),
  (@b33, 2, 13, 'Pralaužėjas atėjo aukštyn priekyje jų; jie prasilaužė, praėjo pro vartus ir išėjo pro juos; jų karalius eis pirma jų, o VIEŠPATS jų priekyje.'),
  (@b33, 3, 1, 'Ir aš tariau: „Klausykite, meldžiu jus, o Jokūbo galvos, jūs, Izraelio namų kunigaikščiai: argi ne jums žinoti teismą?'),
  (@b33, 3, 2, 'Jums, kurie nekenčiate gero ir mylite pikta; kurie lupate jų odą nuo jų ir jų mėsą nuo jų kaulų;'),
  (@b33, 3, 3, 'kurie ėdate mano tautos kūną ir lupate jų odą nuo jų“; ir jie sulaužo jų kaulus, sukapoja juos į gabalus tarsi puodui, kaip mėsą katile.'),
  (@b33, 3, 4, 'Tada jie šauksis VIEŠPATIES, bet jis neišklausys jų; tuo metu jis paslėps savo veidą nuo jų, kaip jie blogai elgėsi savo darbais.'),
  (@b33, 3, 5, 'Taip sako VIEŠPATS apie pranašus, kurie klaidina mano tautą, kurie kramto savo dantimis ir šaukia: „Taika“; o prieš tą, kuris jiems nieko neįdeda į burną, jie ruošia karą.'),
  (@b33, 3, 6, 'Todėl jums bus naktis, kad neturėtumėte regėjimo; ir jums bus tamsu, kad neburtumėte; saulė nusileis virš pranašų, ir virš jų bus tamsi diena.'),
  (@b33, 3, 7, 'Tada gėdysis regėtojai, ir ateities būrėjai bus sugluminti; taip, jie visi užsidengs lūpas, nes nėra atsakymo iš Dievo.'),
  (@b33, 3, 8, 'Bet tikrai aš pilnas jėgos per VIEŠPATIES Dvasią, teismo ir galios, kad paskelbčiau Jokūbui jo nusižengimą ir Izraeliui jo nuodėmę.'),
  (@b33, 3, 9, 'Klausykite tai, meldžiu jus, jūs Jokūbo namų galvos ir Izraelio namų kunigaikščiai, kurie bjauritės teismu ir iškreipiate visa, kas teisinga.'),
  (@b33, 3, 10, 'Jie stato Sioną krauju ir Jeruzalę neteisybe.'),
  (@b33, 3, 11, 'Jos galvos teisia už apdovanojimą, jos kunigai moko už atlyginimą ir jos pranašai buria už pinigus; tačiau jie pasiremia VIEŠPAČIU ir sako: „Argi VIEŠPATS nėra tarp mūsų? Nelaimė neužeis ant mūsų“.'),
  (@b33, 3, 12, 'Todėl dėl jūsų Sionas bus ariamas kaip laukas, Jeruzalė taps krūvomis, o namų kalnas – miško aukštuma.'),
  (@b33, 4, 1, 'Bet paskutinėmis dienomis įvyks, kad VIEŠPATIES namų kalnas bus įtvirtintas kalnų viršūnėse ir bus išaukštintas viršum kalvų; ir tautos plauks į jį.'),
  (@b33, 4, 2, 'Ir daug tautų ateis ir sakys: „Ateikite, eikime aukštyn į VIEŠPATIES kalną, į Jokūbo Dievo namus; ir jis mus mokys savo kelių, ir mes vaikščiosime jo takais“; nes iš Siono išeis įstatymas, VIEŠPATIES žodis iš Jeruzalės.'),
  (@b33, 4, 3, 'Jis teis tarp daugelio tautų ir bars stiprias tolimas tautybes; jos perkals savo kalavijus į noragus ir savo ietis į genėjimo peilius; tauta nebekels kalavijo prieš tautą, ir jos nebesimokys kariauti.'),
  (@b33, 4, 4, 'Bet jie kiekvienas sėdės po savo vynmedžiu ir po savo figmedžiu, ir niekas jų negąsdins; nes kariuomenių VIEŠPATIES burna tai kalbėjo.'),
  (@b33, 4, 5, 'Nes visos tautos vaikščios kiekviena savo dievo vardu, o mes vaikščiosime VIEŠPATIES, savo Dievo, vardu per amžių amžius.'),
  (@b33, 4, 6, '„Tą dieną, – sako VIEŠPATS, – aš surinksiu šlubuojančius, surinksiu išvarytuosius ir tuos, kuriuos varginau;'),
  (@b33, 4, 7, 'ir padarysiu šlubuosius likučiu, ir toli atmestuosius – stipria tauta; ir VIEŠPATS jiems karaliaus Siono kalne nuo tada ir per amžius.'),
  (@b33, 4, 8, 'Ir tu, kaimenės bokšte, Siono dukters tvirtove, pas tave ji ateis, būtent pirmoji valdžia; karalystė ateis pas Jeruzalės dukrą.'),
  (@b33, 4, 9, 'Kodėl dabar taip garsiai šauki? Ar nėra tavyje karaliaus? Argi tavo patarėjas pražuvo? Nes tave suėmė skausmai kaip gimdančiąją.'),
  (@b33, 4, 10, 'Būk skausmuose ir triūsk, kad pagimdytum kaip gimdyvė, o Siono dukra; nes dabar tu išeisi iš miesto ir gyvensi ant lauko, ir eisi į Babiloną; ten būsi išvaduota; ten VIEŠPATS tave atpirks iš tavo priešų rankos.'),
  (@b33, 4, 11, 'Dabar susirinko prieš tave daug tautų, sakančių: „Ji tebūna išniekinta, ir težiūri į Sioną mūsų akys“.'),
  (@b33, 4, 12, 'Bet jos nežino VIEŠPATIES minčių ir nesupranta jo sumanymo; nes jis jas surinks kaip pėdus į klojimą.'),
  (@b33, 4, 13, '„Kelkis ir kulk, o Siono dukra; nes aš padarysiu tavo ragą geležinį ir tavo kanopas žalvarines; ir tu sutrupinsi daug tautų“; aš pašvęsiu jų grobį VIEŠPAČIUI ir jų turtus visos žemės Viešpačiui.'),
  (@b33, 5, 1, 'Susiburk dabar į pulkus, o pulkų dukra; jis apgulė mus; lazda jie trenks į skruostą Izraelio teisėjui.'),
  (@b33, 5, 2, 'Bet tu, Efratos Betliejau, nors esi mažas tarp Judos tūkstančių, tačiau iš tavęs pas mane išeis tas, kuris bus valdovas Izraelyje, kurio išėjimai buvo nuo seno, nuo amžinybės.'),
  (@b33, 5, 3, 'Todėl jis paliks juos iki to laiko, kol gimdančioji bus pagimdžiusi; tada jo brolių likutis sugrįš pas Izraelio vaikus.'),
  (@b33, 5, 4, 'Ir jis stovės ir ganys VIEŠPATIES galia, VIEŠPATIES, savo Dievo, vardo didybe; ir jie gyvens; nes tada jis bus didis iki žemės pakraščių.'),
  (@b33, 5, 5, 'Ir šis žmogus bus taika, kai asiras ateis į mūsų šalį; ir kai jis žengs mūsų rūmuose, tada mes pakelsime prieš jį septynis ganytojus ir aštuonis viršiausius žmones.'),
  (@b33, 5, 6, 'Ir jie nuniokos Asirijos šalį kalaviju ir Nimrodo šalį jos įėjimuose; taip jis išvaduos mus nuo asiro, kai jis įeis į mūsų šalį, kai jis žengs mūsų ribose.'),
  (@b33, 5, 7, 'Ir Jokūbo likutis bus daugelio tautų tarpe kaip rasa nuo VIEŠPATIES, kaip liūtis ant žolės, kuri nelūkuriuoja žmogaus ir nelaukia žmonių sūnų.'),
  (@b33, 5, 8, 'Ir Jokūbo likutis bus tarp pagonių, daugelio tautų tarpe, kaip liūtas tarp miško žvėrių, kaip jaunas liūtas tarp avių kaimenių; kuris, kai pereina, sumindo ir sudrasko, ir niekas negali išgelbėti.'),
  (@b33, 5, 9, 'Tavo ranka bus pakelta prieš tavo priešininkus, ir visi tavo priešai bus iškirsti.'),
  (@b33, 5, 10, '„Ir tą dieną įvyks, – sako VIEŠPATS, – kad aš iškirsiu iš tavo tarpo tavo žirgus ir sunaikinsiu tavo vežimus;'),
  (@b33, 5, 11, 'ir iškirsiu tavo šalies miestus, ir sugriausiu visas tavo tvirtoves;'),
  (@b33, 5, 12, 'ir iškirsiu raganavimus iš tavo rankos, ir tu nebeturėsi pranašautojų;'),
  (@b33, 5, 13, 'iškirsiu ir tavo raižytus atvaizdus, ir tavo stovinčius atvaizdus iš tavo tarpo; ir tu nebegarbinsi savo rankų darbo.'),
  (@b33, 5, 14, 'Ir išrausiu iš tavo tarpo tavo giraites; taip sunaikinsiu tavo miestus.'),
  (@b33, 5, 15, 'Supykęs ir įtūžęs įvykdysiu pagonims kerštą, kokio jie nėra girdėję“.'),
  (@b33, 6, 1, 'Na, klausykite, ką sako VIEŠPATS: „Kelkis, ginčykis kalnų akivaizdoje, ir tegul kalvos išgirsta tavo balsą“.'),
  (@b33, 6, 2, 'Išgirskite, o kalnai, VIEŠPATIES ginčą, ir jūs, stiprieji žemės pamatai; nes VIEŠPATS bylinėjasi su savo tauta, jis bylinėsis su Izraeliu.'),
  (@b33, 6, 3, '„O mano tauta, ką tau padariau? Kuo tave nuvarginau? Paliudyk prieš mane.'),
  (@b33, 6, 4, 'Nes aš išvedžiau tave aukštyn iš Egipto šalies, ir atpirkau tave iš tarnų namų; ir siunčiau tavo akivaizdon Mozę, Aaroną ir Mirjamą.'),
  (@b33, 6, 5, 'O mano tauta, atsimink, ką tarėsi Balakas, Moabo karalius, ir ką jam atsakė Balaamas, Beoro sūnus, nuo Šitimo iki Gilgalo; kad žinotumėte VIEŠPATIES teisumą“.'),
  (@b33, 6, 6, 'Su kuo man ateiti VIEŠPATIES akivaizdon ir nusilenkti prieš aukštąjį Dievą? Ar ateiti jo akivaizdon su deginamosiomis atnašomis, su metiniais veršiais?'),
  (@b33, 6, 7, 'Ar VIEŠPAČIUI patiks tūkstančiai avinų ar dešimtys tūkstančių aliejaus upių? Ar man atiduoti savo pirmagimį už savo nusižengimą, savo kūno vaisių už savo sielos nuodėmę?'),
  (@b33, 6, 8, 'Tau, žmogau, jis paskelbė, kas yra gerai; ir ko VIEŠPATS reikalauja iš tavęs, tai elgtis teisingai, mylėti gailestingumą ir vaikščioti nuolankiai su savo Dievu.'),
  (@b33, 6, 9, 'VIEŠPATIES balsas šaukia miestui, ir išmintingasis matys tavo vardą; klausykite lazdos ir to, kas ją paskyrė.'),
  (@b33, 6, 10, 'Ar dar tebėra nedorėlio namuose nedorybės turtai ir sumažintas saikas, kuris yra pasibjaurėjimas?'),
  (@b33, 6, 11, 'Ar laikysiu tyrais tuos, esančius su nedoromis svarstyklėmis ir su apgaulingų svarsčių maišeliu?'),
  (@b33, 6, 12, 'Nes jo turtuoliai pilni smurto ir jo gyventojai kalba melus, ir jų liežuvis yra melagingas jų burnoje.'),
  (@b33, 6, 13, 'Todėl padarysiu tave sergantį, mušdamas tave, niokodamas tave dėl tavo nuodėmių.'),
  (@b33, 6, 14, 'Tu valgysi, bet nepasisotinsi; ir tavo prislėgtumas bus tavo tarpe; tu nusitversi, bet neišgelbėsi; o ką išgelbėsi, tai atiduosiu kalavijui.'),
  (@b33, 6, 15, 'Tu sėsi, bet nepjausi; tu suminsi alyvas, bet nesitepsi aliejumi, ir saldų vyną, bet negersi vyno.'),
  (@b33, 6, 16, 'Nes laikomasi Omrio įstatų ir visų Ahabo namų darbų, ir jūs vaikštote pagal jų patarimus; kad padaryčiau tave dykyne ir tavo gyventojus švilpavimu; todėl nešiosite mano tautos priekaištą“.'),
  (@b33, 7, 1, 'Vargas man! Nes man, kaip surinkus vasaros vaisius, kaip vynuogių parankos per vynuogių rinkimą: nei vienos kekės pavalgyti; mano siela trokšta pirmųjų prinokusių vaisių.'),
  (@b33, 7, 2, 'Žuvo geri žmonės žemėje; ir nėra tiesaus tarp žmonių; jie visi tykoja kraujo; jie kiekvienas medžioja savo brolį tinklu.'),
  (@b33, 7, 3, 'Kad jie abiem rankom uoliai darytų pikta, kunigaikštis reikalauja, ir teisėjas reikalauja atlyginimo; didžiūnas ištaria savo piktadariškus norus; taip jie tai užbaigia.'),
  (@b33, 7, 4, 'Geriausias iš jų yra kaip erškėtis; tiesiausias yra aštresnis už dygliuotą tvorą; tavo sargų diena, tavo aplankymas ateina; dabar bus jų sumišimas.'),
  (@b33, 7, 5, 'Netikėkite draugu, nepasitikėkite vedliu; saugok savo burnos duris nuo gulinčios prie tavo krūtinės.'),
  (@b33, 7, 6, 'Nes sūnus užtraukia negarbę tėvui, duktė sukyla prieš savo motiną, marti prieš savo uošvę; žmogaus priešai – jo paties namiškiai.'),
  (@b33, 7, 7, 'Todėl aš žiūrėsiu į VIEŠPATĮ; lauksiu savo išgelbėjimo Dievo; mano Dievas išklausys mane.'),
  (@b33, 7, 8, 'Nesidžiauk prieš mane, o mano prieše; nukritęs aš atsikelsiu; kai sėdžiu tamsoje, VIEŠPATS bus man šviesa.'),
  (@b33, 7, 9, 'Aš nešiosiu VIEŠPATIES pasipiktinimą, – nes jam nusidėjau, – kol jis apgins mano bylą ir įvykdys dėl manęs teismą; jis išves mane į šviesą, aš pamatysiu jo teisumą.'),
  (@b33, 7, 10, 'Tada mano priešė tai matys, ir gėda apdengs tą, kuri man sakė: „Kur yra VIEŠPATS, tavo Dievas?“ Mano akys matys ją; dabar ji bus sutrypta kaip gatvių purvas.'),
  (@b33, 7, 11, 'Tą dieną, kai turės būti statomos tavo sienos, tą dieną bus atitolintas įsakas.'),
  (@b33, 7, 12, 'Tą dieną ateis pas tave iš Asirijos, iš sutvirtintų miestų, nuo tvirtovės iki upės, nuo jūros iki jūros ir nuo kalno iki kalno.'),
  (@b33, 7, 13, 'Tačiau šalis bus dykynė dėl jos gyventojų, dėl jų darbų vaisių.'),
  (@b33, 7, 14, 'Ganyk savo tautą savo lazda, savo paveldo kaimenę, atsiskyrėliškai gyvenančią miške, Karmelio viduryje; tegul jos ganosi Bašane ir Gileade, kaip senomis dienomis.'),
  (@b33, 7, 15, 'Aš jam parodysiu nuostabių dalykų, kaip tomis dienomis, kai išėjai iš Egipto šalies.'),
  (@b33, 7, 16, 'Tautos matys ir susigės dėl visos savo galios; jie uždės rankas ant savo burnos, jų ausys bus kurčios.'),
  (@b33, 7, 17, 'Jos laižys dulkes kaip gyvatė, jos išlįs iš savo skylių kaip žemės kirminai; jos bijos VIEŠPATIES, mūsų Dievo, ir baiminsis dėl tavęs.'),
  (@b33, 7, 18, 'Kas yra toks Dievas, kaip tu, kuris atleidžia neteisybę ir praeina pro šalį savo paveldo likučio nusižengimui? Jis nelaiko savo pykčio per amžius, nes jis gėrisi gailestingumu.'),
  (@b33, 7, 19, 'Jis atsigręš, jis pasigailės mūsų; jis nuslopins mūsų neteisybes; ir tu numesi į jūros gelmes visas jų nuodėmes.'),
  (@b33, 7, 20, 'Tu įvykdysi tiesą Jokūbui, gailestingumą Abraomui, kurį prisiekei mūsų tėvams nuo senų dienų.'),
  (@b34, 1, 1, 'Ninevės našta. Elkošiečio Nahumo regėjimo knyga.'),
  (@b34, 1, 2, 'Dievas pavydus, ir VIEŠPATS keršija; VIEŠPATS keršija ir yra įtūžęs; VIEŠPATS atkeršys savo priešininkams, ir jis taupo rūstybę savo priešams.'),
  (@b34, 1, 3, 'VIEŠPATS yra lėtas pykti ir didis galia, ir tikrai neišteisins nedorėlio; VIEŠPATS turi savo kelią viesule ir audroje, o debesys – jo kojų dulkės.'),
  (@b34, 1, 4, 'Jis subara jūrą ir padaro ją sausą, ir išdžiovina visas upes; nuvysta Bašanas ir Karmelis, ir Libano žiedas nuvysta.'),
  (@b34, 1, 5, 'Kalnai dreba prieš jį, ir kalvos tirpsta, ir žemė dega jo akivaizdoje, taip, pasaulis ir visi jame gyvenantys.'),
  (@b34, 1, 6, 'Kas gali atsilaikyti prieš jo pasipiktinimą? Kas gali pakęsti jo pykčio įniršyje? Jo įtūžis išsilieja kaip ugnis, ir jis išvarto uolas.'),
  (@b34, 1, 7, 'VIEŠPATS yra geras, tvirtovė bėdos dieną; jis pažįsta tuos, kurie juo pasitiki.'),
  (@b34, 1, 8, 'Bet užliejančiu tvanu jis padarys visišką galą jos vietai, ir tamsa persekios jo priešus.'),
  (@b34, 1, 9, 'Ką sumanote prieš VIEŠPATĮ? Jis padarys visišką galą; bėda antrą kartą nebeiškils.'),
  (@b34, 1, 10, 'Nes kol jie yra susipynę kaip erškėčiai, kol jie yra girti kaip girtuokliai, jie bus praryti kaip visiškai sausos ražienos.'),
  (@b34, 1, 11, 'Iš tavęs išeina tas, kuris sumano pikta prieš VIEŠPATĮ – nedorasis patarėjas.'),
  (@b34, 1, 12, 'Taip sako VIEŠPATS: „Nors jie yra ramūs ir taip pat gausūs, tačiau taip jie bus iškirsti, kai jis praeis. Nors tave varginau, daugiau tavęs nebevarginsiu.'),
  (@b34, 1, 13, 'Nes dabar nulaušiu jo jungą nuo tavęs ir sutraukysiu tavo pančius“.'),
  (@b34, 1, 14, 'Ir VIEŠPATS įsakė dėl tavęs, kad iš tavo vardo nebebūtų sėjama; iš tavo dievų namų iškirsiu raižytus atvaizdus ir nulietus atvaizdus; aš padarysiu tavo kapą, nes tu esi niekingas“.'),
  (@b34, 1, 15, 'Štai kalnuose kojos, nešančio gerą žinią, skelbiančio taiką! O Juda, švęsk savo iškilmingas šventes, tesėk savo įžadus; nes daugiau nebepereis per tave nedorėlis; jis visiškai iškirstas.'),
  (@b34, 2, 1, 'Tas, kuris daužo į gabalus, atėjo aukštyn tau prieš akis; saugok sutvirtinimą, stebėk kelią, sustiprink savo strėnas, galingai sustiprink savo jėgas.'),
  (@b34, 2, 2, 'Nes VIEŠPATS nusuko Jokūbo puikybę kaip Izraelio puikybę; nes tuštintojai juos ištuštino ir sudarkė jų vynmedžio šakas.'),
  (@b34, 2, 3, 'Jo galiūnų skydai paraudonavo, narsuoliai nusidažę skaisčiai raudonai; vežimai bus su liepsnojančiais deglais jo paruošimo dieną, o eglės siaubingai drebės.'),
  (@b34, 2, 4, 'Gatvėse siautės vežimai, jie grūsis vienas priešais kitą plačiuose keliuose; jie atrodys kaip deglai, jie lakstys kaip žaibai.'),
  (@b34, 2, 5, 'Jis suminės savo vertinguosius; jie suklups eidami; jie skubės prie jo sienos, ir apsauga bus paruošta.'),
  (@b34, 2, 6, 'Upių vartai bus atidaryti, ir rūmai bus ištirpdyti.'),
  (@b34, 2, 7, 'Ir Huzabas bus išvestas nelaisvėn, jis bus nuvestas aukštyn, ir jo tarnaitės ves jį tarsi karvelio balsais, mušdamos sau į krūtinę.'),
  (@b34, 2, 8, 'Bet Ninevė nuo seno yra kaip vandens tvenkinys; tačiau jie pabėgs. Jie šauks: „Sustokite, sustokite“, bet niekas neatsigręš.'),
  (@b34, 2, 9, 'Grobkite sidabrą, grobkite auksą; nes atsargoms ir šlovei nėra galo iš visokių geistinų reikmenų.'),
  (@b34, 2, 10, 'Ji negyvenama, tuščia ir nuniokota; alpsta širdis, daužosi kelis į kelią, didelis skausmas visose strėnose ir visų veidai pajuodę.'),
  (@b34, 2, 11, 'Kur yra liūtų buveinė ir jaunų liūtų maitinimosi vieta, kur vaikščiojo liūtas, tai yra, senas liūtas ir liūto jauniklis, ir niekas jų neišgąsdino?'),
  (@b34, 2, 12, 'Liūtas draskė, kad užtektų jo jaunikliams ir smaugė savo liūtėms, ir pripildė grobio savo olas ir savo urvus to, ko prisiplėšė.'),
  (@b34, 2, 13, '„Štai aš esu prieš tave, – sako kariuomenių VIEŠPATS, – aš sudeginsiu jos vežimus dūmuose, ir tavo jaunus liūtus suris kalavijas; aš iškirsiu tavo grobį iš žemės, ir nebebus girdimas tavo pasiuntinių balsas“.'),
  (@b34, 3, 1, 'Vargas kruvinam miestui! Jis visas pilnas melų ir plėšikavimo; plėšimas nesiliauja;'),
  (@b34, 3, 2, 'botagų pliaukšėjimas ir ratų dardėjimo, šuoliuojančių žirgų ir šokinėjančių vežimų triukšmas.'),
  (@b34, 3, 3, 'Raitelis pakelia švytintį kalaviją ir blizgančią ietį; daugybė užmuštų, didžiulis skaičius lavonų; nėra galo jų lavonams; jie klumpa ant jų lavonų;'),
  (@b34, 3, 4, 'dėl daugybės ištvirkavimų gražios paleistuvės, raganavimų meistrės, kuri pardavinėja tautas savo paleistuvavimais ir šeimas savo raganavimais.'),
  (@b34, 3, 5, '„Štai aš esu prieš tave, – sako kariuomenių VIEŠPATS; – aš atidengsiu tavo skvernus, užkeldamas tau ant veido, ir parodysiu tautoms tavo nuogumą ir karalystėms tavo gėdą.'),
  (@b34, 3, 6, 'Apmėtysiu tave pasibjaurėtinu nešvarumu, padarysiu tave niekingą ir pastatysiu tave reginiu.'),
  (@b34, 3, 7, 'Ir įvyks, kad kiekvienas, kuris tave matys, bėgs nuo tavęs ir sakys: ‘Ninevė nusiaubta; kas ją apraudos? Kur man ieškoti tau guodėjų?’'),
  (@b34, 3, 8, 'Argi tu geresnė už tankiai gyvenamą Noją, išsidėsčiusį tarp upių, apsuptą vandenų, kurio pylimas buvo jūra, ir jo siena buvo iš jūros?'),
  (@b34, 3, 9, 'Etiopija ir Egiptas buvo jo stiprybė, ir ji buvo begalinė; Putas ir lubimai buvo tavo pagalbininkai.'),
  (@b34, 3, 10, 'Tačiau jis buvo išvestas, jis išėjo į nelaisvę; maži jo vaikai buvo triuškinami visų gatvių galuose; dėl jo garbingųjų metė burtus, ir visi jo didžiūnai buvo sukaustyti grandinėmis.'),
  (@b34, 3, 11, 'Tu irgi pasigersi; tu būsi pasislėpusi, tu irgi ieškosi stiprybės dėl priešo.'),
  (@b34, 3, 12, 'Visos tavo tvirtovės bus kaip figmedžiai su pirmosiomis prinokusiomis figomis; jei kas juos papurtytų, jos kristų į valgančiojo burną.'),
  (@b34, 3, 13, 'Štai tavo tauta tavo tarpe yra moterys; tavo šalies vartai bus plačiai atverti tavo priešams; ugnis suės tavo skląsčius.'),
  (@b34, 3, 14, 'Pasisemk vandens apgulimui, sutvirtink savo tvirtoves; eik į molį ir mindyk skiedinį, sustiprink plytų degimo krosnį.'),
  (@b34, 3, 15, 'Ten surys tave ugnis; iškirs tave kalavijas, jis suės tave kaip kandžių vikšrai; dauginkis kaip kandžių vikšrai, dauginkis kaip skėriai.'),
  (@b34, 3, 16, 'Tu padarei savo pirklių daugiau nei dangaus žvaigždžių; kandžių vikšrai sugadina ir nuskrenda.'),
  (@b34, 3, 17, 'Tavo karūnuotieji yra kaip skėriai, ir tavo vadai – kaip didieji žiogai, stovyklaujantys šaltą dieną ant tvorų, bet saulei patekėjus jie nulekia, ir niekas nežino jų vietos, kur jie yra.'),
  (@b34, 3, 18, 'O Asirijos karaliau, tavo ganytojai snaudžia; tavo kilmingieji gyvens dulkėse; tavo tauta išsklaidyta kalnuose, ir nėra, kas juos surinktų.'),
  (@b34, 3, 19, 'Nėra pagijimo tavo sumušimui; sunki tavo žaizda; visi, kurie išgirsta gandą apie tave, plos rankomis dėl tavęs; nes pas ką gi nuolatos neateidavo tavo nedorybė?'),
  (@b35, 1, 1, 'Našta, kurią matė pranašas Habakukas.'),
  (@b35, 1, 2, 'O VIEŠPATIE, kiek ilgai aš šauksiu, o tu neišgirsi!? Šauksiu tau apie smurtą, o tu negelbėsi!?'),
  (@b35, 1, 3, 'Kodėl man rodai neteisybę ir duodi man pamatyti skriaudas? Nes plėšikavimas ir smurtas yra mano akivaizdoje; ir yra sukeliantieji vaidus ir ginčus.'),
  (@b35, 1, 4, 'Todėl įstatymas nusilpęs, ir teismas niekada neišeina į priekį; nes nedorėlis apsupa teisųjį; todėl vyksta neteisingas teismas.'),
  (@b35, 1, 5, 'Pažiūrėkite tarp pagonių, atkreipkite dėmesį ir stebėte stebėkitės; nes aš darysiu darbą jūsų dienomis, kuriuo jūs netikėtumėte, net jeigu jums apie jį pasakotų.'),
  (@b35, 1, 6, 'Nes štai aš pakeliu kaldėjus, tą rūsčią ir greitą tautą, kuri žygiuos per šalies platumą, kad pasisavintų ne savo gyvenamas vietas.'),
  (@b35, 1, 7, 'Jie baisūs ir bauginantys; iš jų pačių išeis jų teismas ir jų kilnumas.'),
  (@b35, 1, 8, 'Jų žirgai greitesni už leopardus ir piktesni už vakaro vilkus; ir jų raiteliai pasklis, jų raiteliai atvyks iš toli; jie skris kaip erelis, skubantis ėsti.'),
  (@b35, 1, 9, 'Jie visi ateis smurtauti; jų veidai siurbčios kaip rytų vėjas, ir jie surinks belaisvius kaip smėlį.'),
  (@b35, 1, 10, 'Jie tyčiosis iš karalių, ir kunigaikščiai jiems bus paniekos objektas; jie išjuoks kiekvieną tvirtovę, nes jie supils dulkes ir ją paims.'),
  (@b35, 1, 11, 'Paskui pasikeis jo nuomonė, ir jis pereis ir nusikals, priskirdamas šią savo jėgą savo dievui.'),
  (@b35, 1, 12, 'Argi tu nesi nuo amžinybės, o VIEŠPATIE, mano Dieve, mano Šventasis? Mes nemirsime. O VIEŠPATIE, tu juos paskyrei teismui; o galingasis Dieve, tu įtvirtinai juos pabaudimui.'),
  (@b35, 1, 13, 'Tu esi per tyrų akių, kad žvelgtum į pikta, ir negali žiūrėti į neteisybę; kodėl žiūri į klastingai besielgiančius ir sulaikai savo liežuvį, kai nedorėlis praryja teisesnį už save?'),
  (@b35, 1, 14, 'Padarai žmones kaip jūros žuvis, kaip roplius, neturinčius sau valdovo.'),
  (@b35, 1, 15, 'Juos visus ištraukia kabliuku, juos pagauna savo tinklu ir surenka savo velkamu tinklu; todėl jie linksminasi ir džiūgauja.'),
  (@b35, 1, 16, 'Todėl jis aukoja savo tinklui ir degina smilkalus savo velkamam tinklui; nes jais riebi jų dalis ir jų maistas gausus.'),
  (@b35, 1, 17, 'Ar todėl jie ištuštins savo tinklą ir nuolat be pasigailėjimo žudys tautas?'),
  (@b35, 2, 1, 'Aš stovėsiu savo sargyboje, atsistosiu bokšte ir žiūrėsiu, kad pamatyčiau, ką jis man pasakys ir ką man atsakyti, kai esu baramas.'),
  (@b35, 2, 2, 'Ir VIEŠPATS man atsakė ir tarė: „Užrašyk regėjimą aiškiai ant plokščių, kad bėgantysis jį galėtų perskaityti!'),
  (@b35, 2, 3, 'Nes regėjimas yra dar skirtam laikui, bet pabaigoje jis kalbės ir nemeluos; nors jis užtruks, lauk jo, nes jis tikrai ateis ir neužtruks.'),
  (@b35, 2, 4, 'Štai, jo išpuikusi siela nėra tiesi jame; bet teisusis gyvens savo tikėjimu.'),
  (@b35, 2, 5, 'Taip pat, kadangi jis nusižengia vynu, yra išdidus žmogus, nepasilieka namuose, kuris išplečia savo norą kaip pragaras ir yra kaip mirtis, ir negali pasisotinti, bet surenka sau visas tautybes ir sukrauna sau visas tautas;'),
  (@b35, 2, 6, 'argi visos šitos nesiims prieš jį palyginimo ir pašaipios patarlės ir nesakys: ‘Vargas tam, kuris daugina tai, kas ne jo! Kiek ilgai? Ir tam, kuris apsikrauna tirštu moliu!’'),
  (@b35, 2, 7, 'Argi staiga nepakils tie, kurie tave kandžios, ir argi neatsibus tie, kurie neduos tau ramybės, ir tu jiems būsi grobis?'),
  (@b35, 2, 8, 'Kadangi tu apiplėšei daug tautybių, tave apiplėš visi tautų likučiai – dėl žmonių kraujo, dėl smurto šaliai, miestui ir visiems jų gyventojams.'),
  (@b35, 2, 9, 'Vargas tam, kuris geidžia pikto godumo savo namams, kad susuktų sau lizdą aukštybėse, kad išsigelbėtų nuo blogio galios!'),
  (@b35, 2, 10, 'Tu patarei gėdą savo namams, iškirsdamas daugelį tautų, ir nusidėjai prieš savo sielą.'),
  (@b35, 2, 11, 'Nes akmuo šauks iš sienos, ir sija jam atsilieps iš medienos.'),
  (@b35, 2, 12, 'Vargas tam, kuris stato miestelį krauju ir įtvirtina miestą neteisybe!'),
  (@b35, 2, 13, 'Štai ar tai ne nuo kariuomenių VIEŠPATIES, kad tautos triūsia ugniai ir tautos nusivargina tuštybei?'),
  (@b35, 2, 14, 'Nes žemė bus pripildyta VIEŠPATIES šlovės pažinimo, kaip kad vandenys uždengia jūrą.'),
  (@b35, 2, 15, 'Vargas tam, kuris duoda savo kaimynui gerti, kuris kišì jam savo butelį ir jį nugirdai, kad galėtum pamatyti jo nuogumą!'),
  (@b35, 2, 16, 'Tu prisipildei gėda vietoj šlovės; gerk ir tu, ir teatsidengia tavo apyvarpė; VIEŠPATIES dešinės taurė bus nukreipta į tave, ir gėdingas vėmimas bus ant tavo šlovės.'),
  (@b35, 2, 17, 'Nes tave apdengs smurtas Libanui ir gyvulių plėšimas, kuris juos gąsdino, – dėl žmonių kraujo ir dėl smurto šaliai, miestui bei visiems ten gyvenantiems.'),
  (@b35, 2, 18, 'Kokia nauda iš raižyto atvaizdo, kurį išraižė jo dirbėjas; iš nulieto atvaizdo, melo mokytojo, kad juo pasitiki savo dirbinio dirbėjas, idant padirbtų nebylius stabus?'),
  (@b35, 2, 19, 'Vargas tam, kuris sako medžiui: ‘Pabusk’; nebyliam akmeniui: ‘Kelkis’, jis pamokys! Štai jis padengtas auksu ir sidabru, jame visiškai nėra kvapo.'),
  (@b35, 2, 20, 'Bet VIEŠPATS yra savo šventoje šventykloje; tetyli prieš jį visa žemė“.'),
  (@b35, 3, 1, 'Pranašo Habakuko malda Šigejonotu.'),
  (@b35, 3, 2, 'O VIEŠPATIE, aš išgirdau tavo kalbą ir išsigandau; o VIEŠPATIE, atgaivink savo darbą tarp metų, duok pažinti metų tarpe; užsirūstinęs atsimink gailestingumą.'),
  (@b35, 3, 3, 'Dievas atėjo iš Temano, Šventasis – nuo Parano kalno. Sela. Jo šlovė apdengė dangus, ir žemė buvo pilna jo gyriaus.'),
  (@b35, 3, 4, 'Jo spindesys buvo kaip šviesa; iš jo rankos ėjo ragai; ten buvo jo galios slėptuvė.'),
  (@b35, 3, 5, 'Pirma jo ėjo maras, o degančios anglys išėjo ties jo kojomis.'),
  (@b35, 3, 6, 'Jis stovėjo ir matavo žemę; jis pažiūrėjo ir išsklaidė tautas; išsisklaidė amžinieji kalnai, nusilenkė amžinos kalvos; jo keliai yra amžini.'),
  (@b35, 3, 7, 'Aš mačiau Kušano palapines bėdoje; Midjano šalies uždangos drebėjo.'),
  (@b35, 3, 8, 'Ar VIEŠPATS buvo nepatenkintas prieš upes? Ar tavo pyktis buvo prieš upes? Ar tavo rūstybė buvo prieš jūrą, kad važiavai savo žirgais, savo išgelbėjimo vežimais?'),
  (@b35, 3, 9, 'Tavo lankas buvo apnuogintas pagal genčių įžadus, būtent tavo žodį. Sela. Tu upėmis išraižei žemę.'),
  (@b35, 3, 10, 'Tave pamatę drebėjo kalnai; perėjo vandens išsiliejimas; gelmės ištarė savo balsą, iškėlė savo rankas į aukštybes.'),
  (@b35, 3, 11, 'Saulė ir mėnulis stovėjo nejudėdami savo buveinėje; jie ėjo šviečiant tavo strėlėms, spindint tavo blizgančiai iečiai.'),
  (@b35, 3, 12, 'Pasipiktinęs tu žygiavai per šalį, supykęs kūlei pagonis.'),
  (@b35, 3, 13, 'Tu išėjai savo tautos gelbėti – gelbėti su savo pateptuoju; tu sužeidei galvą iš nedorėlio namų, atidengdamas pamatus iki sprando. Sela.'),
  (@b35, 3, 14, 'Tu pervėrei jo lazdomis jo gyvenviečių galvą; jie išėjo kaip viesulas manęs išsklaidyti; jų džiaugsmas – tarsi slaptai praryti vargšą.'),
  (@b35, 3, 15, 'Su savo žirgais tu ėjai per jūrą, per didžiulių vandenų krūvą.'),
  (@b35, 3, 16, 'Kai išgirdau, drebėjo mano pilvas; nuo balso virpėjo mano lūpos; pūvinys įsimetė į mano kaulus, ir aš drebėjau savyje, kad ilsėčiausi bėdos dieną; kai jis ateis aukštyn pas tautą, jis įsiverš pas juos su savo pulkais.'),
  (@b35, 3, 17, 'Nors figmedis nežydės ir nebus vaisių vynmedžiuose; alyvmedžio triūsas apvils, ir laukai neduos maisto; kaimenė bus iškirsta iš aptvaro, ir nebus bandos tvartuose;'),
  (@b35, 3, 18, 'tačiau aš džiaugsiuosi VIEŠPAČIU, aš džiūgausiu savo išgelbėjimo Dievu.'),
  (@b35, 3, 19, 'VIEŠPATS Dievas – mano stiprybė, jis padarys mano kojas kaip elnių ir vedžios mane mano aukštumose. Vyriausiam giesmininkui mano styginiais instrumentais.'),
  (@b36, 1, 1, 'VIEŠPATIES žodis, kuris atėjo Sofonijui, – sūnui Kušio, sūnui Gedalijos, sūnui Amarijos, sūnui Chizkijo, – Jozijo, sūnaus Amono, Judos karaliaus, dienomis.'),
  (@b36, 1, 2, '„Aš naikinte sunaikinsiu viską iš šalies, – sako VIEŠPATS.'),
  (@b36, 1, 3, '– Sunaikinsiu žmones ir gyvulius; sunaikinsiu dangaus skrajūnus bei jūros žuvis ir suklupimo kliuvinius su nedorėliais; ir iškirsiu žmones iš šalies, – sako VIEŠPATS.'),
  (@b36, 1, 4, '– Aš ištiesiu savo ranką į Judą ir į visus Jeruzalės gyventojus; iškirsiu iš šitos vietos Baalo likutį ir kemarų vardą su kunigais;'),
  (@b36, 1, 5, 'ir tuos, kurie ant stogų garbina dangaus kariuomenę; ir tuos, kurie garbina, kurie prisiekia VIEŠPAČIU ir prisiekia Malkamu;'),
  (@b36, 1, 6, 'ir tuos, kurie nusisukę nuo VIEŠPATIES; ir tuos, kurie neieškojo VIEŠPATIES ir nesiteiravo apie jį.'),
  (@b36, 1, 7, 'Nutilk Viešpaties DIEVO akivaizdoje; nes čia pat VIEŠPATIES diena; nes VIEŠPATS paruošė auką, jis pakvietė savo svečius.'),
  (@b36, 1, 8, 'Ir VIEŠPATIES aukos dieną atsitiks, kad aš nubausiu kunigaikščius ir karaliaus vaikus, ir visus, vilkinčius keistais drabužiais.'),
  (@b36, 1, 9, 'Tą pačią dieną nubausiu visus, šokančius per slenkstį, pripildančius savo valdovų namus smurto ir apgaulės.'),
  (@b36, 1, 10, 'Ir tą dieną įvyks, – sako VIEŠPATS, – kad bus šauksmo garsas nuo Žuvų vartų ir kauksmas nuo antrųjų, ir didelė griūtis nuo kalvų.'),
  (@b36, 1, 11, 'Kaukite, Maktešo gyventojai, nes pakirsta visa prekiautojų tauta; iškirsti visi, nešiojantys sidabrą.'),
  (@b36, 1, 12, 'Ir tuo metu įvyks, kad apieškosiu Jeruzalę žvakėmis ir nubausiu žmones, sėdinčius ant savo nuosėdų, sakančius savo širdyje: ‘VIEŠPATS nedarys nei gera, nei pikta’.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b36, 1, 13, 'Todėl jų turtai taps grobiu ir jų namai tuštuma; jie statys namus, bet negyvens juose; jie sodins vynuogynus, bet negers jų vyno.'),
  (@b36, 1, 14, 'Arti didžioji VIEŠPATIES diena, ji arti ir labai skuba, – VIEŠPATIES dienos balsas; ten karčiai šauks galiūnas.'),
  (@b36, 1, 15, 'Ta diena – rūstybės diena, suspaudimo ir sielvarto diena, niokojimo ir nusiaubimo diena, tamsos ir niūrumo diena, debesų ir tirštos tamsos diena,'),
  (@b36, 1, 16, 'trimito ir pavojaus signalo diena prieš aptvertus miestus ir prieš aukštuosius bokštus.'),
  (@b36, 1, 17, 'Aš atnešiu žmonėms sielvartą, kad jie vaikščios kaip akli, nes nusidėjo prieš VIEŠPATĮ; jų kraujas bus išlietas kaip dulkės, o jų kūnas – kaip mėšlas.'),
  (@b36, 1, 18, 'Nei jų sidabras, nei jų auksas negalės jų išgelbėti VIEŠPATIES rūstybės dieną; bet visa šalis bus praryta jo pavydo ugnimi; nes jis greitai atsikratys visais gyvenančiais šalyje“.'),
  (@b36, 2, 1, '„Susirinkite kartu, taip, susirinkite, o negeistina tauta;'),
  (@b36, 2, 2, 'kol dar neišėjo įsakas, kol diena nepraėjo kaip pelai, kol ant jūsų neužėjo įnirtingas VIEŠPATIES pyktis, kol ant jūsų neužėjo VIEŠPATIES pykčio diena.'),
  (@b36, 2, 3, 'Ieškokite VIEŠPATIES, visi žemės romieji, kurie vykdote jo teismą; ieškokite teisumo, ieškokite romumo; galbūt būsite paslėpti VIEŠPATIES pykčio dieną.'),
  (@b36, 2, 4, 'Nes Gaza bus palikta, o Aškelonas – dykynė; Ašdodą išvarys vidudienį, o Ekronas bus išrautas su šaknimis.'),
  (@b36, 2, 5, 'Vargas pajūrio srities gyventojams, keretų tautai! VIEŠPATIES žodis yra prieš jus, o Kanaane, filistinų šalie, aš sunaikinsiu tave taip, kad nebeliks gyventojų.'),
  (@b36, 2, 6, 'Ir pajūrio sritis bus piemenims buveinėmis, nameliais, o kaimenėms – aptvarais.'),
  (@b36, 2, 7, 'Ir ta sritis bus Judos namų likučiui; jie ganysis joje; Aškelono namuose vakare jie suguls; nes VIEŠPATS, jų Dievas, juos aplankys ir nukreips jų nelaisvę.'),
  (@b36, 2, 8, 'Aš girdėjau Moabo priekaištą ir Amono vaikų keiksmus, kuriais jie priekaištavo mano tautai ir didžiavosi prieš jų ribas.'),
  (@b36, 2, 9, 'Todėl, kaip aš gyvas, – sako kariuomenių VIEŠPATS, Izraelio Dievas, – tikrai Moabas bus kaip Sodoma ir Amono vaikai kaip Gomora, būtent dilgėlių dauginimosi vieta, druskos duobės ir amžina dykynė; mano tautos likutis juos apiplėš, ir mano tautos likutis juos pasisavins.'),
  (@b36, 2, 10, 'Tai jie turės už savo išdidumą, nes jie priekaištavo ir didžiavosi prieš kariuomenių VIEŠPATIES tautą.'),
  (@b36, 2, 11, 'Baisus bus jiems VIEŠPATS; nes jis kankins badu visus žemės dievus; ir žmonės garbins jį, kiekvienas iš savo vietos, būtent visos pagonių salos.'),
  (@b36, 2, 12, 'Ir jūs, etiopai, jūs būsite nužudyti mano kalaviju.'),
  (@b36, 2, 13, 'Jis išties savo ranką prieš šiaurę ir sunaikins Asiriją; ir pavers Ninevę dykyne, sausa kaip dykuma.'),
  (@b36, 2, 14, 'Gulinės jos viduryje kaimenės, visi tautų žvėrys; kormoranas ir didysis baublys apsigyvens jos aukštutinėse sąramose; jų balsai giedos languose; slenksčiuose bus nuniokojimas; nes jis nudengs kedro dirbinius.'),
  (@b36, 2, 15, 'Tai džiūgaujantis miestas, nerūpestingai gyvenantis, sakantis savo širdyje: ‘Aš esu, ir be manęs nėra kito’; kaip jis pavirto dykyne, vieta žvėrims atsigulti! Kiekvienas praeinantis pro jį, švilps ir mos ranka“.'),
  (@b36, 3, 1, '„Vargas purvinam ir suterštam, engiančiam miestui!'),
  (@b36, 3, 2, 'Jis nepakluso balsui, nepriėmė pataisymo, nepasitikėjo VIEŠPAČIU, nesiartino prie savo Dievo.'),
  (@b36, 3, 3, 'Jo kunigaikščiai jo viduje yra riaumojantys liūtai, jo teisėjai – vakaro vilkai, jie negraužia kaulų iki rytojaus.'),
  (@b36, 3, 4, 'Jo pranašai – lengvabūdžiai, išdavikiški žmonės; jo kunigai suteršė šventovę, jie sulaužė įstatymą.'),
  (@b36, 3, 5, 'Teisus VIEŠPATS yra jo viduryje; jis nedarys neteisybės; kas rytą jis atveda savo teismą į šviesą, jis neapvilia; bet neteisieji nepažįsta gėdos.'),
  (@b36, 3, 6, 'Aš iškirtau tautas; jų bokštai nuniokoti; ištuštinau jų gatves, kad niekas jomis neina; jų miestai sunaikinti, kad nebėra žmonių, nebėra gyventojų.'),
  (@b36, 3, 7, 'Aš tariau: ‘Tu tikrai bijosi manęs, priimsi pamokymą’; taip jų buveinės nebūtų buvę iškirstos, kad ir kaip juos baudžiau; bet jie anksti atsikėlę sugadino visus savo darbus.'),
  (@b36, 3, 8, 'Todėl laukite manęs, – sako VIEŠPATS, – iki tos dienos, kai pakilsiu plėšti; nes esu nusprendęs surinkti tautas, kad suburčiau karalystes, išlieti ant jų savo pasipiktinimą – visą savo smarkų pyktį; nes visa žemė bus suryta mano pavydo ugnimi.'),
  (@b36, 3, 9, 'Nes tada nukreipsiu tautoms tyrą kalbą, kad jos visos galėtų šauktis VIEŠPATIES vardo, vieningai jam tarnauti.'),
  (@b36, 3, 10, 'Iš anapus Etiopijos upių mano maldautojai, būtent mano išsklaidytųjų dukra, atneš mano atnašą.'),
  (@b36, 3, 11, 'Tą dieną nebereikės tau gėdytis dėl visų savo darbų, kuriais prieš mane nusižengei; nes tada pašalinsiu iš tavo tarpo tuos, kurie džiaugiasi tavo išdidumu, ir tu nebebūsi išdidi dėl mano šventojo kalno.'),
  (@b36, 3, 12, 'Taip pat paliksiu tavo tarpe vargstančią ir beturtę tautą, ir jie pasitikės VIEŠPATIES vardu.'),
  (@b36, 3, 13, 'Izraelio likutis nedarys neteisybės ir nekalbės melų; ir nebus rasta jų burnoje klastingo liežuvio; nes jie ganysis ir gulinės, ir niekas jų negąsdins“.'),
  (@b36, 3, 14, 'Giedok, o Siono dukra; šūkauk, o Izraeli; linksminkis ir džiūgauk visa širdimi, o Jeruzalės dukra.'),
  (@b36, 3, 15, 'VIEŠPATS pašalino tavo teismus, jis išvarė tavo priešą; Izraelio karalius, tai yra VIEŠPATS, yra tavo tarpe; tu nebematysi to, kas pikta.'),
  (@b36, 3, 16, 'Tą dieną bus sakoma Jeruzalei: „Nebijok“, Sionui: „Tenenusilpsta tavo rankos“.'),
  (@b36, 3, 17, 'VIEŠPATS, tavo Dievas, tavo tarpe yra galingas; jis išgelbės, jis su džiaugsmu džiaugsis tavimi; jis ilsėsis savo meilėje, jis giedodamas džiūgaus dėl tavęs.'),
  (@b36, 3, 18, 'Aš surinksiu sielvartaujančius dėl iškilmingo susirinkimo, tuos, kurie yra iš tavęs, kuriems to priekaištas buvo našta.'),
  (@b36, 3, 19, 'Štai tuo metu sužlugdysiu visus tave kamuojančius; išgelbėsiu šlubuojantį ir surinksiu tai, kas buvo išsklaidyta; ir įgysiu jiems gyrių ir garbę kiekvienoje šalyje, kur jie buvo gėdinami.'),
  (@b36, 3, 20, 'Tuo metu jus parvesiu, būtent tuo metu, kai jus surinksiu; nes aš paskirsiu jums vardą ir gyrių tarp visų žemės tautų, kai sugrąžinsiu jūsų nelaisvę jums prieš akis“, – sako VIEŠPATS.'),
  (@b37, 1, 1, 'Antraisiais karaliaus Darijaus metais, šeštąjį mėnesį, pirmąją to mėnesio dieną, VIEŠPATIES žodis atėjo per pranašą Agėją Šealtielio sūnui Zerubabeliui, Judos valdytojui, ir Jocadako sūnui Jozuei, aukščiausiajam kunigui, sakydamas:'),
  (@b37, 1, 2, '„Taip sako kariuomenių VIEŠPATS, sakydamas: ‘Šita tauta sako: Dar neatėjo laikas, laikas, kai turi būti statomi VIEŠPATIES namai’“.'),
  (@b37, 1, 3, 'Tada VIEŠPATIES žodis atėjo per pranašą Agėją, sakydamas:'),
  (@b37, 1, 4, '„Argi metas jums gyventi lentomis apmuštuose jūsų namuose, kai šitie namai ištuštėję?'),
  (@b37, 1, 5, 'Todėl dabar taip sako kariuomenių VIEŠPATS: ‘Apsvarstykite savo kelius.'),
  (@b37, 1, 6, 'Jūs daug pasėjote, o mažai suvalėte; jūs valgote, bet jums neužtenka; jūs geriate, bet neatsigeriate gėrimu; jūs apsirengiate, bet nesušylate; o kas uždirba algą, uždirbą algą, kad ją įdėtų į skylėtą maišelį’.'),
  (@b37, 1, 7, 'Taip sako kariuomenių VIEŠPATS: ‘Apsvarstykite savo kelius.'),
  (@b37, 1, 8, 'Lipkite į kalną, parsigabenkite medžių ir statykite namus; man tai patiks ir aš būsiu pašlovintas’, – sako VIEŠPATS.'),
  (@b37, 1, 9, '‘Jūs tikėjotės daug, o štai išėjo mažai; ir kai pargabenote tai į namus, aš papūčiau į tai. Kodėl? – sako kariuomenių VIEŠPATS. – Dėl mano namų, kurie yra ištuštėję, o jūs kiekvienas bėgate į savo paties namus.'),
  (@b37, 1, 10, 'Todėl viršum jūsų dangus sulaikė rasą, o žemė sulaikė savo vaisių.'),
  (@b37, 1, 11, 'Aš pašaukiau sausrą šaliai ir kalnams, ir javams, ir jaunam vynui, ir aliejui, ir tam, ką išaugina dirva, ir žmonėms, ir galvijams, ir visam rankų triūsui’“.'),
  (@b37, 1, 12, 'Tada Šealtielio sūnus Zerubabelis ir Jocadako sūnus Jozuė, aukščiausiasis kunigas, su visu tautos likučiu pakluso VIEŠPATIES, savo Dievo, balsui ir pranašo Agėjo žodžiams, kai VIEŠPATS, jų Dievas, buvo jį siuntęs, ir tauta bijojo VIEŠPATIES akivaizdoje.'),
  (@b37, 1, 13, 'Tada Agėjas, VIEŠPATIES pasiuntinys, kalbėjo VIEŠPATIES žinią tautai, sakydamas: „Aš esu su jumis, – sako VIEŠPATS“.'),
  (@b37, 1, 14, 'Ir VIEŠPATS sužadino Šealtielio sūnaus Zerubabelio, Judos valdytojo, dvasią ir Jocadako sūnaus Jozuės, aukščiausiojo kunigo, dvasią, ir viso tautos likučio dvasią; ir jie atėję dirbo darbą kariuomenių VIEŠPATIES, savo Dievo, namuose,'),
  (@b37, 1, 15, 'dvidešimt ketvirtąją šeštojo mėnesio dieną, antraisiais karaliaus Darijaus metais.'),
  (@b37, 2, 1, 'Septintąjį mėnesį, dvidešimt pirmąją to mėnesio dieną, VIEŠPATIES žodis atėjo per pranašą Agėją, sakydamas:'),
  (@b37, 2, 2, '„Kalbėk dabar Šealtielio sūnui Zerubabeliui, Judos valdytojui, ir Jocadako sūnui Jozuei, aukščiausiajam kunigui, ir tautos likučiui, sakydamas:'),
  (@b37, 2, 3, '‘Kas dar yra išlikęs tarp jūsų, kuris matė šituos namus jų primykštėje šlovėje? Ir kokius jūs matote juos dabar? Argi jie palyginus nėra lyg niekas jūsų akyse?'),
  (@b37, 2, 4, 'Tačiau dabar būk stiprus, o Zerubabeli, – sako VIEŠPATS, – būk stiprus, o Jozue, Jocadako sūnau, aukščiausiasis kunige; būk stipri, visa šalies tauta, – sako VIEŠPATS, – ir dirbkite; nes aš esu su jumis, – sako kariuomenių VIEŠPATS;'),
  (@b37, 2, 5, 'pagal tą žodį, kuriuo su jumis sudariau sandorą, jums išėjus iš Egipto, taip mano Dvasia pasilieka tarp jūsų; nebijokite’.'),
  (@b37, 2, 6, 'Nes taip sako kariuomenių VIEŠPATS: ‘Trumpa valandėlė, ir aš dar kartą sudrebinsiu dangus ir žemę, jūrą ir sausumą;'),
  (@b37, 2, 7, 'aš supurtysiu visas tautas, ir ateis visų tautų noras; ir aš pripildysiu šituos namus šlove, – sako kariuomenių VIEŠPATS.'),
  (@b37, 2, 8, '– Mano yra sidabras ir mano yra auksas, – sako kariuomenių VIEŠPATS.'),
  (@b37, 2, 9, '– Šitų paskutinių namų šlovė bus didesnė už pirmųjų, – sako kariuomenių VIEŠPATS; – ir šitoje vietoje aš suteiksiu ramybę, – sako kariuomenių VIEŠPATS’“.'),
  (@b37, 2, 10, 'Devintojo mėnesio dvidešimt ketvirtąją dieną, antraisiais Darijaus metais, VIEŠPATIES žodis atėjo per pranašą Agėją, sakydamas:'),
  (@b37, 2, 11, '„Taip sako kariuomenių VIEŠPATS: Pasiklausk kunigų apie įstatymą, sakydamas:'),
  (@b37, 2, 12, '‘Jei kas neša šventą mėsą savo drabužio skverne ir savo skvernu paliečia duoną ar viralą, ar vyną, ar aliejų, ar kokį valgį, ar tai bus šventa?’“ Kunigai atsakė ir tarė: „Ne“.'),
  (@b37, 2, 13, 'Tada Agėjas tarė: „Jei kas, nešvarus nuo lavono, paliečia ką nors iš tų, ar tai bus nešvaru?“ Kunigai atsakė ir tarė: „Tai bus nešvaru“.'),
  (@b37, 2, 14, 'Tada Agėjas atsakė ir tarė: „Tokia yra šita tauta ir tokia yra šita tautybė mano akivaizdoje, – sako VIEŠPATS, – ir toks yra kiekvienas jų rankų darbas; ir tai, ką jie ten atnašauja, yra nešvaru.'),
  (@b37, 2, 15, 'O dabar, meldžiu jus, apsvarstykite nuo šios dienos ir toliau, kai dar nebuvo padėtas akmuo ant akmens VIEŠPATIES šventykloje;'),
  (@b37, 2, 16, 'nuo tų dienų, kai kas nors ateidavo prie dvidešimties saikų krūvos, tebūdavo dešimt; kai kas nors ateidavo prie spaustuvo kubilo pasisemti penkiasdešimt indų iš spaustuvo, tebūdavo dvidešimt.'),
  (@b37, 2, 17, 'Aš ištikau jus džiovinančiu pūtimu, pelėsiu ir kruša visuose jūsų rankų darbuose; tačiau jūs nesigręžėte į mane, – sako VIEŠPATS.'),
  (@b37, 2, 18, '– Apsvarstykite nuo šios dienos ir toliau, nuo dvidešimt ketvirtosios devintojo mėnesio dienos – nuo tos dienos, kai buvo padėtas VIEŠPATIES šventyklos pamatas, apsvarstykite tai.'),
  (@b37, 2, 19, 'Ar dar yra sėklos svirne? Taip, kai vynmedis, figmedis, granatmedis ir alyvmedis dar neatnešė vaisių; nuo šios dienos aš jus laiminsiu“.'),
  (@b37, 2, 20, 'Ir VIEŠPATIES žodis vėl atėjo Agėjui dvidešimt ketvirtąją to mėnesio dieną, sakydamas:'),
  (@b37, 2, 21, '„Kalbėk Zerubabeliui, Judos valdytojui, sakydamas: ‘Aš supurtysiu dangus ir žemę;'),
  (@b37, 2, 22, 'ir aš nuversiu karalysčių sostus, ir sunaikinsiu pagonių karalysčių stiprybę; aš apversiu vežimus ir tuos, kurie juose važiuoja; kris žirgai ir jų raiteliai, kiekvienas nuo savo brolio kalavijo.'),
  (@b37, 2, 23, 'Tą dieną, – sako kariuomenių VIEŠPATS, – aš paimsiu tave, o Zerubabeli, Šealtielio sūnau, mano tarne, – sako VIEŠPATS, – ir tave padarysiu tarsi žiedo antspaudu, nes aš tave išsirinkau, – sako kariuomenių VIEŠPATS’“.'),
  (@b38, 1, 1, 'Aštuntąjį mėnesį, antraisiais Darijaus metais, VIEŠPATIES žodis atėjo pranašo Idojo sūnaus Berechijos sūnui Zacharijui, sakydamas:'),
  (@b38, 1, 2, '„VIEŠPATS buvo labai supykęs ant jūsų tėvų.'),
  (@b38, 1, 3, 'Todėl sakyk jiems: ‘Taip sako kariuomenių VIEŠPATS: Atsigręžkite į mane, – sako kariuomenių VIEŠPATS, – ir aš atsigręšiu į jus, – sako kariuomenių VIEŠPATS.'),
  (@b38, 1, 4, '– Nebūkite kaip jūsų tėvai, kuriems ankstesnieji pranašai šaukė, sakydami: „Taip sako kariuomenių VIEŠPATS: Nusisukite nuo savo piktų kelių ir nuo savo piktų darbų“; bet jie negirdėjo ir neklausė manęs, – sako VIEŠPATS.'),
  (@b38, 1, 5, '– Jūsų tėvai – kur jie yra? Ir pranašai – ar jie amžinai gyvena?'),
  (@b38, 1, 6, 'Bet mano žodžiai ir mano įstatai, kuriuos įsakiau savo tarnams pranašams, argi jie nenutvėrė jūsų tėvų? Ir jie sugrįžo ir sakė: Kaip kariuomenių VIEŠPATS sumanė mums daryti pagal mūsų kelius ir pagal mūsų darbus, taip jis ir pasielgė su mumis’“.'),
  (@b38, 1, 7, 'Vienuoliktojo mėnesio, tai yra Sebato mėnesio, dvidešimt ketvirtąją dieną, antraisiais Darijaus metais,VIEŠPATIES žodis atėjo pranašo Idojo sūnaus Berechijos sūnui Zacharijui, sakydamas:'),
  (@b38, 1, 8, '„Naktį aš regėjau, ir štai vyras, jojantis ant raudono žirgo, ir jis stovėjo tarp mirtų, esančių apačioje; o už jo buvo raudoni, margi ir balti žirgai“.'),
  (@b38, 1, 9, 'Tada aš tariau: „Kas yra šitie, o mano viešpatie?“ Ir angelas, kalbantis su manimi, man tarė: „Aš tau parodysiu, kas yra šitie“.'),
  (@b38, 1, 10, 'Ir vyras, stovintis tarp mirtų, atsakė ir tarė: „Tai yra tie, kuriuos VIEŠPATS siuntė vaikščioti ten ir atgal po žemę“.'),
  (@b38, 1, 11, 'Ir jie atsakė VIEŠPATIES angelui, stovinčiam tarp mirtų, ir tarė: „Mes vaikščiojome ten ir atgal po žemę, ir štai visa žemė rami ir ilsisi“.'),
  (@b38, 1, 12, 'Tada VIEŠPATIES angelas atsakė ir tarė: „O kariuomenių VIEŠPATIE, kiek ilgai nepasigailėsi Jeruzalės ir Judos miestų, kuriais buvai pasipiktinęs per šituos septyniasdešimt metų?“'),
  (@b38, 1, 13, 'Ir VIEŠPATS atsakė angelui, kalbančiam su manimi, gerais žodžiais, paguodos žodžiais.'),
  (@b38, 1, 14, 'Taigi angelas, kalbantis su manimi, man tarė: „Šauk, sakydamas: ‘Taip sako kariuomenių VIEŠPATS: Aš pavydžiu dėl Jeruzalės ir dėl Siono didžiu pavydu.'),
  (@b38, 1, 15, 'Ir aš labai smarkiai supykęs ant pagonių, kurie gyvena be rūpesčių; nes buvau tik truputį supykęs, o jie padėjo paspartinti vargą.'),
  (@b38, 1, 16, 'Todėl taip sako VIEŠPATS: Aš sugrįžau į Jeruzalę su gailestingumais: mano namai bus pastatyti joje, – sako kariuomenių VIEŠPATS, – ir virvė bus ištiesta ant Jeruzalės’.'),
  (@b38, 1, 17, 'Dar šauk, sakydamas: ‘Taip sako kariuomenių VIEŠPATS: Mano miestai suklestėję dar pasklis; ir VIEŠPATS dar paguos Sioną ir dar išsirinks Jeruzalę’“.'),
  (@b38, 1, 18, 'Paskui aš pakėliau savas akis ir mačiau, ir štai keturi ragai.'),
  (@b38, 1, 19, 'Ir aš tariau angelui, kalbančiam su manimi: „Kas yra šitie?“ O jis man atsakė: „Šitie yra ragai, kurie išsklaidė Judą, Izraelį ir Jeruzalę“.'),
  (@b38, 1, 20, 'Ir VIEŠPATS man parodė keturis dailides.'),
  (@b38, 1, 21, 'Tada aš tariau: „Ką šitie ateina daryti?“ O jis kalbėjo, sakydamas: „Šitie yra ragai, kurie taip išsklaidė Judą, kad niekas nepakėlė savo galvos; bet šitie atėjo jų išgąsdinti, išmesti ragus pagonių, pakėlusių savo ragą virš Judos šalies, idant ją išsklaidytų“.'),
  (@b38, 2, 1, 'Aš vėl pakėliau savas akis ir pažiūrėjau, ir štai vyras su matavimo virve savo rankoje.'),
  (@b38, 2, 2, 'Tada tariau: „Kur eini?“ O jis man tarė: „Jeruzalės išmatuoti, pamatyti, koks jos plotis ir koks jos ilgis“.'),
  (@b38, 2, 3, 'Ir štai angelas, kalbėjęs su manimi, išėjo priekin, o kitas angelas išėjo jo pasitikti,'),
  (@b38, 2, 4, 'ir jam tarė: „Bėk, kalbėk tam jaunuoliui, sakydamas: ‘Jeruzalė bus gyvenama kaip miestai be sienų dėl daugybės žmonių ir galvijų joje;'),
  (@b38, 2, 5, 'nes aš jai būsiu, – sako VIEŠPATS, – ugnies siena aplinkui ir būsiu šlovė jos viduryje’“.'),
  (@b38, 2, 6, '„Ei, ei, išeikite ir bėkite iš šiaurės šalies, – sako VIEŠPATS; – nes aš jus išsklaidžiau kaip keturis dangaus vėjus, – sako VIEŠPATS.'),
  (@b38, 2, 7, '– Gelbėkis, o Sione, gyvenantis su Babilono dukterimi.'),
  (@b38, 2, 8, 'Nes taip sako kariuomenių VIEŠPATS: ‘Po šlovės jis siuntė mane pas tautas, kurios apiplėšė jus; nes tas, kas paliečia jus, paliečia jo akies obuolį.'),
  (@b38, 2, 9, 'Nes štai aš papurtysiu į juos savo ranka, ir jie bus grobiu savo tarnams; ir jūs žinosite, kad kariuomenių VIEŠPATS siuntė mane.'),
  (@b38, 2, 10, 'Giedok ir džiūgauk, o Siono dukra; nes štai aš ateinu ir gyvensiu tavo tarpe, – sako VIEŠPATS.'),
  (@b38, 2, 11, '– Ir daug tautų prisijungs prie VIEŠPATIES tą dieną ir bus mano tauta; ir aš gyvensiu tavo tarpe, ir tu žinosi, kad kariuomenių VIEŠPATS siuntė mane pas tave.'),
  (@b38, 2, 12, 'Ir VIEŠPATS paveldės Judą, savo dalį šventojoje šalyje, ir vėl išsirinks Jeruzalę.'),
  (@b38, 2, 13, 'Nutilkite, o visi kūnai, prieš VIEŠPATĮ; nes jis pakilo iš savo šventosios buveinės’“.'),
  (@b38, 3, 1, 'Ir jis man parodė aukščiausiąjį kunigą Jozuę, stovintį prieš VIEŠPATIES angelą, ir šėtoną, stovintį jo dešinėje, kad jam pasipriešintų.'),
  (@b38, 3, 2, 'Ir VIEŠPATS tarė šėtonui: „Tebara tave VIEŠPATS, o šėtone; būtent VIEŠPATS, kuris išsirinko Jeruzalę, tebara tave; argi šitas nėra nuodėgulis, ištrauktas iš ugnies?“'),
  (@b38, 3, 3, 'Na, o Jozuė buvo apsivilkęs purvinais drabužiais ir stovėjo priešais angelą.'),
  (@b38, 3, 4, 'Ir jis atsakė ir kalbėjo stovintiems prieš jį, sakydamas: „Nuvilkite nuo jo purvinus drabužius“. O jam pasakė: „Štai aš pašalinau nuo tavęs tavo neteisybę ir apvilksiu tave drabužių pakaita“.'),
  (@b38, 3, 5, 'Ir aš tariau: „Tegul jie uždeda jam ant galvos švarią mitrą“. Taigi jie uždėjo švarią mitrą jam ant galvos ir apvilko jį drabužiais. O VIEŠPATIES angelas stovėjo šalia.'),
  (@b38, 3, 6, 'Ir VIEŠPATIES angelas tvirtino Jozuei, sakydamas:'),
  (@b38, 3, 7, '„Taip sako kariuomenių VIEŠPATS: ‘Jei vaikščiosi mano keliais ir jei laikysiesi mano įpareigojimo, tai ir tu teisi mano namus ir taip pat saugosi mano kiemus, ir aš tau suteiksiu vietą vaikščioti tarp šitų, kurie stovi šalia.'),
  (@b38, 3, 8, 'Klausykis, Jozue, aukščiausiasis kunige, tu ir tavo draugai, sėdintys priešais tave; nes jie yra vyrai, kuriais stebimasi; nes štai aš išvesiu savo tarną – ATŽALĄ.'),
  (@b38, 3, 9, 'Nes štai akmuo, kurį padėjau priešais Jozuę; ant vieno akmens bus septynios akys; štai aš išraižysiu jo graviūrą, – sako kariuomenių VIEŠPATS, – ir pašalinsiu tos šalies neteisybę per vieną dieną.'),
  (@b38, 3, 10, 'Tą dieną, – sako kariuomenių VIEŠPATS, – jūs pasikviesite kiekvienas savo artimą po vynmedžiu ir po figmedžiu’“.'),
  (@b38, 4, 1, 'Ir angelas, kuris kalbėjo su manimi, vėl atėjo ir pažadino mane kaip žmogų, kuris žadinamas iš miego,'),
  (@b38, 4, 2, 'ir man tarė: „Ką matai?“ Aš tariau: „Aš pažiūrėjau, ir štai žvakidė, visa auksinė su dubeniu jos viršuje, ir jos septyni žibintai ant jos, ir septyni vamzdeliai septyniems žibintams, kurie yra jos viršuje;'),
  (@b38, 4, 3, 'ir du alyvmedžiai šalia jos: vienas dubens dešinėje pusėje, o kitas jo kairėje“.'),
  (@b38, 4, 4, 'Taigi aš atsiliepiau ir tariau angelui, kalbančiam su manimi, sakydamas: „Kas tie yra, mano viešpatie?“'),
  (@b38, 4, 5, 'Tada angelas, kalbantis su manimi, man atsakė ir tarė: „Argi nežinai, kas tie yra?“ Ir aš tariau: „Ne, mano viešpatie“.'),
  (@b38, 4, 6, 'Tada jis atsakė ir man kalbėjo, sakydamas: „Tai yra VIEŠPATIES žodis Zerubabeliui, sakantis: ‘Ne galybe ir ne jėga, bet mano Dvasia’, – sako kariuomenių VIEŠPATS“.'),
  (@b38, 4, 7, 'Kas tu esi, o didysis kalne? Prieš Zerubabelį tu tapsi lyguma; ir jis išneš jo pagrindinį akmenį su šauksmais, šaukdamas: „Malonė, malonė jam“.'),
  (@b38, 4, 8, 'Man dar atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b38, 4, 9, '„Zerubabelio rankos padėjo šitų namų pamatus; jo rankos juos ir užbaigs; ir tu žinosi, kad kariuomenių VIEŠPATS siuntė mane pas jus.'),
  (@b38, 4, 10, 'Nes kas paniekino mažų dalykų dieną? Nes jie džiaugsis ir matys svambalą Zerubabelio rankoje su tais septyniais; jie yra VIEŠPATIES akys, lakstančios ten ir atgal po visą žemę“.'),
  (@b38, 4, 11, 'Tada aš atsiliepiau ir jam tariau: „Kas yra šitie du alyvmedžiai žvakidės dešinėje ir jos kairėje?“'),
  (@b38, 4, 12, 'Aš vėl atsiliepiau ir jam tariau: „Kas yra tos dvi alyvmedžio šakos, kurios per du auksinius vamzdelius išpila iš savęs auksinį aliejų?“'),
  (@b38, 4, 13, 'Ir jis man atsakė ir tarė: „Ar nežinai, kas šitie yra?“ Ir aš tariau: „Ne, mano viešpatie“.'),
  (@b38, 4, 14, 'Tada jis tarė: „Šitie yra du pateptieji, kurie stovi šalia visos žemės Viešpaties“.'),
  (@b38, 5, 1, 'Paskui aš pasisukau, pakėliau savas akis ir pažiūrėjau, ir štai skrendantis ritinys.'),
  (@b38, 5, 2, 'Ir jis man tarė: „Ką matai?“ Aš atsakiau: „Matau skrendantį ritinį, kurio ilgis – dvidešimt uolekčių ir plotis – dešimt uolekčių“.'),
  (@b38, 5, 3, 'Tada jis man tarė: „Tai prakeikimas, išeinantis per visos žemės paviršių; nes kiekvienas vagiantis bus iškirstas pagal tai, kaip šioje jo pusėje; ir kiekvienas prisiekiantis bus iškirstas pagal tai, kaip anoje jo pusėje.'),
  (@b38, 5, 4, 'Aš jį išvesiu, – sako kariuomenių VIEŠPATS, – ir jis įeis į vagies namus ir į namus to, kuris melagingai prisiekia mano vardu; ir jis pasiliks jo namų viduryje ir juos sunaikins kartu su jų mediena ir jų akmenimis“.'),
  (@b38, 5, 5, 'Paskui angelas, kalbėjęs su manimi, išėjo priekin ir man tarė: „Pakelk dabar savo akis ir pažiūrėk, kas yra tai, kas išeina“.'),
  (@b38, 5, 6, 'Ir aš tariau: „Kas tai yra?“ O jis tarė: „Tai yra efa, kuri išeina“. Jis dar tarė: „Tai jų panašumas visoje žemėje“.'),
  (@b38, 5, 7, 'Ir štai pasikėlė švininis talentas; ir tai yra moteris, sėdinti efos viduryje.'),
  (@b38, 5, 8, 'Ir jis tarė: „Tai nedorybė“. Ir jis ją įmetė į efos vidurį; ir užmetė švininį svorį ant jos angos.'),
  (@b38, 5, 9, 'Tada pakėliau savo akis ir pažiūrėjau, ir štai išėjo dvi moterys, ir vėjas buvo jų sparnuose; nes jos turėjo sparnus kaip gandro sparnus; ir jos pakėlė efą tarp žemės ir dangaus.'),
  (@b38, 5, 10, 'Tada tariau angelui, kalbančiam su manimi: „Kur jos neša efą?“'),
  (@b38, 5, 11, 'Ir jis man tarė: „Jai statyti namus Šinaro šalyje; ir ji bus įtvirtinta ir ten padėta ant jos pagrindo“.'),
  (@b38, 6, 1, 'Ir aš pasisukau, pakėliau savo akis ir pažiūrėjau, ir štai išvažiavo keturi vežimai iš dviejų kalnų tarpo; o tie kalnai buvo žalvariniai kalnai.'),
  (@b38, 6, 2, 'Pirmajame vežime buvo raudoni žirgai; antrajame vežime – juodi žirgai;'),
  (@b38, 6, 3, 'trečiajame vežime – balti žirgai; o ketvirtajame vežime – pilkšvi ir bėri žirgai.'),
  (@b38, 6, 4, 'Tada atsiliepiau ir tariau angelui, kalbančiam su manimi: „Kas šitie yra, mano viešpatie?“'),
  (@b38, 6, 5, 'Ir angelas atsakė ir man tarė: „Šitie yra keturios dangų dvasios, kurios išvyksta nuo stovėjimo visos žemės Viešpaties akivaizdoje.'),
  (@b38, 6, 6, 'Juodieji žirgai, esantys jame, išvyksta į šiaurės šalį; baltieji išvyksta paskui juos; o pilkšvieji išvyksta į pietų kraštą“.'),
  (@b38, 6, 7, 'O bėrieji išvyko ir siekė eiti, kad vaikščiotų ten ir atgal po žemę; ir jis tarė: „Eikite iš čia, vaikštinėkite ten ir atgal po žemę“. Taigi jie vaikštinėjo ten ir atgal po žemę.'),
  (@b38, 6, 8, 'Paskui jis pašaukė mane ir kalbėjo man, sakydamas: „Žiūrėk, tie, kurie vyksta į šiaurės kraštą, nuramino mano dvasią šiaurės krašte“.'),
  (@b38, 6, 9, 'Ir man atėjo VIEŠPATIES žodis, sakydamas:'),
  (@b38, 6, 10, '„Paimk iš belaisvių – iš Heldajo, iš Tobijos ir iš Jedajo, kurie yra atvykę iš Babilono, ir ateik tą pačią dieną ir įeik į Sofonijo sūnaus Jozijo namus;'),
  (@b38, 6, 11, 'tada paimk sidabrą ir auksą, padaryk vainikus ir uždėk juos ant Jocadako sūnaus Jozuės, aukščiausiojo kunigo, galvos;'),
  (@b38, 6, 12, 'ir jam kalbėk, sakydamas: ‘Taip kalba kariuomenių VIEŠPATS, sakydamas: Štai vyras, kurio vardas ATŽALA; jis išaugs iš savo vietos ir pastatys VIEŠPATIES šventyklą;'),
  (@b38, 6, 13, 'jis pastatys VIEŠPATIES šventyklą; jis nešios šlovę, jis sėdės ir valdys savo soste; jis bus kunigas savo soste; ir taikos taryba bus tarp tų abiejų’.'),
  (@b38, 6, 14, 'Ir tie vainikai bus Helemui, Tobijai, Jedajai ir Sofonijo sūnui Henui kaip atminimas VIEŠPATIES šventykloje.'),
  (@b38, 6, 15, 'Ir toli esantieji ateis ir statys VIEŠPATIES šventykloje, ir jūs žinosite, kad kariuomenių VIEŠPATS mane siuntė pas jus. Ir tai įvyks, jei uoliai paklusite VIEŠPATIES, jūsų Dievo, balsui“.'),
  (@b38, 7, 1, 'Ketvirtaisiais karaliaus Darijaus metais įvyko, kad VIEŠPATIES žodis atėjo Zacharijui devintojo mėnesio ketvirtąją dieną, būtent Kislevo mėnesį;'),
  (@b38, 7, 2, 'kai jie siuntė į Dievo namus Šarecerą ir Regem-Melechą, ir jų žmones, kad melstųsi VIEŠPATIES akivaizdoje'),
  (@b38, 7, 3, 'ir kalbėtų kunigams, esantiems kariuomenių VIEŠPATIES namuose, bei pranašams, sakydami: „Ar man atsiskyrus verkti penktąjį mėnesį, kaip dariau šituos daugelį metų?“'),
  (@b38, 7, 4, 'Tada man atėjo kariuomenių VIEŠPATIES žodis, sakydamas:'),
  (@b38, 7, 5, '„Kalbėk visai šalies tautai ir kunigams, sakydamas: ‘Kai pasninkavote ir gedėjote penktąjį ir septintąjį mėnesį per šituos septyniasdešimt metų, ar tikrai man, būtent man, pasninkavote?'),
  (@b38, 7, 6, 'O kai valgėte ir kai gėrėte, argi ne sau valgėte ir ne sau gėrėte?’'),
  (@b38, 7, 7, 'Argi neturėjote išgirsti žodžių, kuriuos VIEŠPATS šaukė per ankstesniuosius pranašus, kai Jeruzalė tebebuvo gyvenama ir klestėjo, ir jos aplinkiniai miestai, kai žmonės buvo apgyvenę pietus ir lygumą?“'),
  (@b38, 7, 8, 'Ir VIEŠPATIES žodis atėjo Zacharijui, sakydamas:'),
  (@b38, 7, 9, '„Taip kalba kariuomenių VIEŠPATS, sakydamas: ‘Vykdykite teisingą teismą ir rodykite gailestingumą ir užuojautas kiekvienas savo broliui;'),
  (@b38, 7, 10, 'neenkite našlės ir našlaičio, ateivio ir vargšo; ir nei vienas nesumanykite pikto savo širdyse prieš savo brolį’.'),
  (@b38, 7, 11, 'Bet jie atsisakė klausyti ir atitraukė petį, ir užkimšo savo ausis, kad negirdėtų.'),
  (@b38, 7, 12, 'Taip, jie padarė savo širdis kaip deimantinį akmenį, kad negirdėtų įstatymo ir žodžių, kuriuos kariuomenių VIEŠPATS buvo atsiuntęs savo Dvasia per ankstesniuosius pranašus; todėl didelė rūstybė atėjo iš kariuomenių VIEŠPATIES.'),
  (@b38, 7, 13, 'Todėl įvyko, kad, kaip jie nesiklausė, kai jis šaukė, taip ir aš nesiklausiau, kai jie šaukė, – sako kariuomenių VIEŠPATS; –'),
  (@b38, 7, 14, 'bet aš išsklaidžiau juos viesulu po visas tautas, kurių jie nepažinojo. Taip šalis buvo tuščia po jų, kad niekas per ją nėjo ir negrįžo; nes jie pavertė tą geistiną šalį dykyne“.'),
  (@b38, 8, 1, 'Man vėl atėjo kariuomenių VIEŠPATIES žodis, sakydamas:'),
  (@b38, 8, 2, '„Taip sako kariuomenių VIEŠPATS: ‘Aš pavydėjau dėl Siono dideliu pavydu ir pavydėjau dėl jo dideliu įtūžiu’.'),
  (@b38, 8, 3, 'Taip sako VIEŠPATS: ‘Aš sugrįžau į Sioną ir gyvensiu Jeruzalės viduje; ir Jeruzalė bus vadinama tiesos miestu, o kariuomenių VIEŠPATIES kalnas – šventuoju kalnu’.'),
  (@b38, 8, 4, 'Taip sako kariuomenių VIEŠPATS: ‘Seniai ir senės dar gyvens Jeruzalės gatvėse, kiekvienas su savo lazda rankoje dėl seno amžiaus.'),
  (@b38, 8, 5, 'Ir miesto gatvės bus pilnos berniukų ir mergaičių, žaidžiančių jo gatvėse’.'),
  (@b38, 8, 6, 'Taip sako kariuomenių VIEŠPATS: ‘Jei šiomis dienomis tai būtų nuostaba šitos tautos likučio akyse, ar tai turėtų būti nuostaba ir mano akyse? – sako kariuomenių VIEŠPATS’.'),
  (@b38, 8, 7, 'Taip sako kariuomenių VIEŠPATS: ‘Štai aš išgelbėsiu savo tautą iš rytų krašto ir iš vakarų krašto;'),
  (@b38, 8, 8, 'ir juos parvesiu, ir jie gyvens Jeruzalės viduje; ir jie bus mano tauta, o aš būsiu jų Dievas tiesoje ir teisume’.'),
  (@b38, 8, 9, 'Taip sako kariuomenių VIEŠPATS: ‘Tebūna stiprios rankos jūsų, kurie šitomis dienomis girdite šituos žodžius iš burnos pranašų, kurie buvo tą dieną, kai buvo dedami kariuomenių VIEŠPATIES namų pamatai, kad šventykla būtų pastatyta.'),
  (@b38, 8, 10, 'Nes anksčiau šių dienų nebuvo atlyginimo nei žmogui, nei atlyginimo gyvuliui; ir nebuvo jokios ramybės išeinančiam ar įeinančiam dėl sielvarto; nes aš nukreipiau kiekvieną prieš savo artimą.'),
  (@b38, 8, 11, 'Bet dabar nebebūsiu šitos tautos likučiui, kaip ankstesnėmis dienomis’, – sako kariuomenių VIEŠPATS.'),
  (@b38, 8, 12, '‘Nes sėkla klestės; vynmedis duos savo vaisius, dirva duos savo prieaugį ir dangūs duos savo rasą; ir šitos tautos likučiui visa tai duosiu nuosavybėn.'),
  (@b38, 8, 13, 'Ir įvyks, kaip jūs, Judos namai ir Izraelio namai, buvote prakeikimu tarp pagonių, taip aš jus išgelbėsiu, ir jūs būsite palaiminimas; nebijokite, tebūna stiprios jūsų rankos’.'),
  (@b38, 8, 14, 'Nes taip sako kariuomenių VIEŠPATS: ‘Kaip aš galvojau jus nubausti, kai jūsų tėvai kurstė mano rūstybę, ir aš nepersigalvojau, – sako kariuomenių VIEŠPATS, –'),
  (@b38, 8, 15, 'taip vėl šiomis dienomis sumaniau daryti gera Jeruzalei ir Judos namams; nebijokite.'),
  (@b38, 8, 16, 'Šitie yra dalykai, kuriuos turėsite daryti: kiekvienas kalbėkite tiesą savo artimui; vykdykite tiesos ir taikos teismą savo vartuose;'),
  (@b38, 8, 17, 'nei vienas iš jūsų nesumanykite savo širdyse pikto prieš savo artimą; ir nemylėkite melagingos priesaikos; nes visi tie yra dalykai, kurių nekenčiu’, – sako VIEŠPATS“.'),
  (@b38, 8, 18, 'Ir man atėjo kariuomenių VIEŠPATIES žodis, sakydamas:'),
  (@b38, 8, 19, '„Taip sako kariuomenių VIEŠPATS: ‘Ketvirtojo mėnesio pasninkas ir penktojo pasninkas, septintojo pasninkas ir dešimtojo pasninkas Judos namams bus džiaugsmu, linksmybe ir džiaugsmingomis šventėmis; todėl mylėkite tiesą ir taiką’.'),
  (@b38, 8, 20, 'Taip sako kariuomenių VIEŠPATS: ‘Dar įvyks, kad ateis tautos ir daugelio miestų gyventojai;'),
  (@b38, 8, 21, 'ir vieno miesto gyventojai eis į kitą, sakydami: „Skubiai eikime melstis VIEŠPATIES akivaizdoje ir ieškoti kariuomenių VIEŠPATIES; eisiu ir aš“.'),
  (@b38, 8, 22, 'Taip, daug tautų ir stiprių tautybių ateis ieškoti kariuomenių VIEŠPATIES Jeruzalėje ir melstis VIEŠPATIES akivaizdoje’.'),
  (@b38, 8, 23, 'Taip sako kariuomenių VIEŠPATS: ‘Tomis dienomis atsitiks, kad dešimt žmonių iš visokiausių tautų kalbų nusitvers, būtent nusitvers už skverno tam, kuris yra žydas, sakydami: Mes eisime su jumis, nes girdėjome, kad Dievas yra su jumis’“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b38, 9, 1, 'VIEŠPATIES žodžio našta Hadracho krašte, o Damaskas bus jo poilsis; kai žmonių akys, kaip visų Izraelio genčių, bus nukreiptos į VIEŠPATĮ.'),
  (@b38, 9, 2, 'Taip pat Hamatas ribosis su juo; Tyras ir Sidonas, nors jie ir labai išmintingi.'),
  (@b38, 9, 3, 'Tyras pasistatė tvirtovę ir prisikrovė sidabro kaip dulkių ir gryno aukso kaip gatvių purvo.'),
  (@b38, 9, 4, 'Štai Viešpats jį išvarys ir sumuš jo galią jūroje; ir jis bus ugnies prarytas.'),
  (@b38, 9, 5, 'Aškelonas tai matys ir nusigąs; taip pat Gaza tai matys, ir labai sielvartaus, ir Ekronas; nes jo lūkestis bus sugėdintas; pražus karalius iš Gazos, ir Aškelonas nebus gyvenamas.'),
  (@b38, 9, 6, 'Ir pavainikis gyvens Ašdode, ir aš iškirsiu filistinų išdidumą.'),
  (@b38, 9, 7, 'Aš atimsiu jo kraują iš jo burnos ir jo bjaurystes iš jo dantų tarpo; bet tas, kuris pasilieka, būtent tas bus mūsų Dievui, ir jis bus kaip valdytojas Judoje, o Ekronas – kaip jebusietis.'),
  (@b38, 9, 8, 'Ir aš stovyklausiu aplink savo namus dėl kariuomenės, dėl praeinančio ir dėl sugrįžtančio; ir joks engėjas nebepereis per juos; nes dabar mačiau savo akimis.'),
  (@b38, 9, 9, 'Didžiai džiūgauk, o Siono dukra; šauk, o Jeruzalės dukra; štai tavo Karalius ateina pas tave; jis teisus ir turintis išgelbėjimą; nusižeminęs ir jojantis ant asilo, ant asiliuko, asilo jauniklio.'),
  (@b38, 9, 10, 'Aš iškirsiu vežimą iš Efraimo ir žirgą iš Jeruzalės, ir kovos lankas bus iškirstas; jis kalbės taiką pagonims; ir jo viešpatavimas bus nuo jūros iki jūros ir nuo upės iki žemės pakraščių.'),
  (@b38, 9, 11, 'Na, o dėl tavęs, tavo sandoros krauju išsiunčiau tavo belaisvius iš duobės, kurioje nėra vandens.'),
  (@b38, 9, 12, 'Gręžkitės į tvirtovę, vilties belaisviai; šiandien aš skelbiu, kad tau dvigubai atlyginsiu;'),
  (@b38, 9, 13, 'kai įtempiau sau Judą, pripildžiau lanką Efraimu ir pakėliau tavo sūnus, o Sione, prieš tavo sūnus, o Graikija, ir padariau tave galiūno kalaviju.'),
  (@b38, 9, 14, 'Ir VIEŠPATS bus regimas viršum jų, ir išlėks jo strėlė kaip žaibas; ir Viešpats DIEVAS pūs trimitą ir eis su pietų viesulais.'),
  (@b38, 9, 15, 'Kariuomenių VIEŠPATS juos gins; jie rys ir pavergs svaidyklės akmenimis; jie gers ir triukšmaus kaip nuo vyno; jie bus pripildyti kaip taurės, kaip aukuro kampai.'),
  (@b38, 9, 16, 'Ir tą dieną VIEŠPATS, jų Dievas, juos išgelbės kaip savo tautos kaimenę; nes jie bus kaip karūnos brangakmeniai, iškelti kaip vėliava jo šalyje.'),
  (@b38, 9, 17, 'Nes koks didis yra jo gerumas ir koks didis yra jo grožis! Javai pradžiugins jaunuolius, o jaunas vynas – merginas.'),
  (@b38, 10, 1, 'Prašykite VIEŠPATĮ lietaus, vėlyvojo lietaus metu; taigi VIEŠPATS padarys šviesius debesis ir duos jiems lietaus liūčių, kiekvienam žolės ant lauko.'),
  (@b38, 10, 2, 'Nes stabai kalbėjo tuštybę, o būrėjai regėjo melą ir pasakojo melagingus sapnus; jie veltui guodžia; todėl jie ėjo savo keliu kaip kaimenė, jie buvo neramūs, nes nebuvo ganytojo.'),
  (@b38, 10, 3, '„Prieš ganytojus užsidegė mano pyktis, aš nubaudžiau ožius; nes kariuomenių VIEŠPATS aplankė savo kaimenę, Judos namus, ir padarė juos tarsi savo gražų žirgą kovoje.'),
  (@b38, 10, 4, 'Iš jo išėjo kertis, iš jo – vinis, iš jo kovos lankas, iš jo visi engėjai kartu.'),
  (@b38, 10, 5, 'Ir jie bus kaip galiūnai, trypiantys gatvių purve savo priešus kovoje; jie kariaus, nes VIEŠPATS yra su jais, ir raiteliai ant žirgų bus sugėdinti.'),
  (@b38, 10, 6, 'Aš sustiprinsiu Judos namus ir išgelbėsiu Juozapo namus, ir juos parvesiu, kad juos apgyvendinčiau; nes aš jų pasigailėsiu; ir jie bus, tarsi nebuvau jų atmetęs; nes aš esu VIEŠPATS, jų Dievas, ir juos išklausysiu.'),
  (@b38, 10, 7, 'Tie iš Efraimo bus kaip galiūnai, ir jų širdys džiaugsis kaip nuo vyno; taip, jų vaikai tai matys ir džiaugsis; jų širdys džiūgaus VIEŠPAČIU.'),
  (@b38, 10, 8, 'Aš jiems sušvilpsiu ir juos surinksiu; nes juos atpirkau; ir jų padaugės, kaip kad buvo padaugėję.'),
  (@b38, 10, 9, 'Ir juos pasėsiu tarp tautų; ir tolimuose kraštuose jie atsimins mane; jie gyvens su savo vaikais ir sugrįš.'),
  (@b38, 10, 10, 'Aš juos parvesiu iš Egipto šalies, ir iš Asirijos juos surinksiu; ir juos atvesiu į Gileado šalį ir Libaną; ir jiems neatsiras vietos.'),
  (@b38, 10, 11, 'Ir jis pereis jūrą bėda ir ištiks jūroje bangas, ir išdžius vìsos upės gelmės; Asirijos išdidumas bus pažemintas, o Egipto skeptras pasišalins.'),
  (@b38, 10, 12, 'Aš sustiprinsiu juos VIEŠPATYJE; ir jie vaikštinės jo vardu“, – sako VIEŠPATS.'),
  (@b38, 11, 1, 'Atidaryk savo duris, o Libane, kad ugnis surytų tavo kedrus.'),
  (@b38, 11, 2, 'Kaukite, eglės; nes kedrai kritę; nes galingieji apiplėšti; kaukite, o Bašano ąžuolai, nes nugriuvo vynuogių derliaus miškas.'),
  (@b38, 11, 3, 'Štai kaukiantis ganytojų balsas; nes apiplėšta jų šlovė; jaunų liūtų riaumojimo balsas; nes apiplėštas Jordano išdidumas.'),
  (@b38, 11, 4, 'Taip sako VIEŠPATS, mano Dievas: „Ganyk pjovimo kaimenę,'),
  (@b38, 11, 5, 'kurios savininkai ją pjauna ir nelaiko savęs kaltais; ir tie, kurie ją parduoda, sako: ‘Palaimintas tebūna VIEŠPATS, nes aš esu turtingas’; ir jos pačios ganytojai nesigaili jos.'),
  (@b38, 11, 6, 'Nes aš nebesigailėsiu šalies gyventojų, – sako VIEŠPATS; – bet štai atiduosiu žmones, kiekvieną į jo artimo rankas ir į jo karaliaus rankas; ir jie triuškins šalį, bet aš jų nevaduosiu iš jų rankų.'),
  (@b38, 11, 7, 'Aš ganysiu pjovimo kaimenę, – jus, o kaimenės vargšai. Ir aš pasiėmiau dvi lazdas; vieną pavadinau Grožiu, o kitą pavadinau Raiščiais; ir ganiau kaimenę.'),
  (@b38, 11, 8, 'Taipogi iškirtau tris ganytojus per vieną mėnesį; mano siela bjaurėjosi jais, o jų siela taip pat bjaurėjosi manimi.'),
  (@b38, 11, 9, 'Tada tariau: ‘Aš jūsų neganysiu: kuri miršta, temiršta; kuri turi būti iškirsta, tebūna iškirsta; o likusios teėda viena kitos kūną’.'),
  (@b38, 11, 10, 'Ir aš paėmiau savo lazdą, būtent Grožį, ir perlaužiau ją, kad sulaužyčiau savo sandorą, kurią buvau sudaręs su visomis tautomis.'),
  (@b38, 11, 11, 'Ir tą dieną ji buvo sulaužyta; ir taip kaimenės vargšai, kurie manęs laukė, suprato, kad tai buvo VIEŠPATIES žodis.'),
  (@b38, 11, 12, 'Ir jiems tariau: ‘Jei jums atrodo gerai, sumokėkite man mano kainą; o jei ne, susilaikykite’. Taigi jie atsvėrė mano vertę – trisdešimt sidabrinių.'),
  (@b38, 11, 13, 'Ir VIEŠPATS man tarė: ‘Mesk juos puodžiui; tą gerą kainą, kuria buvau jų įkainotas’. Ir aš paėmiau trisdešimt sidabrinių ir mečiau juos puodžiui VIEŠPATIES namuose.'),
  (@b38, 11, 14, 'Paskui perlaužiau kitą savo lazdą, būtent Raiščius, kad nutraukčiau brolystę tarp Judos ir Izraelio.'),
  (@b38, 11, 15, 'Ir VIEŠPATS man tarė: Dar pasiimk kvailojo ganytojo įrankius.'),
  (@b38, 11, 16, 'Nes štai iškeliu šalyje ganytoją, kuris neaplankys iškirstųjų, neieškos jauniklių, negydys sulaužytų ir neganys tų, kurios dar stovi; bet jis ės riebiųjų mėsą ir nuplėš jų nagus.'),
  (@b38, 11, 17, 'Vargas stabui ganytojui, kuris palieka kaimenę! Kalavijas bus ant jo rankos ir ant jo dešinės akies; jo ranka džiūte nudžius, ir jo dešinė akis visiškai aptems“.'),
  (@b38, 12, 1, 'VIEŠPATIES žodžio našta Izraeliui, sako VIEŠPATS, kuris ištiesia dangus, deda žemės pamatą ir formuoja žmogaus dvasią jo viduje.'),
  (@b38, 12, 2, '„Štai aš padarysiu Jeruzalę drebėjimo taure visoms aplinkinėms tautoms, kai jos bus apgulusios Judą ir Jeruzalę.'),
  (@b38, 12, 3, 'Ir tą dieną Jeruzalę padarysiu sunkiu akmeniu visoms tautoms: visos, kurios juo apsikraus, bus sutrupintos, nors prieš ją susirinks visos žemės tautos.'),
  (@b38, 12, 4, 'Tą dieną, – sako VIEŠPATS, – aš ištiksiu visus žirgus nuostaba ir jų raitelius pamišimu; o į Judos namus atversiu savo akis, bet visus tautų žirgus ištiksiu aklumu.'),
  (@b38, 12, 5, 'Ir Judos valdytojai sakys savo širdyse: ‘Jeruzalės gyventojai bus mano stiprybė kariuomenių VIEŠPATYJE, jų Dieve’.'),
  (@b38, 12, 6, 'Tą dieną Judos valdytojus padarysiu lyg ugnies židiniu malkose ir lyg ugnies deglu pėduose; ir jie surys visas aplinkines tautas dešinėje ir kairėje; ir Jeruzalė vėl bus apgyvendinta savo vietoje – Jeruzalėje“.'),
  (@b38, 12, 7, 'VIEŠPATS pirmiausia išgelbės Judos palapines, kad Dovydo namų šlovė ir Jeruzalės gyventojų šlovė nesiaukštintų prieš Judą.'),
  (@b38, 12, 8, 'Tą dieną VIEŠPATS apgins Jeruzalės gyventojus; ir silpniausias tarp jų tą dieną bus kaip Dovydas; o Dovydo namai bus kaip Dievas, kaip VIEŠPATIES angelas jų priešakyje.'),
  (@b38, 12, 9, 'Ir tą dieną įvyks, kad aš sieksiu sunaikinti visas tautas, ateinančias prieš Jeruzalę.'),
  (@b38, 12, 10, 'Ir ant Dovydo namų bei ant Jeruzalės gyventojų išliesiu malonės ir maldavimų dvasią; ir jie žvelgs į mane, kurį jie perdūrė; ir apraudos jį, kaip aprauda vienintelį sūnų, ir bus kartybėje dėl jo, kaip būna kartybėje dėl savo pirmagimio.'),
  (@b38, 12, 11, 'Tą dieną bus toks didis gedulas Jeruzalėje, kaip Hadadrimono gedulas Megidono lygumoje.'),
  (@b38, 12, 12, 'Ir šalis raudos, kiekviena šeima atskirai: Dovydo namų šeima atskirai ir jų žmonos atskirai; Natano namų šeima atskirai ir jų žmonos atskirai;'),
  (@b38, 12, 13, 'Levio namų šeima atskirai ir jų žmonos atskirai; Šimio šeima atskirai ir jų žmonos atskirai;'),
  (@b38, 12, 14, 'visos likusios šeimos, kiekviena šeima atskirai ir jų žmonos atskirai.'),
  (@b38, 13, 1, 'Tą dieną bus šaltinis atsivėręs Dovydo namams ir Jeruzalės gyventojams dėl nuodėmės ir dėl nešvarumo.'),
  (@b38, 13, 2, '„Ir tą dieną įvyks, – sako kariuomenių VIEŠPATS, – kad aš iškirsiu iš šalies stabų vardus, ir jų nebeprisimins; taip pat pranašus ir netyrą dvasią pašalinsiu iš šalies.'),
  (@b38, 13, 3, 'Ir atsitiks, kai kas nors dar pranašaus, tai jo tėvas ir jo motina, kurie jį pagimdė, jam tars: ‘Tu neturi gyventi, nes kalbi melus VIEŠPATIES vardu’; ir jo tėvas bei jo motina, kurie jį pagimdė, jį perdurs jam pranašaujant.'),
  (@b38, 13, 4, 'Ir tą dieną įvyks, kad pranašai gėdysis kiekvienas savo regėjimo, kai pranašavo; ir jie nebevilkės šiurkštaus drabužio, kad apgautų;'),
  (@b38, 13, 5, 'bet kiekvienas sakys: ‘Aš ne pranašas, aš žemdirbys; nes mane nuo pat jaunystės mokė laikyti galvijus’.'),
  (@b38, 13, 6, 'Ir jam sakys: ‘Kas tai per žaizdos tavo rankose?’ Tada jis atsakys: ‘Tos, kuriomis buvau sužeistas savo draugų namuose’.'),
  (@b38, 13, 7, 'Kalavijau, pabusk prieš mano ganytoją, prieš mano bendrą, – sako kariuomenių VIEŠPATS; – kirsk ganytojui, ir avys išsisklaidys; ir aš nukreipsiu savo ranką prieš mažuosius.'),
  (@b38, 13, 8, 'Ir atsitiks, kad visoje šalyje, – sako VIEŠPATS, – joje dvi dalys bus iškirstos ir žus; bet trečdalis joje išliks.'),
  (@b38, 13, 9, 'Ir tą trečdalį aš vesiu per ugnį ir juos valysiu kaip valo sidabrą, ir juos mėginsiu kaip mėgina auksą; jie šauksis mano vardo, ir aš juos išklausysiu; aš sakysiu: ‘Tai mano tauta’; o jie sakys: ‘VIEŠPATS yra mano Dievas’“.'),
  (@b38, 14, 1, 'Štai ateina VIEŠPATIES diena, ir tavo grobis bus padalintas tavo tarpe.'),
  (@b38, 14, 2, 'Nes aš surinksiu visas tautas į mūšį prieš Jeruzalę; miestas bus paimtas, namai apiplėšti, moterys išprievartautos; ir pusė miesto išeis į nelaisvę, o tautos likutis nebus iškirstas iš miesto.'),
  (@b38, 14, 3, 'Tada VIEŠPATS išeis ir kariaus prieš tas tautas, kaip jis kariavo mūšio dieną.'),
  (@b38, 14, 4, 'Ir tą dieną jo kojos atsistos ant Alyvų kalno, esančio rytuose prieš Jeruzalę, ir Alyvų kalnas perskils per vidurį į rytus ir į vakarus, ir bus labai didelis slėnis; pusė kalno pasitrauks į šiaurę, o pusė – į pietus.'),
  (@b38, 14, 5, 'Ir jūs bėgsite į kalnų slėnį; nes kalnų slėnis sieks iki Azalo; taip, jūs bėgsite, kaip bėgote nuo žemės drebėjimo Judos karaliaus Uzijo dienomis; ir ateis VIEŠPATS, mano Dievas, ir visi šventieji su tavimi.'),
  (@b38, 14, 6, 'Ir tą dieną įvyks, kad šviesa nebus nei šviesi, nei tamsi;'),
  (@b38, 14, 7, 'bet tai bus viena diena, žinoma VIEŠPAČIUI, nei diena, nei naktis; bet įvyks, kad vakaro metu bus šviesu.'),
  (@b38, 14, 8, 'Ir tą dieną bus, kad gyvieji vandenys tekės iš Jeruzalės: pusė jų į priekinę jūrą, o pusė jų į užnugarinę jūrą; tai bus vasarą ir žiemą.'),
  (@b38, 14, 9, 'Ir VIEŠPATS bus visos žemės karalius; tą dieną bus vienas VIEŠPATS ir jo vardas vienas.'),
  (@b38, 14, 10, 'Visa ta šalis pasikeis, bus kaip lyguma nuo Gebos iki Rimono, į pietus nuo Jeruzalės; ji bus pakelta ir apgyvendinta savo vietoje, nuo Benjamino vartų iki Pirmųjų vartų vietos, iki Kertinių vartų, ir nuo Hananelio bokšto iki karaliaus vyno spaustuvų.'),
  (@b38, 14, 11, 'Ir žmonės gyvens joje, ir nebebus visiško sunaikinimo; bet Jeruzalė bus saugiai apgyventa.'),
  (@b38, 14, 12, 'O tokia bus rykštė, kuria VIEŠPATS suduos visoms tautoms, kariavusioms prieš Jeruzalę: jų kūnai ištirps, jiems tebestovint ant kojų, jų akys ištirps savo akiduobėse, ir jų liežuviai ištirps jų burnose.'),
  (@b38, 14, 13, 'Ir tą dieną įvyks, kad jų tarpe bus didelis sąmyšis nuo VIEŠPATIES; ir jie kiekvienas nutvers savo artimo ranką, ir jų ranka pakils prieš savo artimo ranką.'),
  (@b38, 14, 14, 'Juda irgi kariaus Jeruzalėje; ir bus surinkti visų aplinkinių pagonių turtai: didelė gausybė aukso, sidabro ir drabužių.'),
  (@b38, 14, 15, 'Ir tokia pat rykštė, kaip šita rykštė, bus žirgams, mulams, kupranugariams, asilams ir visiems gyvuliams, esantiems tose palapinėse.'),
  (@b38, 14, 16, 'Ir įvyks, kad visi, kurie išliks iš visų tautų, atėjusių prieš Jeruzalę, iš metų į metus eis aukštyn garbinti Karaliaus, kariuomenių VIEŠPATIES, ir švęsti Padangčių šventės.'),
  (@b38, 14, 17, 'Ir bus, jei kas iš visų žemės šeimų neateis aukštyn į Jeruzalę garbinti Karaliaus, kariuomenių VIEŠPATIES, jiems nebus lietaus.'),
  (@b38, 14, 18, 'Ir jei Egipto šeima, kuri neturi lietaus, neis aukštyn ir neateis, tuomet bus ta rykštė, kuria VIEŠPATS ištiks pagonis, neateinančius aukštyn švęsti Padangčių šventės.'),
  (@b38, 14, 19, 'Tokia bus Egipto bausmė ir bausmė visų tautų, kurios neateina aukštyn švęsti Padangčių šventės.'),
  (@b38, 14, 20, 'Tą dieną ant žirgų varpelių bus parašyta „ŠVENTUMAS VIEŠPAČIUI“; ir puodai VIEŠPATIES namuose bus kaip taurės prieš aukurą.'),
  (@b38, 14, 21, 'Taip, kiekvienas puodas Jeruzalėje ir Judoje bus šventumas kariuomenių VIEŠPAČIUI; ir visi aukojantys ateis, paims iš jų ir juose virs; ir tą dieną nebebus kanaaniečio kariuomenių VIEŠPATIES namuose.'),
  (@b39, 1, 1, 'VIEŠPATIES žodžio našta Izraeliui per Malachiją.'),
  (@b39, 1, 2, '„Aš jus pamilau, – sako VIEŠPATS. – Tačiau jūs sakote: ‘Kuo tu mus pamilai?’ Argi Ezavas nebuvo Jokūbo brolis? – sako VIEŠPATS; – tačiau aš mylėjau Jokūbą,'),
  (@b39, 1, 3, 'o Ezavo nekenčiau, ir jo kalnus bei jo paveldą paverčiau dykyne dykumos slibinams“.'),
  (@b39, 1, 4, 'Kadangi Edomas sako: „Mes esame nuskurdinti, bet mes grįšime ir atstatysime dykvietes“; taip sako kariuomenių VIEŠPATS: „Jie statys, bet aš griausiu; ir juos vadins ‘nedorybės ribomis’ ir ‘tauta, prieš kuriuos VIEŠPATS pasipiktinęs per amžius’.'),
  (@b39, 1, 5, 'Jūsų akys matys ir jūs sakysite: ‘VIEŠPATS bus išaukštintas nuo Izraelio ribų’.'),
  (@b39, 1, 6, 'Sūnus gerbia savo tėvą ir tarnas savo valdovą; tad jei aš esu tėvas, kur mano garbė? Ir jei aš esu valdovas, kur mano baimė? – sako kariuomenių VIEŠPATS jums, kunigai, kurie niekinate mano vardą. Ir jūs sakote: ‘Kuo mes paniekinome tavo vardą?’'),
  (@b39, 1, 7, 'Jūs atnašaujate ant mano aukuro suterštą duoną; ir sakote: ‘Kuo mes suteršėme tave?’ Tuo, kad sakote: ‘VIEŠPATIES stalas niekingas’.'),
  (@b39, 1, 8, 'Ir jei atnašaujate aklą kaip auką, ar tai nėra blogai? Ir jei atnašaujate raišą ir ligotą, ar tai nėra blogai? Atnašauk tai savo valdytojui; ar jis bus patenkintas tavimi, ar tave priims? – sako kariuomenių VIEŠPATS.'),
  (@b39, 1, 9, '– O dabar, meldžiu jus, maldaukite Dievą, kad jis būtų mums maloningas; tai buvo pagal jūsų būdą; ar jis atsižvelgs į jūsų asmenybę?– sako kariuomenių VIEŠPATS.'),
  (@b39, 1, 10, '– Kas yra tarp jūsų, kuris uždarytų duris veltui? Nei veltui nekurkite ugnies ant mano aukuro. Aš nemėgstu jūsų, – sako kariuomenių VIEŠPATS, – ir nepriimsiu atnašos iš jūsų rankų.'),
  (@b39, 1, 11, 'Nes nuo saulės patekėjimo iki jos nusileidimo didis bus mano vardas tarp pagonių; ir kiekvienoje vietoje mano vardui bus atnašaujami smilkalai ir tyra atnaša; nes didis bus mano vardas tarp pagonių, – sako kariuomenių VIEŠPATS.'),
  (@b39, 1, 12, '– Bet jūs suteršėte jį tuo, kad sakote: ‘VIEŠPATIES stalas yra suterštas; ir jo vaisius, tai yra, jo maistas, yra niekingas’.'),
  (@b39, 1, 13, 'Taip pat sakėte: ‘Štai koks tai varginimasis!’ Jūs tai užgesinote, – sako kariuomenių VIEŠPATS; – ir atnešėte tai, kas sudraskyta, luoša ir ligota; taip atnešėte atnašą; ar turėčiau tai priimti iš jūsų rankos? – sako kariuomenių VIEŠPATS.'),
  (@b39, 1, 14, '– Bet prakeiktas tebūna apgavikas, kuris savo kaimenėje turi patiną ir pažada, o aukoja VIEŠPAČIUI sugadintąjį; nes aš esu didis Karalius, – sako kariuomenių VIEŠPATS, – ir mano vardas bauginantis tarp pagonių“.'),
  (@b39, 2, 1, 'O dabar jūs, kunigai, šitas įsakymas yra jums.'),
  (@b39, 2, 2, '„Jei neklausysite ir jei nesidėsite to į širdį, kad duotumėte šlovę mano vardui, – sako kariuomenių VIEŠPATS, – aš siųsiu ant jūsų prakeikimą ir prakeiksiu jūsų palaiminimus; taip, jau prakeikiau juos, nes nesidedate to į širdį.'),
  (@b39, 2, 3, 'Štai aš sugadinsiu jūsų sėklą ir apdrabstysiu jūsų veidus mėšlu – jūsų iškilmingų švenčių mėšlu; ir su juo jus pašalins.'),
  (@b39, 2, 4, 'Ir žinosite, kad aš jums siunčiau šitą įsakymą, kad mano sandora būtų su Leviu, – sako kariuomenių VIEŠPATS.'),
  (@b39, 2, 5, '– Mano sandora buvo su juo gyvenimo ir ramybės; ir daviau jam juos dėl baimės, kuria jis bijojo manęs ir buvo išsigandęs prieš mano vardą.'),
  (@b39, 2, 6, 'Tiesos įstatymas buvo jo burnoje, ir neteisybės nerasta jo lūpose; jis vaikščiojo su manimi ramybėje ir teisingume, ir daugelį nukreipė nuo neteisybės.'),
  (@b39, 2, 7, 'Nes kunigo lūpos turėtų saugoti pažinimą, o jie turėtų ieškoti įstatymo iš jo burnos; nes jis yra kariuomenių VIEŠPATIES pasiuntinys.'),
  (@b39, 2, 8, 'Bet jūs esate pasitraukę nuo to kelio; jūs daugelį suklupdėte įstatymu; jūs iškraipėte Levio sandorą, – sako kariuomenių VIEŠPATS.'),
  (@b39, 2, 9, 'Todėl ir aš jus padariau niekingais ir menkais visos tautos akivaizdoje pagal tai, kaip ir jūs nesilaikėte mano kelių, bet buvote šališki įstatyme“.'),
  (@b39, 2, 10, 'Argi ne visi mes turime vieną tėvą? Argi ne vienas Dievas mus sutvėrė? Kodėl mes išdavikiškai elgiamės kiekvienas su savo broliu, suteršdami savo tėvų sandorą?'),
  (@b39, 2, 11, 'Išdavikiškai elgėsi Juda, ir bjaurystė daroma Izraelyje ir Jeruzalėje; nes Juda suteršė VIEŠPATIES šventumą, kurį jis mylėjo, ir vedė svetimo dievo dukterį.'),
  (@b39, 2, 12, 'VIEŠPATS iškirs žmogų, kuris tai daro, mokytoją bei mokinį iš Jokūbo padangčių ir tą, kuris atnašauja atnašą kariuomenių VIEŠPAČIUI.'),
  (@b39, 2, 13, 'Ir jūs vėl tai darėte, apdengdami VIEŠPATIES aukurą ašaromis, verksmu ir šauksmu taip, kad jis nebeatsižvelgia į atnašą ir jos nebepriima gera valia iš jūsų rankų.'),
  (@b39, 2, 14, 'Tačiau jūs sakote: „Kodėl?“ Todėl, kad VIEŠPATS buvo liudytojas tarp tavęs ir tavo jaunystės žmonos, su kuria tu elgeisi išdavikiškai; nors ji yra tavo draugė ir tavo sandoros žmona.'),
  (@b39, 2, 15, 'Argi jis ne vieną padarė? Jis dar turėjo dvasios likutį. Ir kodėl vieną? Kad jis ieškotų dievotos sėklos. Todėl rūpinkitės savo dvasia, ir tegul niekas nesielgia išdavikiškai su savo jaunystės žmona.'),
  (@b39, 2, 16, 'Nes VIEŠPATS, Izraelio Dievas, sako, kad nekenčia paleidimų; nes jie apdengia smurtą savo drabužiu, sako kariuomenių VIEŠPATS; todėl saugokite savo dvasią, kad nesielgtumėte išdavikiškai.'),
  (@b39, 2, 17, 'Jūs nuvarginote VIEŠPATĮ savo žodžiais. Tačiau jūs sakote: „Kuo mes jį nuvarginome?“ Kai jūs sakote: „Kiekvienas darantis pikta yra geras VIEŠPATIES akyse, ir tokiais jis gėrisi“; arba: „Kur yra teismo Dievas?“'),
  (@b39, 3, 1, '„Štai aš siųsiu savo pasiuntinį, ir jis paruoš kelią pirma manęs; ir Viešpats, kurio ieškote, staiga ateis į savo šventyklą, būtent sandoros pasiuntinys, kuriuo gėritės; štai jis ateis“, – sako kariuomenių VIEŠPATS.'),
  (@b39, 3, 2, 'Bet kas gali iškęsti jo atėjimo dieną? Ir kas išsilaikys jam pasirodžius? Nes jis yra kaip valytojo ugnis ir kaip vėlėjų muilas;'),
  (@b39, 3, 3, 'ir jis atsisės kaip sidabro valytojas ir grynintojas; jis išgrynins Levio sūnus ir juos išvalys kaip auksą ir sidabrą, kad jie atnašautų VIEŠPAČIUI atnašą teisumu.'),
  (@b39, 3, 4, 'Tada VIEŠPAČIUI patiks Judos ir Jeruzalės atnaša kaip senomis dienomis ir kaip ankstesniais metais.'),
  (@b39, 3, 5, '„Aš priartėsiu prie jūsų teismui; ir būsiu skubus liudytojas prieš burtininkus, prieš svetimautojus, prieš melagingai prisiekiančius ir prieš tuos, kurie engia samdinį jo uždarbiu, engia našles bei našlaičius, ir kuris nukreipia ateivį nuo jo teisių ir manęs nebijo, – sako kariuomenių VIEŠPATS.'),
  (@b39, 3, 6, '– Nes aš esu VIEŠPATS, aš nesikeičiu; todėl jūs, Jokūbo sūnūs, nesate sunaikinti.'),
  (@b39, 3, 7, 'Nuo savo tėvų dienų jūs pasitraukėte nuo mano įsakų ir jų nesilaikėte. Sugrįžkite pas mane, ir aš sugrįšiu pas jus, – sako kariuomenių VIEŠPATS. – Bet jūs sakėte: ‘Kaip mums sugrįžti?’'),
  (@b39, 3, 8, 'Ar žmogus apiplėš Dievą? Tačiau jūs apiplėšėte mane. Bet jūs sakote: ‘Kuo mes apiplėšėme tave?’ Dešimtinėmis ir atnašomis.'),
  (@b39, 3, 9, 'Jūs prakeikti prakeikimu; nes jūs – visa šita tauta – apiplėšėte mane.'),
  (@b39, 3, 10, 'Atneškite visas dešimtines į sandėlį, kad būtų maisto mano namuose, ir tuo išmėginkite mane, – sako kariuomenių VIEŠPATS, – ar aš neatidarysiu jums dangaus langų ir neišliesiu jums palaiminimo, kad neužteks vietos jį priimti.'),
  (@b39, 3, 11, 'Ir aš subarsiu dėl jūsų rijiką, ir jis nesunaikins jūsų dirvos vaisių; ir jūsų vynmedis prieš laiką neišmes savo vaisių lauke, – sako kariuomenių VIEŠPATS.'),
  (@b39, 3, 12, 'Ir visos tautos vadins jus palaimintais; nes jūs būsite pasigėrėtina šalis, – sako kariuomenių VIEŠPATS.'),
  (@b39, 3, 13, '– Jūsų žodžiai buvo narsūs prieš mane, – sako VIEŠPATS. – Tačiau jūs sakote: ‘Ką mes taip daug kalbėjome prieš tave?’'),
  (@b39, 3, 14, 'Jūs sakėte: ‘Tuščia yra tarnauti Dievui; kokia nauda, kad laikėmės jo įsakų ir gedulingai vaikščiojome kariuomenių VIEŠPATIES akivaizdoje?'),
  (@b39, 3, 15, 'Dabar mes vadiname laimingais išdidžiuosius; taip, tie, kurie daro nedorybę, yra įsitvirtinę; taip, tie, kurie gundo Dievą, yra išvaduoti’“.'),
  (@b39, 3, 16, 'Tada tie, kurie bijojo VIEŠPATIES, dažnai kalbėjosi vienas su kitu; o VIEŠPATS tai klausėsi ir girdėjo, ir jo akivaizdoje buvo parašyta atminimo knyga dėl tų, kurie bijojo VIEŠPATIES ir mąstė apie jo vardą.'),
  (@b39, 3, 17, '„Jie bus mano, – sako kariuomenių VIEŠPATS, – tą dieną, kai pagaminsiu savo brangenybes; ir jų gailėsiuos, kaip žmogus gailisi savo sūnaus, kuris jam tarnauja.'),
  (@b39, 3, 18, 'Tada jūs sugrįšite ir matysite skirtumą tarp teisiojo ir nedorėlio, tarp tarnaujančio Dievui ir tarp to, kuris jam netarnauja.'),
  (@b39, 4, 1, 'Nes štai ateina diena, deganti kaip krosnis; ir visi išdidieji, taip, ir visi, kurie elgiasi nedorai, bus ražienomis; ir juos sudegins ateinanti diena, – sako kariuomenių VIEŠPATS, – kad ji nepaliks jiems nei šaknies, nei šakos.'),
  (@b39, 4, 2, 'Bet jums, bijantiems mano vardo, patekės teisumo Saulė su išgydymu savo sparnuose, ir jūs išeisite ir augsite kaip tvarto veršiai.'),
  (@b39, 4, 3, 'Ir jūs mindysite nedorėlius; nes jie bus pelenai po jūsų kojų padais tą dieną, kai aš tai darysiu, – sako kariuomenių VIEŠPATS.'),
  (@b39, 4, 4, '– Atsiminkite mano tarno Mozės įstatymą, kurį jam įsakiau Horebe visam Izraeliui, su įstatais ir teismais.'),
  (@b39, 4, 5, 'Štai aš siųsiu jums pranašą Eliją, prieš ateinant didžiai ir baisiai VIEŠPATIES dienai;'),
  (@b39, 4, 6, 'ir jis atgręš tėvų širdis į vaikus ir vaikų širdis į jų tėvus, kad atėjęs neištikčiau žemės prakeikimu“.'),
  (@b40, 1, 1, 'Jėzaus Kristaus, Dovydo sūnaus, Abraomo sūnaus, kilmės knyga.'),
  (@b40, 1, 2, 'Abraomas pagimdė Izaoką; ir Izaokas pagimdė Jokūbą; ir Jokūbas pagimdė Judą ir jo brolius;'),
  (@b40, 1, 3, 'ir Juda pagimdė Faresą ir Zarą iš Tamaros; ir Faresas pagimdė Esromą; ir Esromas pagimdė Aramą;'),
  (@b40, 1, 4, 'ir Aramas pagimdė Aminadabą; ir Aminadabas pagimdė Naasoną; ir Naasonas pagimdė Salmoną;'),
  (@b40, 1, 5, 'ir Salmonas pagimdė Boozą iš Rahabos; ir Boozas pagimdė Jobedą iš Rūtos; ir Jobedas pagimdė Jesę;'),
  (@b40, 1, 6, 'ir Jesė pagimdė Dovydą – karalių; ir karalius Dovydas pagimdė Saliamoną iš tos, kuri buvo Ūrijo žmona;'),
  (@b40, 1, 7, 'ir Saliamonas pagimdė Roboamą; ir Roboamas pagimdė Abiją; ir Abija pagimdė Asą;'),
  (@b40, 1, 8, 'ir Asa pagimdė Juozapatą; ir Juozapatas pagimdė Joramą; ir Joramas pagimdė Oziją;'),
  (@b40, 1, 9, 'ir Ozijas pagimdė Joatamą; ir Joatamas pagimdė Achazą; ir Achazas pagimdė Ezekiją;'),
  (@b40, 1, 10, 'ir Ezekijas pagimdė Manasą; ir Manasas pagimdė Amoną; ir Amonas pagimdė Joziją;'),
  (@b40, 1, 11, 'ir Jozijas pagimdė Jechoniją ir jo brolius apie tą laiką, kai jie buvo išvesti į Babiloną;'),
  (@b40, 1, 12, 'ir po to, kai jie buvo nuvesti į Babiloną, Jechonijas pagimdė Salatielį; ir Salatielis pagimdė Zorobabelį;'),
  (@b40, 1, 13, 'ir Zorobabelis pagimdė Abijudą; ir Abijudas pagimdė Eliakimą; ir Eliakimas pagimdė Azorą;'),
  (@b40, 1, 14, 'ir Azoras pagimdė Sadoką; ir Sadokas pagimdė Achimą; ir Achimas pagimdė Elijudą;'),
  (@b40, 1, 15, 'ir Elijudas pagimdė Eleazarą; ir Eleazaras pagimdė Mataną; ir Matanas pagimdė Jokūbą;'),
  (@b40, 1, 16, 'ir Jokūbas pagimdė Juozapą – vyrą Marijos, iš kurios gimė Jėzus, kuris yra vadinamas Kristumi.'),
  (@b40, 1, 17, 'Taigi nuo Abraomo iki Dovydo – iš viso keturiolika kartų; ir nuo Dovydo iki išvedimo į Babiloną – keturiolika kartų; ir nuo išvedimo į Babiloną iki Kristaus – keturiolika kartų.'),
  (@b40, 1, 18, 'Na, o Jėzaus Kristaus gimimas buvo toks: kai jo motina Marija buvo susižadėjusi su Juozapu, prieš jiems sueinant kartu, ji radosi su vaiku iš Šventosios Dvasios.'),
  (@b40, 1, 19, 'Tuomet jos vyras Juozapas, būdamas teisus vyras ir nenorėdamas jos viešai apskelbti, buvo nusiteikęs slapta ją atleisti.'),
  (@b40, 1, 20, 'Bet, jam begalvojant apie tai, štai Viešpaties angelas pasirodė jam sapne, sakydamas: „Juozapai, Dovydo sūnau, nebijok pasiimti sau savo žmonos Marijos, nes tai, kas joje prasidėjo, yra iš Šventosios Dvasios.'),
  (@b40, 1, 21, 'Ir ji pagimdys sūnų, ir tu pavadinsi jį vardu JĖZUS, nes jis išgelbės savo tautą iš jos nuodėmių.'),
  (@b40, 1, 22, 'Na, o visa tai atsitiko, kad išsipildytų tai, kas buvo Viešpaties kalbėta per pranašą, sakant:'),
  (@b40, 1, 23, '‘Štai mergelė bus nėščia ir pagimdys sūnų, ir jie vadins jį vardu Emanuelis’, kas išvertus reiškia ‘Dievas su mumis’“.'),
  (@b40, 1, 24, 'Tada Juozapas atsikėlęs iš miego padarė, kaip Viešpaties angelas buvo jam įsakęs, ir pasiėmė savo žmoną,'),
  (@b40, 1, 25, 'ir jos nepažinojo, kol ji nepagimdė savo pirmagimio sūnaus; ir jis pavadino jį vardu JĖZUS.'),
  (@b40, 2, 1, 'Na, o kai Jėzus buvo gimęs Judėjos Betliejuje, karaliaus Erodo dienomis, štai atkeliavo į Jeruzalę išminčiai iš rytų,'),
  (@b40, 2, 2, 'sakydami: „Kur yra tas, kuris gimė – žydų Karalius? Nes matėme jo žvaigždę rytuose ir atvykome jo pagarbinti“.'),
  (@b40, 2, 3, 'Išgirdęs tai, karalius Erodas sunerimo, ir su juo visa Jeruzalė,'),
  (@b40, 2, 4, 'ir susikvietęs visus tautos vyriausiuosius kunigus bei raštininkus jis jų teiravosi, kur turėjęs gimti Kristus.'),
  (@b40, 2, 5, 'Ir jie tarė jam: „Judėjos Betliejuje, nes taip yra pranašo parašyta:'),
  (@b40, 2, 6, '‘Ir tu, Betliejau Judos šalyje, nesi mažiausias tarp Judos kunigaikščių, nes iš tavęs ateis Valdytojas, kuris valdys mano tautą Izraelį’“.'),
  (@b40, 2, 7, 'Tada Erodas, slapta pasikvietęs išminčius, stropiai juos išklausinėjo, kokiu laiku pasirodė žvaigždė.'),
  (@b40, 2, 8, 'Ir jis pasiuntė juos į Betliejų ir pasakė: „Eikite ir rūpestingai ieškokite mažo vaiko; ir kai jį surasite, praneškite man, kad ir aš ateičiau ir jį pagarbinčiau“.'),
  (@b40, 2, 9, 'Išklausę karaliaus jie išvyko; ir štai žvaigždė, kurią jie matė rytuose, ėjo pirma jų, kol ji atėjo ir atsistojo viršum ten, kur buvo mažas vaikas.'),
  (@b40, 2, 10, 'Kai jie pamatė žvaigždę, jie džiaugėsi be galo dideliu džiaugsmu.'),
  (@b40, 2, 11, 'Ir, įėję į namą, jie pamatė mažą vaiką su jo motina Marija ir parpuolė, ir jį pagarbino; ir kai jie atidengė savo brangenybes, jie pristatė jam dovanas: auksą ir smilkalus, ir mirą.'),
  (@b40, 2, 12, 'Ir sapne Dievo perspėti, kad negrįžtų pas Erodą, jie kitu keliu iškeliavo į savo šalį.'),
  (@b40, 2, 13, 'Ir kai jie buvo išėję, štai Viešpaties angelas pasirodė Juozapui sapne, sakydamas: „Kelkis ir pasiimk mažą vaiką bei jo motiną, ir bėk į Egiptą, ir būk ten, kol aš tau pranešiu, nes Erodas ieškos mažo vaiko, kad jį sunaikintų“.'),
  (@b40, 2, 14, 'Atsikėlęs jis nakčia pasiėmė mažą vaiką bei jo motiną ir iškeliavo į Egiptą;'),
  (@b40, 2, 15, 'ir ten buvo iki Erodo mirties, kad išsipildytų, kas Viešpaties buvo pasakyta per pranašą, sakant: „Iš Egipto aš pašaukiau savo sūnų“.'),
  (@b40, 2, 16, 'Tuomet Erodas, pamatęs, kad buvo išminčių pajuoktas, be galo užsirūstino ir pasiuntė, ir išžudė visus vaikus, kurie buvo Betliejuje ir visose jo ribose nuo dvejų metų ir jaunesnius, pagal tą laiką, kurį stropiai išklausinėjo išminčių.'),
  (@b40, 2, 17, 'Tuomet išsipildė tai, kas buvo pranašo Jeremijo kalbėta, sakant:'),
  (@b40, 2, 18, '„Ramoje girdėjosi balsas, rauda ir verksmas, ir didžiulis gedulas: Rachelė verkia savo vaikų ir nenori būti paguosta, nes jų nebėra“.'),
  (@b40, 2, 19, 'Bet, kai Erodas buvo miręs, štai Viešpaties angelas Egipte pasirodė Juozapui sapne,'),
  (@b40, 2, 20, 'sakydamas: „Kelkis ir pasiimk mažą vaiką bei jo motiną ir eik į Izraelio šalį, nes yra mirę tie, kurie ieškojo mažo vaiko gyvybės“.'),
  (@b40, 2, 21, 'Ir jis atsikėlė ir pasiėmė mažą vaiką bei jo motiną, ir atėjo į Izraelio šalį.'),
  (@b40, 2, 22, 'Bet, kai išgirdo, kad Judėjoje valdo Archelajus savo tėvo Erodo vietoje, jis bijojo ten eiti; tačiau sapne Dievo įspėtas, jis pasuko į Galilėjos sritis;'),
  (@b40, 2, 23, 'ir jis atėjo ir apsigyveno mieste, vadinamame Nazaretu, idant išsipildytų, kas buvo kalbėta pranašų: „Jį vadins nazariečiu“.'),
  (@b40, 3, 1, 'Tomis dienomis atėjo Jonas Krikštytojas, skelbdamas Judėjos dykumoje'),
  (@b40, 3, 2, 'ir sakydamas: „Atgailaukite, nes dangaus karalystė yra čia pat“.'),
  (@b40, 3, 3, 'Nes tai tas, apie kurį yra kalbėjęs pranašas Izaijas, sakydamas: „Dykumoje šaukiančiojo balsas: ‘Paruoškite Viešpaties kelią, tiesius darykite jo takus’“.'),
  (@b40, 3, 4, 'Ir tas pats Jonas turėjo kupranugario šerių drabužį ir aplink strėnas – odinį diržą; ir jo maistas buvo skėriai bei laukinis medus.'),
  (@b40, 3, 5, 'Tuomet išėjo pas jį Jeruzalė ir visa Judėja, ir visa sritis aplink Jordaną,'),
  (@b40, 3, 6, 'ir buvo jo krikštijami Jordane, išpažindami savo nuodėmes.'),
  (@b40, 3, 7, 'Bet, pamatęs daugelį iš fariziejų ir sadukiejų ateinančių prie jo krikšto, jis jiems tarė: „O angių palikuonys, kas jus perspėjo bėgti nuo ateinančios rūstybės?');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b40, 3, 8, 'Todėl duokite vaisių, deramų atgailai;'),
  (@b40, 3, 9, 'ir nemanykite sakyti savyje: ‘Mes turime Abraomą savo tėvu’; nes aš jums sakau, kad Dievas gali iš šitų akmenų prikelti vaikų Abraomui.'),
  (@b40, 3, 10, 'O ir kirvis jau pridėtas prie medžių šaknies; todėl kiekvienas medis, kuris neduoda gero vaisiaus, yra iškertamas ir įmetamas į ugnį.'),
  (@b40, 3, 11, 'Aš, tiesa, jus krikštiju vandeniu atgailai, bet tas, kuris ateina po manęs, yra galingesnis už mane, aš nevertas nešti jo apavą; jis krikštys jus Šventąja Dvasia ir ugnimi;'),
  (@b40, 3, 12, 'jo vėtyklė – jo rankoje, ir jis visiškai išvalys savo klojimą ir surinks savo kviečius į svirną; bet jis sudegins pelus neužgesinama ugnimi“.'),
  (@b40, 3, 13, 'Tuomet ateina Jėzus iš Galilėjos prie Jordano pas Joną, kad būtų jo pakrikštytas.'),
  (@b40, 3, 14, 'Bet Jonas jam uždraudė, sakydamas: „Aš turiu būti tavęs pakrikštytas, o tu ateini pas mane?“'),
  (@b40, 3, 15, 'Ir Jėzus atsakydamas jam tarė: „Dabar leisk, kad taip būtų, nes taip mums dera išpildyti visą teisumą“. Tada jis jam leido.'),
  (@b40, 3, 16, 'Ir kai Jėzus buvo pakrikštytas, tuoj išėjo iš vandens; ir štai jam atsivėrė dangūs, ir jis pamatė Dievo Dvasią nusileidžiančią kaip balandį ir nutupiančią ant jo;'),
  (@b40, 3, 17, 'ir štai balsas iš dangaus sakantis: „Šitas yra mano mylimas Sūnus, kuriuo aš labai patenkintas“.'),
  (@b40, 4, 1, 'Tada Jėzus buvo Dvasios nuvestas į dykumą, kad būtų velnio gundomas.'),
  (@b40, 4, 2, 'Ir po to, kai išpasninkavo keturiasdešimt dienų ir keturiasdešimt naktų, jis buvo alkanas.'),
  (@b40, 4, 3, 'Ir gundytojas, atėjęs pas jį, tarė: „Jei tu esi Dievo Sūnus, įsakyk, kad šie akmenys pavirstų duona“.'),
  (@b40, 4, 4, 'Bet jis atsakydamas tarė: „Yra parašyta: ‘Žmogus gyvens ne vien duona, bet kiekvienu žodžiu, išeinančiu iš Dievo burnos’“.'),
  (@b40, 4, 5, 'Tuomet velnias paima jį į šventąjį miestą ir pastato jį ant šventyklos viršūnės,'),
  (@b40, 4, 6, 'ir sako jam: „Jei tu esi Dievo Sūnus, meskis žemyn, nes yra parašyta: ‘Jis įpareigos savo angelus dėl tavęs, ir savo rankose jie nešios tave, idant neužsigautum kada savo kojos į akmenį’“.'),
  (@b40, 4, 7, 'Jėzus jam tarė: „Vėlgi yra parašyta: ‘Negundyk Viešpaties, savo Dievo’“.'),
  (@b40, 4, 8, 'Vėl velnias paima jį į be galo aukštą kalną ir parodo jam visas pasaulio karalystes bei jų šlovę;'),
  (@b40, 4, 9, 'ir jam sako: „Visa tai duosiu tau, jei parpulsi ir mane pagarbinsi“.'),
  (@b40, 4, 10, 'Tuomet Jėzus jam sako: „Eik šalin, šėtone, nes yra parašyta: ‘Garbink Viešpatį, savo Dievą, ir jam vienam tarnauk’“.'),
  (@b40, 4, 11, 'Tada velnias jį palieka, ir štai atėjo angelai ir jam tarnavo.'),
  (@b40, 4, 12, 'Na, o kai Jėzus išgirdo, kad Jonas įmestas į kalėjimą, jis išėjo į Galilėją;'),
  (@b40, 4, 13, 'ir, palikęs Nazaretą, jis atėjo ir apsigyveno Kafernaume, kuris yra jūros pakrantėje, Zabulono ir Neftalio ribose,'),
  (@b40, 4, 14, 'kad išsipildytų, kas buvo kalbėta pranašo Izaijo, sakant:'),
  (@b40, 4, 15, '„Zabulono šalis ir Neftalio šalis, prie jūros kelio, anapus Jordano, pagonių Galilėja;'),
  (@b40, 4, 16, 'tauta, kuri sėdėjo tamsoje, išvydo didžią šviesą; ir tiems, kurie sėdėjo krašte ir šešėlyje mirties, užtekėjo šviesa“.'),
  (@b40, 4, 17, 'Nuo to laiko Jėzus pradėjo skelbti ir sakyti: „Atgailaukite, nes dangaus karalystė yra čia pat“.'),
  (@b40, 4, 18, 'Ir Jėzus, vaikščiodamas palei Galilėjos jūrą, pamatė du brolius: Simoną, vadinamą Petru, ir jo brolį Andriejų, metančius tinklą į jūrą, nes jie buvo žvejai.'),
  (@b40, 4, 19, 'Ir jis sako jiems: „Sekite paskui mane, ir aš jus padarysiu žmonių žvejais“.'),
  (@b40, 4, 20, 'Ir jie tuojau paliko savo tinklus ir sekė paskui jį.'),
  (@b40, 4, 21, 'Ir iš ten eidamas jis pamatė kitus du brolius – Zebediejaus sūnų Jokūbą ir jo brolį Joną – laive su jų tėvu Zebediejumi savo tinklus betaisančius, ir jis pašaukė juos.'),
  (@b40, 4, 22, 'Ir jie tuoj pat paliko laivą bei savo tėvą ir sekė paskui jį.'),
  (@b40, 4, 23, 'Ir Jėzus ėjo po visą Galilėją, mokydamas jų sinagogose ir skelbdamas karalystės evangeliją, ir gydydamas visokias negalias bei visokias ligas tautos tarpe.'),
  (@b40, 4, 24, 'Ir garsas apie jį sklido po visą Siriją; ir jie atnešė pas jį visus sergančius, įvairiausių ligų bei kančių apimtus, ir tuos, kurie buvo velnių apsėsti, ir tuos, kurie buvo lunatikai, ir tuos, kurie turėjo paralyžių; ir jis išgydė juos.'),
  (@b40, 4, 25, 'Ir paskui jį sekė didžiulės minios žmonių iš Galilėjos ir iš Dekapolio, ir iš Jeruzalės, ir iš Judėjos, ir iš anapus Jordano.'),
  (@b40, 5, 1, 'Ir matydamas minias jis užlipo į kalną; ir kai jis atsisėdo, pas jį atėjo jo mokiniai;'),
  (@b40, 5, 2, 'ir jis pravėrė savo burną ir juos mokė, sakydamas:'),
  (@b40, 5, 3, '„Palaiminti vargšai dvasia, nes jų yra dangaus karalystė.'),
  (@b40, 5, 4, 'Palaiminti tie, kurie liūdi, nes jie bus paguosti.'),
  (@b40, 5, 5, 'Palaiminti romieji, nes jie paveldės žemę.'),
  (@b40, 5, 6, 'Palaiminti tie, kurie alksta ir trokšta teisumo, nes jie bus pasotinti.'),
  (@b40, 5, 7, 'Palaiminti gailestingieji, nes jie įgys gailestingumą.'),
  (@b40, 5, 8, 'Palaiminti tyraširdžiai, nes jie matys Dievą.'),
  (@b40, 5, 9, 'Palaiminti taikdariai, nes jie bus vadinami Dievo vaikais.'),
  (@b40, 5, 10, 'Palaiminti tie, kurie persekiojami dėl teisumo, nes jų yra dangaus karalystė.'),
  (@b40, 5, 11, 'Palaiminti esate jūs, kai dėl manęs jus keiks ir persekios, ir melagingai kalbės apie jus visokį blogį.'),
  (@b40, 5, 12, 'Džiaukitės ir būkite be galo linksmi, nes didelis yra jūsų užmokestis danguje; nes taip jie persekiojo anksčiau jūsų buvusius pranašus“.'),
  (@b40, 5, 13, '„Jūs esate žemės druska; bet jei druska praranda savo skonį, kuo gi ją bepasūdysi? Ji jau niekam nebetinka, o tik kad būtų išmesta lauk ir sumindyta žmonėms po kojomis.'),
  (@b40, 5, 14, 'Jūs esate pasaulio šviesa. Miestas, pastatytas ant kalvos, negali būti paslėptas.'),
  (@b40, 5, 15, 'Nei kas, uždegęs žvakę, nestato jos po saiku, bet į žvakidę; ir ji duoda šviesą visiems esantiems namuose.'),
  (@b40, 5, 16, 'Taip jūsų šviesa tešviečia žmonių akivaizdoje, kad jie matytų jūsų gerus darbus ir šlovintų jūsų Tėvą, kuris yra danguje“.'),
  (@b40, 5, 17, '„Nemanykite, kad atėjau sunaikinti įstatymo ar pranašų; atėjau ne sunaikinti, bet išpildyti.'),
  (@b40, 5, 18, 'Nes iš tiesų sakau jums: kol dangus ir žemė nepraeis, nei viena raidelė, nei vienas brūkšnelis jokiu būdu neišnyks iš įstatymo, kol viskas išsipildys.'),
  (@b40, 5, 19, 'Todėl, kas sulaužys vieną iš šitų mažiausių įsakymų ir taip mokys žmones, tas bus vadinamas mažiausiu dangaus karalystėje; bet kas juos vykdys ir mokys, tas bus vadinamas didžiu dangaus karalystėje.'),
  (@b40, 5, 20, 'Nes sakau jums: jeigu jūsų teisumas nepranoks raštininkų ir fariziejų teisumo, jūs jokiu atveju neįeisite į dangaus karalystę“.'),
  (@b40, 5, 21, '„Jūs girdėjote, kad buvo senolių pasakyta: ‘Nežudyk’; ir kas nužudys, tam gresia teismas;'),
  (@b40, 5, 22, 'bet aš jums sakau: kas be priežasties pyksta ant savo brolio, tam gresia teismas; ir kas pasakys savo broliui: ‘Raka’, tam gresia taryba; bet kas pasakys: ‘Tu kvailys’, tam gresia pragaro ugnis.'),
  (@b40, 5, 23, 'Todėl jei atneši savo dovaną prie aukuro ir ten prisimeni, kad tavo brolis turi kažką tai prieš tave,'),
  (@b40, 5, 24, 'palik savo dovaną ten prie aukuro ir eik; pirmiausia susitaikyk su savo broliu ir tada ateik, ir atnašauk savo dovaną.'),
  (@b40, 5, 25, 'Greitai susitark su savo priešininku, kol dar esi su juo kelyje; kad kuriuo metu priešininkas tavęs neatiduotų teisėjui, o teisėjas neatiduotų tavęs pareigūnui, ir tu nebūtum įmestas į kalėjimą.'),
  (@b40, 5, 26, 'Iš tikrųjų sakau tau: tu jokiu būdu iš ten neišeisi, kol nesumokėsi iki paskutinio kvadranto“.'),
  (@b40, 5, 27, '„Esate girdėję, kad buvo senolių pasakyta: ‘Nesvetimauk’;'),
  (@b40, 5, 28, 'bet aš jums sakau: kas žiūri į moterį jos geisdamas, tas jau svetimavo su ja savo širdyje.'),
  (@b40, 5, 29, 'Ir jei tavo dešinioji akis tave piktina, išlupk ją ir mesk nuo savęs, nes tau yra naudinga, kad pražūtų vienas iš tavo narių, o ne kad visas tavo kūnas būtų įmestas į pragarą.'),
  (@b40, 5, 30, 'Ir jei tavo dešinioji ranka tave piktina, nukirsk ją ir mesk nuo savęs, nes tau yra naudinga, kad pražūtų vienas iš tavo narių, o ne kad visas tavo kūnas būtų įmestas į pragarą“.'),
  (@b40, 5, 31, '„Buvo pasakyta: ‘Kas pašalins savo žmoną, teduoda jai skyrybų raštą’;'),
  (@b40, 5, 32, 'bet aš jums sakau: kas pašalins savo žmoną ne dėl paleistuvavimo, tas verčia ją svetimauti, ir kas išsiskyrusiąją veda – svetimauja“.'),
  (@b40, 5, 33, '„Vėlgi – jūs girdėjote, kad buvo senolių pasakyta: ‘Melagingai neprisiek, bet ištesėk Viešpačiui savo priesaikas’;'),
  (@b40, 5, 34, 'bet aš jums sakau: iš viso neprisiekinėkite – nei dangumi, nes tai yra Dievo sostas,'),
  (@b40, 5, 35, 'nei žeme, nes tai yra jo pakojis; nei Jeruzale, nes ji yra didžiojo Karaliaus miestas.'),
  (@b40, 5, 36, 'Neprisiek nei savo galva, nes tu negali padaryti nei vieno plauko balto ar juodo.'),
  (@b40, 5, 37, 'Bet tegul jūsų bendravimas būna ‘Taip – taip’, ‘Ne – ne’; nes kas yra daugiau šitų, ateina iš pikto“.'),
  (@b40, 5, 38, '„Jūs girdėjote, kad buvo pasakyta: ‘Akis už akį ir dantis už dantį’;'),
  (@b40, 5, 39, 'bet aš jums sakau: nesipriešinkite piktam; bet jei kas tau smogtų į dešinį skruostą, atsuk jam ir kitą.'),
  (@b40, 5, 40, 'Ir jei kas norėtų su tavimi bylinėtis ir atims tavo marškinius, atiduok jam ir savo apsiaustą.'),
  (@b40, 5, 41, 'Ir jei kas vers tave nueiti mylią, nueik su juo dvi.'),
  (@b40, 5, 42, 'Duok tam, kuris tavęs prašo, ir nenusigręžk nuo to, kuris nori iš tavęs pasiskolinti“.'),
  (@b40, 5, 43, '„Jūs girdėjote, kad buvo pasakyta: ‘Mylėk savo artimą ir nekęsk savo priešo’.'),
  (@b40, 5, 44, 'Bet aš jums sakau: mylėkite savo priešus, laiminkite tuos, kurie jus keikia, darykite gera tiems, kurie jūsų nekenčia, ir melskitės už tuos, kurie piktai su jumis elgiasi ir jus persekioja;'),
  (@b40, 5, 45, 'kad būtumėte vaikai savo Tėvo, kuris yra danguje; nes jis padaro, kad jo saulė patekėtų piktiems bei geriems ir siunčia lietų teisiems bei neteisiems.'),
  (@b40, 5, 46, 'Nes jei mylite tuos, kurie jus myli, kokį gi turite atlygį? Argi ir muitininkai taip nedaro?'),
  (@b40, 5, 47, 'Ir jei sveikinate tik savo brolius, ką gi darote daugiau už kitus? Argi taip nedaro ir muitininkai?'),
  (@b40, 5, 48, 'Todėl būkite tobuli, kaip ir jūsų Tėvas, esantis danguje, yra tobulas“.'),
  (@b40, 6, 1, '„Saugokitės, kad nedalintumėte savo išmaldų žmonių akyse, idant būtumėte jų matomi, kitaip jūs neturite užmokesčio iš savo Tėvo, kuris yra danguje.'),
  (@b40, 6, 2, 'Todėl, kai dalini savo išmaldas, netrimituok prieš save, kaip daro veidmainiai sinagogose ir gatvėse, kad jie būtų žmonių giriami. Iš tiesų jums sakau: jie turi savo užmokestį.'),
  (@b40, 6, 3, 'Bet kai dalini išmaldas, tegul tavo kairė nežino, ką daro dešinė,'),
  (@b40, 6, 4, 'kad tavo išmaldos būtų slaptoje; ir tavo Tėvas, kuris mato slaptoje, pats atlygins tau viešai.'),
  (@b40, 6, 5, 'Ir kai meldiesi, nebūk kaip veidmainiai, nes jie mėgsta melstis stovėdami sinagogose ir gatvių kampuose, kad būtų matomi žmonių. Iš tiesų jums sakau: jie turi savo užmokestį.'),
  (@b40, 6, 6, 'Bet kai tu meldiesi, įeik į savo kambarėlį ir užsirakinęs duris melskis savo Tėvui, kuris yra slaptoje; ir tavo Tėvas, kuris mato slaptoje, atlygins tau viešai.'),
  (@b40, 6, 7, 'Bet kai meldžiatės, nevartokite tuščių pakartojimų, kaip pagonys daro, nes jie galvoja, kad jie bus išgirsti dėl jų gausaus kalbėjimo.'),
  (@b40, 6, 8, 'Todėl nebūkite kaip jie, nes jūsų Tėvas žino, ko jums reikia prieš jums dar jo prašant.'),
  (@b40, 6, 9, 'Todėl šitaip melskitės: „Tėve mūsų, kuris esi danguje, tebūna pašvęstas tavo vardas.'),
  (@b40, 6, 10, 'Teateina tavo karalystė. Tebūna įvykdyta tavo valia žemėje, kaip kad ji yra danguje.'),
  (@b40, 6, 11, 'Kasdienės mūsų duonos duok mums šiandien.'),
  (@b40, 6, 12, 'Ir atleisk mums mūsų skolas, kaip mes atleidžiame savo skolininkams.'),
  (@b40, 6, 13, 'Ir nevesk mūsų į pagundą, bet išvaduok mus nuo pikto; nes tavo yra karalystė ir galia, ir šlovė per amžius. Amen“.'),
  (@b40, 6, 14, 'Nes jei atleidžiate žmonėms jų nusižengimus, tai ir jūsų dangiškasis Tėvas jums atleis;'),
  (@b40, 6, 15, 'bet jei neatleisite žmonėms jų nusižengimų, tai nei jūsų Tėvas neatleis jūsų nusižengimų“.'),
  (@b40, 6, 16, '„Be to, kai pasninkaujate, nebūkite kaip veidmainiai, liūdna veido išraiška, nes jie iškreipia savo veidus, kad jie pasirodytų žmonėms esą pasninkaujantys. Iš tiesų sakau jums: jie turi savąjį atlygį.'),
  (@b40, 6, 17, 'Bet kai tu pasninkauji, pasitepk savo galvą ir nusiplauk savo veidą,'),
  (@b40, 6, 18, 'kad ne žmonėms rodytumeisi pasninkaująs, bet savo Tėvui, kuris yra slaptoje; ir tavo Tėvas, kuris mato slaptoje, atlygins tau viešai.'),
  (@b40, 6, 19, 'Nekraukite sau lobių žemėje, kur kandys bei rūdys sugadina, ir kur vagys įsilaužia bei vagia;'),
  (@b40, 6, 20, 'bet kraukite sau lobius danguje, kur nei kandys, nei rūdys nesugadina, ir kur vagys neįsilaužia ir nevagia;'),
  (@b40, 6, 21, 'nes kur yra jūsų lobis, ten bus ir jūsų širdis.'),
  (@b40, 6, 22, 'Kūno šviesa yra akis, todėl jei tavo akis vienalypė, visas tavo kūnas bus pilnas šviesos.'),
  (@b40, 6, 23, 'Bet jei tavo akis pikta, tavo visas kūnas bus pilnas tamsos. Todėl jei tavyje esanti šviesa yra tamsa, tai kokia didelė toji tamsa!'),
  (@b40, 6, 24, 'Niekas negali tarnauti dviem šeimininkams, nes jis vieno nekęs, o kitą – mylės; arba jis vieno laikysis, o kitą niekins. Jūs negalite tarnauti Dievui ir momonai.'),
  (@b40, 6, 25, 'Todėl sakau jums: nesirūpinkite savo gyvybe, ką valgysite ar ką gersite; nei savo kūnu, kuo vilkėsite. Argi gyvybė ne daugiau už maistą, o kūnas – už drabužį?'),
  (@b40, 6, 26, 'Pažvelkite į oro skrajūnus: jie nei sėja, nei pjauna, nei į kluonus krauna; tačiau jūsų dangiškasis Tėvas juos maitina. Argi nesate daug geresni už juos?'),
  (@b40, 6, 27, 'Kuris iš jūsų savo rūpesčiu gali pridėti vieną uolektį savo ūgiui?'),
  (@b40, 6, 28, 'Ir kodėl rūpinatės drabužiu? Įdėmiai stebėkite lauko lelijas, kaip jos auga – jos nei dirba, nei verpia;'),
  (@b40, 6, 29, 'tačiau jums sakau, kad netgi Saliamonas visoje savo šlovėje nebuvo taip pasipuošęs, kaip bet kuri iš jų.'),
  (@b40, 6, 30, 'Tai jei Dievas taip aprengia lauko žolę, kuri šiandien yra, o rytoj įmetama į krosnį, tai argi jis dar labiau neaprengs jūsų, o jūs, mažatikiai?'),
  (@b40, 6, 31, 'Todėl nesirūpinkite sakydami: ‘Ką valgysime?’ arba ‘Ką gersime?’ arba ‘Kuo apsirengsime?’'),
  (@b40, 6, 32, '(nes viso to ieško pagonys), nes jūsų dangiškasis Tėvas žino, kad jums reikia viso to.'),
  (@b40, 6, 33, 'Bet pirmiausiai ieškokite Dievo karalystės ir jo teisumo; ir visa tai bus jums pridėta.'),
  (@b40, 6, 34, 'Todėl nesirūpinkite rytojumi, nes rytojus pats pasirūpins savo reikalais. Dienai užtenka savo blogio“.'),
  (@b40, 7, 1, '„Neteiskite, kad nebūtumėte teisiami.'),
  (@b40, 7, 2, 'Nes kokiu teismu teisiate, tokiu jūs būsite teisiami; ir kokiu matu matuojate, tokiu jums bus atmatuota.'),
  (@b40, 7, 3, 'Ir kodėl matai krislą, esantį savo brolio akyje, bet nepastebi rąsto, esančio savojoje akyje?'),
  (@b40, 7, 4, 'Arba kaip gali sakyti savo broliui: ‘Leisk man išimti krislą iš tavo akies’, o štai rąstas yra tavo akyje?'),
  (@b40, 7, 5, 'Veidmainy, pirma išmesk rąstą iš savo akies; ir tuomet aiškiai matysi, kaip išmesti krislą iš savo brolio akies“.'),
  (@b40, 7, 6, '„Neduokite to, kas šventa, šunims nei nemeskite savo perlų prieš kiaules, kad jos nesutryptų jų po savo kojomis ir atsigręžusios jūsų nesudraskytų“.'),
  (@b40, 7, 7, '„Prašykite, ir jums bus duota; ieškokite, ir surasite; belskite, ir jums bus atidaryta;'),
  (@b40, 7, 8, 'nes kiekvienas, kas prašo, gauna; ir kas ieško, randa; ir tam, kas beldžiasi, bus atidaryta.'),
  (@b40, 7, 9, 'Arba kuris žmogus čia iš jūsų, jeigu jo sūnus jo prašytų duonos, duotų jam akmenį?'),
  (@b40, 7, 10, 'Arba jeigu jis prašytų žuvies, argi jis duotų jam gyvatę?'),
  (@b40, 7, 11, 'Tad jei jūs, būdami pikti, žinote, kaip duoti gerų dovanų savo vaikams, tad kiek daugiau jūsų Tėvas, kuris yra danguje, duos gera tiems, kurie jo prašo?'),
  (@b40, 7, 12, 'Todėl visa, ko norėtumėte, kad žmonės jums darytų, taip ir jūs jiems darykite; nes tai yra įstatymas ir pranašai“.'),
  (@b40, 7, 13, '„Įeikite pro ankštus vartus, nes erdvūs yra vartai ir platus yra kelias, kuris veda į pražūtį, ir daug yra pro juos einančių;'),
  (@b40, 7, 14, 'nes ankšti yra vartai ir siauras yra kelias, kuris veda į gyvenimą, ir nedaug yra jį atrandančių“.'),
  (@b40, 7, 15, '„Saugokitės netikrų pranašų, kurie ateina pas jus avių rūbuose, bet viduje jie yra plėšrūs vilkai.'),
  (@b40, 7, 16, 'Iš jų vaisių juos pažinsite. Ar žmonės renka vynuoges nuo erškėčių arba figas nuo usnių?'),
  (@b40, 7, 17, 'Taip ir kiekvienas geras medis duoda gerą vaisių; bet sugedęs medis duoda blogą vaisių.'),
  (@b40, 7, 18, 'Geras medis negali duoti blogo vaisiaus, nei sugedęs medis negali duoti gero vaisiaus.'),
  (@b40, 7, 19, 'Kiekvienas medis, kuris neduoda gero vaisiaus, yra iškertamas ir įmetamas į ugnį.'),
  (@b40, 7, 20, 'Todėl iš jų vaisių juos pažinsite“.'),
  (@b40, 7, 21, '„Ne kiekvienas, kuris sako man: ‘Viešpatie, Viešpatie’, įeis į dangaus karalystę; bet tik tas, kuris vykdo valią mano Tėvo, kuris yra danguje.'),
  (@b40, 7, 22, 'Daugelis man sakys aną dieną: ‘Viešpatie, Viešpatie, argi nepranašavome tavo vardu? Ir argi tavo vardu neišvarinėjome velnių? Ir argi tavo vardu nedarėme daug nuostabių darbų?’'),
  (@b40, 7, 23, 'Ir tada jiems pareikšiu: ‚Aš niekada jūsų nepažinojau – pasitraukite nuo manęs jūs, kurie darote neteisybę’“.'),
  (@b40, 7, 24, '„Todėl tą, kuris klauso šitų mano pasakymų ir juos vykdo, aš prilyginu išmintingam žmogui, kuris pasistatė namus ant uolos;'),
  (@b40, 7, 25, 'ir lijo lietus, ir užėjo potvyniai, ir pūtė vėjai, ir daužėsi į tuos namus, o jie nenugriuvo, nes jų pamatai buvo pastatyti ant uolos.'),
  (@b40, 7, 26, 'Ir kiekvienas, kas klauso šitų mano pasakymų ir jų nevykdo, bus prilygintas kvailam žmogui, kuris pasistatė savo namus ant smėlio;'),
  (@b40, 7, 27, 'ir lijo lietus, ir užėjo potvyniai, ir pūtė vėjai, ir daužėsi į tuos namus; ir jie sugriuvo, ir smarkus buvo jų griuvimas“.'),
  (@b40, 7, 28, 'Ir įvyko, kai Jėzus pabaigė tuos pasakymus, tauta stebėjosi jo mokslu;'),
  (@b40, 7, 29, 'nes jis juos mokė kaip turintis valdžią, o ne kaip raštininkai.'),
  (@b40, 8, 1, 'Kai jis nusileido nuo kalno, didžiulės minios sekė paskui jį.'),
  (@b40, 8, 2, 'Ir štai atėjo raupsuotasis ir pagarbino jį, sakydamas: „Viešpatie, jei nori, gali mane padaryti švarų“.'),
  (@b40, 8, 3, 'Ir Jėzus ištiesė ranką ir palietė jį, sakydamas: „Noriu, būk švarus“. Ir tučtuojau jo raupsai buvo apvalyti.'),
  (@b40, 8, 4, 'Ir Jėzus jam sako: „Žiūrėk, niekam nesakyk; bet eik, pasirodyk kunigui ir atnašauk dovaną, kurią Mozė įsakė kaip liudijimą jiems“.'),
  (@b40, 8, 5, 'Ir kai Jėzus buvo įėjęs į Kafernaumą, pas jį atėjo šimtininkas, maldaudamas jo'),
  (@b40, 8, 6, 'ir sakydamas: „Viešpatie, mano tarnas guli namie sergantis paralyžiumi, sunkiai besikankindamas“.'),
  (@b40, 8, 7, 'Ir Jėzus jam sako: „Aš ateisiu ir jį išgydysiu“.'),
  (@b40, 8, 8, 'Šimtininkas atsakydamas tarė: „Viešpatie, nesu vertas, kad ateitum po mano stogu, bet ištark tik žodį, ir mano tarnas bus išgydytas.'),
  (@b40, 8, 9, 'Nes esu žmogus pavaldus valdžiai, turintis sau pavaldžių kareivių; ir sakau tam: ‘Eik’, ir jis eina; ir kitam: ‘Ateik’, ir jis ateina; ir savo tarnui: ‘Daryk tai’, ir jis tai daro“.'),
  (@b40, 8, 10, 'Kai Jėzus tai išgirdo, jis stebėjosi ir pasakė tiems, kurie sekė paskui: „Iš tiesų sakau jums: ne, neradau tokio didelio tikėjimo nei Izraelyje.'),
  (@b40, 8, 11, 'Ir sakau jums, kad daugelis ateis iš rytų bei vakarų ir sėsis su Abraomu ir Izaoku, ir Jokūbu dangaus karalystėje.'),
  (@b40, 8, 12, 'Bet karalystės vaikai bus išmesti laukan į išorinę tamsą; ten bus verksmas ir dantų griežimas“.'),
  (@b40, 8, 13, 'Ir Jėzus tarė šimtininkui: „Eik; teįvyksta tau taip, kaip įtikėjai“. Ir jo tarnas buvo pagydytas tą pačią valandą.'),
  (@b40, 8, 14, 'Ir, kai Jėzus atėjo į Petro namus, jis pamatė jo žmonos motiną gulinčią ir sergančią karštine.'),
  (@b40, 8, 15, 'Ir jis palietė jos ranką, ir karštinė ją paliko; ir ji pakilo bei jiems patarnavo.'),
  (@b40, 8, 16, 'Kai atėjo vakaras, jie atvedė jam daug velniais apsėstųjų; ir jis išvarė dvasias savo žodžiu ir išgydė visus, kurie sirgo,'),
  (@b40, 8, 17, 'idant išsipildytų, kas buvo kalbėta pranašo Izaijo, sakant: „Jis pasiėmė mūsų negalias ir nešiojo mūsų ligas“.'),
  (@b40, 8, 18, 'Na, o kai Jėzus pamatė didžiules minias aplink jį, jis įsakė pasitraukti į kitą pusę.'),
  (@b40, 8, 19, 'Ir atėjo vienas raštininkas ir jam tarė: „Mokytojau, aš seksiu paskui tave, kur tik tu eisi“.'),
  (@b40, 8, 20, 'Ir Jėzus jam sako: „Lapės turi olas ir oro paukščiai lizdus; bet žmogaus Sūnus neturi kur priglausti savo galvos“.'),
  (@b40, 8, 21, 'Ir kitas iš jo mokinių jam tarė: „Viešpatie, leisk man pirmiau eiti ir palaidoti savo tėvą“.'),
  (@b40, 8, 22, 'Bet Jėzus jam tarė: „Sek paskui mane; ir tegul mirusieji laidoja savo mirusiuosius“.'),
  (@b40, 8, 23, 'Ir kai jis buvo įlipęs į laivą, jo mokiniai nusekė paskui jį.'),
  (@b40, 8, 24, 'Ir štai pakilo jūroje didžiulė audra taip, kad bangos dengė laivą; bet jis miegojo.'),
  (@b40, 8, 25, 'Ir jo mokiniai atėjo prie jo ir pažadino jį, sakydami: „Viešpatie, gelbėk mus – mes žūstame“.'),
  (@b40, 8, 26, 'Ir jis sako jiems: „Kodėl esate bailūs, o mažatikiai?“ Tada jis pakilo ir sudraudė vėjus bei jūrą; ir buvo didžiai ramu.'),
  (@b40, 8, 27, 'Bet žmonės stebėjosi, sakydami: „Kas tai per žmogus, kad netgi vėjai ir jūra jo klauso!?“'),
  (@b40, 8, 28, 'Ir kai jis atvyko į kitą pusę, į gergeziečių kraštą, ten jį pasitiko du velnių apsėstieji, išėję iš kapų, labai įniršę, taip, kad nei vienas žmogus negalėjo praeiti tuo keliu.'),
  (@b40, 8, 29, 'Ir štai jie šaukė, sakydami: „Kas mums su tavimi darbo, Jėzau, Dievo Sūnau? Ar čia atėjai mūsų kankinti pirma laiko?“'),
  (@b40, 8, 30, 'Ir ten toli nuo jų buvo banda daugybės besiganančių kiaulių.'),
  (@b40, 8, 31, 'Tad velniai maldavo jį, sakydami: „Jei tu mus išvarysi lauk, leisk mums įeiti į kiaulių bandą“.'),
  (@b40, 8, 32, 'Ir jis jiems tarė: „Eikite“. Ir kai jie išėjo, jie įėjo į kiaulių bandą; ir štai visa kiaulių banda galvotrūkčiais pasileido žemyn nuo stačios vietos į jūrą ir pražuvo vandenyse.'),
  (@b40, 8, 33, 'Ir tie, kurie jas ganė, pabėgo ir nuėjo sau į miestą, ir papasakojo viską ir kas atsitiko velnių apsėstiesiems.'),
  (@b40, 8, 34, 'Ir štai visas miestas išėjo pasitikti Jėzaus; ir kai jie pamatė jį, jie maldavo, kad jis išeitų iš jų ribų.'),
  (@b40, 9, 1, 'Ir jis įlipo į laivą ir persikėlė, ir atėjo į savąjį miestą.'),
  (@b40, 9, 2, 'Ir štai jie atnešė jam žmogų, sergantį paralyžiumi, gulintį ant patalo; ir Jėzus, matydamas jų tikėjimą, tarė sergančiam paralyžiumi: „Sūnau, pralinksmėk – tau atleidžiamos tavo nuodėmės“.'),
  (@b40, 9, 3, 'Ir štai kai kurie iš raštininkų sakė savyje: „Tas piktžodžiauja“.'),
  (@b40, 9, 4, 'Ir Jėzus, žinodamas jų mintis, tarė: „Kodėl galvojate pikta savo širdyse?'),
  (@b40, 9, 5, 'Nes kas yra lengviau – ar pasakyti: ‘Tau atleidžiamos tavo nuodėmės’, ar pasakyti: ‘Kelkis ir vaikščiok’?'),
  (@b40, 9, 6, 'Bet kad žinotumėte, jog žmogaus Sūnus turi valdžią žemėje atleisti nuodėmes (tuomet jis sako sergančiam paralyžiumi); kelkis, pasiimk savo patalą ir eik į savo namus“.'),
  (@b40, 9, 7, 'Ir jis atsikėlė ir išėjo į savo namus.'),
  (@b40, 9, 8, 'Bet kai minios tai pamatė, jie stebėjosi ir šlovino Dievą, davusį tokią galią žmonėms.'),
  (@b40, 9, 9, 'Ir iš ten išvykęs Jėzus pamatė žmogų, vardu Matas, sėdintį prie muito surinkimo; ir jis jam sako: „Sek paskui mane“. Ir jis atsikėlė ir sekė paskui jį.'),
  (@b40, 9, 10, 'Ir įvyko, kai Jėzus namuose sėdosi prie maisto, štai daug muitininkų ir nusidėjėlių atėjo ir sėdosi su juo ir jo mokiniais.'),
  (@b40, 9, 11, 'Ir kai fariziejai tai pamatė, jie tarė jo mokiniams: „Kodėl jūsų Mokytojas valgo su muitininkais ir nusidėjėliais?“'),
  (@b40, 9, 12, 'Bet kai Jėzus tai išgirdo, jis jiems pasakė: „Gydytojo nereikia sveikiems, bet tik sergantiems.'),
  (@b40, 9, 13, 'Bet eikite ir pasimokykite, ką reiškia: ‘Noriu pasigailėjimo, o ne aukos’; nes atėjau pašaukti atgailai ne teisiuosius, bet nusidėjėlius“.'),
  (@b40, 9, 14, 'Tada pas jį atėjo Jono mokiniai, sakydami: „Kodėl mes ir fariziejai dažnai pasninkaujame, o tavo mokiniai nepasninkauja?“'),
  (@b40, 9, 15, 'Ir Jėzus jiems tarė: „Ar gali vestuvių menės vaikai gedėti, kol su jais yra jaunikis? Bet ateis dienos, kai jaunikis bus iš jų atimtas, ir tada jie pasninkaus“.'),
  (@b40, 9, 16, '„Niekas nededa naujo audinio lopo ant seno drabužio, nes uždėtas lopinys tik atplėšia nuo drabužio, ir įplyšimas pablogėja.'),
  (@b40, 9, 17, 'Taip pat niekas nepila naujo vyno į senus indus, antraip indai pratrūksta, ir vynas išsilieja, ir indai pražūsta; bet jie pila naują vyną į naujus indus, ir abeji yra išsaugomi“.'),
  (@b40, 9, 18, 'Kol jis jiems tai kalbėjo, štai atėjo vienas valdovas ir jį pagarbino, sakydamas: „Mano dukra jau mirusi, bet ateik ir uždėk ant jos savo ranką, ir ji gyvens“.'),
  (@b40, 9, 19, 'Ir Jėzus atsikėlė ir nuėjo paskui jį, ir taip padarė jo mokiniai.'),
  (@b40, 9, 20, 'Ir štai moteris, dvylika metų serganti kraujoplūdžiu, priėjo jam iš paskos ir palietė jo drabužio apvadą,');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b40, 9, 21, 'nes ji tarė savyje: „Jei tik paliesiu jo drabužį, pagysiu“.'),
  (@b40, 9, 22, 'Bet Jėzus apsisuko ir pamatęs ją tarė: „Dukra, būk paguosta – tavo tikėjimas tave išgydė“. Ir nuo tos valandos moteris išgijo.'),
  (@b40, 9, 23, 'Ir kai Jėzus atėjo į valdovo namus ir pamatė vamzdininkus bei triukšmaujančią liaudį,'),
  (@b40, 9, 24, 'jis tarė jiems: „Duokite vietos, nes mergaitė ne mirusi, bet miega“. Ir jie išsijuokė iš jo.'),
  (@b40, 9, 25, 'Bet kai liaudis buvo išvaryta, jis įėjo vidun ir paėmė ją už rankos, ir mergaitė atsikėlė.'),
  (@b40, 9, 26, 'Ir garsas apie tai pasklido po visą tą šalį.'),
  (@b40, 9, 27, 'Ir kai Jėzus išėjo iš ten, du neregiai sekė paskui jį šaukdami ir sakydami: „Dovydo Sūnau, pasigailėk mūsų“.'),
  (@b40, 9, 28, 'Ir kai jis įėjo į namus, aklieji atėjo pas jį; ir Jėzus sako jiems: „Ar tikite, kad galiu tai padaryti?“ Jie tarė jam: „Taip, Viešpatie“.'),
  (@b40, 9, 29, 'Tada jis palietė jų akis, sakydamas: „Tebūna jums pagal jūsų tikėjimą“.'),
  (@b40, 9, 30, 'Ir jų akys atsivėrė; ir Jėzus juos griežtai įpareigojo, sakydamas: „Žiūrėkite, kad niekas šito nesužinotų“.'),
  (@b40, 9, 31, 'Bet jie išėję paskleidė garsą apie jį visame tame krašte.'),
  (@b40, 9, 32, 'Kai jie išėjo, štai jie atvedė pas jį velnio apsėstą nebylį.'),
  (@b40, 9, 33, 'Ir kai velnias buvo išvarytas, nebylys prakalbo; ir minios stebėjosi, sakydamos: „Taip dar niekada nebuvo matyta Izraelyje“.'),
  (@b40, 9, 34, 'Bet fariziejai tarė: „Jis išvarinėja velnius per velnių kunigaikštį“.'),
  (@b40, 9, 35, 'Ir Jėzus ėjo po visus miestus ir kaimus, mokydamas jų sinagogose ir skelbdamas karalystės evangeliją, ir gydydamas visas ligas bei visas negalias tautoje.'),
  (@b40, 9, 36, 'Bet kai jis pamatė minias, jam pagailo jų, nes jie buvo nusilpę ir išsisklaidę kaip avys neturinčios piemens.'),
  (@b40, 9, 37, 'Tuomet jis sako savo mokiniams: „Pjūtis iš tiesų didelė, bet darbininkų maža;'),
  (@b40, 9, 38, 'todėl melskite pjūties Viešpatį, kad jis išsiųstų darbininkų į savo pjūtį“.'),
  (@b40, 10, 1, 'Ir kai jis pasišaukė savo dvylika mokinių, jis davė jiems valdžią netyrosioms dvasioms, išvarinėti jas ir gydyti visokią ligą ir visokią negalią.'),
  (@b40, 10, 2, 'Na, o vardai dvylikos apaštalų yra šie: pirmasis – Simonas, kuris vadinamas Petru, ir jo brolis Andriejus; Zebediejaus sūnus Jokūbas ir jo brolis Jonas;'),
  (@b40, 10, 3, 'Pilypas ir Baltramiejus; Tomas ir muitininkas Matas; Alfiejaus sūnus Jokūbas ir Lebiejus, kurio pravardė buvo Tadas;'),
  (@b40, 10, 4, 'Simonas kanaanietis ir Judas Iskariotas, kuris taipogi išdavė jį.'),
  (@b40, 10, 5, 'Tuos dvylika Jėzus išsiuntė ir jiems įsakė, sakydamas: „Neikite į pagonių kelią ir neikite į jokį samariečių miestą;'),
  (@b40, 10, 6, 'bet verčiau eikite pas pražuvusias Izraelio namų avis.'),
  (@b40, 10, 7, 'Ir kai eisite, skelbkite sakydami: ‘Dangaus karalystė yra čia pat’.'),
  (@b40, 10, 8, 'Gydykite ligonius, apvalykite raupsuotuosius, prikelkite mirusiuosius, išvarinėkite velnius; dovanai gavote, dovanai duokite.'),
  (@b40, 10, 9, 'Neparūpinkite savo piniginėms nei aukso, nei sidabro, nei žalvario,'),
  (@b40, 10, 10, 'nei kelionmaišio savo kelionei, nei dviejų marškinių, nei batų, nei lazdos; nes darbininkas vertas savo maisto.'),
  (@b40, 10, 11, 'Ir įėję į kokį miestą ar miestelį teiraukitės, kas jame yra vertas; ir ten pasilikite, kol iš ten išeisite.'),
  (@b40, 10, 12, 'Ir kai įeisite į namus, pasveikinkite juos.'),
  (@b40, 10, 13, 'Ir jei namai bus verti, teateina jiems jūsų ramybė; bet jei jie nebūtų verti, tegul jūsų ramybė sugrįžta pas jus.'),
  (@b40, 10, 14, 'Ir jei kas jūsų nepriims nei neklausys jūsų žodžių, tai jūs, išeidami iš šitų namų ar miesto, nusipurtykite dulkes nuo kojų.'),
  (@b40, 10, 15, 'Iš tiesų sakau jums: Sodomos ir Gomoros šaliai bus daug pakenčiamiau teismo dieną negu tam miestui.'),
  (@b40, 10, 16, 'Štai išsiunčiu jus kaip avis į tarpą vilkų; todėl būkite gudrūs kaip gyvatės ir nekenksmingi kaip balandžiai.'),
  (@b40, 10, 17, 'Bet saugokitės žmonių; nes jie atiduos jus taryboms ir jie plaks jus savo sinagogose;'),
  (@b40, 10, 18, 'ir dėl manęs jus vedžios valdytojų ir karalių akivaizdon dėl liudijimo prieš juos ir pagonis.'),
  (@b40, 10, 19, 'Bet kai jie jus įduos, nesirūpinkite, kaip ar ką kalbėsite, nes tą valandą jums bus duota, ką turėsite kalbėti.'),
  (@b40, 10, 20, 'Nes tai ne jūs, kurie kalbate, bet jūsų Tėvo Dvasia, kuri kalba jumyse.'),
  (@b40, 10, 21, 'Ir brolis įduos brolį mirčiai, ir tėvas vaiką; ir vaikai sukils prieš savo tėvus ir darys, kad juos paduotų mirčiai.'),
  (@b40, 10, 22, 'Ir dėl mano vardo jūsų nekęs visi; bet tas, kuris ištvers iki galo, bus išgelbėtas.'),
  (@b40, 10, 23, 'Bet kai jie persekios jus šiame mieste, bėkite į kitą; nes iš tiesų sakau jums: jūs nebūsite apėję Izraelio miestų, kol ateis žmogaus Sūnus.'),
  (@b40, 10, 24, 'Mokinys nėra aukštesnis už savo mokytoją nei tarnas aukštesnis už savo viešpatį.'),
  (@b40, 10, 25, 'Pakanka mokiniui, kad jis būtų kaip jo mokytojas, ir tarnui – kaip jo viešpats. Jei namų šeimininką jie vadino Belzebubu, tai kaip juo labiau nevadins jo namiškių?'),
  (@b40, 10, 26, 'Todėl nebijokite jų; nes nieko nėra uždengta, kas nebūtų atskleista; ir paslėpta, kas nebūtų sužinota.'),
  (@b40, 10, 27, 'Ką jums sakau tamsoje, kalbėkite tai šviesoje; ir ką girdėjote į ausį, tai skelbkite ant namų stogų.'),
  (@b40, 10, 28, 'Ir nebijokite tų, kurie nužudo kūną, bet negali nužudyti sielos; bet verčiau bijokite to, kuris gali sunaikinti ir sielą, ir kūną pragare.'),
  (@b40, 10, 29, 'Argi ne du žvirbliai parduodami už asą? Ir nei vienas iš jų nekris žemėn be jūsų Tėvo.'),
  (@b40, 10, 30, 'Bet visi jūsų galvos plaukai yra suskaičiuoti.'),
  (@b40, 10, 31, 'Todėl nebijokite – jūs vertesni už daugybę žvirblių.'),
  (@b40, 10, 32, 'Todėl kas išpažins mane žmonių akivaizdoje, tą ir aš išpažinsiu akivaizdoje savo Tėvo, kuris yra danguje.'),
  (@b40, 10, 33, 'Bet kas išsigins manęs žmonių akivaizdoje, to ir aš išsiginsiu akivaizdoje savo Tėvo, kuris yra danguje.'),
  (@b40, 10, 34, 'Negalvokite, kad esu atėjęs siųsti į žemę taiką; atėjau siųsti ne taiką, bet kalaviją.'),
  (@b40, 10, 35, 'Nes esu atėjęs sukiršinti žmogaus prieš savo tėvą ir dukters prieš savo motiną, ir marčios prieš savo anytą.'),
  (@b40, 10, 36, 'Ir žmogaus priešai bus jo namiškiai.'),
  (@b40, 10, 37, 'Kas myli tėvą ar motiną labiau už mane, tas nevertas manęs; ir kas myli sūnų ar dukterį labiau už mane, tas nevertas manęs.'),
  (@b40, 10, 38, 'Ir kas neima savo kryžiaus ir neseka paskui mane, tas nevertas manęs.'),
  (@b40, 10, 39, 'Kas atranda savo gyvybę, ją praras, o kas praranda savo gyvybę dėl manęs, tas ją atras“.'),
  (@b40, 10, 40, '„Kas priima jus, priima mane, o kas priima mane, priima tą, kuris mane siuntė.'),
  (@b40, 10, 41, 'Kas priima pranašą vardan pranašo, tas gaus pranašo atlygį; o kas priima teisųjį vardan teisiojo, tas gaus teisiojo atlygį.'),
  (@b40, 10, 42, 'Ir kas duos atsigerti bent taurę šalto vandens vienam iš tų mažųjų vardan mokinio, iš tiesų sakau jums, tas jokiu būdu nepraras savo atlygio“.'),
  (@b40, 11, 1, 'Ir įvyko, kai Jėzus baigė duoti įsakymus savo dvylikai mokinių, jis iš ten išvyko mokyti ir skelbti jų miestuose.'),
  (@b40, 11, 2, 'Na, o Jonas, kalėjime išgirdęs apie Kristaus darbus, pasiuntė du iš savo mokinių'),
  (@b40, 11, 3, 'ir tarė jam: „Ar tu tas, kuris turi ateiti, ar mums laukti kito?“'),
  (@b40, 11, 4, 'Jėzus atsakydamas tarė jiems: „Eikite ir vėl praneškite Jonui tai, ką girdite ir matote:'),
  (@b40, 11, 5, 'aklieji praregi ir raišieji vaikšto, raupsuotieji yra apvalomi ir kurtieji girdi, mirusieji yra prikeliami ir vargšams skelbiama evangelija.'),
  (@b40, 11, 6, 'Ir palaimintas yra tas, kuris nepasipiktins manimi“.'),
  (@b40, 11, 7, 'Ir jiems nuėjus Jėzus pradėjo kalbėti minioms apie Joną: „Ko išėjote į dykumą pamatyti? Ar vėjo linguojamos nendrės?'),
  (@b40, 11, 8, 'Bet ko išėjote pamatyti? Ar švelniais drabužiais vilkinčio žmogaus? Štai tie, kurie vilki švelniais drabužiais, yra karalių namuose.'),
  (@b40, 11, 9, 'Bet ko išėjote pamatyti? Pranašo? Taip, sakau jums, ir daugiau negu pranašo.'),
  (@b40, 11, 10, 'Nes jis yra tas, apie kurį yra parašyta: ‘Štai siunčiu savo pasiuntinį pirma tavo veido, kuris paruoš tavo kelią pirma tavęs’.'),
  (@b40, 11, 11, 'Iš tiesų sakau jums: tarp gimusių iš moterų nėra kilusio didesnio nei Jonas Krikštytojas; tačiau tas, kuris mažiausias dangaus karalystėje, yra didesnis už jį.'),
  (@b40, 11, 12, 'Ir nuo Jono Krikštytojo dienų iki dabar dangaus karalystė kenčia smurtą, ir smurtininkai ją ima jėga.'),
  (@b40, 11, 13, 'Nes visi pranašai ir įstatymas pranašavo iki Jono.'),
  (@b40, 11, 14, 'Ir jei tai norite priimti, šis yra Elijas, kuris turėjo ateiti.'),
  (@b40, 11, 15, 'Kas turi ausis klausyti, tegul klauso“.'),
  (@b40, 11, 16, '„Bet kam aš prilyginsiu šią kartą? Ji prilygsta vaikams, sėdintiems turguose ir šaukiantiems savo draugams,'),
  (@b40, 11, 17, 'ir sakantiems: ‘Mes jums dūdavome, o jūs nešokote; mes jums raudojome, o jūs neverkėte’.'),
  (@b40, 11, 18, 'Nes atėjo Jonas – nei valgantis, nei geriantis, ir jie sako: ‘Jis turi velnią’.'),
  (@b40, 11, 19, 'Atėjo žmogaus Sūnus – valgantis ir geriantis, ir jie sako: ‘Štai žmogus rijūnas ir vyno gėrėjas, muitininkų ir nusidėjėlių draugas’. Bet išmintis yra išteisinta jos vaikų“.'),
  (@b40, 11, 20, 'Tada jis pradėjo priekaištauti miestams, kuriuose buvo daugiausia padaryta jo galingų darbų, kadangi jie neatgailavo:'),
  (@b40, 11, 21, '„Vargas tau, Chorazine! Vargas tau, Betsaida! Nes jei galingi darbai, kurie buvo padaryti jumyse, būtų buvę padaryti Tyre ir Sidone, tai jie seniai būtų atgailavę ašutinėje ir pelenuose.'),
  (@b40, 11, 22, 'Bet sakau jums: Tyrui ir Sidonui teismo dieną bus daug pakenčiamiau negu jums.'),
  (@b40, 11, 23, 'Ir tu, Kafernaume, kuris esi išaukštintas iki dangaus, būsi nugramzdintas į pragarą; nes jei galingi darbai, kurie buvo padaryti tavyje, būtų buvę padaryti Sodomoje, ji iki šios dienos būtų išlikusi.'),
  (@b40, 11, 24, 'Bet sakau jums, kad Sodomos šaliai teismo dieną bus daug pakenčiamiau negu tau“.'),
  (@b40, 11, 25, 'Anuo metu Jėzus atsakydamas tarė: „Dėkoju tau, o Tėve, dangaus ir žemės Viešpatie, nes paslėpei tai nuo išmintingųjų bei protingųjų ir atskleidei tai kūdikiams.'),
  (@b40, 11, 26, 'Būtent taip, Tėve, nes taip atrodė gera tavo akyse.'),
  (@b40, 11, 27, 'Viskas yra man atiduota mano Tėvo; ir niekas nepažįsta Sūnaus, o tik Tėvas; ir nei Tėvo niekas nepažįsta, o tik Sūnus ir tas, kuriam Sūnus nori jį apreikšti“.'),
  (@b40, 11, 28, '„Ateikite pas mane visi, kurie triūsiate ir esate sunkiai apkrauti, ir aš jums duosiu poilsį.'),
  (@b40, 11, 29, 'Imkite ant savęs mano jungą ir mokykitės iš manęs; nes esu romus ir nuolankios širdies; ir jūs rasite poilsį savo sieloms.'),
  (@b40, 11, 30, 'Nes mano jungas nesunkus, ir mano našta yra lengva“.'),
  (@b40, 12, 1, 'Anuo metu Jėzus sabato dieną ėjo per javus; ir jo mokiniai buvo išalkę ir pradėjo skinti javų varpas bei valgyti.'),
  (@b40, 12, 2, 'Bet kai fariziejai tai pamatė, jie tarė jam: „Štai tavo mokiniai daro tai, ką neteisėta daryti sabato dieną“.'),
  (@b40, 12, 3, 'Bet jis jiems tarė: „Ar neskaitėte, ką padarė Dovydas, kai buvo išalkęs jis ir tie, kurie buvo su juo;'),
  (@b40, 12, 4, 'kaip jis įėjo į Dievo namus ir valgė parodomos duonos, kurios nebuvo teisėta valgyti nei jam, nei tiems, kurie buvo su juo, bet vien tik kunigams?'),
  (@b40, 12, 5, 'Arba negi neskaitėte įstatyme, kaip kunigai sabato dienomis šventykloje suteršia sabatą ir yra nekalti?'),
  (@b40, 12, 6, 'Bet aš jums sakau, kad šioje vietoje yra vienas didesnis nei šventykla.'),
  (@b40, 12, 7, 'Bet jei būtumėte žinoję, ką reiškia ‘Noriu pasigailėjimo, o ne aukos’, nebūtumėte pasmerkę nekaltų.'),
  (@b40, 12, 8, 'Nes žmogaus Sūnus yra ir sabato dienos Viešpats“.'),
  (@b40, 12, 9, 'Ir iš ten išėjęs jis nuėjo į jų sinagogą;'),
  (@b40, 12, 10, 'ir štai ten buvo žmogus, kuris turėjo nudžiūvusią ranką. Ir jie paklausė jo, sakydami: „Ar teisėta gydyti sabato dienomis?“ – kad galėtų jį apkaltinti.'),
  (@b40, 12, 11, 'Ir jis jiems tarė: „Kuris tarp jūsų, turėdamas vieną avį, jeigu ji įkristų į duobę per sabato dieną, jos nenutvertų ir neiškeltų?'),
  (@b40, 12, 12, 'Tad kiek daugiau žmogus yra geresnis už avį? Todėl teisėta daryti gera sabato dienomis“.'),
  (@b40, 12, 13, 'Tuomet jis sako žmogui: „Ištiesk savo ranką“. Ir jis ją ištiesė; ir ji buvo atstatyta sveika kaip ir kita.'),
  (@b40, 12, 14, 'Tada fariziejai išėjo ir tarėsi prieš jį, kaip jie galėtų jį sunaikinti.'),
  (@b40, 12, 15, 'Bet kai Jėzus tai sužinojo, jis iš ten pasitraukė; ir didžiulės minios sekė paskui jį, ir jis juos visus išgydė;'),
  (@b40, 12, 16, 'ir įpareigojo juos, kad jie jo negarsintų,'),
  (@b40, 12, 17, 'kad išsipildytų tai, kas buvo kalbėta pranašo Izaijo, sakant:'),
  (@b40, 12, 18, '„Štai mano tarnas, kurį išsirinkau; mano mylimasis, kuriuo labai patenkinta mano siela; aš uždėsiu ant jo savo Dvasią, ir jis praneš pagonims teismą.'),
  (@b40, 12, 19, 'Jis nesiginčys nei šauks; ir niekas negirdės jo balso gatvėse.'),
  (@b40, 12, 20, 'Jis nenulauš pažeistos nendrės ir neužgesins rūkstančio lino, kol nepasiųs teismo link pergalės.'),
  (@b40, 12, 21, 'Ir jo vardu pagonys pasitikės“.'),
  (@b40, 12, 22, 'Tada pas jį atvedė vieną velnio apsėstą – aklą ir nebylų; ir jis išgydė jį taip, kad aklas ir nebylus kalbėjo ir regėjo.'),
  (@b40, 12, 23, 'Ir visa tauta stebėjosi ir sakė: „Ar ne šis yra Dovydo sūnus?“'),
  (@b40, 12, 24, 'Bet kai fariziejai tai išgirdo, jie sakė: „Šitas išvaro velnius ne kitaip, kaip tik per velnių kunigaikštį Belzebubą“.'),
  (@b40, 12, 25, 'Ir Jėzus žinojo jų mintis ir tarė jiems: „Kiekviena karalystė, pasidalijusi prieš save, tampa suniokota; ir kiekvienas miestas ar namai, pasidaliję prieš save, neišstovės;'),
  (@b40, 12, 26, 'ir jei šėtonas išvaro šėtoną, jis yra pasidalijęs prieš save; kaipgi tada išstovės jo karalystė?'),
  (@b40, 12, 27, 'Ir jei aš išvarinėju velnius per Belzebubą, per ką jūsų vaikai juos išvarinėja? Todėl jie bus jūsų teisėjai.'),
  (@b40, 12, 28, 'Bet jei išvarinėju velnius Dievo Dvasia, tuomet pas jus atėjo Dievo karalystė.'),
  (@b40, 12, 29, 'Arba kaipgi gali kas įeiti į stipruolio namus ir išplėšti jo turtą pirmiau nesurišęs stipruolio? Tik tada jis išplėš jo namus.'),
  (@b40, 12, 30, 'Kas ne su manimi, tas prieš mane; ir kas nerenka su manimi, tas barsto“.'),
  (@b40, 12, 31, '„Todėl sakau jums: visokia nuodėmė ir piktžodžiavimas bus žmonėms atleisti, bet piktžodžiavimas Šventajai Dvasiai nebus žmonėms atleistas.'),
  (@b40, 12, 32, 'Ir kas kalba žodį prieš žmogaus Sūnų, tam bus atleista; bet jei kas kalba prieš Šventąją Dvasią, tam nebus atleista nei šiame, nei ateinančiame pasaulyje.'),
  (@b40, 12, 33, 'Arba darykite medį gerą ir jo vaisių gerą; arba darykite medį sugedusį ir jo vaisių sugedusį; nes medis yra pažįstamas iš jo vaisiaus.'),
  (@b40, 12, 34, 'O angių palikuonys, kaipgi jūs, būdami pikti, galite kalbėti gera? Nes burna kalba iš to, ko pertekusi širdis.'),
  (@b40, 12, 35, 'Geras žmogus iš gero širdies lobyno atneša gera, o piktas žmogus iš pikto lobyno atneša pikta.'),
  (@b40, 12, 36, 'Bet aš sakau jums, kad už kiekvieną tuščią žodį, kurį žmonės kalbės, jie duos ataskaitą teismo dieną.'),
  (@b40, 12, 37, 'Nes pagal savo žodžius būsi išteisintas ir pagal savo žodžius būsi pasmerktas“.'),
  (@b40, 12, 38, 'Tada kai kurie iš raštininkų ir fariziejų atsakė, tardami: „Mokytojau, norėtume pamatyti iš tavęs ženklą“.'),
  (@b40, 12, 39, 'Bet jis atsakydamas tarė jiems: „Pikta ir svetimaujanti karta ieško ženklo; bet nebus jai duota ženklo, o tik pranašo Jonos ženklas;'),
  (@b40, 12, 40, 'nes kaip Jona buvo tris dienas ir tris naktis banginio pilve, taip ir žmogaus Sūnus bus tris dienas ir tris naktis žemės širdyje.'),
  (@b40, 12, 41, 'Ninevės žmonės kelsis su šia karta į teismą ir ją pasmerks, nes jie atgailavo skelbiant Jonai; o štai čia yra didesnis negu Jona.'),
  (@b40, 12, 42, 'Pietų karalienė kelsis su šia karta į teismą ir ją pasmerks, nes ji atėjo iš tolimiausių žemės pakraščių pasiklausyti Saliamono išminties; o štai čia yra didesnis negu Saliamonas.'),
  (@b40, 12, 43, 'Kai netyroji dvasia yra išėjusi iš žmogaus, ji vaikšto per sausas vietas ieškodama poilsio ir neranda.'),
  (@b40, 12, 44, 'Tada ji sako: ‘Sugrįšiu į savo namus, iš kurių išėjau’; ir kai ji ateina, ji randa juos tuščius, iššluotus ir išpuoštus.'),
  (@b40, 12, 45, 'Tuomet ji eina ir pasiima su savimi kitas septynias už save nedoresnes dvasias, ir jos įeina ir ten apsigyvena; ir galutinė to žmogaus būsena yra blogesnė nei pirmoji. Lygiai taip pat bus ir šitai nedorai kartai“.'),
  (@b40, 12, 46, 'Jam dar bekalbant tautai, štai jo motina ir jo broliai stovėjo lauke, norėdami su juo pasikalbėti.'),
  (@b40, 12, 47, 'Tada vienas tarė jam: „Štai tavo motina ir tavo broliai stovi lauke, norėdami su tavimi pasikalbėti“.'),
  (@b40, 12, 48, 'Bet tam, kuris jam pasakė, jis atsakydamas tarė: „Kas yra mano motina? Ir kas yra mano broliai?“'),
  (@b40, 12, 49, 'Ir jis ištiesė savo ranką į savo mokinius ir tarė: „Štai mano motina ir mano broliai!'),
  (@b40, 12, 50, 'Nes kas vykdys valią mano Tėvo, kuris yra danguje, tas yra mano brolis ir sesuo, ir motina“.'),
  (@b40, 13, 1, 'Tą pačią dieną Jėzus išėjo iš namų ir atsisėdo palei jūrą.'),
  (@b40, 13, 2, 'Ir didžiulės minios susirinko pas jį taip, kad jis įėjo į laivą ir atsisėdo; o visa minia stovėjo ant kranto.'),
  (@b40, 13, 3, 'Ir daug jis kalbėjo jiems palyginimais, sakydamas: „Štai sėjėjas išėjo sėti;'),
  (@b40, 13, 4, 'ir kai jis sėjo, kai kurios sėklos nukrito palei kelią, ir atskrido skrajūnai ir jas prarijo;'),
  (@b40, 13, 5, 'kai kurios nukrito į akmenuotas vietas, kur jos turėjo nedaug žemės; ir jos tuojau išdygo, nes neturėjo žemės gilumo;'),
  (@b40, 13, 6, 'ir kai saulė pakilo, jos išdegė; ir kadangi jos neturėjo šaknies, jos nudžiūvo.'),
  (@b40, 13, 7, 'ir kai kurios nukrito tarp erškėčių; ir erškėčiai išdygo ir jas nusmelkė;'),
  (@b40, 13, 8, 'bet kitos nukrito į gerą žemę ir atnešė vaisių: vienos šimteriopą, vienos šešiasdešimteriopą, vienos trisdešimteriopą.'),
  (@b40, 13, 9, 'Kas turi ausis klausyti, tas teklauso“.'),
  (@b40, 13, 10, 'Ir atėjo mokiniai ir jam tarė: „Kodėl jiems kalbi palyginimais?“'),
  (@b40, 13, 11, 'Jis atsakydamas tarė jiems: „Kadangi jums yra duota pažinti dangaus karalystės paslaptis, bet jiems nėra duota.'),
  (@b40, 13, 12, 'Nes kas turi, tam bus duota, ir jis turės dar gausiau; bet kas neturi, iš to bus atimta net ir tai, ką jis turi.'),
  (@b40, 13, 13, 'Todėl jiems kalbu palyginimais; nes matydami jie nemato ir girdėdami jie negirdi nei nesupranta.'),
  (@b40, 13, 14, 'Ir juose išsipildė Izaijo pranašystė, kuri sako: ‘Girdėdami jūs girdėsite ir nesuprasite; ir žiūrėdami jūs žiūrėsite ir nepastebėsite;'),
  (@b40, 13, 15, 'nes šitos tautos širdis nutuko, ir jų ausys sunkiai girdi, ir jie užmerkė savo akis; idant kuriuo metu nepamatytų savo akimis ir neišgirstų savo ausimis, ir nesuprastų savo širdimi, ir neatsiverstų, ir aš jų neišgydyčiau’.'),
  (@b40, 13, 16, 'Bet palaimintos jūsų akys, nes jos mato; ir jūsų ausys, nes jos girdi.'),
  (@b40, 13, 17, 'Nes iš tiesų sakau jums, kad daug pranašų ir teisiųjų troško pamatyti tai, ką jūs matote, bet nematė; ir išgirsti tai, ką jūs girdite, bet negirdėjo“.'),
  (@b40, 13, 18, '„Todėl klausykite palyginimo apie sėjėją.'),
  (@b40, 13, 19, 'Kada kas klauso karalystės žodį ir jo nesupranta, tada ateina tas nedorėlis ir išplėšia tai, kas buvo pasėta jo širdyje. Tai yra tas, kuris priėmė sėklą palei kelią.'),
  (@b40, 13, 20, 'Bet tas, kuris priėmė sėklą akmenuotose vietose, yra tas, kuris girdi žodį ir tuojau pat su džiaugsmu jį priima;'),
  (@b40, 13, 21, 'tačiau jis neturi savyje šaknies ir tėra trumpalaikis; nes kai dėl žodžio iškyla suspaudimas ar persekiojimas, jis tuoj pat pasipiktina.'),
  (@b40, 13, 22, 'Ir tas, kuris priėmė sėklą tarp erškėčių, yra tas, kuris girdi žodį; bet šio pasaulio rūpesčiai ir turtų apgaulė nusmelkia žodį, ir jis tampa nevaisingas.'),
  (@b40, 13, 23, 'Bet tas, kuris priėmė sėklą į gerą žemę, yra tas, kuris girdi žodį ir jį supranta; kuris taip pat neša vaisių, ir duoda vieni šimteriopą, vieni šešiasdešimteriopą, vieni trisdešimteriopą“.'),
  (@b40, 13, 24, 'Kitą palyginimą jis jiems pateikė, sakydamas: „Dangaus karalystė prilygsta žmogui, kuris pasėjo gerą sėklą savo lauke;'),
  (@b40, 13, 25, 'bet kol žmonės miegojo, atėjo jo priešas ir pasėjo svidres tarp kviečių, ir nuėjo.'),
  (@b40, 13, 26, 'Bet kai želmuo išdygo ir atnešė vaisių, tuomet ir svidrės pasirodė.'),
  (@b40, 13, 27, 'Tai namų šeimininko tarnai atėjo ir tarė jam: ‘Pone, argi nepasėjai geros sėklos savo lauke? Tad iš kur ėmėsi svidrės?’'),
  (@b40, 13, 28, 'Jis jiems tarė: ‘Priešas tai padarė’. Tarnai jam tarė: ‘Tad ar nori, kad nueitume ir jas išrinktume?’'),
  (@b40, 13, 29, 'Bet jis tarė: ‘Ne; kad kartais, išrinkinėdami svidres neišrautumėte su jomis ir kviečių.'),
  (@b40, 13, 30, 'Tegul abeji auga kartu iki pjūties; o pjūties metu aš pasakysiu pjovėjams: ‘Pirmiau surinkite svidres ir suriškite jas į kūlelius sudeginimui; bet kviečius surinkite į mano kluoną’“.'),
  (@b40, 13, 31, 'Jis pateikė jiems kitą palyginimą, sakydamas: „Dangaus karalystė prilygsta garstyčios sėklos grūdeliui, kurį žmogus ėmė ir pasėjo savo lauke;'),
  (@b40, 13, 32, 'kuris iš tikro yra mažiausias iš visų sėklų; bet užaugęs jis yra didžiausias tarp žolių ir tampa medžiu taip, kad oro paukščiai atskrenda ir apsigyvena jo šakose“.'),
  (@b40, 13, 33, 'Jis pasakė jiems kitą palyginimą: „Dangaus karalystė prilygsta raugui, kurį ėmė moteris ir paslėpė trijuose saikuose miltų, kol viskas įrūgo“.'),
  (@b40, 13, 34, 'Visa tai Jėzus kalbėjo miniai palyginimais; ir be palyginimo jis jiems nekalbėjo;'),
  (@b40, 13, 35, 'kad išsipildytų, kas buvo kalbėta per pranašą, sakant: „Atversiu savo burną palyginimais; ištarsiu tai, kas buvo paslėpta nuo pasaulio įkūrimo“.'),
  (@b40, 13, 36, 'Tada Jėzus paleido minią ir nuėjo į namus; ir jo mokiniai atėjo pas jį, sakydami: „Išaiškink mums palyginimą apie lauko svidres“.'),
  (@b40, 13, 37, 'Jis atsakydamas tarė jiems: „Tas, kuris sėja gerą sėklą, yra žmogaus Sūnus;'),
  (@b40, 13, 38, 'laukas yra pasaulis; gera sėkla yra karalystės vaikai; bet svidrės yra to nedorėlio vaikai;'),
  (@b40, 13, 39, 'priešas, kuris jas pasėjo, yra velnias; pjūtis yra pasaulio pabaiga; o pjovėjai yra angelai.'),
  (@b40, 13, 40, 'Taigi kaip yra surenkamos svidrės ir sudeginamos ugnyje, taip bus ir šio pasaulio pabaigoje.'),
  (@b40, 13, 41, 'Žmogaus Sūnus pasiųs savo angelus, ir jie išrinks iš jo karalystės visa, kas piktina, ir darančiuosius neteisybę;'),
  (@b40, 13, 42, 'ir įmes juos į ugnies krosnį; ten bus kauksmas ir dantų griežimas.'),
  (@b40, 13, 43, 'Tada teisieji spindės kaip saulė savo Tėvo karalystėje. Kas turi ausis klausyti, tas teklauso“.'),
  (@b40, 13, 44, '„Vėlgi, dangaus karalystė prilygsta lauke paslėptam lobiui; kurį žmogus atradęs paslepia ir iš džiaugsmo dėl jo eina ir parduoda viską, ką turi, ir nusiperka tą lauką“.'),
  (@b40, 13, 45, '„Vėlgi, dangaus karalystė prilygsta pirkliui, ieškančiam gražių perlų;'),
  (@b40, 13, 46, 'kuris, atradęs vieną labai brangų perlą, nuėjo ir pardavė viską, ką turėjo, ir nusipirko jį“.'),
  (@b40, 13, 47, '„Vėlgi, dangaus karalystė prilygsta tinklui, kuris buvo įmestas į jūrą ir užgriebė visokių rūšių;'),
  (@b40, 13, 48, 'kurį, kai jis buvo pilnas, jie išvilko į krantą ir susėdo, ir surinko geras į indus, bet blogas numetė šalin.'),
  (@b40, 13, 49, 'Taip bus pasaulio pabaigoje: išeis angelai ir atskirs nedorėlius iš teisiųjų tarpo,'),
  (@b40, 13, 50, 'ir įmes juos į ugnies krosnį; ten bus kauksmas ir dantų griežimas“.'),
  (@b40, 13, 51, 'Jėzus jiems sako: „Ar supratote visa tai?“ Jie sako jam: „Taip, Viešpatie“.'),
  (@b40, 13, 52, 'Tada jis jiems tarė: „Todėl kiekvienas raštininkas, išmokytas dangaus karalystei, prilygsta žmogui, kuris yra namų šeimininkas, kuris išneša iš savo lobyno nauja ir sena“.'),
  (@b40, 13, 53, 'Ir įvyko, kai Jėzus baigė šiuos palyginimus, jis iš ten išėjo.'),
  (@b40, 13, 54, 'Ir kai jis atvyko į savo tėviškę, jis mokė juos jų sinagogoje taip, kad jie stebėjosi ir sakė: „Iš kur šitas turi šią išmintį ir šiuos galingus darbus?'),
  (@b40, 13, 55, 'Argi šis ne dailidės sūnus? Argi ne jo motina vadinama Marija? O jo broliai – Jokūbas ir Jozė, ir Simonas, ir Judas?'),
  (@b40, 13, 56, 'Ir jo seserys, argi ne jos visos su mumis? Tad iš kur šitas turi visa tai?“'),
  (@b40, 13, 57, 'Ir jie pasipiktino juo. Bet Jėzus jiems tarė: „Pranašas nebūna be pagarbos, išskyrus savo tėviškėje ir savo namuose“.'),
  (@b40, 13, 58, 'Ir jis ten nedarė daug galingų darbų dėl jų netikėjimo.'),
  (@b40, 14, 1, 'Anuo metu tetrarchas Erodas išgirdo garsą apie Jėzų'),
  (@b40, 14, 2, 'ir tarė savo tarnams: „Tai – Jonas Krikštytojas – jis yra prisikėlęs iš numirusiųjų; ir todėl jame pasirodo galingi darbai“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b40, 14, 3, 'Nes Erodas buvo sučiupęs Joną, jį surišęs ir įmetęs į kalėjimą dėl Erodijos, savo brolio Pilypo žmonos.'),
  (@b40, 14, 4, 'Nes Jonas jam sakė: „Tau neteisėta jos turėti“.'),
  (@b40, 14, 5, 'Ir kai jis norėjo jį užmušti, jis pabijojo minios, nes jie laikė jį pranašu.'),
  (@b40, 14, 6, 'Bet kai buvo švenčiamas Erodo gimtadienis, Erodijos duktė šoko prieš juos ir patiko Erodui.'),
  (@b40, 14, 7, 'Dėl to jis su priesaika pažadėjo jai duoti ko tik ji beprašytų.'),
  (@b40, 14, 8, 'Ir ji, prieš tai pamokyta savo motinos, tarė: „Duok man čia dubenyje Jono Krikštytojo galvą“.'),
  (@b40, 14, 9, 'Ir karalius nuliūdo; tačiau dėl priesaikos ir dėl tų, kurie su juo sėdėjo prie maisto, jis įsakė tai jai duoti.'),
  (@b40, 14, 10, 'Ir jis pasiuntė ir nukirsdino Jonui galvą kalėjime.'),
  (@b40, 14, 11, 'Ir jo galva buvo atnešta dubenyje ir paduota tai panelei; ir ji nunešė tai savo motinai.'),
  (@b40, 14, 12, 'Ir atėjo jo mokiniai, pasiėmė kūną, palaidojo jį ir nuėjo bei pasakė Jėzui.'),
  (@b40, 14, 13, 'Kai Jėzus tai išgirdo, jis išvyko iš ten laivu nuošalėn į dykvietę; ir kai tauta apie tai išgirdo, jie iš miestų nusekė paskui jį pėsčiomis.'),
  (@b40, 14, 14, 'Ir Jėzus išėjo ir pamatė didžiulę minią, ir buvo apimtas gailesčio jiems, ir jis išgydė jų ligonius.'),
  (@b40, 14, 15, 'Ir kai buvo vakaras, pas jį atėjo jo mokiniai, sakydami: „Čia yra dykvietė, ir jau yra praėję laiko; paleisk minią, kad jie nueitų į kaimus ir nusipirktų sau maisto“.'),
  (@b40, 14, 16, 'Bet Jėzus tarė jiems: „Jiems nereikia išeiti; jūs duokite jiems valgyti“.'),
  (@b40, 14, 17, 'Ir jie sako jam: „Mes čia turime tik penkis kepalus ir dvi žuvis“.'),
  (@b40, 14, 18, 'Jis tarė: „Atneškite čia man juos“.'),
  (@b40, 14, 19, 'Ir jis įsakė miniai susėsti ant žolės ir paėmė penkis kepalus bei dvi žuvis, ir žiūrėdamas į dangų jis palaimino ir laužė, ir davė kepalus savo mokiniams, o mokiniai – miniai.'),
  (@b40, 14, 20, 'Ir jie visi valgė ir pasisotino; ir jie pririnko dvylika pilnų pintinių likusių nuolaužų.'),
  (@b40, 14, 21, 'Ir tų, kurie valgė, buvo apie penkis tūkstančius vyrų, neskaitant moterų ir vaikų.'),
  (@b40, 14, 22, 'Ir tuoj pat Jėzus privertė savo mokinius lipti į laivą ir pirma jo plaukti į kitą pusę, kol jis paleidinėjo minias.'),
  (@b40, 14, 23, 'Ir paleidęs minias, jis užkopė nuošaliai į kalną melstis; ir kai atėjo vakaras, jis ten buvo vienas.'),
  (@b40, 14, 24, 'Bet laivas jau buvo jūros viduryje, blaškomas bangų, nes vėjas buvo priešpriešis.'),
  (@b40, 14, 25, 'Ir per ketvirtą nakties budėjimą Jėzus ėjo pas juos žingsniuodamas jūra.'),
  (@b40, 14, 26, 'Ir kai mokiniai pamatė jį einantį jūra, jie sunerimo sakydami: „Tai dvasia“; ir jie šaukė iš baimės.'),
  (@b40, 14, 27, 'Bet Jėzus tuojau tarė jiems, sakydamas: „Pralinksmėkite; tai aš – nebijokite“.'),
  (@b40, 14, 28, 'Ir Petras jam atsakydamas tarė: „Viešpatie, jei tai tu, liepk man ateiti pas tave vandeniu“.'),
  (@b40, 14, 29, 'Ir jis tarė: „Ateik“. Ir kai Petras išlipo iš laivo, jis ėjo vandeniu, kad nueitų pas Jėzų“.'),
  (@b40, 14, 30, 'Bet kai jis pamatė smarkų vėją, jis išsigando; ir pradėjęs skęsti jis šaukė, sakydamas: „Viešpatie, gelbėk mane“.'),
  (@b40, 14, 31, 'Ir tuojau Jėzus ištiesė savo ranką ir pagavo jį bei tarė jam: „O mažatiki, kodėl abejojai?“'),
  (@b40, 14, 32, 'Ir jiems įėjus į laivą vėjas nurimo.'),
  (@b40, 14, 33, 'Tuomet tie, kurie buvo laive, atėjo ir pagarbino jį, sakydami: „Iš tiesų tu esi Dievo Sūnus“.'),
  (@b40, 14, 34, 'Ir perplaukę jie atvyko į Genezareto šalį.'),
  (@b40, 14, 35, 'Ir kai tos vietos žmonės pažino jį, jie pasiuntė į visą tą aplinkinį kraštą ir atnešė jam visus sergančius;'),
  (@b40, 14, 36, 'ir maldavo jo, kad jie galėtų bent paliesti jo drabužio apvadą; ir kurie tik palietė, tapo visiškai sveiki.'),
  (@b40, 15, 1, 'Tuomet atėjo pas Jėzų raštininkai ir fariziejai, kurie buvo iš Jeruzalės, sakydami:'),
  (@b40, 15, 2, '„Kodėl tavo mokiniai laužo vyresniųjų tradiciją? Nes jie nesiplauna savo rankų, kai valgo duoną“.'),
  (@b40, 15, 3, 'Bet jis atsakydamas tarė jiems: „Kodėl ir jūs laužote Dievo įsakymą savąja tradicija?'),
  (@b40, 15, 4, 'Nes Dievas įsakė, sakydamas: ‘Gerbk savo tėvą ir motiną’; ir: ‘Kas keikia tėvą ar motiną, tas temiršta mirtimi’.'),
  (@b40, 15, 5, 'Bet jūs sakote: ‘Kas tik pasakys savo tėvui ar savo motinai: „Tai yra dovana, kuria tu iš manęs turėtumei naudą“,'),
  (@b40, 15, 6, 'o negerbtų savo tėvo ar motinos, tas bus laisvas’. Taip jūs sava tradicija Dievo įsakymą padarėte negaliojančiu.'),
  (@b40, 15, 7, 'Veidmainiai, gerai Izaijas pranašavo apie jus, sakydamas:'),
  (@b40, 15, 8, '‘Ši tauta artinasi prie manęs savo burna ir gerbia mane savo lūpomis; bet jų širdis yra toli nuo manęs.'),
  (@b40, 15, 9, 'Bet veltui jie mane garbina, mokydami žmonių įsakymus kaip mokslus’“.'),
  (@b40, 15, 10, 'Ir jis pasišaukė minią ir tarė jiems: „Klausykite ir supraskite:'),
  (@b40, 15, 11, 'ne tai, kas įeina į burną, suteršia žmogų; bet tai, kas išeina iš burnos, – tai suteršia žmogų“.'),
  (@b40, 15, 12, 'Tada atėjo jo mokiniai ir jam pasakė: „Ar tu žinai, kad fariziejai pasipiktino, išgirdę šį pasakymą?“'),
  (@b40, 15, 13, 'Bet jis atsakydamas tarė: „Kiekvienas augalas, kurio mano dangiškasis Tėvas nesodino, bus išrautas.'),
  (@b40, 15, 14, 'Palikite juos: jie yra akli aklųjų vadovai. Ir jei aklas veda aklą, abu įkris į griovį“.'),
  (@b40, 15, 15, 'Tada Petras atsakydamas tarė jam: „Išaiškink mums šitą palyginimą“.'),
  (@b40, 15, 16, 'Ir Jėzus tarė: „Ar ir jūs dar be supratimo?'),
  (@b40, 15, 17, 'Ar dar nesuprantate, kad visa, kas patenka į burną, eina į pilvą ir išmetama į išvietę?'),
  (@b40, 15, 18, 'Bet kas išeina iš burnos, ateina iš širdies; ir tai suteršia žmogų.'),
  (@b40, 15, 19, 'Nes iš širdies eina piktos mintys, žmogžudystės, svetimavimai, paleistuvystės, vagystės, melagingi liudijimai, piktžodžiavimai –'),
  (@b40, 15, 20, 'šitie yra tai, kas suteršia žmogų; bet valgymas neplautomis rankomis nesuteršia žmogaus“.'),
  (@b40, 15, 21, 'Tada Jėzus iš ten išėjo ir nuėjo į Tyro ir Sidono sritis.'),
  (@b40, 15, 22, 'Ir štai Kanaano moteris atėjo iš tų pačių ribų ir šaukė jam, sakydama: „Pasigailėk manęs, o Viešpatie, Dovydo Sūnau; mano dukrą labai maudžia velnias“.'),
  (@b40, 15, 23, 'Bet jis neatsakė jai nei žodžio. Ir jo mokiniai atėjo ir maldavo jį, sakydami: „Paleisk ją; nes ji šaukia mums iš paskos“.'),
  (@b40, 15, 24, 'Bet jis atsakydamas tarė: „Aš esu siųstas tik pas pražuvusias Izraelio namų avis“.'),
  (@b40, 15, 25, 'Tada ji atėjo ir pagarbino jį, tardama: „Viešpatie, padėk man“.'),
  (@b40, 15, 26, 'Bet jis atsakydamas tarė: „Nedera imti vaikų duoną ir mesti ją šunims“.'),
  (@b40, 15, 27, 'Ir ji tarė: „Tiesa, Viešpatie; betgi ir šunys maitinasi trupiniais, kurie krenta nuo jų šeimininkų stalo“.'),
  (@b40, 15, 28, 'Tada Jėzus atsakydamas tarė jai: „O moterie, didis tavo tikėjimas; tebūna tau kaip nori“. Ir jos dukra tapo sveika tą pačią valandą.'),
  (@b40, 15, 29, 'Ir Jėzus iš ten išėjo ir atėjo prie Galilėjos jūros; ir užėjo ant kalno ir ten atsisėdo.'),
  (@b40, 15, 30, 'Ir didžiulės minios atėjo pas jį, turėdamos su savimi raišų, aklų, nebylių, luošų ir daug kitų, ir dėjo juos prie Jėzaus kojų; ir jis juos išgydė;'),
  (@b40, 15, 31, 'taip, kad minia stebėjosi, matydama nebylius kalbančius, luošius sveikus, raišus vaikščiojančius ir aklus reginčius; ir jie šlovino Izraelio Dievą.'),
  (@b40, 15, 32, 'Tuomet Jėzus pasišaukė savo mokinius ir tarė: „Man gaila tos minios, nes jau tris dienas jie pasilieka su manimi ir neturi ko valgyti; ir aš nenoriu paleisti jų pasninkaujančių, kad jie nenusilptų kelyje“.'),
  (@b40, 15, 33, 'Ir jo mokiniai jam sako: „Iš kur imti mums dykumoje tiek daug duonos, kad pasotintume tokią didžiulę minią?“'),
  (@b40, 15, 34, 'Ir Jėzus jiems sako: „Kiek turite kepalų?“ Ir jie tarė: „Septynis ir keletą mažų žuvų“.'),
  (@b40, 15, 35, 'Ir jis įsakė miniai susėsti ant žemės.'),
  (@b40, 15, 36, 'Ir jis paėmė septynis kepalus bei žuvis ir padėkojo, ir laužė, ir davė savo mokiniams, o mokiniai – miniai.'),
  (@b40, 15, 37, 'Ir jie visi valgė ir pasisotino; ir jie pririnko septynias pilnas pintines likusio prilaužyto maisto.'),
  (@b40, 15, 38, 'Ir valgančiųjų buvo keturi tūkstančiai vyrų, neskaitant moterų ir vaikų.'),
  (@b40, 15, 39, 'Ir jis paleido minią ir įsėdo į laivą, ir atvyko į Magdalos ribas.'),
  (@b40, 16, 1, 'Atėjo taip pat ir fariziejai su sadukiejais ir gundydami prašė jį, kad jis parodytų jiems ženklą iš dangaus.'),
  (@b40, 16, 2, 'Jis atsakydamas tarė jiems: „Kai yra vakaras, jūs sakote: ‘Bus giedra, nes dangus yra raudonas’.'),
  (@b40, 16, 3, 'O ryte: ‘Šiandien bus bjaurus oras, nes dangus yra raudonas ir niaukiasi’. O veidmainiai, jūs galite atpažinti dangaus veidą; bet argi negalite atpažinti laikų ženklų?'),
  (@b40, 16, 4, 'Nedora ir svetimaujanti karta ieško ženklo; bet jai nebus duotas ženklas, o tik pranašo Jonos ženklas“. Ir jis paliko juos ir išėjo.'),
  (@b40, 16, 5, 'Ir kai jo mokiniai atvyko į kitą pusę, jie buvo pamiršę pasiimti duonos.'),
  (@b40, 16, 6, 'Tuomet Jėzus jiems tarė: „Būkite atidūs ir saugokitės fariziejų bei sadukiejų raugo“.'),
  (@b40, 16, 7, 'Ir jie tarpusavyje svarstė, kalbėdami: „Tai todėl, kad nepasiėmėme duonos“.'),
  (@b40, 16, 8, 'Tai supratęs Jėzus jiems tarė: „O mažatikiai, kodėl tarpusavyje svarstote, kad neatsinešėte duonos?'),
  (@b40, 16, 9, 'Argi dar nesuprantate nei nepamenate anų penkių kepalų dėl penketo tūkstančių ir kiek pintinių pririnkote?'),
  (@b40, 16, 10, 'Nei anų septynių kepalų dėl ketverto tūkstančių ir kiek pintinių pririnkote?'),
  (@b40, 16, 11, 'Tad kaipgi nesuprantate, kad kalbėjau jums tai ne apie duoną, idant saugotumėtės fariziejų ir sadukiejų raugo?“'),
  (@b40, 16, 12, 'Tada jie suprato, kad jis liepė saugotis ne duonos raugo, bet fariziejų ir sadukiejų mokslo.'),
  (@b40, 16, 13, 'Kai Jėzus atėjo į Pilypo Cezarėjos sritis, jis paklausė savo mokinių, sakydamas: „Kuo žmonės sako mane, žmogaus Sūnų, esant?“'),
  (@b40, 16, 14, 'Ir jie tarė: „Vieni sako, kad tu Jonas Krikštytojas, kiti – Elijas; o kiti – Jeremijas arba vienas iš pranašų“.'),
  (@b40, 16, 15, 'Jis sako jiems: „Bet kuo jūs sakote mane esant?“'),
  (@b40, 16, 16, 'Ir Simonas Petras atsakydamas tarė: „Tu esi Kristus, gyvojo Dievo Sūnus“.'),
  (@b40, 16, 17, 'Ir Jėzus atsakydamas tarė jam: „Palaimintas esi, Simonai Bar-Jona, nes ne kūnas ir kraujas tau tai apreiškė, bet mano Tėvas, kuris yra danguje.'),
  (@b40, 16, 18, 'Ir aš taip pat sakau tau, kad tu esi Petras, ir ant šitos uolos aš pastatysiu savo bažnyčią; ir pragaro vartai jos nenugalės.'),
  (@b40, 16, 19, 'Ir tau duosiu dangaus karalystės raktus; ir ką tu suriši žemėje, bus surišta danguje; ir ką tu atriši žemėje, bus atrišta danguje“.'),
  (@b40, 16, 20, 'Tada jis įpareigojo savo mokinius, kad jie niekam nesakytų, kad jis yra Jėzus – Kristus.'),
  (@b40, 16, 21, 'Nuo to laiko Jėzus pradėjo skelbti savo mokiniams, kad jis turįs eiti į Jeruzalę ir daug iškentėti nuo vyresniųjų ir vyriausiųjų kunigų bei raštininkų, ir būti nužudytas bei trečią dieną būti prikeltas.'),
  (@b40, 16, 22, 'Tada Petras paėmė jį ir pradėjo jį barti, sakydamas: „Tebūna tai toli nuo tavęs, Viešpatie, – tau neturi tai atsitikti“.'),
  (@b40, 16, 23, 'Bet jis atsisuko ir tarė Petrui: „Pasitrauk už manęs, šėtone; tu esi man papiktinimas, nes tau nepatinka tai, kas Dievo, o tik tai, kas žmonių“.'),
  (@b40, 16, 24, 'Tada Jėzus tarė savo mokiniams: „Jei kas nori eiti paskui mane, teišsižada savęs ir teima savo kryžių, ir seka paskui mane.'),
  (@b40, 16, 25, 'Nes kas nori išgelbėti savo gyvybę, tas ją praras; o kas praras savo gyvybę dėl manęs, tas ją atras.'),
  (@b40, 16, 26, 'Nes kokia gi žmogui nauda, jeigu jis laimėtų visą pasaulį, o savo sielą prarastų? Arba ką žmogus gali duoti mainais už savo sielą?'),
  (@b40, 16, 27, 'Nes žmogaus Sūnus ateis savo Tėvo šlovėje su savo angelais; ir tada jis atlygins kiekvienam pagal jo darbus.'),
  (@b40, 16, 28, 'Iš tiesų sakau jums: yra kai kurie čia stovintys, kurie neragaus mirties, kol pamatys žmogaus Sūnų, ateinantį savo karalystėje“.'),
  (@b40, 17, 1, 'Ir po šešių dienų Jėzus pasiima Petrą, Jokūbą ir jo brolį Joną ir užsiveda juos nuošaliai ant aukšto kalno;'),
  (@b40, 17, 2, 'ir atsimainė jų akivaizdoje; ir jo veidas spindėjo kaip saulė, ir jo drabužiai buvo balti kaip šviesa.'),
  (@b40, 17, 3, 'Ir štai jiems pasirodė Mozė ir Elijas, besikalbą su juo.'),
  (@b40, 17, 4, 'Tada Petras atsakydamas tarė Jėzui: „Viešpatie, gera mums čia būti; jei nori, padarykime čia tris padangtes – vieną tau, vieną Mozei ir vieną Elijui“.'),
  (@b40, 17, 5, 'Dar jam bekalbant štai šviesus debesis apgaubė juos šešėliu; ir štai balsas iš debesies, kuris tarė: „Šitas yra mano mylimas Sūnus, kuriuo aš labai patenkintas; klausykite jo“.'),
  (@b40, 17, 6, 'Ir tai išgirdę mokiniai parpuolė veidu žemyn ir buvo labai išsigandę.'),
  (@b40, 17, 7, 'Ir Jėzus atėjo ir palietė juos, ir tarė: „Kelkitės ir nebijokite“.'),
  (@b40, 17, 8, 'Ir pakėlę savo akis jie nebematė nieko, vien tiktai Jėzų.'),
  (@b40, 17, 9, 'Ir kai jie leidosi nuo kalno, Jėzus juos įpareigojo, sakydamas: „Niekam nepasakokite regėjimo, iki žmogaus Sūnus bus prisikėlęs iš numirusių“.'),
  (@b40, 17, 10, 'Ir jo mokiniai jo pakláusė, sakydami: „Kodėl tad raštininkai sako, kad pirmiau turįs ateiti Elijas?“'),
  (@b40, 17, 11, 'Ir Jėzus atsakydamas tarė jiems: „Iš tiesų Elijas ateis pirmiau ir viską atstatys.'),
  (@b40, 17, 12, 'Bet sakau jums, kad Elijas jau yra atėjęs, ir jie jo nepažino, bet padarė jam, ką tik panorėjo. Taip pat ir žmogaus Sūnus nuo jų kentės“.'),
  (@b40, 17, 13, 'Tada mokiniai suprato, kad jis kalbėjo jiems apie Joną Krikštytoją.'),
  (@b40, 17, 14, 'Ir kai jie buvo atėję prie minios, pas jį atėjo vienas žmogus, klaupdamasis prieš jį ir sakydamas:'),
  (@b40, 17, 15, '„Viešpatie, pasigailėk mano sūnaus; nes jis yra lunatikas ir labai kankinasi; nes jis dažnai įpuola į ugnį ir dažnai į vandenį.'),
  (@b40, 17, 16, 'Ir aš atvedžiau jį pas tavo mokinius, o jie negalėjo jo išgydyti“.'),
  (@b40, 17, 17, 'Tada Jėzus atsakydamas tarė: „O netikinti ir iškrypusi karta, kiek ilgai būsiu su jumis? Kiek ilgai turėsiu jus kęsti? Atveskite jį čia pas mane“.'),
  (@b40, 17, 18, 'Ir Jėzus subarė velnią; ir jis išėjo iš jo; ir vaikas pasveiko tą pačią valandą.'),
  (@b40, 17, 19, 'Tada mokiniai atskirai atėjo pas Jėzų ir tarė: „Kodėl negalėjome jo išvaryti?“'),
  (@b40, 17, 20, 'Ir Jėzus jiems tarė: „Dėl jūsų netikėjimo; nes iš tiesų sakau jums: jei turite tikėjimą kaip garstyčios sėklos grūdelį, jūs pasakysite šitam kalnui: ‘Persikelk iš čia į tenai’, ir jis persikels; ir nieko jums nebus neįmanomo.'),
  (@b40, 17, 21, 'Tačiau šita veislė kitaip neišeina, kaip tik per maldą ir pasninką“.'),
  (@b40, 17, 22, 'Ir kol jie laikėsi Galilėjoje, Jėzus jiems tarė: „Žmogaus Sūnus bus išduotas į žmonių rankas;'),
  (@b40, 17, 23, 'ir jie nužudys jį, ir trečią dieną jis bus prikeltas“. Ir jie be galo nuliūdo.'),
  (@b40, 17, 24, 'Ir kai jie buvo atėję į Kafernaumą, pas Petrą atėjo tie, kurie rinko duoklės pinigus, ir tarė: „Ar jūsų mokytojas nemoka duoklės?“'),
  (@b40, 17, 25, 'Jis sako: „Taip“. Ir jam įėjus į namus, Jėzus pirmas jį prakalbino: „Kaip tu manai, Simonai? Iš ko žemės karaliai ima muitą ar duoklę? Iš savo vaikų ar iš svetimų?“'),
  (@b40, 17, 26, 'Petras jam sako: „Iš svetimų“. Jėzus sako jam: „Tuomet vaikai laisvi.'),
  (@b40, 17, 27, 'Tačiau kad jų nepapiktintume, eik prie jūros, įmesk kabliuką ir ištrauk pirmą iškilusią žuvį; ir pravėręs jos žiotis rasi pinigą; paimk jį ir duok jiems už mane ir save“.'),
  (@b40, 18, 1, 'Tuo pačiu metu pas Jėzų atėjo mokiniai, sakydami: „Kas yra didžiausias dangaus karalystėje?“'),
  (@b40, 18, 2, 'Ir Jėzus pasišaukė mažą vaiką ir pastatė jį į jų tarpą,'),
  (@b40, 18, 3, 'ir tarė: „Iš tiesų sakau jums: jei nebūsite atsivertę ir nepasidarysite kaip maži vaikai, jūs neįeisite į dangaus karalystę.'),
  (@b40, 18, 4, 'Todėl kas nusižemins kaip šis mažas vaikas, tas yra didžiausias dangaus karalystėje.'),
  (@b40, 18, 5, 'Ir kas priims tokį mažą vaiką mano vardu, tas priima mane.'),
  (@b40, 18, 6, 'Bet kas papiktins vieną iš šitų mažųjų, kurie tiki manimi, tam būtų buvę geriau, kad girnų akmuo būtų užkabintas jam ant kaklo ir kad jis būtų paskandintas jūros gilumoje.'),
  (@b40, 18, 7, 'Vargas pasauliui dėl papiktinimų! Nes reikia, kad papiktinimai ateitų; bet vargas tam žmogui, per kurį papiktinimas ateina!'),
  (@b40, 18, 8, 'Todėl jei tavo ranka ar tavo koja tave piktina, nukirsk jas ir mesk nuo savęs; tau yra geriau įeiti į gyvenimą raišam arba luošam, negu turint dvi rankas arba dvi kojas būti įmestam į amžiną ugnį.'),
  (@b40, 18, 9, 'Ir jei tavo akis tave piktina, išlupk ją ir mesk nuo savęs; tau yra geriau įeiti į gyvenimą viena akimi, negu turint dvi akis būti įmestam į pragaro ugnį.'),
  (@b40, 18, 10, 'Žiūrėkite, kad nepaniekintumėte nei vieno iš šitų mažųjų; nes sakau jums, kad jų angelai danguje visada mato veidą mano Tėvo, kuris yra danguje.'),
  (@b40, 18, 11, 'Nes žmogaus Sūnus atėjo gelbėti to, kas buvo pražuvę.'),
  (@b40, 18, 12, 'Kaip jūs manote? Jei kas turi šimtą avių, ir viena iš jų yra pasiklydusi, argi jis nepalieka devyniasdešimt devynių ir neina į kalnus, ir neieško tos, kuri pasiklydusi?'),
  (@b40, 18, 13, 'Ir jei nutinka, kad jis ją suranda, iš tiesų sakau jums: jis daugiau džiaugiasi dėl tos avies, negu dėl devyniasdešimt devynių, kurios nepasiklydo.'),
  (@b40, 18, 14, 'Taip ir jūsų Tėvo, esančio danguje, valia, kad nei vienas iš šitų mažųjų nepražūtų“.'),
  (@b40, 18, 15, '„Be to, jei tavo brolis nusižengs prieš tave, eik ir apie jo kaltę jam pasakyk tik tarp savęs ir jo; jeigu jis paklausys tavęs, tu laimėjai savo brolį.'),
  (@b40, 18, 16, 'Bet jeigu jis tavęs neklausys, paimk su savimi dar vieną ar du, kad dviejų ar trijų liudytojų burnoje būtų patvirtintas kiekvienas žodis.'),
  (@b40, 18, 17, 'Ir jeigu jam nerūpės jų klausyti, pasakyk tai bažnyčiai; bet jeigu jam nerūpės klausyti bažnyčios, tegul jis tau būna kaip pagonis ir muitininkas.'),
  (@b40, 18, 18, 'Iš tiesų sakau jums: ką surišite žemėje, bus surišta danguje; ir ką atrišite žemėje, bus atrišta danguje.'),
  (@b40, 18, 19, 'Vėlgi sakau jums: jei du iš jūsų susitars žemėje dėl kokio dalyko, kad jo prašytų, tai bus jiems padaryta mano Tėvo, kuris yra danguje.'),
  (@b40, 18, 20, 'Nes kur du ar trys susirinkę mano vardu, ten aš esu tarp jų“.'),
  (@b40, 18, 21, 'Tada pas jį atėjo Petras ir tarė: „Viešpatie, kaip dažnai mano brolis nusidės prieš mane, o aš turiu jam atleisti? Iki septynių kartų?“'),
  (@b40, 18, 22, 'Jėzus jam sako: „Nesakau tau iki septynių kartų, bet iki septyniasdešimtkart septynių“.'),
  (@b40, 18, 23, '„Todėl dangaus karalystė prilygsta vienam karaliui, kuris norėjo atsiskaityti su savo tarnais.'),
  (@b40, 18, 24, 'Ir kai jis pradėjo atsiskaitinėti, atvedė pas jį vieną, kuris buvo jam skolingas dešimt tūkstančių talentų.'),
  (@b40, 18, 25, 'Bet kadangi jis neturėjo kuo užmokėti, jo viešpats įsakė parduoti jį ir jo žmoną, ir vaikus, ir viską, ką jis turėjo, ir kad būtų užmokėta.'),
  (@b40, 18, 26, 'Todėl tarnas parpuolė ir pagarbino jį, sakydamas: ‘Viešpatie, turėk man kantrybės, ir aš tau viską sumokėsiu’.'),
  (@b40, 18, 27, 'Tuomet to tarno viešpats buvo apimtas gailesčio ir paleido jį bei atleido jam skolą.'),
  (@b40, 18, 28, 'Bet tas tarnas išėjo ir sutiko vieną iš savo bendratarnių, kuris buvo jam skolingas šimtą denarų; ir jis pridėjo prie jo rankas bei paėmė jį už gerklės, sakydamas: ‘Sumokėk man, ką esi skolingas’.'),
  (@b40, 18, 29, 'Ir jo bendratarnis parpuolė prie jo kojų ir jo maldavo, sakydamas: ‘Turėk man kantrybės, ir aš tau viską sumokėsiu’.'),
  (@b40, 18, 30, 'O jis nenorėjo; bet nuėjo ir įmetė jį į kalėjimą, kol jis sumokės skolą.'),
  (@b40, 18, 31, 'Tad jo bendratarniai pamatę, kas atsitiko, labai nuliūdo ir atėję papasakojo savo viešpačiui viską, kas atsitiko.'),
  (@b40, 18, 32, 'Tada jo viešpats jį pasišaukęs jam tarė: ‘O nedorasis tarne, aš atleidau tau visą tą skolą, nes tu manęs prašei;'),
  (@b40, 18, 33, 'argi neturėjai ir tu pasigailėti savo bendratarnio, kaip ir aš tavęs pasigailėjau?‘'),
  (@b40, 18, 34, 'Ir jo viešpats užsirūstino ir atidavė jį kankintojams, kol jis sumokės viską, kas jam priklauso.'),
  (@b40, 18, 35, 'Taip ir mano dangiškasis Tėvas padarys jums, jei kiekvienas iš širdies neatleisite savo broliams jų nusižengimų“.'),
  (@b40, 19, 1, 'Ir kai Jėzus pabaigė šiuos pasakymus, įvyko, kad jis išėjo iš Galilėjos ir atėjo į Judėjos ribas anapus Jordano;'),
  (@b40, 19, 2, 'ir didelės minios sekė paskui jį; ir jis ten juos išgydė.'),
  (@b40, 19, 3, 'Atėjo pas jį ir fariziejai, gundydami jį ir sakydami jam: „Ar teisėta vyrui dėl kiekvienos priežasties pašalinti savo žmoną?“'),
  (@b40, 19, 4, 'Ir jis atsakydamas tarė jiems: „Ar neskaitėte, kad tas, kuris juos padarė pradžioje, ‘padarė juos vyriškos lyties ir moteriškos lyties’'),
  (@b40, 19, 5, 'ir tarė: ‘Dėl šios priežasties vyras tėvą ir motiną paliks ir prie savo žmonos prilips; ir jie du bus vienas kūnas’?'),
  (@b40, 19, 6, 'Dėl to jie jau nebėra du, bet vienas kūnas. Todėl ką Dievas sujungė, žmogus teneperskiria“.'),
  (@b40, 19, 7, 'Jie sako jam: „Kodėl tad Mozė įsakė duoti skyrybų raštą ir ją pašalinti?“'),
  (@b40, 19, 8, 'Jis jiems sako: „Dėl jūsų širdžių kietumo Mozė leido jums pašalinti savo žmonas; bet nuo pradžios taip nebuvo.'),
  (@b40, 19, 9, 'Ir aš jums sakau: kas tik pašalins savo žmoną, jei ne dėl paleistuvystės, ir ves kitą, svetimauja; ir kas pašalintąją veda, svetimauja“.'),
  (@b40, 19, 10, 'Jo mokiniai jam sako: „Jei tokie vyro reikalai su žmona, tai nėra gerai vesti“.'),
  (@b40, 19, 11, 'Bet jis jiems tarė: „Ne visi gali priimti šitą pasakymą, o tik tie, kuriems yra duota.'),
  (@b40, 19, 12, 'Nes yra eunuchų, kurie tokie gimė iš savo motinos įsčių; ir yra eunuchų, kurie žmonių padaryti eunuchais; ir yra eunuchų, kurie padarė save eunuchais dėl dangaus karalystės. Kas gali tai priimti, tepriima“.'),
  (@b40, 19, 13, 'Tuomet atvedė jam mažų vaikų, kad jis uždėtų ant jų savo rankas ir pasimelstų; o mokiniai juos barė.'),
  (@b40, 19, 14, 'Bet Jėzus tarė: „Leiskite mažus vaikus ir nedrauskite jiems ateiti pas mane, nes tokių yra dangaus karalystė“.'),
  (@b40, 19, 15, 'Ir jis uždėjo ant jų savo rankas ir iš ten išėjo.'),
  (@b40, 19, 16, 'Ir štai vienas atėjo ir tarė jam: „Gerasis Mokytojau, ką gero turiu daryti, idant turėčiau amžiną gyvenimą?“'),
  (@b40, 19, 17, 'Ir jis jam tarė: „Kodėl vadini mane geru? Nėra nei vieno gero, bet tik vienas, tai yra Dievas; bet jei nori įeiti į gyvenimą, laikykis įsakymų“.'),
  (@b40, 19, 18, 'Jis jam sako: „Kurių?“ Jėzus tarė: „Nežudyk“, „Nesvetimauk“, „Nevok“, „Melagingai neliudyk“,'),
  (@b40, 19, 19, '„Gerbk savo tėvą ir motiną“ ir „Mylėk savo artimą kaip save patį“.'),
  (@b40, 19, 20, 'Jaunuolis jam sako: „Viso to laikiausi nuo savo jaunystės; ko dar man trūksta?“'),
  (@b40, 19, 21, 'Jėzus jam tarė: „Jei nori būti tobulas, eik ir parduok, ką turi, ir duok vargšams, ir turėsi lobį danguje; ir ateik bei sek paskui mane“.'),
  (@b40, 19, 22, 'Bet jaunuolis, išgirdęs tą pasakymą, nuėjo nuliūdęs; nes jis turėjo didelius turtus.'),
  (@b40, 19, 23, 'Tada Jėzus tarė savo mokiniams: „Iš tiesų sakau jums, kad turtuolis sunkiai įeis į dangaus karalystę.'),
  (@b40, 19, 24, 'Ir vėl sakau jums: lengviau yra kupranugariui pralįsti pro adatos auselę, negu turtuoliui įeiti į Dievo karalystę“.'),
  (@b40, 19, 25, 'Kai jo mokiniai tai išgirdo, jie buvo be galo nustebę, sakydami: „Kas tada gali būti išgelbėtas?“'),
  (@b40, 19, 26, 'Bet Jėzus pažvelgė į juos ir jiems tarė: „Žmonėms tai neįmanoma; bet Dievui viskas yra įmanoma“.'),
  (@b40, 19, 27, 'Tada Petras atsakė ir jam tarė: „Štai mes viską palikome ir sekėme paskui tave; tad kas mums bus už tai?“'),
  (@b40, 19, 28, 'Ir Jėzus jiems tarė: „Iš tiesų sakau jums, kad atgimime, kai žmogaus Sūnus sėdės savo šlovės soste, jūs, kurie sekėte paskui mane, irgi sėdėsite dvylikoje sostų, teisdami dvylika Izraelio genčių.'),
  (@b40, 19, 29, 'Ir kiekvienas, kuris paliko namus ar brolius, ar seseris, ar tėvą, ar motiną, ar žmoną, ar vaikus, ar žemes dėl mano vardo, gaus šimteriopai ir paveldės amžinąjį gyvenimą.'),
  (@b40, 19, 30, 'Bet daugelis pirmųjų bus paskutiniai; ir paskutiniai bus pirmi“.'),
  (@b40, 20, 1, '„Nes dangaus karalystė prilygsta žmogui – namų šeimininkui, kuris anksti ryte išėjo samdyti darbininkų savo vynuogynui.'),
  (@b40, 20, 2, 'Ir suderėjęs su darbininkais po denarą į dieną, jis išsiuntė juos į savo vynuogyną.'),
  (@b40, 20, 3, 'Ir jis išėjo apie trečią valandą ir pamatė kitus, stovinčius turgavietėje be darbo,'),
  (@b40, 20, 4, 'ir tarė jiems: ‘Eikite ir jūs į vynuogyną, ir aš jums duosiu, kas teisinga’. Ir jie nuėjo.'),
  (@b40, 20, 5, 'Vėl jis išėjo apie šeštą ir devintą valandą ir padarė taip pat.'),
  (@b40, 20, 6, 'Ir apie vienuoliktą valandą jis išėjo ir rado kitus stovinčius be darbo, ir sako jiems: ‘Kodėl čia stovite visą dieną be darbo?’'),
  (@b40, 20, 7, 'Jie sako jam: ‘Todėl, kad niekas mūsų nepasamdė’. Jis sako jiems: ‘Eikite ir jūs į vynuogyną; ir gausite tai, kas teisinga’.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b40, 20, 8, 'Taigi atėjus vakarui vynuogyno viešpats sako savo ūkvedžiui: ‘Pakviesk darbininkus ir duok jiems jų atlyginimą, pradedant nuo paskutiniųjų iki pirmųjų’.'),
  (@b40, 20, 9, 'Ir kai atėjo tie, kurie buvo pasamdyti apie vienuoliktą valandą, kiekvienas gavo po denarą.'),
  (@b40, 20, 10, 'Bet atėję pirmieji, manė gausią daugiau; ir jie taip pat – kiekvienas gavo po denarą.'),
  (@b40, 20, 11, 'Ir tai gavę jie murmėjo prieš namų šeimininką,'),
  (@b40, 20, 12, 'sakydami: ‘Šitie paskutinieji tedirbo vieną valandą, ir tu padarei juos lygius mums, pakėlusiems dienos naštą ir kaitrą’.'),
  (@b40, 20, 13, 'Bet jis atsakė vienam iš jų ir tarė: ‘Drauge, aš nedarau tau skriaudos; argi tu ne už denarą suderėjai su manimi?'),
  (@b40, 20, 14, 'Paimk tai, kas yra tavo, ir eik; aš noriu duoti šitam paskutiniam kaip ir tau.'),
  (@b40, 20, 15, 'Argi neturiu teisės daryti tai, ką noriu, su tuo, kas mano? Ar tavo akis pikta, kadangi aš geras?’'),
  (@b40, 20, 16, 'Taip paskutinieji bus pirmi, o pirmieji – paskutiniai; nes daug yra pašauktų, bet mažai išrinktų“.'),
  (@b40, 20, 17, 'Ir Jėzus, eidamas aukštyn į Jeruzalę, kelyje atskirai pasiėmė dvylika mokinių ir tarė jiems:'),
  (@b40, 20, 18, '„Štai mes einame aukštyn į Jeruzalę; ir žmogaus Sūnus bus išduotas vyriausiems kunigams bei raštininkams, ir jie pasmerks jį į mirtį'),
  (@b40, 20, 19, 'ir atiduos jį pagonims tyčiotis ir nuplakti, ir jį nukryžiuoti; ir trečią dieną jis prisikels“.'),
  (@b40, 20, 20, 'Tada pas jį atėjo Zebediejaus vaikų motina su savo sūnumis, garbindama jį ir kažko tai jo prašydama.'),
  (@b40, 20, 21, 'Ir jis jai tarė: „Ko nori?“ Ji sako jam: „Paskirk, kad šitie mano du sūnūs sėdėtų vienas tavo dešinėje, o kitas kairėje tavo karalystėje“.'),
  (@b40, 20, 22, 'Bet Jėzus atsakydamas tarė: „Jūs nežinote, ko prašote. Ar galite gerti iš taurės, iš kurios aš gersiu, ir būti krikštijami krikštu, kuriuo aš esu krikštijamas?“ Jie sako jam: „Mes galime“.'),
  (@b40, 20, 23, 'Ir jis jiems sako: „Jūs iš tikrųjų gersite iš mano taurės ir būsite pakrikštyti krikštu, kuriuo aš esu krikštijamas; bet sėdėti mano dešinėje ir mano kairėje ne mano, kad duočiau, bet bus duota tiems, kuriems yra mano Tėvo paruošta“.'),
  (@b40, 20, 24, 'Ir kai dešimt tai išgirdo, jie pasipiktino prieš du brolius.'),
  (@b40, 20, 25, 'Bet Jėzus juos pasišaukė ir tarė: „Jūs žinote, kad pagonių kunigaikščiai jiems viešpatauja, ir didieji valdo juos.'),
  (@b40, 20, 26, 'Bet ne taip bus tarp jūsų; bet kas tarp jūsų nori būti didis, tegul jis būna jūsų tarnautojas;'),
  (@b40, 20, 27, 'ir kas tarp jūsų nori būti vyriausias, tegul jis būna jūsų tarnas;'),
  (@b40, 20, 28, 'lygiai kaip žmogaus Sūnus atėjo ne kad jam patarnautų, bet patarnauti ir atiduoti savo gyvybę atpirkimui už daugelį“.'),
  (@b40, 20, 29, 'Ir jiems išeinant iš Jericho, didžiulė minia sekė paskui jį.'),
  (@b40, 20, 30, 'Ir štai pakelėje sėdintys du aklieji išgirdę, kad Jėzus eina pro šalį, šaukė, sakydami: „Pasigailėk mūsų, o Viešpatie, Dovydo Sūnau!“'),
  (@b40, 20, 31, 'Ir minia draudė juos, nes jie turėjo tylėti; bet jie dar labiau šaukė, sakydami: „Pasigailėk mūsų, o Viešpatie, Dovydo Sūnau!“'),
  (@b40, 20, 32, 'Ir Jėzus sustojo ir pašaukė juos, ir tarė: „Ko norite, kad jums padaryčiau?“'),
  (@b40, 20, 33, 'Jie sako jam: „Viešpatie, kad mūsų akys būtų atvertos“.'),
  (@b40, 20, 34, 'Tad Jėzus pasigailėjo jų ir palietė jų akis; ir tuoj pat jų akys praregėjo, ir jie nusekė paskui jį.'),
  (@b40, 21, 1, 'Ir kai jie priartėjo prie Jeruzalės ir atėjo į Betfagę prie Alyvų kalno, Jėzus pasiuntė du mokinius,'),
  (@b40, 21, 2, 'sakydamas jiems: „Eikite į priešais jus esantį kaimą, ir tuojau rasite pririštą asilę ir asiliuką su ja; atriškite juos ir atveskite man.'),
  (@b40, 21, 3, 'Ir jei kas ką nors jums sakytų, jūs pasakykite: ‘Jų reikia Viešpačiui’; ir jis tuojau juos išsiųs“.'),
  (@b40, 21, 4, 'Visa tai įvyko, kad išsipildytų, kas buvo kalbėta per pranašą, sakant:'),
  (@b40, 21, 5, '„Sakykite Siono dukrai: ‘Štai tavo Karalius ateina pas tave romus ir sėdintis ant asilės ir ant asiliuko – asilės jauniklio’“.'),
  (@b40, 21, 6, 'Ir mokiniai nuėjo ir padarė, kaip Jėzus jiems įsakė,'),
  (@b40, 21, 7, 'ir, atvedę asilę ir asiliuką, uždėjo ant jų savo drabužius, ir užsodino jį ant tų.'),
  (@b40, 21, 8, 'Ir labai didelė minia tiesė savo drabužius ant kelio; kiti kirto nuo medžių šakas ir barstė jas ant kelio.'),
  (@b40, 21, 9, 'Ir minios, kurios ėjo priekyje ir kurios sekė, šaukė, sakydamos: „Osana Dovydo Sūnui! Palaimintas tas, kuris ateina Viešpaties vardu! Osana aukštybėse!“'),
  (@b40, 21, 10, 'Ir jam atėjus į Jeruzalę, visas miestas sujudo, sakydamas: „Kas yra šitas?“'),
  (@b40, 21, 11, 'Ir minia tarė: „Šitas yra Jėzus, pranašas iš Galilėjos Nazareto“.'),
  (@b40, 21, 12, 'Ir Jėzus įėjo į Dievo šventyklą ir išvarė visus tuos, kurie pardavinėjo ir pirko šventykloje, ir apvertė pinigų keitėjų stalus bei krėslus tų, kurie pardavinėjo balandžius,'),
  (@b40, 21, 13, 'ir tarė jiems: „Yra parašyta: ‘Mano namai bus vadinami maldos namais’; bet jūs padarėte juos vagių lindyne“.'),
  (@b40, 21, 14, 'Ir akli bei raiši atėjo pas jį į šventyklą; ir jis išgydė juos.'),
  (@b40, 21, 15, 'Ir kai vyriausieji kunigai ir raštininkai pamatė stebuklus, kuriuos jis padarė, ir vaikus šaukiančius šventykloje bei sakančius: „Osana Dovydo Sūnui!“; jie buvo labai nepatenkinti'),
  (@b40, 21, 16, 'ir tarė jam: „Ar girdi, ką šie sako?“ Ir Jėzus jiems sako: „Taip; ar niekada neskaitėte: ‘Iš kūdikių ir žindomųjų burnos tu ištobulinai gyrių’?“'),
  (@b40, 21, 17, 'Ir jis paliko juos ir išėjo iš miesto į Betaniją; ir jis ten apsistojo.'),
  (@b40, 21, 18, 'Na, o ryte, grįždamas į miestą, jis išalko.'),
  (@b40, 21, 19, 'Ir pamatęs kelyje figmedį, jis prie jo priėjo ir nieko ant jo nerado, bet vien tik lapus, ir tarė jam: „Nuo šiol teneauga ant tavęs vaisius per amžius!“ Ir netrukus figmedis nudžiūvo.'),
  (@b40, 21, 20, 'Ir kai mokiniai tai pamatė, jie stebėjosi, sakydami: „Kaip greitai nudžiūvo figmedis!“'),
  (@b40, 21, 21, 'Jėzus atsakydamas tarė jiems: „Iš tiesų sakau jums: jei turite tikėjimą ir neabejojate, jūs padarysite ne tik tai, kas yra padaryta figmedžiui, bet taip pat jei pasakysite šitam kalnui: ‘Pasikelk ir meskis į jūrą’, tai bus padaryta.'),
  (@b40, 21, 22, 'Ir visa, ko tik prašysite maldoje tikėdami, gausite“.'),
  (@b40, 21, 23, 'Ir kai jis buvo atėjęs į šventyklą, jam bemokant atėjo pas jį vyriausieji kunigai ir tautos vyresnieji ir tarė: „Kokia valdžia tu tai darai? Ir kas tau davė šią valdžią?“'),
  (@b40, 21, 24, 'Ir Jėzus atsakydamas jiems tarė: „Ir aš paklausiu jus vieno dalyko; jei jį man pasakysite, tai ir aš jums pasakysiu, kokia valdžia tai darau.'),
  (@b40, 21, 25, 'Iš kur buvo Jono krikštas? Iš dangaus ar iš žmonių?“ Ir jie svarstė tarpusavyje, sakydami: „Jei pasakysime: ‘Iš dangaus’, jis mums pasakys: ‘Tad kodėl juo netikėjote?’'),
  (@b40, 21, 26, 'Bet jei pasakysime: ‘Iš žmonių’, mes bijome tautos; nes visi laiko Joną pranašu“.'),
  (@b40, 21, 27, 'Ir jie atsakė Jėzui ir tarė: „Mes nežinome“. Ir jis tarė jiems: „Tai ir aš jums nepasakysiu, kokia valdžia tai darau“.'),
  (@b40, 21, 28, '„Bet kaip jūs galvojate? Vienas žmogus turėjo du sūnus; ir jis atėjo pas pirmąjį ir tarė: ‘Sūnau, eik šiandien dirbti į mano vynuogyną’.'),
  (@b40, 21, 29, 'Jis atsakydamas tarė: ‘Neisiu’; bet po to jis apsigalvojo ir nuėjo.'),
  (@b40, 21, 30, 'Ir jis atėjo pas antrąjį ir tą patį pasakė. Ir jis atsakydamas tarė: ‘Einu, pone’; bet nenuėjo.'),
  (@b40, 21, 31, 'Kuris iš tų dviejų įvykdė savo tėvo valią?“ Jie sako jam: „Pirmasis“. Jėzus jiems sako: „Iš tiesų sakau jums, kad muitininkai ir paleistuvės pirma jūsų eina į Dievo karalystę.'),
  (@b40, 21, 32, 'Nes Jonas atėjo pas jus teisumo keliu, o jūs juo netikėjote; bet muitininkai ir paleistuvės juo tikėjo; ir jūs, tai matydami, po to neapsigalvojote, kad juo tikėtumėte.'),
  (@b40, 21, 33, 'Klausykite kito palyginimo. Buvo vienas namų šeimininkas, kuris pasodino vynuogyną ir aplinkui aptvėrė jį tvora, ir iškasė jame vyno spaustuvą bei pastatė bokštą, ir išnuomojo jį žemdirbiams, ir išėjo į tolimą šalį;'),
  (@b40, 21, 34, 'Ir kai priartėjo vaisiaus laikas, jis pasiuntė savo tarnus pas žemdirbius, kad jie atsiimtų to vaisius.'),
  (@b40, 21, 35, 'Ir žemdirbiai paėmė jo tarnus ir vieną primušė, o kitą nužudė, o dar kitą užmėtė akmenimis.'),
  (@b40, 21, 36, 'Vėl jis siuntė kitus tarnus, daugiau negu pirma; ir jie padarė jiems lygiai taip pat.'),
  (@b40, 21, 37, 'Bet galiausiai jis išsiuntė pas juos savo sūnų, sakydamas: ‘Jie gerbs mano sūnų’.'),
  (@b40, 21, 38, 'Bet kai žemdirbiai pamatė sūnų, jie kalbėjo tarpusavyje: ‘Šitas yra paveldėtojas; eime, užmuškime jį ir užgrobkime jo paveldą’.'),
  (@b40, 21, 39, 'Ir jie pagavo jį, išmetė iš vynuogyno ir jį užmušė.'),
  (@b40, 21, 40, 'Taigi kai ateis vynuogyno viešpats, ką jis padarys šitiems žemdirbiams?“'),
  (@b40, 21, 41, 'Jie sako jam: „Jis žiauriai sunaikins šituos nedorėlius ir išnuomos savo vynuogyną kitiems žemdirbiams, kurie atiduos jam vaisius jų laikais“.'),
  (@b40, 21, 42, 'Jėzus sako jiems: „Ar niekada neskaitėte Raštuose: ‘Tas akmuo, kurį statytojai atmetė, tapo kertės pagrindu; tai yra Viešpaties darbas, ir tai nuostabu mūsų akyse’?'),
  (@b40, 21, 43, 'Todėl sakau jums: Dievo karalystė bus atimta iš jūsų ir duota tautai, kuri neš jos vaisius.'),
  (@b40, 21, 44, 'Ir kas ant šito akmens kris, susilaužys; bet ant ko jis nukris, tą sutrins į miltus“.'),
  (@b40, 21, 45, 'Ir kai vyriausieji kunigai ir fariziejai išgirdo jo palyginimus, jie suprato, kad jis kalbėjo apie juos.'),
  (@b40, 21, 46, 'Bet kai jie siekė pridėti prie jo rankas, jie pabijojo minios, nes jie laikė jį pranašu.'),
  (@b40, 22, 1, 'Ir Jėzus atsakė ir vėl kalbėjo jiems palyginimais, ir tarė:'),
  (@b40, 22, 2, '„Dangaus karalystė prilygsta vienam karaliui, kuris paruošė savo sūnui sutuoktuves'),
  (@b40, 22, 3, 'ir išsiuntė savo tarnus pašaukti tuos, kurie buvo pakviesti į vestuves; o jie nenorėjo ateiti.'),
  (@b40, 22, 4, 'Vėlgi jis išsiuntė kitus tarnus, sakydamas: ‘Pasakyk tiems, kurie yra pakviesti: „Štai aš esu paruošęs savo pietus – mano jaučiai ir peniukšliai papjauti, ir viskas paruošta – ateikite į sutuoktuves“’.'),
  (@b40, 22, 5, 'Bet jie nežiūrėjo į tai rimtai ir nuėjo sau: vienas į savo ūkį, kitas prie savo prekybos;'),
  (@b40, 22, 6, 'o likusieji paėmė jo tarnus ir išniekino juos, ir užmušė.'),
  (@b40, 22, 7, 'Bet kai karalius apie tai išgirdo, jis užsirūstino; ir jis išsiuntė savo kariuomenes ir sunaikino tuos žmogžudžius, ir sudegino jų miestą.'),
  (@b40, 22, 8, 'Po to jis sako savo tarnams: ‘Vestuvės yra paruoštos, bet tie, kurie buvo pakviesti, nebuvo verti.'),
  (@b40, 22, 9, 'Todėl eikite į vieškelius ir visus, kuriuos tik rasite, kvieskite į sutuoktuves’.'),
  (@b40, 22, 10, 'Taigi tie tarnai išėjo į vieškelius ir surinko visus, kuriuos tik rado, tiek blogus, tiek gerus; ir vestuvės buvo aprūpintos svečiais.'),
  (@b40, 22, 11, 'Ir kai karalius įėjo pamatyti svečių, jis pamatė ten žmogų, kuris nebuvo apsirengęs vestuviniu drabužiu;'),
  (@b40, 22, 12, 'ir jis jam sako: ‘Drauge, kaip tu čia įėjai neturėdamas vestuvinio drabužio?’ Ir jis tylėjo.'),
  (@b40, 22, 13, 'Tuomet karalius tarė tarnams: ‘Suriškite jam rankas bei kojas ir išveskite jį, ir įmeskite į išorinę tamsą; ten bus verksmas ir dantų griežimas’.'),
  (@b40, 22, 14, 'Nes daug yra pašauktų, bet maža išrinktų“.'),
  (@b40, 22, 15, 'Tada fariziejai nuėjo ir tarėsi, kaip jie galėtų jį prigauti jo kalboje.'),
  (@b40, 22, 16, 'Ir jie išsiuntė pas jį savo mokinius su erodininkais, sakydami: „Mokytojau, žinome, kad esi teisus bei mokai Dievo kelio tiesoje ir nepataikauji nei vienam; nes tu neatsižvelgi į žmonių asmenis.'),
  (@b40, 22, 17, 'Todėl pasakyk mums: kaip tu galvoji? Ar teisėta duoti duoklę ciesoriui, ar ne?“'),
  (@b40, 22, 18, 'Bet Jėzus suprato jų nedorybę ir tarė: „Kodėl mane gundote, veidmainiai?'),
  (@b40, 22, 19, 'Parodykite man duoklės pinigą!“ Ir jie atnešė jam denarą.'),
  (@b40, 22, 20, 'Ir jis sako jiems: „Kieno čia atvaizdas ir įrašas?“'),
  (@b40, 22, 21, 'Jie sako jam: „Ciesoriaus“. Tada jis sako jiems: „Todėl atiduokite kas ciesoriaus – ciesoriui; o kas Dievo – Dievui“.'),
  (@b40, 22, 22, 'Išgirdę šiuos žodžius jie stebėjosi ir paliko jį, ir nuėjo.'),
  (@b40, 22, 23, 'Tą pačią dieną atėjo pas jį sadukiejai, kurie sako, kad nėra prisikėlimo, ir klausė jo,'),
  (@b40, 22, 24, 'sakydami: „Mokytojau, Mozė sakė: ‘Jei vyras miršta ir neturi vaikų, jo brolis teveda jo žmoną ir teprikelia savo broliui sėklą’.'),
  (@b40, 22, 25, 'Na, o pas mus buvo septyni broliai; ir pirmasis, vedęs žmoną, mirė ir, neturėdamas palikuonio, paliko savo žmoną savo broliui;'),
  (@b40, 22, 26, 'taip pat ir antrasis, ir trečiasis, iki septintojo.'),
  (@b40, 22, 27, 'Ir po jų visų numirė ir ta moteris.'),
  (@b40, 22, 28, 'Tad prisikėlime kurio iš septynių ji bus žmona? Nes jie visi ją turėjo“.'),
  (@b40, 22, 29, 'Jėzus atsakydamas tarė jiems: „Jūs klystate nepažinodami nei Raštų, nei Dievo galios.'),
  (@b40, 22, 30, 'Nes prisikėlime jie nei veda, nei teka, bet yra kaip Dievo angelai danguje.'),
  (@b40, 22, 31, 'Bet kas dėl mirusiųjų prisikėlimo, argi neskaitėte to, kas jums buvo kalbėta Dievo, sakant:'),
  (@b40, 22, 32, '‘Aš esu Abraomo Dievas ir Izaoko Dievas, ir Jokūbo Dievas’? Dievas nėra mirusiųjų Dievas, bet gyvųjų“.'),
  (@b40, 22, 33, 'Ir kai minia tai išgirdo, jie buvo nustebinti jo mokslo.'),
  (@b40, 22, 34, 'Bet kai fariziejai išgirdo, kad jis nutildė sadukiejus, jie susirinko kartu.'),
  (@b40, 22, 35, 'Tada vienas iš jų, įstatymininkas, paklausė jo gundydamas jį ir sakydamas:'),
  (@b40, 22, 36, '„Mokytojau, kuris įsakymas yra didis įstatyme?“'),
  (@b40, 22, 37, 'Jėzus jam tarė: „‘Mylėk Viešpatį savo Dievą visa savo širdimi ir visa savo siela, ir visu savo protu’.'),
  (@b40, 22, 38, 'Šis yra pirmasis ir didis įsakymas.'),
  (@b40, 22, 39, 'Ir antrasis panašus į jį: ‘Mylėk savo artimą kaip save patį’.'),
  (@b40, 22, 40, 'Ant šitų dviejų įsakymų kybo visas įstatymas ir pranašai“.'),
  (@b40, 22, 41, 'Kol fariziejai tebebuvo susirinkę, Jėzus paklausė jų,'),
  (@b40, 22, 42, 'sakydamas: „Ką galvojate apie Kristų? Kieno jis yra sūnus?“ Jie sako jam: „Dovydo Sūnus“.'),
  (@b40, 22, 43, 'Jis sako jiems: „Kaipgi tada Dovydas dvasioje vadina jį Viešpačiu, sakydamas:'),
  (@b40, 22, 44, '‘VIEŠPATS tarė mano Viešpačiui: Sėskis mano dešinėje, kol padarysiu tavo priešus tavo pakoju’?'),
  (@b40, 22, 45, 'Tad jei Dovydas vadina jį Viešpačiu, kaipgi jis yra jo sūnus?“'),
  (@b40, 22, 46, 'Ir nei vienas negalėjo jam nei žodžio atsakyti, nei nedrįso niekas nuo tos dienos jo daugiau klausinėti.'),
  (@b40, 23, 1, 'Tada Jėzus kalbėjo miniai ir savo mokiniams,'),
  (@b40, 23, 2, 'sakydamas: „Raštininkai ir fariziejai sėdi Mozės krasėje;'),
  (@b40, 23, 3, 'todėl visko, ko jie liepia jums laikytis, to laikykitės ir darykite; bet nedarykite pagal jų darbus; nes jie sako, bet nedaro.'),
  (@b40, 23, 4, 'Nes jie riša sunkias ir nepanešamas naštas ir užkrauna jas ant žmonių pečių; bet jie patys nenori jų nei vienu savo pirštu pajudinti.'),
  (@b40, 23, 5, 'Bet visus savo darbus jie daro, kad būtų žmonių matomi; jie pasidaro plačius savo filakterius ir pasididina savo drabužių kraštus,'),
  (@b40, 23, 6, 'ir mėgsta aukščiausias vietas pokyliuose bei pirmuosius krėslus sinagogose,'),
  (@b40, 23, 7, 'ir sveikinimus turguose, ir kad žmonės juos vadintų ‘Rabi, Rabi’.'),
  (@b40, 23, 8, 'Bet jūs nesivadinkite ‘Rabi’, nes vienas yra jūsų Mokytojas – Kristus; o jūs visi esate broliai.'),
  (@b40, 23, 9, 'Ir nei vieno nevadinkite savo tėvu žemėje, nes vienas yra jūsų Tėvas, kuris yra danguje.'),
  (@b40, 23, 10, 'Nei vadinkitės mokytojais, nes vienas yra jūsų Mokytojas – Kristus.'),
  (@b40, 23, 11, 'Bet tas, kuris yra didžiausias tarp jūsų, bus jūsų tarnas.'),
  (@b40, 23, 12, 'Ir kas save aukštins, bus pažemintas; o kas nusižemins, bus išaukštintas“.'),
  (@b40, 23, 13, '„Bet vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs užrakinate nuo žmonių dangaus karalystę; nes nei jūs patys neįeinate, nei į ją įeinantiems neleidžiate įeiti.'),
  (@b40, 23, 14, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs suryjate našlių namus, ir apsimestinai kalbate ilgą maldą; todėl jūs gausite didesnį pasmerkimą.'),
  (@b40, 23, 15, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs apkeliaujate jūrą ir sausumą, kad padarytumėte nors vieną prozelitu, ir kai jis tampa, jūs padarote jį už save dvigubai didesniu pragaro vaiku.'),
  (@b40, 23, 16, 'Vargas jums, akli vadai, kurie sakote: ‘Kas prisieks šventykla, tai nieko; bet kas prisieks šventyklos auksu, tas yra skolininkas’!'),
  (@b40, 23, 17, 'Jūs, kvailiai ir akli, kas gi yra didesnis – auksas ar šventykla, kuri pašvenčia auksą?'),
  (@b40, 23, 18, 'Ir: ‘Kas prisieks aukuru, tai nieko; bet kas prisieks dovana, kuri yra ant jo, tas yra kaltas’.'),
  (@b40, 23, 19, 'Jūs, kvailiai ir akli, kas gi didesnis – dovana ar aukuras, kuris pašvenčia dovaną?'),
  (@b40, 23, 20, 'Todėl kas prisieks aukuru, prisiekia juo ir viskuo, kas ant jo.'),
  (@b40, 23, 21, 'Ir kas prisieks šventykla, prisiekia ja ir tuo, kuris gyvena joje.'),
  (@b40, 23, 22, 'Ir kas prisieks dangumi, tas prisiekia Dievo sostu ir tuo, kuris sėdi ant jo.'),
  (@b40, 23, 23, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs mokate dešimtinę nuo mėtų ir anyžių bei kmynų, o nepaisote svarbesnių įstatymo dalykų – teismo, gailestingumo ir tikėjimo – šituos turėtumėte padaryti ir nepalikti kito nepadaryto.'),
  (@b40, 23, 24, 'Jūs akli vedliai, kurie iškošiate mašalėlį, o praryjate kupranugarį.'),
  (@b40, 23, 25, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs švarinate taurės ir dubens išorę, bet viduje jie pilni plėšikavimo ir nesaikingumo.'),
  (@b40, 23, 26, 'Aklas fariziejau, pirmiau išvalyk tai, kas yra taurės ir dubens viduje, kad ir jų išorė būtų švari.'),
  (@b40, 23, 27, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs panašūs į pabaltintus kapus, kurie iš tikro atrodo gražūs iš išorės, bet viduje yra pilni numirėlių kaulų ir visokių nešvarumų.'),
  (@b40, 23, 28, 'Taip ir jūs išoriškai atrodote žmonėms teisūs, bet viduje esate pilni veidmainystės ir neteisybės.'),
  (@b40, 23, 29, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs statote pranašų antkapius ir puošiate teisiųjų kapus,'),
  (@b40, 23, 30, 'ir sakote: ‘Jei būtume buvę mūsų tėvų dienomis, nebūtume su jais buvę bendrininkai pranašų kraujyje’.'),
  (@b40, 23, 31, 'Todėl jūs patys sau liudininkai, kad esate vaikai tų, kurie užmušė pranašus.'),
  (@b40, 23, 32, 'Tad pripildykite savo tėvų saiką.'),
  (@b40, 23, 33, 'Gyvatės jūs, angių palikuonys, kaip jūs galite pasprukti nuo pragaro pasmerkimo?'),
  (@b40, 23, 34, 'Todėl štai aš siunčiu jums pranašus, išminčius ir raštininkus; vienus iš jų užmušite ir nukryžiuosite; kitus iš jų plaksite savo sinagogose ir persekiosite juos iš miesto į miestą;'),
  (@b40, 23, 35, 'kad ant jūsų ateitų visas teisus kraujas, pralietas žemėje, nuo teisiojo Abelio kraujo iki Barachijo sūnaus Zacharijo kraujo, kurį nužudėte tarp šventyklos ir aukuro.'),
  (@b40, 23, 36, 'Iš tiesų sakau jums: visa tai ateis ant šitos kartos.'),
  (@b40, 23, 37, 'O Jeruzale, Jeruzale, žudanti pranašus ir užmėtanti akmenimis tuos, kurie yra pas tave siųsti; kiek kartų norėjau surinkti tavo vaikus, kaip višta surenka savo viščiukus po savo sparnais, o jūs nenorėjote!'),
  (@b40, 23, 38, 'Štai jūsų namai palikti jums tušti.'),
  (@b40, 23, 39, 'Nes sakau jums: nuo šiol manęs nematysite, kol netarsite: ‘Palaimintas tas, kuris ateina Viešpaties vardu!’“'),
  (@b40, 24, 1, 'Ir Jėzus išėjo ir pasitraukė nuo šventyklos; ir jo mokiniai atėjo pas jį, kad parodytų jam šventyklos pastatus.'),
  (@b40, 24, 2, 'Ir Jėzus jiems tarė: „Argi nematote viso šito? Iš tiesų sakau jums: čia nebus palikto akmens ant akmens, kuris nebūtų nugriautas“.'),
  (@b40, 24, 3, 'Ir jam sėdint ant Alyvų kalno, mokiniai atėjo atskirai pas jį, sakydami: „Pasakyk mums, kada tai bus? Ir koks bus tavo atėjimo ir pasaulio pabaigos ženklas?“'),
  (@b40, 24, 4, 'Ir Jėzus atsakydamas tarė jiems: „Žiūrėkite, kad niekas jūsų nesuklaidintų.'),
  (@b40, 24, 5, 'Nes daugelis ateis mano vardu, sakydami: ‘Aš esu Kristus’; ir daugelį suklaidins.'),
  (@b40, 24, 6, 'Ir išgirsite apie karus ir karų gandus; žiūrėkite, kad nebūtumėte sunerimę; nes visa tai turi įvykti, bet tai – dar ne galas.'),
  (@b40, 24, 7, 'Nes tauta sukils prieš tautą ir karalystė prieš karalystę; ir bus badmečių, ir marų, ir žemės drebėjimų įvairiose vietose.'),
  (@b40, 24, 8, 'Visa tai yra sielvartų pradžia.'),
  (@b40, 24, 9, 'Tada jie atiduos jus kančiai ir jus žudys; ir jūsų nekęs visos tautos dėl mano vardo.'),
  (@b40, 24, 10, 'Ir tada daugelis pasipiktins ir išdavinės vieni kitus, ir vieni kitų nekęs.'),
  (@b40, 24, 11, 'Ir kils daug netikrų pranašų ir daugelį suklaidins.'),
  (@b40, 24, 12, 'Ir kadangi gausės neteisybė, daugelio meilė atšals.'),
  (@b40, 24, 13, 'Bet kas ištvers iki galo, tas bus išgelbėtas.'),
  (@b40, 24, 14, 'Ir ši karalystės evangelija bus paskelbta visame pasaulyje paliudyti visoms tautoms; ir tada ateis galas.'),
  (@b40, 24, 15, 'Todėl kai pamatysite per pranašą Danielių kalbėtą suniokojimo bjaurybę, stovinčią šventoje vietoje (kas skaito, tegul supranta),'),
  (@b40, 24, 16, 'tuomet, esantys Judėjoje, tebėga į kalnus;'),
  (@b40, 24, 17, 'esantys ant namo stogo, tenelipa žemyn pasiimti ko nors iš savo namų;'),
  (@b40, 24, 18, 'ir esantys ant lauko, tenegrįžta pasiimti savo drabužių.'),
  (@b40, 24, 19, 'Ir vargas nėščioms bei žindančioms tomis dienomis!'),
  (@b40, 24, 20, 'Bet melskitės, kad jums netektų bėgti žiemą ar sabato dieną,'),
  (@b40, 24, 21, 'nes tuomet bus didelis suspaudimas, kokio nėra buvę nuo pasaulio pradžios iki dabar, nei niekada nebebus.'),
  (@b40, 24, 22, 'Ir jei tos dienos nebūtų sutrumpintos, nei vienas kūnas nebūtų išgelbėtas; bet dėl išrinktųjų tos dienos bus sutrumpintos.'),
  (@b40, 24, 23, 'Jei tada kas nors jums sakys: ‘Štai čia Kristus’, arba ‘Tenai!’, – netikėkite.'),
  (@b40, 24, 24, 'Nes kils netikrų kristų ir netikrų pranašų ir parodys didžių ženklų ir stebuklų; taip, kad, jei būtų įmanoma, jie suklaidintų pačius išrinktuosius.'),
  (@b40, 24, 25, 'Štai pasakiau jums iš anksto.'),
  (@b40, 24, 26, 'Todėl jei jie sakys jums: ‘Štai jis dykumoje’, – neikite; ‘Štai jis slaptuose kambariuose’, – netikėkite tuo.'),
  (@b40, 24, 27, 'Nes kaip iš rytų išeina žaibas ir nušvinta iki vakarų; toks bus ir žmogaus Sūnaus atėjimas.'),
  (@b40, 24, 28, 'Nes kur yra lavonų, ten ir ereliai bus susirinkę.'),
  (@b40, 24, 29, 'Tuoj pat po tų dienų suspaudimo užtems saulė ir mėnulis nebeduos savo šviesos, ir žvaigždės kris iš dangaus, ir dangų jėgos bus sudrebintos;'),
  (@b40, 24, 30, 'ir tada danguje pasirodys žmogaus Sūnaus ženklas; ir tada visos žemės gentys raudos, ir jie pamatys žmogaus Sūnų ateinantį dangaus debesyse su jėga ir didžia šlove.'),
  (@b40, 24, 31, 'Ir jis pasiųs savo angelus su didžiu trimito garsu, ir jie surinks jo išrinktuosius iš keturių vėjų, nuo vieno dangaus galo iki kito.'),
  (@b40, 24, 32, 'Dabar pasimokykite palyginimo iš figmedžio: kai jo šaka jau minkšta ir išleidžia lapus, jūs žinote, kad vasara arti;'),
  (@b40, 24, 33, 'taip pat ir jūs, kai matysite visa tai, žinokite, kad tai arti, prie durų.'),
  (@b40, 24, 34, 'Iš tiesų sakau jums: ši karta nepraeis, kol visa tai išsipildys.'),
  (@b40, 24, 35, 'Dangus ir žemė praeis, bet mano žodžiai nepraeis“.'),
  (@b40, 24, 36, '„Bet tos dienos ir valandos nežino niekas, ne, nei dangaus angelai, bet tik mano Tėvas.'),
  (@b40, 24, 37, 'Bet kaip buvo Nojaus dienos, toks bus ir žmogaus Sūnaus atėjimas.'),
  (@b40, 24, 38, 'Nes kaip dienomis prieš tvaną jie valgė ir gėrė, tuokėsi ir tekėjo iki tos dienos, kai Nojus įžengė į arką,'),
  (@b40, 24, 39, 'ir nežinojo, kol užėjo tvanas ir pasiėmė juos visus; toks bus ir žmogaus Sūnaus atėjimas.'),
  (@b40, 24, 40, 'Tada du bus ant lauko; vienas bus paimtas, o kitas paliktas.'),
  (@b40, 24, 41, 'Dvi moterys mals malūne; viena bus paimta, o kita palikta.'),
  (@b40, 24, 42, 'Todėl budėkite; nes nežinote, kurią valandą jūsų Viešpats ateina.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b40, 24, 43, 'Bet žinokite tai: jei namų šeimininkas būtų žinojęs, per kurį budėjimą ateis vagis, jis būtų budėjęs ir nebūtų leidęs įsilaužti į jo namus.'),
  (@b40, 24, 44, 'Todėl būkite ir jūs pasiruošę; nes žmogaus Sūnus ateina tą valandą, kurią nemanote.'),
  (@b40, 24, 45, 'Kas tada yra ištikimas ir išmintingas tarnas, kurį jo viešpats paskyrė valdyti savo namiškius, duoti jiems maisto skirtu laiku?'),
  (@b40, 24, 46, 'Palaimintas yra tas tarnas, kurį atėjęs viešpats ras taip bedarantį.'),
  (@b40, 24, 47, 'Iš tiesų sakau jums, kad jis paskirs jį valdyti visų savo turtų.'),
  (@b40, 24, 48, 'Bet jei anas piktas tarnas tars savo širdyje: ‘Mano viešpats delsia ateiti’;'),
  (@b40, 24, 49, 'ir pradės mušti savo bendratarnius ir valgyti bei gerti su girtuokliais;'),
  (@b40, 24, 50, 'to tarno viešpats ateis tą dieną, kai jis jo nelaukia, ir tą valandą, kurios jis nežino,'),
  (@b40, 24, 51, 'ir perkirs jį pusiau, ir paskirs jam jo dalį su veidmainiais; ten bus verksmas ir dantų griežimas“.'),
  (@b40, 25, 1, '„Tada dangaus karalystė bus panaši į dešimtį mergelių, kurios pasiėmė savo žibintus ir išėjo pasitikti jaunikio.'),
  (@b40, 25, 2, 'Penkios iš jų buvo išmintingos ir penkios kvailos.'),
  (@b40, 25, 3, 'Tos, kurios buvo kvailos, pasiėmė savo žibintus, o nepasiėmė aliejaus;'),
  (@b40, 25, 4, 'bet išmintingos kartu su žibintais pasiėmė aliejaus savo induose.'),
  (@b40, 25, 5, 'Kol jaunikis užtruko, jos visos prisnūdo ir užmigo.'),
  (@b40, 25, 6, 'Ir vidurnaktį pasigirdo šauksmas: ‘Štai jaunikis ateina; išeikite jo pasitikti!’'),
  (@b40, 25, 7, 'Tada visos tos mergelės atsikėlė ir pasiruošė žibintus.'),
  (@b40, 25, 8, 'Ir kvailosios tarė išmintingosioms: ‘Duokite mums savo aliejaus; nes mūsų žibintai užgeso’.'),
  (@b40, 25, 9, 'Bet išmintingosios atsakė tardamos: ‘Ne; kad kartais nepritrūktų ir mums, ir jums; bet eikite verčiau pas tuos, kurie pardavinėja, ir nusipirkite’.'),
  (@b40, 25, 10, 'Ir joms nuėjus pirkti, atėjo jaunikis; ir tos, kurios buvo pasiruošusios, įėjo su juo į sutuoktuves, ir durys buvo uždarytos.'),
  (@b40, 25, 11, 'Po to atėjo ir kitos mergelės, sakydamos: ‘Viešpatie, Viešpatie, atidaryk mums’.'),
  (@b40, 25, 12, 'Bet jis atsakydamas tarė: ‘Iš tiesų sakau jums, aš jūsų nepažįstu’.'),
  (@b40, 25, 13, 'Todėl budėkite, nes nežinote nei dienos, nei valandos, kurią ateina žmogaus Sūnus.'),
  (@b40, 25, 14, 'Nes dangaus karalystė yra kaip žmogus, keliaujantis į tolimą šalį, kuris pasišaukė savo tarnus ir įteikė jiems savo turtą.'),
  (@b40, 25, 15, 'Ir vienam jis davė penkis talentus, kitam – du, o kitam – vieną; kiekvienam pagal jų skirtingus sugebėjimus; ir tuojau iškeliavo.'),
  (@b40, 25, 16, 'Tada tas, kuris gavo penkis talentus, išėjo ir jais vertėsi, ir uždirbo tiems kitus penkis.'),
  (@b40, 25, 17, 'Ir taip pat tas, kuris gavo du, jis irgi uždirbo kitus du.'),
  (@b40, 25, 18, 'Bet tas, kuris gavo vieną, išėjo ir pakasė žemėje, ir paslėpė savo viešpaties pinigus.'),
  (@b40, 25, 19, 'Po ilgo laiko ateina tų tarnų viešpats ir atsiskaitinėja su jais.'),
  (@b40, 25, 20, 'Ir atėjo tas, kuris buvo gavęs penkis talentus, ir atnešė kitus penkis talentus, sakydamas: ‘Viešpatie, tu įteikei man penkis talentus; štai be tų uždirbau dar penkis talentus’.'),
  (@b40, 25, 21, 'Jo viešpats tarė jam: ‘Gerai atlikta, gerasis ir ištikimasis tarne; tu buvai ištikimas keliuose dalykuose, aš padarysiu tave daugelio dalykų valdovu; įeik į savo viešpaties džiaugsmą’.'),
  (@b40, 25, 22, 'Taip pat ir tas, kuris buvo gavęs du talentus, atėjo ir tarė: ‘Viešpatie, tu įteikei man du talentus; štai be tų uždirbau kitus du talentus’.'),
  (@b40, 25, 23, 'Jo viešpats tarė jam: ‘Gerai atlikta, gerasis ir ištikimasis tarne; tu buvai ištikimas keliuose dalykuose, aš padarysiu tave daugelio dalykų valdovu; įeik į savo viešpaties džiaugsmą’.'),
  (@b40, 25, 24, 'Tada tas, kuris buvo gavęs vieną talentą, atėjo ir tarė: ‘Viešpatie, žinojau, kad esi kietas žmogus; pjauni, kur nesėjai, ir renki, kur nebarstei;'),
  (@b40, 25, 25, 'ir aš išsigandęs nuėjau ir paslėpiau tavo talentą žemėje; štai turi, kas tavo’.'),
  (@b40, 25, 26, 'Jo viešpats atsakydamas tarė jam: ‘Nedoras ir tingus tarne, tu žinojai, kad pjaunu, kur nesėjau, ir renku, kur nebarsčiau;'),
  (@b40, 25, 27, 'todėl turėjai duoti mano pinigus keitėjams, ir tada mano atėjimui būčiau gavęs, kas mano, su palūkanomis.'),
  (@b40, 25, 28, 'Todėl atimkite iš jo talentą ir duokite jį tam, kuris turi dešimt talentų.'),
  (@b40, 25, 29, 'Nes kiekvienam, kuris turi, bus duota, ir jis turės apsčiai; bet iš to, kuris neturi, bus atimta ir tai, ką jis turi.'),
  (@b40, 25, 30, 'Ir įmeskite nenaudingąjį tarną į išorinę tamsą; ten bus verksmas ir dantų griežimas’“.'),
  (@b40, 25, 31, '„Kai žmogaus Sūnus ateis savo šlovėje, ir su juo visi šventi angelai, tada jis atsisės savo šlovės soste;'),
  (@b40, 25, 32, 'ir prieš jį bus surinktos visos tautos, ir jis atskirs jas vieną nuo kitos, kaip piemuo atskiria savo avis nuo ožkų;'),
  (@b40, 25, 33, 'ir jis pastatys avis savo dešinėje, bet ožkas kairėje.'),
  (@b40, 25, 34, 'Tada Karalius sakys tiems jo dešinėje: ‘Ateikite, mano Tėvo palaimintieji, paveldėkite karalystę, paruoštą jums nuo pasaulio įkūrimo;'),
  (@b40, 25, 35, 'nes aš buvau išalkęs, ir jūs davėte man maisto; buvau ištroškęs, ir jūs davėte man atsigerti; buvau ateivis, ir jūs priėmėte mane;'),
  (@b40, 25, 36, 'nuogas, ir jūs mane aprengėte; sirgau, ir jūs mane aplankėte; buvau kalėjime, ir jūs atėjote pas mane’.'),
  (@b40, 25, 37, 'Tada teisieji atsakys jam, tardami: ‘Viešpatie, kada matėme tave išalkusį, ir tave pavalgydinome? Arba ištroškusį, ir davėme tau gerti?'),
  (@b40, 25, 38, 'Kada matėme tave ateiviu ir tave priėmėme? Arba nuogą, ir tave aprengėme?'),
  (@b40, 25, 39, 'Arba kada matėme tave sergantį ar kalėjime ir atėjome pas tave?’'),
  (@b40, 25, 40, 'Ir Karalius atsakys ir tars jiems: ‘Iš tiesų sakau jums: taip, kaip tai padarėte vienam iš šitų mažiausių mano brolių, taip man padarėte’.'),
  (@b40, 25, 41, 'Tada jis tars ir tiems kairėje: ‘Eikite nuo manęs, prakeiktieji, į amžinąją ugnį, paruoštą velniui ir jo angelams;'),
  (@b40, 25, 42, 'nes buvau išalkęs, ir jūs nedavėte man maisto; buvau ištroškęs, ir jūs nedavėte man atsigerti;'),
  (@b40, 25, 43, 'buvau ateivis, ir jūs manęs nepriėmėte; nuogas, ir jūs manęs neaprengėte; sergantis ir kalėjime, ir jūs manęs neaplankėte’.'),
  (@b40, 25, 44, 'Tada ir jie atsakys jam, tardami: ‘Viešpatie, kada matėme tave išalkusį ar ištroškusį, ar ateivį, ar nuogą, ar sergantį, ar kalėjime ir tau nepatarnavome?’'),
  (@b40, 25, 45, 'Tada jis atsakys jiems, tardamas: ‘Iš tiesų sakau jums: taip, kaip to nepadarėte vienam iš šitų mažiausiųjų, taip nepadarėte man’.'),
  (@b40, 25, 46, 'Ir šitie nueis į amžinąją bausmę; o teisieji – į amžinąjį gyvenimą“.'),
  (@b40, 26, 1, 'Ir įvyko, kai Jėzus baigė visus šiuos pasakymus, jis tarė savo mokiniams:'),
  (@b40, 26, 2, '„Žinote, kad po dviejų dienų yra Apėjimo šventė, ir žmogaus Sūnus bus išduotas nukryžiavimui“.'),
  (@b40, 26, 3, 'Tada susirinko vyriausieji kunigai ir raštininkai, ir tautos vyresnieji į rūmus aukščiausiojo kunigo, kuris buvo vardu Kajafas,'),
  (@b40, 26, 4, 'ir tarėsi, kad suimtų Jėzų klasta ir jį užmuštų.'),
  (@b40, 26, 5, 'Bet jie sakė: „Ne šventės dieną, kad nekiltų tautoje triukšmas“.'),
  (@b40, 26, 6, 'Na, o kai Jėzus buvo Betanijoje, Simono raupsuotojo namuose,'),
  (@b40, 26, 7, 'pas jį atėjo moteris, turinti alebastrinę labai brangaus tepalo dėžutę, ir išliejo jį jam ant galvos, kai jis sėdėjo prie valgio.'),
  (@b40, 26, 8, 'Bet tai pamatę jo mokiniai pasipiktino, sakydami: „Kokiam tikslui šis eikvojimas?'),
  (@b40, 26, 9, 'Nes šį tepalą būtų buvę galima už daug parduoti ir išdalyti vargšams“.'),
  (@b40, 26, 10, 'Kai Jėzus tai suprato, jis jiems tarė: „Kodėl varginate moterį? Nes ji atliko ant manęs gerą darbą.'),
  (@b40, 26, 11, 'Nes jūs visada turite vargšų su savimi; bet mane ne visada turite.'),
  (@b40, 26, 12, 'Nes, išpildama šitą tepalą ant mano kūno, ji padarė tai mano laidotuvėms.'),
  (@b40, 26, 13, 'Iš tiesų sakau jums: kur tik ši evangelija bus skelbiama visame pasaulyje, ten bus pasakojama jos atminimui ir tai, ką ši moteris padarė“.'),
  (@b40, 26, 14, 'Tada vienas iš dvylikos, vadinamas Judu Iskarijotu, nuėjo pas vyriausiuosius kunigus'),
  (@b40, 26, 15, 'ir jiems tarė: „Ką man duosite; ir aš jums jį įduosiu?“ Ir jie suderėjo su juo už trisdešimt sidabrinių.'),
  (@b40, 26, 16, 'Ir nuo to laiko jis ieškojo progos jį išduoti.'),
  (@b40, 26, 17, 'Na, o pirmąją neraugintos duonos šventės dieną mokiniai atėjo pas Jėzų, sakydami jam: „Kur nori, kad tau paruoštume valgyti Apėjimą?“'),
  (@b40, 26, 18, 'Ir jis tarė: „Eikite į miestą pas tokį žmogų ir jam sakykite: ‘Mokytojas sako: „Mano metas čia pat; aš švęsiu tavo namuose Apėjimą su savo mokiniais“’“.'),
  (@b40, 26, 19, 'Ir mokiniai padarė, kaip Jėzus jiems nurodė; ir jie paruošė Apėjimą.'),
  (@b40, 26, 20, 'Na, o kai atėjo vakaras, jis atsisėdo su dvylika.'),
  (@b40, 26, 21, 'Ir jiems valgant jis tarė: „Iš tiesų sakau jums, kad vienas iš jūsų mane išduos“.'),
  (@b40, 26, 22, 'Ir jie be galo nuliūdo, ir kiekvienas iš jų pradėjo jam sakyti: „Viešpatie, ar tai aš?“'),
  (@b40, 26, 23, 'Ir jis atsakydamas tarė: „Tas, kuris su manimi mirko savo ranką dubenyje, mane išduos.'),
  (@b40, 26, 24, 'Žmogaus Sūnus eina, kaip apie jį yra parašyta; bet vargas tam žmogui, per kurį žmogaus Sūnus yra išduotas! Tam žmogui būtų buvę geriau, jeigu jis nebūtų gimęs“.'),
  (@b40, 26, 25, 'Tada Judas, kuris jį išdavė, atsakydamas tarė: „Mokytojau, ar tai aš?“ Jis jam tarė: „Tu pasakei“.'),
  (@b40, 26, 26, 'Ir kai jie valgė, Jėzus paėmė duoną ir palaimino ją, ir laužė ją, ir davė ją mokiniams, ir tarė: „Imkite, valgykite – tai yra mano kūnas“.'),
  (@b40, 26, 27, 'Ir jis paėmė taurę ir padėkojo, ir ją davė jiems, sakydamas: „Gerkite iš jos visi;'),
  (@b40, 26, 28, 'nes tai yra mano kraujas naujojo testamento, kuris yra išliejamas už daugelį nuodėmių atleidimui.'),
  (@b40, 26, 29, 'Bet sakau jums: aš nebegersiu šito vynmedžio vaisiaus nuo šiol iki tos dienos, kai gersiu jį naują su jumis savo Tėvo karalystėje“.'),
  (@b40, 26, 30, 'Ir sugiedoję himną jie išėjo į Alyvų kalną.'),
  (@b40, 26, 31, 'Tada Jėzus jiems sako: „Šią naktį jūs visi pasipiktinsite manimi; nes yra parašyta: ‘Aš smogsiu piemeniui, ir kaimenės avys išsisklaidys’.'),
  (@b40, 26, 32, 'Bet kai būsiu prisikėlęs, pirma jūsų eisiu į Galilėją“.'),
  (@b40, 26, 33, 'Petras atsakydamas tarė jam: „Nors ir visi tavimi pasipiktins, aš niekada nepasipiktinsiu“.'),
  (@b40, 26, 34, 'Jėzus jam tarė: „Iš tiesų sakau tau, kad šią naktį, prieš gaidžiui pragystant, tu triskart manęs išsiginsi“.'),
  (@b40, 26, 35, 'Petras jam tarė: „Nors man ir tektų mirti su tavimi, tačiau tavęs aš neišsiginsiu“. Taip pat sakė ir visi mokiniai.'),
  (@b40, 26, 36, 'Tada Jėzus su jais ateina į vietą, vadinamą Getsemane, ir sako mokiniams: „Sėskite čia, kol nuėjęs ten melsiuosi“.'),
  (@b40, 26, 37, 'Ir jis pasiėmė Petrą bei du Zebediejaus sūnus ir pradėjo sielvartauti ir labai liūdėti.'),
  (@b40, 26, 38, 'Tada jis sako jiems: „Mano siela nepaprastai nuliūdusi, iki mirties; likite čia ir budėkite su manimi“.'),
  (@b40, 26, 39, 'Ir jis paėjo truputį toliau, krito veidu į žemę ir meldėsi, sakydamas: „O mano Tėve, jei būtų įmanoma, teaplenkia mane šita taurė, tačiau ne kaip aš noriu, bet kaip tu nori“.'),
  (@b40, 26, 40, 'Ir jis ateina pas mokinius ir randa juos miegančius, ir sako Petrui „Ką, ar negalėjote pabudėti su manimi vieną valandą?'),
  (@b40, 26, 41, 'Budėkite ir melskitės, kad neįeitumėte į pagundą; dvasia iš tikrųjų yra norì, bet kūnas silpnas“.'),
  (@b40, 26, 42, 'Jis vėl nuėjo antrą kartą ir meldėsi, sakydamas: „O mano Tėve, jei ši taurė negali aplenkti manęs mano negerta, teįvyksta tavo valia“.'),
  (@b40, 26, 43, 'Ir jis atėjo ir vėl rado juos miegančius, nes jų akys buvo apsunkusios.'),
  (@b40, 26, 44, 'Ir jis paliko juos ir vėl nuėjo, ir meldėsi trečią kartą, sakydamas tuos pačius žodžius.'),
  (@b40, 26, 45, 'Tada jis ateina pas savo mokinius ir sako jiems: „Dabar miegokite ir ilsėkitės; štai valanda jau čia pat, ir žmogaus Sūnus yra išduotas į nusidėjėlių rankas.'),
  (@b40, 26, 46, 'Kelkitės, eime; štai tas, kuris mane išduoda, jau čia pat“.'),
  (@b40, 26, 47, 'Ir jam bekalbant štai atėjo Judas, vienas iš dvylikos, ir su juo didžiulė minia su kalavijais ir vėzdais, nuo vyriausiųjų kunigų ir tautos vyresniųjų.'),
  (@b40, 26, 48, 'Na, o tas, kuris jį išdavė, davė jiems ženklą, sakydamas: „Kurį pabučiuosiu, tai yra tas, suimkite jį“.'),
  (@b40, 26, 49, 'Ir nedelsiant jis atėjo pas Jėzų ir tarė: „Sveikas, mokytojau“, ir pabučiavo jį.'),
  (@b40, 26, 50, 'Ir Jėzus jam tarė: „Drauge, ko atėjai?“ Tada jie atėjo ir uždėjo ant Jėzaus rankas, ir suėmė jį.'),
  (@b40, 26, 51, 'Ir štai vienas iš tų, kurie buvo su Jėzumi, ištiesė savo ranką, ištraukė savo kalaviją, kirto aukščiausiojo kunigo tarnui ir nukirto jam ausį.'),
  (@b40, 26, 52, 'Tada Jėzus jam tarė: „Kišk savo kalaviją atgal į jo vietą, nes visi, kurie ima kalaviją, žus nuo kalavijo.'),
  (@b40, 26, 53, 'Tu manai, kad dabar negalėčiau melstis savo Tėvui, ir jis bematant neduotų man daugiau kaip dvylikos legionų angelų?'),
  (@b40, 26, 54, 'Bet kaip tad išsipildytų Raštai, kad šitaip turi būti?“'),
  (@b40, 26, 55, 'Tą pačią valandą Jėzus tarė minioms: „Ar išėjote kaip prieš vagį su kalavijais ir vėzdais manęs suimti? Kasdien sėdėjau su jumis, mokydamas šventykloje, o jūs nesuėmėte manęs.'),
  (@b40, 26, 56, 'Bet visa tai įvyko, kad išsipildytų pranašų Raštai“. Tada visi mokiniai jį paliko ir pabėgo.'),
  (@b40, 26, 57, 'Ir tie, kurie suėmė Jėzų, nuvedė jį pas aukščiausiąjį kunigą Kajafą, kur buvo susirinkę raštininkai ir vyresnieji.'),
  (@b40, 26, 58, 'Bet Petras sekė paskui jį iš tolo iki aukščiausiojo kunigo rūmų ir įėjo bei atsisėdo su tarnais pasižiūrėti pabaigos.'),
  (@b40, 26, 59, 'Na, o vyriausieji kunigai bei vyresnieji ir visa taryba ieškojo melagingo liudijimo prieš Jėzų, kad jį nužudytų,'),
  (@b40, 26, 60, 'bet nerado; taip, nors ir daug melagingų liudytojų atėjo, tačiau nei vieno nerado. Pagaliau atėjo du melagingi liudytojai'),
  (@b40, 26, 61, 'ir tarė: „Šitas sakė: ‘Galiu sugriauti Dievo šventyklą ir pastatyti ją per tris dienas’“.'),
  (@b40, 26, 62, 'Ir aukščiausiasis kunigas atsikėlė bei jam tarė: „Tu nieko neatsakai? Kas tai, ką šitie liudija prieš tave?“'),
  (@b40, 26, 63, 'Bet Jėzus tylėjo. Ir aukščiausiasis kunigas atsakė bei tarė jam: „Prisaikdinu tave gyvuoju Dievu, kad pasakytum mums, ar tu esi Kristus, Dievo Sūnus“.'),
  (@b40, 26, 64, 'Jėzus jam sako: „Tu pasakei; tačiau sakau jums: nuo šiol matysite žmogaus Sūnų sėdintį galios dešinėje ir ateinantį dangaus debesyse“.'),
  (@b40, 26, 65, 'Tada aukščiausiasis kunigas persiplėšė drabužius, sakydamas: „Jis piktžodžiavo; kam mums dar bereikia liudytojų? Štai dabar išgirdote jo piktžodžiavimą.'),
  (@b40, 26, 66, 'Ką galvojate?“ Jie atsakydami tarė: „Jis yra kaltas myriop“.'),
  (@b40, 26, 67, 'Tada jie spjaudė jam į veidą ir mušė jį; o kiti smogė jam rankų delnais,'),
  (@b40, 26, 68, 'sakydami: „Pranašauk mums, Kristau! Kas yra tas, kuris tau smogė?“'),
  (@b40, 26, 69, 'Na, o Petras sėdėjo rūmuose, lauke; ir prie jo priėjo panelė, sakydama: „Tu irgi buvai su Jėzumi iš Galilėjos“.'),
  (@b40, 26, 70, 'Bet jis išsigynė prieš juos visus, sakydamas: „Nežinau, ką sakai“.'),
  (@b40, 26, 71, 'Ir kai jis buvo išėjęs į prieangį, kita panelė pamatė jį ir tarė tiems, kurie ten buvo: „Šitas irgi buvo su Jėzumi iš Nazareto“.'),
  (@b40, 26, 72, 'Ir vėl jis išsigynė, prisiekdamas: „Nepažįstu to žmogaus“.'),
  (@b40, 26, 73, 'Ir po kiek laiko prie jo priėjo stovėjusieji šalia ir tarė Petrui: „Tikrai, tu irgi esi vienas iš jų; nes tavo kalba tave išduoda“.'),
  (@b40, 26, 74, 'Tada jis pradėjo keiktis ir prisiekinėti, sakydamas: „Nepažįstu to žmogaus“. Ir tuoj pat pragydo gaidys.'),
  (@b40, 26, 75, 'Ir Petras prisiminė Jėzaus žodį, kuris jam sakė: „Prieš gaidžiui pragystant tu triskart manęs išsiginsi“. Ir jis išėjo laukan ir karčiai verkė.'),
  (@b40, 27, 1, 'Kai atėjo rytas, visi vyriausieji kunigai ir tautos vyresnieji tarėsi prieš Jėzų, kad jį nužudytų;'),
  (@b40, 27, 2, 'ir jį surišę jie išvedė jį ir atidavė valdytojui Poncijui Pilotui.'),
  (@b40, 27, 3, 'Tada Judas, kuris jį išdavė, pamatęs, kad yra pasmerktas, gailėjosi ir nunešė atgal trisdešimt sidabrinių vyriausiems kunigams ir vyresniesiems,'),
  (@b40, 27, 4, 'sakydamas: „Aš nusidėjau išduodamas nekaltą kraują“. O jie tarė: „Kas mums darbo? Tu žiūrėkis“.'),
  (@b40, 27, 5, 'Ir jis numetė sidabrinius šventykloje ir išėjo, ir nuėjęs pasikorė.'),
  (@b40, 27, 6, 'Ir vyriausieji kunigai paėmė sidabrinius ir tarė: „Neteisėta jų dėti į iždą, nes tai yra kraujo kaina“.'),
  (@b40, 27, 7, 'Ir jie pasitarė ir už juos nupirko puodžiaus lauką ateiviams laidoti.'),
  (@b40, 27, 8, 'Dėl to tas laukas buvo vadinamas Kraujo lauku; iki šios dienos.'),
  (@b40, 27, 9, 'Tada išsipildė tai, kas buvo kalbėta per pranašą Jeremiją, sakant: „Ir jie paėmė trisdešimt sidabrinių, kainą to, kuris buvo įkainotas, kurį tie iš Izraelio vaikų įkainavo;'),
  (@b40, 27, 10, 'ir davė juos už puodžiaus lauką, kaip Viešpats man paskyrė“.'),
  (@b40, 27, 11, 'Ir Jėzus stovėjo prieš valdytoją; ir valdytojas jo paklausė, sakydamas: „Ar tu esi žydų Karalius?“ Ir Jėzus jam tarė: „Tu sakai“.'),
  (@b40, 27, 12, 'Ir kai jis buvo kaltinamas vyriausiųjų kunigų ir vyresniųjų, jis nieko neatsakė.'),
  (@b40, 27, 13, 'Tada jam Pilotas tarė: „Ar negirdi, kiek daug visko jie prieš tave liudija?“'),
  (@b40, 27, 14, 'Ir jis neatsakė jam nei į vieną žodį, kad net valdytojas didžiai stebėjosi.'),
  (@b40, 27, 15, 'Na, o per tą šventę valdytojas buvo pratęs paleisti tautai kalinį, kurio jie norėdavo.'),
  (@b40, 27, 16, 'Ir tuo metu jie turėjo žymų kalinį, vadinamą Barabu.'),
  (@b40, 27, 17, 'Todėl kai jie buvo susirinkę, Pilotas jiems tarė: „Kurį norite, kad jums paleisčiau? Barabą ar Jėzų, kuris vadinamas Kristumi?“'),
  (@b40, 27, 18, 'Nes jis žinojo, kad jie iš pavydo buvo jį įdavę.'),
  (@b40, 27, 19, 'Kai jis buvo atsisėdęs teismo krasėje, jo žmona jam siuntė, sakydama: „Neturėk jokių reikalų su šituo teisiu žmogumi, nes šią dieną sapne daug dėl jo kentėjau“.'),
  (@b40, 27, 20, 'Bet vyriausieji kunigai ir vyresnieji įkalbėjo minią, kad jie prašytų Barabo, o Jėzų sunaikintų.'),
  (@b40, 27, 21, 'Valdytojas atsakydamas tarė jiems: „Kurį iš tų dviejų norite, kad jums paleisčiau?“ Jie tarė: „Barabą“.'),
  (@b40, 27, 22, 'Pilotas jiems sako: „Tad ką man daryti su Jėzumi, kuris vadinamas Kristumi?“ Jie visi jam sako: „Tegul jis būna nukryžiuotas“.'),
  (@b40, 27, 23, 'Ir valdytojas tarė: „Kodėl, ką pikta jis padarė?“ Bet jie dar daugiau šaukė, sakydami: „Tebūna jis nukryžiuotas!“'),
  (@b40, 27, 24, 'Kai Pilotas pamatė, kad nieko negali laimėti, o tik sukilo sujudimas, jis paėmė vandens ir nusiplovė rankas minios akivaizdoje, sakydamas: „Aš nekaltas dėl šio teisiojo asmens kraujo – jūs žinokitės“.'),
  (@b40, 27, 25, 'Tada visa tauta atsakydama tarė: „Tebūna jo kraujas ant mūsų ir ant mūsų vaikų“.'),
  (@b40, 27, 26, 'Tada jis paleido jiems Barabą ir, nuplakdinęs Jėzų, atidavė jį nukryžiuoti.'),
  (@b40, 27, 27, 'Tada valdytojo kareiviai paėmė Jėzų į bendruosius rūmus, ir prie jo susirinko visas pulkas kareivių.'),
  (@b40, 27, 28, 'Ir jie nurengė jį ir apvilko ryškiai raudonu apsiaustu.'),
  (@b40, 27, 29, 'Ir nupynę erškėčių vainiką, jie dėjo jam jį ant galvos ir nendrę į jo dešinę ranką; ir jie klaupėsi prieš jį ant kelių ir tyčiojosi iš jo, sakydami: „Sveikas, žydų Karaliau!“'),
  (@b40, 27, 30, 'Ir jie spjaudė ant jo ir paėmė nendrę, ir smogė jam per galvą.'),
  (@b40, 27, 31, 'Ir pasityčioję iš jo jie nuėmė nuo jo apsiaustą ir apvilko jį jo paties drabužiu, ir išvedė jį nukryžiuoti.'),
  (@b40, 27, 32, 'Ir išėję jie užtiko žmogų iš Kirenės, vardu Simonas; jie privertė jį nešti jo kryžių.'),
  (@b40, 27, 33, 'Ir kai jie atėjo į vietą, vadinamą Golgota, tai reiškia į kaukolės vietą,'),
  (@b40, 27, 34, 'jie davė jam gerti acto, sumaišyto su tulžimi; ir jo paragavęs jis negėrė.'),
  (@b40, 27, 35, 'Ir jie nukryžiavo jį ir pasidalino jo drabužius, mesdami burtus; kad išsipildytų, kas buvo kalbėta per pranašą: „Jie tarpusavyje dalinosi mano drabužius ir dėl mano apdaro jie metė burtus“.'),
  (@b40, 27, 36, 'Ir jie sėdėdami ten jį saugojo;'),
  (@b40, 27, 37, 'ir virš jo galvos įtaisė užrašytą kaltinimą jam: „ŠITAS YRA JĖZUS, ŽYDŲ KARALIUS“.'),
  (@b40, 27, 38, 'Tada su juo buvo nukryžiuoti du vagys, vienas iš dešinės, o kitas iš kairės.'),
  (@b40, 27, 39, 'Ir tie, kurie ėjo pro šalį, plūdo jį linguodami savo galvas'),
  (@b40, 27, 40, 'ir sakydami: „Tu, kuris sunaikini šventyklą ir pastatai ją per tris dienas, išgelbėk save. Jei esi Dievo Sūnus, nuženk nuo kryžiaus“.'),
  (@b40, 27, 41, 'Taip pat ir vyriausieji kunigai, tyčiodamiesi iš jo kartu su raštininkais ir vyresniaisiais, sakė:'),
  (@b40, 27, 42, '„Jis gelbėjo kitus; savęs jis negali išgelbėti. Jei jis yra Izraelio Karalius, tenužengia dabar nuo kryžiaus, ir mes juo patikėsime.'),
  (@b40, 27, 43, 'Jis pasitikėjo Dievu; tegul jis dabar jį išvaduoja, jeigu jam jo reikia; nes jis sakė: ‘Aš esu Dievo Sūnus’“.'),
  (@b40, 27, 44, 'Taip pat ir vagys, kurie buvo su juo nukryžiuoti, prikaišiojo jam tuo pačiu.'),
  (@b40, 27, 45, 'Na, o nuo šeštos iki devintos valandos visą šalį gaubė tamsa.'),
  (@b40, 27, 46, 'Ir apie devintą valandą Jėzus šaukė garsiu balsu, sakydamas: „Eli, Eli, lama sabachtani?“, tai reiškia: „Mano Dieve, mano Dieve, kodėl mane apleidai?“'),
  (@b40, 27, 47, 'Kai kurie iš ten stovėjusiųjų tai išgirdę tarė: „Šitas šaukiasi Elijo“.'),
  (@b40, 27, 48, 'Ir tuoj pat vienas iš jų nubėgęs paėmė kempinę, pripildė ją acto ir užmovė ją ant nendrės, ir davė jam gerti.'),
  (@b40, 27, 49, 'Likusieji tarė: „Palauk, pažiūrėkime, ar Elijas ateis jo išgelbėti“.'),
  (@b40, 27, 50, 'Jėzus, vėl sušukęs garsiu balsu, atidavė dvasią.'),
  (@b40, 27, 51, 'Ir štai šventyklos uždanga perplyšo pusiau nuo viršaus iki apačios; ir žemė drebėjo, ir uolos plyšinėjo;'),
  (@b40, 27, 52, 'ir atsivėrė kapai; ir daug užmigusiųjų šventųjų kūnų kėlėsi,'),
  (@b40, 27, 53, 'ir išėjo iš kapų po jo prisikėlimo, ir nuėjo į šventąjį miestą, ir daugeliui pasirodė.'),
  (@b40, 27, 54, 'Na, o šimtininkas ir su juo buvusieji, saugojantys Jėzų, pamatę žemės drebėjimą ir tai, kas dėjosi, labai išsigando, sakydami: „Tikrai šitas buvo Dievo Sūnus“.'),
  (@b40, 27, 55, 'Ir ten buvo daug moterų, žiūrinčių iš tolo, kurios sekė paskui Jėzų nuo Galilėjos, jam patarnaudamos;'),
  (@b40, 27, 56, 'tarp kurių buvo Marija Magdalietė ir Jokūbo bei Jozės motina Marija, ir Zebediejaus vaikų motina.'),
  (@b40, 27, 57, 'Atėjus vakarui atėjo turtingas žmogus iš Arimatėjos, vardu Juozapas, kuris pats irgi buvo Jėzaus mokinys;'),
  (@b40, 27, 58, 'jis nuėjo pas Pilotą ir maldavo Jėzaus kūno. Tada Pilotas įsakė, kad kūnas būtų atiduotas.'),
  (@b40, 27, 59, 'Ir Juozapas paėmęs kūną, įvyniojo jį į švarų lininį audeklą'),
  (@b40, 27, 60, 'ir paguldė jį savo naujame kape, kurį buvo ištašęs uoloje; ir jis užritino didžiulį akmenį ant kapo durų ir nuėjo.'),
  (@b40, 27, 61, 'Ir ten buvo Marija Magdalietė bei kita Marija, sėdinčios priešais kapą.'),
  (@b40, 27, 62, 'Na, o kitą dieną, kuri yra po pasiruošimo dienos, vyriausieji kunigai ir fariziejai susirinko pas Pilotą,'),
  (@b40, 27, 63, 'sakydami: „Pone, mes prisimename, kad tas suvedžiotojas, kol dar buvo gyvas, sakė: ‘Po trijų dienų prisikelsiu’.'),
  (@b40, 27, 64, 'Todėl įsakyk, kad kapu būtų pasirūpinta iki trečios dienos, idant naktį neateitų jo mokiniai ir jo nepavogtų, ir tautai nepasakytų: ‘Jis yra prisikėlęs iš numirusių’ – taip paskutinė klaida būtų blogesnė už pirmąją“.'),
  (@b40, 27, 65, 'Pilotas jiems tarė: „Turite sargybą, eikite ir užtikrinkite tai kaip tik galite“.'),
  (@b40, 27, 66, 'Taigi jie nuėjo ir pasirūpino kapu, užantspauduodami akmenį ir pastatydami sargybą.'),
  (@b40, 28, 1, 'Sabato pabaigoje, auštant į pirmąją savaitės dieną, Marija Magdalietė ir kita Marija atėjo apžiūrėti kapo.'),
  (@b40, 28, 2, 'Ir štai buvo didžiulis žemės drebėjimas, nes Viešpaties angelas nusileido iš dangaus ir atėjo bei nuritino nuo durų akmenį ir atsisėdo ant jo.'),
  (@b40, 28, 3, 'Jo veidas buvo kaip žaibas, o jo drabužis baltas kaip sniegas;'),
  (@b40, 28, 4, 'ir jo bijodami, sargybiniai drebėjo, ir tapo kaip numirėliai.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b40, 28, 5, 'Ir angelas atsakydamas tarė moterims: „Nebijokite, nes žinau, kad ieškote Jėzaus, kuris buvo nukryžiuotas.'),
  (@b40, 28, 6, 'Jo čia nėra, nes jis yra prisikėlęs, kaip jis sakė. Ateikite, apžiūrėkite vietą, kur Viešpats gulėjo.'),
  (@b40, 28, 7, 'Ir skubiai eikite bei pasakykite jo mokiniams, kad jis yra prisikėlęs iš numirusių; ir štai jis eina pirma jūsų į Galilėją; ten jį pamatysite; štai aš jums pasakiau“.'),
  (@b40, 28, 8, 'Ir jos skubiai nuėjo nuo kapo su baime ir didžiu džiaugsmu; ir nubėgo pranešti jo mokiniams žodį.'),
  (@b40, 28, 9, 'Ir joms beeinant pasakyti jo mokiniams, štai Jėzus sutiko jas, sakydamas: „Sveikos!“ Ir jos atėjo, apkabino jo kojas ir pagarbino jį.'),
  (@b40, 28, 10, 'Tada Jėzus joms tarė: „Nebijokite; eikite, pasakykite mano broliams, kad jie eitų į Galilėją, ir ten jie mane pamatys“.'),
  (@b40, 28, 11, 'Na, o joms einant, štai keletas iš sargybos atėjo į miestą ir apsakė vyriausiems kunigams visa, kas atsitiko.'),
  (@b40, 28, 12, 'Ir jiems susirinkus su vyresniaisiais bei pasitarus, jie davė kareiviams daug pinigų,'),
  (@b40, 28, 13, 'tardami: „Sakykite: ‘Naktį atėjo jo mokiniai ir mums bemiegant jį pavogė’.'),
  (@b40, 28, 14, 'Ir jei tai pasieks valdytojo ausis, mes jį įtikinsime ir jus apsaugosime“.'),
  (@b40, 28, 15, 'Taigi jie paėmė pinigus ir padarė, kaip buvo primokyti; ir šis pasakymas paprastai yra pasakojamas tarp žydų iki šios dienos.'),
  (@b40, 28, 16, 'Tada vienuolika mokinių nuėjo į Galilėją, į kalną, kur Jėzus jiems buvo nurodęs.'),
  (@b40, 28, 17, 'Ir kai jį pamatė, jie pagarbino jį; bet kai kurie abejojo.'),
  (@b40, 28, 18, 'Ir Jėzus atėjęs jiems kalbėjo, sakydamas: „Visa valdžia danguje ir žemėje yra man duota“.'),
  (@b40, 28, 19, 'Todėl eikite ir mokykite visas tautas, krikštydami jas Tėvo ir Sūnaus, ir Šventosios Dvasios vardu:'),
  (@b40, 28, 20, 'mokydami jas laikytis visko, ką jums esu įsakęs; ir štai aš su jumis nuolatos, iki pasaulio pabaigos. Amen“.'),
  (@b41, 1, 1, 'Jėzaus Kristaus, Dievo Sūnaus, evangelijos pradžia;'),
  (@b41, 1, 2, 'kaip yra parašyta pranašuose: „Štai siunčiu pirma tavo veido savo pasiuntinį, kuris paruoš tavo kelią pirma tavęs“.'),
  (@b41, 1, 3, 'Dykumoje šaukiančiojo balsas: „Paruoškite Viešpaties kelią, tiesius darykite jo takus“.'),
  (@b41, 1, 4, 'Jonas krikštijo dykumoje ir skelbė atgailos krikštą nuodėmėms atleisti.'),
  (@b41, 1, 5, 'Ir pas jį išėjo visa Judėjos šalis ir tie iš Jeruzalės, ir visi buvo jo krikštijami Jordano upėje, išpažindami savo nuodėmes.'),
  (@b41, 1, 6, 'Ir Jonas vilkėjo kupranugario šeriais ir odiniu diržu aplink savo strėnas; ir jis maitinosi skėriais bei laukiniu medumi;'),
  (@b41, 1, 7, 'ir skelbė, sakydamas: „Po manęs ateina galingesnis už mane, kuriam nesu vertas pasilenkti ir atrišti jo apavo raiščių.'),
  (@b41, 1, 8, 'Aš iš tikrųjų jus krikštijau vandeniu, bet jis krikštys jus Šventąja Dvasia“.'),
  (@b41, 1, 9, 'Ir įvyko tomis dienomis, kad atėjo Jėzus iš Galilėjos Nazareto ir buvo Jono pakrikštytas Jordane.'),
  (@b41, 1, 10, 'Ir tuojau lipdamas iš vandens jis pamatė atsivėrusius dangus ir Dvasią, tarsi balandį nusileidžiančią ant jo;'),
  (@b41, 1, 11, 'ir atėjo balsas iš dangaus, sakantis: „Tu esi mano mylimasis Sūnus, kuriuo esu labai patenkintas“.'),
  (@b41, 1, 12, 'Ir tuoj pat Dvasia nuvaro jį į dykumą.'),
  (@b41, 1, 13, 'Ir jis ten dykumoje buvo keturiasdešimt dienų gundomas šėtono; ir buvo su laukiniais žvėrimis; ir angelai jam tarnavo.'),
  (@b41, 1, 14, 'Na, o po to, kai Jonas buvo uždarytas į kalėjimą, Jėzus atėjo į Galilėją skelbdamas Dievo karalystės evangeliją'),
  (@b41, 1, 15, 'ir sakydamas: „Laikas išsipildė, ir Dievo karalystė yra čia pat; atgailaukite ir tikėkite evangelija“.'),
  (@b41, 1, 16, 'Na, o eidamas palei Galilėjos jūrą jis pamatė Simoną ir jo brolį Andriejų, metančius tinklą į jūrą, nes jie buvo žvejai.'),
  (@b41, 1, 17, 'Ir Jėzus jiems tarė: „Eikite paskui mane, ir aš padarysiu, kad taptumėte žmonių žvejais“.'),
  (@b41, 1, 18, 'Ir tuoj pat jie paliko savo tinklus bei sekė paskui jį.'),
  (@b41, 1, 19, 'O nuo ten truputį toliau paėjęs, jis pamatė Zebediejaus sūnų Jokūbą ir jo brolį Joną, kurie taip pat buvo laive betaisą savo tinklus.'),
  (@b41, 1, 20, 'Ir jis tuoj pat juos pašaukė; ir jie paliko savo tėvą Zebediejų laive su samdytais tarnais, ir nuėjo paskui jį.'),
  (@b41, 1, 21, 'Ir jie nuėjo į Kafernaumą; ir iškart, sabato dieną, jis įėjo į sinagogą ir mokė.'),
  (@b41, 1, 22, 'Ir jie stebėjosi jo mokslu, nes jis juos mokė kaip turintis valdžią, o ne kaip raštininkai.'),
  (@b41, 1, 23, 'Ir jų sinagogoje buvo žmogus, turintis netyrąją dvasią; ir jis šaukė,'),
  (@b41, 1, 24, 'sakydamas: „Palik mus ramybėje! Kas mums darbo su tavimi, Jėzau iš Nazareto? Ar atėjai mūsų sunaikinti? Pažįstu tave, kas esi – Dievo Šventasis“.'),
  (@b41, 1, 25, 'Ir Jėzus jį sudraudė, sakydamas: „Nutilk ir išeik iš jo!“'),
  (@b41, 1, 26, 'Ir netyroji dvasia, draskydama jį ir šaukdama garsiu balsu, išėjo iš jo.'),
  (@b41, 1, 27, 'Ir jie visi stebėjosi, kad net klausinėjo tarpusavyje, sakydami: „Kas tai yra? Kas tai per naujas mokslas? Nes jis įsakinėja su valdžia netgi netyroms dvasioms, ir jos klauso jo“.'),
  (@b41, 1, 28, 'Ir tuoj garsas apie jį pasklido po visą sritį aplink Galilėją.'),
  (@b41, 1, 29, 'Ir tuojau, išėję iš sinagogos, jie įėjo į Simono ir Andriejaus namus su Jokūbu ir Jonu.'),
  (@b41, 1, 30, 'Bet Simono žmonos motina gulėjo serganti karštine, ir jie tuojau jam pasakė apie ją.'),
  (@b41, 1, 31, 'Ir jis atėjo ir paėmė ją už rankos bei ją pakėlė; ir tuoj pat karštinė ją paliko, ir ji patarnavo jiems.'),
  (@b41, 1, 32, 'O vakare, saulei nusileidus, jie atvedė jam visus ligotus ir tuos, kurie buvo velnių apsėsti.'),
  (@b41, 1, 33, 'Ir visas miestas buvo susirinkęs prie durų.'),
  (@b41, 1, 34, 'Ir jis išgydė daug sergančių įvairiomis ligomis ir išvarė daug velnių; ir neleido velniams kalbėti, nes jie pažinojo jį.'),
  (@b41, 1, 35, 'Ir ryte, atsikėlęs gerokai prieš aušrą, jis išėjo bei nuėjo į nuošalią vietą ir ten meldėsi.'),
  (@b41, 1, 36, 'O Simonas ir buvę su juo nusekė paskui jį.'),
  (@b41, 1, 37, 'Ir jį suradę jie tarė jam: „Visi tavęs ieško“.'),
  (@b41, 1, 38, 'O jis tarė jiems: „Eikime į gretimus miestelius, kad ir ten skelbčiau; nes dėl to aš išėjau“.'),
  (@b41, 1, 39, 'Ir jis skelbė jų sinagogose po visą Galilėją ir išvarinėjo velnius.'),
  (@b41, 1, 40, 'Ir pas jį atėjo raupsuotasis, maldaudamas jo ir klaupdamasis prieš jį, ir jam sakydamas: „Jei nori, gali padaryti mane švarų“.'),
  (@b41, 1, 41, 'Ir Jėzus, apimtas gailesčio, ištiesė savo ranką ir palietė jį, ir sako jam: „Noriu; būk švarus“.'),
  (@b41, 1, 42, 'Ir jam tik pasakius, raupsai iškart pasitraukė nuo jo, ir jis buvo apvalytas.'),
  (@b41, 1, 43, 'Ir jis griežtai jį įpareigojo ir nedelsiant jį paleido;'),
  (@b41, 1, 44, 'ir sako jam: „Žiūrėk, niekam nieko nesakyk; bet eik, pasirodyk kunigui ir atnašauk už savo apvalymą tai, ką Mozė įsakė, kaip liudijimą jiems“.'),
  (@b41, 1, 45, 'Bet jis išėjo ir pradėjo labai skelbti ir plačiai tą dalyką garsinti, kad Jėzus net nebegalėjo atvirai įeiti į miestą, bet buvo lauke, dykiose vietose; ir jie atėjo pas jį iš visur.'),
  (@b41, 2, 1, 'Ir vėl po keleto dienų jis įėjo į Kafernaumą; ir buvo išgarsinta, kad jis buvo namuose.'),
  (@b41, 2, 2, 'Ir nedelsiant daugelis susirinko, kad net nebuvo vietos jų priimti, netgi prie durų; ir jis skelbė jiems žodį.'),
  (@b41, 2, 3, 'Ir jie atėjo pas jį atgabendami vieną sergantį paralyžiumi, kurį nešė keturiese.'),
  (@b41, 2, 4, 'Ir kai jie nebegalėjo prieiti prie jo dėl spūsties, jie atidengė stogą, kur jis buvo; ir jį pralaužę nuleido žemyn patalą, kuriame gulėjo sergantis paralyžiumi.'),
  (@b41, 2, 5, 'Jėzus, pamatęs jų tikėjimą, tarė sergančiam paralyžiumi: „Sūnau, tavo nuodėmės tau atleistos“.'),
  (@b41, 2, 6, 'Bet ten sėdėjo kai kurie iš raštininkų ir svarstė savo širdyse:'),
  (@b41, 2, 7, '„Kodėl šitas žmogus taip kalba piktžodžiavimus? Kas gali atleisti nuodėmes, jei ne vienas Dievas?“'),
  (@b41, 2, 8, 'Ir Jėzus, iš karto supratęs savo dvasioje, kad jie šitaip svarstė savyje, tarė jiems: „Kodėl svarstote tai savo širdyse?'),
  (@b41, 2, 9, 'Kas yra lengviau – pasakyti sergančiam paralyžiumi: ‘Tavo nuodėmės tau atleistos’, ar pasakyti: ‘Kelkis, paimk savo patalą ir vaikščiok’?'),
  (@b41, 2, 10, 'Bet kad žinotumėte, kad žmogaus Sūnus turi valdžią žemėje atleisti nuodėmes (jis sako sergančiajam paralyžiumi);'),
  (@b41, 2, 11, 'sakau tau: ‘Kelkis, paimk savo patalą ir eik į savo namus’“.'),
  (@b41, 2, 12, 'Ir jis tuojau atsikėlė, paėmė patalą ir išėjo visų jų akivaizdoje, kad net visi jie stebėjosi ir šlovino Dievą, sakydami: „Mes niekada nieko tokio nesame matę“.'),
  (@b41, 2, 13, 'Ir jis vėl išėjo į pajūrį, ir visa minia rinkosi pas jį, o jis mokė juos.'),
  (@b41, 2, 14, 'Ir praeidamas jis pamatė Alfiejaus sūnų Levį, sėdintį prie muito surinkimo, ir tarė jam: „Sek paskui mane“. Ir jis atsikėlė ir nusekė paskui jį.'),
  (@b41, 2, 15, 'Ir įvyko, kai Jėzus sėdėjo prie maisto jo namuose, daug muitininkų ir nusidėjėlių taip pat sėdėjo kartu su Jėzumi ir jo mokiniais; nes buvo daug, ir jie sekė paskui jį.'),
  (@b41, 2, 16, 'O kai raštininkai ir fariziejai pamatė jį valgantį su muitininkais bei nusidėjėliais, jie tarė jo mokiniams: „Kaipgi yra, kad jis valgo ir geria su muitininkais bei nusidėjėliais?“'),
  (@b41, 2, 17, 'Tai išgirdęs Jėzus sako jiems: „Sveikiesiems nereikia gydytojo, o tik ligoniams; aš atėjau šaukti ne teisiųjų, bet nusidėjėlių atgailai“.'),
  (@b41, 2, 18, 'O Jono ir fariziejų mokiniai pasninkaudavo; ir jie atėję sako jam: „Kodėl Jono ir fariziejų mokiniai pasninkauja, bet tavo mokiniai nepasninkauja?“'),
  (@b41, 2, 19, 'Ir Jėzus jiems tarė: „Ar gali vestuvių menės vaikai pasninkauti, kol su jais yra jaunikis? Kol su jais yra jaunikis, jie negali pasninkauti.'),
  (@b41, 2, 20, 'Bet ateis dienos, kai jaunikis bus iš jų atimtas, ir tada jie pasninkaus tomis dienomis.'),
  (@b41, 2, 21, 'Taip pat niekas nesiuva naujo audinio lopo ant seno drabužio – antraip naujasis prilopytas lopas atplėšia nuo senojo, ir įplyšimas darosi blogesnis.'),
  (@b41, 2, 22, 'Ir niekas nepila naujo vyno į senus indus – antraip naujas vynas sutraukys indus, ir vynas išsipils, ir indai bus sugadinti; bet naujas vynas turi būti pilamas į naujus indus“.'),
  (@b41, 2, 23, 'Ir įvyko, kad jis sabato dieną ėjo per javų laukus; o jo mokiniai eidami pradėjo skabyti javų varpas.'),
  (@b41, 2, 24, 'Ir fariziejai jam tarė: „Žiūrėk, kodėl jie sabato dieną daro tai, kas neteisėta?“'),
  (@b41, 2, 25, 'O jis jiems tarė: „Ar niekada neskaitėte, ką padarė Dovydas, kai stokojo ir buvo išalkęs – jis ir tie, kurie buvo su juo?'),
  (@b41, 2, 26, 'Kaip jis įėjo į Dievo namus aukščiausiojo kunigo Abiataro dienomis ir valgė parodomos duonos, kurios niekam neteisėta valgyti, tik kunigams, ir taip pat davė tiems, kurie buvo su juo?“'),
  (@b41, 2, 27, 'Ir jis tarė jiems: „Sabatas buvo padarytas žmogui, o ne žmogus sabatui;'),
  (@b41, 2, 28, 'todėl žmogaus Sūnus yra ir sabato Viešpats“.'),
  (@b41, 3, 1, 'Ir jis vėl įėjo į sinagogą; o ten buvo žmogus, turintis nudžiūvusią ranką.'),
  (@b41, 3, 2, 'Ir jie stebėjo jį, ar jis gydys jį sabato dieną – kad galėtų jį apkaltinti.'),
  (@b41, 3, 3, 'Ir jis sako žmogui, turinčiam nudžiūvusią ranką: „Stokis pirmyn!“'),
  (@b41, 3, 4, 'Ir jis sako jiems: „Ar sabato dienomis teisėta daryti gera ar daryti pikta? Gelbėti gyvybę ar žudyti?“ Bet jie tylėjo.'),
  (@b41, 3, 5, 'Ir jis, su pykčiu juos apžvelgęs, nuliūdęs dėl jų širdžių kietumo, sako žmogui: „Ištiesk savo ranką“. Ir jis ją ištiesė; ir jo ranka tapo sveika kaip kita.'),
  (@b41, 3, 6, 'O fariziejai išėjo ir tuojau tarėsi prieš jį su erodininkais, kaip jie galėtų jį sunaikinti.'),
  (@b41, 3, 7, 'Bet Jėzus su savo mokiniais pasitraukė prie jūros; ir paskui jį sekė didžiulė minia iš Galilėjos ir iš Judėjos,'),
  (@b41, 3, 8, 'ir iš Jeruzalės, ir iš Idumėjos, ir iš anapus Jordano; ir tie iš Tyro ir Sidono apylinkių, didžiulė gausybė, išgirdę kokius didžius dalykus jis padarė, atėjo pas jį.'),
  (@b41, 3, 9, 'Ir jis kalbėjo savo mokiniams, kad jam paruoštų nedidelį laivą – dėl minios, kad jie nesuspaustų jo.'),
  (@b41, 3, 10, 'Nes jis buvo daugelį išgydęs; kad net veržėsi prie jo visi, ištikti rykščių, idant jį paliestų.'),
  (@b41, 3, 11, 'Ir netyrosios dvasios jį pamačiusios puolė prieš jį žemėn ir šaukė, sakydamos: „Tu esi Dievo Sūnus“.'),
  (@b41, 3, 12, 'O jis griežtai jas įpareigojo, kad jo neišgarsintų.'),
  (@b41, 3, 13, 'Ir jis užžengia į kalną ir pasišaukia kuriuos jis norėjo; ir jie atėjo pas jį.'),
  (@b41, 3, 14, 'Ir jis paskyrė dvylika, kad jie būtų su juo ir kad jis juos išsiųstų skelbti'),
  (@b41, 3, 15, 'bei turėti valdžią gydyti ligas ir išvarinėti velnius;'),
  (@b41, 3, 16, 'ir Simoną jis praminė Petru;'),
  (@b41, 3, 17, 'ir Jokūbą, Zebediejaus sūnų, ir Joną, Jokūbo brolį; juos jis praminė Boanerges, tai yra „griaustinio sūnūs”;'),
  (@b41, 3, 18, 'ir Andriejų, ir Pilypą, ir Bartalamiejų, ir Matą, ir Tomą, ir Alfiejaus sūnų Jokūbą, ir Tadą, ir Simoną kanaanietį,'),
  (@b41, 3, 19, 'ir Judą Iskariotą, kuris jį ir išdavė; ir jie nuėjo į namus.'),
  (@b41, 3, 20, 'Ir vėl susirenka minia taip, kad jie net negalėjo valgyti duonos.'),
  (@b41, 3, 21, 'O kai jo draugai apie tai išgirdo, jie išėjo jo sulaikyti, nes jie sakė: „Jis yra išėjęs iš proto“.'),
  (@b41, 3, 22, 'Ir raštininkai, atėję žemyn iš Jeruzalės, tarė: „Jis turi Belzebubą, ir per velnių kunigaikštį išvarinėja velnius“.'),
  (@b41, 3, 23, 'Ir jis pasišaukė juos bei tarė jiems palyginimais: „Kaipgi šėtonas gali išvaryti šėtoną?'),
  (@b41, 3, 24, 'Ir jei karalystė yra pasidalijusi prieš save, ta karalystė negali išstovėti.'),
  (@b41, 3, 25, 'Ir jei namai yra pasidaliję prieš save, tie namai negali išstovėti.'),
  (@b41, 3, 26, 'Ir jei šėtonas sukyla prieš save ir yra pasidalijęs, jis negali išstovėti, bet jam yra galas.'),
  (@b41, 3, 27, 'Niekas negali įeiti į stipruolio namus ir išgrobti jo turto, jei pirmiau nesuriš stipruolio; ir tik tada jis apiplėš jo namus.'),
  (@b41, 3, 28, 'Iš tiesų sakau jums: visos nuodėmės bus atleistos žmonių sūnums ir piktžodžiavimai, kokiais jie bepiktžodžiautų;'),
  (@b41, 3, 29, 'bet tam, kuris piktžodžiaus Šventajai Dvasiai, niekada nebus atleidimo, bet gresia amžinas pasmerkimas“;'),
  (@b41, 3, 30, 'kadangi jie sakė: „Jis turi netyrąją dvasią“.'),
  (@b41, 3, 31, 'Tada atėjo jo broliai bei jo motina ir, stovėdami lauke, pasiuntė pas jį, jį kviesdami.'),
  (@b41, 3, 32, 'O minia sėdėjo aplink jį, ir jie tarė jam: „Štai tavo motina bei tavo broliai lauke ieško tavęs“.'),
  (@b41, 3, 33, 'Ir jis atsakė jiems, tardamas: „Kas yra mano motina ar mano broliai?“'),
  (@b41, 3, 34, 'Ir jis apžvelgė visus aplinkui jį sėdinčius ir tarė: „Štai mano motina bei mano broliai!'),
  (@b41, 3, 35, 'Nes kas vykdys Dievo valią, tas yra mano brolis, mano sesuo ir motina“.'),
  (@b41, 4, 1, 'Ir jis vėl pradėjo mokyti palei jūrą; ir pas jį susirinko didžiulė minia taip, kad jis įlipo į laivą ir atsisėdo jūroje; o visa minia buvo palei jūrą sausumoje.'),
  (@b41, 4, 2, 'Ir jis mokė juos daugelio dalykų palyginimais ir tarė jiems savu mokslu:'),
  (@b41, 4, 3, '„Paklausykite: štai sėjėjas išėjo sėti;'),
  (@b41, 4, 4, 'ir įvyko, kad jam besėjant viena krito palei kelią, ir atskrido oro skrajūnai, ir tai surijo.'),
  (@b41, 4, 5, 'Ir viena krito ant akmenuotos dirvos, kur buvo nedaug žemės; ir tai tuoj pat išdygo, nes neturėjo žemės gilumo;'),
  (@b41, 4, 6, 'bet saulei pakilus tai išdegė ir, kadangi tai neturėjo šaknies, tai sudžiūvo.'),
  (@b41, 4, 7, 'O viena nukrito tarp erškėčių, ir erškėčiai užaugo ir tai nusmelkė, ir tai nedavė vaisiaus.'),
  (@b41, 4, 8, 'O kita nukrito ant geros žemės ir davė vaisių, kuris išdygo bei užaugo; ir atnešė viena trisdešimt, kita šešiasdešimt, o kita šimtą“.'),
  (@b41, 4, 9, 'Ir jis tarė jiems: „Kas turi ausis klausyti, teklauso“.'),
  (@b41, 4, 10, 'O kai jis buvo vienas, tie, kurie buvo aplink jį kartu su dvylika, paklausė jo apie palyginimą.'),
  (@b41, 4, 11, 'Ir jis jiems tarė: „Jums yra duota sužinoti Dievo karalystės paslaptį; bet išorėje esantiems visa tai pateikiama palyginimais;'),
  (@b41, 4, 12, 'kad ‘matydami jie matytų, bet nepastebėtų, ir klausydami jie klausytų, bet nesuprastų; kad kokiu metu jie neatsiverstų, ir jų nuodėmės nebūtų jiems atleistos’“.'),
  (@b41, 4, 13, 'Ir jis tarė jiems: „Ar nežinote šito palyginimo? Ir kaip tada žinosite visus palyginimus?'),
  (@b41, 4, 14, 'Sėjėjas sėja žodį.'),
  (@b41, 4, 15, 'O šitie yra tie palei kelią, kur žodis yra pasėtas; bet, jiems išgirdus, tuojau pat ateina šėtonas ir atima žodį, kuris buvo pasėtas jų širdyse.'),
  (@b41, 4, 16, 'Ir panašiai šitie yra tie, kurie pasėti ant akmenuotos dirvos; kurie išgirdę žodį tuoj pat priima jį su džiaugsmu;'),
  (@b41, 4, 17, 'ir neturi savyje šaknies, ir taip išsilaiko tik neilgam; po to, ištikus vargui ar persekiojimui dėl žodžio, jie tuoj pat pasipiktina.'),
  (@b41, 4, 18, 'Ir šitie yra tie, kurie yra pasėti tarp erškėčių, tokie, kurie išgirsta žodį,'),
  (@b41, 4, 19, 'bet šio pasaulio rūpesčiai ir turtų apgaulė bei kitų dalykų geismas įžengia, nusmelkia žodį, ir jis tampa nevaisingas.'),
  (@b41, 4, 20, 'O šitie yra tie, kurie yra pasėti geroje dirvoje, tokie, kurie girdi žodį ir priima jį, ir atneša vaisių: vieni trisdešimteriopą, vieni šešiasdešimteriopą, vieni šimteriopą“.'),
  (@b41, 4, 21, 'Ir jis tarė jiems: „Argi žvakė atnešama, kad būtų pastatyta po saiku ar po lova? O ne tam, kad būtų įstatyta į žvakidę?'),
  (@b41, 4, 22, 'Nes nieko nėra paslėpta, kas nebūtų aiškiai parodyta; nei nieko nebuvo laikoma paslaptyje, bet kad tai pasklistų.'),
  (@b41, 4, 23, 'Jei kas turi ausis klausyti, teklauso“.'),
  (@b41, 4, 24, 'Ir jis tarė jiems: „Būkite atidūs, ką girdite: kokiu saiku jūs seikėjate, tai jums bus atseikėta; o jums, kurie girdite, bus duota daugiau.'),
  (@b41, 4, 25, 'Nes tas, kas turi, tam bus duota; o tas, kas neturi, iš to bus atimta net ir tai, ką jis turi“.'),
  (@b41, 4, 26, 'Ir jis tarė: „Taip yra Dievo karalystė, tarsi žmogus išbertų sėklą į dirvą;'),
  (@b41, 4, 27, 'ir miegotų, ir keltųsi naktį bei dieną, o sėkla išdygtų ir užaugtų jam nežinant kaip.'),
  (@b41, 4, 28, 'Nes žemė iš savęs neša vaisių; iš pradžių – želmenį, paskui – varpą, po to – pilną grūdą varpoje.'),
  (@b41, 4, 29, 'Bet kai vaisius atneštas, jis tuoj pat prideda pjautuvą, nes atėjo pjūtis“.'),
  (@b41, 4, 30, 'Ir jis tarė: „Kam prilyginsime Dievo karalystę? Arba kokiu palyginimu ją palyginsime?'),
  (@b41, 4, 31, 'Ji yra kaip garstyčios sėklos grūdas, kuris pasėtas žemėje yra mažiausias už visas sėklas, esančias žemėje;'),
  (@b41, 4, 32, 'bet pasėtas jis užauga ir tampa didesnis už visas žoles, ir išleidžia dideles šakas; taip, kad oro skrajūnai gali apsigyventi jo paūksmėje“.'),
  (@b41, 4, 33, 'Ir daugeliu tokių palyginimų jis kalbėjo jiems žodį, kiek jie pajėgė klausyti.'),
  (@b41, 4, 34, 'Bet be palyginimo jis jiems nekalbėjo; o kai jie buvo vieni, jis viską išaiškino savo mokiniams.'),
  (@b41, 4, 35, 'Ir tą pačią dieną, atėjus vakarui, jis sako jiems: „Persikelkime į kitą pusę“.'),
  (@b41, 4, 36, 'Ir kai jie paleido minią, jie pasiėmė jį, kaip jis ir buvo laive. Ir ten su juo buvo ir kiti nedideli laivai.'),
  (@b41, 4, 37, 'Ir pakilo didžiulė vėjo audra, ir bangos taip daužėsi į laivą, kad jis jau buvo apsemtas.'),
  (@b41, 4, 38, 'O jis buvo laivo paskuigalyje, miegantis ant pagalvės; ir jie pažadino jį, ir sako jam: „Mokytojau, argi tau nerūpi, kad žūstame?“'),
  (@b41, 4, 39, 'Ir jis atsikėlė, sudraudė vėją ir tarė jūrai: „Nutilk, būk rami!“ Ir vėjas liovėsi, ir buvo didi tyla.'),
  (@b41, 4, 40, 'Ir jis tarė jiems: „Kodėl jūs tokie bailūs? Kaipgi yra, kad neturite tikėjimo?“'),
  (@b41, 4, 41, 'Ir jie be galo bijojo ir sakė vienas kitam: „Kas tai per žmogus, kad net vėjas ir jūra jo klauso?“'),
  (@b41, 5, 1, 'Ir jie atvyko į kitą jūros pusę, į Gadareneso šalį.'),
  (@b41, 5, 2, 'O kai jis išlipo iš laivo, tuojau iš kapų jį pasitiko turintis netyrą dvasią žmogus,'),
  (@b41, 5, 3, 'kuris gyveno tarp kapų; ir niekas negalėjo jo surišti nei grandinėmis;'),
  (@b41, 5, 4, 'nes jis dažnai buvo rištas pančiais ir grandinėmis, bet jis pertraukdavo grandines pusiau ir sutraukydavo pančius į gabalus; ir niekas negalėjo jo suvaldyti.'),
  (@b41, 5, 5, 'Ir visada – naktį ir dieną – jis buvo kalnuose ir kapuose, šaukdamas ir pjaustydamas save akmenimis.'),
  (@b41, 5, 6, 'Bet kai jis iš tolo pamatė Jėzų, jis nubėgo ir pagarbino jį,'),
  (@b41, 5, 7, 'ir šaukė garsiu balsu, ir tarė: „Kas man darbo su tavimi, Jėzau, aukščiausiojo Dievo Sūnau? Saikdinu tave Dievu, kad tu manęs nekankintumei“.'),
  (@b41, 5, 8, 'Nes jis sakė jam: „Išeik iš to žmogaus, netyroji dvasia!“'),
  (@b41, 5, 9, 'Ir jis paklausė jos: „Koks tavo vardas?“ O ji atsakė, tardama: „Mano vardas Legionas, nes mūsų daug“.'),
  (@b41, 5, 10, 'Ir ji jo labai maldavo, kad jis neišsiųstų jų iš tos šalies.'),
  (@b41, 5, 11, 'Na, o ten, šalia kalnų, ganėsi didelė kiaulių banda.'),
  (@b41, 5, 12, 'Ir visi velniai maldavo jo, sakydami: „Pasiųsk mus į kiaules, kad įeitume į jas“.'),
  (@b41, 5, 13, 'Ir Jėzus iškart jiems leido. Ir netyrosios dvasios išėjo ir įėjo į kiaules; ir banda galvotrūkčiais leidosi nuo stačios vietos žemyn į jūrą (jų buvo apie du tūkstančius) ir prigėrė jūroje.'),
  (@b41, 5, 14, 'O tie, kurie ganė kiaules, pabėgo ir papasakojo tai mieste ir kiemuose. Ir jie išėjo pažiūrėti, kas tai yra, kas buvo atsitikę.'),
  (@b41, 5, 15, 'Ir jie atėjo pas Jėzų ir pamatė tą, kuris buvo velnio apsėstas ir turėjo legioną, sėdintį ir apsirengusį, ir sveiko proto; ir jie išsigando.'),
  (@b41, 5, 16, 'Ir tie, kurie tai matė, pasakė jiems, kas nutiko su velnio apsėstuoju, ir taip pat apie kiaules.'),
  (@b41, 5, 17, 'Ir jie pradėjo jo maldauti, kad jis išeitų iš jų ribų.'),
  (@b41, 5, 18, 'Ir kai jis atėjo į laivą, tas, kuris buvo velnio apsėstas, maldavo jo, kad galėtų būti pas jį.'),
  (@b41, 5, 19, 'Tačiau Jėzus jam neleido, bet jam sako: „Eik namo pas savo draugus ir papasakok jiems, kokių didžių dalykų tau padarė Viešpats ir kaip tavęs pasigailėjo.'),
  (@b41, 5, 20, 'Ir išėjęs jis pradėjo skelbti Dekapolyje, kokių didžių dalykų jam padarė Jėzus; ir visi stebėjosi.'),
  (@b41, 5, 21, 'O kai Jėzus vėl persikėlė laivu į kitą pusę, daug liaudies susirinko pas jį; jis buvo šalia jūros.'),
  (@b41, 5, 22, 'Ir štai ateina vienas iš sinagogos valdovų, vardu Jayras; ir jį pamatęs jis parpuolė prie jo kojų'),
  (@b41, 5, 23, 'ir labai jo maldavo, sakydamas: „Mano dukrelė guli prie mirties; meldžiu tave, ateik ir uždėk ant jos savo rankas, kad ji būtų išgydyta; ir ji gyvens“.'),
  (@b41, 5, 24, 'Ir Jėzus nuėjo su juo; ir daug liaudies ėjo paskui jį ir jį spaudė.'),
  (@b41, 5, 25, 'Ir viena moteris, dvylika metų turinti kraujoplūdį'),
  (@b41, 5, 26, 'bei daug iškentėjusi nuo daugelio gydytojų ir išleidusi viską, ką ji turėjo; ir niekas nepagerėjo, bet ėjo vis blogyn;'),
  (@b41, 5, 27, 'kai ji išgirdo apie Jėzų, įėjo į spūstį iš paskos ir palietė jo rūbą.'),
  (@b41, 5, 28, 'Nes ji tarė: „Jei galėčiau paliesti bent jo drabužius, pasveikčiau“.'),
  (@b41, 5, 29, 'Ir tuojau pat jos kraujo šaltinis išdžiūvo; ir ji pajuto savo kūne, kad ji buvo išgydyta nuo tos rykštės.'),
  (@b41, 5, 30, 'Ir Jėzus, tuojau pažinęs savyje, kad iš jo išėjo veiksmingumas, atsisuko į spūstį ir tarė: „Kas palietė mano drabužius?“'),
  (@b41, 5, 31, 'Ir jo mokiniai jam tarė: „Tu matai, kaip minia tave spaudžia, ir sakai: ‘Kas mane palietė’?“'),
  (@b41, 5, 32, 'Ir jis žvalgėsi aplinkui, kad pamatytų tą, kuri tai padarė.'),
  (@b41, 5, 33, 'Bet moteris, bijodama ir drebėdama, žinodama, kas joje atsitiko, atėjo ir puolė prieš jį, ir pasakė jam visą tiesą.'),
  (@b41, 5, 34, 'O jis jai tarė: „Dukra, tavo tikėjimas padarė tave sveiką; eik ramybėje ir būk sveika nuo savo rykštės“.'),
  (@b41, 5, 35, 'Jam dar tebekalbant, atėjo vienas iš sinagogos valdovo namų, kuris sakė: „Tavo dukra mirusi; kodėl vis dar vargini Mokytoją?“');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b41, 5, 36, 'Vos tik Jėzus išgirdo pasakytą žodį, jis sako sinagogos valdovui: „Nebijok, vien tikėk“.'),
  (@b41, 5, 37, 'Ir jis neleido niekam sekti paskui jį, išskyrus Petrui, Jokūbui bei Jokūbo broliui Jonui.'),
  (@b41, 5, 38, 'Ir jis ateina į sinagogos valdovo namus ir pamato sujudimą bei verkiančius ir labai raudančius.'),
  (@b41, 5, 39, 'Ir jis įėjęs jiems sako: „Kodėl keliate tokį triukšmą ir verkiate? Mergaitė ne mirusi, bet miega“.'),
  (@b41, 5, 40, 'Ir jie išsijuokė iš jo. Bet, juos visus išvaręs lauk, jis paima mergaitės tėvą, motiną ir su juo esančius, ir įeina ten, kur mergaitė gulėjo.'),
  (@b41, 5, 41, 'Ir jis paėmė mergaitę už rankos bei jai tarė: „Talita kumi“, kas išvertus reiškia: „Mergaite, sakau tau, kelkis“.'),
  (@b41, 5, 42, 'Ir mergaitė tuojau atsikėlė ir vaikščiojo; nes ji buvo dvylikos metų. Ir jie stebėjosi didžia nuostaba.'),
  (@b41, 5, 43, 'Ir jis juos griežtai įpareigojo, kad niekas šito nežinotų; ir įsakė, kad jai būtų duota ko nors valgyti.'),
  (@b41, 6, 1, 'Ir jis iš ten išėjo ir atėjo į savo tėviškę; o jo mokiniai sekė paskui jį.'),
  (@b41, 6, 2, 'Ir atėjus sabato dienai jis pradėjo mokyti sinagogoje; ir daugelis jį girdėdami stebėjosi, sakydami: „Iš kur šitas tai turi? Ir kas per išmintis, kuri jam yra duota, kad net tokie galingi darbai yra padaryti jo rankomis?'),
  (@b41, 6, 3, 'Argi šitas ne dailidė, Marijos sūnus, Jokūbo, Jozės, Judos ir Simono brolis? Ir argi ne jo seserys su mumis?“ Ir jie pasipiktino juo.'),
  (@b41, 6, 4, 'Bet Jėzus jiems tarė: „Pranašas nebūna be pagarbos, nebent savo tėviškėje, tarp savo giminaičių ir savo namuose“.'),
  (@b41, 6, 5, 'Ir jis negalėjo ten daryti jokio galingo darbo, tik ant keleto sergančių žmonių jis uždėjo savo rankas ir juos išgydė.'),
  (@b41, 6, 6, 'Ir jis stebėjosi dėl jų netikėjimo. Ir jis ėjo aplink kaimus mokydamas.'),
  (@b41, 6, 7, 'Ir jis pasišaukė dvylika ir pradėjo juos siųsti po du; ir davė jiems valdžią netyrosioms dvasioms;'),
  (@b41, 6, 8, 'ir jiems įsakė, kad jie nieko nesiimtų kelionei išskyrus lazdą: nei kelionmaišio, nei duonos, nei pinigų į pinigines;'),
  (@b41, 6, 9, 'bet būtų apsiavę sandalais; ir neapsivilktų dviejų marškinių.'),
  (@b41, 6, 10, 'Ir jis tarė jiems: „Kurioje tik vietoje beįeisite į namus, ten pasilikite, kol išeisite iš tos vietos.'),
  (@b41, 6, 11, 'O kas tik jūsų nepriimtų ir jūsų nesiklausytų, iš ten išeidami nusipurtykite dulkes sau po kojomis kaip liudijimą prieš juos. Iš tiesų sakau jums: Sodomai ir Gomorai teismo dieną bus daug pakenčiamiau negu šitam miestui“.'),
  (@b41, 6, 12, 'Ir jie išėjo bei skelbė, kad žmonės turi atgailauti.'),
  (@b41, 6, 13, 'Ir jie išvarė daug velnių ir daugelį sergančių patepė aliejumi bei juos išgydė.'),
  (@b41, 6, 14, 'Ir karalius Erodas išgirdo apie jį (nes jo vardas buvo plačiai paplitęs); ir jis tarė: „Tai – Jonas Krikštytojas, prisikėlęs iš numirusių, ir todėl galingi darbai rodosi jame“.'),
  (@b41, 6, 15, 'Kiti sakė: „Tai yra Elijas“. O kiti sakė: „Tai yra pranašas arba kaip vienas iš pranašų“.'),
  (@b41, 6, 16, 'Bet kai Erodas tai išgirdo, jis tarė: „Tai – Jonas, kuriam nukirsdinau galvą; jis yra prisikėlęs iš numirusių“.'),
  (@b41, 6, 17, 'Nes pats Erodas pasiuntė ir suėmė Joną bei surišo jį kalėjime dėl savo brolio Pilypo žmonos Erodijos; nes jis buvo ją vedęs.'),
  (@b41, 6, 18, 'Nes Jonas buvo sakęs Erodui: „Tau neteisėta turėti savo brolio žmonos“.'),
  (@b41, 6, 19, 'Todėl Erodija jautė jam priešiškumą ir norėjo jį nužudyti; bet ji negalėjo,'),
  (@b41, 6, 20, 'nes Erodas bijojo Jono, žinodamas, kad jis yra teisus vyras bei šventas, ir stebėjo jį; jo išklausęs, jis daug ką darė ir mielai jo klausydavosi.'),
  (@b41, 6, 21, 'Ir kai atėjo patogi diena, kai Erodas per savo gimtadienį suruošė vakarienę savo viešpačiams, aukštiems vadams ir Galilėjos prakilniausiems;'),
  (@b41, 6, 22, 'ir kai įėjo minėtos Erodijos duktė ir šoko bei patiko Erodui ir sėdėjusiems su juo, karalius tarė tai panelei: „Prašyk iš manęs, ko tik nori, ir tau tai duosiu“.'),
  (@b41, 6, 23, 'Ir jis prisiekė jai: „Ko tik iš manęs beprašysi, tau tai duosiu, iki pusės savo karalystės“.'),
  (@b41, 6, 24, 'Ir ji išėjo bei tarė savo motinai: „Ko man prašyti?“ Ir ji tarė: „Jono Krikštytojo galvos“.'),
  (@b41, 6, 25, 'Ir ji tuojau skubomis atėjo pas karalių ir paprašė, sakydama: „Noriu, kad man tuojau duotum dubenyje Jono Krikštytojo galvą“.'),
  (@b41, 6, 26, 'Ir karalius labai nuliūdo; tačiau dėl savo priesaikos ir dėl tų, kurie sėdėjo su juo, jis nenorėjo jos atmesti.'),
  (@b41, 6, 27, 'Ir tuoj pat karalius išsiuntė budelį ir įsakė, kad būtų atnešta jo galva; ir jis nuėjo ir nukirto jam kalėjime galvą.'),
  (@b41, 6, 28, 'Ir atnešė jo galvą dubenyje ir padavė ją tai panelei; o panelė padavė ją savo motinai.'),
  (@b41, 6, 29, 'Ir kai jo mokiniai apie tai išgirdo, jie atėję pasiėmė jo lavoną ir paguldė jį į kapą.'),
  (@b41, 6, 30, 'Ir apaštalai susirinko pas Jėzų ir papasakojo jam viską – ir ką jie padarė, ir ko jie mokė.'),
  (@b41, 6, 31, 'Ir jis tarė jiems: „Ateikite vieni nuošalėn į dykvietę ir truputį pailsėkite“; nes daug buvo ateinančių bei išeinančių, ir jiems nebuvo laisvo laiko net pavalgyti.'),
  (@b41, 6, 32, 'Ir jie atskirai išvyko laivu į dykvietę.'),
  (@b41, 6, 33, 'O tauta pamatė juos išvykstant, ir daugelis jį pažinę pėsti bėgo ten iš visų miestų, aplenkė juos ir susirinko pas jį.'),
  (@b41, 6, 34, 'Ir Jėzus išėjęs pamatė daug liaudies, ir dėl jų jį apėmė gailestis, nes jie buvo kaip avys, neturinčios piemens; ir jis pradėjo juos mokyti daugelio dalykų.'),
  (@b41, 6, 35, 'Ir dienai baigiantis pas jį atėjo jo mokiniai ir tarė: „Čia dykvietė, ir laiko jau praėjo;'),
  (@b41, 6, 36, 'paleisk juos, kad jie eitų į aplinkinius sodžius ir į kaimus ir nusipirktų sau duonos, nes jie neturi ko valgyti“.'),
  (@b41, 6, 37, 'Jis atsakydamas tarė jiems: „Jūs duokite jiems valgyti“. Ir jie sako jam: „Ar mums eiti ir nupirkti duonos už du šimtus denarų ir duoti jiems valgyti?“'),
  (@b41, 6, 38, 'Jis sako jiems: „Kiek turite kepalų? Eikite ir pažiūrėkite“. Ir sužinoję jie sako: „Penkis ir dvi žuvis“.'),
  (@b41, 6, 39, 'Ir jis įsakė jiems susodinti visus būriais ant žalios žolės.'),
  (@b41, 6, 40, 'Ir jie susėdo eilėmis po šimtą ir po penkiasdešimt.'),
  (@b41, 6, 41, 'Ir paėmęs penkis kepalus ir dvi žuvis jis pažvelgė aukštyn į dangų, palaimino, laužė kepalus ir davė juos savo mokiniams, kad išdėliotų priešais juos; ir dvi žuvis jis padalino tarp jų visų.'),
  (@b41, 6, 42, 'Ir jie visi valgė ir pasotino.'),
  (@b41, 6, 43, 'Ir jie pririnko dvylika pintinių, pilnų nuolaužų ir žuvų.'),
  (@b41, 6, 44, 'O tų, kurie valgė iš kepalų, buvo apie penkis tūkstančius vyrų.'),
  (@b41, 6, 45, 'Ir tuojau jis privertė savo mokinius eiti į laivą ir pirmiau vykti į kitą pusę į Betsaidą, kol jis paleis tautą.'),
  (@b41, 6, 46, 'Ir kai jis juos paleido, jis nuėjo į kalną melstis.'),
  (@b41, 6, 47, 'Ir kai atėjo vakaras, laivas buvo viduryje jūros, o jis vienas sausumoje.'),
  (@b41, 6, 48, 'Ir jis matė juos vargstančius besiiriant, nes vėjas buvo jiems priešpriešis; ir apie ketvirtą nakties budėjimą jis ateina pas juos žengdamas jūra, norėdamas praeiti jiems pro šalį.'),
  (@b41, 6, 49, 'Bet pamatę jį einantį jūra, jie pamanė, kad tai dvasia, ir šaukė;'),
  (@b41, 6, 50, 'nes jie visi jį matė ir nerimavo. Ir jis tuojau prakalbo jiems, ir jiems sako: „Pralinksmėkite, tai aš; nebijokite“.'),
  (@b41, 6, 51, 'Ir jis įlipo pas juos į laivą; ir vėjas liovėsi, ir jie didžiai buvo savyje be saiko apstulbę ir stebėjosi.'),
  (@b41, 6, 52, 'Nes jie neapgalvojo kepalų stebuklo; nes jų širdis buvo užkietėjusi.'),
  (@b41, 6, 53, 'Ir persikėlę jie atvyko į Genezareto šalį ir prisitraukė prie kranto.'),
  (@b41, 6, 54, 'Ir išlipę iš laivo jie tuoj pat pažino jį'),
  (@b41, 6, 55, 'ir apibėgo visą aplinkinį rajoną, ir pradėjo lovose gabenti sergančiuosius ten, kur girdėjo jį esant.'),
  (@b41, 6, 56, 'Ir kur tik jis įėjo – į kaimus ar miestus, ar vienkiemius, jie guldė sergančiuosius gatvėse ir maldavo jį, kad jie galėtų paliesti nors jo drabužio kraštą; ir visi, kurie jį palietė, pasveiko.'),
  (@b41, 7, 1, 'Tuomet susirinko pas jį fariziejai ir kai kurie iš raštininkų, kurie atėjo iš Jeruzalės.'),
  (@b41, 7, 2, 'Ir pamatę kai kuriuos jo mokinius valgančius duoną suterštomis, tai yra, neplautomis rankomis, jie kaltino.'),
  (@b41, 7, 3, 'Nes fariziejai ir visi žydai, laikydamiesi vyresniųjų tradicijų, nevalgo, jei dažnai nesiplauna rankų.'),
  (@b41, 7, 4, 'Ir jeigu jie nenusiplauna parėję iš turgaus – jie nevalgo. Ir yra daug ko kito, ko jie yra prisiėmę laikytis, kaip kad taurių ir puodų, žalvarinių indų ir stalų plovimo.'),
  (@b41, 7, 5, 'Tada fariziejai ir raštininkai jo paklausė: „Kodėl tavo mokiniai nevaikšto pagal vyresniųjų tradiciją, bet valgo duoną neplautomis rankomis?“'),
  (@b41, 7, 6, 'Jis atsakydamas tarė jiems: „Gerai Izaijas pranašavo apie jus, veidmainiai, kaip yra parašyta: ‘Ši tauta garbina mane savo lūpomis, bet jų širdis yra toli nuo manęs.'),
  (@b41, 7, 7, 'Tačiau veltui jie mane garbina, mokydami žmonių įsakymų kaip mokslų’.'),
  (@b41, 7, 8, 'Nes atidėdami į šoną Dievo įsakymą, jūs laikotės žmonių tradicijos, kaip kad puodų ir taurių plovimo; ir daug kitų panašių dalykų jūs darote“.'),
  (@b41, 7, 9, 'Ir jis tarė jiems: „Puikiai atmetate Dievo įsakymą, kad galėtumėte laikytis savo tradicijos.'),
  (@b41, 7, 10, 'Nes Mozė sakė: ‘Gerbk savo tėvą ir motiną’; ir: ‘Kas keiktų tėvą ar motiną, tas temiršta mirtimi’;'),
  (@b41, 7, 11, 'bet jūs sakote: ‘Jei kas pasakys savo tėvui ar motinai: čia yra Korban, tai yra, dovana, per kurią tu iš manęs turėtumei naudą, – tas bus laisvas’.'),
  (@b41, 7, 12, 'Ir leidžiate jam nieko nebedaryti dėl savo tėvo ar motinos;'),
  (@b41, 7, 13, 'darydami Dievo žodį neveiksmingu per savo tradiciją, kurią davėte; ir daug panašių dalykų darote“.'),
  (@b41, 7, 14, 'Ir pasišaukęs visą liaudį, jis tarė jiems: „Klausykitės manęs kiekvienas iš jūsų ir supraskite:'),
  (@b41, 7, 15, 'nėra nieko, kas iš išorės patekęs į žmogų galėtų jį suteršti; bet kas išeina iš jo, tai suteršia žmogų.'),
  (@b41, 7, 16, 'Jei kas turi ausis klausyti, teklauso“.'),
  (@b41, 7, 17, 'Ir kai jis nuo liaudies įėjo į namus, jo mokiniai paklausė jo dėl palyginimo.'),
  (@b41, 7, 18, 'O jis sako jiems: „Ar jūs irgi tokie be supratimo? Argi nesuvokiate, kad visa tai, kas iš išorės įeina į žmogų, negali jo suteršti?'),
  (@b41, 7, 19, 'Nes tai įeina ne į jo širdį, bet į pilvą, ir išeina laukan į išvietę, išvalant visą maistą.“'),
  (@b41, 7, 20, 'Ir jis tarė: „Kas išeina iš žmogaus, tai suteršia žmogų.'),
  (@b41, 7, 21, 'Nes iš vidaus, iš žmonių širdies, išeina piktos mintys, svetimavimai, paleistuvystės, žmogžudystės,'),
  (@b41, 7, 22, 'vagystės, godumas, nedorybė, apgaulė, gašlumas, pikta akis, piktžodžiavimas, išdidumas, kvailumas;'),
  (@b41, 7, 23, 'visos šitos blogybės eina iš vidaus ir suteršia žmogų“.'),
  (@b41, 7, 24, 'Ir iš ten jis kėlėsi ir nuėjo į Tyro bei Sidono ribas ir įėjo į namus, ir norėjo, kad niekas to nežinotų; bet jis negalėjo būti paslėptas.'),
  (@b41, 7, 25, 'Nes viena moteris, kurios jauna duktė turėjo netyrąją dvasią, išgirdo apie jį ir atėjusi parpuolė prie jo kojų;'),
  (@b41, 7, 26, 'ta moteris buvo graikė, sirofinikiečių tautybės; ir ji maldavo jo, kad jis išvarytų velnią iš jos dukters.'),
  (@b41, 7, 27, 'Bet Jėzus jai tarė: „Tegul pirmiau vaikai būna pasotinti, nes nedera imti vaikų duoną ir mesti ją šunims“.'),
  (@b41, 7, 28, 'Ir ji atsakė bei tarė jam: „Taip, Viešpatie; tačiau šunys maitinasi po stalu vaikų trupiniais“.'),
  (@b41, 7, 29, 'Ir jis jai tarė: „Dėl šito pasakymo eik; velnias išėjo iš tavo dukros“.'),
  (@b41, 7, 30, 'Ir kai ji parėjo į savo namus, ji rado velnią išėjusį, o jos dukra gulėjo ant lovos.'),
  (@b41, 7, 31, 'Ir vėl, išėjęs iš Tyro bei Sidono ribų, jis atėjo per Dekapolio ribų vidurį prie Galilėjos jūros.'),
  (@b41, 7, 32, 'Ir jie atveda pas jį kurčią ir turintį defektą savo kalboje; ir jie maldavo jį, kad uždėtų ant jo savo ranką.'),
  (@b41, 7, 33, 'Ir jis pasivedė jį į šoną nuo minios ir įkišo savo pirštus į jo ausis, ir spjovęs palietė jo liežuvį;'),
  (@b41, 7, 34, 'ir, žiūrėdamas į dangų, jis atsiduso ir sako jam: „Efata!“, tai yra: „Atsiverk!“'),
  (@b41, 7, 35, 'Ir tuojau jo ausys atsivėrė, ir jo liežuvio raištis atsilaisvino, ir jis kalbėjo aiškiai.'),
  (@b41, 7, 36, 'Ir jis juos įpareigojo, kad jie niekam nepasakotų; bet kuo labiau jis juos įpareigojo, tuo dar labiau jie tai garsino;'),
  (@b41, 7, 37, 'ir buvo be saiko nustebę, sakydami: „Jis visa atliko gerai – jis padaro, kad kurtieji girdi ir kad nebyliai kalba“.'),
  (@b41, 8, 1, 'Tomis dienomis esant labai didelei ir neturinčiai ko valgyti miniai, Jėzus pasišaukė savo mokinius ir sako jiems:'),
  (@b41, 8, 2, '„Man gaila minios, nes jau trys dienos jie yra su manimi ir neturi ko valgyti;'),
  (@b41, 8, 3, 'ir jei juos paleisiu į jų namus pasninkaujančius, jie nusilps kelyje, nes kai kurie iš jų atėjo iš toli“.'),
  (@b41, 8, 4, 'Ir jo mokiniai jam atsakė: „Iš kur čia dykumoje kas gali tuos žmones pasotinti duona?“'),
  (@b41, 8, 5, 'Ir jis paklausė jų: „Kiek turite kepalų?“ Ir jie tarė: „Septynis“.'),
  (@b41, 8, 6, 'Ir jis įsakė tautai susėsti ant žemės; ir paėmęs septynis kepalus, padėkojo, laužė, ir davė savo mokiniams, kad padėtų priešais juos; ir jie padėjo juos priešais tautą.'),
  (@b41, 8, 7, 'Ir jie turėjo keletą mažų žuvų; ir jis palaimino, ir įsakė padėti ir jas priešais juos.'),
  (@b41, 8, 8, 'Taip jie valgė ir pasisotino; ir jie surinko septynias pintines likusio sulaužyto maisto.'),
  (@b41, 8, 9, 'O valgiusiųjų buvo apie keturis tūkstančius; ir jis juos paleido.'),
  (@b41, 8, 10, 'Ir tuojau jis su savo mokiniais įėjo į laivą ir atvyko į Dalmanutos vietoves.'),
  (@b41, 8, 11, 'Ir išėjo fariziejai bei pradėjo jo klausinėti, siekdami iš jo ženklo iš dangaus, gundydami jį.'),
  (@b41, 8, 12, 'Ir jis giliai atsiduso savo dvasioje ir sako: „Kodėl ši karta siekia ženklo? Iš tiesų sakau jums: šitai kartai nebus duota ženklo“.'),
  (@b41, 8, 13, 'Ir jis paliko juos, ir vėl įlipęs į laivą nuvyko į kitą pusę.'),
  (@b41, 8, 14, 'Na, o mokiniai buvo pamiršę pasiimti duonos nei neturėjo su savimi laive daugiau kaip vieno kepalo.'),
  (@b41, 8, 15, 'Ir jis juos įpareigojo, sakydamas: „Žiūrėkite, saugokitės fariziejų raugo ir Erodo raugo“.'),
  (@b41, 8, 16, 'Ir jie tarpusavyje svarstė, sakydami: „Tai todėl, kad neturime duonos“.'),
  (@b41, 8, 17, 'Ir tai supratęs Jėzus jiems sako: „Kodėl svarstote, kad neturite duonos? Argi vis dar nesuvokiate ir nesuprantate? Ar jūsų širdis vis dar užkietėjusi?'),
  (@b41, 8, 18, 'Turėdami akis argi nematote? Ir turėdami ausis argi negirdite? Ir argi neprisimenate?'),
  (@b41, 8, 19, 'Kai laužiau penkis kepalus tarp penketo tūkstančių, kiek pilnų pintinių nuolaužų pririnkote?“ Jie sako jam: „Dvylika“.'),
  (@b41, 8, 20, '„Ir kai septynis – tarp ketverto tūkstančių, kiek pilnų pintinių nuolaužų pririnkote?“ Ir jie tarė: „Septynias“.'),
  (@b41, 8, 21, 'Ir jis tarė jiems: „Kaipgi nesuprantate?“'),
  (@b41, 8, 22, 'Ir jis ateina į Betsaidą; ir jie atveda jam akląjį, ir prašė jo, kad jį paliestų.'),
  (@b41, 8, 23, 'Ir jis paėmė akląjį už rankos ir išvedė jį iš miestelio; ir spjovęs jam į akis ir uždėjęs ant jo savo rankas paklausė jo, ar jis ką mato.'),
  (@b41, 8, 24, 'O jis pažvelgė ir tarė: „Matau žmones kaip medžius, vaikščiojančius“.'),
  (@b41, 8, 25, 'Po to jis vėl uždėjo savo rankas ant jo akių ir davė pažvelgti; ir jis pagijo, ir aiškiai matė kiekvieną.'),
  (@b41, 8, 26, 'Ir jis išsiuntė jį į jo namus, sakydamas: „Nei eik į miestelį, nei kam nors miestelyje tai pasakok“.'),
  (@b41, 8, 27, 'Ir išėjo Jėzus ir jo mokiniai į Pilypo Cezarėjos miestelius; ir kelyje jis paklausė savo mokinių, sakydamas jiems: „Kuo žmonės sako mane esantį?“'),
  (@b41, 8, 28, 'Ir jie atsakė: „Jonu Krikštytoju; bet kai kurie sako Elijas; o kiti – vienas iš pranašų“.'),
  (@b41, 8, 29, 'Ir jis sako jiems: „Bet kuo jūs sakote mane esantį?“ Ir Petras atsako ir taria jam: „Tu esi Kristus“.'),
  (@b41, 8, 30, 'Ir jis juos įpareigojo, kad niekam apie jį nepasakotų.'),
  (@b41, 8, 31, 'Ir jis pradėjo juos mokyti, kad žmogaus Sūnus turi daug iškentėti ir būti atmestas vyresniųjų ir vyriausiųjų kunigų bei raštininkų ir būti nužudytas, ir po trijų dienų prisikelti.'),
  (@b41, 8, 32, 'Ir jis kalbėjo šį pasakymą atvirai. Ir Petras paėmė jį bei pradėjo jį barti.'),
  (@b41, 8, 33, 'Bet atsigręžęs ir pažiūrėjęs į savo mokinius, jis subarė Petrą, sakydamas: „Pasitrauk už manęs, šėtone; nes tau patinka ne tai, kas Dievo, bet tai, kas žmonių“.'),
  (@b41, 8, 34, 'Ir pasišaukęs tautą bei savo mokinius jis tarė jiems: „Kas nori eiti paskui mane, tas teišsižada savęs, teima savo kryžių ir teseka paskui mane.'),
  (@b41, 8, 35, 'Nes kas nori išgelbėti savo gyvybę, tas ją praras; bet kas praras savo gyvybę dėl manęs ir dėl evangelijos, tas ją išgelbės.'),
  (@b41, 8, 36, 'Nes kokia gi nauda žmogui, jeigu jis laimės visą pasaulį, o praras savo sielą?'),
  (@b41, 8, 37, 'Arba ką žmogus duos mainais už savo sielą?'),
  (@b41, 8, 38, 'Todėl kas gėdysis manęs ir mano žodžių šioje svetimaujančioje ir nuodėmingoje kartoje, to gėdysis ir žmogaus Sūnus, kai jis ateis savo Tėvo šlovėje su šventaisiais angelais“.'),
  (@b41, 9, 1, 'Ir jis tarė jiems: „Iš tiesų sakau jums, kad yra kai kurie iš čia stovinčių, kurie neragaus mirties, kol nepamatys Dievo karalystės, ateinančios su galia“.'),
  (@b41, 9, 2, 'Ir po šešių dienų Jėzus pasiima Petrą, Jokūbą bei Joną ir užsiveda juos vienus nuošaliai į aukštą kalną; ir jis atsimainė priešais juos.'),
  (@b41, 9, 3, 'Ir jo drabužiai tapo spindintys, nepaprastai balti kaip sniegas; tokie, kaip joks vėlėjas žemėje negalėtų jų išbaltinti.'),
  (@b41, 9, 4, 'Ir ten jiems pasirodė Elijas su Moze, ir jie kalbėjo su Jėzumi.'),
  (@b41, 9, 5, 'Ir Petras atsakė bei tarė Jėzui: „Mokytojau, gera mums čia būti; padarykime tris padangtes: vieną tau, vieną Mozei ir vieną Elijui“.'),
  (@b41, 9, 6, 'Nes jis nežinojo, ką sakyti; nes jie buvo labai išsigandę.'),
  (@b41, 9, 7, 'Ir buvo debesis, kuris uždengė juos šešėliu; o iš debesies atėjo balsas, tardamas: „Šitas yra mano mylimasis Sūnus – jo klausykite“.'),
  (@b41, 9, 8, 'Ir staiga, kai jie apsidairė aplinkui, jie nieko nebematė, vien tik Jėzų su jais.'),
  (@b41, 9, 9, 'Ir kai jie leidosi nuo kalno, jis įpareigojo juos, kad jie niekam nepasakotų, ką jie matė, kol žmogaus Sūnus nebus prisikėlęs iš numirusių.'),
  (@b41, 9, 10, 'Ir jie saugojo šį pasakymą su savimi, klausinėdami vienas kito, ką turėtų reikšti prisikėlimas iš numirusių.'),
  (@b41, 9, 11, 'Ir jie klausė jo, sakydami: „Kodėl raštininkai sako, kad pirma turi ateiti Elijas?“'),
  (@b41, 9, 12, 'O jis jiems atsakydamas tarė: „Elijas iš tikrųjų ateina pirmas ir atstato viską; ir, kaip yra parašyta apie žmogaus Sūnų, kad jis turi daug iškentėti ir būti paniekintas.'),
  (@b41, 9, 13, 'Bet sakau jums, kad Elijas iš tiesų atėjo, ir jie padarė jam ką tik norėjo, kaip yra apie jį parašyta“.'),
  (@b41, 9, 14, 'Ir kai jis atėjo pas savo mokinius, jis pamatė aplink juos didžiulę minią ir juos klausinėjančius raštininkus.'),
  (@b41, 9, 15, 'Ir tuoj visa jį pamačiusi tauta labai nustebo ir pas jį bėgdama sveikino jį.'),
  (@b41, 9, 16, 'Ir jis paklausė raštininkų: „Apie ką klausinėjatės su jais?“'),
  (@b41, 9, 17, 'Ir vienas iš minios atsakydamas tarė: „Mokytojau, aš atvedžiau pas tave savo sūnų, kuris turi nebyliąją dvasią;'),
  (@b41, 9, 18, 'ir kur tik ji nutveria jį, ji drasko jį; ir jam eina putos, ir jis griežia dantimis, ir silpsta; ir aš kalbėjau su tavo mokiniais, kad jie ją išvarytų; bet jie negalėjo“.'),
  (@b41, 9, 19, 'Jis atsako jam ir taria: „O netikinti karta, kiek ilgai man reikės su jumis būti? Kiek ilgai man reikės jus kęsti? Atveskite jį pas mane“.'),
  (@b41, 9, 20, 'Ir jie jį atvedė pas jį; ir, jį pamačiusi, dvasia tuojau pat ėmė jį draskyti; ir jis nukrito ant žemės ir putodamasis voliojosi.'),
  (@b41, 9, 21, 'Ir jis paklausė jo tėvo: „Kaip seniai jį tai yra ištikę?“ Ir jis pasakė: „Nuo vaikystės.'),
  (@b41, 9, 22, 'Ir dažnai ji įmesdavo jį į ugnį ir į vandenis, kad jį sunaikintų; bet jei tu gali ką nors padaryti, pasigailėk mūsų ir padėk mums“.'),
  (@b41, 9, 23, 'Jėzus jam tarė: „Jei tu gali tikėti, viskas yra įmanoma tam, kuris tiki“.'),
  (@b41, 9, 24, 'Ir tuojau vaiko tėvas sušuko ir tarė su ašaromis: „Viešpatie, aš tikiu! Padėk mano netikėjimui“.'),
  (@b41, 9, 25, 'Kai Jėzus pamatė susibėgančią tautą, jis sudraudė netyrąją dvasią, sakydamas jai: „Tu, nebyli ir kurčia dvasia, įpareigoju tave: išeik iš jo ir daugiau į jį nebeįeik!“'),
  (@b41, 9, 26, 'Ir dvasia šaukė ir smarkiai jį draskė, ir išėjo iš jo; ir jis buvo tarsi negyvas, kad net daugelis sakė: „Jis miręs“.'),
  (@b41, 9, 27, 'Bet Jėzus paėmė jį už rankos ir jį pakėlė; ir jis atsikėlė.'),
  (@b41, 9, 28, 'Ir kai jis buvo įėjęs į namus, jo mokiniai paklausė jo atskirai: „Kodėl negalėjome jos išvaryti?“'),
  (@b41, 9, 29, 'Ir jis tarė jiems: „Ši veislė neišeina per nieką kita, bet tik per maldą ir pasninką“.'),
  (@b41, 9, 30, 'Ir iš ten išėję jie keliavo per Galilėją; ir jis nenorėjo, kad kas nors tai žinotų.'),
  (@b41, 9, 31, 'Nes jis mokė savo mokinius ir tarė jiems: „Žmogaus Sūnus yra atiduotas į žmonių rankas, ir jie jį nužudys; ir po jo nužudymo jis trečią dieną prisikels“.'),
  (@b41, 9, 32, 'Bet jie nesuprato to pasakymo ir bijojo jo klausti.'),
  (@b41, 9, 33, 'Ir jis atėjo į Kafernaumą; ir būdamas namuose jis paklausė jų: „Apie ką tarpusavyje ginčijotės kelyje?“'),
  (@b41, 9, 34, 'Bet jie tylėjo, nes kelyje jie ginčijosi tarpusavyje, kas turėtų būti didžiausias.'),
  (@b41, 9, 35, 'Ir atsisėdęs jis pašaukė dvylika ir sako jiems: „Jei kas nori būti pirmas, tas turi būti iš visų paskutinis ir visų tarnas“.'),
  (@b41, 9, 36, 'Ir paėmė vaiką bei pastatė jį tarp jų; ir paėmęs jį ant rankų tarė jiems:'),
  (@b41, 9, 37, '„Kas priims vieną iš tokių vaikų mano vardu, tas priima mane; o kas priims mane, ne mane priima, bet tą, kuris mane siuntė“.'),
  (@b41, 9, 38, 'Ir Jonas jam atsakė, tardamas: „Mokytojau, mes matėme vieną išvarinėjantį velnius tavo vardu, bet jis neseka paskui mus; ir mes jam draudėme, kadangi jis neseka paskui mus“.'),
  (@b41, 9, 39, 'Bet Jėzus tarė: „Nedrauskite jam, nes nėra nei vieno, kuris darytų mano vardu stebuklą ir čia pat kalbėtų apie mane pikta.'),
  (@b41, 9, 40, 'Nes kas ne prieš mus, tas yra mūsų pusėje.'),
  (@b41, 9, 41, 'Nes kas jums duos atsigerti taurę vandens mano vardu dėl to, kad priklausote Kristui, iš tiesų sakau jums: tas nepraras savojo atlygio.'),
  (@b41, 9, 42, 'O kas papiktins vieną iš šitų mažųjų, kurie tiki manimi, tai tam būtų geriau, kad jam ant kaklo būtų pakabintas malūno akmuo ir jis būtų įmestas į jūrą.'),
  (@b41, 9, 43, 'Ir jei tavo ranka tave piktina, nukirsk ją: tau geriau įeiti į gyvenimą luošam, negu turint dvi rankas eiti į pragarą, į ugnį, kuri niekada neužges,'),
  (@b41, 9, 44, 'kur jų kirminas nemiršta ir ugnis neužgęsta.'),
  (@b41, 9, 45, 'Ir jei tavo koja tave piktina, nukirsk ją: tau geriau įeiti į gyvenimą raišam, negu turint dvi kojas būti įmestam į pragarą, į ugnį, kuri niekada neužges,'),
  (@b41, 9, 46, 'kur jų kirminas nemiršta ir ugnis neužgęsta.'),
  (@b41, 9, 47, 'Ir jei tavo akis tave piktina, išlupk ją lauk: tau geriau įeiti į Dievo karalystę su viena akimi, negu turint dvi akis būti įmestam į pragaro ugnį,'),
  (@b41, 9, 48, 'kur jų kirminas nemiršta ir ugnis neužgęsta.'),
  (@b41, 9, 49, 'Nes kiekvienas bus pasūdytas ugnimi, ir kiekviena auka bus pasūdyta druska.'),
  (@b41, 9, 50, 'Druska yra gerai, bet jei druska praranda savo sūrumą, kuo gi ją bepaskaninsi? Turėkite savyje druskos ir būkite taikūs vienas su kitu“.'),
  (@b41, 10, 1, 'Ir iš ten pakilęs jis ateina į Judėjos ribas, prie tolimesnio Jordano krašto; ir tauta vėl rinkosi pas jį; ir jis vėl juos mokė, kaip buvo pratęs.'),
  (@b41, 10, 2, 'Ir fariziejai atėjo pas jį ir jį gundydami klausė jo: „Ar teisėta vyrui pašalinti savo žmoną?“'),
  (@b41, 10, 3, 'O jis atsakydamas tarė jiems: „Ką Mozė jums įsakė?“'),
  (@b41, 10, 4, 'Ir jie tarė: „Mozė leido parašyti skyrybų raštą ir ją pašalinti“.'),
  (@b41, 10, 5, 'O Jėzus atsakydamas tarė jiems: „Dėl jūsų širdies kietumo jis parašė jums šį prisakymą.'),
  (@b41, 10, 6, 'Bet nuo sutvėrimo pradžios Dievas padarė juos vyriškos lyties ir moteriškos lyties.'),
  (@b41, 10, 7, 'Dėl šios priežasties vyras savo tėvą ir motiną paliks, ir prie savo žmonos prilips;'),
  (@b41, 10, 8, 'ir jie abu bus vienas kūnas; taip, kad jie jau nebėra du, bet vienas kūnas.'),
  (@b41, 10, 9, 'Todėl ką Dievas sujungė, žmogus teneperskiria“.'),
  (@b41, 10, 10, 'Ir namuose jo mokiniai vėl jo klausė apie tą patį.'),
  (@b41, 10, 11, 'Ir jis sako jiems: „Kas pašalins savo žmoną ir ves kitą, tas jai svetimauja.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b41, 10, 12, 'Ir jei moteris pašalins savo vyrą ir ištekės už kito, ji svetimauja“.'),
  (@b41, 10, 13, 'Ir jie atvedė pas jį mažus vaikus, kad jis juos paliestų; o jo mokiniai barė tuos, kurie juos atvedė.'),
  (@b41, 10, 14, 'Bet kai Jėzus tai pamatė, jis buvo labai nepatenkintas ir tarė jiems: „Leiskite vaikeliams ateiti pas mane ir nedrauskite jiems, nes tokių yra Dievo karalystė.'),
  (@b41, 10, 15, 'Iš tiesų sakau jums: kas nepriims Dievo karalystės kaip vaikelis, tas neįeis į ją“.'),
  (@b41, 10, 16, 'Ir jis ėmė juos į savo rankas, dėjo ant jų savo rankas ir juos palaimino.'),
  (@b41, 10, 17, 'Ir kai jis buvo beišeinąs į kelią, atbėgo vienas, atsiklaupė jam ir jo paklausė: „Gerasis Mokytojau, ką turiu daryti, kad paveldėčiau amžinąjį gyvenimą?“'),
  (@b41, 10, 18, 'Ir Jėzus jam tarė: „Kodėl mane vadini geru? Nėra nei vieno gero, o tik vienas, tai yra Dievas.'),
  (@b41, 10, 19, 'Tu žinai įsakymus: ‘Nesvetimauk’, ‘Nežudyk’, ‘Nevok’, ‘Melagingai neliudyk’, ‘Neapgaudinėk’, ‘Gerbk savo tėvą ir motiną’“.'),
  (@b41, 10, 20, 'Ir jis atsakydamas tarė jam: „Mokytojau, visų šitų laikiausi nuo jaunystės“.'),
  (@b41, 10, 21, 'Tada Jėzus, žvelgdamas į jį, pamilo jį ir jam tarė: „Vieno tau trūksta: eik, parduok viską, ką turi, ir atiduok vargšams, ir turėsi lobį danguje; ir ateik, imk kryžių ir sek paskui mane“.'),
  (@b41, 10, 22, 'Ir jis nuliūdo dėl šio pasakymo ir nuėjo liūdėdamas, nes jis turėjo didelius turtus.'),
  (@b41, 10, 23, 'Ir Jėzus apžvelgė aplinkui ir sako savo mokiniams: „Kaip sunkiai tie, kurie turi turtus, įeis į Dievo karalystę!“'),
  (@b41, 10, 24, 'Ir mokiniai buvo apstulbinti jo žodžių. Bet Jėzus vėl atsako ir taria jiems: „Vaikai, kaip sunku tiems, kurie pasitiki turtais, įeiti į Dievo karalystę!'),
  (@b41, 10, 25, 'Lengviau kupranugariui pralįsti pro adatos auselę, negu turtuoliui įeiti į Dievo karalystę“.'),
  (@b41, 10, 26, 'Ir jie buvo be saiko apstulbę, kalbėdami tarpusavyje: „Kas gi tada gali būti išgelbėtas?“'),
  (@b41, 10, 27, 'O Jėzus žiūrėdamas į juos sako: „Žmonėms tai yra neįmanoma, bet ne Dievui, nes Dievui viskas yra įmanoma“.'),
  (@b41, 10, 28, 'Tada Petras pradėjo jam sakyti: „Štai mes viską palikome ir sekėme paskui tave“.'),
  (@b41, 10, 29, 'Ir Jėzus atsakydamas tarė: „Iš tiesų jums sakau: nėra nei vieno, kuris paliktų namus ar brolius, ar seseris, ar tėvą, ar motiną, ar žmoną, ar vaikus, ar žemes dėl manęs ir evangelijos,'),
  (@b41, 10, 30, 'bet kuris jau dabar, šiuo laiku, negautų šimteriopai namų ir brolių, ir seserų, ir motinų, ir vaikų, ir žemių kartu su persekiojimais; ir ateinančiame pasaulyje – amžinojo gyvenimo.'),
  (@b41, 10, 31, 'Bet daugelis pirmųjų bus paskutiniai; o paskutiniųjų – pirmi“.'),
  (@b41, 10, 32, 'Ir jie buvo kelyje, beeiną aukštyn į Jeruzalę; ir Jėzus ėjo pirma jų; ir jie buvo nustebę; ir sekdami paskui jie bijojo. Ir jis vėl paėmė dvylika ir pradėjo jiems pasakoti, kas jam turės atsitikti,'),
  (@b41, 10, 33, 'sakydamas: „Štai mes einame į Jeruzalę; ir žmogaus Sūnus bus atiduotas vyriausiems kunigams ir raštininkams; ir jie pasmerks jį mirčiai ir atiduos jį pagonims;'),
  (@b41, 10, 34, 'ir jie tyčiosis iš jo, jį nuplaks, spjaudys ant jo ir jį nužudys; ir trečią dieną jis prisikels“.'),
  (@b41, 10, 35, 'Ir atėjo pas jį Zebediejaus sūnūs Jokūbas ir Jonas, sakydami: „Mokytojau, norime, kad padarytum mums, ko tik paprašysime“.'),
  (@b41, 10, 36, 'Ir jis tarė jiems: „Ką norite, kad jums padaryčiau?“'),
  (@b41, 10, 37, 'Jie tarė jam: „Suteik mums, kad galėtume sėdėti vienas tavo dešinėje, o kitas tavo kairėje tavo šlovėje“.'),
  (@b41, 10, 38, 'Bet Jėzus jiems tarė: „Jūs nežinote, ko prašote – ar galite gerti iš taurės, iš kurios aš geriu? Ir būti pakrikštyti krikštu, kuriuo aš esu krikštijamas?“'),
  (@b41, 10, 39, 'Ir jie tarė jam: „Galime“. O Jėzus jiems tarė: „Iš tiesų gersite iš taurės, iš kurios aš geriu; ir būsite pakrikštyti krikštu, kuriuo aš esu krikštijamas;'),
  (@b41, 10, 40, 'bet sėdėti mano dešinėje ir mano kairėje – ne mano, kad duočiau; bet bus duota tiems, kuriems tai yra paruošta“.'),
  (@b41, 10, 41, 'Ir kai dešimt tai išgirdo, jie pradėjo labai piktintis Jokūbu ir Jonu.'),
  (@b41, 10, 42, 'Bet Jėzus pasišaukė juos ir sako jiems: „Jūs žinote, kad tie, kurie atsakingi valdyti pagonis, jiems viešpatauja; ir jų didieji juos valdo.'),
  (@b41, 10, 43, 'Bet tarp jūsų taip nebus; bet kas nori būti didis tarp jūsų, tas bus jūsų tarnautojas;'),
  (@b41, 10, 44, 'ir kas iš jūsų nori būti vyriausias, bus visų tarnas.'),
  (@b41, 10, 45, 'Nes ir žmogaus Sūnus atėjo ne kad jam tarnautų, bet tarnauti ir atiduoti savo gyvybę išpirkai už daugelį“.'),
  (@b41, 10, 46, 'Ir jie atėjo į Jerichą; ir kai jis ėjo iš Jericho su savo mokiniais ir su dideliu skaičiumi žmonių, prie vieškelio sėdėjo beelgetaujantis aklas Bartimiejus, Timiejaus sūnus.'),
  (@b41, 10, 47, 'Ir kai jis išgirdo, kad tai buvo Jėzus iš Nazareto, jis pradėjo šaukti ir sakyti: „Jėzau, Dovydo Sūnau, pasigailėk manęs!“'),
  (@b41, 10, 48, 'Ir daugelis jį įpareigojo, kad jis tylėtų, bet jis dar labiau šaukė: „Dovydo Sūnau, pasigailėk manęs!“'),
  (@b41, 10, 49, 'Ir Jėzus sustojo ir įsakė pašaukti jį. Ir jie pašaukė akląjį, jam sakydami: „Būk paguostas, kelkis – jis tave šaukia“.'),
  (@b41, 10, 50, 'Ir jis, nusimetęs savo drabužį, atsikėlė ir atėjo pas Jėzų.'),
  (@b41, 10, 51, 'Ir Jėzus atsakė ir tarė jam: „Ką nori kad tau padaryčiau?“ Aklasis jam tarė: „Viešpatie, kad praregėčiau“.'),
  (@b41, 10, 52, 'Ir Jėzus jam tarė: „Eik; tavo tikėjimas tave išgydė“. Ir tuoj pat jis praregėjo ir nusekė paskui Jėzų keliu.'),
  (@b41, 11, 1, 'Ir kai jie prisiartino prie Jeruzalės, prie Betfagės ir Betanijos, ties Alyvų kalnu, jis išsiuntė du savo mokinius'),
  (@b41, 11, 2, 'ir tarė jiems: „Eikite į priešais jus esantį kaimą; ir vos tik į jį įėję rasite pririštą asiliuką, ant kurio niekada žmogus nėra sėdėjęs: atriškite jį ir atveskite.'),
  (@b41, 11, 3, 'O jei kas jums sakytų: ‘Kodėl tai darote?’ sakykite, kad Viešpačiui jo reikia; ir jis tuojau pat jį čia pasiųs“.'),
  (@b41, 11, 4, 'Ir jie nuėjo ir rado pririštą asiliuką lauke prie durų, vietoje, kur susitinka du keliai; ir jie atrišo jį.'),
  (@b41, 11, 5, 'Ir kai kurie iš ten stovinčių jiems tarė: „Ką darote atrišdami asiliuką?“'),
  (@b41, 11, 6, 'Ir jie pasakė jiems kaip Jėzus buvo įsakęs; ir jie leido jiems eiti.'),
  (@b41, 11, 7, 'Ir jie atvedė asiliuką Jėzui ir užmetė ant jo savo drabužius; ir jis atsisėdo ant jo.'),
  (@b41, 11, 8, 'Ir daugelis tiesė kelyje savo drabužius; o kiti kirto medžių šakas ir barstė jas kelyje.'),
  (@b41, 11, 9, 'Ir tie, kurie ėjo priekyje, ir tie, kurie sekė paskui, šaukė, sakydami: „Osana! Palaimintas yra tas, kuris ateina Viešpaties vardu!'),
  (@b41, 11, 10, 'Palaiminta tebūna mūsų tėvo Dovydo karalystė, kuri ateina Viešpaties vardu! Osana aukštybėse!“'),
  (@b41, 11, 11, 'Ir Jėzus įžengė į Jeruzalę ir į šventyklą; ir kai jis visa apžiūrėjo ir jau buvo atėjęs vakaras, jis su dvylika išėjo į Betaniją.'),
  (@b41, 11, 12, 'Ir rytojaus dieną, kai jie ėjo iš Betanijos, jis buvo alkanas;'),
  (@b41, 11, 13, 'ir, matydamas iš tolo figmedį su lapais, jis priėjo, gal kartais ką ant jo ras; ir prie jo priėjęs jis nerado nieko, tik lapus, nes dar nebuvo figų metas.'),
  (@b41, 11, 14, 'Ir Jėzus atsakydamas tarė jam: „Nuo šiol niekas nevalgys nuo tavęs vaisiaus per amžius“. O jo mokiniai tai girdėjo.'),
  (@b41, 11, 15, 'Ir jie ateina į Jeruzalę; ir Jėzus įėjo į šventyklą ir pradėjo varyti lauk tuos, kurie pardavinėjo ir pirko šventykloje; ir išvartė pinigų keitėjų stalus bei krėslus tų, kurie pardavinėjo balandžius;'),
  (@b41, 11, 16, 'ir niekam neleido per šventyklą nešti jokio indo.'),
  (@b41, 11, 17, 'Ir jis mokė, sakydamas jiems: „Argi nėra parašyta: ‘Mano namai visų tautų bus vadinami maldos namais’? Bet jūs pavertėte juos vagių lindyne“.'),
  (@b41, 11, 18, 'Ir raštininkai bei vyriausieji kunigai tai girdėjo ir ieškojo, kaip jie galėtų jį sunaikinti; nes jie jo bijojo, kadangi visa tauta stebėjosi jo mokslu.'),
  (@b41, 11, 19, 'Ir atėjus vakarui jis išėjo iš miesto.'),
  (@b41, 11, 20, 'Ir ryte, eidami pro šalį, jie pamatė figmedį nudžiūvusį nuo pat šaknų.'),
  (@b41, 11, 21, 'Ir Petras prisiminęs sako jam: „Mokytojau, žiūrėk – figmedis, kurį tu prakeikei, – nudžiūvęs“.'),
  (@b41, 11, 22, 'Ir Jėzus atsakydamas jiems sako: „Turėkite tikėjimą Dievu.'),
  (@b41, 11, 23, 'Nes iš tiesų sakau jums: kas pasakys šitam kalnui: ‘Pasikelk ir meskis į jūrą’ ir savo širdyje neabejos, bet tikės, kad įvyks tai, ką jis sako, jis turės, ką besakytų.'),
  (@b41, 11, 24, 'Todėl sakau jums: ko benorėtumėte, kai meldžiatės, tikėkite, kad tai gausite, ir tai turėsite.'),
  (@b41, 11, 25, 'Ir kai stovite melsdamiesi, atleiskite, jei ką nors turite prieš ką; kad ir jūsų Tėvas, kuris yra danguje, atleistų jums jūsų nusižengimus.'),
  (@b41, 11, 26, 'Bet jei jūs neatleidžiate, tai nei jūsų Tėvas, kuris yra danguje, neatleis jūsų nusižengimų“.'),
  (@b41, 11, 27, 'Ir jie vėl atėjo į Jeruzalę; ir jam vaikščiojant šventykloje pas jį atėjo vyriausieji kunigai, raštininkai ir vyresnieji'),
  (@b41, 11, 28, 'ir sako jam: „Kokia valdžia tu tai darai ir kas tau davė šią valdžią tai daryti?“'),
  (@b41, 11, 29, 'O Jėzus atsakydamas tarė jiems: „Aš irgi paklausiu jūsų vieno klausimo, atsakykite man, ir aš jums pasakysiu, kokia valdžia tai darau.'),
  (@b41, 11, 30, 'Jono krikštas – ar tai buvo iš dangaus, ar iš žmonių? Atsakykite man“.'),
  (@b41, 11, 31, 'Ir jie samprotavo tarpusavyje, sakydami: „Jei pasakysime: ‘Iš dangaus’, jis pasakys: ‘Kodėl tad netikėjote juo?’'),
  (@b41, 11, 32, 'Bet jei: ‘Iš žmonių’?“; jie bijojo tautos, nes visi laikė Joną esant tikru pranašu.'),
  (@b41, 11, 33, 'Ir jie atsakydami tarė Jėzui: „Mes nežinome“. Ir Jėzus atsakydamas sako jiems: „Tai ir aš jums nepasakysiu, kokia valdžia tai darau“.'),
  (@b41, 12, 1, 'Ir jis pradėjo jiems kalbėti palyginimais. „Vienas žmogus pasodino vynuogyną, aptvėrė jį tvora, iškasė vietą vyninei, pastatė bokštą, išnuomojo jį žemdirbiams ir išvyko į tolimą šalį.'),
  (@b41, 12, 2, 'Ir atėjus laikui jis siuntė žemdirbiams tarną, kad jis iš žemdirbių atsiimtų vynuogyno vaisių.'),
  (@b41, 12, 3, 'O jie pagavo jį, sumušė ir paleido tuščiomis.'),
  (@b41, 12, 4, 'Ir vėl jis pasiuntė jiems kitą tarną; o jie apmėtė jį akmenimis, sužeidė jį į galvą ir apgėdinę išsiuntė.'),
  (@b41, 12, 5, 'Ir vėl jis siuntė kitą; o jie užmušė jį ir daugelį kitų: vienus sumušdami, kitus užmušdami.'),
  (@b41, 12, 6, 'Todėl dar turėdamas vieną sūnų, jo labai mylimą, jis išsiuntė ir jį pas juos paskutinį, sakydamas: ‘Jie gerbs mano sūnų’.'),
  (@b41, 12, 7, 'Bet tie žemdirbiai kalbėjo tarpusavyje: ‘Šitas yra paveldėtojas; eime, užmuškime jį, ir paveldas bus mūsų’.'),
  (@b41, 12, 8, 'Ir jie paėmę jį užmušė ir išmetė iš vynuogyno.'),
  (@b41, 12, 9, 'Tad ką gi padarys vynuogyno viešpats? Jis ateis ir sunaikins žemdirbius, ir duos vynuogyną kitiems.'),
  (@b41, 12, 10, 'Ir argi neskaitėte šito Rašto: ‘Akmuo, kurį atmetė statytojai, tapo kertės pagrindu.'),
  (@b41, 12, 11, 'Tai buvo Viešpaties darbas, ir tai yra nuostabu mūsų akyse’?“'),
  (@b41, 12, 12, 'Ir jie siekė jį suimti, bet bijojo tautos, nes žinojo, kad jis kalbėjo palyginimą prieš juos; ir jie paliko jį ir nuėjo.'),
  (@b41, 12, 13, 'Ir jie nusiunčia pas jį kai kuriuos iš fariziejų ir iš erodininkų, kad sugautų jį jo žodžiuose.'),
  (@b41, 12, 14, 'Ir kai jie atėjo, jie sako jam: „Mokytojau, žinome, kad esi teisus ir niekam nepataikauji; nes tu neatsižvelgi į žmonių asmenis, bet mokai Dievo kelio tiesoje; ar teisėta duoti duoklę ciesoriui, ar ne?'),
  (@b41, 12, 15, 'Ar mums duoti, ar neduoti?“ Bet jis, žinodamas jų veidmainystę, jiems tarė: „Kodėl mane gundote? Atneškite man denarą, kad jį pamatyčiau“.'),
  (@b41, 12, 16, 'Ir jie atnešė. Ir jis sako jiems: „Kieno tai atvaizdas ir užrašas?“ Ir jie tarė jam: „Ciesoriaus“.'),
  (@b41, 12, 17, 'O Jėzus atsakydamas jiems tarė: „Duokite ciesoriui, kas yra ciesoriaus, o Dievui – kas Dievo“. Ir jie stebėjosi juo.'),
  (@b41, 12, 18, 'Tada pas jį atėjo sadukiejai, kurie sako, kad nėra prisikėlimo; ir jie paklausė jo, sakydami:'),
  (@b41, 12, 19, '„Mokytojau, Mozė mums rašė: ‘Jei kieno brolis miršta ir po savęs palieka savo žmoną, ir nepalieka vaikų, tuomet jo brolis turi imti jo žmoną ir prikelti savo broliui sėklą’.'),
  (@b41, 12, 20, 'Na, o buvo septyni broliai, ir pirmasis ėmė žmoną, bet mirdamas nepaliko sėklos.'),
  (@b41, 12, 21, 'Ir antrasis ją ėmė ir mirė, ir nepaliko sėklos; ir taip pat trečiasis.'),
  (@b41, 12, 22, 'Ir septyni ją turėjo, bet nepaliko sėklos; paskutinė iš visų mirė ir moteris.'),
  (@b41, 12, 23, 'Todėl prisikėlime, kai jie prisikels, kurio iš jų bus ji žmona? Nes septyni turėjo ją už žmoną“.'),
  (@b41, 12, 24, 'Ir Jėzus atsakydamas tarė jiems: „Argi ne todėl klystate, kad nepažįstate nei Raštų, nei Dievo jėgos?'),
  (@b41, 12, 25, 'Nes kai jie prisikels iš mirusių, jie nei ves, nei tekės; bet yra kaip angelai, kurie yra danguje.'),
  (@b41, 12, 26, 'O dėl mirusiųjų, kad jie prisikelia, – argi neskaitėte Mozės knygoje, kaip Dievas krūme kalbėjo jam, sakydamas: ‘Aš esu Abraomo Dievas, Izaoko Dievas ir Jokūbo Dievas’?'),
  (@b41, 12, 27, 'Jis nėra mirusiųjų Dievas, bet gyvųjų Dievas; todėl jūs labai klystate“.'),
  (@b41, 12, 28, 'Ir atėjo vienas iš raštininkų ir išgirdęs juos kartu samprotaujant bei pastebėjęs, kad jis jiems gerai atsakė, paklausė jo: „Kuris yra pirmas iš visų įsakymų?“'),
  (@b41, 12, 29, 'Ir Jėzus jam atsakė: „Pirmas iš visų įsakymų yra: ‘Klausyk, o Izraeli, Viešpats mūsų Dievas yra vienas Viešpats;'),
  (@b41, 12, 30, 'ir mylėk Viešpatį, savo Dievą, visa savo širdimi, visa savo siela, visu savo protu ir visomis savo jėgomis’, – šis yra pirmasis įsakymas.'),
  (@b41, 12, 31, 'O antrasis yra panašus, būtent šis: ‘Mylėk savo artimą kaip save patį’. Nėra kito įsakymo, didesnio už šituos“.'),
  (@b41, 12, 32, 'Ir raštininkas jam tarė: „Gerai, Mokytojau, tu pasakei tiesą, nes yra vienas Dievas; ir nėra kito, tik jis;'),
  (@b41, 12, 33, 'ir mylėti jį visa širdimi, visu supratimu, visa siela ir visomis jėgomis, ir mylėti savo artimą kaip save patį yra daugiau negu visos visiškai sudeginamos atnašos ir aukos“.'),
  (@b41, 12, 34, 'Ir pamatęs, kad jis atsakė protingai, Jėzus jam tarė: „Tu netoli nuo Dievo karalystės“. Ir niekas po to nebedrįso jo klausinėti.'),
  (@b41, 12, 35, 'Ir mokydamas šventykloje Jėzus atsakydamas tarė: „Kaipgi raštininkai sako, kad Kristus yra Dovydo Sūnus?'),
  (@b41, 12, 36, 'Nes pats Dovydas sakė Šventąja Dvasia: ‘VIEŠPATS tarė mano Viešpačiui: Sėskis mano dešinėje, kol padarysiu tavo priešus tavo pakoju’.'),
  (@b41, 12, 37, 'Taigi pats Dovydas jį vadina Viešpačiu; tai kaipgi jis yra jo sūnus?“ Ir paprasti žmonės mielai jo klausėsi.'),
  (@b41, 12, 38, 'Ir jis kalbėjo jiems savo mokslu: „Saugokitės raštininkų, kurie mėgsta vaikščioti ilgais drabužiais ir mėgsta sveikinimus turgavietėse,'),
  (@b41, 12, 39, 'ir pirmuosius krėslus sinagogose, ir aukščiausias vietas pokyliuose;'),
  (@b41, 12, 40, 'kurie praryja našlių namus ir apsimestinai kalba ilgas maldas; šitie gaus didesnį pasmerkimą“.'),
  (@b41, 12, 41, 'Ir Jėzus atsisėdo priešais iždinę ir žiūrėjo, kaip tauta meta pinigus į iždinę; ir daugelis, kurie buvo turtingi, įmetė daug.'),
  (@b41, 12, 42, 'Ir atėjo viena vargšė našlė, ir ji įmetė dvi leptas, kurios sudaro kvadrantą.'),
  (@b41, 12, 43, 'Ir pasišaukęs savo mokinius jis sako jiems: „Iš tiesų sakau jums, kad ši varginga našlė įmetė daugiau už visus, kurie metė į iždinę;'),
  (@b41, 12, 44, 'nes jie visi įmetė iš savo pertekliaus; bet ji iš savo nepritekliaus įmetė viską, ką turėjo, visą savo pragyvenimą“.'),
  (@b41, 13, 1, 'Ir jam išeinant iš šventyklos, vienas iš jo mokinių jam sako: „Mokytojau, žiūrėk, kokie akmenys ir kokie čia pastatai!“'),
  (@b41, 13, 2, 'O Jėzus atsakydamas jam tarė: „Ar matai šituos didžiulius pastatus? Čia neliks akmens ant akmens, kurie nebūtų išgriauti“.'),
  (@b41, 13, 3, 'Ir kai jis sėdėjo ant Alyvų kalno priešais šventyklą, Petras, Jokūbas, Jonas ir Andriejus klausė jo asmeniškai:'),
  (@b41, 13, 4, '„Pasakyk mums, kada tai bus? Ir koks bus ženklas, kai visa tai išsipildys?“'),
  (@b41, 13, 5, 'Ir Jėzus jiems atsakydamas pradėjo kalbėti: „Žiūrėkite, kad niekas jūsų nesuklaidintų;'),
  (@b41, 13, 6, 'nes daugelis ateis mano vardu, sakydami: ‘Aš esu Kristus’, ir daugelį suklaidins.'),
  (@b41, 13, 7, 'Ir kai girdėsite apie karus ir karų gandus, nepradėkite nerimauti, nes tai turi būti; bet dar ne galas.'),
  (@b41, 13, 8, 'Nes tauta sukils prieš tautą ir karalystė prieš karalystę; ir bus žemės drebėjimų įvairiose vietose, ir bus badmečių ir neramumų – šie yra sielvartų pradžios.'),
  (@b41, 13, 9, 'Bet žiūrėkitės, nes jie atiduos jus taryboms; ir jūs būsite mušami sinagogose, ir dėl manęs jus atves valdytojų ir karalių akivaizdon dėl liudijimo prieš juos.'),
  (@b41, 13, 10, 'Ir evangelija pirmiausia turi būti paskelbta tarp visų tautų.'),
  (@b41, 13, 11, 'Bet kai jie ves jus ir jus atiduos, nesirūpinkite iš anksto, ką kalbėsite, nei iš anksto apgalvokite; bet, kas jums bus tą valandą duota, tai kalbėkite; nes tai ne jūs, kurie kalbate, bet Šventoji Dvasia.'),
  (@b41, 13, 12, 'Na, o brolis išduos brolį mirčiai ir tėvas – sūnų; ir vaikai sukils prieš savo tėvus ir padarys, kad jie būtų nužudyti.'),
  (@b41, 13, 13, 'Ir dėl mano vardo jūsų nekęs visi; bet kas ištvers iki galo, tas bus išgelbėtas.'),
  (@b41, 13, 14, 'Bet kai pamatysite per pranašą Danielių kalbėtą suniokojimo bjaurastį, stovinčią ten, kur ji neturėtų (tas, kas skaito, tesupranta), tuomet tie, kurie bus Judėjoje, tebėga į kalnus;'),
  (@b41, 13, 15, 'o kas bus ant namo viršaus, tenelipa žemyn į namą ir teneįeina vidun ko nors pasiimti iš savo namo;'),
  (@b41, 13, 16, 'o kas ant lauko, tenegrįžta pasiimti savo drabužio.'),
  (@b41, 13, 17, 'Bet vargas nėščioms ir žindančioms tomis dienomis!'),
  (@b41, 13, 18, 'Ir melskitės, kad jums netektų bėgti žiemą.'),
  (@b41, 13, 19, 'Nes tomis dienomis bus toks suspaudimas, kokio nebuvo nuo sutvėrimo, kurį Dievas sutvėrė, pradžios iki šio laiko ir nebebus.'),
  (@b41, 13, 20, 'Ir jei Viešpats nebūtų sutrumpinęs tų dienų, neišsigelbėtų nei vienas kūnas; bet dėl išrinktųjų, kuriuos jis išsirinko, jis sutrumpino tas dienas.'),
  (@b41, 13, 21, 'Ir tada, jei kas nors jums sakys: ‘Štai čia Kristus!’ arba ‘Štai, jis tenai!‘ – netikėkite juo;'),
  (@b41, 13, 22, 'nes iškils netikrų kristų ir netikrų pranašų ir rodys ženklus bei stebuklus, kad suviliotų, jei įmanoma, net išrinktuosius.'),
  (@b41, 13, 23, 'Bet jūs saugokitės – štai pasakiau jums viską iš anksto.'),
  (@b41, 13, 24, 'Bet tomis dienomis, po ano suspaudimo, saulė užtems, ir mėnulis nebeduos savo šviesos,'),
  (@b41, 13, 25, 'ir dangaus žvaigždės kris, ir jėgos, kurios yra danguje, bus sudrebintos.'),
  (@b41, 13, 26, 'Ir tada jie pamatys žmogaus Sūnų, ateinantį debesyse su didžia jėga bei šlove.'),
  (@b41, 13, 27, 'Ir tuomet jis pasiųs savo angelus ir surinks savo išrinktuosius iš keturių vėjų, nuo tolimiausio žemės pakraščio iki tolimiausio dangaus pakraščio.'),
  (@b41, 13, 28, 'Pasimokykite palyginimo iš figmedžio: kai jo šaka suminkštėja ir išleidžia lapus, žinote, kad vasara yra arti;'),
  (@b41, 13, 29, 'taip pat ir jūs – kai pamatysite tai vykstant, žinokite, kad tai yra arti, prie durų.'),
  (@b41, 13, 30, 'Iš tiesų sakau jums, kad ši karta nepraeis, kol visa tai neįvyks.'),
  (@b41, 13, 31, 'Dangus ir žemė praeis, bet mano žodžiai nepraeis.'),
  (@b41, 13, 32, 'Bet anos dienos ir valandos niekas nežino, ne, nei angelai, kurie yra danguje, nei Sūnus, bet tik Tėvas.'),
  (@b41, 13, 33, 'Saugokitės, budėkite ir melskitės, nes nežinote, kada yra laikas.'),
  (@b41, 13, 34, 'Nes žmogaus Sūnus yra kaip žmogus, vykstantis į tolimą kelionę, kuris paliko savo namus ir davė valdžią savo tarnams ir kiekvienam savąjį darbą ir įsakė durininkui budėti.'),
  (@b41, 13, 35, 'Todėl budėkite, nes nežinote, kada namų valdovas ateina: vakare ar vidurnakty, ar gaidžiui giedant, ar ryte;'),
  (@b41, 13, 36, 'kad netikėtai atėjęs jis neužtiktų jūsų miegančių.'),
  (@b41, 13, 37, 'Ir ką jums sakau, sakau visiems – budėkite“.'),
  (@b41, 14, 1, 'Po dviejų dienų buvo Apėjimo ir Neraugintos duonos šventė; ir vyriausieji kunigai bei raštininkai ieškojo, kaip jie galėtų klasta jį suimti ir nužudyti.'),
  (@b41, 14, 2, 'Bet jie tarė: „Ne šventės dieną, kad nekiltų tautos triukšmas“.'),
  (@b41, 14, 3, 'Ir jam esant Betanijoje, Simono raupsuotojo namuose, sėdint prie maisto, atėjo moteris, turinti alebastrinę labai brangaus nardo tepalo dėžutę; ir ji sudaužė dėžutę ir išliejo jį ant jo galvos.'),
  (@b41, 14, 4, 'Ir buvo kai kurie besipiktinantys savyje, ir sakė: „Kodėl yra šitas tepalo eikvojimas?'),
  (@b41, 14, 5, 'Nes jį buvo galima parduoti už daugiau nei tris šimtus denarų ir išdalyti vargšams“. Ir jie murmėjo prieš ją.'),
  (@b41, 14, 6, 'Bet Jėzus tarė: „Palikite ją ramybėje; kodėl ją varginate? Ji atliko ant manęs gerą darbą.'),
  (@b41, 14, 7, 'Nes vargšų visada turite su savimi, ir kada tik norite, galite jiems daryti gera; bet mane ne visada turite.'),
  (@b41, 14, 8, 'Ji padarė, ką galėjo – ji yra atėjusi iš anksto patepti mano kūno laidojimui.'),
  (@b41, 14, 9, 'Iš tiesų sakau jums: kur tik po visą pasaulį bus skelbiama ši evangelija, jos atminimui bus kalbama ir apie tai, ką ji padarė“.'),
  (@b41, 14, 10, 'Ir Judas Iskariotas, vienas iš dvylikos, nuėjo pas vyriausiuosius kunigus jiems jį išduoti.'),
  (@b41, 14, 11, 'Ir tai išgirdę jie apsidžiaugė ir pažadėjo duoti jam pinigų. Ir jis ieškojo, kaip galėtų jį tinkamai išduoti.'),
  (@b41, 14, 12, 'Ir pirmąją Neraugintos duonos dieną, kada jie pjovė Apėjimą, jo mokiniai jam tarė: „Kur nori, kad eitume ir paruoštume, kad valgytum Apėjimą?“'),
  (@b41, 14, 13, 'Ir jis išsiunčia du iš savo mokinių ir sako jiems: „Eikite į miestą, ir ten jus sutiks žmogus, nešinas vandens ąsočiu; sekite paskui jį.'),
  (@b41, 14, 14, 'Ir kur jis įeis, sakykite namų šeimininkui: ‘Mokytojas sako: kur yra svečių kambarys, kur su savo mokiniais valgysiu Apėjimą?’'),
  (@b41, 14, 15, 'Ir jis parodys jums didelį aukštutinį kambarį, apstatytą ir paruoštą; ten paruoškite mums“.'),
  (@b41, 14, 16, 'Ir jo mokiniai išėjo ir atėjo į miestą bei rado taip, kaip jis buvo jiems sakęs; ir jie paruošė Apėjimą.'),
  (@b41, 14, 17, 'Ir vakare jis ateina su dvylika.'),
  (@b41, 14, 18, 'Ir kai jie susėdo ir valgė, Jėzus tarė: „Iš tiesų sakau jums: vienas iš jūsų, su manimi valgančių, mane išduos“.'),
  (@b41, 14, 19, 'Ir jie pradėjo liūdėti ir vienas po kito jam sakyti: „Ar tai aš?“ Ir kitas tarė: „Ar tai aš?“'),
  (@b41, 14, 20, 'Ir jis atsakydamas tarė jiems: „Tai – vienas iš dvylikos, kuris mirko su manimi lėkštėje.'),
  (@b41, 14, 21, 'Žmogaus Sūnus iš tiesų eina, kaip apie jį parašyta, bet vargas tam žmogui, per kurį žmogaus Sūnus išduodamas! Gerai būtų buvę tam žmogui, jei jis niekada nebūtų gimęs“.'),
  (@b41, 14, 22, 'Ir kai jie valgė, Jėzus paėmė duoną, palaimino, laužė ją, davė jiems ir tarė: „Imkite, valgykite – tai yra mano kūnas“.'),
  (@b41, 14, 23, 'Ir jis paėmė taurę ir padėkojęs padavė ją jiems; ir jie visi iš jos gėrė.'),
  (@b41, 14, 24, 'Ir jis tarė jiems: „Tai yra mano kraujas naujojo testamento, kuris yra išliejamas už daugelį.'),
  (@b41, 14, 25, 'Iš tiesų sakau jums: nebegersiu vynmedžio vaisiaus iki tos dienos, kai gersiu jį naują Dievo karalystėje“.'),
  (@b41, 14, 26, 'Ir sugiedoję himną jie išėjo į Alyvų kalną.'),
  (@b41, 14, 27, 'Ir Jėzus jiems sako: „Jūs visi šią naktį pasipiktinsite dėl manęs, nes yra parašyta: ‘Smogsiu piemeniui, ir avys išsisklaidys’.'),
  (@b41, 14, 28, 'Bet prisikėlęs pirma jūsų eisiu į Galilėją“.'),
  (@b41, 14, 29, 'Bet Petras jam tarė: „Nors ir visi pasipiktins, tačiau ne aš“.'),
  (@b41, 14, 30, 'O Jėzus jam sako: „Iš tiesų sakau tau, kad šią dieną, šią naktį, prieš gaidžiui pragydus dukart, tu manęs išsiginsi triskart“.'),
  (@b41, 14, 31, 'Bet jis dar karščiau kalbėjo: „Jei man reikėtų mirti su tavimi, aš jokiu būdų tavęs neišsižadėsiu“. Taip pat ir jie visi kalbėjo.'),
  (@b41, 14, 32, 'Ir jie atėjo į vietą, vadinamą Getsemane; ir jis sako savo mokiniams: „Sėskite čia, kol melsiuosi“.'),
  (@b41, 14, 33, 'Ir pasiėmęs Petrą, Jokūbą ir Joną jis pradėjo labai stebėtis bei sielvartauti;'),
  (@b41, 14, 34, 'ir sako jiems: „Mano siela labai nuliūdusi, iki mirties; laukite čia ir budėkite“.'),
  (@b41, 14, 35, 'Ir jis paėjo truputį toliau, krito ant žemės ir meldėsi, kad, jei būtų įmanoma, ta valanda nueitų nuo jo.'),
  (@b41, 14, 36, 'Ir jis tarė: „Aba, Tėve, viskas tau įmanoma; paimk nuo manęs šią taurę; tačiau ne tai, ko aš noriu, bet tai, ko tu nori“.'),
  (@b41, 14, 37, 'Ir jis ateina ir randa juos miegančius, ir sako Petrui: „Simonai, tu miegi? Ar negalėjai pabudėti vieną valandą?'),
  (@b41, 14, 38, 'Budėkite ir melskitės, kad neįžengtumėte į pagundą. Dvasia iš tiesų pasiruošusi, bet kūnas silpnas“.'),
  (@b41, 14, 39, 'Ir vėl jis nuėjo ir meldėsi bei kalbėjo tuos pačius žodžius.'),
  (@b41, 14, 40, 'Ir kai jis sugrįžo, jis vėl juos rado miegančius (nes jų akys buvo apsunkusios), ir jie nežinojo, ką jam atsakyti.'),
  (@b41, 14, 41, 'Ir jis ateina trečią kartą ir sako jiems: „Dabar miegokite ir ilsėkitės; gana, valanda atėjo; štai žmogaus Sūnus yra išduotas į nusidėjėlių rankas.'),
  (@b41, 14, 42, 'Kelkitės, eime; štai tas, kuris mane išduoda, jau čia pat“.'),
  (@b41, 14, 43, 'Ir tuojau, jam dar bekalbant, ateina Judas, vienas iš dvylikos, o su juo didžiulė minia su kalavijais ir vėzdais – nuo vyriausiųjų kunigų, raštininkų ir vyresniųjų.'),
  (@b41, 14, 44, 'Ir tas, kuris jį išdavė, davė jiems ženklą, sakydamas: „Kurį pabučiuosiu, tai yra tas; suimkite jį ir saugiai nusiveskite“.'),
  (@b41, 14, 45, 'Ir vos tik atėjęs jis tuojau prieina prie jo ir sako: „Mokytojau, mokytojau!“ ir pabučiavo jį.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b41, 14, 46, 'Ir jie uždėjo ant jo savo rankas ir suėmė jį.'),
  (@b41, 14, 47, 'Ir vienas iš šalia stovinčiųjų išsitraukė kalaviją ir kirto aukščiausiojo kunigo tarnui, ir nupjovė jo ausį.'),
  (@b41, 14, 48, 'Ir Jėzus atsakydamas tarė jiems: „Ar išeinate kaip prieš vagį, su kalavijais ir vėzdais manęs suimti?'),
  (@b41, 14, 49, 'Kasdien buvau su jumis šventykloje mokydamas, o jūs manęs nesuėmėte; bet turi išsipildyti Raštai“.'),
  (@b41, 14, 50, 'Ir jie visi paliko jį ir pabėgo.'),
  (@b41, 14, 51, 'Ir jam iš paskos sekė vienas jaunuolis, apsigaubęs nuogą kūną lininiu audeklu; ir jauni vyrai jį sučiupo;'),
  (@b41, 14, 52, 'bet jis paliko lininį audeklą ir pabėgo nuo jų nuogas.'),
  (@b41, 14, 53, 'Ir jie nuvedė Jėzų pas aukščiausiąjį kunigą; ir su juo buvo susirinkę visi vyriausieji kunigai, vyresnieji ir raštininkai.'),
  (@b41, 14, 54, 'Ir Petras sekė paskui jį iš tolo į aukščiausiojo kunigo rūmus; ir jis atsisėdo su tarnais ir šildėsi prie ugnies.'),
  (@b41, 14, 55, 'Ir vyriausieji kunigai bei visa taryba ieškojo prieš Jėzų liudijimo, kad jį nužudytų; bet nerado nei vieno.'),
  (@b41, 14, 56, 'Nes daugelis melagingai liudijo prieš jį, bet jų liudijimai nesutapo.'),
  (@b41, 14, 57, 'Ir kėlėsi vieni ir melagingai liudijo prieš jį, sakydami:'),
  (@b41, 14, 58, '„Mes girdėjome jį sakant: ‘Aš sugriausiu šią šventyklą, padarytą rankomis, ir per tris dienas pastatysiu kitą, padarytą ne rankomis’“.'),
  (@b41, 14, 59, 'Bet nei šitaip jų liudijimai nesutapo.'),
  (@b41, 14, 60, 'Ir aukščiausiasis kunigas atsistojo viduryje ir paklausė Jėzaus, sakydamas: „Ar nieko neatsakai? Kas tai, ką šitie liudija prieš tave?“'),
  (@b41, 14, 61, 'Bet jis tylėjo ir nieko neatsakė. Vėl aukščiausiasis kunigas jo klausė ir tarė jam: „Ar tu esi Kristus, Palaimintojo Sūnus?“'),
  (@b41, 14, 62, 'Ir Jėzus tarė: „Aš esu; ir pamatysite žmogaus Sūnų, sėdintį galios dešinėje ir ateinantį dangaus debesyse“.'),
  (@b41, 14, 63, 'Tada aukščiausiasis kunigas persiplėšė drabužius ir sako: „Kam mums dar bereikia kitų liudijimų?'),
  (@b41, 14, 64, 'Jūs girdėjote piktžodžiavimą; ką galvojate?“ Ir jie visi pasmerkė jį esantį kaltu myriop.'),
  (@b41, 14, 65, 'Ir kai kurie pradėjo į jį spjaudyti, dengti jam veidą, mušti jį ir jam sakyti: „Pranašauk!“, ir tarnai daužė jį savo rankų delnais.'),
  (@b41, 14, 66, 'Ir Petrui esant žemai rūmuose, ateina viena iš aukščiausiojo kunigo tarnaičių;'),
  (@b41, 14, 67, 'ir kai ji pamatė besišildantį Petrą, ji pažiūrėjo į jį ir tarė: „Tu irgi buvai su Jėzumi iš Nazareto“.'),
  (@b41, 14, 68, 'Bet jis išsigynė, sakydamas: „Nežinau nei nesuprantu, ką sakai“. Ir jis išėjo laukan į prieangį; ir pragydo gaidys.'),
  (@b41, 14, 69, 'Ir tarnaitė vėl jį pamatė ir pradėjo sakyti šalia stovintiems: „Šitas yra vienas iš jų“.'),
  (@b41, 14, 70, 'Ir jis vėl tai paneigė. O truputį vėliau šalia stovintys vėl tarė Petrui: „Tikrai tu vienas iš jų; nes esi galilėjietis ir tavo kalba tokia pat“.'),
  (@b41, 14, 71, 'Bet jis pradėjo keiktis ir prisiekinėti, sakydamas: „Nežinau šito žmogaus, apie kurį kalbate“.'),
  (@b41, 14, 72, 'Ir antrą kartą pragydo gaidys. Ir Petras prisiminė žodį, kurį Jėzus jam sakė: „Prieš gaidžiui pragydus dukart, tu manęs išsiginsi triskart“. Ir kai jis apie tai pagalvojo, jis pravirko.'),
  (@b41, 15, 1, 'Ir tuojau ryte vyriausieji kunigai surengė pasitarimą su vyresniaisiais, raštininkais bei visa taryba ir, surišę Jėzų, nuvedė jį ir atidavė Pilotui.'),
  (@b41, 15, 2, 'Ir Pilotas jo paklausė: „Ar tu esi žydų Karalius?“ Ir jis atsakydamas jam tarė: „Tu tai sakai“.'),
  (@b41, 15, 3, 'Ir vyriausieji kunigai daug kuo jį kaltino, bet jis nieko neatsakė.'),
  (@b41, 15, 4, 'O Pilotas vėl jo klausė, sakydamas: „Ar nieko neatsakai? Štai kiek daug visko jie liudija prieš tave“.'),
  (@b41, 15, 5, 'Bet Jėzus vis nieko neatsakė; taip, kad Pilotas stebėjosi.'),
  (@b41, 15, 6, 'Na, o per tą šventę jis paleisdavo jiems vieną kalinį, kurio jie norėdavo.'),
  (@b41, 15, 7, 'Ir ten buvo vienas, vardu Barabas, kuris gulėjo surištas su tais, kurie kartu su juo vykdė sukilimą, kuris per sukilimą įvykdė žmogžudystę.'),
  (@b41, 15, 8, 'Ir minia garsiai šaukdama pradėjo prašyti jo, kad padarytų, kaip jis visada jiems darydavo.'),
  (@b41, 15, 9, 'Bet Pilotas jiems atsakė, sakydamas: „Ar norite, kad paleisčiau jums žydų Karalių?“'),
  (@b41, 15, 10, 'Nes jis žinojo, kad vyriausieji kunigai atidavė jį iš pavydo.'),
  (@b41, 15, 11, 'Bet vyriausieji kunigai sukurstė tautą, kad jis verčiau paleistų jiems Barabą.'),
  (@b41, 15, 12, 'Ir Pilotas atsakė ir vėl jiems tarė: „Ką tada norite, kad padaryčiau tam, kurį vadinate žydų Karaliumi?“'),
  (@b41, 15, 13, 'Ir jie vėl šaukė: „Nukryžiuok jį!“'),
  (@b41, 15, 14, 'Tuomet Pilotas jiems tarė: „Kodėl, ką pikta jis padarė?“ Bet jie dar labiau šaukė: „Nukryžiuok jį!“'),
  (@b41, 15, 15, 'Ir taip Pilotas, norėdamas patenkinti tautą, paleido jiems Barabą ir nuplakdinęs Jėzų atidavė jį nukryžiuoti.'),
  (@b41, 15, 16, 'Ir kareiviai nusivedė jį į rūmus, vadinamus Pretorijumi; ir jie susišaukia visą pulką.'),
  (@b41, 15, 17, 'Ir jie aprengė jį purpuru bei nupynė erškėčių vainiką ir uždėjo jį aplink jo galvą,'),
  (@b41, 15, 18, 'ir pradėjo jį sveikinti: „Sveikas, žydų Karaliau!“'),
  (@b41, 15, 19, 'Ir jie mušė su nendre jam per galvą ir spjaudė į jį, ir priklaupdami jį garbino.'),
  (@b41, 15, 20, 'Ir iš jo pasityčioję jie nuvilko nuo jo purpurą, apvilko jį jo paties drabužiais ir išvedė jį nukryžiuoti.'),
  (@b41, 15, 21, 'Ir jie privertė vieną grįžtantį iš laukų, praeinantį pro šalį, Simoną kirėnietį, Aleksandro ir Rufo tėvą, nešti jo kryžių.'),
  (@b41, 15, 22, 'Ir jie nuveda jį į Golgotos vietą, kas išvertus reiškia Kaukolės vieta.'),
  (@b41, 15, 23, 'Ir jie davė jam gerti vyno, sumaišyto su mira, bet jis jo nepriėmė.'),
  (@b41, 15, 24, 'Ir nukryžiavę jį, jie pasidalijo jo drabužius, mesdami dėl jų burtus, kas ką imsiąs.'),
  (@b41, 15, 25, 'Ir buvo trečia valanda, ir jie nukryžiavo jį.'),
  (@b41, 15, 26, 'Ir viršuje buvo užrašytas jo kaltinimo užrašas: „ŽYDŲ KARALIUS“.'),
  (@b41, 15, 27, 'Ir su juo jie nukryžiavo du vagis: vieną jo dešinėje, o kitą jo kairėje.'),
  (@b41, 15, 28, 'Ir išsipildė Raštas, kuris sako: „Ir jis buvo priskaičiuotas prie nusižengėlių“.'),
  (@b41, 15, 29, 'O praeinantys pro šalį plūdo jį, kraipydami savo galvas ir sakydami: „Tu, kuris sunaikini šventyklą ir pastatai ją per tris dienas,'),
  (@b41, 15, 30, 'išgelbėk save ir nuženk nuo kryžiaus“.'),
  (@b41, 15, 31, 'Panašiai ir vyriausieji kunigai tarpusavyje su raštininkais tyčiodamiesi sakė: „Jis gelbėjo kitus; savęs jis negali išgelbėti.'),
  (@b41, 15, 32, 'Tegul Kristus, Izraelio Karalius, nužengia dabar nuo kryžiaus, kad pamatytume ir patikėtume“. Ir tie, kurie buvo su juo nukryžiuoti, plūdo jį.'),
  (@b41, 15, 33, 'Ir kai atėjo šešta valanda, tamsa apgaubė visą šalį iki devintos valandos.'),
  (@b41, 15, 34, 'O devintą valandą Jėzus garsiu balsu šaukė, sakydamas: „Eloi, Eloi, lama sabachtani?“, kas išvertus yra: „Mano Dieve, mano Dieve, kodėl mane apleidai?“'),
  (@b41, 15, 35, 'Ir kai kurie iš šalia stovinčiųjų tai išgirdę tarė: „Žiūrėk, jis šaukiasi Elijo“.'),
  (@b41, 15, 36, 'Ir vienas nubėgęs pripildė kempinę pilną acto, užmovė ją ant nendrės ir davė jam gerti, sakydamas: „Liaukitės; pažiūrėkime, ar Elijas ateis jo nuimti“.'),
  (@b41, 15, 37, 'Ir Jėzus sušuko garsiu balsu ir atidavė dvasią.'),
  (@b41, 15, 38, 'Ir šventyklos uždanga perplyšo į dvi dalis nuo viršaus iki apačios.'),
  (@b41, 15, 39, 'Ir kai stovėjęs priešais jį šimtininkas pamatė, kad jis taip sušuko ir atidavė dvasią, jis tarė: „Iš tiesų šis žmogus buvo Dievo Sūnus“.'),
  (@b41, 15, 40, 'Ten buvo ir moterys, bežiūrinčios iš toli; tarp kurių buvo Marija Magdalietė ir Marija – Jokūbo mažesniojo ir Jozės motina, ir Salomė'),
  (@b41, 15, 41, '(kurios taip pat, kai jis buvo Galilėjoje, sekė paskui jį ir jam tarnavo); ir daug kitų moterų, kurios atėjo su juo aukštyn į Jeruzalę.'),
  (@b41, 15, 42, 'Na, o atėjus vakarui, kadangi tai buvo pasiruošimas, tai yra diena prieš sabatą,'),
  (@b41, 15, 43, 'atėjo Juozapas iš Arimatėjos, garbingas patarėjas, kuris taip pat laukė Dievo karalystės, ir drąsiai nuėjo pas Pilotą, ir maldavo Jėzaus kūno.'),
  (@b41, 15, 44, 'Ir Pilotas stebėjosi, kad jis jau buvo miręs; ir pasišaukęs šimtininką, jis paklausė jo, ar praėję kiek laiko, kai jis yra miręs.'),
  (@b41, 15, 45, 'Ir kai jis sužinojo tai iš šimtininko, jis atidavė Juozapui kūną.'),
  (@b41, 15, 46, 'Ir jis nupirko plonos drobės ir, nuėmęs jį žemėn, įvyniojo į drobę, paguldė jį į kapą, kuris buvo ištašytas iš uolos, ir užritino ant kapo durų akmenį.'),
  (@b41, 15, 47, 'Ir Marija Magdalietė bei Jozės motina Marija žiūrėjo, kur jis buvo paguldytas.'),
  (@b41, 16, 1, 'Ir praėjus sabatui, Marija Magdalietė, Jokūbo motina Marija ir Salomė nupirko gardžių kvapų, kad ateitų ir pateptų jį.'),
  (@b41, 16, 2, 'Ir labai anksti ryte, pirmą savaitės dieną, saulei tekant jos atėjo prie kapo.'),
  (@b41, 16, 3, 'Ir jos kalbėjo tarpusavyje: „Kas mums nuritins akmenį nuo kapo durų?“'),
  (@b41, 16, 4, 'Ir kai jos pažvelgė, jos pamatė, kad akmuo buvo nuritintas; nes jis buvo labai didelis.'),
  (@b41, 16, 5, 'Ir įeidamos į kapą jos pamatė jauną vyrą, sėdintį dešinėje pusėje, apsirengusį ilgu baltu drabužiu; ir jos išsigando.'),
  (@b41, 16, 6, 'Ir jis sako joms: „Neišsigąskite! Jūs ieškote Jėzaus iš Nazareto, kuris buvo nukryžiuotas; jis yra prisikėlęs; jo čia nėra; štai vieta, kur jie paguldė jį.'),
  (@b41, 16, 7, 'Bet eikite, pasakykite jo mokiniams ir Petrui, kad jis pirma jūsų eina į Galilėją: ten pamatysite jį, kaip jis sakė jums“.'),
  (@b41, 16, 8, 'Ir jos greitai išėjo ir bėgo nuo kapo; nes jos drebėjo ir buvo nustebusios; ir niekam nieko nesakė; nes jos bijojo.'),
  (@b41, 16, 9, 'Na, o Jėzus, pirmąją savaitės dieną anksti prisikėlęs, pirma pasirodė Marijai Magdalietei, iš kurios jis buvo išvaręs septynis velnius.'),
  (@b41, 16, 10, 'Ir ji nuėjo ir papasakojo tiems, kurie yra buvę su juo, kai jie gedėjo ir verkė.'),
  (@b41, 16, 11, 'Ir išgirdę, kad jis yra gyvas ir jos pačios buvo regėtas, jie netikėjo.'),
  (@b41, 16, 12, 'Po to jis kitu pavidalu pasirodė dviems iš jų, jiems bevaikštant ir einant į kaimą.'),
  (@b41, 16, 13, 'Ir jie nuėjo bei papasakojo tai likusiems; ir jais jie netikėjo.'),
  (@b41, 16, 14, 'Po to jis pasirodė vienuolikai, kai jie sėdėjo prie maisto, ir prikaišiojo jiems dėl jų netikėjimo ir širdies kietumo, nes jie netikėjo tais, kurie buvo matę jį po to, kai jis prisikėlė.'),
  (@b41, 16, 15, 'Ir jis jiems tarė: „Eikite į visą pasaulį ir skelbkite evangeliją kiekvienam sutvėrimui.'),
  (@b41, 16, 16, 'Tas, kuris tiki ir yra pakrikštijamas, bus išgelbėtas; bet tas, kuris netiki, bus pasmerktas.'),
  (@b41, 16, 17, 'Ir šie ženklai lydės tuos, kurie tiki: mano vardu jie išvarinės velnius; jie kalbės naujomis kalbomis;'),
  (@b41, 16, 18, 'jie ims gyvates; ir jeigu jie išgers ką nors mirtino, tai jiems nekenks; jie dės rankas ant ligonių, ir šie pasveiks“.'),
  (@b41, 16, 19, 'Taigi jiems pakalbėjęs Viešpats buvo paimtas į dangų ir atsisėdo Dievo dešinėje.'),
  (@b41, 16, 20, 'Ir jie išėjo ir skelbė visur, Viešpačiui besidarbuojant su jais ir patvirtinant žodį lydinčiais ženklais. Amen.'),
  (@b42, 1, 1, 'Kadangi daugelis apsiėmė nuosekliai išdėstyti paskelbimą to, kas be jokių abejonių įtikėta tarp mūsų,'),
  (@b42, 1, 2, 'kaip perdavė tai mums tie, kurie nuo pradžios patys tai regėjo ir buvo žodžio tarnautojai;'),
  (@b42, 1, 3, 'atrodė gerai ir man, turinčiam tobulą supratimą visko nuo pat pradžios, nuosekliai surašyti tau, garbingiausiasis Teofiliau,'),
  (@b42, 1, 4, 'idant žinotumei tikrumą to, ko buvai išmokytas.'),
  (@b42, 1, 5, 'Judėjos karaliaus Erodo dienomis buvo vienas kunigas, vardu Zacharijas, iš Abijos skyriaus; o jo žmona buvo iš Aarono dukterų, ir jos vardas buvo Elžbieta.'),
  (@b42, 1, 6, 'Ir jie abu buvo teisūs prieš Dievą, nepriekaištingai vaikščiojantys pagal visus Viešpaties įsakymus ir nuostatus.'),
  (@b42, 1, 7, 'Bet jie neturėjo vaikų, nes Elžbieta buvo nevaisinga, ir jie abu jau buvo gerai palaužti metų.'),
  (@b42, 1, 8, 'Ir įvyko, kad, jam bevykdant kunigo tarnystę Dievo akivaizdoje pagal jo skyriaus tvarką,'),
  (@b42, 1, 9, 'pagal kunigo tarnystės paprotį, burtu jam teko įėjus į Viešpaties šventyklą deginti smilkalus.'),
  (@b42, 1, 10, 'O visa tautos minia smilkymo metu meldėsi lauke.'),
  (@b42, 1, 11, 'Ir jam pasirodė Viešpaties angelas, stovintis smilkalų aukuro dešinėje pusėje.'),
  (@b42, 1, 12, 'Ir jį pamatęs Zacharijas sunerimo, ir jį apėmė baimė.'),
  (@b42, 1, 13, 'Bet angelas jam tarė: „Nebijok, Zacharijau, nes tavo malda išgirsta; ir tavo žmona Elžbieta pagimdys tau sūnų, ir tu jį praminsi vardu Jonas.'),
  (@b42, 1, 14, 'Ir tau bus džiaugsmas bei linksmybė; ir daugelis džiaugsis jo gimimu.'),
  (@b42, 1, 15, 'Nes jis bus didis Viešpaties akyse ir negers nei vyno, nei stipraus gėrimo; ir nuo savo motinos įsčių bus pripildytas Šventosios Dvasios.'),
  (@b42, 1, 16, 'Ir daugelį Izraelio vaikų jis nukreips į Viešpatį, jų Dievą.'),
  (@b42, 1, 17, 'Ir jis eis pirma jo, Elijo dvasioje ir jėgoje nukreipti tėvų širdis į vaikus ir neklusniuosius į teisiųjų išmintį; parengti tautą, paruoštą Viešpačiui“.'),
  (@b42, 1, 18, 'Ir Zacharijas tarė angelui: „Pagal ką tai pažinsiu? Nes esu senas žmogus, ir mano žmona gerai metų palaužta“.'),
  (@b42, 1, 19, 'O angelas atsakydamas jam tarė: „Aš esu Gabrielius, kuris stoviu Dievo akivaizdoje; ir esu atsiųstas kalbėti tau ir tau pranešti šią linksmą žinią.'),
  (@b42, 1, 20, 'Ir štai tu būsi nebylys ir negalėsi kalbėti iki tos dienos, kai tai bus įvykdyta, nes tu netiki mano žodžiais, kurie išsipildys savo laiku“.'),
  (@b42, 1, 21, 'Ir tauta laukė Zacharijo bei stebėjosi, kad jis taip ilgai užtruko šventykloje.'),
  (@b42, 1, 22, 'Ir kai jis išėjo, jis negalėjo jiems kalbėti; ir jie suprato, kad jis šventykloje matė regėjimą; nes jis mojavo jiems ir pasiliko nebylus.'),
  (@b42, 1, 23, 'Ir kai tik buvo užbaigtos jo tarnavimo dienos, įvyko, kad jis išėjo į savo namus.'),
  (@b42, 1, 24, 'Ir po šitų dienų jo žmona Elžbieta pastojo ir penkis mėnesius slėpėsi, sakydama:'),
  (@b42, 1, 25, '„Taip Viešpats su manimi pasielgė tomis dienomis, kai jis atsižvelgė į mane, kad nuimtų mano gėdą tarp žmonių“.'),
  (@b42, 1, 26, 'Ir šeštąjį mėnesį angelas Gabrielius buvo pasiųstas nuo Dievo į Galilėjos miestą, vadinamą Nazaretu,'),
  (@b42, 1, 27, 'pas mergelę, sužadėtą su vyru iš Dovydo namų, kurio vardas buvo Juozapas; o mergelės vardas buvo Marija.'),
  (@b42, 1, 28, 'Ir angelas atėjo pas ją ir tarė: „Sveika, labai pamalonintoji, Viešpats yra su tavimi, palaiminta esi tarp moterų“.'),
  (@b42, 1, 29, 'Ir jį pamačiusi ji sunerimo dėl jo pasakymo ir galvojo, kas tai turėtų būti per pasveikinimas.'),
  (@b42, 1, 30, 'Ir angelas jai tarė: „Nebijok, Marija, nes radai palankumą pas Dievą.'),
  (@b42, 1, 31, 'Ir štai tu pastosi savo įsčiose ir pagimdysi sūnų, ir praminsi jį vardu JĖZUS.'),
  (@b42, 1, 32, 'Jis bus didis ir bus vadinamas Aukščiausiojo Sūnumi; ir Viešpats Dievas jam duos jo tėvo Dovydo sostą;'),
  (@b42, 1, 33, 'ir jis karaliaus Jokūbo namams per amžius; ir jo karalystei nebus galo“.'),
  (@b42, 1, 34, 'Tuomet Marija tarė angelui: „Kaip tai bus? Kadangi nepažįstu vyro.“'),
  (@b42, 1, 35, 'O angelas atsakydamas tarė jai: „Ant tavęs užeis Šventoji Dvasia, ir Aukščiausiojo jėga apgaubs tave šešėliu; todėl ir tai, kas šventa, kas gims iš tavęs, vadinsis Dievo Sūnumi.'),
  (@b42, 1, 36, 'Ir štai tavo giminaitė Elžbieta, ji taip pat pradėjo sūnų savo senatvėje; ir šis yra šeštasis mėnuo jai, kuri buvo vadinama nevaisinga.'),
  (@b42, 1, 37, 'Nes Dievui nieko nebus neįmanomo“.'),
  (@b42, 1, 38, 'Ir Marija tarė: „Štai Viešpaties tarnaitė; tebūna tai man pagal tavo žodį“. Ir angelas nuo jos pasitraukė.'),
  (@b42, 1, 39, 'Ir tomis dienomis Marija pakilo ir skubiai nuvyko į kalvų kraštą, į Judos miestą;'),
  (@b42, 1, 40, 'ir įėjo į Zacharijo namus bei pasveikino Elžbietą.'),
  (@b42, 1, 41, 'Ir įvyko, kad Elžbietai išgirdus Marijos pasveikinimą, jos įsčiose pašoko kūdikis; ir Elžbieta buvo pripildyta Šventosios Dvasios;'),
  (@b42, 1, 42, 'ir ji kalbėjo garsiu balsu ir tarė: „Palaiminta tu tarp moterų ir palaimintas tavo įsčių vaisius.'),
  (@b42, 1, 43, 'Ir iš kur man tai, kad mano Viešpaties motina turėjo ateiti pas mane?'),
  (@b42, 1, 44, 'Nes štai vos tik tavo pasveikinimo balsas suskambėjo mano ausyse, mano įsčiose iš džiaugsmo pašoko kūdikis.'),
  (@b42, 1, 45, 'Ir palaiminta ta, kuri patikėjo, nes bus vykdoma tai, kas buvo jai nuo Viešpaties pasakyta“.'),
  (@b42, 1, 46, 'Ir Marija tarė: „Mano siela aukština Viešpatį,'),
  (@b42, 1, 47, 'ir mano dvasia apsidžiaugė Dievu, mano Gelbėtoju.'),
  (@b42, 1, 48, 'Nes jis atsižvelgė į savo tarnaitės žemą padėtį; nes štai nuo šiol visos kartos vadins mane palaiminta.'),
  (@b42, 1, 49, 'Nes tas, kuris yra galingas, man padarė didžių dalykų; ir šventas yra jo vardas.'),
  (@b42, 1, 50, 'Ir jo gailestingumas iš kartos į kartą yra ant tų, kurie jo bijo.'),
  (@b42, 1, 51, 'Jis savo ranka parodė stiprybę; jis išsklaidė išdidžiuosius jų širdžių sumanyme.'),
  (@b42, 1, 52, 'Jis nustūmė galinguosius nuo jų sostų ir išaukštino tuos, žemos padėties.'),
  (@b42, 1, 53, 'Jis pripildė alkaną gėrybėmis; o turtuolį jis paleido tuščiomis.'),
  (@b42, 1, 54, 'Jis padėjo savo tarnui Izraeliui, prisimindamas savo gailestingumą;'),
  (@b42, 1, 55, 'kaip jis kalbėjo mūsų tėvams, Abraomui ir jo sėklai per amžius“.'),
  (@b42, 1, 56, 'Ir Marija pasiliko pas ją apie tris mėnesius ir grįžo į savo namus.'),
  (@b42, 1, 57, 'Na, o Elžbietai atėjo pilnas laikas, kai ji turėtų gimdyti; ir ji pagimdė sūnų.'),
  (@b42, 1, 58, 'Ir jos kaimynai bei jos giminės išgirdo, kaip Viešpats ant jos parodė didį gailestingumą; ir jie džiaugėsi su ja.'),
  (@b42, 1, 59, 'Ir įvyko, kad aštuntąją dieną jie atėjo apipjaustyti vaiko; ir jie pavadino jį Zacharijumi, jo tėvo vardu.'),
  (@b42, 1, 60, 'O jo motina atsakydama tarė: „Ne taip; jis bus pavadintas Jonu“.'),
  (@b42, 1, 61, 'Ir jie tarė jai: „Nėra nei vieno iš tavo giminaičių, kurį vadintų šiuo vardu“.'),
  (@b42, 1, 62, 'Ir jie ženklais rodė jo tėvui, kaip jis norėtų jį pavadinti.'),
  (@b42, 1, 63, 'Ir jis paprašė rašymo lentos, ir užrašė, sakydamas: „Jo vardas yra Jonas“. Ir jie visi stebėjosi.'),
  (@b42, 1, 64, 'Ir tuojau atsivėrė jo burna ir atsirišo jo liežuvis, ir jis kalbėjo bei gyrė Dievą.'),
  (@b42, 1, 65, 'Ir visus, gyvenančius aplink juos, apėmė baimė; ir visi šitie pasakymai buvo plačiai pagarsinti po visą kalvotąjį Judėjos kraštą.'),
  (@b42, 1, 66, 'Ir visi, kurie juos girdėjo, dėjosi juos į savo širdis, sakydami: „Kas gi tai bus per vaikas?“ Ir Viešpaties ranka buvo su juo.'),
  (@b42, 1, 67, 'Ir jo tėvas Zacharijas buvo pripildytas Šventosios Dvasios ir pranašavo, sakydamas:'),
  (@b42, 1, 68, '„Tebūna palaimintas Izraelio Viešpats Dievas; nes jis aplankė ir atpirko savo tautą,'),
  (@b42, 1, 69, 'ir iškėlė mums išgelbėjimo ragą savo tarno Dovydo namuose;'),
  (@b42, 1, 70, 'kaip jis kalbėjo savo šventųjų pranašų burna, kurie buvo nuo pasaulio pradžios,'),
  (@b42, 1, 71, 'kad būtume išgelbėti nuo mūsų priešų ir iš rankos visų tų, kurie mūsų nekenčia;'),
  (@b42, 1, 72, 'kad įvykdytų gailestingumą, pažadėtą mūsų tėvams, ir prisimintų savo šventąją sandorą;'),
  (@b42, 1, 73, 'priesaiką, kurią jis prisiekė mūsų tėvui Abraomui,'),
  (@b42, 1, 74, 'idant jis skirtų mums, kad mes, būdami išvaduoti iš mūsų priešų rankos, galėtume jam be baimės tarnauti'),
  (@b42, 1, 75, 'šventume ir teisume jo akivaizdoje per visas mūsų gyvenimo dienas.'),
  (@b42, 1, 76, 'O tu, vaike, būsi vadinamas Aukščiausiojo pranašu, nes eisi pirma Viešpaties veido paruošti jo kelių;'),
  (@b42, 1, 77, 'suteikti jo tautai pažinimą išgelbėjimo per jų nuodėmių atleidimą,'),
  (@b42, 1, 78, 'per meilingą mūsų Dievo gailestingumą; kuriuo mus aplankė aušra iš aukštybių,'),
  (@b42, 1, 79, 'suteikti šviesą sėdintiems tamsoje ir mirties šešėlyje, vesti mūsų kojas į ramybės kelią“.'),
  (@b42, 1, 80, 'Ir vaikas augo bei stiprėjo dvasia ir buvo dykumose iki savo pasirodymo Izraeliui dienos.'),
  (@b42, 2, 1, 'Ir įvyko tomis dienomis, kad išėjo ciesoriaus Augusto įsakas, jog visas pasaulis būtų surašytas'),
  (@b42, 2, 2, '(ir šis surašymas pirmas buvo atliktas kai Kvirinas buvo Sirijos valdytojas).'),
  (@b42, 2, 3, 'Ir visi ėjo užsirašyti, kiekvienas į savo miestą.'),
  (@b42, 2, 4, 'Taip pat ir Juozapas ėjo iš Galilėjos, iš Nazareto miesto, į Judėją, į Dovydo miestą, vadinamą Betliejumi (nes jis buvo iš Dovydo namų ir giminės);'),
  (@b42, 2, 5, 'užsirašyti su Marija, savo sužadėtąja žmona, esančia nėščia.'),
  (@b42, 2, 6, 'Ir buvo taip, kad jiems ten beesant išsipildė dienos, kai ji turėtų gimdyti.'),
  (@b42, 2, 7, 'Ir ji pagimdė savo pirmagimį sūnų ir suvyniojo jį į vystyklus, ir paguldė jį ėdžiose; nes jiems nebuvo vietos užeigoje.'),
  (@b42, 2, 8, 'Ir tam pačiam krašte buvo apsistoję piemenys ant lauko, budėdami naktį prie savo kaimenės.'),
  (@b42, 2, 9, 'Ir štai ant jų užėjo Viešpaties angelas, ir Viešpaties šlovė apšvietė juos; ir jie labai išsigando.'),
  (@b42, 2, 10, 'Ir angelas jiems tarė: „Nebijokite, nes štai jums atnešu gerą naujieną didžio džiaugsmo, kuris bus visai tautai.'),
  (@b42, 2, 11, 'Nes jums šią dieną Dovydo mieste gimė Gelbėtojas, kuris yra Kristus Viešpats.'),
  (@b42, 2, 12, 'Ir šis jums bus ženklas: rasite kūdikį, suvyniotą į vystyklus, gulintį ėdžiose“.'),
  (@b42, 2, 13, 'Ir staiga su angelu buvo dangiškosios kariuomenės minia, girianti Dievą ir sakanti:'),
  (@b42, 2, 14, '„Šlovė Dievui aukštybėse, o žemėje ramybė, gera valia žmonėms“.'),
  (@b42, 2, 15, 'Ir įvyko, kai angelai pasitraukė nuo jų į dangų, piemenys sakė vienas kitam: „Eime dabar į Betliejų ir pamatykime tai, kas įvyko, ką Viešpats mums davė žinoti“.'),
  (@b42, 2, 16, 'Ir skubiai atėję jie rado Mariją, Juozapą ir kūdikį, gulintį ėdžiose.'),
  (@b42, 2, 17, 'Ir tai pamatę jie visur paskelbė jiems kalbėtą pasakymą apie šį vaiką.'),
  (@b42, 2, 18, 'Ir visi, kurie tai girdėjo, stebėjosi tuo, ką jiems papasakojo piemenys.'),
  (@b42, 2, 19, 'Bet Marija saugojo visus tuos dalykus ir mąstė apie juos savo širdyje.'),
  (@b42, 2, 20, 'Ir piemenys grįžo šlovindami bei girdami Dievą už viską, ką jie girdėjo ir matė, kaip jiems buvo pasakyta.'),
  (@b42, 2, 21, 'Ir užsibaigus aštuonioms dienoms dėl vaiko apipjaustymo, jis buvo pavadintas vardu JĖZUS, kuris buvo taip pavadintas angelo dar prieš jo pradėjimą įsčiose.'),
  (@b42, 2, 22, 'Ir kai užsibaigė jos apsivalymo pagal Mozės įstatymą dienos, jie atnešė jį į Jeruzalę, kad pristatytų jį Viešpačiui'),
  (@b42, 2, 23, '(kaip yra parašyta Viešpaties įstatyme: „Kiekvienas iš vyriškosios lyties, kuris atveria įsčias, bus vadinamas šventu Viešpačiui“);'),
  (@b42, 2, 24, 'ir kad atnašautų auką pagal tai, kas pasakyta Viešpaties įstatyme: „Porą balandžių arba du jaunus karvelius“.'),
  (@b42, 2, 25, 'Ir štai Jeruzalėje buvo žmogus vardu Simeonas; ir tas žmogus buvo teisus bei dievobaimingas, laukiantis Izraelio paguodos; ir Šventoji Dvasia buvo ant jo.'),
  (@b42, 2, 26, 'Ir jam buvo Šventosios Dvasios apreikšta, kad jis nematys mirties, kol nepamatys Viešpaties Kristaus.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b42, 2, 27, 'Ir jis pagal Dvasią atėjo į šventyklą; ir kai gimdytojai įnešė vaiką Jėzų, kad jam padarytų pagal įstatymo paprotį,'),
  (@b42, 2, 28, 'jis paėmė jį į savo rankas, palaimino Dievą ir tarė:'),
  (@b42, 2, 29, '„Dabar, Viešpatie, pagal savo žodį tu leidi savo tarnui išeiti ramybėje;'),
  (@b42, 2, 30, 'nes mano akys išvydo tavo išgelbėjimą,'),
  (@b42, 2, 31, 'kurį paruošei visų žmonių akivaizdoje;'),
  (@b42, 2, 32, 'šviesą pagonims apšviesti ir šlovę tavo tautos Izraelio“.'),
  (@b42, 2, 33, 'Ir Juozapas bei jo motina stebėjosi tuo, kas buvo kalbama apie jį.'),
  (@b42, 2, 34, 'Ir Simeonas juos palaimino ir tarė Marijai, jo motinai: „Štai, šis vaikas yra pastatytas daugelio kritimui ir vėl atsikėlimui Izraelyje; ir ženklui, kuriam bus prieštaraujama'),
  (@b42, 2, 35, '(taip, kalavijas perdurs ir tavo sielą); kad būtų atskleistos daugelio širdžių mintys“.'),
  (@b42, 2, 36, 'Ir buvo tokia Ona, pranašė, Fanuelio duktė iš Asero genties; ji buvo labai sena ir nuo savo mergystės išgyveno su vyru septynis metus;'),
  (@b42, 2, 37, 'ir apie aštuoniasdešimt keturis metus ji buvo našlė, kuri neišėjo iš šventyklos, bet tarnavo Dievui pasninkais ir maldomis naktį ir dieną.'),
  (@b42, 2, 38, 'Ir įėjusi tuo pačiu metu, ji taip pat dėkojo Viešpačiui ir kalbėjo apie jį visiems, kurie laukė atpirkimo Jeruzalėje.'),
  (@b42, 2, 39, 'Ir visa atlikę pagal Viešpaties įstatymą jie sugrįžo į Galilėją, į savąjį miestą Nazaretą.'),
  (@b42, 2, 40, 'Ir vaikas augo bei stiprėjo dvasioje, pripildytas išminties; ir Dievo malonė buvo ant jo.'),
  (@b42, 2, 41, 'Na, o jo tėvai kiekvienais metais per Apėjimo šventę eidavo į Jeruzalę.'),
  (@b42, 2, 42, 'Ir kai jis buvo dvylikos metų, pagal šventės paprotį jie nuėjo aukštyn į Jeruzalę.'),
  (@b42, 2, 43, 'Ir kai jie išpildė tas dienas, jiems grįžtant vaikas Jėzus pasiliko Jeruzalėje; o Juozapas ir jo motina apie tai nežinojo.'),
  (@b42, 2, 44, 'Bet jie, manydami jį esant būryje, nuėjo dienos kelią; ir jie ieškojo jo tarp savo giminaičių ir pažįstamų.'),
  (@b42, 2, 45, 'Ir jiems jo neradus, jie sukosi atgal į Jeruzalę, jo ieškodami.'),
  (@b42, 2, 46, 'Ir įvyko, kad po trijų dienų jie rado jį šventykloje, sėdintį mokytojų viduryje jų besiklausantį ir juos beklausinėjantį.'),
  (@b42, 2, 47, 'Ir visi, kurie jį girdėjo, stebėjosi jo supratimu ir atsakymais.'),
  (@b42, 2, 48, 'Ir kai jie pamatė jį, jie nustebo; ir jo motina jam tarė: „Sūnau, kodėl taip su mumis pasielgei? Štai tavo tėvas ir aš sielvartaudami ieškojome tavęs“.'),
  (@b42, 2, 49, 'O jis jiems tarė: „Kaipgi yra, kad manęs ieškojote? Ar nežinojote, kad man reikia būti savo Tėvo reikaluose?“'),
  (@b42, 2, 50, 'Ir jie nesuprato to pasakymo, kurį jis jiems kalbėjo.'),
  (@b42, 2, 51, 'Ir jis ėjo su jais žemyn ir atėjo į Nazaretą, ir buvo jiems klusnus; bet jo motina visus šituos pasakymus saugojo savo širdyje.'),
  (@b42, 2, 52, 'Ir Jėzus augo išmintimi bei ūgiu ir palankumu pas Dievą ir žmogų.'),
  (@b42, 3, 1, 'Na, o penkioliktais ciesoriaus Tiberijaus viešpatavimo metais, Pontijui Pilotui esant Judėjos valdytoju, o Erodui esant Galilėjos tetrarchu ir jo broliui Pilypui – Iturėjos bei Trachonitės srities tetrarchu, o Lesanijui – Abilenės tetrarchu,'),
  (@b42, 3, 2, 'Anui ir Kajafui esant aukščiausiais kunigais, Dievo žodis atėjo Zacharijo sūnui Jonui dykumoje.'),
  (@b42, 3, 3, 'Ir jis atėjo į visą kraštą, esantį aplink Jordaną, skelbdamas atgailos krikštą nuodėmėms atleisti;'),
  (@b42, 3, 4, 'kaip yra parašyta pranašo Izaijo žodžių knygoje, sakant: „Dykumoje šaukiančiojo balsas: ‘Paruoškite Viešpaties kelią, darykite tiesius jo takus!'),
  (@b42, 3, 5, 'Kiekvienas slėnis bus pripildytas, ir kiekvienas kalnas bei kalva bus pažeminti; kreivas bus ištiesintas, o nelygūs keliai išlyginti;'),
  (@b42, 3, 6, 'Ir visi kūnai išvys Dievo išgelbėjimą’“.'),
  (@b42, 3, 7, 'Tada jis tarė miniai, kuri išėjo, idant būtų jo pakrikštyta: „O gyvačių palikuonys, kas jus perspėjo bėgti nuo ateinančios rūstybės?'),
  (@b42, 3, 8, 'Todėl duokite vaisių, vertų atgailos, ir nepradėkite sakyti savyje: ‘Mes turime Abraomą savo tėvu’; nes aš jums sakau, kad Dievas gali iš šitų akmenų prikelti vaikų Abraomui.'),
  (@b42, 3, 9, 'Ir dabar ir kirvis pridėtas prie medžių šaknies; todėl kiekvienas medis, neduodantis gero vaisiaus, yra iškertamas ir įmetamas į ugnį“.'),
  (@b42, 3, 10, 'Ir tauta jo paklausė, sakydama: „Ką tuomet mums daryti?“'),
  (@b42, 3, 11, 'Jis atsako ir taria jiems: „Kas turi dvejus marškinius, tas teduoda tam, kuris nei vienų neturi; o kas turi maisto, tedaro taip pat“.'),
  (@b42, 3, 12, 'Tada ir muitininkai atėjo krikštytis ir tarė jam: „Mokytojau, ką mums daryti?“'),
  (@b42, 3, 13, 'O jis tarė jiems: „Nereikalaukite daugiau, nei jums yra paskirta“.'),
  (@b42, 3, 14, 'Taip pat ir kariai klausė jo, sakydami: „O ką mums daryti?“ Ir jis tarė jiems: „Nesmurtaukite nei prieš vieną žmogų nei neapkaltinkite nei vieno melagingai ir tenkinkitės savo alga“.'),
  (@b42, 3, 15, 'Ir tautai esant apimtai lūkesčio, ir visiems žmonėms mąstant savo širdyse apie Joną, ar jis yra Kristus, ar ne,'),
  (@b42, 3, 16, 'Jonas atsakė, sakydamas jiems visiems: „Iš tikro aš jus krikštiju vandeniu; bet ateina vienas už mane galingesnis, kurio batų raiščio aš nevertas atrišti; jis krikštys jus Šventąja Dvasia ir ugnimi;'),
  (@b42, 3, 17, 'jo rankoje yra jo vėtyklė, ir jis visiškai išvalys savo klojimą, ir surinks kviečius į savo svirną; bet pelus jis sudegins neužgesinama ugnimi“.'),
  (@b42, 3, 18, 'Ir savo raginimu daug ką kito jis skelbė tautai.'),
  (@b42, 3, 19, 'Bet tetrarchas Erodas, jo baramas dėl Erodijos, jo brolio Pilypo žmonos ir dėl visų piktų darbų, kuriuos Erodas buvo padaręs,'),
  (@b42, 3, 20, 'pridėjo viršum viso to ir tai, kad uždarė Joną į kalėjimą.'),
  (@b42, 3, 21, 'Na, o kai visa tauta krikštijosi, įvyko tai, kad ir Jėzui pasikrikštijus ir besimeldžiant atsivėrė dangus,'),
  (@b42, 3, 22, 'ir Šventoji Dvasia kūnišku pavidalu tarsi balandis nužengė ant jo, ir atėjo balsas iš dangaus, kuris tarė: „Tu esi mano mylimasis Sūnus; tavimi esu labai patenkintas“.'),
  (@b42, 3, 23, 'Ir Jėzus pats pradėjo būti apie trisdešimties metų, būdamas (kaip buvo manoma) Juozapo sūnus, kuris buvo sūnus Helio,'),
  (@b42, 3, 24, 'kuris buvo sūnus Matato, kuris buvo sūnus Levio, kuris buvo sūnus Melchio, kuris buvo sūnus Janajo, kuris buvo sūnus Juozapo,'),
  (@b42, 3, 25, 'kuris buvo sūnus Matatijo, kuris buvo sūnus Amoso, kuris buvo sūnus Naumo, kuris buvo sūnus Eslio, kuris buvo sūnus Nagajo,'),
  (@b42, 3, 26, 'kuris buvo sūnus Maato, kuris buvo sūnus Matatijo, kuris buvo sūnus Semėjo, kuris buvo sūnus Juozapo, kuris buvo sūnus Judos,'),
  (@b42, 3, 27, 'kuris buvo sūnus Joanano, kuris buvo sūnus Resos, kuris buvo sūnus Zorobabelio, kuris buvo sūnus Salatielio, kuris buvo sūnus Nerio,'),
  (@b42, 3, 28, 'kuris buvo sūnus Melchio, kuris buvo sūnus Adijo, kuris buvo sūnus Kosamo, kuris buvo sūnus Elmodamo, kuris buvo sūnus Ero,'),
  (@b42, 3, 29, 'kuris buvo sūnus Jozės, kuris buvo sūnus Eliezero, kuris buvo sūnus Jorimo, kuris buvo sūnus Matato, kuris buvo sūnus Levio,'),
  (@b42, 3, 30, 'kuris buvo sūnus Simeono, kuris buvo sūnus Judos, kuris buvo sūnus Juozapo, kuris buvo sūnus Jonano, kuris buvo sūnus Eliakimo,'),
  (@b42, 3, 31, 'kuris buvo sūnus Melėjo, kuris buvo sūnus Menano, kuris buvo sūnus Matatos, kuris buvo sūnus Natano, kuris buvo sūnus Dovydo,'),
  (@b42, 3, 32, 'kuris buvo sūnus Jesės, kuris buvo sūnus Obedo, kuris buvo sūnus Boozo, kuris buvo sūnus Salmono, kuris buvo sūnus Naasono,'),
  (@b42, 3, 33, 'kuris buvo sūnus Aminadabo, kuris buvo sūnus Aramo, kuris buvo sūnus Esromo, kuris buvo sūnus Fareso, kuris buvo sūnus Judos,'),
  (@b42, 3, 34, 'kuris buvo sūnus Jokūbo, kuris buvo sūnus Izaoko, kuris buvo sūnus Abraomo, kuris buvo sūnus Taros, kuris buvo sūnus Nachoro,'),
  (@b42, 3, 35, 'kuris buvo sūnus Serucho, kuris buvo sūnus Ragaujo, kuris buvo sūnus Faleko, kuris buvo sūnus Hebero, kuris buvo sūnus Salos,'),
  (@b42, 3, 36, 'kuris buvo sūnus Kainano, kuris buvo sūnus Arfaksado, kuris buvo sūnus Semo, kuris buvo sūnus Nojaus, kuris buvo sūnus Lamecho,'),
  (@b42, 3, 37, 'kuris buvo sūnus Matusalos, kuris buvo sūnus Henocho, kuris buvo sūnus Jaredo, kuris buvo sūnus Maleleelio, kuris buvo sūnus Kainano,'),
  (@b42, 3, 38, 'kuris buvo sūnus Eno, kuris buvo sūnus Seto, kuris buvo sūnus Adomo, kuris buvo sūnus Dievo.'),
  (@b42, 4, 1, 'Ir Jėzus, būdamas pilnas Šventosios Dvasios, grįžo nuo Jordano ir buvo Dvasios nuvestas į dykumą,'),
  (@b42, 4, 2, 'būdamas keturiasdešimt dienų velnio gundomas. Ir tomis dienomis jis nieko nevalgė; o joms pasibaigus jis po to buvo išalkęs.'),
  (@b42, 4, 3, 'Ir velnias jam tarė: „Jei tu esi Dievo Sūnus, įsakyk šitam akmeniui, kad jis pavirstų duona“.'),
  (@b42, 4, 4, 'O Jėzus atsakė jam, tardamas: „Yra parašyta, kad žmogus gyvens ne vien duona, bet kiekvienu Dievo žodžiu“.'),
  (@b42, 4, 5, 'Ir velnias, užvedęs jį į aukštą kalną, per vieną akimirką parodė jam visas pasaulio karalystes.'),
  (@b42, 4, 6, 'Ir velnias tarė jam: „Visą šitą valdžią ir jų šlovę aš tau duosiu, nes tai man yra duota; ir tai duodu kam tik noriu.'),
  (@b42, 4, 7, 'Todėl jei tu mane pagarbinsi, viskas bus tavo“.'),
  (@b42, 4, 8, 'O Jėzus atsakė ir tarė jam: „Pasitrauk už manęs, šėtone, nes yra parašyta: ‘Garbink Viešpatį, savo Dievą, ir tik jam tarnauk’“.'),
  (@b42, 4, 9, 'Ir jis atvedė jį į Jeruzalę, pastatė jį ant šventyklos viršūnės ir tarė jam: „Jei esi Dievo Sūnus, meskis nuo čia žemyn,'),
  (@b42, 4, 10, 'nes yra parašyta: ‘Jis įpareigos dėl tavęs savo angelus, kad saugotų tave,'),
  (@b42, 4, 11, 'ir savo rankose jie neš tave, kad kokiu metu neužsigautum savo kojos į akmenį’“.'),
  (@b42, 4, 12, 'O Jėzus atsakydamas jam tarė: „Yra pasakyta: ‘Negundyk Viešpaties, savo Dievo’“.'),
  (@b42, 4, 13, 'Ir kai velnias baigė visą gundymą, jis nuėjo nuo jo laikotarpiui.'),
  (@b42, 4, 14, 'Ir Jėzus Dvasios jėgoje grįžo į Galilėją; ir pasklido apie jį garsas aplinkui po visą sritį.'),
  (@b42, 4, 15, 'Ir jis mokė jų sinagogose visų šlovinamas.'),
  (@b42, 4, 16, 'Ir jis atėjo į Nazaretą, kur buvo užaugintas; ir pagal savo paprotį jis sabato dieną nuėjo į sinagogą ir atsistojo skaityti.'),
  (@b42, 4, 17, 'Ir jam buvo paduota pranašo Izaijo knyga. Ir kai jis atvertė knygą, jis rado vietą, kur buvo parašyta:'),
  (@b42, 4, 18, '„Viešpaties Dvasia yra ant manęs, nes jis patepė mane skelbti evangeliją vargšams; jis pasiuntė mane gydyti tų, kurie yra sudaužytomis širdimis, skelbti belaisviams išvadavimą ir akliesiems praregėjimą, išlaisvinti sumuštuosius,'),
  (@b42, 4, 19, 'skelbti priimtinus Viešpaties metus“.'),
  (@b42, 4, 20, 'Ir jis užvertė knygą, atidavė ją tarnautojui ir atsisėdo. Ir visų sinagogoje esančiųjų akys buvo įsmeigtos į jį.'),
  (@b42, 4, 21, 'Ir jis pradėjo jiems sakyti: „Šią dieną šis Raštas išsipildė jūsų ausyse“.'),
  (@b42, 4, 22, 'Ir visi jam liudijo ir stebėjosi maloningais žodžiais, einančiais iš jo burnos. Ir jie tarė: „Argi šis – ne Juozapo sūnus?“'),
  (@b42, 4, 23, 'Ir jis tarė jiems: „Jūs, žinoma, sakysite man šią patarlę: ‘Gydytojau, pats išsigydyk’ – padaryk ir čia, savo tėviškėje, tai, ką girdėjome esant atlikta Kafernaume“.'),
  (@b42, 4, 24, 'Ir jis tarė: „Iš tiesų sakau jums: joks pranašas nėra priimtinas savo tėviškėje“.'),
  (@b42, 4, 25, 'Bet sakau jums iš tiesų: „Elijo dienomis daug buvo našlių Izraelyje, kai dangus buvo uždarytas tris metus ir šešis mėnesius, kai visoje šalyje buvo didis badas;'),
  (@b42, 4, 26, 'bet nei pas vieną iš jų Elijas nebuvo siųstas, o tik į Sareptą, Sidono miestą, pas moterį našlę.'),
  (@b42, 4, 27, 'Ir daug raupsuotųjų buvo Izraelyje pranašo Eliziejaus laiku; bet nei vienas iš jų nebuvo apvalytas, o tik sirijietis Naamanas“.'),
  (@b42, 4, 28, 'Ir tai išgirdę, visi sinagogoje prisipildė rūstybės'),
  (@b42, 4, 29, 'ir pakilę išstūmė jį iš miesto ir nuvedė jį ant krašto kalvos, ant kurios buvo pastatytas jų miestas, kad jie numestų jį žemyn galva.'),
  (@b42, 4, 30, 'Bet jis, praėjęs per jų vidurį, nuėjo sau'),
  (@b42, 4, 31, 'ir atėjo žemyn į Kafernaumą, Galilėjos miestą, ir sabato dienomis juos mokė.'),
  (@b42, 4, 32, 'Ir jie stebėjosi jo mokslu, nes jo žodis buvo su galia.'),
  (@b42, 4, 33, 'Ir sinagogoje buvo žmogus, kuris turėjo netyro velnio dvasią ir šaukė garsiu balsu,'),
  (@b42, 4, 34, 'sakydamas: „Palik mus ramybėje! Kas mums darbo su tavimi, Jėzau iš Nazareto? Ar mūsų sunaikinti atėjai? Žinau tave, kas esi – Dievo Šventasis“.'),
  (@b42, 4, 35, 'Ir Jėzus jį sudraudė, sakydamas: „Nutilk ir išeik iš jo!“ Ir nubloškęs jį į vidurį, velnias išėjo iš jo ir jo nesužeidė.'),
  (@b42, 4, 36, 'Ir jie visi stebėjosi ir kalbėjo tarpusavyje, sakydami: „Kas tai per žodis! Nes su valdžia ir jėga jis įsako netyroms dvasioms, ir jos išeina“.'),
  (@b42, 4, 37, 'Ir garsas apie jį sklido į visas aplinkinio krašto vietas.'),
  (@b42, 4, 38, 'Ir jis pakilo iš sinagogos ir įėjo į Simono namus. Ir Simono žmonos motina buvo apimta didelio karščiavimo; ir jie maldavo jį dėl jos.'),
  (@b42, 4, 39, 'Ir jis atsistojo virš jos ir sudraudė karštinę; ir ta ją paliko; ir tuojau ji atsikėlė ir jiems patarnavo.'),
  (@b42, 4, 40, 'Na, o saulei leidžiantis, visi, kurie turėjo sergančių įvairiomis ligomis, atvedė juos pas jį; ir jis dėjo savo rankas ant kiekvieno iš jų, ir juos išgydė.'),
  (@b42, 4, 41, 'Taip pat iš daugelio išėjo ir velniai, šaukdami ir sakydami: „Tu esi Kristus, Dievo Sūnus“. Bet jis, drausdamas juos, neleido jiems kalbėti, nes jie žinojo, kad jis yra Kristus.'),
  (@b42, 4, 42, 'Ir kai buvo diena, jis išėjo ir nuėjo į dykvietę; ir tauta jo ieškojo, ir atėjo pas jį, ir jį sustabdė, kad jis nuo jų neišeitų.'),
  (@b42, 4, 43, 'Ir jis jiems tarė: „Turiu skelbti Dievo karalystę ir kitiems miestams; nes dėl to esu siųstas“.'),
  (@b42, 4, 44, 'Ir jis skelbė Galilėjos sinagogose.'),
  (@b42, 5, 1, 'Ir įvyko, kad, kai tauta veržėsi pas jį klausytis Dievo žodžio, jis stovėjo prie Genezareto ežero'),
  (@b42, 5, 2, 'ir pamatė du laivus, stovinčius palei ežerą; bet žvejai buvo išėję iš jų ir plovė savo tinklus.'),
  (@b42, 5, 3, 'Ir jis įžengė į vieną iš laivų, kuris buvo Simono, ir maldavo jį, kad jis truputį atsistumtų nuo sausumos. Ir jis atsisėdo ir mokė tautą iš laivo.'),
  (@b42, 5, 4, 'Na, o baigęs kalbėti jis tarė Simonui: „Pasileisk nuo kranto į gilumą ir nuleiskite savo tinklus traukimui“.'),
  (@b42, 5, 5, 'Ir Simonas atsakydamas jam tarė: „Mokytojau, mes visą naktį triūsėme ir nieko nepagavome; tačiau dėl tavo žodžio nuleisiu tinklą“.'),
  (@b42, 5, 6, 'Ir tai padarę jie užgriebė didžiulę žuvų daugybę; ir jų tinklas pratrūko.'),
  (@b42, 5, 7, 'Ir jie mojavo savo bendrininkams, buvusiems kitame laive, kad jie ateitų ir jiems padėtų. Ir jie atėjo ir pripildė abu laivus taip, kad jie pradėjo skęsti.'),
  (@b42, 5, 8, 'Kai Simonas Petras tai pamatė, jis parpuolė prie Jėzaus kelių, sakydamas: „Eik nuo manęs, o Viešpatie, nes esu nuodėmingas žmogus“.'),
  (@b42, 5, 9, 'Nes jis ir visi, buvusieji su juo, buvo apstulbę dėl to valksmo žuvų, kurias jie pagavo;'),
  (@b42, 5, 10, 'taip pat Zebediejaus sūnūs Jokūbas ir Jonas, kurie su Simonu buvo bendrininkai. Ir Jėzus tarė Simonui: „Nebijok; nuo šiol tu gaudysi žmones“.'),
  (@b42, 5, 11, 'Ir atplukdę savo laivus į sausumą jie viską paliko ir sekė paskui jį.'),
  (@b42, 5, 12, 'Ir įvyko, kai jis buvo viename mieste, štai vyras pilnas raupsų, kuris, pamatęs Jėzų, parpuolė veidu žemyn ir jo maldavo, sakydamas: „Viešpatie, jei nori, gali padaryti mane švariu“.'),
  (@b42, 5, 13, 'Ir jis ištiesė savo ranką ir palietė jį, sakydamas: „Noriu; būk švarus“. Ir iškart raupsai nuo jo atsitraukė.'),
  (@b42, 5, 14, 'Ir jis įpareigojo jį niekam nepasakoti: „Bet eik, pasirodyk kunigui ir atnašauk už savo apvalymą, kaip liudijimą jiems, pagal tai, kaip Mozė įsakė“.'),
  (@b42, 5, 15, 'Bet garsas apie jį sklido dar plačiau; ir didelės minios susirinko pasiklausyti ir būti jo išgydyti nuo jų negalių.'),
  (@b42, 5, 16, 'Ir jis pasitraukė į dykumą ir meldėsi.'),
  (@b42, 5, 17, 'Ir įvyko vieną dieną, kai jis mokė, kad šalimais sėdėjo fariziejai ir įstatymo mokytojai, kurie buvo atėję iš kiekvieno Galilėjos, Judėjos ir Jeruzalės miestelio; ir Viešpaties jėga buvo ten, kad gydytų juos.'),
  (@b42, 5, 18, 'Ir štai vyrai guolyje atnešė suparalyžiuotą žmogų; ir jie ieškojo būdų jį įnešti ir paguldyti prieš jį.'),
  (@b42, 5, 19, 'Ir dėl minios neradę kelio, kuriuo galėtų jį įnešti, jie užlipo ant namo stogo ir pro čerpes nuleido jį su jo guoliu į vidurį priešais Jėzų.'),
  (@b42, 5, 20, 'Ir pamatęs jų tikėjimą jis tarė jam: „Žmogau, tavo nuodėmės tau atleistos“.'),
  (@b42, 5, 21, 'O raštininkai ir fariziejai pradėjo svarstyti, sakydami: „Kas yra šitas, kuris kalba piktžodžiavimus? Kas gali atleisti nuodėmes, jei ne vienas Dievas?“'),
  (@b42, 5, 22, 'Bet kai Jėzus suprato jų mintis, jis atsakydamas tarė jiems: „Ką svarstote savo širdyse?'),
  (@b42, 5, 23, 'Kas yra lengviau, ar pasakyti: ‘Tavo nuodėmės tau atleistos’ ar pasakyti: ‘Kelkis ir vaikščiok?’'),
  (@b42, 5, 24, 'Bet kad žinotumėte, jog žmogaus Sūnus turi ant žemės valdžią atleisti nuodėmes (jis tarė sergančiam paralyžiumi): sakau tau, kelkis, imk savo guolį ir eik į savo namus“.'),
  (@b42, 5, 25, 'Ir jis tuojau atsikėlė jų akivaizdoje, pasiėmė tai, ant ko gulėjo, ir šlovindamas Dievą nuėjo į savo namus.'),
  (@b42, 5, 26, 'Ir jie visi stebėjosi ir šlovino Dievą, ir buvo pilni baimės, sakydami: „Šiandien pamatėme keistų dalykų“.'),
  (@b42, 5, 27, 'O po to jis išėjo ir pamatė muitininką, vardu Levis, sėdintį prie muito surinkimo, ir jam tarė: „Sek paskui mane“.'),
  (@b42, 5, 28, 'Ir jis, viską palikęs, atsikėlė ir sekė paskui jį.'),
  (@b42, 5, 29, 'Ir Levis savo namuose paruošė jam didelę puotą; ir ten buvo didelis būrys muitininkų ir kitų, sėdinčių su jais.'),
  (@b42, 5, 30, 'Bet jų raštininkai ir fariziejai murmėjo prieš jo mokinius, sakydami: „Kodėl valgote ir geriate su muitininkais ir nusidėjėliais?“'),
  (@b42, 5, 31, 'Ir Jėzus atsakydamas jiems tarė: „Sveikiesiems nereikia gydytojo; bet tik sergantiems.'),
  (@b42, 5, 32, 'Atėjau pašaukti atgailai ne teisiųjų, bet nusidėjėlių”.'),
  (@b42, 5, 33, 'Ir jie tarė jam: „Kodėl Jono mokiniai dažnai pasninkauja ir atlikinėja maldas, taip pat ir fariziejų mokiniai; bet tavieji valgo ir geria?“'),
  (@b42, 5, 34, 'O jis jiems tarė: „Ar galite vestuvių menės vaikus priversti pasninkauti, kol su jais yra jaunikis?'),
  (@b42, 5, 35, 'Bet ateis dienos, kai jaunikis bus iš jų atimtas, ir tada, tomis dienomis jie pasninkaus“.'),
  (@b42, 5, 36, 'Ir jis dar pasakė jiems palyginimą: „Niekas nededa naujo drabužio skiautės ant senojo; kitaip ir naujasis suplėšomas, ir skiautė, išplėšta iš naujojo, nepritinka senajam.'),
  (@b42, 5, 37, 'Ir niekas nepila naujo vyno į senus indus; antraip naujas vynas sutraukytų indus ir išsilietų, ir indai pražūtų.'),
  (@b42, 5, 38, 'Bet naujas vynas turi būti pilamas į naujus indus; ir abeji yra išsaugoti.'),
  (@b42, 5, 39, 'Taip pat nei vienas, gėręs seno vyno, tuojau neužsinorės naujo, nes jis sako: ‘Senasis yra geresnis’“.'),
  (@b42, 6, 1, 'Ir įvyko antrąjį sabatą po pirmojo, kad jis ėjo per javų laukus; o jo mokiniai skabė javų varpas ir valgė, trindami jas rankose.'),
  (@b42, 6, 2, 'Ir kai kurie iš fariziejų jiems tarė: „Kodėl darote tai, kas yra neteisėta daryti sabato dienomis?“'),
  (@b42, 6, 3, 'Bet Jėzus atsakydamas jiems tarė: „Ar nepaskaitėte nei to, ką Dovydas darė, kai buvo išalkęs jis pats ir tie, kurie buvo su juo;'),
  (@b42, 6, 4, 'kaip jis įėjo į Dievo namus ir ėmė bei valgė parodomosios duonos ir taip pat davė tiems, kurie buvo su juo; kurios niekam neteisėta valgyti, bet tik kunigams?“'),
  (@b42, 6, 5, 'Ir jis tarė jiems, kad „žmogaus Sūnus yra ir sabato Viešpats“.'),
  (@b42, 6, 6, 'Ir įvyko taip pat kitą sabatą, kad jis įėjo į sinagogą ir mokė; ir ten buvo žmogus, kurio dešinioji ranka buvo nudžiūvusi.'),
  (@b42, 6, 7, 'O raštininkai ir fariziejai jį stebėjo, ar jis gydys sabato dieną, kad jie rastų prieš jį kaltinimą.'),
  (@b42, 6, 8, 'Bet jis pažinojo jų mintis ir tarė žmogui, kuris turėjo nudžiūvusią ranką: „Kelkis ir stok į vidurį“. Ir jis kėlėsi ir stojosi pirmyn.'),
  (@b42, 6, 9, 'Tada Jėzus jiems tarė: „Paklausiu jūsų vieno: ar sabato dienomis teisėta daryti gera, ar daryti pikta? Gelbėti gyvybę, ar ją sunaikinti?“'),
  (@b42, 6, 10, 'Ir apžvelgęs juos visus jis tarė tam žmogui: „Ištiesk savo ranką“. Ir jis taip padarė; ir jo ranka vėl tapo sveika kaip ir kita.'),
  (@b42, 6, 11, 'Ir jie prisipildė įniršio; ir tarėsi vienas su kitu, ką jie galėtų padaryti Jėzui.'),
  (@b42, 6, 12, 'Ir įvyko tomis dienomis, kad jis išėjo į kalną melstis ir pasiliko visą naktį maldoje Dievui.'),
  (@b42, 6, 13, 'Ir kai buvo diena, jis pasišaukė savo mokinius; ir iš jų jis išsirinko dvylika, kuriuos ir pavadino apaštalais:'),
  (@b42, 6, 14, 'Simoną (kurį ir pavadino Petru) ir jo brolį Andriejų, Jokūbą ir Joną, Pilypą ir Baltramiejų,'),
  (@b42, 6, 15, 'Matą ir Tomą, Alfiejaus sūnų Jokūbą ir Simoną, vadinamą Zelotu,'),
  (@b42, 6, 16, 'Jokūbo brolį Judą ir Judą Iskariotą, kuris ir buvo išdavikas.'),
  (@b42, 6, 17, 'Ir jis atėjo su jais žemyn ir atsistojo lygumoje; ir jo mokinių būrys bei didelė tautos minia iš visos Judėjos, Jeruzalės, iš Tyro ir Sidono pajūrio, kurie atėjo jo pasiklausyti ir būti išgydyti nuo savo ligų,'),
  (@b42, 6, 18, 'ir tie, kurie buvo netyrų dvasių kamuojami; ir jie buvo išgydyti.'),
  (@b42, 6, 19, 'Ir visa minia siekė jį paliesti, nes iš jo ėjo veiksmingumas ir juos visus gydė.'),
  (@b42, 6, 20, 'Ir jis pakėlė savo akis į savo mokinius ir tarė: „Palaiminti jūs, vargšai, nes jūsų yra Dievo karalystė.'),
  (@b42, 6, 21, 'Palaiminti jūs, kurie dabar alkstate, nes jūs būsite pasotinti. Palaiminti jūs, kurie dabar verkiate, nes jūs juoksitės.'),
  (@b42, 6, 22, 'Palaiminti esate jūs, kai žmonės jūsų nekęs ir kai jie atskirs jus nuo savo draugijos, ir jums prikaišios, ir atmes jūsų vardą kaip piktą dėl žmogaus Sūnaus.'),
  (@b42, 6, 23, 'Džiaukitės tą dieną ir šokinėkite iš džiaugsmo, nes štai didis yra jūsų atlygis danguje; nes panašiai ir jų tėvai darė pranašams.'),
  (@b42, 6, 24, 'Bet vargas jums, kurie esate turtingi! Nes jūs jau gavote savo paguodą.'),
  (@b42, 6, 25, 'Vargas jums, kurie esate sotūs! Nes jūs alksite. Vargas jums, kurie dabar juokiatės! Nes jūs liūdėsite ir verksite.'),
  (@b42, 6, 26, 'Vargas jums, kai visi žmonės kalbės apie jus gerai! Nes taip darė jų tėvai netikriems pranašams.'),
  (@b42, 6, 27, 'Bet jums, kurie klausotės, sakau: mylėkite savo priešus, darykite gera tiems, kurie jūsų nekenčia,'),
  (@b42, 6, 28, 'laiminkite tuos, kurie jus keikia, ir melskitės už tuos, kurie piktai su jumis elgiasi.'),
  (@b42, 6, 29, 'Ir tam, kuris trenkia tau per vieną skruostą, pasiūlyk ir antrąjį; ir tam, kuris atima tavo marškinius, nedrausk paimti ir tavo apsiausto.'),
  (@b42, 6, 30, 'Duok kiekvienam, kuris tavęs prašo; ir iš to, kuris paima tai, kas tavo, nereikalauk to atgal.'),
  (@b42, 6, 31, 'Ir kaip norite, kad žmonės jums darytų, taip pat ir jūs jiems darykite.'),
  (@b42, 6, 32, 'Nes jei mylite tuos, kurie jus myli, kokią jūs turite padėką? Nes ir nusidėjėliai myli tuos, kurie juos myli.'),
  (@b42, 6, 33, 'Ir jei darote gera tiems, kurie jums gera daro, kokią jūs turite padėką? Nes ir nusidėjėliai daro lygiai tą patį.'),
  (@b42, 6, 34, 'Ir jei skolinate tiems, iš kurių tikitės atgauti, kokią jūs turite padėką? Nes ir nusidėjėliai skolina nusidėjėliams, kad atgautų tiek pat.'),
  (@b42, 6, 35, 'Bet mylėkite savo priešus ir darykite gera, ir skolinkite nesitikėdami nieko atgal; ir jūsų atlygis bus didis, ir būsite Aukščiausiojo vaikai; nes jis yra geras nedėkingiems ir piktiesiems.'),
  (@b42, 6, 36, 'Todėl būkite gailestingi, kaip ir jūsų Tėvas yra gailestingas.'),
  (@b42, 6, 37, 'Neteiskite, ir nebūsite teisiami; nesmerkite, ir nebūsite smerkiami; atleiskite, ir jums bus atleista;'),
  (@b42, 6, 38, 'duokite, ir jums bus duota; gerą saiką, prikimštą ir sukratytą, ir su kaupu duos jums į užantį. Nes kokiu saiku seikėjate, tokiu pat bus jums atseikėta“.'),
  (@b42, 6, 39, 'Ir jis kalbėjo jiems palyginimą: „Ar gali aklas vesti aklą? Argi ne jie abu įkris į griovį?'),
  (@b42, 6, 40, 'Mokinys ne didesnis už savo mokytoją; bet kiekvienas, kuris yra tobulas, bus kaip jo mokytojas.'),
  (@b42, 6, 41, 'Ir kodėl matai krislą, esantį tavo brolio akyje, bet nepastebi rąsto savo akyje?'),
  (@b42, 6, 42, 'Arba kaip gali sakyti savo broliui: ‘Broli, leisk man ištraukti krislą iš tavo akies’, pats nematydamas rąsto savo akyje? Veidmainy, pirmiau išmesk rąstą iš savo akies, ir tuomet aiškiai matysi kaip ištraukti krislą iš savo brolio akies.'),
  (@b42, 6, 43, 'Nes geras medis neduoda sugedusio vaisiaus; ir sugedęs medis neduoda gero vaisiaus.'),
  (@b42, 6, 44, 'Nes kiekvienas medis atpažįstamas iš jo paties vaisiaus. Nes nuo erškėčių niekas nerenka figų, nei nuo gervuogės krūmo nerenka vynuogių.'),
  (@b42, 6, 45, 'Geras žmogus iš gero savo širdies lobyno neša tai, kas gera; o piktas žmogus iš pikto savo širdies lobyno neša tai, kas pikta; nes iš širdies pertekliaus kalba jo burna.'),
  (@b42, 6, 46, 'Ir kodėl vadinate mane: ‘Viešpatie, Viešpatie’, o nedarote to, ką sakau?'),
  (@b42, 6, 47, 'Kas ateina pas mane ir klausosi mano pasakymų, ir juos daro, aš parodysiu jums, į ką jis yra panašus:'),
  (@b42, 6, 48, 'jis panašus į žmogų, kuris stato namą; iškasė giliai, ir padėjo pamatą ant uolos; ir kai pakilo potvynis, srovė smarkiai daužėsi į tą namą ir negalėjo jo pajudinti; nes jo pamatas buvo pastatytas ant uolos.'),
  (@b42, 6, 49, 'Bet tas, kuris klausosi, o nedaro, yra panašus į žmogų, kuris be pamato ant žemės pastatė namą, į kurį smarkiai daužėsi srovė, ir kaipmat jis sugriuvo; ir didi buvo to namo griūtis“.'),
  (@b42, 7, 1, 'Na, o pabaigęs visus savo pasakymus besiklausiusiai tautai, jis įėjo į Kafernaumą.'),
  (@b42, 7, 2, 'Ir vienas šimtininko tarnas, kuris jam buvo brangus, sirgo ir buvo arti mirties.'),
  (@b42, 7, 3, 'Ir išgirdęs apie Jėzų, jis pasiuntė pas jį žydų vyresniuosius, maldaudamas jo, kad jis ateitų ir išgydytų jo tarną.'),
  (@b42, 7, 4, 'Ir atėję pas Jėzų jie primygtinai jo maldavo, sakydami, kad „jis yra vertas, jog jis jam tai padarytų,');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b42, 7, 5, 'nes jis myli mūsų tautą ir jis pastatė mums sinagogą“.'),
  (@b42, 7, 6, 'Tada Jėzus ėjo su jais. O jam esant netoli namų, šimtininkas pasiuntė pas jį draugus, sakydamas jam: „Viešpatie, nesivargink, nes nesu vertas, kad įeitum po mano stogu;'),
  (@b42, 7, 7, 'todėl nemaniau save esant vertu ateiti pas tave, bet pasakyk žodžiu, ir mano tarnas pasveiks.'),
  (@b42, 7, 8, 'Nes ir aš esu žmogus, paskirtas būti pavaldžiu valdžiai, turintis sau pavaldžių kareivių, ir sakau vienam: ‘Eik’, ir jis eina; ir kitam: ‘Ateik’, ir jis ateina; ir savo tarnui: ‘Daryk tai’, ir jis tai daro“.'),
  (@b42, 7, 9, 'Tai išgirdęs Jėzus stebėjosi juo ir atsigręžęs tarė sekusiai paskui jį tautai: „Sakau jums: neradau tokio didžio tikėjimo; ne, ne Izraelyje“.'),
  (@b42, 7, 10, 'O tie, kurie buvo pasiųsti, sugrįžę į namus rado sirgusį tarną sveiką.'),
  (@b42, 7, 11, 'Ir įvyko rytojaus dieną, kad jis įėjo į miestą, vadinamą Nainu; o daug jo mokinių ir daug liaudies ėjo su juo.'),
  (@b42, 7, 12, 'Na, o kai jis priartėjo prie miesto vartų, štai išnešė numirėlį, vienintelį savo motinos sūnų, o ji buvo našlė; ir daug miesto liaudies buvo su ja.'),
  (@b42, 7, 13, 'Ir kai Viešpats ją pamatė, jis pasigailėjo jos ir tarė jai: „Neverk“.'),
  (@b42, 7, 14, 'Ir jis atėjo ir palietė karsto neštuvus; ir jį nešusieji sustojo. Ir jis tarė: „Jaunuoli, sakau tau: kelkis“.'),
  (@b42, 7, 15, 'Ir tas, kuris buvo miręs, atsisėdo ir pradėjo kalbėti. Ir jis atidavė jį jo motinai.'),
  (@b42, 7, 16, 'Ir visus apėmė baimė; ir jie šlovino Dievą, sakydami: „Didis pranašas yra kilęs tarp mūsų“ ir: „Dievas aplankė savo tautą“.'),
  (@b42, 7, 17, 'Ir šis gandas apie jį iškeliavo po visą Judėją ir aplink po visą kraštą.'),
  (@b42, 7, 18, 'Ir Jono mokiniai jam apsakė visa tai.'),
  (@b42, 7, 19, 'Ir Jonas, pasišaukęs du iš savo mokinių, pasiuntė juos pas Jėzų, sakydamas: „Ar tu esi tas, kuris turi ateiti, ar mums laukti kito?“'),
  (@b42, 7, 20, 'Vyrai pas jį atėję tarė: „Jonas Krikštytojas mus atsiuntė pas tave, sakydamas: ‘Ar tu esi tas, kuris turi ateiti, ar mums laukti kito?‘“'),
  (@b42, 7, 21, 'Ir tą pačią valandą jis išgydė daugelį iš jų negalių, rykščių ir iš piktų dvasių; ir daugeliui aklųjų jis suteikė regėjimą.'),
  (@b42, 7, 22, 'Tada Jėzus atsakydamas jiems tarė: „Eikite ir pasakykite Jonui, ką matėte ir girdėjote: kaip aklieji regi, raišieji vaikšto, raupsuotieji yra apvalomi, kurtieji girdi, mirusieji prikeliami, vargšams skelbiama evangelija.'),
  (@b42, 7, 23, 'Ir palaimintas yra tas, kuris manimi nepasipiktins“.'),
  (@b42, 7, 24, 'O kai Jono pasiuntiniai išėjo, jis pradėjo kalbėti tautai apie Joną: „Ko išėjote į dykumą pažiūrėti? Ar vėjo siūbuojamos nendrės?'),
  (@b42, 7, 25, 'Tačiau ko išėjote pažiūrėti? Ar žmogaus, apsirengusio minkštais rūbais? Štai tie, kurie puošniai apsirengę ir prabangiai gyvena, yra karalių rūmuose.'),
  (@b42, 7, 26, 'Tačiau ko išėjote pažiūrėti? Ar pranašo? Taip, sakau jums, ir daug daugiau negu pranašo.'),
  (@b42, 7, 27, 'Jis yra tas, apie kurį yra parašyta: ‘Štai siunčiu savo pasiuntinį pirma tavo veido, kuris pirma tavęs paruoš tavo kelią’.'),
  (@b42, 7, 28, 'Nes sakau jums: tarp tų, kurie gimę iš moterų, nėra didesnio pranašo už Joną Krikštytoją; bet tas, kuris yra mažiausias Dievo karalystėje, yra didesnis už jį“.'),
  (@b42, 7, 29, 'Ir visa tauta, kuri jį girdėjo, ir muitininkai pateisino Dievą, pasikrikštydami Jono krikštu.'),
  (@b42, 7, 30, 'Bet fariziejai ir įstatymininkai atmetė Dievo sumanymą prieš save pačius, nebūdami jo pakrikštyti.'),
  (@b42, 7, 31, 'Ir Viešpats tarė: „Tad kam gi prilyginsiu šios kartos žmones? Ir į ką jie yra panašūs?'),
  (@b42, 7, 32, 'Jie yra panašūs į vaikus, sėdinčius turgavietėje ir vienas kitam šaukiančius ir sakančius: ‘Mes jums dūdavome, o jūs nešokote; mes jums raudojome, o jūs neverkėte’.'),
  (@b42, 7, 33, 'Nes Jonas Krikštytojas atėjo nei duonos valgantis, nei vyno geriantis; o jūs sakote: ‘Jis turi velnią’.'),
  (@b42, 7, 34, 'Žmogaus Sūnus atėjo valgantis ir geriantis; ir jūs sakote: ‘Štai žmogus rijūnas ir vyno gėrėjas, muitininkų ir nusidėjėlių draugas!’'),
  (@b42, 7, 35, 'Bet išmintis yra išteisinta visų jos vaikų“.'),
  (@b42, 7, 36, 'Ir vienas iš fariziejų prašė jo, kad jis valgytų su juo. Ir jis įėjo į fariziejaus namus ir sėdosi prie valgio.'),
  (@b42, 7, 37, 'Ir štai moteris mieste, kuri buvo nusidėjėlė, sužinojusi, kad Jėzus sėdi prie valgio fariziejaus namuose, atnešė alebastrinę tepalo dėžutę'),
  (@b42, 7, 38, 'ir atsistojo iš užnugario prie jo kojų verkdama, ir pradėjo ašaromis plauti jo kojas, ir šluostė jas savo galvos plaukais, bučiavo jo kojas ir tepė jas tepalu.'),
  (@b42, 7, 39, 'Na, o fariziejus, kuris buvo jį pasikvietęs, tai matydamas kalbėjo savyje, sakydamas: „Jei šis žmogus būtų pranašas, jis žinotų, kas ir kokia tai per moteris, kuri jį liečia, nes ji yra nusidėjėlė“.'),
  (@b42, 7, 40, 'Ir Jėzus atsakydamas jam tarė: „Simonai, turiu tau kai ką pasakyti“. O jis sako: „Mokytojau, sakyk“.'),
  (@b42, 7, 41, '„Buvo vienas skolintojas, kuris turėjo du skolininkus: vienas buvo skolingas penkis šimtus denarų, o kitas – penkiasdešimt.'),
  (@b42, 7, 42, 'Ir kai jie neturėjo nieko susimokėti, jis nuoširdžiai jiems abiems atleido. Todėl pasakyk man, kuris iš jų labiau jį mylės?“'),
  (@b42, 7, 43, 'Simonas atsakydamas tarė: „Manau, kad tas, kuriam jis daugiausiai atleido“. Ir jis tarė jam: „Tu teisingai teisi“.'),
  (@b42, 7, 44, 'Ir jis atsisuko į moterį ir tarė Simonui: „Ar matai šią moterį? Aš įėjau į tavo namus, tu nedavei man vandens mano kojoms; bet ji ašaromis nuplovė mano kojas ir jas nušluostė savo galvos plaukais.'),
  (@b42, 7, 45, 'Tu nepabučiavai manęs; bet ši moteris nuo to laiko, kai įėjau, nesiliovė bučiavusi mano kojų.'),
  (@b42, 7, 46, 'Mano galvos aliejumi tu nepatepei; bet ši moteris patepė tepalu mano kojas.'),
  (@b42, 7, 47, 'Dėl to sakau tau: jos nuodėmės, kurių yra daug, yra atleistos; nes ji labai mylėjo; bet kam yra mažai atleista, tas myli mažai“.'),
  (@b42, 7, 48, 'Ir jis jai tarė: „Tavo nuodėmės yra atleistos“.'),
  (@b42, 7, 49, 'Ir tie, kurie su juo sėdėjo prie valgio, pradėjo savyje kalbėti: „Kas yra šis, kuris ir nuodėmes atleidžia?“'),
  (@b42, 7, 50, 'Ir jis tarė moteriai: „Tavo tikėjimas tave išgelbėjo – eik ramybėje“.'),
  (@b42, 8, 1, 'Ir po to įvyko, kad jis ėjo per kiekvieną miestą ir kaimą, skelbdamas ir garsindamas Dievo karalystės džiugią naujieną; o su juo buvo dvylika'),
  (@b42, 8, 2, 'ir kai kurios moterys, kurios buvo išgydytos nuo piktų dvasių ir negalių: Marija, vadinama Magdaliete, iš kurios išėjo septyni velniai,'),
  (@b42, 8, 3, 'ir Erodo ūkvedžio Chūzo žmona Joana, ir Zuzana, ir daug kitų, kurios jam patarnavo iš savo turto.'),
  (@b42, 8, 4, 'Ir kai susirinko daug liaudies ir atėjo pas jį iš kiekvieno miesto, jis kalbėjo palyginimu:'),
  (@b42, 8, 5, '„Sėjėjas išėjo sėti savo sėklos; ir jam besėjant, viena krito palei kelią; ir ji buvo sutrypta, ir oro skrajūnai ją prarijo.'),
  (@b42, 8, 6, 'Ir viena krito ant uolos; ir vos tik išdygusi ji nudžiūvo, nes jai trūko drėgmės.'),
  (@b42, 8, 7, 'Ir viena krito tarp erškėčių; ir erškėčiai išdygo kartu su ja ir ją nusmelkė.'),
  (@b42, 8, 8, 'O kita krito ant geros žemės ir išdygo, ir davė šimteriopą vaisių“. Ir tai pasakęs jis šaukė: „Kas turi ausis klausyti, teklauso!“'),
  (@b42, 8, 9, 'Ir jo mokiniai kláusė jo, sakydami: „Kas tai galėtų būti per palyginimas?“'),
  (@b42, 8, 10, 'Ir jis tarė: „Jums yra duota pažinti Dievo karalystės paslaptis; bet kitiems – palyginimais; kad matydami jie nematytų ir klausydami jie nesuprastų.'),
  (@b42, 8, 11, 'Na, o palyginimas yra šis: sėkla yra Dievo žodis.'),
  (@b42, 8, 12, 'Tie palei kelią yra tie, kurie klausosi; tada ateina velnias ir paima žodį iš jų širdžių, kad jie netikėtų ir nebūtų išgelbėti.'),
  (@b42, 8, 13, 'Tie ant uolos yra tie, kurie išgirdę priima žodį su džiaugsmu; bet jie neturi šaknies, kurie trumpam tiki, o gundymo metu atkrinta.'),
  (@b42, 8, 14, 'O kas krito tarp erškėčių, yra tie, kurie išgirdę išeina ir yra nusmelkiami šio gyvenimo rūpesčių, turtų bei malonumų ir neduoda vaisiaus iki tobulumo.'),
  (@b42, 8, 15, 'Bet ta ant geros žemės yra tie, kurie išgirdę žodį saugo jį doroje ir geroje širdyje ir duoda vaisių kantrumu.'),
  (@b42, 8, 16, 'Nei vienas, uždegęs žvakę, neuždengia jos indu ir nededa jos po lova; bet pastato ją žvakidėje, kad įeinantys matytų šviesą.'),
  (@b42, 8, 17, 'Nes nieko nėra slapto, kas neišaiškėtų; nei nieko paslėpto, kas netaptų žinoma ir plačiai nepasklistų.'),
  (@b42, 8, 18, 'Todėl žiūrėkite, kaip klausotės; nes kas turi, tam bus duota; o kas neturi, iš to bus atimta ir tai, ką jis tariasi turįs“.'),
  (@b42, 8, 19, 'Tada pas jį atėjo jo motina bei jo broliai ir negalėjo prie jo prieiti dėl spūsties.'),
  (@b42, 8, 20, 'Ir buvo jam pasakyta kai kurių, kurie tarė: „Tavo motina ir tavo broliai stovi lauke, norėdami tave pamatyti“.'),
  (@b42, 8, 21, 'O jis atsakė ir tarė jiems: „Mano motina ir mano broliai yra tie, kurie klausosi Dievo žodžio ir jį vykdo“.'),
  (@b42, 8, 22, 'Na, o vieną dieną įvyko, kad jis su savo mokiniais įėjo į laivą; ir jis tarė jiems: „Persikelkime į kitą ežero pusę“. Ir jie pasileido nuo kranto.'),
  (@b42, 8, 23, 'Bet, jiems beplaukiant, jis užmigo; ir ant ežero užėjo vėjo audra; ir jie buvo apsemti vandens ir buvo pavojuje.'),
  (@b42, 8, 24, 'Ir jie atėjo pas jį ir jį pažadino, sakydami: „Mokytojau, mokytojau, mes žūstame“. Tada jis atsikėlė ir sudraudė vėją bei vandens šėlsmą; ir jie liovėsi, ir buvo tyku.'),
  (@b42, 8, 25, 'Ir jis tarė jiems: „Kur yra jūsų tikėjimas?“ Ir jie išsigandę stebėjosi, sakydami vienas kitam: „Kas tai per žmogus? Nes jis įsako net vėjams ir vandeniui, ir tie jo klauso“.'),
  (@b42, 8, 26, 'Ir jie atvyko į gadarėnų kraštą, kuris yra priešais Galilėją.'),
  (@b42, 8, 27, 'Ir kai jis žengė į sausumą, jį sutiko vienas žmogus iš miesto, kuris ilgą laiką turėjo velnių ir nedėvėjo drabužių, ir negyveno jokiuose namuose, bet kapuose.'),
  (@b42, 8, 28, 'Pamatęs Jėzų, jis šaukė ir parpuolė prieš jį bei garsiu balsu tarė: „Kas man darbo su tavimi, Jėzau, aukščiausiojo Dievo Sūnau? Meldžiu tave, nekankink manęs“'),
  (@b42, 8, 29, '(nes jis buvo įsakęs netyrajai dvasiai išeiti iš to žmogaus. Nes dažnai ji pagaudavo jį; ir jis buvo laikomas surištas grandinėmis ir pančiuose; ir jis sutraukydavo raiščius, ir būdavo velnio varomas į dykumą).'),
  (@b42, 8, 30, 'Ir Jėzus klausė jo, sakydamas: „Koks tavo vardas?“ O jis tarė: „Legionas“, nes daug velnių buvo į jį įėję.'),
  (@b42, 8, 31, 'Ir jie maldavo jį, kad jis neįsakytų jiems išeiti į gelmę.'),
  (@b42, 8, 32, 'O ten ant kalno buvo daugybės besiganančių kiaulių banda; ir jie maldavo jo, kad jis leistų jiems į jas įeiti. Ir jis jiems leido.'),
  (@b42, 8, 33, 'Tada išėjo velniai iš to žmogaus ir įėjo į kiaules; ir banda lėkė galvotrūkčiais žemyn nuo stačios vietos į ežerą ir prigėrė.'),
  (@b42, 8, 34, 'Ir kai tie, kurie jas ganė, pamatė, kas atsitiko, jie pabėgo ir nuėję papasakojo tai mieste ir kiemuose.'),
  (@b42, 8, 35, 'Tada jie išėjo pažiūrėti, kas buvo atsitikę; ir atėjo pas Jėzų, ir rado žmogų, iš kurio buvo išėję velniai, sėdintį prie Jėzaus kojų, apsirengusį ir sveiko proto; ir jie išsigando.'),
  (@b42, 8, 36, 'Ir tie, kurie tai matė, jiems papasakojo, kokiu būdu buvo išgydytas velnių apsėstasis.'),
  (@b42, 8, 37, 'Tuomet visa minia iš aplinkinio gadarėnų krašto maldavo jo pasitraukti nuo jų; nes jie buvo apimti didelės baimės; ir jis įlipo į laivą ir sugrįžo atgal.'),
  (@b42, 8, 38, 'Na, o žmogus, iš kurio buvo išėję velniai, jo maldavo, kad galėtų būti su juo; bet Jėzus jį išsiuntė, sakydamas:'),
  (@b42, 8, 39, '„Grįžk į savo namus ir papasakok, kokių didžių dalykų tau padarė Dievas“. Ir jis nuėjo ir paskelbė po visą miestą, kokių didžių dalykų jam padarė Jėzus.'),
  (@b42, 8, 40, 'Ir įvyko, kad, Jėzui sugrįžus, tauta jį priėmė su džiaugsmu; nes jie visi jo laukė.'),
  (@b42, 8, 41, 'Ir štai atėjo žmogus, vardu Jayras, ir jis buvo sinagogos valdovas; ir jis parpuolė prie Jėzaus kojų ir jo maldavo, kad jis ateitų į jo namus;'),
  (@b42, 8, 42, 'nes jis turėjo vienintelę dukterį, apie dvylikos metų amžiaus, ir ji gulėjo bemirštanti. Bet jam beeinant tauta jį grūdo.'),
  (@b42, 8, 43, 'Ir moteris, dvylika metų turinti kraujoplūdį, išleidusi visą savo pragyvenimą gydytojams ir nei vieno negalėjusi būti išgydyta,'),
  (@b42, 8, 44, 'priėjo jam iš užnugario ir palietė jo drabužio kraštą; ir tuoj pat jos kraujoplūdis sustojo.'),
  (@b42, 8, 45, 'Ir Jėzus tarė: „Kas mane palietė?“ Visiems išsiginant Petras ir su juo esantys tarė: „Mokytojau, minia tave grūda ir spaudžia, o tu sakai: ‘Kas mane palietė?’“'),
  (@b42, 8, 46, 'Ir Jėzus tarė: „Kažkas mane palietė, nes supratau, kad iš manęs yra išėjusi jėga“.'),
  (@b42, 8, 47, 'Ir moteris, pamačiusi, kad nepasislėps, atėjo drebėdama ir parkritusi prieš jį pareiškė jam visos tautos akivaizdoje, dėl kokios priežasties ji palietė jį ir kaip tuoj pat pasveiko.'),
  (@b42, 8, 48, 'Ir jis jai tarė: „Dukra, būk paguosta: tavo tikėjimas tave išgydė; eik ramybėje“.'),
  (@b42, 8, 49, 'Jam bekalbant, ateina vienas iš sinagogos valdovo namų, jam sakydamas: „Tavo duktė yra mirusi; nevargink Mokytojo“.'),
  (@b42, 8, 50, 'Bet tai išgirdęs Jėzus jam atsakė, tardamas: „Nebijok: vien tik tikėk, ir ji taps sveika“.'),
  (@b42, 8, 51, 'Ir įėjęs į namus, jis niekam neleido įeiti, išskyrus Petrą, Jokūbą, Joną ir tos mergaitės tėvą bei motiną.'),
  (@b42, 8, 52, 'O visi verkė ir ją apraudojo; bet jis tarė: „Neverkite; ji nemirusi, bet miega“.'),
  (@b42, 8, 53, 'Ir jie išsijuokė iš jo, žinodami, kad ji mirusi.'),
  (@b42, 8, 54, 'Ir jis išvarė juos visus laukan, ir paėmė ją už rankos, ir pašaukė, sakydamas: „Mergaite, kelkis“.'),
  (@b42, 8, 55, 'Ir jos dvasia sugrįžo, ir ji kaipmat atsikėlė; ir jis įsakė duoti jai valgio.'),
  (@b42, 8, 56, 'Ir jos tėvai buvo apstulbinti; bet jis juos įpareigojo, kad niekam nepasakytų, kas atsitiko.'),
  (@b42, 9, 1, 'Tuomet jis pašaukė dvylika savo mokinių ir davė jiems jėgą bei valdžią visiems velniams ir gydyti ligoms.'),
  (@b42, 9, 2, 'Ir jis pasiuntė juos skelbti Dievo karalystę ir gydyti ligonius.'),
  (@b42, 9, 3, 'Ir jis jiems tarė: „Nesiimkite nieko kelionei: nei lazdų, nei kelionmaišio, nei duonos, nei pinigų; nei neturėkite po dvejus marškinius.'),
  (@b42, 9, 4, 'Ir į kokius namus beįeitumėte, ten pasilikite ir iš ten eikite.'),
  (@b42, 9, 5, 'O kas jūsų nepriimtų, išeidami iš to miesto nusikratykite net dulkes nuo savo kojų kaip liudijimą prieš juos“.'),
  (@b42, 9, 6, 'Ir jie išėjo ir ėjo per miestelius, skelbdami evangeliją ir visur gydydami.'),
  (@b42, 9, 7, 'Na, o tetrarchas Erodas išgirdo viską, kas buvo jo padaryta; ir jis suglumo, nes buvo kai kurių pasakyta, kad Jonas yra prisikėlęs iš numirusių;'),
  (@b42, 9, 8, 'o kai kurių, kad Elijas pasirodė; o kitų, kad vienas iš senųjų pranašų yra prisikėlęs.'),
  (@b42, 9, 9, 'Ir Erodas tarė: „Jonui nukirsdinau galvą, bet kas yra šitas, apie kurį girdžiu tokius dalykus?“ Ir jis norėjo jį pamatyti.'),
  (@b42, 9, 10, 'Ir sugrįžę apaštalai papasakojo jam viską, ką jie padarė. Ir jis paėmė juos ir nuėjo nuošalėn į dykvietę, priklausančią miestui, vadinamam Betsaida.'),
  (@b42, 9, 11, 'Ir tai sužinojusi, tauta sekė paskui jį; ir jis juos priėmė ir kalbėjo jiems apie Dievo karalystę, ir išgydė tuos, kuriems reikėjo gydymo.'),
  (@b42, 9, 12, 'O dienai pradėjus slinkti į pabaigą, atėjo dvylika ir tarė jam: „Paleisk minią, kad jie eitų į miestelius bei aplinkinius vienkiemus ir pernakvotų, ir susirastų maisto; nes čia esame dykvietėje“.'),
  (@b42, 9, 13, 'Bet jis tarė jiems: „Jūs duokite jiems valgyti“. O jie tarė: „Mes neturime daugiau kaip penkių kepalų ir dviejų žuvų; nebent nueitume ir nupirktume valgio visai šitai liaudžiai“.'),
  (@b42, 9, 14, 'Nes jų buvo apie penkis tūkstančius vyrų. Ir jis tarė savo mokiniams: „Susodinkite juos grupėmis po penkiasdešimt“.'),
  (@b42, 9, 15, 'Ir jie taip padarė ir juos visus susodino.'),
  (@b42, 9, 16, 'Tada jis paėmė penkis kepalus bei dvi žuvis ir, žiūrėdamas į dangų, juos palaimino, laužė ir davė mokiniams išdėlioti priešais minią;'),
  (@b42, 9, 17, 'ir jie valgė, ir visi pasisotino; ir buvo pririnkta dvylika pintinių jiems likusių nuolaužų.'),
  (@b42, 9, 18, 'Ir įvyko, kai jis buvo vienas besimeldžiąs, jo mokiniai buvo su juo; ir jis jų paklausė, sakydamas: „Kuo tauta sako mane esantį?“'),
  (@b42, 9, 19, 'Jie atsakydami tarė: „Jonu Krikštytoju; bet kai kurie – Eliju; o kiti sako, kad vienas iš senųjų pranašų yra prisikėlęs“.'),
  (@b42, 9, 20, 'Jis tarė jiems: „Bet kuo jūs sakote mane esantį?“ Petras atsakydamas tarė: „Dievo Kristumi“.'),
  (@b42, 9, 21, 'Ir jis tuojau juos įpareigojo ir įsakė, kad niekam to nepasakotų;'),
  (@b42, 9, 22, 'sakydamas: „Žmogaus Sūnus turi daug iškentėti ir būti atstumtas vyresniųjų, vyriausiųjų kunigų ir raštininkų, būti nužudytas ir trečią dieną prikeltas“.'),
  (@b42, 9, 23, 'Ir jis tarė jiems visiems: „Jei kas nori eiti paskui mane, tas teišsižada savęs, kasdien teima savo kryžių ir teseka paskui mane.'),
  (@b42, 9, 24, 'Nes kas nori išsaugoti savo gyvybę, tas ją praras; bet kas praras savo gyvybę dėl manęs, tas ją išgelbės.'),
  (@b42, 9, 25, 'Nes kokią naudą turėtų žmogus, jei jis laimėtų visą pasaulį, o prarastų save arba būtų atmestas?'),
  (@b42, 9, 26, 'Nes kas gėdysis manęs ir mano žodžių, to gėdysis žmogaus Sūnus, kai ateis šlovėje savo, savo Tėvo ir šventųjų angelų.'),
  (@b42, 9, 27, 'Bet iš tiesų jums sakau: yra keli čia stovintys, kurie neragaus mirties, kol neišvys Dievo karalystės“.'),
  (@b42, 9, 28, 'Ir įvyko, maždaug už aštuonių dienų po šitų pasakymų, jis pasiėmė Petrą, Joną bei Jokūbą ir užžengė į kalną melstis.'),
  (@b42, 9, 29, 'Ir jam meldžiantis jo veido išvaizda pasikeitė, ir jo rūbas buvo baltas ir spindintis.'),
  (@b42, 9, 30, 'Ir štai su juo kalbėjo du vyrai, tai buvo Mozė ir Elijas;'),
  (@b42, 9, 31, 'kurie pasirodė šlovėje ir kalbėjo apie jo baigtį, kurią jis turės įvykdyti Jeruzalėje.'),
  (@b42, 9, 32, 'Bet Petras ir su juo esantys buvo apsunkinti miego; ir atsibudę jie pamatė jo šlovę ir tuos du vyrus, stovinčius su juo.'),
  (@b42, 9, 33, 'Ir įvyko, kai jie nuo jo nuėjo, Petras tarė Jėzui: „Mokytojau, gera mums čia būti; padarykime tris padangtes: vieną tau, vieną Mozei ir vieną Elijui“, nežinodamas, ką jis pasakė.'),
  (@b42, 9, 34, 'Jam taip bekalbant užėjo debesis ir uždengė juos šešėliu; ir jie išsigando, kai jie paniro į debesį.'),
  (@b42, 9, 35, 'Ir atėjo balsas iš debesies, sakydamas: „Šitas yra mano mylimasis Sūnus; jo klausykite“.'),
  (@b42, 9, 36, 'O balsui praėjus Jėzus buvo rastas vienas. Ir jie laikė tai paslaptyje ir tomis dienomis niekam nepasakojo nieko apie tai, ką buvo matę.'),
  (@b42, 9, 37, 'Ir įvyko, kad rytojaus dieną, jiems nusileidus nuo kalvos, jį pasitiko daug liaudies.'),
  (@b42, 9, 38, 'Ir štai žmogus šaukė iš būrio, sakydamas: „Mokytojau, maldauju tave, apžiūrėk mano sūnų; nes jis yra vienintelis mano vaikas.'),
  (@b42, 9, 39, 'Ir štai dvasia paima jį, ir jis staiga šaukia; ir ji plėšo jį, kad jis net putoja, ir jį mušdama sunkiai nuo jo atstoja.'),
  (@b42, 9, 40, 'Ir aš maldavau tavo mokinių ją išvaryti; o jie negalėjo“.'),
  (@b42, 9, 41, 'Ir Jėzus atsakydamas tarė: „O netikinti ir iškrypusi karta, kiek ilgai būsiu su jumis ir jus kęsiu? Atvesk čia savo sūnų“.'),
  (@b42, 9, 42, 'Ir jam dar beateinant, velnias parbloškė jį žemėn ir jį draskė. Ir Jėzus sudraudė netyrąją dvasią, išgydė vaiką ir atidavė jį jo tėvui.'),
  (@b42, 9, 43, 'Ir jie visi stebėjosi galinga Dievo jėga. Bet jiems visiems besistebint visu tuo, ką Jėzus padarė, jis tarė savo mokiniams:'),
  (@b42, 9, 44, '„Tegul šitie pasakymai įsiskverbia į jūsų ausis; nes žmogaus Sūnus bus atiduotas į žmonių rankas“.'),
  (@b42, 9, 45, 'Bet jie nesuprato šito pasakymo, ir tai liko nuo jų paslėpta, kad jie to nesuvokė; ir jie bijojo jo klausti apie šį pasakymą.'),
  (@b42, 9, 46, 'Tada kilo tarp jų samprotavimas, kuris iš jų turėtų būti didžiausias.'),
  (@b42, 9, 47, 'O Jėzus, suprasdamas jų širdies mintis, paėmė vaiką ir pastatė jį šalia savęs,'),
  (@b42, 9, 48, 'ir tarė jiems: „Kas priims šitą vaiką mano vardu, tas mane priima; o kas mane priims, priima tą, kuris mane siuntė; nes tas, kuris tarp jūsų yra visų mažiausias, tas bus didis“.'),
  (@b42, 9, 49, 'Ir Jonas atsakė ir tarė: „Mokytojau, matėme vieną tavo vardu išvarinėjantį velnius; ir jam draudėme, nes jis neseka su mumis“.'),
  (@b42, 9, 50, 'O Jėzus jam tarė: „Nedrauskite jam; nes kas ne prieš mus, tas yra už mus“.'),
  (@b42, 9, 51, 'Ir įvyko, atėjus laikui, kai jis turėjo būti paimtas aukštyn, jis ryžtingai nukreipė savo veidą eiti į Jeruzalę'),
  (@b42, 9, 52, 'ir išsiuntė pirma savo veido pasiuntinius; ir jie nuėjo, ir įėjo į samariečių kaimą, kad jam paruoštų.'),
  (@b42, 9, 53, 'Ir jie nepriėmė jo, nes jo veidas buvo kaip einančiojo į Jeruzalę.'),
  (@b42, 9, 54, 'Ir kai jo mokiniai Jokūbas ir Jonas tai pamatė, jie tarė: „Viešpatie, ar nori, kad įsakytume ugniai nusileisti iš dangaus ir juos praryti, kaip Elijas padarė?“'),
  (@b42, 9, 55, 'Bet jis atsisuko, juos sudraudė ir tarė: „Nežinote, kokios jūs esate dvasios.'),
  (@b42, 9, 56, 'Nes žmogaus Sūnus neatėjo sunaikinti žmonių gyvybių, bet jas išgelbėti“. Ir jie nuėjo į kitą kaimą.'),
  (@b42, 9, 57, 'Ir įvyko, kad, jiems einant keliu, vienas žmogus jam tarė: „Viešpatie, aš seksiu paskui tave, kur tik tu eisi“.'),
  (@b42, 9, 58, 'O Jėzus jam tarė: „Lapės turi olas, ir oro paukščiai turi lizdus; bet žmogaus Sūnus neturi kur padėti savo galvos“.'),
  (@b42, 9, 59, 'Ir jis tarė kitam: „Sek paskui mane“. Bet jis tarė: „Viešpatie, leisk man pirmiau eiti ir palaidoti savo tėvą“.'),
  (@b42, 9, 60, 'Jėzus jam tarė: „Tegul mirusieji laidoja savo mirusiuosius; bet tu eik ir skelbk Dievo karalystę“.'),
  (@b42, 9, 61, 'Ir kitas taipogi tarė: „Viešpatie, aš seksiu paskui tave; bet leisk man pirmiau eiti atsisveikinti su esančiais mano namuose“.'),
  (@b42, 9, 62, 'O Jėzus jam tarė: „Nei vienas, uždėjęs ant plūgo ranką ir besižvalgąs atgal, netinka Dievo karalystei“.'),
  (@b42, 10, 1, 'Po šių dalykų Viešpats paskyrė dar kitus septyniasdešimt ir išsiuntė juos po du pirma savo veido į kiekvieną miestą ir vietą, kur jis pats ketino eiti.'),
  (@b42, 10, 2, 'Todėl jis tarė jiems: „Pjūtis iš tiesų didelė, bet darbininkų maža; todėl melskite pjūties Viešpatį, kad jis išsiųstų darbininkų į savo pjūtį.'),
  (@b42, 10, 3, 'Eikite; štai jus išsiunčiu kaip avinėlius tarp vilkų.'),
  (@b42, 10, 4, 'Nesineškite nei piniginės, nei kelionmaišio, nei apavo ir nieko kelyje nesveikinkite.'),
  (@b42, 10, 5, 'Ir į kokius namus beįeisite, pirma sakykite: ‘Ramybė tebūna šiems namams’.'),
  (@b42, 10, 6, 'Ir jei ten bus ramybės sūnus, jūsų ramybė ilsėsis ant jų; jei ne, ji sugrįš pas jus.'),
  (@b42, 10, 7, 'Ir pasilikite tuose pačiuose namuose, valgykite ir gerkite tai, ką jie duos; nes darbininkas yra vertas savo užmokesčio. Neikite iš namų į namus.'),
  (@b42, 10, 8, 'Ir į kokį miestą beįeisite, ir jie jus priims, valgykite tai, kas yra prieš jus padėta;'),
  (@b42, 10, 9, 'ir gydykite ten esančius ligonius, ir sakykite jiems: ‘Jums prisiartino Dievo karalystė’.'),
  (@b42, 10, 10, 'Bet jei į kokį miestą jums įėjus jie jūsų nepriimtų, išeikite į jo gatves ir sakykite:'),
  (@b42, 10, 11, '‘Mes nusibraukiame prieš jus net jūsų miesto dulkes, prilipusias ant mūsų; tačiau žinokite tai, kad jums prisiartino Dievo karalystė’.'),
  (@b42, 10, 12, 'Bet sakau jums, kad Sodomai aną dieną bus daug pakenčiamiau negu tam miestui.'),
  (@b42, 10, 13, 'Vargas tau, Chorazine! Vargas tau, Betsaida! Nes jei galingi darbai, kurie padaryti jumyse, būtų buvę padaryti Tyre ir Sidone, jie jau seniai būtų atgailavę, sėdėdami ašutinėje ir pelenuose.'),
  (@b42, 10, 14, 'Bet Tyrui ir Sidonui teisme bus daug pakenčiamiau, negu jums.'),
  (@b42, 10, 15, 'Ir tu, Kafernaume, kuris esi išaukštintas iki dangaus, būsi nustumtas žemyn į pragarą.'),
  (@b42, 10, 16, 'Kas jūsų klauso, tas manęs klauso; ir kas jus niekina, tas mane niekina; o kas mane niekina, tas niekina tą, kuris mane siuntė“.'),
  (@b42, 10, 17, 'Ir septyniasdešimt su džiaugsmu sugrįžo, sakydami: „Viešpatie, per tavo vardą mums paklūsta net velniai“.'),
  (@b42, 10, 18, 'O jis tarė jiems: „Mačiau šėtoną, kaip žaibą krintantį iš dangaus.'),
  (@b42, 10, 19, 'Štai jums duodu valdžią mindyti gyvates bei skorpionus, ir viršesnę už visą priešo jėgą; ir niekas jokiais būdais jums nepakenks.'),
  (@b42, 10, 20, 'Tačiau tuo nesidžiaukite, kad dvasios yra jums paklusnios; bet verčiau džiaukitės, kad jūsų vardai yra įrašyti danguje“.'),
  (@b42, 10, 21, 'Tą valandą Jėzus džiaugėsi dvasioje ir tarė: „Dėkoju tau, o Tėve, dangaus ir žemės Viešpatie, kad paslėpei šiuos dalykus nuo išmintingųjų bei protingųjų ir apreiškei juos kūdikiams; būtent taip, Tėve; nes taip atrodė gera tavo akyse.'),
  (@b42, 10, 22, 'Viskas man yra duota mano Tėvo; ir niekas nežino, kas yra Sūnus, bet tik Tėvas; ir kas yra Tėvas, bet tik Sūnus ir tas, kuriam Sūnus nori jį apreikšti“.'),
  (@b42, 10, 23, 'Ir jis atsisuko į savo mokinius ir tarė asmeniškai jiems: „Palaimintos akys, matančios tai, ką jūs matote;'),
  (@b42, 10, 24, 'nes sakau jums, kad daug pranašų ir karalių norėjo pamatyti tai, ką jūs matote, bet nepamatė; ir išgirsti tai, ką jūs girdite, bet neišgirdo“.'),
  (@b42, 10, 25, 'Ir štai atsistojo vienas įstatymininkas ir gundė jį, sakydamas: „Mokytojau, ką turiu daryti, kad paveldėčiau amžinąjį gyvenimą?“'),
  (@b42, 10, 26, 'Jis jam tarė: „Kas yra parašyta įstatyme? Kaip tu skaitai?“'),
  (@b42, 10, 27, 'O jis atsakydamas tarė: „Mylėk Viešpatį savo Dievą visa savo širdimi ir visa savo siela, ir visomis savo jėgomis, ir visu savo protu; ir savo artimą kaip save patį“.'),
  (@b42, 10, 28, 'Ir jis tarė jam: „Teisingai atsakei; daryk tai ir gyvensi“.'),
  (@b42, 10, 29, 'Bet jis, norėdamas save išteisinti, tarė Jėzui: „O kas yra mano artimas?“'),
  (@b42, 10, 30, 'Ir Jėzus atsakydamas tarė: „Vienas žmogus ėjo iš Jeruzalės žemyn į Jerichą ir papuolė tarp vagių, kurie nuvilko jam drabužius, jį sužeidė ir nuėjo palikę jį pusgyvį.'),
  (@b42, 10, 31, 'Ir atsitiktinai tuo keliu ėjo žemyn vienas kunigas; ir, jį pamatęs, jis praėjo kita puse.'),
  (@b42, 10, 32, 'Ir taip pat levitas, būdamas toje vietoje, atėjo ir pažiūrėjo į jį, ir praėjo kita puse.'),
  (@b42, 10, 33, 'Bet vienas samarietis keliaudamas atėjo, kur jis buvo; ir pamatęs jį pasigailėjo,'),
  (@b42, 10, 34, 'priėjo, aprišo jo žaizdas, užpildamas aliejumi ir vynu, užsodino jį ant savo gyvulio, nugabeno jį į užeigą ir juo rūpinosi.'),
  (@b42, 10, 35, 'O rytojaus dieną išeidamas jis išsiėmė du denarus ir padavė juos šeimininkui, ir tarė jam: ‘Pasirūpink juo; o jei ką išleisi viršaus, sugrįžęs tau atmokėsiu’.'),
  (@b42, 10, 36, 'Na, tai kaip tu galvoji, kuris iš tų trijų buvo artimas tam, kuris papuolė tarp vagių?“');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b42, 10, 37, 'Ir jis tarė: „Tas, kuris jam parodė gailestingumą“. Tada Jėzus jam tarė: „Eik, ir tu taip pat daryk“.'),
  (@b42, 10, 38, 'Na, o jiems einant įvyko, kad jis įėjo į vieną kaimą; ir viena moteris, vardu Morta, priėmė jį į savo namus.'),
  (@b42, 10, 39, 'Ir ji turėjo seserį, vadinamą Marija, kuri ir sėdėjo prie Jėzaus kojų ir klausėsi jo žodžio.'),
  (@b42, 10, 40, 'Bet Morta apsisunkino dėl didelio patarnavimo ir priėjusi prie jo tarė: „Viešpatie, ar tau nerūpi, kad mano sesuo paliko mane vieną patarnauti? Todėl pasakyk jai, kad ji man padėtų“.'),
  (@b42, 10, 41, 'O Jėzus atsakė ir tarė jai: „Morta, Morta, tu rūpiniesi ir varginiesi dėl daug ko;'),
  (@b42, 10, 42, 'bet vieno tereikia, ir Marija pasirinko tą gerąją dalį, kuri nebus iš jos atimta“.'),
  (@b42, 11, 1, 'Ir įvyko, kad jam vienoje vietoje besimeldžiant, kai jis baigė, vienas iš jo mokinių jam tarė: „Viešpatie, išmokyk mus melstis, kaip ir Jonas mokė savo mokinius“.'),
  (@b42, 11, 2, 'Ir jis jiems tarė: „Kai meldžiatės, sakykite: ‘Tėve mūsų, kuris esi danguje, tebūna pašvęstas tavo vardas. Teateina tavo karalystė. Tebūna įvykdyta tavo valia – kaip danguje, taip ir žemėje.'),
  (@b42, 11, 3, 'Kas dieną duok mums kasdienės mūsų duonos.'),
  (@b42, 11, 4, 'Ir atleisk mums mūsų nuodėmes; nes ir mes atleidžiame kiekvienam, kuris yra mums skolingas. Ir nevesk mūsų į pagundą; bet gelbėk mus nuo pikto’“.'),
  (@b42, 11, 5, 'Ir jis tarė jiems: „Kuris iš jūsų turės draugą ir, nuėjęs pas jį vidurnaktį, sakys jam: ‘Drauge, paskolink man tris kepalus;'),
  (@b42, 11, 6, 'nes mano draugas iš savo kelionės atėjo pas mane, bet aš neturiu nieko prieš jį padėti’?'),
  (@b42, 11, 7, 'O anas iš vidaus atsakys ir tars: ‘Netrukdyk manęs; durys jau užsklęstos, ir mano vaikai yra su manimi lovoje; negaliu keltis ir tau duoti’.'),
  (@b42, 11, 8, 'Sakau jums: nors jis nesikels ir neduos jam dėl to, kad yra jo draugas, tačiau dėl jo įkyrumo jis atsikels ir duos jam tiek, kiek reikia.'),
  (@b42, 11, 9, 'Ir aš sakau jums: prašykite, ir jums bus duota; ieškokite, ir rasite; belskite, ir jums bus atidaryta.'),
  (@b42, 11, 10, 'Nes kiekvienas, kuris prašo, gauna; ir tas, kuris ieško, randa; o tam, kuris beldžiasi, bus atidaryta.'),
  (@b42, 11, 11, 'Ar kuris iš jūsų, būdamas tėvu, duonos prašančiam sūnui duotų akmenį? Arba jeigu jis prašytų žuvies, ar jis vietoje žuvies duotų jam gyvatę?'),
  (@b42, 11, 12, 'Arba jei jis prašytų kiaušinio, ar jis pasiūlytų jam skorpioną?'),
  (@b42, 11, 13, 'Tad jei jūs, būdami pikti, mokate duoti savo vaikams geras dovanas, tai kiek daugiau jūsų dangiškasis Tėvas duos Šventąją Dvasią tiems, kurie jo prašo?“'),
  (@b42, 11, 14, 'Ir jis išvarinėjo velnią, ir tas buvo nebylys. Ir įvyko, kai velnias buvo išėjęs, nebylys prakalbo; ir tauta nustebo.'),
  (@b42, 11, 15, 'Bet vieni iš jų tarė: „Jis išvarinėja velnius per velnių vadą Belzebubą“.'),
  (@b42, 11, 16, 'O kiti, jį gundydami, ieškojo iš jo ženklo iš dangaus.'),
  (@b42, 11, 17, 'Bet jis, žinodamas jų mintis, tarė jiems: „Kiekviena karalystė, pasidalinusi prieš save, tampa suniokota; ir namai, pasidalinę prieš namus, griūna.'),
  (@b42, 11, 18, 'Jei ir šėtonas būtų prieš save pasidalinęs, kaipgi išstovėtų jo karalystė? Nes sakote, kad išvarinėju velnius per Belzebubą.'),
  (@b42, 11, 19, 'Ir jei aš išvarinėju velnius per Belzebubą, per ką jūsų sūnūs juos išvarinėja? Todėl jie bus jūsų teisėjai.'),
  (@b42, 11, 20, 'Bet jei išvarinėju velnius Dievo pirštu, be abejonės pas jus atėjo Dievo karalystė.'),
  (@b42, 11, 21, 'Kai apsiginklavęs stipruolis saugo savo rūmus, jo turtas yra ramybėje;'),
  (@b42, 11, 22, 'bet kai ant jo užeis stipresnis už jį ir jį nugalės, jis atims iš jo visus ginklus, kuriais tas pasitikėjo, ir padalins jo grobį.'),
  (@b42, 11, 23, 'Kas ne su manimi, tas yra prieš mane; ir kas nerenka su manimi, tas barsto.'),
  (@b42, 11, 24, 'Netyroji dvasia, išėjusi iš žmogaus, vaikšto sausose vietose, ieškodama poilsio; ir neradusi ji sako: ‘Sugrįšiu į savo namus, iš kurių išėjau’.'),
  (@b42, 11, 25, 'Ir atėjusi ji randa juos iššluotus ir išpuoštus.'),
  (@b42, 11, 26, 'Tada ji eina ir pasiima kitas septynias, už save piktesnes dvasias; ir jos įeina, ir ten apsigyvena; ir galutinė to žmogaus būsena yra blogesnė negu pirmoji“.'),
  (@b42, 11, 27, 'Ir įvyko, jam bekalbant tuos dalykus, viena moteris iš grupės pakėlė savo balsą ir tarė jam: „Palaimintos įsčios, kurios tave nešiojo, ir krūtys, kurias tu žindai“.'),
  (@b42, 11, 28, 'Bet jis tarė: „Taip, verčiau palaiminti tie, kurie klausosi Dievo žodžio ir jo laikosi“.'),
  (@b42, 11, 29, 'Ir kai prisirinko tirštai liaudies, jis pradėjo sakyti: „Šita yra piktoji karta – jie ieško ženklo; ir jiems nebus duota jokio ženklo, bet tik pranašo Jonos ženklas.'),
  (@b42, 11, 30, 'Nes kaip Jona buvo ženklas nineviečiams, taip ir žmogaus Sūnus bus šitai kartai.'),
  (@b42, 11, 31, 'Pietų karalienė kelsis į teismą su šios kartos žmonėmis ir juos pasmerks, nes ji atėjo iš tolimiausių žemės pakraščių pasiklausyti Saliamono išminties; o štai čia yra didesnis negu Saliamonas.'),
  (@b42, 11, 32, 'Ninevės žmonės kelsis į teismą su šia karta ir ją pasmerks, nes Jonai skelbiant jie atgailavo; o štai čia yra didesnis negu Jona.'),
  (@b42, 11, 33, 'Nei vienas, uždegęs žvakę, nededa jos į slaptą vietą ar po saiku, bet į žvakidę, kad įeinantys matytų šviesą.'),
  (@b42, 11, 34, 'Kūno šviesa yra akis; todėl jei tavo akis vienalypė, tai ir visas tavo kūnas yra pilnas šviesos; bet kai tavo akis yra pikta, tai ir tavo kūnas pilnas tamsos.'),
  (@b42, 11, 35, 'Todėl žiūrėk, kad tavyje esanti šviesa nebūtų tamsa.'),
  (@b42, 11, 36, 'Todėl jei tavo visas kūnas pilnas šviesos, neturintis jokios tamsios dalies, visas bus pilnas šviesos, kaip kad tave apšviečia skaistus žvakės spindėjimas“.'),
  (@b42, 11, 37, 'Ir jam bekalbant vienas fariziejus maldavo jo, kad papietautų su juo; ir jis įėjo ir sėdosi prie valgio.'),
  (@b42, 11, 38, 'O kai fariziejus tai pamatė, jis stebėjosi, kad jis prieš pietus pirmiau neapsiplovė.'),
  (@b42, 11, 39, 'Ir Viešpats jam tarė: „Nagi, jūs, fariziejai, švarinate taurės ir dubens išorę; bet jūsų vidus yra pilnas plėšrumo ir nedorybės.'),
  (@b42, 11, 40, 'Kvailiai, argi tas, kuris padarė išorę, nepadarė ir to, kas yra viduje?'),
  (@b42, 11, 41, 'Bet verčiau duokite išmaldai iš to, ką turite; ir štai, viskas jums yra švaru.'),
  (@b42, 11, 42, 'Bet vargas jums, fariziejai! Nes jūs duodate dešimtinę iš mėtų, rūtų ir visokių žolių, o teismą ir Dievo meilę apeinate; šituos turėtumėte daryti ir nepalikti kitų neatliktų.'),
  (@b42, 11, 43, 'Vargas jums, fariziejai! Nes jūs mėgstate pirmuosius krėslus sinagogose ir sveikinimus turguose.'),
  (@b42, 11, 44, 'Vargas jums, raštininkai ir fariziejai, veidmainiai! Nes jūs esate kaip kapai, kurių nesimato, ir žmonės, kurie ant jų vaikšto, jų nepastebi“.'),
  (@b42, 11, 45, 'Tada atsakė vienas iš įstatymininkų ir jam tarė: „Mokytojau, taip sakydamas tu ir mums priekaištauji“.'),
  (@b42, 11, 46, 'O jis tarė: „Vargas ir jums, įstatymininkai! Nes jūs kraunate žmonėms nepakeliamas naštas, o patys neliečiate naštų nei vienu savo pirštu.'),
  (@b42, 11, 47, 'Vargas jums! Nes jūs statote pranašų kapus, o jūsų tėvai juos žudė.'),
  (@b42, 11, 48, 'Iš tiesų jūs liudijate, kad pritariate savo tėvų darbams, nes jie tikrai juos nužudė, o jūs statote jų kapus.'),
  (@b42, 11, 49, 'Todėl ir Dievo išmintis sakė: ‘Aš siųsiu jiems pranašų bei apaštalų, ir vienus iš jų jie užmuš ir persekios,'),
  (@b42, 11, 50, 'kad iš šios kartos būtų išreikalautas visų pranašų kraujas, kuris buvo pralietas nuo pasaulio įkūrimo;'),
  (@b42, 11, 51, 'nuo Abelio kraujo iki Zacharijo kraujo, kuris žuvo tarp aukuro ir šventyklos’; iš tiesų sakau jums: bus jo išreikalauta iš šios kartos.'),
  (@b42, 11, 52, 'Vargas jums, įstatymininkai! Nes atėmėte pažinimo raktą; jūs patys neįėjote ir įeinantiems trukdėte“.'),
  (@b42, 11, 53, 'Ir kai jis jiems tai kalbėjo, raštininkai ir fariziejai pradėjo smarkiai jo reikalauti ir jį kurstyti, kad apie daug ką kalbėtų;'),
  (@b42, 11, 54, 'tykodami jo ir siekdami ką nors pagauti iš jo burnos, kad galėtų jį apkaltinti.'),
  (@b42, 12, 1, 'Tuo tarpu, kai susirinko nesuskaičiuojama daugybė liaudies, kad jie net vienas kitą trypė, jis pradėjo sakyti pirmiausia savo mokiniams: „Saugokitės fariziejų raugo, kuris yra veidmainystė.'),
  (@b42, 12, 2, 'Nes nėra nieko uždengto, kas nebus atskleista; ir paslėpto, kas netaps žinoma.'),
  (@b42, 12, 3, 'Todėl ką kalbėjote tamsoje, bus išgirsta šviesoje; ir ką kalbėjote į ausį kambarėliuose, bus skelbiama ant namų stogų.'),
  (@b42, 12, 4, 'Ir aš sakau jums, mano draugai: nebijokite tų, kurie nužudo kūną ir po to nieko daugiau negali padaryti.'),
  (@b42, 12, 5, 'Bet aš jus įspėju, ko jums reikia bijoti: bijokite to, kuris nužudęs turi galią įmesti į pragarą; taip, sakau jums, jo bijokite.'),
  (@b42, 12, 6, 'Ar ne penki žvirbliai parduodami už du asus, ir nei vienas iš jų nėra užmirštas Dievo akivaizdoje?'),
  (@b42, 12, 7, 'Bet netgi jūsų galvos plaukai yra suskaičiuoti. Todėl nebijokite – jūs vertesni už daugybę žvirblių.'),
  (@b42, 12, 8, 'Taip pat jums sakau: kas išpažins mane žmonių akivaizdoje, tą ir žmogaus Sūnus išpažins Dievo angelų akivaizdoje;'),
  (@b42, 12, 9, 'bet kas išsigina manęs žmonių akivaizdoje, to bus išsiginta Dievo angelų akivaizdoje.'),
  (@b42, 12, 10, 'Ir kas kalbės žodį prieš žmogaus Sūnų, tam bus atleista; bet kas piktžodžiaus Šventajai Dvasiai, tam nebus atleista.'),
  (@b42, 12, 11, 'Ir kai jie ves jus į sinagogas, pas valdytojus ir valdžias, negalvokite, kaip ar ką turėsite atsakyti, ar ką jums reikės sakyti;'),
  (@b42, 12, 12, 'nes Šventoji Dvasia tą pačią valandą jus mokys, ką turėsite sakyti“.'),
  (@b42, 12, 13, 'Ir vienas iš būrio tarė jam: „Mokytojau, sakyk mano broliui, kad jis pasidalytų su manimi paveldą“.'),
  (@b42, 12, 14, 'Ir jis jam tarė: „Žmogau, kas mane paskyrė jūsų teisėju ar dalytoju?“'),
  (@b42, 12, 15, 'Ir jis jiems tarė: „Žiūrėkite ir saugokitės godumo; nes žmogaus gyvybė nesusideda iš gausybės jo turimų dalykų“.'),
  (@b42, 12, 16, 'Ir jis kalbėjo jiems palyginimą, sakydamas: „Vieno turtingo žmogaus dirva davė gausiai;'),
  (@b42, 12, 17, 'ir jis pagalvojo savyje, sakydamas: ‘Ką man daryti, nes neturiu vietos, kur sudėti savo vaisių?’'),
  (@b42, 12, 18, 'Ir jis tarė: ‘Štai ką padarysiu – išversiu savo svirnus ir pastatysiu didesnius; ir ten sudėsiu visus savo vaisius ir savo gėrybes.'),
  (@b42, 12, 19, 'Ir tarsiu savo sielai: ‘Siela, tu turi daug gėrybių, sukrautų daugeliui metų; ilsėkis, valgyk, gerk ir linksminkis’“.'),
  (@b42, 12, 20, 'Bet Dievas jam tarė: ‘Kvaily, šią naktį iš tavęs bus pareikalauta tavo sielos; kieno tada bus tie dalykai, kuriais apsirūpinai?’'),
  (@b42, 12, 21, 'Toks yra tas, kuris kaupia sau turtus, o nėra turtingas Dievui“.'),
  (@b42, 12, 22, 'Ir jis tarė savo mokiniams: „Todėl sakau jums: nesirūpinkite savo gyvybe, ką valgysite; nei kūnu, kuo vilkėsite.'),
  (@b42, 12, 23, 'Gyvybė yra daugiau negu maistas, ir kūnas yra daugiau negu drabužis.'),
  (@b42, 12, 24, 'Pasvarstykite apie varnus, nes jie nei sėja, nei pjauna; jie neturi nei sandėlio, nei svirno; o Dievas juos maitina; tai kiek labiau jūs esate vertesni už skrajūnus?'),
  (@b42, 12, 25, 'Ir kuris iš jūsų besirūpindamas gali pridėti uolektį savo ūgiui?'),
  (@b42, 12, 26, 'Tad jei nesate pajėgūs padaryti menkniekio, kodėl rūpinatės kitkuo?'),
  (@b42, 12, 27, 'Pasvarstykite apie lelijas, kaip jos auga: jos netriūsia, jos neverpia; tačiau jums sakau, kad Saliamonas visoje savo šlovėje nebuvo pasipuošęs kaip nei viena iš jų.'),
  (@b42, 12, 28, 'Tad jei Dievas taip aprengia žolę, kuri šiandien yra lauke, o rytoj įmetama į krosnį, tai kaip juo labiau aprengs jus, mažatikiai?'),
  (@b42, 12, 29, 'Ir neieškokite, ką valgysite ar ką gersite, nei nebūkite abejojančio proto.'),
  (@b42, 12, 30, 'Nes viso to ieško pasaulio tautos; o jūsų Tėvas žino, kad jums šito reikia.'),
  (@b42, 12, 31, 'Bet verčiau ieškokite Dievo karalystės; ir visa tai bus jums pridėta.'),
  (@b42, 12, 32, 'Nebijok, mažoji kaimene, nes tai jūsų Tėvo geras noras duoti jums karalystę.'),
  (@b42, 12, 33, 'Parduokite, ką turite, ir atiduokite išmaldai; pasirūpinkite krepšių, kurie nesensta, nenykstantį turtą danguose, kuris nežlunga, kur vagis neprieina nei kandys nesugadina.'),
  (@b42, 12, 34, 'Nes kur yra jūsų turtas, ten bus ir jūsų širdis.'),
  (@b42, 12, 35, 'Tebūna sujuostos jūsų strėnos ir jūsų žibintai degantys;'),
  (@b42, 12, 36, 'o jūs patys panašūs į žmones, kurie laukia savo viešpaties, kada jis grįš iš vestuvių; kad jam atėjus ir pasibeldus jie galėtų jam tuoj pat atidaryti.'),
  (@b42, 12, 37, 'Palaiminti tie tarnai, kuriuos atėjęs viešpats ras budinčius; iš tiesų sakau jums, kad jis susijuos ir susodins juos prie valgio, ir atėjęs jiems patarnaus.'),
  (@b42, 12, 38, 'Ir jeigu jis ateis antrame budėjime ar ateis trečiame budėjime ir taip juos ras, palaiminti yra tie tarnai.'),
  (@b42, 12, 39, 'Ir žinokite, kad, jei namų šeimininkas žinotų, kurią valandą ateis vagis, tai jis budėtų ir neleistų įsilaužti į savo namus.'),
  (@b42, 12, 40, 'Todėl ir jūs būkite pasiruošę, nes žmogaus Sūnus ateina tą valandą, kuomet jūs nemanote“.'),
  (@b42, 12, 41, 'Tada Petras jam tarė: „Viešpatie, ar mums kalbi šitą palyginimą, ar visiems?“'),
  (@b42, 12, 42, 'Ir Viešpats tarė: „Tad kas yra tas ištikimas ir išmintingas ūkvedys, kurį jo viešpats paskirs savo namiškių valdovu, duoti jiems skirtu laiku jų maisto dalį?'),
  (@b42, 12, 43, 'Palaimintas tas tarnas, kurį atėjęs jo viešpats ras taip darantį.'),
  (@b42, 12, 44, 'Iš tiesų sakau jums, kad jis paskirs jį valdovu visko, ką jis turi.'),
  (@b42, 12, 45, 'Bet jei tas tarnas sakys savo širdyje: ‘Mano viešpats delsia savo atėjimą’; ir pradės mušti tarnus bei tarnaites ir valgyti, gerti, ir girtuokliauti;'),
  (@b42, 12, 46, 'to tarno viešpats ateis tą dieną, kai jis jo nelaukia, ir tą valandą, kurią jis nesitiki, ir perkirs jį pusiau, ir jam paskirs jo dalį su netikinčiaisiais.'),
  (@b42, 12, 47, 'O tas tarnas, kuris žinojo savo viešpaties valią, bet nepasiruošė ir nei nedarė pagal jo valią, bus mušamas daugybe kirčių.'),
  (@b42, 12, 48, 'Bet tas, kuris nežinojo, o padarė tai, kas verta kirčių, bus mušamas keletu kirčių. Nes kam yra daug duota, iš to bus daug pareikalauta; ir kam daug patikėjo, iš to daugiau reikalaus.'),
  (@b42, 12, 49, 'Aš atėjau pasiųsti ugnį žemėje; ir ko norėčiau, jei ji jau būtų užsiliepsnojusi.'),
  (@b42, 12, 50, 'Bet aš turiu būti pakrikštytas krikštu; ir kaip esu suspaustas, kol tai bus įvykdyta!'),
  (@b42, 12, 51, 'Manote, kad atėjau duoti žemėje ramybę? Sakau jums: ne; verčiau pasidalijimą;'),
  (@b42, 12, 52, 'nes nuo šiol penki vienuose namuose bus pasidaliję, trys prieš du ir du prieš tris.'),
  (@b42, 12, 53, 'Tėvas bus pasidalijęs prieš sūnų, o sūnus prieš tėvą; motina prieš dukrą, o dukra prieš motiną; anyta prieš savo marčią, o marti prieš savo anytą“.'),
  (@b42, 12, 54, 'Ir jis taip pat tarė tautai: „Kai matote iš vakarų kylantį debesį, jūs tuojau sakote: ‘Ateina liūtis’; taip ir yra;'),
  (@b42, 12, 55, 'ir kai matote pučiant pietų vėją, jūs sakote: ‘Bus kaitra’; tai ir įvyksta.'),
  (@b42, 12, 56, 'Veidmainiai, jūs mokate atpažinti dangaus ir žemės veidą; bet kaip yra, kad neatpažįstate šio laiko?'),
  (@b42, 12, 57, 'Taip, ir kodėl iš savęs nenusprendžiate, kas yra teisinga?'),
  (@b42, 12, 58, 'Kai tu su savo priešininku eini pas valdytoją, dar būdamas kelyje pasistenk, kad galėtum išsivaduoti iš jo; idant jis nenusitemptų tavęs pas teisėją, o teisėjas neatiduotų tavęs pareigūnui, o pareigūnas neįmestų tavęs į kalėjimą.'),
  (@b42, 12, 59, 'Sakau tau: tu iš ten neišeisi, kol nesumokėsi iki paskutinės leptos“.'),
  (@b42, 13, 1, 'Tuo laiku buvo ten keli, kurie papasakojo jam apie galilėjiečius, kurių kraują Pilotas sumaišė su jų aukomis.'),
  (@b42, 13, 2, 'Ir Jėzus atsakydamas jiems tarė: „Manote, kad tie galilėjiečiai buvo didesni nusidėjėliai už visus galilėjiečius, kad tai kentėjo?'),
  (@b42, 13, 3, 'Sakau jums: ne; bet jei neatgailausite, jūs visi taip pat pražūsite.'),
  (@b42, 13, 4, 'Arba anie aštuoniolika, ant kurių užkrito Siloamo bokštas ir juos užmušė, manote, kad jie buvo didesni nusidėjėliai už visus Jeruzalėje gyvenančius žmones?'),
  (@b42, 13, 5, 'Sakau jums: ne; bet jei neatgailausite, jūs visi taip pat pražūsite“.'),
  (@b42, 13, 6, 'Jis taip pat pasakė šį palyginimą: „Vienas žmogus turėjo savo vynuogyne pasisodinęs figmedį; ir atėjęs jis ieškojo ant jo vaisiaus, bet nieko nerado.'),
  (@b42, 13, 7, 'Tuomet jis tarė savo vynuogininkui: ‘Štai šiuos trejus metus ateinu ieškodamas ant šio figmedžio vaisiaus ir nieko nerandu: nukirsk jį; kam jis apsunkina žemę?’'),
  (@b42, 13, 8, 'O jis atsakydamas jam tarė: ‘Viešpatie, palik jį dar ir šiuos metus, kol jį apkasiu ir apmėšluosiu;'),
  (@b42, 13, 9, 'ir jeigu jis duos vaisių, gerai; o jei ne, tai po to jį iškirsk’“.'),
  (@b42, 13, 10, 'Ir jis per sabatą mokė vienoje iš sinagogų.'),
  (@b42, 13, 12, 'Ir Jėzus ją pamatęs pasišaukė ir jai tarė: „Moterie, tu išlaisvinta iš savo negalios“.'),
  (@b42, 13, 13, 'Ir jis ant jos uždėjo savo rankas; ir tuoj pat ji tapo tiesi, ir šlovino Dievą.'),
  (@b42, 13, 14, 'O kadangi Jėzus išgydė sabato dieną, sinagogos valdovas atsakė su pasipiktinimu ir tarė tautai: „Yra šešios dienos, per kurias reikia dirbti; todėl per jas ateikite ir gydykitės, o ne per sabato dieną“.'),
  (@b42, 13, 15, 'Tada Viešpats jam atsakė, ir tarė: „Veidmainy, argi ne kiekvienas iš jūsų sabato dieną atriša savo jautį ar asilą nuo gardo ir nuveda jį pagirdyti?'),
  (@b42, 13, 16, 'Ir argi šios moters, esančios Abraomo dukterimi, kurią šėtonas laikė surišęs štai šiuos aštuoniolika metų, nereikėjo išlaisvinti iš šitų pančių sabato dieną?“'),
  (@b42, 13, 17, 'Ir kai jis tai pasakė, visi jo priešininkai susigėdo; o visa tauta džiaugėsi visais tais šlovingais jo padarytais dalykais.'),
  (@b42, 13, 18, 'Tada jis tarė: „Į ką yra panaši Dievo karalystė? Ir su kuo ją palyginsiu?'),
  (@b42, 13, 19, 'Ji panaši į garstyčios sėklos grūdą, kurį žmogus ėmė ir metė į savo daržą; ir jis užaugo ir tapo dideliu medžiu; ir oro skrajūnai apsigyveno jo šakose“.'),
  (@b42, 13, 20, 'Ir vėl jis tarė: „Kam aš prilyginsiu Dievo karalystę?'),
  (@b42, 13, 21, 'Ji panaši į raugą, kurį moteris ėmė ir paslėpė trijuose saikuose miltų, kol viskas įrūgo“.'),
  (@b42, 13, 22, 'Ir jis ėjo per miestus ir kaimus mokydamas ir keliaudamas Jeruzalės link.'),
  (@b42, 13, 23, 'Tada vienas jam tarė: „Viešpatie, ar maža bus išgelbėtųjų?“ O jis jiems tarė:'),
  (@b42, 13, 24, '„Stenkitės įeiti per siaurus vartus, nes sakau jums: daugelis stengsis įeiti ir nepajėgs.'),
  (@b42, 13, 25, 'Kai tik namų šeimininkas yra atsikėlęs ir užrakinęs duris, o jūs, stovėdami lauke pradedate belstis į duris, sakydami: ‘Viešpatie, Viešpatie, atidaryk mums’; o jis atsakys ir tars jums: ‘Nežinau jūsų, iš kur esate’;'),
  (@b42, 13, 26, 'tada pradėsite sakyti: ‘Mes valgėme ir gėrėme tavo akivaizdoje, ir tu mokei mūsų gatvėse’.'),
  (@b42, 13, 27, 'Bet jis tars: ‘Sakau jums: nežinau jūsų, iš kur esate; eikite nuo manęs jūs visi, neteisybės darytojai’.'),
  (@b42, 13, 28, 'Ten bus verksmas ir dantų griežimas, kai pamatysite Abraomą, Izaoką, Jokūbą ir visus pranašus Dievo karalystėje, o save pačius – išmestus laukan.'),
  (@b42, 13, 29, 'Ir jie ateis iš rytų, vakarų, iš šiaurės ir pietų, ir atsisės Dievo karalystėje.'),
  (@b42, 13, 30, 'Ir štai yra paskutiniai, kurie bus pirmi, ir yra pirmi, kurie bus paskutiniai“.'),
  (@b42, 13, 31, 'Tą pačią dieną atėjo kai kurie iš fariziejų, jam sakydami: „Eik laukan ir eik iš čia, nes Erodas tave nužudys“.'),
  (@b42, 13, 32, 'O jis jiems tarė: „Eikite ir pasakykite tam lapei: ‘Štai aš išvarinėju velnius ir gydau šiandien ir rytoj, o trečią dieną būsiu ištobulintas’.'),
  (@b42, 13, 33, 'Tačiau šiandien, rytoj ir poryt turiu vaikščioti, nes negali būti, kad pranašas pražūtų ne Jeruzalėje.'),
  (@b42, 13, 34, 'O Jeruzale, Jeruzale, kuri žudai pranašus ir užmėtai akmenimis tuos, kurie yra pas tave siųsti; kiek kartų norėjau surinkti tavo vaikus, kaip višta surenka savo jauniklius po savo sparnais, o jūs nenorėjote!'),
  (@b42, 13, 35, 'Štai jūsų namai yra paliekami jums apleisti; ir iš tiesų sakau jums: jūs manęs nematysite, kol ateis laikas, kai sakysite: ‘Palaimintas tas, kuris ateina Viešpaties vardu’“.'),
  (@b42, 13, 11, 'Ir štai ten buvo moteris, kuri aštuoniolika metų turėjo negalios dvasią ir buvo sulinkusi, ir jokiu būdu negalėjo išsitiesti.'),
  (@b42, 14, 1, 'Ir jam įėjus į vieno fariziejų vyriausiojo namus sabato dieną valgyti duonos, įvyko, kad jie stebėjo jį.'),
  (@b42, 14, 2, 'Ir štai ten priešais jį buvo vienas žmogus, sergantis vandenlige.'),
  (@b42, 14, 3, 'Ir Jėzus atsakydamas kalbėjo įstatymininkams ir fariziejams, sakydamas: „Ar teisėta gydyti sabato dieną?“'),
  (@b42, 14, 4, 'O jie tylėjo. Ir jis ėmė jį, išgydė ir paleido;'),
  (@b42, 14, 5, 'ir atsakė jiems, tardamas: „Kuris iš jūsų turės asilą arba jautį, įkritusį į duobę, ir tuojau jo neištrauks per sabato dieną?“'),
  (@b42, 14, 6, 'Ir jie negalėjo jam į tai atsakyti.'),
  (@b42, 14, 7, 'Ir jis pateikė palyginimą tiems, kurie buvo pakviesti, stebėdamas, kaip jie rinkosi pirmąsias vietas, sakydamas jiems:'),
  (@b42, 14, 8, '„Kai esi kieno nors pakviestas į vestuves, nesisėsk aukščiausioje vietoje; kad kartais nebūtų jo pakviestas už tave garbingesnis žmogus;'),
  (@b42, 14, 9, 'ir atėjęs tas, kuris tave ir jį pakvietė, netartų tau: ‘Užleisk šitam žmogui vietą’; ir tu susigėdęs turėsi sėstis į žemiausią vietą.'),
  (@b42, 14, 10, 'Bet kai esi pakviestas, eik ir sėskis žemiausioje vietoje; kad tas, kuris tave pakvietė, atėjęs galėtų tau pasakyti: ‘Drauge, palipk aukščiau’; tada tau bus garbė akivaizdoje tų, kurie sėdi su tavimi prie valgio.'),
  (@b42, 14, 11, 'Nes tas, kas save aukština, bus pažemintas; o tas, kas save žemina, bus išaukštintas“.'),
  (@b42, 14, 12, 'Tada jis tarė ir tam, kuris jį pakvietė: „Kai ruoši pietus ar vakarienę, nekviesk savo draugų nei savo brolių, nei savo giminaičių, nei savo turtingų kaimynų; kad jie savo ruožtu nepakviestų tavęs, ir tau nebūtų atlyginta.'),
  (@b42, 14, 13, 'Bet kai ruoši puotą, pasikviesk vargšų, luošių, raišų, aklų;'),
  (@b42, 14, 14, 'ir tu būsi palaimintas; nes jie negali tau atsilyginti; nes tau bus atlyginta teisiųjų prisikėlime.'),
  (@b42, 14, 15, 'Ir kai vienas iš sėdinčiųjų su juo prie valgio išgirdo tai, jis jam tarė: „Palaimintas tas, kuris valgys duoną Dievo karalystėje“.'),
  (@b42, 14, 16, 'Tada jis jam tarė: „Vienas žmogus paruošė didžiulę vakarienę ir pakvietė daugelį;'),
  (@b42, 14, 17, 'ir vakarienės metu siuntė savo tarną pasakyti pakviestiesiems: ‘Ateikite; nes viskas jau yra paruošta’.'),
  (@b42, 14, 18, 'Bet jie visi kaip vienas pradėjo atsiprašinėti. Pirmasis jam tarė: ‘Nusipirkau žemės gabalą ir turiu eiti, ir jį apžiūrėti; meldžiu tave, laikyk mane atsiprašiusiu’.'),
  (@b42, 14, 19, 'Ir kitas tarė: ‘Nusipirkau penkis jungus jaučių ir einu juos išbandyti; meldžiu tave, laikyk mane atsiprašiusiu’.'),
  (@b42, 14, 20, 'Ir kitas tarė: ‘Vedžiau žmoną, todėl negaliu ateiti’.'),
  (@b42, 14, 21, 'Taigi tarnas parėjo ir apsakė tai savo viešpačiui. Tada namų šeimininkas supykęs tarė savo tarnui: ‘Greitai išeik į miesto gatves bei gatveles ir atvesk čia vargšus, luošius, raišus ir akluosius’.'),
  (@b42, 14, 22, 'Ir tarnas tarė: ‘Viešpatie, kaip tu įsakei, yra padaryta, ir vis dar yra vietos’.'),
  (@b42, 14, 23, 'Ir viešpats tarė tarnui: ‘Išeik į vieškelius bei patvorius ir priversk juos įeiti, kad mano namai būtų pripildyti.'),
  (@b42, 14, 24, 'Nes sakau jums, kad nei vienas iš anų pakviestų žmonių neragaus mano vakarienės’“.'),
  (@b42, 14, 25, 'Ir su juo ėjo didžiulės minios; ir jis atsisuko ir jiems tarė:'),
  (@b42, 14, 26, '„Jei kas ateina pas mane ir nelaiko neapykantoje savo tėvo, motinos, žmonos, vaikų, brolių, seserų, taip, ir savo gyvybės, tas negali būti mano mokinys.'),
  (@b42, 14, 27, 'Ir kas neneša savo kryžiaus ir neseka paskui mane, negali būti mano mokinys.'),
  (@b42, 14, 28, 'Nes kas iš jūsų, norėdamas pastatyti bokštą, pirmiau nesėda ir nepaskaičiuoja išlaidų, ar jis turi pakankamai tam užbaigti?'),
  (@b42, 14, 29, 'Kad kartais, jam padėjus pamatą ir nepajėgus pabaigti, visi tai matydami nepradėtų iš jo tyčiotis,'),
  (@b42, 14, 30, 'sakydami: ‘Šis žmogus pradėjo statyti, bet nepajėgė užbaigti’.'),
  (@b42, 14, 31, 'Arba koks karalius, ruošdamasis kariauti prieš kitą karalių, pirmiau nesėda ir nepasitaria, ar jis pajėgus su dešimčia tūkstančių pasitikti tą, kuris ateina prieš jį su dvidešimčia tūkstančių?'),
  (@b42, 14, 32, 'Priešingu atveju, kol kitas dar toli, jis siunčia pasiuntinybę ir prašo taikos derybų.'),
  (@b42, 14, 33, 'Taip pat kiekvienas iš jūsų, kuris neatsižada viso, ką turi, negali būti mano mokinys.'),
  (@b42, 14, 34, 'Druska yra gerai, bet jei druska praranda savo skonį, kuo ją bepaskaninsi?'),
  (@b42, 14, 35, 'Ji nebetinka nei žemei, nei mėšlo krūvai; žmonės ją išmeta lauk. Kas turi ausis klausyti, tas teklauso“.'),
  (@b42, 15, 1, 'Tada prie jo prisiartino visi muitininkai ir nusidėjėliai jo paklausyti.'),
  (@b42, 15, 2, 'O fariziejai ir raštininkai murmėjo, sakydami: „Šitas priima nusidėjėlius ir valgo su jais“.'),
  (@b42, 15, 3, 'Ir jis kalbėjo jiems šitą palyginimą, sakydamas:'),
  (@b42, 15, 4, '„Jei kuris iš jūsų turėdamas šimtą avių praranda vieną iš jų, argi jis nepalieka devyniasdešimt devynių dykumoje ir neieško tos, kuri pražuvusi, kol ją suranda?'),
  (@b42, 15, 5, 'O kai suranda, su džiaugsmu ją užsideda sau ant pečių.'),
  (@b42, 15, 6, 'Ir kai pareina namo, pasišaukia savo draugus ir kaimynus, jiems sakydamas: ‘Džiaukitės su manimi, nes radau savo avį, kuri buvo pražuvusi’.'),
  (@b42, 15, 7, 'Sakau jums: taip pat ir danguje bus daugiau džiaugsmo dėl vieno nusidėjėlio, kuris atgailauja, negu dėl devyniasdešimt devynių teisiųjų asmenų, kuriems nereikia atgailavimo.'),
  (@b42, 15, 8, 'Arba jei kuri moteris, turėdama dešimt sidabrinių vieną pameta, ar neužsidega žvakės ir nešluoja namų, ir rūpestingai neieško, kol jį suranda?'),
  (@b42, 15, 9, 'Ir jį suradusi pasišaukia savo drauges ir kaimynes, sakydama: ‘Džiaukitės su manimi; nes suradau sidabrinį, kurį buvau pametusi’.'),
  (@b42, 15, 10, 'Sakau jums: lygiai taip pat dėl vieno atgailavusio nusidėjėlio yra džiaugsmo Dievo angelų akivaizdoje“.'),
  (@b42, 15, 11, 'Ir jis tarė: „Vienas žmogus turėjo du sūnus;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b42, 15, 12, 'ir jausnesnysis iš jų tarė savo tėvui: „Tėve, duok man atitenkančią turto dalį“. Ir jis padalino jiems savo pragyvenimą.'),
  (@b42, 15, 13, 'Ir po nedaugelio dienų, jaunesnysis sūnus viską susirinko ir leidosi kelionėn į tolimą šalį, ir ten palaidai gyvendamas iššvaistė savo turtą.'),
  (@b42, 15, 14, 'Ir kai jis viską išleido, toje šalyje kilo didžiulis badas; ir jis pradėjo stokoti.'),
  (@b42, 15, 15, 'Ir jis nuėjo ir prisijungė prie tos šalies piliečio; o tas pasiuntė jį į savo laukus kiaulių ganyti.'),
  (@b42, 15, 16, 'Ir jis geidė prikimšti savo pilvą žievėmis, kurias ėdė kiaulės; bet niekas jam nedavė.'),
  (@b42, 15, 17, 'Ir susiprotėjęs jis tarė: ‘Kiek mano tėvo samdinių turi užtektinai duonos ir dar atliekamos, o aš badu mirštu!'),
  (@b42, 15, 18, 'Kelsiuos, eisiu pas savo tėvą, ir jam sakysiu: Tėve, nusidėjau prieš dangų ir tavo akivaizdoje'),
  (@b42, 15, 19, 'ir nebesu vertas vadintis tavo sūnumi; laikyk mane kaip vieną iš savo samdinių’.'),
  (@b42, 15, 20, 'Ir jis pakilo ir atėjo pas savo tėvą. Bet jam dar toli esant, jo tėvas jį pamatė ir pasigailėjo, ir nubėgo, ir puolė jam ant kaklo, ir jį pabučiavo.'),
  (@b42, 15, 21, 'Ir sūnus jam tarė: ‘Tėve, nusidėjau prieš dangų ir tavo akyse ir nebesu vertas būti vadinamas tavo sūnumi’.'),
  (@b42, 15, 22, 'Bet tėvas tarė savo tarnams: ‘Išneškite geriausią drabužį ir apvilkite jį; ir užmaukite ant jo rankos žiedą ir batus ant jo kojų;'),
  (@b42, 15, 23, 'ir atveskite čia nupenėtą veršį ir papjaukite; ir valgykime bei linksminkimės,'),
  (@b42, 15, 24, 'nes šitas mano sūnus buvo miręs, bet vėl yra gyvas; jis buvo pražuvęs, bet atsirado’. Ir jie pradėjo linksmintis.'),
  (@b42, 15, 25, 'Na, o jo vyresnysis sūnus buvo ant lauko; ir jam ateinant bei artėjant prie namų, jis išgirdo muziką ir šokius.'),
  (@b42, 15, 26, 'Ir jis pašaukė vieną iš tarnų ir paklausė, ką tai reiškia.'),
  (@b42, 15, 27, 'Ir jis jam tarė: ‘Tavo brolis atėjo; ir tavo tėvas papjovė nupenėtą veršį, nes atgavo jį sveiką’.'),
  (@b42, 15, 28, 'Ir jis supyko ir nenorėjo įeiti; todėl jo tėvas išėjo ir jį prašė.'),
  (@b42, 15, 29, 'O jis atsakydamas tarė savo tėvui: ‘Štai šiuos daugelį metų tau tarnauju ir nei karto nenusižengiau tavo įsakymui; tačiau tu niekada nedavei man nei ožiuko, idant pasilinksminčiau su savo draugais;'),
  (@b42, 15, 30, 'bet kai tik grįžo šitas tavo sūnus, kuris prarijo tavo pragyvenimą su paleistuvėmis, tu jam papjovei nupenėtą veršį’.'),
  (@b42, 15, 31, 'O jis jam tarė: ‘Sūnau, tu visada esi su manimi, ir visa, ką aš turiu, yra tavo.'),
  (@b42, 15, 32, 'Derėjo, kad linksmintumės ir džiaugtumės, nes šis tavo brolis buvo miręs, bet vėl yra gyvas; buvo pražuvęs, bet atsirado’“.'),
  (@b42, 16, 1, 'Ir jis taip pat tarė savo mokiniams: „Buvo vienas turtingas žmogus, kuris turėjo ūkvedį; ir tas buvo jam apskųstas, kad išeikvojo jo turtą.'),
  (@b42, 16, 2, 'Ir jis pašaukė jį ir jam tarė: ‘Kaip yra, kad girdžiu tai apie tave? Duok savo ūkvedybos ataskaitą; nes tu ilgiau nebegali būti ūkvedys’.'),
  (@b42, 16, 3, 'Tada ūkvedys tarė savyje: ‘Ką aš darysiu? Nes mano viešpats atima iš manęs ūkvedybą; kasti aš negaliu, elgetauti man gėda.'),
  (@b42, 16, 4, 'Nusprendžiau, ką daryti, kad jie priimtų mane į savo namus, kai būsiu atleistas iš ūkvedybos’.'),
  (@b42, 16, 5, 'Taigi jis pakvietė visus savo viešpaties skolininkus ir tarė pirmajam: ‘Kiek esi skolingas mano viešpačiui?’'),
  (@b42, 16, 6, 'Ir jis tarė: ‘Šimtą saikų aliejaus’. O jis jam tarė: ‘Imk savo sąskaitą, greitai sėsk ir rašyk: penkiasdešimt’.'),
  (@b42, 16, 7, 'Tada jis kitam tarė: ‘O kiek tu skolingas?’ Ir jis tarė: ‘Šimtą saikų kviečių’. O jis tarė jam: ‘Imk savo sąskaitą ir rašyk: aštuoniasdešimt’.'),
  (@b42, 16, 8, 'Ir viešpats pagyrė neteisųjį ūkvedį, kad jis išmintingai pasielgė; nes šio pasaulio vaikai savo kartoje yra išmintingesni už šviesos vaikus.'),
  (@b42, 16, 9, 'Ir aš jums sakau: pasidarykite draugų iš neteisumo momonos; kad jums sužlugus jie priimtų jus į amžinąsias buveines.'),
  (@b42, 16, 10, 'Kas yra ištikimas mažiausiame dalyke, tas yra ištikimas ir dideliame; ir kas yra neteisus mažiausiame, tas yra neteisus ir dideliame.'),
  (@b42, 16, 11, 'Todėl jei nebuvote ištikimi neteisioje momonoje, kas jums patikės tikruosius turtus?'),
  (@b42, 16, 12, 'Ir jei nebuvote ištikimi tame, kas yra kito žmogaus, kas jums duos tai, kas yra jūsų pačių?'),
  (@b42, 16, 13, 'Joks tarnas negali tarnauti dviem šeimininkams; nes jis arba vieno nekęs, o kitą mylės; arba vieno laikysis, o kitą niekins. Jūs negalite tarnauti Dievui ir momonai“.'),
  (@b42, 16, 14, 'Ir fariziejai, kurie buvo godūs, taip pat girdėjo visa tai; ir jie išjuokė jį.'),
  (@b42, 16, 15, 'O jis jiems tarė: „Jūs esate tie, kurie patys save teisina žmonių akivaizdoje, bet Dievas žino jūsų širdis; nes tai, kas yra aukštinama tarp žmonių, Dievo akyse yra pasibjaurėjimas.'),
  (@b42, 16, 16, 'Įstatymas ir pranašai buvo iki Jono, nuo to laiko yra skelbiama Dievo karalystė, ir kiekvienas į ją veržiasi.'),
  (@b42, 16, 17, 'Ir lengviau yra dangui ir žemei praeiti, negu vienam įstatymo brūkšneliui iškristi.'),
  (@b42, 16, 18, 'Kas pašalina savo žmoną ir veda kitą, tas svetimauja; ir kas vyro pašalintąją veda, tas svetimauja.'),
  (@b42, 16, 19, 'Buvo vienas turtingas žmogus, kuris vilkėjo purpuru bei plona drobe ir kiekvieną dieną ištaigingai puotaudavo;'),
  (@b42, 16, 20, 'ir buvo vienas elgeta, vardu Lozorius, kuris gulėjo prie jo vartų aptekęs žaizdomis'),
  (@b42, 16, 21, 'ir trokšdamas pasimaitinti trupiniais, krentančiais nuo turtuolio stalo; dar daugiau: šunys ateidavo ir nulaižydavo jam žaizdas.'),
  (@b42, 16, 22, 'Ir įvyko, kad elgeta mirė ir buvo angelų nuneštas į Abraomo prieglobstį; mirė ir turtuolis ir buvo palaidotas;'),
  (@b42, 16, 23, 'ir pragare, būdamas kančiose, jis pakelia savo akis ir iš tolo mato Abraomą ir jo prieglobstyje – Lozorių.'),
  (@b42, 16, 24, 'Ir jis šaukė ir tarė: ‘Tėve Abraomai, pasigailėk manęs ir atsiųsk Lozorių, kad jis pavilgytų vandenyje savo piršto galą ir atvėsintų mano liežuvį; nes kankinuosi šioje liepsnoje’.'),
  (@b42, 16, 25, 'Bet Abraomas tarė: ‘Sūnau, prisimink, kad tu per savo gyvenimą gavai savo gėrybes, o Lozorius blogybes; bet dabar jis yra paguostas, o tu kankiniesi.'),
  (@b42, 16, 26, 'Ir prie viso to, tarp mūsų ir jūsų yra įtvirtinta didžiulė praraja; taip, kad tie, kurie nori iš čia pereiti pas jus, negali; nei iš ten norintys negali ateiti pas mus’.'),
  (@b42, 16, 27, 'Tada jis tarė: ‘Tad meldžiu tave, tėve, kad nusiųstum jį į mano tėvo namus;'),
  (@b42, 16, 28, 'nes turiu penkis brolius; kad jis jiems paliudytų, idant ir jie neateitų į šią kančios vietą’.'),
  (@b42, 16, 29, 'Abraomas jam sako: ‘Jie turi Mozę ir pranašus; tegul jų klauso’.'),
  (@b42, 16, 30, 'O jis tarė: ‘Ne, tėve Abraomai; bet jei kas iš numirusiųjų nueitų pas juos, jie atgailautų’.'),
  (@b42, 16, 31, 'Ir jis jam tarė: ‘Jeigu jie neklauso Mozės ir pranašų, tai jie nebus įtikinti, jei kas ir iš numirusiųjų prisikeltų’“.'),
  (@b42, 17, 1, 'Tada jis tarė mokiniams: „Neįmanoma, kad papiktinimai neateitų; bet vargas tam, per kurį jie ateina!'),
  (@b42, 17, 2, 'Jam geriau būtų, kad ant jo kaklo būtų užkabintas girnos akmuo, ir jis būtų įmestas į jūrą, negu kad jis papiktintų vieną iš šitų mažųjų.'),
  (@b42, 17, 3, 'Žiūrėkite savęs – jei tavo brolis nusižengia prieš tave, pabark jį; ir jei jis atgailauja, atleisk jam.'),
  (@b42, 17, 4, 'Ir jeigu jis nusižengtų prieš tave septynis kartus per dieną ir septynis kartus per dieną atsigręžtų į tave, sakydamas: ‘Atgailauju’, atleisk jam“.'),
  (@b42, 17, 5, 'Ir apaštalai tarė Viešpačiui: „Padidink mūsų tikėjimą“.'),
  (@b42, 17, 6, 'O Viešpats tarė: „Jei turėtumėte tikėjimą kaip garstyčios sėklos grūdelį, jūs pasakytumėte šitam šilkmedžiui: ‘Išsirauk su šaknimis ir pasisodink jūroje’, ir jis jūsų paklausytų.'),
  (@b42, 17, 7, 'Bet kuris iš jūsų, turėdamas ariantį ar galvijus ganantį tarną, jam grįžus iš lauko tuoj pat pasakys: ‘Eik ir sėsk prie valgio’?'),
  (@b42, 17, 8, 'Argi jis verčiau jam nesakys: ‘Paruošk ką nors man pavakarieniauti ir susijuosk, ir man patarnauk, kol pavalgysiu ir atsigersiu; o po to tu valgyk ir gerk’?'),
  (@b42, 17, 9, 'Argi jis dėkoja tam tarnui, kad jis atliko, kas buvo jam įsakyta? Nemanau.'),
  (@b42, 17, 10, 'Taip ir jūs, kai būsite atlikę visa tai, kas buvo jums įsakyta, sakykite: ‘Mes – nenaudingi tarnai; mes padarėme tai, ką privalėjome padaryti’“.'),
  (@b42, 17, 11, 'Ir įvyko, kad jam einant į Jeruzalę jis ėjo tarp Samarijos ir Galilėjos.'),
  (@b42, 17, 12, 'Ir jam įėjus į vieną kaimą, ten jį pasitiko dešimt raupsuotųjų vyrų, kurie stovėjo atokiai;'),
  (@b42, 17, 13, 'ir jie pakėlė savo balsus ir tarė: „Jėzau, Mokytojau, pasigailėk mūsų“.'),
  (@b42, 17, 14, 'Ir kai jis pamatė juos, jis jiems tarė: „Eikite, pasirodykite kunigams“. Ir įvyko, kad jiems beeinant jie buvo apvalyti.'),
  (@b42, 17, 15, 'Ir vienas iš jų, pamatęs, kad buvo išgydytas, sugrįžo ir garsiu balsu šlovino Dievą'),
  (@b42, 17, 16, 'ir dėkodamas jam parpuolė veidu žemyn prie jo kojų; ir jis buvo samarietis.'),
  (@b42, 17, 17, 'Ir Jėzus atsakydamas tarė: „Argi ne dešimt yra apvalytų? Bet kur yra devyni?'),
  (@b42, 17, 18, 'Neatsirado nei vieno, kuris būtų grįžęs atiduoti Dievui šlovę, išskyrus šitą svetimšalį“.'),
  (@b42, 17, 19, 'Ir jis tarė jam: „Kelkis, eik – tavo tikėjimas išgydė tave“.'),
  (@b42, 17, 20, 'Ir fariziejų paklaustas, kada ateis Dievo karalystė, jis jiems atsakydamas tarė: „Dievo karalystė neateina regimai;'),
  (@b42, 17, 21, 'ir nesakys: ‘Štai čia!’ arba ‘Štai ten!’, nes štai Dievo karalystė yra jumyse“.'),
  (@b42, 17, 22, 'Ir jis tarė mokiniams: „Ateis dienos, kai norėsite išvysti bent vieną iš žmogaus Sūnaus dienų, bet jos nepamatysite.'),
  (@b42, 17, 23, 'Ir sakys jums: ‘Štai čia’ arba, ‘Štai ten’; nesekiokite jų nei sekite jais.'),
  (@b42, 17, 24, 'Nes kaip žaibas, tvykstelėjęs iš vieno galo po dangumi, nušviečia iki kito galo po dangumi, taip bus ir žmogaus Sūnus savo dieną.'),
  (@b42, 17, 25, 'Bet pirmiau jis turi daug iškentėti ir būti šios kartos atmestas.'),
  (@b42, 17, 26, 'Ir kaip buvo Nojaus dienomis, taip bus ir žmogaus Sūnaus dienomis.'),
  (@b42, 17, 27, 'Jie valgė, gėrė, vedė žmonas ir tekėjo iki tos dienos, kai Nojus įžengė į arką, ir atėjo tvanas, ir juos visus sunaikino.'),
  (@b42, 17, 28, 'Taip pat, kaip buvo ir Loto dienomis: jie valgė, gėrė, pirko, pardavinėjo, sodino, statė;'),
  (@b42, 17, 29, 'bet tą pačią dieną, kai Lotas išėjo iš Sodomos, iš dangaus lijo ugnimi bei siera ir juos visus sunaikino.'),
  (@b42, 17, 30, 'Taip bus ir tą dieną, kai žmogaus Sūnus bus apreikštas.'),
  (@b42, 17, 31, 'Tą dieną, kas bus ant namo stogo, o jo daiktai name, tenelipa žemyn jų pasiimti; o tas, kuris yra ant lauko, taip pat tenegrįžta.'),
  (@b42, 17, 32, 'Prisiminkite Loto žmoną.'),
  (@b42, 17, 33, 'Kas sieks išgelbėti savo gyvybę, tas ją praras; o kas praras savo gyvybę, tas ją išsaugos.'),
  (@b42, 17, 34, 'Sakau jums: tą naktį bus du vienoje lovoje; vienas bus paimtas, o kitas paliktas.'),
  (@b42, 17, 35, 'Dvi mals kartu; viena bus paimta, o kita palikta.'),
  (@b42, 17, 36, 'Du bus ant lauko; vienas bus paimtas, o kitas paliktas“.'),
  (@b42, 17, 37, 'O jie atsakė ir tarė jam: „Kur, Viešpatie?“ Ir jis tarė jiems: „Kur yra kūnas, ten susirinks ir ereliai“.'),
  (@b42, 18, 1, 'Ir jis kalbėjo jiems palyginimą tuo tikslu, kad reikia visada melstis ir nepailsti;'),
  (@b42, 18, 2, 'sakydamas: „Mieste buvo teisėjas, kuris nebijojo Dievo ir nepaisė žmogaus;'),
  (@b42, 18, 3, 'ir tame mieste buvo našlė; ir ji atėjo pas jį, sakydama: ‘Atkeršyk už mane mano priešininkui’.'),
  (@b42, 18, 4, 'Ir jis kurį laiką nenorėjo; bet paskui jis kalbėjo savyje: ‘Nors nebijau Dievo ir nepaisau žmogaus,'),
  (@b42, 18, 5, 'tačiau, kadangi šita našlė man neduoda ramybės, aš atkeršysiu už ją, kad savo nuolatiniu atėjimu ji manęs nenuvargintų’“.'),
  (@b42, 18, 6, 'Ir Viešpats tarė: „Paklausykite, ką sako neteisusis teisėjas.'),
  (@b42, 18, 7, 'Ir argi Dievas neatkeršys už savo išrinktuosius, kurie dieną ir naktį jam šaukia, nors jis ir ilgai juos pakenčia?'),
  (@b42, 18, 8, 'Sakau jums, kad jis greitai už juos atkeršys. Tačiau kai ateis žmogaus Sūnus, ar jis beras žemėje tikėjimą?“'),
  (@b42, 18, 9, 'Ir tiems, kurie pasitikėjo savimi, kad yra teisūs, o kitus niekino, jis kalbėjo šitą palyginimą:'),
  (@b42, 18, 10, '„Du žmonės nuėjo aukštyn į šventyklą melstis; vienas – fariziejus, o kitas – muitininkas.'),
  (@b42, 18, 11, 'Fariziejus atsistojo ir taip savyje meldėsi: ‘Dieve, dėkoju tau, kad nesu kaip kiti žmonės – plėšikai, neteisūs, svetimautojai arba kaip ir šis muitininkas.'),
  (@b42, 18, 12, 'Aš pasninkauju dukart savaitėje, duodu dešimtinę iš visko, ką turiu’.'),
  (@b42, 18, 13, 'O muitininkas, stovėdamas atokiai, nenorėjo nei savo akių į dangų pakelti, bet mušėsi sau į krūtinę, sakydamas: ‘Dieve, būk gailestingas man, nusidėjėliui’.'),
  (@b42, 18, 14, 'Sakau jums: šitas nuėjo į savo namus išteisintas, o ne anas; nes kiekvienas, kuris save aukština, bus pažemintas; o tas, kuris save žemina, bus išaukštintas“.'),
  (@b42, 18, 15, 'Ir jie nešė pas jį ir kūdikius, kad jis juos paliestų: bet kai jo mokiniai tai pamatė, jie barė juos.'),
  (@b42, 18, 16, 'Bet Jėzus pasišaukė juos ir tarė: „Leiskite vaikeliams ateiti pas mane ir jiems nedrauskite, nes tokių yra Dievo karalystė.'),
  (@b42, 18, 17, 'Iš tiesų sakau jums: kas nepriims Dievo karalystės kaip vaikelis, tas niekaip į ją neįeis“.'),
  (@b42, 18, 18, 'Ir vienas valdovas jo paklausė, sakydamas: „Gerasis Mokytojau, ką turiu daryti, kad paveldėčiau amžinąjį gyvenimą?“'),
  (@b42, 18, 19, 'O Jėzus jam tarė: „Kodėl mane vadini geru? Nėra nei vieno gero, išskyrus vieną, tai yra Dievą.'),
  (@b42, 18, 20, 'Tu žinai įsakymus: ‘Nesvetimauk’, ‘Nežudyk’, ‘Nevok’, ‘Melagingai neliudyk’, ‘Gerbk savo tėvą ir motiną’“.'),
  (@b42, 18, 21, 'O jis tarė: „Visų šitų laikiausi nuo pat savo jaunystės“.'),
  (@b42, 18, 22, 'Tai išgirdęs Jėzus jam tarė: „Tačiau vieno tau trūksta: parduok viską, ką turi, ir išdalink vargšams, ir turėsi lobį danguje; ir ateik, sek paskui mane“.'),
  (@b42, 18, 23, 'Ir tai išgirdęs jis labai nuliūdo, nes buvo labai turtingas.'),
  (@b42, 18, 24, 'Ir pamatęs, kad jis labai nuliūdo, Jėzus tarė: „Kaip sunkiai tie, kurie turi turtų, įeis į Dievo karalystę!'),
  (@b42, 18, 25, 'Nes lengviau kupranugariui pralįsti pro adatos auselę, negu turtuoliui įeiti į Dievo karalystę“.'),
  (@b42, 18, 26, 'Ir tie, kurie tai išgirdo, tarė: „Kas tada gali būti išgelbėtas?“'),
  (@b42, 18, 27, 'Ir jis tarė: „Kas neįmanoma žmonėms, tai įmanoma Dievui“.'),
  (@b42, 18, 28, 'Tada Petras tarė: „Štai mes viską palikome ir sekėme paskui tave“.'),
  (@b42, 18, 29, 'Ir jis tarė jiems: „Iš tiesų sakau jums: nėra nei vieno, kuris paliko namus ar tėvus, ar brolius, ar žmoną, ar vaikus dėl Dievo karalystės'),
  (@b42, 18, 30, 'ir kuris negautų daugeriopai šiuo metu ir amžinojo gyvenimo ateinančiame pasaulyje“.'),
  (@b42, 18, 31, 'Tada jis pasiėmė dvylika ir jiems tarė: „Štai mes einame aukštyn į Jeruzalę, ir išsipildys viskas, kas pranašų parašyta apie žmogaus Sūnų.'),
  (@b42, 18, 32, 'Nes jis bus atiduotas pagonims, išjuoktas, paniekintas ir apspjaudytas;'),
  (@b42, 18, 33, 'ir jie nuplaks jį ir nužudys; o trečią dieną jis prisikels“.'),
  (@b42, 18, 34, 'Bet jie nieko iš to nesuprato; ir šitas pasakymas buvo jiems paslėptas, ir jie nežinojo, kas buvo pasakyta.'),
  (@b42, 18, 35, 'Ir įvyko, kad jam priartėjus prie Jericho, vienas neregys sėdėjo pakelėje elgetaudamas;'),
  (@b42, 18, 36, 'ir girdėdamas pro šalį einančią minią jis paklausė, ką tai reiškia.'),
  (@b42, 18, 37, 'Ir pasakė jam, kad pro šalį eina Jėzus iš Nazareto.'),
  (@b42, 18, 38, 'Ir jis šaukė, sakydamas: „Jėzau, Dovydo Sūnau, pasigailėk manęs“.'),
  (@b42, 18, 39, 'O priekyje einantys barė jį, kad jis tylėtų, bet jis dar labiau šaukė: „Dovydo Sūnau, pasigailėk manęs!“'),
  (@b42, 18, 40, 'Ir Jėzus sustojo ir įsakė, kad jis būtų pas jį atvestas; ir kai tas prisiartino, jis paklausė jo,'),
  (@b42, 18, 41, 'sakydamas: „Ką nori, kad tau padaryčiau?“ Ir jis tarė: „Viešpatie, kad praregėčiau“.'),
  (@b42, 18, 42, 'Ir Jėzus jam tarė: „Regėk – tavo tikėjimas tave išgelbėjo“.'),
  (@b42, 18, 43, 'Ir tuoj pat jis praregėjo ir sekė paskui jį, šlovindamas Dievą; ir visa tauta tai pamačiusi gyrė Dievą“.'),
  (@b42, 19, 1, 'Ir Jėzus įėjęs ėjo per Jerichą.'),
  (@b42, 19, 2, 'Ir štai buvo žmogus, vardu Zachiejus, kuris buvo vyriausiasis tarp muitininkų, ir buvo turtingas.'),
  (@b42, 19, 3, 'Ir jis siekė pamatyti Jėzų, kas jis esąs; bet dėl spūsties negalėjo, nes buvo mažo ūgio.'),
  (@b42, 19, 4, 'Ir užbėgęs į priekį jis įlipo į sikomoro medį, kad jį pamatytų; nes jis turėjo tuo keliu praeiti.'),
  (@b42, 19, 5, 'Ir kai Jėzus atėjo į tą vietą, jis pažiūrėjo į viršų, jį pamatė ir tarė jam: „Zachiejau, pasiskubink, nulipk; nes šiandien turiu apsistoti tavo namuose“.'),
  (@b42, 19, 6, 'Ir jis pasiskubino, nusileido ir su džiaugsmu priėmė jį.'),
  (@b42, 19, 7, 'Tai matydami, jie visi murmėjo, kalbėdami, kad „jis užėjo į svečius pas žmogų, kuris yra nusidėjėlis“.'),
  (@b42, 19, 8, 'Ir Zachiejus atsistojo ir tarė Viešpačiui: „Štai Viešpatie, pusę savo turto atiduodu vargšams; ir jei melagingai apkaltinęs ką nors paėmiau iš kokio žmogaus, grąžinsiu jam keturgubai“.'),
  (@b42, 19, 9, 'Ir Jėzus jam tarė: „Šią dieną į šiuos namus atėjo išgelbėjimas, kadangi ir jis yra Abraomo sūnus.'),
  (@b42, 19, 10, 'Nes žmogaus Sūnus atėjo ieškoti ir gelbėti to, kas buvo pražuvę“.'),
  (@b42, 19, 11, 'Ir jiems to besiklausant jis pridūrė, kalbėdamas palyginimą, kadangi jis buvo arti Jeruzalės, ir kadangi jie galvojo, jog Dievo karalystė turi tuoj pat pasirodyti.'),
  (@b42, 19, 12, 'Todėl jis tarė: „Vienas kilmingas žmogus išėjo į tolimą kraštą, kad gautų sau karalystę ir sugrįžtų.'),
  (@b42, 19, 13, 'Ir jis pašaukė savo dešimt tarnų ir davė jiems dešimt minų, ir tarė jiems: ‘Verskitės, kol sugrįšiu’.'),
  (@b42, 19, 14, 'Bet jo piliečiai jo nekentė ir nusiuntė jam iš paskos žinią, sakydami: ‘Mes nenorime, kad šitas mums karaliautų’.'),
  (@b42, 19, 15, 'Ir įvyko, kad, kai gavęs karalystę jis sugrįžo, tuomet jis įsakė, kad jam pakviestų tuos tarnus, kuriems jis buvo davęs pinigus, idant sužinotų, kiek kiekvienas versdamasis uždirbo.'),
  (@b42, 19, 16, 'Tada atėjo pirmasis, sakydamas: ‘Viešpatie, tavo mina uždirbo dešimt minų’.'),
  (@b42, 19, 17, 'Ir jis jam tarė: ‘Gerai, gerasis tarne; kadangi buvai ištikimas labai mažame dalyke, turėk valdžią dešimčiai miestų’.'),
  (@b42, 19, 18, 'Ir antrasis atėjo, sakydamas: ‘Viešpatie, tavo mina uždirbo penkias minas’.'),
  (@b42, 19, 19, 'Taip pat ir jam jis tarė: ‘Ir tu valdyk penkis miestus’.'),
  (@b42, 19, 20, 'Ir kitas atėjo, sakydamas: ‘Viešpatie, štai tavo mina, kurią laikiau suvyniojęs į servetėlę;'),
  (@b42, 19, 21, 'nes bijojau tavęs, kadangi esi griežtas žmogus: imi tai, ko nesi padėjęs, ir pjauni tai, ko nesėjai’.'),
  (@b42, 19, 22, 'Ir jis jam sako: ‘Iš tavo paties burnos aš tave teisiu, nedorasis tarne. Žinojai, kad esu griežtas žmogus, imantis tai, ko nepadėjau ir pjaunantis tai, ko nesėjau;'),
  (@b42, 19, 23, 'tad kodėl nedavei mano pinigų bankui, kad man atėjus būčiau pareikalavęs, kas mano, su palūkanomis?’'),
  (@b42, 19, 24, 'Ir jis tarė šalia stovintiems: ‘Atimkite iš jo miną ir duokite ją tam, kuris turi dešimt minų’'),
  (@b42, 19, 25, '(o jie tarė jam: ‘Viešpatie, jis turi dešimt minų’).'),
  (@b42, 19, 26, 'Nes sakau jums, kad kiekvienam, kuris turi, bus duota; o iš to, kuris neturi, bus atimta ir tai, ką jis turi.'),
  (@b42, 19, 27, 'O tuos mano priešus, nenorėjusius, kad jiems karaliaučiau, atveskite čia ir mano akivaizdoje užmuškite’“.'),
  (@b42, 19, 28, 'Ir taip pakalbėjęs jis nuėjo priekin, kildamas aukštyn į Jeruzalę.'),
  (@b42, 19, 29, 'Ir įvyko, kad jam priartėjus prie Betfagės ir Betanijos, prie vadinamo Alyvų kalno, jis pasiuntė du iš savo mokinių,'),
  (@b42, 19, 30, 'sakydamas: „Eikite į priešais jus esantį kaimą, į kurį įeidami rasite pririštą asiliuką, ant kurio niekada nėra sėdėjęs žmogus; atriškite jį ir atveskite čia.'),
  (@b42, 19, 31, 'O jei kas jūsų paklaustų: ‘Kodėl jį atrišate?’, taip jam sakykite: ‘Todėl, kad jo reikia Viešpačiui’.'),
  (@b42, 19, 32, 'Ir pasiųstieji nuėjo ir rado taip, kaip jis buvo jiems sakęs.'),
  (@b42, 19, 33, 'Ir jiems beatrišant asiliuką, jo šeimininkai jiems tarė: „Kodėl atrišate asiliuką?“'),
  (@b42, 19, 34, 'Ir jie tarė: „Viešpačiui jo reikia“.'),
  (@b42, 19, 35, 'Ir jie atvedė jį pas Jėzų; ir jie užmetė ant asiliuko savo drabužius ir ant jo jie užsodino Jėzų.'),
  (@b42, 19, 36, 'Ir jam einant, jie tiesė savo drabužius kelyje.'),
  (@b42, 19, 37, 'Ir jam priartėjus prie Alyvų kalno šlaito, visa mokinių minia pradėjo garsiu balsu džiūgauti ir girti Dievą už visus galingus darbus, kuriuos jie matė,'),
  (@b42, 19, 38, 'sakydami: „Tebūna palaimintas Karalius, kuris ateina Viešpaties vardu; ramybė danguje ir šlovė aukštybėse!“'),
  (@b42, 19, 39, 'Ir kai kurie fariziejai iš minios jam tarė: „Mokytojau, sudrausk savo mokinius“.'),
  (@b42, 19, 40, 'O jis atsakydamas tarė jiems: „Sakau tai jums: jei šitie tylės, tai akmenys tuoj pat šauks“.'),
  (@b42, 19, 41, 'Ir priartėjęs jis pažiūrėjo į miestą ir dėl jo verkė,'),
  (@b42, 19, 42, 'sakydamas: „Jei tu, būtent tu, bent šioje savo dienoje būtum žinojęs tai, kas skirta tavo ramybei! Bet dabar tai yra paslėpta nuo tavo akių.'),
  (@b42, 19, 43, 'Nes ateis ant tavęs dienos, kai tavo priešai apjuos tave apkasais ir apsups tave, ir suspaus tave iš visų pusių,'),
  (@b42, 19, 44, 'ir sulygins tave su žeme ir tavo vaikus tavyje; ir jie nepaliks tavyje akmens ant akmens; nes tu nepažinai savo aplankymo meto“.'),
  (@b42, 19, 45, 'Ir jis įėjo į šventyklą ir pradėjo varyti laukan joje pardavinėjančius ir perkančius,'),
  (@b42, 19, 46, 'sakydamas jiems: „Yra parašyta: ‘Mano namai yra maldos namai’; bet jūs pavertėte juos vagių lindyne“.'),
  (@b42, 19, 47, 'Ir jis kasdien mokė šventykloje. Bet vyriausieji kunigai, raštininkai ir tautos vyriausieji siekė jį sunaikinti,'),
  (@b42, 19, 48, 'bet negalėjo surasti, ką jie galėtų padaryti, nes visa tauta buvo labai prikibusi jo pasiklausyti.'),
  (@b42, 20, 1, 'Ir įvyko, kad vieną iš tų dienų, kai jis mokė tautą šventykloje ir skelbė evangeliją, prie jo atėjo vyriausieji kunigai ir raštininkai su vyresniaisiais'),
  (@b42, 20, 2, 'ir kalbėjo jam, sakydami: „Pasakyk mums, kokia valdžia tai darai, arba kas yra tas, kuris tau davė šitą valdžią?“'),
  (@b42, 20, 3, 'O jis atsakydamas tarė jiems: „Aš irgi paklausiu jūsų vieno dalyko; ir atsakykite man:'),
  (@b42, 20, 4, 'Jono krikštas – ar tai buvo iš dangaus, ar iš žmonių?“'),
  (@b42, 20, 5, 'Ir jie svarstė tarpusavyje, sakydami: „Jei sakysime: ‘Iš dangaus’, jis pasakys: ‘Tad kodėl juo netikėjote?’'),
  (@b42, 20, 6, 'Bet jei sakysime: ‘Iš žmonių’, visa tauta mus užmėtys akmenimis; nes jie įsitikinę, kad Jonas buvo pranašas“.'),
  (@b42, 20, 7, 'Ir jie atsakė, jog jie nežino, iš kur tai.'),
  (@b42, 20, 8, 'Ir Jėzus jiems tarė: „Tai nei aš jums nepasakysiu, kokia valdžia tai darau“.'),
  (@b42, 20, 9, 'Tada jis tautai pradėjo kalbėti šį palyginimą: „Vienas žmogus pasodino vynuogyną, išnuomojo jį žemdirbiams ir ilgam laikui išvyko į tolimą šalį.'),
  (@b42, 20, 10, 'O kai buvo metas, jis pasiuntė tarną pas žemdirbius, kad jie duotų jam iš vynuogyno vaisių; bet žemdirbiai jį primušė ir išsiuntė tuščiomis.'),
  (@b42, 20, 11, 'Ir jis vėl siuntė kitą tarną; tą jie irgi primušė ir gėdingai su juo pasielgė, ir išsiuntė jį tuščiomis.'),
  (@b42, 20, 12, 'Ir jis vėl siuntė trečią; ir jį taip pat jie sužeidė ir išmetė laukan.'),
  (@b42, 20, 13, 'Tada vynuogyno viešpats tarė: ‘Ką man daryti? Aš siųsiu savo mylimąjį sūnų: galbūt jį pamatę jie jį gerbs’.'),
  (@b42, 20, 14, 'Bet kai žemdirbiai jį pamatė, jie tarpusavyje samprotavo, sakydami: ‘Šitas yra paveldėtojas: eime, užmuškime jį, kad paveldas būtų mūsų’.'),
  (@b42, 20, 15, 'Tad jie išmetė jį iš vynuogyno ir užmušė. Ką gi jiems darys vynuogyno viešpats?'),
  (@b42, 20, 16, 'Jis ateis ir sunaikins tuos žemdirbius, ir atiduos vynuogyną kitiems“. Ir kai jie tai išgirdo, jie tarė: „Apsaugok Dieve!“'),
  (@b42, 20, 17, 'Ir jis į juos pažiūrėjęs tarė: „Kas gi tuomet tai, kas parašyta: ‘Akmuo, kurį statytojai atmetė, tapo kertės pagrindu’?'),
  (@b42, 20, 18, 'Kas kris ant šito akmens, tas susidaužys; bet ant ko jis užkris, tą sutrins į miltus“.'),
  (@b42, 20, 19, 'Ir vyriausieji kunigai bei raštininkai tą pačią valandą ieškojo, kad prie jo pridėtų rankas; ir jie bijojo tautos, nes jie suprato, kad jis kalbėjo šitą palyginimą prieš juos.'),
  (@b42, 20, 20, 'Ir jie stebėjo jį ir išsiuntė šnipus, kurie apsimestų teisiais, kad nutvertų jo žodžius, idant jie taip galėtų jį atiduoti valdytojo galiai ir valdžiai.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b42, 20, 21, 'Ir jie paklausė jo, sakydami: „Mokytojau, žinome, kad sakai ir mokai teisingai, ir neatsižvelgi į asmenis, bet tikrai mokai Dievo kelio;'),
  (@b42, 20, 22, 'ar teisėta mums duoti duoklę ciesoriui, ar ne?“'),
  (@b42, 20, 23, 'Bet jis suprato jų klastą ir jiems tarė: „Kodėl mane gundote?'),
  (@b42, 20, 24, 'Parodykite man denarą. Kieno atvaizdą ir užrašą jis turi?“ Jie atsakydami tarė: „Ciesoriaus“.'),
  (@b42, 20, 25, 'Ir jis tarė jiems: „Todėl kas yra ciesoriaus, atiduokite ciesoriui, o kas Dievo – Dievui“.'),
  (@b42, 20, 26, 'Ir jie negalėjo tautos akivaizdoje nutverti jo žodžių; ir jie stebėjosi jo atsakymu ir nutilo.'),
  (@b42, 20, 27, 'Tada pas jį atėjo kai kurie iš sadukiejų, kurie neigia, kad yra prisikėlimas; ir jie paklausė jo,'),
  (@b42, 20, 28, 'sakydami: „Mokytojau, Mozė mums parašė: ‘jei kieno brolis miršta turėdamas žmoną, ir jis miršta be vaikų, tai jo brolis turi imti jo žmoną ir prikelti savo broliui sėklą’.'),
  (@b42, 20, 29, 'Taigi buvo septyni broliai; ir pirmasis ėmė žmoną ir mirė be vaikų.'),
  (@b42, 20, 30, 'Ir antrasis ėmė ją į žmonas, ir jis mirė bevaikis.'),
  (@b42, 20, 31, 'Ir trečiasis ėmė ją; ir taip pat tie septyni; ir jie, nepalikę vaikų, mirė.'),
  (@b42, 20, 32, 'Paskutinė iš visų mirė ir moteris.'),
  (@b42, 20, 33, 'Taigi kieno iš jų žmona ji bus prisikėlime? Nes septyni turėjo ją už žmoną“.'),
  (@b42, 20, 34, 'O Jėzus atsakydamas jiems tarė: „Šio pasaulio vaikai veda ir išteka;'),
  (@b42, 20, 35, 'bet tie, kurie bus laikomi vertais įsigyti aną pasaulį ir prisikėlimą iš numirusiųjų, nei ves, nei tekės;'),
  (@b42, 20, 36, 'jie nebegali ir mirti, nes jie yra lygūs angelams; ir yra Dievo vaikai, būdami prisikėlimo vaikais.'),
  (@b42, 20, 37, 'Na, o kad mirusieji prikeliami, ir Mozė nurodė prie krūmo, kai jis vadina Viešpatį Abraomo Dievu, Izaoko Dievu ir Jokūbo Dievu.'),
  (@b42, 20, 38, 'Nes jis nėra mirusiųjų Dievas, bet gyvųjų; nes visi jam gyvena“.'),
  (@b42, 20, 39, 'Tada kai kurie iš raštininkų atsakydami tarė: „Mokytojau, tu gerai pasakei“.'),
  (@b42, 20, 40, 'Ir po to jie nedrįso jo nieko klausti.'),
  (@b42, 20, 41, 'Ir jis tarė jiems: „Kaipgi jie sako, kad Kristus yra Dovydo sūnus?'),
  (@b42, 20, 42, 'Ir pats Dovydas Psalmių knygoje sako: ‘VIEŠPATS tarė mano Viešpačiui: sėskis mano dešinėje,'),
  (@b42, 20, 43, 'kol padarysiu tavo priešus tavo pakoju’.'),
  (@b42, 20, 44, 'Taigi Dovydas vadina jį Viešpačiu; tad kaipgi jis yra jo sūnus?“'),
  (@b42, 20, 45, 'Tada, visai tautai besiklausant, jis tarė savo mokiniams:'),
  (@b42, 20, 46, '„Saugokitės raštininkų, kurie trokšta vaikščioti ilgais drabužiais, mėgsta sveikinimus turguose, aukščiausius krėslus sinagogose ir viršiausias vietas puotose;'),
  (@b42, 20, 47, 'kurie suryja našlių namus, o dėl akių atlieka ilgas maldas: jie gaus didesnį pasmerkimą“.'),
  (@b42, 21, 1, 'Ir jis pažvelgė ir pamatė turtuolius, metančius savo dovanas į iždinę.'),
  (@b42, 21, 2, 'Ir taip pat jis pamatė vieną vargšę našlę, įmetančią ten dvi leptas.'),
  (@b42, 21, 3, 'Ir jis tarė: „Iš tiesų sakau jums, kad ši vargšė našlė įmetė daugiau už juos visus;'),
  (@b42, 21, 4, 'nes visi tie iš savo pertekliaus įmetė Dievo atnašoms, bet ji iš savo skurdo įmetė visą pragyvenimą, kurį ji turėjo“.'),
  (@b42, 21, 5, 'Ir kai kuriems kalbant apie šventyklą, kaip ji yra išpuošta gražiais akmenimis ir dovanomis, jis tarė:'),
  (@b42, 21, 6, '„Ateis dienos, kai iš to, ką matote, neliks akmens ant akmens, kuris nebūtų nugriautas“.'),
  (@b42, 21, 7, 'Ir jie klausė jo, sakydami: „Mokytojau, bet kada tai bus? Ir koks bus ženklas, kai tai įvyks?“'),
  (@b42, 21, 8, 'Ir jis tarė: „Žiūrėkite, kad nebūtumėte suklaidinti, nes daugelis ateis mano vardu, sakydami: ‘Aš esu Kristus’ ir: ‘Laikas artėja’; todėl neikite paskui juos.'),
  (@b42, 21, 9, 'Bet kai išgirsite apie karus ir sąmyšius, nesibaisėkite, nes tai turi pirmiau įvykti; bet galas dar negreit“.'),
  (@b42, 21, 10, 'Tada jis tarė jiems: „Tauta sukils prieš tautą ir karalystė prieš karalystę;'),
  (@b42, 21, 11, 'ir įvairiose vietose bus didelių žemės drebėjimų, badmečių ir marų; ir iš dangaus bus baisūs reginiai ir dideli ženklai.'),
  (@b42, 21, 12, 'Bet pirmiau visų šitų, pridės prie jūsų rankas, persekios jus, atiduodami sinagogoms ir į kalėjimus, dėl mano vardo atvestus pas karalius ir valdovus.'),
  (@b42, 21, 13, 'Ir tai jums pasitarnaus liudijimui.'),
  (@b42, 21, 14, 'Todėl dėkitės į širdis iš anksto negalvoti, ką turėsite atsakyti;'),
  (@b42, 21, 15, 'nes aš jums duosiu burną ir išmintį, kuriai nepajėgs prieštarauti ir priešintis nei vienas jūsų priešininkas.'),
  (@b42, 21, 16, 'Ir jus išdavinės gimdytojai, broliai, giminaičiai ir draugai; ir padarys, kad kai kurie iš jūsų būtumėte nužudyti.'),
  (@b42, 21, 17, 'Ir dėl mano vardo būsite visų nekenčiami.'),
  (@b42, 21, 18, 'Bet nuo jūsų galvos neprapuls nei vienas plaukas.'),
  (@b42, 21, 19, 'Savo kantrumu valdykite savo sielas.'),
  (@b42, 21, 20, 'Ir kai pamatysite Jeruzalę apsuptą kariuomenių, tada žinokite, kad jos suniokojimas arti.'),
  (@b42, 21, 21, 'Tada tie, kurie yra Judėjoje, tebėga į kalnus; ir tie, kurie yra jos viduryje, teišeina lauk; ir tie, kurie yra apylinkėse, teneina į ją.'),
  (@b42, 21, 22, 'Nes šitos bus keršto dienos, kad išsipildytų viskas, kas užrašyta.'),
  (@b42, 21, 23, 'Bet vargas nėščioms ir žindančioms tomis dienomis! Nes šalyje bus didis sielvartas ir rūstybė šitai tautai.'),
  (@b42, 21, 24, 'Ir jie kris nuo kalavijo ašmenų ir bus vedami į nelaisvę į visas tautas; ir Jeruzalė bus pagonių trypiama, kol išsipildys pagonių laikai.'),
  (@b42, 21, 25, 'Ir bus ženklų saulėje, mėnulyje ir žvaigždėse; ir žemėje tautų sielvartas su suglumimu; jūros ir bangų ūžimas;'),
  (@b42, 21, 26, 'žmonių širdys nusilps dėl baimės ir belaukiant dalykų, ateisiančių ant žemės; nes dangaus jėgos bus sudrebintos.'),
  (@b42, 21, 27, 'Ir tada jie pamatys žmogaus Sūnų, ateinantį debesyje su jėga ir didžia šlove.'),
  (@b42, 21, 28, 'Ir kai tie dalykai pradės pildytis, tada žiūrėkite aukštyn ir pakelkite savo galvas; nes artinasi jūsų atpirkimas“.'),
  (@b42, 21, 29, 'Ir jis kalbėjo jiems palyginimą: „Žiūrėkite į figmedį ir visus medžius:'),
  (@b42, 21, 30, 'kai jie jau išsprogsta, patys matote ir žinote, kad vasara jau visai čia pat.'),
  (@b42, 21, 31, 'Taip ir jūs, kai matysite tai vykstant, žinokite, kad Dievo karalystė visai čia pat.'),
  (@b42, 21, 32, 'Iš tiesų sakau jums: ši karta nepraeis iki viskas išsipildys.'),
  (@b42, 21, 33, 'Dangus ir žemė praeis, bet mano žodžiai nepraeis.'),
  (@b42, 21, 34, 'Ir žiūrėkite savęs, kad kokiu metu jūsų širdys nebūtų apsunkintos persisotinimo, girtavimo ir šio gyvenimo rūpesčių, kad toji diena neužeitų ant jūsų netikėtai.'),
  (@b42, 21, 35, 'Nes kaip žabangos ji ateis ant visų gyvenančių ant visos žemės paviršiaus.'),
  (@b42, 21, 36, 'Todėl budėkite ir visuomet melskitės, kad būtumėte palaikyti vertais išvengti viso to, kas įvyks, ir stovėti žmogaus Sūnaus akivaizdoje“.'),
  (@b42, 21, 37, 'Ir dienos metu jis mokydavo šventykloje; o naktį jis išeidavo ir apsistodavo kalne, vadinamame Alyvų.'),
  (@b42, 21, 38, 'Ir visa tauta anksti ryte ateidavo pas jį į šventyklą jo pasiklausyti.'),
  (@b42, 22, 1, 'Artėjo gi Neraugintos duonos šventė, kuri yra vadinama Apėjimu.'),
  (@b42, 22, 2, 'Ir vyriausieji kunigai bei raštininkai ieškojo, kaip galėtų jį užmušti; nes jie bijojo tautos.'),
  (@b42, 22, 3, 'Tada šėtonas įėjo į Judą, pravarde Iskariotas, esantį iš dvylikos skaičiaus.'),
  (@b42, 22, 4, 'Ir jis nuėjo ir kalbėjo su vyriausiais kunigais ir vadais, kaip jis jiems galėtų jį išduoti.'),
  (@b42, 22, 5, 'Ir jie apsidžiaugė ir sutarė duoti jam pinigų.'),
  (@b42, 22, 6, 'Ir jis pažadėjo ir ieškojo progos jiems jį išduoti ne prie minios.'),
  (@b42, 22, 7, 'Tada atėjo Neraugintos duonos diena, kada turėjo būti užmušamas Apėjimas.'),
  (@b42, 22, 8, 'Ir jis išsiuntė Petrą bei Joną, sakydamas: „Eikite ir paruoškite mums Apėjimą, kad galėtume valgyti“.'),
  (@b42, 22, 9, 'Ir jie tarė jam: „Kur nori, kad paruoštume?“'),
  (@b42, 22, 10, 'Ir jis tarė jiems: „Štai jums įėjus į miestą jus pasitiks žmogus, nešinas vandens ąsočiu; sekite paskui jį į tą namą, į kurį jis įeis.'),
  (@b42, 22, 11, 'Ir sakysite namo šeimininkui: ‘Mokytojas tau sako: kur yra svečių kambarys, kur valgysiu Apėjimą su savo mokiniais?’'),
  (@b42, 22, 12, 'Ir jis parodys jums didelį apstatytą aukštutinį kambarį, ten paruoškite“.'),
  (@b42, 22, 13, 'Ir jie nuėjo ir rado taip, kaip jis buvo jiems sakęs; ir jie paruošė Apėjimą.'),
  (@b42, 22, 14, 'Ir atėjus valandai, jis sėdosi, ir su juo – dvylika apaštalų.'),
  (@b42, 22, 15, 'Ir jis tarė jiems: „Trokšte troškau su jumis valgyti šį Apėjimą pirmiau nei kentėsiu;'),
  (@b42, 22, 16, 'nes jums sakau: nebevalgysiu jo, iki jis išsipildys Dievo karalystėje“.'),
  (@b42, 22, 17, 'Ir jis paėmė taurę, padėkojo ir tarė: „Imkite tai ir pasidalinkite tarpusavyje;'),
  (@b42, 22, 18, 'nes sakau jums: negersiu iš vynmedžio vaisiaus, kol neateis Dievo karalystė“.'),
  (@b42, 22, 19, 'Ir jis paėmė duoną ir padėkojo, ir ją laužė, ir davė jiems, sakydamas: „Tai yra mano kūnas, kuris atiduodamas už jus: tai darykite mano atminimui“.'),
  (@b42, 22, 20, 'Taip pat ir taurę po vakarienės, sakydamas: „Ši taurė – naujas testamentas mano kraujyje, kuris už jus išliejamas.'),
  (@b42, 22, 21, 'Bet štai, mane išduodančiojo ranka yra su manimi ant stalo.'),
  (@b42, 22, 22, 'Ir iš tiesų žmogaus Sūnus eina, kaip buvo nulemta; bet vargas tam žmogui, per kurį jis yra išduotas!“'),
  (@b42, 22, 23, 'Ir jie pradėjo tarpusavyje klausinėti, kas gi iš jų yra tas, kuris tai padarys.'),
  (@b42, 22, 24, 'Ir tarp jų taip pat kilo ginčas, kuris iš jų turėtų būti laikomas didžiausiu.'),
  (@b42, 22, 25, 'O jis jiems tarė: „Pagonių karaliai jiems viešpatauja; ir tie, kurie juos valdo, yra vadinami geradariais.'),
  (@b42, 22, 26, 'Bet jūs nebūkite tokie; bet kas tarp jūsų didžiausias, tebūna kaip jauniausias; o vyriausias – kaip tas, kuris tarnauja.'),
  (@b42, 22, 27, 'Nes kas yra didesnis: ar tas, kuris sėdi prie valgio, ar tas, kuris patarnauja? Argi ne tas, kuris sėdi prie valgio? Bet aš esu tarp jūsų kaip tas, kuris patarnauja.'),
  (@b42, 22, 28, 'Jūs esate tie, kurie pasilikote su manimi mano pagundose.'),
  (@b42, 22, 29, 'Ir aš skiriu jums karalystę, kaip mano Tėvas man paskyrė;'),
  (@b42, 22, 30, 'kad valgytumėte ir gertumėte už mano stalo mano karalystėje ir sėdėtumėte sostuose, teisdami dvylika Izraelio genčių“.'),
  (@b42, 22, 31, 'Ir Viešpats tarė: „Simonai, Simonai, štai šėtonas geidė jūsų, kad persijotų jus kaip kviečius;'),
  (@b42, 22, 32, 'bet aš meldžiausi už tave, kad tavo tikėjimas nesiliautų; ir kai tu būsi atsivertęs, sustiprink savo brolius“.'),
  (@b42, 22, 33, 'Ir jis tarė jam: „Viešpatie, aš pasiruošęs eiti su tavimi į kalėjimą ir į mirtį“.'),
  (@b42, 22, 34, 'O jis tarė: „Sakau tau, Petrai, šią dieną, dar prieš gaidžiui pragystant, tu triskart išsiginsi, kad mane pažįsti“.'),
  (@b42, 22, 35, 'Ir jis tarė jiems: „Kai jus siunčiau be piniginės, be kelionmaišio ir be batų, ar jums ko trūko?“ Ir jie tarė: „Nieko“.'),
  (@b42, 22, 36, 'Tada jis tarė jiems: „Bet dabar, kas turi piniginę, tepasiima ją, taip pat ir savo kelionmaišį; o kas neturi kalavijo, teparduoda savo drabužį ir jį tenusiperka.'),
  (@b42, 22, 37, 'Nes sakau jums, kad tai, kas parašyta, dar turi išsipildyti manyje: ‘Ir jis buvo priskaitytas tarp pažeidėjų’; nes tai, kas apie mane, turi pabaigą“.'),
  (@b42, 22, 38, 'Ir jie tarė: „Viešpatie, štai, čia yra du kalavijai“. Ir jis tarė jiems: „Pakanka“.'),
  (@b42, 22, 39, 'Ir jis išėjo ir, kaip buvo įpratęs, ėjo į Alyvų kalną; taip pat ir jo mokiniai sekė jį.'),
  (@b42, 22, 40, 'Ir kai jis buvo toje vietoje, jis tarė jiems: „Melskitės, kad nepatektumėte į pagundą“.'),
  (@b42, 22, 41, 'Ir jis buvo atsitraukęs nuo jų maždaug per akmens metimą ir atsiklaupęs meldėsi,'),
  (@b42, 22, 42, 'sakydamas: „Tėve, jei nori, paimk nuo manęs šitą taurę; tačiau ne mano, bet tavo valia tebūna įvykdyta“.'),
  (@b42, 22, 43, 'Ir jam pasirodė iš dangaus angelas, jį sustiprindamas.'),
  (@b42, 22, 44, 'Ir būdamas agonijoje jis dar uoliau meldėsi; ir jo prakaitas buvo kaip dideli kraujo lašai, krentantys ant žemės.'),
  (@b42, 22, 45, 'Ir kai jis pakilo nuo maldos ir atėjo pas savo mokinius, jis rado juos iš liūdesio miegančius'),
  (@b42, 22, 46, 'ir tarė jiems: „Kodėl miegate? Kelkitės ir melskitės, kad neįeitumėte į pagundą“.'),
  (@b42, 22, 47, 'Ir jam dar bekalbant, štai minia ir vienas iš dvylikos, kurį vadino Judu, ėjo priekyje jų ir prisiartino prie Jėzaus jo pabučiuoti.'),
  (@b42, 22, 48, 'Bet Jėzus jam tarė: „Judai, tu pabučiavimu išduodi žmogaus Sūnų?“'),
  (@b42, 22, 49, 'Tie, kurie buvo aplink jį, pamatę, kas bus, tarė jam: „Viešpatie, ar mums kirsti kalaviju?“'),
  (@b42, 22, 50, 'Ir vienas iš jų kirto aukščiausiojo kunigo tarnui ir nupjovė jo dešinę ausį.'),
  (@b42, 22, 51, 'Ir Jėzus atsakydamas tarė: „Leiskite kol kas“. Ir jis palietė jo ausį ir jį išgydė.'),
  (@b42, 22, 52, 'Tada Jėzus tarė vyriausiems kunigams, šventyklos vadams ir vyresniesiems, kurie buvo pas jį atėję: „Kaip prieš vagį išėjote su kalavijais ir lazdomis?'),
  (@b42, 22, 53, 'Kai kasdien buvau su jumis šventykloje, jūs neištiesėte rankų prieš mane; bet šita yra jūsų valanda ir tamsos valdžia.“'),
  (@b42, 22, 54, 'Tada jie suėmė jį ir nusivedę atvedė į aukščiausiojo kunigo namus. O Petras sekė iš tolo.'),
  (@b42, 22, 55, 'Ir rūmų viduryje jiems užkūrus ugnį ir kartu susėdus, tarp jų atsisėdo Petras.'),
  (@b42, 22, 56, 'Bet viena tarnaitė pamatė jį sėdintį prie ugnies ir į jį įsižiūrėjusi tarė: „Šis žmogus irgi buvo su juo“.'),
  (@b42, 22, 57, 'Ir jis išsigynė jo, sakydamas: „Moterie, aš jo nepažįstu“.'),
  (@b42, 22, 58, 'O po kiek laiko kitas jį pamatė ir tarė: „Tu irgi esi iš jų“. Ir Petras tarė: „Žmogau, aš nesu“.'),
  (@b42, 22, 59, 'Ir kažkur po valandos kitas įsitikinęs patvirtino, sakydamas: „Tikrai, šitas irgi buvo su juo, nes jis yra galilėjietis“.'),
  (@b42, 22, 60, 'Bet Petras tarė: „Žmogau, nežinau, ką sakai“. Ir tuoj pat, jam dar bekalbant, pragydo gaidys.'),
  (@b42, 22, 61, 'Ir Viešpats atsisuko ir pažiūrėjo į Petrą. Ir Petras prisiminė Viešpaties žodį, kaip jis jam sakė: „Prieš gaidžiui pragystant tu triskart manęs išsiginsi“.'),
  (@b42, 22, 62, 'Ir Petras išėjo laukan ir karčiai verkė.'),
  (@b42, 22, 63, 'Ir vyrai, kurie laikė Jėzų, iš jo tyčiojosi ir jį mušė.'),
  (@b42, 22, 64, 'Ir uždengę jam akis, jie trenkė jam į veidą ir klausė jo, sakydami: „Pranašauk, kas tas, kuris tau trenkė?“'),
  (@b42, 22, 65, 'Ir daug kitko piktžodžiaudami jie kalbėjo prieš jį.'),
  (@b42, 22, 66, 'Ir vos tik išaušo diena, susirinko tautos vyresnieji, vyriausieji kunigai ir raštininkai ir atvedė jį į savo tarybą, sakydami:'),
  (@b42, 22, 67, '„Ar tu esi Kristus? Pasakyk mums“. Ir jis tarė jiems: „Jei jums pasakysiu, netikėsite;'),
  (@b42, 22, 68, 'ir jei aš jūsų paklausiu, jūs man neatsakysite ir manęs nepaleisite.'),
  (@b42, 22, 69, 'Nuo šiol žmogaus Sūnus sėdės Dievo galios dešinėje“.'),
  (@b42, 22, 70, 'Tada jie visi tarė: „Tad ar tu Dievo Sūnus?“ O jis jiems tarė: „Jūs sakote, kad esu“.'),
  (@b42, 22, 71, 'Ir jie tarė: „Kam mums bereikia tolimesnio liudijimo? Nes mes patys išgirdome iš jo burnos“.'),
  (@b42, 23, 1, 'Ir visa jų minia pakilo ir nuvedė jį pas Pilotą.'),
  (@b42, 23, 2, 'Ir jie pradėjo jį kaltinti, sakydami: „Mes radome, kad šitas iškreipia tautą ir draudžia duoti duoklę ciesoriui, sakydamas, kad jis pats yra Kristus karalius“.'),
  (@b42, 23, 3, 'Ir Pilotas paklausė jo, sakydamas: „Ar tu žydų Karalius?“ Ir jis atsakė jam ir tarė: „Tu tai sakai“.'),
  (@b42, 23, 4, 'Tada Pilotas tarė vyriausiems kunigams ir tautai: „Nerandu jokios kaltės šiame žmoguje“.'),
  (@b42, 23, 5, 'Ir jie dar labiau įniršo, sakydami: „Jis kursto tautą, mokydamas visoje Žydijoje, pradedant nuo Galilėjos iki šios vietos“.'),
  (@b42, 23, 6, 'Kai Pilotas išgirdo apie Galilėją, jis paklausė, ar tas žmogus yra galilėjietis.'),
  (@b42, 23, 7, 'Ir vos tik sužinojęs, kad jis priklauso Erodo valdžios sričiai, jis pasiuntė jį pas Erodą, kuris pats tuo metu buvo Jeruzalėje.'),
  (@b42, 23, 8, 'Ir pamatęs Jėzų, Erodas be galo apsidžiaugė, nes jau ilgą laiką troško jį pamatyti, kadangi daug girdėjo apie jį; ir jis tikėjosi išvysiąs jį darant kokį nors stebuklą.'),
  (@b42, 23, 9, 'Tada jis klausinėjo jį daugeliu žodžių; bet jis jam nieko neatsakė.'),
  (@b42, 23, 10, 'O vyriausieji kunigai ir raštininkai stovėjo ir įnirtingai jį kaltino.'),
  (@b42, 23, 11, 'Ir Erodas su savo karo vyrais jį išniekino, tyčiojosi iš jo ir aprengė jį puošniu drabužiu, ir išsiuntė jį atgal pas Pilotą.'),
  (@b42, 23, 12, 'Ir tą pačią dieną Pilotas su Erodu tapo draugais, nes prieš tai jie buvo vienas kitam priešiški.'),
  (@b42, 23, 13, 'Ir Pilotas, sukvietęs vyriausius kunigus, valdovus ir tautą,'),
  (@b42, 23, 14, 'jiems tarė: „Atvedėte man šitą žmogų kaip tą, kuris iškreipia tautą; ir štai aš, ištyręs jį jūsų akivaizdoje, neradau šitame žmoguje jokios kaltės dėl to, kuo jį kaltinate,'),
  (@b42, 23, 15, 'ir nei Erodas; nes siunčiau jus pas jį; ir štai nieko jam nepadaryta, kas būtų verta mirties.'),
  (@b42, 23, 16, 'Todėl jį nubausiu ir paleisiu“'),
  (@b42, 23, 17, '(nes jis būtinai turėjo per šventę jiems vieną paleisti).'),
  (@b42, 23, 18, 'Ir jie visi kartu šaukė, sakydami: „Šalin šitą, o paleisk mums Barabą!“'),
  (@b42, 23, 19, '(kuris buvo įmestas į kalėjimą už tam tikrą mieste įvykdytą maištą ir už žmogžudystę).'),
  (@b42, 23, 20, 'Taigi Pilotas, norėdamas paleisti Jėzų, vėl jiems kalbėjo.'),
  (@b42, 23, 21, 'Bet jie šaukė, sakydami: „Nukryžiuok jį, nukryžiuok jį!“'),
  (@b42, 23, 22, 'Ir jis trečią kartą tarė jiems: „Kodėl, ką pikto jis padarė? Neradau jame jokio pagrindo mirčiai, todėl jį nubausiu ir paleisiu“.'),
  (@b42, 23, 23, 'Bet jie nesiliovė garsiais balsais reikalaudami, kad jis būtų nukryžiuotas. Ir jų bei vyriausiųjų kunigų balsai ėmė viršų.'),
  (@b42, 23, 24, 'Ir Pilotas priėmė nuosprendį, kad būtų taip, kaip jie reikalavo.'),
  (@b42, 23, 25, 'Ir jis paleido jiems tą, kurio jie norėjo, kuris už maištą ir žmogžudystę buvo įmestas į kalėjimą; bet Jėzų atidavė jų valiai.'),
  (@b42, 23, 26, 'Ir vesdami jį šalin, jie nutvėrė tokį Simoną, kirėnietį, išeinantį iš apylinkių, ir ant jo uždėjo kryžių, kad neštų jį paskui Jėzų.'),
  (@b42, 23, 27, 'Ir paskui jį sekė didžiulis būrys liaudies bei moterų, kurios taip pat jį apraudojo ir apverkė.'),
  (@b42, 23, 28, 'Bet Jėzus atsisukęs į jas tarė: „Jeruzalės dukros, neverkite dėl manęs, bet verkite dėl savęs ir dėl savo vaikų.'),
  (@b42, 23, 29, 'Nes štai ateina dienos, kuriose sakys: ‘Palaimintos nevaisingosios ir įsčios, kurios niekada negimdė, ir krūtys, kurios niekada nežindė’.'),
  (@b42, 23, 30, 'Tada jie pradės sakyti kalnams: ‘Griūkite ant mūsų’; ir kalvoms: ‘Uždenkite mus’.'),
  (@b42, 23, 31, 'Nes jeigu jie tai daro žaliame medyje, tai kas bus daroma sausame?“'),
  (@b42, 23, 32, 'Ir kiti du, nusikaltėliai, buvo su juo vedami nužudyti.'),
  (@b42, 23, 33, 'Ir atėję į vietą, vadinamą Kaukolės, ten jie nukryžiavo jį ir nusikaltėlius: vieną iš dešinės, o kitą iš kairės.'),
  (@b42, 23, 34, 'Tada Jėzus tarė: „Tėve, atleisk jiems; nes jie nežino, ką daro“. Ir jie dalino jo drabužius ir metė burtus.'),
  (@b42, 23, 35, 'Ir tauta stovėjo žiūrėdama. Ir valdovai taip pat su jais išjuokė jį, sakydami: „Jis kitus gelbėjo; teišgelbėja save, jei yra Kristus, Dievo išrinktasis“.'),
  (@b42, 23, 36, 'Taip pat ir kareiviai iš jo tyčiojosi, ateidami pas jį ir siūlydami jam acto,'),
  (@b42, 23, 37, 'ir sakydami: „Jei esi žydų karalius, išgelbėk save“.'),
  (@b42, 23, 38, 'O viršum jo taipogi buvo graikų, lotynų ir hebrajų raidėmis užrašytas užrašas: „ŠITAS YRA ŽYDŲ KARALIUS“.'),
  (@b42, 23, 39, 'Ir vienas iš pakabintų nusikaltėlių jį keikė, sakydamas: „Jei esi Kristus, išgelbėk save ir mus“.'),
  (@b42, 23, 40, 'Bet kitas atsakydamas barė jį, sakydamas: „Ar nebijai Dievo, pats būdamas taip pat pasmerktas?'),
  (@b42, 23, 41, 'O mes, žinoma, teisingai; nes gauname užsitarnautą savo darbų atlygį, bet šitas žmogus nieko blogo nepadarė“.'),
  (@b42, 23, 42, 'Ir jis tarė Jėzui: „Viešpatie, prisimink mane, kai ateisi į savo karalystę“.'),
  (@b42, 23, 43, 'Ir Jėzus jam tarė: „Iš tiesų sakau tau: šiandien būsi su manimi rojuje“.'),
  (@b42, 23, 44, 'Ir buvo apie šeštą valandą, ir tamsa buvo virš visos žemės iki devintos valandos.'),
  (@b42, 23, 45, 'Ir saulė aptemo, ir šventyklos uždanga perplyšo per vidurį.'),
  (@b42, 23, 46, 'Ir sušukęs garsiu balsu Jėzus tarė: „Tėve, į tavo rankas pavedu savo dvasią“; ir taip pasakęs jis atidavė dvasią.'),
  (@b42, 23, 47, 'Na, o šimtininkas, pamatęs, kas atsitiko, šlovino Dievą, sakydamas: „Tikrai šitas buvo teisus žmogus“.'),
  (@b42, 23, 48, 'Ir visa tauta, kuri susirinko prie šito reginio, matydama tai, kas atsitiko, mušėsi sau į krūtines ir sugrįžo.'),
  (@b42, 23, 49, 'Ir visi jo pažįstami ir moterys, kurios sekė jį nuo Galilėjos, stovėjo iš tolo, žiūrėdami į tai.'),
  (@b42, 23, 50, 'Ir štai, buvo vyras vardu Juozapas, tarybos narys; geras žmogus ir teisus'),
  (@b42, 23, 51, '(jis nepritarė tarybai ir jų darbui); jis buvo iš Arimatėjos, žydų miesto; jis pats irgi laukė Dievo karalystės.'),
  (@b42, 23, 52, 'Šitas nuėjo pas Pilotą ir maldavo Jėzaus kūno.'),
  (@b42, 23, 53, 'Ir jis nuėmė jį žemėn, įvyniojo į drobę ir paguldė į kapą, ištašytą akmenyje, kuriame prieš tai niekas niekada negulėjo.'),
  (@b42, 23, 54, 'O ta diena buvo pasiruošimas, ir artinosi sabatas.'),
  (@b42, 23, 55, 'Ir moterys, atėjusios su juo iš Galilėjos, irgi nusekė iš paskos ir pamatė kapą bei kaip buvo paguldytas jo kūnas.'),
  (@b42, 23, 56, 'Ir jos sugrįžo ir paruošė kvapų ir tepalų; ir pagal įsakymą ilsėjosi sabato dieną.'),
  (@b42, 24, 1, 'Na, o pirmąją savaitės dieną, labai anksti ryte, jos atėjo prie kapo nešinos pasiruoštais kvapais, ir su jomis kai kurios kitos.'),
  (@b42, 24, 2, 'Ir jos rado akmenį nuritintą nuo kapo.'),
  (@b42, 24, 3, 'Ir įėjusios nerado Viešpaties Jėzaus kūno.'),
  (@b42, 24, 4, 'Ir įvyko, kai jos dėl to buvo labai sumišusios, štai šalia jų stovėjo du vyrai spindinčiais drabužiais;'),
  (@b42, 24, 5, 'ir kai jos išsigando ir nuleido savo veidus į žemę, jie tarė joms: „Kodėl ieškote gyvojo tarp mirusiųjų?'),
  (@b42, 24, 6, 'Jis ne čia, bet yra prisikėlęs – prisiminkite, kaip jis jums kalbėjo, kai dar buvo Galilėjoje,'),
  (@b42, 24, 7, 'sakydamas: ‘Žmogaus Sūnus turi būti atiduotas į nuodėmingų žmonių rankas, būti nukryžiuotas, o trečią dieną prisikelti’“.'),
  (@b42, 24, 8, 'Ir jos prisiminė jo žodžius');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b42, 24, 9, 'ir sugrįžusios nuo kapo papasakojo visa tai vienuolikai ir visiems kitiems.'),
  (@b42, 24, 10, 'Tai buvo Marija Magdalietė ir Joana, ir Jokūbo motina Marija, ir kitos, buvusios su jomis, kurios papasakojo tai apaštalams.'),
  (@b42, 24, 11, 'Bet jų žodžiai jiems atrodė kaip tuščios pasakos, ir jie netikėjo jomis.'),
  (@b42, 24, 12, 'Tada pakilo Petras ir nubėgo prie kapo; ir pasilenkęs žemyn jis pamatė vienas sau gulinčias drobules ir išėjo, besistebėdamas savyje tuo, kas įvyko.'),
  (@b42, 24, 13, 'Ir štai du iš jų tą pačią dieną ėjo į kaimą, vadinamą Emausu, buvusį apie šešiasdešimt stadijų nuo Jeruzalės.'),
  (@b42, 24, 14, 'Ir jie kalbėjosi apie visa tai, kas įvyko.'),
  (@b42, 24, 15, 'Ir įvyko, kad jiems besikalbant ir besvarstant prisiartino pats Jėzus ir ėjo su jais.'),
  (@b42, 24, 16, 'Bet jų akys buvo sulaikytos, kad jo nepažintų.'),
  (@b42, 24, 17, 'Ir jis tarė jiems: „Koks čia jūsų pasikalbėjimas vieno su kitu, kai einate ir esate nuliūdę?“'),
  (@b42, 24, 18, 'Ir vienas jų, vardu Kleopas, atsakydamas jam tarė: „Ar tu vienintelis ateivis Jeruzalėje ir nežinai šiomis dienomis ten įvykusių dalykų?“'),
  (@b42, 24, 19, 'Ir jis tarė jiems: „Kokių?“ Ir jie tarė jam: „Apie Jėzų iš Nazareto, kuris buvo pranašas, galingas darbu ir žodžiu Dievo ir visos tautos akyse;'),
  (@b42, 24, 20, 'ir kaip vyriausieji kunigai ir mūsų valdovai atidavė jį, kad būtų pasmerktas myriop, ir jį nukryžiavo.'),
  (@b42, 24, 21, 'Bet mes pasitikėjome, kad tai turėjo būti tas, kuris turi atpirkti Izraelį; ir šalia viso to šiandien yra trečia diena nuo to laiko, kai tai įvyko.'),
  (@b42, 24, 22, 'Taip, ir kai kurios moterys iš mūsiškių mus apstulbino, kurios buvo anksti prie kapo;'),
  (@b42, 24, 23, 'ir neradusios jo kūno atėjo sakydamos, kad jos taipogi mačiusios regėjimą angelų, kurie sakė, kad jis yra gyvas.'),
  (@b42, 24, 24, 'Ir kai kurie iš esančių su mumis nuėjo prie kapo ir atrado taip, kaip moterys buvo sakiusios; bet jo jie nematė“.'),
  (@b42, 24, 25, 'Tada jis tarė jiems: „O kvailiai ir lėtos širdies tikėti visu tuo, ką kalbėjo pranašai!'),
  (@b42, 24, 26, 'Argi Kristus neturėjo šito kentėti ir įeiti į savo šlovę?“'),
  (@b42, 24, 27, 'Ir pradedant nuo Mozės ir visų pranašų jis jiems iš visų Raštų išaiškino tuos dalykus apie jį.'),
  (@b42, 24, 28, 'Ir jie priartėjo prie kaimo, į kurį ėjo; o jis dėjosi einąs toliau.'),
  (@b42, 24, 29, 'Bet jie privertė jį, sakydami: „Pasilik su mumis, nes jau vakarėja, ir diena jau baigiasi“. Ir jis įėjo, kad pasiliktų su jais.'),
  (@b42, 24, 30, 'Ir įvyko jam atsisėdus su jais prie valgio, jis paėmė duoną, palaimino ją, laužė ir davė jiems.'),
  (@b42, 24, 31, 'Ir jų akys atsivėrė, ir jie pažino jį; bet jis pranyko jiems iš akių.'),
  (@b42, 24, 32, 'Ir jie vienas kitam tarė: „Argi mūsų širdys nedegė mumyse, kai jis kelyje kalbėjo su mumis ir kai atvėrė mums Raštus?“'),
  (@b42, 24, 33, 'Ir tą pačią valandą jie pakilo ir sugrįžo į Jeruzalę, ir rado susirinkusius vienuolika ir tuos, kurie buvo su jais,'),
  (@b42, 24, 34, 'sakančius: „Viešpats tikrai prisikėlęs ir pasirodė Simonui“.'),
  (@b42, 24, 35, 'Ir jie papasakojo, kas nutiko kelyje, ir kaip jis buvo jų atpažintas duonos laužyme.'),
  (@b42, 24, 36, 'Ir jiems taip bekalbant, pats Jėzus atsistojo jų viduryje ir jiems sako: „Ramybė jums“.'),
  (@b42, 24, 37, 'Bet jie buvo siaubo apimti ir išsigandę, ir tarėsi matą dvasią.'),
  (@b42, 24, 38, 'Ir jis tarė jiems: „Kodėl jūs sunerimę? Ir kodėl jūsų širdyse kyla mintys?'),
  (@b42, 24, 39, 'Pasižiūrėkite į mano rankas ir mano kojas, kad tai aš pats, palieskite mane ir pamatykite; nes dvasia neturi mėsos ir kaulų, kaip matote mane turint“.'),
  (@b42, 24, 40, 'Ir taip pasakęs jis parodė jiems savo rankas ir kojas.'),
  (@b42, 24, 41, 'Ir jiems iš džiaugsmo vis dar netikint ir stebintis, jis tarė jiems: „Ar turite čia kokio maisto?“'),
  (@b42, 24, 42, 'Ir jie davė jam gabalą keptos žuvies ir medaus korio.'),
  (@b42, 24, 43, 'Ir jis tai paėmė ir valgė jų akivaizdoje.'),
  (@b42, 24, 44, 'Ir jis tarė jiems: „Šitie yra žodžiai, kuriuos jums kalbėjau, kol dar buvau su jumis, kad turi išsipildyti visa, kas surašyta apie mane Mozės įstatyme, pranašuose ir psalmėse“.'),
  (@b42, 24, 45, 'Tada jis atvėrė jiems supratimą, kad jie suprastų Raštus,'),
  (@b42, 24, 46, 'ir tarė jiems: „Taip yra parašyta ir taip reikėjo Kristui kentėti ir trečią dieną prisikelti iš mirusiųjų;'),
  (@b42, 24, 47, 'ir kad pradedant nuo Jeruzalės tarp visų tautų jo vardu turi būti skelbiama atgaila ir nuodėmių atleidimas.'),
  (@b42, 24, 48, 'Ir jūs esate šito liudytojai.'),
  (@b42, 24, 49, 'Ir štai siunčiu ant jūsų savo Tėvo pažadą; bet jūs pasilikite Jeruzalės mieste, kol būsite apdalinti jėga iš aukštybių“.'),
  (@b42, 24, 50, 'Ir jis išvedė juos iki Betanijos, iškėlė savo rankas ir juos palaimino.'),
  (@b42, 24, 51, 'Ir įvyko, kol jis juos laimino, jis buvo atskirtas nuo jų ir paimtas į dangų.'),
  (@b42, 24, 52, 'Ir jie pagarbino jį ir su didžiu džiaugsmu sugrįžo į Jeruzalę;'),
  (@b42, 24, 53, 'ir nuolat buvo šventykloje, girdami ir laimindami Dievą. Amen.'),
  (@b43, 1, 1, 'Pradžioje buvo Žodis, ir Žodis buvo pas Dievą, ir Žodis buvo Dievas.'),
  (@b43, 1, 2, 'Jis buvo pradžioje pas Dievą.'),
  (@b43, 1, 3, 'Visa yra per jį padaryta; ir be jo nėra padaryta nieko, kas tik yra padaryta.'),
  (@b43, 1, 4, 'Jame buvo gyvybė; ir ta gyvybė buvo žmonių šviesa.'),
  (@b43, 1, 5, 'Ir šviesa šviečia tamsoje; o tamsa jos neužgožė.'),
  (@b43, 1, 6, 'Buvo iš Dievo siųstas žmogus, kurio vardas Jonas.'),
  (@b43, 1, 7, 'Jis atėjo liudijimui, kad paliudytų apie Šviesą, kad visi per jį įtikėtų.'),
  (@b43, 1, 8, 'Jis nebuvo ta Šviesa, bet buvo pasiųstas liudyti apie tą Šviesą.'),
  (@b43, 1, 9, 'Ta buvo tikroji Šviesa, kuri apšviečia kiekvieną žmogų, ateinantį į pasaulį.'),
  (@b43, 1, 10, 'Jis buvo pasaulyje, ir pasaulis buvo per jį padarytas, bet pasaulis jo nepažino.'),
  (@b43, 1, 11, 'Jis atėjo pas savuosius, bet savieji jo nepriėmė.'),
  (@b43, 1, 12, 'O visiems, kurie jį priėmė, tiems jis davė valdžią tapti Dievo sūnumis – tiems, kurie tiki į jo vardą,'),
  (@b43, 1, 13, 'kurie gimė ne iš kraujo, nei iš kūno noro, nei iš vyro noro, bet iš Dievo.'),
  (@b43, 1, 14, 'Ir Žodis tapo kūnu ir gyveno tarp mūsų (ir mes matėme jo šlovę – kaip Tėvo viengimio šlovę), pilnas malonės ir tiesos.'),
  (@b43, 1, 15, 'Jonas liudijo apie jį ir šaukė, sakydamas: „Jis buvo tas, apie kurį kalbėjau: ‘Tas, kuris ateina po manęs, yra pirmesnis už mane, nes jis buvo anksčiau už mane’.'),
  (@b43, 1, 16, 'Ir iš jo pilnatvės mes visi gavome ir malonę už malonę.'),
  (@b43, 1, 17, 'Nes įstatymas buvo duotas per Mozę, bet malonė ir tiesa atėjo per Jėzų Kristų.'),
  (@b43, 1, 18, 'Niekas niekada nėra matęs Dievo; viengimis Sūnus, kuris yra Tėvo prieglobstyje, tas jį paskelbė“.'),
  (@b43, 1, 19, 'Ir šitas yra Jono liudijimas, kai žydai iš Jeruzalės siuntė kunigus ir levitus jo paklausti: „Kas tu esi?“'),
  (@b43, 1, 20, 'Ir jis išpažino ir neišsigynė; bet išpažino: „Aš nesu Kristus“.'),
  (@b43, 1, 21, 'Ir jie paklausė jo: „Kas tuomet? Ar tu Elijas?“ O jis sako: „Aš nesu“. „Ar tu tas pranašas?“ Ir jis atsakė: „Ne“.'),
  (@b43, 1, 22, 'Tada jie tarė jam: „Kas tu? Kad galėtume duoti atsakymą tiems, kurie mus siuntė. Ką sakai apie save?“'),
  (@b43, 1, 23, 'Jis tarė: „Aš – dykumoje šaukiančiojo balsas: ‘Tiesinkite Viešpaties kelią’, kaip sakė pranašas Izaijas“.'),
  (@b43, 1, 24, 'O atsiųstieji buvo iš fariziejų.'),
  (@b43, 1, 25, 'Ir jie paklausė jo ir jam tarė: „Tad kodėl krikštiji, jei nesi tas Kristus nei Elijas, nei tas pranašas?“'),
  (@b43, 1, 26, 'Jonas jiems atsakė, tardamas: „Aš krikštiju vandeniu; bet tarp jūsų stovi tas, kurio nepažįstate;'),
  (@b43, 1, 27, 'jis yra tas, kuris ateina po manęs, kuris pirmesnis už mane, kurio batų dirželio nesu vertas atrišti“.'),
  (@b43, 1, 28, 'Tai atsitiko Betabaroje už Jordano, kur Jonas krikštijo.'),
  (@b43, 1, 29, 'Rytojaus dieną Jonas pamato ateinantį pas jį Jėzų ir sako: „Štai Dievo Avinėlis, kuris pašalina pasaulio nuodėmę.'),
  (@b43, 1, 30, 'Šitas yra tas, apie kurį sakiau: ‘Po manęs ateina vyras, kuris yra pirmesnis už mane, nes jis buvo pirma manęs’.'),
  (@b43, 1, 31, 'Ir aš jo nepažinojau, bet kad jis būtų apreikštas Izraeliui, dėl to atėjau krikštydamas vandeniu“.'),
  (@b43, 1, 32, 'Ir Jonas liudija, sakydamas: „Mačiau Dvasią, lyg balandį nusileidžiančią iš dangaus, ir ji pasiliko ant jo.'),
  (@b43, 1, 33, 'Ir aš jo nepažinojau; bet tas, kuris siuntė mane krikštyti vandeniu, man sakė: ‘Ant kurio pamatysi nusileidžiančią Dvasią ir ant jo pasiliekančią, jis yra tas, kuris krikštija Šventąja Dvasia’.'),
  (@b43, 1, 34, 'Ir aš mačiau ir liudiju, kad šitas yra Dievo Sūnus“.'),
  (@b43, 1, 35, 'Rytojaus dieną vėl stovėjo Jonas ir du iš jo mokinių;'),
  (@b43, 1, 36, 'ir žiūrėdamas į einantį Jėzų jis sako: „Štai Dievo Avinėlis!“'),
  (@b43, 1, 37, 'Ir tiedu mokiniai girdėjo jį kalbant ir nusekė paskui Jėzų.'),
  (@b43, 1, 38, 'Tada Jėzus atsisukęs pamatė juos sekančius ir sako jiems: „Ko ieškote?“ Jie tarė jam: „Rabi (kas išvertus reiškia „Mokytojau“), kur tu gyveni?“'),
  (@b43, 1, 39, 'Jis sako jiems: „Ateikite ir pažiūrėkite“. Jie atėjo ir pamatė, kur jis gyvena, ir tą dieną pasiliko pas jį; nes buvo apie dešimtą valandą.'),
  (@b43, 1, 40, 'Vienas iš tų dviejų, kurie girdėjo Joną kalbant ir sekė paskui jį, buvo Simono Petro brolis Andriejus.'),
  (@b43, 1, 41, 'Jis pirma suranda savo brolį Simoną ir jam sako: „Mes radome Mesiją!“, kas išvertus reiškia „Kristų“.'),
  (@b43, 1, 42, 'Ir atvedė jį pas Jėzų. Ir į jį pažiūrėjęs Jėzus tarė: „Tu esi Simonas, Jonos sūnus; tu būsi vadinamas Kefu, kas išvertus reiškia „Akmuo“.'),
  (@b43, 1, 43, 'Rytojaus dieną Jėzus norėjo eiti į Galilėją; ir suranda Pilypą ir jam sako: „Sek paskui mane“.'),
  (@b43, 1, 44, 'Na, o Pilypas buvo iš Betsaidos, Andriejaus ir Petro miesto.'),
  (@b43, 1, 45, 'Pilypas suranda Natanaelį ir jam sako: „Mes suradome tą, apie kurį rašė Mozė įstatyme ir pranašai, Jėzų iš Nazareto, Juozapo sūnų“.'),
  (@b43, 1, 46, 'Ir Natanaelis jam tarė: „Argi iš Nazareto gali būti kas gero?“ Pilypas jam sako: „Ateik ir pažiūrėk“.'),
  (@b43, 1, 47, 'Jėzus pamatė Natanaelį, ateinantį pas jį, ir jam sako: „Štai tikras izraelitas, kuriame nėra klastos!“'),
  (@b43, 1, 48, 'Natanaelis jam sako: „Iš kur mane pažįsti?“ Jėzus atsakydamas tarė jam: „Prieš Pilypui pakviečiant tave, kai tu buvai po figmedžiu, aš mačiau tave“.'),
  (@b43, 1, 49, 'Natanaelis atsakydamas taria jam: „Rabi, tu esi Dievo Sūnus; tu esi Izraelio Karalius“.'),
  (@b43, 1, 50, 'Jėzus atsakydamas tarė jam: „Tiki, kadangi tau pasakiau: ‘Mačiau tave po figmedžiu’? Pamatysi didesnių dalykų už šituos“.'),
  (@b43, 1, 51, 'Ir sako jam: „Iš tiesų, iš tiesų sakau jums: nuo šiol matysite atvirą dangų ir Dievo angelus, kylančius ir nusileidžiančius ant žmogaus Sūnaus“.'),
  (@b43, 2, 1, 'Ir trečią dieną Galilėjos Kanoje buvo vestuvės; ir Jėzaus motina buvo ten;'),
  (@b43, 2, 2, 'ir tiek Jėzus, tiek jo mokiniai buvo pakviesti į vestuves.'),
  (@b43, 2, 3, 'Ir kai jie stokojo vyno, Jėzaus motina jam sako: „Jie neturi vyno“.'),
  (@b43, 2, 4, 'Jėzus jai sako: „Kas man darbo su tavimi, moterie? Mano valanda dar neatėjo“.'),
  (@b43, 2, 5, 'Jo motina sako tarnams: „Ką jis jums sako, tai darykite“.'),
  (@b43, 2, 6, 'Ir pagal žydų apvalymo papročius ten buvo padėti šeši akmeniniai vandens puodai, kiekvienas talpinantis du arba tris saikus.'),
  (@b43, 2, 7, 'Jėzus jiems sako: „Pripildykite vandenpuodžius vandeniu“. Ir jie pripildė juos iki briaunos.'),
  (@b43, 2, 8, 'Ir jis sako jiems: „Dabar semkite ir neškite puotos valdytojui“. Ir jie nunešė.'),
  (@b43, 2, 9, 'Kai puotos valdytojas paragavo vandens, paversto vynu, ir nežinojo, iš kur jis yra (bet tarnai, kurie sėmė vandenį, žinojo), puotos valdytojas pasišaukė jaunikį'),
  (@b43, 2, 10, 'ir jam sako: „Kiekvienas žmogus pradžioje padeda gerą vyną; o kai žmonės gerai įgėrę, tada prastesnį; bet tu laikei gerą vyną iki šiol“.'),
  (@b43, 2, 11, 'Šitą stebuklų pradžią Jėzus padarė Galilėjos Kanoje ir apreiškė savo šlovę; ir jo mokiniai juo įtikėjo.'),
  (@b43, 2, 12, 'Po to jis nuėjo į Kafernaumą, jis ir jo motina, ir jo broliai, ir jo mokiniai; ir jie ten pasiliko nedaug dienų.'),
  (@b43, 2, 13, 'Ir žydų Apėjimas buvo čia pat, ir Jėzus nuėjo aukštyn į Jeruzalę,'),
  (@b43, 2, 14, 'ir šventykloje rado tuos, kurie pardavinėjo jaučius, avis ir balandžius, ir sėdinčius pinigų keitėjus;'),
  (@b43, 2, 15, 'ir pasidaręs iš virvučių rimbą, jis išvarė iš šventyklos juos visus, avis ir jaučius; ir išpylė keitėjų pinigus bei apvertė stalus;'),
  (@b43, 2, 16, 'ir tarė balandžių pardavinėtojams: „Pasiimkite tai iš čia; nedarykite mano Tėvo namų prekybos namais“.'),
  (@b43, 2, 17, 'Ir jo mokiniai prisiminė, kad buvo parašyta: „Tavo namų uolumas mane suėdė“.'),
  (@b43, 2, 18, 'Tada žydai atsakydami jam tarė: „Kokį ženklą mums rodai, kad tai darai?“'),
  (@b43, 2, 19, 'Jėzus atsakydamas tarė jiems: „Sugriaukite šitą šventyklą, ir per tris dienas aš ją pakelsiu“.'),
  (@b43, 2, 20, 'Tada tarė žydai: „Keturiasdešimt šešis metus buvo statoma ši šventykla, o tu ją pastatysi per tris dienas?“'),
  (@b43, 2, 21, 'Bet jis kalbėjo apie savo kūno šventyklą.'),
  (@b43, 2, 22, 'Todėl kai jis buvo prisikėlęs iš numirusių, jo mokiniai prisiminė, kad jis tai jiems sakė; ir jie tikėjo Raštu ir žodžiu, kurį sakė Jėzus.'),
  (@b43, 2, 23, 'Na, o jam esant Jeruzalėje per Apėjimą, šventės dieną, daugelis, pamatę stebuklus, kuriuos jis darė, įtikėjo jo vardu.'),
  (@b43, 2, 24, 'Bet Jėzus savęs jiems nepatikėjo, nes jis visus pažinojo,'),
  (@b43, 2, 25, 'ir nereikėjo, kad kas liudytų apie žmogų, nes jis žinojo, kas yra žmoguje.'),
  (@b43, 3, 1, 'Buvo žmogus iš fariziejų, vardu Nikodemas, žydų valdovas;'),
  (@b43, 3, 2, 'jis atėjo naktį pas Jėzų ir jam tarė: „Rabi, žinome, kad esi mokytojas, atėjęs nuo Dievo, nes nei vienas negali padaryti šitų stebuklų, kuriuos tu darai, jei Dievas nėra su juo“.'),
  (@b43, 3, 3, 'Jėzus atsakydamas jam tarė: „Iš tiesų, iš tiesų sakau tau: jei kas negims iš naujo, tas negali regėti Dievo karalystės“.'),
  (@b43, 3, 4, 'Nikodemas jam sako: „Kaip žmogus gali gimti, būdamas senas? Ar jis gali antrą kartą įeiti į savo motinos įsčias ir gimti?“'),
  (@b43, 3, 5, 'Jėzus atsakė: „Iš tiesų, iš tiesų sakau tau: jei kas negims iš vandens ir Dvasios, tas negali įeiti į Dievo karalystę.'),
  (@b43, 3, 6, 'Tas, kuris gimęs iš kūno, yra kūnas; o tas, kuris gimęs iš Dvasios, yra dvasia.'),
  (@b43, 3, 7, 'Nesistebėk, kad pasakiau tau: ‘Jums būtina vėl gimti’.'),
  (@b43, 3, 8, 'Vėjas pučia, kur nori, ir tu girdi jo garsą, bet negali pasakyti, iš kur jis ateina ir kur nueina; taip yra kiekvienas gimęs iš Dvasios“.'),
  (@b43, 3, 9, 'Nikodemas atsakydamas jam tarė: „Kaip tai gali būti?“'),
  (@b43, 3, 10, 'Jėzus atsakydamas jam tarė: „Tu esi Izraelio mokytojas ir nežinai šito?'),
  (@b43, 3, 11, 'Iš tiesų, iš tiesų sakau tau: mes kalbame, ką žinome, ir liudijame, ką matėme; o jūs nepriimate mūsų liudijimo.'),
  (@b43, 3, 12, 'Jei kalbėjau jums žemiškus dalykus, ir jūs netikite, kaipgi tikėsite, jei kalbėsiu jums apie dangiškus dalykus?'),
  (@b43, 3, 13, 'Ir niekas nepakilo į dangų, bet tik tas, kuris nužengė iš dangaus, būtent žmogaus Sūnus, kuris yra danguje.'),
  (@b43, 3, 14, 'Ir kaip Mozė dykumoje iškėlė gyvatę, taip ir žmogaus Sūnus turi būti iškeltas,'),
  (@b43, 3, 15, 'kad kiekvienas, kuris jį tiki, nepražūtų, bet turėtų amžinąjį gyvenimą.'),
  (@b43, 3, 16, 'Nes Dievas taip pamilo pasaulį, kad atidavė savo viengimį Sūnų, idant kiekvienas, kuris į jį tiki, nepražūtų, bet turėtų amžinąjį gyvenimą.'),
  (@b43, 3, 17, 'Nes Dievas nesiuntė savo Sūnaus į pasaulį, kad pasmerktų pasaulį; bet kad pasaulis per jį būtų išgelbėtas.'),
  (@b43, 3, 18, 'Kas juo tiki, tas nesmerkiamas, tačiau kas netiki, tas jau yra pasmerktas, kadangi netikėjo viengimio Dievo Sūnaus vardu.'),
  (@b43, 3, 19, 'Ir šis yra pasmerkimas, kad šviesa atėjo į pasaulį, bet žmonės verčiau pamilo tamsą negu šviesą, nes jų darbai buvo pikti.'),
  (@b43, 3, 20, 'Nes kiekvienas, kuris daro pikta, nekenčia šviesos ir neina į šviesą, kad jo darbai nebūtų pabarti.'),
  (@b43, 3, 21, 'Tačiau kas vykdo tiesą, tas ateina į šviesą, idant jo darbai pasirodytų, kad jie yra atlikti Dieve“.'),
  (@b43, 3, 22, 'Po šių dalykų Jėzus ir jo mokiniai atėjo į Judėjos šalį; ir ten jis su jais apsistojo ir krikštijo.'),
  (@b43, 3, 23, 'Ir Jonas taipogi krikštijo Enone, arti Salimo, nes ten buvo daug vandens; ir jie atėjo ir buvo pakrikštyti.'),
  (@b43, 3, 24, 'Nes Jonas dar nebuvo įmestas į kalėjimą.'),
  (@b43, 3, 25, 'Tada iškilo klausimas tarp kai kurių Jono mokinių ir žydų dėl apvalymo.'),
  (@b43, 3, 26, 'Ir jie atėjo pas Joną ir jam tarė: „Rabi, tas, kuris buvo su tavimi už Jordano, kurį tu liudijai, štai jis krikštija, ir visi ateina pas jį“.'),
  (@b43, 3, 27, 'Jonas atsakydamas tarė: „Žmogus nieko negali priimti, jeigu jam nebūtų duota iš dangaus.'),
  (@b43, 3, 28, 'Jūs patys man liudijate, kad pasakiau: ‘Aš nesu Kristus, bet esu pirma jo pasiųstas’.'),
  (@b43, 3, 29, 'Kas turi nuotaką, tas yra jaunikis; bet jaunikio draugas, kuris stovi ir jo klausosi, didžiai džiaugiasi jaunikio balsu; todėl šis mano džiaugsmas išsipildė.'),
  (@b43, 3, 30, 'Jis turi augti, bet aš turiu mažėti.'),
  (@b43, 3, 31, 'Tas, kuris ateina iš aukštai, yra virš visų; kas yra iš žemės, yra žemiškas ir kalba iš žemės; tas, kuris ateina iš dangaus, yra virš visų.'),
  (@b43, 3, 32, 'Ir ką jis yra matęs ir girdėjęs, tai jis liudija; bet niekas nepriima jo liudijimo.'),
  (@b43, 3, 33, 'Kas priėmė jo liudijimą, tas užantspaudavo tai, kad Dievas yra teisus.'),
  (@b43, 3, 34, 'Nes tas, kurį Dievas siuntė, kalba Dievo žodžius, nes Dievas jam duoda Dvasios ne su saiku.'),
  (@b43, 3, 35, 'Tėvas myli Sūnų, ir visa yra atidavęs į jo ranką.'),
  (@b43, 3, 36, 'Tas, kuris tiki Sūnų, turi amžinąjį gyvenimą; o tas, kuris netiki Sūnumi, nematys gyvenimo; bet ant jo pasilieka Dievo rūstybė“.'),
  (@b43, 4, 1, 'Taigi kai Viešpats sužinojo, kaip fariziejai išgirdo, jog Jėzus padarė ir pakrikštijo daugiau mokinių negu Jonas'),
  (@b43, 4, 2, '(nors pats Jėzus nekrikštijo, bet jo mokiniai),'),
  (@b43, 4, 3, 'jis paliko Judėją ir pasitraukė vėl į Galilėją.'),
  (@b43, 4, 4, 'Ir jam reikėjo eiti per Samariją.'),
  (@b43, 4, 5, 'Tada jis ateina į Samarijos miestą, vadinamą Sicharu, šalia žemės sklypo, kurį Jokūbas davė savo sūnui Juozapui.'),
  (@b43, 4, 6, 'Na, o ten buvo Jokūbo šulinys. Todėl Jėzus, pavargęs nuo savo kelionės, atsisėdo taip ant šulinio; ir buvo apie šeštą valandą.'),
  (@b43, 4, 7, 'Ateina moteris iš Samarijos pasisemti vandens; Jėzus jai sako: „Duok man gerti“'),
  (@b43, 4, 8, '(nes jo mokiniai buvo nuėję į miestą nupirkti maisto).'),
  (@b43, 4, 9, 'Tada moteris iš Samarijos jam sako: „Kaipgi tu, būdamas žydas, prašai gerti manęs, Samarijos moters?“ Nes žydai nebendrauja su samariečiais.'),
  (@b43, 4, 10, 'Jėzus atsakydamas jai tarė: „Jei žinotumei Dievo dovaną ir kas yra tas, kuris tau sako: ‘Duok man gerti’, tu jo prašytumei, ir jis tau duotų gyvojo vandens“.'),
  (@b43, 4, 11, 'Moteris jam sako: „Pone, tu neturi kuo pasemti, o šulinys yra gilus; tad iš kur tu turi to gyvojo vandens?'),
  (@b43, 4, 12, 'Ar esi didesnis už mūsų tėvą Jokūbą, kuris mums davė šį šulinį ir pats iš jo gėrė ir jo vaikai, ir jo galvijai?“'),
  (@b43, 4, 13, 'Jėzus atsakydamas jai tarė: „Kas geria šio vandens, vėl trokš;'),
  (@b43, 4, 14, 'bet kas geria vandens, kurio aš jam duosiu, niekada nebetrokš; bet vanduo, kurį jam duosiu, bus jame vandens šaltinis, trykštantis į amžinąjį gyvenimą“.'),
  (@b43, 4, 15, 'Moteris jam sako: „Pone, duok man to vandens, kad nebetrokščiau ir nebeičiau čia semti“.'),
  (@b43, 4, 16, 'Jėzus jai sako: „Eik, pakviesk savo vyrą ir ateik čia“.'),
  (@b43, 4, 17, 'Moteris atsakydama tarė: „Aš neturiu vyro“. Jėzus jai tarė: „Gerai pasakei: ‘Aš neturiu vyro’,'),
  (@b43, 4, 18, 'nes esi turėjusi penkis vyrus; ir tas, kurį dabar turi, nėra tavo vyras – tame sakai tiesą“.'),
  (@b43, 4, 19, 'Moteris jam sako: „Pone, matau, kad esi pranašas.'),
  (@b43, 4, 20, 'Mūsų tėvai garbino šiame kalne; o jūs sakote, kad Jeruzalėje yra vieta, kur reikia garbinti“.'),
  (@b43, 4, 21, 'Jėzus jai sako: „Moterie, tikėk manimi: ateina valanda, kai jūs ne šiame kalne ir ne Jeruzalėje garbinsite Tėvą.'),
  (@b43, 4, 22, 'Jūs nežinote, ką garbinate; mes žinome, ką garbiname; nes išgelbėjimas yra iš žydų.'),
  (@b43, 4, 23, 'Bet ateina valanda, ir jau yra, kai tikri garbintojai Tėvą garbins dvasioje ir tiesoje; nes Tėvas ieško tokių jį garbinti.'),
  (@b43, 4, 24, 'Dievas yra Dvasia, ir tie, kurie jį garbina, turi jį garbinti dvasioje ir tiesoje“.'),
  (@b43, 4, 25, 'Moteris jam sako: „Žinau, kad Mesijas ateina, kuris vadinamas Kristumi; kai jis ateis, viską mums pasakys“.'),
  (@b43, 4, 26, 'Jėzus jai sako: „Aš, kuris su tavimi kalbu, esu jis“.'),
  (@b43, 4, 27, 'Ir tuo metu atėjo jo mokiniai ir stebėjosi, kad jis kalbėjosi su moterimi; tačiau nei vienas nesakė: „Ko ieškai?“ arba: „Kodėl su ja kalbi?“'),
  (@b43, 4, 28, 'Tada moteris paliko savo vandens puodą, nuėjo į miestą ir sako žmonėms:'),
  (@b43, 4, 29, '„Ateikite pažiūrėti žmogaus, kuris pasakė man viską, ką esu padariusi; argi šitas ne Kristus?“'),
  (@b43, 4, 30, 'Tada jie išėjo iš miesto ir atėjo pas jį.'),
  (@b43, 4, 31, 'Tuo tarpu jo mokiniai meldė jo, sakydami: „Mokytojau, valgyk“.'),
  (@b43, 4, 32, 'Bet jis tarė jiems: „Aš turiu valgyti maisto, kurio jūs nežinote“.'),
  (@b43, 4, 33, 'Todėl mokiniai tarė vienas kitam: „Ar kas atnešė jam ką pavalgyti?“'),
  (@b43, 4, 34, 'Jėzus jiems sako: „Mano maistas – vykdyti valią to, kuris mane siuntė, ir užbaigti jo darbą.'),
  (@b43, 4, 35, 'Argi nesakote: ‘Dar keturi mėnesiai, ir tada ateina pjūtis’? Štai jums sakau: ‘Pakelkite savo akis ir pažvelkite į laukus; nes jie jau baltuoja pjūčiai’.'),
  (@b43, 4, 36, 'Ir kas pjauna, gauna algą ir surenka vaisių amžinajam gyvenimui; kad tas, kuris sėja, ir tas, kuris pjauna, džiaugtųsi drauge.'),
  (@b43, 4, 37, 'Ir čia teisingas yra šis pasakymas: ‘Vienas sėja, o kitas pjauna’.'),
  (@b43, 4, 38, 'Aš siunčiu jus pjauti to, į ką jūs neįdėjote triūso; kiti triūsė, o jūs įstoję į jų darbus“.'),
  (@b43, 4, 39, 'Ir daug to miesto samariečių įtikėjo į jį dėl moters pasakymo, kuri liudijo: „Jis man pasakė viską, ką esu padariusi“.'),
  (@b43, 4, 40, 'Tad kai samariečiai atėjo pas jį, jie maldavo jo, kad jis apsistotų pas juos; ir jis pasiliko ten dvi dienas.'),
  (@b43, 4, 41, 'Ir dar daugelis įtikėjo dėl jo paties žodžio;'),
  (@b43, 4, 42, 'ir tarė moteriai: „Dabar tikime ne dėl tavo pasakymo, nes mes patys išgirdome jį ir pažinome, kad šitas iš tikrųjų yra Kristus, pasaulio Gelbėtojas“.'),
  (@b43, 4, 43, 'Na, o po dviejų dienų jis iš ten išėjo ir nuėjo į Galilėją.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b43, 4, 44, 'Nes pats Jėzus liudijo, kad pranašas negerbiamas savo tėviškėje.'),
  (@b43, 4, 45, 'Tada, kai jis atėjo į Galilėją, jį priėmė galilėjiečiai, mačiusieji visa, ką jis padarė per šventę Jeruzalėje, nes ir jie ėjo į šventę.'),
  (@b43, 4, 46, 'Taip Jėzus vėl atėjo į Galilėjos Kaną, kur jis padarė vandenį vynu. Ir buvo vienas didikas, kurio sūnus sirgo Kafernaume.'),
  (@b43, 4, 47, 'Išgirdęs, kad Jėzus iš Judėjos atėjo į Galilėją, nuėjo pas jį ir maldavo jo, kad ateitų žemyn ir išgydytų jo sūnų, nes jis buvo prie mirties.'),
  (@b43, 4, 48, 'Tada Jėzus jam tarė: „Jei nepamatysite ženklų ir stebuklų, netikėsite“.'),
  (@b43, 4, 49, 'Didikas jam sako: „Pone, ateik žemyn, kol mano vaikas nenumirė“.'),
  (@b43, 4, 50, 'Jėzus jam sako: „Eik – tavo sūnus gyvas“. Ir tas žmogus patikėjo žodžiu, kurį Jėzus jam kalbėjo, ir nuėjo.'),
  (@b43, 4, 51, 'Ir jam beeinant žemyn, jį pasitiko jo tarnai ir jam pasakė, tardami: „Tavo sūnus gyvas“.'),
  (@b43, 4, 52, 'Tada jis jų teiravosi dėl valandos, kada jis pradėjo taisytis. Ir jie tarė jam: „Vakar septintą valandą karštinė jį paliko“.'),
  (@b43, 4, 53, 'Taigi tėvas žinojo, kad tai buvo ta pati valanda, kurią Jėzus jam tarė: „Tavo sūnus gyvas“, ir įtikėjo jis pats ir visi jo namai.'),
  (@b43, 4, 54, 'Šitas vėl yra antrasis stebuklas, kurį padarė Jėzus, kai jis buvo atėjęs iš Judėjos į Galilėją.'),
  (@b43, 5, 1, 'Po to buvo žydų šventė; ir Jėzus nuėjo aukštyn į Jeruzalę.'),
  (@b43, 5, 2, 'Na, o Jeruzalėje prie avių turgaus yra tvenkinys, hebrajiškai vadinamas Betezda, turintis penkis prieangius.'),
  (@b43, 5, 3, 'Juose guli didžiulė minia bejėgių, aklų, šlubių, sudžiūvusių, laukiančių vandens sujudėjimo.'),
  (@b43, 5, 4, 'Nes angelas tam tikru metu nusileisdavo į tvenkinį ir sujudindavo vandenį; tad kas pirmas po vandens sujudinimo įlipdavo, pasveikdavo nuo bet kokios ligos, kokia besirgdavo.'),
  (@b43, 5, 5, 'Ir ten buvo vienas žmogus, kuris trisdešimt aštuonerius metus turėjo negalią.'),
  (@b43, 5, 6, 'Kai Jėzus pamatė jį gulintį ir žinojo, kad jis jau ilgą laiką serga, jis jam sako: „Ar nori tapti sveikas?“'),
  (@b43, 5, 7, 'Bejėgis jam atsakė: „Pone, aš neturiu žmogaus, kuris vandeniui sujudėjus įkeltų mane į tvenkinį; o kol ateinu, kitas pirma manęs įžengia“.'),
  (@b43, 5, 8, 'Jėzus jam sako: „Kelkis, pasiimk savo patalą ir vaikščiok“.'),
  (@b43, 5, 9, 'Ir tuojau tas žmogus tapo sveikas ir paėmė savo patalą, ir vaikščiojo; o tą pačią dieną buvo sabatas.'),
  (@b43, 5, 10, 'Todėl žydai tarė išgydytajam: „Tai sabato diena; tau neteisėta nešti savo patalo“.'),
  (@b43, 5, 11, 'Jis atsakė jiems: „Tas, kuris mane išgydė, man tarė: ‘Pasiimk savo patalą ir vaikščiok’“.'),
  (@b43, 5, 12, 'Tada jie paklausė jo: „Kas yra tas žmogus, pasakęs tau: ‘Pasiimk savo patalą ir vaikščiok’?“'),
  (@b43, 5, 13, 'Bet išgydytasis nežinojo, kas jis, nes, miniai esant toje vietoje, Jėzus pasitraukė.'),
  (@b43, 5, 14, 'Po to Jėzus rado jį šventykloje ir tarė jam: „Štai tapai sveikas: nebenusidėk, kad tavęs neištiktų kas blogesnio“.'),
  (@b43, 5, 15, 'Tas žmogus nuėjo ir pasakė žydams, kad tai buvo Jėzus, kuris padarė jį sveiką.'),
  (@b43, 5, 16, 'Ir todėl žydai persekiojo Jėzų ir siekė jį užmušti, nes jis padarė tai sabato dieną.'),
  (@b43, 5, 17, 'Bet Jėzus jiems atsakė: „Mano Tėvas lig šiolei dirba, ir aš dirbu“.'),
  (@b43, 5, 18, 'Todėl žydai dar labiau siekė jį nužudyti, nes jis ne tik laužė sabatą, bet ir sakė, kad Dievas yra jo Tėvas, darydamas save lygų Dievui.'),
  (@b43, 5, 19, 'Tada Jėzus atsakydamas tarė jiems: „Iš tiesų, iš tiesų sakau jums: Sūnus negali nieko daryti iš savęs, bet tai, ką mato Tėvą darant; nes ką jis daro, tą taip pat daro ir jo Sūnus.'),
  (@b43, 5, 20, 'Nes Tėvas myli Sūnų ir jam parodo visa, ką jis pats daro; ir jis parodys jam didesnių darbų negu šitie, kad stebėtumėtės.'),
  (@b43, 5, 21, 'Nes kaip Tėvas prikelia mirusiuosius ir juos atgaivina; taip ir Sūnus atgaivina, ką jis nori.'),
  (@b43, 5, 22, 'Nes Tėvas neteisia nei vieno, bet visą teismą pavedė Sūnui,'),
  (@b43, 5, 23, 'idant visi gerbtų Sūnų, kaip jie gerbia ir Tėvą. Kas negerbia Sūnaus, negerbia Tėvo, kuris jį siuntė.'),
  (@b43, 5, 24, 'Iš tiesų, iš tiesų sakau jums: kas klauso mano žodžio ir tiki mane siuntusįjį, turi amžinąjį gyvenimą ir neateis į pasmerkimą; bet yra perėjęs iš mirties į gyvenimą.'),
  (@b43, 5, 25, 'Iš tiesų, iš tiesų sakau jums: ateina valanda, ir jau yra, kai mirusieji išgirs Dievo Sūnaus balsą; ir tie, kurie išgirs, gyvens.'),
  (@b43, 5, 26, 'Nes kaip Tėvas turi gyvybę savyje, taip jis yra davęs ir Sūnui turėti gyvybę savyje;'),
  (@b43, 5, 27, 'ir taip pat davė jam valdžią vykdyti teismą, nes jis yra žmogaus Sūnus.'),
  (@b43, 5, 28, 'Nesistebėkite tuo, nes ateina valanda, kurioje visi, esantys kapuose, išgirs jo balsą'),
  (@b43, 5, 29, 'ir išeis; tie, kurie darė gera – į gyvenimo prisikėlimą; o tie, kurie darė pikta – į pasmerkimo prisikėlimą.'),
  (@b43, 5, 30, 'Iš savęs aš nieko negaliu padaryti; aš teisiu, kaip girdžiu, ir mano teismas yra teisingas; nes ieškau ne savo valios, bet valios Tėvo, kuris mane siuntė.'),
  (@b43, 5, 31, 'Jei liudiju apie save, mano liudijimas nėra teisingas.'),
  (@b43, 5, 32, 'Yra kitas, kuris apie mane liudija; ir žinau, kad liudijimas, kurį jis apie mane liudija, yra teisingas.'),
  (@b43, 5, 33, 'Jūs siuntėte pas Joną, ir jis liudijo tiesą.'),
  (@b43, 5, 34, 'Bet aš nepriimu liudijimo iš žmogaus, bet sakau tai, kad būtumėte išgelbėti.'),
  (@b43, 5, 35, 'Jis buvo deganti ir spindinti šviesa, ir jūs kurį laiką norėjote pasidžiaugti jo šviesoje.'),
  (@b43, 5, 36, 'Bet aš turiu didesnį liudijimą negu tą iš Jono, nes darbai, kuriuos Tėvas man davė užbaigti, tie darbai, kuriuos darau, liudija apie mane, kad Tėvas mane siuntė.'),
  (@b43, 5, 37, 'Ir pats Tėvas, kuris mane siuntė, yra paliudijęs apie mane. Jūs nesate nei jo balso kada nors girdėję, nei matę jo pavidalo.'),
  (@b43, 5, 38, 'Ir neturite jo žodžio jumyse pasiliekančio, nes netikite tuo, kurį jis siuntė.'),
  (@b43, 5, 39, 'Tyrinėkite Raštus; nes manote juose turį amžinąjį gyvenimą; o jie yra tie, kurie liudija apie mane.'),
  (@b43, 5, 40, 'Ir nenorite ateiti pas mane, kad turėtumėte gyvenimą.'),
  (@b43, 5, 41, 'Aš nepriimu garbės iš žmonių.'),
  (@b43, 5, 42, 'Bet aš jus pažįstu, kad neturite savyje Dievo meilės.'),
  (@b43, 5, 43, 'Aš atėjau savo Tėvo vardu, bet jūs manęs nepriimate; jei kitas ateis savo vardu, tą priimsite.'),
  (@b43, 5, 44, 'Kaip galite tikėti jūs, vieni iš kitų priimantys garbę, o neieškantys garbės, kuri ateina vien iš Dievo?'),
  (@b43, 5, 45, 'Nemanykite, kad aš jus kaltinsiu Tėvui; yra vienas, kuris jus kaltina, būtent Mozė, kuriuo jūs pasitikite.'),
  (@b43, 5, 46, 'Nes jei būtumėte tikėję Moze, tikėtumėte manimi; nes jis parašė apie mane.'),
  (@b43, 5, 47, 'Bet jei netikite jo raštais, kaip tikėsite mano žodžiais?“'),
  (@b43, 6, 1, 'Po šių dalykų Jėzus nuėjo už Galilėjos jūros, kuri yra Tiberijo jūra.'),
  (@b43, 6, 2, 'Ir juo sekė didžiulė minia, nes jie matė jo stebuklus, kuriuos jis darė ant ligonių.'),
  (@b43, 6, 3, 'Ir Jėzus užlipo į kalną, ir ten atsisėdo su savo mokiniais.'),
  (@b43, 6, 4, 'Ir buvo arti Apėjimas, žydų šventė.'),
  (@b43, 6, 5, 'Tada Jėzus, pakėlęs akis ir pamatęs didelį būrį, ateinantį pas jį, sako Pilypui: „Iš kur nupirksime duonos, kad šitie galėtų valgyti?“'),
  (@b43, 6, 6, 'Ir jis tai sakė mėgindamas jį, nes jis pats žinojo, ką darysiąs.'),
  (@b43, 6, 7, 'Pilypas jam atsakė: „Už du šimtus denarų duonos jiems neužteks, kad kiekvienas iš jų gautų po truputį“.'),
  (@b43, 6, 8, 'Vienas iš jo mokinių, Andriejus, Simono Petro brolis, jam sako:'),
  (@b43, 6, 9, '„Čia yra berniukas, kuris turi penkis miežinius kepalus ir dvi žuveles, bet kas tai yra tokiai daugybei?“'),
  (@b43, 6, 10, 'Ir Jėzus tarė: „Susodinkite žmones“. Na, o toje vietoje buvo daug žolės. Taigi susėdo vyrų, skaičiumi apie penkis tūkstančius.'),
  (@b43, 6, 11, 'Ir Jėzus paėmė kepalus ir padėkojęs išdalino mokiniams, o mokiniai susėdusiems; ir taip pat iš žuvų, kiek jie norėjo.'),
  (@b43, 6, 12, 'Kai jie buvo pasotinti, jis tarė savo mokiniams: „Surinkite atlikusias nuolaužas, kad niekas neprapultų“.'),
  (@b43, 6, 13, 'Taigi jie surinko jas ir pripildė dvylika pintinių nuolaužų iš penkių miežinių kepalų, kurių atliko valgiusiems.'),
  (@b43, 6, 14, 'Tada tie žmonės, pamatę stebuklą, kurį padarė Jėzus, tarė: „Šitas iš tiesų yra tas pranašas, kuris turi ateiti į pasaulį“.'),
  (@b43, 6, 15, 'Todėl Jėzus, supratęs, kad jie nori ateiti ir paimti jį jėga, idant padarytų jį karaliumi, vėl pasitraukė pats vienas į kalną.'),
  (@b43, 6, 16, 'Ir atėjus vakarui jo mokiniai nusileido prie jūros'),
  (@b43, 6, 17, 'ir įėję į laivą plaukė per jūrą Kafernaumo link. Ir jau buvo tamsu, o Jėzus nebuvo pas juos atėjęs.'),
  (@b43, 6, 18, 'Ir sukilo jūra, nes pūtė didelis vėjas.'),
  (@b43, 6, 19, 'Taigi, jiems nusiyrus apie dvidešimt penkias ar trisdešimt stadijų, jie pamato Jėzų, einantį ant jūros ir besiartinantį prie laivo; ir jie išsigando.'),
  (@b43, 6, 20, 'Bet jis sako jiems: „Tai aš; nebijokite“.'),
  (@b43, 6, 21, 'Tada jie noriai priėmė jį į laivą, ir tuojau laivas buvo prie sausumos, kur jie keliavo.'),
  (@b43, 6, 22, 'Ateinančią dieną tauta, stovinti kitoje jūros pusėje, pamatė, kad ten nebuvo jokios kitos valties, išskyrus tą, į kurią buvo įlipę jo mokiniai, ir kad Jėzus nėjo kartu su savo mokiniais į valtį, bet jo mokiniai buvo išvykę vieni'),
  (@b43, 6, 23, '(tačiau atkeliavo kitos valtys iš Tiberijaus arti tos vietos, kur jie valgė duoną po to, kai Viešpats padėkojo);'),
  (@b43, 6, 24, 'todėl kai tauta pamatė, kad ten nebuvo Jėzaus nei jo mokinių, tai ir jie sulipo į laivus ir atvyko į Kafernaumą, ieškodami Jėzaus.'),
  (@b43, 6, 25, 'Ir suradę jį kitoje jūros pusėje jie tarė jam: „Rabi, kada čia atvykai?“'),
  (@b43, 6, 26, 'Jėzus jiems atsakydamas tarė: „Iš tiesų, iš tiesų sakau jums: jūs manęs ieškote ne todėl, kad matėte stebuklus, bet todėl, kad valgėte kepalų ir pasisotinote.'),
  (@b43, 6, 27, 'Plušėkite ne dėl žūvančio maisto, bet dėl maisto, išliekančio amžinajam gyvenimui, kurį jums duos žmogaus Sūnus; nes jį užantspaudavo Dievas Tėvas“.'),
  (@b43, 6, 28, 'Tada jie tarė jam: „Ką mums daryti, kad dirbtume Dievo darbus?“'),
  (@b43, 6, 29, 'Jėzus atsakydamas tarė jiems: „Tai yra Dievo darbas, kad tikėtumėte tą, kurį jis siuntė“.'),
  (@b43, 6, 30, 'Tad jie tarė jam: „Tai kokį ženklą tu rodai, kad matytume ir tikėtume tavimi? Ką tu darai?'),
  (@b43, 6, 31, 'Mūsų tėvai valgė maną dykumoje; kaip yra parašyta: ‘Jis davė jiems valgyti duonos iš dangaus’“.'),
  (@b43, 6, 32, 'Tada Jėzus jiems tarė: „Iš tiesų, iš tiesų sakau jums: Mozė jums nedavė tos duonos iš dangaus, bet mano Tėvas duoda jums tikrąją duoną iš dangaus.'),
  (@b43, 6, 33, 'Nes Dievo duona yra tas, kuris nužengia iš dangaus ir duoda pasauliui gyvybę“.'),
  (@b43, 6, 34, 'Tada jie tarė jam: „Viešpatie, visada duok mums šitos duonos“.'),
  (@b43, 6, 35, 'O Jėzus jiems tarė: „Aš esu gyvenimo duona: kas ateina pas mane, niekada nebealks, ir kas į mane tiki, niekada nebetrokš.'),
  (@b43, 6, 36, 'Bet aš jums sakiau, kad jūs irgi mane matėte, o netikite.'),
  (@b43, 6, 37, 'Visi, kuriuos Tėvas man duoda, ateis pas mane; ir to, kuris ateina pas mane, jokiu būdu neatmesiu.'),
  (@b43, 6, 38, 'Nes nužengiau iš dangaus ne savo valios vykdyti, bet valios to, kuris mane siuntė.'),
  (@b43, 6, 39, 'Ir šita yra valia Tėvo, kuris mane siuntė, kad neprarasčiau nieko iš viso to, ką jis man yra davęs, bet kad paskutiniąją dieną tai prikelčiau.'),
  (@b43, 6, 40, 'Ir šita yra valia to, kuris mane siuntė, kad kiekvienas, kuris mato Sūnų ir į jį tiki, turėtų amžinąjį gyvenimą; ir aš jį prikelsiu paskutiniąją dieną“.'),
  (@b43, 6, 41, 'Tada žydai ant jo murmėjo, nes jis sakė: „Aš esu duona, kuri nužengė iš dangaus“.'),
  (@b43, 6, 42, 'Ir jie tarė: „Argi šitas – ne Jėzus, Juozapo sūnus, kurio tėvą ir motiną pažįstame? Tad kaipgi yra, kad jis sako: ‘Aš nužengiau iš dangaus’?“'),
  (@b43, 6, 43, 'Todėl Jėzus jiems atsakydamas tarė: „Nemurmėkite tarpusavyje.'),
  (@b43, 6, 44, 'Niekas negali ateiti pas mane, jei jo nepatrauktų Tėvas, kuris mane siuntė; ir aš jį prikelsiu paskutiniąją dieną.'),
  (@b43, 6, 45, 'Yra parašyta pranašuose: ‘Ir jie visi bus Dievo mokomi’. Todėl kiekvienas, kuris girdėjo ir išmoko iš Tėvo, ateina pas mane.'),
  (@b43, 6, 46, 'Ne, kad kas yra matęs Tėvą, išskyrus tą, kuris yra iš Dievo, tas yra matęs Tėvą.'),
  (@b43, 6, 47, 'Iš tiesų, iš tiesų sakau jums: kas tiki į mane, tas turi amžinąjį gyvenimą.'),
  (@b43, 6, 48, 'Aš esu ta gyvenimo duona.'),
  (@b43, 6, 49, 'Jūsų tėvai dykumoje valgė maną, bet yra mirę.'),
  (@b43, 6, 50, 'Šita yra duona, kuri nužengia iš dangaus, kad kas jos valgytų ir nemirtų.'),
  (@b43, 6, 51, 'Aš esu ta gyvoji duona, kuri nužengė iš dangaus: jei kas valgys šitos duonos, gyvens per amžius; ir duona, kurios duosiu, yra mano kūnas, kurį duosiu už pasaulio gyvenimą“.'),
  (@b43, 6, 52, 'Todėl žydai ginčijosi tarpusavyje, sakydami: „Kaipgi šitas gali mums duoti valgyti savo kūną?“'),
  (@b43, 6, 53, 'Tada Jėzus jiems tarė: „Iš tiesų, iš tiesų sakau jums: jei nevalgysite žmogaus Sūnaus kūno ir negersite jo kraujo, neturėsite savyje gyvenimo.'),
  (@b43, 6, 54, 'Kas valgo mano kūną ir geria mano kraują, turi amžinąjį gyvenimą; ir aš jį prikelsiu paskutiniąją dieną.'),
  (@b43, 6, 55, 'Nes mano kūnas tikrai yra valgis, ir mano kraujas tikrai yra gėrimas.'),
  (@b43, 6, 56, 'Kas valgo mano kūną ir geria mano kraują, gyvena manyje, o aš jame.'),
  (@b43, 6, 57, 'Kaip gyvasis Tėvas mane siuntė, ir aš gyvenu per Tėvą, taip ir tas, kuris mane valgo, gyvens per mane.'),
  (@b43, 6, 58, 'Ši yra ta duona, kuri nužengė iš dangaus; ne taip, kaip jūsų tėvai valgė maną ir yra mirę; kas valgo šitos duonos, tas gyvens per amžius“.'),
  (@b43, 6, 59, 'Šiuos dalykus jis kalbėjo sinagogoje, mokydamas Kafernaume.'),
  (@b43, 6, 60, 'Todėl daugelis jo mokinių tai išgirdę sakė: „Tai kietas pasakymas; kas gali to klausyti?“'),
  (@b43, 6, 61, 'Kai Jėzus pažino savyje, kad jo mokiniai dėl to murmėjo, tarė jiems: „Ar tai jus piktina?'),
  (@b43, 6, 62, 'O kas, jei pamatysite žmogaus Sūnų pakylantį ten, kur jis buvo pirmiau?'),
  (@b43, 6, 63, 'Tai Dvasia, kuri atgaivina; kūnas neduoda jokios naudos; žodžiai, kuriuos jums kalbu, yra Dvasia ir yra gyvenimas.'),
  (@b43, 6, 64, 'Bet yra kai kurie iš jūsų, kurie netiki“. Nes Jėzus nuo pradžių žinojo, kas buvo tie, kurie netikėjo, ir kas jį išduos.'),
  (@b43, 6, 65, 'Ir jis tarė: „Todėl jums sakiau, kad niekas negali ateiti pas mane, jei tai jam nebūtų duota mano Tėvo“.'),
  (@b43, 6, 66, 'Nuo to laiko daugelis iš jo mokinių nuėjo atgal ir daugiau su juo nebevaikščiojo.'),
  (@b43, 6, 67, 'Tada Jėzus tarė dvylikai: „Ar ir jūs norite pasišalinti?“'),
  (@b43, 6, 68, 'Tada Simonas Petras jam atsakė: „Viešpatie, pas ką mes eisime? Tu turi amžinojo gyvenimo žodžius.'),
  (@b43, 6, 69, 'Ir mes tikime ir esame įsitikinę, kad tu esi tas Kristus, gyvojo Dievo Sūnus“.'),
  (@b43, 6, 70, 'Jėzus jiems atsakė: „Ar ne aš jus, dvylika, išsirinkau, o vienas iš jūsų yra velnias?“'),
  (@b43, 6, 71, 'Jis kalbėjo apie Judą Iskariotą, Simono sūnų, nes tai buvo jis, kuris turėjo jį išduoti, būdamas vienas iš dvylikos.'),
  (@b43, 7, 1, 'Po šių dalykų Jėzus vaikščiojo po Galilėją, nes jis nenorėjo vaikščioti po žydiją, nes žydai siekė jį užmušti.'),
  (@b43, 7, 2, 'Na, o buvo arti žydų Padangčių šventė.'),
  (@b43, 7, 3, 'Todėl jo broliai jam tarė: „Išeik iš čia ir eik į Judėją, kad ir tavo mokiniai pamatytų darbus, kuriuos tu darai.'),
  (@b43, 7, 4, 'Nes nėra nei vieno, kuris ką nors daro slapčia, o pats siekia, kad būtų žinomas viešai. Jei darai šituos dalykus, parodyk save pasauliui“.'),
  (@b43, 7, 5, 'Nes nei jo broliai juo netikėjo.'),
  (@b43, 7, 6, 'Tada Jėzus tarė jiems: „Mano laikas dar neatėjo, bet jūsų laikas visuomet tinkamas.'),
  (@b43, 7, 7, 'Pasaulis negali jūsų nekęsti; bet manęs jis nekenčia, nes aš liudiju apie jį, kad jo darbai yra pikti.'),
  (@b43, 7, 8, 'Eikite aukštyn į šią šventę; aš dar neinu aukštyn į šią šventę, nes mano laikas dar pilnai neatėjo“.'),
  (@b43, 7, 9, 'Pasakęs jiems tuos žodžius, jis dar pasiliko Galilėjoje.'),
  (@b43, 7, 10, 'Bet kai jo broliai buvo nuėję aukštyn, tada ir jis nuėjo aukštyn į šventę, ne viešai, bet tartum slapčia.'),
  (@b43, 7, 11, 'Tada žydai ieškojo jo šventėje ir sakė: „Kur jis yra?“'),
  (@b43, 7, 12, 'Ir apie jį tautoje buvo daug murmėjimo, nes vieni sakė: „Jis yra geras žmogus“, kiti sakė: „Ne; jis suvedžioja tautą“.'),
  (@b43, 7, 13, 'Tačiau niekas dėl žydų baimės viešai apie jį nekalbėjo.'),
  (@b43, 7, 14, 'Na, o šventei įpusėjus Jėzus nuėjo aukštyn į šventyklą ir mokė.'),
  (@b43, 7, 15, 'Ir žydai stebėjosi, sakydami: „Kaip šitas, niekada nesimokęs, žino raides?“'),
  (@b43, 7, 16, 'Jėzus jiems atsakydamas tarė: „Mano mokslas yra ne mano, bet to, kuris mane siuntė.'),
  (@b43, 7, 17, 'Jei kas nori vykdyti jo valią, tas pažins tą mokslą – ar tai yra iš Dievo, ar aš kalbu iš savęs.'),
  (@b43, 7, 18, 'Kas iš savęs kalba, tas ieško savo šlovės, bet kas ieško šlovės to, kuris jį siuntė, tas yra tikras, ir jame nėra neteisumo.'),
  (@b43, 7, 19, 'Argi Mozė jums nedavė įstatymo? Tačiau nei vienas iš jūsų nesilaiko įstatymo. Kodėl ruošiatės mane užmušti?“'),
  (@b43, 7, 20, 'Tauta atsakydama tarė: „Tu turi velnią; kas gi ruošiasi tave nužudyti?“'),
  (@b43, 7, 21, 'Jėzus atsakydamas tarė jiems: „Aš padariau vieną darbą, o jūs visi stebitės.'),
  (@b43, 7, 22, 'Dėl to Mozė davė jums apipjaustymą (ne todėl, kad jis yra iš Mozės, bet iš tėvų); ir jūs sabato dieną apipjaustote žmogų.'),
  (@b43, 7, 23, 'Jei žmogus sabato dieną gauna apipjaustymą, kad nebūtų sulaužytas Mozės įstatymas, ar jūs ant manęs pykstate, kad sabato dieną visą žmogų padariau sveiką?'),
  (@b43, 7, 24, 'Neteiskite pagal išorę, bet teiskite teisingu teismu“.'),
  (@b43, 7, 25, 'Tada kai kurie iš tų, iš Jeruzalės, tarė: „Ar tai ne tas, kurį jie siekia užmušti?'),
  (@b43, 7, 26, 'Bet štai jis drąsiai kalba, ir jie nieko jam nesako. Ar valdovai tikrai žino, kad šitas yra pats Kristus?'),
  (@b43, 7, 27, 'Tačiau mes žinome šitą žmogų, iš kur jis yra; bet kai ateina Kristus, niekas nežino, iš kur jis“.'),
  (@b43, 7, 28, 'Tada Jėzus mokydamas šaukė šventykloje, sakydamas: „Jūs mane ir pažįstate, ir žinote, iš kur esu; ir aš neatėjau iš savęs, bet tas, kuris mane siuntė, yra tikras, kurio jūs nepažįstate.'),
  (@b43, 7, 29, 'Bet aš jį pažįstu, nes esu iš jo, ir jis mane siuntė“.'),
  (@b43, 7, 30, 'Tada jie ieškojo jį sučiupti, bet nei vienas nepridėjo prie jo rankų, nes jo valanda dar nebuvo atėjusi.'),
  (@b43, 7, 31, 'Ir daugelis iš tautos įtikėjo į jį ir sakė: „Kai Kristus ateis, ar jis padarys daugiau stebuklų už tuos, kuriuos šitas padarė?“'),
  (@b43, 7, 32, 'Fariziejai girdėjo, kad tauta tai murmėjo apie jį; ir fariziejai bei vyriausieji kunigai pasiuntė pareigūnus jo suimti.'),
  (@b43, 7, 33, 'Tada Jėzus tarė jiems: „Dar trumpam esu su jumis, ir tada eisiu pas tą, kuris mane siuntė.'),
  (@b43, 7, 34, 'Jūs manęs ieškosite ir nerasite; ir kur aš esu, ten negalite ateiti“.'),
  (@b43, 7, 35, 'Tada žydai tarp savęs tarė: „Kur jis eis, kad jo nerasime? Ar jis eis pas išsklaidytuosius tarp pagonių ir mokys pagonis?'),
  (@b43, 7, 36, 'Kas tai per pasakymas, kurį jis sakė: ‘Jūs manęs ieškosite ir nerasite; ir kur aš esu, ten negalite ateiti?’“'),
  (@b43, 7, 37, 'Paskutinę dieną, tą didžiąją šventės dieną, Jėzus atsistojo ir šaukė, sakydamas: „Jei kas trokšta, teateina pas mane ir tegeria.'),
  (@b43, 7, 38, 'Kas į mane tiki, kaip sakė Raštas, iš jo pilvo tekės gyvojo vandens upės“'),
  (@b43, 7, 39, '(bet tai jis kalbėjo apie Dvasią, kurią turės gauti tie, kurie įtiki į jį, nes Šventoji Dvasia dar nebuvo duota; nes Jėzus dar nebuvo pašlovintas).'),
  (@b43, 7, 40, 'Todėl daugelis iš tautos, išgirdę šitą pasakymą, sakė: „Iš tiesų šitas yra Pranašas“.'),
  (@b43, 7, 41, 'Kiti sakė: „Šitas yra Kristus“. Bet kai kurie sakė: „Ar Kristus ateis iš Galilėjos?'),
  (@b43, 7, 42, 'Argi Raštas nesakė, kad Kristus ateina iš Dovydo sėklos ir iš Betliejaus miestelio, kur buvo Dovydas?“'),
  (@b43, 7, 43, 'Taigi dėl jo tautoje buvo susiskaldymas.'),
  (@b43, 7, 44, 'Ir kai kurie iš jų norėjo jį suimti; bet nei vienas nepridėjo prie jo rankų.'),
  (@b43, 7, 45, 'Tada pareigūnai atėjo pas vyriausiuosius kunigus ir fariziejus, o jie tarė jiems: „Kodėl neatvedėte jo?“'),
  (@b43, 7, 46, 'Pareigūnai atsakė: „Niekada dar žmogus nekalbėjo kaip šitas žmogus“.'),
  (@b43, 7, 47, 'Tada fariziejai jiems atsakė: „Ar ir jūs esate suvedžioti?'),
  (@b43, 7, 48, 'Ar kuris iš valdovų ar iš fariziejų į jį įtikėjo?'),
  (@b43, 7, 49, 'Bet šita tauta, kuri nežino įstatymo, yra prakeikta“.'),
  (@b43, 7, 50, 'Nikodemas jiems sako (tas, kuris atėjo naktį pas Jėzų, būdamas vienas iš jų):'),
  (@b43, 7, 51, '„Ar mūsų įstatymas teisia kurį žmogų prieš tai jo neišklausęs ir nesužinojęs, ką jis daro?“'),
  (@b43, 7, 52, 'Jie atsakydami tarė jam: „Ar ir tu iš Galilėjos? Patyrinėk ir pažiūrėk, nes iš Galilėjos neiškyla joks pranašas“.'),
  (@b43, 7, 53, 'Ir kiekvienas nuėjo į savo namus.'),
  (@b43, 8, 1, 'Jėzus nuėjo į Alyvų kalną.'),
  (@b43, 8, 2, 'Ir anksti ryte jis vėl atėjo į šventyklą, ir visa tauta atėjo pas jį; ir jis atsisėdo ir juos mokė.'),
  (@b43, 8, 3, 'Ir raštininkai bei fariziejai atvedė pas jį moterį, pagautą svetimaujant; ir pastatę ją į tarpą'),
  (@b43, 8, 4, 'sako jam: „Mokytojau, šita moteris buvo pagauta svetimaujant, pačiame veiksme.'),
  (@b43, 8, 5, 'Mozė gi įstatyme mums įsakė, kad tokia turi būti užmėtyta akmenimis; bet ką tu sakai?“'),
  (@b43, 8, 6, 'Tai jie sakė gundydami jį, kad turėtų kuo jį apkaltinti. Bet Jėzus pasilenkė ir pirštu rašė ant žemės, tarsi jų negirdėdamas.'),
  (@b43, 8, 7, 'Taigi jiems nesiliaujant jo klausinėti jis išsitiesė ir jiems tarė: „Kas tarp jūsų yra be nuodėmės, tas pirmas temeta į ją akmenį“.'),
  (@b43, 8, 8, 'Ir vėl jis pasilenkė ir rašė ant žemės.'),
  (@b43, 8, 9, 'Ir tie, kurie tai išgirdo, savo sąžinės įtikinti išėjo vienas po kito, pradedant nuo vyriausiojo iki paskutiniojo; ir Jėzus liko vienas, ir moteris, stovinti viduryje.'),
  (@b43, 8, 10, 'Kai Jėzus išsitiesė ir nebematė nei vieno, bet tik moterį, jis tarė jai: „Moterie, kur yra tie tavo kaltintojai? Nei vienas tavęs nepasmerkė?“'),
  (@b43, 8, 11, 'Ji tarė: „Nei vienas, Viešpatie“. Ir Jėzus jai tarė: „Nei aš tavęs nesmerkiu; eik ir nebenusidėk“.'),
  (@b43, 8, 12, 'Tada Jėzus vėl jiems kalbėjo, sakydamas: „Aš esu pasaulio šviesa; kas seka paskui mane, tas nevaikščios tamsoje, bet turės gyvenimo šviesą“.'),
  (@b43, 8, 13, 'Todėl fariziejai jam tarė: „Tu apie save liudiji; tavo liudijimas netikras“.'),
  (@b43, 8, 14, 'Jėzus atsakydamas tarė jiems: „Nors ir liudiju apie save, mano liudijimas yra tikras; nes žinau, iš kur atėjau ir kur einu; bet jūs nežinote, iš kur ateinu ir kur einu.'),
  (@b43, 8, 15, 'Jūs teisiate pagal kūną; aš neteisiu nei vieno.'),
  (@b43, 8, 16, 'Bet jei ir teisiu, mano teismas yra teisingas, nes esu ne vienas, bet aš ir Tėvas, kuris mane siuntė.'),
  (@b43, 8, 17, 'O ir jūsų įstatyme yra parašyta, kad dviejų žmonių liudijimas yra tikras.'),
  (@b43, 8, 18, 'Aš esu tas, kuris liudija apie save, ir Tėvas, kuris mane siuntė, liudija apie mane“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b43, 8, 19, 'Tada jie tarė jam: „Kur yra tavo Tėvas?“ Jėzus atsakė: „Jūs nei manęs nepažįstate, nei mano Tėvo; jei pažintumėte mane, pažintumėte ir mano Tėvą“.'),
  (@b43, 8, 20, 'Šituos žodžius Jėzus kalbėjo iždinėje, kai jis mokė šventykloje, ir niekas nepridėjo prie jo rankų; nes jo valanda dar nebuvo atėjusi.'),
  (@b43, 8, 21, 'Tada Jėzus vėl jiems tarė: „Aš einu, o jūs manęs ieškosite ir mirsite savo nuodėmėse; kur aš einu, jūs negalite ateiti“.'),
  (@b43, 8, 22, 'Tada žydai tarė: „Ar jis nusižudys? Nes jis sako: ‘Kur aš einu, jūs negalite ateiti’“.'),
  (@b43, 8, 23, 'Ir jis tarė jiems: „Jūs esate iš žemai; aš esu iš aukštai; jūs iš šito pasaulio; aš nesu iš šito pasaulio.'),
  (@b43, 8, 24, 'Todėl sakiau jums, kad mirsite savo nuodėmėse; nes jei netikite, kad esu tas, mirsite savo nuodėmėse“.'),
  (@b43, 8, 25, 'Tada jie tarė jam: „Kas tu esi?“ Ir Jėzus jiems sako: „Tas pats, kaip sakiau jums nuo pradžios.'),
  (@b43, 8, 26, 'Daug ką turiu apie jus kalbėti ir teisti, bet tas, kuris mane siuntė, yra teisingas; ir aš kalbu pasauliui tai, ką iš jo girdėjau“.'),
  (@b43, 8, 27, 'Jie nesuprato, kad jis kalbėjo jiems apie Tėvą.'),
  (@b43, 8, 28, 'Tada Jėzus tarė jiems: „Kai būsite iškėlę žmogaus Sūnų, tada pažinsite, kad esu tas ir kad nieko nedarau iš savęs; bet kalbu tai, kaip mano Tėvas mane išmokė.'),
  (@b43, 8, 29, 'Ir tas, kuris mane siuntė, yra su manimi; Tėvas nepaliko manęs vieno; nes aš visada darau tai, kas jam patinka“.'),
  (@b43, 8, 30, 'Jam kalbant tuos žodžius, daugelis įtikėjo į jį.'),
  (@b43, 8, 31, 'Tada Jėzus tarė į jį įtikėjusiems žydams: „Jei pasiliekate mano žodyje, tikrai esate mano mokiniai;'),
  (@b43, 8, 32, 'ir pažinsite tiesą, ir tiesa padarys jus laisvus“.'),
  (@b43, 8, 33, 'Jie atsakė jam: „Mes esame Abraomo sėkla ir niekada niekam nevergavome; kaipgi tu sakai: ‘Jūs būsite išlaisvinti’?“'),
  (@b43, 8, 34, 'Jėzus jiems atsakė: „Iš tiesų, iš tiesų sakau jums: kas daro nuodėmę, tas yra nuodėmės tarnas.'),
  (@b43, 8, 35, 'O tarnas nepasilieka namuose per amžius, bet Sūnus pasilieka per amžius.'),
  (@b43, 8, 36, 'Todėl jei Sūnus padarys jus laisvus, iš tikrųjų būsite laisvi.'),
  (@b43, 8, 37, 'Žinau, kad esate Abraomo sėkla; bet ieškote mane užmušti, nes mano žodis neturi jumyse vietos.'),
  (@b43, 8, 38, 'Aš kalbu tai, ką esu matęs pas savo Tėvą, o jūs darote tai, ką esate matę pas savo tėvą“.'),
  (@b43, 8, 39, 'Jie atsakė ir jam tarė: „Abraomas yra mūsų tėvas“. Jėzus jiems sako: „Jei būtumėte Abraomo vaikai, darytumėte Abraomo darbus.'),
  (@b43, 8, 40, 'Bet dabar siekiate nužudyti mane – žmogų, jums kalbėjusį tiesą, kurią girdėjau iš Dievo; šito nedarė Abraomas.'),
  (@b43, 8, 41, 'Jūs darote savo tėvo darbus“. Tada jie tarė jam: „Mes nesame gimę iš paleistuvystės; mes turime vieną Tėvą – Dievą“.'),
  (@b43, 8, 42, 'Jėzus jiems tarė: „Jei Dievas būtų jūsų Tėvas, mylėtumėte mane, nes aš išėjau ir atėjau iš Dievo; ir ne nuo savęs atėjau, bet jis mane siuntė.'),
  (@b43, 8, 43, 'Kodėl nesuprantate mano kalbos? Todėl, kad negalite klausytis mano žodžio.'),
  (@b43, 8, 44, 'Jūs esate iš savo tėvo – velnio, ir norite vykdyti savo tėvo geidulius. Jis nuo pradžios buvo žmogžudys ir nepasiliko tiesoje, nes jame nėra tiesos. Kai jis kalba melą, kalba iš savęs; nes yra melagis ir to tėvas.'),
  (@b43, 8, 45, 'O kadangi kalbu jums tiesą, manimi netikite.'),
  (@b43, 8, 46, 'Kuris iš jūsų įtikina mane nusidėjus? O jei sakau tiesą, kodėl netikite manimi?'),
  (@b43, 8, 47, 'Kas yra iš Dievo, tas klausosi Dievo žodžių; jūs todėl neklausote jų, kadangi nesate iš Dievo“.'),
  (@b43, 8, 48, 'Tada žydai atsakydami tarė jam: „Ar ne gerai sakome, kad esi samarietis ir turi velnią?“'),
  (@b43, 8, 49, 'Jėzus atsakė: „Aš neturiu velnio; bet gerbiu savo Tėvą, o jūs negerbiate manęs.'),
  (@b43, 8, 50, 'Ir aš neieškau savo šlovės; yra vienas, kuris ieško ir teisia“.'),
  (@b43, 8, 51, 'Iš tiesų, iš tiesų sakau jums: „Jei kas laikosi mano pasakymo, tas niekada nematys mirties“.'),
  (@b43, 8, 52, 'Tada žydai jam tarė: „Dabar žinome, kad tu turi velnią. Abraomas yra miręs ir pranašai; o tu sakai: ‘Jei kas laikosi mano pasakymo, tas niekada neragaus mirties’.'),
  (@b43, 8, 53, 'Ar esi didesnis už mūsų tėvą Abraomą, kuris yra miręs? Ir pranašai mirę; kuo save daraisi?“'),
  (@b43, 8, 54, 'Jėzus atsakė: „Jei gerbiu save, mano garbė yra niekas; tai mano Tėvas, kuris mane gerbia, apie kurį sakote, kad jis jūsų Dievas;'),
  (@b43, 8, 55, 'tačiau jūs jo nepažinote; bet aš jį pažįstu; o jei sakyčiau: ‘Nepažįstu jo’, būčiau toks pat melagis, kaip ir jūs; bet aš jį pažįstu ir laikausi jo pasakymo.'),
  (@b43, 8, 56, 'Jūsų tėvas Abraomas džiūgavo, kad matysiąs mano dieną; ir jis ją pamatė ir džiaugėsi“.'),
  (@b43, 8, 57, 'Tada žydai jam tarė: „Tau dar nėra nei penkiasdešimties metų, o esi matęs Abraomą?“'),
  (@b43, 8, 58, 'Jėzus jiems tarė: „Iš tiesų, iš tiesų sakau jums: pirmiau, nei buvo Abraomas, aš esu“.'),
  (@b43, 8, 59, 'Tada jie ėmėsi akmenų, kad mestų į jį, bet Jėzus pasislėpė ir, eidamas pro jų tarpą, išėjo iš šventyklos ir taip praėjo.'),
  (@b43, 9, 1, 'Ir eidamas pro šalį Jėzus pamatė žmogų, aklą nuo gimimo.'),
  (@b43, 9, 2, 'Ir jo mokiniai paklausė jo, sakydami: „Mokytojau, kas nusidėjo – šitas žmogus, ar jo tėvai, kad jis gimė aklas?“'),
  (@b43, 9, 3, 'Jėzus atsakė: „Nei šitas žmogus nusidėjo, nei jo tėvai, bet kad Dievo darbai pasireikštų jame.'),
  (@b43, 9, 4, 'Aš turiu daryti darbus to, kuris mane siuntė, kol dar yra diena; ateina naktis, kai niekas negali dirbti.'),
  (@b43, 9, 5, 'Kol esu pasaulyje, esu pasaulio šviesa“.'),
  (@b43, 9, 6, 'Taip pasakęs jis spjovė ant žemės, iš seilių padarė purvo, purvu patepė aklojo akis'),
  (@b43, 9, 7, 'ir jam tarė: „Eik, nusiplauk Siloamo (kuris išvertus reiškia „Pasiųstas“) tvenkinyje“. Taigi jis nuėjo, nusiplovė ir parėjo regintis.'),
  (@b43, 9, 8, 'Todėl kaimynai ir tie, kurie anksčiau matė jį esant aklą, tarė: „Ar jis ne tas, kuris sėdėdavo ir elgetaudavo?“'),
  (@b43, 9, 9, 'Vieni sakė: „Tai – jis“, kiti: „Jis yra panašus į aną“, bet jis sakė: „Aš esu tas“.'),
  (@b43, 9, 10, 'Todėl jie tarė jam: „Kaip buvo atvertos tavo akys?“'),
  (@b43, 9, 11, 'Jis atsakydamas tarė: „Žmogus, vadinamas Jėzumi, padarė purvo ir patepė mano akis, ir tarė man: ‘Eik į Siloamo tvenkinį ir nusiplauk’; ir aš nuėjau, nusiploviau ir praregėjau.'),
  (@b43, 9, 12, 'Tada jie tarė jam: „Kur jis yra?“ Jis tarė: „Nežinau“.'),
  (@b43, 9, 13, 'Jie atvedė pas fariziejus tą, kuris anksčiau buvo aklas.'),
  (@b43, 9, 14, 'O buvo sabato diena, kai Jėzus padarė purvo ir atvėrė jo akis.'),
  (@b43, 9, 15, 'Tada vėl jo klausė ir fariziejai, kaip jis praregėjo. Jis tarė jiems: „Jis uždėjo ant mano akių purvo, aš nusiploviau ir regiu“.'),
  (@b43, 9, 16, 'Todėl kai kurie fariziejai sakė: „Šitas žmogus ne iš Dievo, nes jis nesilaiko sabato dienos“. Kiti sakė: „Kaip gali žmogus, kuris yra nusidėjėlis, daryti tokius stebuklus?“ Ir tarp jų buvo susiskaldymas.'),
  (@b43, 9, 17, 'Jie vėl sako aklajam: „Ką tu sakai apie jį, kad jis atvėrė tavo akis?“ Jis tarė: „Jis yra pranašas“.'),
  (@b43, 9, 18, 'Bet žydai netikėjo apie jį, kad jis buvęs aklas ir praregėjo, kol pasišaukė tėvus to, kuris praregėjo.'),
  (@b43, 9, 19, 'Ir jie paklausė jų, sakydami: „Ar šitas yra jūsų sūnus, kuris, sakote, gimė aklas? Tai kaipgi jis dabar regi?“'),
  (@b43, 9, 20, 'Jo tėvai jiems atsakydami tarė: „Žinome, kad šitas yra mūsų sūnus ir kad jis gimė aklas,'),
  (@b43, 9, 21, 'bet kokiu būdu jis dabar regi, nežinome; arba kas atvėrė jo akis, mes nežinome; jis pilnametis, jo klauskite, jis pats kalbės už save“.'),
  (@b43, 9, 22, 'Šituos žodžius kalbėjo jo tėvai, nes jie bijojo žydų; nes žydai jau buvo susitarę, kad jei kas išpažins, kad jis yra Kristus, tas bus išvarytas iš sinagogos“.'),
  (@b43, 9, 23, 'Todėl jo tėvai tarė: „Jis yra pilnametis; jo klauskite“.'),
  (@b43, 9, 24, 'Tada jie vėl pašaukė tą žmogų, kuris buvo aklas, ir jam tarė: „Duok Dievui gyrių; mes žinome, kad šitas žmogus yra nusidėjėlis“.'),
  (@b43, 9, 25, 'Jis atsakydamas tarė: „Ar jis nusidėjėlis ar ne, nežinau; viena žinau, kad buvau aklas, dabar regiu“.'),
  (@b43, 9, 26, 'Tada jie vėl tarė jam: „Ką jis tau padarė? Kaip jis atvėrė tavo akis?“'),
  (@b43, 9, 27, 'Jis atsakė jiems: „Jau sakiau jums, bet nesiklausėte; kodėl vėl norite tai girdėti? Ar ir jūs norite būti jo mokiniai?“'),
  (@b43, 9, 28, 'Tada jie keikė jį ir tarė: „Tu esi jo mokinys; bet mes Mozės mokiniai.'),
  (@b43, 9, 29, 'Mes žinome, kad Dievas kalbėjo Mozei; bet dėl šito mes nežinome, iš kur jis“.'),
  (@b43, 9, 30, 'Tas žmogus atsakydamas tarė jiems: „Todėl nuostabu tai, kad nežinote, iš kur jis yra, tačiau jis atvėrė mano akis.'),
  (@b43, 9, 31, 'Žinome gi, kad Dievas neišklauso nusidėjėlių, bet jei kas yra Dievo garbintojas ir vykdo jo valią, tą jis išklauso.'),
  (@b43, 9, 32, 'Nuo pasaulio pradžios nėra girdėta, kad kas būtų atvėręs akis to, kuris gimė aklas.'),
  (@b43, 9, 33, 'Jei šitas nebūtų iš Dievo, jis nieko negalėtų padaryti“.'),
  (@b43, 9, 34, 'Jie atsakė ir jam tarė: „Tu visas gimei nuodėmėse, ir mus mokai?“ Ir jie išmetė jį lauk.'),
  (@b43, 9, 35, 'Jėzus išgirdo, kad jie išmetė jį; ir suradęs jį, jam tarė: „Ar tiki į Dievo Sūnų?“'),
  (@b43, 9, 36, 'Jis atsakydamas tarė: „Kas jis, Viešpatie, kad galėčiau į jį tikėti?“'),
  (@b43, 9, 37, 'Ir Jėzus jam tarė: „Tu jį matei, ir tai tas, kuris kalba su tavimi“.'),
  (@b43, 9, 38, 'Ir jis tarė: „Viešpatie, aš tikiu“. Ir jis pagarbino jį.'),
  (@b43, 9, 39, 'Ir Jėzus tarė: „Dėl teismo atėjau į šį pasaulį, kad tie, kurie nemato, galėtų matyti; o tie, kurie mato, taptų akli“.'),
  (@b43, 9, 40, 'Ir kai kurie iš fariziejų, kurie buvo su juo, išgirdo tuos žodžius ir jam tarė: „Ar ir mes akli?“'),
  (@b43, 9, 41, 'Jėzus jiems tarė: „Jei būtumėte akli, neturėtumėte nuodėmės, bet dabar sakote: ‘Mes regime’; todėl jūsų nuodėmė pasilieka“.'),
  (@b43, 10, 1, '„Iš tiesų, iš tiesų sakau jums: kas įeina į avidę ne pro duris, bet įlipa kokiu kitu keliu, tas yra vagis ir plėšikas.'),
  (@b43, 10, 2, 'Tačiau kas įeina pro duris, tas yra avių ganytojas.'),
  (@b43, 10, 3, 'Jam durininkas atidaro; ir avys klauso jo balso, ir jis šaukia savąsias avis vardais ir jas išveda.'),
  (@b43, 10, 4, 'Ir išleidęs savąsias avis jis eina jų priešakyje, ir avys seka paskui jį, nes jos pažįsta jo balsą.'),
  (@b43, 10, 5, 'O paskui svetimą jos neseks, bet nuo jo bėgs, nes jos nepažįsta svetimųjų balso“.'),
  (@b43, 10, 6, 'Jėzus kalbėjo jiems šį palyginimą, bet jie nesuprato, kas tai, ką jis kalbėjo jiems.'),
  (@b43, 10, 7, 'Tada Jėzus vėl jiems tarė: „Iš tiesų, iš tiesų sakau jums: aš esu avių durys.'),
  (@b43, 10, 8, 'Visi, kurie kada nors atėjo pirma manęs, yra vagys ir plėšikai, bet avys jų neklausė.'),
  (@b43, 10, 9, 'Aš esu durys; jei kas įeina per mane, tas bus išgelbėtas ir įeis, ir išeis, ir ras ganyklą.'),
  (@b43, 10, 10, 'Vagis ateina ne kam kitam, kaip tiktai vogti, žudyti ir naikinti; aš atėjau, kad jie turėtų gyvenimą ir kad gausiau jo turėtų.'),
  (@b43, 10, 11, 'Aš esu gerasis ganytojas: gerasis ganytojas atiduoda už avis savo gyvybę.'),
  (@b43, 10, 12, 'Bet tas, kuris yra samdinys, o ne ganytojas, kuriam avys nesavos, pamatęs ateinantį vilką palieka avis ir bėga; o vilkas jas gaudo ir išsklaido avis.'),
  (@b43, 10, 13, 'Samdinys bėga, nes jis yra samdinys, ir nesirūpina avimis.'),
  (@b43, 10, 14, 'Aš esu gerasis ganytojas ir pažįstu savo avis, ir esu pažįstamas savosioms.'),
  (@b43, 10, 15, 'Kaip Tėvas mane pažįsta, taip ir aš pažįstu Tėvą; ir už avis guldau savo gyvybę.'),
  (@b43, 10, 16, 'Ir kitų avių turiu, kurios nėra iš šito aptvaro; jas taip pat turiu atvesti, ir jos klausys mano balso; ir bus vienas aptvaras ir vienas ganytojas.'),
  (@b43, 10, 17, 'Mano Tėvas mane myli dėl to, kad guldau savo gyvybę, idant vėl ją pasiimčiau.'),
  (@b43, 10, 18, 'Niekas jos iš manęs neatima, bet aš pats ją guldau. Aš turiu valdžią ją guldyti ir turiu valdžią vėl ją pasiimti. Šitą įsakymą gavau iš savo Tėvo“.'),
  (@b43, 10, 19, 'Todėl ir vėl buvo susiskaldymas tarp žydų dėl šitų pasakymų.'),
  (@b43, 10, 20, 'Ir daugelis iš jų sakė: „Jis turi velnią ir yra išprotėjęs; kodėl jo klausote?“'),
  (@b43, 10, 21, 'Kiti sakė: „Šitie žodžiai nėra to, kuris turi velnią. Ar velnias gali atverti aklojo akis?“'),
  (@b43, 10, 22, 'Ir Jeruzalėje buvo pašventimo šventė, ir buvo žiema.'),
  (@b43, 10, 23, 'Ir Jėzus vaikščiojo šventykloje, Saliamono prieangyje.'),
  (@b43, 10, 24, 'Tada žydai jį apstojo ratu ir jam tarė: „Kaip ilgai laikysi mus abejonėse? Jei esi Kristus, pasakyk mums atvirai“.'),
  (@b43, 10, 25, 'Jėzus jiems atsakė: „Aš jums sakiau, o jūs netikėjote; darbai, kuriuos darau savo Tėvo vardu, jie liudija apie mane.'),
  (@b43, 10, 26, 'Bet netikite, nes nesate iš manųjų avių, kaip jums sakiau.'),
  (@b43, 10, 27, 'Mano avys klauso mano balso, ir aš jas pažįstu, ir jos seka paskui mane,'),
  (@b43, 10, 28, 'ir aš joms duodu amžinąjį gyvenimą; ir jos niekada nepražus, ir niekas jų neišplėš iš mano rankos.'),
  (@b43, 10, 29, 'Mano Tėvas, kuris man jas davė, yra didesnis už visus; ir niekas negali jų išplėšti iš mano Tėvo rankos.'),
  (@b43, 10, 30, 'Aš ir mano Tėvas esame viena“.'),
  (@b43, 10, 31, 'Tada žydai vėl ėmėsi akmenų, kad jais jį užmėtytų.'),
  (@b43, 10, 32, 'Jėzus jiems atsakė: „Daug gerų darbų jums parodžiau nuo savo Tėvo; už kurį iš šitų darbų mane užmėtote akmenimis?“'),
  (@b43, 10, 33, 'Žydai jam atsakė, sakydami: „Už gerą darbą tavęs neužmėtome akmenimis; bet už piktžodžiavimą; ir todėl, kad tu, būdamas žmogus, darai save Dievu“.'),
  (@b43, 10, 34, 'Jėzus jiems atsakė: „Argi nėra parašyta jūsų įstatyme: ‘Aš tariau: jūs esate dievai’?'),
  (@b43, 10, 35, 'Jeigu jis pavadino dievais tuos, kuriems atėjo Dievo žodis, o Raštas negali būti sulaužytas;'),
  (@b43, 10, 36, 'ar jūs sakote apie tą, kurį Tėvas pašventė ir siuntė į pasaulį: ‘Tu piktžodžiauji’; nes aš tariau: ‘Aš esu Dievo Sūnus’?'),
  (@b43, 10, 37, 'Jei nedarau savo Tėvo darbų, netikėkite manimi.'),
  (@b43, 10, 38, 'Bet jei darau, nors ir netikite manimi, tikėkite darbais, idant pažintumėte ir tikėtumėte, kad Tėvas yra manyje, ir aš jame“.'),
  (@b43, 10, 39, 'Dėl to jie vėl siekė jį sučiupti, bet jis paspruko iš jų rankų'),
  (@b43, 10, 40, 'ir vėl nuėjo už Jordano į tą vietą, kur pirma Jonas krikštijo; ir ten jis pasiliko.'),
  (@b43, 10, 41, 'Ir daugelis rinkosi pas jį ir sakė: „Jonas nepadarė jokio stebuklo, bet visa tai, ką Jonas kalbėjo apie šitą žmogų, yra teisybė“.'),
  (@b43, 10, 42, 'Ir daugelis tenai į jį įtikėjo.'),
  (@b43, 11, 1, 'Na, o buvo vienas sergantis, vardu Lozorius, iš Betanijos, iš Marijos ir jos sesers Mortos miestelio'),
  (@b43, 11, 2, '(tai buvo ta Marija, kuri patepė Viešpatį tepalu ir nušluostė jo kojas savo plaukais, kurios brolis Lozorius sirgo).'),
  (@b43, 11, 3, 'Todėl jo seserys pasiuntė pas jį, sakydamos: „Viešpatie, štai tas, kurį tu myli, serga“.'),
  (@b43, 11, 4, 'Kai Jėzus išgirdo tai, jis tarė: „Šita liga ne mirčiai, bet Dievo šlovei, kad Dievo Sūnus per ją būtų pašlovintas“.'),
  (@b43, 11, 5, 'Na, o Jėzus mylėjo Mortą, jos seserį ir Lozorių.'),
  (@b43, 11, 6, 'Todėl išgirdęs, kad jis sergąs, pasiliko dar dvi dienas toje vietoje, kur buvo.'),
  (@b43, 11, 7, 'Tad po to jis sako savo mokiniams: „Eikime vėl į Judėją“.'),
  (@b43, 11, 8, 'Jo mokiniai jam sako: „Mokytojau, žydai neseniai siekė tave užmėtyti akmenimis; o tu vėl ten eini?“'),
  (@b43, 11, 9, 'Jėzus atsakė: „Argi ne dvylika valandų yra dienoje? Jei kas vaikšto dieną, nesuklumpa, nes mato šio pasaulio šviesą.'),
  (@b43, 11, 10, 'Bet jei kas vaikšto naktį, suklumpa, nes jame nėra šviesos“.'),
  (@b43, 11, 11, 'tai jis pasakė, o po to jis sako jiems: „Mūsų draugas Lozorius miega; bet einu, kad pažadinčiau jį iš miego“.'),
  (@b43, 11, 12, 'Tada jo mokiniai tarė: „Viešpatie, jeigu jis miega, pasveiks“.'),
  (@b43, 11, 13, 'Tačiau Jėzus kalbėjo apie jo mirtį, bet jie galvojo, kad jis kalbėjo apie poilsio miegą.'),
  (@b43, 11, 14, 'Tada Jėzus tiesiai jiems pasakė: „Lozorius yra miręs.'),
  (@b43, 11, 15, 'Ir aš džiaugiuosi dėl jūsų, kad ten nebuvau, idant tikėtumėte; tačiau eikime pas jį“.'),
  (@b43, 11, 16, 'Tada Tomas, vadinamas Didimu, tarė savo bendramokiniams: „Eikime ir mes, kad mirtume su juo“.'),
  (@b43, 11, 17, 'Jėzus atėjęs rado, kad jau keturias dienas jis išgulėjo kape.'),
  (@b43, 11, 18, 'Na, o Betanija buvo arti Jeruzalės, maždaug už penkiolikos stadijų,'),
  (@b43, 11, 19, 'ir daugelis iš žydų atėjo pas Mortą ir Mariją jų paguosti dėl jų brolio.'),
  (@b43, 11, 20, 'Tada Morta, vos tik išgirdusi, kad Jėzus ateina, nuėjo ir pasitiko jį, bet Marija vis dar sėdėjo namuose.'),
  (@b43, 11, 21, 'Tada Morta tarė Jėzui: „Viešpatie, jei būtum čia buvęs, mano brolis nebūtų miręs.'),
  (@b43, 11, 22, 'Bet žinau, kad netgi dabar, ko tik beprašysi Dievo, tau Dievas tai duos“.'),
  (@b43, 11, 23, 'Jėzus jai sako: „Tavo brolis prisikels“.'),
  (@b43, 11, 24, 'Morta jam sako: „Žinau, kad jis prisikels paskutinę dieną prisikėlime“.'),
  (@b43, 11, 25, 'Jėzus jai tarė: „Aš esu prisikėlimas ir gyvenimas: kas tiki į mane, nors ir bus miręs, tačiau gyvens;'),
  (@b43, 11, 26, 'ir kas tik gyvena ir tiki į mane, niekada nemirs. Ar tuo tiki?“'),
  (@b43, 11, 27, 'Ji sako jam: „Taip, Viešpatie, tikiu, kad esi Kristus, Dievo Sūnus, kuris turi ateiti į pasaulį“.'),
  (@b43, 11, 28, 'Ir taip pasakiusi ji nuėjo ir slapta pašaukė savo seserį Mariją, sakydama: „Mokytojas yra atėjęs ir tave šaukia“.'),
  (@b43, 11, 29, 'Vos tik tai išgirdusi ji greitai pakilo ir atėjo pas jį.'),
  (@b43, 11, 30, 'Na, o Jėzus dar nebuvo atėjęs į miestelį, bet tebebuvo toje vietoje, kur Morta jį pasitiko.'),
  (@b43, 11, 31, 'Tada žydai, kurie buvo su ja namuose ir ją guodė, pamatę, kad Marija skubiai pakilo ir išėjo, sekė paskui ją, sakydami: „Ji eina prie kapo ten paverkti“.'),
  (@b43, 11, 32, 'Tad, kai Marija atėjo, kur buvo Jėzus, ir pamatė jį, ji parpuolė prie jo kojų, sakydama jam: „Viešpatie, jei būtumei čia buvęs, mano brolis nebūtų miręs“.'),
  (@b43, 11, 33, 'Todėl kai Jėzus pamatė ją verkiančią ir taip pat verkiančius su ja atėjusius žydus, jis dejavo dvasioje ir sunerimo,'),
  (@b43, 11, 34, 'ir tarė: „Kur jį paguldėte?“ Jie tarė jam: „Viešpatie, ateik ir pažiūrėk“.'),
  (@b43, 11, 35, 'Jėzus pravirko.'),
  (@b43, 11, 36, 'Tada žydai tarė: „Štai kaip jis jį mylėjo!“'),
  (@b43, 11, 37, 'O vieni iš jų tarė: „Ar tas, kuris atvėrė aklojo akis, negalėjo padaryti, kad ir šis nebūtų miręs?“'),
  (@b43, 11, 38, 'Todėl Jėzus vėl dejuodamas savyje ateina prie kapo. Tai buvo ola, ir ant jos gulėjo akmuo.'),
  (@b43, 11, 39, 'Jėzus tarė: „Nuimkite akmenį“. Morta, mirusiojo sesuo, jam sako: „Viešpatie, jis jau dvokia, nes jau keturios dienos kaip jis miręs“.'),
  (@b43, 11, 40, 'Jėzus jai sako: „Ar nesakiau tau, kad jei tikėsi, pamatysi Dievo šlovę?“'),
  (@b43, 11, 41, 'Tada jie nuėmė akmenį nuo tos vietos, kur buvo paguldytas numirėlis. Ir Jėzus pakėlė savo akis ir tarė: „Tėve, dėkoju tau, kad išklausei mane.'),
  (@b43, 11, 42, 'Ir aš žinojau, kad visada manęs išklausai; bet dėl šalia stovinčios tautos tai pasakiau, kad jie tikėtų, jog tu mane siuntei“.'),
  (@b43, 11, 43, 'Ir taip pakalbėjęs jis sušuko garsiu balsu: „Lozoriau, išeik!“'),
  (@b43, 11, 44, 'Ir tas, kuris buvo miręs, išėjo laidojimo drobėmis surištomis rankomis ir kojomis, ir jo veidas buvo aprištas skepeta. Jėzus jiems sako: „Atriškite jį ir leiskite jam eiti“.'),
  (@b43, 11, 45, 'Tada daugelis iš žydų, kurie atėjo pas Mariją ir pamatė, ką Jėzus padarė, įtikėjo į jį.'),
  (@b43, 11, 46, 'Bet kai kurie iš jų nuėjo pas fariziejus ir papasakojo jiems, ką Jėzus padarė.'),
  (@b43, 11, 47, 'Tada vyriausieji kunigai ir fariziejai surinko tarybą ir tarė: „Ką darysime? Nes šitas žmogus daro daug stebuklų.'),
  (@b43, 11, 48, 'Jei taip jį paliksime, visi į jį įtikės, ir atėję romiečiai atims mūsų vietą ir tautą“.'),
  (@b43, 11, 49, 'O vienas iš jų, vardu Kajafas, tais pačiais metais būdamas aukščiausiasis kunigas, jiems tarė: „Jūs visiškai nieko neišmanote'),
  (@b43, 11, 50, 'nei neapsvarstote, kad mums yra naudingiau, jog vienas žmogus mirtų už tautą, idant nepražūtų visa tauta“.'),
  (@b43, 11, 51, 'O tai jis kalbėjo ne iš savęs, bet, būdamas tais metais aukščiausiasis kunigas, jis pranašavo, kad Jėzus turi mirti už šią tautą;'),
  (@b43, 11, 52, 'ir ne tik už šią tautą, bet kad jis taip pat turi surinkti į viena Dievo vaikus, kurie buvo išsklaidyti.'),
  (@b43, 11, 53, 'Tada, nuo tos dienos, jie drauge tarėsi, kad jį nužudytų.'),
  (@b43, 11, 54, 'Todėl Jėzus nebevaikščiojo viešai tarp žydų; bet iš ten nuėjo į kraštą netoli dykumos, į miestą, vadinamą Efraimu, ir ten laikėsi su savo mokiniais.'),
  (@b43, 11, 55, 'Ir čia pat buvo žydų Apėjimas, ir daugelis prieš Apėjimą ėjo iš to krašto aukštyn į Jeruzalę apsivalyti.'),
  (@b43, 11, 56, 'Tada jie ieškojo Jėzaus ir stovėdami šventykloje tarpusavyje kalbėjo: „Kaip galvojate, ar jis neateis į šventę?“'),
  (@b43, 11, 57, 'Na, o vyriausieji kunigai ir fariziejai davė įsakymą, kad, jei kuris žinotų, kur jis esąs, tai praneštų, idant jie galėtų jį suimti.'),
  (@b43, 12, 1, 'Tada, šešios dienos prieš Apėjimą, Jėzus atėjo į Betaniją, kur buvo Lozorius, kuris buvo miręs, kurį jis prikėlė iš numirusių.'),
  (@b43, 12, 2, 'Ten jie pagamino jam vakarienę; ir Morta patarnavo; bet Lozorius buvo vienas iš sėdinčiųjų su juo už stalo.'),
  (@b43, 12, 3, 'Tada Marija paėmė svarą labai brangaus nardo tepalo ir patepė Jėzaus kojas, ir nušluostė jo kojas savo plaukais; ir namai prisipildė tepalo kvapo.'),
  (@b43, 12, 4, 'Tada vienas iš jo mokinių, Judas Iskariotas, Simono sūnus, kuris turėjo jį išduoti, sako:'),
  (@b43, 12, 5, '„Kodėl šis tepalas nebuvo parduotas už tris šimtus denarų ir atiduotas vargšams?“'),
  (@b43, 12, 6, 'Jis tai sakė ne todėl, kad rūpinosi vargšais; bet todėl, kad buvo vagis ir turėjo krepšį, ir nešiojosi tai, kas buvo į jį įdedama.'),
  (@b43, 12, 7, 'Tada Jėzus tarė: „Palik ją ramybėje, ji tai laikė mano laidojimo dienai.'),
  (@b43, 12, 8, 'Nes vargšų visada turite su savimi, bet mane ne visada turite“.'),
  (@b43, 12, 9, 'Taigi daug žydų liaudies žinojo, kad jis ten buvo, ir jie atėjo ne vien dėl Jėzaus, bet taip pat kad pamatytų Lozorių, kurį jis prikėlė iš numirusių.'),
  (@b43, 12, 10, 'Bet vyriausieji kunigai tarėsi, kad jie ir Lozorių nužudytų;'),
  (@b43, 12, 11, 'kadangi dėl jo daugelis iš žydų išėjo ir įtikėjo į Jėzų.'),
  (@b43, 12, 12, 'Rytojaus dieną daug liaudies, atėjusios į šventę, išgirdę, kad Jėzus ateina į Jeruzalę,'),
  (@b43, 12, 13, 'ėmė palmių šakas ir išėjo jo pasitikti, ir šaukė: „Osana! Palaimintas Izraelio Karalius, ateinantis Viešpaties vardu!“'),
  (@b43, 12, 14, 'O Jėzus, radęs jauną asilą, atsisėdo ant jo; kaip yra parašyta:'),
  (@b43, 12, 15, '„Nebijok, Siono dukra; štai ateina tavo Karalius, sėdintis ant asilės asiliuko“.'),
  (@b43, 12, 16, 'Iš pradžių jo mokiniai šito nesuprato; bet kai Jėzus buvo pašlovintas, tada jie prisiminė, kad tai buvo apie jį parašyta, ir kad jie padarė jam tai.'),
  (@b43, 12, 17, 'Todėl tauta, buvusi su juo, kai jis pašaukė Lozorių iš kapo ir prikėlė jį iš numirusių, liudija.'),
  (@b43, 12, 18, 'Dėl šios priežasties tauta jį ir pasitiko, nes jie girdėjo, kad jis padarė šitą stebuklą.'),
  (@b43, 12, 19, 'Todėl fariziejai tarpusavyje kalbėjo: „Ar matote, kaip nieko negalite padaryti? Štai pasaulis nuėjo paskui jį“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b43, 12, 20, 'Ir tarp atėjusiųjų aukštyn per šventę pagarbinti buvo kai kurie graikai;'),
  (@b43, 12, 21, 'taigi tie atėjo pas Pilypą, kuris buvo iš Galilėjos Betsaidos, ir prašė jo, sakydami: „Pone, norime pamatyti Jėzų“.'),
  (@b43, 12, 22, 'Pilypas ateina ir pasako Andriejui, o Andriejus ir Pilypas vėl pasako Jėzui.'),
  (@b43, 12, 23, 'O Jėzus jiems atsakė, sakydamas: „Ateina valanda, kad būtų pašlovintas žmogaus Sūnus.'),
  (@b43, 12, 24, 'Iš tiesų, iš tiesų sakau jums: jei kviečio grūdas nekrenta į dirvą ir nemiršta, jis pasilieka vienas; bet jeigu jis miršta, jis atneša daug vaisių.'),
  (@b43, 12, 25, 'Kas myli savo gyvybę, tas ją praras; o kas nekenčia savo gyvybės šiame pasaulyje, išsaugos ją amžinajam gyvenimui.'),
  (@b43, 12, 26, 'Jei kas man tarnauja, tas teseka paskui mane; ir kur aš esu, ten bus ir mano tarnas; jei kas man tarnauja, tą gerbs mano Tėvas.'),
  (@b43, 12, 27, 'Dabar mano siela nerimastinga; ir ką aš sakysiu? Tėve, gelbėk mane nuo šios valandos? Bet dėl šios priežasties aš atėjau į šią valandą.'),
  (@b43, 12, 28, 'Tėve, pašlovink savo vardą“. Tada iš dangaus atėjo balsas, sakydamas: „Aš jį pašlovinau ir vėl pašlovinsiu“.'),
  (@b43, 12, 29, 'Todėl šalia stovinti ir tai girdėjusi tauta sakė, kad griaudėjo; kiti sakė: „Angelas jam kalbėjo“.'),
  (@b43, 12, 30, 'Jėzus atsakydamas tarė: „Šitas balsas atėjo ne dėl manęs, bet dėl jūsų“.'),
  (@b43, 12, 31, 'Dabar yra šio pasaulio teismas: dabar bus išmestas šio pasaulio kunigaikštis.'),
  (@b43, 12, 32, 'Ir jei aš būsiu pakeltas nuo žemės, prie savęs patrauksiu visus“.'),
  (@b43, 12, 33, 'Tai jis pasakė parodydamas, kokia mirtimi turės mirti.'),
  (@b43, 12, 34, 'Tauta jam atsakė: „Mes iš įstatymo girdėjome, kad Kristus pasilieka per amžius; o kaipgi tu sakai: ‘Žmogaus Sūnus turi būti iškeltas’? Kas yra šis žmogaus Sūnus?“'),
  (@b43, 12, 35, 'Tada Jėzus jiems tarė: „Dar trumpam šviesa yra su jumis. Vaikščiokite, kol turite šviesą, kad ant jūsų neužeitų tamsa; nes tas, kuris vaikšto tamsoje, nežino, kur eina.'),
  (@b43, 12, 36, 'Kol turite šviesą, tikėkite šviesa, kad būtumėte šviesos vaikai“. Tai pasakęs Jėzus išėjo ir pasislėpė nuo jų.'),
  (@b43, 12, 37, 'Bet nors jis jų akivaizdoje padarė tiek daug stebuklų, tačiau jie netikėjo į jį,'),
  (@b43, 12, 38, 'kad išsipildytų pranašo Izaijo pasakymas, kurį jis kalbėjo: „Viešpatie, kas patikėjo mūsų pranešimu? Ir kam buvo apreikšta Viešpaties ranka?“'),
  (@b43, 12, 39, 'Todėl jie negalėjo tikėti, nes Izaijas vėl sakė:'),
  (@b43, 12, 40, '„Jis apakino jų akis ir užkietino jų širdį; kad jie nematytų savo akimis nei nesuprastų savo širdimi ir neatsiverstų, ir aš jų nepagydyčiau“.'),
  (@b43, 12, 41, 'Tai kalbėjo Izaijas, kai pamatė jo šlovę ir kalbėjo apie jį.'),
  (@b43, 12, 42, 'Tačiau ir tarp vyriausiųjų valdovų daugelis įtikėjo į jį; bet dėl fariziejų jie neišpažino jo, kad nebūtų išmesti iš sinagogos,'),
  (@b43, 12, 43, 'nes žmonių gyrių jie mėgo labiau negu Dievo gyrių.'),
  (@b43, 12, 44, 'Jėzus šaukė ir tarė: „Kas tiki į mane, tas tiki ne į mane, bet į tą, kuris mane siuntė.'),
  (@b43, 12, 45, 'Ir kas mato mane, mato tą, kuris mane siuntė.'),
  (@b43, 12, 46, 'Aš, šviesa, atėjau į pasaulį, kad kas į mane tiki, nepasiliktų tamsoje.'),
  (@b43, 12, 47, 'Ir jei kas klausosi mano žodžių ir netiki, aš jo neteisiu, nes atėjau ne teisti pasaulio, bet gelbėti pasaulį.'),
  (@b43, 12, 48, 'Kas mane atmeta ir nepriima mano žodžių, turi tą, kuris jį teisia: žodis, kurį kalbėjau, tas jį teis paskutiniąją dieną.'),
  (@b43, 12, 49, 'Nes aš nekalbėjau iš savęs; bet Tėvas, kuris mane siuntė, jis man davė įsakymą, ką turiu sakyti ir ką turiu kalbėti.'),
  (@b43, 12, 50, 'Ir aš žinau, kad jo įsakymas yra amžinas gyvenimas; todėl ką kalbu, kalbu taip, kaip man sakė Tėvas “.'),
  (@b43, 13, 1, 'Na, o prieš Apėjimo šventę, kai Jėzus žinojo, kad atėjo jo valanda, jog jis turi išeiti iš šio pasaulio pas Tėvą, mylėdamas savuosius, kurie buvo pasaulyje, jis mylėjo juos iki galo.'),
  (@b43, 13, 2, 'Ir pasibaigus vakarienei, velniui jau įdėjus į Simono sūnaus Judo Iskarioto širdį jį išduoti;'),
  (@b43, 13, 3, 'Jėzus, žinodamas, kad Tėvas davė visa į jo rankas ir kad jis buvo atėjęs iš Dievo ir ėjo pas Dievą;'),
  (@b43, 13, 4, 'keliasi nuo vakarienės ir padėjo į šoną savo drabužius; ir paėmęs rankšluostį apsijuosė.'),
  (@b43, 13, 5, 'Po to jis įpila vandens į praustuvę ir pradėjo plauti mokiniams kojas, ir šluostyti jas rankšluosčiu, kuriuo buvo apsijuosęs.'),
  (@b43, 13, 6, 'Tada jis ateina prie Simono Petro; ir Petras jam sako: „Viešpatie, ar tu plauni mano kojas?“'),
  (@b43, 13, 7, 'Jėzus atsakydamas tarė jam: „Ką darau, tu dabar nežinai; bet po to sužinosi“.'),
  (@b43, 13, 8, 'Petras jam sako: „Niekada neplausi mano kojų“. Jėzus jam atsakė: „Jei neplausiu tavęs, tu su manimi neturi jokios dalies“.'),
  (@b43, 13, 9, 'Simonas Petras jam sako: „Viešpatie, ne vien mano kojas, bet taip pat rankas ir galvą“.'),
  (@b43, 13, 10, 'Jėzus jam sako: „Kas yra nuplautas, tam nereikia daugiau, kaip tik kojas nusiplauti, nes yra visas švarus; ir jūs esate švarūs, bet ne visi“.'),
  (@b43, 13, 11, 'Nes jis žinojo, kas turi jį išduoti; todėl sakė: „Ne visi esate švarūs“.'),
  (@b43, 13, 12, 'Taigi nuplovęs jų kojas ir pasiėmęs savo drabužius, ir vėl atsisėdęs jis tarė jiems: „Ar žinote, ką jums padariau?'),
  (@b43, 13, 13, 'Jūs mane vadinate Mokytoju ir Viešpačiu, ir gerai sakote; nes aš toks esu.'),
  (@b43, 13, 14, 'Tad jei aš, jūsų Viešpats ir Mokytojas, nuploviau jūsų kojas; tai ir jūs turite plauti vienas kito kojas.'),
  (@b43, 13, 15, 'Nes daviau jums pavyzdį, kad darytumėte, kaip aš jums padariau.'),
  (@b43, 13, 16, 'Iš tiesų, iš tiesų sakau jums: tarnas ne didesnis už savo viešpatį; nei pasiųstasis nėra didesnis už tą, kuris jį siuntė.'),
  (@b43, 13, 17, 'Jei žinote tai, esate laimingi, jei tai darote.'),
  (@b43, 13, 18, 'Ne apie jus visus kalbu; aš žinau, kuriuos išsirinkau; bet kad išsipildytų Raštas: ‘Tas, kuris su manimi valgo duoną, pakėlė prieš mane savo kulną’.'),
  (@b43, 13, 19, 'Sakau jums dabar, prieš įvykstant, kad tam įvykus tikėtumėte, jog aš esu tas.'),
  (@b43, 13, 20, 'Iš tiesų, iš tiesų sakau jums: kas priima tą, kurį siunčiu, tas priima mane; o kas priima mane, tas priima tą, kuris mane siuntė“.'),
  (@b43, 13, 21, 'Taip taręs, Jėzus sunerimo dvasioje ir liudijo, ir tarė: „Iš tiesų, iš tiesų sakau jums, kad vienas iš jūsų mane išduos“.'),
  (@b43, 13, 22, 'Tada mokiniai žiūrėjo vienas į kitą abejodami, apie kurį jis kalbėjo.'),
  (@b43, 13, 23, 'Na, o vienas iš jo mokinių, kurį Jėzus mylėjo, buvo palinkęs prie Jėzaus krūtinės.'),
  (@b43, 13, 24, 'Todėl Simonas Petras pamojo jam, kad jis paklaustų, kas galėtų būti tas, apie kurį jis kalbėjo.'),
  (@b43, 13, 25, 'Tada jis, prigulęs prie Jėzaus krūtinės, jam sako: „Viešpatie, kuris tai?“'),
  (@b43, 13, 26, 'Jėzus atsakė: „Tai tas, kuriam duosiu gabaliuką, jį pamirkęs“. Ir pamirkęs gabaliuką padavė jį Simono sūnui Judui Iskariotui.'),
  (@b43, 13, 27, 'Ir po to gabaliuko šėtonas įėjo į jį. Tada Jėzus jam tarė: „Ką darai, daryk greitai“.'),
  (@b43, 13, 28, 'Na, o prie stalo nei vienas nesuprato, kokiu tikslu jis jam tai kalbėjo.'),
  (@b43, 13, 29, 'Nes kai kurie iš jų manė, kadangi Judas turėjo krepšį, todėl Jėzus jam sakė: „Nupirk tai, ko mums reikia šventei“; arba kad jis ką nors duotų vargšams.'),
  (@b43, 13, 30, 'Tada jis, ėmęs gabaliuką, tuojau išėjo; ir buvo naktis.'),
  (@b43, 13, 31, 'Todėl kai jis buvo išėjęs, Jėzus tarė: „Dabar žmogaus Sūnus yra pašlovintas, ir Dievas yra pašlovintas jame.'),
  (@b43, 13, 32, 'Jei Dievas yra pašlovintas jame, tai ir Dievas jį pašlovins savyje ir nedelsiant jį pašlovins.'),
  (@b43, 13, 33, 'Vaikeliai, dar trumpam esu su jumis. Jūs manęs ieškosite, ir kaip sakiau žydams: ‘Kur aš einu, jūs negalite ateiti’; taip dabar jums sakau.'),
  (@b43, 13, 34, 'Duodu jums naują įsakymą: kad mylėtumėte vienas kitą; kaip aš jus mylėjau, kad ir jūs mylėtumėte vienas kitą.'),
  (@b43, 13, 35, 'Iš to visi žinos, kad esate mano mokiniai, jei turėsite vienas kitam meilės“.'),
  (@b43, 13, 36, 'Simonas Petras jam tarė: „Viešpatie, kur tu eini?“ Jėzus jam atsakė: „Kur aš einu, negali dabar sekti paskui mane; bet po to seksi paskui mane“.'),
  (@b43, 13, 37, 'Petras jam tarė: „Viešpatie, kodėl negaliu sekti paskui tave dabar? Aš už tave guldysiu savo gyvybę“.'),
  (@b43, 13, 38, 'Jėzus jam atsakė: „Ar tu už mane guldysi savo gyvybę? Iš tiesų, iš tiesų sakau tau: dar gaidys nebus pragydęs, kai triskart manęs išsiginsi“.'),
  (@b43, 14, 1, '„Tenebūna nerimastingos jūsų širdys: tikite į Dievą, tikėkite ir į mane.'),
  (@b43, 14, 2, 'Mano Tėvo namuose yra daug buveinių; jei taip nebūtų, aš jums būčiau pasakęs. Einu paruošti jums vietą.'),
  (@b43, 14, 3, 'Ir jei einu ir paruošiu jums vietą, vėl ateisiu ir pasiimsiu jus pas save; kad ten, kur aš esu, būtumėte ir jūs.'),
  (@b43, 14, 4, 'Ir kur aš einu, jūs žinote, ir kelią žinote“.'),
  (@b43, 14, 5, 'Tomas jam sako: „Viešpatie, mes nežinome, kur tu eini; ir kaip galime žinoti kelią?“'),
  (@b43, 14, 6, 'Jėzus jam sako: „Aš esu kelias, tiesa ir gyvenimas; niekas neateina pas Tėvą kitaip, kaip tik per mane.'),
  (@b43, 14, 7, 'Jei pažintumėte mane, tai pažintumėte ir mano Tėvą; ir nuo šiol jį pažįstate ir jį matėte“.'),
  (@b43, 14, 8, 'Pilypas jam sako: „Viešpatie, parodyk mums Tėvą, ir to mums pakaks“.'),
  (@b43, 14, 9, 'Jėzus jam sako: „Buvau su jumis tokį ilgą laiką, o tu, Pilypai, vis dar manęs nepažinai? Kas matė mane, matė Tėvą; tad kaipgi tu sakai: ‘Parodyk mums Tėvą’?'),
  (@b43, 14, 10, 'Ar netiki, kad aš esu Tėve, o Tėvas manyje? Žodžius, kuriuos jums kalbu, kalbu ne iš savęs, bet Tėvas, kuris gyvena manyje, jis daro darbus.'),
  (@b43, 14, 11, 'Tikėkite manimi, kad aš esu Tėve, o Tėvas manyje; jei ne, tai tikėkite manimi dėl pačių darbų.'),
  (@b43, 14, 12, 'Iš tiesų, iš tiesų sakau jums: kas tiki į mane, tas irgi darys darbus, kuriuos aš darau; ir darys didesnius darbus už šituos; nes aš einu pas savo Tėvą.'),
  (@b43, 14, 13, 'Ir ko tik prašysite mano vardu, tai padarysiu, kad Tėvas būtų pašlovintas Sūnuje.'),
  (@b43, 14, 14, 'Jei ko prašysite mano vardu, aš tai padarysiu.'),
  (@b43, 14, 15, 'Jei mylite mane, laikykitės mano įsakymų.'),
  (@b43, 14, 16, 'Ir aš melsiu Tėvo, ir jis duos jums kitą Guodėją, kad jis pasiliktų su jumis per amžius,'),
  (@b43, 14, 17, 'tai yra, tiesos Dvasią, kurios pasaulis negali priimti, nes jos nemato nei jos nepažįsta; bet jūs pažįstate ją, nes ji gyvena su jumis ir bus jumyse.'),
  (@b43, 14, 18, 'Nepaliksiu jūsų be paguodos – ateisiu pas jus.'),
  (@b43, 14, 19, 'Dar trumpam, ir pasaulis manęs nebematys; bet jūs mane matysite; kadangi aš gyvenu, jūs irgi gyvensite.'),
  (@b43, 14, 20, 'Tą dieną žinosite, kad aš esu savo Tėve, ir jūs manyje, ir aš jumyse.'),
  (@b43, 14, 21, 'Kas turi mano įsakymus ir jų laikosi, jis yra tas, kuris mane myli; o tas, kuris myli mane, bus mylimas mano Tėvo, ir aš jį mylėsiu ir jam apsireikšiu“.'),
  (@b43, 14, 22, 'Judas, ne Iskariotas, jam sako: „Viešpatie, kaip yra, kad nori apsireikšti mums, o ne pasauliui?“'),
  (@b43, 14, 23, 'Jėzus atsakydamas tarė jam: „Jei kas mane myli, tas laikysis mano žodžių; ir mano Tėvas jį mylės, ir mes pas jį ateisime ir susikursime pas jį savo buveinę.'),
  (@b43, 14, 24, 'Kas manęs nemyli, nesilaiko mano pasakymų; ir žodis, kurį girdite, yra ne mano, bet mane siuntusio Tėvo.'),
  (@b43, 14, 25, 'Tai jums kalbėjau dar būdamas su jumis.'),
  (@b43, 14, 26, 'Bet Guodėjas, kuris yra Šventoji Dvasia, kurią Tėvas atsiųs mano vardu, ji mokys jus visko ir primins jums viską, ką jums sakiau.'),
  (@b43, 14, 27, 'Palieku su jumis ramybę, duodu jums savo ramybę; aš jums duodu ne kaip pasaulis duoda. Tenebūna nerimastingos jūsų širdys ir tenebijo.'),
  (@b43, 14, 28, 'Girdėjote, kaip jums sakiau: ‘Išeinu ir vėl ateisiu pas jus’. Jei mane mylėtumėte, džiaugtumėtės, kad sakiau: ‘Einu pas Tėvą’, nes mano Tėvas yra didesnis už mane.'),
  (@b43, 14, 29, 'Ir dabar, prieš tam įvykstant, jums pasakiau, kad kai tai įvyks, tikėtumėte.'),
  (@b43, 14, 30, 'Nuo šiol nebedaug kalbėsiu su jumis, nes ateina šio pasaulio kunigaikštis, ir nieko manyje neturi.'),
  (@b43, 14, 31, 'Bet kad pasaulis žinotų, kad myliu Tėvą; ir kaip Tėvas davė man įsakymą, taip darau. Kelkitės, eikime iš čia“.'),
  (@b43, 15, 1, '„Aš esu tikrasis vynmedis, o mano Tėvas – žemdirbys.'),
  (@b43, 15, 2, 'Kiekvieną manyje esančią šaką, neduodančią vaisiaus, jis pašalina; o kiekvieną šaką, duodančią vaisių, apvalo, kad ji neštų daugiau vaisiaus.'),
  (@b43, 15, 3, 'Dabar esate švarūs per žodį, kurį jums kalbėjau.'),
  (@b43, 15, 4, 'Pasilikite manyje, ir aš jumyse. Kaip šaka negali duoti vaisiaus iš savęs, jei ji nepasilieka vynmedyje, taip ir jūs negalite, jei nepasiliekate manyje.'),
  (@b43, 15, 5, 'Aš esu vynmedis, jūs esate šakos: kas pasilieka manyje ir aš jame, tas neša daug vaisiaus; nes be manęs nieko negalite padaryti.'),
  (@b43, 15, 6, 'Jei kas nepasilieka manyje, yra išmetamas kaip šaka ir sudžiūna; ir jas surenka ir įmeta į ugnį, ir jos sudega.'),
  (@b43, 15, 7, 'Jei pasiliekate manyje, ir mano žodžiai pasilieka jumyse, prašysite, ko tik norėsite, ir jums tai bus padaryta.'),
  (@b43, 15, 8, 'Mano Tėvas yra pašlovintas tame, kad duodate daug vaisių; taip būsite mano mokiniai.'),
  (@b43, 15, 9, 'Kaip Tėvas mane pamilo, taip aš jus pamilau; pasilikite mano meilėje.'),
  (@b43, 15, 10, 'Jei laikysitės mano įsakymų, pasiliksite mano meilėje; kaip ir aš laikiausi savo Tėvo įsakymų, ir pasilieku jo meilėje.'),
  (@b43, 15, 11, 'Tai jums kalbėjau, kad mano džiaugsmas liktų jumyse ir kad jūsų džiaugsmas būtų pilnas.'),
  (@b43, 15, 12, 'Šitas yra mano įsakymas: kad mylėtumėte vienas kitą kaip aš jus mylėjau.'),
  (@b43, 15, 13, 'Niekas neturi didesnės meilės už tą, kad kas guldo savo gyvybę už savo draugus.'),
  (@b43, 15, 14, 'Jūs esate mano draugai, jei darote, ką jums įsakau.'),
  (@b43, 15, 15, 'Nuo šiol jūsų nebevadinu tarnais; nes tarnas nežino, ką daro jo viešpats; bet pavadinau jus draugais; nes viską, ką girdėjau iš savo Tėvo, daviau jums žinoti.'),
  (@b43, 15, 16, 'Jūs manęs neišsirinkote, bet aš jus išsirinkau ir paskyriau jus, kad eitumėte ir neštumėte vaisių, ir kad jūsų vaisius išliktų; kad ko tik prašysite Tėvo mano vardu, jis jums tai duotų.'),
  (@b43, 15, 17, 'Aš jums tai įsakau, kad mylėtumėte vienas kitą.'),
  (@b43, 15, 18, 'Jei pasaulis jūsų nekenčia, žinokite, kad jis manęs nekentė pirmiau negu jūsų.'),
  (@b43, 15, 19, 'Jei būtumėte iš pasaulio, pasaulis mylėtų savuosius; bet kadangi nesate iš pasaulio, bet aš jus išsirinkau iš pasaulio, todėl pasaulis jūsų nekenčia.'),
  (@b43, 15, 20, 'Prisiminkite žodį, kurį jums sakiau: ‘Tarnas nėra didesnis už savo viešpatį’. Jeigu jie mane persekiojo, tai ir jus persekios; jeigu jie laikėsi mano pasakymo, tai laikysis ir jūsų.'),
  (@b43, 15, 21, 'Bet visa tai jie darys jums dėl mano vardo, nes jie nepažįsta to, kuris mane siuntė.'),
  (@b43, 15, 22, 'Jei nebūčiau atėjęs ir jiems kalbėjęs, jie neturėtų nuodėmės; bet dabar jie neturi priedangos savo nuodėmei.'),
  (@b43, 15, 23, 'Kas manęs nekenčia, nekenčia ir mano Tėvo.'),
  (@b43, 15, 24, 'Jei nebūčiau tarp jų padaręs darbų, kurių nepadarė niekas kitas, jie neturėtų nuodėmės; bet dabar jie ir matė, ir nekentė tiek manęs, tiek mano Tėvo.'),
  (@b43, 15, 25, 'Bet tai vyksta, kad išsipildytų žodis, kuris yra užrašytas jų įstatyme: ‘Jie nekentė manęs be priežasties’.'),
  (@b43, 15, 26, 'Bet kai bus atėjęs Guodėjas, kurį jums iš Tėvo atsiųsiu, – tiesos Dvasia, kuri išeina iš Tėvo, ji liudys apie mane;'),
  (@b43, 15, 27, 'ir jūs irgi liudysite, nes buvote su manimi nuo pradžios“.'),
  (@b43, 16, 1, '„Jums tai kalbėjau, kad nepasipiktintumėte.'),
  (@b43, 16, 2, 'Jie išmes jus iš sinagogų; taip, ateina laikas, kad kiekvienas, kuris jus žudys, manys, jog atlieka tarnystę Dievui.'),
  (@b43, 16, 3, 'Ir tai jie darys jums, nes jie nepažino nei Tėvo, nei manęs.'),
  (@b43, 16, 4, 'Bet tai jums pasakiau, kad atėjus laikui prisimintumėte, kad aš jums apie tai sakiau. Ir nesakiau jums to pradžioje, nes buvau su jumis.'),
  (@b43, 16, 5, 'Bet dabar einu pas tą, kuris mane siuntė; ir nei vienas iš jūsų manęs neklausia: ‘Kur eini?’'),
  (@b43, 16, 6, 'Bet kadangi pasakiau jums tai, liūdesys pripildė jūsų širdį.'),
  (@b43, 16, 7, 'Tačiau sakau jums tiesą: jums yra naudinga, kad išeinu; nes jei neišeisiu, pas jus neateis Guodėjas; bet jei išeisiu, atsiųsiu jį pas jus.'),
  (@b43, 16, 8, 'Ir jis atėjęs bars pasaulį dėl nuodėmės, dėl teisumo ir dėl teismo:'),
  (@b43, 16, 9, 'dėl nuodėmės, nes jie netiki į mane;'),
  (@b43, 16, 10, 'dėl teisumo, nes aš einu pas savo Tėvą, ir nebematysite manęs;'),
  (@b43, 16, 11, 'dėl teismo, nes šio pasaulio kunigaikštis yra nuteistas.'),
  (@b43, 16, 12, 'Daug dar ką turiu jums pasakyti, bet dabar negalite to pakelti.'),
  (@b43, 16, 13, 'Tačiau kai ateis ji, tiesos Dvasia, ji ves jus į visą tiesą, nes kalbės ne iš savęs, bet kalbės, ką išgirs, ir paskelbs jums tai, kas turės įvykti.'),
  (@b43, 16, 14, 'Ji pašlovins mane, nes ji ims iš mano, ir tai jums apsakys.'),
  (@b43, 16, 15, 'Visa, ką turi Tėvas, yra mano, todėl sakiau, kad ji ims iš mano, ir tai jums paskelbs.'),
  (@b43, 16, 16, 'Dar trumpam, ir nematysite manęs; ir vėl, dar trumpam, ir mane pamatysite, nes aš einu pas Tėvą“.'),
  (@b43, 16, 17, 'Tada kai kurie iš jo mokinių tarpusavyje sakė: „Kas tai yra, ką jis mums sako: ‘Dar trumpam, ir nematysite manęs; ir vėl, dar trumpam, ir mane pamatysite’ ir: ‘Nes aš einu pas Tėvą’?“'),
  (@b43, 16, 18, 'Todėl jie sakė: „Kas tai yra, ką jis sako: ‘Dar trumpam’? Mes nežinome, ką jis sako“.'),
  (@b43, 16, 19, 'Na, o Jėzus žinojo, kad jie norėjo jį klausti, ir tarė jiems: „Ar tarpusavyje klausinėjatės apie tai, kad pasakiau: ‘Dar trumpam, ir nematysite manęs; ir vėl, dar trumpam, ir mane pamatysite’?'),
  (@b43, 16, 20, 'Iš tiesų, iš tiesų sakau jums, kad jūs verksite ir raudosite, bet pasaulis džiaugsis; ir jūs sielvartausite, bet jūsų sielvartas pavirs džiaugsmu.'),
  (@b43, 16, 21, 'Moteris gimdymo kančiose sielvartauja, nes atėjo jos valanda; bet vos tik pagimdžiusi vaiką ji nebeprisimena skausmo iš džiaugsmo, kad žmogus gimė į pasaulį.'),
  (@b43, 16, 22, 'Todėl ir jūs dabar sielvartaujate, bet aš jus vėl pamatysiu, ir jūsų širdis džiaugsis, ir jūsų džiaugsmo niekas neatims iš jūsų.'),
  (@b43, 16, 23, 'Ir tą dieną nieko manęs neprašysite. Iš tiesų, iš tiesų sakau jums: ko tik prašysite Tėvo mano vardu, jis jums tai duos.'),
  (@b43, 16, 24, 'Lig šiol nieko neprašėte mano vardu; prašykite, ir gausite, kad jūsų džiaugsmas būtų pilnas.'),
  (@b43, 16, 25, 'Tai jums kalbėjau patarlėmis, bet ateina laikas, kai nebekalbėsiu jums patarlėmis, tačiau aiškiai paskelbsiu jums apie Tėvą.'),
  (@b43, 16, 26, 'Tą dieną prašysite mano vardu, ir nesakau jums, kad maldausiu Tėvo už jus,'),
  (@b43, 16, 27, 'nes pats Tėvas jus myli, nes jūs mane mylėjote ir tikėjote, kad atėjau nuo Dievo.'),
  (@b43, 16, 28, 'Aš išėjau nuo Tėvo ir esu atėjęs į pasaulį; vėl palieku pasaulį ir einu pas Tėvą“.'),
  (@b43, 16, 29, 'Jo mokiniai jam tarė: „Štai dabar aiškiai kalbi ir nekalbi patarlės.'),
  (@b43, 16, 30, 'Dabar esame tikri, kad žinai viską, ir tau nereikia, jog kas nors tavęs klaustų; iš to mes tikime, kad tu išėjęs iš Dievo“.'),
  (@b43, 16, 31, 'Jėzus jiems atsakė: „Ar dabar tikite?'),
  (@b43, 16, 32, 'Štai ateina valanda, taip, dabar yra atėjusi, kad išsisklaidysite kiekvienas prie savo ir paliksite mane vieną, tačiau aš nesu vienas, nes su manimi yra Tėvas.'),
  (@b43, 16, 33, 'Tai jums kalbėjau, kad manyje turėtumėte ramybę. Pasaulyje turėsite suspaudimą, bet pralinksmėkite; aš nugalėjau pasaulį“.'),
  (@b43, 17, 1, 'Šiuos žodžius kalbėjo Jėzus ir pakėlė savo akis į dangų, ir tarė: „Tėve, atėjo valanda; pašlovink savo Sūnų, kad ir tavo Sūnus tave pašlovintų;'),
  (@b43, 17, 2, 'kaip jam esi davęs valdžią visiems kūnams, kad jis duotų amžinąjį gyvenimą visiems, kuriuos esi jam davęs.'),
  (@b43, 17, 3, 'O šis yra amžinas gyvenimas, kad jie pažintų tave, vienintelį tikrąjį Dievą, ir Jėzų Kristų, kurį siuntei.'),
  (@b43, 17, 4, 'Aš pašlovinau tave žemėje; užbaigiau darbą, kurį man davei atlikti.'),
  (@b43, 17, 5, 'O dabar, o Tėve, pašlovink mane pačiu savimi ta šlove, kurią turėjau su tavimi pirmiau, nei buvo pasaulis.'),
  (@b43, 17, 6, 'Aš apreiškiau tavo vardą žmonėms, kuriuos man davei iš pasaulio; jie buvo tavo, ir man juos davei; ir jie laikėsi tavo žodžio.'),
  (@b43, 17, 7, 'Dabar jie pažino, kad visa, ką man davei, yra iš tavęs.'),
  (@b43, 17, 8, 'Nes jiems daviau žodžius, kuriuos man davei; ir jie juos priėmė ir tikrai pažino, kad išėjau iš tavęs, ir jie įtikėjo, kad tu mane siuntei.'),
  (@b43, 17, 9, 'Aš meldžiu už juos, nesimeldžiu už pasaulį, bet už tuos, kuriuos man davei; nes jie tavo.'),
  (@b43, 17, 10, 'Ir visi manieji yra tavieji, o tavieji yra manieji; ir aš esu pašlovintas juose.'),
  (@b43, 17, 11, 'Ir dabar aš jau nebe pasaulyje, bet šitie yra pasaulyje, ir aš ateinu pas tave. Šventasis Tėve, išlaikyk savo vardu tuos, kuriuos man davei, idant jie būtų viena, kaip mes.'),
  (@b43, 17, 12, 'Kol buvau su jais pasaulyje, išlaikiau juos tavo vardu; tuos, kuriuos man davei, išsaugojau, ir nei vienas iš jų nepražuvo, tiktai pražūties sūnus; idant išsipildytų Raštas.'),
  (@b43, 17, 13, 'O dabar ateinu pas tave; ir tai kalbu pasaulyje, kad jie turėtų savyje išsipildžiusį mano džiaugsmą.'),
  (@b43, 17, 14, 'Aš jiems daviau tavo žodį; ir pasaulis jų nekentė, nes jie nėra iš pasaulio, kaip ir aš nesu iš pasaulio.'),
  (@b43, 17, 15, 'Nesimeldžiu, kad pasiimtumei juos iš pasaulio, bet kad saugotum juos nuo pikto.'),
  (@b43, 17, 16, 'Jie nėra iš pasaulio, kaip ir aš nesu iš pasaulio.'),
  (@b43, 17, 17, 'Pašvęsk juos savąja tiesa; tavo žodis yra tiesa.'),
  (@b43, 17, 18, 'Kaip tu mane siuntei į pasaulį, taip ir aš juos siunčiau į pasaulį.'),
  (@b43, 17, 19, 'Ir dėl jų aš pašvenčiu save, kad ir jie būtų pašvęsti per tiesą.'),
  (@b43, 17, 20, 'Tačiau meldžiu ne vien už šituos, bet ir už tuos, kurie tikės į mane per jų žodį;'),
  (@b43, 17, 21, 'kad jie visi būtų viena; kaip tu, Tėve, esi manyje, ir aš tavyje, kad ir jie būtų viena mumyse; idant pasaulis tikėtų, kad tu esi mane siuntęs.'),
  (@b43, 17, 22, 'Ir šlovę, kurią man davei, aš jiems daviau, kad jie būtų viena, kaip ir mes esame viena:'),
  (@b43, 17, 23, 'aš juose, ir tu manyje, idant jie taptų tobuli viename; ir kad pasaulis žinotų, jog tu mane siuntei ir juos pamilai, kaip pamilai mane.'),
  (@b43, 17, 24, 'Tėve, noriu, kad ir tie, kuriuos man davei, būtų su manimi, kur aš esu, idant jie matytų mano šlovę, kurią man davei, nes pamilai mane prieš pasaulio įkūrimą.'),
  (@b43, 17, 25, 'O teisusis Tėve, pasaulis tavęs nepažino, bet aš tave pažinau, ir šitie pažino, kad tu mane siuntei.'),
  (@b43, 17, 26, 'Ir aš jiems paskelbiau tavo vardą ir jį paskelbsiu, kad meilė, kuria mane pamilai, būtų juose, ir aš juose.'),
  (@b43, 18, 1, 'Pakalbėjęs tuos žodžius Jėzus išėjo su savo mokiniais už Kedrono upelio, kur buvo sodas, į kurį įėjo jis ir jo mokiniai.'),
  (@b43, 18, 2, 'O Judas, kuris jį išdavė, taip pat žinojo tą vietą, nes Jėzus su savo mokiniais ten dažnai susieidavo.'),
  (@b43, 18, 3, 'Tada Judas, gavęs būrį vyrų ir pareigūnų iš vyriausiųjų kunigų ir fariziejų, ateina ten su žibintais, deglais ir ginklais.'),
  (@b43, 18, 4, 'Todėl Jėzus, žinodamas visa, kas jam turi atsitikti, išėjo ir jiems tarė: „Ko ieškote?“'),
  (@b43, 18, 5, 'Jie atsakė jam: „Jėzaus iš Nazareto“. Jėzus jiems sako: „Aš esu tas“. O Judas, kuris išdavė jį, irgi stovėjo su jais.'),
  (@b43, 18, 6, 'Tad vos tik jis ištarė jiems: „Aš esu tas“, jie atsitraukė atbulomis ir krito ant žemės.'),
  (@b43, 18, 7, 'Tada jis vėl jų paklausė: „Ko ieškote?“ Ir jie tarė: „Jėzaus iš Nazareto“.'),
  (@b43, 18, 8, 'Jėzus atsakė: „Sakiau jums, kad aš esu tas; taigi jei ieškote manęs, leiskite šitiems eiti“,'),
  (@b43, 18, 9, 'idant išsipildytų pasakymas, kurį jis kalbėjo: „Iš tų, kuriuos man davei, nepražudžiau nei vieno“.'),
  (@b43, 18, 10, 'Tada Simonas Petras, turėdamas kalaviją, išsitraukė jį, kirto aukščiausiojo kunigo tarnui ir nupjovė jo dešinę ausį. To tarno vardas buvo Malkus.'),
  (@b43, 18, 11, 'Tada Jėzus tarė Petrui: „Kišk savo kalaviją į makštį; argi negersiu taurės, kurią man davė mano Tėvas?“'),
  (@b43, 18, 12, 'Tada būrys, vadas ir žydų pareigūnai suėmė Jėzų, jį surišo'),
  (@b43, 18, 13, 'ir nuvedė jį pirma pas Aną; nes jis buvo uošvis Kajafo, kuris tais pačiais metais buvo aukščiausiasis kunigas.'),
  (@b43, 18, 14, 'Kajafas gi buvo tas, kuris patarė žydams esant naudinga, kad vienas žmogus mirtų už tautą.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b43, 18, 15, 'Ir Simonas Petras sekė paskui Jėzų ir taip padarė kitas mokinys; tas mokinys buvo pažįstamas aukščiausiajam kunigui ir įėjo su Jėzumi į aukščiausiojo kunigo rūmus.'),
  (@b43, 18, 16, 'Bet Petras stovėjo lauke prie durų. Tada išėjo tas kitas mokinys, kuris buvo pažįstamas aukščiausiajam kunigui, ir kalbėjo durininkei, ir įsivedė Petrą.'),
  (@b43, 18, 17, 'Tada mergina, durininkė, sako Petrui: „Ar ir tu tik nebūsi vienas iš šito žmogaus mokinių?“ Jis sako: „Nesu“.'),
  (@b43, 18, 18, 'Ir tarnai bei pareigūnai ten stovėjo susikūrę anglių ugnį; nes buvo šalta, ir jie šildėsi; ir Petras stovėjo su jais ir šildėsi.'),
  (@b43, 18, 19, 'Tada aukščiausiasis kunigas paklausė Jėzaus apie jo mokinius ir apie jo mokslą.'),
  (@b43, 18, 20, 'Jėzus jam atsakė: „Aš kalbėjau atvirai pasauliui; visada mokiau sinagogoje ir šventykloje, kur visada susieina žydai; ir nieko nesakiau slapčia.'),
  (@b43, 18, 21, 'Kodėl manęs klausi? Klausk tų, kurie mane girdėjo, ką jiems sakiau; štai jie žino, ką sakiau“.'),
  (@b43, 18, 22, 'Ir kai jis taip pasakė, vienas iš šalia stovinčių pareigūnų sudavė Jėzui rankos delnu, sakydamas: „Ar taip atsakai aukščiausiajam kunigui?“'),
  (@b43, 18, 23, 'Jėzus jam atsakė: „Jei kalbėjau pikta, liudyk apie pikta, bet jei gera, kodėl mane muši?“'),
  (@b43, 18, 24, 'Na, o Anas išsiuntė jį surištą pas aukščiausiąjį kunigą Kajafą.'),
  (@b43, 18, 25, 'Ir Simonas Petras stovėjo ir šildėsi. Todėl jie tarė jam: „Ar ir tu tik nebūsi vienas iš jo mokinių?“ Jis tai paneigė ir tarė: „Nesu“.'),
  (@b43, 18, 26, 'Vienas iš aukščiausiojo kunigo tarnų, giminaitis to, kuriam Petras nupjovė ausį, sako: „Argi tavęs nemačiau sode su juo?“'),
  (@b43, 18, 27, 'Tada Petras vėl išsigynė; ir tuojau pragydo gaidys.'),
  (@b43, 18, 28, 'Tada jie nuvedė Jėzų iš Kajafo į teismo rūmus; o buvo anksti; bet jie patys nėjo į teismo rūmus, kad nesusiterštų, bet kad galėtų valgyti Apėjimą.'),
  (@b43, 18, 29, 'Tada Pilotas išėjo pas juos ir tarė: „Kokį kaltinimą keliate prieš šitą žmogų?“'),
  (@b43, 18, 30, 'Jie atsakė ir jam tarė: „Jeigu jis nebūtų piktadarys, nebūtume jo tau perdavę“.'),
  (@b43, 18, 31, 'Tada Pilotas tarė jiems: „Pasiimkite jį ir teiskite jį pagal savo įstatymą“. Todėl žydai jam tarė: „Mums neteisėta nei vieno nužudyti“,'),
  (@b43, 18, 32, 'kad išsipildytų Jėzaus pasakymas, kurį jis kalbėjo, parodydamas, kokia mirtimi jis turės mirti.'),
  (@b43, 18, 33, 'Tada Pilotas vėl įėjo į teismo rūmus ir pašaukęs Jėzų jam tarė: „Ar tu esi žydų Karalius?“'),
  (@b43, 18, 34, 'Jėzus jam atsakė: „Ar tai sakai nuo savęs, ar kiti tau tai pasakė apie mane?“'),
  (@b43, 18, 35, 'Pilotas atsakė: „Ar aš žydas? Tavo tauta ir vyriausieji kunigai perdavė tave man; ką esi padaręs?“'),
  (@b43, 18, 36, 'Jėzus atsakė: „Mano karalystė yra ne iš šio pasaulio; jei mano karalystė būtų iš šio pasaulio, tuomet mano tarnai kovotų, kad nebūčiau atiduotas žydams; bet dabar mano karalystė ne iš čia“.'),
  (@b43, 18, 37, 'Todėl Pilotas jam tarė: „Tuomet tu esi karalius?“ Jėzus atsakė: „Tu sakai, kad esu karalius. Tuo tikslu aš gimiau ir dėl to atėjau į pasaulį, kad liudyčiau tiesą. Kiekvienas, kuris yra iš tiesos, klauso mano balso“.'),
  (@b43, 18, 38, 'Pilotas jam sako: „Kas yra tiesa?“ Ir tai taręs jis vėl išėjo pas žydus ir jiems sako: „Nerandu jame jokios kaltės“.'),
  (@b43, 18, 39, 'Bet jūs turite paprotį, kad paleisčiau per Apėjimą jums vieną; tad ar norite, kad paleisčiau jums žydų Karalių?“'),
  (@b43, 18, 40, 'Tada vėl jie visi šaukė, sakydami: „Ne šitą, o Barabą“. Na, o Barabas buvo plėšikas.'),
  (@b43, 19, 1, 'Taigi todėl Pilotas paėmė Jėzų ir nuplakdino jį.'),
  (@b43, 19, 2, 'Ir kareiviai nupynė erškėčių vainiką ir uždėjo jį ant jo galvos, ir apvilko jį purpuriniu rūbu,'),
  (@b43, 19, 3, 'ir tarė: „Sveikas, žydų Karaliau!“, ir mušė jį rankomis.'),
  (@b43, 19, 4, 'Taigi Pilotas vėl išėjo ir jiems sako: „Štai išvedu jį pas jus, idant žinotumėte, kad nerandu jame jokios kaltės“.'),
  (@b43, 19, 5, 'Tada Jėzus išėjo, dėvėdamas erškėčių vainiką ir purpurinį rūbą. Ir Pilotas jiems sako: „Štai žmogus!“'),
  (@b43, 19, 6, 'Todėl jį pamatę vyriausieji kunigai ir pareigūnai šaukė, sakydami: „Nukryžiuok jį, nukryžiuok!“ Pilotas jiems sako: „Pasiimkite jį ir nukryžiuokite; nes nerandu jame jokios kaltės“.'),
  (@b43, 19, 7, 'Žydai jam atsakė: „Mes turime įstatymą, ir pagal mūsų įstatymą jis turi mirti, nes jis darė save Dievo Sūnumi“.'),
  (@b43, 19, 8, 'Todėl Pilotas, išgirdęs šį pasakymą, dar labiau išsigando;'),
  (@b43, 19, 9, 'ir vėl nuėjo į teismo rūmus ir sako Jėzui: „Iš kur tu esi?“ Bet Jėzus nedavė jam atsakymo.'),
  (@b43, 19, 10, 'Tada Pilotas jam sako: „Nekalbi su manimi? Ar nežinai, kad turiu valdžią tave nukryžiuoti ir turiu valdžią tave paleisti?“'),
  (@b43, 19, 11, 'Jėzus atsakė: „Tu prieš mane visiškai neturėtum jokios valdžios, jei tau nebūtų jos duota iš aukštybių; todėl tas, kuris mane atidavė tau, turi didesnę nuodėmę“.'),
  (@b43, 19, 12, 'Ir nuo tada Pilotas siekė jį paleisti, bet žydai šaukė, sakydami: „Jei šitą paleisi, tu nesi ciesoriaus draugas – kas darosi karaliumi, tas kalba prieš ciesorių“.'),
  (@b43, 19, 13, 'Todėl Pilotas, išgirdęs šitą pasakymą, išvedė Jėzų ir atsisėdo į teismo krasę vietoje, vadinamoje Grindiniu, o hebrajiškai – Gabata.'),
  (@b43, 19, 14, 'Ir buvo Apėjimo pasiruošimas ir apie šeštą valandą; ir jis sako žydams: „Štai jūsų Karalius!“'),
  (@b43, 19, 15, 'Bet jie šaukė: „Šalin, šalin jį, nukryžiuok jį!“ Pilotas jiems sako: „Ar turiu nukryžiuoti jūsų Karalių?“ Vyriausieji kunigai atsakė: „Mes neturime karaliaus, tik ciesorių“.'),
  (@b43, 19, 16, 'Todėl tuomet jis jiems atidavė jį, kad būtų nukryžiuotas. Ir jie paėmę Jėzų nusivedė.'),
  (@b43, 19, 17, 'Ir jis, nešdamas savo kryžių, išėjo į vietą, vadinamą Kaukolės vieta, kuri hebrajiškai vadinama Golgota,'),
  (@b43, 19, 18, 'kur jie nukryžiavo jį ir su juo kitus du, iš kiekvieno šono po vieną, o Jėzų viduryje.'),
  (@b43, 19, 19, 'Ir Pilotas užrašęs antraštę uždėjo ją ant kryžiaus. Ir užrašas buvo: „JĖZUS IŠ NAZARETO, ŽYDŲ KARALIUS“.'),
  (@b43, 19, 20, 'Tad šią antraštę skaitė daugelis iš žydų, nes vieta, kur Jėzus buvo nukryžiuotas, buvo arti miesto; ir buvo užrašyta hebrajiškai, graikiškai ir lotyniškai.'),
  (@b43, 19, 21, 'Tada žydų vyriausieji kunigai tarė Pilotui: „Nerašyk: ‘Žydų Karalius’; bet, kad jis sakė: ‘Aš esu žydų Karalius’“.'),
  (@b43, 19, 22, 'Pilotas atsakė: „Ką parašiau, tą parašiau“.'),
  (@b43, 19, 23, 'Tada kareiviai, nukryžiavę Jėzų, paėmė jo drabužius ir padarė keturias dalis, kiekvienam kareiviui po dalį; ir taip pat jo marškinius; na, o marškiniai buvo be siūlės, nuo viršaus ištisai austi.'),
  (@b43, 19, 24, 'Todėl jie tarpusavyje tarė: „Neplėšykime jų, bet meskime dėl jų burtą, kieno jie bus“, idant išsipildytų Raštas, kuris sako: „Jie tarpusavyje dalijosi mano drabužius ir dėl mano apdaro metė burtą.” Dėl to kareiviai tai darė.'),
  (@b43, 19, 25, 'Na, o prie Jėzaus kryžiaus stovėjo jo motina ir jo motinos sesuo, Marija – Kleopo žmona, ir Marija Magdalietė.'),
  (@b43, 19, 26, 'Todėl Jėzus, pamatęs savo motiną ir šalia stovintį mokinį, kurį jis mylėjo, sako savo motinai: „Moterie, štai tavo sūnus!“'),
  (@b43, 19, 27, 'Po to jis sako mokiniui: „Štai tavo motina!“ Ir nuo tos valandos tas mokinys pasiėmė ją į savo namus.'),
  (@b43, 19, 28, 'Po šito, žinodamas, kad jau viskas atlikta, kad išsipildytų Raštas, Jėzus sako: „Trokštu“.'),
  (@b43, 19, 29, 'Na, o ten stovėjo indas, pilnas acto, ir jie pripildė kempinę acto, uždėjo ją ant yzopo ir pridėjo prie jo burnos.'),
  (@b43, 19, 30, 'Todėl Jėzus, ėmęs acto, tarė: „Užbaigta“, ir nuleidęs savo galvą atidavė dvasią.'),
  (@b43, 19, 31, 'Kadangi buvo pasiruošimas, kad sabato dieną kūnai nepasiliktų ant kryžiaus (nes ta sabato diena buvo didelė diena), žydai maldavo Piloto, kad būtų sulaužytos jų kojos ir jie būtų nuimti.'),
  (@b43, 19, 32, 'Tada atėjo kareiviai ir sulaužė pirmojo kojas ir kito, kuris buvo su juo nukryžiuotas.'),
  (@b43, 19, 33, 'Bet kai jie atėjo prie Jėzaus ir pamatė, kad jis jau nebegyvas, jie nelaužė jo kojų,'),
  (@b43, 19, 34, 'bet vienas iš kareivių ietimi perdūrė jo šoną, ir tuojau pat išbėgo kraujas bei vanduo.'),
  (@b43, 19, 35, 'Ir tas, kuris tai matė, liudija, ir jo liudijimas yra teisingas; ir jis žino, kad sako tiesą, idant tikėtumėte.'),
  (@b43, 19, 36, 'Nes tai atsitiko, kad išsipildytų Raštas: „Jo kaulas nebus sulaužytas“.'),
  (@b43, 19, 37, 'Ir vėl, kitas Raštas sako: „Jie žiūrės į tą, kurį perdūrė“.'),
  (@b43, 19, 38, 'Ir po to Juozapas iš Arimatėjos, būdamas Jėzaus mokinys, bet slapta dėl žydų baimės, maldavo Piloto, kad galėtų paimti Jėzaus kūną; ir Pilotas davė jam leidimą. Todėl jis atėjo ir paėmė Jėzaus kūną.'),
  (@b43, 19, 39, 'Ir taip pat atėjo Nikodemas, kuris iš pradžių atėjo pas Jėzų nakčia, ir atnešė apie šimto svarų svorio miros ir alavijo mišinio.'),
  (@b43, 19, 40, 'Tada jie paėmė Jėzaus kūną ir įvyniojo jį į linines drobes su kvepalais, kaip žydų paprotys yra laidoti.'),
  (@b43, 19, 41, 'Na, o toje vietoje, kur jis buvo nukryžiuotas, buvo sodas, o sode naujas kapas, kuriame dar niekada niekas nebuvo paguldytas.'),
  (@b43, 19, 42, 'Todėl jie ten paguldė Jėzų dėl žydų pasiruošimo dienos; nes kapas buvo čia pat.'),
  (@b43, 20, 1, 'Pirmąją savaitės dieną, anksti, kai dar buvo tamsu, ateina Marija Magdalietė prie kapo ir mato nuo kapo patrauktą akmenį.'),
  (@b43, 20, 2, 'Tada ji bėga ir ateina pas Simoną Petrą ir pas kitą mokinį, kurį mylėjo Jėzus, ir jiems sako: „Jie paėmė iš kapo Viešpatį, ir nežinome, kur jį paguldė“.'),
  (@b43, 20, 3, 'Todėl Petras ir tas kitas mokinys išėjo ir atėjo prie kapo.'),
  (@b43, 20, 4, 'Taip jie bėgo abu kartu; bet kitas mokinys aplenkė Petrą ir pirmas atėjo prie kapo.'),
  (@b43, 20, 5, 'Ir pasilenkęs ir žiūrėdamas vidun pamatė gulinčias linines drobes; tačiau į vidų nėjo.'),
  (@b43, 20, 6, 'Tada ateina paskui jį Simonas Petras ir įėjo į kapą, ir mato gulinčias linines drobes'),
  (@b43, 20, 7, 'ir skepetą, kuri buvo aplink jo galvą, ne gulinčią su lininėmis drobėmis, bet suvyniotą vietoje atskirai.'),
  (@b43, 20, 8, 'Tada įėjo ir tas kitas mokinys, kuris pirmas atėjo prie kapo, ir jis pamatė ir patikėjo.'),
  (@b43, 20, 9, 'Nes jie dar nepažino Rašto, kad jis turi prisikelti iš numirusiųjų.'),
  (@b43, 20, 10, 'Tada tie mokiniai vėl nuėjo į savuosius namus.'),
  (@b43, 20, 11, 'Bet Marija stovėjo lauke prie kapo verkdama; ir kai verkė, ji pasilenkė ir pažiūrėjo į kapą,'),
  (@b43, 20, 12, 'ir mato du angelus baltais rūbais sėdinčius – vieną prie galvos, o kitą prie kojų, kur buvo gulėjęs Jėzaus kūnas.'),
  (@b43, 20, 13, 'Ir jie sako jai: „Moterie, kodėl verki?“ Ji sako jiems: „Nes jie paėmė mano Viešpatį, ir nežinau, kur jį paguldė“.'),
  (@b43, 20, 14, 'Ir taip pasakiusi ji atsisuko atgal ir pamatė Jėzų stovintį, ir nepažino, kad tai buvo Jėzus.'),
  (@b43, 20, 15, 'Jėzus jai sako: „Moterie, kodėl verki? Ko ieškai?“ Ji, manydama, kad jis esąs sodininkas, jam sako: „Pone, jei tu jį iš čia išnešei, pasakyk man, kur jį paguldei, ir aš jį pasiimsiu“.'),
  (@b43, 20, 16, 'Jėzus jai sako: „Marija!“ Ji atsisuko ir jam sako: „Rabuni!“, tai reiškia: „Mokytojau!“'),
  (@b43, 20, 17, 'Jėzus jai sako: „Neliesk manęs; nes dar nepakilau pas savo Tėvą; bet eik pas mano brolius ir sakyk jiems: ‘Aš kylu pas savo Tėvą ir jūsų Tėvą; pas savo Dievą ir jūsų Dievą’“.'),
  (@b43, 20, 18, 'Marija Magdalietė atėjo ir pasakė mokiniams, kad ji mačiusi Viešpatį, ir kad jis jai kalbėjęs tai.'),
  (@b43, 20, 19, 'Tada, tos pačios dienos vakare, esant pirmai savaitės dienai, kai durys buvo užrakintos, kur mokiniai buvo susirinkę dėl žydų baimės, atėjo Jėzus, atsistojo viduryje ir jiems sako: „Ramybė tebūna jums!“'),
  (@b43, 20, 20, 'Ir taip pasakęs parodė jiems savo rankas ir savo šoną. Tada mokiniai, pamatę Viešpatį, apsidžiaugė.'),
  (@b43, 20, 21, 'Tada Jėzus vėl jiems tarė: „Ramybė tebūna jums! Kaip mano Tėvas mane siuntė, taip ir aš jus siunčiu“.'),
  (@b43, 20, 22, 'Ir tai taręs jis kvėpė į juos ir jiems sako: „Imkite Šventąją Dvasią:'),
  (@b43, 20, 23, 'kieno nuodėmes atleisite, tiems jos bus atleistos; ir kieno nuodėmes sulaikysite, jos bus sulaikytos“.'),
  (@b43, 20, 24, 'Bet Tomas, vienas iš dvylikos, vadinamas Didimu, nebuvo su jais, kai atėjo Jėzus.'),
  (@b43, 20, 25, 'Todėl kiti mokiniai jam tarė: „Mes matėme Viešpatį“. Bet jis tarė jiems: „Jei nepamatysiu jo rankose vinių žymės, neįdėsiu savo piršto į vinių žymę ir neįkišiu savo rankos į jo šoną, netikėsiu“.'),
  (@b43, 20, 26, 'Ir po aštuonių dienų jo mokiniai vėl buvo viduje, ir Tomas su jais; tada atėjo Jėzus, esant užrakintoms durims, atsistojo viduryje ir tarė: „Ramybė tebūna jums!“'),
  (@b43, 20, 27, 'Tada jis sako Tomui: „Ištiesk čia savo pirštą ir pažiūrėk į mano rankas; ir ištiesk čia savo ranką, ir įkišk ją į mano šoną; ir nebūk netikintis, bet tikintis“.'),
  (@b43, 20, 28, 'Ir Tomas atsakydamas tarė jam: „Mano Viešpatie ir mano Dieve!“'),
  (@b43, 20, 29, 'Jėzus jam sako: „Tomai, tu įtikėjai todėl, kad mane pamatei; palaiminti tie, kurie nematė, tačiau įtikėjo“.'),
  (@b43, 20, 30, 'Ir daug kitų ženklų iš tiesų darė Jėzus savo mokinių akivaizdoje, kurie nėra užrašyti šioje knygoje;'),
  (@b43, 20, 31, 'bet šitie yra užrašyti, idant įtikėtumėte, kad Jėzus yra Kristus, Dievo Sūnus; ir kad tikėdami turėtumėte gyvenimą per jo vardą.'),
  (@b43, 21, 1, 'Po to Jėzus vėl pasirodė mokiniams prie Tiberijo jūros; ir jis pasirodė šitaip.'),
  (@b43, 21, 2, 'Kartu buvo Simonas Petras ir Tomas, vadinamas Didimu, ir Natanaelis iš Galilėjos Kanos, ir Zebediejaus sūnūs, ir kiti du iš jo mokinių.'),
  (@b43, 21, 3, 'Simonas Petras jiems sako: „Einu žvejoti“. Jie sako jam: „Mes irgi einame su tavimi“. Jie išėjo ir tuojau įlipo į laivą; ir tą naktį jie nieko nesugavo.'),
  (@b43, 21, 4, 'Bet kai jau atėjo rytas, Jėzus stovėjo ant kranto; bet mokiniai nepažino, kad tai buvo Jėzus.'),
  (@b43, 21, 5, 'Tada Jėzus jiems sako: „Vaikai, ar turite kokio maisto?“ Jie atsakė jam: „Ne“.'),
  (@b43, 21, 6, 'Ir jis jiems tarė: „Užmeskite tinklą dešinėje laivo pusėje, ir užtiksite“. Taigi jie užmetė, ir jau nebepajėgė jo patraukti dėl žuvų gausybės.'),
  (@b43, 21, 7, 'Todėl tas mokinys, kurį mylėjo Jėzus, sako Petrui: „Tai – Viešpats“. Na, o kai Simonas Petras išgirdo, kad tai buvo Viešpats, jis apsijuosė žvejo drabužiu (nes buvo nuogas) ir metėsi į jūrą.'),
  (@b43, 21, 8, 'Ir kiti mokiniai atvyko nedideliu laivu (nes buvo netoli nuo sausumos, bet maždaug du šimtus uolekčių), vilkdami tinklą su žuvimis.'),
  (@b43, 21, 9, 'Vos tik atvykę į sausumą ten pamatė anglių laužą ir ant jo padėtą žuvį ir duoną.'),
  (@b43, 21, 10, 'Jėzus jiems sako: „Atneškite iš žuvų, kurias dabar sugavote“.'),
  (@b43, 21, 11, 'Simonas Petras nuėjo ir ištraukė į sausumą tinklą, pilną didelių žuvų, šimtą penkiasdešimt tris; ir nors jų buvo tiek daug, tačiau tinklas nesutrūko.'),
  (@b43, 21, 12, 'Jėzus jiems sako: „Ateikite ir pietaukite!“ Ir nei vienas iš mokinių nedrįso jo klausti: „Kas tu esi?“, žinodami, kad tai buvo Viešpats.'),
  (@b43, 21, 13, 'Tada ateina Jėzus, paima duoną ir duoda jiems, ir taip pat žuvį.'),
  (@b43, 21, 14, 'Na, o šitas yra trečias kartas, kai Jėzus pasirodė savo mokiniams po to, kai jis buvo prisikėlęs iš numirusių.'),
  (@b43, 21, 15, 'Tad jiems papietavus Jėzus sako Simonui Petrui: „Simonai, Jonos sūnau, ar myli mane labiau negu šitie?“ Jis sako jam: „Taip, Viešpatie; tu žinai, kad tave myliu“. Jis sako jam: „Ganyk mano avinėlius“.'),
  (@b43, 21, 16, 'Jis vėl jam sako antrą kartą: „Simonai, Jonos sūnau, ar myli mane?“ Jis sako jam: „Taip, Viešpatie; tu žinai, kad tave myliu“. Jis sako jam: „Ganyk mano avis“.'),
  (@b43, 21, 17, 'Jis sako jam trečią kartą: „Simonai, Jonos sūnau, ar myli mane?“ Petras nuliūdo, kad jis sakė jam trečią kartą: „Ar myli mane?“ Ir jis tarė jam: „Viešpatie, tu žinai viską; tu žinai, kad tave myliu“. Jėzus jam sako: „Ganyk mano avis.'),
  (@b43, 21, 18, 'Iš tiesų, iš tiesų sakau tau: kai buvai jaunas, susijuosdavai ir vaikščiodavai kur norėjai; bet kai būsi senas, ištiesi savo rankas, o kitas tave apjuos ir ves tave, kur nenori“.'),
  (@b43, 21, 19, 'Tai jis kalbėjo parodydamas, kokia mirtimi jis pašlovinsiąs Dievą. Ir tai pasakęs jis sako jam: „Sek paskui mane!“'),
  (@b43, 21, 20, 'Tada Petras atsisukęs mato iš paskos einantį mokinį, kurį Jėzus mylėjo; kuris taip pat per vakarienę palinko prie jo krūtinės ir tarė: „Viešpatie, kuris yra tas, kuris tave išduoda?“'),
  (@b43, 21, 21, 'Petras, matydamas jį, sako Jėzui: „Viešpatie, o ką darys šitas?“'),
  (@b43, 21, 22, 'Jėzus jam sako: „Jei noriu, kad jis pasiliktų, kol ateisiu, kas tau dėl to? Tu sek paskui mane“.'),
  (@b43, 21, 23, 'Tada šis pasakymas plačiai pasklido tarp brolių, kad tas mokinys nemirsiąs; tačiau Jėzus jam nesakė: „Jis nemirs“; bet: „Jei noriu, kad jis pasiliktų, kol ateisiu, kas tau dėl to?“'),
  (@b43, 21, 24, 'Šitas yra mokinys, kuris liudija apie šituos dalykus ir tai užrašė; ir mes žinome, kad jo liudijimas yra tikras.'),
  (@b43, 21, 25, 'Ir yra taip pat daug kitų dalykų, kuriuos padarė Jėzus; jei kiekvienas iš jų būtų užrašytas, manau, kad net pats pasaulis nesutalpintų knygų, kurios būtų parašytos. Amen.'),
  (@b44, 1, 1, 'Pirmąjį veikalą buvau sudaręs, o Teofiliau, apie viską, ką Jėzus pradėjo ir daryti, ir mokyti'),
  (@b44, 1, 2, 'iki tos dienos, kurioje buvo paimtas aukštyn po to, kai per Šventąją Dvasią davė įsakymus apaštalams, kuriuos buvo išsirinkęs;'),
  (@b44, 1, 3, 'kuriems taipogi jis gyvas pasirodė po savo kančios daugeliu patikimų įrodymų, jų regėtas keturiasdešimt dienų ir kalbėjęs apie Dievo karalystei priklausančius dalykus;'),
  (@b44, 1, 4, 'ir susirinkęs su jais jiems įsakė, kad neišeitų iš Jeruzalės, bet lauktų Tėvo pažado, „kurį, – jis sako, – girdėjote iš manęs.'),
  (@b44, 1, 5, 'Nes Jonas, tiesa, krikštijo vandeniu; bet jūs po nedaugelio dienų būsite pakrikštyti Šventąja Dvasia“.'),
  (@b44, 1, 6, 'Todėl kai jie buvo susirinkę, paklausė jo, sakydami: „Viešpatie, ar tu šiuo laiku vėl atkursi Izraelio karalystę?“'),
  (@b44, 1, 7, 'O jis tarė jiems: „Ne jums žinoti laikus ar laikotarpius, kuriuos Tėvas nustatė savo valdžia.'),
  (@b44, 1, 8, 'Bet kai ant jūsų ateis Šventoji Dvasia, gausite jėgą; ir būsite mano liudytojai Jeruzalėje ir visoje Judėjoje, ir Samarijoje, ir iki tolimiausio žemės pakraščio“.'),
  (@b44, 1, 9, 'Ir jam pasakius tai, jiems bežiūrint jis buvo paimtas aukštyn; ir debesis paėmė jį nuo jų akių.'),
  (@b44, 1, 10, 'Ir kol jam kylant jie įdėmiai žiūrėjo į dangų, štai prie jų stovėjo du vyrai baltais drabužiais;'),
  (@b44, 1, 11, 'kurie taip pat tarė: „Galilėjos vyrai, kodėl stovite žiūrėdami į dangų? Tas pats Jėzus, kuris nuo jūsų yra paimtas į dangų, ateis lygiai taip pat, kaip matėte jį einant į dangų“.'),
  (@b44, 1, 12, 'Tada jie sugrįžo į Jeruzalę nuo kalno, vadinamo Alyvų, kuris nuo Jeruzalės – sabato dienos kelionės atstumu.'),
  (@b44, 1, 13, 'Ir kai jie įėjo, jie užlipo į aukštutinį kambarį, kur buvo apsistojęs Petras ir Jokūbas, ir Jonas, ir Andriejus, Pilypas ir Tomas, Baltramiejus ir Matas, Alfiejaus sūnus Jokūbas ir Simonas Zelotas, ir Jokūbo brolis Judas.'),
  (@b44, 1, 14, 'Šitie visi vieningai pasiliko maldoje ir prašymuose su moterimis ir Jėzaus motina Marija, ir jo broliais.'),
  (@b44, 1, 15, 'Ir tomis dienomis atsistojo Petras mokinių viduryje ir tarė (vardų skaičius kartu buvo apie šimtą dvidešimt):'),
  (@b44, 1, 16, '„Vyrai ir broliai, turėjo išsipildyti šis Raštas, kurį Šventoji Dvasia anksčiau kalbėjo Dovydo burna apie Judą, kuris buvo vadovas tiems, kurie suėmė Jėzų.'),
  (@b44, 1, 17, 'Nes jis buvo priskaičiuotas prie mūsų ir buvo gavęs šios tarnystės dalį.'),
  (@b44, 1, 18, 'Šitas gi neteisybės atlyginimu nusipirko lauką; ir, krisdamas žemyn galva, perplyšo pusiau, ir visi jo viduriai išvirto.'),
  (@b44, 1, 19, 'Ir tai buvo žinoma visiems gyventojams Jeruzalėje; taip, kad šitas laukas jų tikrąja kalba yra vadinamas Akeldama, tai yra Kraujo laukas.'),
  (@b44, 1, 20, 'Nes yra parašyta Psalmių knygoje: ‘Jo buveinė tebūna tuščia, ir niekas joje tenegyvena; o kitas teima jo vyskupystę’.'),
  (@b44, 1, 21, 'Todėl iš tų vyrų, kurie visą laiką buvo su mumis, kai Viešpats Jėzus tarp mūsų įeidavo ir išeidavo,'),
  (@b44, 1, 22, 'pradedant nuo Jono krikšto iki tos dienos, kai jis buvo nuo mūsų paimtas aukštyn, vienas turi būti paskirtas su mumis jo prisikėlimo liudytoju“.'),
  (@b44, 1, 23, 'Ir jie paskyrė du: Juozapą, vadinamą Barsabu, kuris buvo pramintas Justu, ir Motiejų.'),
  (@b44, 1, 24, 'Ir jie meldėsi ir tarė: „Tu, Viešpatie, kuris pažįsti visų širdis, parodyk, kurį iš tų dviejų esi išsirinkęs,'),
  (@b44, 1, 25, 'kad jis užimtų dalį šitos tarnystės ir apaštalystės, nuo kurios Judas nusižengimu atkrito, kad eitų į savąją vietą“.'),
  (@b44, 1, 26, 'Ir jie metė jų burtus; ir burtas krito Motiejui; ir jis buvo priskaičiuotas prie vienuolikos apaštalų.'),
  (@b44, 2, 1, 'Ir atėjus Sekminių dienai, jie visi vieningai buvo vienoje vietoje.'),
  (@b44, 2, 2, 'Ir staiga iš dangaus atėjo garsas tarsi besiveržiančio galingo vėjo ir pripildė visą namą, kur jie sėdėjo.'),
  (@b44, 2, 3, 'Ir jiems pasirodė pasidaliję liežuviai, tarsi ugnies, ir sėdosi ant kiekvieno iš jų.'),
  (@b44, 2, 4, 'Ir jie visi buvo pripildyti Šventosios Dvasios ir pradėjo kalbėti kitomis kalbomis, kaip Dvasia jiems davė prabilti.'),
  (@b44, 2, 5, 'Ir Jeruzalėje gyveno žydai, dievobaimingi vyrai, iš kiekvienos po dangumi esančios tautos.'),
  (@b44, 2, 6, 'Na, o kai tai išgarsėjo, susirinko minia ir buvo apstulbinta, nes kiekvienas girdėjo juos kalbant savo kalba.'),
  (@b44, 2, 7, 'Ir jie visi buvo apstulbinti ir stebėjosi, sakydami vienas kitam: „Štai, argi ne visi šitie kalbantys yra galilėjiečiai?'),
  (@b44, 2, 8, 'Ir kaipgi mes kiekvienas girdime savo pačių kalba, kurioje esame gimę?'),
  (@b44, 2, 9, 'Mes – partai ir medai, ir elamitai, ir Mesopotamijos, ir Judėjos, ir Kapadokijos, Pontijos ir Azijos,'),
  (@b44, 2, 10, 'Frigijos ir Pamfilijos, Egipto ir Libijos pakraščių apie Kirėnę gyventojai, ir Romos ateiviai, žydai ir prozelitai,'),
  (@b44, 2, 11, 'kretiečiai ir arabai – girdime juos kalbant mūsų kalbomis nuostabius Dievo darbus“.'),
  (@b44, 2, 12, 'Ir jie visi buvo nustebinti ir buvo abejonėse, vienas kitam sakydami: „Ką tai reiškia?“'),
  (@b44, 2, 13, 'Kiti tyčiodamiesi tarė: „Šitie yra pilni jauno vyno“.'),
  (@b44, 2, 14, 'Bet Petras, atsistojęs su vienuolika, pakėlė savo balsą ir jiems tarė: „Judėjos vyrai ir visi, kurie gyvenate Jeruzalėje, tebūna jums tai žinoma, ir klausykite mano žodžių,'),
  (@b44, 2, 15, 'nes šitie nėra prisigėrę, kaip jūs manote, kadangi tėra trečia valanda dienos.'),
  (@b44, 2, 16, 'Bet tai yra tai, kas buvo pasakyta pranašo Joelio:'),
  (@b44, 2, 17, '‘Ir įvyks paskutinėmis dienomis, – sako Dievas, – aš išliesiu savo Dvasios ant visų kūnų; ir jūsų sūnūs ir jūsų dukros pranašaus, ir jūsų jaunuoliai matys regėjimus, ir jūsų seniai sapnuos sapnus;'),
  (@b44, 2, 18, 'ir ant savo tarnų ir ant savo tarnaičių tomis dienomis aš išliesiu savo Dvasios; ir jie pranašaus;'),
  (@b44, 2, 19, 'ir rodysiu stebuklus aukštai danguje ir ženklus žemai ant žemės; kraują ir ugnį, ir dūmų rūką;'),
  (@b44, 2, 20, 'saulė pavirs tamsybe, o mėnulis krauju prieš ateinant tai didžiai ir žymiai Viešpaties dienai;'),
  (@b44, 2, 21, 'Ir įvyks, kad kiekvienas, kuris šauksis Viešpaties vardo, bus išgelbėtas.'),
  (@b44, 2, 22, 'Izraelio vyrai, klausykitės šių žodžių; Jėzų iš Nazareto, žmogų, Dievo patvirtintą tarp jūsų stebuklais ir nuostabomis, ir ženklais, kuriuos Dievas darė per jį jūsų tarpe, kaip ir patys žinote;'),
  (@b44, 2, 23, 'jį, atiduotą Dievo nustatytu ketinimu ir išankstiniu žinojimu, jūs ėmėte ir piktomis rankomis nukryžiavote bei užmušėte;'),
  (@b44, 2, 24, 'kurį Dievas prikėlė, atrišęs mirties skausmus, nes buvo neįmanoma, kad jis būtų jos laikomas.'),
  (@b44, 2, 25, 'Nes Dovydas kalba apie jį: ‘Aš iš anksto mačiau Viešpatį visada priešais savo veidą, nes jis yra mano dešinėje, kad nesusvyruočiau;'),
  (@b44, 2, 26, 'todėl džiūgavo mano širdis ir linksminosi mano liežuvis; be to, ir mano kūnas ilsėsis viltyje,'),
  (@b44, 2, 27, 'nes tu nepaliksi mano sielos pragare nei neleisi savo Šventajam matyti supuvimo.'),
  (@b44, 2, 28, 'Tu man davei pažinti gyvenimo kelius; tu savo veidu pripildysi mane džiaugsmo’.'),
  (@b44, 2, 29, 'Vyrai ir broliai, leiskite man jums laisvai kalbėti apie patriarchą Dovydą, kad jis yra ir miręs, ir palaidotas, ir jo kapas yra su mumis iki šios dienos.'),
  (@b44, 2, 30, 'Todėl būdamas pranašas ir žinodamas, kad Dievas prisiekė jam priesaika, jog pagal kūną iš jo strėnų vaisiaus jis prikels Kristų sėdėti jo soste;'),
  (@b44, 2, 31, 'matydamas tai anksčiau, jis kalbėjo apie Kristaus prisikėlimą, kad jo siela nebuvo palikta pragare, nei jo kūnas nematė gedimo.'),
  (@b44, 2, 32, 'Šitą Jėzų Dievas prikėlė, ko mes visi esame liudytojai.'),
  (@b44, 2, 33, 'Todėl būdamas išaukštintas Dievo dešinės ir gavęs iš Tėvo Šventosios Dvasios pažadą, jis išliejo tai, ką dabar matote ir girdite.'),
  (@b44, 2, 34, 'Nes Dovydas nėra pakilęs į dangus, bet pats sako: „VIEŠPATS tarė mano Viešpačiui: ‘Sėskis mano dešinėje,'),
  (@b44, 2, 35, 'kol padarysiu tavo priešus tavo pakoju’.'),
  (@b44, 2, 36, 'Todėl tegul tvirtai žino visi Izraelio namai, kad Dievas tą patį Jėzų, kurį jūs nukryžiavote, padarė Viešpačiu ir Kristumi“.'),
  (@b44, 2, 37, 'Na, o kai jie tai išgirdo, jiems vėrė širdį, ir jie tarė Petrui ir kitiems apaštalams: „Vyrai ir broliai, ką mums daryti?“'),
  (@b44, 2, 38, 'Tada Petras jiems tarė: „Atgailaukite, ir kiekvienas iš jūsų tepasikrikštija Jėzaus Kristaus vardu nuodėmių atleidimui, ir gausite Šventosios Dvasios dovaną.'),
  (@b44, 2, 39, 'Nes pažadas yra jums ir jūsų vaikams, ir visiems, esantiems toli, būtent visiems, kiek pašauks Viešpats mūsų Dievas“.'),
  (@b44, 2, 40, 'Ir daugeliu kitų žodžių jis liudijo ir ragino, sakydamas: „Gelbėkite save nuo šitos priešgynios kartos“.'),
  (@b44, 2, 41, 'Tada tie, kurie mielai priėmė jo žodį, buvo pakrikštyti; ir tą pačią dieną prie jų prisidėjo apie tris tūkstančius sielų.'),
  (@b44, 2, 42, 'Ir jie tvirtai pasiliko apaštalų moksle ir bendrystėje, ir duonos laužyme, ir maldose.'),
  (@b44, 2, 43, 'Ir baimė apėmė kiekvieną sielą; ir daug stebuklų ir ženklų buvo padaryta per apaštalus.'),
  (@b44, 2, 44, 'Ir visi, kurie įtikėjo, buvo kartu ir viską turėjo bendra;'),
  (@b44, 2, 45, 'ir pardavė savo nuosavybes bei turtus ir padalijo juos visiems, kiek kiekvienam reikėjo.'),
  (@b44, 2, 46, 'Ir kasdien vieningai pasilikdami šventykloje ir laužydami duoną tai vienuose tai kituose namuose, jie valgė savo maistą su džiaugsmu ir širdies vienumu,'),
  (@b44, 2, 47, 'girdami Dievą ir turėdami palankumą visoje tautoje. Ir Viešpats kasdien pridėdavo prie bažnyčios tuos, kurie turėjo būti išgelbėti.'),
  (@b44, 3, 1, 'Na, o Petras ir Jonas, esant devintai valandai, maldos valandai, ėjo kartu aukštyn į šventyklą.'),
  (@b44, 3, 2, 'Ir buvo atneštas vienas raišas nuo savo motinos įsčių vyras, kurį jie kasdien padėdavo prie šventyklos vartų, vadinamų Gražiaisiais, kad prašytų išmaldos iš įeinančių į šventyklą;'),
  (@b44, 3, 3, 'jis, pamatęs Petrą ir Joną beįeinančius į šventyklą, prašė išmaldos.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b44, 3, 4, 'Ir Petras, įbedęs kartu su Jonu į jį savo akis, tarė: „Pažiūrėk į mus“.'),
  (@b44, 3, 5, 'Ir jis atkreipė savo dėmesį į juos, tikėdamasis iš jų ką nors gauti.'),
  (@b44, 3, 6, 'Tada Petras tarė: „Sidabro ir aukso neturiu; bet ką turiu, tau duodu: Jėzaus Kristaus iš Nazareto vardu kelkis ir vaikščiok!“'),
  (@b44, 3, 7, 'Ir jis paėmė jį už dešinės rankos ir pakėlė; ir tuoj pat jo kojos bei kulkšnies kaulai gavo stiprybės.'),
  (@b44, 3, 8, 'Ir jis pašokęs atsistojo ir vaikščiojo, ir su jais įėjo į šventyklą vaikščiodamas, šokinėdamas ir girdamas Dievą.'),
  (@b44, 3, 9, 'Ir visa tauta pamatė jį vaikščiojantį ir giriantį Dievą;'),
  (@b44, 3, 10, 'ir jie pažino, kad tai buvo tas, kuris dėl išmaldos sėdėdavo prie šventyklos Gražiųjų vartų; ir jie buvo pilni nusistebėjimo ir nuostabos dėl to, kas buvo jam atsitikę.'),
  (@b44, 3, 11, 'Ir kai išgydytas raišasis laikėsi Petro ir Jono, visa tauta didžiai nustebusi susibėgo pas juos į prieangį, vadinamą Saliamono.'),
  (@b44, 3, 12, 'Ir tai pamatęs Petras atsakė tautai: „Izraelio vyrai, kodėl stebitės tuo? Arba kodėl taip įdėmiai žiūrite į mus, tarsi savo pačių jėga ar šventumu būtume padarę šitą žmogų vaikščiojantį?'),
  (@b44, 3, 13, 'Abraomo ir Izaoko, ir Jokūbo Dievas, mūsų tėvų Dievas, pašlovino savo Sūnų Jėzų, kurį atidavėte ir jo išsigynėte Piloto akivaizdoje, kai tas buvo nusprendęs jį paleisti.'),
  (@b44, 3, 14, 'Bet jūs išsigynėte Šventojo ir Teisiojo ir norėjote, kad jums būtų dovanotas žmogžudys;'),
  (@b44, 3, 15, 'ir nužudėte gyvybės Kunigaikštį, kurį Dievas prikėlė iš numirusių; mes esame to liudytojai.'),
  (@b44, 3, 16, 'O jo vardas – per tikėjimą jo vardu – šitą žmogų, kurį matote ir pažįstate, padarė stiprų; taip, tikėjimas, kuris yra per jį, jam suteikė šią visišką sveikatą jūsų visų akivaizdoje.'),
  (@b44, 3, 17, 'Ir dabar, broliai, žinau, kad tai padarėte iš nežinojimo, kaip ir jūsų valdovai.'),
  (@b44, 3, 18, 'Bet tai, ką Dievas anksčiau skelbė visų savo pranašų burna, kad Kristus turėsiąs kentėti, jis taip įvykdė.'),
  (@b44, 3, 19, 'Todėl atgailaukite ir atsiverskite, kad būtų išdildytos jūsų nuodėmės, kai nuo Viešpaties veido ateis atgaivos laikai;'),
  (@b44, 3, 20, 'ir jis atsiųs Jėzų Kristų, kuris anksčiau jums buvo paskelbtas,'),
  (@b44, 3, 21, 'kurį turi priimti dangus iki visų dalykų atkūrimo laikų, ką Dievas kalbėjo visų savo šventųjų pranašų burna nuo pasaulio pradžios.'),
  (@b44, 3, 22, 'Nes Mozė tikrai sakė tėvams: ‘Viešpats, jūsų Dievas, jums prikels iš jūsų brolių pranašą – tokį, kaip mane; klausykite jo visame kame, ką jis jums sakys.'),
  (@b44, 3, 23, 'Ir įvyks, kad kiekviena siela, kuri neklausys to pranašo, bus išnaikinta iš tautos tarpo“.'),
  (@b44, 3, 24, 'Taip, ir visi pranašai nuo Samuelio ir tų, kurie sekė vėliau, kiek tik jų yra kalbėję, taip pat išpranašavo apie šitas dienas.'),
  (@b44, 3, 25, 'Jūs esate vaikai pranašų ir sandoros, kurią Dievas sudarė su mūsų tėvais, sakydamas Abraomui: ‘Ir tavo sėkloje bus palaimintos visos žemės giminės’.'),
  (@b44, 3, 26, 'Jums pirmiems Dievas, prikėlęs savo Sūnų Jėzų, pasiuntė jį palaiminti jus, nukreipdamas kiekvieną iš jūsų nuo jūsų neteisybių.'),
  (@b44, 4, 1, 'Ir jiems bekalbant tautai, pas juos atėjo kunigai, šventyklos vadas ir sadukiejai,'),
  (@b44, 4, 2, 'apimti apmaudo, kad jie mokė tautą ir skelbė prisikėlimą iš numirusiųjų per Jėzų.'),
  (@b44, 4, 3, 'Ir jie pridėjo prie jų rankas ir patalpino juos į kalėjimą iki kitos dienos, nes jau buvo vakaras.'),
  (@b44, 4, 4, 'Tačiau daugelis iš girdėjusių žodį įtikėjo; ir vyrų skaičius buvo apie penkis tūkstančius.'),
  (@b44, 4, 5, 'Ir įvyko rytojaus dieną, kad jų valdovai ir vyresnieji, ir raštininkai,'),
  (@b44, 4, 6, 'ir aukščiausiasis kunigas Anas, ir Kajafas, ir Jonas, ir Aleksandras, ir visi, kurie buvo iš aukščiausiojo kunigo giminės, susirinko Jeruzalėje.'),
  (@b44, 4, 7, 'Ir pastatę juos į vidurį jie klausė: „Kokia jėga ir kokiu vardu tai padarėte?“'),
  (@b44, 4, 8, 'Tada Petras, pripildytas Šventosios Dvasios, jiems tarė: „Tautos valdovai ir Izraelio vyresnieji,'),
  (@b44, 4, 9, 'jei šią dieną esame tardomi dėl bejėgiui žmogui padaryto gero darbo, kokiu būdu jis išgydytas;'),
  (@b44, 4, 10, 'tebūna žinoma jums visiems ir visai Izraelio tautai, kad per vardą Jėzaus Kristaus iš Nazareto, kurį nukryžiavote, kurį Dievas prikėlė iš numirusiųjų – per jį šitas vyras jūsų akivaizdoje stovi sveikas.'),
  (@b44, 4, 11, 'Šitas yra akmuo, kurį jūs, statytojai, laikėte nieku, kuris tapo kertės pagrindu.'),
  (@b44, 4, 12, 'Ir niekame kitame nėra išgelbėjimo, nes po dangumi tarp žmonių nėra duoto kito vardo, kuriuo turime būti išgelbėti“.'),
  (@b44, 4, 13, 'Na, o matydami Petro ir Jono drąsą ir pastebėję, kad jie buvo nemokyti ir neišprusę žmonės, jie stebėjosi; ir atpažino juos, kad jie buvę su Jėzumi.'),
  (@b44, 4, 14, 'Ir matydami su jais stovintį išgydytąjį žmogų jie negalėjo nieko pasakyti prieš.'),
  (@b44, 4, 15, 'Bet, įsakę jiems pasišalinti iš tarybos, jie tarėsi tarpusavyje,'),
  (@b44, 4, 16, 'sakydami: „Ką darysime šitiems žmonėms? Nes iš tikrųjų jų padarytas pastebimas stebuklas, aiškus visiems, gyvenantiems Jeruzalėje; ir negalime to paneigti.'),
  (@b44, 4, 17, 'Bet kad tai toliau neišplistų tautos tarpe, griežtai juos pagrasinkime, kad jie nuo šiol nei vienam nekalbėtų šituo vardu“.'),
  (@b44, 4, 18, 'Ir jie pašaukė juos ir įsakė išvis nekalbėti nei nemokyti Jėzaus vardu.'),
  (@b44, 4, 19, 'Bet Petras ir Jonas atsakydami tarė jiems: „Spręskite, ar teisinga yra Dievo akyse klausyti jūsų labiau negu Dievo.'),
  (@b44, 4, 20, 'Nes mes negalime nekalbėti to, ką matėme ir girdėjome“.'),
  (@b44, 4, 21, 'Taigi dar jiems pagrasinę jie paleido juos, neradę, kaip galėtų juos nubausti, dėl tautos; nes visi šlovino Dievą už tai, kas buvo padaryta.'),
  (@b44, 4, 22, 'Nes žmogus, ant kurio buvo parodytas šis gydymo stebuklas, buvo virš keturiasdešimties metų.'),
  (@b44, 4, 23, 'Ir paleisti jie nuėjo pas savuosius ir išpasakojo viską, ką jiems buvo sakę vyriausieji kunigai ir vyresnieji.'),
  (@b44, 4, 24, 'Ir tai išgirdę jie vieningai pakėlė savo balsą į Dievą ir tarė: „Viešpatie, tu esi Dievas, kuris padarei dangų ir žemę, ir jūrą, ir visa, kas juose yra,'),
  (@b44, 4, 25, 'kuris savo tarno Dovydo burna tarei: ‘Kodėl įnirto pagonys, ir tauta prasimanė tuštybių?'),
  (@b44, 4, 26, 'Žemės karaliai atsistojo, ir valdovai susirinko prieš Viešpatį ir prieš jo Kristų’.'),
  (@b44, 4, 27, 'Nes iš tiesų prieš tavo šventąjį vaiką Jėzų, kurį tu patepei, susirinko Erodas ir Pontijus Pilotas su pagonimis, ir Izraelio tauta,'),
  (@b44, 4, 28, 'kad darytų tai, ką tavo ranka ir tavo nutarimas iš anksto buvo nulėmę, idant įvyktų.'),
  (@b44, 4, 29, 'O dabar, Viešpatie, pažvelk į jų grasinimus ir duok savo tarnams, kad visa drąsa jie galėtų kalbėti tavo žodį,'),
  (@b44, 4, 30, 'ištiesdamas savo ranką gydyti; ir kad būtų daromi ženklai ir stebuklai tavo šventojo vaiko Jėzaus vardu“.'),
  (@b44, 4, 31, 'Ir kai jie pasimeldė, sudrebėjo vieta, kur jie buvo susirinkę; ir jie visi buvo pripildyti Šventosios Dvasios ir drąsiai kalbėjo Dievo žodį.'),
  (@b44, 4, 32, 'Ir daugybė tų, kurie tikėjo, buvo vienos širdies ir vienos sielos; ir nei vienas nesakė, kad tai, ką kuris turėjo, yra jo nuosava; bet visa jiems buvo bendra.'),
  (@b44, 4, 33, 'Ir su didžiule jėga apaštalai liudijo apie Viešpaties Jėzaus prisikėlimą, ir didelė malonė buvo ant jų visų.'),
  (@b44, 4, 34, 'Ir nebuvo tarp jų nei vieno stokojančio, nes visi, kurie buvo žemių ar namų savininkai, pardavė juos ir atnešė vertes to, kas parduota,'),
  (@b44, 4, 35, 'ir padėjo prie apaštalų kojų; ir buvo dalijama kiekvienam pagal tai, kiek kam reikėjo.'),
  (@b44, 4, 36, 'Ir Jozė, kuris apaštalų buvo pramintas Barnabu (kas išvertus yra „Paguodos sūnus“), levitas iš Kipro šalies,'),
  (@b44, 4, 37, 'turėdamas žemės ją pardavė ir atnešė pinigus, ir padėjo prie apaštalų kojų.'),
  (@b44, 5, 1, 'Bet vienas žmogus, vardu Ananijas, su savo žmona Sapfyra pardavė nuosavybę'),
  (@b44, 5, 2, 'ir, jo žmonai irgi žinant, pasilaikė dalį vertės ir atnešęs tam tikrą dalį padėjo ją prie apaštalų kojų.'),
  (@b44, 5, 3, 'Bet Petras tarė: „Ananijau, kodėl šėtonas pripildė tavo širdį, kad meluotum Šventajai Dvasiai ir pasilaikytum dalį žemės vertės?'),
  (@b44, 5, 4, 'Kol tai dar pasiliko, ar tai nebuvo tavo? Ir kai buvo parduota, argi tai nebuvo tavo valdžioje? Kodėl sumanei šį dalyką savo širdyje? Tu pamelavai ne žmonėms, bet Dievui“.'),
  (@b44, 5, 5, 'Ir Ananijas, girdėdamas tuos žodžius, parkrito ir išleido dvasią; ir didžiulė baimė apėmė visus, kurie tai girdėjo.'),
  (@b44, 5, 6, 'Ir pakilo jaunuoliai, suvyniojo jį, išnešė ir palaidojo.'),
  (@b44, 5, 7, 'Ir maždaug po trijų valandų tarpo, nežinodama, kas buvo atsitikę, įėjo jo žmona.'),
  (@b44, 5, 8, 'Ir Petras jai atsakė: „Sakyk man, ar už tiek pardavėte žemę?“ Ir ji tarė: „Taip, už tiek“.'),
  (@b44, 5, 9, 'Tada Petras jai tarė: „Kaip tai yra, kad susitarėte gundyti Viešpaties Dvasią? Kojos štai tų, kurie palaidojo tavo vyrą, yra ties durimis, ir tave išneš“.'),
  (@b44, 5, 10, 'Tuomet ji bematant parkrito prie jo kojų ir išleido dvasią; ir įėjo jaunuoliai, rado ją negyvą ir išnešė, ir palaidojo šalia jos vyro.'),
  (@b44, 5, 11, 'Ir didžiulė baimė apėmė visą bažnyčią ir visus, kurie tai girdėjo.'),
  (@b44, 5, 12, 'Ir per apaštalų rankas tautos tarpe buvo daroma daug ženklų ir stebuklų (ir jie visi vieningai buvo Saliamono prieangyje.'),
  (@b44, 5, 13, 'O iš kitų nei vienas nedrįso prie jų prisijungti; bet tauta juos aukštino.'),
  (@b44, 5, 14, 'Ir prie Viešpaties prisidėjo vis daugiau tikinčiųjų, tiek vyrų, tiek moterų daugybė);'),
  (@b44, 5, 15, 'taip, kad į gatves jie nešė ligonius ir guldė juos ant patalų bei lovų, idant, Petrui praeinant pro šalį, bent jo šešėlis kristų ant kurių nors iš jų.'),
  (@b44, 5, 16, 'Taip pat į Jeruzalę atėjo daugybė iš aplinkinių miestų, nešdami sergančius žmones ir tuos, kurie buvo nešvarių dvasių varginami, ir jie visi buvo išgydyti.'),
  (@b44, 5, 17, 'Tada pakilo aukščiausiasis kunigas ir visi, buvusieji su juo (kurie yra sadukiejų sekta), ir buvo pilni pasipiktinimo,'),
  (@b44, 5, 18, 'ir, pridėję prie apaštalų rankas, pasodino juos į viešą kalėjimą.'),
  (@b44, 5, 19, 'Bet Viešpaties angelas naktį atidarė kalėjimo duris, išvedė juos ir tarė:'),
  (@b44, 5, 20, '„Eikite, atsistokite ir kalbėkite tautai šventykloje visus šio gyvenimo žodžius“.'),
  (@b44, 5, 21, 'Ir tai išgirdę jie anksti ryte įėjo į šventyklą ir mokė. Bet atėjo aukščiausiasis kunigas ir buvusieji su juo, sušaukė tarybą bei visą Izraelio vaikų vyresnybę ir pasiuntė į kalėjimą, kad juos atvestų.'),
  (@b44, 5, 22, 'Bet kai atėjo pareigūnai ir nerado jų kalėjime, jie sugrįžo ir papasakojo,'),
  (@b44, 5, 23, 'sakydami: „Iš tikrųjų mes radome kalėjimą visiškai saugiai užrakintą ir sargus, stovinčius lauke prie durų, bet atidarę viduje nieko neradome“.'),
  (@b44, 5, 24, 'Na, o aukščiausiasis kunigas, šventyklos vadas ir vyriausieji kunigai išgirdę tuos dalykus nebuvo tikri, į ką tai išaugs.'),
  (@b44, 5, 25, 'Tada atėjo vienas ir jiems pasakė, tardamas: „Štai vyrai, kuriuos pasodinote į kalėjimą, stovi šventykloje ir moko tautą“.'),
  (@b44, 5, 26, 'Tada vadas su pareigūnais nuėjo ir atsivedė juos be prievartos, nes bijojo tautos, kad jų neužmėtytų akmenimis.'),
  (@b44, 5, 27, 'Ir atvedę pastatė juos tarybos akivaizdoje; ir aukščiausiasis kunigas jų paklausė,'),
  (@b44, 5, 28, 'sakydamas: „Argi griežtai jums neįsakėme, kad nemokytumėte šituo vardu? O štai jūs pripildėte Jeruzalę savo mokslu ir norite užtraukti ant mūsų šito žmogaus kraują“.'),
  (@b44, 5, 29, 'Tada Petras ir kiti apaštalai atsakydami tarė: „Mes verčiau turime klausyti Dievo nei žmonių.'),
  (@b44, 5, 30, 'Mūsų tėvų Dievas prikėlė Jėzų, kurį užmušėte ir pakabinote ant medžio.'),
  (@b44, 5, 31, 'Jį Dievas išaukštino savo dešine, kad būtų Kunigaikštis ir Gelbėtojas, idant suteiktų Izraeliui atgailą ir nuodėmių atleidimą.'),
  (@b44, 5, 32, 'Ir mes esame jo liudytojai šitų dalykų; ir taip pat Šventoji Dvasia, kurią Dievas davė tiems, kurie jam paklūsta“.'),
  (@b44, 5, 33, 'Kai jie tai išgirdo, jiems vėrė širdį, ir jie tarėsi juos užmušti.'),
  (@b44, 5, 34, 'Tada taryboje atsistojo vienas fariziejus, vardu Gamalielis, įstatymo mokytojas, visoje tautoje gerbiamas, ir įsakė trumpam išvesti apaštalus;'),
  (@b44, 5, 35, 'ir jiems tarė: „Izraelio vyrai, žiūrėkitės, ką ketinate daryti dėl šitų žmonių.'),
  (@b44, 5, 36, 'Nes pirmiau šių dienų iškilo Teudas, besididžiuojantis esąs kažin kas; prie kurio prisijungė skaičiumi apie keturis šimtus vyrų; kuris buvo užmuštas; ir visi, kurie jo klausė, išsisklaidė ir į nieką pavirto.'),
  (@b44, 5, 37, 'Po šito vyro, surašymo dienomis, pakilo Judas iš Galilėjos ir patraukė paskui save daug žmonių; jis irgi pražuvo; ir visi, kurie jam pakluso, buvo išsklaidyti.'),
  (@b44, 5, 38, 'O dabar sakau jums: susilaikykite nuo šitų žmonių ir palikite juos ramybėje; nes jei šis sumanymas ar šis darbas yra iš žmonių, tai nueis niekais,'),
  (@b44, 5, 39, 'bet jei tai yra iš Dievo, jūs negalite to suardyti; kad kartais nebūtumėte rasti ir kovojantys prieš Dievą“.'),
  (@b44, 5, 40, 'Ir jie sutiko su juo; ir pasišaukę apaštalus ir juos primušę įsakė, kad jie nekalbėtų Jėzaus vardu, ir juos paleido.'),
  (@b44, 5, 41, 'Ir jie išėjo iš tarybos akivaizdos, džiaugdamiesi, kad buvo palaikyti vertais dėl jo vardo kentėti gėdą.'),
  (@b44, 5, 42, 'Ir kasdien šventykloje ir kiekvienuose namuose jie nesiliovė mokyti ir skelbti Jėzų Kristų.'),
  (@b44, 6, 1, 'Ir tomis dienomis, kai mokinių skaičius daugėjo, kilo graikiškų murmėjimas prieš hebrajus, kadangi kasdieniame tarnavime buvo apleidžiamos jų našlės.'),
  (@b44, 6, 2, 'Tuomet dvylika pasišaukė mokinių minią ir tarė: „Tai ne priežastis, kad paliktume Dievo žodį ir tarnautume prie stalų.'),
  (@b44, 6, 3, 'Todėl, broliai, paieškokite savo tarpe septynių dorą atsiliepimą turinčių, Šventosios Dvasios ir išminties pilnų vyrų, kuriuos galėtume paskirti šitam reikalui.'),
  (@b44, 6, 4, 'O mes be perstojo atsidėsime maldai ir žodžio tarnybai“.'),
  (@b44, 6, 5, 'Ir tas pasakymas patiko visai miniai; ir jie išsirinko Steponą, vyrą pilną tikėjimo ir Šventosios Dvasios, ir Pilypą, ir Prochorą, ir Nikanorą, ir Timoną, ir Parmeną, ir Nikolą – prozelitą iš Antiocho,'),
  (@b44, 6, 6, 'kuriuos jie pastatė apaštalų akivaizdon; ir šie pasimeldę uždėjo ant jų savo rankas.'),
  (@b44, 6, 7, 'Ir Dievo žodis augo; ir mokinių skaičius Jeruzalėje labai didėjo; ir didelis kunigų būrys pakluso tikėjimui.'),
  (@b44, 6, 8, 'O Steponas, pilnas tikėjimo ir jėgos, darė tautos tarpe didžias nuostabas ir stebuklus.'),
  (@b44, 6, 9, 'Tada pakilo kai kurie iš sinagogos, vadinamos libertinų ir kirėniečių, ir aleksandriečių, ir iš tų iš Kilikijos bei Azijos, ginčidamiesi su Steponu.'),
  (@b44, 6, 10, 'Ir jie nepajėgė pasipriešinti išminčiai ir Dvasiai, kuria jis kalbėjo.'),
  (@b44, 6, 11, 'Tada jie sukurstė vyrus, kurie sakė: „Mes girdėjome jį kalbant piktžodžiavimo žodžius prieš Mozę ir Dievą“.'),
  (@b44, 6, 12, 'Ir jie sukurstė tautą, vyresniuosius bei raštininkus ir užpuolę pagavo jį, ir atvedė į tarybą,'),
  (@b44, 6, 13, 'ir pastatė melagingus liudytojus, kurie tarė: „Šitas žmogus nesiliauja kalbėti piktžodžiavimo žodžių prieš šią šventą vietą ir įstatymą;'),
  (@b44, 6, 14, 'nes girdėjome jį kalbant, kad šitas Jėzus iš Nazareto sunaikins šią vietą ir pakeis papročius, kuriuos mums davė Mozė.'),
  (@b44, 6, 15, 'Ir visi sėdintys taryboje įdėmiai žiūrėdami į jį pamatė jo veidą, tarsi tai būtų buvęs angelo veidas.'),
  (@b44, 7, 1, 'Tuomet aukščiausiasis kunigas tarė: „Ar taip yra?“'),
  (@b44, 7, 2, 'Ir jis tarė: „Vyrai, broliai ir tėvai, klausykite: Šlovės Dievas pasirodė mūsų tėvui Abraomui, kai jis buvo Mesopotamijoje, pirmiau nei jis gyveno Harane,'),
  (@b44, 7, 3, 'ir jam tarė: ‘Išeik iš savo krašto ir iš savo giminės ir ateik į šalį, kurią tau parodysiu’.'),
  (@b44, 7, 4, 'Tada jis išėjo iš kaldėjų šalies ir apsigyveno Harane; ir iš ten, numirus jo tėvui, jis perkėlė jį į šią šalį, kurioje jūs dabar gyvenate.'),
  (@b44, 7, 5, 'Ir nedavė jam jokio paveldo joje, ne, nei jo kojai pastatyti; tačiau pažadėjo duosiąs ją nuosavybėn jam ir jo sėklai po jo, jam dar neturint vaiko.'),
  (@b44, 7, 6, 'Ir Dievas šitaip kalbėjo, kad jo sėkla turės laikinai apsigyventi svetimoje šalyje; ir kad jie juos pavergs bei piktai su jais elgsis keturis šimtus metų.'),
  (@b44, 7, 7, '‘O tautą, kuriai jie vergaus, aš teisiu, – tarė Dievas; – ir po to jie išeis ir man tarnaus šioje vietoje’.'),
  (@b44, 7, 8, 'Ir jis davė jam apipjaustymo sandorą; ir taip Abraomas pagimdė Izaoką ir apipjaustė jį aštuntą dieną; ir Izaokas pagimdė Jokūbą; ir Jokūbas pagimdė dvyliką patriarchų.'),
  (@b44, 7, 9, 'Ir patriarchai, pavydo paskatinti, pardavė Juozapą į Egiptą, bet Dievas buvo su juo'),
  (@b44, 7, 10, 'ir išgelbėjo jį iš visų jo vargų, ir davė jam palankumą bei išmintį Egipto karaliaus faraono akivaizdoje; ir jis paskyrė jį Egipto ir visų savo namų valdytoju.'),
  (@b44, 7, 11, 'Na, o visai Egipto šaliai ir Kanaanui atėjo badas ir didis vargas; ir mūsų tėvai nerado prasimaitinimo.'),
  (@b44, 7, 12, 'Bet Jokūbas išgirdęs, kad Egipte yra javų, išsiuntė mūsų tėvus pirmą kartą.'),
  (@b44, 7, 13, 'O antrąkart Juozapas buvo atpažintas savo brolių; ir Juozapo giminė tapo žinoma faraonui.'),
  (@b44, 7, 14, 'Tada Juozapas pasiuntė ir pasikvietė savo tėvą Jokūbą bei visą savo giminę, septyniasdešimt penkias sielas.'),
  (@b44, 7, 15, 'Taigi Jokūbas nuėjo žemyn į Egiptą ir mirė jis ir mūsų tėvai,'),
  (@b44, 7, 16, 'ir buvo pergabenti į Sichemą, ir paguldyti į kapą, kurį Abraomas nupirko už pinigų sumą iš Sichemo tėvo Emoro sūnų.'),
  (@b44, 7, 17, 'Bet kai artėjo laikas pažado, kurį Dievas prisiekė Abraomui, tauta augo ir dauginosi Egipte,'),
  (@b44, 7, 18, 'kol iškilo kitas karalius, kuris nepažinojo Juozapo.'),
  (@b44, 7, 19, 'Tas elgėsi klastingai su mūsų gimine ir piktai elgėsi su mūsų tėvais, kad jie išmestų savo mažus vaikus, idant jie nebegyventų.'),
  (@b44, 7, 20, 'Tuo laiku gimė Mozė ir buvo nepaprastai gražus, ir tris mėnesius buvo auginamas savo tėvo namuose;'),
  (@b44, 7, 21, 'ir, kai jis buvo išmestas, jį paėmė faraono duktė ir augino jį kaip savo sūnų.'),
  (@b44, 7, 22, 'Ir Mozė buvo išmokytas visos egiptiečių išminties ir buvo galingas žodžiais bei darbais.'),
  (@b44, 7, 23, 'O kai jis buvo pilnų keturiasdešimties metų, jam atėjo į širdį aplankyti savo brolius, Izraelio vaikus.'),
  (@b44, 7, 24, 'Ir matydamas vieną jų neteisingai kenčiantį, apgynė jį ir atkeršijo už engiamąjį bei sumušė egiptietį;'),
  (@b44, 7, 25, 'nes manė, kad jo broliai suprasią, kad Dievas per jo ranką juos išgelbės; bet jie nesuprato.'),
  (@b44, 7, 26, 'Ir ateinančią dieną jis pasirodė jiems kai jie kovojo, ir norėjo juos vėl suvienyti, sakydamas: ‘Ponai, jūs esate broliai; kodėl vienas kitą skriaudžiate?’'),
  (@b44, 7, 27, 'Bet tas, kuris darė neteisybę savo artimui, nustūmė jį šalin, sakydamas: ‘Kas tave paskyrė mūsų valdovu ir teisėju?'),
  (@b44, 7, 28, 'Ar nori nužudyti mane, kaip vakar nužudei egiptietį?’'),
  (@b44, 7, 29, 'Tada Mozė pabėgo dėl šio pasakymo ir buvo ateivis Midjano šalyje, kur pagimdė du sūnus.'),
  (@b44, 7, 30, 'Ir, pasibaigus keturiasdešimčiai metų, Sinajaus kalno dykumoje jam pasirodė Viešpaties angelas, ugnies liepsnoje, krūme.'),
  (@b44, 7, 31, 'Mozė pamatęs stebėjosi šiuo reginiu, ir kai artinosi į tai pažiūrėti, jam atėjo Viešpaties balsas,'),
  (@b44, 7, 32, 'sakydamas: ‘Aš esu tavo tėvų Dievas, Abraomo Dievas ir Izaoko Dievas, ir Jokūbo Dievas’. Tada Mozė drebėjo ir nedrįso žiūrėti.'),
  (@b44, 7, 33, 'Tada Viešpats jam tarė: ‘Nusiimk nuo kojų apavą, nes vieta, kur stovi, yra šventa žemė.'),
  (@b44, 7, 34, 'Mačiau, mačiau vargą savo tautos, esančios Egipte, ir girdėjau jų dejones, ir atėjau žemyn jų išvaduoti. Ir dabar ateik, pasiųsiu tave į Egiptą’.'),
  (@b44, 7, 35, 'Šitą Mozę, kurio jie atsisakė, sakydami: ‘Kas tave paskyrė valdovu ir teisėju?’, tą patį Dievas pasiuntė būti valdovu ir išvaduotoju per ranką angelo, kuris jam pasirodė krūme.'),
  (@b44, 7, 36, 'Jis išvedė juos, parodęs stebuklus ir ženklus Egipto šalyje bei Raudonoje jūroje ir keturiasdešimt metų dykumoje.'),
  (@b44, 7, 37, 'Šis yra tas Mozė, kuris sakė Izraelio vaikams: ‘Viešpats, jūsų Dievas, jums prikels iš jūsų brolių pranašą, tokį kaip mane; jo klausysite’.'),
  (@b44, 7, 38, 'Jis yra tas, kuris buvo bažnyčioje, dykumoje su angelu, jam kalbėjusiu Sinajaus kalne, ir su mūsų tėvais; jis gavo gyvus pasakymus, kad mums duotų;'),
  (@b44, 7, 39, 'jam mūsų tėvai nenorėjo paklusti, bet atstūmė jį nuo savęs ir savo širdyse vėl atsigręžė į Egiptą,'),
  (@b44, 7, 40, 'sakydami Aaronui: ‘Padaryk mums dievų, kad eitų priekyje mūsų, nes dėl šito Mozės, kuris išvedė mus iš Egipto šalies, mes nežinome, kas jam nutiko’.'),
  (@b44, 7, 41, 'Ir tomis dienomis jie padarė veršį bei atnašavo stabui auką ir džiaugėsi savo pačių rankų darbais.'),
  (@b44, 7, 42, 'Tada Dievas nusisuko ir paliko juos garbinti dangaus kariuomenę; kaip yra parašyta pranašų knygoje: ‘O Izraelio namai, ar man atnašavote papjautus gyvulius ir aukas dykumoje keturiasdešimt metų?'),
  (@b44, 7, 43, 'Taip, jūs pasiėmėte Molocho padangtę ir jūsų dievo Remfano žvaigždę, atvaizdus, kuriuos pasidarėte, kad juos garbintumėte; ir aš išgabensiu jus už Babilono’.'),
  (@b44, 7, 44, 'Mūsų tėvai turėjo liudijimo padangtę dykumoje, kaip jis buvo nurodęs, sakydamas Mozei, kad padarytų ją pagal pavyzdį, kurį buvo matęs.'),
  (@b44, 7, 45, 'Kurią taip pat mūsų tėvai, atėję vėliau, įnešė su Jėzumi į nuosavybę pagonių, kuriuos Dievas išvarė mūsų tėvų akivaizdoje, iki Dovydo dienų;'),
  (@b44, 7, 46, 'kuris rado malonę Dievo akivaizdoje ir troško surasti padangtę Jokūbo Dievui.'),
  (@b44, 7, 47, 'Bet Saliamonas jam pastatė namus.'),
  (@b44, 7, 48, 'Tačiau Aukščiausiasis negyvena rankomis padarytose šventyklose; kaip sako pranašas:'),
  (@b44, 7, 49, '‘Dangus yra mano sostas, o žemė – mano pakojis; kokius namus norite man pastatyti? – sako Viešpats, – arba kokia yra mano poilsio vieta?'),
  (@b44, 7, 50, 'Argi ne mano rankos padarė visa tai?’'),
  (@b44, 7, 51, 'Jūs, kietasprandžiai ir neapipjaustytomis širdimis bei ausimis, jūs visuomet priešinatės Šventajai Dvasiai: kaip jūsų tėvai darė, taip ir jūs.'),
  (@b44, 7, 52, 'Kurio iš pranašų nepersekiojo jūsų tėvai? Ir jie užmušė tuos, kurie iš anksto paskelbė Teisiojo atėjimą; kurio dabar esate išdavikai ir žudikai;'),
  (@b44, 7, 53, 'kurie gavote įstatymą per angelų išsidėstymą ir jo nesilaikėte“.'),
  (@b44, 7, 54, 'Kai jie išgirdo tai, jiems vėrė širdį, ir jie griežė ant jo dantimis.'),
  (@b44, 7, 55, 'Bet jis, būdamas pilnas Šventosios Dvasios, įdėmiai žiūrėjo į dangų ir pamatė Dievo šlovę bei Jėzų, stovintį Dievo dešinėje,'),
  (@b44, 7, 56, 'ir tarė: „Štai matau atsivėrusius dangus ir žmogaus Sūnų, stovintį Dievo dešinėje“.'),
  (@b44, 7, 57, 'Tada jie šaukė garsiu balsu, užsikimšo savo ausis ir vieningai puolę ant jo'),
  (@b44, 7, 58, 'išmetė jį iš miesto ir užmėtė akmenimis; ir liudytojai padėjo savo drabužius prie kojų jaunuolio, vardu Saulius.'),
  (@b44, 7, 59, 'Ir jie užmėtė akmenimis Steponą, besišaukiantį Dievo ir sakantį: „Viešpatie Jėzau, priimk mano dvasią!“'),
  (@b44, 7, 60, 'Ir jis atsiklaupė bei šaukė garsiu balsu: „Viešpatie, neįskaityk jiems šios nuodėmės!“ Ir tai pasakęs jis užmigo.'),
  (@b44, 8, 1, 'Ir Saulius pritarė jo mirčiai. Ir tuo laiku buvo didelis Jeruzalėje esančios bažnyčios persekiojimas; ir jie visi, išskyrus apaštalus, pasklido po Judėjos ir Samarijos sritis.'),
  (@b44, 8, 2, 'Ir dievobaimingi vyrai nunešė palaidoti Steponą ir labai jį apraudojo.'),
  (@b44, 8, 3, 'Na o Saulius niokojo bažnyčią, įeidamas į kiekvienus namus ir ištempdamas vyrus bei moteris atiduodavo juos į kalėjimą.'),
  (@b44, 8, 4, 'Todėl tie, kurie buvo išsisklaidę, ėjo visur skelbdami žodį.'),
  (@b44, 8, 5, 'Tada Pilypas nusileido į Samarijos miestą ir skelbė jiems Kristų.'),
  (@b44, 8, 6, 'O tauta vieningai kreipė dėmesį į tai, ką kalbėjo Pilypas, girdėdami ir matydami stebuklus, kuriuos jis darė.'),
  (@b44, 8, 7, 'Nes netyrosios dvasios, šaukdamos garsiu balsu, išėjo iš daugelio, kurie buvo jų apsėsti; ir daugelis paralyžiumi ištiktų bei luošų buvo išgydyti.'),
  (@b44, 8, 8, 'Ir tame mieste buvo didelis džiaugsmas.'),
  (@b44, 8, 9, 'Bet buvo vienas vyras, vardu Simonas, kuris anksčiau tame pačiame mieste burtininkavo ir apkerėjo Samarijos tautą, skelbdamas save kokiu tai didžiu;'),
  (@b44, 8, 10, 'į kurį jie visi kreipė dėmesį: nuo mažiausiojo iki didžiausojo, sakydami: „Šitas yra didelė Dievo jėga“.'),
  (@b44, 8, 11, 'Ir jie paisydavo jo todėl, kad ilgą laiką jis juos buvo apkerėjęs burtais.'),
  (@b44, 8, 12, 'Bet kai jie įtikėjo Pilypu, skelbiančiu dalykus apie Dievo karalystę ir Jėzaus Kristaus vardą, jie buvo pakrikštyti – tiek vyrai, tiek moterys.'),
  (@b44, 8, 13, 'Tuomet ir pats Simonas įtikėjo ir, kai buvo pakrikštytas, pasiliko su Pilypu ir stebėjosi, matydamas daromus stebuklus ir ženklus.'),
  (@b44, 8, 14, 'Na, o apaštalai, esantys Jeruzalėje, išgirdę, kad Samarija priėmė Dievo žodį, pasiuntė jiems Petrą ir Joną,'),
  (@b44, 8, 15, 'kurie atėję žemyn meldėsi už juos, kad jie gautų Šventąją Dvasią'),
  (@b44, 8, 16, '(nes ji dar nebuvo nupuolusi nei ant vieno iš jų – jie tik buvo pakrikštyti Viešpaties Jėzaus vardu).'),
  (@b44, 8, 17, 'Tada jie uždėjo ant jų savo rankas, ir jie gavo Šventąją Dvasią.'),
  (@b44, 8, 18, 'O Simonas, pamatęs, kad apaštalų rankų uždėjimu buvo duota Šventoji Dvasia, pasiūlė jiems pinigų,'),
  (@b44, 8, 19, 'sakydamas: „Duokite ir man šią galią, kad tas, ant kurio uždėsiu rankas, gautų Šventąją Dvasią“.'),
  (@b44, 8, 20, 'Bet Petras jam tarė: „Tavo pinigai tepražūna su tavimi, nes tu galvojai, kad Dievo dovana gali būti nupirkta už pinigus.'),
  (@b44, 8, 21, 'Tu šiame dalyke neturi nei dalies, nei dalios, nes tavo širdis yra neteisi Dievo akyse.'),
  (@b44, 8, 22, 'Todėl atgailauk dėl šios savo nedorybės ir melsk Dievo, galbūt tau bus atleistas tavo širdies ketinimas.'),
  (@b44, 8, 23, 'Nes matau, kad esi kartybės tulžyje ir neteisybės pančiuose“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b44, 8, 24, 'Tada Simonas atsakydamas tarė: „Melskite už mane Viešpatį, kad manęs neištiktų niekas iš to, ką sakėte“.'),
  (@b44, 8, 25, 'Ir paliudiję bei paskelbę Viešpaties žodį jie grįžinėjo į Jeruzalę ir skelbė evangeliją daugelyje samariečių kaimų.'),
  (@b44, 8, 26, 'Ir Viešpaties angelas kalbėjo Pilypui, sakydamas: „Kelkis ir eik pietų link, į kelią, kuris eina žemyn iš Jeruzalės į Gazą, kuri yra dykuma“.'),
  (@b44, 8, 27, 'Ir jis atsikėlė ir nuėjo; ir štai vyras iš Etiopijos, didelės valdžios eunuchas, pavaldus etiopų karalienei Kandakei, kuris turėjo valdžią visam jos turtui ir buvo atėjęs į Jeruzalę pagarbinti,'),
  (@b44, 8, 28, 'buvo begrįžtąs ir sėdėdamas savo vežime skaitė pranašą Izaiją.'),
  (@b44, 8, 29, 'Tada Dvasia tarė Pilypui: „Prieik ir prisijunk prie šito vežimo“.'),
  (@b44, 8, 30, 'Ir Pilypas nubėgo ten prie jo ir išgirdo jį skaitant pranašą Izaiją, ir tarė: „Ar supranti, ką skaitai?“'),
  (@b44, 8, 31, 'Ir jis tarė: „Kaip aš galiu; nebent kas nors mane pamokytų“. Ir jis prašė Pilypo, kad šis užliptų ir atsisėstų su juo.'),
  (@b44, 8, 32, 'Rašto vieta, kurią jis skaitė, buvo ši: „Jis buvo vedamas kaip avis skerdimui; ir kaip avinėlis, nebylus prieš savo kirpėją, taip jis neatvėrė savo burnos;'),
  (@b44, 8, 33, 'jo nužeminime buvo pašalintas jo teismas; ir kas paskelbs jo giminę? Nes jo gyvybė paimta nuo žemės“.'),
  (@b44, 8, 34, 'Ir Eunuchas atsakydamas Pilypui tarė: „Meldžiu tave, apie ką pranašas tai kalba? Apie save ar apie ką kitą?“'),
  (@b44, 8, 35, 'Tada Pilypas atvėręs savo burną pradėjo nuo to paties Rašto ir paskelbė jam Jėzų.'),
  (@b44, 8, 36, 'Ir jiems bekeliaujant keliu, jie atvyko prie kažkokio vandens, ir eunuchas tarė: „Žiūrėk, vanduo; kas man trukdo būti pakrikštytam?“'),
  (@b44, 8, 37, 'Ir Pilypas tarė: „Jei tiki visa širdimi, gali“. Ir jis atsakydamas tarė: „Tikiu, kad Jėzus Kristus yra Dievo Sūnus“.'),
  (@b44, 8, 38, 'Ir jis įsakė vežimui sustoti, ir jie abu, Pilypas ir eunuchas, nusileido į vandenį; ir jis pakrikštijo jį.'),
  (@b44, 8, 39, 'Ir jiems išlipus iš vandens, Viešpaties Dvasia pagavo Pilypą, kad eunuchas daugiau jo nebematė; ir jis patraukė savo keliu džiaugdamasis.'),
  (@b44, 8, 40, 'Bet Pilypas buvo rastas Azote ir praeidamas skelbė visuose miestuose, kol atėjo į Cezarėją.'),
  (@b44, 9, 1, 'O Saulius, vis tebealsuodamas grasinimais ir žudynėmis prieš Viešpaties mokinius, nuėjo pas aukščiausiąjį kunigą'),
  (@b44, 9, 2, 'ir jo prašė laiškų į Damaską, į sinagogas, kad radęs ką iš to kelio, ar tai vyrus, ar moteris, jis galėtų atvesti juos surištus į Jeruzalę.'),
  (@b44, 9, 3, 'Ir bekeliaudamas jis priartėjo prie Damasko; ir staiga jį apšvietė šviesa iš dangaus,'),
  (@b44, 9, 4, 'ir jis nukrito ant žemės ir išgirdo balsą, sakantį jam: „Sauliau, Sauliau, kodėl mane persekioji?“'),
  (@b44, 9, 5, 'Ir jis tarė: „Kas tu esi, Viešpatie?“ O Viešpats tarė: „Aš esu Jėzus, kurį tu persekioji; sunku tau spyriotis prieš dyglius“.'),
  (@b44, 9, 6, 'Ir jis drebėdamas bei apstulbęs tarė: „Viešpatie, ką nori, kad padaryčiau?“ Ir Viešpats jam tarė: „Kelkis ir eik į miestą, ir tau bus pasakyta, ką turi daryti“.'),
  (@b44, 9, 7, 'O vyrai, kurie su juo keliavo, stovėjo nebylūs, girdėdami balsą, bet nieko nematydami.'),
  (@b44, 9, 8, 'Ir Saulius atsikėlė nuo žemės; ir atmerkęs akis nieko nematė, bet jie vedė jį už rankos ir atvedė į Damaską.'),
  (@b44, 9, 9, 'Ir tris dienas jis buvo neregintis ir nei valgė, nei gėrė.'),
  (@b44, 9, 10, 'O Damaske buvo vienas mokinys, vardu Ananijas; ir jam regėjime Viešpats tarė: „Ananijau!“ Ir jis tarė: „Štai aš čia, Viešpatie“.'),
  (@b44, 9, 11, 'Ir Viešpats jam tarė: „Kelkis ir eik į gatvę, vadinamą Tiesiąja, ir Judo namuose teiraukis vieno, vadinamo Sauliumi iš Tarso, nes štai jis meldžiasi'),
  (@b44, 9, 12, 'ir regėjime matė vyrą, vardu Ananijas, įeinantį ir uždedantį ant jo savo ranką, kad jis atgautų regėjimą“.'),
  (@b44, 9, 13, 'Tada Ananijas atsakė: „Viešpatie, iš daugelio girdėjau apie šitą vyrą, kiek daug pikto jis padarė tavo šventiesiems Jeruzalėje;'),
  (@b44, 9, 14, 'ir čia jis turi įgaliojimą iš vyriausiųjų kunigų surišti visus, kurie šaukiasi tavo vardo“.'),
  (@b44, 9, 15, 'Bet Viešpats jam tarė: „Eik, nes jis yra išrinktasis indas man, kad neštų mano vardą pagonių, karalių ir Izraelio vaikų akivaizdoje,'),
  (@b44, 9, 16, 'nes jam parodysiu, kokius didžius dalykus jis turės kentėti dėl mano vardo“.'),
  (@b44, 9, 17, 'Ir Ananijas nuėjo ir įėjo į namus; ir uždėdamas ant jo savo rankas, tarė: „Broli Sauliau, Viešpats – Jėzus, pasirodęs kelyje tau ateinant, siuntė mane, kad atgautum regėjimą ir būtum pripildytas Šventosios Dvasios“.'),
  (@b44, 9, 18, 'Ir tuojau nuo jo akių nukrito tarsi žvynai; ir jis kaipmat praregėjo, kėlėsi ir buvo pakrikštytas.'),
  (@b44, 9, 19, 'Ir gavęs valgio jis sustiprėjo. Paskui kiek tai dienų Saulius buvo su mokiniais, esančiais Damaske.'),
  (@b44, 9, 20, 'Ir tuojau jis skelbė sinagogose Kristų, kad jis yra Dievo Sūnus.'),
  (@b44, 9, 21, 'Bet visi, kurie jį girdėjo, stebėjosi ir tarė: „Ar jis ne tas, kuris naikino tuos, kurie Jeruzalėje šaukėsi šio vardo, ir čia atėjo tam, kad juos surištus vestų pas vyriausiuosius kunigus?“'),
  (@b44, 9, 22, 'Bet Saulius vis labiau stiprėjo ir kėlė sąmyšį žydams, gyvenantiems Damaske, įrodydamas, kad šitas yra tas Kristus“.'),
  (@b44, 9, 23, 'Ir po to, kai išsipildė daug dienų, žydai tarėsi jį nužudyti,'),
  (@b44, 9, 24, 'bet jų tykojimas buvo Sauliui žinomas. Ir jie saugojo vartus dieną ir naktį, kad jį nužudytų.'),
  (@b44, 9, 25, 'Tada mokiniai paėmė jį naktį ir nuleido žemyn per sieną pintinėje.'),
  (@b44, 9, 26, 'O atėjęs į Jeruzalę Saulius bandė prisijungti prie mokinių, bet jie visi jo bijojo ir netikėjo, kad jis buvo mokinys.'),
  (@b44, 9, 27, 'Bet Barnabas paėmė jį ir atvedė pas apaštalus bei papasakojo jiems, kaip jis kelyje matė Viešpatį ir kad jis kalbėjo su juo, ir kaip jis Damaske drąsiai skelbė Jėzaus vardu.'),
  (@b44, 9, 28, 'Ir jis buvo su jais įeidamas ir išeidamas Jeruzalėje.'),
  (@b44, 9, 29, 'Ir jis drąsiai kalbėjo Viešpaties Jėzaus vardu ir ginčijosi su graikiškais, bet jie ketino jį užmušti.'),
  (@b44, 9, 30, 'Tai sužinoję broliai nugabeno jį žemyn į Cezarėją ir išsiuntė jį į Tarsą.'),
  (@b44, 9, 31, 'Tada bažnyčios po visą Judėją, Galilėją ir Samariją ilsėjosi ir statydinosi; ir dauginosi vaikščiodamos Viešpaties baimėje bei Šventosios Dvasios paguodoje.'),
  (@b44, 9, 32, 'Ir įvyko, kai Petras ėjo per visas vietas, jis atėjo žemyn ir pas šventuosius, kurie gyveno Lydoje.'),
  (@b44, 9, 33, 'Ir ten jis užtiko vieną žmogų, vardu Enėjas, kuris laikėsi savo patale aštuonis metus ir sirgo paralyžiumi.'),
  (@b44, 9, 34, 'Ir Petras jam tarė: „Enėjau, Jėzus Kristus išgydo tave: kelkis ir pasiklok patalą“. Ir jis tuojau atsikėlė.'),
  (@b44, 9, 35, 'Ir visi, kurie gyveno Lydoje bei Sarone, pamatė jį ir atsigręžė į Viešpatį.'),
  (@b44, 9, 36, 'Na, o Jopėje buvo viena mokinė, vardu Tabita, kas išvertus vadinama Dorka; ši moteris buvo pilna gerų darbų ir išmaldos darbų, kuriuos ji darė.'),
  (@b44, 9, 37, 'Ir įvyko tomis dienomis, kad ji susirgo ir mirė; nuplovę ją jie paguldė į aukštutinį kambarį.'),
  (@b44, 9, 38, 'Ir kadangi Lyda buvo arti Jopės, mokiniai išgirdę, kad ten buvo Petras, pasiuntė pas jį du vyrus, prašydami, kad jis nedelsdamas ateitų pas juos.'),
  (@b44, 9, 39, 'Tada Petras pakilo ir nuėjo su jais. Kai jis atėjo, jie atvedė jį į aukštutinį kambarį; ir visos našlės sustojo prie jo verkdamos ir rodydamos marškinius bei rūbus, kuriuos padarė Dorka, kol dar buvo su jomis.'),
  (@b44, 9, 40, 'Bet Petras jas visas išvarė ir atsiklaupė bei meldėsi; ir atsisukęs į kūną tarė: „Tabita, kelkis“. Ir ji atmerkė savo akis ir pamačiusi Petrą atsisėdo.'),
  (@b44, 9, 41, 'Ir jis padavė jai savo ranką ir ją pakėlė, ir pakvietęs šventuosius bei našles pristatė ją gyvą.'),
  (@b44, 9, 42, 'Ir tai buvo žinoma visoje Jopėje; ir daugelis įtikėjo į Viešpatį.'),
  (@b44, 9, 43, 'Ir įvyko, kad jis daug dienų pasiliko Jopėje pas vieną Simoną, kailiadirbį.'),
  (@b44, 10, 1, 'Cezarėjoje buvo vienas vyras, vardu Kornelijus, šimtininkas pulko, vadinamo italų,'),
  (@b44, 10, 2, 'pamaldus vyras ir Dievo bijantis su visais savo namais, kuris davė daug išmaldų tautai ir visuomet meldėsi Dievui.'),
  (@b44, 10, 3, 'Apie devintą valandą dienos jis regėjime aiškiai matė pas jį įeinantį Dievo angelą ir jam sakantį: „Kornelijau!“'),
  (@b44, 10, 4, 'Ir į jį pasižiūrėjęs jis išsigando ir tarė: „Kas yra, Viešpatie?“ Ir jis tarė jam: „Tavo maldos ir tavo išmaldos pakilo Dievo akivaizdon prisiminimui.'),
  (@b44, 10, 5, 'Ir dabar pasiųsk vyrus į Jopę ir pakviesk tokį Simoną, pravarde Petras;'),
  (@b44, 10, 6, 'jis apsistojęs pas tokį Simoną kailiadirbį, kurio namai yra pajūryje – jis tau pasakys, ką turi daryti“.'),
  (@b44, 10, 7, 'Ir kai angelas, kuris kalbėjo Kornelijui, buvo išėjęs, jis pašaukė du savo namų tarnus ir dievobaimingą kareivį iš tų, kurie nuolat jam patarnavo;'),
  (@b44, 10, 8, 'ir paskelbęs jiems visa tai, jis pasiuntė juos į Jopę.'),
  (@b44, 10, 9, 'Rytojaus dieną, jiems keliaujant ir artėjant prie miesto, apie šeštą valandą Petras užlipo ant namo stogo melstis;'),
  (@b44, 10, 10, 'ir jis labai išalko ir norėjo valgyti, bet kol jie ruošė, jis pateko į transą'),
  (@b44, 10, 11, 'ir pamatė atsivėrusį dangų bei kažkokį indą, nusileidžiantį pas jį, tarsi didelę drobulę, pririštą už keturių kampų ir nuleidžiamą ant žemės,'),
  (@b44, 10, 12, 'kuriame buvo visokiausių keturkojų žemės gyvulių, laukinių žvėrių, ropojančių būtybių ir oro skrajūnų.'),
  (@b44, 10, 13, 'Ir jam atėjo balsas: „Kelkis, Petrai; užmušk ir valgyk“.'),
  (@b44, 10, 14, 'Bet Petras tarė: „Ne, Viešpatie; nes niekada nevalgiau nieko prasto ar nešvaraus“.'),
  (@b44, 10, 15, 'Ir jam antrą kartą vėl kalbėjo balsas: „Ką Dievas apvalė, tu nevadink prastu“.'),
  (@b44, 10, 16, 'Tai buvo padaryta triskart; ir indas buvo vėl paimtas į dangų.'),
  (@b44, 10, 17, 'Na, o kol Petras abejojo savyje, ką šis jo matytas regėjimas turėtų reikšti, štai vyrai, kurie buvo pasiųsti nuo Kornelijaus, išsiklausinėjo apie Simono namus ir stovėjo prie vartų,'),
  (@b44, 10, 18, 'ir pašaukę paklausė, ar Simonas, kuris pramintas Petru, ten apsistojęs.'),
  (@b44, 10, 19, 'Kol Petras tebemąstė apie tą regėjimą, Dvasia jam tarė: „Štai trys vyrai tavęs ieško.'),
  (@b44, 10, 20, 'Todėl kelkis, nusileisk ir eik su jais nei kiek neabejodamas, nes aš juos siunčiau“.'),
  (@b44, 10, 21, 'Tada Petras nusileido pas vyrus, kurie buvo jam siųsti nuo Kornelijaus, ir tarė: „Štai aš esu tas, kurio ieškote; dėl kokios priežasties atėjote?“'),
  (@b44, 10, 22, 'Ir jie tarė: „Šimtininkas Kornelijus, teisingas vyras ir bijantis Dievo, ir turintis gerą atsiliepimą visos žydų tautos tarpe, buvo perspėtas iš Dievo per šventąjį angelą, kad pasiųstų pakviesti tave į savo namus ir išklausytų tavo žodžių“.'),
  (@b44, 10, 23, 'Tada jis juos pakvietė vidun ir priglaudė. O rytojaus dieną Petras išėjo su jais, ir jį lydėjo kai kurie broliai iš Jopės.'),
  (@b44, 10, 24, 'O sekančią dieną jie įėjo į Cezarėją. Ir Kornelijus jų laukė, ir buvo susikvietęs savo gimines bei artimus draugus.'),
  (@b44, 10, 25, 'Ir Petrui įeinant Kornelijus jį pasitiko, parpuolė prie jo kojų ir jį pagarbino.'),
  (@b44, 10, 26, 'Bet Petras jį pakėlė, sakydamas: „Stokis; aš taip pat esu žmogus“.'),
  (@b44, 10, 27, 'Ir su juo kalbėdamas jis įėjo ir rado daug susirinkusių.'),
  (@b44, 10, 28, 'Ir jis tarė jiems: „Jūs žinote, kad žmogui, kuris yra žydas, neteisėta bendrauti arba ateiti pas kitatautį; bet Dievas man parodė, kad jokio žmogaus nevadinčiau prastu ar nešvariu.'),
  (@b44, 10, 29, 'Todėl, kai tik buvau pasiųstas, atėjau pas jus be prieštaravimų; todėl klausiu, kokiu tikslu pasiuntėte manęs pakviesti?“'),
  (@b44, 10, 30, 'Ir Kornelijus tarė: „Prieš keturias dienas pasninkavau iki šios valandos; o devintą valandą meldžiausi savo namuose, ir štai prieš mane atsistojo vyras skaisčiais drabužiais'),
  (@b44, 10, 31, 'ir tarė: ‘Kornelijau, tavo malda išgirsta ir tavo išmaldos prisimintos Dievo akyse.'),
  (@b44, 10, 32, 'Todėl pasiųsk į Jopę ir pasikviesk čia Simoną, kurio pravardė Petras; jis prisiglaudęs tokio Simono kailiadirbio namuose pajūryje; atėjęs jis tau kalbės’.'),
  (@b44, 10, 33, 'Todėl tuojau pasiunčiau pas tave; ir tu gerai padarei, kad atėjai. Todėl dabar čia visi esame Dievo akivaizdoje, kad išgirstume viską, kas tau yra Dievo įsakyta“.'),
  (@b44, 10, 34, 'Tada Petras atvėrė savo burną ir tarė: „Iš tiesų matau, kad Dievas neatsižvelgia į asmenis,'),
  (@b44, 10, 35, 'bet kiekvienoje tautoje tas, kuris jo bijo ir daro teisumą, yra jam priimtinas.'),
  (@b44, 10, 36, 'Žodį, kurį Dievas siuntė Izraelio vaikams, skelbdamas taiką per Jėzų Kristų (jis yra visų Viešpats),'),
  (@b44, 10, 37, 'tą žodį, sakau, jūs žinote; kuris buvo paskelbtas po visą Judėją ir prasidėjo nuo Galilėjos po krikšto, kurį skelbė Jonas;'),
  (@b44, 10, 38, 'kaip Dievas patepė Šventąja Dvasia ir jėga Jėzų iš Nazareto, kuris ėjo aplinkui darydamas gera ir gydydamas visus, kurie buvo velnio engiami; nes Dievas buvo su juo.'),
  (@b44, 10, 39, 'Ir mes esame liudytojai visko, ką jis padarė žydų šalyje ir Jeruzalėje; kurį jie nužudė ir pakabino ant medžio;'),
  (@b44, 10, 40, 'jį Dievas prikėlė trečią dieną ir atvirai jį apreiškė;'),
  (@b44, 10, 41, 'ne visai tautai, bet liudytojams, Dievo anksčiau išrinktiems – mums, kurie valgėme ir gėrėme su juo po to, kai jis prisikėlė iš numirusiųjų.'),
  (@b44, 10, 42, 'Ir jis įsakė mums skelbti tautai bei liudyti, kad tai jis, kuris yra Dievo paskirtas būti gyvųjų ir mirusiųjų Teisėju.'),
  (@b44, 10, 43, 'Jį liudija visi pranašai, kad per jo vardą kiekvienas, kuris į jį tiki, gaus nuodėmių atleidimą“.'),
  (@b44, 10, 44, 'Kol Petras dar kalbėjo tuos žodžius, Šventoji Dvasia nupuolė ant visų tų, kurie klausėsi žodžio.'),
  (@b44, 10, 45, 'Ir tie iš apipjaustymo, kurie tikėjo, kurie atėjo su Petru, buvo apstulbinti, kadangi ant pagonių irgi buvo išlieta Šventosios Dvasios dovana.'),
  (@b44, 10, 46, 'Nes jie girdėjo juos kalbant kalbomis ir aukštinant Dievą. Tada Petras atsakė:'),
  (@b44, 10, 47, '„Argi gali kas uždrausti vandenį, kad nebūtų pakrikštyti tie, kurie gavo Šventąją Dvasią kaip ir mes?“'),
  (@b44, 10, 48, 'Ir jis įsakė jiems, kad būtų pakrikštyti Viešpaties vardu. Tada jie maldavo jį pasilikti keletą dienų.'),
  (@b44, 11, 1, 'Ir apaštalai bei broliai, kurie buvo Judėjoje, išgirdo, kad ir pagonys priėmė Dievo žodį.'),
  (@b44, 11, 2, 'Ir kai Petras atėjo aukštyn į Jeruzalę, tie, kurie buvo iš apipjaustymo, ginčijosi su juo,'),
  (@b44, 11, 3, 'sakydami: „Tu nuėjai pas neapipjaustytus vyrus ir su jais valgei“.'),
  (@b44, 11, 4, 'Bet Petras atpasakojo tą reikalą nuo pradžios ir išdėstė jiems jį paeiliui, sakydamas:'),
  (@b44, 11, 5, '„Aš buvau Jopės mieste besimeldžiantis ir transe mačiau regėjimą: nusileido kažkoks indas, tarsi didelė drobulė, nuleidžiama iš dangaus už keturių kampų; ir tas atėjo pas mane,'),
  (@b44, 11, 6, 'į kurį įbedęs akis atidžiai įsižiūrėjau ir pamačiau keturkojus žemės gyvulius, laukinius žvėris, ropojančias būtybes ir oro skrajūnus.'),
  (@b44, 11, 7, 'Ir išgirdau balsą, man tariantį: ‘Kelkis, Petrai; užmušk ir valgyk’.'),
  (@b44, 11, 8, 'Bet aš pasakiau: ‘Ne jau, Viešpatie; nes nieko prasto ar nešvaraus niekada neįėjo į mano burną’.'),
  (@b44, 11, 9, 'Bet balsas man vėl iš dangaus atsakė: ‘Ką Dievas apvalė, tu nevadink prastu’.'),
  (@b44, 11, 10, 'Ir tai atsitiko tris kartus; ir viskas buvo vėl užtraukta į dangų.'),
  (@b44, 11, 11, 'Ir štai prie namų, kuriuose buvau, tuojau atėjo trys vyrai, pasiųsti pas mane iš Cezarėjos.'),
  (@b44, 11, 12, 'Ir Dvasia liepė man eiti su jais nei kiek neabejojant. Be to, šitie šeši broliai mane lydėjo, ir mes įėjome į to vyro namus;'),
  (@b44, 11, 13, 'ir jis mums apsakė, kaip savo namuose matė angelą, kuris stovėjo ir jam tarė: ‘Pasiųsk į Jopę vyrus ir pakviesk Simoną, pravarde Petras;'),
  (@b44, 11, 14, 'kuris pasakys tau žodžius, kuriais tu ir visi tavo namai būsite išgelbėti’.'),
  (@b44, 11, 15, 'Ir man pradėjus kalbėti, Šventoji Dvasia nupuolė ant jų, kaip ir ant mūsų pradžioje.'),
  (@b44, 11, 16, 'Tada prisiminiau Viešpaties žodį, kaip jis sakė: ‘Jonas iš tikrųjų krikštijo vandeniu; bet jūs būsite pakrikštyti Šventąja Dvasia’.'),
  (@b44, 11, 17, 'Jei tad Dievas davė jiems tokią pačią dovaną kaip mums, kurie įtikėjome į Viešpatį Jėzų Kristų, kas aš esu, kad galėčiau priešintis Dievui?“'),
  (@b44, 11, 18, 'Kai jie tai išgirdo, nusiramino ir šlovino Dievą, sakydami: „Tad ir pagonims Dievas davė atgailą gyvenimui“.'),
  (@b44, 11, 19, 'Na, o tie, kurie buvo išsisklaidę dėl persekiojimo, kilusio dėl Stepono, keliavo iki Finikijos ir Kipro, ir Antiocho, skelbdami žodį niekam kitam, o vien tik žydams.'),
  (@b44, 11, 20, 'Ir vieni iš jų buvo vyrai iš Kipro ir Kirenės, kurie, atėję į Antiochą, kalbėjo graikiškiems, skelbdami Viešpatį Jėzų.'),
  (@b44, 11, 21, 'Ir su jais buvo Viešpaties ranka; ir didelis skaičius įtikėjo bei atsigręžė į Viešpatį.'),
  (@b44, 11, 22, 'Tada žinia apie tai atėjo iki Jeruzalėje esančios bažnyčios ausų, ir jie išsiuntė Barnabą, kad jis eitų iki Antiocho.'),
  (@b44, 11, 23, 'Kuris, atėjęs ir pamatęs Dievo malonę, apsidžiaugė ir ragino juos visus, kad širdies nutarimu jie priliptų prie Viešpaties.'),
  (@b44, 11, 24, 'Nes jis buvo geras vyras ir pilnas Šventosios Dvasios bei tikėjimo, ir daug žmonių buvo pridėta prie Viešpaties.'),
  (@b44, 11, 25, 'Tada Barnabas išėjo į Tarsą ieškoti Sauliaus;'),
  (@b44, 11, 26, 'ir jį suradęs atvedė jį į Antiochą. Ir įvyko, kad visus metus jie susirinkdavo su bažnyčia ir mokė daug žmonių. Ir mokiniai krikščionimis pirmiausiai buvo pavadinti Antioche.'),
  (@b44, 11, 27, 'Ir tomis dienomis iš Jeruzalės į Antiochą atėjo pranašai.'),
  (@b44, 11, 28, 'Ir atsistojo vienas iš jų, vardu Agabas, ir pareiškė per Dvasią, kad visame pasaulyje bus didelis badas, kuris įvyko ciesoriaus Klaudijaus dienomis.'),
  (@b44, 11, 29, 'Tada mokiniai, kiekvienas pagal savo išgales nusprendė nusiųsti paramą broliams, gyvenantiems Judėjoje;'),
  (@b44, 11, 30, 'ką jie ir padarė, ir išsiuntė tai vyresniesiems per Barnabo ir Sauliaus rankas.'),
  (@b44, 12, 1, 'Na, o apie tą laiką karalius Erodas pakėlė rankas neduoti ramybės kai kuriems iš bažnyčios.'),
  (@b44, 12, 2, 'Ir jis kalaviju nužudė Jono brolį Jokūbą.'),
  (@b44, 12, 3, 'Ir matydamas, kad tai patiko žydams, jis tęsė toliau, kad suimtų ir Petrą (tada buvo Neraugintos duonos dienos).'),
  (@b44, 12, 4, 'Ir jį sulaikęs jis pasodino jį į kalėjimą ir padavė saugoti keturiems ketvertams kareivių; norėdamas po Velykų išvesti jį tautai.'),
  (@b44, 12, 5, 'Todėl Petras buvo laikomas kalėjime; bet už jį be perstojo buvo atliekama bažnyčios malda Dievui.'),
  (@b44, 12, 6, 'Ir kai Erodas norėjo jį išvesti, tą pačią naktį Petras miegojo tarp dviejų kareivių, surištas dviem grandinėmis; o sargai prie durų saugojo kalėjimą.'),
  (@b44, 12, 7, 'Ir štai pas jį atėjo Viešpaties angelas, ir kalėjime nušvito šviesa; ir jis sudavė Petrui į šoną bei jį pakėlė, sakydamas: „Greitai kelkis!“ Ir jo grandinės nukrito nuo jo rankų.'),
  (@b44, 12, 8, 'Ir angelas jam tarė: „Susijuosk ir susirišk savo sandalus“. Ir jis taip padarė. Ir jis sako jam: „Užsimesk savo drabužį ir sek paskui mane“.'),
  (@b44, 12, 9, 'Ir jis išėjo ir sekė paskui jį; ir nežinojo, kad tai buvo tikra, kas buvo angelo daroma; bet galvojo, kad jis matė regėjimą.'),
  (@b44, 12, 10, 'Praėję pro pirmą ir antrą sargybą, jie atėjo prie geležinių vartų, vedančių į miestą; kurie jiems patys savaime atsivėrė, ir jie išėjo ir praėjo pro vieną gatvę; ir angelas tuoj pat nuo jo nuėjo.'),
  (@b44, 12, 11, 'Ir kai Petras atsipeikėjo, jis tarė: „Dabar tikrai žinau, kad Viešpats siuntė savo angelą ir išvadavo mane iš Erodo rankos ir iš viso to, ko tikėjosi žydų tauta“.'),
  (@b44, 12, 12, 'Ir tai apsvarstęs jis atėjo prie namų Marijos, motinos Jono, pravarde Morkus; kur daugelis susirinkę meldėsi.'),
  (@b44, 12, 13, 'Ir kai Petras beldėsi į vartų duris, atėjo panelė, vardu Roda, paklausyti.'),
  (@b44, 12, 14, 'Ir pažinusi Petro balsą ji iš džiaugsmo neatidarė vartų, bet įbėgo ir papasakojo, kad Petras stovįs priešais vartus.'),
  (@b44, 12, 15, 'O jie tarė jai: „Tu pamišusi“. Bet ji be perstojo tvirtino, kad tai buvo taip. Tada jie tarė: „Tai – jo angelas“.'),
  (@b44, 12, 16, 'Bet Petras toliau beldėsi; ir atidarę duris bei jį pamatę jie apstulbo.'),
  (@b44, 12, 17, 'Bet jis, pamojęs jiems ranka, kad jie tylėtų, papasakojo jiems, kaip Viešpats išvedė jį iš kalėjimo. Ir jis tarė: „Eikite, apsakykite tai Jokūbui ir broliams“. Ir jis išėjo ir nuėjo į kitą vietą.'),
  (@b44, 12, 18, 'Na, o vos tik atėjus dienai, tarp kareivių buvo nemažas sąmyšis, kas gi atsitiko Petrui.'),
  (@b44, 12, 19, 'Ir kai Erodas jo ieškojo ir nerado, jis ištardė sargus ir įsakė, kad jie būtų nužudyti. Ir jis ėjo žemyn iš Judėjos į Cezarėją bei ten pasiliko.'),
  (@b44, 12, 20, 'Ir Erodas buvo labai nepatenkintas tais iš Tyro ir Sidono; bet jie vieningai atėjo pas jį ir, susidraugavę su Blastu, karaliaus rūmininku, prašė taikos; nes jų kraštas buvo maitinamas karaliaus krašto.'),
  (@b44, 12, 21, 'Ir paskirtą dieną Erodas, pasipuošęs karališkais drabužiais, atsisėdo į savo sostą ir sakė jiems kalbą.'),
  (@b44, 12, 22, 'Ir tauta sušuko, sakydama: „Tai – dievo, o ne žmogaus balsas“.'),
  (@b44, 12, 23, 'Ir tuoj pat jam smogė Viešpaties angelas, nes jis nedavė Dievui šlovės; ir jis buvo suėstas kirmėlių ir išleido dvasią.'),
  (@b44, 12, 24, 'Bet Dievo žodis augo ir dauginosi.'),
  (@b44, 12, 25, 'Ir Barnabas bei Saulius, atlikę savo tarnystę, grįžo iš Jeruzalės ir pasiėmė su savimi Joną, pravarde Morkus.'),
  (@b44, 13, 1, 'Na, o bažnyčioje, esančioje Antioche, buvo kai kurie pranašai ir mokytojai, tokie kaip Barnabas ir Simeonas, vadinamas Nigeriu, ir Liucijus iš Kirenės, ir Manaenas, kuris užaugo kartu su tetrarchu Erodu, ir Saulius.'),
  (@b44, 13, 2, 'Kai jie tarnavo Viešpačiui ir pasninkavo, Šventoji Dvasia tarė: „Išskirkite man Barnabą ir Saulių darbui, kuriam juos pašaukiau“.'),
  (@b44, 13, 3, 'Ir kai jie papasninkavo, pasimeldė ir uždėjo ant jų savo rankas, jie juos išsiuntė.'),
  (@b44, 13, 4, 'Taip jie, išsiųsti Šventosios Dvasios, išėjo į Seleukiją; ir iš ten išplaukė į Kiprą.'),
  (@b44, 13, 5, 'Ir būdami Salame, jie skelbė Dievo žodį žydų sinagogose; ir jie taip pat turėjo Joną, kaip savo tarnautoją.'),
  (@b44, 13, 6, 'Ir perėję tą salą iki Pafo jie užtiko vieną burtininką, netikrą pranašą, žydą vardu Bar-Jėzus,'),
  (@b44, 13, 7, 'kuris buvo pas šalies vietininką Sergijų Paulių, protingą vyrą; kuris pasikvietė Barnabą bei Saulių ir norėjo išgirsti Dievo žodį.'),
  (@b44, 13, 8, 'Bet burtininkas Elimas (nes išvertus toks jo vardas) jiems priešinosi, siekdamas nukreipti vietininką nuo tikėjimo.'),
  (@b44, 13, 9, 'Tada Saulius (kurį vadino ir Pauliumi) pripildytas Šventosios Dvasios nukreipė į jį akis'),
  (@b44, 13, 10, 'ir tarė: „Ak tu, pilnas visokio klastingumo ir visokios piktadarystės, velnio vaike, visokio teisumo prieše, ar nesiliausi kraipyti teisingų Viešpaties kelių?'),
  (@b44, 13, 11, 'O dabar štai ant tavęs yra Viešpaties ranka, ir tu būsi aklas, laikotarpiui nematydamas saulės“. Ir tuojau ant jo užkrito migla ir tamsa; ir jis vaikščiojo ieškodamas, kad kas vestų jį už rankos.'),
  (@b44, 13, 12, 'Tada vietininkas, pamatęs, kas atsitiko, įtikėjo, apstulbintas Viešpaties mokslo.'),
  (@b44, 13, 13, 'Na, o kai Paulius ir jo draugija išplaukė iš Pafo, jie atvyko į Pergę Pamfilijoje; o Jonas, nuo jų pasitraukęs, sugrįžo į Jeruzalę.'),
  (@b44, 13, 14, 'Bet pasitraukę iš Pergės jie atvyko į Antiochą Pisidijoje ir sabato dieną nuėjo į sinagogą ir atsisėdo.'),
  (@b44, 13, 15, 'Ir po įstatymo bei pranašų skaitymo sinagogos valdovai pasiuntė pas juos, sakydami: „Vyrai ir broliai, jei turite kokį paskatinimo žodį tautai, tarkite“.'),
  (@b44, 13, 16, 'Tada atsistojo Paulius ir pamojęs ranka tarė: „Izraelio vyrai ir jūs, kurie bijote Dievo, išklausykite.'),
  (@b44, 13, 17, 'Šios Izraelio tautos Dievas išsirinko mūsų tėvus ir išaukštino tautą, kai jie gyveno kaip ateiviai Egipto šalyje, ir aukšta ranka juos išvedė iš jos.'),
  (@b44, 13, 18, 'Ir apie keturiasdešimties metų laikotarpį jis kentė jų būdą dykumoje.'),
  (@b44, 13, 19, 'Ir Kanaano šalyje sunaikinęs septynias tautas jis burtu jiems padalino jų šalį.'),
  (@b44, 13, 20, 'Ir po to jis apie keturis šimtus penkiasdešimt metų davė jiems teisėjus iki pranašo Samuelio.'),
  (@b44, 13, 21, 'Ir po to jie prašė karaliaus; ir Dievas davė jiems Saulių, Kišo sūnų, vyrą iš Benjamino genties, keturiasdešimčiai metų.'),
  (@b44, 13, 22, 'Ir jį pašalinęs jis prikėlė jiems Dovydą būti jų karaliumi; kuriam jis ir paliudijo tardamas: ‘Radau Dovydą, Jesės sūnų, vyrą pagal mano širdį, kuris įvykdys visą mano valią’.'),
  (@b44, 13, 23, 'Iš šio vyro sėklos Dievas pagal savo pažadą prikėlė Izraeliui Gelbėtoją, Jėzų;'),
  (@b44, 13, 24, 'kai Jonas prieš jo atėjimą pirmiau paskelbė atgailos krikštą visai Izraelio tautai.'),
  (@b44, 13, 25, 'Ir kai Jonas išpildė savo bėgimą, jis tarė: ‘Kuo jūs galvojate mane esant? Aš nesu tas. Bet štai ateina vienas po manęs, kurio kojų apavo nesu vertas atrišti’.'),
  (@b44, 13, 26, 'Vyrai ir broliai, Abraomo giminės vaikai ir tarp jūsų besibijantys Dievo, jums yra pasiųstas šio išgelbėjimo žodis.'),
  (@b44, 13, 27, 'Nes gyvenantys Jeruzalėje ir jų valdovai, nepažinę jo ir balso pranašų, kurie yra skaitomi kiekvieną sabato dieną, juos jie išpildė jį pasmerkdami.'),
  (@b44, 13, 28, 'Ir nors jie nerado jame pagrindo mirčiai, tačiau prašė Piloto, kad jis būtų nužudytas.'),
  (@b44, 13, 29, 'Ir išpildę viską, kas apie jį buvo parašyta, jie nuėmė jį nuo medžio ir paguldė į kapą.'),
  (@b44, 13, 30, 'Bet Dievas prikėlė jį iš numirusiųjų,'),
  (@b44, 13, 31, 'ir per daugelį dienų jis buvo regėtas tų, kurie su juo atėjo iš Galilėjos aukštyn į Jeruzalę, kurie yra jo liudytojai tautai.'),
  (@b44, 13, 32, 'Ir mes skelbiame jums džiugią žinią, kad pažadą, duotą tėvams,'),
  (@b44, 13, 33, 'Dievas išpildė mums, jų vaikams, prikeldamas Jėzų; kaip yra parašyta ir antroje psalmėje: ‘Tu esi mano Sūnus, šią dieną aš tave pagimdžiau’.'),
  (@b44, 13, 34, 'Ir apie tai, kad jis prikėlė jį iš numirusiųjų, daugiau nebegrįšiantį į supuvimą, jis tarė taip: ‘Aš duosiu jums tikrus Dovydo gailestingumus’.'),
  (@b44, 13, 35, 'Todėl jis sako ir kitoje psalmėje: ‘Tu neleisi savo Šventajam matyti supuvimo’.'),
  (@b44, 13, 36, 'Nes Dovydas, atitarnavęs savajai kartai pagal Dievo valią, užmigo ir buvo paguldytas pas savo tėvus, ir matė supuvimą;'),
  (@b44, 13, 37, 'bet tas, kurį Dievas prikėlė, nematė supuvimo.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b44, 13, 38, 'Todėl tebūna jums žinoma, vyrai ir broliai, kad per šitą vyrą jums yra skelbiamas nuodėmių atleidimas;'),
  (@b44, 13, 39, 'ir visi, kurie tiki, yra per jį išteisinami nuo visko, nuo ko negalėjote būti išteisinti Mozės įstatymu.'),
  (@b44, 13, 40, 'Todėl saugokitės, kad ant jūsų neateitų tai, kas yra pasakyta pranašuose:'),
  (@b44, 13, 41, '‘Žiūrėkite, niekintojai, stebėkitės ir pražūkite, nes aš darau darbą jūsų dienomis, darbą, kuriuo jokiu būdu netikėsite, nors jį jums kas ir paskelbtų’.'),
  (@b44, 13, 42, 'Ir kai žydai buvo išėję iš sinagogos, pagonys maldavo, kad šitie žodžiai būtų jiems paskelbti ateinantį sabatą.'),
  (@b44, 13, 43, 'Na, o kai susirinkimas išsiskirstė, daugelis iš žydų ir religingų prozelitų sekė paskui Paulių ir Barnabą, kurie, kalbėdami jiems, įtikinėjo juos pasilikti Dievo malonėje.'),
  (@b44, 13, 44, 'Ir kitą sabatą susirinko beveik visas miestas pasiklausyti Dievo žodžio.'),
  (@b44, 13, 45, 'Bet žydai pamatę minias prisipildė pavydo ir priešgyniaudami bei piktžodžiaudami kalbėjo priešingai tam, kas buvo kalbama Pauliaus.'),
  (@b44, 13, 46, 'Tada Paulius ir Barnabas įsidrąsino ir tarė: „Buvo būtina, kad Dievo žodis pirmiau turėjo būti kalbamas jums; bet kadangi jį atmetate nuo savęs ir nuteisiate save kaip nevertus amžinojo gyvenimo, štai mes sukame pas pagonis.'),
  (@b44, 13, 47, 'Nes taip mums įsakė Viešpats, sakydamas: „Aš pastačiau tave būti pagonių šviesa, kad būtumei išgelbėjimui iki žemės pakraščių“.'),
  (@b44, 13, 48, 'O pagonys tai išgirdę apsidžiaugė ir šlovino Viešpaties žodį; ir visi, kurie buvo paskirti amžinajam gyvenimui, įtikėjo.'),
  (@b44, 13, 49, 'Ir Viešpaties žodis išplito po visą kraštą.'),
  (@b44, 13, 50, 'Bet žydai sukurstė dievobaimingas ir gerbiamas moteris bei miesto vyriausiuosius ir sukėlė Pauliaus bei Barnabo persekiojimą, ir išvarė juos iš savo ribų.'),
  (@b44, 13, 51, 'Bet jie nusipurtė prieš juos dulkes nuo savo kojų ir atėjo į Ikonijų.'),
  (@b44, 13, 52, 'Ir mokiniai buvo pripildyti džiaugsmo bei Šventosios Dvasios.'),
  (@b44, 14, 1, 'Ir įvyko Ikonijuje, kad jie kartu nuėjo į žydų sinagogą ir taip kalbėjo, jog įtikėjo didelė minia ir žydų, ir taip pat graikų.'),
  (@b44, 14, 2, 'Bet netikintys žydai sukurstė pagonis ir supykdė jų širdis prieš brolius.'),
  (@b44, 14, 3, 'Taigi jie ten laikėsi ilgą laiką, drąsiai kalbėdami Viešpatyje, kuris liudijo savo malonės žodį ir davė ženklų bei stebuklų, kad būtų padaryti jų rankomis.'),
  (@b44, 14, 4, 'Bet miesto minia buvo pasidalijusi: dalis palaikė žydus, o dalis apaštalus.'),
  (@b44, 14, 5, 'Ir kai pagonys bei žydai su savo valdovais kėsinosi juos išniekinti ir užmėtyti akmenimis,'),
  (@b44, 14, 6, 'jie tai žinojo ir pabėgo į Likaonijos miestus Listrą ir Derbę bei į aplinkui esantį kraštą,'),
  (@b44, 14, 7, 'ir ten skelbė evangeliją.'),
  (@b44, 14, 8, 'Ir Listroje sėdėjo vienas vyras bejėgėmis kojomis, būdamas luošys nuo savo motinos įsčių, kuris niekada nebuvo vaikščiojęs;'),
  (@b44, 14, 9, 'jis girdėjo kalbant Paulių, kuris įdėmiai žiūrėdamas į jį ir pastebėjęs, kad jis turi tikėjimą būti išgydytas,'),
  (@b44, 14, 10, 'garsiu balsu tarė: „Stokis tiesiai ant savo kojų!“ Ir jis pašoko ir vaikščiojo.'),
  (@b44, 14, 11, 'Ir liaudis pamačiusi, ką Paulius padarė, pakėlė savo balsus, sakydami likaoniečių kalba: „Dievai žmonių pavidalu nužengė pas mus“.'),
  (@b44, 14, 12, 'Ir jie pavadino Barnabą Jupiteriu; o Paulių Merkurijumi, nes jis buvo pagrindinis kalbėtojas.'),
  (@b44, 14, 13, 'Tuomet kunigas Jupiterio, kuris buvo priešais jų miestą, atgabeno prie vartų jaučių bei vainikų ir su liaudimi norėjo atlikti auką.'),
  (@b44, 14, 14, 'Išgirdę apie tai, apaštalai Barnabas ir Paulius persiplėšė drabužius ir nubėgo į vidurį liaudies šaukdami'),
  (@b44, 14, 15, 'ir sakydami: „Ponai, kodėl tai darote? Mes irgi esame tokių pat aistrų žmonės, kaip ir jūs, ir jums skelbiame, kad nusigręžtumėte nuo šitų tuštybių į gyvąjį Dievą, kuris padarė dangų, žemę, jūrą ir visa, kas juose;'),
  (@b44, 14, 16, 'kuris praeitais laikais leido visoms tautoms vaikščioti savais keliais.'),
  (@b44, 14, 17, 'Tačiau jis nepaliko savęs nepaliudyto, darydamas gera ir duodamas mums lietų iš dangaus ir vaisingus laikotarpius, pripildydamas mūsų širdis maistu ir džiaugsmu“.'),
  (@b44, 14, 18, 'Ir šitais pasakymais jie vos ne vos sulaikė liaudį, kad šie neatliktų jiems aukos.'),
  (@b44, 14, 19, 'Ir ten atėjo kai kurie žydai iš Antiocho ir Ikonijaus, kurie įkalbėjo liaudį ir, užmėtę Paulių akmenimis, ištempė iš miesto, manydami jį esant mirusiu.'),
  (@b44, 14, 20, 'Tačiau kai mokiniai sustojo aplink jį, jis atsikėlė ir įėjo į miestą; o rytojaus dieną jis su Barnabu išvyko į Derbę.'),
  (@b44, 14, 21, 'Ir paskelbę evangeliją tam miestui bei daugelį išmokę, jie vėl sugrįžo į Listrą, Ikonijų ir Antiochą,'),
  (@b44, 14, 22, 'stiprindami mokinių sielas ir ragindami juos pasilikti tikėjime, ir kad mes per daug suspaudimo turime įeiti į Dievo karalystę.'),
  (@b44, 14, 23, 'Ir paskyrę jiems vyresniuosius kiekvienoje bažnyčioje bei pasimeldę su pasninku, jie patikėjo juos Viešpačiui, į kurį jie tikėjo.'),
  (@b44, 14, 24, 'Ir perėję per visą Pisidiją jie atėjo į Pamfiliją.'),
  (@b44, 14, 25, 'Ir paskelbę žodį Pergėje jie nuėjo žemyn į Ataliją;'),
  (@b44, 14, 26, 'o iš ten išplaukė į Antiochą, iš kur jie buvo patikėti Dievo malonei, darbui, kurį jie įvykdė.'),
  (@b44, 14, 27, 'O atvykę ir surinkę bažnyčią, jie atpasakojo viską, ką Dievas su jais nuveikė ir kaip atvėrė tikėjimo duris pagonims.'),
  (@b44, 14, 28, 'Ir ten jie ilgą laiką laikėsi su mokiniais.'),
  (@b44, 15, 1, 'Ir kai kurie, atėję žemyn iš Judėjos, mokė brolius ir sakė: „Jei nebūsite apipjaustyti pagal Mozės paprotį, negalite būti išgelbėti“.'),
  (@b44, 15, 2, 'Todėl kai Paulius ir Barnabas turėjo su jais nemažai nesutarimų ir ginčų, jie nutarė, kad Paulius ir Barnabas bei kai kurie kiti iš jų dėl šito klausimo turi eiti aukštyn į Jeruzalę pas apaštalus ir vyresniuosius.'),
  (@b44, 15, 3, 'Ir bažnyčios išleisti į kelią, jie ėjo per Finikiją ir Samariją, pasakodami apie pagonių atsivertimą: ir jie sukėlė didelį džiaugsmą visiems broliams.'),
  (@b44, 15, 4, 'Ir atvykę į Jeruzalę jie buvo priimti bažnyčios ir apaštalų bei vyresniųjų, ir jie papasakojo viską, ką Dievas nuveikė su jais.'),
  (@b44, 15, 5, 'Bet kai kurie iš fariziejų sektos, kurie įtikėjo, pakilo sakydami, kad būtina juos apipjaustyti ir įsakyti jiems laikytis Mozės įstatymo.'),
  (@b44, 15, 6, 'Ir susirinko apaštalai ir vyresnieji apsvarstyti šio dalyko.'),
  (@b44, 15, 7, 'Ir kai buvo daug ginčo, pakilo Petras ir jiems tarė: „Vyrai ir broliai, jūs žinote, kaip Dievas prieš gerą laiko tarpą tarp mūsų išsirinko, kad pagonys per mano burną išgirstų evangelijos žodį ir įtikėtų.'),
  (@b44, 15, 8, 'Ir Dievas, kuris pažįsta širdis, jiems paliudijo, duodamas jiems Šventąją Dvasią, lygiai kaip padarė ir mums;'),
  (@b44, 15, 9, 'ir nedarė jokio skirtumo tarp mūsų ir jų, apvalydamas jų širdis tikėjimu.'),
  (@b44, 15, 10, 'Tai kodėl dabar gundote Dievą, dėdami ant mokinių sprando jungą, kurio nei mūsų tėvai, nei mes nepajėgėme panešti?'),
  (@b44, 15, 11, 'Bet tikime, kad per Viešpaties Jėzaus Kristaus malonę mes būsime išgelbėti kaip ir jie“.'),
  (@b44, 15, 12, 'Tada visa minia nutilo bei klausė Barnabo ir Pauliaus pasakojant, kokius stebuklus ir nuostabas per juos tarp pagonių darė Dievas.'),
  (@b44, 15, 13, 'O po to, kai jie nutilo, Jokūbas atsakė, sakydamas: „Vyrai ir broliai, paklausykite manęs:'),
  (@b44, 15, 14, 'Simeonas papasakojo, kaip Dievas pirma aplankė pagonis, kad iš jų pasiimtų savo vardui liaudį.'),
  (@b44, 15, 15, 'Ir su tuo sutinka pranašų žodžiai, kaip yra parašyta:'),
  (@b44, 15, 16, '‘Po to aš sugrįšiu ir atstatysiu Dovydo padangtę, kuri yra nugriuvusi; ir vėl atstatysiu jos griuvėsius ir ją atitiesiu;'),
  (@b44, 15, 17, 'kad ieškotų Viešpaties žmonių likutis ir visi pagonys, ant kurių yra ištartas mano vardas, sako Viešpats, darantis visa tai’.'),
  (@b44, 15, 18, 'Dievui yra žinomi visi jo darbai nuo pasaulio pradžios.'),
  (@b44, 15, 19, 'Todėl mano sprendimas yra, kad nevargintume tų, kurie iš pagonių tarpo yra atsigręžę į Dievą;'),
  (@b44, 15, 20, 'bet kad jiems parašytume, kad jie susilaikytų nuo susiteršimo stabais ir nuo paleistuvystės, ir nuo to, kas pasmaugta, ir nuo kraujo.'),
  (@b44, 15, 21, 'Nes Mozė nuo senų laikų turi kiekviename mieste tų, kurie skelbia jį, skaitydami sinagogose kiekvieną sabato dieną“.'),
  (@b44, 15, 22, 'Tuomet patiko apaštalams ir vyresniesiems su visa bažnyčia pasiųsti iš jų tarpo išrinktus vyrus į Antiochą su Pauliumi ir Barnabu; būtent Judą, pramintą Barsabu, ir Silą, viršiausius vyrus tarp brolių;'),
  (@b44, 15, 23, 'ir per juos jie parašė tokius laiškus: „Apaštalai, vyresnieji ir broliai siunčia sveikinimus broliams, esantiems iš pagonių Antioche, Sirijoje ir Kilikijoje;'),
  (@b44, 15, 24, 'kadangi girdėjome, jog kai kurie išėję iš mūsų trikdė jus žodžiais, apversdami jūsų sielas, sakydami: ‘Jūs turite būti apipjaustyti ir laikytis įstatymo’, kuriems mes nedavėme tokio įsakymo;'),
  (@b44, 15, 25, 'mums, vieningai susirinkusiems, atrodė gerai jums pasiųsti išrinktus vyrus su mūsų mylimaisiais Barnabu ir Pauliumi,'),
  (@b44, 15, 26, 'žmonėmis, kurie rizikavo savo gyvybėmis dėl mūsų Viešpaties Jėzaus Kristaus vardo.'),
  (@b44, 15, 27, 'Todėl pasiuntėme Judą ir Silą, kurie irgi jums papasakos tą patį burna.'),
  (@b44, 15, 28, 'Nes Šventajai Dvasiai ir mums atrodė gerai neuždėti ant jūsų didesnės naštos negu tai, kas būtina;'),
  (@b44, 15, 29, 'kad susilaikytumėte nuo maisto, atnašauto stabams, ir nuo kraujo, ir nuo to, kas pasmaugta, ir nuo paleistuvystės; jei nuo jų susilaikysite, gerai darysite. Būkite sveiki!“'),
  (@b44, 15, 30, 'Taigi išleisti jie atėjo į Antiochą; ir surinkę minią įteikė laišką,'),
  (@b44, 15, 31, 'kurį paskaitę jie džiaugėsi paguoda.'),
  (@b44, 15, 32, 'O Judas ir Silas, patys irgi būdami pranašai, skatino brolius daugeliu žodžių ir juos sustiprino.'),
  (@b44, 15, 33, 'Ir ten prabuvę kurį laiką jie buvo išleisti ramybėje nuo brolių pas apaštalus.'),
  (@b44, 15, 34, 'Tačiau Silui patiko dar ten pasilikti.'),
  (@b44, 15, 35, 'Taip pat Paulius ir Barnabas pasiliko Antioche, mokydami ir skelbdami Viešpaties žodį, taipogi su daugeliu kitų.'),
  (@b44, 15, 36, 'Ir po kiek tai dienų Paulius tarė Barnabui: „Vėl eikime ir aplankykime mūsų brolius kiekviename mieste, kur skelbėme Viešpaties žodį, ir pažiūrėkime, kaip jiems sekasi“.'),
  (@b44, 15, 37, 'O Barnabas nusprendė pasiimti su jais Joną, pravarde Morkus.'),
  (@b44, 15, 38, 'Bet Paulius manė, kad negerai pasiimti su jais tą, kuris iš Pamfilijos nuo jų pasitraukė ir nėjo su jais į darbą.'),
  (@b44, 15, 39, 'Ir nesutarimas tarp jų buvo toks aštrus, kad jie vienas nuo kito atsiskyrė; ir taip Barnabas pasiėmė Morkų ir išplaukė į Kiprą;'),
  (@b44, 15, 40, 'o Paulius pasirinko Silą ir, brolių pavestas Dievo malonei, iškeliavo.'),
  (@b44, 15, 41, 'Ir jis ėjo per Siriją ir Kilikiją, stiprindamas bažnyčias.'),
  (@b44, 16, 1, 'Tuomet jis atėjo į Derbę ir Listrą; ir štai ten buvo vienas mokinys, vardu Timotiejus, sūnus tokios moters, kuri buvo žydė ir tikėjo; bet jo tėvas buvo graikas;'),
  (@b44, 16, 2, 'apie jį buvo gerai atsiliepta brolių, esančių Listroje ir Ikonijuje.'),
  (@b44, 16, 3, 'Paulius norėjo, kad jis išvyktų su juo; ir paėmęs jį apipjaustė dėl žydų, buvusių tose vietose, nes jie visi žinojo, kad jo tėvas buvo graikas.'),
  (@b44, 16, 4, 'Ir eidami per miestus jie perdavė jiems laikytis įsakų, nustatytų apaštalų ir vyresniųjų, esančių Jeruzalėje.'),
  (@b44, 16, 5, 'Ir taip bažnyčios buvo sutvirtintos tikėjime ir kasdien augo skaičiumi.'),
  (@b44, 16, 6, 'Na, o perėję Frigiją ir Galatijos kraštą, ir Šventajai Dvasiai uždraudus jiems skelbti žodį Azijoje,'),
  (@b44, 16, 7, 'po to atėję į Myziją jie bandė eiti į Bitiniją, bet Dvasia jiems neleido.'),
  (@b44, 16, 8, 'Ir jie, praeidami pro Myziją, atėjo žemyn į Troją.'),
  (@b44, 16, 9, 'Ir naktį Pauliui pasirodė regėjimas: stovėjo vyras iš Makedonijos ir meldė jo, sakydamas: „Ateik į Makedoniją ir padėk mums“.'),
  (@b44, 16, 10, 'Ir po to, kai jis pamatė regėjimą, mes tuojau stengėmės vykti į Makedoniją, darydami išvadą, kad Viešpats pašaukė mus skelbti jiems evangeliją.'),
  (@b44, 16, 11, 'Todėl išplaukę iš Trojos tiesiu kursu atvykome į Samotrakiją, o rytojaus dieną – į Neapolį;'),
  (@b44, 16, 12, 'o iš ten į Filipus, kuris yra pagrindinis tos Makedonijos dalies miestas ir kolonija; ir tame mieste pasilikome kiek tai dienų.'),
  (@b44, 16, 13, 'Ir per sabatą išėjome iš miesto prie upės, kur buvo paprotys atlikti maldą; ir atsisėdome bei kalbėjome ten susiėjusioms moterims.'),
  (@b44, 16, 14, 'Ir viena moteris, vardu Lidija, purpuro prekiautoja iš Tiatyrų miesto, kuri garbino Dievą, klausėsi mūsų; Viešpats atvėrė jos širdį, kad ji kreipė dėmesį į tai, ką kalbėjo Paulius.'),
  (@b44, 16, 15, 'Ir kai buvo pakrikštyta ji ir jos namiškiai, ji mūsų maldavo, sakydama: „Jei nusprendėte, kad esu ištikima Viešpačiui, ateikite į mano namus ir ten pasilikite“. Ir ji mus privertė.'),
  (@b44, 16, 16, 'Ir įvyko, kai ėjome į maldą, mus sutiko viena mergina, apsėsta ateities būrimo dvasios, kuri pranašavimu nešė savo valdovams didelį pelną;'),
  (@b44, 16, 17, 'ji sekė paskui Paulių ir mus bei šaukė, sakydama: „Šitie vyrai yra aukščiausiojo Dievo tarnai, kurie skelbia mums išgelbėjimo kelią“.'),
  (@b44, 16, 18, 'Ir ji tai darė daug dienų. Bet Paulius, apimtas sielvarto, atsisuko ir tarė dvasiai: „Įsakau tau Jėzaus Kristaus vardu išeiti iš jos“. Ir ji išėjo tą pačią valandą.'),
  (@b44, 16, 19, 'Ir jos valdovai pamatę, kad prapuolė jų pasipelnymo viltis, sučiupo Paulių bei Silą, nutempė į turgavietę pas valdovus'),
  (@b44, 16, 20, 'ir atvedė juos pas valdytojus, sakydami: „Šitie žmonės, būdami žydai, stipriai drumsčia mūsų miestą'),
  (@b44, 16, 21, 'ir moko papročių, kurių neteisėta mums, esant romiečiais, nei priimti, nei laikytis“.'),
  (@b44, 16, 22, 'Ir minia kartu sukilo prieš juos; ir valdytojai persiplėšė drabužius ir įsakė juos primušti.'),
  (@b44, 16, 23, 'Ir sudavę jiems daug kirčių įmetė į kalėjimą, įpareigodami kalėjimo prižiūrėtoją juos užtikrintai saugoti;'),
  (@b44, 16, 24, 'kuris, gavęs tokį įpareigojimą, įmetė juos į vidinį kalėjimą ir jų kojas įtvėrė į trinką.'),
  (@b44, 16, 25, 'Ir vidurnaktį Paulius ir Silas meldėsi bei giedojo gyrių Dievui, o kaliniai juos girdėjo.'),
  (@b44, 16, 26, 'Ir staiga buvo didelis žemės drebėjimas, kad net kalėjimo pamatai drebėjo; ir tuojau atsivėrė visos durys, ir kiekvieno pančiai atsilaisvino.'),
  (@b44, 16, 27, 'O kalėjimo prižiūrėtojas, atsikėlęs iš miego ir pamatęs atviras kalėjimo duris, išsitraukė kalaviją ir norėjo nusižudyti, manydamas, kad kaliniai pabėgę.'),
  (@b44, 16, 28, 'Bet Paulius šaukė garsiu balsu, sakydamas: „Nedaryk sau žalos, nes mes visi esame čia“.'),
  (@b44, 16, 29, 'Tada jis pašaukė šviesos, įšoko ir atėjo drebėdamas, ir parpuolė priešais Paulių ir Silą,'),
  (@b44, 16, 30, 'ir išvedęs juos laukan tarė: „Ponai, ką turiu daryti, kad būčiau išgelbėtas?“'),
  (@b44, 16, 31, 'Ir jie tarė: „Tikėk į Viešpatį Jėzų Kristų, ir būsi išgelbėtas tu bei tavo namai“.'),
  (@b44, 16, 32, 'Ir jie kalbėjo Viešpaties žodį jam ir visiems, buvusiems jo namuose.'),
  (@b44, 16, 33, 'Ir jis paėmė juos tą pačią nakties valandą ir nuplovė jų kirčių žaizdas; ir nedelsiant buvo pakrikštytas jis ir visi jo saviškiai.'),
  (@b44, 16, 34, 'Ir atvedęs juos į savo namus jis padėjo priešais juos maisto ir džiaugėsi, tikėdamas į Dievą su visais savo namais.'),
  (@b44, 16, 35, 'Ir kai buvo diena, valdytojai pasiuntė tarnus, sakydami: „Paleiskite šituos žmones“.'),
  (@b44, 16, 36, 'Ir kalėjimo prižiūrėtojas kalbėjo šitą pasakymą Pauliui: „Valdytojai siuntė jus paleisti, todėl dabar išeikite ir eikite ramybėje“.'),
  (@b44, 16, 37, 'Bet Paulius jiems tarė: „Jie mus, esančius romiečiais, primušė viešai nepasmerktus ir įmetė į kalėjimą; o dabar jie išmeta mus slapčia? Tikrai ne; jie patys teateina ir mus išveda“.'),
  (@b44, 16, 38, 'Ir tarnai pasakė tuos žodžius valdytojams; ir išgirdę, kad šie yra romiečiai, jie išsigando.'),
  (@b44, 16, 39, 'Ir jie atėjo bei maldavo jų ir išvedė juos, ir prašė išeiti iš miesto.'),
  (@b44, 16, 40, 'Ir jie išėjo iš kalėjimo, ir įėjo į Lidijos namus; ir pamatę brolius paguodė juos ir išvyko.'),
  (@b44, 17, 1, 'Na, o perėję Amfipolį ir Apoloniją jie atėjo į Tesaloniką, kur buvo žydų sinagoga;'),
  (@b44, 17, 2, 'ir kaip buvo pratęs, Paulius įėjo pas juos ir tris sabato dienas diskutavo su jais iš Raštų,'),
  (@b44, 17, 3, 'atverdamas ir tvirtindamas, kad Kristui reikėjo kentėti ir prisikelti iš numirusių; ir kad: „Šis Jėzus, kurį jums skelbiu, yra Kristus“.'),
  (@b44, 17, 4, 'Ir kai kurie iš jų įtikėjo ir prisidėjo prie Pauliaus ir Silo; ir didelė minia dievobaimingų graikų, ir nemažai viršiausiųjų moterų.'),
  (@b44, 17, 5, 'Bet žydai, kurie netikėjo, apimti pavydo pasiėmė žemiausios klasės nešvankių vyrų ir surinkę būrį sukėlė visame mieste triukšmą, ir užpuolė Jasono namus, ir siekė išvesti juos pas liaudį.'),
  (@b44, 17, 6, 'Bet jų neradę tempė Jasoną ir kai kuriuos brolius pas miesto valdovus, šaukdami: „Šitie, kurie apvertė pasaulį aukštyn kojomis, ir čia yra atėję;'),
  (@b44, 17, 7, 'kuriuos Jasonas priėmė; ir šitie visi daro priešingai ciesoriaus įsakams sakydami, kad yra kitas karalius, toks Jėzus“.'),
  (@b44, 17, 8, 'Ir jie trikdė liaudį bei miesto valdovus jiems tai girdint.'),
  (@b44, 17, 9, 'Ir paėmę iš Jasono ir kitų garantą, jie paleido juos.'),
  (@b44, 17, 10, 'Ir broliai tuojau išsiuntė Paulių ir Silą nakčia į Berėją; kurie, ten atėję, nuėjo į žydų sinagogą.'),
  (@b44, 17, 11, 'Šitie buvo kilnesni negu tie Tesalonikoje tuo, kad jie priėmė žodį visu noringumu ir kasdien tyrinėjo Raštus, ar taip ir yra.'),
  (@b44, 17, 12, 'Todėl daugelis iš jų įtikėjo; taip pat iš garbingų graikų moterų ir iš vyrų – nemažai.'),
  (@b44, 17, 13, 'Bet kai Tesalonikos žydai sužinojo, kad Dievo žodis buvo Pauliaus skelbiamas Berėjoje, jie ir ten atėjo bei sukurstė liaudį.'),
  (@b44, 17, 14, 'Ir tada broliai tuoj pat išsiuntė Paulių eiti neva iki jūros; bet Silas ir Timotiejus vis dar ten pasiliko.'),
  (@b44, 17, 15, 'Ir tie, kurie lydėjo Paulių, atgabeno jį į Atėnus ir, gavę įsakymą Silui ir Timotiejui kuo greičiau pas jį ateiti, išvyko.'),
  (@b44, 17, 16, 'Na, o kol Paulius laukė jų Atėnuose, jo dvasia jame užsidegė, kai jis pamatė miestą visiškai atiduotą stabmeldystei.'),
  (@b44, 17, 17, 'Todėl jis diskutavo sinagogoje su žydais ir su dievobaimingais asmenimis, ir kas dieną turguje su tais, kurie su juo susitikdavo.'),
  (@b44, 17, 18, 'Tuomet kai kurie epikūrininkų ir stoikų filosofai su juo susirėmė. Ir kai kurie sakė: „Ką šis plepys nori pasakyti?“ Dar kiti: „Jis atrodo esąs svetimų dievų skelbėjas“, nes jis skelbė jiems Jėzų ir prisikėlimą.'),
  (@b44, 17, 19, 'Ir jie paėmė jį ir atvedė į Areopagą, sakydami: „Ar galime sužinoti, kas tai per naujas mokslas, apie kurį tu kalbi?'),
  (@b44, 17, 20, 'Nes tu mūsų ausims pateiki svetimų dalykų; todėl norime sužinoti, ką jie reiškia“'),
  (@b44, 17, 21, '(nes visi atėniečiai ir ten esantys ateiviai neleisdavo laiko niekam kitam, o tik tam, kad pasakotų arba išgirstų ką nors naujo).'),
  (@b44, 17, 22, 'Tada Paulius atsistojo Marso kalvos viduryje ir tarė: „Atėnų vyrai, matau, kad visame kame esate pernelyg prietaringi.'),
  (@b44, 17, 23, 'Nes praeidamas ir matydamas jūsų apeigas radau aukurą su šiuo užrašu: ‘NEŽINOMAM DIEVUI’. Taigi, kurį jūs nežinodami garbinate, tą aš jums skelbiu.'),
  (@b44, 17, 24, 'Dievas, kuris padarė pasaulį ir visa, kas jame, kadangi jis yra dangaus ir žemės Viešpats, negyvena rankomis padarytose šventyklose;'),
  (@b44, 17, 25, 'nei garbinamas žmonių rankomis, tarsi jam ko nors reikia, kadangi jis visiems duoda gyvybę ir kvėpavimą, ir viską;'),
  (@b44, 17, 26, 'ir iš vieno kraujo padarė visas žmonių tautas gyventi ant viso žemės paviršiaus, ir nustatė anksčiau paskirtus laikus ir jų apsigyvenimo vietos ribas;'),
  (@b44, 17, 27, 'kad jie ieškotų Viešpaties, galbūt apčiuoptų jį ir atrastų, nors jis nėra toli nuo kiekvieno iš mūsų;'),
  (@b44, 17, 28, 'nes jame gyvename ir judame, ir turime savo būtį; kaip ir kai kurie iš jūsų pačių poetų yra pasakę: ‘Nes taipogi esame jo palikuonys’.'),
  (@b44, 17, 29, 'Tad kadangi esame Dievo palikuonys, neturime manyti, kad Dievystė yra panaši į auksą ar sidabrą, ar akmenį, išraižytą meniškai ir žmogaus sumanymu.'),
  (@b44, 17, 30, 'Ir Dievas nekreipė dėmesio į šito nežinojimo laikus; bet dabar visur visiems žmonėms įsako atgailauti,'),
  (@b44, 17, 31, 'nes jis nustatė dieną, kurioje teis pasaulį teisumu per tą vyrą, kurį yra paskyręs; apie tai jis yra visiems garantavęs tuo, kad prikėlė jį iš numirusiųjų“.'),
  (@b44, 17, 32, 'Ir kai jie išgirdo apie mirusiųjų prisikėlimą, vieni šaipėsi, o kiti sakė: „Apie tai tavęs dar paklausysime“.'),
  (@b44, 17, 33, 'Taigi Paulius išėjo iš jų tarpo.'),
  (@b44, 17, 34, 'Tačiau kai kurie vyrai prilipo prie jo ir įtikėjo; tarp kurių buvo areopagietis Dionizas ir moteris, vardu Damaris, ir kiti su jais.'),
  (@b44, 18, 1, 'Po to Paulius išvyko iš Atėnų ir atėjo į Korintą;'),
  (@b44, 18, 2, 'ir rado vieną žydą vardu Akvilas, gimusį Ponte, neseniai atėjusį iš Italijos su savo žmona Priscila (todėl, kad Klaudijus įsakė visiems žydams išeiti iš Romos), ir atėjo pas juos.'),
  (@b44, 18, 3, 'O kadangi jis buvo to paties amato, pasiliko pas juos ir dirbo; nes pagal jų verslą jie buvo palapinių gamintojai.'),
  (@b44, 18, 4, 'Ir kiekvieną sabatą jis kalbėdavosi sinagogoje bei įtikinėjo žydus ir graikus.'),
  (@b44, 18, 5, 'Ir kai Silas bei Timotiejus atėjo iš Makedonijos, Paulius buvo spaudžiamas dvasioje ir liudijo žydams, kad Jėzus yra Kristus.'),
  (@b44, 18, 6, 'Bet kai jie prieštaravo ir piktžodžiavo, jis nusipurtė drabužį ir jiems tarė: „Jūsų kraujas tebūna ant jūsų pačių galvų; aš esu švarus; nuo šiol eisiu pas pagonis“.'),
  (@b44, 18, 7, 'Ir jis iš ten išėjo bei įėjo į namus vieno vyro, vardu Justas, kuris garbino Dievą, kurio namas buvo sujungtas su sinagoga.'),
  (@b44, 18, 8, 'Ir Krispas, vyriausiasis sinagogos valdovas, įtikėjo į Viešpatį su visais savo namais; ir daugelis iš korintiečių klausydamiesi įtikėjo ir buvo pakrikštyti.'),
  (@b44, 18, 9, 'Tada Viešpats naktį kalbėjo Pauliui per regėjimą: „Nebijok, bet kalbėk ir netylėk,'),
  (@b44, 18, 10, 'nes aš esu su tavimi, ir niekas nesikėsins tau pakenkti, nes turiu daug žmonių šiame mieste“.'),
  (@b44, 18, 11, 'Ir jis ten pasiliko metus ir šešis mėnesius, mokydamas tarp jų Dievo žodžio.'),
  (@b44, 18, 12, 'Ir kai Galionas buvo Achajos vietininkas, žydai vieningai sukilo prieš Paulių ir nuvedė jį į teismo krasę,'),
  (@b44, 18, 13, 'sakydami: „Šitas įtikinėja žmones garbinti Dievą priešingai įstatymui“.'),
  (@b44, 18, 14, 'Ir Pauliui besiruošiant praverti burną, Galionas tarė žydams: „O, žydai, jei tai būtų skriaudos arba nedoros nešvankybės reikalas, tai būtų, dėl ko turėčiau jus pakęsti;'),
  (@b44, 18, 15, 'bet jei tai yra žodžių,vardų ir jūsų įstatymo klausimas, jūs rūpinkitės tuo; nes aš nenoriu būti tokių reikalų teisėjas“.'),
  (@b44, 18, 16, 'Ir jis pavarė juos nuo teismo krasės.'),
  (@b44, 18, 17, 'Tada visi graikai paėmė Sosteną, viršiausiąjį sinagogos valdovą, ir mušė jį priešais teismo krasę. Bet Galionui niekas iš viso to nerūpėjo.'),
  (@b44, 18, 18, 'Ir Paulius po to dar ilgai ten pasiliko, ir tada jis atsisveikino su broliais ir iš ten išplaukė į Siriją, o su juo Priscila ir Akvilas, nusiskutęs Kenchrėjoje savo galvą, nes jis davė įžadą.'),
  (@b44, 18, 19, 'Ir jis atvyko į Efezą, ir juos ten paliko, bet jis pats įėjo į sinagogą ir kalbėjosi su žydais.'),
  (@b44, 18, 20, 'Kai jie prašė jį pasilikti su jais ilgesnį laiką, jis nesutiko;'),
  (@b44, 18, 21, 'bet atsisveikino su jais, sakydamas: „Aš būtinai turiu švęsti šią ateinančią šventę Jeruzalėje, bet aš vėl pas jus sugrįšiu, jei Dievas norės“. Ir jis išplaukė iš Efezo.'),
  (@b44, 18, 22, 'Ir išlipęs Cezarėjoje, nuėjęs aukštyn ir pasveikinęs bažnyčią, jis nuvyko žemyn į Antiochą.'),
  (@b44, 18, 23, 'Ir ten praleidęs kiek tai laiko, jis išvyko ir ėjo per visą Galatijos ir Frigijos kraštą paeiliui, stiprindamas visus mokinius.'),
  (@b44, 18, 24, 'Ir vienas žydas, vardu Apolas, gimęs Aleksandrijoje, iškalbingas vyras ir galingas Raštuose, atėjo į Efezą.'),
  (@b44, 18, 25, 'Šis vyras buvo pamokytas Viešpaties kelio ir būdamas karštos dvasios stropiai kalbėjo bei mokė Viešpaties dalykų, žinodamas vien tik Jono krikštą.'),
  (@b44, 18, 26, 'Ir jis pradėjo drąsiai kalbėti sinagogoje; kurį Akvilas ir Priscila išgirdę pasiėmė pas save ir jam tobuliau išaiškino Dievo kelią.'),
  (@b44, 18, 27, 'Ir kai jis buvo nusiteikęs pereiti į Achają, broliai parašė, ragindami mokinius jį priimti; kuris ten atvykęs daug padėjo tiems, kurie buvo įtikėję per malonę;'),
  (@b44, 18, 28, 'nes jis galingai įtikinėjo žydus, ir tai viešai, rodydamas per Raštus, kad Jėzus yra Kristus.'),
  (@b44, 19, 1, 'Ir įvyko, kad Apolui esant Korinte, Paulius, perėjęs per aukštutines sritis, atėjo į Efezą ir suradęs kai kuriuos mokinius'),
  (@b44, 19, 2, 'tarė jiems: „Ar nuo tada, kai įtikėjote, gavote Šventąją Dvasią?“ Ir jie tarė jam: „Mes net negirdėjome, kad yra kokia tai Šventoji Dvasia“.'),
  (@b44, 19, 3, 'Ir jis tarė jiems: „Į ką tuomet esate pakrikštyti?“ O jie tarė: „Į Jono krikštą“.'),
  (@b44, 19, 4, 'Tada Paulius tarė: „Jonas iš tikrųjų krikštijo atgailos krikštu, sakydamas tautai, kad jie tikėtų tą, kuris turi po jo ateiti, tai yra, Kristų Jėzų“.'),
  (@b44, 19, 5, 'Tai išgirdę jie buvo pakrikštyti Viešpaties Jėzaus vardu.'),
  (@b44, 19, 6, 'Ir kai Paulius uždėjo ant jų savo rankas, ant jų atėjo Šventoji Dvasia; ir jie kalbėjo kalbomis bei pranašavo.'),
  (@b44, 19, 7, 'O viso vyrų buvo apie dvylika.'),
  (@b44, 19, 8, 'Ir jis įėjo į sinagogą ir per tris mėnesius drąsiai kalbėjo, diskutuodamas bei įtikinėdamas tai, kas apie Dievo karalystę.'),
  (@b44, 19, 9, 'Tačiau kai nekurie užkietėjo ir netikėjo, bet kalbėjo pikta daugybės akivaizdoje apie tą kelią, jis nuo jų pasitraukė ir atskyrė mokinius, kasdien diskutuodamas Tirano mokykloje.'),
  (@b44, 19, 10, 'Ir tai truko dvejus metus; taip, kad visi, gyvenantys Azijoje, žydai ir graikai, išgirdo Viešpaties Jėzaus žodį.'),
  (@b44, 19, 11, 'Ir Dievas Pauliaus rankomis darė ypatingus stebuklus;'),
  (@b44, 19, 12, 'taip, kad nuo jo kūno ant ligonių buvo nešamos nosinės arba prijuostės, ir ligos pasitraukdavo nuo jų, ir piktosios dvasios iš jų išeidavo.'),
  (@b44, 19, 13, 'Tada kai kurie žydai klajūnai, egzorcistai, apsiėmė pašaukti Viešpaties Jėzaus vardą tiems, kurie turėjo piktąsias dvasias, sakydami: „Mes prisaikdiname jus per Jėzų, kurį skelbia Paulius“.'),
  (@b44, 19, 14, 'Ir kurie taip darė, buvo septyni sūnūs tokio Skevo, žydo ir vyriausiojo iš kunigų.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b44, 19, 15, 'O piktoji dvasia atsiliepdama tarė: „Jėzų pažįstu ir Paulių pažįstu; bet kas esate jūs?“'),
  (@b44, 19, 16, 'Ir tas žmogus, kuriame buvo piktoji dvasia, šoko ant jų ir juos nugalėjo, ir juos įveikė taip, kad jie pabėgo iš tų namų nuogi ir sužeisti.'),
  (@b44, 19, 17, 'Ir tai tapo žinoma visiems žydams ir taipogi graikams, gyvenantiems Efeze; ir juos visus apėmė baimė, ir Viešpaties Jėzaus vardas buvo išaukštintas.'),
  (@b44, 19, 18, 'Ir daugelis, kurie įtikėjo, atėjo ir išpažino, ir apsakė savo darbus.'),
  (@b44, 19, 19, 'Taip pat daugelis iš tų, kurie užsiiminėjo smalsiais mokslais, sunešė savo knygas ir sudegino jas visų akivaizdoje; ir jie apskaičiavo jų vertę, ir ji radosi penkiasdešimt tūkstančių sidabrinių.'),
  (@b44, 19, 20, 'Taip galingai augo Dievo žodis ir ėmė viršų.'),
  (@b44, 19, 21, 'Pasibaigus šitiems dalykams, Paulius nusprendė dvasioje, perėjęs per Makedoniją ir Achają, eiti į Jeruzalę, sakydamas: „Ten pabuvęs aš turiu pamatyti ir Romą“.'),
  (@b44, 19, 22, 'Taigi jis pasiuntė į Makedoniją du iš tų, kurie jam tarnavo, Timotiejų ir Erastą; bet jis pats laikotarpiui pasiliko Azijoje.'),
  (@b44, 19, 23, 'Ir tuo pačiu metu kilo nemažas sąmyšis dėl to kelio.'),
  (@b44, 19, 24, 'Nes vienas, vardu Demetrijus, sidabrakalys, gaminęs sidabrines šventyklas Dianai, nešė nemažą pelną amatininkams;'),
  (@b44, 19, 25, 'kuriuos jis susikvietė kartu su panašaus verslo darbininkais ir tarė: „Ponai, jūs žinote, kad iš šito amato turime savo gerovę.'),
  (@b44, 19, 26, 'Be to, matote ir girdite, kad ne vien tik Efeze, bet beveik visoje Azijoje šitas Paulius įtikino ir nukreipė daug žmonių, sakydamas, kad tie, kurie padaryti rankomis, nėra dievai,'),
  (@b44, 19, 27, 'todėl ne vien šis mūsų amatas yra pavojuje tapti beverčiu; bet ir didžiosios deivės Dianos šventykla bus paniekinta, ir bus sunaikinta jos didybė, kurią garbina visa Azija ir pasaulis“.'),
  (@b44, 19, 28, 'Ir išgirdę šiuos pasakymus, jie buvo pilni rūstybės ir šaukė sakydami: „Didi efeziečių Diana!“'),
  (@b44, 19, 29, 'Ir visas miestas prisipildė sąmyšio; ir pasigavę vyrus iš Makedonijos, Pauliaus kelionės palydovus Gajų ir Aristarchą, jie vieningai veržėsi į teatrą.'),
  (@b44, 19, 30, 'Ir kai Paulius norėjo įeiti pas liaudį, mokiniai jam neleido.'),
  (@b44, 19, 31, 'Ir vieni iš Azijos vyriausiųjų, kurie buvo jo draugai, pasiuntė pas jį, prašydami jo, kad jis nedrįstų pats eiti į teatrą.'),
  (@b44, 19, 32, 'Taigi vieni šaukė viena, o kiti kita, nes susirinkimas buvo sumišęs; ir didesnė dalis nežinojo, kodėl jie susirinko.'),
  (@b44, 19, 33, 'Ir jie ištempė iš minios Aleksandrą, žydams jį stumiant į priekį. Ir Aleksandras pamojo ranka ir norėjo liaudžiai pasakyti apsigynimo kalbą.'),
  (@b44, 19, 34, 'Bet kai jie sužinojo, kad jis buvo žydas, visi vienu balsu apie dvi valandas šaukė: „Didi efeziečių Diana!“'),
  (@b44, 19, 35, 'Ir miesto raštininkas nuraminęs liaudį tarė: „Efezo vyrai, kas gi yra toks žmogus, kuris nežinotų, kad efeziečių miestas yra garbintojas didžiosios deivės Dianos ir atvaizdo, nukritusio iš Jupiterio?'),
  (@b44, 19, 36, 'Tad kadangi tam negalima prieštarauti, turite būti ramūs ir nieko nedaryti neapgalvotai.'),
  (@b44, 19, 37, 'Nes čia atvedėte šituos vyrus, kurie nėra nei bažnyčių plėšikai, nei jūsų deivės piktžodžiautojai.'),
  (@b44, 19, 38, 'Todėl, jei Demetrijus ir su juo esantys amatininkai turi reikalą prieš ką nors, teismas yra atviras, ir yra vietininkai: tegul jie skundžia vienas kitą.'),
  (@b44, 19, 39, 'Bet jei ko nors ieškote dėl kitų reikalų, tai bus nuspręsta teisėtame susirinkime.'),
  (@b44, 19, 40, 'Nes esame pavojuje būti iškviesti apklausai dėl šios dienos triukšmo, nesant jokiai priežasčiai, kuria galėtume pasiaiškinti dėl šio susibūrimo“.'),
  (@b44, 19, 41, 'Ir taip pakalbėjęs, jis paleido susirinkimą.'),
  (@b44, 20, 1, 'Ir triukšmui paliovus Paulius pasikvietė mokinius, juos apkabino ir išėjo, kad vyktų į Makedoniją.'),
  (@b44, 20, 2, 'Ir perėjęs tas vietoves ir suteikęs jiems daug paskatinimo, jis atėjo į Graikiją'),
  (@b44, 20, 3, 'ir ten pasiliko tris mėnesius. Ir kai jam besiruošiant plaukti į Siriją, žydai jo tykojo, jis nusprendė grįžti per Makedoniją.'),
  (@b44, 20, 4, 'Ir į Aziją jį lydėjo Sopateris iš Berėjos; o iš tesalonikiečių Aristarchas ir Sekundas; ir Gajus iš Derbės, ir Timotiejus; o iš Azijos Tichikas ir Trofimas.'),
  (@b44, 20, 5, 'Šitie, pirma nuėję, laukė mūsų Trojoje.'),
  (@b44, 20, 6, 'O po Neraugintos duonos dienų išplaukėme iš Filipų ir per penkias dienas atvykome pas juos į Troją, kur pasilikome septynias dienas.'),
  (@b44, 20, 7, 'Ir pirmąją savaitės dieną, kai mokiniai susirinko laužyti duonos, Paulius jiems skelbė, pasiruošęs rytojaus dieną išeiti; ir užtęsė savo kalbą iki vidurnakčio.'),
  (@b44, 20, 8, 'Ir buvo daug šviesų aukštutiniame kambaryje, kur jie buvo susirinkę.'),
  (@b44, 20, 9, 'Ir lange sėdėjo vienas jaunuolis, vardu Eutikas, užmigęs giliu miegu; ir Pauliui ilgai beskelbiant, jis nugrimzdo į miegą ir nukrito iš trečio aukšto, ir buvo pakeltas negyvas.'),
  (@b44, 20, 10, 'Ir Paulius nuėjo žemyn, užkrito ant jo ir jį apkabinęs tarė: „Nebūkite sunerimę; nes jo gyvybė yra jame“.'),
  (@b44, 20, 11, 'Taigi jis, vėl atėjęs į viršų, laužęs duoną, valgęs ir pakalbėjęs ilgą laiko tarpą, net iki aušros, taip išėjo.'),
  (@b44, 20, 12, 'Ir jie atvedė jaunuolį gyvą ir buvo nemenkai paguosti.'),
  (@b44, 20, 13, 'Ir mes pirma nuėjome į laivą ir išplaukėme į Asą, ten ketindami pasiimti Paulių, nes jis taip nurodė, pats ketindamas eiti pėsčiomis.'),
  (@b44, 20, 14, 'Ir kai jis susitiko su mumis Asoje, jį pasiėmėme ir atvykome į Mitilėnę.'),
  (@b44, 20, 15, 'Ir iš ten išplaukėme ir rytojaus dieną atvykome priešais Chiją; o kitą dieną atvykome į Samosą ir pasilikome Trogiliume; ir dar kitą dieną atvykome į Miletą.'),
  (@b44, 20, 16, 'Nes Paulius buvo nusprendęs praplaukti Efezą, kadangi jis nenorėjo praleisti laiko Azijoje; nes jis skubėjo, jei būtų įmanoma, Sekminių dieną būti Jeruzalėje.'),
  (@b44, 20, 17, 'Ir iš Mileto jis pasiuntė į Efezą ir pakvietė bažnyčios vyresniuosius.'),
  (@b44, 20, 18, 'Ir kai jie pas jį atėjo, jis tarė jiems: „Jūs žinote nuo pirmos dienos, kai atėjau į Aziją, koks buvau su jumis visais laikotarpiais,'),
  (@b44, 20, 19, 'tarnaudamas Viešpačiui su visu nuolankumu ir daugeliu ašarų, ir pagundų, kurios ištiko mane dėl žydų tykojimo;'),
  (@b44, 20, 20, 'ir kaip neužlaikiau nieko, kas buvo jums naudinga, bet jums paskelbiau ir jus mokiau viešai bei iš namų į namus,'),
  (@b44, 20, 21, 'liudydamas tiek žydams, tiek ir graikams atgailą link Dievo ir tikėjimą į mūsų Viešpatį Jėzų Kristų.'),
  (@b44, 20, 22, 'O štai dabar dvasioje sukaustytas einu į Jeruzalę nežinodamas, kas mane ten ištiks;'),
  (@b44, 20, 23, 'tiktai Šventoji Dvasia liudija kiekviename mieste sakydama, kad manęs laukia pančiai ir vargai.'),
  (@b44, 20, 24, 'Bet niekas iš šitų dalykų manęs nejaudina, ir nebranginu savo gyvybės, idant užbaigčiau savo bėgimą su džiaugsmu ir tarnystę, kurią gavau iš Viešpaties Jėzaus, kad liudyčiau Dievo malonės evangeliją.'),
  (@b44, 20, 25, 'O dabar štai žinau, kad jūs visi, tarp kurių ėjau skelbdamas Dievo karalystę, nebematysite mano veido.'),
  (@b44, 20, 26, 'Todėl liudiju jums šią dieną, kad esu tyras nuo visų žmonių kraujo.'),
  (@b44, 20, 27, 'Nes nevengiau jums paskelbti visų Dievo sumanymų.'),
  (@b44, 20, 28, 'Todėl žiūrėkite savęs ir visos kaimenės, kuriai Šventoji Dvasia paskyrė jus prižiūrėtojais, ganyti Dievo bažnyčią, kurią jis nusipirko savo krauju.'),
  (@b44, 20, 29, 'Nes žinau tai, kad po mano išėjimo tarp jūsų įeis smarkūs vilkai, nesigailintys kaimenės.'),
  (@b44, 20, 30, 'Taip pat ir iš jūsų pakils vyrai, kalbantys iškreiptus dalykus, kad patrauktų mokinius paskui save.'),
  (@b44, 20, 31, 'Todėl budėkite ir prisiminkite, kad per trejus metus naktį ir dieną nepalioviau įspėjinėti kiekvieno su ašaromis.'),
  (@b44, 20, 32, 'O dabar, broliai, pavedu jus Dievui ir jo malonės žodžiui, kuris yra pajėgus jus pastatyti ir duoti jums paveldą tarp visų tų, kurie yra pašvęsti.'),
  (@b44, 20, 33, 'Aš negeidžiau niekieno sidabro ar aukso, ar drabužio.'),
  (@b44, 20, 34, 'Taip, jūs patys žinote, kad šitos rankos tarnavo mano reikmėms ir tiems, kurie buvo su manimi.'),
  (@b44, 20, 35, 'Aš visa jums parodžiau, kad šitaip triūsdami turite paremti silpnuosius ir prisiminti Viešpaties Jėzaus žodžius, kaip jis sakė: ‘Labiau palaiminta duoti, negu imti’“.'),
  (@b44, 20, 36, 'Ir taip pakalbėjęs jis atsiklaupė ir su jais visais pasimeldė.'),
  (@b44, 20, 37, 'Ir jie visi smarkiai verkė, puolė Pauliui ant kaklo ir jį bučiavo,'),
  (@b44, 20, 38, 'labiausiai liūdėdami dėl jo pasakytų žodžių, kad jie nebematys jo veido. Ir jie palydėjo jį į laivą.'),
  (@b44, 21, 1, 'Ir įvyko, kai nuo jų atsiskyrėme ir pasileidome nuo kranto, mes tiesiu kursu atvykome į Kosą ir rytojaus dieną į Rodą, o iš ten į Patarą;'),
  (@b44, 21, 2, 'ir suradę laivą, plaukiantį į Finikiją, įlipome ir išvykome.'),
  (@b44, 21, 3, 'Na, o išvydę Kiprą, jį palikome kairėje ir plaukėme į Siriją, ir išlipome Tyre, nes ten laivas turėjo iškrauti savo naštą.'),
  (@b44, 21, 4, 'Ir suradę mokinius, ten pasilikome septynias dienas; jie sakė Pauliui per Dvasią, kad jis neitų aukštyn į Jeruzalę.'),
  (@b44, 21, 5, 'Ir kai užbaigėme tas dienas, išėjome ir nukeliavome sau; ir jie visi su žmonomis ir vaikais mus lydėjo, kol atsiradome už miesto; ir mes atsiklaupėme ant kranto ir pasimeldėme.'),
  (@b44, 21, 6, 'Ir vieni su kitais atsisveikinę įlipome į laivą; ir jie sugrįžo namo.'),
  (@b44, 21, 7, 'Ir kai užbaigėme savo plaukimą iš Tyro, atvykome į Ptolemaidą ir pasveikinome brolius bei pasilikome su jais vieną dieną.'),
  (@b44, 21, 8, 'O rytojaus dieną mes, kurie buvome drauge su Pauliumi, išvykome ir atvykome į Cezarėją; ir įėjome į namus evangelisto Pilypo, kuris buvo vienas iš septynių; ir pasilikome pas jį.'),
  (@b44, 21, 9, 'Ir tas vyras turėjo keturias dukteris, mergeles, kurios pranašavo.'),
  (@b44, 21, 10, 'Ir mums ten pasilikus daug dienų, iš Judėjos atėjo žemyn vienas pranašas, vardu Agabas.'),
  (@b44, 21, 11, 'Ir pas mus atėjęs, jis paėmė Pauliaus juostą ir susirišo savo rankas bei kojas ir tarė: „Taip sako Šventoji Dvasia: ‘Taip žydai Jeruzalėje suriš tą vyrą, kuriam priklauso šita juosta, ir atiduos jį į pagonių rankas’“.'),
  (@b44, 21, 12, 'Ir kai tai išgirdome, mes ir tenykščiai maldavome jo neiti aukštyn į Jeruzalę.'),
  (@b44, 21, 13, 'Tada Paulius atsakė: „Ką darote verkdami ir draskydami man širdį? Nes aš pasiruošęs ne tik būti surištas, bet ir mirti Jeruzalėje dėl Viešpaties Jėzaus vardo“.'),
  (@b44, 21, 14, 'Ir kai jis nesidavė perkalbamas, mes paliovėme, sakydami: „Tebūna atlikta Viešpaties valia“.'),
  (@b44, 21, 15, 'Ir po tų dienų pasiėmėme savo mantą ir nuėjome aukštyn į Jeruzalę.'),
  (@b44, 21, 16, 'Su mumis taip pat vyko kai kurie iš Cezarėjos mokinių ir vedėsi su savimi tokį Mnasoną iš Kipro, seną mokinį, pas kurį turėjome apsistoti.'),
  (@b44, 21, 17, 'O kai atėjome į Jeruzalę, broliai mus priėmė su džiaugsmu.'),
  (@b44, 21, 18, 'Ir rytojaus dieną Paulius su mumis įėjo pas Jokūbą; ir ten buvo visi vyresnieji.'),
  (@b44, 21, 19, 'Ir juos pasveikinęs jis detaliai išdėstė, ką Dievas atliko tarp pagonių per jo tarnystę.'),
  (@b44, 21, 20, 'Ir tai išgirdę jie šlovino Viešpatį ir jam tarė: „Matai, broli, kiek tūkstančių yra žydų, kurie tiki; ir jie visi uolūs dėl įstatymo;'),
  (@b44, 21, 21, 'ir jiems yra pranešta apie tave, kad tu mokai visus žydus, esančius tarp pagonių, atsižadėti Mozės, sakydamas, kad jiems nereikia apipjaustyti savo vaikų nei vaikščioti pagal papročius.'),
  (@b44, 21, 22, 'Tad kas gi tai? Minia būtinai turės susirinkti, nes jie išgirs, kad tu esi atėjęs.'),
  (@b44, 21, 23, 'Todėl daryk tai, ką tau sakome: pas mus yra keturi vyrai, kurie yra davę įžadą;'),
  (@b44, 21, 24, 'juos paimk ir apsivalyk su jais, ir prisiimk jų išlaidas, kad jie nusiskustų galvas; ir visi žinotų, jog tai, kas apie tave jiems pranešta, yra niekas; bet kad ir tu pats vaikštai drausmingai ir laikaisi įstatymo.'),
  (@b44, 21, 25, 'O dėl pagonių, kurie tiki, esame parašę ir nusprendę, kad jie nieko tokio nesilaikytų, o tik kad saugotųsi nuo to, kas atnašaujama stabams, nuo kraujo, nuo pasmaugtų ir nuo paleistuvystės“.'),
  (@b44, 21, 26, 'Tada Paulius paėmė vyrus ir rytojaus dieną apsivalęs su jais įėjo į šventyklą pranešti apsivalymo dienų užbaigimą, kol turės būti atnašaujama atnaša už kiekvieną iš jų.'),
  (@b44, 21, 27, 'O kai septynios dienos buvo beveik pasibaigusios, Azijos žydai, pamatę jį šventykloje, sukurstė visą tautą ir pridėjo prie jo rankas,'),
  (@b44, 21, 28, 'šaukdami: „Izraelio vyrai, padėkite: šitas yra tas vyras, kuris visur visus moko prieš tautą, įstatymą ir šitą vietą; o be to jis dar ir graikus atvedė į šventyklą ir suteršė šią šventą vietą'),
  (@b44, 21, 29, '(nes jie prieš tai buvo matę su juo mieste efezietį Trofimą ir manė, kad Paulius buvo jį atsivedęs į šventyklą).'),
  (@b44, 21, 30, 'Ir visas miestas sujudo, ir tauta susibėgo kartu; ir jie pačiupo Paulių ir išvedė jį iš šventyklos; ir bematant durys buvo užrakintos.'),
  (@b44, 21, 31, 'Ir kai jie ruošėsi jį užmušti, žinia atėjo iki vyriausiojo pulko vado, kad visa Jeruzalė sujudo.'),
  (@b44, 21, 32, 'Jis tuoj pat paėmė kareivius bei šimtininkus ir nubėgo žemyn pas juos; ir pamatę vyriausiąjį vadą ir kareivius jie liovėsi mušę Paulių.'),
  (@b44, 21, 33, 'Tada vyriausiasis vadas priėjo, jį paėmė ir įsakė surišti jį dviem grandinėm; ir klausinėjo, kas jis yra ir ką padaręs.'),
  (@b44, 21, 34, 'O minios tarpe vieni šaukė viena, kiti kita; ir dėl triukšmo negalėdamas sužinoti tikrumo jis įsakė jį nuvesti į pilį.'),
  (@b44, 21, 35, 'Ir kai jis atėjo ant laiptų, buvo taip, kad jis buvo kareivių nešamas dėl tautos įsisiautėjimo.'),
  (@b44, 21, 36, 'Nes tautos daugybė sekė paskui, šaukdama: „Šalin jį!“'),
  (@b44, 21, 37, 'Ir kai Paulius buvo bevedamas į pilį, jis tarė vyriausiam vadui: „Ar galiu tau kalbėti?“, kuris tarė: „Ar moki kalbėti graikiškai?'),
  (@b44, 21, 38, 'Ar tu nesi tas egiptietis, kuris prieš šias dienas sukėlė sujudimą ir išvedė į dykumą keturis tūkstančius vyrų, kurie buvo žmogžudžiai?“'),
  (@b44, 21, 39, 'Bet Paulius tarė: „Aš esu žydas, žmogus iš Kilikijos miesto Tarso, nemenko miesto pilietis; ir maldauju tavęs, leisk man kalbėti tautai“.'),
  (@b44, 21, 40, 'Ir kai jis davė jam leidimą, Paulius atsistojo ant laiptų ir pamojo ranka tautai. Ir kai pasidarė didi tyla, jis kalbėjo jiems hebrajų kalba, sakydamas:'),
  (@b44, 22, 1, '„Vyrai, broliai ir tėvai, išklausykite mano apsigynimo, kurį dabar kalbu jums'),
  (@b44, 22, 2, '(ir išgirdę jį kalbant jiems hebrajų kalba, jie dar labiau nutilo; ir jis sako):'),
  (@b44, 22, 3, '„Aš iš tiesų esu vyras, žydas, gimęs Kilikijos mieste Tarse, dar užaugintas šiame mieste prie Gamalielio kojų ir išmokytas pagal tobulą tėvų įstatymo būdą, ir buvau uolus dėl Dievo kaip jūs visi esate šią dieną.'),
  (@b44, 22, 4, 'Ir iki mirties persekiojau šitą kelią, surišdamas ir atiduodamas į kalėjimus tiek vyrus, tiek moteris.'),
  (@b44, 22, 5, 'Kaip ir aukščiausiasis kunigas man liudija, ir visas vyresniųjų luomas, iš kurių taip pat gavau laiškus broliams ir ėjau į Damaską, kad ten esančius vesčiau surištus į Jeruzalę, idant būtų nubausti.'),
  (@b44, 22, 6, 'Ir įvyko, kad, kai aš keliavau ir apie vidurdienį priartėjau prie Damasko, staiga iš dangaus mane apšvietė didi šviesa.'),
  (@b44, 22, 7, 'Ir aš nukritau ant žemės ir išgirdau man sakantį balsą: ‘Sauliau, Sauliau, kodėl mane persekioji?’'),
  (@b44, 22, 8, 'Ir aš atsakiau: ‘Kas tu esi, Viešpatie?’ O jis man tarė: ‘Aš esu Jėzus iš Nazareto, kurį tu persekioji’.'),
  (@b44, 22, 9, 'Ir tie, kurie buvo su manimi, iš tiesų matė šviesą ir išsigando; bet jie negirdėjo man kalbėjusiojo balso.'),
  (@b44, 22, 10, 'Ir aš tariau: ‘Ką turiu daryti, Viešpatie?’ O Viešpats man tarė: ‘Kelkis ir eik į Damaską; ir ten tau bus pasakyta apie visa, kas tau yra paskirta daryti’.'),
  (@b44, 22, 11, 'Ir kai negalėjau matyti dėl tos šviesos šlovės, vedamas už rankos tų, kurie buvo su manimi, atėjau į Damaską.'),
  (@b44, 22, 12, 'Ir toks Ananijas, dievobaimingas pagal įstatymą vyras, turintis gerą atsiliepimą iš visų ten gyvenančių žydų,'),
  (@b44, 22, 13, 'atėjo pas mane, atsistojo ir man tarė: ‘Broli Sauliau, atgauk savo regėjimą!’ Ir tą pačią valandą pažiūrėjau į jį aukštyn.'),
  (@b44, 22, 14, 'Ir jis tarė: ‘Mūsų tėvų Dievas tave išsirinko, kad pažintum jo valią ir pamatytum tą Teisųjį, ir išgirstum jo burnos balsą.'),
  (@b44, 22, 15, 'Nes tu būsi jo liudytojas visiems žmonėms to, ką matei ir girdėjai.'),
  (@b44, 22, 16, 'O dabar, ko delsi? Kelkis, būk pakrikštytas ir nusiplauk savo nuodėmes, šaukdamasis Viešpaties vardo’.'),
  (@b44, 22, 17, 'Ir įvyko, kai buvau grįžęs į Jeruzalę, man besimeldžiant šventykloje, buvau transe;'),
  (@b44, 22, 18, 'ir pamačiau jį man sakant: ‘Skubėk ir greitai išeik iš Jeruzalės, nes jie nepriims tavo liudijimo apie mane’.'),
  (@b44, 22, 19, 'Ir aš tariau: ‘Viešpatie, jie žino, kad aš įkalindavau ir mušdavau kiekvienoje sinagogoje tuos, kurie tiki į tave;'),
  (@b44, 22, 20, 'ir kai buvo pralietas tavo kankinio Stepono kraujas, aš irgi stovėjau šalia ir pritariau jo mirčiai, ir saugojau drabužius tų, kurie jį užmušė.'),
  (@b44, 22, 21, 'O jis man tarė: ‘Išeik, nes aš tave išsiųsiu toli pas pagonis’“.'),
  (@b44, 22, 22, 'Ir jie klausėsi jo iki šio žodžio, ir tada pakėlė savo balsus ir tarė: „Šalin tokį nuo žemės, nes nedera, kad jis gyventų!“'),
  (@b44, 22, 23, 'Ir jiems šaukiant bei nusimetant drabužius ir mėtant dulkes į orą,'),
  (@b44, 22, 24, 'vyriausiasis vadas įsakė įvesti jį į pilį ir liepė, kad jis būtų tardomas plakant; idant sužinotų, kodėl jie taip prieš jį šaukė.'),
  (@b44, 22, 25, 'Ir kai jie rišo jį diržais, Paulius tarė šalia stovinčiam šimtininkui: „Ar jums teisėta plakti žmogų, kuris yra romietis ir nepasmerktas?“'),
  (@b44, 22, 26, 'Kai šimtininkas tai išgirdo, jis nuėjo ir pasakė vyriausiajam vadui, tardamas: „Žiūrėk, ką darai, nes šitas žmogus yra romietis“.'),
  (@b44, 22, 27, 'Tada vyriausiasis vadas atėjo ir jam tarė: „Sakyk man, ar tu esi romietis?“ Jis tarė: „Taip“.'),
  (@b44, 22, 28, 'Ir vyriausiasis vadas atsakė: „Už didelę sumą įsigijau šią laisvę“. O Paulius tarė: „O aš gimiau laisvas“.'),
  (@b44, 22, 29, 'Tuomet bematant pasitraukė nuo jo tie, kurie turėjo jį tardyti; ir vyriausiasis vadas irgi išsigando po to, kai sužinojo, kad jis buvo romietis ir kad buvo jį surišęs.'),
  (@b44, 22, 30, 'Rytojaus dieną, norėdamas sužinoti tikrumą, kodėl jis buvo apkaltintas žydų, jis atlaisvino jį nuo raiščių ir įsakė pasirodyti vyriausiems kunigams bei visai jų tarybai, ir, atvedęs Paulių žemyn, pastatė jį jų akivaizdoje.'),
  (@b44, 23, 1, 'Ir Paulius įdėmiai žiūrėdamas į tarybą tarė: „Vyrai ir broliai, aš iki šios dienos gyvenau Dievo akivaizdoje visiškai gryna sąžine“.'),
  (@b44, 23, 2, 'O aukščiausiasis kunigas Ananijas įsakė šalia jo stovintiems smogti jam per burną.'),
  (@b44, 23, 3, 'Tada Paulius jam tarė: „Dievas tau smogs, pabaltinta siena; ar tu sėdi, kad mane teistum pagal įstatymą, o įsakai, kad man smogtų priešingai įstatymui?“'),
  (@b44, 23, 4, 'Ir stovintys šalia tarė: „Ar tu keiki aukščiausiąjį Dievo kunigą?“'),
  (@b44, 23, 5, 'Tada Paulius tarė: „Nežinojau, broliai, kad jis yra aukščiausiasis kunigas, nes yra parašyta: ‘Nekalbėk pikto apie savo tautos valdovą’.'),
  (@b44, 23, 6, 'Bet Paulius, supratęs, kad viena dalis buvo sadukiejai, o kita – fariziejai, šaukė taryboje: „Vyrai ir broliai, aš esu fariziejus, fariziejaus sūnus; esu teisiamas dėl mirusiųjų vilties ir prisikėlimo“.'),
  (@b44, 23, 7, 'Ir kai jis taip pasakė, tarp fariziejų ir sadukiejų kilo ginčas; ir minia pasidalijo.'),
  (@b44, 23, 8, 'Nes sadukiejai sako, kad nėra prisikėlimo nei angelo, nei dvasios; bet fariziejai tuos pripažįsta.'),
  (@b44, 23, 9, 'Ir kilo didelis šauksmas; ir pakilo raštininkai iš fariziejų pusės, ir ginčijosi, sakydami: „Mes nerandame nieko pikta šiame žmoguje; bet jei jam kalbėjo dvasia ar angelas, nekovokime prieš Dievą“.'),
  (@b44, 23, 10, 'Ir kai kilo smarkus ginčas, vyriausiasis vadas bijodamas, kad Paulius nebūtų jų sudraskytas į gabalus, įsakė kareiviams nueiti žemyn ir jėga paimti jį iš jų tarpo bei nuvesti į pilį.'),
  (@b44, 23, 11, 'Ir ateinančią naktį prie jo atsistojo Viešpats ir tarė: „Pauliau, būk linksmas; nes kaip tu liudijai apie mane Jeruzalėje, taip turi liudyti ir Romoje“.'),
  (@b44, 23, 12, 'Ir kai buvo diena, susibūrė kai kurie žydai ir užsikeikė, sakydami, kad jie nei valgys, nei gers, kol nenužudys Pauliaus.'),
  (@b44, 23, 13, 'O buvo daugiau nei keturiasdešimt surengusių šį sąmokslą.'),
  (@b44, 23, 14, 'Ir jie atėjo pas vyriausiuosius kunigus bei vyresniuosius ir tarė: „Mes didžiai užsikeikėme, kad nieko nevalgysime, kol neužmušime Pauliaus.'),
  (@b44, 23, 15, 'Todėl dabar su taryba praneškite vyriausiajam vadui, kad jis atvestų jį rytoj žemyn pas jus, tarsi norėtumėte geriau išsiaiškinti apie jį; o mes, jam dar neprisiartinus, esame pasiruošę jį nužudyti“.'),
  (@b44, 23, 16, 'Bet Pauliaus sesers sūnus, išgirdęs apie jų tykojimą, nuėjo ir įėjo į pilį, ir pasakė Pauliui.'),
  (@b44, 23, 17, 'Tada Paulius pasišaukė vieną iš šimtininkų ir tarė: „Nuvesk šitą jaunuolį pas vyriausiąjį vadą, nes jis turi jam kai ką pasakyti“.'),
  (@b44, 23, 18, 'Taigi jis paėmė jį, nuvedė pas vyriausiąjį vadą ir tarė: „Kalinys Paulius pasišaukė mane ir meldė mane atvesti pas tave šį jaunuolį, kuris turi tau kažką pasakyti“.'),
  (@b44, 23, 19, 'Tada vyriausiasis vadas paėmė jį už rankos ir nuėjo su juo asmeniškai į šalį, ir jo paklausė: „Kas tai yra, ką turi man pasakyti?“'),
  (@b44, 23, 20, 'Ir jis tarė: „Žydai sutarė tavęs prašyti, kad rytoj nuvestum Paulių žemyn į tarybą, tarsi jie nori apie jį šį tą geriau išsiaiškinti.'),
  (@b44, 23, 21, 'Bet tu nenusileisk jiems; nes iš jų daugiau nei keturiasdešimt vyrų jo tyko, kurie surišo save priesaika, kad jie nei valgys, nei gers, kol jo nenužudys; o dabar jie yra pasiruošę, laukdami iš tavęs pažado“.'),
  (@b44, 23, 22, 'Taigi vyriausiasis vadas išleido jaunuolį ir jį įpareigojo: „Žiūrėk, niekam nesakyk, kad man tai pranešei“.'),
  (@b44, 23, 23, 'Ir jis pasišaukė du šimtininkus, sakydamas: „Paruoškite du šimtus kareivių eiti į Cezarėją ir septyniasdešimt raitelių bei du šimtus ietininkų trečią valandą nakties;'),
  (@b44, 23, 24, 'ir parūpinkite jiems gyvulių, kad jie užsodintų Paulių ir nugabentų jį sveiką pas valdytoją Feliksą“.'),
  (@b44, 23, 25, 'Ir jis parašė tokio pobūdžio laišką:'),
  (@b44, 23, 26, '„Klaudijus Lisijus, pačiam prakilniausiajam valdytojui Feliksui siunčia sveikinimą.'),
  (@b44, 23, 27, 'Šitas vyras buvo pagautas žydų ir turėjo būti jų nužudytas; tuomet aš atėjau su kariuomene ir jį išgelbėjau, supratęs, kad jis buvo romietis.'),
  (@b44, 23, 28, 'Ir norėdamas sužinoti priežastį, dėl kurios jie kaltino jį, nuvedžiau jį į jų tarybą;'),
  (@b44, 23, 29, 'supratau jį kaltinamą dėl jų įstatymo klausimų, bet nieko nepaskirta jo kaltinimui, kas būtų verta mirties ar pančių.'),
  (@b44, 23, 30, 'Ir kai man buvo pasakyta, kad žydai tykojo to vyro, tuojau pat nusiunčiau pas tave ir jo kaltintojams daviau įsakymą, kad ir tavo akivaizdoje pasakytų, ką jie turėjo prieš jį. Lik sveikas“.'),
  (@b44, 23, 31, 'Tada kareiviai, kaip jiems buvo įsakyta, paėmė Paulių ir nakčia nugabeno jį į Antipatridą.'),
  (@b44, 23, 32, 'Rytojaus dieną jie paliko raitelius eiti su juo ir sugrįžo į pilį;'),
  (@b44, 23, 33, 'kurie, atėję į Cezarėją ir padavę valdytojui laišką, pristatė jo akivaizdon ir Paulių.'),
  (@b44, 23, 34, 'Ir perskaitęs laišką valdytojas paklausė, iš kokios jis provincijos. Ir supratęs, kad jis iš Kilikijos,'),
  (@b44, 23, 35, 'tarė: „Aš išklausysiu tavęs, kai bus atėję ir tavo kaltintojai“. Ir jis įsakė saugoti jį Erodo teismo rūmuose.'),
  (@b44, 24, 1, 'Ir po penkių dienų aukščiausiasis kunigas Ananijas nusileido su vyresniaisiais ir su vienu oratoriumi, vardu Tertulas, kurie įskundė Paulių valdytojui.'),
  (@b44, 24, 2, 'Ir kai jis buvo iškviestas, Tertulas pradėjo jį kaltinti, sakydamas: „Kadangi per tave patiriame didelę ramybę ir kad tavo rūpesčiu šitai tautai yra daromi labai vertingi darbai,'),
  (@b44, 24, 3, 'mes visada ir visur tai pripažįstame, kilmingiausiasis Feliksai, su visu dėkingumu.'),
  (@b44, 24, 4, 'Tačiau, kad toliau tavęs nevarginčiau, meldžiu tave, kad iš savo maloningumo išklausytum keletą mūsų žodžių.'),
  (@b44, 24, 5, 'Nes šitą žmogų radome esant kenksmingu ir maišto kurstytoju tarp visų žydų po visą pasaulį; ir nazariečių sektos vadeiva,'),
  (@b44, 24, 6, 'kuris taip pat ruošėsi teršti šventyklą; kurį sučiupome ir norėjome teisti pagal mūsų įstatymą.'),
  (@b44, 24, 7, 'Bet vyriausiasis vadas Lisijus užėjo ant mūsų ir su didele prievarta atėmė jį iš mūsų rankų,'),
  (@b44, 24, 8, 'įsakydamas jo kaltintojams ateiti pas tave; apklausdamas pats galėsi iš jo sužinoti apie viską, kuo mes jį kaltiname“.'),
  (@b44, 24, 9, 'Ir žydai taip pat pritarė sakydami, kad taip yra.'),
  (@b44, 24, 10, 'Tada Paulius, po to kai valdytojas pamojo jam ranka kalbėti, atsakė: „Kadangi žinau, kad daug metų buvai šios tautos teisėju, dar džiugiau atsakysiu už save;'),
  (@b44, 24, 11, 'nes tu gali suprasti, kad yra dar tik dvylika dienų nuo tada, kai ėjau aukštyn į Jeruzalę garbinti.'),
  (@b44, 24, 12, 'Ir nei jie mane rado šventykloje su kuo besiginčijant, nei sukeliant tautą, nei sinagogose, nei mieste;'),
  (@b44, 24, 13, 'nei jie gali įrodyti tai, kuo jie dabar mane kaltina.'),
  (@b44, 24, 14, 'Bet tau išpažįstu tai, kad pagal tą kelią, kurį jie vadina erezija, taip aš garbinu savo tėvų Dievą, tikėdamas viskuo, kas yra parašyta įstatyme ir pranašuose;'),
  (@b44, 24, 15, 'ir turiu viltį Dievo link, kurią ir jie patys pripažįsta, kad bus mirusiųjų prisikėlimas, tiek teisiųjų, tiek neteisiųjų.'),
  (@b44, 24, 16, 'Ir tuo lavinu save, kad visada turėčiau sąžinę be nusižengimo prieš Dievą ir žmones.'),
  (@b44, 24, 17, 'Na, o po daugelio metų atvykau, kad atneščiau išmaldas savo tautai ir atnašas.'),
  (@b44, 24, 18, 'Tame gi kai kurie žydai iš Azijos rado mane apsivaliusį šventykloje be minios ir be triukšmo.'),
  (@b44, 24, 19, 'Kuriems reikėtų būti čia, tavo akivaizdoje, ir prieštarauti, jei ką turi prieš mane.'),
  (@b44, 24, 20, 'Arba tegul šitie patys pasako, jeigu jie rado manyje kokį piktą darbą, kol stovėjau prieš tarybą,'),
  (@b44, 24, 21, 'nebent tai būtų dėl to vieno balso, kai šaukiau stovėdamas tarp jų: ‘Dėl mirusiųjų prisikėlimo šią dieną esu jūsų teisiamas’“.'),
  (@b44, 24, 22, 'Ir tai išklausęs Feliksas, turėdamas tobulesnį šio kelio pažinimą, atidėjo juos ir tarė: „Kai ateis žemyn vyriausiasis vadas Lisijus, iki galo sužinosiu apie jūsų reikalą“.'),
  (@b44, 24, 23, 'Ir jis įsakė šimtininkui, kad saugotų Paulių ir kad leistų jam turėti laisvę, ir kad jis nedraustų nei vienam iš jo pažįstamų jam tarnauti ar pas jį ateiti.'),
  (@b44, 24, 24, 'Ir po keleto dienų, kai atėjo Feliksas su savo žmona Drusila, kuri buvo žydė, jis pasiuntė Pauliaus pakviesti ir išklausė jo apie tikėjimą Kristumi.'),
  (@b44, 24, 25, 'Ir kai jis kalbėjo apie teisumą, susilaikymą ir ateisiantį teismą, Feliksas drebėjo ir atsakė: „Šiam kartui eik; kai man bus tinkamas laikas, išsikviesiu tave“.'),
  (@b44, 24, 26, 'Jis taip pat tikėjosi, kad Paulius jam duosiąs pinigų, idant jį paleistų; todėl jis dažniau pasiųsdavo jo pakviesti ir su juo kalbėdavosi.'),
  (@b44, 24, 27, 'Bet po dviejų metų Porcijus Festas atėjo į Felikso vietą; ir Feliksas, norėdamas suteikti žydams malonumą, paliko Paulių sulaikytą.'),
  (@b44, 25, 1, 'Na, o kai Festas buvo atėjęs į provinciją, po trijų dienų jis iš Cezarėjos užkilo į Jeruzalę.'),
  (@b44, 25, 2, 'Tada aukščiausiasis kunigas ir žydų vyriausiasis įskundė jam Paulių ir jo maldavo,'),
  (@b44, 25, 3, 'ir prašė malonės jo nenaudai, kad jis pasiųstų jo iškviesti į Jeruzalę, tykodami kelyje jį nužudyti.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b44, 25, 4, 'Bet Festas atsakė, kad Paulius turi būti saugomas Cezarėjoje, ir kad jis pats netrukus ten išvyksiąs.'),
  (@b44, 25, 5, '„Todėl tie, – tarė jis, – kurie tarp jūsų gali, tegul eina su manimi žemyn ir kaltina šį vyrą, jei jame būtų kokia nedorybė“.'),
  (@b44, 25, 6, 'Ir prabuvęs tarp jų daugiau nei dešimt dienų, nuėjo žemyn į Cezarėją; ir ateinančią dieną sėdėdamas teismo krasėje įsakė, kad būtų atvestas Paulius.'),
  (@b44, 25, 7, 'Ir kai jis buvo atėjęs, žydai, atėję žemyn iš Jeruzalės, sustojo aplinkui ir primetė daug bei sunkių kaltinimų prieš Paulių, kurių jie negalėjo įrodyti.'),
  (@b44, 25, 8, 'Tuo tarpu jis už save atsakė: „Nei prieš žydų įstatymą, nei prieš šventyklą ir nei prieš ciesorių aš visiškai niekuo nenusikaltau“.'),
  (@b44, 25, 9, 'Bet Festas, norėdamas padaryti žydams malonumą, atsakė Pauliui ir tarė: „Ar nori eiti aukštyn į Jeruzalę ir ten mano akivaizdoje būti teisiamas dėl šitų dalykų?“'),
  (@b44, 25, 10, 'Tada Paulius tarė: „Aš stoviu prie ciesoriaus teismo krasės, kur turiu būti teisiamas: žydams aš nieko blogo nepadariau, kaip tu labai gerai žinai.'),
  (@b44, 25, 11, 'Nes jei esu nusikaltėlis ar padariau ką nors verto mirties, aš neatsisakau mirti; bet jei nėra nieko, kuo šitie mane kaltina, niekas negali manęs jiems atiduoti. Aš kreipiuosi į ciesorių“.'),
  (@b44, 25, 12, 'Tada Festas, pasitaręs su taryba, atsakė: „Ar kreipiesi į ciesorių? Pas ciesorių eisi“.'),
  (@b44, 25, 13, 'Ir po keleto dienų karalius Agripa ir Bernikė atėjo į Cezarėją pasveikinti Festo.'),
  (@b44, 25, 14, 'Ir jiems ten išbuvus daug dienų, Festas paskelbė karaliui Pauliaus bylą, sakydamas: „Felikso yra paliktas vienas vyras pančiuose,'),
  (@b44, 25, 15, 'kurį, man būnant Jeruzalėje, įskundė vyriausieji kunigai ir žydų vyresnieji, prašydami prieš jį vykdyti teismą.'),
  (@b44, 25, 16, 'Kuriems atsakiau: ‘Tai ne romiečių būdas atiduoti kurį nors žmogų mirti, prieš tai kaltinamajam nesusitikus su kaltintojais akis į akį ir negavus leidimo už save atsakyti dėl primesto jam nusikaltimo.'),
  (@b44, 25, 17, 'Todėl, kai jie buvo čia atėję, nedelsiant rytojaus dieną atsisėdau į teismo krasę ir įsakiau, kad būtų išvestas tas vyras.'),
  (@b44, 25, 18, 'Prieš kurį atsistoję kaltintojai nepateikė jokio kaltinimo tuo, ko tikėjausi;'),
  (@b44, 25, 19, 'bet turėjo prieš jį tam tikrų klausimų apie jų pačių prietarus ir apie tokį Jėzų, kuris buvo miręs, kurį Paulius tvirtino esant gyvą.'),
  (@b44, 25, 20, 'Ir kadangi abejojau dėl tokių klausimų, paklausiau, ar jis norėtų eiti į Jeruzalę ir ten būti dėl šito teisiamas.'),
  (@b44, 25, 21, 'Bet kai Paulius kreipėsi, kad būtų paliktas Augusto svarstymui, aš įsakiau, kad jis būtų saugomas, kol galėsiu jį pasiųsti pas ciesorių“.'),
  (@b44, 25, 22, 'Tada Agripa tarė Festui: „ Aš pats irgi norėčiau išgirsti tą žmogų“. „Rytoj, – jis tarė, – išgirsi jį“.'),
  (@b44, 25, 23, 'Ir rytojaus dieną, kai buvo atėjęs Agripa ir Bernikė su didele puikybe ir buvo įėję į klausymosi vietą su vyriausiais vadais ir viršiausiais miesto vyrais, Festo įsakymu buvo išvestas Paulius.'),
  (@b44, 25, 24, 'Ir Festas tarė: „Karaliau Agripa ir visi, kurie čia esate su mumis, jūs matote šitą vyrą, dėl kurio visa žydų daugybė kreipėsi į mane tiek Jeruzalėje, tiek ir čia, šaukdami, kad jis neturįs ilgiau gyventi.'),
  (@b44, 25, 25, 'Bet kai radau, kad jis nieko nepadarė verto mirties ir kad jis pats kreipėsi į Augustą, nusprendžiau jį pasiųsti.'),
  (@b44, 25, 26, 'Apie kurį neturiu nieko tikro parašyti savo viešpačiui. Todėl jį išvedžiau jūsų akivaizdon, o ypač prieš tave, karaliau Agripa, kad po įvykdytos apklausos turėčiau ką rašyti.'),
  (@b44, 25, 27, 'Nes man atrodo neprotinga siųsti kalinį ir kartu nenurodyti jam priskirtų nusikaltimų“.'),
  (@b44, 26, 1, 'Tada Agripa tarė Pauliui: „Tau leidžiama kalbėti už save“. Tada Paulius ištiesė ranką ir atsakinėjo už save:'),
  (@b44, 26, 2, '„Manau esu laimingas, karaliau Agripa, nes atsakysiu už save šią dieną tavo akivaizdoje dėl visko, kuo esu žydų kaltinamas;'),
  (@b44, 26, 3, 'ypač todėl, kad žinau, jog esi žinovas visų papročių ir klausimų, esančių tarp žydų, todėl maldauju tave kantriai manęs išklausyti.'),
  (@b44, 26, 4, 'Mano gyvenimo būdą nuo jaunystės, kuris pirma buvo mano tautos tarpe Jeruzalėje, pažįsta visi žydai;'),
  (@b44, 26, 5, 'kurie mane pažinojo nuo pradžios, jeigu jie norėtų paliudyti, kad pagal griežčiausią mūsų religijos sektą gyvenau fariziejumi.'),
  (@b44, 26, 6, 'O dabar stoviu ir esu teisiamas dėl vilties pažado, kurį Dievas davė mūsų tėvams;'),
  (@b44, 26, 7, 'to pažado mūsų dvylika genčių, nepaliaujamai tarnaudamos Dievui naktį ir dieną, tikisi ateinant. Dėlei šios vilties, karaliau Agripa, esu kaltinamas žydų.'),
  (@b44, 26, 8, 'Kodėl jums atrodo neįtikėtina, kad Dievas prikelia numirusius?'),
  (@b44, 26, 9, 'Aš iš tikrųjų galvojau savyje, kad turiu daryti daug ką priešingai vardui Jėzaus iš Nazareto.'),
  (@b44, 26, 10, 'Ką ir dariau Jeruzalėje; ir daug šventųjų uždariau į kalėjimą, gavęs įgaliojimą iš vyriausiųjų kunigų; ir kai jie buvo žudomi, aš daviau savo balsą prieš juos.'),
  (@b44, 26, 11, 'Ir juos dažnai baudžiau kiekvienoje sinagogoje bei verčiau juos piktžodžiauti; ir būdamas be galo ant jų supykęs, persekiojau juos netgi iki svetimų miestų.'),
  (@b44, 26, 12, 'Dėl to vykdamas į Damaską su įgaliojimu ir pavedimu nuo vyriausiųjų kunigų,'),
  (@b44, 26, 13, 'vidurdienį, o karaliau, kelyje pamačiau iš dangaus šviesą, skaistesnę už saulės skaistumą, apšviečiančią mane ir tuos, kurie keliavo su manimi.'),
  (@b44, 26, 14, 'Ir kai mes visi buvome nukritę ant žemės, išgirdau balsą, kalbantį man ir tariantį hebrajų kalba: ‘Sauliau, Sauliau, kodėl mane persekioji? Sunku tau spyriotis prieš dyglius’.'),
  (@b44, 26, 15, 'Ir aš tariau: ‘Kas tu esi, Viešpatie?’ O jis tarė: ‘Aš esu Jėzus, kurį tu persekioji.'),
  (@b44, 26, 16, 'Bet kelkis ir stokis ant kojų, nes aš tau pasirodžiau tam, kad padaryčiau tave tarnu ir liudytoju to, ką tu matei, ir to, kame aš tau pasirodysiu,'),
  (@b44, 26, 17, 'išvaduodamas tave iš tautos ir pagonių, pas kuriuos dabar tave siunčiu'),
  (@b44, 26, 18, 'atverti jiems akis ir atgręžti juos nuo tamsybės į šviesą ir nuo šėtono valdžios į Dievą, kad jie gautų nuodėmių atleidimą ir paveldą tarp tų, kurie yra pašvęsti per tikėjimą, kuris yra manyje’.'),
  (@b44, 26, 19, 'Todėl, o karaliau Agripa, aš nebuvau neklusnus tam dangiškajam regėjimui;'),
  (@b44, 26, 20, 'bet apsakiau pirmiausiai tiems iš Damasko ir Jeruzalėje, ir visose Judėjos ribose, ir paskui pagonims, kad jie atgailautų ir gręžtųsi į Dievą bei darytų darbus tinkamus atgailai.'),
  (@b44, 26, 21, 'Dėl šių dalykų žydai pagavo mane šventykloje ir ruošėsi mane nužudyti.'),
  (@b44, 26, 22, 'Todėl gavęs pagalbos iš Dievo, aš tebetęsiu iki šios dienos, liudydamas tiek mažam, tiek dideliam, nesakydamas nieko kito, kaip tik tai, ką pranašai ir Mozė kalbėjo įvyksiant:'),
  (@b44, 26, 23, 'kad Kristus turės kentėti ir kad jis turės būti pirmasis, kuris prisikels iš numirusiųjų ir paskelbs šviesą tautai bei pagonims“.'),
  (@b44, 26, 24, 'Ir kai jis taip kalbėjo už save, Festas tarė garsiu balsu: „Pauliau, tu išprotėjęs; daug mokymosi tave veda iš proto“.'),
  (@b44, 26, 25, 'Bet jis tarė: „Aš nesu išprotėjęs, kilmingiausiasis Festai; bet kalbu tiesos ir blaivumo žodžius.'),
  (@b44, 26, 26, 'Nes apie tai žino karalius, kurio akivaizdoje laisvai ir kalbu; nes esu įsitikinęs, kad nuo jo nieko iš to nėra paslėpto; nes tai neįvyko užkampyje.'),
  (@b44, 26, 27, 'Karaliau Agripa, ar tu tiki pranašais? Žinau, kad tiki“.'),
  (@b44, 26, 28, 'Tada Agripa tarė Pauliui: „Tu mane beveik įtikini tapti krikščionimi“.'),
  (@b44, 26, 29, 'O Paulius tarė: „Aš norėčiau Dievo akivaizdoje, kad ne tik tu, bet ir visi, kurie klausosi manęs šią dieną, būtų ir beveik, ir visiškai tokie kaip aš esu, tik be šitų pančių“.'),
  (@b44, 26, 30, 'Ir kai jis taip pakalbėjo, atsikėlė karalius, valdytojas, Bernikė ir tie, kurie su jais sėdėjo;'),
  (@b44, 26, 31, 'ir nuėję į šoną jie kalbėjosi tarpusavyje, sakydami: „Šitas žmogus nedaro nieko verto mirties ar pančių“.'),
  (@b44, 26, 32, 'Tada Agripa tarė Festui: „Šitą žmogų būtų galima išlaisvinti, jei nebūtų kreipęsis į ciesorių“.'),
  (@b44, 27, 1, 'Ir kai buvo nuspręsta, kad turime plaukti į Italiją, jie atidavė Paulių ir kai kuriuos kitus kalinius tokiam vardu Julijus, Augusto pulko šimtininkui.'),
  (@b44, 27, 2, 'Ir įlipę į Adramitijos laivą, pasileidome nuo kranto, ketindami plaukti palei Azijos ribas; tokiam Aristarchui, makedoniečiui iš Tesalonikos, esant su mumis.'),
  (@b44, 27, 3, 'O rytojaus dieną pasiekėme Sidoną. Ir Julijus pagarbiai elgėsi su Pauliumi ir davė jam laisvę eiti pas savo draugus atsigaivinti.'),
  (@b44, 27, 4, 'O iš ten pasileidę plaukėme Kipro užuovėja, kadangi buvo priešpriešiai vėjai.'),
  (@b44, 27, 5, 'Ir perplaukę Kilikijos ir Pamfilijos jūrą, atvykome į Lykijos miestą Mirą.'),
  (@b44, 27, 6, 'Ir ten šimtininkas rado Aleksandrijos laivą, plaukiantį į Italiją; ir jis mus įsodino į jį.'),
  (@b44, 27, 7, 'Ir kai daug dienų plaukėme palengva, ir vos ne vos atvykę priešais Knidą, vėjui mums neleidžiant, plaukėme Kretos užuovėja priešais Salmonę;'),
  (@b44, 27, 8, 'ir, sunkiai ją aplenkę, atvykome į vietą, vadinamą „Dailūs uostai“, arti kurios buvo Lasėjos miestas.'),
  (@b44, 27, 9, 'Na, o kai buvo praėję daug laiko ir kai plaukiojimas jau buvo pavojingas, kadangi jau buvo praėjęs pasninkas, Paulius juos įspėjo'),
  (@b44, 27, 10, 'ir jiems tarė: „Ponai, matau, kad ši kelionė bus su žala ir dideliu nuostoliu ne vien tik krovinio ir laivo, bet ir mūsų gyvybių“.'),
  (@b44, 27, 11, 'Tačiau šimtininkas tikėjo laivo kapitonu ir šeimininku labiau nei tuo, ką kalbėjo Paulius.'),
  (@b44, 27, 12, 'Ir kadangi uostas nebuvo tinkamas jame žiemoti, didesnė dalis patarė ir iš ten pasitraukti, kad kaip nors galėtų pasiekti Feniką peržiemojimui; kuris yra Kretos uostas ir išsidėstęs link pietvakarių bei šiaurės vakarų.'),
  (@b44, 27, 13, 'Ir kai švelniai pūtė pietų vėjas, manydami, kad pasiekė savo tikslą, iš ten pasileidę jie plaukė arti palei Kretą.'),
  (@b44, 27, 14, 'Bet netrukus priešais ją pakilo audringas vėjas, vadinamas Euroklidonu.'),
  (@b44, 27, 15, 'Ir kai laivas buvo pagautas ir negalėjo pasipriešinti vėjui, mes leidome jį nešti.'),
  (@b44, 27, 16, 'Ir leidžiantis vienos salos, vadinamos Klauda, užuovėja, mes turėjome daug darbo, kad prieitume prie valties,'),
  (@b44, 27, 17, 'kurią jie pakėlę, naudojo pastiprinimą, apjuosdami laivą; ir bijodami, kad neįpultų į slankųjį smėlį, nuleido bures ir taip buvo nešami.'),
  (@b44, 27, 18, 'Ir kai buvome be galo blaškomi audros, rytojaus dieną jie palengvino laivą;'),
  (@b44, 27, 19, 'o trečią dieną savo pačių rankomis išmetėme laivo įrenginius.'),
  (@b44, 27, 20, 'Ir nei saulei, nei žvaigždėms daugelį dienų nesirodant, ir nemažai audrai užgulus ant mūsų, buvo atimta bet kokia viltis, kad būsime išgelbėti.'),
  (@b44, 27, 21, 'Bet po ilgo susilaikymo atsistojo Paulius į jų vidurį ir tarė: „Ponai, jums reikėjo paklausyti manęs ir nesileisti iš Kretos, ir neįgyti šitos žalos bei netekimo.'),
  (@b44, 27, 22, 'Ir dabar raginu jus pralinksmėti, nes tarp jūsų nebus nei vienos gyvybės praradimo, o tiktai laivo.'),
  (@b44, 27, 23, 'Nes šią naktį prie manęs atsistojo angelas Dievo, kurio aš esu ir kuriam tarnauju,'),
  (@b44, 27, 24, 'sakydamas: ‘Nebijok, Pauliau; tu turi būti nugabentas ciesoriaus akivaizdon, ir štai Dievas tau davė visus tuos, kurie plaukia su tavimi’.'),
  (@b44, 27, 25, 'Todėl, ponai, pralinksmėkite, nes tikiu Dievu, kad bus būtent taip, kaip buvo man pasakyta.'),
  (@b44, 27, 26, 'Tačiau turime būti išmesti tam tikroje saloje“.'),
  (@b44, 27, 27, 'Bet kai atėjo keturiolikta naktis, kai buvome Adrijoje nešiojami šen bei ten, apie vidurnaktį laivininkai manė, kad priartėjo prie kažkokios šalies;'),
  (@b44, 27, 28, 'ir išmatavę gylį rado jį dvidešimties jūros sieksnių; ir paplaukę truputį toliau jie vėl išmatavo gylį ir rado jį penkiolikos jūros sieksnių.'),
  (@b44, 27, 29, 'Tada bijodami, kad neužšoktume ant uolų, išmetė iš laivagalio keturis inkarus ir tikėjosi dienos.'),
  (@b44, 27, 30, 'O kai jūreiviai ruošėsi pabėgti iš laivo, nuleidę į jūrą valtį apsimesdami, neva norėtų išmesti inkarus iš laivo pirmgalio,'),
  (@b44, 27, 31, 'Paulius tarė šimtininkui ir kareiviams: „Jei šitie nepasiliks laive, jūs negalite būti išgelbėti“.'),
  (@b44, 27, 32, 'Tuomet kareiviai atkirto nuo valties virves ir leido jai nukristi.'),
  (@b44, 27, 33, 'Ir dienai ateinant, Paulius jų visų maldavo imti maisto, sakydamas: „Ši diena yra keturiolikta diena, kai laukiate ir pasiliekate pasninkaujantys, nieko neimdami.'),
  (@b44, 27, 34, 'Todėl meldžiu jus imti maisto, nes tai yra jūsų sveikatai: nes nei nuo vieno jūsų galvos nenukris nei plaukas“.'),
  (@b44, 27, 35, 'Ir taip pakalbėjęs jis paėmė duoną ir visų jų akivaizdoje padėkojo Dievui; ir ją sulaužęs pradėjo valgyti.'),
  (@b44, 27, 36, 'Tuomet jie visi pralinksmėjo ir taip pat ėmė maisto.'),
  (@b44, 27, 37, 'O laive mūsų visų buvo du šimtai septyniasdešimt šešios sielos.'),
  (@b44, 27, 38, 'Ir užtektinai pavalgę jie palengvino laivą ir išmetė kviečius į jūrą.'),
  (@b44, 27, 39, 'O kai buvo diena, jie nepažino sausumos, bet išvydo vieną nedidelę įlanką su krantu, į kurią jie manė, jei būtų įmanoma, įvaryti laivą.'),
  (@b44, 27, 40, 'Ir pakėlę inkarus patikėjo save jūrai ir atleidę vairo raiščius bei iškėlę didburę į vėją, leidosi į krantą.'),
  (@b44, 27, 41, 'Ir įpuolę į vietą, kur susitinka dvi jūros, jie užvarė laivą ant seklumos; ir priekis tvirtai įstrigo, ir liko nepajudinamas, bet paskuigalis buvo sulaužytas nuo bangų smarkumo.'),
  (@b44, 27, 42, 'O kareivių sumanymas buvo nužudyti kalinius, kad kuris iš jų neišplauktų ir nepabėgtų.'),
  (@b44, 27, 43, 'Bet šimtininkas, norėdamas išgelbėti Paulių, sulaikė juos nuo jų tikslo; ir įsakė, kad tie, kurie gali plaukti, pirmi mestųsi į jūrą ir pasiektų sausumą,'),
  (@b44, 27, 44, 'o likusieji – vieni ant lentų, o kiti ant laivo nuolaužų. Ir taip įvyko, kad visi sveiki išsigelbėjo sausumoje.'),
  (@b44, 28, 1, 'Ir išsigelbėję jie sužinojo, kad sala vadinosi Melita.'),
  (@b44, 28, 2, 'Ir barbarai parodė mums nemažai gerumo, nes jie užkūrė ugnį ir priėmė mus visus dėl esamo lietaus ir dėl šalčio.'),
  (@b44, 28, 3, 'Ir kai Paulius pririnko glėbį pagalių ir uždėjo ant ugnies, iš karščio išėjo angis ir įsikabino jam į ranką.'),
  (@b44, 28, 4, 'Ir barbarai pamatę nuodingą žvėrį, pakibusį jam ant rankos, tarė tarpusavyje: „Be jokių abejonių šitas žmogus yra žmogžudys ir nors jis ir išsigelbėjo iš jūros, tačiau kerštas neleidžia jam gyventi“.'),
  (@b44, 28, 5, 'Bet jis nukratė žvėrį į ugnį ir nieko blogo nepatyrė.'),
  (@b44, 28, 6, 'Tačiau jie žiūrėjo, kada jis turės ištinti arba staiga kristi negyvas; bet ilgai pražiūrėję ir nepamatę jokiam blogiui jį ištinkant, jie pakeitė savo nuomones ir sakė, kad jis yra dievas.'),
  (@b44, 28, 7, 'Tose pačiose vietose buvo nuosavybė viršiausiojo salos žmogaus, vardu Publijus; kuris mus priėmė ir pagarbiai tris dienas apgyvendino.'),
  (@b44, 28, 8, 'Ir įvyko, kad Publijaus tėvas gulėjo sergantis karštine ir kraujingu viduriavimu; pas kurį Paulius įėjo ir meldėsi, ir uždėjo ant jo savo rankas, ir jį išgydė.'),
  (@b44, 28, 9, 'Taigi kai tai atsitiko, atėjo ir kiti, turintys ligas saloje, ir buvo išgydyti;'),
  (@b44, 28, 10, 'kurie taip pat gerbė mus daugeriopa pagarba; ir mums išvykstant, prikrovė mums visko, kas buvo reikalinga.'),
  (@b44, 28, 11, 'O po trijų mėnesių išvykome Aleksandrijos laivu, žiemojusiu toje saloje, kuris turėjo Kastoro ir Polukso ženklą.'),
  (@b44, 28, 12, 'Ir išlipę Sirakūzuose, ten pasilikome tris dienas.'),
  (@b44, 28, 13, 'Ir iš ten plaukėme aplinkui ir atvykome į Regijų, ir po vienos dienos pūtė pietų vėjas, ir rytojaus dieną atvykome į Puteolus,'),
  (@b44, 28, 14, 'kur radome brolius, ir buvome prašomi pasilikti su jais septynias dienas; ir taip vykome Romos link.'),
  (@b44, 28, 15, 'Ir broliai, išgirdę apie mus, iš ten atėjo mūsų pasitikti iki Apijaus Forumo ir Trijų smuklių; kuriuos pamatęs Paulius dėkojo Dievui ir įgavo drąsos.'),
  (@b44, 28, 16, 'Ir kai atvykome į Romą, šimtininkas perdavė kalinius sargybos vadui, bet Pauliui buvo leista gyventi atskirai su kareiviu, kuris jį saugojo.'),
  (@b44, 28, 17, 'Ir įvyko, kad po trijų dienų Paulius sukvietė žydų vyriausiuosius; ir jiems susirinkus jis jiems tarė: „Vyrai ir broliai, nors nieko nepadariau prieš tautą ar mūsų tėvų papročius, tačiau iš Jeruzalės buvau įduotas kaliniu į romiečių rankas.'),
  (@b44, 28, 18, 'Kurie, mane ištardę, norėjo paleisti, nes manyje nebuvo nieko, verto mirties.'),
  (@b44, 28, 19, 'Bet kai žydai tam prieštaravo, aš buvau priverstas kreiptis į ciesorių; ne todėl, kad turėjau kuo nors kaltinti savo tautą.'),
  (@b44, 28, 20, 'Tad dėl šios priežasties pasikviečiau jus, kad jus pamatyčiau ir su jumis kalbėčiau; nes dėl Izraelio vilties esu surakintas šia grandine“.'),
  (@b44, 28, 21, 'O jie tarė jam: „Mes nei laiškų negavome iš Judėjos apie tave, nei kas iš atėjusių brolių pranešė ar kalbėjo ką bloga apie tave.'),
  (@b44, 28, 22, 'Bet norime išgirsti iš tavęs, ką tu galvoji, nes apie šitą sektą žinome, kad visur jai prieštaraujama“.'),
  (@b44, 28, 23, 'Ir kai jie paskyrė jam dieną, daug atėjo pas jį į jo buveinę; kuriems jis nuo ryto iki vakaro dėstė ir liudijo Dievo karalystę, įtikinėdamas juos apie Jėzų tiek iš Mozės įstatymo, tiek iš pranašų.'),
  (@b44, 28, 24, 'Ir vieni tikėjo tuo, kas buvo kalbama, o kiti ne.'),
  (@b44, 28, 25, 'Bet kai jie tarpusavyje nesutarė, jie išėjo po to, kai Paulius pasakė vieną žodį: „Gerai sakė Šventoji Dvasia per pranašą Izaiją mūsų tėvams,'),
  (@b44, 28, 26, 'sakydama: ‘Eik pas šitą tautą ir sakyk: Girdėdami girdėsite, bet nesuprasite; ir žiūrėdami žiūrėsite, bet nepastebėsite;'),
  (@b44, 28, 27, 'nes šios tautos širdis nutuko, ir jų ausys sunkiai girdi, ir jie užmerkė savo akis, kad nepamatytų savo akimis ir neišgirstų savo ausimis, ir nesuprastų savo širdimi, ir neatsiverstų, ir aš jų neišgydyčiau’.'),
  (@b44, 28, 28, 'Todėl tebūna jums žinoma, kad šis Dievo išgelbėjimas yra pasiųstas pagonims, ir jie jo klausysis“.'),
  (@b44, 28, 29, 'Ir jam pasakius tuos žodžius, žydai išėjo ir daug samprotavo tarpusavyje.'),
  (@b44, 28, 30, 'Ir Paulius ištisus dvejus metus gyveno savo išsinuomotame name ir priimdavo visus, kurie ateidavo pas jį,'),
  (@b44, 28, 31, 'skelbdamas Dievo karalystę ir mokydamas to, kas apie Viešpatį Jėzų Kristų, su pilnu pasitikėjimu, niekam jam nedraudžiant.'),
  (@b45, 1, 1, 'Paulius, Jėzaus Kristaus tarnas, pašauktas būti apaštalu, atskirtas Dievo evangelijai'),
  (@b45, 1, 2, '(kurią jis anksčiau buvo pažadėjęs per savo pranašus šventuosiuose Raštuose)'),
  (@b45, 1, 3, 'apie jo Sūnų Jėzų Kristų, mūsų Viešpatį, kuris pagal kūną buvo padarytas iš Dovydo sėklos'),
  (@b45, 1, 4, 'ir pagal šventumo Dvasią paskelbtas Dievo Sūnumi su jėga per prisikėlimą iš numirusių,'),
  (@b45, 1, 5, 'per kurį gavome malonę ir apaštalystę dėl klusnumo tikėjimui tarp visų tautų, dėlei jo vardo,'),
  (@b45, 1, 6, 'tarp kurių ir jūs esate Jėzaus Kristaus pašauktieji.'),
  (@b45, 1, 7, 'Visiems, esantiems Romoje, Dievo mylimiesiems, pašauktiems būti šventaisiais: malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir Viešpaties Jėzaus Kristaus.'),
  (@b45, 1, 8, 'Pirmiausiai dėkoju savo Dievui per Jėzų Kristų už jus visus, kad apie jūsų tikėjimą kalbama visame pasaulyje.'),
  (@b45, 1, 9, 'Nes Dievas, kuriam tarnauju savo dvasia jo Sūnaus evangelijoje, yra mano liudytojas, kad be paliovos visuomet miniu jus savo maldose,'),
  (@b45, 1, 10, 'prašydamas, kad pagaliau jau kaip nors sėkmingai atvykčiau pas jus Dievo valia.'),
  (@b45, 1, 11, 'Nes trokštu jus pamatyti, idant galėčiau jums duoti kokią dvasinę dovaną tam, kad būtumėte sutvirtinti,'),
  (@b45, 1, 12, 'tai yra, kad kartu su jumis pasiguosčiau bendru jūsų ir mano tikėjimu.'),
  (@b45, 1, 13, 'Nenoriu gi, broliai, kad būtumėte nežinantys, jog daug kartų ketinau ateiti pas jus (bet ligi šiolei buvau sukliudytas), kad ir tarp jūsų turėčiau šiek tiek vaisių, kaip ir tarp kitų pagonių.'),
  (@b45, 1, 14, 'Esu skolininkas tiek graikams, tiek barbarams, tiek išmintingiems, tiek neišmintingiems.'),
  (@b45, 1, 15, 'Taigi kiek manyje yra, esu pasiruošęs skelbti evangeliją ir jums, esantiems Romoje.'),
  (@b45, 1, 16, 'Nes aš nesigėdiju Kristaus evangelijos, nes ji yra Dievo jėga išgelbėjimui – kiekvienam, kuris tiki; pirma žydui ir taip pat graikui.'),
  (@b45, 1, 17, 'Nes joje apreikštas Dievo teisumas iš tikėjimo į tikėjimą; kaip yra parašyta: „Teisusis gyvens tikėjimu“.'),
  (@b45, 1, 18, 'Nes Dievo rūstybė apreikšta iš dangaus prieš kiekvieną bedievystę ir neteisumą žmonių, kurie tiesą užgniaužia neteisumu;'),
  (@b45, 1, 19, 'todėl kad tai, kas gali būti žinoma apie Dievą, juose yra apreikšta, nes Dievas jiems tai parodė.'),
  (@b45, 1, 20, 'Nes neregimi jo dalykai – jo amžinoji jėga ir Dievystė – yra aiškiai matomi nuo pasaulio sutvėrimo, suprantami pagal tai, kas padaryta, todėl jie nepateisinami;'),
  (@b45, 1, 21, 'nes pažinę Dievą, jie nešlovino jo kaip Dievo nei buvo dėkingi; bet tapo tušti savo sumanymais, ir jų kvaila širdis aptemo.'),
  (@b45, 1, 22, 'Dėdamiesi esą išmintingi, jie tapo kvaili'),
  (@b45, 1, 23, 'ir negendančio Dievo šlovę iškeitė į atvaizdą, panašų į gendančio žmogaus, paukščių, keturkojų žvėrių ir ropojančių būtybių.'),
  (@b45, 1, 24, 'Todėl ir Dievas per jų pačių širdžių geidulius paliko juos nešvarumui, kad tarpusavyje gėdintų savo pačių kūnus;'),
  (@b45, 1, 25, 'kurie Dievo tiesą iškeitė į melą ir garbino bei tarnavo sutvėrimui daugiau negu Kūrėjui, kuris yra palaimintas per amžius. Amen.'),
  (@b45, 1, 26, 'Todėl Dievas paliko juos bjaurioms aistroms; nes netgi jų moterys iškeitė prigimtinę paskirtį į tą, kuri yra priešinga prigimčiai;'),
  (@b45, 1, 27, 'taip pat ir vyrai, palikę prigimtinę moters paskirtį, degė geiduliais vienas kitam: vyrai su vyrais darydami tai, kas nepridera, ir už savo nuklydimą gaudami savyje tą atlygį, kuris tinkamas.'),
  (@b45, 1, 28, 'Ir kaip jie savo pažinime nenorėjo išlaikyti Dievo, Dievas perdavė juos netikusiamprotui, daryti tai, kas nėra tinkama;'),
  (@b45, 1, 29, 'būdami pripildyti visokio neteisumo, paleistuvystės, nedorumo, godulystės, piktavališkumo; kupini pavydo, žmogžudystės, ginčų, suktybės, pagiežingumo; šnabždūnai,'),
  (@b45, 1, 30, 'šmeižikai, nekenčiantys Dievo, pikti, išdidūs, pagyrūnai, išradėjai to, kas pikta, neklusnūs tėvams,'),
  (@b45, 1, 31, 'be supratimo, sandorų laužytojai, be prigimtinio prieraišumo, nesutaikomi, negailestingi;'),
  (@b45, 1, 32, 'kurie, žinodami Dievo teismą, kad visa tai darantys yra verti mirties, ne tik tą daro, bet ir mėgaujasi tais, kurie tai daro.'),
  (@b45, 2, 1, 'Todėl esi nepateisinamas, kas bebūtum, o žmogau, kuris teisi, nes kuo teisi kitą, tuo pasmerki save; nes tu, kuris teisi, darai tą patį.'),
  (@b45, 2, 2, 'Bet mes tikri, kad Dievo teismas yra pagal tiesą prieš tuos, kurie tokius dalykus daro.'),
  (@b45, 2, 3, 'Ir manai, o žmogau, kuris teisi tai darančius ir darai tą patį, kad išvengsi Dievo teismo?'),
  (@b45, 2, 4, 'Arba, ar niekinsi jo gerumo ir susilaikymo bei ilgo pakantumo turtus, nežinodamas, kad Dievo gerumas veda tave į atgailą?'),
  (@b45, 2, 5, 'Bet savo užkietėjimu ir neatgailaujančia širdimi kaupi sau rūstybę rūstybės ir Dievo teisaus teismo apreiškimo dienai;'),
  (@b45, 2, 6, 'kuris atmokės kiekvienam pagal jo darbus:'),
  (@b45, 2, 7, 'tiems, kurie kantriai nuolatos darydami gera, ieško šlovės ir garbės, ir nemirtingumo, – amžinuoju gyvenimu,'),
  (@b45, 2, 8, 'bet tiems, kurie ginčijasi ir nepaklūsta tiesai, bet paklūsta neteisumui, – pasipiktinimu ir rūstybe;'),
  (@b45, 2, 9, 'suspaudimas ir kančia kiekvienai sielai žmogaus, kuris daro pikta, pirma žydo ir taip pat pagonies;'),
  (@b45, 2, 10, 'bet šlovė, garbė ir ramybė kiekvienam, kuris daro gera – pirma žydui ir taip pat pagoniui,'),
  (@b45, 2, 11, 'nes Dievas neatsižvelgia į asmenis.'),
  (@b45, 2, 12, 'Nes tie, kurie nusidėjo be įstatymo, be įstatymo ir pražus; ir tie, kurie nusidėjo įstatyme, bus teisiami pagal įstatymą'),
  (@b45, 2, 13, '(nes ne įstatymo klausytojai teisūs Dievo akivaizdoje, bet įstatymo vykdytojai bus išteisinti.'),
  (@b45, 2, 14, 'Nes kai pagonys, neturintys įstatymo, iš prigimties daro tai, kas yra įstatyme, tai šitie, neturėdami įstatymo, yra patys sau įstatymas;'),
  (@b45, 2, 16, 'tą dieną, kai Dievas teis žmonių paslaptis per Jėzų Kristų pagal mano evangeliją.'),
  (@b45, 2, 17, 'Štai tu vadiniesi žydu ir remiesi įstatymu, ir giriesi Dievu,'),
  (@b45, 2, 18, 'ir žinai jo valią, ir iš įstatymo pamokytas išmėgini tai, kas geriausia;'),
  (@b45, 2, 19, 'ir įsitikinęs, kad esi aklųjų vedlys, šviesa esančiųjų tamsoje,'),
  (@b45, 2, 20, 'kvailųjų auklėtojas, kūdikių mokytojas, įstatyme turįs pažinimo ir tiesos pavidalą.'),
  (@b45, 2, 21, 'Todėl tu, kuris mokai kitą, ar savęs nepamokai? Tu, kuris skelbi nevogti, ar vagi?'),
  (@b45, 2, 22, 'Tu, kuris sakai nesvetimauti, ar svetimauji? Tu, kuris bjauriesi stabais, ar šventvagiauji?'),
  (@b45, 2, 23, 'Tu, kuris giriesi įstatymu, ar darai negarbę Dievui laužydamas įstatymą?'),
  (@b45, 2, 24, 'Nes per jus piktžodžiaujama Dievo vardui tarp pagonių, kaip yra parašyta.'),
  (@b45, 2, 25, 'Nes apipjaustymas iš tiesų naudingas, jei laikaisi įstatymo, bet jei esi įstatymo laužytojas, tavo apipjaustymas tapo neapipjaustymu.'),
  (@b45, 2, 26, 'Todėl jei neapipjaustymas laikosi įstatymo teisumo, argi jo neapipjaustymas nebus užskaitytas apipjaustymu?'),
  (@b45, 2, 27, 'Ir pagal prigimtį neapipjaustymas, jei jis vykdo įstatymą, argi neteis tavęs, nusižengiančio įstatymui pagal raidę ir apipjaustymą?'),
  (@b45, 2, 28, 'Nes ne tas yra žydas, kuris toks yra išoriškai, nei apipjaustymas yra tas, kuris yra išoriškas kūne;'),
  (@b45, 2, 29, 'bet tas yra žydas, kuris toks yra viduje; ir apipjaustymas yra tas širdies, dvasioje, o ne raidėje; kurio gyrius ne iš žmonių, bet iš Dievo.'),
  (@b45, 2, 15, 'kurie parodo įstatymo darbą, įrašytą jų širdyse, ir jų sąžinė paliudija, ir jų mintys tuo tarpu kaltina arba pateisina viena kitą)'),
  (@b45, 3, 1, 'Kokį tada pranašumą turi žydas? Arba kokia nauda iš apipjaustymo?'),
  (@b45, 3, 2, 'Didelį, visokeriopai: svarbiausia tai, kad jiems buvo patikėti Dievo pasakymai.'),
  (@b45, 3, 3, 'O kas, jei kai kurie netikėjo? Ar jų netikėjimas padarys Dievo tikėjimą neveiksmingą?'),
  (@b45, 3, 4, 'Jokiu būdu! Taip, Dievas tebūna teisingas, bet kiekvienas žmogus – melagis; kaip yra parašyta: „Kad tu būtumei išteisintas savo pasakymais ir laimėtumei, kai esi teisiamas“.'),
  (@b45, 3, 5, 'Bet jei mūsų neteisumas giria Dievo teisumą, ką sakysime? Ar neteisus Dievas, kuris kerštauja? (Kalbu kaip žmogus).'),
  (@b45, 3, 6, 'Jokiu būdu! Nes kaip tada Dievas teis pasaulį?'),
  (@b45, 3, 7, 'Nes jei Dievo tiesa per mano melą dar labiau pagausėjo jo šlovei, kodėl aš dar esu ir teisiamas kaip nusidėjėlis?'),
  (@b45, 3, 8, 'Ir ar neverčiau (kaip esame šmeižiami, ir kaip kai kurie tvirtina mus sakant) „darykime pikta, kad išeitų gera“? Tokių pasmerkimas yra teisingas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b45, 3, 9, 'Ką tuomet? Ar esame geresni už juos? Ne, jokiu būdu! Nes prieš tai įrodėme, kad tiek žydai, tiek pagonys – jie visi yra nuodėmės valdžioje;'),
  (@b45, 3, 10, 'kaip yra parašyta: „Nėra teisaus, ne, nei vieno;'),
  (@b45, 3, 11, 'nėra kas suprastų, nėra, kas ieškotų Dievo.'),
  (@b45, 3, 12, 'Jie visi nuėję nuo kelio, jie kartu tapo nenaudingi; nėra, kas darytų gera, ne, nei vieno.'),
  (@b45, 3, 13, 'Jų gerklė – atviras kapas; savo liežuviais jie apgaudinėjo; gyvačių nuodai po jų lūpomis;'),
  (@b45, 3, 14, 'jų burna pilna keiksmo ir kartumo;'),
  (@b45, 3, 15, 'jų kojos greitos kraują išlieti,'),
  (@b45, 3, 16, 'sunaikinimas ir kančia jų keliuosè,'),
  (@b45, 3, 17, 'ir taikos kelio jie nepažino;'),
  (@b45, 3, 18, 'prieš jų akis nėra Dievo baimės“.'),
  (@b45, 3, 19, 'Žinome gi, kad ką besako įstatymas, jis sako tiems, kurie yra įstatymo valdžioje, kad užsičiauptų kiekviena burna, ir visas pasaulis taptų kaltas prieš Dievą.'),
  (@b45, 3, 20, 'Todėl įstatymo darbais jo akyse nebus išteisintas joks kūnas, nes per įstatymą yra nuodėmės pažinimas.'),
  (@b45, 3, 21, 'Bet dabar be įstatymo yra apreikštas Dievo teisumas, paliudytas įstatymo ir pranašų,'),
  (@b45, 3, 22, 'tai yra, Dievo teisumas per Jėzaus Kristaus tikėjimą visiems ir ant visų tų, kurie tiki; nes nėra jokio skirtumo,'),
  (@b45, 3, 23, 'nes visi nusidėjo ir stokoja Dievo šlovės;'),
  (@b45, 3, 24, 'išteisinami dovanai jo malone per atpirkimą, kuris yra Kristuje Jėzuje,'),
  (@b45, 3, 25, 'kurį Dievas išstatė būti numaldymu per tikėjimą jo krauju, kad paskelbtų savo teisumą dėl praeities nuodėmių atleidimo per Dievo pakantumą;'),
  (@b45, 3, 26, 'kad paskelbtų, sakau, savo teisumą šiuo laiku, kad jis būtų teisus ir išteisintojas to, kuris tiki Jėzumi.'),
  (@b45, 3, 27, 'Kurgi tada gyrimasis? Jis pašalintas. Kokiu įstatymu? Darbų? Ne; tikėjimo įstatymu.'),
  (@b45, 3, 28, 'Todėl darome išvadą, kad žmogus išteisinamas tikėjimu be įstatymo darbų.'),
  (@b45, 3, 29, 'Ar jis tik žydų Dievas? Argi jis nėra ir pagonių? Taip, ir pagonių;'),
  (@b45, 3, 30, 'kadangi yra vienas Dievas, kuris tikėjimu išteisins apipjaustymą ir per tikėjimą – neapipjaustymą.'),
  (@b45, 3, 31, 'Tad ar per tikėjimą panaikiname įstatymą? Jokiu būdu! Iš tikrųjų, mes įtvirtiname įstatymą.'),
  (@b45, 4, 1, 'Ką gi, tuomet pasakysime, Abraomas, mūsų tėvas, pagal kūną atrado?'),
  (@b45, 4, 2, 'Nes jei Abraomas buvo išteisintas darbais, jis turi kuo pasigirti, bet ne prieš Dievą.'),
  (@b45, 4, 3, 'Nes ką gi sako Raštas? „Abraomas patikėjo Dievu, ir tai jam buvo įskaityta teisumu“.'),
  (@b45, 4, 4, 'Tam gi, kuris dirba, atlygis nepriskiriamas iš malonės, bet iš skolos.'),
  (@b45, 4, 5, 'Tačiau tam, kuris nedirba, bet tiki į tą, kuris išteisina bedievį, jo tikėjimas įskaitomas teisumu.'),
  (@b45, 4, 6, 'Kaip ir Dovydas apibūdina palaiminimą žmogaus, kuriam Dievas priskiria teisumą be darbų,'),
  (@b45, 4, 7, 'sakydamas: „Palaiminti tie, kurių neteisybės atleistos ir kurių nuodėmės uždengtos.'),
  (@b45, 4, 8, 'Palaimintas žmogus, kuriam Viešpats neįskaitys nuodėmės“.'),
  (@b45, 4, 9, 'Tad ar šis palaiminimas ateina tik ant apipjaustymo, ar taip pat ir ant neapipjaustymo? Nes sakome, kad Abraomui tikėjimas buvo įskaitytas teisumu.'),
  (@b45, 4, 10, 'Tad kaipgi jis buvo įskaitytas? Kai jis buvo apipjaustyme ar neapipjaustyme? Ne apipjaustyme, bet neapipjaustyme.'),
  (@b45, 4, 11, 'Ir jis gavo apipjaustymo ženklą, antspaudą teisumo to tikėjimo, kurį jis turėjo dar būdamas neapipjaustytas, kad jis būtų tėvas visų tų, kurie tiki, nors jie ir nebūtų apipjaustyti; kad ir jiems būtų įskaitytas teisumas;'),
  (@b45, 4, 12, 'ir tėvas apipjaustymo tiems, kurie ne tik iš apipjaustymo, bet ir vaikšto mūsų tėvo Abraomo pėdomis to tikėjimo, kurį jis turėjo dar būdamas neapipjaustytas.'),
  (@b45, 4, 13, 'Nes pažadas, kad jis būsiąs pasaulio paveldėtojas, nebuvo Abraomui arba jo sėklai per įstatymą, bet per tikėjimo teisumą.'),
  (@b45, 4, 14, 'Nes jei paveldėtojai tie, kurie yra iš įstatymo, tai tikėjimas tapo tuščias, ir pažadas tapo neveiksmingas;'),
  (@b45, 4, 15, 'nes įstatymas gamina rūstybę; nes kur nėra įstatymo, ten nėra nusižengimo.'),
  (@b45, 4, 16, 'Todėl jis yra iš tikėjimo, kad jis būtų per malonę, tam, kad pažadas būtų tvirtas visai sėklai; ne tik tai, kuri yra iš įstatymo, bet ir tai, kuri yra iš tikėjimo Abraomo, kuris yra visų mūsų tėvas'),
  (@b45, 4, 17, '(kaip yra parašyta: „Aš padariau tave daugelio tautų tėvu“) prieš tą, kuriuo jis patikėjo, tai yra, Dievą, kuris atgaivina mirusiuosius ir pašaukia tai, ko nėra, tarsi tai būtų.'),
  (@b45, 4, 18, 'Kuris prieš viltį tikėjo viltimi, kad taptų daugelio tautų tėvu pagal tai, kas buvo pasakyta: „Tokia bus tavo sėkla“.'),
  (@b45, 4, 19, 'Ir nebūdamas silpnas tikėjimu, jis neatsižvelgė į savo jau mirusį kūną, kai buvo apie šimto metų, nei į Saros įsčių negyvumą;'),
  (@b45, 4, 20, 'jis neabejojo Dievo pažadu per netikėjimą; bet buvo stiprus tikėjimu, duodamas Dievui šlovę;'),
  (@b45, 4, 21, 'ir būdamas pilnai įsitikinęs, kad tai, ką jis pažadėjo, jis pajėgus ir įvykdyti.'),
  (@b45, 4, 22, 'Ir todėl tai jam buvo įskaityta teisumu.'),
  (@b45, 4, 23, 'Na, o tai buvo parašyta ne jo vieno dėlei, kad tai jam buvo įskaityta;'),
  (@b45, 4, 24, 'bet ir dėl mūsų, kuriems tai bus įskaityta, jei tikime į tą, kuris prikėlė iš numirusiųjų Jėzų, mūsų Viešpatį;'),
  (@b45, 4, 25, 'kuris buvo atiduotas už mūsų nusikaltimus ir buvo prikeltas dėl mūsų išteisinimo.'),
  (@b45, 5, 1, 'Todėl, būdami išteisinti tikėjimu, mes turime taiką su Dievu per mūsų Viešpatį Jėzų Kristų,'),
  (@b45, 5, 2, 'per kurį tikėjimu turime ir priėjimą į šią malonę, kurioje stovime ir džiaugiamės Dievo šlovės viltyje.'),
  (@b45, 5, 3, 'Ir ne vien tai, bet dar giriamės ir suspaudimuose, žinodami, kad suspaudimas gamina kantrybę;'),
  (@b45, 5, 4, 'o kantrybė – patirtį; o patirtis – viltį:'),
  (@b45, 5, 5, 'o viltis negėdina, nes Dievo meilė yra išlieta mūsų širdyse per Šventąją Dvasią, kuri mums duota.'),
  (@b45, 5, 6, 'Nes kai dar buvome bejėgiai, Kristus tinkamu laiku mirė už bedievius.'),
  (@b45, 5, 7, 'Nes vargu ar kas mirtų už teisų žmogų, tačiau už gerą žmogų galbūt kas ir išdrįstų numirti.'),
  (@b45, 5, 8, 'Bet Dievas mums įrodo savo meilę tuo, kad, kol dar buvome nusidėjėliai, Kristus mirė už mus.'),
  (@b45, 5, 9, 'Tai dar daugiau, dabar būdami išteisinti jo krauju, per jį būsime išgelbėti nuo rūstybės.'),
  (@b45, 5, 10, 'Nes jei dar būdami priešai buvome sutaikyti su Dievu jo Sūnaus mirtimi, tai dar daugiau – būdami sutaikyti mes būsime išgelbėti jo gyvenimu.'),
  (@b45, 5, 11, 'Ir ne tik tai, bet taip pat džiaugiamės Dievu per mūsų Viešpatį Jėzų Kristų, per kurį dabar gavome sutaikinimą.'),
  (@b45, 5, 12, 'Todėl kaip per vieną žmogų nuodėmė įėjo į pasaulį, o per nuodėmę – mirtis; ir taip mirtis perėjo į visus žmones, nes visi nusidėjo'),
  (@b45, 5, 13, '(nes iki įstatymo nuodėmė buvo pasaulyje, bet nuodėmė neįskaitoma, kai nėra įstatymo.'),
  (@b45, 5, 14, 'Vis dėlto mirtis viešpatavo nuo Adomo iki Mozės net tiems, kurie nenusidėjo nusižengimu, panašiu į Adomo, kuris yra provaizdis to, kuris turėjo ateiti.'),
  (@b45, 5, 15, 'Bet ne kaip nusikaltimas, taip ir nemokama dovana. Nes jei per vieno nusikaltimą daugelis yra mirę, dar daugiau Dievo malonė ir dovana per malonę, esanti per vieną žmogų, Jėzų Kristų, pagausėjo daugeliui.'),
  (@b45, 5, 16, 'Ir ne taip, kaip per vieną, kuris nusidėjo, yra dovana; nes teismas per vieną buvo į pasmerkimą, bet nemokama dovana yra iš daugelio nusikaltimų į išteisinimą.'),
  (@b45, 5, 17, 'Nes jei per vieno žmogaus nusikaltimą mirtis viešpatavo per vieną; tai dar daugiau tie, kurie gauna malonės ir teisumo dovanos perteklių, viešpataus gyvenime per vieną, Jėzų Kristų).'),
  (@b45, 5, 18, 'Todėl kaip per vieno nusikaltimą teismas atėjo ant visų žmonių pasmerkimui, taip per vieno teisumą nemokama dovana atėjo ant visų žmonių gyvenimo išteisinimui.'),
  (@b45, 5, 19, 'Nes kaip per vieno žmogaus neklusnumą daugelis tapo nusidėjėliai, taip per vieno klusnumą daugelis taps teisūs.'),
  (@b45, 5, 20, 'Be to, įstatymas įėjo, kad pagausėtų nusikaltimas. Bet kur pagausėjo nuodėmė, daug daugiau pagausėjo malonė;'),
  (@b45, 5, 21, 'kad kaip nuodėmė viešpatavo mirties link, taip malonė per teisumą viešpatautų amžinojo gyvenimo link, per Jėzų Kristų, mūsų Viešpatį.'),
  (@b45, 6, 1, 'Tad ką gi sakysime? Ar mums pasilikti nuodėmėje, kad pagausėtų malonė?'),
  (@b45, 6, 2, 'Jokiu būdu! Kaipgi mes, kurie esame mirę nuodėmei, toliau joje gyvensime?'),
  (@b45, 6, 3, 'Ar nežinote, kad visi mes, kurie buvome pakrikštyti į Jėzų Kristų, buvome pakrikštyti į jo mirtį?'),
  (@b45, 6, 4, 'Todėl krikštu esame su juo palaidoti į mirtį, kad kaip Kristus buvo prikeltas iš numirusiųjų Tėvo šlove, taip ir mes vaikščiotume gyvenimo naujume.'),
  (@b45, 6, 5, 'Nes jei buvome kartu pasodinti jo mirties panašume, tai būsime ir jo prisikėlimo panašume;'),
  (@b45, 6, 6, 'žinodami tai, kad mūsų senasis žmogus su juo nukryžiuotas, kad nuodėmės kūnas būtų sunaikintas, kad nuo šiol nebetarnautume nuodėmei.'),
  (@b45, 6, 7, 'Nes kas yra miręs, tas išlaisvintas iš nuodėmės.'),
  (@b45, 6, 8, 'Na, o jei esame mirę su Kristumi, tikime, kad ir gyvensime su juo:'),
  (@b45, 6, 9, 'žinodami, kad Kristus, prikeltas iš numirusiųjų, nebemiršta; mirtis jam nebeviešpatauja.'),
  (@b45, 6, 10, 'Nes kad jis numirė, tai numirė nuodėmei vieną kartą; o kad jis gyvena, tai gyvena Dievui.'),
  (@b45, 6, 11, 'Taip pat ir jūs laikykite save iš tikrųjų mirusiais nuodėmei, bet gyvais Dievui per Jėzų Kristų, mūsų Viešpatį.'),
  (@b45, 6, 12, 'Todėl teneviešpatauja nuodėmė jūsų mirtingame kūne, kad jai paklustumėte jo geismuose.'),
  (@b45, 6, 13, 'Nei nepaduokite nuodėmei savo narių kaip neteisumo įrankių; bet paduokite save Dievui kaip gyvus iš numirusiųjų ir savo narius kaip teisumo įrankius Dievui.'),
  (@b45, 6, 14, 'Nes nuodėmė jums neviešpataus, nes esate ne įstatymo, bet malonės valdžioje.'),
  (@b45, 6, 15, 'Ką tuomet? Ar darysime nuodėmes, kadangi esame ne įstatymo valdžioje, bet malonės valdžioje? Jokiu būdu!'),
  (@b45, 6, 16, 'Ar nežinote, kad kam paduodate save tarnais paklusti, esate tarnai to, kuriam paklūstate; ar tai nuodėmės – link mirties, ar klusnumo – link teisumo?'),
  (@b45, 6, 17, 'Bet ačiū Dievui, kad buvote nuodėmės tarnai, tačiau iš širdies paklusote tam mokslo pavidalui, kuris buvo jums įteiktas.'),
  (@b45, 6, 18, 'Tad būdami išlaisvinti iš nuodėmės, tapote teisumo tarnais.'),
  (@b45, 6, 19, 'Kalbu žmogiškai dėl jūsų kūno negalios; nes kaip padavėte savo narius tarnais nešvarumui ir neteisybei – link neteisybės, taip dabar paduokite savo narius tarnais teisumui – link šventumo.'),
  (@b45, 6, 20, 'Nes kai buvote nuodėmės tarnai, buvote laisvi nuo teisumo.'),
  (@b45, 6, 21, 'Kokį vaisių tada turėjote tame, ko dabar gėdijatės? Nes anų dalykų galas – mirtis.'),
  (@b45, 6, 22, 'Bet dabar, išlaisvinti iš nuodėmės ir tapę tarnais Dievui, jūs turite savo vaisių link šventumo, ir pabaigą – amžinąjį gyvenimą.'),
  (@b45, 6, 23, 'Nes nuodėmės uždarbis – mirtis; bet Dievo dovana – amžinasis gyvenimas per Jėzų Kristų, mūsų Viešpatį.'),
  (@b45, 7, 1, 'Ar nežinote, broliai (nes kalbu žinantiems įstatymą), kad įstatymas viešpatauja žmogui tol, kol jis gyvena?'),
  (@b45, 7, 2, 'Nes moteris, turinti vyrą, įstatymu surišta su savo vyru tol, kol jis gyvena; bet jei vyras miręs, ji yra išlaisvinta nuo savo vyro įstatymo.'),
  (@b45, 7, 3, 'Todėl, jei ji bus ištekėjusi už kito vyro, kol dar gyvena jos vyras, ji bus vadinama svetimautoja; bet jei jos vyras miręs, ji yra laisva nuo to įstatymo; taigi ji nėra svetimautoja, nors ji ir ištekėjusi už kito vyro.'),
  (@b45, 7, 4, 'Todėl, mano broliai, jūs irgi tapote mirusiais įstatymui per Kristaus kūną; kad būtumėte ištekėję už kito, už to, kuris prikeltas iš numirusiųjų, kad neštume vaisių Dievui.'),
  (@b45, 7, 5, 'Nes kai buvome kūne, nuodėmių paskatos, kurios buvo per įstatymą, veikė mūsų nariuose, kad duotų vaisių mirčiai.'),
  (@b45, 7, 6, 'Bet dabar esame išvaduoti iš įstatymo, kad būdami mirę tame, kame buvome laikomi, idant tarnautume dvasios naujume, o ne raidės senume.'),
  (@b45, 7, 7, 'Ką tuomet sakysime? Ar įstatymas nuodėmė? Jokiu būdu! Ne, aš nebūčiau pažinęs nuodėmės, kaip tik per įstatymą; nes nebūčiau pažinęs geismo, jei įstatymas nebūtų sakęs: „Negeisk!“'),
  (@b45, 7, 8, 'Bet nuodėmė, pasinaudodama proga per įsakymą, gamino manyje visokeriopą geidulį. Nes be įstatymo nuodėmė buvo mirusi.'),
  (@b45, 7, 9, 'Nes kartą buvau gyvas be įstatymo, bet kai atėjo įsakymas, atgijo nuodėmė, ir aš miriau.'),
  (@b45, 7, 10, 'Ir įsakymą, kuris buvo skirtas gyvenimui, radau esantį link mirties.'),
  (@b45, 7, 11, 'Nes nuodėmė pasinaudodama proga per įsakymą mane apgavo ir per jį mane nužudė.'),
  (@b45, 7, 12, 'Todėl įstatymas yra šventas, ir įsakymas šventas ir teisingas, ir geras.'),
  (@b45, 7, 13, 'Ar tuomet tai, kas yra gera, man tapo mirtimi? Jokiu būdu! Bet nuodėmė, kad pasirodytų nuodėme, gamindama manyje mirtį per tai, kas yra gera, kad nuodėmė per įsakymą taptų be galo nuodėminga.'),
  (@b45, 7, 14, 'Nes žinome, kad įstatymas yra dvasiškas, bet aš esu kūniškas, parduotas nuodėmės valdžiai.'),
  (@b45, 7, 15, 'Nes nesuprantu, ką darau; nes ko noriu, to nedarau; bet ko nekenčiu, tai darau.'),
  (@b45, 7, 16, 'Tad jei darau tai, ko nenoriu, pritariu įstatymui, kad jis geras.'),
  (@b45, 7, 17, 'Taigi dabar nebe aš tai darau, bet nuodėmė, gyvenanti manyje.'),
  (@b45, 7, 18, 'Nes žinau, kad manyje (tai yra mano kūne) negyvena nieko gero; nes noras yra šalia manęs, o kaip vykdyti gera, aš nerandu.'),
  (@b45, 7, 19, 'Nes gero, kurio noriu, nedarau; o pikta, kurio nenoriu, tą darau.'),
  (@b45, 7, 20, 'Na, o jei darau tai, ko nenoriu, tai nebe aš tai darau, bet nuodėmė, gyvenanti manyje.'),
  (@b45, 7, 21, 'Tuomet randu įstatymą, kad, kai noriu daryti gera, pikta yra šalia manęs.'),
  (@b45, 7, 22, 'Nes aš žaviuosi Dievo įstatymu pagal vidinį žmogų;'),
  (@b45, 7, 23, 'bet savo nariuose matau kitą įstatymą, kovojantį prieš mano proto įstatymą ir atvedantį mane į nelaisvę nuodėmės įstatymui, esančiam mano nariuose.'),
  (@b45, 7, 24, 'Vargšas aš žmogus! Kas mane išvaduos iš šitos mirties kūno?'),
  (@b45, 7, 25, 'Dėkoju Dievui per Jėzų Kristų, mūsų Viešpatį. Taip tad aš pats protu tarnauju Dievo įstatymui, bet kūnu – nuodėmės įstatymui.'),
  (@b45, 8, 1, 'Todėl dabar nėra pasmerkimo tiems, kurie yra Kristuje Jėzuje, kurie vaikšto ne pagal kūną, bet pagal Dvasią.'),
  (@b45, 8, 2, 'Nes gyvenimo Kristuje Jėzuje Dvasios įstatymas išlaisvino mane iš nuodėmės ir mirties įstatymo.'),
  (@b45, 8, 3, 'Nes ko įstatymas negalėjo padaryti, kadangi buvo silpnas per kūną, tai Dievas, atsiuntęs savo Sūnų nuodėmingo kūno panašumu ir už nuodėmę, pasmerkė nuodėmę kūne:'),
  (@b45, 8, 4, 'kad įstatymo teisumas išsipildytų mumyse, vaikštančiuose ne pagal kūną, bet pagal Dvasią.'),
  (@b45, 8, 5, 'Nes tie, kurie yra pagal kūną, rūpinasi kūno dalykais; bet tie, kurie yra pagal Dvasią – Dvasios dalykais.'),
  (@b45, 8, 6, 'Nes būti kūniškai nusiteikusiam yra mirtis; bet būti dvasiškai nusiteikusiam yra gyvenimas ir ramybė.'),
  (@b45, 8, 7, 'Nes kūniškas nusiteikimas yra priešiškumas Dievui; nes jis nėra paklusnus Dievo įstatymui ir tikrai negali būti.'),
  (@b45, 8, 8, 'Todėl tie, kurie yra kūne, negali patikti Dievui.'),
  (@b45, 8, 9, 'Tačiau jūs nesate kūne, bet Dvasioje, jei taip yra, kad Dievo Dvasia gyvena jumyse. Na, o jei kas neturi Kristaus Dvasios, tas nėra jo.'),
  (@b45, 8, 10, 'Ir jei Kristus jumyse, kūnas yra miręs dėl nuodėmės; bet Dvasia yra gyvenimas dėl teisumo.'),
  (@b45, 8, 11, 'Bet jei jumyse gyvena Dvasia to, kuris prikėlė Jėzų iš numirusiųjų, tai tas, kuris prikėlė Kristų iš numirusių, atgaivins ir jūsų mirtingus kūnus savo Dvasia, gyvenančia jumyse.'),
  (@b45, 8, 12, 'Taigi, broliai, esame skolininkai ne kūnui, kad gyventume pagal kūną.'),
  (@b45, 8, 13, 'Nes jei gyvenate pagal kūną – mirsite; bet jei per Dvasią marinate kūno darbus – gyvensite.'),
  (@b45, 8, 14, 'Nes visi, kurie yra Dievo Dvasios vedami, yra Dievo sūnūs.'),
  (@b45, 8, 15, 'Nes jūs negavote vergystės dvasios, kad vėl bijotumėte; bet gavote įvaikystės Dvasią, kuria šaukiame: „Aba, Tėve!“'),
  (@b45, 8, 16, 'Pati Dvasia liudija su mūsų dvasia, kad esame Dievo vaikai;'),
  (@b45, 8, 17, 'o jei vaikai, tuomet paveldėtojai; Dievo paveldėtojai ir bendrapaveldėtojai su Kristumi; jei taip yra, kad kenčiame su juo, kad būtume ir pašlovinti kartu.'),
  (@b45, 8, 18, 'Nes manau, kad šio dabartinio laiko kentėjimai nėra verti, kad būtų sugretinti su šlove, kuri bus apreikšta mumyse.'),
  (@b45, 8, 19, 'Nes uolus sutvėrimo lūkestis laukia Dievo sūnų apreiškimo.'),
  (@b45, 8, 20, 'Nes sutvėrimas buvo pajungtas tuštybei ne savo noru, bet dėl to, kuris jį pajungė viltyje,'),
  (@b45, 8, 21, 'nes ir pats sutvėrimas bus išvaduotas iš gedimo vergovės į šlovingą Dievo vaikų laisvę.'),
  (@b45, 8, 22, 'Nes žinome, kad visa kūrinija drauge dejuoja ir kankinasi skausme iki šiol.'),
  (@b45, 8, 23, 'Ir ne tik jie, bet ir mes, turintys Dvasios pirmavaisius, – ir mes patys dejuojame savyje, laukdami įvaikystės, tai yra, mūsų kūno atpirkimo.'),
  (@b45, 8, 24, 'Nes mes išgelbėti viltimi; bet viltis, kuri matoma, nėra viltis; nes tai, ką kas regi, kodėl jis to dar viliasi?'),
  (@b45, 8, 25, 'Bet jei viliamės to, ko nematome, tada su kantrumu to laukiame.'),
  (@b45, 8, 26, 'Taip pat ir Dvasia padeda mūsų negalioms; nes nežinome, ko turime melsti, kaip mums privalu, bet pati Dvasia užtaria mus neišsakomomis dejonėmis.'),
  (@b45, 8, 27, 'O tas, kuris tiria širdis, žino, koks yra Dvasios nusiteikimas, nes ji užtaria šventuosius pagal Dievo valią.'),
  (@b45, 8, 28, 'Ir žinome, kad visa kartu veikia į gera tiems, kurie myli Dievą, tiems, kurie yra pašauktieji pagal jo tikslą.'),
  (@b45, 8, 29, 'Nes kuriuos jis iš anksto pažinojo, jis iš anksto ir paskyrė atitikti atvaizdą jo Sūnaus, kad jis būtų pirmagimis tarp daugelio brolių.'),
  (@b45, 8, 30, 'Be to, kuriuos jis iš anksto paskyrė, tuos ir pašaukė; o kuriuos pašaukė, tuos ir išteisino; o kuriuos išteisino, tuos ir pašlovino.'),
  (@b45, 8, 31, 'Ką tuomet į tai pasakysime? Jei Dievas už mus, kas gali būti prieš mus?'),
  (@b45, 8, 32, 'Tas, kuris nepagailėjo savo Sūnaus, bet atidavė jį už mus visus, kaipgi ir visko mums nedovanotų kartu su juo?'),
  (@b45, 8, 33, 'Kas kuo nors apkaltins Dievo išrinktuosius? Tai – Dievas, kuris išteisina.'),
  (@b45, 8, 34, 'Kas tas, kuris smerkia? Tai – Kristus, kuris mirė, dar daugiau, kuris yra prisikėlęs, kuris yra ir Dievo dešinėje, kuris ir užtaria mus.'),
  (@b45, 8, 35, 'Kas mus atskirs nuo Kristaus meilės? Ar suspaudimas, ar sielvartas, ar persekiojimas, ar badas, ar nuogumas, ar pavojus, ar kalavijas?'),
  (@b45, 8, 36, 'Kaip yra parašyta: „Dėl tavęs mes žudomi visą dieną; esame laikomi avimis skerdimui“.'),
  (@b45, 8, 37, 'Ne, visuose šiuose dalykuose esame daugiau nei nugalėtojai per tą, kuris mus pamilo.'),
  (@b45, 8, 38, 'Nes esu įsitikinęs, kad nei mirtis, nei gyvenimas, nei angelai, nei kunigaikštystės, nei valdžios, nei dabartis, nei ateitis,'),
  (@b45, 8, 39, 'nei aukštis, nei gylis, nei koks kitas sutvėrimas nepajėgs atskirti mūsų nuo Dievo meilės, kuri yra Kristuje Jėzuje, mūsų Viešpatyje.'),
  (@b45, 9, 1, 'Sakau tiesą Kristuje, nemeluoju, ir mano sąžinė man liudija Šventojoje Dvasioje,'),
  (@b45, 9, 2, 'kad labai liūdžiu ir nuolat sielvartauju savo širdyje.'),
  (@b45, 9, 3, 'Nes norėčiau, kad pats būčiau prakeiktas nuo Kristaus dėl savo brolių, mano giminaičių pagal kūną,'),
  (@b45, 9, 4, 'kurie yra izraelitai; kuriems priklauso įvaikystė ir šlovė, ir sandoros, ir įstatymo leidyba, ir Dievo tarnystė, ir pažadai;'),
  (@b45, 9, 5, 'kurių yra tėvai ir iš kurių pagal kūną kilo Kristus, kuris yra virš visų – palaimintas Dievas per amžius. Amen.'),
  (@b45, 9, 6, 'Nėra, tarsi Dievo žodis neturėjo poveikio. Nes ne visi, esantys iš Izraelio, yra Izraelis;'),
  (@b45, 9, 7, 'nei dėl to, kad jie yra Abraomo sėkla, visi jie yra vaikai; bet „Izaoke bus pašaukta tavo sėkla“.'),
  (@b45, 9, 8, 'Tai yra, tie, kurie yra kūno vaikai, nėra Dievo vaikai; bet pažado vaikai laikomi sėkla.'),
  (@b45, 9, 9, 'Nes šis yra pažado žodis: „Šituo laiku ateisiu, ir Sara turės sūnų“.'),
  (@b45, 9, 10, 'Ir ne tik tai; bet ir kai Rebeka tapo nėščia per vieną, būtent per mūsų tėvą Izaoką'),
  (@b45, 9, 11, '(nes vaikams dar negimus ir nepadarius nieko gero ar blogo, kad išstovėtų Dievo tikslas pagal išrinkimą, ne dėl darbų, bet iš to, kuris pašaukia),'),
  (@b45, 9, 12, 'jai buvo pasakyta: „Vyresnysis tarnaus jaunesniajam“.'),
  (@b45, 9, 13, 'Kaip yra parašyta: „Jokūbą mylėjau, bet Ezavo nekenčiau“.'),
  (@b45, 9, 14, 'Ką tuomet pasakysime? Ar pas Dievą yra neteisumas? Jokiu būdu!'),
  (@b45, 9, 15, 'Nes jis sako Mozei: „Aš pasigailėsiu, kurio pasigailėsiu, ir būsiu gailestingas, kuriam būsiu gailestingas“.'),
  (@b45, 9, 16, 'Taigi tai nėra iš to, kuris nori, nei iš to, kuris bėga, bet iš Dievo, kuris pasigaili.'),
  (@b45, 9, 17, 'Nes Raštas sako faraonui: „Kaip tik šitam tikslui tave iškėliau, kad tavyje parodyčiau savo jėgą ir kad mano vardas būtų skelbiamas po visą žemę“.'),
  (@b45, 9, 18, 'Todėl jis pasigaili, kurio nori pasigailėti, ir kurį nori – jis užkietina.'),
  (@b45, 9, 19, 'Tuomet man pasakysi: „Kodėl jis dar kaltina? Nes kas gi yra atsispyręs jo valiai?“'),
  (@b45, 9, 20, 'Ne, bet, o žmogau, kas gi esi, kad prieštarauji Dievui? Argi suformuotas daiktas sako tam, kuris jį suformavo: „Kodėl mane taip padarei?“'),
  (@b45, 9, 21, 'Argi puodžius neturi valdžios moliui, iš to paties minkalo padaryti vieną indą garbei, o kitą negarbei?'),
  (@b45, 9, 22, 'Ką jei Dievas, norėdamas parodyti savo rūstybę ir duoti pažinti savo galią, ilgu pakantumu pakentė rūstybės indus, tinkamus sunaikinimui;'),
  (@b45, 9, 23, 'ir kad duotų pažinti savo šlovės turtus gailestingumo indams, kuriuos jis iš anksto paruošė šlovei,'),
  (@b45, 9, 24, 'tai yra, mums, kuriuos jis pašaukė ne tik iš žydų, bet ir iš pagonių?'),
  (@b45, 9, 25, 'Kaip jis sako ir Ozėjuje: „Pavadinsiu juos savo tauta, kurie nebuvo mano tauta; ir mylimąja tą, kuri nebuvo mylima.'),
  (@b45, 9, 26, 'Ir įvyks, kad toje vietoje, kur buvo jiems pasakyta: ‘Jūs ne mano tauta’, ten jie bus vadinami gyvojo Dievo vaikais“.'),
  (@b45, 9, 27, 'Izaijas irgi šaukia apie Izraelį: „Nors Izraelio vaikų skaičius būtų kaip jūros smėlis, tik likutis bus išgelbėtas;'),
  (@b45, 9, 28, 'nes jis užbaigs darbą ir sutrumpins jį teisumu; nes trumpą darbą Viešpats atliks žemėje“.'),
  (@b45, 9, 29, 'Ir kaip anksčiau sakė Izaijas: „Jei Sabaoto Viešpats nebūtų mums palikęs sėklos, mes būtume buvę kaip Sodoma ir būtume panašūs į Gomorą“.'),
  (@b45, 9, 30, 'Ką tuomet pasakysime? Kad pagonys, kurie nesekė teisumu, pasiekė teisumą – teisumą, kuris yra iš tikėjimo.'),
  (@b45, 9, 31, 'Bet Izraelis, kuris sekė teisumo įstatymu, nepasiekė teisumo įstatymo.'),
  (@b45, 9, 32, 'Kodėl? Nes jie ieškojo to ne tikėjimu, bet tarytum įstatymo darbais. Nes jie suklupo ties tuo suklupimo akmeniu;'),
  (@b45, 9, 33, 'kaip yra parašyta: „Štai dedu Sione suklupimo akmenį ir papiktinimo uolą; bet kas į jį tiki, nebus sugėdintas“.'),
  (@b45, 10, 1, 'Broliai, mano širdies troškimas ir malda Dievui už Izraelį yra, kad jie būtų išgelbėti.'),
  (@b45, 10, 2, 'Nes aš jiems liudiju, kad jie turi Dievo uolumo, bet ne pagal pažinimą.'),
  (@b45, 10, 3, 'Nes jie, nežinodami Dievo teisumo ir imdamiesi įtvirtinti savąjį teisumą, nepakluso Dievo teisumui.'),
  (@b45, 10, 4, 'Nes Kristus yra įstatymo galas teisumui – kiekvienam, kuris tiki.'),
  (@b45, 10, 5, 'Nes Mozė aprašo teisumą, kuris yra iš įstatymo, kad „Žmogus, kuris daro tuos dalykus, jais gyvens“.'),
  (@b45, 10, 6, 'Bet teisumas, kuris yra iš tikėjimo, kalba taip: „Nesakyk savo širdyje: ‘Kas pakils į dangų?’ (tai yra, atvesti žemyn Kristaus iš aukštai)'),
  (@b45, 10, 7, 'Arba: ‘Kas nusileis į gelmę?’ (tai yra, atvesti aukštyn Kristaus iš numirusiųjų)“'),
  (@b45, 10, 8, 'Bet ką jis sako? „Žodis yra arti tavęs – tavo burnoje ir tavo širdyje“, tai yra tikėjimo žodis, kurį skelbiame;'),
  (@b45, 10, 9, 'kad, jei savo burna išpažinsi Viešpatį Jėzų ir tikėsi savo širdyje, jog Dievas jį prikėlė iš numirusiųjų, būsi išgelbėtas.'),
  (@b45, 10, 10, 'Nes širdimi žmogus tiki teisumui; o išpažinimas burna atliekamas išgelbėjimui.'),
  (@b45, 10, 11, 'Nes Raštas sako: „Kas į jį tiki, nebus sugėdintas“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b45, 10, 12, 'Nes nėra skirtumo tarp žydo ir graiko; nes tas pats visų Viešpats yra turtingas visiems, kurie jo šaukiasi.'),
  (@b45, 10, 13, 'Nes kas šauksis Viešpaties vardo, bus išgelbėtas.'),
  (@b45, 10, 14, 'Kaip tad jie šauksis to, kuriuo netikėjo? Ir kaip tikės į tą, apie kurį negirdėjo? Ir kaip jie išgirs be skelbėjo?'),
  (@b45, 10, 15, 'Ir kaip jie skelbs, jei nebus pasiųsti? Kaip yra parašyta: „Kokios dailios kojos skelbiančiųjų taikos evangeliją ir nešančiųjų džiugią žinią apie gera!“'),
  (@b45, 10, 16, 'Bet jie ne visi pakluso evangelijai. Nes Izaijas sako: „Viešpatie, kas patikėjo mūsų pranešimu?“'),
  (@b45, 10, 17, 'Tad tikėjimas ateina iš klausymo, o klausymas – iš Dievo žodžio.'),
  (@b45, 10, 18, 'Bet sakau: ar jie negirdėjo? Taip, iš tiesų, jų garsas ėjo po visą žemę, ir jų žodžiai iki pasaulio pakraščių.'),
  (@b45, 10, 19, 'Bet sakau: ar Izraelis nežinojo? Pirma Mozė sako: „Aš sukelsiu jums pavydą per tuos, kurie nėra tauta, ir per kvailą tautą jus užpykinsiu“.'),
  (@b45, 10, 20, 'Bet Izaijas yra labai drąsus ir sako: „Buvau atrastas tų, kurie manęs neieškojo; apsireiškiau tiems, kurie apie mane neklausinėjo“.'),
  (@b45, 10, 21, 'Bet Izraeliui jis sako: „Ištisą dieną esu ištiesęs savo rankas į neklusnią ir prieštaraujančią tautą“.'),
  (@b45, 11, 1, 'Tad sakau: Ar Dievas atmetė savo tautą? Jokiu būdu! Nes ir aš izraelitas, iš Abraomo sėklos, iš Benjamino genties.'),
  (@b45, 11, 2, 'Dievas neatmetė savo tautos, kurią jis iš anksto pažinojo. Ar nežinote, ką sako Raštas apie Eliją? Kaip jis atlieka užtarimą Dievui prieš Izraelį, sakydamas:'),
  (@b45, 11, 3, '„Viešpatie, jie nužudė tavo pranašus ir iškasė tavo aukurus; o aš išlikau vienas, ir jie ieško mano gyvybės“.'),
  (@b45, 11, 4, 'Bet ką jam sako Dievo atsakymas? „Aš sau pasilaikiau septynis tūkstančius vyrų, kurie nesulenkė kelių Baalio atvaizdui“.'),
  (@b45, 11, 5, 'Tad taip ir šiuo dabartiniu laiku yra likutis pagal malonės išrinkimą.'),
  (@b45, 11, 6, 'O jei malone, tuomet nebe dėl darbų: kitaip malonė nebėra malonė. Bet jei dėl darbų, tuomet tai nebėra malonė: kitaip darbas nebėra darbas.'),
  (@b45, 11, 7, 'Ką tuomet? Izraelis nepasiekė to, ko ieško; tačiau išrinkimas pasiekė, o likusieji buvo apakinti'),
  (@b45, 11, 8, '(pagal tai, kaip yra parašyta: „Dievas jiems davė snaudulio dvasią, akis, kad jie nematytų, ir ausis, kad jie negirdėtų“) iki šios dienos.'),
  (@b45, 11, 9, 'Ir Dovydas sako: „Jų stalas tepavirsta jiems spąstais ir pinklėmis, ir kliūtimi, ir atpildu;'),
  (@b45, 11, 10, 'jų akys tebūna aptemusios, kad jie nematytų ir nuolat lenktų savo nugarą“.'),
  (@b45, 11, 11, 'Tad sakau: ar jie suklupo, kad pargriūtų? Jokiu būdu! Bet verčiau per jų griuvimą išgelbėjimas atėjo pagonims, kad sukeltų jiems pavydą.'),
  (@b45, 11, 12, 'Na, o jei jų griuvimas yra pasaulio turtas ir jų mažėjimas – pagonių turtas, tai kaip juo daugiau jų pilnuma?'),
  (@b45, 11, 13, 'Nes aš kalbu jums, pagonys, kadangi esu pagonių apaštalas, aš aukštinu savo tarnybą,'),
  (@b45, 11, 14, 'kad kaip nors sukelčiau pavydą tiems, kurie yra mano kūnas, ir kai kuriuos jų išgelbėčiau.'),
  (@b45, 11, 15, 'Nes jei jų atmetimas yra pasaulio sutaikinimas, tai kas bus jų priėmimas, jei ne gyvenimas iš numirusiųjų?'),
  (@b45, 11, 16, 'Nes jei pirmavaisis šventas, minkalas taip pat šventas: ir jei šaknis šventa, tai ir šakos.'),
  (@b45, 11, 17, 'Ir jei kai kurios šakos yra nulaužtos, o tu, būdamas laukinis alyvmedis, buvai tarp jų įskiepytas ir su jomis esi alyvmedžio šaknies bei riebumo dalininkas;'),
  (@b45, 11, 18, 'nesididžiuok prieš šakas. Bet jei didžiuojiesi, ne tu išlaikai šaknį, bet šaknis tave.'),
  (@b45, 11, 19, 'Tu tuomet pasakysi: „Šakos buvo nulaužtos, kad aš būčiau įskiepytas“.'),
  (@b45, 11, 20, 'Gerai; dėl netikėjimo jos buvo nulaužtos, o tu stovi tikėjimu. Nebūk išdidus, bet bijok;'),
  (@b45, 11, 21, 'nes jei Dievas nepagailėjo prigimtinių šakų, žiūrėkis kad jis ir tavęs nepagailės.'),
  (@b45, 11, 22, 'Todėl pažiūrėk į Dievo gerumą ir griežtumą: tiems, kurie griuvo – griežtumas; bet tavęs link – gerumas, jei pasiliksi jo gerume: kitaip ir tu būsi iškirstas.'),
  (@b45, 11, 23, 'Ir jie taip pat, jei vis dar netikėjime nepasiliks, bus įskiepyti; nes Dievas pajėgus juos vėl įskiepyti.'),
  (@b45, 11, 24, 'Nes jei tu buvai iškirstas iš alyvmedžio, kuris yra laukinis prigimtimi, ir buvai įskiepytas prieš prigimtį į gerą alyvmedį, tai kaip dar labiau šitie, kurie yra prigimtinės šakos, bus įskiepyti į savo pačių alyvmedį?'),
  (@b45, 11, 25, 'Nes nenoriu, broliai, kad būtumėte nežinantys šios paslapties, idant nebūtumėte išmintingi savo pačių išmanymu; kad Izraelį yra dalinai ištikęs aklumas, kol įeis pagonių pilnuma.'),
  (@b45, 11, 26, 'Ir taip bus išgelbėtas visas Izraelis, kaip yra parašyta: „Iš Siono ateis Išvaduotojas ir nukreips bedievystę nuo Jokūbo,'),
  (@b45, 11, 27, 'nes ši yra mano sandora jiems, kai nuimsiu jų nuodėmes“.'),
  (@b45, 11, 28, 'Evangelijos atžvilgiu jie yra priešai jūsų dėlei, bet išrinkimo atžvilgiu jie yra mylimieji tėvų dėlei.'),
  (@b45, 11, 29, 'Nes Dievo dovanos ir pašaukimas yra neatšaukiami.'),
  (@b45, 11, 30, 'Nes kaip jūs praeityje netikėjote Dievu, tačiau dabar gavote pasigailėjimą per jų netikėjimą,'),
  (@b45, 11, 31, 'taip ir šitie dabar netikėjo, kad per jūsų pasigailėjimą ir jie gautų pasigailėjimą.'),
  (@b45, 11, 32, 'Nes Dievas uždarė juos visus netikėjime, kad visų pasigailėtų.'),
  (@b45, 11, 33, 'O Dievo išminties ir pažinimo turtų gelme! Kokie neištiriami jo teismai ir nesusekami jo keliai!'),
  (@b45, 11, 34, 'Nes kas pažinojo Viešpaties protą? Arba kas buvo jo patarėju?'),
  (@b45, 11, 35, 'Arba kas jam pirma davė, ir jam bus atmokėta?'),
  (@b45, 11, 36, 'Nes iš jo ir per jį, ir jam yra visa; jam tebūna šlovė per amžius. Amen.'),
  (@b45, 12, 1, 'Taigi, broliai, maldauju jus Dievo gailestingumais, kad pristatytumėte savo kūnus gyva auka, šventa, priimtina Dievui – tai yra jūsų protingas tarnavimas.'),
  (@b45, 12, 2, 'Ir nesusitapatinkite su šiuo pasauliu, bet pasikeiskite, atnaujindami savo protą, kad išmėgintumėte, kas yra ta gera ir priimtina, ir tobula Dievo valia.'),
  (@b45, 12, 3, 'Nes per man duotą malonę sakau kiekvienam tarp jūsų esančiam nemanyti apie save aukščiau, negu jis turėtų manyti; bet manyti blaiviai, pagal kiekvienam Dievo duotą tikėjimo matą.'),
  (@b45, 12, 4, 'Nes kaip turime daug narių viename kūne, o visi nariai turi ne tą pačią tarnybą;'),
  (@b45, 12, 5, 'taip mes, daugelis, esame vienas kūnas Kristuje, o pavieniui – vieni kitų nariai.'),
  (@b45, 12, 6, 'Tad turėdami dovanų, skirtingų pagal mums suteiktą malonę: ar tai pranašystę, tai pranašaukime pagal tikėjimo proporciją;'),
  (@b45, 12, 7, 'ar tarnystę, tai patarnaukime savo tarnavimu; arba kas moko, – mokymu;'),
  (@b45, 12, 8, 'arba kas ragina, – raginimu; kas duoda, tedaro tai su paprastumu; kas valdo, – su uolumu; kas rodo gailestingumą, – su linksmumu.'),
  (@b45, 12, 9, 'Meilė tebūna neveidmainiška. Bjaurėkitės tuo, kas pikta; prilipkite prie to, kas gera.'),
  (@b45, 12, 10, 'Būkite nuoširdžiai vienas prie kito prisirišę broliška meile; laikydami vienas kitą garbingesniu;'),
  (@b45, 12, 11, 'būkite ne tingūs reikaluose; karšti dvasioje; tarnaujantys Viešpačiui;'),
  (@b45, 12, 12, 'besidžiaugiantys viltyje; kantrūs suspaudime; pasilikdami nedelsiantys maldoje;'),
  (@b45, 12, 13, 'dalinantys šventųjų būtinybėms; atsidavę svetingumui.'),
  (@b45, 12, 14, 'Laiminkite tuos, kurie jus persekioja, laiminkite ir nekeikite.'),
  (@b45, 12, 15, 'Džiaukitės su tais, kurie džiaugiasi, ir verkite su tais, kurie verkia.'),
  (@b45, 12, 16, 'Būkite vienas kito atžvilgiu vienminčiai. Nesirūpinkite aukštais dalykais, bet nusižeminkite iki žemos padėties žmonių. Nebūkite išmintingi savo pačių išmanymu.'),
  (@b45, 12, 17, 'Neatmokėkite nei vienam piktu už pikta. Rūpinkitės tuo, kas dora, visų žmonių akyse.'),
  (@b45, 12, 18, 'Jei būtų įmanoma, tiek kiek yra jumyse, gyvenkite taikiai su visais žmonėmis.'),
  (@b45, 12, 19, 'Brangiai mylimi, nekeršykite patys, bet verčiau užleiskite vietą rūstybei, nes yra parašyta: „Mano kerštas; aš atmokėsiu, – sako Viešpats“.'),
  (@b45, 12, 20, 'Todėl jei tavo priešas alksta, pavalgydink jį; jei trokšta, pagirdyk jį; nes taip darydamas sukrausi ugnies žarijas ant jo galvos.'),
  (@b45, 12, 21, 'Nebūkite pikto nugalėti, bet nugalėkite pikta geru.'),
  (@b45, 13, 1, 'Kiekviena siela tebūna pavaldi aukštesnėms valdžioms. Nes nėra valdžios, kaip tiktai iš Dievo; valdžios, kurios yra, yra nustatytos iš Dievo.'),
  (@b45, 13, 2, 'Todėl kas priešinasi valdžiai, priešinasi Dievo sutvarkymui; ir tie, kurie priešinasi, užsitrauks sau pasmerkimą.'),
  (@b45, 13, 3, 'Nes valdovai bijotini ne geriems darbams, bet piktiems. Ar nori tad nebijoti valdžios? Daryk tai, kas gera, ir turėsi iš jos pagyrimą,'),
  (@b45, 13, 4, 'nes ji yra Dievo tarnautoja tau dėl gero. Bet jei darai tai, kas pikta, – bijok; nes ji ne veltui nešiojasi kalaviją; nes ji yra Dievo tarnautoja, keršytoja, kad įvykdytų rūstybę tam, kuris daro pikta.'),
  (@b45, 13, 5, 'Todėl jums reikia būti pavaldiems ne tik dėl rūstybės, bet ir dėl sąžinės.'),
  (@b45, 13, 6, 'Nes dėl to ir duoklę mokate; nes jos yra Dievo tarnautojos, nuolatos tuo besirūpinančios.'),
  (@b45, 13, 7, 'Todėl visiems atiduokite, ką privalote: kam duoklę – duoklę; kam muitą – muitą; kam baimę – baimę; kam garbę – garbę.'),
  (@b45, 13, 8, 'Niekam nieko nebūkite skolingi, o tik mylėti vienas kitą; nes kas myli kitą, yra įvykdęs įstatymą.'),
  (@b45, 13, 9, 'Nes tai – „Nesvetimauk“, „Nežudyk“, „Nevok“, „Melagingai neliudyk“, „Negeisk“; ir jei būtų koks kitas įsakymas, tai trumpai apima šis pasakymas, tai yra: „Mylėk savo artimą kaip save patį“.'),
  (@b45, 13, 10, 'Meilė nedaro blogo artimui, todėl meilė yra įstatymo išpildymas.'),
  (@b45, 13, 11, 'Ir tai, žinodami laiką, kad dabar pats laikas pabusti iš miego; nes dabar mūsų išgelbėjimas arčiau negu tada, kai įtikėjome.'),
  (@b45, 13, 12, 'Naktis jau praėjusi, diena čia pat; todėl nusimeskime tamsos darbus ir užsidėkime šviesos ginklus.'),
  (@b45, 13, 13, 'Vaikščiokime dorai, kaip dieną; ne ūžavime ir girtavime, ne sanguliavime ir paleistuvavime, ne vaiduose ir pavydėjime.'),
  (@b45, 13, 14, 'Bet apsivilkite Viešpačiu Jėzumi Kristumi ir nesirūpinkite kūnu, kad patenkintumėte jo geismus.'),
  (@b45, 14, 1, 'Silpnąjį tikėjime priimkite, bet ne abejotiniems ginčams.'),
  (@b45, 14, 2, 'Nes vienas tiki galintis valgyti viską, kitas, silpnasis, valgo žoles.'),
  (@b45, 14, 3, 'Kas valgo, teneniekina to, kuris nevalgo; o kas nevalgo, teneteisia to, kuris valgo; nes Dievas jį priėmė.'),
  (@b45, 14, 4, 'Kas esi, kad teisi kito tarną? Savo šeimininkui jis stovi arba griūna. Taip, jis bus palaikomas, nes Dievas yra pajėgus jį pastatyti.'),
  (@b45, 14, 5, 'Vienas laiko vieną dieną aukščiau už kitą, kitas laiko kiekvieną dieną vienodomis. Kiekvienas tebūna pilnai įsitikinęs savo paties prote.'),
  (@b45, 14, 6, 'Kas atsižvelgia į dieną, Viešpačiui į ją atsižvelgia; o kas neatsižvelgia į dieną, Viešpačiui į ją neatsižvelgia. Kas valgo, Viešpačiui valgo, nes jis dėkoja Dievui; o kas nevalgo, tas Viešpačiui nevalgo ir dėkoja Dievui.'),
  (@b45, 14, 7, 'Nes nei vienas iš mūsų sau negyvena, ir nei vienas sau nemiršta.'),
  (@b45, 14, 8, 'Nes ar gyvename, Viešpačiui gyvename; ir ar mirštame, Viešpačiui mirštame; todėl ar gyvename, ar mirštame, esame Viešpaties.'),
  (@b45, 14, 9, 'Nes Kristus ir mirė, ir prisikėlė, ir atgijo tam, kad būtų tiek mirusiųjų, tiek gyvųjų Viešpats.'),
  (@b45, 14, 10, 'Bet kodėl teisi savo brolį? Arba kodėl niekini savo brolį? Nes mes visi stosime prieš Kristaus teismo krasę.'),
  (@b45, 14, 11, 'Nes yra parašyta: „Kaip aš gyvas, – sako Viešpats, – man nusilenks kiekvienas kelis, ir kiekvienas liežuvis išpažins Dievui“.'),
  (@b45, 14, 12, 'Taigi kiekvienas iš mūsų duos už save ataskaitą Dievui.'),
  (@b45, 14, 13, 'Todėl nebeteiskime vienas kito; bet verčiau teiskite tai, kad nei vienas nesudarytų savo brolio kelyje kliūties ar progos pargriūti.'),
  (@b45, 14, 14, 'Aš žinau ir esu įsitikinęs per Viešpatį Jėzų, kad nieko nėra nešvaraus iš savęs; bet tam, kuris ką nors laiko nešvariu, jam tai yra nešvaru.'),
  (@b45, 14, 15, 'Bet jei tavo brolis nuliūdintas dėl tavo valgio, tu jau vaikštai ne pagal meilę. Savo valgiu nenaikink to, už kurį mirė Kristus.'),
  (@b45, 14, 16, 'Tad apie jūsų gėrį tenebūna kalbama pikta;'),
  (@b45, 14, 17, 'nes Dievo karalystė ne maistas ir gėrimas, bet teisumas, ramybė ir džiaugsmas Šventojoje Dvasioje.'),
  (@b45, 14, 18, 'Nes kas tuo tarnauja Kristui, tas yra priimtinas Dievui ir išmėgintas žmonių.'),
  (@b45, 14, 19, 'Todėl sekime tuo, kas pasitarnauja ramybei, ir tuo, kuo galime vienas kitą statydinti.'),
  (@b45, 14, 20, 'Negriauk Dievo darbo dėl maisto. Iš tikrųjų viskas yra tyra; bet bloga tam žmogui, kuris valgo papiktindamas.'),
  (@b45, 14, 21, 'Gerai nei valgyti mėsos, nei gerti vyno, nei ko kito, per ką tavo brolis suklumpa ar yra papiktintas, ar daromas silpnu.'),
  (@b45, 14, 22, 'Ar turi tikėjimą? Turėkis jį sau Dievo akivaizdoje. Laimingas, kuris nesmerkia savęs tuo, ką pripažįsta.'),
  (@b45, 14, 23, 'O kas abejoja, yra smerkiamas, jei valgo, nes jis valgo ne iš tikėjimo; nes viskas, kas ne iš tikėjimo, yra nuodėmė.'),
  (@b45, 15, 1, 'Tad mes, stiprieji, turime nešioti silpnųjų negalias, o ne sau įtikti.'),
  (@b45, 15, 2, 'Tegul kiekvienas iš mūsų įtinka savo artimui jo labui, statydinimui.'),
  (@b45, 15, 3, 'Nes ir Kristus ne sau įtiko; bet, kaip yra parašyta: „Tau priekaištaujančiųjų priekaištai krito ant manęs“.'),
  (@b45, 15, 4, 'Nes tai, kas buvo anksčiau parašyta, buvo parašyta mūsų mokymuisi, kad per Raštų kantrybę ir paguodą turėtume viltį.'),
  (@b45, 15, 5, 'Na, o kantrybės ir paguodos Dievas teduoda jums būti vienas kito atžvilgiu vienminčiais pagal Kristų Jėzų;'),
  (@b45, 15, 6, 'kad vienu protu ir viena burna šlovintumėte Dievą, tai yra, mūsų Viešpaties Jėzaus Kristaus Tėvą.'),
  (@b45, 15, 7, 'Todėl priimkite vienas kitą, kaip ir Kristus mus priėmė Dievo šlovei.'),
  (@b45, 15, 8, 'Sakau gi, kad Jėzus Kristus buvo apipjaustymo tarnas dėl Dievo tiesos, kad patvirtintų tėvams duotus pažadus;'),
  (@b45, 15, 9, 'ir kad pagonys šlovintų Dievą už jo gailestingumą; kaip yra parašyta: „Dėl to aš tau išpažinsiu tarp pagonių ir tavo vardui giedosiu“.'),
  (@b45, 15, 10, 'Ir vėl jis sako: „Džiaukitės, pagonys, su jo tauta“.'),
  (@b45, 15, 11, 'Ir vėl: „Girkite Viešpatį, visi pagonys; ir šlovinkite jį, visos tautos“.'),
  (@b45, 15, 12, 'Ir vėl Izaijas sako: „Bus Jesės šaknis ir tas, kuris pakils viešpatauti pagonims; juo pasitikės pagonys“.'),
  (@b45, 15, 13, 'Na, o vilties Dievas tepripildo jus visu džiaugsmu ir ramybe kai tikite, kad būtumėte pertekę viltimi per Šventosios Dvasios jėgą.'),
  (@b45, 15, 14, 'Ir aš ir pats esu įsitikinęs dėl jūsų, mano broliai, kad ir jūs pilni gerumo, pripildyti viso pažinimo, galintys taipogi vienas kitą įspėti.'),
  (@b45, 15, 15, 'Tačiau, broliai, parašiau jums tam tikru laipsniu dar drąsiau, kaip primindamas jums, dėl man duotos Dievo malonės,'),
  (@b45, 15, 16, 'kad būčiau Jėzaus Kristaus tarnautojas pagonims, patarnaujantis Dievo evangeliją, kad pagonių atnašavimas būtų priimtinas, pašvęstas Šventosios Dvasios.'),
  (@b45, 15, 17, 'Todėl turiu, kuo galėčiau pasigirti per Jėzų Kristų tame, kas susiję su Dievu.'),
  (@b45, 15, 18, 'Nes nedrįsiu kalbėti ko nors iš to, ko Kristus nebūtų padaręs per mane, idant padarytų pagonis paklusniais žodžiu ir darbu'),
  (@b45, 15, 19, 'per galingus ženklus ir stebuklus, Dievo Dvasios jėga; taip, kad nuo Jeruzalės ir aplinkui iki Ilyrikos pilnai paskelbiau Kristaus evangeliją.'),
  (@b45, 15, 20, 'Taip, šitaip stengiausi skelbti evangeliją ne ten, kur Kristus buvo minimas, kad nestatyčiau ant kito žmogaus pamato,'),
  (@b45, 15, 21, 'bet kaip yra parašyta: „Tie, kuriems nebuvo kalbėta apie jį, – pamatys, ir tie, kurie nebuvo girdėję, – supras“.'),
  (@b45, 15, 22, 'Dėl to man buvo labai ir kliudoma pas jus atvykti.'),
  (@b45, 15, 23, 'Bet dabar, nebeturėdamas daugiau vietos šiose srityse ir šituos daugelį metų turėdamas didelį troškimą atvykti pas jus;'),
  (@b45, 15, 24, 'kai tik keliausiu į Ispaniją, atvyksiu pas jus; nes tikiuosi jus pamatyti savo kelionėje ir būti jūsų išlydėtas keliauti ten, jei pirma šiek tiek pasisotinsiu bendravimu su jumis.'),
  (@b45, 15, 25, 'Bet dabar vykstu į Jeruzalę patarnauti šventiesiems.'),
  (@b45, 15, 26, 'Nes tiems iš Makedonijos ir Achajos patiko atlikti tam tikrą paaukojimą beturčiams šventiesiems, esantiems Jeruzalėje.'),
  (@b45, 15, 27, 'Jiems iš tikrųjų tai patiko; ir jie yra jų skolininkai. Nes jei pagonys tapo jų dvasinių dalykų bendrininkai, tai ir jų pareiga patarnauti jiems kūniškais dalykais.'),
  (@b45, 15, 28, 'Todėl tai atlikęs ir užantspaudavęs jiems šitą vaisių, per jus atvyksiu į Ispaniją.'),
  (@b45, 15, 29, 'Ir esu tikras, kad kai atvyksiu pas jus, atvyksiu Kristaus evangelijos palaiminimo pilnume.'),
  (@b45, 15, 30, 'Maldauju gi jus, broliai, dėl Viešpaties Jėzaus Kristaus ir dėl Dvasios meilės, kad kovotumėte kartu su manimi savo maldose už mane Dievui;'),
  (@b45, 15, 31, 'kad būčiau išvaduotas nuo netikinčių Judėjoje; ir kad mano tarnavimas, kurį atlieku Jeruzalei, būtų priimtinas šventiesiems;'),
  (@b45, 15, 32, 'idant su džiaugsmu atvykčiau pas jus Dievo valia ir su jumis atsigaivinčiau.'),
  (@b45, 15, 33, 'Na, o ramybės Dievas tebūna su jumis visais. Amen.'),
  (@b45, 16, 1, 'Patikiu jums mūsų seserį Febę, kuri yra tarnaitė bažnyčios, esančios Kenchrėjoje,'),
  (@b45, 16, 2, 'kad priimtumėte ją Viešpatyje, kaip tinka šventiesiems, ir kad padėtumėte jai bet kokiu reikalu, ko jai iš jūsų beprireiktų; nes ji buvo daugelio padėjėja, taip pat ir mano.'),
  (@b45, 16, 3, 'Pasveikinkite Priscilę ir Akvilą, mano padėjėjus Kristuje Jėzuje,'),
  (@b45, 16, 4, 'kurie už mano gyvybę guldė savo pačių kaklus; kuriems ne tik aš dėkoju, bet ir visos pagonių bažnyčios.'),
  (@b45, 16, 5, 'Taip pat sveikinkite bažnyčią, esančią jų namuose. Sveikinkite mano labai mylimą Epenetą, kuris yra Achajos pirmavaisiai Kristui.'),
  (@b45, 16, 6, 'Sveikinkite Mariją, kuri daug dėl mūsų triūsė.'),
  (@b45, 16, 7, 'Sveikinkite Androniką ir Juniją, mano giminaičius ir mano bendrakalinius, kurie yra garsūs tarp apaštalų, kurie taip pat pirma manęs buvo Kristuje.'),
  (@b45, 16, 8, 'Sveikinkite Ampliatą, mano mylimąjį Viešpatyje.'),
  (@b45, 16, 9, 'Sveikinkite Urboną, mūsų padėjėją Kristuje, ir mano mylimąjį Stachį.'),
  (@b45, 16, 10, 'Sveikinkite Apelį, išmėgintą Kristuje. Sveikinkite tuos, kurie yra iš Aristobulo namiškių.'),
  (@b45, 16, 11, 'Sveikinkite mano giminaitį Erodioną. Sveikinkite tuos, kurie yra iš Narcizo namiškių, kurie yra Viešpatyje.'),
  (@b45, 16, 12, 'Sveikinkite Trifeną ir Trifosą, kurios triūsia Viešpatyje. Sveikinkite mylimąją Persidę, kuri daug triūsė Viešpatyje.'),
  (@b45, 16, 13, 'Sveikinkite Rufą, išrinktąjį Viešpatyje, ir jo motiną bei manąją.'),
  (@b45, 16, 14, 'Sveikinkite Asinkritą, Flegoną, Hermą, Patrobą, Hermį ir su jais esančius brolius.'),
  (@b45, 16, 15, 'Sveikinkite Filologą ir Juliją, Nerėją ir jo seserį, ir Olimpą, ir visus su jais esančius šventuosius.'),
  (@b45, 16, 16, 'Sveikinkite vienas kitą šventu pabučiavimu. Kristaus bažnyčios sveikina jus.'),
  (@b45, 16, 17, 'Maldauju gi jus, broliai, paženklinkite tuos, kurie kelia susiskaldymus ir papiktinimus, priešingus tam mokslui, kurio išmokote; ir venkite jų.'),
  (@b45, 16, 18, 'Nes tokie tarnauja ne mūsų Viešpačiui Jėzui Kristui, bet savo pilvui; ir gerais žodžiais bei gražiomis kalbomis klaidina paprastųjų širdis.'),
  (@b45, 16, 19, 'Nes jūsų klusnumas pasklido visiems. Todėl džiaugiuosi dėl jūsų; tačiau noriu, kad būtumėte išmintingi gėriui, o neišmanūs blogio atžvilgiu.'),
  (@b45, 16, 20, 'Ir ramybės Dievas netrukus sutrins šėtoną po jūsų kojomis. Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis. Amen.'),
  (@b45, 16, 21, 'Timotiejus, mano bendradarbis, ir mano giminaičiai Liucijus, Jasonas ir Sosipatras sveikina jus.'),
  (@b45, 16, 22, 'Aš, Tercijus, kuris rašiau šį laišką, sveikinu jus Viešpatyje.'),
  (@b45, 16, 23, 'Mano ir visos bažnyčios šeimininkas Gajus sveikina jus. Jus sveikina miesto prievaizdas Erastas ir brolis Kvartas.'),
  (@b45, 16, 24, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis visais. Amen.'),
  (@b45, 16, 25, 'Na, o tam, kuris gali jus sutvirtinti pagal mano evangeliją ir Jėzaus Kristaus skelbimą pagal apreiškimą paslapties, kuri buvo nutylėta nuo pasaulio pradžios,'),
  (@b45, 16, 26, 'bet dabar atskleista ir per pranašų Raštus pagal amžinojo Dievo įsakymą duota žinoti visoms tautoms tikėjimo klusnumui,'),
  (@b45, 16, 27, 'vieninteliam išmintingajam Dievui tebūna šlovė per Jėzų Kristų amžinai. Amen.'),
  (@b46, 1, 1, 'Paulius, pašauktas būti Jėzaus Kristaus apaštalu per Dievo valią, ir mūsų brolis Sostenas,'),
  (@b46, 1, 2, 'Dievo bažnyčiai, esančiai Korinte, tiems, kurie yra pašvęsti Kristuje Jėzuje, pašaukti būti šventaisiais, su visais, kurie kiekvienoje vietoje šaukiasi vardo Jėzaus Kristaus, mūsų Viešpaties, tiek jų, tiek mūsų;'),
  (@b46, 1, 3, 'malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir nuo Viešpaties Jėzaus Kristaus.'),
  (@b46, 1, 4, 'Aš visuomet dėkoju savo Dievui dėl jūsų už Dievo malonę, kuri jums yra suteikta per Jėzų Kristų;'),
  (@b46, 1, 5, 'kad per jį esate praturtinti viskuo, visa ištarme ir visu pažinimu;'),
  (@b46, 1, 6, 'kaip ir Kristaus liudijimas buvo patvirtintas jumyse;'),
  (@b46, 1, 7, 'taip, kad jums netrūksta jokios dovanos, belaukiant mūsų Viešpaties Jėzaus Kristaus atėjimo;'),
  (@b46, 1, 8, 'kuris ir sutvirtins jus iki galo, kad būtumėte nekalti mūsų Viešpaties Jėzaus Kristaus dieną.'),
  (@b46, 1, 9, 'Ištikimas yra Dievas, kurio buvote pašaukti į jo Sūnaus Jėzaus Kristaus, mūsų Viešpaties, bendrystę.'),
  (@b46, 1, 10, 'Maldauju gi jus, broliai, mūsų Viešpaties Jėzaus Kristaus vardu, kad visi kalbėtumėte tą patį, ir kad tarp jūsų nebūtų susiskaldymų; bet kad būtumėte tobulai suvienyti tam pačiam prote ir tam pačiam sprendime.'),
  (@b46, 1, 11, 'Nes man buvo pranešta apie jus, mano broliai, nuo tų iš Chlojės namiškių, kad tarp jūsų yra ginčų.'),
  (@b46, 1, 12, 'Sakau gi tai, kad kiekvienas iš jūsų sako: „Aš esu Pauliaus; o aš – Apolo; o aš – Kefo; o aš – Kristaus“.'),
  (@b46, 1, 13, 'Ar Kristus padalytas? Ar Paulius už jus buvo nukryžiuotas? Arba, ar buvote pakrikštyti Pauliaus vardan?'),
  (@b46, 1, 14, 'Dėkoju Dievui, kad nei vieno iš jūsų nepakrikštijau, išskyrus Krispą ir Gajų;'),
  (@b46, 1, 15, 'kad kas nesakytų, jog krikštijau savo paties vardan.'),
  (@b46, 1, 16, 'Pakrikštijau ir Stepono namiškius; be to, nežinau, ar ką kitą pakrikštijau.'),
  (@b46, 1, 17, 'Nes Kristus nesiuntė manęs krikštyti, bet skelbti evangeliją: ne žodžių išmintimi, kad Kristaus kryžius netaptų neveiksmingas.'),
  (@b46, 1, 18, 'Nes kryžiaus skelbimas tiems, kurie žūsta, yra kvailystė; bet mums, kurie esame išgelbėti, jis yra Dievo jėga.'),
  (@b46, 1, 19, 'Nes yra parašyta: „Aš sunaikinsiu išmintingųjų išmintį ir paversiu niekais protingųjų supratimą“.'),
  (@b46, 1, 20, 'Kur išmintingasis? Kur raštininkas? Kur šio pasaulio ginčininkas? Argi Dievas šio pasaulio išminties nepavertė kvailyste?'),
  (@b46, 1, 21, 'Nes kadangi Dievo išmintyje pasaulis išmintimi nepažino Dievo, tai Dievui patiko skelbimo kvailumu išgelbėti tuos, kurie tiki.'),
  (@b46, 1, 22, 'Nes žydai reikalauja ženklo, o graikai ieško išminties,'),
  (@b46, 1, 23, 'bet mes skelbiame Kristų nukryžiuotą – žydams kliuvinį, o graikams – kvailystę;'),
  (@b46, 1, 24, 'bet tiems, kurie yra pašaukti, tiek žydams, tiek graikams, Kristų – Dievo jėgą ir Dievo išmintį.'),
  (@b46, 1, 25, 'Nes Dievo kvailystė yra išmintingesnė už žmones; ir Dievo silpnybė yra stipresnė už žmones.'),
  (@b46, 1, 26, 'Nes matote savo pašaukimą, broliai, kad nedaug išmintingųjų pagal kūną, nedaug galingų, nedaug kilmingų yra pašauktų;'),
  (@b46, 1, 27, 'bet Dievas išsirinko tai, kas pasaulyje kvaila, kad sugėdintų kas išmintinga; ir Dievas išsirinko tai, kas pasaulyje silpna, kad sugėdintų tai, kas galinga;'),
  (@b46, 1, 28, 'ir tai, kas pasaulyje prasta, ir tai, kas paniekinta, išsirinko Dievas, taip, ir tai, ko nėra, kad paverstų niekais tai, kas yra;'),
  (@b46, 1, 29, 'kad joks kūnas nesigirtų jo akivaizdoje.'),
  (@b46, 1, 30, 'Bet iš jo jūs esate Kristuje Jėzuje, kuris nuo Dievo mums padarytas išmintimi, teisumu, pašventimu ir atpirkimu;'),
  (@b46, 1, 31, 'kad pagal tai, kas yra parašyta: „Kas giriasi, tesigiria Viešpatyje“.'),
  (@b46, 2, 1, 'Ir aš, broliai, kai atėjau pas jus, neatėjau kalbos ar išminties puikumu, skelbdamas jums Dievo liudijimą.'),
  (@b46, 2, 2, 'Nes nusprendžiau tarp jūsų nieko nežinoti, išskyrus Jėzų Kristų, ir jį nukryžiuotą.'),
  (@b46, 2, 3, 'Ir buvau pas jus silpnume, baimėje ir labai drebėdamas.'),
  (@b46, 2, 4, 'Ir mano kalba bei mano skelbimas buvo ne viliojančiais žmogaus išminties žodžiais, bet Dvasios ir jėgos parodymu:'),
  (@b46, 2, 5, 'kad jūsų tikėjimas stovėtų ne žmonių išmintyje, bet Dievo jėgoje.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b46, 2, 6, 'Nors mes kalbame išmintį tarp tobulųjų, tačiau ne šio pasaulio išmintį nei šio pasaulio kunigaikščių, kurie eina niekais;'),
  (@b46, 2, 7, 'bet mes kalbame Dievo išmintį paslaptyje, tai yra, paslėptą išmintį, kurią Dievas anksčiau pasaulio paskyrė mūsų šlovei;'),
  (@b46, 2, 8, 'kurios niekas iš šio pasaulio kunigaikščių nežinojo, nes jeigu jie būtų ją žinoję, jie nebūtų nukryžiavę šlovės Viešpaties.'),
  (@b46, 2, 9, 'Bet kaip yra parašyta: „Akis nematė, nei ausis negirdėjo, nei į žmogaus širdį neįėjo tai, ką Dievas paruošė tiems, kurie jį myli“.'),
  (@b46, 2, 10, 'Bet Dievas mums tai atskleidė savo Dvasia, nes Dvasia ištiria visa, taip, Dievo gelmes.'),
  (@b46, 2, 11, 'Nes kuris žmogus žino tai, kas yra žmogaus, jei ne žmogaus dvasia, esanti jame? Taip ir to, kas Dievo, niekas nežino, bet tik Dievo Dvasia.'),
  (@b46, 2, 12, 'Mes gi gavome ne pasaulio dvasią, bet Dvasią, kuri yra iš Dievo; kad pažintume tai, kas mums nuo Dievo dovanota.'),
  (@b46, 2, 13, 'Tai mes ir kalbame – ne tais žodžiais, kurių moko žmogaus išmintis, bet kurių moko Šventoji Dvasia – gretinant dvasinius dalykus su dvasiniais.'),
  (@b46, 2, 14, 'Bet prigimtinis žmogus nepriima to, kas iš Dievo Dvasios, nes tai jam yra kvailystė; nei negali jis to suprasti, nes tai yra dvasiškai vertinama.'),
  (@b46, 2, 15, 'Bet dvasiškasis sprendžia apie viską, tačiau niekas negali spręsti apie jį.'),
  (@b46, 2, 16, 'Nes kas gi pažino Viešpaties protą, kad jis pamokytų jį? Bet mes turime Kristaus protą.'),
  (@b46, 3, 1, 'Ir aš, broliai, negalėjau jums kalbėti kaip dvasiškiems, bet kaip kūniškiems – kaip kūdikiams Kristuje.'),
  (@b46, 3, 2, 'Maitinau jus pienu, o ne kietu maistu; nes ligi šiolei nebuvote pajėgūs jo pakelti, nei dabar dar nesate pajėgūs.'),
  (@b46, 3, 3, 'Nes tebesate kūniški; nes kadangi tarp jūsų yra pavydas, vaidai ir susiskaldymai, argi nesate kūniški ir nevaikštote kaip žmonės?'),
  (@b46, 3, 4, 'Nes kai vienas sako: „Aš esu Pauliaus“, o kitas: „Aš esu Apolo“, argi jūs ne kūniški?'),
  (@b46, 3, 5, 'Kas tad yra Paulius ir kas Apolas? Tik tarnai, per kuriuos įtikėjote, – kaip Viešpats kiekvienam davė.'),
  (@b46, 3, 6, 'Aš sodinau, Apolas laistė; bet Dievas davė augimą.'),
  (@b46, 3, 7, 'Taigi nei tas, kuris sodina, yra kažkas, nei tas, kuris laisto; bet tik Dievas, kuris duoda augimą.'),
  (@b46, 3, 8, 'Tas gi, kuris sodina, ir tas, kuris laisto, yra viena; ir kiekvienas gaus savo atlygį pagal savo triūsą.'),
  (@b46, 3, 9, 'Nes mes esame darbininkai kartu su Dievu: jūs esate Dievo dirva, jūs esate Dievo pastatas.'),
  (@b46, 3, 10, 'Pagal Dievo man duotą malonę aš, kaip išmintingas vadovaujantis statytojas, padėjau pamatą, o kitas ant jo stato. Bet tegul kiekvienas žiūrisi, kaip ant jo stato.'),
  (@b46, 3, 11, 'Nes niekas negali dėti kito pamato, kaip tą, kuris padėtas, kuris yra Jėzus Kristus.'),
  (@b46, 3, 12, 'Na, o jei kas ant šito pamato stato auksą, sidabrą, brangiuosius akmenis, medį, šieną, šiaudus;'),
  (@b46, 3, 13, 'kiekvieno darbas išaiškės, nes diena jį paskelbs, kadangi jis bus atskleistas ugnimi; ir ugnis ištirs kiekvieno darbą, koks jis yra.'),
  (@b46, 3, 14, 'Jei kurio darbas išliks, kurį jis statė ant jo, tas gaus atlygį.'),
  (@b46, 3, 15, 'Jei kurio darbas sudegs, tas patirs praradimą; bet jis pats bus išgelbėtas; tačiau taip, kaip per ugnį.'),
  (@b46, 3, 16, 'Ar nežinote, kad esate Dievo šventykla, ir kad jumyse gyvena Dievo Dvasia?'),
  (@b46, 3, 17, 'Jei kas teršia Dievo šventyklą, tą Dievas sunaikins; nes Dievo šventykla yra šventa, ir ta šventykla esate jūs.'),
  (@b46, 3, 18, 'Tegul niekas savęs neapgaudinėja. Jei kas tarp jūsų atrodo esąs išmintingas šiame pasaulyje, tepasidaro kvailiu, kad būtų išmintingas.'),
  (@b46, 3, 19, 'Nes šio pasaulio išmintis yra kvailystė pas Dievą. Nes yra parašyta: „Jis sugauna išmintinguosius jų pačių gudrybėje“.'),
  (@b46, 3, 20, 'Ir vėl: „Viešpats žino išmintingųjų mintis, kad jos yra tuščios“.'),
  (@b46, 3, 21, 'Todėl niekas tenesigiria žmonėmis. Nes viskas yra jūsų:'),
  (@b46, 3, 22, 'ar tai Paulius, ar Apolas, ar Kefas, ar pasaulis, ar gyvenimas, ar mirtis, ar dabartis, ar ateitis – viskas yra jūsų;'),
  (@b46, 3, 23, 'o jūs esate Kristaus; o Kristus Dievo.'),
  (@b46, 4, 1, 'Tegul kiekvienas laiko mus kaip Kristaus tarnautojais ir Dievo paslapčių ūkvedžiais.'),
  (@b46, 4, 2, 'Be to, iš ūkvedžių yra reikalaujama, kad kiekvienas rastųsi ištikimas.'),
  (@b46, 4, 3, 'Bet man tai mažmožis, kad būčiau teisiamas jūsų ar žmogaus teismo; taip, aš pats savęs neteisiu.'),
  (@b46, 4, 4, 'Nes aš pats nieko nežinau; tačiau tuo nesu išteisintas; bet tas, kuris mane teisia, yra Viešpats.'),
  (@b46, 4, 5, 'Todėl nieko neteiskite prieš laiką, kol Viešpats ateis, kuris išves į šviesą tai, kas tamsoje paslėpta, ir atskleis širdžių ketinimus; ir tada kiekvienas gaus pagyrimą iš Dievo.'),
  (@b46, 4, 6, 'O tai, broliai, jūsų labui vaizdžiai pritaikiau sau ir Apolui; kad mumyse išmoktumėte negalvoti apie žmones daugiau to, kas yra parašyta, kad niekas iš jūsų nesipūstų dėl vieno prieš kitą.'),
  (@b46, 4, 7, 'Nes kas gi tave skiria nuo kito? Ir ką gi turi, ko nebūtum gavęs? Na, o jei tai gavai, kodėl giriesi tarsi to negavęs?'),
  (@b46, 4, 8, 'Jūs jau sotūs, jūs jau turtingi, jūs be mūsų karaliavote; ir duok Dieve, kad būtumėte karaliavę, kad ir mes su jumis karaliautume.'),
  (@b46, 4, 9, 'Nes manau, kad Dievas mus, apaštalus, išstatė paskutiniais, tarsi paskirtus mirčiai; nes mes tapome reginiu pasauliui, angelams ir žmonėms.'),
  (@b46, 4, 10, 'Mes kvailiai dėl Kristaus, bet jūs išmintingi Kristuje; mes silpni, bet jūs stiprūs; jūs gerbiami, bet mes niekinami.'),
  (@b46, 4, 11, 'Iki pat šios valandos alkstame, trokštame, esame nuogi, esame mušami ir neturime tikros gyvenamos vietos;'),
  (@b46, 4, 12, 'ir triūsiame, dirbdami savo pačių rankomis; keikiami mes laiminame, persekiojami mes tai pakenčiame,'),
  (@b46, 4, 13, 'šmeižiami mes meldžiame; mes tapome pasaulio purvu, ir esame viso ko padugnės iki šios dienos.'),
  (@b46, 4, 14, 'Nerašau to, kad jus sugėdinčiau, bet kaip savo mylimus sūnus jus įspėju.'),
  (@b46, 4, 15, 'Nes, nors ir turėtumėte dešimt tūkstančių auklėtojų Kristuje, tačiau neturite daug tėvų; nes aš jus pagimdžiau Kristuje Jėzuje per evangeliją.'),
  (@b46, 4, 16, 'Todėl maldauju jus, būkite mano sekėjai.'),
  (@b46, 4, 17, 'Dėl to pasiunčiau pas jus Timotiejų, kuris yra mano mylimasis sūnus ir ištikimas Viešpatyje, kuris jums primins mano kelius, kurie yra Kristuje, kaip aš mokau visur, kiekvienoje bažnyčioje.'),
  (@b46, 4, 18, 'Na, o kai kurie yra pasipūtę, tartum neketinčiau pas jus ateiti.'),
  (@b46, 4, 19, 'Bet netrukus ateisiu pas jus, jei Viešpats norės, ir sužinosiu ne pasipūtėlių kalbą, bet jėgą.'),
  (@b46, 4, 20, 'Nes Dievo karalystė yra ne žodyje, bet jėgoje.'),
  (@b46, 4, 21, 'Ko norite? Ar man pas jus ateiti su lazda, ar meile ir romumo dvasia?'),
  (@b46, 5, 1, 'Bendrai kalbama, kad tarp jūsų yra paleistuvystė, ir tokia paleistuvystė, kokia nėra minima net tarp pagonių, kad kažkas turi savo tėvo žmoną.'),
  (@b46, 5, 2, 'Ir jūs esate pasipūtę, užuot nuliūdę, kad tas, kuris padarė šitą darbą, būtų pašalintas iš jūsų tarpo.'),
  (@b46, 5, 3, 'Nes aš iš tiesų nebūdamas pas jus kūnu, bet būdamas dvasia, jau nusprendžiau, tarsi būdamas su jumis, dėl to, kuris taip padarė šitą darbą,'),
  (@b46, 5, 4, 'mūsų Viešpaties Jėzaus Kristaus vardu, kai esate susirinkę jūs ir mano dvasia, su mūsų Viešpaties Jėzaus Kristaus jėga,'),
  (@b46, 5, 5, 'atiduoti tokį šėtonui – kūno sunaikinimui, kad dvasia būtų išgelbėta Viešpaties Jėzaus dieną.'),
  (@b46, 5, 6, 'Jūsų gyrimasis nėra geras. Ar nežinote, kad truputis raugo suraugina visą minkalą?'),
  (@b46, 5, 7, 'Todėl išvalykite senąjį raugą, kad būtumėte naujas minkalas, kaip esate nerauginti. Nes būtent Kristus – mūsų Apėjimas – yra paaukotas už mus;'),
  (@b46, 5, 8, 'todėl švęskime šventę ne su senu raugu nei su piktos valios ir nedorybės raugu; bet su nerauginta nuoširdumo ir tiesos duona.'),
  (@b46, 5, 9, 'Laiške rašiau jums nebendrauti su paleistuviais,'),
  (@b46, 5, 10, 'tačiau ne apskritai su šio pasaulio paleistuviais ar godžiais, ar plėšikais, ar su stabmeldžiais; nes tada jums reikėtų išeiti iš pasaulio.'),
  (@b46, 5, 11, 'Bet dabar jums parašiau nebendrauti, jei kuris, vadinamas broliu, būtų paleistuvis ar godus, ar stabmeldys, ar keikūnas, ar girtuoklis, ar plėšikas; su tokiu net nevalgykite.'),
  (@b46, 5, 12, 'Nes kas man darbo teisti ir tuos, kurie yra išorėje? Argi jūs teisiate ne tuos, kurie yra viduje?'),
  (@b46, 5, 13, 'Bet esančius išorėje Dievas teisia. Todėl pašalinkite tą nedorėlį iš savo tarpo.'),
  (@b46, 6, 1, 'Drįsta kas iš jūsų, turėdamas reikalą prieš kitą, bylinėtis akivaizdoje neteisiųjų, o ne akivaizdoje šventųjų?'),
  (@b46, 6, 2, 'Ar nežinote, kad šventieji teis pasaulį? O jei pasaulis bus teisiamas jūsų, argi jūs neverti spręsti mažiausių reikalų?'),
  (@b46, 6, 3, 'Ar nežinote, kad mes teisime angelus? Tai kaip juo labiau dalykus, susijusius su šiuo gyvenimu?'),
  (@b46, 6, 4, 'Tad jei turite teismų dėl dalykų, susijusių su šiuo gyvenimu, paskirkite kad teistų tie, kurie mažiausiai vertinami bažnyčioje.'),
  (@b46, 6, 5, 'Kalbu jūsų gėdai. Ar taip yra, kad tarp jūsų nėra išmintingo? Ar nei vieno, kuris galėtų teisti tarp savo brolių?'),
  (@b46, 6, 6, 'Bet brolis su broliu bylinėjasi, ir tai netikinčiųjų akivaizdoje.'),
  (@b46, 6, 7, 'Todėl tai jau visiška yda jūsų tarpe, kad vienas su kitu bylinėjatės. Kodėl jums verčiau nepakęsti skriaudos? Kodėl verčiau nesiduodate apgaunami?'),
  (@b46, 6, 8, 'Ne, jūs skriaudžiate ir apgaunate, ir tai savo brolius.'),
  (@b46, 6, 9, 'Ar nežinote, kad neteisieji nepaveldės Dievo karalystės? Neapsigaukite: nei paleistuviai, nei stabmeldžiai, nei svetimautojai, nei sumoterėję, nei save tvirkinantys su vyriška lytimi,'),
  (@b46, 6, 10, 'nei vagys, nei godūs, nei girtuokliai, nei keikūnai, nei plėšikai nepaveldės Dievo karalystės.'),
  (@b46, 6, 11, 'O tokie buvote kai kurie iš jūsų; bet jūs nuplauti, bet jūs pašvęsti, bet jūs išteisinti Viešpaties Jėzaus vardu ir mūsų Dievo Dvasia.'),
  (@b46, 6, 12, 'Viskas man yra teisėta, bet ne viskas naudinga: viskas man yra teisėta, bet aš nesiduosiu užvaldomas jokio dalyko.'),
  (@b46, 6, 13, 'Valgiai yra pilvui, ir pilvas yra valgiams; bet Dievas sunaikins ir jį, ir juos. Kūnas gi ne paleistuvystei, bet Viešpačiui; o Viešpats – kūnui.'),
  (@b46, 6, 14, 'O Dievas prikėlė tiek Viešpatį, tiek ir mus prikels savo jėga.'),
  (@b46, 6, 15, 'Ar nežinote, kad jūsų kūnai yra Kristaus nariai? Ar tad imsiu Kristaus narius ir paversiu juos paleistuvės nariais? Jokiu būdu!'),
  (@b46, 6, 16, 'Ką? Ar nežinote, kad tas, kuris susijungęs su paleistuve, yra vienas kūnas? Nes du, – sako jis, – bus vienas kūnas.'),
  (@b46, 6, 17, 'Bet tas, kuris susijungęs su Viešpačiu, yra viena dvasia.'),
  (@b46, 6, 18, 'Bėkite nuo paleistuvystės. Kiekviena nuodėmė, kurią žmogus daro, yra kūno išorėje; bet tas, kuris paleistuvauja, nusideda prieš savo kūną.'),
  (@b46, 6, 19, 'Ką? Ar nežinote, kad jūsų kūnas yra šventykla Šventosios Dvasios, esančios jumyse, kurią turite iš Dievo, ir jūs nesate savo pačių?'),
  (@b46, 6, 20, 'Nes esate nupirkti už kainą; todėl šlovinkite Dievą savo kūne ir savo dvasioje, kurie yra Dievo.'),
  (@b46, 7, 1, 'Na, o dėl to, apie ką man rašėte; yra gerai vyrui neliesti moters.'),
  (@b46, 7, 2, 'Tačiau paleistuvavimui išvengti tegul kiekvienas vyras turi savo žmoną ir tegul kiekviena moteris turi savo vyrą.'),
  (@b46, 7, 3, 'Tegul vyras suteikia žmonai priklausantį palankumą; taip pat ir žmona vyrui.'),
  (@b46, 7, 4, 'Žmona neturi valdžios savo kūnui, bet vyras; taip pat ir vyras neturi valdžios savo kūnui, bet žmona.'),
  (@b46, 7, 5, 'Neatimkite vienas kito; išskyrus jei tai būtų sutikimu laikui, kad atsiduotumėte pasninkui ir maldai; ir vėl susieikite, kad šėtonas jūsų negundytų dėl jūsų nesusilaikymo.'),
  (@b46, 7, 6, 'Bet tai kalbu leidimu, o ne įsakymu.'),
  (@b46, 7, 7, 'Nes norėčiau, kad visi žmonės būtų tokie, kaip ir aš. Bet kiekvienas turi iš Dievo sau būdingą dovaną, vienas vienokią, o kitas kitokią.'),
  (@b46, 7, 8, 'Todėl sakau nesusituokusiems ir našlėms: gerai jiems, jeigu jie pasilieka tokie, kaip ir aš.'),
  (@b46, 7, 9, 'Bet jei jie negali susilaikyti, tegul tuokiasi; nes geriau yra tuoktis, negu degti.'),
  (@b46, 7, 10, 'O susituokusiems įsakau, tačiau ne aš, bet Viešpats: tegul žmona neišeina iš savo vyro;'),
  (@b46, 7, 11, 'bet jei ji išeitų, tepasilieka netekėjusi arba tesusitaiko su savo vyru, ir vyras tenepašalina savo žmonos.'),
  (@b46, 7, 12, 'Bet kitiems kalbu aš, ne Viešpats: jei kuris brolis turi netikinčią žmoną, ir jai patinka gyventi su juo, tegul jis jos nepašalina.'),
  (@b46, 7, 13, 'Ir moteris, turinti netikintį vyrą, ir jeigu jam patinka su ja gyventi, tegul ji jo nepalieka.'),
  (@b46, 7, 14, 'Nes netikintis vyras yra pašvęstas per žmoną, ir netikinti žmona yra pašvęsta per vyrą: kitaip jūsų vaikai būtų nešvarūs; bet dabar jie yra šventi.'),
  (@b46, 7, 15, 'Bet jei netikintis išeina, tegul išeina. Tokiais atvejais brolis ar sesuo nėra vergovėje; bet Dievas pašaukė mus taikai.'),
  (@b46, 7, 16, 'Nes ką tu žinai, o žmona, ar išgelbėsi savo vyrą? Arba kaip tu žinai, o vyre, ar išgelbėsi savo žmoną?'),
  (@b46, 7, 17, 'Bet kaip Dievas paskirstė kiekvienam, kaip Viešpats pašaukė kiekvieną, taip jis tevaikšto. Ir taip aš tvarkau visose bažnyčiose.'),
  (@b46, 7, 18, 'Ar kuris pašauktas būdamas apipjaustytas? Tenetampa neapipjaustytu. Ar kuris pašauktas neapipjaustyme? Tenebūna apipjaustytas.'),
  (@b46, 7, 19, 'Apipjaustymas yra niekas ir neapipjaustymas yra niekas, bet Dievo įsakymų laikymasis.'),
  (@b46, 7, 20, 'Kiekvienas tepasilieka tam pačiam pašaukime, kuriame buvo pašauktas.'),
  (@b46, 7, 21, 'Ar esi pašauktas būdamas tarnu? Nesirūpink tuo, bet jei gali tapti laisvu, verčiau tuo pasinaudok.'),
  (@b46, 7, 22, 'Nes tas, kuris pašauktas Viešpatyje būdamas tarnu, yra Viešpaties laisvasis; taip pat ir tas, kuris pašauktas būdamas laisvu, yra Kristaus tarnas.'),
  (@b46, 7, 23, 'Jūs nupirkti už kainą; nebūkite žmonių tarnais.'),
  (@b46, 7, 24, 'Broliai, kame kiekvienas yra pašauktas, tame tepasilieka prieš Dievą.'),
  (@b46, 7, 25, 'Na, o dėl mergelių neturiu Viešpaties įsakymo; tačiau pateikiu savo sprendimą, kaip gavusysis Viešpaties gailestingumą būti ištikimu.'),
  (@b46, 7, 26, 'Todėl manau, kad yra gerai dėl dabartinio sielvarto, sakau, kad gerai žmogui tokiam būti.'),
  (@b46, 7, 27, 'Esi susietas su žmona? Neieškok atsilaisvinimo. Esi atsilaisvinęs nuo žmonos? Neieškok žmonos.'),
  (@b46, 7, 28, 'Bet jei ir apsivedi, nenusidedi; ir jei mergelė išteka, nenusideda. Tačiau tokie turės vargą kūne; bet aš jus tausoju.'),
  (@b46, 7, 29, 'Bet sakau tai, broliai: laikas trumpas; ir belieka, kad tie, kurie turi žmonas, būtų tarsi neturėtų;'),
  (@b46, 7, 30, 'ir tie, kurie verkia, tarsi neverktų; ir tie, kurie džiaugiasi, tarsi nesidžiaugtų; ir tie, kurie perka, tarsi neturėtų;'),
  (@b46, 7, 31, 'ir tie, kurie naudojasi šiuo pasauliu, tarsi juo nepiktnaudžiautų; nes šio pasaulio pavidalas praeina.'),
  (@b46, 7, 32, 'Bet noriu, kad nebūtumėte susirūpinę. Kas nevedęs, rūpinasi Viešpačiui priklausančiais dalykais, kaip galėtų patikti Viešpačiui;'),
  (@b46, 7, 33, 'o vedęs rūpinasi pasaulio dalykais, kaip galėtų patikti savo žmonai.'),
  (@b46, 7, 34, 'Yra skirtumas ir tarp žmonos bei mergelės. Netekėjusi moteris rūpinasi Viešpaties dalykais, kad būtų šventa ir kūne, ir dvasioje; o ištekėjusi rūpinasi pasaulio dalykais, kaip galėtų patikti savo vyrui.'),
  (@b46, 7, 35, 'Bet tai kalbu jūsų pačių naudai; ne tam, kad paspęsčiau jums spąstus, o dėl to, kas tinkama, ir kad galėtumėte neblaškomi tarnauti Viešpačiui.'),
  (@b46, 7, 36, 'Bet jei kas mano, kad netinkamai elgiasi su savo mergele, jeigu ji peraugo savo amžiaus žydėjimą, ir taip reikalauja poreikis, tedaro kaip nori, jis nenusideda: tegul jie tuokiasi.'),
  (@b46, 7, 37, 'Tačiau tas, kuris tvirtai stovi savo širdyje, neturėdamas būtinybės, bet turi valdžią savo valiai ir taip nutarė savo širdyje, kad išlaikys savo mergelę, daro gerai.'),
  (@b46, 7, 38, 'Taigi tas, kuris duoda ją vedyboms, daro gerai; bet tas, kuris neduoda jos vedyboms, daro geriau.'),
  (@b46, 7, 39, 'Žmona surišta įstatymu tol, kol gyvena jos vyras; bet jei jos vyras būtų miręs, ji yra laisva ištekėti už ko nori; tiktai Viešpatyje.'),
  (@b46, 7, 40, 'Bet ji laimingesnė, jeigu ji taip pasilieka, pagal mano sprendimą; ir aš taip pat manau, kad turiu Dievo Dvasią.'),
  (@b46, 8, 1, 'Na, o dėl dalykų, atnašaujamų stabams, žinome, kad visi turime pažinimą. Pažinimas išpučia, bet meilė statydina.'),
  (@b46, 8, 2, 'Ir jei kas mano, kad ką nors žino, jis dar nieko nežino, kaip turi pažinoti.'),
  (@b46, 8, 3, 'Bet jei kuris myli Dievą, tas yra jo pažintas.'),
  (@b46, 8, 4, 'Taigi dėl stabams paaukotų dalykų valgymo žinome, kad stabas yra niekas pasaulyje, ir kad nėra kito Dievo, bet tik vienas.'),
  (@b46, 8, 5, 'Nes nors yra kurie vadinami dievais ar danguje, ar žemėje (kaip yra daug dievų ir daug viešpačių),'),
  (@b46, 8, 6, 'bet mums yra tik vienas Dievas, Tėvas, iš kurio yra visa ir mes jame; ir vienas Viešpats Jėzus Kristus, per kurį yra visa ir mes per jį.'),
  (@b46, 8, 7, 'Tačiau ne kiekviename yra tas pažinimas; nes kai kurie su stabo sąžine iki šios valandos valgo tai kaip dalyką, paaukotą stabui; ir jų sąžinė, būdama silpna, suteršiama.'),
  (@b46, 8, 8, 'Bet valgis mūsų negiria Dievui; nes nei kai valgome, nesame geresni; nei kai nevalgome, nesame blogesni.'),
  (@b46, 8, 9, 'Bet žiūrėkite, kad ši jūsų laisvė kokiu tai būdu netaptų kliūtimi tiems, kurie yra silpni.'),
  (@b46, 8, 10, 'Nes jei kas tave, turintį pažinimą, mato sėdintį prie valgio stabų šventykloje, argi sąžinė to, kuris yra silpnas, nebus padrąsinta valgyti dalykų, paaukotų stabams;'),
  (@b46, 8, 11, 'ir per tavo pažinimą pražus silpnasis brolis, už kurį mirė Kristus?'),
  (@b46, 8, 12, 'Bet taip nusidėdami prieš brolius ir sužeisdami jų silpną sąžinę, nusidedate prieš Kristų.'),
  (@b46, 8, 13, 'Todėl jei valgis piktina mano brolį, aš nevalgysiu mėsos kol esti pasaulis, idant nepapiktinčiau savo brolio.'),
  (@b46, 9, 1, 'Ar aš ne apaštalas? Ar aš ne laisvas? Ar aš nemačiau Jėzaus Kristaus, mūsų Viešpaties? Ar ne jūs esate mano darbas Viešpatyje?'),
  (@b46, 9, 2, 'Jei nesu apaštalas kitiems, tačiau neabejotinai jums esu; nes jūs esate mano apaštalystės antspaudas Viešpatyje.'),
  (@b46, 9, 3, 'Mano apsigynimas prieš tuos, kurie mane tiria, yra šis:'),
  (@b46, 9, 4, 'ar neturime teisės valgyti ir gerti?'),
  (@b46, 9, 5, 'Ar neturime teisės vedžiotis seserį, žmoną, kaip ir kiti apaštalai ir kaip Viešpaties broliai, ir Kefas?'),
  (@b46, 9, 6, 'Arba, ar vien tik aš ir Barnabas neturime teisės nedirbti?'),
  (@b46, 9, 7, 'Kas kada nors kariauja už savo išlaidas? Kas sodina vynuogyną, o nevalgo jo vaisių? Arba, kas gano kaimenę, o nesimaitina kaimenės pienu?'),
  (@b46, 9, 8, 'Ar tai sakau kaip žmogus? Ar to paties nesako ir įstatymas?'),
  (@b46, 9, 9, 'Nes yra parašyta Mozės įstatyme: „Neužrišk nasrų jaučiui, minančiam javus“. Ar Dievas rūpinasi jaučiais?'),
  (@b46, 9, 10, 'Ar jis sako tai apskritai mūsų labui? Mūsų labui, be abejo, tai yra parašyta, kad ariantis artų su viltimi; ir kad su viltimi kuliantis būtų savo vilties dalininkas.'),
  (@b46, 9, 11, 'Jei mes jums pasėjome dvasiškų dalykų, tai ar didelis dalykas, jei pjausime jūsų kūniškų dalykų?'),
  (@b46, 9, 12, 'Jei kiti yra dalininkai šios teisės į jus, ar mes ne juo labiau? Tačiau mes nesinaudojome šia teise, bet pakenčiame viską, kad nekliudytume Kristaus evangelijai.'),
  (@b46, 9, 13, 'Ar nežinote, kad tie, kurie tarnauja prie to, kas šventa, gyvena iš šventyklos dalykų? Ir tarnaujantys prie aukuro yra dalininkai su aukuru?'),
  (@b46, 9, 14, 'Taip ir Viešpats patvarkė, kad tie, kurie skelbia evangeliją, gyventų iš evangelijos.'),
  (@b46, 9, 15, 'Bet aš iš to niekuo nesinaudojau nei to nerašiau, kad man taip būtų padaryta; nes man geriau būtų numirti, negu kad kas paverstų mano gyrimąsi nieku.'),
  (@b46, 9, 16, 'Nes nors ir skelbiu evangeliją, neturiu kuo pasigirti, nes būtinybė guli ant manęs; taip, vargas man, jei neskelbčiau evangelijos!'),
  (@b46, 9, 17, 'Nes jei tai darau noriai, turiu atlygį; bet jei prieš savo valią, tai man yra patikėta evangelijos ūkvedyba.'),
  (@b46, 9, 18, 'Koks tad mano atlygis? Iš tiesų tai, kad kai skelbiu evangeliją, galiu padaryti Kristaus evangeliją nemokama, kad nesinaudočiau savo teise evangelijoje.'),
  (@b46, 9, 19, 'Nes, nors esu laisvas nuo visų, tačiau pasidariau save tarnu visiems, kad laimėčiau daugiau.'),
  (@b46, 9, 20, 'Ir žydams tapau kaip žydas, kad laimėčiau žydus; tiems, kurie yra įstatymo valdžioje, kaip esantis įstatymo valdžioje, kad laimėčiau esančius įstatymo valdžioje;'),
  (@b46, 9, 21, 'esantiems be įstatymo, kaip be įstatymo (nebūdamas be įstatymo Dievui, bet Kristui – įstatymo valdžioje), kad laimėčiau esančius be įstatymo.'),
  (@b46, 9, 22, 'Silpniems tapau kaip silpnas, kad laimėčiau silpnuosius – visiems tapau viskuo, kad visokiais būdais kai kuriuos išgelbėčiau.'),
  (@b46, 9, 23, 'Ir tai darau evangelijos labui, kad su jumis būčiau jos dalininku.'),
  (@b46, 9, 24, 'Ar nežinote, kad tie, kurie bėga lenktynėse, bėga visi, bet vienas gauna prizą? Taip bėkite, kad gautumėte.'),
  (@b46, 9, 25, 'Ir kiekvienas, kovojantis dėl pranašumo, nuo visko susilaiko. Jie gi tai daro, kad gautų gendantį vainiką; bet mes negendantį.'),
  (@b46, 9, 26, 'Todėl taip bėgu, ne kaip netikrai; taip kovoju, ne kaip smūgiuojantis į orą;'),
  (@b46, 9, 27, 'bet tramdau savo kūną ir atiduodu jį klusnumui, kad kitiems skelbdamas pats kokiu nors būdu nebūčiau atmestinas.'),
  (@b46, 10, 1, 'Be to, broliai, nenoriu, kad būtumėte nežinantys, kaip visi mūsų tėvai buvo po debesimi ir visi perėjo per jūrą;'),
  (@b46, 10, 2, 'ir visi buvo pakrikštyti Mozei debesyje ir jūroje;'),
  (@b46, 10, 3, 'ir visi valgė tą patį dvasinį maistą;'),
  (@b46, 10, 4, 'ir visi gėrė tą patį dvasinį gėrimą; nes jie gėrė iš tos dvasinės Uolos, kuri sekė paskui juos; ir ta Uola buvo Kristus.'),
  (@b46, 10, 5, 'Bet daugeliu iš jų Dievas buvo nelabai patenkintas; nes jie buvo sunaikinti dykumoje.'),
  (@b46, 10, 6, 'Tie gi dalykai buvo mūsų pavyzdžiai tam, kad negeistume to, kas pikta, kaip jie geidė.'),
  (@b46, 10, 7, 'Ir nebūkite stabmeldžiai, kaip buvo kai kurie iš jų; kaip yra parašyta: „Tauta sėdosi valgyti ir gerti, ir kėlėsi žaisti“.'),
  (@b46, 10, 8, 'Ir nepaleistuvaukime kaip kai kurie iš jų paleistuvavo, ir vieną dieną krito dvidešimt trys tūkstančiai.'),
  (@b46, 10, 9, 'Ir negundykime Kristaus kaip ir kai kurie iš jų gundė ir buvo gyvačių sunaikinti.'),
  (@b46, 10, 10, 'Ir nemurmėkite kaip ir kai kurie iš jų murmėjo ir buvo naikintojo sunaikinti.'),
  (@b46, 10, 11, 'Na, o visa tai jiems atsitiko kaip pavyzdžiai, ir tai yra surašyta perspėjimui mums, kuriems pasaulio pabaigos atėję.'),
  (@b46, 10, 12, 'Todėl tas, kuris galvoja stovįs, težiūrisi, kad negriūtų.'),
  (@b46, 10, 13, 'Jūsų nėra ištikusi kitokia pagunda nei tokia, kuri įprasta žmogui; bet Dievas yra ištikimas, kuris neleis jums būti gundomiems virš jūsų pajėgumo; bet su pagunda parūpins ir išeitį, kad pajėgtumėte ją pakelti.'),
  (@b46, 10, 14, 'Todėl, mano brangiai mylimi, bėkite nuo stabmeldystės.'),
  (@b46, 10, 15, 'Kalbu kaip išmintingiems; apsvarstykite, ką sakau.'),
  (@b46, 10, 16, 'Laiminimo taurė, kurią laiminame, ar ji nėra Kristaus kraujo bendrystė? Duona, kurią laužome, ar ji nėra Kristaus kūno bendrystė?'),
  (@b46, 10, 17, 'Nes mes, daugelis, esame viena duona ir vienas kūnas; nes visi esame tos vienos duonos dalininkai.'),
  (@b46, 10, 18, 'Štai Izraelis pagal kūną: argi tie, kurie valgo iš aukų, nėra aukuro dalininkai?'),
  (@b46, 10, 19, 'Tad ką sakau? Ar kad stabas yra kažkas, ar tai, kas yra paaukota stabams, yra kažkas?'),
  (@b46, 10, 20, 'Bet sakau, kad tai, ką pagonys aukoja, aukoja velniams, o ne Dievui; o aš nenoriu, kad turėtumėte bendrystę su velniais.'),
  (@b46, 10, 21, 'Jūs negalite gerti Viešpaties taurės ir velnių taurės; jūs negalite būti dalininkai Viešpaties stalo ir velnių stalo.'),
  (@b46, 10, 22, 'Ar kurstysime Viešpaties pavydą? Ar esame už jį stipresni?'),
  (@b46, 10, 23, 'Viskas man teisėta, bet ne viskas naudinga; viskas man teisėta, bet ne viskas statydina.'),
  (@b46, 10, 24, 'Nei vienas teneieško savo, bet kiekvienas kito gerovės.'),
  (@b46, 10, 25, 'Valgykite tai, kas parduodama mėsos turguose, neklausinėdami jokių klausimų sąžinės labui;'),
  (@b46, 10, 26, 'nes Viešpaties yra žemė ir jos pilnumas.'),
  (@b46, 10, 27, 'Jei kas iš netikinčių jus pakviečia į puotą, ir jūs nusiteikę eiti; valgykite viską, kas prieš jus padėta, neklausinėdami jokių klausimų sąžinės labui.'),
  (@b46, 10, 28, 'Bet jei kas jums sakytų: „Tai yra paaukota stabams“, nevalgykite labui to, kuris tai pasakė, ir sąžinės labui; nes žemė yra Viešpaties, ir jos pilnumas;'),
  (@b46, 10, 29, 'sąžinės, sakau, ne tavo, bet kito; nes kodėl mano laisvė yra teisiama kito sąžinės?'),
  (@b46, 10, 30, 'Nes jei per malonę esu dalininkas, kodėl esu piktai apkalbamas už tai, už ką dėkoju?'),
  (@b46, 10, 31, 'Todėl ar valgote, ar geriate, ar ką bedarote, visa darykite Dievo šlovei.'),
  (@b46, 10, 32, 'Nepiktinkite nei žydų, nei pagonių, nei Dievo bažnyčios;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b46, 10, 33, 'kaip ir aš visiems viskuo įtinku, neieškodamas savo naudos, bet naudos daugelio, kad jie būtų išgelbėti.'),
  (@b46, 11, 1, 'Būkite mano sekėjai, kaip ir aš esu Kristaus.'),
  (@b46, 11, 2, 'Giriu gi jus, broliai, kad prisimenate mane visame kame ir laikotės įsakų, kaip jums juos perdaviau.'),
  (@b46, 11, 3, 'Bet noriu, kad žinotumėte, jog kiekvieno vyro galva yra Kristus; o moters galva yra vyras; o Kristaus galva yra Dievas.'),
  (@b46, 11, 4, 'Kiekvienas vyras, melsdamasis ar pranašaudamas apdengta galva, suteikia negarbę savo galvai.'),
  (@b46, 11, 5, 'Bet kiekviena moteris, kuri meldžiasi ar pranašauja atidengta galva, suteikia negarbę savo galvai; nes tai yra vienas ir tas pats, kaip kad ji būtų nuskusta.'),
  (@b46, 11, 6, 'Nes jei moteris nėra apsidengusi, tai ir tenusikerpa; bet jei moteriai būtų gėda būti nukirptai ar nuskustai, teapsidengia.'),
  (@b46, 11, 7, 'Nes vyras iš tiesų neturi apsidengti galvos, kadangi jis yra Dievo atvaizdas ir šlovė; bet moteris yra vyro šlovė.'),
  (@b46, 11, 8, 'Nes vyras nėra iš moters; bet moteris iš vyro.'),
  (@b46, 11, 9, 'Taip pat vyras nebuvo sukurtas moteriai; bet moteris vyrui.'),
  (@b46, 11, 10, 'Dėl to moteris privalo turėti valdžią virš savo galvos dėl angelų.'),
  (@b46, 11, 11, 'Tačiau Viešpatyje nei vyras yra be moters, nei moteris be vyro.'),
  (@b46, 11, 12, 'Nes kaip moteris yra iš vyro, taip ir vyras yra per moterį; bet visa iš Dievo.'),
  (@b46, 11, 13, 'Spręskite patys: ar dera, kad moteris meldžiasi Dievui atsidengusi?'),
  (@b46, 11, 14, 'Argi net ir pati prigimtis jūsų nemoko, kad jei vyras turi ilgus plaukus, jam yra gėda?'),
  (@b46, 11, 15, 'Bet jei moteris turi ilgus plaukus, jai yra šlovė; nes jos plaukai jai duoti kaip apdangalas.'),
  (@b46, 11, 16, 'Bet jei kas atrodo mėgstąs ginčytis, mes neturime tokio papročio, nei Dievo bažnyčios.'),
  (@b46, 11, 17, 'Na, o tuo, ką jums pareiškiu, aš jūsų negiriu, kad susirenkate ne geresniam, bet blogesniam.'),
  (@b46, 11, 18, 'Nes pirmiausia, kai susirenkate bažnyčioje, girdžiu, kad tarp jūsų yra susiskaldymai; ir iš dalies tuo tikiu.'),
  (@b46, 11, 19, 'Nes tarp jūsų turi būti ir erezijų, kad tarp jūsų išaiškėtų tie, kurie yra išmėginti.'),
  (@b46, 11, 20, 'Taigi kai susirenkate į vieną vietą, tai ne Viešpaties vakarienės valgyti.'),
  (@b46, 11, 21, 'Nes valgyme kiekvienas pirmiau kito ima savo vakarienę; ir vienas yra alkanas, o kitas girtas.'),
  (@b46, 11, 22, 'Ką? Ar neturite namų valgyti ir gerti? Arba, ar niekinsite Dievo bažnyčią ir gėdinsite tuos, kurie neturi? Ką jums pasakysiu? Ar jus tame girsiu? Aš jūsų negiriu.'),
  (@b46, 11, 23, 'Nes aš gavau iš Viešpaties tai, ką jums ir perdaviau, kad Viešpats Jėzus tą naktį, kurią buvo išduotas, paėmė duoną'),
  (@b46, 11, 24, 'ir padėkojęs ją laužė, ir tarė: „Imkite, valgykite – tai yra mano kūnas, kuris už jus laužomas; tai darykite mano atminimui“.'),
  (@b46, 11, 25, 'Tokiu pat būdu, pavakarieniavęs jis paėmė ir taurę, sakydamas: „Ši taurė yra naujasis testamentas mano kraujyje – tai darykite tiek kartų, kiek ją gersite, mano atminimui“.'),
  (@b46, 11, 26, 'Nes kiek kartų valgote šią duoną ir geriate šią taurę, jūs skelbiate Viešpaties mirtį, kol jis ateis.'),
  (@b46, 11, 27, 'Todėl kas nevertai valgys šią duoną ir gers šią Viešpaties taurę, bus kaltas Viešpaties kūnu ir krauju.'),
  (@b46, 11, 28, 'Bet tegul žmogus save ištiria ir taip tevalgo iš tos duonos ir geria iš tos taurės.'),
  (@b46, 11, 29, 'Nes kas valgo ir geria nevertai, tas valgo ir geria sau pasmerkimą, neatskirdamas Viešpaties kūno.'),
  (@b46, 11, 30, 'Dėl to daugelis yra silpni ir sergantys tarp jūsų, ir daugelis miega.'),
  (@b46, 11, 31, 'Nes jei save teistume, nebūtume teisiami.'),
  (@b46, 11, 32, 'Bet kai esame teisiami, esame Viešpaties baudžiami, kad nebūtume pasmerkti su pasauliu.'),
  (@b46, 11, 33, 'Todėl, mano broliai, kai susirenkate valgyti, palaukite vienas kito.'),
  (@b46, 11, 34, 'O jei kas išalkęs, tepavalgo namie; kad nesusirinktumėte pasmerkimui. O visa kita sutvarkysiu kai atvyksiu.'),
  (@b46, 12, 1, 'Na, o dėl dvasinių dovanų, broliai, nenoriu, kad būtumėte nežinantys.'),
  (@b46, 12, 2, 'Jūs žinote, kad buvote pagonys, nešiojami pas tuos nebylius stabus, kaip ir buvote vedami.'),
  (@b46, 12, 3, 'Todėl duodu jums suprasti, kad nei vienas, kalbėdamas Dievo Dvasia, nevadina Jėzaus prakeiktu; ir kad nei vienas negali sakyti, kad Jėzus yra Viešpats, kaip tik Šventąja Dvasia.'),
  (@b46, 12, 4, 'Na, o yra dovanų įvairovės, bet ta pati Dvasia.'),
  (@b46, 12, 5, 'Ir yra tarnavimų skirtingumai, bet tas pats Viešpats.'),
  (@b46, 12, 6, 'Ir yra veikimų įvairovės, bet yra tas pats Dievas, kuris visa atlieka visuose.'),
  (@b46, 12, 7, 'Bet kiekvienam duotas Dvasios pasireiškimas, kad būtų nauda.'),
  (@b46, 12, 8, 'Nes vienam Dvasia yra duotas išminties žodis; kitam – pažinimo žodis ta pačia Dvasia;'),
  (@b46, 12, 9, 'kitam – tikėjimas ta pačia Dvasia; kitam – gydymo dovanos ta pačia Dvasia;'),
  (@b46, 12, 10, 'kitam – stebuklų darymas; kitam – pranašystė; kitam – dvasių atskyrimas; kitam – įvairios kalbų rūšys; kitam – kalbų vertimas;'),
  (@b46, 12, 11, 'bet visus šituos atlieka viena ir ta pati Dvasia, dalindama kiekvienam atskirai, kaip ji nori.'),
  (@b46, 12, 12, 'Nes kaip kūnas yra vienas ir turi daug narių, ir visi to vieno kūno nariai, būdami daugelis, yra vienas kūnas, taip yra ir Kristus.'),
  (@b46, 12, 13, 'Nes viena Dvasia mes visi esame pakrikštyti į vieną kūną, ar būtume žydai, ar pagonys, ar būtume vergai, ar laisvi; ir visiems buvo duota gerti į vieną Dvasią.'),
  (@b46, 12, 14, 'Nes kūnas nėra vienas narys, bet daug.'),
  (@b46, 12, 15, 'Jei koja sakytų: „Kadangi aš ne ranka, aš nesu iš kūno“; argi dėl to ji ne iš kūno?'),
  (@b46, 12, 16, 'Ir jei ausis sakytų: „Kadangi aš ne akis, aš nesu iš kūno“; argi dėl to ji ne iš kūno?'),
  (@b46, 12, 17, 'Jei visas kūnas būtų akis, kur būtų klausa? Jei visas būtų klausa, kur būtų uoslė?'),
  (@b46, 12, 18, 'Bet dabar Dievas sudėjo narius kiekvieną iš jų kūne kaip panorėjo.'),
  (@b46, 12, 19, 'Ir jeigu jie visi būtų vienas narys, kur būtų kūnas?'),
  (@b46, 12, 20, 'Bet dabar jie yra daug narių, bet tik vienas kūnas.'),
  (@b46, 12, 21, 'Ir akis negali pasakyti rankai: „Man tavęs nereikia“ nei vėlgi galva kojoms: „Man jūsų nereikia“.'),
  (@b46, 12, 22, 'Ne, tie kūno nariai, kurie atrodo silpnesni, yra daug reikalingesni;'),
  (@b46, 12, 23, 'ir tie kūno nariai, kurie, manome, yra mažiau gerbiami, tiems mes skiriame gausesnę garbę; ir mūsų nepatrauklūs nariai turi gausiau patrauklumo.'),
  (@b46, 12, 24, 'Nes mūsų patraukliems nariams nieko nereikia; bet Dievas sumaišė kūną kartu, davęs gausiau garbės tam nariui, kuriam trūksta;'),
  (@b46, 12, 25, 'kad kūne nebūtų susiskaldymo, bet kad nariai vienodai rūpintųsi vienas kitu.'),
  (@b46, 12, 26, 'Ir jei vienas narys kenčia, visi nariai kenčia su juo; arba jei vienas narys pagerbiamas, visi nariai džiaugiasi su juo.'),
  (@b46, 12, 27, 'Jūs gi esate Kristaus kūnas, o atskirai – nariai.'),
  (@b46, 12, 28, 'Ir kai kuriuos Dievas paskyrė bažnyčioje: pirma – apaštalais, antra – pranašais, trečia – mokytojais, po to – stebuklai, paskui – gydymų dovanos, pagalbos, valdymai, kalbų įvairovės.'),
  (@b46, 12, 29, 'Ar visi apaštalai? Ar visi pranašai? Ar visi mokytojai? Ar visi stebuklų darytojai?'),
  (@b46, 12, 30, 'Ar visi turi gydymo dovanas? Ar visi kalba kalbomis? Ar visi verčia?'),
  (@b46, 12, 31, 'Bet uoliai trokškite geriausių dovanų; o aš jums dar parodau pranašesnį kelią.'),
  (@b46, 13, 1, 'Nors kalbu žmonių bei angelų kalbomis, bet neturiu meilės, tampu kaip skambantis žalvaris arba žvangantys cimbolai.'),
  (@b46, 13, 2, 'Ir nors turiu pranašystės dovaną ir suprantu visas paslaptis ir visą pažinimą; ir nors turiu visą tikėjimą, kad galiu perkelti kalnus, bet neturiu meilės, esu niekas.'),
  (@b46, 13, 3, 'Ir nors atiduodu visus savo turtus vargšams pamaitinti, ir nors atiduodu savo kūną sudeginimui, bet neturiu meilės, tai man neduoda jokios naudos.'),
  (@b46, 13, 4, 'Meilė ilgai pakenčia ir yra maloni; meilė nepavydi; meilė nesigiria, nėra pasipūtusi,'),
  (@b46, 13, 5, 'nesielgia netinkamai, neieško savo, nėra lengvai suerzinama, negalvoja pikto;'),
  (@b46, 13, 6, 'nesidžiaugia neteisybe, bet džiaugiasi tiesa;'),
  (@b46, 13, 7, 'visa pakelia, visa tiki, viskuo viliasi, visa ištveria.'),
  (@b46, 13, 8, 'Meilė niekada nesibaigia, bet ar tai būtų pranašystės, jos pasibaigs; ar tai būtų kalbos, jos liausis; ar tai būtų pažinimas, jis pranyks.'),
  (@b46, 13, 9, 'Nes mes žinome iš dalies ir pranašaujame iš dalies.'),
  (@b46, 13, 10, 'Bet kai ateis tai, kas tobula, tada tai, kas iš dalies, bus panaikinta.'),
  (@b46, 13, 11, 'Kai buvau vaikas, kalbėjau kaip vaikas, supratau kaip vaikas, mąsčiau kaip vaikas; bet kai tapau vyru, atmečiau tai, kas vaikiška.'),
  (@b46, 13, 12, 'Nes dabar matome per stiklą, neaiškiai; bet tuomet – veidas į veidą; dabar pažįstu iš dalies, bet tuomet pažinsiu kaip ir esu pažintas.'),
  (@b46, 13, 13, 'O dabar pasilieka tikėjimas, viltis, meilė – tie trys; bet didžiausia iš jų – meilė.'),
  (@b46, 14, 1, 'Sekite meile ir trokškite dvasinių dovanų, bet verčiau – kad galėtumėte pranašauti.'),
  (@b46, 14, 2, 'Nes tas, kuris kalba nežinoma kalba, ne žmonėms kalba, bet Dievui; nes niekas jo nesupranta; bet jis dvasioje kalba paslaptis.'),
  (@b46, 14, 3, 'Bet tas, kuris pranašauja, kalba žmonėms statydinimui, paraginimui ir paguodai.'),
  (@b46, 14, 4, 'Kas kalba nežinoma kalba, save statydina; bet kas pranašauja, statydina bažnyčią.'),
  (@b46, 14, 5, 'Norėčiau, kad visi kalbėtumėte kalbomis, bet verčiau – kad pranašautumėte; nes kas pranašauja, yra didesnis už tą, kuris kalba kalbomis, nebent jis išverstų, idant bažnyčia gautų statydinimą.'),
  (@b46, 14, 6, 'Dabar, broliai, jei ateisiu pas jus kalbėdamas kalbomis, kokią jums duosiu naudą, jeigu jums nekalbėsiu ar tai apreiškimu, ar pažinimu, ar pranašavimu, ar mokslu?'),
  (@b46, 14, 7, 'Net ir negyvi daiktai, skleidžiantys garsą, ar tai dūda, ar arfa, jeigu jie nesuteiks skirtumo garsuose, kaipgi bus žinoma, kas yra dūduota arba arfa grota?'),
  (@b46, 14, 8, 'Nes jei trimitas duoda neaiškų garsą, kas ruošis į mūšį?'),
  (@b46, 14, 9, 'Taip pat ir jūs, jei neištarsite liežuviu lengvai suprantamų žodžių, kaipgi bus žinoma, kas yra kalbėta? Nes jūs kalbėsite į orą.'),
  (@b46, 14, 10, 'Yra galbūt tiek daug balsų rūšių pasaulyje, ir nei vienas iš jų nėra be reikšmės.'),
  (@b46, 14, 11, 'Todėl jei nežinau balso reikšmės, būsiu barbaras kalbančiajam, o kalbantysis bus man barbaras.'),
  (@b46, 14, 12, 'Taip pat ir jūs, kadangi esate uolūs dėl dvasinių dovanų, stenkitės būti pranašesni bažnyčios statydinimui.'),
  (@b46, 14, 13, 'Todėl kalbantysis nežinoma kalba tesimeldžia, kad galėtų versti.'),
  (@b46, 14, 14, 'Nes jei meldžiuosi nežinoma kalba, mano dvasia meldžiasi, bet mano supratimas yra bevaisis.'),
  (@b46, 14, 15, 'Tai ką gi tada? Aš melsiuosi dvasia ir taip pat melsiuosi supratimu; aš giedosiu dvasia ir taip pat giedosiu supratimu.'),
  (@b46, 14, 16, 'Kitaip, jei tu laiminsi dvasia, kaipgi tas, kuris užima nemokyto vietą, pasakys tavo dėkojimui „Amen“, kadangi nesupranta, ką sakai?'),
  (@b46, 14, 17, 'Nes tu iš tiesų gerai dėkoji, bet kitas nėra statydinamas.'),
  (@b46, 14, 18, 'Dėkoju savo Dievui, aš kalbu kalbomis daugiau nei jūs visi;'),
  (@b46, 14, 19, 'tačiau bažnyčioje verčiau ištarsiu penkis žodžius savo supratimu, kad savo balsu ir kitus mokyčiau, negu dešimt tūkstančių žodžių nežinoma kalba.'),
  (@b46, 14, 20, 'Broliai, nebūkite vaikai supratimu, tačiau piktybe būkite vaikai, bet supratimu būkite vyrai.'),
  (@b46, 14, 21, 'Įstatyme yra parašyta: „Per kitų kalbų ir kitų lūpų žmones kalbėsiu šiai tautai; tačiau ir dėl viso to jie manęs neklausys, – sako Viešpats“.'),
  (@b46, 14, 22, 'Todėl kalbos yra ženklui, ne tiems, kurie tiki, bet tiems, kurie netiki; bet pranašystė pasitarnauja ne tiems, kurie netiki, bet tiems, kurie tiki.'),
  (@b46, 14, 23, 'Todėl jei visa bažnyčia susirinktų į vieną vietą, ir visi kalbėtų kalbomis, ir įeitų tie, kurie yra nemokyti arba netikintys, argi jie nesakytų, kad esate išprotėję?'),
  (@b46, 14, 24, 'Bet jei visi pranašautų, ir įeitų netikintysis arba nemokytasis, jis būtų visų įtikintas, jis būtų visų nuteistas;'),
  (@b46, 14, 25, 'ir taip jo širdies paslaptys išaiškėtų; ir taip puldamas veidu žemyn, jis pagarbintų Dievą ir praneštų, kad Dievas iš tiesų yra jumyse.'),
  (@b46, 14, 26, 'Tad kaipgi, broliai? Kai susirenkate, kiekvienas iš jūsų turi psalmę, turi mokslą, turi kalbą, turi apreiškimą, turi vertimą. Viskas tebūna daroma statydinimui.'),
  (@b46, 14, 27, 'Jei kuris kalba nežinoma kalba, tebūna po du arba daugiausiai po tris, ir tai paeiliui; o vienas teišverčia.'),
  (@b46, 14, 28, 'Bet jei nėra vertėjo, tegul jis bažnyčioje tyli; ir tegul jis kalba sau ir Dievui.'),
  (@b46, 14, 29, 'Pranašai tekalba du arba trys, o kiti tegul vertina.'),
  (@b46, 14, 30, 'Jei kas apreiškiama kitam, šalia sėdinčiajam, pirmasis tenutyla.'),
  (@b46, 14, 31, 'Nes visi galite pranašauti vienas po kito, kad visi pasimokytų ir visi būtų paguosti.'),
  (@b46, 14, 32, 'Ir pranašų dvasios yra pavaldžios pranašams.'),
  (@b46, 14, 33, 'Nes Dievas yra ne sumaišties, bet ramybės autorius, kaip visose šventųjų bažnyčiose.'),
  (@b46, 14, 34, 'Tegul jūsų moterys tyli bažnyčiose, nes joms neleidžiama kalbėti; bet joms yra įsakyta būti paklusniomis, kaip sako ir įstatymas.'),
  (@b46, 14, 35, 'O jeigu jos nori ko nors išmokti, namuose teklausia savo vyrų; nes gėda moterims kalbėti bažnyčioje.'),
  (@b46, 14, 36, 'Ką? Ar iš jūsų atėjo Dievo žodis? Arba ar pas jus vienus jis atėjo?'),
  (@b46, 14, 37, 'Jei kas mano esąs pranašas ar dvasiškas, tas tepripažįsta, kad tai, ką jums rašau, yra Viešpaties įsakymai.'),
  (@b46, 14, 38, 'Bet jei kas yra nežinantis, tebūna nežinantis.'),
  (@b46, 14, 39, 'Todėl, broliai, trokškite pranašauti ir nedrauskite kalbėti kalbomis.'),
  (@b46, 14, 40, 'Viskas tebūna daroma padoriai ir pagal tvarką.'),
  (@b46, 15, 1, 'Be to, broliai, skelbiu jums tą evangeliją, kurią jums paskelbiau, kurią ir priėmėte, ir kurioje stovite;'),
  (@b46, 15, 2, 'kuria esate ir išgelbėti, jei saugojate atmintyje, ką jums paskelbiau, nebent įtikėjote tuščiai.'),
  (@b46, 15, 3, 'Nes jums perdaviau pirmiausiai tai, ką ir gavau, – kaip Kristus mirė už mūsų nuodėmes pagal Raštus;'),
  (@b46, 15, 4, 'ir kad buvo palaidotas, ir kad prisikėlė trečią dieną pagal Raštus;'),
  (@b46, 15, 5, 'ir kad buvo regėtas Kefo, paskui dvylikos;'),
  (@b46, 15, 6, 'po to buvo regėtas daugiau kaip penkių šimtų brolių vienu metu; iš kurių didesnė dalis išlikę iki dabar, bet kai kurie yra užmigę.'),
  (@b46, 15, 7, 'Po to buvo regėtas Jokūbo; paskui visų apaštalų.'),
  (@b46, 15, 8, 'O galiausiai iš visų buvo regėtas ir manęs, kaip nelaiku gimusio.'),
  (@b46, 15, 9, 'Nes esu mažiausias iš apaštalų, kuris nesu tinkamas vadintis apaštalu, nes persekiojau Dievo bažnyčią.'),
  (@b46, 15, 10, 'Bet Dievo malone esu kas esu, ir man suteikta jo malonė nebuvo bergždžia; bet aš triūsiau gausiau negu jie visi, tačiau ne aš, bet Dievo malonė, kuri buvo su manimi.'),
  (@b46, 15, 11, 'Todėl ar tai buvau aš, ar jie, taip mes skelbiame, ir taip jūs įtikėjote.'),
  (@b46, 15, 12, 'Na, o jei Kristus yra skelbiamas, kad prisikėlė iš numirusių, kaipgi kai kurie tarp jūsų sako, kad nėra mirusiųjų prisikėlimo?'),
  (@b46, 15, 13, 'Bet jei nėra mirusiųjų prisikėlimo, tai Kristus nėra prisikėlęs;'),
  (@b46, 15, 14, 'o jei Kristus nėra prisikėlęs, tai mūsų skelbimas tuščias, ir jūsų tikėjimas irgi tuščias.'),
  (@b46, 15, 15, 'Taip, ir esame randami melagingais Dievo liudytojais; nes liudijome apie Dievą, kad jis prikėlė Kristų, kurio jis neprikėlė, jei taip yra, kad mirusieji neprisikelia.'),
  (@b46, 15, 16, 'Nes jei mirusieji neprisikelia, tada Kristus nėra prikeltas;'),
  (@b46, 15, 17, 'o jei Kristus nėra prikeltas, jūsų tikėjimas yra tuščias; jūs tebesate savo nuodėmėse.'),
  (@b46, 15, 18, 'Tada ir tie, kurie užmigę Kristuje, yra pražuvę.'),
  (@b46, 15, 19, 'Jei tik šiame gyvenime turime viltį Kristuje, mes iš visų žmonių esame labiausiai apgailėtini.'),
  (@b46, 15, 20, 'Bet dabar Kristus yra prisikėlęs iš numirusiųjų ir tapo pirmavaisis tų, kurie užmigo.'),
  (@b46, 15, 21, 'Nes kadangi per žmogų atėjo mirtis, per žmogų atėjo ir mirusiųjų prisikėlimas.'),
  (@b46, 15, 22, 'Nes kaip Adome visi miršta, taip ir Kristuje visi bus atgaivinti.'),
  (@b46, 15, 23, 'Bet kiekvienas pagal savo eilę: Kristus – pirmavaisis; po to tie, kurie yra Kristaus, jo atėjime.'),
  (@b46, 15, 24, 'Tada ateis galas, kai jis bus atidavęs karalystę Dievui, būtent Tėvui; kai bus nugriovęs kiekvieną valdymą ir kiekvieną valdžią bei jėgą.'),
  (@b46, 15, 25, 'Nes jis turi karaliauti, kol padės visus priešus po savo kojomis.'),
  (@b46, 15, 26, 'Paskutinis priešas, kuris bus sunaikintas, yra mirtis.'),
  (@b46, 15, 27, 'Nes jis visa padėjo po jo kojomis. Bet kai jis sako, kad visa yra po juo padėta, yra aišku, kad išskyrus tą, kuris po juo visa padėjo.'),
  (@b46, 15, 28, 'O kai visa bus jam pajungta, tada ir pats Sūnus bus pavaldus tam, kuris padėjo visa po juo, kad Dievas būtų visa visame.'),
  (@b46, 15, 29, 'Be to, ką darys tie, kurie pakrikštyti už mirusiuosius, jei mirusieji iš viso neprisikelia? Tad kodėl jie pakrikštyti už mirusiuosius?'),
  (@b46, 15, 30, 'Ir kodėl mes kiekvieną valandą stovime pavojuje?'),
  (@b46, 15, 31, 'Tvirtinu jūsų džiaugsmu, kurio turiu Kristuje Jėzuje, mūsų Viešpatyje, aš mirštu kasdien.'),
  (@b46, 15, 32, 'Jei pagal žmogaus būdą kovojau su žvėrimis Efeze, koks man iš to pranašumas, jei mirusieji neprisikelia? Valgykime ir gerkime; nes rytoj mirsime.'),
  (@b46, 15, 33, 'Nebūkite suklaidinti: blogi bendravimai gadina gerus įpročius.'),
  (@b46, 15, 34, 'Atsibuskite teisumui ir nenuodėmiaukite; nes kai kurie neturi Dievo pažinimo; kalbu tai jūsų gėdai.'),
  (@b46, 15, 35, 'Bet kai kas sakys: „Kaip mirusieji yra prikeliami? Ir kokiu kūnu jie ateina?“'),
  (@b46, 15, 36, 'Kvaily, tai, ką sėji, neatgyja, jei nemiršta;'),
  (@b46, 15, 37, 'ir tai, ką sėji, tu sėji ne tą kūną, kuris bus, bet pliką grūdą, kaip pasitaiko, kviečio arba kokį kitą grūdą,'),
  (@b46, 15, 38, 'bet Dievas duoda jam kūną kaip jis norėjo ir kiekvienai sėklai jos pačios kūną.'),
  (@b46, 15, 39, 'Ne visi kūnai yra tokie pat kūnai; bet vienokia žmonių kūno rūšis, kitoks kūnas gyvūlių, kitoks – žuvų, ir kitoks – paukščių.'),
  (@b46, 15, 40, 'Taip pat yra ir dangiškieji kūnai bei žemiškieji kūnai, bet vienokia dangiškųjų šlovė, o kitokia žemiškųjų šlovė.'),
  (@b46, 15, 41, 'Vienokia yra saulės šlovė, kitokia mėnulio šlovė, ir kitokia žvaigždžių šlovė; nes viena žvaigždė skiriasi nuo kitos žvaigždės šlove.'),
  (@b46, 15, 42, 'Toks yra ir mirusiųjų prisikėlimas. Sėjamas gedime, prikeliamas negedime;'),
  (@b46, 15, 43, 'sėjamas negarbėje, prikeliamas šlovėje; sėjamas silpnume, prikeliamas jėgoje;'),
  (@b46, 15, 44, 'sėjamas prigimtinis kūnas, prikeliamas dvasinis kūnas. Yra prigimtinis kūnas ir yra dvasinis kūnas.'),
  (@b46, 15, 45, 'Ir taip yra parašyta: „Pirmasis žmogus Adomas buvo padarytas gyva siela, paskutinis Adomas buvo padarytas atgaivinančia dvasia“.'),
  (@b46, 15, 46, 'Tačiau pirmasis buvo ne dvasinis, o prigimtinis; o po to dvasinis.'),
  (@b46, 15, 47, 'Pirmasis žmogus – iš žemės, žemiškas, antrasis žmogus – Viešpats iš dangaus.'),
  (@b46, 15, 48, 'Koks yra žemiškas, tokie ir žemiškieji; ir koks yra dangiškasis, tokie ir dangiškieji.'),
  (@b46, 15, 49, 'Ir kaip nešiojome žemiškojo atvaizdą, nešiosime ir dangiškojo atvaizdą.'),
  (@b46, 15, 50, 'Sakau gi tai, broliai, kad kūnas ir kraujas negali paveldėti Dievo karalystės; nei gedimas paveldėti negedimo.'),
  (@b46, 15, 51, 'Štai išdėstau jums paslaptį: mes ne visi užmigsime, bet visi būsime pakeisti;'),
  (@b46, 15, 52, 'akimirksniu, akies mirksniu, per paskutinįjį trimitavimą; nes trimitas nuskambės, ir mirusieji bus prikelti negendantys, ir mes būsime pakeisti.'),
  (@b46, 15, 53, 'Nes šis gendantis turi apsivilkti negendamumu ir šis mirtingas turi apsivilkti nemirtingumu.'),
  (@b46, 15, 54, 'Taigi kai šis gendantis apsivilks negendamumu ir šis mirtingas apsivilks nemirtingumu, tada išsipildys užrašytas pasakymas: „Mirtis yra praryta pergalėje.'),
  (@b46, 15, 55, 'O mirtie, kur tavo geluonis? O kape, kur tavo pergalė?“'),
  (@b46, 15, 56, 'Mirties geluonis – nuodėmė; o nuodėmės jėga – įstatymas.'),
  (@b46, 15, 57, 'Bet ačiū tebūna Dievui, kuris duoda mums pergalę per mūsų Viešpatį Jėzų Kristų.'),
  (@b46, 15, 58, 'Todėl, mano mylimieji broliai, būkite tvirti, nepajudinami, visuomet gausūs Viešpaties darbe, kadangi žinote, kad jūsų triūsas nėra veltui Viešpatyje.'),
  (@b46, 16, 1, 'Na, o dėl rinkliavos šventiesiems, kaip nurodžiau Galatijos bažnyčioms, taip ir jūs darykite.'),
  (@b46, 16, 2, 'Pirmąją savaitės dieną kiekvienas iš jūsų teatsideda pas save pataupymui, kaip Dievas kam davė klestėjimą, kad nebūtų rinkliavų kai ateisiu.'),
  (@b46, 16, 3, 'O kai ateisiu, kuriuos patvirtinsite savo laiškais, tuos pasiųsiu nunešti jūsų dosnumą į Jeruzalę.'),
  (@b46, 16, 4, 'Ir jei bus tinkama, kad ir aš eičiau, jie eis su manimi.'),
  (@b46, 16, 5, 'Ateisiu gi pas jus kai vyksiu per Makedoniją, nes vykstu per Makedoniją.'),
  (@b46, 16, 6, 'Ir gali būti, kad pasiliksiu, taip, ir žiemosiu pas jus, kad mane išlydėtumėte į mano kelionę, kur tik bekeliausiu.'),
  (@b46, 16, 7, 'Nes dabar nenoriu susitikti su jumis pakeliui; tačiau tikiuosi pasilikti pas jus kurį laiką, jei Viešpats leis.'),
  (@b46, 16, 8, 'Bet pasiliksiu Efeze iki Sekminių.'),
  (@b46, 16, 9, 'Nes man atvertos plačios ir veiksmingos durys, ir yra daug priešininkų.'),
  (@b46, 16, 10, 'O jei ateis Timotiejus, žiūrėkite, kad jis būtų pas jus be baimės, nes jis dirba Viešpaties darbą kaip ir aš.'),
  (@b46, 16, 11, 'Todėl niekas jo teneniekina, bet išlydėkite jį ramybėje, kad ateitų pas mane; nes laukiu jo su broliais.'),
  (@b46, 16, 12, 'Kas dėl mūsų brolio Apolo, labai jo prašiau ateiti pas jus su broliais, tačiau jo valia buvo iš viso neateiti šį kartą; bet jis ateis radęs tinkamą laiką.'),
  (@b46, 16, 13, 'Budėkite, tvirtai stovėkite tikėjime, elkitės vyriškai, būkite stiprūs.'),
  (@b46, 16, 14, 'Jūsų visa tebūna daroma su meile.'),
  (@b46, 16, 15, 'Maldauju jus, broliai (jūs žinote Stepono namus, kad jie yra Achajos pirmavaisiai ir kad jie atsidavę šventųjų tarnystei),'),
  (@b46, 16, 16, 'kad paklustumėte tokiems ir kiekvienam, kuris su mumis padeda ir triūsia.'),
  (@b46, 16, 17, 'Džiaugiuosi Stepono, Fortunato ir Achaiko atvykimu, nes tai, ko trūko iš jūsų pusės, jie parūpino.'),
  (@b46, 16, 18, 'Nes jie atgaivino mano ir jūsų dvasią, todėl pripažinkite tuos, kurie tokie.'),
  (@b46, 16, 19, 'Jus sveikina Azijos bažnyčios. Jus labai sveikina Viešpatyje Akvilas ir Priscilė su bažnyčia, esančia jų namuose.'),
  (@b46, 16, 20, 'Jus sveikina visi broliai. Sveikinkite vienas kitą šventu pabučiavimu.'),
  (@b46, 16, 21, 'Sveikinimas mano, Pauliaus, mano paties ranka.'),
  (@b46, 16, 22, 'Jei kas nemyli Viešpaties Jėzaus Kristaus, tas tebūna Anatema; Maran-ata.'),
  (@b46, 16, 23, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b46, 16, 24, 'Mano meilė tebūna su jumis visais Kristuje Jėzuje. Amen.'),
  (@b47, 1, 1, 'Paulius, Dievo valia Jėzaus Kristaus apaštalas, ir mūsų brolis Timotiejus, Dievo bažnyčiai, esančiai Korinte, su visais šventaisiais, kurie yra visoje Achajoje;'),
  (@b47, 1, 2, 'malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir nuo Viešpaties Jėzaus Kristaus.'),
  (@b47, 1, 3, 'Tebūna palaimintas Dievas, būtent mūsų Viešpaties Jėzaus Kristaus Tėvas, gailestingumų Tėvas ir visos paguodos Dievas;'),
  (@b47, 1, 4, 'kuris guodžia mus visame mūsų suspaudime, kad pajėgtume paguosti tuos, kurie yra bet kokiame varge, ta paguoda, kuria patys esame Dievo guodžiami.'),
  (@b47, 1, 5, 'Nes kaip mumyse gausėja Kristaus kentėjimų, taip per Kristų gausėja ir mūsų paguoda.'),
  (@b47, 1, 6, 'Ir ar mes patiriame sielvartą, tai yra jūsų paguodai ir išgelbėjimui, kuris yra veiksmingas ištveriant tokius pačius kentėjimus, kuriuos ir mes kenčiame; arba, jei esame paguosti, tai yra jūsų paguodai ir išgelbėjimui.'),
  (@b47, 1, 7, 'Ir mūsų viltis dėl jūsų yra tvirta, žinant, kad, kaip esate kentėjimų, taip būsite ir paguodos dalininkai.'),
  (@b47, 1, 8, 'Nes nenorime, broliai, kad būtumėte nežinantys apie mūsų vargą, kuris mus ištiko Azijoje, kad buvome slegiami virš saiko, virš jėgų taip, jog netekome vilties net išlikti gyvi;'),
  (@b47, 1, 9, 'bet savyje turėjome mirties nuosprendį, kad pasitikėtume ne savimi, bet Dievu, kuris prikelia mirusiuosius,'),
  (@b47, 1, 10, 'kuris išvadavo mus iš tokios didelės mirties ir tebevaduoja, kuriuo pasitikime, kad mus dar išvaduos;'),
  (@b47, 1, 11, 'ir jūs kartu padedate malda už mus, kad už mums suteiktą dovaną per daugelį asmenų būtų daugelio dėkojama dėl mūsų.'),
  (@b47, 1, 12, 'Nes mūsų džiaugsmas yra šis: mūsų sąžinės liudijimas, kad paprastumu ir dievotu nuoširdumu, ne kūniška išmintimi, bet Dievo malone mes elgėmės pasaulyje ir daug gausiau su jumis.'),
  (@b47, 1, 13, 'Nes nerašome jums nieko kito, kaip to, ką skaitote ar pripažįstate; ir tikiuosi iki galo pripažinsite;'),
  (@b47, 1, 14, 'kaip iš dalies mus ir pripažinote, kad esame jūsų džiaugsmas, lygiai kaip ir jūs mūsų esate Viešpaties Jėzaus dieną.'),
  (@b47, 1, 15, 'Ir šiuo pasitikėjimu buvau nusiteikęs anksčiau ateiti pas jus, kad pakartotinai gautumėte naudos;'),
  (@b47, 1, 16, 'ir eiti pro jus į Makedoniją, ir iš Makedonijos vėl ateiti pas jus, ir būti jūsų išlydėtas Judėjos link.'),
  (@b47, 1, 17, 'Tad, kai buvau taip nusiteikęs, ar elgiausi lengvabūdiškai? Arba, ar tai, ką nutariu, ar nutariu pagal kūną, idant pas mane būtų „taip, taip“, ir „ne, ne“?'),
  (@b47, 1, 18, 'Bet kaip Dievas yra teisingas, mūsų žodis jums nebuvo „taip“ ir „ne“.'),
  (@b47, 1, 19, 'Nes Dievo Sūnus, Jėzus Kristus, kuris buvo mūsų, būtent mano, Silvano ir Timotiejaus – skelbiamas tarp jūsų, nebuvo „taip“ ir „ne“, bet jame buvo „taip“.'),
  (@b47, 1, 20, 'Nes visi Dievo pažadai jame yra „taip“, ir jame „Amen“ Dievo šlovei per mus.'),
  (@b47, 1, 21, 'Tas gi, kuris sutvirtina mus su jumis Kristuje ir mus patepė, yra Dievas;'),
  (@b47, 1, 22, 'kuris taipogi užantspaudavo mus ir davė Dvasios užstatą į mūsų širdis.'),
  (@b47, 1, 23, 'Be to, šaukiu Dievą liudijimui savo sielai, kad gailėtis jūsų dar neatvykau į Korintą.'),
  (@b47, 1, 24, 'Ne kad viešpataujame jūsų tikėjimui, bet esame jūsų džiaugsmo pagalbininkai; nes jūs stovite tikėjimu.'),
  (@b47, 2, 1, 'Bet nusprendžiau tai savyje, kad neatvyksiu pas jus vėl su liūdesiu.'),
  (@b47, 2, 2, 'Nes jei aš jus liūdinu, tai kas tas, kuris mane džiugina, jei ne tas, kuris yra mano nuliūdintas?'),
  (@b47, 2, 3, 'Ir parašiau jums tą patį, kad atvykęs nepatirčiau liūdesio nuo tų, kuriais turėčiau džiaugtis; pasitikėdamas jumis visais, kad mano džiaugsmas yra visų jūsų džiaugsmas.'),
  (@b47, 2, 4, 'Nes iš didelio sielvarto ir didelio širdies skausmo jums parašiau su gausiomis ašaromis; ne tam, kad būtumėte nuliūdinti, bet kad pažintumėte meilę, kurios gausiau jums turiu.'),
  (@b47, 2, 5, 'Bet jei kas nuliūdino, jis manęs nenuliūdino, bet iš dalies; kad jūsų visų per daug neapkraučiau.'),
  (@b47, 2, 6, 'Tokiam pakankama yra ši daugumos paskirta bausmė.'),
  (@b47, 2, 7, 'Taip kad atvirkščiai, jūs verčiau turėtumėte jam atleisti ir jį paguosti, kad kartais toks nebūtų pernelyg didelio liūdesio prarytas.'),
  (@b47, 2, 8, 'Todėl maldauju jus, kad patvirtintumėte jam savo meilę.'),
  (@b47, 2, 9, 'Nes aš ir rašiau tuo tikslu, kad sužinočiau jūsų išmėginimą, ar visame kame esate paklusnūs.'),
  (@b47, 2, 10, 'Kam jūs ką nors atleidžiate, aš – irgi atleidžiu; nes jei ką nors atleidau, kuriam atleidau, jūsų labui tai atleidau Kristaus asmenyje;'),
  (@b47, 2, 11, 'kad šėtonas nepasinaudotų mumis, nes mums nėra nežinomi jo kėslai.'),
  (@b47, 2, 12, 'Be to, kai atėjau į Troją skelbti Kristaus evangelijos, ir durys man buvo atvertos Viešpaties,'),
  (@b47, 2, 13, 'neturėjau savo dvasioje poilsio, kadangi neradau savo brolio Tito, bet su jais atsisveikinęs iš ten vykau į Makedoniją.'),
  (@b47, 2, 14, 'Dėkui gi Dievui, kuris visada duoda mums švęsti pergalę Kristuje ir per mus kiekvienoje vietoje atskleidžia savo pažinimo kvapą.'),
  (@b47, 2, 15, 'Nes Dievui mes esame gardus Kristaus kvapas tuose, kurie yra išgelbėti, ir tuose, kurie žūsta;'),
  (@b47, 2, 16, 'vieniems esame mirties kvapas link mirties, o kitiems – gyvenimo kvapas link gyvenimo. Ir kas yra tam pakankamas?'),
  (@b47, 2, 17, 'Nes nesame kaip daugelis, kurie iškraipo Dievo žodį, bet kaip iš nuoširdumo, kaip iš Dievo, Dievo akivaizdoje kalbame Kristuje.'),
  (@b47, 3, 1, 'Ar mes vėl pradėsime girtis? Arba, ar mums reikia, kaip kitiems, pagiriančių laiškų jums arba pagiriančių laiškų iš jūsų?'),
  (@b47, 3, 2, 'Jūs esate mūsų laiškas, įrašytas mūsų širdyse, visų žmonių žinomas ir skaitomas;'),
  (@b47, 3, 3, 'kadangi aiškiai pasirodote esą mūsų patarnautas Kristaus laiškas, parašytas ne rašalu, bet gyvojo Dievo Dvasia; ne akmens plokštėse, bet kūniškose širdies plokštėse.'),
  (@b47, 3, 4, 'Ir tokį pasitikėjimą turime per Kristų į Dievą:'),
  (@b47, 3, 5, 'ne kad mes pakankami iš savęs manyti kažką tarytum iš savęs; bet mūsų pakankamumas yra iš Dievo;'),
  (@b47, 3, 6, 'kuris taip pat padarė mus pajėgiais naujojo testamento tarnautojais; ne raidės, bet Dvasios; nes raidė užmuša, o Dvasia duoda gyvybę.'),
  (@b47, 3, 7, 'Bet jei mirties tarnystė, įrašyta ir išraižyta akmenyse, buvo šlovinga taip, kad Izraelio vaikai negalėjo įdėmiai žiūrėti į Mozės veidą dėl jo veido šlovės, kuri turėjo būti panaikinta;'),
  (@b47, 3, 8, 'kaipgi verčiau šlovingesnė nebus Dvasios tarnystė?'),
  (@b47, 3, 9, 'Nes jei pasmerkimo tarnystė yra šlovė, tai daug daugiau teisumo tarnystė pralenkia šlove.'),
  (@b47, 3, 10, 'Nes netgi tai, kas buvo padaryta šlovinga, šiuo atžvilgiu neturėjo šlovės dėl pranokstančios šlovės.'),
  (@b47, 3, 11, 'Nes jei tai, kas panaikinta, buvo šlovinga, daug labiau tai, kas pasilieka, yra šlovinga.'),
  (@b47, 3, 12, 'Taigi, turėdami tokią viltį, mes naudojame labai aiškią kalbą;'),
  (@b47, 3, 13, 'o ne kaip Mozė, kuris užsidėdavo dangalą sau ant veido, kad Izraelio vaikai negalėtų įdėmiai žiūrėti į pabaigą to, kas yra panaikinta;'),
  (@b47, 3, 14, 'bet jų protai buvo apakinti, nes iki šios dienos pasilieka nenuimtas tas pats dangalas skaitant senąjį testamentą; tas dangalas yra panaikinamas Kristuje.'),
  (@b47, 3, 15, 'Bet net iki šios dienos, kai skaitomas Mozė, dangalas yra ant jų širdies.'),
  (@b47, 3, 16, 'Tačiau kai ji atsigręš į Viešpatį, dangalas bus nuimtas.'),
  (@b47, 3, 17, 'Viešpats gi yra ta Dvasia; o kur yra Viešpaties Dvasia, ten yra laisvė.'),
  (@b47, 3, 18, 'Bet mes visi, atviru veidu kaip veidrodyje matydami Viešpaties šlovę, esame keičiami į tą patį atvaizdą iš šlovės į šlovę, kaip per Viešpaties Dvasią.'),
  (@b47, 4, 1, 'Todėl, kadangi turime šią tarnystę, kaip gavome pasigailėjimą, mes nenusilpstame;'),
  (@b47, 4, 2, 'bet, atsisakę slaptų nesąžiningumų, nevaikščiodami gudrume ir nenaudodami klastingai Dievo žodžio; bet tiesos atskleidimu prisistatome kiekvieno žmogaus sąžinei Dievo akivaizdoje.'),
  (@b47, 4, 3, 'Bet jei mūsų evangelija paslėpta, ji paslėpta tiems, kurie pražuvę,'),
  (@b47, 4, 4, 'kuriuose šio pasaulio dievas apakino protus tų, kurie netiki, kad jiems nenušvistų Kristaus, kuris yra Dievo atvaizdas, šlovingosios evangelijos šviesa.'),
  (@b47, 4, 5, 'Nes mes skelbiame ne save, bet Kristų Jėzų – Viešpatį; ir save pačius – jūsų tarnus Jėzaus dėlei.'),
  (@b47, 4, 6, 'Nes Dievas, kuris įsakė šviesai nušvisti iš tamsos, nušvito mūsų širdyse, kad duotų Dievo šlovės pažinimo šviesą Jėzaus Kristaus veide.'),
  (@b47, 4, 7, 'Bet šį lobį turime žemiškuose induose, kad jėgos pranašumas būtų iš Dievo, o ne iš mūsų.'),
  (@b47, 4, 8, 'Mes varginami iš visų pusių, tačiau neišsekinti; sugluminti, bet nenusivylę;'),
  (@b47, 4, 9, 'persekiojami, bet neapleisti; parblokšti, bet nesunaikinti;'),
  (@b47, 4, 10, 'visuomet nešiodamiesi kūne Viešpaties Jėzaus mirimą, kad ir Jėzaus gyvybė apsireikštų mūsų kūne.'),
  (@b47, 4, 11, 'Nes mes, kurie gyvename, nuolat esame atiduodami mirčiai dėl Jėzaus, kad ir Jėzaus gyvybė apsireikštų mūsų mirtingame kūne.'),
  (@b47, 4, 12, 'Taip tad mirtis veikia mumyse, bet gyvybė jumyse.'),
  (@b47, 4, 13, 'Mes, turėdami tą pačią tikėjimo dvasią, pagal tai, kaip yra parašyta: „Aš tikėjau, ir todėl kalbėjau“; mes irgi tikime, ir todėl kalbame;'),
  (@b47, 4, 14, 'žinodami, kad tas, kuris prikėlė Viešpatį Jėzų, prikels ir mus per Jėzų ir pristatys mus su jumis.'),
  (@b47, 4, 15, 'Nes visa yra jūsų labui, kad gausi malonė per daugelio padėką darytų Dievui šlovę.'),
  (@b47, 4, 16, 'Todėl mes nenusilpstame; bet nors mūsų išorinis žmogus ir nyksta, tačiau vidinis atnaujinamas diena iš dienos.'),
  (@b47, 4, 17, 'Nes mūsų lengvas sielvartas, kuris tik akimirkai, gamina mums nepalyginamai pranašesnį ir amžiną šlovės svorį;'),
  (@b47, 4, 18, 'mums bežiūrint ne į tai, kas matoma, bet į tai, kas nematoma; nes tai, kas matoma, yra laikina; bet tai, kas nematoma, yra amžina.'),
  (@b47, 5, 1, 'Nes žinome, kad jei mūsų žemiškasis šios padangtės namas suirs, mes turime Dievo pastatą, ne rankomis padarytą namą, amžiną danguose.'),
  (@b47, 5, 2, 'Nes tame dejuojame, uoliai trokšdami būti apsirengę mūsų namu, kuris yra iš dangaus;'),
  (@b47, 5, 3, 'jei tik, būdami apsirengę, nebūtume rasti nuogi.'),
  (@b47, 5, 4, 'Nes mes, esantys šioje padangtėje, dejuojame, būdami apsunkinti: ne tam, kad būtume neapsirengę, bet apsirengę, kad marumas būtų gyvenimo prarytas.'),
  (@b47, 5, 5, 'Na, o tas, kuris tam pačiam mus padarė, yra Dievas, kuris taip pat mums davė Dvasios užstatą.'),
  (@b47, 5, 6, 'Todėl visada esame tikri, žinodami, kad, kol esame namuose, kūne, nesame pas Viešpatį'),
  (@b47, 5, 7, '(nes mes vaikštome tikėjimu, o ne regėjimu);'),
  (@b47, 5, 8, 'esame tikri, sakau, ir norėdami verčiau nebūti kūne, o būti pas Viešpatį.'),
  (@b47, 5, 9, 'Todėl triūsiame, kad, ar būdami ar nebūdami, mes būtume jo priimtini.'),
  (@b47, 5, 10, 'Nes mes visi turime pasirodyti prieš Kristaus teismo krasę; kad kiekvienas gautų tai, ką atlikęs savo kūne, pagal tai, ką jis padarė, ar tai būtų gera, ar bloga.'),
  (@b47, 5, 11, 'Todėl, žinodami Viešpaties baimę, įtikinėjame žmones; bet mes tapome aiškūs Dievui; ir, tikuosi, tapome aiškūs ir jūsų sąžinėse.'),
  (@b47, 5, 12, 'Nes vėl jums nesigiriame, bet duodame jums progą girtis dėl mūsų, kad turėtumėte, ką atsakyti tiems, kurie giriasi išore, o ne širdimi.'),
  (@b47, 5, 13, 'Nes jei esame išprotėję, tai yra Dievui, arba jei esame blaivūs, tai yra dėl jūsų.'),
  (@b47, 5, 14, 'Nes Kristaus meilė mus verčia; nes mes taip sprendžiame, jog, jei vienas mirė už visus, tuomet visi yra mirę;'),
  (@b47, 5, 15, 'ir jog jis mirė už visus, kad tie, kurie gyvena, nuo šiol nebe sau gyventų, bet tam, kuris mirė už juos ir prisikėlė.'),
  (@b47, 5, 16, 'Todėl nuo šiol nei vieno nebepažįstame pagal kūną; taip, nors esame pažinę Kristų pagal kūną, tačiau nuo šiol jau nebepažįstame.'),
  (@b47, 5, 17, 'Todėl jei kas yra Kristuje, tas yra naujas sutvėrimas: kas sena, yra praėję; štai visa tapo nauja.'),
  (@b47, 5, 18, 'Ir visa yra iš Dievo, kuris sutaikė mus su savimi per Jėzų Kristų, ir davė mums sutaikymo tarnystę;'),
  (@b47, 5, 19, 'tai yra, kad Dievas buvo Kristuje, taikydamas su savimi pasaulį, neįskaitydamas jiems jų nusižengimų; ir mums patikėjo sutaikymo žodį.'),
  (@b47, 5, 20, 'Taigi esame pasiuntiniai Kristui, tarsi Dievas jus maldavo per mus; meldžiame jus Kristaus vietoje: susitaikykite su Dievu.'),
  (@b47, 5, 21, 'Nes tą, kuris nepažino nuodėmės, jis padarė būti nuodėme už mus; kad jame mes taptume Dievo teisumu.'),
  (@b47, 6, 1, 'Tad mes, kaip darbininkai kartu su juo, jus irgi maldaujame, kad neimtumėte Dievo malonės veltui'),
  (@b47, 6, 2, '(nes jis sako: „Aš išklausiau tave priimtinu laiku ir išgelbėjimo dieną tau padėjau; štai dabar priimtinas laikas; štai dabar išgelbėjimo diena“).'),
  (@b47, 6, 3, 'Niekuo nesukeldami pasipiktinimo, kad tarnystė nebūtų peikiama,'),
  (@b47, 6, 4, 'bet visame kame pasirodydami kaip Dievo tarnai: didele kantrybe, sielvartuose, stokojimuose, kančiose,'),
  (@b47, 6, 5, 'plakimuose, įkalinimuose, sąmyšiuose, sunkiuose darbuose, budėjimuose, pasninkavimuose;'),
  (@b47, 6, 6, 'tyrumu, pažinimu, ilgu pakantumu, gerumu, Šventąja Dvasia, neveidmainiška meile,'),
  (@b47, 6, 7, 'tiesos žodžiu, Dievo jėga, teisumo ginklais iš dešinės ir iš kairės,'),
  (@b47, 6, 8, 'garbe ir negarbe, blogais atsiliepimais ir gerais atsiliepimais, kaip klaidintojai, tačiau teisūs;'),
  (@b47, 6, 9, 'kaip nežinomi, tačiau gerai žinomi; kaip mirštantys, ir štai gyvename; kaip baudžiami, ir nenužudomi;'),
  (@b47, 6, 10, 'kaip liūdintys, tačiau visuomet besidžiaugiantys; kaip vargšai, tačiau daugelį padarydami turtingais; kaip nieko neturintys, tačiau turintys viską.'),
  (@b47, 6, 11, 'O korintiečiai, mūsų burna jums atverta, mūsų širdis prasiplėtusi.'),
  (@b47, 6, 12, 'Jums neankšta mumyse, bet jums ankšta jūsų pačių viduriuose.'),
  (@b47, 6, 13, 'Na, o atsimokėdami tuo pačiu (aš kalbu kaip savo vaikams), būkite ir jūs prasiplėtę.'),
  (@b47, 6, 14, 'Neįsikinkykite į nevienodą jungą su netikinčiaisiais; nes kokią gi bendrystę teisumas turi su neteisumu? Ir kokią gi bendrystę šviesa turi su tamsa?'),
  (@b47, 6, 15, 'Ir kokią santarvę Kristus turi su Belialu? Arba, kokią dalį tikintis turi su netikinčiuoju?'),
  (@b47, 6, 16, 'Ir kokį sutarimą Dievo šventykla turi su stabais? Nes jūs esate gyvojo Dievo šventykla; kaip Dievas yra pasakęs: „Aš gyvensiu juose ir vaikščiosiu juose; ir būsiu jų Dievas, o jie bus mano tauta.'),
  (@b47, 6, 17, 'Todėl išeikite iš jų tarpo ir būkite atsiskyrę, – sako Viešpats, – ir nelieskite to, kas nešvaru; ir aš jus priimsiu,'),
  (@b47, 6, 18, 'ir būsiu jums Tėvas, o jūs būsite mano sūnūs ir dukterys“, – sako Visagalis Viešpats.'),
  (@b47, 7, 1, 'Todėl, turėdami šiuos pažadus, brangiai mylimi, apsivalykime nuo visų kūno ir dvasios nešvarumų, tobulindami šventumą Dievo baimėje.'),
  (@b47, 7, 2, 'Priimkite mus; mes nenuskriaudėme nei vieno, nesugadinome nei vieno, neapgavome nei vieno.'),
  (@b47, 7, 3, 'Nekalbu to, kad jus pasmerkčiau; nes anksčiau sakiau, kad esate mūsų širdyse, idant su jumis mirtume ir gyventume.'),
  (@b47, 7, 4, 'Didelė yra mano kalbos drąsa jums, didis mano gyrimasis jumis: esu pripildytas paguodos, esu be galo džiaugsmingas visame mūsų suspaudime.'),
  (@b47, 7, 5, 'Nes kai atvykome į Makedoniją, mūsų kūnas neturėjo poilsio, bet buvome varginami iš visų pusių; išorėje buvo kovos, viduje buvo baimės.'),
  (@b47, 7, 6, 'Tačiau Dievas, kuris paguodžia prislėgtuosius, paguodė mus Tito atvykimu;'),
  (@b47, 7, 7, 'ir ne tik jo atvykimu, bet ir ta paguoda, kuria jis buvo jumyse paguostas, kai jis papasakojo mums apie jūsų uolų troškimą, jūsų raudojimą, jūsų užsidegimą man; taip, kad aš dar labiau pradžiugau.'),
  (@b47, 7, 8, 'Nors ir priverčiau jus nuliūsti laišku, nesigailiu, nors ir gailėjausi; nes matau, kad tas pats laiškas jus nuliūdino, nors tai buvo tik kuriam laikui.'),
  (@b47, 7, 9, 'Dabar džiaugiuosi ne todėl, kad buvote nuliūdinti, bet kad liūdėjote link atgailos; nes buvote nuliūdę dievotu būdu, kad per mus niekuo nepatirtumėte žalos.'),
  (@b47, 7, 10, 'Nes dievotas liūdesys gamina atgailą į išgelbėjimą, dėl ko nereikia gailėtis; bet pasaulio liūdesys gamina mirtį.'),
  (@b47, 7, 11, 'Nes tai, kad liūdėjote dievotu būdu, štai kokį susirūpinimą tai pagamino jumyse, taip, kokį savęs valymą, taip, kokį pasipiktinimą, taip, kokią baimę, taip, kokį stiprų troškimą, taip, kokį uolumą, taip, kokį kerštą! Visuose dalykuose pasirodėte švarūs šiame reikale.'),
  (@b47, 7, 12, 'Todėl, nors jums parašiau, to nepadariau dėl to, kuris padarė skriaudą, nei dėl to, kuris kentėjo skriaudą, bet kad jums atsiskleistų mūsų rūpestis jumis Dievo akyse.'),
  (@b47, 7, 13, 'Todėl buvome paguosti jūsų paguoda: taip, ir be galo labiau džiaugėmės dėl Tito džiaugsmo, nes jo dvasia buvo jūsų visų atgaivinta.'),
  (@b47, 7, 14, 'Nes jei esu jam kuo nors apie jus pasigyręs, aš nesigėdiju; bet kaip viską jums tiesoje kalbėjome, taip ir mūsų pasigyrimas Tito akivaizdoje pasirodė tiesa.'),
  (@b47, 7, 15, 'Ir jo vidinis prieraišumas yra jums dar gausesnis, kai jis prisimena jūsų visų paklusnumą, kaip jį priėmėte su baime ir drebėjimu.'),
  (@b47, 7, 16, 'Todėl džiaugiuosi, kad pasitikiu jumis visame kame.'),
  (@b47, 8, 1, 'Be to, broliai, pranešame jums apie Dievo malonę, suteiktą Makedonijos bažnyčioms;'),
  (@b47, 8, 2, 'kaip dideliame vargo išbandyme jų džiaugsmo gausa ir jų gilus skurdas pagausėjo iki jų dosnumo turtų.'),
  (@b47, 8, 3, 'Nes pagal savo išgales, aš liudiju, taip, ir virš savo išgalių, jie patys norėjo;'),
  (@b47, 8, 4, 'melsdami mus didžiu maldavimu, kad priimtume dovaną ir prisiimtume tarnavimo šventiesiems bendrystę.'),
  (@b47, 8, 5, 'Ir tai jie padarė ne kaip mes tikėjomės, bet jie pirma atidavė save Viešpačiui ir mums pagal Dievo valią.'),
  (@b47, 8, 6, 'Tiek, kad prašėme Tito, kad, kaip jis pradėjo, taip ir baigtų tą pačią malonę ir jumyse.'),
  (@b47, 8, 7, 'Todėl, kaip esate visu kuo gausūs, tikėjimu ir ištarme, ir pažinimu, ir visokiu stropumu, ir jūsų meile mums, žiūrėkite, kad būtumėte gausūs ir šita malone.'),
  (@b47, 8, 8, 'Kalbu ne įsakymu, bet kitų uolumo proga ir kad išmėginčiau jūsų meilės nuoširdumą.'),
  (@b47, 8, 9, 'Nes žinote mūsų Viešpaties Jėzaus Kristaus malonę, kad, nors jis buvo turtingas, tačiau dėl jūsų tapo vargšu, kad per jo neturtą jūs būtumėte turtingi.'),
  (@b47, 8, 10, 'Ir čia duodu savo patarimą; nes tai naudinga jums, kurie anksčiau pradėjote ne tik daryti, bet ir būti uolūs prieš metus.'),
  (@b47, 8, 11, 'Todėl dabar vykdykite šį darbą; kad, kaip buvo pasirengimas norėti, taip būtų ir vykdymas iš to, ką turite.'),
  (@b47, 8, 12, 'Nes jei pirmiausiai yra noringumas, tai yra priimtina pagal tai, ką žmogus turi, o ne pagal tai, ko jis neturi.'),
  (@b47, 8, 13, 'Nes turiu mintyje ne tai, kad kitiems būtų palengvinta, o jums apsunkinta;'),
  (@b47, 8, 14, 'bet pagal lygybę, kad dabar, šiuo metu, jūsų perteklius būtų jų stygiaus aprūpinimui, kad ir jų perteklius būtų jūsų stygiaus aprūpinimui: kad būtų lygybė,'),
  (@b47, 8, 15, 'kaip yra parašyta: „Kas daug surinko, neturėjo nieko atliekamo; o kas surinko mažai, neturėjo stokos“.'),
  (@b47, 8, 16, 'Bet ačiū tebūna Dievui, kuris įdėjo tą patį uolų rūpestį į Tito širdį dėl jūsų.'),
  (@b47, 8, 17, 'Nes iš tiesų jis priėmė paraginimą; bet, būdamas uolesnis, savo noru nuvyko pas jus.'),
  (@b47, 8, 18, 'Ir pasiuntėme su juo brolį, kurio gyrius yra evangelijoje visose bažnyčiose;'),
  (@b47, 8, 19, 'ir ne tik tai, bet jis buvo ir bažnyčių išrinktas keliauti su mumis su šia malone, kuri yra mūsų patarnaujama to paties Viešpaties šlovei ir jūsų pasirengimo paskelbimui:'),
  (@b47, 8, 20, 'vengdami to, kad niekas mūsų nekaltintų dėl šios gausos, kuri yra mūsų patarnaujama;'),
  (@b47, 8, 21, 'rūpindamiesi tuo, kas dora, ne tik Viešpaties akyse, bet ir žmonių akyse.'),
  (@b47, 8, 22, 'Ir pasiuntėme su jais mūsų brolį, kurį daug kartų išmėginome esantį daug kame uolų, bet dabar daug uolesnį dėl didelio pasitikėjimo, kurio turiu jumyse.'),
  (@b47, 8, 23, 'Jei kas teiraujasi apie Titą, jis yra mano bendrininkas ir bendratalkininkas dėl jūsų; arba, jei teiraujamasi dėl mūsų brolių, jie yra bažnyčių pasiuntiniai ir Kristaus šlovė.'),
  (@b47, 8, 24, 'Todėl parodykite jiems ir bažnyčių akivaizdoje savo meilės bei mūsų gyrimosi dėl jūsų įrodymą.'),
  (@b47, 9, 1, 'Nes dėl patarnavimo šventiesiems, man nėra reikalo jums rašyti;'),
  (@b47, 9, 2, 'nes žinau jūsų pasirengimą, dėl kurio giriuosi jumis makedoniečiams, kad Achaja buvo pasiruošusi prieš metus; ir jūsų uolumas paskatino labai daugelį.'),
  (@b47, 9, 3, 'Tačiau pasiunčiau brolius, kad mūsų gyrimąsis jumis dėl šito nebūtų tuščias; kad jūs, kaip sakiau, būtumėte pasiruošę;'),
  (@b47, 9, 4, 'kad kartais, jei ateitų su manimi makedoniečiai ir rastų jus nepasiruošusius, mes (kad nesakytume „jūs“) nebūtume sugėdinti dėl to tvirto gyrimosi.'),
  (@b47, 9, 5, 'Todėl, maniau, yra būtina paraginti brolius, kad jie pirma nueitų pas jus ir iš anksto paruoštų jūsų prieš tai minėtą dosnumą, kad jis būtų paruoštas kaip dosnumas, o ne kaip godumas.'),
  (@b47, 9, 6, 'Bet sakau tai: kas šykščiai sėja, šykščiai ir pjaus; o kas dosniai sėja, dosniai ir pjaus.'),
  (@b47, 9, 7, 'Kiekvienas teduoda pagal tai, kaip nutaria savo širdyje; ne gailėdamas ar verčiamas; nes Dievas myli linksmą davėją.'),
  (@b47, 9, 8, 'O Dievas yra pajėgus pagausinti jums visokeriopą malonę; kad visame kame visada turėdami visokeriopą pakankamumą, gausėtumėte kiekvienam geram darbui'),
  (@b47, 9, 9, '(kaip yra parašyta: „Jis išbarstė; jis davė vargšams; jo teisumas išlieka per amžius“.'),
  (@b47, 9, 10, 'Tas gi, kuris parūpina sėjėjui sėklos, taip pat parūpina duonos jūsų valgiui ir padaugina jūsų pasėtą sėklą, ir padaugina jūsų teisumo vaisius);'),
  (@b47, 9, 11, 'visame kame būdami praturtinti visokeriopam dosnumui, kuris per mus gamina padėką Dievui.'),
  (@b47, 9, 12, 'Nes šito tarnavimo tvarkymas ne tik aprūpina šventųjų stygių, bet ir yra gausus daugeliu padėkų Dievui;'),
  (@b47, 9, 13, 'kai, patirdami šitą tarnavimą, jie šlovina Dievą už jūsų išpažintą klusnumą Kristaus evangelijai ir už jūsų dosnų išdalijimą jiems bei visiems;'),
  (@b47, 9, 14, 'ir jų malda už jus, kurie ilgisi jūsų dėl pranokstančios Dievo malonės jumyse.'),
  (@b47, 9, 15, 'Dėkui tebūna Dievui už jo neapsakomą dovaną.'),
  (@b47, 10, 1, 'Na, o aš pats, Paulius, maldauju jus Kristaus romumu ir švelnumu, kuris esu menkas būdamas tarp jūsų, bet nebūdamas pas jus esu prieš jus drąsus;'),
  (@b47, 10, 2, 'bet maldauju jus, kad man būnant pas jus nereikėtų būti drąsiu tuo pasitikėjimu, kuriuo manau būti drąsiu prieš kai kuriuos, apie mus manančius, tarsi vaikščiojome pagal kūną.'),
  (@b47, 10, 3, 'Nes, nors vaikštome kūne, mes nekovojame pagal kūną'),
  (@b47, 10, 4, '(nes mūsų kovos ginklai nėra kūniški, bet galingi per Dievą tvirtovėms griauti);'),
  (@b47, 10, 5, 'nuversdami sumanymus ir visa, kas aukšta, kas išsikelia prieš Dievo pažinimą, ir atvesdami nelaisvėn kiekvieną mintį Kristaus klusnumui;'),
  (@b47, 10, 6, 'ir turėdami parengtyje atkeršyti kiekvienam neklusnumui, kai jūsų klusnumas bus išpildytas.'),
  (@b47, 10, 7, 'Ar žiūrite į dalykus pagal išorę? Jei kas pasitiki savyje, kad yra Kristaus, tai dar kartą tepamąsto apie save, jog, kaip jis Kristaus, taip ir mes Kristaus.'),
  (@b47, 10, 8, 'Nes nors ir kiek daugiau girčiausi mūsų valdžia, kurią Viešpats mums yra davęs jūsų statydinimui, o ne griovimui, aš nebūčiau sugėdintas;'),
  (@b47, 10, 9, 'kad neatrodyčiau tarsi noriu išgąsdinti jus laiškais.'),
  (@b47, 10, 10, 'Nes jo laiškai, – jie sako, – yra svarūs ir galingi; bet jo buvimas kūnu – silpnas, ir jo kalba – niekinga.'),
  (@b47, 10, 11, 'Tegul toks pamąsto tai, kad, kokie esame žodžiu per laiškus, nebūdami pas jus, tokie būsime ir darbu, būdami pas jus.'),
  (@b47, 10, 12, 'Nes nedrįstame savęs priskaičiuoti ar sugretinti savęs su kai kuriais, kurie save giria; bet jie save matuodami pagal save pačius ir gretindami save tarpusavyje, nėra išmintingi.'),
  (@b47, 10, 13, 'Bet nesigirsime tuo, kas virš mūsų mato, bet pagal virvės matą, kurį Dievas mums yra paskirstęs, matą, kad siektų būtent iki jūsų.'),
  (@b47, 10, 14, 'Nes mes neišsitiesiame už savo mato, tarsi nebūtume pasiekę jūsų; nes atėjome ir iki jūsų Kristaus evangelijos skelbime;'),
  (@b47, 10, 15, 'nesigirdami tuo, kas virš mūsų mato, tai yra, kitų žmonių darbais; bet turėdami viltį, kad, jūsų tikėjimui išaugus, mes per jus gausiai prasiplėsime pagal savo virvę,'),
  (@b47, 10, 16, 'skelbti evangeliją kraštuose anapus jūsų ir nesigirti tuo, ką kitas savo virvės ribose padarė mūsų parankumui.'),
  (@b47, 10, 17, 'Bet kas giriasi, tesigiria Viešpatyje.'),
  (@b47, 10, 18, 'Nes ne tas išmėgintas, kuris giria save, bet kurį Viešpats giria.'),
  (@b47, 11, 1, 'O, kad truputį pakęstumėte mane mano kvailystėje; ir iš tikrųjų pakęskite mane.'),
  (@b47, 11, 2, 'Nes aš pavyduliauju dėl jūsų dievotu pavydu, nes sužiedavau jus su vienu vyru, kad pristatyčiau jus Kristui kaip skaisčią mergelę.'),
  (@b47, 11, 3, 'Bet bijau, kad kokiu būdu, kaip gyvatė savo klastingumu apgavo Ievą, taip ir jūsų mintys nebūtų sugadintos atitraukiant nuo paprastumo, kuris yra Kristuje.'),
  (@b47, 11, 4, 'Nes jei tas, kuris ateina, skelbia kitą Jėzų, kurio mes neskelbėme, arba jei priimate kitą dvasią, kurios nesate priėmę, arba kitą evangeliją, kurios nesate pripažinę, jūs gerai jį pakęstumėte.'),
  (@b47, 11, 5, 'Nes manau, nebuvau nei trupučiu atsilikęs nuo pačių vyriausiųjų apaštalų.'),
  (@b47, 11, 6, 'Bet nors esu prastas kalboje, tačiau ne pažinime; bet mes tarp jūsų visame kame pilnai tapome aiškūs.'),
  (@b47, 11, 7, 'Ar padariau nusikaltimą pažemindamas save, kad jūs būtumėte išaukštinti, kadangi jums paskelbiau Dievo evangeliją dovanai?'),
  (@b47, 11, 8, 'Aš apiplėšiau kitas bažnyčias, imdamas iš jų atlyginimą, kad jums tarnaučiau.'),
  (@b47, 11, 9, 'Ir būdamas pas jus bei stokodamas, neapsunkinau nei vieno; nes tai, ko stokojau, parūpino iš Makedonijos atėję broliai; ir visame kame saugojausi, kad nebūčiau jums apsunkinimas, ir taip saugosiuosi.'),
  (@b47, 11, 10, 'Kaip Kristaus tiesa yra manyje, niekas nesulaikys manęs nuo šito gyrimosi Achajos kraštuose.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b47, 11, 11, 'Kodėl? Kadangi jūsų nemyliu? Dievas žino.'),
  (@b47, 11, 12, 'Bet ką darau, tai darysiu, kad atkirsčiau progą nuo tų, kurie trokšta progos, idant tuo, kuo jie giriasi, jie rastųsi tokie, kaip ir mes.'),
  (@b47, 11, 13, 'Nes tokie yra netikri apaštalai, apgaulingi darbininkai, pasivertę Kristaus apaštalais.'),
  (@b47, 11, 14, 'Ir nenuostabu; nes pats šėtonas yra pasivertęs šviesos angelu.'),
  (@b47, 11, 15, 'Todėl nieko ypatingo, jei ir jo tarnautojai yra pasivertę būti kaip teisumo tarnautojai; kurių galas bus pagal jų darbus.'),
  (@b47, 11, 16, 'Vėl sakau: nei vienas tenemano mane esant kvailiu; jei priešingu atveju, tai priimkite mane kaip kvailį, kad truputį galėčiau pasigirti.'),
  (@b47, 11, 17, 'Tai, ką kalbu, nekalbu pagal Viešpatį, bet tarsi kvailai, šiuo gyrimosi tvirtumu.'),
  (@b47, 11, 18, 'Kadangi daugelis giriasi pagal kūną, tai ir aš pasigirsiu.'),
  (@b47, 11, 19, 'Nes jūs mielai pakenčiate kvailius, kadangi patys esate išmintingi.'),
  (@b47, 11, 20, 'Nes pakenčiate, jei kas jus pavergia, jei kas jus suryja, jei kas atima iš jūsų, jei kas save išaukština, jei kas smogia jums į veidą.'),
  (@b47, 11, 21, 'Kalbu dėl priekaišto, tarsi buvome silpni. Tačiau jei kas kuo nors yra drąsus (kalbu kvailai), aš irgi drąsus.'),
  (@b47, 11, 22, 'Ar jie hebrajai? Taip pat ir aš. Ar jie izraelitai? Taip pat ir aš. Ar jie Abraomo sėkla? Taip pat ir aš.'),
  (@b47, 11, 23, 'Ar jie Kristaus tarnautojai? (Kalbu kaip kvailys) aš labiau; gausesnis darbais, kirčiais be saiko, dažniau kalėjimuose, dažnai mirtyse.'),
  (@b47, 11, 24, 'Nuo žydų gavau penkis kartus po keturiasdešimt kirčių be vieno.'),
  (@b47, 11, 25, 'Triskart buvau muštas lazdomis, vienąkart buvau užmėtytas akmenimis, triskart patyriau laivo sudužimą, naktį ir dieną buvau gelmėje;'),
  (@b47, 11, 26, 'dažnai kelionėse, vandens pavojuose, pavojuose nuo plėšikų, pavojuose nuo savo tautiečių, pavojuose nuo pagonių, pavojuose mieste, pavojuose dykumoje, pavojuose jūroje, pavojuose tarp netikrų brolių;'),
  (@b47, 11, 27, 'nuvargime ir skausmingume, dažnai budėjimuose, alkyje ir troškulyje, dažnai pasninkavimuose, šaltyje ir nuogume.'),
  (@b47, 11, 28, 'Be viso to, kas išorėje, kas ištinka mane kasdien, dar rūpinimasis visomis bažnyčiomis.'),
  (@b47, 11, 29, 'Kas yra silpnas, o aš nesu silpnas? Kas yra papiktintas, o aš nedegu?'),
  (@b47, 11, 30, 'Jei man reikia girtis, girsiuosi tuo, kas susiję su mano negaliomis.'),
  (@b47, 11, 31, 'Dievas ir Tėvas mūsų Viešpaties Jėzaus Kristaus, kuris yra palaimintas per amžius, žino, kad nemeluoju.'),
  (@b47, 11, 32, 'Damaske valdant karaliui Aretui, valdytojas saugojo damaskiečių miestą su įgula, trokšdamas mane suimti,'),
  (@b47, 11, 33, 'ir aš pro langą buvau nuleistas per sieną žemyn pintinėje ir ištrūkau iš jo rankų.'),
  (@b47, 12, 1, 'Neabejotinai man nenaudinga girtis. Aš ateisiu prie Viešpaties regėjimų ir apreiškimų.'),
  (@b47, 12, 2, 'Pažinojau žmogų Kristuje daugiau kaip prieš keturiolika metų (ar tai kūne, nežinau; ar tai už kūno, nežinau – Dievas žino), šitoks buvo pagautas į trečiąjį dangų.'),
  (@b47, 12, 3, 'Ir pažinojau tokį žmogų (ar tai kūne, ar tai už kūno, nežinau – Dievas žino),'),
  (@b47, 12, 4, 'kaip jis buvo pagautas į rojų ir girdėjo neišsakomus žodžius, kurių neteisėta žmogui ištarti.'),
  (@b47, 12, 5, 'Šitokiu pasigirsiu; tačiau savimi nesigirsiu, bet tik savo negaliomis.'),
  (@b47, 12, 6, 'Nors jei trokščiau girtis, nebūčiau kvailys; nes sakyčiau tiesą; bet dabar susilaikau, kad kas nepagalvotų apie mane daugiau to, kuo jis mato mane esant, arba ką jis iš manęs girdi.'),
  (@b47, 12, 7, 'Ir kad virš saiko nesiaukštinčiau dėl apreiškimų gausos, man buvo duotas dyglys kūne, šėtono pasiuntinys, idant mane smūgiuotų, kad virš saiko nesiaukštinčiau.'),
  (@b47, 12, 8, 'Dėl to triskart maldavau Viešpaties, kad tai nuo manęs pasitrauktų.'),
  (@b47, 12, 9, 'Ir jis man tarė: „Mano malonė tau yra pakankama, nes mano stiprybė tampa tobula silpnume“. Todėl verčiau mieliausiai girsiuosi savo negaliomis, kad Kristaus jėga ilsėtųsi ant manęs.'),
  (@b47, 12, 10, 'Todėl gėriuosi negaliomis, priekaištais, stokojimais, persekiojimais, kančiomis dėl Kristaus; nes kai esu silpnas, tada esu stiprus.'),
  (@b47, 12, 11, 'Besigirdamas tapau kvailiu; jūs mane privertėte; nes aš turėčiau būti jūsų giriamas; nes niekuo neatsilieku nuo pačių vyriausiųjų apaštalų, nors esu niekas.'),
  (@b47, 12, 12, 'Iš tiesų tarp jūsų buvo atlikti apaštalo ženklai visa kantrybe, ženklais, stebuklais ir galingais darbais.'),
  (@b47, 12, 13, 'Nes kas gi tai, kuo buvote prastesni už kitas bažnyčias, išskyrus tai, kad aš pats nebuvau jums apsunkinimas? Atleiskite man šią neteisybę.'),
  (@b47, 12, 14, 'Štai trečiąkart esu pasiruošęs ateiti pas jus; ir nebūsiu jums apsunkinimas, nes ieškau ne to, kas jūsų, bet jūsų pačių; nes ne vaikai turi kaupti tėvams, bet tėvai vaikams.'),
  (@b47, 12, 15, 'Ir aš labai mielai eikvosiu bei būsiu eikvojamas dėl jūsų; nors kuo gausiau jus myliu, tuo mažiau esu mylimas.'),
  (@b47, 12, 16, 'Bet tebūna taip, aš jūsų neapsunkinau; tačiau būdamas gudrus jus klasta pagavau.'),
  (@b47, 12, 17, 'Ar jumis pasipelniau per kurį iš tų, kuriuos jums siunčiau?'),
  (@b47, 12, 18, 'Aš prašiau Tito ir su juo siunčiau brolį. Ar Titas jumis pasipelnė? Ar mes nevaikščiojome ta pačia dvasia? Ar mes nevaikščiojome tomis pačiomis pėdomis?'),
  (@b47, 12, 19, 'Vėlgi, jūs manote, kad teisinamės prieš jus? Mes kalbame Dievo akivaizdoje Kristuje; bet viską darome, brangiai mylimi, jūsų statydinimui.'),
  (@b47, 12, 20, 'Nes bijau, kad atėjęs nerasiu jūsų tokių, kokių noriu, ir kad būsiu jums rastas toks, kokio jūs nenorite; kad nebūtų ginčų, pavydų, rūstybių, barnių, šmeižtų, šnabždėjimų, pasipūtimų, sumišimų;'),
  (@b47, 12, 21, 'kad man vėl atėjus, mano Dievas manęs nepažemintų tarp jūsų, ir kad man nereikėtų apraudoti daugelio, kurie jau nusidėję ir neatgailavę dėl nešvarumo, paleistuvavimo ir gašlumo, kuriuos yra darę.'),
  (@b47, 13, 1, 'Tai trečiasis kartas, kai ateinu pas jus. Dviejų ar trijų liudininkų burnoje bus įtvirtintas kiekvienas žodis.'),
  (@b47, 13, 2, 'Sakiau jums anksčiau ir sakau jums iš anksto, kaip būdamas pas jus antrą kartą; o nebūdamas pas jus, dabar rašau tiems, kurie iki tol nusidėjo, ir visiems kitiems, kad, jei vėl ateisiu, nepasigailėsiu;'),
  (@b47, 13, 3, 'kadangi ieškote įrodymo Kristaus, kalbančio manyje, kuris jums nėra silpnas, bet yra galingas jumyse.'),
  (@b47, 13, 4, 'Nes nors jis buvo nukryžiuotas per silpnumą, tačiau jis gyvena Dievo jėga. Nes ir mes esame silpni jame, bet jums gyvensime su juo Dievo jėga.'),
  (@b47, 13, 5, 'Ištirkite save, ar esate tikėjime; išmėginkite save pačius. Ar nepažįstate savęs, kad Jėzus Kristus yra jumyse, nebent esate atmestini?'),
  (@b47, 13, 6, 'Bet tikiuosi, kad pažinsite, jog mes nesame atmestini.'),
  (@b47, 13, 7, 'Meldžiu gi Dievą, kad nedarytumėte nieko pikto; ne tam, kad mes pasirodytume išmėginti, bet kad jūs darytumėte tai, kas dora, nors mes būtume kaip atmestini.'),
  (@b47, 13, 8, 'Nes nieko negalime padaryti prieš tiesą, o tik už tiesą.'),
  (@b47, 13, 9, 'Nes džiaugiamės, kai esame silpni, o jūs esate stiprūs; ir to dar norime, būtent jūsų tobulumo.'),
  (@b47, 13, 10, 'Todėl tai rašau nebūdamas pas jus, kad būdamas pas jus nepavartočiau aštrumo pagal tą valdžią, kurią man Viešpats yra davęs statydinimui, o ne griovimui.'),
  (@b47, 13, 11, 'Galiausiai, broliai, gerai laikykitės. Būkite tobuli, būkite geros paguodos, būkite vieno proto, gyvenkite taikiai; o meilės ir ramybės Dievas bus su jumis.'),
  (@b47, 13, 12, 'Sveikinkite vienas kitą šventu pabučiavimu.'),
  (@b47, 13, 13, 'Jus sveikina visi šventieji.'),
  (@b47, 13, 14, 'Viešpaties Jėzaus Kristaus malonė ir Dievo meilė, ir Šventosios Dvasios bendrystė tebūna su jumis visais. Amen.'),
  (@b48, 1, 1, 'Paulius, apaštalas (ne nuo žmonių, nei per žmogų, bet per Jėzų Kristų ir Dievą Tėvą, kuris prikėlė jį iš numirusiųjų),'),
  (@b48, 1, 2, 'ir visi su manimi esantys broliai, Galatijos bažnyčioms:'),
  (@b48, 1, 3, 'malonė jums ir ramybė nuo Dievo Tėvo ir nuo mūsų Viešpaties Jėzaus Kristaus,'),
  (@b48, 1, 4, 'kuris atidavė save už mūsų nuodėmes, kad išvaduotų mus iš šio dabartinio pikto pasaulio, pagal valią Dievo ir mūsų Tėvo,'),
  (@b48, 1, 5, 'kuriam tebūna šlovė per amžių amžius. Amen.'),
  (@b48, 1, 6, 'Stebiuosi, kad nuo to, kuris pašaukė jus į Kristaus malonę, taip greitai persimetėte į kitą evangeliją,'),
  (@b48, 1, 7, 'kuri nėra kita; bet yra kai kurie, kurie trikdo jus ir nori iškreipti Kristaus evangeliją.'),
  (@b48, 1, 8, 'Bet nors ir mes ar angelas iš dangaus skelbtų jums kokią kitą evangeliją negu tą, kurią jums paskelbėme, tebūna prakeiktas.'),
  (@b48, 1, 9, 'Kaip sakėme anksčiau, taip vėl dabar sakau: jei kas jums skelbia kokią kitą evangeliją negu tą, kurią priėmėte, tebūna prakeiktas.'),
  (@b48, 1, 10, 'Ar dabar įtikinėju žmones, ar Dievą? Arba, ar siekiu įtikti žmonėms? Nes jei vis dar įtikčiau žmonėms, nebūčiau Kristaus tarnas.'),
  (@b48, 1, 11, 'Bet patvirtinu jums, broliai, kad mano paskelbtoji evangelija nėra pagal žmogų.'),
  (@b48, 1, 12, 'Nes aš nei gavau ją iš žmogaus, nei buvau jos išmokytas, bet per Jėzaus Kristaus apreiškimą.'),
  (@b48, 1, 13, 'Nes girdėjote apie mano gyvenseną praeityje žydų religijoje, kaip virš saiko persekiojau Dievo bažnyčią ir ją niokojau;'),
  (@b48, 1, 14, 'ir žydų religijoje buvau naudingesnis už daugelį man lygių mano tautoje, būdamas nepalyginamai uolesnis dėl savo tėvų tradicijų.'),
  (@b48, 1, 15, 'Bet kai patiko Dievui, kuris atskyrė mane nuo mano motinos įsčių ir pašaukė mane savo malone,'),
  (@b48, 1, 16, 'kad apreikštų manyje savo Sūnų, idant skelbčiau jį tarp pagonių; aš tuojau nesitariau su kūnu ir krauju;'),
  (@b48, 1, 17, 'nei nuvykau aukštyn į Jeruzalę pas tuos, kurie pirmiau manęs buvo apaštalai; bet nuėjau į Arabiją ir vėl sugrįžau į Damaską.'),
  (@b48, 1, 18, 'Paskui, po trejų metų, nuėjau aukštyn į Jeruzalę pasimatyti su Petru ir pasilikau pas jį penkiolika dienų.'),
  (@b48, 1, 19, 'Bet kitų iš apaštalų nei vieno nemačiau, išskyrus Viešpaties brolį Jokūbą.'),
  (@b48, 1, 20, 'Na, o tai, ką jums rašau, štai Dievo akivaizdoje, aš nemeluoju.'),
  (@b48, 1, 21, 'Po to atėjau į Sirijos ir Kilikijos sritis;'),
  (@b48, 1, 22, 'ir iš veido buvau nepažįstamas Judėjos bažnyčioms, kurios buvo Kristuje;'),
  (@b48, 1, 23, 'bet jos tik girdėjo, kad: „Tas, kuris mus praeityje persekiojo, dabar skelbia tikėjimą, kurį kadaise griovė“.'),
  (@b48, 1, 24, 'Ir jos šlovino Dievą manyje.'),
  (@b48, 2, 1, 'Paskui, po keturiolikos metų, vėl nuėjau aukštyn į Jeruzalę su Barnabu, pasiėmęs ir Titą.'),
  (@b48, 2, 2, 'Ir nuėjau aukštyn per apreiškimą ir jiems išdėsčiau tą evangeliją, kurią skelbiu tarp pagonių, bet asmeniškai tiems, kurie buvo gerbiami, kad kokiu būdu nebėgčiau ar nebūčiau bėgęs veltui.'),
  (@b48, 2, 3, 'Bet nei Titas, kuris buvo su manimi, būdamas graikas, nebuvo verčiamas apsipjaustyti;'),
  (@b48, 2, 4, 'o tai dėl netikrų brolių, nejučia įvestų, kurie slapta įėjo šnipinėti mūsų laisvės, kurią turime Kristuje Jėzuje, kad galėtų mus pavergti;'),
  (@b48, 2, 5, 'jiems mes nenusileidome pavaldumui nei valandai; kad evangelijos tiesa pasiliktų su jumis.'),
  (@b48, 2, 6, 'Bet iš tų, kurie atrodė esą kažin kas (kas jie bebuvo, man tai neturi reikšmės: Dievas nepaiso nei vieno žmogaus asmenybės); nes tie, kurie atrodė esą kažin kas, pasitarime man nieko nepridėjo;'),
  (@b48, 2, 7, 'bet priešingai, kai jie pamatė, kad man buvo patikėta neapipjaustymo evangelija, kaip Petrui apipjaustymo evangelija'),
  (@b48, 2, 8, '(nes tas, kuris buvo veiksmingas Petre apipjaustymo apaštalystei, tas pats buvo galingas manyje pagonims);'),
  (@b48, 2, 9, 'ir kai Jokūbas, Kefas ir Jonas, kurie atrodė esą stulpai, suprato tą man duotą malonę, jie padavė man ir Barnabui dešines bendravimo rankas; kad mes eitume pas pagonis, o jie pas apipjaustymą.'),
  (@b48, 2, 10, 'Tiktai jie norėjo, kad mes prisimintume vargšus; tai, ką ir stengiausi daryti.'),
  (@b48, 2, 11, 'Bet kai Petras buvo atėjęs į Antiochą, aš pasipriešinau jam į akis, nes jis buvo peiktinas.'),
  (@b48, 2, 12, 'Nes prieš atvykstant kai kuriems nuo Jokūbo, jis valgė su pagonimis; bet kai jie atvyko, jis atsitraukė ir atsiskyrė, bijodamas tų, kurie buvo iš apipjaustymo.'),
  (@b48, 2, 13, 'Ir kiti žydai taip pat veidmainiavo su juo; iki tiek, kad ir Barnabas buvo jų veidmainystės nuviliotas.'),
  (@b48, 2, 14, 'Bet kai pamačiau, kad jie nevaikšto tiesiai pagal evangelijos tiesą, aš tariau Petrui jų visų akivaizdoje: „Jei tu, būdamas žydas, gyveni pagoniškai, o ne kaip žydai gyvena, kodėl verti pagonis gyventi, kaip žydai gyvena?“'),
  (@b48, 2, 15, 'Mes, iš prigimties žydai, o ne pagonių nusidėjėliai,'),
  (@b48, 2, 16, 'žinodami, kad žmogus neišteisinamas per įstatymo darbus, bet per Jėzaus Kristaus tikėjimą, ir mes įtikėjome Jėzumi Kristumi, kad būtume išteisinti per Kristaus tikėjimą, o ne per įstatymo darbus; nes įstatymo darbais nebus išteisintas joks kūnas.'),
  (@b48, 2, 17, 'Bet jei, ieškodami, kad būtume išteisinti per Kristų, mes ir patys esame rasti nusidėjėliais, ar todėl Kristus yra nuodėmės tarnautojas? Jokiu būdu!'),
  (@b48, 2, 18, 'Nes jei vėl statau tai, ką sugrioviau, darau save nusižengėliu.'),
  (@b48, 2, 19, 'Nes per įstatymą esu miręs įstatymui, kad gyvenčiau Dievui.'),
  (@b48, 2, 20, 'Esu nukryžiuotas su Kristumi: vis dėlto gyvenu; tačiau ne aš, bet Kristus gyvena manyje; ir gyvenimą, kurį dabar gyvenu kūne, gyvenu per Dievo Sūnaus tikėjimą, kuris mane pamilo ir atidavė save už mane.'),
  (@b48, 2, 21, 'Aš neverčiu niekais Dievo malonės; nes jei teisumas ateina per įstatymą, tuomet Kristus yra miręs veltui.'),
  (@b48, 3, 1, 'O kvaili Galatai, kas jus apkerėjo, kad nepaklustumėte tiesai, prieš kurių akis Jėzus Kristus buvo aiškiai pavaizduotas, nukryžiuotas tarp jūsų?'),
  (@b48, 3, 2, 'Vien tai norėčiau iš jūsų sužinoti: ar Dvasią gavote per įstatymo darbus, ar per tikėjimo klausymąsi?'),
  (@b48, 3, 3, 'Ar jūs tokie kvaili? Pradėję Dvasioje ar dabar darotės tobuli kūnu?'),
  (@b48, 3, 4, 'Ar tiek daug iškentėjote veltui? Jei tai būtų dar veltui!'),
  (@b48, 3, 5, 'Taigi tas, kuris jums parūpina Dvasią ir daro stebuklus tarp jūsų, ar jis tai daro per įstatymo darbus, ar per tikėjimo klausymąsi?'),
  (@b48, 3, 6, 'Kaip Abraomas patikėjo Dievu, ir tai jam buvo įskaityta teisumu.'),
  (@b48, 3, 7, 'Todėl žinokite, kad tie, kurie yra iš tikėjimo, tie yra Abraomo vaikai.'),
  (@b48, 3, 8, 'Ir Raštas, iš anksto numatydamas, kad Dievas išteisins pagonis per tikėjimą, prieš tai paskelbė Abraomui evangeliją, sakydamas: „Tavyje bus palaimintos visos tautos“.'),
  (@b48, 3, 9, 'Taip tad tie, kurie yra iš tikėjimo, yra palaiminti su ištikimuoju Abraomu.'),
  (@b48, 3, 10, 'Nes visi, esantys iš įstatymo darbų, yra prakeikimo valdžioje, nes yra parašyta: „Prakeiktas kiekvienas, nepasiliekantis visame tame, kas yra surašyta įstatymo knygoje, kad tai darytų“.'),
  (@b48, 3, 11, 'Bet kad niekas neišteisinamas per įstatymą Dievo akyse, yra aišku, nes: „Teisusis gyvens tikėjimu“.'),
  (@b48, 3, 12, 'O įstatymas nėra iš tikėjimo, bet: „Žmogus, kuris juos daro, juose gyvens“.'),
  (@b48, 3, 13, 'Kristus mus atpirko iš įstatymo prakeikimo, už mus tapęs prakeikimu, nes yra parašyta: „Prakeiktas kiekvienas, kuris kabo ant medžio“;'),
  (@b48, 3, 14, 'kad Abraomo palaiminimas ateitų ant pagonių per Jėzų Kristų; kad mes per tikėjimą gautume Dvasios pažadą.'),
  (@b48, 3, 15, 'Broliai, kalbu pagal žmogaus būdą; nors tai būtų tik žmogaus sandora, tačiau jei ji būtų patvirtinta, niekas jos nepanaikina nei prie jos prideda.'),
  (@b48, 3, 16, 'Abraomui gi ir jo sėklai buvo duoti pažadai. Jis nesako: „Ir sėkloms“, kaip apie daugelį, bet kaip apie vieną: „Ir tavo sėklai“, kuri yra Kristus.'),
  (@b48, 3, 17, 'Ir tai sakau, kad sandoros, kuri anksčiau buvo Dievo patvirtinta Kristuje, negali panaikinti po keturių šimtų trisdešimties metų atsiradęs įstatymas, kad pažadą paverstų negaliojančiu.'),
  (@b48, 3, 18, 'Nes jei paveldas būtų iš įstatymo, tai jau nebe iš pažado; bet Dievas davė jį Abraomui per pažadą.'),
  (@b48, 3, 19, 'Tai kam reikalingas įstatymas? Jis buvo pridėtas dėl nusižengimų, kol ateis sėkla, kuriai buvo duotas pažadas; ir buvo parengtas per angelus tarpininko rankoje.'),
  (@b48, 3, 20, 'Tarpininkas gi nėra vieno tarpininkas, bet Dievas yra vienas.'),
  (@b48, 3, 21, 'Ar tad įstatymas priešingas Dievo pažadams? Jokiu būdu! Nes jei būtų duotas įstatymas, galintis suteikti gyvenimą, tai iš tikrųjų teisumas būtų buvęs per įstatymą.'),
  (@b48, 3, 22, 'Bet Raštas viską užrakino nuodėmės valdžioje, kad pažadas per Jėzaus Kristaus tikėjimą būtų duotas tiems, kurie tiki.'),
  (@b48, 3, 23, 'Bet prieš ateinant tikėjimui mes buvome saugomi įstatymo valdžioje, užrakinti iki to tikėjimo, kuris po to turėjo būti apreikštas.'),
  (@b48, 3, 24, 'Todėl įstatymas buvo mūsų auklėtojas, kad atvestų mus iki Kristaus, kad būtume išteisinti tikėjimu.'),
  (@b48, 3, 25, 'Bet atėjus tikėjimui, mes nebesame auklėtojo valdžioje.'),
  (@b48, 3, 26, 'Nes jūs visi esate Dievo vaikai per tikėjimą į Kristų Jėzų.'),
  (@b48, 3, 27, 'Nes jūs visi, kurie buvote pakrikštyti į Kristų, apsivilkote Kristumi.'),
  (@b48, 3, 28, 'Nėra nei žydo, nei graiko, nėra nei vergo, nei laisvojo, nėra nei vyriškos lyties, nei moteriškos lyties: nes jūs visi esate viena Kristuje Jėzuje.'),
  (@b48, 3, 29, 'O jei esate Kristaus, tada esate Abraomo sėkla ir paveldėtojai pagal pažadą.'),
  (@b48, 4, 1, 'Sakau gi, kad, kol paveldėtojas yra vaikas, jis niekuo nesiskiria nuo tarno, nors ir yra visų viešpats;'),
  (@b48, 4, 2, 'bet yra auklėtojų ir valdytojų valdžioje iki tėvo nustatyto laiko.'),
  (@b48, 4, 3, 'Taip ir mes, kai buvome vaikai, buvome pasaulio pradmenų vergijoje;'),
  (@b48, 4, 4, 'bet kai atėjo laiko pilnatvė, Dievas išsiuntė savo Sūnų, padarytą iš moters, padarytą pavaldžiu įstatymui,'),
  (@b48, 4, 5, 'kad atpirktų esančius įstatymo valdžioje, kad mes gautume įsūnystę.'),
  (@b48, 4, 6, 'O kadangi esate sūnūs, Dievas išsiuntė į jūsų širdis savo Sūnaus Dvasią, šaukiančią: „Aba, Tėve“.'),
  (@b48, 4, 7, 'Todėl tu jau nebesi tarnas, bet sūnus; o jei sūnus, tuomet Dievo paveldėtojas per Kristų.'),
  (@b48, 4, 8, 'Tačiau tada, kai nepažinojote Dievo, jūs tarnavote tiems, kurie prigimtimi nėra dievai.'),
  (@b48, 4, 9, 'Bet dabar, kai esate pažinę Dievą arba verčiau esate Dievo pažinti, kaipgi vėl gręžiatės į silpnus ir elgetiškus pradmenis, kuriems vėl trokštate vergauti?'),
  (@b48, 4, 10, 'Jūs laikotės dienų ir mėnesių, ir laikų, ir metų.'),
  (@b48, 4, 11, 'Bijau dėl jūsų, kad nebūčiau jums triūsą skyręs veltui.'),
  (@b48, 4, 12, 'Broliai, maldauju jus, būkite kaip aš; nes aš esu, kaip jūs: jūs manęs visiškai neįžeidėte.'),
  (@b48, 4, 13, 'Jūs žinote, kaip per kūno negalią pirmą kartą paskelbiau jums evangeliją.'),
  (@b48, 4, 14, 'Ir jūs nepaniekinote nei neatmetėte mano kūne buvusios pagundos; bet priėmėte mane kaip Dievo angelą, kaip Kristų Jėzų.'),
  (@b48, 4, 15, 'Tad kurgi yra palaima, apie kurią kalbėjote? Nes aš jums liudiju, kad, jei būtų buvę įmanoma, jūs būtumėte išsilupę savo akis ir jas man atidavę.'),
  (@b48, 4, 16, 'Ar tapau jūsų priešu todėl, kad kalbu jums tiesą?'),
  (@b48, 4, 17, 'Jie uoliai jus veikia, bet ne gerai; taip, jie norėtų jus atitraukti, kad būtumėte uolūs dėl jų.'),
  (@b48, 4, 18, 'Bet gerai būti visada uoliai veikiamiems dėl gero, ir ne vien tuomet, kai esu pas jus.'),
  (@b48, 4, 19, 'Mano vaikeliai, dėl kurių vėl kenčiu gimdymo skausmus, kol Kristus susiformuos jumyse,'),
  (@b48, 4, 20, 'trokštu dabar būti pas jus ir pakeisti savo balsą; nes abejoju dėl jūsų.'),
  (@b48, 4, 21, 'Pasakykite man jūs, trokštantys būti įstatymo valdžioje, ar negirdite įstatymo?'),
  (@b48, 4, 22, 'Nes yra parašyta, kad Abraomas turėjo du sūnus: vieną iš vergės, kitą iš laisvosios.'),
  (@b48, 4, 23, 'Bet tas iš vergės buvo gimęs pagal kūną; o tas iš laisvosios – per pažadą.'),
  (@b48, 4, 24, 'Tai yra alegorija, nes šios yra dvi sandoros: viena iš Sinajaus kalno, gimdanti vergystei, kuri yra Agara.'),
  (@b48, 4, 25, 'Nes ši Agara yra Sinajaus kalnas Arabijoje ir atitinka Jeruzalę, kuri dabar yra, ir yra vergystėje su savo vaikais.'),
  (@b48, 4, 26, 'Bet Jeruzalė, esanti aukštai, yra laisva, kuri yra visų mūsų motina.'),
  (@b48, 4, 27, 'Nes yra parašyta: „Džiaukis, nevaisingoji, kuri negimdai; pratrūk ir šauk tu, neturinti gimdymo skausmų; nes apleistoji turi daug daugiau vaikų, negu turinčioji vyrą“.'),
  (@b48, 4, 28, 'Mes gi, broliai, kaip Izaokas buvo, esame pažado vaikai.'),
  (@b48, 4, 29, 'Bet kaip tuomet gimusysis pagal kūną persekiojo gimusįjį pagal Dvasią, taip ir dabar.'),
  (@b48, 4, 30, 'Tačiau ką sako Raštas? „Išvaryk vergę ir jos sūnų; nes vergės sūnus nebus paveldėtojas su laisvosios sūnumi“.'),
  (@b48, 4, 31, 'Taip kad, broliai, mes esame ne vergės vaikai, bet laisvosios.'),
  (@b48, 5, 1, 'Todėl tvirtai stovėkite laisvėje, kuria Kristus mus išlaisvino, ir neįsipainiokite vėl į vergystės jungą.'),
  (@b48, 5, 2, 'Štai aš, Paulius, sakau jums, kad, jei apsipjaustysite, Kristus jums nebus niekuo naudingas.'),
  (@b48, 5, 3, 'Nes vėl liudiju kiekvienam, kuris apipjaustomas, jog jis yra skolininkas, kad vykdytų visą įstatymą.'),
  (@b48, 5, 4, 'Kristus tapo neveiksmingu jums, kurie iš jūsų teisinatės įstatymu; jūs atkritote nuo malonės.'),
  (@b48, 5, 5, 'Nes mes per Dvasią tikėjimu laukiame teisumo vilties.'),
  (@b48, 5, 6, 'Nes Jėzuje Kristuje nei apipjaustymas neduoda naudos, nei neapipjaustymas; bet tikėjimas, veikiantis meile.'),
  (@b48, 5, 7, 'Jūs gerai bėgote; kas jums sutrukdė, kad nepaklustumėte tiesai?'),
  (@b48, 5, 8, 'Šis įtikinimas ateina ne iš to, kuris jus šaukia.'),
  (@b48, 5, 9, 'Truputis raugo įraugina visą minkalą.'),
  (@b48, 5, 10, 'Pasitikiu jumis per Viešpatį, kad nebūsite kitaip nusiteikę; bet tas, kuris jus trikdo, kas jis bebūtų, nešios savąjį teismą.'),
  (@b48, 5, 11, 'O aš, broliai, jei vis dar skelbiu apipjaustymą, kodėl dar kenčiu persekiojimą? Tuomet kryžiaus papiktinimas yra liovęsis.'),
  (@b48, 5, 12, 'Norėčiau, kad tie, kurie jus trikdo, būtų iškirsti.'),
  (@b48, 5, 13, 'Nes jūs, broliai, buvote pašaukti į laisvę; tik nenaudokite laisvės kaip progos kūnui, bet meile tarnaukite vienas kitam.'),
  (@b48, 5, 14, 'Nes visas įstatymas yra išpildomas viename žodyje, būtent šiame: „Mylėk savo artimą kaip save“.'),
  (@b48, 5, 15, 'Bet jei kandžiojate ir ryjate vienas kitą, žiūrėkite, kad nebūtumėte vienas kito sunaikinti.'),
  (@b48, 5, 16, 'Tad sakau tai: vaikščiokite Dvasioje, ir nepildysite kūno geidulių.'),
  (@b48, 5, 17, 'Nes kūnas geidžia priešingo Dvasiai, o Dvasia priešingo kūnui; ir šitie yra priešingi vienas kitam; taip, kad negalite padaryti to, ko norite.'),
  (@b48, 5, 18, 'Bet jei esate Dvasios vedami, nesate įstatymo valdžioje.'),
  (@b48, 5, 19, 'Kūno gi darbai yra aiškūs, kurie yra šie: svetimavimas, paleistuvavimas, nešvarumas, gašlumas,'),
  (@b48, 5, 20, 'stabmeldystė, raganavimas, neapykanta, nesutarimas, rungtyniavimai, rūstybė, vaidai, kurstymai, erezijos,'),
  (@b48, 5, 21, 'pavydai, žmogžudystės, girtavimai, ūžavimai ir panašūs tokie; apie kuriuos sakau iš anksto, kaip ir esu jums sakęs praeityje, kad tie, kurie taip daro, nepaveldės Dievo karalystės.'),
  (@b48, 5, 22, 'Bet Dvasios vaisius yra meilė, džiaugsmas, ramybė, ilgas pakantumas, švelnumas, gerumas, tikėjimas,'),
  (@b48, 5, 23, 'romumas, susivaldymas – prieš tokius nėra įstatymo.'),
  (@b48, 5, 24, 'O kurie yra Kristaus, tie nukryžiavo kūną su prisirišimais ir geismais.'),
  (@b48, 5, 25, 'Jei gyvename Dvasioje, tai ir vaikščiokime Dvasioje.'),
  (@b48, 5, 26, 'Netrokškime tuščios šlovės, erzindami vienas kitą, pavydėdami vienas kitam.'),
  (@b48, 6, 1, 'Broliai, jei žmogus būtų užvaldytas nusižengime, jūs, kurie esate dvasiški, atstatykite tokį su romia dvasia; žiūrėdamas savęs, kad pats nebūtumei sugundytas.'),
  (@b48, 6, 2, 'Nešiokite vieni kitų naštas ir taip išpildykite Kristaus įstatymą.'),
  (@b48, 6, 3, 'Nes jei kas, būdamas niekas, mano esąs kažin kas, tas save apgaudinėja.'),
  (@b48, 6, 4, 'Bet kiekvienas teišmėgina savo darbą, ir tada galės džiūgauti pačiame savyje, o ne kitame.'),
  (@b48, 6, 5, 'Nes kiekvienas neš savo paties naštą.'),
  (@b48, 6, 6, 'Kas mokomas žodžio, tegul dalijasi visomis gėrybėmis su tuo, kuris moko.'),
  (@b48, 6, 7, 'Neapsigaukite; iš Dievo nepasišaipysi; nes ką žmogus sėja, tai ir pjaus.'),
  (@b48, 6, 8, 'Nes tas, kas sėja savo kūnui, iš kūno pjaus sugedimą; bet tas, kas sėja Dvasiai, iš Dvasios pjaus amžinąjį gyvenimą.'),
  (@b48, 6, 9, 'Ir nenuvarkime darydami gera, nes tinkamu laiku pjausime, jei nenusilpsime.'),
  (@b48, 6, 10, 'Todėl kai turime progą, darykime gera visiems, ypač tikėjimo namiškiams.'),
  (@b48, 6, 11, 'Matote, kokį didelį laišką jums parašiau savo ranka.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b48, 6, 12, 'Visi, kurie trokšta gerai pasirodyti kūnu, verčia jus apsipjaustyti tik tam, kad jiems nereikėtų kentėti persekiojimo dėl Kristaus kryžiaus.'),
  (@b48, 6, 13, 'Nes nei jie patys, kurie yra apipjaustyti, nesilaiko įstatymo; bet trokšta, kad jūs būtumėte apipjaustyti, kad jie galėtų pasigirti jūsų kūnu.'),
  (@b48, 6, 14, 'Bet apsaugok Dieve, kad aš kuo girčiausi, išskyrus kryžiumi mūsų Viešpaties Jėzaus Kristaus, per kurį pasaulis man yra nukryžiuotas, ir aš pasauliui.'),
  (@b48, 6, 15, 'Nes Kristuje Jėzuje niekuo nenaudingas nei apipjaustymas, nei neapipjaustymas, bet tik naujas sutvėrimas.'),
  (@b48, 6, 16, 'Ir visi, kurie vaikšto pagal šią taisyklę, ramybė ir gailestingumas tebūna jiems; ir Dievo Izraeliui.'),
  (@b48, 6, 17, 'Nuo šiol niekas tenetrukdo manęs, nes savo kūne nešioju Viešpaties Jėzaus žymes.'),
  (@b48, 6, 18, 'Broliai, mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jūsų dvasia. Amen.'),
  (@b49, 1, 1, 'Paulius, Dievo valia Jėzaus Kristaus apaštalas, šventiesiems, esantiems Efeze, ir ištikimiesiems Kristuje Jėzuje:'),
  (@b49, 1, 2, 'malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir nuo Viešpaties Jėzaus Kristaus.'),
  (@b49, 1, 3, 'Tebūna palaimintas Dievas ir mūsų Viešpaties Jėzaus Kristaus Tėvas, kuris palaimino mus visais dvasiniais palaiminimais dangiškose vietose Kristuje;'),
  (@b49, 1, 4, 'pagal tai, kaip jis mus jame išsirinko prieš pasaulio pamato padėjimą, kad būtume šventi ir be kaltės jo akivaizdoje meilėje;'),
  (@b49, 1, 5, 'iš anksto mus paskyręs sau įvaikinti per Jėzų Kristų pagal gerą savo valios norą,'),
  (@b49, 1, 6, 'šlovės gyriui savo malonės, kuria jis padarė mus priimtinus Mylimajame.'),
  (@b49, 1, 7, 'Kuriame turime atpirkimą per jo kraują, nuodėmių atleidimą, pagal turtus jo malonės,'),
  (@b49, 1, 8, 'kurioje jis buvo mums gausus visa išmintimi ir protingumu;'),
  (@b49, 1, 9, 'davęs mums žinoti savo valios paslaptį pagal savo gerą norą, kurį jis sumanė savyje,'),
  (@b49, 1, 10, 'kad laikų pilnatvės ūkvedyboje jis surinktų į viena Kristuje visa tai, kas yra tiek danguje, tiek žemėje; būtent jame,'),
  (@b49, 1, 11, 'kuriame gavome ir paveldą, būdami iš anksto paskirti pagal tikslą to, kuris visa daro pagal savo valios nutarimą,'),
  (@b49, 1, 12, 'kad būtume jo šlovės gyriui mes, kurie pirmi pasitikėjome Kristumi.'),
  (@b49, 1, 13, 'Kuriuo ir jūs pasitikėjote, išgirdę tiesos žodį, jūsų išgelbėjimo evangeliją; kuriuo įtikėję buvote ir užantspauduoti ta šventa pažado Dvasia,'),
  (@b49, 1, 14, 'kuri yra mūsų paveldo užstatas iki nupirktos nuosavybės atpirkimo, jo šlovės gyriui.'),
  (@b49, 1, 15, 'Todėl ir aš, išgirdęs apie jūsų tikėjimą Viešpačiu Jėzumi ir meilę visiems šventiesiems,'),
  (@b49, 1, 16, 'nepaliauju už jus dėkoti, minėdamas jus savo maldose;'),
  (@b49, 1, 17, 'kad mūsų Viešpaties Jėzaus Kristaus Dievas, šlovės Tėvas, duotų jums išminties ir apreiškimo dvasią jo pažinime,'),
  (@b49, 1, 18, 'apšvietus jūsų supratimo akis; kad pažintumėte, kokia yra jo pašaukimo viltis ir kokie jo paveldo šlovės turtai šventuosiuose,'),
  (@b49, 1, 19, 'ir kokia viršijanti jo jėgos didybė mums, kurie tikime, pagal veikimą jo galingos jėgos,'),
  (@b49, 1, 20, 'kuria jis veikė Kristuje, kai prikėlė jį iš numirusiųjų ir pasodino savo dešinėje dangiškose vietose,'),
  (@b49, 1, 21, 'daug aukščiau už kiekvieną kunigaikštystę, valdžią, galybę, viešpatystę ir kiekvieną vardą, kuris minimas ne tik šiame pasaulyje, bet ir ateinančiame;'),
  (@b49, 1, 22, 'ir visa padėjo po jo kojomis ir davė jį būti galva viršum visko bažnyčiai,'),
  (@b49, 1, 23, 'kuri yra jo kūnas, pilnuma jo, kuris visa visame pripildo.'),
  (@b49, 2, 1, 'Ir jis atgaivino jus, kurie buvote mirę nusižengimuose ir nuodėmėse;'),
  (@b49, 2, 2, 'kuriuose praeityje vaikščiojote pagal šio pasaulio eigą, pagal oro valdžios kunigaikštį, dvasią, kuri dabar veikia neklusnumo vaikuose;'),
  (@b49, 2, 3, 'tarp kurių ir mes visi praeityje elgėmės pagal savo kūno geidulius, pildydami kūno ir proto troškimus; ir prigimtimi buvome rūstybės vaikai, kaip ir kiti.'),
  (@b49, 2, 4, 'Bet Dievas, kuris turtingas gailestingumu, dėl savo didžios meilės, kuria mus pamilo,'),
  (@b49, 2, 5, 'būtent kai buvome mirę nuodėmėse, atgaivino mus kartu su Kristumi (jūs esate išgelbėti malone)'),
  (@b49, 2, 6, 'ir prikėlė mus kartu, ir pasodino mus kartu dangiškose vietose Kristuje Jėzuje;'),
  (@b49, 2, 7, 'kad ateinančiais amžiais savo gerumu mums per Jėzų Kristų jis parodytų viršijančius savo malonės turtus.'),
  (@b49, 2, 8, 'Nes jūs esate išgelbėti malone per tikėjimą; ir tai ne iš jūsų – tai Dievo dovana;'),
  (@b49, 2, 9, 'ne dėl darbų, idant kuris nesigirtų.'),
  (@b49, 2, 10, 'Nes mes esame jo darbas, sutverti Kristuje Jėzuje geriems darbams, kuriuos Dievas iš anksto paskyrė, kad juose vaikščiotume.'),
  (@b49, 2, 11, 'Todėl atsiminkite, kad jūs, praeityje būdami kūnu pagonys, kuriuos Neapipjaustymu vadino tie, kurie vadinosi Apipjaustymu, rankomis atliktu kūne;'),
  (@b49, 2, 12, 'kad anuo laiku buvote be Kristaus, atitolinti nuo Izraelio sandraugos ir svetimi pažado sandoroms, neturintys vilties ir be Dievo pasaulyje;'),
  (@b49, 2, 13, 'bet dabar Kristuje Jėzuje jūs, kurie kadaise buvote toli, per Kristaus kraują tapote artimi.'),
  (@b49, 2, 14, 'Nes jis yra mūsų taika, kuris iš abejų padarė viena ir nugriovė atskyrimo sieną tarp mūsų;'),
  (@b49, 2, 15, 'savo kūne panaikinęs priešiškumą, būtent įsakymų įstatymą, turintį įsakus; kad padarytų savyje iš dviejų vieną naują žmogų, taip darydamas taiką;'),
  (@b49, 2, 16, 'ir kad jis abejus sutaikytų su Dievu viename kūne per kryžių, juo užmušdamas priešiškumą;'),
  (@b49, 2, 17, 'ir atėjęs paskelbė taiką jums, buvusiems toli, ir jiems, buvusiems arti.'),
  (@b49, 2, 18, 'Nes per jį mes abeji turime priėjimą prie Tėvo viena Dvasia.'),
  (@b49, 2, 19, 'Todėl dabar nebesate ateiviai ir svetimšaliai, bet bendrapiliečiai su šventaisiais ir Dievo namiškiai;'),
  (@b49, 2, 20, 'ir esate pastatyti ant apaštalų ir pranašų pamato, pačiam Jėzui Kristui esant kertiniu akmeniu;'),
  (@b49, 2, 21, 'kuriame visas pastatas suderintai sudėtas auga į šventą šventyklą Viešpatyje;'),
  (@b49, 2, 22, 'kuriame ir jūs kartu statomi Dievo buveine per Dvasią.'),
  (@b49, 3, 1, 'Dėl to aš, Paulius, Jėzaus Kristaus kalinys dėl jūsų, pagonių,'),
  (@b49, 3, 2, 'jei girdėjote apie Dievo malonės ūkvedybą, kuri duota man dėl jūsų;'),
  (@b49, 3, 3, 'kaip apreiškimu jis davė man žinoti paslaptį (kaip anksčiau parašiau keletu žodžių,'),
  (@b49, 3, 4, 'iš kurių, kai skaitote, galite suprasti mano pažinimą tos Kristaus paslapties),'),
  (@b49, 3, 5, 'kuri kitais amžiais nebuvo duota žinoti žmonių sūnums, kaip ji dabar atskleista jo šventiems apaštalams ir pranašams per Dvasią;'),
  (@b49, 3, 6, 'kad pagonys turi būti bendrapaveldėtojai ir to paties kūno, ir jo pažado dalininkai Kristuje per evangeliją;'),
  (@b49, 3, 7, 'kurios tarnu tapau pagal Dievo malonės dovaną, man duotą veiksmingu jo jėgos veikimu.'),
  (@b49, 3, 8, 'Man, mažesniam už mažiausiąjį iš visų šventųjų, yra duota ši malonė, kad tarp pagonių skelbčiau neištiriamus Kristaus turtus;'),
  (@b49, 3, 9, 'ir padaryčiau, kad visi pamatytų, kokia yra bendrystė šios paslapties, kuri nuo pasaulio pradžios buvo paslėpta Dieve, kuris visa sutvėrė per Jėzų Kristų;'),
  (@b49, 3, 10, 'tam, kad dabar kunigaikštystėms ir valdžioms dangiškose vietose per bažnyčią taptų žinoma daugeriopa Dievo išmintis,'),
  (@b49, 3, 11, 'pagal amžinąjį tikslą, kurį jis sumanė Kristuje Jėzuje, mūsų Viešpatyje;'),
  (@b49, 3, 12, 'kuriame per jo tikėjimą mes turime drąsą ir priėjimą su pasitikėjimu.'),
  (@b49, 3, 13, 'Todėl prašau, kad nenusilptumėte dėl mano suspaudimų jūsų labui, kurie yra jūsų šlovė.'),
  (@b49, 3, 14, 'Dėl to lenkiu savo kelius mūsų Viešpaties Jėzaus Kristaus Tėvui,'),
  (@b49, 3, 15, 'nuo kurio yra įvardinta visa šeima danguje ir žemėje,'),
  (@b49, 3, 16, 'kad jis pagal savo šlovės turtus duotų jums būti sustiprintais galybe per jo Dvasią vidiniame žmoguje;'),
  (@b49, 3, 17, 'kad Kristus per tikėjimą gyventų jūsų širdyse; kad jūs, įsišaknyję ir įsitvirtinę meilėje,'),
  (@b49, 3, 18, 'pajėgtumėte su visais šventaisiais suvokti, kas yra plotis ir ilgis, ir gylis, ir aukštis;'),
  (@b49, 3, 19, 'ir pažinti Kristaus meilę, kuri pranoksta pažinimą, kad būtumėte pripildyti visa Dievo pilnatve.'),
  (@b49, 3, 20, 'Na, o tam, kuris pagal jėgą, veikiančią mumyse, yra pajėgus padaryti nepalyginamai gausiau viso to, ko prašome ar galvojame,'),
  (@b49, 3, 21, 'jam tebūna šlovė bažnyčioje per Kristų Jėzų per visus amžius pasaulyje be pabaigos. Amen.'),
  (@b49, 4, 1, 'Todėl aš, Viešpaties kalinys, jus maldauju, kad vaikščiotumėte verti to pašaukimo, kuriuo esate pašaukti,'),
  (@b49, 4, 2, 'su visu nuolankumu ir romumu, su ilgu pakantumu, pakęsdami vienas kitą meilėje;'),
  (@b49, 4, 3, 'stengdamiesi išlaikyti Dvasios vienybę taikos ryšiu.'),
  (@b49, 4, 4, 'Yra vienas kūnas ir viena Dvasia, kaip ir esate pašaukti vienoje jūsų pašaukimo viltyje;'),
  (@b49, 4, 5, 'vienas Viešpats, vienas tikėjimas, vienas krikštas,'),
  (@b49, 4, 6, 'vienas Dievas ir visų Tėvas, kuris yra virš visų ir per visus ir visuose jumyse.'),
  (@b49, 4, 7, 'Bet kiekvienam iš mūsų duota malonė pagal Kristaus dovanos matą.'),
  (@b49, 4, 8, 'Todėl jis sako: „Kai jis pakilo į aukštybę, jis nelaisvę nuvedė nelaisvėn ir davė žmonėms dovanų“'),
  (@b49, 4, 9, '(na, o kad jis pakilo, kas gi tai, jei ne tai, kad jis pirma ir nusileido į žemesniąsias žemės dalis?'),
  (@b49, 4, 10, 'Tas, kuris nusileido, yra tas pats, kuris ir pakilo daug aukščiau visų dangų, kad visa pripildytų).'),
  (@b49, 4, 11, 'Ir jis davė kai kuriuos apaštalais; kai kuriuos pranašais; kai kuriuos evangelistais; kai kuriuos pastoriais ir mokytojais;'),
  (@b49, 4, 12, 'šventųjų tobulinimui, tarnystės darbui, Kristaus kūno statydinimui,'),
  (@b49, 4, 13, 'kol mes visi ateisime į tikėjimo ir Dievo Sūnaus pažinimo vienybę, į tobulą žmogų, į Kristaus pilnatvės ūgio matą;'),
  (@b49, 4, 14, 'kad daugiau nebebūtume vaikai, mėtomi šen bei ten ir nešiojami visokio mokslo vėjo per žmonių gudrybes ir sumanią klastą, kuo jie tykoja, kad apgautų;'),
  (@b49, 4, 15, 'bet kalbėdami tiesą meilėje, visu kuo augtume į jį, kuris yra galva, būtent Kristus;'),
  (@b49, 4, 16, 'iš kurio visas kūnas suderintai sujungtas ir suglaustas kiekvieno sąnario tiekimu, pagal veiksmingą darbą kiekvienos dalies matu, augina kūną savo statydinimui meilėje.'),
  (@b49, 4, 17, 'Todėl tai sakau ir liudiju Viešpatyje, kad nuo šiol nebevaikščiotumėte, kaip kiti pagonys vaikšto savo proto tuštybėje,'),
  (@b49, 4, 18, 'turėdami aptemusį supratimą, būdami atitolę nuo Dievo gyvenimo per juose esantį nežinojimą, dėl jų širdies aklumo;'),
  (@b49, 4, 19, 'praradę pojūtį, jie atidavė save gašlumui, kad su godumu darytų visas nešvarybes.'),
  (@b49, 4, 20, 'Bet jūs ne taip išmokote Kristų;'),
  (@b49, 4, 21, 'jei taip yra, kad jį girdėjote ir buvote jo išmokyti, kaip tiesa yra Jėzuje,'),
  (@b49, 4, 22, 'kad dėl ankstesnės gyvensenos nusivilkote senąjį žmogų, kuris sugedęs pagal apgaulingus geismus;'),
  (@b49, 4, 23, 'ir būkite atsinaujinę savo proto dvasioje;'),
  (@b49, 4, 24, 'ir kad apsivilkote nauju žmogumi, kuris pagal Dievą yra sutvertas teisume ir tikrame šventume.'),
  (@b49, 4, 25, 'Todėl pašalinę melą kiekvienas kalbėkite tiesą su savo artimu; nes esame vienas kito nariai.'),
  (@b49, 4, 26, 'Pykite, bet nenusidėkite: tenenusileidžia saulė ant jūsų rūstybės;'),
  (@b49, 4, 27, 'nei neduokite vietos velniui.'),
  (@b49, 4, 28, 'Kas vogė, tegul nebevagia, bet verčiau tegul triūsia, dirbdamas savo rankomis tai, kas gera, kad turėtų ko duoti stokojančiajam.'),
  (@b49, 4, 29, 'Sugedusi kalba teneišeina iš jūsų burnos, bet tai, kas gera, statydinimo naudai, kad tai duotų malonę klausytojams.'),
  (@b49, 4, 30, 'Ir neliūdinkite šventos Dievo Dvasios, kuria esate užantspauduoti atpirkimo dienai.'),
  (@b49, 4, 31, 'Visa kartybė ir rūstybė, ir pyktis, ir rėkavimas, ir pikta kalba su visa piktybe tebūna pašalinti nuo jūsų;'),
  (@b49, 4, 32, 'ir būkite geri vienas kitam, minkštaširdžiai, atleisdami vienas kitam, kaip ir Dievas dėlei Kristaus jums atleido.'),
  (@b49, 5, 1, 'Taigi būkite Dievo sekėjai, kaip mieli vaikai;'),
  (@b49, 5, 2, 'ir vaikščiokite meilėje, kaip ir Kristus mus pamilo ir atidavė save už mus – atnašą ir auką Dievui dėl gardaus kvapo.'),
  (@b49, 5, 3, 'Bet paleistuvystė ir visokia nešvarybė ar godulystė nei karto tenebūna minima tarp jūsų, kaip tinka šventiesiems;'),
  (@b49, 5, 4, 'nei nešvankumas, nei kvaila šneka, nei juokavimas, kurie netinka; bet verčiau dėkojimas.'),
  (@b49, 5, 5, 'Nes žinokite tai, kad joks paleistuvis nei nešvarus, nei godus, kuris yra stabmeldys, neturi jokio paveldo Kristaus ir Dievo karalystėje.'),
  (@b49, 5, 6, 'Niekas teneapgauna jūsų tuščiais žodžiais; nes dėl šitų dalykų Dievo rūstybė ateina ant neklusnumo vaikų.'),
  (@b49, 5, 7, 'Todėl nebūkite su jais dalininkai.'),
  (@b49, 5, 8, 'Nes kadaise buvote tamsa, bet dabar esate šviesa Viešpatyje: vaikščiokite kaip šviesos vaikai'),
  (@b49, 5, 9, '(nes Dvasios vaisius yra visokiame gerume ir teisume bei tiesoje),'),
  (@b49, 5, 10, 'išmėgindami, kas Viešpačiui yra priimtina.'),
  (@b49, 5, 11, 'Ir neturėkite bendrystės su nevaisingais tamsos darbais, bet verčiau juos papeikite.'),
  (@b49, 5, 12, 'Nes gėda netgi kalbėti apie tai, kas jų yra daroma slapčia.'),
  (@b49, 5, 13, 'Bet visa, kas yra papeikta, yra šviesos atskleista; nes tai, kas atskleidžia, yra šviesa.'),
  (@b49, 5, 14, 'Todėl jis sako: „Atsibusk, kuris miegi, ir kelkis iš numirusiųjų, ir Kristus tave apšvies“.'),
  (@b49, 5, 15, 'Tad žiūrėkite, kad vaikščiotumėte apdairiai, ne kaip kvailiai, bet kaip išmintingi,'),
  (@b49, 5, 16, 'atpirkdami laiką, nes dienos yra piktos.'),
  (@b49, 5, 17, 'Todėl nebūkite neišmintingi, bet suprantantys, kokia yra Viešpaties valia.'),
  (@b49, 5, 18, 'Ir nebūkite prisigėrę vyno, kuriame yra nesaikingumas; bet būkite prisipildę Dvasios;'),
  (@b49, 5, 19, 'kalbėdami sau psalmėmis ir himnais bei dvasinėmis giesmėmis, giedodami ir kurdami savo širdyje melodiją Viešpačiui;'),
  (@b49, 5, 20, 'visada už viską dėkodami Dievui ir Tėvui mūsų Viešpaties Jėzaus Kristaus vardu;'),
  (@b49, 5, 21, 'paklusdami vieni kitiems Dievo baimėje.'),
  (@b49, 5, 22, 'Žmonos, pakluskite savo vyrams, kaip Viešpačiui.'),
  (@b49, 5, 23, 'Nes vyras yra žmonos galva, kaip ir Kristus yra bažnyčios galva; ir jis yra kūno gelbėtojas.'),
  (@b49, 5, 24, 'Todėl, kaip bažnyčia pavaldi Kristui, taip ir žmonos visame kame tebūna savo vyrams.'),
  (@b49, 5, 25, 'Vyrai, mylėkite savo žmonas, kaip ir Kristus mylėjo bažnyčią, ir atidavė save už ją;'),
  (@b49, 5, 26, 'kad jis pašvęstų ją ir apvalytų vandens nuplovimu per žodį,'),
  (@b49, 5, 27, 'kad pristatytų ją sau šlovinga bažnyčia, neturinčia dėmės ar raukšlės, ar ko nors tokio; bet kad ji būtų šventa ir be kaltės.'),
  (@b49, 5, 28, 'Vyrai taip turi mylėti savo žmonas, kaip savo pačių kūnus. Kas myli savo žmoną, myli save.'),
  (@b49, 5, 29, 'Nes niekas niekada nėra nekentęs savo kūno; bet jį maitina ir globoja, kaip ir Viešpats bažnyčią;'),
  (@b49, 5, 30, 'nes mes esame jo kūno nariai, jo mėsos ir jo kaulų.'),
  (@b49, 5, 31, 'Todėl vyras paliks savo tėvą bei motiną ir susijungs su savo žmona, ir jie abu bus vienas kūnas.'),
  (@b49, 5, 32, 'Tai yra didelė paslaptis; bet kalbu apie Kristų ir bažnyčią.'),
  (@b49, 5, 33, 'Tačiau tegul kiekvienas atskirai iš jūsų myli savo žmoną taip, kaip save patį; o žmona tegerbia savo vyrą.'),
  (@b49, 6, 1, 'Vaikai, pakluskite savo gimdytojams Viešpatyje, nes tai yra teisinga.'),
  (@b49, 6, 2, 'Gerbk savo tėvą ir motiną (tai yra pirmasis įsakymas su pažadu),'),
  (@b49, 6, 3, 'kad tau būtų gerai ir ilgai gyventum žemėje.'),
  (@b49, 6, 4, 'Ir jūs, tėvai, nerūstinkite savo vaikų; bet auginkite juos Viešpaties ugdyme ir įspėjime.'),
  (@b49, 6, 5, 'Tarnai, pakluskite savo šeimininkams pagal kūną su baime ir drebėjimu, vienalype širdimi, kaip Kristui;'),
  (@b49, 6, 6, 'ne dėl akių, kaip įtikdami žmonėms; bet kaip Kristaus tarnai, iš širdies vykdydami Dievo valią;'),
  (@b49, 6, 7, 'gera valia atlikdami tarnavimą kaip Viešpačiui, o ne žmonėms;'),
  (@b49, 6, 8, 'žinodami, kad ką gera kas bedarytų, tą patį gaus iš Viešpaties, ar jis būtų vergas, ar laisvasis.'),
  (@b49, 6, 9, 'Ir jūs, šeimininkai, darykite jiems tą patį, susilaikydami nuo grasinimo, žinodami, kad ir jūsų Šeimininkas yra danguje; ir jis neatsižvelgia į asmenis.'),
  (@b49, 6, 10, 'Galiausiai, mano broliai, būkite stiprūs Viešpatyje ir jo galybės jėgoje.'),
  (@b49, 6, 11, 'Užsidėkite visą Dievo ginkluotę, kad būtumėte pajėgūs stovėti prieš velnio klastas.'),
  (@b49, 6, 12, 'Nes mes grumiamės ne su kūnu ir krauju, bet su kunigaikštystėmis, su valdžiomis, su šio pasaulio tamsybės valdovais, su dvasine nedorybe aukštybės vietose.'),
  (@b49, 6, 13, 'Todėl pasiimkite visą Dievo ginkluotę, kad pajėgtumėte piktąją dieną atsilaikyti ir, viską atlikę, stovėti.'),
  (@b49, 6, 14, 'Todėl stovėkite susijuosę savo strėnas tiesa ir užsidėję teisumo krūtinšarvį;'),
  (@b49, 6, 15, 'ir apsiavę kojas taikos evangelijos parengimu;'),
  (@b49, 6, 16, 'virš visko pasiėmę tikėjimo skydą, kuriuo būsite pajėgūs užgesinti visas ugningas nedorojo strėles.'),
  (@b49, 6, 17, 'Ir imkite išgelbėjimo šalmą ir Dvasios kalaviją, kuris yra Dievo žodis,'),
  (@b49, 6, 18, 'visada melsdamiesi Dvasioje visokeriopa malda bei prašymu ir tam budėdami visa ištverme bei prašymu už visus šventuosius;'),
  (@b49, 6, 19, 'ir už mane, kad man būtų duotas ištarimas, kad drąsiai atverčiau savo burną, duodamas žinoti paslaptį evangelijos,'),
  (@b49, 6, 20, 'dėl kurios esu pasiuntinys pančiuose; kad juose kalbėčiau drąsiai, kaip turiu kalbėti.'),
  (@b49, 6, 21, 'Bet, kad ir jūs žinotumėte mano reikalus ir kaip man sekasi, jums viską duos žinoti Tichikas, mylimas brolis ir ištikimas tarnautojas Viešpatyje;'),
  (@b49, 6, 22, 'kurį jums pasiunčiau dėl to paties, kad žinotumėte mūsų reikalus ir kad jis paguostų jūsų širdis.'),
  (@b49, 6, 23, 'Ramybė tebūna broliams ir meilė su tikėjimu nuo Dievo Tėvo ir Viešpaties Jėzaus Kristaus.'),
  (@b49, 6, 24, 'Malonė tebūna su visais, kurie nuoširdžiai myli mūsų Viešpatį Jėzų Kristų. Amen.'),
  (@b50, 1, 1, 'Paulius ir Timotiejus, Jėzaus Kristaus tarnai, visiems šventiesiems Kristuje Jėzuje, esantiems Filipuose, su vyskupais ir diakonais:'),
  (@b50, 1, 2, 'malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir nuo Viešpaties Jėzaus Kristaus.'),
  (@b50, 1, 3, 'Dėkoju savo Dievui kiekviename prisiminimeapie jus,'),
  (@b50, 1, 4, 'visada, kiekvienoje savo maldoje prašydamas už jus visus su džiaugsmu,'),
  (@b50, 1, 5, 'už jūsų bendrystę evangelijoje nuo pirmos dienos iki dabar;'),
  (@b50, 1, 6, 'būdamas tikras tuo, kad tas, kuris pradėjo gerą darbą jumyse, įvykdys jį iki Jėzaus Kristaus dienos;'),
  (@b50, 1, 7, 'kaip man ir tinka tai galvoti apie jus visus, nes turiu jus savo širdyje; kadangi tiek mano pančiuose, tiek evangelijos apgynime ir patvirtinime jūs visi esate mano malonės dalininkai.'),
  (@b50, 1, 8, 'Nes Dievas yra mano liudytojas, kaip labai jūsų visų ilgiuosi Jėzaus Kristaus viduriuose.'),
  (@b50, 1, 9, 'Ir meldžiu to, kad jūsų meilė vis labiau ir labiau gausėtų pažinimu bei visokiu nuovokumu;'),
  (@b50, 1, 10, 'kad išmėgintumėte tai, kas geriausia; kad būtumėte nuoširdūs ir be papiktinimo iki Kristaus dienos;'),
  (@b50, 1, 11, 'būdami pripildyti teisumo vaisių, kurie yra per Jėzų Kristų, Dievo šlovei ir gyriui.'),
  (@b50, 1, 12, 'Bet noriu, kad suprastumėte, broliai, kad tai, kas man atsitiko, verčiau nutiko evangelijos plitimui;'),
  (@b50, 1, 13, 'taip, kad mano pančiai Kristuje tapo žinomi visuose rūmuose ir visur kitur;'),
  (@b50, 1, 14, 'ir daugelis iš brolių Viešpatyje, įgavę pasitikėjimo per mano pančius, yra daug drąsesni kalbėti žodį be baimės.'),
  (@b50, 1, 15, 'Tiesa, kai kurie skelbia Kristų iš pavydo ir rungtyniaudami; o kai kurie ir iš geros valios:'),
  (@b50, 1, 16, 'vieni skelbia Kristų varžydamiesi, nenuoširdžiai, manydami pridėti sielvarto prie mano pančių;'),
  (@b50, 1, 17, 'bet kiti iš meilės, žinodami, kad esu paskirtas evangelijos gynimui.'),
  (@b50, 1, 18, 'Tai ką? Nepaisant to, visokiais būdais, ar tai apsimetant, ar iš tikrųjų yra skelbiamas Kristus; šituo džiaugiuosi, taip, ir džiaugsiuosi.'),
  (@b50, 1, 19, 'Nes žinau, kad tai pakryps mano išgelbėjimui per jūsų maldą ir Jėzaus Kristaus Dvasios aprūpinimą,'),
  (@b50, 1, 20, 'pagal mano uolų laukimą ir mano viltį, kad niekuo nebūsiu sugėdintas, bet kad visa drąsa, kaip visuomet, taip ir dabar, Kristus bus išaukštintas mano kūne, ar tai būtų gyvenimu, ar mirtimi.'),
  (@b50, 1, 21, 'Nes man gyventi – tai Kristus, o mirti – tai laimėjimas.'),
  (@b50, 1, 22, 'Bet jei gyvenu kūne, tai yra mano triūso vaisius; tačiau ką pasirinksiu, nežinau.'),
  (@b50, 1, 23, 'Nes esu suvaržytas tarp dviejų, turėdamas troškimą išeiti ir būti su Kristumi, kas yra daug geriau,'),
  (@b50, 1, 24, 'tačiau pasilikti kūne daug reikalingiau dėl jūsų.'),
  (@b50, 1, 25, 'Ir turėdamas šį įsitikinimą žinau, kad pasiliksiu ir tęsiu su jumis visais dėl jūsų pažangos ir tikėjimo džiaugsmo;'),
  (@b50, 1, 26, 'kad jūsų džiaugimasis dėl manęs būtų gausesnis Jėzuje Kristuje man vėl pas jus ateinant.'),
  (@b50, 1, 27, 'Tik jūsų gyvensena tebūna tinkama Kristaus evangelijai: kad, ar tai atvykčiau ir jus pamatyčiau, arba nebūdamas pas jus išgirsčiau apie jūsų reikalus, kad tvirtai stovite vienoje dvasioje, viena mintimi kartu kovodami už evangelijos tikėjimą;'),
  (@b50, 1, 28, 'ir niekuo savo priešininkų neišgąsdinti: jiems tai yra akivaizdus pražūties ženklas, bet jums išgelbėjimo, o tai iš Dievo.'),
  (@b50, 1, 29, 'Nes jums duota dėl Kristaus ne tik į jį tikėti, bet ir dėl jo kentėti;'),
  (@b50, 1, 30, 'turint tą pačią kovą, kurią matėte manyje ir dabar girdite esančią manyje.'),
  (@b50, 2, 1, 'Taigi jei yra koks nuraminimas Kristuje, jei kokia meilės paguoda, jei kokia Dvasios bendrystė, jei kokie viduriai ir gailestingumai,'),
  (@b50, 2, 2, 'tai išpildykite mano džiaugsmą, kad būtumėte vienminčiai, turėdami tą pačią meilę, būdami vieningi, vieningo nusiteikimo.'),
  (@b50, 2, 3, 'Niekas tenebūna daroma per varžymąsi ar tuščią garbę; bet su nusižeminimu kiekvienas telaiko kitą geresniu už save.'),
  (@b50, 2, 4, 'Nei vienas tenežiūri dėl savęs, bet kiekvienas taipogi dėl kitų.'),
  (@b50, 2, 5, 'Tebūna šis nusiteikimas jumyse, kuris buvo ir Kristuje Jėzuje,'),
  (@b50, 2, 6, 'kuris, būdamas Dievo pavidalu, nelaikė apiplėšimu būti lygiu Dievui,'),
  (@b50, 2, 7, 'bet save numenkino ir prisiėmė tarno pavidalą, ir tapo panašus į žmones;'),
  (@b50, 2, 8, 'ir pavidalu rastas kaip žmogus, jis nusižemino ir tapo paklusnus iki mirties – iki kryžiaus mirties.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b50, 2, 9, 'Todėl Dievas jį labai ir išaukštino ir davė jam vardą, kuris yra aukščiau kiekvieno vardo;'),
  (@b50, 2, 10, 'kad Jėzaus vardui lenktųsi kiekvienas kelis iš to, kas danguje, ir to, kas žemėje, ir to, kas po žeme;'),
  (@b50, 2, 11, 'ir kad kiekvienas liežuvis išpažintų, kad Jėzus Kristus yra Viešpats, Dievo Tėvo šlovei.'),
  (@b50, 2, 12, 'Todėl, mano mylimieji, kaip visada paklusote, ne tik kai esu pas jus, bet dar daugiau dabar man nesant pas jus, išdirbkite savo pačių išgelbėjimą su baime ir drebėjimu.'),
  (@b50, 2, 13, 'Nes tai Dievas, kuris veikia jumyse ir norėti, ir daryti iš jo gero noro.'),
  (@b50, 2, 14, 'Viską darykite be murmėjimų ir ginčų,'),
  (@b50, 2, 15, 'kad būtumėte nepeiktini ir nekenkiantys Dievo sūnūs, nepriekaištingi tarpe nedoros ir iškrypusios tautos, tarp kurios jūs spindite kaip šviesos pasaulyje;'),
  (@b50, 2, 16, 'laikydamiesi gyvenimo žodžio; kad galėčiau džiaugtis Kristaus dieną, jog nebėgau veltui nei veltui netriūsiau.'),
  (@b50, 2, 17, 'Taip, ir jei esu atnašaujamas ant jūsų tikėjimo aukos ir tarnystės, aš džiaugiuosi ir džiūgauju su jumis visais.'),
  (@b50, 2, 18, 'Dėl to paties ir jūs džiaukitės bei džiūgaukite su manimi.'),
  (@b50, 2, 19, 'Bet pasitikiu Viešpačiu Jėzumi netrukus pasiųsti pas jus Timotiejų, kad ir aš būčiau gerai paguostas, sužinojęs jūsų būklę.'),
  (@b50, 2, 20, 'Nes neturiu nei vieno taip nusiteikusio, kuris neapsimestinai rūpintųsi jūsų būkle.'),
  (@b50, 2, 21, 'Nes visi ieško savo, ne to, kas Jėzaus Kristaus.'),
  (@b50, 2, 22, 'Bet jūs žinote jo išmėginimą, kad, kaip sūnus su tėvu, jis tarnavo su manimi evangelijoje.'),
  (@b50, 2, 23, 'Todėl tikuosi greitai jį pasiųsti, kai tik pamatysiu, kas bus su manimi.'),
  (@b50, 2, 24, 'Bet pasitikiu Viešpačiu, kad ir aš pats netrukus ateisiu.'),
  (@b50, 2, 25, 'Dar pamaniau, yra būtina jums pasiųsti Epafroditą, mano brolį ir bendradarbį, ir bendrakareivį, bet jūsų pasiuntinį ir patarnautoją mano reikmėms.'),
  (@b50, 2, 26, 'Nes jis jūsų visų ilgėjosi ir buvo pilnas sunkumo, nes girdėjote, kad jis buvo susirgęs.'),
  (@b50, 2, 27, 'Nes iš tikrųjų jis sirgo būdamas arti mirties; bet Dievas jo pasigailėjo; ir ne tik jo, bet ir manęs, kad neturėčiau sielvarto po sielvarto.'),
  (@b50, 2, 28, 'Todėl dar rūpestingiau jį pasiunčiau, kad vėl jį pamatę džiaugtumėtės ir kad būčiau mažiau nuliūdęs.'),
  (@b50, 2, 29, 'Todėl priimkite jį Viešpatyje su visu džiaugsmu; ir laikykite tokius garbėje;'),
  (@b50, 2, 30, 'nes dėl Kristaus darbo jis buvo arti mirties, nepaisydamas savo gyvybės, kad užpildytų jūsų tarnavimo man trūkumą.'),
  (@b50, 3, 1, 'Galiausiai, mano broliai, džiaukitės Viešpatyje. Rašyti jums tuos pačius dalykus man, iš tikrųjų, nėra sunku, bet jums tai saugu.'),
  (@b50, 3, 2, 'Saugokitės šunų, saugokitės piktų darbininkų, saugokitės susipjaustymo.'),
  (@b50, 3, 3, 'Nes mes esame apipjaustymas, kurie šloviname Dievą dvasioje ir džiaugiamės Kristuje Jėzuje, ir neturime pasitikėjimo kūnu.'),
  (@b50, 3, 4, 'Nors aš ir galėčiau pasitikėti kūnu. Jei kas kitas mano turintis, dėl ko galėtų pasitikėti kūnu, aš daugiau:'),
  (@b50, 3, 5, 'apipjaustytas aštuntą dieną, iš Izraelio giminės, iš Benjamino genties, hebrajas iš hebrajų; pagal įstatymą – fariziejus;'),
  (@b50, 3, 6, 'pagal uolumą – persekiojantis bažnyčią; pagal teisumą, kuris yra įstatyme, – nepeiktinas.'),
  (@b50, 3, 7, 'Bet tai, kas man buvo pelnas, tai palaikiau nuostoliu dėl Kristaus.'),
  (@b50, 3, 8, 'Taip, ir neabejotinai viską laikau nuostoliu dėl Kristaus Jėzaus pažinimo pranašumo, mano Viešpaties, dėl kurio viską praradau ir laikau tai mėšlu, kad laimėčiau Kristų'),
  (@b50, 3, 9, 'ir būčiau rastas jame, neturėdamas savo teisumo, kuris yra iš įstatymo, bet tą, kuris yra per Kristaus tikėjimą – teisumą, kuris yra iš Dievo, tikėjimu;'),
  (@b50, 3, 10, 'kad pažinčiau jį ir jo prisikėlimo jėgą, ir jo kentėjimų bendrystę, atitikdamas jo mirtį;'),
  (@b50, 3, 11, 'jei kokiu tai būdu pasiekčiau mirusiųjų prisikėlimą.'),
  (@b50, 3, 12, 'Ne tarsi jau pasiekiau, ar jau esu tobulas; bet seku iš paskos, kad suimčiau tai, dėl ko ir esu Kristaus Jėzaus suimtas.'),
  (@b50, 3, 13, 'Broliai, aš nelaikau savęs suėmusiu; bet viena darau: pamiršdamas tai, kas už nugaros, ir siekdamas to, kas priekyje,'),
  (@b50, 3, 14, 'veržiuosi link žymės dėl prizo – aukšto Dievo pašaukimo Kristuje Jėzuje.'),
  (@b50, 3, 15, 'Todėl kiek mūsų yra tobulų, būkime taip nusiteikę; o jei dėl ko nors esate nusiteikę kitaip, Dievas jums ir tai apreikš.'),
  (@b50, 3, 16, 'Tačiau iki kur jau pasiekėme, vaikščiokime ta pačia taisykle, nusiteikime tam pačiam dalykui.'),
  (@b50, 3, 17, 'Broliai, būkite kartu mano sekėjai ir paženklinkite tuos, kurie vaikšto taip, kaip turite mus pavyzdžiu'),
  (@b50, 3, 18, '(nes daugelis vaikšto, apie kuriuos jums dažnai sakydavau ir dabar sakau netgi verkdamas, kad jie yra Kristaus kryžiaus priešai,'),
  (@b50, 3, 19, 'kurių galas – žlugimas, kurių Dievas – jų pilvas ir kurių šlovė yra jų gėdoje, kurie nusiteikę tam, kas žemiška).'),
  (@b50, 3, 20, 'Nes mūsų gyvensena yra danguje; iš kur ir laukiame Gelbėtojo, Viešpaties Jėzaus Kristaus;'),
  (@b50, 3, 21, 'kuris pakeis mūsų niekingą kūną, kad jis būtų padarytas tokiu, kaip jo šlovingas kūnas, pagal tą veikimą, kuriuo jis visa pajėgus ir pajungti sau.'),
  (@b50, 4, 1, 'Todėl, mano broliai, brangiai mylimi ir išsiilgtieji, mano džiaugsme ir vainike, taip tvirtai stovėkite Viešpatyje, mano brangiai mylimi.'),
  (@b50, 4, 2, 'Maldauju Evodiją ir maldauju Sintichę, kad jos būtų vienos minties Viešpatyje.'),
  (@b50, 4, 3, 'Maldauju ir tavęs, tikrasis jungo drauge, padėk toms moterims, kurios triūsė su manimi evangelijoje ir su Klemensu, ir su kitais mano bendradarbiais, kurių vardai yra gyvenimo knygoje.'),
  (@b50, 4, 4, 'Nuolat džiaukitės Viešpatyje, ir vėl sakau: džiaukitės.'),
  (@b50, 4, 5, 'Jūsų susivaldymas tebūna žinomas visiems žmonėms. Viešpats yra čia pat.'),
  (@b50, 4, 6, 'Niekuo nebūkite susirūpinę; bet visame kame per maldą ir prašymą su padėka jūsų prašymai tetampa žinomi Dievui.'),
  (@b50, 4, 7, 'Ir Dievo ramybė, pranokstanti visą supratimą, saugos jūsų širdis ir protus per Kristų Jėzų.'),
  (@b50, 4, 8, 'Galiausiai, broliai, kas yra tikra, kas dora, kas teisinga, kas tyra, kas meilu, kas gero atsiliepimo; jei yra dorybė ir jei yra gyrius, galvokite apie tai.'),
  (@b50, 4, 9, 'Ką išmokote ir gavote, ir girdėjote, ir matėte manyje, darykite tai, ir ramybės Dievas bus su jumis.'),
  (@b50, 4, 10, 'Bet aš didžiai džiaugiausi Viešpatyje, kad dabar pagaliau vėl pražydo jūsų rūpinimasis manimi; tuo ir rūpinotės, bet jums stigo progos.'),
  (@b50, 4, 11, 'Ne tai, kad kalbu atsižvelgiant į stoką, nes aš išmokau, kokioje būklėje bebūčiau, tuo būti patenkintas.'),
  (@b50, 4, 12, 'Žinau ir kaip būti pažemintam ir žinau, kaip gausiai turėti: visur ir visame kame esu išmokytas ir būti sotus, ir būti alkanas, ir turėti gausiai, ir kentėti stoką.'),
  (@b50, 4, 13, 'Galiu padaryti viską per Kristų, kuris mane stiprina.'),
  (@b50, 4, 14, 'Vis dėlto gerai padarėte, kad buvote mano vargo bendrininkai.'),
  (@b50, 4, 15, 'Jūs gi, filipiečiai, irgi žinote, kad evangelijos pradžioje, kai išvykau iš Makedonijos, jokia bažnyčia nebendravo su manimi davimo ir gavimo atžvilgiu, tik jūs vieni.'),
  (@b50, 4, 16, 'Nes ir į Tesaloniką atsiuntėte vieną ir kitą kartą mano būtinybei.'),
  (@b50, 4, 17, 'Ne todėl, kad trokštu dovanos, bet trokštu vaisiaus, kuris gausėtų į jūsų sąskaitą.'),
  (@b50, 4, 18, 'Bet aš turiu visko ir turiu gausiai: esu prisotintas, gavęs iš Epafrodito tai, kas buvo iš jūsų atsiųsta – gardaus kvapo aromatą, priimtiną auką, labai patinkančią Dievui.'),
  (@b50, 4, 19, 'Bet mano Dievas aprūpins visą jūsų reikmę pagal savo turtus šlovėje per Kristų Jėzų.'),
  (@b50, 4, 20, 'Dievui gi ir mūsų Tėvui tebūna šlovė per amžių amžius. Amen.'),
  (@b50, 4, 21, 'Sveikinkite kiekvieną šventąjį Kristuje Jėzuje. Jus sveikina broliai, esantys su manimi.'),
  (@b50, 4, 22, 'Jus sveikina visi šventieji, ypač esantys iš ciesoriaus namiškių.'),
  (@b50, 4, 23, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis visais. Amen.'),
  (@b51, 1, 1, 'Paulius, Dievo valia Jėzaus Kristaus apaštalas, ir mūsų brolis Timotiejus,'),
  (@b51, 1, 2, 'šventiesiems ir ištikimiems broliams Kristuje, esantiems Kolosuose: malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir Viešpaties Jėzaus Kristaus.'),
  (@b51, 1, 3, 'Dėkojame Dievui ir mūsų Viešpaties Jėzaus Kristaus Tėvui visada melsdamiesi už jus'),
  (@b51, 1, 4, 'nuo tada, kai išgirdome apie jūsų tikėjimą Kristumi Jėzumi ir apie jūsų meilę visiems šventiesiems,'),
  (@b51, 1, 5, 'už viltį, kuri jums atidėta danguje, apie kurią anksčiau girdėjote tiesos žodyje evangelijos;'),
  (@b51, 1, 6, 'kuri atėjo pas jus, kaip ir visame pasaulyje; ir neša vaisių, kaip ir jumyse, nuo tos dienos, kai apie ją išgirdote ir pažinote Dievo malonę tiesoje;'),
  (@b51, 1, 7, 'kaip ir išmokote iš mūsų brangaus bendratarnio Epafro, kuris dėl jūsų yra ištikimas Kristaus tarnautojas;'),
  (@b51, 1, 8, 'kuris ir pranešė mums apie jūsų meilę Dvasioje.'),
  (@b51, 1, 9, 'Dėl to ir mes, nuo tos dienos, kai tai išgirdome, nesiliaujame melstis už jus ir prašyti, kad būtumėte pripildyti jo valios pažinimo visa išmintimi ir dvasiniu supratimu;'),
  (@b51, 1, 10, 'kad vaikščiotumėte verti Viešpaties, viskuo patikdami, būdami vaisingi kiekvienu geru darbu ir augdami Dievo pažinimu;'),
  (@b51, 1, 11, 'sustiprinti visa galybe pagal jo šlovingą jėgą visokiai kantrybei ir ilgam pakantumui su džiaugsmu;'),
  (@b51, 1, 12, 'dėkodami Tėvui, padariusiam mus tinkamais būti šventųjų paveldo dalininkais šviesoje;'),
  (@b51, 1, 13, 'kuris išvadavo mus iš tamsybės valdžios ir perkėlė į karalystę savo mielojo Sūnaus,'),
  (@b51, 1, 14, 'kuriame turime atpirkimą per jo kraują, tai yra, nuodėmių atleidimą,'),
  (@b51, 1, 15, 'kuris yra neregimojo Dievo atvaizdas, kiekvieno sutvėrimo pirmagimis;'),
  (@b51, 1, 16, 'nes per jį sutverta visa, kas danguje ir kas žemėje, regima ir neregima, ar tai būtų sostai, ar viešpatystės, ar kunigaikštystės, ar valdžios: visa yra per jį ir dėl jo sutverta;'),
  (@b51, 1, 17, 'ir jis yra pirma visko, ir visa per jį laikosi.'),
  (@b51, 1, 18, 'Ir jis yra galva kūno, bažnyčios; jis yra pradžia, pirmagimis iš numirusiųjų, kad visame kame jis turėtų pirmenybę.'),
  (@b51, 1, 19, 'Nes Tėvui patiko, kad jame gyventų visa pilnuma;'),
  (@b51, 1, 20, 'ir, padarius taiką per jo kryžiaus kraują, per jį sutaikinti sau visa; per jį, sakau, ar tai būtų tai, kas žemėje, ar tai, kas danguje.'),
  (@b51, 1, 21, 'Ir jus, kurie kadaise buvote atitolę ir priešai savo protu nedorais darbais, tačiau dabar jis sutaikino'),
  (@b51, 1, 22, 'jo fiziniame kūne per mirtį, kad savo akivaizdoje pristatytų jus šventus ir nekaltintinus, ir nebartinus;'),
  (@b51, 1, 23, 'jei pasiliekate tikėjime įsitvirtinę ir tvirti, ir neatitraukiami nuo vilties tos evangelijos, kurią girdėjote, ir kuri buvo paskelbta kiekvienam sutvėrimui po dangumi; kurios tarnautoju aš, Paulius, tapau;'),
  (@b51, 1, 24, 'kuris dabar džiaugiuosi savo kentėjimuose dėl jūsų ir savo kūne papildau tai, ko dar trūksta Kristaus vargams dėl jo kūno, kuris yra bažnyčia,'),
  (@b51, 1, 25, 'kurios tarnautoju tapau pagal Dievo ūkvedybą, kuri man duota dėl jūsų, kad išpildyčiau Dievo žodį,'),
  (@b51, 1, 26, 'tai yra, tą paslaptį, kuri buvo paslėpta nuo amžių ir kartų, bet dabar yra atskleista jo šventiesiems;'),
  (@b51, 1, 27, 'kuriems Dievas nori duoti žinoti, kokie yra šios paslapties šlovės turtai tarp pagonių, kuri yra Kristus jumyse – šlovės viltis;'),
  (@b51, 1, 28, 'kurį mes skelbiame, perspėdami kiekvieną žmogų ir mokydami kiekvieną žmogų visa išmintimi; kad pristatytume kiekvieną žmogų tobulą Kristuje Jėzuje;'),
  (@b51, 1, 29, 'tam ir triūsiu, kovodamas pagal jo veikimą, kuris galingai veikia manyje.'),
  (@b51, 2, 1, 'Nes noriu, kad žinotumėte, kokią didelę kovą turiu dėl jūsų ir dėl tų Laodikėjoje, ir dėl visų, kurie nėra matę mano veido kūne;'),
  (@b51, 2, 2, 'kad jų širdys būtų paguostos, sujungtos meilėje ir visiems pilno supratimo užtikrintumo turtams, pripažinimui paslapties Dievo ir Tėvo, ir Kristaus;'),
  (@b51, 2, 3, 'kuriame yra paslėpti visi išminties bei pažinimo lobiai.'),
  (@b51, 2, 4, 'Ir tai sakau, kad kas jūsų neapgautų viliojančiais žodžiais.'),
  (@b51, 2, 5, 'Nes, nors nesu su jumis kūnu, tačiau esu su jumis dvasia, džiaugdamasis ir matydamas jūsų tvarką ir jūsų tikėjimo Kristumi tvirtumą.'),
  (@b51, 2, 6, 'Todėl, kaip priėmėte Kristų Jėzų – Viešpatį, taip ir vaikščiokite jame:'),
  (@b51, 2, 7, 'įšaknyti ir pastatyti jame, ir sutvirtinti tikėjime, kaip buvote išmokyti, tame pertekę dėkojimo.'),
  (@b51, 2, 8, 'Saugokitės, kad kas jūsų nepasigrobtų per filosofiją ir tuščią apgaulę, pagal žmonių tradicijas, pagal pasaulio pradmenis, o ne pagal Kristų.'),
  (@b51, 2, 9, 'Nes jame kūniškai gyvena visa Dievystės pilnatvė.'),
  (@b51, 2, 10, 'O jūs esate pripildyti jame, kuris yra kiekvienos kunigaikštystės ir valdžios galva;'),
  (@b51, 2, 11, 'kuriame esate ir apipjaustyti ne rankomis atliktu apipjaustymu, atmetant kūniškų nuodėmių kūną Kristaus apipjaustymu;'),
  (@b51, 2, 12, 'palaidoti su juo krikšte, kuriame esate ir prikelti su juo per Dievo, prikėlusio jį iš numirusių, veikimo tikėjimą.'),
  (@b51, 2, 13, 'Ir jus, mirusius savo nuodėmėse ir jūsų kūno neapipjaustyme, jis atgaivino kartu su juo, atleidęs jums visus nusikaltimus;'),
  (@b51, 2, 14, 'ištrynęs įsakų rankraštį, kuris buvo prieš mus, kuris buvo mums priešingas, ir pašalino jį, prikalęs jį prie jo kryžiaus;'),
  (@b51, 2, 15, 'ir, apiplėšęs kunigaikštystes bei valdžias, jis padarė iš jų viešą reginį, triumfuodamas prieš jas kryžiuje.'),
  (@b51, 2, 16, 'Todėl niekas teneteisia jūsų dėl maisto ar dėl gėrimo, ar švenčių, ar jauno mėnulio, ar sabato dienų atžvilgiu,'),
  (@b51, 2, 17, 'kurie yra ateinančių dalykų šešėlis; bet kūnas yra Kristaus.'),
  (@b51, 2, 18, 'Niekas jūsų tenenuvilioja nuo jūsų atlygio tyčiniu nusižeminimu ir angelų garbinimu, įsibraudamas į tai, ko nėra matęs, tuščiai pasipūtęs savo kūnišku protu'),
  (@b51, 2, 19, 'ir nesilaikydamas Galvos, iš kurios visas kūnas per sąnarius ir raiščius aprūpintas maitinimu ir sujungtas auga Dievo auginimu.'),
  (@b51, 2, 20, 'Todėl jei esate mirę su Kristumi pasaulio pradmenims, kodėl, tarsi gyvendami pasaulyje, esate pavaldūs įsakams'),
  (@b51, 2, 21, '(neliesk, neragauk, neimk;'),
  (@b51, 2, 22, 'kurie visi dingsta vartojant) pagal žmonių įsakymus ir mokslus?'),
  (@b51, 2, 23, 'Šitie dalykai iš tikrųjų turi išminties išvaizdą noro garbinime ir nusižeminime, ir kūno varginime; neturintys jokios garbės kūno patenkinime.'),
  (@b51, 3, 1, 'Tad jei esate prisikėlę su Kristumi, siekite to, kas aukštai, kur Kristus sėdi Dievo dešinėje.'),
  (@b51, 3, 2, 'Prisiriškite prie to, kas aukštai, o ne prie to, kas žemėje.'),
  (@b51, 3, 3, 'Nes jūs esate mirę, ir jūsų gyvenimas yra paslėptas su Kristumi Dieve.'),
  (@b51, 3, 4, 'Kai pasirodys Kristus, kuris yra mūsų gyvenimas, tuomet ir jūs pasirodysite su juo šlovėje.'),
  (@b51, 3, 5, 'Todėl marinkite savo narius, kurie yra žemėje: paleistuvystę, nešvarumą, aistringumą, piktą geidulį ir godumą, kuris yra stabmeldystė;'),
  (@b51, 3, 6, 'dėl šių dalykų Dievo rūstybė ateina ant neklusnumo vaikų,'),
  (@b51, 3, 7, 'kuriuose ir jūs kadaise vaikščiojote, kai gyvenote juose.'),
  (@b51, 3, 8, 'Bet dabar ir jūs nusivilkite visus šituos – pyktį, rūstybę, piktybę, piktžodžiavimą, nešvankią kalbą iš savo burnos.'),
  (@b51, 3, 9, 'Nemeluokite vienas kitam, kadangi nusivilkote senąjį žmogų su jo darbais;'),
  (@b51, 3, 10, 'ir apsivilkote nauju žmogumi, kuris yra atnaujinamas pažinimu pagal atvaizdą to, kuris jį sutvėrė;'),
  (@b51, 3, 11, 'kur nėra nei graiko, nei žydo, nei apipjaustymo nei neapipjaustymo, barbaro, skito, vergo nei laisvo; bet Kristus yra visa ir visuose.'),
  (@b51, 3, 12, 'Todėl, kaip Dievo išrinktieji, šventi ir mylimi, apsivilkite gailestingumų viduriais, gerumu, nuolankumu, romumu, ilgu pakantumu;'),
  (@b51, 3, 13, 'pakęsdami vienas kitą ir atleisdami vienas kitam, jei kas prieš kitą turi ginčą: kaip Kristus jums atleido, taip ir jūs atleiskite.'),
  (@b51, 3, 14, 'O viršum visų šitų apsivilkite meile, kuri yra tobulumo raištis.'),
  (@b51, 3, 15, 'Ir tevaldo jūsų širdyse Dievo ramybė, į kurią ir esate pašaukti viename kūne; ir būkite dėkingi.'),
  (@b51, 3, 16, 'Tegul Kristaus žodis turtingai gyvena jumyse visa išmintimi; mokant ir įspėjant vienas kitą psalmėmis, himnais ir dvasinėmis giesmėmis, giedant Viešpačiui su malone savo širdyse.'),
  (@b51, 3, 17, 'Ir ką bedarote žodžiu ar darbu, viską darykite Viešpaties Jėzaus vardu, per jį dėkodami Dievui ir Tėvui.'),
  (@b51, 3, 18, 'Žmonos, pakluskite savo vyrams, kaip tai dera Viešpatyje.'),
  (@b51, 3, 19, 'Vyrai, mylėkite savo žmonas ir nebūkite prieš jas pikti.'),
  (@b51, 3, 20, 'Vaikai, pakluskite savo gimdytojams visame kame; nes tai labai patinka Viešpačiui.'),
  (@b51, 3, 21, 'Tėvai, nepykdykite savo vaikų, kad jie neprarastų drąsos.'),
  (@b51, 3, 22, 'Tarnai, visame kame pakluskite savo šeimininkams pagal kūną; ne dėl akių, kaip norintys įtikti žmonėms; bet vienalype širdimi, bijodami Dievo;'),
  (@b51, 3, 23, 'ir ką darote, darykite širdingai, kaip Viešpačiui, o ne žmonėms;'),
  (@b51, 3, 24, 'žinodami, kad iš Viešpaties gausite paveldo atlygį; nes jūs tarnaujate Viešpačiui Kristui.'),
  (@b51, 3, 25, 'Bet kas daro neteisybę, gaus už savo padarytą neteisybę; ir nebus atsižvelgimo į asmenis.'),
  (@b51, 4, 1, 'Šeimininkai, duokite savo tarnams tai, kas yra teisinga ir lygybiška; žinodami, kad ir jūs turite Šeimininką danguje.'),
  (@b51, 4, 2, 'Pasilikite maldoje ir budėkite joje su padėka;'),
  (@b51, 4, 3, 'tuo pačiu melsdamiesi ir už mus, kad Dievas atvertų mums ištarmės duris kalbėti Kristaus paslaptį, dėl kurios esu ir pančiuose,'),
  (@b51, 4, 4, 'kad ją atskleisčiau taip, kaip turiu kalbėti.'),
  (@b51, 4, 5, 'Vaikščiokite išmintingai priešais tuos, kurie yra išorėje, atpirkdami laiką.'),
  (@b51, 4, 6, 'Jūsų kalba tebūna nuolat su malone, paskaninta druska, kad žinotumėte, kaip turite kiekvienam atsakyti.'),
  (@b51, 4, 7, 'Apie visą mano būklę jums praneš Tichikas, kuris yra mylimas brolis ir ištikimas tarnautojas bei bendratarnis Viešpatyje,'),
  (@b51, 4, 8, 'kurį jums pasiunčiau dėl to paties, kad sužinotų jūsų būklę ir paguostų jūsų širdis;'),
  (@b51, 4, 9, 'su Onesimu, ištikimu ir mylimu broliu, kuris yra vienas iš jūsų. Jie duos jums žinoti visa tai, kas čia vyksta.'),
  (@b51, 4, 10, 'Jus sveikina Aristarchas, mano bendrakalinys, ir Morkus, sesers sūnus Barnabui (dėl jo gavote įsakymus; jeigu jis ateis pas jus, priimkite jį),'),
  (@b51, 4, 11, 'ir Jėzus, vadinamas Justu, kurie yra iš apipjaustymo. Šitie vieninteliai yra mano bendradarbiai Dievo karalystei, kurie buvo man paguoda.'),
  (@b51, 4, 12, 'Jus sveikina Epafras, kuris yra vienas iš jūsų, Kristaus tarnas, visada karštai triūsiantis už jus maldose, kad stovėtumėte tobuli ir pripildyti visoje Dievo valioje.'),
  (@b51, 4, 13, 'Nes aš jam liudiju, kad jis labai uolus dėl jūsų ir esančių Laodikėjoje bei esančių Hierapolyje.'),
  (@b51, 4, 14, 'Jus sveikina Lukas, mylimasis gydytojas, ir Demas.'),
  (@b51, 4, 15, 'Sveikinkite brolius, esančius Laodikėjoje, ir Nimfą bei bažnyčią, esančią jo namuose.'),
  (@b51, 4, 16, 'Ir kai šis laiškas tarp jūsų bus perskaitytas, padarykite, kad jis būtų perskaitytas ir laodikėjiečių bažnyčioje; ir kad jūs taip pat perskaitytumėte laišką iš Laodikėjos.'),
  (@b51, 4, 17, 'Ir pasakykite Archipui: „Žiūrėkis tarnystės, kurią gavai Viešpatyje, kad ją išpildytum“.'),
  (@b51, 4, 18, 'Sveikinimas mano, Pauliaus, ranka. Prisiminkite mano pančius. Malonė tebūna su jumis. Amen.'),
  (@b52, 1, 1, 'Paulius ir Silvanas, ir Timotiejus, tesalonikiečių bažnyčiai, esančiai Dieve Tėve ir Viešpatyje Jėzuje Kristuje: malonė jums ir ramybė nuo Dievo mūsų Tėvo ir Viešpaties Jėzaus Kristaus.'),
  (@b52, 1, 2, 'Mes visada dėkojame Dievui už jus visus, minėdami jus savo maldose;'),
  (@b52, 1, 3, 'be paliovos prisimindami Dievo ir mūsų Tėvo akivaizdoje jūsų tikėjimo darbą ir meilės triūsą, ir vilties kantrumą mūsų Viešpatyje Jėzuje Kristuje;'),
  (@b52, 1, 4, 'žinodami, mylimi broliai, jūsų išrinkimą iš Dievo.'),
  (@b52, 1, 5, 'Nes mūsų evangelija neatėjo pas jus vien žodžiu, bet taip pat ir jėga, ir Šventąja Dvasia, ir didžiu užtikrintumu; kaip jūs žinote, kokie tarp jūsų buvome jūsų labui.'),
  (@b52, 1, 6, 'Ir jūs tapote mūsų sekėjais bei Viešpaties, priėmę žodį daugelyje vargų su Šventosios Dvasios džiaugsmu:'),
  (@b52, 1, 7, 'taip, kad jūs buvote pavyzdžiais visiems, kurie tiki Makedonijoje ir Achajoje.'),
  (@b52, 1, 8, 'Nes iš jūsų Viešpaties žodis nuskambėjo ne tik Makedonijoje ir Achajoje, bet ir kiekvienoje vietoje pasklido jūsų tikėjimas į Dievą; taip, kad mums nereikia nieko kalbėti.'),
  (@b52, 1, 9, 'Nes jie patys praneša apie mus, kokį turėjome įėjimą pas jus ir kaip jūs nuo stabų atsigręžėte į Dievą tarnauti gyvajam ir tikrajam Dievui;'),
  (@b52, 1, 10, 'ir laukti iš dangaus jo Sūnaus, kurį jis prikėlė iš numirusiųjų, būtent Jėzaus, kuris išvadavo mus nuo ateinančios rūstybės.'),
  (@b52, 2, 1, 'Nes jūs patys, broliai, žinote mūsų įėjimą pas jus, kad tai nebuvo veltui;'),
  (@b52, 2, 2, 'bet netgi kentėję prieš tai ir paniekinti, kaip žinote, Filipuose, po to buvome drąsūs savo Dieve kalbėti jums Dievo evangeliją su didele kova.'),
  (@b52, 2, 3, 'Nes mūsų raginimas buvo ne iš apgaulės nei iš nešvarumo, nei su klasta;'),
  (@b52, 2, 4, 'bet, kaip buvome pripažinti Dievo, kad mums patikėtų evangeliją, taip ir kalbame; ne kaip žmonėms patikdami, bet Dievui, kuris mėgina mūsų širdis.'),
  (@b52, 2, 5, 'Nes, kaip žinote, mes niekada nevartojome meilikaujančių žodžių nei godumo priedangos; Dievas yra liudytojas;'),
  (@b52, 2, 6, 'ir neieškojome šlovės nei iš žmonių, nei iš jūsų, nei iš kitų, kai mes, kaip Kristaus apaštalai, galėjome būti apsunkinimu.'),
  (@b52, 2, 7, 'Bet buvome tarp jūsų švelnūs, būtent kaip žindyvė globoja savo vaikus;'),
  (@b52, 2, 8, 'taip prieraišiai trokšdami dėl jūsų, buvome pasiruošę jums perduoti ne tik Dievo evangeliją, bet ir savo pačių sielas, nes buvote mums brangūs.'),
  (@b52, 2, 9, 'Nes prisimenate, broliai, mūsų triūsą ir išsekinantį darbą; nes triūsdami naktį ir dieną, kad neapsunkintume nei vieno iš jūsų, skelbėme jums Dievo evangeliją.'),
  (@b52, 2, 10, 'Jūs esate liudytojai, Dievas irgi, kaip šventai, teisiai ir nepriekaištingai mes elgėmės tarp jūsų, kurie tikite;'),
  (@b52, 2, 11, 'kaip jūs žinote, kaip kiekvieną iš jūsų raginome ir guodėme bei įpareigojome, kaip tėvas savo vaikus,'),
  (@b52, 2, 12, 'kad vaikščiotumėte verti Dievo, kuris pašaukė jus į savo karalystę ir šlovę.'),
  (@b52, 2, 13, 'Dėl to be paliovos ir dėkojame Dievui, kadangi priėmę Dievo žodį, kurį išgirdote iš mūsų, priėmėte jį ne kaip žmonių žodį, bet kaip jis iš tiesų yra – Dievo žodį, kuris galingai ir veikia jumyse, kurie tikite.'),
  (@b52, 2, 14, 'Nes jūs, broliai, tapote sekėjais Dievo bažnyčių, kurios Judėjoje yra Kristuje Jėzuje; nes ir jūs tą patį kentėjote nuo savo tėvynainių, kaip ir jos nuo žydų;'),
  (@b52, 2, 15, 'kurie užmušė tiek Viešpatį Jėzų, tiek savo pačių pranašus bei persekiojo mus; ir jie nepatinka Dievui, ir yra priešiški visiems žmonėms,'),
  (@b52, 2, 16, 'neleisdami mums kalbėti pagonims, kad tie būtų išgelbėti, kad nuolat pripildytų savo nuodėmes; nes ant jų galutinai yra atėjusi rūstybė.'),
  (@b52, 2, 17, 'O mes, broliai, trumpam laikui iš jūsų atimti veidu, bet ne širdimi, dar labiau stengėmės su dideliu troškimu pamatyti jūsų veidą.'),
  (@b52, 2, 18, 'Todėl norėjome ateiti pas jus – aš, Paulius, kartą ir kitą, – bet mums sutrukdė šėtonas.'),
  (@b52, 2, 19, 'Nes kas yra mūsų viltis ar džiaugsmas, ar džiūgavimo vainikas? Argi ir ne jūs mūsų Viešpaties Jėzaus Kristaus akivaizdoje jo atėjime?'),
  (@b52, 2, 20, 'Nes jūs esate mūsų šlovė ir džiaugsmas.'),
  (@b52, 3, 1, 'Todėl, nebegalėdami ilgiau iškęsti, manėme, kad gerai pasilikti vieniems Atėnuose;'),
  (@b52, 3, 2, 'ir pasiuntėme Timotiejų, mūsų brolį ir Dievo tarnautoją, ir mūsų bendradarbį Kristaus evangelijoje, jus sutvirtinti ir paguosti jus dėl jūsų tikėjimo;'),
  (@b52, 3, 3, 'kad nei vienas nesusvyruotų dėl šitų vargų, nes patys žinote, jog esame tam skirti.'),
  (@b52, 3, 4, 'Nes iš tiesų, kai buvome su jumis, anksčiau jums sakėme, kad turime kentėti suspaudimą; kaip ir įvyko, ir jūs žinote.'),
  (@b52, 3, 5, 'Todėl, nebegalėdamas ilgiau iškęsti, pasiunčiau sužinoti apie jūsų tikėjimą, kad kokiu tai būdu jūsų nebūtų sugundęs gundytojas, ir mūsų triūsas nebūtų bergždžias.'),
  (@b52, 3, 6, 'Bet dabar, kai iš jūsų pas mus atėjo Timotiejus ir atnešė mums gerą žinią apie jūsų tikėjimą ir meilę, ir kad visuomet mus gerai prisimenate, didžiai trokšdami pamatyti mus, kaip ir mes pamatyti jus;'),
  (@b52, 3, 7, 'todėl, broliai, buvome jumis paguosti visame mūsų varge ir kančioje per jūsų tikėjimą;'),
  (@b52, 3, 8, 'nes dabar mes gyvename, jei tvirtai stovite Viešpatyje.'),
  (@b52, 3, 9, 'Nes kokią padėką galime Dievui atiduoti už jus, už visą džiaugsmą, kuriuo džiaugiamės dėl jūsų mūsų Dievo akivaizdoje;');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b52, 3, 10, 'naktį ir dieną gausiai melsdamiesi, kad pamatytume jūsų veidą ir ištobulintume tai, ko trūksta jūsų tikėjimui?'),
  (@b52, 3, 11, 'Pats gi Dievas ir mūsų Tėvas, ir mūsų Viešpats Jėzus Kristus tenukreipia mūsų kelią pas jus.'),
  (@b52, 3, 12, 'Ir Viešpats jus teaugina ir tegausina meile vienas kitam bei visiems žmonėms, kaip ir mes jums;'),
  (@b52, 3, 13, 'tam, kad jis sutvirtintų jūsų širdis nepeiktinas šventume prieš Dievą, būtent mūsų Tėvą, mūsų Viešpaties Jėzaus Kristaus atėjime su visais jo šventaisiais.'),
  (@b52, 4, 1, 'Taigi dar jus maldaujame, broliai, ir raginame jus per Viešpatį Jėzų, kad, kaip gavote iš mūsų, kaip turite vaikščioti ir patikti Dievui, taip labiau ir labiau gausėtumėte.'),
  (@b52, 4, 2, 'Nes žinote, kokius įsakymus jums davėme per Viešpatį Jėzų.'),
  (@b52, 4, 3, 'Nes tai yra Dievo valia, būtent jūsų šventėjimas, kad susilaikytumėte nuo paleistuvystės;'),
  (@b52, 4, 4, 'kad kiekvienas iš jūsų žinotų, kaip laikyti savo indą šventėjime ir garbėje;'),
  (@b52, 4, 5, 'ne gašlumo geidulyje, kaip pagonys, kurie nepažįsta Dievo;'),
  (@b52, 4, 6, 'kad nei vienas neperžengtų ribų ir neapgaudinėtų savo brolio jokiame dalyke; nes Viešpats yra visų tokių keršytojas, kaip jus anksčiau ir perspėjome bei liudijome.'),
  (@b52, 4, 7, 'Nes Dievas nepašaukė mūsų nešvarumui, bet šventumui.'),
  (@b52, 4, 8, 'Todėl kas niekina, ne žmogų niekina, bet Dievą, kuris mums ir davė savo šventą Dvasią.'),
  (@b52, 4, 9, 'Bet apie brolišką meilę jums nereikia, kad jums rašyčiau, nes patys esate Dievo išmokyti mylėti vienas kitą.'),
  (@b52, 4, 10, 'Ir iš tiesų jūs tai darote visiems broliams, esantiems visoje Makedonijoje; bet maldaujame jus, broliai, kad labiau ir labiau augtumėte;'),
  (@b52, 4, 11, 'ir kad uoliai stengtumėtės būti tylūs ir užsiimti savo reikalais bei dirbti savo pačių rankomis, kaip jums įsakėme;'),
  (@b52, 4, 12, 'kad vaikščiotumėte dorai prieš esančius išorėje, ir kad jums nieko netrūktų.'),
  (@b52, 4, 13, 'Bet nenoriu, broliai, kad būtumėte nežinantys apie užmigusiuosius, kad neliūdėtumėte, kaip ir kiti, kurie neturi vilties.'),
  (@b52, 4, 14, 'Nes jei tikime, kad Jėzus mirė ir prisikėlė, taip ir tuos, kurie miega Jėzuje, Dievas atves su juo.'),
  (@b52, 4, 15, 'Nes tai jums sakome Viešpaties žodžiu, kad mes, gyvieji ir pasilikusieji iki Viešpaties atėjimo, nepralenksime užmigusiųjų.'),
  (@b52, 4, 16, 'Nes pats Viešpats nusileis iš dangaus su šauksmu, su arkangelo balsu ir su Dievo trimitavimu; ir mirusieji Kristuje prisikels pirmi;'),
  (@b52, 4, 17, 'tuomet mes, gyvieji ir pasilikusieji, kartu su jais būsime pagauti debesyse, sutikti Viešpatį ore; ir taip visada būsime su Viešpačiu.'),
  (@b52, 4, 18, 'Todėl guoskite vienas kitą šiais žodžiais.'),
  (@b52, 5, 1, 'Bet apie laikus ir laikotarpius, broliai, nereikia, kad jums rašyčiau.'),
  (@b52, 5, 2, 'Nes patys puikiai žinote, kad Viešpaties diena ateina taip, kaip vagis naktį.'),
  (@b52, 5, 3, 'Nes kai jie sakys: „Ramybė ir saugumas“, tuomet juos ištiks staigus žlugimas, kaip gimdymo skausmai nėščią moterį; ir jie nepabėgs.'),
  (@b52, 5, 4, 'Bet jūs, broliai, nesate tamsoje, kad toji diena jus užkluptų kaip vagis.'),
  (@b52, 5, 5, 'Jūs visi esate šviesos vaikai ir dienos vaikai – mes nesame nei nakties, nei tamsos.'),
  (@b52, 5, 6, 'Todėl nemiegokime, kaip kiti miega; bet budėkime ir būkime blaivūs.'),
  (@b52, 5, 7, 'Nes tie, kurie miega, naktį miega; ir tie, kurie pasigėrę, naktį pasigėrę.'),
  (@b52, 5, 8, 'Bet mes, esantys dienos, būkime blaivūs, užsidėję tikėjimo ir meilės krūtinšarvį; ir išgelbėjimo viltį kaip šalmą.'),
  (@b52, 5, 9, 'Nes Dievas nepaskyrė mūsų rūstybei, bet įgyti išgelbėjimą per mūsų Viešpatį Jėzų Kristų,'),
  (@b52, 5, 10, 'kuris mirė už mus, kad mes, ar bundame, ar miegame, gyventume kartu su juo.'),
  (@b52, 5, 11, 'Todėl kartu guoskitės ir vienas kitą statydinkite, kaip ir darote.'),
  (@b52, 5, 12, 'Ir jus maldaujame, broliai, pažinoti tuos, kurie triūsia tarp jūsų ir vadovauja jums Viešpatyje, ir jus įspėjinėja;'),
  (@b52, 5, 13, 'ir didžiai juos gerbti meilėje dėl jų darbo. Ir būkite tarpusavyje taikoje.'),
  (@b52, 5, 14, 'Raginame gi jus, broliai, perspėkite nepaklusniuosius, paguoskite silpnadvasius, palaikykite silpnuosius, būkite visiems kantrūs.'),
  (@b52, 5, 15, 'Žiūrėkite, kad nei vienas neatmokėtų nei vienam piktu už piktą; bet visada sekite tuo, kas gera, tiek savo tarpe, tiek visiems.'),
  (@b52, 5, 16, 'Visuomet džiaukitės.'),
  (@b52, 5, 17, 'Be paliovos melskitės.'),
  (@b52, 5, 18, 'Visame kame dėkokite; nes tai yra Dievo valia Kristuje Jėzuje dėl jūsų.'),
  (@b52, 5, 19, 'Negesinkite Dvasios.'),
  (@b52, 5, 20, 'Neniekinkite pranašavimų.'),
  (@b52, 5, 21, 'Visa išmėginkite; tvirtai laikykitės to, kas gera.'),
  (@b52, 5, 22, 'Susilaikykite nuo visko, kas matosi pikta.'),
  (@b52, 5, 23, 'Ir pats ramybės Dievas jus visiškai tepašvenčia; ir meldžiu Dievą, kad jūsų visa dvasia ir siela, ir kūnas būtų išlaikyti nepeiktini mūsų Viešpaties Jėzaus Kristaus atėjimui.'),
  (@b52, 5, 24, 'Ištikimas tas, kuris jus šaukia, kuris tai ir padarys.'),
  (@b52, 5, 25, 'Broliai, melskitės už mus.'),
  (@b52, 5, 26, 'Sveikinkite visus brolius šventu pabučiavimu.'),
  (@b52, 5, 27, 'Įpareigoju jus Viešpačiu, kad šis laiškas būtų perskaitytas visiems šventiesiems broliams.'),
  (@b52, 5, 28, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis. Amen.'),
  (@b53, 1, 1, 'Paulius ir Silvanas, ir Timotiejus, tesalonikiečių bažnyčiai Dieve, mūsų Tėve, ir Viešpatyje Jėzuje Kristuje:'),
  (@b53, 1, 2, 'malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir Viešpaties Jėzaus Kristaus.'),
  (@b53, 1, 3, 'Mes privalome visuomet dėkoti Dievui už jus, broliai, kaip tai pridera, nes jūsų tikėjimas nepaprastai auga, ir kiekvieno visų jūsų meilė vieno kitam gausėja;'),
  (@b53, 1, 4, 'taip kad mes patys giriamės jumis Dievo bažnyčiose dėl jūsų kantrybės ir tikėjimo visuose jūsų persekiojimuose ir suspaudimuose, kuriuos ištveriate;'),
  (@b53, 1, 5, 'tai yra aiškus Dievo teisaus teismo ženklas, kad būtumėte palaikyti vertais Dievo karalystės, dėl kurios ir kenčiate;'),
  (@b53, 1, 6, 'kadangi Dievui yra teisinga atmokėti suspaudimu jūsų vargintojams;'),
  (@b53, 1, 7, 'ir jums, varginamiems, ilsėtis su mumis, kai Viešpats Jėzus bus apreikštas iš dangaus su savo galingais angelais,'),
  (@b53, 1, 8, 'liepsnojančia ugnimi atkeršydamas tiems, kurie nepažįsta Dievo ir nepaklūsta mūsų Viešpaties Jėzaus Kristaus evangelijai,'),
  (@b53, 1, 9, 'kurie bus nubausti amžinąja pražūtimi nuo Viešpaties veido ir nuo jo jėgos šlovės;'),
  (@b53, 1, 10, 'kai jis ateis, kad tą dieną būtų pašlovintas savo šventuosiuose ir juo žavėtųsi visuose tuose, kurie tiki (nes mūsų liudijimas tarp jūsų buvo įtikėtas).'),
  (@b53, 1, 11, 'Todėl visuomet ir meldžiamės už jus, kad mūsų Dievas palaikytų jus vertais šio pašaukimo ir įvykdytų visą savo gerumo gerą norą ir tikėjimo darbą su jėga;'),
  (@b53, 1, 12, 'kad mūsų Viešpaties Jėzaus Kristaus vardas būtų pašlovintas jumyse, ir jūs jame, pagal mūsų Dievo ir Viešpaties Jėzaus Kristaus malonę.'),
  (@b53, 2, 1, 'Maldaujame gi jus, broliai, mūsų Viešpaties Jėzaus Kristaus atėjimu ir mūsų susirinkimu pas jį,'),
  (@b53, 2, 2, 'kad greit nesvyruotumėte prote ar nebūtumėte sutrikdyti nei dvasia, nei žodžiu, nei laišku, tarsi nuo mūsų, esą Kristaus diena jau čia pat.'),
  (@b53, 2, 3, 'Tegul niekas neapgauna jūsų kokiu nors būdu; nes ta diena neateis, kol pirma neateis atkritimas ir nebus apreikštas tas nuodėmės žmogus, pražūties sūnus;'),
  (@b53, 2, 4, 'kuris priešinasi ir aukštinasi viršum viso, kas vadinama Dievu, ar to, kas garbinama; taip, kad jis sėdi Dievo šventykloje kaip Dievas, rodydamas save esant Dievu.'),
  (@b53, 2, 5, 'Ar neprisimenate, kad dar būdamas pas jus jums tai sakiau?'),
  (@b53, 2, 6, 'Ir dabar žinote, kas sulaiko, kad jis būtų apreikštas savo laiku.'),
  (@b53, 2, 7, 'Nes neteisybės paslaptis jau veikia; tik tas, kuris dabar sulaiko, dar sulaikys, kol bus patrauktas.'),
  (@b53, 2, 8, 'Ir tada bus apreikštas tas nedorėlis, kurį Viešpats užmuš savo burnos dvasia ir sunaikins savo atėjimo spindesiu,'),
  (@b53, 2, 9, 'būtent tą, kurio atėjimas yra pagal šėtono veikimą su visokia jėga ir ženklais, ir melagingais stebuklais,'),
  (@b53, 2, 10, 'ir su visokia neteisumo apgavyste tuose, kurie žūsta; nes jie nepriėmė tiesos meilės, kad būtų išgelbėti.'),
  (@b53, 2, 11, 'Ir todėl Dievas pasiųs jiems stiprų paklydimą, kad jie tikėtų melu,'),
  (@b53, 2, 12, 'kad būtų pasmerkti visi, kurie netikėjo tiesa, bet mėgavosi neteisumu.'),
  (@b53, 2, 13, 'Bet mes privalome nuolat dėkoti Dievui už jus, Viešpaties mylimi broliai, nes Dievas nuo pradžios jus išsirinko išgelbėjimui per Dvasios pašventimą ir tiesos tikėjimą;'),
  (@b53, 2, 14, 'į tai jis pašaukė jus per mūsų evangeliją, kad įgytumėte mūsų Viešpaties Jėzaus Kristaus šlovę.'),
  (@b53, 2, 15, 'Todėl, broliai, stovėkite tvirtai ir laikykitės tradicijų, kurių buvote išmokyti ar tai žodžiu, ar mūsų laišku.'),
  (@b53, 2, 16, 'Na, o pats mūsų Viešpats Jėzus Kristus ir Dievas – mūsų Tėvas, kuris mus pamilo ir davė mums amžinąją paguodą bei gerą viltį per malonę,'),
  (@b53, 2, 17, 'teguodžia jūsų širdis ir tesutvirtina jus kiekviename gerame žodyje ir darbe.'),
  (@b53, 3, 1, 'Galiausiai, broliai, melskitės už mus, kad Viešpaties žodis turėtų laisvą kelią ir būtų pašlovintas, kaip ir pas jus,'),
  (@b53, 3, 2, 'ir kad mes būtume išvaduoti nuo neprotingų ir nedorų žmonių, nes ne visi turi tikėjimą.'),
  (@b53, 3, 3, 'Bet Viešpats yra ištikimas, kuris jus sutvirtins ir saugos jus nuo pikto.'),
  (@b53, 3, 4, 'Ir pasitikime Viešpatyje dėl jūsų, kad jūs ir darote, ir darysite tai, ką jums įsakome.'),
  (@b53, 3, 5, 'Ir Viešpats tenukreipia jūsų širdis į Dievo meilę ir į kantrų Kristaus laukimą.'),
  (@b53, 3, 6, 'Jums gi, broliai, įsakome mūsų Viešpaties Jėzaus Kristaus vardu, kad atsitrauktumėte nuo kiekvieno brolio, kuris vaikšto nedrausmingai ir ne pagal tradiciją, kurią iš mūsų gavo.'),
  (@b53, 3, 7, 'Nes patys žinote, kaip turite sekti mumis; nes mes nesielgėme tarp jūsų nedrausmingai;'),
  (@b53, 3, 8, 'nei nevalgėme veltui niekieno duonos; bet naktį ir dieną darbavomės su triūsu ir skausmingumu, kad neapsunkintume nei vieno iš jūsų:'),
  (@b53, 3, 9, 'ne todėl, kad neturime teisės, bet kad taptume jums pavyzdžiu sekti mumis.'),
  (@b53, 3, 10, 'Nes ir kai buvome su jumis, jums įsakėme tai, kad, jei kas nenori dirbti, tas neturi ir valgyti.'),
  (@b53, 3, 11, 'Nes girdime, kad yra kai kurie nedrausmingai vaikštantys tarp jūsų, visiškai nedirbantys, bet besikišantys į svetimus reikalus.'),
  (@b53, 3, 12, 'Na, o tokiems įsakome ir raginame per mūsų Viešpatį Jėzų Kristų, kad jie tyliai dirbtų ir valgytų savo pačių duoną.'),
  (@b53, 3, 13, 'Bet jūs, broliai, nepailskite darydami gera.'),
  (@b53, 3, 14, 'O jei kuris nepaklūsta mūsų žodžiui šiuo laišku, pasižymėkite tokį ir nebendraukite su juo, kad susigėstų.'),
  (@b53, 3, 15, 'Tačiau nelaikykite jo priešu, bet įspėkite jį kaip brolį.'),
  (@b53, 3, 16, 'Na, o pats ramybės Viešpats teduoda jums ramybę visuomet visais būdais. Viešpats tebūna su jumis visais.'),
  (@b53, 3, 17, 'Sveikinimas mano paties, Pauliaus, ranka, kas yra ženklas kiekviename laiške: taip aš rašau.'),
  (@b53, 3, 18, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis visais. Amen.'),
  (@b54, 1, 1, 'Paulius, Jėzaus Kristaus apaštalas įsakymu Dievo, mūsų Gelbėtojo, ir Viešpaties Jėzaus Kristaus, kuris yra mūsų viltis;'),
  (@b54, 1, 2, 'Timotiejui, mano sūnui tikėjime: malonė, gailestingumas ir ramybė nuo Dievo, mūsų Tėvo, ir Jėzaus Kristaus, mūsų Viešpaties.'),
  (@b54, 1, 3, 'Kaip vykdamas į Makedoniją maldavau tave vis dar pasilikti Efeze, kad kai kuriuos įpareigotum, idant jie nemokytų kito mokslo'),
  (@b54, 1, 4, 'nei nekreiptų dėmesio į pasakas ir begalines genealogijas, kurios greičiau sukelia klausimus, negu kad dievotą statydinimą, kuris yra tikėjime, – taip daryk.'),
  (@b54, 1, 5, 'Na, o įsakymo tikslas yra meilė iš tyros širdies ir iš geros sąžinės, ir iš neveidmainiško tikėjimo,'),
  (@b54, 1, 6, 'nuo ko kai kurie nukrypę pasuko į šalį, į tuščius plepalus;'),
  (@b54, 1, 7, 'trokšdami būti įstatymo mokytojai; nesuprasdami nei ką sako, nei ką tvirtina.'),
  (@b54, 1, 8, 'Bet žinome, kad įstatymas yra geras, jei kas teisėtai jį naudoja,'),
  (@b54, 1, 9, 'žinodamas tai, kad įstatymas nėra skirtas teisiajam, bet nepaisantiems įstatymų ir neklusniems, bedieviams ir nusidėjėliams, nešventiems ir suterštiems, tėvažudžiams ir motinžudžiams, žmogžudžiams,'),
  (@b54, 1, 10, 'paleistuviams, susiteršiantiems su vyriškąja lytimi, žmogvagiams, melagiams, melagingai prisiekiantiems, ir jei dar yra kas kita, kas priešinga sveikam mokslui;'),
  (@b54, 1, 11, 'pagal palaimintojo Dievo šlovingąją evangeliją, kuri buvo man patikėta.'),
  (@b54, 1, 12, 'Ir aš dėkoju Kristui Jėzui, mūsų Viešpačiui, kuris įgalino mane, kad palaikė mane ištikimu, įstatydamas mane į tarnystę;'),
  (@b54, 1, 13, 'kuris anksčiau buvau piktžodžiautojas ir persekiotojas, ir kenkiantis; bet manęs buvo pasigailėta, nes tai dariau nežinodamas, per netikėjimą.'),
  (@b54, 1, 14, 'Ir mūsų Viešpaties malonė buvo be galo gausi, su tikėjimu ir meile, kuri yra Kristuje Jėzuje.'),
  (@b54, 1, 15, 'Šitas yra ištikimas pasakymas ir vertas visiško pritarimo, kad Kristus Jėzus atėjo į pasaulį išgelbėti nusidėjėlių; iš kurių aš esu pirmiausias.'),
  (@b54, 1, 16, 'Tačiau dėl to manęs buvo pasigailėta, kad manyje pirmajame Jėzus Kristus parodytų visą ilgą pakantumą kaip pavyzdį tiems, kurie po to įtikės į jį amžinajam gyvenimui.'),
  (@b54, 1, 17, 'Na, o amžinajam Karaliui, nemirtingajam, neregimajam, vieninteliam išmintingajam Dievui tebūna garbė ir šlovė per amžių amžius. Amen.'),
  (@b54, 1, 18, 'Šį įpareigojimą pavedu tau, sūnau Timotiejau, pagal pranašystes, kurios anksčiau apie tave atėjo, kad per jas kovotum gerą kovą;'),
  (@b54, 1, 19, 'išlaikydamas tikėjimą ir gerą sąžinę; kurią kai kurie atmetę, tikėjimo atžvilgiu patyrė laivo sudužimą;'),
  (@b54, 1, 20, 'iš kurių yra Himenėjas ir Aleksandras; kuriuos atidaviau šėtonui, kad išmoktų nepiktžodžiauti.'),
  (@b54, 2, 1, 'Todėl raginu, kad visų pirma būtų atliekami prašymai, maldos, užtarimai ir padėkos už visus žmones:'),
  (@b54, 2, 2, 'už karalius ir už visus, esančius valdžioje; kad gyventume tylų ir taikų gyvenimą visame dievotume ir dorume.'),
  (@b54, 2, 3, 'Nes tai gera ir priimtina akyse Dievo, mūsų Gelbėtojo;'),
  (@b54, 2, 4, 'kuris nori, kad visi žmonės būtų išgelbėti ir ateitų į tiesos pažinimą.'),
  (@b54, 2, 5, 'Nes yra vienas Dievas ir vienas tarpininkas tarp Dievo ir žmonių – žmogus Kristus Jėzus;'),
  (@b54, 2, 6, 'kuris atidavė save išpirka už visus, kad būtų paliudytas tinkamu laiku.'),
  (@b54, 2, 7, 'Šitam aš esu paskirtas skelbėju ir apaštalu (kalbu tiesą Kristuje ir nemeluoju), pagonių mokytoju tikėjime ir tiesoje.'),
  (@b54, 2, 8, 'Todėl noriu, kad vyrai visur melstųsi, keldami šventas rankas, be rūstybės ir abejojimo.'),
  (@b54, 2, 9, 'Taip pat ir kad moterys puoštųsi kukliais drabužiais, su drovumu ir blaivumu, ne supintais plaukais ar auksu, ar perlais, ar brangiais drabužiais,'),
  (@b54, 2, 10, 'bet (kas tinka moterims, išpažįstančioms dievotumą) gerais darbais.'),
  (@b54, 2, 11, 'Tegul moteris mokosi tyliai, su visišku paklusnumu.'),
  (@b54, 2, 12, 'Neleidžiu, kad moteris nei mokytų, nei kad pasiglemžtų valdžią vyrui vadovauti, bet kad laikytųsi tyliai.'),
  (@b54, 2, 13, 'Nes Adomas buvo suformuotas pirmas, paskui Ieva.'),
  (@b54, 2, 14, 'Ir Adomas nebuvo apgautas, bet moteris apgauta buvo nusižengime.'),
  (@b54, 2, 15, 'Tačiau ji bus išgelbėta vaikų gimdymu, jeigu jos pasiliks tikėjime ir meilėje, ir šventume su blaivumu.'),
  (@b54, 3, 1, 'Tai yra tikras pasakymas: jei kas trokšta vyskupo tarnystės, tas trokšta gero darbo.'),
  (@b54, 3, 2, 'Tuomet vyskupas turi būti nepeiktinas, vienos žmonos vyras, budrus, blaivus, gero elgesio, linkęs į svetingumą, sugebantis mokyti;'),
  (@b54, 3, 3, 'ne linkęs į vyną, ne mušeika, ne geidžiantis nešvaraus pelno; bet kantrus, ne triukšmadarys, ne godus;'),
  (@b54, 3, 4, 'gerai valdantis savo namus, savo vaikus laikantis klusnume visu rimtumu;'),
  (@b54, 3, 5, '(nes jei kas nežino, kaip valdyti savo namus, kaip jis rūpinsis Dievo bažnyčia?)'),
  (@b54, 3, 6, 'ne naujatikis, kad pasididžiavęs neįpultų į velnio pasmerkimą.'),
  (@b54, 3, 7, 'Be to, jis turi turėti gerą atsiliepimą nuo esančiųjų išorėje; kad nepatektų į priekaištavimą ir velnio pinkles.'),
  (@b54, 3, 8, 'Taip pat diakonai turi būti rimti, ne dviliežuviai, ne linkę į daug vyno, ne godūs nešvaraus pelno;'),
  (@b54, 3, 9, 'išlaikantys tikėjimo paslaptį tyroje sąžinėje.'),
  (@b54, 3, 10, 'Ir šitie taip pat pirma tebūna išmėginti; paskui tediakonauja, kai rasis nepeiktini.'),
  (@b54, 3, 11, 'Taip ir jų žmonos turi būti rimtos, ne šmeižikės, blaivios, visame kame ištikimos.'),
  (@b54, 3, 12, 'Diakonai tebūna vienos žmonos vyrai, gerai valdantys savo vaikus ir savo namus.'),
  (@b54, 3, 13, 'Nes kurie gerai diakonavo, įgyja gerą laipsnį ir didelę drąsą tikėjime, kuris yra Kristuje Jėzuje.'),
  (@b54, 3, 14, 'Tai tau rašau tikėdamasis netrukus ateiti pas tave;'),
  (@b54, 3, 15, 'bet jei ilgai užtruksiu, kad žinotum, kaip tu turi elgtis Dievo namuose, kurie yra gyvojo Dievo bažnyčia, tiesos stulpas ir pagrindas.'),
  (@b54, 3, 16, 'Ir neginčijamai didelė yra dievotumo paslaptis: Dievas buvo apreikštas kūne, išteisintas Dvasioje, regėtas angelų, paskelbtas pagonims, įtikėtas pasaulyje, paimtas aukštyn į šlovę.'),
  (@b54, 4, 1, 'Dvasia gi aiškiai sako, kad paskutiniais laikais kai kurie atsitrauks nuo tikėjimo, sutelkdami dėmesį į suviliojančias dvasias ir velnių mokslus;'),
  (@b54, 4, 2, 'veidmainingai kalbantys melą; turintys savo sąžinę išdegintą karšta geležimi;'),
  (@b54, 4, 3, 'draudžiantys tuoktis ir įsakantys susilaikyti nuo maisto, kurį Dievas sutvėrė, kad būtų priimtas su padėka tų, kurie tiki ir pažįsta tiesą.'),
  (@b54, 4, 4, 'Nes kiekvienas Dievo sutvėrimas yra geras, ir nieko nėra atmestino, jei tai priimama su padėka;'),
  (@b54, 4, 5, 'nes tai pašvenčiama Dievo žodžiu ir malda.'),
  (@b54, 4, 6, 'Jei priminsi broliams apie tuos dalykus, būsi geras Jėzaus Kristaus tarnautojas, pamaitintas žodžiais tikėjimo ir gero mokslo, kurį pasiekei.'),
  (@b54, 4, 7, 'Bet atmesk suterštas ir bobiškas pasakas, o verčiau lavink save dievotumui.'),
  (@b54, 4, 8, 'Nes kūniškas lavinimas duoda mažai naudos, bet dievotumas yra naudingas viskam, turintis dabartinio ir ateinančio gyvenimo pažadą.'),
  (@b54, 4, 9, 'Tai yra ištikimas pasakymas ir vertas visiško pritarimo.'),
  (@b54, 4, 10, 'Nes todėl ir triūsiame, ir kenčiame priekaištą, kadangi pasitikime gyvuoju Dievu, kuris yra visų žmonių Gelbėtojas, o ypač tų, kurie tiki.'),
  (@b54, 4, 11, 'Tuos dalykus įsakyk ir mokyk.'),
  (@b54, 4, 12, 'Niekas teneniekina tavo jaunystės; bet būk tikinčiųjų pavyzdys žodžiu, gyvensena, meile, dvasia, tikėjimu, skaistumu.'),
  (@b54, 4, 13, 'Kol ateisiu, užsiimk skaitymu, raginimu, mokslu.'),
  (@b54, 4, 14, 'Neapleisk dovanos, esančios tavyje, kuri tau buvo duota per pranašystę su vyresniųjų rankų uždėjimu.'),
  (@b54, 4, 15, 'Mąstyk apie tuos dalykus; atsiduok jiems visiškai; kad tavo pažanga būtų matoma visiems.'),
  (@b54, 4, 16, 'Žiūrėk savęs ir mokslo; pasilik juose, nes tai darydamas išgelbėsi ir save, ir tuos, kurie tavęs klausosi.'),
  (@b54, 5, 1, 'Vyresniojo nebark, bet maldauk jo kaip tėvo; o jaunesniųjų – kaip brolių;'),
  (@b54, 5, 2, 'vyresnių moterų – kaip motinų; jaunesnių – kaip seserų, visu skaistumu.'),
  (@b54, 5, 3, 'Gerbk našles, kurios tikrai yra našlės.'),
  (@b54, 5, 4, 'Bet jei kuri našlė turi vaikų ar vaikaičių, tegul jie pirma išmoksta parodyti pagarbą namuose ir atsimokėti savo tėvams; nes tai yra gera ir priimtina Dievo akyse.'),
  (@b54, 5, 5, 'Na, o ta, kuri tikrai yra našlė ir vieniša, pasitiki Dievu ir pasilieka prašymuose bei maldose naktį ir dieną.'),
  (@b54, 5, 6, 'Bet ta, kuri gyvena malonumais, yra mirusi dar būdama gyva.'),
  (@b54, 5, 7, 'Ir tai įpareigok, kad būtų nepeiktini.'),
  (@b54, 5, 8, 'Bet jei kas neaprūpina savųjų, o ypač savo namiškių, tas išsigynęs tikėjimo ir yra blogesnis už netikintįjį.'),
  (@b54, 5, 9, 'Tebūna į skaičių įtraukiama našlė ne jaunesnė kaip šešiasdešimties metų, buvusi vieno vyro žmona,'),
  (@b54, 5, 10, 'apie kurią gerai atsiliepiama už gerus darbus; jeigu ji išaugino vaikus, jei priglausdavo pašaliečius, jei plaudavo šventųjų kojas, jei pagelbėdavo vargstantiesiems, jei stropiai sekė kiekvienu geru darbu.'),
  (@b54, 5, 11, 'Bet jaunesnių našlių nepriimk; nes, pradėjusios gašlauti prieš Kristų, jos nori ištekėti;'),
  (@b54, 5, 12, 'turėdamos pasmerkimą, nes jos atmetė savo pirmąjį tikėjimą.'),
  (@b54, 5, 13, 'Ir, be to, jos išmoksta dykinėti, besibastydamos iš namų į namus; ir ne tik dykinėti, bet ir plepėti bei kištis į svetimus reikalus, kalbėdamos tai, ko neturėtų.'),
  (@b54, 5, 14, 'Todėl noriu, kad jaunesnės moterys ištekėtų, gimdytų vaikus, valdytų namus, neduotų priešininkui jokios progos kalbėti priekaištingai.'),
  (@b54, 5, 15, 'Nes kai kurios jau nusuko į šalį paskui šėtoną.'),
  (@b54, 5, 16, 'Jei kuris vyras ar moteris, kurie tiki, turi našlių, tegul joms pagelbėja ir tenebūna apsunkinama bažnyčia; kad ji pagelbėtų toms, kurios tikrai yra našlės.'),
  (@b54, 5, 17, 'Vyresnieji, kurie gerai valdo, tebūna laikomi vertais dvigubos pagarbos, ypač triūsiantys žodyje ir moksle.'),
  (@b54, 5, 18, 'Nes Raštas sako: „Neužrišk nasrų jaučiui, minančiam javus“. Ir: „Darbininkas vertas savo atlygio“.'),
  (@b54, 5, 19, 'Skundo prieš vyresnįjį nepriimk, bet tik dviejų ar trijų liudytojų akivaizdoje.'),
  (@b54, 5, 20, 'Tuos, kurie nusideda, bark visų akivaizdoje, kad ir kiti bijotų.'),
  (@b54, 5, 21, 'Įpareigoju tave Dievo ir Viešpaties Jėzaus Kristaus, ir išrinktųjų angelų akivaizdoje, kad laikytumeisi šių dalykų, neteikdamas pirmenybės vienam daugiau už kitą, nieko nedarydamas šališkai.'),
  (@b54, 5, 22, 'Nei ant vieno skubomis neuždėk rankų nei nebūk kito nuodėmių dalininku: išsilaikyk tyras.'),
  (@b54, 5, 23, 'Nebegerk vien vandens, bet vartok truputį vyno dėl savo skrandžio ir savo dažnų negalavimų.'),
  (@b54, 5, 24, 'Kai kurių žmonių nuodėmės yra iš anksto atviros, einančios pirma į teismą; o kai kuriuos jos seka paskui.'),
  (@b54, 5, 25, 'Taip pat ir kai kurių geri darbai yra iš anksto akivaizdūs; o tie, kurie yra kitokie, negali būti paslėpti.'),
  (@b54, 6, 1, 'Visi tarnai, kurie yra po jungu, telaiko savo šeimininkus vertais visokeriopos pagarbos, kad nebūtų piktžodžiaujama Dievo vardui ir jo mokslui.'),
  (@b54, 6, 2, 'O turintys tikinčius šeimininkus teneniekina jų, kadangi jie yra broliai; bet verčiau tetarnauja jiems, kadangi jie yra ištikimi ir mylimi, geradarystės dalininkai. To mokyk ir ragink.'),
  (@b54, 6, 3, 'Jei kas moko kitaip ir nesutinka su sveikais žodžiais, būtent mūsų Viešpaties Jėzaus Kristaus žodžiais – ir mokslu, kuris yra pagal dievotumą;'),
  (@b54, 6, 4, 'tas yra išdidus, nieko nežinantis, bet pakvaišęs dėl klausimų ir žodžių kovų, iš kurių kyla pavydas, kivirčai, keiksmai, pikti įtarinėjimai,'),
  (@b54, 6, 5, 'iškreipti ginčai sugedusio proto ir tiesos neturinčių žmonių, manančių, kad pelnas yra dievotumas; nuo tokių šalinkis.'),
  (@b54, 6, 6, 'Bet dievotumas su pasitenkinimu yra didelis pelnas.'),
  (@b54, 6, 7, 'Nes nieko neatsinešėme į šį pasaulį ir tikrai negalime nieko išsinešti.'),
  (@b54, 6, 8, 'Ir turėdami maisto bei drabužį, būkime tuo pasitenkinę.'),
  (@b54, 6, 9, 'Bet tie, kurie nori būti turtingi, įpuola į pagundą bei pinkles, ir į daugelį kvailų bei žalingų geismų, kurie paskandina žmones žlugime ir pražūtyje.'),
  (@b54, 6, 10, 'Nes meilė pinigams yra visokio blogio šaknis; kurių geisdami kai kurie nuklydo nuo tikėjimo ir pervėrė save daugybe sielvartų.'),
  (@b54, 6, 11, 'Bet tu, o Dievo žmogau, bėk nuo šitų dalykų; ir sek paskui teisumą, dievotumą, tikėjimą, meilę, kantrybę, romumą.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b54, 6, 12, 'Kovok gerąją tikėjimo kovą, nutverk amžinąjį gyvenimą, kuriam ir esi pašauktas, ir išpažinai gerą išpažinimą daugelio liudytojų akivaizdoje.'),
  (@b54, 6, 13, 'Įpareigoju tave Dievo akyse, kuris visa atgaivina, ir prieš Kristų Jėzų, kuris Pontijaus Piloto akivaizdoje liudijo gerą išpažinimą;'),
  (@b54, 6, 14, 'kad laikytumeisi šio įsakymo be dėmės, nepeiktinai, iki mūsų Viešpaties Jėzaus Kristaus pasirodymo,'),
  (@b54, 6, 15, 'kurį savo laikais parodys jis – palaimintasis ir vienintelis Valdovas, karalių Karalius ir viešpačių Viešpats;'),
  (@b54, 6, 16, 'vienintelis turintis nemirtingumą, gyvenantis šviesoje, prie kurios joks žmogus negali prieiti; kurio neregėjo nei vienas žmogus, nei negali regėti; kuriam tebūna garbė ir amžinoji valdžia. Amen.'),
  (@b54, 6, 17, 'Įpareigok tuos, kurie yra turtingi šiame pasaulyje, kad nebūtų išdidūs, nei pasitikėtų nepatikimais turtais, bet gyvuoju Dievu, kuris visko mums apsčiai duoda mėgavimuisi;'),
  (@b54, 6, 18, 'kad darytų gera, kad būtų turtingi gerais darbais, pasiruošę dalintis, norintys bendrauti;'),
  (@b54, 6, 19, 'susikraudami sau gerą pamatą ateinančiam laikui, kad nutvertų amžinąjį gyvenimą.'),
  (@b54, 6, 20, 'O Timotiejau, saugok tai, kas tau patikėta, vengdamas suterštų bei tuščių plepalų ir melagingai taip vadinamo mokslo prieštaravimų;'),
  (@b54, 6, 21, 'kai kurie jį išpažindami, tikėjimo atžvilgiu nuklydo. Malonė tebūna su tavimi. Amen.'),
  (@b55, 1, 1, 'Paulius, Dievo valia Jėzaus Kristaus apaštalas, pagal pažadą gyvenimo, esančio Kristuje Jėzuje,'),
  (@b55, 1, 2, 'mano brangiai mylimam sūnui Timotiejui: malonė, gailestingumas ir ramybė nuo Dievo Tėvo ir Kristaus Jėzaus, mūsų Viešpaties.'),
  (@b55, 1, 3, 'Dėkoju Dievui, kuriam tarnauju nuo savo protėvių tyra sąžine, kad be paliovos prisimenu tave savo maldose naktį ir dieną;'),
  (@b55, 1, 4, 'didžiai trokšdamas pamatyti tave, atmindamas tavo ašaras, kad būčiau pripildytas džiaugsmo;'),
  (@b55, 1, 5, 'kai prisimenu neveidmainišką tikėjimą, esantį tavyje, kuris pirmiau gyveno tavo senelėje Loidėje ir tavo motinoje Eunikėje; ir esu įsitikinęs, kad ir tavyje.'),
  (@b55, 1, 6, 'Todėl primenu tau, kad pakurstytum Dievo dovaną, kuri yra tavyje per mano rankų uždėjimą.'),
  (@b55, 1, 7, 'Nes Dievas nedavė mums baimės dvasios; bet jėgos ir meilės, ir sveiko proto.'),
  (@b55, 1, 8, 'Todėl nesigėdink mūsų Viešpaties liudijimo nei manęs, jo kalinio; bet būk evangelijos kančių dalininkas pagal Dievo jėgą;'),
  (@b55, 1, 9, 'kuris mus išgelbėjo ir pašaukė šventu pašaukimu ne pagal mūsų darbus, bet pagal savo tikslą ir malonę, kuri buvo mums duota Kristuje Jėzuje prieš pasaulio prasidėjimą,'),
  (@b55, 1, 10, 'bet dabar yra atskleista per pasirodymą mūsų Gelbėtojo Jėzaus Kristaus, kuris panaikino mirtį ir atnešė gyvenimą bei nemirtingumą į šviesą per evangeliją;'),
  (@b55, 1, 11, 'kuriai esu paskirtas skelbėju ir apaštalu, ir pagonių mokytoju.'),
  (@b55, 1, 12, 'Dėl šios priežasties tai ir kenčiu; tačiau nesigėdiju; nes žinau, kuo įtikėjau, ir esu įsitikinęs, kad jis pajėgus išsaugoti tai, ką jam patikėjau anai dienai.'),
  (@b55, 1, 13, 'Tvirtai laikykis pavidalo sveikų žodžių, kuriuos girdėjai iš manęs, tikėjime ir meilėje, kurie yra Kristuje Jėzuje.'),
  (@b55, 1, 14, 'Tą tau patikėtą gerą dalyką saugok Šventąja Dvasia, gyvenančia mumyse.'),
  (@b55, 1, 15, 'Tu tai žinai, kad nuo manęs nusigręžė visi, esantys Azijoje; iš kurių yra Figelas ir Hermogenas.'),
  (@b55, 1, 16, 'Viešpats teduoda gailestingumo Onesiforo namams; nes jis dažnai mane atgaivindavo ir nesigėdijo mano grandinės;'),
  (@b55, 1, 17, 'bet kai buvo Romoje, jis labai stropiai manęs ieškojo ir surado.'),
  (@b55, 1, 18, 'Viešpats tesuteikia jam, kad aną dieną rastų Viešpaties gailestingumą; ir kiek daugelyje dalykų jis patarnavo man Efeze, tu labai gerai žinai.'),
  (@b55, 2, 1, 'Taigi tu, mano sūnau, būk stiprus malonėje, esančioje Kristuje Jėzuje.'),
  (@b55, 2, 2, 'Ir ką iš manęs girdėjai tarp daugelio liudytojų, tai patikėk ištikimiems žmonėms, kurie bus pajėgūs ir kitus mokyti.'),
  (@b55, 2, 3, 'Taigi ištverk sunkumus, kaip geras Jėzaus Kristaus karys.'),
  (@b55, 2, 4, 'Nei vienas kariaujantis neįsivelia į šio gyvenimo reikalus; kad jis patiktų tam, kuris išrinko jį būti kariu.'),
  (@b55, 2, 5, 'Ir jei kas ir kovoja dėl pranašumo, nevainikuojamas, jei nekovoja pagal taisykles.'),
  (@b55, 2, 6, 'Triūsiantis žemdirbys turi būti pirmas vaisių dalininkas.'),
  (@b55, 2, 7, 'Apgalvok, ką sakau; ir Viešpats tau duos supratimą visame kame.'),
  (@b55, 2, 8, 'Prisimink, kad Jėzus Kristus, iš Dovydo sėklos, buvo prikeltas iš numirusiųjų pagal mano evangeliją,'),
  (@b55, 2, 9, 'kurioje kenčiu vargą kaip piktadarys, netgi iki pančių; bet Dievo žodis nėra supančiotas.'),
  (@b55, 2, 10, 'Todėl visa ištveriu dėl išrinktųjų, kad jie irgi įgytų išgelbėjimą, kuris yra Kristuje Jėzuje su amžinąja šlove.'),
  (@b55, 2, 11, 'Tai ištikimas pasakymas: Nes jei esame mirę su juo, mes ir gyvensime su juo;'),
  (@b55, 2, 12, 'jei kenčiame, mes ir karaliausime su juo; jei jo atsisakysime, ir jis mūsų atsisakys;'),
  (@b55, 2, 13, 'jei netikime, jis gi išlieka ištikimas – savęs jis negali atsisakyti.'),
  (@b55, 2, 14, 'Primink jiems apie tai, įpareigodamas Viešpaties akivaizdoje, kad jie nekovotų dėl žodžių, kas neduoda naudos, bet tik apverčia klausytojus.'),
  (@b55, 2, 15, 'Uoliai stenkis pasirodyti Dievui išmėgintu, neturinčiu ko gėdytis darbininku, teisingai padalijančiu tiesos žodį.'),
  (@b55, 2, 16, 'Bet venk suterštų ir tuščių plepalų; nes jie išaugs į daugiau bedieviškumo.'),
  (@b55, 2, 17, 'Ir jų žodis ės kaip ėda vėžys; iš kurių yra Himenėjas ir Filetas;'),
  (@b55, 2, 18, 'kurie tiesos atžvilgiu nuklydo, sakydami, kad prisikėlimas jau įvykęs; ir griauna kai kurių tikėjimą.'),
  (@b55, 2, 19, 'Tačiau Dievo pamatas stovi tvirtai, turintis šį antspaudą: „Viešpats pažįsta tuos, kurie yra jo“. Ir: „Tegul kiekvienas, kuris mini Kristaus vardą, atsitraukia nuo neteisybės“.'),
  (@b55, 2, 20, 'Bet dideliuose namuose yra indų ne tik iš aukso ir sidabro, bet ir iš medžio bei molio; ir kai kurie garbei, o kai kurie negarbei.'),
  (@b55, 2, 21, 'Todėl jei kas apsivalys nuo šitų, tas bus indas garbei, pašvęstas ir tinkamas šeimininko naudojimui, ir paruoštas kiekvienam geram darbui.'),
  (@b55, 2, 22, 'Taip pat bėk nuo jaunatvės geismų; bet sek teisumu, tikėjimu, meile, ramybe su tais, kurie šaukiasi Viešpaties iš tyros širdies.'),
  (@b55, 2, 23, 'Bet venk kvailų ir nemokšiškų klausimų, žinodamas, kad jie gimdo kivirčus.'),
  (@b55, 2, 24, 'O Viešpaties tarnas neturi kivirčytis; bet būti malonus visiems, sugebantis mokyti, kantrus,'),
  (@b55, 2, 25, 'romumu pamokantis prieštaraujančius; rasi Dievas duos jiems atgailą tiesai pripažinti;'),
  (@b55, 2, 26, 'ir kad jie atsipeikėtų nuo velnio pinklių, kurie yra jo paimti nelaisvėn jo valia.'),
  (@b55, 3, 1, 'Žinok ir tai, kad paskutinėmis dienomis ateis pavojingi laikai.'),
  (@b55, 3, 2, 'Nes žmonės bus savimylos, godūs, pagyrūnai, išdidūs, piktžodžiautojai, neklusnūs tėvams, nedėkingi, nešventi,'),
  (@b55, 3, 3, 'be prigimtinio prieraišumo, paliaubų laužytojai, melagingi kaltintojai, nesusivaldantys, niršūs, nekenčiantys tų, kurie yra geri,'),
  (@b55, 3, 4, 'išdavikai, karštagalviai, pasipūtę, labiau malonumų mylėtojai nei Dievo mylėtojai;'),
  (@b55, 3, 5, 'turintys dievotumo pavidalą, bet išsižadėję jo jėgos; nuo tokių šalinkis.'),
  (@b55, 3, 6, 'Nes iš tokių yra tie, kurie įslenka į namus ir veda nelaisvėn paikas moteris, nuodėmėmis apkrautas, įvairių geismų vedžiojamas,'),
  (@b55, 3, 7, 'visada besimokančias ir niekados nepajėgiančias ateiti į tiesos pažinimą.'),
  (@b55, 3, 8, 'Na, o kaip Janas ir Jambras priešinosi Mozei, taip ir šitie priešinasi tiesai: sugedusio proto žmonės, tikėjimo atžvilgiu atmestini.'),
  (@b55, 3, 9, 'Bet jie toliau nepažengs, nes jų kvailybė, kaip ir anų, paaiškės visiems.'),
  (@b55, 3, 10, 'Bet tu pilnai pažinai mano mokslą, gyvenimo būdą, tikslą, tikėjimą, ilgą pakantumą, meilę, kantrybę,'),
  (@b55, 3, 11, 'persekiojimus, kentėjimus, kurie mane ištiko Antioche, Ikonijuje, Listroje; kokius persekiojimus iškenčiau; bet iš jų visų Viešpats mane išvadavo.'),
  (@b55, 3, 12, 'Taip, ir visi, norintys dievotai gyventi Kristuje Jėzuje, kentės persekiojimą.'),
  (@b55, 3, 13, 'Bet pikti žmonės ir suvedžiotojai eis blogyn ir blogyn, klaidindami ir klaidinami.'),
  (@b55, 3, 14, 'Bet tu pasilik tame, ko išmokai ir kuo esi užtikrintas, žinodamas, iš ko tai išmokai;'),
  (@b55, 3, 15, 'ir kad nuo vaikystės esi pažinęs šventuosius Raštus, kurie pajėgūs padaryti tave išmintingu išgelbėjimui per tikėjimą, kuris yra Kristuje Jėzuje.'),
  (@b55, 3, 16, 'Visas Raštas yra duotas Dievo įkvėpimu ir yra naudingas mokslui, pabarimui, pataisymui, teisumo pamokymui,'),
  (@b55, 3, 17, 'kad Dievo žmogus būtų tobulas, pilnai aprūpintas visiems geriems darbams.'),
  (@b55, 4, 1, 'Todėl tave įpareigoju akivaizdoje Dievo ir Viešpaties Jėzaus Kristaus, kuris teis gyvus ir mirusius savo pasirodyme ir savo karalystėje:'),
  (@b55, 4, 2, 'skelbk žodį; nedelsk laiku ir nelaiku; bark, peik, ragink su visu ilgu pakantumu ir mokslu.'),
  (@b55, 4, 3, 'Nes ateis laikas, kai jie nebepakęs sveiko mokslo; bet susikraus sau mokytojų pagal savo geismus, turėdami niežtinčias ausis;'),
  (@b55, 4, 4, 'ir nukreips savo ausis nuo tiesos ir atsigręš į pasakas.'),
  (@b55, 4, 5, 'Bet tu visame kame budėk, iškęsk vargus, dirbk evangelisto darbą, pilnai įrodyk savo tarnystę.'),
  (@b55, 4, 6, 'Nes aš jau pasiruošęs būti atnašaujamas, ir mano išėjimo laikas čia pat.'),
  (@b55, 4, 7, 'Aš kovojau gerą kovą, užbaigiau savo bėgimą, išlaikiau tikėjimą;'),
  (@b55, 4, 8, 'nuo šiol man atidėtas teisumo vainikas, kurį aną dieną man duos Viešpats, teisusis teisėjas: ir ne vien man, bet ir visiems mylintiems jo pasirodymą.'),
  (@b55, 4, 9, 'Pasistenk greitai ateiti pas mane;'),
  (@b55, 4, 10, 'nes Demas, pamilęs šį dabartinį pasaulį, mane paliko ir išėjo į Tesaloniką; Kreskas – į Galatiją, Titas – į Dalmatiją.'),
  (@b55, 4, 11, 'Vien Lukas yra su manimi. Paimk Morkų ir atsivesk su savimi; nes jis man naudingas tarnystei.'),
  (@b55, 4, 12, 'O Tichiką pasiunčiau į Efezą.'),
  (@b55, 4, 13, 'Ateidamas atsinešk apsiaustą, kurį palikau Trojoje pas Karpą, ir knygas, o ypač pergamentus.'),
  (@b55, 4, 14, 'Vario kalėjas Aleksandras man padarė daug pikto; Viešpats jam atlygins pagal jo darbus;'),
  (@b55, 4, 15, 'ir tu jo saugokis; nes jis labai priešinosi mūsų žodžiams.'),
  (@b55, 4, 16, 'Mano pirmajame apsigynime su manimi nestovėjo nei vienas, bet visi mane paliko; meldžiu Dievą, kad tai jiems nebūtų įskaityta kaltinimui.'),
  (@b55, 4, 17, 'Tačiau su manimi stovėjo Viešpats ir mane sustiprino; kad per mane skelbimas būtų pilnai žinomas, ir kad visi pagonys išgirstų; ir buvau išvaduotas iš liūto nasrų.'),
  (@b55, 4, 18, 'Ir Viešpats išvaduos mane iš kiekvieno pikto darbo, ir išsaugos savo dangiškajai karalystei; kuriam tebūna šlovė per amžių amžius. Amen.'),
  (@b55, 4, 19, 'Sveikink Priską ir Akvilą, ir Onesiforo namiškius.'),
  (@b55, 4, 20, 'Erastas pasiliko Korinte; bet Trofimą palikau Milete sergantį.'),
  (@b55, 4, 21, 'Pasistenk ateiti prieš žiemą. Tave sveikina Eubijus ir Pudensas, ir Linas, ir Klaudija, ir visi broliai.'),
  (@b55, 4, 22, 'Viešpats Jėzus Kristus tebūna su tavo dvasia. Malonė tebūna su jumis. Amen.'),
  (@b56, 1, 1, 'Paulius, Dievo tarnas ir Jėzaus Kristaus apaštalas, pagal Dievo išrinktųjų tikėjimą ir pripažinimą tiesos, kuri yra pagal dievotumą;'),
  (@b56, 1, 2, 'viltyje amžinojo gyvenimo, kurį negalintis meluoti Dievas pažadėjo prieš pasaulio prasidėjimą;'),
  (@b56, 1, 3, 'bet tinkamais laikais atskleidė savo žodį per skelbimą, kuris yra patikėtas man pagal Dievo, mūsų Gelbėtojo, įsakymą;'),
  (@b56, 1, 4, 'Titui, mano sūnui pagal bendrą tikėjimą: malonė, gailestingumas ir ramybė nuo Dievo Tėvo ir Viešpaties Jėzaus Kristaus, mūsų Gelbėtojo.'),
  (@b56, 1, 5, 'Palikau tave Kretoje dėl to, kad sutvarkytum tai, kas dar nesutvarkyta, ir kiekviename mieste paskirtum vyresniuosius, kaip tave paskyriau:'),
  (@b56, 1, 6, 'jei kuris yra nepeiktinas, vienos žmonos vyras, turintis ištikimus vaikus, nekaltinamus maištingumu ar neklusnumu.'),
  (@b56, 1, 7, 'Nes vyskupas turi būti nepeiktinas, kaip Dievo ūkvedys; ne savivaliautojas, ne greitas pykti, ne linkęs į vyną, ne mušeika, ne linkęs į nešvarų pelną;'),
  (@b56, 1, 8, 'bet mylintis svetingumą, mylintis gerus žmones, blaivus, teisingas, šventas, susivaldantis;'),
  (@b56, 1, 9, 'tvirtai besilaikantis ištikimo žodžio, kaip buvo išmokytas, kad sveiku mokslu pajėgtų ir paraginti, ir įtikinti prieštaraujančius.'),
  (@b56, 1, 10, 'Nes yra daug nesuvaldomų ir tuščiakalbių, ir apgaudinėtojų, ypač tų iš apipjaustymo;'),
  (@b56, 1, 11, 'kurių burnos turi būti užčiauptos, kurie apverčia ištisus namus, mokydami tai, ko neturėtų, dėl nešvaraus pelno.'),
  (@b56, 1, 12, 'Vienas iš jų, jų pačių pranašas, sakė: „Kretiečiai visados melagiai, pikti žvėrys, tingūs pilvai“.'),
  (@b56, 1, 13, 'Šis liudijimas teisingas. Todėl bark juos griežtai, kad būtų sveiki tikėjime;'),
  (@b56, 1, 14, 'nekreipdami dėmesio į žydiškas pasakas ir žmonių įsakymus, kurie nukreipia nuo tiesos.'),
  (@b56, 1, 15, 'Tyriems viskas tyra, bet susiteršusiems ir netikintiems nieko nėra tyro; bet netgi jų protas ir sąžinė yra suteršti.'),
  (@b56, 1, 16, 'Jie išpažįsta žinantys Dievą; bet darbais jį paneigia, būdami pasibjaurėtini ir neklusnūs, ir netikę nei vienam geram darbui.'),
  (@b56, 2, 1, 'Bet tu kalbėk tai, kas tinka sveikam mokslui;'),
  (@b56, 2, 2, 'kad senesni vyrai būtų blaivūs, rimti, susivaldantys, sveiki tikėjime, meilėje, kantrybėje.'),
  (@b56, 2, 3, 'Taip pat ir kad senesnės moterys elgtųsi kaip tinka šventumui, kad būtų ne melagingos kaltintojos, ne linkusios į daug vyno, gero mokytojos;'),
  (@b56, 2, 4, 'kad mokytų jaunas moteris būti blaiviomis, mylėti savo vyrus, mylėti savo vaikus,'),
  (@b56, 2, 5, 'būti apdairiomis, skaisčiomis, prižiūrinčiomis namus, geromis, klusniomis savo pačių vyrams, kad nebūtų piktžodžiaujama Dievo žodžiui.'),
  (@b56, 2, 6, 'Taip pat jaunus vyrus ragink būti blaivaus proto.'),
  (@b56, 2, 7, 'Visame kame rodydamas save gerų darbų pavyzdžiu: moksle rodydamas neiškreiptumą, rimtumą, nuoširdumą,'),
  (@b56, 2, 8, 'sveiką kalbą, kurios nebūtų galima pasmerkti; kad tas, iš priešingos pusės, susigėstų, neturėdamas nieko pikto apie jus pasakyti.'),
  (@b56, 2, 9, 'Ragink tarnus būti klusniais savo šeimininkams, jiems visame kame gerai įtikti, neatsikalbinėjant;'),
  (@b56, 2, 10, 'ne vagiliaujant, bet parodant visokeriopą gerą ištikimybę; kad visame kame puoštų Dievo, mūsų Gelbėtojo, mokslą.'),
  (@b56, 2, 11, 'Nes Dievo malonė, nešanti išgelbėjimą, pasirodė visiems žmonėms,'),
  (@b56, 2, 12, 'mokydama mus, kad, atsižadėję bedievystės ir pasaulietiškų geismų, gyventume blaiviai, teisiai ir dievotai šiame dabartiniame pasaulyje;'),
  (@b56, 2, 13, 'laukdami tos palaimintos vilties ir didžiojo Dievo bei mūsų Gelbėtojo Jėzaus Kristaus šlovingojo pasirodymo;'),
  (@b56, 2, 14, 'kuris atidavė save už mus, kad mus išpirktų iš visos neteisybės ir nuskaistintų sau ypatingą liaudį, uolią geriems darbams.'),
  (@b56, 2, 15, 'Tai kalbėk ir ragink, ir bark su visa valdžia. Tegul niekas tavęs neniekina.'),
  (@b56, 3, 1, 'Primink jiems būti pavaldžiais kunigaikštystėms ir valdžioms, paklusti valdytojams, būti pasiruošusiais kiekvienam geram darbui,'),
  (@b56, 3, 2, 'nekalbėti pikta nei apie vieną, nebūti triukšmadariais, bet švelniais, rodant visą romumą visiems žmonėms.'),
  (@b56, 3, 3, 'Nes ir mes patys kadaise buvome kvaili, neklusnūs, suklaidinti, tarnaujantys įvairiems geismams ir malonumams, gyvenantys piktybėje ir pavyde, nekenčiami ir nekenčiantys vieni kitų.'),
  (@b56, 3, 4, 'Bet kai pasirodė Dievo, mūsų Gelbėtojo, gerumas ir meilė žmogui,'),
  (@b56, 3, 5, 'jis išgelbėjo mus ne pagal teisumo darbus, kuriuos darėme, bet pagal savo gailestingumą, atgimdymo nuplovimu ir Šventosios Dvasios atnaujinimu;'),
  (@b56, 3, 6, 'kurios jis gausiai išliejo ant mūsų per Jėzų Kristų, mūsų Gelbėtoją;'),
  (@b56, 3, 7, 'kad, išteisinti jo malone, taptume paveldėtojais pagal amžinojo gyvenimo viltį.'),
  (@b56, 3, 8, 'Tai ištikimas pasakymas, ir noriu, kad nuolat tvirtintum šiuos dalykus, kad įtikėjusieji Dievu rūpintųsi išlaikyti gerus darbus. Tai gera ir naudinga žmonėms.'),
  (@b56, 3, 9, 'Bet venk kvailų klausimų ir genealogijų, ir nesutarimų, ir kivirčų dėl įstatymo; nes jie nenaudingi ir tušti.'),
  (@b56, 3, 10, 'Žmogų eretiką po pirmo ir antro įspėjimo atmesk;'),
  (@b56, 3, 11, 'žinodamas, kad toks yra apverstas ir nusideda, būdamas savęs pasmerktas.'),
  (@b56, 3, 12, 'Kai pasiųsiu pas tave Artemą arba Tichiką, pasistenk atvykti pas mane į Nikopolį; nes nusprendžiau ten žiemoti.'),
  (@b56, 3, 13, 'Įstatymininką Zeną ir Apolą stropiai išlydėk į kelionę, kad nieko jiems netrūktų.'),
  (@b56, 3, 14, 'Tesimoko ir mūsiškiai išlaikyti gerus darbus būtinoms reikmėms, kad nebūtų nevaisingi.'),
  (@b56, 3, 15, 'Tave sveikina visi, esantys su manimi. Sveikink tuos, kurie myli mus tikėjime. Malonė tebūna su jumis visais. Amen.'),
  (@b57, 1, 1, 'Paulius, Jėzaus Kristaus kalinys, ir mūsų brolis Timotiejus, mūsų brangiai mylimam ir bendradarbiui Filemonui'),
  (@b57, 1, 2, 'ir mūsų mylimai Apfijai, ir mūsų bendrakareiviui Archipui, ir bažnyčiai tavo namuose:'),
  (@b57, 1, 3, 'malonė jums ir ramybė nuo Dievo, mūsų Tėvo, ir Viešpaties Jėzaus Kristaus.'),
  (@b57, 1, 4, 'Dėkoju savo Dievui, visuomet minėdamas tave savo maldose,'),
  (@b57, 1, 5, 'girdėdamas apie tavo meilę ir tikėjimą, kurio turi Viešpačiui Jėzui ir visiems šventiesiems;'),
  (@b57, 1, 6, 'kad tavo tikėjimo bendravimas taptų veiksmingas pripažįstant kiekvieną gerą dalyką, esantį jumyse Kristuje Jėzuje.'),
  (@b57, 1, 7, 'Nes mes turime didelį džiaugsmą ir paguodą tavo meilėje, nes šventųjų viduriai yra atgaivinti per tave, broli.'),
  (@b57, 1, 8, 'Todėl, nors galėčiau būti labai drąsus Kristuje įsakyti tau tai, kas tinkama,'),
  (@b57, 1, 9, 'tačiau meilės labui aš verčiau tavęs maldauju, būdamas toks, koks esu – Paulius, senesnysis, o dabar ir Jėzaus Kristaus kalinys.'),
  (@b57, 1, 10, 'Maldauju tavęs dėl savo sūnaus Onesimo, kurį pagimdžiau savo pančiuose;'),
  (@b57, 1, 11, 'kuris praeityje tau buvo nenaudingas, bet dabar naudingas tau ir man;'),
  (@b57, 1, 12, 'kurį siunčiau atgal; todėl priimk jį, tai yra, mano paties vidurius;'),
  (@b57, 1, 13, 'kurį norėjau pasilaikyti pas save, kad vietoje tavęs patarnautų man evangelijos pančiuose;'),
  (@b57, 1, 14, 'bet be tavo sutikimo nenorėjau nieko daryti; kad tavo geradarystė nebūtų tarsi iš būtinybės, bet laisvanoriška.'),
  (@b57, 1, 15, 'Nes gal todėl jis atsiskyrė laikotarpiui, kad jį priimtum amžiams;'),
  (@b57, 1, 16, 'jau ne kaip tarną, bet daugiau nei tarną, kaip mylimą brolį, ypač man, o kaip dar labiau tau, tiek kūne, tiek Viešpatyje.'),
  (@b57, 1, 17, 'Todėl jei laikai mane bendrininku, priimk jį kaip mane.'),
  (@b57, 1, 18, 'Jeigu jis tave nuskriaudė ar tau ką skolingas, įskaityk tai mano sąskaiton;'),
  (@b57, 1, 19, 'aš, Paulius, parašiau savo ranka, aš atmokėsiu; nors tau nesakau, kaip šalia to man esi skolingas net save patį.'),
  (@b57, 1, 20, 'Taip, broli, leisk man tavimi pasidžiaugti Viešpatyje: atgaivink mano vidurius Viešpatyje.'),
  (@b57, 1, 21, 'Pasitikėdamas tavo klusnumu tau parašiau, žinodamas, kad padarysi ir daugiau negu sakau.'),
  (@b57, 1, 22, 'Bet kartu man paruošk ir būstą; nes pasitikiu, kad per jūsų maldas būsiu jums duotas.'),
  (@b57, 1, 23, 'Tave sveikina Epafras, mano bendrakalinys Kristuje Jėzuje;'),
  (@b57, 1, 24, 'Morkus, Aristarchas, Demas, Lukas – mano bendradarbiai.'),
  (@b57, 1, 25, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jūsų dvasia. Amen.'),
  (@b58, 1, 1, 'Dievas, kuris įvairiais laikais ir įvairiais būdais praeityje kalbėjo tėvams per pranašus,'),
  (@b58, 1, 2, 'šiomis paskutinėmis dienomis prakalbo mums per savo Sūnų, kurį paskyrė visa ko paveldėtoju, per kurį taipogi padarė pasaulius;'),
  (@b58, 1, 3, 'kuris, būdamas jo šlovės spindesys bei tikslus jo asmens atvaizdas ir viską laikantis savo jėgos žodžiu, savimi nuvalęs mūsų nuodėmes, atsisėdo Didenybės dešinėje aukštybėse;'),
  (@b58, 1, 4, 'tapdamas tiek geresnis už angelus, kiek pranašesnį už juos paveldu gavo vardą.'),
  (@b58, 1, 5, 'Nes kuriam iš angelų jis kada nors pasakė: „Tu esi mano Sūnus, šią dieną aš tave pagimdžiau“? Ir vėl: „Aš būsiu jam Tėvas, o jis man bus Sūnus“?'),
  (@b58, 1, 6, 'Ir vėl, kai įveda pirmagimį į pasaulį, jis sako: „Ir tegarbina jį visi Dievo angelai“.'),
  (@b58, 1, 7, 'O apie angelus jis sako: „Jis padaro savo angelus dvasiomis ir savo tarnus – ugnies liepsna“.'),
  (@b58, 1, 8, 'Bet Sūnui sako: „Tavo sostas, o Dieve, yra per amžių amžius: teisumo skeptras – tavo karalystės skeptras.'),
  (@b58, 1, 9, 'Tu pamilai teisumą ir nekentei neteisybės; todėl Dievas, tavo Dievas, patepė tave džiaugsmo aliejumi daugiau nei tavo bendrus“.'),
  (@b58, 1, 10, 'Ir: „Tu, Viešpatie, pradžioje padėjai žemės pamatą; ir dangūs yra tavo rankų darbai;'),
  (@b58, 1, 11, 'jie pražus, bet tu pasiliksi; ir jie visi pasens kaip drabužis;'),
  (@b58, 1, 12, 'ir kaip apsiaustą juos suvyniosi, ir jie bus pakeisti; bet tu esi tas pats, ir tavo metai nesibaigs“.'),
  (@b58, 1, 13, 'Bet kuriam iš angelų jis kada nors pasakė: „Sėskis mano dešinėje, kol padarysiu tavo priešus tavo pakoju“?'),
  (@b58, 1, 14, 'Argi jie visi nėra patarnaujančios dvasios, išsiųstos patarnauti tiems, kurie bus išgelbėjimo paveldėtojai?'),
  (@b58, 2, 1, 'Todėl mes turime dar uoliau kreipti dėmesį į tai, ką esame girdėję, kad kuriuo metu neleistume tam išsprūsti.'),
  (@b58, 2, 2, 'Nes jei per angelus kalbėtas žodis buvo tvirtas, ir kiekvienas nusižengimas bei neklusnumas gaudavo teisingą atlygio užmokestį;'),
  (@b58, 2, 3, 'tai kaip mes pabėgsime, jei nepaisysime tokio didžio išgelbėjimo; kuris pirma buvo pradėtas kalbėti Viešpaties ir mums patvirtintas jį girdėjusiųjų;'),
  (@b58, 2, 4, 'ir Dievui jiems liudijant ženklais ir nuostabomis, ir įvairiais stebuklais, ir Šventosios Dvasios dovanomis, pagal jo valią?'),
  (@b58, 2, 5, 'Nes ne angelams jis pajungė ateinantį pasaulį, apie kurį kalbame.'),
  (@b58, 2, 6, 'Bet kažkas vienoje vietoje paliudijo, sakydamas: „Kas yra žmogus, kad jį atsimeni? Arba žmogaus sūnus, kad jį aplankai?'),
  (@b58, 2, 7, 'Tu padarei jį truputį žemesnį už angelus; apvainikavai jį šlove bei garbe ir pastatei jį virš savo rankų darbų;'),
  (@b58, 2, 8, 'visa padėjai po jo kojomis pavaldumui“. Nes tame, kad visa padėjo po juo pavaldumui, jis nepaliko nieko, kas nebūtų po juo padėta. Bet dabar dar nematome, kad visa padėta po juo.'),
  (@b58, 2, 9, 'Bet matome Jėzų, padarytą truputį žemesniu už angelus dėl mirties kančios, apvainikuotą šlove ir garbe; kad Dievo malone jis už kiekvieną paragautų mirties.'),
  (@b58, 2, 10, 'Nes priderėjo jam, dėl kurio yra visa, ir per kurį yra visa, vedant daugybę sūnų į šlovę, per kentėjimus jų išgelbėjimo vadą padaryti tobulą.'),
  (@b58, 2, 11, 'Nes tiek šventintojas, tiek pašvenčiamieji – visi yra iš vieno; dėl šios priežasties jis nesigėdija juos vadinti broliais,'),
  (@b58, 2, 12, 'sakydamas: „Aš paskelbsiu tavo vardą savo broliams, bažnyčios viduryje tau giedosiu gyrių“.'),
  (@b58, 2, 13, 'Ir vėl: „Aš juo pasitikėsiu“. Ir vėl: „Štai aš ir vaikai, kuriuos man davė Dievas“.'),
  (@b58, 2, 14, 'Kadangi vaikai yra kūno ir kraujo dalininkai, tai taip pat ir jis pats buvo to dalininkas; kad per mirtį sunaikintų tą, kuris turėjo mirties galią, tai yra velnią;'),
  (@b58, 2, 15, 'ir išvaduotų tuos, kurie dėl mirties baimės visą savo gyvenimą buvo pavaldūs vergystei.'),
  (@b58, 2, 16, 'Nes iš tiesų jis neprisiėmė angelų prigimties, bet prisiėmė Abraomo sėklą.'),
  (@b58, 2, 17, 'Todėl viskuo jam priderėjo tapti panašiu į savo brolius, kad būtų gailestingas ir ištikimas aukščiausiasis kunigas tame, kas priklauso Dievui, kad atliktų sutaikinimą už tautos nuodėmes.'),
  (@b58, 2, 18, 'Nes tame, kad jis pats kentėjo, kai buvo gundomas, jis yra pajėgus pagelbėti gundomiems.'),
  (@b58, 3, 1, 'Todėl, šventi broliai, dangiškojo pašaukimo dalininkai, įsižiūrėkite į mūsų išpažinimo Apaštalą ir Aukščiausiąjį Kunigą Kristų Jėzų;'),
  (@b58, 3, 2, 'kuris buvo ištikimas tam, kuris jį paskyrė, kaip ir Mozė buvo ištikimas visuose jo namuose.'),
  (@b58, 3, 3, 'Nes šitas buvo laikomas vertu didesnės šlovės negu Mozė, tiek, kiek namų statytojas turi daugiau garbės už namus.'),
  (@b58, 3, 4, 'Nes kiekvienas namas yra kieno tai statomas; bet tas, kuris viską pastatė, yra Dievas.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b58, 3, 5, 'Ir Mozė iš tiesų buvo ištikimas visuose jo namuose kaip tarnas, paliudijimui to, apie ką paskui turėjo būti kalbama;'),
  (@b58, 3, 6, 'bet Kristus, kaip sūnus, viešpatauja savo namams; kurio namai esame mes, jei tvirtai išlaikome pasitikėjimą ir vilties džiaugsmą tvirtą iki galo.'),
  (@b58, 3, 7, 'Todėl (kaip sako Šventoji Dvasia: „Šiandien, jei išgirsite jo balsą,'),
  (@b58, 3, 8, 'neužkietinkite savo širdžių kaip per kurstymą gundymo dieną dykumoje,'),
  (@b58, 3, 9, 'kai jūsų tėvai mane gundė, mane mėgino ir matė mano darbus per keturiasdešimt metų.'),
  (@b58, 3, 10, 'Todėl aš liūdėjau dėl šios kartos ir tariau: ‘Jie visados klysta savo širdyje; ir jie nėra pažinę mano kelių’.'),
  (@b58, 3, 11, 'Tai aš prisiekiu savo rūstybėje: ‘Jie neįeis į mano poilsį’“.)'),
  (@b58, 3, 12, 'žiūrėkitės, broliai, kad kuriame iš jūsų nebūtų pikta netikėjimo širdis, atsitraukiant nuo gyvojo Dievo.'),
  (@b58, 3, 13, 'Bet raginkite vienas kitą kas dieną, kol dar yra vadinama Šiandien; kad kuris iš jūsų nebūtų užkietintas per nuodėmės apgaulę.'),
  (@b58, 3, 14, 'Nes mes esame tapę Kristaus dalininkais, jei išlaikome mūsų pasitikėjimo pradžią tvirtą iki galo;'),
  (@b58, 3, 15, 'kol yra sakoma: „Šiandien, jei išgirsite jo balsą, neužkietinkite savo širdžių, kaip per kurstymą“.'),
  (@b58, 3, 16, 'Nes kai kurie išgirdę kurstė; tačiau ne visi išėjusieji iš Egipto per Mozę.'),
  (@b58, 3, 17, 'Bet dėl kurių jis liūdėjo keturiasdešimt metų? Argi ne dėl tų, kurie nusidėjo, kurių lavonai krito dykumoje?'),
  (@b58, 3, 18, 'O kuriems jis prisiekė, kad neįeis į jo poilsį, jei ne tiems, kurie netikėjo?'),
  (@b58, 3, 19, 'Taigi matome, kad jie negalėjo įeiti dėl netikėjimo.'),
  (@b58, 4, 1, 'Todėl bijokime, kad kuris iš jūsų neatrodytų atsilikęs nuo mums palikto pažado įeiti į jo poilsį.'),
  (@b58, 4, 2, 'Nes mums buvo paskelbta evangelija kaip ir jiems, bet paskelbtas žodis jiems nedavė naudos, nebuvęs sujungtas su tikėjimu tuose, kurie jį girdėjo.'),
  (@b58, 4, 3, 'Nes mes, kurie įtikėjome, įeiname į poilsį, kaip jis sakė: „Kaip aš prisiekiau savo rūstybėje, jeigu jie įeis į mano poilsį“; nors darbai buvo užbaigti nuo pasaulio įkūrimo.'),
  (@b58, 4, 4, 'Nes jis tam tikroje vietoje apie septintąją dieną kalbėjo šitaip: „Ir Dievas septintąją dieną ilsėjosi nuo visų savo darbų“.'),
  (@b58, 4, 5, 'Ir toje vietoje vėl: „Jeigu jie įeis į mano poilsį“.'),
  (@b58, 4, 6, 'Tad kadangi pasilieka, kad kai kurie turi į jį įeiti, o tie, kuriems ji pirma buvo paskelbta, į jį neįėjo dėl netikėjimo;'),
  (@b58, 4, 7, 'vėlgi, jis apriboja tam tikra diena, sakydamas Dovyde: „Šiandien“, – po tokio ilgo laiko; kaip yra pasakyta: „Šiandien, jei išgirsite jo balsą, neužkietinkite savo širdžių“.'),
  (@b58, 4, 8, 'Nes jei Jėzus būtų jiems davęs poilsį, tuomet po to jis nebūtų kalbėjęs apie kitą dieną.'),
  (@b58, 4, 9, 'Todėl Dievo tautai pasilieka poilsis.'),
  (@b58, 4, 10, 'Nes tas, kuris įėjo į jo poilsį, irgi paliovė savo darbus, kaip Dievas – savus.'),
  (@b58, 4, 11, 'Todėl stenkimės įeiti į tą poilsį, kad kuris nenupultų, sekdamas tuo pačiu netikėjimo pavyzdžiu.'),
  (@b58, 4, 12, 'Nes Dievo žodis yra gyvas ir veiksmingas, ir aštresnis už bet kokį dviašmenį kalaviją, prasiskverbiantis iki perskyrimo sielos ir dvasios, ir sąnarių bei kaulų smegenų, ir įžvelgiantis širdies mintis bei ketinimus.'),
  (@b58, 4, 13, 'Ir nėra nei vieno sutvėrimo neaiškaus jo akyse; bet visa yra nuoga ir atidengta akims to, su kuriuo turime reikalą.'),
  (@b58, 4, 14, 'Tad kadangi turime didį aukščiausiąjį kunigą, perėjusį į dangus, Jėzų, Dievo Sūnų, tvirtai laikykimės mūsų išpažinimo.'),
  (@b58, 4, 15, 'Nes mes turime ne tokį aukščiausiąjį kunigą, kuris negalėtų atjausti mūsų negalių; bet kuris buvo visais atžvilgiais gundytas, kaip ir mes, tačiau be nuodėmės.'),
  (@b58, 4, 16, 'Todėl drąsiai ateikime prie malonės sosto, kad gautume gailestingumą ir rastume malonę pagalbai reikiamu laiku.'),
  (@b58, 5, 1, 'Nes kiekvienas aukščiausiasis kunigas, paimtas iš žmonių tarpo, yra paskiriamas dėl žmonių dalykuose, priklausančiuose Dievui, kad atnašautų tiek dovanas, tiek aukas už nuodėmes,'),
  (@b58, 5, 2, 'kuris gali užjausti nežinančiuosius ir nuklydusius nuo kelio; nes ir jis pats yra apgaubtas negalios.'),
  (@b58, 5, 3, 'Ir dėl jos jis turi, kaip už tautą, taip ir už save, atnašauti už nuodėmes.'),
  (@b58, 5, 4, 'Ir nei vienas sau nepasiima tos garbės, bet tas, kuris yra Dievo pašauktas, kaip buvo Aaronas.'),
  (@b58, 5, 5, 'Taip ir Kristus šlovino ne pats save, kad taptų aukščiausiuoju kunigu; bet tas, kuris jam tarė: „Tu mano Sūnus, šiandien tave pagimdžiau“.'),
  (@b58, 5, 6, 'Kaip jis sako ir kitoje vietoje: „Tu esi kunigas per amžius pagal Melkizedeko potvarkį“.'),
  (@b58, 5, 7, 'Kuris savo kūno dienomis su stipriu šauksmu bei ašaromis atnašavęs maldas ir prašymus tam, kuris buvo pajėgus jį išgelbėti iš mirties, ir buvo išklausytas tame, ko bijojo;'),
  (@b58, 5, 8, 'nors jis buvo Sūnus, tačiau išmoko klusnumo per tai, ką iškentėjo;'),
  (@b58, 5, 9, 'ir pasidaręs tobulas tapo amžinojo išgelbėjimo autoriumi visiems, kurie jam paklūsta;'),
  (@b58, 5, 10, 'Dievo pavadintas aukščiausiuoju kunigu pagal Melkizedeko potvarkį.'),
  (@b58, 5, 11, 'Apie kurį turime pasakyti daug dalykų ir sunkiai išsakomų, kadangi esate silpnai girdintys.'),
  (@b58, 5, 12, 'Nes kuomet pagal laiką turėtumėte būti mokytojai, jums reikia, kad kas jus vėl mokytų, kas yra Dievo pasakymų pradmenys; ir tapote tokie, kuriems reikia pieno, o ne stipraus maisto.'),
  (@b58, 5, 13, 'Nes kiekvienas, vartojantis pieną, yra nepatyręs teisumo žodyje; nes yra kūdikis.'),
  (@b58, 5, 14, 'Bet stiprus maistas tinka subrendusiems, tiems, kurie pratybomis išlavino savo pojūčius, kad atskirtų tiek gera, tiek pikta.'),
  (@b58, 6, 1, 'Todėl, palikę Kristaus mokslo pradmenis, eikime toliau į tobulumą; iš naujo nedėdami pamato atgailos nuo negyvų darbų ir tikėjimo į Dievą,'),
  (@b58, 6, 2, 'mokslo krikštų, rankų uždėjimo, mirusiųjų prisikėlimo ir amžinojo teismo.'),
  (@b58, 6, 3, 'Ir tai padarysime, jei Dievas leis.'),
  (@b58, 6, 4, 'Nes tie, kurie kartą buvo apšviesti ir paragavo dangiškosios dovanos, ir tapo Šventosios Dvasios dalininkais,'),
  (@b58, 6, 5, 'ir paragavo gerojo Dievo žodžio bei ateinančio pasaulio jėgų,'),
  (@b58, 6, 6, 'ir jei jie atkrenta, jų nebeįmanoma vėl atnaujinti atgailai; nes jie iš naujo kryžiuoja sau Dievo Sūnų ir išstato jį viešai gėdai.'),
  (@b58, 6, 7, 'Nes žemė, sugerianti dažnai ant jos krentantį lietų ir duodanti žoles, tinkančias tiems, kurie ją įdirba, gauna palaiminimą iš Dievo;'),
  (@b58, 6, 8, 'bet ta, kuri neša erškėčius ir usnis, yra atmetama ir yra arti prakeikimo; kurios galas – sudeginimas.'),
  (@b58, 6, 9, 'Bet mylimieji, nors taip kalbame, esame apie jus įsitikinę ko geresnio ir to, kas lydi išgelbėjimą.'),
  (@b58, 6, 10, 'Nes Dievas nėra neteisus, kad pamirštų jūsų darbą ir triūsą meilės, kurią parodėte jo vardui tuo, kad tarnavote šventiesiems ir tarnaujate.'),
  (@b58, 6, 11, 'Ir trokštame, kad kiekvienas iš jūsų iki galo rodytų tokį patį stropumą pilnam vilties užtikrintumui;'),
  (@b58, 6, 12, 'kad nebūtumėte tingūs, bet sekėjai tų, kurie per tikėjimą ir kantrumą paveldi pažadus.'),
  (@b58, 6, 13, 'Nes kai Dievas davė pažadą Abraomui, kadangi negalėjo niekuo didesniu prisiekti, jis prisiekė savimi,'),
  (@b58, 6, 14, 'sakydamas: „Iš tiesų aš laiminte tave palaiminsiu ir dauginte tave padauginsiu“.'),
  (@b58, 6, 15, 'Ir taip, kantriai iškentęs, jis gavo, kas žadėta.'),
  (@b58, 6, 16, 'Nes iš tiesų žmonės prisiekia didesniu, o priesaika patvirtinimui jiems yra viso ginčo pabaiga.'),
  (@b58, 6, 17, 'Tame Dievas, norėdamas pažado dalininkams gausiau parodyti savo sumanymo nekintamumą, patvirtino jį priesaika;'),
  (@b58, 6, 18, 'kad per du nekintamus dalykus, kuriuose Dievui buvo neįmanoma meluoti, turėtume stiprią paguodą, mes, kurie pabėgome į prieglobstį nutverti priešais mus padėtos vilties;'),
  (@b58, 6, 19, 'kurią turime kaip sielos inkarą, tiek patikimą, tiek tvirtą ir įeinantį į uždangos vidų;'),
  (@b58, 6, 20, 'kur už mus įėjo pirmtakas – Jėzus, tapęs aukščiausiuoju kunigu per amžius pagal Melkizedeko potvarkį.'),
  (@b58, 7, 1, 'Nes šitas Melkizedekas, Salemo karalius, aukščiausiojo Dievo kunigas, kuris pasitiko Abraomą, grįžtantį iš karalių žudynių, ir jį palaimino;'),
  (@b58, 7, 2, 'taip pat kuriam Abraomas davė nuo visko dešimtąją dalį; išvertus pirmiausiai esąs teisumo Karalius, o paskui ir Salemo Karalius, kas yra taikos Karalius;'),
  (@b58, 7, 3, 'be tėvo, be motinos, be kilmės, neturintis nei dienų pradžios, nei gyvenimo pabaigos; bet padarytas panašiu į Dievo Sūnų; nuolatos pasilieka kunigu.'),
  (@b58, 7, 4, 'Apmąstykite gi, koks didis buvo šis žmogus, kuriam net patriarchas Abraomas davė dešimtinę nuo grobio.'),
  (@b58, 7, 5, 'Ir iš tiesų, tie, kurie yra iš Levio sūnų, kurie gauna kunigystę, pagal įstatymą turi įsakymą imti iš tautos dešimtines, tai yra, iš savo brolių, nors jie ir išeina iš Abraomo strėnų;'),
  (@b58, 7, 6, 'bet tas, kurio kilmė nėra laikoma iš jų, gavo iš Abraomo dešimtines ir palaimino tą, kuris turėjo pažadus.'),
  (@b58, 7, 7, 'Ir, be jokio prieštaravimo, menkesnis yra palaimintas geresniojo.'),
  (@b58, 7, 8, 'Ir čia ima dešimtines žmonės, kurie miršta; bet ten jas ima tas, apie kurį yra paliudyta, kad jis gyvena.'),
  (@b58, 7, 9, 'Ir taip sakant, ir Levis, kuris ima dešimtines, mokėjo dešimtines Abraome.'),
  (@b58, 7, 10, 'Nes jis tebebuvo savo tėvo strėnose, kai jį pasitiko Melkizedekas.'),
  (@b58, 7, 11, 'Todėl jei tobulumas būtų per levitų kunigystę (nes jai vadovaujant tauta gavo įstatymą), tai kam dar būtų reikėję iškilti kitam kunigui pagal Melkizedeko potvarkį ir nebūti vadinamam pagal Aarono tvarką?'),
  (@b58, 7, 12, 'Nes pasikeitus kunigystei, dėl būtinybės atliekamas ir įstatymo pakeitimas.'),
  (@b58, 7, 13, 'Nes tas, apie kurį tai kalbama, priklauso kitai genčiai, iš kurios nei vienas netarnavo prie aukuro.'),
  (@b58, 7, 14, 'Nes yra aišku, kad mūsų Viešpats kilo iš Judos; apie tą gentį Mozė dėl kunigystės nieko nekalbėjo.'),
  (@b58, 7, 15, 'Ir tai yra dar aiškiau, nes pagal Melkizedeko panašumą iškyla kitas kunigas,'),
  (@b58, 7, 16, 'kuris padarytas ne pagal kūniško įsakymo įstatymą, bet pagal nesibaigiančio gyvenimo jėgą.'),
  (@b58, 7, 17, 'Nes jis liudija: „Tu esi kunigas per amžius pagal Melkizedeko potvarkį“.'),
  (@b58, 7, 18, 'Nes iš tiesų yra prieš tai veikusio įsakymo panaikinimas dėl jo silpnumo ir nenaudingumo.'),
  (@b58, 7, 19, 'Nes įstatymas nieko nepadarė tobulo, bet tai padarė įvedimas geresnės vilties; per kurią mes artinamės prie Dievo.'),
  (@b58, 7, 20, 'Ir tiek, kiek ne be priesaikos jis buvo padarytas kunigu'),
  (@b58, 7, 21, '(nes anie kunigais buvo daromi be priesaikos; bet šis su priesaika per tą, kuris jam tarė: „Viešpats prisiekia ir nesigailės – tu esi kunigas per amžius pagal Melkizedeko potvarkį“),'),
  (@b58, 7, 22, 'tiek daugiau Jėzus buvo padarytas geresnio testamento laiduotoju.'),
  (@b58, 7, 23, 'Ir iš tiesų jų buvo daug kunigų, nes jiems nebūdavo leista pasilikti dėl mirties;'),
  (@b58, 7, 24, 'bet šitas, kadangi jis pasilieka amžiams, turi nekintamą kunigystę.'),
  (@b58, 7, 25, 'Todėl jis yra pajėgus ir išgelbėti iki galo tuos, kurie per jį ateina prie Dievo, kadangi jis visada gyvena, kad juos užtartų.'),
  (@b58, 7, 26, 'Nes mums tiko toks aukščiausiasis kunigas: šventas, nekaltas, nesuterštas, atskirtas nuo nusidėjėlių ir padarytas aukštesniu nei dangūs;'),
  (@b58, 7, 27, 'kuriam nereikia, kaip tiems aukščiausiems kunigams, kasdien atnašauti aukos pirma už savo nuodėmes, o paskui už tautos; nes jis tai padarė vieną kartą, kai paaukojo save.'),
  (@b58, 7, 28, 'Nes įstatymas daro aukščiausiais kunigais žmones, turinčius negalias; bet priesaikos žodis, kuris buvo nuo pat įstatymo, daro Sūnų, kuris yra amžinai pašvęstas.'),
  (@b58, 8, 1, 'Na, o esmė to, ką kalbėjome, yra ši: mes turime tokį aukščiausiąjį kunigą, kuris yra atsisėdęs Didenybės sosto dešinėje danguose;'),
  (@b58, 8, 2, 'tarnautoją šventovės ir tikrosios padangtės, kurią pastatė Viešpats, o ne žmogus.'),
  (@b58, 8, 3, 'Nes kiekvienas aukščiausiasis kunigas yra paskirtas atnašauti dovanas ir aukas, todėl yra būtinybė, kad ir šis žmogus turėtų ką atnašauti.'),
  (@b58, 8, 4, 'Nes jeigu jis būtų žemėje, jis nebūtų kunigas, kadangi yra kunigai, kurie atnašauja dovanas pagal įstatymą,'),
  (@b58, 8, 5, 'kurie tarnauja dangiškų dalykų pavyzdžiui ir šešėliui, kaip Mozė buvo Dievo perspėtas, kai rengėsi daryti padangtę, nes: „Žiūrėk, – sako jis, – kad viską padarytum pagal tau kalne parodytą pavyzdį“.'),
  (@b58, 8, 6, 'Bet dabar jis gavo tiek pranašesnę tarnystę, kiek jis yra ir tarpininkas geresnės sandoros, kuri buvo įtvirtinta remiantis geresniais pažadais.'),
  (@b58, 8, 7, 'Nes jei ana pirmoji sandora būtų buvusi nepakaltinama, tuomet nebūtų ieškoma vietos antrajai.'),
  (@b58, 8, 8, 'Nes juos kaltindamas, jis sako: „Štai ateina dienos, – sako Viešpats, – kai sudarysiu naują sandorą su Izraelio namais ir su Judos namais:'),
  (@b58, 8, 9, 'ne pagal sandorą, kurią sudariau su jų tėvais tą dieną, kai paėmiau juos už rankos, kad išvesčiau juos iš Egipto šalies; kadangi jie nepasiliko mano sandoroje, ir aš jų nepaisiau, – sako Viešpats.'),
  (@b58, 8, 10, '– Nes šita yra sandora, kurią sudarysiu su Izraelio namais po tų dienų, – sako Viešpats; – aš įdėsiu savo įstatymus į jų protą ir įrašysiu juos jų širdyse, ir būsiu jiems Dievas, o jie bus man tauta;'),
  (@b58, 8, 11, 'ir jie nei vienas nemokys savo artimo ir nei vienas savo brolio, sakydami: ‘Pažink Viešpatį’, nes visi pažins mane, nuo mažiausio iki didžiausio.'),
  (@b58, 8, 12, 'Nes aš būsiu gailestingas jų neteisumui, ir jų nuodėmių bei jų neteisybių daugiau neprisiminsiu“.'),
  (@b58, 8, 13, 'Tuo, kad jis sako: „Naują sandorą“, jis pirmąją padarė sena. Na, o tai, kas genda ir sensta, yra arti išnykimo.'),
  (@b58, 9, 1, 'Tad iš tiesų, pirmoji sandora irgi turėjo dieviško tarnavimo potvarkių ir pasaulietišką šventovę.'),
  (@b58, 9, 2, 'Nes buvo padaryta padangtė; pirmoji, kurioje buvo žvakidė ir stalas, ir parodomoji duona; kuri vadinama šventove.'),
  (@b58, 9, 3, 'O už antrosios uždangos – padangtė, vadinama visų Švenčiausioji;'),
  (@b58, 9, 4, 'kuri turėjo auksinį smilkytuvą ir aplinkui auksu padengtą sandoros skrynią, kurioje buvo auksinis puodas su mana ir pumpurus išleidusi Aarono lazda, ir sandoros plokštės;'),
  (@b58, 9, 5, 'o virš jos – šlovės kerubai, dengiantys šešėliu gailestingumo krasę; apie ką dabar negalime kalbėti detaliai.'),
  (@b58, 9, 6, 'Na, o kai tie dalykai buvo taip nustatyti, kunigai visada įeidavo į pirmąją padangtę, atlikinėdami Dievo tarnavimą.'),
  (@b58, 9, 7, 'Bet į antrąją įeidavo vienas tik aukščiausiasis kunigas, kartą kiekvienais metais, ne be kraujo, kurį jis atnašaudavo už save ir už tautos suklydimus;'),
  (@b58, 9, 8, 'tuo Šventoji Dvasia parodo, kad kelias į visų švenčiausiąją dar nebuvo apreikštas, kol tebestovėjo pirmoji padangtė,'),
  (@b58, 9, 9, 'kuri buvo atvaizdas tuometinio laiko, kuriame buvo atnašaujamos tiek dovanos, tiek aukos, kurios negalėjo sąžinės atžvilgiu ištobulinti to, kuris tarnavo;'),
  (@b58, 9, 10, 'kas apėmė tik valgius ir gėrimus, ir įvairius apiplovimus, ir kūniškus potvarkius, jiems uždėtus iki pertvarkymo laiko.'),
  (@b58, 9, 11, 'Bet Kristus – atėjęs būsimųjų gerų dalykų aukščiausiasis kunigas per didesnę ir tobulesnę padangtę, ne rankomis padarytą, tai yra ne šios statybos;'),
  (@b58, 9, 12, 'ir ne per ožių bei veršių kraują, bet per savo kraują jis įėjo vieną kartą į šventąją vietą, gaudamas mums amžiną atpirkimą.'),
  (@b58, 9, 13, 'Nes jeigu jaučių bei ožių kraujas ir telyčios pelenai, apšlakstantys nešvariuosius, pašvenčia kūno apvalymui,'),
  (@b58, 9, 14, 'tai kaip juo labiau Kristaus kraujas, kuris per amžinąją Dvasią atnašavo save, esantį be dėmės Dievui, išvalys jūsų sąžines nuo negyvų darbų, kad tarnautumėte gyvajam Dievui?'),
  (@b58, 9, 15, 'Ir dėl to jis yra naujojo testamento tarpininkas, kad per mirtį, pirmajame testamente buvusiems nusižengimams atpir̃kti, pašauktieji gautų amžinojo paveldo pažadą.'),
  (@b58, 9, 16, 'Nes kur yra testamentas, ten dėl būtinybės turi būti ir testatoriaus mirtis.'),
  (@b58, 9, 17, 'Nes testamentas įsigalioja po to, kai žmogus yra miręs; kitaip jis visiškai neturi galios, kol testatorius gyvena.'),
  (@b58, 9, 18, 'Todėl nei pirmasis testamentas nebuvo pašvęstas be kraujo.'),
  (@b58, 9, 19, 'Nes Mozė, pagal įstatymą išsakęs visai tautai kiekvieną prisakymą, paėmė veršių bei ožių kraujo su vandeniu ir skaisčiai raudonos vilnos bei yzopą ir apšlakstė tiek knygą, tiek visą tautą,'),
  (@b58, 9, 20, 'sakydamas: „Šis yra kraujas testamento, kurį Dievas jums įsakė“.'),
  (@b58, 9, 21, 'Jis taip pat apšlakstė krauju ir padangtę, ir visus tarnystės indus.'),
  (@b58, 9, 22, 'Ir beveik viskas pagal įstatymą yra apvaloma krauju; ir be kraujo praliejimo nėra atleidimo.'),
  (@b58, 9, 23, 'Todėl buvo būtina, kad pavyzdžiai to, kas danguose, turi būti apvalomi šitais; bet patys dangiški dalykai – geresnėmis aukomis, negu šitos.'),
  (@b58, 9, 24, 'Nes Kristus įėjo ne į rankomis padarytas šventas vietas, kurios yra tikrųjų atvaizdai; bet į patį dangų, idant dabar pasirodytų Dievo akivaizdoje už mus;'),
  (@b58, 9, 25, 'ir ne tam, kad jis dažnai save atnašautų, kaip aukščiausiasis kunigas kasmet įeina į šventąją vietą su kitų krauju;'),
  (@b58, 9, 26, 'nes tuomet jam būtų reikėję daug kartų kentėti nuo pasaulio įkūrimo; bet dabar vieną kartą pasaulio pabaigoje jis pasirodė, kad savo auka pašalintų nuodėmę.'),
  (@b58, 9, 27, 'Ir kaip žmonėms yra skirta vieną kartą mirti, bet po to – teismas,'),
  (@b58, 9, 28, 'taip ir Kristus buvo vieną kartą atnašautas, kad neštų daugelio nuodėmes; ir tiems, kurie jo laukia, jis pasirodys antrą kartą be nuodėmės – išgelbėjimui.'),
  (@b58, 10, 1, 'Nes įstatymas, turintis ateinančių gerų dalykų šešėlį, o ne patį dalykų atvaizdą, niekada negali tomis aukomis, kurias jie kasmet be paliovos atnašaudavo, padaryti tobulais tų, kurie prie to ateina.'),
  (@b58, 10, 2, 'Nes kitaip argi nebūtų liautasi jas atnašauti? Todėl, kad garbintojai vieną kartą apvalyti, daugiau nebeturėtų nuodėmių sąžinės?'),
  (@b58, 10, 3, 'Bet tomis aukomis kiekvienais metais yra priminimas apie nuodėmes.'),
  (@b58, 10, 4, 'Nes neįmanoma, kad jaučių bei ožių kraujas pašalintų nuodėmes.'),
  (@b58, 10, 5, 'Todėl ateidamas į pasaulį jis sako: „Tu nenorėjai aukos ir atnašos, bet man paruošei kūną;'),
  (@b58, 10, 6, 'tau nepatiko deginamosios atnašos ir aukos už nuodėmę“.'),
  (@b58, 10, 7, 'Tada tariau: „Štai ateinu (apie mane yra parašyta knygos ritinyje) vykdyti, o Dieve, tavo valios“.'),
  (@b58, 10, 8, 'Kai jis aukščiau sakė: „Tu nenorėjai aukos ir atnašos bei deginamųjų atnašų ir atnašos už nuodėmę, nei tau jos patiko“; kurios yra pagal įstatymą atnašaujamos;'),
  (@b58, 10, 9, 'tada jis tarė: „Štai ateinu vykdyti, o Dieve, tavo valios“. Jis pašalina pirma, kad įtvirtintų antra.'),
  (@b58, 10, 10, 'Ta valia esame pašvęsti per Jėzaus Kristaus kūno atnašą kartą visiems laikams.'),
  (@b58, 10, 11, 'Ir kiekvienas kunigas kasdien stovi tarnaudamas ir daug kartų atnašaudamas tas pačias aukas, kurios niekada negali pašalinti nuodėmių;'),
  (@b58, 10, 12, 'bet šis, atnašavęs vieną auką už nuodėmes amžiams, atsisėdo Dievo dešinėje;'),
  (@b58, 10, 13, 'nuo šiol laukdamas, kol jo priešai bus padaryti jo pakoju.'),
  (@b58, 10, 14, 'Nes viena atnaša jis amžiams ištobulino pašvęstuosius.'),
  (@b58, 10, 15, 'Tai mums liudija ir Šventoji Dvasia, nes po to ji buvo sakiusi:'),
  (@b58, 10, 16, '„Šita yra sandora, kurią su jais sudarysiu po tų dienų, – sako Viešpats, – aš įdėsiu savo įstatymus į jų širdis ir įrašysiu juos jų protuose;'),
  (@b58, 10, 17, 'ir jų nuodėmių bei neteisybių nebeprisiminsiu“.'),
  (@b58, 10, 18, 'Na, o kur yra jų atleidimas, ten nebėra atnašos už nuodėmę.'),
  (@b58, 10, 19, 'Todėl, broliai, turėdami drąsą įeiti į švenčiausiąją per Jėzaus kraują,'),
  (@b58, 10, 20, 'nauju ir gyvu keliu, kurį jis mums pašventė, per uždangą, tai yra, savo kūną;'),
  (@b58, 10, 21, 'ir turėdami aukščiausiąjį kunigą, vadovaujantį Dievo namams;'),
  (@b58, 10, 22, 'artinkimės su tikra širdimi, pilnu tikėjimo užtikrintumu, turėdami savo širdis apšlakstytas nuo piktos sąžinės ir mūsų kūnus nuplautus švariu vandeniu.'),
  (@b58, 10, 23, 'Tvirtai išlaikykime mūsų tikėjimo išpažinimą nesvyruodami (nes ištikimas tas, kuris pažadėjo);'),
  (@b58, 10, 24, 'ir žiūrėkime vienas kito, kad paskatintume meilei ir geriems darbams,'),
  (@b58, 10, 25, 'neapleisdami mūsų susirinkimo kartu, kaip kai kurie yra įpratę; bet ragindami vienas kitą, ir juo labiau, kai matote besiartinančią tą dieną.'),
  (@b58, 10, 26, 'Nes jei gavę tiesos pažinimą sąmoningai nusidedame, nebelieka aukos už nuodėmes,'),
  (@b58, 10, 27, 'bet kažkoks baisus laukimas teismo ir ugningo pasipiktinimo, kuris prarys priešininkus.'),
  (@b58, 10, 28, 'Kas niekino Mozės įstatymą, mirė be pasigailėjimo prie dviejų ar trijų liudytojų;'),
  (@b58, 10, 29, 'pamanykite, kiek skaudesnės bausmės bus vertas tas, kuris sutrypė po kojomis Dievo Sūnų, ir sandoros kraują, kuriuo buvo pašvęstas, palaikė nešventu dalyku ir paniekino malonės Dvasią.'),
  (@b58, 10, 30, 'Nes mes pažįstame tą, kuris pasakė: „Kerštas priklauso man, aš atmokėsiu, – sako Viešpats“. Ir vėl: „Viešpats teis savo tautą“.'),
  (@b58, 10, 31, 'Baisu įpulti į gyvojo Dievo rankas.'),
  (@b58, 10, 32, 'Bet prisiminkite ankstesnes dienas, kuriose jūs, kai buvote apšviesti, ištvėrėte didelę kentėjimų kovą;'),
  (@b58, 10, 33, 'dalinai, kai buvote išstatyti viešam reginiui per gėdą ir kentėjimus; ir dalinai, kai tapote bendrininkais tų, su kuriais buvo taip elgiamasi.'),
  (@b58, 10, 34, 'Nes užjautėte mane mano pančiuose ir džiaugsmingai priėmėte savo turto išplėšimą, žinodami savyje, kad danguje turite geresnį ir išliekantį turtą.'),
  (@b58, 10, 35, 'Todėl neatmeskite savo pasitikėjimo, kuris turi didelį atlygio atpildą.'),
  (@b58, 10, 36, 'Nes jums reikia kantrybės, kad, įvykdę Dievo valią, gautumėte, kas pažadėta.'),
  (@b58, 10, 37, 'Nes dar trumpai, ir ateis tas, kuris turi ateiti, ir neužtruks.'),
  (@b58, 10, 38, 'Teisusis gi gyvens tikėjimu; bet jei kuris atsitrauktų, mano siela nebus juo patenkinta.'),
  (@b58, 10, 39, 'Bet mes nesame iš tų, kurie atsitraukia pražūčiai; bet iš tų, kurie tiki sielos išgelbėjimui.'),
  (@b58, 11, 1, 'Na, o tikėjimas yra pagrindas to, ko viliamasi, įrodymas to, kas neregima.'),
  (@b58, 11, 2, 'Nes per jį vyresnieji įgijo gerą atsiliepimą.'),
  (@b58, 11, 3, 'Per tikėjimą suprantame, kad pasauliai buvo sutverti Dievo žodžiu, taip kad regima nebuvo padaryta iš to, kas matoma.'),
  (@b58, 11, 4, 'Per tikėjimą Abelis atnašavo Dievui pranašesnę auką negu Kainas, per kurį gavo liudijimą, kad buvo teisus, Dievui liudijant apie jo dovanas; ir per jį, būdamas miręs, tebekalba.'),
  (@b58, 11, 5, 'Per tikėjimą Henochas buvo perkeltas, kad nematytų mirties; ir nebuvo rastas, nes Dievas jį perkėlė; nes prieš jo perkėlimą jis gavo liudijimą, kad jis patiko Dievui.'),
  (@b58, 11, 6, 'Bet be tikėjimo neįmanoma jam patikti; nes ateinantysis pas Dievą, turi tikėti, kad jis yra, ir kad jis yra atlygintojas tiems, kurie uoliai jo ieško.'),
  (@b58, 11, 7, 'Per tikėjimą Nojus, Dievo perspėtas apie tai, kas dar nematoma, baimės skatinamas paruošė arką savo namų išgelbėjimui; per kurį jis pasmerkė pasaulį ir tapo paveldėtoju teisumo, kuris yra per tikėjimą.'),
  (@b58, 11, 8, 'Per tikėjimą Abraomas pakluso, kai buvo pašauktas išeiti į vietą, kurią turėsiąs gauti paveldui; ir jis išėjo, nežinodamas, kur einąs.'),
  (@b58, 11, 9, 'Per tikėjimą jis laikinai apsigyveno pažado šalyje, kaip svetimame krašte, gyvendamas padangtėse su Izaoku ir Jokūbu, to paties pažado paveldėtojais kartu su juo;'),
  (@b58, 11, 10, 'nes jis laukė miesto, turinčio pamatus, kurio statytojas ir darytojas yra Dievas.'),
  (@b58, 11, 11, 'Per tikėjimą ir pati Sara gavo galios užmegzti sėklą, ir pagimdė vaiką, būdama nebe to amžiaus, nes ji laikė ištikimu tą, kuris buvo pažadėjęs.'),
  (@b58, 11, 12, 'Todėl iš jo vieno ir beveik mirusio kilo tiek daug, kaip dangaus žvaigždžių daugybė ir kaip pajūryje esantis nesuskaičiuojamas smėlis.'),
  (@b58, 11, 13, 'Visi šitie mirė tikėjime, negavę pažadėtų dalykų, bet matę juos iš tolo, ir buvo jais įsitikinę, ir priėmė juos, ir išpažino, kad jie buvo svetimi ir keleiviai žemėje.'),
  (@b58, 11, 14, 'Nes tai kalbantys aiškiai pareiškia, kad ieško tėvynės.'),
  (@b58, 11, 15, 'Ir iš tiesų, jeigu jie būtų nusiteikę tai tėvynei, iš kurios išėjo, jie būtų turėję progą sugrįžti.'),
  (@b58, 11, 16, 'Bet dabar jie trokšta geresnės tėvynės, tai yra dangiškosios; todėl Dievas nesigėdija vadintis jų Dievu, nes jis paruošė jiems miestą.'),
  (@b58, 11, 17, 'Per tikėjimą Abraomas atnašavo Izaoką, kai buvo mėginamas; ir jis, kuris buvo gavęs pažadus, atnašavo savo viengimį sūnų,'),
  (@b58, 11, 18, 'apie kurį buvo pasakyta: „Kad Izaoke bus pašaukta tavo sėkla“,'),
  (@b58, 11, 19, 'laikydamas, kad Dievas pajėgus jį prikelti, net iš numirusiųjų, iš kur ir atgavo jį kaip pavyzdį.'),
  (@b58, 11, 20, 'Per tikėjimą Izaokas palaimino Jokūbą ir Ezavą dėl ateities.'),
  (@b58, 11, 21, 'Per tikėjimą Jokūbas mirdamas palaimino abu Juozapo sūnus; ir pagarbino, atsirėmęs į savo lazdos viršugalį.'),
  (@b58, 11, 22, 'Per tikėjimą Juozapas mirdamas paminėjo apie Izraelio vaikų išėjimą; ir davė įsakymą dėl savo kaulų.'),
  (@b58, 11, 23, 'Per tikėjimą Mozė, kai gimė, tris mėnesius buvo savo tėvų paslėptas, nes jie matė, kad jis buvo dailus vaikas; ir jie nebijojo karaliaus įsakymo.'),
  (@b58, 11, 24, 'Per tikėjimą Mozė, kai suaugo, atsisakė būti vadinamas faraono dukters sūnumi;'),
  (@b58, 11, 25, 'pasirinkdamas verčiau kentėti vargą su Dievo tauta, negu laikotarpiui mėgautis nuodėmės malonumais;'),
  (@b58, 11, 26, 'laikydamas Kristaus paniekinimą didesniais turtais nei lobiai Egipte, nes jis atsižvelgė į atlygio atpildą.'),
  (@b58, 11, 27, 'Per tikėjimą jis paliko Egiptą, nebijodamas karaliaus rūstybės, nes ištvėrė, tarsi matydamas neregimąjį.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b58, 11, 28, 'Per tikėjimą jis laikėsi Apėjimo ir kraujo šlakstymo, kad tas, kuris naikino pirmagimius, nepaliestų jų.'),
  (@b58, 11, 29, 'Per tikėjimą jie perėjo Raudonąją jūrą tarsi per sausumą; tai bandę daryti egiptiečiai buvo paskandinti.'),
  (@b58, 11, 30, 'Per tikėjimą Jericho sienos nugriuvo, kai aplink jas buvo eita septynias dienas.'),
  (@b58, 11, 31, 'Per tikėjimą paleistuvė Rahaba nepražuvo su tais, kurie netikėjo, taikingai priėmusi žvalgus.'),
  (@b58, 11, 32, 'Ir ką man daugiau pasakyti? Nes man neužtektų laiko papasakoti apie Gedeoną ir Baraką, ir Samsoną, ir Jeftą; taip pat apie Dovydą ir Samuelį, ir pranašus,'),
  (@b58, 11, 33, 'kurie per tikėjimą nugalėjo karalystes, darė teisumą, įgijo pažadus, užčiaupė liūtų nasrus,'),
  (@b58, 11, 34, 'užgesino ugnies siautėjimą, pabėgo nuo kalavijo ašmenų, iš silpnumo tapo stiprūs, tapo narsūs kovoje, privertė bėgti svetimųjų kariuomenes.'),
  (@b58, 11, 35, 'Moterys atgavo savo mirusiuosius, prikeltus gyvenimui; o kiti buvo kankinami, nepriimdami išvadavimo, kad gautų geresnį prisikėlimą;'),
  (@b58, 11, 36, 'ir kiti patyrė žiaurių pasityčiojimų ir nuplakimų išbandymą, taip, dargi pančių ir įkalinimų:'),
  (@b58, 11, 37, 'jie buvo užmėtomi akmenimis, pjaustomi pusiau, gundomi, žudomi kalaviju, klajojo aplinkui avikailiuose ir ožkenose; būdami skurde, varginami, kankinami'),
  (@b58, 11, 38, '(kurių pasaulis nebuvo vertas); jie klajojo dykumose ir kalnuose, ir urvuose bei žemės olose.'),
  (@b58, 11, 39, 'Ir tie visi, per tikėjimą įgavę gerą atsiliepimą, negavo to, kas pažadėta;'),
  (@b58, 11, 40, 'Dievui mums paruošus kai ką geresnio, kad jie be mūsų netaptų tobuli.'),
  (@b58, 12, 1, 'Todėl, kadangi ir mes esame apsupti tokio didelio liudytojų debesies, atmeskime kiekvieną apsunkinimą ir nuodėmę, kuri taip lengvai mus apninka, ir kantriai bėkime prieš mus išstatytose lenktynėse,'),
  (@b58, 12, 2, 'žiūrėdami į Jėzų, mūsų tikėjimo autorių ir užbaigėją; kuris dėl prieš jį išstatyto džiaugsmo iškentė kryžių paniekinęs gėdą ir atsisėdo Dievo sosto dešinėje.'),
  (@b58, 12, 3, 'Nes pamąstykite apie jį, iškentėjusį tokį nusidėjėlių prieštaravimą jam, kad nepailstumėte ir nenusilptumėte savo dvasioje.'),
  (@b58, 12, 4, 'Jūs dar nesipriešinote iki kraujo, kovodami prieš nuodėmę.'),
  (@b58, 12, 5, 'Ir užmiršote raginimą, kuris jums kalba kaip vaikams: „Mano sūnau, nepaniekink Viešpaties baudimo nei nenusilpk, kai esi jo baramas,'),
  (@b58, 12, 6, 'nes kurį Viešpats mylį, tą baudžia, ir plaka kiekvieną sūnų, kurį priima“.'),
  (@b58, 12, 7, 'Jei pakenčiate baudimą, Dievas elgiasi su jumis kaip su sūnumis; nes koks yra sūnus, kurio tėvas nebaudžia?'),
  (@b58, 12, 8, 'Bet jei esate be baudimo, kurio visi yra dalininkai, tada esate pavainikiai, o ne sūnūs.'),
  (@b58, 12, 9, 'Be to, turėjome mūsų kūno tėvus, kurie mus pataisydavo, ir juos gerbėme; tai ar ne juo labiau turėtume paklusti dvasių Tėvui ir gyventi?'),
  (@b58, 12, 10, 'Nes jie iš tikrųjų mus baudė kelias dienas pagal savo pačių norą; bet jis – mūsų naudai, kad būtume jo šventumo dalininkais.'),
  (@b58, 12, 11, 'Na, o joks baudimas šiuo metu neatrodo džiaugsmingas, bet liūdnas; tačiau paskui jis duoda taikų teisumo vaisių tiems, kurie per jį yra išlavinti.'),
  (@b58, 12, 12, 'Todėl pakelkite nuleistas rankas ir silpnus kelius;'),
  (@b58, 12, 13, 'ir darykite tiesius takus savo kojoms, kad nenukryptų nuo kelio tai, kas luoša; bet tai verčiau tesugyja.'),
  (@b58, 12, 14, 'Su visais sekite ramybe ir šventumu, be kurio niekas neregės Viešpaties;'),
  (@b58, 12, 15, 'stropiai žiūrėdami, kad kas nepritrūktų Dievo malonės; kad kokia kylanti kartybės šaknis jūsų nesutrikdytų, ir per ją daugelis nesusiteptų;'),
  (@b58, 12, 16, 'kad nebūtų kokio paleistuvio ar susiteršusio, kaip Ezavas, kuris už vieną valgio kąsnį pardavė savo pirmagimystės teises.'),
  (@b58, 12, 17, 'Nes žinote, kaip jis paskui, norėdamas paveldėti palaiminimą, buvo atmestas, nes nerado vietos atgailai, nors ieškojo jos rūpestingai su ašaromis.'),
  (@b58, 12, 18, 'Nes jūs neatėjote prie paliečiamo ir ugnimi degusio kalno nei prie juodumo ir tamsybės, ir audros,'),
  (@b58, 12, 19, 'ir trimito garso, ir žodžių balso, kurį girdėjusieji maldavo, kad jiems nebebūtų kalbamas žodis'),
  (@b58, 12, 20, '(nes jie negalėjo pakelti to, kas buvo įsakyta: „Ir jei nors žvėris paliestų kalną, bus užmėtytas akmenimis arba perdurtas strėle“;'),
  (@b58, 12, 21, 'ir reginys buvo toks baisus, kad Mozė tarė: „Aš be galo bijau ir drebu“);'),
  (@b58, 12, 22, 'bet atėjote prie Siono kalno ir prie gyvojo Dievo miesto, dangiškosios Jeruzalės ir prie nesuskaičiuojamos angelų minios,'),
  (@b58, 12, 23, 'prie visuotinio susirinkimo ir bažnyčios pirmagimių, įrašytų danguje, ir prie visų Teisėjo Dievo, ir prie ištobulintų teisiųjų žmonių dvasių,'),
  (@b58, 12, 24, 'ir prie Jėzaus, naujosios sandoros tarpininko, ir prie apšlakstymo kraujo, kalbančio geresnius dalykus nei Abelio kraujas.'),
  (@b58, 12, 25, 'Žiūrėkite, kad neatmestumėte to, kuris kalba. Nes jei neišvengė tie, kurie atmetė kalbantįjį žemėje, juo labiau mes neišvengsime, jei nusigręšime nuo to, kuris kalba iš dangaus,'),
  (@b58, 12, 26, 'kurio balsas anuomet drebino žemę; bet dabar jis pažadėjo, sakydamas: „Dar vieną kartą aš sudrebinsiu ne tik žemę, bet ir dangų“.'),
  (@b58, 12, 27, 'O šis žodis: „Dar vieną kartą“, nurodo pašalinimą sudrebinamų dalykų, kaip tų, kurie yra padaryti, idant pasiliktų nesudrebinami dalykai.'),
  (@b58, 12, 28, 'Todėl, gaudami nepajudinamą karalystę, turėkime malonės, kuria priimtinai tarnautume Dievui su pagarba ir dievota baime;'),
  (@b58, 12, 29, 'nes mūsų Dievas – ryjanti ugnis.'),
  (@b58, 13, 1, 'Tepasilieka broliška meilė.'),
  (@b58, 13, 2, 'Nepamirškite vaišinti ateivių, nes per tai kai kurie nežinodami pavaišino angelus.'),
  (@b58, 13, 3, 'Prisiminkite esančius pančiuose, lyg drauge supančioti; ir kenčiančius nelaimes, lyg patys būdami kūne.'),
  (@b58, 13, 4, 'Santuoka gerbiama visame, ir lova nesuteršta; bet paleistuvius ir svetimautojus teis Dievas.'),
  (@b58, 13, 5, 'Jūsų gyvensena tebūna be godumo; pasitenkinkite tuo, ką turite, nes jis sakė: „Aš niekada tavęs nepaliksiu nei tavęs atsižadėsiu“.'),
  (@b58, 13, 6, 'Taip kad galime drąsiai pasakyti: „Viešpats yra mano padėjėjas, ir aš nebijosiu to, ką žmogus man padarys“.'),
  (@b58, 13, 7, 'Prisiminkite savo vadovus, kurie kalbėjo jums Dievo žodį, kurių tikėjimu sekite, stebėdami jų gyvensenos pabaigą.'),
  (@b58, 13, 8, 'Jėzus Kristus tas pats vakar ir šiandien, ir per amžius.'),
  (@b58, 13, 9, 'Nebūkite nešiojami įvairių ir svetimų mokslų. Nes gerai, kad širdis yra sutvirtinta malone; ne valgiais, kurie nedavė naudos tiems, kurie buvo jais užsiėmę.'),
  (@b58, 13, 10, 'Mes turime aukurą, nuo kurio neturi teisės valgyti tarnaujantys padangtei.'),
  (@b58, 13, 11, 'Nes kūnai tų gyvulių, kurių kraujas aukščiausiojo kunigo įnešamas į šventovę už nuodėmę, yra sudeginami už stovyklos.'),
  (@b58, 13, 12, 'Todėl ir Jėzus, kad savo krauju pašvęstų tautą, kentėjo už vartų.'),
  (@b58, 13, 13, 'Todėl išeikime pas jį už stovyklos, nešdami jo priekaištą.'),
  (@b58, 13, 14, 'Nes čia neturime pasiliekančio miesto, bet ieškome ateisiančiojo.'),
  (@b58, 13, 15, 'Todėl per jį nuolatos atnašaukime Dievui gyriaus auką, tai yra, vaisių mūsų lūpų, dėkojančių jo vardui.'),
  (@b58, 13, 16, 'Bet nepamirškite daryti gera ir dalintis, nes tokiomis aukomis Dievas labai patenkintas.'),
  (@b58, 13, 17, 'Pakluskite savo vadovams ir būkite pavaldūs, nes jie budi dėl jūsų sielų, kaip turėsiantys duoti ataskaitą, kad jie tai darytų su džiaugsmu, o ne su širdgėla, nes tai jums nenaudinga.'),
  (@b58, 13, 18, 'Melskitės už mus, nes pasitikime turį gerą sąžinę, visame kame norintys gyventi dorai.'),
  (@b58, 13, 19, 'Bet maldauju verčiau daryti tai, kad būčiau greičiau jums sugrąžintas.'),
  (@b58, 13, 20, 'Na, o ramybės Dievas, kuris per amžinosios sandoros kraują parvedė iš numirusiųjų mūsų Viešpatį Jėzų, tą didį avių ganytoją,'),
  (@b58, 13, 21, 'tepadaro jus tobulus kiekviename gerame darbe, kad vykdytumėte jo valią, darydamas jumyse tai, kas labai patinka jo akims, per Jėzų Kristų; kuriam tebūna šlovė per amžių amžius. Amen.'),
  (@b58, 13, 22, 'Ir maldauju jus, broliai, pakęskite šį paraginimo žodį, nes parašiau jums laišką keliais žodžiais.'),
  (@b58, 13, 23, 'Žinokite, kad mūsų brolis Timotiejus yra išlaisvintas; su kuriuo, jei jis netrukus ateis, jus pamatysiu.'),
  (@b58, 13, 24, 'Sveikinkite visus savo vadovus ir visus šventuosius. Jus sveikina tie iš Italijos.'),
  (@b58, 13, 25, 'Malonė tebūna su jumis visais. Amen.'),
  (@b59, 1, 1, 'Jokūbas, Dievo ir Viešpaties Jėzaus Kristaus tarnas, dvylikai išsisklaidžiusių genčių – pasveikinimas.'),
  (@b59, 1, 2, 'Mano broliai, laikykite visa tai džiaugsmu, kai įpuolate į įvairius gundymus;'),
  (@b59, 1, 3, 'žinodami, kad jūsų tikėjimo išbandymas gamina kantrybę.'),
  (@b59, 1, 4, 'Bet tegul kantrybė turi savo tobulą darbą, kad būtumėte tobuli ir pilnume, nieko nestokojantys.'),
  (@b59, 1, 5, 'Jei kuriam iš jūsų trūksta išminties, teprašo Dievo, kuris visiems dosniai duoda ir nepriekaištauja; ir jam bus duota.'),
  (@b59, 1, 6, 'Bet teprašo tikėjimu, nei kiek nesvyruodamas. Nes svyruojantis yra panašus į vėjo varinėjamą ir blaškomą jūros bangą.'),
  (@b59, 1, 7, 'Nes tas žmogus tenegalvoja, kad ką nors gaus iš Viešpaties.'),
  (@b59, 1, 8, 'Dvejopamintis žmogus netvirtas visuose savo keliuose.'),
  (@b59, 1, 9, 'Žemos padėties brolis tesidžiaugia savo išaukštinimu,'),
  (@b59, 1, 10, 'bet turtuolis – savo nužeminimu, nes jis pranyks kaip žolės žiedas.'),
  (@b59, 1, 11, 'Nes saulė nepakyla greičiau su deginančia kaitra, bet išdžiovina žolę, ir jos žiedas nukrenta, ir jos išvaizdos grožis žūsta; taip ir turtuolis sunyks savo keliuose.'),
  (@b59, 1, 12, 'Palaimintas žmogus, kuris ištveria pagundą; nes kai bus išbandytas, jis gaus gyvenimo vainiką, kurį Viešpats pažadėjo tiems, kurie jį myli.'),
  (@b59, 1, 13, 'Nei vienas gundomas tenesako: „Aš esu Dievo gundomas“, nes Dievas negali būti pikto gundomas, ir nei vieno jis negundo;'),
  (@b59, 1, 14, 'bet kiekvienas yra gundomas, kai yra savo geismo patrauktas ir suviliotas.'),
  (@b59, 1, 15, 'Paskui pradėtas geismas pagimdo nuodėmę, o nuodėmė, kai yra užbaigta, pagimdo mirtį.'),
  (@b59, 1, 16, 'Neklyskite, mano mylimi broliai.'),
  (@b59, 1, 17, 'Kiekviena gera dovana ir kiekviena tobula dovana yra iš aukštai, ir ateina žemyn nuo šviesybių Tėvo, pas kurį nėra permainų nei pasikeitimo šešėlio.'),
  (@b59, 1, 18, 'Savo paties valia jis mus pagimdė tiesos žodžiu, kad būtume tam tikri jo sutvėrimų pirmavaisiai.'),
  (@b59, 1, 19, 'Todėl, mano mylimi broliai, kiekvienas žmogus tebūna greitas klausytis, lėtas kalbėti, lėtas rūstauti,'),
  (@b59, 1, 20, 'nes žmogaus rūstybė nedaro Dievo teisumo.'),
  (@b59, 1, 21, 'Todėl atmeskite visą nešvarumą bei piktybės gausumą ir su romumu priimkite įskiepytą žodį, kuris pajėgus išgelbėti jūsų sielas.'),
  (@b59, 1, 22, 'Bet būkite žodžio vykdytojai, o ne tik klausytojai, apgaudinėjantys save.'),
  (@b59, 1, 23, 'Nes jei kuris yra žodžio klausytojas, o ne vykdytojas, jis yra panašus į žmogų, žiūrintį į savo gimtąjį veidą veidrodyje,'),
  (@b59, 1, 24, 'nes jis pasižiūri į save ir nueina, ir bematant pamiršta, koks buvo.'),
  (@b59, 1, 25, 'Bet kas žiūri į tobulą laisvės įstatymą ir jame pasilieka, būdamas ne užmaršus klausytojas, bet darbo vykdytojas, tas bus palaimintas savo darbe.'),
  (@b59, 1, 26, 'Jei kuris tarp jūsų regisi esąs religingas ir nepažaboja savo liežuvio, bet apgaudinėja savo širdį, to religija tuščia.'),
  (@b59, 1, 27, 'Tyra ir nesuteršta religija prieš Dievą ir Tėvą yra ši: lankyti našlaičius ir našles jų varge ir laikyti save nesuteptą pasauliu.'),
  (@b59, 2, 1, 'Mano broliai, neturėkite mūsų Viešpaties Jėzaus Kristaus, šlovės Viešpaties, tikėjimo su atsižvelgimu į asmenis.'),
  (@b59, 2, 2, 'Nes jei ateina į jūsų susirinkimą žmogus su auksiniu žiedu, gražiais drabužiais ir taip pat įeina vargšas bjauriu drabužiu;'),
  (@b59, 2, 3, 'ir jūs atsižvelgiate į dėvintį puošniais drabužiais ir jam sakote: „Sėskis čia, į gerąją vietą“; o vargšui sakote: „Stovėk ten, arba sėskis čia, žemiau mano pakojo“;'),
  (@b59, 2, 4, 'argi tuomet nesate savyje šališki ir tapę piktų minčių teisėjais?'),
  (@b59, 2, 5, 'Paklausykite, mano mylimi broliai: argi Dievas neišsirinko šio pasaulio vargšų būti turtingais tikėjime ir paveldėtojais karalystės, kurią jis pažadėjo tiems, kurie jį myli?'),
  (@b59, 2, 6, 'Bet jūs paniekinote vargšą. Argi ne turtuoliai jus engia ir jus tempia prie teismo krasių?'),
  (@b59, 2, 7, 'Argi ne jie piktžodžiauja tam garbingam vardui, kuriuo jūs vadinatės?'),
  (@b59, 2, 8, 'Jei įvykdote karališkąjį įstatymą pagal Raštą: „Mylėk savo artimą kaip save“, darote gerai;'),
  (@b59, 2, 9, 'bet jei atsižvelgiate į asmenis, darote nuodėmę ir esate įstatymo įtikinti kaip nusižengėliai.'),
  (@b59, 2, 10, 'Nes kas laikosi viso įstatymo, tačiau nusižengia vienu dalyku, tas kaltas dėl visų.'),
  (@b59, 2, 11, 'Nes tas, kuris sakė: „Nesvetimauk“, taip pat sakė: „Nežudyk“. Na, o jei nesvetimauji, tačiau žudai, tampi įstatymo pažeidėju.'),
  (@b59, 2, 12, 'Taip kalbėkite ir taip darykite, kaip tie, kurie bus teisiami pagal laisvės įstatymą.'),
  (@b59, 2, 13, 'Nes teismas be gailesčio bus tam, kuris neparodė gailestingumo; o gailestingumas džiaugiasi prieš teismą.'),
  (@b59, 2, 14, 'Kokia nauda, mano broliai, jei kuris sako turįs tikėjimą, o neturi darbų? Ar tikėjimas gali jį išgelbėti?'),
  (@b59, 2, 15, 'Jei brolis ar sesuo būtų nuogi ir neturėtų kasdienio maisto,'),
  (@b59, 2, 16, 'o vienas iš jūsų jiems sakote: „Eikite ramybėje, susišildykite ir pasisotinkite“, tačiau neduodate jiems to, kas būtina kūnui, kokia iš to nauda?'),
  (@b59, 2, 17, 'Taip ir tikėjimas, jei neturi darbų, būdamas pats vienas yra miręs.'),
  (@b59, 2, 18, 'Taip, kažkas galėtų pasakyti: „Tu turi tikėjimą, o aš turiu darbus“; parodyk man savo tikėjimą be savo darbų, o aš tau parodysiu savo tikėjimą savo darbais.'),
  (@b59, 2, 19, 'Tu tiki, kad yra vienas Dievas; gerai darai: velniai irgi tiki ir dreba.'),
  (@b59, 2, 20, 'Bet ar nori žinoti, o tuščias žmogau, kad tikėjimas be darbų yra miręs?'),
  (@b59, 2, 21, 'Argi ne darbais buvo išteisintas mūsų tėvas Abraomas, kai atnašavo savo sūnų Izaoką ant aukuro?'),
  (@b59, 2, 22, 'Ar matai, kaip tikėjimas veikė su jo darbais, ir darbais tikėjimas buvo ištobulintas?'),
  (@b59, 2, 23, 'Ir išsipildė Raštas, kuris sako: „Abraomas patikėjo Dievu, ir tai jam buvo įskaityta teisumu“, ir jis buvo vadinamas Dievo Draugu.'),
  (@b59, 2, 24, 'Tad matote, kaip žmogus išteisinamas darbais, o ne vien tikėjimu.'),
  (@b59, 2, 25, 'Taip pat ir paleistuvė Rahaba, argi ne darbais buvo išteisinta, priimdama pasiuntinius ir juos kitu keliu išleidusi?'),
  (@b59, 2, 26, 'Nes kaip kūnas be dvasios yra miręs, taip ir tikėjimas be darbų yra miręs.'),
  (@b59, 3, 1, 'Mano broliai, nebūkime daugelis mokytojais, žinodami, kad gausime didesnį pasmerkimą.'),
  (@b59, 3, 2, 'Nes daug kuo mes visi nusižengiame. Jei kas nenusižengia žodžiu, tas tobulas žmogus, pajėgus sutramdyti ir visą kūną.'),
  (@b59, 3, 3, 'Štai įkišame žąslus arkliams į nasrus, kad jie mums paklustų; ir sukinėjame visą jų kūną.'),
  (@b59, 3, 4, 'Štai ir laivai, nors ir tokie dideli ir varomi smarkių vėjų, tačiau labai mažo vairo pasukami ten, kur nori valdytojas.'),
  (@b59, 3, 5, 'Taip ir liežuvis yra mažas narys, bet giriasi didžiais dalykais. Štai kokį didį dalyką padega maža ugnis!'),
  (@b59, 3, 6, 'Ir liežuvis yra ugnis, neteisybės pasaulis; toks yra liežuvis tarp mūsų narių, suteršiantis visą kūną ir padegantis prigimtinę eigą; ir yra pragaro padegtas.'),
  (@b59, 3, 7, 'Nes kiekviena rūšis žvėrių ir paukščių, ir gyvačių, ir jūros būtybių, yra sutramdoma, ir buvo žmonijos sutramdyta,'),
  (@b59, 3, 8, 'bet liežuvio negali sutramdyti joks žmogus; jis yra nesuvaldoma piktybė, pilnas mirtinų nuodų.'),
  (@b59, 3, 9, 'Juo mes laiminame Dievą, būtent Tėvą; ir juo mes keikiame žmones, kurie yra padaryti pagal Dievo panašumą.'),
  (@b59, 3, 10, 'Iš tos pačios burnos eina laiminimas ir prakeikimas. Mano broliai, tai neturėtų taip būti.'),
  (@b59, 3, 11, 'Ar šaltinis toje pačioje vietoje lieja saldų ir kartų vandenį?'),
  (@b59, 3, 12, 'Ar figmedis, mano broliai, gali nešti alyvuoges? Arba vynmedis figas? Taip ir joks šaltinis negali duoti ir sūraus, ir gėlo vandens.'),
  (@b59, 3, 13, 'Kas tarp jūsų yra išmintingas ir apdalintas pažinimu? Teparodo gera gyvensena savo darbus su išminties romumu.'),
  (@b59, 3, 14, 'Bet jei savo širdyse turite kartų pavydą ir kivirčą, nesigirkite ir nemeluokite prieš tiesą.'),
  (@b59, 3, 15, 'Ta išmintis nenusileidžia iš aukštybių, bet yra žemiška, juslinė, velniška.'),
  (@b59, 3, 16, 'Nes kur pavydas ir kivirčas, ten sumaištis ir visokie pikti darbai.'),
  (@b59, 3, 17, 'Bet išmintis, esanti iš aukštybių, pirmiausiai yra tyra, paskui taiki, švelni ir nuolaidi, pilna gailestingumo ir gerų vaisių, be šališkumo ir be veidmainystės.'),
  (@b59, 3, 18, 'O teisumo vaisius ramybėje sėjamas tų, kurie daro taiką.'),
  (@b59, 4, 1, 'Iš kur tarp jūsų karai ir kovos? Ar ne iš čia – iš jūsų geismų, kariaujančių jūsų nariuose?'),
  (@b59, 4, 2, 'Jūs geidžiate, o neturite; žudote ir trokštate turėti, o negalite įsigyti; kovojate ir kariaujate, tačiau neturite, nes neprašote.'),
  (@b59, 4, 3, 'Prašote, o negaunate, nes prašote neteisingai, kad galėtumėte tai suvartoti savo geismams.'),
  (@b59, 4, 4, 'Svetimautojai ir svetimautojos, ar nežinote, kad pasaulio draugystė yra priešiškumas Dievui? Todėl, kas nori būti pasaulio draugas, tas yra Dievo priešas.'),
  (@b59, 4, 5, 'Ar galvojate, kad Raštas veltui sako: „Ta dvasia, kuri gyvena mumyse, geidžia iki pavydo?“'),
  (@b59, 4, 6, 'Bet jis duoda daugiau malonės. Todėl jis sako: „Dievas priešinasi išdidiems, bet nuolankiems duoda malonę“.'),
  (@b59, 4, 7, 'Todėl būkite pavaldūs Dievui. Priešinkitės velniui, ir jis bėgs nuo jūsų.'),
  (@b59, 4, 8, 'Artinkitės prie Dievo, ir jis artinsis prie jūsų. Apsivalykite rankas, nusidėjėliai; ir apsivalykite širdis, dvejopaminčiai.'),
  (@b59, 4, 9, 'Kamuokitės ir gedėkite, ir verkite: jūsų juokas tepavirsta gedulu, o džiaugsmas – nusiminimu.'),
  (@b59, 4, 10, 'Nusižeminkite Viešpaties akyse, ir jis jus išaukštins.'),
  (@b59, 4, 11, 'Broliai, nekalbėkite vienas apie kitą pikto. Kas kalba pikta apie savo brolį ir teisia savo brolį, tas kalba pikta apie įstatymą ir teisia įstatymą; bet jei teisi įstatymą, tuomet nesi įstatymo vykdytojas, bet teisėjas.'),
  (@b59, 4, 12, 'Yra vienas įstatymleidys, kuris pajėgus išgelbėti ir sunaikinti; kas tu esi, kad teisi kitą?'),
  (@b59, 4, 13, 'Nagi dabar jūs, kurie sakote: „Šiandien arba rytoj eisime į tą miestą ir pasiliksime ten metus, ir pirksime bei parduosime, ir pasipelnysime“;'),
  (@b59, 4, 14, 'jūs tuo tarpu nežinote, kas bus rytoj. Nes kas yra jūsų gyvybė? Ji yra garas, kuris pasirodo trumpam laikui ir paskui išnyksta.'),
  (@b59, 4, 15, 'Vietoje to turite sakyti: „Jei Viešpats panorės, mes gyvensime ir darysime tą arba aną“.'),
  (@b59, 4, 16, 'Bet dabar džiaugiatės savo pasigyrimais; visas toks džiaugsmas yra piktas.'),
  (@b59, 4, 17, 'Todėl kas moka daryti gera, bet nedaro, tam yra nuodėmė.'),
  (@b59, 5, 1, 'Nagi dabar jūs, turtuoliai, verkite ir kaukite dėl jūsų nelaimių, kurios ateis ant jūsų.'),
  (@b59, 5, 2, 'Jūsų turtai supuvę, ir jūsų drabužiai kandžių suėsti.'),
  (@b59, 5, 3, 'Jūsų auksas ir sidabras surūdiję; ir jų rūdys bus liudijimas prieš jus, ir ės jūsų kūnus tarsi ugnis. Jūs susikrovėte lobį paskutinėms dienoms.'),
  (@b59, 5, 4, 'Štai šaukia jūsų laukus nupjovusių darbininkų užmokestis, sulaikytas jūsų per sukčiavimą; ir nupjovusiųjų šauksmai atėjo į Sabaoto Viešpaties ausis.'),
  (@b59, 5, 5, 'Jūs gyvenote žemėje malonumais ir buvote pasileidę; nupenėjote savo širdis kaip skerdimo dieną.'),
  (@b59, 5, 6, 'Jūs pasmerkėte ir nužudėte teisųjį; ir jis jums nesipriešina.'),
  (@b59, 5, 7, 'Todėl būkite kantrūs, broliai, iki Viešpaties atėjimo. Štai žemdirbys laukia brangaus žemės vaisiaus, ir dėl jo yra ilgai kantrus, kol gauna ankstyvojo ir vėlyvojo lietaus.'),
  (@b59, 5, 8, 'Būkite ir jūs kantrūs; sustiprinkite savo širdis, nes artinasi Viešpaties atėjimas.'),
  (@b59, 5, 9, 'Nelaikykite vienas prieš kitą pagiežos, broliai, kad nebūtumėte smerkiami: štai teisėjas stovi priešais duris.'),
  (@b59, 5, 10, 'Imkite, mano broliai, vargo kentėjimo ir kantrumo pavyzdžiu pranašus, kurie kalbėjo Viešpaties vardu.'),
  (@b59, 5, 11, 'Štai laikome laimingais tuos, kurie ištveria. Jūs girdėjote apie Jobo kantrybę ir matėte Viešpaties pabaigą, kad Viešpats yra labai gailestingas ir maloningo pasigailėjimo.'),
  (@b59, 5, 12, 'Bet pirmiau visko, mano broliai, neprisiekinėkite nei dangumi, nei žeme, nei jokia kita priesaika; bet jūsų „taip“ tebūna taip; ir jūsų „ne“ – ne; kad neįpultumėte į pasmerkimą.'),
  (@b59, 5, 13, 'Ar kas tarp jūsų kenčia? Tesimeldžia. Ar kas linksmas? Tegieda psalmes.'),
  (@b59, 5, 14, 'Ar kas tarp jūsų serga? Tepasikviečia bažnyčios vyresniuosius; ir jie tesimeldžia dėl jo, patepdami jį aliejumi Viešpaties vardu;'),
  (@b59, 5, 15, 'ir tikėjimo malda išgelbės sergantįjį, ir Viešpats jį pakels; ir jeigu jis padaręs nuodėmių, jos bus jam atleistos.'),
  (@b59, 5, 16, 'Išpažinkite vienas kitam savo kaltes ir melskitės vienas už kitą, kad būtumėte išgydyti. Daug naudos duoda veiksminga karšta teisiojo malda.'),
  (@b59, 5, 17, 'Elijas buvo žmogus, pavaldus panašioms aistroms kaip ir mes, ir jis uoliai meldėsi, kad nelytų, ir nelijo žemėje trejus metus ir šešis mėnesius.'),
  (@b59, 5, 18, 'Ir jis vėl meldėsi, ir dangus davė lietų, ir žemė atnešė savo vaisių.'),
  (@b59, 5, 19, 'Broliai, jei kuris iš jūsų nuklystų nuo tiesos, ir kas nors jį atverstų;'),
  (@b59, 5, 20, 'težino, kad tas, kuris atverčia nusidėjėlį nuo jo kelio paklydimo, išgelbės sielą nuo mirties ir uždengs daugybę nuodėmių.'),
  (@b60, 1, 1, 'Petras, Jėzaus Kristaus apaštalas, ateiviams, išsisklaidžiusiems Ponte, Galatijoje, Kapadokijoje, Azijoje ir Bitinijoje,'),
  (@b60, 1, 2, 'išrinktiems pagal Dievo Tėvo išankstinį žinojimą, per Dvasios pašventimą, klusnumui ir Jėzaus Kristaus kraujo apšlakstymui; tepadaugėja jums malonė ir ramybė.'),
  (@b60, 1, 3, 'Tebūna palaimintas mūsų Viešpaties Jėzaus Kristaus Dievas ir Tėvas, kuris pagal savo gausų gailestingumą mus vėl pagimdė gyvai vilčiai per Jėzaus Kristaus prisikėlimą iš numirusiųjų,'),
  (@b60, 1, 4, 'negendančiam ir nesuterštam paveldui, ir nenykstančiam, palaikytam danguje jums,'),
  (@b60, 1, 5, 'kurie esate saugomi Dievo jėga per tikėjimą išgelbėjimui, paruoštam apreikšti paskutiniu laiku.'),
  (@b60, 1, 6, 'Kuo jūs didžiai džiaugiatės, nors dabar laikotarpiui, jei reikia, esate nuliūdę per visokeriopus gundymus,'),
  (@b60, 1, 7, 'kad jūsų tikėjimo išbandymas, daug brangesnis už pragaištantį auksą, nors ir ugnimi ištirtą, būtų rastas gyriui ir garbei, ir šlovei pasirodant Jėzui Kristui;'),
  (@b60, 1, 8, 'kurį mylite nematę; nors dabar jo nematote, tačiau juo tikėdami džiaugiatės neapsakomu ir pilnu šlovės džiaugsmu,'),
  (@b60, 1, 9, 'gaudami jūsų tikėjimo pabaigą – jūsų sielų išgelbėjimą.'),
  (@b60, 1, 10, 'Apie tą išgelbėjimą teiravosi ir uoliai tyrinėjo pranašai, kurie pranašavo apie jums ateisiančią malonę;'),
  (@b60, 1, 11, 'tyrinėdami, kurį arba kokio būdo laiką nurodė juose buvusi Kristaus Dvasia, kai ji iš anksto liudijo Kristaus kentėjimus ir po jų seksiančią šlovę.'),
  (@b60, 1, 12, 'Jiems buvo atskleista, kad ne sau, bet mums jie patarnavo tai, kas dabar jums pranešta per tuos, kurie paskelbė jums evangeliją Šventąja Dvasia, pasiųsta iš dangaus; į tai trokšta pažvelgti angelai.'),
  (@b60, 1, 13, 'Todėl susijuoskite savo proto strėnas, būkite blaivūs ir iki galo tikėkitės malonės, kuri bus jums atnešta Jėzui Kristui apsireiškiant;'),
  (@b60, 1, 14, 'kaip klusnūs vaikai, neformuodami savęs pagal ankstesnius geismus, buvusius jūsų nežinojime,'),
  (@b60, 1, 15, 'bet kaip šventas yra tas, kuris jus pašaukė, taip ir jūs būkite šventi visokioje gyvensenoje;'),
  (@b60, 1, 16, 'nes yra parašyta: „Būkite šventi; nes aš esu šventas“.'),
  (@b60, 1, 17, 'Ir jei šaukiatės Tėvo, kuris neatsižvelgdamas į asmenis teisia pagal kiekvieno žmogaus darbą, su baime praleiskite čia savo viešnagės laiką;'),
  (@b60, 1, 18, 'kadangi žinote, jog nebuvote atpirkti nuo savo niekingos, iš savo tėvų per tradicijas paveldėtos, gyvensenos gendančiais dalykais – kaip auksu ir sidabru,'),
  (@b60, 1, 19, 'bet brangiu Kristaus krauju, kaip avinėlio be trūkumų ir be dėmės;'),
  (@b60, 1, 20, 'kuris iš tikrųjų buvo iš anksto paskirtas pirmiau pasaulio pamato padėjimo, bet buvo apreikštas šiais paskutiniais laikais jums,'),
  (@b60, 1, 21, 'kurie per jį tikite į Dievą, kuris prikėlė jį iš numirusiųjų ir davė jam šlovę; kad jūsų tikėjimas ir viltis būtų į Dievą.'),
  (@b60, 1, 22, 'Kadangi apvalėte savo sielas paklusdami tiesai per Dvasią neveidmainiškai brolių meilei, žiūrėkite, kad karštai mylėtumėte vienas kitą tyra širdimi,'),
  (@b60, 1, 23, 'būdami vėl gimę ne iš gendančios sėklos, bet iš negendančios, per Dievo žodį, kuris gyvena ir pasilieka per amžius.'),
  (@b60, 1, 24, 'Nes kiekvienas kūnas – kaip žolė, ir visa žmogaus šlovė – kaip žolės žiedas. Žolė sudžiūsta, ir jos žiedas nukrenta,'),
  (@b60, 1, 25, 'bet Viešpaties žodis pasilieka per amžius. Ir šitas yra žodis, kuris jums paskelbtas per evangeliją.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b60, 2, 1, 'Todėl atidėję visokią piktybę ir visokią klastą, ir veidmainystes, ir pavydus, ir visas piktas kalbas,'),
  (@b60, 2, 2, 'kaip naujai gimę kūdikiai trokškite tyro žodžio pieno, kad juo augtumėte;'),
  (@b60, 2, 3, 'jei tik paragavote, kad Viešpats maloningas.'),
  (@b60, 2, 4, 'Prie kurio ateidami, kaip prie gyvojo akmens, žmonių, tiesa, atmesto, bet Dievo išrinkto ir brangaus,'),
  (@b60, 2, 5, 'jūs irgi, kaip gyvi akmenys, esate statomi dvasiniai namai, šventa kunigystė, kad atnašautumėte dvasines aukas, priimtinas Dievui per Jėzų Kristų.'),
  (@b60, 2, 6, 'Todėl yra ir Rašte: „Štai dedu Sione pagrindinį kertinį akmenį, išrinktą, brangų; ir tas, kuris į jį tiki, nebus suglumintas“.'),
  (@b60, 2, 7, 'Todėl jums, kurie tikite, jis yra brangus; bet neklusniesiems tas akmuo, kurį statytojai atmetė, tapo kertės pagrindu'),
  (@b60, 2, 8, 'ir suklupimo akmeniu, ir papiktinimo uola, būtent tiems, kurie suklumpa ties žodžiu, būdami neklusnūs; tam jie ir buvo skirti.'),
  (@b60, 2, 9, 'Bet jūs esate išrinktoji giminė, karališka kunigystė, šventa tauta, ypatinga tauta; kad skelbtumėte gyrių to, kuris jus pašaukė iš tamsybės į savo nuostabią šviesą;'),
  (@b60, 2, 10, 'kurie praeityje nebuvote tauta, bet dabar esate Dievo tauta; kurie nebuvote įgiję gailestingumo, bet dabar įgijote gailestingumą.'),
  (@b60, 2, 11, 'Brangiai mylimi, maldauju jus kaip ateivius ir keliautojus: susilaikykite nuo kūniškų geismų, kurie kovoja prieš sielą;'),
  (@b60, 2, 12, 'būdami doros gyvensenos tarp pagonių, kad už tai, už ką apkalba jus kaip piktadarius, per jūsų gerus darbus, kuriuos matys, jie šlovintų Dievą aplankymo dienoje.'),
  (@b60, 2, 13, 'Pakluskite kiekvienam žmogaus potvarkiui Viešpaties labui: ar tai būtų karaliui, kaip aukščiausiam,'),
  (@b60, 2, 14, 'ar valdytojams, kaip jo pasiųstiems bausti piktadarius ir pagirti geradarius.'),
  (@b60, 2, 15, 'Nes tokia yra Dievo valia, kad gera darydami nutildytumėte kvailų žmonių nežinojimą;'),
  (@b60, 2, 16, 'kaip laisvi, o nesinaudojantys laisve kaip piktybės priedanga, bet kaip Dievo tarnai.'),
  (@b60, 2, 17, 'Gerbkite visus. Mylėkite broliją. Bijokite Dievo. Gerbkite karalių.'),
  (@b60, 2, 18, 'Tarnai, būkite pavaldūs savo šeimininkams su visa baime; ne tik geriems ir švelniems, bet ir atžagariems.'),
  (@b60, 2, 19, 'Nes tai verta padėkos, jei kas dėl sąžinės Dievui pakenčia sielvartą neteisėtai kentėdamas.'),
  (@b60, 2, 20, 'Nes koks gi tai yra gyrius, jei kantriai priimate, kai esate mušami už savo nusižengimus? Bet jei darydami gera ir už tai kentėdami priimate tai kantriai, tai yra priimtina Dievui.'),
  (@b60, 2, 21, 'Nes būtent tam jūs pašaukti: kadangi ir Kristus kentėjo už mus, palikdamas mums pavyzdį, kad sektumėte jo pėdomis;'),
  (@b60, 2, 22, 'kuris nepadarė nuodėmės, nei nebuvo rasta jo burnoje klastos;'),
  (@b60, 2, 23, 'kuris keikiamas neatsakė keiksmu; kentėdamas jis negrasino; bet patikėjo save tam, kuris teisiai teisia;'),
  (@b60, 2, 24, 'jis pats užnešė mūsų nuodėmes savo kūne ant medžio, kad mes, mirę nuodėmėms, gyventume teisumui – jo rėžiais jūs išgydyti.'),
  (@b60, 2, 25, 'Nes buvote kaip klaidžiojančios avys; bet dabar sugrįžote pas savo sielų Ganytoją ir Vyskupą.'),
  (@b60, 3, 1, 'Taip pat jūs, žmonos, būkite pavaldžios savo vyrams; kad, jei kurie nepaklūsta žodžiu, jie ir be žodžio būtų laimėti žmonų gyvensena;'),
  (@b60, 3, 2, 'matydami jūsų skaisčią gyvenseną, sujungtą su baime.'),
  (@b60, 3, 3, 'Jūsų pasipuošimas tenebūna išoriškas, supinant plaukus ir nešiojant auksą arba apsivelkant drabužius;'),
  (@b60, 3, 4, 'bet tai tebūna paslėptas širdies žmogus tuo, kas negenda, būtent romios ir tylios dvasios papuošalas, kuris Dievo akyse yra didelės vertės.'),
  (@b60, 3, 5, 'Nes senais laikais šitaip puošdavosi ir šventos moterys, pasitikinčios Dievu, pavaldžios savo vyrams;'),
  (@b60, 3, 6, 'kaip ir Sara pakluso Abraomui, vadindama jį viešpačiu; jūs esate jos dukterys, kol darote gera ir nebijote jokia nuostaba.'),
  (@b60, 3, 7, 'Taip pat jūs, vyrai, gyvenkite su jomis pagal pažinimą, suteikdami pagarbą žmonoms kaip silpnesniems indams ir kaip esančioms gyvenimo malonės bendrapaveldėtojoms; kad jūsų maldos nebūtų trukdomos.'),
  (@b60, 3, 8, 'Galiausiai, visi būkite vienminčiai, užjaučiantys vieni kitus, mylėkite kaip broliai, būkite gailestingi, būkite paslaugūs;'),
  (@b60, 3, 9, 'neatsilygindami piktu už pikta ar keikimu už keikimą, bet atvirkščiai, laiminimu; žinodami, kad esate tam pašaukti, kad paveldėtumėte palaiminimą.'),
  (@b60, 3, 10, 'Nes norintis mylėti gyvenimą ir matyti geras dienas, tesulaiko savo liežuvį nuo pikto ir savo lūpas, kad jos nekalbėtų klastos;'),
  (@b60, 3, 11, 'tevengia jis pikto ir daro gera; teieško ramybės ir tesiveja ją.'),
  (@b60, 3, 12, 'Nes Viešpaties akys į teisiuosius, ir jo ausys atviros jų maldoms; bet Viešpaties veidas yra prieš darančius pikta.'),
  (@b60, 3, 13, 'Ir kas gi tas, kuris jums pakenks, jei būsite sekėjai to, kas gera?'),
  (@b60, 3, 14, 'Bet jei ir kenčiate dėl teisumo, esate laimingi; ir nebijokite jų gąsdinimo nei nebūkite nerimastingi;'),
  (@b60, 3, 15, 'bet pašvęskite Viešpatį Dievą savo širdyse ir visuomet būkite pasiruošę atsakyti kiekvienam, klausiančiam jumyse esančios vilties priežasties, su romumu ir baime;'),
  (@b60, 3, 16, 'turėdami gerą sąžinę; kad tame, kame jus apkalba kaip piktadarius, susigėstų tie, kurie melagingai kaltina jūsų gerą gyvenseną Kristuje.'),
  (@b60, 3, 17, 'Nes geriau, jei tokia yra Dievo valia, kad kenčiate darydami gera, negu darydami pikta.'),
  (@b60, 3, 18, 'Nes ir Kristus vieną kartą kentėjo už nuodėmes, teisusis už neteisiuosius, kad nuvestų mus pas Dievą, būdamas numarintas kūnu, bet atgaivintas Dvasia,'),
  (@b60, 3, 19, 'kuria jis taipogi nuėjo ir skelbė kalėjime dvasioms;'),
  (@b60, 3, 20, 'kurios kadaise buvo neklusnios, kai kartą Dievo ilgas pakantumas laukė Nojaus dienomis, kol buvo ruošiama arka, kurioje keletas, tai yra, aštuonios sielos, buvo išgelbėti per vandenį.'),
  (@b60, 3, 21, 'Į kurį panašus atvaizdas – krikštas – mus irgi dabar išgelbėja (ne kūno nešvarumų pašalinimas, bet geros sąžinės atsakas Dievui) per Jėzaus Kristaus prisikėlimą,'),
  (@b60, 3, 22, 'kuris yra nuėjęs į dangų ir yra Dievo dešinėje; jam pavaldūs angelai ir valdžios, ir jėgos.'),
  (@b60, 4, 1, 'Tad kadangi Kristus kentėjo už mus kūne, taip ir jūs apsiginkluokite ta pačia mintimi; nes tas, kuris kentėjo kūne, paliovė nuodėmę;'),
  (@b60, 4, 2, 'kad likusį savo laiką kūne jis gyventų nebe žmonių geismams, bet Dievo valiai.'),
  (@b60, 4, 3, 'Nes mums pakanka mūsų gyvenimo praeityje, kad vykdėme pagonių valią, kai vaikščiojome gašlume, geismuose, vyno nesaikingume, ūžavimuose, puotavimuose ir bjauriose stabmeldystėse;'),
  (@b60, 4, 4, 'tame jie mano keista, kad nebėgate su jais į tą patį besaikį šėlsmą, kalbėdami apie jus pikta;'),
  (@b60, 4, 5, 'jie duos ataskaitą tam, kuris pasiruošęs teisti gyvuosius ir mirusiuosius.'),
  (@b60, 4, 6, 'Nes dėl to evangelija buvo paskelbta ir mirusiesiems, kad jie būtų teisiami pagal žmones kūne, bet gyventų pagal Dievą dvasioje.'),
  (@b60, 4, 7, 'Bet viso ko galas yra čia pat, todėl būkite blaivūs ir budėkite maldai.'),
  (@b60, 4, 8, 'Ir viršum visko turėkite tarpusavyje karštą meilę, nes meilė uždengs gausybę nuodėmių.'),
  (@b60, 4, 9, 'Būkite vienas kitam svetingi be pagiežos.'),
  (@b60, 4, 10, 'Kaip kiekvienas gavo dovaną, taip ta pačia tarnaukite vienas kitam, kaip geri visokeriopos Dievo malonės ūkvedžiai.'),
  (@b60, 4, 11, 'Jei kas kalba, tekalba kaip Dievo pasakymus; jei kas tarnauja, tedaro tai kaip iš pajėgumo, kurį duoda Dievas: kad Dievas visame kame būtų pašlovintas per Jėzų Kristų, kuriam tebūna gyrius ir valdžia per amžių amžius. Amen.'),
  (@b60, 4, 12, 'Mylimieji, teneatrodo svetimas tas ugningas išbandymas, kuris yra jums išbandyti, tarsi jums būtų atsitikę kažkas keisto,'),
  (@b60, 4, 13, 'bet džiaukitės, kadangi esate Kristaus kentėjimų dalininkai; kad apsireiškus jo šlovei ir jūs džiūgautumėte beribiu džiaugsmu.'),
  (@b60, 4, 14, 'Jeigu jums priekaištaujama dėl Kristaus vardo, esate laimingi; nes ant jūsų ilsisi šlovės ir Dievo Dvasia; iš jų pusės ji piktai apkalbama, bet iš jūsų pusės ji šlovinama.'),
  (@b60, 4, 15, 'Bet niekas iš jūsų tegul nekenčia kaip žmogžudys ar kaip vagis, ar kaip piktadarys, ar kaip besikišąs į kitų reikalus.'),
  (@b60, 4, 16, 'Tačiau jei kas kenčia kaip krikščionis, tegul nesigėdija; bet tešlovina dėl to Dievą.'),
  (@b60, 4, 17, 'Nes atėjęs laikas, kad teismas turi prasidėti nuo Dievo namų; ir jeigu jis pirma prasideda nuo mūsų, koks bus galas tų, kurie nepaklūsta Dievo evangelijai?'),
  (@b60, 4, 18, 'Ir jei teisusis vos ne vos išgelbėjamas, kur pasirodys bedievis ir nusidėjėlis?'),
  (@b60, 4, 19, 'Todėl kenčiantys pagal Dievo valią tepatiki jam savo sielų saugojimą kaip ištikimam Sutvėrėjui, darydami gera.'),
  (@b60, 5, 1, 'Tarp jūsų esančius vyresniuosius raginu aš, kuris irgi esu vyresnysis ir Kristaus kentėjimų liudytojas, ir taip pat dalininkas šlovės, kuri bus apreikšta:'),
  (@b60, 5, 2, 'ganykite Dievo kaimenę, esančią tarp jūsų, prižiūrėdami ją ne iš prievartos, bet noriai; ne dėl nešvaraus pelno, bet iš pasirengimo;'),
  (@b60, 5, 3, 'ir ne kaip viešpataujantys Dievo paveldui, bet būdami pavyzdžiais kaimenei.'),
  (@b60, 5, 4, 'Ir kai pasirodys vyriausiasis Ganytojas, gausite nenykstantį šlovės vainiką.'),
  (@b60, 5, 5, 'Taip pat jūs, jaunesnieji, būkite pavaldūs vyresniesiems. Taip, visi būkite vienas kitam paklusnūs ir būkite apsivilkę nuolankumu; nes Dievas priešinasi išdidiems ir duoda malonę nusižeminusiems.'),
  (@b60, 5, 6, 'Todėl nusižeminkite po galinga Dievo ranka, kad jis jus išaukštintų tinkamu laiku;'),
  (@b60, 5, 7, 'užmesdami ant jo visą savo rūpestį; nes jis rūpinasi jumis.'),
  (@b60, 5, 8, 'Būkite blaivūs, būkite budrūs; nes jūsų priešininkas velnias kaip riaumojantis liūtas vaikšto aplinkui, ieškodamas, kurį galėtų praryti;'),
  (@b60, 5, 9, 'jam priešinkitės tvirti tikėjime, žinodami, kad tokie patys kentėjimai įvyksta jūsų broliuose, esančiuose pasaulyje.'),
  (@b60, 5, 10, 'Bet visos malonės Dievas, kuris pašaukė mus į savo amžinąją šlovę per Kristų Jėzų, trumpai pakentėjusius jus tepadaro tobulus, sutvirtina, sustiprina, užtikrina.'),
  (@b60, 5, 11, 'Jam tebūna šlovė ir valdžia per amžių amžius. Amen.'),
  (@b60, 5, 12, 'Per Silvaną, jums ištikimą brolį, kaip manau, trumpai parašiau, ragindamas ir liudydamas, kad tai yra tikra Dievo malonė, kurioje stovite.'),
  (@b60, 5, 13, 'Jus sveikina bažnyčia, esanti Babilone, išrinkta drauge su jumis; sveikina ir mano sūnus Morkus.'),
  (@b60, 5, 14, 'Sveikinkite vienas kitą meilės pabučiavimu. Ramybė tebūna su jumis visais, esančiais Kristuje Jėzuje. Amen.'),
  (@b61, 1, 1, 'Simonas Petras, Jėzaus Kristaus tarnas ir apaštalas, tiems, kurie su mumis gavo tokį pat brangų tikėjimą per Dievo ir mūsų Gelbėtojo Jėzaus Kristaus teisumą:'),
  (@b61, 1, 2, 'malonė ir ramybė tepadaugėja jums per Dievo ir Jėzaus, mūsų Viešpaties, pažinimą.'),
  (@b61, 1, 3, 'Pagal tai, kaip jo dieviška jėga davė mums visa, kas priklauso gyvenimui ir dievotumui, per pažinimą to, kuris pašaukė mus į šlovę ir dorybę;'),
  (@b61, 1, 4, 'kuo mums yra duoti be galo dideli ir brangūs pažadai, kad per tuos būtumėte dieviškos prigimties dalininkai, pabėgę nuo sugedimo, esančio pasaulyje per geismą.'),
  (@b61, 1, 5, 'Ir šalia to, pateikdami visą stropumą, pridėkite prie savo tikėjimo dorybę; o prie dorybės – pažinimą;'),
  (@b61, 1, 6, 'o prie pažinimo – susivaldymą; o prie susivaldymo – kantrybę; o prie kantrybės – dievotumą;'),
  (@b61, 1, 7, 'o prie dievotumo – brolišką gerumą; o prie broliško gerumo – meilę.'),
  (@b61, 1, 8, 'Nes jei šitie dalykai yra jumyse ir gausėja, jie padarys, kad nebūsite nei bergždi, nei bevaisiai mūsų Viešpaties Jėzaus Kristaus pažinime.'),
  (@b61, 1, 9, 'Bet tas, kuriam tų dalykų trūksta, yra aklas ir negali toli matyti, ir yra užmiršęs, kad buvo apvalytas nuo savo senų nuodėmių.'),
  (@b61, 1, 10, 'Todėl, broliai, juo labiau stenkitės daryti savo pašaukimą ir išrinkimą tvirtus; nes jei tai darote, niekada nepargriūsite;'),
  (@b61, 1, 11, 'nes taip gausiai jums bus parūpintas įėjimas į amžinąją mūsų Viešpaties ir Gelbėtojo Jėzaus Kristaus karalystę.'),
  (@b61, 1, 12, 'Todėl nebūsiu aplaidus visada jums apie tai priminti, nors tai žinote ir esate sutvirtinti dabartinėje tiesoje.'),
  (@b61, 1, 13, 'Taip, manau tinka, kol esu šioje padangtėje, jus žadinti jums primenant;'),
  (@b61, 1, 14, 'žinant, kad netrukus turėsiu nusiimti šią savo padangtę, kaip ir man parodė mūsų Viešpats Jėzus Kristus.'),
  (@b61, 1, 15, 'Dar daugiau, stengsiuosi, kad po mano galo visada galėtumėte turėti šiuos dalykus atmintyje.'),
  (@b61, 1, 16, 'Nes mes nesekėme gudriai sugalvotomis pasakomis, kai jums davėme pažinti mūsų Viešpaties Jėzaus Kristaus jėgą ir atėjimą, bet buvome jo didybės liudininkai, matę akimis.'),
  (@b61, 1, 17, 'Nes jis iš Dievo Tėvo gavo garbę ir šlovę, kai iš tobulos šlovės jam atėjo toks balsas: „Šitas yra mano mylimasis Sūnus, kuriuo aš labai patenkintas“.'),
  (@b61, 1, 18, 'Ir šitą balsą, atėjusį iš dangaus, mes girdėjome būdami su juo šventame kalne.'),
  (@b61, 1, 19, 'Taip pat mes turime patikimesnį pranašystės žodį; gerai darote kreipdami į jį dėmesį, kaip į žibintą, šviečiantį tamsioje vietoje, kol išauš diena, ir dienos žvaigždė patekės jūsų širdyse;'),
  (@b61, 1, 20, 'pirmiausiai žinodami tai, kad jokia Rašto pranašystė nėra iš jokio asmeniško aiškinimo.'),
  (@b61, 1, 21, 'Nes pranašystė senais laikais neatėjo žmogaus valia, bet šventi Dievo žmonės kalbėjo, kaip jie buvo judinami Šventosios Dvasios.'),
  (@b61, 2, 1, 'Bet buvo tautoje ir netikrų pranašų, kaip ir tarp jūsų bus netikrų mokytojų, kurie slapta įves smerkiamų erezijų, netgi išsigindami juos nupirkusio Viešpaties, ir užsitrauks greitą pražūtį.'),
  (@b61, 2, 2, 'Ir daugelis seks jų pražūtingais keliais; per juos bus piktžodžiaujama tiesos keliui.'),
  (@b61, 2, 3, 'Ir per godumą apsimestiniais žodžiais jie prekiaus jumis; jų teismas jau seniai neužtrunka ir jų pasmerkimas nesnaudžia.'),
  (@b61, 2, 4, 'Nes jei Dievas nepagailėjo nusidėjusių angelų, bet numetė juos žemyn į pragarą ir atidavė į tamsybės grandines, kad būtų laikomi teismui;'),
  (@b61, 2, 5, 'ir nepagailėjo senojo pasaulio, bet išgelbėjo aštuntąjį asmenį Nojų, teisumo skelbėją, užleisdamas tvaną ant bedievių pasaulio;'),
  (@b61, 2, 6, 'ir, paversdamas Sodomos bei Gomoros miestus pelenais, pasmerkė juos nuvertimu, padarydamas juos pavyzdžiu tiems, kurie po to gyvens bedieviškai;'),
  (@b61, 2, 7, 'ir išgelbėjo teisųjį Lotą, apmaudaujantį nuo ištvirkusios nedorėlių gyvensenos'),
  (@b61, 2, 8, '(nes tas teisusis, gyvendamas tarp jų, matydamas ir girdėdamas, diena iš dienos maudino savo teisią sielą jų neteisėtais darbais);'),
  (@b61, 2, 9, 'Viešpats žino kaip išvaduoti dievotuosius nuo pagundų ir išlaikyti neteisiuosius teismo dienai, kad būtų baudžiami;'),
  (@b61, 2, 10, 'bet ypač tuos, kurie vaikšto paskui kūną nešvarumo geisme ir niekina valdžią. Jie įžūlūs, savavaliai, nebijantys piktžodžiauti aukštiesiems.'),
  (@b61, 2, 11, 'Tuo tarpu angelai, esantys didesni jėga ir galybe, neatneša prieš juos keikiančio kaltinimo Viešpaties akivaizdon.'),
  (@b61, 2, 12, 'Bet šitie, kaip prigimtiniai neprotingi gyvuliai, gimę sugavimui ir sunaikinimui, piktžodžiauja tam, ko nesupranta; ir visiškai pražus savo sugedime;'),
  (@b61, 2, 13, 'ir gaus neteisumo atlygį kaip tie, kurie laiko malonumu ūžauti dienos metu. Dė̃mės jie yra ir ydos, pramogaudami savo pačių klaidinimais, puotaudami su jumis;'),
  (@b61, 2, 14, 'turėdami akis pilnas svetimavimo ir negalinčias liautis nuo nuodėmės; suviliojantys netvirtas sielas; jie turi širdį, išlavintą godumo pratybomis; prakeikti vaikai,'),
  (@b61, 2, 15, 'palikę teisingąjį kelią ir nuklydę sekdami Bosoro sūnaus Balaamo keliu, kuris pamilo neteisumo užmokestį;'),
  (@b61, 2, 16, 'bet buvo pabartas dėl savo neteisybės: nebylus asilas, kalbantis žmogaus balsu, uždraudė pranašo beprotystę.'),
  (@b61, 2, 17, 'Šitie yra bevandeniai šaltiniai, audros nešiojami debesys; kuriems yra laikoma tamsybės migla per amžius.'),
  (@b61, 2, 18, 'Nes kai jie kalba didžius išpūstus tuštybės žodžius, jie per kūno geismus, per daugelį ištvirkavimų privilioja tuos, kurie buvo visiškai pabėgę nuo gyvenančių paklydime.'),
  (@b61, 2, 19, 'Jie žada jiems laisvę, patys būdami sugedimo tarnai; nes kurio kas yra nugalėtas, to paties yra pavergiamas.'),
  (@b61, 2, 20, 'Nes jei pabėgę nuo pasaulio teršalų per Viešpaties ir Gelbėtojo Jėzaus Kristaus pažinimą, jie ir vėl į juos yra įsivėlę ir nugalėti, tai jų paskutinysis galas yra blogesnis nei pradžia.'),
  (@b61, 2, 21, 'Nes jiems geriau būtų buvę nepažinti teisumo kelio, negu jį pažinus nusigręžti nuo jiems duoto šventojo įsakymo.'),
  (@b61, 2, 22, 'Bet jiems atsitiko pagal teisingą patarlę: „Šuo sugrįžo prie savo vėmalo; ir nuplauta kiaulė – prie voliojimosi purvyne“.'),
  (@b61, 3, 1, 'Mylimieji, šį antrąjį laišką dabar jums rašau; šiuose abiejuose priminimu žadinu jūsų tyras mintis,'),
  (@b61, 3, 2, 'kad prisimintumėte anksčiau per šventuosius pranašus kalbėtus žodžius ir įsakymą mūsų – Viešpaties ir Gelbėtojo apaštalų;'),
  (@b61, 3, 3, 'žinodami pirmiausia tai, kad paskutinėmis dienomis ateis pašaipūnai, vaikščiojantys pagal savo pačių geismus'),
  (@b61, 3, 4, 'ir sakantys: „Kur yra jo atėjimo pažadas? Nes nuo to laiko, kai užmigo tėvai, visa pasilieka, kaip buvo nuo sutvėrimo pradžios“.'),
  (@b61, 3, 5, 'Nes jie noriai yra nežinantys apie tai, kad Dievo žodžiu dangūs buvo nuo seno ir žemė, stovinti iš vandens ir vandenyje,'),
  (@b61, 3, 6, 'kuriuo žuvo tuometinis pasaulis, užtvindytas vandeniu,'),
  (@b61, 3, 7, 'bet dabartiniai dangūs ir žemė tuo pačiu žodžiu yra taupomi, laikomi ugniai teismo dienai ir bedievių žmonių pražūčiai.'),
  (@b61, 3, 8, 'Bet, mylimieji, nebūkite nežinantys šio vieno dalyko, kad viena diena pas Viešpatį yra kaip tūkstantis metų, ir tūkstantis metų kaip viena diena.'),
  (@b61, 3, 9, 'Viešpats nėra lėtas dėl savo pažado, kaip kai kurie laiko lėtumu; bet yra ilgai pakantus mums, nenorėdamas, kad kuris pražūtų, bet kad visi ateitų į atgailą.'),
  (@b61, 3, 10, 'Bet Viešpaties diena ateis kaip vagis naktį; kurioje dangūs praeis su dideliu triukšmu, ir elementai sutirps iš didelio karščio, taipogi žemė ir joje esantys darbai bus sudeginti.'),
  (@b61, 3, 11, 'Tad kadangi visa tai suirs, tai kokie jūs turėtumėte būti visokia šventa gyvensena ir dievotumu,'),
  (@b61, 3, 12, 'laukdami ir skubindamiesi atėjimui Dievo dienos, kurioje dangūs degdami suirs, ir elementai ištirps iš didelio karščio?'),
  (@b61, 3, 13, 'Tačiau pagal jo pažadą laukiame naujų dangų ir naujos žemės, kuriuose gyvena teisumas.'),
  (@b61, 3, 14, 'Todėl, mylimieji, kadangi laukiate šito, stenkitės, kad būtumėte jo rasti taikoje, be dėmės ir nepriekaištingi.'),
  (@b61, 3, 15, 'Ir mūsų Viešpaties ilgą pakantumą laikykite išgelbėjimu; kaip ir mūsų mylimas brolis Paulius jums parašė pagal jam duotą išmintį;'),
  (@b61, 3, 16, 'kaip ir visuose savo laiškuose, kalbėdamas juose apie tuos dalykus; kuriuose yra sunkiai suprantamų dalykų, kuriuos nemokytieji ir netvirti iškreipia, kaip ir kitus Raštus, savo pačių pražūčiai.'),
  (@b61, 3, 17, 'Todėl jūs, mylimieji, kadangi iš anksto tai žinote, saugokitės, kad ir jūs, nedorėlių nuklydimo nuvesti, nenupultumėte nuo savo tvirtumo.'),
  (@b61, 3, 18, 'Bet aukite malonėje ir pažinime mūsų Viešpaties ir Gelbėtojo Jėzaus Kristaus. Jam tebūna šlovė ir dabar, ir per amžius. Amen.'),
  (@b62, 1, 1, 'Tai, kas buvo nuo pradžios, ką girdėjome, ką matėme savo akimis, ką stebėjome ir ką lietė mūsų rankos, apie gyvenimo Žodį'),
  (@b62, 1, 2, '(nes gyvenimas pasirodė, ir mes jį matėme, ir liudijame, ir skelbiame jums tą amžiną gyvenimą, kuris buvo pas Tėvą ir pasirodė mums);'),
  (@b62, 1, 3, 'tai, ką matėme ir girdėjome, skelbiame jums, kad ir jūs turėtumėte bendrystę su mumis; ir tikrai mūsų bendrystė yra su Tėvu ir su jo Sūnumi Jėzumi Kristumi.'),
  (@b62, 1, 4, 'Ir tai jums rašome, kad jūsų džiaugsmas būtų pilnas.'),
  (@b62, 1, 5, 'Tad ši yra žinia, kurią iš jo išgirdome ir jums skelbiame, kad Dievas yra šviesa, ir jame visiškai nėra tamsos.'),
  (@b62, 1, 6, 'Jei sakome, kad turime bendrystę su juo, o vaikštome tamsoje, meluojame ir nedarome tiesos;'),
  (@b62, 1, 7, 'bet jei vaikštome šviesoje, kaip jis yra šviesoje, turime bendrystę vienas su kitu, ir jo Sūnaus Jėzaus Kristaus kraujas apvalo mus nuo visos nuodėmės.'),
  (@b62, 1, 8, 'Jei sakome, kad neturime nuodėmės, apgaudinėjame save, ir nėra mumyse tiesos.'),
  (@b62, 1, 9, 'Jei išpažįstame savo nuodėmes, jis ištikimas ir teisingas, kad mums atleistų nuodėmes ir apvalytų mus nuo viso neteisumo.'),
  (@b62, 1, 10, 'Jei sakome, kad nenusidėjome, darome jį melagiu, ir nėra mumyse jo žodžio.'),
  (@b62, 2, 1, 'Mano vaikeliai, tai jums rašau, kad nenusidėtumėte. O jei kas nusidėtų, mes turime užtarėją pas Tėvą, Jėzų Kristų, teisųjį;'),
  (@b62, 2, 2, 'ir jis yra numaldymas už mūsų nuodėmes; ir ne vien už mūsų, bet ir už viso pasaulio nuodėmes.'),
  (@b62, 2, 3, 'Ir tuo žinome, kad jį pažįstame, jei laikomės jo įsakymų.'),
  (@b62, 2, 4, 'Kas sako: „Aš jį pažįstu“, bet nesilaiko jo įsakymų, yra melagis, ir nėra jame tiesos.'),
  (@b62, 2, 5, 'Bet kas laikosi jo žodžio, tame iš tiesų Dievo meilė yra ištobulinta: tuo žinome, kad esame jame.'),
  (@b62, 2, 6, 'Kas sako pasiliekąs jame, tas turi ir pats taip vaikščioti, kaip ir jis vaikščiojo.'),
  (@b62, 2, 7, 'Broliai, rašau jums ne naują įsakymą, bet seną įsakymą, kurį turėjote nuo pradžios. Senasis įsakymas yra žodis, kurį girdėjote nuo pradžios.'),
  (@b62, 2, 8, 'Vėlgi, naują įsakymą jums rašau, kuris yra tikras jame ir jumyse, nes tamsa praėjo, ir tikroji šviesa jau šviečia.'),
  (@b62, 2, 9, 'Kas sako esąs šviesoje, o nekenčia savo brolio, tas yra tamsoje iki šiol.'),
  (@b62, 2, 10, 'Kas myli savo brolį, pasilieka šviesoje, ir nėra jame progos suklupti.'),
  (@b62, 2, 11, 'Bet kas nekenčia savo brolio, yra tamsoje ir vaikšto tamsoje, ir nežino, kur eina, nes tamsa apakino jo akis.'),
  (@b62, 2, 12, 'Rašau jums, vaikeliai, nes jūsų nuodėmės jums yra atleistos dėl jo vardo.'),
  (@b62, 2, 13, 'Rašau jums, tėvai, nes esate pažinę tą, kuris yra nuo pradžios. Rašau jums, jaunuoliai, nes nugalėjote tą nedorėlį. Rašau jums, vaikeliai, nes esate pažinę Tėvą.'),
  (@b62, 2, 14, 'Parašiau jums, tėvai, nes esate pažinę tą, kuris yra nuo pradžios. Parašiau jums, jaunuoliai, nes esate stiprūs, ir Dievo žodis pasilieka jumyse, ir jūs nugalėjote tą nedorėlį.'),
  (@b62, 2, 15, 'Nemylėkite pasaulio nei to, kas pasaulyje. Jei kas myli pasaulį, nėra jame Tėvo meilės.'),
  (@b62, 2, 16, 'Nes visa, kas pasaulyje – kūno geismas ir akių geismas, ir gyvenimo išdidumas – nėra iš Tėvo, bet yra iš pasaulio.'),
  (@b62, 2, 17, 'O pasaulis praeina ir jo geismas; bet kas vykdo Dievo valią, pasilieka per amžius.'),
  (@b62, 2, 18, 'Vaikeliai, tai paskutinis laikas; ir kaip girdėjote, kad ateis Antikristas, būtent dabar yra daug antikristų; tuo žinome, kad yra paskutinis laikas.'),
  (@b62, 2, 19, 'Jie išėjo iš mūsų, bet jie nebuvo iš mūsų; nes jeigu jie būtų buvę iš mūsų, jie be abejo būtų pasilikę su mumis; bet jie išėjo, kad išaiškėtų, jog jie ne visi buvo iš mūsų.'),
  (@b62, 2, 20, 'Bet jūs turite patepimą nuo Šventojo ir viską žinote.'),
  (@b62, 2, 21, 'Parašiau jums ne todėl, kad nežinote tiesos, bet todėl, kad ją žinote, ir kad iš tiesos nėra melo.'),
  (@b62, 2, 22, 'Kas yra melagis, jei ne tas, kuris neigia, kad Jėzus yra Kristus? Tas yra Antikristas, kuris neigia Tėvą ir Sūnų.'),
  (@b62, 2, 23, 'Kas neigia Sūnų, tas neturi Tėvo; (bet) kas pripažįstą Sūnų, turi ir Tėvą.'),
  (@b62, 2, 24, 'Todėl tepasilieka jumyse tai, ką girdėjote nuo pradžios. Jei tai, ką girdėjote nuo pradžios, pasiliks jumyse, tai ir jūs pasiliksite Sūnuje ir Tėve.'),
  (@b62, 2, 25, 'Ir šitas yra pažadas, kurį jis mums pažadėjo, būtent amžinasis gyvenimas.'),
  (@b62, 2, 26, 'Parašiau tai jums apie tuos, kurie jus suvedžioja.'),
  (@b62, 2, 27, 'Bet patepimas, kurį iš jo gavote, pasilieka jumyse, ir jums nereikia, kad kas jus mokytų; bet kaip tas patepimas jus visko moko ir yra tiesa, o ne melas, ir kaip jis jus išmokė, jūs jame pasiliksite.'),
  (@b62, 2, 28, 'O dabar, vaikeliai, pasilikite jame; kad, kai jis pasirodys, turėtume pasitikėjimo ir nebūtume prieš jį sugėdinti jo atėjime.'),
  (@b62, 2, 29, 'Jei žinote, kad jis teisus, žinote, kad kiekvienas, kuris daro teisumą, yra iš jo gimęs.'),
  (@b62, 3, 1, 'Žiūrėkite, kokią meilę mums yra davęs Tėvas, kad būtume vadinami Dievo sūnumis; pasaulis todėl mūsų nepažįsta, nes nepažino jo.'),
  (@b62, 3, 2, 'Mylimieji, dabar esame Dievo sūnūs, bet dar nepasirodo, kas būsime; tačiau žinome, kad, kai jis pasirodys, mes būsime kaip jis; nes jį pamatysime, koks jis yra.'),
  (@b62, 3, 3, 'Ir kiekvienas, turintis šią viltį jame, ištyrina save, kaip ir jis yra tyras.'),
  (@b62, 3, 4, 'Kas daro nuodėmę, tas pažeidžia ir įstatymą, nes nuodėmė yra įstatymo pažeidimas.'),
  (@b62, 3, 5, 'Ir žinote, kad jis pasirodė, kad pašalintų mūsų nuodėmes; ir jame nėra nuodėmės.'),
  (@b62, 3, 6, 'Kas pasilieka jame, tas nenusideda; kas nusideda, tas nėra jo matęs nei jo pažinęs.'),
  (@b62, 3, 7, 'Vaikeliai, niekas jūsų tenesuklaidina; kas daro teisumą, tas yra teisus, kaip ir jis yra teisus.'),
  (@b62, 3, 8, 'Kas daro nuodėmę, yra iš velnio; nes velnias nusideda nuo pradžios. Dėl to pasirodė Dievo Sūnus, kad sunaikintų velnio darbus.'),
  (@b62, 3, 9, 'Kas gimęs iš Dievo, tas nedaro nuodėmės, nes jo sėkla pasilieka jame; ir jis negali nusidėti, nes yra gimęs iš Dievo.'),
  (@b62, 3, 10, 'Tame išaiškėja Dievo vaikai ir velnio vaikai: kas nedaro teisumo, tas nėra iš Dievo, nei tas, kuris nemyli savo brolio.'),
  (@b62, 3, 11, 'Nes šita yra žinia, kurią girdėjote nuo pradžios, kad mylėtume vienas kitą.'),
  (@b62, 3, 12, 'Ne kaip Kainas, kuris buvo iš to nedorėlio ir nužudė savo brolį. Ir kodėl jį nužudė? Kadangi jo darbai buvo pikti, o jo brolio – teisūs.'),
  (@b62, 3, 13, 'Nesistebėkite, mano broliai, jei pasaulis jūsų nekenčia.'),
  (@b62, 3, 14, 'Mes žinome, kad perėjome iš mirties į gyvenimą, nes mylime brolius. Kas nemyli savo brolio, tas pasilieka mirtyje.'),
  (@b62, 3, 15, 'Kiekvienas, nekenčiantis savo brolio, yra žmogžudys; o jūs žinote, kad žmogžudys neturi jame pasiliekančio amžinojo gyvenimo.'),
  (@b62, 3, 16, 'Tuo suprantame Dievo meilę, nes jis už mus paguldė savo gyvybę; ir mes turime guldyti savo gyvybes už brolius.'),
  (@b62, 3, 17, 'Bet kas turi šio pasaulio gėrybių ir mato savo brolį stokojantį, ir jam užrakina savo užuojautos vidurius, kaipgi jame gyvena Dievo meilė?'),
  (@b62, 3, 18, 'Mano vaikeliai, nemylėkime žodžiu nei liežuviu, bet darbu ir tiesa.'),
  (@b62, 3, 19, 'Ir tuo žinome, kad esame iš tiesos, ir jo akivaizdoje užtikrinsime savo širdis.'),
  (@b62, 3, 20, 'Nes jei mūsų širdis mus smerkia, Dievas yra didesnis už mūsų širdį ir viską žino.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b62, 3, 21, 'Mylimieji, jei mūsų širdis mūsų nesmerkia, tuomet turime pasitikėjimą Dievo link.'),
  (@b62, 3, 22, 'Ir ko beprašome, iš jo gauname, nes laikomės jo įsakymų ir darome tai, kas patinkama jo akyse.'),
  (@b62, 3, 23, 'Ir šitas yra jo įsakymas: kad tikėtume į jo Sūnaus Jėzaus Kristaus vardą ir mylėtume vienas kitą, kaip jis davė mums įsakymą.'),
  (@b62, 3, 24, 'Ir kas laikosi jo įsakymų, gyvena jame, ir jis jame. Ir tuo žinome, kad jis pasilieka mumyse – per Dvasią, kurią jis mums yra davęs.'),
  (@b62, 4, 1, 'Mylimieji, netikėkite kiekviena dvasia, bet ištirkite dvasias, ar jos iš Dievo, nes daug netikrų pranašų yra išėjusių į pasaulį.'),
  (@b62, 4, 2, 'Tuo pažinkite Dievo Dvasią: kiekviena dvasia, kuri išpažįsta, kad Jėzus Kristus atėjo kūne, yra iš Dievo,'),
  (@b62, 4, 3, 'o kiekviena dvasia, kuri neišpažįsta, kad Jėzus Kristus atėjo kūne, nėra iš Dievo; ir šita yra ta Antikristo dvasia, apie kurią girdėjote, kad ji turi ateiti; ir būtent jau dabar ji yra pasaulyje.'),
  (@b62, 4, 4, 'Jūs esate iš Dievo, vaikeliai, ir nugalėjote juos; nes tas, kuris yra jumyse, didesnis už tą, kuris yra pasaulyje.'),
  (@b62, 4, 5, 'Jie yra iš pasaulio, todėl kalba iš pasaulio, ir pasaulis jų klausosi.'),
  (@b62, 4, 6, 'Mes esame iš Dievo; kas pažįsta Dievą, klausosi mūsų; kas nėra iš Dievo, mūsų nesiklauso. Tuo pažįstame tiesos dvasią ir klaidos dvasią.'),
  (@b62, 4, 7, 'Mylimieji, mylėkime vienas kitą, nes meilė yra iš Dievo; ir kiekvienas, kuris myli, yra gimęs iš Dievo ir pažįsta Dievą.'),
  (@b62, 4, 8, 'Kas nemyli, tas nepažįsta Dievo; nes Dievas yra meilė.'),
  (@b62, 4, 9, 'Tame mums buvo apreikšta Dievo meilė, nes Dievas siuntė į pasaulį savo viengimį Sūnų, kad per jį gyventume.'),
  (@b62, 4, 10, 'Tame yra meilė, ne kad mes pamilome Dievą, bet kad jis mus pamilo ir siuntė savo Sūnų būti numaldymu už mūsų nuodėmes.'),
  (@b62, 4, 11, 'Mylimieji, jei Dievas taip mus pamilo, tai ir mes turime mylėti vienas kitą.'),
  (@b62, 4, 12, 'Niekas niekados nėra matęs Dievo. Jei mylime vienas kitą, Dievas gyvena mumyse, ir jo meilė yra ištobulinta mumyse.'),
  (@b62, 4, 13, 'Tuo žinome, kad gyvename jame ir jis mumyse, nes jis mums yra davęs iš savo Dvasios.'),
  (@b62, 4, 14, 'Ir mes matėme ir liudijame, kad Tėvas siuntė Sūnų būti pasaulio Gelbėtoju.'),
  (@b62, 4, 15, 'Kas išpažins, kad Jėzus yra Dievo Sūnus, tame gyvena Dievas, ir jis Dieve.'),
  (@b62, 4, 16, 'Ir mes pažinome ir įtikėjome meile, kurios Dievas turi mūsų link. Dievas yra meilė; ir kas gyvena meilėje, gyvena Dieve, ir Dievas jame.'),
  (@b62, 4, 17, 'Tame mūsų meilė yra padaryta tobula, kad turėtume drąsos teismo dieną; nes koks yra jis, tokie ir mes esame šiame pasaulyje.'),
  (@b62, 4, 18, 'Meilėje nėra baimės; bet tobula meilė išvaro baimę, nes baimė turi kančią. Tas, kas bijo, nėra padarytas tobulu meilėje.'),
  (@b62, 4, 19, 'Mes mylime jį, nes jis pirmas mus pamilo.'),
  (@b62, 4, 20, 'Jei kas sako: „Aš myliu Dievą“, o nekenčia savo brolio, tas yra melagis; nes kas nemyli savo brolio, kurį yra matęs, kaipgi gali mylėti Dievą, kurio nėra matęs?'),
  (@b62, 4, 21, 'Ir šitą įsakymą turime iš jo, kad: Tas, kuris myli Dievą, myli ir savo brolį.'),
  (@b62, 5, 1, 'Kas tiki, kad Jėzus yra Kristus, tas yra gimęs iš Dievo; ir kiekvienas, kuris myli gimdytoją, myli ir iš jo pagimdytąjį.'),
  (@b62, 5, 2, 'Tuo žinome, kad mylime Dievo vaikus, kai mylime Dievą ir laikomės jo įsakymų.'),
  (@b62, 5, 3, 'Nes tai yra Dievo meilė, kad laikomės jo įsakymų; o jo įsakymai nėra sunkūs.'),
  (@b62, 5, 4, 'Nes kas yra gimęs iš Dievo, nugali pasaulį; ir ši yra pergalė, nugalinti pasaulį, būtent mūsų tikėjimas.'),
  (@b62, 5, 5, 'Kas yra nugalintis pasaulį, jei ne tas, kuris tiki, kad Jėzus yra Dievo Sūnus?'),
  (@b62, 5, 6, 'Tai yra tas, kuris atėjo per vandenį ir kraują, būtent Jėzus Kristus; ne vien per vandenį, bet per vandenį ir kraują. Ir tai yra Dvasia, kuri liudija, nes Dvasia yra tiesa.'),
  (@b62, 5, 7, 'Nes yra trys, liudijantys danguje: Tėvas, Žodis ir Šventoji Dvasia; ir šitie trys yra viena.'),
  (@b62, 5, 8, 'Ir yra trys, liudijantys žemėje: Dvasia ir vanduo, ir kraujas; ir šitie trys sutaria viename.'),
  (@b62, 5, 9, 'Jei priimame žmonių liudijimą, Dievo liudijimas yra didesnis; nes šitas yra Dievo liudijimas, kurį jis yra paliudijęs apie savo Sūnų.'),
  (@b62, 5, 10, 'Kas tiki į Dievo Sūnų, tas turi liudijimą savyje; kas netiki Dievu, tas padarė jį melagiu, kadangi netiki liudijimu, kurį Dievas liudijo apie savo Sūnų.'),
  (@b62, 5, 11, 'Ir šitas yra liudijimas, kad Dievas mums davė amžinąjį gyvenimą, ir tas gyvenimas yra jo Sūnuje.'),
  (@b62, 5, 12, 'Kas turi Sūnų, tas turi gyvenimą; o kas neturi Dievo Sūnaus, tas neturi gyvenimo.'),
  (@b62, 5, 13, 'Tai parašiau jums, kurie tikite į Dievo Sūnaus vardą; kad žinotumėte, jog turite amžinąjį gyvenimą ir kad tikėtumėte į Dievo Sūnaus vardą.'),
  (@b62, 5, 14, 'Ir šis yra pasitikėjimas, kurį turime jame, kad, jei ko prašome pagal jo valią, jis mus išklauso;'),
  (@b62, 5, 15, 'ir jei žinome, kad jis mus išklauso, ko tik prašome, žinome, kad esame gavę prašinius, kurių iš jo prašėme.'),
  (@b62, 5, 16, 'Jei kas mato savo brolį nusidedant nuodėme, kuri nėra link mirties, tas prašys, ir jis duos jam gyvenimą, tiems, kurie nenusideda link mirties. Yra nuodėmė link mirties; nesakau, kad jis melstųsi už tai.'),
  (@b62, 5, 17, 'Visas neteisumas yra nuodėmė; ir yra nuodėmė ne link mirties.'),
  (@b62, 5, 18, 'Žinome, kad kiekvienas, gimęs iš Dievo, nenusideda; bet iš Dievo pagimdytasis save saugo, ir tas nedorėlis jo nepaliečia.'),
  (@b62, 5, 19, 'Žinome, kad esame iš Dievo, o visas pasaulis guli nedorybėje.'),
  (@b62, 5, 20, 'Ir žinome, kad Dievo Sūnus yra atėjęs ir davęs mums supratimą, kad pažintume tą tikrąjį, ir esame tame tikrajame – jo Sūnuje Jėzuje Kristuje. Šis yra tikrasis Dievas ir amžinasis gyvenimas.'),
  (@b62, 5, 21, 'Vaikeliai, saugokitės stabų. Amen.'),
  (@b63, 1, 1, 'Vyresnysis išrinktajai poniai ir jos vaikams, kuriuos myliu tiesoje; ir ne tik aš, bet ir visi, pažinusieji tiesą;'),
  (@b63, 1, 2, 'dėl tiesos, kuri gyvena mumyse ir bus su mumis per amžius.'),
  (@b63, 1, 3, 'Malonė tebūna su jumis, gailestingumas ir ramybė nuo Dievo Tėvo ir nuo Viešpaties Jėzaus Kristaus, Tėvo Sūnaus, tiesoje ir meilėje.'),
  (@b63, 1, 4, 'Didžiai nudžiugau, kad iš tavo vaikų radau vaikščiojančių tiesoje, kaip mes gavome įsakymą iš Tėvo.'),
  (@b63, 1, 5, 'O dabar meldžiu tave, ponia, ne tarsi parašiau tau naują įsakymą, bet tą, kurį turėjome nuo pradžios, kad mylėtume vienas kitą.'),
  (@b63, 1, 6, 'Ir tai yra meilė, kad vaikštome pagal jo įsakymus. Šis yra įsakymas: kad, kaip girdėjote nuo pradžios, vaikščiotumėte tame.'),
  (@b63, 1, 7, 'Nes daug klaidintojų įėjo į pasaulį, kurie neišpažįsta, kad Jėzus Kristus atėjo kūne. Šitas yra klaidintojas ir Antikristas.'),
  (@b63, 1, 8, 'Žiūrėkite savęs, kad neprarastume to, ką dirbome, bet kad gautume pilną atlygį.'),
  (@b63, 1, 9, 'Kas nusižengia ir nepasilieka Kristaus moksle, tas neturi Dievo. Kas pasilieka Kristaus moksle, tas turi ir Tėvą, ir Sūnų.'),
  (@b63, 1, 10, 'Jei kas ateina pas jus ir neatneša šio mokslo, nepriimkite jo į savo namus nei jo nesveikinkite;'),
  (@b63, 1, 11, 'nes kas jį sveikina, yra jo piktų darbų dalininkas.'),
  (@b63, 1, 12, 'Turėdamas daug ką jums parašyti, nenoriu rašyti popieriumi ir rašalu, bet tikiuosi ateiti pas jus ir pakalbėti akis į akį, kad mūsų džiaugsmas būtų pilnas.'),
  (@b63, 1, 13, 'Tave sveikina išrinktosios tavo sesers vaikai. Amen.'),
  (@b64, 1, 1, 'Vyresnysis, labai mylimam Gajui, kurį myliu tiesoje.'),
  (@b64, 1, 2, 'Mylimasis, viršum visko trokštu, kad klestėtum ir būtum sveikas, kaip ir tavo siela klesti.'),
  (@b64, 1, 3, 'Nes didžiai pradžiugau, kai atėjo broliai ir paliudijo apie tiesą, esančią tavyje, kaip tu vaikštai tiesoje.'),
  (@b64, 1, 4, 'Neturiu didesnio džiaugsmo, kaip girdėti, kad mano vaikai vaikšto tiesoje.'),
  (@b64, 1, 5, 'Mylimasis, tu ištikimai darai, ką bedarai broliams ir ateiviams;'),
  (@b64, 1, 6, 'kurie paliudijo apie tavo meilę bažnyčios akivaizdoje; gerai padarysi, jei dievotai juos išleisi kelionėn;'),
  (@b64, 1, 7, 'nes jie išvyko dėl jo vardo, nieko neimdami iš pagonių.'),
  (@b64, 1, 8, 'Todėl turime tokius priimti, kad būtume tiesos bendrapagalbininkai.'),
  (@b64, 1, 9, 'Parašiau bažnyčiai, bet Diotrefas, mėgstantis turėti pranašumą tarp jų, mūsų nepriima.'),
  (@b64, 1, 10, 'Todėl, jei ateisiu, prisiminsiu jo darbus, kuriuos jis daro plepėdamas prieš mus piktais žodžiais; ir tuo nepasitenkina – nei pats nepriima brolių, nei neleidžia norintiems ir išmeta juos iš bažnyčios.'),
  (@b64, 1, 11, 'Mylimasis, nesek tuo, kas pikta, bet tuo, kas gera. Kas daro gera, tas yra iš Dievo; bet kas daro pikta, tas nėra matęs Dievo.'),
  (@b64, 1, 12, 'Demetrijus turi gerus atsiliepimus iš visų ir iš pačios tiesos; taip, ir mes liudijame; ir žinote, kad mūsų liudijimas yra tikras.'),
  (@b64, 1, 13, 'Turėjau daug ką parašyti, tačiau tau nerašysiu rašalu ir plunksna;'),
  (@b64, 1, 14, 'bet tikiuosi, netrukus tave pamatysiu, ir mes pakalbėsime akis į akį. Tebūna tau ramybė. Tave sveikina mūsų draugai. Sveikink draugus pavardžiui.'),
  (@b65, 1, 1, 'Judas, Jėzaus Kristaus tarnas ir Jokūbo brolis, Dievo Tėvo pašvęstiesiems ir išsaugotiems Jėzuje Kristuje, ir pašauktiems:'),
  (@b65, 1, 2, 'tepadaugėja jums gailestingumas ir ramybė, ir meilė.'),
  (@b65, 1, 3, 'Mylimieji, kai sutelkiau visą stropumą jums rašyti apie bendrą išgelbėjimą, buvo reikalinga man jums parašyti ir jus paraginti, kad uoliai kovotumėte už tikėjimą, kuris buvo vieną kartą duotas šventiesiems.'),
  (@b65, 1, 4, 'Nes vogčiomis įslinko kai kurie žmonės, kurie nuo seno paskirti šitam pasmerkimui, bedieviai, paverčiantys mūsų Dievo malonę į gašlumą ir neigiantys vienintelį Viešpatį Dievą ir mūsų Viešpatį Jėzų Kristų.'),
  (@b65, 1, 5, 'Todėl noriu jums priminti, nors vieną kartą tai žinojote, kaip Viešpats, išgelbėjęs tautą iš Egipto šalies, po to sunaikino tuos, kurie netikėjo.'),
  (@b65, 1, 6, 'Ir angelus, kurie nesilaikė savo pirmosios padėties, bet paliko savo buveinę, jis yra išlaikęs amžinose grandinėse po tamsa, didžiosios dienos teismui.'),
  (@b65, 1, 7, 'Būtent kaip Sodoma bei Gomora ir miestai aplink juos, tokiu pat būdu atsidavę paleistuvystei ir nuėję paskui svetimą kūną, yra išstatyti pavyzdžiu, kentėdami amžinosios ugnies kerštą.'),
  (@b65, 1, 8, 'Taip pat ir šitie ištvirkę sapnuotojai suteršia kūną, išniekina viešpatystę ir kalba pikta apie aukštuosius.'),
  (@b65, 1, 9, 'Tačiau arkangelas Mykolas, varžydamasis su velniu, ginčydamasis dėl Mozės kūno, nedrįso pateikti prieš jį keikiančio kaltinimo, bet tarė: „Tebara tave Viešpats“.'),
  (@b65, 1, 10, 'Bet šitie kalba pikta apie tai, ko nežino, bet ką žino iš prigimties kaip neprotingi gyvuliai, tame jie save gadina.'),
  (@b65, 1, 11, 'Vargas jiems! Nes jie nuėjo Kaino keliu ir dėl atlygio godžiai nubėgo paskui Balaamo nuklydimą, ir pražuvo Korės prieštaravime.'),
  (@b65, 1, 12, 'Šitie yra dė̃mės jūsų meilės pokyliuose, kai jie su jumis puotauja, ganydami save be baimės; jie yra bevandeniai debesys, nešiojami vėjų; medžiai, kurių vaisius vysta, bevaisiai, du kartus mirę, išrauti su šaknimis;'),
  (@b65, 1, 13, 'šėlstančios jūros bangos, išputojančios savo pačių gėdą; klajojančios žvaigždės, kurioms yra išlaikyta tamsos juoduma per amžius.'),
  (@b65, 1, 14, 'Ir Henochas, septintasis nuo Adomo, taipogi apie šituos pranašavo, sakydamas: „Štai ateina Viešpats su dešimt tūkstančių savo šventųjų'),
  (@b65, 1, 15, 'įvykdyti teismą visiems ir įtikinti visus tarp jų esančius bedievius dėl visų jų bedieviškų darbų, kuriuos jie bedieviškai vykdė, ir dėl visų jų šiurkščių kalbų, kurias bedieviški nusidėjėliai kalbėjo prieš jį“.'),
  (@b65, 1, 16, 'Šitie yra murmėtojai, besiskundžiantys, vaikštantys pagal savo geismus; ir jų burna kalba didžiai išpūstus žodžius, rodant susižavėjimą žmonių asmenimis dėl naudos.'),
  (@b65, 1, 17, 'Bet, mylimieji, prisiminkite mūsų Viešpaties Jėzaus Kristaus apaštalų anksčiau kalbėtus žodžius;'),
  (@b65, 1, 18, 'kaip jie jums sakė, kad paskutiniu laiku bus išjuokėjų, kurie vaikščios pagal savo pačių bedieviškus geismus.'),
  (@b65, 1, 19, 'Šitie yra tie, kurie atskiria save, jusliniai, neturintys Dvasios.'),
  (@b65, 1, 20, 'Bet jūs, mylimieji, statydami save ant savo švenčiausio tikėjimo, melsdamiesi Šventojoje Dvasioje,'),
  (@b65, 1, 21, 'išlaikykite save Dievo meilėje, laukdami mūsų Viešpaties Jėzaus Kristaus gailestingumo amžinam gyvenimui.'),
  (@b65, 1, 22, 'Ir vienų gailėkitės, išlaikydami skirtumą;'),
  (@b65, 1, 23, 'o kitus gelbėkite su baime, ištraukdami juos iš ugnies; nekęsdami netgi drabužio, sutepto kūnu.'),
  (@b65, 1, 24, 'Na, o tam, kuris pajėgus jus išsaugoti nuo griuvimo ir pristatyti jus nepriekaištingus savo šlovės akivaizdoje su begaliniu džiaugsmu,'),
  (@b65, 1, 25, 'vieninteliam išmintingajam Dievui mūsų Gelbėtojui tebūna šlovė ir didybė, viešpatystė ir valdžia tiek dabar, tiek ir visada. Amen.'),
  (@b66, 1, 1, 'Jėzaus Kristaus Apreiškimas, kurį jam davė Dievas, kad parodytų savo tarnams tai, kas turi netrukus įvykti; ir pasiuntęs jis parodė tai per savo angelą savo tarnui Jonui,'),
  (@b66, 1, 2, 'kuris liudija Dievo žodį ir Jėzaus Kristaus liudijimą, ir visa, ką matė.'),
  (@b66, 1, 3, 'Palaimintas tas, kuris skaito, ir tie, kurie klausosi šios pranašystės žodžių ir laikosi to, kas joje surašyta; nes laikas yra čia pat.'),
  (@b66, 1, 4, 'Jonas, septynioms bažnyčioms, esančioms Azijoje: malonė tebūna jums ir ramybė nuo to, kuris yra ir kuris buvo, ir kuris ateis; ir nuo septynių dvasių, kurios yra prieš jo sostą;'),
  (@b66, 1, 5, 'ir nuo Jėzaus Kristaus, kuris yra ištikimasis liudytojas, mirusiųjų pirmagimis ir žemės karalių kunigaikštis. Tam, kuris mus pamilo ir nuplovė mus nuo mūsų nuodėmių savo kraujyje,'),
  (@b66, 1, 6, 'ir padarė mus karaliais ir kunigais Dievui ir savo Tėvui; jam tebūna šlovė ir viešpatystė per amžių amžius. Amen.'),
  (@b66, 1, 7, 'Štai jis ateina su debesimis; ir regės jį kiekviena akis, taip pat ir tie, kurie jį perdūrė; ir visos žemės giminės dėl jo aimanuos. Taip, Amen.'),
  (@b66, 1, 8, '„Aš esu Alfa ir Omega, pradžia ir pabaiga“, – sako Viešpats, kuris yra ir kuris buvo, ir kuris ateis, Visagalis.'),
  (@b66, 1, 9, 'Aš, Jonas, kuris esu ir jūsų brolis, ir draugas suspaudime, ir karalystėje, ir kantrybėje Jėzaus Kristaus, buvau saloje, kuri vadinama Patmu, dėl Dievo žodžio ir dėl Jėzaus Kristaus liudijimo.'),
  (@b66, 1, 10, 'Buvau Dvasioje Viešpaties dieną ir išgirdau sau už nugaros didį balsą, kaip trimito,'),
  (@b66, 1, 11, 'sakantį: „Aš esu Alfa ir Omega, pirmasis ir paskutinysis“ ir: „Ką matai, užrašyk į knygą ir nusiųsk tai septynioms bažnyčioms, kurios yra Azijoje: į Efezą ir į Smirną, ir į Pergamą, ir į Tiatyrus, ir į Sardus, ir į Filadelfiją, ir į Laodikėją“.'),
  (@b66, 1, 12, 'Ir atsigręžiau pažiūrėti balso, kuris kalbėjo su manimi. Ir atsisukęs pamačiau septynias auksines žvakides;'),
  (@b66, 1, 13, 'o septynių žvakidžių viduryje – vieną panašų į žmogaus Sūnų, apsivilkusį pėdas siekiančiu drabužiu ir apsijuosusį apie krūtinę auksine juosta.'),
  (@b66, 1, 14, 'Jo galva ir plaukai buvo balti kaip vilna, balti kaip sniegas; o jo akys – kaip ugnies liepsna;'),
  (@b66, 1, 15, 'o jo kojos panašios į puikų žalvarį, tarsi jos degtų krosnyje; o jo balsas kaip daugelio vandenų garsas.'),
  (@b66, 1, 16, 'Ir savo dešinėje rankoje jis turėjo septynias žvaigždes, o iš jo burnos ėjo aštrus dviašmenis kalavijas; o jo veidas – kaip savo stiprumu šviečianti saulė.'),
  (@b66, 1, 17, 'Ir kai jį pamačiau, kritau prie jo kojų kaip negyvas. Ir jis uždėjo ant manęs savo dešinę ranką, sakydamas man: „Nebijok; aš esu pirmasis ir paskutinysis,'),
  (@b66, 1, 18, 'gyvasis, ir buvau miręs; ir štai esu amžinai gyvas, Amen; ir turiu pragaro bei mirties raktus.'),
  (@b66, 1, 19, 'Užrašyk tai, ką matei ir tai, kas yra, ir tai, kas bus po to;'),
  (@b66, 1, 20, 'paslaptis septynių žvaigždžių, kurias matei mano dešinėje rankoje, ir septynių auksinių žvakidžių. Septynios žvaigždės yra septynių bažnyčių angelai, o septynios žvakidės, kurias matei, yra septynios bažnyčios“.'),
  (@b66, 2, 1, '„Efezo bažnyčios angelui rašyk: ‘Tai sako tas, kuris savo dešinėje rankoje laiko septynias žvaigždes, kuris vaikšto tarp septynių auksinių žvakidžių;'),
  (@b66, 2, 2, 'žinau tavo darbus ir tavo triūsą, ir tavo kantrybę, ir kaip negali pakęsti piktųjų; ir ištyrei tuos, kurie sakosi esą apaštalai, tačiau nėra, ir radai juos esant melagiais;'),
  (@b66, 2, 3, 'ir iškentei, ir turi kantrybės, ir triūsei dėl mano vardo, ir nenusilpai.'),
  (@b66, 2, 4, 'Tačiau kai ką turiu prieš tave, nes palikai savo pirmąją meilę.'),
  (@b66, 2, 5, 'Todėl prisimink, nuo kur esi nupuolęs, ir atgailauk, ir daryk pirmuosius darbus; antraip, aš greitai ateisiu pas tave ir pašalinsiu tavo žvakidę iš jos vietos, jei neatgailausi.'),
  (@b66, 2, 6, 'Bet tu turi tai, kad nekenti nikolaitų darbų, kurių ir aš nekenčiu’.'),
  (@b66, 2, 7, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms: ‘Tam, kuris nugali, duosiu valgyti nuo gyvybės medžio, kuris yra Dievo rojaus viduryje’.'),
  (@b66, 2, 8, 'Ir bažnyčios Smirnoje angelui rašyk: ‘Tai sako pirmasis ir paskutinysis, kuris buvo miręs ir yra gyvas;'),
  (@b66, 2, 9, 'žinau tavo darbus ir suspaudimą, ir skurdą (bet tu esi turtingas), ir žinau piktžodžiavimą tų, kurie sakosi esą žydai, tačiau nėra, bet yra šėtono sinagoga.'),
  (@b66, 2, 10, 'Nebijok nieko iš to, ką kentėsi: štai velnias įmes kai kuriuos iš jūsų į kalėjimą, kad būtumėte išbandyti; ir turėsite dešimt dienų suspaudimo; būk ištikimas iki mirties, ir tau duosiu gyvenimo vainiką’.'),
  (@b66, 2, 11, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms: ‘Kas nugali, tas nenukentės nuo antrosios mirties’.'),
  (@b66, 2, 12, 'Ir bažnyčios Pergame angelui rašyk: Tai sako tas, kuris turi aštrų kalaviją su dviem ašmenimis;'),
  (@b66, 2, 13, 'žinau tavo darbus ir kur gyveni, būtent kur yra šėtono sostas; ir tvirtai laikaisi mano vardo, ir neišsigynei mano tikėjimo, netgi tomis dienomis, kai Antipas buvo mano ištikimas liudytojas, kuris buvo nužudytas tarp jūsų, kur gyvena šėtonas.'),
  (@b66, 2, 14, 'Bet turiu kai ką prieš tave, nes ten turi besilaikančių mokslo Balaamo, kuris mokė Balaką įmesti sukluptį Izraelio vaikų akivaizdon, kad valgytų tai, kas paaukota stabams, ir kad paleistuvautų.'),
  (@b66, 2, 15, 'Taip ir tu turi besilaikančių nikolaitų mokslo, ko aš nekenčiu.'),
  (@b66, 2, 16, 'Atgailauk; antraip, greitai pas tave ateisiu ir kovosiu prieš juos savo burnos kalaviju’.'),
  (@b66, 2, 17, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms: ‘Tam, kuris nugali, duosiu valgyti paslėptos manos ir duosiu jam baltą akmenį ir akmenyje įrašytą naują vardą, kurio nežino niekas, išskyrus tą, kuris jį gauna’.'),
  (@b66, 2, 18, 'Ir bažnyčios Tiatyruose angelui rašyk: ‘Tai sako Dievo Sūnus, kuris turi akis kaip ugnies liepsna, ir jo kojos kaip puikus žalvaris;'),
  (@b66, 2, 19, 'žinau tavo darbus ir meilę, ir tarnavimą, ir tikėjimą, ir tavo kantrybę, ir tavo darbus; ir paskutiniųjų yra daugiau, negu pirmųjų.'),
  (@b66, 2, 20, 'Tačiau turiu prieš tave kai ką, nes leidi tai moteriai Jezabelei, vadinančiai save pranaše, mokyti ir suvilioti mano tarnus, kad paleistuvautų bei valgytų tai, kas paaukota stabams.'),
  (@b66, 2, 21, 'Ir daviau jai laiko atgailauti dėl savo paleistuvystės; bet ji neatgailavo.'),
  (@b66, 2, 22, 'Štai įmesiu ją į patalą, o su ja svetimaujančius – į didelį suspaudimą, jeigu jie neatgailaus dėl savo darbų.'),
  (@b66, 2, 23, 'Ir nužudysiu jos vaikus mirtimi; ir visos bažnyčios žinos, kad aš esu tas, kuris tiria inkstus ir širdis; ir duosiu kiekvienam iš jūsų pagal jūsų darbus.'),
  (@b66, 2, 24, 'Bet sakau jums ir kitiems, esantiems Tiatyruose, kurie neturi šito mokslo ir kurie, kaip sakosi, nėra pažinę šėtono gelmių; aš ant jūsų neužkrausiu kitos naštos.'),
  (@b66, 2, 25, 'Bet tai, ką jau turite, tvirtai laikykite, kol ateisiu.'),
  (@b66, 2, 26, 'O tam, kuris nugali ir laikosi mano darbų iki galo, duosiu valdžią tautoms;'),
  (@b66, 2, 27, 'ir jis valdys jas geležine lazda; kaip puodžiaus indai jie bus sudaužyti į šukes, kaip ir aš gavau iš savo Tėvo.'),
  (@b66, 2, 28, 'Ir jam duosiu ryto žvaigždę’.'),
  (@b66, 2, 29, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms“.'),
  (@b66, 3, 1, '„Ir bažnyčios Sarduose angelui rašyk: ‘Tai sako tas, kuris turi septynias Dievo dvasias ir septynias žvaigždes; žinau tavo darbus, kad turi vardą, jog esi gyvas, bet esi miręs.'),
  (@b66, 3, 2, 'Būk budrus ir sustiprink tai, kas likę, kas yra prie mirties, nes neradau tavo darbų, tobulų Dievo akivaizdoje.'),
  (@b66, 3, 3, 'Todėl prisimink, kaip gavai ir girdėjai, ir tvirtai laikyk, ir atgailauk. Taigi, jei nebudėsi, užeisiu ant tavęs kaip vagis, ir nežinosi, kurią valandą ant tavęs užeisiu.'),
  (@b66, 3, 4, 'Tu turi keletą vardų ir Sarduose, kurie nesuteršė savo drabužių; ir jie vaikščios su manimi baltais drabužiais, nes jie yra verti.'),
  (@b66, 3, 5, 'Kas nugali, tas bus apvilktas baltu drabužiu; ir aš neištrinsiu jo vardo iš gyvenimo knygos, bet išpažinsiu jo vardą savo Tėvo akivaizdoje ir jo angelų akivaizdoje’.'),
  (@b66, 3, 6, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms.'),
  (@b66, 3, 7, 'Ir bažnyčios Filadelfijoje angelui rašyk: ‘Tai sako šventasis, tikrasis, turintis Dovydo raktą, tas, kuris atrakina, ir niekas neužrakina; ir užrakina, ir niekas neatrakina;'),
  (@b66, 3, 8, 'žinau tavo darbus; štai paruošiau priešais tave atviras duris, ir niekas negali jų užrakinti; nes tu turi mažai stiprybės, ir išsaugojai mano žodį ir neišsigynei mano vardo.'),
  (@b66, 3, 9, 'Štai padarysiu tuos iš šėtono sinagogos, kurie sakosi esą žydai, o nėra, bet meluoja; štai padarysiu, kad jie ateitų ir garbintų prie tavo kojų ir žinotų, kad aš pamilau tave.'),
  (@b66, 3, 10, 'Kadangi išsaugojai mano kantrybės žodį, tai ir aš apsaugosiu tave nuo gundymo valandos, ateisiančios ant viso pasaulio, kad išbandytų gyvenančius žemėje.'),
  (@b66, 3, 11, 'Štai aš greitai ateinu; tvirtai laikyk tai, ką turi, kad niekas nepaimtų tavo vainiko.'),
  (@b66, 3, 12, 'Kas nugali, tą padarysiu stulpu mano Dievo šventykloje, ir jis nebeišeis laukan; ir ant jo užrašysiu mano Dievo vardą ir mano Dievo miesto vardą, naujosios Jeruzalės, nužengiančios iš dangaus nuo mano Dievo; ir ant jo užrašysiu savo naują vardą’.'),
  (@b66, 3, 13, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms.'),
  (@b66, 3, 14, 'Ir laodikėjiečių bažnyčios angelui rašyk: ‘Tai sako Amen, ištikimasis ir tikrasis liudytojas, Dievo kūrinijos pradžia;'),
  (@b66, 3, 15, 'žinau tavo darbus, kad esi nei šaltas, nei karštas; norėčiau, kad būtum šaltas arba karštas.'),
  (@b66, 3, 16, 'Tad kadangi esi drungnas, o nei šaltas, nei karštas, aš išspjausiu tave iš savo burnos.'),
  (@b66, 3, 17, 'Kadangi sakai: ‘Esu turtingas ir pralobęs, ir nieko man nereikia’; o nežinai, kad esi nelaimingas ir apgailėtinas, ir beturtis, ir aklas, ir nuogas;'),
  (@b66, 3, 18, 'patariu tau pirkti iš manęs aukso, išbandyto ugnyje, kad būtumei turtingas; ir baltą drabužį, kad būtumei apsirengęs, ir kad nepasirodytų tavo nuogumo gėda; ir pasitepk akis akių tepalu, kad regėtum.'),
  (@b66, 3, 19, 'Visus, kuriuos myliu, baru ir baudžiu; todėl būk uolus ir atgailauk.'),
  (@b66, 3, 20, 'Štai aš stoviu prie durų ir beldžiuosi: jei kas girdi mano balsą ir atidaro duris, aš įeisiu pas jį ir su juo vakarieniausiu, ir jis su manimi.'),
  (@b66, 3, 21, 'Kas nugali, tam duosiu atsisėsti su manimi mano soste, kaip ir aš nugalėjau ir atsisėdau su savo Tėvu jo soste’.'),
  (@b66, 3, 22, 'Kas turi ausis, teklauso, ką Dvasia sako bažnyčioms“.'),
  (@b66, 4, 1, 'Po to pažiūrėjau, ir štai buvo atvertos durys danguje; ir pirmasis balsas, kurį išgirdau, buvo tarsi trimito, kalbančio su manimi; kuris tarė: „Užženk čionai, ir parodysiu tau tai, kas turės būti po to“.'),
  (@b66, 4, 2, 'Ir tuoj pat buvau Dvasioje; ir štai danguje stovėjo sostas, ir vienas sėdėjo soste.'),
  (@b66, 4, 3, 'Ir tas sėdintysis žiūrint buvo panašus į jaspio ir sardžio akmenį; ir aplink sostą buvo vaivorykštė, žiūrint panaši į smaragdą.'),
  (@b66, 4, 4, 'O aplink sostą buvo dvidešimt keturi sostai, ir tuose sostuose mačiau sėdinčius dvidešimt keturis vyresniuosius, apsivilkusius baltais drabužiais; o ant savo galvų jie turėjo aukso vainikus.'),
  (@b66, 4, 5, 'Ir nuo to sosto ėjo žaibai ir griaustiniai, ir balsai; ir prieš sostą buvo septyni degantys ugnies žibintai, kurie yra septynios Dievo dvasios.'),
  (@b66, 4, 6, 'Ir prieš sostą buvo stiklo jūra, panaši į krištolą; o sosto viduryje ir aplink sostą buvo keturi žvėrys, pilni akių iš priekio ir iš nugaros.'),
  (@b66, 4, 7, 'Ir pirmasis žvėris buvo panašus į liūtą, ir antrasis žvėris panašus į veršį, ir trečiasis žvėris turėjo veidą kaip žmogaus, ir ketvirtasis žvėris buvo panašus į skrendantį erelį.'),
  (@b66, 4, 8, 'O tie keturi žvėrys, kiekvienas iš jų aplink save turėjo po šešis sparnus; ir jie viduje buvo pilni akių; ir jie nesiilsi dieną nei naktį, sakydami: „Šventas, šventas, šventas, Viešpats Dievas Visagalis, kuris buvo ir yra, ir ateis“.'),
  (@b66, 4, 9, 'Ir kai tie žvėrys duoda šlovę ir garbę, ir padėką tam, kuris sėdi soste, kuris gyvena per amžių amžius,'),
  (@b66, 4, 10, 'dvidešimt keturi vyresnieji puola žemėn prieš sėdintįjį soste ir garbina gyvenantįjį per amžių amžius, ir meta savo vainikus prieš sostą, sakydami:'),
  (@b66, 4, 11, '„Esi vertas, o Viešpatie, imti šlovę ir garbę, ir jėgą, nes tu visa sutvėrei, ir dėl tavo noro tai yra ir buvo sutverta“.'),
  (@b66, 5, 1, 'Ir soste sėdinčiojo dešinėje pamačiau knygą, prirašytą viduje ir nugarinėje pusėje, užantspauduotą septyniais antspaudais.'),
  (@b66, 5, 2, 'Ir pamačiau stiprų angelą, skelbiantį garsiu balsu: „Kas yra vertas atverti knygą ir atplėšti jos antspaudus?“'),
  (@b66, 5, 3, 'Ir niekas nei danguje, nei žemėje, nei po žeme, negalėjo atverti tos knygos nei į ją pažiūrėti.'),
  (@b66, 5, 4, 'Ir aš labai verkiau, kad neatsirado nei vieno verto atverti ir skaityti tą knygą nei į ją pažiūrėti.'),
  (@b66, 5, 5, 'Ir vienas iš vyresniųjų man sako: „Neverk – štai nugalėjo Liūtas iš Judos genties, Dovydo Šaknis, kad atvertų knygą ir atplėštų septynis jos antspaudus“.'),
  (@b66, 5, 6, 'Ir aš pažiūrėjau, ir štai sosto bei keturių žvėrių viduryje ir vyresniųjų viduryje stovėjo Avinėlis, kaip buvęs nužudytas, turintis septynis ragus ir septynias akis, kurios yra septynios Dievo dvasios, išsiųstos į visą žemę.'),
  (@b66, 5, 7, 'Ir jis atėjo ir paėmė knygą iš soste sėdinčiojo dešinės.'),
  (@b66, 5, 8, 'Ir kai jis paėmė knygą, keturi žvėrys bei dvidešimt keturi vyresnieji parpuolė prieš Avinėlį, kiekvienas iš jų turėdamas arfą ir auksinius dubenis, pilnus kvapų, kurie yra šventųjų maldos.'),
  (@b66, 5, 9, 'Ir jie giedojo naują giesmę, sakydami: „Tu esi vertas imti knygą ir atverti jos antspaudus; nes buvai užmuštas ir savo krauju atpirkai Dievui mus iš kiekvienos giminės ir kalbos, ir tautos, ir tautybės;'),
  (@b66, 5, 10, 'ir padarei mus mūsų Dievui karaliais ir kunigais, ir mes karaliausime žemėje“.'),
  (@b66, 5, 11, 'Ir aš pažiūrėjau, ir išgirdau balsą daugybės angelų aplink sostą ir žvėrių, ir vyresniųjų – ir jų skaičius buvo dešimt tūkstančių kart dešimt tūkstančių, ir tūkstančių tūkstančiai –'),
  (@b66, 5, 12, 'garsiu balsu sakančių: „Vertas yra Avinėlis, kuris buvo užmuštas, priimti galią ir turtus, ir išmintį, ir stiprybę, ir garbę, ir šlovę, ir palaiminimą“.'),
  (@b66, 5, 13, 'Ir kiekvieną sutvėrimą, kurie yra danguje ir žemėje, ir po žeme, ir tokius, kurie yra jūroje, bei visus, esančius juose, girdėjau sakant: „Palaiminimas ir garbė, ir šlovė, ir valdžia tebūna tam, kuris sėdi soste, ir Avinėliui per amžių amžius“.'),
  (@b66, 5, 14, 'Ir keturi žvėrys tarė: „Amen“. Ir dvidešimt keturi vyresnieji parpuolė žemėn ir pagarbino gyvenantįjį per amžių amžius.'),
  (@b66, 6, 1, 'Ir mačiau, kai Avinėlis atvėrė vieną iš antspaudų, ir išgirdau tarsi griaustinio garsą, vieną iš keturių žvėrių sakant: „Ateik ir žiūrėk“.'),
  (@b66, 6, 2, 'Ir pamačiau, ir štai baltas žirgas; ir ant jo sėdintysis turėjo lanką; ir jam buvo duotas vainikas, ir jis išėjo nugalėdamas ir kad nugalėtų.'),
  (@b66, 6, 3, 'Ir kai jis atvėrė antrąjį antspaudą, išgirdau antrąjį žvėrį sakant: „Ateik ir žiūrėk“.'),
  (@b66, 6, 4, 'Ir išėjo kitas žirgas, raudonas, ir ant jo sėdinčiajam buvo duota valdžia atimti iš žemės taiką, ir kad jie vienas kitą žudytų; ir jam buvo duotas didelis kalavijas.'),
  (@b66, 6, 5, 'Ir kai jis atvėrė trečiąjį antspaudą, išgirdau trečiąjį žvėrį sakant: „Ateik ir žiūrėk“. Ir pažiūrėjau, ir štai juodas žirgas; ir ant jo sėdintysis turėjo savo rankoje svarstykles.'),
  (@b66, 6, 6, 'Ir išgirdau balsą keturių žvėrių viduryje, sakant: „Kviečių saikas už denarą ir trys saikai miežių už denarą; ir žiūrėk, nepakenk aliejui ir vynui“.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b66, 6, 7, 'Ir kai jis atvėrė ketvirtąjį antspaudą, išgirdau ketvirtojo žvėries balsą sakant: „Ateik ir žiūrėk“.'),
  (@b66, 6, 8, 'Ir pažiūrėjau, ir štai išblyškęs žirgas; ir ant jo sėdinčiojo vardas buvo Mirtis, ir Pragaras sekė su juo. Ir jiems buvo duota valdžia žemės ketvirtadaliui, žudyti kalaviju ir alkiu, ir mirtimi, ir žemės žvėrimis.'),
  (@b66, 6, 9, 'Ir kai jis atvėrė penktąjį antspaudą, pamačiau po aukuru sielas užmuštųjų dėl Dievo žodžio ir dėl liudijimo, kurio jie laikėsi;'),
  (@b66, 6, 10, 'ir jie šaukė garsiu balsu, sakydami: „Kiek ilgai, o Viešpatie, šventas ir teisingas, tu neteisi ir nekeršysi už mūsų kraują gyvenantiems žemėje?“'),
  (@b66, 6, 11, 'Ir kiekvienam iš jų buvo duoti balti drabužiai; ir jiems buvo pasakyta, kad jie dar trumpą laikotarpį ilsėtųsi, kol ir jų bendratarniai bei jų broliai, kurie turės būti užmušti kaip jie, turės išsipildyti.'),
  (@b66, 6, 12, 'Ir kai jis atvėrė šeštąjį antspaudą, pamačiau, ir štai buvo didelis žemės drebėjimas; ir saulė tapo juoda kaip maišas iš šerių, ir mėnulis tapo kaip kraujas;'),
  (@b66, 6, 13, 'ir dangaus žvaigždės krito ant žemės, kaip ir figmedis, galingo vėjo purtomas, numeta savo neprinokusias figas.'),
  (@b66, 6, 14, 'Ir dangus pasitraukė kaip suvyniojamas ritinys; ir kiekvienas kalnas bei sala buvo išjudinti iš savo vietų.'),
  (@b66, 6, 15, 'Ir žemės karaliai ir didžiūnai, ir turtuoliai, ir vyriausieji vadai, ir galiūnai, ir kiekvienas vergas, ir kiekvienas laisvasis pasislėpė urvuose ir kalnų uolose;'),
  (@b66, 6, 16, 'ir tarė kalnams ir uoloms: „Griūkite ant mūsų ir paslėpkite mus nuo sėdinčiojo soste veido ir nuo Avinėlio rūstybės,'),
  (@b66, 6, 17, 'nes atėjo didi jo rūstybės diena; ir kas pajėgs išstovėti?“'),
  (@b66, 7, 1, 'Ir po šių dalykų pamačiau keturis angelus, stovinčius keturiuose žemės kampuose, laikančius keturis žemės vėjus, kad vėjas nepūstų nei į žemę, nei į jūrą, nei į jokį medį.'),
  (@b66, 7, 2, 'Ir pamačiau kitą angelą, pakylantį nuo rytų, turintį gyvojo Dievo antspaudą; ir jis garsiu balsu šaukė keturiems angelams, kuriems buvo duota kenkti žemei ir jūrai,'),
  (@b66, 7, 3, 'sakydamas: „Nekenkite nei žemei, nei jūrai, nei medžiams, kol užantspauduosime mūsų Dievo tarnus jų kaktose“.'),
  (@b66, 7, 4, 'Ir išgirdau skaičių užantspauduotųjų, ir buvo užantspauduota šimtas keturiasdešimt keturi tūkstančiai iš visų Izraelio vaikų genčių.'),
  (@b66, 7, 5, 'Iš Judos genties buvo užantspauduota dvylika tūkstančių. Iš Rubeno genties buvo užantspauduota dvylika tūkstančių. Iš Gado genties buvo užantspauduota dvylika tūkstančių.'),
  (@b66, 7, 6, 'Iš Asero genties buvo užantspauduota dvylika tūkstančių. Iš Neftalio genties buvo užantspauduota dvylika tūkstančių. Iš Manaso genties buvo užantspauduota dvylika tūkstančių.'),
  (@b66, 7, 7, 'Iš Simeono genties buvo užantspauduota dvylika tūkstančių. Iš Levio genties buvo užantspauduota dvylika tūkstančių. Iš Isacharo genties buvo užantspauduota dvylika tūkstančių.'),
  (@b66, 7, 8, 'Iš Zabulono genties buvo užantspauduota dvylika tūkstančių. Iš Juozapo genties buvo užantspauduota dvylika tūkstančių. Iš Benjamino genties buvo užantspauduota dvylika tūkstančių.'),
  (@b66, 7, 9, 'Po to pažiūrėjau, ir štai didžiulė minia, kurios niekas negalėjo suskaičiuoti, iš visų tautybių ir giminių, ir tautų, ir kalbų, stovėjo prieš sostą ir prieš Avinėlį, apsivilkę baltais drabužiais, ir palmės jų rankose;'),
  (@b66, 7, 10, 'ir šaukė garsiu balsu, sakydami: „Išgelbėjimas mūsų Dievui, sėdinčiam soste, ir Avinėliui“.'),
  (@b66, 7, 11, 'Ir visi angelai stovėjo aplink sostą ir aplink vyresniuosius bei keturis žvėris ir parpuolė prieš sostą veidais žemėn, ir pagarbino Dievą,'),
  (@b66, 7, 12, 'sakydami: „Amen! Palaiminimas ir šlovė, ir išmintis, ir padėka, ir garbė, ir jėga, ir galybė tebūna mūsų Dievui per amžių amžius. Amen“.'),
  (@b66, 7, 13, 'Ir vienas iš vyresniųjų atsakė, man sakydamas: „Kas yra šitie, apsirengę baltais drabužiais? Ir iš kur jie atėjo?“'),
  (@b66, 7, 14, 'Ir aš jam tariau: „Pone, tu žinai“. Ir jis man tarė: „Šitie yra tie, kurie išėjo iš didžiojo suspaudimo ir išplovė savo drabužius, ir juos išbaltino Avinėlio kraujyje.'),
  (@b66, 7, 15, 'Todėl jie yra prieš Dievo sostą ir tarnauja jam dieną bei naktį jo šventykloje; o sėdintysis soste gyvens tarp jų.'),
  (@b66, 7, 16, 'Jie nebealks nei nebetrokš; nei saulė jų nebepuls, nei jokia kaitra.'),
  (@b66, 7, 17, 'Nes Avinėlis, esantis sosto viduryje, juos ganys ir ves juos prie gyvųjų vandenų šaltinių; ir Dievas nušluostys visas ašaras nuo jų akių“.'),
  (@b66, 8, 1, 'Ir kai jis atvėrė septintąjį antspaudą, danguje kokį pusvalandį buvo tyla.'),
  (@b66, 8, 2, 'Ir mačiau septynis angelus, kurie stovėjo prieš Dievą; ir jiems buvo duoti septyni trimitai.'),
  (@b66, 8, 3, 'Ir kitas angelas, turintis auksinį smilkytuvą, atėjo ir atsistojo prie aukuro; ir jam buvo duota daug smilkalų, kad jis juos atnašautų su visų šventųjų maldomis ant auksinio aukuro, esančio prieš sostą.'),
  (@b66, 8, 4, 'Ir dūmai smilkalų, atėjusių su šventųjų maldomis, iš angelo rankos pakilo aukštyn Dievo akivaizdon.'),
  (@b66, 8, 5, 'Ir angelas paėmė smilkytuvą ir pripildė jį aukuro ugnies, ir metė į žemę; ir buvo balsai ir griaustiniai, ir žaibai, ir žemės drebėjimas.'),
  (@b66, 8, 6, 'Ir septyni angelai, turintys septynis trimitus, pasiruošė trimituoti.'),
  (@b66, 8, 7, 'Sutrimitavo pirmasis angelas, ir pasekė kruša bei ugnis, sumaišyti su krauju, ir tie buvo numesti į žemę; ir sudegė trečdalis medžių, ir sudegė visa žalia žolė.'),
  (@b66, 8, 8, 'Ir sutrimitavo antrasis angelas, ir tarsi didelis ugnimi degantis kalnas buvo įmestas į jūrą, ir trečdalis jūros tapo krauju;'),
  (@b66, 8, 9, 'ir trečdalis jūroje esančių sutvėrimų bei turinčių gyvybę, mirė; ir trečdalis laivų buvo sunaikinti.'),
  (@b66, 8, 10, 'Ir sutrimitavo trečiasis angelas, ir iš dangaus nukrito didelė žvaigždė, deganti tarsi žibintas, ir nukrito ant trečdalio upių ir ant vandens šaltinių;'),
  (@b66, 8, 11, 'ir žvaigždės vardas yra vadinamas Metėle; ir trečdalis vandenų tapo metėle; ir daug žmonių mirė nuo vandenų, nes jie pasidarė kartūs.'),
  (@b66, 8, 12, 'Ir sutrimitavo ketvirtasis angelas, ir buvo užgautas trečdalis saulės, ir trečdalis mėnulio, ir trečdalis žvaigždžių; taip, kad trečdalis jų aptemo, ir diena nebešvietė savo trečdaliu, ir taip pat naktis.'),
  (@b66, 8, 13, 'Ir aš pažiūrėjau, ir išgirdau angelą, skrendantį dangaus viduriu, garsiu balsu sakantį: „Vargas, vargas, vargas žemės gyventojams dėl kitų trimito balsų tų trijų angelų, kurie dar turės trimituoti!“'),
  (@b66, 9, 1, 'Ir sutrimitavo penktasis angelas, ir mačiau žvaigždę, nukritusią iš dangaus į žemę; ir jai buvo duotas bedugnės duobės raktas.'),
  (@b66, 9, 2, 'Ir ji atidarė bedugnę duobę; ir iš duobės pakilo dūmai, kaip dūmai didelės krosnies; ir saulė bei oras aptemo nuo duobės dūmų.'),
  (@b66, 9, 3, 'Ir iš dūmų išėjo į žemę skėriai; ir jiems buvo duota valdžia, kokią valdžią turi žemės skorpionai.'),
  (@b66, 9, 4, 'Ir jiems buvo įsakyta, kad nekenktų žemės žolei nei kokiam žalumynui, nei kokiam medžiui; bet tik tiems žmonėms, kurie neturi Dievo antspaudo savo kaktose.'),
  (@b66, 9, 5, 'Ir jiems buvo duota, kad jų nežudytų, bet kad kankintų penkis mėnesius; ir jų kankinimas buvo kaip skorpiono kankinimas, kai jis įgelia žmogui.'),
  (@b66, 9, 6, 'Ir tomis dienomis žmonės ieškos mirties, ir jos neras; ir trokš mirti, bet mirtis bėgs nuo jų.'),
  (@b66, 9, 7, 'Ir tų skėrių išvaizda buvo panaši į žirgų, paruoštų mūšiui; ir ant jų galvų buvo tarsi vainikai, panašūs į auksą, ir jų veidai buvo kaip žmonių veidai.'),
  (@b66, 9, 8, 'Ir jie turėjo plaukus kaip moterų plaukai, ir jų dantys buvo kaip liūtų.'),
  (@b66, 9, 9, 'Ir jie turėjo krūtinšarvius lyg geležinius krūtinšarvius; ir jų sparnų garsas buvo kaip garsas vežimų daugybės žirgų, bėgančių į mūšį.'),
  (@b66, 9, 10, 'Ir jie turėjo uodegas, panašias į skorpionus, ir jų uodegose buvo geluonis; ir jų valdžia buvo kenkti žmonėms penkis mėnesius.'),
  (@b66, 9, 11, 'Ir jie turėjo sau karalių, bedugnės duobės angelą, kurio vardas hebrajiškai yra Abadonas, bet graikiškai turi vardą Apolionas.'),
  (@b66, 9, 12, 'Vienas vargas praėjo; ir štai po to ateina dar du vargai.'),
  (@b66, 9, 13, 'Ir sutrimitavo šeštasis angelas, ir išgirdau balsą iš keturių ragų auksinio aukuro, esančio Dievo akivaizdoje,'),
  (@b66, 9, 14, 'sakantį šeštajam angelui, turinčiam trimitą: „Paleisk keturis angelus, kurie yra surišti didžiojoje Eufrato upėje“.'),
  (@b66, 9, 15, 'Ir buvo paleisti keturi angelai, paruošti valandai ir dienai, ir mėnesiui, ir metams, kad išžudytų trečdalį žmonių.'),
  (@b66, 9, 16, 'Ir raitelių kariuomenės skaičius buvo du šimtai tūkstančių tūkstančiai; ir išgirdau jų skaičių.'),
  (@b66, 9, 17, 'Ir taip tame regėjime mačiau žirgus ir ant jų sėdinčius, turinčius krūtinšarvius ugnies ir hiacinto, ir sieros; o žirgų galvos buvo kaip liūtų galvos; ir iš jų nasrų ėjo ugnis ir dūmai, ir siera.'),
  (@b66, 9, 18, 'Šitais trim buvo nužudytas trečdalis žmonių: ugnimi ir dūmais, ir siera, kurie ėjo iš jų nasrų.'),
  (@b66, 9, 19, 'Nes jų jėga yra jų nasruose ir jų uodegose; nes jų uodegos buvo panašios į gyvates ir turėjo galvas, ir jomis jie kenkia.'),
  (@b66, 9, 20, 'O likusieji žmonės, kurie nebuvo šitomis rykštėmis užmušti, vis dar neatgailavo dėl savo rankų darbų, kad negarbintų velnių ir stabų iš aukso ir sidabro, ir žalvario, ir akmens, ir iš medžio – kurie nei matyti gali, nei girdėti, nei vaikščioti;'),
  (@b66, 9, 21, 'ir jie neatgailavo nei dėl savo žmogžudysčių, nei dėl savo burtininkavimų, nei dėl savo paleistuvystės, nei dėl savo vagysčių.'),
  (@b66, 10, 1, 'Ir mačiau kitą galingą angelą, nužengiantį iš dangaus, apsirengusį debesimi; ir virš jo galvos buvo vaivorykštė, o jo veidas buvo kaip saulė, ir jo kojos – kaip ugnies stulpai;'),
  (@b66, 10, 2, 'ir savo rankoje jis turėjo atverstą knygelę, ir jis padėjo savo dešinę koją ant jūros, o kairę ant žemės'),
  (@b66, 10, 3, 'ir šaukė garsiu balsu, kaip liūtas riaumoja; ir kai jis sušuko, septyni griaustiniai prabilo savo balsais.'),
  (@b66, 10, 4, 'Ir kai septyni griaustiniai prabilo savo balsais, aš rengiausi rašyti; ir išgirdau balsą iš dangaus man sakantį: „Užantspauduok tai, ką ištarė septyni griaustiniai, ir to nerašyk“.'),
  (@b66, 10, 5, 'Ir angelas, kurį regėjau stovintį ant jūros ir ant žemės, iškėlė savo ranką į dangų'),
  (@b66, 10, 6, 'ir prisiekė gyvenančiuoju per amžių amžius, kuris sutvėrė dangų ir tai, kas jame, ir žemę, ir tai, kas joje, ir jūrą, ir tai, kas joje, kad laiko daugiau nebebus;'),
  (@b66, 10, 7, 'bet septintojo angelo balso dienomis, kai jis pradės trimituoti, bus užbaigta Dievo paslaptis, kaip jis yra paskelbęs savo tarnams pranašams.'),
  (@b66, 10, 8, 'Ir balsas, kurį išgirdau iš dangaus, vėl man kalbėjo, ir tarė: „Eik, paimk tą knygelę, atverstą rankoje angelo, kuris stovi ant jūros ir ant žemės“.'),
  (@b66, 10, 9, 'Ir nuėjęs pas angelą, jam tariau: „Duok man tą knygelę“. Ir jis man tarė: „Imk ir ją suvalgyk; ir ji apkartins tavo pilvą, bet tavo burnoje ji bus saldi kaip medus“.'),
  (@b66, 10, 10, 'Ir aš paėmiau knygelę iš angelo rankos ir ją suvalgiau; ir mano burnoje ji buvo saldi kaip medus; ir kai tik ją suvalgiau, mano pilvas tapo kartus.'),
  (@b66, 10, 11, 'Ir jis man tarė: „Tu turi vėl pranašauti daugelio tautų ir tautybių, ir kalbų, ir karalių akivaizdoje“.'),
  (@b66, 11, 1, 'Ir man buvo duota nendrė, panaši į lazdą; ir angelas stovėjo, sakydamas: „Kelkis ir išmatuok Dievo šventyklą ir aukurą, ir tuos, kurie garbina joje.'),
  (@b66, 11, 2, 'Bet kiemą, esantį šventyklos išorėje, palik ir jo nematuok, nes jis yra duotas pagonims; ir jie tryps šventąjį miestą po kojomis keturiasdešimt du mėnesius.'),
  (@b66, 11, 3, 'Ir aš duosiu valdžią savo dviems liudytojams, ir jie pranašaus tūkstantį du šimtus šešiasdešimt dienų apsirengę ašutine“.'),
  (@b66, 11, 4, 'Šitie yra du alyvmedžiai ir dvi žvakidės, stovintys žemės Dievo akivaizdoje.'),
  (@b66, 11, 5, 'Ir jei kas norės jiems pakenkti, iš jų burnos išeina ugnis ir prarija jų priešus; ir jei kas norės jiems pakenkti, tas turės būti taip nužudytas.'),
  (@b66, 11, 6, 'Šitie turi valdžią užrakinti dangų, kad nelytų jų pranašavimo dienomis ir turi valdžią vandenims, paversti juos krauju ir ištikti žemę visomis rykštėmis tiek dažnai, kiek panorės.'),
  (@b66, 11, 7, 'Ir kai jie bus pabaigę savo liudijimą, prieš juos kariaus žvėris, kuris iškyla iš bedugnės duobės, ir juos nugalės, ir juos nužudys.'),
  (@b66, 11, 8, 'Ir jų lavonai gulės gatvėje didžiojo miesto, kuris dvasiškai vadinamas Sodoma ir Egiptu, kur buvo ir mūsų Viešpats nukryžiuotas.'),
  (@b66, 11, 9, 'Ir tie iš tautos ir giminių, ir kalbų, ir tautybių matys jų lavonus tris su puse dienos ir neleis jų lavonų padėti į kapus.'),
  (@b66, 11, 10, 'Ir gyvenantys žemėje džiaugsis dėl jų ir linksminsis, ir siųs vieni kitiems dovanas; nes tie du pranašai kankino tuos, kurie gyveno žemėje.'),
  (@b66, 11, 11, 'Ir po trijų su puse dienos į juos įėjo gyvybės Dvasia iš Dievo, ir jie atsistojo ant savo kojų; ir didelė baimė užgriuvo ant tų, kurie juos matė.'),
  (@b66, 11, 12, 'Ir jie išgirdo didį balsą iš dangaus jiems sakantį: „Užženkite šen“. Ir jie pakilo į dangų debesyje; ir jų priešai į juos žiūrėjo.'),
  (@b66, 11, 13, 'Ir tą pačią valandą buvo didelis žemės drebėjimas, ir dešimtadalis miesto sugriuvo, ir žemės drebėjime žuvo septyni tūkstančiai žmonių; o likusieji buvo išsigandę ir atidavė šlovę dangaus Dievui.'),
  (@b66, 11, 14, 'Praėjo antras vargas; ir štai greitai ateina trečiasis vargas.'),
  (@b66, 11, 15, 'Ir sutrimitavo septintasis angelas; ir danguje buvo galingi balsai, sakantys: „Šio pasaulio karalystės tapo mūsų Viešpaties ir jo Kristaus karalystėmis; ir jis karaliaus per amžių amžius“.'),
  (@b66, 11, 16, 'Ir dvidešimt keturi vyresnieji, sėdintys savo sostuose Dievo akivaizdoje, parpuolė savo veidais žemėn ir garbino Dievą,'),
  (@b66, 11, 17, 'sakydami: „Dėkojame tau, o Viešpatie Dieve Visagali, kuris esi ir buvai, ir ateini; nes pasiėmei savo didžiąją galią ir karaliavai.'),
  (@b66, 11, 18, 'Ir tautos įpyko, ir atėjo tavo rūstybė bei mirusiųjų metas, kad jie būtų teisiami, ir kad duotum atlygį savo tarnams pranašams ir šventiesiems, ir bijantiems tavo vardo, mažiems ir dideliems; ir kad sunaikintum tuos, kurie naikina žemę“.'),
  (@b66, 11, 19, 'Ir danguje atsivėrė Dievo šventykla, ir jo šventykloje matėsi jo testamento skrynia; ir buvo žaibai ir balsai, ir griaustiniai, ir žemės drebėjimas, ir didžiulė kruša.'),
  (@b66, 12, 1, 'Ir danguje pasirodė didelis ženklas: moteris, apsirengusi saule, ir mėnulis po jos kojomis, ir ant jos galvos – dvylikos žvaigždžių vainikas;'),
  (@b66, 12, 2, 'ir ji, būdama nėščia, šaukė, kentėdama gimdymo skausmus ir sąrėmius, kad pagimdytų.'),
  (@b66, 12, 3, 'Ir pasirodė danguje kitas ženklas: ir štai didelis raudonas slibinas, turintis septynias galvas ir dešimt ragų, ir septynias karūnas ant savo galvų.'),
  (@b66, 12, 4, 'Ir jo uodega patraukė trečdalį dangaus žvaigždžių ir numetė jas į žemę; ir slibinas stovėjo prieš moterį, kuri buvo bepagimdanti, kad prarytų jos vaiką, kai tik jis gims.'),
  (@b66, 12, 5, 'Ir ji pagimdė vyriškos lyties vaiką, kuris turėjo valdyti visas tautas geležine lazda; ir jos vaikas buvo paimtas pas Dievą ir į jo sostą.'),
  (@b66, 12, 6, 'Ir ta moteris pabėgo į dykumą, kur ji turi Dievo paruoštą vietą, kad ten ją maitintų tūkstantį du šimtus šešiasdešimt dienų.'),
  (@b66, 12, 7, 'Ir danguje buvo karas: Mykolas ir jo angelai kovojo prieš slibiną; ir slibinas kovojo bei jo angelai,'),
  (@b66, 12, 8, 'bet nenugalėjo; nei nebebuvo rasta jų vieta danguje.'),
  (@b66, 12, 9, 'Ir buvo išmestas tas didysis slibinas, ta sena gyvatė, vadinama velniu ir šėtonu, kuris suklaidina visą pasaulį; jis buvo išmestas į žemę, ir jo angelai buvo išmesti su juo.'),
  (@b66, 12, 10, 'Ir aš išgirdau garsų balsą, kalbantį danguje: „Dabar atėjo išgelbėjimas ir stiprybė, ir mūsų Dievo karalystė, ir jo Kristaus valdžia; nes išmestas žemyn mūsų brolių kaltintojas, kuris kaltino juos mūsų Dievo akivaizdoje dieną ir naktį.'),
  (@b66, 12, 11, 'Ir jie nugalėjo jį Avinėlio krauju ir savo liudijimo žodžiu; ir jie nemylėjo savo gyvybių iki mirties.'),
  (@b66, 12, 12, 'Todėl džiaukitės, dangūs ir juose gyvenantys. Vargas žemės ir jūros gyventojams! Nes pas jus nusileido velnias, kupinas didelės rūstybės, nes žino, kad teturi mažai laiko.'),
  (@b66, 12, 13, 'Ir kai slibinas pamatė, kad buvo numestas į žemę, jis persekiojo tą moterį, kuri pagimdė vyriškos lyties vaiką.'),
  (@b66, 12, 14, 'Ir moteriai buvo duoti du didžiojo erelio sparnai, kad nuo gyvatės veido nuskristų į dykumą, į jos vietą, kur ji bus maitinama laiką ir laikus, ir pusę laiko.'),
  (@b66, 12, 15, 'Ir gyvatė iš savo nasrų paskui moterį išleido vandenį kaip upę, kad nuplukdytų ją srove.'),
  (@b66, 12, 16, 'O žemė padėjo moteriai, ir žemė atvėrė savo burną ir prarijo upę, kurią slibinas išleido iš savo burnos.'),
  (@b66, 12, 17, 'Ir slibinas užsirūstino ant moters, ir nuėjo kariauti su jos sėklos likučiu, kuris laikosi Dievo įsakymų ir turi Jėzaus Kristaus liudijimą.'),
  (@b66, 13, 1, 'Ir aš stovėjau ant jūros smėlio ir mačiau iš jūros iškylantį žvėrį, turintį septynias galvas ir dešimt ragų, o ant jo ragų dešimt karūnų, ir ant jo galvų piktžodžiavimo vardą.'),
  (@b66, 13, 2, 'Ir žvėris, kurį mačiau, buvo panašus į leopardą, ir jo kojos buvo kaip meškos, ir jo nasrai kaip liūto nasrai; ir slibinas davė jam savo jėgą ir savo sostą, ir didelę valdžią.'),
  (@b66, 13, 3, 'Ir mačiau vieną iš jo galvų lyg mirtinai sužeistą; ir jo mirtina žaizda užgijo; ir visas pasaulis stebėdamasis nusekė paskui žvėrį.'),
  (@b66, 13, 4, 'Ir jie garbino slibiną, kuris davė valdžią žvėriui; ir jie garbino žvėrį, sakydami: „Kas yra lygus žvėriui? Kas pajėgus su juo kariauti?“'),
  (@b66, 13, 5, 'Ir jam buvo duota burna, kalbanti didybes ir piktžodžiavimus; ir jam buvo duota valdžia pasilikti keturiasdešimt du mėnesius.'),
  (@b66, 13, 6, 'Ir jis atvėrė savo burną piktžodžiavimui prieš Dievą, piktžodžiauti jo vardui ir jo padangtei, ir tiems, kurie gyvena danguje.'),
  (@b66, 13, 7, 'Ir jam buvo duota kariauti su šventaisiais ir juos nugalėti; ir jam buvo duota valdžia visoms giminėms ir kalboms, ir tautoms.'),
  (@b66, 13, 8, 'Ir garbins jį visi gyvenantys žemėje, kurių vardai nėra įrašyti gyvenimo knygoje Avinėlio, užmušto nuo pasaulio įkūrimo.'),
  (@b66, 13, 9, 'Jei kas turi ausis, teklauso.'),
  (@b66, 13, 10, 'Kas veda į nelaisvę, tas eis į nelaisvę; kas žudo kalaviju, turės būti nužudytas kalaviju. Štai šventųjų kantrybė ir tikėjimas.'),
  (@b66, 13, 11, 'Ir mačiau kitą žvėrį, ateinantį aukštyn iš žemės; ir jis turėjo du ragus kaip avinėlis, ir jis kalbėjo kaip slibinas.'),
  (@b66, 13, 12, 'Ir jis vykdo visą pirmojo žvėries valdžią jo akivaizdoje ir verčia žemę bei joje gyvenančius garbinti pirmąjį žvėrį, kurio mirtina žaizda buvo sugijusi.'),
  (@b66, 13, 13, 'Ir jis daro didžius stebuklus taip, kad žmonių akivaizdoje nuleidžia ugnį iš dangaus į žemę'),
  (@b66, 13, 14, 'ir klaidina gyvenančius žemėje tais stebuklais, kuriuos jis turi galią daryti žvėries akivaizdoje; sakydamas gyvenantiems žemėje, kad jie padarytų atvaizdą žvėriui, kuris turėjo žaizdą nuo kalavijo ir gyveno.'),
  (@b66, 13, 15, 'Ir jis turėjo galią duoti žvėries atvaizdui gyvybę, kad žvėries atvaizdas ir kalbėtų, ir padarytų, kad visi, kurie negarbins žvėries atvaizdo, būtų nužudyti.'),
  (@b66, 13, 16, 'Ir jis daro, kad visi, ir maži, ir dideli, turtingi ir vargšai, laisvi ir vergai imtų ženklą į savo dešinę ranką arba į savo kaktas;'),
  (@b66, 13, 17, 'ir kad niekas negalėtų pirkti ar parduoti išskyrus tą, kuris turi ženklą ar žvėries vardą, ar jo vardo skaičių.'),
  (@b66, 13, 18, 'Čia yra išmintis. Kas turi supratimą, teapskaičiuoja žvėries skaičių, nes tai yra žmogaus skaičius; ir jo skaičius yra šeši šimtai šešiasdešimt šeši.'),
  (@b66, 14, 1, 'Ir aš pažiūrėjau, ir štai Avinėlis stovėjo ant Siono kalno, o su juo šimtas keturiasdešimt keturi tūkstančiai, turintys jo Tėvo vardą, įrašytą jų kaktose.'),
  (@b66, 14, 2, 'Ir girdėjau balsą iš dangaus, kaip daugelio vandenų balsą ir kaip galingo griaustinio balsą; ir girdėjau balsą arfininkų, skambinančių savo arfomis;'),
  (@b66, 14, 3, 'ir jie giedojo tarsi naują giesmę priešais sostą ir priešais keturis žvėris ir vyresniuosius; ir niekas negalėjo išmokti tos giesmės, tik šimtas keturiasdešimt keturi tūkstančiai, kurie buvo atpirkti iš žemės.'),
  (@b66, 14, 4, 'Šitie yra tie, kurie nesusiteršė su moterimis; nes jie yra mergelės. Šitie yra tie, kurie seka paskui Avinėlį, kur tik jis eina. Šitie buvo atpirkti iš žmonių tarpo, būdami pirmavaisiai Dievui ir Avinėliui.'),
  (@b66, 14, 5, 'Ir jų burnoje nebuvo rasta apgaulės, nes jie yra be kaltės prieš Dievo sostą.'),
  (@b66, 14, 6, 'Ir mačiau kitą angelą, skrendantį dangaus viduriu, turintį amžinąją evangeliją, kad skelbtų gyvenantiems žemėje ir kiekvienai tautybei ir giminei, ir kalbai, ir tautai,'),
  (@b66, 14, 7, 'sakantį garsiu balsu: „Bijokite Dievo ir atiduokite jam šlovę; nes atėjo jo teismo valanda; ir garbinkite tą, kuris padarė dangų ir žemę, ir jūrą, ir vandenų šaltinius“.'),
  (@b66, 14, 8, 'Ir sekė kitas angelas, sakydamas: „Krito, krito Babilonas, tas didysis miestas, nes jis prigirdė visas tautas savo paleistuvystės rūstybės vynu“.'),
  (@b66, 14, 9, 'Ir paskui juos sekė trečiasis angelas, sakydamas garsiu balsu: „Jei kas garbina žvėrį bei jo atvaizdą ir ima jo ženklą į savo kaktą ar į savo ranką,'),
  (@b66, 14, 10, 'tas gers Dievo rūstybės vyno, kuris be priemaišų išpiltas į jo pasipiktinimo taurę, ir bus kankinamas ugnimi ir siera šventųjų angelų akivaizdoje ir Avinėlio akivaizdoje;'),
  (@b66, 14, 11, 'ir jų kankinimo dūmai kyla aukštyn per amžių amžius; ir neturi poilsio nei dieną, nei naktį tie, kurie garbina žvėrį ir jo atvaizdą, ir kurie ima jo vardo ženklą.'),
  (@b66, 14, 12, 'Štai šventųjų kantrybė – štai tie, kurie laikosi Dievo įsakymų ir Jėzaus tikėjimo“.'),
  (@b66, 14, 13, 'Ir girdėjau balsą iš dangaus man sakantį: „Rašyk: ‘Palaiminti mirusieji, kurie nuo šiol miršta Viešpatyje; taip, – sako Dvasia, – kad jie ilsėtųsi nuo savo triūso; ir jų darbai seka jais’“.'),
  (@b66, 14, 14, 'Ir pasižiūrėjau, ir štai baltas debesis, o ant debesies sėdėjo vienas, panašus į žmogaus Sūnų, ant savo galvos turintis auksinį vainiką, o savo rankoje – aštrų pjautuvą.'),
  (@b66, 14, 15, 'Ir kitas angelas išėjo iš šventyklos, šaukdamas garsiu balsu sėdinčiajam ant debesies: „Įmesk savo pjautuvą ir pjauk, nes atėjo laikas tau pjauti; nes žemės derlius prinokęs“.'),
  (@b66, 14, 16, 'Ir sėdintysis ant debesies įmetė savo pjautuvą ant žemės; ir žemė buvo nupjauta.'),
  (@b66, 14, 17, 'Ir kitas angelas išėjo iš šventyklos, esančios danguje, jis irgi turėjo aštrų pjautuvą.'),
  (@b66, 14, 18, 'Ir nuo aukuro išėjo kitas angelas, turintis valdžią ugniai; ir šaukė garsiu balsu turinčiam aštrų pjautuvą, sakydamas: „Įmesk savo aštrų pjautuvą ir nurink žemės vynmedžio kekes; nes jo vynuogės pilnai prinokusios“.'),
  (@b66, 14, 19, 'Ir tas angelas įmetė savo pjautuvą į žemę ir nurinko žemės vynmedį, ir įmetė tai į didįjį Dievo rūstybės vyno spaustuvą.'),
  (@b66, 14, 20, 'Ir tas vyno spaustuvas buvo minamas už miesto, ir iš spaustuvo išėjo kraujas, net iki arklių žąslų, tūkstančio ir šešių šimtų furlongų atstumu.'),
  (@b66, 15, 1, 'Ir mačiau kitą ženklą danguje, didį ir nuostabų: septynis angelus, turinčius septynias paskutines rykštes; nes jomis užsibaigė Dievo rūstybė.'),
  (@b66, 15, 2, 'Ir mačiau tarsi stiklo jūrą, sumaišytą su ugnimi, ir nugalėjusius žvėrį ir jo atvaizdą, ir jo ženklą, ir jo vardo skaičių, stovinčius ant stiklo jūros, turinčius Dievo arfas.'),
  (@b66, 15, 3, 'Ir jie gieda Dievo tarno Mozės giesmę ir Avinėlio giesmę, sakydami: „Dideli ir nuostabūs tavo darbai, Viešpatie, Visagali Dieve; teisūs ir tikri tavo keliai, šventųjų Karaliau.'),
  (@b66, 15, 4, 'Kas gi tavęs nebijos, o Viešpatie, ir nešlovins tavo vardo? Nes tu vienintelis esi šventas, nes visos tautos ateis ir garbins tavo akivaizdoje; nes tavo teismai tapo aiškūs“.'),
  (@b66, 15, 5, 'Ir po to pažiūrėjau, ir štai atsidarė liudijimo padangtės šventykla danguje;'),
  (@b66, 15, 6, 'ir iš šventyklos išėjo septyni angelai, turintys septynias rykštes, apsirengę tyra ir balta drobe ir krūtines apsijuosę auksinėmis juostomis.'),
  (@b66, 15, 7, 'Ir vienas iš keturių žvėrių davė septyniems angelams septynis auksinius butelius, pilnus per amžių amžius gyvenančio Dievo rūstybės.'),
  (@b66, 15, 8, 'Ir šventykla prisipildė dūmų nuo Dievo šlovės ir nuo jo galios; ir niekas negalėjo įeiti į šventyklą, kol nesibaigė septynių angelų septynios rykštės.'),
  (@b66, 16, 1, 'Ir girdėjau iš šventyklos stiprų balsą, sakantį septyniems angelams: „Eikite ir išpilkite Dievo rūstybės butelius į žemę“.'),
  (@b66, 16, 2, 'Ir pirmasis nuėjo ir išpylė savo butelį į žemę; ir ištiko kenksminga ir skaudi žaizda žmones, turinčius žvėries ženklą ir garbinančius jo atvaizdą.'),
  (@b66, 16, 3, 'Ir antrasis angelas išpylė savo butelį į jūrą; ir ji tapo kaip numirėlio kraujas; ir jūroje mirė kiekviena gyva siela.'),
  (@b66, 16, 4, 'Ir trečiasis angelas išpylė savo butelį į upes ir vandenų šaltinius; ir jie tapo krauju.'),
  (@b66, 16, 5, 'Ir girdėjau vandenų angelą sakant: „Tu esi teisus, o Viešpatie, kuris esi ir buvai, ir būsi, nes taip teisei.'),
  (@b66, 16, 6, 'Nes jie išliejo šventųjų ir pranašų kraują, ir tu jiems davei gerti kraują; nes jie yra verti“.'),
  (@b66, 16, 7, 'Ir girdėjau kitą, nuo aukuro sakant: „Būtent taip, Viešpatie, Visagali Dieve, tikri ir teisūs yra tavo teismai“.'),
  (@b66, 16, 8, 'Ir ketvirtasis angelas išliejo savo butelį į saulę; ir jai buvo duota valdžia svilinti žmones ugnimi.'),
  (@b66, 16, 9, 'Ir žmonės buvo svilinami didžiule kaitra ir piktžodžiavo vardui Dievo, kuris turi valdžią šitoms rykštėms; ir jie neatgailavo, kad atiduotų jam šlovę.'),
  (@b66, 16, 10, 'Ir penktasis angelas išpylė savo butelį ant žvėries sosto; ir jo karalystė buvo pilna tamsos; ir jie kramtė savo liežuvius iš skausmo,'),
  (@b66, 16, 11, 'ir piktžodžiavo dangaus Dievui dėl savo skausmų bei savo žaizdų, ir neatgailavo dėl savo darbų.'),
  (@b66, 16, 12, 'Ir šeštasis angelas išpylė savo butelį į didžiąją Eufrato upę; ir jos vanduo išdžiūvo, kad būtų paruoštas rytų karalių kelias.'),
  (@b66, 16, 13, 'Ir aš mačiau tris nešvarias dvasias, panašias į varles, išeinančias iš slibino burnos ir iš žvėries burnos, ir iš netikrojo pranašo burnos.'),
  (@b66, 16, 14, 'Nes jos yra velnių dvasios, darančios stebuklus, kurios išeina pas žemės ir viso pasaulio karalius, surinkti juos į Visagalio Dievo tos didžiosios dienos mūšį.'),
  (@b66, 16, 15, '„Štai aš ateinu kaip vagis. Palaimintas, kas budi ir saugo savo drabužius, kad nevaikščiotų nuogas, ir jie nepamatytų jo gėdos“.'),
  (@b66, 16, 16, 'Ir jis surinko juos į vietą, hebrajiškai vadinamą Armagedonu.'),
  (@b66, 16, 17, 'Ir septintasis angelas išpylė savo butelį į orą; ir iš dangaus šventyklos, nuo sosto, atėjo stiprus balsas, sakantis: „Atlikta“.'),
  (@b66, 16, 18, 'Ir buvo balsai ir griaustiniai, ir žaibai; ir buvo didelis žemės drebėjimas, kokio nebuvo nuo tada, kai žmonės buvo žemėje, toks galingas žemės drebėjimas, toks didelis.'),
  (@b66, 16, 19, 'Ir didysis miestas suskilo į tris dalis, ir tautų miestai sugriuvo; ir didysis Babilonas atėjo atmintin prieš Dievą, kad jam duotų savo rūstybės įniršio vyno taurę.'),
  (@b66, 16, 20, 'Ir kiekviena sala pabėgo, ir nebuvo rasta kalnų.'),
  (@b66, 16, 21, 'Ir ant žmonių iš dangaus krito didžiulė kruša, kiekvienas ledokšnis apie talentą svorio; ir žmonės piktžodžiavo Dievui dėl krušos rykštės; nes jos rykštė buvo nepaprastai sunki.'),
  (@b66, 17, 1, 'Ir atėjo vienas iš septynių angelų, turinčių septynis butelius, ir kalbėjo su manimi, man sakydamas: „Ateik čia; aš tau parodysiu teismą tos didžiosios paleistuvės, sėdinčios ant daugybės vandenų;'),
  (@b66, 17, 2, 'su kuria žemės karaliai paleistuvavo, ir žemės gyventojai buvo pasigėrę jos paleistuvavimo vynu“.'),
  (@b66, 17, 3, 'Taigi jis dvasioje nunešė mane į dykumą; ir mačiau moterį, sėdinčią ant skaisčiai raudonos spalvos žvėries, pilno piktžodžiavimo vardų, turinčio septynias galvas ir dešimt ragų.'),
  (@b66, 17, 4, 'Ir moteris buvo apsirengusi purpurine bei skaisčiai raudona spalva ir pasipuošusi auksu ir brangakmeniais, ir perlais, savo rankoje turinti auksinę taurę, pilną savo paleistuvystės bjaurybių ir nešvarumų;'),
  (@b66, 17, 5, 'ir ant jos kaktos buvo užrašytas vardas: „PASLAPTIS, DIDYSIS BABILONAS, ŽEMĖS PALEISTUVIŲ IR BJAURYBIŲ MOTINA“.'),
  (@b66, 17, 6, 'Ir mačiau tą moterį, girtą nuo šventųjų kraujo ir nuo Jėzaus kankinių kraujo; ir ją pamatęs stebėjausi didele nuostaba.'),
  (@b66, 17, 7, 'Ir angelas man tarė: „Kodėl stebėjaisi? Aš tau pasakysiu paslaptį tos moters ir ją nešančio žvėries, kuris turi septynias galvas ir dešimt ragų.'),
  (@b66, 17, 8, 'Žvėris, kurį matei, buvo ir nėra; ir pakils iš bedugnės duobės, ir eis į pražūtį; ir gyvenantys žemėje, kurių vardai nuo pasaulio įkūrimo nebuvo įrašyti gyvenimo knygoje, stebėsis, žiūrėdami į žvėrį, kuris buvo ir nėra, ir vis dėlto yra.'),
  (@b66, 17, 9, 'Ir štai protas, turintis išmintį. Septynios galvos yra septyni kalnai, ant kurių sėdi moteris.'),
  (@b66, 17, 10, 'Ir yra septyni karaliai: penki kritę, ir vienas yra, o kitas dar neatėjęs; ir kai jis ateis, turės trumpam pasilikti.'),
  (@b66, 17, 11, 'O žvėris, kuris buvo ir nėra, – jis yra aštuntasis ir yra iš septynių, ir eina į pražūtį.'),
  (@b66, 17, 12, 'O dešimt ragų, kuriuos matei, yra dešimt karalių, kurie dar nėra gavę karalystės; bet gaus valdžią kaip karaliai vienai valandai su žvėrimi.'),
  (@b66, 17, 13, 'Šitie turi vieną mintį, ir duos savo valdžią bei jėgą žvėriui.'),
  (@b66, 17, 14, 'Šitie kariaus su Avinėliu, ir Avinėlis juos nugalės, nes jis yra viešpačių Viešpats, ir karalių Karalius; ir su juo esantys yra pašaukti ir išrinkti, ir ištikimi.'),
  (@b66, 17, 15, 'Ir jis man sako: „Vandenys, kuriuos matei, kur sėdi ta paleistuvė, yra žmonės ir minios, ir tautos, ir kalbos.'),
  (@b66, 17, 16, 'O dešimt ragų, kuriuos matei ant žvėries, šitie nekęs paleistuvės ir nuniokos ją ir padarys nuogą, ir ės jos kūną, ir sudegins ją ugnimi.'),
  (@b66, 17, 17, 'Nes Dievas į jų širdis įdėjo išpildyti jo valią ir sutarti, ir duoti savo karalystę žvėriui, kol išsipildys Dievo žodžiai.'),
  (@b66, 17, 18, 'O moteris, kurią matei, yra tas didysis miestas, kuris viešpatauja žemės karaliams“.'),
  (@b66, 18, 1, 'Ir po šių dalykų mačiau kitą angelą, nusileidžiantį iš dangaus, turintį didelę valdžią; ir žemė buvo apšviesta jo šlovės.'),
  (@b66, 18, 2, 'Ir jis galingai šaukė stipriu balsu, sakydamas: „Krito, krito didysis Babilonas ir tapo velnių buveine ir kiekvienos nešvarios dvasios kalėjimu, ir kiekvieno nešvaraus bei nekenčiamo paukščio narvu.'),
  (@b66, 18, 3, 'Nes visos tautos gėrė jo paleistuvystės rūstybės vyno, ir žemės karaliai su juo paleistuvavo, ir žemės pirkliai pralobo iš jo prabangos gausumo“.'),
  (@b66, 18, 4, 'Ir aš girdėjau kitą balsą iš dangaus, sakantį: „Išeik iš jo, mano tauta, kad nebūtumei jo nuodėmių dalininkė ir kad negautumei jo rykščių.'),
  (@b66, 18, 5, 'Nes jo nuodėmės pasiekė dangų, ir Dievas prisiminė jo neteisybes.'),
  (@b66, 18, 6, 'Atlyginkite jam taip, kaip jis jums atlygino, ir atiduokite jam dvigubai pagal jo darbus: į tą taurę, kurią jis pripylė, pripilkite jam dvigubai.');
INSERT INTO bible_verses (BOOK_ID, CHAPTER_NUM, VERSE_NUM, TEXT) VALUES
  (@b66, 18, 7, 'Kiek jis save šlovino ir prabangiai gyveno, tiek jam duokite kančios ir liūdesio, nes jis sako savo širdyje: ‘Aš sėdžiu karalienė ir nesu našlė, ir nematysiu liūdesio’.'),
  (@b66, 18, 8, 'Todėl vieną dieną ateis jo rykštės: mirtis ir gedulas, ir badas; ir jis visiškai bus sudegintas ugnimi, nes stiprus yra Viešpats Dievas, kuris jį teisia.'),
  (@b66, 18, 9, 'Ir žemės karaliai, paleistuvavę ir gyvenę prabangiai su juo, jį apraudos ir dėl jo verks, kai pamatys jo degimo dūmus,'),
  (@b66, 18, 10, 'stovėdami iš tolo, iš baimės dėl jo kančios, sakydami: ‘Bėda, bėda, tas didysis mieste Babilone, tas galingasis mieste! Nes per vieną valandą atėjo tavo teismas’.'),
  (@b66, 18, 11, 'Ir žemės pirkliai verks ir gedės jo; nes niekas nebeperka jų prekių:'),
  (@b66, 18, 12, 'prekių iš aukso ir sidabro, ir brangakmenių, ir iš perlų, ir plonos drobės, ir purpuro, ir šilko, ir skaisčiai raudonos, ir visokio tujinio medžio, ir visokių dramblio kaulo indų, ir visokių indų iš brangiausio medžio, ir iš žalvario, ir geležies, ir marmuro,'),
  (@b66, 18, 13, 'ir cinamono, ir kvepalų, ir tepalų, ir smilkalų, ir vyno, ir aliejaus, ir smulkių miltų, ir kviečių, ir gyvulių, ir avių, ir žirgų, ir vežimų, ir vergų, ir žmonių sielų.'),
  (@b66, 18, 14, 'Ir vaisiai, kurių tavo siela geidė, pasitraukę nuo tavęs, ir visa, kas buvo skoninga ir gražu, yra pasitraukę nuo tavęs, ir tu jų visai neberasi.'),
  (@b66, 18, 15, 'Per jį pralobę šitų dalykų pirkliai stovės iš tolo, iš baimės dėl jo kančios, verkdami ir aimanuodami,'),
  (@b66, 18, 16, 'ir sakydami: ‘Bėda, bėda, tas didysis miestas, kuris buvo apsirengęs plona drobe ir purpuru, ir skaisčiai raudona, ir pasipuošęs auksu, ir brangakmeniais, ir perlais!'),
  (@b66, 18, 17, 'Nes per vieną valandą niekais virto tokie didžiuliai turtai’. Ir kiekvienas laivo kapitonas, ir visos įgulos laivuose, ir jūreiviai, ir visi besiverčiantys iš jūros, stovėjo iš tolo'),
  (@b66, 18, 18, 'ir, žiūrėdami į jo degimo dūmus, šaukė sakydami: ‘Koks miestas prilygsta šitam didžiajam miestui!’'),
  (@b66, 18, 19, 'Ir jie bėrė dulkes ant savo galvų ir šaukė verkdami ir aimanuodami, sakydami: ‘Bėda, bėda, tas didysis miestas, kuriame praturtėjo visi, turėję jūroje laivus, iš jo brangumo! Nes per vieną valandą jis tapo nuniokotas’.'),
  (@b66, 18, 20, 'Džiaukis dėl jo, dangau, ir jūs, šventi apaštalai ir pranašai; nes Dievas jam atkeršijo už jus“.'),
  (@b66, 18, 21, 'Ir galingas angelas iškėlė akmenį, lyg didžiulį girnų akmenį, ir įmetė į jūrą, sakydamas: „Taip su smarkumu bus sugriautas tas didysis miestas Babilonas ir daugiau nebebus rastas.'),
  (@b66, 18, 22, 'Ir arfininkų, ir muzikantų, ir dūduotojų, ir trimituotojų balso daugiau nebesigirdės tavyje; ir jokio kokio nors amato amatininko daugiau nebebus rasta tavyje; ir girnos akmens garso daugiau nebesigirdės tavyje;'),
  (@b66, 18, 23, 'ir žvakės šviesa daugiau nebešvies tavyje; ir jaunikio bei jaunosios balso daugiau nebesigirdės tavyje; nes tavo pirkliai buvo žemės didžiūnai; nes tavo burtais buvo suklaidintos visos tautos.'),
  (@b66, 18, 24, 'Ir jame buvo rastas pranašų ir šventųjų, ir visų žemėje nužudytųjų kraujas“.'),
  (@b66, 19, 1, 'Ir po šių dalykų girdėjau stiprų gausios liaudies balsą danguje, sakantį: „Aleliuja! Išgelbėjimas ir šlovė, ir garbė, ir jėga Viešpačiui, mūsų Dievui;'),
  (@b66, 19, 2, 'nes tikri ir teisūs jo teismai, nes jis nuteisė tą didžiąją paleistuvę, kuri sugadino žemę savo paleistuvyste, ir atkeršijo už jo tarnų kraują iš jos rankos“.'),
  (@b66, 19, 3, 'Ir vėl jie tarė: „Aleliuja!“ Ir jos dūmai kilo per amžių amžius.'),
  (@b66, 19, 4, 'Ir dvidešimt keturi vyresnieji bei keturi žvėrys parpuolė ir pagarbino Dievą, sėdintį soste, sakydami: „Amen! Aleliuja!“'),
  (@b66, 19, 5, 'Ir nuo sosto nuėjo balsas, sakydamas: „Girkite mūsų Dievą, visi jo tarnai ir kurie jo bijote, tiek maži, tiek dideli“.'),
  (@b66, 19, 6, 'Ir aš girdėjau tarsi didelės minios balsą, ir kaip daugybės vandenų balsą, ir kaip galingų griaustinių balsą, sakantį: „Aleliuja, nes viešpatauja Viešpats Dievas visagalis.'),
  (@b66, 19, 7, 'Linksminkimės ir džiūgaukime, ir duokime jam garbę“; nes atėjo Avinėlio vestuvės, ir jo žmona pasiruošė.'),
  (@b66, 19, 8, 'Ir jai buvo duota apsirengti plona drobe, švaria ir balta, nes plona drobė tai šventųjų teisumas.'),
  (@b66, 19, 9, 'Ir jis man sako: „Rašyk: ‘Palaiminti, kurie pašaukti į Avinėlio vestuvių vakarienę’“. Ir jis man sako: „Šitie yra tikri Dievo pasakymai“.'),
  (@b66, 19, 10, 'Ir aš parpuoliau prie jo kojų jo pagarbinti. O jis man tarė: „Žiūrėk, to nedaryk; aš esu tavo bendratarnis ir tavo brolių, turinčių Jėzaus liudijimą; Dievą garbink; nes Jėzaus liudijimas yra pranašystės dvasia“.'),
  (@b66, 19, 11, 'Ir mačiau atvirą dangų, ir štai baltas žirgas; ir ant jo sėdintysis buvo vadinamas Ištikimasis ir Tikrasis, ir teisumu jis teisia bei kariauja.'),
  (@b66, 19, 12, 'Jo akys buvo kaip ugnies liepsna, ir ant jo galvos buvo daug karūnų; ir jis turėjo užrašytą vardą, kurio niekas nežinojo, tik jis pats.'),
  (@b66, 19, 13, 'Ir jis buvo apsirengęs rūbais, pamirkytais kraujyje; ir jo vardas yra vadinamas Dievo Žodžiu.'),
  (@b66, 19, 14, 'Ir kariuomenės, esančios danguje, sekė paskui jį ant baltų žirgų, apsirengusios plona drobe, balta ir švaria.'),
  (@b66, 19, 15, 'Ir iš jo burnos eina aštrus kalavijas, kad jis juo suduotų tautoms; ir jis jas valdys geležine lazda; ir jis mina Visagalio Dievo įniršio ir rūstybės vyno spaustuvą.'),
  (@b66, 19, 16, 'Ir ant savo drabužio ir savo šlaunies jis turi užrašytą vardą: „KARALIŲ KARALIUS IR VIEŠPAČIŲ VIEŠPATS“.'),
  (@b66, 19, 17, 'Ir aš mačiau angelą, stovintį saulėje; ir jis šaukė garsiu balsu, sakydamas visiems skrajūnams, skraidantiems dangaus viduriu: „Ateikite, susirinkite į didžiojo Dievo vakarienę;'),
  (@b66, 19, 18, 'kad valgytumėte karalių kūnus ir vadų kūnus, ir galiūnų kūnus, ir žirgų bei ant jų sėdinčiųjų kūnus, ir visų laisvųjų ir vergų, mažų ir didelių kūnus“.'),
  (@b66, 19, 19, 'Ir mačiau žvėrį ir žemės karalius, ir jų kariuomenes, susirinkusius kariauti prieš sėdintįjį ant žirgo, ir prieš jo kariuomenę.'),
  (@b66, 19, 20, 'Ir buvo paimtas žvėris ir su juo netikrasis pranašas, kuris darė stebuklus jo akivaizdoje, kuriais jis suklaidino tuos, kurie buvo ėmę žvėries ženklą, ir tuos, kurie garbino jo atvaizdą. Jiedu buvo gyvi įmesti į ugnies ežerą, degantį siera.'),
  (@b66, 19, 21, 'O likusieji buvo užmušti kalaviju to, kuris sėdėjo ant žirgo, ir tas kalavijas ėjo iš jo burnos; ir visi skrajūnai prisisotino jų kūnais.'),
  (@b66, 20, 1, 'Ir mačiau angelą, nužengiantį iš dangaus, turintį bedugnės duobės raktą ir didžiulę grandinę savo rankoje.'),
  (@b66, 20, 2, 'Ir jis čiupo slibiną, tą seną gyvatę, kuri yra velnias ir šėtonas, ir surišo jį tūkstančiui metų,'),
  (@b66, 20, 3, 'ir įmetė jį į bedugnę duobę, ir jį užrakino, ir užantspaudavo viršum jo, kad jis nebeklaidintų tautų, kol išsipildys tūkstantis metų; o po to jis turės būti trumpam laikotarpiui paleistas.'),
  (@b66, 20, 4, 'Ir mačiau sostus, ir jie sėdėjo juose, ir jiems buvo duota teisti; ir mačiau sielas tų, kuriems buvo nukirstos galvos dėl Jėzaus liudijimo ir dėl Dievo žodžio, ir kurie negarbino žvėries nei jo atvaizdo, nei neėmė jo ženklo ant savo kaktų ar į savo rankas; ir jie gyveno ir karaliavo su Kristumi tūkstantį metų.'),
  (@b66, 20, 5, 'Bet likę mirusieji neatgijo iki pasibaigs tūkstantis metų. Šis yra pirmasis prisikėlimas.'),
  (@b66, 20, 6, 'Palaimintas ir šventas tas, kuris turi dalį pirmajame prisikėlime; šitiems antroji mirtis neturi valdžios, bet jie bus Dievo ir Kristaus kunigai ir karaliaus su juo tūkstantį metų.'),
  (@b66, 20, 7, 'Ir kai tūkstantis metų pasibaigs, šėtonas bus išleistas iš savo kalėjimo'),
  (@b66, 20, 8, 'ir išeis suklaidinti tautų, esančių keturiuose žemės kampuose, Gogo ir Magogo, surinkti juos į mūšį; kurių skaičius yra kaip jūros smilčių.'),
  (@b66, 20, 9, 'Ir jie ėjo aukštyn ant žemės platumos ir apsupo šventųjų stovyklą ir mylimąjį miestą; ir nuo Dievo iš dangaus nužengė ugnis ir juos prarijo.'),
  (@b66, 20, 10, 'O juos klaidinęs velnias buvo įmestas į ugnies ir sieros ežerą, kur yra žvėris ir netikrasis pranašas, ir bus kankinami dieną ir naktį per amžių amžius.'),
  (@b66, 20, 11, 'Ir aš mačiau didžiulį baltą sostą ir jame sėdintįjį, nuo kurio veido pabėgo žemė ir dangus; ir jiems nebuvo rasta vietos.'),
  (@b66, 20, 12, 'Ir mačiau mirusiuosius, mažus ir didelius, stovinčius prieš Dievą; ir buvo atvertos knygos; ir buvo atverta kita knyga, kuri yra gyvenimo knyga; ir mirusieji buvo teisiami iš to, kas surašyta knygose, pagal jų darbus.'),
  (@b66, 20, 13, 'Ir jūra atidavė mirusiuosius, esančius joje; ir mirtis bei pragaras atidavė mirusiuosius, esančius juose; ir jie buvo teisiami, kiekvienas pagal savo darbus.'),
  (@b66, 20, 14, 'Ir mirtis bei pragaras buvo įmesti į ugnies ežerą. Tai yra antroji mirtis.'),
  (@b66, 20, 15, 'Ir kas nebuvo rastas įrašytas gyvenimo knygoje, buvo įmestas į ugnies ežerą.'),
  (@b66, 21, 1, 'Ir mačiau naują dangų ir naują žemę; nes pirmasis dangus ir pirmoji žemė praėjo; ir nebebuvo jūros.'),
  (@b66, 21, 2, 'Ir aš, Jonas, mačiau šventąjį miestą, naująją Jeruzalę, nužengiančią iš dangaus nuo Dievo, paruoštą kaip nuotaką, papuoštą savo vyrui.'),
  (@b66, 21, 3, 'Ir girdėjau stiprų balsą iš dangaus, sakantį: „Štai Dievo padangtė yra su žmonėmis, ir jis gyvens su jais, ir jie bus jo tauta, ir pats Dievas bus su jais, ir bus jų Dievas.'),
  (@b66, 21, 4, 'Ir Dievas nuvalys visas ašaras nuo jų akių; ir nebebus mirties nei liūdesio, nei verksmo, ir nebebus skausmo, nes kas buvo pirmiau – praėjo.'),
  (@b66, 21, 5, 'Ir sėdintysis soste tarė: „Štai visa darau nauja“. Ir jis man tarė: „Rašyk; nes šie žodžiai yra tikri ir patikimi“.'),
  (@b66, 21, 6, 'Ir jis man tarė: „Atlikta. Aš esu Alfa ir Omega, pradžia ir pabaiga. Trokštančiam aš duosiu iš gyvenimo vandens šaltinio dovanai.'),
  (@b66, 21, 7, 'Kas nugali, tas viską paveldės; ir aš būsiu jo Dievas, ir jis bus mano sūnus.'),
  (@b66, 21, 8, 'Bet bailiai ir netikintys, ir pasibjaurėtini, ir žmogžudžiai, ir paleistuviai, ir burtininkai, ir stabmeldžiai, ir visi melagiai turės savo dalį ežere, kuris dega ugnimi ir siera; tai yra antroji mirtis“.'),
  (@b66, 21, 9, 'Ir pas mane atėjo vienas iš septynių angelų, turėjusių septynis butelius, pilnus septynių paskutinių rykščių, ir kalbėjo su manimi, sakydamas: „Ateik čia, aš tau parodysiu nuotaką, Avinėlio žmoną“.'),
  (@b66, 21, 10, 'Ir jis nunešė mane dvasioje į didelį ir aukštą kalną, ir man parodė tą didįjį miestą, šventąją Jeruzalę, nusileidžiančią iš dangaus nuo Dievo,'),
  (@b66, 21, 11, 'turinčią Dievo šlovę; ir jos šviesa buvo panaši į paties brangiausio akmens, tarsi jaspio akmens, skaidraus kaip krištolas;'),
  (@b66, 21, 12, 'ir turėjo didelę ir aukštą sieną, turėjo dvylika vartų, ir prie vartų dvylika angelų, ir ant jų užrašytus vardus, kurie yra dvylikos Izraelio vaikų genčių vardai:'),
  (@b66, 21, 13, 'rytuose treji vartai; šiaurėje treji vartai; pietuose treji vartai; ir vakaruose treji vartai.'),
  (@b66, 21, 14, 'Ir miesto siena turėjo dvylika pamatų, ir juose – dvylikos Avinėlio apaštalų vardai.'),
  (@b66, 21, 15, 'Ir tas, kuris su manimi kalbėjo, turėjo auksinę nendrę išmatuoti miestui ir jo vartams, ir jo sienai.'),
  (@b66, 21, 16, 'O miestas išsidėstęs kvadratu, ir ilgis yra tokio pat dydžio kaip ir plotis; ir jis išmatavo miestą nendre: dvylika tūkstančių furlongų. Jo ilgis ir plotis, ir aukštis yra vienodi.'),
  (@b66, 21, 17, 'Ir jis išmatavo jo sieną: šimtas keturiasdešimt keturios uolektys žmogaus matu, tai yra, angelo.'),
  (@b66, 21, 18, 'Ir jo sienos statinys buvo iš jaspio; o miestas buvo grynas auksas, panašus į skaidrų stiklą.'),
  (@b66, 21, 19, 'Ir miesto sienos pamatai buvo papuošti visokiais brangiaisiais akmenimis. Pirmasis pamatas buvo jaspis; antrasis – safyras; trečiasis – chalcedonas; ketvirtasis – smaragdas;'),
  (@b66, 21, 20, 'penktasis – sardoniksas; šeštasis – sardis; septintasis – chrizolitas; aštuntasis – berilas; devintasis – topazas; dešimtasis – chrizoprazas; vienuoliktasis – hiacintas; dvyliktasis – ametistas.'),
  (@b66, 21, 21, 'Ir dvylika vartų buvo dvylika perlų; kiekvieni vartai buvo iš vieno perlo, o miesto gatvė buvo grynas auksas, tarsi skaidrus stiklas.'),
  (@b66, 21, 22, 'Ir jame nemačiau šventyklos; nes Viešpats Visagalis Dievas ir Avinėlis yra jo šventykla.'),
  (@b66, 21, 23, 'Ir miestui nereikėjo nei saulės, nei mėnulio, kad šviestų jame; nes Dievo šlovė apšvietė jį, ir Avinėlis yra jo šviesa.'),
  (@b66, 21, 24, 'Ir išgelbėtųjų tautos vaikščios jo šviesoje; ir žemės karaliai atneša į jį savo šlovę ir garbę.'),
  (@b66, 21, 25, 'Ir jo vartai visiškai nebus užrakinami dieną, nes ten nebus nakties.'),
  (@b66, 21, 26, 'Ir jie atneš į jį tautų šlovę ir garbę.'),
  (@b66, 21, 27, 'Ir jokiu būdu į jį neįeis niekas, kas suteršia, nei kas daro bjaurastį ar melą, bet tik tie, kurie yra įrašyti Avinėlio gyvenimo knygoje.'),
  (@b66, 22, 1, 'Ir jis man parodė tyrą gyvenimo vandens upę, skaidrią kaip krištolas, ištekančią nuo Dievo ir Avinėlio sosto.'),
  (@b66, 22, 2, 'Jo gatvės viduryje ir abejose upės pusėse buvo gyvenimo medis, kuris nešė dvylika vaisių rūšių ir davė kas mėnesį savo vaisių; ir medžio lapai buvo tautų gydymui.'),
  (@b66, 22, 3, 'Ir nebebus prakeikimo; bet jame bus Dievo ir Avinėlio sostas; ir jo tarnai jam tarnaus;'),
  (@b66, 22, 4, 'ir jie matys jo veidą; ir jo vardas bus jų kaktose.'),
  (@b66, 22, 5, 'Ir ten nebus nakties; ir jiems nereikės žvakės nei saulės šviesos; nes Viešpats Dievas duoda jiems šviesą; ir jie karaliaus per amžių amžius.'),
  (@b66, 22, 6, 'Ir jis man tarė: „Šie pasakymai yra patikimi ir tikri; ir šventųjų pranašų Viešpats Dievas pasiuntė savo angelą parodyti savo tarnams tai, kas netrukus turi įvykti.'),
  (@b66, 22, 7, 'Štai aš greitai ateinu: palaimintas tas, kuris laikosi šios knygos pranašystės pasakymų“.'),
  (@b66, 22, 8, 'Ir aš, Jonas, tuos dalykus mačiau ir girdėjau. Ir išgirdęs ir pamatęs aš parpuoliau pagarbinti prie kojų angelo, kuris man šiuos dalykus parodė.'),
  (@b66, 22, 9, 'Tada jis man sako: „Žiūrėk, nedaryk to; nes esu bendratarnis tavo ir tavo brolių pranašų, ir tų, kurie laikosi šios knygos pasakymų; Dievą garbink“.'),
  (@b66, 22, 10, 'Ir jis man sako: „Neužantspauduok šios knygos pranašystės pasakymų; nes laikas yra čia pat.'),
  (@b66, 22, 11, 'Neteisusis toliau tebūna neteisus; ir nešvarusis toliau tebūna nešvarus; ir teisusis toliau tebūna teisus; ir šventasis toliau tebūna šventas.'),
  (@b66, 22, 12, 'Ir štai aš greitai ateinu; ir mano atlygis su manimi, kad duočiau kiekvienam pagal tai, koks bus jo darbas.'),
  (@b66, 22, 13, 'Aš esu Alfa ir Omega, pradžia ir pabaiga, pirmasis ir paskutinysis.'),
  (@b66, 22, 14, 'Palaiminti tie, kurie vykdo jo įsakymus, kad jie turėtų teisę į gyvenimo medį ir galėtų įeiti pro vartus į miestą.'),
  (@b66, 22, 15, 'Nes lauke yra šunys ir burtininkai, ir paleistuviai, ir žmogžudžiai, ir stabmeldžiai, ir visi, kurie mėgsta ir daro melą“.'),
  (@b66, 22, 16, '„Aš, Jėzus, pasiunčiau savo angelą, kad paliudytų jums šiuos dalykus bažnyčiose. Aš esu Dovydo šaknis ir palikuonis, šviesi ir rytinė žvaigždė“.'),
  (@b66, 22, 17, 'Ir Dvasia bei nuotaka sako: „Ateik“. Ir kas girdi, tesako: „Ateik“. Ir kas ištroškęs, teateina. Ir kas nori, teima dovanai gyvenimo vandens.'),
  (@b66, 22, 18, 'Nes aš liudiju kiekvienam, girdinčiam šios knygos pranašystės žodžius: „Jei kas prie šių dalykų pridės, tam Dievas pridės rykščių, surašytų šioje knygoje;'),
  (@b66, 22, 19, 'ir jei kas atims nuo šios pranašystės knygos žodžių, Dievas atims jo dalį iš gyvenimo knygos ir iš šventojo miesto, ir iš tų dalykų, kurie yra surašyti šioje knygoje“.'),
  (@b66, 22, 20, 'Kas šiuos dalykus liudija, sako: „Tikrai aš greitai ateinu“. Amen. Būtent taip, ateik, Viešpatie Jėzau!'),
  (@b66, 22, 21, 'Mūsų Viešpaties Jėzaus Kristaus malonė tebūna su jumis visais. Amen.');
